INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, then, we hold that the PCRA court’s grant of a new trial cannot be sustained on the present state of the record and findings.', 'general', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1466352/', '1466352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the jury’s determination that appellee deliberately killed the victim was supported by sufficient evidence, and that, when viewed in the light most favorable to the Commonwealth, and employing reasonable inferences, the evidence was sufficient to support the aggravating circumstance that the murder was committed as a consequence of a drug-sale-related rivalry.', 'general', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1466352/', '1466352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the defendant was convicted of sexually assaulting his four-year-old daughter, and, on review, this Court held that counsel was ineffective for failing to present the testimony of a number of available character witnesses.', 'ineffective_assistance', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1466352/', '1466352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the PCRA court had defaulted on its duty to assess the credibility of the recantation and its significance in light of the trial record, and we remanded the matter to the PCRA court for the limited purpose of making such a determination.', 'general', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1466352/', '1466352') ON CONFLICT DO NOTHING;
