INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Prior to 1979, we held that, if circumstantial evidence was used to prove aiding and abetting, the evidence had to pass the test of being consistent with the defendant’s guilt and inconsistent with any rational hypothesis of his innocence.', 'general', 'State of Iowa v. Dalevonte Davelle Hearn', 'https://www.courtlistener.com/opinion/4472439/', '4472439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that there was substantial evidence that Hearn aided and abetted the carjacking and thus cannot escape his conviction of felony eluding on the ground that he was not participating in an underlying felony.', 'general', 'State of Iowa v. Dalevonte Davelle Hearn', 'https://www.courtlistener.com/opinion/4472439/', '4472439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that when police officers responding to a contemporaneous crime report come upon the accused in close temporal and geographic proximity to the crime and give chase, the police officers are “pursuers” under Iowa Code section 702.', 'general', 'State of Iowa v. Dalevonte Davelle Hearn', 'https://www.courtlistener.com/opinion/4472439/', '4472439') ON CONFLICT DO NOTHING;
