INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we hold that the offenses of sexual assault in the second degree and robbery may constitute continuing offenses for purposes of criminal prosecution within the territorial jurisdiction of the state of West Virginia.', 'general', 'State v. Dennis', 'https://www.courtlistener.com/opinion/1412175/', '1412175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In consideration of the foregoing we conclude that the judge and jury share responsibility for the ultimate determination of territorial jurisdiction in a criminal case involving controverted jurisdictional facts.', 'general', 'State v. Dennis', 'https://www.courtlistener.com/opinion/1412175/', '1412175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we affirm the judgment of conviction for all crimes except sexual assault and robbery and we remand for a new trial on these latter charges.', 'general', 'State v. Dennis', 'https://www.courtlistener.com/opinion/1412175/', '1412175') ON CONFLICT DO NOTHING;
