INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that in each instance the circuit court, not the Court of Appeals, correctly resolved the issue whether the defendant was denied effective assistance.', 'general', 'People v. LeBlanc', 'https://www.courtlistener.com/opinion/849023/', '849023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Thus, “[w]hile defendant was unable to demonstrate that race was a bona fide issue in the case, we conclude that the failure to inquire into bias or prejudice based on occupation and race undermines the reliability of the verdict.', 'general', 'People v. LeBlanc', 'https://www.courtlistener.com/opinion/849023/', '849023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of the record on appeal, we conclude that the cumulative effect of counsel’s errors undermines the confidence in the reliability of the verdict and a new trial is warranted.', 'general', 'People v. LeBlanc', 'https://www.courtlistener.com/opinion/849023/', '849023') ON CONFLICT DO NOTHING;
