INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the aggravating circumstances present in this case, while serious, do not justify a greater-than-double durational departure from the presumptive sentence and therefore reduce appellant’s sentence to 96 months.', 'sentencing', 'State v. Spain', 'https://www.courtlistener.com/opinion/2228008/', '2228008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a 144-month sentence is disproportional to the severity of appellant’s conduct.', 'sentencing', 'State v. Spain', 'https://www.courtlistener.com/opinion/2228008/', '2228008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing this case and comparing the sentence imposed with sentences imposed in other cases, we conclude that the extent of the sentencing departure imposed here was not justified.', 'sentencing', 'State v. Spain', 'https://www.courtlistener.com/opinion/2228008/', '2228008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we conclude that imposition of a 144-month sentence in this matter would be inconsistent with the primary purpose of the sentencing guidelines, which is to ensure that sentences are “proportional to the severity of the offense of conviction and the extent of the offender’s criminal history.', 'sentencing', 'State v. Spain', 'https://www.courtlistener.com/opinion/2228008/', '2228008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987), this Court held that all questions regarding the sufficiency of indictments are determinable by reference to Rule 2.', 'general', 'Nguyen v. State', 'https://www.courtlistener.com/opinion/1770567/', '1770567') ON CONFLICT DO NOTHING;
