INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the district court did not abuse its discretion by denying Jonas a new trial on this issue.', 'general', 'State of Iowa v. Christopher Craig Thompson', 'https://www.courtlistener.com/opinion/4472202/', '4472202') ON CONFLICT DO NOTHING;
