INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under these circumstances, appellant has forfeited his complaint that the improper-relationship statute is facially unconstitutional, and he may not now litigate that issue in the instant post-conviction habeas proceeding.', 'habeas', 'Ex parte Beck', 'https://www.courtlistener.com/opinion/6241138/', '6241138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Karenev , this Court held that, in general, a facial constitutional challenge to a statute does not implicate an absolute requirement or prohibition that is exempt from ordinary *853preservation-of-error requirements, and, therefore, such a challenge may not be presented for the first time on direct appeal.', 'general', 'Ex parte Beck', 'https://www.courtlistener.com/opinion/6241138/', '6241138') ON CONFLICT DO NOTHING;
