INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals and remand this case to the circuit court for resentencing.', 'sentencing', 'People v. McGraw', 'https://www.courtlistener.com/opinion/836290/', '836290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals and remand the case to the circuit court for resentencing.', 'sentencing', 'People v. McGraw', 'https://www.courtlistener.com/opinion/836290/', '836290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Carter, we held that no reviewable error existed because defense counsel had “clearly expressed satisfaction with the trial court’s decision to refuse the jury’s request [to rehear testimony] and its subsequent instruction.', 'general', 'People v. McGraw', 'https://www.courtlistener.com/opinion/836290/', '836290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '712 NW2d 419 (2006), we held that in felony murder, a defendant’s “perpetration” of the predicate felony includes acts that occur outside the definitional elements but during “the unbroken chain of events surrounding that felony.', 'general', 'People v. McGraw', 'https://www.courtlistener.com/opinion/836290/', '836290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, as this Court held in Smith, an appellee’s failure to file a brief altogether does not constitute a confession of *141error, then it follows that an appellee’s filing of a brief that does not address a particular issue also is not a confession of error.', 'general', 'People v. McGraw', 'https://www.courtlistener.com/opinion/836290/', '836290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that the jury did not convict the defendant of abusing the complainant’s sister and that the abuse of the sister did not arise out of the same transaction as the abuse of the complainant, we concluded that zero points should have been assessed for OV 9.', 'general', 'People v. McGraw', 'https://www.courtlistener.com/opinion/836290/', '836290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '658 NW2d 184 (2003) (“[W]here the Legislature has not precluded it, we find that where the crimes involved constitute one continuum of conduct, as here, it is logical and reasonable to consider the entirety of defendant’s conduct in calculating the sentencing guideline range with respect to each offense.', 'sentencing', 'People v. McGraw', 'https://www.courtlistener.com/opinion/836290/', '836290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because the Court of Appeals *142reached the correct result, we affirm the Court of Appeals decision for the reasons stated herein.', 'general', 'People v. McGraw', 'https://www.courtlistener.com/opinion/836290/', '836290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the restriction is not
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that section 33.', 'general', 'State v. Abigail Marie Stubbs', 'https://www.courtlistener.com/opinion/4246993/', '4246993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute serves a significant governmental interest.', 'general', 'State v. Abigail Marie Stubbs', 'https://www.courtlistener.com/opinion/4246993/', '4246993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '07(a), we reverse
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the superficial similarity of the statutory language in California’s determinate scheme does not transform Michigan’s intermediate sanction cells into the relevant statutory máximums for Blakely purposes.', 'general', 'People v. Harper', 'https://www.courtlistener.com/opinion/842331/', '842331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because Michigan has a true indeterminate sentencing scheme, an intermediate sanction is not a maximum sentence that is governed by Blakely.', 'sentencing', 'People v. Harper', 'https://www.courtlistener.com/opinion/842331/', '842331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, even if an intermediate sanction were a statutoiy maximum for purposes oí Blakely and the sentencing courts in these cases violated Blakely, we conclude that any error was harmless.', 'sentencing', 'People v. Harper', 'https://www.courtlistener.com/opinion/842331/', '842331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in Bums, we conclude that if any Blakely error is found to have occurred, it would be harmless beyond a reasonable doubt.', 'general', 'People v. Harper', 'https://www.courtlistener.com/opinion/842331/', '842331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the defendants’ convictions and sentences.', 'sentencing', 'People v. Harper', 'https://www.courtlistener.com/opinion/842331/', '842331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Harper’s sentence.', 'sentencing', 'People v. Harper', 'https://www.courtlistener.com/opinion/842331/', '842331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Bums’s sentence.', 'sentencing', 'People v. Harper', 'https://www.courtlistener.com/opinion/842331/', '842331') ON CONFLICT DO NOTHING;
