INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was sufficient to support the indictment for conspiracy, bribery and official misconduct.', 'general', 'State v. Schenkolewski', 'https://www.courtlistener.com/opinion/7402652/', '7402652') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the State presented sufficient evidence to support an indictment against defendants for conspiracy, bribery and official misconduct.', 'general', 'State v. Schenkolewski', 'https://www.courtlistener.com/opinion/7402652/', '7402652') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the dismissal of the indictment based on the prosecutor’s failure to ensure the impartiality of the grand jurors.', 'dismissal', 'State v. Schenkolewski', 'https://www.courtlistener.com/opinion/7402652/', '7402652') ON CONFLICT DO NOTHING;
