INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the order granting Arthur’s Rule 35 motion.', 'general', 'State v. Arthur', 'https://www.courtlistener.com/opinion/874892/', '874892') ON CONFLICT DO NOTHING;
