INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the Court of Appeals finding no error in the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Strange', 'https://www.courtlistener.com/opinion/890558/', '890558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that unless we reverse, the suppression will have a critical impact on the outcome of the trial.', 'suppression', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that any statements made by Scott during the unwarned interrogation are inadmissible.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the facts presented here, we hold that the state has shown by a fair preponderance of the evidence that Scott validly waived his Miranda rights.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here we hold that the state established by a preponderance of the evidence that Scott''s confession was voluntarily given.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the suppression of the confession would significantly reduce the likelihood of a successful prosecution and, therefore, critical impact has been established.', 'suppression', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In one instance, we held that a juvenile''s waiver was involuntary.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that his waiver was involuntarily given because the juvenile was incapable of understanding or intelligently waiving his rights.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Scott knowingly and voluntarily waived his right to remain silent before he described his participation in a drive-by shooting for which he was subsequently charged.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only when the answer to this question is yes will we conclude that the statement was given involuntarily.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and trial court and remand for trial.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235433/', '1235433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that jury instructions that add requirements to what the statute sets out as necessary to prove the commission of a crime are erroneous;', 'jury_instruction', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the totality of circumstances, it is clear beyond a reasonable doubt the jury would have found Beamon guilty of fleeing or attempting to elude an officer absent the erroneous jury instruction.', 'jury_instruction', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that there was sufficient evidence to convict Beamon, and we affirm the decision of the court of appeals.', 'general', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 61, we conclude that harmless error analysis is appropriate where jury instructions include a requirement in addition to that set forth in a statute, such as occurred in Beamon''s case.', 'jury_instruction', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the instructions used in this case, we conclude that the instructions did not properly state the statutory requirements for fleeing or eluding under Wis.', 'general', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and therefore, we conclude that the instructions’ requirement of proof by two methods was erroneous.', 'general', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of all the testimony, we conclude that it is clear beyond a reasonable doubt that a rational jury, properly instructed on the statutory requirements of fleeing or eluding, would have found Beamon guilty.', 'general', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, as we shift our analysis to Beamon''s sufficiency of the evidence challenge, we conclude that the jury instructions cannot provide the proper standard for analysis.', 'jury_instruction', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the totality of circumstances, it is clear beyond a reasonable doubt the *588jury would have found Beamon guilty of fleeing or attempting to elude an officer absent the erroneous jury instruction.', 'jury_instruction', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our case law discussing the doctrines of waiver and forfeiture, we conclude that such failure to object is more properly labeled forfeiture than waiver.', 'general', 'State v. Courtney C. Beamon', 'https://www.courtlistener.com/opinion/873320/', '873320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the interpretation of “illegal sentence” under Rule 35 is limited to sentences that are illegal from the face of the record, i.', 'sentencing', 'State v. Clements', 'https://www.courtlistener.com/opinion/874871/', '874871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we hold that the district court lacked authority under Idaho Criminal Rule 35 to examine the underlying facts of Clements’s case before concluding that Clements’s sentence was illegal.', 'sentencing', 'State v. Clements', 'https://www.courtlistener.com/opinion/874871/', '874871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the district court lacked authority under Rule 35 to examine the underlying facts of Clements’s case.', 'general', 'State v. Clements', 'https://www.courtlistener.com/opinion/874871/', '874871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the district court’s order and remand.', 'general', 'State v. Clements', 'https://www.courtlistener.com/opinion/874871/', '874871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the district court’s order vacating Clements’s judgment of conviction and sentence for attempted second-degree murder with a firearm enhancement, and remand the matter to the district court to reinstate the judgment of conviction and sentence that was vacated.', 'sentencing', 'State v. Clements', 'https://www.courtlistener.com/opinion/874871/', '874871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the district court’s order vacating Clements’s judgment of conviction and sentence for attempted second-degree murder with a firearm enhancement and remand the matter to the district court to reinstate the judgment of conviction and sentence that was vacated.', 'sentencing', 'State v. Clements', 'https://www.courtlistener.com/opinion/874871/', '874871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a motion to correct sentence may only be used to correct sentencing errors that are clear from the face of the judgment imposing the sentence in light of the statutory authority.', 'sentencing', 'State v. Clements', 'https://www.courtlistener.com/opinion/874871/', '874871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that any person who takes a vehicle contrary to a provision of the Michigan Penal Code2 — including MCL 750.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Bronson Court’s “chain of permissive use” theory is inconsistent with the statutory language of the no-fault act.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*523Furthermore, in Bieszck v Avis Rent-a-Car System, Inc, this Court held that a rental contract forbidding anyone under age 25 from operating the rented vehicle conclusively rebutted the presumption that the 21-year-old driver was operating the vehicle with the owner’s express or implied consent.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 We conclude that Bronson erred by applying a theory developed in owner-liability caselaw to the context of MCL 500.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the Court of Appeals erred by affirming the circuit court’s grant of summary disposition to Spectrum Health because MCL 500.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*524In applying this principle of law to the facts of this case, we conclude that there is no factual dispute that Craig Sr.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the family-joyriding exception is not supported by the text of MCL 500.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Justice Levin’s plurality opinion in Priesman and its progeny — including Butterworth,95 Mester,96 Allen,97 and Roberts98 — did not apply the plain meaning of MCL 500.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '143330), we reverse the judgments of the Court of Appeals and remand these cases to their respective circuit courts for further proceedings consistent with this opinion.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '51 We reverse the lower court judgments and remand this case to the circuit court for further proceedings consistent with this opinion.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '61 Accordingly, we hold that genuine impossibility is a defense to the charge of felony nonsupport under *399MCL 750.', 'general', 'People of Michigan v. Selesa Arrosieur Likine', 'https://www.courtlistener.com/opinion/824277/', '824277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that to establish an impossibility defense for felony nonsupport, a defendant must show that he or she acted in good faith and made all reasonable efforts to comply with the family court order, but could not do so through no fault of his or her own.', 'general', 'People of Michigan v. Selesa Arrosieur Likine', 'https://www.courtlistener.com/opinion/824277/', '824277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that a defendant charged with felony nonsupport may, in exceptional circumstances, on making the requisite evidentiary showing, establish impossibility as a defense to a charge of felony nonsupport.', 'general', 'People of Michigan v. Selesa Arrosieur Likine', 'https://www.courtlistener.com/opinion/824277/', '824277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the circuit court did not abuse its discretion by refusing to allow Harris to withdraw his plea, and he is therefore not entitled to relief.', 'plea', 'People of Michigan v. Selesa Arrosieur Likine', 'https://www.courtlistener.com/opinion/824277/', '824277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that People v Adams correctly held that MCL 750.', 'general', 'People of Michigan v. Selesa Arrosieur Likine', 'https://www.courtlistener.com/opinion/824277/', '824277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Parks is not entitled to relief, we affirm the judgment of the Court of Appeals in that case.', 'general', 'People of Michigan v. Selesa Arrosieur Likine', 'https://www.courtlistener.com/opinion/824277/', '824277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, having concluded that Likine preserved this claim of constitutional error and that the prosecution has not shown that the error was harmless, we reverse her conviction and remand the case to the circuit court for further proceedings.', 'general', 'People of Michigan v. Selesa Arrosieur Likine', 'https://www.courtlistener.com/opinion/824277/', '824277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the judgment of the Court of Appeals in Parks.', 'general', 'People of Michigan v. Selesa Arrosieur Likine', 'https://www.courtlistener.com/opinion/824277/', '824277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”1 Here, we hold that because the circumstances described in OV 19 expressly include events occurring after the completion of the sentencing offense, scoring OV 19 necessarily is not limited to consideration of the sentencing offense.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/829414/', '829414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v McGraw, this Court held that “[o]ffense variables must be scored giving consideration to the sentencing offense alone, unless otherwise provided in the particular variable.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/829414/', '829414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McGraw, this Court held that “[o]ffense variables must be scored giving consideration to the sentencing offense alone, unless otherwise provided in the particular variable.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/829414/', '829414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we concluded that interference with the administration of justice “encompasse[d] more than just the actual judi*202cial process” and that the scoring of OV 19 was proper because the police “are an integral component in the administration of justice, regardless of whether they are operating directly pursuant to a court order.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/829414/', '829414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals in part and reinstate defendant’s sentence for manslaughter.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/829414/', '829414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we held that offense variables may be scored on the basis of conduct not related to the sentencing offense when an offense variable “specifically provide[s] otherwise.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/829414/', '829414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the majority correctly recites, in McGrow this Court held that “[o]ffense variables must be scored giving consideration to the sentencing offense alone, unless otherwise provided in the particular variable.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/829414/', '829414') ON CONFLICT DO NOTHING;
