INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held the matter in abeyance and remanded the case “to the sentencing court for a factual finding whether defendant was convicted of a sexual offense against an individual who is less than 18 years of age.', 'sentencing', 'People v. Althoff', 'https://www.courtlistener.com/opinion/1655007/', '1655007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the particular facts of a violation are to be considered in determining whether the violation “by its nature constitutes a sexual offense against an individual who is less than 18 years of age” under MCL 28.', 'general', 'People v. Althoff', 'https://www.courtlistener.com/opinion/1655007/', '1655007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that a sentencing court may consider all record evidence in determining if a defendant must register under SORA, as long as the defendant has the opportunity to challenge relevant factual
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Althoff', 'https://www.courtlistener.com/opinion/1655007/', '1655007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the challenged conduct did not constitute plain error because the prosecutor introduced the evidence on the basis of Lieutenant Hagler''s declared status as an expert witness in the area of street-gang investigation and practices.', 'general', 'People v. Gonzalez', 'https://www.courtlistener.com/opinion/1639096/', '1639096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not err in denying defendant Guerra''s motion to suppress.', 'suppression', 'People v. Gonzalez', 'https://www.courtlistener.com/opinion/1639096/', '1639096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Gonzalez', 'https://www.courtlistener.com/opinion/1639096/', '1639096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has failed to show that it has a clear legal right to temporary injunctive relief because it has not demonstrated a substantial likelihood of success on the merits.', 'general', 'Playpen South, Inc. v. City of Oakland Park', 'https://www.courtlistener.com/opinion/1842044/', '1842044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 We hold that the Arizona Constitution also provides for a right to refuse medical treatment.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the doctrine of informed consent—a doctrine borne of the common-law right to be free from nonconsensual physical invasions—permits an individual to refuse medical treatment.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that court-resolved disputes in cases of this nature must be resolved by clear and convincing evidence.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the medical treatment decisions made in this case were not decisions to commit suicide, neither the physicians, nurses, health care facility, guardian, guardian ad litem, nor any similarly situated individual or entity can be charged with manslaughter.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rasmussen’s right to refuse medical treatment still existed despite her incompetency and her failure to articulate her medical treatment desires prior to becoming incompetent.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Vermuele’s convictions and sentences.', 'sentencing', 'State v. Vermuele', 'https://www.courtlistener.com/opinion/1251084/', '1251084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err when it dismissed the false arrest, assault and battery, and negligence counts of the complaint on the basis that the police reports failed, under the terms of the statute, to give sufficient notice to the District that a claim might arise.', 'dismissal', 'Allen v. District of Columbia', 'https://www.courtlistener.com/opinion/1966980/', '1966980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the District received ample information “from which it could be reasonably anticipated that a claim .', 'general', 'Allen v. District of Columbia', 'https://www.courtlistener.com/opinion/1966980/', '1966980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'note 7, we held that in order for there to be proper notice “a police report must do more than merely report the happening of an event or accident;', 'general', 'Allen v. District of Columbia', 'https://www.courtlistener.com/opinion/1966980/', '1966980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the malicious prosecution count, we conclude that Allen’s letter satisfied the requirements of § 12-309, and, therefore, the District was afforded adequate notice of the lawsuit that was to be filed.', 'general', 'Allen v. District of Columbia', 'https://www.courtlistener.com/opinion/1966980/', '1966980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Allen’s notice in writing to the District, dated less than two months after his acquittal on the criminal offense, was not only timely under the terms of § 12-309 but it was also sufficient to meet the “cause” and “circumstances” requirements of the statute.', 'general', 'Allen v. District of Columbia', 'https://www.courtlistener.com/opinion/1966980/', '1966980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse the order granting summary judgment on the claim of malicious prosecution.', 'general', 'Allen v. District of Columbia', 'https://www.courtlistener.com/opinion/1966980/', '1966980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand with directions to reinstate the malicious prosecution count.', 'general', 'Allen v. District of Columbia', 'https://www.courtlistener.com/opinion/1966980/', '1966980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court erred in refusing to give the lesser included offense instructions on the crime of manslaughter in this case.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in refusing to give the lesser included offense instructions on the ground that Eckert afforded the defendant the right to waive them and the State would be bound by such a waiver.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with this approach, and we hold that the language of Wyoming Rule 31(c), which is identical to FEDERAL Rule 31(c), implies and requires that both prosecution and defense have an equal right to a lesser included offense instruction.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the determination of what offenses are “necessarily included in the offense charged” is primarily a question of law.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, applying these standards, the trial court erred in denying the State’s request for a lesser included offense instruction on voluntary manslaughter.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the requested instruction should have been given because all five of the Chapman elements were present and satisfied.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Using this standard as stated, we held that no evidence at trial justified any instruction for lesser included offenses.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the teachings of these cases, we conclude that the failure to give a lesser included offense instruction which was supported by the evidence must constitute error implicating due process guarantees.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that evidence of the DNA match and the accompanying statistical probability was properly admitted.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, where mental health professionals specifically testified that the victim was abused at the hands of the defendant, we held that “[s]uch testimony cannot be perceived to address an area in which expert testimony provides assistance to the jury in resolving a factual issue.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that none of the delay in bringing appellant to trial may be included in the speedy trial calculation.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “at some level, the statistical probability could be perceived as an opinion by the expert that the accused is guilty” and that the “better practice in Wyoming should be not to refer to the statistical probability of duplication when introducing DNA test results.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our determination in Rivera parallels a most recent decision of the United States Supreme Court.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the superior court erred in barring the state from presenting evidence to prove McLaughlin’s previous conviction of a felony.', 'general', 'State v. McLaughlin', 'https://www.courtlistener.com/opinion/1145398/', '1145398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Smith was not prejudiced as a result of his trial counsel’s failure to object to evidence of the pretrial identification procedures and the victim’s in-court identification at trial.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1657755/', '1657755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Smith was not prejudiced as a result of his counsel’s failure to challenge the information or request a bill of particulars for specificity and preserve such issues for appeal.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1657755/', '1657755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Smith was not prejudiced by his counsel’s failure to object to improper questioning by the State at trial because the district court is presumed to have considered only legally admissible evidence in deciding the case.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1657755/', '1657755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that police are not required to advise a person in custody that she may consult with an attorney before administering FSTs.', 'general', 'Ackerman v. State', 'https://www.courtlistener.com/opinion/2057323/', '2057323') ON CONFLICT DO NOTHING;
