INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the BAC test result was relatively unimportant evidence in light of the other evidence presented at trial and that there .', 'general', 'Ackerman v. State', 'https://www.courtlistener.com/opinion/2057323/', '2057323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ackerman v. State', 'https://www.courtlistener.com/opinion/2057323/', '2057323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the juvenile court did not abuse its discretion by admitting the officer’s testimony, and the evidence is sufficient to prove A.', 'general', 'A.J.R. v. State', 'https://www.courtlistener.com/opinion/7167588/', '7167588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on a plain reading of the statute, we hold that a wound or injury must be of the variety contemplated by the statute before it qualifies as mutilation.', 'general', 'A.J.R. v. State', 'https://www.courtlistener.com/opinion/7167588/', '7167588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although decided prior to the enactment of statutory definitions for "mutilate” and "torture,” this court held that "the act of shooting [an animal] is not enough alone to establish cruelty to an animal by either torture or mutilation.', 'general', 'A.J.R. v. State', 'https://www.courtlistener.com/opinion/7167588/', '7167588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’s actions did not constitute mutilation or torture of an animal, we reverse his adjudications for cruelty to an animal.', 'general', 'A.J.R. v. State', 'https://www.courtlistener.com/opinion/7167588/', '7167588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part and reverse in part.', 'general', 'A.J.R. v. State', 'https://www.courtlistener.com/opinion/7167588/', '7167588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the overruling of a plea in abatement challenging the sufficiency of the evidence adduced at a preliminary hearing was not a final order, because the defendant could still make a motion to dismiss at the close of the State’s case and raise on appeal the issue whether there was sufficient evidence to convict him.', 'dismissal', 'State v. Loyd', 'https://www.courtlistener.com/opinion/1657394/', '1657394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 331 (1997), in which this court held that the denial of a motion to discharge based upon speedy trial grounds is a final order, as an order affecting a substantial right made in a special proceeding, and that failure to perfect an appeal within 30 days of the overruling of such a motion to discharge results in a waiver of that issue.', 'general', 'State v. Loyd', 'https://www.courtlistener.com/opinion/1657394/', '1657394') ON CONFLICT DO NOTHING;
