INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '20 For the reasons set forth in *417Boyne, we hold that the statute cannot be contrived to encompass a condition of probation, incarceration, which is in fact the antithesis of the essential purposes of probation.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that Spra-gue’s admissions of guilt were not the product of any improper promises on the part of the investigating officers.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Roman we found that conditioning the appellant’s probation on his consent to war-rantless searches under the direction of the parole officer was “reasonably related to the rehabilitation of the offender and the protection of the public” and was not “unduly restrictive of liberty.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 107, 110 (Alaska 1977), as support for its view, in Brown we found that AS 12.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm the judgment, finding no error in the trial court’s ruling that Sprague’s statements did not constitute involuntary admissions or confessions.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 439 (1991), this Court held that a two-part foundation must be established before a witness’s out-of-court statement may be offered into evidence pursuant to 11
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the judge improperly commented upon the evidence.', 'general', 'Feleke v. State', 'https://www.courtlistener.com/opinion/1547905/', '1547905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not abuse his discretion, and that the conviction does not suffer from a constitutional infirmity.', 'general', 'Feleke v. State', 'https://www.courtlistener.com/opinion/1547905/', '1547905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Feleke v. State', 'https://www.courtlistener.com/opinion/1547905/', '1547905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” From this, we conclude that defendant killed both of the victims to eliminate them as witnesses to the robbery.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Judge Scholl’s findings at the sentencing hearing were based on relevant evidence presented at defendant’s trial, as well as at the sentencing hearing.', 'sentencing', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We find that Judge Scholl, for purposes of aggravation, properly considered the presentence report as to all counts except for the murder counts and, as A.', 'sentencing', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the victims were helpless and the defendant relished the murders.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the facts in this case, we find that the record supports the trial court’s finding that the murders were committed in an especially heinous or depraved manner.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*173Based upon our review of these decisions, we find that the imposition of the death penalty in this case is proportional to the sentences imposed in similar cases.', 'sentencing', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Walton, we found that the defendant relished the murder because he said that he had “never seen a man pee in his pants before.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gillies, we found that the extent and duration of defendant’s participation in the crime minimized the impact of his youth as a mitigating factor.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that legally inconsistent guilty verdicts require reversal and, where the remand for a new trial is without express instructions, the defendant may be retried on all charges.', 'general', 'State v. Moore', 'https://www.courtlistener.com/opinion/1350094/', '1350094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence establishes beyond a reasonable doubt that the defendant caused his wife’s death with intent and premeditation.', 'general', 'State v. Moore', 'https://www.courtlistener.com/opinion/1350094/', '1350094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set out below, we affirm the conviction.', 'general', 'State v. Moore', 'https://www.courtlistener.com/opinion/1350094/', '1350094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction of murder in the first degree.', 'general', 'State v. Moore', 'https://www.courtlistener.com/opinion/1350094/', '1350094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Burnett''s probable *1174 possession of child pornography and the likelihood that it would be found on the computer and diskettes in his bedroom, we conclude that the warrant application failed.', 'general', 'Burnett v. State', 'https://www.courtlistener.com/opinion/1780866/', '1780866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his convictions for lewd or lascivious conduct, but because the affidavit in support of the search warrant was fatally defective, we reverse the convictions for possession of child pornography and remand for resentencing.', 'sentencing', 'Burnett v. State', 'https://www.courtlistener.com/opinion/1780866/', '1780866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this appeal we reverse the finding that the detectives had probable cause to search for and to seize Mr.', 'probable_cause', 'Burnett v. State', 'https://www.courtlistener.com/opinion/1780866/', '1780866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse the convictions on 136 counts of possession of child pornography that flowed from the illegal seizure of those items.', 'general', 'Burnett v. State', 'https://www.courtlistener.com/opinion/1780866/', '1780866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion within the context of Rule 403.', 'general', 'Sandy v. State', 'https://www.courtlistener.com/opinion/1350121/', '1350121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '•We affirm.', 'general', 'Sandy v. State', 'https://www.courtlistener.com/opinion/1350121/', '1350121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that no prejudicial error occurred in this regard.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the admission of Rivers’ testimony was error, but the error was cured when testimony of like import was thereafter amplified on cross-examination by defense counsel.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the admission of Rivers’ statement that Richard Adams showed Rivers the alleged murder weapon, we conclude that the court did not err.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'that the Rivers testimony as to the gun was hearsay, we conclude that this evidence was properly admitted for corroborative purposes.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was “substantial similarity” between the testimony of Rivers and Richard Adams as it related to the gun, given that Richard Adams admitted on cross-examination that Rivers had in fact observed the gun.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was ample evidence from which a jury could reasonably infer the satisfaction of each of the statutory elements enunciated above.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the evidence was sufficient for the jury to find defendant guilty of acting in concert in the felony murder of the victim, and the trial court properly denied defendant’s motion to dismiss.', 'dismissal', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judgments were improperly entered.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse defendant’s conviction of and vacate defendant’s sentence on the felonious larceny pursuant to a breaking or entering charge.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/1269859/', '1269859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed above, we reverse
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 937 (1980), this Court held that an instruction such as this one may be given to the jury only when the State has tried to impeach its own witness, and then only to explain why the State is permitted to do so.', 'general', 'State v. Jaramillo', 'https://www.courtlistener.com/opinion/1521218/', '1521218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that error occurred.', 'general', 'State v. Simonson', 'https://www.courtlistener.com/opinion/1154459/', '1154459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this is one such situation.', 'general', 'State v. Simonson', 'https://www.courtlistener.com/opinion/1154459/', '1154459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we hold that Simonson’s conviction must be reversed and the case remanded for a new trial.', 'general', 'State v. Simonson', 'https://www.courtlistener.com/opinion/1154459/', '1154459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Simuel', 'https://www.courtlistener.com/opinion/1351600/', '1351600') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse and remand for sentencing consistent with our holding in this case.', 'sentencing', 'State v. Simuel', 'https://www.courtlistener.com/opinion/1351600/', '1351600') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we concluded that the sentencing judge should have had the benefit of a current psychological evaluation, stating in part:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1031, 1033 (Alaska 1975), we concluded that the sentencing court’s stated reasons satisfied AS 12.', 'sentencing', 'Andrews v. State', 'https://www.courtlistener.com/opinion/1251200/', '1251200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this testimony was permissible because it helped the jury understand one aspect of the evidence — the victim’s request to her assailant — and be*530cause the expert’s explanation did not constitute testimony with respect to the veracity of the victim.', 'general', 'Barnes v. State', 'https://www.courtlistener.com/opinion/1154921/', '1154921') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Using our often repeated plain error analysis, we find that what was said was rationally based upon the officer’s perception of the witness, helpful to a clear understanding of her testimony, violated no rule of law, and was properly admitted by the court.', 'general', 'Barnes v. State', 'https://www.courtlistener.com/opinion/1154921/', '1154921') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Barnes v. State', 'https://www.courtlistener.com/opinion/1154921/', '1154921') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that any error in the district court''s failure to offer the jury Hudson''s proposed instructions on the lesser included misdemeanor offenses was harmless pursuant to the acquittal first requirement under I.', 'general', 'State v. Hudson', 'https://www.courtlistener.com/opinion/1122971/', '1122971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered the facts and circumstances, we hold that the district court did not abuse its discretion in denying Hudson''s motion for continuance.', 'general', 'State v. Hudson', 'https://www.courtlistener.com/opinion/1122971/', '1122971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if the district court erred in failing to instruct the jury on the lesser included misdemeanor offenses, such error was harmless because of the acquittal first requirement under I.', 'general', 'State v. Hudson', 'https://www.courtlistener.com/opinion/1122971/', '1122971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Hudson', 'https://www.courtlistener.com/opinion/1122971/', '1122971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '262 (1907), this court held that the defendant’s attempt to induce a witness to leave the state and refrain from testifying at the defendant’s trial was admissible in “ ‘determining the guilt or innocence of the defendant.', 'general', 'State v. Clancy', 'https://www.courtlistener.com/opinion/1658334/', '1658334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Clancy’s threatening telephone call to Jane DeVaney was important evidence to the State’s case.', 'general', 'State v. Clancy', 'https://www.courtlistener.com/opinion/1658334/', '1658334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, regarding every element of the offense charged, there was evidence with probative value to submit to the jury the question whether Clancy was guilty of the crime charged.', 'general', 'State v. Clancy', 'https://www.courtlistener.com/opinion/1658334/', '1658334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the nature of the charge in the present case and Clancy’s history of criminal acts, including impermissible liberties with people and the property of others, we find that the district court did not abuse its discretion in the sentence imposed on Clancy.', 'sentencing', 'State v. Clancy', 'https://www.courtlistener.com/opinion/1658334/', '1658334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the exclusion of plaintiff’s evidence was not an abuse of discretion by the trial court.', 'general', 'McDonnell v. Guilford County Tradewind Airlines, Inc.', 'https://www.courtlistener.com/opinion/1155948/', '1155948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we affirm the judgment of the trial court.', 'general', 'McDonnell v. Guilford County Tradewind Airlines, Inc.', 'https://www.courtlistener.com/opinion/1155948/', '1155948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 13 Because the trial court’s finding is supported by substantial evidence and Pima County’s authorities are inapposite, we conclude that the trial court’s finding that Gilbert had proven she owned the seized funds was not clearly erroneous.', 'general', 'In re United States Currency In Amount of $26,980.00', 'https://www.courtlistener.com/opinion/6603659/', '6603659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any interest actually earned on seized funds that are not subject to forfeiture and are returned to a claimant becomes part of the res and must also be returned to the claimant.', 'general', 'In re United States Currency In Amount of $26,980.00', 'https://www.courtlistener.com/opinion/6603659/', '6603659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, however, we concluded that the record owner of real property had no real interest in the property for purposes of establishing the “innocent owner” exception to forfeiture because his father had selected the house and made the down payment and the record owner had never made mortgage or tax payments on the property, insured it, maintained it, or lived in it.', 'general', 'In re United States Currency In Amount of $26,980.00', 'https://www.courtlistener.com/opinion/6603659/', '6603659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse the trial court’s award of ten percent prejudgment interest.', 'general', 'In re United States Currency In Amount of $26,980.00', 'https://www.courtlistener.com/opinion/6603659/', '6603659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the portion of the judgment ordering the seized funds returned but vacate the portion of the judgment awarding Gilbert ten percent prejudgment interest because A.', 'general', 'In re United States Currency In Amount of $26,980.00', 'https://www.courtlistener.com/opinion/6603659/', '6603659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 32 We affirm the trial court’s judgment requiring return of the seized funds.', 'general', 'In re United States Currency In Amount of $26,980.00', 'https://www.courtlistener.com/opinion/6603659/', '6603659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the doctrine of transferred intent may be used to convict a defendant of ABIK when the defendant kills the intended victim and also injures an unintended victim.', 'general', 'State v. Fennell', 'https://www.courtlistener.com/opinion/1420203/', '1420203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the doctrine of transferred intent may be used to convict a defendant of ABIK when the defendant kills the intended victim and also injures an unintended victim.', 'general', 'State v. Fennell', 'https://www.courtlistener.com/opinion/1420203/', '1420203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that our- criminal laws, unlike those of some other jurisdictions, make it necessary to impose the doctrine of transferred intent in this case.', 'general', 'State v. Fennell', 'https://www.courtlistener.com/opinion/1420203/', '1420203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Fennell', 'https://www.courtlistener.com/opinion/1420203/', '1420203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the Court of Appeals’ ruling that it was improper to submit the offense of malicious damage to personal property to the jury because
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the orders of the trial court.', 'general', 'McCuen v. State', 'https://www.courtlistener.com/opinion/1780739/', '1780739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court in denying relief on this point.', 'general', 'McCuen v. State', 'https://www.courtlistener.com/opinion/1780739/', '1780739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Lane did not breach any duty of care that she owed to Cilley, and affirm the judgment.', 'general', 'Estate of Cilley v. Lane', 'https://www.courtlistener.com/opinion/2056496/', '2056496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Novak, we held that a determination of whether the evidence supports a conviction on a lesser offense is a completely separate inquiry.', 'general', 'People v. Baldwin', 'https://www.courtlistener.com/opinion/2056541/', '2056541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that courts must first examine whether the charging instrument identifies a lesser-included offense.', 'general', 'People v. Baldwin', 'https://www.courtlistener.com/opinion/2056541/', '2056541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither of these counts set forth a broad foundation or main outline of aggravated unlawful restraint.', 'general', 'People v. Baldwin', 'https://www.courtlistener.com/opinion/2056541/', '2056541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the circuit court erred in finding defendant guilty of the uncharged crime of aggravated unlawful restraint.', 'general', 'People v. Baldwin', 'https://www.courtlistener.com/opinion/2056541/', '2056541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Jones case to the case sub judice, we find that the evidence shows that the statement made was properly admitted.', 'general', 'Burt v. State', 'https://www.courtlistener.com/opinion/1658853/', '1658853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when the state seeks to terminate a juvenile from probation unsuccessfully based on an alleged violation, termination proceedings under Ariz.', 'general', 'In re Thomas D.', 'https://www.courtlistener.com/opinion/6604082/', '6604082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*32¶ 12 We hold that the court abused its discretion because it applied the procedures of Ariz.', 'general', 'In re Thomas D.', 'https://www.courtlistener.com/opinion/6604082/', '6604082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 19 We therefore hold that when the state alleges a violation of a condition of probation as the basis for terminating a juvenile from probation, the probationer is entitled to the due process protections that Rule 32 affords.', 'general', 'In re Thomas D.', 'https://www.courtlistener.com/opinion/6604082/', '6604082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 9 Based on Williams, and absent a clear expression of legislative intent that driving on a suspended license be a strict liability offense, we hold that the State must prove beyond a reasonable doubt that a defendant knew or should have known of his license suspension, revocation, cancellation, or refusal in prosecutions under A.', 'general', 'State v. Yazzie', 'https://www.courtlistener.com/opinion/6604178/', '6604178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 10 Because the court did not instruct jurors regarding an element of the offense that the State was required to prove *618beyond a reasonable doubt, we reverse Yazzie’s conviction and sentence.', 'sentencing', 'State v. Yazzie', 'https://www.courtlistener.com/opinion/6604178/', '6604178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when physical discipline of a child is at issue in a custody proceeding, the court must determine expressly whether the discipline rises to the level of domestic violence.', 'general', 'Christopher K. v. Markaa S.', 'https://www.courtlistener.com/opinion/6604197/', '6604197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To safeguard the identities of the minor children, it is ordered that the clerk of this court shall amend the caption of this appeal as shown above.', 'general', 'Christopher K. v. Markaa S.', 'https://www.courtlistener.com/opinion/6604197/', '6604197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we hold that the retroactive application of the lifetime registration requirement and quarterly in-person verification procedures of SORNA of 1999 to offenders originally sentenced subject to SORA of 1991 and SORNA of 1995, without, at a minimum, affording those offenders any opportunity to ever be relieved of the duty as was permitted under those laws, is punitive.', 'sentencing', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that if SORNA of 1999 registration was made a part of a criminal sentence, the exclusive means by which the State could seek to modify the offender’s sex offender classification under SORNA of 1999 was through Rule 35 of the Maine Rules of Criminal Procedure.', 'sentencing', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute imposes an ex post facto punishment as to offenders sentenced in the years before the effective date of SORNA of 1999 for whom registration was a required part of their sentence and who were subsequently made subject to the more burdensome requirements of SORNA of 1999 after its effective date of September 18, 1999.', 'sentencing', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 25] Thus, we conclude that the ex post facto clauses of the Maine and United States Constitutions are interpreted similarly and are coextensive, and a statute violates the prohibition against ex post facto laws if it: (1) punishes as criminal an act that was not criminal when done, (2) makes more burdensome the punishment for a crime after it has been committed, or (3) deprives the defendant of a defense that was available according to law at the time the act was committed.', 'general', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Maine’s statutory scheme is indistinguishable in this respect and, for the reasons articulated by the Supreme Court in Smith, we conclude that Internet posting pursuant to SORNA of 1999 is not punitive in purpose or effect.', 'general', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Haskell we concluded that it is not and that this factor supports SORNA being viewed as non-punitive.', 'general', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these facts and circumstances, we find that the State did not present sufficient evidence at trial to prove that Ferge was predisposed to commit the crime of patronizing a prostitute, and that he established the defense of entrapment as a matter of law.', 'general', 'Ferge v. State', 'https://www.courtlistener.com/opinion/2056757/', '2056757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Ferge v. State', 'https://www.courtlistener.com/opinion/2056757/', '2056757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the sentence imposed by the trial court is valid and must be affirmed.', 'sentencing', 'State v. Bieniek', 'https://www.courtlistener.com/opinion/2056765/', '2056765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In respect of the issue raised by the panel about whether the court recognized that it need not accept the sentence in the negotiated plea agreement, we find that there was no basis whatsoever for questioning the trial court’s understanding of its authority.', 'sentencing', 'State v. Bieniek', 'https://www.courtlistener.com/opinion/2056765/', '2056765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division and reinstate the sentence imposed by the trial court.', 'sentencing', 'State v. Bieniek', 'https://www.courtlistener.com/opinion/2056765/', '2056765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that any error was harmless beyond a reasonable doubt because there is no indication in the record that Mitchell’s defense was stymied by the trial court’s denial of the motion to suppress and the statements where he admitted to being present at the scene were never admitted into evidence.', 'suppression', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2056933/', '2056933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that appellant did not make a specific showing of prejudice to satisfy the "affecting substantial rights” prong of the plain-error rule.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2056933/', '2056933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the strength of the evidence of appellant’s intent to kill that the government presented at trial, we conclude that there is not a reasonable probability that the jury convicted appellant on an impermissible negligence theory.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2056933/', '2056933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence presented at trial establishing the necessary elements for assault with intent to kill while armed and second-degree murder, we conclude that there was sufficient evidence to establish that both appellants committed assault with a dangerous weapon while armed.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2056933/', '2056933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions of appellants Mitchell and Stroud in all respects except that we reverse and remand with directions to vacate both appellants’ convictions for AAWA and direct the trial court to re-sentence appellants accordingly.', 'sentencing', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2056933/', '2056933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2056933/', '2056933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” While noting that at trial the defendant unsuccessfully sought to have State’s Exhibit 9 redacted to eliminate reference to the forgery shown by Exhibit 7, we conclude that the trial court’s refusal was harmless under the circumstances.', 'general', 'Vanway v. State', 'https://www.courtlistener.com/opinion/2057473/', '2057473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the prior forgery represented by State’s Exhibit 4 was not excludable from evidence, we find that the cumulative effect of informing the jury of the additional prior forgery resulted in relatively minimal additional prejudice, which, in light of other evidence showing the defendant’s guilt of the charged offense, does not justify a reversal of his conviction.', 'general', 'Vanway v. State', 'https://www.courtlistener.com/opinion/2057473/', '2057473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the facts of this case, we find that the opportunities for the witness to view the defendant provided an independent basis, rendering her in-court identification admissible.', 'general', 'Vanway v. State', 'https://www.courtlistener.com/opinion/2057473/', '2057473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Vanway v. State', 'https://www.courtlistener.com/opinion/2057473/', '2057473') ON CONFLICT DO NOTHING;
