INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the term ''present'' from being rendered meaningless, we conclude that ''present'' under Section 32.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, when the government employs a licensing scheme to regulate a profession or an activity that affects the public welfare, administrative revocation or suspension of that license can legitimately serve to deter conduct and still remain “remedial” for double jeopardy purposes so long as the revocation or suspension is based on conduct that bears a direct relation to the government’s regulatory goals or to the proper administration and enforcement of the regulatory scheme.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained in more detail below, we conclude that when the legislature employs a licensing scheme to regulate a profession or an activity affecting the public health or safety, a statute that authorizes a regulatory body to revoke these licenses is “remedial” for double jeopardy purposes even though the law serves to deter licensees from engaging in conduct that is inconsistent with their duties as licensees or that is inconsistent with the public welfare.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the administrative revocation of the defendants’ driver’s licenses is premised on remedial goals.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as the Supreme Court declined to unreflectively apply the *758Halper test in Austin and Kurth Ranch, we conclude that Halper ⅛ statements about deterrence do not govern the cases before us.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that administrative license revocation continues to be a “remedial” sanction, not a “punitive” sanction, for purposes of the federal double jeopardy clause.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In one exhortatoiy paragraph that cites no pertinent legal authority, the defendants urge us to declare that administrative revocation of driver''s licenses constitutes "punishment" for purposes of the double jeopardy clause of the Alaska Constitution (Article I, Section 9), even if we conclude that administrative revocation is remedial for purposes of the Federal Constitution.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we reinstate the prosecutions that were dismissed and we affirm the district court’s refusal to dismiss the prosecution in file number A-5739.', 'dismissal', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under the Double Jeopardy Clause a defendant who already has been punished in a criminal prosecution may not be subjected to an additional civil sanction to the extent that the second sanction may not fairly be characterized as remedial, but only as a deterrent or [as] retribution.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the criminal penalty described in Sarasota County Ordinance 87-41 conflicts with state law and is superseded by the noncriminal state sanction.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1106064/', '1106064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agree with the trial court that the criminal sanction contained in the county''s ordinance has been superseded by a noncriminal state statute, we reverse the suppression order because the ordinance was presumptively valid at the time of the arrest.', 'suppression', 'State v. Smith', 'https://www.courtlistener.com/opinion/1106064/', '1106064') ON CONFLICT DO NOTHING;
