INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Kirby', 'https://www.courtlistener.com/opinion/1422398/', '1422398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the abuse prevention order was not unconstitutional and was not issued in violation of defendant’s due process rights.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1969450/', '1969450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court correctly charged on the mens rea element of the crime of violation of the abuse prevention order.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1969450/', '1969450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the abuse prevention order being challenged is no longer in effect, and the relief requested would not help defendant in his challenge to his criminal conviction, we conclude that this controversy is moot.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1969450/', '1969450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both the conviction and the refusal to reopen the order.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1969450/', '1969450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” On this record, we hold that the district court’s decision was not clearly erroneous.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/2058868/', '2058868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not fail to exercise its discretion or rely solely on the federal poverty guide*504lines.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/2058868/', '2058868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, on this record, Jones did not give a knowing, intelligent, and voluntary waiver of his right to counsel.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/2058868/', '2058868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the district court did not abuse its discretion in not appointing advisory counsel here.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/2058868/', '2058868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/2058868/', '2058868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regardless of the basis for its decision, therefore, we hold that the trial court did not err in overruling Fitzgerald’s motion to suppress
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in its totality, we hold that there is no merit in Fitzgerald’s objection and that the court did not abuse its discretion in seating Griffin.', 'general', 'Fitzgerald v. Commonwealth', 'https://www.courtlistener.com/opinion/1363213/', '1363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, the expert did not attempt to express an opinion as to the veracity of any witness, and we hold that the trial court did not err in admitting his testimony.', 'general', 'Fitzgerald v. Commonwealth', 'https://www.courtlistener.com/opinion/1363213/', '1363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is no merit in Fitzgerald’s argument.', 'general', 'Fitzgerald v. Commonwealth', 'https://www.courtlistener.com/opinion/1363213/', '1363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the hearsay objection, we hold that any error in admitting portions of the report containing inadmissible opinions,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the imposition of sentences against Fitzgerald for the rape and robbery underlying his capital murder conviction did not violate the Double Jeopardy Clause.', 'sentencing', 'Fitzgerald v. Commonwealth', 'https://www.courtlistener.com/opinion/1363213/', '1363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the sentence of death is not excessive or disproportionate to sentences generally imposed by Virginia juries in crimes of a similar but less horrifying nature.', 'sentencing', 'Fitzgerald v. Commonwealth', 'https://www.courtlistener.com/opinion/1363213/', '1363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review, we conclude that Hackney and Mann showed an earnest desire and willingness to decide the case, both as to guilt and as to punishment, on the basis of the evidence presented, that they understood that the Commonwealth had the burden of proof, and that Fitzgerald was presumed to be innocent and was not required to testify or to present any evidence.', 'general', 'Fitzgerald v. Commonwealth', 'https://www.courtlistener.com/opinion/1363213/', '1363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'City of Rock Hill v. Suchenski', 'https://www.courtlistener.com/opinion/1279155/', '1279155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we held that no specific jury instruction was required.', 'jury_instruction', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2058346/', '2058346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that “in every case when a defendant is charged with kidnapping in conjunction with an underlying crime, a specific instruction requiring the jury to find that the movement and/or restraint is independent of and not incidental to the underlying crime is mandatory.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2058346/', '2058346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'under different circumstances, this Court held that a specific instruction requiring the jury to find proof of more interference than
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record clearly supports the State’s assertion that more than one factor aroused suspicion on the part of the police, resulting in Coleman’s detention, and that Coleman was not arbitrarily or discriminatorily
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the police in this case had a reasonable basis for their suspicion that the individual they observed may have been involved in the prior criminal activity and, hence, the stop of Coleman was “justified in its inception.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2058346/', '2058346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Coleman’s detention was minimally intrusive and “reasonably related in scope to the circumstances which justified the interference.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2058346/', '2058346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that “the record .', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2058346/', '2058346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that “the use of race may be legitimate when it is one among several factors suggestive of criminality.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2058346/', '2058346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that when the police observed a man, fitting generally, though not exactly, the description of the suspect, on foot, within one-half of a mile of the crime scene, they were justified in stopping and detaining him.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2058346/', '2058346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in State v.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1097548/', '1097548') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we hold that the trial court’s denial of defendant’s motion to sever was not an abuse of discretion, and that defendant was not significantly prejudiced by the joinder of the March 20 counts with the homicide counts in the guilt phase of the proceedings.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as defense counsel did not request a diminished capacity charge, and the evidence offered did not significantly relate defendant’s mental disorder to the state of mind described by defendant’s psychiatric expert, we hold that it was not plain error for the trial court to have failed, sua sponte, to instruct the jury on diminished capacity and aggravated manslaughter on the theory that defendant’s mental condition afforded the jury a rational basis for convicting defendant of the less...', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To recapitulate, we hold that it was not plain error for the trial court to have omitted to charge the jury on aggravated manslaughter — whether in connection with the proofs offered by defendant bearing on imperfect self-defense, diminished capacity, or state of mind.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although we hold that defendant was not entitled to a charge on aggravated manslaughter, we are also satisfied that its submission to the jury would have had no effect on the verdict.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ramseur, supra, where we held that an instruction that the jury “should decide the case on the evidence without any bias, prejudice or sympathy * * * ” did not violate a defendant’s constitutional rights, 106 N.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although expressly declining to rule on the admissibility of the proposed testimony in respects other than relevancy, we held that the proffered expert testimony “generally satisfies broad standards of relevancy” and hence was admissible to establish a mitigating factor in the penalty phase.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the Gerald charge would have been appropriate, we consider whether its omission was clearly capable of affecting the verdict.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we concluded that the evidence in the record was susceptible to either finding, we reversed defendant’s capital murder conviction and remanded the matter for a new trial.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We also adopted in Ramseur a narrowing construction of c(4)(c) in order to satisfy constitutional standards, and we concluded that the defendant’s state of mind was the critical element:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his convictions for murder and the related offenses.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury in this case did not specify which of the foregoing offenses '' (capital murder or non-capital murder) defendant was convicted of, and because it is possible, on this record, that the jury could have determined that the defendant had the purpose or knowledge to cause only serious bodily injury but not death, we conclude that the judgment of conviction .', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that from this time forward a Neil inquiry is required when an objection is raised that a peremptory challenge is being used in a racially discriminatory manner.', 'general', 'State v. Johans', 'https://www.courtlistener.com/opinion/1095978/', '1095978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the proper remedy in all cases where the trial court errs in failing to hold a Neil inquiry is to reverse and remand for a new trial.', 'general', 'State v. Johans', 'https://www.courtlistener.com/opinion/1095978/', '1095978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that even under the Neil "strong likelihood" standard the trial court erred in failing to conduct a Neil inquiry.', 'general', 'State v. Johans', 'https://www.courtlistener.com/opinion/1095978/', '1095978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that by knowingly driving under these circumstances, the Defendant operated his vehicle in a reckless (i.', 'general', 'Lewek v. State', 'https://www.courtlistener.com/opinion/1101016/', '1101016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the eyewitness''s testimony was not an expert opinion, but was a lay opinion, which is generally admissible as to the rate of speed of the Defendant''s car.', 'general', 'Lewek v. State', 'https://www.courtlistener.com/opinion/1101016/', '1101016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the evidence of the victim''s pregnancy was irrelevant because it neither proves nor disproves any material issue in the case, and as such, it should have been excluded.', 'general', 'Lewek v. State', 'https://www.courtlistener.com/opinion/1101016/', '1101016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we conclude that the State presented a prima facie case of vehicular homicide sufficient to overcome the Defendant''s motions for judgment of acquittal.', 'general', 'Lewek v. State', 'https://www.courtlistener.com/opinion/1101016/', '1101016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As our opinion states, we concluded that under the circumstances of this case, the suspension of the Defendant''s driver''s license was irrelevant to prove whether he knowingly drove under circumstances likely to cause death or great bodily harm to others.', 'general', 'Lewek v. State', 'https://www.courtlistener.com/opinion/1101016/', '1101016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we reverse the Defendant''s convictions on two counts of vehicular homicide and remand the case for a new trial, finding that the Defendant''s due process rights were violated under the terms enunciated in Coney v.', 'general', 'Lewek v. State', 'https://www.courtlistener.com/opinion/1101016/', '1101016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that we need only address appellant''s contention that the trial court abused its discretion in declining to give a requested instruction on the defense of necessity.', 'general', 'Bozeman v. State', 'https://www.courtlistener.com/opinion/1102278/', '1102278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to that issue, we reverse and remand for a new trial.', 'general', 'Bozeman v. State', 'https://www.courtlistener.com/opinion/1102278/', '1102278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ward v. State', 'https://www.courtlistener.com/opinion/1104069/', '1104069') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our discussion above, we hold that prior to the filing of a prospective judicial proceeding, a pai*ty to a dispute is absolutely privileged to publish defamatory matter about a third person who is not a party to the dispute only when (1) the prospective judicial action is contemplated in good faith and is under serious consideration;', 'general', 'Collins v. Red Roof Inns, Inc.', 'https://www.courtlistener.com/opinion/1421839/', '1421839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an absolute privilege applies to defamatory statements uttered prior to the commencement of a judicial action, even when the subject of the defamatory comments is a third person, but only within the specific
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse her order reinstating Wilson, however, and remand this matter to the Board of Nursing for consideration whether his license should be revoked on the conduct issue standing alone.', 'general', 'Miss. State Bd. of Nursing v. Wilson', 'https://www.courtlistener.com/opinion/1113754/', '1113754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the chancellor as to the addiction issue.', 'general', 'Miss. State Bd. of Nursing v. Wilson', 'https://www.courtlistener.com/opinion/1113754/', '1113754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Roles’s proposed instruction adds nothing essential to the instructions already given, we hold that the court did not err by refusing to give that instruction.', 'general', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the presumption that the language of the applicable statute utilized in jury instructions is ordinarily the best suited, we hold that the rape instruction adequately presents the elements of that charge.', 'jury_instruction', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the instructions given did not constitute fundamental error, but that they adequately presented the issues and law before the jury so that it could acquit or convict based on how it decided the facts.', 'general', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Roles has not shown that he received ineffective assistance of counsel based on this claim.', 'ineffective_assistance', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Roles has not shown that the lack of an objection to the jury instructions as a whole by his trial counsel constituted deficient representation.', 'jury_instruction', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Roles has not proven this claim of ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Roles has failed to prove both prongs of his ineffective assistance of counsel claim.', 'ineffective_assistance', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the instructions individually and as a whole, we conclude that the instructions are clear and exhibit no reversible error.', 'general', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence was properly admitted and that defense counsel’s want of objection was neither deficient nor prejudicial.', 'general', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Roles’s trial counsel was adequate in questioning him.', 'general', 'State v. Roles', 'https://www.courtlistener.com/opinion/1182143/', '1182143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we hold that the argument of the prosecutor, although error, did not constitute plain error warranting the Court of Appeals to overlook the failure of the defense counsel to preserve the point by timely objection;', 'general', 'United States v. Young', 'https://www.courtlistener.com/opinion/111353/', '111353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that any potential harm from this remark was mitigated by the jury''s understanding that the prosecutor was countering defense counsel''s repeated attacks on the *18 prosecution''s integrity and defense counsel''s argument that the evidence established no such crime.', 'general', 'United States v. Young', 'https://www.courtlistener.com/opinion/111353/', '111353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the context of the prosecutor''s remarks and defense counsel''s broadside attack, however, we conclude that the jury was not influenced to stray from its responsibility to be fair and unbiased.', 'general', 'United States v. Young', 'https://www.courtlistener.com/opinion/111353/', '111353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The concerns underlying our reactions against improper prosecutorial arguments to the jury are implicated here, but not to the extent that we conclude that the jury''s deliberations were compromised.', 'general', 'United States v. Young', 'https://www.courtlistener.com/opinion/111353/', '111353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, in an action alleging unlawful discharge in violation of HRS § 378-2, the time for filing an administrative complaint begins to run on the date that the employee is actually discharged, that is, on the date that his or her employment terminates.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that if Ross prevails on his marital discrimination claim (count I) following remand, he is entitled to appropriate equitable relief, including backpay, as provided in HRS § 378 — 5(f), but he cannot recover any compensatory damages or punitive damages on that claim.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court properly granted summary judgment in favor of Stouffer on count II of Ross’s amended complaint.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court properly entered summary judgment in favor of Stouffer on Ross’s negligent infliction of emotional distress claim.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Ross cannot recover punitive damages for tortious breach of contract and that the circuit court properly dismissed count V of Ross’s amended complaint.', 'dismissal', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As noted above, because Ross has not assigned the dismissal of count VI as a point of error on appeal and has not addressed the claim in his briefs, we hold that he has waived any argument that count VI was improperly dismissed.', 'dismissal', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'resolution of certain civil matters[,]” HAR 2(A) (1991), we hold that Stouffer’s motion for partial summary judgment, which sought dismissal of six of Ross’s seven claims, did not violate HAR 7(F).', 'dismissal', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Ross has not assigned the dismissal of count VI as a point of error on appeal and has completely failed to mention that claim in either his opening or reply briefs, we hold that he has waived any argument that count VI was improperly dismissed.', 'dismissal', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it removes any doubt about when the filing period begins, it has the beneficent effect of avoiding the protracted and expensive litigation over the precise date and adequacy of an employer’s notice of termination that would inevitably result if we concluded that the date of notice triggered the filing period.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Stouffer was not entitled to summary judgment on count I on the ground that Ross’s DLIR complaint was not timely filed.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1073 (1988), where we held that the tolling provisions of HRS § 657-13 applied to toll the two year statute of limitations set forth in HRS § 294-36 for bringing a suit for *473no-fault benefits.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, given the limited conditions under which the Supreme Court has allowed on-reservation jurisdiction over member Indians, we find that the appellant has not established extraordinary circumstances with which to overcome “the right of reservation Indians to make their own laws and be ruled by them.', 'general', 'State v. Stone', 'https://www.courtlistener.com/opinion/1251928/', '1251928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Stone', 'https://www.courtlistener.com/opinion/1251928/', '1251928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in denying Page a continuance to consider the presen-tence report but hold that any error was harmless under the circumstances.', 'general', 'Page v. State', 'https://www.courtlistener.com/opinion/1159170/', '1159170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the record will not support consecutive sentences of ninety-nine and twenty years for this defendant and, therefore, vacate the sentence and remand for entry of a judgment that will provide that the sentences run concurrently.', 'sentencing', 'Page v. State', 'https://www.courtlistener.com/opinion/1159170/', '1159170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction.', 'general', 'Page v. State', 'https://www.courtlistener.com/opinion/1159170/', '1159170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '282, we held that the legislature by enactment of the 1927 Highway Code containing a provision making failure to stop in case of accident a misdemeanor had impliedly repealed the former statutory felony of leaving the scene of an accident.', 'general', 'State v. Morf', 'https://www.courtlistener.com/opinion/1122402/', '1122402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the state met its burden and decide such contact was harmless.', 'general', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/1123145/', '1123145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the district court’s findings of fact, we conclude that Wilson’s statements to Mealor during the drive to Grangeville were voluntarily given.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/1123556/', '1123556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon reviewing the record, we conclude that the district court did not abuse its discretion in reaching this conclusion.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/1123556/', '1123556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/1123556/', '1123556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, applying the plain and ordinary meaning of the word “possession,” the evidence here was sufficient to prove beyond a reasonable doubt that defendant knowingly distributed harmful material to a minor.', 'general', 'People v. Ward', 'https://www.courtlistener.com/opinion/2058950/', '2058950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons discussed above, we affirm the judgment of the appellate court affirming defendant’s conviction for distributing harmful material to a minor.', 'general', 'People v. Ward', 'https://www.courtlistener.com/opinion/2058950/', '2058950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a complaint for disorderly conduct was fatally defective because the charge only contained allegations that the defendant
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the complaint “by any fair construction” was “constitutionally insufficient and therefore fatally defective” because we found no way to construe the charge as alleging either actual or threatened
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding the indictment sufficient under these standards, we affirm.', 'general', 'State v. Motta', 'https://www.courtlistener.com/opinion/1159211/', '1159211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that Mata adequately raised the issue of Morgan’s possible bias.', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant was entitled to discovery of the IAD file because it contained evidence of prior bad acts of the alleged victim that would be potentially admissible under Hawaii Rules of Evidence (HRE) Rule 404(b).', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the other hand, we held that the defendant was not entitled to discovery of the psychologist’s testing materials because the materials were “neither relevant nor admissible,” and we “fail[ed] to discern what discoverable evidence could have been obtained” therefrom.', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that it was “error for the trial court, whatever its reasoning may have been, to have refused to give [the defendant’s] requested [accomplice witness] instruction either in the form as requested or in such modified form as may have been deemed more suitable to the court.', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the facts required to be determined “must be established by proof beyond a reasonable doubt and subject to the ordinary rules of evidence.', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the trial court did not abuse its discretion when it refused to give Pahio’s requested instruction because “[t]he defense counsel’s opening statement to the jury, his cross-examination of the prosecution witnesses and the general instruction given by the trial judge adequately directed the jury’s attention to the identification evidence and made defendant’s requested instruction unnecessary.', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our evaluation of the circumstances surrounding Kobayashi’s identification, particularly the fact that Okumura was the only person in the courtroom wearing a prison uniform and shackles, we conclude that the identification procedure was suggestive and that the circuit court erred in ruling otherwise.', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, considering the evidence in the light most favorable to the prosecution, we conclude that the circuit court did not err in denying Okumura’s motion for judgment of acquittal.', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we affirm Okumura’s convictions on the burglary charges but remand to the circuit court for clarification of the record with respect to its decision to impose extended terms of imprisonment.', 'general', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we affirm Mata’s conviction and sentence on the conspiracy charge.', 'sentencing', 'State v. Okumura', 'https://www.courtlistener.com/opinion/1123575/', '1123575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the trial court abused its discretion when it admitted Patrolman Dye’s deposition into evidence as such a ruling violated Appellant’s right to confront the witness, we hold that the error was harmless given that the deposition testimony did not compromise the outcome of the trial.', 'general', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Appellant’s defense counsel did not perform deficiently and that, therefore, Appellant was not prejudiced by the manner in which his trial attorney conducted his case.', 'general', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that, in order for a decision not to call an expert to be considered as being evidence that counsel’s performance was deficient, the defendant must show that such expert testimony was available and necessary.', 'general', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that failure to file a suppression motion did not constitute ineffective assistance of counsel
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State introduced sufficient evidence to support the allegation that Appellant committed aggravated vehicular homicide by either driving while he was intoxicated or driving in a reckless manner.', 'general', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining Appellant’s tape-recorded statements in their entirety, we conclude that Appellant voluntarily gave his statements.', 'general', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was not necessary for the trial court to attach any findings as the information which Appellant disagreed with did not have any impact on his sentence.', 'sentencing', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Appellant’s proportionality assertion lacks merit.', 'general', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such evidence was sufficient to permit the reasonable inference to be drawn that Appellant’s conduct was the proximate cause of the victim’s death.', 'general', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bloomquist v. State', 'https://www.courtlistener.com/opinion/1130164/', '1130164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Alex’ claim that he has twice been placed in jeopardy for the same offense is not well founded.', 'general', 'Alex v. State', 'https://www.courtlistener.com/opinion/1185405/', '1185405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that AS 11.', 'general', 'Alex v. State', 'https://www.courtlistener.com/opinion/1185405/', '1185405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that an indigent has a right to be represented by counsel at a probation revocation proceeding.', 'general', 'Alex v. State', 'https://www.courtlistener.com/opinion/1185405/', '1185405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the weight of authority, as reviewed by the court in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the challenged instructions were sufficient under the requirements of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In line with uniform authorities, we conclude that a good time forfeiture proceeding which does not increase the term of the original sentence, is an administrative proceeding at which jeopardy does not attach.', 'sentencing', 'Alex v. State', 'https://www.courtlistener.com/opinion/1185405/', '1185405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that under this terminology it was possible to be guilty of the offense when “there was an entire lack of any conscious deprivation of property or
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that “[i]f one fails to return an automobile out of neglect, without any intention to deprive the owner of his property or to convert property to his own use, or of doing wrong to the owner, he is made guilty of a felony although he may have acted unwittingly or inadvertently or negligently.', 'general', 'Alex v. State', 'https://www.courtlistener.com/opinion/1185405/', '1185405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), in which we held that, in the context of presumptive sentencing, a person has not been convicted of a felony until he has been sentenced for that felony.', 'sentencing', 'Larson v. State', 'https://www.courtlistener.com/opinion/1132218/', '1132218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that a finding of deliberate cruelty required either evidence of torture or gratuitous violence.', 'general', 'Larson v. State', 'https://www.courtlistener.com/opinion/1132218/', '1132218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Larson should not have been treated as a third felony offender and that the record does not support a sentence of more than forty years’ imprisonment.', 'sentencing', 'Larson v. State', 'https://www.courtlistener.com/opinion/1132218/', '1132218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that a person who receives a suspended imposition of sentence has been convicted of a felony for purposes of subsequent recidivist proceedings under the presumptive sentencing statutes, at least where the defendant’s record has not subsequently been expunged.', 'sentencing', 'Larson v. State', 'https://www.courtlistener.com/opinion/1132218/', '1132218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Larson appealed and we reversed the trial court’s decision in an unpublished opinion.', 'general', 'Larson v. State', 'https://www.courtlistener.com/opinion/1132218/', '1132218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Larson v. State', 'https://www.courtlistener.com/opinion/1132218/', '1132218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects we affirm the judgment of the superior court.', 'general', 'Larson v. State', 'https://www.courtlistener.com/opinion/1132218/', '1132218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a conviction that has been set aside pursuant to AS 12.', 'general', 'Larson v. State', 'https://www.courtlistener.com/opinion/1132218/', '1132218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Misdemeanor Criminal Rules'' sentencing guidelines do not so infringe upon the right to a jury trial.', 'sentencing', 'State v. Missamore', 'https://www.courtlistener.com/opinion/1131433/', '1131433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that fundamental rights are not implicated in this case.', 'general', 'State v. Missamore', 'https://www.courtlistener.com/opinion/1131433/', '1131433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the dual charging system employed in misdemeanor cases is not a violation of equal protection.', 'general', 'State v. Missamore', 'https://www.courtlistener.com/opinion/1131433/', '1131433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s ruling that the jury should not have been instructed on mistake of fact as a defense.', 'general', 'State v. Missamore', 'https://www.courtlistener.com/opinion/1131433/', '1131433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Garvin v. State', 'https://www.courtlistener.com/opinion/1279701/', '1279701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the denial of post-conviction relief and conclude trial counsel was not ineffective because Section 24-13-410(0 requires a mandatory consecutive sentence when a pre-trial detainee escapes.', 'sentencing', 'Garvin v. State', 'https://www.courtlistener.com/opinion/1279701/', '1279701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Sobieck', 'https://www.courtlistener.com/opinion/1856651/', '1856651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the orders on appeal and remand for further proceedings.', 'general', 'State v. Sobieck', 'https://www.courtlistener.com/opinion/1856651/', '1856651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Sobieck', 'https://www.courtlistener.com/opinion/1856651/', '1856651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no due process violation occurred in incorporating the statement of Mehring’s sister or the three letters from parents of uncharged victims into the presentence report.', 'sentencing', 'Mehring v. State', 'https://www.courtlistener.com/opinion/1145395/', '1145395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Mehring v. State', 'https://www.courtlistener.com/opinion/1145395/', '1145395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and remand for the limited purpose noted in this opinion.', 'general', 'Mehring v. State', 'https://www.courtlistener.com/opinion/1145395/', '1145395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that nothing in the setting of petitioner’s January 10, 2001 bail review hearing can be said to have coerced him into making his inculpatory statement.', 'general', 'State v. Kirton', 'https://www.courtlistener.com/opinion/1156843/', '1156843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, instructing:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, determining:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Kirton', 'https://www.courtlistener.com/opinion/1156843/', '1156843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1155486/', '1155486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court should have granted the motion to suppress evidence obtained in a search and seizure that exceeded the scope of defendant’s consent and was otherwise unsupported by probable cause.', 'suppression', 'State v. Swanson', 'https://www.courtlistener.com/opinion/1155739/', '1155739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the evidence, including a tape recording that Officer Rush made of his conversation with defendant prior to the search, we conclude that the trial court’s determination that defendant voluntarily consented to the search was not clearly erroneous.', 'general', 'State v. Swanson', 'https://www.courtlistener.com/opinion/1155739/', '1155739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the search exceeded the scope of the consent and was not backed by probable cause, we did not address whether defendant’s consent was invalid because, as he argues, the officers exceeded the scope of the traffic stop by keeping him for an inordinate length of time.', 'probable_cause', 'State v. Swanson', 'https://www.courtlistener.com/opinion/1155739/', '1155739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'State v. Kiper', 'https://www.courtlistener.com/opinion/1160212/', '1160212') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that, on appeal, the issue whether the trial court erred in denying a Rule 40 petition without a hearing based on no showing of a colorable claim is reviewed
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Dan has failed to show that the trial court’s findings with respect to trial counsel’s alleged intoxication to be clearly erroneous, we hold that the trial court was “right” in concluding that Dan failed to state a colorable claim based upon trial counsel’s alleged intoxication.', 'general', 'Dan v. State', 'https://www.courtlistener.com/opinion/1158966/', '1158966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we hold that the trial court was “right” in concluding that Dan’s claim of ineffective assistance of appellate counsel “fails to state a colorable claim by failing to even suggest a meritorious basis upon which counsel could have filed a Motion to Reconsider[J”
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the evidence, other than the photographs, clearly supports the jury’s verdict in this case.', 'general', 'Dan v. State', 'https://www.courtlistener.com/opinion/1158966/', '1158966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court was “right” in concluding that the “newly discovered evidence[] fails to present a colorable claim[.', 'general', 'Dan v. State', 'https://www.courtlistener.com/opinion/1158966/', '1158966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the trial court was “right” in denying Dan’s Rule 40 petition without an evidentiary hearing.', 'general', 'Dan v. State', 'https://www.courtlistener.com/opinion/1158966/', '1158966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Dan v. State', 'https://www.courtlistener.com/opinion/1158966/', '1158966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As previously noted, we affirmed Dan’s conviction in December 1991.', 'general', 'Dan v. State', 'https://www.courtlistener.com/opinion/1158966/', '1158966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm the circuit court’s orders denying Dan’s Rule 40 petition and his request for court-appointed counsel.', 'general', 'Dan v. State', 'https://www.courtlistener.com/opinion/1158966/', '1158966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred when it instructed the jury with respect to the issue of causation and when it excluded the evidence of the use of a controlled substance by Stegena.', 'general', 'Buckles v. State', 'https://www.courtlistener.com/opinion/1162767/', '1162767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'case, we hold that both - Instruction Nos.', 'general', 'Buckles v. State', 'https://www.courtlistener.com/opinion/1162767/', '1162767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court violated clear and unequivocal rules of law when it failed to inform the jury it could consider Stegena’s negligence for its bearing upon Buckles’ conduct and upon
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this instance, we conclude that the exclusion of this evidence was an abuse of the trial court’s discretion.', 'general', 'Buckles v. State', 'https://www.courtlistener.com/opinion/1162767/', '1162767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the ruling of the trial court that admitted the result of Buckles’ blood alcohol test into evidence.', 'general', 'Buckles v. State', 'https://www.courtlistener.com/opinion/1162767/', '1162767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1163223/', '1163223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that any error connected with the magistrate’s decision to deny Amerson’s motion to dismiss essentially became moot upon the jury’s verdict finding Amerson guilty beyond a reasonable doubt.', 'dismissal', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err.', 'general', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Amerson has failed to establish error by the district court with respect to the instructions given on the statute of limitation question.', 'general', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After due consideration, we conclude that we need not resolve the standard of proof question, nor whether the dismissal motion should have been granted by the magistrate.', 'dismissal', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the record, we conclude that Amer-son received a fair trial and was found guilty upon sufficient evidence to sustain the verdict.', 'general', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find it unnecessary to address these arguments, however, because we conclude that even if the admission of the DNA evidence was in error, the error was harmless.', 'general', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'to Amerson’s case, we conclude that beyond a reasonable doubt there was no reasonable probability that any error in the admission of the DNA evidence contributed to Amerson’s conviction of the crimes charged.', 'general', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we conclude that the district court abused its discretion by arriving at an unreasonably harsh sentencing structure for Amerson’s crimes.', 'sentencing', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the record in this case, including the circumstances of the criminal acts committed by Amerson, the fact that all three charges arose from a single incident of criminal behavior, Amerson’s character, age and background and the effect of the crimes upon the victim, we conclude that concurrent service of the two twenty-five year sentences imposed by the district court for the rape and for the forcible penetration would sufficiently protect the public interest.', 'sentencing', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments of conviction.', 'general', 'State v. Amerson', 'https://www.courtlistener.com/opinion/1163308/', '1163308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court’s alternative findings of physical cruelty or gratuitous violence cannot stand.', 'general', 'State v. Soto-Fong', 'https://www.courtlistener.com/opinion/1191763/', '1191763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, pursuant to our independent review, we hold that defendant’s age is of some mitigating weight.', 'general', 'State v. Soto-Fong', 'https://www.courtlistener.com/opinion/1191763/', '1191763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “[a]bsent evidence to the contrary [this court will assume that] the trial judge in a capital case is capable of focusing on the relevant sentencing factors and setting aside the irrelevant, inflammatory, and emotional factors.', 'sentencing', 'State v. Soto-Fong', 'https://www.courtlistener.com/opinion/1191763/', '1191763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that although Jackson’s age, sixteen years and ten months at the time of the crime, was a mitigating factor, it was not sufficiently mitigating so as to call for leniency in that case.', 'general', 'State v. Soto-Fong', 'https://www.courtlistener.com/opinion/1191763/', '1191763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 874 (1983), this court held that the trial court did not abuse its discretion by allowing the state to bring out on cross-examination that defendant’s brother, who testified on defendant’s behalf at trial, had refused to honor a state subpoena.', 'general', 'State v. Soto-Fong', 'https://www.courtlistener.com/opinion/1191763/', '1191763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held a cruelty finding to be inappropriate because “the fatal wounds appear to have been delivered at vital parts of the bodies of the victims, and death ensued swiftly.', 'general', 'State v. Soto-Fong', 'https://www.courtlistener.com/opinion/1191763/', '1191763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where the defendant shot two victims several times, this court held “that the evidence [was] inconclusive as to whether the victims suffered in such a way as to support a finding that the crime was committed in a cruel manner.', 'general', 'State v. Soto-Fong', 'https://www.courtlistener.com/opinion/1191763/', '1191763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the murders were heinous and depraved because they were senseless murders committed against helpless victims and motivated solely by a desire to eliminate any witnesses to the robbery.', 'general', 'State v. Soto-Fong', 'https://www.courtlistener.com/opinion/1191763/', '1191763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that witness elimination was “[t]he only reasonably ascertainable motive for the murders----”
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this court held that the murder was senseless and committed against a helpless victim, the factors were not enough
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it is impossible to preserve the constitutionality of the Tampa ordinance without effectively rewriting it, and we decline to "legislate" in that fashion.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1806993/', '1806993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it does not.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1806993/', '1806993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions, but remand for resentencing because defendant’s sentence was improperly enhanced by conviction of two crimes committed on the same occasion.', 'sentencing', 'State v. Bedoni', 'https://www.courtlistener.com/opinion/1167600/', '1167600') ON CONFLICT DO NOTHING;
