INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the circumstances involved in Hooper’s offense were neither particularly aggravated nor mitigated, we held that a substantial sentence of imprisonment was necessary to avoid depreciating the seriousness of the offense and to express community condemnation.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1168255/', '1168255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On these grounds, although concluding that a sentence of ten years was excessive, we held that a sentence of up to ten years with four years suspended would be justified.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1168255/', '1168255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence is too lenient and disapprove it.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1168255/', '1168255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '055(d), we conclude that community work cannot properly be relied on to replace jail time altogether when the circumstances surrounding an offender’s conviction for a class B felony, and the consequent need to emphasize community condemnation, would require the imposition of a nonprobationary term.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1168255/', '1168255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, absent significant mitigating circumstances, the seriousness of the offense required imposition of a sentence involving a substantial period of incarceration.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1168255/', '1168255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that an unsuspended term of at least eighteen months to serve should have been imposed.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1168255/', '1168255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the state’s argument has merit.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1168255/', '1168255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not commit fundamental error when it gave the instruction on second degree murder.', 'general', 'State v. Neal', 'https://www.courtlistener.com/opinion/1173197/', '1173197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of conviction and the sentence.', 'sentencing', 'State v. Neal', 'https://www.courtlistener.com/opinion/1173197/', '1173197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After an independent review of the record, we conclude that the state’s concession of error is well-founded.', 'general', 'Minano v. State', 'https://www.courtlistener.com/opinion/1173317/', '1173317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court erred in refusing to give the lesser-included offense instruction on joyriding.', 'general', 'Minano v. State', 'https://www.courtlistener.com/opinion/1173317/', '1173317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that on retrial the jury should be instructed on the lesser-included offense of theft.', 'general', 'Minano v. State', 'https://www.courtlistener.com/opinion/1173317/', '1173317') ON CONFLICT DO NOTHING;
