INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm the judgment of conviction for the crime of eluding a peace officer.', 'general', 'State v. James Leroy Skunkcap', 'https://www.courtlistener.com/opinion/3133321/', '3133321') ON CONFLICT DO NOTHING;
