INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm Defendant’s conviction for misdemeanor assault.', 'general', 'State v. James Leroy Skunkcap', 'https://www.courtlistener.com/opinion/3133321/', '3133321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Defendant’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments of the district court.', 'general', 'State v. James Leroy Skunkcap', 'https://www.courtlistener.com/opinion/3133321/', '3133321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction, but modify the sentences that were imposed so that appellant’s incarceration on count three runs concurrently with count two and not consecutively.', 'sentencing', 'State v. Drapeau', 'https://www.courtlistener.com/opinion/1175667/', '1175667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we hold that HRS § 708-830(6)(a) describes with reasonable clarity the acts that it proscribes, provides fixed standards for adjudging guilt, and gives persons of ordinary intelligence a reasonable opportunity to know what conduct is prohibited so that they may choose between lawful and unlawful conduct.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Gaylord having failed to meet his burden of plainly, clearly, manifestly, and unmistakably showing unconstitutionality beyond a reasonable doubt, we hold that HRS § 708-830(6)(a) is not unconstitutionally vague.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 and 4 of this opinion, we hold that HRS § 708-830(6)(a) is not unconstitutionally overbroad.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the sentencing court''s restitution order failed to comply with HRS § 706-605(1)(d) and was illegally imposed.', 'sentencing', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2]  After full and thorough consideration, and based on a review of the entire record before us, we hold that Gaylord''s remaining points of error on appeal are without merit.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ordered that the defendant be given credit for time served while awaiting trial on these charges.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Gaylord''s amended judgment of conviction, vacate his amended sentence, and remand the matter to the circuit court for resentencing.', 'sentencing', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Gaylord''s amended judgment of conviction, vacate his amended sentence, and remand the matter to the circuit court for resentencing consistent with this opinion.', 'sentencing', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Conner v. State', 'https://www.courtlistener.com/opinion/1177043/', '1177043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a sentence of eight years with five suspended is not greater than the presumptive sentence of four years for purposes of applying the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Tazruk’s sentence does not violate the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the nature of the offense, we find that Judge Hodges was not clearly mistaken in imposing the sentence of eight years with five years suspended.', 'sentencing', 'Tazruk v. State', 'https://www.courtlistener.com/opinion/1177761/', '1177761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Tazruk v. State', 'https://www.courtlistener.com/opinion/1177761/', '1177761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that self-defense and provocation instructions are not available in response to a charge of felony-murder where the predicate felony is the delivery of a controlled substance.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that, as a matter of law, second-degree murder, voluntary manslaughter, and involuntary manslaughter are not lesser included offenses of felony-murder.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that involuntary manslaughter is not a lesser included offense of felony-murder.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the court committed no prejudicial error.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Necessarily, we find that the circuit court properly denied Wade’s request for such instructions during the proceedings below.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that both second-degree murder and voluntary manslaughter are not lesser included offenses of felony-murder because they each require an element that is not necessary for a conviction of felony-murder:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, where the violent conflict arose from a disputed drug transaction, and where Wade fired at the command of Stradwick, the drug dealer, we find that the jury could conclude beyond a reasonable doubt that the delivery of a controlled substance and the homicide were parts of one continuous transaction.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this liberal standard, we find that most of the evidence Wade complains of was relevant, and the trial court did not abuse its discretion in admitting that evidence.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this evidence was not relevant to any fact of consequence to this case, and was admitted in error.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not abuse its discretion by ruling against the defendant with regard to these two challenged jurors.', 'general', 'State v. Wade', 'https://www.courtlistener.com/opinion/1330549/', '1330549') ON CONFLICT DO NOTHING;
