INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'case of two counts of involuntary manslaughter and, accordingly, we reverse the courts below and remand for trial.', 'general', 'Commonwealth v. Huggins', 'https://www.courtlistener.com/opinion/2323025/', '2323025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the order of the Superior Court, we reinstate the charges of involuntary manslaughter, and we remand the matter to the Court of Common Pleas of Monroe County for trial.', 'plea', 'Commonwealth v. Huggins', 'https://www.courtlistener.com/opinion/2323025/', '2323025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 279 (1979), when we held that “[t]he prosecuting attorney is a constitutional officer who exercises the sovereign power of the State at the will of the people and he is at all times answerable to them.', 'general', 'State Ex Rel. Diva P. v. Kaufman', 'https://www.courtlistener.com/opinion/1330571/', '1330571') ON CONFLICT DO NOTHING;
