INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 402, 410 (1991), we held that “[r]eckless driving lies somewhere between careless driving .', 'general', 'State v. Parks', 'https://www.courtlistener.com/opinion/1251761/', '1251761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 308, 316 (1997), we held that careless driving is a lesser-included offense of reckless driving, noting: “We cannot
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred in not instructing the jury on the lesser-included offense of negligent child abuse, and therefore, we reverse the Court of Appeals’ judgment affirming the district court’s judgment and remand the cause for a new trial.', 'general', 'State v. Parks', 'https://www.courtlistener.com/opinion/1251761/', '1251761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’ ” Thus, we conclude that because negligent child abuse falls somewhere between intentional abuse and lawful conduct, misdemeanor child abuse is a lesser-included offense of felony child abuse under the statutory elements test.', 'general', 'State v. Parks', 'https://www.courtlistener.com/opinion/1251761/', '1251761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record in this case contains such evidence.', 'general', 'State v. Parks', 'https://www.courtlistener.com/opinion/1251761/', '1251761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a fact susceptible to jury determination is a predicate to the imposition of an enhanced sentence, the Hawai`i Constitution requires that such factual determinations be made by the trier of fact.', 'sentencing', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 376 ("[B]ecause all of the essential elements of assault in the third degree were alleged in the oral charge and proven at trial, we hold that the appropriate remedy for Elliott''s post-conviction challenge to the defective charge is to remand the case for entry of judgment of conviction of assault in the third degree and for resentencing in accordance therewith.', 'sentencing', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we hold that: (1) the prosecution failed to offer a compelling justification to overrule Domingues;', 'general', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the jury, and not the sentencing judge, was required to make the factual finding that the police officer was on-duty when shot.', 'sentencing', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 901 (footnote omitted), this court held, inter alia, that (1) for purposes of enhanced sentences, "findings regarding (a) the age or handicapped status of the victim and (b) whether `[s]uch disability is known or reasonably should be known to the defendant'' entail `intrinsic'' facts[]" that are "inextricably enmeshed in the defendant''s actions in committing the offense charged[,]" Tafoya, 91 Hawai`i at 271, 982 P.', 'sentencing', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On March 21, 2007, this court held oral argument.', 'general', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Analyzing the language of the prosecution''s oral charge, we concluded that the assault against a police officer charge was fatally defective because it did not allege that the offense was committed against "a police officer who [was] engaged in the performance of duty[.', 'general', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we reversed Elliott''s convictions of the offenses of assault against a police officer and resisting arrest.', 'general', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Thompson, supra, we held that an officer with reasonable suspicion under Ark.', 'general', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kaiser this court held that the police lacked reasonable suspicion to stop a vehicle suspected of carrying contraband when the information was provided by the Missouri State Police, who in turn told Arkansas authorities that the "information came from a reliable informant.', 'general', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the tip carried with it sufficient indicia of reliability to give the officer reasonable suspicion to justify an investigatory stop.', 'general', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that under the totality of the circumstances, Smith''s tip carried with it sufficient indicia of reliability to justify an investigatory stop under Rule 3.', 'general', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court''s denial of appellant''s motion to suppress.', 'suppression', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the denial of Hammons''s motion to suppress because the two anonymous calls led the police detective to the parking lot for further investigation under Rule 2.', 'suppression', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[25] Consistently with the legislative mandate, we hold that the aggravating circumstance specified below should have been quashed and, because this was the only aggravating *103 circumstance specified by the Commonwealth, we must vacate the sentence of death and remand for imposition of a sentence of life imprisonment.', 'sentencing', 'Commonwealth v. Boczkowski', 'https://www.courtlistener.com/opinion/2181355/', '2181355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 110, 119-20 (2001), this Court held that for a statement to be considered an excited utterance, it must be made spontaneously and without opportunity for reflection:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we find that this sentence of death cannot stand under Section 9711(h)(3)(i)''s proscription against sentences that are the product of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Commonwealth v. Boczkowski', 'https://www.courtlistener.com/opinion/2181355/', '2181355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the verdict of guilt, *81 but vacate the sentence of death and remand for imposition of a sentence of life imprisonment.', 'sentencing', 'Commonwealth v. Boczkowski', 'https://www.courtlistener.com/opinion/2181355/', '2181355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found appellant''s claims of pre-trial and guilt phase error to be meritless, we affirm appellant''s conviction for first degree murder.', 'general', 'Commonwealth v. Boczkowski', 'https://www.courtlistener.com/opinion/2181355/', '2181355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Page, this Court held that "`each prior conviction is an element of the felony offense, and each must be specifically charged.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1149018/', '1149018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of the record, we find that the indictment charging Williams with felony DUI was sufficient according to the requirements of Miss.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1149018/', '1149018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the dissenters in Weaver misinterpreted the holding by the Court in McIlwain.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1149018/', '1149018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Cabrera-Pena should, in fairness, have been allowed to cross-examine Officer Membreno to fully place into context the substance of their conversation.', 'general', 'State v. Cabrera-Pena', 'https://www.courtlistener.com/opinion/1330625/', '1330625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that Terry, who had elected not to testify, could not thereafter admit the self-serving statement he made to the police.', 'general', 'State v. Cabrera-Pena', 'https://www.courtlistener.com/opinion/1330625/', '1330625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds the view that the state is not required to negate each exception to the offense of unlawfully carrying a pistol to sustain its burden of proof.', 'general', 'State v. Cabrera-Pena', 'https://www.courtlistener.com/opinion/1330625/', '1330625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We find that fundamental fairness requires that Cabrera-Pena be permitted to cross-examine Officer Membreno concerning the entirety of their conversation.', 'general', 'State v. Cabrera-Pena', 'https://www.courtlistener.com/opinion/1330625/', '1330625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Cabrera-Pena’s conduct — leaving Alma at Applebee’s and purchasing a handgun;', 'general', 'State v. Cabrera-Pena', 'https://www.courtlistener.com/opinion/1330625/', '1330625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without addressing whether or not SLED was granting permits that night, we find that Cabrera-Pena was not simply carrying a weapon;', 'general', 'State v. Cabrera-Pena', 'https://www.courtlistener.com/opinion/1330625/', '1330625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE the ruling of the Court of Appeals that an adverse party is not permitted to bring out, during cross-examination, remaining portions of an unrecorded conversation or oral statement made by the adverse party for the purpose of clarifying or explaining an entire conversation.', 'general', 'State v. Cabrera-Pena', 'https://www.courtlistener.com/opinion/1330625/', '1330625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in result.', 'general', 'State v. Cabrera-Pena', 'https://www.courtlistener.com/opinion/1330625/', '1330625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that petitioner''s probation had expired by the time of his arrest in *343 1976, and the trial court had no authority to extend the probationary period.', 'general', 'State Ex Rel. DeGreat v. Phelps', 'https://www.courtlistener.com/opinion/1127403/', '1127403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On review, we reverse.', 'general', 'State Ex Rel. DeGreat v. Phelps', 'https://www.courtlistener.com/opinion/1127403/', '1127403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the juror, albeit off the record, assured the trial court that he could be impartial, and because there was no evidence to the contrary, this court held that the trial court did not abuse its discretion in denying motions that the juror be excused and that a mistrial be declared.', 'mistrial', 'State v. Krutilek', 'https://www.courtlistener.com/opinion/1251651/', '1251651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Krutilek', 'https://www.courtlistener.com/opinion/1251651/', '1251651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Krutilek', 'https://www.courtlistener.com/opinion/1251651/', '1251651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'a panel of this Court held that the prohibition against double jeopardy was not violated in a case where the defendant committed an armed robbery of an individual and stole the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this statute has yet to be interpreted, we conclude that the offense of stealing or retaining a financial transaction device constitutes a specific intent crime, given that knowledge is an essential element of this crime.', 'general', 'People v. Ainsworth', 'https://www.courtlistener.com/opinion/2174650/', '2174650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'First Pacific Corp. v. Sociedade De Empreendimentos E Construcoes, Ltda.', 'https://www.courtlistener.com/opinion/1151894/', '1151894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because the employment of Gerson was solicited in violation of Section 877.', 'general', 'Spence, Payne, Masington v. Philip M. Gerson', 'https://www.courtlistener.com/opinion/1097501/', '1097501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse a judgment awarding to the appellee, Philip M.', 'general', 'Spence, Payne, Masington v. Philip M. Gerson', 'https://www.courtlistener.com/opinion/1097501/', '1097501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the prosecutor’s remarks did not substantially affect defendant’s right to a fair trial on the charges of possession of a deadly weapon by a person prohibited and possession of a wiretap interception device.', 'general', 'Sexton v. State', 'https://www.courtlistener.com/opinion/2173435/', '2173435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that both warrants were issued upon constitutionally sufficient affidavits.', 'general', 'Sexton v. State', 'https://www.courtlistener.com/opinion/2173435/', '2173435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions on the possession charges, but because of prejudicial prosecutorial remarks, we reverse his convictions for receiving stolen property.', 'general', 'Sexton v. State', 'https://www.courtlistener.com/opinion/2173435/', '2173435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because this court has concluded that the terms lewd and lascivious are synonymous with obscene, we hold that the regulation of such conduct by ordinance or statute must conform to the guidelines set forth in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because not all sexual conduct is obscene, we hold that application of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that “lewd and lascivious behavior is synonymous with obscene behavior.', 'general', 'State v. Botsford', 'https://www.courtlistener.com/opinion/1253383/', '1253383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '160(b) fails to define “other sexual conduct,” we conclude that the district court properly determined that the section of the ordinance prohibiting public acts, offers, or attempts to engage in “other sexual conduct” is unconstitutionally overbroad on its face.', 'general', 'State v. Botsford', 'https://www.courtlistener.com/opinion/1253383/', '1253383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this testimony was permissible because it helped the jury understand one aspect of the evidencethe victim''s request to her assailantand because *530 the expert''s explanation did not constitute testimony with respect to the veracity of the victim.', 'general', 'Barnes v. State', 'https://www.courtlistener.com/opinion/1154921/', '1154921') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Using our often repeated plain error analysis, we find that what was said was rationally based upon the officer''s perception of the witness, helpful to a clear understanding of her testimony, violated no rule of law, and was properly admitted by the court.', 'general', 'Barnes v. State', 'https://www.courtlistener.com/opinion/1154921/', '1154921') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Barnes v. State', 'https://www.courtlistener.com/opinion/1154921/', '1154921') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 259, we concluded that the first prong of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that reckless driving is not a lesser-included offense of aggravated assault with a deadly weapon as alleged in the indictment, we need not consider the second step of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed because the indictment’s allegation of “habitation” was functionally equivalent to the allegation of notice that entry into the habitation was forbidden.', 'general', 'Rice v. State', 'https://www.courtlistener.com/opinion/2284489/', '2284489') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and remand to the court of appeals to address the remaining issues.', 'general', 'Rice v. State', 'https://www.courtlistener.com/opinion/2284489/', '2284489') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that sex offender registration is not part of a defendant’s sentence but is, instead, a civil regulatory measure that attaches certain collateral consequences to a conviction for a sex offense.', 'sentencing', 'Peterson v. State', 'https://www.courtlistener.com/opinion/1196176/', '1196176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if the defendant was not otherwise aware of the sex offender registration requirement, and if the defendant would not have entered his plea had he known of this requirement, then the defendant is entitled to withdraw his plea.', 'plea', 'Peterson v. State', 'https://www.courtlistener.com/opinion/1196176/', '1196176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though we conclude that sex offender registration is a “collateral” consequence of Peterson’s plea, the fact remains that the legislature expressly amended Criminal Rule 11(c) to make sure that defendants are warned about their duty to register as sex offenders before they plead guilty or no contest to a sex crime.', 'plea', 'Peterson v. State', 'https://www.courtlistener.com/opinion/1196176/', '1196176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this history of the ABA standard from which Aaska Criminal Rule 11(h)(4) was drawn, we conclude that the four clauses of Rule 11(h)(4) are not intended to define the outer limits of “manifest injustice”.', 'general', 'Peterson v. State', 'https://www.courtlistener.com/opinion/1196176/', '1196176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But examining the legislature’s actions as a whole, we conclude that the legislature enacted Criminal Rule 11(e)(4) because they concluded that it would be manifestly unfair to allow a defendant to plead guilty or no contest to a sex offense without first warning the defendant about the requirement of sex offender registration.', 'plea', 'Peterson v. State', 'https://www.courtlistener.com/opinion/1196176/', '1196176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we REVERSE the superior court’s order dismissing Peterson’s claim regarding the court’s failure to apprise Peterson of the sex offender registration law.', 'dismissal', 'Peterson v. State', 'https://www.courtlistener.com/opinion/1196176/', '1196176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the reasons discussed above, we AFFIRM the superior court’s order dismissing Peterson’s claims (1) that he was denied the right of allocution, (2) that the court failed to ascertain that he understood the nature of the charge, and (3) that he received ineffective assistance of counsel.', 'dismissal', 'Peterson v. State', 'https://www.courtlistener.com/opinion/1196176/', '1196176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that, for defendants who pleaded guilty or no contest to an offense listed in AS 12.', 'plea', 'Peterson v. State', 'https://www.courtlistener.com/opinion/1196176/', '1196176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that to the extent that our decision in Campbell established the broad rule that criminal intent can be found by implication only in statutes which codify common law crimes, Campbell is overruled.', 'general', 'Kimoktoak v. State', 'https://www.courtlistener.com/opinion/1160443/', '1160443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that we may.', 'general', 'Kimoktoak v. State', 'https://www.courtlistener.com/opinion/1160443/', '1160443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus in Campbell we concluded that AS 11.', 'general', 'Kimoktoak v. State', 'https://www.courtlistener.com/opinion/1160443/', '1160443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that instance, we found that we were unable to redraft the statute in several particulars so as to validate it.', 'general', 'Kimoktoak v. State', 'https://www.courtlistener.com/opinion/1160443/', '1160443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, finding as did the Court of Appeals that respondent was entitled to a directed verdict on the burglary charge.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1273647/', '1273647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the right to “be present .', 'general', 'Kimes v. United States', 'https://www.courtlistener.com/opinion/1981219/', '1981219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agree that the admission of the “other coats” evidence raised the possibility of the unfavorable inference that appellant suggests, we conclude that, under the circumstances, admission of this evidence does not warrant reversal of appellant’s conviction.', 'general', 'Kimes v. United States', 'https://www.courtlistener.com/opinion/1981219/', '1981219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that even if the evidence was erroneously admitted or interpreted to the jury, any such error — in light of the strong evidence of guilt — was not “so clearly prejudicial to substantial rights as to jeopardize the very fairness and integrity of the trial.', 'general', 'Kimes v. United States', 'https://www.courtlistener.com/opinion/1981219/', '1981219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects we affirm the conviction.', 'general', 'Kimes v. United States', 'https://www.courtlistener.com/opinion/1981219/', '1981219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that anything that is used in a manner likely to cause death or serious physical injury is a dangerous instrument.', 'general', 'Hart v. State', 'https://www.courtlistener.com/opinion/1154099/', '1154099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, but remand for resentencing.', 'sentencing', 'Hart v. State', 'https://www.courtlistener.com/opinion/1154099/', '1154099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that double time credits were not awardable.', 'general', 'State v. Reffitt', 'https://www.courtlistener.com/opinion/1154142/', '1154142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that the facts precluded such an instruction.', 'general', 'State v. Reffitt', 'https://www.courtlistener.com/opinion/1154142/', '1154142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the failure to object to the computation of appellant’s sentence, we find that appellant’s sentence was not miscomputed.', 'sentencing', 'State v. Reffitt', 'https://www.courtlistener.com/opinion/1154142/', '1154142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'John Doe asserts that even if this court holds Collins satisfied Section 38-77-170, he is still entitled to a directed verdict because Collins did not produce witnesses to establish John Doe caused the accident.', 'general', 'Collins v. Doe', 'https://www.courtlistener.com/opinion/1358390/', '1358390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Collins v. Doe', 'https://www.courtlistener.com/opinion/1358390/', '1358390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Corey''s motion was sufficient to preserve for appeal the issue of whether venue was established.', 'general', 'State v. Corey J.G.', 'https://www.courtlistener.com/opinion/1252026/', '1252026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Corey''s motion was sufficient to preserve the issue of venue for appeal.', 'general', 'State v. Corey J.G.', 'https://www.courtlistener.com/opinion/1252026/', '1252026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature''s usage of the word "resides" is ambiguous, as the term may reasonably be interpreted as meaning "residence" or "domicile.', 'general', 'State v. Corey J.G.', 'https://www.courtlistener.com/opinion/1252026/', '1252026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that Corey''s motion to dismiss was sufficiently specific to preserve the issue of whether venue had been established for appeal.', 'dismissal', 'State v. Corey J.G.', 'https://www.courtlistener.com/opinion/1252026/', '1252026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals.', 'general', 'State v. Corey J.G.', 'https://www.courtlistener.com/opinion/1252026/', '1252026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Mitchell testified that Diana’s injuries were life-threatening), we hold that Diana’s statements to Officer Kuaana, Dr.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
