INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and, accordingly, we hold that Mow-Taira was properly allowed to testify regarding the effects of domestic violence and, in particular, that victims of domestic violence often recant allegations of abuse.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with the foregoing authority, we hold that, where a victim recants allegations of abuse, evidence of prior incidents of violence between the victim and the defendant are relevant to show the trier of fact the context of the relationship between the victim and the defendant, where, as here, that relationship is offered as a possible explanation for the victim’s recantation.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, viewing the trial record in the light most favorable to the prosecution, we hold that a reasonable trier of fact could fairly conclude, beyond a reasonable doubt, that the prosecution had proved that Clark “[i]n-tentionally engage[d] in conduct which .', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we hold that there was no misconduct on the part of the prosecutor in this case.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the evidence in the present case and the context in which the phrase “cockamamie story” was utilized, we conclude that the prosecutor was well within the limits of propriety to infer, and indeed argue, that Clark’s denial of drug usage was improbable, untruthful, and, in short, a “cockamamie story.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm Clark’s conviction.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we affirm Clark’s conviction.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial court did not err in admitting Diana’s tape recorded statement to Detective Swann as substantive evidence of Clark’s guilt.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1160484/', '1160484') ON CONFLICT DO NOTHING;
