INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[20] For the reasons set forth in *417 Boyne, we hold that the statute cannot be contrived to encompass a condition of probation, incarceration, which is in fact the antithesis of the essential purposes of probation.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that Sprague''s admissions of guilt were not the product of any improper promises on the part of the investigating officers.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Roman we found that conditioning the appellant''s probation on his consent to warrantless searches under the direction of the parole officer was "reasonably related to the rehabilitation of the offender and the protection of the public" and was not "unduly restrictive of liberty.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
