INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We affirm the judgment, finding no error in the trial court''s ruling that Sprague''s statements did not constitute involuntary admissions or confessions.', 'general', 'Sprague v. State', 'https://www.courtlistener.com/opinion/1150286/', '1150286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking narrowly at the question framed by Kluss, whether the district court erred by not giving an included offense instruction, we hold that where there was no request for such an instruction, and the court was given no reason to believe that such an instruction was desired by Kluss or appropriate under existing law, there was no error.', 'general', 'State v. Kluss', 'https://www.courtlistener.com/opinion/1196482/', '1196482') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, while we hold that there was substantial evidence upon which the jury could find that Kluss had an intent to deliver the marijuana, the evidence almost entirely overlaps the evidence relating to “manufacturing.', 'general', 'State v. Kluss', 'https://www.courtlistener.com/opinion/1196482/', '1196482') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that to punish .', 'general', 'State v. Kluss', 'https://www.courtlistener.com/opinion/1196482/', '1196482') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err.', 'general', 'State v. Kluss', 'https://www.courtlistener.com/opinion/1196482/', '1196482') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute creates no privacy interest in utility company records.', 'general', 'State v. Kluss', 'https://www.courtlistener.com/opinion/1196482/', '1196482') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the evidence presented to the magistrate at the probable cause hearing is not affected by any
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons given below, we affirm the conviction and sentences for manufacturing marijuana and possession of marijuana without a tax stamp, but in order to avoid double punishment for the same acts, we vacate the conviction for possession with intent to deliver.', 'sentencing', 'State v. Kluss', 'https://www.courtlistener.com/opinion/1196482/', '1196482') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in the exercise of our supervisory power to insure the fair administration of justice, we hold that all custodial interrogation including any information about rights, any waiver of those rights, and all questioning shall be electronically recorded where feasible and must be recorded when questioning occurs at a place of detention.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, the Alaska Supreme Court has also ruled that such recording is generally required: “we hold that an unexcused failure to electronically record a custodial interrogation conducted in a place of detention violates a suspect’s right to due process, under the Alaska Constitution, and that any statement thus obtained is generally inadmissible.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whittaker contends that the excluded testimony should have been allowed as an exception to the hearsay rule, we conclude that the excluded testimony of Ms.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whittaker’s assignments of error, we conclude that the circuit court did not err by upholding Ms.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the parties’ arguments, the record presented for our consideration, and the pertinent authorities, we affirm Ms.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the bar’s actions were not in breach of this duty, and affirm the grant of summary judgment.', 'general', 'Feliciano v. Waikiki Deep Water, Inc.', 'https://www.courtlistener.com/opinion/1283368/', '1283368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From these authorities, we conclude that without more, aggressive sales of drinks at a bar do not constitute affirmative acts that would create liability to the consumer on the part of the bar or tavern.', 'general', 'Feliciano v. Waikiki Deep Water, Inc.', 'https://www.courtlistener.com/opinion/1283368/', '1283368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that an incarcerated individual who raises an issue on direct appeal that was not the subject of a previous petition seeking post-conviction relief under West Virginia Code § 53-4A-1 is not prohibited from seeking habeas corpus relief following the issuance of an opinion by the West Virginia Supreme Court of Appeals where the decision on the appeal does not contain any ruling on the merits of the issue, as no final adjudication within the meaning of West Virginia Code § 5...', 'habeas', 'State v. Frye', 'https://www.courtlistener.com/opinion/1331508/', '1331508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of this matter, we find that the record is not properly developed to permit us to review this issue on its merits.', 'general', 'State v. Frye', 'https://www.courtlistener.com/opinion/1331508/', '1331508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the ruling below.', 'general', 'State v. Frye', 'https://www.courtlistener.com/opinion/1331508/', '1331508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that absent extraordinary circumstances, courts should apply the calculation methodology of Rule 90.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "a court must consider the best interests of the children by applying the criteria in AS 25.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that the superior court made several erroneous factual findings regarding Linda''s credibility, we conclude that these errors were not prejudicial.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court did not clearly err with respect to its findings regarding Linda''s disciplinary methods, Robert''s presence at home when Linda and Jeana lived with Robert, and Robert''s refusal to pay for day care.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] Although we conclude that the court clearly erred in finding that Linda made false or misleading statements regarding her current alcohol consumption and her allegation that Robert stalked her,[4] these errors were harmless given the remaining findings bearing on Linda''s credibility.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the erroneous findings of wrongful conduct and custodial interference influenced and invalidated the superior court''s conclusion that Linda had failed to foster a healthy relationship between Jeana and Robert and would continue to do so in the future.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these rulings were permissible and reveal no partiality or bias.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the standard announced in House, 779 P.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the "decision of the family to move to [California] was based upon a valid reason, that is, a reason which was not primarily motivated by a desire to make visitation .', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we reverse the custody award because the court erroneously weighed the statutory factors.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although Detective Smentkowski’s statements were not admitted under a “firmly rooted” hearsay exception, we hold that an unavailability analysis is, likewise, unnecessary
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, we hold that the trial court’s ruling constituted no abuse of discretion.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The trial court concluded that the testimony supported circumstances constituting an excited utterance, and after a careful review of the record, we hold that sufficient facts support the trial court’s conclusion.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that any argument that might have been raised as to self-defense based on lack of confrontation has been abandoned and that the trial court did not abuse its discretion by admitting only as much of Detective SmentkowsM’s testimony as the trial court determined to be both probative and reliable.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we hold that the trial court did not abuse its discretion in refusing to permit Williamson to question Zecca about Williamson’s description of the events in the motel room.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion by refusing to grant the appellants ten peremptory challenges and that, in reaching its decision, the trial court was not unfairly partial to the State.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that the trial court violated the defendant’s rights by refusing to allow him to question witnesses about cash payments they had allegedly received from the victim’s mother.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that a victim’s statement may not be admitted “for the purpose of identifying the defendant as a killer.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that each of the arguments lacks merit and affirm the convictions.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that ‘Roberts must be read consistently with the question it answered, the authority it cited, and its own facts.', 'general', 'Williamson v. State', 'https://www.courtlistener.com/opinion/2060701/', '2060701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if the matter of contempt was an unresolved issue, we hold that the “notice” provided by the order failed adequately to apprise plaintiff that she should be prepared to defend herself against the charges.', 'general', 'O''Briant v. O''Briant', 'https://www.courtlistener.com/opinion/1158575/', '1158575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we hold that the notice afforded plaintiff was inadequate to inform her that she should be prepared to defend herself for her failure to attend court hearings on charges of contempt in the February 1983 custody trial.', 'general', 'O''Briant v. O''Briant', 'https://www.courtlistener.com/opinion/1158575/', '1158575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Guided by these principles, we conclude that plaintiffs failure to appear at two court hearings, if contempt at all, constituted criminal contempt.', 'general', 'O''Briant v. O''Briant', 'https://www.courtlistener.com/opinion/1158575/', '1158575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that such actions on the part of the respondent constitute an usurpation of judicial power, we hold that prohibition is a proper proceeding in this case.', 'general', 'State Ex Rel. Miller v. Smith', 'https://www.courtlistener.com/opinion/1331747/', '1331747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a prosecuting attorney who attempts to influence the grand jury by means other than the presentation of evidence or the giving of court supervised instructions, exceeds his lawful jurisdiction and usurps the judicial power of the circuit court and of the grand jury.', 'general', 'State Ex Rel. Miller v. Smith', 'https://www.courtlistener.com/opinion/1331747/', '1331747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that, by application to the circuit judge, whose duty is to insure access to the grand jury, any person may go to the grand jury to present a complaint to it.', 'general', 'State Ex Rel. Miller v. Smith', 'https://www.courtlistener.com/opinion/1331747/', '1331747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we disagree, we vacate the decision of the court of appeals, we reverse the district court’s judgment of conviction, and we remand for entry of a judgment of acquittal.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/2174322/', '2174322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We vacate the decision of the court of appeals, we reverse the district court’s judgment of conviction, and we remand for entry of a judgment of acquittal.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/2174322/', '2174322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, when the government employs a licensing scheme to regulate a profession or an activity that affects the public welfare, administrative revocation or suspension of that license can legitimately serve to deter conduct and still remain "remedial" for double jeopardy purposes so long as the revocation or suspension is based on conduct that bears a direct relation to the government''s regulatory goals or to the proper administration and enforcement of the regulatory scheme.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained in more detail below, we conclude that when the legislature employs a licensing scheme to regulate a profession or an activity affecting the public health or safety, a statute that authorizes a regulatory body to revoke these licenses is "remedial" for double jeopardy purposes even though the law serves to deter licensees from engaging in conduct that is inconsistent with their duties as licensees or that is inconsistent with the public welfare.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the administrative revocation of the defendants'' driver''s licenses is premised on remedial goals.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as the Supreme Court declined to unreflectively apply the *758 Halper test in Austin and Kurth Ranch, we conclude that Halper''s statements about deterrence do not govern the cases before us.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that administrative license revocation continues to be a "remedial" sanction, not a "punitive" sanction, for purposes of the federal double jeopardy clause.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8]  In one exhortatory paragraph that cites no pertinent legal authority, the defendants urge us to declare that administrative revocation of driver''s licenses constitutes "punishment" for purposes of the double jeopardy clause of the Alaska Constitution (Article I, Section 9), even if we conclude that administrative revocation is remedial for purposes of the Federal Constitution.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we reinstate the prosecutions that were dismissed and we affirm the district court''s refusal to dismiss the prosecution in file number A-5739.', 'dismissal', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under the Double Jeopardy Clause a defendant who already has been punished in a criminal prosecution may not be subjected to an additional civil sanction to the extent that the second sanction may not fairly be characterized as remedial, but only as a deterrent or [as] retribution.', 'general', 'State v. Zerkel', 'https://www.courtlistener.com/opinion/1158382/', '1158382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon careful review we find that these contentions are not fairly raised by the record before this Court, and therefore we are unable to address their merits.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1331968/', '1331968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that admission of these remarks does not rise to the level of plain error.', 'general', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that most of the challenged testimony was properly admitted under the “excited utterance” exception to the hearsay rule.', 'general', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Judge Taylor did not err in his treatment of the evidence of flight.', 'general', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Lipscomb’s due process rights were not violated.', 'general', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trustworthiness of all the statements made by O''Donnell and admitted through the testimony of LaSage and Nielsen was established either by the fact that they fell within the recognized hearsay exception for excited utterances or by "particularized guarantees," including the strong corroborative evidence
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that evidence that Dyer fled the scene immediately, assumed a false name on at least one occasion, and deliberately avoided all contact with police for nearly sixteen months was properly admitted.', 'general', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that, “while not binding on the trial court, the new code does give an indication of current legislative intent and, absent factors in a specific case warranting a harsher sentence, the defendant should be sentenced within the range of sentences provided by the new code.', 'sentencing', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that, even if Lipscomb’s denial would have been admissible before the grand jury as an exculpatory statement, the exclusion did not constitute error.', 'general', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that admission of the information contained in Detective Nielsen’s questions on the audio tape, if error, was harmless.', 'general', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statements made to LaSage immediately after his arrival were properly admitted as “excited utterances,” under Evidence Rule 803(2).', 'general', 'Lipscomb v. State', 'https://www.courtlistener.com/opinion/1194760/', '1194760') ON CONFLICT DO NOTHING;
