INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that misdemeanor breaking or entering should have been submitted to the jury since “[t]he jury was not compelled to find from the evidence that the defendant intended to commit rape at the time he entered the building.', 'general', 'State v. Lawrence', 'https://www.courtlistener.com/opinion/1203326/', '1203326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In contrast, this Court held that the trial court properly refused to submit the lesser-included offense of breaking or entering in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that “the evidence was clear and positive that defendant entered the apartment with the intent to commit larceny, and the fact that he also may have intended to commit the felonies of rape and murder does not constitute evidence that he entered the apartment without the intent to commit a felony therein.', 'general', 'State v. Lawrence', 'https://www.courtlistener.com/opinion/1203326/', '1203326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held the two circumstances were not supported by the same evidence.', 'general', 'State v. Lawrence', 'https://www.courtlistener.com/opinion/1203326/', '1203326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that a juror may find that a nonstatutory mitigating circumstance exists but may give that circumstance no mitigating value.', 'general', 'State v. Lawrence', 'https://www.courtlistener.com/opinion/1203326/', '1203326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we conclude that defendant’s trial was free from prejudicial error.', 'general', 'State v. Lawrence', 'https://www.courtlistener.com/opinion/1203326/', '1203326') ON CONFLICT DO NOTHING;
