INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon further reflection, we hold that findings regarding (a) the age or handicapped status of the victim and (b) whether “[s]uch disability is known or reasonably should be known to the defendant” entail “intrinsic” facts.', 'general', 'State v. Tafoya', 'https://www.courtlistener.com/opinion/1252759/', '1252759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a fact susceptible to jury determination is a predicate to the imposition of an enhanced sentence, the Hawai''i Constitution requires that such factual determinations be made by the trier of fact.', 'sentencing', 'State v. Tafoya', 'https://www.courtlistener.com/opinion/1252759/', '1252759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, this court held that “[defense counsel’s actions] reflected a ‘lack of skill, judgment or diligence[.', 'general', 'State v. Tafoya', 'https://www.courtlistener.com/opinion/1252759/', '1252759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the circuit court’s imposition of an enhanced sentence, vacate the sentence imposed and remand for resentencing without enhancement.', 'sentencing', 'State v. Tafoya', 'https://www.courtlistener.com/opinion/1252759/', '1252759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the circuit court’s imposition of an enhanced sentence, vacate the sentence imposed and remand for resentencing without enhancement.', 'sentencing', 'State v. Tafoya', 'https://www.courtlistener.com/opinion/1252759/', '1252759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Tafoya’s conviction.', 'general', 'State v. Tafoya', 'https://www.courtlistener.com/opinion/1252759/', '1252759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Tafo-ya’s conviction.', 'general', 'State v. Tafoya', 'https://www.courtlistener.com/opinion/1252759/', '1252759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the informant''s tip, particularly the prediction of future events, the details of which were verified by the observation of the law enforcement officers, furnished more than adequate probable cause to stop the Goettl vehicle.', 'probable_cause', 'Goettl v. State', 'https://www.courtlistener.com/opinion/1205036/', '1205036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 5, in which we held that, after police officers have stopped a vehicle for investigatory purposes, they may obtain additional information about the suspects that leads to adequate probable cause for an arrest.', 'probable_cause', 'Goettl v. State', 'https://www.courtlistener.com/opinion/1205036/', '1205036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that there was insufficient probable cause to arrest Susan Rodarte.', 'probable_cause', 'Goettl v. State', 'https://www.courtlistener.com/opinion/1205036/', '1205036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2412, we conclude that sufficient probable cause was present to justify the investigatory stop of Goettl''s car.', 'probable_cause', 'Goettl v. State', 'https://www.courtlistener.com/opinion/1205036/', '1205036') ON CONFLICT DO NOTHING;
