INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the intrasovereign context, we hold that in the absence of collusion, unlawfully seized evidence may properly be admitted for purposes of an independent civil tax assessment proceeding.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nash, supra at 207-215, 225-226, this Court held that the Michigan Constitution does not pro*231vide a greater degree of protection than the United States Constitution unless there is a "compelling reason” to impose a different interpretation.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, on finding that there were no "compelling reasons” to interpret art 1, § 11 of the Michigan Constitution any differently than the Fourth Amendment, this Court held that the evidence was admissible.', 'search_seizure', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By balancing each of *237the five Wolf factors, we conclude that an application of the exclusionary rule in the instant case would not deter future violations of the Fourth Amendment.', 'search_seizure', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of more than "curious facts” and agreeing with the dissent that there is no direct evidence of bad faith, collusion between the agencies, or unethical behavior on the part of the law enforcement agents, we conclude that the Court of Appeals incorrectly found that evidence seized in an improper police search may not be used as the basis of an independent civil jeopardy tax assess- .', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the secondary proceedings were intrasovereign.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals determination and find in favor of respondent Department of Treasury.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and reinstate the order of the Tax Tribunal.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
