INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding waiver, we conclude that these issues have no merit.', 'general', 'State v. Townes', 'https://www.courtlistener.com/opinion/1079473/', '1079473') ON CONFLICT DO NOTHING;
