INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a full review of the record, the briefs, and the applicable law, we affirm the trial court’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that where a criminal defendant has been placed on probation after successfully completing a program of rehabilitation under the Youthful Offenders Act, and such probation is subsequently revoked, the circuit court has no discretion under § 25-4-6 to impose anything other than the sentence that the defendant would have originally received had he or she not been committed to a youthful offender center and subsequently placed on probation.', 'sentencing', 'State v. Richards', 'https://www.courtlistener.com/opinion/1204317/', '1204317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Valid policy arguments favoring flexibility in this area notwithstanding, we conclude that the Act expressly forecloses such action.', 'general', 'State v. Richards', 'https://www.courtlistener.com/opinion/1204317/', '1204317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a private citizen may not use force to resist peaceful arrest by one he knows or has good reason to believe is an authorized peace officer performing his duties, regardless of whether the arrest is illegal in the circumstances of the occasion.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/1183397/', '1183397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We are of the opinion that the trend is, and should be, away from the traditional common law rule, and therefore we hold that if a person has reasonable ground to believe he is being arrested by a peace officer, it is his duty to refrain from using force or any weapon in resisting arrest regardless of whether or not there is a legal basis for the arrest.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/1183397/', '1183397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regardless of whether the arrest is illegal under the circumstances of the occasion, we hold that an individual may not use force to resist an arrest by one he knows or has good reason to believe is an authorized peace officer in the performance of his duties.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/1183397/', '1183397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we conclude that Wis.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that § 756.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that Wis.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Wis.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '528, 529 (1932) ("Hence, we find that at common law a man might change his name as radically and as often as he desired, if for an honest purpose and not to the injury of third persons.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the circuit court''s judgment convicting the Defendant of obstructing an officer.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Defendant''s conviction for bail jumping.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'I, § 7 and, therefore, we reverse the Defendant''s convictions for obstructing an officer and bail jumping.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Defendant''s convictions for obstructing an officer and bail jumping and remand the case to the circuit court for further proceedings consistent with this opinion.', 'general', 'State v. Hansford', 'https://www.courtlistener.com/opinion/1709803/', '1709803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of these circumstances, we hold that the matter must be remanded to the district court for the purpose of developing the facts concerning Ravin''s arrest and circumstances of his possession of marijuana.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that such a fundamental right is shown by virtue of the analysis we employed in Breese.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that citizens of the State of Alaska have a basic right to privacy in their homes under Alaska''s constitution.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that no adequate justification for the state''s intrusion into the citizen''s right to privacy by its prohibition of possession of marijuana by an adult for personal consumption in the home has been shown.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that hairstyles are a highly personal matter in which the individual is traditionally autonomous, we concluded that governmental control of personal appearance would be antithetical to the concept of personal liberty under Alaska''s constitution.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the student would be forced to choose between controlling his own personal appearance and asserting his right to an education if the regulations were upheld, we concluded that the constitutional language quoted above embodied an affirmative grant of liberty to public school students to choose their own hairstyles, for "at the core of [the concept of liberty] is the notion of total personal immunity from government control: the right `to be let alone.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the total sentence of fifteen years with five years suspended was clearly mistaken.', 'sentencing', 'Lawrence v. State', 'https://www.courtlistener.com/opinion/1161813/', '1161813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Carlson was clearly mistaken in restricting Lawrence’s parole eligibility.', 'general', 'Lawrence v. State', 'https://www.courtlistener.com/opinion/1161813/', '1161813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we affirmed Langton’s sentence, found that Doe’s sentence was too lenient, and ordered Joe’s sentence reduced to ten years.', 'sentencing', 'Lawrence v. State', 'https://www.courtlistener.com/opinion/1161813/', '1161813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 318 (2004), this Court held that the State could amend a habitual felon indictment pursuant to N.', 'general', 'State v. Coltrane', 'https://www.courtlistener.com/opinion/1208700/', '1208700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 324, we conclude that the 10 April 2006 indictment in the present case sufficiently notified defendant that the prior felony conviction referenced was his 8 June 2004 conviction for fleeing to elude arrest, which occurred in Guilford County.', 'general', 'State v. Coltrane', 'https://www.courtlistener.com/opinion/1208700/', '1208700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Court of Appeals erred, and we thus reverse that opinion.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1358524/', '1358524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We are not persuaded by this argument, and we conclude that, under the circumstances, the burden of reliability was not met.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1358524/', '1358524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, on its own, this tip is not sufficient to create a reasonable suspicion.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1358524/', '1358524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'to be a “close case,” we conclude that defendant’s Fourth Amendment protections were violated.', 'search_seizure', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1358524/', '1358524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the tip taken as a whole was insufficient to create a reasonable suspicion, we next look to see if it was made sufficient by independent police corroboration.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1358524/', '1358524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), we held that the voluntariness of a plea was not affected where defense counsel stated that a fifteen-year sentence would be imposed, requiring actual confinement of only two or three years, but the defendant was specifically informed by the judge that recommendations by counsel were not binding and that a life sentence could be imposed.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hays was fully aware he was admitting the jurisdictional facts alleged in the information.', 'general', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hays'' contention is not moot.', 'general', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the above points do not show that counsel''s performance so undermined the proceedings that a just result was not produced.', 'general', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the offenses for which the Legislature has authorized life sentences, we conclude that an indeterminate life sentence, with parole eligibility, for lewd and lascivious conduct with a minor is not per se unconstitutional.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that his sentence is proportional to the offense he committed.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hays'' application raised no genuine material issues of fact regarding the district court''s jurisdiction, assistance of counsel, disproportionality of the sentence, and breach of the plea agreement.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that Hays'' sentence is not unreasonable or excessive.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 730 (1963) in which we held that the right to a preliminary hearing may be forfeited by one who becomes a fugitive.', 'general', 'Commonwealth v. Boyd', 'https://www.courtlistener.com/opinion/1963953/', '1963953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the appellant by becoming a fugitive lost his right to a review of his post-trial motions and that the trial court did not abuse its discretion in refusing to consider the motions upon his return to the jurisdiction.', 'general', 'Commonwealth v. Boyd', 'https://www.courtlistener.com/opinion/1963953/', '1963953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in terminating S.', 'general', 'Sj v. Lt', 'https://www.courtlistener.com/opinion/1204471/', '1204471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the Los Angeles Superior Court did not exercise jurisdiction substantially in conformity with the UCCJA, but that the Alaska Superior Court did not abuse its discretion in deferring to California and staying the Alaska proceeding even though the California court did not have jurisdiction.', 'general', 'Sj v. Lt', 'https://www.courtlistener.com/opinion/1204471/', '1204471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part and remand for further proceedings.', 'general', 'Sj v. Lt', 'https://www.courtlistener.com/opinion/1204471/', '1204471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that an appeal of an individual dismissal would not have provided an adequate remedy, we hold that in the instant matter the circuit court’s issuance of the order of superintending control was clearly appropriate.', 'dismissal', 'City of Detroit v. Recorder''s Court Judge', 'https://www.courtlistener.com/opinion/2062157/', '2062157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that an ordinance violation can properly be labelled a criminal act, assuming
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '288-289, in which Judge Hague’s practice of dismissing nontraffic ordinance violation complaints issued in ticket form was appealed, this Court held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, as in that case, we find that the City of Detroit was faced with an extraordinary situation — mass dismissals of city ordinance cases before trial.', 'dismissal', 'City of Detroit v. Recorder''s Court Judge', 'https://www.courtlistener.com/opinion/2062157/', '2062157') ON CONFLICT DO NOTHING;
