INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 407 (1958), this Court held that the one-year statute of limitations is applicable to actions for assault and false imprisonment applied to actions against police officers as well as others.', 'general', 'Fowler v. Valencourt', 'https://www.courtlistener.com/opinion/1225074/', '1225074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that where police lack express legislative authority, particularized suspicion of criminal wrongdoing and prior judicial approval, roadblocks established to apprehend drunk drivers cannot withstand constitutional scrutiny.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1162605/', '1162605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the individual’s right of freedom from arbitrary governmental intrusion, and the questionable efficacy of roadblocks, we conclude that such roadblocks cannot withstand constitutional scrutiny.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1162605/', '1162605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1162605/', '1162605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we affirm the judgment of the trial court.', 'general', 'Manns v. Commonwealth', 'https://www.courtlistener.com/opinion/1235651/', '1235651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Charles Parish Certified Conviction packet introduced into evidence at the multiple bill hearing, we find that the State produced sufficient evidence to prove that defendant Brown is the same individual convicted of manslaughter in St.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/5041362/', '5041362') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/5041362/', '5041362') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion by admitting the 911 tape into evidence.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1967082/', '1967082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore we conclude that the evidence was legally sufficient to sustain appellant’s con-vietion for first-degree premeditated murder.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1967082/', '1967082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1967082/', '1967082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Defendant raises no other issues on appeal, we affirm Defendant’s conviction and sentence.', 'sentencing', 'State v. Lefevre', 'https://www.courtlistener.com/opinion/1224300/', '1224300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), is controlling on this point wherein we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it was "within the sound discretion of the trial judge as to whether or not burglary tools found near the scene of a burglary are near enough in time and place to be of a probative evidentiary value.', 'general', 'Hubbard v. State', 'https://www.courtlistener.com/opinion/1668187/', '1668187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 389 (1966), wherein we reversed a conviction because the trial judge''s remarks were "so marked and severe that it could not have failed to make an impression upon the jury.', 'general', 'Hubbard v. State', 'https://www.courtlistener.com/opinion/1668187/', '1668187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions on all charges.', 'general', 'Hubbard v. State', 'https://www.courtlistener.com/opinion/1668187/', '1668187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pictures of the decedent depicting his stab wound was admitted into evidence, and we affirmed.', 'general', 'Hubbard v. State', 'https://www.courtlistener.com/opinion/1668187/', '1668187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that ease, we held that proof of the mere presence of a weapon is insufficient to satisfy the “threatens to use” element of the crime of aggravated assault and battery.', 'general', 'Gunderson v. State', 'https://www.courtlistener.com/opinion/1163226/', '1163226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury reasonably inferred that Appellant’s actions with the gun constituted an actual threat to physically injure the female victim.', 'general', 'Gunderson v. State', 'https://www.courtlistener.com/opinion/1163226/', '1163226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Gunderson v. State', 'https://www.courtlistener.com/opinion/1163226/', '1163226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant did not make a prima facie showing of purposeful discrimination on the part of the State.', 'general', 'Morse v. State', 'https://www.courtlistener.com/opinion/2025738/', '2025738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On direct appeal, this Court held that "[i]f the statement here was a reference to the defendants'' failure to testify, it was not an `extended reference.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1219741/', '1219741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the error here was not harmless beyond a reasonable doubt and that defendant is entitled to a new trial.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1219741/', '1219741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and hold that any direct reference to defendant''s failure to testify is error and requires curative measures be taken by the trial court.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1219741/', '1219741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the state had power to try Defendant for the murder committed in Mexico.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the trial judge was not required to send the question of jurisdiction to the jury.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There being no textual limit on the reach of this statute conferring extra-territorial power, we conclude that the statute includes, on its face, offenses consummated in foreign countries as well as in other states and that it was properly applied by the trial court.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '17 We conclude that the *545application of A.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the danger of unfair prejudice on this record was not so great that any error could be described as fundamental.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On balance, we conclude that Defendant’s record of good deeds does not outweigh the aggravating factor.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that there was no error, fundamental or otherwise, in refusing Defendant’s request to instruct the jury on the jurisdictional prerequisites and only harmless error in the judge’s statement that he found jurisdiction by a preponderance.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We affirm the finding that Defendant murdered for financial gain.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Defendant’s convictions and death sentence.', 'sentencing', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The opinion stated: "We hold that a person has been `convicted of a felony'' when the appropriate trier of fact has made a determination of guilt and sentence has been imposed.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a person has been "convicted of a felony" when the appropriate trier of fact has made a determination of guilt and sentence has been imposed.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" In Kelly, we held that a witness could be impeached by evidence of a prior conviction of dishonesty or false statement under Evidence Rule 609 where the "verdict of guilt has been accepted but sentencing has not yet occurred.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rastopsoff, where this court held that a defendant should not be considered a repeat felony offender for presumptive sentencing purposes unless the defendant committed the subsequent felony after being sentenced for prior offenses.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendants who have entered a plea or have been found guilty of a felony at trial are "convicted of a felony" for purposes of this statute.', 'plea', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the precedent, policy, and reasoning discussed above, we conclude that the most persuasive interpretation of "convicted" is the interpretation first raised in Berg, that a defendant is "convicted of a felony" for purposes of AS 11.', 'general', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that AS 11.', 'general', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the policy set forth in Carlson seems to be better fulfilled by establishing the time of sentencing as the point when the conviction is final, rather than the time when there is a finding of guilty or a plea of guilty or nolo contendere.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is preferable to have a clear and definite time when a conviction will be final and that this time is the time of sentencing.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Leonard', 'https://www.courtlistener.com/opinion/1238571/', '1238571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that (1) Klinge''s constitutional right to a unanimous verdict was not violated inasmuch as HRS §§ 707-715(1) and (2) do not give rise to two separate and distinct crimes;', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that this remark did not constitute prosecutorial misconduct.', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in light of the nature of the prosecutor''s statement, the failure of defense counsel to object, and the strength of the evidence against Klinge, we hold that any error with regard to this statement by the prosecutor did not prejudicially affect Klinge''s substantial rights.', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4, we hold that his remark, though distasteful and unprofessional, was not so prejudicial as to deny Klinge a fair trial.', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion in denying Klinge''s motion for mistrial based on prosecutorial misconduct.', 'mistrial', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that (1) Klinge''s constitutional right to a unanimous verdict was not violated inasmuch as HRS §§ 707-715(1) and (2) do not give rise to two separate and distinct crimes;', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, this court held that the prosecutor''s repeated injection of her personal opinion concerning the defendant''s guilt and the credibility of defense witnesses amounted to plain error in light of "the inconclusive evidence against Marsh, the particularly egregious misconduct of the prosecutor in presenting her personal views on the dispositive issues, and the lack of a prompt jury instruction specifically directed to the prosecutor''s closing remarks[.', 'jury_instruction', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court''s judgment, guilty conviction and sentence filed on December 3, 1997.', 'sentencing', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court''s judgment, guilty conviction and sentence filed on December 3, 1997.', 'sentencing', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State presented substantial evidence tending to show that the defendant possessed the stolen automobile for a dishonest purpose.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1245841/', '1245841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the Court of Appeals did not err in overruling the defendant’s assignment concerning the Speedy Trial Act.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1245841/', '1245841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 203 (1983), we held that when superseding indictments are appropriate and obtained in good faith, the 120-day period begins on the date the new indictments were returned.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1245841/', '1245841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the State presented sufficient evidence to show that the defendant had reasonable grounds to believe that the Datsun was stolen.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1245841/', '1245841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these circumstances, we conclude that the State presented substantial evidence tending to show that the defendant knew or had reasonable grounds to believe the vehicle was stolen.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1245841/', '1245841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that such an interpretation is erroneous, and we accordingly reverse this portion of the decision of the Court of Appeals.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1245841/', '1245841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 104 (1999), this Court held that a person can be acting lawfully, even if he is in unlawful possession of a weapon, if he was entitled to arm himself in self-defense at the time of the shooting.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1234004/', '1234004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1234004/', '1234004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was evidence  in this case introduced by the State  supporting a conviction for the lesser included offense of voluntary manslaughter, we reverse Appellant''s conviction in the slaying of Kimberly Brown.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1234004/', '1234004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the given jury instructions omitted two elements of felony destruction of evidence and therefore did not provide instructions on all matters of law necessary for the jury’s information, we hold that the jury instructions as a whole did not fairly and accurately reflect the applicable law.', 'jury_instruction', 'State v. Peteja', 'https://www.courtlistener.com/opinion/2629266/', '2629266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the instruction incorrectly articulated the law applicable to the felony destruction of evidence because it failed to require the jury to find that the investigation was “criminal in nature” and “involve[d] a felony offense.', 'general', 'State v. Peteja', 'https://www.courtlistener.com/opinion/2629266/', '2629266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the district court’s instructions should have informed the jury that it must find whether the officer’s investigation was “criminal in nature” and whether the bag and its contents that Peteja concealed would have tended to demonstrate the commission of a felony.', 'general', 'State v. Peteja', 'https://www.courtlistener.com/opinion/2629266/', '2629266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, irrespective of the jury instructions’ omissions of the elements of a criminal investigation and involving a felony, we conclude that, on the whole record and beyond a reasonable doubt, the evidence on the omitted element is so clear and convincing that the return of the jury’s verdict could not have been attributable to any such erroneous instruction and that Peteja consequently has suffered no harm therefrom.', 'jury_instruction', 'State v. Peteja', 'https://www.courtlistener.com/opinion/2629266/', '2629266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a final matter, we conclude that, beyond a reasonable doubt, substantial and competent evidence of Peteja’s guilt on every material element suffices to sustain his felony conviction for the destruction or concealment of evidence.', 'general', 'State v. Peteja', 'https://www.courtlistener.com/opinion/2629266/', '2629266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, although the jury instructions were erroneous as to the elements of a felony destruction of evidence crime, that error was harmless.', 'jury_instruction', 'State v. Peteja', 'https://www.courtlistener.com/opinion/2629266/', '2629266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Peteja', 'https://www.courtlistener.com/opinion/2629266/', '2629266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason and because the evidence suffices to sustain Peteja’s conviction of that crime, we affirm.', 'general', 'State v. Peteja', 'https://www.courtlistener.com/opinion/2629266/', '2629266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm our decision that Magistrate Cruickshanks be suspended without pay until the underlying judicial disciplinary proceeding is completed.', 'general', 'In Re Cruickshanks', 'https://www.courtlistener.com/opinion/1231469/', '1231469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances and absent any record of the voir dire proceedings, we find that appellant has failed to establish the existence of purposeful discrimination.', 'general', 'Bueno-Hernandez v. State', 'https://www.courtlistener.com/opinion/1211373/', '1211373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of the circumstances surrounding his interrogation, we find that appellant’s statements were voluntarily, knowingly, and intelligently made.', 'general', 'Bueno-Hernandez v. State', 'https://www.courtlistener.com/opinion/1211373/', '1211373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'a crime, we find that the general attempt statute applies, and appellant was properly charged with attempted second-degree sexual assault.', 'general', 'Bueno-Hernandez v. State', 'https://www.courtlistener.com/opinion/1211373/', '1211373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bueno-Hernandez v. State', 'https://www.courtlistener.com/opinion/1211373/', '1211373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 317 (1994), this Court held that prior shoplifting convictions are elements of the crime of third-offense shoplifting, and are therefore admissible before the jury.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In footnote 1 of Cozart, this Court held that previous convictions of driving under the influence of alcohol are admissible to show the defendant is currently guilty of a third offense of driving under the influence of alcohol.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following a review of the parties'' arguments, the record of the proceedings below, and the pertinent authorities, we affirm the decision of the Circuit Court of Harrison County.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we affirm the decision of the Circuit Court of Harrison County as our law clearly concludes that prior shoplifting convictions are an element of third offense shoplifting.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the conviction and sentence.', 'sentencing', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the amended information was adequate.', 'general', 'Kindred v. State', 'https://www.courtlistener.com/opinion/2063677/', '2063677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold only that a strong showing of the photograph''s competency and authenticity must be established.', 'general', 'Kindred v. State', 'https://www.courtlistener.com/opinion/2063677/', '2063677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the State established an adequate foundation for the admission of the videotapes, and the trial court properly admitted them.', 'general', 'Kindred v. State', 'https://www.courtlistener.com/opinion/2063677/', '2063677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, given the circumstances of this offense, the sentence imposed in this case is neither grossly disproportionate to his crime, nor does it violate either the state or federal constitution.', 'sentencing', 'State v. Long', 'https://www.courtlistener.com/opinion/2629257/', '2629257') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, pursuant to A.', 'general', 'State v. Long', 'https://www.courtlistener.com/opinion/2629257/', '2629257') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm Long’s convictions and sentences.', 'sentencing', 'State v. Long', 'https://www.courtlistener.com/opinion/2629257/', '2629257') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987), we held that there is no violation of a defendant''s fundamental right to not be placed twice in jeopardy under the Fifth Amendment to the Constitution of the United States or under art.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1236292/', '1236292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Baum, we held that, if different criminal acts are at issue, supported by different factual evidence, even though they are separated in time by only a few seconds, one offense is not included in the other.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1236292/', '1236292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986), this court held charges of delivery of a controlled substance and possession of a controlled substance with intent to deliver did not merge for double jeopardy purposes.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1236292/', '1236292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the multiple punishments imposed and overrule Birr.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1236292/', '1236292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the trial court erred in permitting a police officer to testify to statements made by an eyewitness in a “detailed blow-by-blow chronological narrative” because “the officer’s testimony [was] in fact his own account of what [the witness] told him during a lengthy police interview.', 'general', 'Reyes v. United States', 'https://www.courtlistener.com/opinion/2194891/', '2194891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that “[a]lthough the exception allows the police to repeat discrete statements by an eyewitness, it does not permit the police to state on the stand what is, in effect, an
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the statements of a complainant were not admissible as excited utterances because there was insufficient indicia of reliability.', 'general', 'Reyes v. United States', 'https://www.courtlistener.com/opinion/2194891/', '2194891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we are satisfied that the trial court correctly evaluated the reliability of the statements by Coe, we conclude that the trial court did not abuse its discretion when it admitted Coe’s statements, through the testimony of Officer Dove, under the excited utterance exception to the hearsay rule.', 'general', 'Reyes v. United States', 'https://www.courtlistener.com/opinion/2194891/', '2194891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err, let alone plainly err, in this case because “when a declarant appears for cross-examination at trial, the Confrontation Clause places no constraints .', 'general', 'Reyes v. United States', 'https://www.courtlistener.com/opinion/2194891/', '2194891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we find that even
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that the declarant’s responses to the interviewing officer’s questions were not spontaneous because the nature of the questions required deliberative and thoughtful answers.', 'general', 'Reyes v. United States', 'https://www.courtlistener.com/opinion/2194891/', '2194891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Reyes v. United States', 'https://www.courtlistener.com/opinion/2194891/', '2194891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the trial court’s decision to allow statements made by the declarant that “described the men and their car in detail.', 'general', 'Reyes v. United States', 'https://www.courtlistener.com/opinion/2194891/', '2194891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm, and thus overrule Davis.', 'general', 'LeCompte v. State', 'https://www.courtlistener.com/opinion/2063923/', '2063923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that even if the admission of testimony about appellant’s drug use was error, the error was harmless in light of the special circumstances of this ease, most notably the appellant’s own, properly admitted statements, also in evidence, about his drug use at the time of the murder.', 'general', 'Settles v. United States', 'https://www.courtlistener.com/opinion/1975929/', '1975929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the prosecutor’s comments do not constitute a basis for reversing appellant’s convictions.', 'general', 'Settles v. United States', 'https://www.courtlistener.com/opinion/1975929/', '1975929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that, under the particular circumstances of this case, any error in admitting the evidence was harmless under the standard of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that the prosecutor’s comments attacking appellant’s credibility, which included referring to appellant as a “self-centered coward” whose explanations so contradicted each other that he “reminds you [the jury] of an octopus because .', 'general', 'Settles v. United States', 'https://www.courtlistener.com/opinion/1975929/', '1975929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'would not have been duplicative of other evidence before the jury, and we found that the trial court had acted within its discretion in concluding that the expert witness’s qualifications for making the proposed assertions had not been sufficiently established.', 'general', 'Settles v. United States', 'https://www.courtlistener.com/opinion/1975929/', '1975929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Settles v. United States', 'https://www.courtlistener.com/opinion/1975929/', '1975929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the trial court’s decision to exclude expert testimony that would have built on previously-admitted evidence of the victim’s PCP use by discussing the effects of PCP use on memory even though the expert had not spoken with the victim about her drug use and hence had “proffered no testimony about her personal reaction to PCP.', 'general', 'Settles v. United States', 'https://www.courtlistener.com/opinion/1975929/', '1975929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we conclude that defendant''s stop and arrest was proper without resting our decision on the constitutionality of the checkpoint.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Officer Falls did have reasonable articulable suspicion to stop defendant.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case at bar, we conclude that the checkpoint is reasonable, and thus conforms to the Fourth Amendment.', 'search_seizure', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Falls'' standing permission to set up checkpoints pursuant to Captain Jonas'' oral guidelines and Officer Falls'' call to his supervisor before creating the checkpoint at issue are constitutionally sufficient restraints to keep Falls from abusing his discretion.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and because the officers stopped all oncoming traffic at the checkpoint, we conclude that the checkpoint was constitutional.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the absence in Lidster of any focus on an issue dealing with supervisory permission and written guidelines indicates that these issues do not merit a constitutionally mandated reversal in a roadblock case such as the one sub judice.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the Court of Appeals as modified herein.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
