INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We hold that a motion presented *586 under WYO.', 'general', 'DeSpain v. State', 'https://www.courtlistener.com/opinion/1235283/', '1235283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that this claim [double jeopardy] may be raised for the first time on a motion for postconviction relief, * * * the relief sought via that motion is the correction of an illegal sentence * * *.', 'sentencing', 'DeSpain v. State', 'https://www.courtlistener.com/opinion/1235283/', '1235283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Brightman v. State', 'https://www.courtlistener.com/opinion/1238104/', '1238104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, given the limited conditions under which the Supreme Court has allowed on-reservation jurisdiction over member Indians, we find that the appellant has not established extraordinary circumstances with which to overcome "the right of reservation Indians to make their own laws and be ruled by them.', 'general', 'State v. Stone', 'https://www.courtlistener.com/opinion/1251928/', '1251928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Stone', 'https://www.courtlistener.com/opinion/1251928/', '1251928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/1253005/', '1253005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court based its decisions upon sufficient evidence.', 'general', 'Wetherelt v. State', 'https://www.courtlistener.com/opinion/1199782/', '1199782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Wetherelt v. State', 'https://www.courtlistener.com/opinion/1199782/', '1199782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Superior Court’s ruling did not deprive Lovett of his due process right to adequate trial preparation.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the trial court committed reversible error in allowing the prosecutor to reserve the bulk of his concluding arguments for his rebuttal summation.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we held that the police officer initiated discussions about the crimes involved there.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the circumstances of this case, including Lovett’s background, experience, and conduct, we conclude that the State met its burden in all respects as to both sets of Lovett’s statements.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the State has met its burden on the “voluntariness” prong of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the admission of Megee’s testimony concerning these statements did not violate Lovett’s Fifth or Sixth Amendment right to counsel.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these principles, we conclude that although the State’s bill of particulars mentioned only principal liability, Lovett was sufficiently put on notice prior to trial that he could be found guilty as an accomplice, and hence that the bill of particulars did not limit the State to proving that Lovett personally killed both Todd and Bull.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that evidence of Lovett’s plan to kill Bower was relevant to Lovett’s consciousness of guilt for the murders of Todd and Bull, and hence that the admission of this evidence did not violate D.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewed in the context of Lovett’s lengthy trial, we conclude that this comment did not affect the fairness of his trial.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence we conclude that he has not satisfied the test for reversal.', 'general', 'Lovett v. State', 'https://www.courtlistener.com/opinion/2064279/', '2064279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we hold that the exclusion of evidence of William’s eligibility for HUD assistance, on the basis of potential confusion under HRE Rule 403, constituted an abuse of discretion.', 'general', 'State v. Staley', 'https://www.courtlistener.com/opinion/1253024/', '1253024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, inasmuch as the circuit court’s error did not affect William’s substantial rights, we hold that it did not amount to plain error.', 'general', 'State v. Staley', 'https://www.courtlistener.com/opinion/1253024/', '1253024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that the circuit court’s failure to establish on the record that William’s decision not to testify was made knowingly and voluntarily constituted plain error.', 'general', 'State v. Staley', 'https://www.courtlistener.com/opinion/1253024/', '1253024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the time was properly excluded, and that the matter proceeded to trial within the time limits required by rule 8.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1164376/', '1164376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we find that appellant has failed to show that the trial court abused its discretion in granting the State’s motion for a continuance or that she was prejudiced thereby.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1164376/', '1164376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the investigating officer’s testimony did provide sufficient foundation for the admission of the bullets.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1164376/', '1164376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that sex offender registration is a collateral consequence of a guilty plea, counsel did not render ineffective assistance in not informing Ray, prior to entry of his plea, that he would be required to register as a sex offender.', 'plea', 'Ray v. State', 'https://www.courtlistener.com/opinion/1253053/', '1253053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that sex offender registration is a collateral consequence of a guilty plea.', 'plea', 'Ray v. State', 'https://www.courtlistener.com/opinion/1253053/', '1253053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, this Court held in State v.', 'general', 'Ray v. State', 'https://www.courtlistener.com/opinion/1253053/', '1253053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In holding that sex offender registration is a collateral, not direct, consequence of pleading guilty, we affirm the district judge’s denial of Ray’s post-conviction petition in this regard.', 'plea', 'Ray v. State', 'https://www.courtlistener.com/opinion/1253053/', '1253053') ON CONFLICT DO NOTHING;
