INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant cannot be required to pay restitution in an amount exceeding statutorily-prescribed monetary parameters of the crime to which he pleads guilty unless he voluntarily and intelligently agrees to pay a higher amount.', 'plea', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court could impose restitution as a proper condition of probation.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the trial court ordered an improper amount of restitution and erred in allowing the probation department to set the manner of payment.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only if one of these three statements are found in the record will we conclude that a defendant voluntarily and intelligently agreed to pay restitution in an amount exceeding statutorily-prescribed monetary parameters of the crime to which he pled guilty.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the Criminal Code, we conclude that the only statutes under which the trial court could have ordered restitution in this case are A.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
