INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that where a prosecuting attorney becomes aware that she or an associate had previously represented a defendant in a substantially related matter, the attorney has a duty to disclose this relationship to the court and defense counsel.', 'general', 'State v. Baker', 'https://www.courtlistener.com/opinion/2326931/', '2326931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that because the two matters were unrelated no presumption of confidential disclosure arose.', 'general', 'State v. Baker', 'https://www.courtlistener.com/opinion/2326931/', '2326931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Crepeault, we found that the two representations were "substantially related" because the prior case concerned the defendant''s parenting abilities and relationship with her children, and the later case involved sexual molestation of one of the children by that same defendant.', 'general', 'State v. Baker', 'https://www.courtlistener.com/opinion/2326931/', '2326931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instructions given in each case were erroneous.', 'jury_instruction', 'Comber v. United States', 'https://www.courtlistener.com/opinion/1909714/', '1909714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree with these contentions of instructional error, we reverse and remand for new trials.', 'general', 'Comber v. United States', 'https://www.courtlistener.com/opinion/1909714/', '1909714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that sex offender registration is a collateral consequence of a guilty plea, counsel did not render ineffective assistance in not informing Ray, prior to entry of his plea, that he would be required to register as a sex offender.', 'plea', 'Ray v. State', 'https://www.courtlistener.com/opinion/1253053/', '1253053') ON CONFLICT DO NOTHING;
