INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that the prior bad check convictions did not constitute the offense on trial a third offense under Code § 18.', 'general', 'Snead v. Commonwealth', 'https://www.courtlistener.com/opinion/1202152/', '1202152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence was sufficient to support the appellant’s conviction of an offense under Code § 18.', 'general', 'Snead v. Commonwealth', 'https://www.courtlistener.com/opinion/1202152/', '1202152') ON CONFLICT DO NOTHING;
