INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), this Court held that a four-level downward departure was warranted because of the defendant’s good works that were of a personal nature.', 'general', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8 Therefore, we conclude that the District Court did not commit any procedural error at Tomko’s sentencing.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the District Court did not abuse its discretion here.', 'general', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, in this case, given the Defendant’s lack of any significant criminal history, his involvement in exceptional charitable work and community activity, and his acceptance of responsibility, we find that a sentence that is mitigated by the factors of 3553[is] warranted.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only when we discern an abuse-of-discretion.', 'general', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because we conclude that this sentence is substantively unreasonable, we dissent.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewed cumulatively, we conclude that the relevant § 3553(a) factors advocate in *586the strongest possible terms for a sentence including a term of imprisonment.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To be clear, we acknowledge that § 3553(a)(3) and (7) arguably support certain aspects of the District Court’s lenient sentence, but we find it unnecessary to elaborate on these factors because we conclude that they are overpowered by § 3553(a)(1), (2), (4), (5), and (6), which advocate in the strongest possible terms for a sentence that includes some duration of imprisonment.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find it unnecessary to weigh in with our own cynical speculations as to the underlying motives of the authors of these letters, as we find that Tomko’s *585“support in the community” and “charitable work” simply do not justify the degree of variance that was granted in this case, especially because his negligible criminal history and employment record keep him squarely in the category of typical tax evaders.', 'general', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the sentence imposed by the District Court fails to reflect the seriousness of the offense, promote respect for the law, provide just punishment for the offense, and afford adequate deterrence to criminal conduct, and therefore is inconsistent with the sentencing goals outlined in § 3553(a)(2)(A)-(B).', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In ruling on the juvenile’s appeal, this court held that upon “[bjeing handcuffed and placed in the police car by the police officers, JDF was clearly in custody.', 'general', 'State v. Turner', 'https://www.courtlistener.com/opinion/1253121/', '1253121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our de novo review, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the judgment of conviction and remand for a new trial.', 'general', 'State v. Turner', 'https://www.courtlistener.com/opinion/1253121/', '1253121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree the best interest of the child can best be met by the husband, we affirm.', 'general', 'Wilker v. Wilker', 'https://www.courtlistener.com/opinion/1253126/', '1253126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that Kauffmann''s confessions were voluntary and were not obtained in violation of Miranda, we reverse the conviction and remand because we find that the statements made by the daughter were inadmissible hearsay.', 'general', 'Kauffmann v. Commonwealth', 'https://www.courtlistener.com/opinion/1200156/', '1200156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*284 Based on this, we find that the trial court properly denied the instruction on sexual battery.', 'general', 'Kauffmann v. Commonwealth', 'https://www.courtlistener.com/opinion/1200156/', '1200156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that, based on the record, the defense did not offer at trial an instruction on taking indecent liberties with a child.', 'general', 'Kauffmann v. Commonwealth', 'https://www.courtlistener.com/opinion/1200156/', '1200156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that absolute immunity does not apply to the advisement and discussion with the probation officer regarding preparation of the original petition for revocation.', 'general', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the prior Cooney opinion we held that all of a deputy county attorney''s activities entitled him to absolute immunity in the probationer''s civil rights action against him.', 'general', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the deputy county attorney''s challenged activities involved in the attempted revocation of the probationer''s probation were "intimately associated with the judicial phase of the criminal process and [were] functions to which the reasons for absolute immunity apply with full force.', 'general', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that procuring a perjured probation revocation petition, assisting the Wyoming Department of Probation and Parole and its probation officer, using the perjured probation revocation petition to obtain a bench warrant for the probationer''s arrest and causing the probationer to be arrested and detained in jail for thirty-eight days were the functional equivalent of the prosecutor''s role as an advocate in a criminal proceeding.', 'general', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nothing in Burns affects or casts doubt upon that part of our decision in Cooney in which we affirmed the trial court''s dismissal of the Cooneys'' claims alleging liability under the Wyoming Governmental Claims Act, Wyo.', 'dismissal', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
