INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that an appellate court''s function in a sentencing guidelines case is merely to review the reasons given to support departure and determine whether the trial court abused its discretion in finding those reasons "clear and convincing.', 'sentencing', 'State v. Mischler', 'https://www.courtlistener.com/opinion/1699817/', '1699817') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that lack of remorse to support a departure sentence cannot be inferred from either the mere exercise of a constitutional right or a continuing assertion of innocence.', 'sentencing', 'State v. Mischler', 'https://www.courtlistener.com/opinion/1699817/', '1699817') ON CONFLICT DO NOTHING;
