INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the context of a county grand jury, we hold that lack of jurisdiction on the part of the grand jury to make an inquiry may not be raised as a defense if the response to the objectionable question is allegedly false.', 'general', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 13-2703(A), and, therefore, need not prove the propriety of its inquiry, we hold that a defendant charged with the crime of false swearing may not raise at trial the defense of lack of jurisdiction on the part of the grand jury.', 'general', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that rule 12.', 'general', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the scope of the statute is substantially and constitutionally curtailed.', 'general', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not abuse its discretion when it denied the motion to dismiss on this ground.', 'dismissal', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the definition of statement contained in A.', 'general', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the challenged provisions are constitutionally precise and reach no further than is necessary to fulfill their functions.', 'general', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court''s ruling on Franzi''s motion to dismiss on the above ground was not an abuse of discretion.', 'dismissal', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '("All parties were aware of the basis for the indictment, and we find that its form was sufficient.', 'general', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not abuse its discretion in its ruling on Franzi''s motion to dismiss.', 'dismissal', 'Franzi v. Superior Court of Arizona', 'https://www.courtlistener.com/opinion/1254617/', '1254617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the language of the Holder instruction is to be applied only at the trial level, and is not an appellate standard of review.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Holder, we held that when guilt is proven by circumstantial evidence, the jury must be instructed to accept any reasonable explanation pointing to the defendant’s innocence.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Randles, we held that the Holder standard does not apply on review.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In considering these factors, we conclude that the studies used by the experts possessed sufficient indicia of- reliability to meet the I.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our standard of review for matters involving judicial discretion, we conclude that the district court did not abuse its discretion by admitting expert testimony based on these studies.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the record we find that the jury’s verdict was not without a basis in fact or reason.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that Dr.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since this *649Court will not presume error, we affirm the district court’s sentence.', 'sentencing', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the justice court’s decisions that McDermott voluntarily entered her guilty plea and that she did not demonstrate that it would be manifestly unjust to deny her request to withdraw her guilty plea were reasonable.', 'plea', 'State v. McDermott', 'https://www.courtlistener.com/opinion/1166706/', '1166706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the plea agreement, we conclude that it substantively complied with W.', 'plea', 'State v. McDermott', 'https://www.courtlistener.com/opinion/1166706/', '1166706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. McDermott', 'https://www.courtlistener.com/opinion/1166706/', '1166706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did and order a new trial.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he was entitled to the instruction.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the willful blindness instruction is inconsistent with North Carolina law, and thus the trial court erred in giving such an instruction to the jury.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the error in giving the willful blindness instruction entitles defendant to a new trial.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Townsend''s testimony was competent evidence of defendant''s character for the relevant trait of law-abidingness, we hold that defendant was entitled to an instruction on his character trait of law-abidingness as substantive evidence of his innocence.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the traits of truthfulness and honesty are not "pertinent" character traits to the crime of trafficking in marijuana by possession or transportation.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that testimony of defendant and of the police officers of defendant''s absence of convictions was not admissible as substantive evidence of defendant''s innocence, not only because it was not in the proper form, but also for the reason that evidence of the lack of prior convictions is not evidence of a "trait of character" but is merely evidence of a fact.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence of a lack of convictions should not have been admitted as character evidence.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the error in instructing the jury on defendant''s willful blindness, the verdict and judgment of the trial court are vacated, and we reverse the decision of the Court of Appeals and remand the case to the Court of Appeals for further remand to the Superior Court, Northampton County, for a new trial.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'PRICEWATERHOUSECOOPERS LLP v. Cedar Resources, Inc.', 'https://www.courtlistener.com/opinion/1771050/', '1771050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, venue is not proper in Pinellas County, and we reverse the order denying the motion to transfer venue.', 'general', 'PRICEWATERHOUSECOOPERS LLP v. Cedar Resources, Inc.', 'https://www.courtlistener.com/opinion/1771050/', '1771050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the limited nature of the questions permitted by the trial court fall within the parameters of Rule 608(b).', 'general', 'State v. Larrimore', 'https://www.courtlistener.com/opinion/1253134/', '1253134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the argument in the instant case is analogous to the argument cited in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that only first-degree murder should have been submitted.', 'general', 'State v. Larrimore', 'https://www.courtlistener.com/opinion/1253134/', '1253134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 799 (1983), this Court held that a trial court is not required to give repeatedly a full, formal rendition of the mandates found in N.', 'general', 'State v. Larrimore', 'https://www.courtlistener.com/opinion/1253134/', '1253134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that arguments designed to convince the jury to convict a defendant due to public sentiment against crime were improper.', 'general', 'State v. Larrimore', 'https://www.courtlistener.com/opinion/1253134/', '1253134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though defendant himself did not attend the conferences in this case, we conclude that the trial court’s bench conferences with defense counsel and counsel for the State did not violate defendant’s state constitutional right to be present at all stages of his trial.', 'general', 'State v. Larrimore', 'https://www.courtlistener.com/opinion/1253134/', '1253134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the defendant’s closing arguments, we conclude that the prosecutor in this instance was responding to assertions made by the defendant.', 'general', 'State v. Larrimore', 'https://www.courtlistener.com/opinion/1253134/', '1253134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the totality of the arguments to which the defendant assigns error, we find that the trial court did not abuse its discretion in handling these arguments.', 'general', 'State v. Larrimore', 'https://www.courtlistener.com/opinion/1253134/', '1253134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the arrest of appellant was valid and that the seizure of evidence incident to that lawful arrest was proper.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence seized was not the fruit of an illegal arrest.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of the instant case, we hold that the trial court did not abuse its discretion in admitting the pellet gun into evidence.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the entire record, we hold that the prosecutor’s improper comments were not grounds for reversal.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the sentence imposed upon appellant did not constitute cruel and unusual punishment.', 'sentencing', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that Article I, Section 11 of our State Constitution was not a self-executing provision.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 448 (1978), we held that the excessive use of hearsay in the grand jury violated defendant’s due process right.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 517 (1978), we held that due process is not violated by the prosecutor’s failure to present exculpatory evidence to the grand jury.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1383 (1980), we held that the failure of prosecutor to instruct the grand jurors of a lesser included offense did not violate due process.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that reversal is required only when the language used in the statement was “manifestly intended or was of such character that the jury would naturally and necessarily take it to be a comment on the failure of the accused to testify.', 'general', 'State v. Melear', 'https://www.courtlistener.com/opinion/1166939/', '1166939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we hold that it is not, and therefore, we reverse the decision of the Court of Appeals as to that issue.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1311891/', '1311891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that inoperability of a “handgun or other firearm” is not an affirmative defense to a charge of possession of a firearm by a felon under N.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1311891/', '1311891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the facts of this case, we conclude that the trial judge did not abuse his discretion by failing to order a mistrial after he had given the curative instruction.', 'mistrial', 'State v. Lynn', 'https://www.courtlistener.com/opinion/1302156/', '1302156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that where an accused has been arrested and interrogated by the police and has not been specifically advised by a court or by his own counsel that he has the constitu
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that they may not.', 'general', 'State Ex Rel. McLeod v. Crowe', 'https://www.courtlistener.com/opinion/1248005/', '1248005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do this because we conclude that the jury should not have been instructed on felony murder.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the possible inconsistency between Hansen’s conviction for second-degree arson and Krus’s conviction for first-degree arson, even assuming that Hansen’s failure to object was not tactical, we conclude that Hansen has not shown plain error.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the context of the State’s evidence at grand jury, we conclude that this evidence would not have appreciably affected the grand jury’s decision to indict Hansen for arson.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, given the absence of any evidence indicating that Hansen did not intend to help Krus commit arson, we conclude that any infirmity in the grand jury instructions was not plain error.', 'jury_instruction', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these other instructions, we conclude that the concept of complicity was adequately communicated to the trial jury;', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we conclude that the instructions adequately communicated the concept that the jury should not convict Hansen as an accomplice to arson unless they were convinced that Hansen desired to see the arson succeed and that he performed acts in furtherance of this desire.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that reasonable judges could differ on the question of verdict inconsistency, and thus Hansen has not established plain error.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Hansen’s second-degree murder conviction;', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse Hansen’s conviction for second-degree murder.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm his second-degree arson conviction.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1202052/', '1202052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that state and municipal prohibitions against discrimination based on marital status protect the rights of unmarried couples.', 'general', 'Foreman v. Anchorage Equal Rights Commission', 'https://www.courtlistener.com/opinion/1167636/', '1167636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that giving part (4) of the jury instruction on negligent entrustment was reversible error.', 'jury_instruction', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that an assailant convicted of manslaughter for shooting and killing his victim was barred from recovering from the manufacturer or seller of the gun for direct personal losses allegedly resulting from the shooting.', 'general', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Because we conclude that the superior court erroneously instructed the jury on the elements of negligent entrustment, we reverse and remand for a new trial.', 'general', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a legitimate factual dispute existed, we conclude that the trial court’s denial of summary judgment on the issue of whether Normandy was negligent per se was not error.', 'general', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the court’s erroneous instructions warrant a remand, we must consider Normandy''s three arguments on cross-appeal.', 'general', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the superior court did not abuse its discretion in allowing Ar-dinger to amend the complaint.', 'general', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was a legitimate factual dispute about whether Normandy permitted Joshua to drive the car, we conclude that a directed verdict would have been premature.', 'general', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the superior court committed reversible error in its instructions on the standard of care, negligence per se, and negligent entrustment.', 'general', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we REVERSE and REMAND to the superior court.', 'general', 'Ardinger v. Hummell', 'https://www.courtlistener.com/opinion/1253168/', '1253168') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Segovia v. Texas Department of Protective & Regulatory Services', 'https://www.courtlistener.com/opinion/2416718/', '2416718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'Segovia v. Texas Department of Protective & Regulatory Services', 'https://www.courtlistener.com/opinion/2416718/', '2416718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ludwick v. This Minute of Carolina, Inc.', 'https://www.courtlistener.com/opinion/1200376/', '1200376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Simmons v. State', 'https://www.courtlistener.com/opinion/1254570/', '1254570') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the applicability of the felony-murder doctrine is triggered only when the death of another results during the commission or attempted commission of the seven felonies enumerated in Ind.', 'general', 'Head v. State', 'https://www.courtlistener.com/opinion/1978579/', '1978579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of these circumstances, including the fact that the victim had not been informed that a suspect was present, we conclude that Roger''s identification was not the product of an unduly suggestive photographic display.', 'general', 'Head v. State', 'https://www.courtlistener.com/opinion/1978579/', '1978579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these various circumstances, including the ample opportunity which Koger had to view the perpetrator, we conclude that his in-court identification was based on observations gained independently of the suggestive pretrial confrontation.', 'general', 'Head v. State', 'https://www.courtlistener.com/opinion/1978579/', '1978579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as the photographic identification and in-court identification were properly admitted and were unequivocal in nature, we conclude that the admission of the pretrial identification obtained via the confrontation, although improper, was harmless beyond a reasonable doubt.', 'general', 'Head v. State', 'https://www.courtlistener.com/opinion/1978579/', '1978579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that McReynolds has failed to establish his entrapment claim by a preponderance of the evidence.', 'general', 'McReynolds v. State', 'https://www.courtlistener.com/opinion/1304316/', '1304316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in light of the mitigating factors established in the record, a sentence of five years with one year suspended is clearly mistaken.', 'sentencing', 'McReynolds v. State', 'https://www.courtlistener.com/opinion/1304316/', '1304316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the issue has not been adequately preserved, and, on this basis, we decline to rule on it.', 'general', 'McReynolds v. State', 'https://www.courtlistener.com/opinion/1304316/', '1304316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction but reverse the sentence.', 'sentencing', 'McReynolds v. State', 'https://www.courtlistener.com/opinion/1304316/', '1304316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the district court found Holkesvig in contempt and imposed a remedial sanction without holding a hearing to which Holkesvig was statutorily entitled, we reverse the order and remand for further proceedings.', 'general', 'State v. Hayes', 'https://www.courtlistener.com/opinion/899134/', '899134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶13]	Because Holkesvig did not receive a hearing on the contempt motion, we reverse and remand for that purpose.', 'general', 'State v. Hayes', 'https://www.courtlistener.com/opinion/899134/', '899134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶14]	We reverse the order and remand for the moving party to schedule and notice a hearing.', 'general', 'State v. Hayes', 'https://www.courtlistener.com/opinion/899134/', '899134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the amended judgment in 
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, Holkesvig did not challenge the injunctive order in the prior appeal, and we affirmed that order in 
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the State presented substantial evidence of defendant''s intentional, willful, and wanton violation of the ordinance.', 'general', 'State v. Powell', 'https://www.courtlistener.com/opinion/1307857/', '1307857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'Dunn v. State', 'https://www.courtlistener.com/opinion/1201215/', '1201215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering these factors individually, we find this case analogous to other cases in which this Court held that a defendant was not deprived of counsel due to hybrid representation.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2003), this Court held that where harmless error or no reversible error is found, it will determine “whether such error or errors, although not reversible when standing alone, may when considered cumulatively require reversal because of the resulting cumulative prejudicial effect.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court failed to comply in the strictest technical sense with Rule 9.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this exchange reveals both misunderstanding and knowledge on Hearn’s part.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Hearn’s behavior at trial only reflected Dr.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we find that Hearn was never without the assistance of counsel.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that there was no need for a waiver instruction.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Section 41-21-97 creates an exception to Section 73-31-29 where a patient makes threats of physical violence.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not err in denying Hearn’s insanity instructions because the evidence was insufficient to create a reasonable doubt of sanity.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was sufficient evidence for a rational trier of fact to find beyond a reasonable doubt that Hearn had threatened a judge.', 'general', 'Hearn v. State', 'https://www.courtlistener.com/opinion/1599683/', '1599683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given Lee’s repeated equivocations about his ability to recommend the death penalty, along with his expressed concern about following the law of the State of North Carolina, we hold that the trial court did not abuse its discretion in excusing him for cause.', 'general', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Since Payton unequivocally stated that she could not recommend the death penalty for this defendant, we hold that the trial court properly granted the State’s challenge for cause.', 'general', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result we hold that the trial court did not err in refusing to give defendant’s requested preselection instruction.', 'general', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering defendant’s claim, we hold that the trial court did not err in overruling defendant’s objection.', 'general', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant waived his right to a week’s interlude between his arraignment and trial, and the trial court did not err in proceeding to trial immediately.', 'general', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that nothing in counsel’s opening statement alleged by defend
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that this instruction is proper and did not impermissibly usurp the jury’s fact-finding role.', 'general', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion by excluding such evidence from the sentencing jury’s consideration and that defendant has failed to show ineffective assistance of counsel.', 'sentencing', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In keeping with our precedent, we hold that this argument was not grossly improper.', 'general', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After close consideration of each statement defendant claims was speculation, we hold that the trial court did not err.', 'general', 'State v. Roache', 'https://www.courtlistener.com/opinion/1266373/', '1266373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that in the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that reckless driving is not a lesser included offense of felony DUI, and we affirm the trial judge''s refusal of Cribb''s requested charge.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 98 (1992), this Court held that a judge''s exclusion of evidence, based on a chain of custody similar to the one presented here, was within his sound discretion.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial judge abused his discretion in admitting the blood alcohol test.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] Accordingly, we find that section 56-5-2950(a) is inapplicable to this case because Cribb was not arrested until some time after the blood alcohol test.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the issue before us, we find that felony DUI, the greater offense, does not contain all the elements of reckless driving, the lesser offense.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that the trial judge was correct in ruling that section 56-5-2950 is inapplicable to pre-arrest DUI investigations and that reckless driving is not a lesser included offense of felony DUI.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when, as here, the defendants have substantially similar interests, it is not an abuse of discretion to limit the defense to one peremptory challenge.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/1265624/', '1265624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we affirm the superior court’s decision.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/1265624/', '1265624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we hold that the trial court’s findings of fact are not supported by competent evidence and do not in turn support the conclusions of law in this order.', 'general', 'State v. Phair', 'https://www.courtlistener.com/opinion/1212300/', '1212300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the orders and arguments, we reverse both orders.', 'general', 'State v. Phair', 'https://www.courtlistener.com/opinion/1212300/', '1212300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse this order.', 'general', 'State v. Phair', 'https://www.courtlistener.com/opinion/1212300/', '1212300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse it.', 'general', 'State v. Phair', 'https://www.courtlistener.com/opinion/1212300/', '1212300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court’s orders are in error, we reverse both convictions for contempt against defendant.', 'general', 'State v. Phair', 'https://www.courtlistener.com/opinion/1212300/', '1212300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we reverse on these grounds, we do not address the remainder of defendant’s arguments.', 'general', 'State v. Phair', 'https://www.courtlistener.com/opinion/1212300/', '1212300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'a decision also being issued today, we hold that the failure to warn a person of the ASORA registration requirement when a person enters a plea to a sex offense may establish manifest injustice for purposes of Criminal Rule 11(c)(3).', 'plea', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the duties imposed on a sex offender by ASORA are not analogous to the supervision of a defendant’s conduct imposed by incarceration, parole, or probation.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the placement of ASORA — a byproduct of a sex offender’s conviction — in Title 12 does not indicate that the legislature had a punitive intent.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute, read with the legislative findings, does not reflect a punitive legislative intent.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that Patterson has not shown a punitive legislative intent, Patterson may still show that the effect of the regulatory statute is so severe that ASO-RA is punishment.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Patterson has not provided any compelling reason or authority to show that ASORA violates an implied right of privacy based on the federal constitution.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the legislature’s expressed interest in public safety, we conclude that Patterson’s assumed subjective expectation of privacy in the biographical information released pursuant to ASORA must yield to society’s public safety interest.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that ASORA does not violate Patterson’s right to privacy under article I, section 22, of the Alaska Constitution.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because ASORA, as presently before us, does not require any administrative adjudication, we conclude that Patterson has not been deprived of procedural due process and that ASORA is not fundamentally unfair.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Patterson’s equal protection attack fails because he has not shown or argued that convicted sex offenders are treated differently than any similarly situated group.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/1264714/', '1264714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s judgment dismissing Count I of Savage’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that absent extraordinary circumstances, courts should apply the calculation methodology of Rule 90.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “a court must consider the best interests of the children by applying the criteria in AS 25.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that the superior court made several erroneous factual findings regarding Linda’s credibility, we conclude that these errors were not prejudicial.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court did not clearly err with respect to its findings regarding Linda’s disciplinary methods, Robert’s presence at home when Linda and Jea-na lived with Robert, and Robert’s refusal to pay for day care.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 Although we conclude that the court clearly erred in finding that Linda made false or misleading statements regarding her current alcohol consumption and her allegation that Robert stalked her,4 these errors were harmless given the remaining findings bearing on Linda’s credibility.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the erroneous findings of wrongful conduct and custodial interference influenced and invalidated the superior court’s conclusion that Linda had failed to foster a healthy relationship between Jeana and Robert and would continue to do so in the future.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these rulings were permissible and reveal no partiality or bias.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the standard announced in House, 779 P.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the “decision of the family to move to [California] was based upon a valid reason, that is, a reason which was not primarily motivated by a desire to make visitation .', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we reverse the custody award because the court erroneously weighed the statutory factors.', 'general', 'Vachon v. Pugliese', 'https://www.courtlistener.com/opinion/1169730/', '1169730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Compton v. State', 'https://www.courtlistener.com/opinion/1169808/', '1169808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the proffered evidence was inadmissible as an attempt to prove defendant’s diminished capacity.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we hold that the trial court did not err by precluding Dr.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not abuse its discretion in admitting evidence of defendant’s prior acts.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court erred in excluding the proffered testimony because it was relevant to the defendant’s “mere presence” defense and provided the jury with information essential to the assessment of credibility.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This was dicta, however, as we held that it was not fundamental error for the trial court not to give a proximate cause instruction sua sponte when causation was not at issue in the trial.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Christensen, this court held that to challenge the element of premeditation, a psychology expert could testify that the defendant reacted impulsively to stress.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 297, 303 (1983), this court held that an instruction stating that the defendant would not be subject to the death penalty should not have been given.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that defendant has not waived her claim that the trial court erred by precluding the proffered testimony.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court’s admission of this evidence was not an abuse of discretion.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the jury reasonably could have concluded that defendant committed the alleged acts.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That rejection, we should note, was not based on any evidentiary offer or formal objection raising the issue on which the majority today decides the case: "We hold that the proffered evidence was inadmissible as an attempt to prove defendant’s diminished capacity.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the conviction in Gonzales, not because we were establishing the diminished capacity defense but because “the trial court’s exclusion of the testimony effectively precluded the defendant from introducing evidence essential” to his mere presence defense.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of these circumstances, we hold that the matter must be remanded to the district court for the purpose of developing the facts concerning Ravin’s arrest and circumstances of his possession of marijuana.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that such a fundamental right is shown by virtue of the analysis we employed in Breese.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that citizens of the State of Alaska have a basic right to privacy in their homes under Alaska’s constitution.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that no adequate justification for the state’s intrusion into the citizen’s right to privacy by its prohibition of possession of marijuana by an adult for personal consumption in the home has been shown.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that hairstyles are a highly personal matter in which the individual is traditionally, autonomous, we concluded that governmental control of personal appearance would be antithetical to the concept of personal liberty under Alaska’s constitution.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the student would be forced to choose between controlling his own personal appearance and asserting his right to an education if the regulations were upheld, we concluded that the constitutional language quoted above embodied an affirmative grant of liberty to public school students to choose their own hairstyles, for “at the core of [the concept of liberty] is the notion of total personal immunity from government control: the right ‘to be let alone.', 'general', 'Ravin v. State', 'https://www.courtlistener.com/opinion/1170252/', '1170252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not err in submitting this circumstance to the jury.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant received a fair trial and capital sentencing proceeding free from prejudicial error.', 'sentencing', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we conclude that the jury selection, guilt-innocence phase, and sentencing proceeding of defendant’s trial were free from prejudicial error and that the death sentence is not disproportionate.', 'sentencing', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason we conclude that the trial court did not abuse its discretion in sustaining the objection.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has failed to show any prejudicial error.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case we conclude that the questions asking prospective juror Bryant whether he could think of any situation where he could vote to impose a sentence other than death for first-degree murder were an impermissible attempt to determine what kind of verdict he would render under certain circumstances.', 'sentencing', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient to support a verdict of guilty of first-degree murder based on premeditation and deliberation.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s instruction on malice did not constitute error, much less plain error.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has failed to show any error, much less plain error, in the trial court’s instruction on malice.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has failed to show any plain error in the trial court’s instruction on premeditation and deliberation.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1267203/', '1267203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pierce, supra, this Court held that S.', 'general', 'State v. Drayton', 'https://www.courtlistener.com/opinion/1311522/', '1311522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Drayton', 'https://www.courtlistener.com/opinion/1311522/', '1311522') ON CONFLICT DO NOTHING;
