INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prejudice was corrected by this instruction.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Merriman''s due process rights under the South Carolina Constitution and United States Constitution were not infringed upon by the trial judge''s refusal to disqualify Hogg as a witness.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Since the polygraph results would have been cumulative to evidence already before the jury, we hold that exclusion of the test was not material to the jury''s verdict.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our prior opinion, we held that this statute, a reception of 5 Eliz.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Section 16-9-10 was, insofar as it prohibits the testimony of a convicted perjuror, repealed by implication upon the enactment of Section 19-11-60.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, for these purposes, the credit card number is the “credit card.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1264876/', '1264876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that possession of a credit card number itself is sufficient to sus
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained above, we conclude that a credit card account number is a “device” for obtaining goods or services on credit.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1264876/', '1264876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Fortunately, we conclude that we need not resolve Morgan’s double jeopardy claim because the issue is not yet ripe.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1264876/', '1264876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to several dictionaries in common use, we find that the word “device” is not limited to physical objects.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1264876/', '1264876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the definition of “credit card” contained in AS 11.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1264876/', '1264876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the case must be remanded for a further evidentiary hearing concerning the circumstances surrounding the loss or destruction of the tapes.', 'general', 'Putnam v. State', 'https://www.courtlistener.com/opinion/1272004/', '1272004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this rule to the case at bar, we conclude that Investigator Hildreth''s testimony concerning the character of these hearsay declarants was within the bounds of permissible evidence.', 'general', 'Putnam v. State', 'https://www.courtlistener.com/opinion/1272004/', '1272004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that when hearsay evidence has been presented to a grand jury, character evidence concerning the hearsay declarant''s credibility is permissible to the same extent to which it would be permissible at trial had the declarant''s character been challenged.', 'general', 'Putnam v. State', 'https://www.courtlistener.com/opinion/1272004/', '1272004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1259428/', '1259428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the negligent homicide statute, W.', 'general', 'Myers v. Murensky', 'https://www.courtlistener.com/opinion/1261991/', '1261991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[26] Accordingly, we hold that the provision in West Virginia Code § 61-3-24d [defining the crime of larceny by fraudulent scheme] found in subsection (c), which reads, "A violation of law may be prosecuted under this section notwithstanding any other provision *920 of this code," does not express a clear legislative intent to create a separate and distinct offense, with separate, additional punishment for the same acts.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing statutory comparison, we hold that every element necessary for a larceny conviction under West Virginia Code § 61-3-24 (false pretenses) is also an element for a larceny conviction under West Virginia Code § 61-3-24d (fraudulent scheme).', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing statutory comparison, we hold that, in the absence of proof that a defendant obtained "services" by a fraudulent scheme, every element necessary for a conviction of larceny by fraudulent scheme under West Virginia Code § 61-3-24d is also an element for conviction of an agent or employee for larceny by embezzlement under West Virginia Code § 61-3-20.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '13 (1998), wherein we held that "[a]lleged errors of a constitutional magnitude will generally trigger a review by this Court under the plain error doctrine.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of these arguments in conjunction with the record, we conclude that two of the convictions constitute multiple convictions and sentences for the same acts which violated double jeopardy protections.', 'sentencing', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the jury might properly find Appellant guilty of a single act of larceny with regard to the property of Elkins.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[38] We conclude that the jury might properly find Appellant guilty of a single act of larceny of the property of Micro Vane.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand this case for new orders of conviction and sentencing consistent with this opinion.', 'sentencing', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that Reese was prejudiced by the solicitor''s improper Golden Rule argument since the question of malice was in contention.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1264694/', '1264694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals holding that Reese was entitled to an involuntary manslaughter instruction.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1264694/', '1264694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1264694/', '1264694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Court of Appeals'' decision reversing Reese''s conviction and remanding the case for a new trial.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1264694/', '1264694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is.', 'general', 'Pears v. State', 'https://www.courtlistener.com/opinion/1172773/', '1172773') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence is clearly mistaken and direct that this case be REMANDED to the superior court so that a sentence consistent with this opinion may be imposed.', 'sentencing', 'Pears v. State', 'https://www.courtlistener.com/opinion/1172773/', '1172773') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'Howard v. Roberson', 'https://www.courtlistener.com/opinion/1268420/', '1268420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1273781/', '1273781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed and held the petitioner had satisfied the prejudice prong when "the only evidence in the record on this point *98 [was] petitioner''s own testimony that had trial counsel not misinformed him that he would face a potential life sentence if he proceeded to trial, he would not have pled guilty.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1273781/', '1273781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, appellant’s conviction and sentence are affirmed, and we hold that the ordinance of the City of Phoenix § 23-52 is constitutional.', 'sentencing', 'State v. Loughran', 'https://www.courtlistener.com/opinion/1172928/', '1172928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, applying this definition to the statute, we hold that the offense of child abuse creating a risk of injury as set forth in W.', 'general', 'State v. Snodgrass', 'https://www.courtlistener.com/opinion/1273702/', '1273702') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Barnette’s testimony was crucial to the appellant’s theory of the case, and thus, we find that the circuit court erred by refusing to allow him to testify.', 'general', 'State v. Snodgrass', 'https://www.courtlistener.com/opinion/1273702/', '1273702') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the final order of the circuit court and remand this case for a new trial.', 'general', 'State v. Snodgrass', 'https://www.courtlistener.com/opinion/1273702/', '1273702') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the evidence presented, we hold that these facts could lead a reasonable mind to the conclusion that the defendant was sane at the time he committed the crime.', 'general', 'State v. Clabourne', 'https://www.courtlistener.com/opinion/1173351/', '1173351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the photographs were admissible.', 'general', 'State v. Clabourne', 'https://www.courtlistener.com/opinion/1173351/', '1173351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the record does not reflect the requisite bias, we find that the judge’s refusal to strike these jurors was proper.', 'general', 'State v. Clabourne', 'https://www.courtlistener.com/opinion/1173351/', '1173351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the killing was committed in a heinous and depraved manner.', 'general', 'State v. Clabourne', 'https://www.courtlistener.com/opinion/1173351/', '1173351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Clabourne', 'https://www.courtlistener.com/opinion/1173351/', '1173351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking all of these factors together, we conclude that Koenig was properly given an aggravated sentence.', 'sentencing', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1268860/', '1268860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reason, we reverse Judge Hanson’s conclusion that he was obligated to give consecutive sentences to Koenig.', 'sentencing', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1268860/', '1268860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1268860/', '1268860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'McNair, supra, this court held that it was not cruel or unusual to impose a life sentence pursuant to A.', 'sentencing', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming, arguendo, that appellant was entitled to an instruction on self-defense, we conclude that this was harmless error in view of the jury’s verdict that appellant was guilty of the burglary charge.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming without deciding that a presumption of prosecutorial vindictiveness was triggered in this case, we conclude that the presumption has been rebutted, at least on the facts of this case.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Mulalley, supra, we concluded that there was a rational basis for the imposition of this same sentence for dangerous assaults by prisoners while in custody.', 'sentencing', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of any prejudice, we find that the error in the indictment was a technical defect amendable upon the state’s motion under 17 A.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the gravity of the offense, we find that appellant’s crimes were very serious.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 225, 227 (1971), we found that Miranda warnings could be renewed at an interrogation two hours after the original warnings by asking the accused if he had been advised of his constitutional rights.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a probation officer i.', 'general', 'Hulsman v. Hemmeter Development Corp.', 'https://www.courtlistener.com/opinion/1173496/', '1173496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since a probation officer is entitled to absolute judicial immunity in the preparation, investigation and submission of a pre-sentece report, accordingly, we hold that the State of Hawaii, as the employer of probation officer Hernandez, is immune from liability for the alleged negligence of its employees based on the doctrine of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further support for our position is found in an analogous situation wherein we held that court-appointed psychiatrists were en-tided to absolute judicial immunity, even if negligent.', 'general', 'Hulsman v. Hemmeter Development Corp.', 'https://www.courtlistener.com/opinion/1173496/', '1173496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the federal statutes regulating firearm sales did not create a duty on a seller in a negligence action nor did it create a private right of action for damages.', 'general', 'Hulsman v. Hemmeter Development Corp.', 'https://www.courtlistener.com/opinion/1173496/', '1173496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the record submitted to us along with the applicable law, we affirm the judgment of the circuit court.', 'general', 'Hulsman v. Hemmeter Development Corp.', 'https://www.courtlistener.com/opinion/1173496/', '1173496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the double jeopardy proscriptions of our federal and state constitutions did not themselves bar continued prosecution, we affirm because we do not view the trial court’s action to have been an unjustified exercise of implicit powers.', 'general', 'State v. Moriwake', 'https://www.courtlistener.com/opinion/1173634/', '1173634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that subsection (f)’s requirement that findings “be set out with specificity” calls for sentencing judges to include, in their remarks on the record, the following specific information: (1) the specific factors in aggravation and in mitigation found to have been established by clear and convincing evidence;', 'sentencing', 'Linn v. State', 'https://www.courtlistener.com/opinion/1173927/', '1173927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), where we held that normally a first offender should receive a substantially more favorable sentence then the presumptive sentence for a second offender.', 'sentencing', 'Brezenoff v. State', 'https://www.courtlistener.com/opinion/1173998/', '1173998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the sentence but direct further proceedings regarding restitution.', 'sentencing', 'Brezenoff v. State', 'https://www.courtlistener.com/opinion/1173998/', '1173998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', in which we held that the disorderly conduct statute could apply to a threatening communication from a student to a teacher.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute may be applied to such conduct.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that the disorderly conduct statute requires, at a minimum, that, when the conduct tends to cause or provoke a disturbance that is private or personal in nature, there must exist the real possibility that this disturbance will spill over and cause a threat to the surrounding community as well.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this analysis, we conclude that the disorderly conduct statute was appropriately applied to *24 Schwebke''s conduct in this case.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we conclude that the application of the disorderly conduct statute in this case was appropriate.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, even though the conduct involved a private interaction between the teacher and student, the disorderly conduct statute could apply, not because it caused the teacher to become upset, but instead because the threat jeopardized the proper functioning of the school itself, which was regarded as a threat to public order.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals'' decision.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we affirm the court of appeals'' decision to uphold the convictions of Schwebke.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Arabie’s conduct did not amount to burglary under AS 11.', 'general', 'Arabie v. State', 'https://www.courtlistener.com/opinion/1174699/', '1174699') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the element of malice under MCL 750.', 'general', 'People v. Henderson', 'https://www.courtlistener.com/opinion/1283640/', '1283640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that MCL 750.', 'general', 'People v. Henderson', 'https://www.courtlistener.com/opinion/1283640/', '1283640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Considered as a whole, we find that the trial court’s instructions properly conveyed the element of malice to the jury.', 'general', 'People v. Henderson', 'https://www.courtlistener.com/opinion/1283640/', '1283640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the law of our sister states for guidance, we find that many have provisions specifically defining “torture” as the term relates to their animal offense statutes.', 'general', 'People v. Henderson', 'https://www.courtlistener.com/opinion/1283640/', '1283640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and reinstate the charges against both defendants.', 'general', 'People v. Henderson', 'https://www.courtlistener.com/opinion/1283640/', '1283640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse that order as well.', 'general', 'People v. Henderson', 'https://www.courtlistener.com/opinion/1283640/', '1283640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Rosemond', 'https://www.courtlistener.com/opinion/1261934/', '1261934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the lower court did not err in admitting evidence of Barker’s prior DUI convictions.', 'general', 'State v. Barker', 'https://www.courtlistener.com/opinion/1272503/', '1272503') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we find the results of the Horizontal Gaze Nystagmus test should have been excluded, and we reverse the judgment of the Circuit Court of Wood County and remand for further proceedings.', 'general', 'State v. Barker', 'https://www.courtlistener.com/opinion/1272503/', '1272503') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse on the issue of the HGN test, we do not address the merits of this argument.', 'general', 'State v. Barker', 'https://www.courtlistener.com/opinion/1272503/', '1272503') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court correctly denied McAttee''s motion to suppress.', 'suppression', 'State v. McAttee', 'https://www.courtlistener.com/opinion/1274675/', '1274675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'accordingly, we affirm.', 'general', 'State v. McAttee', 'https://www.courtlistener.com/opinion/1274675/', '1274675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'error in the circuit court’s denial of Johnson’s motion to suppress, and we affirm the circuit
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this conduct was not sufficient to put defendants on notice that Muller would make false, defamatory statements on the air if WRCX and Evergreen hired him.', 'general', 'Van Horne v. Muller', 'https://www.courtlistener.com/opinion/1998695/', '1998695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that plaintiff’s allegations in this case are insufficient to state a cause of action against WRCX or Evergreen for negligent hiring or retention of Muller.', 'general', 'Van Horne v. Muller', 'https://www.courtlistener.com/opinion/1998695/', '1998695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that plaintiffs allegations are insufficient, as a matter of law, to impose liability on WRCX and Evergreen under a theory of negligent hiring or retention of Muller.', 'general', 'Van Horne v. Muller', 'https://www.courtlistener.com/opinion/1998695/', '1998695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the appellate court holding reversing the dismissal of counts V VI, VII, and VIII of plaintiffs complaint.', 'dismissal', 'Van Horne v. Muller', 'https://www.courtlistener.com/opinion/1998695/', '1998695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the appellate court holding reversing the dismissal of count II of plaintiffs complaint.', 'dismissal', 'Van Horne v. Muller', 'https://www.courtlistener.com/opinion/1998695/', '1998695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the circuit court erred in dismissing count II for failure to state a cause of action.', 'dismissal', 'Van Horne v. Muller', 'https://www.courtlistener.com/opinion/1998695/', '1998695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 399 (Alaska 1980), where we held that separate punishments for multiple deaths resulting from a single criminal act are impermissible under the state’s double jeopardy clause.', 'general', 'State v. Dunlop', 'https://www.courtlistener.com/opinion/1175813/', '1175813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “where there has been but one statute violated by a single act, without intent to harm multiple victims, the Alaskan constitutional prohibition against placing a person in jeopardy twice for the same offense prevents imposition of multiple punishments.', 'general', 'State v. Dunlop', 'https://www.courtlistener.com/opinion/1175813/', '1175813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Alaska’s constitutional prohibition against double jeopardy does not bar multiple sentences for multiple victims where one statute has been violated several times.', 'sentencing', 'State v. Dunlop', 'https://www.courtlistener.com/opinion/1175813/', '1175813') ON CONFLICT DO NOTHING;
