INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that robbery and use of a firearm were the same offense under this test and hence only one sentence could be imposed.', 'sentencing', 'State v. Dunlop', 'https://www.courtlistener.com/opinion/1175813/', '1175813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that all the tests failed to determine when separate statutory violations consti
