INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the gang loitering ordinance is an arbitrary restriction on personal liberty and, thus, violates substantive due process.', 'general', 'City of Chicago v. Morales', 'https://www.courtlistener.com/opinion/2230034/', '2230034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the gang loitering ordinance violates due process of law in that it is impermissibly vague on its face and an arbitrary restriction on personal liberties.', 'general', 'City of Chicago v. Morales', 'https://www.courtlistener.com/opinion/2230034/', '2230034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we find that the gang loitering ordinance fails to meet the adequate notice standards of the vagueness doctrine.', 'general', 'City of Chicago v. Morales', 'https://www.courtlistener.com/opinion/2230034/', '2230034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we find that the gang loitering ordinance unreasonably infringes upon personal liberty.', 'general', 'City of Chicago v. Morales', 'https://www.courtlistener.com/opinion/2230034/', '2230034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that as to embezzlement and false pretenses charges, the legislature intended to give full effect to our original common law rule against requiring the State to elect between charges, if the felonies charged allegedly arose from the same transaction.', 'general', 'State v. Speckman', 'https://www.courtlistener.com/opinion/1268005/', '1268005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, given the peculiar posture in which this case comes before us, we conclude that there is a “reasonable possibility” that a different result would have been reached at trial as to both charges, had the trial court correctly instructed the jury that it could convict the defendant only of one offense or the other, but not of both.', 'general', 'State v. Speckman', 'https://www.courtlistener.com/opinion/1268005/', '1268005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS ORDERED THAT the livestock, including but not limited to the horses, are [sic] hereby placed in the protective custody of [SCARE], and further that the animals remain on the property for assessment and medial treatment and care, as deemed necessary by SCARE and their [sic] agents.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/1208387/', '1208387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to the magistrate court.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/1208387/', '1208387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we reverse the circuit court’s ruling that appellants were not entitled to a post-seizure hearing.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/1208387/', '1208387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'McFee v. State', 'https://www.courtlistener.com/opinion/1743707/', '1743707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the above, we affirm.', 'general', 'McFee v. State', 'https://www.courtlistener.com/opinion/1743707/', '1743707') ON CONFLICT DO NOTHING;
