INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pursuant to the analysis set forth below, we hold that it did not.', 'general', 'State v. Furutani', 'https://www.courtlistener.com/opinion/1209855/', '1209855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being the case, we hold that the circuit court’s COL that “the possible misconduct at voir dire .', 'general', 'State v. Furutani', 'https://www.courtlistener.com/opinion/1209855/', '1209855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that when a criminal defendant makes a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court’s COL that juror “misconduct during deliberations deprived [Furutani] of a trial by twelve fair and impartial jurors” was not clearly erroneous.', 'general', 'State v. Furutani', 'https://www.courtlistener.com/opinion/1209855/', '1209855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as the circuit court’s FOFs and COL were not clearly erroneous, we hold that the circuit court did not commit, an abuse of discretion in granting Furutani’s motion for new trial.', 'general', 'State v. Furutani', 'https://www.courtlistener.com/opinion/1209855/', '1209855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the trial court abused its discretion in refusing to grant a new trial when, during voir dire, a juror gave an untruthful answer to the very question at issue in the present case.', 'general', 'State v. Furutani', 'https://www.courtlistener.com/opinion/1209855/', '1209855') ON CONFLICT DO NOTHING;
