INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being so, we hold that the family court could reasonably have inferred that Stocker intended his conduct to “annoy” or “alarm” Shane.', 'general', 'State v. Stocker', 'https://www.courtlistener.com/opinion/1277222/', '1277222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he must.', 'general', 'State v. Stocker', 'https://www.courtlistener.com/opinion/1277222/', '1277222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Stocker was a “parent” for purposes of HRS § 703-309(1).', 'general', 'State v. Stocker', 'https://www.courtlistener.com/opinion/1277222/', '1277222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that the family court’s finding is unsupported by substantial evidence.', 'general', 'State v. Stocker', 'https://www.courtlistener.com/opinion/1277222/', '1277222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse his judgment, guilty conviction, and sentence.', 'sentencing', 'State v. Stocker', 'https://www.courtlistener.com/opinion/1277222/', '1277222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the forgoing reasoning, we reverse the judgment, guilty conviction, and sentence of the family court.', 'sentencing', 'State v. Stocker', 'https://www.courtlistener.com/opinion/1277222/', '1277222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant received a fair trial and capital sentencing proceeding, free of prejudicial error.', 'sentencing', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the failure to instruct did not rise to the level of plain error.', 'general', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 672 (1986), this Court held that a defendant has been denied effective assistance of counsel if his counsel admits his guilt to the jury without his consent.', 'general', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the instructional error might have “tilted the scales” and caused the jury to reach its guilty verdict “[i]n light of the highly conflicting evidence in the .', 'general', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 158, 168 (1992), this Court held that “[i]n the event of some contact with a juror it is the duty of the trial judge to determine whether such contact resulted in substantial and irreparable prejudice to the defendant.', 'general', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that “[t]he trial judge is not required to repeat a definition each time a word or term is repeated in the charge when it has once been defined.', 'general', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that defendant’s trial and sentences, including specifically his capital sentencing proceeding, were free of prejudicial error and that defendant’s sentence of death is not disproportionate.', 'sentencing', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these facts provided ample evidence of confinement not inherent in the first-degree murder to support the charge of first-degree kidnapping.', 'general', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court correctly denied defendant’s request to submit the offense of second-degree murder to the jury.', 'general', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s instruction in this regard was without error.', 'general', 'State v. Gainey', 'https://www.courtlistener.com/opinion/1298639/', '1298639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State’s complaint was properly dismissed and the petition properly denied.', 'dismissal', 'State Ex Rel. Edmisten v. Tucker', 'https://www.courtlistener.com/opinion/1298189/', '1298189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 769 (1984), we hold that the trial court correctly denied the State’s petition for writ of mandamus or prohibition in this case.', 'general', 'State Ex Rel. Edmisten v. Tucker', 'https://www.courtlistener.com/opinion/1298189/', '1298189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial judge’s order dismissing the complaint and petition against all defendants.', 'dismissal', 'State Ex Rel. Edmisten v. Tucker', 'https://www.courtlistener.com/opinion/1298189/', '1298189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the finding of the trial court is supported by the record and not clearly erroneous as a matter of law.', 'general', 'State v. Kimbrough', 'https://www.courtlistener.com/opinion/1253361/', '1253361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that defense counsel''s representation of Kimbrough was objectively reasonable under all the circumstances and ensured that Kimbrough received a fair trial.', 'general', 'State v. Kimbrough', 'https://www.courtlistener.com/opinion/1253361/', '1253361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the evidence was sufficient for the jury to have drawn the appropriate inference that Kimbrough acted with criminal recklessness in causing the death of Anthony.', 'general', 'State v. Kimbrough', 'https://www.courtlistener.com/opinion/1253361/', '1253361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'State v. Kimbrough', 'https://www.courtlistener.com/opinion/1253361/', '1253361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the guilt-innocence determination phase of the defendant''s trial was free from prejudicial error.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the evidence as to the wives'' deaths was admissible to show motive as well as knowledge of the effect of poison in the killing for which the defendant was on trial.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '72 (1938), this Court held that evidence of previous poisonings was admissible to show scienter, intent and motive.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing Rule 901, this Court held that the tape recording was properly authenticated.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion by allowing these photographs into evidence for the limited purpose of illustrating witnesses'' testimony.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the authentication requirements of Rule 901 have superseded and replaced the seven-pronged Lynch test.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the trial court properly admitted the tape recording as evidence at trial.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant received a trial and sentencing hearing free of prejudicial error, that the jury did not sentence out of passion or prejudice, and that the sentence is not disproportionate.', 'sentencing', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'that it was error for the trial court to have conducted the change of venue hearing out of defendant’s presence, we conclude that any such error was harmless.', 'general', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that any error which may have resulted from defendant’s failure to attend the hearing is harmless beyond a reasonable doubt.', 'general', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s argument in this case was likewise not grossly improper.', 'general', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any impropriety in the prosecutor’s argument or error in the trial judge’s failure to intervene was cured by the subsequent instructions on the law.', 'general', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence in this case compels the conclusion that the defendant premeditated and deliberated the killing.', 'general', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we find that the trial judge’s instructions adequately apprised the jury that if it did not find that the aggravating factor outweighed the mitigating factors, it would return a recommendation of life imprisonment.', 'general', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, after making such a comparison, we find that juries have consistently been returning death sentences in the similar cases, then we will have a strong basis for concluding that a death sentence in the case under review is not excessive or disproportionate.', 'sentencing', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the other hand if we find that juries have consistently been returning life sentences in the similar cases, we will have a strong basis for concluding that a death sentence in the case under review is excessive or disproportionate.', 'sentencing', 'State v. Zuniga', 'https://www.courtlistener.com/opinion/1359245/', '1359245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the provisions of the Omnibus Crime Bill were enacted after Section 16-11-312, we conclude that subsection (C) of Section 16-11-312 has been implicitly repealed.', 'general', 'Hair v. State', 'https://www.courtlistener.com/opinion/1354857/', '1354857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these two statutory provisions are in direct conflict;', 'general', 'Hair v. State', 'https://www.courtlistener.com/opinion/1354857/', '1354857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Hair v. State', 'https://www.courtlistener.com/opinion/1354857/', '1354857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when one or more of the tail lamps on a vehicle originally equipped with multiple tail lamps are not in proper working condition, the provisions of West Virginia Code § 17C-15-l(a) that establish a misdemeanor offense for the operation of an unsafe or improperly equipped motor vehicle are violated.', 'general', 'Strick v. CICCHIRILLO', 'https://www.courtlistener.com/opinion/1375610/', '1375610') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having carefully examined the arguments on this issue, we find that the trial court did not commit error and, accordingly, affirm.', 'general', 'Strick v. CICCHIRILLO', 'https://www.courtlistener.com/opinion/1375610/', '1375610') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 315 (2006), this Court held it was immediately apparent that a shower curtain found in the defendant’s home was evidence of a crime when the officer testified the curtain matched pictures she had seen that the “victims ha[d] provided [her] of items that were taken from their bathroom.', 'general', 'State v. Haymond', 'https://www.courtlistener.com/opinion/1299936/', '1299936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant’s motions to dismiss those charges should have been granted, and we reverse his convictions of breaking or entering in 07 CRS 881, 07 CRS 886, and 07 CRS 50466.', 'dismissal', 'State v. Haymond', 'https://www.courtlistener.com/opinion/1299936/', '1299936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Lincoln ordinance is susceptible to a narrowing construction, and we therefore turn to the rules governing analysis of a facial challenge to the constitutionality of a statute.', 'general', 'State v. Hookstra', 'https://www.courtlistener.com/opinion/1253371/', '1253371') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court had no authority to revoke parole eligibility and did not do so and that the defendant was not subjected to multiple prosecutions or punishments.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1847033/', '1847033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1847033/', '1847033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that physical evidence obtained as a result of statements made in contravention of Miranda is excludable under Article 10 of the Vermont Constitution.', 'general', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', where we held that simply feeling a plastic baggie during the course of a legal pat-down did not provide an officer with the requisite probable cause to seize the baggie.', 'probable_cause', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that the threshold determination of whether a reasonable expectation of privacy is implicated is not met.', 'general', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that a seizure in this circumstance is justified under Article 11 of the Vermont Constitution and under the Fourth Amendment.', 'search_seizure', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With regard to the court’s inference that defendant was engaged in selling drugs, we conclude that this inference was relevant to sentencing because it shed light on the nature of the crime and defendant’s proclivities.', 'sentencing', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the officer had probable cause to open the pouch even absent defendant’s consent, we do not reach this issue.', 'probable_cause', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we concluded that “mere possession of a plastic bag in a pocket is [not] sufficiently incriminating to render it immediately apparent that the contents of that bag are contraband.', 'general', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it was undisputed that the marijuana plants in that case were a fruit of the unwarned interrogation, we found that the trial court erred in failing to suppress them.', 'suppression', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lambert, we reversed a sentence where the sentencing court “specifically attempted to establish a minimum equal to the maximum term” by imposing a sentence of not less than twenty-four months or more than two years.', 'sentencing', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction on all three charges, reverse the sentence for cocaine possession, and remand for resentencing on this charge.', 'sentencing', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that WIS.', 'general', 'State v. Randle', 'https://www.courtlistener.com/opinion/1296834/', '1296834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that territorial jurisdiction may be waived.', 'general', 'State v. Randle', 'https://www.courtlistener.com/opinion/1296834/', '1296834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that because territorial jurisdiction attached to the original charge of second-degree sexual assault, the trial court necessarily retained jurisdiction over all lesser-included offenses of the original charge, including third-degree sexual assault.', 'general', 'State v. Randle', 'https://www.courtlistener.com/opinion/1296834/', '1296834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Randle waived his right to challenge territorial jurisdiction, because territorial jurisdiction was established, and because Randle failed to prove that he received ineffective assistance of trial counsel, we affirm.', 'ineffective_assistance', 'State v. Randle', 'https://www.courtlistener.com/opinion/1296834/', '1296834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although theseoffenses are included in the same statutory chapter, HRS Chapter 708, entitled “Offenses Against Property Rights,” and while the ultimate results of both offenses may be similar, we hold that the legislature intended to protect different societal interests in enacting these statutes.', 'general', 'State v. Freeman', 'https://www.courtlistener.com/opinion/1179516/', '1179516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under HRS § 701-109(4)(c), Theft in the Second Degree is not a lesser included offense of F.', 'general', 'State v. Freeman', 'https://www.courtlistener.com/opinion/1179516/', '1179516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Theft in the Second Degree is not a lesser included offense of Fraudulent Use of a Credit Card pursuant to HRS § 701-109(4), nor does the offense of Theft in the Second Degree merge with the offense of Fraudulent Use ofa Credit Card pursuant to HRS § 701-109(1).', 'general', 'State v. Freeman', 'https://www.courtlistener.com/opinion/1179516/', '1179516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Theft in the Second Degree is not a lesser included offense of Fraudulent Use of a Credit Card, nor do the two offenses merge pursuant to HRS § 701-109.', 'general', 'State v. Freeman', 'https://www.courtlistener.com/opinion/1179516/', '1179516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Fot the above reasons, we conclude that Theft in the Second Degree is not a lesser included offense of F.', 'general', 'State v. Freeman', 'https://www.courtlistener.com/opinion/1179516/', '1179516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Thorne’s due process rights at the revocation hearing were violated by the state’s failure to preserve the videotape.', 'general', 'Thorne v. Department of Public Safety', 'https://www.courtlistener.com/opinion/1179545/', '1179545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1330651/', '1330651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the ordinance violates the U.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
