INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s award of attorney fees.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s grant of summary judgment declaring the ordinance in violation of the U.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Steffensen v. State', 'https://www.courtlistener.com/opinion/1179998/', '1179998') ON CONFLICT DO NOTHING;
