INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in refusing to merge Counts 17 and 18.', 'general', 'State of Tennessee v. Benjamin Foust', 'https://www.courtlistener.com/opinion/2912095/', '2912095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'review, we conclude that the trial court erred by allowing the State to introduce, as
