INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not err in accepting the stipulation
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we conclude that the trial court‘s error in admitting the irrelevant
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the error does not rise to the level of plain error.', 'general', 'State of Tennessee v. Benjamin Foust', 'https://www.courtlistener.com/opinion/2912095/', '2912095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgments of the trial court and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the ends of justice do not require that we consider the issue for the first time on appeal.', 'general', 'Mounce v. Commonwealth', 'https://www.courtlistener.com/opinion/1359164/', '1359164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circumstances of this case do not demonstrate the good cause required by Rule 3:10-2 to mount such an untimely challenge, nor do they reveal any fundamental miscarriage of justice that would invoke our supervisory power to correct a perceived injustice.', 'general', 'State v. Del Fino', 'https://www.courtlistener.com/opinion/2349242/', '2349242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that in the absence of a timely challenge to the indictment, it would be an excess exercise of our supervisory power to attempt to reconstruct the processes of this grand jury now.', 'general', 'State v. Del Fino', 'https://www.courtlistener.com/opinion/2349242/', '2349242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the indictment in this case failed to satisfy the minimum criteria for describing the essential elements of the felony third-offense crime defined by W.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/1365591/', '1365591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[22] There, we held that the State must allege, in the face of a motion to quash, which type of intoxication it seeks to prove in a prosecution for involuntary manslaughter.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Porter, we held that the State need not allege which definition of "forgery" it seeks to prove.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that once the State made this allegation, it had to prove it.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Curry''s hypothetically correct jury charge would have instructed the jury to convict Curry if it found that he intentionally or knowingly abducted Williams with the intent to prevent his liberation by using or threatening to use deadly force namely, a firearm, on Williams and with intent to inflict bodily injury on Williams or to terrorize Williams or to violate and abuse Williams sexually.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the phrase "by using and threatening to use deadly force namely, a firearm" was not surplusage.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[24] We concluded that "[i]f the prohibited conduct is statutorily defined to include more than one manner or means of commission," the State must allege, upon timely request, which manner or means it seeks to establish.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, albeit for different reasons, the court of appeals'' holding that the evidence was sufficient to convict.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court properly exercised its discretion in excluding portions of Jensen''s defense witnesses'' testimony, but erred in submitting an erroneous jury instruction and in excluding portions of Jensen''s own testimony.', 'jury_instruction', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it did not do so, we conclude that the jury instruction violates § 903.', 'jury_instruction', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered the question, we conclude that the statutory instructional error was not harmless beyond a reasonable doubt.', 'general', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Jensen''s substantial rights were affected because the instruction operated to relieve the State of its burden of proving beyond a reasonable doubt that Jensen acted with the intent to obtain a dishonest advantage for himself or another.', 'general', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court properly exercised its discretion in excluding the testimony of Jensen''s proffered witnesses as to campaign practices among Democratic and Republican legislators, but that the record is insufficient to establish whether it properly exercised its discretion in excluding Jensen''s own testimony on that same topic.', 'general', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the proffered testimony of Jensen''s defense witnesses was not relevant to whether Jensen intended to gain a dishonest advantage, and thus the trial court did not erroneously exercise its discretion in excluding it.', 'general', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, while we conclude that the testimony of Jensen''s defense witnesses was properly excluded as irrelevant, we do not reach the same conclusion as to Jensen''s own testimony on the same issue.', 'general', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the trial court''s jury instruction on Misconduct in Public Office was erroneous.', 'jury_instruction', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the court properly exercised its discretion in excluding the portions of Jensen''s defense witnesses'' testimony as to those practices, because their beliefs were not relevant to Jensen''s intent.', 'general', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the court''s jury instruction was erroneous under Wis.', 'jury_instruction', 'State v. Jensen', 'https://www.courtlistener.com/opinion/1574012/', '1574012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Newell''s sentence, but we reverse the parole restriction.', 'sentencing', 'Newell v. State', 'https://www.courtlistener.com/opinion/1355576/', '1355576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other aspects we affirm the sentence.', 'sentencing', 'Newell v. State', 'https://www.courtlistener.com/opinion/1355576/', '1355576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Rakestraw v. SC DEPT. HIGHWAYS & TRANS.', 'https://www.courtlistener.com/opinion/1356755/', '1356755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is no merit to any issue except sufficiency of the evidence on the first-degree battery conviction.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1794962/', '1794962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case we find that it is appropriate to reduce the sentence from twenty years imprisonment, the maximum for first-degree battery, to six years, the maximum sentence for second degree battery.', 'sentencing', 'Smith v. State', 'https://www.courtlistener.com/opinion/1794962/', '1794962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court on this point as well.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1794962/', '1794962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that where police lack express legislative authority, particularized suspicion of criminal wrongdoing and prior judicial approval, roadblocks established to apprehend drunk drivers cannot withstand constitutional scrutiny.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1162605/', '1162605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the individual''s right of freedom from arbitrary governmental intrusion, and the questionable efficacy of roadblocks, we conclude that such roadblocks cannot withstand constitutional scrutiny.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1162605/', '1162605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1162605/', '1162605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this standard, we hold that substantial evidence exists to support both the kidnapping and murder convictions.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that defendant was not denied a fair trial because of pretrial publicity, we do not address the various alleged incidents of improper contact with the media.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 411 (1991), we hold that defendant has failed to establish the degree of underrepresentation “by comparing the proportion of the group in the total population to the proportion called to serve as .', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concerning his claim that “persons not employed by large corporations” were systematically excluded from the jury pool, we hold that, as with his sixth amendment claim, defendant has failed to demonstrate that those persons constitute a distinct group for purposes of equal protection analysis.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the “We The People” members were not sufficiently noticeable, persuasive, or influential — passively or otherwise — to deprive defendant of a fair trial.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the error was harmless.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial judge’s failure to make an Enmund finding is not error.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence presented, although circumstantial, plainly negated the possibility that the victim died as the result of an accident.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing this evidence in the light most favorable to upholding the jury’s finding, we conclude that the jury was presented with substantial evidence from which it could conclude beyond a reasonable doubt that defendant murdered the victim.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We address the merits of defendant’s claim in this direct appeal because, viewing the record in its entirety, we conclude that defendant’s claim is merit-less.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we find that counsel sufficiently preserved the argument for review.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that it would have been futile to move to strike testimony which the trial court had already ruled was proper.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Bryant was unfairly prejudiced by the improper cross-examination.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse on this issue.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Court of Appeals'' ruling on this issue.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence in this case was legally insufficient to support the conviction for engaging in organized criminal activity.', 'general', 'Hart v. State', 'https://www.courtlistener.com/opinion/1353950/', '1353950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals''s judgment in part, render a verdict of guilt for theft of property valued greater than $20,000 but less than $100,000, and remand the case to the trial court for a new punishment determination.', 'general', 'Hart v. State', 'https://www.courtlistener.com/opinion/1353950/', '1353950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Truesdale', 'https://www.courtlistener.com/opinion/1328843/', '1328843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a circuit court should conduct an on-the-record colloquy to ensure that the defendant is knowingly, intelligently, and voluntarily waiving his or her right to testify.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In analyzing Weed''s hearsay challenge and ultimately concluding that any error was harmless, the court of appeals appeared to employ a sufficiency of the *457 evidence standard: "Because there was sufficient evidence, other than Michael''s alleged hearsay statement, to convict Patricia [Weed] beyond a reasonable doubt, we hold that any error in the admission of the Fuerbringers'' testimony was harmless.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the circuit court did not erroneously exercise its discretion in admitting the hearsay statement under the recent perception exception to the hearsay rule.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the constitutional right of a criminal defendant to testify on his or her behalf is a fundamental right.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on our review of the record and the circuit court''s rulings regarding the admissibility of Michael''s statement, we conclude that the circuit court did not erroneously exercise its discretion in admitting Michael''s statement under the recent perception exception to the hearsay rule.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of defense counsel''s cross-examination of Fuerbringer and his son, the low probative value of Michael''s statement, and the overwhelming evidence presented by the State, we conclude that the admission of the hearsay statement was not prejudicial.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the admission of Michael''s statement did not contribute to the verdict because it is "clear beyond a reasonable doubt that a rational jury would have convicted absent the error.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the lack of a colloquy, we conclude that Weed knowingly, intelligently, and voluntarily waived *465 her right to testify based on our review of the record and the evidence presented at the post-conviction hearing.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that Weed waived her right to testify based on the record and the evidence presented at the post-conviction hearing, we decline to determine whether a post-conviction hearing would always be sufficient to ensure that a criminal defendant has waived his or her right to testify.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the circuit court did not erroneously exercise its discretion in admitting the hearsay statement made by Michael under the recent perception exception to the hearsay rule.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, this Court held in Syllabus Point 1 of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 504 (1995), this Court held, in part, that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the magistrate court did not have jurisdiction of the offenses of burglary, grand larceny, and destruction of property as a matter of law, we do not find it necessary to consider these specific arguments.', 'general', 'State v. Hutzler', 'https://www.courtlistener.com/opinion/1318663/', '1318663') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the double jeopardy clause did not bar the appellant’s subsequent indictment for the felony offenses of burglary and grand larceny in the Circuit Court of Berkeley County.', 'general', 'State v. Hutzler', 'https://www.courtlistener.com/opinion/1318663/', '1318663') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, having determined that the Magistrate Court of Jefferson County did not have jurisdiction of the offenses of burglary, grand larceny, and destruction of property with which the appellant was charged, we find that the appellant was never in jeopardy for these offenses in the Magistrate Court of Jefferson County.', 'general', 'State v. Hutzler', 'https://www.courtlistener.com/opinion/1318663/', '1318663') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Hutzler', 'https://www.courtlistener.com/opinion/1318663/', '1318663') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the appellant’s prosecution in the Circuit Court of Berkeley County for burglary, grand larceny, and destruction of property was not barred by the double jeopardy clause and should not have been dismissed as a result of the State’s destruction of evidence, we affirm the January 6, 2008, order of the circuit court adjudging the appellant guilty of felony destruction of property and sentencing him to three years of probation.', 'dismissal', 'State v. Hutzler', 'https://www.courtlistener.com/opinion/1318663/', '1318663') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing the conviction this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 891 (2002) (per curiam) this Court held as reversible error the following comment by a prosecuting attorney made during closing argument: "[t]here are cases in which the murderer himself says, `I am so *516 sorry;', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having already so found, we conclude that the fourth prong of Sugg, supra, is satisfied.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Syllabus Point 7 of LaRock, supra, and Syllabus Point 7 of Miller, supra, are dispositive of this issue.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the exception of the last comment considered by us relating to the testimony of the defendant, we find that the statements made by the prosecuting attorney were deliberate.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein we reverse and remand for a new trial.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the reasons stated herein, we reverse and remand for a new trial.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that "there was an entire lack of those elements of outrageous conduct which would subject the defendants to punitive damages.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, for the following reasons, we conclude that Officer Woolard was immune from suit in either capacity.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts and circumstances as set forth above, however, we conclude that the searches were not consensual, but were the result of intimidation.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no manifest abuse of discretion in the award of compensatory damages.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial court erred in finding that Friend engaged in outrageous conduct and in concluding that Friend''s outrageous conduct entitled plaintiff to recover punitive damages from Friend.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 279 (1979), when we held that "[t]he prosecuting attorney is a constitutional officer who exercises the sovereign power of the State at the will of the people and he is at all times answerable to them.', 'general', 'State Ex Rel. Diva P. v. Kaufman', 'https://www.courtlistener.com/opinion/1330571/', '1330571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 537 (1989) we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our review of the record we find that the circuit court was not clearly erroneous, in determining that the guardian ad litem failed to establish that there was no reasonable likelihood the conditions of neglect could be substantially corrected.', 'general', 'State Ex Rel. Diva P. v. Kaufman', 'https://www.courtlistener.com/opinion/1330571/', '1330571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing, we find that the petitioners are not entitled to relief and, therefore, we deny the requested writ.', 'general', 'State Ex Rel. Diva P. v. Kaufman', 'https://www.courtlistener.com/opinion/1330571/', '1330571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because they did not employ force prior to or while taking the store merchandise, we hold that petitioners cannot be properly convicted of robbery with a firearm under section 812.', 'general', 'Royal v. State', 'https://www.courtlistener.com/opinion/1876126/', '1876126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that subsection (3) was intended only to define the phrase "in the course of committing the robbery," as it is used in subsection (2) for purposes of establishing punishment by reference to the type of force used to perpetrate the robbery.', 'general', 'Royal v. State', 'https://www.courtlistener.com/opinion/1876126/', '1876126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these facts, however, we find that petitioners could have been charged separately with theft, for the taking of the goods that occurred in the store;', 'general', 'Royal v. State', 'https://www.courtlistener.com/opinion/1876126/', '1876126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because this record clearly establishes the petitioners'' guilt of aggravated assault with a deadly weapon, which is a necessarily lesser included offense of robbery with a firearm, we find that, pursuant to section 924.', 'general', 'Royal v. State', 'https://www.courtlistener.com/opinion/1876126/', '1876126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the evidence was sufficient to support the conviction and that there was no other error, we affirm the judgment.', 'general', 'State v. Bruzzese', 'https://www.courtlistener.com/opinion/1540134/', '1540134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 14] Because we conclude that the evidence was sufficient for the jury rationally to find beyond a reasonable doubt that Bruzzese exercised unauthorized control over items worth more than $1,000 in value, and because we discern no other error, we affirm Bruzzese’s conviction of Class C theft pursuant to 17-A M.', 'general', 'State v. Bruzzese', 'https://www.courtlistener.com/opinion/1540134/', '1540134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 227, 229 (1984), we held that a defendant who has already entered a plea pursuant to a plea agreement must be given an opportunity to withdraw that plea if the trial court refuses to impose the sentence recommended by the plea agreement.', 'sentencing', 'State v. Bergerson', 'https://www.courtlistener.com/opinion/2182083/', '2182083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because this is plain error, affecting substantial rights of defendant, we reverse and remand.', 'general', 'State v. Bergerson', 'https://www.courtlistener.com/opinion/2182083/', '2182083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In support of our conclusion, we hold that the appellant''s constitutional right to counsel under the Alaska Constitution was violated.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was not the intent of the Alaska Constitutional Convention, in adopting a portion of the wording of the Sixth Amendment, to give to article I, section 11 any broader application than that portion of the Sixth Amendment had been given by the United States Supreme Court.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the petitioner was denied the basic protections of that guarantee [right to counsel, sixth amendment] when there was used against him at his trial evidence of his own incriminating words, which federal agents had deliberately elicited from him after he had been indicted and in the absence of his counsel.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that providing transportation of school children to non-public schools at public expense would be a contravention of the state constitution.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of this evidence by the trial court was error.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that article I, § 11 of the Alaska Constitution requires counsel in the circumstances of the present case.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), we held that the gravamen of the offense of “false statement to obtain property or credit” of Section 32.', 'general', 'Harris, Owen Thomas', 'https://www.courtlistener.com/opinion/2944222/', '2944222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wallace, we held that “to whom the exposure is directed is not an essential element of the offense of indecent exposure.', 'general', 'Harris, Owen Thomas', 'https://www.courtlistener.com/opinion/2944222/', '2944222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8 Consequently, we held that the failure to plead the specific person to whom an accused exposed himself did not render an indictment or information fundamentally defective.', 'plea', 'Harris, Owen Thomas', 'https://www.courtlistener.com/opinion/2944222/', '2944222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Amador, we held that indecent exposure, as set out in Section 21.', 'general', 'Harris, Owen Thomas', 'https://www.courtlistener.com/opinion/2944222/', '2944222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that “to whom the exposure is directed is not an essential element of the offense of indecent exposure.', 'general', 'Harris, Owen Thomas', 'https://www.courtlistener.com/opinion/2944222/', '2944222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”18 We found that the failure to plead that the accused exposed himself to a specified person did not render a charging instrument fundamentally defective.', 'plea', 'Harris, Owen Thomas', 'https://www.courtlistener.com/opinion/2944222/', '2944222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Parris', 'https://www.courtlistener.com/opinion/1340365/', '1340365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the court of appeals and remand the cause to that court to address the appellant’s remaining point of error.', 'general', 'Snowden, Rion Pheal', 'https://www.courtlistener.com/opinion/2944420/', '2944420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellant had revoked her consent to enter, the officers had no probable cause to arrest her until after the fourth iteration of her revocation of consent, and that, by remaining in her apartment, the officers were not at a vantage point where they had the right to be.', 'probable_cause', 'Miller, Christina Jean', 'https://www.courtlistener.com/opinion/2945761/', '2945761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992) (“Though we defer to a trial court’s factual findings when they are supported by the record, we conclude that the record does not support the trial court’s finding.', 'general', 'Miller, Christina Jean', 'https://www.courtlistener.com/opinion/2945761/', '2945761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s factual finding that the police presence in the appellant’s apartment was part of a reasonable domestic-violence investigation is accurate with respect to the officers’ initial entry, but it does not support a legal conclusion that the officers were still completing their investigation of domestic violence at the time they remained in appellant’s apartment while waiting for a return on the warrant check and at the time that the illegal substance was found.', 'general', 'Miller, Christina Jean', 'https://www.courtlistener.com/opinion/2945761/', '2945761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals’s judgment.', 'general', 'Miller, Christina Jean', 'https://www.courtlistener.com/opinion/2945761/', '2945761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appéals and remand this cause to the trial court for further proceedings consistent with this opinion.', 'general', 'Miller, Christina Jean', 'https://www.courtlistener.com/opinion/2945761/', '2945761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '003, we hold that a DPS substantial-similarity determination is an essential element of the offense of failure to comply with registration requirements.', 'general', 'Crabtree, Mark Alan', 'https://www.courtlistener.com/opinion/2945915/', '2945915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we held that Warren’s out-of-state conviction was substantially similar to indecency with a child for purposes of article 62.', 'general', 'Crabtree, Mark Alan', 'https://www.courtlistener.com/opinion/2945915/', '2945915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addressing Harbin’s claim of actual innocence for failing to comply with registration requirements based on two out-of-state convictions, we held that, due to the various savings clauses found in the legislative amendments to Chapter 62, the convictions alleged in the indictment did not trigger an obligation to register.', 'general', 'Crabtree, Mark Alan', 'https://www.courtlistener.com/opinion/2945915/', '2945915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '41 We held that, under the version of Chapter 62 in effect at the time of the opinion, Harbin would need to register for his 1988 conviction for lewd or lascivious acts — the same offense that we held did not trigger Chapter 62’s applicability at the time of the alleged offense — and his 1995 conviction for sexual battery because DPS determined in 2006 that both of these convictions are reportable convictions in Texas.', 'general', 'Crabtree, Mark Alan', 'https://www.courtlistener.com/opinion/2945915/', '2945915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Holding that the evidence was legally insufficient to support Crabtree’s conviction for the offense of failure to comply with registration requirements, we reverse the judgments of the courts below and enter a judgment of acquittal.', 'general', 'Crabtree, Mark Alan', 'https://www.courtlistener.com/opinion/2945915/', '2945915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the first issue is dispositive, we need not reach the second issue.', 'general', 'Crenshaw, Bradley Kelton', 'https://www.courtlistener.com/opinion/2946079/', '2946079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d at 171, we held that the jury charge improperly broadened the charges against the appellant.', 'general', 'Crenshaw, Bradley Kelton', 'https://www.courtlistener.com/opinion/2946079/', '2946079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and remand the case for further proceedings consistent with this opinion.', 'general', 'Crenshaw, Bradley Kelton', 'https://www.courtlistener.com/opinion/2946079/', '2946079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the evidence presented in this case showed that the child was quite cold and one could infer that, if the child had remained outside with the same clothing the child might have been in imminent danger of bodily injury or physical or mental impairment, we conclude that one could not reasonably determine from the evidence that Garcia’s conduct placed the child in imminent danger of bodily injury or physical or mental impairment.', 'general', 'Garcia, Aima Lorena', 'https://www.courtlistener.com/opinion/2946564/', '2946564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in a light most favorable to the jury’s verdict, we conclude that no rational fact finder could have determined that appellant’s child had sustained bodily injury or physical impairment.', 'general', 'Garcia, Aima Lorena', 'https://www.courtlistener.com/opinion/2946564/', '2946564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Garcia, Aima Lorena', 'https://www.courtlistener.com/opinion/2946564/', '2946564') ON CONFLICT DO NOTHING;
