INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we hold that Section 402.', 'general', 'Lo, Ex Parte John Christopher', 'https://www.courtlistener.com/opinion/2947509/', '2947509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On original submission, this Court held Section 33.', 'general', 'Lo, Ex Parte John Christopher', 'https://www.courtlistener.com/opinion/2947509/', '2947509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the constitutionally required presumption that “content-based regulations [of speech] are presumptively invalid”6 and subject to strict scrutiny,7 we conclude that Section 33.', 'general', 'Lo, Ex Parte John Christopher', 'https://www.courtlistener.com/opinion/2947509/', '2947509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the statutory provision before us is not narrowly drawn to effectuate a compelling state interest because there are narrower means of achieving the State interests advanced here, at least some of which are already covered by other statutes prohibiting solicitation, obscenity, harassment, or the distribution of harmful material to minors.', 'general', 'Lo, Ex Parte John Christopher', 'https://www.courtlistener.com/opinion/2947509/', '2947509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of that court and remand the case to the trial court to dismiss the indictment.', 'dismissal', 'Lo, Ex Parte John Christopher', 'https://www.courtlistener.com/opinion/2947509/', '2947509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a consideration of the petition, it is ordered that our former opinion be withdrawn and the following substituted therefor.', 'general', 'State v. Horton', 'https://www.courtlistener.com/opinion/1213073/', '1213073') ON CONFLICT DO NOTHING;
