INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing all of the evidence in the light most favorable to the guilty verdict, we hold that the evidence merely raises a *773suspicion of appellant’s guilt and is legally insufficient to support a conviction of capital murder beyond a reasonable doubt.', 'general', 'Winfrey, Megan AKA Megan Winfrey Hammond', 'https://www.courtlistener.com/opinion/2948611/', '2948611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that dog-scent lineups, “when used alone or as primary evidence, are legally insufficient to support a conviction.', 'general', 'Winfrey, Megan AKA Megan Winfrey Hammond', 'https://www.courtlistener.com/opinion/2948611/', '2948611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that we do not need to address the proper interpretation of the statute in this case because the record does not contain evidence on which a reasonable jury could find that appellant agreed with one or both of the alleged co-conspirators that one or more of them would engage in conduct that would constitute the alleged capital murder or that one or more of them performed an overt act in pursuance of such an agreement.', 'general', 'Winfrey, Megan AKA Megan Winfrey Hammond', 'https://www.courtlistener.com/opinion/2948611/', '2948611') ON CONFLICT DO NOTHING;
