INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and render a judgment of acquittal for each offense.', 'general', 'Winfrey, Megan AKA Megan Winfrey Hammond', 'https://www.courtlistener.com/opinion/2948611/', '2948611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'His conviction'' was affirmed by the court of appeals but, on discretionary review, we reversed his conviction and entered a judgment of acquittal.', 'general', 'Winfrey, Megan AKA Megan Winfrey Hammond', 'https://www.courtlistener.com/opinion/2948611/', '2948611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that the misconduct must be shown to have materially contributed to the verdict of the jury.', 'general', 'State v. Griffiths', 'https://www.courtlistener.com/opinion/1212795/', '1212795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the burden of proving beyond a reasonable doubt [assuming that burden is upon the respondent State] that the error did not contribute to the guilty verdict has been sustained.', 'general', 'State v. Griffiths', 'https://www.courtlistener.com/opinion/1212795/', '1212795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 171 (1963), this Court held "that there is not a reasonable possibility the prosecutorial misconduct in closing argument may have contributed to the guilty verdict in this case.', 'general', 'State v. Griffiths', 'https://www.courtlistener.com/opinion/1212795/', '1212795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1340 (1973), this Court held that the statute imposed a requirement on the trial court:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this requirement, this Court held that a defendant was harmed when his enhanced punishment was premised on an invalid prior conviction even when the record revealed another prior conviction not alleged in the indictment that could have properly been used to enhance.', 'general', 'Parrott, Ex Parte Jimmie Mark Jr.', 'https://www.courtlistener.com/opinion/2948851/', '2948851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rich stands for the propositions that, in general,
(1) an applicant is harmed by an illegal sentence when the appellate and ha-beas records show that he has no other conviction that could support the punishment range within which he was sentenced;', 'sentencing', 'Parrott, Ex Parte Jimmie Mark Jr.', 'https://www.courtlistener.com/opinion/2948851/', '2948851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 We held that he was estopped from complaining of the illegal sentence because “[a] defendant who has enjoyed the benefits of an agreed judgment prescribing a too-lenient punishment should not be allowed to collaterally attack that judgment on a later date on the basis of the illegal leniency.', 'sentencing', 'Parrott, Ex Parte Jimmie Mark Jr.', 'https://www.courtlistener.com/opinion/2948851/', '2948851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brooks, we held that “prior convictions used as enhancements must be pled in some form, but they need not be pled in the indictment — although it is permissible and perhaps preferable to do so.', 'general', 'Parrott, Ex Parte Jimmie Mark Jr.', 'https://www.courtlistener.com/opinion/2948851/', '2948851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the court of appeals’s judgment that upheld the trial court’s ruling to suppress the checks.', 'suppression', 'State of Texas v. Story, Kimberly Crystal', 'https://www.courtlistener.com/opinion/2949088/', '2949088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Justice requires that we reverse and remand appellant''s conviction and sentence for a new trial in which this novel scientific evidence is subjected to the newly formulated test.', 'sentencing', 'State v. Council', 'https://www.courtlistener.com/opinion/1335490/', '1335490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Council', 'https://www.courtlistener.com/opinion/1335490/', '1335490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'ref''d) ("We hold that the trial court, in suppressing Deputy Pikett’s testimony, reasonably could have concluded that his opinion was not reliable because of the inadequacies in his protocol, training and methods, and lack of oversight and verification of his test results.', 'suppression', 'Acosta, Victor Manuel', 'https://www.courtlistener.com/opinion/2949642/', '2949642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that dog “scent lineups” are different from tracking and narcotics detection, we held that “scent lineups,” when used alone or as primary evidence, are legally insufficient to support a conviction.', 'general', 'Acosta, Victor Manuel', 'https://www.courtlistener.com/opinion/2949642/', '2949642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it "was irrelevant to any issue that was then or later before the jury to decide, and was inherently prejudicial to the right of appellants to receive a fair and impartial trial before the jury.', 'general', 'Acosta, Victor Manuel', 'https://www.courtlistener.com/opinion/2949642/', '2949642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held exactly that in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*844We hold that, under the entire statutory scheme governing regular community supervision, the statutory language is plain in providing that appellant was ineligible for jury-recommended community supervision because, even though he received judicial clemency on an earlier community supervision, that conviction was resurrected for the limited purpose of probation ineligibility when he was convicted of the present offense.', 'general', 'Yazdchi v. State', 'https://www.courtlistener.com/opinion/2949784/', '2949784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 We hold that the court of appeals properly determined that the trial court rendered no “decision” or “ruling” and that appellant, therefore, failed to preserve the issue for consideration on appeal.', 'general', 'Yazdchi v. State', 'https://www.courtlistener.com/opinion/2949784/', '2949784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court of appeals properly determined that (1) appellant was not eligible for community supervision from the jury because his conviction in this case revived his earlier conviction for the limited purpose of probation ineligibility, even though his earlier conviction had been terminated by a discharge order that permitted him to withdraw his plea of guilty, dismissed the indictment, and set aside the verdict, and (2) appellant did not preserve his complaint that it is impermis...', 'dismissal', 'Yazdchi v. State', 'https://www.courtlistener.com/opinion/2949784/', '2949784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that a jury could find in its verdict that the defendant has never before been convicted of a felony when the record showed that Baker’s two convictions for aggravated robbery were on appeal at the time of the trial and, therefore, were not final convictions.', 'general', 'Yazdchi v. State', 'https://www.courtlistener.com/opinion/2949784/', '2949784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying principles of statutory construction to that provision, we find that its plain meaning supports the conclusion that appellant’s conviction “resurrected” for the limited purpose of probation ineligibility.', 'general', 'Yazdchi v. State', 'https://www.courtlistener.com/opinion/2949784/', '2949784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Yazdchi v. State', 'https://www.courtlistener.com/opinion/2949784/', '2949784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 After careful con*388sideration of the granted grounds, and to afford future litigants a “roadmap” to questions regarding court costs, we hold that (1) a claim with respect to the basis of court costs need not be preserved at trial to be raised for the first time on appeal, (2) Appellant’s claim is ripe for review, (8) a record on appeal can be supplemented with a bill of costs, (4) the document in the supplemental clerk’s record is a bill of costs, (5) the court of appeals erred when it fa...', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that Appellant need not have objected at trial to raise a claim challenging the bases of assessed costs on appeal.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the document contained in the first supplemental clerk’s record is a bill of costs for purposes of Chapter 103 of the Texas Code of Criminal Procedure dealing with the tracking and collecting of court costs.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that once the record was properly supplemented with a bill of costs, the court of appeals erred when it failed to consider that bill of costs when resolving Appellant’s court-costs claim.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that a specific amount of court costs need not be supported by a bill of costs in the appellate record for a reviewing court to conclude that the assessed court costs are supported by facts in the record.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court of appeals erred when it deleted the specific amount of court costs on the judgment of conviction, and we modify the judgment of the court of appeals to reinstate the deleted court costs and affirm the judgment as modified.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2010), in which this Court held that an objection is not required to raise such a claim, is distinguishable because that case dealt with the imposition of discretionary attorney’s fees, while this case deals with the imposition of mandatory, statutorily imposed costs.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the arguments of the parties and the authorities cited therein, we conclude that a criminal defendant need not preserve an objection in the trial court to raise a claim challenging the bases for the imposition of court costs for the first time on appeal.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a bill of costs is a relevant item that if omitted from the record, can be prepared and added to the record via a supplemental clerk’s record.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We first addressed the State’s argument that the appellant procedurally defaulted his attor-neyVfees claim because he failed to object to the imposition to the fees in the trial court, and we concluded that the appellant did not have to object at trial to raise his claim for the first time on appeal.', 'general', 'Johnson, Manley Dewayne', 'https://www.courtlistener.com/opinion/2950028/', '2950028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a conviction under Article 62.', 'general', 'Robinson, Leo Demory', 'https://www.courtlistener.com/opinion/2950353/', '2950353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Sec.', 'general', 'Robinson, Leo Demory', 'https://www.courtlistener.com/opinion/2950353/', '2950353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that McQueen, Young, and Penal Code § 6.', 'general', 'Robinson, Leo Demory', 'https://www.courtlistener.com/opinion/2950353/', '2950353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that sufficiency-of-the-evidence reviews in bench trials should be conducted under the well-established Jackson standard without consideration of a trial court’s unauthorized findings of fact and conclusions of law.', 'general', 'Robinson, Leo Demory', 'https://www.courtlistener.com/opinion/2950353/', '2950353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” 18 As a result, this Court held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an appellate court should disregard a trial court’s findings of fact and conclusions of law in their entirety, even when they support the trial court’s judgment.', 'general', 'Robinson, Leo Demory', 'https://www.courtlistener.com/opinion/2950353/', '2950353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals’ judgment.', 'general', 'Robinson, Leo Demory', 'https://www.courtlistener.com/opinion/2950353/', '2950353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a customer who becomes voluntarily intoxicated, even if served liquor in violation of HRS § 281-78(a)(2)(B), is not within the class of persons protected by the statute.', 'general', 'Delos Reyes v. Kuboyama', 'https://www.courtlistener.com/opinion/1349805/', '1349805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that even a minor who was sold liquor in violation of subsection (a)(2)(A) was not part of the class meant to be protected by that statute if he had become voluntarily intoxicated and injured himself, as had the plaintiffs in Bertelmann and Feliciano.', 'general', 'Delos Reyes v. Kuboyama', 'https://www.courtlistener.com/opinion/1349805/', '1349805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Kuboyama owed a duty to Tiffany not to sell liquor to a minor in violation of HRS chapter 281, we vacate the grant of summary judgment and remand this case for further proceedings.', 'general', 'Delos Reyes v. Kuboyama', 'https://www.courtlistener.com/opinion/1349805/', '1349805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that they are not.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”38 In yet another case, we held that the guilt-stage jury charge was in error in failing to instruct on the prior convictions required for, a felony-DWI offense because those prior convictions were essential elements of the offense.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '97 Nevertheless, citing Broughton and other cases construing Article 802b, we held that “[t]he addition of the prior theft convictions in the instant case created a new offense of the grade of felony and vested the District Court with jurisdiction just as the allegation of the prior conviction for driving while intoxicated created a felony offense under 802b.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,we held that “the prior theft offenses, as jurisdictional elements of the offense alleged, must be included in the body of the main *84charge before the jury is authorized to make a general finding of guilt.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984), wherein we held that a punishment allegation used for enhancement purposes does not constitute a new or different offense, -the prior conviction is, in the instant case, an element of the felony offense itself, and must be proved at the guilt-innocence stage of trial in order to authorize a conviction.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '57 We conclude that the inclusion of felony DWI and intoxication assault within the same chapter is a slight factor in favor of treating the offenses as the same.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On balance, we conclude that the offenses of felony DWI and intoxication assault are named similarly enough for that to be a *80slight factor in favor of treating the offenses as the same.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On balance, we conclude that the sameness of the punishment ranges in the present case is a slight factor in favor of treating the offenses as the same.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '135 We conclude that historical considerations weigh in favor of construing the offenses of felony DWI and intoxication assault to be different offenses for double-jeopardy purposes.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '56 In Shelby, we addressed intoxication assault, and we concluded that its appearance within that chapter — a separate chapter from the one containing the offense of aggravated assault — could have been a mere housekeeping measure and provided “minimal guidance” on what the legislature intended.', 'general', 'Benson, Yusulf Shaheed', 'https://www.courtlistener.com/opinion/2950623/', '2950623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the principles announced in Long, Chrisman, and Hensley, we hold that police officers may, whenever they possess an articulable and objectively reasonable belief that a suspect is presently or potentially dangerous, conduct a protective search of the area within the suspect''s immediate control.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we find that the "stop" of the defendant was clearly valid.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we do not go so far as to adopt such a per se rule in a Terry context, we find that the concerns present in an arrest situation may also be present in an investigatory detention.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that this holding is necessary in the interest of police protection.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that Officer Farmer''s warrantless entry into the motel room was reasonable.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that the impoundment of the defendant''s car was reasonable.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Guided by these principles, we find that the evidence was sufficient to support convictions of possession of marijuana and cocaine with the intent to distribute.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgments of the trial court.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the State can proceed with the charge of perjury against Canon if the circuit judge finds that the new evidence proffered by the State satisfies the requirements set forth above.', 'general', 'State v. Canon', 'https://www.courtlistener.com/opinion/1348991/', '1348991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'State v. Canon', 'https://www.courtlistener.com/opinion/1348991/', '1348991') ON CONFLICT DO NOTHING;
