INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, in connection with the charge of attempted sexual assault in the second degree, we hold that the circuit court erred in refusing to instruct the jury regarding the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that neither sexual assault in the fourth degree nor attempted sexual assault in the fourth degree are included offenses of attempted sexual assault in the second degree, within the meaning of HRS § 701-109(4)(a).', 'general', 'State v. Kinnane', 'https://www.courtlistener.com/opinion/1213794/', '1213794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because sexual assault in the fourth degree, in violation of HRS § 707-733(l)(a), and attempted sexual assault in the fourth degree, in violation of HRS §§ 705-500 and 707-733(l)(a), are included offenses of the charged offense pf attempted sexual assault in the second degree, in violation of HRS §§ 705-500 and 707-731(l)(a), we hold that the circuit court erred in refusing, over Kin-nane’s objection, to instruct the jury with respect to them.', 'general', 'State v. Kinnane', 'https://www.courtlistener.com/opinion/1213794/', '1213794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm the ICA’s decision.', 'general', 'State v. Kinnane', 'https://www.courtlistener.com/opinion/1213794/', '1213794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that there was a rational basis in the evidence for the jury to find beyond a reasonable doubt that Kinnane knowingly subjected the complainant to sexual contact by compulsion and thus to convict him of sexual assault in the fourth degree.', 'general', 'State v. Kinnane', 'https://www.courtlistener.com/opinion/1213794/', '1213794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that there was a rational basis in the evidence for the jury to convict Kinnane of attempted sexual assault in the fourth degree.', 'general', 'State v. Kinnane', 'https://www.courtlistener.com/opinion/1213794/', '1213794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being the case, and attempted sexual assault in the fourth degree being an included offense of sexual assault in the fourth degree pursuant to HRS § 701-109(4)(b), we therefore hold that sexual assault in the fourth degree and attempted sexual assault in the fourth degree are included offenses of attempted sexual assault in the second degree, within the meaning of HRS § 701-109(4)(c).', 'general', 'State v. Kinnane', 'https://www.courtlistener.com/opinion/1213794/', '1213794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 745 (1994), comports with the protections afforded under the Vermont Constitution, we affirm.', 'general', 'State v. Porter', 'https://www.courtlistener.com/opinion/1437588/', '1437588') ON CONFLICT DO NOTHING;
