INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004), we find that Berry''s request to proceed pro se was unequivocal and that his decision was knowingly, intelligently and voluntarily made.', 'general', 'Commonwealth v. Berry', 'https://www.courtlistener.com/opinion/1465718/', '1465718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse the Court of Appeals'' decision and reinstate Berry''s conviction and sentence in accordance with the trial court''s judgment.', 'sentencing', 'Commonwealth v. Berry', 'https://www.courtlistener.com/opinion/1465718/', '1465718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record here sustains the trial court’s finding that the officials were confronting an emergency law enforcement situation, and that their urgent need to act as quickly as possible justified proceeding without a warrant.', 'general', 'Tuck v. United States', 'https://www.courtlistener.com/opinion/1506518/', '1506518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bearing in mind the oft-repeated thought that what may appear to be small in principal may loom large in principle, we conclude that the exigencies of the situation militated against delay and were of a sufficient proportion to justify proceeding without a warrant.', 'general', 'Tuck v. United States', 'https://www.courtlistener.com/opinion/1506518/', '1506518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the indictment was not constructively amended and that, although there was a variance between the indictment and the evidence presented at trial, Carter neither claimed prejudice nor made any evidentiary showing that the variance impaired his defense.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/1989377/', '1989377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judge was familiar with, the statute and that, notwithstanding her failure explicitly to mention the portion of the thigh with which Carter had contact, she effectively found Carter guilty of a sexual touching of the inner thigh.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/1989377/', '1989377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/1989377/', '1989377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1153 (1976), this Court held that the trial court had committed plain error in instructing the jury on first-degree murder when the facts in the record did not support the charge.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 218, this Court held the defendant''s confession admissible despite the fact that the interrogating officer had given assurance that he was acting solely in the defendant''s interest.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*643 Against that background, we conclude that the Legislature by its use of the term "mental disease or defect" did not intend to preclude evidence of a mental condition consisting of a "disorder" as such.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant did provide expert testimony sufficient to warrant a jury instruction on diminished capacity.', 'jury_instruction', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the interrogation that elicited defendant''s confession did not violate his rights against self-incrimination, and that his confession was the result of a knowing, voluntary, and intelligent waiver of those rights, in accordance with the Miranda standards.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was not sufficient to justify the submission of the third-degree child-endangerment charge to the jury.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to defendant, we find that it offers at least the suggestion that defendant''s faculties were sufficiently affected to preclude him from engaging in purposeful or knowing conduct when he harmed the infant.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*650 Accordingly, we find that the improper instruction withdrawing the defense of diminished capacity from the jury constituted harmful error and requires the reversal of defendant''s conviction for murder.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our construction of the statute, we find that the trial court''s instruction was plainly erroneous in that it failed to instruct the jury that to find that defendant had assumed responsibility for the child within the meaning of the statute, it must find that he had assumed a caretaking function over the child on a continuing, regular, or recurrent basis.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division, which sustained the convictions for murder and third-degree child endangerment, and remand the matter for a new trial.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
