INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'section 13-1502(A), we conclude that it applies to both private and public property.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the court correctly denied Appellant''s Rule 20(a) motion for acquittal with respect to the charge of third-degree criminal trespass.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Huddleston analysis here, we conclude that the trial court did not abuse its discretion by admitting testimony about these acts in evidence.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion by admitting in evidence testimony concerning Appellant''s two prior acts.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that the court''s comments to Appellant were entirely appropriate under the circumstances.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a person can be convicted of third-degree criminal trespass on public property pursuant to A.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[5] Therefore, we hold that the trial court erred when it joined the identity-theft offense with the three theft-by-swindle offenses because the theft-by-swindle offenses, while related to the identity-theft offense, were unrelated to each other.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wakefield, reasoning that it is fundamentally unfair for the state to force a defendant to again defend against alleged conduct after the defendant has successfully done so once, we held that evidence related to a crime for which the defendant has been acquitted may not be used as Spreigl evidence.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that neither due process nor fundamental fairness would have prevented evidence of the Sears offense from being used as Spreigl evidence at separate trials of the offenses had the trials been properly severed and the evidence otherwise met the requirements for the admission of Spreigl evidence.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we conclude that the record contains admissible evidence connecting Ross to each of the theft-by-swindle offenses sufficient to meet the clear and convincing standard.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that evidence of Ross''s participation in each theft-by-swindle offense is relevant to a determination of Ross''s guilt with respect to each of the other theft-by-swindle offenses.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the probative value of the evidence outweighs the potential for unfair prejudice to Ross.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that admission of evidence of the improperly joined offenses would have been admissible as Spreigl evidence had the offenses been properly severed for trial, we also conclude that the improper joinder of the offenses was not prejudicial to Ross regarding determination of his guilt or innocence.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979) (stating that "we conclude that under no circumstances *284 is evidence of a crime other than that for which a defendant is on trial admissible when the defendant has been acquitted of that other offense.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand to the court of appeals for determination of any remaining properly raised issues.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the court of appeals and reinstate Ross''s convictions, we remand these issues to the court of appeals for further consideration.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Souter did not abuse his discretion when he permitted that testimony over Collins’s objection.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this issue was waived.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was not an abuse of discretion for Judge Souter to admit the contested documents as circumstantial evidence of drug activity because the issue of trafficking in controlled substances is a material issue to count II.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Collins’s conviction on these counts must be reversed for the reasons expressed in Judge Mannheimer’s concurring opinion.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the record, we conclude that reasonable jurors could agree that the prosecution had proven this count beyond a reasonable doubt.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE his conviction for maintaining a crack house and REMAND for entry of a judgment of acquittal on that count.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE Collins’s conviction of possession of a firearm during the commission of a felony drug offense and REMAND for a new trial on that count.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained here, we AFFIRM Collins’s convictions for possession of cocaine and possession of an altered firearm.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*752We held that, because Steve was attacking his conviction on a legal ground that did not require resolution of any of the facts of the case, his pleading was not a “motion for judgement of acquittal”, and the granting of his motion would not preclude the State from re-trying him:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Collins’s conviction for violating the crack house statute must be reversed.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that AS 11.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we do not recommend this practice, we find that Judge Hawkins’ receipt of the jury’s verdict was merely a ministerial duty and did not really involve judicial participation.', 'general', 'State v. Schrock', 'https://www.courtlistener.com/opinion/1187771/', '1187771') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1036 (1982), we held that the denial of a petition to revoke probation, based on the state''s failure to establish a probation violation, did not collaterally estop the state from prosecuting the defendant for sexual assault, even though the sexual assault was the basis for the probation revocation petition.', 'general', 'State v. Nunez', 'https://www.courtlistener.com/opinion/1379263/', '1379263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 756, 765 (1960), this court held that an earlier judgment in a criminal case was conclusive as to all issues actually litigated and adjudicated.', 'general', 'State v. Nunez', 'https://www.courtlistener.com/opinion/1379263/', '1379263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without unduly prolonging this opinion, it is sufficient to say that, based upon our review of the entire record, we find that sufficient evidence exists to withstand defendant''s motion for acquittal.', 'general', 'State v. Nunez', 'https://www.courtlistener.com/opinion/1379263/', '1379263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant''s conviction and vacate that part of the court of appeals'' opinion designated "Double Jeopardy and Collateral Estoppel.', 'general', 'State v. Nunez', 'https://www.courtlistener.com/opinion/1379263/', '1379263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the defendant received a fair trial free from prejudicial error.', 'general', 'State v. Eason', 'https://www.courtlistener.com/opinion/1217322/', '1217322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and giving proper deference to the decision of the magistrate to issue the search warrant, we conclude that there was more than a “substantial basis” for his determination that probable cause existed.', 'probable_cause', 'State v. Eason', 'https://www.courtlistener.com/opinion/1217322/', '1217322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err by admitting the finger as evidence, because its probative value as to the issue of the identity of the victim was not substantially outweighed by any danger of unfair prejudice.', 'general', 'State v. Eason', 'https://www.courtlistener.com/opinion/1217322/', '1217322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given such testimony, we conclude that there was a sufficient basis upon which the expert could base his opinion;', 'general', 'State v. Eason', 'https://www.courtlistener.com/opinion/1217322/', '1217322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing Captain Gosnell’s answer, which was preserved for the record, we conclude that it fails to meet the test of relevancy under Rule 401.', 'general', 'State v. Eason', 'https://www.courtlistener.com/opinion/1217322/', '1217322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion.', 'general', 'State v. Eason', 'https://www.courtlistener.com/opinion/1217322/', '1217322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the defendant received a trial free from prejudicial error.', 'general', 'State v. Eason', 'https://www.courtlistener.com/opinion/1217322/', '1217322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the particular course chosen by counsel had some reasonable basis, our inquiry ceases and counsel''s assistance is deemed effective.', 'general', 'Commonwealth v. Yager', 'https://www.courtlistener.com/opinion/2304642/', '2304642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has not established manifest injustice requiring the withdrawal of his guilty plea.', 'plea', 'Commonwealth v. Yager', 'https://www.courtlistener.com/opinion/2304642/', '2304642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '("We find that the absence of this inquiry from the transcript renders the colloquy defective" [615 A.', 'general', 'Commonwealth v. Yager', 'https://www.courtlistener.com/opinion/2304642/', '2304642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We affirm.', 'general', 'Commonwealth v. Yager', 'https://www.courtlistener.com/opinion/2304642/', '2304642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a two-year misdemeanor conviction arising out of the first felony charge may serve as the "conviction of the prior charged offense” required for consecutive sentencing.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a charge remains "pending” for purposes of this statute until a defendant is sentenced on a conviction arising out of the offense, and until the original charge arising out of the offense is dismissed.', 'dismissal', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the right to counsel is violated, and a defendant must be resentenced, if the sentencing judge obtains information about the *435defendant from the probation officer that is not included in the written presentence report.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that two-year misdemeanors may be considered "felonies” for whatever purposes that word is used in the consecutive sentencing statute.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the constitutional guarantee of an appeal as a matter of right from criminal prosecutions required that an indigent be provided with *445appointed appellate counsel and a free transcript of the proceedings at trial, noting that "[t]he name ''felony’ or ''misdemeanor’ can make small difference as relates to [defendant’s] constitutional right to such assistance.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More recently, we held that the need for "complete, accurate, and reliable” information at sentencing required the use of a reasonably updated presentence report in sentencing for felonies.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In order to achieve the Legislature’s intended purpose in the Code of Criminal Procedure, we find that the Legislature meant exactly what it said: Offenses punishable by more than one year of imprisonment are "felonies” for purposes of the habitual-offender, probation, and consecutive sentencing statutes.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions of Timothy Smith under the habitual-offender statutes, because the two-year misdemeanor convictions which served as the bases for his habitual-offender charges could be considered "felonies” for purposes of the habitual-offender statutes.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the sentences given to Paul Wallace *447and David Shoup, because the two-year misdemeanors of which they were convicted could be considered "felonies” for purposes of the probation statute.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all the reasons above, we affirm the convic*460tions of and sentences received by all four defendants.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Parole Board failed to abide by the enumerated time limits within which to hold Valentine''s final revocation hearing, we conclude that, if his conduct so warranted, he was entitled to receive good time credit for the additional time he was detained in the Marion County Jail as a result of the Parole Board''s delay.', 'general', 'State Ex Rel. Valentine v. Watkins', 'https://www.courtlistener.com/opinion/1396259/', '1396259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the Parole Board failed to conduct Valentine''s parole revocation hearing within the time allowed for such a proceeding, we find that he is entitled to good time credit for that period of his detention necessitated by the Parole Board''s delay.', 'general', 'State Ex Rel. Valentine v. Watkins', 'https://www.courtlistener.com/opinion/1396259/', '1396259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that the petition charging possession of a stolen motor vehicle was fatally defective because it failed to allege the essential element that the juvenile knew or had reason to believe the vehicle was stolen or unlawfully taken.', 'general', 'In the Matter of Kjh', 'https://www.courtlistener.com/opinion/1387266/', '1387266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing a challenge to the sufficiency of the evidence, we view the evidence in a light most favorable to the State, considering only the evidence that supports the verdict, and we affirm if substantial evidence exists to support it.', 'general', 'DeShazer v. State', 'https://www.courtlistener.com/opinion/1394169/', '1394169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'DeShazer v. State', 'https://www.courtlistener.com/opinion/1394169/', '1394169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the legislature could
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the language of article I, section 22, and given the deference that we should pay to the decision of a co-equal branch of government, we conclude that the legislature’s four-ounce dividing line is presumptively constitutional under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Noy’s conviction.', 'general', 'Noy v. State', 'https://www.courtlistener.com/opinion/2629180/', '2629180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the report of the chemical analysis in Ingram’s case was virtually identical to the type of report considered by the supreme court in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we held that consecutive sentences for more than one offense may not exceed the presumptive term for the more serious offense unless lengthier incarceration is necessary to protect the public.', 'sentencing', 'Gibson v. State', 'https://www.courtlistener.com/opinion/1188072/', '1188072') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that in order to be charged with MICS involving marijuana, a person must be in possession of a substance that contains its seeds, leaves, buds or flowers;', 'general', 'Gibson v. State', 'https://www.courtlistener.com/opinion/1188072/', '1188072') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Gibson’s conviction, but remand for resentencing.', 'sentencing', 'Gibson v. State', 'https://www.courtlistener.com/opinion/1188072/', '1188072') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court lacked personal jurisdiction to enter a final RFA order, and reverse.', 'general', 'Fox v. Fox', 'https://www.courtlistener.com/opinion/2718135/', '2718135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s assault of plaintiff in New Hampshire does not by itself support personal jurisdiction for a final RFA order in Vermont.', 'general', 'Fox v. Fox', 'https://www.courtlistener.com/opinion/2718135/', '2718135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court lacked the personal jurisdiction required to issue a final RFA order, we need not reach the other issues defendant raises in his appeal.', 'general', 'Fox v. Fox', 'https://www.courtlistener.com/opinion/2718135/', '2718135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, in an action alleging unlawful discharge in violation of HRS § 378-2, the time for filing an administrative complaint begins to run on the date that the employee is actually discharged, that is, on the date that his or her employment terminates.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that if Ross prevails on his marital discrimination claim (count I) following remand, he is entitled to appropriate equitable relief, including backpay, as provided in HRS § 378-5(f), but he cannot recover any compensatory damages or punitive damages on that claim.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court properly granted summary judgment in favor of Stouffer on count II of Ross''s amended complaint.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court properly entered summary judgment in favor of Stouffer on Ross''s negligent infliction of emotional distress claim.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Ross cannot recover punitive damages for tortious breach of contract and that the circuit court properly dismissed count V of Ross''s amended complaint.', 'dismissal', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As noted above, because Ross has not assigned the dismissal of count VI as a point of error on appeal and has not addressed the claim in his briefs, we hold that he has waived any argument that count VI was improperly dismissed.', 'dismissal', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we share Ross''s concern about "piecemeal" litigation, especially with respect to cases assigned to the Court Annexed Arbitration Program, which is intended "to provide a prompt and equitable resolution of certain civil matters[,]" HAR 2(A) (1991), we hold that Stouffer''s motion for partial summary judgment, which sought dismissal of six of Ross''s seven claims, did not violate HAR 7(F).', 'dismissal', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Ross has not assigned the dismissal of count VI as a point of error on appeal and has completely failed to mention that claim in either his opening or reply briefs, we hold that he has waived any argument that count VI was improperly dismissed.', 'dismissal', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1073 (1988), where we held that the tolling provisions of HRS § 657-13 applied to toll the two year statute of limitations set forth in HRS § 294-36 for bringing a suit for *1056 no-fault benefits.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it removes any doubt about when the filing period begins, it has the beneficent effect of avoiding the protracted and expensive litigation over the precise date and adequacy of an employer''s notice of termination that would inevitably result if we concluded that the date of notice triggered the filing period.', 'general', 'Ross v. Stouffer Hotel Co. (Hawai''i) Ltd.', 'https://www.courtlistener.com/opinion/1159042/', '1159042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that by changing the aggravating circumstance from entering during the darkness to causing physical injury, the amendment to the indictment "substituted an entirely different [offense] for the one charged.', 'general', 'State v. Guthrie', 'https://www.courtlistener.com/opinion/1389574/', '1389574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Guthrie', 'https://www.courtlistener.com/opinion/1389574/', '1389574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the re-entry into a continuing conspiracy subsequent to the defendant''s arrest is, for purposes of double jeopardy, the formation of a new agreement.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/1389694/', '1389694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8] Under several authorities, we find that it is.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/1389694/', '1389694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We affirm in result.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/1389694/', '1389694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record before us, we hold that defendant did not intentionally waive his right to counsel at the preliminary hearing.', 'general', 'Davila v. State', 'https://www.courtlistener.com/opinion/1399044/', '1399044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Blonigen, Assistant District Attorney, and the Court having found that the County Court Judge did not abuse his discretion in denying a continuance in this matter at the preliminary hearing, it is ordered that the Defendant''s Motion to Dismiss should be, and is hereby, denied.', 'dismissal', 'Davila v. State', 'https://www.courtlistener.com/opinion/1399044/', '1399044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Davila v. State', 'https://www.courtlistener.com/opinion/1399044/', '1399044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Decker', 'https://www.courtlistener.com/opinion/1216638/', '1216638') ON CONFLICT DO NOTHING;
