INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court’s decision.', 'general', 'Davis v. Commonwealth', 'https://www.courtlistener.com/opinion/1217358/', '1217358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the trial court’s decision.', 'general', 'Davis v. Commonwealth', 'https://www.courtlistener.com/opinion/1217358/', '1217358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this sentence was not clearly mistaken.', 'sentencing', 'Jones v. State', 'https://www.courtlistener.com/opinion/1394803/', '1394803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we find that the judge did not communicate a bias against Hartley to the jury or suggest in any manner that he did not believe Hartley.', 'general', 'Hartley v. State', 'https://www.courtlistener.com/opinion/1188355/', '1188355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the state has no discretion to suppress evidence of past convictions or aggravating or mitigating factors.', 'suppression', 'Hartley v. State', 'https://www.courtlistener.com/opinion/1188355/', '1188355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Taylor''s refusal to take the field sobriety tests was not elicited in violation of his statutory or constitutional rights and its use at trial does not offend constitutional principles.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1747207/', '1747207') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that the officers articulated a reasonable suspicion based on a number of objective facts.', 'general', 'State v. Frisby', 'https://www.courtlistener.com/opinion/1404326/', '1404326') ON CONFLICT DO NOTHING;
