INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this is the proper extent of inquiry.', 'general', 'State v. Via', 'https://www.courtlistener.com/opinion/1189091/', '1189091') ON CONFLICT DO NOTHING;
