INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only in the event of an abuse of this discretion will we reverse.', 'general', 'State v. Via', 'https://www.courtlistener.com/opinion/1189091/', '1189091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the state does not have the right to appeal.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/1219472/', '1219472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these arguments have merit and reverse and remand.', 'general', 'Tackett v. State', 'https://www.courtlistener.com/opinion/1495542/', '1495542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As for his other complaints, we held that they were not yet ripe for decision.', 'general', 'Tackett v. State', 'https://www.courtlistener.com/opinion/1495542/', '1495542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 216 (1981), we held that a prior conviction was admissible to enhance punishment pursuant to the Habitual Offender Act (Ark.', 'general', 'Tackett v. State', 'https://www.courtlistener.com/opinion/1495542/', '1495542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we find that the trial court abused its discretion in ruling that the prosecution could impeach Tackett''s testimony with these prior convictions.', 'general', 'Tackett v. State', 'https://www.courtlistener.com/opinion/1495542/', '1495542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the issue is moot, we dismiss the appeal.', 'dismissal', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1219517/', '1219517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. DiPietro', 'https://www.courtlistener.com/opinion/1490767/', '1490767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury in this case was not required to unanimously agree on any of these theories.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1401703/', '1401703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of the record, we conclude that the inconsistencies in the expert testimony did not render that testimony so unreliable that a jury could not have resolved those inconsistencies to reach the verdict rendered in this case.', 'general', 'Commonwealth v. Hlatky', 'https://www.courtlistener.com/opinion/1478293/', '1478293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Commonwealth sustained this burden.', 'general', 'Commonwealth v. Hlatky', 'https://www.courtlistener.com/opinion/1478293/', '1478293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hlatky’s claim that the trial court failed to place sufficient reasons for his sentence on the record presents a substantial question.', 'sentencing', 'Commonwealth v. Hlatky', 'https://www.courtlistener.com/opinion/1478293/', '1478293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of the sentencing transcript in this case, we conclude that there was no abuse of discretion on the part of sentencing court and we dismiss this claim as merit-less.', 'dismissal', 'Commonwealth v. Hlatky', 'https://www.courtlistener.com/opinion/1478293/', '1478293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Hlatky', 'https://www.courtlistener.com/opinion/1478293/', '1478293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, based on the foregoing, we affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Hlatky', 'https://www.courtlistener.com/opinion/1478293/', '1478293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the instruction was proper and not an abuse of discretion in a specific intent case.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), this court held that the evidence of restraint necessary to establish kidnapping must go beyond that which is incidental to the underlying offense.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the trial court did not abuse its discretion in denying McDonald’s motion to dismiss the indictment.', 'dismissal', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in admitting the photographs.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the evidence and the inferences drawn therefrom in the light most favorable to the state, we conclude that sufficient evidence was presented to allow fair-minded persons to reasonably differ on whether guilt has been established beyond a reasonable doubt.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in rejecting McDonald’s proposed instructions.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reading the instructions as a whole, as the jury was expressly told to do, we conclude that Instruction 32 did not unconstitutionally draw attention to McDonald’s failure to testify.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion in refusing to find that a new trial was warranted on the ground of newly discovered evidence.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we ultimately conclude that the disputed testimony was admissible at trial, we find that its admission before the grand jury was also proper.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, we find that McDonald has made no showing of prejudice.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/1189735/', '1189735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'none have merit, and we affirm.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/1506642/', '1506642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the relevant statutes and ease law, the record on appeal and the parties’ arguments, we conclude that the Commissioner erred by revoking Coil’s license without having first reviewed the secondary chemical test results;', 'general', 'Coll v. Cline', 'https://www.courtlistener.com/opinion/1333388/', '1333388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the Commissioner had the authority and the jurisdiction to consider the revocation of Coil’s license to drive.', 'general', 'Coll v. Cline', 'https://www.courtlistener.com/opinion/1333388/', '1333388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the specific statutory question presented by the parties, however, we conclude that while Commissioner Cline had jurisdiction to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a reasonable delay caused by the Commissioner’s efforts to correct the error did not violate the revokee’s due process rights.', 'general', 'Coll v. Cline', 'https://www.courtlistener.com/opinion/1333388/', '1333388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it is not.', 'general', 'Coll v. Cline', 'https://www.courtlistener.com/opinion/1333388/', '1333388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Code § 17A-2-9, we find that the above-quoted statute outlines the procedural and evidentiary requirements for revocation.', 'general', 'Coll v. Cline', 'https://www.courtlistener.com/opinion/1333388/', '1333388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we find that the results of a secondary chemical test to determine the blood alcohol concentration of an individual who has been arrested for driving under the influence of alcohol are not a jurisdictional prerequisite to the Commissioner’s authority to revoke a driver’s license.', 'general', 'Coll v. Cline', 'https://www.courtlistener.com/opinion/1333388/', '1333388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the July 18, 1997, order of the Circuit Court of Harrison County, and reinstate the final order of the Commissioner of the West Virginia Division of Motor Vehicles, entered January 15,1997.', 'general', 'Coll v. Cline', 'https://www.courtlistener.com/opinion/1333388/', '1333388') ON CONFLICT DO NOTHING;
