INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Ramirez’s plea was valid, we hold that withdrawal of the plea was not necessary to correct a manifest injustice, and the trial court did not abuse its discretion in denying Ramirez’s motion to withdraw his plea.', 'plea', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1190311/', '1190311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, based solely on the information ascertained by the judge at the change of plea hearing, we conclude that the judge did ascertain that there was a strong factual basis for the plea, and that Ramirez did enter his plea knowingly and voluntarily.', 'plea', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1190311/', '1190311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the district court did not abuse its discretion in refusing to hold a hearing and to allow Ramirez to be present at such hearing on Ramirez’s Rule 35 motion.', 'general', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1190311/', '1190311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1190311/', '1190311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts and reasoning set forth above, we affirm the district court’s denial of Ramirez’s motion to withdraw his plea and his motion to reduce his sentence.', 'sentencing', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1190311/', '1190311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the trial court in that case based its ruling on Rule of Evidence 608(b), governing admissibility of specific instances of conduct bearing on truthfulness or untruthfulness, this Court held “that the trial court erred in excluding [the] evidence because it was admissible impeachment evidence under Rule 611(b).', 'general', 'State v. Whaley', 'https://www.courtlistener.com/opinion/1224085/', '1224085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held the error prejudicial and awarded the defendant a new trial.', 'general', 'State v. Whaley', 'https://www.courtlistener.com/opinion/1224085/', '1224085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Whaley', 'https://www.courtlistener.com/opinion/1224085/', '1224085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and remand this case to that court
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the limitation placed upon the state’s right to appeal in a criminal case, found in AS 22.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 We hold that the superior court’s decision that in a case of direct contempt the contemnor is entitled to a jury trial, in regard to his purportedly contumacious conduct, is of such importance and substance as to justify our review of the matter.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that direct criminal con-tempts must be treated like any other criminal prosecution for purposes of the right to jury trial under article I, section 11 of the Alaska Constitution.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant was entitled to a jury trial.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that “willful disregard or disobedience of the authority or orders of the court” was a necessary element of indirect contempt.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 375 (Alaska 1960), where this court held that the superior court’s denial of a jury trial affected a substantial right of the petitioner under Supreme Ct.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '9 In view of these factors, we conclude that the case comes within the purview of Supreme Court Rule 23(c) (3).', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Rather, we find that a right to jury trial in a direct criminal contempt situation is “necessary for the kind of civilized life and ordered liberty which is at the core of our constitutional heritage.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It then appealed the dismissal of its petition, and we affirmed the superior court’s dismissal of the petition for review.', 'dismissal', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the state can invoke our discretionary review jurisdiction in criminal cases where the matter sought to be reviewed involves a non-final order or decision of the superior court.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the one house veto provision contained in § 233(c)(2) of the Home Rule Act is invalid based on Immigration &amp;', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that none of the appellants is entitled to relief.', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reject Pee''s suggestion that we conclude that without the legislative veto, Congress would have rejected home rule because of "a distrust of the Democratic, liberal and largely black government that would result.', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Johnson, supra, we conclude that our decision should have prospective effect only, from the date of our decision.', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*836 We find that the trial court''s error was harmless beyond a reasonable doubt.', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thereafter, we held that severance was appropriate where the State would have been unable to introduce a statement by the co-defendant at a joint trial because it could not be redacted, without substantially altering its meaning, to meet the requirements of Bruton v.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the verdict was facially void because it in no way complied with the requirement of the determinate sentence law in effect at the time of sentencing.', 'sentencing', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Middlebrooks a majority of this Court held that, when a defendant is convicted of first-degree murder solely on the basis that the murder was committed during the course of a felony, then the felony-murder aggravating circumstance does not narrow the class of death eligible defendants because it duplicates exactly the elements of the offense supporting the conviction that made the defendant death-eligible.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under the present record, the defendant has failed to show that he was prejudiced by the trial court''s granting the severance.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that neither the state nor the federal constitution prohibited admission of Stephenson''s confession.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree that courts should give a broad interpretation to a suspect''s request for counsel, we conclude that the defendant''s question herein constituted an equivocal invocation of the right to counsel that limited further interrogation to questions clarifying his desire for an attorney.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the facts in this record in accordance with the analysis utilized in Street, we conclude that the defendant''s Sixth Amendment right of confrontation was not violated.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that there is no statutory, common-law, or constitutional right to allocution in a capital case.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that .', 'general', 'Barnett v. State', 'https://www.courtlistener.com/opinion/1191894/', '1191894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being the case, we hold that the remedy being sought by Barnett is not available in this case.', 'general', 'Barnett v. State', 'https://www.courtlistener.com/opinion/1191894/', '1191894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that HRS § 706-669 allows victims or their representatives the opportunity to make oral comments at minimum prison term hearings before the HPA, Barnett’s contention in his HRPP Rule 40 petition that the HPA erred by allowing the mothers of two victims the opportunity to comment at the minimum term hearing was patently without merit and did not establish a colorable claim for purposes of HRPP Rule 40.', 'general', 'Barnett v. State', 'https://www.courtlistener.com/opinion/1191894/', '1191894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we reverse the ICA’s decision and affirm the circuit court’s order denying Barnett’s HRPP Rule 40 petition.', 'general', 'Barnett v. State', 'https://www.courtlistener.com/opinion/1191894/', '1191894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we reverse the ICA’s decision and affirm the circuit court’s order denying Barnett’s HRPP Rule 40 petition filed April 24,1996.', 'general', 'Barnett v. State', 'https://www.courtlistener.com/opinion/1191894/', '1191894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 1 We hold that driving on a DUI-suspended license is a jury-eligible offense and that Arizona Revised Statutes Annotated (“A.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that section 22-320 applies to all lower courts.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 21 We hold that section 22-320 is constitutional.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that driving on a DUI-suspended license is a jury-eligible offense and that A.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 8 When we apply the Rothweiler analysis and follow its holding, as all courts inferior to the supreme court must do, we conclude that a person charged with driving on a DUI-suspended license is entitled to a jury in Arizona for the same reasons that a person charged with DUI is entitled to a jury in Arizona.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because these different procedures were incorporated into the constitution without substantive change, we conclude that a reasonable basis exists for having different jury waiver procedures in inferior and superior courts.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 23 We conclude that Rule 18.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 24 We conclude that a defendant validly waives the right to a jury by failing to comply with section 22-320 after having been given timely notice of both the right to a jury and the provisions of section 22-320.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse only if
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Steven Anderson v. State of Indiana', 'https://www.courtlistener.com/opinion/2724420/', '2724420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 Accordingly, we affirm.', 'general', 'Steven Anderson v. State of Indiana', 'https://www.courtlistener.com/opinion/2724420/', '2724420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Persuaded by public policy reflecting a clear judicial trend across the nation to allow such a cause of action, we held that the liquor control statute, HRS § 281-78(a)(2)(B) (1976),
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the strong presumption that motions for change of venue should not be decided until voir dire has at least been attempted, we hold that Judge Cutler did not abuse her discretion in denying Wylie''s pretrial motion without prejudice and leaving the issue to be reconsidered after voir dire examination.', 'general', 'Wylie v. State', 'https://www.courtlistener.com/opinion/1192101/', '1192101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), we held that ordinarily a first felony offender convicted of an offense should receive a more favorable sentence than the presumptive term for a second felony offender.', 'sentencing', 'Wylie v. State', 'https://www.courtlistener.com/opinion/1192101/', '1192101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that the presumptive term for a second felony offender constitutes a ceiling on an appropriate sentence for a first felony offender in the absence of aggravating factors, or the kind of extraordinary circumstances that would warrant referral of a second felony offender to a three-judge panel for sentencing.', 'sentencing', 'Wylie v. State', 'https://www.courtlistener.com/opinion/1192101/', '1192101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in accordance with the Iowa and California courts, we find that when a passenger jumps from a moving vehicle and as a result suffers injury or death, the motorist is obligated to stop and render assistance and notify the proper authorities.', 'general', 'Wylie v. State', 'https://www.courtlistener.com/opinion/1192101/', '1192101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that giving Instruction 33 was not prejudicial error in this case.', 'general', 'Wylie v. State', 'https://www.courtlistener.com/opinion/1192101/', '1192101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But given the limited evidence of domestic problems and the strength of the evidence of intoxication, we find that any error was harmless.', 'general', 'Wylie v. State', 'https://www.courtlistener.com/opinion/1192101/', '1192101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Wylie’s conviction but vacate his sentence and remand for resentencing.', 'sentencing', 'Wylie v. State', 'https://www.courtlistener.com/opinion/1192101/', '1192101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the parties do not challenge this portion of the district court’s order, and since we hold that Moon’s RICO pleading fails on other grounds, we decline to express an opinion on this subject.', 'plea', 'Moon v. Harrison Piping Supply', 'https://www.courtlistener.com/opinion/2974425/', '2974425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that a single scheme emanating from a dispute over an ordinary construction contract did not possess the requisite RICO continuity:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the Complaint lacks facts establishing a “pattern of racketeering activity,” and thus fails to state a RICO claim, we do not address any of the other RICO elements.', 'general', 'Moon v. Harrison Piping Supply', 'https://www.courtlistener.com/opinion/2974425/', '2974425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because deciding Moon’s state-law claim was unnecessary, we REVERSE the district court’s exercise of pendent jurisdiction, and REMAND with instructions to dismiss those claims without prejudice.', 'dismissal', 'Moon v. Harrison Piping Supply', 'https://www.courtlistener.com/opinion/2974425/', '2974425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE the district court’s dismissal of Moon’s claim for intentional infliction of emotional distress, and REMAND with instructions to dismiss that claim without prejudice.', 'dismissal', 'Moon v. Harrison Piping Supply', 'https://www.courtlistener.com/opinion/2974425/', '2974425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Moon failed sufficiently to'' allege a pattern of racketeering activity for purposes of RICO, we AFFIRM the district court’s judgment with respect to Moon’s RICO claim.', 'general', 'Moon v. Harrison Piping Supply', 'https://www.courtlistener.com/opinion/2974425/', '2974425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons described above, we AFFIRM the district court’s judgment dismissing Moon’s RICO claims under Rule 12(b)(6).', 'dismissal', 'Moon v. Harrison Piping Supply', 'https://www.courtlistener.com/opinion/2974425/', '2974425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons described above, we AFFIRM the district court’s dismissal of Moon’s RICO claim for failure to state a claim upon which relief can be granted under Rule 12(b)(6).', 'dismissal', 'Moon v. Harrison Piping Supply', 'https://www.courtlistener.com/opinion/2974425/', '2974425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons that follow, we hold that the decision to employ a summary contempt proceeding under Rule 42(a) was inappropriate under the circumstances of this case and that the contempt conviction is substantively deficient, in that the elements of criminal contempt were not met.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that whatever disruption Mr.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We decline to remand this case, however because we hold that the evidence was insufficient that Mr.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, based on our review of the evidence in this case we conclude that some of the facts contained in the certification that were relied upon by the trial court are not supported by the record.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We will also reverse a conviction for contempt if we find that there is not adequate record support for any certified fact, if that fact was part of an aggregate of facts upon which the trial judge based his or her contempt ruling.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the conviction for contempt.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the appellant in Warrick I, whose summary contempt conviction we reversed, Mr.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse Mr.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 244 (1976), we held that a penal statute "must give reasonable notice of the conduct which it proscribes to a person charged with violating its interdiction.', 'general', 'Commonwealth v. Mikulan', 'https://www.courtlistener.com/opinion/1462180/', '1462180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This direct appeal followed, and we reverse.', 'general', 'Commonwealth v. Mikulan', 'https://www.courtlistener.com/opinion/1462180/', '1462180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, this Court holds that a social host who knowingly enables an adult guest to become intoxicated knowing that the guest will operate a motor vehicle is liable for damages to a third party caused by the intoxicated guest.', 'general', 'Kelly v. Gwinnell', 'https://www.courtlistener.com/opinion/1468662/', '1468662') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a host who serves liquor to an adult social guest, knowing both that the guest is intoxicated and will thereafter be operating a motor vehicle, is liable for injuries inflicted on a third party as a result of the negligent operation of a motor vehicle by the adult guest when such negligence is caused by the intoxication.', 'general', 'Kelly v. Gwinnell', 'https://www.courtlistener.com/opinion/1468662/', '1468662') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that voluntary intoxication is available to negate a finding of the requisite mental intent in a charge under this statute.', 'general', 'State v. D''AMICO', 'https://www.courtlistener.com/opinion/1519892/', '1519892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the error in the trial court’s charge so affects the substantial rights of this respondent that we will notice the error on appeal despite the lack of proper objection.', 'general', 'State v. D''AMICO', 'https://www.courtlistener.com/opinion/1519892/', '1519892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that proof of loss causation is not required in a civil securities proceeding under sections 517.', 'general', 'EF Hutton & Co., Inc. v. Rousseff', 'https://www.courtlistener.com/opinion/1130236/', '1130236') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the PrimeTime Live video program DWB was not defamatory.', 'general', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 903 (2002), we held that a pat-down of a passenger was invalid when its only justification was an improper consent to search the car.', 'general', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998), we held that a videotape was admissible in a prosecution of a "nanny" for assaulting and endangering the welfare of a child, because the baby vicariously consented through her parents.', 'general', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'They cite Diaz in support of this contention, but there we declined to consider the issue because we held that the audio portion of the recording was admissible based upon vicarious consent.', 'general', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1193 (1995), in which we held that telephone conversations in defendant''s house on his telephone line between his ex-wife and her mother, taped by defendant, were inadmissible because the taping violated the Act.', 'general', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', this court held that the trooper did not have "any reasonable belief in a threat to his safety.', 'general', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judge correctly dismissed plaintiffs'' defamation and false light claims.', 'dismissal', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here also, we conclude that the Act does not apply to the video portion of the film.', 'general', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, because we concluded that plaintiffs failed to honor the testers'' right to freedom from unreasonable searches, as in Smith, we are reluctant to recognize their own claims of privacy as reasonable.', 'general', 'Hornberger v. American Broadcasting Cos., Inc.', 'https://www.courtlistener.com/opinion/1468966/', '1468966') ON CONFLICT DO NOTHING;
