INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on the Supreme Court’s rationale set out above, we held that the defendant’s argument was meritless where no restitution was ordered.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1251370/', '1251370') ON CONFLICT DO NOTHING;
