INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the centrality of "purpose" in any finding of the escape-detection factor, we hold that the trial court erred in failing to define it during the penalty phase.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 188, we held that a trial court must charge the jury regarding "all of the possible offenses that might reasonably be found from such facts.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*411 In Brown, supra, we held that the jury should have been instructed that a nonunanimous verdict was acceptable on the question whether defendant had committed the murders by his own conduct.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mejia, supra, we held that the jury should have been informed in the guilt phase that a nonunanimous verdict was acceptable on the question whether the defendant had committed homicide with the intent to cause death or serious bodily injury that resulted in death.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 188 (1987), we held that penalty-phase juries, when deciding between life and death, must be instructed about the noncapital sentence for purposeful-or-knowing murder.', 'sentencing', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 19 (1994), we held that guilt-phase juries must be instructed that a failure to agree unanimously that a capital defendant committed murder "by his own conduct," N.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 175 (1992), in which we held that, where the evidence provides a rational basis for the jury to convict of felony murder, felony murder must be charged to provide the jury with the opportunity to convict of that noncapital alternative form of murder.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 9712(a), we hold that the mandatory minimum sentence provided by that section applies only to those parties culpable for a crime of violence as defined by 42 Pa.', 'sentencing', 'Commonwealth v. Dickson', 'https://www.courtlistener.com/opinion/1537713/', '1537713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because we disagree with the Commonwealth''s characterization of Appellant''s argument before the trial court, and find implicit in that argument the § 9712 argument raised before the Superior Court and now this Court, we conclude that Appellant preserved the issue for appellate review.', 'general', 'Commonwealth v. Dickson', 'https://www.courtlistener.com/opinion/1537713/', '1537713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Appellant preserved the issue raised herein in the lower courts, and that it therefore is ripe for our review.', 'general', 'Commonwealth v. Dickson', 'https://www.courtlistener.com/opinion/1537713/', '1537713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse.', 'general', 'Commonwealth v. Dickson', 'https://www.courtlistener.com/opinion/1537713/', '1537713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 719, 722 (1986), we held that the testimony of a probationer at a probation revocation hearing held prior to the disposition of related criminal charges is inadmissible against probationer during the subsequent criminal proceedings.', 'general', 'State v. Brunelle', 'https://www.courtlistener.com/opinion/1533148/', '1533148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Brunelle', 'https://www.courtlistener.com/opinion/1533148/', '1533148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Seeking to balance these concerns, we therefore hold that previously suppressed evidence is unavailable to the State for impeachment purposes except when it is clear that the defendant has testified during direct examination in a manner contradictory to the suppressed evidence.', 'suppression', 'State v. Brunelle', 'https://www.courtlistener.com/opinion/1533148/', '1533148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the points raised by defendant are clearly without merit, R.', 'general', 'State v. Cantor', 'https://www.courtlistener.com/opinion/1533201/', '1533201') ON CONFLICT DO NOTHING;
