INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that police officers are absolutely immune under N.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whatever the relevance of those Motor Vehicle statutory provisions, we hold that they do not affect the immunity conferred on police officers by the Act, specifically by section 5-2b(2), as we have construed it.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That may not be the "plain meaning" of the section, but given its history, its apparent purpose, and the absence of any indication of a contrary intent, we conclude that the statute should be so construed.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not have to grapple with these questions, including whether Roll conferred a common law immunity preserved by the Act, because we find that section 5-2b(2) confers absolute immunity, except where the police officer engages in willful misconduct.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Appellate Division.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the common methodology “showed a single scheme or plan rather than a number of isolated instances” even though all of the offenses were not closely connected in time.', 'general', 'State v. Venman', 'https://www.courtlistener.com/opinion/1487245/', '1487245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1187, 1189 (1983), this Court held that a motion for a severance under Rule 14(b)(1)(B) must be accompanied by “substantial evidence of prejudice.', 'general', 'State v. Venman', 'https://www.courtlistener.com/opinion/1487245/', '1487245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that a penalty would not run afoul of the constitutional restriction unless it were “clearly out of all just proportion to the offense.', 'general', 'State v. Venman', 'https://www.courtlistener.com/opinion/1487245/', '1487245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 280, we conclude that defendant’s allegation of prejudice in this case reduces to an “unsupported assertion that delay is per se prejudicial.', 'general', 'State v. Venman', 'https://www.courtlistener.com/opinion/1487245/', '1487245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 15, we conclude that in this case the complainant’s testimony regarding defendant’s prior assault on his ex-girlfriend was admissible under Rule 404(b) because it was relevant to whether a reasonable person in the victim’s circumstances would fear bodily injury.', 'general', 'State v. Hinchliffe', 'https://www.courtlistener.com/opinion/1057247/', '1057247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these factors to the evidence at issue, we conclude that the court did not abuse its discretion.', 'general', 'State v. Hinchliffe', 'https://www.courtlistener.com/opinion/1057247/', '1057247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Hinchliffe', 'https://www.courtlistener.com/opinion/1057247/', '1057247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we hold that the complaint does state a cause of action against the city under the facts presented here.', 'general', 'Huhn v. Dixie Ins. Co.', 'https://www.courtlistener.com/opinion/1592939/', '1592939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Affirmatively we hold that a municipal corporation may be held liable for the torts of police officers under the doctrine of respondeat superior.', 'general', 'Huhn v. Dixie Ins. Co.', 'https://www.courtlistener.com/opinion/1592939/', '1592939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the complaint in this instant case stated a cause of action and the trial court erred in finding that the city could not be responsible for the acts or omissions of its police officers under these circumstances.', 'general', 'Huhn v. Dixie Ins. Co.', 'https://www.courtlistener.com/opinion/1592939/', '1592939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'consequently, we conclude that Modlin and its ancestry and progeny have no continuing vitality subsequent to the effective date of section 768.', 'general', 'Huhn v. Dixie Ins. Co.', 'https://www.courtlistener.com/opinion/1592939/', '1592939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we find that because the complaint alleged that the police officers knew Collins to be intoxicated yet failed to detain or arrest him, there was little room for discretion which would warrant a finding of immunity.', 'general', 'Huhn v. Dixie Ins. Co.', 'https://www.courtlistener.com/opinion/1592939/', '1592939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Huhn v. Dixie Ins. Co.', 'https://www.courtlistener.com/opinion/1592939/', '1592939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Medeiros', 'https://www.courtlistener.com/opinion/1542780/', '1542780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Bacote', 'https://www.courtlistener.com/opinion/1254231/', '1254231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the trial court erred in failing to suppress the cocaine obtained as a result of an illegal seizure and subsequent involuntary consensual search.', 'suppression', 'Deer v. Commonwealth', 'https://www.courtlistener.com/opinion/1226656/', '1226656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse Deer’s conviction.', 'general', 'Deer v. Commonwealth', 'https://www.courtlistener.com/opinion/1226656/', '1226656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record is insufficient to determine whether Klessig''s waiver of counsel was knowing, intelligent and voluntary, and that the circuit court should have made an independent determination of Klessig''s competence to represent himself.', 'general', 'State v. Klessig', 'https://www.courtlistener.com/opinion/1623148/', '1623148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that in order for an accused''s waiver of his right to counsel to be valid, the record must reflect not only his deliberate choice to proceed without counsel, but also his awareness of the difficulties and disadvantages of self-representation, the seriousness of the charge or charges he is facing and the general range of possible penalties that may be imposed if he is found guilty.', 'general', 'State v. Klessig', 'https://www.courtlistener.com/opinion/1623148/', '1623148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Pickens, this court held that "competency to stand trial is not the same as competency to proceed pro se and that, even though he has knowingly waived counsel and elected to do so, a defendant may *209 be prevented from representing himself.', 'general', 'State v. Klessig', 'https://www.courtlistener.com/opinion/1623148/', '1623148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the court of appeals.', 'general', 'State v. Klessig', 'https://www.courtlistener.com/opinion/1623148/', '1623148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the fact that the commencement of appellant’s trial was at hand and juror Maenius was apparently plagued with personal problems so exigent as to potentially inhibit his ability to concentrate on the trial, we hold that the trial judge’s decision to excuse this juror under Article 35.', 'general', 'Fuentes v. State', 'https://www.courtlistener.com/opinion/1533957/', '1533957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'supra, we held that anti-sympathy charges do not unconstitutionally contradict mitigation instructions.', 'general', 'Fuentes v. State', 'https://www.courtlistener.com/opinion/1533957/', '1533957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 268 (1993), this Court held that Code of Criminal Procedure article 35.', 'general', 'Fuentes v. State', 'https://www.courtlistener.com/opinion/1533957/', '1533957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Code § 61-2-1 and the plain intent of the Legislature in enacting that statute, we hold that pursuant to W.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 402 (1990), this Court held that it was not error for the trial court to admit an entire videotaped statement under Rule 613(b) to impeach a witness’ testimony at trial.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that any privileged conversations between Hutsenpiller and his attorney concerning an agreement with the State were not waived by the “fairness doctrine.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that the trial court did not err by refusing to give the instruction.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the record, we find that the defendant failed to raise this specific issue below.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that W.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that the trial court did not err when it held that Hutsenpiller did not testify to anything that could be impeached by Attorney Anderson’s testimony.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court did not abuse its discretion.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not abuse its discretion in excluding the videotaped statement of Lana Poole in its entirety.', 'general', 'State v. Rodoussakis', 'https://www.courtlistener.com/opinion/1229173/', '1229173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We conclude that it did not.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Mata timely informed the trial court of his grounds with sufficient specificity and, therefore, that he preserved error.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given McDougall''s inconsistent testimony, along with the single breath test conducted over two hours after the driving, we conclude that, in this case, the State failed to prove by clear and convincing evidence that McDougall''s retrograde extrapolation was reliable.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the testimony, we find that, while McDougall''s testimony indicates a general understanding of the BAC curve and the concepts of absorption and elimination, it reflects failure to explain the theory to the court with any clarity.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the factors in this case weigh against a finding of reliability.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the district court in each case.', 'general', 'State v. Lynch', 'https://www.courtlistener.com/opinion/1640701/', '1640701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is no statute or court rule requiring a disclosure of this information, we hold that the trial judge did not abuse his discretion in denying appellant’s request.', 'general', 'State v. Childs', 'https://www.courtlistener.com/opinion/1228731/', '1228731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was sufficient evidence to deny appellant’s motion and to sustain the aggravating circumstance of robbery while armed with a deadly weapon.', 'general', 'State v. Childs', 'https://www.courtlistener.com/opinion/1228731/', '1228731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that there was no violation of due process and that the trial judge did not abuse his discretion in refusing to require the solicitor’s office to disclose the remainder of the information it had gathered on prospective jurors.', 'general', 'State v. Childs', 'https://www.courtlistener.com/opinion/1228731/', '1228731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that based on the totality of the circumstances and on the record before us, the trial judge properly determined that appellant’s post-arrest statement was voluntarily made and was not the result of coercive and threatening police tactics.', 'general', 'State v. Childs', 'https://www.courtlistener.com/opinion/1228731/', '1228731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this standard, we find that the record in this case contains sufficient evidence to raise more than a mere suspicion of guilt and to warrant denial of both motions for directed verdicts as evidenced by the following discussion.', 'general', 'State v. Childs', 'https://www.courtlistener.com/opinion/1228731/', '1228731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this evidence tends to prove the guilt of appellant as to the charge of conspiracy and hold that such guilt could be fairly and logically deduced from the evidence.', 'general', 'State v. Childs', 'https://www.courtlistener.com/opinion/1228731/', '1228731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reversed the defendant’s conviction of murder and sentence of life imprisonment and remanded for a new trial because the State failed to meet its burden of showing that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial judge’s initial determination of the validity of appellant’s post-arrest statement and its ultimate submission to the jury.', 'general', 'State v. Childs', 'https://www.courtlistener.com/opinion/1228731/', '1228731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Black was not prejudiced by the charging in the alternative and the district court did not abuse its discretion by refusing to sever the charges.', 'general', 'Black v. State', 'https://www.courtlistener.com/opinion/1229766/', '1229766') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Black v. State', 'https://www.courtlistener.com/opinion/1229766/', '1229766') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and sentence.', 'sentencing', 'Black v. State', 'https://www.courtlistener.com/opinion/1229766/', '1229766') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court.', 'general', 'Robinson v. Traughber', 'https://www.courtlistener.com/opinion/2105281/', '2105281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a double (but not a greater) departure was justified because of the absolute vulnerability of the victim (who was 2 years and 10 months old) and the particular cruelty involved (in penetrating the victim with his finger, the defendant caused a tear requiring surgery to repair).', 'general', 'State v. Herberg', 'https://www.courtlistener.com/opinion/1580153/', '1580153') ON CONFLICT DO NOTHING;
