INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'Johnathon R. Aslinger v. State of Indiana', 'https://www.courtlistener.com/opinion/2725754/', '2725754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court was correct, although for
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 628 (1991), we held that a conviction for driving on a suspended license in violation of former Code § 46.', 'general', 'Driscoll v. Commonwealth', 'https://www.courtlistener.com/opinion/1244992/', '1244992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 561 (1991) (en banc), we concluded that Fairfax County Code § 82-4-17 is invalid and that a second or later conviction for driving while intoxicated in violation of that provision may not be the basis for a determination that one is an habitual offender.', 'general', 'Driscoll v. Commonwealth', 'https://www.courtlistener.com/opinion/1244992/', '1244992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm this determination because, even though the trial court erred in ruling that certain offenses were predicate offenses while others were not, it, nevertheless, reached the correct result.', 'general', 'Driscoll v. Commonwealth', 'https://www.courtlistener.com/opinion/1244992/', '1244992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the facts testified to by the defendant raised the inference of self-defense.', 'general', 'State v. Lujan', 'https://www.courtlistener.com/opinion/1234395/', '1234395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the record, the briefs and the oral arguments of the parties, we affirm the judgment of the trial court, although we modify the terms of the sentence for inciting to riot.', 'sentencing', 'State v. Russell', 'https://www.courtlistener.com/opinion/1451606/', '1451606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, finding no error requiring reversal, we affirm the judgment of the trial court as modified to reflect 75 percent service of the inciting to riot sentence.', 'sentencing', 'State v. Russell', 'https://www.courtlistener.com/opinion/1451606/', '1451606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the most appropriate remedy under the circumstances is to ameliorate the no-parole feature of the penalty.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it would be incongruous and not conducive to substantial justice to limit our consideration of the penalty issue to Hasson and not Bullock.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that it is, we need not express any view regarding how defendant Hasson''s alternative as-applied challenge to the penalty would properly have been dealt with, or whether a remand for sentencing hearings would have been necessary with regard to both Bullock and Hasson, in order to properly address any as-applied challenge.', 'sentencing', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that regardless of whether it is or should be necessary to adduce a "compelling reason" to interpret Const 1963, art 1, § 16 more broadly than the United States Supreme Court interprets the Eighth Amendment, at least three compelling reasons do, in fact, exist to interpret our state constitutional provision more broadly in these cases than the United States Supreme Court interpreted the Eighth Amendment in Harmelin.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that a proper interpretation of Const 1963, art 1, § 16, in accordance with this Court''s longstanding precedent in this area, requires us to strike down the penalty at issue as unjustifiably disproportionate to the crime for which it is imposed, and therefore "cruel or unusual.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated in parts II(A) and (B), we reverse the judgments of the Court of Appeals and reinstate the convictions of both defendants at bar.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'careful review of the trial court’s jury charge in this case, we find that denial of the Anthony
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm the judgment of the Court of Criminal Appeals.', 'general', 'State v. Cozart', 'https://www.courtlistener.com/opinion/1060446/', '1060446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in ruling that Coleman’s statements of March 11 and 12, 1981, except for irrelevant matter deleted without objection, were admissible as statements given during non-custodial interrogation.', 'general', 'Coleman v. Commonwealth', 'https://www.courtlistener.com/opinion/1227505/', '1227505') ON CONFLICT DO NOTHING;
