INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the cases, we hold that the sentence of death imposed upon Coleman was not excessive or disproportionate to sentences generally imposed by Virginia juries in crimes of a similar nature.', 'sentencing', 'Coleman v. Commonwealth', 'https://www.courtlistener.com/opinion/1227505/', '1227505') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 793 (1968), cited by Coleman, we held that the defendant was in custody at the sheriff’s office when he confessed.', 'general', 'Coleman v. Commonwealth', 'https://www.courtlistener.com/opinion/1227505/', '1227505') ON CONFLICT DO NOTHING;
