INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Wales', 'https://www.courtlistener.com/opinion/1576442/', '1576442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the statutory or legal element test should be the sole approach in determining what are the elements of the offense charged and that the language of the information or indictment charging the crime has no bearing on that analysis.', 'general', 'State v. Wales', 'https://www.courtlistener.com/opinion/1576442/', '1576442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With these principles as our guide, we conclude that the evidence established malice.', 'general', 'Long v. Commonwealth', 'https://www.courtlistener.com/opinion/1205648/', '1205648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence established beyond a reasonable doubt the charge of malicious wounding and we affirm the judgment.', 'general', 'Long v. Commonwealth', 'https://www.courtlistener.com/opinion/1205648/', '1205648') ON CONFLICT DO NOTHING;
