INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only for an abuse of discretion.', 'general', 'State v. Folck', 'https://www.courtlistener.com/opinion/1576518/', '1576518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated in Division VII, we reverse the conviction and sentence on the charge of sexual abuse.', 'sentencing', 'State v. Folck', 'https://www.courtlistener.com/opinion/1576518/', '1576518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s conviction and sentence for kidnapping, and we affirm the denial of post-conviction relief.', 'sentencing', 'State v. Folck', 'https://www.courtlistener.com/opinion/1576518/', '1576518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find no abuse of discretion here, and accordingly, we affirm the denial of relief.', 'general', 'State v. Folck', 'https://www.courtlistener.com/opinion/1576518/', '1576518') ON CONFLICT DO NOTHING;
