INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the remarks by the substitute judge, while they could have been stated in a more formal manner or in a separate document, constitute an adequate certification under the rule.', 'general', 'Vit v. State', 'https://www.courtlistener.com/opinion/1250743/', '1250743') ON CONFLICT DO NOTHING;
