INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the doctrine of corpus delicti is inapplicable at the sentencing phase.', 'sentencing', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235400/', '1235400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 436 (1984), we held that article 2, section 12 “does not say an individual will be qualified as a juror
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of all the proffered mitigating evidence, we agree with all aspects of the trial court’s consideration of statutory and non-statutory mitigating circumstances except we conclude that lack of a prior felony record is a non-statutory mitigating circumstance.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235400/', '1235400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude defendant was properly convicted and sentenced, we affirm his convictions and sentences on all counts.', 'sentencing', 'State v. Scott', 'https://www.courtlistener.com/opinion/1235400/', '1235400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the resulting prejudice was clear in that the jury gave the maximum sentences for kidnapping and theft to a first offender.', 'sentencing', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2430181/', '2430181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We must first determine the appellants’ sufficiency argument, even though we reverse on other grounds.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2430181/', '2430181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To reiterate, we conclude that Berry’s $100 public defender fee was imposed pursuant to Section 35-33-7-6, which requires a finding of ability to pay.', 'general', 'Berry v. State', 'https://www.courtlistener.com/opinion/2526557/', '2526557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/1495687/', '1495687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As substantial evidence clearly existed in this case to support the jury''s verdict, with or without the introduction of the prior conviction, we affirm.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/1495687/', '1495687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that our courts have no such power.', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not.', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly we conclude that the "power cannot successfully be questioned at least with respect to the type of offense here involved .', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When considered in conjunction with the unmistakable policy expressed by the Legislature in the Graves Act  that conviction for the listed offense results without fail in at least three years imprisonment, which imprisonment is not to be reduced by parole eligibility, sentence suspension, or anything  we find that the legislative intent permits but one conclusion.', 'sentencing', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[19] Accordingly, we affirm the judgment below.', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm the judgment of the Appellate Division in Des Marets and that of the trial court in Appleton.', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case of Woodard, we hold that there is.', 'general', 'McCoy v. United States', 'https://www.courtlistener.com/opinion/1493867/', '1493867') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that “[o]nce the legislature has specifically authorized the use of sentencing alternatives to confinement for a particular offense, trial courts may not summarily impose
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons subsequently discussed in this opinion, we conclude that the sentencing court applied inappropriate sentencing considerations, and, therefore, we need not presume that the sentences imposed by the court are correct.', 'sentencing', 'State v. Millsaps', 'https://www.courtlistener.com/opinion/2431409/', '2431409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court could not deny the appellant an alternative sentence on the basis of the amount of money stolen.', 'sentencing', 'State v. Millsaps', 'https://www.courtlistener.com/opinion/2431409/', '2431409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'review of the record, we conclude that the appellant is an eligible and appropriate offender for sentencing under the Tennessee Community Corrections Act.', 'sentencing', 'State v. Millsaps', 'https://www.courtlistener.com/opinion/2431409/', '2431409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the issue before us arises out of a criminal case and is, therefore, reviewable by this court.', 'general', 'State v. Millsaps', 'https://www.courtlistener.com/opinion/2431409/', '2431409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the action of the Legislature in amending our statute to conform to the language of the Model Penal Code, and the intent of the Model Code drafters to limit the reach of the provision to “fighting words,” we hold that the “abusive language” provision of § 1026(3) is properly construed as proscribing only “fighting words.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '129 (1802), in which we held that the “redress of grievances” provision of Chapter I, Article 20 of the Vermont Constitution creates an absolute privilege for libelous statements addressed to the Legislature.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that “the abuse of the right must be submitted to in common with other evils in government, as subservient to the public welfare.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant having failed to demonstrate that the Vermont Constitution affords a more expansive free-speeeh right than is found under the federal charter, we conclude that the statements that formed the basis for his disorderly conduct conviction find no constitutional protection.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Oren, however, we affirmed a conviction for hindering a law enforcement officer under the “fighting words” doctrine, without regard to the fact that both the defendant and the *151officer were women.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that one intended purpose of AS 12.', 'general', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we held that the police have no duty to advise a suspect of any right to counsel, we did not hold that the police may refuse the specific requests to contact counsel that were made in the instant cases.', 'general', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the videotape evidence of his actions after he requested to speak with his attorney should have been suppressed entirely.', 'suppression', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given those considerations and the absence of a history of excessive force in arrests by police officers, we concluded that the imposition of the exclusionary rule for violations of the forcible arrest statute would at best achieve only a marginal deterrent effect.', 'general', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that when a person is arrested for operating a motor vehicle while intoxicated and asks to consult a lawyer, AS 12.', 'general', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a private citizen may not use force to resist a search by an authorized police officer engaged in the performance of his duties whether or not the arrest is illegal.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that a private citizen may not use force to resist a peaceful search by one he knows or has good reason to believe is an authorized police officer performing his duties, regardless of whether the search is ultimately determined to be illegal.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 421, 427 (Alaska 1969), we held that a private citizen may not use force to resist a peaceful arrest regardless of whether the arrest is illegal.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 289, 291 (Alaska 1963), we held that testimony regarding a defendant''s silence in the face of an accusatory statement is inadmissible in situations where the defendant''s silence is equally consistent with a state of mind other than acquiescence in the truth of what was said.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sears, we held that the judicial integrity rationale would be implicated only in cases of gross police misconduct.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the rationale of Bargas and Padgett applies with equal force to lawful searches.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1201 Applying this standard to this case, we conclude that Elson had no right to resist physically the pat down search by the officer.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that where the illegally seized evidence is reliable, where the police conduct involved in obtaining the evidence does not shock the conscience of the court, and where it is clear that the evidence was not obtained for purposes of influencing the sentencing judge, illegally seized evidence may be considered in fashioning a sentence.', 'sentencing', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing these various policy considerations, we conclude that the Court of Appeals, in declining to apply the exclusionary rule in this case, struck a proper balance between the interests of the judicial system in sentencing and the purposes of the exclusionary rule.', 'sentencing', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that where the state[30] is able to prove (1) that the illegal evidence is reliable, (2) that the police did not obtain the evidence as a result of gross or shocking misconduct, and (3) that the evidence was not obtained for purposes of influencing the sentencing court, the illegally seized evidence may be considered by the sentencing court in fashioning a defendant''s sentence.', 'sentencing', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in denying defen*312dants the right to cross-examine Arias concerning the polygraph test results, not because those results were reliable, but because the test results caused Arias to change her statement.', 'general', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that on this record, D’Amico failed to establish his claim for ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to reinstate the convictions and sentences.', 'sentencing', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Appellate Division judgment and reinstate the convictions and sentences of defendants Castagna and D’Amico.', 'sentencing', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the officers did not have reasonable grounds to make the initial stop.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1758387/', '1758387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Witchey', 'https://www.courtlistener.com/opinion/1254429/', '1254429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ross v. State', 'https://www.courtlistener.com/opinion/1452570/', '1452570') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1108, we concluded that "[t]here was ample evidence, most of which was not denied, to justify revocation.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our review of Wyoming probation revocation statutes and case law, we find that it is possible to delineate revocation procedures within four relatively distinct categories: (1) Wyo.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'NOW, THEREFORE, IT IS ORDERED that the Defendant be remanded to the custody of the Sheriff of Natrona County, Wyoming, where he shall serve a term of nine (9) months in the Natrona County Jail, with credit for 188 day(s) served previously in the Natrona County Jail.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse this aspect of the district court''s actions in this case.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the sentence entered and authorize the district court to resentence Raymond Wlodarczyk to confinement for a period no longer than the term remaining on the three year probationary period on the day the petition for revocation was filed.', 'sentencing', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the revocation of probation on the basis of the charges presented and the admitted violations precluding use of intoxicating beverages.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that evidence of these convictions properly was excluded.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury was informed of the plea bargain, because Pierce was allowed to inquire substantially into the nature of that bargain, and because DeLucia had not yet actually been sentenced, we hold that the trial judge did not abuse his discretion by merely restricting further inquiry into comparable penalties for different offenses.', 'sentencing', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the admission waived any defect in the hearing which resulted in amendment of the prosecutor’s information.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the testimony of the accomplice DeLucia was adequately corroborated to sustain the conviction.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district judge did not err by allowing this limited impeachment, even though the reason he gave for doing so was incorrect.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state’s failure to disclose his expected testimony violated no constitutional duty or rule requirement.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we conclude that the district court did not abuse its discretion in sentencing Pierce to an indeterminate, thirty-year period of custody.', 'sentencing', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that he did not abuse his discretion by sentencing Pierce to a longer term than those received by his accomplices.', 'sentencing', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons stated below, we find that Pierce was properly *100convicted following a fair trial.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm the judgment in all other respects.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1427104/', '1427104') ON CONFLICT DO NOTHING;
