INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion by refusing to allow rehabilitation questions of these prospective jurors.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1335408/', '1335408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'standard here, we conclude that the trial court did not abuse its discretion in excusing prospective jurors McDonald and Blackard for cause.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1335408/', '1335408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wynn’s testimony was proper nonhearsay evidence when introduced for that limited purpose.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1335408/', '1335408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taken in the light most favorable to the State, we conclude that there was sufficient evidence to give rise
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was ample evidence of restraint not inherent in the armed robbery to support the charge of kidnapping.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1335408/', '1335408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that there is sufficient evidence of a constructive breaking to sustain defendant’s burglary conviction.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1335408/', '1335408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence is sufficient to satisfy the State’s burden of proving premeditation and deliberation.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1335408/', '1335408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in reopening the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court properly overruled defendant Carraway’s objection to the State’s question.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1245749/', '1245749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court properly sustained the objections.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1245749/', '1245749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s conduct was entirely proper.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1245749/', '1245749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court properly admitted Dekeyser’s in-court identification of the defendants.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1245749/', '1245749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that State’s exhibits 2 and 3 were properly admitted for illustrative purposes.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1245749/', '1245749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that defendant Carraway waived her right to object to this evidence.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1245749/', '1245749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, we hold that any possible error which might have occurred due to the phrasing of the first instruction was surely cured by the court’s immediate explanatory instruction.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1245749/', '1245749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this assignment of error is feckless because the comment was made during a bench conference out of the hearing of the jury.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1245749/', '1245749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that none of the prosecutor''s statements violated defendant''s right to a fair trial.', 'general', 'People v. Abraham', 'https://www.courtlistener.com/opinion/1607809/', '1607809') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 49, this Court held that the statute requiring adult sentences for juveniles tried as adults, M.', 'sentencing', 'People v. Abraham', 'https://www.courtlistener.com/opinion/1607809/', '1607809') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court in Conat, supra, disposed of this argument in a similar manner, and we conclude that its reasoning is equally applicable in the present case:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Abraham', 'https://www.courtlistener.com/opinion/1607809/', '1607809') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err, on first amendment grounds, in denying Vi-glielmo’s motions to dismiss or in finding her guilty, inasmuch as (1) the district court’s decisions did not run afoul of federal constitutional case law and (2) Viglielmo’s expressive conduct on the premises of Ala Moana Shopping Center was not protected under the first amendment to the United States Constitution.', 'dismissal', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that article I, section 4 of the Hawai''i Constitution affords Viglielmo no greater free speech protection than the first amendment to the United States Constitution and that she is therefore not insulated from criminal liability under HRS § 708-814(l)(b).', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there has been no such dedication of Lloyd’s privately owned and operated shopping center to public use as to entitle respondents to exercise therein the asserted [fjirst [ajmendment rights.', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in light of the United States Supreme Court’s decisions delineating the boundaries of first amendment protections in shopping centers, we hold that the district court did not err, on first amendment grounds, in denying Viglielmo’s motions to dismiss or in finding her guilty, inasmuch as (1) the district court’s decisions did not run afoul of federal constitutional case law and (2) Viglielmo’s expressive conduct on the premises of Ala Moana Shopping Center was not protected under th...', 'dismissal', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*213Under these circumstances, we hold that article I, section 4 of the Hawai''i Constitution affords Viglielmo no greater free speech protection than the first amendment to the United States Constitution and that she is therefore not insulated from criminal liability under HRS § 708-814(l)(b), see supra note 2.', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 216 (1990), we held that a hospital’s no-solicitation policy precluding distribution of leaflets and other expressions of anti-abortion views did not implicate “state action” for the purposes of the state constitutional guarantee of free speech, and that an interior walkway adjacent to one of the main entrances of the hospital was not historically or traditionally associated with the exercise of free speech rights and therefore not to be treated as public property for free speech purposes.', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing analysis, we affirm the district court’s judgment of conviction and sentence.', 'sentencing', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that: (1) pursuant to the post-conviction liberal construction rule adopted by this court in State v.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Sprattling failed to prove by a preponderance of the evidence that his waiver was involuntary, we hold that the district court did not err in this regard.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as Sprattling fails to provide a clear showing of substantial prejudice or that the charge could not be reasonably interpreted to assert a criminal offense, this court holds that the charge was sufficient.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this court holds that Sprattling validly waived his right to a trial by jury.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, this court holds that Sprattling’s conviction is affirmed.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Friedman, this court held that an analysis into whether a jury trial waiver was valid must be made in light of the totality of the circumstances.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In no case has this court held, as the majority would hold here, that, although the accusation—as the oral charge here—cannot be reasonably construed to chai''ge an offense, a conviction obtained thereon must nonetheless stand unless the defendant can establish that he or she suffered actual “prejudice.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that there is a genuine issue of fact as to the lawfulness of Kemp’s arrest of Crawford.', 'general', 'Crawford v. Kemp', 'https://www.courtlistener.com/opinion/2600520/', '2600520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the superior court’s decision granting summary judgment in favor of Kemp because there are genuine issues of material fact as to whether there was probable cause for Crawford’s subsequent arrest and search and whether Kemp is entitled to immunity.', 'probable_cause', 'Crawford v. Kemp', 'https://www.courtlistener.com/opinion/2600520/', '2600520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a factual issue has been raised as to whether Kemp’s arrest was made for an impermissible or pretextual purpose, we reverse the superior court''s grant of summary judgment on Crawford’s state law tort claims.', 'general', 'Crawford v. Kemp', 'https://www.courtlistener.com/opinion/2600520/', '2600520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we REVERSE the superior court’s grant of summary judgment in favor of Kemp and REMAND this case for further proceedings consistent with this opinion.', 'general', 'Crawford v. Kemp', 'https://www.courtlistener.com/opinion/2600520/', '2600520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4] There, this Court held that first-degree *474 child abuse was a specific-intent crime.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ainsworth,[26] this Court held that the offense of stealing or retaining a financial-transaction device (more commonly known as a credit card) constitutes a specific-intent crime, given that knowledge is an essential part of the crime, because the statute[27] requires that a person "knowingly" commit the offense.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" More to the point, however, we can presume that the Legislature was aware that in Gould[68] this Court held the crime of first-degree child abuse to be a specific-intent crime but that, upon review, the Supreme Court classified this holding as dicta.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the dictionary definition of the word "knowingly" and applying the plain and ordinary meaning of the word to the language of the statute, we conclude that "knowingly" as contained in the statute means the same thing as the word "intentionally.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the dictionary definitions described above, as well as our Legislature''s deliberate use of different phrases when defining first- and second-degree child abuse, we conclude that first-degree child abuse is a specific-intent crime.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that there was ample evidence to support a finding of probable cause for second-degree murder.', 'probable_cause', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the circuit court did not err in reinstating the felony-murder charges.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that a specific intent is required under the first-degree child abuse statute.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2]  Thus, for the same reasons, we conclude that the district court abused its discretion in finding that the evidence only supported involuntary manslaughter.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all of the circumstances presented in this case, we conclude that the State met its burden to show that the exigent circumstance exception to the warrant requirement applied to Officer Cotter’s entry of Pearson-Anderson’s home, and we therefore affirm the district court’s denial of her suppression motion.', 'suppression', 'State v. Pearson-Anderson', 'https://www.courtlistener.com/opinion/2600824/', '2600824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In these consolidated appeals, Pearson-Anderson asks that we reverse the order denying her suppression motion and the order revoking probation.', 'suppression', 'State v. Pearson-Anderson', 'https://www.courtlistener.com/opinion/2600824/', '2600824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the proof of rape was substantial.', 'general', 'Mills v. State', 'https://www.courtlistener.com/opinion/1638170/', '1638170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'Mills v. State', 'https://www.courtlistener.com/opinion/1638170/', '1638170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court on this point.', 'general', 'Mills v. State', 'https://www.courtlistener.com/opinion/1638170/', '1638170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In support of his argument, Isaac cites the Court to several cases in which this Court held the evidence to be insufficient to sustain a conviction of arson.', 'general', 'Isaac v. State', 'https://www.courtlistener.com/opinion/1604204/', '1604204') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition to the above cases, Isaac cites the Court to numerous other arson cases in which this Court held that the evidence was not sufficient to support a conviction.', 'general', 'Isaac v. State', 'https://www.courtlistener.com/opinion/1604204/', '1604204') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 799 (1984), we held that undue delay in ruling upon an appeal does not warrant dismissal of a criminal charge.', 'dismissal', 'State v. Fix', 'https://www.courtlistener.com/opinion/1640315/', '1640315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Loebach', 'https://www.courtlistener.com/opinion/1605742/', '1605742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 114 (1980), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has not met this burden.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1389040/', '1389040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in a light most favorable to the State, we conclude that a reasonable inference of defendant’s guilt may be drawn from the direct and circumstantial evidence presented by the State.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1389040/', '1389040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we reverse the decision of the Court of Appeals and remand this case to that court for further remand to the Superior Court, Durham County.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1389040/', '1389040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), this Court held that chapter 95-182, Laws of Florida, violated the single subject rule because the law addressed two different subjects: domestic violence and career criminals.', 'general', 'FLA. DHSMV v. Critchfield', 'https://www.courtlistener.com/opinion/1836884/', '1836884') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, this Court held that a chapter law violated the single subject rule by combining the subject of habitual offenders with the subject of licensing private investigators.', 'general', 'FLA. DHSMV v. Critchfield', 'https://www.courtlistener.com/opinion/1836884/', '1836884') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that chapter 98-223 violates the single subject rule.', 'general', 'FLA. DHSMV v. Critchfield', 'https://www.courtlistener.com/opinion/1836884/', '1836884') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision below and hold that chapter 98-223 violates article III, section 6 of the Florida Constitution.', 'general', 'FLA. DHSMV v. Critchfield', 'https://www.courtlistener.com/opinion/1836884/', '1836884') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons recited below, we affirm Meehan’s convictions in their entirety, and modify and affirm the sentences imposed upon him.', 'sentencing', 'State v. Meehan', 'https://www.courtlistener.com/opinion/1620215/', '1620215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Meehan’s conviction and sentence on count V, subornation of perjury.', 'sentencing', 'State v. Meehan', 'https://www.courtlistener.com/opinion/1620215/', '1620215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Meehan’s convictions and modify his sentences.', 'sentencing', 'State v. Meehan', 'https://www.courtlistener.com/opinion/1620215/', '1620215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Carr', 'https://www.courtlistener.com/opinion/1249425/', '1249425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm the order denying the motion to suppress.', 'suppression', 'State v. Carr', 'https://www.courtlistener.com/opinion/1249425/', '1249425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained below, we hold that Apprendi does not apply retroactively.', 'general', 'Hughes v. State', 'https://www.courtlistener.com/opinion/1643148/', '1643148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that a change of law would not be deemed retroactive "unless the change: (a) emanates from this Court or the United States Supreme Court, (b) is constitutional in nature, and (c) constitutes a development of fundamental significance.', 'general', 'Hughes v. State', 'https://www.courtlistener.com/opinion/1643148/', '1643148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a Prison Releasee Reoffender sentence does not exceed the statutory maximum, we held that the sentence did not violate Apprendi.', 'sentencing', 'Hughes v. State', 'https://www.courtlistener.com/opinion/1643148/', '1643148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10]  In a separate opinion, this Court holds, employing a Witt analysis, that Ring does not apply retroactively.', 'general', 'Hughes v. State', 'https://www.courtlistener.com/opinion/1643148/', '1643148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our consideration of the Stovall/Linkletter factors, we conclude that the new criminal procedure rule announced in Apprendi does not warrant retroactive application.', 'general', 'Hughes v. State', 'https://www.courtlistener.com/opinion/1643148/', '1643148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we conclude that the United States Supreme Court effectively overruled Mays as to scoring factors that are neither alleged in the information nor found by a jury beyond a reasonable doubt.', 'general', 'Hughes v. State', 'https://www.courtlistener.com/opinion/1643148/', '1643148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "[t]he values implemented by the right to jury trial would not measurably be served by requiring retrial of all persons convicted in the past by procedures not consistent with the Sixth Amendment right to jury trial.', 'general', 'Hughes v. State', 'https://www.courtlistener.com/opinion/1643148/', '1643148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 352, where this court held prejudice was not shown by a denial of a continuance to obtain a witness when there was similar testimony offered at trial.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1632198/', '1632198') ON CONFLICT DO NOTHING;
