INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the vast majority of the delay was attributable to the appellant''s filing various motions and.', 'general', 'Zumbado v. State', 'https://www.courtlistener.com/opinion/1619096/', '1619096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all the Barker factors, especially the delay attributable to the appellant, we conclude that the appellant''s right to a speedy trial was not violated and that, therefore, the trial court did not err by denying the appellant''s motion to dismiss.', 'dismissal', 'Zumbado v. State', 'https://www.courtlistener.com/opinion/1619096/', '1619096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 Contrary to the state''s assertion, we conclude that this motion, filed in the Talladega Circuit Court, was filed in the proper court.', 'general', 'Zumbado v. State', 'https://www.courtlistener.com/opinion/1619096/', '1619096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we find that the trial court''s ruling on the appellant''s Batson motion was not clearly erroneous.', 'general', 'Zumbado v. State', 'https://www.courtlistener.com/opinion/1619096/', '1619096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Division One of this court held that the guard’s report of a crime to law enforcement “w[as] protected by a conditional privilege” because the guard had not been acting in his official capacity as a public officer when he made the complaint.', 'general', 'Ledvina v. Cerasani', 'https://www.courtlistener.com/opinion/2588386/', '2588386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), Division One of this court held that an absolute rather than qualified privilege applied to statements made in a complaint to the State Bar of Arizona alleging unethical conduct by an attorney.', 'general', 'Ledvina v. Cerasani', 'https://www.courtlistener.com/opinion/2588386/', '2588386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude the trial court correctly determined the report was absolutely privileged, we affirm.', 'general', 'Ledvina v. Cerasani', 'https://www.courtlistener.com/opinion/2588386/', '2588386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not impermissibly vague.', 'general', 'DuFresne v. State', 'https://www.courtlistener.com/opinion/1630297/', '1630297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we hold that the term "mental injury" in section 827.', 'general', 'DuFresne v. State', 'https://www.courtlistener.com/opinion/1630297/', '1630297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] On appeal, this Court held that the term "mental injury," as well as other provisions in the statute, was not void for vagueness.', 'general', 'DuFresne v. State', 'https://www.courtlistener.com/opinion/1630297/', '1630297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, pursuant to the analytical framework set forth in Fuchs, we conclude that the district court properly held that the challenged statute is not unconstitutionally vague because the term *279 "mental injury" is adequately defined in another related statute.', 'general', 'DuFresne v. State', 'https://www.courtlistener.com/opinion/1630297/', '1630297') ON CONFLICT DO NOTHING;
