INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this clear statement of legislative intent, we hold that Municipal Courts comply with the constitutional mandate that they be part of a unified judicial system.', 'general', 'City of Pickens v. Schmitz', 'https://www.courtlistener.com/opinion/1255318/', '1255318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'test here, we hold that Municipal Courts in South Carolina possess uniform jurisdiction as set out in §14-25-45.', 'general', 'City of Pickens v. Schmitz', 'https://www.courtlistener.com/opinion/1255318/', '1255318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Act’s constitutionality and Schmitz’s conviction.', 'general', 'City of Pickens v. Schmitz', 'https://www.courtlistener.com/opinion/1255318/', '1255318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court committed no reversible error in sentencing the Defendant to ten years on the homicide offense, but did commit reversible error in placing the Defendant on probation.', 'sentencing', 'State v. Carter', 'https://www.courtlistener.com/opinion/1651558/', '1651558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 40-35-402(c) (2006), we hold that they do not have the authority to do so simply upon the basis of a trial court’s “fail[ure] to appropriately adjust” a sentence in light of applicable, but merely advisory, mitigating or enhancement factors.', 'sentencing', 'State v. Carter', 'https://www.courtlistener.com/opinion/1651558/', '1651558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our de novo review of the facts and circumstances of this case and of the Defendant, we hold that the Defendant has not carried his burden of establishing his suitability for probation and has not established that the suspension of his sentence serves the ends of justice or the best interest of the public.', 'sentencing', 'State v. Carter', 'https://www.courtlistener.com/opinion/1651558/', '1651558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Defendant is not entitled to probation on his ten-year sentence for vehicular homicide and must serve his sentence in the Department of Correction.', 'sentencing', 'State v. Carter', 'https://www.courtlistener.com/opinion/1651558/', '1651558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because insufficient grounds exist on the record before us to overcome the presumption, we reverse the judgment of the Court of Criminal Appeals imposing a fifteen-year sentence and reinstate the Defendant’s ten-year sentence.', 'sentencing', 'State v. Carter', 'https://www.courtlistener.com/opinion/1651558/', '1651558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s grant of probation.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1651558/', '1651558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As indicated, we find that as applied to the facts of Appellant''s alleged disorderly conduct in this case, Section 877.', 'general', 'In Re Fuller', 'https://www.courtlistener.com/opinion/1831236/', '1831236') ON CONFLICT DO NOTHING;
