INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm a conviction if substantial evidence exists to support it.', 'general', 'Morgan v. State', 'https://www.courtlistener.com/opinion/1575195/', '1575195') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the convictions for manufacturing methamphetamine and possession of drug paraphernalia with the intent to manufacture methamphetamine.', 'general', 'Morgan v. State', 'https://www.courtlistener.com/opinion/1575195/', '1575195') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We cannot say that Morgan’s conviction for endangering the welfare of a minor or the sentence enhancement he received for manufacturing methamphetamine in the presence of a minor were not supported by substantial evidence and, therefore, we affirm.', 'sentencing', 'Morgan v. State', 'https://www.courtlistener.com/opinion/1575195/', '1575195') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, the circuit court’s denial of Morgan’s motion to suppress was not clearly against the preponderance of the evidence, and we affirm.', 'suppression', 'Morgan v. State', 'https://www.courtlistener.com/opinion/1575195/', '1575195') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the state met each of the five criteria, we conclude that the evidence was properly admitted.', 'general', 'State v. Brewer', 'https://www.courtlistener.com/opinion/2384257/', '2384257') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this evidence, we find that the jury acted within its prerogative in determining that all other reasonable hypothesis, save the guilt of the accused, had been excluded beyond a reasonable doubt.', 'general', 'State v. Brewer', 'https://www.courtlistener.com/opinion/2384257/', '2384257') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment and the sentence of the trial court.', 'sentencing', 'State v. Brewer', 'https://www.courtlistener.com/opinion/2384257/', '2384257') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the term "thing of value" in § 138 of the Casino Control Act is not unconstitutionally vague.', 'general', 'Matter of Petition of Soto', 'https://www.courtlistener.com/opinion/1561239/', '1561239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the guidelines concerning the practice of law, though unspecified, sufficiently gave plaintiff fair notice of those activities which would be construed as legal services.', 'general', 'Matter of Petition of Soto', 'https://www.courtlistener.com/opinion/1561239/', '1561239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our thorough review of the record we affirm.', 'general', 'Matter of Petition of Soto', 'https://www.courtlistener.com/opinion/1561239/', '1561239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that section 12a is not rendered unconstitutional by the fact that it prohibits small political contributions as well as large contributions.', 'general', 'Matter of Petition of Soto', 'https://www.courtlistener.com/opinion/1561239/', '1561239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a later homicide case, this court held it to be error to instruct the jury no particular time need intervene between the formation of the intention and the act in order to constitute premeditated malice.', 'general', 'Young v. State', 'https://www.courtlistener.com/opinion/1135736/', '1135736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the state does not have a constitutional duty to manufacture evidence in addition to its duty under Brady to disclose exculpatory evidence in its possession.', 'general', 'Young v. State', 'https://www.courtlistener.com/opinion/1135736/', '1135736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the unambiguous terminology employed in this section, we hold that the plain language of W.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Allen’s flight convictions do not offend constitutional principles of double jeopardy, and we affirm the trial court’s rulings in this regard.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the sentences imposed for Allen’s numerous misdemeanor convictions, we find that the trial court properly sentenced the defendant in accordance with the statutorily-prescribed punishments for such crimes.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed such evidence, we are not left with the impression that there remains a reasonable doubt as to Allen’s guilt of these crimes nor do we find that his convictions were tarnished by “misapprehension, or passion and prejudice.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the decision of the Wood County Circuit Court.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no impermissible factors influenced the trial court’s sentencing decision, we affirm the lower court’s ruling.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error with the trial court’s refusal of Allen’s duress or coercion instruction or with the court’s sentencing of the *163defendant to consecutive sentences in the county jail for his multiple misdemeanor convictions, we affirm the decision of the Circuit Court of Wood County.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the arrest of Appellant was unlawful because Officer Fetterman did not have probable cause to believe that Appellant had committed a crime which would justify his warrantless arrest.', 'probable_cause', 'Commonwealth v. Clark', 'https://www.courtlistener.com/opinion/1889555/', '1889555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, it is ordered that the trial court prepare an amended commitment form specifying that only the sentence on count one, attempted armed robbery, must be served without the benefit of probation, parole, or suspension of sentence.', 'sentencing', 'State v. Trepagnier', 'https://www.courtlistener.com/opinion/1806212/', '1806212') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Trepagnier', 'https://www.courtlistener.com/opinion/1806212/', '1806212') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that both were properly charged, pursuant to 11
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held since criminal contempt was not tried by a jury at common law, it "does not fall within the provision of Article 1, § 4 of the Delaware Constitution which guarantees a right to trial by jury as ‘heretofore.', 'general', 'Claudio v. State', 'https://www.courtlistener.com/opinion/1485890/', '1485890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the trial judge did not abuse his discretion in declining the defense request for an immediate curative instruction.', 'general', 'Claudio v. State', 'https://www.courtlistener.com/opinion/1485890/', '1485890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the instruction on accomplice liability which was given in this case, considered as a whole, was a correct statement of the present substantive law.', 'general', 'Claudio v. State', 'https://www.courtlistener.com/opinion/1485890/', '1485890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a proper examination of the defendants’ Rule 24(c) argument is subsumed within a review of their constitutional claims.', 'general', 'Claudio v. State', 'https://www.courtlistener.com/opinion/1485890/', '1485890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this is not a case of egregious circumstances so inherently prejudicial as to demonstrate actual prejudice or to raise a presumption of prejudice in the defendants’ favor.', 'general', 'Claudio v. State', 'https://www.courtlistener.com/opinion/1485890/', '1485890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm all of the convictions of each defendant.', 'general', 'Claudio v. State', 'https://www.courtlistener.com/opinion/1485890/', '1485890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these holdings, we hold that there is no distinction between a probation period that has expired and one that is satisfactorily completed.', 'general', 'Ex Parte Menchaca', 'https://www.courtlistener.com/opinion/1657295/', '1657295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Arne', 'https://www.courtlistener.com/opinion/2193290/', '2193290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we held that the trial court should determine defendant''s actual knowledge by looking at the totality of the circumstances to distinguish whether the plea was voluntarily, knowingly, and intelligently made.', 'plea', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1305 (1992), this Court held that defendant was entitled to withdraw his guilty plea where the trial court failed to inform him that sentences for multiple counts could be consecutive.', 'sentencing', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we concluded that the defendant was not entitled to any post-conviction relief.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we find that Appellant''s reliance on Riggins is misplaced.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court acted within its discretion in determining that Appellant was competent to stand trial.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that a capital defendant''s waiver to his statutory right to a penalty-phase jury must be knowing, voluntary and intelligent.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[12]  Like the waiver of a jury trial, we find that any waiver to a capital defendant''s right to a penalty-phase jury must be considered a personal right of the defendant''s.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm Appellant''s convictions but reverse the judgment of sentence imposed by the trial court and remand for a new penalty phase hearing.', 'sentencing', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellant''s convictions but vacate the judgment of sentence and remand for a new penalty phase hearing.', 'sentencing', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2437831/', '2437831') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we find that appellant’s sentence was not cruel and unusual.', 'sentencing', 'Andrews v. State', 'https://www.courtlistener.com/opinion/2551246/', '2551246') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that appellant’s consecutive ten-year sentences for failure to report a temporary residence do not constitute cruel and unusual punishment.', 'sentencing', 'Andrews v. State', 'https://www.courtlistener.com/opinion/2551246/', '2551246') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as to all issues.', 'general', 'Andrews v. State', 'https://www.courtlistener.com/opinion/2551246/', '2551246') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the facts of this case, Balan-za was entitled to a jury instruction on the procuring agent defense and that there was insufficient evidence supporting Balanza’s conviction of Count I.', 'jury_instruction', 'State v. Balanza', 'https://www.courtlistener.com/opinion/2552566/', '2552566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in the absence of a bill of particulars, where the evidence adduced at trial proves only a sale and a reasonable juror could find that the defendant did not act on the seller’s behalf, the defendant is entitled to a jury instruction on the procuring agent defense.', 'jury_instruction', 'State v. Balanza', 'https://www.courtlistener.com/opinion/2552566/', '2552566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in denying Balanza’s motion for severance.', 'general', 'State v. Balanza', 'https://www.courtlistener.com/opinion/2552566/', '2552566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1370 (1977), we held that the procuring agent defense is not available to a defendant charged with promoting a dangerous drug.', 'general', 'State v. Balanza', 'https://www.courtlistener.com/opinion/2552566/', '2552566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1022 (1978), we held that the procuring agent defense was available where a bill of particulars limited the prosecution to proving distribution through a sale.', 'general', 'State v. Balanza', 'https://www.courtlistener.com/opinion/2552566/', '2552566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court did not abuse its discretion in denying the motion because Reed received sufficient no
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the trial court did not err in refusing to instruct the jury on the procuring agent defense.', 'general', 'State v. Balanza', 'https://www.courtlistener.com/opinion/2552566/', '2552566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the procuring agent defense was applicable where there was a bill of particulars limiting the prosecution to proving distribution through a sale.', 'general', 'State v. Balanza', 'https://www.courtlistener.com/opinion/2552566/', '2552566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a bill of particulars is a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse his conviction of Count I and remand the ease for entry of a judgment of acquittal on that count.', 'general', 'State v. Balanza', 'https://www.courtlistener.com/opinion/2552566/', '2552566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Section 67-5101(G)''s plain language is not broad enough to encompass enforcement of controlled substance laws that do not involve the operation or management of motor vehicles as an element of the offense.', 'general', 'State v. Ambro', 'https://www.courtlistener.com/opinion/2634804/', '2634804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Giving the words of Section 67-5101(G) their plain and rational meaning, we conclude that, in order for that section to confer state jurisdiction over an offense committed by an Indian on a reservation, the offense must concern the "operation and management" of motor vehicles on highways and roads maintained by the county or state.', 'general', 'State v. Ambro', 'https://www.courtlistener.com/opinion/2634804/', '2634804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a conviction under Hawai`i Revised Statutes (HRS) § 707-734 (1993) for indecent exposure must be supported by proof that the defendant "intentionally," as defined in HRS § 702-206(1) (1993), exposed his or her genitals to another person under circumstances in which the other person was likely to be affronted.', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As previously indicated, the prosecution contends that Rocker supports Defendant''s conviction because, in Rocker, this court held that the defendants'' nude sunbathing at a public beach supported their convictions of indecent exposure under HRS § 727-1 (1968).', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court applied the wrong legal standard in convicting Defendant under HRS § 707-734 and, further, as measured against the correct legal standard, there was insufficient evidence to establish his guilt.', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the evidence was not of "sufficient quality and probative value to enable [a person] of reasonable caution to support [the] conclusion" that Defendant acted intentionally under circumstances likely to cause affront.', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Defendant''s conviction because the court applied the wrong legal standard and because the evidence was insufficient to establish guilt under the legal standard that should have been applied.', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the ICA did not gravely err in affirming the court''s judgment because in Petitioner''s case (1) under HRS § 706-606.', 'general', 'State v. Kamanao', 'https://www.courtlistener.com/opinion/2569923/', '2569923') ON CONFLICT DO NOTHING;
