INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that, in all cases in which HRS § 706-606.', 'general', 'State v. Kamanao', 'https://www.courtlistener.com/opinion/2569923/', '2569923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, this court held that, "in all cases in which HRS § 706-606.', 'general', 'State v. Kamanao', 'https://www.courtlistener.com/opinion/2569923/', '2569923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that connection, this court held that HRS § 706-606.', 'general', 'State v. Kamanao', 'https://www.courtlistener.com/opinion/2569923/', '2569923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In those cases, this court held that HRS § 706-606.', 'general', 'State v. Kamanao', 'https://www.courtlistener.com/opinion/2569923/', '2569923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that a mandatory minimum term is inherently part of the indeterminate maximum term of which it is a part, the two cannot be separated, and both of the two components must be served as part of one sentence.', 'sentencing', 'State v. Kamanao', 'https://www.courtlistener.com/opinion/2569923/', '2569923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, reading that statute in pari materia with the other sentencing provisions noted, and applying this court''s precedent explaining the nature of the relationship inherent between minimum and maximum sentences, we conclude that mandatory minimum sentences are not separate sentences and therefore, cannot be divorced from the indeterminate maximum sentences of which they are a part.', 'sentencing', 'State v. Kamanao', 'https://www.courtlistener.com/opinion/2569923/', '2569923') ON CONFLICT DO NOTHING;
