INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Gleason', 'https://www.courtlistener.com/opinion/1435504/', '1435504') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that aggravated stalking and Johnson''s violation of the injunction are separate offenses, and double jeopardy does not bar a subsequent prosecution.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/1720106/', '1720106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Mejia was not entitled to a claim-of-right charge on the guilt phase.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By comparison, we hold that the penalty-phase anti-claim-of-right charge precluded the jury from considering as a mitigating factor Mejia''s honest belief that he was entitled to recover his $750 from Garcia.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court''s "instruction had *484 the potential to foreclose jury consideration of whether passion/provocation should reduce an otherwise purposeful killing from murder to manslaughter.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that the trial court, which had found a rational basis for charging aggravated and reckless manslaughter, also should have charged the jury on serious-bodily-injury murder.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the words and structure of the Code, and for sound reasons of public policy, we conclude that the Legislature did not intend to extend the claim-of-right defense to robbery.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'So here, we find that the jury should have been given the option of finding that defendant had intended to cause only serious bodily injury when he killed the victim.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that Mejia knowingly and intelligently waived his Miranda rights.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse defendant''s death sentence and remand for imposition of a non-capital-murder sentence.', 'sentencing', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse defendant''s death sentence.', 'sentencing', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 846 (1988) (Bey I), we reversed the defendant''s murder conviction because the trial court failed to ensure that the jury was not exposed to mid-trial publicity respecting defendant''s other-alleged offenses, including *514 another murder.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State appeals and we affirm.', 'general', 'State v. Bolin', 'https://www.courtlistener.com/opinion/1208319/', '1208319') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because the injunction we affirm today only enjoins the dissemination of records pertaining to criminal charges and not historical facts, Appellants are not enjoined from forwarding information they have a statutory duty to send to DPPPS.', 'general', 'Compton v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/2505986/', '2505986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the order of the circuit court as modified.', 'general', 'Compton v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/2505986/', '2505986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we affirm.', 'general', 'Commonwealth v. Felder', 'https://www.courtlistener.com/opinion/6482919/', '6482919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'a PFA Order, and, thus, we affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Felder', 'https://www.courtlistener.com/opinion/6482919/', '6482919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Legislature intended to afford the expungement remedy to all “persons,” whether corporate or natural.', 'general', 'State v. XYZ Corp.', 'https://www.courtlistener.com/opinion/7401123/', '7401123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. XYZ Corp.', 'https://www.courtlistener.com/opinion/7401123/', '7401123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the term “thing of value” in § 138 of the Casino Control Act is not unconstitutionally vague.', 'general', 'Soto v. State', 'https://www.courtlistener.com/opinion/7401205/', '7401205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the guidelines concerning the practice of law, though unspecified, sufficiently gave plaintiff fair notice of those activities which would be construed as legal services.', 'general', 'Soto v. State', 'https://www.courtlistener.com/opinion/7401205/', '7401205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our thorough review of the record we affirm.', 'general', 'Soto v. State', 'https://www.courtlistener.com/opinion/7401205/', '7401205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The General Assembly may reasonably have believed, however, that its efforts to further the relevant State interests would have been much less effective if only contributions above a certain amount were prohibited____ We therefore hold that section 12a is not rendered unconstitutional by the fact that it prohibits small political contributions as well as large contributions.', 'general', 'Soto v. State', 'https://www.courtlistener.com/opinion/7401205/', '7401205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred by holding that Fawcett retained
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the chemical analysis of a lawfully obtained blood sample
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and remand.', 'general', 'State of Minnesota v. Debra Lee Fawcett', 'https://www.courtlistener.com/opinion/3168505/', '3168505') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 784 (1991), we held that the defendant’s Sixth Amendment rights outweighed the Rape Shield Law considerations where “crucial defense evidence” on the source of the nine-year-old victim’s familiarity with sexual matters would otherwise have been excluded.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 978 (1985), we held that the two general instructions on the State’s burden of proof overcame the alleged error when the judge instructed the jury that in the absence of proof that a weapon was for a lawful purpose, it could conclude that it was for an unlawful one.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that as to the convictions on all counts other than Count Three, it does not appear “that there was a miscarriage of justice under the law.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of the permissible evidence presented to the jury, we conclude that the jury could rationally have found that all the elements required to prove the remaining counts on which defendants were convicted were proved beyond a reasonable doubt and that the jury’s verdicts were not against the weight of evidence.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that on Count Two, charging penetration of a person defendants knew or should have known was mentally defective, the ease against defendants was very strong and the evidence that M.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the preclusion order does not require reversal.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we conclude that even when viewed cumulatively, the Brady violations were without sufficient effect to require reversal.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'exhibited RTS and our vacating of the convictions on Count Three, we conclude that the absence during the improper testimony did no additional harm to Kevin.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we might disagree with the trial judge’s assessment of the risk of misleading the jury if defendants had been allowed to elicit testimony on the offense for which Paul was arrested, possession of alcohol by a minor, we conclude that the judge’s decision was not a clear abuse of discretion sufficient to warrant reversal.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, again we find that any misconduct or error did not have the potential to taint the verdict except as to the charge set forth in Count Three.', 'general', 'State v. Scherzer', 'https://www.courtlistener.com/opinion/7402665/', '7402665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because entry of that order was a mistaken exercise of discretion, which works an injustice, we reverse.', 'general', 'State v. Franklin Savings Account Number 2067', 'https://www.courtlistener.com/opinion/7404255/', '7404255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a finder of fact could reasonably have found, based on the totality of the circumstances, that defendant’s behavior would have placed a reasonable person in fear of bodily injury.', 'general', 'H.E.S. v. J.C.S.', 'https://www.courtlistener.com/opinion/7407707/', '7407707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that argument unpersuasive given the novelty of the factual circumstances and the legal issue involved.', 'general', 'H.E.S. v. J.C.S.', 'https://www.courtlistener.com/opinion/7407707/', '7407707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and hold that the trial procedures violated defendant’s right to due process.', 'general', 'H.E.S. v. J.C.S.', 'https://www.courtlistener.com/opinion/7407707/', '7407707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the Appellate Division erred when it concluded that, apparently as a matter of law, defendant’s conduct could not constitute harassment under N.', 'general', 'H.E.S. v. J.C.S.', 'https://www.courtlistener.com/opinion/7407707/', '7407707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Giving effect to our statute’s particular language in light of Arizona’s unique history, we hold that A.', 'general', 'State v. Rowan', 'https://www.courtlistener.com/opinion/6603042/', '6603042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reason, we hold that the trial court did not err when it found Wells
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reason, we affirm
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More particularly, we held that due process forbids the trial court “ ‘to convert a hearing on a complaint alleging one act of domestic violence into a hearing on other acts of domestic violence which are not even alleged in the complaint.', 'general', 'J.D. v. M.D.F.', 'https://www.courtlistener.com/opinion/7409293/', '7409293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Cromedy, this Court relied on numerous social scientific studies when we held that special jury instructions were needed in appropriate cases involving cross-racial identifications.', 'jury_instruction', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More recently in Romero, supra, this Court held that “there [was] insufficient data to support the conclusion that, as a matter of due process, people of the same race but different ethnicity .', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the end, we conclude that the current standard for assessing eyewitness identification evidence does not fully meet its goals.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the scientific evidence considered at the remand hearing is reliable.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the failure to perform blind lineup procedures can increase the likelihood of misidentification.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that courts should consider whether a lineup is poorly constructed when evaluating the admissibility of an identification.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To reiterate, we find that feedback affects the reliability of an identification in that it can distort memory, create a false sense of confidence, and alter a witness’ report of how he or she viewed an event.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that high levels of stress are likely to affect the reliability of eyewitness identifications.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record, we find that non-State actors like co-witnesses and other sources of information can affect the independent nature and reliability of identification evidence and inflate witness confidence—in the same way that law enforcement feedback can.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the scientific evidence presented is both reliable and useful.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/7409298/', '7409298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circumstances of this ease support a factfinder’s determination that defendant transported Chowdhury a “substantial distance” from the site of their initial encounter, or, in the alternative, that defendant unlawfully confined Chowdhury for a “substantial period,” within the meaning of N.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/7409405/', '7409405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Analyzing this ease in conformance with our prior decisions, we hold that there was sufficient evidence to support the jury verdict with respect to both the “substantial distance” and “substantial confinement” elements of N.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/7409405/', '7409405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Masino, although the “linear” distance between the location where the defendant had abducted the victim and the location where she was found was not long, we held that the evidence supported a jury finding that the defendant moved the victim a “substantial distance.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/7409405/', '7409405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing Masino’s approach to the issue of “substantial distance,” we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following Masino, we found that the “substantial distance” element of N.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/7409405/', '7409405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the panel’s determination regarding the trial evidence supporting defendant’s kidnapping conviction.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/7409405/', '7409405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Appellate Division panel insofar as it reversed defendant’s conviction for kidnapping.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/7409405/', '7409405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*400We affirm in part and reverse in part the Appellate Division panel’s decision.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/7409405/', '7409405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that although the UDIR form is relevant to the State’s investigation of defendant for false swearing and fraud, the trial court properly quashed the State’s trial subpoena seeking defendant’s UDIR form to prosecute him.', 'general', 'In re Subpoena Duces Tecum On Custodian of Records', 'https://www.courtlistener.com/opinion/7409690/', '7409690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the relevancy of the information sought by the State to a potential criminal prosecution, we hold that the information is not subject to disclosure in response to the State’s trial subpoena.', 'general', 'In re Subpoena Duces Tecum On Custodian of Records', 'https://www.courtlistener.com/opinion/7409690/', '7409690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In an effort to balance these concerns, we hold that disclosure of the financial section of a defendant’s UDIR form where the State seeks to investigate and prosecute the defendant for false swearing and/or fraud is proper only in limited circumstances.', 'general', 'In re Subpoena Duces Tecum On Custodian of Records', 'https://www.courtlistener.com/opinion/7409690/', '7409690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the defendant’s financial disclosures to obtain a public defender should not be used to prosecute the pending case, a grand jury subpoena is the appropriate mechanism by which a defendant’s UDIR form may be sought in an appropriate case.', 'general', 'In re Subpoena Duces Tecum On Custodian of Records', 'https://www.courtlistener.com/opinion/7409690/', '7409690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶11] We conclude that the information from the conductor presented
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that at the time Morrison ordered a stop of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that the District Court was correct to follow this *287circuit’s well established procedure by refusing appellants’ pre- voir dire requests for a continuance42 or a change of venue.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore conclude that the probative value of the Ellsberg-Fielding break-in evidence far outweighed its prejudicial effect,160 and we hold that evidence of Ehrlichman’s relation to that venture was properly admitted into evidence.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the instruction which was given 200 fully satisfied Bronston, and we affirm the conviction.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the District Court did not abuse its discretion in denying the requested continuance.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered all of the arguments raised by each of the appellants, we conclude that there was no reversible error in this case.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not undertake a resolution of that controversy since we conclude that even under the appearance-of-impartiality standard the events in question pass muster.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have carefully reviewed the “Watergate” articles submitted by appellants, and we find that the pretrial publicity in this case, although massive, was neither as inherently prejudicial nor as unforgettable as the spectacle of Rideau’s dramatically staged and broadcast confession.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning now to Ehrlichman’s complaint in reference to congressional materials, we find that his discovery motion was similarly flawed.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 We affirm.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm the court’s decision not to grant a continuance, we do not decide whether appellants’ showing would have satisfied Rule 15’s requirements.', 'general', 'United States v. Haldeman', 'https://www.courtlistener.com/opinion/7891455/', '7891455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that entering without permission is not a lesser included offense of entering with the intent to commit a larceny.', 'general', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the elements applicable to this case, the trial court did not err when it refused to instruct the jury on entering without permission because entering without permission is not a lesser included offense of entering (without breaking) with the intent to commit a larceny.', 'general', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Heft has not demonstrated a clear error because he has not shown that the police failed to preserve exculpatory evidence.', 'general', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '42 We conclude that defense counsel was not ineffective by failing to challenge these statements.', 'ineffective_assistance', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Heft has not overcome the presumption that defense counsel’s decision was sound trial strategy.', 'general', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”46 We conclude that Heft has not overcome the strong presumption that defense counsel’s decision not to challenge this testimony constituted sound trial strategy.', 'general', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Heft has not overcome the presumption that defense counsel’s decision not to challenge the statement constituted *85sound trial strategy or shown that the admission of the evidence affected the outcome of his proceedings, we conclude that Heft has not shown ineffective assistance of counsel.', 'ineffective_assistance', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that entering without permission is not a lesser included offense of entering without breaking with the intent to commit larceny.', 'general', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '268639), p 2, in which we concluded that the defendant was properly convicted of entering with intent to commit a larceny when the defendant entered a resort building with permission.', 'general', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We affirm.', 'general', 'People v. Heft', 'https://www.courtlistener.com/opinion/8006741/', '8006741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Expanding on this ruling, we hold that a violation may be continuing under either the “amount owed theory” or the “time ordered theory.', 'general', 'People v. Monaco', 'https://www.courtlistener.com/opinion/8006109/', '8006109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to this case, we conclude that the statutory period of limitations on the felony-nonsupport charge against defendant has not yet begun to run.', 'general', 'People v. Monaco', 'https://www.courtlistener.com/opinion/8006109/', '8006109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '165, we conclude that felony-nonsupport charge against defendant does not violate ex post facto prohibitions.', 'general', 'People v. Monaco', 'https://www.courtlistener.com/opinion/8006109/', '8006109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Monaco', 'https://www.courtlistener.com/opinion/8006109/', '8006109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s denial of defendant’s motion to dismiss even though it reached the right result for the wrong reason.', 'dismissal', 'People v. Monaco', 'https://www.courtlistener.com/opinion/8006109/', '8006109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is hereby ordered, adjudged, and decreed that the Clerk of Court shall destroy any and all weapons and/or ammunitions in its possession and designated by me in the attached pages one (1) through seventeen (17) to be destroyed.', 'general', 'County of Greenville v. Mann', 'https://www.courtlistener.com/opinion/8326451/', '8326451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we REVERSE the circuit court’s order holding Mann in criminal contempt.', 'general', 'County of Greenville v. Mann', 'https://www.courtlistener.com/opinion/8326451/', '8326451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we agree that the district court, like this court, has no authority to add to those whom the legislature has identified as victims entitled to restitution, we reverse the restitution order and remand for proceedings consistent with this opinion.', 'general', 'State v. Christensen', 'https://www.courtlistener.com/opinion/8282273/', '8282273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the legislature did not include conservators among those who may be victims entitled to restitution, we reverse the restitution award to L.', 'general', 'State v. Christensen', 'https://www.courtlistener.com/opinion/8282273/', '8282273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because appellant’s challenge to his conviction is based on a misreading of the jury’s verdicts, we affirm the conviction.', 'general', 'State v. Christensen', 'https://www.courtlistener.com/opinion/8282273/', '8282273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury’s verdicts were not inconsistent, we affirm the denial of appellant’s motion for a new trial.', 'general', 'State v. Christensen', 'https://www.courtlistener.com/opinion/8282273/', '8282273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Based on the record, we conclude that Mikulak made statements, never withdrawn or corrected, that negated the mens rea element of the charged offense.', 'general', 'State v. Mikulak', 'https://www.courtlistener.com/opinion/8282575/', '8282575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even assuming without deciding that Mikulak violated the predatory-offender-registration statute by becoming homeless and failing to register within 24 hours of entering Renville County, we conclude that the factual basis was inadequate because it failed to establish that he knowingly did so.', 'general', 'State v. Mikulak', 'https://www.courtlistener.com/opinion/8282575/', '8282575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because ignorance of the law is a defense when the charged offense prohibits a knowing violation of a statutory provision, we reverse the court of appeals and remand to the district court for further proceedings consistent with this opinion.', 'general', 'State v. Mikulak', 'https://www.courtlistener.com/opinion/8282575/', '8282575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the foregoing reasons, we reverse the decision of the court of appeals and remand to the district court for further proceedings consistent with this opinion.', 'general', 'State v. Mikulak', 'https://www.courtlistener.com/opinion/8282575/', '8282575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 In Watkins, we held that “the phrase ‘knowingly violates this subdivision’ .', 'general', 'State v. Mikulak', 'https://www.courtlistener.com/opinion/8282575/', '8282575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it can, and we affirm the decision of the court of appeals.', 'general', 'State v. Boecker', 'https://www.courtlistener.com/opinion/8281583/', '8281583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully considering the parties’ interpretations in light of the plain language of the first-degree DWI statute and the applicable session law, we conclude that the State has the better interpretation: Boecker’s 1998 conviction was properly relied on to enhance his 2015 DWI charge to a first-degree offense.', 'general', 'State v. Boecker', 'https://www.courtlistener.com/opinion/8281583/', '8281583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In each case, we concluded that the defendant’s claim was “doomed on its merits” because a review of the session law “makes clear” that the statute was enacted with a proper enacting clause and title.', 'general', 'State v. Boecker', 'https://www.courtlistener.com/opinion/8281583/', '8281583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the court of appeals.', 'general', 'State v. Boecker', 'https://www.courtlistener.com/opinion/8281583/', '8281583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 39 (1993), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we conclude that § 48.', 'general', 'Racine Cnty. Human Servs. Dep''t v. L. R. H.-J. (In re J.N.J.-W.)', 'https://www.courtlistener.com/opinion/8288042/', '8288042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the statute is tailored to the government''s interest in protecting children from unfit parents and birth mother has failed to overcome the presumption of constitutionality beyond a reasonable doubt, we conclude that § 48.', 'general', 'Racine Cnty. Human Servs. Dep''t v. L. R. H.-J. (In re J.N.J.-W.)', 'https://www.courtlistener.com/opinion/8288042/', '8288042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that trial counsel did not perform deficiently by failing to raise the issue at the grounds phase of the TPR proceedings as counsel cannot be held deficient for failing to raise a losing argument.', 'general', 'Racine Cnty. Human Servs. Dep''t v. L. R. H.-J. (In re J.N.J.-W.)', 'https://www.courtlistener.com/opinion/8288042/', '8288042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that § 48.', 'general', 'Racine Cnty. Human Servs. Dep''t v. L. R. H.-J. (In re J.N.J.-W.)', 'https://www.courtlistener.com/opinion/8288042/', '8288042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On August 29, 2018, we concluded that there was at least one arguably meritorious issue that could be pursued, and we rejected the no-merit report and dismissed the appeal without prejudice.', 'dismissal', 'Racine Cnty. Human Servs. Dep''t v. L. R. H.-J. (In re J.N.J.-W.)', 'https://www.courtlistener.com/opinion/8288042/', '8288042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" While we agree that these factors are relevant to the TPR proceeding and it goes without saying that there will be circumstances specific to each TPR case, we find that these factors may be addressed during the disposition phase where the court determines what is in the best interests of the child under the totality of the circumstances.', 'general', 'Racine Cnty. Human Servs. Dep''t v. L. R. H.-J. (In re J.N.J.-W.)', 'https://www.courtlistener.com/opinion/8288042/', '8288042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we find that the statute is constitutional, birth mother''s trial counsel was not ineffective for failing to challenge the statutory basis at the grounds phase.', 'ineffective_assistance', 'Racine Cnty. Human Servs. Dep''t v. L. R. H.-J. (In re J.N.J.-W.)', 'https://www.courtlistener.com/opinion/8288042/', '8288042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '415(9m) is constitutional and, therefore, trial counsel did not perform deficiently, we affirm.', 'general', 'Racine Cnty. Human Servs. Dep''t v. L. R. H.-J. (In re J.N.J.-W.)', 'https://www.courtlistener.com/opinion/8288042/', '8288042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Minn.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/8288836/', '8288836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the court of appeals.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/8288836/', '8288836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Paradee , we concluded that an in camera approach was appropriate because it struck "a fairer balance between the interest of the privilege holder in having his confidences kept and the interest of the criminal defendant in obtaining all relevant evidence that might help in his defense.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/8288836/', '8288836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '282 (1871), in which we held that the "without" clause of the statute that was the precursor to the current third-degree murder statute was not an element of the offense.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, in Staples , we held that "without a design to effect death" in the second-degree manslaughter statute, Minn.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, in Walker , we held that the purpose of the clause "without intent to inflict great bodily harm" in an earlier version of a provision of the aggravated-assault statute, Minn.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 More recently, *742in Moore , we held that the phrase "without premeditation" in the second-degree murder statute, Minn.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 Finally, in Cole , we held that "without intent to effect the death of any person" in Minn.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Stokely line of precedent to this case, we conclude that the "without intent to effect the death of any person" clause of the third-degree murder statute, Minn.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 After reviewing the evidence presented by the State, we concluded that it "amply supports a conviction of third-degree murder.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the third-degree murder statute does not require the State to prove beyond a reasonable doubt that the defendant lacked an intent to effect the death of any person, we reverse and remand for consideration of Hall''s alternative argument.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*744We reverse the court of appeals decision because it is in direct conflict with the Stokely line of precedent.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the decision of the court of appeals and remand for further consideration of Hall''s arguments on appeal.', 'general', 'State v. Hall', 'https://www.courtlistener.com/opinion/8289137/', '8289137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that MCL 769.', 'general', 'People v. Skinner', 'https://www.courtlistener.com/opinion/8284903/', '8284903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the latter conclusion is erroneous.', 'general', 'People v. Skinner', 'https://www.courtlistener.com/opinion/8284903/', '8284903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the decision to sentence a juvenile to life without parole is to be made by a judge and that this decision is to be reviewed under the traditional abuse-of-discretion standard.', 'sentencing', 'People v. Skinner', 'https://www.courtlistener.com/opinion/8284903/', '8284903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 231 (2003), this Court held that a trial court''s decision to depart from the guidelines will be reviewed for an abuse of discretion.', 'general', 'People v. Skinner', 'https://www.courtlistener.com/opinion/8284903/', '8284903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the judgment of the Court of Appeals in Skinner and affirm the part of Hyatt that held that "[a] judge, not a jury, must determine whether to impose a life-without-parole sentence or a term-of-years sentence under MCL 769.', 'sentencing', 'People v. Skinner', 'https://www.courtlistener.com/opinion/8284903/', '8284903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse the part of Hyatt that adopted a heightened standard of review for life-without-parole sentences imposed under MCL 769.', 'sentencing', 'People v. Skinner', 'https://www.courtlistener.com/opinion/8284903/', '8284903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the judgment of the Court of Appeals in Skinner and affirm that part of Hyatt that held that "[a] judge, not a jury, must determine whether to impose a life-without-parole sentence or a term-of-years sentence under MCL 769.', 'sentencing', 'People v. Skinner', 'https://www.courtlistener.com/opinion/8284903/', '8284903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Decker''s simultaneous electronic communications with a minor are sufficient to support his convictions.', 'general', 'State v. Decker', 'https://www.courtlistener.com/opinion/8284760/', '8284760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the court of appeals.', 'general', 'State v. Decker', 'https://www.courtlistener.com/opinion/8284760/', '8284760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that with respect to that circumstance, the presence requirement was ambiguous because it was susceptible to more than one reasonable interpretation.', 'general', 'State v. Decker', 'https://www.courtlistener.com/opinion/8284760/', '8284760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 16 In Stewart , we held that merely presenting a document can satisfy the "representing" element of *120Wisconsin''s other identity theft statute, WIS.', 'general', 'State v. Mason', 'https://www.courtlistener.com/opinion/8285186/', '8285186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 4 We conclude that State v.', 'general', 'State v. Mason', 'https://www.courtlistener.com/opinion/8285186/', '8285186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 15 As noted, we conclude that our recent Stewart decision requires rejection of Mason''s argument.', 'general', 'State v. Mason', 'https://www.courtlistener.com/opinion/8285186/', '8285186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 29 For the reasons above, we affirm Mason''s conviction for two counts of identity theft.', 'general', 'State v. Mason', 'https://www.courtlistener.com/opinion/8285186/', '8285186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, reviewing the statute, we conclude that the issue involved in the present case is not whether Defendant “provided” Mr.', 'general', 'State v. Sexton', 'https://www.courtlistener.com/opinion/8913134/', '8913134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Notwithstanding the distinction between the present case and Barron, we conclude that, by Mr.', 'general', 'State v. Sexton', 'https://www.courtlistener.com/opinion/8913134/', '8913134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming arguendo it was error for the trial court to instruct the jury as it did, we find that such error was not plain error.', 'general', 'State v. Sexton', 'https://www.courtlistener.com/opinion/8913134/', '8913134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, after viewing the evidence in the light most favorable to the State, we conclude that the court did not err by denying defendant’s motion to dismiss the charge of communicating threats.', 'dismissal', 'State v. Hill', 'https://www.courtlistener.com/opinion/8913532/', '8913532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, because “[t]his is clearly contrary to Rule 21 of the General Rules of Practice, [former] Rule 10(b)(2) of the Rules of Appellate Procedure, and a long line of cases requiring ‘plain error’ review in the absence of an objection to a jury instruction,” we concluded that our review of this unpreserved error was “limited to plain error.', 'jury_instruction', 'State v. Hill', 'https://www.courtlistener.com/opinion/8913532/', '8913532') ON CONFLICT DO NOTHING;
