INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons set forth above, we affirm Mares’ conviction.', 'general', 'United States v. Mares', 'https://www.courtlistener.com/opinion/37726/', '37726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We will explain why the trial court''s sentence in this case was proper such that we affirm.', 'sentencing', 'State v. Lasanske', 'https://www.courtlistener.com/opinion/8239030/', '8239030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the district court’s summary judgment in favor of the defendants on the plaintiffs’ antitrust claim.', 'general', 'Forsyth v. Humana, Inc.', 'https://www.courtlistener.com/opinion/7045576/', '7045576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s summary judgment on the ERISA claims, reverse the district court’s summary judgment on the Sherman Act antitrust claims, and affirm in part and reverse in part summary judgment on the RICO claims.', 'general', 'Forsyth v. Humana, Inc.', 'https://www.courtlistener.com/opinion/7045576/', '7045576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s summary judgment against the Co-Payors on their breach of fiduciary duty claim under section 1132(a)(3) of ERISA We also affirm the district court’s summary judgment in favor of the Co-Payors on their benefits breach of contract claim under section 1132(a)(1) of ERISA and the district court’s computation of damages set forth in its July 29, 1994 order.', 'general', 'Forsyth v. Humana, Inc.', 'https://www.courtlistener.com/opinion/7045576/', '7045576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the district court’s partial summary judgment in favor of the defendants as to any claim by the plaintiffs for RICO damages in excess of these overpayments.', 'general', 'Forsyth v. Humana, Inc.', 'https://www.courtlistener.com/opinion/7045576/', '7045576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though he had not recently driven the vehicle, we concluded that Fleck “was in a position to exercise dominion or control over the vehicle and that he could, without too much difficulty, make the vehicle a source of danger.', 'general', 'Axelberg v. Commissioner of Public Safety', 'https://www.courtlistener.com/opinion/8281406/', '8281406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '79 did not clearly abrogate the common law defenses of waiver and estoppel, we concluded that the Legislature had not intended to abolish those defenses.', 'general', 'Axelberg v. Commissioner of Public Safety', 'https://www.courtlistener.com/opinion/8281406/', '8281406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite these limits, we concluded that the Legislature had not intended to abrogate the common law defenses of estoppel and waiver.', 'general', 'Axelberg v. Commissioner of Public Safety', 'https://www.courtlistener.com/opinion/8281406/', '8281406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'of this test” if we conclude that Pola “has not established
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'have given the instructions proposed by Pola, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Pola', 'https://www.courtlistener.com/opinion/10700414/', '10700414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶38    For the foregoing reasons, we affirm Pola’s convictions.', 'general', 'State v. Pola', 'https://www.courtlistener.com/opinion/10700414/', '10700414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that some of his parole conditions are impermissible on several grounds, but find no fault with the remainder.', 'general', 'Bleeke v. Lemmon', 'https://www.courtlistener.com/opinion/7167398/', '7167398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, finding that Gilfillen was attending the required sessions and that was all that was required under the trial court’s order.', 'general', 'Bleeke v. Lemmon', 'https://www.courtlistener.com/opinion/7167398/', '7167398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” But we affirm the trial court’s grant of summary judgment in favor of the Parole Board with respect to Bleeke’s remaining additional conditions.', 'general', 'Bleeke v. Lemmon', 'https://www.courtlistener.com/opinion/7167398/', '7167398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 247 (1970), where we stated that section 16-11-620 applies only to trespasses on private property, and where we held that the statute has no application to conduct at a public airport.', 'general', 'In the Interest of Joseph B.', 'https://www.courtlistener.com/opinion/8323990/', '8323990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in Perry that the right to a speedy trial applies only after a person has been accused.', 'general', 'Lightsey v. State', 'https://www.courtlistener.com/opinion/1658324/', '1658324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that by pleading guilty or nolo contendere defendants have waived their right to raise these issues on appeal.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, we hold that a defendant, after pleading guilty, may raise on appeal only those defenses and rights which would preclude the state from obtaining a valid conviction against the defendant.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we hold that a plea of nolo contendere has the same effect upon a defendant''s ability to raise an issue on appeal as does a plea of guilty.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a defendant may appeal from a denial of a Fourth Amendment or a Const 1963, art 1, § 11 search and seizure claim where "the defendant could not be prosecuted if *491 his claim that a constitutional right against unreasonable search and seizure was violated is sustained and the defendant, the prosecutor, and the judge have agreed to the conditional plea.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '362 NW2d 655 (1984), this Court held that a defendant could obtain appellate review following a plea of guilty of a decision denying a motion to suppress evidence where the prosecutor and judge agreed at *498 the time of the plea of guilty to a so-called conditional plea.', 'suppression', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, as this Court held in People v Reid, supra, appellate review is permissible following a plea of guilty when the prosecutor and the judge consent, then it ought to be questioned on what basis the prosecutor, the defendant''s adversary, and the judge, whose ruling would be reviewed, should be empowered to decide whether to allow or withhold "consent" to such review.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that none of the factors cited by the district court justified a departure.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the random firing of multiple shots into a group of people was contemplated by the legislature as the predicate facts upon which the presumptive sentence for second-degree murder by drive-by shooting is based, and therefore could not be used to justify an upward departure.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Ott, Ford, and Spaeth do not prohibit the district court from using "overlapping" facts to depart upward when a defendant is convicted of multiple offenses arising out of a single behavioral incident, if those facts show that the defendant committed the offense being sentenced in a particularly serious way.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For those reasons, we conclude that Jackson does not apply here.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that when a defendant is convicted of several offenses involving multiple victims arising out of a single behavioral incident, a sentencing *607 court may use "overlapping" facts of those offenses as the basis for an upward departure, provided that those facts show that the defendant committed the offense being sentenced in a particularly serious way.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that the district court did not err when it used the risk to bystanders arising from Edwards'' conduct as an aggravating factor.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that facts underlying an uncharged separate incident are an impermissible basis for departure because those facts do not show that the offense being sentenced was committed in a particularly serious way.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that such facts may be used to depart.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the reasons provided by the district court were improper bases for departure.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In both Ford and Spaeth, we concluded that the facts in question did not relate to the offense being sentenced.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, briefs, and prior holdings of this Court, we hold that there is no reversible error in this case.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1666205/', '1666205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that the lower court was correct in overruling Gray''s motion to quash the indictment.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1666205/', '1666205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the overwhelming evidence of guilt, we hold that any error does not rise to the level of reversal.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1666205/', '1666205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the photographs were not introduced into evidence as an attempt by the prosecutor to incite or inflame the jury so as to unfairly prejudice Gray.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1666205/', '1666205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence in the record presented before the Court, we hold that the jury verdict was not against the overwhelming weight of the evidence.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1666205/', '1666205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that a demand for dismissal coupled with a demand for an instant trial was insufficient to weigh this factor in favor of the defendant, where the motion came after the bulk of the entire period of delay had elapsed.', 'dismissal', 'Gray v. State', 'https://www.courtlistener.com/opinion/1666205/', '1666205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 468 (1971), we held that the Speedy Trial Clause of the Sixth Amendment does not apply to the period before a defendant is indicted, arrested, or otherwise officially accused:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held penetration may be established by circumstantial evidence.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1666205/', '1666205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the prosecutor''s comments regarding Blue''s guilt and the punishment due him were not personal opinion comments.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1666205/', '1666205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we hold that Walton and Apprendi are irreconcilable;', 'general', 'Bottoson v. Moore', 'https://www.courtlistener.com/opinion/1670351/', '1670351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1956), this Court held that any interference with the right to a unanimous verdict denies the defendant a fair trial.', 'general', 'Bottoson v. Moore', 'https://www.courtlistener.com/opinion/1670351/', '1670351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prosecution in the case at bar violated its duty to provide West pre-trial discovery of Dr.', 'general', 'West v. State', 'https://www.courtlistener.com/opinion/1670189/', '1670189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1935(2) is not impermissibly vague in all of its applications, as demonstrated by the facts of this case, and because it adequately specifies a comprehensible standard of prohibited core conduct, we hold that it is facially constitutional.', 'general', 'State v. Barnes', 'https://www.courtlistener.com/opinion/1671581/', '1671581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the statute as applied to the alleged conduct of the appellee is not facially void for vagueness, we reverse and remand for further proceedings.', 'general', 'State v. Barnes', 'https://www.courtlistener.com/opinion/1671581/', '1671581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court''s order, reinstate count one of the information, and remand for further proceedings.', 'general', 'State v. Barnes', 'https://www.courtlistener.com/opinion/1671581/', '1671581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Brown', 'https://www.courtlistener.com/opinion/1670023/', '1670023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we held that Mata voluntarily acquiesced in the questioning because he agreed to speak with officers after being "told at the police station that he could leave at any time.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the above facts, we held that the suspect''s confession was voluntary and, therefore, "properly entered into evidence.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because he did so after being advised that he was not required to stay, we conclude that Tyler, like Mata, "`voluntarily acquiesced to official requests to respond to questions.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the prosecution met its burden to show that Tyler''s confession was voluntarily made and was not the product of coercion.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the juvenile court correctly denied Tyler''s motion to suppress incriminating statements he made to officers at OCHS.', 'suppression', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that Tyler could be found to be a child defined under § 43-247(1) for disturbing Kimberly''s peace by enabling and encouraging others to harass her directly.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Mata,[18] we concluded that there was "no evidence of restrictions placed on [Raymond] Mata''s movement during questioning" even though Mata was questioned by a pair of officers in an unlocked room at the police station.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Mata''s interrogation was not custodial despite the fact that the interrogation took place in an undeniably police-dominated atmosphere.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm for the reasons set forth below.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found that all of Tyler''s assignments of error and arguments on appeal lack merit, we affirm the juvenile court''s judgment.', 'general', 'In Re Interest of Tyler F.', 'https://www.courtlistener.com/opinion/1670476/', '1670476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), we hold that chapter 95-184 violates the single subject rule and invalidate the law in its entirety.', 'general', 'Heggs v. State', 'https://www.courtlistener.com/opinion/1855113/', '1855113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that chapter 95-184, Laws of Florida, violates article III, section 6 of the Florida Constitution.', 'general', 'Heggs v. State', 'https://www.courtlistener.com/opinion/1855113/', '1855113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Thompson, we held that chapter 95-182, which addressed violent career criminal sentencing, was unconstitutional because the enactment embraced civil and criminal provisions that had no "natural or logical connection.', 'sentencing', 'Heggs v. State', 'https://www.courtlistener.com/opinion/1855113/', '1855113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the various sections contained in chapter 95-184, we conclude that our analysis in Thompson concerning chapter 95-182 must be applied herethe domestic violence provisions contained in chapters 95-182 and 95-184 are not naturally or logically connected to the remaining criminal subject matters contained in those chapter laws.', 'general', 'Heggs v. State', 'https://www.courtlistener.com/opinion/1855113/', '1855113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration, we find that severability is not appropriate in this case.', 'general', 'Heggs v. State', 'https://www.courtlistener.com/opinion/1855113/', '1855113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing Moreau, we find that the severability analysis set forth therein must be limited to the appropriations context.', 'general', 'Heggs v. State', 'https://www.courtlistener.com/opinion/1855113/', '1855113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that the doctrine of severability is applicable in the single subject rule context only in certain situations.', 'general', 'Heggs v. State', 'https://www.courtlistener.com/opinion/1855113/', '1855113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we conclude that section 776.', 'general', 'Smiley v. State', 'https://www.courtlistener.com/opinion/1682303/', '1682303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Simpson, in which we held that an inference of knowledge and control is warranted when the defendant shares exclusive dominion and control over the place where the drugs are found.', 'general', 'State v. Webb', 'https://www.courtlistener.com/opinion/1680623/', '1680623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That is because in Reeves we held that "where the accused *78 has not been in exclusive possession of the premises but only in joint possession, knowledge of the presence of the substances on the premises and the ability to maintain control over them by the accused will not be inferred but must be established by proof.', 'general', 'State v. Webb', 'https://www.courtlistener.com/opinion/1680623/', '1680623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that arson under section 806.', 'general', 'Linehan v. State', 'https://www.courtlistener.com/opinion/1688619/', '1688619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when the underlying felony upon which a felony murder charge is based is a specific intent offense, the defense of voluntary intoxication may apply to felony murder, but when the underlying felony is a general intent crime, the voluntary intoxication defense does not apply.', 'general', 'Linehan v. State', 'https://www.courtlistener.com/opinion/1688619/', '1688619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the present statutory definition of arson does not materially vary from the common law definition with regard to the requisite intent.', 'general', 'Linehan v. State', 'https://www.courtlistener.com/opinion/1688619/', '1688619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that the Florida Standard Jury Instructions schedule of lesser included offenses should be amended to include second-degree murder as a necessarily lesser included offense of first-degree felony murder.', 'jury_instruction', 'Linehan v. State', 'https://www.courtlistener.com/opinion/1688619/', '1688619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we hold that based upon the totality of the circumstances within the perception of the law enforcement officers in the instant case, probable cause to search the entirety of the respondent''s vehicle existed.', 'probable_cause', 'State v. Betz', 'https://www.courtlistener.com/opinion/1688769/', '1688769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001), we held that appellate courts must accord trial court rulings on motions to suppress "a presumption of correctness.', 'suppression', 'State v. Betz', 'https://www.courtlistener.com/opinion/1688769/', '1688769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] Thus, we conclude that the legitimate scope of the power of police officers to search an entire automobile, based upon the Ross generalized probable cause to do so, was not altered by the United States Supreme Court''s Acevedo opinion.', 'probable_cause', 'State v. Betz', 'https://www.courtlistener.com/opinion/1688769/', '1688769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this principle, we conclude that the police officer here had probable cause to search both the passenger compartment and the trunk of Betz''s automobile.', 'probable_cause', 'State v. Betz', 'https://www.courtlistener.com/opinion/1688769/', '1688769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances presented to the police here, we conclude that Officer Harrold possessed probable cause to search the entirety of the respondent''s automobile, including the trunk.', 'probable_cause', 'State v. Betz', 'https://www.courtlistener.com/opinion/1688769/', '1688769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having performed this review, we conclude that the trial court was correct in its determination that none of the evidence seized from the respondent''s vehicle should be suppressed based upon a violation of the Fourth Amendment to the United States Constitution.', 'suppression', 'State v. Betz', 'https://www.courtlistener.com/opinion/1688769/', '1688769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we concluded that the legislature had expressed a clear intent to punish possession of a firearm by a minor in addition to any other firearm-related offenses.', 'general', 'State v. Maxwell', 'https://www.courtlistener.com/opinion/1687214/', '1687214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we find that the multiple convictions and sentences in this case did not violate the constitutional protection against double jeopardy.', 'sentencing', 'State v. Maxwell', 'https://www.courtlistener.com/opinion/1687214/', '1687214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the totality of circumstances, however, we conclude that removal is not an appropriate sanction.', 'general', 'MISS. COM''N ON JUD. PERFORMANCE v. Guest', 'https://www.courtlistener.com/opinion/1688186/', '1688186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In response to Judge Guest''s argument that his educational level should be a mitigating factor in imposing a sanction, we find that this has little bearing on the appropriate sanction in the present case.', 'general', 'MISS. COM''N ON JUD. PERFORMANCE v. Guest', 'https://www.courtlistener.com/opinion/1688186/', '1688186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is hereby ordered that Judge Jerry W.', 'general', 'MISS. COM''N ON JUD. PERFORMANCE v. Guest', 'https://www.courtlistener.com/opinion/1688186/', '1688186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, given the court''s statements at sentencing, the state failed to show that the court did not rely on this information.', 'sentencing', 'Doty v. State', 'https://www.courtlistener.com/opinion/1693456/', '1693456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4th DCA 1994), we held that "unsubstantiated allegations of misconduct may not be considered by a trial judge at a criminal sentencing hearing and to do so violates fundamental due process.', 'sentencing', 'Doty v. State', 'https://www.courtlistener.com/opinion/1693456/', '1693456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse for resentencing.', 'sentencing', 'Doty v. State', 'https://www.courtlistener.com/opinion/1693456/', '1693456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that it did not meet that burden, we reversed.', 'general', 'Doty v. State', 'https://www.courtlistener.com/opinion/1693456/', '1693456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with Epprecht and Seays, we reverse and remand for resentencing in front of a different judge pursuant to this opinion, noting that sentencing on the battery conviction is barred by the double jeopardy clause.', 'sentencing', 'Doty v. State', 'https://www.courtlistener.com/opinion/1693456/', '1693456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm appellant''s convictions.', 'general', 'Doty v. State', 'https://www.courtlistener.com/opinion/1693456/', '1693456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In one of the few cases in which this court has addressed the issue of intent since the criminal code revisions, we held that the record must demonstrate more than an intent to temporarily deprive the owner of the property in order to prove a theft.', 'general', 'State v. Schminkey', 'https://www.courtlistener.com/opinion/1693511/', '1693511') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we agree with Judge Anstead and reject the reasoning as set forth in Johnson and Barber, we find that the impeachment *1132 issue has not been preserved for appellate review.', 'general', 'Parker v. State', 'https://www.courtlistener.com/opinion/1693352/', '1693352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the conviction below and acknowledge conflict with Hall.', 'general', 'Parker v. State', 'https://www.courtlistener.com/opinion/1693352/', '1693352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In O''Callaghan, we concluded that the defendant was not prejudiced by the lack of a felony murder charge in his indictment or by the instructions given to the jury on the crime as charged in the indictment.', 'general', 'Kearse v. State', 'https://www.courtlistener.com/opinion/1694532/', '1694532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we find that Kearse''s conviction is supported by competent, substantial evidence.', 'general', 'Kearse v. State', 'https://www.courtlistener.com/opinion/1694532/', '1694532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While most of Kearse''s penalty phase issues are without merit,[3] we find that several constituted error that requires a new sentencing proceeding before a jury.', 'sentencing', 'Kearse v. State', 'https://www.courtlistener.com/opinion/1694532/', '1694532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm Kearse''s convictions, but vacate his death sentence and remand for a new penalty phase proceeding before a jury.', 'sentencing', 'Kearse v. State', 'https://www.courtlistener.com/opinion/1694532/', '1694532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm Kearse''s convictions for first-degree murder and robbery with a firearm.', 'general', 'Kearse v. State', 'https://www.courtlistener.com/opinion/1694532/', '1694532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record and applicable case law this Court holds that the cumulative rulings of the court relative to Steed''s motion for continuance, motion for mistrial and preventing his counsel from arguing venue are supported by law and are without merit.', 'mistrial', 'Steed v. State', 'https://www.courtlistener.com/opinion/1691424/', '1691424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that the State showed impartiality, and, therefore, we affirm the trial court''s denial of the change of venue request.', 'general', 'Steed v. State', 'https://www.courtlistener.com/opinion/1691424/', '1691424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that the trial judge''s ruling did not constitute an abuse of discretion and was not in error.', 'general', 'Steed v. State', 'https://www.courtlistener.com/opinion/1691424/', '1691424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[W]e can only disturb the trial judge''s denial of a change of venue if we find that this ruling on the record has been a clear abuse of discretion.', 'general', 'Steed v. State', 'https://www.courtlistener.com/opinion/1691424/', '1691424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding his arguments without merit, we affirm.', 'general', 'Steed v. State', 'https://www.courtlistener.com/opinion/1691424/', '1691424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a comparison of the crime to the sentence imposed does not lead to an inference of gross disproportionality.', 'sentencing', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1694928/', '1694928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the issue of legal sufficiency, this Court held in Pinkney v.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1694928/', '1694928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in McFee v.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1694928/', '1694928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), this Court held that the appellant has the responsibility to present a trial record sufficient to undergird his assignments of error.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1694928/', '1694928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), this Court held that the general rule in Mississippi is that a sentence that does not exceed the maximum term allowed by the statute, cannot be disturbed on appeal.', 'sentencing', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1694928/', '1694928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), this Court held that a trial court "does not abuse its discretion in imposing a heavier sentence if the record reveals that the sentence was based on a presentence report and prior convictions.', 'sentencing', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1694928/', '1694928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in the conviction and sentence, we affirm in part, and reverse in part, the judgment of the Court of Appeals and reinstate and affirm in toto the judgment of the Circuit Court of DeSoto County.', 'sentencing', 'Miller v. State', 'https://www.courtlistener.com/opinion/1696019/', '1696019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that both the Court of Appeals and the Circuit Court of DeSoto County were correct in holding that the jury properly concluded from substantial evidence as revealed in the record, that Donald Wade Miller was guilty of arson, we affirm Miller''s conviction.', 'general', 'Miller v. State', 'https://www.courtlistener.com/opinion/1696019/', '1696019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4] Therefore, we affirm in part, and reverse in part, the judgment of the Court of Appeals and reinstate and affirm in toto the judgment of the DeSoto County Circuit Court.', 'general', 'Miller v. State', 'https://www.courtlistener.com/opinion/1696019/', '1696019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we hold that the trial court''s punishment falls well within its vast discretion and within the limits allowed by La.', 'general', 'Davis v. Harmony House Nursing Home', 'https://www.courtlistener.com/opinion/1694821/', '1694821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the record, we find that the trial court acted well within its discretion in determining the contempt violation for Bolen''s "use of insulting, abusive and discourteous language" "in irrelevant criticism of another attorney.', 'general', 'Davis v. Harmony House Nursing Home', 'https://www.courtlistener.com/opinion/1694821/', '1694821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that counsel''s statements about opposing counsel and his cross-examination of the district judge during the recusal hearing could be ruled contemptuous, we affirm.', 'general', 'Davis v. Harmony House Nursing Home', 'https://www.courtlistener.com/opinion/1694821/', '1694821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we affirm based upon the finding that Bolen''s arguments accusing plaintiff''s counsel of misleading the court and his discourteous questioning of Judge Crichton are sufficient grounds for the two contempt rulings.', 'general', 'Davis v. Harmony House Nursing Home', 'https://www.courtlistener.com/opinion/1694821/', '1694821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm appellant''s convictions and reject appellant''s claim that the proof was insufficient to sustain his conviction for tampering with evidence under section 918.', 'general', 'Hayes v. State', 'https://www.courtlistener.com/opinion/1859115/', '1859115') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Brooks''s claims arose at the moment the Rankin County deputy/jailor accepted custody of Brooks based on Martin''s surrender of him.', 'general', 'Brooks v. Pennington', 'https://www.courtlistener.com/opinion/1696651/', '1696651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that genuine issues of material fact exist sufficient to defeat summary judgment on this immunity ground.', 'general', 'Brooks v. Pennington', 'https://www.courtlistener.com/opinion/1696651/', '1696651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that section 11-46-9(1)(m) is, nevertheless, inapplicable to the facts before us.', 'general', 'Brooks v. Pennington', 'https://www.courtlistener.com/opinion/1696651/', '1696651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no appearance of impropriety and that this suit was filed in compliance with the MTCA, we find that the trial judge did not abuse his discretion in denying the order to recuse.', 'general', 'Brooks v. Pennington', 'https://www.courtlistener.com/opinion/1696651/', '1696651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that section 316.', 'general', 'State v. Bodden', 'https://www.courtlistener.com/opinion/1697396/', '1697396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the implied consent law for operators of motor vehicles does not require that urine testing methods be approved in accordance with the APA.', 'general', 'State v. Bodden', 'https://www.courtlistener.com/opinion/1697396/', '1697396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that section 316.', 'general', 'State v. Bodden', 'https://www.courtlistener.com/opinion/1697396/', '1697396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these distinctions, we conclude that a rational basis exists for treating the procedures for administering urine tests differently from the procedures for administering breath and blood tests and therefore reject Bodden''s argument that the statute violates equal protection.', 'general', 'State v. Bodden', 'https://www.courtlistener.com/opinion/1697396/', '1697396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We hold that any alleged statement made by Cook and some unidentified person on March 7 at which time Thorson revealed nothing had no bearing on Thorson''s confession on the Monday following.', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, based on the record, Evans'' conduct throughout the proceedings and the lack of a clear and unambiguous request, we hold that Evans'' continued acquiescence in representation by counsel waived his Faretta rights.', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that the "sheer number of law enforcement-connected persons in the jury pool, as well as persons selected as jurors, has worked a great hardship on Mhoon.', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting the opportunity for undue influence over the opinions of other jurors, we held that "under this novel situation the coercive inference on the jury precludes this Court from saying that this appellant was afforded his constitutional right of a trial by an impartial jury secured by Art.', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), we held that the trial judge properly sustained an objection to an argument that the jurors were representatives of "the people of the State of Mississippi and this community.', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" There, we held that the six-instruction limit is a "numerical beginning point .', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Each time we held that the instruction[s] did not violate the holding in McKoy v.', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 903 (1995), this Court held that "[t]he general rule is that for a confession to be admissible it must have been given voluntarily *634 and not given as a result of promises, threats or inducements.', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hunt, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), wherein this Court held that the confession was involuntary due to "various statements conveyed to Abram [which] proximately caused him to confess.', 'general', 'Evans v. State', 'https://www.courtlistener.com/opinion/1707183/', '1707183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that their aggregate effect was to deny the defendant below a fundamentally fair trial on whether he should suffer the death penalty.', 'general', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this tactic, combined with others, so prejudiced the jury that Jimbo Stringer did not receive a fair sentencing trial.', 'sentencing', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When combined with other tactics used by the prosecution during the sentencing phase, we hold that the cumulative effect was to deny Jimbo Stringer a fundamentally fair trial at the penalty phase.', 'sentencing', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these remarks, combined with: the introduction of photographs of Mrs.', 'general', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that no reversible error was committed during the trial on Jimbo Stringer''s guilt, and we thereby affirm his conviction.', 'general', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lucas, we held that this issue lacks merit.', 'general', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '826 (1896), this Court held that a witness may only be impeached on a statement which embodies "A fact substantive in its nature and relevant to the issue made in the case.', 'general', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that evidence to be inadmissible.', 'general', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 220 (1962), this Court held that it was not error to give the number of the convictions and the nature of the offenses.', 'general', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that that testimony did not waive his rights as to the confession.', 'general', 'Stringer v. State', 'https://www.courtlistener.com/opinion/1708859/', '1708859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Based upon the plain language of the Act, which is supported both by its legislative history[5] and by a subsequent clarifying amendment, we hold thatat least to the extent that the Act is properly construed to establish a mandatory minimum sentenceit does.', 'sentencing', 'State v. Cotton', 'https://www.courtlistener.com/opinion/1863312/', '1863312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] Because the "exception discretion" provision is otherwise subsumed by the State''s broad, underlying prosecutorial discretion, we hold that the Act, which establishes a mandatory minimum sentencing scheme, is not unconstitutional on its face as violative of separation of powers principles.', 'sentencing', 'State v. Cotton', 'https://www.courtlistener.com/opinion/1863312/', '1863312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the language of the Act is clear and unambiguous, we find it unnecessary to rely on legislative history.', 'general', 'State v. Cotton', 'https://www.courtlistener.com/opinion/1863312/', '1863312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that they are.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1710075/', '1710075') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the dismissal of the racketeering charge but affirm the dismissal of the remaining charges.', 'dismissal', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1710075/', '1710075') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do, however, find that the trial court erred in dismissing the racketeering charge and, therefore, we reverse the order granting the other motion to dismiss.', 'dismissal', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1710075/', '1710075') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986), this Court held that a statement given under oath during a police investigation is not a statement given at an "other proceeding" and consequently is not admissible as substantive evidence under section 90.', 'general', 'Pearce v. State', 'https://www.courtlistener.com/opinion/1707925/', '1707925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the error in excluding this evidence was harmless beyond a reasonable doubt in this case.', 'general', 'Pearce v. State', 'https://www.courtlistener.com/opinion/1707925/', '1707925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that any error in excluding extrinsic evidence of Brittingham''s prior inconsistent statements was harmless beyond a reasonable doubt under the facts of this case.', 'general', 'Pearce v. State', 'https://www.courtlistener.com/opinion/1707925/', '1707925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court properly applied the aggravating circumstance of commission during the course of a kidnapping in this case.', 'general', 'Pearce v. State', 'https://www.courtlistener.com/opinion/1707925/', '1707925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the CCP aggravating circumstance was properly found in this case.', 'general', 'Pearce v. State', 'https://www.courtlistener.com/opinion/1707925/', '1707925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we affirm the judgments and sentences.', 'sentencing', 'Pearce v. State', 'https://www.courtlistener.com/opinion/1707925/', '1707925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Pearce''s convictions for first-degree murder with a firearm and attempted first-degree murder with a firearm.', 'general', 'Pearce v. State', 'https://www.courtlistener.com/opinion/1707925/', '1707925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the reasons discussed above, we affirm Pearce''s convictions and his sentence of death.', 'sentencing', 'Pearce v. State', 'https://www.courtlistener.com/opinion/1707925/', '1707925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Therefore, we hold that where, as here, a prospective juror in a criminal case fails to respond to a relevant, direct, and unambiguous question presented by defense counsel on voir dire, although having knowledge of the information sought to be elicited, the trial court should, upon motion for a new trial, determine whether the question propounded to the juror was (1) relevant to the voir dire examination;', 'general', 'Mariner Health Care v. Estate of Edwards', 'https://www.courtlistener.com/opinion/1709406/', '1709406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though this Court held in Howard that licensees and administrators do not owe a duty of care to the residents, they do owe a duty to their employer.', 'general', 'Mariner Health Care v. Estate of Edwards', 'https://www.courtlistener.com/opinion/1709406/', '1709406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the failure to investigate alleged juror misconduct, the admission of improper evidence, and the failure to distinguish among defendants compel us to reverse the judgment for the Plaintiff and remand the case for further proceedings.', 'general', 'Mariner Health Care v. Estate of Edwards', 'https://www.courtlistener.com/opinion/1709406/', '1709406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, in this case, the failure to investigate juror misconduct jeopardized the parties'' right to a fair and impartial trial, and that consequently the judgment must be reversed.', 'general', 'Mariner Health Care v. Estate of Edwards', 'https://www.courtlistener.com/opinion/1709406/', '1709406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the use of the testimony at trial to emphasize the "bad corporate character" of Mariner, we find that admission of the testimony materially prejudiced the defendants.', 'general', 'Mariner Health Care v. Estate of Edwards', 'https://www.courtlistener.com/opinion/1709406/', '1709406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court erred in denying Mariner''s proposed instruction on separate consideration.', 'general', 'Mariner Health Care v. Estate of Edwards', 'https://www.courtlistener.com/opinion/1709406/', '1709406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, finding that "[t]he evidence is overwhelming that [the juror] withheld material information during voir dire which would have resulted in her being challenged by [the defendant], then relayed that exact disqualifying information to the other members of the jury during deliberations.', 'general', 'Mariner Health Care v. Estate of Edwards', 'https://www.courtlistener.com/opinion/1709406/', '1709406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the trial court.', 'general', 'Bowden v. State', 'https://www.courtlistener.com/opinion/1715144/', '1715144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '20 does not authorize the trial court to grant a money judgment *375 when seized property is missing or has been mistakenly returned to a third party, we reverse.', 'general', 'City of Milwaukee v. Glass', 'https://www.courtlistener.com/opinion/1718597/', '1718597') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Thomas'' conviction.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/1720359/', '1720359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reason to burden society as a whole with the losses of one who has failed to bargain for adequate contractual remedies, we concluded that "contract principles [are] more appropriate than tort principles for recovering economic loss without an accompanying physical injury or property damage.', 'general', 'Williams v. PEAK RESORTS INTERN. INC.', 'https://www.courtlistener.com/opinion/1720091/', '1720091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the partial summary judgment, and remand for further proceedings.', 'general', 'Williams v. PEAK RESORTS INTERN. INC.', 'https://www.courtlistener.com/opinion/1720091/', '1720091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the partial summary judgment, and remand this case to the trial court for further proceedings.', 'general', 'Williams v. PEAK RESORTS INTERN. INC.', 'https://www.courtlistener.com/opinion/1720091/', '1720091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the committees'' request to allow the routine sealing of such records must be denied.', 'general', 'Amend. to Fl. Family Law Rules of Proc.', 'https://www.courtlistener.com/opinion/1722627/', '1722627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree that a rule governing civil contempt should be adopted, but we conclude that neither of the committees'' proposals is completely acceptable.', 'general', 'Amend. to Fl. Family Law Rules of Proc.', 'https://www.courtlistener.com/opinion/1722627/', '1722627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the confusion and risk of unwarranted incarceration that have occurred in similar situations, we conclude that a second hearing must always be conducted when incarceration is deferred.', 'general', 'Amend. to Fl. Family Law Rules of Proc.', 'https://www.courtlistener.com/opinion/1722627/', '1722627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that hearing officers have no constitutional or statutory authorization to make recommendations regarding custody and visitation, and we accordingly conclude that they are not authorized to hear contested paternity proceedings.', 'general', 'Amend. to Fl. Family Law Rules of Proc.', 'https://www.courtlistener.com/opinion/1722627/', '1722627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '21, we hold that Section 828.', 'general', 'Bell v. State', 'https://www.courtlistener.com/opinion/1724503/', '1724503') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the wording of the statute not only restricts the courts'' ability to place defendants with prior felony convictions on probation, but it also restricts their ability to wholly or partially suspend the sentence of a previously convicted felon.', 'sentencing', 'Goss v. State', 'https://www.courtlistener.com/opinion/1725724/', '1725724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Causey', 'https://www.courtlistener.com/opinion/1726161/', '1726161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] We reverse because the trial court erred in finding that Ms.', 'general', 'State v. Walter', 'https://www.courtlistener.com/opinion/1726382/', '1726382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that none of the reasons cited by the court are sufficiently "clear and convincing" to justify departure from the guidelines.', 'general', 'Sarvis v. State', 'https://www.courtlistener.com/opinion/1726929/', '1726929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on points 1 and 2 and reverse on point 3.', 'general', 'Sarvis v. State', 'https://www.courtlistener.com/opinion/1726929/', '1726929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the evidence presented, we conclude that the lower tribunal reversibly erred by refusing *1030 to instruct the jury on the law of self-defense.', 'general', 'Langston v. State', 'https://www.courtlistener.com/opinion/1728995/', '1728995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that it was reversible error not to give the instruction, we affirm the escape conviction, reverse the resisting with violence conviction, and remand for a new trial with directions to give the instruction.', 'general', 'Langston v. State', 'https://www.courtlistener.com/opinion/1728995/', '1728995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we AFFIRM the conviction for escape, REVERSE the conviction for resisting with violence, and REMAND for a new trial with directions to the trial court to give the requested instruction.', 'general', 'Langston v. State', 'https://www.courtlistener.com/opinion/1728995/', '1728995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson and Fairman, both cases in which the dangerous act was directed to only one person not others, and deliberately so as well, we held that the defendant could be prosecuted under subparagraph (b).', 'general', 'Windham v. State', 'https://www.courtlistener.com/opinion/1723898/', '1723898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Griffin, this Court held that "the Weathersby Rule is not the proper subject of an instruction to the jury.', 'general', 'Windham v. State', 'https://www.courtlistener.com/opinion/1723898/', '1723898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed because of confusing instructions blurring the distinction between a subparagraph (a) murder by deliberate design with the crime of manslaughter committed in the heat of passion.', 'general', 'Windham v. State', 'https://www.courtlistener.com/opinion/1723898/', '1723898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there may have been error in denying the motion to compel discovery and ruling in effect that a self-defense argument was not permissible.', 'general', 'Ivester v. State', 'https://www.courtlistener.com/opinion/1730114/', '1730114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the defendant was identified beyond a reasonable doubt we affirm the first point.', 'general', 'Ivester v. State', 'https://www.courtlistener.com/opinion/1730114/', '1730114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that John Toney, who had sworn his unconditional ownership of the subject currency, who had never disavowed such ownership, and for which no other competing claim had been made to the seizing authority, had a sufficient property interest to confer him standing to proceed with his claims at the adversarial preliminary hearing stage of a forfeiture proceeding pursuant to Florida''s Contraband Forfeiture Act.', 'general', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, at the preliminary adversarial hearing stage, we hold that a person entitled to notice, whose sworn and uncontradicted testimony establishes ownership of *755 the subject currency and who has never disavowed such ownership, has demonstrated a sufficient property interest to confer them standing to proceed with their claims.', 'general', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the ten-day time requirement for providing the adversarial preliminary hearing is mandatory, but where the seizing authority has acted immediately and the delay is caused by the court, unless the claimant can show harm, the forfeiture action should not be summarily dismissed.', 'dismissal', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the stated reasons, we conclude that the inquiry on standing must be confined to facts relating to the issue of ownership, not the ultimate merits of the case.', 'general', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While Munoz stated that a "[a]t a bare minimum, we conclude that a claimant to *751 seized currency must come forward with sworn proof of a possessory and/or ownership interest in the same to acquire standing to contest the forfeiture proceeding," the case involved the standing requirement at an adversarial preliminary hearing, not the actual forfeiture proceeding.', 'general', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Toney has established standing, we reverse and remand in his case with directions to proceed to a trial on the merits.', 'general', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing analysis, we find that Toney established standing at the adversarial preliminary hearing stage of a forfeiture proceeding sufficient to be able to contest probable cause for the seizure.', 'probable_cause', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wayne Chuck''s case, because there *739 was evidence that he contradicted himself as to the ownership of the currency, we reverse and remand for a new hearing on standing.', 'general', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed because Chuck was not given a preliminary hearing within the ten day-period provided in section 932.', 'general', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court''s order in Chuck''s case and remand for a new hearing on standing under the procedure outlined here.', 'general', 'Chuck v. City of Homestead Police Dept.', 'https://www.courtlistener.com/opinion/1731247/', '1731247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the circuit court erred when it denied Nguyen''s motion for judgment notwithstanding the verdict.', 'general', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the State presented sufficient evidence to satisfy the "Transport" prong of Section 97-23-101(1)(b)(ii)(1).', 'general', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the State presented sufficient evidence that the money derived from "some form of unlawful activity"  narcotics trafficking.', 'general', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As for Tran''s ineffective assistance of counsel claim, we find that allegation to be premature.', 'ineffective_assistance', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'above, we found that the State presented insufficient evidence that Nguyen knew the money represented proceeds of specified unlawful activity.', 'general', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Nguyen''s conviction and render a judgment of acquittal for Nguyen.', 'general', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Nguyen''s conviction and render a judgment of acquittal.', 'general', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we affirm.', 'general', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we do not consider the issue due to the state of the record, assuming we affirm the conviction, Tran may raise his ineffective assistance of counsel claim in post-conviction relief proceeding.', 'ineffective_assistance', 'Tran v. State', 'https://www.courtlistener.com/opinion/1732247/', '1732247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we hold that a reversal of Vance''s conviction for third-degree assault is necessary.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moore, we held that harmless error analysis is not applicable when the defendant is deprived of the right to have the jury determine that every element of the charged offense has been established.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Ihle, we held that jury instructions that omitted an element of the offense did not meet the third prong of the plain error test because there was "no *661 reasonable likelihood that a more accurate instruction would have changed the outcome.', 'jury_instruction', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Baird, for example, we held that a jury instruction that erroneously stated that the defendant, who claimed self defense, had a duty to retreat from his home met the third prong of the plain error test.', 'jury_instruction', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If the three prongs of the plain error test are met, we may reverse if we conclude that reversal is required to ensure fairness and the integrity of the judicial proceedings.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that by omitting CRIMJIG 13.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we conclude that by instructing the jury that "it is not necessary for the State to prove that [Vance] intended to inflict substantial bodily harm" (emphasis added), the court gave the jury the opposite impression, namely that intent to harm did not have to be proven, and that intent to commit the act that resulted in the harm was enough.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the instructions the district court gave to the jury were erroneous because they created the possibility that the jury convicted Vance without finding that he intended to cause bodily harm.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that such an argument is more appropriately considered under the third prong of the plain error test, as the legal issue that is arguably unclear is whether jury instructions that omit an element of the crime can ever be harmless.', 'jury_instruction', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the district court committed plain error when it failed to instruct the jury on the intent element of the crime of third-degree assault.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we hold that the district court erred when it denied Flowers'' motion to suppress the use of the gun as evidence.', 'suppression', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the court erred when it gave the additional instruction.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Olson, we held that the district court''s instruction was improper, and said that instructions on inferences "should be avoided as much as possible.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing general principles, we conclude that the officers did not carefully and appropriately limit their response to the facts and circumstances of this case.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if we were to assume that all of the actions taken by the officers to this point were permissible, we conclude that the officers impermissibly exceeded the scope of a Terry stop whenafter their search of Flowers, their search of the vehicle, and the dog-sniff search of the vehiclethe officers returned to the vehicle and conducted another search which lasted for an unknown period of time.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that it is not plausible to believe that during that interval the officers gained a reasonable suspicion that Flowers might have been illegally possessing a firearm.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the officers exceeded the permissible *258 scope of a Terry search when they conducted this search.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the totality of these facts and circumstances, we conclude that the state has not met its burden of proving that this Terry search was appropriately limited in scope.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred when it failed to make a record that it specifically considered and weighed the Jones factors.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have previously noted, however, that we will not hesitate to order a new trial when the state, intentionally or unintentionally, elicits information ruled to be inadmissible and we conclude that information is prejudicial to the defendant.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this court held that to be convicted twice under the same statutory offense as to the same factual event violated Miles'' double jeopardy rights and reversed one conviction.', 'general', 'Hoag v. State', 'https://www.courtlistener.com/opinion/1742825/', '1742825') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986), where this court held that giving three altered dollar bills to one person at one time constituted but one criminal act of uttering.', 'general', 'Hoag v. State', 'https://www.courtlistener.com/opinion/1742825/', '1742825') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), this Court held that the statutory provision pertaining to the lack of consent of the owners or occupiers of the structure or conveyance is not an essential element of the crime but creates a defense that must be raised affirmatively.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/1744064/', '1744064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that an indictment or information charging burglary is not required to specify the offense which the accused is alleged to have intended to commit.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/1744064/', '1744064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the constitutional requirements of the Confrontation Clause were met.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Officer Puckett''s testimony from the bond-revocation hearing was erroneously admitted into evidence under Ark.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the improper admission of Officer Puckett''s testimony was harmless error as to the offense of third-degree battery.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the testimony was well-developed because of the cross-examination of the witness with the purpose to impeach the testimony on the very point at issue at trial.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Johnson, we held that the motive to develop testimony at a probable-cause hearing was not similar to the motive to cross-examine at a trial.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the cross-examination was sufficient.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even without Officer Puckett''s testimony, we conclude that the evidence of Proctor''s guilt on the stalking charge is overwhelming and, thus, the improper admission of the officer''s testimony was harmless as to the offense of second-degree stalking.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the erroneous admission of Officer Puckett''s testimony was harmless as to the offense of first-degree terroristic threatening.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Vick, we concluded that the cross-examination of the witness at a habeas corpus hearing was sufficient.', 'habeas', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm those convictions, but reverse and remand the attempted-murder conviction.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that "a jury, as trier of fact, was entitled to believe all or part of the conflicting testimony proffered and introduced by either side.', 'general', 'Bignall v. State', 'https://www.courtlistener.com/opinion/1756851/', '1756851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Bignall v. State', 'https://www.courtlistener.com/opinion/1756851/', '1756851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence in this case clearly satisfies the standards for an instruction on a lesser included offense, we reverse the court of appeals'' opinion and remand the cause to the court of appeals for a harm analysis.', 'general', 'Bignall v. State', 'https://www.courtlistener.com/opinion/1756851/', '1756851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Horstmann v. Re', 'https://www.courtlistener.com/opinion/5127964/', '5127964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"In our judgment, however, no equal protection question is presented because we hold that the legislature did not intend to exclude drug-related offenses from the operation of the Habitual Felony Offender Act.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We hold that extrinsic evidence is not admissible to prove that a conviction in a foreign jurisdiction would have been a felony in Minnesota if, by definition, that crime could have constituted an offense which is not a felony in this state.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Hines case comes closer to carrying out the intent of our legislature, but we do not address in this opinion how the state can make proof of a "prior conviction.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that Temporary Rule 6(b)(3)(iv) was adopted to further the purposes of the Habitual Offender Act, as intended by the legislature.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Court of Criminal Appeals has authority to remand a case, if it determines justice would require it, to the trial court for a determination to be made on the defendant''s claim that he was inadequately represented at his trial.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the evidence, we find that it supports the verdict of the jury.', 'general', 'Washington v. State', 'https://www.courtlistener.com/opinion/1778449/', '1778449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding the issues raised by Washington to be procedurally barred, moot or meritless, we affirm the jury''s verdict.', 'general', 'Washington v. State', 'https://www.courtlistener.com/opinion/1778449/', '1778449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Fourteenth Court of Appeals.', 'general', 'Stennett v. State', 'https://www.courtlistener.com/opinion/1780677/', '1780677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We therefore hold that under the Double Jeopardy Clause a defendant who has already been punished in a criminal prosecution may not be subjected to an additional civil sanction to the extent that the second sanction may not be characterized as remedial, but only as a deterrent or retribution.', 'general', 'Stennett v. State', 'https://www.courtlistener.com/opinion/1780677/', '1780677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 362 (1994), where this court held that, in cases where less than the presumptive amount was found in possession of the accused, but other proof of intent to deliver was present, the appellant''s conviction for possession with intent to deliver was proper.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/1781273/', '1781273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we find that due process requires that the trial judge at least orally inform the defendant of the terms and conditions upon which his suspended sentence is contingent before it may be properly revoked for the violation of those terms and conditions.', 'sentencing', 'Artis v. State', 'https://www.courtlistener.com/opinion/1879608/', '1879608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was no proof at trial under the correct measure of damages, we reverse the final judgment and remand for the entry of a judgment for the defendants.', 'general', 'Teca, Inc. v. WM-Tab, Inc.', 'https://www.courtlistener.com/opinion/1778742/', '1778742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment in favor of appellee and remand to the trial court for the entry of judgment in favor of appellants.', 'general', 'Teca, Inc. v. WM-Tab, Inc.', 'https://www.courtlistener.com/opinion/1778742/', '1778742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the cross-appeal, we affirm the trial court''s finding of no liability on the fraudulent misrepresentation count.', 'general', 'Teca, Inc. v. WM-Tab, Inc.', 'https://www.courtlistener.com/opinion/1778742/', '1778742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In so doing, we hold that because the Legislature did not include fraudulent intent as an element of unlawful insurance solicitation, the statute at issue unconstitutionally infringes upon the protections afforded commercial speech by the First Amendment to the United States Constitution.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/1882186/', '1882186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the language of this statute is facially clear and unambiguous, our analysis need not proceed any further.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/1882186/', '1882186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court''s reasoning that the concept of reading statutes in pari materia necessarily incorporates the fraud requirement contained in subsection (1) into subsection (8) is premised on a misguided interpretation of that particular canon of statutory construction.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/1882186/', '1882186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the plain meaning of the statute does not indicate that fraud is an element;', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/1882186/', '1882186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we conclude that the Legislature has not included fraudulent intent as an element of the offense of unlawful insurance solicitation.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/1882186/', '1882186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the statute does not directly and materially alleviate the problem of insurance fraud and actually condemns totally lawful conduct.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/1882186/', '1882186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Wife''s petition to extend the injunction did not allege any fear of domestic violence and because the trial court did not make any findings that the Wife had any objectively reasonable fear of domestic violence, we reverse.', 'general', 'Giallanza v. Giallanza', 'https://www.courtlistener.com/opinion/1882203/', '1882203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the consideration during the sentencing phase of a statutorily prescribed aggravating circumstance enacted following the crime required reversal, notwithstanding a failure to bring the issue to the attention of the trial court.', 'sentencing', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 772 (1993), in which we held that when the defendant is allowed to present the possible mitigators and the jury is told it is not limited to the mitigators listed on the form, it is not error to submit the standard form to the jury in lieu of a form proposed by the defendant.', 'general', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 800 (1992), in which this court held that Ark.', 'general', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the capital murder conviction, but we reverse the death sentence and remand for new sentencing.', 'sentencing', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm his convictions for capital murder, but reverse and remand his two sentences of death.', 'sentencing', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the DUI manslaughter standard jury instruction should not be modified to include a negligence element.', 'jury_instruction', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1781522/', '1781522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of that reasoning, we held that neither negligence nor proximate causation was an element of DUI manslaughter.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1781522/', '1781522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that Magaw has been misinterpreted by several district courts as reading a separate and independent negligence element into the crime of DUI manslaughter.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1781522/', '1781522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in that case we concluded that "[i]t was not necessary to allege culpable negligence of the defendant in the operation of the motor vehicle, as that is not a specific element of the offense defined by the particular statute.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1781522/', '1781522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon consideration of those factors, we concluded that the 1986 amendments to section 316.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1781522/', '1781522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we found that "[s]ilence does not suggest that the legislature dispensed with scienter here.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1781522/', '1781522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that Stoop and Smith do not require reversal today.', 'general', 'Heidel v. State', 'https://www.courtlistener.com/opinion/1784227/', '1784227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained below, we hold that such claims are insufficient to meet both prongs of the test for alleging the ineffective assistance of counsel established in Strickland v.', 'ineffective_assistance', 'State v. Dickey', 'https://www.courtlistener.com/opinion/1784700/', '1784700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that wrong advice about the consequences for a crime not yet committed cannot constitute ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Dickey', 'https://www.courtlistener.com/opinion/1784700/', '1784700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a claim that counsel affirmatively misadvised a defendant about the collateral effect of future sentence-enhancing potential does not meet Strickland''s requirements for a valid claim of ineffective assistance of counsel.', 'sentencing', 'State v. Dickey', 'https://www.courtlistener.com/opinion/1784700/', '1784700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3]  Because the State has not raised the issue, because it is beyond the question certified, and because we hold that Dickey is not entitled to relief on the merits, we need not decide whether the enhancement of Dickey''s Alabama sentence based on the prior Florida conviction constitutes "newly discovered evidence" under Florida Rule of Criminal Procedure 3.', 'sentencing', 'State v. Dickey', 'https://www.courtlistener.com/opinion/1784700/', '1784700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that allegations of affirmative misadvice by trial counsel on the sentence-enhancing consequences of a defendant''s plea for future criminal behavior in an otherwise facially sufficient motion are not cognizable as an ineffective assistance of counsel claim.', 'sentencing', 'State v. Dickey', 'https://www.courtlistener.com/opinion/1784700/', '1784700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "the proper interpretation of Hill is to follow its express language.', 'general', 'State v. Dickey', 'https://www.courtlistener.com/opinion/1784700/', '1784700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 3 We conclude that the discovery that Shaibani testified falsely about his credentials is newly-discovered evidence that gives rise to a reasonable probability that, had the jury heard Shaibani''s misrepresentation about his credentials, it would have had a reasonable doubt as to Plude''s guilt.', 'general', 'State v. Plude', 'https://www.courtlistener.com/opinion/1784049/', '1784049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 36 We conclude that in a trial rife with conflicting and inconclusive medical expert testimony about a case the circuit court observed was based on "circumstantial evidence," there exists a reasonable probability that, had the jury discovered that Shaibani lied about his credentials, it would have had a reasonable doubt as to Plude''s guilt.', 'general', 'State v. Plude', 'https://www.courtlistener.com/opinion/1784049/', '1784049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 50 We conclude that the discovery that Shaibani testified falsely about his credentials is newly-discovered evidence that gives rise to a reasonable probability that had the jury heard of Shaibani''s misrepresentation about his credentials, it would have had a reasonable doubt as to Plude''s guilt.', 'general', 'State v. Plude', 'https://www.courtlistener.com/opinion/1784049/', '1784049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" That section provides this court with unique, discretionary authority to order a new trial when we conclude that the real controversy has not been fully tried or when there is a probable miscarriage of justice.', 'general', 'State v. Plude', 'https://www.courtlistener.com/opinion/1784049/', '1784049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court''s exclusion of defense witness Wendy Baudin, and the denial of judgment of acquittal as to the charge of reckless driving, and remand for a new trial.', 'general', 'Miller v. State', 'https://www.courtlistener.com/opinion/1788288/', '1788288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Miller v. State', 'https://www.courtlistener.com/opinion/1788288/', '1788288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming arguendo that the double jeopardy clauses do apply, we hold that dismissal of the complaint in Case No.', 'dismissal', 'Mississippi State Bar v. Young', 'https://www.courtlistener.com/opinion/1789160/', '1789160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without further ado, we hold that MSB''s Assignment of Error No.', 'general', 'Mississippi State Bar v. Young', 'https://www.courtlistener.com/opinion/1789160/', '1789160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that MSB''s Assignment of Error No.', 'general', 'Mississippi State Bar v. Young', 'https://www.courtlistener.com/opinion/1789160/', '1789160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] There, we held that a trial judge may impose costs against an indigent defendant, provided:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Jenkins had not been given adequate prior notice that the costs would be assessed against him at the sentencing hearing, we held that the assessment violated his due process rights.', 'sentencing', 'State v. Beasley', 'https://www.courtlistener.com/opinion/1791940/', '1791940') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because of this language, we held that the statute required the court to make a determination of indigency at the sentencing hearing prior to assessing costs.', 'sentencing', 'State v. Beasley', 'https://www.courtlistener.com/opinion/1791940/', '1791940') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jenkins, this Court held that the state must provide a defendant with adequate notice and an opportunity to object to the assessment of costs pursuant to sections 960.', 'general', 'State v. Beasley', 'https://www.courtlistener.com/opinion/1791940/', '1791940') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was more than sufficient evidence of probable cause for Smith to initiate criminal charges against *75 Croft.', 'probable_cause', 'Croft v. Grand Casino Tunica, Inc.', 'https://www.courtlistener.com/opinion/1881078/', '1881078') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these facts we find that Smith on behalf of the Casino possessed sufficient probable cause at the time the affidavit was filed charging Croft with petit larceny and thus Croft''s action for malicious prosecution must fail.', 'probable_cause', 'Croft v. Grand Casino Tunica, Inc.', 'https://www.courtlistener.com/opinion/1881078/', '1881078') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that there was abundant probable cause for Croft''s arrest.', 'probable_cause', 'Croft v. Grand Casino Tunica, Inc.', 'https://www.courtlistener.com/opinion/1881078/', '1881078') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By Croft''s own testimony we find that he failed to support this allegation as is shown by his deposition testimony:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We find that there was no evidence of the Casino attempting to extort money from Croft.', 'general', 'Croft v. Grand Casino Tunica, Inc.', 'https://www.courtlistener.com/opinion/1881078/', '1881078') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that his issue is moot *78 due to our finding that summary judgment is appropriate.', 'general', 'Croft v. Grand Casino Tunica, Inc.', 'https://www.courtlistener.com/opinion/1881078/', '1881078') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Croft v. Grand Casino Tunica, Inc.', 'https://www.courtlistener.com/opinion/1881078/', '1881078') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Estelle has not been overruled, and with the factual situation here being far more similar to that of Rummel, we find that the second assignment of error is without merit and there is no Eighth Amendment violation.', 'general', 'Barnwell v. State', 'https://www.courtlistener.com/opinion/1806339/', '1806339') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16 ("Only when the officer, by means of physical force or show of authority, has in some way restrained the liberty of a citizen may we conclude that a `seizure'' has occurred.', 'general', 'Perez v. State', 'https://www.courtlistener.com/opinion/1811320/', '1811320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 497 (1980) ("We conclude that a person has been "seized" within the meaning of the Fourth Amendment only if, in view of all of the circumstances surrounding the incident, a reasonable person would have believed that he was not free to leave.', 'search_seizure', 'Perez v. State', 'https://www.courtlistener.com/opinion/1811320/', '1811320') ON CONFLICT DO NOTHING;
