INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing Monforte''s responses during voir dire, we conclude that the trial court acted within its discretion in granting the challenge for cause.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1822394/', '1822394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that he has not demonstrated reversible error as to either his first-degree murder conviction or death sentence.', 'sentencing', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1822394/', '1822394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court acted within its discretion under the rules of evidence, specifically sections 90.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1822394/', '1822394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State presented sufficient evidence to support the verdict on both the underlying felonies and first-degree felony murder.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1822394/', '1822394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that death is proportionate in this case.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1822394/', '1822394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in comparison with analogous cases in which this Court ruled that death was a proportionate penalty, the sentence here is not constitutionally disproportionate.', 'sentencing', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1822394/', '1822394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering all issues raised, we affirm the convictions and the sentence of death.', 'sentencing', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1822394/', '1822394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth herein, we affirm Johnson''s convictions, including his conviction of first-degree murder, and his sentence of death.', 'sentencing', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1822394/', '1822394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the postconviction court erred when it declined to consider Maurstad''s criminal history score claim on the basis of waiver.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in Goff, we held that a defendant may challenge a criminal history score for the first time after sentencing, when the score includes a prior conviction obtained in violation of the defendant''s right to counsel.', 'sentencing', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we conclude that because a sentence based on an incorrect criminal history score is an illegal sentence  and therefore, under Minn.', 'sentencing', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that a defendant cannot forfeit review of his criminal history score calculation, and accordingly, the plain error doctrine is inapplicable in this case.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite the state''s initial contention that the applicable guidelines are unambiguous, we conclude that the state''s arguments center not on the unambiguous nature of the guidelines'' language, but rather on the intent behind that language.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'c is relevant here, because we conclude that the language of this section is ambiguous in light of the words the Pennington County District Court used in "pronouncing" Maurstad''s length of stay.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if the Pennington County District Court had placed Maurstad on probation for 10 years, he could have been "discharged early from probation" on any date before 10 years had passed and therefore still be within the "initial length of stay" when he committed the current offenses.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Drawing on the discussion in Osborne, we conclude that just as it would be logically untenable to allow a defendant to waive by silence a right that he must waive by affirmative act, it would be logically untenable to allow a defendant to waive by silence an alleged error that he cannot waive by affirmative act.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Osborne where we concluded that application of the plain error doctrine was not appropriate.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Osborne we found that the defendant was not aware of the issue that was the subject of appellate review.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, as to the description of the offense, HRS § 291E-61, which relates to operating a vehicle under the influence of an intoxicant, substantially reenacted HRS § 291-4.', 'general', 'State v. Domingues', 'https://www.courtlistener.com/opinion/2509316/', '2509316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a fact susceptible to jury determination is a predicate to the imposition of an enhanced sentence, the Hawai''i Constitution requires that such factual determinations be made by the trier of fact.', 'sentencing', 'State v. Domingues', 'https://www.courtlistener.com/opinion/2509316/', '2509316') ON CONFLICT DO NOTHING;
