INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the holding that the Family Part has the authority to retain and dispose of weapons even after the dismissal of a domestic violence complaint.', 'dismissal', 'In re Return of Weapons to J.W.D.', 'https://www.courtlistener.com/opinion/7406121/', '7406121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the content of the instant messages written by and to the victim in this case constitutes “sexual conduct” within the meaning of N.', 'general', 'State v. J.A.C.', 'https://www.courtlistener.com/opinion/7409366/', '7409366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in this case, the trial court conducted the careful inquiry required by N.', 'general', 'State v. J.A.C.', 'https://www.courtlistener.com/opinion/7409366/', '7409366') ON CONFLICT DO NOTHING;
