INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Nash has met prongs one and three of the Carter test.', 'general', 'State v. Nash', 'https://www.courtlistener.com/opinion/7409500/', '7409500') ON CONFLICT DO NOTHING;
