INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons already expressed, we hold that Nash is entitled to a new trial based on newly discovered evidence.', 'general', 'State v. Nash', 'https://www.courtlistener.com/opinion/7409500/', '7409500') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that had that evidence been presented to the jury, the outcome of the case probably would have been different.', 'general', 'State v. Nash', 'https://www.courtlistener.com/opinion/7409500/', '7409500') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when no such undisputed facts exist or findings are made, prior dismissed charges may not be considered for any purpose.', 'dismissal', 'State v. K.S.', 'https://www.courtlistener.com/opinion/7410409/', '7410409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we concluded that the offenses were too “temporally distant” to support a finding by the prosecutor of a “ ‘pattern of anti-social behavior,’ ” we held that a broad category of offenses could be considered in determining an applicant’s suitability for Pretrial Intervention.', 'general', 'State v. K.S.', 'https://www.courtlistener.com/opinion/7410409/', '7410409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that defendant has no prior offenses that could be considered in evaluating his PTI application, we find that remand is warranted to consider de novo whether the medical evidence of defendant’s bipolar disorder applies to the factors relating to his admission into, or presumptive exclusion from PTI.', 'general', 'State v. K.S.', 'https://www.courtlistener.com/opinion/7410409/', '7410409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the prosecutor’s decision was based on “consideration of inappropriate factors or not premised upon a consideration of all relevant factors,” we reverse the judgment of the Appellate Division, and remand this matter to the Somerset County Prosecutor for further consideration of the medical evidence provided by defendant, the victim’s objection to defendant’s admission into PTI, and the assaultive and violent nature of the offense charged, to determine whether to admit de...', 'general', 'State v. K.S.', 'https://www.courtlistener.com/opinion/7410409/', '7410409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Walker', 'https://www.courtlistener.com/opinion/8325393/', '8325393') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the petitions for rehearing in this case, it is ordered that the opinion heretofore filed be withdrawn and the attached opinion, wherein we amended the first paragraph of Part II, be substituted therefor.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/8325427/', '8325427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Bryant’s conviction for malicious damage to personal property but otherwise affirm the judgment below.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/8325427/', '8325427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Three years ago we held that the federal wagering tax statutes, 26 U.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 67-69, we held that the privilege against self-incrimination was available to the petitioners as a defense to prosecution for failure to register for, report, or pay the federal wagering taxes.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On January 29, 1968, this Court held that the Fifth Amendment privilege against compulsory self-incrimination was a valid defense to a prosecution for failure to register as a gambler and to pay the related occupational and gambling excise taxes under 26 U.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '22 (1953), a prosecution for failure to register and pay the gambling tax, this Court held that the registration requirement and the obligation to pay the gambling tax did not violate the Fifth Amendment.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On that basis we concluded that "throughout the United States, wagering is `an area permeated with criminal statutes,'' and those engaged in wagering are a group `inherently suspect of criminal activities.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS ORDERED that the petition is granted and respondent is placed on interim suspension until further order of this Court.', 'general', 'In re Roberts', 'https://www.courtlistener.com/opinion/8325957/', '8325957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In applying these principles of statutory interpretation, we hold that it is clear that subsection (a) of the first-degree domestic-battering statute sets out the elements of the offense, while subsection (b)(2) of the statute is a sentencing enhancement based on prior domestic-battering convictions.', 'sentencing', 'Crayton v. State', 'https://www.courtlistener.com/opinion/6241285/', '6241285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Crayton v. State', 'https://www.courtlistener.com/opinion/6241285/', '6241285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the harmless-error rule of Chapman  v.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that materiality of falsehood is an element of the federal mail fraud, wire fraud, and bank fraud statutes.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As in Pope, however, we held that the unconstitutional conclusive presumption was "subject to the harmless-error rule.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite that omission, we held that "[t]he case before us is a case for application of the `harmless error'' standard.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But since we held that harmless-error analysis was appropriate in Pope, that case not only does not support petitioner''s approach, but rejects it.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 468-469, we concluded that the error did not warrant correction in light of the "`overwhelming'' " and "uncontroverted" evidence supporting materiality, id.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '510 (1927), where we reversed the defendant''s conviction because he had been tried before a biased judge, the State argued that "the evidence shows clearly that the defendant was guilty and that he was only fined $100, which was the minimum amount, and therefore that he can not complain of a lack of due process, either in his conviction or in the amount of the judgment.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
