INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the trial court and remand for further proceedings.', 'general', 'Powell v. CRIMINAL JUSTICE AND TRAINING', 'https://www.courtlistener.com/opinion/7472353/', '7472353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We reverse the trial court''s order and remand for further consideration as to the offense of possession of a stolen vehicle.', 'general', 'Powell v. CRIMINAL JUSTICE AND TRAINING', 'https://www.courtlistener.com/opinion/7472353/', '7472353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the state had presented sufficient evidence of conspiracy to commit first-degree murder and remarked that the friends'' suggestion "lets go on a killing spree" and the defendants'' laughing agreement were "[m]ost striking.', 'general', 'State v. Thorpe', 'https://www.courtlistener.com/opinion/7478057/', '7478057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Taken together, we conclude that this evidence was sufficient to permit a rational trier of fact to determine that Defendant and Royster had a mutual, implied understanding that they were going to kill Mr.', 'general', 'State v. Thorpe', 'https://www.courtlistener.com/opinion/7478057/', '7478057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that role, and after careful review of the record, we conclude that the trial court did not err in denying Defendant''s motion to dismiss.', 'dismissal', 'State v. Thorpe', 'https://www.courtlistener.com/opinion/7478057/', '7478057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that what the trial court did know about the appellants more than justified the trial court’s denial of their petition for probation.', 'general', 'State v. Caskey', 'https://www.courtlistener.com/opinion/8218161/', '8218161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*290For the foregoing reasons, we conclude that there was sufficient information in the record to warrant the trial court’s exercise of its sentencing discretion and its decision to dispense with a presentence report.', 'sentencing', 'State v. Caskey', 'https://www.courtlistener.com/opinion/8218161/', '8218161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '9 Therefore, we find that the sentence, which was voidable when imposed, became legal when it was not properly challenged by the State in a timely manner.', 'sentencing', 'State ex rel. Hill v. Parsons', 'https://www.courtlistener.com/opinion/8218445/', '8218445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the commission of each predicate crime constitutes a different manner and means of committing the single offense of engaging in organized criminal activity.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having determined that the gravamen of the offense of engaging in organized criminal activity is the circumstance surrounding the conduct, we hold that the Legislature intended to treat the individual predicate offenses listed in the statute as alternate manner and means of committing the offense of engaging in organized criminal activity.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '50 We held that it required "something more" than that because the use of the plural "activities" implies that the combination at issue must do more than one thing.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that Section 31.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '58 In light of this determination, we held that a jury need not unanimously agree upon every individual instance of theft so long as it unanimously agrees that the aggregated thefts were committed pursuant to a continuing course of conduct.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this was error and the jury must have been told that it needed to be unanimous on at least one of the three alleged acts.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that the State can rely upon party liability to establish the completion of the underlying predicate offense even though one of the two "means" of establishing the offense includes a conspiracy to commit the predicate offense.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State , this Court held that, "when an indictment alleges multiple felonies in a prosecution under [the felony-murder statute], these specifically named felonies are not elements about which a jury must be unanimous.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that, because of that statutory language, the State was permitted to allege various felony offenses in the disjunctive as alternative manner and means *396that did not have to be unanimously found by a jury.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*391Similarly, we conclude that, for an adequate showing of an "intent to establish, maintain, or participate in a combination or in the profits of a combination" in an engaging case the State must show that the predicate offense was committed as part of a collaboration of three or more people working together in a continuing course of criminal activities.', 'general', 'O''Brien v. State', 'https://www.courtlistener.com/opinion/6241380/', '6241380') ON CONFLICT DO NOTHING;
