INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated in this opinion, we reverse the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred by refusing to allow discovery on Castillo''s action for breach of contract, including whether there was any outside influence on the jury.', 'general', 'Ford Motor Co. v. Castillo', 'https://www.courtlistener.com/opinion/895102/', '895102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals'' judgment and remand the case to the trial court for further proceedings consistent with this opinion.', 'general', 'Ford Motor Co. v. Castillo', 'https://www.courtlistener.com/opinion/895102/', '895102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the wording of the statute not only restricts the courts'' ability to place defendants with prior felony convictions on probation, but it also restricts their ability to wholly or partially suspend the sentence of a previously convicted felon.', 'sentencing', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1110608/', '1110608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment below and restore Robinson''s plea of not guilty to the indictment for possession of more than one ounce and less than one kilogram of marijuana and remand for such further appropriate proceedings.', 'plea', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1110608/', '1110608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On writ of certiorari, we affirmed the sentence as imposed by the trial court and held that the trial court was authorized by the applicable statutes to sentence the defendant to one year in the custody of MDOC, followed by ten years of probation, but limited by the five year maximum for MDOC supervision.', 'sentencing', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1110608/', '1110608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the above analysis, we hold that defendant''s sentences of 15 years for the first offense and 25 years for the second offense are disproportionate to the crimes he committed under the specific facts of this case, and thus violate the eighth amendment proscription against cruel and unusual punishment.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 692, 703 (1990) (hereinafter Bartlett I), we held that Joseph Bartlett, Jr.', 'general', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bartlett I, we held that the "broad application of the statute to encompass [Defendant''s] situation results in a penalty grossly out of proportion to the severity of the crime.', 'general', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The majority begins its analysis by stating, "In Bartlett I, we held that the `broad application of the statute to encompass [Defendant''s] situation results in a penalty grossly out of proportion to the severity of the crime.', 'general', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a comparison of the punishments imposed for other crimes in Arizona reveals the disproportion with which defendant was sentenced under these factual circumstances.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this authority, we conclude that the mandatory minimum sentence imposed on defendant for his first offense was disproportionate to sentences received by similarly situated defendants in other jurisdictions.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On review, we concluded that Defendant''s sentence constituted cruel and unusual punishment under the eighth amendment to the United States Constitution.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bartlett I, we concluded that "the mandatory minimum sentence imposed on defendant for his first offense was disproportionate to sentences received by similarly situated defendants in other jurisdictions," and that "the 25-year mandatory minimum imposed for defendant''s second offense [was] also disproportionate to the sentences imposed on similarly situated defendants in other jurisdictions.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Defendant''s forty-year sentence without possibility of early release violates the eighth amendment prohibition of cruel and unusual punishment.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'Parrish v. Allison', 'https://www.courtlistener.com/opinion/1208841/', '1208841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the search warrant relied upon in the prosecution of this case issued upon a constitutionally sufficient showing of probable cause.', 'probable_cause', 'Guerra v. State', 'https://www.courtlistener.com/opinion/1213701/', '1213701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Guerra v. State', 'https://www.courtlistener.com/opinion/1213701/', '1213701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We frame the issue as follows: is an accused entitled to a verdict on the greater charge where the jury has unanimously decided that charge but is deadlocked on the lesser-included offenses? We conclude that the accused is entitled to such a verdict.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*278 We conclude that the trial judge abused his discretion in refusing to resolve the questions posed by the juror which evidenced some possibility of reaching a partial verdict or to repoll the jury as requested by Whiteaker.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a consequence, we conclude that the trial judge abused his discretion in concluding that there was no probability that a unanimous verdict could be reached.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 948 (Alaska 1986), we concluded that manifest necessity was found where a jury could not agree on the greatest charge of attempted first-degree murder and that the defendant was not entitled to a verdict on any lesser-included offense under those facts.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a consequence we find that Whiteaker cannot face trial on an offense more serious than negligent homicide.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse her conviction.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we REVERSE the conviction for second degree murder and REMAND to the trial court.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, on the basis of the undisputed facts, we conclude that the sanction of disbarment is the reference point from which we begin our analysis of aggravating and mitigating factors.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon a consideration of all the above factors, we conclude that a sanction of not more than two years suspension and passage of the MPRE, as recommended by the Board, should be imposed on Schuler.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, given the relevant mitigating factors in this record, we conclude that a significant period of suspension from the practice of law is indicated.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '12, we affirmed the Disciplinary Board''s "determination that disbarment or suspension are generally appropriate sanctions given the nature of West''s misconduct.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the stipulated and recommended sanction should be approved.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing the conviction, this Court held that the evidence was insufficient to show that the town official''s misrepresentation had in any way induced the town to part with its money.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although, the name of the county was omitted from the body of the indictment, we find that sufficient information was contained in the indictment to confer jurisdiction upon the Wilkes County grand jury and to inform Michael Almond that the charges against him arose from activities in Wilkes County.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the above language was more than sufficient to give Michael Almond notice of the charge against him.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, given that the trial court has broad discretion to control discovery so as to prevent undue embarrassment and annoyance, we find that the trial court did not err.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record we find that the evidentiary issues to which defendants objected were only tangential and did not affect defendants'' convictions.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendants received a fair trial free from prejudicial error.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon these many authorities, we hold that when a party appeals a lower court''s ruling to the Supreme Court of Appeals of West Virginia and he/she is required to post an appeal bond, his/her failure to post such bond will result in the dismissal of that party''s appeal and the consequent affirmance, as to that party, of the lower court''s ruling.', 'dismissal', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that an appellant/defendant may not assign as error a circuit court''s affirmative assertion of personal jurisdiction over a coappellant/codefendant when the coappellant/codefendant either has not challenged the assertion of personal jurisdiction over him/her or has otherwise, by his/her acts and/or omissions, waived his/her right to challenge the personal jurisdiction ruling.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the instant a child is born, both unwed biological parents have a right to establish a parent-child relationship with their child.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that any person or persons who plot, plan, scheme, or otherwise conspire to affirmatively, intentionally, and willfully conceal information regarding a newborn child''s birth or physical location, or indicating where and in whose care the child may be found, in response to inquiries by the child''s parent for such information, may be held liable for his/ her or their participation in such civil conspiracy.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because this relationship is so intimately connected with the parent''s person, we hold that where there is an intentional interference with a parent''s custody of his or her child, an injured parent is entitled to a remedy that completely compensates him or her.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a parent[47] may maintain a cause of action against one who tortiously interferes with the parent''s parental or custodial relationship with his/her minor child, which right accrues the instant the child is born.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that where a parent presents a prima facie case of tortious interference with his/her parental or custodial relationship, the party interfering with such relationship may assert the affirmative defense of justification, i.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lastly, we hold that a parent cannot charge his/her child''s other parent with tortious interference with parental or custodial relationship if both parents have equal rights, or substantially equal rights (as in the case of a nonmarital child where the putative biological father seeks to establish a meaningful parent-child relationship with his child and, until such a relationship has been commenced, does not have rights identical to those of the child''s biological mother), to establish or ma...', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Interstate Compact on the Placement of Children (ICPC), set forth in W.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 260 (1982), we held that "[a]n intended beneficiary may sue for tortious interference with a testamentary bequest.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the above and foregoing discussion, we hold that appellant''s right to speedy trial was not violated in this case.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that a reasonable possibility exists that, had the jury not heard the deputy sheriff''s "rape determination" testimony, the verdict might have been more favorable to appellant.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no error occurred.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the record is clear as to the testimony complained about, we hold that appellant has failed to demonstrate the "transgression of a clear and unequivocal rule of law in a clear and obvious way.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no error is demonstrated.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no error occurred when the trial court admitted this testimony.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Zabel, under a plain error analysis, we held that a clinical psychologist''s testimony of not having seen signs of fabrication of the victims'' versions of the sexual abuse incidents, based upon that psychologist''s testing and interviewing the victims, "constituted a psychologist''s evaluation of whether the victims were lying in the `reporting.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Weighing all of the above and foregoing factors, we conclude that the admission of the deputy sheriff''s "rape determination" testimony undermines our judicial confidence in the jury''s verdict.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that this testimony was preliminary in nature and simply established factual foundation for Ms.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the evidence of the accused''s guilt was not overwhelming.', 'general', 'Whiteplume v. State', 'https://www.courtlistener.com/opinion/1236468/', '1236468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the language in [two earlier cases] we hold that a defendant may employ deadly force in self-defense only if it reasonably appears to be necessary to protect against death or great bodily harm.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held 1) that the trial judge correctly denied defendant''s motion to suppress her inculpatory statements, and 2) the instructions on self-defense were not prejudicial to defendant.', 'suppression', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in its ruling but that the error was harmless.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant has failed to show a reasonable possibility that the outcome at trial would have been different had the requested instructions been provided in writing rather than orally, we conclude that the trial court''s error was harmless error.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that this line of cross-examination was proper, as it was relevant to the issue of the credibility of defendant''s testimony that he carried the gun out of fear of robbery and only carried the gun in the club.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no error in admitting the evidence and allowing the prosecutor to refer to it in his closing argument.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant''s reliance upon Clay is misplaced.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that such an instruction conflicts with the long line of cases which hold that the State''s disproof of element two permits a conviction of murder, while the State''s disproof only of element four results in manslaughter.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court''s levying of sanctions in the form of attorneys'' fees and related expenses, and remand this case for the entry of an order in accordance with this opinion.', 'general', 'Davis Ex Rel. Davis v. Wallace', 'https://www.courtlistener.com/opinion/1248690/', '1248690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1005 (1982), we held that a motion for return of property under A.', 'general', 'State Ex Rel. Milstead v. Melvin', 'https://www.courtlistener.com/opinion/1278516/', '1278516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under either approach he cannot prevail.', 'general', 'State Ex Rel. Appleby v. Recht', 'https://www.courtlistener.com/opinion/1309488/', '1309488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not commit clear legal error in this case.', 'general', 'State Ex Rel. Appleby v. Recht', 'https://www.courtlistener.com/opinion/1309488/', '1309488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1339 (1983)) ("We find that there is a substantial state interest in reducing the carnage wrought by drunk drivers.', 'general', 'State Ex Rel. Appleby v. Recht', 'https://www.courtlistener.com/opinion/1309488/', '1309488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a defendant may be convicted for both malicious assault and attempted murder in the first degree without violating the proscription against double jeopardy found within article III, section 5 of the West Virginia Constitution since the provisions for each offense require proof of an additional fact which the other does not.', 'general', 'State v. George', 'https://www.courtlistener.com/opinion/1314560/', '1314560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[a]t that point from interviewing people there at the scene we found that, myself and .', 'general', 'State v. George', 'https://www.courtlistener.com/opinion/1314560/', '1314560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we hold that the Miranda requirements did not apply to this situation inasmuch as nothing was asked of the defendant concerning his alleged crime;', 'general', 'State v. Rassmussen', 'https://www.courtlistener.com/opinion/1345472/', '1345472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"In harmony with the declared public policy of this state with reference to the necessity of corroboration of testimony of the complaining witness in such sex crimes, we hold that the testimony of the prosecuting witness in the prosecution for lewd and lascivious acts must be corroborated either by direct evidence or evidence of surrounding circumstances which clearly corroborate the statements of the complaining witness under the rule as laid down in the case of State v.', 'general', 'State v. Rassmussen', 'https://www.courtlistener.com/opinion/1345472/', '1345472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the statements in context, including the other evidence admitted at trial, we conclude that the statements were innocuous, not intended to inflame the jury, and not of a degree that prejudiced defendant''s right to a fair trial.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this line of questioning was relevant and did not result in any improper bolstering of prosecution witnesses.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not abuse his discretion in admitting this evidence because it was relevant to Asker''s motivation for cooperating with the government.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewed in its entirety, we conclude that it was not error.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these comments were intended to rebut the defense theory that this was a "bought" case, i.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of this evidence, we find that any error in admitting Asker''s testimony regarding the beating was harmless.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and reinstate defendant''s conviction.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, we held that a defendant''s act of necrophilia "without question" constituted the infliction of gratuitous violence on the victim.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that admission *14 of this evidence did not constitute fundamental error.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant was held accountable only for his own actions.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Overall, after considering the evidence that defendant was impaired to some degree on the night of the murder, as well as his history of drug and alcohol abuse, we find that defendant''s impairment constitutes a non-statutory mitigating circumstance in this case.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant''s initial actions evinced little remorse.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Yet, we find that defendant''s impairment on the night of the murder, when coupled with his history of drug and alcohol abuse, constitutes a non-statutory mitigating circumstance in this case.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm defendant''s convictions but remand this case for resentencing on the first degree murder conviction.', 'sentencing', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both judgments of conviction, and we affirm defendant''s sentence for sexual conduct with a minor under the age of 15.', 'sentencing', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Grippon is the sole remaining charge to be utilized by the courts of this state in instructing juries in cases relying, in whole or in part, on circumstantial evidence.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the recommended language in Grippon is the sole and exclusive charge to be given in circumstantial evidence cases in this state,[14] along with a proper reasonable doubt instruction.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 372, 374 (1991), we held that a circumstantial evidence charge which requires the jury to seek some reasonable explanation other than the defendant''s guilt "turns the State''s burden of proof on its head by requiring the jury to find a `reasonable explanation'' of the evidence inconsistent with appellant''s guilt before it can find him not guilty.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '150 (1954), a majority of this Court held in State v.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[9] Although this Court held that the "reasonable hypothesis" language did not shift the burden of proof, we held the instruction actually given by the trial court, adequately conveyed the level of proof required to find Grippon guilty.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in result.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having done so, and in applying the Dost factors to the record before this Court in today''s case, we conclude that the jury was justified in its finding that the images it viewed depicted "sexually explicit conduct.', 'general', 'Hood v. State', 'https://www.courtlistener.com/opinion/1575949/', '1575949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that an exception applies in today''s case because "[t]here is no privilege under this rule .', 'general', 'Hood v. State', 'https://www.courtlistener.com/opinion/1575949/', '1575949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, since the offers were expressly limited to mitigation of punishment, and since the question of guilt is free from *209 doubt, and since the error can be expunged by a commutation of the sentence, we hold that it does not require reversal of the judgment.', 'sentencing', 'State v. Owen', 'https://www.courtlistener.com/opinion/1422247/', '1422247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '79, 80, this court said: `* * * This court held, in State v.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/1422247/', '1422247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that no error was committed by requiring the appellants to state the nature of the felonies for which previous convictions had been admitted.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/1422247/', '1422247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful examination of the entire record, the evidence, proceedings and instructions of the court, we find that the defendants had a fair and impartial trial so far as concerns the question of their guilt.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/1422247/', '1422247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1452521/', '1452521') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the New Jersey Constitution, citizens have a reasonable expectation of privacy in bank records.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the New Jersey Constitution recognizes an account holder''s interest in the privacy of his or her bank records.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', when the government seeks bank records on file with a bank  we hold that the issuance of a grand jury subpoena duces tecum based on a relevancy standard satisfies the constitutional prohibition against improper government intrusion.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, in Novembrino, we held that our Constitution, unlike the Federal Constitution, does not afford law enforcement a "good faith" exception to the exclusionary rule.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hunt, supra, we held that citizens had a protectable interest in their long distance phone records even though those records were in possession of the telephone company.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that existing grand jury subpoena procedures sufficiently protect that expectation of privacy.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that New Jersey citizens have a reasonable expectation of privacy in their bank records, circumstances will arise that justify State intrusion upon that interest.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that notice is not constitutionally mandated, we believe that further study is warranted to assess whether a notice requirement reflects good policy.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm in part, reverse in part, and affirm defendant''s conviction.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1977), this court held that the trial court must permit either side to bring out the criminal convictions of its own witnesses on direct examination in order to "draw the sting from the inevitable impeachment on cross-examination.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has highlighted this testimony out of its context in the record.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this circumstance, we conclude that substantial rights were not affected by the absence of a cautionary instruction, and thus the error was harmless.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under all the circumstances, we conclude that appellant''s substantial rights were not affected by the failure of the trial court to strike, without prompting by defense counsel, the prosecutor''s argument to the jury and to intervene, sua sponte, when appellant was asked whether he had told the police of his alibi.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sampson, we found that the government failed to show "a threshold inconsistency" between the defendant''s testimony in court and the omissions in his statement to the police prior to trial denying involvement in the crime.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] Although we do not find the trial proceedings to be without error, we affirm appellant''s conviction because we are persuaded that any errors that were committed could not have substantially swayed the judgment of the jury.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that as long as there is sufficient evidence for the State to make a prima facie showing that each defendant committed the murder by his or her own conduct, the State is permitted to charge more than one defendant with capital murder, even where it is clear that only one person actually killed the victim by his own conduct.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial judge''s findings of facts were not clearly erroneous.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when the Legislature adopted the Attorney General''s suggested change, it intended to *23 make any prior murder committed by a defendant at any time and at any place an aggravating factor.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that defendant is not entitled to a reversal of his death sentence or a new penalty-phase trial based on the excusal of Clevenger for cause.', 'sentencing', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regardless, we find that the trial court did not abuse its discretion when failing to excuse Beebe for cause.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court did not err in failing to excuse this potential juror for cause.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not err in failing to exclude any of the nine jurors challenged in this appeal.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court properly denied defendant''s request for a stay.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm all of the convictions as well as the sentence of death.', 'sentencing', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant''s convictions and capital and noncapital sentences.', 'sentencing', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is and affirm.', 'general', 'Lamb v. State', 'https://www.courtlistener.com/opinion/1580350/', '1580350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We hold that, under Padilla, the trial court’s warning to a defendant that “the plea may subject him or her to deportation,” as required by Florida Rule of Criminal Procedure 3.', 'plea', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/4995081/', '4995081') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because all three Witt factors weigh against retroactive application, we hold that the rule announced in Padilla does not apply retroactively.', 'general', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/4995081/', '4995081') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that rule 3.', 'general', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/4995081/', '4995081') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987) ("We therefore hold that counsel’s failure to advise his client of the collateral consequence of deportation does not constitute ineffective assistance of counsel.', 'ineffective_assistance', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/4995081/', '4995081') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in granting Calcagino’s motion to suppress.', 'suppression', 'State v. Tamburri', 'https://www.courtlistener.com/opinion/7608819/', '7608819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Tamburri', 'https://www.courtlistener.com/opinion/7608819/', '7608819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore we reverse.', 'general', 'State v. Tamburri', 'https://www.courtlistener.com/opinion/7608819/', '7608819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for proceedings consistent with this opinion.', 'general', 'State v. Tamburri', 'https://www.courtlistener.com/opinion/7608819/', '7608819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the plea attorney’s failure to consider whether Petitioner was properly charged with eighteen separate counts of receiving stolen goods constituted ineffective assistance of counsel.', 'plea', 'Stevens v. State', 'https://www.courtlistener.com/opinion/8326796/', '8326796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After granting certiorari, we reverse.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/8326796/', '8326796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no evidence to support the PCR court’s finding that Petitioner knowingly and voluntarily pled guilty to all charges, we reverse the PCR court’s decision and remand Petitioner’s case for a new plea hearing or trial.', 'plea', 'Stevens v. State', 'https://www.courtlistener.com/opinion/8326796/', '8326796') ON CONFLICT DO NOTHING;
