INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Virden v. State', 'https://www.courtlistener.com/opinion/7878061/', '7878061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“Although states that have signed the Compact can be expected to follow the purposes and requirements of the act, where they fail to do so, in a case such as this, we hold that a person’s license remains valid until the driver is properly notified of the revocation and provided with an opportunity for hearing.', 'general', 'Welch v. Alabama Department of Public Safety', 'https://www.courtlistener.com/opinion/7631396/', '7631396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the Court of Civil Appeals erred in affirming the decision of the circuit court.', 'general', 'Welch v. Alabama Department of Public Safety', 'https://www.courtlistener.com/opinion/7631396/', '7631396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that in this case the Code’s safety objective is met through reliance on the Compact, as incorporated by the Code.', 'general', 'Welch v. Alabama Department of Public Safety', 'https://www.courtlistener.com/opinion/7631396/', '7631396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the verdicts, even if they were inconsistent, should stand as rendered.', 'general', 'Hall v. State', 'https://www.courtlistener.com/opinion/7634785/', '7634785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that section 812.', 'general', 'Hall v. State', 'https://www.courtlistener.com/opinion/1630400/', '1630400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that section 812.', 'general', 'Hall v. State', 'https://www.courtlistener.com/opinion/1630400/', '1630400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5th DCA 1982), we affirm on [this issue].', 'general', 'Hall v. State', 'https://www.courtlistener.com/opinion/1630400/', '1630400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the objections to the oral charges were outside the jury’s hearing.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/7662629/', '7662629') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in Boykin v.', 'general', 'Moosani v. State', 'https://www.courtlistener.com/opinion/1716683/', '1716683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Court of Appeals'' reasoning is correct and adopt it as our own.', 'general', 'Moosani v. State', 'https://www.courtlistener.com/opinion/1716683/', '1716683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “[t]his instruction survives the Pierce rule, since it informed the jury that it should not look to Maye to prove self-defense, but to the State to prove the lack thereof.', 'general', 'Gilmore v. State', 'https://www.courtlistener.com/opinion/5105172/', '5105172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the jury was sufficiently instructed that the State bore the burden of proving beyond a reasonable doubt that Gilmore did not act in self-defense.', 'general', 'Gilmore v. State', 'https://www.courtlistener.com/opinion/5105172/', '5105172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial on both counts, because Gilmore was prejudiced by the introduction of inadmissible evidence of a prior conviction.', 'general', 'Gilmore v. State', 'https://www.courtlistener.com/opinion/5105172/', '5105172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgments of conviction of the Circuit Court of Claiborne County and remand for a new trial on both counts.', 'general', 'Gilmore v. State', 'https://www.courtlistener.com/opinion/5105172/', '5105172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court on this issue.', 'general', 'Gilmore v. State', 'https://www.courtlistener.com/opinion/5105172/', '5105172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/8324738/', '8324738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the fee agreement was void because it violated the rule that "[a] lawyer shall not enter into an arrangement for, charge or collect .', 'general', 'Gables Ins. Recovery, Inc. v. Citizens Prop. Ins. Corp.', 'https://www.courtlistener.com/opinion/7697894/', '7697894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the evidence, in the light most favorable to Gerson, showed he "unlawfully solicited the legal business.', 'general', 'Gables Ins. Recovery, Inc. v. Citizens Prop. Ins. Corp.', 'https://www.courtlistener.com/opinion/7697894/', '7697894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we cannot say on this record whether the assignment was invalid, we reverse summary judgment in case number 16-87 and remand for further proceedings.', 'general', 'Gables Ins. Recovery, Inc. v. Citizens Prop. Ins. Corp.', 'https://www.courtlistener.com/opinion/7697894/', '7697894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the summary judgment in case number 15-2320.', 'general', 'Gables Ins. Recovery, Inc. v. Citizens Prop. Ins. Corp.', 'https://www.courtlistener.com/opinion/7697894/', '7697894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion by allowing the prosecution to present the results of the second test which had been made on the blood sample.', 'general', 'Candelaria v. State', 'https://www.courtlistener.com/opinion/1265589/', '1265589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Candelaria v. State', 'https://www.courtlistener.com/opinion/1265589/', '1265589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the Department of Corrections cannot grant credit for time spent under Control Release supervision unless the Parole Commission instructs it to do so.', 'general', 'Gay v. Singletary', 'https://www.courtlistener.com/opinion/1799732/', '1799732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our reading of the pertinent statutes, we find that the Florida Parole Commission has the authority to either grant or deny a releasee credit for time spent on *1221 Control Release when that release is revoked due to a violation of the terms and conditions of release.', 'general', 'Gay v. Singletary', 'https://www.courtlistener.com/opinion/1799732/', '1799732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We find that this action merely indicates an intent to retain the Parole Commission and does not constitute evidence of any later intent as to the language contained in any of the affected statutory provisions.', 'general', 'Gay v. Singletary', 'https://www.courtlistener.com/opinion/1799732/', '1799732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the FCFA does not preempt a municipality from using its home rule powers to enact such an ordinance.', 'general', 'City of Hollywood v. Mulligan', 'https://www.courtlistener.com/opinion/1891743/', '1891743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As stated earlier, we hold that the FCFA does not preempt municipalities from adopting ordinances authorizing the seizure and impoundment of vehicles used in the commission of enumerated misdemeanor offenses.', 'general', 'City of Hollywood v. Mulligan', 'https://www.courtlistener.com/opinion/1891743/', '1891743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in answering the certified question as rephrased, we hold that the FCFA does not preempt a municipality from adopting an ordinance that authorizes the seizure and impoundment of vehicles used in the commission of certain misdemeanors.', 'general', 'City of Hollywood v. Mulligan', 'https://www.courtlistener.com/opinion/1891743/', '1891743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Keshbro, we held that a temporary closure of a hotel and apartment by city nuisance abatement boards for drug- and prostitution-related activities was a compensable regulatory taking under the "economically beneficial use standard" outlined in Lucas v.', 'general', 'City of Hollywood v. Mulligan', 'https://www.courtlistener.com/opinion/1891743/', '1891743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the FCFA does not preempt a municipality such as the City of Hollywood from adopting an ordinance that authorizes the seizure and impoundment of vehicles used in the commission of certain misdemeanor offenses.', 'general', 'City of Hollywood v. Mulligan', 'https://www.courtlistener.com/opinion/1891743/', '1891743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that the differing procedures employed by the FCFA and the ordinance do not create a conflict necessitating the invalidation of the ordinance, we agree with the Fourth District that the ordinance''s procedures raise serious constitutional concerns.', 'general', 'City of Hollywood v. Mulligan', 'https://www.courtlistener.com/opinion/1891743/', '1891743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1212 (1992)(in which a plurality of this Court held that the Commonwealth may appeal a pre-trial order granting a motion in limine if the order terminates or substantially handicaps the prosecution);', 'general', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the suppression motion was a substantial first step leading directly into the guilt-determining process because the suppression motion in Jones was returnable at the time of trial.', 'suppression', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[7]  In Jarman and Modaffare, this Court held that the evidence was insufficient to sustain convictions for driving under the influence of alcohol where blood samples taken approximately one hour after the defendants operated their vehicles showed that their blood alcohol levels were slightly above the 0.', 'general', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Commonwealth did not introduce expert testimony to relate back the defendants'' blood alcohol level at the time they drove their cars, this Court held that the convictions were based on speculation and there was no proof beyond a reasonable doubt.', 'general', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Order of the Superior Court.', 'general', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the Order of the Superior Court and we remand this case to the Court of Common Pleas of McKean County for trial.', 'plea', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), this Court held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statute is constitutional and not void for vagueness nor overbroad.', 'general', 'Richmond v. City of Corinth', 'https://www.courtlistener.com/opinion/1912176/', '1912176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Richmond v. City of Corinth', 'https://www.courtlistener.com/opinion/1912176/', '1912176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to the trial court for further proceedings.', 'general', 'CHAS. BLOOM & CO. v. Echo Jewelers', 'https://www.courtlistener.com/opinion/1933864/', '1933864') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when, as here, the evidence of a prior crime is a necessary element of the *1263 State''s case, introduction of such evidence will not require reversal.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1936088/', '1936088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Having found that the evidence was sufficient to prove the element of the crime that Taylor was "under a sentence of life," we hold that it was legally sufficient to support the finding of an aggravating circumstance.', 'sentencing', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1936088/', '1936088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 772 (1984), this Court held that crimes and convictions occurring subsequent to the murder but before the murder trial could be admitted into evidence as an aggravating circumstance.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1936088/', '1936088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Adams, this Court held that the prosecution''s delay caused by subsequent re-indictments constituted "negligence" and therefore this time should not be charged against the State.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1936088/', '1936088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Smith, this Court held that a defendant was prejudiced by the State''s waiting to prosecute until another conviction was obtained.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1936088/', '1936088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), this Court held that prosecutors can probe the prejudices of the prospective jurors to the end that all will understand the jurors'' thoughts on the matters directly related to the issues to be tried.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1936088/', '1936088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), this Court held that an admission by a defendant to his girlfriend of an alleged burglary was a "confession," and constituted direct evidence of the crime such that giving a circumstantial evidence instruction was not required.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1936088/', '1936088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mackbee, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In determining that the prosecutor violated Butler''s Fifth Amendment rights, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there may be some constitutional errors which in the setting of a particular case are so unimportant and insignificant that they may, consistent with the Federal Constitution, be deemed harmless, not requiring the automatic reversal of the conviction.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1936088/', '1936088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we recognize that the statute grants a right to such treatment as is psychiatrically indicated, we hold that on this record the sentencing court erred in attempting to determine whether that treatment would in fact be provided.', 'sentencing', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that on the record before us the sentencing court was an inappropriate forum to determine that the sentencing provisions of MCL 768.', 'sentencing', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that this statute requires a sentencing court to obtain a report from the Center for Forensic Psychiatry evaluating a defendant''s present mental health prior to sentencing a defendant found guilty but mentally ill.', 'sentencing', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court''s factual finding that the conditions at the Department of Corrections facilities posed a threat of immediate and irreparable injury to the defendant was made on an inadequate factual record and consequently does not impair our holding.', 'general', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that it obviously contemplates such an inquiry and implicitly requires one.', 'general', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant''s interest in the legislatively created sentencing alternative of probation will be protected adequately if the sentencing court is required to obtain a report on defendant''s present mental health prior to sentencing and provides a procedure for review to allow shortening or discontinuing the period of probation if the reasons for the five-year period no longer obtain.', 'sentencing', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Court of Appeals.', 'general', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. JTS', 'https://www.courtlistener.com/opinion/1944281/', '1944281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Schneider, supra, this court held that the trial court did not abuse its discretion when it did not allow the defendant to withdraw his plea of no contest after he learned he would be required to register as a sex offender.', 'plea', 'State v. Williams', 'https://www.courtlistener.com/opinion/1947027/', '1947027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the evidence in the record, we conclude that the trial court did not abuse its discretion in denying Williams'' motions to withdraw his plea.', 'plea', 'State v. Williams', 'https://www.courtlistener.com/opinion/1947027/', '1947027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court properly accepted Williams'' plea.', 'plea', 'State v. Williams', 'https://www.courtlistener.com/opinion/1947027/', '1947027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this sentence is not excessive and that the court did not abuse its discretion.', 'sentencing', 'State v. Williams', 'https://www.courtlistener.com/opinion/1947027/', '1947027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth herein, we affirm the judgment of the district court.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1947027/', '1947027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that a defendant may summon his own attorney to give evidence vital to his defense, even though it may cause the lawyer embarrassment or raise the appearance of an ethical violation.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1946348/', '1946348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state laid a predicate for impeaching Page with his prior statements and, even were this not so, the statements were not so inflammatory as to infect the sentencing phase of his trial.', 'sentencing', 'Gray v. State', 'https://www.courtlistener.com/opinion/1946348/', '1946348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 345 (1964), we concluded that the state was not genuinely taken by surprise by witness Johnson''s repudiation of his prior statement nor was Johnson unexpectedly hostile.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1946348/', '1946348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have carefully reviewed all of the assignments of error offered by Gray affecting the guilt phase of his trial and we find that none of them are meritorious.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1946348/', '1946348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that this information impermissibly lessened the burden upon the jury as to whether their verdict was the only final determination on the question of whether the death penalty would be imposed upon West.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1946348/', '1946348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Moffett, we affirmed that a party is prohibited from impeaching his own witness with a prior statement when he knows reasonably well in advance that the witness has repudiated the statement.', 'general', 'Gray v. State', 'https://www.courtlistener.com/opinion/1946348/', '1946348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 447, we held that first degree murder while armed is a "crime punishable by death" within the meaning of the accessory after the fact statute, even though the maximum sentence for first degree murder is now life in prison pursuant to D.', 'sentencing', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Williams, we held that the driver of a getaway car was not an accessory after the fact to armed robbery because the offense was not yet complete;', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We may set aside Jones'' AAF conviction for evidentiary insufficiency only if, after viewing the record in the light most favorable to the prosecution, we conclude that there was no evidence upon which an impartial jury could fairly find, beyond a reasonable doubt, that Jones committed the offense.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these standards for review of claimed evidentiary insufficiency, we affirm the convictions.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment on the obstruction of justice count and the conviction for accessory after the fact to first degree murder while armed, but remand for resentencing on the latter conviction.', 'sentencing', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we held that the "`substantive penological policies announced'' by the Florida Legislature in enacting this statute are legitimately furthered by the structure of the Act.', 'general', 'Grant v. State', 'https://www.courtlistener.com/opinion/1955315/', '1955315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this subsection allows a trial court to impose an HFO sentence on a PRR when the defendant qualifies under both statutes.', 'sentencing', 'Grant v. State', 'https://www.courtlistener.com/opinion/1955315/', '1955315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that although the lesser offense of theft was included in the greater offense of robbery, as charged, the evidence left no doubt but that the defendant was guilty of robbery or of no crime whatsoever.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2103043/', '2103043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that under those circumstances, "the officers'' actions constituted a show of authority," and that a reasonable person "would likely conclude that, if he or she drove away, then the two officers would soon be in hot pursuit.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, under the totality of the circumstances, these actions constituted a show of authority to which a reasonable person would feel compelled to submit.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the officers'' actions constituted a show of authority and that a reasonable person in the driver''s position would not have felt free to leave.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in Brownlee, this court held that the defendant was unlawfully seized after the justification for the traffic stop had ended, where the two officers continued to flank both sides of the vehicle after returning the motorist''s documents and stating that no citations would be issued, paused for a "couple of minutes," and then requested that the occupants agree to a consent search.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We conclude that a person has been `seized'' within the meaning of the Fourth Amendment only if, in view of all of the circumstances surrounding the incident, a reasonable person would have believed that he was not free to leave.', 'search_seizure', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While Cosby argues before this court that there was no break between the conclusion of the traffic stop and the officer''s request for consent to search, we conclude that the record does not support such an argument.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, applying the principles of Brownlee and Mendenhall, we conclude that Cosby was not seized and that his consent to search his car was therefore voluntary.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As noted, however, this statement contradicts the position taken by the majority earlier in its opinion, wherein it finds that there was a break between the conclusion of the traffic stop and Kaus'' request to Cosby to allow a search, and rejects precisely the same argument it now embraces, writing: "While Cosby argues before this court that there was no break between the conclusion of the traffic stop and the officer''s request for consent to search, we conclude that the record does not suppor...', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the officers'' stop of the vehicle was supported by probable cause.', 'probable_cause', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '100681, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Atkinson, however, we held that "trial courts should not consider the mere-fact method of impeachment.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Atkinson, this court held that, as a matter of law, it is always improper for a circuit court to employ the mere-fact method to impeach a testifying defendant.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the trial court has discretion in conducting this balancing test and determining whether a witness'' prior *170 conviction is admissible.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the defendant''s conviction and remand for a new trial.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*171 We reversed the appellate court and reinstated the defendant''s conviction.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons we have discussed, we reverse the judgments of the appellate and circuit courts and remand the cause to the circuit court for a new trial.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant was brought to trial within the statutory periods proscribed by the speedy-trial statute.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing reasons, we hold that the challenged prosecutorial comments during closing and rebuttal arguments did not operate to deny defendant a fair trial or due process of law.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the ex parte communications did not prejudice defendant, and as a result, such improper communications were harmless beyond a reasonable doubt.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court did not err in admitting testimony concerning these statements, which were made during the course of and in furtherance of the conspiracy.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that there was no evidence that the sentencing judge improperly considered the memorandum for sentencing purposes, after noting that the sentencing judge did not refer to the memorandum or indicate that it influenced his sentencing decision.', 'sentencing', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Permanian''s statements made in the context of receiving payment from Rinaldi were admissible under the coconspirator exception to the hearsay rule.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the case at bar, we conclude that the trial judge abused her discretion in admitting evidence that defendant had pistol-whipped Behenna.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the context of the proceeding, we conclude that the prosecutor''s comments were not improper or did not deprive defendant of a fair trial.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court abused its discretion in attributing this delay to the State.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that only 97 days from defendant''s arrest to commencement of his trial for murder are not attributable to defendant.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hausman, the most recent case to entertain any expansion of the public policy exception, we held that "[w]here the law imposes an affirmative obligation upon an employee .', 'general', 'Bammert v. Don''s SuperValu, Inc.', 'https://www.courtlistener.com/opinion/2013834/', '2013834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The case was properly dismissed for failure to state a claim, and we affirm.', 'dismissal', 'Bammert v. Don''s SuperValu, Inc.', 'https://www.courtlistener.com/opinion/2013834/', '2013834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[F]or recklessness to exist," this court held in State v.', 'general', 'State v. Sutton', 'https://www.courtlistener.com/opinion/2023249/', '2023249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the defendant''s disregard for this danger, combined with driving at an excessive speed in a school zone, demonstrated the level of recklessness necessary to support a conviction for vehicular homicide.', 'general', 'State v. Sutton', 'https://www.courtlistener.com/opinion/2023249/', '2023249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the conviction and sentence entered against Joseph Sutton for aiding and abetting vehicular homicide.', 'sentencing', 'State v. Sutton', 'https://www.courtlistener.com/opinion/2023249/', '2023249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '897 (1984), and the development of the good faith exception to the exclusionary rule in this court, we held that suppression was not necessary when police officers reasonably relied upon a warrant issued by an independent magistrate, even though the "no-knock" portion of the warrant was constitutionally infirm.', 'suppression', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As early as 1924, this court held in State v.', 'general', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence seized must be suppressed.', 'suppression', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the order.', 'general', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we affirm the order of the circuit court granting the defendant''s motion to suppress the evidence.', 'suppression', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning attention then, under Blockburger, to § 16-113(h), we hold that it, in turn, possesses a unique element which is not a required element of § 21-902.', 'general', 'In re Michael W.', 'https://www.courtlistener.com/opinion/7974336/', '7974336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we hold that the *152two offenses may not be deemed the same for purposes of double jeopardy and that the trial court erred in dismissing the entire juvenile petition on that basis.', 'dismissal', 'In re Michael W.', 'https://www.courtlistener.com/opinion/7974336/', '7974336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the trial court''s misapprehension of the evidence''s relevance, we hold that post-crime consciousness of guilt evidence is relevant to state of mind disputes arising in criminal prosecutions for reckless conduct.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the consciousness of guilt evidence is relevant to defendant''s mental state at the time of the shooting for which he is charged with reckless manslaughter.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that at trial on our remand, a strong limiting instruction should be administered by the trial court informing the jury that it should not draw any inference of consciousness of guilt by defendant from his post-crime conduct unless it believes that defendant acted to cover up a crime.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In these circumstances we conclude that this relevant information should not be kept from the jury.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence''s probative value is not outweighed by undue prejudice.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[9]  Indeed, as our earlier analysis detailed, we find that Cofield''s "similar in kind and reasonably close in time" prong does not have any applicability in this setting.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 951 (2006), and now, we reverse.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion then, we reverse the trial court''s relevance assessment that held, for purposes of Rule 404(b) admission, that defendant''s cover-up conduct was legally irrelevant in the re-prosecution of defendant for reckless manslaughter.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the trial court, affirmed by the Appellate Division, that found that the evidence of defendant''s post-shooting conduct was legally irrelevant and that the evidence''s prejudicial effect required its preclusion under Evidence Rule 404(b).', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/8327208/', '8327208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/8327208/', '8327208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse and remand this case to the trial court.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/8327208/', '8327208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Manning', 'https://www.courtlistener.com/opinion/8327236/', '8327236') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the circuit court’s decision to deny Manning’s motion for a mistrial.', 'mistrial', 'State v. Manning', 'https://www.courtlistener.com/opinion/8327236/', '8327236') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), we held that “neither the United States Constitution nor the Tennessee Constitution requires the trial judge to read or submit non-statutory mitigating circumstances to the jury.', 'general', 'State v. Odom', 'https://www.courtlistener.com/opinion/5263918/', '5263918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons appearing below, we find that the evidence was insufficient to support the finding of this aggravating circumstance.', 'general', 'State v. Odom', 'https://www.courtlistener.com/opinion/5263918/', '5263918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that there was no statutory requirement that nonstatu-tory mitigating factors be expressly instructed:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Zaccardo v. State', 'https://www.courtlistener.com/opinion/7779827/', '7779827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no defendant may be adjudged mentally retarded for purposes of the Eighth Amendment, unless such defendant produces, at a minimum, an *25expert who expresses an opinion, to a reasonable degree of certainty, that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit judge did not err by instructing the jury to reform its verdict.', 'general', 'Dickerson v. State', 'https://www.courtlistener.com/opinion/5105431/', '5105431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Comparing other factually similar cases in which a death sentence was imposed, we conclude that the death penalty is not excessive or disproportionate in the *35instant case.', 'sentencing', 'Dickerson v. State', 'https://www.courtlistener.com/opinion/5105431/', '5105431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Dickerson v. State', 'https://www.courtlistener.com/opinion/5105431/', '5105431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After éxamining other statements in the Atkins majority, we concluded that it intended to grant “Eighth Amendment protection from execution to all [intellectually disabled] persons.', 'general', 'Dickerson v. State', 'https://www.courtlistener.com/opinion/5105431/', '5105431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶3     For the reasons discussed, we conclude that the issue
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶38 Applying these principles here, we conclude that Groce’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶39 Specifically, we conclude that Groce’s challenge to the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'arguments, and we affirm the district court’s detention orders.', 'general', 'State v. Groce', 'https://www.courtlistener.com/opinion/10276697/', '10276697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the plain language of Section 1102, we hold that, to prove “pecuniary benefit” as used in the conflict of interest statute, the prosecution must show some private financial gain.', 'general', 'Commonwealth v. Veon', 'https://www.courtlistener.com/opinion/5149790/', '5149790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 67 (2012), echoing Figueroa, we held that the compensation of Commonwealth personnel cannot be recovered, as restitution under Section 1106.', 'general', 'Commonwealth v. Veon', 'https://www.courtlistener.com/opinion/5149790/', '5149790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we find that Section 1102 is amenable to an interpretation that eliminates the necessity of constitutional inquiry.', 'general', 'Commonwealth v. Veon', 'https://www.courtlistener.com/opinion/5149790/', '5149790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we found that, in this regard, the intention reflected in Section 1106 could not be gleaned from the plain language alone, requiring the court to consider the legislative history behind Section 1106, the object to be obtained by the statute, and the consequences of the competing interpretations.', 'general', 'Commonwealth v. Veon', 'https://www.courtlistener.com/opinion/5149790/', '5149790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we affirm Appellant’s judgment of sentence and grant counsel’s petition to withdraw.', 'sentencing', 'Commonwealth v. Schmidt', 'https://www.courtlistener.com/opinion/5156441/', '5156441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellant’s judgment of sentence and grant counsel’s petition to withdraw.', 'sentencing', 'Commonwealth v. Schmidt', 'https://www.courtlistener.com/opinion/5156441/', '5156441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this evidence, while circumstantial, was substantial.', 'general', 'Benton v. State', 'https://www.courtlistener.com/opinion/5283990/', '5283990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Benton v. State', 'https://www.courtlistener.com/opinion/5283990/', '5283990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, substantial evidence supports Benton’s conviction for theft by receiving, and we affirm.', 'general', 'Benton v. State', 'https://www.courtlistener.com/opinion/5283990/', '5283990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Benton v. State', 'https://www.courtlistener.com/opinion/5283990/', '5283990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that nothing in the Act or our prior jurisprudence prevents appellate courts from addressing certain unpre-served sentencing errors on direct appeal.', 'sentencing', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that for those defendants who did not have the benefit of our recently promulgated amendment to rule 3.', 'general', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on all these considerations, we conclude that the interests of justice will not be advanced if appellate courts decline to correct certain categories of sentencing errors for criminal defendants whose appellate briefs were filed during the window period after the enactment of the Act but before the adoption of our recent procedural changes in Amendments II.', 'sentencing', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that for those cases in which the first appellate brief was filed prior to our recent opinion in Amendments II expanding the time in which a rule 3.', 'general', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that serious errors resulting from deviations in the written sentence from the oral pronouncement should continue to be corrected on appeal during this window period where the sentencing error has a qualitative effect on the integrity of the sentencing process or when it has a quantitative effect on the length of the sentence.', 'sentencing', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that in these cases the appellate courts should correct errors such as those that occurred in Peavy v.', 'general', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that for defendants who did not agree to the imposition of a departure sentence in a plea agreement, the policy reasons for correcting a departure sentence in which the trial court failed to file statutorily required written reasons for departure are still applicable following the Act.', 'sentencing', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this statutory omission is an important one that affects the integrity of the sentencing process concerning the critical question of the length of the sentence.', 'sentencing', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an unpreserved error in the assessment of costs cannot be considered a serious, patent sentencing error that should be corrected on appeal as fundamental in the absence of proper preservation in the trial court.', 'sentencing', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that because the statute “affect[ed] a quantifiable determinant of the length of sentence that may be imposed on a defendant,” it involved “fundamental ‘liberty’ due process interests.', 'sentencing', 'Maddox v. State', 'https://www.courtlistener.com/opinion/7792607/', '7792607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2014), we held that a condominium owner’s "undivided ownership interest in the common area of the condominium complex made the common area [his] ''own premises'' under the [Unlawful Carrying Weapons] statute.', 'general', 'State v. Rendon', 'https://www.courtlistener.com/opinion/5446213/', '5446213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'State v. Rendon', 'https://www.courtlistener.com/opinion/5446213/', '5446213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we explain more fully below, we hold that the officers’ conduct in bringing a trained drug-detection dog up to the threshold or area immediately outside of appellee’s front door for the purpose of conducting a canine-narcotics sniff was an “unlicensed physical intrusion” onto the curtilage of his home that constituted a search in violation of the Fourth Amendment.', 'search_seizure', 'State v. Rendon', 'https://www.courtlistener.com/opinion/5446213/', '5446213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Jardines,1 we conclude that the officers’ use of a dog sniff at the front door of the apartment-home of Michael Eric Rendon, appellee, resulted in a physical intrusion into the curtilage that exceeded the scope of any express or implied license, thereby constituting a warrantless search in violation of the Fourth Amendment.', 'search_seizure', 'State v. Rendon', 'https://www.courtlistener.com/opinion/5446213/', '5446213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, under these facts that show that the dog sniff occurred at the threshold'' of appellee’s apartment-home, we conclude that application of the ■ property-rights baseline renders the present case a straightforward one-.', 'general', 'State v. Rendon', 'https://www.courtlistener.com/opinion/5446213/', '5446213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under a strict application of the “traditional property-based understanding of the Fourth Amendment,” we conclude that the dog sniff at the threshold of ap-pellee’s apartment’s door was an unlawful search within the meaning of the Fourth Amendment.', 'search_seizure', 'State v. Rendon', 'https://www.courtlistener.com/opinion/5446213/', '5446213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Supreme Court’s reasoning in Jardines to the facts of this case, we conclude that, by bringing a drug-detection dog directly up to appellee’s front door for the purpose of conducting a canine-narcotics sniff,: the officers physically intruded upon the curtilage of appellee’s home in a manner that exceeded the scope of any express or implied license, and any evidence obtained as a result of .', 'general', 'State v. Rendon', 'https://www.courtlistener.com/opinion/5446213/', '5446213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that, given the broadness of the particular statutory language in the deadly weapon statute, and given our consideration of the extra-textual factors, here the Legislature’s apparent intent as to this statute was to permit a deadly weapon finding for those weapons that are used or exhibited against humans only.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence is insufficient to support a deadly weapon finding under circumstances in which the sole recipient or being against whom a deadly weapon was used or exhibited was a nonhuman.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court has previously discussed the broad nature of the language in this statute when we held that its laiiguage was ambiguous in another respect.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we held that the Legislature intended for the statutory language to broadly apply to animals, as the State proposes, then this would permit a deadly weapon finding as to all animals, and not just to those that some of us may prefer, such as cats, dogs, and horses.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, in which this Court held that a deadly weapon finding was properly made when a jury found a defendant guilty of criminally negligent homicide “as included in the indictment” and the indictment had alleged a deadly weapon.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in Plummer v.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Plummer, this Court held that a deadly weapon finding for a felony''offense requires some facilitating connection between the weapon and the felony.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, but there this Court held that “to sustain a deadly weapon finding, there must be evidence that others were actually endangered, not merely a hypothetical potential for danger if others had been present.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, but there this Court held that, “in order to sustain a deadly weapon finding, the evidence must demonstrate that: (1) the object meets the definition of a deadly weapon;', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the language of the deadly weapon statute is ambiguous with respect to whether a deadly weapon finding may be made for weapons used or exhibited against nonhumans, and thus, we must consider extra-textual factors to discern the Legislature’s intent as to this matter.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, where we held that driving while intoxicated and crossing the center stripe was not sufficient to make the defendant’s car a deadly weapon when there was no traffic on the road.', 'general', 'Prichard v. State', 'https://www.courtlistener.com/opinion/5449396/', '5449396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with Peat, Marwick, we hold that, in the circumstances presented here, a negligence/malpractice cause of action accrues when the client incurs damages at the conclusion of the related or underlying judicial proceedings or, if there are no related or underlying judicial proceedings, when the client’s right to sue in the related or underlying proceeding expires.', 'general', 'Perez-Abreu, Zamora & De La Fe, P.A. v. Taracido', 'https://www.courtlistener.com/opinion/7801923/', '7801923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Edwards, we held that the cause of action had accrued in 1963, when the clients were advised that the contract was probably usurious.', 'general', 'Perez-Abreu, Zamora & De La Fe, P.A. v. Taracido', 'https://www.courtlistener.com/opinion/7801923/', '7801923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The clients clearly had knowledge of their injury in 1963, and we held that the statute of limitations barred that action.', 'general', 'Perez-Abreu, Zamora & De La Fe, P.A. v. Taracido', 'https://www.courtlistener.com/opinion/7801923/', '7801923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that even though the related or underlying judicial proceeding was not complete until 1967, the cause of action accrued in 1963, and therefore the statute of limitations began to run at that time.', 'general', 'Perez-Abreu, Zamora & De La Fe, P.A. v. Taracido', 'https://www.courtlistener.com/opinion/7801923/', '7801923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Blumberg, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this reasoning to the present case, we conclude that the cause of action against the Attorneys did not accrue until the related or underlying judicial proceeding involving Childers and the Clients settled.', 'general', 'Perez-Abreu, Zamora & De La Fe, P.A. v. Taracido', 'https://www.courtlistener.com/opinion/7801923/', '7801923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Miss.', 'general', 'Hill v. State', 'https://www.courtlistener.com/opinion/7819348/', '7819348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding the statute constitutional, we affirm.', 'general', 'Hill v. State', 'https://www.courtlistener.com/opinion/7819348/', '7819348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Kenneth B.', 'general', 'Hill v. State', 'https://www.courtlistener.com/opinion/7819348/', '7819348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” This Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a police officer sufficiently meets enough of the above-enumerated criteria to come within the confines of the term “officers” as used in section 16-9-220.', 'general', 'State v. Crenshaw', 'https://www.courtlistener.com/opinion/1265672/', '1265672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Appellants Crenshaw and Ligón were each convicted of bribery and sentenced to five years imprisonment, suspended upon the service of eighteen months and five years probation We affirm.', 'sentencing', 'State v. Crenshaw', 'https://www.courtlistener.com/opinion/1265672/', '1265672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the lower court’s determination of those issues under Rule 23 of the Rules of Practice, of this Court.', 'general', 'State v. Crenshaw', 'https://www.courtlistener.com/opinion/1265672/', '1265672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we affirm R.', 'general', 'R.J.S. v. State', 'https://www.courtlistener.com/opinion/7834027/', '7834027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified.', 'general', 'S.C. Dep''t of Motor Vehicles v. Dover', 'https://www.courtlistener.com/opinion/7478368/', '7478368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the circumstances of this case, we hold that such a special relationship came into being, under a statute enacted in 1977, when a child abuse report was filed with the government agency established by that statute for the protection of abused children.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in granting that motion.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the District of Columbia, however, we hold that when CPS received a report that the two Roddy children, who were specifically and individually identified, were being abused by their father, the Child Abuse Prevention Act created a special relationship between the District and the two children.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'District of Columbia, supra, this court held that when the District of Columbia is sued for failure to provide public services, its duty of care is "owed .', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reading Platt and Morgan together, we conclude that there are at least two ways to demonstrate the existence of a "special relationship"[6] between the city and the injured party which would justify reliance by the injured party on the city''s representations.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that appellants presented enough evidence to raise a material issue of fact and thereby defeat the District''s motion for summary judgment.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s dismissal of the complaint with respect to Marion Barry, the Mayor of the District of Columbia, and Regina Barnard, the chief of CPS.', 'dismissal', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the defendants did not owe Heck a duty to safely store and keep the gun at issue.', 'general', 'Estate of Heck Ex Rel. Heck v. Stoffer', 'https://www.courtlistener.com/opinion/2167057/', '2167057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if we overlook the brief''s deficiencies, we conclude that there *203 was no misfeasance because the defendants owed Heck no duty to safely store the gun.', 'general', 'Estate of Heck Ex Rel. Heck v. Stoffer', 'https://www.courtlistener.com/opinion/2167057/', '2167057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Estate of Heck Ex Rel. Heck v. Stoffer', 'https://www.courtlistener.com/opinion/2167057/', '2167057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that, although the trial court erred in its Frye analysis, this error was harmless.', 'general', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that defendant did not make a timely objection to the prosecutor''s opening statement.', 'general', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we conclude that the trial court erred in dismissing Juror 20.', 'dismissal', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the record, we conclude that had the jury been allowed to continue to deliberate with Juror 20 as a member of the jury, a nonunanimous verdict would likely have been rendered.', 'general', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we find that the trial court abused its discretion in dismissing Juror 20.', 'dismissal', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant''s convictions, as well as his sentences on the home invasion *1092 and aggravated arson convictions.', 'sentencing', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), where we held that even though Kentucky does not have a statute of limitations for felonies, a due process violation for pre-indictment delay will only result "where there is both substantial prejudice and an intentional delay to gain advantage.', 'general', 'Shane v. Commonwealth', 'https://www.courtlistener.com/opinion/2356861/', '2356861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Morgan, this Court held that the trial court''s error in not properly striking a juror for cause was harmless (even though the defendant therein had to exercise a peremptory challenge to remove a biased juror), because no unqualified juror sat on his case.', 'general', 'Shane v. Commonwealth', 'https://www.courtlistener.com/opinion/2356861/', '2356861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'residence, and no such report was furnished here, we affirm.', 'general', 'State v. Jason Muxlow', 'https://www.courtlistener.com/opinion/10283964/', '10283964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction.', 'general', 'Pursley v. State', 'https://www.courtlistener.com/opinion/7878416/', '7878416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Articulating for the first time, and then applying, a multifaetor set of criteria for determining whether the Winskip protections applied to bar such a system, we concluded that the Pennsylvania statute did not run afoul of our previous admonitions against relieving the State of its burden of proving guilt, or tailoring the mere form of a criminal statute solely to avoid Winship’s strictures.', 'general', 'Apprendi v. New Jersey', 'https://www.courtlistener.com/opinion/118381/', '118381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*488Rejecting Almendarez-Torres’ objection, we concluded that sentencing him to a term higher than that attached to the offense alleged in the indictment did not violate the strictures of Winship in that case.', 'sentencing', 'Apprendi v. New Jersey', 'https://www.courtlistener.com/opinion/118381/', '118381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we held that New York’s requirement that the defendant, rather than the State, bear the burden of proof on this factual determination comported with the Fourteenth Amendment’s Due Process Clause.', 'general', 'Apprendi v. New Jersey', 'https://www.courtlistener.com/opinion/118381/', '118381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we held that the Constitution does not restrict a judge’s sentencing decision to information that is charged in an indictment and subject to cross-examination in open court.', 'sentencing', 'Apprendi v. New Jersey', 'https://www.courtlistener.com/opinion/118381/', '118381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with Sievers that a dismissal was appropriate under these facts, and we reverse and dismiss.', 'dismissal', 'Sievers v. City of Fort Smith', 'https://www.courtlistener.com/opinion/7879539/', '7879539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we cannot agree that this was a place to which the public or substantial numbers of people had access, we hold that the trial court erred in failing to dismiss appellant’s case.', 'dismissal', 'Weaver v. State', 'https://www.courtlistener.com/opinion/7879877/', '7879877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 745 (1964), we held that Berry, who was seated in a vehicle parked on a highway right-of-way approximately ten to twenty-five feet from the paved surface of the road, was in a “public place.', 'general', 'Weaver v. State', 'https://www.courtlistener.com/opinion/7879877/', '7879877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/7879958/', '7879958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 381 (1996), we articulated a standard for determining whether a civil forfeiture is “punishment” for double jeopardy purposes, and we hold that this standard pertains to the suspension provision.', 'general', 'Pyron v. State', 'https://www.courtlistener.com/opinion/7880174/', '7880174') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the temporary revocation of the privilege of driving for refusal to submit to a chemical analysis is rationally related to the purpose of the statute, which is to protect the public from intoxicated drivers and to reduce alcohol-related accidents.', 'general', 'Pyron v. State', 'https://www.courtlistener.com/opinion/7880174/', '7880174') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the totality of the circumstances of this case, we conclude that the trial court’s denial of Potter’s motion to suppress should be affirmed.', 'suppression', 'Potter v. State', 'https://www.courtlistener.com/opinion/7880760/', '7880760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not commit error in finding that the officer’s decision to conduct a pat-down search was appropriate to avoid a potentially dangerous situation.', 'general', 'Potter v. State', 'https://www.courtlistener.com/opinion/7880760/', '7880760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is indeed different from the question decided in Zadvydas, but because the statutory text provides for no distinction between admitted and nonad-mitted aliens, we find that it results in the same answer.', 'general', 'Clark v. Martinez', 'https://www.courtlistener.com/opinion/137741/', '137741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Ninth Circuit, reverse the judgment of the Eleventh Circuit, and remand both cases for proceedings consistent with this opinion.', 'general', 'Clark v. Martinez', 'https://www.courtlistener.com/opinion/137741/', '137741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Cyr, this Court held that the Immigration and Nationality Act (INA) did not divest district courts of jurisdiction under 28 U.', 'general', 'Clark v. Martinez', 'https://www.courtlistener.com/opinion/137741/', '137741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the avoidance canon poses no obstacle and the interpretive circumstances point in a common direction, we conclude that, as a matter of statutory interpretation, § 924(e)(1)(A) defines a single offense.', 'general', 'Harris v. United States', 'https://www.courtlistener.com/opinion/121164/', '121164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reaffirming McMillan and employing the approach outlined in that case, we conclude that the federal provision at issue, 18 U.', 'general', 'Harris v. United States', 'https://www.courtlistener.com/opinion/121164/', '121164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*609For the reasons stated, we hold that Walton and Apprendi are irreconcilable;', 'general', 'Ring v. Arizona', 'https://www.courtlistener.com/opinion/121165/', '121165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Sixth Amendment applies to both.', 'general', 'Ring v. Arizona', 'https://www.courtlistener.com/opinion/121165/', '121165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*602We held that Apprendi’s sentence violated his right to “a jury determination that [he] is guilty of every element of the crime with which he is charged, beyond a reasonable doubt.', 'sentencing', 'Ring v. Arizona', 'https://www.courtlistener.com/opinion/121165/', '121165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '639 (1990), this Court held that Arizona’s sentencing scheme was compatible with the Sixth Amendment because the additional facts found by the judge qualified as sentencing considerations, not as “element[s] of the offense of capital murder.', 'sentencing', 'Ring v. Arizona', 'https://www.courtlistener.com/opinion/121165/', '121165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such a requirement nonetheless applied, so that the Government would have to prove that a person charged with possessing child pornography actually knew that the materials contained depictions of real minors engaged in sexually explicit conduct.', 'general', 'Ashcroft v. Free Speech Coalition', 'https://www.courtlistener.com/opinion/118496/', '118496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant was entitled to present the evidence and to have it considered and thus are compelled to reverse and remand for resentencing.', 'sentencing', 'State v. Randolph', 'https://www.courtlistener.com/opinion/2297077/', '2297077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the language of the Appellate Division''s remand order leaves room for ambiguity and that resolution of this dispute turns on a close examination of the exchanges during argument between the appellate panel and counsel.', 'general', 'State v. Randolph', 'https://www.courtlistener.com/opinion/2297077/', '2297077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the uncontradicted testimony supports the trial judge''s finding of guilt, we affirm.', 'general', 'In Re Dw', 'https://www.courtlistener.com/opinion/2323678/', '2323678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because each inquiry leads us to conclude that defendant is entitled to relief, we affirm the judgment of the Appellate Division and remand the matter for a new trial.', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/2328579/', '2328579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, and in all other respects, we affirm the judgment of the Appellate Division.', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/2328579/', '2328579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in this sequence, the mandatory minimum sentencing statute does not apply because the first conviction did not occur within seven years prior to the commission of the second offense.', 'sentencing', 'Commonwealth v. Shiffler', 'https://www.courtlistener.com/opinion/2403675/', '2403675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the courts below properly deemed them to be "separate criminal transactions" for purposes of the three strikes provision.', 'general', 'Commonwealth v. Shiffler', 'https://www.courtlistener.com/opinion/2403675/', '2403675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We found that the word had acquired a "peculiar and appropriate" meaning in the sentencing context and examined its usage in various sections of the Sentencing Guidelines, as well as the usage of the phrase "criminal episode" in the compulsory joinder rule set forth in Section 110 of the Crimes Code.', 'sentencing', 'Commonwealth v. Shiffler', 'https://www.courtlistener.com/opinion/2403675/', '2403675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of the Superior Court and remand this matter to the trial court for sentencing consistent with Section 9714(a)(1).', 'sentencing', 'Commonwealth v. Shiffler', 'https://www.courtlistener.com/opinion/2403675/', '2403675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed, explaining our reading of the statute, which was consistent with the defendant''s position, as follows:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and remand.', 'general', 'Bocanegra v. State', 'https://www.courtlistener.com/opinion/2438242/', '2438242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the jury could have reasonably inferred Bocanegra''s misrepresentations subjected his employer to potential injury, we affirm his conviction of forgery and remand for vacation of the identity deception conviction.', 'general', 'Bocanegra v. State', 'https://www.courtlistener.com/opinion/2438242/', '2438242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold potential injury remains a sufficient basis for a finding of criminal intent in a forgery prosecution.', 'general', 'Bocanegra v. State', 'https://www.courtlistener.com/opinion/2438242/', '2438242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '602 NW2d 371 (1999), when we held that the defendant’s polite refusal to comply with a search warrant for the extraction of blood, “although indisputably passive in nature, was nevertheless sufficient to constitute obstruction, resistance, or opposition.', 'general', 'People v. Vasquez', 'https://www.courtlistener.com/opinion/849104/', '849104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that prior intoxication-related convictions serve the purpose of enhancing the offense in Section 49.', 'general', 'Gibson v. State', 'https://www.courtlistener.com/opinion/2463936/', '2463936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Section 49.', 'general', 'Gibson v. State', 'https://www.courtlistener.com/opinion/2463936/', '2463936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State proved an entry for purposes of the burglary statute.', 'general', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 267), we hold that the State proved that defendant Jones participated in the burglary of Little''s vehicle.', 'general', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 267), we conclude that an entry into the vehicle was proved.', 'general', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse the appellate court''s judgment in both cases and reinstate defendants'' convictions and sentences for burglary.', 'sentencing', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we reverse the judgment of the appellate court in Beauchamp''s case modifying the trial court''s judgment to reflect a conviction for theft, and reinstate Beauchamp''s conviction and *325 sentence for burglary.', 'sentencing', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse because, in our judgment, the evidence was sufficient.', 'general', 'People v. Hardiman', 'https://www.courtlistener.com/opinion/848898/', '848898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the plain language of the statute, constructive knowledge is not sufficient to impose liability under MCL 600.', 'general', 'Echelon Homes, LLC v. Carter Lumber Co.', 'https://www.courtlistener.com/opinion/848658/', '848658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under MCL 600.', 'general', 'Echelon Homes, LLC v. Carter Lumber Co.', 'https://www.courtlistener.com/opinion/848658/', '848658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the judgment of the Court of Appeals and hold that the statute requires exactly what it says — that the person knew that the property had been stolen, embezzled, or converted.', 'general', 'Echelon Homes, LLC v. Carter Lumber Co.', 'https://www.courtlistener.com/opinion/848658/', '848658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In lieu of granting leave to appeal, we reverse the Court of Appeals holding that constructive knowledge is sufficient to impose liability under MCL 600.', 'general', 'Echelon Homes, LLC v. Carter Lumber Co.', 'https://www.courtlistener.com/opinion/848658/', '848658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 896, 900 (2010) ("Today, though, we hold that an applicant currently on a felony deferred adjudication who remains under court supervision may not be admitted to practice law until the period of supervision has ended.', 'general', 'Miranda v. People', 'https://www.courtlistener.com/opinion/2499764/', '2499764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that as a condition of reinstatement, Petitioner must attend monthly AA meetings for the duration of his parole sentence.', 'sentencing', 'Miranda v. People', 'https://www.courtlistener.com/opinion/2499764/', '2499764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[38] Instead, we conclude that the fact Petitioner is serving a parole sentence ought to be considered as but one element in the totality of the circumstances in order to determine whether his resumption of legal practice will be injurious to the public.', 'sentencing', 'Miranda v. People', 'https://www.courtlistener.com/opinion/2499764/', '2499764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Spradlin, this Court held that attempted murder requires a specific intent to kill, and is not supported by "knowing" actions.', 'general', 'Guyton v. State', 'https://www.courtlistener.com/opinion/853128/', '853128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court as to murder and carrying a handgun without a license.', 'general', 'Guyton v. State', 'https://www.courtlistener.com/opinion/853128/', '853128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in limiting cross-examination, but even if it did, such error would be harmless beyond a reasonable doubt.', 'general', 'Spivey v. State', 'https://www.courtlistener.com/opinion/853249/', '853249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his convictions.', 'general', 'Spivey v. State', 'https://www.courtlistener.com/opinion/853249/', '853249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that a defendant prosecuted under HRS  708-836 may assert the mistake-of-fact defense with respect to the authorization element, where he claims that he mistakenly believed that the person who authorized his operation of the vehicle was the vehicle''s registered owner, because such a belief would potentially "negative[ ] the state of mind required to establish [the authorization] element of the offense.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the record does not reflect whether Lopez received Miranda warnings from Officer Hawkins or any other police officer at the time or after he was arrested, we hold that the right against self-incrimination attached at least as of the time of the arrest,[9] "because the right to remain silent derives from the Constitution and not from the Miranda warnings themselves.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that all three factors counsel that the DPA''s improper comments were not harmless beyond a reasonable doubt and, consequently, that Lopez is entitled to a new trial on remand.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Padilla, this court held that, because the defendant invoked an adverse inference with respect to the prosecution''s failure to call a witness, the prosecution was entitled to explain why it had not done so.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, although the defendant did not raise an alibi defense, he did undertake to "explain away" much of the prosecution''s evidence and, consequently, opened the door to the prosecution''s cross-examination and later "`comment on the state of the evidence.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While these cases permit prosecutorial comment on issues raised by the defendant, we conclude that they are distinguishable.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it was objectively reasonable for the officer to conclude that Heriberto''s general consent to come inside the apartment to talk to Erica included consent to walk down the open hallway to knock on the bathroom door.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6] In Elias, we held that when a trial court issues findings of fact but does not make a fact finding on a pertinent issue, an appellate court must assume that the trial court made no finding at all on the matter.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, we conclude that a reasonable person would have believed that the officers had authority to conduct a full search of Starr''s home including his closet and a roll of film;', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') ("Given the evidence regarding the initial traffic stop and the arrival of the drug-detection dog, all of which shows that the dog arrived within eight minutes of the traffic stop and before Wingfield finished conducting normal procedures for a traffic stop, we conclude that the record supports an implied finding by the trial court that the time it took for the dog to arrive did not prolong the initial stop beyond the time reasonably required to complete the mission of the stop.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Weaver''s consent, we affirm the judgment of the trial court and that of the court of appeals.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit
