INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When viewing the evidence in the light most favorable to the prosecution, we conclude that a rational trier of fact could have found beyond a reasonable doubt that defendants violated MCL 722.', 'general', 'People v. Lockett', 'https://www.courtlistener.com/opinion/8006566/', '8006566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*186We conclude that the trial court did not abuse its discretion in denying the request to have both instructions presented because the instructions as given fairly presented the issues to the jury and sufficiently protected defendants’ rights.', 'general', 'People v. Lockett', 'https://www.courtlistener.com/opinion/8006566/', '8006566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*177However, we find that MCL 750.', 'general', 'People v. Lockett', 'https://www.courtlistener.com/opinion/8006566/', '8006566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse both defendants’ convictions of CSC-I under MCL 750.', 'general', 'People v. Lockett', 'https://www.courtlistener.com/opinion/8006566/', '8006566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Johnson’s conviction of CSC-I under MCL 750.', 'general', 'People v. Lockett', 'https://www.courtlistener.com/opinion/8006566/', '8006566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we affirm Johnson’s conviction of CSC-I for engaging in sexual penetration with a person under 13 years of age.', 'general', 'People v. Lockett', 'https://www.courtlistener.com/opinion/8006566/', '8006566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant’s confession was freely and voluntarily made under the totality of the circumstances;', 'general', 'People v. Ryan', 'https://www.courtlistener.com/opinion/8006578/', '8006578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the absence of words of limitation in the statute, and because of the lack of evidence that there was a legislative intent to limit the scope of the term “another felony” in § 7401(3), we hold that the term includes any felony for which the defendant has been sentenced either before or simultaneously with the controlled substance felony enumerated in § 7401(3) for which a defendant is currently being sentenced.', 'sentencing', 'People v. Ryan', 'https://www.courtlistener.com/opinion/8006578/', '8006578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court correctly interpreted and applied MCL 750.', 'general', 'People v. Ryan', 'https://www.courtlistener.com/opinion/8006578/', '8006578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err by denying defendant’s motion to suppress his confession.', 'suppression', 'People v. Ryan', 'https://www.courtlistener.com/opinion/8006578/', '8006578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the arguments in defendant’s Standard 4 brief do not warrant reversal.', 'general', 'People v. Ryan', 'https://www.courtlistener.com/opinion/8006578/', '8006578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We conclude that the trial court correctly interpreted and applied MCL 750.', 'general', 'People v. Ryan', 'https://www.courtlistener.com/opinion/8006578/', '8006578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this logic applies equally to MCL 750.', 'general', 'People v. Ryan', 'https://www.courtlistener.com/opinion/8006578/', '8006578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the convictions and sentences.', 'sentencing', 'People v. Ryan', 'https://www.courtlistener.com/opinion/8006578/', '8006578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The majority cites People v Chapman,8 in which this Court held that a defendant is “ ‘responsible criminally for what of wrong flows directly from his corrupt intentions.', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '299 NW2d 304 (1980), this Court held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the first inquiry, we conclude that the trial court’s decision to allow evidence of Cameron’s prior bad acts did not unfairly prejudice Cameron at trial.', 'general', 'People v. Cameron', 'https://www.courtlistener.com/opinion/8006415/', '8006415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the second inquiry, we conclude that any prejudicial effect of the trial court’s decision to allow evidence of Cameron’s prior bad acts did not substantially outweigh the probative value of the evidence.', 'general', 'People v. Cameron', 'https://www.courtlistener.com/opinion/8006415/', '8006415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '36 Therefore, we conclude that the evidence satisfies the elements of assault or an assault and battery under MCL 750.', 'general', 'People v. Cameron', 'https://www.courtlistener.com/opinion/8006415/', '8006415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence supported an inference that Cameron intended to commit an assault or an assault and battery against Yacheson.', 'general', 'People v. Cameron', 'https://www.courtlistener.com/opinion/8006415/', '8006415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that sufficient evidence existed to support the jury’s guilty verdict.', 'general', 'People v. Cameron', 'https://www.courtlistener.com/opinion/8006415/', '8006415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”50 We conclude that the evidence supported the jury’s finding that Cameron intentionally committed an assault or assault and bat*620tery against Yacheson and that the jury’s verdict was not against the great weight of the evidence.', 'general', 'People v. Cameron', 'https://www.courtlistener.com/opinion/8006415/', '8006415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Cameron', 'https://www.courtlistener.com/opinion/8006415/', '8006415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it is again pure speculation that the alternate juror was coerced, we conclude that defendant was not prejudiced by the substitution of the alternate juror.', 'general', 'People v. Mahone', 'https://www.courtlistener.com/opinion/8006530/', '8006530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant appeals his convictions by right, and we affirm.', 'general', 'People v. Mahone', 'https://www.courtlistener.com/opinion/8006530/', '8006530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court complied with the remand order but erred by granting defendant’s motion for a new trial.', 'general', 'People v. Russell', 'https://www.courtlistener.com/opinion/8006682/', '8006682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and sentences.', 'sentencing', 'People v. Russell', 'https://www.courtlistener.com/opinion/8006682/', '8006682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred when it granted defendant’s motion on the basis of the 180-day rule.', 'general', 'People v. Rivera', 'https://www.courtlistener.com/opinion/8006827/', '8006827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because defendant presented no evidence of prejudice, defendant cannot prove that his right to a speedy trial was violated.', 'general', 'People v. Rivera', 'https://www.courtlistener.com/opinion/8006827/', '8006827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for further proceedings.', 'general', 'People v. Rivera', 'https://www.courtlistener.com/opinion/8006827/', '8006827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that because the erroneous admission of *641the evidence was not outcome determinative, reversal is not warranted.', 'general', 'People v. Roscoe', 'https://www.courtlistener.com/opinion/8006933/', '8006933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Roscoe', 'https://www.courtlistener.com/opinion/8006933/', '8006933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that “[w]hen a statute lists alternative means of committing an offense which in and of themselves do not constitute separate and distinct offenses, jury unanimity is not required with regard to the alternate theory.', 'general', 'People v. Chelmicki', 'https://www.courtlistener.com/opinion/8006977/', '8006977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statements contained in the victim’s police statement were hearsay.', 'general', 'People v. Chelmicki', 'https://www.courtlistener.com/opinion/8006977/', '8006977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was such evidence.', 'general', 'People v. Chelmicki', 'https://www.courtlistener.com/opinion/8006977/', '8006977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, we find that OV 8 could have properly been scored in this case on the basis of “asportation.', 'general', 'People v. Chelmicki', 'https://www.courtlistener.com/opinion/8006977/', '8006977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that our ruling does not offend Griffin v United States, 502 US 46;', 'general', 'People v. Chelmicki', 'https://www.courtlistener.com/opinion/8006977/', '8006977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Chelmicki', 'https://www.courtlistener.com/opinion/8006977/', '8006977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant must possess the criminal intent to aid, abet, procure, or counsel the commission of an offense.', 'general', 'People v. Henderson', 'https://www.courtlistener.com/opinion/8007012/', '8007012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Henderson', 'https://www.courtlistener.com/opinion/8007012/', '8007012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that, in this case, the trial court properly counted defendant’s misdemeanor convictions for possession of drug paraphernalia under PRV 5.', 'general', 'People v. Stevens', 'https://www.courtlistener.com/opinion/8007044/', '8007044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the prosecution presented sufficient evidence to support defendant’s conviction for AWIGBH and any error related to the scoring of prior record variable (PRV) 5 does not entitle defendant to resentencing, we affirm.', 'sentencing', 'People v. Stevens', 'https://www.courtlistener.com/opinion/8007044/', '8007044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1303 ("Thus, we hold that in order to protect the right to testify under the Hawai`i Constitution, trial courts must advise criminal defendants of their right to testify and must obtain an on-the-record waiver of that right in every case in which the defendant does not testify.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/2625250/', '2625250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/2625250/', '2625250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS HEREBY ORDERED that the Judgment of Conviction and Sentence filed on December 5, 2007 in the Circuit Court of the First Circuit is affirmed.', 'sentencing', 'State v. Coles', 'https://www.courtlistener.com/opinion/2625745/', '2625745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury instructions were prejudicially misleading, prejudicially confusing, and likely contributed to the reckless manslaughter conviction.', 'jury_instruction', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the jury instructions were inconsistent and misleading.', 'jury_instruction', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court committed plain error and Culkin''s conviction must be set aside.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court erred by ruling that Thomas''s past use of the handgun was not relevant.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998) ("Today we hold that juror interrogation is no longer to be left to the discretion of the trial court, but rather is a practice that is condemned and outright forbidden by this court.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 901, 902 (1998) ("We hold that allowing juror-inspired questions in a criminal case is not prejudicial per se, but is a matter committed to the sound discretion of the trial court.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the forgoing reasons, we affirm Culkin''s conviction of reckless endangering in the second degree, vacate Culkin''s conviction of reckless manslaughter, and remand this matter to the circuit court for a new trial.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
