INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that larceny from the person involves a substantial risk that force will be used during its commission and, therefore, hold that it is a specified felony.', 'general', 'People v. Perkins', 'https://www.courtlistener.com/opinion/848612/', '848612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because a person whose property is stolen from his presence may take steps to retain possession, and the offender may react violently, we conclude that the offense of larceny from a person, “by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense.', 'general', 'People v. Perkins', 'https://www.courtlistener.com/opinion/848612/', '848612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the felon-in-possession statute contains a proviso.', 'general', 'People v. Perkins', 'https://www.courtlistener.com/opinion/848612/', '848612') ON CONFLICT DO NOTHING;
