INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Appeals.', 'general', 'People v. Perkins', 'https://www.courtlistener.com/opinion/848612/', '848612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We therefore hold that larceny from a person is a specified felony within the meaning of MCL 750.', 'general', 'People v. Perkins', 'https://www.courtlistener.com/opinion/848612/', '848612') ON CONFLICT DO NOTHING;
