INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this Court ruled that the trial judge deprived the defendant of his constitutional right to a jury trial by allowing an expert to testify on the ultimate issue, this Court held the error to be harmless in light of the defendant’s confession.', 'general', 'Luginbyhl v. Commonwealth', 'https://www.courtlistener.com/opinion/1063261/', '1063261') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we hold that the Court of Criminal Appeals erred in reversing the defendant’s conviction and sentence.', 'sentencing', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the (i)(5) aggravating circumstance may be vicariously applied because the statutory language focuses upon the nature and circumstances of the crime, rather than the actions, intent, and conduct of the defendant.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we conclude that the trial court did not err by failing to instruct the jury on facilitation and solicitation or by permitting the medical examiner to display the victim’s cleaned and reconstructed skull as a demonstrative aid during his testimony;', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we conclude that the trial court did not err in failing to instruct on solicitation and facilitation.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we conclude that the trial court did not abuse its discretion by allowing Dr.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we conclude that the trial court did not err by admitting Exhibits 8, 9, and 10 into evidence.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, from our thorough review of the record and the briefs, we conclude that the prosecution did not pursue inconsistent theories at these separate trials.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we conclude that the defendant’s sentence of death is not disproportionate to the sentence imposed in similar cases, considering both the circumstances of the crime and the defendant.', 'sentencing', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the photograph array, we conclude that the evidence does not preponderate against the findings of the trial court.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is no reasonable likelihood that the jurors interpreted the trial court’s instructions so as to prevent proper consideration of direct and circumstantial evidence.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1058506/', '1058506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held Fontaine did not “acquiesce” in the trial court’s decision.', 'general', 'Edwards v. Commonwealth', 'https://www.courtlistener.com/opinion/1064059/', '1064059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Appellant is correct that this Court held Smith was at “the scene of any accident” when she was arrested, even though she stopped her car 100 yards away from the road sign she had struck.', 'general', 'Edwards v. Commonwealth', 'https://www.courtlistener.com/opinion/1064059/', '1064059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon rehearing en banc, we affirm the trial court on both offenses.', 'general', 'Edwards v. Commonwealth', 'https://www.courtlistener.com/opinion/1064059/', '1064059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since Rule 5A:18 bars consideration of this issue, we affirm the conviction of assault on a police officer.', 'general', 'Edwards v. Commonwealth', 'https://www.courtlistener.com/opinion/1064059/', '1064059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm both convictions.', 'general', 'Edwards v. Commonwealth', 'https://www.courtlistener.com/opinion/1064059/', '1064059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the conduct at issue violated the Fourth Amendment of the United States Constitution, we do not consider Divello''s Indiana Constitution claims.', 'search_seizure', 'Divello v. State', 'https://www.courtlistener.com/opinion/2039018/', '2039018') ON CONFLICT DO NOTHING;
