INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the parties’ arguments, the pertinent authorities, and the record designated for appellate consideration, we conclude that the circuit court erred by ruling that Mr.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statutes in question, ie.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Code § 61-7-7(c) to persons who have received unconditional pardons for their convictions, we concluded that “the Legislature’s method of achieving th[e] goal [of public safety] has been crafted narrowly so as not to offend the Constitution.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rohrbaugh has been convicted of such a crime, we find that the prohibitions of W.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these tenets to the matter at hand, we find that the Legislature did not violate the West Virginia or United States Constitutions by enacting the firearm restrictions contained in W.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Insofar as § 61-7-7 does not operate to increase the punishment for the crimes referenced therein, we find that it does not constitute cruel and unusual punishment under either the West Virginia or United States Constitutions.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the January 13,2003, order of the Grant County Circuit Court.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified.', 'general', 'Law v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/1301253/', '1301253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the directed verdict for Respondent on their wrongful termination claims because *440they failed to state a cause of action.', 'general', 'Law v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/1301253/', '1301253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s grant of Respondent’s motions for summary judgment on the malicious prosecution claims and for JNOV on the false imprisonment claims.', 'general', 'Law v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/1301253/', '1301253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified the directed verdict for Respondent on the wrongful termination claims.', 'general', 'Law v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/1301253/', '1301253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held “even if plaintiff were able to establish that [the chief] participated in a conspiracy to cover, up the shooting incident, a plain reading of W.', 'general', 'Kelley v. CITY OF WILLIAMSON, WEST VIRGINIA', 'https://www.courtlistener.com/opinion/1223993/', '1223993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we hold that admis-sión of this testimony was error.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we hold that the admission of the testimony was not sufficiently prejudicial to justify a new trial.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the state did not engage in pros-ecutorial misconduct.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that sufficient evidence was introduced at trial to support Lopez-Rios’s conviction for first-degree premeditated murder.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was little, if any, real value to much of the gang expert testimony, especially when considered in light of its probative value versus potential prejudice;', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’ ” We conclude that the state’s remarks merely paraphrased the substance of the witness’s testimony and “at worst, [were] unartful, not misconduct.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Lopez-Rios’s ineffective assistance of counsel claim is meritless.', 'ineffective_assistance', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, by failing to object at trial, where the court has the opportunity to remedy this oversight, Lopez-Rios waived the right to raise the issue on appeal.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In DeShay, we concluded that expert testimony relating to gang activity in general and gang affiliation was neither necessary nor helpful to the jury in evaluating the relevant evidence.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that DeShay was a routine drug conspiracy case and that in the context of that case, much of the gang expert’s testimony was duplicative and more prejudicial than probative.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that there was little, if any, real value to much of the gang expert testimony, especially when considered in light of its probative value versus potential prejudice * * The majority’s tepid decision departs from our clear abuse of discretion standard, but then nevertheless holds that “the admission of the testimony was not sufficiently prejudicial to justify a new trial.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion in summarily denying Hilton’s motion for a new trial without a hearing to determine if appellant’s claims of fear and intimidation were credible.', 'general', 'Lyons v. United States', 'https://www.courtlistener.com/opinion/1444074/', '1444074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in denying Lyons’s motion to suppress and affirm his conviction, but rem and for a hearing on Hilton’s motion for a new trial.', 'suppression', 'Lyons v. United States', 'https://www.courtlistener.com/opinion/1444074/', '1444074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the ruling of the trial court denying Hilton’s motion for judgment of acquittal, holding that the evidence was sufficient for a reasonable jury to find the appellant guilty beyond a reasonable doubt.', 'general', 'Lyons v. United States', 'https://www.courtlistener.com/opinion/1444074/', '1444074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s levying of sanctions in the form of attorneys’ fees and related expenses, and remand this case for the entry of an order in accordance with this opinion.', 'general', 'Davis Ex Rel. Davis v. Wallace', 'https://www.courtlistener.com/opinion/1248690/', '1248690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 558 (1987), for instance, we held that “[ejxpert testimony can be utilized to explain the psychological basis for the battered woman’s syndrome and to offer an opinion that the defendant meets the requisite profile of the syndrome.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004), we find that Berry’s request to proceed pro se was unequivocal and that his decision was knowingly, intelligently and voluntarily made.', 'general', 'Commonwealth v. Berry', 'https://www.courtlistener.com/opinion/1465718/', '1465718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse the Court of Appeals’ decision and reinstate Berry’s conviction and sentence in accordance with the trial court’s judgment.', 'sentencing', 'Commonwealth v. Berry', 'https://www.courtlistener.com/opinion/1465718/', '1465718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the indictments were insufficient to allege the crime of obtaining property by false pretenses and that the trial court property dismissed those charges.', 'dismissal', 'State v. Jones', 'https://www.courtlistener.com/opinion/6837888/', '6837888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State must allege the name of the recipient or that the recipient’s name is unknown in charging the crime of trafficking in stolen identities.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/6837888/', '6837888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State presented sufficient evidence to support the jury’s determination that Jones possessed the specific intent to commit identity theft.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/6837888/', '6837888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the Court of Appeals.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/6837888/', '6837888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the probationer’s threatening telephone call to the victim evinced an intent “to stalk [the victim] for the purpose of injuring him or her,” which was sufficiently threatening behavior to violate this same condition “M.', 'general', 'State v. Sanville', 'https://www.courtlistener.com/opinion/8210066/', '8210066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse because the condition failed to thoroughly apprise defendant of the conduct prohibited.', 'general', 'State v. Sanville', 'https://www.courtlistener.com/opinion/8210066/', '8210066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Evans v. Cote', 'https://www.courtlistener.com/opinion/8210152/', '8210152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '13 (1998), wherein we held that "[a]lleged errors of a constitutional magnitude will generally trigger a review by this Court under the plain error doctrine.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Burroughs'' prior conviction is comparable to the Wisconsin felony of attempted murder and that, pursuant to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in the final analysis, we conclude that the answer lies in our own Wisconsin case law that has defined the term "confine" for purposes of Wis.', 'general', 'State v. Burroughs', 'https://www.courtlistener.com/opinion/1711865/', '1711865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence presented at trial, we conclude that a reasonable jury could find that Burroughs confined Sharon by depriving her of her freedom of movement and compelling her to remain where she did not wish to remain.', 'general', 'State v. Burroughs', 'https://www.courtlistener.com/opinion/1711865/', '1711865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Based on the language of the statute and the accompanying Alabama jury instruction, we conclude that the elements of this offense were (1) that a person committed an assault on another and (2) that person had the intent, "unlawfully and maliciously to kill the person assaulted.', 'jury_instruction', 'State v. Burroughs', 'https://www.courtlistener.com/opinion/1711865/', '1711865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the supreme court''s decision in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that Burroughs has not contested this fact either on appeal or before the trial court, we conclude that the trial court properly relied on the Alabama conviction in sentencing Burroughs under the "three strikes" law.', 'sentencing', 'State v. Burroughs', 'https://www.courtlistener.com/opinion/1711865/', '1711865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient evidence for a reasonable jury to find that Burroughs confined Sharon contrary to the kidnapping statute, Wis.', 'general', 'State v. Burroughs', 'https://www.courtlistener.com/opinion/1711865/', '1711865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, given the charging language, we conclude that paragraph (l)(b) would be the only applicable paragraph.', 'general', 'State v. Burroughs', 'https://www.courtlistener.com/opinion/1711865/', '1711865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction and the order denying Burroughs'' motion for postconviction relief.', 'general', 'State v. Burroughs', 'https://www.courtlistener.com/opinion/1711865/', '1711865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a person who has been convicted of a misdemeanor crime of domestic violence and who does not lose his or her civil rights as a result of the conviction cannot have his or her civil rights “restored” for the purpose of 18 U.', 'general', 'In re Parsons', 'https://www.courtlistener.com/opinion/8219132/', '8219132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the tern “civil rights” in 921(a)(33)(B)(ii), which provides several exceptions to the prohibition in 922 U.', 'general', 'In re Parsons', 'https://www.courtlistener.com/opinion/8219132/', '8219132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it did not.', 'general', 'In re Parsons', 'https://www.courtlistener.com/opinion/8219132/', '8219132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that Appellant committed a misdemeanor crime of domestic violence as defined in 18 U.', 'general', 'In re Parsons', 'https://www.courtlistener.com/opinion/8219132/', '8219132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For *355the reasons that follow, we affirm the circuit court’s order.', 'general', 'In re Parsons', 'https://www.courtlistener.com/opinion/8219132/', '8219132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the reasons set forth above, we affirm the July 19, 2004, order of the Circuit Court of Ohio County that dismissed Appellant’s petition to regain the ability to possess a firearm.', 'dismissal', 'In re Parsons', 'https://www.courtlistener.com/opinion/8219132/', '8219132') ON CONFLICT DO NOTHING;
