INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 163 (1995), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that by enacting the offense of assault during the commission of a felony, the legislature clearly intended to impose punishment in addition to that specified for the underlying felony, if the criminal actor shot, cut, stabbed, or wounded another person during the attempt to commit or the commission of the underlying felony and to classify that additional conduct as felonious.', 'general', 'State v. McGilton', 'https://www.courtlistener.com/opinion/8219288/', '8219288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the reasons stated above, we affirm the order of the Circuit Court of Ohio County entered on January 12, 2011.', 'general', 'State v. McGilton', 'https://www.courtlistener.com/opinion/8219288/', '8219288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'City of Landrum v. Sarratt', 'https://www.courtlistener.com/opinion/1389646/', '1389646') ON CONFLICT DO NOTHING;
