INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the trial court denying bail to English and remand for the setting of a reasonable bond.', 'general', 'State v. English', 'https://www.courtlistener.com/opinion/1408712/', '1408712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And so, here, we conclude that to adhere to the principles well established in Rodriguez and our subsequent cases, double jeopardy and due process principles did not preclude the judge''s imposition, for the first time, of an extended term on count eleven.', 'general', 'State v. Kosch', 'https://www.courtlistener.com/opinion/6487537/', '6487537') ON CONFLICT DO NOTHING;
