INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this matter is ripe for judicial review, and defendant’s assignments of error are thus overruled.', 'general', 'North Carolina Department of Correction v. North Carolina Medical Board', 'https://www.courtlistener.com/opinion/6835437/', '6835437') ON CONFLICT DO NOTHING;
