INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the juvenile court’s finding that Jamie F.', 'general', 'In Re Audrey S.', 'https://www.courtlistener.com/opinion/1509090/', '1509090') ON CONFLICT DO NOTHING;
