INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the juvenile court’s determination that terminating Jamie F.', 'general', 'In Re Audrey S.', 'https://www.courtlistener.com/opinion/1509090/', '1509090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the juvenile court’s October 7, 2004 and November 11, 2004 orders terminating Jamie F.', 'general', 'In Re Audrey S.', 'https://www.courtlistener.com/opinion/1509090/', '1509090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the district court abused its discretion in instructing the jury on the probable cause element of test refusal in accordance with the language of CRIMJIG 29.', 'probable_cause', 'State v. Koppi', 'https://www.courtlistener.com/opinion/8280124/', '8280124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that Koppi has waived his argument regarding whether the district court abused its discretion by concluding as a matter of law that Koppi had a reasonable amount of time to consult with an attorney.', 'general', 'State v. Koppi', 'https://www.courtlistener.com/opinion/8280124/', '8280124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the district court abused its discretion in instructing the jury on probable cause in accordance with the language of CRIMJIG 29.', 'probable_cause', 'State v. Koppi', 'https://www.courtlistener.com/opinion/8280124/', '8280124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we hold that erratic driving behavior is always required for an officer to have probable cause that a suspect is driving while impaired.', 'probable_cause', 'State v. Koppi', 'https://www.courtlistener.com/opinion/8280124/', '8280124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the district court’s instruction to the jury included an incorrect, purely subjective definition of probable cause and the instructional error was not harmless beyond a reasonable doubt, we reverse.', 'probable_cause', 'State v. Koppi', 'https://www.courtlistener.com/opinion/8280124/', '8280124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we cannot say that the instructional error was harmless beyond a reasonable doubt, we reverse Koppi’s conviction for test refusal and remand for further proceedings consistent with this opinion.', 'general', 'State v. Koppi', 'https://www.courtlistener.com/opinion/8280124/', '8280124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After agreeing that in informant cases a defendant need only establish that the informant''s testimony "may be necessary to a determination of guilt or innocence," this court held that "in light of the strong public policy favoring protection of the counseling records .', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Charlotte did not waive her therapist-patient privilege, as she did not disclose any significant part of a confidential matter or communication.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In response to the court of appeals'' certified question, we conclude that there is a public policy exception to the therapist-patient privilege and to the confidentiality in patient health care records where negligent therapy causes false accusations against the parents for sexually or physically abusing their child.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that none of the records constitute a voluntary disclosure of "any significant part of the matter or communication.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Charlotte reasonably believed her communications with Phillips would be confidential with Phillips.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that public policy requires creating an exception to therapist-patient confidentiality and privilege where negligent therapy is alleged to have caused accusations against parents for sexually or physically abusing their child.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bearing this in mind, we conclude that the victim cannot impede the claim.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that Charlotte did not waive her therapist-patient privilege.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that there is a public policy exception to the therapist-patient privilege and to the confidentiality in patient health care records where negligent therapy causes false accusations against the parents for sexually or physically abusing their child.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 Therefore, we reverse the circuit court''s order and remand this case for further proceedings.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in ruling that the State was not required to prove Mr.', 'general', 'Short v. State', 'https://www.courtlistener.com/opinion/1748010/', '1748010') ON CONFLICT DO NOTHING;
