INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the instructions given by the court adequately covered all pertinent matters included in Iromuanya’s proposed “theory of defense” instruction.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the district court did not err in refusing to give Iromuanya’s proposed instruction stating his theory of defense.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming the truth of Iromuanya’s statement to police that when Jenkins approached a second time, he asked if Iromuanya was the person who had punched him previously, we conclude that neither that statement nor any other circumstance reflected in the record would warrant a reasonable or good faith belief in the necessity of using deadly force.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking into account all of the relevant circumstances, including but not limited to the fact that Iromuanya had no significant criminal record or history of violence, we conclude that the district court abused its discretion in setting life imprisonment as the minimum term of the sentence for second degree murder and that to that extent, the sentence was excessive.', 'sentencing', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence imposed by the district court of not less than life imprisonment nor more than life imprisonment on count III, murder in the second degree, is excessive, and we modify that sentence to not less than 50 years’ imprisonment nor more than life imprisonment, with the sentence on count III to be served concurrently with the sentence on count I.', 'sentencing', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that because the defendant was found guilty of two distinct predicate offenses, attempted second degree murder and first degree assault, the trial court did not err in imposing consecutive sentences on the two corresponding convictions for use of a weapon to commit a felony.', 'sentencing', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Stone, we held that driving without a driver’s license in violation of MinmStat.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, we held that driving after revocation of a person’s driver’s license in violation of Minn.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the extent that in Johnson we held that the state had no jurisdiction to enforce the driving-after-revocation statute against tribal members driving on tribal lands, driving after cancellation as inimical to public safety should produce no different result.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Our ruling in Johnson was clear and unequivocal — we held that because the prior offense carries its own sanction, fairness dictates it not again be used to determine the sanction for the current-and substantially different — matter before the court, Johnson, 598 N.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that withdrawal of appellant’s guilty pleas was not required to correct a manifest injustice or for fair and just reason, and that he received effective assistance of counsel.', 'plea', 'Butala v. State', 'https://www.courtlistener.com/opinion/1822728/', '1822728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that the district court did not err in denying appellant’s request to withdraw his pleas and that appellant received effective assistance of counsel, we affirm.', 'plea', 'Butala v. State', 'https://www.courtlistener.com/opinion/1822728/', '1822728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Butala v. State', 'https://www.courtlistener.com/opinion/1822728/', '1822728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 156 (1980), we held that, in order to sustain a conviction of first-degree battery, life-endangering conduct must generally be involved.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, in Bolden, we reversed a conviction for first-degree battery where the defendant had kicked and beaten a police officer about the head and chest, resulting in a broken jaw, because there was insufficient evidence to show that the injuries were caused by a weapon, rather than by the beating and kicking that the officer sustained.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', in which we held that the disorderly conduct statute could apply to a threatening communication from a student to a teacher.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute may be applied to such conduct.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that the disorderly conduct statute requires, at a minimum, that, when the conduct tends to cause or provoke a disturbance that is private or personal in nature, there must exist the real possibility that this disturbance will spill over and cause a threat to the surrounding community as well.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this analysis, we conclude that the disorderly conduct statute was appropriately applied to *24Schwebke''s conduct in this case.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we conclude that the application of the disorderly conduct statute in this case was appropriate.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, even though the conduct involved a private interaction between the teacher and student, the disorderly conduct statute could apply, not because it caused the teacher to become upset, but instead because the threat jeopardized the proper functioning of the school itself, which was regarded as a threat to public order.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals'' decision.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we affirm the court of appeals'' decision to uphold the convictions of Schwebke.', 'general', 'State v. Schwebke', 'https://www.courtlistener.com/opinion/1852126/', '1852126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the sentencing court did not render a non-individualized sentence in this matter and reject the Superior Court’s assertions to the contrary.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the findings upon which Walls’ sentence was based were legally permissible.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we find that the Superior Court *561did err.', 'general', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we appreciate the Superior Court’s scholarly review of sentencing discretion, we find that the Superior Court’s understanding of the import of the guidelines and of the nature of appellate review of sentencing led it to impermissibly characterize the sentencing court’s decision and to reweigh the reasons offered by the sentencing court.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that while the sentencing court unfortunately cast doubt upon the individualized nature of Walls’ sentence by making certain general comments about those who sexually victimize young children, when viewed as a whole, the sentencing court made a sentencing decision that was individualized with respect to Walls.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the Superior Court, we find that the sentencing court was permitted to rely on these factors to justify Walls’ sentence.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that the sentencing court took into account the general standards for sentencing.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the above, we find that the Superior Court exceeded its standard of review and erred in making certain legal determinations which led it to supplant the sentencing court’s discretion and to vacate the judgment of sentence imposed by the sentencing court.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Appellate Division upheld the defendants’ arguments in respect of both claims and we reverse that judgment.', 'general', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Atkinson, this court held that, as a matter of law, it is always improper for a circuit court to employ the mere-fact method to impeach a testifying defendant.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION In sum, we hold that plaintiffs’ public nuisance claims against both the manufacturer and the dealer defendants must be dismissed.', 'dismissal', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We note, however, that in City of Chicago we held that the manufacturer and distributor defendants owed no duty to the plaintiff city or its residents to prevent the illegal possession and use of their products within the city.', 'general', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that although the village was empowered by statute to declare what would be deemed a nuisance within its borders, it did not have the power to declare a nuisance where no nuisance, in fact, existed.', 'general', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not, however, determine whether the tragic personal losses suffered by plaintiffs constitute the type of special injury necessary to confer standing because we conclude that, as a matter of law, they cannot state a claim in public nuisance against these defendants.', 'general', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is equally unreasonable to expect defendants to foresee that the aggregate effect of the lawful manufacture and sale of firearms will be the creation of a public nuisance in a distant city.', 'general', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, reviewing the evidence in accord with the standard expressed above, we hold that a rational trier of fact could have found, beyond a reasonable doubt, that defendant’s belief that the circumstances justified the use of deadly force was unreasonable.', 'general', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the foregoing reasons, we hold that the State proved beyond a reasonable doubt that defendant’s claim of self-defense was unreasonable.', 'general', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that rape was the more serious offense and reversed the defendant’s conviction for incest, even though the defendant received a longer sentence for that conviction.', 'sentencing', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the appellate court on this issue and remand to the appellate court with directions to vacate defendant’s second degree murder conviction in favor of his aggravated battery with a firearm conviction, the sentence to run consecutively to defendant’s other 18-year sentence that has not been appealed.', 'sentencing', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hill, we affirmed the conviction for the more specific crime and vacated the conviction for the more general crime.', 'general', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this court held that, because both convictions arose from the same act, only the conviction for the greater offense could stand.', 'general', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Florine, we held that the defendant was guilty under Minn.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Strong, we held that Minn.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '12 We conclude that the “catch all” language of section 609.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that in light of our jurisprudential history requiring clear legislative intent to dispense with proof of mens rea and our heightened concern when it relates to felony level crimes, and because we believe the nature of the weapon here-a knife-was not so inherently dangerous that appellant should be on notice that mere possession would be a crime, respondent was required to prove that appellant knew he possessed the knife on school property as an element of the section 609.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals decision and remand to the trial court to determine whether ''appellant had knowledge of possession of the knife while on school property-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 The court of appeals concluded that “[bjecause *805there is sufficient evidence that appellant should have known that the knife was in his coat, we affirm the trial court.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Siirila, we affirmed a conviction under Minn.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While this Court held in Frohriep, supra at 697-698, that the knock and talk procedure is not unconstitutional per se, we noted that it is not without constitutional implications.', 'general', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district *433court’s findings were not clearly erroneous and that the coerciveness of the encounter constituted an unreasonable seizure of defendant’s person.', 'general', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only when the officer, by means of physical force or show of authority, has in some way restrained the liberty of a citizen may we conclude that a ‘seizure’ has occurred”.', 'general', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, under these circumstances we conclude that the police officers’ persistence despite defendant’s efforts to terminate the encounter resulted in defendant being seized in violation of his constitutional rights.', 'general', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that defendant is entitled to the suppression of his incriminating statements and the marijuana.', 'suppression', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s order affirming the district court’s order of dismissal.', 'dismissal', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s order affirming the district court’s dismissal of this case.', 'dismissal', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration, we find that by a guilty plea a criminal defendant does waive Apprendi-based sentencing objections on appeal, as our appellate court has for the most part concluded.', 'sentencing', 'People v. Jackson', 'https://www.courtlistener.com/opinion/2244625/', '2244625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons above stated, we affirm the judgment of the appellate court, which affirmed the judgment of the circuit court.', 'general', 'People v. Jackson', 'https://www.courtlistener.com/opinion/2244625/', '2244625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, relying on the long-standing and well-established principle that consistency in a verdict is not required, we hold that Appellee’s acquittal of the predicate offense of robbery does not *596necessitate the vacatur of his conviction of second-degree murder.', 'general', 'Commonwealth v. Miller', 'https://www.courtlistener.com/opinion/2319429/', '2319429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirmed the Superior Court’s vacatur of the Maglioceo cross-appellee’s conviction for ethnic intimidation.', 'general', 'Commonwealth v. Miller', 'https://www.courtlistener.com/opinion/2319429/', '2319429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After Magliocco was decided, the Commonwealth Court held, and we affirmed, that the ethnic intimidation statute was unconstitutional on procedural grounds related to its enactment by the General Assembly.', 'general', 'Commonwealth v. Miller', 'https://www.courtlistener.com/opinion/2319429/', '2319429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2C:1-6(c) and the policy rationale underlying the criminal statute of limitations, we conclude that the DNA-tolling exception applies only when the State obtains DNA evidence that directly matches the defendant to physical evidence of a crime.', 'general', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, for the DNA-tolling provision to apply, the State must have DNA evidence that establishes a direct link between physical evidence already within its possession and the defendant it seeks to prosecute.', 'general', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the statutory definitions and "viewing the term in its proper syntax," we concluded that the word "actor" is synonymous with "defendant" in NERA and includes both principals and accomplices.', 'general', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as we found that NERA, by its own use of the term, compelled a particular definition of "actor," so we find that the tolling statute uses "actor" to denote the defendant, the object of prosecution.', 'general', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, we find that adopting the State''s interpretation and applying the "any natural person" language set forth in N.', 'general', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court correctly dismissed the indictment in Twiggs.', 'dismissal', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there may have been a continuing course of conduct, for tolling purposes, which will be determined by a jury upon remand.', 'general', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the DNA identifications at issue in these cases did not directly link defendants to the relevant offenses, we affirm the Appellate Division''s affirmance of the trial court''s dismissal of the indictments against defendant Gary Twiggs in its entirety and against defendants James and Likisha Jones in relevant part.', 'dismissal', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Appellate Division affirming the trial court''s dismissal of the indictment against defendant in Twiggs.', 'dismissal', 'State v. Twiggs', 'https://www.courtlistener.com/opinion/8263582/', '8263582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of the record, we hold that Perroni has failed to demonstrate the required bias on Judge Fox’s part.', 'general', 'Perroni v. State', 'https://www.courtlistener.com/opinion/2354900/', '2354900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm.', 'general', 'Perroni v. State', 'https://www.courtlistener.com/opinion/2354900/', '2354900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Venhaus, we held that a judge should have recused to avoid the mere appearance of bias.', 'general', 'Perroni v. State', 'https://www.courtlistener.com/opinion/2354900/', '2354900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More recently, we held that a trial judge should recuse from deciding Rule 11 sanctions where the judge’s comments and rulings indicated that he was biased.', 'general', 'Perroni v. State', 'https://www.courtlistener.com/opinion/2354900/', '2354900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the prosecutor’s comments were “clearly improper” because he implied that the expert’s testimony was fabricated or contrived with the assistance of defense counsel.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that the prosecutor’s remarks were improper and constituted prosecutorial misconduct.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the expert witnesses’ testimony about where Makowski was riding her bicycle when she was hit by defendant’s car was highly contested at trial and because defendant’s guilt depended entirely on which experts the jury believed, we conclude that the inappropriate comments made by the prosecutor could have improperly swayed the jury and denied defendant a fair trial.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed defendant’s death sentence for a number of reasons, including that the cumulative effect of prosecutorial improprieties were substantially prejudicial and deprived defendant of his constitutional right to a fair trial.', 'sentencing', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the conviction on other grounds and did not determine whether any alleged misconduct constituted reversible error.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division affirming defendant’s conviction and remand the matter to the Law Division for a new trial.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in this sequence, the mandatory minimum sentencing statute does not apply because the first conviction did not occur within seven years prior to the commission of the second offense.', 'sentencing', 'Commonwealth v. Shiffler', 'https://www.courtlistener.com/opinion/2403675/', '2403675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the courts below properly deemed them to be “separate criminal transactions” for purposes of the three strikes provision.', 'general', 'Commonwealth v. Shiffler', 'https://www.courtlistener.com/opinion/2403675/', '2403675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We found that the word had acquired a “peculiar and appropriate” meaning in the sentencing context and examined its usage in various sections of the Sentencing Guidelines, as well as the usage of the phrase “criminal episode” in the compulsory joinder rule set forth in Section 110 of the Crimes Code.', 'sentencing', 'Commonwealth v. Shiffler', 'https://www.courtlistener.com/opinion/2403675/', '2403675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*497Accordingly, we reverse the order of the Superior Court and remand this matter to the trial court for sentencing consistent with Section 9714(a)(1).', 'sentencing', 'Commonwealth v. Shiffler', 'https://www.courtlistener.com/opinion/2403675/', '2403675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed, explaining our reading of the statute, which was consistent with the defendant’s position, as follows:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" 56 Because we conclude that the "right" to cause damage addressed by this element of the offense includes a claim of right based on a legal justification such as the defense of necessity, we hold that McGee was improperly required to bear the burden of proof on his claim of necessity.', 'general', 'McGee v. State', 'https://www.courtlistener.com/opinion/2586302/', '2586302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this statutory definition of the offense, we conclude that the state bore the burden of proving beyond a reasonable doubt that McGee lacked any reasonable ground to believe that his actions were justified by his need for self-protection.', 'general', 'McGee v. State', 'https://www.courtlistener.com/opinion/2586302/', '2586302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the text, context, and history of the criminal mischief statute provide no support for the narrow meaning of "right" proposed by the state, we conclude that the criminal mischief statute''s phrase "having no right to do so or any reasonable ground to believe the person has such a right" encompasses any reasonable ground to believe that a legal justification for causing the alleged property damage existed.', 'general', 'McGee v. State', 'https://www.courtlistener.com/opinion/2586302/', '2586302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we conclude that rational jurors could have differed as to whether the totality of the evidence raised a reasonable doubt based on McGee''s claim of necessity.', 'general', 'McGee v. State', 'https://www.courtlistener.com/opinion/2586302/', '2586302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'McGee v. State', 'https://www.courtlistener.com/opinion/2586302/', '2586302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, even if the “M-800” was an illegal firework,3 its lone presence in the passenger compartment would not justify a search of the trunk any more than would a burning cigarette in the passenger compartment of an automobile occupied by a single minor, or an open container in the passenger compartment of a vehicle being operated on a public roadway.', 'general', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, assuming the single firecracker ran afoul of the ordinance, we conclude that its presence in the passenger compartment did not justify a search of the automobile’s trunk under the automobile exception.', 'general', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record before us, we conclude that the district court correctly concluded that the slight odor of burnt marijuana alone was insufficient to justify Bowes’ warrantless search of the trank of Schmadeka’s vehicle.', 'general', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the district court’s order denying the motion to suppress must be reversed and the ease remanded to the district court for proceedings consistent with Sehmadeka’s Rule 11 plea agreement.', 'suppression', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the district court’s order denying Schmadeka’s motion to suppress regarding the search of the automobile’s trunk, we conclude that his post-arrest statements come within the fruit of the poisonous tree doctrine.', 'suppression', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mitsuda, this court held that the victim’s awai’eness of the theft is a necessary element according to HRS § 708-840(l)(b)(ii).', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that instance, we found that the trial court properly ruled that the defendant''s oral and written confessions -- obtained after just over three hours of interrogation and nine hours at the police station, during which the defendant asked to "lie down" and "was offered food, beverages, cigarettes, and the opportunity to rest" -- was voluntary.', 'general', 'State v. A.M.', 'https://www.courtlistener.com/opinion/8269554/', '8269554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we reverse the judgment of the Appellate Division and reinstate defendant''s conviction.', 'general', 'State v. A.M.', 'https://www.courtlistener.com/opinion/8269554/', '8269554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that we do not need to decide this issue because we hold that Matthew has not established that he was "subjected to restrictions approximating those experienced by one who is incarcerated.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,1 where we held that whether a person is entitled to credit for time served while released on bail or probation is determined by whether the "person released on bail or probation is subjected to restrictions approximating those experienced by one who is incarcerated.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" 2 We conclude that the restrictions to which Matthew was subjected did not meet this standard.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that Matthew was not entitled to credit toward his sentence of imprisonment for the period of time he was subject to electronic monitoring .', 'sentencing', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Matthew''s court-ordered conditions of release did not subject him to "restrictions approximating those experienced by one who is incarcerated.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that, just because the Commissioner of the Department of Corrections has the authority to designate relatively unstructured ways in which a prisoner may serve a sentence, it does not follow that a person subject to those same conditions as a component of pre-custody release by the court must receive credit for time served.', 'sentencing', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the proper test for whether a person gets credit against his sentence for time spent on a court-ordered release is the test which the supreme court set forth in Lock: whether the conditions of release impose "substantial restrictions on one''s freedom of movement and behavior.', 'sentencing', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '23 When we apply the test in Nygren, we conclude that the restrictions which Matthew faced did not "approximate those experienced by one who is incarcerated.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree in part, and, therefore, we reverse in part and affirm in part.', 'general', 'State v. Welch', 'https://www.courtlistener.com/opinion/2638805/', '2638805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse the conviction and sentence for the possession of chemicals and equipment for manufacturing methamphetamine.', 'sentencing', 'State v. Welch', 'https://www.courtlistener.com/opinion/2638805/', '2638805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 15 For the foregoing reasons, we affirm the convictions and sentences for the manufacture of the dangerous drug methamphetamine and for the possession of drug paraphernalia.', 'sentencing', 'State v. Welch', 'https://www.courtlistener.com/opinion/2638805/', '2638805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we affirm the admission of the photographs, we take this opportunity to address an area of growing concern to this Court.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/2719240/', '2719240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both on the basis of Judge Blee''s comprehensive
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the sentence is procedurally sound, the second step is to review the "substantive reasonableness” of the sentence, taking into account the totality of the circumstances, "including the extent of any variance from the Guidelines range.', 'sentencing', 'United States v. Irey', 'https://www.courtlistener.com/opinion/151874/', '151874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Rather, under my approach, when we reverse a sentence on substantive grounds, we are simply holding that under the non-clearly erroneous facts found by the district judge and in light of the district judge''s explanation, no rational judge could have imposed that sentence.', 'sentencing', 'United States v. Irey', 'https://www.courtlistener.com/opinion/151874/', '151874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'City of Rock Hill v. Suchenski', 'https://www.courtlistener.com/opinion/1279155/', '1279155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in denying the motion to suppress.', 'suppression', 'Debroux v. Commonwealth', 'https://www.courtlistener.com/opinion/1285162/', '1285162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm.', 'general', 'Debroux v. Commonwealth', 'https://www.courtlistener.com/opinion/1285162/', '1285162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that the unused bags were found in close proximity to other items used in the sale and distribution of methamphetamine, as well as a sizeable quantity of methamphetamine, we conclude that the only reasonable inference to be drawn from the circumstances proved is that Hanson possessed the 12.', 'general', 'State v. Hanson', 'https://www.courtlistener.com/opinion/8280194/', '8280194') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence that Hanson possessed the approximately 100 small, unused bags, when coupled with the remaining evidence as a whole, forms a complete chain that leads so directly to Hanson’s guilt of possessing more than 10 grams of methamphetamine with the intent tó sell as to exclude beyond a reasonable doubt any rational inference other than guilt.', 'general', 'State v. Hanson', 'https://www.courtlistener.com/opinion/8280194/', '8280194') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the court of appeals.', 'general', 'State v. Hanson', 'https://www.courtlistener.com/opinion/8280194/', '8280194') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that assault-harm, as defined by *310Minn.', 'general', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the court had not abused its discretion in refusing to give the requested instruction because the assault at issue was not a specific-intent crime.', 'general', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we held that the State had established critical impact because Edrozo’s “confession [was] important to the state’s *311burden of proving [Edrozo’s] state of mind.', 'general', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When viewed according to its plain and ordinary meaning, we conclude that the phrase “particular intent” as used in Minn.', 'general', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because an assault-fear offense is a specific-intent crime, we conclude that the district court properly instructed the jurors that they could consider Fleck’s voluntary intoxication in determining whether he intended to cause KW.', 'general', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that assault-harm is a general-intent crime and, therefore, the district court did not err in concluding that assault-harm is not the type of crime that is subject to a voluntary intoxication jury instruction.', 'jury_instruction', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude the district court properly instructed the jury, we reverse the court of appeals’ decision and reinstate Fleck’s conviction.', 'general', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we ultimately conclude that the district court properly instructed the jury, we reverse the court of appeals’ decision and reinstate Fleck’s conviction.', 'general', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 Because the district court properly instructed the jury on the law, we reverse the court of appeals’ decision and reinstate Fleck’s conviction.', 'general', 'State v. Fleck', 'https://www.courtlistener.com/opinion/8280464/', '8280464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Lange was disqualified under Rule 2.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/8280573/', '8280573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the circumstances proved, we conclude that Pratt’s arguments have no merit.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/8280573/', '8280573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the evidence of the lenders’ reliance is sufficient to support Pratt’s convictions.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/8280573/', '8280573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a reasonable examiner would question Judge Lange’s ability to be impartial.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/8280573/', '8280573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that we must.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/8280573/', '8280573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jacobs, we concluded that a reasonable examiner would not question a judge’s impartiality based on his wife’s employment.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/8280573/', '8280573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11(A) of the Code of Judicial Conduct, that Pratt is entitled to a new trial, and therefore we reverse.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/8280573/', '8280573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Judge Lange’s relationship with the HCAO would cause a reasonable examiner to question his impartiality and reversal is required to maintain the public’s confidence in the independence, integrity, *879and impartiality of the judiciary, we reverse Pratt’s convictions and remand to the district court for further proceedings consistent with this opinion.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/8280573/', '8280573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we affirm.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/8280734/', '8280734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/8280734/', '8280734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the submission of documentary evidence presenting contradictory versions of events cannot constitute a valid trial on stipulated facts under Minn.', 'general', 'Dereje v. State', 'https://www.courtlistener.com/opinion/8281224/', '8281224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the procedures used to convict him complied with the requirements of Minn.', 'general', 'Dereje v. State', 'https://www.courtlistener.com/opinion/8281224/', '8281224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did not.', 'general', 'Dereje v. State', 'https://www.courtlistener.com/opinion/8281224/', '8281224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of these reasons, we conclude that Dereje did not receive ineffective assistance of counsel.', 'ineffective_assistance', 'Dereje v. State', 'https://www.courtlistener.com/opinion/8281224/', '8281224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2, and that he received effective assistance of counsel, we reverse the decision of the court of appeals and remand to the district court to reinstate Dereje’s judgment of conviction and sentence.', 'sentencing', 'Dereje v. State', 'https://www.courtlistener.com/opinion/8281224/', '8281224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2, and he received effective assistance of counsel, we reverse the court of appeals and reinstate Dereje’s judgment of conviction and sentence.', 'sentencing', 'Dereje v. State', 'https://www.courtlistener.com/opinion/8281224/', '8281224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm in part and reverse in part the judgment of the appellate court.', 'general', 'People v. Thurow', 'https://www.courtlistener.com/opinion/2029848/', '2029848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the appellate court’s judgment that defendant’s enhanced sentence was imposed in error, but reverse the appellate court’s vacating of the sentence and remandment for a new sentencing hearing.', 'sentencing', 'People v. Thurow', 'https://www.courtlistener.com/opinion/2029848/', '2029848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that denying to committed same-sex couples the financial and social benefits and privileges given to their married heterosexual counterparts bears no substantial relationship to a legitimate governmental purpose.', 'general', 'Lewis v. Harris', 'https://www.courtlistener.com/opinion/1551161/', '1551161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained, we affirm in part and modify in part the judgment of the Appellate Division.', 'general', 'Lewis v. Harris', 'https://www.courtlistener.com/opinion/1551161/', '1551161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find these cases persuasive, and we hold that when the argument is raised that MCL 750.', 'general', 'Buchanan v. Crisler', 'https://www.courtlistener.com/opinion/8286341/', '8286341') ON CONFLICT DO NOTHING;
