INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court erred by excluding Zovak''s testimony under Rule 411 for the following reasons.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon Ritchie , we hold that the circuit court erred by failing to review the DHS file to determine whether it contains information that was material to Taffner''s defense.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did not.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The circuit court erred by not allowing Zovak''s testimony, but we conclude that there was no prejudice.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the circuit court erred with respect to the DHS file, we must determine the appropriate remedy.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and remand for further proceedings.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we affirm the circuit court''s rulings denying Taffner''s motions for a directed verdict and for a new trial.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that there was no prejudice in its exclusion.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Ritchie''s interest (as well as that of the Commonwealth) in ensuring a fair trial can be protected fully by requiring that the CYS files be submitted only to the trial court for in camera review.', 'general', 'Taffner v. State', 'https://www.courtlistener.com/opinion/6241086/', '6241086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Whetstone', 'https://www.courtlistener.com/opinion/8326099/', '8326099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In upholding the decision of the family court, we noted that while the razor blade was not a per se violation of the statute because it was not a knife with a blade longer than two inches, we held that it was an object that could be used to inflict bodily injury or death.', 'general', 'In re Thomas Edward D.', 'https://www.courtlistener.com/opinion/8326389/', '8326389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In re Thomas Edward D.', 'https://www.courtlistener.com/opinion/8326389/', '8326389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/8326942/', '8326942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Gilliland', 'https://www.courtlistener.com/opinion/8327357/', '8327357') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding Gilliland has failed to demonstrate error, we affirm.', 'general', 'State v. Gilliland', 'https://www.courtlistener.com/opinion/8327357/', '8327357') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial court’s denial of Gilliland’s motion for a directed verdict.', 'general', 'State v. Gilliland', 'https://www.courtlistener.com/opinion/8327357/', '8327357') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Middleton', 'https://www.courtlistener.com/opinion/8327652/', '8327652') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Whatley', 'https://www.courtlistener.com/opinion/8327665/', '8327665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, this Court held in a series of decisions that local governments did not possess the authority to ban such cruises because the plain language of the Johnson Act indicated that only a state, not a political subdivision of a state, could prohibit those cruises, and our General Assembly had elected not to enact a statute prohibiting the “cruises to nowhere.', 'general', 'Catawba Indian Nation v. State', 'https://www.courtlistener.com/opinion/8327673/', '8327673') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Catawba Indian Nation v. State', 'https://www.courtlistener.com/opinion/8327673/', '8327673') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, however, the circuit court’s determination that the Gambling Cruise Act does not authorize the Tribe to offer video poker on its Reservation in contravention of the existing statewide ban on video gambling devices.', 'general', 'Catawba Indian Nation v. State', 'https://www.courtlistener.com/opinion/8327673/', '8327673') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Douglas', 'https://www.courtlistener.com/opinion/8327838/', '8327838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the circuit court’s order granting Respondent immunity from prosecution.', 'general', 'State v. Douglas', 'https://www.courtlistener.com/opinion/8327838/', '8327838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find these errors prejudiced King as to his conviction for attempted murder, we reverse and remand for a new trial.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8327890/', '8327890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find the court’s errors caused King no prejudice as to his convictions for armed robbery and possession of a firearm during the commission of a violent crime, and we affirm those convictions.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8327890/', '8327890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because King failed to demonstrate prejudice from the trial court’s errors as to those convictions, we affirm.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8327890/', '8327890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as to King’s remaining issues pursuant to Rule 220(b), SCACR, and the following authorities:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm King’s convictions for armed robbery and possession of a firearm.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8327890/', '8327890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the record, as well as the relevant authority, we hold that Cradock is a public employee.', 'general', 'State v. Bailey', 'https://www.courtlistener.com/opinion/8328064/', '8328064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Bailey', 'https://www.courtlistener.com/opinion/8328064/', '8328064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because the circuit court erred in concluding Cradock was a public official for purposes of subsection 16-3-1040(A), we reverse Bailey’s conviction.', 'general', 'State v. Bailey', 'https://www.courtlistener.com/opinion/8328064/', '8328064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a trial on the merits of Huffman’s false imprisonment and malicious prosecution claims.', 'general', 'Huffman v. Sunshine Recycling, LLC', 'https://www.courtlistener.com/opinion/8328175/', '8328175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse summary judgment for Respondents on Huffman’s false imprisonment claim.', 'general', 'Huffman v. Sunshine Recycling, LLC', 'https://www.courtlistener.com/opinion/8328175/', '8328175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we reverse summary judgment for Respondents on Huffman’s malicious prosecution claim.', 'general', 'Huffman v. Sunshine Recycling, LLC', 'https://www.courtlistener.com/opinion/8328175/', '8328175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because this evidence should have gone to the jury, we reverse the *533circuit court’s order and remand for a trial on the merits of Huffman’s false imprisonment and malicious prosecution claims.', 'general', 'Huffman v. Sunshine Recycling, LLC', 'https://www.courtlistener.com/opinion/8328175/', '8328175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Appellant’s murder conviction.', 'general', 'State v. Westmoreland', 'https://www.courtlistener.com/opinion/8328334/', '8328334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Appellant’s murder conviction because the error was not harmless for that conviction.', 'general', 'State v. Westmoreland', 'https://www.courtlistener.com/opinion/8328334/', '8328334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse Appellant’s murder conviction because the error was not harmless and could have contributed to the verdict.', 'general', 'State v. Westmoreland', 'https://www.courtlistener.com/opinion/8328334/', '8328334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Appellant’s conviction for hit and run and reverse his murder conviction.', 'general', 'State v. Westmoreland', 'https://www.courtlistener.com/opinion/8328334/', '8328334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm this conviction.', 'general', 'State v. Westmoreland', 'https://www.courtlistener.com/opinion/8328334/', '8328334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, the error was harmless as to Appellant’s conviction for hit and run, and we affirm that conviction.', 'general', 'State v. Westmoreland', 'https://www.courtlistener.com/opinion/8328334/', '8328334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the trial court’s jury instructions.', 'jury_instruction', 'State v. Westmoreland', 'https://www.courtlistener.com/opinion/8328334/', '8328334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Appellant’s conviction for hit and run because the trial court’s error was harmless as to that conviction.', 'general', 'State v. Westmoreland', 'https://www.courtlistener.com/opinion/8328334/', '8328334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in keeping with the McCaffrey rule and the approach taken by many jurisdictions, we hold that the bona fide use and other subsection (b) exemptions are ordinary defenses, for which the defendant has the burden of production and the State has the burden of persuasion.', 'general', 'Fraser v. Sleeper', 'https://www.courtlistener.com/opinion/8345110/', '8345110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The McCaffrey rule has been explicitly followed several times since, most recently in 1989 when we held that defendants bore the burden of proving that their alleged offenses were committed in “Indian country” and therefore outside of Vermont jurisdiction.', 'general', 'Fraser v. Sleeper', 'https://www.courtlistener.com/opinion/8345110/', '8345110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is not in this case and therefore affirm.', 'general', 'Fraser v. Sleeper', 'https://www.courtlistener.com/opinion/8345110/', '8345110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, despite those potential evidentiary obstacles, a convicted offender should be given the opportunity through a declaratory judgment action, such as the present case, to meet the burden of production of one or more exemptions to the Vermont statute.', 'general', 'Fraser v. Sleeper', 'https://www.courtlistener.com/opinion/8345110/', '8345110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that the instruction was plain error, and that the evidence below could not support a conviction for violating the abuse-prevention order, as worded.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/8345167/', '8345167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in the absence of any elaboration in the RFA order regarding the intended definition of “harassment” or the type of conduct prohibited, the most appropriate touchstone for defining the term in the context of a VAPO prosecution is the definition in Vermont’s stalking statute.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/8345167/', '8345167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court’s instruction was erroneous.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/8345167/', '8345167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, given the considerations outlined above, including the wide range of legal and everyday uses of the *246term and the due-process-infused rule of lenity, we conclude that the instruction that allowed the jury to convict defendant on the basis of objectively annoying conduct was clearly error.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/8345167/', '8345167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If the jury instructions had defined harassment consistent with the default definition identified above — one that requires an element of threat — we conclude that the jury could not have convicted defendant on this evidence.', 'jury_instruction', 'State v. Waters', 'https://www.courtlistener.com/opinion/8345167/', '8345167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that we conclude that a jury instructed about the definition of “harassment” in the RFA order in a way that is consistent with this opinion could not convict defendant of violating the abuse-prevention order on the basis of the evidence presented below, convicting defendant of a felony on the basis of an overly broad instruction would undermine the fairness of the judicial process.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/8345167/', '8345167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these factors, we concluded that the case was not appropriate for interlocutory review.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/8345167/', '8345167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that “the court’s broad definition of harassment permitted defendant to be convicted on the basis of virtually any behavior that bothered the complainant,” we reversed the conviction.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/8345167/', '8345167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 685 (1996), this Court held that,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The short answer to this argument is that Berry does not require that we hold that Code § 19.', 'general', 'Washington v. Commonwealth', 'https://www.courtlistener.com/opinion/6934164/', '6934164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '32, we find that under the facts of this case, the 2003 conviction could not have been a basis for the conviction as a matter of law.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" After a review of the record, we find that the trial court''s judgment of acquittal was proper, because we do not believe that the State proved beyond a reasonable doubt that Lightner committed the theft offense in count one, the receiving stolen property offenses in counts four, eight and nine, and the grand theft of a motor vehicle in counts five and seven.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record is devoid of any testimony or evidence relating to the theft offense on March 11, 2007.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '28} Likewise, we find that there was insufficient evidence to support the predicate acts in counts five and seven.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, there was no difference between counts seven and six, and because the jury returned a not guilty verdict as to count six, we find that there was insufficient evidence to support the same predicate act in count seven.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '30} Thus, as to counts five and seven, we find that there was not sufficient evidence presented to the jury for them to have relied on those as underlining predicate acts.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury only found Lightner guilty as to receiving stolen property as it related to only one of the ATVs, we find that there was insufficient evidence upon which the jury could have convicted Lightner of engaging in a pattern of corrupt activity.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '43} Thus, after a review of the record and construing the evidence in light of the prosecution, we find that there was sufficient evidence to show that Lightner had at least reason to believe, if not knew, that at least one of the ATVs had been obtained through the commission of a theft offense.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse in part and affirm in part.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '45} Having found error prejudicial to the appellant herein as to appellant''s first assignment of error in the particulars assigned and argued, we reverse the judgment of the trial court as to appellant''s first assignment of error and remand for further proceedings consistent with this opinion.', 'general', 'State v. Lightner, 6-08-11 (2-9-2009)', 'https://www.courtlistener.com/opinion/3945021/', '3945021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the doctrine of transferred intent may be used to convict a defendant of [assault and battery with intent to kill] when the defendant kills the intended victim and also injures an unintended victim.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/7478898/', '7478898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the candid and compelling nature of the foregoing evidence, we conclude that beyond any reasonable doubt, the felony murder rule instruction made no contribution to the verdict and any error in giving it was harmless.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/7478898/', '7478898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/7478898/', '7478898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the denial of Appellant''s directed verdict motion.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/7478898/', '7478898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellant''s attempted murder conviction.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/7478898/', '7478898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that by omitting the "no duty to retreat" provision, the trial court''s jury instructions constituted preserved error.', 'jury_instruction', 'State v. Moss', 'https://www.courtlistener.com/opinion/7479460/', '7479460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it did.', 'general', 'State v. Moss', 'https://www.courtlistener.com/opinion/7479460/', '7479460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the trial court on this issue and remand this case to the trial court for a new trial with proper instructions on self-defense and no duty to retreat.', 'general', 'State v. Moss', 'https://www.courtlistener.com/opinion/7479460/', '7479460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the trial court in part, find no error in part, vacate Defendant''s conviction, and remand the case for further proceedings.', 'general', 'State v. Moss', 'https://www.courtlistener.com/opinion/7479460/', '7479460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the admission of Officer Sem-mel’s testimony relating the testimonial statements of the non-appearing eyewitness violated defendant’s Sixth Amendment right to confront the witnesses against him.', 'general', 'State ex rel. J.A.', 'https://www.courtlistener.com/opinion/7409048/', '7409048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*340We conclude that the non-appearing witness’s statements relating the details of a robbery that occurred ten minutes earlier is not the equivalent of describing the crime “immediately after” it occurred.', 'general', 'State ex rel. J.A.', 'https://www.courtlistener.com/opinion/7409048/', '7409048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the non-appearing eyewitness’s statements to Officer Semmel about the robbery were testimonial.', 'general', 'State ex rel. J.A.', 'https://www.courtlistener.com/opinion/7409048/', '7409048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not decide that issue, however, because we find that defendant did not have a prior opportunity to cross-examine the non-appearing witness whose statements were clearly testimonial.', 'general', 'State ex rel. J.A.', 'https://www.courtlistener.com/opinion/7409048/', '7409048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the family court abused its discretion by admitting the witness’s statements under the present sense impression exception to the hearsay rule.', 'general', 'State ex rel. J.A.', 'https://www.courtlistener.com/opinion/7409048/', '7409048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was sufficient credible evidence for the trial court to conclude that defendant was misinformed by counsel and that defendant would not have pled guilty if he had received accurate information that his plea would result in deportation.', 'plea', 'State v. Nuñez-Valdéz', 'https://www.courtlistener.com/opinion/7409126/', '7409126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 336 (1987), in which we held that the federal standard for evaluating an ineffective-assistanee-of-eounsel claim approved in Strickland, supra, 466 U.', 'ineffective_assistance', 'State v. Nuñez-Valdéz', 'https://www.courtlistener.com/opinion/7409126/', '7409126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the required deferential standard, we conclude that there was sufficient credible evidence in the record to support the trial court’s findings.', 'general', 'State v. Nuñez-Valdéz', 'https://www.courtlistener.com/opinion/7409126/', '7409126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Appellate Division and reinstate the trial court’s order that directed withdrawal of defendant’s plea and reinstatement of the matter for trial.', 'plea', 'State v. Nuñez-Valdéz', 'https://www.courtlistener.com/opinion/7409126/', '7409126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that a non-testifying witness’s statement to the police, recounting a robbery and the flight of the perpetrators that occurred several minutes before the witness gave the statement, was clearly testimonial and therefore inadmissible because defendant “did not have a prior opportunity to cross-examine [him].', 'general', 'State v. Basil', 'https://www.courtlistener.com/opinion/7409201/', '7409201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the on-scene identification by a citizen informant and corroborative discovery of the shotgun gave the officers probable cause to arrest defendant, and therefore defendant’s volunteered statement should not have been suppressed as the product of an unlawful arrest.', 'suppression', 'State v. Basil', 'https://www.courtlistener.com/opinion/7409201/', '7409201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under both the Fourth Amendment and Article I, Paragraph 7 of our State Constitution, the police had probable cause to arrest defendant, and therefore defendant’s alleged spontaneous admission to Officer Ruocco did not occur during an unlawful seizure.', 'probable_cause', 'State v. Basil', 'https://www.courtlistener.com/opinion/7409201/', '7409201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the non-testifying witness’s statement implicating defendant was testimonial, that is, the statement was the equivalent of bearing witness against defendant.', 'general', 'State v. Basil', 'https://www.courtlistener.com/opinion/7409201/', '7409201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the non-appearing witness’s testimonial statement was inadmissible.', 'general', 'State v. Basil', 'https://www.courtlistener.com/opinion/7409201/', '7409201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we reverse the part of the judgment of the Appellate Division that suppressed defendant’s verbal admission to the police on the ground that defendant was arrested without probable cause.', 'suppression', 'State v. Basil', 'https://www.courtlistener.com/opinion/7409201/', '7409201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it may not and thus affirm the judgment of the Appellate Division.', 'general', 'State v. Schubert', 'https://www.courtlistener.com/opinion/7409457/', '7409457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, this Court held that convictions for multiple offenses on the same day constituted a single conviction on "separate occasions” for *68purposes of NJ.', 'general', 'In re J.S.', 'https://www.courtlistener.com/opinion/7410629/', '7410629') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, as it is currently drafted, N.', 'general', 'In re J.S.', 'https://www.courtlistener.com/opinion/7410629/', '7410629') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Appellate Division’s decisions in both appeals.', 'general', 'In re J.S.', 'https://www.courtlistener.com/opinion/7410629/', '7410629') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the Appellate Division and trial court drew different inferences from the record, we conclude that the inferences drawn by the trial court were reasonable and that the trial court’s ultimate determination was not clearly mistaken.', 'general', 'State v. S.S.', 'https://www.courtlistener.com/opinion/7412006/', '7412006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we find that the trial court’s factual determination, based solely on its review of the video-recorded interrogation, is supported by sufficient credible evidence in the record.', 'general', 'State v. S.S.', 'https://www.courtlistener.com/opinion/7412006/', '7412006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*386Having reviewed the video-recorded interrogation in light of the nature and history of the case, we find that the trial court’s factual conclusions are supported by sufficient credible evidence in the record and therefore are not clearly mistaken.', 'general', 'State v. S.S.', 'https://www.courtlistener.com/opinion/7412006/', '7412006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that sufficient credible evidence in the record supports the trial court’s factual finding that defendant invoked his right to silence during the interrogation.', 'general', 'State v. S.S.', 'https://www.courtlistener.com/opinion/7412006/', '7412006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed, we reverse the judgment of the Appellate Division.', 'general', 'State v. S.S.', 'https://www.courtlistener.com/opinion/7412006/', '7412006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the interrogating investigators failed to honor defendant’s invocation of his right to silence or, at the very least, to seek clarification if they thought that defendant’s statements were ambiguous, we affirm the trial court’s suppression order.', 'suppression', 'State v. S.S.', 'https://www.courtlistener.com/opinion/7412006/', '7412006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Scott , this court held a defendant''s 1977 robbery conviction was not too remote to be used to impeach her because, although she received parole in 1980, her sentence was still in effect until 1986.', 'sentencing', 'State v. Shands', 'https://www.courtlistener.com/opinion/7478650/', '7478650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Shands''s convictions for first-degree burglary, kidnapping, first-degree assault and battery, and possession of a weapon during the commission of a violent crime, and we reverse his conviction for attempted murder.', 'general', 'State v. Shands', 'https://www.courtlistener.com/opinion/7478650/', '7478650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'State v. Shands', 'https://www.courtlistener.com/opinion/7478650/', '7478650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We affirm.', 'general', 'State v. Shands', 'https://www.courtlistener.com/opinion/7478650/', '7478650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s denial of Shands''s motion to quash because Shands did not present clear evidence that there was an abuse of the grand jury proceedings in his case.', 'general', 'State v. Shands', 'https://www.courtlistener.com/opinion/7478650/', '7478650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '9 However, we find the trial court''s error caused Shands no prejudice as to his convictions for first-degree burglary, kidnapping, first-degree assault and battery, and possession of a weapon during the commission of a violent crime, and we affirm those convictions.', 'general', 'State v. Shands', 'https://www.courtlistener.com/opinion/7478650/', '7478650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial court''s denial of Shands''s motion for a directed verdict on the kidnapping charge.', 'general', 'State v. Shands', 'https://www.courtlistener.com/opinion/7478650/', '7478650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State appeals, and for the reasons that follow, we reverse.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/7479802/', '7479802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the dismissal of the indictment and remand the case for further proceedings consistent with this opinion.', 'dismissal', 'State v. Williams', 'https://www.courtlistener.com/opinion/7479802/', '7479802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 For the reasons that follow, we reverse the trial court''s dismissal of the indictment in Case Number S19A0209, and we affirm the exclusion of seatbelt-use evidence in Case Number S19X0210, albeit for reasons different from those that the trial court gave.', 'dismissal', 'State v. Mondor', 'https://www.courtlistener.com/opinion/7479879/', '7479879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained below, we affirm the trial court''s order excluding evidence of seatbelt-use evidence in this case, albeit on different grounds than the trial court''s reasoning.', 'general', 'State v. Mondor', 'https://www.courtlistener.com/opinion/7479879/', '7479879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, because we affirm the trial court''s evidentiary finding, we need not reach Mondor''s argument that OCGA § 40-8-76.', 'general', 'State v. Mondor', 'https://www.courtlistener.com/opinion/7479879/', '7479879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that evidence of a victim''s failure to wear a seatbelt generally is not relevant evidence of causation in criminal cases.', 'general', 'State v. Mondor', 'https://www.courtlistener.com/opinion/7479879/', '7479879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2002) (“In view of the historical endorsement of a right to intrastate travel and the practical necessity of such a right, we hold that the Constitution protects a right to travel locally through public spaces and roadways.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, accepting the dissent’s analysis would require the Court to recede from its precedent of only three years ago, in which we held that the strict scrutiny standard is applicable when reviewing juvenile curfew ordinances.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', this Court held that strict scrutiny should be applied when reviewing a juvenile curfew ordinance and answered the first certified question accordingly.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding these constitutionally protected First Amendment rights, we conclude that the ordinances at issue here do not implicate the juveniles’ rights to free speech and assembly as these activities are specifically exempted from their ambit.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the Florida Constitution’s explicit privacy provision and the Florida case law recognizing that this right encompasses family privacy, we conclude that the ordinances may implicate the parental right to raise children.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the penalty provisions of the instant ordinances do not meet strict scrutiny.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the problems discussed above, we conclude that the Tampa and Pinellas Park juvenile curfew ordinances are not narrowly tailored and thus fail to survive strict scrutiny.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[juvenile curfew ordinance] as an attempt to usurp the parental functions, and as unreasonable, and we therefore hold the ordinance in question as illegal and void.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), for example, we held that although the right to privacy protected the private enjoyment of obscene material in one’s home, there was no legitimate reasonable expectation of privacy in being able to publicly purchase such material.', 'general', 'State v. J.P.', 'https://www.courtlistener.com/opinion/7834384/', '7834384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Allbee', 'https://www.courtlistener.com/opinion/1355739/', '1355739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Poole [444 Mich at 161], this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that even without Bennett’s statements, there was legally sufficient evidence for a “person of ordinary caution and prudence” to have a reasonable belief that Benson committed the crime of murdering the victim.', 'general', 'People v. Bennett', 'https://www.courtlistener.com/opinion/8006358/', '8006358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, the prosecutor’s argument to Benson’s jury was largely the same as her argument to Bennett’s jury, and we conclude that she was not bolstering Toth’s testimony or intimating to the jury that she had special knowledge regarding Toth’s investigations.', 'general', 'People v. Bennett', 'https://www.courtlistener.com/opinion/8006358/', '8006358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, even if we concluded that the evidence established that Bennett may have been reluctant to have Benson kill the victim, that evidence does not negate the critical element of Bennett’s knowledge of Benson’s specific intent to kill the victim.', 'general', 'People v. Bennett', 'https://www.courtlistener.com/opinion/8006358/', '8006358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that there was sufficient evidence from which the jury could conclude that Bennett was guilty of first-degree murder on a theory of aiding and abetting.', 'general', 'People v. Bennett', 'https://www.courtlistener.com/opinion/8006358/', '8006358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth in this opinion, we affirm.', 'general', 'People v. Bennett', 'https://www.courtlistener.com/opinion/8006358/', '8006358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and sentence of defendant Paula Renai Bennett.', 'sentencing', 'People v. Bennett', 'https://www.courtlistener.com/opinion/8006358/', '8006358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and sentences of defendant Kyron Darell Benson.', 'sentencing', 'People v. Bennett', 'https://www.courtlistener.com/opinion/8006358/', '8006358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), we held that the harmless-error standard does not apply to an erroneous omission of an element of the charged offense from a jury instruction, thereby implicitly rejecting the reasoning of Neder.', 'jury_instruction', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court of appeals misconstrued existing case law when it held that, as a matter of law, the failure to instruct on an element of the charged offense affects a defendant’s substantial rights.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the record, we conclude that the failure to instruct on the “knowingly” element of the charged offense was trial error that affected Watkins’ substantial rights.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the error is subject to review as a trial error, not as a structural error.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure to instruct the jury on an element of the charged offense is subject to review as a trial error, not as a structural error.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed below, we conclude that the court of appeals misconstrued our decisions in Mahkuk and Hall.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the omission of the “knowingly” element was prejudicial and affected Watkins’ substantial rights.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the specific facts of this case, we conclude that allowing the jury to consider Watkins’ defense will protect the fairness, integrity, and public reputation of judicial proceedings.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon an examination of the record, we conclude that the omission of the “knowingly” element of the charged offense affected Watkins’ substantial rights, and that a new trial is required to ensure the fairness, integrity, and public reputation of judicial proceedings.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that a knowing violation is a question of fact for the jury.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/8281259/', '8281259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record before the Court, we conclude that CSAAS does not satisfy a basic standard of admissibility -- reliability -- because it is not generally accepted by the scientific community.', 'general', 'State v. J.L.G.', 'https://www.courtlistener.com/opinion/8264164/', '8264164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we find that the expert testimony about CSAAS introduced at trial was harmless, and we affirm defendant''s convictions.', 'general', 'State v. J.L.G.', 'https://www.courtlistener.com/opinion/8264164/', '8264164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of those reasons, we find that the admission of the CSAAS evidence in this case was harmless.', 'general', 'State v. J.L.G.', 'https://www.courtlistener.com/opinion/8264164/', '8264164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that expert testimony about CSAAS in general, and its component behaviors other than delayed disclosure, may no longer be admitted at criminal trials.', 'general', 'State v. J.L.G.', 'https://www.courtlistener.com/opinion/8264164/', '8264164') ON CONFLICT DO NOTHING;
