INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'revocation statutes in favor of the defendant, Carter, supra, we hold that the arrest warrant
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 We find that the remaining sentencing order under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and dismiss the sentencing order entered in case number 10-1265 on
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court''s dismissal order and remand for further proceedings consistent with this opinion.', 'dismissal', 'State v. Espinoza', 'https://www.courtlistener.com/opinion/7701575/', '7701575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, based on the foregoing, we reverse the trial court''s order granting Espinoza''s motion to dismiss the information and remand for further proceedings consistent with this opinion.', 'dismissal', 'State v. Espinoza', 'https://www.courtlistener.com/opinion/7701575/', '7701575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the government meets its burden by showing that the consenting party cooperated “knowing what the law enforcement officers were about.', 'general', 'United States v. Sell', 'https://www.courtlistener.com/opinion/5128027/', '5128027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge applied the correct standard and turn, finally, to review his ultimate conclusion.', 'general', 'United States v. Sell', 'https://www.courtlistener.com/opinion/5128027/', '5128027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For several reasons we conclude that the trial judge''s assessment is without substantia] support in the record and must be reversed.', 'general', 'United States v. Sell', 'https://www.courtlistener.com/opinion/5128027/', '5128027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the trial court’s finding was plainly wrong.', 'general', 'United States v. Sell', 'https://www.courtlistener.com/opinion/5128027/', '5128027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'United States v. Sell', 'https://www.courtlistener.com/opinion/5128027/', '5128027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Eddington v. Torrez', 'https://www.courtlistener.com/opinion/2811144/', '2811144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/8327331/', '8327331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the instructions were sufficient to eliminate the potential “spillover” effect resulting from the joint trial.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the jury foreman’s responses to questioning, we find that the trial judge’s finding that his ability to render an impartial verdict had not been compromised does not amount to an abuse of discretion.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we noted above with regard to Brooks and Sanders, we find that the testimony regarding the Irons incident, coupled with evidence of Skinner’s involvement in the Grinage and Yates robberies and his presence in the area during the period of time when the shooting occurred, could lead a jury to infer that he was involved in the attempted robbery.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in this case we find that the prosecution’s failure to disclose Skinner’s statement was harmless error as to defendants Brooks and Sanders, even though that failure was a clear violation of Rule 16.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that test to this case as to defendants Brooks and Sanders, we find that significant evidence, independent of Skinner’s statement, was before the jury to support a conclusion that a robbery was to be perpetrated at the Irons residence.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since other sufficient, independent evidence was available to the jury through the testimony of various witnesses, we find that Skinner’s statement was not central to the State’s case against Brooks and Sanders.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In applying the Hughes analysis to Skinner’s case, however, we find that the violation of Superior Court Criminal Rule 16 and the introduction of Skinner’s statement into evidence is reversible error.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that such a delay in disclosure prejudiced Skinner in his defense.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the convictions of Skinner as to attempted robbery, one count of possession of a deadly weapon during the commission of a felony, one count of conspiracy in the second degree, and felony murder arising out of the Irons incident, and we remand those charges to Superior Court for a new trial.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the Superior Court and find no abuse of discretion in its ruling which found no violation of defendants’ right to a speedy trial.', 'general', 'Skinner v. State', 'https://www.courtlistener.com/opinion/5129606/', '5129606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But because we held that Webber did not announce a deferential rule, there was nothing to overrule.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/8281743/', '8281743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court of appeals correctly applied the law and we decline the invitation to overrule our precedent.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/8281743/', '8281743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because we conclude that, when viewed as a whole, there are rational hypotheses other than guilt consistent with the circumstances proved, we need not address the impact, if any, of Harris''s attempt to reframe his earlier concession.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/8281743/', '8281743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “our decision in Webber was not intended to, nor did it, announce a rule of deference to district court pretrial legal conclusions that the State has appealed,” Id.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/8281743/', '8281743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the court of appeals.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/8281743/', '8281743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 937, by its plain language, does not set forth a substantive offense.', 'general', 'People v. Pinkney', 'https://www.courtlistener.com/opinion/8283904/', '8283904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that § 937 does not create a substantive offense, we do not reach defendant''s argument that the trial court improperly admitted other-acts evidence under MRE 404(b).', 'general', 'People v. Pinkney', 'https://www.courtlistener.com/opinion/8283904/', '8283904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, because we hold that § 937 unambiguously sets forth a penalty provision and not a substantive offense, we do not reach defendant''s additional arguments that the rule of lenity precludes enforcement of § 937 against defendant or that § 937 is void for vagueness.', 'general', 'People v. Pinkney', 'https://www.courtlistener.com/opinion/8283904/', '8283904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After focusing on the plain language, context, and history of § 937, we conclude that it is nothing more than an inoperative penalty provision.', 'general', 'People v. Pinkney', 'https://www.courtlistener.com/opinion/8283904/', '8283904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant cannot be convicted under a statute that does not set forth a crime, we reverse and remand for further proceedings not inconsistent with this opinion.', 'general', 'People v. Pinkney', 'https://www.courtlistener.com/opinion/8283904/', '8283904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals'' holding to the contrary and remand to the trial court for further proceedings not inconsistent with this *551opinion.', 'general', 'People v. Pinkney', 'https://www.courtlistener.com/opinion/8283904/', '8283904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Then, we reversed the Court of Appeals, holding that the prosecutor had discretion to charge the defendant under both § 937 and § 544c.', 'general', 'People v. Pinkney', 'https://www.courtlistener.com/opinion/8283904/', '8283904') ON CONFLICT DO NOTHING;
