INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the facts of this case, as developed in the trial record, do not support a passion/provocation finding under N.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court’s decision to charge the jury regarding passion/provocation lacked the required foundation in the trial evidence.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the verdict sheet in this case contained an error, but on the record of this ease, that error was incapable of producing an unjust result.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Tracing the history of passion/provocation as a component of New Jersey homicide law, we held that the unavailability of passion/provocation mitigation in manslaughter cases did not reflect a legislative oversight, as the defendant in Grunow suggested.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that the limitation of passion/provocation to murder represented a legislative determination intended to balance “the subjective ranges of criminal responsibility” advocated by the Criminal Law Revision Commission and “the Legislature’s desire to return to objective levels of responsibility” that were part of New Jersey’s common law.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 256 (2010), we held that the omission of one of several elements in the crime of stalking constituted harmless error, where the jury charge correctly listed all of the elements and the trial court “stressed the importance of his oral instructions over the content of the verdict sheet.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that *385there was no such “rational basis” for charging passion/provocation in the evidence presented to the jury.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that having downgraded a crime committed with recklessness manifesting “extreme indifference to human life” from murder to man*381slaughter, the Legislature could plausibly determine that passion/provocation should not be available to mitigate that crime.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the error in the verdict sheet was harmless, and did not deprive defendant of a fair trial.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 951, we reversed the defendants’ convictions on the basis of erroneous instructions directing the jury not to *388consider passion/provocation under N.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McCurrie, when the Town took a position before this Court “entirely contrary to its position in the trial court,” we held that the Town’s “about-face [was] a blatant violation of the principle of judicial estoppel.', 'general', 'State v. Galicia', 'https://www.courtlistener.com/opinion/7409367/', '7409367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Cagno', 'https://www.courtlistener.com/opinion/7409408/', '7409408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bums, we held that a trial court must instruct the jury not to draw any inferences, for or against a defendant, even when a witness’s refusal to testify is not justified by any privilege.', 'general', 'State v. Cagno', 'https://www.courtlistener.com/opinion/7409408/', '7409408') ON CONFLICT DO NOTHING;
