INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the PPO''s expiration alone does not render the appeal moot, and we remand to the Court of Appeals for further proceedings.', 'general', 'T.M. v. M.Z.', 'https://www.courtlistener.com/opinion/8284761/', '8284761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Appellant''s counsel conceded at oral argument that the only available relief is a notation in LEIN that the PPO has been rescinded, and we hold that this is enough to avoid concluding that the case is moot.', 'general', 'T.M. v. M.Z.', 'https://www.courtlistener.com/opinion/8284761/', '8284761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that identifying an improperly issued PPO as rescinded is a live controversy and thus not moot.', 'general', 'T.M. v. M.Z.', 'https://www.courtlistener.com/opinion/8284761/', '8284761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '23 In rejecting the plaintiff''s argument that the ordinance was void because it exceeded the powers granted by the act, we held that the dissent''s position was "based on the erroneous assumption that the legislature, in making it unlawful to water ski from 1 hour after sundown to 1 hour before sunrise, was expressing a lawful right to water ski without regulation during the other hours of the day.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the statute and ordinance conflicted.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '32 We held that the ordinance was preempted.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '677 (1940), in which this Court held that when a criminal statute creates an exception to a penalty, this logically permits an individual to engage in the conduct that is the subject of the exception.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the ordinance "attempts to prohibit that which the statute permits and is, therefore, void.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '342 (1935), in which this Court held that where the Legislature makes conduct *776unlawful unless certain conditions are satisfied, the Legislature has logically made the conduct lawful when those conditions have been satisfied.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the Grand Rapids ordinance "attempts to prohibit what the statute permits .', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the ordinance did not conflict with the statute because the statute was silent regarding how many pounds of fireworks a retailer could store.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"24 We could discern no such intent from our review of the statute, and consequently we concluded that the ordinance and the statute did not conflict.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Llewellyn , no statute expressly stated the Legislature''s intent to preempt local obscenity regulation, but we found that the state''s comprehensive coverage of the field impliedly revealed the Legislature''s intent to occupy the field.', 'general', 'Mich. Gun Owners, Inc. v. Ann Arbor Pub. Sch.', 'https://www.courtlistener.com/opinion/8285292/', '8285292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute''s words "manifest[ ] a clear meaning," and therefore, "our inquiry ceases and we will apply that meaning.', 'general', 'State v. Stewart', 'https://www.courtlistener.com/opinion/8284739/', '8284739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that the defendants'' conduct forms the basis for two different offenses under two different statutory provisions and that .', 'general', 'State v. Stewart', 'https://www.courtlistener.com/opinion/8284739/', '8284739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But based on the State''s stipulation, we reverse the part of the postconviction order (which affirmed the judgments "in toto ") pertaining to the child support.', 'general', 'State v. Stewart', 'https://www.courtlistener.com/opinion/8284739/', '8284739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments and order as modified.', 'general', 'State v. Stewart', 'https://www.courtlistener.com/opinion/8284739/', '8284739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We affirm the order in all respects except insofar as it affirmed judgments with the child support arrears designated as restitution.', 'general', 'State v. Stewart', 'https://www.courtlistener.com/opinion/8284739/', '8284739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a defendant like Pakhnyuk does not forfeit a sufficiency-of-the-evidence challenge that is based on a statutory interpretation argument when he fails to raise it in the district court.', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the legislative history and purpose of subdivision 1(a) support the conclusion that the intent requirement in clause (3) of subdivision 1(a) applies only to the peeping conduct described in clause (2), and not to the property-entry conduct in clause (1).', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the forfeiture rule does not apply to such a challenge.', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, after considering these principles, we conclude that the statute is " ''subject to more than one reasonable interpretation,'' " then it is ambiguous, and we "may apply canons of construction to resolve the ambiguity.', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After analyzing the statute''s text, structure, punctuation, and the parties'' grammatical arguments, we conclude that the intent requirement in subdivision 1(a) is subject to more than one reasonable interpretation and is therefore ambiguous.', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither of these grammatical rules resolves the ambiguity present in subdivision 1(a).', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, given the particular ambiguities arising from subdivision 1(a)''s text and structure, we conclude that it is "susceptible to more than one reasonable interpretation.', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that subdivision 1(a) is ambiguous.', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we find that the legislative history and purpose of subdivision 1(a) resolve the ambiguity in the State''s favor.', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals.', 'general', 'State v. Pakhnyuk', 'https://www.courtlistener.com/opinion/8287647/', '8287647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that the State''s position is correct.', 'general', 'State v. Jama', 'https://www.courtlistener.com/opinion/8286520/', '8286520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed Peery''s conviction, explaining that "[o]rdinary acts or conduct involving exposure of the person as the result of carelessness or thoughtlessness do not themselves establish the offense of indecent exposure.', 'general', 'State v. Jama', 'https://www.courtlistener.com/opinion/8286520/', '8286520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the indecent-exposure statute does not require the State to prove that the defendant had a specific intent to be lewd, we affirm.', 'general', 'State v. Jama', 'https://www.courtlistener.com/opinion/8286520/', '8286520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the court of appeals, but said that its analysis "partially misconstrues Peery .', 'general', 'State v. Jama', 'https://www.courtlistener.com/opinion/8286520/', '8286520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the court of appeals.', 'general', 'State v. Jama', 'https://www.courtlistener.com/opinion/8286520/', '8286520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, as will be discussed, we hold that a specific intent to kill is an element of attempted murder as codified in section 16-3-29.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8398325/', '8398325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, in contrast to the Court of Appeals, we hold that the trial judge erred in admitting the recording of King''s detention center **71phone call.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8398325/', '8398325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the legislative history as a whole, we conclude that section 16-3-29 is not a codification of the offense of ABWIK.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8398325/', '8398325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, like *28the Court of Appeals, we conclude that the error, if combined with the erroneous attempted murder jury instruction, was not harmless as to the attempted murder charge.', 'jury_instruction', 'State v. King', 'https://www.courtlistener.com/opinion/8398325/', '8398325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that this error does not warrant reversal of all convictions as advocated by King.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8398325/', '8398325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the admission of the recording does not warrant reversal of King''s convictions for armed robbery and possession of a firearm during the commission of a violent crime.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8398325/', '8398325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons that will be discussed, we affirm as modified.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8398325/', '8398325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm the decision of the Court of Appeals regarding the requisite mens rea for attempted murder, we decline to address King''s additional sustaining ground.', 'general', 'State v. King', 'https://www.courtlistener.com/opinion/8398325/', '8398325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We affirm.', 'general', 'State v. Brandenburg', 'https://www.courtlistener.com/opinion/8328255/', '8328255') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/8328295/', '8328295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the denial of Appellants’ respective directed verdict motions on the HCA charge.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/8328295/', '8328295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the denial of Appellants’ directed verdict motions on the unlawful conduct charges.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/8328295/', '8328295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm the trial court’s admission of the challenged photographs pursuant to Rule 403.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/8328295/', '8328295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellants’ respective convictions for HCA and unlawful conduct toward a child.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/8328295/', '8328295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*288IT IS ORDERED that respondent’s license to practice law in this state is suspended until further order of the Court.', 'general', 'In re Gay', 'https://www.courtlistener.com/opinion/8327071/', '8327071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the penalty provision of section 56-5-1210 is not grossly disproportionate to the offense, and no further review is necessary.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/8327347/', '8327347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that his sentence is significantly disproportionate to his crime, and is therefore prohibited by the Eighth Amendment.', 'sentencing', 'State v. Harrison', 'https://www.courtlistener.com/opinion/8327347/', '8327347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992) (“We conclude that *299Justice Kennedy’s view that the eighth amendment ‘forbids only extreme sentences that are grossly disproportionate to the crime’ is the rule of Harmelin.', 'sentencing', 'State v. Harrison', 'https://www.courtlistener.com/opinion/8327347/', '8327347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the foregoing authority demonstrates the proper articulation of proportionality review as discussed in Harmelin and Somelin.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/8327347/', '8327347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we find that the General Assembly could rationally conclude that leaving the scene of an accident where death results poses a risk substantial enough to support the penalty portion of the.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/8327347/', '8327347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/8327347/', '8327347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the trial court’s conclusion that section 56-5-1210 of the South Carolina Code is constitutional.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/8327347/', '8327347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that any inference of vindictiveness derived from the timing of the direct indictment was insufficient to prove an improper motivation because the evidence established probable cause to believe the crime had occurred;', 'probable_cause', 'State v. Blakely', 'https://www.courtlistener.com/opinion/8327378/', '8327378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Blakely', 'https://www.courtlistener.com/opinion/8327378/', '8327378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm as to this issue.', 'general', 'State v. Blakely', 'https://www.courtlistener.com/opinion/8327378/', '8327378') ON CONFLICT DO NOTHING;
