INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'going forward, for offenses committed after the issuance of this opinion, we hold that the same-elements test will serve as the singular framework for determining whether two charges are in fact the same offense for purposes of double-jeopardy analysis.', 'general', 'State v. Rodney J. Miles a/k/a Jamal D. Allen (077035) (Camden County and Statewide)', 'https://www.courtlistener.com/opinion/4392849/', '4392849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') (recognizing Dixon’s holding, but deciding to apply same-evidence test until this Court holds otherwise), certif.', 'general', 'State v. Rodney J. Miles a/k/a Jamal D. Allen (077035) (Camden County and Statewide)', 'https://www.courtlistener.com/opinion/4392849/', '4392849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the same-evidence test, however, we find that defendant’s successive prosecution for the school-zone offense is prohibited because it is based on the same evidence that supported the plea and conviction on the loitering offense.', 'plea', 'State v. Rodney J. Miles a/k/a Jamal D. Allen (077035) (Camden County and Statewide)', 'https://www.courtlistener.com/opinion/4392849/', '4392849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the State could not prosecute the driver for driving while intoxicated (DWI) if the driver’s reckless conduct in the first prosecution was predicated solely on his presumed intoxication.', 'general', 'State v. Rodney J. Miles a/k/a Jamal D. Allen (077035) (Camden County and Statewide)', 'https://www.courtlistener.com/opinion/4392849/', '4392849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that a driver who pled guilty to DWI could not be prosecuted for death by auto if the sole basis for his reckless conduct was his intoxication.', 'general', 'State v. Rodney J. Miles a/k/a Jamal D. Allen (077035) (Camden County and Statewide)', 'https://www.courtlistener.com/opinion/4392849/', '4392849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '07(2) of the Model Penal Code, notions of fairness, and the defendant’s reasonable expectations, we reversed the drug-possession convictions, concluding that “a defendant shall not be subject to separate trials for multiple offenses ‘based on the same conduct or arising from the same criminal episode.', 'general', 'State v. Rodney J. Miles a/k/a Jamal D. Allen (077035) (Camden County and Statewide)', 'https://www.courtlistener.com/opinion/4392849/', '4392849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ruden, we held that the plaintiff could use a violation of the Iowa Code of Professional Responsibility for Lawyers as evidence of negligence, but ultimately held that the attorney’s acts or omissions were not sufficient to demonstrate proximate cause of any damages as a matter of law.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Blessum’s motion for a new trial on the issue'' of damages, and the cross-appeal, were untimely.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Blessum did not violate this rule.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that the defendant’s cross-appeal was untimely, we reject on the merits the defendant’s challenge to the amount of the jury award.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the district court did not abuse its discretion by not permitting the expanded expert testimony of Brandes as it was irrelevant to any issue the jury was properly instructed to consider.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Blessum’s motion and cross-appeal were both untimely.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Blessum’s disciplinary case, we found that he violated three rules: a sexual relationship with a client in violation of rule 32:1.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm the district court.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the district court granting the motion for directed verdict as to this claim of legal malpractice.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the analysis set forth above regarding the claims for legal malpractice and breach of fiduciary duty based solely on the sexual relationship, we affirm the district court’s decision not to allow Brandes’s expanded testimony.', 'general', 'Melissa Stender v. Anthony Zane Blessum', 'https://www.courtlistener.com/opinion/4400907/', '4400907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Petersen, we held that good cause existed to postpone trial fourteen days past the speedy trial deadline because one of the State’s expert witnesses was on vacation during a rescheduled trial date.', 'general', 'State of Iowa v. Christopher Clay McNeal', 'https://www.courtlistener.com/opinion/4403033/', '4403033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "the State did not meet its burden of showing good cause for the delay* ” Id.', 'general', 'State of Iowa v. Christopher Clay McNeal', 'https://www.courtlistener.com/opinion/4403033/', '4403033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, under that law, we find that the court acted within its discretion.', 'general', 'State of Iowa v. Christopher Clay McNeal', 'https://www.courtlistener.com/opinion/4403033/', '4403033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the circumstances of that case, we affirmed the district court’s finding of good cause, although one could certainly fault the State for not starting and concluding the plea negotiations more diligently.', 'plea', 'State of Iowa v. Christopher Clay McNeal', 'https://www.courtlistener.com/opinion/4403033/', '4403033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Gathercole, we held that a person who had been taken into custody in Utah by a private transport company and brought under guard to Iowa following extradition had not been arrested for speedy indictment purposes, noting, “We define an ‘arrest’ in speedy-trial cases by our general law of arrest under Iowa Code chapter 804 because rule of criminal procedure 27(2) and Iowa Code section 804.', 'general', 'State of Iowa v. Deantay Darelle Williams', 'https://www.courtlistener.com/opinion/4394391/', '4394391') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in light of Birchfield and McNeely, N.', 'general', 'State v. Romano', 'https://www.courtlistener.com/opinion/4398945/', '4398945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that N.', 'general', 'State v. Romano', 'https://www.courtlistener.com/opinion/4398945/', '4398945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8 Though we do not have definitive guidance from the Supreme Court, based on the Supreme Court’s Fourth Amendment precedent regarding consent as well as the rationale and language the Court employed in McNeely and Birchfield, we conclude that the blood draw from defendant cannot be justified *691under N.', 'search_seizure', 'State v. Romano', 'https://www.courtlistener.com/opinion/4398945/', '4398945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2(b) to take a blood draw outside these circumstances, we conclude that N.', 'general', 'State v. Romano', 'https://www.courtlistener.com/opinion/4398945/', '4398945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons we affirm as modified herein the Court of Appeals’ opinion affirming the trial court’s order suppressing any testing of defendant’s blood.', 'suppression', 'State v. Romano', 'https://www.courtlistener.com/opinion/4398945/', '4398945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that the superior court erred in rejecting the proposed mitigator
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*195Based on our review of this legislative history, we conclude that .', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/4420015/', '4420015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, we conclude that the court erred in rejecting the proposed mitigator.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/4420015/', '4420015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Brown’s post-traumatic stress from the sexual assault in Kuwait was “combat-related” for purposes of this mitigator because Kuwait was a combat zone, we need not reach Brown’s alternative claim that his sexual assault was causally related to combat because it “reactivated” or exacerbated the post-traumatic stress that he suffered from his combat experience in Iraq.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/4420015/', '4420015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gaffney, this Court held the retroactive application of Megan’s Law I did not violate the state or federal ex post facto clauses.', 'general', 'Commonwealth v. Muniz, J., Aplt.', 'https://www.courtlistener.com/opinion/4410372/', '4410372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse and hold: 1) SORNA’s registration provisions constitute punishment notwithstanding the General Assembly’s identification of the provisions as nonpunitive;', 'general', 'Commonwealth v. Muniz, J., Aplt.', 'https://www.courtlistener.com/opinion/4410372/', '4410372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Superior Court’s decision affirming appellant’s judgment of sentence, and vacate that, portion of the sentence requiring appellant to comply with SORNA.', 'sentencing', 'Commonwealth v. Muniz, J., Aplt.', 'https://www.courtlistener.com/opinion/4410372/', '4410372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold this factor weighs in favor of finding SORNA’s effect to be punitive.', 'general', 'Commonwealth v. Muniz, J., Aplt.', 'https://www.courtlistener.com/opinion/4410372/', '4410372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a guilty plea relinquishes the right to assert a multiplicity claim when the claim cannot be resolved on the record.', 'plea', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, after considering the relationship of Broce to Morris and its progeny, especially Hubbard, we conclude that the rule in Broce that a guilty plea can waive double jeopardy defects, subject to certain exceptions, is consistent with Wisconsin case law and properly balances the public''s interest in efficient judicial administration with a defendant''s double jeopardy rights.', 'plea', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither overbroad precedent from Wisconsin courts nor any policy view of our criminal justice system warrants our breaking ranks with Broce.', 'general', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Kelty''s guilty plea relinquished her opportunity to have a court determine the merits of her multiplicity challenge.', 'plea', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] Because Kelty''s attempt to withdraw her guilty plea cannot meet any of these grounds for withdrawal,[4] we reverse the court of appeals.', 'plea', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therein, we held that Act 152 of 2004 was unconstitutional under the Single Subject Clause of the Pennsylvania Constitution, and its various subparts were not severa-ble.', 'general', 'Commonwealth v. Derhammer, J., Aplt.', 'https://www.courtlistener.com/opinion/4445734/', '4445734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we held that recklessness, pure and simple, is the mens rea for depraved indifference murder, which is “distinguishable from manslaughter ] not by the mental element involved but by the objective circumstances in which the act occurs”;', 'general', 'Policano v. Herbert', 'https://www.courtlistener.com/opinion/5639290/', '5639290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'Policano v. Herbert', 'https://www.courtlistener.com/opinion/5639290/', '5639290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As for Sanchez’s other argument, we concluded that if we “accept[ed] the jury’s determination that the killing of Range was not intentional,” then Sanchez’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, we said as much ourselves in Sanchez when we concluded that strong proof of intent did not foreclose the jury from finding recklessness and depraved indifference (see 98 NY2d at 378).', 'general', 'Policano v. Herbert', 'https://www.courtlistener.com/opinion/5639290/', '5639290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wall, we held that because the “record established that defendant was guilty of an intentional shooting or no other” (29 NY2d at 864), a verdict convicting the defendant of criminally negligent homicide could not be sustained.', 'general', 'Policano v. Herbert', 'https://www.courtlistener.com/opinion/5639290/', '5639290') ON CONFLICT DO NOTHING;
