INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that Utah''s aggravated abuse statute is not unconstitutionally vague and conclude that Tulley has not met his burden of establishing that Utah''s habitual violent offender statute violates either the Utah Constitution''s cruel and unusual punishment clause or the double jeopardy clause.', 'general', 'State v. Tulley', 'https://www.courtlistener.com/opinion/4522353/', '4522353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶3 We conclude that the district court correctly excluded evidence of Victim''s prior sexual misconduct and correctly instructed the jury.', 'general', 'State v. Tulley', 'https://www.courtlistener.com/opinion/4522353/', '4522353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that although section 402(4)(a) provides a non-exhaustive list of felonies, section 402(4)(b) describes the types of crimes that can be added to that non-exhaustive list.', 'general', 'State v. Tulley', 'https://www.courtlistener.com/opinion/4522353/', '4522353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the state of the crime scene, in addition to Victim''s apparent injuries, and the officer''s concern that Victim may be dead, we conclude that "no reasonable law enforcement official acquainted with [Tulley''s] behavior could conclude other than that" Tulley had committed aggravated abuse of a vulnerable adult.', 'general', 'State v. Tulley', 'https://www.courtlistener.com/opinion/4522353/', '4522353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the aggravated abuse of a vulnerable adult statute is not unconstitutionally vague, and that Tulley has not demonstrated that the habitual violent offender statute violates the Utah Constitution.', 'general', 'State v. Tulley', 'https://www.courtlistener.com/opinion/4522353/', '4522353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the end, we affirm the district court.', 'general', 'State v. Tulley', 'https://www.courtlistener.com/opinion/4522353/', '4522353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court.', 'general', 'State v. Tulley', 'https://www.courtlistener.com/opinion/4522353/', '4522353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prejudicial effect of such evidence substantially outweighed any probative value it may have had.', 'general', 'State v. Kelsey', 'https://www.courtlistener.com/opinion/1276847/', '1276847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that any prejudice to Kelsey was cured by the trial judge’s curative instruction to the jury.', 'general', 'State v. Kelsey', 'https://www.courtlistener.com/opinion/1276847/', '1276847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in admitting the exhibits into evidence.', 'general', 'State v. Kelsey', 'https://www.courtlistener.com/opinion/1276847/', '1276847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s instructions, taken as a whole, were adequate.', 'general', 'State v. Kelsey', 'https://www.courtlistener.com/opinion/1276847/', '1276847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we find that Kelsey was not unfairly prejudiced by the testimony.', 'general', 'State v. Kelsey', 'https://www.courtlistener.com/opinion/1276847/', '1276847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Kelsey', 'https://www.courtlistener.com/opinion/1276847/', '1276847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we AFFIRM the trial court on all issues.', 'general', 'State v. Kelsey', 'https://www.courtlistener.com/opinion/1276847/', '1276847') ON CONFLICT DO NOTHING;
