INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the offense of driving while under the influence of intoxicants is a “traffic offense,” and that under our Juvenile Code the municipal court has jurisdiction to hear such cases.', 'general', 'City of Camden v. Brassell', 'https://www.courtlistener.com/opinion/1281113/', '1281113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that driving under the influence, first offense, under § 56-5-2930 is a “traffic violation” pursuant to § 20-7-410.', 'general', 'City of Camden v. Brassell', 'https://www.courtlistener.com/opinion/1281113/', '1281113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'City of Camden v. Brassell', 'https://www.courtlistener.com/opinion/1281113/', '1281113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prosecution may present evidence, if relevant and helpful, to generally explain the common postincident behavior of children who are victims of sexual abuse.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Smith, we hold that the trial court exercised the proper discretion in allowing a single expert to clarify why child victims of sexual assault frequently delay reporting the incident.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, for the reasons set forth below, in Peterson, we find that the trial court erred in allowing certain aspects of the expert testimony to be presented to the jury.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in light of the overwhelming evidence against Peterson, we find that any error was harmless.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the use of testimony on general behavioral characteristics of sexually abused children is still the subject of contention and dispute among experts in the field, we find that its use as a general profile to be used to prove the existence of abuse is inappropriate.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction in Smith, and note that the conduct of the trial presents an almost perfect model for the limitations that must be set in allowing expert testimony into evidence in child sexual abuse cases.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the guest statute violates the equal protection guarantee of the Idaho and United States Constitutions and therefore we must hold it unconstitutional.', 'general', 'Thompson v. Hagan', 'https://www.courtlistener.com/opinion/1163777/', '1163777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and clarify
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that subject matter jurisdiction and venue were proper in the locus of the defendant’s failure to act.', 'general', 'Commonwealth v. Bershad', 'https://www.courtlistener.com/opinion/5134571/', '5134571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the nature of Bershad’s duty to Penn Triple S and the act which Bershad failed to perform, we find that the locus of Bershad’s failure to act was Dauphin County.', 'general', 'Commonwealth v. Bershad', 'https://www.courtlistener.com/opinion/5134571/', '5134571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully considering section 3927(a) in its entirety, we find that the statute is sufficiently definite, and that persons of common intelligence will not be forced to guess about its meaning or application.', 'general', 'Commonwealth v. Bershad', 'https://www.courtlistener.com/opinion/5134571/', '5134571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that section 7268(b) of the Tax Reform Code was not designed to require the defendant to meet the obligation under which he obtained the property of another.', 'general', 'Commonwealth v. Bershad', 'https://www.courtlistener.com/opinion/5134571/', '5134571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that Bershad has not presented any substantial question for our review, we decline to address his sentencing claims.', 'sentencing', 'Commonwealth v. Bershad', 'https://www.courtlistener.com/opinion/5134571/', '5134571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there is no merit to Bershad’s contention that the trial court erroneously excluded relevant psychiatric evidence.', 'general', 'Commonwealth v. Bershad', 'https://www.courtlistener.com/opinion/5134571/', '5134571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Bershad', 'https://www.courtlistener.com/opinion/5134571/', '5134571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that our theft statute applies to theft of real property by occupation, seizure, and the filing of a deed to the property and that the evidence is sufficient to support *417the defendant''s convictions.', 'general', 'State v. Gentry', 'https://www.courtlistener.com/opinion/6240796/', '6240796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the options available to the General Assembly when the consolidated theft statute was enacted and the statutory language it chose to adopt, we conclude that the General Assembly intended our consolidated theft statute to apply to theft of real property in the same way it applies to other property.', 'general', 'State v. Gentry', 'https://www.courtlistener.com/opinion/6240796/', '6240796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that sufficient evidence supports the jury''s verdict finding Defendant guilty of theft of property valued at over $250,000, a Class A felony.', 'general', 'State v. Gentry', 'https://www.courtlistener.com/opinion/6240796/', '6240796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Defendant''s assertion that she was limited in questioning the witness about adverse possession is wholly without merit.', 'general', 'State v. Gentry', 'https://www.courtlistener.com/opinion/6240796/', '6240796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals upholding the defendant''s convictions and remanding to the trial court for resentencing.', 'sentencing', 'State v. Gentry', 'https://www.courtlistener.com/opinion/6240796/', '6240796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court erred in concluding that section 5-64-411 did not require a culpable mental state, and we reverse and remand on this point.', 'general', 'Small v. State', 'https://www.courtlistener.com/opinion/6241282/', '6241282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s decision to deny his motions to suppress and reverse the trial court''s conviction for violating Arkansas Code Annotated section 5-64-411 ;', 'suppression', 'Small v. State', 'https://www.courtlistener.com/opinion/6241282/', '6241282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the denial of the motion to suppress.', 'suppression', 'Small v. State', 'https://www.courtlistener.com/opinion/6241282/', '6241282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that any point raised on appeal would be wholly without merit.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/6242525/', '6242525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the revocation and grant counsel''s motion to withdraw.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/6242525/', '6242525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that *47the trial court erred in concluding that "each act of identity theft" is the allowable unit of prosecution under the statute.', 'general', 'State v. Donaldson', 'https://www.courtlistener.com/opinion/6242770/', '6242770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '51, we conclude that the gravamen of the offense of fraudulent use or possession of identifying information is the prohibited act of obtaining, possessing, transferring, or using an item of identifying information.', 'general', 'State v. Donaldson', 'https://www.courtlistener.com/opinion/6242770/', '6242770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set out below, we reverse the trial court''s order and remand for further proceedings consistent with this opinion.', 'general', 'State v. Donaldson', 'https://www.courtlistener.com/opinion/6242770/', '6242770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court''s order quashing Count VI of the indictment and remand this cause for further proceedings consistent with this opinion.', 'general', 'State v. Donaldson', 'https://www.courtlistener.com/opinion/6242770/', '6242770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the newly discovered evidence of Sullivan was cumulative, material and admissible, and whether or not it would on a new trial granted cause a different result in the verdict was speculative.', 'general', 'Lowe v. State', 'https://www.courtlistener.com/opinion/3395114/', '3395114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because "fictitious credit card" was not defined by the legislature, and because there were two ways for a credit card to be "fictitious" under the statute, we held that "a trial court should grant a motion to quash an indictment that fails to adequately notify the defendant of the manner in which the credit card is fictitious.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court of appeals reached this decision by consulting our decision in May , in which we held that "alarm" in the pre-1983 version of the harassment statute was vague.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Olurebi , after we determined that the language of the indictment was ambiguous, we held that the trial court should have granted the motion to quash, and, because Olurebi''s motion to quash was erroneously denied, we remanded to the court of appeals to determine whether the error impacted Olurebi''s ability to prepare a defense.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '27 And, for the following reasons, we conclude that, in Penal Code Section 42.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Putting these ideas together, we conclude that the phrase "a manner calculated to alarm" means a manner that is objectively likely to frighten an ordinary, reasonable person.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, to be guilty of disorderly conduct under Penal Code Section 42.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Construing the statute in this manner, we conclude that it is not unconstitutionally vague.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '61 For these reasons, we conclude that the concerns expressed in Kramer and May about the vagueness of the former harassment statute do not apply to the disorderly conduct statute.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals'' judgment.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/6244070/', '6244070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*914McClintock I was a search and seizure case in which we held that the statements remaining in a search warrant affidavit-after the court of appeals excised portions of the affidavit-did not support a finding of probable cause that illegal narcotics would be found inside a particular apartment.', 'probable_cause', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the remaining facts in the affidavit-that an officer smelled marijuana outside the building (not specifically from the upstairs apartment), that a male person was seen entering and leaving the upstairs apartment at odd hours, and that the officer received information that marijuana was being grown in the building-did not "clearly establish[ ] probable cause" for the search of the upstairs apartment.', 'probable_cause', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that these facts sufficed to support a finding of probable cause that evidence of the offense of driving while intoxicated would be found in a search of Appellant''s blood.', 'probable_cause', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When we consider the totality of the remaining facts in Officer Harrison''s search warrant affidavit, giving no deference to the magistrate''s initial reading of those facts, we conclude that it still demonstrated the existence of probable cause.', 'probable_cause', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the trial court, we conclude that the information remaining in the warrant affidavit is sufficient to supply probable cause.', 'probable_cause', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But in assaying that question, we concluded that those facts supported a finding of probable cause, which is necessary for any search conducted pursuant to a warrant.', 'probable_cause', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And we concluded that, in any event, "[o]ther evidence clearly established appellant was the driver of the pickup at the time of the collision.', 'general', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the holding of the court of appeals.', 'general', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the holding of the court of appeals.', 'general', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the judgment of the court of appeals and remand the cause to that court for disposition of Appellant''s remaining points of error.', 'general', 'Hyland v. State', 'https://www.courtlistener.com/opinion/6244122/', '6244122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 10] Turning to Black’s sentence appeal, we conclude that the court neither misapplied principle in setting Black’s basic sentence at five to seven years, nor abused its discretion in setting her maximum sentence at five years.', 'sentencing', 'State v. Black', 'https://www.courtlistener.com/opinion/5142805/', '5142805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error at trial, we affirm Black’s conviction without discussion.', 'general', 'State v. Black', 'https://www.courtlistener.com/opinion/5142805/', '5142805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have not suggested that sentencing in Maine follow the federal sentencing guidelines, but some time ago this Court held that our sentencing decisions should "be informed by the likely sentence that would have been imposed for the same offense if prosecuted in the concurrent federal jurisdiction.', 'sentencing', 'State v. Black', 'https://www.courtlistener.com/opinion/5142805/', '5142805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that further factual development is necessary, and we remand for further proceedings.', 'general', 'Doe v. District Attorney', 'https://www.courtlistener.com/opinion/5143259/', '5143259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Haskell does not declare for all time that SORNA is immune from an ex post facto challenge.', 'general', 'Doe v. District Attorney', 'https://www.courtlistener.com/opinion/5143259/', '5143259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the amendments to SORNA since Haskell, along with Smith v.', 'general', 'Doe v. District Attorney', 'https://www.courtlistener.com/opinion/5143259/', '5143259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 36] We conclude that, taking the allegations of the complaint as true, we must vacate the Superior Court’s dismissal of the complaint and remand the matter for further development of a record to give Doe the opportunity to demonstrate by the clearest proof that the effects of SORNA are punitive.', 'dismissal', 'Doe v. District Attorney', 'https://www.courtlistener.com/opinion/5143259/', '5143259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That is, we first looked to whether the Legislature, in enacting SORNA, intended to enact a civil or criminal penalty, and we concluded that it intended a civil penalty.', 'general', 'Doe v. District Attorney', 'https://www.courtlistener.com/opinion/5143259/', '5143259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the statute did not constitute ex post facto legislation as applied to the defendant.', 'general', 'Doe v. District Attorney', 'https://www.courtlistener.com/opinion/5143259/', '5143259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In voiding the statute, we held that the civil OUI process was, in reality, a criminal proceeding, requiring constitutional protections, which could not be denied “for the sake of legislative or judicial efficiency.', 'general', 'Doe v. District Attorney', 'https://www.courtlistener.com/opinion/5143259/', '5143259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because no such right exists—and because, in fact, that third-party representation would have constituted the unauthorized practice of law, which is a crime—the court correctly denied the motion, and we affirm the judgment.', 'general', 'State v. Rupert', 'https://www.courtlistener.com/opinion/5160691/', '5160691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, plaintiffs initial good faith tax filing was a business decision, but because it was rejected by the Division well after a timely amended return could have been filed, we hold that the business decision rule does not operate to bind plaintiff to its original filing.', 'general', 'Chemical New Jersey Holdings, Inc. v. Director, New Jersey Division of Taxation', 'https://www.courtlistener.com/opinion/9313957/', '9313957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse and remand for an accurate determination of plaintiffs tax liability for the years 1992 and 1993.', 'general', 'Chemical New Jersey Holdings, Inc. v. Director, New Jersey Division of Taxation', 'https://www.courtlistener.com/opinion/9313957/', '9313957') ON CONFLICT DO NOTHING;
