INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the court of appeals.', 'general', 'Guzman v. State', 'https://www.courtlistener.com/opinion/1867558/', '1867558') ON CONFLICT DO NOTHING;
