INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1287941/', '1287941') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the identity theft statute does not criminalize the act of defaming a public official, and therefore does not violate Baron''s First Amendment rights.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/1288778/', '1288778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the identity theft statute as applied to Baron does not criminalize his constitutionally protected right to defame a public official.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/1288778/', '1288778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the State has met its burden of proving beyond a reasonable doubt that the statute is constitutional.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/1288778/', '1288778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the identity theft statute does not impose any cognizable burden on political speech, we reject Baron''s argument that the statute is subject to strict scrutiny.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/1288778/', '1288778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/1288778/', '1288778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the circuit court''s order dismissing the charge against Baron under Wis.', 'dismissal', 'State v. Baron', 'https://www.courtlistener.com/opinion/1288778/', '1288778') ON CONFLICT DO NOTHING;
