INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the facts of this case we hold that defendant has failed to establish that a different result would have been reached if the alleged “bad acts” had been redacted from the transcript.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1289476/', '1289476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant received a fair trial free from prejudicial error.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1289476/', '1289476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This case presents a question on which Courts of Appeals have divided: Does a defendant’s purpose to circumvent a bank’s reporting obligation suffice to sustain a conviction for “willfully violating” the antistructuring provision?1 We hold that the “willfulness” *137requirement mandates something more.', 'general', 'Ratzlaf v. United States', 'https://www.courtlistener.com/opinion/112919/', '112919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '19 Because the jury was not properly instructed in this regard, we reverse the judgment of the Ninth Circuit and remand this case for further proceedings consistent with this opinion.', 'general', 'Ratzlaf v. United States', 'https://www.courtlistener.com/opinion/112919/', '112919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that while the trial court erred in admitting vouching testimony from four witnesses who testified that the complainant was “sincere” in her complaint, the error was harmless beyond a reasonable doubt because “one would expect [such] witnesses to say” that the complainant was sincere.', 'general', 'Van Buren v. State', 'https://www.courtlistener.com/opinion/1346263/', '1346263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Van Bu-rén was denied a fair trial by the admission of prejudicial vouching testimony, we reverse the court of appeals and remand for a new
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that there is a reasonable likelihood that any error substantially affected the verdict, we review Van Buren’s claims.', 'general', 'Van Buren v. State', 'https://www.courtlistener.com/opinion/1346263/', '1346263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that, under the facts and circumstances presented here, improper vouching testimony was admitted at trial and, as a result, Van Burén was denied a fair trial.', 'general', 'Van Buren v. State', 'https://www.courtlistener.com/opinion/1346263/', '1346263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that "[w]here the same act or transaction constitutes a violation of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the circuit court erroneously concluded that a double jeopardy violation occurred based upon Green’s multiple convictions and sentences.', 'sentencing', 'State v. Green', 'https://www.courtlistener.com/opinion/1236196/', '1236196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the indictments are legally sufficient, and on this issue, we affirm the holding and rationale of the Court of Appeals.', 'general', 'Clinebell v. Commonwealth', 'https://www.courtlistener.com/opinion/1294647/', '1294647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such statements are not “conduct” within the meaning of Code § 18.', 'general', 'Clinebell v. Commonwealth', 'https://www.courtlistener.com/opinion/1294647/', '1294647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the daughter’s prior statements, we conclude that the doctor’s testimony was relevant and probative to impeach her testimony.', 'general', 'Clinebell v. Commonwealth', 'https://www.courtlistener.com/opinion/1294647/', '1294647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In another part of this opinion we hold that the victim was competent to testify, but assuming he was not, his testimony was admitted by the court and it was properly considered on the motion to dismiss.', 'dismissal', 'State v. Swann', 'https://www.courtlistener.com/opinion/1294316/', '1294316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant has not shown that there is a reasonable possibility that but for errors of the defendant’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant has made no showing that his trial counsel failed to render effective assistance of counsel, to the prejudice of his defense, and that Judge Lewis properly denied his motion for appropriate relief.', 'general', 'State v. Swann', 'https://www.courtlistener.com/opinion/1294316/', '1294316') ON CONFLICT DO NOTHING;
