INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that he had been placed in double jeopardy solely because he was sentenced for both crimes, each of which had all the elements of the other.', 'sentencing', 'State v. Swann', 'https://www.courtlistener.com/opinion/1294316/', '1294316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held there was a transactional connection between all the alleged crimes and found no error in the consolidation of them for trial.', 'general', 'State v. Swann', 'https://www.courtlistener.com/opinion/1294316/', '1294316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, while this would have been a violation of subsection 3 of section 719.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1294870/', '1294870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, under the test set out above, Breitbach was in custody because he was subject to immediate physical restraint by fleeing from the officers.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1294870/', '1294870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The district court found the defendant guilty, and we affirm.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1294870/', '1294870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the trial court’s ruling, we hold that the district court did not err by admitting Appellant’s statement.', 'general', 'Van Riper v. State', 'https://www.courtlistener.com/opinion/1296862/', '1296862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS HEREBY ORDERED that COURTNEY VAN RIPER is guilty of the crime charged in the Information filed herein and that he be imprisoned and confined in the Wyoming Department of Corrections located at or near the city of Rawlins, Wyoming for a period of not less than six (6) years nor more than nine (9) years .', 'general', 'Van Riper v. State', 'https://www.courtlistener.com/opinion/1296862/', '1296862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified.', 'general', 'Van Riper v. State', 'https://www.courtlistener.com/opinion/1296862/', '1296862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6] In Gearinger, we held that when probation is revoked solely for the violation of a special condition, "the revocation court is authorized by section 42-8-34.', 'general', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] We conclude that in this case, unlawful confinement under a sentence longer than that permitted by state statute would constitute a denial of liberty without due process of law.', 'sentencing', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the habeas court incorrectly ruled that the revocation of the full balance of Petitioner''s probation violated the provisions of OCGA § 42-8-34.', 'habeas', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our decision in Gearinger, supra, authorizes a revocation court, when faced with a probationer who has both violated a special condition and committed a felony, to dispose of a probationer as having either violated a special condition or committed a felony.', 'general', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse.', 'general', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Condrey', 'https://www.courtlistener.com/opinion/1296575/', '1296575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we find that there was sufficient evidence from which the jury could find that defendant committed welfare fraud with respect to both the Spencer and Kinchlow files.', 'general', 'People v. Jemison', 'https://www.courtlistener.com/opinion/1297615/', '1297615') ON CONFLICT DO NOTHING;
