INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record contains sufficient evidence to support the conviction.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/1296678/', '1296678') ON CONFLICT DO NOTHING;
