INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse the defendant''s conviction pursuant to Wis.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/1296678/', '1296678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we reverse the defendant''s conviction on grounds different from the grounds stated by the court of appeals, we recognize and commend the meticulous review of the evidence embodied in the court''s opinion.', 'general', 'State v. Watkins', 'https://www.courtlistener.com/opinion/1296678/', '1296678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for trial.', 'general', 'State v. Cuevas', 'https://www.courtlistener.com/opinion/1299165/', '1299165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. LaCoste', 'https://www.courtlistener.com/opinion/1298459/', '1298459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court erred in refusing to admit the excited utterances of the unknown male bystander, we reverse on this issue.', 'general', 'State v. LaCoste', 'https://www.courtlistener.com/opinion/1298459/', '1298459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the conviction, judgment and sentence.', 'sentencing', 'Nixon v. State', 'https://www.courtlistener.com/opinion/1256153/', '1256153') ON CONFLICT DO NOTHING;
