INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'possession to determine that jurisdiction was proper, we affirm the circuit court’s order for a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that respondent''s criminal conduct falls within the provisions of art.', 'general', 'Matter of Marquardt', 'https://www.courtlistener.com/opinion/1298515/', '1298515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the established facts require imposition of sanctions under art.', 'general', 'Matter of Marquardt', 'https://www.courtlistener.com/opinion/1298515/', '1298515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, the conviction having become final, we hold that the following sanctions are appropriate for consideration: censure, suspension without pay, or removal from office.', 'general', 'Matter of Marquardt', 'https://www.courtlistener.com/opinion/1298515/', '1298515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that respondent, Judge Philip W.', 'general', 'Matter of Marquardt', 'https://www.courtlistener.com/opinion/1298515/', '1298515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] In Biggins we held that although a misdemeanor conviction of driving under the influence did not require that the judge be removed from office, it was "conduct prejudicial to the administration of justice that brings the judicial office into disrepute" within the meaning of art.', 'general', 'Matter of Marquardt', 'https://www.courtlistener.com/opinion/1298515/', '1298515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Wescott', 'https://www.courtlistener.com/opinion/1305869/', '1305869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Adhering to these views, we hold that no right protected by the Fourth Amendment was violated in the present case.', 'search_seizure', 'Hoffa v. United States', 'https://www.courtlistener.com/opinion/107318/', '107318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we believe that trial by jury in criminal cases is fundamental to the American scheme of justice, we hold that the Fourteenth Amendment guarantees a right of jury trial in all criminal cases which — were they to be tried in a federal court — would come within the Sixth Amendment’s guarantee.', 'general', 'Duncan v. Louisiana', 'https://www.courtlistener.com/opinion/107685/', '107685') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 Since we consider the appeal be*150fore us to be such a case, we hold that the Constitution was violated when appellant’s demand for jury trial was refused.', 'general', 'Duncan v. Louisiana', 'https://www.courtlistener.com/opinion/107685/', '107685') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On January 29, 1968, this Court held that the Fifth Amendment privilege against compulsory self-incrimination was a valid defense to a prosecution for failure to register as a gambler and to pay the related occupational and gambling excise taxes under 26 U.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '22 (1953), a prosecution for failure to register and pay the gambling tax, this Court held that the registration requirement and the obligation to pay the gambling tax did not violate the Fifth Amendment.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Three years ago we held that the federal wagering tax statutes, 26 U.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 67-69, we held that the privilege against self-incrimination was available to the petitioners as a defense to prosecution for failure to register for, report, or pay the federal wagering taxes.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On that basis we concluded that “throughout the United States, wagering is ''an area permeated with criminal statutes/ and those engaged in wagering are a group ‘inherently suspect of criminal activities.', 'general', 'MacKey v. United States', 'https://www.courtlistener.com/opinion/108302/', '108302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 We conclude that § 1202 is ambiguous in the critical respect.', 'general', 'United States v. Bass', 'https://www.courtlistener.com/opinion/108421/', '108421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that Congress has not "plainly and unmistakably," United States v.', 'general', 'United States v. Bass', 'https://www.courtlistener.com/opinion/108421/', '108421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in commerce or affecting commerce,” for we conclude that the Government meets its burden here if it demonstrates that the firearm received has previously traveled in interstate commerce.', 'general', 'United States v. Bass', 'https://www.courtlistener.com/opinion/108421/', '108421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 We affirm the judgment of the court below, *339but for substantially different reasons.', 'general', 'United States v. Bass', 'https://www.courtlistener.com/opinion/108421/', '108421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the judgment for the remaining four counts, and remanded for resentencing.', 'sentencing', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/1546248/', '1546248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Chief Justice asserts that if we hold that capital punishment is unconstitutional because it is excessive, we will next have to determine whether a 10-year prison sentence rather than a five-year sentence is also excessive, or whether a $5 fine would not do equally well as a $10 fine.', 'sentencing', 'Furman v. Georgia', 'https://www.courtlistener.com/opinion/108605/', '108605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 207, this Court held “that committing to the untrammeled discretion of the jury the power to pronounce life or death in capital cases is [not] offensive to anything in the Constitution.', 'general', 'Furman v. Georgia', 'https://www.courtlistener.com/opinion/108605/', '108605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '130 (1879), this Court held that execution by shooting was not a prohibited mode of carrying out a sentence of death.', 'sentencing', 'Furman v. Georgia', 'https://www.courtlistener.com/opinion/108605/', '108605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, we held that the Secretary of State’s denial of a passport for travel to Cuba did not violate a citizen’s First Amendment rights.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The rule was justified by the “weightiest considerations of national security” and we concluded that the “right to speak and publish does not carry with it the unrestrained right to gather information.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Alabama, supra, we found that compelled disclosure of the names of those in Alabama who belonged to the NAACP “is likely to affect adversely the ability [of the NAACP] and its members to pursue their .', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not interpret this discussion as indicating that petitioner was abandoning his First Amendment claim if the Kentucky Court of Appeals did not agree with his statutory interpretation argument, and we hold that the constitutional question in Branzburg v.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Massachusetts Supreme Judicial Court and hold that petitioner must appear before the grand jury to answer the questions put to him, subject, of course, to the supervision of the presiding judge as to “the propriety, purposes, and scope of the grand jury inquiry and the pertinence of the probable testimony.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that after a criminal defendant pleads guilty, on the advice of counsel, he is not automatically entitled to federal collateral relief on proof that the indicting grand jury was unconstitutionally selected.', 'plea', 'Tollett v. Henderson', 'https://www.courtlistener.com/opinion/108762/', '108762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But just as the guilty pleas in the Brady trilogy were found to foreclose direct inquiry into the merits of claimed antecedent constitutional violations there, we conclude that respondent’s guilty plea here alike forecloses independent inquiry into the claim of discrimination in the selection of the grand jury.', 'plea', 'Tollett v. Henderson', 'https://www.courtlistener.com/opinion/108762/', '108762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '15 In short, we hold that the discretion vested in a district judge under § 5010 (d) is essentially the same as the traditional discretion vested in the court, for example, to impose the minimum sentence on a first offender or a larger sentence on a recidivist.', 'sentencing', 'Dorszynski v. United States', 'https://www.courtlistener.com/opinion/109093/', '109093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We conclude that while an express finding of no benefit must be made on the *426record, the Act does not require that it be accompanied by supporting reasons.', 'general', 'Dorszynski v. United States', 'https://www.courtlistener.com/opinion/109093/', '109093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the pledges here were “offers” or “sales” under § 17 (a);', 'general', 'Rubin v. United States', 'https://www.courtlistener.com/opinion/110378/', '110378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We ednclude that it will not and therefore we reverse.', 'general', 'Ernst & Ernst v. Hochfelder', 'https://www.courtlistener.com/opinion/109420/', '109420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'United States v. Chadwick', 'https://www.courtlistener.com/opinion/109714/', '109714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the District Court’s award is adequately supported by its finding of bad faith and that the Act supports the additional award by the Court of Appeals.', 'general', 'Hutto v. Finney', 'https://www.courtlistener.com/opinion/109919/', '109919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bradley, supra, we affirmed an order requiring a state treasurer to pay a substantial sum to another litigant, even though the District Court’s opinion explicitly recognized that “this remedial decree will be paid for by the taxpayers of the City of Detroit and the State of Michigan,” App.', 'general', 'Hutto v. Finney', 'https://www.courtlistener.com/opinion/109919/', '109919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that such prospective relief is not barred by the Eleventh Amendment.', 'general', 'Hutto v. Finney', 'https://www.courtlistener.com/opinion/109919/', '109919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'of Social Services, supra, decided only weeks ago, we held that the Congress which passed the Civil Rights Act of 1871, now § 1983 — a statute enacted pursuant to § 5 of the Fourteenth Amendment, see 436 IT.', 'general', 'Hutto v. Finney', 'https://www.courtlistener.com/opinion/109919/', '109919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“We concluded that none of the statutes relied upon by plaintiffs in Edelman contained any authorization by *702Congress to join a State as defendant.', 'general', 'Hutto v. Finney', 'https://www.courtlistener.com/opinion/109919/', '109919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we concluded that “the Eleventh Amendment, and the principle of state sovereignty which it embodies, .', 'general', 'Hutto v. Finney', 'https://www.courtlistener.com/opinion/109919/', '109919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Fitzpatrick, we held that under § 5 of the Fourteenth Amendment Congress could explicitly allow for recovery against state agencies without violating the Eleventh Amendment.', 'general', 'Hutto v. Finney', 'https://www.courtlistener.com/opinion/109919/', '109919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in a challenge to a state criminal conviction brought under 28 U.', 'general', 'Jackson v. Virginia', 'https://www.courtlistener.com/opinion/110138/', '110138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these criteria, we hold that a rational trier of fact could reasonably have found that the petitioner committed murder in the first degree under Virginia law.', 'general', 'Jackson v. Virginia', 'https://www.courtlistener.com/opinion/110138/', '110138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trier of fact entertained such a doubt, this Court held that the juvenile was constitutionally entitled to the same verdict that an adult defendant in a criminal case would receive.', 'general', 'Jackson v. Virginia', 'https://www.courtlistener.com/opinion/110138/', '110138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the language and structure of the Act make plain Congress’ intent to authorize an award of restitution only for the loss caused by the specific conduct that is the basis of the offense of conviction.', 'general', 'Hughey v. United States', 'https://www.courtlistener.com/opinion/112428/', '112428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the District Court acted Within its discretion, and we therefore affirm the judgment of the Court of Appeals.', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '250 (1988), in which this Court held that a district court could not rely on its supervisory power as a means of circumventing the clear mandate of a procedural rule.', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the circumstances of this case, we find that the District Court acted within its discretion in assessing as a sanction for Chambers’ bad-faith conduct the entire amount of NASCO’s attorney’s fees.', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that the jury must do so.', 'general', 'Richardson v. United States', 'https://www.courtlistener.com/opinion/118295/', '118295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Act is properly read to include such a requirement.', 'general', 'United States v. X-Citement Video, Inc.', 'https://www.courtlistener.com/opinion/117881/', '117881') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we conclude that the term “knowingly” in §2252 extends both to the sexually explicit nature of the material and to the age of the performers.', 'general', 'United States v. X-Citement Video, Inc.', 'https://www.courtlistener.com/opinion/117881/', '117881') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '] 568, we hold that, under § 5 of the Willis-Campbell Act, a civil action to recover taxes, which in fact are penalties, is punitive in character and barred by a prior conviction of the defendant for a criminal offense involving the same transactions.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these in rem civil forfeitures are neither “punishment” nor criminal for purposes of the Double Jeopardy Clause.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In another unanimous decision, we held that the forfeiture was not barred by the prior criminal proceeding.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the Montana marijuana tax, we held that because “tax *286statutes serve a purpose quite different from civil penalties, .', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Michigan, supra, at 452, where we held that “forfeiture .', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the civil forfeitures involved in these cases do not constitute punishment under the Double Jeopardy Clause, see infra, at 292, we do not address those three arguments in this opinion.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, we concluded that the civil forfeiture “furthered] broad remedial aims,” including both “discouraging unregulated commerce in firearms” and “removing from circulation firearms that have been used or intended for use outside regulated channels of commerce.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we concluded that “forfeiture under [§§ 881(a)(4) and (a)(7)] constitutes ‘payment to a sovereign as punishment for some offense,’ and, as such, is subject to the limitations of the Eighth Amendment’s Excessive Fines Clause.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*290Moving to the second stage of our analysis, we find that there is little evidence, much less the “ ‘clearest proof’ ” that we require, see 89 Firearms, supra, at 365, quoting Ward, 448 U.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we found that the forfeiture provision, because it reached both weapons used in violation of federal law and those “intended to be used” in such a manner, reached a broader range of conduct than its criminal analog.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 610, 621, we held that §§ 881(a)(4) and (a)(7) must be considered to qualify as such, partly because forfeitures have historically been understood as punishment and more importantly because no remedial purpose underlay the sanction the statute created.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that any forfeiture was subject to the constraints of the Excessive Fines Clause of the Eighth Amendment.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 On that basis, we held that imposition of the tax after criminal prosecution of the taxpayer violated double jeopardy.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kurth Ranch we held that the Double Jeopardy Clause applies to punitive proceedings even if they are labeled a tax.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '299 (1932), in which we held that for double jeopardy purposes two statutes define different offenses if “each provision requires proof of a fact which the other does not.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Austin, we held that the exemption revealed a “congressional intent to punish only those involved in drug trafficking” because “ ‘the traditional criminal sanctions .', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under the Double Jeopardy Clause a defendant who already has been punished in a criminal prosecution may not be subjected to an additional civil sanction to the extent that the second sanction may not fairly be characterized as remedial, but only as a deterrent or retribution.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Johnson, and we hold that the court’s action in this case was not “plain error” of the sort which an appellate court may notice under Federal Rule of Criminal Procedure 52(b).', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/118106/', '118106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, absent a clear indication of Congress’ intent to change the balance, the proper course was to adopt a construction which maintains the existing balance.', 'general', 'Salinas v. United States', 'https://www.courtlistener.com/opinion/118151/', '118151') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 666 limited to eases in which the bribe has a demonstrated effect upon federal funds? Second, does the conspiracy prohibition contained in the Racketeer Influenced and Corrupt Organizations Act (RICO) apply only when the conspirator agrees to commit two of the predicate acts RICO forbids? Ruling against the petitioner on both issues, we affirm the judgment of the Court of Appeals for the Fifth Circuit.', 'general', 'Salinas v. United States', 'https://www.courtlistener.com/opinion/118151/', '118151') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the subsection is a penalty provision, which simply authorizes a court to increase the sentence for a recidivist.', 'sentencing', 'Almendarez-Torres v. United States', 'https://www.courtlistener.com/opinion/118188/', '118188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “the Due Process Clause protects the accused against conviction except upon proof beyond a reasonable doubt of every fact necessary to constitute the crime with which he is charged,” 397 U.', 'general', 'Almendarez-Torres v. United States', 'https://www.courtlistener.com/opinion/118188/', '118188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In neither case did we hold that §§ 2113(d) and (e) set forth distinct offenses.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/118274/', '118274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the harmless-error rule of Chapman v.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that materiality of falsehood is an element of the federal mail fraud, wire fraud, and bank fraud statutes.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As in Pope, however, we held that the unconstitutional conclusive presumption was “subject to the harmless-error rule.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite that omission, we held that “[t]he case before us is a case for application of the ‘harmless error’ standard.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But • since we held that harmless-error analysis was appropriate in Pope, that case not only does not support petitioner’s approach, but rejects it.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 468-469, we concluded that the error did not warrant correction in light of the “ ‘overwhelming’ ” and “uncontroverted” evidence supporting materiality, id.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '510 (1927), where we reversed the defendant’s conviction because he had been tried before a biased judge, the State argued that “the evidence shows clearly that the defendant was guilty and that he was only fined $100, which was the minimum amount, and therefore that he can not complain of a lack of due process, either in his conviction or in the amount of the judgment.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '461 (1997), we affirmed the petitioner’s conviction even though the element of materiality had been withheld from the jury.', 'general', 'Neder v. United States', 'https://www.courtlistener.com/opinion/118298/', '118298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with the Government as to the interpretation of prior law, and we find that consideration of the Ex Post Facto Clause is unnecessary.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/118364/', '118364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 765, this court held: "Before accepting a guilty plea a judge is expected to sufficiently examine the defendant to determine whether he understands the nature of the charge, the possible penalty, and the effect of his plea.', 'plea', 'State v. Irish', 'https://www.courtlistener.com/opinion/1640999/', '1640999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the taking of the foregoing steps is sufficient to assure that a plea represents a voluntary and intelligent choice among the alternative courses of action open to a criminal defendant, the ultimate standard by which pleas of guilty or nolo contendere are to be tested.', 'plea', 'State v. Irish', 'https://www.courtlistener.com/opinion/1640999/', '1640999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Irish', 'https://www.courtlistener.com/opinion/1640999/', '1640999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that no defendant may be imprisoned for any offense, whether a traffic infraction, misdemeanor, or felony, absent a knowing and intelligent waiver of his rights as provided for by the Boykin-Turner rule.', 'general', 'State v. Irish', 'https://www.courtlistener.com/opinion/1640999/', '1640999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an ineffective-assistance-of-counsel claim may be brought in a collateral proceeding under § 2255, whether or not the petitioner could have raised the claim on direct appeal.', 'ineffective_assistance', 'Massaro v. United States', 'https://www.courtlistener.com/opinion/127915/', '127915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that requiring a criminal defendant to bring ineffective-assistance-of-counsel claims on direct appeal does not promote these objectives.', 'ineffective_assistance', 'Massaro v. United States', 'https://www.courtlistener.com/opinion/127915/', '127915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with the majority of the Courts of Appeals, and we reverse.', 'general', 'Massaro v. United States', 'https://www.courtlistener.com/opinion/127915/', '127915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that a determination of the constitutionality of W.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the satisfaction of the dual notice requirements, we conclude that W.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the defendants’ first contention, we conclude that the evidence was sufficient to establish that the defendants possessed an intent to abuse the patient.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because we find that the record contained sufficient evidence upon which a jury could have based them conclusions that the defendants willfully created an emergency situation for the patient, we conclude that the evidence was sufficient to support their convictions under W.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the parties’ arguments on this matter, we conclude that the resolution of this issue is rather facile.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained below, we find that § 9-6-15(b) is constitutional.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with our holding and our prior precedents in this field, we find that the circuit court properly imposed upon the defendants those sentences authorized by W.', 'sentencing', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 820 (1979), permit a defendant to elect between punishments when amendments to a penal statute reduce the penalties that may be imposed, we find that no such right of election existed in the underlying proceedings.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only if no rational trier of fact could have found the essential elements of the crime beyond a reasonable doubt.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the parties’ arguments on appeal, the record established in this case, and the pertinent authorities, we affirm the decision of the Circuit Court of Hampshire County.', 'general', 'State v. Easton', 'https://www.courtlistener.com/opinion/1338946/', '1338946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ramirez’s account, and we find that petitioner’s description of “ ‘an explo*563sive device in a box’ ” was little better than no guidance at all.', 'general', 'Groh v. Ramirez', 'https://www.courtlistener.com/opinion/131161/', '131161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that respondent’s complaint fails to plead sufficient facts to state a claim for purposeful and unlawful discrimination against petitioners.', 'plea', 'Ashcroft v. Iqbal', 'https://www.courtlistener.com/opinion/145875/', '145875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that in that sort of circumstance, “[a]n allegation of parallel conduct is .', 'general', 'Ashcroft v. Iqbal', 'https://www.courtlistener.com/opinion/145875/', '145875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we conclude that the Court of Appeals had jurisdiction to hear petitioners’ appeal.', 'general', 'Ashcroft v. Iqbal', 'https://www.courtlistener.com/opinion/145875/', '145875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under Twombly’s, construction of Rule 8, we conclude that respondent’s complaint has not “nudged [his] claims” of invidious discrimination “across the line from conceivable to plausible.', 'general', 'Ashcroft v. Iqbal', 'https://www.courtlistener.com/opinion/145875/', '145875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this is sufficient evidence of conspiracy to withstand the directed verdict motion.', 'general', 'State v. Prince', 'https://www.courtlistener.com/opinion/1320132/', '1320132') ON CONFLICT DO NOTHING;
