INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the order granting a new trial on Prince’s conviction for accessory before the fact of murder and remand for sentencing.', 'sentencing', 'State v. Prince', 'https://www.courtlistener.com/opinion/1320132/', '1320132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Prince’s convictions for solicitation and conspiracy.', 'general', 'State v. Prince', 'https://www.courtlistener.com/opinion/1320132/', '1320132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 229 (1991), where we held that a defendant had standing to challenge the statutes in question on overbreadth and vagueness grounds.', 'general', 'Woolfolk v. Commonwealth', 'https://www.courtlistener.com/opinion/1320141/', '1320141') ON CONFLICT DO NOTHING;
