INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 is directed primarily at conduct that has no legitimate purpose and, if directed at speech then without regard to its content, we conclude that appellant has not shown any overbreadth of the statute that is “substantial .', 'general', 'Woolfolk v. Commonwealth', 'https://www.courtlistener.com/opinion/1320141/', '1320141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that appellant failed to prove that former Code § 18.', 'general', 'Woolfolk v. Commonwealth', 'https://www.courtlistener.com/opinion/1320141/', '1320141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that former Code § 18.', 'general', 'Woolfolk v. Commonwealth', 'https://www.courtlistener.com/opinion/1320141/', '1320141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we find that former Code § 18.', 'general', 'Woolfolk v. Commonwealth', 'https://www.courtlistener.com/opinion/1320141/', '1320141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Woolfolk v. Commonwealth', 'https://www.courtlistener.com/opinion/1320141/', '1320141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS ORDERED that respondent’s license to practice law in this state is suspended until further order of the Court.', 'general', 'In Re Ellerbe', 'https://www.courtlistener.com/opinion/1318895/', '1318895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When we examine these provisions of the Drug Control Act, we find that the General Assembly has established a system of record-keeping designed to reflect the identity of all persons to whom controlled drugs are sold, administered, or dispensed.', 'general', 'McCutcheon v. Commonwealth', 'https://www.courtlistener.com/opinion/1321606/', '1321606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that both courts correctly concluded that the Sixth Amendment as construed in *227Blakely does apply to the Sentencing Guidelines.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that it was impermissible for “the trial judge, sitting alone” to determine the presence or absence of the aggravating factors required by Arizona law for imposition of the death penalty.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '87 (1993), we held that the provisions of the Guidelines that require a sentence enhancement if the judge determines that the defendant committed perjury do not violate the privilege of the accused to testify on her own behalf.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '389 (1995), we held that the Double Jeopardy Clause did not bar a prosecution for conduct that had provided the basis for an enhancement of the defendant''s sentence in a prior case.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Watts, relying on Witte, we held that the Double Jeopardy Clause permitted a court to consider acquitted conduct in sentencing a defendant under the Guidelines.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this provision must be severed and excised, as must one other statutory section, § 3742(e) (2000 ed.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While reasonable minds can, and do, differ about the outcome, we conclude that the constitutional jury trial requirement is not compatible with the Act as written and that some severance and excision are necessary.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 232, we concluded that the harm to the victim was an element of the crime.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“We concluded that ‘consideration of information about the defendant’s character and conduct at sentencing does not result in “punishment” for any offense other than the one of which the defendant was convicted.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But they failed to make that argument, and, based on our review of the record which showed “a series of interrelated drug transactions involving both cocaine and crack,” we concluded that no such claim could succeed.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it may not, and that a later court determining the character of an admitted burglary is generally limited to examining the statutory definition, charging document, written plea agreement, transcript of plea colloquy, and any explicit factual finding by the trial judge to which the defendant assented.', 'plea', 'Shepard v. United States', 'https://www.courtlistener.com/opinion/142875/', '142875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that enquiry under the ACCA to determine whether a plea of guilty to burglary defined by a nongeneric statute necessarily admitted elements of the generic offense is limited to the terms of the charging document, the terms of a plea agreement or transcript of colloquy between judge and defendant in which the factual basis for the plea was confirmed by the defendant, or to some comparable judicial record of this information.', 'plea', 'Shepard v. United States', 'https://www.courtlistener.com/opinion/142875/', '142875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '575 (1990), we held that a court sentencing under the ACCA could look to statutory elements, charging documents, and jury instructions to determine whether an earlier conviction after trial was for generic burglary.', 'sentencing', 'Shepard v. United States', 'https://www.courtlistener.com/opinion/142875/', '142875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We held that the ACCA generally prohibits the later court from delving into particular facts disclosed by the record of conviction, thus leaving the court normally to “look only to the fact of conviction and the statutory definition of the prior offense.', 'general', 'Shepard v. United States', 'https://www.courtlistener.com/opinion/142875/', '142875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/1324801/', '1324801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals rejection of the States request for a sentencing remand on the three first-degree CSC convictions because the lesser included offense of second-degree CSC was not submitted to the jury.', 'sentencing', 'State v. Brown', 'https://www.courtlistener.com/opinion/1324801/', '1324801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '36, 53-54 (2004), we held that this provision bars “admission of testimonial statements of a witness who did not appear at trial unless he was unavailable to testify, and the defendant had had a prior opportunity for cross-examination.', 'general', 'Davis v. Washington', 'https://www.courtlistener.com/opinion/145641/', '145641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Supreme Court of Indiana in No.', 'general', 'Davis v. Washington', 'https://www.courtlistener.com/opinion/145641/', '145641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Supreme Court of Washington in No.', 'general', 'Davis v. Washington', 'https://www.courtlistener.com/opinion/145641/', '145641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such a complaint should be dismissed.', 'dismissal', 'Bell Atlantic Corp. v. Twombly', 'https://www.courtlistener.com/opinion/145730/', '145730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In applying these general standards to a § 1 claim, we hold that stating such a claim requires a complaint with enough factual matter (taken as true) to suggest that an agreement was made.', 'general', 'Bell Atlantic Corp. v. Twombly', 'https://www.courtlistener.com/opinion/145730/', '145730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed on the ground that the Court of Appeals had impermissibly applied what amounted to a heightened pleading requirement by insisting that Swierkiewicz allege “specific facts” beyond those necessary to state his claim and the grounds showing entitlement to relief.', 'plea', 'Bell Atlantic Corp. v. Twombly', 'https://www.courtlistener.com/opinion/145730/', '145730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '232 (1974), we reversed the Court of Appeals’ dismissal on the pleadings when the respondents, the Governor and other officials of the State of Ohio, argued that the petitioners’ claims were barred by sovereign immunity.', 'dismissal', 'Bell Atlantic Corp. v. Twombly', 'https://www.courtlistener.com/opinion/145730/', '145730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the Court of Appeals on the ground that “[w]hatever *584the plaintiffs may or may not be able to establish as to the merits of their allegations, their claims, as stated in the complaints, given the favorable reading required by the Federal Rules of Civil Procedure,” were not barred by the Eleventh Amendment because they were styled as suits against the defendants in their individual capacities.', 'general', 'Bell Atlantic Corp. v. Twombly', 'https://www.courtlistener.com/opinion/145730/', '145730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed in another unanimous opinion, holding that “under a notice pleading system, it is not appropriate to require a plaintiff to plead facts establishing a prima facie case because the McDonnell Douglas framework does not apply in every employment discrimination case.', 'plea', 'Bell Atlantic Corp. v. Twombly', 'https://www.courtlistener.com/opinion/145730/', '145730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that it does.', 'general', 'Flores-Figueroa v. United States', 'https://www.courtlistener.com/opinion/145876/', '145876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that §1028A(a)(l) requires the Government to show that the defendant knew that the means of identification at issue belonged to another person.', 'general', 'Flores-Figueroa v. United States', 'https://www.courtlistener.com/opinion/145876/', '145876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in these circumstances the jury should not be barred from considering all the evidence.', 'general', 'Herring v. United States', 'https://www.courtlistener.com/opinion/145922/', '145922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '981 (1984), we held that the exclusionary rule did not apply when a warrant was invalid because a judge forgot to make “clerical corrections” to it.', 'general', 'Herring v. United States', 'https://www.courtlistener.com/opinion/145922/', '145922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a mistake made by a judicial employee could not give rise to exclusion for three reasons: The exclusionary rule was crafted to curb police rather than judicial misconduct;', 'general', 'Herring v. United States', 'https://www.courtlistener.com/opinion/145922/', '145922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Franks, we held that police negligence in obtaining a warrant did not even rise to the level of a Fourth Amendment violation, let alone meet the more stringent test for triggering the exclusionary rule.', 'search_seizure', 'Herring v. United States', 'https://www.courtlistener.com/opinion/145922/', '145922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the Constitution allowed defendants, in some circumstances, “to challenge the truthfulness of factual statements made in an affidavit supporting the warrant,” even after the warrant had issued.', 'general', 'Herring v. United States', 'https://www.courtlistener.com/opinion/145922/', '145922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Leon, we held that “the marginal or nonexistent benefits produced by suppressing evidence obtained in objectively reasonable reliance on a subsequently invalidated search warrant cannot justify the substantial costs of exclusion.', 'suppression', 'Herring v. United States', 'https://www.courtlistener.com/opinion/145922/', '145922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 909-910, we conclude that when police mistakes are the result of negligence such as that described here, rather than systemic error or reckless disregard of constitutional requirements, any marginal deterrence does not “pay its *148way.', 'general', 'Herring v. United States', 'https://www.courtlistener.com/opinion/145922/', '145922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 (1995), we held that recordkeeping errors made by a court clerk do not trigger the exclusionary rule, so long as the *158police reasonably relied upon the court clerk’s recordkeeping.', 'general', 'Herring v. United States', 'https://www.courtlistener.com/opinion/145922/', '145922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there existed sufficient evidence to sustain the charge against defendant of fraudulently burning a dwelling.', 'general', 'State v. Payne', 'https://www.courtlistener.com/opinion/1326419/', '1326419') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the amount of monetary damages sustained is not an element of either crime upon which defendant was convicted, we find that the trial court did not err in finding as an aggravating factor for both charges that the acts involved an attempted and actual taking of property of great monetary value.', 'general', 'State v. Payne', 'https://www.courtlistener.com/opinion/1326419/', '1326419') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''With these two sections excised (and statutory cross-references to the two sections consequently invalidated),” we held that “the remainder of the Act *821satisfies the Court’s constitutional requirements.', 'general', 'Dillon v. United States', 'https://www.courtlistener.com/opinion/148795/', '148795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Booker does not demand that result.', 'general', 'Dillon v. United States', 'https://www.courtlistener.com/opinion/148795/', '148795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the limited scope and purpose of § 3582(c)(2), we conclude that proceedings under that section do not implicate the interests identified in Booker.', 'general', 'Dillon v. United States', 'https://www.courtlistener.com/opinion/148795/', '148795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of these reasons, we conclude that neither Booker’s constitutional nor remedial holding requires the result that Dillon urges.', 'general', 'Dillon v. United States', 'https://www.courtlistener.com/opinion/148795/', '148795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the first of two opinions, we held that the two applications of the Guidelines before us violated the Sixth Amendment because the sentencing judge in each case imposed a more severe sentence than the facts found by the jury warranted.', 'sentencing', 'Dillon v. United States', 'https://www.courtlistener.com/opinion/148795/', '148795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this provision must be severed and excised, as must one other statutory section, § 3742(e) (2000 ed.', 'general', 'Dillon v. United States', 'https://www.courtlistener.com/opinion/148795/', '148795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 In that case we concluded that the wire-fraud statute, 18 U.', 'general', 'Morrison v. National Australia Bank Ltd.', 'https://www.courtlistener.com/opinion/149289/', '149289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the dismissal of petitioners’ complaint on this ground.', 'dismissal', 'Morrison v. National Australia Bank Ltd.', 'https://www.courtlistener.com/opinion/149289/', '149289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that failure on the part of a party to properly raise preemption under Section 301 of the Labor Management Relations Act of 1947, 29 U.', 'general', 'Tolliver v. Kroger Co.', 'https://www.courtlistener.com/opinion/1329021/', '1329021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a matter of public policy in this state, we hold that generally a CBA may not bind employees to resolve assault or battery conduct by employers or their agents through grievance procedures.', 'general', 'Tolliver v. Kroger Co.', 'https://www.courtlistener.com/opinion/1329021/', '1329021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'assault and battery claims are not bound with questions of the labor contract’s interpretation, we hold that these intentional tort claims are not, per se, preempted from state court consideration.', 'general', 'Tolliver v. Kroger Co.', 'https://www.courtlistener.com/opinion/1329021/', '1329021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 254 (1993) we held that “[a]n arbitration clause of a collective bargaining agreement cannot nullify the statutory rights given to employees under the West Virginia Wage Payment and Collection Act, W.', 'general', 'Tolliver v. Kroger Co.', 'https://www.courtlistener.com/opinion/1329021/', '1329021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in syllabus point 1 of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Tollivers’ claim for intentional infliction of emotional distress had to be resolved through the grievance process established by the collective bargaining agreement.', 'general', 'Tolliver v. Kroger Co.', 'https://www.courtlistener.com/opinion/1329021/', '1329021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the circuit court’s order granting partial summary judgment on those two issues.', 'general', 'Tolliver v. Kroger Co.', 'https://www.courtlistener.com/opinion/1329021/', '1329021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the order of the circuit court of Cabell County.', 'general', 'Tolliver v. Kroger Co.', 'https://www.courtlistener.com/opinion/1329021/', '1329021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that (1) Klinge’s constitutional right to a unanimous verdict was not violated inasmuch as HRS §§ 707-715(1) and (2) do not give rise to two separate and distinct crimes;', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that this remark did not constitute prosecutorial misconduct.', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in light of the nature of the prosecutor’s statement, the failure of defense counsel to object, and the strength of the evidence against Klinge, we hold that any error with regard to this statement by the prosecutor did not prejudicially affect Klinge’s substantial rights.', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4, we hold that his remark, though distasteful and unprofessional, was not so prejudicial as to deny Klinge a fair trial.', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion in denying Klinge’s motion for mistrial based on prosecutorial misconduct.', 'mistrial', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that (1) Klinge’s constitutional right to a unanimous verdict was not violated inasmuch as HRS §§ 707-715(1) and (2) do not give rise to two separate and distinct crimes;', 'general', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, this court held that the prosecutor’s repeated injection of her personal opinion concerning the defendant’s guilt and the credibility of defense witnesses amounted to plain error in light of “the inconclusive evidence against Marsh, the particularly egregious misconduct of the prosecutor in presenting her personal views on the dispositive issues, and the lack of a prompt jury instruction specifically directed to the prosecutor’s closing remarks[.', 'jury_instruction', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s judgment, guilty conviction and sentence filed on December 3, 1997.', 'sentencing', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s judgment, guilty conviction and sentence filed on December 3,1997.', 'sentencing', 'State v. Klinge', 'https://www.courtlistener.com/opinion/1255918/', '1255918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that a trial court’s decision on whether to remit, under Rule 46(e)(4) of the West Virginia Rules of Criminal Procedure, a previously forfeited bail bond will be reviewed by this Court under an abuse of discretion standard.', 'general', 'State v. Hedrick', 'https://www.courtlistener.com/opinion/1335457/', '1335457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the surety bears the burden of establishing that the trial court abused its discretion in refusing to remit, pursuant to Rule 46(e)(4) of the West Virginia Rules of Criminal Procedure, all or part of a previously forfeited bail bond.', 'general', 'State v. Hedrick', 'https://www.courtlistener.com/opinion/1335457/', '1335457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that when a trial court is asked to remit all or part of a previously forfeited bail bond, pursuant to Rule 46(e)(4) of the West Virginia Rules of Criminal Procedure, the court shall consider the following criteria to the extent that they are relevant to the particular case under consideration: (1) the willfulness of the defendant’s breach of the bond’s conditions;', 'general', 'State v. Hedrick', 'https://www.courtlistener.com/opinion/1335457/', '1335457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court did not abuse its discretion by remitting only $355,000.', 'general', 'State v. Hedrick', 'https://www.courtlistener.com/opinion/1335457/', '1335457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that our review of the circuit court’s decision on this issue is for an abuse of discretion.', 'general', 'State v. Hedrick', 'https://www.courtlistener.com/opinion/1335457/', '1335457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in the body of this opinion, we find that the Circuit Court of Pendleton County properly exercised its discretion when it declined to remit $100,000.', 'general', 'State v. Hedrick', 'https://www.courtlistener.com/opinion/1335457/', '1335457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'State v. Long', 'https://www.courtlistener.com/opinion/1256015/', '1256015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that paragraph three of § 56-5-2946 incorporates the technical testing requirements of § 56-5-2950(a).', 'general', 'State v. Long', 'https://www.courtlistener.com/opinion/1256015/', '1256015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Long', 'https://www.courtlistener.com/opinion/1256015/', '1256015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Thus, we hold that defendant has failed to demonstrate how the trial court abused its discretion in granting the State’s for-cause challenge of Rose.', 'general', 'State v. Nobles', 'https://www.courtlistener.com/opinion/1335516/', '1335516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since Smith unequivocally stated that she could not recommend the death penalty under any circumstances, we hold that the trial court did not abuse its discretion in excusing her for cause.', 'general', 'State v. Nobles', 'https://www.courtlistener.com/opinion/1335516/', '1335516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that the trial court properly granted the State’s challenge for cause.', 'general', 'State v. Nobles', 'https://www.courtlistener.com/opinion/1335516/', '1335516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'of this prospective juror may have indicated her ambivalence toward the death penalty, we hold that she was properly excused for cause because that testimony also demonstrated that she would be unable to render a verdict in accordance with the trial court’s instructions and the laws of the state.', 'general', 'State v. Nobles', 'https://www.courtlistener.com/opinion/1335516/', '1335516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these questions did not seek to predetermine what kind of verdict prospective jurors would render;', 'general', 'State v. Nobles', 'https://www.courtlistener.com/opinion/1335516/', '1335516') ON CONFLICT DO NOTHING;
