INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 311 (2006), this Court held that,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the record, we find that the evidence presented at the appellant''s trial supported a first degree arson conviction.', 'general', 'Damron v. Haines', 'https://www.courtlistener.com/opinion/1342361/', '1342361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, and to avoid possible challenges to convictions and guilty pleas, we hold that when a criminal defendant is entitled to elect the law under which he is to be sentenced, it must appear on the record that he has been fully advised of his right to elect and he must be given an opportunity to exercise that right by the court.', 'sentencing', 'State Ex Rel. Arbogast v. Mohn', 'https://www.courtlistener.com/opinion/1334321/', '1334321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons cited herein, we reverse the ruling of the Circuit Court of Preston County and remand appellant Arbogast’s case for further proceedings consistent with this opinion, and award the writ prayed for by petitioner Rodoussakis.', 'general', 'State Ex Rel. Arbogast v. Mohn', 'https://www.courtlistener.com/opinion/1334321/', '1334321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Roper', 'https://www.courtlistener.com/opinion/1334347/', '1334347') ON CONFLICT DO NOTHING;
