INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this court held that (a) the district court did not have authority to “extend” a restraining order beyond two years;', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the very existence of the harassment statute raises the possibility that others may refrain from free speech or expression, we conclude that the exception applies, and that appellant need not establish individual standing.', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that respondent’s reliance on these cases is misplaced.', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the harassment statute only regulates speech or conduct that constitutes “fighting words,” “true threats,” or substantial invasions of one’s privacy, we conclude that the statute is narrowly tailored and is, therefore, constitutional.', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the statute does not infringe on constitutionally protected speech and is not unconstitutionally overbroad.', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the incidental impact on protected speech, if any, does not render the statute substantially overbroad.', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the harassment statute is “quasi-criminal” and is subject to the heightened definiteness requirement.', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the harassment statute is not facially over-broad or void for vagueness;', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because only one incident was found by the court to have occurred, we reversed the order in an opinion filed on June 29, 2004.', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and that there are no genuine issues of material fact that preclude summary judgment, we affirm.', 'general', 'Dunham v. Roer', 'https://www.courtlistener.com/opinion/1345770/', '1345770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the Parole Board acted lawfully when it anticipatorily revoked Webb’s mandatory parole, and we therefore AFFIRM the judgement of the superior court.', 'general', 'Webb v. Alaska Department of Corrections', 'https://www.courtlistener.com/opinion/1348273/', '1348273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Glenn', 'https://www.courtlistener.com/opinion/1345989/', '1345989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that when the trial judge chooses to make a preliminary ruling on the admissibility of prior convictions to impeach a defendant and the defendant does not testify at trial, the claim of improper impeachment is not preserved for review.', 'general', 'State v. Glenn', 'https://www.courtlistener.com/opinion/1345989/', '1345989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in prosecutions for assaulting an officer, obstructing a peace officer, or resisting arrest, we hold that a trial court must instruct the jury on the issue of self-defense when there is any evidence adduced which raises a legally cognizable claim that the police officer used unreasonable force in making the arrest.', 'general', 'State v. Yeutter', 'https://www.courtlistener.com/opinion/1349900/', '1349900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Yeutter failed to adduce any evidence which raised a legally cognizable claim that the police officer used unreasonable force in making the arrest.', 'general', 'State v. Yeutter', 'https://www.courtlistener.com/opinion/1349900/', '1349900') ON CONFLICT DO NOTHING;
