INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, even absent the challenged violation, the district court would have revoked probation based upon three other undisputed violations and, accordingly, we affirm.', 'general', 'State v. Upton', 'https://www.courtlistener.com/opinion/1360548/', '1360548') ON CONFLICT DO NOTHING;
