INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the spousal privilege did not apply because appellant intended the fabricated story to be told to the police.', 'general', 'MacKool v. State', 'https://www.courtlistener.com/opinion/1439176/', '1439176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More recently, this court held that the trial court did not abuse its discretion in denying defendant’s motion to allow jurors to question him after the State completed its cross-examination.', 'general', 'MacKool v. State', 'https://www.courtlistener.com/opinion/1439176/', '1439176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Mike’s own statements to the police, some of which contained inconsistencies, Mike’s conduct before and after the crime, and the statements of Ms.', 'general', 'MacKool v. State', 'https://www.courtlistener.com/opinion/1439176/', '1439176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court did not abuse its discretion in admitting the financial documents.', 'general', 'MacKool v. State', 'https://www.courtlistener.com/opinion/1439176/', '1439176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court did not abuse its discretion.', 'general', 'MacKool v. State', 'https://www.courtlistener.com/opinion/1439176/', '1439176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'MacKool v. State', 'https://www.courtlistener.com/opinion/1439176/', '1439176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that by enacting the offense of assault during the commission of a felony, the legislature clearly intended to impose punishment in addition to that specified for the underlying felony, if the criminal actor shot, cut, stabbed, or wounded another person during the attempt to commit or the commission of the underlying felony and to classify that additional conduct as felonious.', 'general', 'State v. Penwell', 'https://www.courtlistener.com/opinion/1364320/', '1364320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we find that the court lacked sufficient evidence to hold Dolfi in contempt for his failure to appear at the Allegheny trial on June 1.', 'general', 'Ricci v. Geary', 'https://www.courtlistener.com/opinion/1436733/', '1436733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Ricci v. Geary', 'https://www.courtlistener.com/opinion/1436733/', '1436733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Bolfi’s conduct did not rise to the level of intentional or willful disregard of the lawful process of court, we reverse.', 'general', 'Ricci v. Geary', 'https://www.courtlistener.com/opinion/1436733/', '1436733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Bianchi', 'https://www.courtlistener.com/opinion/1365931/', '1365931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'vide guidance to trial courts in the future, we hold that generally, in criminal trials, trial courts should exercise the utmost caution prior to admitting hearsay testimony pursuant to Rule 804 of the West Virginia Rules of Evidence when the declarant’s unavailability under that rule is due to the fact that his or her lawyer is a State legislator or designated employee of the Legislature, the Legislature is then in regular session, and the legislator or designated employee of the Legislature...', 'general', 'State v. Ladd', 'https://www.courtlistener.com/opinion/1365727/', '1365727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a curator of an estate, appointed pursuant to W.', 'general', 'State v. Ladd', 'https://www.courtlistener.com/opinion/1365727/', '1365727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we held that “[t]he two central requirements for admission of extrajudicial testimony under the Confrontation Clause contained in the Sixth
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 828 (1998), this Court held that “[a] defendant is not entitled to relief from prejudicial joinder pursuant to Rule 14 of the West Virginia
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did.', 'general', 'State v. Ladd', 'https://www.courtlistener.com/opinion/1365727/', '1365727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that a rational trier of fact could find from this evidence the essential elements of a conspiracy, of which the defendant was a part, to murder Richard Ladd.', 'general', 'State v. Ladd', 'https://www.courtlistener.com/opinion/1365727/', '1365727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the defendant’s assignment of error based on insufficiency of the evidence is mer-itless.', 'general', 'State v. Ladd', 'https://www.courtlistener.com/opinion/1365727/', '1365727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the circuit court erred in admitting the out-of-court statements of Mitchell and Ankeney.', 'general', 'State v. Ladd', 'https://www.courtlistener.com/opinion/1365727/', '1365727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that both the State’s and the trial court’s statements are insufficient under our law to support the admission of the challenged evidence.', 'general', 'State v. Ladd', 'https://www.courtlistener.com/opinion/1365727/', '1365727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that it was an abuse of discretion for the trial court to exclude reference to the Boggses’ marriage during the trial.', 'general', 'State v. Ladd', 'https://www.courtlistener.com/opinion/1365727/', '1365727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence in this case was legally insufficient to support her conviction under Section 22.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1440936/', '1440936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we cannot conclude that the act of taking a child from a house with working utilities to one without working utilities is the type of conduct that, by its nature, raises a substantial and unjustifiable risk of injury, we hold that it cannot support a finding of reckless injury to a child.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1440936/', '1440936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was not legally sufficient to permit a finding of gross criminal negligence on the part of the appellant and that the charge of manslaughter, therefore, should not have been submitted to the jury.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1440936/', '1440936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Alternatively, we hold that the evidence was not legally sufficient to permit a finding that any action of the appellant, even if assumed to have been grossly negligent, was the proximate cause of the decedent''s death and that the charge of manslaughter, therefore, should not have been submitted to the jury.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1440936/', '1440936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the legislature could not have intended the seven-year presumptive term to apply to those who recklessly commit assault in the first degree, but only a five-year presumptive term to those who, under identical circumstances, kill their victim.', 'general', 'Pruett v. State', 'https://www.courtlistener.com/opinion/1368900/', '1368900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After tracing the history of these statutes, we concluded that in order to avoid “manifest injustice” referral to the three-judge panel for sentencing was mandatory where a defendant both recklessly killed one victim and recklessly injured another by means of the same dangerous instrument.', 'sentencing', 'Pruett v. State', 'https://www.courtlistener.com/opinion/1368900/', '1368900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that it was theoretically possible to commit manslaughter without using a dangerous instrument.', 'general', 'Pruett v. State', 'https://www.courtlistener.com/opinion/1368900/', '1368900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the trial court had placed undue emphasis on the son’s death, even though it was appropriate to consider it.', 'general', 'Pruett v. State', 'https://www.courtlistener.com/opinion/1368900/', '1368900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for resentencing to a term not to exceed fifteen years with five years suspended.', 'sentencing', 'Pruett v. State', 'https://www.courtlistener.com/opinion/1368900/', '1368900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Pruett’s conviction in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that present Delaware law prohibits such separate prosecutions.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1463040/', '1463040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislative revision has made the rationale of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally before this Court are the following questions: (1) Did the General Assembly intend that a person charged under Section 6312(d) be subjected to individual counts for each item of child pornography possessed? and (2) If the General Assembly so intended, is it constitutional to impose separate punishments for each conviction? For the following reasons, we hold that Section 6312(d) is not unconstitutionally vague or overbroad.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that charging, trying, convicting and sentencing appellant for multiple counts of possession of child pornography is not unlawful under the statute.', 'sentencing', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Section 6312(d) is not unconstitutionally vague in violation of Article I, Section 9 of the Pennsylvania Constitution or the Fourteenth Amendment.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that Section 6312(d) is not overbroad in violation of Article I, Section 7 of the Pennsylvania Constitution or the First Amendment.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that each image of child pornography creates a permanent record of a child''s abuse, which results in continuing exploitation of a child when the image is subsequently viewed.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that the General Assembly did intend that a person charged under Section 6312(d) may be subjected to individual counts and sentences for each item of child pornography possessed, and that the General Assembly''s intention in this regard is constitutional.', 'sentencing', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statute is not void for vagueness under Article I, Section 9 of the Pennsylvania Constitution or under the Fourteenth Amendment.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that it was the General Assembly''s intention that a person charged under Section 6312(d) may be subjected to prosecution and punishment for each depiction of child pornography possessed, and that this intention is constitutional.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Superior Court.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Where, as here, the defense witness was not disclosed until a week prior to trial, we conclude that imposing the sanction of preclusion of the rebuttal testimony would be unnecessarily harsh.', 'general', 'State v. Walton', 'https://www.courtlistener.com/opinion/1357707/', '1357707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the statutes defining reckless manslaughter and negligent homicide do not violate the equal protection clause of the Constitution.', 'general', 'State v. Walton', 'https://www.courtlistener.com/opinion/1357707/', '1357707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the search of Foster’s vehicle was not a lawful search incident to his arrest, and all evidence obtained through the unlawful search should have been suppressed as viola-tive of the Fourth Amendment.', 'suppression', 'State v. Foster', 'https://www.courtlistener.com/opinion/1374782/', '1374782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the search was prohibited by the Fourth Amendment, we vacate the judgment of conviction and remand the case for further proceedings.', 'search_seizure', 'State v. Foster', 'https://www.courtlistener.com/opinion/1374782/', '1374782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Connor v. Town of Hilton Head Island', 'https://www.courtlistener.com/opinion/1378013/', '1378013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that Rodriguez has not shown the guilty plea was tainted by the “confession” even if the confession was improperly obtained.', 'plea', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/1442304/', '1442304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the district court did not abuse its discretion in denying the motion to withdraw the guilty plea.', 'plea', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/1442304/', '1442304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and (3) were Rodriguez’ inculpatory statements made voluntarily? For reasons explained below, we affirm.', 'general', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/1442304/', '1442304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of conviction.', 'general', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/1442304/', '1442304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'for example, this court held that even the “vicious” whipping of a naked child with a wet telephone cord did not create “the kind of ‘extreme’ pain that can reasonably be compared to or equated with any of the categories of serious injury enumerated by the legislature and adopted by this court in Nixon.', 'general', 'Swinton v. United States', 'https://www.courtlistener.com/opinion/1442976/', '1442976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even viewing the evidence in the light most favorable to preserving the jury’s verdict, we conclude that there was sufficient evidence of neither “protracted and obvious disfigurement” nor “extreme physical pain.', 'general', 'Swinton v. United States', 'https://www.courtlistener.com/opinion/1442976/', '1442976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence of “serious bodily injury” was insufficient to support this felony conviction, we reverse and remand for entry of a judgment of conviction on the lesser-included misdemeanor offense of simple assault.', 'general', 'Swinton v. United States', 'https://www.courtlistener.com/opinion/1442976/', '1442976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '01(a), we reverse his conviction of aggravated assault and remand the case for entry of a superseding judgment of conviction on the lesser included offense of simple assault, with re-sentencing as appropriate.', 'sentencing', 'Swinton v. United States', 'https://www.courtlistener.com/opinion/1442976/', '1442976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm because we conclude the evidence is sufficient to support the verdict and because our review of the entire record shows no reversible error.', 'general', 'State v. Arredondo', 'https://www.courtlistener.com/opinion/1384624/', '1384624') ON CONFLICT DO NOTHING;
