INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the grant of summary judgment for defendants as to these other grounds offered by plaintiff to challenge the arrest, the registration check, and the use of handcuffs.', 'general', 'Burton v. City of Durham', 'https://www.courtlistener.com/opinion/1395472/', '1395472') ON CONFLICT DO NOTHING;
