INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court did not err in denying Jefferson’s directed-verdict motion on the grounds that the State failed to present sufficient evidence that Jefferson acted under circumstances manifesting an extreme indifference to the value of human life.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1451124/', '1451124') ON CONFLICT DO NOTHING;
