INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the circuit court did not err in denying Jefferson’s challenge to the phrase.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1451124/', '1451124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the Due Process Clause requires the prosecution to prove beyond a reasonable doubt all the elements of the offense charged but that it does not require the prosecution to prove the nonexistence of all affirmative defenses.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1451124/', '1451124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find no error and, accordingly, we affirm.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1451124/', '1451124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm a conviction if substantial evidence exists to support it.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1451124/', '1451124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, for purposes of construing AS 11.', 'general', 'Vigue v. State', 'https://www.courtlistener.com/opinion/1401354/', '1401354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the police officer had probable cause to arrest Vigue at the time of the initial stop, and thus all of the evidence flowing from that stop was admissible against Vigue.', 'probable_cause', 'Vigue v. State', 'https://www.courtlistener.com/opinion/1401354/', '1401354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that a person who possesses drugs may not be found guilty of tampering with evidence simply because he discards or hides the drugs upon the approach of a police officer.', 'general', 'Vigue v. State', 'https://www.courtlistener.com/opinion/1401354/', '1401354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Hundley Ex Rel. Hundley v. Rite Aid of South Carolina, Inc.', 'https://www.courtlistener.com/opinion/1402250/', '1402250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the court of appeals applied the legal sufficiency test incorrectly, we remand the case to the court of appeals to reconsider the legal sufficiency of the evidence supporting Appellant’s conviction.', 'general', 'Hooper v. State', 'https://www.courtlistener.com/opinion/1404060/', '1404060') ON CONFLICT DO NOTHING;
