INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no plain error, we affirm Barrington’s conviction on Count One.', 'general', 'United States v. Barrington', 'https://www.courtlistener.com/opinion/222924/', '222924') ON CONFLICT DO NOTHING;
