INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'United States v. Barrington', 'https://www.courtlistener.com/opinion/222924/', '222924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the evidence presented at Appellant''s trial, we conclude that the State did not meet this burden in the instant matter.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1406110/', '1406110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the record before this Court, including detailed examination of the transcript of Appellant''s November 29, 2005, trial, applicable precedent and the arguments *872 of the parties, we reverse Appellant''s conviction.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1406110/', '1406110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse both convictions.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1406110/', '1406110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the General Assembly did not intend to punish for felony death by vehicle and felony serious injury by vehicle when a conviction for a greater offense is based on the same conduct.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1402540/', '1402540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4(b), we hold that the General Assembly did not authorize punishment for the enumerated offenses when punishment is imposed for higher class offenses that apply to the same conduct.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1402540/', '1402540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the dismissal by the Court of Appeals as it relates to defendant’s constitutional double jeopardy argument.', 'dismissal', 'State v. Davis', 'https://www.courtlistener.com/opinion/1402540/', '1402540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), this court held that “exposure of luggage to a drug detection dog is a search under the Alaska Constitution.', 'general', 'McGahan v. State', 'https://www.courtlistener.com/opinion/1454383/', '1454383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1311, while this court held that exposing luggage to a dog sniff is a search under the Alaska Constitution, we added that it is
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the State provided no evidence that Shaheed was a less safe driver as a result of being under the influence of alcohol, we reverse that conviction.', 'general', 'Shaheed v. State', 'https://www.courtlistener.com/opinion/1411874/', '1411874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the evidence was sufficient to support defendant’s conviction for indecent exposure and that the Court of Appeals erred in reversing the trial court.', 'general', 'State v. Fly', 'https://www.courtlistener.com/opinion/1414838/', '1414838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s office should demand in writing what evidence it will find satisfactory, and that Maisey should have 30 days from the receipt of this demand to produce evidence satisfactory to the prosecutor’s office that he has completed his community service.', 'general', 'State v. Maisey', 'https://www.courtlistener.com/opinion/1415768/', '1415768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the lower court abused its discretion in not either accepting Maisey’s evidence, or allowing him an additional opportunity to prove that he had completed the community service.', 'general', 'State v. Maisey', 'https://www.courtlistener.com/opinion/1415768/', '1415768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse and remand with directions.', 'general', 'State v. Maisey', 'https://www.courtlistener.com/opinion/1415768/', '1415768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse.', 'general', 'State v. Maisey', 'https://www.courtlistener.com/opinion/1415768/', '1415768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“[C]on-sidering that the total value of the stolen goods was a close question, we hold that the evidence was not sufficient to eliminate the possibility that the verdict was based on surmise or conjecture.', 'general', 'Hebron v. United States', 'https://www.courtlistener.com/opinion/2159781/', '2159781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, we conclude that expert testimony was not necessary to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that a minimum sentence of 178 months is within the range of reasonable and principled outcomes.', 'sentencing', 'People v. Petri', 'https://www.courtlistener.com/opinion/1653609/', '1653609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Petri', 'https://www.courtlistener.com/opinion/1653609/', '1653609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s reasoning.', 'general', 'People v. Petri', 'https://www.courtlistener.com/opinion/1653609/', '1653609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that an accused who is aware of all charges filed against him in separate townships but based on the same criminal episode, and who fails to move for the consolidation of these charges, waives his section 110 statutory right to have all of these charges brought in a single prosecution.', 'general', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1971677/', '1971677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does.', 'general', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1971677/', '1971677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the double jeopardy clause does apply to motor vehicle citations.', 'general', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1971677/', '1971677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that appellant has presented sufficient reasons to justify granting his request for permission to withdraw his guilty plea.', 'plea', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1971677/', '1971677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court erred when it refused to allow appellant to withdraw his guilty pleas to these charges.', 'plea', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1971677/', '1971677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find appellant’s position to have merit, and we reverse those convictions set forth more specifically below which were entered contra to this constitutional provision.', 'general', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1971677/', '1971677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hereby vacate the order of the trial court denying appellant permission to withdraw his guilty pleas, which were entered on November 15, 1980, to charges under sections 3525, 3734, and 3362 of the Vehicle Code and we reverse those convictions.', 'plea', 'Commonwealth v. Johnson', 'https://www.courtlistener.com/opinion/1971677/', '1971677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prejudice was corrected by this instruction.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Merriman’s due process rights under the South Carolina Constitution and United States Constitution were not infringed upon by the trial judge’s refusal to disqualify Hogg as a witness.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Since the polygraph results would have been cumulative to evidence already before the jury, we hold that exclusion of the test was not material to the jury’s verdict.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Section 16-9-10 was, insofar as it prohibits the testimony of a convicted perjuror, repealed by implication upon the enactment of Section 19-11-60.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our prior opinion, we held that this statute, a reception of 5 Eliz.', 'general', 'State v. Merriman', 'https://www.courtlistener.com/opinion/1256390/', '1256390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on all counts except that pertaining to the alteration of identifying marks on a weapon as that conviction was premised upon an unconstitutional statutory inference.', 'general', 'Reid v. United States', 'https://www.courtlistener.com/opinion/1971980/', '1971980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On several earlier occasions, we held that aggravated assault with a dangerous weapon was a general intent crime.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/1423708/', '1423708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/1423708/', '1423708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that in such a case, a harmless error analysis must be made.', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1335935/', '1335935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review and study of the record, we conclude that the trial court did not abuse its discretion in this regard.', 'general', 'State v. Duffy', 'https://www.courtlistener.com/opinion/1431609/', '1431609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and sentence.', 'sentencing', 'State v. Duffy', 'https://www.courtlistener.com/opinion/1431609/', '1431609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having rejected appellant’s claims that the evidence was insufficient to support each of his convictions, we affirm the June 22,1995 judgment of sentence.', 'sentencing', 'Commonwealth v. Giddings', 'https://www.courtlistener.com/opinion/1462030/', '1462030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a recipient of a transfer of marijuana cannot be guilty of unlawful transfer to himself or herself either under the transfer statute or through accomplice liability.', 'general', 'State v. Cota', 'https://www.courtlistener.com/opinion/1433791/', '1433791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse because a transferee cannot transfer to himself or herself.', 'general', 'State v. Cota', 'https://www.courtlistener.com/opinion/1433791/', '1433791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the respondent, though licensed as an attorney in 1987, is relatively inexperienced in the practice of law.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/1135394/', '1135394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we conclude that a six-month suspension, in conjunction with the conditions that the respondent has assented to, constitutes an appropriate sanction in this case.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/1135394/', '1135394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is hereby ordered that Janet Lynn Moore be suspended from the practice of law for six months, effective thirty days after the date of this opinion.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/1135394/', '1135394') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that unlawful entry is also an “offense upon a person” because such statutes are designed to protect public safety as well as property.', 'general', 'Murphy v. Okeke', 'https://www.courtlistener.com/opinion/1470295/', '1470295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this understanding of the history and purpose of unlawful entry statutes to protect against violence or threats of violence against the person, in addition to protecting property rights, we conclude that an unlawful entry offense can, in some circumstances, support the entry of a CPO under the Intrafamily Offense Act.', 'general', 'Murphy v. Okeke', 'https://www.courtlistener.com/opinion/1470295/', '1470295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s entry of the CPO against Ms.', 'general', 'Murphy v. Okeke', 'https://www.courtlistener.com/opinion/1470295/', '1470295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the finding of criminal contempt against Ms.', 'general', 'Murphy v. Okeke', 'https://www.courtlistener.com/opinion/1470295/', '1470295') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Trial Court’s ultimate
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” But we concluded that any arguably due process question with respect to burden of proof of intent was “a false conflict when examined in the light of the other sections of the Criminal Code which make clear that the constitutional level of proof must be met by the State.', 'general', 'Wyant v. State', 'https://www.courtlistener.com/opinion/1516490/', '1516490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the elements of a civil malicious harassment action under Tenn.', 'general', 'Washington v. Robertson County', 'https://www.courtlistener.com/opinion/1473456/', '1473456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 4-21-701 no longer contains a specific reference to a criminal statute, we conclude that given the legislative history and intent, the elements of malicious harassment are found by examining its
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a claim of malicious harassment requires not only that a person acted maliciously, i.', 'general', 'Washington v. Robertson County', 'https://www.courtlistener.com/opinion/1473456/', '1473456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that an individual, including an employee working for a government agency, may be liable for malicious harassment pursuant to Tenn.', 'general', 'Washington v. Robertson County', 'https://www.courtlistener.com/opinion/1473456/', '1473456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a government or a government agency may be held liable for acts committed by its employees.', 'general', 'Washington v. Robertson County', 'https://www.courtlistener.com/opinion/1473456/', '1473456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we conclude that a municipality cannot be held liable
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that governmental liability in these circumstances is to be determined through the traditional doctrine of respondeat superior.', 'general', 'Washington v. Robertson County', 'https://www.courtlistener.com/opinion/1473456/', '1473456') ON CONFLICT DO NOTHING;
