INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Burriss', 'https://www.courtlistener.com/opinion/1257665/', '1257665') ON CONFLICT DO NOTHING;
