INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record, read as a whole, fails to support appellants’ claims.', 'general', 'State v. Plath', 'https://www.courtlistener.com/opinion/1337331/', '1337331') ON CONFLICT DO NOTHING;
