INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we recognize that summary judgment is an extreme remedy and rarely granted in negligence actions, we hold that the trial court did not err in granting defendant’s motion based on the facts of this case.', 'general', 'Culler v. Hamlett', 'https://www.courtlistener.com/opinion/1337375/', '1337375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the doctrine of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons herein, we affirm the trial court’s grant of summary judgment in favor of Green.', 'general', 'Culler v. Hamlett', 'https://www.courtlistener.com/opinion/1337375/', '1337375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s grant of summary judgment in favor of defendant.', 'general', 'Culler v. Hamlett', 'https://www.courtlistener.com/opinion/1337375/', '1337375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence admitted here in the light most favorable to the State, we hold that sufficient evidence was presented from which a reasonable mind could conclude that defendant constructively possessed cocaine.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/1257904/', '1257904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When the evidence showed, among other things, that defendant was found within touching distance of the crack cocaine in question and defendant’s identity documents were in the same room, we conclude that the evidence was sufficient to support the jury’s verdict.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/1257904/', '1257904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the opinion of the Court of Appeals.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/1257904/', '1257904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since enforcement of the statute under present Arizona law is impossible, we hold that A.', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1257944/', '1257944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that petitioner has presented a colorable claim, and is entitled to an evidentiary hearing on the recantation issue.', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1257944/', '1257944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we hold that the affidavits which have been submitted raise a colorable claim sufficient to entitle petitioner to an evidentiary hearing.', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1257944/', '1257944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons given below, we affirm.', 'general', 'State v. Hass', 'https://www.courtlistener.com/opinion/1405725/', '1405725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In line with the reasoning in the Supreme Court’s decision on the Alaska act, we hold that the District’s SORA is not punitive.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we hold that due process requires the government to shoulder the burden of persuasion on the factual issue that determined whether W.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the District of Columbia Sex Offender Registration Act of 1999 is not punitive and does not inflict punishment on appellants in violation of the Ex Post Facto, Double Jeopardy, or Due Process Clauses of the Constitution.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the burden of persuasion on the predicate factual issue of use of force belongs with the government.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that when a person disputes CSOSA’s finding that “certain sexual acts or contacts were forcible,” D.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Supreme Court has settled most, though not all, of the issues presented in the instant appeals.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that SORA does not infringe any fundamental rights or liberty interests of appellants and therefore is constitutional so long as it is rationally related to a legitimate governmental goal — a test the law meets easily.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the intent of the Council, like that of the Alaska Legislature, “was to create a civil, nonpunitive regime.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, having held that the District of Columbia Sex Offender Registration Act of 1999 does not violate the Ex Post Facto, Double Jeopardy, or Due Process Clauses of the Constitution, we affirm the orders of the Superior Court requiring appellants to register as sex offenders.', 'general', 'In re W.M.', 'https://www.courtlistener.com/opinion/5140695/', '5140695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the clear
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err by granting the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that sufficient evidence supported defendant’s conviction of identity theft.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/4316404/', '4316404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'reversal, we affirm.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/4316404/', '4316404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding neither argument persuasive, we affirm.', 'general', 'Olden v. United States', 'https://www.courtlistener.com/opinion/1494392/', '1494392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” charges is to be avoided and may constitute reversible error, we find that under the facts before us it was not error.', 'general', 'Britt v. State', 'https://www.courtlistener.com/opinion/1497025/', '1497025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the record designated for our consideration, and the pertinent authorities, we affirm the rulings made by the circuit court.', 'general', 'Swears v. R.M. Roach & Sons, Inc.', 'https://www.courtlistener.com/opinion/1223132/', '1223132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Mayne has not proven the existence of significant mitigating factors that would warrant departure from the sanctions we generally impose for similar misconduct.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the referee erred when he found that Mayne did not suffer from her psychological disorders during the time period in which her misconduct occurred.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Mayne’s disorders did not directly cause her misconduct, which is required under a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'analysis, we conclude that the referee did not clearly err in his causation finding.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Mayne has failed to prove that her disorders directly caused her misconduct, we conclude that she has not met her burden and is not entitled to mitigation on the basis of her psychological disorders.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'factors, we conclude that the referee clearly erred in considering Mayne’s psychological disorders as a mitigating factor.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because of the deference we give a referee’s findings, and because the record is scarce on the issue of Mayne’s remorse, we conclude that the referee did not clearly err in rejecting mitigation based on remorse.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is evidence in the record to support the finding, we conclude that the referee did not clearly err in finding Mayne’s extreme stress as a mitigating factor.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the deference we give to the findings of a referee, and because there is some evidence in the record of Mayne’s intent to pay restitution, we conclude that the referee did not clearly err in finding that Mayne was entitled to mitigation on the basis that she is making restitution.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the referee clearly erred in finding Mayne entitled to mitigation for her cooperation with the Director.', 'general', 'In Re Disciplinary Action Against Mayne', 'https://www.courtlistener.com/opinion/1588745/', '1588745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agree with the family court that contempt is not available against a deceased contemnor, we conclude that the family court did have the equitable power to award the insurance proceeds to wife, the party protected by the court’s initial order.', 'general', 'Aither v. Estate of Aither', 'https://www.courtlistener.com/opinion/1516016/', '1516016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the latter line of cases represents the better reasoning.', 'general', 'Aither v. Estate of Aither', 'https://www.courtlistener.com/opinion/1516016/', '1516016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the family court erred in dismissing wife’s motion for enforcement, and therefore reverse the family court’s decision on that motion and remand for the family court to determine whether wife is entitled to equitable relief.', 'dismissal', 'Aither v. Estate of Aither', 'https://www.courtlistener.com/opinion/1516016/', '1516016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Aither v. Estate of Aither', 'https://www.courtlistener.com/opinion/1516016/', '1516016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Our standard of factual review, although limited, requires that we conclude that a rational trier of fact could have eliminated any other reasonable interpretation except for the thoughtful desire on the part of the defendant to kill the victim.', 'general', 'State v. Bordis', 'https://www.courtlistener.com/opinion/1516950/', '1516950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that the circumstantial proof was sufficient, under the usual guidelines of review, to show that the defendant not only made a conscious decision to kill the infant victim but then, in a reasoned, purposeful, and deliberate manner carried out his designs.', 'general', 'State v. Bordis', 'https://www.courtlistener.com/opinion/1516950/', '1516950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1232, we held that it is not enough for the plaintiff to allege that he or she was "acutely upset" by the incident in question, especially where no medical assistance or counseling is sought.', 'general', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the objector could demonstrate a "special grievance" in the context of malicious use of process because of the chilling effect the applicant''s complaint had upon the objector''s First Amendment freedom of speech and right to protest.', 'general', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Franek, we held that the defendant''s remark established a prima facie basis for a claim of unlawful discrimination in an LAD-based action sufficient to withstand a summary judgment dismissal motion.', 'dismissal', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court properly dismissed this cause of action.', 'dismissal', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we conclude that the trial court properly held that plaintiff has not demonstrated a special grievance.', 'general', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court''s treatment of plaintiff''s public accommodation claims evinces an erroneous understanding of the policies underlying the provisions of the LAD and 42 U.', 'general', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As with the LAD, we find that the protective cloak of 42 U.', 'general', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" However, we reverse the dismissal of the discrimination counts, finding genuine issues of material fact exist with respect to each that would support the respective causes of action.', 'dismissal', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse its grant of summary judgment dismissing plaintiff''s causes of action under the LAD and 42 U.', 'dismissal', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons that follow, we affirm the dismissal of the claim of intentional infliction of emotional distress, finding no proof that plaintiff suffered severe emotional distress, and the malicious prosecution claim, finding no evidence of a "special grievance.', 'dismissal', 'Turner v. Wong', 'https://www.courtlistener.com/opinion/1518534/', '1518534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that on the facts of this case the photograph was improperly admitted, since the prosecution failed to establish a proper purpose for it under MRE 404(b).', 'general', 'People v. Engelman', 'https://www.courtlistener.com/opinion/1808141/', '1808141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that prior testimony that the defendant had exposed himself to two young girls and kissed the breast of one of them was not probative or material respecting the charge that he kissed the breast of an eleven-year-old girl.', 'general', 'People v. Engelman', 'https://www.courtlistener.com/opinion/1808141/', '1808141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we find that the proffered evidence does not meet the second part of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we find that the photograph does not, in the first instance, establish a scheme, plan, or system on defendant’s part, we need not discuss its probative and prejudicial characteristics.', 'general', 'People v. Engelman', 'https://www.courtlistener.com/opinion/1808141/', '1808141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that an alien may not be indicted under § 1326 more than five years after he entered or attempted to enter the United States through an official INS port of entry when the immigration authorities have a record of when he entered or attempted to enter.', 'general', 'United States v. Disantillo, Michele Romeo', 'https://www.courtlistener.com/opinion/374682/', '374682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For several reasons we conclude that the decisions relied upon by the district court do not compel the conclusion reached by that court in this case.', 'general', 'United States v. Disantillo, Michele Romeo', 'https://www.courtlistener.com/opinion/374682/', '374682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, through the exercise of our supervisory power, we hold that a party shall be informed by the magistrate that objections must be filed within ten days or further appeal is waived.', 'general', 'United States v. W. R. Walters, United States of America v. Two Hundred Sixty-Two Firearms', 'https://www.courtlistener.com/opinion/386074/', '386074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the United States Attorney, as a delegate of the Attorney General for purposes of instituting a forfeiture action, 28 U.', 'general', 'United States v. W. R. Walters, United States of America v. Two Hundred Sixty-Two Firearms', 'https://www.courtlistener.com/opinion/386074/', '386074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse the judgment of the district court and remand the case for appropriate proceedings.', 'general', 'United States v. W. R. Walters, United States of America v. Two Hundred Sixty-Two Firearms', 'https://www.courtlistener.com/opinion/386074/', '386074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, both to ensure proper notification to the client of that client’s rights upon the filing of an Anders brief and to facilitate appellate review, we hold that counsel must attach as an exhibit to the petition to withdraw filed with this Court a copy of the letter sent to counsel’s client giving notice of the client’s rights.', 'general', 'Commonwealth v. Millisock', 'https://www.courtlistener.com/opinion/5141536/', '5141536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that counsel’s petition to withdraw is deficient and, therefore, deny the motion and remand with instructions.', 'general', 'Commonwealth v. Millisock', 'https://www.courtlistener.com/opinion/5141536/', '5141536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result of the misstatement and the failure to attach a copy of the actual letter, we conclude that the petition to withdraw is deficient.', 'general', 'Commonwealth v. Millisock', 'https://www.courtlistener.com/opinion/5141536/', '5141536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated in this opinion, we conclude that possession of cocaine is a felony and therefore reverse the decision of the Court of Appeals holding otherwise.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1258697/', '1258697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that possession of cocaine is a felony and therefore can serve as an underlying felony to an habitual felon indictment.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1258697/', '1258697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it did not, and in light of other factors discussed below, we conclude that possession of cocaine is a felony.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1258697/', '1258697') ON CONFLICT DO NOTHING;
