INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that under N.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1258697/', '1258697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse in part the decision of the Court of Appeals and remand this case to that court for further remand to the Superior Court, Forsyth County, for proceedings not inconsistent with this opinion.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1258697/', '1258697') ON CONFLICT DO NOTHING;
