INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since leave to amend appears to have been denied on the grounds of futility alone, we hold that plaintiffs may amend their complaint and replead claims (1) and (4).', 'plea', 'In Re Burlington Coat Factory Securities Litigation. P. Gregory Buchanan, Jacob Turner and Ronald Abramoff', 'https://www.courtlistener.com/opinion/741725/', '741725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, since we hold that the above-mentioned claims did pass Rule 12(b)(6) we reverse the court’s denial of leave to amend on these claims.', 'general', 'In Re Burlington Coat Factory Securities Litigation. P. Gregory Buchanan, Jacob Turner and Ronald Abramoff', 'https://www.courtlistener.com/opinion/741725/', '741725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that ordinary, run-of-the-mill forecasts contain no more than the implicit representation that the forecasts were made reasonably and in good faith.', 'general', 'In Re Burlington Coat Factory Securities Litigation. P. Gregory Buchanan, Jacob Turner and Ronald Abramoff', 'https://www.courtlistener.com/opinion/741725/', '741725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Complaint survives scrutiny under Rule 12(b)(6) to the extent that it alleges: (1) that the defendants overstated BCF’s quarterly income by 2-3 cents per share in each quarter of fiscal year 1994;', 'general', 'In Re Burlington Coat Factory Securities Litigation. P. Gregory Buchanan, Jacob Turner and Ronald Abramoff', 'https://www.courtlistener.com/opinion/741725/', '741725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But, where the district court’s dismissals can be justified only on Rule 9(b) particularity grounds we reverse the denial of leave to replead.', 'dismissal', 'In Re Burlington Coat Factory Securities Litigation. P. Gregory Buchanan, Jacob Turner and Ronald Abramoff', 'https://www.courtlistener.com/opinion/741725/', '741725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s dismissals on claims (2), (3), and (5).', 'dismissal', 'In Re Burlington Coat Factory Securities Litigation. P. Gregory Buchanan, Jacob Turner and Ronald Abramoff', 'https://www.courtlistener.com/opinion/741725/', '741725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we affirm the district court’s dismissal of this claim.', 'dismissal', 'In Re Burlington Coat Factory Securities Litigation. P. Gregory Buchanan, Jacob Turner and Ronald Abramoff', 'https://www.courtlistener.com/opinion/741725/', '741725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm the district court.', 'general', 'In Re Burlington Coat Factory Securities Litigation. P. Gregory Buchanan, Jacob Turner and Ronald Abramoff', 'https://www.courtlistener.com/opinion/741725/', '741725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that evidence of prior acts becomes admissible under Rules 404(b) and 403 if it meets the following criteria: (1) The evidence must be relevant to an issue, such as an element of an offense, and must not be offered to establish the general character of the defendant.', 'general', 'United States v. Roland Demingo Queen, A/K/A Mingo', 'https://www.courtlistener.com/opinion/749879/', '749879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), we held that evidence of a defendant’s involvement in prior drug transactions was admissible to prove intent in later drug trafficking incidents.', 'general', 'United States v. Roland Demingo Queen, A/K/A Mingo', 'https://www.courtlistener.com/opinion/749879/', '749879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), we held that a conviction for an earlier assault was inadmissible to show intent for a later charge of .', 'general', 'United States v. Roland Demingo Queen, A/K/A Mingo', 'https://www.courtlistener.com/opinion/749879/', '749879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the district court properly applied both Rule 404(b) and Rule 403 and did not abuse its discretion in admitting the evidence of Queen’s prior acts.', 'general', 'United States v. Roland Demingo Queen, A/K/A Mingo', 'https://www.courtlistener.com/opinion/749879/', '749879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we have not previously addressed in any comprehensive way the issue of whether the trier of fact must find that the starting date of a conspiracy coincide with the starting date alleged in the indictment, we conclude that it need not do so.', 'general', 'United States v. Roland Demingo Queen, A/K/A Mingo', 'https://www.courtlistener.com/opinion/749879/', '749879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the instruction did not seriously impair Queen’s ability to defend himself, we need not address whether the instructions satisfied the first two elements of the test articulated in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude, after a full examination of our Rule 404(b) jurisprudence, that the district court did not abuse its discretion in admitting the evidence, and because we reject the defendant’s other assignments of error, we affirm.', 'general', 'United States v. Roland Demingo Queen, A/K/A Mingo', 'https://www.courtlistener.com/opinion/749879/', '749879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Queen’s conviction and sentence.', 'sentencing', 'United States v. Roland Demingo Queen, A/K/A Mingo', 'https://www.courtlistener.com/opinion/749879/', '749879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Because we find that a sufficient factual basis supports his voluntary plea and that his attorney was not ineffective in representing him, we affirm.', 'plea', 'Britton v. State', 'https://www.courtlistener.com/opinion/4997419/', '4997419') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although not the brief of counsel, we find that it “explains the nature of the case and .', 'general', 'United States v. Mohamed Youla, A/K/A Mohamed Fofana Mohamed Youla', 'https://www.courtlistener.com/opinion/772197/', '772197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the record, we find that Youla has raised a nonfrivolous issue with respect to his sentencing, particularly whether the District Court correctly determined the intended loss at $400,000 based the credit limit of eight credit cards.', 'sentencing', 'United States v. Mohamed Youla, A/K/A Mohamed Fofana Mohamed Youla', 'https://www.courtlistener.com/opinion/772197/', '772197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a party relies on deposition testimony in a summary judgment motion without citing to page and line numbers, the trial court may in its discretion exclude the evidence.', 'general', 'Robin Orr v. Bank of America, Nt & Sa', 'https://www.courtlistener.com/opinion/777147/', '777147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that with the exception of Exhibits A, U, and V, Orr’s exhibits are inadmissible due to inadequate authentication or hearsay.', 'general', 'Robin Orr v. Bank of America, Nt & Sa', 'https://www.courtlistener.com/opinion/777147/', '777147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Orr discovered or should have reasonably discovered the necessary facts supporting her tort claims by September 1995 and that the statute of limitations for these claims began to run at that time.', 'general', 'Robin Orr v. Bank of America, Nt & Sa', 'https://www.courtlistener.com/opinion/777147/', '777147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying California’s governmental interest test, we conclude that Nevada law, including its statute of limitations, is applicable to Orr’s tort claims.', 'general', 'Robin Orr v. Bank of America, Nt & Sa', 'https://www.courtlistener.com/opinion/777147/', '777147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Exhibits B and S are both inadmissible hearsay.', 'general', 'Robin Orr v. Bank of America, Nt & Sa', 'https://www.courtlistener.com/opinion/777147/', '777147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 1291, and we affirm.', 'general', 'Robin Orr v. Bank of America, Nt & Sa', 'https://www.courtlistener.com/opinion/777147/', '777147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Exhibits A, U, and V do not present a triable issue of material fact, we affirm the district court’s grant of summary judgment.', 'general', 'Robin Orr v. Bank of America, Nt & Sa', 'https://www.courtlistener.com/opinion/777147/', '777147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court of appeals erred in its application of the Strickland standard, and we REVERSE the judgment of that court and AFFIRM the judgment of the trial court.', 'ineffective_assistance', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2384922/', '2384922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), in which we held that a trial counsel’s assistance was not ineffective when he failed to strike or challenge, in a trial for cocaine possession, an ex-narcotics officer who knew the defendant and stated that he could not be impartial.', 'ineffective_assistance', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2384922/', '2384922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has not met his burden of showing that his trial counsel’s assistance was ineffective.', 'ineffective_assistance', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2384922/', '2384922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not abuse its discretion when it denied Okoro and Akpan’s motion for a mistrial.', 'mistrial', 'United States v. Ernest Nda Akpan Chijioke Victor Okoro, M.D., Also Known as Victor Okoro, Also Known as Chiji v. Okoro', 'https://www.courtlistener.com/opinion/790191/', '790191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was sufficient to support Okoro’s convictions on counts seven and eight.', 'general', 'United States v. Ernest Nda Akpan Chijioke Victor Okoro, M.D., Also Known as Victor Okoro, Also Known as Chiji v. Okoro', 'https://www.courtlistener.com/opinion/790191/', '790191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 962 (1990), we find that when the spread of an applicable Guideline range is less than 24 months, the district court is not required to state its reasons for imposing a sentence at a particular point within the Guideline range.', 'sentencing', 'United States v. Ernest Nda Akpan Chijioke Victor Okoro, M.D., Also Known as Victor Okoro, Also Known as Chiji v. Okoro', 'https://www.courtlistener.com/opinion/790191/', '790191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in the district court’s rulings or the jury trial, we affirm Akpan’s and Okoro’s convictions.', 'general', 'United States v. Ernest Nda Akpan Chijioke Victor Okoro, M.D., Also Known as Victor Okoro, Also Known as Chiji v. Okoro', 'https://www.courtlistener.com/opinion/790191/', '790191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Akpan’s sentence.', 'sentencing', 'United States v. Ernest Nda Akpan Chijioke Victor Okoro, M.D., Also Known as Victor Okoro, Also Known as Chiji v. Okoro', 'https://www.courtlistener.com/opinion/790191/', '790191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we AFFIRM both Okoro’s and Akpan’s convictions, as well as Akpan’s sentence.', 'sentencing', 'United States v. Ernest Nda Akpan Chijioke Victor Okoro, M.D., Also Known as Victor Okoro, Also Known as Chiji v. Okoro', 'https://www.courtlistener.com/opinion/790191/', '790191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree with the district court that there is no evidence that defendants have intimidated plaintiff or other witnesses from participating in litigation, we hold that the court did not abuse its discretion in denying preliminary relief or the request for an evidentiary hearing.', 'general', 'Matricia Moore v. Consolidated Edison Company of New York, Inc. And John Morrill', 'https://www.courtlistener.com/opinion/790403/', '790403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s conclusions that the negative evaluation was insufficient to demonstrate irreparable harm and that the claim of psychological harm was too speculative to warrant preliminary relief.', 'general', 'Matricia Moore v. Consolidated Edison Company of New York, Inc. And John Morrill', 'https://www.courtlistener.com/opinion/790403/', '790403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the instant appeal is not moot.', 'general', 'Matricia Moore v. Consolidated Edison Company of New York, Inc. And John Morrill', 'https://www.courtlistener.com/opinion/790403/', '790403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that "the amended version of MCL 780.', 'general', 'People v. Connor', 'https://www.courtlistener.com/opinion/1347823/', '1347823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'People v. Connor', 'https://www.courtlistener.com/opinion/1347823/', '1347823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Kennedy’s initial encounter with the defendant did not violate the defendant’s Fourth Amendment right against unreasonable searches and seizures.', 'search_seizure', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1347780/', '1347780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'hearing and the trial court’s findings, we conclude that the trial court’s findings of fact are supported by substantial competent evidence.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1347780/', '1347780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court was correct in denying the defendant’s motion to suppress the physical evidence seized during that search on the ground that it had been seized in violation of his Fourth
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the defendant received a fair trial free of prejudicial error.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1347780/', '1347780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, it is Ordered that the defendant’s Motion to Suppress the search and seizure of drugs and his person be and the same is hereby, Denied and Dismissed.', 'suppression', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1347780/', '1347780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is Ordered that the defendant’s Motion to Suppress statements made by the defendant after the search and seizure of scales and said drugs is hereby allowed.', 'suppression', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1347780/', '1347780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is hereby Ordered, that the evidence seized from the defendant’s person and automobile and all statements prior to the seizure of the scales and drugs shall be admissible.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1347780/', '1347780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, It is hereby Ordered, that the incriminating statements made by the defendant subsequent to the discovery and seizure of scales and drugs shall be inadmissible.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1347780/', '1347780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the statements in context, including the other evidence admitted at trial, we conclude that the statements were innocuous, not intended to inflame the jury, and not of a degree that prejudiced defendant’s right to a fair trial.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this line of questioning was relevant and did not result in any improper bolstering of prosecution witnesses.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not abuse his discretion in admitting this evidence because it was relevant to Asker’s motivation for cooperating with the government.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewed in its entirety, we conclude that it was not error.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these comments were intended to rebut the defense theory that this was a "bought” case, i.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of this evidence, we find that any error in admitting Asker’s testimony regarding the beating was harmless.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and reinstate defendant’s conviction.', 'general', 'People v. Bahoda', 'https://www.courtlistener.com/opinion/1347781/', '1347781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the structure of § 3742 and other related statutory and guideline provisions, we hold that revocation sentences should be reviewed to determine whether they are “plainly unreasonable” with regard to those § 3553(a) factors applicable to supervised release revocation sentences.', 'sentencing', 'United States v. Christopher Devon Crudup', 'https://www.courtlistener.com/opinion/795526/', '795526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d at 916, we conclude that Congress intended a distinction between the two terms.', 'general', 'United States v. Christopher Devon Crudup', 'https://www.courtlistener.com/opinion/795526/', '795526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Crudup’s sentence is not unreasonable, it necessarily follows that his sentence is not plainly unreasonable.', 'sentencing', 'United States v. Christopher Devon Crudup', 'https://www.courtlistener.com/opinion/795526/', '795526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that Crudup’s 36-month revocation sentence is not plainly unreasonable, and we affirm the judgment of the district court.', 'sentencing', 'United States v. Christopher Devon Crudup', 'https://www.courtlistener.com/opinion/795526/', '795526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'United States v. Christopher Devon Crudup', 'https://www.courtlistener.com/opinion/795526/', '795526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we decide that Crudup’s sentence is within the prescribed statutory range and is not plainly unreasonable, we affirm.', 'sentencing', 'United States v. Christopher Devon Crudup', 'https://www.courtlistener.com/opinion/795526/', '795526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the police officers’ searches were conducted under the direction and supervision of Midgette’s probation officer, we conclude that they did not violate North Carolina law.', 'general', 'United States v. Nicholas Omar Midgette', 'https://www.courtlistener.com/opinion/796984/', '796984') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Midgette failed to present his other arguments regarding the constitutionality of the North Carolina probation law and the lack of reasonable suspicion to the district judge as objections to the magistrate judge’s report, we conclude that he waived his right to appeal those issues.', 'general', 'United States v. Nicholas Omar Midgette', 'https://www.courtlistener.com/opinion/796984/', '796984') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Midgette waived his right to argue that the North Carolina probation scheme is unconstitutional and that the probation officer did not have a reasonable suspicion that Midgette possessed contraband.', 'general', 'United States v. Nicholas Omar Midgette', 'https://www.courtlistener.com/opinion/796984/', '796984') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we affirm.', 'general', 'United States v. Nicholas Omar Midgette', 'https://www.courtlistener.com/opinion/796984/', '796984') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the state substantially complied with the 20-minute rule.', 'general', 'Bagwell v. State', 'https://www.courtlistener.com/opinion/1258955/', '1258955') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bagwell v. State', 'https://www.courtlistener.com/opinion/1258955/', '1258955') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court correctly considered Campbell''s conduct in finding him guilty under § 941.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1350549/', '1350549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Wis.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1350549/', '1350549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on the protections mandated by the West Virginia Constitution, we hold that no chronic alcoholic can be criminally prosecuted for public drunkenness.', 'general', 'State Ex Rel. Harper v. Zegeer', 'https://www.courtlistener.com/opinion/1339742/', '1339742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 793 (1978), we held that this statutory provision is mandatory.', 'general', 'State Ex Rel. Harper v. Zegeer', 'https://www.courtlistener.com/opinion/1339742/', '1339742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree the statutes violate the separation-of-powers doctrine, we reverse and remand for further proceedings.', 'general', 'Klouda v. Sixth Judicial District Department of Correctional Services', 'https://www.courtlistener.com/opinion/1350712/', '1350712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on the first count and reverse and remand on the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that due process requires that an indigent defendant has an absolute right to court-appointed counsel in state-initiated paternity proceedings.', 'general', 'Carroll v. Moore', 'https://www.courtlistener.com/opinion/1347984/', '1347984') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing to Chambers, we held that “the circumstances that furnished the officers with probable cause were unanticipated and developed spontaneously.', 'probable_cause', 'State v. William L. Witt(074468)', 'https://www.courtlistener.com/opinion/2993869/', '2993869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Eckel, we held that the warrantless search of an automobile is impermissible under the search-ineident-to-arrest exception once a vehicle’s driver or occupant has been arrested, removed, and secured.', 'general', 'State v. William L. Witt(074468)', 'https://www.courtlistener.com/opinion/2993869/', '2993869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Alston, supra, we held that the automobile exception authorized the warrantless search of an automobile only when the police have probable cause to believe that the vehicle contains contraband or evidence of an offense and the circumstances giving rise to probable cause are unforeseeable and spontaneous.', 'probable_cause', 'State v. William L. Witt(074468)', 'https://www.courtlistener.com/opinion/2993869/', '2993869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it would be unfair, and contrary to our established rules, to decide the lawfulness of the stop when the State was deprived of the opportunity to establish a record that might have resolved the issue through a few questions to Officer Raeite.', 'general', 'State v. William L. Witt(074468)', 'https://www.courtlistener.com/opinion/2993869/', '2993869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed that we were keeping faith with the Chambers paradigm.', 'general', 'State v. William L. Witt(074468)', 'https://www.courtlistener.com/opinion/2993869/', '2993869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Appellate Division, which upheld the suppression of evidence in this case.', 'suppression', 'State v. William L. Witt(074468)', 'https://www.courtlistener.com/opinion/2993869/', '2993869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To substantiate that statement, the Court provided a detailed discussion of three cases: “In prior cases, such as Alston, Martin, and LaPorte, we held that the warrantless automobile searches were reasonable only because they were supported by probable cause and exigent or emergent circumstances.', 'probable_cause', 'State v. William L. Witt(074468)', 'https://www.courtlistener.com/opinion/2993869/', '2993869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we conclude that the evidence was sufficient respecting the first count but insufficient with regard to the second.', 'general', 'People v. Wolfe', 'https://www.courtlistener.com/opinion/1348841/', '1348841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*526Although the evidence of possession with intent to deliver in this case was circumstantial, we conclude that it is sufficient.', 'general', 'People v. Wolfe', 'https://www.courtlistener.com/opinion/1348841/', '1348841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of our review of the evidence, we conclude that the jury could have rationally concluded that Wolfe’s guilt of possession with intent to deliver less than fifty grams of cocaine had been proven beyond a reasonable doubt.', 'general', 'People v. Wolfe', 'https://www.courtlistener.com/opinion/1348841/', '1348841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wolfe’s presence in the apartment alone is insufficient proof of possession of a firearm during the commission of a felony.', 'general', 'People v. Wolfe', 'https://www.courtlistener.com/opinion/1348841/', '1348841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse the decision of that *528Court with respect to the charge of possession of less than 50 grams of cocaine with intent to deliver;', 'general', 'People v. Wolfe', 'https://www.courtlistener.com/opinion/1348841/', '1348841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm the decision of the Court of Appeals with respect to the felony-firearm charge;', 'general', 'People v. Wolfe', 'https://www.courtlistener.com/opinion/1348841/', '1348841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district judge’s ruling was consistent with the often cited primary sentencing
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district judge appropriately exercised his discretion in ordering Beckett to serve his sentence upon revocation of probation.', 'sentencing', 'State v. Beckett', 'https://www.courtlistener.com/opinion/1348983/', '1348983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district judge had sufficient information to decide that probation in Beckett’s case was not working and that continued probationary status would endanger the public, particularly young boys.', 'general', 'State v. Beckett', 'https://www.courtlistener.com/opinion/1348983/', '1348983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we affirm.', 'general', 'State v. Beckett', 'https://www.courtlistener.com/opinion/1348983/', '1348983') ON CONFLICT DO NOTHING;
