INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Next, we find that the circuit court did not abuse its discretion by determining that Mr.', 'general', 'State of West Virginia v. Steven Michael Williams', 'https://www.courtlistener.com/opinion/2995419/', '2995419') ON CONFLICT DO NOTHING;
