INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review, we affirm the circuit court’s ruling.', 'general', 'State of West Virginia v. Steven Michael Williams', 'https://www.courtlistener.com/opinion/2995419/', '2995419') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the appellant has failed to demonstrate that he was prejudiced by the trial judge’s ruling.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court committed prejudicial error in denying appellant’s request to charge based upon section 24-21-640, in violation of the Eighth and Fourteenth Amendments of the United States Constitution and Article V, § 21, of the South Carolina Constitution.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse appellant’s death sentence and remand for a new sentencing proceeding.', 'sentencing', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and sentence of life imprisonment, reverse the death sentence, and remand for a new sentencing proceeding.', 'sentencing', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
