INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse the Court of Appeals’ decision finding the trial court should have granted a directed
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals’ decision finding the trial court should have granted a directed verdict on the charge of breach of peace.', 'general', 'In the Interest of Jeremiah W.', 'https://www.courtlistener.com/opinion/1359932/', '1359932') ON CONFLICT DO NOTHING;
