INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Therefore, we hold that the State Transport Officer merely assisted in facilitating the traffic stop.', 'general', 'State v. Landis', 'https://www.courtlistener.com/opinion/1360237/', '1360237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the statute does not specify to whom the arresting officer should submit the affidavit, we hold that whether the affidavit has been submitted is not an issue when it has undisputedly been prepared and is in defense counsel’s possession at trial.', 'general', 'State v. Landis', 'https://www.courtlistener.com/opinion/1360237/', '1360237') ON CONFLICT DO NOTHING;
