INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 785, we reversed the judgment convicting Garland of possession of the contraband.', 'general', 'Drew v. Commonwealth', 'https://www.courtlistener.com/opinion/1363879/', '1363879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the rules reconciled and the principles established in Ward and summarized by contemporary commentators, we hold that actual harm or prejudice to the rights of another was not an element of the crime of forgery of public records at English common law and that, pursuant to Code §§ 1-10 and -11, this became the law of this Commonwealth.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1364586/', '1364586') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that ‘ ‘there was no error in giving and refusing the instructions set forth in the first bill of exceptions.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1364586/', '1364586') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, while this Court held that the harm-or-prejudice issue was preserved at trial, nothing in the opinion suggests that it was raised on appeal by either party.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1364586/', '1364586') ON CONFLICT DO NOTHING;
