INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in result.', 'general', 'State v. McGowan', 'https://www.courtlistener.com/opinion/1365625/', '1365625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the record demonstrates that Appellant was confined for at least 187 days, we hold that the district court abused its discretion by awarding a credit of only 114 days toward Appellant’s kidnapping sentence.', 'sentencing', 'Eustice v. State', 'https://www.courtlistener.com/opinion/1366798/', '1366798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Eustice v. State', 'https://www.courtlistener.com/opinion/1366798/', '1366798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court erred in holding that the juvenile court did not have jurisdiction over the charges laid against Zamora;', 'general', 'Zamora v. State', 'https://www.courtlistener.com/opinion/1367475/', '1367475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the relevant statutes, we conclude that the juvenile court did have original jurisdiction over the criminal charges alleged to have been committed by Zamora.', 'general', 'Zamora v. State', 'https://www.courtlistener.com/opinion/1367475/', '1367475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1001, we conclude that the court did not abuse its discretion when it waived jurisdiction based upon the seriousness of the offense and the maturity factor.', 'general', 'Zamora v. State', 'https://www.courtlistener.com/opinion/1367475/', '1367475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the magistrate’s order waiving jurisdiction and remand the cause for further proceedings not inconsistent with this opinion.', 'general', 'Zamora v. State', 'https://www.courtlistener.com/opinion/1367475/', '1367475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that under article 2, sections 4, 23, and 24 of the Arizona Constitution and the sixth and fourteenth amendments of the United States Constitution, Powers had a right to trial by jury under the reasonable doubt standard on the question of whether he had escaped.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1369114/', '1369114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we held that release status need not be found by a jury nor found beyond a reasonable doubt.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1369114/', '1369114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we conclude that although release status determination may be made by a court by a lesser standard of proof without violating constitutional guarantees
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that although release status determination involves a factual finding, the status is not an element of the crime, but only a sentence enhancer.', 'sentencing', 'State v. Powers', 'https://www.courtlistener.com/opinion/1369114/', '1369114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding none, we affirm the remainder of the proceedings.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1369114/', '1369114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the district court adequately and properly
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we conclude that Scott’s 135-month sentence is reasonable.', 'sentencing', 'United States v. David William Scott', 'https://www.courtlistener.com/opinion/77090/', '77090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review, we affirm.', 'general', 'United States v. David William Scott', 'https://www.courtlistener.com/opinion/77090/', '77090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in setting aside its sentence of Kido and that Kido’s cross-appeal is untimely.', 'sentencing', 'State v. Kido', 'https://www.courtlistener.com/opinion/1369949/', '1369949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that Kido’s appeal of the April 30,1981 Decision and Order and the May 1,1981 Judgmentis untimely.', 'general', 'State v. Kido', 'https://www.courtlistener.com/opinion/1369949/', '1369949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the September 15, 1981 Judgment, order the reinstatement of the May 1,1981 Judgment, and remand for issuance of the mittimus.', 'general', 'State v. Kido', 'https://www.courtlistener.com/opinion/1369949/', '1369949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial judge on this issue.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse his conviction of possession with intent to distribute marijuana and remand for a new trial based on the trial judge’s burden-shifting jury instructions.', 'jury_instruction', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial judge’s ruling in this matter and hold that the taped conversations between Appellant and Johnson were properly admitted into evidence.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Appellant’s conviction of distribution of marijuana.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial judge’s instruction that possession of more than 28 grams or one ounce of marijuana was prima facie evidence of guilt of the charge of possession with intent to distribute marijuana constitutes an impermissible presumption which shifted the burden of proof from the State to Appellant.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the use of the computer network of an e-mail service provider or its subscribers is an integral part of the crime charged and because the use of AOL''s e-mail servers was the "immediate result" of Jaynes'' acts, we hold that Jaynes was amenable to prosecution in Virginia for a violation of Code § 18.', 'general', 'Jaynes v. Com.', 'https://www.courtlistener.com/opinion/1374657/', '1374657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the circuit court had jurisdiction over Jaynes.', 'general', 'Jaynes v. Com.', 'https://www.courtlistener.com/opinion/1374657/', '1374657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that Jaynes'' vagueness argument is without merit, and the statute does not violate the Commerce Clause.', 'general', 'Jaynes v. Com.', 'https://www.courtlistener.com/opinion/1374657/', '1374657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our standard of review to the evidence presented along with all reasonable inferences therefrom, we conclude that the evidence supports the conclusion that Jaynes knew and intended that the e-mails he sent to AOL subscribers would utilize AOL''s servers which are located in Virginia.', 'general', 'Jaynes v. Com.', 'https://www.courtlistener.com/opinion/1374657/', '1374657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Code § 18.', 'general', 'Jaynes v. Com.', 'https://www.courtlistener.com/opinion/1374657/', '1374657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we concluded that the discrete crime of drug distribution was committed by the defendant while in Arizona and that the ultimate sale of the drugs in Virginia was not the "immediate result" of the distribution of drugs in Arizona because the subsequent distributions by Moreno''s accomplices intervened.', 'general', 'Jaynes v. Com.', 'https://www.courtlistener.com/opinion/1374657/', '1374657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Jaynes has no standing to raise a First Amendment objection to Code § 18.', 'general', 'Jaynes v. Com.', 'https://www.courtlistener.com/opinion/1374657/', '1374657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that double jeopardy does not bar the State from prosecuting defendant under section 14-208.', 'general', 'State v. Sparks', 'https://www.courtlistener.com/opinion/1374720/', '1374720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a post-release revocation hearing is not a criminal prosecution.', 'general', 'State v. Sparks', 'https://www.courtlistener.com/opinion/1374720/', '1374720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that revocation of defendant’s post-release and reinstatement of the time remaining on his original sentence result from defendant’s original felony convictions and not from his conduct which triggered the revocation, absconding from his post-release officer.', 'sentencing', 'State v. Sparks', 'https://www.courtlistener.com/opinion/1374720/', '1374720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Sparks', 'https://www.courtlistener.com/opinion/1374720/', '1374720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in the instant case, we affirm the Court of Appeals and hold that the State may criminally prosecute defendant pursuant to N.', 'general', 'State v. Sparks', 'https://www.courtlistener.com/opinion/1374720/', '1374720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), this Court held that the victim’s resistance to the defendant’s attempted sexual assault was a circumstance which made the consummation of the crime more difficult.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1375337/', '1375337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that sufficient evidence supported the jury’s decision.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1375337/', '1375337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1375337/', '1375337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court was “wrong” in concluding that the discussion “fell under the attorney-client privilege[] and [was] not subject to revelation to the police or prosecution” (COL 1 of Order No.', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/1375619/', '1375619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we hold that it was not.', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/1375619/', '1375619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There being no violation of the sixth amendment to the United States Constitution or article I, section 14 of the Hawaii Constitution, we hold that COLs 2, 4, and 6 of Order No.', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/1375619/', '1375619') ON CONFLICT DO NOTHING;
