INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the attorney-client privilege was not applicable to the communications in question because they were not “confidential,” but, rather, were “voluntarily disclosed,”
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that it necessarily “is a class C felony” for sentencing purposes.', 'sentencing', 'State v. Soto', 'https://www.courtlistener.com/opinion/1375619/', '1375619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that, for sentencing purposes, criminal solicitation of first degree murder is a class C felony, subject to the sentencing provisions of HRS § 706-660,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Balancing these competing concerns, we conclude that[,] in order to make a prima facie showing of prejudice^] the defendant must prove that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the circuit court’s Order No.', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/1375619/', '1375619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Lau’s intrusion into the “courthouse hallway discussion” occurred “under circumstances indicating that the .', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/1375619/', '1375619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that because the defendant failed to make any effort or attempt to reconstruct, modify, or supplement the record,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, although the term “associated with” is broad, it is not unconstitutionally vague under the.', 'general', 'State v. Bates', 'https://www.courtlistener.com/opinion/1375634/', '1375634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the broad discretion accorded to a trial court, we hold that the court did not abuse its discretion in permitting the introduction of this evidence because the probative value of this impeachment evidence outweighed any substantial evidence to the defendant.', 'general', 'State v. Bates', 'https://www.courtlistener.com/opinion/1375634/', '1375634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that a prosecutor’s closing remark that, “[w]hen the defendant comes in here and tells you that he was not on cocaine that night, that just—it’s a cockamamie story and it’s asking you to take yourselves as fools[,]” was proper because it represented a fair characterization of the evidence presented against the defendant.', 'general', 'State v. Bates', 'https://www.courtlistener.com/opinion/1375634/', '1375634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does.', 'general', 'State v. Bates', 'https://www.courtlistener.com/opinion/1375634/', '1375634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the statements presented, we conclude that they represent reasonable inferences drawn from the evidence regarding the defendant’s credibility and the.', 'general', 'State v. Bates', 'https://www.courtlistener.com/opinion/1375634/', '1375634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the record, statutes, and applicable case law, we affirm the defendant’s convictions on both counts.', 'general', 'State v. Bates', 'https://www.courtlistener.com/opinion/1375634/', '1375634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm the judgment of the trial court and affirm the defendant’s convictions on all counts.', 'general', 'State v. Bates', 'https://www.courtlistener.com/opinion/1375634/', '1375634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is appropriate for us to review the invited error exception to the admission of otherwise inadmissible evidence in this case.', 'general', 'State v. Palenkas', 'https://www.courtlistener.com/opinion/1375705/', '1375705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that no invited error occurred that would justify the prosecution’s conduct in this case.', 'general', 'State v. Palenkas', 'https://www.courtlistener.com/opinion/1375705/', '1375705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecution’s references to defendant’s invocation of his fourth amendment rights to refuse to consent to a warrantless entry and to his contact with an attorney prior to his arrest violated defendant’s due process rights to a fair trial.', 'search_seizure', 'State v. Palenkas', 'https://www.courtlistener.com/opinion/1375705/', '1375705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these comments were highly improper in at least two respects.', 'general', 'State v. Palenkas', 'https://www.courtlistener.com/opinion/1375705/', '1375705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s use of this evidence violated defendant’s due process rights to a fair trial, and the error was not harmless beyond a reasonable doubt.', 'general', 'State v. Palenkas', 'https://www.courtlistener.com/opinion/1375705/', '1375705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the prosecutor’s conduct, not invited by defendant, resulted in prejudicial, fundamental unfairness that violated defendant’s right to due process, we reverse and remand for new trial.', 'general', 'State v. Palenkas', 'https://www.courtlistener.com/opinion/1375705/', '1375705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 104 (1999), this Court held that a person can be acting lawfully, even if he is in unlawful possession of a weapon, if he was entitled to arm himself in self-defense at the time of the shooting.', 'general', 'State v. Crosby', 'https://www.courtlistener.com/opinion/1376034/', '1376034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Crosby', 'https://www.courtlistener.com/opinion/1376034/', '1376034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that neither federal nor state due process clauses empower us to intervene and supervise the pending impeachment proceedings.', 'general', 'Mecham v. Gordon', 'https://www.courtlistener.com/opinion/1377672/', '1377672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the application of HRS § 291-4 to Davia was not “absurd” and that the “literal” meaning of the statutory language should be followed.', 'general', 'State v. Davia', 'https://www.courtlistener.com/opinion/1379172/', '1379172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being the ease, we hold that HRS § 291—4(b) does not offend the eighth amendment to the United States Constitution or article I, section 12 of the Hawai''i Constitution.', 'general', 'State v. Davia', 'https://www.courtlistener.com/opinion/1379172/', '1379172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1010, 1012 (1986), this court held that the trial court’s failure to comply with HRPP Rule 11(c) and (d) constituted plain error.', 'general', 'State v. Davia', 'https://www.courtlistener.com/opinion/1379172/', '1379172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that appellant knew the consequences of his decision to proceed pro se and that the circumstances of his trial were self-created, we affirm.', 'general', 'Mapp v. State', 'https://www.courtlistener.com/opinion/1379005/', '1379005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Mapp’s conviction.', 'general', 'Mapp v. State', 'https://www.courtlistener.com/opinion/1379005/', '1379005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the ICA erred in dismissing the present appeal for lack of appellate jurisdiction.', 'dismissal', 'State v. Kalani', 'https://www.courtlistener.com/opinion/1379009/', '1379009') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Lollis', 'https://www.courtlistener.com/opinion/1379102/', '1379102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we REVERSE the Court of Appeals’ decision.', 'general', 'State v. Lollis', 'https://www.courtlistener.com/opinion/1379102/', '1379102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record supports Judge Saunders’ conclusion that retrial was not barred by double jeopardy provisions in the federal constitution or by the “law of the land” clause in the state constitution, and that it was not error to deny defendant’s motion.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1379649/', '1379649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 14-87, the long-standing and extensive case law interpreting this statutory section and establishing our former rule that larceny is a lesser included offense of armed robbery, and the natural relationship between armed robbery and larceny, we hold that larceny is a lesser included offense of armed robbery, and we overrule State v.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1379649/', '1379649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only recently have we held that felonious larceny is not a lesser included offense of armed robbery.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1379649/', '1379649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 550, we held that common law robbery is a lesser offense of armed robbery but not of attempted armed robbery, and that attempted common law robbery is a lesser offense of attempted armed robbery.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1379649/', '1379649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that test here, we conclude that the trial court did not err in denying defendant’s motion to dismiss on grounds of double jeopardy.', 'dismissal', 'State v. White', 'https://www.courtlistener.com/opinion/1379649/', '1379649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that larceny is a lesser included offense of armed robbery.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1379649/', '1379649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the Court of Appeals.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1379649/', '1379649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 14-87, the long-standing and extensive case law interpreting this statutory section and establishing our former rule that larceny is a lesser included offense of armed robbery, and the natural relationship between armed robbery and larceny, we hold that larceny is a lesser included offense of armed robbery.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1379649/', '1379649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the re-entry into a continuing conspiracy subsequent to the defendant’s arrest is, for purposes of double jeopardy, the formation of a new agreement.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/1389694/', '1389694') ON CONFLICT DO NOTHING;
