INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion by admitting in evidence testimony concerning Appellant’s two prior acts.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that the court’s comments to Appellant were entirely appropriate under the circumstances.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a person can be convicted of third-degree criminal trespass on public property pursuant to A.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/1387278/', '1387278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'review we hold that defendant played a major role in the murders of D’Brito and Cady, even though he did not do the actual killing.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “the trial judge must determine beyond a reasonable doubt prior to imposing a sentence of death that the defendant killed, attempted to kill or intended to kill.', 'sentencing', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that defendant’s age of 20 was not sufficiently substantial given the extent and duration of his participation.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have also considered the mitigating circumstances offered by defendant, and we conclude that even in combination the mitigating circumstances are not sufficiently substantial to call for leniency.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial judge did not err in finding that defendant had a prior felony conviction involving use or threat of violence against another person.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we find that the trial judge applied the new aggravating circumstance to murders which occurred before the effective date of this aggravating circumstance and that the amendment is a substantive, rather than a procedural, change.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that none of these factors, alone or in combination, are sufficiently substantial to call for leniency.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial judge stated sufficiently for the record his finding of cruel, heinous and depraved applied separately to each victim.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these crimes were above the norm of first degree murders and that defendant, because of his prior convictions for crimes involving violence, is above the norm of first degree murderers.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that defendant’s age of 16 was sufficiently substantial to call for life imprisonment despite the presence of aggravating factors under A.', 'general', 'State v. Correll', 'https://www.courtlistener.com/opinion/1387659/', '1387659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Christian failed to demonstrate that the challenged jury instructions represented an obvious transgression of a clear and unequivocal rule of law constituting plain error.', 'jury_instruction', 'Christian v. State', 'https://www.courtlistener.com/opinion/1388814/', '1388814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Christian v. State', 'https://www.courtlistener.com/opinion/1388814/', '1388814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the case before us, we hold that Detective Pantke’s questioning of defendant Eastlack was entirely proper and was squarely within the boundaries set by both the majority opinion and the concurrence in Davis.', 'general', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite what may have been dilatory behavior on the part of defense counsel, we hold that, under the peculiar facts and circumstances of this case, it was improper to proceed to sentencing without providing defendant the opportunity of expert assistance.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that the trial court was well within its discretion in denying the motion for mistrial.', 'mistrial', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of circumstances, we conclude that the present sentences must be vacated and remanded for resentencing after the appointment of an appropriate expert to assist defendant in determining whether there is additional mitigating evidence to be presented and, if so, to assist defendant in presenting it.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all factors, we conclude that the appointment of an independent expert might well have produced mitigating evidence.', 'general', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'a jury may be misled by an instruction placing undue emphasis on the rapidity with which premeditation can occur____ However, jury instructions must be considered as a whole— A case will not be reversed because some isolated portion of an instruction might be misleading____ Although we have problems with the “no appreciable space of time” language, we find that the remaining portions of the instructions clarified the definition of premeditation.', 'jury_instruction', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having thoroughly reviewed the record, we find that defendant had the constitutional and statutory right to the assistance of proper psychological testing and expert assistance.', 'general', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons we develop more fully below, we affirm all of defendant’s convictions but remand for resentencing.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial judge should have continued the sentencing hearing, done whatever was necessary to regularize the proceedings, and arranged for the appointment of an appropriate expert at reasonable cost before proceeding to sentencing in tMs capital case.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Apelt, the defendant moved to continue his sentencing hearing claiming that he was unable to adequately prepare, but we affirmed the trial judge’s denial of that motion.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a private citizen may not use force to resist peaceful arrest by one he knows or has good reason to believe is an authorized peace officer performing his duties, regardless of whether the arrest is illegal in the circumstances of the occasion.', 'general', 'People v. Hess', 'https://www.courtlistener.com/opinion/1389399/', '1389399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a person may not use force to resist being placed under arrest or in protective custody by a police officer engaged in the performance of his duties, regardless of whether the police conduct is unlawful.', 'general', 'People v. Hess', 'https://www.courtlistener.com/opinion/1389399/', '1389399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed in Part II, we conclude that the trial court erred in dismissing the case.', 'dismissal', 'People v. Hess', 'https://www.courtlistener.com/opinion/1389399/', '1389399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if the stop or the taking into protective custody was unlawful, we conclude that the defendant had no right to resist an arrest and therefore dismissal was an inappropriate remedy.', 'dismissal', 'People v. Hess', 'https://www.courtlistener.com/opinion/1389399/', '1389399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'People v. Hess', 'https://www.courtlistener.com/opinion/1389399/', '1389399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with our prior holdings, we conclude that defendant’s first-degree murder convictions based on premeditated and deliberate murder should be vacated.', 'general', 'State v. Millsaps', 'https://www.courtlistener.com/opinion/1389515/', '1389515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, based upon the totality of the circumstances, a reasonable person in defendant’s position would not have believed that he was under arrest or that he was restrained to a degree that would cause him to believe he was formally arrested.', 'general', 'State v. Barden', 'https://www.courtlistener.com/opinion/1389649/', '1389649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that, based upon the totality of the circumstances, defendant gave the statements voluntarily.', 'general', 'State v. Barden', 'https://www.courtlistener.com/opinion/1389649/', '1389649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we hold that the trial court’s conclusions of law were correct.', 'general', 'State v. Barden', 'https://www.courtlistener.com/opinion/1389649/', '1389649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, although we acknowledge that the issue is a close one, we hold that the trial court’s conclusion that defendant failed to present a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that defendant has failed to properly preserve these issues for review by this Court.', 'general', 'State v. Barden', 'https://www.courtlistener.com/opinion/1389649/', '1389649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'record, we hold that the trial court did not err in failing to intervene
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we hold that the trial court did not abuse its discretion in overruling defendant’s objection.', 'general', 'State v. Barden', 'https://www.courtlistener.com/opinion/1389649/', '1389649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the full transcript and the context in which these comments were made, we hold that the statements were not so grossly improper that the trial court should have intervened
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the prosecutor properly argued to the jury that it was the voice and moral conscience of the community without suggesting that the jury “lend an ear to the community.', 'general', 'State v. Barden', 'https://www.courtlistener.com/opinion/1389649/', '1389649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the record, we hold that the trial court did not abuse its discretion in overruling defendant’s objections to the argument.', 'general', 'State v. Barden', 'https://www.courtlistener.com/opinion/1389649/', '1389649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this evidence
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of any evidence explaining that Wells’ continued absence resulted from duress, or otherwise justifying Wells’ continuing absence, we hold that the trial court did not err in refusing to instruct the jury on the defense of necessity.', 'general', 'Wells v. State', 'https://www.courtlistener.com/opinion/1389764/', '1389764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that AS 12.', 'general', 'Wells v. State', 'https://www.courtlistener.com/opinion/1389764/', '1389764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a person’s age, which determines whether he would have been subject to juvenile or adult prosecution in Alaska, was not an element of an offense within the meaning of AS 12.', 'general', 'Wells v. State', 'https://www.courtlistener.com/opinion/1389764/', '1389764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We decline the invitation because we find that Wells failed to prove a bona-fide effort to return to custody.', 'general', 'Wells v. State', 'https://www.courtlistener.com/opinion/1389764/', '1389764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Wells v. State', 'https://www.courtlistener.com/opinion/1389764/', '1389764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reversed the incest convictions, there are no priors and the sentencing range for the sexual exploitation has been reduced from 14 to 28 years (class II felony with two prior convictions) to 5.', 'sentencing', 'State v. Lindsey', 'https://www.courtlistener.com/opinion/1390040/', '1390040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the exploitation counts do not turn on the question of credibility and are supported by overwhelming evidence, we affirm the conviction and sentence on those six counts.', 'sentencing', 'State v. Lindsey', 'https://www.courtlistener.com/opinion/1390040/', '1390040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the overwhelming and uncontroverted evidence against the defendant, we find that the error was not prejudicial and that the jury, beyond a reasonable doubt, would still have found the defendant guilty even if the prejudicial testimony had not been heard.', 'general', 'State v. Mulalley', 'https://www.courtlistener.com/opinion/1391602/', '1391602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 13-1206, and the severity with which a number of our sister states would punish one in the defendant’s situation, we find that the life sentence mandated by the statute is not so disproportionate as to violate the prohibitions against cruel and unusual punishment in our state and federal constitutions.', 'sentencing', 'State v. Mulalley', 'https://www.courtlistener.com/opinion/1391602/', '1391602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that A.', 'general', 'State v. Mulalley', 'https://www.courtlistener.com/opinion/1391602/', '1391602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in concluding that defendant’s inculpatory statement was admissible.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a defendant requests the trial court to instruct the jury that it may consider the mental condition of the defendant in deciding whether she formed a premeditated and deliberate specific intent to kill the victim, there must be sufficient evidence “reasonably to warrant inference of the fact at issue.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in refusing to charge the jury on murder in the second degree.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the sentencing court’s failure to find this mitigating factor was error.', 'sentencing', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the trial court had properly determined this testimony admissible under Rule 704 of the North Carolina Rules of Evidence and that, as such, defendant was entitled to a jury instruction on this element of the crime.', 'jury_instruction', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, with regard to the conviction of conspiracy we conclude that the sentencing court’s erroneous failure to consider a statutory mitigating factor entitles defendant to a new sentencing hearing.', 'sentencing', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under this test, we conclude that the trial court in the case sub judice did not err in refusing to instruct the jury that it could consider evidence of defendant’s mental disorder as rendering her incapable of forming the specific intent to kill.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 641 (1960), this Court held that: “Due process of law, within the meaning of the State and Federal constitutional provisions, extends to actions of administrative officers and tribunals, as well as to the judicial branches of the governments.', 'general', 'State v. Spade', 'https://www.courtlistener.com/opinion/1394025/', '1394025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this fact, we find that the interests of judicial economy and finality require us to render a decision on this issue instead of remanding the case to the circuit court and waiting for it to come before us on a second appeal.', 'general', 'State v. Spade', 'https://www.courtlistener.com/opinion/1394025/', '1394025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this sentence was not clearly mistaken.', 'sentencing', 'Jones v. State', 'https://www.courtlistener.com/opinion/1394803/', '1394803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Parole Board failed to abide by the enumerated time limits within which to hold Valentine’s final revocation hearing, we conclude that, if his conduct so warranted, he was entitled to receive good time credit for the additional time he was detained in the Marion County Jail as a result of the Parole Board’s delay.', 'general', 'State Ex Rel. Valentine v. Watkins', 'https://www.courtlistener.com/opinion/1396259/', '1396259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the Parole Board failed to conduct Valentine’s parole revocation hearing within the time allowed for such a proceeding, we find that he is entitled to good time credit for that period of his detention necessitated by the Parole Board’s delay.', 'general', 'State Ex Rel. Valentine v. Watkins', 'https://www.courtlistener.com/opinion/1396259/', '1396259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that, under Studer v.', 'general', 'Teal v. State', 'https://www.courtlistener.com/opinion/1396275/', '1396275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,45 this Court held that “a written instrument is an indictment or information under the Constitution if it accuses someone of a crime with enough clarity and specificity to identify the penal statute under which the State intends to prosecute, even if the instrument is otherwise defective.', 'general', 'Teal v. State', 'https://www.courtlistener.com/opinion/1396275/', '1396275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as to the firearm charge and reverse as to the convictions of receiving stolen goods.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1158630/', '1158630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we affirm as to the conviction for carrying a pistol, we address that issue first.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1158630/', '1158630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the conviction for carrying a pistol.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1158630/', '1158630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm Henderson’s conviction for carrying a pistol, and reverse the convictions for receiving stolen goods.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1158630/', '1158630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was insufficient evidence to justify a protective order;', 'general', 'Wolfe v. Wolfe', 'https://www.courtlistener.com/opinion/5046958/', '5046958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we reverse and render the judgment of the chancery court.', 'general', 'Wolfe v. Wolfe', 'https://www.courtlistener.com/opinion/5046958/', '5046958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse and render the chancery court’s entry of a Mississippi protective order.', 'general', 'Wolfe v. Wolfe', 'https://www.courtlistener.com/opinion/5046958/', '5046958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed, we reverse and render the judgment of the chancery court.', 'general', 'Wolfe v. Wolfe', 'https://www.courtlistener.com/opinion/5046958/', '5046958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the New Jersey Constitution, citizens have a reasonable expectation of privacy in bank records.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the New Jersey *33Constitution recognizes an account holder’s interest in the privacy of his or her bank records.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', when the government seeks bank records on file with a bank — we hold that the issuance of a grand jury subpoena duces tecum based on a relevancy standard satisfies the constitutional prohibition against improper government intrusion.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, in Novembrino, we held that our Constitution, unlike the Federal Constitution, does not afford law enforcement a “good faith” exception to the exclusionary rule.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hunt, supra, we held that citizens had a protectable interest in their long distance phone records even though those records were in possession of the telephone company.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that existing grand jury subpoena procedures sufficiently protect that expectation of privacy.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that New Jersey citizens have a reasonable expectation of privacy in their bank records, circumstances will arise that justify State intrusion upon that interest.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that notice is not constitutionally mandated, we believe that further study is warranted to assess whether a notice requirement reflects good policy.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm in part, reverse in part, and affirm defendant’s conviction.', 'general', 'State v. McAllister', 'https://www.courtlistener.com/opinion/1475083/', '1475083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial judge did not err in failing to direct a verdict of not guilty to second degree arson;', 'general', 'State v. Glenn', 'https://www.courtlistener.com/opinion/1401171/', '1401171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that ample evidence existed that Mrs.', 'general', 'State v. Glenn', 'https://www.courtlistener.com/opinion/1401171/', '1401171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the tenants vacated the apartment with no intention of returning, we found that the apartment was not a dwelling house, and, therefore, not capable of being burglarized.', 'general', 'State v. Glenn', 'https://www.courtlistener.com/opinion/1401171/', '1401171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm her conviction and sentence.', 'sentencing', 'State v. Glenn', 'https://www.courtlistener.com/opinion/1401171/', '1401171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Under these circumstances, we hold that DHS received notice comporting with due process and the requirements of Ark.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the particular facts of this case, we hold that Doherty had notice of the accusation that otherwise comported with the requirements of section 16-10-108 and due process of law.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that DHS must first attempt to obtain relief in the trial court.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, we conclude that DHS has standing and has filed a timely notice of appeal from the trial court’s order denying its motion to set aside the September 30 order.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that the trial court is empowered to order family services in FINS cases to prevent a juvenile from being removed from a parent, which by definition includes cash assistance, we conclude that the General Assembly’has specifically waived sovereign immunity as to DHS in such instances.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reasons expressed as to DHS above, we affirm the trial court here.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the anti-abrogation clause is not implicated by the EPA because the cause of action which it allegedly abrogates — wrongful termination in violation of public policy expressed in ACRA — originates exclusively within the statute, would not otherwise exist, and cannot trace its antecedents to a common law right of action.', 'general', 'Cronin v. Sheldon', 'https://www.courtlistener.com/opinion/1402780/', '1402780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶57 For the reasons set forth, we hold that the preámble to the EPA, though unconstitutional on its face, does not implicate the constitutionality of the statutory text.', 'general', 'Cronin v. Sheldon', 'https://www.courtlistener.com/opinion/1402780/', '1402780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'a common law negligence action for medical malpractice, we held that a statute permitting the defendant to make periodic payments rather than the traditional lump sum payment of the verdict violated the non-limitation clause.', 'general', 'Cronin v. Sheldon', 'https://www.courtlistener.com/opinion/1402780/', '1402780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we affirm the constitutionality of the challenged provisions of the EPA and uphold the superior court’s judgment of dismissal against Cronin and the summary judgment against Finley on their respective wrongful discharge claims.', 'dismissal', 'Cronin v. Sheldon', 'https://www.courtlistener.com/opinion/1402780/', '1402780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was not.', 'general', 'State v. Barron', 'https://www.courtlistener.com/opinion/1405172/', '1405172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State’s evidence showed nothing more than “[Djefendant had been in an area where he could have committed the crimes charged,” and was insufficient to send the charge of possession of controlled substances to the jury.', 'general', 'State v. Barron', 'https://www.courtlistener.com/opinion/1405172/', '1405172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Defendant’s active acknowledgment to Armstead that the last four digits of his social security number were “2301” was a “use [of] identifying information” of another person within the meaning of N.', 'general', 'State v. Barron', 'https://www.courtlistener.com/opinion/1405172/', '1405172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the evidence presented at Appellant’s trial, we conclude that the State did not meet this burden in the instant matter.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1406110/', '1406110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the record before this Court, including detailed examination of the transcript of Appellant’s November 29, 2005, trial, applicable precedent and the arguments *436of the parties, we reverse Appellant’s conviction.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1406110/', '1406110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse both convictions.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1406110/', '1406110') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the court erred when it initiated the contempt proceeding.', 'general', 'Alfred v. State', 'https://www.courtlistener.com/opinion/1406155/', '1406155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Alfred v. State', 'https://www.courtlistener.com/opinion/1406155/', '1406155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking at the insignificant error in instructions “6” and “8” in relation to the uncontroverted facts supporting the jury’s verdict and counsel’s failure to alert the court to non-compliance with MAI, we hold that submission of these verdict directors did not prejudice appellant.', 'general', 'State v. Green', 'https://www.courtlistener.com/opinion/1523002/', '1523002') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the offense as defined by the statute is not a specific intent crime;', 'general', 'Fleming v. Commonwealth', 'https://www.courtlistener.com/opinion/1410265/', '1410265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm that conviction.', 'general', 'Fleming v. Commonwealth', 'https://www.courtlistener.com/opinion/1410265/', '1410265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the employee did not lawfully possess or control the misappropriated funds and therefore affirm the decision of the Court of Appeals which reversed defendant’s convictions.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/1411993/', '1411993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Kimberly Weaver never lawfully “possessed” the misappropriated funds and because the funds were not “under [her] care” we conclude that Kimberly Weaver did not commit the crime of embezzlement as defined in N.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/1411993/', '1411993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the evidence presented at trial does not support defendant’s conviction for the crime of embezzlement.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/1411993/', '1411993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on that decision, and on the context in which the phrase “great bodily harm” was used in this case, we hold that the information was sufficient.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1414463/', '1414463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he was not.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1414463/', '1414463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge did not abuse his discretion by refusing to exclude it from evidence.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1414463/', '1414463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was substantial evidence to show that a battery had oc
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons explained below, we affirm the judgment of conviction.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1414463/', '1414463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that, absent specific evidence that a defendant has actually tailored his or her testimony to fit the evidence, it is misconduct for a prosecutor to imply that a defendant is less believable because he or she has exercised the right of confrontation.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1728460/', '1728460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we conclude that the prosecutor’s cross-examination of Davis, which suggested that Davis’s presence at trial allowed Davis to tailor his testimony to fit the evidence, constituted misconduct, we also conclude that the misconduct did not affect Davis’s substantial rights.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1728460/', '1728460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'was decided before Rule 609 became effective, we conclude that these factors remain suitable and we reaffirm their application in determining whether the probative value outweighs the prejudice under the rule.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1728460/', '1728460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'factors to the five convictions the district court found admissible, we conclude that the district court did not abuse its discretion in determining that the probative value of the convictions outweighed the potential for unfair prejudice.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1728460/', '1728460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the record is devoid of any evidence from which it could be inferred that Davis tailored his testimony to fit the evidence.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1728460/', '1728460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the prosecutor’s arguments were at times expressed in colorful terms, we conclude that the arguments did not constitute error and thus did not involve misconduct.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1728460/', '1728460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm Davis’s convictions.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1728460/', '1728460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Syllabus Point 5 of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 883 (1983), in which this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we conclude that this is not one of those extremely rare cases in which we are able to find ineffective assistance of counsel
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having failed to find numerous errors, we conclude that the cumulative error doctrine is not applicable.', 'general', 'State v. Foster', 'https://www.courtlistener.com/opinion/1208826/', '1208826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, taking into account Taylor’s actions surrounding the perpetration of the crime, we find that the trier of fact, the trial judge in this ease, could have rationally concluded that Taylor was part of a common design to murder the victim, to which he assented, and therefore was guilty of the murder of [the victim] based on accountability.', 'general', 'State v. Foster', 'https://www.courtlistener.com/opinion/1208826/', '1208826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the jury was properly instructed that the evidence must be sufficient to show that the appellant acted together with another who did the acts necessary to constitute the crime pursuant to a common plan, purpose or scheme.', 'general', 'State v. Foster', 'https://www.courtlistener.com/opinion/1208826/', '1208826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not err in not giving such an instruction in light of the fact that the trial court gave a proper instruction on the concerted action theory of criminal liability.', 'general', 'State v. Foster', 'https://www.courtlistener.com/opinion/1208826/', '1208826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on the record in this case, we find that Mr.', 'general', 'State v. Foster', 'https://www.courtlistener.com/opinion/1208826/', '1208826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm.', 'general', 'State v. Foster', 'https://www.courtlistener.com/opinion/1208826/', '1208826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm the appellant’s convictions of two counts of second-degree murder and his consecutive forty-year sentences.', 'sentencing', 'State v. Foster', 'https://www.courtlistener.com/opinion/1208826/', '1208826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this opinion, we affirm the trial court’s decision to try appellants jointly and affirm its denial of Stuckey’s directed verdict motions.', 'general', 'State v. Stuckey', 'https://www.courtlistener.com/opinion/1418688/', '1418688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because none of the appellants have shown that a separate trial would have resulted in a more favorable result, we affirm the trial court’s decision to proceed''with a joint trial.', 'general', 'State v. Stuckey', 'https://www.courtlistener.com/opinion/1418688/', '1418688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of defendant’s failure to follow the procedures clearly set out for jury panel challenges and his failure to alert the trial court to the challenged improprieties, we hold that defendant failed to preserve this issue for appellate review.', 'general', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 8C-1, Rule 608(b), we hold that admission of the evidence did not rise to the level of plain error.', 'general', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant received a fair trial and capital sentencing proceeding, free from prejudicial error.', 'sentencing', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 304, 326 (1983), we held that the prosecutor’s argument that the death penalty of North Carolina was consistent with the Bible was permissible.', 'general', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 144, 154 (1990), this Court held that such questions did not minimize the importance of the jury or diminish the jury’s responsibility for the decision to impose death.', 'general', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 391, 397 (1979), this Court held that a defendant charged with committing a murder in prison “should be permitted to present to the jury his evidence of the availability of weapons both to rebut the state’s evidence and to assist in establishing his claim of self-defense.', 'general', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 397-98, this Court held competent and admissible the testimony of Lee Bounds, former Director of Prisons, about prevailing prison conditions.', 'general', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 398, this Court held that the trial court properly excluded expert testimony about the effect of imprisonment on the defendant on the basis that the expert was in no better position than the jury to determine the reasonableness of the defendant’s apprehension.', 'general', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 437, 447 (1992), this Court held that the prosecutor did not improperly assert his personal beliefs when he argued that “justice in Halifax County will be dead” if the defendant was found not guilty.', 'general', 'State v. Braxton', 'https://www.courtlistener.com/opinion/1420123/', '1420123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err.', 'general', 'Jenkins v. Commonwealth', 'https://www.courtlistener.com/opinion/1420585/', '1420585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From a consideration of these previous cases, we conclude that the death sentences in this case are not excessive or disproportionate to the punishment generally imposed by juries in the Commonwealth for similar conduct.', 'sentencing', 'Jenkins v. Commonwealth', 'https://www.courtlistener.com/opinion/1420585/', '1420585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when reviewing the findings of fact and conclusions of law of a circuit court sentencing a defendant following a revocation of probation, we apply a three-pronged standard of review.', 'sentencing', 'State v. Duke', 'https://www.courtlistener.com/opinion/1420969/', '1420969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that where a circuit court places a criminal defendant on probation for an offense he/she committed while on probation for a previous offense, the court must make clear on the record the precise nature of the subsequently imposed probationary term
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the standard of review for a sentence arising from a probation revocation is substantially similar to the standard articulated in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the novel question presented by this appeal and for the reasons stated below, we find that the standard established by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the circuit court’s actions in granting the defendant’s request for probation incident to his plea of guilty to brandishing resulted in the imposition of a separate and distinct one-year term of probation for brandishing to begin July 13, 1995 (the date upon which the sexual assault probation was scheduled to expire), and to end July 13, 1996.', 'plea', 'State v. Duke', 'https://www.courtlistener.com/opinion/1420969/', '1420969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the record, and for the reasons stated below, we reverse the order of the Circuit Court of Wetzel County and remand this ease for entry of an order consistent with our decision.', 'general', 'State v. Duke', 'https://www.courtlistener.com/opinion/1420969/', '1420969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of the Circuit Court of Wetzel County.', 'general', 'State v. Duke', 'https://www.courtlistener.com/opinion/1420969/', '1420969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that an affiant who commits the act of swearing to the veracity of one or more matters set forth in an affidavit may only be charged with a single count of false swearing within the meaning of West Virginia Code § 61-5-2.', 'general', 'State Ex Rel. Porter v. Recht', 'https://www.courtlistener.com/opinion/1421854/', '1421854') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of the relevant statute combined with pertinent case law, we conclude that Petitioner is entitled to the requested writ of prohibition to prevent him from being wrongly subjected to multiple punishments for the same two offenses.', 'general', 'State Ex Rel. Porter v. Recht', 'https://www.courtlistener.com/opinion/1421854/', '1421854') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In support of our conclusion, we hold that the appellant’s constitutional right to counsel under the Alaska Constitution was violated.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was not the intent of the Alaska Constitutional Convention, in adopting a portion of the wording of the Sixth Amendment, to give to article I, section 11 any broader application than that portion of the Sixth Amendment had been given by the United States Supreme Court.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the petitioner was denied the basic protections of that guarantee [right to counsel, sixth amendment] when there was used against him at his trial evidence of his own incriminating words, which federal agents had deliberately elicited from him after he had been indicted and in the absence of his counsel.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that providing transportation of school children to non-public schools at public expense would be a contravention of the state constitution.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of this evidence by the trial court was error.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that article I, § 11 of the Alaska Constitution requires counsel in the circumstances of the present case.', 'general', 'Roberts v. State', 'https://www.courtlistener.com/opinion/1422758/', '1422758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Capshaw v. State', 'https://www.courtlistener.com/opinion/1426956/', '1426956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 6-2-304, and one was no more “specific” than the other, we concluded that Wyo.', 'general', 'Pierson v. State', 'https://www.courtlistener.com/opinion/1433936/', '1433936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Wyo.', 'general', 'Pierson v. State', 'https://www.courtlistener.com/opinion/1433936/', '1433936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, due to the misleading and confusing nature of the instructions given the jury, we reverse.', 'general', 'Pierson v. State', 'https://www.courtlistener.com/opinion/1433936/', '1433936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that our indecent liberties statute is not unconstitutionally vague as applied to Mr.', 'general', 'Pierson v. State', 'https://www.courtlistener.com/opinion/1433936/', '1433936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1921, 1927-28 (1994), comports with the protections afforded under the Vermont Constitution, we affirm.', 'general', 'State v. Porter', 'https://www.courtlistener.com/opinion/1437588/', '1437588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1153 (1976), this Court held that the trial court had committed plain error in instructing the jury on first-degree murder when the facts in the record did not support the charge.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 218, this Court held the defendant’s confession admissible despite the fact that the interrogating officer had given assurance that he was acting solely in the defendant’s interest.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*643Against that background, we conclude that the Legislature by its use of the term “mental disease or defect” did not intend to preclude evidence of a mental condition consisting of a “disorder” as such.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant did provide expert testimony sufficient to warrant a jury instruction on diminished capacity.', 'jury_instruction', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the interrogation that elicited defendant’s confession did not violate his rights against self-incrimination, and that his confession was the result of a knowing, voluntary, and intelligent waiver of those rights, in accordance with the Miranda standards.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was not sufficient to justify the submission of the third-degree child-endangerment charge to the jury.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to defendant, we find that it offers at least the suggestion that defendant’s faculties were sufficiently affected to preclude him from engaging in purposeful or knowing conduct when he harmed the infant.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*650Accordingly, we find that the improper instruction withdrawing the defense of diminished capacity from the jury constituted harmful error and requires the reversal of defendant’s conviction for murder.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our construction of the statute, we find that the trial court’s instruction was plainly erroneous in that it failed to instruct the jury that to find that defendant had assumed responsibility for the child within the meaning of the statute, it must find that he had assumed a caretaking function over the child on a continuing, regular, or recurrent basis.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division, which sustained the convictions for murder and third-degree child endangerment, and remand the matter for a new trial.', 'general', 'State v. Galloway', 'https://www.courtlistener.com/opinion/1439077/', '1439077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial co^rt continued the trial as if it were a bifurcated proceeding, and because admonishments as to the punishment range were not required in a bifurcated trial, we held that failure to admonish was not reversible error.', 'general', 'Barfield v. State', 'https://www.courtlistener.com/opinion/1439935/', '1439935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, pursuant to its own order, a majority of this court holds that because appellant waived his right to a jury trial, his trial should not have been bifurcated.', 'general', 'Barfield v. State', 'https://www.courtlistener.com/opinion/1439935/', '1439935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Jones’s confession “would clearly meet the requirements of Article 38.', 'general', 'Barfield v. State', 'https://www.courtlistener.com/opinion/1439935/', '1439935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our grant of the State’s petition was improvident because the record does not present a case in which the evidence was insufficient to prove the jurisdictional allegations of prior convictions for DWI.', 'general', 'Barfield v. State', 'https://www.courtlistener.com/opinion/1439935/', '1439935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to consider the circumstances of Appellant’s case, we conclude that the complainant’s clothing is not evidence so crucial to the defense that its destruction will necessarily result in a fundamentally unfair trial.', 'general', 'State v. Matafeo', 'https://www.courtlistener.com/opinion/1442818/', '1442818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the showup procedure was impermis*496sibly suggestive, but because the victim’s identification of defendant was reliable it was properly admitted at trial.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that evidence obtained from an out-of-court showup is inherently suggestive and will not be admissible unless, based on the totality of the circumstances, the procedure was necessary.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in combination with the suggestiveness inherent in a showup, the added comments by the police rendered the showup procedures in the out-of-court identification of defendant impermissibly suggestive.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an approximate five-hour period between the incident and the identification does not subvert the reliability of the identification procedure.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the totality of the circumstances, we conclude that the trial court properly admitted Valentin’s out-of-court identification of defendant.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Appellate Division’s judgment.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In Re Grega', 'https://www.courtlistener.com/opinion/1444028/', '1444028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on remand, the sentencing court should impose a sentence not in excess of ten years with four years suspended.', 'sentencing', 'Skrepich v. State', 'https://www.courtlistener.com/opinion/1446803/', '1446803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that Maal’s prior record, his poor prognosis for rehabilitation, and the aggravated circumstances of his current offense were all factors that the court could properly consider and rely on in deciding upon an appropriate sentence.', 'sentencing', 'Skrepich v. State', 'https://www.courtlistener.com/opinion/1446803/', '1446803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the defendant’s first-offender status could not be disregarded entirely, because the lengthy period between Maal’s current offense and his past convictions indicated at least some potential for rehabilitation.', 'general', 'Skrepich v. State', 'https://www.courtlistener.com/opinion/1446803/', '1446803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither Skrepich’s background nor his current offense can support the conclusion that he is a worst offender.', 'general', 'Skrepich v. State', 'https://www.courtlistener.com/opinion/1446803/', '1446803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances involved in the present case, we conclude that, on remand, a sentence of not more than ten years with four years suspended should be imposed.', 'sentencing', 'Skrepich v. State', 'https://www.courtlistener.com/opinion/1446803/', '1446803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that, under the circumstances, reliance on the psychological prognosis of future danger gave “undue prominence to speculation as to Maal’s ‘future behavior.', 'general', 'Skrepich v. State', 'https://www.courtlistener.com/opinion/1446803/', '1446803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Skrepich v. State', 'https://www.courtlistener.com/opinion/1446803/', '1446803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1447803/', '1447803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not for two reasons — one textual and the other based on the central importance of providing access to public records.', 'general', 'Konvalinka v. Chattanooga-Hamilton County Hospital Authority', 'https://www.courtlistener.com/opinion/1448625/', '1448625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that Konvalinka and Lawrence are in direct civil contempt
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment finding Mr.', 'general', 'Konvalinka v. Chattanooga-Hamilton County Hospital Authority', 'https://www.courtlistener.com/opinion/1448625/', '1448625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing evidence, we hold that there was substantial evidence to support the jury’s verdict and that the jury did not have to resort to speculation concluding that the appellant was guilty of arson, and we affirm the appellant’s conviction and sentence for arson.', 'sentencing', 'Wright v. State', 'https://www.courtlistener.com/opinion/1448613/', '1448613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that this evidence falls within the excited-utterance exception to the hearsay rule, and the circuit court did not abuse its discretion in admitting Thompson’s testimony.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/1448613/', '1448613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that allowing the testimony of these three witnesses as excited utterances was an abuse of discretion, as the facts do not establish that Sharlene’s statements were spontaneous, excited, or impulsive.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/1448613/', '1448613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/1448613/', '1448613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because the admission of the co-workers’ testimony was harmless error due to its cumulative nature, we affirm on this point as well.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/1448613/', '1448613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed his first conviction of first-degree murder and remanded the case for retrial, holding that the circuit court erred in refusing Wyles’s proffered jury instructions on the lesser-included offenses of second-degree murder and manslaughter.', 'jury_instruction', 'Wyles v. State', 'https://www.courtlistener.com/opinion/1448875/', '1448875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore conclude that there was substantial evidence to support the jury’s verdict, and we affirm.', 'general', 'Wyles v. State', 'https://www.courtlistener.com/opinion/1448875/', '1448875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statement objected to by appellant in the instant case was not improper and certainly not fundamental error.', 'general', 'State v. Zaragoza', 'https://www.courtlistener.com/opinion/1449708/', '1449708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that by sexually assaulting Winifred Duggan and senselessly killing her, knowing full well that by virtue of her advanced age and limited mental capabilities she was easy prey, appellant demonstrated a shockingly evil and corrupt state
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the murder in the instant case was heinous and depraved within the meaning of A.', 'general', 'State v. Zaragoza', 'https://www.courtlistener.com/opinion/1449708/', '1449708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the giving of the felony murder instruction was not relevant in determining whether appellant should receive a death sentence and therefore is not a mitigating circumstance.', 'sentencing', 'State v. Zaragoza', 'https://www.courtlistener.com/opinion/1449708/', '1449708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have reviewed the remaining factors appellant relies on and we find that they are not mitigating circumstances.', 'general', 'State v. Zaragoza', 'https://www.courtlistener.com/opinion/1449708/', '1449708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Zaragoza', 'https://www.courtlistener.com/opinion/1449708/', '1449708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm appellant’s conviction we also affirm the trial court’s revocation of probation and sentence.', 'sentencing', 'State v. Zaragoza', 'https://www.courtlistener.com/opinion/1449708/', '1449708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the collateral estoppel effect attributed to the Double Jeopardy Clause does not preclude a defendant from being charged with a subsequent offense arising out of the same actions when the elements of the offenses are different.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1449939/', '1449939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we hold that double jeopardy does not apply and that the trial court erred in this case by barring a subsequent prosecution for second-degree murder.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1449939/', '1449939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in the case of State v.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1449939/', '1449939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Still, this Court held, quoting from our decision in State v.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1449939/', '1449939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we reverse and remand the case to the trial court.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1449939/', '1449939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that admission of Eugene’s hearsay statement does not meet the “stringent standard” of fundamental error.', 'general', 'State v. Wood', 'https://www.courtlistener.com/opinion/1451091/', '1451091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that the absence of such an instruction did not deprive Defendant of a fair trial.', 'general', 'State v. Wood', 'https://www.courtlistener.com/opinion/1451091/', '1451091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Defendant’s convictions and sentences.', 'sentencing', 'State v. Wood', 'https://www.courtlistener.com/opinion/1451091/', '1451091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ross v. State', 'https://www.courtlistener.com/opinion/1452570/', '1452570') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that De Nardo’s act of carrying a long-bladed knife in a briefcase constituted the concealment of a dangerous weapon “on his person” in violation of AS 11.', 'general', 'De Nardo v. State', 'https://www.courtlistener.com/opinion/1453481/', '1453481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'De Nardo v. State', 'https://www.courtlistener.com/opinion/1453481/', '1453481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons explained below, we affirm.', 'general', 'Matter of Clayton', 'https://www.courtlistener.com/opinion/1454036/', '1454036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court’s error was harmless, however, because it did not prejudice Appellant’s substantial rights.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/1454677/', '1454677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1977), we held that an expert may not testify about the veracity of a defendant’s version because “it assumes the function of the jury.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/1454677/', '1454677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/1454677/', '1454677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that murder after deliberation and felony murder were alternative ways in which to commit first-degree murder, and the proper procedure was to inform the jury
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Coleman’s own admission, we conclude that Mr.', 'general', 'Lawyer Disciplinary Board v. Coleman', 'https://www.courtlistener.com/opinion/1276364/', '1276364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the foregoing principles, we conclude that the trial judge did not abuse her broad discretion in denying Whitley’s motion for a new trial.', 'general', 'Whitley v. United States', 'https://www.courtlistener.com/opinion/1461840/', '1461840') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Whitley’s claim of eviden-tiary insufficiency is altogether devoid of merit.', 'general', 'Whitley v. United States', 'https://www.courtlistener.com/opinion/1461840/', '1461840') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm that order as well as Whitley’s convictions.', 'general', 'Whitley v. United States', 'https://www.courtlistener.com/opinion/1461840/', '1461840') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons that follow, we hold that the decision to employ a summary contempt proceeding under Rule 42(a) was inappropriate under the circumstances of this ease and that the contempt conviction is substantively deficient, in that the elements of criminal contempt were not met.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that whatever disruption Mr.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We decline to remand this ease, however because we hold that the evidence was insufficient that Mr.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, based on our review of the evidence in this case we conclude that some of the facts contained in the certification that were relied upon by the trial court are not supported by the record.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We will also reverse a conviction for contempt if we find that there is not adequate record support for any certified fact, if that fact was part of an aggregate of facts upon which the trial judge based his or her contempt ruling.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the conviction for contempt.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the appellant in Warrick I, whose summary contempt conviction we reversed, Mr.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse Mr.', 'general', 'Brooks v. United States', 'https://www.courtlistener.com/opinion/1462156/', '1462156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances and in light of Sherron’s request, we conclude that the trial court erred by not instructing the jury on criminal restraint as a lesser included offense of kidnapping and that that error requires reversal of the conspiracy and murder convictions.', 'general', 'State v. Savage', 'https://www.courtlistener.com/opinion/1469124/', '1469124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand to the trial court for reconsideration of the sentence imposed.', 'sentencing', 'Holloway v. United States', 'https://www.courtlistener.com/opinion/1470253/', '1470253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 25] We conclude that the court’s decision to admit this evidence was within the proper bounds of the discretion afforded by M.', 'general', 'State v. Roberts', 'https://www.courtlistener.com/opinion/1470596/', '1470596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 35] Nor can we conclude that admission of the protection from abuse affidavit was so prejudicial as to constitute error, much less obvious error, under the facts of this case.', 'general', 'State v. Roberts', 'https://www.courtlistener.com/opinion/1470596/', '1470596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this situation, we conclude that the statute is susceptible to two reasonable interpretations.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in such situations, the elements of the aggravated rape and the murder may overlap.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the facts in appellant’s case constituted a proper subject for prosecution under the capital murder statute.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that a rational jury could have found beyond a reasonable doubt that appellant constituted a continuing threat to society and overrule appellant’s sixteenth point of error.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we conclude that appellant was arrested upon probable cause in a suspicious place, under circumstances that reasonably show he had committed some felony.', 'probable_cause', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Before addressing the substance of appellant’s seventh and eighth points of error, we conclude that we need not address appellant’s Texas constitutional claims.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that the trial judge, acting as the factfinder, decided a controverted question in a manner supported by the record.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Zerbst, supra, we conclude that appellant knowingly relinquished his right to consult with an attorney.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that no evidence before the jury raised the issue of the voluntariness of appellant’s confession.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concerning appellant’s artistic abilities, we conclude that in this case the evidence adduced “is otherwise irrelevant to an individualized assessment of the deathworthiness of appellant.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm in part, and reverse in part.', 'general', 'State v. Pownal Tanning Co.', 'https://www.courtlistener.com/opinion/1472844/', '1472844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the court’s order imposing a $10,000 nonpurgeable fine on the defendant.', 'general', 'State v. Pownal Tanning Co.', 'https://www.courtlistener.com/opinion/1472844/', '1472844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that they are, but that the prosecutor’s decision to provide community notification, including the manner of notification, is subject to judicial review before such notification is given, and that such review is constitutionally required.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such additional procedures in the form of a hearing are due, that they must, on application, be provided before notification and that they are constitutionally required.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislative intent was to use the word “moderate” in comparison to the “low” risk that the Legislature found was minimally characteristic of all those sex offenders required to register.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the detention imposed by the Act falls on the regulatory side of the dichotomy.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, where as a result of the information disclosed under the Notification Law, plaintiff may be exposed to uninvited harassment, we conclude that disclosure of plaintiffs home address, particularly when coupled with the other information disclosed, implicates a privacy interest.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the public need for information about dangerous sex offenders greatly outweighs plaintiffs right to privacy and the intrusion of that right associated with registration and notification.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Thus, we conclude that classification in Tiers Two or Three, with the requisite public notification, would expose plaintiff to public opprobrium, not only identifying him as a sex offender but also labelling him as potentially currently dangerous, and thereby undermining his reputation and standing in the community.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that because the stigma resulting from notification is tied to the protectible interest in privacy, which has been grounded in the Fourteenth Amendment, plaintiff has a protectible interest in his reputation.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the consequences to plaintiffs reputation from classification in Tier Two or Three implicate a liberty interest.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that under both the Federal and State Constitutions, the Registration and Notification Laws implicate protectible liberty interests in privacy and reputation, and therefore trigger the right to due process.', 'general', 'Doe v. Poritz', 'https://www.courtlistener.com/opinion/1473573/', '1473573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Mejia was not entitled to a claim-of-right charge on the guilt phase.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By comparison, we hold that the penalty-phase anti-claim-of-right charge precluded the jury from considering as a mitigating factor Mejia’s honest belief that he was entitled to recover his $750 from Garcia.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court’s “instruction had *484the potential to foreclose jury consideration of whether passion/provocation should reduce an otherwise purposeful killing from murder to manslaughter.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that the trial court, which had found a rational basis for charging aggravated and reckless manslaughter, also should have charged the jury on serious-bodily-injury murder.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the words and structure of the Code, and for sound reasons of public policy, we conclude that the Legislature did not intend to extend the claim-of-right defense to robbery.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'So here, we find that the jury should have been given the option of finding that defendant had intended to cause only serious bodily injury when he killed the victim.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that Mejia knowingly and intelligently waived his Miranda rights.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse defendant’s death sentence and remand for imposition of a non-capital-murder sentence.', 'sentencing', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse defendant’s death sentence.', 'sentencing', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Mejia’s conviction for murder, but reverse the imposition of the death penalty.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 846 (1988) (Bey I), we reversed the defendant’s murder conviction because the trial court failed to ensure that the jury was not exposed to mid-trial publicity respecting defendant’s other-alleged offenses, in-*514eluding another murder.', 'general', 'State v. Mejia', 'https://www.courtlistener.com/opinion/1473608/', '1473608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court’s denial of Bilynsky’s motions.', 'general', 'State v. Bilynsky', 'https://www.courtlistener.com/opinion/1477667/', '1477667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that: (1) The record supports a finding that Kane’s conflict of interest could have compromised his ability to render effective assistance to appellant during the remainder of the trial.', 'general', 'Douglas v. United States', 'https://www.courtlistener.com/opinion/1479756/', '1479756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 56,27 we conclude that a defendant’s choice of counsel is among the fundamental defense decisions constitutionally protected under Faretta and Frendak.', 'general', 'Douglas v. United States', 'https://www.courtlistener.com/opinion/1479756/', '1479756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lewis, we affirmed a trial court’s restriction of a defendant’s choice of counsel, without a hearing, because it was “apparent .', 'general', 'Douglas v. United States', 'https://www.courtlistener.com/opinion/1479756/', '1479756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1280, 1283 (1987), we held that Rule 41(c)’s standard for issuing warrants based on hearsay adopts the two-pronged test of Aguilar v.', 'general', 'State v. Bruyette', 'https://www.courtlistener.com/opinion/1481573/', '1481573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was highly probative on the identity issue, and that the relevance standard was satisfied.', 'general', 'State v. Bruyette', 'https://www.courtlistener.com/opinion/1481573/', '1481573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that he was not.', 'general', 'Sullivan v. United States', 'https://www.courtlistener.com/opinion/1483672/', '1483672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s failure to resort to that mechanism is no bar to our consideration of his claim.', 'general', 'Sullivan v. United States', 'https://www.courtlistener.com/opinion/1483672/', '1483672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Sadino', 'https://www.courtlistener.com/opinion/1187207/', '1187207') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that the admission of the second statement was harmless, beyond a reasonable doubt, as to the felony murder convictions.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 565, we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no merit in any of the defendant’s other contentions, we conclude that the felony murder convictions *585and the death penalty imposed for those convictions should be affirmed.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite the fact that the defendant’s second confession was erroneously admitted into evidence, we conclude that the error was harmless beyond a reasonable doubt as to the felony murder convictions.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Enmund does not preclude the imposition of the death penalty in this case where Deputy was not “found guilty only vicariously as a felony murderer.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning first to subparagraph b, we conclude that the evidence supported the jury’s findings of the statutory aggra*602vating circumstances which have been discussed in this opinion.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we conclude that given “the totality of evidence in aggravation and mitigation which bears upon the particular circumstances or details of the offense and the character and propensities of the offender” the sentence of death imposed by the jury was neither arbitrarily nor capriciously imposed.', 'sentencing', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the imposition of death in this case was therefore not disproportionate and the defendant’s convictions and sentence as to the felony murder charges are accordingly affirmed.', 'sentencing', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, finding the initial detention pursu*588ant to 11 Del.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the trial court’s decision to admit the defendant’s first recorded statement.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mace this Court held that an information amending a second degree assault charge from § 565.', 'general', 'State v. Greathouse', 'https://www.courtlistener.com/opinion/1492449/', '1492449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1(5), we find that the judgment rendered on the amended information, which charged a different offense from the original information, is a nullity.', 'general', 'State v. Greathouse', 'https://www.courtlistener.com/opinion/1492449/', '1492449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment, the conviction and sentence are vacated, and the case is remanded for new trial on the original information or the original information may be dismissed and the state may proceed on a new information.', 'dismissal', 'State v. Greathouse', 'https://www.courtlistener.com/opinion/1492449/', '1492449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that mention of the lie detector test as the trigger point for Gerry’s decision to cooperate and the related issue of his lawyer’s vouching for Gerry’s credibility were improper but not reversible error in light of the trial judge’s limiting instruction and the totality of all the evidence presented in this long trial.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the quotations from Fahey going to her state of mind were properly admitted under established exceptions to the hearsay rules.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge was correct in not instructing the jury on the lesser included offenses.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge erroneously limited Capano’s allocution by not permitting him to discuss or argue in allocution from facts already in the record.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we hold that this error was harmless under all the circumstances and Capano was not unduly prejudiced.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the authority relied on by Capano does not support this argument.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Delaware Death Penalty Statute is constitutional and was properly applied here.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On harmless error analysis, therefore, we hold that the erroneous admission of Lyons’ testimony concerning Gerry’s polygraph test and his improper vouching did not substantially prejudice the defense and that admission of this testimony does not warrant a reversal of Capano’s conviction and sentence.', 'sentencing', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence produced at trial does not provide a rational basis for “a verdict acquitting the defendant of the offense charged and convicting the defendant of the included offense.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that as a matter of Delaware’s law of allocution, any erroneous limitations placed on Capano’s right of allocution and the trial judge’s colloquy with Capano in front of the jury, although regrettable, did not prejudice Capano and do not entitle him to a new penalty hearing.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these arguments have merit and reverse and remand.', 'general', 'Tackett v. State', 'https://www.courtlistener.com/opinion/1495542/', '1495542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As for his other complaints, we held that they were not yet ripe for decision.', 'general', 'Tackett v. State', 'https://www.courtlistener.com/opinion/1495542/', '1495542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we find that the trial court abused its discretion in ruling that the prosecution could impeach Tackett’s testimony with these prior convictions.', 'general', 'Tackett v. State', 'https://www.courtlistener.com/opinion/1495542/', '1495542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/1495687/', '1495687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As substantial evidence clearly existed in this case to support the jury’s verdict, with or without the introduction of the prior conviction, we affirm.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/1495687/', '1495687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We shall treat the questions raised by defendant seri-atim, but finding no error, we affirm.', 'general', 'Foraker v. State', 'https://www.courtlistener.com/opinion/1499124/', '1499124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that our courts have no such power.', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not.', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly we conclude that the “power cannot successfully be questioned at least with respect to the type of offense here involved .', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When considered in conjunction with the unmistakable policy expressed by the Legislature in the Graves Act — that conviction for the listed offense results without fail in at least three years imprisonment, which imprisonment is not to be reduced by parole eligibility, sentence suspension, or anything — we find that the legislative intent permits but one conclusion.', 'sentencing', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '19 Accordingly, we affirm the judgment below.', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm the judgment of the Appellate Division in Des Marets and that of the trial court in Appleton.', 'general', 'State v. Des Marets', 'https://www.courtlistener.com/opinion/1500778/', '1500778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that his appearance at the police station for the polygraph test demonstrates a waiver of his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that reference to the defendant’s polygraph examination was properly allowed.', 'general', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1502279/', '1502279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'rule intact when enacting § 206, and we hold that Rape is not a lesser included offense of Felony Murder (Rape).', 'general', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1502279/', '1502279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, our determination in Section VIII A that the Legislature did intend to authorize the convictions and sentences imposed in this case necessarily answers defendant’s double jeopardy argument, and we hold that imposition of multiple sentences upon defendant for the Felony Murder and the Rape First Degree in this case does not violate the Double Jeopardy Clause as interpreted in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, considering the untimeliness of the objection and the foundation that was established by the State, we conclude that the evidence from the Master Semen Test was properly admitted.', 'general', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1502279/', '1502279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the Legislature did intend to authorize separate convictions and sentences for Felony Murder and the underlying Rape First Degree in this case.', 'sentencing', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1502279/', '1502279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and we reverse the death sentence on his Murder First Degree conviction.', 'sentencing', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1502279/', '1502279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We perceive no prejudice to the appellant from the interim delay which will necessarily result from our decision, since he is presently incarcerated under a thirty year prison sentence on his instant conviction for Burglary First Degree (which conviction and sentence we affirm by our decision today).', 'sentencing', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1502279/', '1502279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we affirm the defendant’s conviction and sentence for Burglary First Degree;', 'sentencing', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1502279/', '1502279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm the convictions for Murder First Degree and Rape First Degree;', 'general', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1502279/', '1502279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that, if there was illegality in defendant’s initial detention, the subsequent automobile search fully authorized under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1181 (1996), this court held that a voluntary manslaughter charge is not proper where the person who was killed is not the person who provoked the defendant, absent evidence of negligence or accident.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1508311/', '1508311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because the photographs were of limited, if any, probative value and were highly prejudicial, we find that they were erroneously admitted into evidence by the trial court.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1508311/', '1508311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '44 in the commission of the murder, we find that the Bulldog Pug 44 SPL did not establish a material fact in the instant case and thus, was erroneously admitted into evidence at trial.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1508311/', '1508311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '18 Accordingly, we affirm the verdict and sentence of death imposed upon appellant, Antyane Robinson, by the Court of Common Pleas of Cumberland County.', 'sentencing', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1508311/', '1508311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1977), this court held that the trial court must permit either side to bring out the criminal convictions of its own witnesses on direct examination in order to “draw the sting from the inevitable impeachment on cross-examination.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has highlighted this testimony out of its context in the record.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this circumstance, we conclude that substantial rights were not affected by the absence of a cautionary instruction, and thus the error was harmless.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under all the circumstances, we conclude that appellant’s substantial rights were not affected by the failure of the trial court to strike, without prompting by defense counsel, the prosecutor’s argument to the jury and to intervene, sua sponte, when appellant* was asked whether he had told the police of his alibi.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sampson, we found that the government failed to show “a threshold inconsistency” between the defendant’s testimony in court and the omissions in his statement to the police prior to trial denying involvement in the crime.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Although we do not find the trial proceedings to be without error, we affirm appellant’s conviction because we are persuaded that any errors that were committed could not have substantially swayed the judgment of the jury.', 'general', 'Beale v. United States', 'https://www.courtlistener.com/opinion/1509614/', '1509614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that a mistaken search was unlikely and that the incorrect apartment number in the warrant was not a fatal defect.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1512309/', '1512309') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we conclude that appellant has failed to preserve the issue for appeal.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1512309/', '1512309') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1512309/', '1512309') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, this Court holds that a conviction for resisting arrest cannot stand where the underlying arrest is found to be unlawful.', 'general', 'Commonwealth v. Biagini', 'https://www.courtlistener.com/opinion/1512513/', '1512513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Turning to the facts of the cases at bar, we conclude that the Commonwealth has met its respective burdens as to both Biagini and Barry W.', 'general', 'Commonwealth v. Biagini', 'https://www.courtlistener.com/opinion/1512513/', '1512513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the appeal of Biagini, we reverse only that part of the Order of the Superior Court which affirmed the conviction for resisting arrest.', 'general', 'Commonwealth v. Biagini', 'https://www.courtlistener.com/opinion/1512513/', '1512513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the remaining portion of the Superior Court Order which affirmed the conviction for aggravated assault and reversed the convictions for disorderly conduct, public drunkenness, prohibited offensive weapons and possession of a small amount of marijuana.', 'general', 'Commonwealth v. Biagini', 'https://www.courtlistener.com/opinion/1512513/', '1512513') ON CONFLICT DO NOTHING;
