INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the attempted robbery charge was the predicate felony for DeJesus’ felony murder conviction, we conclude that his convictions for both charges must be reversed.', 'general', 'DeJesus v. State', 'https://www.courtlistener.com/opinion/1512559/', '1512559') ON CONFLICT DO NOTHING;
