INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 836, we concluded that the defendant’s behavior, under the circumstances, did not warrant this conclusion.', 'general', 'DeJesus v. State', 'https://www.courtlistener.com/opinion/1512559/', '1512559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, therefore, we find that the Superior Court properly held that DeJesus’ waiver of his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that DeJesus’ admission that he attempted to rob Robinson is insufficiently corroborated under the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the convictions of DeJesus for felony murder and attempted robbery, as well as their accompanying two charges of possession of a deadly weapon during the commission of a felony.', 'general', 'DeJesus v. State', 'https://www.courtlistener.com/opinion/1512559/', '1512559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that this defendant did not “volunteer,” under N.', 'general', 'State v. Valentin', 'https://www.courtlistener.com/opinion/1516529/', '1516529') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the capital punishment act is in all respects constitutional.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that New Jersey’s death penalty does not conflict with contemporary standards of decency in this state.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that capital punishment is not per se a violation of our state constitutional ban against cruel and unusual punishments.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*190We hold that the Act is constitutional under the eighth amendment to the federal Constitution.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the marginal strength of the statistical showing in comparison to other cases, the fact that the mechanism by which jury lists are now constituted is facially neutral and objective, the failure to demonstrate underrepresentativeness over a sufficient period of time, and the State’s efforts at reform, we hold that defend*228ant has failed to make a prima facie showing that the Essex County grand and petit jury selection procedures violate either the sixth or fourteenth amendments.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the principles set forth in Batson and Gilmore, however, we hold that the dismissal of two blacks from defendant’s grand jury was not an error of constitutional magnitude.', 'dismissal', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court’s refusal to rule on this issue earlier was not an abuse of discretion.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court’s scheduling decision did not deprive defendant of a fair trial.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion in admitting the evidence.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the trial court’s entire charge and numerous instructions to the jurors concerning their responsibility as fact-finders, we hold that the charge neither constituted an abuse of discretion nor violated the defendant’s fundamental right to a fair trial and to a trial by jury.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that voir dire questioning directed to racial prejudice was not constitutionally required, the wiser course generally is to propound appropriate questions designed to identify racial prejudice if requested by the defendant.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '128 (1969), we held that a defendant had a right to disclosure of presentence reports and a right to be heard regarding any adverse matters within those reports.', 'sentencing', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '309 (1978), we held that a defendant could not be retried on a charge for which the defendant had been convicted, where the conviction had been reversed by the Appellate Division.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Guido, for example, this Court held that a course of ill treatment, including continuous unfaithfulness, could induce a homicidal response in a person of ordinary firmness if the accused reasonably believed that it would continue.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 226, explained the Court’s refusal to follow federal precedent in a search and seizure context: “Because we find that these recent decisions of the Supreme Court provide persons with inadequate protection against unreasonable searches and seizures, we respectfully part company with the Supreme Court’s view of standing and construe Article I, paragraph 7 of our State Constitution to afford greater protection.', 'search_seizure', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the undisputed facts concerning LaPointe’s knowledge at the time pursuit commenced, we conclude that LaPointe reasonably believed that Moráis had left the scene of an accident involving personal injury.', 'general', 'Morais v. Yee', 'https://www.courtlistener.com/opinion/1523231/', '1523231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and remand for further proceedings on the state law claims against LaPointe, Yee, and Tupper.', 'general', 'Morais v. Yee', 'https://www.courtlistener.com/opinion/1523231/', '1523231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Morais v. Yee', 'https://www.courtlistener.com/opinion/1523231/', '1523231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that plaintiffs have not demonstrated violations of Moráis’ constitutional rights, we affirm summary judgment for the Town on the § 1983 claim.', 'general', 'Morais v. Yee', 'https://www.courtlistener.com/opinion/1523231/', '1523231') ON CONFLICT DO NOTHING;
