INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the prosecution in a stalking case may establish a violation of the statute in a number of different ways, one of which is by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that since the defendant had declined to make a statement concerning the murder for which he was charged, the police should not have redirected the questioning to the crime which was the subject of the terminated interrogation in the same conversation, only 45 minutes later, and without giving any "fresh"
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Trial Court neither abused its discretion nor committed reversible error in failing to excuse the two jurors.', 'general', 'DeShields v. State', 'https://www.courtlistener.com/opinion/1533221/', '1533221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Trial Court’s finding that such evidence would have inevitably been discovered is fairly supported by the record and not clearly erroneous.', 'general', 'DeShields v. State', 'https://www.courtlistener.com/opinion/1533221/', '1533221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s statements did not create an impermissible inference of guilt.', 'general', 'DeShields v. State', 'https://www.courtlistener.com/opinion/1533221/', '1533221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find DeShields’ proffer to be too speculative and conclusory, we conclude that the Trial Court did not abuse its discretion in refusing to hold an evidentiary hearing.', 'general', 'DeShields v. State', 'https://www.courtlistener.com/opinion/1533221/', '1533221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Addressing subparagraph b first, we conclude that the evidence supported the jury’s findings of the statutory aggravating circumstances enumerated under section 4209(e).', 'general', 'DeShields v. State', 'https://www.courtlistener.com/opinion/1533221/', '1533221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying an Edwards-type analysis to this record, we conclude that defendant initiated the fourth statement to Detective Passwaters and this statement was properly ruled
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” From our careful review of the record, we conclude that there is substantial evidence to support the Court’s findings that defendant’s statement was (1) defendant initiated;', 'general', 'DeShields v. State', 'https://www.courtlistener.com/opinion/1533221/', '1533221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and we concluded that defendant’s “subsequent admissible statement to Passwaters would have ultimately led to the discovery of the same evidence.', 'general', 'DeShields v. State', 'https://www.courtlistener.com/opinion/1533221/', '1533221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, given the legislature-enacted alternative of death by lethal injection, DeShields lacks standing to challenge the constitutionality of death by hanging.', 'general', 'DeShields v. State', 'https://www.courtlistener.com/opinion/1533221/', '1533221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court failed to exercise its discretion under V.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 631 (“The trial court performed the balancing here____[but] [e]ven accounting for the court’s wide discretion, we conclude that probative value was substantially outweighed by the danger of unfair prejudice.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this rule, we held that “[w]hen the sexual acts are taken together with the specific statements that the girlfriend and the victim were forced to repeat, and the defendant’s frequent use of cocaine during the activity, the evidence strongly tended to show that defendant was the perpetrator.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that voluntary manslaughter is a lesser included offense of murder under Code of Criminal Procedure Article 37.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/1535016/', '1535016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we reverse the judgment and remand this cause for a new trial.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/1535016/', '1535016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 9712(a), we hold that *387the mandatory minimum sentence provided by that section applies only to those parties culpable for a crime of violence as defined by 42 Pa.', 'sentencing', 'Commonwealth v. Dickson', 'https://www.courtlistener.com/opinion/1537713/', '1537713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because we disagree with the Commonwealth’s characterization of Appellant’s argument before the trial court, and find implicit in that argument the § 9712 argument raised before the Superior Court and now this Court, we conclude that Appellant preserved the issue for appellate review.', 'general', 'Commonwealth v. Dickson', 'https://www.courtlistener.com/opinion/1537713/', '1537713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Appellant preserved the issue raised herein in the lower courts, and that it therefore is ripe for our review.', 'general', 'Commonwealth v. Dickson', 'https://www.courtlistener.com/opinion/1537713/', '1537713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse.', 'general', 'Commonwealth v. Dickson', 'https://www.courtlistener.com/opinion/1537713/', '1537713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to this case, we hold that the bus excise tax imposes an unconstitutional burden on interstate commerce.', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*545Accordingly, we hold that the bus-excise tax, N.', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '471 (1967), where we held that the imposition of New Jersey’s Corporation Business Tax on a trucking company conducting an exclusively interstate business involving substantial properties and activities in New Jersey did not violate the commerce clause.', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the tax, which was fairly apportioned between intrastate and interstate commerce, was a nondiscriminatory means of requiring interstate commerce to pay its fair share of the cost of state government.', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Continental is not entitled to the refund.', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We found that the dentists in that ease did not pay the fee voluntarily but under duress.', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Appellate Division insofar as it holds that N.', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that this inadequacy, when combined with the trial court’s erroneous refusal to dismiss prospective juror Pfeiffer for cause, which effectively'' resulted in defendant’s loss of a peremptory challenge, requires reversal of both the guilt and penalty proceedings.', 'dismissal', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a juror’s bias need not “be proven with unmistakable clarity.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pfeiffer’s death penalty views during the voir dire, we conclude that the trial court erred in failing to excuse this prospective juror for *441cause.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, apart from the deficit *446in peremptories arising from the court’s failure to excuse prospective juror Pfeiffer for cause, we conclude that the trial court did not erroneously deprive defendant of peremptory challenges.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we concluded that "[tjhis standard does not require that a juror’s bias be proven with unmistakable clarity.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Although this question was an appropriate starting point, we find that the trial court’s repeated refusal to go beyond this initial inquiry raises serious questions about the impartiality of the jury ultimately impan-elled.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on an independent review of the voir dire, we find that the trial court relied much too heavily on closed-ended questions, and on several occasions did not ask adequate follow-up questions to overcome the inadequacy of the initial inquiry.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the voir dire of juror Stevenson did uncover potential bias, we find that the limited scope of the trial court’s questioning of jurors Reade, Vasanski, and Malloy was more representative of the jury selection process as a whole.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse both the conviction and the sentence.', 'sentencing', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we reverse, as noted above, because the deprivation of the peremptory challenge in conjunction with the perfunctory nature of the voir dire combined to deny defendant fundamental procedural protections that guarantee a fair and impartial jury panel.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the victim’s testimony as to penetration was sufficient to support the jury’s finding that a rape had occurred.', 'general', 'Styler v. State', 'https://www.courtlistener.com/opinion/1545304/', '1545304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that test to this case, we conclude that the Trial Judge’s actions were permissible and that neither of defendant’s contentions has merit.', 'general', 'Styler v. State', 'https://www.courtlistener.com/opinion/1545304/', '1545304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that the trial court erred when instructing the jury that it could convict the defendant of first-degree murder on an aiding and abetting theory without requiring a finding that he had formed the specific intent to murder required to convict a principal;', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), in which we held that, because D.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2009), in which we concluded that “Wilson-Bey is not limited to specific intent crimes.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2002), where we affirmed a conviction for carjacking by a defendant who had assaulted the victim, initially, in the security-guard booth where she was working, and then appropriated her car “only a few feet away” from the booth.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in Winstead, we concluded that for the purposes of the carjacking statute, a car is within a victim’s immediate actual possession if “ ‘the car is within such range that the victim could, if not deterred by violence or fear, retain actual physical control over it.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that there was insufficient evidence to support Ishola’s conviction.', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/1560118/', '1560118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the term “another,” as it is used in § 8-301(e), is ambiguous, the rule of strict construction requires that we resolve that ambiguity against the State and in favor of Ishola.', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/1560118/', '1560118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the evidence presented at trial was insufficient to sustain Ishola’s convictions under § 8-301(c).', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/1560118/', '1560118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the offenses were not “the same of-fence” under the Double Jeopardy Clause.', 'general', 'Ortega v. State', 'https://www.courtlistener.com/opinion/1560675/', '1560675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It held, “Because we conclude that resisting arrest and assault on a peace officer are the ‘same offense’ for double jeopardy purposes in this case and because we find that appellant has already been tried and convicted for resisting arrest, we reverse the judgment of the trial court and order a judgment of acquittal on the assault charge.', 'general', 'Ortega v. State', 'https://www.courtlistener.com/opinion/1560675/', '1560675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and remand the case to that court for the consideration of the appellant’s other points of error.', 'general', 'Ortega v. State', 'https://www.courtlistener.com/opinion/1560675/', '1560675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the district court''s decision.', 'general', 'State v. Meyer', 'https://www.courtlistener.com/opinion/1625184/', '1625184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Dye v. State', 'https://www.courtlistener.com/opinion/1561426/', '1561426') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a prospective juror is not challengeable for cause because he or she will use the facts to determine punishment.', 'general', 'Glauser v. State', 'https://www.courtlistener.com/opinion/1561614/', '1561614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we find that the proof of guilt is greatly outweighed by contrary proof.', 'general', 'Glauser v. State', 'https://www.courtlistener.com/opinion/1561614/', '1561614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the error was not of constitutional magnitude.', 'general', 'Glauser v. State', 'https://www.courtlistener.com/opinion/1561614/', '1561614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that the argument did not affect the certainty of conviction.', 'general', 'Glauser v. State', 'https://www.courtlistener.com/opinion/1561614/', '1561614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Glauser v. State', 'https://www.courtlistener.com/opinion/1561614/', '1561614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments.', 'general', 'Glauser v. State', 'https://www.courtlistener.com/opinion/1561614/', '1561614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the operation of an automobile may constitute the use of a deadly weapon under a prosecution under § 19.', 'general', 'Glauser v. State', 'https://www.courtlistener.com/opinion/1561614/', '1561614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the current version of § 6308(b) is constitutional under the Fourth Amendment and Article I, § 8.', 'search_seizure', 'Commonwealth v. Chase', 'https://www.courtlistener.com/opinion/1563033/', '1563033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that mere omission from § 641 of any mention of intent will not be construed as eliminating that element from the crimes denounced.', 'general', 'Morissette v. United States', 'https://www.courtlistener.com/opinion/104952/', '104952') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Deborah’s first appeal to this Court, we held that payments for medical insurance could be awarded as a type of alimony and remanded the case for the chancellor to consider the issue of Deborah’s medical insurance.', 'general', 'Weeks v. Weeks', 'https://www.courtlistener.com/opinion/1570547/', '1570547') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the chancellor’s original intent was to require Roland to pay the fixed amount of $516 per month.', 'general', 'Weeks v. Weeks', 'https://www.courtlistener.com/opinion/1570547/', '1570547') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Deborah’s first appeal to this Court, we found that the testimony concerning her poor health and large medical bills was uncontradicted.', 'general', 'Weeks v. Weeks', 'https://www.courtlistener.com/opinion/1570547/', '1570547') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding error, we affirm in part and reverse and remand in part.', 'general', 'Weeks v. Weeks', 'https://www.courtlistener.com/opinion/1570547/', '1570547') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the other acts evidence was not probative of the defendant''s intent or absence of accident and that the circuit court erroneously exercised its discretion in admitting the other acts evidence.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the prosecutor''s repeated references to the other acts evidence in the opening and closing statements, and the fact that the cautionary instruction was not limited to evidence of the defendant''s intent or absence of accident, we conclude that the cautionary instruction was insufficient to cure the prejudicial impact of the other acts evidence.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful reading of the record we conclude that the State has not proven that the error did not contribute to the conviction.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record and the prosecutor''s own view of the case, we conclude that there is a reasonable possibility that the other acts evidence contributed to the defendant''s convictions.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we conclude that the State has not met its burden of proving beyond a reasonable doubt that the error did not contribute to the verdict.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we reverse the decision of the court of appeals.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we reverse the judgments of conviction and remand the cause to the circuit court.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that fidelity to these principles dictates that, in this category of cases, the judge does not sit as a thirteenth juror.', 'general', 'People v. Lemmon', 'https://www.courtlistener.com/opinion/1572995/', '1572995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*648However, because we find that the court did not err in ordering a new trial under the erroneous thirteenth juror standard previously permitted under Herbert, we affirm the decision of the Court of Appeals27 and hold that the newly adopted limitations on Herbert apply prospectively to cases not yet final as of the date of this decision.', 'general', 'People v. Lemmon', 'https://www.courtlistener.com/opinion/1572995/', '1572995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Herbert, we held that it was error for the trial judge to conclude that he was not allowed to consider the credibility of witnesses when deciding a *649motion for a new trial.', 'general', 'People v. Lemmon', 'https://www.courtlistener.com/opinion/1572995/', '1572995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having done so, and in applying the Dost factors to the record before this Court in today’s case, we conclude that the jury was justified in its finding that the images it viewed depicted “sexually explicit con*556duct.', 'general', 'Hood v. State', 'https://www.courtlistener.com/opinion/1575949/', '1575949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that an exception applies in today’s case because “[t]here is no privilege under this rule .', 'general', 'Hood v. State', 'https://www.courtlistener.com/opinion/1575949/', '1575949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it may not, and we reverse the judgment of the court of appeals.', 'general', 'Karenev v. State', 'https://www.courtlistener.com/opinion/1578755/', '1578755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '48 We conclude that the “Rabb/Rose ” rule is “a made-up .', 'general', 'Karenev v. State', 'https://www.courtlistener.com/opinion/1578755/', '1578755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a defendant may not raise for the first time on appeal a facial challenge to the constitutionality of a statute.', 'general', 'Karenev v. State', 'https://www.courtlistener.com/opinion/1578755/', '1578755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and remand to that court so that it may address appellant’s remaining claims.', 'general', 'Karenev v. State', 'https://www.courtlistener.com/opinion/1578755/', '1578755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the word “structure,” as used in Tenn.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1578633/', '1578633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is and affirm.', 'general', 'Lamb v. State', 'https://www.courtlistener.com/opinion/1580350/', '1580350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in this prosecution for criminal sexual conduct where the defendant claimed consent it was reversible error for an expert to testify concerning typical post-rape symptoms and behavior of rape victims and give opinions that the complainant was a victim of rape and had not fantasized the rape.', 'general', 'State v. Saldana', 'https://www.courtlistener.com/opinion/1580100/', '1580100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of Dreyer’s testimony was error.', 'general', 'State v. Saldana', 'https://www.courtlistener.com/opinion/1580100/', '1580100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the admission of such testimony requires the reversal of appellant’s conviction, and we remand for a new trial.', 'general', 'State v. Saldana', 'https://www.courtlistener.com/opinion/1580100/', '1580100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse appellant’s conviction and remand for a new trial.', 'general', 'State v. Saldana', 'https://www.courtlistener.com/opinion/1580100/', '1580100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We cannot address this argument because it is raised for the first time on appeal, and, therefore, we affirm.', 'general', 'Houston v. State', 'https://www.courtlistener.com/opinion/1587124/', '1587124') ON CONFLICT DO NOTHING;
