INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'Cuellar v. State', 'https://www.courtlistener.com/opinion/1591416/', '1591416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Court of Appeals.', 'general', 'Cuellar v. State', 'https://www.courtlistener.com/opinion/1591416/', '1591416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that appellant’s efforts to bring about a needed change in the law should not go unrewarded, because without such inducement change might not occur.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that the photograph was capable of authentication and previously supplied to all the parties, we conclude that the trial court abused its discretion by excluding the photograph.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In light of the foregoing, we find that appellant’s notice of appeal was adequate to preserve appellate review of the trial court’s intermediate order dismissing the claims regarding the Estate of Baby Boy Aka.', 'dismissal', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find merit in appellant’s arguments, and we reverse and remand for further action consistent with this opinion.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the trial court’s grant of partial summary judgment against the Estate of Baby Boy Aka.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court’s order granting summary judgment.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we will not reverse a trial court’s ruling on the admission of evidence absent an abuse of that discretion nor will we reverse absent a showing of prejudice.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We will not reverse a trial court’s ruling on the admission of evidence absent an abuse of that discretion, nor will we reverse absent a showing of prejudice.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 808 (1984), we affirmed a probate court’s finding that it was without authority to order the administration of the estate of an unborn fetus, and we declined to hold that an unborn or stillborn fetus was a deceased person within the meaning of the probate code.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Stewart, and we affirm the trial court on this issue.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we conclude that the District Court was in error, the judgment is reversed and the case is remanded for further proceedings.', 'general', 'United States v. Cores', 'https://www.courtlistener.com/opinion/105684/', '105684') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We conclude that the magistrate was correct in finding that defendant was not in a public place while she remained in the motor "vehicle.', 'general', 'State v. Lake', 'https://www.courtlistener.com/opinion/1602070/', '1602070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the judicial magistrate.', 'general', 'State v. Lake', 'https://www.courtlistener.com/opinion/1602070/', '1602070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the circuit court erred by allowing Dr.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that the circuit court erred in granting reverse waiver here, for three reasons: (1) the court substantively relied on inadmissible hearsay testimony from Dr.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that remand for a new reverse waiver hearing would not be appropriate under the facts of this case.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the juvenile must be given reasonable latitude to offer admissible evidence for the purpose of meeting his burden to prove the three elements for reverse waiver under Wis.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the general prohibition on hearsay applies to reverse waiver hearings, we conclude that Dr.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court erroneously exercised its discretion by refusing to allow Dr.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the circuit court erroneously exercised its discretion by allowing Dr.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that this matter is not moot, we conclude that a remand for a new reverse waiver hearing is not appropriate under these facts.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that remand is not appropriate under these facts.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that transferring this 19-year-old defendant to juvenile court would depreciate the seriousness of the offenses and undermine deterrence.', 'general', 'State v. Kleser', 'https://www.courtlistener.com/opinion/1602561/', '1602561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that evidence obtained by state officers during a search which, if conducted by federal officers, would have violated the defendant''s immunity from unreasonable searches and seizures under the Fourth Amendment is inadmissible over the defendant''s timely objection in a federal criminal trial.', 'search_seizure', 'Elkins v. United States', 'https://www.courtlistener.com/opinion/106107/', '106107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] For the reasons that follow we conclude that this doctrine can no longer be accepted.', 'general', 'Elkins v. United States', 'https://www.courtlistener.com/opinion/106107/', '106107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that none of the prosecutor’s statements violated defendant’s right to a fair trial.', 'general', 'People v. Abraham', 'https://www.courtlistener.com/opinion/1607809/', '1607809') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Conat, supra at 159, this Court held that the statute requiring adult sentences for juveniles tried as adults, MCL 769.', 'sentencing', 'People v. Abraham', 'https://www.courtlistener.com/opinion/1607809/', '1607809') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court in Conat, supra, disposed of this argument in a similar manner, *283and we conclude that its reasoning is equally applicable in the present case:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Abraham', 'https://www.courtlistener.com/opinion/1607809/', '1607809') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the dictionary definition of the word “knowingly” and applying the plain and ordinary meaning of the word to the language of the statute, we conclude that “knowingly” as contained in the statute means the same thing as the word “intentionally.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the dictionary definitions described above, as well as our Legislature’s deliberate use of different phrases when defining first- and second-degree child *243abuse, we conclude that first-degree child abuse is a specific-intent crime.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that there was ample evidence to support a finding of probable cause for second-degree murder.', 'probable_cause', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the circuit court did not err in reinstating the felony-murder charges.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, for the same reasons, we conclude that the district court abused its discretion in finding that the evidence only supported involun*245taiy manslaughter.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The majority cites with approval this Court’s opinion in People v Gould4 There, this Court held that first-degree child abuse was a specific-intent crime.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in People v Ainsworth,26 this Court held that the offense of stealing or retaining a financial-transaction device (more commonly known as a credit card) constitutes a specific-intent crime, given that knowledge is an essential part of the crime, because the statute27 requires that a person “knowingly” commit the offense.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” More to the point, however, we can presume that the Legislature was aware that in Gould68 this Court held the crime of first-degree child abuse to be a specific-intent crime but that, upon review, the Supreme Court classified this holding as dicta.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the dictionary definition of the word “knowingly” and applying the plain and ordinary meaning of the word to the language of the statute, we conclude that “knowingly” as contained in the statute means the same thing as the word “intentionally.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that a specific intent is required under the first-degree child abuse statute.', 'general', 'People v. Maynor', 'https://www.courtlistener.com/opinion/1607628/', '1607628') ON CONFLICT DO NOTHING;
