INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For purposes of review, we conclude that authority relating to the propriety of conditions of probation is applicable to conditions of extended supervision.', 'general', 'State v. Koenig', 'https://www.courtlistener.com/opinion/1608445/', '1608445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statutes were sufficiently specific so that when coupled with the probation condition, Lo had adequate notice of the expected conduct and an ascertainable standard for enforcement.', 'general', 'State v. Koenig', 'https://www.courtlistener.com/opinion/1608445/', '1608445') ON CONFLICT DO NOTHING;
