INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the district court.', 'general', 'State v. Dohlman', 'https://www.courtlistener.com/opinion/1621600/', '1621600') ON CONFLICT DO NOTHING;
