INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We conclude that McGowan held only that assault by threat requires the defendant to communicate a threat of imminent bodily injury;', 'general', 'Olivas v. State', 'https://www.courtlistener.com/opinion/1631136/', '1631136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Tunnell as required under the Texas Penal Code, we reverse the judgment of the court of appeals and remand the case to that court to address appellant’s remaining points of error.', 'general', 'Olivas v. State', 'https://www.courtlistener.com/opinion/1631136/', '1631136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '36 We affirmed the aggravated-assault-by-threat conviction against the daughter because “[t]he evidence showed that after she was initially stabbed by appellant [the daughter] saw him holding the knife and began begging appellant not to cut her.', 'general', 'Olivas v. State', 'https://www.courtlistener.com/opinion/1631136/', '1631136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, given all of the evidence, a rational jury would necessarily entertain a reasonable doubt as to the defendant’s guilt, the due process guarantee requires that we reverse and order a judgment of acquittal.', 'general', 'Swearingen v. State', 'https://www.courtlistener.com/opinion/1634893/', '1634893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court applied the Miranda ruling soon after it was announced by the United States Supreme Court, and early on, we held that a suspect need not be rt-Mirandized during continuous interrogation.', 'general', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we held that the initial Miranda warnings were sufficient and there was no Fifth Amendment violation.', 'general', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In making that ruling, we conclude that the circuit court properly guarded against the jury becoming confused by other burden-of-proof standards that are inapplicable in criminal cases.', 'general', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that there was some evidence before the jury to rationally support the giving of an instruction on the lesser-included offense of first-degree murder.', 'general', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have recently stated: In reviewing a trial judge’s ruling on a motion to suppress, we make an independent determination based upon the totality of the circumstances, viewing the evidence in a light most favorable to the State [appellee], and we reverse only if the ruling is clearly against the preponderance of the evidence.', 'suppression', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The evidence was suppressed and we affirmed.', 'suppression', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court’s refusal to give an instruction on a lesser-included offense stating, “[the officers’s] testimony so sharply conflicted with Doby’s that it would not be reasonable to expect a jury to pick and choose and come up with a finding of a lesser offense when to do so would require a finding that Doby was a liar and the officers liars in part.', 'general', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that this statement in Crabtree has been totally abrogated by the current statute, T.', 'general', 'State v. Walker', 'https://www.courtlistener.com/opinion/1638125/', '1638125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 705 (1967), we held that before a federal constitutional error can be held harmless, the review-*412mg court must find “beyond a reasonable doubt that the error complained of did not contribute to the verdict obtained.', 'general', 'State v. Walker', 'https://www.courtlistener.com/opinion/1638125/', '1638125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the challenged conduct did not constitute plain error because the prosecutor introduced the evidence on the basis of Lieutenant Hagler’s declared status as an expert witness in the area of street-gang investigation and practices.', 'general', 'People v. Gonzalez', 'https://www.courtlistener.com/opinion/1639096/', '1639096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*233We find that the trial court did not err in denying defendant Guerra’s motion to suppress.', 'suppression', 'People v. Gonzalez', 'https://www.courtlistener.com/opinion/1639096/', '1639096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Gonzalez', 'https://www.courtlistener.com/opinion/1639096/', '1639096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Beggs this Court held that in a trial for injury to a child, the jury must be instructed that they cannot find the defendant guilty unless they find that he intended the result of his conduct.', 'general', 'Schultz v. State', 'https://www.courtlistener.com/opinion/1640345/', '1640345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), when we held that the culpable mental state of “knowingly” must apply to the surrounding circumstances in the statute prohibiting the unauthorized use of a motor vehicle.', 'general', 'Schultz v. State', 'https://www.courtlistener.com/opinion/1640345/', '1640345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985) this court held that TexPe-nal Code § 31.', 'general', 'Schultz v. State', 'https://www.courtlistener.com/opinion/1640345/', '1640345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the photo array was not unduly suggestive, we may then disregard Swoopes’ argument that the physical lineup and the in-court identification were tainted.', 'general', 'State v. Swoopes', 'https://www.courtlistener.com/opinion/1643088/', '1643088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having therefore concluded that all of the assignments of error must be overruled, we affirm the convictions and sentences.', 'sentencing', 'State v. Swoopes', 'https://www.courtlistener.com/opinion/1643088/', '1643088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Russell', 'https://www.courtlistener.com/opinion/1647925/', '1647925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under our state constitutional standard of rational basis review the challenged statute cannot stand.', 'general', 'State v. Russell', 'https://www.courtlistener.com/opinion/1647925/', '1647925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like these courts, we conclude that when a law regulates sexual conduct involving a minor,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Act, neither on its face nor as applied to Senters, violates the right to privacy or the right to equal protection under the law.', 'general', 'State v. Senters', 'https://www.courtlistener.com/opinion/1648752/', '1648752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the rifle was inextricably intertwined with the crimes charged, and the photograph of the rifle was cer
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if the admission of the photograph was an abuse of the trial court’s discretion, we conclude that the error was harmless.', 'general', 'MONESTIME v. State', 'https://www.courtlistener.com/opinion/1649039/', '1649039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that competent, substantial evidence supports the trial court’s ruling on Monestime’s motion for judgment of acquittal.', 'general', 'MONESTIME v. State', 'https://www.courtlistener.com/opinion/1649039/', '1649039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the trial court’s admission of the gun evidence.', 'general', 'MONESTIME v. State', 'https://www.courtlistener.com/opinion/1649039/', '1649039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'extractable, we hold that the legislature unconstitutionally created
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '68 We hold that without subsection (2)’s special
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Drej, we held that it was appropriate to allow the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we conclude that, while the second of the two assaults on [the victim] merged with the murder, the first did not.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Lyon’s estate did not waive the psychotherapist-patient privilege for purposes of the present case.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this setting we conclude that the right of confrontation is paramount to the State’s policy of protecting a juvenile offender.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a limited disclosure of the medical records should be ordered in this case.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because that crime fell within the statutory definition of forcible felony and because a person commits murder in the first degree when he or she Mils another person while participating in a forcible felony, this court held in Beeman that willful injury could serve as a basis for a felony-murder conviction under Iowa Code section 707.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although in Hinkle this court held that the merger argument had not been preserved for consideration, it discussed the doctrine, as considered by other courts, and stated:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the inclusion, by the legislature, of “felonious assault” in sections 707.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In rejecting the equal-protection challenge lodged in Ragland, we found that there was a rational basis for concluding that the crime of willful injury posed a greater risk to the victim than other crimes for which felony murder may not be invoked.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that expert testimony that there was a 99.', 'general', 'State v. Joon Kyu Kim', 'https://www.courtlistener.com/opinion/1658035/', '1658035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 Because we cannot meaningfully distinguish the evidence offered in Boyd from that in the case now before us, we conclude that Boyd controls.', 'general', 'State v. Joon Kyu Kim', 'https://www.courtlistener.com/opinion/1658035/', '1658035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals.', 'general', 'State v. Joon Kyu Kim', 'https://www.courtlistener.com/opinion/1658035/', '1658035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals and hold that the state has not clearly and unequivocally shown that the trial court order suppressing statistical population frequency evidence was erroneous.', 'suppression', 'State v. Joon Kyu Kim', 'https://www.courtlistener.com/opinion/1658035/', '1658035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that by pleading guilty or nolo contendere defendants have waived their right to raise these issues on appeal.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, we hold that a defendant, after pleading guilty, may raise on appeal only those defenses and rights which would preclude the state from obtaining a valid conviction against the defendant.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we hold that a plea of nolo contendere has the same effect upon a defendant’s ability to raise an issue on appeal as does a plea of guilty.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a defendant may appeal from a denial of a Fourth Amendment or a Const 1963, art 1, § 11 search and seizure claim where "the defendant could not be prosecuted if *491his claim that a constitutional right against unreasonable search and seizure was violated is sustained and the defendant, the prosecutor, and the judge have agreed to the conditional plea.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '362 NW2d 655 (1984), this Court held that a defendant could obtain appellate review following a plea of guilty of a decision denying a motion to suppress evidence where the prosecutor and judge agreed at *498the time of the plea of guilty to a so-called conditional plea.', 'suppression', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, as this Court held in People v Reid, supra, appellate review is permissible following a plea of guilty when the prosecutor and the judge consent, then it ought to be questioned on what basis the prosecutor, the defendant’s adversary, and the judge, whose ruling would be reviewed, should be empowered to decide whether to allow or withhold "consent” to such review.', 'plea', 'People v. New', 'https://www.courtlistener.com/opinion/1658101/', '1658101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, on the basis of the dual grounds of the automobile exception, we hold that suppression is not warranted by the Fourth Amendment as applied to the states by the Fourteenth Amendment because the arson investigator had probable cause to search the vehicle without a warrant.', 'suppression', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Next we hold that suppression is also unjustified under the Michigan Constitution.', 'suppression', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following our review de novo of the circuit court’s decision to affirm, we hold that the district court abused its discretion in dismissing the charges.', 'dismissal', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the constitutional premise of Mapp v Ohio, supra at 655 (“We hold that all evidence obtained by searches and seizures in violation of the Constitution is, by that same authority, inadmissible in a state court.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '26 L Ed 2d 419 (1970), we held that when police officers have probable cause to believe there is contraband inside an automobile that has been stopped on the road, the officers may conduct a warrantless search of the vehicle, even after it has been impounded and is in police custody.', 'probable_cause', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, having concluded that the evidence of arson discovered during the search of defendant’s automobile was admissible, we conclude that the lower courts erred in dismissing the charges against defendant of burning personal property valued at greater than $1,000 but less than $20,000, MCL 750.', 'dismissal', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for trial.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Adhering to these views, we hold that no right protected by the Fourth Amendment was violated in the present case.', 'search_seizure', 'Hoffa v. United States', 'https://www.courtlistener.com/opinion/107318/', '107318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that none of the factors cited by the district court justified a departure.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the random firing of multiple shots into a group of people was contemplated by the legislature as the predicate facts upon which the presumptive sentence for second-degree murder by drive-by shooting is based, and therefore could not be used to justify an upward departure.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Ott, Ford, and Spaeth do not prohibit the district court from using “overlapping” facts to depart upward when a defendant is convicted of multiple offenses arising out of a single behavioral incident, if those facts show that the defendant committed the offense being sentenced in a particularly serious way.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For those reasons, we conclude that Jackson does not apply here.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that when a defendant is convicted of several offenses involving multiple victims arising out of a single behavioral incident, a sen-*607teneing court may use “overlapping” facts of those offenses as the basis for an upward departure, provided that those facts show that the defendant committed the offense being sentenced in a particularly serious way.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that the district court did not err when it used the risk to bystanders arising from Edwards’ conduct as an aggravating factor.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that facts underlying an uncharged separate incident are an impermissible basis for departure because those facts do not show that the offense being sentenced was committed in a particularly serious way.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that such facts may be used to depart.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the reasons provided by the district court were improper bases for departure.', 'general', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In both Ford and Spaeth, we concluded that the facts in question did not relate to the offense being sentenced.', 'sentencing', 'State v. Edwards', 'https://www.courtlistener.com/opinion/1665152/', '1665152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Brown', 'https://www.courtlistener.com/opinion/1670023/', '1670023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'McNeil, supra, we hold that here certiorari is the proper remedy.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that certiorari was the proper remedy.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though we held that the contempt citation was valid, we also held that the punishment of ninety days was unduly harsh, and we modified the penalty to five days and a fine of $500.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judge’s entered order controls and that the contempt was criminal contempt.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Clark, we reversed a contempt order where the trial judge held a lawyer in contempt for filing a motion for the judge to recuse.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The case was appealed to this court, and we affirmed the contempt finding because it was based on the attorney’s failure to comply with a court order to go to trial.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, given all the evidence, a rational jury would necessarily entertain a reasonable doubt as to the defendant’s guilt, the due process guarantee requires that we reverse and order a judgment of acquittal.', 'general', 'Alvarado v. State', 'https://www.courtlistener.com/opinion/1676536/', '1676536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no reversible error, we AFFIRM the judgments of the trial court.', 'general', 'Alvarado v. State', 'https://www.courtlistener.com/opinion/1676536/', '1676536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that victim impact evidence simply has no probative force in the sentencing context.', 'sentencing', 'Alvarado v. State', 'https://www.courtlistener.com/opinion/1676536/', '1676536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that, in the course of deciding a motion for new trial, a judge may evaluate the credibility of the witnesses.', 'general', 'People v. Herbert', 'https://www.courtlistener.com/opinion/1677370/', '1677370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Earlier, we held that Judge Sosnick had full authority to reconsider Judge Thorbum’s earlier rulings.', 'general', 'People v. Herbert', 'https://www.courtlistener.com/opinion/1677370/', '1677370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The defendant asks that we reverse Judge Sos-nick’s denial of the motion for a directed verdict.', 'general', 'People v. Herbert', 'https://www.courtlistener.com/opinion/1677370/', '1677370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Masters was not entitled to a lesser-included offense instruction under either
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Masters’ convictions and sentences but remand the cause to the district court with direction to give Masters credit on his firearm sentence for the time he served prior to sentencing.', 'sentencing', 'State v. Masters', 'https://www.courtlistener.com/opinion/1679554/', '1679554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm both of Masters’ sentences but remand the cause to the district court with direction to credit Masters’ firearm sentence with the amount of time he served prior to sentencing.', 'sentencing', 'State v. Masters', 'https://www.courtlistener.com/opinion/1679554/', '1679554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Simpson, in which we held that an inference of knowledge and control is warranted when the defendant shares exclusive dominion and control over the place where the drugs are found.', 'general', 'State v. Webb', 'https://www.courtlistener.com/opinion/1680623/', '1680623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That is because in Reeves we held that “where the ac*78cused has not been in exclusive possession of the premises but only in joint possession, knowledge of the presence of the substances on the premises and the ability to maintain control over them by the accused will not be inferred but must be established by proof.', 'general', 'State v. Webb', 'https://www.courtlistener.com/opinion/1680623/', '1680623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 We held that he was not entitled to an instruction on aggravated assault because the evidence (even his own testimony) showed that he was at least guilty of “intent to commit serious bodily injury” murder under § 19.', 'general', 'Guzman v. State', 'https://www.courtlistener.com/opinion/1867558/', '1867558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,9 this Court held that the evidence raised the culpable mental state of recklessness.', 'general', 'Guzman v. State', 'https://www.courtlistener.com/opinion/1867558/', '1867558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 This Court held that he was not entitled to that instruction because, at best, the evidence showed he was aware of the risk of death, and so he was at least reckless, which might have entitled him to a charge of involuntary manslaughter, but not to a charge of criminally negligent homicide.', 'general', 'Guzman v. State', 'https://www.courtlistener.com/opinion/1867558/', '1867558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we hold that a defendant seeking a jury instruction on perfect self-defense to a charge of first-degree intentional homicide must satisfy an objective threshold showing that she reasonably believed that she was preventing or terminating an unlawful interference with her person and reasonably believed that the force she used was necessary to prevent imminent death or great bodily harm.', 'jury_instruction', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we hold that a defendant seeking a jury instruction on unnecessary defensive force (imperfect self-defense) to a charge of first-degree intentional homicide is not required to satisfy an objective threshold showing that she was acting under a reasonable belief that she was in imminent danger of death or great bodily harm or that the force she used was necessary to defend herself.', 'jury_instruction', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, we hold that a defendant who claims self-defense to a charge of first-degree intentional ho*208micide may use evidence of a victim''s violent character and past acts of violence to show a satisfactory factual basis that she actually believed she was in imminent danger of death or great bodily harm and actually believed that the force used was necessary to defend herself, even if both beliefs were unreasonable.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a claim of imperfect self-defense, which mitigates first-degree intentional homicide to second-degree intentional homicide, does not require a showing that a person who used unnecessary defensive force was acting with a reasonable belief of an unlawful interference with her person.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because evidence that should have been admitted was excluded and because an instruction that should have been given was denied, we conclude that Debra Head is entitled to a new trial.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that Wis JI — Criminal 1014, the jury instruction involving the mitigation of first-degree intentional homicide to second-degree intentional homicide based on unnecessary defensive force, does not accurately reflect the law as set forth in this opinion.', 'jury_instruction', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '05(2), supported by the legislative history and articulated public policy behind the statute, we conclude that when imperfect self-defense is placed in issue by the trial evidence, the state has the burden to prove that the person had no actual belief that she was in imminent danger of death or great bodily harm, or no actual belief that the amount of force she used was necessary to prevent or terminate this interference.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that evidence of a victim''s violent character and of the victim''s prior acts of violence of which a defendant has knowledge should be considered in determining whether a sufficient factual basis exists to raise a claim of self-defense.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that a defendant need not meet an objective reasonable threshold to assert imperfect self-defense.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that Debra Head was entitled to a jury instruction on second-degree intentional homicide, we note that Wis JI — Criminal 1014 "First Degree Intentional Homicide: Self Defense: Second Degree Intentional Homicide.', 'jury_instruction', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that although ch.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/1685409/', '1685409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that violating a harassment injunction is a crime and that it is not a lesser-included offense of § 947.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/1685409/', '1685409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While Sveum''s argument is not unreasonable, we conclude that the legislature intended such violations to be punished as crimes and that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the legislature intended violations of harassment injunctions to he prosecuted as crimes.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/1685409/', '1685409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature''s use of the phrase "subject to," as opposed to "in violation of," directs that whether the defendant''s conduct actually violated the terms of the court''s order is not relevant in a prosecution under § 947.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/1685409/', '1685409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Sveum''s assumption about the permissible scope of harassment injunctions is mistaken.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/1685409/', '1685409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '013(lr) each require proof of an element that the other does not, we conclude that violating a harassment injunction is not a lesser-included offense of harassment under § 947.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/1685409/', '1685409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Sveum''s convictions for violating a Wis.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/1685409/', '1685409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that violating a harassment injunction is a crime and that it is not a lesser-included offense of Wis.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/1685409/', '1685409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Jones raises several points for appeal, none of which have merit, and we affirm the convictions.', 'general', 'Jones v. City of Little Rock', 'https://www.courtlistener.com/opinion/1685769/', '1685769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 would create the anomalous situation of barring the prosecution of a terrorist who communicates a threat by a physical act, but not the spoken or written word, we hold that physical acts which communicate a threat, as well as oral and written threats, fall within the ambit of that subdivision.', 'general', 'State v. Murphy', 'https://www.courtlistener.com/opinion/1691535/', '1691535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Murphy is not eligible for release for several years, we hold that his claim is prematurely raised and thus is not properly reviewable.', 'general', 'State v. Murphy', 'https://www.courtlistener.com/opinion/1691535/', '1691535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Murphy’s conduct constitutes terroristic threats, affirm the district court’s imposition of a 96-month sentence, but we do not reach the issue of Murphy’s condition of probation because this issue is not ripe for appellate review.', 'sentencing', 'State v. Murphy', 'https://www.courtlistener.com/opinion/1691535/', '1691535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewed as a whole, we conclude that these severe aggravating factors were sufficient to justify imposing a sentence more than two times the presumptive sentence established by the sentencing guidelines.', 'sentencing', 'State v. Murphy', 'https://www.courtlistener.com/opinion/1691535/', '1691535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because the court did not rely on Murphy’s criminal history score in departing from the sentencing guidelines, we conclude that the error was harmless and cannot serve as a basis for reversal.', 'sentencing', 'State v. Murphy', 'https://www.courtlistener.com/opinion/1691535/', '1691535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Murphy’s acts were threats to commit future acts of physical violence under Minn.', 'general', 'State v. Murphy', 'https://www.courtlistener.com/opinion/1691535/', '1691535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'In re Doris G.', 'https://www.courtlistener.com/opinion/5142769/', '5142769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in the circumstances of this case, the other-crime evidence together with Dr.', 'general', 'State v. Plaster', 'https://www.courtlistener.com/opinion/1701233/', '1701233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Plaster', 'https://www.courtlistener.com/opinion/1701233/', '1701233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1702618/', '1702618') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals'' decision.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1702618/', '1702618') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1702618/', '1702618') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments.', 'general', 'State v. Samson', 'https://www.courtlistener.com/opinion/5142881/', '5142881') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, *983we affirm the trial court’s denial of Samson’s first motion to suppress.', 'suppression', 'State v. Samson', 'https://www.courtlistener.com/opinion/5142881/', '5142881') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the potential prejudice suffered by Wiltgen from the use of an unreviewed administrative revocation to enhance a subsequent DWI rises to the level of a violation of her right to procedural due process.', 'general', 'State v. Wiltgen', 'https://www.courtlistener.com/opinion/1707012/', '1707012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we appreciate the important nature of the government interest, we conclude that Wiltgen’s interest in her liberty, combined with the risk of erroneous deprivation, outweighs the state’s interest in providing enhanced penalties for repeat offenders, pending resolution of the implied consent proceeding.', 'general', 'State v. Wiltgen', 'https://www.courtlistener.com/opinion/1707012/', '1707012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we concluded that the 2003 statutory elimination of the requirement that a hearing be “held at the earliest practicable date, and in any event no later than 60 days following the filing of the petition for review,” affected the third
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that the statutory elimination of the requirement for a prompt postrevocation
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and affirm the district court’s order reducing the DWI charge to third-degree.', 'general', 'State v. Wiltgen', 'https://www.courtlistener.com/opinion/1707012/', '1707012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the tort of negligent hiring, training or supervising is a valid claim in Wisconsin.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that a cause of action for negligent hiring, training or supervision is a valid claim in Wisconsin.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that negligent hiring, training or supervision is a valid claim in Wisconsin.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence is sufficient to support an award of punitive damages, assuming a causal connection between the employer''s negligence and the employee''s wrongful act.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court''s denial of Wal-Mart''s motion for directed *274verdict was not clearly erroneous.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the circuit court and remand for further proceedings only with respect to the elements of the tort as set forth in this opinion.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we determine that the violations of the different conditions of bond are different in fact and there is no clear indication to rebut the presumption that the legislature intended multiple punishments, we hold that the two convictions are not multiplicitous.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that charging this defendant with multiple counts of bail jumping for violating separate terms of the same bond is not multiplicitous.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that charging this defendant with multiple counts of bail jumping for violating separate terms of the same bond is not multiplicitous.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record, we conclude that the count of bail jumping for consuming alcohol and the count of bail jumping for contact with Lain are not identical in fact.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record, we conclude that the count of bail jumping based on Anderson''s consuming alcohol and the count of bail jumping based on his contact with Lain are different in fact.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the different interests meant to be protected by the legislature, we conclude that separate punishments for violations of different conditions of bond is appropriate.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our analysis of the four factors — statutory language, legislative history and context, the nature of the proscribed conduct, and the appropriateness of multiple punishments — we conclude that there is no clear indication to overcome the *757presumption that the legislature intended multiple punishments for violations of different conditions of the same bond.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals'' decision.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and uphold the circuit court''s entry of judgment for two convictions of bail jumping.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we believe that trial by jury in criminal cases is fundamental to the American scheme of justice, we hold that the Fourteenth Amendment guarantees a right of jury trial in all criminal cases whichwere they to be tried in a federal courtwould come within the Sixth Amendment''s guarantee.', 'general', 'Duncan v. Louisiana', 'https://www.courtlistener.com/opinion/107685/', '107685') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[14] Since we consider the appeal before *150 us to be such a case, we hold that the Constitution was violated when appellant''s demand for jury trial was refused.', 'general', 'Duncan v. Louisiana', 'https://www.courtlistener.com/opinion/107685/', '107685') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '20 does not authorize the trial court to grant a money judgment *375when seized property is missing or has been mistakenly returned to a third party, we reverse.', 'general', 'City of Milwaukee v. Glass', 'https://www.courtlistener.com/opinion/1718597/', '1718597') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the trial judge erroneously charged the jury in the language of the 1989 statute, in Bush we held that the error was harmless beyond a reasonable doubt, concluding that the proof established that the murder was heinous.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), this Court held the jury''s consideration of that aggravating circumstance harmless error beyond a reasonable doubt.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained below, considering the nature of the crime and the defendant in light of these factors, we conclude that imposition of the death penalty for the torturous and cruel premeditated killing of this young woman is not disproportionate to the penalty imposed in similar cases.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the nature of the dime and the defendant, we conclude that the torturous and cruel murder of this nineteen-year-old woman places Pike into the class of defendants for whom the death penalty is an appropriate punishment.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review, we conclude that the following cases in which the death penalty has been imposed have many similarities with this ease.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the risk to human life is inherent in the grading of the offense of conspiracy to commit first-degree murder.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For both of these reasons, we conclude that enhancement factor should not have been applied.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, given the circumstances surrounding this offense, especially the heinous nature of the crime and the fact that the Defendant showed no remorse, we conclude that the Defendant met the criteria for consecutive sentencing and the trial court did not abuse her discretion in ordering such.', 'sentencing', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon careful review of the record, we conclude that the Defendant has offered no grounds that warrant relief from her convictions of premeditated first degree murder and conspiracy to commit first degree murder.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that the Defendant has failed to establish any ground warranting relief from the sentence of death and the consecutive sentence of twenty-five (25) years.', 'sentencing', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing based upon the particular facts and circumstances there existing, we held that the witness statements did not bear “sufficient indicia of reliability" and that admission of the disputed statement in evidence was violative of the accused’s right of confrontation.', 'general', 'State v. Daniels', 'https://www.courtlistener.com/opinion/1723130/', '1723130') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Daniels', 'https://www.courtlistener.com/opinion/1723130/', '1723130') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a claim of repressed memory of past sexual abuse does not delay the accrual of a cause of action for non-incestuous sexual assault, regardless of the victim''s minority and the position of trust occupied by the alleged perpetrator.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we held that her claim was barred because she delayed too long after discovering the elements of her claim to file suit.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the discovery rule did not save plaintiffs cause of action because she knew all of the elements of her underlying claim against the priest, at the latest, by the time their relationship ended.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court of appeals certified the following question: Does the discovery rule save an otherwise untimely, non-incestuous, sexual assault claim against the individual alleged perpetrator when the alleged victim was a minor, and the alleged perpetrator was a person in a position of trust vis-a-vis the child/victim? Applying the discovery rule to these cases, we conclude that the plaintiffs'' claims were not timely filed because each of the plaintiffs discovered, or in the exercise of *319reason...', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in each case, the circuit court properly held that the claims of each plaintiff are barred by the statute of limitations for minors, and therefore affirm.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '15 Thus, we conclude that these five plaintiffs knew at least the identity of the responsible defendant and the nature of their injury no later than the time of the last sexual assault.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that, as a matter of law, these plaintiffs'' claims accrued at the time of their last assaults, we recognize that the legislature has given them varying amounts of time to file their causes of action based upon their respective ages at the time of the assaults.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon those considerations, as a matter of law we conclude that it would be contrary to public policy, and would defeat the purposes of limitations statutes, to allow claims of repressed memory to invoke the discovery rule and to indefinitely toll the statutory limitations for these plaintiffs.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that in each case, the respective circuit courts properly held that the claims of each plaintiff are barred by statutes of limitations.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we concluded that Ms.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because *312extension of incarceration constitutes compulsion and because there was a real and appreciable risk that any admissions made by Henderson would be incriminating in a potential perjury prosecution, we hold that the Commissioner violated Henderson’s privilege against self-incrimination by extending his incarceration by 45 days for refusal to admit his crime in sex offender treatment.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Morrow, we held that a disciplinary-sanction extending an inmate’s incarceration for refusing to admit his offense as part of sex offender treatment while his conviction was on direct appeal did not constitute “compulsion” for Fifth Amendment purposes.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “when Morrow received a 36-month sentence, those 36 months belonged presumptively to the state,” and when the state deprived Morrow of an opportunity for earlier supervised release, such deprivation did not constitute a substantial penalty.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that extension of incarceration “represents a significant departure from the basic conditions of the inmate’s sentence,” we held that a Minnesota inmate has a “protected liberty interest in his supervised release date that triggers a right to procedural due process before that date can be extended.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Carrillo we held that under the Minnesota sentencing scheme the extension of an inmate’s term of incarceration as a disciplinary sanction meets the Sandin test for a liberty interest because it is an atypical and significant hardship.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that principle applies to cases in which the sentence has been fixed and the judgment of conviction has become final.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004) (“[Ajpplying the vast sea of compulsion principles applied by the various opinions in McKune and the federal appellate decisions that followed, [we find that] the loss of good time credits imposed automatically and directly for plaintiffs failure to give up his right to silence and participate in the [sex offender treatment] program, violate every single one of them.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse, because Henderson had testified at trial that he did not commit the crime and admission of the offense in treatment would therefore have exposed him to prosecution for perjury.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals’ decision that at the time Henderson refused to participate in sex offender treatment, he no longer had a Fifth Amendment privilege against self-incrimination.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Morrow, we held that giving an inmate a choice between treatment and confinement for a larger portion of his sentence was not compulsion within the meaning of the Fifth Amendment.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying Sandin, we held that “any extension of an inmate’s period of imprisonment represents a significant departure from the basic conditions of the inmate’s sentence” and concluded that Carrillo had “a protected liberty interest in his supervised release date that triggers a right to procedural due process before that date can be extended.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the decision to bifurcate the trial and affirm the decision to postpone ruling on the admissibility of the prior conduct.', 'general', 'State v. Helmers', 'https://www.courtlistener.com/opinion/1732093/', '1732093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '459 (1969), we held that a failure to comply with Rule 11 required that a defendant who had pleaded guilty be allowed to plead anew.', 'plea', 'Brady v. United States', 'https://www.courtlistener.com/opinion/108137/', '108137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '831 (1969), we held that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held the statute valid, except for the death penalty provision;', 'general', 'Brady v. United States', 'https://www.courtlistener.com/opinion/108137/', '108137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Brady v. United States', 'https://www.courtlistener.com/opinion/108137/', '108137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing the conviction, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the Court of Appeals erred in reversing the order of the trial court denying defendant’s motion to quash the information.', 'general', 'People v. Doss', 'https://www.courtlistener.com/opinion/1738129/', '1738129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals and remand to the trial court for appropriate proceedings.', 'general', 'People v. Doss', 'https://www.courtlistener.com/opinion/1738129/', '1738129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 817 (1990), this Court held an individual had no standing to contest a warrantless search and seizure because there was no showing that the person owned or leased the searched premises.', 'search_seizure', 'Davasher v. State', 'https://www.courtlistener.com/opinion/1740214/', '1740214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction.', 'general', 'Davasher v. State', 'https://www.courtlistener.com/opinion/1740214/', '1740214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'THE CHIEF JUSTICE asserts that if we hold that capital punishment is unconstitutional because it is excessive, we will next have to determine whether a 10-year prison sentence rather than a five-year sentence is also excessive, or whether a $5 fine would not do equally well as a $10 fine.', 'sentencing', 'Furman v. Georgia', 'https://www.courtlistener.com/opinion/108605/', '108605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 207, this Court held "that committing to the untrammeled discretion of the jury the power to pronounce life or death in capital cases is [not] offensive to anything in the Constitution.', 'general', 'Furman v. Georgia', 'https://www.courtlistener.com/opinion/108605/', '108605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '130 (1879), this Court held that execution by shooting was not a prohibited mode of carrying out a sentence of death.', 'sentencing', 'Furman v. Georgia', 'https://www.courtlistener.com/opinion/108605/', '108605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taylor then filed a petition for review in this court, and we granted review only as to the second issue presented, namely: Is a sentence of 12 years of initial confinement and 6 years extended supervision excessive for this nineteen-year-old defendant who had non-forced sexual intercourse with a fifteen-year-old girl? We conclude that under the totality of the facts and circumstances of this case, the sentence is not excessive, and we affirm the court of appeals.', 'sentencing', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1742790/', '1742790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under our well-established standards for reviewing the circuit court''s exercise of its sentencing discretion, and in light of the individual facts and circumstances of this case, the circuit court exercised proper discretion in its sentence and in its refusal to modify that sentence.', 'sentencing', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1742790/', '1742790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1742790/', '1742790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately we concluded that "[w]hat has previously been satisfied with implied rationale must now be set forth on the record.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1742790/', '1742790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no basis for reversal, we affirm.', 'general', 'State v. Newell', 'https://www.courtlistener.com/opinion/1742814/', '1742814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the defendant’s conviction of first-degree murder.', 'general', 'State v. Newell', 'https://www.courtlistener.com/opinion/1742814/', '1742814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the constitutional requirements of the Confrontation Clause were met.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Officer Puckett’s testimony from the bond-revocation hearing was erroneously admitted into evidence under Ark.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the improper admission of Officer Puckett’s testimony was harmless error as to the offense of third-degree battery.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the testimony was well-developed because of the cross-examination of the witness with the purpose to impeach the testimony on the very point at issue at trial.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Johnson, we held that the motive to develop testimony at a probable-cause hearing was not similar to the motive to cross-examine at a trial.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the cross-examination was sufficient .', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even without Officer Puckett’s testimony, we conclude that the evidence of Proctor’s guilt on the stalking charge is overwhelming and, thus, the improper admission of the officer’s testimony was harmless as to the offense of second-degree stalking.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the erroneous admission of Officer Puckett’s testimony was harmless as to the offense of first-degree terroristic threatening.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Vick, we concluded that the cross-examination of the witness at a habeas corpus hearing was sufficient.', 'habeas', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm those convictions, but reverse and remand the attempted-murder conviction.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/1748052/', '1748052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in this case, the appellant did not adequately advise the trial court of his desire to have a hearing.', 'general', 'Gardner v. State', 'https://www.courtlistener.com/opinion/1749178/', '1749178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1019 (1898), this Court held that a dying declaration does not violate the right of confrontation and explained,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the 911 call was admissible as a dying declaration,20 we need not address *289its admissibility as a nontestimonial excited utterance or present-sense impression.', 'general', 'Gardner v. State', 'https://www.courtlistener.com/opinion/1749178/', '1749178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial court’s judgment and sentence of death.', 'sentencing', 'Gardner v. State', 'https://www.courtlistener.com/opinion/1749178/', '1749178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no reversible error, we affirm the judgment of the trial court.', 'general', 'Gardner v. State', 'https://www.courtlistener.com/opinion/1749178/', '1749178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Mr.', 'general', 'Ivy v. Keith', 'https://www.courtlistener.com/opinion/1752264/', '1752264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Judge Keith plainly, manifestly, and grossly abused his discretion in using criminal contempt as a penalty for failure to pay the Rule 11 sanctions.', 'general', 'Ivy v. Keith', 'https://www.courtlistener.com/opinion/1752264/', '1752264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jail sentence was intended as a punishment, not as an inducement to pay.', 'sentencing', 'Ivy v. Keith', 'https://www.courtlistener.com/opinion/1752264/', '1752264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hon.', 'general', 'Ivy v. Keith', 'https://www.courtlistener.com/opinion/1752264/', '1752264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 318 (1995), wherein this court held that [MJotions for directed verdict are superfluous when there is a trial without a jury as the judge would only be directing his own verdict and the entire purpose of a bench trial is to have the judge, rather than a jury, ascertain the sufficiency of the evidence to convict.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1755270/', '1755270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rule 33.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1755270/', '1755270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it will not and therefore we reverse.', 'general', 'Ernst & Ernst v. Hochfelder', 'https://www.courtlistener.com/opinion/109420/', '109420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that defendant’s confrontation right was violated by the admission of the statements, notwithstanding that the Fisch-ers refused to testify at trial.', 'general', 'State v. Hansen', 'https://www.courtlistener.com/opinion/1757692/', '1757692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), we held that the witness’ statements to police and her testimony at a prior trial were statements against penal interest under 804(b)(3) when they inculpated the defendant as well as the witness.', 'general', 'State v. Hansen', 'https://www.courtlistener.com/opinion/1757692/', '1757692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judgment of conviction must be reversed because introduction of the declarations violated both the hearsay rule and the confrontation clause of the sixth amendment, as incorporated in the fourteenth amendment, of the United States Constitution.', 'general', 'State v. Hansen', 'https://www.courtlistener.com/opinion/1757692/', '1757692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the determination, of whether an offense is a lesser-included offense is controlled by the elements of the crimes as set forth in the statutes and not by the facts presented in the particular case at issue.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/1760595/', '1760595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion in denying DF&amp;', 'general', 'Weiss v. Johnson', 'https://www.courtlistener.com/opinion/1760754/', '1760754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and dismiss, holding that the service provisions of Rule 4 are appEcable because the statutory procedure at issue is sEent on notice or service of process at the circuit court level.', 'dismissal', 'Weiss v. Johnson', 'https://www.courtlistener.com/opinion/1760754/', '1760754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not.', 'general', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we hold that, while neither party disputes the existence of probable cause to effect the arrest, sufficient exigent circumstances did not exist to overcome the strong presumption that warrantless home arrests are unreasonable.', 'probable_cause', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of the circumstances involved in the case at bar, we hold that, as in Patzner, Ms.', 'general', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the above-stated reasons, we hold that the State has failed to prove that the warrantless activity at issue in this case was reasonable based upon the totality of the circumstances, and hereby reverse and dismiss the case.', 'dismissal', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and, for the following reasons, we reverse the trial court and dismiss the case.', 'dismissal', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is the fact of the lawful arrest which establishes the authority to search, and we hold that in the case of a lawful custodial arrest a full search of the person is not only an exception to the warrant requirement of the Fourth Amendment, but is also a `reasonable'' search under that Amendment.', 'search_seizure', 'United States v. Chadwick', 'https://www.courtlistener.com/opinion/109714/', '109714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'United States v. Chadwick', 'https://www.courtlistener.com/opinion/109714/', '109714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[15] In short, we hold that the discretion vested in a district judge under § 5010 (d) is essentially the same as the traditional discretion vested in the court, for example, to impose the minimum sentence on a first offender or a larger sentence on a recidivist.', 'sentencing', 'Dorszynski v. United States', 'https://www.courtlistener.com/opinion/109093/', '109093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We conclude that while an express finding of no benefit must be made on the *426 record, the Act does not require that it be accompanied by supporting reasons.', 'general', 'Dorszynski v. United States', 'https://www.courtlistener.com/opinion/109093/', '109093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the agents had a reasonable basis to suspect that respondent was transporting illegal drugs on these facts.', 'general', 'United States v. Sokolow', 'https://www.courtlistener.com/opinion/112239/', '112239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, 30 (1968), we held that the police can stop and briefly detain a person for investigative purposes if the officer has a reasonable suspicion supported by articulable facts that criminal activity "may be afoot," even if the officer lacks probable cause.', 'probable_cause', 'United States v. Sokolow', 'https://www.courtlistener.com/opinion/112239/', '112239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Yocum v. State', 'https://www.courtlistener.com/opinion/1767843/', '1767843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the pledges here were "offers" or "sales" under § 17 (a);', 'general', 'Rubin v. United States', 'https://www.courtlistener.com/opinion/110378/', '110378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the issue is a close one, we hold that the evidence of Gates’s actual malice was not clear and convincing.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we held that while a message may be false and defamatory as a whole, even though no single statement is false, proof of actual malice requires clear and convincing evidence that the defendant “knew or strongly suspected that the publication as a whole could present a false and defamatory impression.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with the court of appeals that only the one defendant is liable for defamation, but we conclude that the jury’s finding of $7 million in mental anguish damages has no evidentiary support and is excessive as a matter of law by constitutional standards.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Judging Gates’s words from the perspective of a reasonable listener, as we must, we conclude that they could easily have been considered defamatory as the jury found.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence that Bunton acted with actual malice in defaming Bentley was clear and convincing.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the First Amendment requires appellate review of amounts awarded for non-economic damages in defamation cases to ensure that any recovery only compensates the plaintiff for actual injuries and is not a disguised disapproval of the defendant.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Exercising that review in this case, we conclude that while the record supports Bentley’s recovery of some amount of mental anguish damages, it does not support the amount of those damages found by the jury.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we conclude that there is no evidence to support part of the actual damage award, punitive damages must be reassessed as well.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is legally and factually sufficient to support the jury’s award of $7,150,000.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified and remand the case.', 'general', 'McGill v. State', 'https://www.courtlistener.com/opinion/1774542/', '1774542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 362 (1994), where this court held that, in cases where less than the presumptive amount was found in possession of the accused, but other proof of intent to deliver was present, the appellant’s conviction for possession with intent to deliver was proper.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/1781273/', '1781273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a prior conviction for a violent crime under Wis.', 'general', 'State v. Warbelton', 'https://www.courtlistener.com/opinion/1782289/', '1782289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the above, we conclude that a prior conviction for a violent crime under Wis.', 'general', 'State v. Warbelton', 'https://www.courtlistener.com/opinion/1782289/', '1782289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that a prior conviction for a violent crime under Wis.', 'general', 'State v. Warbelton', 'https://www.courtlistener.com/opinion/1782289/', '1782289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Due to the likelihood of unfair prejudice, we concluded that "the evidence of the defendant''s prior convictions, suspensions or revocations should be excluded and the [prior conviction] element not submitted to the jury because the probative value of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we concluded that it was not a matter for determination by the jury.', 'general', 'State v. Warbelton', 'https://www.courtlistener.com/opinion/1782289/', '1782289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals.', 'general', 'State v. Warbelton', 'https://www.courtlistener.com/opinion/1782289/', '1782289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the discovery that Shaibani testified falsely about his credentials is newly-discovered evidence that gives rise to a reasonable probability that, had the jury heard Shaibani''s misrepresentation about his credentials, it would have had a reasonable doubt as to Plude''s guilt.', 'general', 'State v. Plude', 'https://www.courtlistener.com/opinion/1784049/', '1784049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in a trial rife with conflicting and inconclusive medical expert testimony about a case the circuit court observed was based on "circumstantial evidence," there exists a reasonable probability that, had the jury discovered that Shaibani lied about his credentials, it would have had a reasonable doubt as to Plude''s guilt.', 'general', 'State v. Plude', 'https://www.courtlistener.com/opinion/1784049/', '1784049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the discovery that Shaibani testified falsely about his credentials is newly-discovered evidence that gives rise to a reasonable probability that had the jury heard of Shaibani''s misrepresentation about his credentials, it would have had a reasonable doubt as to Plude''s guilt.', 'general', 'State v. Plude', 'https://www.courtlistener.com/opinion/1784049/', '1784049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" That section provides this court with unique, discretionary authority to order a new trial when we conclude that the real controversy has not been fully tried or when there is a probable miscarriage of justice.', 'general', 'State v. Plude', 'https://www.courtlistener.com/opinion/1784049/', '1784049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in the absence of some permanent deprivation of life, liberty, or property related to the collection of the tax, applicant suffered no “punishment” for the purposes of the Double Jeopardy Clause.', 'general', 'Ex Parte Chappell', 'https://www.courtlistener.com/opinion/1785250/', '1785250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Thompson, supra, we held that an officer with reasonable suspicion under Ark.', 'general', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kaiser this court held that the police lacked reasonable suspicion to stop a vehicle suspected of carrying contraband when the information was provided by the Missouri State Police, who in turn told Arkansas authorities that the “information came from a reliable informant.', 'general', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 895 (1988), where this court held that the police lacked probable cause to make a warrantless entry into a home when an anonymous caller claimed that a person had been shot at a particular address and was dead.', 'probable_cause', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the tip carried with it sufficient indicia of reliability to give the officer reasonable suspicion to justify an investigatory stop.', 'general', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that under the totality of the circumstances, Smith’s tip carried with it sufficient indicia of reliability to justify an investigatory stop under Rule 3.', 'general', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s denial of appellant’s motion to suppress.', 'suppression', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the denial of Hammons’s motion to suppress because the two anonymous calls led the police detective to the parking lot for further investigation under Rule 2.', 'suppression', 'Frette v. City of Springdale', 'https://www.courtlistener.com/opinion/1785644/', '1785644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 655 ("We hold that all evidence obtained by searches and seizures in violation of the Constitution is, by that same authority, inadmissible in a state court").', 'general', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[34] Today, for the first time, this Court holds that although the Constitution has been violated, no court should do anything about it at any time and in any proceeding.', 'general', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the marginal or nonexistent benefits produced by suppressing evidence obtained in objectively reasonable reliance on a subsequently invalidated search warrant cannot justify the substantial costs of exclusion.', 'suppression', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the rule can have no substantial deterrent effect in the sorts of situations under consideration in this case, see infra, at 916-921, we conclude that it cannot pay its way in those situations.', 'general', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In determining whether persons aggrieved solely by the introduction of damaging evidence unlawfully obtained from their co-conspirators or codefendants could seek suppression, for example, we found that the additional benefits of such an extension of the exclusionary rule would not outweigh its costs.', 'suppression', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals.', 'general', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In essence, we conclude that the circuit court did not erroneously exercise its discretion.', 'general', 'State v. Gallion', 'https://www.courtlistener.com/opinion/1787862/', '1787862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the circuit court did not erroneously exercise its discretion.', 'general', 'State v. Gallion', 'https://www.courtlistener.com/opinion/1787862/', '1787862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the court of appeals.', 'general', 'State v. Gallion', 'https://www.courtlistener.com/opinion/1787862/', '1787862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals.', 'general', 'State v. Gallion', 'https://www.courtlistener.com/opinion/1787862/', '1787862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Trial Court denied Frazier’s request for a manslaughter instruction, and we affirmed.', 'general', 'Rainey v. State', 'https://www.courtlistener.com/opinion/1789021/', '1789021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'cases, and we affirm the judgment of the United States Court of Appeals for the Fifth Circuit.', 'general', 'Russello v. United States', 'https://www.courtlistener.com/opinion/111043/', '111043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the information supporting the no-knock and nighttime provisions in the search warrant was illegally obtained.', 'general', 'State v. Amundson', 'https://www.courtlistener.com/opinion/1792545/', '1792545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the search-warrant application, when viewed in its totality, provided a reasonable basis for the issuing magistrate to conclude that probable cause exists.', 'probable_cause', 'State v. Amundson', 'https://www.courtlistener.com/opinion/1792545/', '1792545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse Amund-son’s convictions, we need not reach the merits of this issue.', 'general', 'State v. Amundson', 'https://www.courtlistener.com/opinion/1792545/', '1792545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in our review of part B(l) and (2), for the purpose of declaratory judgment, we substitute our findings for those of the trier of fact only if we conclude that the trier of fact’s determination is clearly wrong.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our de novo review of part B(3), we conclude that the State did not prove beyond a reasonable doubt that “Takin’ It to the Jury” lacked any serious literary, artistic, political, or scientific value.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of exhibits 18 through 23 was error.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the admission of this testimony was prejudicial error, since the county attorney did not qualify as an expert.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, the State bears the burden of proving beyond a reasonable doubt all three elements of obscenity, and we find that this assignment of error is without merit.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the determination made by the district court under part B(3) as to exhibit 9.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 299 (1999), we affirmed the trier of fact’s finding that the visual depiction of a man masturbating appealed to the prurient interest, we do not compare that finding to the finding by the trier of fact in this case.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered the State’s assignments of error and finding that they have no merit, we affirm the judgment of the district court as modified.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Harrold, supra, this court held that the trier of facts’ finding that the visual depiction of a man masturbating appealed to the prurient interest was not clearly wrong.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '21, 28 (1974), instead of invoking notions of "absolute" prosecutorial discretion, we held that certain potentially vindictive exercises of prosecutorial discretion were both reviewable and impermissible.', 'general', 'Heckler v. Chaney', 'https://www.courtlistener.com/opinion/111383/', '111383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that *834 review was available.', 'general', 'Heckler v. Chaney', 'https://www.courtlistener.com/opinion/111383/', '111383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Heckler v. Chaney', 'https://www.courtlistener.com/opinion/111383/', '111383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But based on our analysis, as well as a natural reading of the statute, we hold that “failing to stop,” “failing to return,” and “failing to remain” are simply alternate methods of committing the same offense.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”5 In Ex parte Ervin, we held that the Double Jeopardy Clause prohibited convictions for both manslaughter and intoxication manslaughter when only one person was killed.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that a jury was not required to unanimously find which of three alleged acts or omissions resulted in the child victim’s death.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that the Double Jeopardy Clause prohibited the State from obtaining two injury to a child convictions for a death that resulted from both an act and an omis*906sion.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State with a jury charge that disjunctively charged these three different types of conduct as a single offense, we held that the State had charged “three different criminal acts,” and the defendant’s constitutional right to a unanimous verdict required that the jurors “unanimously agree[ ] upon the commission of any one of these criminal acts.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that two different types of conduct described by the offense of indecency with a child occurring at two different times were separate offenses, so that the disjunctive submission of the two types of conduct in the jury charge violated the right to jury unanimity.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these various statutory methods for committing the offense do not constitute separate offenses, but are merely alternate means of committing the same offense.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”20 We concluded that “separately described conduct constitutes a separate statutory offense” and could be separately prosecuted.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 We found that the Blockburger7 “same elements” test was “not the sole test for determining whether offenses are the same under the multiple punishments aspect of the Double Jeopardy Clause.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 We found that “the essential element or focus” of the injury to a child statute was “the result of the defendant’s conduct” — injury to child — “and not the possible combinations of conduct that cause the result.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is no merit to any issue except sufficiency of the evidence on the first-degree battery conviction.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1794962/', '1794962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case we find that it is appropriate to reduce the sentence from twenty years imprisonment, the maximum for first-degree battery, to six years, the maximum sentence for second degree battery.', 'sentencing', 'Smith v. State', 'https://www.courtlistener.com/opinion/1794962/', '1794962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court on this point as well.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1794962/', '1794962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing de novo the determination of probable cause for a warrantless search and seizure in this case, we conclude that, given the totality of the circumstances, the state failed to carry its burden to justify the warrantless arrest of appellant.', 'probable_cause', 'Torres v. State', 'https://www.courtlistener.com/opinion/1796535/', '1796535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Torres v. State', 'https://www.courtlistener.com/opinion/1796535/', '1796535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the uncontradicted testimony supports the trial judge’s finding of guilt, we affirm.', 'general', 'In re D.W.', 'https://www.courtlistener.com/opinion/5144614/', '5144614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such facts do not rebut the presumption that the appellant was represented by counsel and that counsel acted effectively.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record shows that the appellant was officially represented by counsel at all times in the litigation, and the appellant has failed to overcome the presumption that counsel was acting effectively at all times.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that motion had been overruled by operation of law and the order granting the motion was a nullity.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), we held that “trial counsel, retained or appointed, had the duty, obligation and responsibility to consult with and fully to advise his client concerning meaning and effect of the judgment rendered by the court, his right to appeal from that judgment, and the necessity of giving notice of appeal and taking other steps to pursue an appeal, as well as expressing his professional judgment as to possible grounds for appeal and their merit, and delineating advantages and disadvantages of ap...', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the State’s petition for discretionary review, we reversed and remanded the ease instructing the First Court to address the issue.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a motion for new trial is a critical stage of the proceedings and that appellant was entitled to be represented by an attorney.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986) (opinion on rehearing), we held that “[a]n advisory opinion results when a court attempts to decide an issue that does not arise from an actual controversy capable of final adjudication_” Ibid.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons recited below, we affirm.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1801879/', '1801879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the procedure employed below, allowing impeachment by evidence of a prior non-specified felony conviction, does not aid the trier of fact in judging a defendant’s credibility while affording a strong potential for prejudicing the defendant.', 'general', 'People v. Garth', 'https://www.courtlistener.com/opinion/1810867/', '1810867') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the District Court acted within its discretion, and we therefore affirm the judgment of the Court of Appeals.', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '`inherent power'' can only obscure analysis of the problem," we held that "whether a court has power to dismiss a complaint because of non-compliance with a production order depends exclusively upon Rule 37.', 'dismissal', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '250, 254 (1988), we held that a federal court could not invoke its inherent supervisory power to circumvent the harmless-error inquiry prescribed by Federal Rule of Criminal Procedure 52(a).', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Piper, supra, we held that the costs recoverable under a prior version of 28 U.', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '250 (1988), in which this Court held that a district court could not rely on its supervisory power as a means of circumventing the clear mandate of a procedural rule.', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the circumstances of this case, we find that the District Court acted within its discretion in assessing as a sanction for Chambers'' bad-faith conduct the entire amount of NASCO''s attorney''s fees.', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'People v. Rutledge', 'https://www.courtlistener.com/opinion/1817985/', '1817985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the terms “consume” and “possess” are ambiguous as used in the “minor in possession” statute because they can be interpreted in more than one manner.', 'general', 'People v. Rutledge', 'https://www.courtlistener.com/opinion/1817985/', '1817985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that minors who legally ingest alcohol in a jurisdiction outside Michigan and then return to Michigan (e.', 'general', 'People v. Rutledge', 'https://www.courtlistener.com/opinion/1817985/', '1817985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because the prosecutor has not raised an issue of fact and has not requested a remand, we conclude that a remand is unnecessary.', 'general', 'People v. Rutledge', 'https://www.courtlistener.com/opinion/1817985/', '1817985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'People v. Rutledge', 'https://www.courtlistener.com/opinion/1817985/', '1817985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*456In summary, we hold that because the stipulated facts establish that there is no allegation that Colvin committed or intended to commit a crime other than the OFP violation, and because the district court specifically found that Colvin’s OFP violation was a violation of the prohibition against entry onto his ex-wife’s residence, Colvin’s unconsented entry in violation of the OFP cannot be the basis for a burglary charge.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Larson, this court held that trespass cannot serve as the crime committed or intended to be committed to establish burglary.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the district court found that Colvin violated the no-entry provision of the OFP, but made no other finding of additional OFP violations, we conclude that Colvin was not charged with violation of the no-contact provision of the OFP.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” The dissent erroneously states that we conclude that Colvin’s sole intent was to enter the home.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that violation of a no-entry provision of an OFP, like trespass, is excluded from the crimes that can be the bases for the independent crime element of burglary.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 But we conclude that the same entry is insufficient to satisfy both the illegal entry element of the burglary statute and the independent-crime requirement.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the postconviction court erred when it declined to consider Maurstad’s criminal history score claim on the basis of waiver.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in Goff, we held that a defendant may challenge a criminal history score for the first time after sentencing, when the score includes a prior conviction obtained in violation of the defendant’s right to counsel.', 'sentencing', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we conclude that because a sentence based on an incorrect criminal history score is an illegal sentence — and therefore, under Minn.', 'sentencing', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that a defendant cannot forfeit review of his criminal history score calculation, and accordingly, the plain error doctrine is inapplicable in this case.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite the state’s initial contention that the applicable guidelines are unambiguous, we conclude that the state’s arguments center not on the unambiguous nature of the guidelines’ language, but rather on the intent behind that language.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'C is relevant here, because we conclude that the language of this section is ambiguous in light of the words the Pennington County District Court used in “pronouncing” Maurstad’s length of stay.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if the Pennington County District Court had placed Maur-stad on probation for 10 years, he could have been “discharged early from probation” on any date before 10 years had passed and therefore still be within the “initial length of stay” when he committed the current offenses.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Drawing on the discussion in Osborne, we conclude that just as it would be logically untenable to allow a defendant to waive by silence a right that he must waive by affirmative act, it would be logically untenable to allow a defendant to waive by silence an alleged error that he cannot waive by affirmative act.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court then stated, “it is hereby ordered that the imposition of the sentence is stayed and you [Maurstad] will be placed on supervised probation * * * for a period not to exceed the statutory maximum.', 'sentencing', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We must make this determination in light of (1) the court’s sentencing pronouncement that, “it is hereby ordered that the imposition of sentence is stayed and you will be placed on supervised probation * ⅜ * for a period not to exceed the statutory maximum [of ten years]” (emphasis added);', 'sentencing', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Osborne where we concluded that application of the plain error doctrine was not appropriate.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Osborne we found that the defendant was not aware of the issue that was the subject of appellate review.', 'general', 'State v. Maurstad', 'https://www.courtlistener.com/opinion/1832488/', '1832488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court in Brunner’s case did not abuse its discretion in concluding that the source code may relate to his guilt or innocence.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1977), we held that a pretrial order will only be reversed if the State “demonstrates clearly and unequivocally that the trial court has erred in its judgment and that, unless reversed, the error will have a critical impact on the outcome of the trial.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the State failed to demonstrate that an error in the order would have a critical impact on the defendant’s prosecution.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the State had not established critical impact.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the Commissioner had failed to meet his burden of demonstrating that the *687source code was “clearly not discoverable” because the source code was in “possession, custody or control” of the State;', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to appellant Brunner, however, we reverse the court of appeals and reinstate the district court’s order for State production of the complete computer source code for the Minnesota model of the Intoxilyzer 5000EN.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we affirm the court of appeals’ decision to reverse the production order in appellant Underdahl’s case.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While not central to our decision, the rule we affirm today fulfills the original purpose behind Minn.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In appellant Underdahl’s case, we affirm the court of appeals and reverse the production order in his case.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the district court discovery orders meet the critical impact test because the exclusion of the breath test results will significantly reduce the likelihood of a successful prosecution on a charged offense.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the Commissioner of Public Safety "failed to meet his burden of demonstrating that the [source code being] sought is clearly not discoverable.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the court of appeals'' denial of a writ of prohibition sought by the State to prevent the district court from enforcing its order.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, even though a jury instruction on exigent circum*593stances could have been given under the evidence presented to the jury, because Ferguson struggled with the officers outside of her home when she was in lawful custody of the police, the instruction given accurately set out the law for the officers'' actions at that time.', 'jury_instruction', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury must have decided that the police were acting with lawful authority.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the test set forth in Harvey, we conclude that if the failure to instruct the jury on exigent circumstances was error, it was harmless.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, even though a jury instruction on exigent circumstances could have been given under the evidence presented to the jury, because Ferguson struggled with the officers outside of her home when she was in lawful custody of the police, the instruction given accurately set out the law for the officers'' actions at that time.', 'jury_instruction', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that due to the law-declaring function of this court, it is our responsibility to overrule Mikkelson''s incorrect interpretation.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and affirm the circuit court''s judgment of conviction.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the search of Andrea Wynne’s purse cannot be justified as incident to a lawful arrest.', 'general', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the search of Wynne’s purse constituted a search of her person and did not fall within the ambit of the premises search warrant.', 'general', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a sufficient nexus does not exist in the current situation.', 'general', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Andrea Wynne’s status as the daughter of Joy Wynne, living in the elder’s home where drugs were found was not enough to form the basis for probable cause to arrest Andrea Wynne.', 'probable_cause', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case we conclude that the search of Andrea Wynne’s purse violated her constitutional rights.', 'general', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our prior decisions on these issues, we hold that a defendant who testifies about his convictions on direct examination after denial of a motion in limine to exclude those convictions has not forfeited the opportunity to appeal the admissibility of those prior convictions.', 'general', 'State v. Swanson', 'https://www.courtlistener.com/opinion/1860432/', '1860432') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore we hold that sufficient evidence exists to find Swanson liable for the kidnapping under either section 609.', 'general', 'State v. Swanson', 'https://www.courtlistener.com/opinion/1860432/', '1860432') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that momentary confinement of the victim of a greater offense did not provide a basis for a separate kidnapping conviction.', 'general', 'State v. Swanson', 'https://www.courtlistener.com/opinion/1860432/', '1860432') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When reviewing claims of prosecutorial misconduct, we reverse only if the misconduct, when considered in light of the whole trial, impaired the defendant’s right to a fair trial.', 'general', 'State v. Swanson', 'https://www.courtlistener.com/opinion/1860432/', '1860432') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because sufficient evidence exists to sustain the kidnapping conviction, the consecutive sentence for kidnapping does not exaggerate the criminality of Swanson’s conduct, and there is no error warranting a new trial, we affirm.', 'sentencing', 'State v. Swanson', 'https://www.courtlistener.com/opinion/1860432/', '1860432') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we hold that the court did not err when it denied Blom’s motions to change the venue of his trial from the City of Virginia, to continue the trial, and to sequester the jury-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Blom’s request for retrial on these grounds lacks merit.', 'general', 'State v. Blom', 'https://www.courtlistener.com/opinion/1867526/', '1867526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'evidence, we hold that here the district court did not abuse its discretion when it permitted the admission of the 1983 incident as
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we hold that the court’s denial of Blom’s request to represent himself did not violate his rights as guaranteed by the Sixth and Fourteenth Amendments of the U.', 'general', 'State v. Blom', 'https://www.courtlistener.com/opinion/1867526/', '1867526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Blom’s statement was not inadmissible on the ground that it was given involuntarily.', 'general', 'State v. Blom', 'https://www.courtlistener.com/opinion/1867526/', '1867526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Blom waived the evidentiary protections of Rule 410 and therefore the district court did not err when it concluded that Blom’s confession was admissible.', 'general', 'State v. Blom', 'https://www.courtlistener.com/opinion/1867526/', '1867526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the jury’s guilty verdict was surely unattributable to the court’s erroneous exclusion of the alternative-perpetrator evidence.', 'general', 'State v. Blom', 'https://www.courtlistener.com/opinion/1867526/', '1867526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, for the reasons stated above, we hold that Blom’s numerous claims of ineffective assistance of trial counsel are without merit.', 'ineffective_assistance', 'State v. Blom', 'https://www.courtlistener.com/opinion/1867526/', '1867526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, by his testimoriy, the defendant impliedly waived the physician/patient privilege and it was proper for the district court to allow the defendant’s treating physician to give limited testimony that the defendant had taken a nonlethal dose of medication and that he had only superficial cuts on his wrists, and thus impeach the defendant’s claim that he had tried to commit suicide.', 'general', 'State v. Blom', 'https://www.courtlistener.com/opinion/1867526/', '1867526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court sufficiently verified that the seated jurors would be fair and impartial and did not abuse its discretion in denying Blom’s motions.', 'general', 'State v. Blom', 'https://www.courtlistener.com/opinion/1867526/', '1867526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a “judgment for costs against a criminal defendant creates a civil, not a criminal, liability.', 'general', 'State v. Sluyter', 'https://www.courtlistener.com/opinion/1869181/', '1869181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, “[i]n light of the circumstances of this case, the availability of the § 626.', 'general', 'State v. Sluyter', 'https://www.courtlistener.com/opinion/1869181/', '1869181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, in the absence of such an exception, “a judgment for costs is to be enforced by execution.', 'general', 'State v. Sluyter', 'https://www.courtlistener.com/opinion/1869181/', '1869181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a probationer has a due process right to a competency determination when during the probation revocation proceeding the administrative law judge has reason to doubt the probationer''s compe
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of these cases, we hold that habeas corpus was a proper method for Vanderbeke to use in challenging his probation revocation on the grounds of violation of due process because of incompe
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when an administrative law judge has reason to doubt that a probationer is competent, a competency proceeding should be conducted by the circuit court in the county in which the probationer was sentenced and that the competency proceeding should adhere to Wis.', 'sentencing', 'State Ex Rel. Vanderbeke v. Endicott', 'https://www.courtlistener.com/opinion/1876909/', '1876909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that the record, although limited, reveals that the administrative law judge had reason to doubt Vanderbeke''s competency;', 'general', 'State Ex Rel. Vanderbeke v. Endicott', 'https://www.courtlistener.com/opinion/1876909/', '1876909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we conclude that when an administrative law judge during a probation revocation proceeding has reason to doubt that a probationer is competent,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we conclude that the guarantee of due process of law requires that a probationer be afforded a competency proceeding when an administrative law judge has reason to doubt the probationer''s competency during a probation revocation proceeding.', 'general', 'State Ex Rel. Vanderbeke v. Endicott', 'https://www.courtlistener.com/opinion/1876909/', '1876909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the constitutional guarantee of due process of law requires the state to provide competency proceedings for persons who are the subjects of probation revocation proceedings, we must craft a procedure to afford probationers their constitutional rights.', 'general', 'State Ex Rel. Vanderbeke v. Endicott', 'https://www.courtlistener.com/opinion/1876909/', '1876909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because an administrative law judge, unlike a circuit court, has no statutory power to conduct competency proceedings and has no experience conducting such proceedings, we conclude that a circuit court should conduct competency proceedings for probationers who are the subjects of probation revocation proceedings.', 'general', 'State Ex Rel. Vanderbeke v. Endicott', 'https://www.courtlistener.com/opinion/1876909/', '1876909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record leaves little question that the administrative law judge had reason to doubt Vanderbeke''s competency.', 'general', 'State Ex Rel. Vanderbeke v. Endicott', 'https://www.courtlistener.com/opinion/1876909/', '1876909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of the circuit court quashing the writ of habeas corpus and remand the.', 'habeas', 'State Ex Rel. Vanderbeke v. Endicott', 'https://www.courtlistener.com/opinion/1876909/', '1876909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that one injury in this case was a significant bodily injury and the other was not, we hold that wounds created by a bullet are not per se significant bodily injuries.', 'general', 'Nero v. United States', 'https://www.courtlistener.com/opinion/5146909/', '5146909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the nature and extent of Randy Brown’s injury, we hold that a reasonable juror could fairly conclude beyond a reasonable doubt that it was significant.', 'general', 'Nero v. United States', 'https://www.courtlistener.com/opinion/5146909/', '5146909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that appellant’s convictions for ADW, AAWA, and mayhem while armed merge into a single AAWA conviction.', 'general', 'Nero v. United States', 'https://www.courtlistener.com/opinion/5146909/', '5146909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2010), this court held that a lacerated ear, which required four to six stitches, was a significant bodily injury.', 'general', 'Nero v. United States', 'https://www.courtlistener.com/opinion/5146909/', '5146909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In contrast, this court held in Quintanilla that short-term headaches and swollen fingers did not constitute significant bodily injuries.', 'general', 'Nero v. United States', 'https://www.courtlistener.com/opinion/5146909/', '5146909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the above, we conclude that the evidence was sufficient for a reasonably jury to conclude beyond a reasonable doubt that Randy Brown’s injury was significant, while the evidence was insufficient to support a similar finding as to Mark Brown’s injury.', 'general', 'Nero v. United States', 'https://www.courtlistener.com/opinion/5146909/', '5146909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand for vacation of several of his convictions.', 'general', 'Nero v. United States', 'https://www.courtlistener.com/opinion/5146909/', '5146909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, upon our review, we conclude that the record supports the factual findings of the suppression court, we are bound by those facts, and may reverse only if the legal conclusions drawn therefrom are in error.', 'suppression', 'Commonwealth v. Ventura', 'https://www.courtlistener.com/opinion/1886361/', '1886361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, even assuming the evidence was relevant, we conclude that the trial court did not err in precluding Dr.', 'general', 'Commonwealth v. Ventura', 'https://www.courtlistener.com/opinion/1886361/', '1886361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the trial court clearly relied upon the presentence report, and the sentence imposed was neither outside the applicable guidelines nor unreasonable, we find that the trial court did not abuse its discretion and, thus, there is no merit to Ventura’s sentencing claims.', 'sentencing', 'Commonwealth v. Ventura', 'https://www.courtlistener.com/opinion/1886361/', '1886361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 19 We find that this evidence was sufficient
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 22 We find that based on the foregoing, the trial court did not err in determining that Ventura knowingly waived his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 48 Finally, we find that there was sufficient evidence to prove that Ventura committed third-degree murder.', 'general', 'Commonwealth v. Ventura', 'https://www.courtlistener.com/opinion/1886361/', '1886361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration, we affirm.', 'general', 'Commonwealth v. Ventura', 'https://www.courtlistener.com/opinion/1886361/', '1886361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in denying Appellant’s fifth request for a continuance, which was based upon nothing more than an unsupported allegation.', 'general', 'Commonwealth v. Antidormi', 'https://www.courtlistener.com/opinion/5147566/', '5147566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Appellant has presented a substantial question only with regard to his sentence under subsection 2705.', 'sentencing', 'Commonwealth v. Antidormi', 'https://www.courtlistener.com/opinion/5147566/', '5147566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the anemic probative value of the evidence in Harris, we concluded that the fingerprint report could not “reasonably be taken to put the whole case in such a different light as to undermine confidence in the verdict.', 'general', 'Commonwealth v. Antidormi', 'https://www.courtlistener.com/opinion/5147566/', '5147566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Antidormi', 'https://www.courtlistener.com/opinion/5147566/', '5147566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1804 (1984), this Court held that where a party seeks to introduce the testimony of a witness, who has previously been hypnotized that party is to: (1) advise the court of the existence of the hypnosis;', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we conclude that the evidence was sufficient to support the finding of three aggravating circumstances in relation to killing of Fortney;', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we find that the trial court did not abuse its discretion in consolidating for trial the Informations relating to the homicides at issue.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because Appellant fails to make any contention relating to any specific item of pre-trial publicity other than the aforementioned Ladies’ Home Journal article, even if we assume the existence of such publicity, we find that his argument fails in relation to those items.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we find that Appellant is similarly not entitled to relief on his allegation of counsel ineffectiveness in relation to the motion to change venue/venire.', 'ineffective_assistance', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, given our deferential view of its decisions in this area of the law and the rationale explained above, we find that the trial court did not abuse its discretion in denying “for cause” challenges to these venire persons.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the third Smoyer guideline was satisfied and that Appellant’s claim of counsel ineffectiveness fails because the substantive claim lacks merit.', 'ineffective_assistance', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court acted entirely within its discretion in refusing to voir dire the jurors, thus avoiding inadvertently notifying the jury of the contents of the article, and giving a sufficient precautionary instruction to secure the integrity of the trial.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Appellant’s argument is without merit.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, given the circumstances at hand, such as the length of the trial, the fact that Burns was the last ■witness to testify, and his unexcused lateness, we find that the trial court’s action did not constitute an abuse of judicial discretion.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, just as this Court held in Patterson that the trial court did not err in refusing to dismiss the juror at issue in that case, I agree with the majority that the trial court below did not err in refusing to dismiss the challenged venirepersons for cause here.', 'dismissal', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in the legal standards applied by the district court, we affirm Garcia’s conviction for identity theft.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1889897/', '1889897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the application of our State’s broader retroactivity'' jurisprudence to defendant’s PCR petition on collateral attack demonstrates that there should not be retroactive application of our decision in Anderson to defendant’s PCR petition.', 'general', 'State v. Purnell', 'https://www.courtlistener.com/opinion/1889536/', '1889536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that defendant is not permitted to collaterally attack his prior judgment of conviction for perjury by having the new rule announced in Anderson and Gaudin retroactively applied.', 'general', 'State v. Purnell', 'https://www.courtlistener.com/opinion/1889536/', '1889536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts of the case, we conclude that the procedure employed in defendant’s trial for perjury is a “far cry [different] from the kind of absolute prerequisite to the fundamental fairness that is ‘implicit in the concept of ordered liberty.', 'general', 'State v. Purnell', 'https://www.courtlistener.com/opinion/1889536/', '1889536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the juvenile court did not misapply the factors set forth in § 6355(a)(4)(iii).', 'general', 'Commonwealth v. Spotti', 'https://www.courtlistener.com/opinion/5147998/', '5147998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Appellant’s due process rights were not violated by Trooper Armour’s failure to preserve the recording.', 'general', 'Commonwealth v. Spotti', 'https://www.courtlistener.com/opinion/5147998/', '5147998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Appellant has failed to demonstrate that the juvenile court abused its discretion in transferring his case to criminal court.', 'general', 'Commonwealth v. Spotti', 'https://www.courtlistener.com/opinion/5147998/', '5147998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, viewing all the evidence in the light most favorable to the Commonwealth as verdict-winner, we find that there was sufficient evidence to support Appellant’s convictions for AA-DUI.', 'general', 'Commonwealth v. Spotti', 'https://www.courtlistener.com/opinion/5147998/', '5147998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the foregoing, we find that there was sufficient evidence that Mr.', 'general', 'Commonwealth v. Spotti', 'https://www.courtlistener.com/opinion/5147998/', '5147998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm.', 'general', 'Commonwealth v. Spotti', 'https://www.courtlistener.com/opinion/5147998/', '5147998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Spotti', 'https://www.courtlistener.com/opinion/5147998/', '5147998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s determination that Mr.', 'general', 'Commonwealth v. Spotti', 'https://www.courtlistener.com/opinion/5147998/', '5147998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a parolee is taken into custody on a parole warrant, the confinement is attributable to the original offense on which the parole was granted and not to any offense or offenses committed during the parolee’s release.', 'general', 'State v. Black', 'https://www.courtlistener.com/opinion/1898779/', '1898779') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that defendant’s argument must fail under both federal and New Jersey double jeopardy jurisprudence as it existed prior to the Supreme Court’s decision in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1212 (1992)(in which a plurality of this Court held that the Commonwealth may appeal a pre-trial order granting a motion in limine if the order terminates or substantially handicaps the prosecution);', 'general', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the suppression motion was a substantial first step leading directly into the guilt-determining process because the suppression motion in Jones was returnable at the time of trial.', 'suppression', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jarman and Modaffare, this Court held that the evidence was insufficient to sustain convictions for driving under the influence of alcohol where blood samples taken approximately one hour after the defendants operated their vehicles showed that their blood alcohol levels were slightly above the 0.', 'general', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Commonwealth did not introduce expert testimony to relate back the defendants’ blood alcohol level at the time they drove their cars, this Court held that the convictions were based on speculation and there was no proof beyond a reasonable doubt.', 'general', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Order of the Superior Court.', 'general', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the Order of the Superior Court and we remand this case to the Court of Common Pleas of McKean County for trial.', 'plea', 'Commonwealth v. Matis', 'https://www.courtlistener.com/opinion/1899206/', '1899206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '672 NW2d 897 (2003), this Court held that violation of a court rule was not structural error requiring automatic reversal.', 'general', 'People v. Plumaj', 'https://www.courtlistener.com/opinion/1901119/', '1901119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court erred in granting defendant’s motions to set aside his pleas without first determining whether the pleas were understandingly, knowingly, voluntarily, and accurately made, we reverse and remand for further proceedings consistent with this opinion.', 'plea', 'People v. Plumaj', 'https://www.courtlistener.com/opinion/1901119/', '1901119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), we concluded that Burrell’s waiver of his Miranda rights was ineffective because of the lack of a parent’s presence.', 'ineffective_assistance', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the found circumstances, we hold that the district court properly imputed knowledge of potential adult prosecution to Far-dan.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the absence of Fardan’s father did not invalidate Fardan’s waiver of his Miranda rights.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on all of these factors, we hold that the district court did not abuse its discretion in admitting the evidence of the later robbery, burglary, kidnapping and shootings into the trunk.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the prejudicial impact of the criminal sexual conduct evidence outweighs any limited probative value, we hold that it was an *320abuse of discretion to admit evidence of Fardan’s criminal sexual conduct.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was sufficient to support the conviction for intentional felony murder.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The evidence supports the court’s findings, and we hold that the court did not abuse its discretion in sentencing.', 'sentencing', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is no reasonable possibility that the erroneous admission of Fardan’s criminal sexual con*321duct significantly affected the jury’s verdict, and hold that the district court’s erroneous admission of the evidence was not reversible error.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But, as Fardan notes, in Burrell, we concluded that a Miranda waiver was ineffective primarily because of the lack of a parent’s presence.', 'ineffective_assistance', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Courtney, we concluded that Spreigl evidence of a domestic assault was erroneously admitted to inform on the defendant’s intent to point a gun at a police officer.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that evidence that the defendant was armed with a pistol when he accosted the victim and shot him at close range would “alone” be sufficient for the jury’s finding of intentional murder.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ogle, we held that both negligent participants in a "drag race" were equally liable for a fatal collision resulting from their negligence, even though only one of the tortfeasors struck a third automobile causing injury.', 'general', 'Richards v. Badger Mutual Insurance', 'https://www.courtlistener.com/opinion/1917348/', '1917348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '045(2) are employed and the concerted action theory of liability is explained, we conclude that § 895.', 'general', 'Richards v. Badger Mutual Insurance', 'https://www.courtlistener.com/opinion/1917348/', '1917348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We affirm the court of appeals.', 'general', 'Richards v. Badger Mutual Insurance', 'https://www.courtlistener.com/opinion/1917348/', '1917348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record provides reasonable support for the trial court’s disposition.', 'general', 'State ex rel. M.T.S.', 'https://www.courtlistener.com/opinion/7405088/', '7405088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Appellate Division and reinstate the disposition of juvenile delinquency for the commission of second-degree sexual assault.', 'general', 'State ex rel. M.T.S.', 'https://www.courtlistener.com/opinion/7405088/', '7405088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2, namely, operating a motor vehicle while ‘under the influence of any intoxicating liquor, toluene, or any controlled substance as defined [by law],’ ” and accordingly, we held that, “the well-known canon of statutory construction in pañ mateña dictates that similar statutes should be interpreted similarly.', 'general', 'State v. DiStefano', 'https://www.courtlistener.com/opinion/1918253/', '1918253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, a majority of this Court holds that under the existing statutory framework, consent is a condition precedent to admissibility.', 'general', 'State v. DiStefano', 'https://www.courtlistener.com/opinion/1918253/', '1918253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that § 31-27-2.', 'general', 'State v. DiStefano', 'https://www.courtlistener.com/opinion/1918253/', '1918253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that Netland’s right to due process was not violated and that the criminal test-refusal statute did not result in an unconstitutional search, we reverse.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circumstances of Netland’s chemical test do not rise to the level of a violation of her right to due process.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the criminal test-refusal statute does not violate the prohibition against unreasonable searches and seizures found in the federal and state constitutions because under the exigency exception, no warrant is necessary to secure a blood-alcohol test where there is probable cause to suspect a crime in which chemical impairment is an element of the offense.', 'probable_cause', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Shriner, we held that the “rapid, natural dissipation of alcohol in the blood creates single-factor exigent circumstances that will justify the police taking a war-rantless, nonconsensual blood draw from a defendant, provided that the police have probable cause to believe the defendant committed criminal vehicular homicide or operation.', 'probable_cause', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our careful review of the record, we conclude that Netland’s conviction for criminal test refusal is not fundamentally unfair, as our cases have addressed that concept, nor does it offend our “sense of fair play and decency.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, as set forth below, we conclude that Netland has not shown that a warrantless search for her blood-alcohol content would have been unconstitutional, we need not determine whether the unconstitutional conditions doctrine applies to Fourth Amendment rights or whether it should be applied to violations of the Minnesota Constitution.', 'search_seizure', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But because Netland did not argue that her conviction conflicts with the statute, we conclude that the statutory interpretation question is better left for another case when the record on this question is developed at the district court.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we concluded that vanishing evidence of blood-alcohol content justified a warrantless entry into the defendant’s home because the officer pursued the defendant on probable cause of driving under the influence, a misdemeanor offense.', 'probable_cause', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that both cases “present[ed] similar compelling exigent circumstances,” regardless of the underlying crimes.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in order to interpret § 28-1205 in a manner which is consistent with its objective, we hold that the language “to commit any felony, ” as it is used in that section, is synonymous with “for the purpose of committing any felony.', 'general', 'State v. Ring', 'https://www.courtlistener.com/opinion/1920411/', '1920411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse the district court’s judgment with respect to the use of a deadly weapon charge and vacate that conviction, but affirm the judgment of the district court with respect to the felony motor vehicle homicide conviction.', 'general', 'State v. Ring', 'https://www.courtlistener.com/opinion/1920411/', '1920411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the motor vehicle homicide conviction, but reverse and vacate the use of a deadly weapon conviction.', 'general', 'State v. Ring', 'https://www.courtlistener.com/opinion/1920411/', '1920411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, in order to carry its burden of proving that an offender is an SVP, the Commonwealth is not obliged to provide a clinical diagnosis by a licensed psychiatrist or psychologist;', 'general', 'Commonwealth v. Conklin', 'https://www.courtlistener.com/opinion/1922328/', '1922328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that it can.', 'general', 'Commonwealth v. Conklin', 'https://www.courtlistener.com/opinion/1922328/', '1922328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 372 (2005), this Court held that expert testimony proffered in a Megan’s Law II
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason we held that it was permissible for the Commonwealth to introduce, in its case-in-chief, medical expert testimony to explain that the absence of physical trauma is not inconsistent with allegations of sexual abuse because there was adequate time for any trauma to heal.', 'general', 'Commonwealth v. Dillon', 'https://www.courtlistener.com/opinion/1925033/', '1925033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the Superior Court.', 'general', 'Commonwealth v. Dillon', 'https://www.courtlistener.com/opinion/1925033/', '1925033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm.', 'general', 'Commonwealth v. Dillon', 'https://www.courtlistener.com/opinion/1925033/', '1925033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the Commonwealth was entitled to address this negative inference in its case-in-chief because the defense may choose not to introduce the results of the physical examination showing the lack of physical trauma, thereby depriving the Commonwealth of the opportunity to address the juror’s potential negative inferences.', 'general', 'Commonwealth v. Dillon', 'https://www.courtlistener.com/opinion/1925033/', '1925033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Commonwealth v. Fenton', 'https://www.courtlistener.com/opinion/1926797/', '1926797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that, although in other contexts, the word “fuck” had to carry a sexual context in order to be obscene, in the circumstances of the case before the court, where Pringle had called the police officers “goddamn fucking pigs”, he had used “obscene” language within the context of section 5503(a)(3), without need for resort to the sexual content of the words.', 'general', 'Commonwealth v. Fenton', 'https://www.courtlistener.com/opinion/1926797/', '1926797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Answering the first certified question, we hold that jeopardy did not attach when defendant voluntarily and in open court entered a guilty plea to a criminal information filed by the State charging him with reckless endangerment on November 23, 1984.', 'plea', 'State v. Forbes', 'https://www.courtlistener.com/opinion/1927325/', '1927325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court should have severed the charge on terroristic threats to kill from the trial of the contempt of the domestic violence restraining order.', 'general', 'State v. Chenique-Puey', 'https://www.courtlistener.com/opinion/1927812/', '1927812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Insofar as the judgment of contempt is concerned, we reverse the Appellate Division and reinstate the judgment of conviction.', 'general', 'State v. Chenique-Puey', 'https://www.courtlistener.com/opinion/1927812/', '1927812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm defendant’s contempt conviction and remand for a new trial on the count concerning terroristic threats.', 'general', 'State v. Chenique-Puey', 'https://www.courtlistener.com/opinion/1927812/', '1927812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Appellate Division vacating the conviction for terroristic threats to kill and remand to the Law Division.', 'general', 'State v. Chenique-Puey', 'https://www.courtlistener.com/opinion/1927812/', '1927812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that to read the statute as a coherent whole requires that stalking be a specific intent crime.', 'general', 'State v. Orsello', 'https://www.courtlistener.com/opinion/1928583/', '1928583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), where this court held that the legislature could criminalize an act without mention of a required intent level and thereby create a general intent crime.', 'general', 'State v. Orsello', 'https://www.courtlistener.com/opinion/1928583/', '1928583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that conviction under the statute requires proof of specific intent and therefore reverse.', 'general', 'State v. Orsello', 'https://www.courtlistener.com/opinion/1928583/', '1928583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because of the peculiar drafting of the statute, we conclude that our analysis must go further.', 'general', 'State v. Orsello', 'https://www.courtlistener.com/opinion/1928583/', '1928583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Wis.', 'general', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the rules of evidence do not formally apply in this context, we do not reach the question of the interplay between Wis.', 'general', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 728 (1996), we held that the state''s proof requirements for showing that a defendant is a repeat offender for the purposes of Wis.', 'general', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we held that prior OWI or OAR offenses may be proved by either "a defendant''s admission, whether given personally or imputed through *608counsel," or by the state "placing before the court reliable documentary proof of each conviction.', 'general', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This burden remains greater than what this court required in Wideman and Spaeth, where we held that a defense counsel''s admission of a defendant''s prior offense constitutes competent proof of the prior offense for purposes of OWI or OAR penalty enhancement.', 'general', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the rules of evidence do not apply to documents offered during a circuit court''s presentence determination of whether a qualifying prior conviction exists.', 'sentencing', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering many factors, we conclude that the proceeding in which the state seeks to prove habitual criminality is, under Wisconsin''s statutory scheme, more analogous to the sentencing process than to trial and, therefore, should be treated similarly in terms of evidentiary requirements.', 'sentencing', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state''s proof process under § 973.', 'general', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the rules of evidence do not apply to documentary evidence the state uses to prove the existence of prior convictions for repeater purposes under §§ 939.', 'general', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under the totality of the information in the record, the court did not err.', 'general', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1932220/', '1932220') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was insufficient as a matter of law to support Roy’s convictions of armed robbery and of PFCV.', 'general', 'Roy v. United States', 'https://www.courtlistener.com/opinion/1933813/', '1933813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have considered all of the facts of record cited by the government in support of this proposition, however, and we conclude that each such fact is just as consistent with the hypothesis that Roy continued to contemplate a gun sale as it is with the alternative hypothesis that he participated in the planning or execution of the robbery.', 'general', 'Roy v. United States', 'https://www.courtlistener.com/opinion/1933813/', '1933813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse Roy’s convictions for armed robbery and PFCV and remand the case to the trial court with directions to enter a judgment of acquit
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse Roy''s convictions for armed robbery and PFCV, we need not reach his allegations of instructional error relating to these offenses.', 'general', 'Roy v. United States', 'https://www.courtlistener.com/opinion/1933813/', '1933813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Roy’s CPWOL conviction and all of Ross’ convictions.', 'general', 'Roy v. United States', 'https://www.courtlistener.com/opinion/1933813/', '1933813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court cannot do so.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1936446/', '1936446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the use of the contempt power is inappropriate in such a circumstance, and that violation of a condition of probation may be sanctioned only through revocation of probation and imposition of all or part of the original sentence.', 'sentencing', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1936446/', '1936446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Legg and Pink, we held that although the defendants were in an area legally protected by the Fourth Amendment, the officer’s entrance did not violate the defendants’ Fourth Amendment rights.', 'search_seizure', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In weighing the competing interests of the State and the defendants as applied to the facts in each particular case, we concluded that the officers’ conduct was reasonable in both cases.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse and remand for a new trial.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s denial of Lewis’s motion to suppress.', 'suppression', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that neither the time of the criminal appropriation nor the value of the property criminally appropriated is substantive and, therefore, an element of the crime of theft prohibited by § 28-511.', 'general', 'State v. Schaaf', 'https://www.courtlistener.com/opinion/1937631/', '1937631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 163 (1976), we held that New Jersey common law provides a defendant with the right to remain silent when in police custody or under interrogation, ruling that defendant’s silence “at or near” the time of arrest may not be introduced to impeach his credibility.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/1938524/', '1938524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, although the conflict between the defendants made difficult the jury’s determination of the facts in the case, we conclude that the jury did not suffer irremediable confusion that impaired its deliberations or impugned its verdicts.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/1938524/', '1938524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the jury’s verdict under all the circumstances should not be supplanted.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/1938524/', '1938524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in cases involving termination for “immorality,” this nexus test strikes a proper balance under Section 1411 for school boards to apply.', 'general', 'Lehto v. Board of Education of the Caesar Rodney School District', 'https://www.courtlistener.com/opinion/1940654/', '1940654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that there was substantial evidence to support the Board’s decision that Lehto’s relationship with the Student constituted immorality justifying dismissal under 14
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in appeals to this Court pursuant to 10
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In an unpublished order, we reversed and remanded, instructing the Superior Court to determine whether probable cause existed, prior to administering the intoxim-eter test, to arrest Cooley on the homicide charge.', 'probable_cause', 'State v. Cooley', 'https://www.courtlistener.com/opinion/1954546/', '1954546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that it is permissible for the sentencing jury to consider aggravating circumstances “other than those listed in the Statute,” 395 A.', 'sentencing', 'Riley v. State', 'https://www.courtlistener.com/opinion/1958976/', '1958976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this “universe” of 28 cases, we conclude that we should limit our consideration to those cases in which the trier of fact found a statutory aggravating circumstance — that is, the 17 defendant-cases listed in Appendix J of Flamer
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 144, we conclude that the death sentence imposed upon Riley is not comparatively disproportionate to the sentences imposed in our universe of comparable eases.', 'sentencing', 'Riley v. State', 'https://www.courtlistener.com/opinion/1958976/', '1958976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find no reversible error as to the conviction and, therefore, we affirm.', 'general', 'Riley v. State', 'https://www.courtlistener.com/opinion/1958976/', '1958976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a probationer’s due process rights are adequately protected when a court states its essential findings on the record.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1959370/', '1959370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1959370/', '1959370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on the facts of this case, the officer’s expeditious stop of the vehicle was based upon sufficiently reliable information, notwithstanding the absence of any personal observation of incriminating behavior by the driver.', 'general', 'State v. Boyea', 'https://www.courtlistener.com/opinion/1959712/', '1959712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that the totality of the factual circumstances in this case satisfied the requirements of reliability
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 After reviewing several cases involving deadly weapons, we concluded that “[t]he principle .', 'general', 'State v. Boyea', 'https://www.courtlistener.com/opinion/1959712/', '1959712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Boyea', 'https://www.courtlistener.com/opinion/1959712/', '1959712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this case “involved more than a hunch.', 'general', 'State v. Boyea', 'https://www.courtlistener.com/opinion/1959712/', '1959712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the facts supporting defendant’s involvement “are specific and articulable” and supported a “reasonable suspicion” that defendant had killed the victim sufficient to warrant issuance of the NTO.', 'general', 'State v. Boyea', 'https://www.courtlistener.com/opinion/1959712/', '1959712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence in each trial was insufficient because it did not include proof of a crucial element of the offense, viz.', 'general', 'Ford v. United States', 'https://www.courtlistener.com/opinion/1967035/', '1967035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, however, we hold that Detective Papaj’s testimony was not probative of any material fact that had not already been established by other evidence.', 'general', 'Ford v. United States', 'https://www.courtlistener.com/opinion/1967035/', '1967035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985) (hereinafter “Ford I”), we held that the statute as amended was not unconstitutionally vague, but only because it “requires that conduct be for the purpose of prostitution and because it provides that objective criteria must be present in order to support a conviction.', 'general', 'Ford v. United States', 'https://www.courtlistener.com/opinion/1967035/', '1967035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court admitted the results of an HGN test without a proper scientific foundation in the first conviction, we hold that the court abused its discretion.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1969068/', '1969068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that only when an individual is convicted of a violation of 21
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that only when an individual is convicted of a violation of 21
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was an abuse of discretion for the Superior Court to admit the HGN evidence without the proper foundation.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1969068/', '1969068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the error in this ease was prejudicial.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1969068/', '1969068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on a careful reading of this section we find that the General Assembly intended to equate convictions with offenses.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1969068/', '1969068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the trial court and remand the matter for further proceedings consistent with this opinion.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1969068/', '1969068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the error was not harmless, we reverse the appellant’s conviction for the June 25, 1995 incident and remand the case for a new trial.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1969068/', '1969068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that where a defendant can establish a reasonable probability that the privileged records are likely to contain material information necessary to his defense, an in camera review of those records *650must be conducted to ascertain whether they contain evidence that is reasonably necessary, and therefore essential, to the defense.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that the trial court abused its discretion when it allowed the improper impeachment of a prosecution witness with hearsay testimony that was highly prejudicial.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the records required under the act are subject to the privilege established by the act.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '340 NW2d 631 (1983), we held that a trial judge abused his discretion when he allowed the defendant’s prior criminal record to be admitted into evidence:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that allowing the police officer to present defendant’s statement purportedly made to his nephew requires reversal of the defendant’s conviction and a new trial.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Stanaway’s conviction and remand for a new trial because the error was not harmless.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Stanaway, we affirm the trial court’s denial of an in camera review of the victim’s counseling records.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering all of the submissions, we conclude that, notwithstanding any contention to the contrary, Hall necessarily was on parole at the time he committed the new criminal charges to which he pleaded guilty.', 'plea', 'Hall v. Carr', 'https://www.courtlistener.com/opinion/1969688/', '1969688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 699, that disposition of the prejudice prong of an ineffectiveness claim may obviate resolution of whether counsel’s performance was deficient, we hold that defendant has failed to demonstrate any likelihood that an evidentiary hearing would produce proof that would show that there is a reasonable probability that, but for counsel’s unprofessional errors, the jury’s penalty-phase deliberations would have been affected substantially.', 'ineffective_assistance', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in concluding that this is not one of the rare cases in which a blanket inspection of the State’s file is appropriate.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In upholding the search warrant to open the envelope containing the tape, we held that the investigator’s failure to include in the supporting affidavit that Dougherty was defendant’s attorney was not improper because the record indicated that the officers believed that Dougherty, who was defendant’s brother-in-law, was not representing defendant in the murder case.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “[t]o whatever extent an attorney-client relationship between defendant and Dougherty may have existed at the time of the seizure, we are unpersuaded that the seizure of the envelope violated the attorney-client privilege.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sanchez, supra, we held that interrogation of an indicted defendant initiated by law-enforcement representatives without the consent of defense counsel violated the defendant’s right to counsel under Article I, Paragraph 10, of the New Jersey Constitution.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When we held that a defendant *250has a constitutional right to the consideration of such factors, Eddings [v.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no reasonable possibility that a different verdict would have arisen had the letters been disclosed.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any failure by counsel in that regard was immaterial to the outcome of the trial, in view of the immateriality of the nondisclosure of such information.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such information, if it existed, would have been immaterial to the outcome of the trial.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that both claims should be dismissed on the merits without an evidentiary hearing.', 'dismissal', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the evidence is fragile, in view of the stage of the proceedings at this point we conclude that it was sufficient to satisfy the burden of a prima facie case.', 'general', 'Commonwealth v. Wojdak', 'https://www.courtlistener.com/opinion/1971909/', '1971909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” For the reasons that follow, we reverse in part and affirm in part the Order of the Superior Court.', 'general', 'Commonwealth v. Wojdak', 'https://www.courtlistener.com/opinion/1971909/', '1971909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that these remaining eight charges arose from conduct which formed part of the same criminal episode as the conduct on which the initial three possession and delivery charges were based.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In applying this analysis to the instant case, we conclude that Bracal-ielly’s criminal actions fail to constitute a single criminal episode.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*475We conclude that the two drug transactions in Commonwealth v.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that neither Commonwealth v.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we concluded that the Section 110 barred the second attempt at prosecution and quashed the subsequent indictments.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we concluded that the drug charges brought against the defendant were not only temporally related but also logically related, and thus constituted a single criminal episode.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Starr involve drug transactions which constitute a “single criminal episode,” we find that Section 110 does not bar the instant prosecutions of either Bracalielly or Starr.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hude, we found that such substantial duplication had occurred.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we found that these offenses presented substantial duplication of issues of law and fact because the *473case did not involve “a situation where different evidence was required to be introduced to establish the alleged individual instances of possession and delivery”, but rather, involved a situation in which the Commonwealth’s case in both the first and second drug trials rested solely upon the credibility of a single witness.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'They were not part of the same criminal episode as those brought in Butler County and we affirm the order of the Superior Court in Commonwealth v.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that there was ample evidence to show that the defendants’ “purpose in setting out to stop [Rigg] was not peaceably to persuade him to stop work and join the union, but was to compel him by force and intimidation to accede to their demand,” this Court held that all the defendants could be found guilty of assault because Orlandi’s act was within the parameters of their “common design to perform an illegal act.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing the basic principle that a person should not be convicted of a crime for which he does not possess the requisite intent, this Court held in Doucette that a jury may not convict a person of felony murder unless it finds, beyond a reasonable doubt, that the person had an intent to kill, an intent to do great bodily harm, or a wanton disregard of the likelihood that death or great bodily harm would result.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s hesitation to provide information that would inculpate Gundlah was not sufficiently direct or emphatic to constitute an invocation of his right to remain silent, and thus the officers were not obligated to cease the interrogation.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has failed to show that the alléged conflict of interest compromised trial counsel’s loyalty to defendant, adversely affected his performance, or imperiled defendant’s-right to a fair trial.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was required, but *299failed, to show that the alleged conflict jeopardized his right to a fair trial.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we reverse the murder conviction based on the court’s instruction on intent, we address defendant’s ineffective-assistance-of-counsel claim because that claim necessarily challenges all of his convictions.', 'ineffective_assistance', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court improperly restricted the scope of the identity theft statute to preclude its application to the facts present in this case.', 'general', 'State v. Peters', 'https://www.courtlistener.com/opinion/1974346/', '1974346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the circuit court''s order dismissing the identity theft charge, and remand for reinstatement of the charge and further proceedings consistent with the opinion.', 'dismissal', 'State v. Peters', 'https://www.courtlistener.com/opinion/1974346/', '1974346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court improperly restricted the scope of the identity theft statute to preclude its application to the facts present in this case.', 'general', 'State v. Peters', 'https://www.courtlistener.com/opinion/1974346/', '1974346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that disbarment is the only appropriate discipline.', 'general', 'In Re Wilson', 'https://www.courtlistener.com/opinion/1974545/', '1974545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we conclude that disbarment is mandated.', 'general', 'In Re Wilson', 'https://www.courtlistener.com/opinion/1974545/', '1974545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ORDERED that WENDELL R.', 'general', 'In Re Wilson', 'https://www.courtlistener.com/opinion/1974545/', '1974545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the diminished public interest in applying the CCW statute in the context of Hamdan''s conduct, we hold that the State''s police power must yield in this case to Hamdan''s reasonable exercise of the constitutional right to keep and bear arms for security.', 'general', 'State v. Hamdan', 'https://www.courtlistener.com/opinion/1975122/', '1975122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that only if the public benefit in this exercise of the police power is substantially outweighed by an individual''s need to conceal a weapon in the exercise of the right to bear arms will an otherwise valid restriction on that right be unconstitutional as applied.', 'general', 'State v. Hamdan', 'https://www.courtlistener.com/opinion/1975122/', '1975122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant''s assertions that he was in a high crime neighborhood, that he was in a vulnerable position while changing his tire, and that he was faced with a potential threat (four young men were allegedly nearby, being loud and profane) were insufficient to constitute an imminent and specific threat under the self-defense privilege statute.', 'general', 'State v. Hamdan', 'https://www.courtlistener.com/opinion/1975122/', '1975122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that to sustain a claim of self-defense the defendant must show that:
(1) the defendant had an actual and reasonable belief that there was an actual or imminent unlawful interference with the defendant''s person;', 'general', 'State v. Hamdan', 'https://www.courtlistener.com/opinion/1975122/', '1975122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was unreasonable and unconstitutional to apply the CCW statute to punish Hamdan on the facts as we understand them.', 'general', 'State v. Hamdan', 'https://www.courtlistener.com/opinion/1975122/', '1975122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury concluded that Hamdan was aware of the weapon''s presence and that the weapon was hidden or concealed from ordinary view, we conclude that Hamdan violated the CCW statute.', 'general', 'State v. Hamdan', 'https://www.courtlistener.com/opinion/1975122/', '1975122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing considerations, we conclude that a citizen''s desire to exercise the right to keep and bear arms for purposes of security is at its apex when undertaken to secure one''s home or privately owned business.', 'general', 'State v. Hamdan', 'https://www.courtlistener.com/opinion/1975122/', '1975122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we determine that Hamdan prevails on both of these issues, we conclude that he had a constitutional right to keep and bear arms for the lawful purpose of security at the time he carried his concealed weapon, that his conviction for carrying a concealed weapon was unconstitutional, and his conviction must be reversed.', 'general', 'State v. Hamdan', 'https://www.courtlistener.com/opinion/1975122/', '1975122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the above analysis demonstrating the general rule favoring application of the presumption and, in addition, finding no valid reason to reject the presumption in this context, we hold that it is appropriate to apply a presumption of constitutionality in this case.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 891, this court held that although a "facial" constitutional challenge was a matter of subject matter jurisdiction and *556could not be waived, an "as applied" challenge was a non-jurisdictional defect that could be waived.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the CCW statute is a reasonable regulation on the time, place, and manner in which the right to bear arms may be exercised.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the CCW statute is a reasonable exercise of the state''s inherent police powers, we find that the CCW statute is not unconstitutional either on its face or as applied to Cole.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the state constitutional right to bear arms is fundamental.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that both claims fail.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that Cole has waived the opportunity to challenge the constitutionality of Wis.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in that case, we found that the unsubstantiated threat of four young men nearby, being loud and profane in a "high crime" area, was not "imminent and specific enough" for the defendant to invoke self-defense.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result of an inmate''s substantial dependency and the extraordinary control jailers wield over their prisoners, we hold that inmates are not precluded from recovering damages from a sheriff for injuries suffered by intentional wrongful acts of jail employees.', 'general', 'Robins v. Harris', 'https://www.courtlistener.com/opinion/1977716/', '1977716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that Sheriff Harris is liable for the assault committed by Soules against Robins and that the Commissioners are not liable for Robins''s alleged injuries.', 'general', 'Robins v. Harris', 'https://www.courtlistener.com/opinion/1977716/', '1977716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994) ("We conclude that Weatherholt''s claim actually concerns the manner in which the county jail was administered, a matter which we have determined falls solely within the province of the sheriff");', 'general', 'Robins v. Harris', 'https://www.courtlistener.com/opinion/1977716/', '1977716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the summary judgment in favor of Sheriff Harris and direct the entry of partial summary judgment in favor of Robins.', 'general', 'Robins v. Harris', 'https://www.courtlistener.com/opinion/1977716/', '1977716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 15] We conclude that the court’s instruction did not constitute obvious error.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/1978978/', '1978978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on the record evidence, the trial court correctly ruled that defendants are not directly liable for Forrest’s misconduct under 24 V.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on the Faragher analysis, we hold that if plaintiff can show that an on-duty law enforcement officer was aided in accomplishing an intentional tort involving a sexual assault on the plaintiff by the existence of the employment relationship with the law enforcement agency, vicarious liability will apply.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that summary judgment in favor of defendants on the claim of apparent authority was appropriate.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the holding in Gary did not survive the Supreme Court decisions in Faragher and Ellerth.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the superior court correctly held that defendants were entitled to summary judgment on the claim under 24 V.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that none of the reasons advanced by the trial court warrant summary judgment for defendants on the § 219(2)(d) claim.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude there are questions of material fact regarding this issue, we reverse the trial court’s grant of summary judgment on this issue.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Confronted with these uncertainties, we concluded that the decision “ ‘involves significant and far-reaching policy concerns’ more properly left to the Legislature, where hearings may be held, data collected, and competing interests heard before a wise decision is reached.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We decline to impose them, and we hold that they are not constitutionally required.', 'general', 'People v. Phillips', 'https://www.courtlistener.com/opinion/1981236/', '1981236') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the statute impermissibly required the defendant to take a procedural step to secure his confrontation rights.', 'general', 'People v. Phillips', 'https://www.courtlistener.com/opinion/1981236/', '1981236') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we held that a defendant must personally waive the right of confrontation “when the State’s entire case is to be presented by stipulation and the defendant does not present or preserve a defense ***, or where the stipulation includes a statement that the evidence is sufficient to convict the defendant.', 'general', 'People v. Phillips', 'https://www.courtlistener.com/opinion/1981236/', '1981236') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“Construing the fundamental constitutional right [of confrontation] in conjunction with the supreme court’s decision in Campbell, we conclude that in order to waive the defendant’s sixth amendment right of confrontation by stipulating to the admission of evidence, there must be some affirmative showing or indication by the defendant in the record that he or she did not object to or dissent from the attorney’s decision to stipulate.', 'general', 'People v. Phillips', 'https://www.courtlistener.com/opinion/1981236/', '1981236') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons hereinafter stated we affirm.', 'general', 'State v. Kane', 'https://www.courtlistener.com/opinion/1981708/', '1981708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that to conduct or participate in the affairs of an enterprise means to act purposefully and knowingly in the affairs of the enterprise in the sense of engaging in activities that seek to further, assist or help effectuate the goals of the enterprise.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/1985816/', '1985816') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the primary criterion, of New Jersey’s “pattern of racketeering activity” is “relatedness.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/1985816/', '1985816') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the term “pattern of racketeering activity” is not unconstitutionally vague.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/1985816/', '1985816') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these several reasons, we conclude that the New Jersey statute does not contain a requirement that in order “to conduct or participate in an enterprise;', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/1985816/', '1985816') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we hold that this circumstance is an exception to the general rule of deferral in Grant.', 'general', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 384 (2000), this Court held that § 9714(a)(1) violated the procedural due process guarantees of the Fourteenth Amendment of the United States Constitution because it placed the burden upon the defendant to rebut the presumption that he is a high risk dangerous offender.', 'general', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Hughes’ rights under the Pennsylvania Constitution were not violated.', 'general', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the record below, we conclude that the sentence imposed was not a product of passion, prejudice or any other arbitrary factor but, instead, was the product of overwhelming evidence.', 'sentencing', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm the judgment of sentence of death.', 'sentencing', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of sentence of death.', 'sentencing', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court stepped outside its authority by rejecting the applicable sentencing statute.', 'sentencing', 'State v. Saari', 'https://www.courtlistener.com/opinion/1989352/', '1989352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Leasa, we held that a “second” PCRA petition requesting reinstatement of appeal rights as to the order dismissing the petitioner’s first petition would be considered merely an extension of the litigation of the petitioner’s first PCRA petition where the appeal from the denial of the first petition was dismissed because of counsel’s failure to file a brief.', 'dismissal', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1991005/', '1991005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Peterson, we held that a “second” petition raising the same issues as the petitioner’s first petition would be treated as an extension of his first petition where his appeal from the denial of his first petition was dismissed because of counsel’s failure to file a brief.', 'dismissal', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1991005/', '1991005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Briggs we held that the trial court should have conducted the Frendak inquiry where “the trial court itself expressed concerns about productivity based on bizarre pretrial behavior, where competency examinations indicated classic, long-term mental illness, and where appellant has resisted every inquiry into a possible insanity defense.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001), we held that even though pre-trial competency reports indicated the defendant was competent to stand trial and not then suffering from a mental illness, once the issue of the defendant’s mental health was called into question during sentencing the trial court should have, at that time, conducted a Frendak inquiry.', 'sentencing', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989),19 where we held that “in light of an unchallenged expert’s report finding no productivity,” and “[a]fter considering all the evidence before the trial judge at the time of trial, we cannot conclude the record raised a substantial question of the defendant’s sanity at the time of the crime.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held in Logan v.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of Frendak, Briggs and Patton, we conclude that, in this case, there were a number of factors that similarly call into question appellant’s sanity at the time of the offense.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these elements to the evidence at trial, we conclude that the evidence was sufficient — if appellant was not insane — to permit the jury to find that appellant intentionally set fire to his mother’s apartment and its contents and that he did so with conscious disregard of the substantial risk to the property and to the building’s occupants, including his six-year old niece.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the conviction, concluding that the trial court abused its discretion in failing to pursue the issue of insanity “without making a Frendak inquiry and taking *156whatever [further] steps became necessary as a consequence.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Atkinson, however, we held that “trial courts should not consider the mere-fact method of impeachment.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the trial court has discretion in conducting this balancing test and determining whether a witness’ prior conviction is admissible.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the defendant’s conviction and remand for a new trial.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the appellate court and reinstated the defendant’s conviction.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons we have discussed, we reverse the judgments of the appellate and circuit courts and remand the cause to the circuit court for a new trial.', 'general', 'People v. Cox', 'https://www.courtlistener.com/opinion/1991155/', '1991155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances disclosed, we hold that defendants were not accorded the right of counsel in any substantial sense.', 'general', 'United States v. Cronic', 'https://www.courtlistener.com/opinion/111169/', '111169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '335 (1980), we held that the Constitution guarantees an accused “adequate legal assistance.', 'general', 'United States v. Cronic', 'https://www.courtlistener.com/opinion/111169/', '111169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that “such designation of counsel as was attempted was either so indefinite or so close upon the trial as to amount to a denial of effective and substantial aid in that regard.', 'general', 'United States v. Cronic', 'https://www.courtlistener.com/opinion/111169/', '111169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Shotwell, this Court held that the habitual offender act was applicable to a felony conviction for prison escape, even though the escape statute, at that time, provided for a maximum three-year sentence to be added to the original sentence.', 'sentencing', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”4 We conclude that the Legislature intended, as indicated by the plain meaning of the habitual offender act, that it be applicable to third and subsequent ouil convictions.', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our earlier analysis, and after considering again the purpose and wording of both the ouil provisions and the habitual offender act, we conclude that the "double enhancement” of which defendant complains was intended by the Legislature.', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statutes in question do not conflict;', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Legislature intended that the sentence for an ouil-3 felony, if it is a first felony conviction, shall be as provided in the Motor Vehicle Code: imprisonment for not less than one or more than five years, and a fine of not less than $500 or more than $5,000, or both.', 'sentencing', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part32 and reverse in part the decision of the Court of Appeals in People v Bewersdorf.', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Johnson, we affirm the decision of the Court of Appeals and remand the *75case to the circuit court for proceedings consistent with this opinion.', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant Bewersdorf was adequately advised by the trial court of his right to háve witnesses against him appear at trial, we affirm the panel’s ruling that defendant was not entitled to withdraw his plea.', 'plea', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court erred when it failed to suppress the evidence seized during the invalid nighttime search of Jackson’s home.', 'suppression', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 that requires suppression of the evidence seized during the search, we hold that the district court erred when it denied Jackson’s motion to suppress the evidence seized as a result of the illegal nighttime search of Jackson’s home.', 'suppression', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the welfare records in Smith were used simply to identify the defendant’s residence and not to disclose his welfare status, we held that the violation “did not subvert the basic purpose of the statute,” and therefore did not require suppression.', 'suppression', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that it is, our case law indicates that the evidence seized during the search should be suppressed;', 'suppression', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that in order to determine whether the search of Jackson’s home seriously violated an interest that subverts the statute, we must define the protected interest more precisely than we have in the past, and in doing so more clearly incorporate the motivation behind the historical aversion to such searches.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that our definition of a period of nighttime repose provides a good template to determine the basic purpose behind section 626.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Given both of the aforementioned deficiencies — the time of the search and the lack of information provided to the court — we conclude that these deficiencies represent fundamental departures from the mandate of section 626.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*173We conclude that Jackson’s case is distinguishable from Lien because before the police entered Jackson’s home they lacked the type of information that the police who entered Lien’s apartment possessed before entering.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that allowing the state to characterize an insufficiently supported nighttime intrusion into Jackson’s home as a mere technical rather than serious violation based on an after-the-fact assessment that she and her children had not yet entered a period of nighttime repose significantly undermines Jackson’s statutory right to be free from the “abrasiveness of official intrusions” during the night.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In essence, we conclude that what the police knew before entering Jackson’s home is critical because the purpose of the statute would be subverted if an unjustified nighttime entrance could be justified by what police learned after entrance into the home.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we concluded that a nighttime search should not have been authorized, we held that the evidence obtained in the search was admissible.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that execution of the warrant did not violate the defendant’s rights under the Fourth Amendment to the United States Constitution because the warrant was executed at a reasonable hour and the search did not entail the type of police conduct that section 626.', 'search_seizure', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”) Therefore, we conclude that Officer D’Andrea’s detention of the defendant constituted a “seizure” within the purview of the fourth amendment.', 'search_seizure', 'State v. Davis', 'https://www.courtlistener.com/opinion/1995892/', '1995892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In determining the reasonableness of the detention, we concluded that all factors must be balanced, including the basis of suspicion on the part of the police officer and the nature and extent of the restraint on the individual.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1995892/', '1995892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the attendant circumstances were sufficient to justify Officer D’Andrea stopping and questioning the defendant.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1995892/', '1995892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 29] Although we hold that the search of Bailey’s computer violated the Fourth Amendment and, on that basis, vacate Bailey’s conviction, we remand the case to the Superior Court for further proceedings.', 'search_seizure', 'State v. Bailey', 'https://www.courtlistener.com/opinion/1996085/', '1996085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that consent that resulted from submitting to an officer''s false claim of lawful authority to search regardless of a warrant is constitutionally impermissible.', 'general', 'State v. Bailey', 'https://www.courtlistener.com/opinion/1996085/', '1996085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the concealment or misrepresentation of their identity does not violate the Fourth Amendment "so long as the entry is for the very purposes contemplated by the occupant.', 'search_seizure', 'State v. Bailey', 'https://www.courtlistener.com/opinion/1996085/', '1996085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 2] Because we conclude that the search of Bailey’s computer violated the Fourth Amendment, we vacate the judgment of conviction and remand for further proceedings to determine whether the evidence obtained as a result of that search must be suppressed as fruits of the illegal search.', 'suppression', 'State v. Bailey', 'https://www.courtlistener.com/opinion/1996085/', '1996085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that when considering the appropriateness of the sentence for the crime committed, courts should initially focus upon the presumptive penalties.', 'sentencing', 'Ware v. State', 'https://www.courtlistener.com/opinion/1997374/', '1997374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court did not abuse its discretion by failing to find this as a mitigating circumstance.', 'general', 'Ware v. State', 'https://www.courtlistener.com/opinion/1997374/', '1997374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''Based on the foregoing, we conclude that the State presented sufficient evidence to sustain Ware''s convictions.', 'general', 'Ware v. State', 'https://www.courtlistener.com/opinion/1997374/', '1997374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the evidence supports the jury''s verdict that Ware committed sexual misconduct with a minor as a Class B felony and as a Class C felony on or about the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'by regaling him with vacations and other luxuries, we find that the evidence of extra-jurisdie-tional sexual acts appears to be relevant only to show Ware''s propensity to commit
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the prejudicial effect of this evidence outweighed its probative value, and the trial court erred in admitting this evidence of extra-jurisdictional sexual acts.', 'general', 'Ware v. State', 'https://www.courtlistener.com/opinion/1997374/', '1997374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'lasting from approximately October of 2000 to at least April 15, 2001, we find that Ware has failed to demonstrate a substantial likelihood that the improperly-admitted evidence contributed to his verdict.', 'general', 'Ware v. State', 'https://www.courtlistener.com/opinion/1997374/', '1997374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not abuse its discretion in finding as aggravating factors that Ware violated a position of trust with SH.', 'general', 'Ware v. State', 'https://www.courtlistener.com/opinion/1997374/', '1997374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After due consideration of the trial court''s decision, we find that Ware''s sentence was appropriate in light of the nature of the offense and the character of the offender.', 'sentencing', 'Ware v. State', 'https://www.courtlistener.com/opinion/1997374/', '1997374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court erred in imposing this restitution order.', 'general', 'Ware v. State', 'https://www.courtlistener.com/opinion/1997374/', '1997374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), we held that "[a]ll custodial interrogation including any information about rights, any waiver of those rights, and all questioning shall be electronically recorded where feasible and must be recorded when questioning occurs in a place of detention” (syllabus).', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1998411/', '1998411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse defendant’s conviction and remand for a new trial.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1998411/', '1998411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant may be convicted of obstruction under N.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in relying on the dispatch from headquarters the officers were “lawfully performing an official function” when they commanded defendant to stop.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not resolve whether the investigatory stop in this case met that constitutional standard because, ultimately, we conclude that under N.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that sufficient credible evidence in the record supports the findings that Officers Williams and Milton reasonably relied on a dispatch from headquarters and therefore were “lawfully performing an official function”—an attempted investigatory stop—when defendant obstructed their efforts by fleeing.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We affirm, but for different reasons.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we affirm the judgment of the Appellate Division upholding defendant’s conviction of obstruction in violation of N.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. McBurney', 'https://www.courtlistener.com/opinion/1524333/', '1524333') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statute does violate the federal and state constitutions as it applies to distributors of such materials, and decline to save the statute insofar as it applies to those accused of the proscribed activities of § 948.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Wis.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 We hold that it may not.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the statute is unconstitutional as it applies to those activities which do not include some interaction between the accused and the child-victim.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an essential element of the crime specified in Wis.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the statute on its face does not allocate to the State the burden to prove that the defendant had knowledge of the minority of the child-victim.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this affirmative defense which could never be proved by most of the actors in § 948.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that the affirmative defense as provided in Wis.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we found that we had the power to do so, relying upon precedent supporting the supplementation of deficiencies to save a statute, id.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Princess Cinema, we found that the same state statute considered and saved in Chobot was now unconstitutionally over-broad, albeit based upon a question not reached in the earlier case.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', criminalizes acts where an individual personally confronts, or has the opportunity to personally confront, a specific child, thereby allowing the individual to easily ascertain *155the child''s age, we conclude that the statute does not create an unreasonable burden on the individual''s First Amendment rights.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, based again upon the plain language of the statute, we hold that a “pattern of criminal conduct” may be demonstrated by reference to past felony or gross misdemeanor convictions or by proof, through clear and convincing evidence, of prior, uncharged acts of criminal conduct, where such acts are similar to the present offense in motive, purpose, results, participants, victims or other characteristics.', 'general', 'State v. Gorman', 'https://www.courtlistener.com/opinion/2067217/', '2067217') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), this court held that a pattern was “a regular, mainly unvarying way of acting or doing.', 'general', 'State v. Gorman', 'https://www.courtlistener.com/opinion/2067217/', '2067217') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant was properly sentenced as a career offender.', 'sentencing', 'State v. Gorman', 'https://www.courtlistener.com/opinion/2067217/', '2067217') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this newly established rule to the facts of this case, we conclude that a pattern of criminal conduct is clearly established.', 'general', 'State v. Gorman', 'https://www.courtlistener.com/opinion/2067217/', '2067217') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that appellant was properly sentenced under the career offender statute, we do not consider whether aggravating circumstances were present to otherwise justify the departure.', 'sentencing', 'State v. Gorman', 'https://www.courtlistener.com/opinion/2067217/', '2067217') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The trial court did, in fact, treat the two June 10 crimes as giving rise to a single conviction for the purposes of this proceeding, and we affirm.', 'general', 'State v. Angelucci', 'https://www.courtlistener.com/opinion/1526312/', '1526312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Holland', 'https://www.courtlistener.com/opinion/2067933/', '2067933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'speedy trial was not violated, we affirm the conviction.', 'general', 'State v. Christen', 'https://www.courtlistener.com/opinion/2068176/', '2068176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that absent a statutory expression to the contrary, the judiciary, including the Family Court, possessed the inherent power to impose consecutive sentences for separate offenses.', 'sentencing', 'State v. Franklin', 'https://www.courtlistener.com/opinion/2070036/', '2070036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Appellate Division and remand to the trial court for the calculation and award of gap-time credit toward the sentences imposed on Franklin’s robbery offenses consistent with this opinion.', 'sentencing', 'State v. Franklin', 'https://www.courtlistener.com/opinion/2070036/', '2070036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When a law enforcement officer kills the accomplice of a person committing a kidnapping, does the kidnapper commit felony murder under the Indiana murder statute? We hold that, under these circumstances, the kidnapper commits felony murder.', 'general', 'Palmer v. State', 'https://www.courtlistener.com/opinion/2071258/', '2071258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold the felony murder provision in our murder statute applies, and we affirm the defendant’s convictions.', 'general', 'Palmer v. State', 'https://www.courtlistener.com/opinion/2071258/', '2071258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'Palmer v. State', 'https://www.courtlistener.com/opinion/2071258/', '2071258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the evidence, however, we find that the videos simply establish that Shane and Hicks were close.', 'general', 'Shane v. State', 'https://www.courtlistener.com/opinion/2074316/', '2074316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction for conspiracy-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court.', 'general', 'Shane v. State', 'https://www.courtlistener.com/opinion/2074316/', '2074316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in Spotz III, we held that the Cumberland County murder was not part of the same criminal episode as the Clearfield, Schuylkill, and York County crimes.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we held that the remark did not put the future dangerousness of the appellant at issue.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On December 23, 1998, this Court held in Commonwealth v.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Rolan, “the crime of burglary has always been and continues to be viewed as a crime *85involving the use or threat of violence to the person.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 763, 779 (1998), this Court held that “the introduction of evidence concerning [the appellant’s escape from prison and parole violations during the guilt phase of the trial .', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 439, 454 (1995) (“If we conclude that the particular course chosen by counsel had some reasonable basis, our inquiry ceases and counsel’s assistance is deemed effective.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'thus, we conclude that trial counsel was not ineffective for failing to object.', 'ineffective_assistance', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 454 (“If we conclude that, the particular course chosen by counsel had some reasonable basis, our inquiry ceases and counsel’s assistance is deemed effective.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence of death imposed upon [Spotz] is not excessive or disproportionate to the penalty imposed in similar cases.', 'sentencing', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the record, we conclude that the sentence of death was not the product of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the circumstances of this case, however, we hold that these errors are harmless and do not warrant a new trial.', 'general', 'State v. Wright', 'https://www.courtlistener.com/opinion/2075892/', '2075892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the errors in the jury instructions pertaining to lesser included offenses were harmless.', 'jury_instruction', 'State v. Wright', 'https://www.courtlistener.com/opinion/2075892/', '2075892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without deciding whether this proposition correctly states the law in Vermont, we find that the facts in evidence in this case do
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that no privilege in confidential communications was violated.', 'general', 'State v. Wright', 'https://www.courtlistener.com/opinion/2075892/', '2075892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Wright', 'https://www.courtlistener.com/opinion/2075892/', '2075892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Donatelli', 'https://www.courtlistener.com/opinion/2077202/', '2077202') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Appellant’s signature of a fictitious name on three fingerprint cards was sufficient to support his convictions for forgery.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we have determined that the property taken need not be physically attached to the victim in order to constitute theft from the person and that Appellant’s counsel had a reasonable basis to agree to the stipulation regarding the grading of the offense, we hold that the trial court properly sentenced Appellant’s theft convictions as first-degree misdemeanors based upon that stipulation.', 'sentencing', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in that case, we held that the sentencing court improperly had graded the defendant’s offense a first-degree misdemeanor as a theft from the person.', 'sentencing', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we conclude that theft from the person under Section 3903(b) includes not only theft from the victim’s body, but also theft in the victim’s presence and from his immediate possession and control.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that in order to be graded as a theft from the person under Section 3903, property need not be taken from the victim’s body as long as it is taken in his presence and from his immediate possession and control.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the present case concerns the propriety of the grading of the offense which thereby establishes the maximum penalty, and not an enhancement to the sentence beyond the statutory maximum penalty for the theft offenses, we conclude that Apprendi does not apply.', 'sentencing', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, we concluded that “common sense dictates that a person need not be in actual physical possession of property to have it taken from his person.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 39 Having found no merit to any of Appellant’s contentions on appeal, we affirm his judgment of sentence.', 'sentencing', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court erred in failing to conduct the necessary preliminary examination as to the factual basis of defendant’s allegations against his appointed trial counsel.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/2078269/', '2078269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that the evi-denee presented by the State was insufficient to support Grim''s conviction as we conclude that the State did not prove that Grim''s possession was "reckless.', 'general', 'Grim v. State', 'https://www.courtlistener.com/opinion/2078393/', '2078393') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Grim v. State', 'https://www.courtlistener.com/opinion/2078393/', '2078393') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying a reasonable doubt standard, we held that there was sufficient evidence to convict, without regard to whether escape formed a part of the substantive offense.', 'general', 'People v. Dennis', 'https://www.courtlistener.com/opinion/2085397/', '2085397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the plain language in our accountability statute, we conclude that, for purposes of accountability, the duration of the commission of an offense is defined by the elements of the offense.', 'general', 'People v. Dennis', 'https://www.courtlistener.com/opinion/2085397/', '2085397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons stated above, we affirm the judgment of the appellate court, which reversed defendant’s conviction and remanded the cause to the circuit court for retrial.', 'general', 'People v. Dennis', 'https://www.courtlistener.com/opinion/2085397/', '2085397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Trinkle''s conviction after determining whether there was a substantial relationship between the prior representation and the criminal proceeding, and whether the prosecuting attorney gained any confidential information through their prior association.', 'general', 'Daugherty v. State', 'https://www.courtlistener.com/opinion/2087023/', '2087023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record before us, we conclude that Lemmer only challenged the constitutionality of Minn.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because collateral estoppel bars only the relitigation of certain issues, we conclude that collateral estoppel is not substantive in function.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the issue decided in the implied consent proceeding is identical to the one to be decided in the DWI prosecution.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the reasoning of House remains sound and, therefore, conclude that the state and the commissioner are not the same party.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in this case the differing functions and responsibilities of the Commissioner of Public Safety and the State of Minnesota are sufficiently distinct to support the conclusion that the parties are not in privity.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that privity does not exist between the Commissioner of Public Safety and the state in these circumstances.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the state did not have a full and fair opportunity to be heard on the litigated issue.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that collateral es-toppel is inapplicable to issues litigated in DWI prosecutions that were previously litigated in implied consent proceedings because the Commissioner of Public Safety and the state are not in privity, and in this instance the state did not have a full and fair opportunity to be heard.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, because we conclude that the elements of collateral estoppel have not been satisfied and that public policy weighs against the application of collateral estoppel, we believe that Minn.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'House, we concluded that a prosecuting attorney, who represented the state in the criminal DWI prosecution, did not have the authority to execute a plea bargain dismissing the subsequent implied consent proceeding, which was brought by the Commissioner of Public Safety.', 'dismissal', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1082 (“Under the circumstances presented here, we hold that the Department of Public Safety and the state were in privity.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state of Ohio is the real party in interest in both proceedings and the requirement of privity as an element of issue preclusion is satisfied.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 972, we held that "the state through its drafting can foreclose as to the defendant, the tactical opportunity to seek a conviction for a lesser offense.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2087780/', '2087780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Appellate Rule 11(B)@8), we affirm Wright''s conviction for Reckless Homicide.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2087780/', '2087780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the purpose of the contempt proceeding .', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that remedial contempt was properly employed, we also do not address whether Heidi was entitled to relief under § 806.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and hold that the circuit court properly employed remedial contempt in this case.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm the circuit court''s use of contempt, we also affirm the suspension of Heidi''s child support obligations.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we affirm the circuit court''s contempt finding against Ronald, we also reinstate the $32,000 overtrial award.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that in these circumstances the State may not use as evidence the fruits of a search incident to an illegal arrest.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Superior Court erred as a matter of Delaware statutory and Delaware constitutional law in denying Jones’ motion to suppress evidence seized on the night of January 11, 1997.', 'suppression', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a seizure took place within the meaning of .', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the *868trial court’s determination was clearly erroneous.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the defendant was illegally seized, in violation of article first, §§ 7 and 9 of the Connecticut constitution.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '64 We conclude that Jones’ actions in walking away from Patrolman Echevar-ria and his refusal to obey or submit to the officer’s commands to stop and remove his hands from his pockets did not furnish grounds for reasonable and articulable suspicion to effect the seizure.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 1902 and Article I, § 6 of the Delaware Constitution, we find that Patrolman Echevarria did not possess a reasonable and articulable suspicion to stop Jones.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this criminal appeal, we reverse the judgment and sentence of the Superior Court because evidence was invalidly seized from the defendant.', 'sentencing', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*402We conclude that the conflict-of-interest laws not only impose duties on public employees but they also constitute constraints on persons dealing with public employees.', 'general', 'MacDougall v. Weichert', 'https://www.courtlistener.com/opinion/2089418/', '2089418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶22] Because we find that Lagasse’s stop and arrest were lawful, we need not reach the other contentions advanced by Lagasse on this appeal.', 'general', 'State v. Lagasse', 'https://www.courtlistener.com/opinion/5149763/', '5149763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under a different set of circumstances, we found that a jury could have construed seemingly inconsistent answers made by an accomplice during his testimony in a manner that would be consistent with his prior description of events.', 'general', 'State v. Lagasse', 'https://www.courtlistener.com/opinion/5149763/', '5149763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/5149788/', '5149788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and sentence of the district court.', 'sentencing', 'State v. Rohm', 'https://www.courtlistener.com/opinion/2090262/', '2090262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the district court’s judgment and sentence
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Artzer', 'https://www.courtlistener.com/opinion/2091179/', '2091179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the $150,000 restitution award payable to Kolacia’s estate.', 'general', 'State v. Artzer', 'https://www.courtlistener.com/opinion/2091179/', '2091179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Artzer’s conviction for murder in the second degree and the accompanying sentence which includes an indefinite term of imprisonment not to exceed fifty years and the $150,000 restitution award payable to Kolacia’s estate.', 'sentencing', 'State v. Artzer', 'https://www.courtlistener.com/opinion/2091179/', '2091179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature did not intend to require an officer to have probable cause to arrest before requesting a PBT.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that our case law establishes that "probable cause to believe" has different meanings at different stages of criminal proceedings.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the context, history and purpose of the statute all suggest that "probable cause to believe" refers to a quantum of proof greater than the reasonable suspicion necessary to justify an investigative stop, and greater than the "reason to believe" that is necessary to request a PBT from a commercial driver, but less than the level of proof required to establish probable cause for arrest.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the officer had the required degree of probable cause to request the defendant to submit to a PBT.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the legislature intended "probable cause to believe" in the first sentence of Wis.', 'sentencing', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the officer had sufficient probable cause to request the PBT even without the HGN test results, we do not need to reach the issue of whether those test results were properly excluded.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that case law does not compel the conclusion that the legislature must have intended "probable cause to believe" to mean probable cause for an arrest.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and remand the cause to the circuit court for reinstatement of the judgment of conviction.', 'general', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the judgment adjudicating respondent a delinquent minor for committing the offense of sexual exploitation of a child, we need not address respondent’s challenge to the circuit court’s order requiring him to register as a sex offender or his challenge to the constitutionality of the Registration Act.', 'general', 'People v. Ryan B.', 'https://www.courtlistener.com/opinion/2093989/', '2093989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the facts known to Officer Bieeker at the time he initiated the investigatory stop did not provide a reasonable, articulable suspicion that defendant had or was about to commit a crime, we hold that the Terry stop violated defendant’s constitutional rights.', 'general', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1319] (1983), where we held that when an officer, without reasonable suspicion or probable cause, approaches an individual, the individual has a right to ignore the police and go about his business.', 'probable_cause', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the arresting police officer did not have a reasonable, articulable suspicion that defendant was about to commit a crime sufficient to justify an investigative stop pursuant to Terry v.', 'general', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION Having determined that the Terry stop of defendant was illegal, we conclude that the trial court should have granted defendant’s motion and excluded all evidence obtained as a result of that illegality, including the cocaine discovered in the apple pie box.', 'general', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because on remand the State would be unable to prove that defendant committed the offense of unlawful possession of a controlled substance without the suppressed cocaine, we reverse defendant’s conviction and sentence.', 'suppression', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the State would be unable to prove beyond a reasonable doubt that defendant unlawfully possessed a controlled substance without the suppressed cocaine, we reverse outright defendant’s conviction and sentence.', 'suppression', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Locken, we held that the resistance of even an unlawful arrest violates section 31 — 1.', 'general', 'City of Champaign v. Torres', 'https://www.courtlistener.com/opinion/2097165/', '2097165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being so, we held that the defendants could not lawfully employ physical force to prevent the police from entering their residence to effectuate the arrest.', 'general', 'City of Champaign v. Torres', 'https://www.courtlistener.com/opinion/2097165/', '2097165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because sections 7 — 7 and 31 — 1 deal specifically with the use of force against peace officers, while section 7 — 2 applies generally to the use of force against anyone, we concluded that the specific provisions of sections 7 — 7 and 31 — 1 controlled.', 'general', 'City of Champaign v. Torres', 'https://www.courtlistener.com/opinion/2097165/', '2097165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has shown beyond a reasonable doubt that § 943.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that § 943.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, as charged and as applied to the facts of this case, Wis.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
