INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case at hand, we conclude that Wis.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under facts of this case, Wis.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has shown beyond a reasonable doubt that Wis.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals'' decision.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statute did not regulate speech and observed that "internet conversations and e-mails .', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held in Weiss v.', 'general', 'Wright v. City of Little Rock', 'https://www.courtlistener.com/opinion/2100846/', '2100846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the charge of fleeing and evading should have been dismissed, we reverse Appellant’s conviction and remand the matter to the trial court.', 'dismissal', 'Foley v. Commonwealth', 'https://www.courtlistener.com/opinion/2101366/', '2101366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that fleeing or evading, under circumstances as occurred in this case, is a single continuous act, regardless of how many police officers may be considered to have given an order to stop.', 'general', 'Foley v. Commonwealth', 'https://www.courtlistener.com/opinion/2101366/', '2101366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Appellant’s conviction for fleeing and evading must be vacated, we necessarily do not reach his argument regarding an alleged error in the jury instructions.', 'jury_instruction', 'Foley v. Commonwealth', 'https://www.courtlistener.com/opinion/2101366/', '2101366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these assumptions to the skeletal definition of “abuse” set out above, we conclude that § 9 derives its function from a constitutional arrangement calculated to correlate the enjoyment of individual rights and the exercise of state power such that the latter facilitates the former.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/2101520/', '2101520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, while we have little regard for either Price’s contumacious manner or her epithet, we conclude that her overall complaint constituted political speech.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/2101520/', '2101520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that Ind.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/2101520/', '2101520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that political expression becomes “unreasonably noisy” for purposes of Ind.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/2101520/', '2101520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that our prior decisions are not subject to distinction and, after examining the Legislature’s actions following those decisions, we adhere to our precedent and affirm the Court of Appeals’s judgment.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Adhering to our prior decisions, we hold that Section 1.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b) of the Penal Code specified that only Titles 1, 2, and 3 of the Penal Code were applicable to offenses defined outside the Penal Code, we held that the attempt statute did not apply to the Controlled Substances Act.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Less than five months later, in Baker, we held that the Penal Code’s criminal conspiracy statute did not apply to the Controlled Substances Act.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b), we held that Section 1.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b) in Moore, in Baker we held that the criminal conspiracy statute, also contained in Title 4, does not apply to offenses in the Controlled Substances Act.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this we conclude that our prior construction of Section 1.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b) references only Titles 1, 2, and 3 of the Penal Code, we concluded that the criminal attempt and conspiracy statutes in Title 4 of the Penal Code did not apply to offenses defined in the Controlled Substances Act.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ']”10 As a result, we reversed the trial court’s judgment revoking the appellant’s probation for the offense of conspiracy to sell marijuana, remanded the case, and ordered the prosecution dismissed.', 'dismissal', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b) of the Penal Code in those cases was correct, we affirm the judgment of the Third Court of Appeals upholding the trial judge’s decision to quash the Election Code-based conspiracy charges against Colyandro, Ellis, and Delay.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that although the lesser offense of theft was included in the greater offense of robbery, as charged, the evidence left no doubt but that the defendant was guilty of robbery or of no crime whatsoever.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2103043/', '2103043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we conclude that the State was not required, under section 111 — 3(c) of the Code of Criminal Procedure, to give the defendants pretrial notice that they would be sentenced as Class X offenders under section 5 — 5—3(c)(8) of the Unified Code of Corrections (Ill.', 'sentencing', 'People v. Jameson', 'https://www.courtlistener.com/opinion/2103792/', '2103792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Zaccaro, this Court held that a search warrant was not required under Article 11 for the introduction of evidence obtained through undercover activity, where the State proved that the officer was invited into the defendant’s home in order to purchase cocaine.', 'general', 'State v. Blow', 'https://www.courtlistener.com/opinion/2104535/', '2104535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that warrantless electronic participant monitoring conducted in a home offends the core values of Article 11.', 'general', 'State v. Blow', 'https://www.courtlistener.com/opinion/2104535/', '2104535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '404(a)(1), we conclude that the court erred.', 'general', 'State v. Blow', 'https://www.courtlistener.com/opinion/2104535/', '2104535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand on all counts.', 'general', 'State v. Blow', 'https://www.courtlistener.com/opinion/2104535/', '2104535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court employed the wrong legal standard *476when determining that there was not a reasonable probability of a different outcome.', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the corroboration requirement in a recanta*478tion case is met if: (1) there is a feasible motive for the initial false statement;', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that McCallum has established a feasible motive for H.', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse that part of the court of appeals'' decision granting a new trial.', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm that part of the court of appeals'' decision reversing the circuit court.', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the district court erred in admitting Colemer’s testimony regarding the statements made by Pool and the disputed portions of Agent Soppeland’s interview with appellant.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/2109108/', '2109108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we held that evidence of a victim’s fear of a perpetrator is admissible only when all three of the following conditions are met:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In ruling this evidence insufficient, we held that, “to support [the defendant’s] convictions for aiding and abetting second and third degree assault, the state needed to establish a sufficient link between [the defendant] and his brother’s actions, and on this point the state has failed.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/2109108/', '2109108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the evidence before us, we conclude that it is equally plausible that, as noted by appellant, the acquaintances “determined on [their] own to avenge the wrongs” believed to have been done to Caldwell and appellant, or were acting on instruction from Caldwell.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/2109108/', '2109108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the admission of portions of Agent Soppeland’s interview with appellant at issue here was plain error.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/2109108/', '2109108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence was insufficient to support appellant’s convictions for first-degree premeditated murder, first-degree felony murder, second-degree intentional murder, kidnapping, and assault.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/2109108/', '2109108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On March 29, 2000, a jury found McCollum guilty of murder in the first degree while committing kidnapping of Pool, and we affirmed that conviction.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/2109108/', '2109108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although John*483son attempted to withdraw his plea agreement, the postconviction court denied that request and we affirmed the denial.', 'plea', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/2109108/', '2109108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When we apply this rule to the language at issue, we conclude that the words “a conviction” plainly indicate one conviction.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/2110229/', '2110229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the words “a conviction” indicate that the defendant’s third offense of domestic battery must occur within ten years of only one of the defendant’s prior domestic violence convictions in order to enhance the third offense to a felony.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/2110229/', '2110229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 Because *372the trial judge weighed the evidence presented by both the prosecutor and defendant, we conclude that his findings and order are more consistent with the ordering of a new trial than with the direction of a verdict of acquittal.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the facts as they have evolved, we find that the trial judge did not direct a verdict of acquittal.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"It is ordered that the jury verdicts as to Defendant Hampton [handwritten by Judge Crockett] be set aside, defendant’s renewed motion for--a- directed vordiet — is *370granted, and a new trial is ordered.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our own painstaking examination of the record in this case, conducted in conformance with the constitutionally binding standard announced in Jackson v Virginia, supra, we conclude that the trial court did not err in finding that the evidence *387produced by the prosecutor was legally insufficient to support a finding of guilt beyond a reasonable doubt.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we find that the trial judge, after applying a standard consistent with the one we announce today, directed a verdict of acquittal.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the order authorizing the installation and monitoring of a GPS tracking device on Sveum''s vehicle was a valid search warrant under the Fourth Amendment.', 'search_seizure', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Affording Judge Callaway''s probable cause determination great deference, we conclude that he had a substantial basis for concluding that given all the facts and circumstances set forth in Ricksecker''s ample and detailed affidavit, there was a fair probability that installing and monitoring a GPS tracking device on Sveum''s vehicle would produce evidence of stalking.', 'probable_cause', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Ricksecker''s affidavit meets the particularity requirements with respect to electronic tracking devices as explained in Karo, 468 U.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that such information "suffice[s] to permit issuance of a warrant authorizing [GPS] installation and surveillance" on Sveum''s vehicle.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in light of the facts and circumstances in this case, the order constitutes a valid search warrant.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because we conclude that the failure to comply with the requirements of Wis.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Noll, we concluded that a search warrant authorizing the seizure of "various long play phono*394graph albums, and miscellaneous vases and glassware items" lacked the required particularity;', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that application of the sever-ability doctrine was proper, and therefore, we excised the defective warrant provisions from the valid warrant provisions.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the order here met each of these requirements.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 722, 726 (Iowa 1985) ("Because there is no common-law right to issue a search warrant, we conclude that we lack the authority to expand by judicial fiat the purposes fixed by the legislature for which search warrants may lawfully issue.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand in part and revise in part.', 'general', 'Payton v. State', 'https://www.courtlistener.com/opinion/2124084/', '2124084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*499For the foregoing reasons, we reverse Payton''s convictions for sexual battery and remand to the trial court with instructions to vacate Payton''s conviction of the lesser-included offenses of sexual battery and enter judgments of conviction and sentence only upon the greater offenses of child molesting and sexual misconduct with a minor.', 'sentencing', 'Payton v. State', 'https://www.courtlistener.com/opinion/2124084/', '2124084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held the defendant’s failure to comply with section 122—2 justified the summary dismissal of his petition.', 'dismissal', 'People v. Hall', 'https://www.courtlistener.com/opinion/2132633/', '2132633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on all of the circumstances, this court held the defendant’s guilty plea was not knowing and voluntary.', 'plea', 'People v. Hall', 'https://www.courtlistener.com/opinion/2132633/', '2132633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgments of the appellate and circuit courts, and remand this matter to the circuit court for an evidentiary hearing on defendant’s postconviction claims.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2132633/', '2132633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the foregoing reasons, we reverse the judgment of the appellate court and the circuit court’s dismissal of defendant’s postconviction petition and remand this matter to the circuit court for an evidentiary hearing on his postconviction claims.', 'dismissal', 'People v. Hall', 'https://www.courtlistener.com/opinion/2132633/', '2132633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of Ceja and Hopkins, we hold that a trial court need not allow a defendant’s request to have the jury instructed on offenses that are less serious, but not included, offenses to those offenses for which he or she was charged regardless of whether the evidence at trial could support the less serious offense.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2133639/', '2133639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that aggravated battery improperly served as the predicate for felony murder.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2133639/', '2133639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the act of throwing the infant formed the basis of the aggravated battery conviction and that it was also the same act underlying the killing.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2133639/', '2133639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm the appellate court.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2133639/', '2133639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was “involved in” the accident because the evidence demonstrated that he was implicated in or connected with the accident in a logical or substantial manner .', 'general', 'People v. Aldrich', 'https://www.courtlistener.com/opinion/2133998/', '2133998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no error requiring reversal, we conclude that defendants’ convictions and sentences must be affirmed.', 'sentencing', 'People v. Aldrich', 'https://www.courtlistener.com/opinion/2133998/', '2133998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Aldrich', 'https://www.courtlistener.com/opinion/2133998/', '2133998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the plain language of the statute did not support this interpretation and held that the limitation did apply to offenses committed at different times.', 'general', 'People v. Pullen', 'https://www.courtlistener.com/opinion/2137470/', '2137470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that as the legislature had seen fit to limit the total number of consecutive sentences that could be imposed on a defendant, we would not “rewrite the statute under the guise of statutory interpretation.', 'sentencing', 'People v. Pullen', 'https://www.courtlistener.com/opinion/2137470/', '2137470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons above stated, we affirm the judgment of the appellate court.', 'general', 'People v. Pullen', 'https://www.courtlistener.com/opinion/2137470/', '2137470') ON CONFLICT DO NOTHING;
