INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant in a civil suspension proceeding may challenge the reasonableness of the underlying stop pursuant to 23 V.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the stops in the two cases before us, we conclude that defendant Steven Lussier was lawfully stopped for operating a motor vehicle with only one functioning taillight, but that defendant Robert Lussier was unlawfully stopped for operating a vehicle with only one functioning rear license plate light.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that, in permitting defendants in a civil suspension proceeding to dispute whether the processing officer had reasonable grounds to believe that the motorist was driving while intoxicated, the Legislature assumed that a constitutional stop would be a necessary predicate to finding “reasonable grounds” for suspicion of DUI.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 981, 982 (1992), we conclude that it is appropriate to apply the exclusionary rule in civil license suspension proceedings to protect the core value of privacy embraced in Article 11, to promote the public’s trust in the judicial system, and to assure that unlawful police conduct is not -encouraged.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we concluded that the State should not have to risk losing the criminal case because of how the issue was presented in the summary civil suspension proceeding.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the federal regulations under our earlier analysis, we find that they require passenger vehicles to display only one rear white license plate lamp to illuminate the plate from the top or sides.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
