INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As there is no dispute that Stenk-lyft had completed 75 percent of the initial confinement portion of his sentence at the time his petition was filed, we hold that Stenklyft''s petition in this case was not premature.', 'sentencing', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
