INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the plain language of § 973.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not reach this issue because even assuming, arguendo, that the power to modify sentences is an exclusive power of the judiciary, we conclude that § 973.', 'sentencing', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
