INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court erred by granting a directed verdict in favor of defendant Sak’s Party Store, and by finding Les Stanford Oldsmobile to be jointly and severally liable for the entire award under MCL 600.', 'general', 'Hashem v. Les Stanford Oldsmobile, Inc', 'https://www.courtlistener.com/opinion/2195422/', '2195422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s decision to grant a directed verdict in favor of Sak’s Party Store on this ground was error.', 'general', 'Hashem v. Les Stanford Oldsmobile, Inc', 'https://www.courtlistener.com/opinion/2195422/', '2195422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court erred by granting a directed verdict in favor of the party store.', 'general', 'Hashem v. Les Stanford Oldsmobile, Inc', 'https://www.courtlistener.com/opinion/2195422/', '2195422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the trial court erred by finding Les Stanford Oldsmobile to be jointly and severally liable under MCL 600.', 'general', 'Hashem v. Les Stanford Oldsmobile, Inc', 'https://www.courtlistener.com/opinion/2195422/', '2195422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that, in cases such as this, the interest of fairness served by disclosure of the true alignment of the parties to the jury must be weighed against the countervailing interests in encouraging settlements and avoiding prejudice to the parties.', 'general', 'Hashem v. Les Stanford Oldsmobile, Inc', 'https://www.courtlistener.com/opinion/2195422/', '2195422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that this matter must he remanded for a new trial, we do not reach Les Stanford Oldsmobile’s claim that the trial court further abused its discretion by denying its motion for remittitur premised on a comparison of the verdict awarded here to that awarded in other “comparable” cases.', 'general', 'Hashem v. Les Stanford Oldsmobile, Inc', 'https://www.courtlistener.com/opinion/2195422/', '2195422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6312(b)(iii), we reverse and remand.', 'general', 'Hashem v. Les Stanford Oldsmobile, Inc', 'https://www.courtlistener.com/opinion/2195422/', '2195422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Hashem v. Les Stanford Oldsmobile, Inc', 'https://www.courtlistener.com/opinion/2195422/', '2195422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, in the exercise of our supervisory power to insure the fair administration of justice,4 we hold that all custodial interrogation including any information about rights, any waiver of those rights, and all questioning shall be electronically recorded where feasible and must be recorded when questioning occurs at a place of detention.', 'general', 'State v. Scales', 'https://www.courtlistener.com/opinion/2197014/', '2197014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction.', 'general', 'State v. Scales', 'https://www.courtlistener.com/opinion/2197014/', '2197014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though the police in this case disregarded our prior warnings in Robinson and Pilcher, we affirm appellant’s conviction because even if the unrecorded statements had been suppressed the result would have been the same.', 'suppression', 'State v. Scales', 'https://www.courtlistener.com/opinion/2197014/', '2197014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction.', 'general', 'State v. Scales', 'https://www.courtlistener.com/opinion/2197014/', '2197014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons set out below, we reverse and dismiss.', 'dismissal', 'State v. Metzger', 'https://www.courtlistener.com/opinion/2206575/', '2206575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the circumstances at bar, the warrant check was outside the scope of the traffic stop and was impermissible.', 'general', 'People v. Harris', 'https://www.courtlistener.com/opinion/2207574/', '2207574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having applied the Gonzalez framework and considered both prongs of the Terry dual inquiry, we conclude that Officer Reed exceeded the proper scope of the traffic stop when he retained defendant’s identification card and performed a check for outstanding warrants for defendant’s arrest.', 'general', 'People v. Harris', 'https://www.courtlistener.com/opinion/2207574/', '2207574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we conclude that the warrant check changed the fundamental nature of the traffic stop.', 'general', 'People v. Harris', 'https://www.courtlistener.com/opinion/2207574/', '2207574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a passenger in a vehicle stopped by the police is “seized” within the meaning of the fourth amendment.', 'search_seizure', 'People v. Harris', 'https://www.courtlistener.com/opinion/2207574/', '2207574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court reversing the circuit court’s denial of defendant’s motion to suppress.', 'suppression', 'People v. Harris', 'https://www.courtlistener.com/opinion/2207574/', '2207574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gonzalez, we held that, in judging the reasonableness of police questioning during a vehicle stop, where the questioning was neither related to the purpose of the stop nor justified by a reasonable, articulable suspicion of criminal conduct, “we must consider whether, in light of all the circumstances and common sense, the question impermissibly prolonged the detention or changed the fundamental nature of the stop.', 'general', 'People v. Harris', 'https://www.courtlistener.com/opinion/2207574/', '2207574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the officer’s conduct did not make the otherwise lawful detention of the passenger unreasonable within the meaning of the fourth amendment.', 'search_seizure', 'People v. Harris', 'https://www.courtlistener.com/opinion/2207574/', '2207574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an appellate court reviewing a competency determination must use the methodology set forth in Garfoot.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that although the circuit court had a duty to inform Byrge about the parole eligibility information before it accepted his plea, the State has met its burden to prove that, despite the deficiency of the plea colloquy, Byrge nonetheless entered the plea knowingly, voluntarily, and intelligently.', 'plea', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an appellate court reviewing a competency determination must utilize the clearly erroneous standard.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 351 (1975), in which we held that a circuit court is not required to notify defendants about parole rights.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Garfoot, a maj ority of this court held that competency to stand trial must be reviewed under the deferential clearly erroneous standard.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when a circuit court exercises its statutory option to fix a parole eligibility date, that date has a direct and automatic effect on the range of punishment.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our analysis of the case law since Fulford, we conclude that the Supreme Court classifies competency to stand trial within a discrete category in which the resolution of the legal issue is better left to the trial court.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the circuit court did not inform Byrge about a potential direct consequence of his conviction, we conclude that Byrge has made a prima facie showing that the plea was not knowing, voluntary, and intelligent according to the requirements outlined in Wis.', 'plea', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not disturb this finding of fact because we conclude that the circuit court''s determination was not clearly erroneous.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the circuit court''s decision that Byrge was competent to stand trial was not clearly erroneous because testimony at the competency hearing indicated Byrge was able to understand the proceedings and assist in his defense.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a probation revocation proceeding is a civil proceeding.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2988 (1986), we held that in a sexually dangerous person proceeding, the defendant was not entitled to refuse to answer a psychiatrist’s questions which might incriminate him.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Peterson, we held that collateral estoppel prohibited the State from challenging a finding that the defendant’s confession was involuntary at a subsequent probation revocation hearing.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that an involuntary confession cannot be admitted against a defendant in a probation revocation hearing.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, rather than “blindly follow the reasoning of a United States Supreme Court decision at all costs,” this court should rely on its own case law, wisdom and reason to construe our state constitutional provisions.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it should not.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the above principles to the instant case, we find that defendant’s testimony at his probation revocation hearing was not a violation of defendant’s privilege against self-incrimination, under article I, section 10.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that defendant’s testimony at his probation revocation hearing was not a violation of defendant’s right against self-incrimination, pursuant to article I, section 10.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that defendant’s due process rights were not violated by compelling him to testify as an adverse witness for the State.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 988, 991 (1977) (“Because of the statutory history of use of the contempt sanction for probation violations, the similarity between sentences of probation and periodic imprisonment and analogy to the common law treatment of sanctioning willful violations of other court orders by contempt, we conclude that a trial court is empowered to punish a willful violation of a condition of periodic imprisonment by holding the violator in indirect criminal contempt”).', 'sentencing', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the search violated Grant’s Fourth Amendment rights, we reverse the conviction, overturn the trial court’s denial of her motion to suppress, and remand for further proceedings.', 'suppression', 'State v. Grant', 'https://www.courtlistener.com/opinion/2211483/', '2211483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence of arson was legally sufficient and reinstate defendant’s convictions of felony murder.', 'general', 'People v. Nowack', 'https://www.courtlistener.com/opinion/2211727/', '2211727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that the evidence was sufficient to establish the elevated level of intent required by the standard instruction.', 'general', 'People v. Nowack', 'https://www.courtlistener.com/opinion/2211727/', '2211727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '528 NW2d 160 (1995), we held that “the word ‘arson’ in the felony murder statute refers to the common-law crime of arson, that is, the malicious and voluntary or wilful *401burning of a dwelling house of another.', 'general', 'People v. Nowack', 'https://www.courtlistener.com/opinion/2211727/', '2211727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ORDERED that DANIEL B.', 'general', 'In re Jacobs', 'https://www.courtlistener.com/opinion/7406508/', '7406508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that the exclusionary rule applies because the warrant was void when issued, the State asks us to extend the good-faith exception to the exclusionary rule in Wisconsin to render evidence admissible when it is seized pursuant to a warrant issued without statutory authority.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The dissent overlooks the language leading up to the Janis quote: "To the extent that recent cases state that deterrence is the prime purpose of the exclusionary rule, and that ''judicial integrity'' is a relevant, albeit subordinate factor, we hold that in this case considerations of judicial integrity do not require exclusion of the evidence.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that suppression was necessary because the means by which the state procured evidence was in violation of the procedures set out by statute.', 'suppression', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By the same token, we held that suppression of an incriminating statement procured by use of those same documents was necessary to fully protect persons from the state''s failure to comply with the statute.', 'suppression', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held in Kriegbaum that where a magistrate lacked authority to issue a warrant, the search conducted and evidence seized resulted in a constitutional violation.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wisconsin, the exclusionary rule dates back to 1923, when this court held that, for "the Bill of Rights as embodied in constitutions to be of substance rather than mere tinsel," a conviction may not rest on unlawfully seized evidence.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the good-faith exception to the exclusionary rule does not apply to a situation in which: (1) no facts existed that would justify an arrest without a warrant;', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the decision of the court of appeals, State v.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the decision of the court of appeals.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a postconviction petitioner demonstrates that defense counsel was ineffective for failing to file a notice of appeal, the trial court may allow the petitioner leave to file a late notice of appeal.', 'ineffective_assistance', 'People v. Ross', 'https://www.courtlistener.com/opinion/2214661/', '2214661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the appellate court acted correctly in vacating its order and dismissing the defendant’s appeal, but we used our supervisory authority to reinstate the defendant’s appeal.', 'dismissal', 'People v. Ross', 'https://www.courtlistener.com/opinion/2214661/', '2214661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the language of the armed robbery statute, which requires a person to carry or to be armed with a dangerous weapon, we concluded that the legislature had
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'People v. Ross', 'https://www.courtlistener.com/opinion/2214661/', '2214661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that we have stated, we affirm the judgment of the appellate court.', 'general', 'People v. Ross', 'https://www.courtlistener.com/opinion/2214661/', '2214661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Soule, for example, we held that the trial court erred by giving a self-defense instruction as to an assault count, but declining to give a competing harms justification as to an aggravated criminal trespass count.', 'general', 'State v. Ouellette', 'https://www.courtlistener.com/opinion/5144992/', '5144992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the jury’s acquittal of the defendant on the assault count indicated that “it was not highly probable that the [failure to give the justification] instruction did not affect the verdict.', 'general', 'State v. Ouellette', 'https://www.courtlistener.com/opinion/5144992/', '5144992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgments of the lower courts, order the injunctions issued to be lifted, and declare Ind.', 'general', 'State v. Baysinger', 'https://www.courtlistener.com/opinion/2218034/', '2218034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court erred when it dismissed this charge against Koenig and therefore we reverse the decision of that court and the affirmance of the decision by the court of appeals.', 'dismissal', 'State v. Koenig', 'https://www.courtlistener.com/opinion/2219095/', '2219095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the statute’s definition of solicitation is plain, an analysis of the legislature’s intent is unnecessary to support our conclusion that there was sufficient probable cause to charge Koenig.', 'probable_cause', 'State v. Koenig', 'https://www.courtlistener.com/opinion/2219095/', '2219095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we conclude that there is sufficient credible evidence of probable cause to support the charge against Koenig for the solicitation *376of a child for sexual activity.', 'probable_cause', 'State v. Koenig', 'https://www.courtlistener.com/opinion/2219095/', '2219095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Koenig', 'https://www.courtlistener.com/opinion/2219095/', '2219095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a circuit court should conduct an on-the-record colloquy to ensure that the defendant is knowingly, intelligently, and voluntarily waiving his or her right to testify.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In analyzing Weed''s hearsay challenge and ultimately concluding that any error was harmless, the court of appeals appeared to employ a sufficiency of the *457evidence standard: "Because there was sufficient evidence, other than Michael''s alleged hearsay statement, to convict Patricia [Weed] beyond a reasonable doubt, we hold that any error in the admission of the Fuer-bringers'' testimony was harmless.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the circuit court did not erroneously exercise its discretion in admitting the hearsay statement under the recent perception exception to the hearsay rule.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the constitutional right of a criminal defendant to testify on his or her behalf is a fundamental right.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on our review of the record and the circuit court''s rulings regarding the admissibility of Michael''s statement, we conclude that the circuit court did not erroneously exercise its discretion in admitting Michael''s statement under the recent perception exception to the hearsay rule.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of defense counsel''s cross-examination of Fuerbringer and his son, the low probative value of Michael''s statement, and the overwhelming evidence presented by the State, we conclude that the admission of the hearsay statement was not prejudicial.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the admission of Michael''s statement did not contribute to the verdict because it is "clear beyond a reasonable doubt that a rational jury would have convicted absent the error.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the lack of a colloquy, we conclude that Weed knowingly, intelligently, and voluntarily waived *465her right to testify based on our review of the record and the evidence presented at the post-conviction hearing.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that Weed waived her right to testify based on the record and the evidence presented at the post-conviction hearing, we decline to determine whether a post-conviction hearing would always be sufficient to ensure that a criminal defendant has waived his or her right to testify.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the circuit court did not erroneously exercise its discretion in admitting the hearsay statement made by Michael under the recent perception exception to the hearsay rule.', 'general', 'State v. Weed', 'https://www.courtlistener.com/opinion/2219163/', '2219163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the legislature did not clearly intend in § 939.', 'general', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '66(2m) is viewed in its full context, considering its legislative history as well as the different harms addressed by different battery statutes, we conclude that § 939.', 'general', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Davison''s multiplicity objection fails on the merits, we decline to decide whether, by pleading guilty, he waived his right to raise this claim.', 'plea', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the imposition of cumulative punishments from different statutes in a single prosecution for "the same offense" violates double jeopardy when the cumulative punishments are not intended by the legislature.', 'general', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our four-factor examination of legislative intent to this multiplicity challenge, we conclude that Davison has failed to meet his burden of *195persuasion.', 'general', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we affirmed the circuit court''s decision refusing to submit either simple battery or intermediate battery to the jury as lesser-included offenses of aggravated battery.', 'general', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the legislative purpose and the underpinnings of the Probate Code mandate the conclusion that a probate court’s discretion at the dispositional phase of a waiver hearing remains unfettered by certain evidentiary requirements recognized in criminal proceedings and already extended to the adjudicative phase of a waiver hearing.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '377 NW2d 262 (1985), in which this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the Court’s analysis of these cases is flawed, and thus it erred in reversing the probate court’s decision to waive jurisdiction over defendant.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Due Process Clause of the Fourteenth Amendment requires that in respect of proceedings to determine delinquency which may result in commitment to an institution in which the juvenile’s freedom is curtailed, the child and his parents must be notified of the child’s right to be represented by counsel retained by them, or if they are unable to afford counsel, that counsel will be appointed to represent the child.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the constitutional protections extended to juvenile proceedings in cases such as Kent and Gault apply in full force to the adjudicative phase of a juvenile waiver hearing.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and remand the case for consideration of the remaining issues raised by defendant.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that 1) jury unanimity was not required on the intent component of the charge of child enticement under Wis.', 'general', 'State v. Derango', 'https://www.courtlistener.com/opinion/2221376/', '2221376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying Schad''s due process test of fundamental fairness and rationality here, we conclude that unanimity was not required.', 'general', 'State v. Derango', 'https://www.courtlistener.com/opinion/2221376/', '2221376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the strong probative value of the videotapes was not substantially outweighed by the danger of unfair prejudice in this case.', 'general', 'State v. Derango', 'https://www.courtlistener.com/opinion/2221376/', '2221376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although some cautionary instructions may be so broad that their effectiveness is significantly diminished, we conclude that this cautionary instruction was not.', 'general', 'State v. Derango', 'https://www.courtlistener.com/opinion/2221376/', '2221376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Derango', 'https://www.courtlistener.com/opinion/2221376/', '2221376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Derango', 'https://www.courtlistener.com/opinion/2221376/', '2221376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If reason existed for legislative rather than judicial action to invalidate an exculpatory clause in a lease, as against public policy, as this court held in O’Callaghan, then, beyond doubt, the same rule should have been applied by the court in its decision in this case.', 'general', 'Molitor v. Kaneland Community Unit District No. 302', 'https://www.courtlistener.com/opinion/2225058/', '2225058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the statute does not attach any significance to the transfer of money in connection with the acts it proscribes, we conclude that the commercial aspect of the defendant’s proposition to the officers has no significance.', 'general', 'People v. Masten', 'https://www.courtlistener.com/opinion/2222708/', '2222708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion in denying Brown’s request for a mistrial.', 'mistrial', 'Brown v. State', 'https://www.courtlistener.com/opinion/2223888/', '2223888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the criminal confinement statute does not provide notice to persons of ordinary intelligence that devising a fake radio contest, in which persons drive themselves to some
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the identity deception statute is defined with sufficient definiteness to adequately inform persons of ordinary intelligence that knowingly using the identifying information of a corporation, such as a radio station, without its consent and with intent to harm or defraud another person constitutes identity deception.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2223888/', '2223888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that there was sufficient evidence to support the jury’s verdict that Brown is guilty of three counts of identity deception.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2223888/', '2223888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In rejecting the defendant’s constitutional challenge, we concluded that the specific intent required by the language of the statute, “to harass, annoy, or alarm another person but with no intent of legitimate communication,” prevented the statute from being unconstitutionally vague.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2223888/', '2223888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Brown’s criminal confinement convictions.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2223888/', '2223888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2223888/', '2223888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Whitfield', 'https://www.courtlistener.com/opinion/2224582/', '2224582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Carter''s offer of proof fails the first and second prongs of the Pulizzano test, we hold that evidence of the alleged previous sexual assault against Cassandra is not excepted from the rape shield law and is therefore inadmissible.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Pulizzano, this court held that while Wisconsin''s rape shield law is constitutional on its face, as applied it may unconstitutionally infringe upon a defendant''s rights to confrontation and compulsory process.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court of appeals improperly remanded the case to the circuit court for further proceedings.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On review, we conclude that Carter did not receive ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Sargent''s performance was not deficient because his strategic decision not to present evidence of the previous sexual assault was objectively reasonable considering all the circumstances.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Sargent reasonably decided that further investigation of the alleged prior sexual assault and its admissibility was unnecessary.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', however, we conclude that Sargent''s decision not to investigate was reasonable.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even assuming that Sargent''s performance was deficient, we conclude that the deficiency did not prejudice Carter''s defense because evidence of the previous sexual assault would have been inadmissible.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that Carter''s offer of proof fails the first and second prongs of the Pulizzano test, and therefore, evidence of the alleged previous sexual assault against Cassandra is not admissible as an exception to the rape shield law.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To summarize, we conclude that the court of appeals improperly remanded the case to the circuit court for further proceedings.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that without knowledge of the applicable law, it is impossible for an attorney to "make a reasoned decision consistent with the standard of performance expected of a prudent lawyer," and that the court should not "ratify a lawyer''s decision merely by labeling it.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction if, looking to the evidence and reasonable inferences therefrom which support the verdict, there is substantial evidence of probative value to support the conclusion of the trier of fact.', 'general', 'Barger v. State', 'https://www.courtlistener.com/opinion/2225706/', '2225706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On these facts, we hold that Trooper Va-selaar did not have an objective legal basis for suspecting that the George was driving his motorcycle in violation of any motor vehicle law (or that he was violating any other law).', 'general', 'State v. George', 'https://www.courtlistener.com/opinion/2226606/', '2226606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the type of careful review that we spelled out in Dezso, we hold that under the totality of circumstances in this case, the state failed to meet its burden of proving that the defendant voluntarily consented to the search.', 'general', 'State v. George', 'https://www.courtlistener.com/opinion/2226606/', '2226606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that there was no objective legal basis for the stop and no consent to the search, we reverse the court of appeals and vacate the conviction.', 'general', 'State v. George', 'https://www.courtlistener.com/opinion/2226606/', '2226606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '188 NW2d 59 (1971), this Court held that the prior statutory language "returned to a state penal institution”, should not be literally construed.', 'general', 'Hinton v. Parole Board', 'https://www.courtlistener.com/opinion/2227024/', '2227024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the parolee was "unavailable” by virtue of his incarceration in Oakland County on local criminal charges.', 'general', 'Hinton v. Parole Board', 'https://www.courtlistener.com/opinion/2227024/', '2227024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '371 NW2d 862 (1985), this Court held that the availability of review of parole revocation decisions under § 101 of the Administrative Procedures Act, supra, did not foreclose alternative avenues of judicial review.', 'general', 'Hinton v. Parole Board', 'https://www.courtlistener.com/opinion/2227024/', '2227024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the lower court erred in holding that only the plaintiff could waive a timely hearing.', 'general', 'Hinton v. Parole Board', 'https://www.courtlistener.com/opinion/2227024/', '2227024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Harris was not seized at this point in the encounter.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Harris was not seized when the officers approached and questioned him at his seat.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Harris did not voluntarily consent to the second search of his person.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the second search of Harris’ person and the resulting seizure of the marijuana found in Harris’ jacket was justified and that the marijuana should not have been suppressed.', 'suppression', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ascher, we held that random sobriety checkpoints are unconstitutional under the Minnesota Constitution.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), where we held that the police seized an underage bar patron.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, under the facts of that case, Cripps had been seized within the meaning of Article I, Section 10 of the Minnesota Constitution after the officers first asked her to produce identification for the purpose of showing that she was of legal age to consume alcohol.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dez-so, we held that the state did not meet its burden of showing that a police officer obtained voluntary consent when the officer searched a defendant’s wallet during a traffic stop on a highway at night.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In George, we held that the state produced insufficient evidence to show that the defendant voluntarily consented to a search of his motorcycle when the defendant was stopped for a minor traffic violation.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'is supported by our decision in Cripps, where we held that Cripps was seized because, “[ujnder [the] circumstances, * * * an objectively reasonable person would have believed that he or she was neither free to disregard the officer’s request nor free to terminate the encounter * * Cripps, 533 N.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In Re Interest of Richter', 'https://www.courtlistener.com/opinion/2228866/', '2228866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the affidavit supporting the October 10, 2006, search warrant was properly filed.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2229197/', '2229197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we consider this to be a close case, we conclude that the C.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2229197/', '2229197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we conclude that the October 10, 2006, search warrant was supported by probable cause, and the trial court therefore did not abuse its discretion in admitting evidence discovered pursuant to its execution.', 'probable_cause', 'Scott v. State', 'https://www.courtlistener.com/opinion/2229197/', '2229197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regarding Deputy Saltzmaris averment that he had detected the odor of ether at Scott’s residence within the prior two months, however, we conclude that this information is not stale.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2229197/', '2229197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the fact of a prior criminal conviction is one of those instances where the staleness doctrine does not apply.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2229197/', '2229197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the probable cause affidavit was properly filed and that the associated search warrant was supported by sufficient probable cause.', 'probable_cause', 'Scott v. State', 'https://www.courtlistener.com/opinion/2229197/', '2229197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that information that ether had been detected within the prior two months at Scott’s residence and that he had been convicted four years previously of manufacturing methamphetamine at the same address was not stale.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2229197/', '2229197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2229197/', '2229197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain language of the statute makes clear that a seventeen-year-old employed by a parent to care for the parent''s child can be a person responsible for the welfare of the child.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/2230341/', '2230341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reject Hughes''s claim that she cannot be considered a person responsible for the victim''s welfare, we affirm the judgment and order.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/2230341/', '2230341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Last term, in Dubose, when this court held that evidence obtained from an out-of-court showup will not be admissible unless the procedure was "necessary," it based its decision on the due process clause in the Wisconsin Constitution.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court still has a limited gate-keeping function to exclude such evidence under Wis.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 Accordingly, we reverse the court of appeals and remand to the circuit court for a determination of whether evidence of the identification of Hibl should be excluded under § 904.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals and remand for the circuit court to make a determination of whether Stuller''s identification of Hibl should be excluded pursuant to § 904.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and remand to the circuit court for a determination of whether the identification evidence in this case should be excluded under § 904.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons expressed above, we hold that the trial court erred in each of these three consolidated cases by using mere-fact impeachment.', 'general', 'People v. Harvey', 'https://www.courtlistener.com/opinion/2234471/', '2234471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*** In Atkinson, however, we held that ‘trial courts should not consider the mere-fact method of impeachment.', 'general', 'People v. Harvey', 'https://www.courtlistener.com/opinion/2234471/', '2234471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In King, this court held that a criminal defendant may not be convicted of multiple offenses when those offenses are all based on precisely the same physical act.', 'general', 'People v. Harvey', 'https://www.courtlistener.com/opinion/2234471/', '2234471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying King to the present case, we conclude that the unlawful possession of a stolen motor vehicle offenses and the aggravated possession offense were based on the same physical act.', 'general', 'People v. Harvey', 'https://www.courtlistener.com/opinion/2234471/', '2234471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the appellate court decision in Harvey, No.', 'general', 'People v. Harvey', 'https://www.courtlistener.com/opinion/2234471/', '2234471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand the appellate court’s judgment in Barefield, No.', 'general', 'People v. Harvey', 'https://www.courtlistener.com/opinion/2234471/', '2234471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lastly, we affirm the appellate court decision in Lyons, 315 Ill.', 'general', 'People v. Harvey', 'https://www.courtlistener.com/opinion/2234471/', '2234471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 959, we affirm the appellate court’s judgment in that case as well.', 'general', 'People v. Harvey', 'https://www.courtlistener.com/opinion/2234471/', '2234471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wilson, this court held that, once a defendant is warned of his rights, he is free to exercise his own decision of whether to make a second statement.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing considerations, we find that any failure to contact Jon’s parents or a juvenile officer prior to questioning Jon did not render his statements involuntary.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we find that the totality of circumstances indicates that Jon’s confession was the result of his own decision and was not the result of compulsion or inducement, nor was Jon’s will being overborne at the time of his confession.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not address whether the appellate court properly found that Harberts’ question was interrogation and that Jon was in custody because we find that, even if the trial court erroneously denied Jon’s motion to suppress his initial statement to Harberts, any error was, at most, harmless.', 'suppression', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As those statements, which repeated and in fact enlarged upon Jon’s initial response to Harberts, were admissible, we find that any purported error in admitting Jon’s initial statement to Harberts was harmless.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, this case is distinguishable from our decision in Clark, where we found that there was “not one scintilla of evidence in the record of the transfer proceeding that would have apprised anyone that the transfer could result in a term of natural life imprisonment.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we found that a juvenile’s confession was voluntary even though he was not provided with an opportunity to confer with a concerned adult because: the juvenile never requested to speak with a concerned adult;', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the holdings in Williams and Kidd to be erroneous, however, we reverse the appellate court’s finding that the trial court should have followed the precedent set forth in those cases and should have given second degree murder instructions on the felony-murder counts.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the appellate court’s finding that a second degree murder instruction should have been given on the charges of felony murder, and affirm the trial court’s order declining to give that instruction.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse the appellate court’s finding that it was prejudicial error to exclude the evidence set forth in Jon’s offers of proof, and affirm the trial court’s ruling excluding the evidence.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the trial court correctly denied defendant’s motion to suppress.', 'suppression', 'State v. Lamb', 'https://www.courtlistener.com/opinion/2259118/', '2259118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the detention was amply justified because (a) the investigating officer had corroborating information that could only have come from a knowledgeable insider, (b) the officer knew that defendant had been arrested previously for DUI, and (c) the offense of DUI presented an imminent risk of injury to the suspect or the public.', 'general', 'State v. Lamb', 'https://www.courtlistener.com/opinion/2259118/', '2259118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lamb', 'https://www.courtlistener.com/opinion/2259118/', '2259118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not necessary for the prosecution to prove, in order that DNA evidence be admitted, that there is a scientific consensus as to the precise probability of a coincidental match.', 'general', 'United States v. Porter', 'https://www.courtlistener.com/opinion/2262050/', '2262050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court holds that this formulation states the relevant scientific field.', 'general', 'United States v. Porter', 'https://www.courtlistener.com/opinion/2262050/', '2262050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the balance to be struck falls within the wide discretion of the trial court.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/2264175/', '2264175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that defendant’s motive in fleeing from the police was irrelevant to the offense.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/2264175/', '2264175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/2264175/', '2264175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the crime for which the defendant was sentenced required a mandatory minimum of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reversed and remanded so that the trial judge could impose the required mandatory minimum sentence.', 'sentencing', 'State v. Sloman', 'https://www.courtlistener.com/opinion/2264206/', '2264206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the sentencing judge, in response to the Attorney General’s forceful prodding, purportedly relied upon Rule 35(b) and the “extraordinary circumstances” language in that rule to justify the sentence modification, we affirm on the basis of a different rationale than that articulated by the sentencing court.', 'sentencing', 'State v. Sloman', 'https://www.courtlistener.com/opinion/2264206/', '2264206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State is constitutionally required to extend to same-sex couples the common benefits and protections that flow from marriage under Vermont law.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that a woman who was co-parenting the two children of her same-sex partner could adopt the children without terminating the natural mother’s parental rights.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, although the State proffered at least a conceivable purpose for the legislative distinction between natural and adopted children, we held that the classification was unreasonable, explaining that *206“[a]dopted persons have historically been a target of discrimination,” id.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the Common Benefits Clause of the Vermont Constitution, which, in pertinent part, reads,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that this approach, rather than the rigid, multi-tiered analysis evolved by the federal courts under the Fourteenth Amendment, shall direct our inquiry under Article 7.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, viewed in the light of history, logic, and experience, we conclude that none of the interests asserted by the State provides a reasonable and just basis for the continued exclusion of same-sex couples from the benefits incident to a civil marriage license under Vermont law.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather than eschewing the federal standards, we held that the educational financing system advanced no “legitimate governmental purpose” under any standard.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that aggravating factor e(4)(f) may be submitted to the jury when the State has produced sufficient *283evidence on which a jury can reasonably conclude that at least one of the motives of the defendant in killing his or her victim was to eliminate a witness or avoid subsequent apprehension and prosecution for criminal acts.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant never requested such an instruction, nor did the jury make an inquiry into the subject, we hold that no error resulted.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we hold that in the future when defense counsel or the jury requests instructions on the potential sentences a defendant will receive for convictions arising from the same trial as his capital-murder conviction, such information should be provided by the trial court.', 'sentencing', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 185 (1966), we held that the Constitution does not require a grand jury presentment before a convicted defendant may receive an enhanced sentence based on his status as a habitual offender.', 'sentencing', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, in Purnell, supra, we held that when the State sought to establish, as an aggravating factor, that a murder was committed in the course of a felony, the defendant was entitled to have the jury consider the non-capital verdict of felony-murder during the guilt-phase deliberations.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that opinion we held that defendants who had been served with a notice of an aggravating factors could, through summary proceedings before the trial court, challenge the sufficiency of the evidence to support those factors.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “our law does not regard a crime committed against a particularly virtuous person as more heinous than one committed against a victim whose moral qualities are perhaps less noteworthy or apparent.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because the defense is allowed to introduce mitigating evidence outside of the Rules of Evidence during the penalty phase to ensure that the jury imposes death only when the defendant is deserving of the punishment, the State should also be permitted to rebut that evidence under the same relaxed conditions.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such a likelihood exists with respect to murders committed during the course of a kidnapping.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of that concern for the reliability of the jury’s verdict, we held that the court, either on defendant’s request or in the event of a jury inquiry, should instruct the jury that the court will decide whether a sentence is to be served concurrently or consecutively to any prior sentences.', 'sentencing', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 172, we concluded that a mitigating factor could be established “by some reliable evidence.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the transcript of the trial in this case, we conclude that the State produced sufficient evidence to convince a reasonable trier of fact beyond a reasonable doubt that the defendant had cultivated the marijuana in the garden.', 'general', 'State v. Neale', 'https://www.courtlistener.com/opinion/2265915/', '2265915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in denying the defendant’s motion for judgment of acquittal based on insufficient evidence.', 'general', 'State v. Neale', 'https://www.courtlistener.com/opinion/2265915/', '2265915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentencing judge gave weight to an improper factor in imposing the sentence;', 'sentencing', 'State v. Neale', 'https://www.courtlistener.com/opinion/2265915/', '2265915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction but remand the case for resentencing.', 'sentencing', 'State v. Neale', 'https://www.courtlistener.com/opinion/2265915/', '2265915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm in part and vacate in part.', 'general', 'Commonwealth v. Bracey', 'https://www.courtlistener.com/opinion/2267936/', '2267936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, this court held: “A party indicted of one offence may be convicted of a lesser, provided it be of the same class with that which he is charged.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '712, 714 (1852), wherein this court held: [U]pon an indictment for a felony, the accused may be convicted of a misdemeanor, where both offences belong to the same generic class, where the commission of the higher may involve the commission of the lower offence, and where the indictment for the higher offence contains all the substantive allegations necessary to let in proof of the misdemeanor.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that under the third test in section 41-105(2)(c), now section 5-1-110(b)(3), negligent homicide was a lesser-included offense of manslaughter because the only difference between the two offenses was that negligent homicide required a lesser kind of culpable mental state than manslaughter.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the first of those cases, Martin, this court held that “the phrase ‘circumstances manifesting extreme indifference to the value of human life’ indicates that the attendant circumstances themselves must be such as to demonstrate the culpable mental state of the accused.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that second-degree murder was not a lesser-included offense of the type of first-degree murder charged in that case, because “the element of causing a death under circumstances manifesting extreme indifference to the value of human life is not an element of the charge for first-degree murder of a person aged fourteen years or younger.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court and affirm the court of appeals.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 29 We conclude that Appellant has mischaracterized his arguments as sufficiency of the evidence claims, and in particular, we specifically disagree with his contention that his claims challenge the sufficiency, and not the weight, of the evidence.', 'general', 'Commonwealth v. Fuentes', 'https://www.courtlistener.com/opinion/2274019/', '2274019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Fuentes', 'https://www.courtlistener.com/opinion/2274019/', '2274019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 31 For all of the foregoing reasons, we affirm.', 'general', 'Commonwealth v. Fuentes', 'https://www.courtlistener.com/opinion/2274019/', '2274019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2275183/', '2275183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm a conviction if substantial evidence exists to support it.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2275183/', '2275183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the evidence of this other victim was improperly admitted.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2275183/', '2275183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we affirm the order of the Superior Court.', 'general', 'Commonwealth v. Grant', 'https://www.courtlistener.com/opinion/2275598/', '2275598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the impeachment of a witness by prior convictions is subject to the discretion of the trial court.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/2280249/', '2280249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Manning, supra, this Court held that a witness may be impeached by cross-examination concerning any prior convictions for crimes involving moral turpitude within 15 .', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/2280249/', '2280249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon reconsideration we conclude that Manning was decided incorrectly, ahd hold that the cross-examination of a witness concerning prior convictions is subject to the discretion of the trial court.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/2280249/', '2280249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that subject to the trial court’s overriding control of the proceedings, the State "should have the right to make a full showing before the jury whenever it considers such course necessary for the proper presentation of its case.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/2315254/', '2315254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While not condoning all aspects of the prosecutor’s conduct, we conclude that, in the context of the entire trial, it did not cause defendant to be denied a fair trial.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/2315254/', '2315254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the facts in this case, we find that the expert testimony was relevant to Gladys Kelly’s state of mind, namely, it was admissible to show she honestly believed she was in imminent danger of death.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/2315254/', '2315254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for a new trial.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/2315254/', '2315254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, “the basic concerns of criminal justice compel us to prohibit .', 'general', 'State v. Ramsay', 'https://www.courtlistener.com/opinion/2292504/', '2292504') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Ramsay', 'https://www.courtlistener.com/opinion/2292504/', '2292504') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the one house veto provision contained in § 233(c)(2) of the Home Rule Act is invalid based on Immigration &amp;', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that none of the appellants is entitled to relief.', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reject Pee’s suggestion that we conclude that without the legislative veto, Congress would have rejected home rule because of “a distrust of the Democratic, liberal and largely black government that would result.', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Johnson, supra, we conclude that our decision should have prospective effect only, from the date of our decision.', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*836We find that the trial court’s error was harmless beyond a reasonable doubt.', 'general', 'Gary v. United States', 'https://www.courtlistener.com/opinion/2292661/', '2292661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reversing the ruling of the trial court, this Court held that defendant “was entitled to show that some, at least, of the injuries described to the jury could have been caused by another person, consistent with his denial of guilt, claim of alibi, and claim of prosecution for revenge.', 'general', 'State v. Catsam', 'https://www.courtlistener.com/opinion/1533402/', '1533402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the strong potential prejudice from the allowance of the proffered cross-examination, compared to its demonstrably weak probative value, we conclude that the trial court’s ruling was without error.', 'general', 'State v. Catsam', 'https://www.courtlistener.com/opinion/1533402/', '1533402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial because of the improper introduction at trial of prejudicial expert testimony.', 'general', 'State v. Catsam', 'https://www.courtlistener.com/opinion/1533402/', '1533402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1528693/', '1528693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court correctly dismissed their claims.', 'dismissal', 'Brady v. Dean', 'https://www.courtlistener.com/opinion/2301189/', '2301189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Brady v. Dean', 'https://www.courtlistener.com/opinion/2301189/', '2301189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the particular course chosen by counsel had some reasonable basis, our inquiry ceases and counsel’s assistance is deemed effective.', 'general', 'Commonwealth v. Yager', 'https://www.courtlistener.com/opinion/2304642/', '2304642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has not established manifest injustice requiring the withdrawal of his guilty plea.', 'plea', 'Commonwealth v. Yager', 'https://www.courtlistener.com/opinion/2304642/', '2304642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm.', 'general', 'Commonwealth v. Yager', 'https://www.courtlistener.com/opinion/2304642/', '2304642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(“We find that the absence of this inquiry from the transcript renders the colloquy defective” [615 A.', 'general', 'Commonwealth v. Yager', 'https://www.courtlistener.com/opinion/2304642/', '2304642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Burns was guilty of theft of property with a value of less than $1000, we conclude that the instructional error was harmless.', 'general', 'State v. Burns', 'https://www.courtlistener.com/opinion/2319535/', '2319535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 15] Because we conclude that the jury could not have rationally found that the value of the property stolen was less than $1000, the basic sentence was appropriately set based on a Class C conviction.', 'sentencing', 'State v. Burns', 'https://www.courtlistener.com/opinion/2319535/', '2319535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury rationally could have found from the evidence presented at trial that Burns was guilty of the theft of the check involved in this case, and the jury could only have found that the amount stolen was the amount of the check, we affirm the conviction.', 'general', 'State v. Burns', 'https://www.courtlistener.com/opinion/2319535/', '2319535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989) (en banc), we conclude that the prosecutor’s remarks coupled with the use of unnecessarily graphic photos of the corpse were improper.', 'general', 'Chatmon v. United States', 'https://www.courtlistener.com/opinion/2320585/', '2320585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Where appellant did not preserve the objection, we reverse only for plain error, i.', 'general', 'Chatmon v. United States', 'https://www.courtlistener.com/opinion/2320585/', '2320585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse and remand on the ineffectiveness claim, we need not reach appellant''s other evidentiary and instructional claims relating to the introduction of a photograph with a police identification number or the sufficiency of evidence for an aiding and abetting instruction.', 'ineffective_assistance', 'Chatmon v. United States', 'https://www.courtlistener.com/opinion/2320585/', '2320585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse on this ground, I do not associate myself with Judge Ruiz’s treatment of the issue of the prosecutor’s use of the photographs of the victim in closing argument, which has the character of lengthy dictum.', 'general', 'Chatmon v. United States', 'https://www.courtlistener.com/opinion/2320585/', '2320585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'test as a guide for applying our own plain-error standard, we hold that the district court’s sentencing decision was plain error.', 'sentencing', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we held that the trial court erred by refusing to instruct the jury on voluntary manslaughter when the defendant maintained his complete innocence at trial.', 'general', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that facts not proven to the jury beyond a reasonable doubt could not be used to increase a first-degree murder sentence beyond the presumptive sentence of life with a minimum term of thirty-five years.', 'sentencing', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s initiation of the third interview was voluntary despite the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s actions were voluntary for the same reasons discussed above.', 'general', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it would be both unfair to appellant and harmful to the public reputation of Vermont’s justice system to allow appellant’s sentence to stand under these circumstances.', 'sentencing', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we concluded that “our acceptance of [the State’s harmless error] argument Vould effectively negate the right to jury instructions on a lesser-included offense in every case.', 'jury_instruction', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm appellant’s conviction, but we reverse in part the superior court’s grant of summary judgment with respect to appellant’s PCR petition, and we remand the petition to the superior court for further proceedings.', 'general', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '‘We reverse trial court evidentiary rulings only when we find an abuse of that discretion resulting in prejudice.', 'general', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm each of the superior court’s rulings except for its determination that there was no genuine issue of material fact with respect to Schwarz’s alleged failure to discuss with appellant the possibility of an argument for a lesser charge.', 'general', 'State v. Yoh', 'https://www.courtlistener.com/opinion/2320298/', '2320298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a law enforcement officer’s investigation of a third party’s civil speeding offense cannot, standing alone, justify the stop and seizure of a motorist, and we vacate the judgment.', 'general', 'State v. LaPlante', 'https://www.courtlistener.com/opinion/2324370/', '2324370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, we concluded that the public concern in the investigation of a recently-committed burglary was sufficiently grave to outweigh the interference with a motorist’s liberty interest when the motorist was stopped briefly at a roadblock for questioning about the burglary.', 'general', 'State v. LaPlante', 'https://www.courtlistener.com/opinion/2324370/', '2324370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we find that Appellant’s reliance on Riggins is misplaced.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court acted within its discretion in determining that Appellant was competent to stand trial.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that a capital defendant’s waiver to his statutory right to a penalty-phase jury must be knowing, voluntary and intelligent.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the waiver of a jury trial, we find that any waiver to a capital defendant’s right to a penalty-phase jury must be considered a personal right of the defendant''s.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm Appellant’s convictions but reverse the judgment of sentence imposed by the trial court and remand for a new penalty phase hearing.', 'sentencing', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*348Accordingly, we affirm Appellant’s convictions but vacate the judgment of sentence and remand for a new penalty phase hearing.', 'sentencing', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we held that the trial court *357should determine defendant’s actual knowledge by looking at the totality of the circumstances to distinguish whether the plea was voluntarily, knowingly, and intelligently made.', 'plea', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1305 (1992), this Court held that defendant was entitled to withdraw his guilty plea where the trial court failed to inform him that sentences for multiple counts could be consecutive.', 'sentencing', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we concluded that the defendant was not entitled to any post-conviction relief.', 'general', 'Commonwealth v. O''Donnell', 'https://www.courtlistener.com/opinion/2324807/', '2324807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that all of the challenged statements were admissible under either the prior identification exception or the medical diagnosis exception to the hearsay rule.', 'general', 'Brown v. United States', 'https://www.courtlistener.com/opinion/2328540/', '2328540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record we hold that the court properly barred a highly prejudicial line of questioning until such evidence was provided — which never happened.', 'general', 'Brown v. United States', 'https://www.courtlistener.com/opinion/2328540/', '2328540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court did not err in admitting the evidence, and thus we need not even consider whether a limiting instruction was required, especially when none was requested.', 'general', 'Brown v. United States', 'https://www.courtlistener.com/opinion/2328540/', '2328540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the challenged evidence served to place the charged crimes in context,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 484 (1997), this court held that, notwithstanding
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because each inquiry leads us to conclude that defendant is entitled to relief, we affirm the judgment of the Appellate Division and remand the matter for a new trial.', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/2328579/', '2328579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, and in all other respects, we affirm the judgment of the Appellate Division.', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/2328579/', '2328579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, where an offender is incarcerated on both a Board detainer and new criminal charges, all time spent in confinement must be credited to either the new sentence or the original sentence.', 'sentencing', 'Martin v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/2328682/', '2328682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'case somewhat similar to this, we held that a man who refused to leave his girlfriend’s apartment after she clearly had ordered him to do so could be convicted for unlawful entry.', 'general', 'District of Columbia v. Murphy', 'https://www.courtlistener.com/opinion/2328784/', '2328784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that the District failed to present such undisputed evidence of probable cause to the trial court.', 'probable_cause', 'District of Columbia v. Murphy', 'https://www.courtlistener.com/opinion/2328784/', '2328784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review of the record, we conclude that we should not consider this argument because the District failed to present it to the trial court.', 'general', 'District of Columbia v. Murphy', 'https://www.courtlistener.com/opinion/2328784/', '2328784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Blackmer', 'https://www.courtlistener.com/opinion/2328910/', '2328910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge erred in so doing.', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 We conclude that, under the circumstances, the husband’s incarceration was a factor which may and should have been considered by the trial judge;', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that even if the husband remained incarcerated, that circumstance would not prevent him from engaging in conduct, either alone, through others, or both, that would be barred by the CPO if it had been extended.', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for further proceedings on the wife’s motion to extend the CPO.', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all three cases, we reverse and remand for resentencing.', 'sentencing', 'People v. Khanani', 'https://www.courtlistener.com/opinion/8006606/', '8006606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an instruction to the jury that the lack of fingerprint evidence cannot, as a matter of law, constitute reasonable doubt impermissibly invaded the jury’s exclusive province to weigh the evidence as a whole against the standard of reasonable doubt, and requires reversal even under the high standard for plain error review.', 'general', 'Wheeler v. United States', 'https://www.courtlistener.com/opinion/2330422/', '2330422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the instruction, viewed in context, was contrary to the elemental premise that a critical assessment of that evidence was for the jury, and not the judge, to make, we hold that it was erroneous, and that the first element of plain error review is satisfied.', 'general', 'Wheeler v. United States', 'https://www.courtlistener.com/opinion/2330422/', '2330422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that this is such a case.', 'general', 'Wheeler v. United States', 'https://www.courtlistener.com/opinion/2330422/', '2330422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instruction was erroneous, though the nature of the error lies somewhere in between the differing analyses provided by the parties.', 'jury_instruction', 'Wheeler v. United States', 'https://www.courtlistener.com/opinion/2330422/', '2330422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1038), we conclude that the error in this case affected the fundamental fairness and integrity of the jury trial, and as such, requires reversal.', 'general', 'Wheeler v. United States', 'https://www.courtlistener.com/opinion/2330422/', '2330422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has shown a plain error which justifies reversal on appeal.', 'general', 'Wheeler v. United States', 'https://www.courtlistener.com/opinion/2330422/', '2330422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in the text, we conclude that appellant has met the burden of showing prejudice to substantial rights.', 'general', 'Wheeler v. United States', 'https://www.courtlistener.com/opinion/2330422/', '2330422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'case, nor do we need to consider whether the “no duty” instruction by itself so prejudiced appellant as to require reversal because, as we discuss in the next section, we reverse the weapons conviction on the basis of another but, on the facts of this case, closely related erroneous instruction.', 'general', 'Wheeler v. United States', 'https://www.courtlistener.com/opinion/2330422/', '2330422') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this case satisfies the criteria of Rule 3(c) in that the State asserts that the sentencing in this case constitutes an error that has been committed to the prejudice of the State and that the correct and uniform administration of criminal law requires review by this court.', 'sentencing', 'State v. Sola', 'https://www.courtlistener.com/opinion/2331819/', '2331819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the circuit court in Rogers and remanded the case because no proof of the dates of arrest were in the record.', 'general', 'State v. Sola', 'https://www.courtlistener.com/opinion/2331819/', '2331819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court and remand for further proceedings.', 'general', 'State v. Sola', 'https://www.courtlistener.com/opinion/2331819/', '2331819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant’s right to challenge a prior conviction that the State intends to use to enhance a sentence is not limited solely to a claim that the conviction was obtained in violation of right to counsel.', 'sentencing', 'State v. Boskind', 'https://www.courtlistener.com/opinion/2332901/', '2332901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant’s collateral challenge to a prior conviction upon which the State relies to enhance a sentence is not limited solely to claims of invalidity based upon a violation of the right to counsel.', 'sentencing', 'State v. Boskind', 'https://www.courtlistener.com/opinion/2332901/', '2332901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the enhanced sentences imposed upon the respective defendants and hold that defendants, should they challenge convictions on the basis of a claim that the trial court did not comply with V.', 'sentencing', 'State v. Boskind', 'https://www.courtlistener.com/opinion/2332901/', '2332901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In fact, we held that the defendant could be required to give exactly such evidence in Brown, 165 Vt.', 'general', 'State v. Boskind', 'https://www.courtlistener.com/opinion/2332901/', '2332901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such registration is required.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/2333002/', '2333002') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is only one reasonable interpretation of this statute —• that the Legislature intended to mandate defendants convicted of a sex offense, pursuant to a deferred sentence, to register as a sex offender — and without an indicia of ambiguity, we need not adopt defendants’ proposed construction.', 'sentencing', 'State v. Thompson', 'https://www.courtlistener.com/opinion/2333002/', '2333002') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that pursuant to N.', 'general', 'State v. Gelman', 'https://www.courtlistener.com/opinion/2335613/', '2335613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Appellate Division, reinstate the trial court’s dismissal of the indictment, and remand for proceedings consistent with this opinion.', 'dismissal', 'State v. Gelman', 'https://www.courtlistener.com/opinion/2335613/', '2335613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the statute requires only knowledge of the material’s character and content, and not knowledge of its legal status as obscene, we hold that the evidence is legally sufficient.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that under section 43.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewed in the light most favorable to the verdict, we hold that a reasonable jury could have found that the appellant had knowledge of the videotape’s character and content.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Court of Appeals correctly found no error by the trial court in excluding the proffered internet images from the library.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this evidence was sufficient to show circumstantially that the defendant had knowledge of the character and content of the obscene material.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we held that the defendant had knowledge of the character and content of the obscene material, we did not expressly deal with the issue of whether a defendant must know that what he promotes is legally obscene or the constitutional issues now raised by the appellant.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court abused its discretion by excluding the other comparable material because the excluded material was more akin to the allegedly obscene materials in the case.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the trial court erred in excluding nine magazines and one film after admitting twenty-nine other magazines, one other film, and a book.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found that the evidence was legally sufficient to support the conviction, and having further found no error in excluding the proffered internet evidence, we affirm the Court of Appeals’s judgment.', 'general', 'Burden v. State', 'https://www.courtlistener.com/opinion/2336088/', '2336088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'when we held that: “[T]he ‘very narrow exception’ created in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the motions court erred in dismissing Fingerhut’s wrongful discharge claim because, under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking these factual allegations as true, as we must in this Rule 12(b)(6) case, we conclude that at this stage of the litigation the complaint sufficiently alleges Finger-hut engaged in investigative police work, during and after the alleged bribe, by making extra copies of the videotape, contacting the Metropolitan Police Department and the FBI to report the bribe, providing a copy of the videotape to the FBI, and responding to inquiries from the FBI.', 'general', 'Fingerhut v. Children''s National Medical Center', 'https://www.courtlistener.com/opinion/2336275/', '2336275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Finger-hut has made the requisite allegations under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand the case with instructions to reinstate Fingerhut’s wrongful discharge claim.', 'general', 'Fingerhut v. Children''s National Medical Center', 'https://www.courtlistener.com/opinion/2336275/', '2336275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the foregoing reasons we reverse the judgment of the trial court and remand this case with instructions to reinstate Fingerhut’s wrongful discharge claim.', 'general', 'Fingerhut v. Children''s National Medical Center', 'https://www.courtlistener.com/opinion/2336275/', '2336275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a case involving simultaneous representation, we held that a conflict of interest existed where an attorney represented a defendant who had information that could be used against another client in an unrelated ongoing criminal matter and might plausibly be useful as a “bargaining chip” for defendant but the lawyer did not make such an offer to the government.', 'general', 'Veney v. United States', 'https://www.courtlistener.com/opinion/2336415/', '2336415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though we conclude that Ve-ney has not established an actual conflict of interest, we will address the second prong of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all of Veney’s arguments, we conclude that he has faded to show that any conflict of interest actually affected Statham’s performance.', 'general', 'Veney v. United States', 'https://www.courtlistener.com/opinion/2336415/', '2336415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Veney’s convictions, but remand the case in part for resentencing.', 'sentencing', 'Veney v. United States', 'https://www.courtlistener.com/opinion/2336415/', '2336415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that police officers are absolutely immune under N.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whatever the relevance of those Motor Vehicle statutory provisions, we hold that they do not affect the immunity conferred on police officers by the Act, specifically by section 5-2b(2), as we have construed it.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That may not be the “plain meaning” of the section, but given its history, its apparent purpose, and the absence of any indication of a contrary intent, we conclude that the statute should be so construed.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not have to grapple with these questions, including whether Roll conferred a common law immunity preserved by the Act, because we find that section 5-2b(2) confers absolute immunity, except where the police officer engages in willful misconduct.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Appellate Division.', 'general', 'Tice v. Cramer', 'https://www.courtlistener.com/opinion/2337042/', '2337042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '23, 2001), this Court held that even if the seizure of the defendant was unconstitutional, the police had probable cause to arrest him for tampering with evidence when he raised his closed hand to his mouth in an attempt to swallow something after an officer told him to stop.', 'probable_cause', 'State v. Abernathy', 'https://www.courtlistener.com/opinion/2341016/', '2341016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the affidavit upon which the judge relied in issuing the search warrant was not defective.', 'general', 'State v. Abernathy', 'https://www.courtlistener.com/opinion/2341016/', '2341016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'State v. Abernathy', 'https://www.courtlistener.com/opinion/2341016/', '2341016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While at the time of the issuance of the arrest warrant the clerk was not statutorily defined as a “judicial officer” or “magistrate”, in felony cases, we hold that the clerk was neutral, detached and capable of the probable cause determination required of him in the issuance of the warrant by reason of the information issued by the state’s attorney on his oath of office.', 'probable_cause', 'Woodmansee v. Smith', 'https://www.courtlistener.com/opinion/2341711/', '2341711') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the totality of the circumstances of this case, then, we hold that the police had “specific and articulable facts which, taken together with rational inferences from those facts, reasonably warrant[ed][the] intrusion” of an investigative stop.', 'general', 'Plummer v. United States', 'https://www.courtlistener.com/opinion/2345263/', '2345263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that D.', 'general', 'Plummer v. United States', 'https://www.courtlistener.com/opinion/2345263/', '2345263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Mr.', 'general', 'Plummer v. United States', 'https://www.courtlistener.com/opinion/2345263/', '2345263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although an anonymous tip was involved in the case before us, we conclude that under the totality of the circumstances,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that Mr.', 'general', 'Plummer v. United States', 'https://www.courtlistener.com/opinion/2345263/', '2345263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that under our State Constitution, law enforcement officers cannot request consent to search a disabled vehicle on the shoulder of a roadway unless they have reasonable and articulable suspicion to believe that evidence of criminal wrongdoing will be discovered in the vehicle.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 798 (2002), we held that a police officer may not ask for consent to search a lawfully stopped vehicle or its occupants unless the officer has “a reasonable and articulable suspicion” that the occupants are engaged in criminal wrongdoing.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 66 (1975), we held that Article I, Paragraph 7 of the New Jersey Constitution, which protects people within this State from “unreasonable searches,”8 requires the State to prove, as a prerequisite to a lawful consent search, that a *241person have knowledge of his right to refuse to give consent.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in Carty, supra, we held that law enforcement officers are required to have a reasonable and articulable suspicion of criminal activity before requesting consent to search a car stopped for a motor vehicle infraction.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under our deferential standard of appellate review, we conclude that there was sufficient credible evidence in the record to support the motion judge’s findings that the troopers engaged in an unconstitutional investigatory detention and search of the Lincoln Town Car and individual defendants.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in the absence of a showing by the prosecutor under Criminal Rule 16(d)(6), the court should have allowed discovery of the report.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court should have allowed discovery of the report brought in by the prosecutor.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a finding that the victim was particularly vulnerable under AS 12.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the finding of vulnerability in this case was based solely upon an environmental factor, we hold that the court erred in concluding that the aggravator in 12.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that accepting the defense stipulation would have been the preferable procedure, we conclude that any error in allowing the testimony on how the photograph was obtained did not appreciably effect the jury’s verdict and was harmless error.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction, but find it necessary to remand for further sentencing proceedings.', 'sentencing', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Trott was not experiencing a restraint “other than incarceration or probation, imposed as a result of the sentence for the criminal judgment which is challenged” within the meaning of 15 M.', 'sentencing', 'LOI VAN NGO v. State', 'https://www.courtlistener.com/opinion/2356024/', '2356024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1034, 1037, we held that Trott’s sentence to time previously served, imposed without any additional term of probation or other restriction on the individual, was the “functional equivalent” of a “sentence of unconditional discharge resulting from a criminal judgment, for a period of 2 years following the date of sentence” within the meaning of section 2124(1)(C).', 'sentencing', 'LOI VAN NGO v. State', 'https://www.courtlistener.com/opinion/2356024/', '2356024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'LOI VAN NGO v. State', 'https://www.courtlistener.com/opinion/2356024/', '2356024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the judgment, holding that the District Court lacked jurisdiction because M.', 'general', 'LOI VAN NGO v. State', 'https://www.courtlistener.com/opinion/2356024/', '2356024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*649We hold that the court of appeals applied the correct legal standard in determining whether the evidence “raised” the “Good Samaritan” defense in this case.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that the trial court did not err in refusing to submit the defensive instruction to the jury.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As far back as 1937, we held that “[cjourts are only required to submit [defensive] theories of cases when same are supported by some testimony of sufficient cogence and substance to make it appear, at least with some degree of likelihood, that there could be a finding by the jury in response to such suggested issue.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” 31 We held that Young himself was not entitled to a necessity instruction because he merely “argued he did not commit the offense because he did not have the requisite intent and he did not perform the actions the State alleged.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”32 Similarly, in Ex parte Nailor, we held that the defendant was not entitled to a jury instruction on self defense because his defensive evidence did not show confession and avoidance, but only a lack of the required culpable act and mens rea.', 'jury_instruction', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, albeit for reasons somewhat different than those expressed by the court of appeals in its opinion below, we affirm its judgment affirming the judgment of the trial court.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), where we held that even though Kentucky does not have a statute of limitations for felonies, a due process violation for pre-indictment delay will only result “where there is both substantial prejudice and an intentional delay to gain advantage.', 'general', 'Shane v. Commonwealth', 'https://www.courtlistener.com/opinion/2356861/', '2356861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Morgan, this Court held that the trial court’s error in not properly striking a juror for cause was harmless (even though the defendant therein had to exercise a peremptory challenge to remove a biased juror), because no unqualified juror sat on his case.', 'general', 'Shane v. Commonwealth', 'https://www.courtlistener.com/opinion/2356861/', '2356861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the town clerk’s decision to replace, or not to replace, the previously removed handrail was not a discretionary decision.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To support this conclusion, we held that “[in] cases where the questioned conduct has little or no purely governmental content but instead resembles decisions or activities carried on by people generally, there is an objective standard for judgment by the courts and the doctrine of discretionary immunity does not bar the action.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 44] We conclude that any inference that the lack of an edge fine was an actual cause of the accident would amount to nothing more than speculation on the part of the jury.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 45] For the foregoing reasons, we conclude that MDOT was entitled to judgment as a matter of law in its favor.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Darling, we found that the commissioner and superintendent of a state mental health facility were entitled to discretionary function immunity from claims that they “negligently devised and oversaw [the facility’s] policies governing the commitment and release of patients.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit judge did not abuse his discretion in denying the motion for a mistrial.', 'mistrial', 'Meadows v. State', 'https://www.courtlistener.com/opinion/2358082/', '2358082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Meadows’s arguments are without merit, and we affirm.', 'general', 'Meadows v. State', 'https://www.courtlistener.com/opinion/2358082/', '2358082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm holding that at the conclusion of the statutory 90 day suspension period, the appellant’s failure to pay the $100 fee effectively rendered her status as one driving without a license.', 'general', 'Allen v. State', 'https://www.courtlistener.com/opinion/2358534/', '2358534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the forgoing reasons, we affirm the Court of Appeals.', 'general', 'Allen v. State', 'https://www.courtlistener.com/opinion/2358534/', '2358534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such an interpretation is neither natural nor necessary.', 'general', 'Tillman v. United States', 'https://www.courtlistener.com/opinion/2359553/', '2359553') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction.', 'general', 'Tillman v. United States', 'https://www.courtlistener.com/opinion/2359553/', '2359553') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*46From the foregoing, we hold that the Commonwealth has sustained its burden of proving, beyond a reasonable doubt, the existence of the aggravating circumstance of “killing a prosecution witness to a murder or other felony committed by the defendant .', 'general', 'Commonwealth v. Zettlemoyer', 'https://www.courtlistener.com/opinion/2367165/', '2367165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the death penalty is not “cruel punishment” within the proscription of Art.', 'general', 'Commonwealth v. Zettlemoyer', 'https://www.courtlistener.com/opinion/2367165/', '2367165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this Court held, based upon Furman and the 1976 quintet of same-day United States Supreme Court decisions,10 that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 For the reasons stated herein, we affirm appellant’s conviction for murder of the first degree, find the sentencing procedures to be valid under both the federal and state constitutions, and uphold the sentence of death.', 'sentencing', 'Commonwealth v. Zettlemoyer', 'https://www.courtlistener.com/opinion/2367165/', '2367165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the brief counsel presently submitted was insufficient.', 'general', 'Commonwealth v. Santiago', 'https://www.courtlistener.com/opinion/2367603/', '2367603') ON CONFLICT DO NOTHING;
