INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Article 46.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the voir dire, we hold that the record supports the trial court’s implicit finding that Blake was capable of discarding any preconceived conclusions he may have had and would follow the law as given to him by the court.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err by overruling appellant’s motion to suppress and admitting his confessions into evidence.', 'suppression', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not err in admitting the exhibits.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that appellant’s point of error 30 is without merit and is overruled.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the deceased’s statement to Peters was admissible as a spontaneous exclamation.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that the defendant’s mother''s mental health records were admissible where defendant was attempting to show that his childhood was unstable because his mother was hospitalized for mental problems for years and, as a result, the children were sent to live with various relatives.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In appellant’s prior case, this Court held that, although a defendant does have the statutory right to have the issue of voluntariness submitted to the jury, he is not entitled to have it resubmitted at the penalty phase when such issues have already been submitted at guilt/innocence.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we conclude that appellant has failed to show that publicity created a prejudice so great as to prevent a fair trial.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of each exhibit, we conclude that any objectionable hearsay seems to involve appellant’s disciplinary problems as a youth, his activities concerning arson, his previous rape conviction, and his alleged homosexuality.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the holding.', 'general', 'Bates v. Bates', 'https://www.courtlistener.com/opinion/2376259/', '2376259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because this court holds the Domestic Abuse Act unconstitutional, this subject matter appears destined for the General Assembly once again.', 'general', 'Bates v. Bates', 'https://www.courtlistener.com/opinion/2376259/', '2376259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the circumstances of this case, we hold that such a special relationship came into being, under a statute enacted in 1977, when a child abuse report was filed with the government agency established by that statute for the protection of abused children.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in granting that motion.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the District of Columbia, however, we hold that when CPS received a report that the two Roddy children, who were specifically and individually identified, were being abused by their father, the Child Abuse Prevention Act created a special relationship between the District and the two children.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'District of Columbia, supra, this court held that when the District of Columbia is sued for failure to provide public services, its duty of care is “owed .', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reading Platt and Morgan together, we conclude that there are at least two ways to demonstrate the existence of a “special relationship”6 between the city and the injured party which would justify reliance by the injured party on the city’s representations.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that appellants presented enough evidence to raise a material issue of fact and thereby defeat the District’s motion for summary judgment.', 'general', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s dismissal of the complaint with respect to Marion Barry, the Mayor of the District of Columbia, and Regina Barnard, the chief of CPS.', 'dismissal', 'Turner v. District of Columbia', 'https://www.courtlistener.com/opinion/2377127/', '2377127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and affirm the trial court’s judgment.', 'general', 'Posey v. State', 'https://www.courtlistener.com/opinion/2377590/', '2377590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the principal issue which Hunter presents for our consideration was not preserved in the trial court, and fashion our review accordingly.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain error standard applies.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Hunter’s conviction.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Keeping in mind the trial court’s role in credibility findings, and after reviewing the trial record and the § 23-110 hearing transcript, we conclude that the findings in the trial court’s lengthy and detailed memorandum are sufficiently supported by evidence in the record.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that in order for defense counsel to have argued any of those defenses (including those incorporating Dr.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that her testimony was sufficient for a reasonable juror reasonably to find that appellant had committed rape while armed.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, all convictions are affirmed, except the conviction for assault with a dangerous weapon (see supra note 2), which we reverse and remand for entry of an order of dismissal.', 'dismissal', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 Thus, we affirm the conviction of burglary.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agreed with the government that there was enough evidence to infer the defendant entered the home while armed with a dangerous weapon, and that the evidence “might support an inference that he intended to use the weapon if somebody attempted to interfere with his taking of property,” we concluded that a burglary conviction “may not rest on such an ‘if’.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in a case where the evidence showed that two defendants engaged in surreptitious behavior before breaking into a basement and then left without taking anything — according to the government, because there was nothing in the basement “both small and valuable enough to steal” — we concluded that the evidence was insufficient to sustain a burglary conviction.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient inconsistency between that omission and her testimony at trial to make it permissible to allow the jury to determine its significance.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that because the appellant had “made to the police a general denial of involvement with and knowledge of the crime but [had] made no statement concerning his whereabouts at the time during *153which the crime was committed,” the government “failed to establish a threshold inconsistency between appellant’s prior statement at the police station and his later alibi defense at trial.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we hold that the omission from the charge does not warrant reversal.', 'general', 'State v. Roy', 'https://www.courtlistener.com/opinion/2387891/', '2387891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that 23 V.', 'general', 'State v. Roy', 'https://www.courtlistener.com/opinion/2387891/', '2387891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a defendant’s right to a speedy trial was not violated even though more than six months elapsed between arraignment and trial and defendant was in jail for the entire time.', 'general', 'State v. Roy', 'https://www.courtlistener.com/opinion/2387891/', '2387891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the charge of simple assault on a police officer included as an element that the defendant knew or had good reason to believe that the victim was a law enforcement officer.', 'general', 'State v. Roy', 'https://www.courtlistener.com/opinion/2387891/', '2387891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that general intent to operate a vehicle without the owner’s consent is an element of the crime of operating without the owner’s consent.', 'general', 'State v. Roy', 'https://www.courtlistener.com/opinion/2387891/', '2387891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this case is governed by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the conviction despite the fact that the charge to the jury, over the objection of the defendant, failed to clearly specify this element.', 'general', 'State v. Roy', 'https://www.courtlistener.com/opinion/2387891/', '2387891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm the denial of access to the information sought by the defense based on the facts and circumstances of this particular case.', 'general', 'State v. Roy', 'https://www.courtlistener.com/opinion/2387891/', '2387891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we hold that the PCRA court erred in dismissing Williams’ twelfth ground for relief without conducting a factual hearing.', 'dismissal', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2395763/', '2395763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kimball, this Court held that the last of these elements, the PCRA''s prejudice requirement, although framed in different terms, is equivalent to the prejudice standard employed in adjudicating a claim of ineffectiveness on direct appeal.', 'ineffective_assistance', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2395763/', '2395763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since this would be inconsistent with our precedent, we find that the PCRA court abused its discretion not only in failing to make an independent credibility determination, but also in adopting reasons in support of its decision that were insufficient on their face.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2395763/', '2395763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, and remand for limited further proceedings.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2395763/', '2395763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, if a probation term provides for warrantless searches and the terms of probation are narrowly tailored to fit the circumstances of the individual probationer, the Griffin “reasonable grounds” standard strikes the proper balance between probationer privacy rights and public protection concerns.', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a probation warrant is not the type of contract contemplated by § 9310(a)(2).', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court did not err when it decided not to order a third competency hearing prior to commencing revocation proceedings.', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we are mindful that limits must be placed on such searches and that consent to future searches “as required” does not permit unfettered intrusions into the private lives of probationers, we find that the “reasonable grounds” standard establishes the proper safeguard.', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 771, this court held that the writ of habeas corpus may not be used as a writ of error to obtain a reversal of a conviction, and that after a judgment of conviction and a commitment pursuant to the conviction, the only material fact to be ascertained upon a petition for a writ of habeas corpus is the existence of a judgment of conviction by a court of competent jurisdiction and a valid commitment of the prisoner to enforce the sentence.', 'sentencing', 'Skinner v. State', 'https://www.courtlistener.com/opinion/6678583/', '6678583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, reaffirming our decision that the matter of parole eligibility, including mandatory mínimums, is not a proper consideration for the jury’s sentencing deliberations, we refer appellant to our holding in Smith and Will-ingham and, we hold that the trial court’s refusal to charge the jury on the effects of parole in this ease was not error.', 'sentencing', 'Lawton v. State', 'https://www.courtlistener.com/opinion/2405700/', '2405700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the entry of an order, along with the recitations indicating that there had been some adversarial hearing on the matter from which the court made conclusions of fact and law, constituted a proceeding under Article 28.', 'general', 'Lawton v. State', 'https://www.courtlistener.com/opinion/2405700/', '2405700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we held that because the record was devoid of any evidence that some type of adversarial hearing was held which led to findings-of-fact and conclusions-of-law supporting the granting or overruling of a pleading, it contained no evidence of a proceeding within the meaning of Article 28.', 'plea', 'Lawton v. State', 'https://www.courtlistener.com/opinion/2405700/', '2405700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 520 (1990) we held that the prohibition against informing the jury of the effects of a hung jury is not unconstitutional.', 'general', 'Lawton v. State', 'https://www.courtlistener.com/opinion/2405700/', '2405700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '08(a)(2) excludes burglary of a vehicle, upon careful review of the entire record, we find that appellant presents no reversible error.', 'general', 'Lawton v. State', 'https://www.courtlistener.com/opinion/2405700/', '2405700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Lawton v. State', 'https://www.courtlistener.com/opinion/2405700/', '2405700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it can not.', 'general', 'Hudson v. Commonwealth', 'https://www.courtlistener.com/opinion/2409527/', '2409527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thereafter, we held that severance was appropriate where the State would have been unable to introduce a statement by the co-defendant at a joint trial because it could not be redacted, without substantially altering its meaning, to meet the requirements of Bruton v.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the verdict was facially void because it in no way complied with the requirement of the determinate sentence law in effect at the time of sentencing.', 'sentencing', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Middlebrooks a majority of this Court held that, when a defendant is convicted of first-degree murder solely on the basis that the murder was committed during the course of a felony, then the felony-murder aggravating circumstance does not narrow the class of death eligible defendants because it duplicates exactly the elements of the offense supporting the conviction that made the defendant death-eligible.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under the present record, the defendant has failed to show that he was prejudiced by the trial court’s granting the severance.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that neither the state nor the federal constitution prohibited admission of Stephenson’s confession.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree that courts should give a broad interpretation to a suspect’s request for counsel, we conclude that the defendant’s question herein constituted an equivocal invocation of the right to counsel that limited further interrogation to questions clarifying his desire for an attorney.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the facts in this record in accordance with the analysis utilized in Street, we conclude that the defendant’s Sixth Amendment right of confrontation was not violated.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that there is no statutory, common-law, or constitutional right to allocution in a capital case.', 'general', 'State v. Stephenson', 'https://www.courtlistener.com/opinion/2410270/', '2410270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the opinion offered by the officer does not meet the requirements needed to qualify it as a lay opinion, and because we conclude that permitting the officer to testify about his opinion invaded the fact-finding province of the jury, we reverse defendant’s conviction and remand for further proceedings.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 702, we concluded that an expert could testify about matters including the acquisition of drugs in New York City, the comparatively higher street value of those drugs if sold here, the purpose of using plastic bags, and “the reasons why drug dealers use juveniles as ‘mules’ to carry drugs on their person in the course of transport.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More recently, we concluded that in the context of a transaction in which defendant did not personally hand over the drugs or accept payment, an expert may be utilized to explain to the jury how his actions fit into the scheme of a “street-level distribution network.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was no need for an expert “to explain the straightforward manner in which the transactions at issue [in those cases] took place,” because they involved only a defendant who was “observed directly handing something to the alleged purchaser and receiving what appeared to be payment in return.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nesbitt, we concluded that such testimony sets forth facts that are not so outside the ken of jurors that they need an expert to spell out for them whether that defendant engaged in a criminal transaction and that offering an expert in those circumstances would be improper.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed defendant’s conviction, concluding that the expert’s inappropriate use of the phrase “constructive possession,” a legal term that “mimicked the language of the statute,” violated Odom’s directive that experts avoid the “precise terminology, and particularly the legalese, of an applicable criminal statute.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 440 (1986), we held that, under Ark.', 'general', 'Ricks v. State', 'https://www.courtlistener.com/opinion/2433035/', '2433035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Neither point has merit, and we affirm the trial court’s judgment.', 'general', 'Ricks v. State', 'https://www.courtlistener.com/opinion/2433035/', '2433035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2437831/', '2437831') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bailey’s direct various fighting words to the officers, when considering his surrounding conduct, such as standing up and grabbing Officer Randle’s arm, we conclude that he used these words “in a manner likely to provoke a violent or disorderly response” under § 5-71-207(a)(3).', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/2441447/', '2441447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion in refusing to allow Mr.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/2441447/', '2441447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm the trial court’s judgment.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/2441447/', '2441447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bailey’s speech with immediate violence, the First Amendment requires that we reverse the conviction for disorderly conduct.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/2441447/', '2441447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This case presents appropriate circumstances, and we hold that sufficient proof was presented to the trial court for a conviction of attempted fraudulent use of a credit card.', 'general', 'Davidson v. State', 'https://www.courtlistener.com/opinion/2445147/', '2445147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 19] For two reasons we conclude that the court abused its discretion when it sustained the State’s objection to Filler’s cross-examination of his wife as to what, if any, legal actions she took to obtain legal custody of the children.', 'general', 'State v. Filler', 'https://www.courtlistener.com/opinion/2446902/', '2446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that granting the motion for a new trial was appropriate on other grounds, we do not consider these arguments in this appeal.', 'general', 'State v. Filler', 'https://www.courtlistener.com/opinion/2446902/', '2446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that when the victim is the State’s primary witness against the defendant, “evidence tending to impeach [the victim’s] credibility ha[s] greatly enhanced probative value.', 'general', 'State v. Filler', 'https://www.courtlistener.com/opinion/2446902/', '2446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[t]he pecuniary interest and motivation of a complaining witness is a proper subject for jury consideration.', 'general', 'State v. Filler', 'https://www.courtlistener.com/opinion/2446902/', '2446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and remand for a new trial.', 'general', 'State v. Filler', 'https://www.courtlistener.com/opinion/2446902/', '2446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the officers arrested Schram for the misdemeanor of operating a motor vehicle while under the influence of alcohol or drugs, and it was undisputed that the police arrived at the scene only after Schram had exited the car and was no longer operating it, we held that “the arrest was invalid and the [evidence] taken after the arrest must be suppressed.', 'suppression', 'Enders v. District of Columbia', 'https://www.courtlistener.com/opinion/2447405/', '2447405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and concluding, “we held that evidence must be suppressed because in each case, although the arresting officer had probable cause, he lacked legal authority to make the arrest”).', 'suppression', 'Enders v. District of Columbia', 'https://www.courtlistener.com/opinion/2447405/', '2447405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987), we held that a letter to the Mayor’s office provided adequate notice under § 12-309 when it gave the District enough
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find no error in the sentencing court’s departure from the sentencing guidelines, and therefore, we affirm the Circuit Court’s denial of relief on the ineffective assistance of counsel claim.', 'sentencing', 'Martin v. State', 'https://www.courtlistener.com/opinion/2453207/', '2453207') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 489 (1973), we held that whenever an accused offers testimony that his confession was induced by violence, threats, coercion or offers of reward, the state has a burden to produce all material witnesses who were connected with the controverted confession or give an adequate explanation of their absence.', 'general', 'Foreman v. State', 'https://www.courtlistener.com/opinion/2454527/', '2454527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, although the trial court did not err in ruling Brooks was an unavailable witness, it did err in ruling her statement was admissible under Rule 804(b)(3) or Rule 804(b)(5).', 'general', 'Foreman v. State', 'https://www.courtlistener.com/opinion/2454527/', '2454527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial judge committed error by requiring the defendant to prove, as a prerequisite to judicial in camera inspection of the personnel file, that the file likely contained the sought-after evidence:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In other words, we held that the trial judge should have used the approach we adopted in Dana: the judge should have conducted an in camera inspection of the personnel file because, if the personnel file contained the sort of information described in the defendant''s motion, this information would have been relevant to the defendant''s guilt or innocence, not just relevant to impeachment of the witness''s general credibility or impeachment of the witness on collateral matters.', 'general', 'Booth v. State', 'https://www.courtlistener.com/opinion/2455189/', '2455189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Dana v.', 'general', 'Booth v. State', 'https://www.courtlistener.com/opinion/2455189/', '2455189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we conclude that the district court should have examined the personnel files in camera to see if the files contained citizen complaints of excessive force, disciplinary actions based on the use of excessive force, or training in the use of pepper spray.', 'general', 'Booth v. State', 'https://www.courtlistener.com/opinion/2455189/', '2455189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these factual assertions, and given Booth''s theory of defense at trial, we find that Booth satisfied the threshold requirement for an in camera inspection of Officer Griffith''s personnel file for prior complaints of excessive force or disciplinary actions based on the use of excessive *378foree.', 'general', 'Booth v. State', 'https://www.courtlistener.com/opinion/2455189/', '2455189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), we held that for offenses which neither expressly require, nor plainly dispense with a culpable mental state, an indictment which fails to specifically allege a mental state will be suffi*106cient so long as the mental state required can be logically inferred from the allegations in the indictment so as to satisfy constitutional and statutory requirements of notice and form.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), this Court held that to establish probable cause an affidavit must set forth facts from which a reasonable conclusion may be drawn that the evidence will be found in the place to be searched pursuant to the warrant.', 'probable_cause', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the previously explained reasons, we conclude that the jury instructions read as a whole were not preju-dicially erroneous;', 'jury_instruction', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Based upon this proof, we conclude that the evidence is sufficient to establish that the murder was especially heinous, atrocious, or cruel in that it involved serious physical abuse beyond that necessary to produce death.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying those rules to the facts of this case, we conclude that the Court of Criminal Appeals properly affirmed the trial court’s judgment denying the defendant’s motion to suppress.', 'suppression', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the nature of the crime and the defendant, we conclude that imposition of the death penalty for the cruel killing of this young child is not disproportionate to the penalty imposed in similar cases, and that this murder places Vann into the class of defendants for whom the death penalty is an appropriate punishment.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review, we conclude that the following cases in which the death penalty has been imposed have many similarities''with this ease.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s thorough instruction of the law was sufficient to counter the Defendant’s request for a specific instruction that the State’s case was based entirely upon circumstantial evidence.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*115In this case, we conclude that the trial court carefully and meticulously orchestrated the jury selection process to insure the Defendant a fair trial.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, as previously stated, we conclude that the trial court thoroughly discussed the presumption of innocence and the State’s burden of proof with each of the potential jurors.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), this Court held that trial courts are statutorily required to instruct juries on all lesser-included and “lesser-grade or class”1 offenses, if the evidence introduced at trial is legally sufficient- to support a conviction for the lesser offenses.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that there was no rational basis for a manslaughter instruction.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without reaching the issue of whether a rational basis exists, we hold that the appellant’s argument must fail.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that a fifteen-year old with an IQ of 74 and a second-grade reading level was capable of comprehending his Miranda rights and of waiving those rights.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Noble, we held that showing the accused a picture of the victim and telling him he would not pass a polygraph didn’t invalidate a confession.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, when a person under age eighteen is charged as an adult in circuit court, failure to obtain a parent’s signature on a waiver form does not render a confession inadmissible.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1022 (1983), we held that a defendant was not necessarily entitled to take the discovery depositions of state witnesses.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such a test could not be used to prove a person drove while intoxicated but could be used to prove that he did not.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is substantial evidence the appellant purposely aided and facilitated his accomplices in the commission of first-degree murder and therefore find sufficient evidence to support his conviction.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After an independent review of the foregoing factors, we conclude that the trial judge’s determination of voluntariness was correct.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we find that the trial court did not abuse its discretion in denying the new trial.', 'general', 'Misskelley v. State', 'https://www.courtlistener.com/opinion/2469499/', '2469499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 183, 185 (1976), this court held that under section 6 — 303, the elements of the offense are “(1) the act of driving a motor vehicle on the highways of this State, and (2) the fact of the revocation of the driver’s license or privilege.', 'general', 'People v. Close', 'https://www.courtlistener.com/opinion/2479519/', '2479519') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm the judgment of the appellate court.', 'general', 'People v. Close', 'https://www.courtlistener.com/opinion/2479519/', '2479519') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court reversing the trial court’s order granting defendant’s motion to quash arrest and suppress evidence and remanding for further proceedings.', 'suppression', 'People v. Close', 'https://www.courtlistener.com/opinion/2479519/', '2479519') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand with instructions.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/2481120/', '2481120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand with instructions to vacate Thomas''s conviction for invasion of privacy as a class A misdemeanor and, at the trial court''s option, to resume direct contempt proceedings 3 to address Thomas''s comment to Smith at the November 16, 2009 hearing.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/2481120/', '2481120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction unless "no reasonable fact-finder could find the elements of the crime proven beyond a reasonable doubt.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/2481120/', '2481120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the appellate court erred in reversing defendant’s conviction based on a violation of Supreme Court Rule 431(b).', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s violation of the amended version of Supreme Court Rule 431(b) in this case does not fall within the very limited category of structural errors and, thus, does not require automatic reversal of defendant’s conviction.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the language and history of the rule, we concluded that the trial court’s violation of Rule 431(b) did not rise to the level of structural error.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the appellate court’s judgment and affirm the judgment of the circuit court.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the foregoing reasons, we reverse the appellate court’s judgment reversing defendant’s conviction and remanding this matter for a new trial.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that such inquiry was required.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State proved an entry for purposes of the burglary statute.', 'general', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 261), we hold that the State proved that defendant Jones participated in the burglary of Little’s vehicle.', 'general', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 261), we conclude that an entry into the vehicle was proved.', 'general', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse the appellate court’s judgment in both cases and reinstate defendants’ convictions and sentences for burglary.', 'sentencing', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons stated, we reverse the judgment of the appellate court in Beauchamp’s case modifying the trial court’s judgment to reflect a conviction for theft, and reinstate Beauchamp’s conviction and sentence for burglary.', 'sentencing', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State proved an entry for purposes of the burglary statute.', 'general', 'People v. Beauchamp', 'https://www.courtlistener.com/opinion/2481950/', '2481950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude the trial court erred by determining that the magistrate did not have probable cause to issue the warrant, and therefore we reverse the order suppressing the evidence and remand for further proceedings.', 'suppression', 'State v. Exantus', 'https://www.courtlistener.com/opinion/2496955/', '2496955') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse, in part, the trial court’s order granting Exantus’ motion to suppress evidence obtained from the ion scan and remand for further proceedings.', 'suppression', 'State v. Exantus', 'https://www.courtlistener.com/opinion/2496955/', '2496955') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, without
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s order in all other respects.', 'general', 'State v. Exantus', 'https://www.courtlistener.com/opinion/2496955/', '2496955') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the Town’s failure to equip its patrol vehicles does not negate the application of the statutory exceptions in subsection (B).', 'general', 'Town of Mt. Pleasant v. Roberts', 'https://www.courtlistener.com/opinion/2506173/', '2506173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that dismissal is the appropriate sanction in the instant case as this was clearly intended by the Legislature and previously decided by this Court in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As for the circuit court’s appellate jurisdiction, we find that Roberts properly met the prerequisites of section 14-25-95.', 'general', 'Town of Mt. Pleasant v. Roberts', 'https://www.courtlistener.com/opinion/2506173/', '2506173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In so ruling, we found that any argument concerning the exceptions for noncompliance in section 56-5-2953(B) was not preserved as the circuit court had not ruled on this issue and the City of Rock Hill had not sought a post-judgment ruling regarding
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified.', 'general', 'Town of Mt. Pleasant v. Roberts', 'https://www.courtlistener.com/opinion/2506173/', '2506173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm as modified the decision of the circuit court judge.', 'general', 'Town of Mt. Pleasant v. Roberts', 'https://www.courtlistener.com/opinion/2506173/', '2506173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jackson, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, as to the description of the offense, HRS § 291E-61, which relates to operating a vehicle under the influence of an intoxicant, substantially reenacted HRS § 291-4.', 'general', 'State v. Domingues', 'https://www.courtlistener.com/opinion/2509316/', '2509316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a fact susceptible to jury determination is a predicate to the imposition of an enhanced sentence, the Hawai''i Constitution requires that such factual determinations be made by the trier of fact.', 'sentencing', 'State v. Domingues', 'https://www.courtlistener.com/opinion/2509316/', '2509316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 and we hold that the prosecution may proceed under the charged statute, no ex post facto problem arises.', 'general', 'State v. Domingues', 'https://www.courtlistener.com/opinion/2509316/', '2509316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we conclude that we must affirm the judgment of the Court of Appeal.', 'general', 'Aguilar v. Atlantic Richfield Co.', 'https://www.courtlistener.com/opinion/2514219/', '2514219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prosecution adduced sufficient evidence to sustain Valdivia’s convictions of the offenses of kidnapping and first degree terroristic threatening and that any misconduct in which the DPA engaged was harmless beyond a reasonable doubt.', 'general', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the prosecution adduced sufficient evidence to justify the jury’s verdict in this regard as well.', 'general', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that prosecution adduced substantial evidence from which a person of reasonable caution could conclude that Valdivia, in fact, uttered a “true threat.', 'general', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we cannot say that the failure of the circuit court to so instruct the jury in the present matter did not contribute to Valdivia’s conviction of first degree terror-istic threatening, we hold that this omission yields an alternative ground for remanding Valdivia’s first degree terroristic threatening conviction for a new trial.', 'general', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that this particular remark was harmless beyond a reasonable doubt.', 'general', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regarding the “blue wall of conduct” comment that, according to Valdivia, constitutes prosecutorial misconduct, we hold that it was not an improper assertion of personal opinion regarding Valdivia’s credibility.', 'general', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “the short answer” was relatively simple: “[A] statement that amount[s] to a threat to kill .', 'general', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that because (1) Chung repeatedly expressed his intention to shoot the principal at the school while displaying a firearm and ammunition, (2) his remarks were sufficiently and objectively alarming to impel a recipient to report them to the vice principal, and (8) his presence at the school was unauthorized at the time, Chung’s remarks constituted “true threats.', 'general', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this court held that the circuit court erred in dismissing terroristic threatening charges against Chung because the circuit court incorrectly concluded that his remarks were constitutionally protected speech.', 'dismissal', 'State v. Valdivia', 'https://www.courtlistener.com/opinion/2514209/', '2514209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Downing had no Fifth or Sixth Amendment right to counsel at the time of his interview with the police.', 'general', 'Downing v. State', 'https://www.courtlistener.com/opinion/2515779/', '2515779') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Downing v. State', 'https://www.courtlistener.com/opinion/2515779/', '2515779') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a fact susceptible to jury determination is a predicate to the imposition of an enhanced sentence, the Hawai''i Constitution requires that such factual determinations be made by the trier of fact.', 'sentencing', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 376 (“[B]ecause all of the essential elements of assault in the third degree were alleged in the oral charge and proven at trial, we hold that the appropriate remedy for Elliott’s post-conviction challenge to the defective charge is to remand the case for entry of judgment of conviction of assault in the third degree and for resentencing in accordance therewith.', 'sentencing', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we hold that: (1) the prosecution failed to offer a compelling justification to overrule Domingues;', 'general', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the jury, and not the sentencing judge, was required to make the factual finding that the police officer was on-duty when shot.', 'sentencing', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 901 (footnote omitted), this court held, inter alia, that (1) for purposes of enhanced sentences, “findings regarding (a) the age or handicapped status of the victim and (b) whether ‘[sjuch disability is known or reasonably should be known to the defendant’ entail ‘intrinsic’ facts[ ]” that are “inextricably enmeshed in the defendant’s actions in committing the offense chargedf,]” Tafoya, 91 Hawai''i at 271, 982 P.', 'sentencing', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Analyzing the language of the prosecution’s oral charge, we concluded that the assault against a police officer charge was fatally defective because it did not allege that the offense was committed against “a police officer who [was] engaged in the performance of duty[.', 'general', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we reversed Elliott’s convictions of the offenses of assault against a police officer and resisting arrest.', 'general', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On March 2Í, 2007, this court held oral argument.', 'general', 'State v. Kekuewa', 'https://www.courtlistener.com/opinion/2630647/', '2630647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the necessity defense does not apply to criminal offenses defined outside Title 13.', 'general', 'State v. Fell', 'https://www.courtlistener.com/opinion/2519807/', '2519807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 14 Because we conclude that the respondent judge erred in ruling that the necessity defense in § 13-417 applies to a DUI charge under Title 28, we reverse his order.', 'general', 'State v. Fell', 'https://www.courtlistener.com/opinion/2519807/', '2519807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we hold that applying ASORA to Doe burdens his fundamental liberty interests and right to procedural fairness arising out of the set-aside granted him in 1994, such that the state must establish a compelling governmental interest.', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that applying ASORA to a person whose conviction was set aside before ASORA became specifically applicable to convictions that were set aside violates the Alaska Constitution''s guarantee of due process.', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because ASORA compels affirmative post-discharge conduct under threat of prosecution, because this conduct is equivalent to that often required by criminal judgments, because this sort of conduct could not be compelled absent a criminal adjudication or its equivalent, because the conviction (since set aside) is the event that triggers these duties, and because the requirement impairs one''s post-set-aside freedom to be let alone, we conclude that it violates Doe''s liberty interests 75 to requi...', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given ASORA''s burden on Doe''s liberty interests and its interference with his settled expectations, we conclude that the Alaska Constitution''s guarantee of due process prevents the state from contradicting the judgment of the superior court and requiring Doe to satisfy ASORA.', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '085 before ASORA became specifically applicable to convictions that were set aside unconstitutionally interferes with the individual''s liberty interests and because the state has failed to establish that this application is justified by a compelling governmental interest, we REVERSE the judgment that upheld ASORA as applied to Doe and REMAND for entry of an order enjoining the state from publishing Doe''s registration information and requiring the state to return all information Doe provided w...', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court.', 'general', 'People v. Comage', 'https://www.courtlistener.com/opinion/2523452/', '2523452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'limited its holding as follows: “In the present case, we hold that the evidence of concealment was insufficient to sustain the convictions of obstruction of justice.', 'general', 'People v. Comage', 'https://www.courtlistener.com/opinion/2523452/', '2523452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that the order forms were objects or symbols of value because they caused Trooper Kaizer to receive items of value and created corresponding debt obligations in his name.', 'general', 'Trainor v. State', 'https://www.courtlistener.com/opinion/2523768/', '2523768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of these reasons, we conclude that the State presented sufficient evidence to support Trainor’s convictions of Class D felony counterfeiting.', 'general', 'Trainor v. State', 'https://www.courtlistener.com/opinion/2523768/', '2523768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Trainor v. State', 'https://www.courtlistener.com/opinion/2523768/', '2523768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing a trial court’s decision for an abuse of discretion, we reverse only where the decision is clearly against the logic and effect of the facts and circumstances.', 'general', 'Delagrange v. State', 'https://www.courtlistener.com/opinion/2529395/', '2529395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and remand.', 'general', 'Delagrange v. State', 'https://www.courtlistener.com/opinion/2529395/', '2529395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm the judgment of the trial court and remand for further proceedings.', 'general', 'Delagrange v. State', 'https://www.courtlistener.com/opinion/2529395/', '2529395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that although there is a mistake in the statute, it is clear that the legislature did not intend to elevate all driving while suspended offenses with prior convictions but rather only intended to elevate those offenses where the offender had a prior conviction within ten years of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the statute enforceable in its current form and Gearlds’ conduct is proscribed under either reading, we reverse the trial court and remand for further proceedings.', 'general', 'State v. Gearlds', 'https://www.courtlistener.com/opinion/2528170/', '2528170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the statute is enforceable in its current form, we reverse the trial court’s dismissal of the Class A misdemeanor charge against Gearlds and remand for further proceedings.', 'dismissal', 'State v. Gearlds', 'https://www.courtlistener.com/opinion/2528170/', '2528170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the statute in that case lacked a culpable mental state beyond both knowledge of the compartment’s capacity to conceal and an intent to conceal, we held that the statute “d[id] not contain a reasonable means of preventing the targeted conduct, and it therefore violate[d] due process.', 'general', 'People v. Madrigal', 'https://www.courtlistener.com/opinion/2530267/', '2530267') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In declaring the statute unconstitutional on its face, we held that it could not “withstand scrutiny under the rational basis test.', 'general', 'People v. Madrigal', 'https://www.courtlistener.com/opinion/2530267/', '2530267') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that precedent to this case, we conclude that defendant met her burden of showing that section 16G — 15(a)(7) is facially unconstitutional.', 'general', 'People v. Madrigal', 'https://www.courtlistener.com/opinion/2530267/', '2530267') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we find that a statute, such as section 16G— 15(a)(7), which criminalizes the use of mere names, or other commonly and publicly available information such as addresses and phone numbers, for the purpose of gaining access to innocent information about people without any criminal intent, purpose or knowledge is an invalid exercise of the police power and is not reasonably related to the purpose of the statute.', 'general', 'People v. Madrigal', 'https://www.courtlistener.com/opinion/2530267/', '2530267') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that “[i]n analogous cases, this court and courts in other jurisdictions have held that criminal statutes that potentially punish innocent conduct violate due process principles because they are not reasonably designed to achieve their purposes.', 'general', 'People v. Madrigal', 'https://www.courtlistener.com/opinion/2530267/', '2530267') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, based upon our review of the evidence as set forth in the record and as explained above, we conclude that sufficient evidence exists from which the trial court could find Bill-ingsley guilty beyond a reasonable doubt of driving while suspended as a class A misdemeanor within ten years of a similar prior infraction.', 'general', 'Billingsley v. State', 'https://www.courtlistener.com/opinion/2531239/', '2531239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Billingsley v. State', 'https://www.courtlistener.com/opinion/2531239/', '2531239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction unless “no reasonable fact-finder could find the elements of the crime proven beyond a reasonable doubt.', 'general', 'Billingsley v. State', 'https://www.courtlistener.com/opinion/2531239/', '2531239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Billingsley’s conviction for driving while suspended as a class A misdemeanor.', 'general', 'Billingsley v. State', 'https://www.courtlistener.com/opinion/2531239/', '2531239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, although the circumstances show that appellant probably intended to enter the Alfred house with intent to commit theft, his behavior after removal of the screen was sufficiently inexplicable that reasonable doubt remains as to what his specific criminal intentions actually were.', 'general', 'Gear v. State', 'https://www.courtlistener.com/opinion/2538612/', '2538612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We conclude that, although the circumstances show that appellant probably intended to enter the Alfred house with intent to commit theft, his behavior after removal of the screen was sufficiently inexplicable that reasonable doubt remains as to what his specific criminal intentions actually were.', 'general', 'Gear v. State', 'https://www.courtlistener.com/opinion/2538612/', '2538612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In contrast to the ICA’s opinion, we hold that, inasmuch as Locquiao adduced sufficient evidence at trial to warrant an ignorance-or-mistake-of-fact instruction, the circuit court’s refusal so to instruct was not harmless beyond a reasonable doubt.', 'general', 'State v. Locquiao', 'https://www.courtlistener.com/opinion/2543862/', '2543862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on the totality of the foregoing circumstances, we hold that the ICA did not gravely err in holding that Kim was acting as a private citizen in connection with the events with which Locquiao was charged and that, therefore, his search and/or seizure of Locquiao was not constrained by the fourth amendment to the United States Constitution and article 1, section 7 of the Hawai''i Constitution, see supra note 6.', 'search_seizure', 'State v. Locquiao', 'https://www.courtlistener.com/opinion/2543862/', '2543862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the plaintiffs’ appeal, we hold that the circuit court erred in apportioning liability between the DOE and Norton and, therefore, that the DOE is liable to the plaintiffs for the full extent of their damages.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing discussion, we hold that, where a plaintiffs negligence claim against the State seeks to hold the State vicariously liable for a state employee’s “assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights” under the doctrine of respondeat superior, the State is, pursuant to HRS § 662-15(4), immune from the plaintiffs claim.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the duty of care that the DOE owes to students and them parents is, on a general level, a duty to take whatever precautions are necessary reasonably to ensure the safety and welfare of the children entrusted to its custody and control against harms that the DOE anticipates, or reasonably should anticipate.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'as she claimed, we hold that the DOE should have reasonably anticipated that Noi''ton posed a potential threat to students and, therefore, that it was reasonably foreseeable that he would molest other students.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we hold that it was unreasonable at that point for the DOE to have failed specifically to supervise Norton and to restrict him from issuing hall passes and “hugging” students.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not clearly err in finding that the DOE’s negligence legally caused the plaintiffs’ various psychological injuries.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Jane Roes, for example, we held that “exposure to HIV-positive blood ‘involve[s] circumstances which guarantee the genuineness and seriousness of the claim’ ” (quoting Rodrigues, 52 Haw.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Miller, this court held that the State “has a duty of reasonably supervising the public school students of Hawai''i during their required attendance and presence at school and while the students are leaving school immediately after the school day is over.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this court held that rules and regulations that the DOE had adopted “pro-vid[ed] the necessary guidelines and requirements for the personnel of the State educational system to perform its supervisory duties.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Absent evidence that the area in which Miller was injured “was dangerous in character or likely to be dangerous because of known deviant conduct of students or of others,” thereby “requiring specific supervision,” this court held that the school was not subject to a duty to single out either the area or Yoshimoto.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 519-20 (“We hold that serious mental distress may be found where a reasonable [person], normally constituted, would be unable to adequately cope with the mental stress engendered by the circumstances of the case”).', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In FHP, this court held that an exception to the “physical injury” rule was created when airline employees unknowingly handled human immunodeficiency virus (HIV) contaminated blood.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, this court held that the “plain and unambiguous language of the 1939 version [of the UCATA] abrogates the common law rule that the release of an employee automatically releases his/her vicariously liable employer.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the chancellor committed manifest error in not making this necessary finding for a civil-contempt citation.', 'general', 'Hanshaw v. Hanshaw', 'https://www.courtlistener.com/opinion/2544830/', '2544830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Shirley did not receive proper notice or an opportunity to defend against the charges in a contempt hearing, we reverse the chancellor’s contempt finding and subsequent denial of Shirley’s motion to reconsider.', 'general', 'Hanshaw v. Hanshaw', 'https://www.courtlistener.com/opinion/2544830/', '2544830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals rendering judgment in Shirley’s favor.', 'general', 'Hanshaw v. Hanshaw', 'https://www.courtlistener.com/opinion/2544830/', '2544830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that a police officer’s repeated requests that appellant stop and talk to him, absent any reasonable suspicion of criminal conduct, constituted a violation of appellant’s Fourth Amendment rights which led to the evidence on which he was convicted, we reverse his conviction.', 'search_seizure', 'State v. Wyman', 'https://www.courtlistener.com/opinion/2544842/', '2544842') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And, because the weapon seized was the basis of the prohibited possessor charge, we reverse appellant’s prohibited possessor conviction in CR 99-020.', 'general', 'State v. Wyman', 'https://www.courtlistener.com/opinion/2544842/', '2544842') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whether or not Julio’s speech was protected, we conclude that, as a whole, his conduct did not amount to seriously disruptive behavior.', 'general', 'In Re JULIO L', 'https://www.courtlistener.com/opinion/2544958/', '2544958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 In Elias, we held that when a trial court issues findings of fact but does not make a fact finding on a pertinent issue, an appellate court must assume that the trial court made no finding at all on the matter.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 Thus, in Smith, an indecent exposure case, we held that the State was required to plead the circumstances under which the defendant exposed himself — such as “in a public place” — to indicate why his otherwise lawful act was reckless.', 'plea', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/2546778/', '2546778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”21 Therefore, we affirm the lower court’s judgment which had upheld the trial judge’s ruling.', 'general', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/2546778/', '2546778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 3 We hold that a trial on the charge of violating section 28-3473(B) (driving on a DUI suspended driver’s license) is not jury eligible.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/2570469/', '2570469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 29 Applying this test to the violation of section 28-3473(B) (driving on a license suspended for violation of the DUI statute), we hold that the offense is not linked to any which would have been jury eligible at common law, that penalties available for the offense do not rise to the level of seriousness as would mandate a jury trial, and that the offense does not implicate the moral element because it is neither a crime of moral turpitude nor a crime which may result in grave consequences.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/2570469/', '2570469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because we must give meaning to the word “intended” in the facilitation portion of § 13-1805(1), Superior Court, we conclude that, before a person may be convicted of the class four offense of “facilitated shoplifting,” the state must not only prove the elements of shoplifting, as defined by § 13-1805(A), but the additional element that the person entered the store with something he or she intended to facilitate the shoplifting.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2571758/', '2571758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, although we agree with Brown that the facilitation portion of § 13-1805(1) creates a greater offense to the lesser offense of shoplifting under § 13-1805(A) and that he was entitled to the lesser-included offense instruction prescribed by LeBlanc, we conclude that the trial court’s instruction and interrogatory neither prejudiced Brown nor resulted in reversible error.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2571758/', '2571758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm Brown’s conviction and sentence.', 'sentencing', 'State v. Brown', 'https://www.courtlistener.com/opinion/2571758/', '2571758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that such certificates are testimonial for purposes of the Sixth Amendment’s Confrontation Clause, and so are inadmissible unless the employee who performed the search and signed the certificate testifies at trial subject to cross-examination.', 'general', 'Campos-Alvarez v. United States', 'https://www.courtlistener.com/opinion/2554480/', '2554480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'evidence from which a reasonable mind might fairly infer guilt beyond a reasonable doubt’ may we reverse a conviction for evidentiary insufficiency.', 'general', 'Campos-Alvarez v. United States', 'https://www.courtlistener.com/opinion/2554480/', '2554480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Elmer Campos-Alvarez’s convictions, except for his CPWL and UF convictions, which we reverse.', 'general', 'Campos-Alvarez v. United States', 'https://www.courtlistener.com/opinion/2554480/', '2554480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although appellants raise several grounds for reversal, for the most part we affirm their convictions.', 'general', 'Campos-Alvarez v. United States', 'https://www.courtlistener.com/opinion/2554480/', '2554480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where this Court held that Article 1, § 6 of the Delaware Constitution provided greater protection than its Fourth Amendment counterpart and that a “seizure” occurs only if, viewing the totality of the circumstances, a reasonable person
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In those circumstances, we concluded that a second “seizure” had occurred, because the officer’s actions exceeded the permissible scope of the initial traffic stop, and the police lacked additional facts sufficient to justify the second “seizure.', 'general', 'Loper v. State', 'https://www.courtlistener.com/opinion/2556883/', '2556883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that at the time the officers made a showing of their authority and ordered Jones to stop, he had been "seized” within the meaning of Article I, § 6 of the Delaware Constitution, even though the police had not used actual force to stop Jones.', 'general', 'Loper v. State', 'https://www.courtlistener.com/opinion/2556883/', '2556883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that while there was no reversible error in the trial court’s curtailment of cross-examination, the government did fail to present sufficient evidence of Lewis’
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the trial court did err by curtailing defense counsel’s cross-examination of Washington, we hold that the error neither rose to the level of constitutional error nor amounted to an abuse of discretion by the trial court.', 'general', 'Lewis v. United States', 'https://www.courtlistener.com/opinion/2557897/', '2557897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed below, we hold that the error did not amount to a constitutional one and that the trial court did not abuse its discretion by curtailing Washington’s cross-examination in the manner that it did.', 'general', 'Lewis v. United States', 'https://www.courtlistener.com/opinion/2557897/', '2557897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we hold that there was insufficient evidence to prove that Lewis acted maliciously when he set the fire, and, therefore, his arson conviction must be reversed.', 'general', 'Lewis v. United States', 'https://www.courtlistener.com/opinion/2557897/', '2557897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we believe that a conviction for arson under the facts in this case would eviscerate any distinction between arson and MDP, we hold that the evidence failed to meet its burden and reverse Lewis’ arson conviction, mindful of the fact that Lewis has already been convicted of MDP and has not challenged that conviction.', 'general', 'Lewis v. United States', 'https://www.courtlistener.com/opinion/2557897/', '2557897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that there was no violation of the Sixth Amendment when the trial court permitted cross-examination of a victim of sexual assault about her friends’ reactions to her story of rape but precluded questioning about her mental understanding of their belief of her story.', 'general', 'Lewis v. United States', 'https://www.courtlistener.com/opinion/2557897/', '2557897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2006), in which we held that to amount to a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the MDP context, we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2010), in which we found that the appellant’s Sixth Amendment rights were not violated when the trial court precluded cross-examination of a government witness about his juvenile convictions and probation status.', 'general', 'Lewis v. United States', 'https://www.courtlistener.com/opinion/2557897/', '2557897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, even viewing the evidence provided at trial in the light most favorable to the government, we cannot find that the prosecution adduced sufficient evidence that Lewis was aware of a substantial risk to human life and consciously disregarded it, and therefore, under the narrow confines of the facts of this case, we reverse his arson conviction.', 'general', 'Lewis v. United States', 'https://www.courtlistener.com/opinion/2557897/', '2557897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that the trial court did not abuse its discretion in excluding proffered expert eyewitness identification testimony concerning complications in the identification process misunderstood by the lay public that were somewhat similar to those proffered in this case.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/2559587/', '2559587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the subject matter of the testimony was not beyond the ken of the average layperson and that the jury could evaluate the witness’ credibility based on information disclosed during cross-examination.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/2559587/', '2559587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that more recent developments in the scientific community and in our case law require more in-depth consideration of the factors affecting admissibility than was afforded here, we reverse and remand for further proceedings consistent with this opinion.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/2559587/', '2559587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that substantial evidence in this record justifies the finding of fact by the hearing examiner that probable cause existed to arrest Nellis for DWUI.', 'probable_cause', 'Nellis v. Wyoming Department of Transportation', 'https://www.courtlistener.com/opinion/2613589/', '2613589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under former AS 12.', 'general', 'Paige v. State', 'https://www.courtlistener.com/opinion/2576184/', '2576184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that Paige’s sentences must be deemed concurrent with each other
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have carefully reviewed the record of the sentencing, and we conclude that Judge Weeks’s sentencing remarks, viewed in context, do not clearly establish his intention to impose consecutive sentences.', 'sentencing', 'Paige v. State', 'https://www.courtlistener.com/opinion/2576184/', '2576184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of these reasons, we conclude that we must interpret Judge Weeks’s sentencing remarks as imposing all of Paige’s sentences concurrently.', 'sentencing', 'Paige v. State', 'https://www.courtlistener.com/opinion/2576184/', '2576184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred by refusing to allow Defendant to present expert testimony on the subject of the proper protocols for interviewing young children to avoid suggestiveness and the implanting of false memories.', 'general', 'State v. Speers', 'https://www.courtlistener.com/opinion/2566318/', '2566318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, given the very minimal standard that evidence must satisfy in order to be “relevant” and therefore admissible, we hold that there was no abuse of discretion by the trial court in denying Defendant’s motion to preclude this “flight” evidence at trial.', 'general', 'State v. Speers', 'https://www.courtlistener.com/opinion/2566318/', '2566318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 417, we conclude that the trial court erred in refusing to permit Defendant to present it for the jury’s consideration in evaluating the children’s testimony.', 'general', 'State v. Speers', 'https://www.courtlistener.com/opinion/2566318/', '2566318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the same circumstances exist here.', 'general', 'State v. Speers', 'https://www.courtlistener.com/opinion/2566318/', '2566318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the standard of review established by the IAPA does not apply to this appeal.', 'general', 'Idaho Historic Preservation Council, Inc. v. City Council', 'https://www.courtlistener.com/opinion/2569166/', '2569166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s decision.', 'general', 'Idaho Historic Preservation Council, Inc. v. City Council', 'https://www.courtlistener.com/opinion/2569166/', '2569166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the IAPA does not apply to the present case.', 'general', 'Idaho Historic Preservation Council, Inc. v. City Council', 'https://www.courtlistener.com/opinion/2569166/', '2569166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rejecting that argument and claims of prosecu-torial misconduct, we affirm the conviction.', 'general', 'Sturgis v. State', 'https://www.courtlistener.com/opinion/2613620/', '2613620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s judgment and order of sentencing.', 'sentencing', 'Sturgis v. State', 'https://www.courtlistener.com/opinion/2613620/', '2613620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶33 For the reasons set forth above, we hold that A.', 'general', 'In Re Ryan A.', 'https://www.courtlistener.com/opinion/2581335/', '2581335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on those rights and responsibilities, we held that a minor victim’s parents are “therefore entitled to restitution for their lost wages incurred while taking [the minor victim] to medical appointments and juvenile court hearings occasioned by” the criminal conduct.', 'general', 'In Re Ryan A.', 'https://www.courtlistener.com/opinion/2581335/', '2581335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶2 For the reasons set forth below, we affirm the trial court’s adjudication and restitution award.', 'general', 'In Re Ryan A.', 'https://www.courtlistener.com/opinion/2581335/', '2581335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the district court had no authority to reject the plea bargain between the State and Phillips on the basis that the State could have proved a more serious charge against Phillips.', 'plea', 'State v. District Court', 'https://www.courtlistener.com/opinion/2581938/', '2581938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we applied this same rationale when we held that neither the State nor the sentencing judge has the discretion to ignore plainly applicable aggravating and mitigating factors:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in the next section of this opinion, we conclude that this premise is wrong.', 'general', 'State v. District Court', 'https://www.courtlistener.com/opinion/2581938/', '2581938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that this is only a seeming conflict.', 'general', 'State v. District Court', 'https://www.courtlistener.com/opinion/2581938/', '2581938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the state has no discretion to suppress evi-denee of past convictions or aggravating or mitigating factors.', 'suppression', 'State v. District Court', 'https://www.courtlistener.com/opinion/2581938/', '2581938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the admission of Staggs’ out-of-court statement did not violate Hawaii’s con*524frontation clause inasmuch as Fields was afforded a sufficient opportunity to cross-examine Staggs about her prior statement at trial.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*531Hence, we conclude that, considered in the light most favorable'' to the prosecution, the evidence is of sufficient quality and probative value to enable a person of reasonable caution to support the conclusion that Fields intentionally, knowingly, or recklessly maltreated Staggs.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court granted certiorari in Sua I and in Sua II, reversed the ICA in part, indicating that "[i]n contrast to the ICA’s opinion, we hold that, under certain circumstances, receipt of grand jury testimony pursuant to a firmly rooted exception to the general rule against hearsay may adequately preserve a defendant''s right of cross-examination.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, because “[t]he eiror in this case was not harmless[,] it must be reversed and remanded for a new trial.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Eastman, this court held that the complainant’s prior inconsistent statement contained in a “Victim’s Voluntary Statement Form” (WSF) which she gave to a police officer “met all the requirements under HRE Rule 802.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reject Eide''s claim because we conclude that a fair-minded juror exercising reasonable judgment could conclude that the State had proven the vehicle theft and revoked license charges.', 'general', 'Eide v. State', 'https://www.courtlistener.com/opinion/2582430/', '2582430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence and reasonable inferences from the evidence in the light most favorable to upholding the verdicts, we conclude that the record contains substantial evidence that Eide drove Thomas''s truck away from Thomas''s residence.', 'general', 'Eide v. State', 'https://www.courtlistener.com/opinion/2582430/', '2582430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient to support the verdicts for first-degree vehicle theft and driving while license revoked.', 'general', 'Eide v. State', 'https://www.courtlistener.com/opinion/2582430/', '2582430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Howard, this court reversed a resisting arrest conviction because we concluded that fleeing from the arresting officer and hiding in the woods was not sufficient to support this crime.', 'general', 'Eide v. State', 'https://www.courtlistener.com/opinion/2582430/', '2582430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Because there was no evidence or any reasonable inference that Howard had resisted his arrest by "force," we reversed his conviction for resisting arrest.', 'general', 'Eide v. State', 'https://www.courtlistener.com/opinion/2582430/', '2582430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the superi- or court.', 'general', 'Eide v. State', 'https://www.courtlistener.com/opinion/2582430/', '2582430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Dixon', 'https://www.courtlistener.com/opinion/2586300/', '2586300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that I.', 'general', 'State v. Hart', 'https://www.courtlistener.com/opinion/2587318/', '2587318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the district judge’s order dismissing the complaint and remand the ease for further proceedings.', 'dismissal', 'State v. Hart', 'https://www.courtlistener.com/opinion/2587318/', '2587318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this was error.', 'general', 'State v. Gonsalves', 'https://www.courtlistener.com/opinion/2587727/', '2587727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we affirm the judgment and sentence of the circuit court.', 'sentencing', 'State v. Gonsalves', 'https://www.courtlistener.com/opinion/2587727/', '2587727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this Court held that the offense of theft by possession of stolen property was not a continuing offense.', 'general', 'State v. Maidwell', 'https://www.courtlistener.com/opinion/2588237/', '2588237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After noting that this would have occurred at least by 1987 when the defendant admitted to his sister that the pickup was “hot,” this Court held that the three-year statute of limitations would have run before the charge was filed in 1991.', 'general', 'State v. Maidwell', 'https://www.courtlistener.com/opinion/2588237/', '2588237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand this case for further proceedings.', 'general', 'State v. Maidwell', 'https://www.courtlistener.com/opinion/2588237/', '2588237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Barnes, this Court held that grand theft by possession of stolen property in violation of Idaho Code § 18-2403(4) was not a “continuing offense” extending until possession ceased;', 'general', 'State v. Maidwell', 'https://www.courtlistener.com/opinion/2588237/', '2588237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') This court held in Houston v.', 'general', 'People v. Kelly', 'https://www.courtlistener.com/opinion/2588350/', '2588350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a decision affirming the judgment in a Wende appeal disposes of a cause within the meaning of article VI, section 14, of the California Constitution, and therefore must be in writing with reasons stated.', 'general', 'People v. Kelly', 'https://www.courtlistener.com/opinion/2588350/', '2588350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that a writ of habeas corpus pursuant to I.', 'habeas', 'State v. Michael P. Martin', 'https://www.courtlistener.com/opinion/3181180/', '3181180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Michael P. Martin', 'https://www.courtlistener.com/opinion/3181180/', '3181180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the district court’s denial of Martin’s Rule 35(c) motion.', 'general', 'State v. Michael P. Martin', 'https://www.courtlistener.com/opinion/3181180/', '3181180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Can Sosa be charged with evidence tampering for defying the warrant, when neither exceptional circumstance specified by statute was present? We hold that he cannot.', 'general', 'Sosa v. State', 'https://www.courtlistener.com/opinion/2595442/', '2595442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it is not necessary to distinguish the elements of the State offenses from the federal offenses inasmuch as the State’s charges of possession of a controlled substance with intent to deliver and public servant bribery are based on different conduct at different times and places from the underlying conduct upon which the various federal offenses relating to conspiracy to possess and possession of more than 100 kilograms of marijuana with intent to distribute are based, and we reve...', 'general', 'State v. McMullen', 'https://www.courtlistener.com/opinion/7878388/', '7878388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm both decisions.', 'general', 'State v. Estrada', 'https://www.courtlistener.com/opinion/2631820/', '2631820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because one can obviously possess narcotics paraphernalia without necessarily, possessing or using a controlled substance, we hold that possession of narcotics paraphernalia is not a lesser-included offense of personal possession or use for purposes of § 13-901.', 'general', 'State v. Estrada', 'https://www.courtlistener.com/opinion/2631820/', '2631820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that 1.', 'general', 'State v. Korsen', 'https://www.courtlistener.com/opinion/2595006/', '2595006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because the magistrate’s dismissal was based upon an erroneous legal, not factual, conclusion, double jeopardy does not bar a retrial on the trespass charge.', 'dismissal', 'State v. Korsen', 'https://www.courtlistener.com/opinion/2595006/', '2595006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that the statute does not violate the Constitution as found by the courts below, either on grounds of vagueness or overbreadth.', 'general', 'State v. Korsen', 'https://www.courtlistener.com/opinion/2595006/', '2595006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that no reasonable jury could have found other than that Dann actually reflected on his decision to kill Andrew Parks, and we therefore conclude beyond a reasonable
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that there was sufficient evidence to support the burglary and felony murder convictions.', 'general', 'State v. Dann', 'https://www.courtlistener.com/opinion/2595414/', '2595414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that any comment favored Dann and, moreover, because the evidence presented at trial overwhelmingly established Dann’s guilt, we conclude, beyond a reasonable doubt, that the error had no influence on the verdict.', 'general', 'State v. Dann', 'https://www.courtlistener.com/opinion/2595414/', '2595414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that by failing to object or seek reconsideration, Dann waived any error that may have been attributable to his absence.', 'general', 'State v. Dann', 'https://www.courtlistener.com/opinion/2595414/', '2595414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the convictions for premeditated murder as to Shelly and Eddie.', 'general', 'State v. Dann', 'https://www.courtlistener.com/opinion/2595414/', '2595414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Dann’s convictions for the first degree premeditated murders of Shelly Parks and Eddie Payan pursuant to A.', 'general', 'State v. Dann', 'https://www.courtlistener.com/opinion/2595414/', '2595414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s decision to preclude the evidence of Andrew’s involvement in the drag trade and the evidence of drugs in the victims’ systems.', 'general', 'State v. Dann', 'https://www.courtlistener.com/opinion/2595414/', '2595414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no abuse of discretion, we affirm the trial court’s decision to deny the motion for mistrial.', 'mistrial', 'State v. Dann', 'https://www.courtlistener.com/opinion/2595414/', '2595414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 76 For the foregoing reasons, we affirm Dann’s convictions for the first degree felony murders of Andrew Parks, Shelly Parks, and Eddie Payan pursuant to A.', 'general', 'State v. Dann', 'https://www.courtlistener.com/opinion/2595414/', '2595414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed infra in section III, we hold that indecent exposure, in violation of HRS § 707-734, does not constitute an offense subject to the sex registration and public notification requirements of HRS ch.', 'general', 'State v. Chun', 'https://www.courtlistener.com/opinion/2598440/', '2598440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, and to reiterate, we hold that indecent exposure, in violation of HRS § 707-734, see supra note 2, does not constitute an offense that entails “criminal sexual conduct” and, consequently, that persons convicted of indecent exposure are not “sex offenders” for purposes of HRS ch.', 'general', 'State v. Chun', 'https://www.courtlistener.com/opinion/2598440/', '2598440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 1255 (2002), this court held, inter alia, that the registration components of HRS ch.', 'general', 'State v. Chun', 'https://www.courtlistener.com/opinion/2598440/', '2598440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '846E is devoid of any suggestion that the legislature sought to exercise its discretion to require registration for “[o]ffenses that do not involve physical contact, such as exhibitionism,” we conclude that the legislature did not intend to include indecent exposure, in violation of HRS § 707-734, among the offenses requiting registration pursuant to HRS ch.', 'general', 'State v. Chun', 'https://www.courtlistener.com/opinion/2598440/', '2598440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Huguelet did not err in refusing to grant Worden''s motion to dismiss the indictment and did not err in denying Worden''s motion for a continuance.', 'dismissal', 'Worden v. State', 'https://www.courtlistener.com/opinion/2598074/', '2598074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the State did not present sufficient evidence to convict Worden of possession of child pornography.', 'general', 'Worden v. State', 'https://www.courtlistener.com/opinion/2598074/', '2598074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Judge Huguelet did not abuse his discretion in denying Worden''s motion for a continuance.', 'general', 'Worden v. State', 'https://www.courtlistener.com/opinion/2598074/', '2598074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that AS 11.', 'general', 'Worden v. State', 'https://www.courtlistener.com/opinion/2598074/', '2598074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we must interpret the statute narrowly, we conclude that it does
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that Worden has waived this objection.', 'general', 'Worden v. State', 'https://www.courtlistener.com/opinion/2598074/', '2598074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM all of Worden''s convictions except his convictions for possession of child pornography.', 'general', 'Worden v. State', 'https://www.courtlistener.com/opinion/2598074/', '2598074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that the People referenced Melina’s conversations with several individuals to corroborate his intent to have someone kill Bueno, not to suggest that Melina had committed several crimes of solicitation.', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the People referenced Melina’s conversations with several individuals to corroborate his intent to have someone kill Bueno, not to suggest that Meli-na had committed several crimes of solicitation.', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we affirm the judgment of the court of appeals.', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989) (“Thus, we hold that the trial court did not err in denying the defendant’s motion to require that the People elect specific acts.', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 641-42 (“We conclude that the People referenced Melina’s conversations with several individuals to corroborate his intent to have someone kill Bueno, not to suggest that Melina had committed several crimes of solicitation.', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Woertman, we reversed the defendant’s convictions for sexual assault on a child after announcing that we were reviewing for plain error, but we did so only because the trial court also admitted evidence of over fifty separate acts, despite a bill of particulars limiting the charges to three specific acts, and not only failed to limit the purpose for which the additional acts could be considered but actually instructed the jury that it would be sufficient for conviction to find any act that...', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1657, and giving due deference to Officer Greene’s training and experience, we conclude that the totality of the circumstances established a reasonable suspicion that defendant was transporting illegal drugs and justified his further detention.', 'general', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 37 In balancing the justification for and circumstances of defendant’s detention against the degree to which his liberty was intruded upon, we conclude that Officer Greene did not act unreasonably by detaining defendant for one hour and forty minutes pending the arrival of a drug-detection dog.', 'general', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 44 We conclude that the record contains sufficient evidence from which reasonable persons could find that defendant knowingly transported marijuana.', 'general', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 47 For the foregoing reasons, we affirm defendant’s convictions and sentences.', 'sentencing', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the language used within subsection (g) by the legislature was meant solely as a carefully thought out prophylactic measure to ensure that the written reports submitted by law enforcement officials called for under the statute be kept confidential.', 'general', 'Pagel v. Franscell', 'https://www.courtlistener.com/opinion/2602424/', '2602424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Pagel v. Franscell', 'https://www.courtlistener.com/opinion/2602424/', '2602424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 22] Given those reasons set forth above, we reverse the order entered by the district court requiring DCI*to provide a list of all people living within Campbell County, Wyoming who currently had a permit or license to carry a concealed weapon under Wyoming law to Newspaper and further remand this matter back to the district court for entry of an order consistent with this opinion.', 'general', 'Pagel v. Franscell', 'https://www.courtlistener.com/opinion/2602424/', '2602424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that § 7-611 does not preclude alternative civil sanctions under the common law or I.', 'general', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find a compelling and legitimate governmental interest in assur*569ing the efficacy of the writ of habeas corpus, we hold that here there is no qualified newsman s privilege beyond the usual inquiry concerning relevance and materiality of the information sought.', 'habeas', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the record, we conclude that the September 18 hearing was a continuing part of the initial habeas corpus proceeding.', 'habeas', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 We conclude that the *565magistrate court had proper jurisdiction to conduct the September 18 hearing and the subsequent hearings in furtherance of the habeas corpus proceeding.', 'habeas', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“IT IS HEREBY ORDERED AND THIS DOES ORDER that the Order of Contempt entered by this Court on September 19, 1980, be modified to provide that the witness, Ellen Marks, shall pay the sum of FIVE HUNDRED &amp;', 'general', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” The majority only partially answers the question when it states: “We hold that here there is no qualified newsman’s privilege beyond the usual inquiry concerning relevance and materiality.', 'general', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Gyles had not shown any basis for refusing to discuss the crimes for which he had already been convicted.', 'general', 'Covington v. State', 'https://www.courtlistener.com/opinion/2606428/', '2606428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we concluded that Gyles had established a sufficient basis for claiming the privilege as to crimes or misconduct for which he had not previously been convicted.', 'general', 'Covington v. State', 'https://www.courtlistener.com/opinion/2606428/', '2606428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, as the trial court instructed, Minick was a “witness” as a matter of law, and the failure to instruct by using the statutory language “in the discharge of his duty” does not constitute reversible error under these circumstances.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2607055/', '2607055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our pragmatic definition of a section 1503 “witness” in light of the protective purpose of the obstruction of justice statute, we find that Mann retained his status as a “witness” while the Talapoosa Pipeline case was pending on direct appeal.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2607055/', '2607055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand the trial court’s Conditional Order Permitting Leave to Proceed in Forma Pauperis and Order Continuing Appointment of Counsel and Requiring Periodic Payments.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2607055/', '2607055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Conditional Order Permitting Leave to Proceed in Forma Pauperis and Order Continuing Appointment of Counsel and Requiring Periodic Payments.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2607055/', '2607055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence considered by the jury was sufficient to sustain Bouw-kamp’s conviction on both felony murder and premeditation theories.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that heretofore we have not identified and articulated a method for evaluating evidence of premeditation.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Bouwkamp’s conviction.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm that premeditation remains the defining crux and the distinction which this court will require to uphold a first degree murder conviction.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when there is such a danger of a fragmented verdict, the court must instruct a jury, on request, that if a guilty verdict is returned, the jury must be unanimous on the underlying facts.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we conclude that such an instruction was not required in this case.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the same bootstrapping is involved in instructing a jury that the intent to assault makes the entry burglary and that the burglary raises the homicide resulting from the assault to first degree murder without proof of malice aforethought and premeditation.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 959 (1977), insofar as it automatically required an EMED manslaughter instruction when a defendant asserted self-defense, we hold that the trial court did not err in this regard.', 'general', 'State v. Sawyer', 'https://www.courtlistener.com/opinion/2609445/', '2609445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that in all murder prosecutions hereafter tried in this state, where the evidence necessitates an instruction on self-defense, the trial court shall also give instructions to the jury on the charge of manslaughter.', 'general', 'State v. Sawyer', 'https://www.courtlistener.com/opinion/2609445/', '2609445') ON CONFLICT DO NOTHING;
