INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, if no specification is made as to whether multiple sentences are concurrent or whether they are consecutive, the sentences will be deemed to be consecutive whether they are imposed in the same case, in different cases, or by different courts.', 'sentencing', 'Pearson v. State', 'https://www.courtlistener.com/opinion/2609901/', '2609901') ON CONFLICT DO NOTHING;
