INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Pearson v. State', 'https://www.courtlistener.com/opinion/2609901/', '2609901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such purely subjective impressions of a juror’s qualities had to be coupled with objective support to overcome a prima facie showing of discrimination.', 'general', 'State v. Trostle', 'https://www.courtlistener.com/opinion/2611397/', '2611397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 192 (1993), we held that the trial court has “no obligation to instruct the jury on theories withdrawn in the prosecutor’s discretion.', 'general', 'State v. Trostle', 'https://www.courtlistener.com/opinion/2611397/', '2611397') ON CONFLICT DO NOTHING;
