INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the impairment was significant for (G)(1) purposes and considered it a substantial factor in our independent reweighing, which resulted in a reduction of the defendant’s three death sentences.', 'sentencing', 'State v. Trostle', 'https://www.courtlistener.com/opinion/2611397/', '2611397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Poland I, we held that an act of premedition, such as the kidnapping of a victim that occurred in Yavapai County, was a sufficient essential act requisite to the commission of the offense of premeditated first degree murder to establish venue in Yavapai County.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Pritchard charges and the Jones/Smith charges were connected together in their commission and were part of a common scheme or plan.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Pritchard offenses were properly joined with the Jones/Smith offenses pursuant to Rule 13.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the trial court properly denied appellant’s motions for judgment of acquittal of the robbery count and the felony murder theory.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that there was conduct constituting two elements of sexual abuse (Count XII) and sexual assault (Count XIII) that occurred in Maricopa County.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion by refusing to strike the two jurors for cause.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence supports the trial court’s finding that appellant had two prior felony convictions involving the use or threat of violence against another person.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the record, we conclude that appellant’s words and actions demonstrate the killing was heinous and depraved.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to appellant’s argument, we find that sufficient evidence supported the armed robbery conviction.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the penalty of death.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Frankel, this court held, in the context of a civil case, that peremptory challenges are a substantial right of a party, and that forcing use of peremptory challenges to strike jurors who should have been stricken for cause denies the party this right.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Evans, in which we concluded that, generally, upward durational departures should not exceed double the presumptive sentence length.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding the departure was impermissibly based on uncharged criminal conduct, we reverse and remand for resentencing.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Jackson’s enhanced sentence and remand for imposition of the presumptive sentence or, unless waived by Jackson, the empanelling of a resentencing jury to determine the existence of facts in support of legitimate aggravating factors for enhanced sentencing, including sentencing as a career or dangerous offender under Minn.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Jackson’s enhanced sentence was based upon impermissible departure factors.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that imposition of two separate sentences violated the statutory prohibition against multiple punishments contained in MinmStat.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we concluded that a plea agreement standing alone could not be used to depart because it does not demonstrate that the defendant’s conduct in the offense of conviction was significantly more or less serious than that typically involved in the commission of the crime in question.', 'plea', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In my view, the departure in this case is consistent with the double upward departure we affirmed in State v.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the contrary, we affirmed the sentence because the departure was based on the “facts relating to the conduct underlying the offense to which the defendant pleaded guilty.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the registration requirement does not constitute punishment, J.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In response to an adult defendant’s claim that the Registration Act violated his right to substantive due process, we held that the public interest to be served by the Registration Act was the assistance of law enforcement in the protection of children.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Malchow, we held that the purpose of the Notification Law, like the Registration Act, was the protection of the public from sex offenders.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, this court held that Rule 604(d) applies to juvenile proceedings.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reading section 2(A — 5) together with section 2(E) so that no word or paragraph is rendered meaningless, we conclude that J.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was nothing unreasonable in the statute’s method of serving its purpose given the direct relationship between the registration of sex offenders and the protection of children.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the appellate court correctly determined that J.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that waiver does not bar consideration of these issues.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case at bar, this court holds that the requirements of the Registration Act apply equally to adults and juveniles and that our constitutional safeguards do not prevent the Registration Act’s lifetime registration provisions from being applied to minors of all ages.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accord with this statutory language and the statutory scheme developed by the legislature, we hold that defendant has sufficiently shown that he is in immediate danger of being subjected to the permissive inference of section 4 — 103.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the above-stated reasons, we hold that section 4 — 103.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the trial court improperly sustained defendant’s facial challenge of section 1 — 191 of the Code on vagueness grounds.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the defendant in Rogers lacked standing to challenge the inference because it was apparent that the inference would not be applied to him.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm in part and reverse in part the judgment of the circuit court, and hold that section 4 — 103.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While these factors lend a measure of support for the conclusion that the questioning was not coercive, we hold that they do not tip the scale away from a finding of custody in light of Mr.', 'general', 'Fredrick E. Morton v. United States', 'https://www.courtlistener.com/opinion/3150415/', '3150415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that, under the totality of the circumstances, the trial court erred in finding Mr.', 'general', 'Fredrick E. Morton v. United States', 'https://www.courtlistener.com/opinion/3150415/', '3150415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Morton was aware of his guilt when he was apprehended and questioned, we hold that he was in custody for Miranda purposes under either construction of the "reasonable person” test.', 'general', 'Fredrick E. Morton v. United States', 'https://www.courtlistener.com/opinion/3150415/', '3150415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, based on the totality of the circumstances in this case, a reasonable person, in appellant’s position, would not have felt free to leave and terminate police- questioning and was subject to a restraint on his freedom of movement tantamount to.', 'general', 'Fredrick E. Morton v. United States', 'https://www.courtlistener.com/opinion/3150415/', '3150415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we conclude that a reasonable person in the place of the appellant would not have felt free to terminate the police questioning and leave, and the restraint involved in appellant’s detainment was congruent to the degree of restraint normally associated with formal arrest.', 'general', 'Fredrick E. Morton v. United States', 'https://www.courtlistener.com/opinion/3150415/', '3150415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that under the circumstances the statement to the appellant that he was not under arrest is not a “strong indication!] on the other side of the ledger that this was not Miranda custody” as is necessary when a suspect’s freedom of movement is restrained by handcuffs.', 'general', 'Fredrick E. Morton v. United States', 'https://www.courtlistener.com/opinion/3150415/', '3150415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record supports the opposite deduction: that Mr.', 'general', 'Fredrick E. Morton v. United States', 'https://www.courtlistener.com/opinion/3150415/', '3150415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse his convictions on the Fifth Amendment claim, we decline to address the merger argument.', 'general', 'Fredrick E. Morton v. United States', 'https://www.courtlistener.com/opinion/3150415/', '3150415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse Robinson’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was not.', 'general', 'State v. Yong Shik Won', 'https://www.courtlistener.com/opinion/3158283/', '3158283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the investigative encounter could be deemed “consensual” only if, prior to the start of questioning, the person was informed of the right to decline to participate in the encounter and of the right to leave at any time and thereafter, the person voluntarily participated in the encounter.', 'general', 'State v. Yong Shik Won', 'https://www.courtlistener.com/opinion/3158283/', '3158283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the ICA’s analysis is in error.', 'general', 'State v. Yong Shik Won', 'https://www.courtlistener.com/opinion/3158283/', '3158283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the fact that the search in this case was for the purpose of collecting evidence for a criminal prosecution, we conclude that under the Supreme Court’s definition, the special needs exception is not applicable to the circumstances of this case, and thus it is unnecessary to address whether a "special law enforcement needs” exception to the warrant requirement is in accordance with the Hawai''i Constitution.', 'general', 'State v. Yong Shik Won', 'https://www.courtlistener.com/opinion/3158283/', '3158283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court has concluded that the contamination of coercion extends even to coercion by private actors: “although no state action is involved where an accused is coerced into making a confession by a private individual, we find that the state participates in that violation by allowing the coerced statements to be used as evidence.', 'general', 'State v. Yong Shik Won', 'https://www.courtlistener.com/opinion/3158283/', '3158283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead of addressing the merits of the class’s claims, we concluded that because the class in that case failed to adequately allege which fundamental right protected by due process was infringed by Megan’s Law II, the class failed to state a substantive due process claim.', 'general', 'J. Taylor v. The PSP of the Commonwealth of PA', 'https://www.courtlistener.com/opinion/3168765/', '3168765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding Kunberger’s convictions do pot violate double jeopardy and his sentence is not inappropriate, we affirm Kunberger’s convictions and sentence.', 'sentencing', 'Thomas M. Kunberger v. State of Indiana', 'https://www.courtlistener.com/opinion/3159333/', '3159333') ON CONFLICT DO NOTHING;
