INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Verenzo Cartrell Green v. State of Mississippi', 'https://www.courtlistener.com/opinion/3173188/', '3173188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm both the judgment of the Adams County Circuit Court and the Court of Appeals judgment affirming it.', 'general', 'Verenzo Cartrell Green v. State of Mississippi', 'https://www.courtlistener.com/opinion/3173188/', '3173188') ON CONFLICT DO NOTHING;
