INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, Haile contends that Old-ner, supra, and Allen, swpra, require that we hold that Johnston’s conviction renders Johnston ineligible to run for or hold office in perpetuity.', 'general', 'Haile v. Johnston', 'https://www.courtlistener.com/opinion/3176750/', '3176750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Powers, while citing to Tyler, we held that the expunged conviction was “as if it had never been.', 'general', 'Haile v. Johnston', 'https://www.courtlistener.com/opinion/3176750/', '3176750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed and explained as follows.', 'general', 'Haile v. Johnston', 'https://www.courtlistener.com/opinion/3176750/', '3176750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the circuit court.', 'general', 'Haile v. Johnston', 'https://www.courtlistener.com/opinion/3176750/', '3176750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals decision affirming the district court’s admission of evidence of the defendant’s attempt to evade detection by law enforcement on September 20, 2011, because it was inadmissible as evidence of his consciousness of guilt for the charged crimes.', 'general', 'State of Iowa v. John Arthur Wilson', 'https://www.courtlistener.com/opinion/3178818/', '3178818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals decision affirming the district court’s admission of evidence of the defendant’s flight from law enforcement on August 11, 2011, because it was admissible as evidence of his consciousness of guilt for the charged crimes.', 'general', 'State of Iowa v. John Arthur Wilson', 'https://www.courtlistener.com/opinion/3178818/', '3178818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However,'' because we find the improper admission of this evidence to be harmless error, we affirm in part and vacate in part the decision of the court of appeals and affirm the judgment of the district court:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm .', 'general', 'State of Iowa v. John Arthur Wilson', 'https://www.courtlistener.com/opinion/3178818/', '3178818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ex parte Sparks, we held that a felony conviction is all that an applicant must show for a claim to be cognizable in post-convictión habeas corpus proceedings, even if the actual offense was a misdemeanor.', 'habeas', 'Palmberg, Bryan Elliott', 'https://www.courtlistener.com/opinion/3180643/', '3180643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing Applicant’s arguments in turn, we conclude that his particular set of circumstances does not fit any scenario, in which this Court typically grants relief.', 'general', 'Palmberg, Bryan Elliott', 'https://www.courtlistener.com/opinion/3180643/', '3180643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Campbell we held that a larceny indictment identifying the property owner as “Manna Baptist Church” was sufficient because “alleging ownership of property in an entity identified as a church or other place of religious worship, like identifying an entity as a ‘company’ or ‘incorporated,’ signifies an entity capable of owning property.', 'general', 'State v. Spivey', 'https://www.courtlistener.com/opinion/3186945/', '3186945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying upon Mason and subsequent cases cited in Hicks, we concluded that there was a fatal variance.', 'general', 'State v. Spivey', 'https://www.courtlistener.com/opinion/3186945/', '3186945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Hall’s claim, based as it was on the ineffectiveness of counsel, “unquestionably” fell within the framework of the PCRA, and, therefore, that the PCRA was the sole means by *406which he could seek relief.', 'ineffective_assistance', 'Commonwealth, Aplt v. Descares', 'https://www.courtlistener.com/opinion/3189718/', '3189718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court further noted that, regardless, as this Court held in Commonwealth v.', 'general', 'Commonwealth, Aplt v. Descares', 'https://www.courtlistener.com/opinion/3189718/', '3189718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In rejecting his argument, we acknowledged that, in Sheehan, swpra, this Court held that petitioners who did not meet the custody requirement under the language of the prior PCHA, “but who faced direct collateral civil or criminal consequences of their convictions, could nevertheless obtain review” through “common law writs of error coram nobis.', 'general', 'Commonwealth, Aplt v. Descares', 'https://www.courtlistener.com/opinion/3189718/', '3189718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, although Appellee cursorily avers that the third sentence of Section 9542 quoted above suggests that the legislature did not intend that a defendant be precluded from seeking, outside of the PCRA, relief from the collateral consequences of a conviction, we note that this same language was in Section 9542 when this Court held in Ahlbom that, despite the fact that the appellant continued to suffer the collateral consequences of his conviction—including a driver’s license suspension and t...', 'sentencing', 'Commonwealth, Aplt v. Descares', 'https://www.courtlistener.com/opinion/3189718/', '3189718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Stock, this Court held that the defendant, who was convicted in absentia of three summary traffic offenses and sentenced to pay fines, and whose attorney failed to file an appeal as requested, could seek permission to file a nunc pro tunc *411appeal of his convictions outside of the framework of PCRA because the defendant was never eligible for relief under the PCRA as he could not meet the PCRA’s requirement that he be “under a sentence of death or imprisonment or on parole or probation.', 'sentencing', 'Commonwealth, Aplt v. Descares', 'https://www.courtlistener.com/opinion/3189718/', '3189718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We conclude that he was not, and, accordingly, vacate the Superi- or Court’s judgment to the contrary and dismiss Appellee’s underlying petition for relief under the Post Conviction Relief Act (“PCRA”), 42 Pa.', 'dismissal', 'Commonwealth, Aplt v. Descares', 'https://www.courtlistener.com/opinion/3189718/', '3189718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More centrally, we conclude that the Superior Court’s decision below is in conflict with Ahlborn, Hall, and our other PCRA jurisprudence, and, accordingly, we disapprove its analysis in that regard.', 'general', 'Commonwealth, Aplt v. Descares', 'https://www.courtlistener.com/opinion/3189718/', '3189718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that Mr.', 'general', 'State Ex Rel. Judicial Investigation Commission v. Putnam County Board of Ballot Commissioners', 'https://www.courtlistener.com/opinion/3192463/', '3192463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these holdings to the case sub judice, we conclude that Mr.', 'general', 'State Ex Rel. Judicial Investigation Commission v. Putnam County Board of Ballot Commissioners', 'https://www.courtlistener.com/opinion/3192463/', '3192463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the Board has a legal duty to remove Mr.', 'general', 'State Ex Rel. Judicial Investigation Commission v. Putnam County Board of Ballot Commissioners', 'https://www.courtlistener.com/opinion/3192463/', '3192463') ON CONFLICT DO NOTHING;
