INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And because we find that no error occurred here, it follows''that there is no plain error.', 'general', 'Archie Quinn v. State of Mississippi', 'https://www.courtlistener.com/opinion/3205285/', '3205285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Windless controls here.', 'general', 'Archie Quinn v. State of Mississippi', 'https://www.courtlistener.com/opinion/3205285/', '3205285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And just as “larceny” is commonly understood to mean stealing, we find that “assault” is commonly understood to mean causing or attempting to cause bodily injury to another.', 'general', 'Archie Quinn v. State of Mississippi', 'https://www.courtlistener.com/opinion/3205285/', '3205285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, .', 'general', 'Archie Quinn v. State of Mississippi', 'https://www.courtlistener.com/opinion/3205285/', '3205285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial judge properly instructed the jury and therefore .', 'general', 'Archie Quinn v. State of Mississippi', 'https://www.courtlistener.com/opinion/3205285/', '3205285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Quinn’s conviction and sentence, but we- dismiss Quinn''s ineffective-assistanee-of-counsel claim without prejudice so that, he may raise it in a post-conviction proceeding, should he so choose.', 'dismissal', 'Archie Quinn v. State of Mississippi', 'https://www.courtlistener.com/opinion/3205285/', '3205285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that joinder was proper because the charges joined were "2 or more acts or transactions connected together or constituting parts of a *13common scheme or plan," the charges were "connected together," and the charges constituted parts of a "common scheme or plan.', 'general', 'State v. Luis C. Salinas', 'https://www.courtlistener.com/opinion/3207143/', '3207143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the charges here were properly joined because they were "2 or more acts or transactions connected together or constituting parts of a common scheme or plan", the charges were "connected together" and the charges constituted "parts of a common scheme or plan.', 'general', 'State v. Luis C. Salinas', 'https://www.courtlistener.com/opinion/3207143/', '3207143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the initial decision to join the intimidation charges with the sexual assault charges was proper because these crimes were "2 or more acts or transactions connected together or constituting parts of a common scheme or plan.', 'general', 'State v. Luis C. Salinas', 'https://www.courtlistener.com/opinion/3207143/', '3207143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals and affirm the jury''s verdicts finding Luis Salinas guilty of: (1) repeated sexual assault of a child;', 'general', 'State v. Luis C. Salinas', 'https://www.courtlistener.com/opinion/3207143/', '3207143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the use of force — although highly inappropriate — did not coerce Braddy to make any incriminating statement, we hold that Braddy’s confession to Detective Diaz was voluntary.', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial judge’s denial of Braddy’s motions on June 18, 2007, was timely.', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the cumulative effect of any errors in the State’s guilt phase closing argument did not compromise the integrity of Braddy’s trial, and we deny relief on Braddy’s closing argument claim.', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''Therefore, having examined the entire closing *847argument, paying specific attention to the challenged comments — whether preserved or not — we hold that the cumulative effect of any improper comments did not deprive Braddy of a fair trial.', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion by allowing the State to introduce the arrest report, affidavit, and plea colloquy from Braddy’s conviction for his crimes against the Coles.', 'plea', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having closely examined the record and considered the totality of evidence presented at Braddy’s trial, we hold that the cumulative effect of any errors did not deprive Braddy of a fair trial.', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering both the aggravating and mitigating factors, we hold that Brad-dy’s sentence is proportionate to death sentences that we have upheld in other cases.', 'sentencing', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Powell I, we held that Miranda warnings advising a defendant of both his right to consult counsel “before any questioning” and his right to invoke any of his rights at any time during the interview were insufficient to inform the defendant of his right to have a lawyer present during questioning.', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reversing Delgado’s burglary conviction, we held that the phrase “remaining in” found in Florida’s burglary statute “should be limited to situations where the suspect enters lawfully and subsequently secretes himself or herself from the host.', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the State’s comments “transcended the limitations of appropriate argument to the jury” by “giv[ing] the jury the benefit of the composite judgment of the State’s Attorney’s staff allegedly reached on the basis of investigations and discussions taking place before the trial.', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Moore, this Court held that the trial court did not abuse its discretion in overruling a defendant’s objection to the State’s penalty-phase closing argument that mitigation evidence of the defendant’s normal, loving upbringing “may sound like mitigation, but .', 'general', 'Braddy v. State', 'https://www.courtlistener.com/opinion/4990543/', '4990543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that Officer Crites’ arrest of the appellant was unlawful.', 'general', 'State v. Hefner', 'https://www.courtlistener.com/opinion/8217986/', '8217986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree, and we reverse the judgment of the circuit court.', 'general', 'State v. Hefner', 'https://www.courtlistener.com/opinion/8217986/', '8217986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 Accordingly, we hold that the district court’s failure to instruct the jury on Miller’s lesser included offense was prejudicial.', 'general', 'State of Iowa v. David Lee Miller', 'https://www.courtlistener.com/opinion/2687715/', '2687715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Sixteen years ago, we held that the crime of absence from custody was not a lesser included offense of escape.', 'general', 'State of Iowa v. David Lee Miller', 'https://www.courtlistener.com/opinion/2687715/', '2687715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Burtlow, we found that the defendant’s conduct did not satisfy the elements of escape because he did not depart from “physical restraint.', 'general', 'State of Iowa v. David Lee Miller', 'https://www.courtlistener.com/opinion/2687715/', '2687715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for new trial.', 'general', 'State of Iowa v. David Lee Miller', 'https://www.courtlistener.com/opinion/2687715/', '2687715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we reverse the judgment of the district court and vacate the decision of the *585court of appeals, we acknowledge both courts properly relied on our applicable precedent.', 'general', 'State of Iowa v. David Lee Miller', 'https://www.courtlistener.com/opinion/2687715/', '2687715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that MCL 750.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We held that a person injured while driving a motor vehicle that was taken contrary to the express prohibition of the vehicle owner cannot receive PIP benefits.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’ ”28 We conclude that the phrase “without an intent to steal” in MCL 750.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we conclude that the phrase “without an intent to steal” is not an express or implied indication that our Legislature intended to dispense with the element of mens rea under MCL 750.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '414 as a whole, we conclude that it properly requires a showing of knowingly taking without authority or knowingly using without authority.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '35 Accordingly, we conclude that MCL 750.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that plaintiff may present evidence that he did not knowingly lack authority to take the motorcycle.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “any person who takes a vehicle contrary to a provision of the Michigan Penal Code — including MCL 750.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we affirm the Court of Appeals’ decision insofar as it holds that plaintiff is entitled to PIP benefits if the evidence establishes he did not know the motorcycle he had taken was stolen.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part the opinion of the Court of Appeals, and remand to the circuit court for further proceedings consistent with this opinion.', 'general', 'Rambin v. Allstate Insurance Company', 'https://www.courtlistener.com/opinion/2710481/', '2710481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that plaintiffs actions resulted in damage to defendant’s undivided interest in the home as a tenant by the entirety and, thus, the trial judge erred in determining that plaintiff had not damaged “property of another” under N.', 'general', 'N.T.B. v. D.D.B.', 'https://www.courtlistener.com/opinion/7404847/', '7404847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judge’s rejection of defendant’s argument that plaintiff committed an act of domestic violence through the predicate act of harassment.', 'general', 'N.T.B. v. D.D.B.', 'https://www.courtlistener.com/opinion/7404847/', '7404847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial judge’s determination the facts did not support a finding of domestic violence through the predicate act of harassment.', 'general', 'N.T.B. v. D.D.B.', 'https://www.courtlistener.com/opinion/7404847/', '7404847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking the above mitigating circumstances into account, we conclude that a six-month suspension is appropriate.', 'general', 'People v. Freeman', 'https://www.courtlistener.com/opinion/5334380/', '5334380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is hereby ordered that Mary Loren Freeman be suspended from the practice of law for six months, commencing immediately upon the issuance of this opinion.', 'general', 'People v. Freeman', 'https://www.courtlistener.com/opinion/5334380/', '5334380') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court and Appellate Division
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed, we affirm the judgment of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, although the officer testified that she did not intend her small talk to provoke an incriminating response, she “should have known that her words were reasonably likely to elicit an incriminating response from the person in custody.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court abused its discretion in admitting evidence of the 2006 prior bad acts, as only the 2007 incident was necessary to counter Raza-nas’s testimony, and the probative value of the 2006 acts was substantially outweighed by the danger of unfair prejudice.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances presented, we hold that the trial court properly permitted the State to introduce Kazanas’s statement at trial.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the fact that the questioning occurred in the police station is but one factor, albeit an important one, in deciding whether the defendant-appellant was in custody when he was questioned.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The ICA then examined Ikaika, a case in which this court held that the defendant was not subjected to interrogation.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that Bartolome’s question was just a “pleasantry,” and that Ikaika’s confession “was of the nature of an unsolicited, spontaneous statement made in the absence of any police questioning.', 'plea', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Judge Foley then analogized Kazanas’s ease to Ketchum, a case in which this court held that police officers who asked a detainee for his home address should have reasonably known that asking the question would elicit an incriminating response, as the detainee lived at a residence, which was identified in a search warrant, in which drugs had just been found.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held, “To determine whether ‘interrogation’ is ‘custodial,’ we look to the totality of the circumstances, focusing on ‘the place and time of the interrogation, the length of the interrogation, the nature of the questions asked, the conduct of the police, and [any] other relevant circumstances.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, in analyzing whether Kazanas was “interrogated,” the majority of the ICA relied heavily upon Ikaika, a case in which this court held that a defendant’s confession that he “shot the haole” to his police lieutenant acquaintance was “of the nature of an unsolicited, spontaneous statement made in the absence of police questioning.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that “after arrest the police practice of inviting an arrestee to make a statement and *39to give his or her ‘side of the story’ or similar entreaties in a ‘pre-interview’ before Miranda warnings are given, violates the defendant’s right against self-incrimination, article I, section 10, and right to due process, article I, section 5, of the Hawai''i Constitution.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, under the totality of the circumstances, the pre-interview was considered an interrogation and that the defendant should have been advised of his Miranda rights before the pre-interview.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the detective’s question constituted an interrogation because the detective should have known that asking the defendant for his side of the story was reasonably likely to elicit an incriminating response.', 'general', 'State v. Kazanas.', 'https://www.courtlistener.com/opinion/4247396/', '4247396') ON CONFLICT DO NOTHING;
