INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we will explain, we hold that the Supreme Court’s decision in Hurst v.', 'general', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Sixth Amendment applies to both.', 'general', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of Ring, we hold that Hurst’s sentence violates the Sixth Amendment.', 'sentencing', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that in addition to unanimously finding the existence of any aggravating factor, the jury must also unanimously find that the aggravating factors are sufficient for the imposition of death and unanimously find that the aggravating factors outweigh the mitigation before a sentence of death may be considered by the judge.', 'sentencing', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that section 775.', 'general', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1956), again acknowledging that “[i]n this state, the verdict of the jury must be unanimous,” this Court held that any interference with the right to a unanimous jury verdict denies the defendant a fair trial as guaranteed by the Declaration of Rights of the Florida Constitution.', 'general', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*45However, we conclude that the error in Hurst’s sentencing identified by the United States Supreme Court was not harmless beyond a reasonable doubt.', 'sentencing', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Florida, as well as the decisions in Ap-prendi and Ring, we conclude that the Sixth Amendment right to a trial by jury mandates that under Florida’s capital sen-fencing scheme, the jury—not the judge— must be the finder of every fact, and thus every element, necessary for the imposition of the death penalty.', 'general', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And because these findings occupy a position on par with elements of a greater offense, we conclude that all these findings necessary for the imposition of a sentence of death must be made by the jury—as are all elements—unanimously.', 'sentencing', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that under the commandments of Hurst v.', 'general', 'Timothy Lee Hurst v. State of Florida', 'https://www.courtlistener.com/opinion/4314145/', '4314145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his judgment without further comment.', 'general', 'Lavender v. State', 'https://www.courtlistener.com/opinion/4318383/', '4318383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Lavender v. State', 'https://www.courtlistener.com/opinion/4318383/', '4318383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon reviewing the record, we conclude that the court below did not abuse its discretion.', 'general', 'State v. Baxter', 'https://www.courtlistener.com/opinion/5341605/', '5341605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Baxter', 'https://www.courtlistener.com/opinion/5341605/', '5341605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the court appropriately addressed the misconduct and no error occurred.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that no evidentiary errors occurred and focus much of our discussion on Linda’s assertions of prose-cutorial misconduct.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that there is sufficient evidence to support the verdict, the evidence supporting the conviction is entirely circumstantial.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 1147, we conclude that the prosecutor’s comments do not rise to the level of obvious error that would require us to vacate the jury’s verdict.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, and considering the overall context of the trial, we conclude that Linda failed to demonstrate a reasonable probability that the prosecutor’s statement affected her substantial rights, that is, that it affected the outcome of the trial.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court’s instructions were sufficient to remedy any prejudice that may have been caused by the prosecutor’s anthropomorphic comments.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d at 84, and we conclude that the prosecutor committed misconduct by the use of words that could have been understood by the jury to present the prosecutor’s personal opinion during the closing argument.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the brief nature of these comments, the strong response by defense counsel in Linda’s closing argument, the duration of trial and amount of evidence presented, and the careful manner in which the judge instructed the jury, we conclude that Linda has failed to demonstrate a reasonable probability that the “Ms.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', “plain” in this context, we conclude that Linda has failed to show a reasonable probability that the error affected the outcome of the trial.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 73] For all these reasons, we conclude that Linda has failed to carry her burden of showing a reasonable probability that the prosecutor’s urgings to “do justice” affected the outcome of this case or deprived Linda of a fair trial.', 'general', 'State v. Dolloff', 'https://www.courtlistener.com/opinion/5146055/', '5146055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 1287 (“We conclude that the trial court properly considered all of the relevant factors it was required to take into account in rendering the current sentence.', 'sentencing', 'Commonwealth v. Cartrette', 'https://www.courtlistener.com/opinion/5147518/', '5147518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon all of the above considerations, we conclude that review of a discretionary sentencing matter after revocation proceedings is encompassed by the scope of this Court’s review.', 'sentencing', 'Commonwealth v. Cartrette', 'https://www.courtlistener.com/opinion/5147518/', '5147518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that this argument raises a substantial question, Commonwealth v.', 'general', 'Commonwealth v. Cartrette', 'https://www.courtlistener.com/opinion/5147518/', '5147518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 949 ("We hold that the Government''s installation of a GPS device on a target''s vehicle, and its use of that device to monitor the vehicle''s movements, constitutes a ''search.', 'general', 'State v. Richard L. Weber', 'https://www.courtlistener.com/opinion/4325497/', '4325497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the deputy''s warrantless entry into Weber''s garage and subsequent arrest of Weber were constitutional because they were justified by the exigent circumstance of hot pursuit of a fleeing suspect who had committed jailable offenses.', 'general', 'State v. Richard L. Weber', 'https://www.courtlistener.com/opinion/4325497/', '4325497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that at the time he entered Weber''s garage, Deputy Dorshorst had probable cause to arrest Weber for violations of Wis.', 'probable_cause', 'State v. Richard L. Weber', 'https://www.courtlistener.com/opinion/4325497/', '4325497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', ¶ ¶ 32-37, 41 ("We conclude that [the deputy''s] entry was justified by the exigent circumstance of hot pursuit.', 'general', 'State v. Richard L. Weber', 'https://www.courtlistener.com/opinion/4325497/', '4325497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the deputy''s warrantless entry into Weber''s garage and subsequent arrest of Weber were constitutional because they were justified by the exigent circumstance of hot pursuit of a fleeing *234suspect who had committed jailable offenses.', 'general', 'State v. Richard L. Weber', 'https://www.courtlistener.com/opinion/4325497/', '4325497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals.', 'general', 'State v. Richard L. Weber', 'https://www.courtlistener.com/opinion/4325497/', '4325497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that unsworn representations,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the good faith exception precludes application of the exclusionary rule where officers conduct a search in objectively reasonable reliance upon clear and settled Wisconsin precedent that is later deemed unconstitutional by the United States Supreme Court.', 'general', 'State v. Dearborn', 'https://www.courtlistener.com/opinion/8238269/', '8238269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16 We concluded as follows: "[B]ecause the officers relied, in objective good faith, upon the pronouncements of this court we hold that exclusion of the evidence would serve no remedial objective and, therefore, the evidence seized at the Ward residence should be admitted.', 'general', 'State v. Dearborn', 'https://www.courtlistener.com/opinion/8238269/', '8238269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the good faith exception precludes application of the exclusionary rule where officers conduct a search in *278objectively reasonable reliance upon clear and settled Wisconsin precedent that is later deemed unconstitutional by the United States Supreme Court.', 'general', 'State v. Dearborn', 'https://www.courtlistener.com/opinion/8238269/', '8238269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the search of Dearborn''s truck was lawful under clear and settled Wisconsin precedent before the Gant decision, and that the officers here reasonably relied on this law in conducting the search.', 'general', 'State v. Dearborn', 'https://www.courtlistener.com/opinion/8238269/', '8238269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we conclude that the good faith exception to the exclusionary rule should preclude the suppression of the illegally obtained evidence in this case because the officers reasonably relied on clear and settled Wisconsin Supreme Court precedent in carrying out the search.', 'suppression', 'State v. Dearborn', 'https://www.courtlistener.com/opinion/8238269/', '8238269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on Belton, we concluded that the search did not violate Wis.', 'general', 'State v. Dearborn', 'https://www.courtlistener.com/opinion/8238269/', '8238269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals and uphold Dearborn''s conviction.', 'general', 'State v. Dearborn', 'https://www.courtlistener.com/opinion/8238269/', '8238269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that unsworn representations, even by an officer of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the offense of attempted assault with a deadly weapon inflicting serious injury is recognized in North Carolina.', 'general', 'State v. Floyd', 'https://www.courtlistener.com/opinion/4332375/', '4332375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we held that an attempted assault is simply not a recognized criminal offense in this jurisdiction.', 'general', 'State v. Floyd', 'https://www.courtlistener.com/opinion/4332375/', '4332375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, because we conclude that attempted assault is not an attempt of an attempt, and thus does not implicate the dicta in Hewett, we do not address the extent to which Hewett may apply to other criminal offenses not at issue in the case subjudice.', 'general', 'State v. Floyd', 'https://www.courtlistener.com/opinion/4332375/', '4332375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that this offense is recognized in this state, we do not reach the State’s alternative argument.', 'general', 'State v. Floyd', 'https://www.courtlistener.com/opinion/4332375/', '4332375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defense counsel in Ali made such a record, we concluded that the defendant was not denied effective assistance of counsel.', 'general', 'State v. Floyd', 'https://www.courtlistener.com/opinion/4332375/', '4332375') ON CONFLICT DO NOTHING;
