INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State of Minnesota v. Emile Rey', 'https://www.courtlistener.com/opinion/4336869/', '4336869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'considered Rey’s ability to pay before ordering restitution, we affirm.', 'general', 'State of Minnesota v. Emile Rey', 'https://www.courtlistener.com/opinion/4336869/', '4336869') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“Therefore, because the discretion given to district courts furthers the legitimate legislative purpose of sentencing offenders based on the severity of their particular circumstances, we hold that section 76-3-207.', 'sentencing', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When the State attempts to admit certain evidence, including “gruesome photographs of a homicide victim’s corpse,” we held that the State must show that the evidence possessed “unusual probative value.', 'general', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '■¶52 We conclude that Utah Code section 76-3-207.', 'general', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not review the district court’s determination that the photographs were not gruesome within the meaning of Lafferty because we conclude that the test set out in Lafferty is no longer good law and because the district court determined the admissibility of the photographs under the correct legal standard — the balancing test set out in rule 403.', 'general', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶114 Even assuming, however, that Met’s trial counsel’s failure to pursue the mistrial motion was deficient, we conclude that Met cannot establish that he was prejudiced by his .', 'mistrial', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the trailer owner had a right to consent to the search of the common areas of the trailer because of its common use by many individuals, including the owner.', 'general', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶102 We concluded that “Finlayson’s detention of the victim up to the time of the rape and sodomy was incidental to the assault, rather than having an independent significance.', 'general', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finlayson also does not adequately explain why we concluded that the detention — including handcuffing the victim — was merely incidental and did not make "the other crime substantially easier of commission.', 'general', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶101 In Finlayson, we reversed the defendant’s conviction for aggravated kidnapping while affirming his convictions for forcible sodomy and rape.', 'general', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we affirm the sentence of life in prison without parole for the child kidnapping conviction.', 'sentencing', 'State v. Met', 'https://www.courtlistener.com/opinion/4323883/', '4323883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the first issue, we hold that Webber did not establish a deferential standard of review in pretrial'' criminal appeals by the State, and, to the extent our language in Webber suggests otherwise, that portion of the opinion is overruled.', 'general', 'State of Minnesota v. Jose Martin Lugo, Jr.', 'https://www.courtlistener.com/opinion/4326123/', '4326123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the second issue, we hold that, under the totality of the undisputed facts, the dog-sniff was supported by a reasonable, articulable suspicion.', 'general', 'State of Minnesota v. Jose Martin Lugo, Jr.', 'https://www.courtlistener.com/opinion/4326123/', '4326123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the totality of the circumstances, we hold that there was a reasonable, articulable suspicion to expand the search.', 'general', 'State of Minnesota v. Jose Martin Lugo, Jr.', 'https://www.courtlistener.com/opinion/4326123/', '4326123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that our decision in Webber was not intended to, nor did it, announce a rule of deference to district court pretrial legal conclusions that the State has appealed.', 'general', 'State of Minnesota v. Jose Martin Lugo, Jr.', 'https://www.courtlistener.com/opinion/4326123/', '4326123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Anderson, we reversed the court of appeals’ holding that the State did not show critical impact, and remanded to that court to address the admissibility of the confession that the district court had suppressed.', 'suppression', 'State of Minnesota v. Jose Martin Lugo, Jr.', 'https://www.courtlistener.com/opinion/4326123/', '4326123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the lower courts’ conclusion that the search was not supported by exigent circumstances, 428 N.', 'general', 'State of Minnesota v. Jose Martin Lugo, Jr.', 'https://www.courtlistener.com/opinion/4326123/', '4326123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the court of appeals.', 'general', 'State of Minnesota v. Jose Martin Lugo, Jr.', 'https://www.courtlistener.com/opinion/4326123/', '4326123') ON CONFLICT DO NOTHING;
