INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a criminal defendant is not “entitled” to have a jury entertain his post-conviction Atkins claim, and remanded for the bench hearing.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5144895/', '5144895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that appellant has no cognizable right either to a bench trial or to a choice of factfinder, other than a jury, under the U.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5144895/', '5144895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that this issue is not renewable.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5144895/', '5144895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Against this background, we find that the trial court committed no error in deferring the Atkins decision to a jury for a penalty phase decision.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5144895/', '5144895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the conviction and judgment of sentence.', 'sentencing', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5144895/', '5144895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this sequence of events clearly gives rise to a reasonable suspicion on
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Wells v. State', 'https://www.courtlistener.com/opinion/4375411/', '4375411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on the evidence presented by the government, in conjunction with the reasonable inferences drawn by the trial court, we conclude that there was sufficient evidence to prove that appellant conspired to commit the assaultive act against J.', 'general', 'IN RE T.M.', 'https://www.courtlistener.com/opinion/4375933/', '4375933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court did not plainly err in failing to prohibit the enforcement of the CP statute at trial where it was neither clear nor obvious that the statute was unconstitutional.', 'general', 'IN RE T.M.', 'https://www.courtlistener.com/opinion/4375933/', '4375933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we concluded that the error was clear, given that the statute violated “fundamental principles of due process .', 'general', 'IN RE T.M.', 'https://www.courtlistener.com/opinion/4375933/', '4375933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'IN RE T.M.', 'https://www.courtlistener.com/opinion/4375933/', '4375933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we affirm appellant’s convictions and remand the case solely for the trial court to address those convictions that merge.', 'general', 'IN RE T.M.', 'https://www.courtlistener.com/opinion/4375933/', '4375933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that each of Lepsch''s claims fails, and that he is not entitled to a new trial.', 'general', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '15 We conclude that he was not denied due process.', 'general', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For similar reasons, under an ineffective assistance of counsel analysis, we conclude that Lep-sch''s attorneys'' failure to object to Lepsch''s absence at the swearing of the prospective jurors did not prejudice21 Lepsch even if this failure constituted deficient performance.', 'ineffective_assistance', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that, contrary to Lep-sch''s contention, Lepsch has forfeited his claim that the swearing of prospective jurors outside of his presence violated his right to receive a public trial by failing to raise an objection below.', 'general', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that he was not denied the effective assistance of counsel with regard to this claim.', 'general', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" In any event, if Lepsch is arguing his lawyers should have objected and raised the arguments Lepsch raises now, we conclude that, even assuming deficient performance of some kind, Lepsch was not prejudiced by it because there was no denial of due process.', 'general', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Pinno we concluded that a presumption of prejudice was not appropriate in cases involving "the denial of the right to a public voir dire.', 'general', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the decision of the court of appeals.', 'general', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the call bore adequate indicia of reliability for the officer to credit, the caller’s account.', 'general', 'Nathan P. Jackson v. United States', 'https://www.courtlistener.com/opinion/4382813/', '4382813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Pal committed two offenses, not one, when he fled from the scene of his accident, and that the legislature authorized punishment for each offense.', 'general', 'State v. Sambath Pal', 'https://www.courtlistener.com/opinion/4387056/', '4387056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the offenses are not identical in law and fact, we presume that the legislature authorized multiple punishments.', 'general', 'State v. Sambath Pal', 'https://www.courtlistener.com/opinion/4387056/', '4387056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 First, we conclude that the two offenses for which Pal was sentenced are not identical in fact.', 'sentencing', 'State v. Sambath Pal', 'https://www.courtlistener.com/opinion/4387056/', '4387056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that Pal has not rebutted the presumption that the legislature authorized punishment for each offense.', 'general', 'State v. Sambath Pal', 'https://www.courtlistener.com/opinion/4387056/', '4387056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the offenses charged are not identical in fact.', 'general', 'State v. Sambath Pal', 'https://www.courtlistener.com/opinion/4387056/', '4387056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals.', 'general', 'State v. Sambath Pal', 'https://www.courtlistener.com/opinion/4387056/', '4387056') ON CONFLICT DO NOTHING;
