INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Schelling, we held that “purely emotional injuries” could only constitute “actual injury” to the extent that those emotional damages were otherwise compensable pursuant to existing statutory or common law.', 'general', 'Dana Desjardins v. Michael Reynolds', 'https://www.courtlistener.com/opinion/4392321/', '4392321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, because we conclude that Desjardins did not meet his prima facie burden as a matter of law according to the standard first articulated in Nader I and reiterated in Gaudette, we need not remand the matter for the Superior Court to apply the additional procedures articulated in Gaudette, which apply only if a plaintiff has met his prima facie burden.', 'general', 'Dana Desjardins v. Michael Reynolds', 'https://www.courtlistener.com/opinion/4392321/', '4392321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Desjardins''s failure to conform his special motion to dismiss opposition to the allegations pleaded in his complaint prevents him from meeting his burden, we need not consider whether such self-generated damages otherwise can satisfy the “actual injury” component of an anti-SLAPP opposition.', 'dismissal', 'Dana Desjardins v. Michael Reynolds', 'https://www.courtlistener.com/opinion/4392321/', '4392321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'Dana Desjardins v. Michael Reynolds', 'https://www.courtlistener.com/opinion/4392321/', '4392321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the discovery protections afforded under New Jersey’s Criminal Justice Reform Act satisfy the requirements of due process and pass muster under the Federal and State Constitutions.', 'general', 'State v. Habeeb Robinson(078900) (Essex County and Statewide)', 'https://www.courtlistener.com/opinion/4392850/', '4392850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*52We find that Rule 3:4—2(c)(1)(B), on which the courts relied, required disclosure of the reports and the photos but not the video.', 'general', 'State v. Habeeb Robinson(078900) (Essex County and Statewide)', 'https://www.courtlistener.com/opinion/4392850/', '4392850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the discovery rule—in its original and revised form—amply lives up to that requirement.', 'general', 'State v. Habeeb Robinson(078900) (Essex County and Statewide)', 'https://www.courtlistener.com/opinion/4392850/', '4392850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we affirm and modify the judgment of the Appellate Division.', 'general', 'State v. Habeeb Robinson(078900) (Essex County and Statewide)', 'https://www.courtlistener.com/opinion/4392850/', '4392850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Propps’s sentence was not unconstitutional under a gross disproportionality analysis.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the forcible felony sentencing statute, Iowa Code section 907.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ragland, we held that Miller applied retroactively.', 'general', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a lengthy term-of-years sentence—in this case a 52.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pearson, we held that a minimum sentence of thirty-five years triggered a Miller individualized sentencing hearing.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lyle, we held that all mandatory minimum sentences of imprisonment for juveniles are unconstitutional under article I, section 17 of the Iowa Constitution.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we will treat Propps’s notice of appeal and accompanying briefs as a petition for writ of certiorari, as we conclude that appeals from a motion to correct an illegal sentence are most appropriately fashioned in this manner.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we find that Iowa Code section 907.', 'general', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there is no constitutional infirmity in Iowa Code section 907.', 'general', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that it was the parole board that was best situated to discern which offenders are irreparably corrupt and which have benefited from opportunities for maturation and rehabilitation.', 'general', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that despite the state legislative history, Congress did not intend to preempt state criminal statutes like the identity theft laws.', 'general', 'State of Iowa v. Martha Aracely Martinez', 'https://www.courtlistener.com/opinion/4398773/', '4398773') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, viewing the record in the light most favorable to the July’s verdict, we hold that the solicitations in this case occurred during the course of multiple criminal episodes.', 'general', 'State of Florida v. Brian Mitchell Lee', 'https://www.courtlistener.com/opinion/4396630/', '4396630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the multiple temporal breaks between communications, the multiple lo*358cations involved, and the different types of unlawful acts Lee solicited, we hold that the record established no fewer than five distinct acts, of solicitation.', 'general', 'State of Florida v. Brian Mitchell Lee', 'https://www.courtlistener.com/opinion/4396630/', '4396630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, viewing the record in the light most favorable to the jury’s verdict, we conclude that Lee’s convictions for traveling after solicitation, unlawful use of a two-way communications device, and soliciting a minor do not violate double jeopardy because his convictions were based on distinct criminal acts.', 'general', 'State of Florida v. Brian Mitchell Lee', 'https://www.courtlistener.com/opinion/4396630/', '4396630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the same elements test, we concluded that Hamilton’s dual convictions violated double jeopardy.', 'general', 'State of Florida v. Brian Mitchell Lee', 'https://www.courtlistener.com/opinion/4396630/', '4396630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore we find that a double jeopardy violation has ■ occurred.', 'general', 'State of Florida v. Brian Mitchell Lee', 'https://www.courtlistener.com/opinion/4396630/', '4396630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we reverse Lee’s sentences and remand for resentencing because the trial court improperly departed .', 'sentencing', 'State of Florida v. Brian Mitchell Lee', 'https://www.courtlistener.com/opinion/4396630/', '4396630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as to .', 'general', 'State of Florida v. Brian Mitchell Lee', 'https://www.courtlistener.com/opinion/4396630/', '4396630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2016), we affirmed a conviction over a double jeopardy challenge where “the in*369formation and the jury verdict demonstrate that the charges were predicated on two distinct acts.', 'general', 'State of Florida v. Brian Mitchell Lee', 'https://www.courtlistener.com/opinion/4396630/', '4396630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 409, 420 (2017) (“In accordance with Miller, we hold that sentencing courts must have complete discretion to consider mitigating circumstances associated with the youth of any juvenile defendant.', 'sentencing', 'State of Iowa v. Christopher Ryan Lee Roby', 'https://www.courtlistener.com/opinion/4400906/', '4400906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm this approach, but would elaborate on the use of the abuse-of-discretion standard in the juvenile sentencing context.', 'sentencing', 'State of Iowa v. Christopher Ryan Lee Roby', 'https://www.courtlistener.com/opinion/4400906/', '4400906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we reverse the decision of the district court and remand the case for entry of an order of dismissal.', 'dismissal', 'State of Iowa v. Martha Aracely Martinez', 'https://www.courtlistener.com/opinion/4398773/', '4398773') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that there was sufficient evidence to support the privilege of self-defense, we conclude that the circuit court erred in failing to instruct the jury on self-defense as requested by the defendant.', 'general', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an adequate basis exists in the record to support a self-defense instruction and to allow the defense of self-defense to be argued to and considered by the jury.', 'general', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the circuit court erred in refusing to instruct the jury on self-defense.', 'general', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the circuit court erroneously refused to instruct the jury on self-defense, we next consider whether the error affected the defendant''s "substantial rights.', 'general', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, after viewing the record in the light most favorable to the defendant, as we must, we conclude that there was sufficient evidence supporting a self-defense instruction in the instant case.', 'general', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the circuit court erred in refusing to instruct the jury on self-defense.', 'general', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not consider those formulations because we conclude that the record supports the defendant''s request for this pattern jury instruction.', 'jury_instruction', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and the judgment of conviction.', 'general', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and the judgment of the circuit court.', 'general', 'State v. Robert Joseph Stietz', 'https://www.courtlistener.com/opinion/4399725/', '4399725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the good faith exception applies where the State has shown, objectively, that the police officers reasonably relied upon a warrant issued by an independent magistrate.', 'general', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we conclude that the State did not prove by clear and convincing evidence that Blackman''s consent to the blood draw was valid, that is, that it was freely and voluntarily given under the Fourth Amendment.', 'search_seizure', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is not.', 'general', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the consent was obtained through misrepresentation and was coerced.', 'general', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the good faith exception does not apply in the instant case.', 'general', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because Blackman''s consent was the product of misrepresentation by the State, and under the totality of the circumstances, the State has not carried its burden of proving that Blackman''s consent was voluntarily and freely given under the Fourth Amendment.', 'search_seizure', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we conclude that the State failed to meet its burden to prove that Blackman voluntarily and freely consented to the blood draw under the Fourth Amendment.', 'search_seizure', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence of Blackman''s blood test should be suppressed.', 'suppression', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we conclude that the State did not prove by clear and convincing evi*370dence that Blackman''s consent to the blood draw was valid, that is, that it was voluntarily and freely given under the Fourth Amendment.', 'search_seizure', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we reverse the decision of the court of appeals, affirm the suppression order of the circuit court, and decline to apply the good faith exception to the exclusionary rule in the instant case.', 'suppression', 'State v. Adam M. Blackman', 'https://www.courtlistener.com/opinion/4407041/', '4407041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the District Court did not abuse its discretion in rejecting Sheehan’s proposed jury instruction on the termination of workers’ compensation benefits under § 39-71-609, MCA.', 'jury_instruction', 'State v. Sheehan', 'https://www.courtlistener.com/opinion/4414298/', '4414298') ON CONFLICT DO NOTHING;
