INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed in more detail infra, this Court held in Gaito that if a parolee is detained both on a detainer by the Pennsylvania Board of Probation and Parole and for new charges for which he did not satisfy bail requirements, the time spent in custody is to be credited to the sentence imposed for the new charges, but if the parolee met bail requirements for the new charges and was thus detained solely on the Board''s detainer, time in custody is to be credited against the original sentence.', 'sentencing', 'Smith, D. v. PA Board of Probation & Parole, Aplt.', 'https://www.courtlistener.com/opinion/4435188/', '4435188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McCray, this Court held a challenge to the denial of credit on a sentence for new criminal offenses must be presented to the sentencing court or in an appeal to the Superior Court, and is not-to be resolved by the Board.', 'sentencing', 'Smith, D. v. PA Board of Probation & Parole, Aplt.', 'https://www.courtlistener.com/opinion/4435188/', '4435188') ON CONFLICT DO NOTHING;
