INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bound by the supreme court’s Cooper decision, we hold that the trial court erred by sentencing McCullough for fleeing or eluding causing serious bodily injury or death and vehicular homicide, in contravention of the single homicide rule.', 'sentencing', 'McCullough v. State', 'https://www.courtlistener.com/opinion/4441297/', '4441297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that McCullough’s sentences for both second-degree vehicular homicide and fleeing or eluding violate the single homicide rule.', 'sentencing', 'McCullough v. State', 'https://www.courtlistener.com/opinion/4441297/', '4441297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bound by Cooper, we hold that the sentencing court erred by punishing McCullough for both vehicular homicide and fleeing or eluding causing serious bodily injury or death.', 'sentencing', 'McCullough v. State', 'https://www.courtlistener.com/opinion/4441297/', '4441297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because fleeing or eluding causing serious bodily injury or death is a first-degree felony, we reverse and remand with instructions for the trial court to vacate the lesser, second-degree felony of vehicular homicide.', 'general', 'McCullough v. State', 'https://www.courtlistener.com/opinion/4441297/', '4441297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm McCullough’s remaining convictions and sentences.', 'sentencing', 'McCullough v. State', 'https://www.courtlistener.com/opinion/4441297/', '4441297') ON CONFLICT DO NOTHING;
