INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the first, we conclude that trial counsel''s failure to move to dismiss the disorderly conduct charge on the basis that it violated Breitzman''s constitutional right to free speech was not deficient performance, and thus not ineffective assistance of counsel, because whether profane conduct that tends to cause or provoke a disturbance is protected as free speech is unsettled law.', 'dismissal', 'State v. Ginger M. Breitzman', 'https://www.courtlistener.com/opinion/4447957/', '4447957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the second, we conclude that trial counsel''s theory of reasonable parental discipline, as presented in opening remarks, was not deficient performance, and thus not ineffective assistance of counsel, because it reflected trial counsel''s reasonable expectations, which were rationally based on discussions with Breitzman, and it was part of a reasonable trial strategy.', 'ineffective_assistance', 'State v. Ginger M. Breitzman', 'https://www.courtlistener.com/opinion/4447957/', '4447957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the third, we conclude that trial counsel''s failure to object to testimony regarding uncharged conduct was not deficient performance, and thus not ineffective assistance of counsel, because declining to object was part of a reasonable trial strategy.', 'ineffective_assistance', 'State v. Ginger M. Breitzman', 'https://www.courtlistener.com/opinion/4447957/', '4447957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that trial counsel''s performance was not deficient, we need not address whether, in the context of ineffective assistance of counsel, there was prejudice to Breitzman, and we decline to do so.', 'ineffective_assistance', 'State v. Ginger M. Breitzman', 'https://www.courtlistener.com/opinion/4447957/', '4447957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that trial counsel''s failure to move to dismiss the disorderly conduct charge on the basis that it violated Breitzman''s constitutional right to free speech was not deficient performance, and thus not ineffective assistance of counsel, because whether profane conduct that tends to cause or provoke a disturbance is protected as free speech is unsettled law.', 'dismissal', 'State v. Ginger M. Breitzman', 'https://www.courtlistener.com/opinion/4447957/', '4447957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defense counsel''s theory of reasonable parental discipline, as presented in opening remarks, was not deficient performance, and thus not ineffective assistance of counsel, because it reflected trial counsel''s reasonable expectations, which were rationally based on discussions with Breitzman, and it was part of a reasonable trial strategy.', 'ineffective_assistance', 'State v. Ginger M. Breitzman', 'https://www.courtlistener.com/opinion/4447957/', '4447957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that trial counsel''s failure to object to testimony regarding uncharged conduct was not deficient performance, and thus not ineffective assistance of counsel, because declining to object was part of a reasonable trial strategy.', 'ineffective_assistance', 'State v. Ginger M. Breitzman', 'https://www.courtlistener.com/opinion/4447957/', '4447957') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Breitzman has not established that trial counsel''s performance was deficient, we need not address whether, in the context of ineffective assistance of counsel, the alleged errors individually or cumulatively prejudiced Breitzman, and we decline to do so.', 'ineffective_assistance', 'State v. Ginger M. Breitzman', 'https://www.courtlistener.com/opinion/4447957/', '4447957') ON CONFLICT DO NOTHING;
