INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that the evidence was insufficient to support a finding of willful absconding under N.', 'general', 'State v. Krider', 'https://www.courtlistener.com/opinion/4469069/', '4469069') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we conclude that the State presented insufficient evidence to support a finding of willful absconding pursuant to N.', 'general', 'State v. Krider', 'https://www.courtlistener.com/opinion/4469069/', '4469069') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As in Williams , we conclude that the evidence in this case does not support a violation of *833N.', 'general', 'State v. Krider', 'https://www.courtlistener.com/opinion/4469069/', '4469069') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the State''s evidence was insufficient to support that allegation, we conclude that the trial court lacked jurisdiction to revoke defendant''s probation after his case expired.', 'general', 'State v. Krider', 'https://www.courtlistener.com/opinion/4469069/', '4469069') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson , emphasizing the defendant''s whereabouts were never "unknown" because defendant was on electronic monitoring, we held that a defendant who informed his probation officer he would not attend an office visit, and then subsequently failed to report to that meeting does not, without more, violate (b)(3a) when those same actions violate (b)(3).', 'general', 'State v. Krider', 'https://www.courtlistener.com/opinion/4469069/', '4469069') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a juvenile adjudication does not constitute a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse the judgment and order of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we conclude the record is not adequate to determine whether defendant’s trial counsel was ineffective in failing to raise the causation issue, we affirm the conviction.', 'ineffective_assistance', 'State of Iowa v. Jonathan Q. Adams', 'https://www.courtlistener.com/opinion/4472371/', '4472371') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Adams’ conviction for homicide by vehicle and affirm the court of appeals’ resolution of Adams’ claim of insufficient evidence to support his conviction for driving while intoxicated.', 'general', 'State of Iowa v. Jonathan Q. Adams', 'https://www.courtlistener.com/opinion/4472371/', '4472371') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'D authorize the district court to make such an unconstitutional upward durational departure upon finding an aggravating factor without the aid of a jury, we hold that the statute is facially unconstitutional and section II.', 'general', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gross-man, we held that the patterned sex offender statute, which allowed the judge to increase by 10 years the maximum prison sentence prescribed by the first-degree criminal sexual conduct statute, based on the judge’s factual findings using a pre-ponderanee-of-evidenee standard, violated due process.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we conclude that in imposing sentence for a felony, the district court is required to impose the presumptive sentence set out in the Sentencing Guidelines *141Grid absent additional findings.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the overriding purposes of the Sentencing Guidelines system, we conclude that the unconstitutional portion of Minn.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that severing the unconstitutional portion of Minn.', 'general', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Apprendi principles were not implicated because only the minimum term of imprisonment is affected by the finding of a heinous crime, and therefore the determination of a prior heinous crime conviction may be found by the district court.', 'general', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with the rule announced in that case, we reverse the court of appeals and remand to the district court.', 'general', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the court of appeals and remand this case to the district court for resentencing consistent with this opinion.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the upward departure from the presumptive sentence is unconstitutional.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court did not err in determining that Beard’s actions constituted a divisible course of conduct and therefore accrued three, not two, criminal history points.', 'general', 'State v. Beard', 'https://www.courtlistener.com/opinion/1723191/', '1723191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'State v. Beard', 'https://www.courtlistener.com/opinion/1723191/', '1723191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when the district court found that Allen was unamenable to probation, and on that basis executed his presumptively stayed sentence, it violated Allen’s Sixth Amendment right to have a jury make that determination using a reasonable-doubt standard.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1875296/', '1875296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the district court’s assigning Allen a custody-status point to calculate his criminal history score did not violate the Sixth Amendment.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1875296/', '1875296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), we held that the imposition of an upward durational departure from the presumptive sentence prescribed by the Minnesota Sentencing Guidelines, based solely on facts found by the judge, violates the Sixth Amendment right to trial by jury under Blakely v.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1875296/', '1875296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Shattuck, we held that for felonies other than first-degree murder, the presumptive sentence prescribed by the Sentencing Guidelines is the maximum a judge may impose based solely on facts reflected in the jury verdict or admitted by the defendant.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1875296/', '1875296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we held that in order for a defendant to be found guilty of criminal vehicular homicide (leaving the scene), the State is required to prove that the defendant knew he had been involved in an accident with a person or another vehicle.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the evidence was sufficient to support the verdict because “[although the evidence is circumstantial, it is ‘consistent with the hypothesis that the accused is guilty’ — i.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the court of appeals erred when it failed to apply the circumstantial-evidence test to Al-Naseer’s sufficieney-of-the-evi-dence claim.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that test to Al-Na-seer’s leaving-the-scene conviction, we conclude that the evidence presented at trial is insufficient to support the conviction.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of that reasonable doubt, we conclude that there is insufficient evidence to support Al-Na-seer’s conviction of criminal vehicular homicide-leaving the scene.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without reaching Al-Naseer’s constitutional challenges, we reverse.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse Al-Naseer’s conviction based on the lack of sufficient evidence, we have no occasion to, and therefore do not, reach the due process issues raised by Al-Naseer.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After granting Al-Naseer’s petition for review, we affirmed the court of appeals’ leaving-the-scene decision but reversed the gross-negligence conviction because the district court failed to instruct the jury on the lesser-included offense of careless driving.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm our holding in Al-Naseer IV and decline to impose a new duty on a driver to stop and investigate if he is not aware that he hit a person or vehicle.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and remand for a new trial.', 'general', 'State v. Pride', 'https://www.courtlistener.com/opinion/2028269/', '2028269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 Therefore, we hold that the trial court erred when it joined the identity-theft offense with the three theft-by-swindle offenses because the theft-by-swindle offenses, while related to the identity-theft offense, were unrelated to each other.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wakefield, reasoning that it is fundamentally unfair for the state to force, a defendant to again defend against alleged conduct after the defendant has successfully done so once, we held that evidence related to a crime for which the defendant has been acquitted may not be used as Spreigl evidence.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that neither due process nor fundamental fairness would have prevented evidence of the Sears offense from being used as Spreigl evidence at separate trials of the offenses had the trials been properly severed and the evidence otherwise met the requirements for the admission of Spreigl evidence.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we conclude that the record contains admissible evidence connecting Ross to each of the theft-by-swindle offenses sufficient to meet the clear and convincing standard.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that evidence of Ross’s participation in each theft-by-swindle offense is relevant to a determination of Ross’s guilt with respect to each of the other theft-by-swindle offenses.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the probative value of the evidence outweighs the potential for unfair prejudice to Ross.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that admission of evidence of the improperly joined offenses would have been admissible as Spreigl evidence had the offenses been properly severed for trial, we also conclude that the improper joinder of the offenses was not prejudicial to Ross regarding determination of his guilt or innocence.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand to the court of appeals for determination of any remaining properly raised issues.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the court of appeals and reinstate Ross’s convictions, we remand these issues to the court of appeals for further consideration.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979) (stating that “we conclude that under no circumstances *284is evidence of a crime other than that for which a defendant is on trial admissible when the defendant has been acquitted of that other offense.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2230925/', '2230925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'Carrier v. Secretary of State', 'https://www.courtlistener.com/opinion/5146154/', '5146154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we affirm her decision because it was otherwise based on grounds authorized by section 2454(5).', 'general', 'Carrier v. Secretary of State', 'https://www.courtlistener.com/opinion/5146154/', '5146154') ON CONFLICT DO NOTHING;
