INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With regard to the first issue, we conclude that the defendant has proved that the no-contest plea was not knowing, intelligent, and voluntary and thus that the matter should be remanded to the circuit court to allow the defendant to withdraw his no-contest plea.', 'plea', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the defendant has proved that he received ineffective assistance of trial counsel and thus that the matter should be remanded to the circuit court to allow the defendant to withdraw his no-contest plea.', 'plea', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we conclude that the defendant entered into the plea agreement without knowing the actual value of the State''s plea offer and relying on misinformation from the court, the State, and trial counsel about the applicability of the persistent repeater enhancer.', 'plea', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the defendant established that he did not knowingly, intelligently, and voluntarily enter the plea of no contest.', 'plea', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the totality of the circumstances set forth in the record (and we have detailed the testimony at ¶¶ 41-51), we conclude that the defendant has satisfied the prejudice prong of the Strickland standard.', 'ineffective_assistance', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, with regard to the first issue, we conclude that the defendant''s no-contest plea was not knowing, intelligent, and voluntary and that the matter should be remanded to the circuit court to allow the defendant to withdraw his no-contest plea.', 'plea', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Cross had not made a prima facie case entitling him to shift the burden to the State to prove that his plea was knowing and intelligent.', 'plea', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the denial of Denk''s motion to withdraw his plea.', 'plea', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the denial of Cross'' motion to withdraw his plea after concluding that the circuit court''s statements on the range of punishments to which Cross was subjected by pleading was not "substantially higher[] than that authorized by law.', 'plea', 'State v. Myron C. Dillard', 'https://www.courtlistener.com/opinion/2755583/', '2755583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that any rights created by the provisions of the Interstate Agreement on Detainers Act, W.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 588 (1989), we held that the rejection of a petition for appeal does not constitute a decision on the merits precluding all future consideration of the issues raised therein.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in Syllabus Point 4 of Moore v.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that our Legislature intended our adoption of the IAD to be consistent with the federal IAD enactment.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While it appears, at first blush, that Boze-man would control this matter, we find that it does not.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed in Section A, infra, we find that they may not.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it involves neither.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we find that Pethel’s guilty plea relative to the drug and burglary charges in the indictment waived his claims based upon violation of the IAD as to the indictment’s drug and burglary related charges.', 'plea', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding significant contrary authority, we reverse the finding of the circuit court.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the circuit court’s grant of habeas relief to Pethel because the same was based upon a violation of the IAD’s anti-shuttling provision.', 'habeas', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold the sentence was not subject to challenge by way of a motion to correct illegal sentence, we affirm the trial court’s denial.', 'sentencing', 'Haynes v. State', 'https://www.courtlistener.com/opinion/4988284/', '4988284') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our previous interpretations of the language “by the threat or presenting of firearms,” we find that Phillips’ reasoning is flawed.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1204916/', '1204916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this standard, we find that the trial court did not abuse its discretion in refusing Phillips’ nonaggravated robbery instruction.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1204916/', '1204916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the violent nature of Phillips’ crimes, the inherent dangers of his attempted escape, and the exorbitant risk to life and limb of numerous innocent persons created by the totality of his conduct, we find that the sentence imposed upon him does not shock the conscience of the court and society.', 'sentencing', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1204916/', '1204916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon a consideration of the totality of the circumstances of this case, we find that the sentence imposed upon Phillips was not disproportionate to the character and degree of the offenses of which he was convicted.', 'sentencing', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1204916/', '1204916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons herein stated, we find that the circuit court did not abuse its discretion in refusing to instruct the jury on the lesser included offense of nonaggravated robbery, and we find that the 140 year sentence was constitutionally proportionate to the character and degree of the offenses committed by Phillips.', 'sentencing', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1204916/', '1204916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the June 13,1995, order of the Circuit Court of Wood County.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1204916/', '1204916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 248 (1990) (per curiam), we affirmed a sentence of 100 years for attempted aggravated robbery.', 'sentencing', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1204916/', '1204916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the June 13, 1995, order of the Circuit Court of Wood County.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1204916/', '1204916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'as to the motor-vehicle-theft conviction, we affirm in part and reverse in part, and remand for a new trial on the charge of motor-vehicle theft.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1560476/', '1560476') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the circumstances the prosecutor’s remarks do not constitute reversible error.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1561512/', '1561512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant’s contentions are without merit.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1561512/', '1561512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Using this test, we find that the case was not close and there was ample evidence in the record to support the jury’s verdict.', 'general', 'Zimmerman v. State', 'https://www.courtlistener.com/opinion/1561512/', '1561512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the decision of the Superior Court but we remand the case to the Superior Court to rearrange the sentencing to conform to 11
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the evidence was sufficient to support the defendant’s conviction for Class D felony evading arrest.', 'general', 'State v. Turner', 'https://www.courtlistener.com/opinion/1670534/', '1670534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the one year imprisonment penalty provided in Tennessee Code Annotated section 55-50-504(a)(2) is a valid sentence for subsequent violations of the statute.', 'sentencing', 'State v. Turner', 'https://www.courtlistener.com/opinion/1670534/', '1670534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the trial court did not err in sentencing the defendant to a one-year term of confinement for driving on a revoked license, fourth offense, since that sentence is a valid punishment for this Class A misdemeanor.', 'sentencing', 'State v. Turner', 'https://www.courtlistener.com/opinion/1670534/', '1670534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the change in the language of the statute providing an increased penalty for a second or subsequent violation of the statute was intentional despite the misdemeanor status of the offense.', 'general', 'State v. Turner', 'https://www.courtlistener.com/opinion/1670534/', '1670534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Criminal Appeals’ holding that the evidence was sufficient to support the defendant’s conviction for Class D felony evading arrest.', 'general', 'State v. Turner', 'https://www.courtlistener.com/opinion/1670534/', '1670534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the Court of Criminal Appeals.', 'general', 'State v. Turner', 'https://www.courtlistener.com/opinion/1670534/', '1670534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the Petition for Rehearing in this case, it is ordered that the opinion heretofore filed, Opinion No.', 'general', 'Nolte v. Gibbs International, Inc.', 'https://www.courtlistener.com/opinion/1335546/', '1335546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Nolte v. Gibbs International, Inc.', 'https://www.courtlistener.com/opinion/1335546/', '1335546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following a review of the record, we conclude that the trial court did not abuse its discretion.', 'general', 'State v. Bell', 'https://www.courtlistener.com/opinion/3937237/', '3937237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that there is no new
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The conviction and sentence were appealed to this court, and we affirmed the trial court’s judgment.', 'sentencing', 'State v. Bell', 'https://www.courtlistener.com/opinion/3937237/', '3937237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), we held that § 4B1.', 'general', 'United States v. Jackson', 'https://www.courtlistener.com/opinion/21490/', '21490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Fitzhugh, we held that the commentary to § 4B1.', 'general', 'United States v. Jackson', 'https://www.courtlistener.com/opinion/21490/', '21490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jackson, we held that the burglary of a building is not a “crime of violence” within the meaning of § 4B1.', 'general', 'United States v. Jackson', 'https://www.courtlistener.com/opinion/21490/', '21490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 85 (1999), an immigration case, we held that UUV is a crime of violence under 18 U.', 'general', 'United States v. Jackson', 'https://www.courtlistener.com/opinion/21490/', '21490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pursuant to this authority, we conclude that UUV’s risk to persons is likewise sufficient to render UUV, as a categorical matter, a crime of violence under § 4B1.', 'general', 'United States v. Jackson', 'https://www.courtlistener.com/opinion/21490/', '21490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The consideration of specific conduct was dictum, because we concluded that the crime at issue, attempted unauthorized entry of an inhabited dwelling, always presents the requisite risk.', 'general', 'United States v. Jackson', 'https://www.courtlistener.com/opinion/21490/', '21490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'United States v. Jackson', 'https://www.courtlistener.com/opinion/21490/', '21490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 211 (1993), this court held that by amending U.', 'general', 'United States v. Jackson', 'https://www.courtlistener.com/opinion/21490/', '21490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 261a (“Based on the reasoning of our prior opinion, we find that the [FEC] is entitled to judgment as a matter of law.', 'general', 'Citizens United v. Federal Election Commission', 'https://www.courtlistener.com/opinion/1741/', '1741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reasons we uphold the application of BCRA §§201 and 311 to the ads, we affirm their application to Hillary.', 'general', 'Citizens United v. Federal Election Commission', 'https://www.courtlistener.com/opinion/1741/', '1741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons hereafter given, we hold that the Government’s first contention must be rejected, and that as to its second, which the Court of Appeals accepted, a new trial must be ordered.', 'general', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the circumstances of this case it was prejudicial error for the trial judge to permit cross-examination of petitioner on his plea of the Fifth Amendment privilege before the grand jury, and that Halperin must therefore be given a new trial on Counts 5, 6, and 7.', 'plea', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons given we hold that the judgments below must be reversed, and the cases remanded to the District Court for further proceedings consistent with this opinion.', 'general', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the other hand, since we hold that petitioners must have a new trial, the error may be corrected.', 'general', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '494, where this Court held that a defendant’s failure to take the stand at his first trial to deny testimony as to an incriminating admission could be used on cross-examination at the second trial, where he did take the stand, to impugn the credibility of his denial of the same admission.', 'general', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, in effect, that when a criminal defendant takes the stand, he waives his privilege completely and becomes subject to cross-examination impeaching his credibility just like any other witness: “His waiver is not partial;', 'general', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed hereafter, we conclude that these convictions must be reversed, and the petitioners granted a new trial.', 'general', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since, under the judge’s charge, the convictions on Count 1 might have rested on an impermissible ground, we conclude that they cannot stand, and the petitioners must be given a new trial as to this Count.', 'general', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that in the circumstances presented here Raffel is not controlling, and that this cross-examination was not permissible.', 'general', 'Grunewald v. United States', 'https://www.courtlistener.com/opinion/105508/', '105508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we conclude that the District Court was in error, the judgment is reversed and the case is remanded for further proceedings.', 'general', 'United States v. Cores', 'https://www.courtlistener.com/opinion/105684/', '105684') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we conclude that an indictment under 2 U.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/106407/', '106407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the stops and questioning at issue may be made in the absence of any individualized suspicion at reasonably located checkpoints.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that stops for brief questioning routinely conducted at permanent checkpoints are consistent with the Fourth Amendment and need not be authorized by warrant.', 'search_seizure', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Brignoni-Ponce, supra, at 886-887, where we noted that “[tjhe likelihood that any given person of Mexican ancestry is an alien is high enough to make Mexican appearance a relevant factor although we held that apparent Mexican ancestry by itself could not create the reasonable suspicion required for a roving-patrol stop.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not address these holdings specifically, as we conclude that no warrant is needed.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the facts of the case, we concluded that the stop was impermissible because reasonable suspicion was lacking.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the interference with Fourth Amendment interests involved in such a stop was “modest,” 422 U.', 'search_seizure', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals for the Ninth Circuit and remand the case with directions to affirm the conviction of Martinez-Fuerte and to remand the other cases to the District Court for further proceedings.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the judgment of the Court of Appeals for the Fifth Circuit, which had affirmed the conviction of Sifuentes.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that when the preliminary facts relevant to Rule 801(d)(2)(E) are disputed, the offering party must prove them by a preponderance of the evidence.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Lonardo’s out-of-court statements were properly admitted against petitioner.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Confrontation Clause does not require a court to embark on an *184independent inquiry into the reliability of statements that satisfy the requirements of Rule 801(d)(2)(E).', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '387 (1986), we held that the first of these two generalized inquiries, unavailability, was not required when the hearsay statement is the out-of-court declaration of a co-conspirator.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, we conclude that the second inquiry, independent indicia of reliability, is also not mandated by the Constitution.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that even if the defendant denies one or more elements of the crime, he is entitled to an entrapment instruction whenever there is sufficient evidence from which a reasonable jury could find entrapment.', 'general', 'Mathews v. United States', 'https://www.courtlistener.com/opinion/112012/', '112012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that a defendant may both deny the acts *66and other elements necessary to constitute the crime charged and at the same time claim entrapment, the high risks to him make it unlikely as a strategic matter that he will choose to do so.', 'general', 'Mathews v. United States', 'https://www.courtlistener.com/opinion/112012/', '112012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Act is constitutional.', 'general', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bowsher, we held that “Congress cannot reserve for itself the power of removal of an officer charged with the execution of the laws except by impeachment.', 'general', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '- In light of the foregoing history and precedent, we conclude that the principle of separation of powers does not absolutely prohibit Article III judges from serving on commissions such as that created by the Act.', 'general', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although it is a judgment that is not without difficulty, we conclude that the participation of federal judges on the Sentencing Commission does not threaten, either in fact or in appearance, the impartiality of the Judicial Branch.', 'sentencing', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in creating the Sentencing Commission— an unusual hybrid in structure and authority — Congress neither delegated excessive legislative power nor upset the constitutionally mandated balance of powers among the coordinate Branches.', 'sentencing', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we concluded that those powers were not “judicial .', 'general', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the consistent responsibility of federal judges to pronounce sentence , within the statutory range established by Congress, we find that the role of the Commission in promulgating guidelines for the exercise of that judicial function bears considerable similarity to the role of this Court in establishing rules of procedure under the various enabling Acts.', 'sentencing', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Keeble, for example, we held that the defendant was entitled to an instruction on the lesser offense of simple assault:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the mailing of the cashed checks to the drawee banks could not supply the mailing element of the mail fraud charges.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on Kann, this Court held that these mailings were not in execution of the scheme as required by the statute because it was immaterial to the defendants how the oil company went about collecting its payment.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, however, that in the absence of any evidence that the tax levy was increased as part of the fraud, the mailing element of the offense could not be supplied by mailings “made or caused to be made under the imperative command of duty imposed by state law.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Schmuck’s conviction was consistent with the statutory definition of mail fraud and that he was not entitled to a lesser included offense instruction on odometer tampering.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, when officials of a school district embezzled tax funds over the course of several years, we held that no mail fraud had occurred even though the success of the scheme plainly depended on the officials’ causing tax bills to be sent by mail (and thus tax payments to be received) every year.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'United States, we concluded that even though defendants who cashed checks obtained as part of a fraudulent scheme knew that the bank cashing the checks would send them by mail to a drawee bank for collection, they did not thereby violate the mail fraud statute, because upon their receipt of the cash “[t]he scheme .', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, when those officials caused the school district to pay by mail credit card bills — a step plainly necessary to enable their continued fraudulent use of the credit card — we concluded that no mail fraud had occurred.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the agents had a reasonable basis to suspect that respondent was transporting illegal drugs on these facts.', 'general', 'United States v. Sokolow', 'https://www.courtlistener.com/opinion/112239/', '112239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, 30 (1968), we held that the police can stop and briefly detain a person for investigative purposes if the officer has a reasonable suspicion supported by articulable facts that criminal activity “may be afoot,” even if the officer lacks probable cause.', 'probable_cause', 'United States v. Sokolow', 'https://www.courtlistener.com/opinion/112239/', '112239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'United States, supra, we held that the retroactive application of the obscenity standards announced in Miller v.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that “[n]o legitimate state interest would have been served by requiring repetition of a patently futile objection,” we held that the Alabama procedural ruling did not preclude our consideration of the defendant’s constitutional claim.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the gravity of the State’s interests in this context, we find that Ohio may constitutionally proscribe the possession and viewing of child pornography.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the convictions on due process grounds because the South Carolina Supreme Court’s expansion of the statute was unforseeable and therefore the petitioners had no reason to suspect that their conduct was criminal.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To conclude, although we find Osborne’s First Amendment arguments unpersuasive, we reverse his conviction and re*126mand for a new trial in order to ensure that Osborne’s conviction stemmed from a finding that the State had proved each of the elements of § 2907.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ferber, we affirmed a conviction under a New York statute that made it a crime to promote the “ ‘lewd exhibition of [a child’s] genitals.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’” In light of this construction, we rejected the petitioners’ facial challenge to the statute as written, and we affirmed the petitioners’ convictions under the section after finding that the petitioners had fair notice that their conduct was criminal.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '18, we found that the statute was not overbroad because only “a tiny fraction of materials within the statute’s reach” was constitutionally protected.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '286 (1969), this Court held that the Travel Act did not incorporate the common-law definition of “extortion,” because that definition had been expanded in many States by the time the Act was passed, id.', 'general', 'Taylor v. United States', 'https://www.courtlistener.com/opinion/112435/', '112435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a person has been convicted of burglary for purposes of a § 924(e) enhancement if he is convicted of any crime, regardless of its exact definition or label, having the basic elements of unlawful or unprivileged entry into, or remaining in, a building or structure, with intent to commit a crime.', 'general', 'Taylor v. United States', 'https://www.courtlistener.com/opinion/112435/', '112435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that an offense constitutes “burglary” for purposes of a § 924(e) sentence enhancement if either its statutory definition substantially corresponds to “generic” burglary, or the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the defendant.', 'sentencing', 'Taylor v. United States', 'https://www.courtlistener.com/opinion/112435/', '112435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because petitioners have not shown that their joint trial subjected them to any legally cognizable prejudice, we conclude that the District Court did not abuse its discretion in denying petitioners’ motions to sever.', 'general', 'Zafiro v. United States', 'https://www.courtlistener.com/opinion/112812/', '112812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '29 We hold that the parking and sidewalk area outside the Exxon station was a public place.', 'general', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Murphy, we held that the collateral-estoppel inquiry involved a two-part analysis: (1) determining exactly what facts were necessarily decided in the first proceeding, and (2) determining whether those necessarily decided facts constitute essential elements of the offense in the second trial.', 'general', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '75 We held that this assumption was incorrect76 Because the defendant argued that the State was barred completely from proving the commission of DWI, this Court never had occasion to address whether the prior finding in the administrative license-suspension hearing could have been used to bar reliti-gation of issues raised in a motion to suppress.', 'suppression', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that, when the validity of an arrest or detention is an element of the charged offense, litigating the validity of the seizure as a suppression issue is inappropriate.', 'suppression', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '83 We do not often say what standard applies in a motion-to-suppress setting, and we are unaware of any cases explicitly stating the State’s standard of proof in establishing reasonable suspicion,84 but we conclude that the appropriate standard is the one that applies to most85 constitutional suppression issues: preponderance of the evidence.', 'suppression', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After noting the distinctions between double jeopardy and “collateral estop-pel,” 36 we held that if a jury determines a punishment-phase special issue in the defendant’s favor, “the doctrine of collateral estoppel bars the State from relitigating it in a second trial”37 and affirmed the Court of Appeals.', 'general', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the challenged conditions do not constitute an illegal sentence and, as such, dismiss his appeal.', 'dismissal', 'United States v. John Robert Andis', 'https://www.courtlistener.com/opinion/782464/', '782464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the doctrine of imperfect self-defense does not exist in Michigan law as a freestanding defense mitigating murder to voluntary manslaughter, although we recognize that factual circumstances that have been characterized as imperfect self-defense may negate the malice element of second-degree murder.', 'general', 'People v. Reese', 'https://www.courtlistener.com/opinion/824885/', '824885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When analyzing the elements of manslaughter in light of defendant’s self-defense claim, we conclude that the Court of Appeals erred in its ruling on the sufficiency of the prosecution’s evidence to sustain defendant’s manslaughter conviction.', 'general', 'People v. Reese', 'https://www.courtlistener.com/opinion/824885/', '824885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse in part the Court of Appeals’ judgment,1 affirm the trial court’s verdict of manslaughter, and remand this case to the Court of Appeals for further consideration of defendant’s remaining issue on appeal.', 'general', 'People v. Reese', 'https://www.courtlistener.com/opinion/824885/', '824885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that MCL 750.', 'general', 'People v. Moreno', 'https://www.courtlistener.com/opinion/825050/', '825050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute did not abrogate this right.', 'general', 'People v. Moreno', 'https://www.courtlistener.com/opinion/825050/', '825050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Consistently *52with the common-law rule, we conclude that the prosecution must establish that the officers’ actions were lawful.', 'general', 'People v. Moreno', 'https://www.courtlistener.com/opinion/825050/', '825050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Court of Appeals in this case relied on Ventura and extended its holding to the context of illegal entries of the home, we reverse the judgment of the Court of Appeals and remand this matter to the trial court.', 'general', 'People v. Moreno', 'https://www.courtlistener.com/opinion/825050/', '825050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Court of Appeals in this case relied on Ventura and extended its broader principle to the context of unlawful entry of the home, we reverse the judgment of the Court of Appeals and remand this matter to the trial court.', 'general', 'People v. Moreno', 'https://www.courtlistener.com/opinion/825050/', '825050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '132 NW2d 69 (1965), this Court held that “one may use such reasonable force as is necessary to prevent an illegal attachment and to resist an illegal arrest” without violating MCL 750.', 'general', 'People v. Moreno', 'https://www.courtlistener.com/opinion/825050/', '825050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This historical context makes this case altogether distinguishable from Dupree in which this Court held that an individual charged with being a felon in possession of a firearm can raise the common-law affirmative defense of self-defense even though the felon-in-possession statute is silent regarding self-defense, because the Legislature had never expressly included self-defense in the statute and then removed it.', 'general', 'People v. Moreno', 'https://www.courtlistener.com/opinion/825050/', '825050') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '40(1), and out of recognition that 15 points for “predatory conduct” constitutes the highest number of points available under OV 10 and that “preoffense conduct” is being used to define “predatory conduct,” we conclude that the latter term does not encompass any “preoffense conduct,” but rather only those forms of “preoffense conduct” that are commonly understood as being “predatory” in nature, e.', 'general', 'People v. Huston', 'https://www.courtlistener.com/opinion/827277/', '827277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a person walking alone at night in a parking lot while two armed people hidden from that person’s view lie in wait to rob that person is a “vulnerable” victim because he or she would have a “readily apparent susceptibility .', 'general', 'People v. Huston', 'https://www.courtlistener.com/opinion/827277/', '827277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that defendant engaged in “predatory conduct” to “exploit[] .', 'general', 'People v. Huston', 'https://www.courtlistener.com/opinion/827277/', '827277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court properly assessed 15 points for OV 10, we reverse the judgment of the Court of Appeals and reinstate the trial court’s judgment of sentence.', 'sentencing', 'People v. Huston', 'https://www.courtlistener.com/opinion/827277/', '827277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Therefore, we reverse the judgment of the Court of Appeals and reinstate the trial court’s judgment of sentence.', 'sentencing', 'People v. Huston', 'https://www.courtlistener.com/opinion/827277/', '827277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because the sexual delinquency statute, MCL 767.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '61a, we hold that separate juries are not necessarily required when a criminal defendant is charged with being a sexual delinquent in addition to another sexual offense.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that separate juries are not necessarily required when a criminal defendant is charged with a sexual offense as well as with being a sexually delinquent person.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Helzer,1 this Court held that when a criminal defendant is charged with being a sexually delinquent person in relation to an underlying sexual offense, separate juries must determine a defendant’s guilt of the sexual delinquency charge and the underlying charge.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Helzer,8 this Court held that separate juries are required when a criminal defendant is charged both with a principal sexual offense and with being a sexually delinquent person.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that Helzer wrongly created a rule mandating bifurcated trials when a defendant is charged with being a sexually delinquent person in addition to an underlying criminal sexual offense, that does not end our inquiry regarding whether Helzer should be overruled.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”32 We conclude that these criteria generally weigh in favor of overruling Helzer.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Although we conclude that the Helzer rule is not practically unworkable, it does impose unnecessary enormous costs on the judicial system because it requires empaneling two juries when the need for this has not been specifically determined.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”33 We conclude that Helzer has not become so embedded in, or fundamental to, society’s general expectations that overruling it would produce significant dislocations.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '61a, we conclude that the portion of Helzer requiring bifurcated trials should be overruled.', 'general', 'People v. Breidenbach', 'https://www.courtlistener.com/opinion/828633/', '828633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the facts of this case, where the jury was presented with no evidence other than that a child was present in a home where criminal activity occurred, we hold that a rational fact-finder could not conclude beyond a reasonable doubt that defendant “tend[ed] to cause” the child to become delinquent or neglected so as to “tend to come” under family court jurisdiction, as those terms are defined by MCL 712A.', 'general', 'People v. Tennyson', 'https://www.courtlistener.com/opinion/830335/', '830335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Again, we conclude that the evidence is insufficient to allow a rational fact-finder to make such a finding.', 'general', 'People v. Tennyson', 'https://www.courtlistener.com/opinion/830335/', '830335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking this evidence in the light most favorable to the prosecutor, we conclude that a rational trier of fact could not reasonably find that defendant’s home was rendered an “unfit place” for the child to live “by reason of” defendant’s criminal conduct where there was no evidence at all that the child was even aware of this criminality.', 'general', 'People v. Tennyson', 'https://www.courtlistener.com/opinion/830335/', '830335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because this result has never before been reached by courts of this state, and because we believe that such result was never intended by the Legislature, we reverse in part the judgment of the Court of Appeals, vacate defendant’s conviction under MCL 750.', 'general', 'People v. Tennyson', 'https://www.courtlistener.com/opinion/830335/', '830335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse in part the judgment of the Court of Appeals, vacate defendant’s conviction under MCL 750.', 'general', 'People v. Tennyson', 'https://www.courtlistener.com/opinion/830335/', '830335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this criminal case, we hold that the traditional common law affirmative defense of self-defense may be interposed to a charge of being a felon in possession of a firearm, MCL 750.', 'general', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that self-defense is an available defense under these facts.', 'general', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the trial court’s modified jury instruction on the momentary innocent possession defense to being a felon in possession was not harmless error.', 'jury_instruction', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the Court of Appeals properly ruled that the trial court’s modified jury instruction on the momentary innocent possession defense was erroneous.', 'jury_instruction', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After thoroughly reviewing the record, we conclude that neither defendant nor the prosecution properly raised the affirmative defense of duress before the trial court.', 'general', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*704However, we conclude that defendant properly raised the common law affirmative defense of self-defense before the trial court.', 'general', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the trial court’s jury instruction on the momentary innocent possession defense was not harmless error.', 'jury_instruction', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having necessarily limited our analysis to the specific issue properly raised and preserved before the trial court, we conclude that the traditional common law affirmative defense of self-defense is generally available to a defendant charged with being a felon in possession if supported by sufficient evidence.', 'general', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Court of Appeals’ result and remand for further proceedings consistent with this opinion.', 'general', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Approximately five months following this trial, we affirmed and adopted the Court of Appeals’ holding in Hernandez-Garcia that the momentary innocent possession of a concealed weapon is not a defense to the charge of unlawfully carrying a concealed weapon, MCL 750.', 'general', 'People v. Dupree', 'https://www.courtlistener.com/opinion/830716/', '830716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion by failing to admit evidence of the victim’s intoxication because it was relevant to the element of causation in MCL 257.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the error resulted in a miscarriage of justice, which therefore requires reversal under MCL 769.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the facts of this case, the trial court abused its discretion by refusing to admit the evidence because it was relevant to the element of proximate causation in MCL *192257.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*203Applying these standards to the facts of this case, we hold that the trial court abused its discretion by failing to admit the evidence of the victim’s BAC.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that 11-carboxy-THC is not a schedule 1 controlled substance under MCL 333.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the Derror majority’s interpretation of the statute was probably unconstitutional, because we hold that 11-carboxy-THC *212is not a schedule 1 controlled substance, defendant’s conviction under MCL 257.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion by failing to admit the evidence of the victim’s intoxication because it was relevant to the issue of causation in MCL 257.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we hold that the error resulted in a miscarriage of justice, requiring reversal under MCL 769.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 In Derror, a majority of this Court held that 11-carboxy-THC, a byproduct of metabolism created when the body breaks down the psychoactive ingredient of marijuana, is a schedule 1 controlled substance under MCL 333.', 'general', 'People v. Feezel', 'https://www.courtlistener.com/opinion/831214/', '831214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that respondent may certainly claim procedural error in an action brought by the state to terminate this right if the state fails to comply with the required procedures and its failure may be said to have affected the outcome of the case.', 'general', 'In Re Rood', 'https://www.courtlistener.com/opinion/837290/', '837290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court clearly erred by ruling that respondent was sufficiently responsible for his own lack of participation to excuse the state’s failures to inform him of the ongoing proceedings.', 'general', 'In Re Rood', 'https://www.courtlistener.com/opinion/837290/', '837290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Court of Appeals.', 'general', 'In Re Rood', 'https://www.courtlistener.com/opinion/837290/', '837290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16 We affirm the judgment of the Court of Appeals and remand this case to the trial court for proceedings consistent with this opinion.', 'general', 'In Re Rood', 'https://www.courtlistener.com/opinion/837290/', '837290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*686We hold that Cunningham does not require us to modify our previous decision.', 'general', 'People v. McCuller', 'https://www.courtlistener.com/opinion/842329/', '842329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our previous opinion, we held that a sentencing court must score both the offense variables (OVs) and the prior record variables (PRVs) to arrive at a defendant’s minimum sentence range.', 'sentencing', 'People v. McCuller', 'https://www.courtlistener.com/opinion/842329/', '842329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 We held that the sentencing court had not violated Blakely by engaging in judicial fact-finding to score the OVs necessary to calculate the recommended minimum sentence range.', 'sentencing', 'People v. McCuller', 'https://www.courtlistener.com/opinion/842329/', '842329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm defendant’s sentence.', 'sentencing', 'People v. McCuller', 'https://www.courtlistener.com/opinion/842329/', '842329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Originally, this Court held the case in abeyance for the matter of People v Drohan, see 472 Mich 881 (2005).', 'general', 'People v. McCuller', 'https://www.courtlistener.com/opinion/842329/', '842329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistently with McDonald, Hanna, Torres, Cornell, Mendoza, and Nickens, we hold that MCL 768.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons we stated, we hold that MCL 768.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '562 NW2d 447 (1997), we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nickens, supra at 624, we held that assault with intent to commit CSC involving sexual penetration, MCL 750.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*121In Cornell, supra at 357, this Court held that, under MCL 768.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, Justice CORRIGAN has not cited, and cannot cite, a single case where this Court held that pursuant to MCL 768.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this caselaw, the error was plain and we conclude that it seriously affected the “fairness, integrity or public reputation of judicial proceedings.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was no indication that the Legislature intended to abrogate the common law, this Court held that sexual penetration of a victim who is at least 13 but less than 16 constitutes a strict liability offense and, therefore, “reasonable mistake of age” is not a defense.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that a trier of fact may not *158consider “cognate lesser offenses, which are only ‘related’ or of the same ‘class or category’ as the greater offense and may contain some elements not found in the greater offense.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Yet this Court held consistently, even before Aaron, that an instruction for second-degree murder was appropriate where the defendant was charged with first-degree felony murder.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McDonald, this Court held that assault and battery was included in a charge of felonious assault, and thus upheld an assault and battery conviction even though the defendant was charged only with felonious assault.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly [to the analysis in Salinas], we conclude that both the first-degree and second-degree assault statutes proscribe but one offense — that of assault.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the offense upon which the trial court instructed the jury is a lesser degree crime of the one with which he was charged and the two crimes, namely assault, are not separate and distinct from one another, we conclude that appellant was *172given sufficient notice to satisfy the requirements of [the state constitution] and the Sixth Amendment.', 'general', 'People v. Nyx', 'https://www.courtlistener.com/opinion/842356/', '842356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We recognized this requirement when we held that double jeopardy analysis for compound offenses relies “not upon the theoretical elements of the offense but upon proof of facts actually adduced.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, we held that the theft of property belonging to two different owners comprised a single larceny because the property was taken at the same time from one granary.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “Const 1963, art 1, § 15 prohibits a second prosecution for an offense arising out of the same criminal act unless it appears from the record that the interests of the State of Michigan and the jurisdiction which initially prosecuted are substantially different.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court correctly denied defendant’s request for the instruction.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '664 NW2d 685 (2003), this Court held that manslaughter, both voluntary and involuntary, is a necessarily included lesser offense of murder.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '684 NW2d 730 (2004), where this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Heflin, supra at 497, this Court held that statutory involuntary manslaughter is a cognate lesser offense3 of murder, not a necessarily included lesser offense.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Heflin, supra at 505, this Court held that the trial court did not err in refusing to instruct the jury regarding the offense of statutory involuntary manslaughter despite giving instructions on murder and voluntary manslaughter.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*71Comparing the elements of these offenses, we conclude that statutory involuntary manslaughter under MCL 750.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we concluded that the elements of common-law manslaughter are completely included in the elements of murder.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the part of the judgment of the Court of Appeals that held to the contrary and reinstate defendant’s convictions of second-degree murder and possession of a firearm during the commission of a felony, MCL 750.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse this aspect of the Court of Appeals judgment and reinstate defendant’s convictions of second-degree murder and felony-firearm.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Holtschlag, supra at 21, this Court held that “[i]f a homicide is not voluntary manslaughter or excused or justified, it is, generally, either murder or involuntary manslaughter.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the elements of involuntary manslaughter are included in the offense of murder be*78cause involuntary manslaughter’s mens rea is included in murder’s greater mens rea.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842958/', '842958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '524 NW2d 682 (1994), this Court held that “[i]nconsistency of defenses is not enough to mandate severance [under MCR 6.', 'general', 'People v. Pipes', 'https://www.courtlistener.com/opinion/845993/', '845993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Banks, this Court held that a Bruton error does not require reversal where “the properly admitted evidence of guilt is so overwhelming, and the prejudicial effect of the *280codefendant’s admission is so insignificant by comparison, that it is clear beyond a reasonable doubt that the improper use of the admission was harmless error.', 'general', 'People v. Pipes', 'https://www.courtlistener.com/opinion/845993/', '845993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In this case, for the same reasons that we find that defendants cannot show prejudice, defendants cannot show that the error “seriously affected the fairness, integrity, or public reputation of the proceedings” or that they are actually innocent.', 'general', 'People v. Pipes', 'https://www.courtlistener.com/opinion/845993/', '845993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Court of Appeals judgment and reinstate defendants’ first-degree murder convictions.', 'general', 'People v. Pipes', 'https://www.courtlistener.com/opinion/845993/', '845993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under Michigan law, a defendant who intends to aid, abet, counsel, or procure the commission of a crime, is liable for that crime as well as the natural and probable consequences of that crime.', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when the Legislature abolished the distinction between principals and accessories, it intended for all offenders to be convicted of the intended offense, in this case aggravated assault, as well as the natural and probable consequences of that offense, in this case death.', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant must possess the criminal intent to aid, abet, procure, or counsel the commission of an offense.', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in People v Chapman, this Court held that a defendant was “ ‘responsible criminally for what of wrong flows directly from his corrupt intentions .', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the jury properly convicted the defendant of rape under an accomplice theory of liability because that crime directly flowed from the original corrupt intention to aid adultery.', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We fail to see how Justice Kelly can conclude that we concluded that defendant was aware of or shared Pannell’s intent to kill.', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and reinstate defendant’s conviction of second-degree murder.', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the *16Court of Appeals erred in reversing defendant’s conviction of second-degree murder, we reverse the judgment of the Court of Appeals and reinstate defendant’s conviction.', 'general', 'People v. Robinson', 'https://www.courtlistener.com/opinion/846032/', '846032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, to qualify as felony murder, the homicide must be incident to the felony and associated with it as one of its hazards.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Aaron, we held that a homicide that occurred during the commission of a felony constitutes murder only if the prosecutor specifically proves the existence of malice.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a divided decision, this Court held that this “transactional approach” was contrary to the language of the statute and that in order for a larceny to be elevated to unarmed robbery, the force and the felonious taking must occur contemporaneously.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that “perpetration” encompasses acts by a defendant that occur outside the definitional elements of the predicate felony and includes acts that occur during the unbroken chain of events surrounding that felony.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the term “perpetration” encompasses acts beyond the definitional elements of the predicate felony, to include those acts committed within the res gestae of that felony.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this analysis, we conclude that the trial court here did not err in denying defendant’s motion for a directed verdict of acquittal.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the scene of the murders was sufficiently close in both time and distance from the scene of the home invasion to support convictions of felony murder.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence does not support the conclusion that defendant drove the wrong way by accident or *140otherwise acted in a merely grossly negligent manner, we conclude that a rational view of the evidence does not support an involuntary manslaughter instruction.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these factors to the instant case, we conclude that the trial court did not err in denying defendant’s motion to direct a verdict of acquittal because, viewing the evidence in a light most favorable to the prosecutor, a reasonable juror could conclude beyond a reasonable doubt that the murders were within the res gestae of the predicate home invasion.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals and remand this case to that Court for consideration of defendant’s other issues.', 'general', 'People v. Gillis', 'https://www.courtlistener.com/opinion/846560/', '846560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court did err in scoring OV 13, and because this error affected the statutory sentencing guidelines range, we remand to the trial court for resentencing.', 'sentencing', 'People v. Francisco', 'https://www.courtlistener.com/opinion/846742/', '846742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court erred in scoring OV13, and that this error affected the statutory sentencing guidelines range, we remand to the trial court for resentencing pursuant to the correct guidelines range.', 'sentencing', 'People v. Francisco', 'https://www.courtlistener.com/opinion/846742/', '846742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Unlike the dissent, we conclude that when a trial court sentences a defendant in reliance upon an inaccurate guidelines range, it does so in rebanee upon inaccurate information.', 'sentencing', 'People v. Francisco', 'https://www.courtlistener.com/opinion/846742/', '846742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”47 We hold that the prosecution, in proving OUIL causing death, must establish beyond a reasonable doubt that (1) the defendant was operating his or her motor vehicle in violation of MCL 257.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '72 In Cornell, we held that instructional error based on the misapplication of a statute is generally considered non-constitutional error.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Lukity,74 we held that MCL 769.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In rejecting the defendants’ due process arguments, this Court held that OUIL causing death is a general intent crime and that “the culpable act that the Legislature wishes to prevent is the one in which a person becomes intoxicated and then decides to drive.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Lardie Court erred in holding that the defendant’s “intoxicated driving”3 must be a substantial cause of the victim’s death.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the trial court erred because the word “cause” in § 625(4) is a legal term of art normally not within the common understanding of jurors, and thus, simply reading the statute to the jury was insufficient.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Lukity standard to the alleged instructional error in the present case, we conclude that any error on the part of the trial court in merely reading the statute and failing to explain the causation element of OUIL causing death was harmless.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court’s other instructional errors were harmless, the Court of Appeals is to consider on remand only whether the trial court’s multiple references to the stipulation constituted error requiring reversal — i.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recent cases where we found that instructional error required reversal include People v Mass, 464 Mich 615;', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Large, we reverse the judgment of the Court of Appeals and remand the case to the district court for reconsideration of whether to bind defendant over on the charge of OUIL causing death in light of the principles set forth in this opinion.', 'general', 'People v. Schaefer', 'https://www.courtlistener.com/opinion/848617/', '848617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the burden of proof regarding the existence of a valid prescription was on the defendant.', 'general', 'People v. Perkins', 'https://www.courtlistener.com/opinion/848612/', '848612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a person whose property is stolen from his presence may take steps to retain possession, and the offender may react violently, we conclude that the offense of larceny from a person, “by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense.', 'general', 'People v. Perkins', 'https://www.courtlistener.com/opinion/848612/', '848612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the dismissal of the charge against defendant, concluding that the prosecution presented sufficient evidence to bind defendant over on the charge of assault with intent to commit criminal sexual conduct involving sexual penetration.', 'dismissal', 'People v. Starks', 'https://www.courtlistener.com/opinion/848626/', '848626') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We conclude that surveillance by licensed private investigators that contributes to the goal of obtaining information, as permitted by the Private Detective License Act, MCL 338.', 'general', 'Nastal v. Henderson & Associates Investigations, Inc', 'https://www.courtlistener.com/opinion/848677/', '848677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, given the plain and ordinary import of the terms used by the Legislature, we conclude that the phrase “conduct that serves a legitimate purpose” means conduct that contributes to a valid purpose that would otherwise be within the law irrespective of the criminal stalking statute.', 'general', 'Nastal v. Henderson & Associates Investigations, Inc', 'https://www.courtlistener.com/opinion/848677/', '848677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sherbine, this Court held that the exclusionary rule is the proper remedy for a violation of MCL 780.', 'general', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sloan, this Court held that a magistrate must base the probable-cause determination on the record (i.', 'general', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the good-faith exception to the exclusionary rule in this case, we conclude that the circuit court erred by suppressing the marijuana, firearm, and firefighter paraphernalia.', 'suppression', 'People v. Goldston', 'https://www.courtlistener.com/opinion/848710/', '848710') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the circuit court’s ruling suppressing the evidence and remand for reinstatement of the charges against defendant.', 'suppression', 'People v. Goldston', 'https://www.courtlistener.com/opinion/848710/', '848710') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 Applying that standard, we hold that there was sufficient evidence in each case to support the felony-firearm convictions, and we affirm both defendants’ convictions.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/848731/', '848731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, applying the general aiding and abetting standard to the facts of this case, we hold that there was sufficient evidence in the record to establish that defendant performed acts or gave encouragement that assisted in the commission of the felony-firearm violation.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/848731/', '848731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Applying this standard, we hold that there was sufficient evidence in each case to support the felony-firearm convictions, and we affirm both defendants’ convictions.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/848731/', '848731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the statute, the proper standard for establishing felony-firearm under an aid*59ing and abetting theory is whether the defendant’s words or deeds “procure[d], counseled], aid[ed], or abet[ted]” another to carry or have in his possession a firearm during the commission or attempted commission of a felony-firearm offense.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/848731/', '848731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Moore’s felony-firearm conviction.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/848731/', '848731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Harris’s felony-firearm convictions.', 'general', 'People v. Moore', 'https://www.courtlistener.com/opinion/848731/', '848731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, however, we conclude that materiality is not an element, then the holding in Gaudin has no bearing on our determination.', 'general', 'People v. Lively', 'https://www.courtlistener.com/opinion/848721/', '848721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the broad scope of the statutory phrase “any matter or thing,” we conclude that the Legislature intended that a willfully false statement about any matter or thing concerning which an oath was authorized or required falls within the statutory definition of perjury and thus may be charged as perjury if a prosecutor so chooses.', 'general', 'People v. Lively', 'https://www.courtlistener.com/opinion/848721/', '848721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these sentences do not violate the Eighth Amendment’s prohibition on cruel and unusual punishment.', 'sentencing', 'State v. Berger', 'https://www.courtlistener.com/opinion/867414/', '867414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 51 In light of the legislature’s intent to deter and punish those who participate in the child pornography industry, and Berger’s commission of twenty separate offenses, we hold that the twenty consecutive ten-year sentences are not grossly disproportionate to his crimes.', 'sentencing', 'State v. Berger', 'https://www.courtlistener.com/opinion/867414/', '867414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶23 Given this history, we conclude that the legislature had a “reasonable basis for believing” that mandatory and lengthy prison sentences for the possession of child pornography would “advance [] the goals of [Arizona’s] criminal justice system in [a] substantial way.', 'sentencing', 'State v. Berger', 'https://www.courtlistener.com/opinion/867414/', '867414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We vacate the part of the opinion of the court of appeals that addresses the Eighth Amendment issue, and we affirm the sentences.', 'sentencing', 'State v. Berger', 'https://www.courtlistener.com/opinion/867414/', '867414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Blockburger same-elements test, as the reigning test in both this Court and the federal courts in 1963, best gives effect to the will of the people in ratifying art 1, § 15.', 'general', 'People v. Nutt', 'https://www.courtlistener.com/opinion/848744/', '848744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '45 NW 514 (1890), this Court held that Const 1850, art 6, § 29 did not preclude the defendant’s prosecution for larceny of money stolen during an alleged burglary where the defendant had previously been acquitted of burglary.', 'general', 'People v. Nutt', 'https://www.courtlistener.com/opinion/848744/', '848744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the defendant’s acquittal in a prosecution for the assault upon the husband did not bar the subsequent prosecution for the assault upon the wife:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, by abandoning the same-elements test, the White Court ignored the ratifiers’ common understanding of the “same offense” term in our Constitution.', 'general', 'People v. Nutt', 'https://www.courtlistener.com/opinion/848744/', '848744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, at the time of the ratification of our 1963 Constitution, the people of this state intended that the words “same offense” be construed consistent with state and federal double jeopardy jurisprudence as it then existed.', 'general', 'People v. Nutt', 'https://www.courtlistener.com/opinion/848744/', '848744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*588Because this issue is ripe for consideration in this case, and because we conclude that White was wrongly decided, we return to this Court’s longstanding practice—commensurate with federal double jeopardy law—of reviewing successive prosecutions claims under the Blockburger same-elements test.', 'general', 'People v. Nutt', 'https://www.courtlistener.com/opinion/848744/', '848744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in adopting art 1, § 15, the people of this state intended that our double jeopardy provision would be construed consistently with Michigan precedent and the Fifth Amendment.', 'general', 'People v. Nutt', 'https://www.courtlistener.com/opinion/848744/', '848744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the two offenses are nowise the same offense under either the Fifth Amendment or art 1, § 15, we affirm the result reached by the Court of Appeals majority and hold that defendant is not entitled to the dismissal of the Oakland County charge.', 'dismissal', 'People v. Nutt', 'https://www.courtlistener.com/opinion/848744/', '848744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Court of Appeals did not determine whether the trial court would have departed, and would have departed to the same degree, had it not relied on these improper factors, we reverse the judgment of the Court of Appeals and remand this case to the Court of Appeals for further consideration pursuant to this opinion.', 'general', 'People v. Babcock', 'https://www.courtlistener.com/opinion/848765/', '848765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Court of Appeals in this case did not determine whether the trial court would have departed, and would have departed to the same degree, absent consideration of the reasons that the Court of Appeals found to be not objective and verifiable, we reverse its judgment and remand this case to the Court of Appeals for further consideration.', 'general', 'People v. Babcock', 'https://www.courtlistener.com/opinion/848765/', '848765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we reverse the judgment of the Court of Appeals and remand this case to the Court of Appeals for further consideration pursuant to this opinion.', 'general', 'People v. Babcock', 'https://www.courtlistener.com/opinion/848765/', '848765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Because we conclude that nothing in the plain language of MCL 791.', 'general', 'Jones v. Department of Corrections', 'https://www.courtlistener.com/opinion/848787/', '848787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '240a permits the release of a parole violator under the circumstances of this case and that the appropriate remedy for the department’s failure to timely conduct a fact-finding hearing is a writ of mandamus, we reverse the judgment of the Court of Appeals, dismiss plaintiff’s complaint for habeas corpus relief and reinstate the order of the parole board revoking plaintiff’s parole.', 'dismissal', 'Jones v. Department of Corrections', 'https://www.courtlistener.com/opinion/848787/', '848787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '240a(l) requires the discharge of a prisoner, we reverse the decision of the Court of Appeals and reinstate the order of the parole board revoking plaintiffs parole.', 'general', 'Jones v. Department of Corrections', 'https://www.courtlistener.com/opinion/848787/', '848787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the [decision of the] Court of Appeals.', 'general', 'Jones v. Department of Corrections', 'https://www.courtlistener.com/opinion/848787/', '848787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that manslaughter is not a necessarily included offense within the crime of murder but that it may nonetheless be an included offense if the evidence adduced at trial would support a verdict of guilty for that crime.', 'general', 'People v. Mendoza', 'https://www.courtlistener.com/opinion/848794/', '848794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that an inferior-offense instruction is appropriate only if the lesser offense is necessarily included in the greater offense, meaning, all the elements of the lesser offense are included in the greater offense, and a rational view of the evidence would support such an instruction.', 'general', 'People v. Mendoza', 'https://www.courtlistener.com/opinion/848794/', '848794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that manslaughter is an inferior offense of murder.', 'general', 'People v. Mendoza', 'https://www.courtlistener.com/opinion/848794/', '848794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the elements of involuntary manslaughter are included in the offense of murder because involuntary manslaughter’s mens rea is included in murder’s greater mens rea.', 'general', 'People v. Mendoza', 'https://www.courtlistener.com/opinion/848794/', '848794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that a rational view of the evidence did not support an involuntary-manslaughter instruction.', 'general', 'People v. Mendoza', 'https://www.courtlistener.com/opinion/848794/', '848794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals and reinstate defendant’s conviction.', 'general', 'People v. Mendoza', 'https://www.courtlistener.com/opinion/848794/', '848794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals.', 'general', 'People v. Mendoza', 'https://www.courtlistener.com/opinion/848794/', '848794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals and reinstate defendant’s second-degree murder conviction.', 'general', 'People v. Mendoza', 'https://www.courtlistener.com/opinion/848794/', '848794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '262 NW2d 638 (1978), *552this Court held that manslaughter was not a necessarily included lesser offense of murder:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '230839]), we hold that evidence of firearms and cocaine seized pursuant to a search warrant should not have been suppressed on the ground that the warrant was issued in violation of the affidavit requirements of MCL 780.', 'suppression', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '651 NW2d 77 [2002]), we hold that evidence of marijuana seized from defendant following his arrest should not have been suppressed on the ground that the bench warrant pursuant to which he was arrested was issued in violation of the affidavit requirements of MCR 3.', 'suppression', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sherbine, we held that evidence obtained specifically in violation of MCL 780.', 'general', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '538 NW2d 380 (1995), in which this Court held that evidence obtained under a search warrant issued in violation of § 653 must be suppressed, was dispositive.', 'suppression', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sherbine, this Court held that suppression of evidence was required where a search warrant affidavit violated a previous version of § 65312 in that it did not *503make any showing that an informant was a credible person and that he supplied reliable information.', 'suppression', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sloan, this Court held that a violation of a different provision in the current version of § 653 required application of the exclusionary rule.', 'general', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” This Court held that this provision was violated when the magistrate looked beyond the affidavit, to unrecorded oral testimony of a police officer, in issuing the search warrant.', 'general', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dixon, this Court held that suppression of evidence was required, and reversed the defendant’s conviction on the ground that a search of the defendant at a police station was in derogation of his right to bail under MCL 780.', 'suppression', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that neither the statute nor the court rule contemplates application of the exclusionary rule, we reverse in both cases.', 'general', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we are unable to conclude that the Legislature intended application of the exclusionary rule where the requirements of § 653 have not been met, we overrule Sloan and Sherbine to the extent that they so hold, and we conclude that defendant was not entitled to suppression of evidence on the basis of the statutory violation.', 'suppression', 'People v. Hawkins; People v. Scherf', 'https://www.courtlistener.com/opinion/848795/', '848795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant may be convicted pursuant to the statute, and, therefore, we reverse the Court of Appeals reversal of defendant’s conviction.', 'general', 'People v. Chavis', 'https://www.courtlistener.com/opinion/848817/', '848817') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 Accordingly, we reverse defendant’s conviction and sentence.', 'sentencing', 'People v. Chavis', 'https://www.courtlistener.com/opinion/848817/', '848817') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse the judgment of the Court of Appeals and reinstate defendant’s conviction.', 'general', 'People v. Chavis', 'https://www.courtlistener.com/opinion/848817/', '848817') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Podolski, this Court held the defendant responsible for felony murder when, after a robbeiy, one police officer shot and killed another while the robbers exchanged fire with the police.', 'general', 'People v. Randolph', 'https://www.courtlistener.com/opinion/848860/', '848860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant could not be convicted of unarmed robbery under the facts of this case.', 'general', 'People v. Randolph', 'https://www.courtlistener.com/opinion/848860/', '848860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From that we conclude that the force used to accomplish the taking underlying a charge of unarmed robbery must be contemporaneous with the taking.', 'general', 'People v. Randolph', 'https://www.courtlistener.com/opinion/848860/', '848860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Court of Appeals erred when it provided that, with new evidence, the prosecution could retry defendant on the originally charged offense.', 'general', 'People v. Randolph', 'https://www.courtlistener.com/opinion/848860/', '848860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Court of Appeals decision to allow retrial is in error, we reverse that portion of the opinion, but remand the case to the trial court.', 'general', 'People v. Randolph', 'https://www.courtlistener.com/opinion/848860/', '848860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the Court of Appeals decision in part, reverse it in part, and remand for entry of a judgment of conviction of larceny in a building and for resentencing.', 'sentencing', 'People v. Randolph', 'https://www.courtlistener.com/opinion/848860/', '848860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm its decision insofar as it reverses defendant’s conviction.', 'general', 'People v. Randolph', 'https://www.courtlistener.com/opinion/848860/', '848860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was error for the trial court to refuse the requested instruction and that the error was harmless.', 'general', 'People v. Cornell', 'https://www.courtlistener.com/opinion/848907/', '848907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a requested instruction on a necessarily included lesser offense is proper if the charged greater offense requires the jury to find a disputed factual element that is not part of the lesser included offense and a rational view of the evidence would support it.', 'general', 'People v. Cornell', 'https://www.courtlistener.com/opinion/848907/', '848907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that breaking and entering without permission is a necessarily included lesser offense of breaking and entering with the intent to commit a felony.', 'general', 'People v. Cornell', 'https://www.courtlistener.com/opinion/848907/', '848907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these harmless error principles to defendant Cornell’s case, we conclude that the error was harmless because the evidence did not clearly support a conviction for the lesser included misdemeanor of breaking and entering without permission.', 'general', 'People v. Cornell', 'https://www.courtlistener.com/opinion/848907/', '848907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that defendant Cornell failed to satisfy his burden of showing that it was more probable than not that the failure to provide the requested instruction undermined the reliability of the verdict and that the error in this case was harmless.', 'general', 'People v. Cornell', 'https://www.courtlistener.com/opinion/848907/', '848907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in refusing to give the requested misdemeanor lesser included offense instruction of breaking and entering without permission.', 'general', 'People v. Cornell', 'https://www.courtlistener.com/opinion/848907/', '848907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm defendant’s conviction.', 'general', 'People v. Cornell', 'https://www.courtlistener.com/opinion/848907/', '848907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Philabaun II, we held that the defendant had violated § 479 by resisting the officer’s attempt to execute a search warrant.', 'general', 'People v. Vasquez', 'https://www.courtlistener.com/opinion/849104/', '849104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an officer’s attempts to “maintain, preserve and keep the peace” under MCL 750.', 'general', 'People v. Vasquez', 'https://www.courtlistener.com/opinion/849104/', '849104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Our opinion is consistent with Philabaun II, where we concluded that the defendant’s refusal to comply with a search warrant for a blood sample constituted an obstruction under Michigan’s “resisting and obstructing” statute.', 'general', 'People v. Vasquez', 'https://www.courtlistener.com/opinion/849104/', '849104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the purpose of the statute is to protect officers from physical harm.', 'general', 'People v. Vasquez', 'https://www.courtlistener.com/opinion/849104/', '849104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since Trooper Spinner was executing his duties as a police officer when the encounter took place, we find that he was engaged in “efforts to maintain, preserve and keep the peace” within the meaning of § 479.', 'general', 'People v. Vasquez', 'https://www.courtlistener.com/opinion/849104/', '849104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this basis, we find that the Legislature drafted the list of six verbs to describe a fluid string of behavior that constitutes a violation of the statute.', 'general', 'People v. Vasquez', 'https://www.courtlistener.com/opinion/849104/', '849104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Before the Court of Appeals decided Vasquez, we reversed the decision in Philabaun I.', 'general', 'People v. Vasquez', 'https://www.courtlistener.com/opinion/849104/', '849104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such claims should be reviewed for fundamental error.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/867448/', '867448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ring III, we held that, in the capital context, “Arizona’s failure to submit [aggravating factors] to the jury does not constitute structural error.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/867448/', '867448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the sentencing procedure followed denied Henderson the right to have certain facts decided by a jury beyond a reasonable doubt, we conclude that the procedure utilized went to the foundation of Henderson’s case.', 'sentencing', 'State v. Henderson', 'https://www.courtlistener.com/opinion/867448/', '867448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the jury’s failure to convict Henderson of kidnapping, we conclude that a reasonable jury, applying the correct burden of proof of beyond a reasonable doubt, could have found differently than did the trial judge as to the C.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/867448/', '867448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we find that a reasonable jury applying the correct standard of proof could have reached a different conclusion than did the trial judge as to any or all aggravators, we must then consider whether at least two aggravators not subject to such a conclusion remain to sustain the defendant’s super-aggravated sentence.', 'sentencing', 'State v. Henderson', 'https://www.courtlistener.com/opinion/867448/', '867448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that fundamental error occurred.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/867448/', '867448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Court of Appeals dismissal of defendant’s claim and remand for consideration of his appeal as of right.', 'dismissal', 'People v. Kaczmarek', 'https://www.courtlistener.com/opinion/849186/', '849186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated in this opinion, we reverse the order of the Court of Appeals and remand this case to that Court for reinstatement of defendant’s appeal.', 'general', 'People v. Kaczmarek', 'https://www.courtlistener.com/opinion/849186/', '849186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '215 NW2d 695 (1974), we held that an appeal following revocation of probation is limited to matters relating to the probation violation.', 'general', 'People v. Kaczmarek', 'https://www.courtlistener.com/opinion/849186/', '849186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 21 In Minnitt, we held that double jeopardy barred the retrial of a defendant whose convictions were procured by false and per*438jured testimony that the prosecutor placed before the jury with full knowledge of its perjurious character and of the likelihood that it would support a conviction.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 686, 694-95 (1983), we held that the spousal communication privilege was waived because the defendant spoke to his wife knowing that police officers could hear him and were listening to him.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 621, 623-25 (1995), we held that a trial court erroneously failed to preclude a witness’s key exhibit, “the centerpiece of the star witness’s testimony,” which was not disclosed to the defense until the day before trial.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that prosecutors “may comment on the vicious and inhuman nature of the defendant’s acts,” but “may not make arguments which appeal to the passions and fears of the jury.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this evidence, we held that the trial court’s failure to properly instruct the jury on the effect of intoxication deprived the defendant of an “important right, which the law accorded him, to have the jury pass on the truthfulness of his story, and, if they believed that he was intoxicated to any extent to say whether such intoxication prevented him from entertaining the malice necessary to constitute murder in the second degree.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hughes, we held that “when counsel [makes] the court aware of his objection through a previous motion, failure to object at trial does not then waive the issue on appeal.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '348, 351 (1905), Arizona’s landmark case on privilege, this court held that the defendant waived his spousal communications privilege when he wrote a letter to his wife from jail knowing that the jailers would open the letter.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the trial judge did not abuse his discretion in denying Moody’s motions to preclude the State from proceeding on felony murder theories at the second trial.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we conclude that there was no fundamental error in denying Moody’s objection to the evidence.', 'general', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the posture of this case, we conclude that the trial court did not abuse its discretion in denying Moody’s mistrial motion.', 'mistrial', 'State v. Moody', 'https://www.courtlistener.com/opinion/867478/', '867478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that in order to prove the element of weight of drugs or controlled substances, the State must either offer evidence of its actual, measured weight or demonstrate that the quantity of the drugs or controlled substances is so large as to permit a reasonable inference that the element of weight has been established.', 'general', 'Halsema v. State', 'https://www.courtlistener.com/opinion/852835/', '852835') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding there was not sufficient evidence, we reverse the Halsemas'' convictions for possession of methamphetamine within 1000 feet of a school as Class A felonies.', 'general', 'Halsema v. State', 'https://www.courtlistener.com/opinion/852835/', '852835') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Halsemas'' convictions for possession of methamphetamine as Class A felonies.', 'general', 'Halsema v. State', 'https://www.courtlistener.com/opinion/852835/', '852835') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the criminal confinement statute cannot serve as a basis for the convictions in this case and that the evidence is insufficient to establish all of the statutory elements of identity deception, we reverse.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/852546/', '852546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the defendant was convicted of removing persons by fraud and/or enticement, we reverse his criminal confinement convictions.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/852546/', '852546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that where the State seeks to prosecute a defendant in a Hawai''i state court, and seeks to admit evidence obtained in another jurisdiction, the court must give due consideration to the Hawai''i Constitution and applicable ease law, as indicated herein, when assessing whether such evidence is admissible against the defendant.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the defendant did not expressly indicate that he consented to a search of his toolbox or the contents therein, this court held that inasmuch as “[cjonsent may also be implied from an individual’s words, gestures, or eonduet[,j” the defendant had consented to the search of his tool box in voluntarily surrendering it for inspection.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing considerations, we conclude that where the admission of evidence obtained in another jurisdiction would violate our constitution, the court must give substantial weight21 to the fact that such admission may compromise the judicial integrity of our courts.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d at 5, we conclude that Petitioner’s consent to the search of his vehicle may be implied from his act of driving past the guard shack and onto PHNB, and imputed from the posted notice indicating that entry onto PHNB constituted consent to a search.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find federal search directives irrelevant in this ease inasmuch as we conclude that the inspection of Petitioner’s vehicle was valid based on Petitioner’s implied consent to such search.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Petitioner’s third question must be answered in the negative.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the opinion of the ICA in all other respects and we affirm the court’s December 5, 2006 order denying Petitioner’s motion to suppress under the Hawai''i Constitution.', 'suppression', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As indicated previously, we affirm the ICA’s decision insofar as it upheld the *400searches of Petitioner’s vehicle as valid under federal law and the United States Constitution.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the December 5, 2006 order of the court denying Petitioner’s motion to suppress under federal law and the Hawai''i Constitution.', 'suppression', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this evidence, we conclude that a reasonable jury could not properly have acquitted the defendant and would have rendered a guilty verdict even if the erroneous flight instruction had not been given.', 'general', 'Dill v. State', 'https://www.courtlistener.com/opinion/853454/', '853454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we concluded that the specific language of the instruction, particularly in the context of the other instructions, did not constitute infringement of the defendant’s right to due process of law, we nevertheless recommended against the future use of this instruction, but did not articulate our reasons or otherwise provide explicit guidance.', 'general', 'Dill v. State', 'https://www.courtlistener.com/opinion/853454/', '853454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Responding to the issues presented, we found that the instruction could not “ ‘reasonably have been understood as creating a presumption that relieves the State of its burden of persuasion on an element of an offense.', 'general', 'Dill v. State', 'https://www.courtlistener.com/opinion/853454/', '853454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the defendant’s convictions and as to all other issues, the Court of Appeals is summarily affirmed.', 'general', 'Dill v. State', 'https://www.courtlistener.com/opinion/853454/', '853454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that this defense, alone, does not establish the existence of a serious evidentiary dispute so as to allow a jury to conclude that reckless homicide was committed instead of murder.', 'general', 'Ellis v. State', 'https://www.courtlistener.com/opinion/853516/', '853516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we held that because the mere assertion of an insanity defense did not create a "serious evidentiary dispute,” the trial court did not err in refusing the defendant’s instructions on reckless homicide.', 'general', 'Ellis v. State', 'https://www.courtlistener.com/opinion/853516/', '853516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the trial court in part and affirm in part, and remand for sentencing as indicated.', 'sentencing', 'Ellis v. State', 'https://www.courtlistener.com/opinion/853516/', '853516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997) (applying the 1994 statute: “we hold that the statutory limitation will apply to an attempted murder conviction unless the defendant received ‘an enhanced penalty because the felony resulted in serious bodily injury if the defendant knowingly or intentionally caused the serious bodily injury’ ”).', 'general', 'Ellis v. State', 'https://www.courtlistener.com/opinion/853516/', '853516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that when eyewitness identification is central to the case, circuit courts must give a specific jury instruction upon the request of the defendant to focus the jury’s attention on the *314trustworthiness of the identification.', 'jury_instruction', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that this rule should be given prospective effect.', 'general', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Haanio, this court held that "trial courts must instruct juries as to any included offenses when there is a rational basis in the evidence^]" 94 Hawai''i at 413, 16 P.', 'general', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Connecticut court stated, “In light of the importance of eyewitness identification evidence and the conclusions to be drawn from the scientific research discussed [supra ], we conclude that it is appropriate to invoke that authority again to mitigate the potential risk of mistaken identification.', 'general', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that the jury''s attention was adequately focused on the *319relevant factors affecting eyewitness identification.', 'general', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm Cabagbag’s Judgment of Conviction and Probation and Sentence filed on July 19, 2010.', 'sentencing', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Cabagbag’s judgment of conviction is affirmed, we affirm the ICA’s judgment on appeal for the reasons set forth in this opinion.', 'general', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Haanio, we held that the court must instruct the jury on lesser included offenses when there is a rational basis in the evidence for a verdict acquitting the defendant for the offense charged and convicting the defendant for the included offense.', 'general', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, inasmuch as, in Garcia, this court held that a new rule benefitting the defendant should be applied retroactively, in this case too, the rule that the jury should be given a specific eyewitness identification instruction, which would benefit Petitioner, should be applied to Petitioner and retroactively to all similarly situated defendants.', 'general', 'State v. Cabagbag', 'https://www.courtlistener.com/opinion/871542/', '871542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Secondly, we hold that the statement of the Deputy Prosecuting Attorney (DPA) to the jury during closing arguments not to “get too caught up in the mumbo jumbo of all the words [of the jury instructions,]” among other statements, infringed on Petitioner’s right to have the case against him proven beyond a reasonable doubt.', 'jury_instruction', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 525 ("[I]n light of the nature of the prosecutor’s statement, the failure of defense counsel to object, and the strength of the evidence against [the defendant], we hold that any error .', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we hold that judicial notice of HRS § 571-84 is controlling in light of the facts of this case.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that HRS § 571-1 “mandates against treating juvenile adjudications as convietions[,]” stating that “[t]he reasoning underlying our holding is addressed succinct*446ly by [the] dissent” in Riveira I.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'as well as the strength of the evidence against [Petitioner], we conclude that the statements of the DPA were harmless beyond a reasonable doubt.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying it, we conclude that in light of HRS § 571-84(h), the court erred in ruling that if Petitioner testified on cross-examination that he did not know a single punch could cause the death of a person, Respondent could introduce evidence from Petition*447er’s juvenile proceedings.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As indicated before, we conclude that HRS § 571-84(h) is plain and unambiguous.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997) ("Thus, in light of the overwhelming evidence of [the defendant''s guilt, we conclude that those of the prosecutor’s comments which were improper were harmless beyond a reasonable doubt.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” As indicated earlier, we affirm the ICA''s conclusion that the use of the power point slide did not constitute prosecutorial misconduct.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To reiterate, we affirm the ICA’s opinion as to the foregoing questions, and therefore, they are not specifically addressed herein.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 884, 888 (2001) (“We hold that the courts are duty-bound to take ‘judicial notice’ of municipal ordinances.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a threshold matter, this court held that “the courts are duty-bound to take ‘judicial notice’ of municipal ordinances” pursuant to HRE Rule 202(b).', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For instance, this court held in Wallace that the defendant’s relevance-based objection to the introduction of the gross weight of cocaine failed to preserve the distinct issue of whether the scale used to weigh the cocaine was accurate.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this court held “that the circuit court did not commit plain error, when, without objection it allowed introduction of one picture of [the defendant’s] firearms and permitted testimony of a weapons expert.', 'general', 'State v. Schnabel.', 'https://www.courtlistener.com/opinion/871554/', '871554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that although a plea of insanity may be viewed as an admission of the commission of the criminal act and may in other ways ease the State’s burden of proof, it does not, in the absence of other compelling circumstances, entitle a defendant to a bifurcated trial.', 'plea', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that the content of an opening statement, absent some egregious blunder, is also a matter of strategy.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “it was not error to restrict this instruction to the more immediate potential consequences, i.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, where the aggravating circumstance was a multiple murder and the court repeatedly referred to the aggravating circumstances in the plural, we held that "[a]ny potential confusion that could have arisen in the mind of a reasonable juror as to how many aggravating circumstances existed and how to apply the evidence of each to the separate murders would certainly have been dispelled” by the instruction given which informed the jury that the State alleged only one aggravating circumstance.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wisehart has not satisfied at least three of the Fox requirements.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We conclude that trial counsel’s performance at the penalty phase was not deficient for failing to place Wisehart’s mental condition before the jury as a mitigating circumstance.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*64We conclude that this averment, standing as it does alone, does not entitle Wisehart to post-conviction relief.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was a sound strategic reason for placing Wisehart’s mental condition at issue in this ease.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') While there was undeniably some confusion on this score, we find that the issue was fully aired and that trial counsel took steps to exclude prospective jurors who expressed unwillingness to entertain the dual arguments.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that trial counsel was not deficient in failing to present sufficient evidence in support of his false confession theory.', 'general', 'Wisehart v. State', 'https://www.courtlistener.com/opinion/854144/', '854144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under this approach, we hold that for the purposes of the crime-of-violence enhancement under § 2L1.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that a defendant''s prior conviction under Texas Penal Code § 22.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this interpretation reads Taylor too strictly and overlooks that the Taylor Court referenced statutory definitions for the narrow purpose of distinguishing the contemporary sweep of “burglary” from its antiquated common-law past.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that taking a plain-meaning approach to derive the “generic, contemporary meaning” of non-common-law offense categories is grounded in the most reasoned interpretation of Taylor, and avoids some of the gymnastics that our prior application of Taylor1 s categorical approach required.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that both are non-common-law offense categories.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '26 For these reasons, we conclude that the “generic, contemporary meaning” of “statutory rape” sets the age of consent as a person under the age of majority as defined by statute.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that it was not error for the district court to impose a sixteen-level enhancement pursuant to U.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is improper to rely on this broader definition when the plain language of the definition of "statutory rape” provides for a narrower meaning of "age of consent.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM Rodriguez’s sentence, and in so doing, we adopt a plain-meaning approach to the “crime of violence” enhancements of “sexual abuse of a minor” and “statutory rape” under U.', 'sentencing', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The majority opinion seems to answer yet another question (changing the phrase "fingerprint evidence and related testimony" in the question to "fingerprint-related testimony" in the answer): "We conclude that, with regard to the admission of fingerprint-related testimony on rebuttal, the circuit court did not erroneously exercise its discretion [to admit the rebuttal testimony].', 'general', 'State v. Brent T. Novy', 'https://www.courtlistener.com/opinion/855157/', '855157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'ultimately concluding that any error was harmless, the court of appeals appeared to employ a sufficiency of the evidence standard: "Because there was sufficient evidence, other than Michael''s alleged hearsay statement, to convict Patricia [Weed] beyond a reasonable doubt, we hold that any error in the admission of the Fuerbringers'' testimony was harmless.', 'general', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that imposing a sentence under the erroneous belief that the defendant was subject to a five-year mandatory minimum period of confinement is an error subject to a harmless error analysis.', 'sentencing', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Thus we conclude that the defendant has met his two-pronged burden under Tiepelman.', 'general', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of the case law governing structural error, we conclude that the error in the present case simply does not fit into the general description of a structural error and is unlike previously categorized structural errors.', 'general', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We decline to extend the limited class of structural errors to the error in the present case, and thus we conclude that the present case does not involve a structural error requiring automatic reversal.', 'general', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the error about the mandatory minimum period of confinement permeated the entire sentencing procedure.', 'sentencing', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that imposing a sentence under the erroneous belief that the defendant was subject to a five-year mandatory minimum period of confinement is *179an error subject to a harmless error analysis.', 'sentencing', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals, but on different grounds, and remand the matter for resentencing.', 'sentencing', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we affirm the decision of the court of appeals.', 'general', 'State v. Lamont L. Travis', 'https://www.courtlistener.com/opinion/866431/', '866431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the relevant set of conduct consisted of that which was in fact charged and proved in the state-court proceeding, not the set of conduct that could have been proved in a hypothetical federal proceeding.', 'general', 'Moncrieffe v. Holder', 'https://www.courtlistener.com/opinion/866024/', '866024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 462 (2006), we held that felony status is controlled by federal, not state, law.', 'general', 'Moncrieffe v. Holder', 'https://www.courtlistener.com/opinion/866024/', '866024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After conducting that review, we conclude that Davis’s conduct was swept up in the broad statutory terms, which, in turn, triggered the mandatory sentences imposed.', 'sentencing', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that given the circumstances of Davis’s offenses, the sentence imposed in this case appears to be grossly disproportionate to his crimes.', 'sentencing', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*390¶ 59 We conclude that Davis’s case is more like Spencer’s.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we cannot be certain which offense served as the predicate for the conviction, we conclude that the real possibility of a non-unanimous jury verdict exists.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 66 Because the State offered evidence of more than one offense to support its first charge against Davis and the events were not part of a single transaction, we conclude that the charge was duplicitous.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the defendant was put in jeopardy in the two counts charged “for any one of what could be one hundred separate criminal offenses.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In section B of this opinion, we reverse one conviction.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Davis’s conviction on count four, but reverse and remand for a new trial on count one.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 704 (“In this case, however, we hold that the statutory range of sentencing .', 'sentencing', 'State v. Davis', 'https://www.courtlistener.com/opinion/867512/', '867512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an appellate court’s remand for entry of judgment of conviction and resentencing for a lesser-included offense must be based on a jurisdic-tionally valid lesser-included charge.', 'sentencing', 'State v. Walker', 'https://www.courtlistener.com/opinion/871589/', '871589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that an appellate court’s remand for entry of judgment of conviction and sentencing for a lesser-ineluded offense must be based on a jurisdictionally valid lesser-ineluded charge.', 'sentencing', 'State v. Walker', 'https://www.courtlistener.com/opinion/871589/', '871589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, as discussed infra, we hold that the circuit court lacked jurisdiction, Walker’s contention that the ICA was required to remand for entry of judgment of conviction and sentencing on the lesser-included offense need not be reached.', 'sentencing', 'State v. Walker', 'https://www.courtlistener.com/opinion/871589/', '871589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By applying the liberal construction standard in Tominiko, we held that an OVUII charge, which did not allege the public road requirement, was sufficient.', 'general', 'State v. Walker', 'https://www.courtlistener.com/opinion/871589/', '871589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the ICA’s judgment and hold that the ICA did not err in vacating the circuit court''s judgment and remanding Walker’s case to the circuit court with instructions to dismiss Count I without prejudice.', 'dismissal', 'State v. Walker', 'https://www.courtlistener.com/opinion/871589/', '871589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the ICA
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Tominiko, we held that an OVUII charge, which did not allege the public road requirement, was sufficient under the liberal construction standard.', 'general', 'State v. Walker', 'https://www.courtlistener.com/opinion/871589/', '871589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that, without further clarification, this instruction was erroneous.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/867554/', '867554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 Accordingly, we conclude that the legislature intended to relieve the state of the burden of proving a defendant’s thought processes by direct evidence.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/867554/', '867554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Guerra’s conviction because the instruction, considered as a whole, was sufficiently balanced to withstand scrutiny.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/867554/', '867554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agree that HRS § 291E-61(a)(3) is an absolute liability offense for which mens rea need not be alleged or proven, we hold that the ICA erred in its holdings regarding HRS § 291E-61(a)(l) in three ways.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we hold that the HRS § 291E-61(a)(1) charges as written (omitting mens rea) failed to fully define the HRS § 291E-61(a)(1) offense in unmistakable terms readily comprehensible to persons of common understanding.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, we hold that the Nesmith majority erred by extending HRS § 806-28 to the district courts, as the plain language of HRS § 806-2 limits the application of the criminal procedure provisions of Chapter 806 to the circuit courts.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the ICA correctly concluded that HRS § 291E-61 (a)(3) is an absolute liability offense for which no mens rea need be alleged or proven, but that the ICA erred by (1) holding that mens rea need not be alleged in an HRS § 291E-61(a)(l) charge, as without such an allegation, the Complaint fails to fully define the offense in unmistakable terms readily comprehensible to persons of common understanding;', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even under a liberal review, we held that the charge could not be reasonably construed to state the offense of resisting arrest.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held, “Although the oral charge here tracked the language of HRS § 291E-61, the failure of the charge to allege that Wheeler was driving his vehicle upon a public way, street, road, or highway at the time of the offense rendered the charge deficient.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, this court held, “the requisite state of mind was omitted from the charge and we perceive no way in which we could reasonably construe it to charge resisting arrest or any included offense.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the legislature’s inaction, we conclude that HRS § 291E-61(a)(3) remains an absolute liability offense.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the ICA’s judgments, which affirmed the district court’s judgments of conviction and sentence under HRS § 291E-61.', 'sentencing', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that “[t]he failure of the complaint to set forth this essential element [i.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 66, this court held that although the abuse of a family or household member statute did not refer to a requisite state of mind, the offense is not an absolute liability offense.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, this court held that under HRS § 346-34, a defendant must act intentionally, knowingly, or recklessly.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 1170, 1173, 1178 (2009) this court held the definition of the term operate, i.', 'general', 'State v. Nesmith', 'https://www.courtlistener.com/opinion/871601/', '871601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that: 1) the charge was not insufficient under the liberal construction standard because, when reading the charge as a whole, it can be reasonably construed to charge a crime;', 'general', 'State v. Tominiko', 'https://www.courtlistener.com/opinion/871166/', '871166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that the charging language was not insufficient under the liberal construction standard.', 'general', 'State v. Tominiko', 'https://www.courtlistener.com/opinion/871166/', '871166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Officer Stuart did not have reasonable suspicion to seize Tominiko because Officer Stuart did not have evidence that Tominiko, rather than other members of his group, had committed or was about commit a crime.', 'general', 'State v. Tominiko', 'https://www.courtlistener.com/opinion/871166/', '871166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence obtained was the result of an illegal seizure because: 1) Officer Stuart’s stop was a single illegal seizure;', 'general', 'State v. Tominiko', 'https://www.courtlistener.com/opinion/871166/', '871166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 1170, 1180 (2009)) In Wheeler, this court held that, where the defendant made a timely objection to an OVUII charge, the charge was insufficient because it failed to allege the public road element of the offense.', 'general', 'State v. Tominiko', 'https://www.courtlistener.com/opinion/871166/', '871166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the defendant was unlawfully seized by the police officers’ interrogation and that the evidence obtained after the defendant fled was inadmissible as the product of an illegal seizure.', 'general', 'State v. Tominiko', 'https://www.courtlistener.com/opinion/871166/', '871166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that opinion, this court held that a count could incorporate language from another count, even though the charging document did not contain language specifically doing so in that case.', 'general', 'State v. Tominiko', 'https://www.courtlistener.com/opinion/871166/', '871166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wheeler, this court held that the statutory definition of the term "operate,” as used in HRS § 291E-61, "establishes an attendant circumstance of the offense of OVUII, i.', 'general', 'State v. Tominiko', 'https://www.courtlistener.com/opinion/871166/', '871166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that all issues raised by Manzanares which concern the Firearm Charge were rendered moot when the Firearm Charge was dismissed.', 'dismissal', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Manzanares’s conditional plea agreement did not reserve the issue for appeal.', 'plea', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that Manzanares’s ex post facto issue is not jurisdictional and was, therefore, waived by pleading guilty.', 'plea', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Manzanares has not met the burden of showing a clear error that violated one of her unwaived constitutional rights.', 'general', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Recruiting Provision is not facially overbroad because it does not prohibit a substantial amount of protected conduct, and we hold that Manzanares has not shown that it is as applied unconstitutional because, due to the circumstances of this case, she is unable to demonstrate what conduct on her part provides the basis of her conviction.', 'general', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the Recruiting Provision is not facially overbroad.', 'general', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that she failed to show that the Recruiting Provision was applied to her in a manner that infringed upon her First Amendment rights.', 'general', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Manzanares argues that the claims are not moot, because if this Court holds in favor of Manzanares on one of the issues related to the Recruiting Charge, I.', 'general', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that Manzanares’s conditional plea agreement reserved the facial and as applied challenges for appeal, we take the time to emphasize the proper means of reserving issues for appeal pursuant to I.', 'plea', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that Manzanares reserved the right to appeal the district court’s ruling that the Recruiting Statute is not overbroad.', 'general', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While knowledge is a different mens rea than specific intent, we find that the Recruiting Provision is sufficiently narrow to avoid implicating a substantial amount of protected conduct.', 'general', 'State v. Manzanares', 'https://www.courtlistener.com/opinion/874754/', '874754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was not.', 'general', 'State v. Flegel', 'https://www.courtlistener.com/opinion/874765/', '874765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 1255 (2011), we held that where the grand jury had no authority to issue an indictment because its term had expired, “a valid indictment was never entered against Lute, [and] the district court never had subject matter jurisdiction over Lute’s case under Article I, section 8 of the Idaho Constitution.', 'general', 'State v. Flegel', 'https://www.courtlistener.com/opinion/874765/', '874765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that it did not because the type of conduct included in the phrase “including but not limited to” must be the conduct of a like or similar class or character to the types of conduct specifically listed.', 'general', 'State v. Flegel', 'https://www.courtlistener.com/opinion/874765/', '874765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the district court’s refusal to instruct on sexual abuse not because sexual abuse is never a lesser-included offense of lewd conduct.', 'general', 'State v. Flegel', 'https://www.courtlistener.com/opinion/874765/', '874765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we affirmed solely because I.', 'general', 'State v. Flegel', 'https://www.courtlistener.com/opinion/874765/', '874765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence presented by the State is sufficient for a reasonable mind to conclude beyond a reasonable doubt that Hickman committed theft of Cain’s wallet.', 'general', 'State v. Hickman', 'https://www.courtlistener.com/opinion/874889/', '874889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the erroneous jury instructions resulted in harmless error, that there was no impermissible variance between the charging document and the jury instructions, and that the evidence is sufficient to sustain the grand theft conviction.', 'jury_instruction', 'State v. Hickman', 'https://www.courtlistener.com/opinion/874889/', '874889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Hickman', 'https://www.courtlistener.com/opinion/874889/', '874889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the jury verdict and the denial of Hickman’s motion for a directed verdict.', 'general', 'State v. Hickman', 'https://www.courtlistener.com/opinion/874889/', '874889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Hickman’s conviction and sentence.', 'sentencing', 'State v. Hickman', 'https://www.courtlistener.com/opinion/874889/', '874889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Weighing this factor against the seriousness of the prosecutorial misconduct and its likely effect on the grand jury, we conclude that Marsalis has not shown that, “but for” the misconduct, he would not have been indicted.', 'general', 'State v. Marsalis', 'https://www.courtlistener.com/opinion/880908/', '880908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Marsalis', 'https://www.courtlistener.com/opinion/880908/', '880908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that the Youth Court’s failure to fully consider KE.', 'general', 'Matter of K.E.G. Youth', 'https://www.courtlistener.com/opinion/890301/', '890301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse in part and remand with directions to the Youth Court to hold a new restitution hearing.', 'general', 'Matter of K.E.G. Youth', 'https://www.courtlistener.com/opinion/890301/', '890301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'had violated his disposition conditions, we held that he was not subject to sentencing under the adult statutes.', 'sentencing', 'Matter of K.E.G. Youth', 'https://www.courtlistener.com/opinion/890301/', '890301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred by refusing to allow discovery on Castillo’s action for breach of contract, including whether there was any outside influence on the jury.', 'general', 'Ford Motor Co. v. Castillo', 'https://www.courtlistener.com/opinion/895102/', '895102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals’ judgment and remand the ease to the trial court for further proceedings consistent with this opinion.', 'general', 'Ford Motor Co. v. Castillo', 'https://www.courtlistener.com/opinion/895102/', '895102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals’ judgment and remand the case to the trial court for further proceedings consistent with this opinion.', 'general', 'Ford Motor Co. v. Castillo', 'https://www.courtlistener.com/opinion/895102/', '895102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we conclude that the second-degree reckless homicide statute and the criminal child abuse statute provide sufficient notice that the parents'' conduct could have criminal consequences if their daughter died.', 'general', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we conclude that the statutes fulfill the constitutional due process fair notice requirement.', 'general', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the second-degree reckless homicide statute and the criminal child abuse statute are sufficiently distinct that a parent has fair notice of conduct that is protected and conduct that is unprotected.', 'general', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instructions imposing a legal duty on a parent to provide medical care for his or her child when necessary do not violate a parent''s fundamental constitutional right to direct the care of his or her child.', 'jury_instruction', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the jury instructions about a parent''s legal duty to provide medical care were not in and of themselves erroneous.', 'jury_instruction', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court''s instructions regarding religious belief were not in and of themselves erroneous.', 'general', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though we conclude that the jury instructions about legal duty and religious belief were not erroneous, we must address the parents'' central contention that these jury instructions, combined with the circuit court''s refusal to instruct the jury about the effect of a parent''s sincere belief in prayer treatment on the subjective awareness element of second-degree reckless homicide, undermined the parents'' ability to defend themselves.', 'jury_instruction', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a specific instruction on the sincere religious beliefs of the parents, as counsel request on appeal, was not required.', 'general', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the real issue in controversy was fully tried.', 'general', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On our independent review of the record and giving weight to the circuit court''s consideration of lack of juror bias, we conclude that the father has not sustained his burden to show that reasonable persons in the juror''s position under the circumstances of the instant case could not set aside their knowledge of the mother''s conviction.', 'general', 'State v. Dale R. Neumann', 'https://www.courtlistener.com/opinion/987953/', '987953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the Cherry motion issue, we hold that because sentence modification is a distinct procedure from Wis.', 'sentencing', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the second issue, the proper pleading standard, we hold that a defendant who argues in a habeas petition that he received ineffective assistance of appellate counsel because certain arguments were not raised must demonstrate that the claims he believes should have been raised on appeal were "clearly stronger" than the claims that were raised.', 'habeas', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the third and final question of whether Starks received ineffective assistance of appellate counsel, we hold that because the arguments Starks believes should have been raised were not clearly stronger than the arguments that were raised in his appeal, Starks''s appellate attorney was not ineffective.', 'ineffective_assistance', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State has articulated the proper standard.', 'general', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that as sentence modification is a distinct procedure from Wis.', 'sentencing', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the question of the proper pleading standard, we hold that a defendant who argues he received ineffective assistance of appellate counsel in a habeas petition because certain arguments were not raised must show why the claims he believes should have been raised on appeal were "clearly stronger" than the claims that were raised.', 'habeas', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that because the arguments about trial counsel''s ineffectiveness are not clearly stronger than the arguments Starks made on direct appeal, Starks did not receive ineffective assistance of appellate counsel and is not entitled to habeas relief.', 'habeas', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals.', 'general', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As Starks did not receive ineffective assistance of appellate counsel, we affirm his conviction.', 'ineffective_assistance', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Kagen was not deficient for failing to make these arguments, and thus need not decide whether he was prejudiced.', 'general', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In an effort to amplify the standard established in Mixon and confirmed by our own decision in Workman, we hold that in a coram nobis proceeding, the trial judge must first consider the newly discovered evidence and be “reasonably well satisfied” with its veracity.', 'general', 'State v. Vasques', 'https://www.courtlistener.com/opinion/1057883/', '1057883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial evidence was sufficient to support the convictions and that the statutory waiver of the entitlement to complete jury instructions does not violate the right to a jury trial or the separation of powers principle.', 'jury_instruction', 'State v. Vasques', 'https://www.courtlistener.com/opinion/1057883/', '1057883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the evidence in the record and the applicable authority, we conclude that the Court of Criminal Appeals properly granted coram nobis relief to Vasquez and Garza based upon the newly discovered evidence and properly denied coram nobis relief to Vasques, Hernandez, and Alonzo.', 'general', 'State v. Vasques', 'https://www.courtlistener.com/opinion/1057883/', '1057883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that (1) the trial court did not err by finding the defendant competent to stand trial;', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In consequence, we hold that the sentences of death were not disproportionate.', 'sentencing', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1993), we held that the trial court *818should not have instructed the jury on the aggravating circumstance under Tennessee Code Annotated section 39 — 13—204(i)(6) where there was “not a shred of evidence in the record” to support the claim.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that the sentence of death was imposed in any arbitrary fashion.', 'sentencing', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the defendant’s sentences of death are not disproportionate under the mandatory review criteria of Tennessee Code Annotated section 39-13-206(c)(l).', 'sentencing', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not err in excluding the testimony of the witnesses.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the evidence in this case, and based upon the above-quoted rationale of the Supreme Court, we conclude that the trial court did not err in limiting the testimony of Reverend Ingle.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Ms.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the answers and responses of Judy Reynolds, we conclude that the trial court did not err in failing to exclude her for cause.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the voir dire, we conclude that defense counsel was not restricted from asking about whether potential jurors believed or had learned from an outside source that identifications are infallible or immune from error.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the photograph was relevant to the description of Defendant on the night in question, and we further determine that the admission of the photograph was not outweighed by any prejudicial effect.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the record, we conclude that the trial court did not err in allowing the introduction of the photograph.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While it depicts blood at the scene, we conclude that the photograph is not particularly gruesome.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that any error by the trial court on this issue was harmless.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that the testimony by Ms.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1057938/', '1057938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the best method for determining whether a particular portion of the charge should be bifurcated from the main crime is by balancing the element’s probative value against the risk of undue prejudice to defendant.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the length of delay was extreme, and that almost two years of the delay was attributable to the state.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We attributed this time period to the state judicial system as a whole, not the prosecution, because during that time defendant was either without counsel or his counsel did very little to move defendant’s case forward, and we held that “ultimately it is the court’s responsibility to assure that [the criminal justice system] prosecutes defendants in a timely manner.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that defendant was deprived of his right to a speedy trial and entitled to dismissal of the charges against him.', 'dismissal', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Galvin, the defendant was charged with assault on a police officer, and we held that the elements of the crime were wholly defined by the simple assault statute, 13 V.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that if the State intends to seek greater punishment based on a prior conviction then the State must charge the principal offense and the prior conviction in two parts in the complaint.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not reach the speedy trial issue under the Vermont Constitution because we conclude that defendant failed to adequately raise this ground in his original appeal.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the additional claims of error, we conclude that the trial court erred in denying defendant’s request to bifurcate the aggravation element of the domestic assault charge.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the record, we conclude that the state constitutional claim was not adequately raised or briefed, and therefore decline to analyze defendant’s speedy-trial argument under the Vermont Constitution.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having failed to raise the issue adequately in the trial court and in his original appeal, we conclude that defendant has waived consideration of this issue on remand.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 1292, we concluded that, “[t]o the contrary, the record reveals that defendant consistently sought to be tried by competent counsel as quickly as possible.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1057223/', '1057223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1973), we held that predecessor statutes addressing claims against estates established “statute[s] of limitation affecting only the remedy.', 'general', 'In Re: Estate of Martha M. Tanner', 'https://www.courtlistener.com/opinion/1057656/', '1057656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we hold that the statute imposing the tax on unauthorized substances does not violate the constitutional protections against self-incrimination and double jeopardy or abridge the guarantee of procedural due process.', 'general', 'Steven Waters v. Reagan Farr, Commissioner of Revenue for the State of Tennessee', 'https://www.courtlistener.com/opinion/1057665/', '1057665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the North Carolina Controlled Substance Tax does not have such fundamentally punitive characteristics as to render it violative of the prohibition against multiple punishments for the same offense contained in the Double Jeopardy Clause.', 'general', 'Steven Waters v. Reagan Farr, Commissioner of Revenue for the State of Tennessee', 'https://www.courtlistener.com/opinion/1057665/', '1057665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having already rejected the foundation for his argument, we hold that the statutory procedure for appealing an imposition of the tax on unauthorized substances does not violate the due process clauses of the federal and state constitutions.', 'general', 'Steven Waters v. Reagan Farr, Commissioner of Revenue for the State of Tennessee', 'https://www.courtlistener.com/opinion/1057665/', '1057665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In one case, for example, this Court held that “[t]he power of the Legislature to declare and tax privileges is unlimited,” and “[i]ts discretion in this regard cannot be restrained or controlled by the courts.', 'general', 'Steven Waters v. Reagan Farr, Commissioner of Revenue for the State of Tennessee', 'https://www.courtlistener.com/opinion/1057665/', '1057665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the aforementioned principles of statutory construction, we conclude that “original civil action” does not include a *566post-conviction action.', 'general', 'Terrance N. CARTER v. Rickey BELL', 'https://www.courtlistener.com/opinion/1057680/', '1057680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Court of Criminal Appeals.', 'general', 'Terrance N. CARTER v. Rickey BELL', 'https://www.courtlistener.com/opinion/1057680/', '1057680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals.', 'general', 'Terrance N. CARTER v. Rickey BELL', 'https://www.courtlistener.com/opinion/1057680/', '1057680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in deciding to refuse the instructions.', 'general', 'Stevens v. Commonwealth', 'https://www.courtlistener.com/opinion/1063435/', '1063435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in permitting prosecution of the aggravated involuntary manslaughter charge under Code § 18.', 'general', 'Stevens v. Commonwealth', 'https://www.courtlistener.com/opinion/1063435/', '1063435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 141, 144 (1986), in which this Court held that in order to find gross, wanton, and culpable conduct, multiple factors are required other than intoxication to show such conduct.', 'general', 'Stevens v. Commonwealth', 'https://www.courtlistener.com/opinion/1063435/', '1063435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon rehearing en banc, it is ordered that the stay of the mandate is lifted, and the judgment of the trial court is affirmed.', 'general', 'Stevens v. Commonwealth', 'https://www.courtlistener.com/opinion/1063435/', '1063435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the trial court.', 'general', 'Stevens v. Commonwealth', 'https://www.courtlistener.com/opinion/1063435/', '1063435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the judgment of the trial court.', 'general', 'Stevens v. Commonwealth', 'https://www.courtlistener.com/opinion/1063435/', '1063435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that dismissal of the prosecution under Code § 18.', 'dismissal', 'Stevens v. Commonwealth', 'https://www.courtlistener.com/opinion/1063435/', '1063435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the proof in this record in accordance with these familiar standards, we hold that the evidence clearly is sufficient to support the jury’s verdict.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Sixth Amendment applies to both.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sims, after carefully considering the language of the aggravating circumstance as well as the procedure utilized by the trial court, this Court held that in determining whether the statutory elements of a prior felony conviction involve the use of violence against the person, “the trial judge must necessarily examine the facts underlying the prior felony_” 45 S.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”) Viewing the evidence in the light most favorable to the prosecution, we conclude that the evidence is sufficient to support the jury’s determination that the aggravating circumstance outweighs mitigating circumstances beyond a reasonable doubt.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having compared the circumstances of the present case with the circumstances of the cases cited above and others not herein detailed, we conclude that this case, taken as a whole, is not plainly lacking in circumstances consistent with other similar cases in which the death penalty has been imposed.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully and thoroughly considering the issues in light of the record and the relevant authority, we affirm the defendant’s conviction and sentence.', 'sentencing', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to issues not specifically addressed herein, we affirm the decision of the Court of Criminal Appeals, authored by Judge Joe G.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the probative value of the photographs is not outweighed by their prejudicial effect, and the trial court did not abuse its discretion in allowing their admission.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury form in this case was clear and unequivocal.', 'general', 'State of Tennessee v. Detrick Cole', 'https://www.courtlistener.com/opinion/1058445/', '1058445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the issue of whether Dr.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated in Berry, we hold that no error occurred in this case.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having carefully reviewed these issues and the remainder of the issues raised by Leach, we conclude that they do not warrant relief.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '‘ We conclude that the evidence, when examined in the light most favorable to the State, was sufficient to support a finding of premeditation.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence, when viewed in the light most favorable to the State, was sufficient to establish that the intent to commit the underlying felony of robbery existed prior to the acts causing the victims’ deaths.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that Leach would not be entitled to relief even if the issue had been properly preserved.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that any error would be harmless because, assuming Dr.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon an exhaustive review of the record and Supreme Court Rule 12 reports, we conclude that the sentences of death imposed in this case are not excessive or disproportionate when compared to the penalty imposed in similar cases.', 'sentencing', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to issues that were raised in this Court but not addressed in this opinion, we affirm the decision of the Court of Criminal Appeals.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that no harmful error exists, and we affirm the convictions and sentences.', 'sentencing', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in this regard.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in admitting the videotape into evidence.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this issue is without merit.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the defendant is not entitled to relief on this issue.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in allowing Dr.', 'general', 'State v. Leach', 'https://www.courtlistener.com/opinion/1058543/', '1058543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Muhammad was an immediate perpetrator and as such was a principal in the first degree in the commission of capital murder during the commission of an act of terrorism.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the evidence and the instruction, we hold that the trial court did not err in granting instruction 5.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We need not address the legal arguments advanced by Muhammad because we hold that the theories of prosecution by the two independent prosecutors were not inconsistent.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that aggravating factors are not constitutionally required to be recited in a capital murder indictment.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the indictments in this case were sufficient under Virginia law.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the purported violation of Virginia''s indictment provisions in this case does not rise to the level of a federal constitutional claim.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was not an abuse of discretion to refuse Muhammad''s motion for a bill of particulars.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that any error that could have been committed by the failure to *562order a bill of particulars was rendered harmless by the provision of the information Muhammad sought in the Commonwealth''s notice of intent to seek the death penalty.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence does not sustain a claim that there were infirmities in the process, selection, or make-up of the grand jury that indicted Muhammad.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the specific arguments made by Muhammad and the relevant portions of the record he identifies, we hold that the trial court did not abridge his rights under the Sixth Amendment to properly consult with standby counsel.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though the evidence did not show which assailant wielded the rock, we held that Strickler took a direct part in inflicting the fatal injuries and was therefore an "immediate perpetrator.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence established "that Remington and Lenz jointly participated in the victim''s death," we found that the trial court did not err in refusing the instruction.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Rogers, we reversed a defendant''s capital murder conviction because the evidence placed the defendant and another man in the victim''s house at the time of the murder and the Commonwealth failed to present "any evidence .', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the defendant''s death sentence finding him to be "an immediate perpetrator" because both he and his codefendant directly assaulted the victim as they "jointly participated in the fatal beating.', 'sentencing', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the conviction for capital murder holding that because the defendant "took a direct part in inflicting the fatal injuries" he was an "immediate perpetrator" and thus a principal in the first degree.', 'general', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court''s denial of the defendant''s proffered jury instructions that would have instructed the jury that he was a principal in the second degree unless he inflicted the actual fatal blow that caused the victim''s death out of the many blows struck.', 'jury_instruction', 'Muhammad v. Com.', 'https://www.courtlistener.com/opinion/1058965/', '1058965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985) (“However, we hold that ‘depravity of mind’ may, in some circumstances, be shown although torture, as hereinabove defined, did not occur.', 'general', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The case was docketed in this Court, and after a careful review of the record and the relevant legal authorities, we conclude that the evidence is sufficient to support the jury’s finding of premeditation, the evidence is sufficient to support the jury’s finding that the murder was especially heinous, atrocious or cruel in that it involved torture or serious physical abuse beyond that necessary to produce death, and the sentence of death in this case is not excessive or disproportionate consi...', 'sentencing', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained below, we conclude that none of the alleged errors have merit.', 'general', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the proof in this record in a light most favorable to the prosecution, we conclude that the evidence is sufficient to support a finding of both torture and serious physical abuse beyond that necessary to produce death.', 'general', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence is sufficient to support the jury’s determination that the “[t]he murder was especially heinous, atrocious or cruel in that it involved torture or serious physical abuse beyond that necessary to produce death.', 'general', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the fact that lethal injection became a method of execution in Tennessee only after this defendant was tried and sentenced, we conclude that a determination of the constitutionality of lethal injection in this case would deprive this defendant of an opportunity to fully and fairly litigate this issue.', 'sentencing', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to issues not addressed in this opinion, we affirm the decision of the Court of Criminal Appeals authored by Judge Joe G.', 'general', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing this claim, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that this argument is without merit.', 'general', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the sealed records, we find that the trial court properly held that the psychological treatment records need not be disclosed.', 'general', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding there is no error in the record before this Court, we AFFIRM the conviction and sentence of death.', 'sentencing', 'State v. Suttles', 'https://www.courtlistener.com/opinion/1060577/', '1060577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the proof in this case demonstrated robbery “by violence,” we hold that no variance existed between the proof and the indictment alleging robbery “by violence.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred by failing to instruct the jury on facilitation of robbery.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that no variance existed between the indictment alleging robbery “by violence” and the proof showing robbery by pointing a gun at the victim.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a similar case, we held that the failure to instruct on facilitation of especially aggravated robbery and facilitation of aggravated robbery was reversible error.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that no variance existed because pointing a deadly weapon at the victim constitutes robbery “by violence.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that pointing a deadly weapon at the victim constitutes “violence” as used in the offense of robbery pursuant to Tenn.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that evidence existed in this case that reasonable minds could accept as to the offense of facilitation of robbery.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When a lesser-included offense instruction is improperly omitted, we conclude that the harmless error inquiry is the same as for other constitutional errors: whether it appears beyond a reasonable doubt that the error did not affect the outcome of the trial.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that pointing a deadly weapon at the victim constitutes “violence” as used in the offense of robbery pursuant to TenmCode Ann.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Criminal Appeals and remand the case for a new trial.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Garland, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the record in light of the appellants’ claims, we find that the trial court did not exclude any relevant admissible evidence tending to implicate others in the murders while exonerating the appellants.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the appellants have waived any challenge regarding the majority of the comments about which they complain because they failed to voice a contemporaneous objection.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we have reviewed the entire arguments of all parties, and considering the factors listed above, we find that the relatively few improper comments by the prosecutors did not affect the verdict to the prejudice of the appellants.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court correctly denied the appellant’s motion to suppress the search of the motel room.', 'suppression', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 956, and consequently, we hold that the evidence is more than sufficient to establish the appellant’s constructive possession of the cocaine base found in room 132.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the evidence in this case is sufficient to support a finding beyond a reasonable doubt that the defendant possessed drug paraphernalia with the intent to process, prepare, or package crack cocaine in violation of Tennessee Code Annotated section 39-17-425(a)(l).', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that while the trial court should have considered the section 40-35-113(1) mitigating factor in deciding upon an ultimate sentence, the sentence that it actually imposed was proper.', 'sentencing', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the search of the appellant’s motel room did not violate the Forth Amendment to the United States Constitution or Article I, section 7 of the Tennessee Constitution.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, although the trial court should have considered the mitigating factor in Tennessee Code Annotated section 40-35-113(1), we conclude that the maximum sentence in the Range is nevertheless appropriate.', 'sentencing', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 Accordingly, we conclude that a true manifestation of privacy in a hotel or motel room is one that society would recognize as legitimate and reasonable.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the facts of this case, we conclude that the appellant’s conduct failed to exhibit an “actual (subjective) expectation of privacy” in the motel room.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the appellant’s attempted distinction is without merit.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, taking the testimony from these two witnesses in the light most favorable to the State, we conclude that the evidence is sufficient to support finding these two elements of the crime beyond a reasonable doubt.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/1060457/', '1060457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that this claim is without merit.', 'general', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', dissenting), in which a majority of this Court held that “when the defendant is convicted of first degree murder solely on the basis of felony murder,” use of the felony murder aggravating circumstance is not permissible because it “does not narrow the class of death-eligible murderers sufficiently under the Eighth Amendment to the U.', 'general', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the instruction actually given, and the proof in light of the factors delineated in Dyle, we conclude that the failure to give the Dyle instruction does not affirmatively appear to have affected the outcome of this case.', 'general', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, evaluating the inappropriate remarks of the prosecutor in this case in light of the previously mentioned five factors, we conclude that they did not affect the verdict to the prejudice of the defendant.', 'general', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Howell analysis to the record in this case, we conclude that the sentence would have been the same had the sentencing authority given no weight to the invalid aggravating circumstance.', 'sentencing', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that analysis, we conclude that imposition of the death penalty for the senseless and unprovoked killing of this woman in her own home is not disproportionate to the penalty imposed in similar cases, considering the nature of the crime and the defendant.', 'general', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review, we conclude that the following cases in which the death penalty has been imposed have many similarities with this case.', 'general', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, after carefully reviewing the record and considering the errors assigned by the defendant, we affirm the judgment of the trial court and Court of Criminal Appeals upholding the defendant’s conviction of first degree murder and sentence of death by electrocution.', 'sentencing', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to issues not specifically addressed herein, we affirm the decision of the Court of Criminal Appeals, authored by Judge Gary R.', 'general', 'State v. Cribbs', 'https://www.courtlistener.com/opinion/1060886/', '1060886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '293 (1878), a decision rendered one year after passage of the statute, this Court held that a trial court’s erroneous failure to charge on a lesser included offense does not automatically result in reversal.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1060829/', '1060829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a trial court’s erroneous failure to instruct on voluntary manslaughter is subject to harmless error analysis.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1060829/', '1060829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*106Applying that standard to the facts in this case, we conclude that the trial court’s failure to instruct upon voluntary manslaughter constitutes harmless error.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1060829/', '1060829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 459 (Utah 1989) (“We conclude that even if it was error for the trial court not to instruct the jury on negligent homicide .', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1060829/', '1060829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Criminal Appeals and reinstate the judgment of the trial court.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1060829/', '1060829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the trial court’s erroneous failure to instruct the jury on voluntary manslaughter is harmless error, and that the admission of Gloria Buchanan’s testimony was not error, we reverse the judgment of the Court of Criminal Appeals and reinstate the judgment of the trial court in accordance with the jury verdict.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1060829/', '1060829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the evidence in tWs record is sufficient to establish premeditation and deliberation.', 'general', 'State v. Bland', 'https://www.courtlistener.com/opinion/1060945/', '1060945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is clearly sufficient to support these findings.', 'general', 'State v. Bland', 'https://www.courtlistener.com/opinion/1060945/', '1060945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review, we conclude that the following cases in which the death penalty has been imposed have many similarities with this case.', 'general', 'State v. Bland', 'https://www.courtlistener.com/opinion/1060945/', '1060945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 After reviewing the record and considering the errors assigned by the defendant, we affirm the judgment of the trial court and Court of Criminal Appeals.', 'general', 'State v. Bland', 'https://www.courtlistener.com/opinion/1060945/', '1060945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ''' With respect to issues not specifically addressed herein, we affirm the decision of the Court of Criminal Appeals, authored by Judge Paul G.', 'general', 'State v. Bland', 'https://www.courtlistener.com/opinion/1060945/', '1060945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the officer’s decision to stop was based upon reasonable suspicion supported by specific and articulable facts that the defendant was driving on a revoked license, the judgment of the Court of Criminal Appeals is affirmed.', 'general', 'State v. Yeargan', 'https://www.courtlistener.com/opinion/1060948/', '1060948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances of this ease in light of the well-settled principles of law set forth above, we conclude that the officer’s decision to initiate the investigatory stop was based upon reasonable suspicion, supported by specific and articulable facts, that the defendant was driving on a revoked license.', 'general', 'State v. Yeargan', 'https://www.courtlistener.com/opinion/1060948/', '1060948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the reliability of the tip would certainly not establish probable cause to search or arrest, and would not furnish reasonable suspicion to stop the defendant in all circumstances, we conclude that, given the threat of violence, the police had “specific and articulable facts” to warrant the investigatory stop in this case.', 'probable_cause', 'State v. Yeargan', 'https://www.courtlistener.com/opinion/1060948/', '1060948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we hold that § 39—16— 502(a)(1) applies to statements volunteered or initiated by an individual but does not apply to statements made in response to inquiries by law enforcement officers.', 'general', 'State v. Levandowski', 'https://www.courtlistener.com/opinion/1060968/', '1060968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under either test, the challenged testimony was admissible.', 'general', 'Henderson v. Commonwealth', 'https://www.courtlistener.com/opinion/1061742/', '1061742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that Code § 18.', 'general', 'Terra Nyree Hines v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061750/', '1061750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the trial court erred in sentencing appellant to a ten-year term of incarceration and *581remand with instructions for entry of an order consistent with this opinion.', 'sentencing', 'Terra Nyree Hines v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061750/', '1061750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, despite the ambiguous term “mandatory minimum,” we conclude that the General Assembly’s insertion of that phrase and its decision not to specify the class of the felony amounts to a mere legislative oversight and not an intention to substantively change the range of punishment for conviction under Code § 18.', 'general', 'Terra Nyree Hines v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061750/', '1061750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm in part, reverse in part, and remand with instructions.', 'general', 'Terra Nyree Hines v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061750/', '1061750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the conviction order for Al-Tarik Sumner does qualify as a predicate criminal act that establishes the existence of a criminal street gang.', 'general', 'Phillips v. Commonwealth', 'https://www.courtlistener.com/opinion/1062155/', '1062155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm appellant’s conviction for recruitment of a juvenile for criminal street gang membership, and we reverse appellant’s conviction for felony participation in a criminal street gang that included a juvenile member.', 'general', 'Phillips v. Commonwealth', 'https://www.courtlistener.com/opinion/1062155/', '1062155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm appellant’s conviction for recruitment of a juvenile for membership in a criminal street gang, and we reverse appellant’s conviction for felony participation in criminal activity for the benefit of a criminal street gang that includes a juvenile, a Class 4 felony.', 'general', 'Phillips v. Commonwealth', 'https://www.courtlistener.com/opinion/1062155/', '1062155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm appellant’s conviction for recruitment of a juvenile for membership in a criminal street gang because the evidence proves that a criminal street gang existed prior to and independent of appellant’s recruitment of A.', 'general', 'Phillips v. Commonwealth', 'https://www.courtlistener.com/opinion/1062155/', '1062155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Virginia Supreme Court’s decision in Armstrong v.', 'general', 'Barson v. Commonwealth', 'https://www.courtlistener.com/opinion/1061920/', '1061920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the trial court did not err in finding the evidence sufficient to convict Barson of violating Code § 18.', 'general', 'Barson v. Commonwealth', 'https://www.courtlistener.com/opinion/1061920/', '1061920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 Upon rehearing en banc, we affirm the trial court.', 'general', 'Barson v. Commonwealth', 'https://www.courtlistener.com/opinion/1061920/', '1061920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A divided panel of this Court held that the evidence was insufficient to prove that appellant had guilty knowledge of the marijuana.', 'general', 'Ervin v. Commonwealth', 'https://www.courtlistener.com/opinion/1062021/', '1062021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 753, this Court held that the evidence at Coward’s trial was insufficient as a matter of law because it “did not establish any other facts or circumstances necessary to draw the legal conclusion that Coward was aware of the presence and character of the cocaine.', 'general', 'Ervin v. Commonwealth', 'https://www.courtlistener.com/opinion/1062021/', '1062021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm appellant’s conviction for possession of marijuana with intent to distribute.', 'general', 'Ervin v. Commonwealth', 'https://www.courtlistener.com/opinion/1062021/', '1062021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Still, this Court held the Commonwealth did not establish any facts or circumstances, other than Coward’s occupancy of the car and proximity to the cocaine, “necessary to draw the legal conclusion that Coward was aware of the presence and character of the cocaine,” despite the fact that the cocaine was in plain sight upon the passenger console of the vehicle.', 'general', 'Ervin v. Commonwealth', 'https://www.courtlistener.com/opinion/1062021/', '1062021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon rehearing en banc, we affirm the trial court.', 'general', 'Clanton v. Commonwealth', 'https://www.courtlistener.com/opinion/1062525/', '1062525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the trial court.', 'general', 'Clanton v. Commonwealth', 'https://www.courtlistener.com/opinion/1062525/', '1062525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court did not err in denying Raab’s motion to suppress, we affirm his conviction for driving under the influence.', 'suppression', 'Raab v. Commonwealth', 'https://www.courtlistener.com/opinion/1062929/', '1062929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we held that the police officers did not violate the Fourth Amendment by conducting a protective sweep of the apartment.', 'search_seizure', 'Williams v. Commonwealth', 'https://www.courtlistener.com/opinion/1063086/', '1063086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Williams v. Commonwealth', 'https://www.courtlistener.com/opinion/1063086/', '1063086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the trial court’s denial of appellant’s motion to suppress and find the evidence sufficient to sustain the conviction.', 'suppression', 'Williams v. Commonwealth', 'https://www.courtlistener.com/opinion/1063086/', '1063086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that as a general matter determinations of reasonable suspicion and probable cause should be reviewed de novo on appeal.', 'probable_cause', 'Williams v. Commonwealth', 'https://www.courtlistener.com/opinion/1063086/', '1063086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon rehearing en banc, we affirm appellant’s conviction on grounds more narrow than, and independent of, the panel decision.', 'general', 'Luginbyhl v. Commonwealth', 'https://www.courtlistener.com/opinion/1063261/', '1063261') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the January 31, 2003 order was not a final, appealable order.', 'general', 'Estate of Hackler v. Hackler', 'https://www.courtlistener.com/opinion/1063715/', '1063715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the court erred in ruling on the contempt disposition and awarding wife $77,437.', 'general', 'Estate of Hackler v. Hackler', 'https://www.courtlistener.com/opinion/1063715/', '1063715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the January 31, 2003 order was not a final, appealable order.', 'general', 'Estate of Hackler v. Hackler', 'https://www.courtlistener.com/opinion/1063715/', '1063715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'An adjudication of contempt will be reversed “only if we find that [the court] abused its discretion.', 'general', 'Estate of Hackler v. Hackler', 'https://www.courtlistener.com/opinion/1063715/', '1063715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm in part, reverse in part and remand for further proceedings consistent with this opinion.', 'general', 'Estate of Hackler v. Hackler', 'https://www.courtlistener.com/opinion/1063715/', '1063715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s appointment of the conservator pursuant to Rule 4:12.', 'general', 'Estate of Hackler v. Hackler', 'https://www.courtlistener.com/opinion/1063715/', '1063715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part, reverse in part, and remand to the trial court to determine the reasonable fees of the conservator accrued to the date of husband’s death.', 'general', 'Estate of Hackler v. Hackler', 'https://www.courtlistener.com/opinion/1063715/', '1063715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm his convictions.', 'general', 'West v. Commonwealth', 'https://www.courtlistener.com/opinion/1063795/', '1063795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm those convictions.', 'general', 'West v. Commonwealth', 'https://www.courtlistener.com/opinion/1063795/', '1063795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court’s probation violation finding and remand the case to the trial court to vacate that portion of its order.', 'general', 'Word v. Commonwealth', 'https://www.courtlistener.com/opinion/1064114/', '1064114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, to the extent that the trial court may have found that Word violated a condition of probation, we reverse that finding and remand the case to the trial court to vacate that finding and to take such further action as hereafter directed to remove the probation violation finding from Word’s record.', 'general', 'Word v. Commonwealth', 'https://www.courtlistener.com/opinion/1064114/', '1064114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse that portion of the trial court’s order to the extent that it may have found that Word violated a condition of probation;', 'general', 'Word v. Commonwealth', 'https://www.courtlistener.com/opinion/1064114/', '1064114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, however, the trial court’s revocation of a portion of Word’s suspended sentence based upon the court’s determination that it was “an impossibility” for Word to satisfy that condition of his suspended sentence which required that he attend the Program, a requirement imposed as a prerequisite to suspending the sentence.', 'sentencing', 'Word v. Commonwealth', 'https://www.courtlistener.com/opinion/1064114/', '1064114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s revoking Word’s nine-year suspended sentence and in re-suspending all but 120 days, thereby requiring that he serve an additional 120 days of active incarceration.', 'sentencing', 'Word v. Commonwealth', 'https://www.courtlistener.com/opinion/1064114/', '1064114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we affirm the trial court’s revocation of Word’s suspended sentence and re-suspending all but 120 days of the remaining nine-year sentence.', 'sentencing', 'Word v. Commonwealth', 'https://www.courtlistener.com/opinion/1064114/', '1064114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We find that this evidence reasonably supported the trial court’s determination that when he was stopped by Trooper Talbert, Kelly had just transported the drugs from the State of Maryland, into the Commonwealth of Virginia.', 'general', 'Kelly v. Commonwealth', 'https://www.courtlistener.com/opinion/1064158/', '1064158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon rehearing en banc, we affirm the judgment of the trial court as to both convictions.', 'general', 'Kelly v. Commonwealth', 'https://www.courtlistener.com/opinion/1064158/', '1064158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the trial court as to each of Kelly’s convictions.', 'general', 'Kelly v. Commonwealth', 'https://www.courtlistener.com/opinion/1064158/', '1064158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in either the trial court’s legal reasoning or the rationality of its factfinding, we affirm.', 'general', 'Boyd v. County of Henrico', 'https://www.courtlistener.com/opinion/1063916/', '1063916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that the trial court’s denial of appellant’s suppression motion also did not violate the Fourth Amendment.', 'suppression', 'Moyer v. Commonwealth', 'https://www.courtlistener.com/opinion/1065604/', '1065604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that sufficient evidence of intent supports all fourteen convictions.', 'general', 'Moyer v. Commonwealth', 'https://www.courtlistener.com/opinion/1065604/', '1065604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The trial court determined that this was the only reasonable hypothesis flowing from the evidence, and we hold that it did not err in so finding.', 'general', 'Moyer v. Commonwealth', 'https://www.courtlistener.com/opinion/1065604/', '1065604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that the acts for which appellant was convicted fell within the proscriptions of the statute.', 'general', 'Moyer v. Commonwealth', 'https://www.courtlistener.com/opinion/1065604/', '1065604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the decision of the trial court.', 'general', 'Moyer v. Commonwealth', 'https://www.courtlistener.com/opinion/1065604/', '1065604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial court’s denial of appellant’s motion to suppress.', 'suppression', 'Moyer v. Commonwealth', 'https://www.courtlistener.com/opinion/1065604/', '1065604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm appellant’s convictions.', 'general', 'Moyer v. Commonwealth', 'https://www.courtlistener.com/opinion/1065604/', '1065604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a person convicted of a felony may not be sentenced pursuant to W.', 'sentencing', 'Robert L. Holcomb v. David Ballard', 'https://www.courtlistener.com/opinion/1085683/', '1085683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the briefs, the record submitted on appeal, and listening to the argument of the parties, we reverse and remand this ease for further proceedings consistent with this opinion.', 'general', 'Robert L. Holcomb v. David Ballard', 'https://www.courtlistener.com/opinion/1085683/', '1085683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we conclude that the background rule of the common law favoring mens rea should govern interpretation of § 5861(d) in this case.', 'general', 'Staples v. United States', 'https://www.courtlistener.com/opinion/1087954/', '1087954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, in Balint, we concluded that the Narcotic Act of 1914, which was intended in part to minimize the spread of addictive drugs by criminalizing undocumented sales of certain narcotics, required proof only that the defendant knew that he was selling drugs, not that he knew the specific items he had sold were “narcotics” within the ambit of the statute.', 'general', 'Staples v. United States', 'https://www.courtlistener.com/opinion/1087954/', '1087954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 The defendant knew that the items in his possession were grenades, and we concluded that § 5861(d) did not require the Government to prove the defendant also knew that the grenades were unregistered.', 'general', 'Staples v. United States', 'https://www.courtlistener.com/opinion/1087954/', '1087954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the Balint case, after acknowledging the general common-law rule that made knowledge of the facts an element of every crime, we held that as to statutory crimes the question is one of legislative intent, and that the Anti-Narcotic Act should be construed to authorize “punishment of a person for an act in violation of law[,] [even] when ignorant of the facts making it so.', 'general', 'Staples v. United States', 'https://www.courtlistener.com/opinion/1087954/', '1087954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the offense of use of a firearm in the commission of second degree murder in violation of HRS § 134-6(a) is not an included offense4 of second degree murder in violation of HRS § 707-701.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, because (1) theft is an element of first degree robbery, (2) a defendant cannot commit first degree robbery without committing theft or attempted theft, and (3) attempted theft is an included offense of theft, see HRS § 701-109(4)(b), we hold that theft and attempted theft, regardless of degree, are included offenses of first degree robbery.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although Jumila entered pleas of no contest to the second degree murder and HRS § 134-6(a) charges, because he raised the HRS § 701-109 argument at his sentencing hearing, before judgment was entered, and because the prosecution has never contended that Jumila should be precluded from raising the argument, we conclude that Jumila did not waive his HRS § 701-109 rights when he entered his no contest pleas.', 'sentencing', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1210, 1219-20 (1996), wherein we concluded that the offenses of “theft and attempted theft, regardless of degree, are included offenses of first degree robbery.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in order to remedy the HRS § 701-109 violation, we reverse Jumila’s conviction and sentence on the HRS § 134-6(a) charge.', 'sentencing', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Vinge, we held that theft and attempted theft are included offenses of robbery in the first degree.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed both convictions.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the [plaintiffs] do not have a fundamental constitutional right to same-sex marriage arising out of the right to privacy or otherwise.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 1249 (“We hold that the First and Fourteenth Amendments prohibit making mere private possession of obscene material a crime.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mueller, our first case directly addressing the scope of article I, section 6, we held that prostitution is not protected by the right to privacy because the decision “to engage in sex for hire at home” is not a fundamental right nor is basic to ordered liberty.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the right “to read or view pornographic material in the privacy of one’s home must be afforded the protection of the Hawaii Constitution article I, section 6[.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the right to privacy in article I, section 6 of the Hawaii Constitution does not encompass a right to possess and use marijuana for recreational purposes.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we believe that the right to privacy does not in-*442elude such a right, we affirm the ICA’s decision.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '12 Therefore, we affirm the ICA’s decision and affirm Malian’s conviction of promoting a detrimental drug in the third degree.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that HRS § 286-81(l)(A) and the regulations promulgated pursuant to it are within the proper exercise of police power.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a statute proscribing the commercial distribution of harmful substances may sweep within its ambit, as an enforcement measure, the possession of the substance for personal use.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In order to resolve the issue, we must answer the threshold question, “When in conflict, does the individual’s fundamental privacy right to possess pornography at home, as guaranteed by article I,, section 6, take precedence over the sovereign police power of the state to regulate obscene material?” Because we answer the threshold question in the affirmative, we hold that HRS § 712-1214(l)(a) is, indeed, violative of article I, section 6 of the Hawai''i Constitution.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the clear and unambiguous history underlying the promulgation of article I, section 6, we hold that the personal decision to read or view pornographic material in the privacy of one’s own home is protected by article I, section 6 of the Hawai''i Constitution.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In other words, we hold that such activity does not implicate a “state interest,” much less a “compelling” one, and that the state may not criminalize it.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that • HRS § 712 — 1214(l)(a) violates article I, section 6 of the Hawai''i Constitution.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the applicant couples do not have a fundamental constitutional right to same-sex marriage arising out of the right to privacy or otherwise.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that HRS § 712-1249 is not unconstitutional.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we are not convinced a decision to engage in sex for hire is a fundamental right in our scheme of ordered liberty, and we affirm her conviction.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Harvey’s right to a speedy trial for the conspiracy charges was not violated.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the conviction because of a speedy trial violation and directed the trial court to dismiss the indictment.', 'dismissal', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the prejudice from such material “may indeed be greater” than when it is part of the prosecution’s evidence “for it is then not tempered by protective procedures.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that when a defendant testifies in support of a motion to suppress evidence on Fourth Amendment grounds, his testimony may not thereafter be admitted against him at trial on the issue of guilt unless he makes no objection.', 'suppression', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no error occurred in connection with Warren’s trial, and the judgment and sentence entered by the district court is affirmed.', 'sentencing', 'Warren v. State', 'https://www.courtlistener.com/opinion/1118302/', '1118302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury was accurately instructed.', 'general', 'Warren v. State', 'https://www.courtlistener.com/opinion/1118302/', '1118302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err in refusing to give the lesser included offense instruction.', 'general', 'Warren v. State', 'https://www.courtlistener.com/opinion/1118302/', '1118302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was no error committed by the district court in joining the trials of the four defendants.', 'general', 'Warren v. State', 'https://www.courtlistener.com/opinion/1118302/', '1118302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence, considered in the light most favorable to the State, is adequate to sustain Warren’s conviction for aggravated assault and battery with a deadly weapon.', 'general', 'Warren v. State', 'https://www.courtlistener.com/opinion/1118302/', '1118302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), we held that the record must contain a clear statement sufficient to inform the trial court of the basis of asserted error.', 'general', 'Warren v. State', 'https://www.courtlistener.com/opinion/1118302/', '1118302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984), we held that voluntary manslaughter was the lesser included offense of either first or second degree murder in affirming the conviction after the lesser included offense instruction was given.', 'general', 'Warren v. State', 'https://www.courtlistener.com/opinion/1118302/', '1118302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the exemption of the Board’s hearing procedures from the WAPA does not evidence an intent to preclude judicial review of the Board’s revocation decisions.', 'general', 'Pisano v. Shillinger', 'https://www.courtlistener.com/opinion/1118592/', '1118592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Pisano v. Shillinger', 'https://www.courtlistener.com/opinion/1118592/', '1118592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking beyond our own jurisdiction, we find that appellate review of parole decisions is nothing new or radical.', 'general', 'Pisano v. Shillinger', 'https://www.courtlistener.com/opinion/1118592/', '1118592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the ITIA violates neither the Federal nor the Idaho Constitution.', 'general', 'State v. Bennion', 'https://www.courtlistener.com/opinion/1118922/', '1118922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking into account the universal right under territorial law to a jury trial whenever imprisonment threatened, the fact that imprisonment distinguishes criminal sanction, and thé ardent desire of the Framers to interpose juries on the road to the prison cell, we conclude that Article 1, § 7 guarantees a jury trial whenever the possible sanction includes imprisonment.', 'general', 'State v. Bennion', 'https://www.courtlistener.com/opinion/1118922/', '1118922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the scientific acceptance of the Intoximeter 3000 is well-established,____”).', 'general', 'State v. Garrett', 'https://www.courtlistener.com/opinion/1120776/', '1120776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court.', 'general', 'State v. Garrett', 'https://www.courtlistener.com/opinion/1120776/', '1120776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the HGN test does satisfy the Frye standard, because the test is based on a generally accepted theory: Persons who are intoxicated (as well as some other non-intoxicated members of the population) exhibit nystagmus.', 'general', 'State v. Garrett', 'https://www.courtlistener.com/opinion/1120776/', '1120776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prosecu*1036tion need not disprove a heat of passion theory in a second-degree murder case because proof that the defendant acted maliciously nullifies that theory.', 'general', 'Yung v. State', 'https://www.courtlistener.com/opinion/1127691/', '1127691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the standard heat of passion instruction given by the district court was a correct statement of the law and it did not confuse or mislead the jury.', 'general', 'Yung v. State', 'https://www.courtlistener.com/opinion/1127691/', '1127691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant’s tape recorded confession is a non-testimonial exhibit which the jury may review during deliberations.', 'general', 'Yung v. State', 'https://www.courtlistener.com/opinion/1127691/', '1127691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Yung v. State', 'https://www.courtlistener.com/opinion/1127691/', '1127691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1260, we adopted Justice Brennan’s analysis in Dickey, and we held that, in the case of excessive delay, prejudice should be presumed.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that none of the cause for the delay can be attributed to appellant.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, we conclude that appellant adequately asserted his right to a speedy trial and that this factor also weighs in appellant’s favor in the balancing test.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, with respect to the factor of prejudice, we conclude that appellant was presumptively prejudiced by the lengthy delay, but only minimally, so that, as to this factor, the balance is tipped only slightly in appellant’s favor in the overall balancing test.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse appellant’s convictions and remand to the district court with instructions to dismiss the information.', 'dismissal', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Misdemeanor Criminal Rules’ sentencing guidelines do not so infringe upon the right to a jury trial.', 'sentencing', 'State v. Missamore', 'https://www.courtlistener.com/opinion/1131433/', '1131433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that fundamental rights are not implicated in this case.', 'general', 'State v. Missamore', 'https://www.courtlistener.com/opinion/1131433/', '1131433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the dual charging system employed in misdemeanor cases is not a violation of equal protection.', 'general', 'State v. Missamore', 'https://www.courtlistener.com/opinion/1131433/', '1131433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s ruling that the jury should not have been instructed on mistake of fact as a defense.', 'general', 'State v. Missamore', 'https://www.courtlistener.com/opinion/1131433/', '1131433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that sexual assault in the fourth degree is not included in the charged offense as defined by HRS § 701-109(4).', 'general', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm.', 'general', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing discussion, we affirm Buch’s conviction, judgment, and sentence for sexual assault in the third degree.', 'sentencing', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a defendant is strictly liable with respect to the attendant circumstance of the victim’s age in a sexual assault;', 'general', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 288 (1979), despite a clear and unambiguous legislative history—as reflected in the relevant committee reports—of an intent to accomplish a particular result in amending the drug laws, this court held, by virtue of the plain language of its statutory work product, that “the [l]egislature did not carry its intention into effect.', 'general', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 692, 703 (1990) (hereinafter Bartlett I), we held that Joseph Bartlett, Jr.', 'general', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bartlett I, we held that the “broad application of the statute to encompass [Defendant’s] situation results in a penalty grossly out of proportion to the severity of the crime.', 'general', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a comparison of the punishments imposed for other crimes in Arizona reveals the disproportion with which defendant was sentenced under these factual circumstances.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On review, we concluded that Defendant’s sentence constituted cruel and unusual punishment under the eighth amendment to the United States Constitution.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bartlett I, we concluded that “the mandatory minimum sentence imposed on defendant for his first offense was disproportionate to sentences received by similarly situated defendants in other jurisdictions,” and that “the 25-year mandatory minimum imposed for defendant’s second offense [was] also disproportionate to the sentences imposed on similarly situated defendants in other jurisdictions.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Defendant’s forty-year sentence without possibility of early release violates the eighth amendment prohibition of cruel and unusual punishment.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The majority begins its analysis by stating, “In Bartlett I, we held that the ‘broad application of the statute to encompass [Defendant’s] situation results in a penalty grossly out of proportion to the severity of the crime.', 'general', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the above analysis, we hold that defendant’s sentences of 15 years for the first offense and 25 years for the second offense are disproportionate to the crimes he committed under the specific facts of this case, and thus violate the eighth amendment proscription against cruel and unusual punishment.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a comparison of the punishments imposed for other crimes in Arizona reveals the disproportion with which defendant was sentenced under these factual circumstances.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this authority, we conclude that the mandatory minimum sentence imposed on defendant for his first offense was disproportionate to sentences received by similarly situated defendants in other jurisdictions.', 'sentencing', 'State v. Bartlett', 'https://www.courtlistener.com/opinion/1162730/', '1162730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we did in Adkinson and Lord, we hold that if plaintiffs engaged in the criminal conduct they are accused of, then they alone should bear full responsibility for the consequences of their acts, including imprisonment.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Scott we held that the misdemean- or offense of operating a motor vehicle while under the influence of intoxicating liquor (OMVI) was a serious offense, even though the maximum term of imprisonment which *1334could be imposed was one year.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that an assailant convicted of manslaughter for shooting and killing his victim with a shotgun had no claim for relief against either the manufacturer or the seller of the shotgun for direct personal losses alleged to have resulted from the shooting.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Scott this court held that prior criminal convictions can be admitted and given collateral estoppel effect if certain conditions are met.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that actual guilt was an affirmative defense.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal we affirmed in a discussion which implicitly assumed for the purpose of analysis that one cause of the victim’s death was a defect in the shotgun.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lord’s claim is barred for the same reasons we affirmed summary judgment against the plaintiff in Adkinson v.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court’s dismissal of Burcina’s case on the authority of Adkinson, Lord, and Shaw: “[W]e conclude that the public policy principle which precludes a person who has been convicted of a crime from imposing liability on others for the consequences of his or her own antisocial conduct applies here.', 'dismissal', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985) (“We hold that the breach of a physician-patient relationship [by disclosing confidential information] is an actionable tort.', 'general', 'Lee v. Corregedore', 'https://www.courtlistener.com/opinion/1163213/', '1163213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Cor-regedore did not have a duty to prevent Per-reira’s suicide.', 'general', 'Lee v. Corregedore', 'https://www.courtlistener.com/opinion/1163213/', '1163213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that HRS Chapter 363 does not create a statutory duty of care on the part of Veterans’ Services Counselors.', 'general', 'Lee v. Corregedore', 'https://www.courtlistener.com/opinion/1163213/', '1163213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Appellees did not have a duty to prevent Perreira’s suicide, and we affirm the circuit court’s summary judgment in favor of Appel-lees.', 'general', 'Lee v. Corregedore', 'https://www.courtlistener.com/opinion/1163213/', '1163213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When a juvenile (Michael) attempted suicide while in the custody of the Hawai''i Youth Correctional Facility (Boys’ Home), we held that the State’s duty to exercise reasonable care to prevent the juvenile’s suicide arose from the existence of the custodial relationship between the Boys’ Home and the juvenile:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Tarasoff v.', 'general', 'Lee v. Corregedore', 'https://www.courtlistener.com/opinion/1163213/', '1163213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that there is a duty which arises between a teacher or school district and a student.', 'general', 'Lee v. Corregedore', 'https://www.courtlistener.com/opinion/1163213/', '1163213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that: (1) a negligent act or omission may be one which involves an unreasonable risk of harm to another through either (a) the continuous operation of a force started or continued by the act or omission, or (b) the foreseeable action of the other, a third person, an animal or a force of nature;', 'general', 'Lee v. Corregedore', 'https://www.courtlistener.com/opinion/1163213/', '1163213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying UCO, we find that the legislature has described a single offense in AS 11.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1172731/', '1172731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the jury instructions were proper, we reverse the decision of the court of appeals.', 'jury_instruction', 'State v. James', 'https://www.courtlistener.com/opinion/1172731/', '1172731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we reverse the appellate court on the issue of jury unanimity, we must consider a second contention James made in that court.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1172731/', '1172731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that Gay’s failure to request such a question was not *154ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s denial of Carriger’s Rule 32 petition was not an abuse of discretion.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In carefully reviewing the trial record, we conclude that Gay’s examination of the witnesses on the stand does not fall below the Watson standard.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that, assuming Gay did not adequately interview prospective witnesses, Carriger was not thereby prejudiced.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of the report was part of defense trial tactics and will not support a claim of ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 We conclude that Carriger’s testimony would have been detrimental to him.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the aggravating circumstance of pecuniary gain was lawfully found to exist in this case.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Carriger was aware of the necessity of raising competency of counsel issues on appeal.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Carriger was sufficiently informed of the necessity of raising competency of counsel issues on appeal.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is substantial corroboration of Dunbar’s testimony in Carriger’s testimony, we find that the jury would not have been persuaded to accept Carriger’s uncorroborated testimony concerning what he did at the time of the crime.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“Since we are persuaded that “we will be in no better position than we are now” to decide this question, we hold that it is presently ripe for adjudication.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not, however, reach the issue of the effectiveness of the complaint since we hold that the statute is void-for-vagueness and violates appellant’s constitutional right to due process of law.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the trial court did not abuse its discretion in admitting the challenged statements.', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 441, we hold that the probative value of the testimony would outweigh the danger of unfair prejudice to the defendant and would survive a challenge under HRE 403.', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when separate and distinct culpable acts are subsumed within a single count charging a sexual assault—any one of which could support a conviction thereunder—and the defendant is ultimately convicted by a jury of the charged offense, the defendant’s constitutional right to a *33unanimous verdict is violated unless one or both of the following occurs: (1) at or before the close of its case-in-chief, the prosecution is required to elect the specific act upon which it is...', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And inasmuch as we cannot say that there was no reasonable possibility that the circuit court’s error contributed to Arceo’s convictions, we hold that the error was not harmless beyond a reasonable doubt.', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '30 We therefore hold that, if the prosecution does so, then testimony regarding any or all of the multiple acts is “direct evidence of the charged offense” and does not implicate “ ‘other’ crimes, wrongs, or acts with which HRE 404(b) is concerned.', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the ten-day driver’s license revocation provided for under N.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we conclude that the ten-day driver’s license revocation does not constitute punishment as such, and consequently, defendant’s criminal conviction for DWI did not violate the Double Jeopardy Clause.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2(a), we conclude that the legislature intended to permit a qualified arresting officer to notify defendant of his rights, orally and in writing, regarding a chemical analysis of the breath, and we so construe the statute.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, as with the indecent liberties statute at issue in Hartness, we conclude that the disjunctive phrasing of the instruction was not a fatal ambiguity which resulted in a nonunanimous jury verdict.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons which follow, we affirm defendant’s conviction and sentence.', 'sentencing', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under the Double Jeopardy Clause a defendant who already has been punished in a criminal prosecution may not be subjected to an additional civil sanction to the extent that the second *207sanction may not fairly be characterized as remedial, but only as a deterrent or retribution.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The opinion stated: “We hold that a person has been ‘convicted of a felony’ when the appropriate trier of fact has made a determination of guilt and sentence has been imposed.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendants who have entered a plea or have been found guilty of a felony at trial are “convicted of a felony” for purposes of this statute.', 'plea', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the precedent, policy, and reasoning discussed above, we conclude that the most persuasive interpretation of “convicted” is the interpretation first raised in Berg, that a defendant is “convicted of a felony” for purposes of AS 11.', 'general', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that AS 11.', 'general', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the judgments of the superior court.', 'general', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying established Arizona precedent, the most recent example of which is Dolny, to which we adhere, we hold that respondent is not entitled to a jury trial as of right under Arizona law, even assuming he would, if convicted, be a prohibited firearms possessor under federal law.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the most recent case in which this court spoke on this issue, we held that a defendant charged with possession of marijuana was entitled to a jury trial.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in Rothweiler this court held that a defendant charged with driving under the influence was entitled to a jury trial.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held, in Spitz v.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held “that where a defendant is charged with several petty offenses, factually related or arising out of a single event, there is no constitutional requirement of a jury trial, but the actual punishment may not exceed that which would be permissible without a jury trial in case of a single offense.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Baum, we held that, if different criminal acts are at issue, supported by different factual evidence, even though they are separated in time by only a few seconds, one offense is not included in the other.', 'general', 'Rivera v. State', 'https://www.courtlistener.com/opinion/1450123/', '1450123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 407 (1958), this Court held that the one-year statute of limitations is applicable to actions for assault and false imprisonment applied to actions against police officers as well as others.', 'general', 'Fowler v. Valencourt', 'https://www.courtlistener.com/opinion/1225074/', '1225074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the provision ordering a person convicted of a dangerous crime against children supervised on parole “on such conditions as the court .', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1218585/', '1218585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed below, we find that the statute in question crosses the definitionally difficult dividing line between constitutional and unconstitutional delegation of powers and, therefore, violates the mandate of Article 3 of the Arizona Constitution that the powers of government remain separate and distinct.', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1218585/', '1218585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On direct appeal, this Court held that “[i]f the statement here was a reference to the defendants’ failure to testify, it was not an ‘extended reference.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1219741/', '1219741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the error here was not harmless beyond a reasonable doubt and that defendant is entitled to a new trial.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1219741/', '1219741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and hold that any direct reference to defendant’s failure to testify is error and requires curative measures be taken by the trial court.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1219741/', '1219741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), we held that the voluntariness of a plea was not affected where defense counsel stated that a fifteen-year sentence would be imposed, requiring actual confinement of only two or three years, but the defendant was specifically informed by the judge that recommendations by counsel were not binding and that a life sentence could be imposed.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hays was fully aware he was admitting the jurisdictional facts alleged in the information.', 'general', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hays’ contention is not moot.', 'general', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the above points do not show that counsel’s performance so undermined the proceedings that a just result was not produced.', 'general', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the offenses for which the Legislature has authorized life sentences, we conclude that an indeterminate life sentence, with parole eligibility, for lewd and lascivious conduct with a minor is not per se unconstitutional.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that his sentence is proportional to the offense he committed.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hays’ application raised no genuine material issues of fact regarding the district court’s jurisdiction, assistance of counsel, disproportionality of the sentence, and breach of the plea agreement.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that Hays’ sentence is not unreasonable or excessive.', 'sentencing', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'Hays v. State', 'https://www.courtlistener.com/opinion/1220541/', '1220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Court’s order of September 20, 1985, stated: "IT IS HEREBY ORDERED that Appellant''s PETITION FOR REHEARING be, and hereby is, GRANTED only as to the single issue of Jury Instruction Number 18 concerning proof of intent and is hereby DENIED as to all other issues raised by Appellant.', 'jury_instruction', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that all three requirements for a valid plain view seizure were met.', 'general', 'State v. Claiborne', 'https://www.courtlistener.com/opinion/1226900/', '1226900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s ruling that The Ugly Duckling was properly seized under the plain view exception to the warrant requirement.', 'general', 'State v. Claiborne', 'https://www.courtlistener.com/opinion/1226900/', '1226900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm our decision that Magistrate Cruickshanks be suspended without pay until the underlying judicial disciplinary proceeding is completed.', 'general', 'In Re Cruickshanks', 'https://www.courtlistener.com/opinion/1231469/', '1231469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that where an issue of sufficiency of evidence is presented to a trial court, sitting without a jury, in a motion to strike at the conclusion of the Commonwealth’s evidence and, upon its denial and upon conclusion of the defendant’s evidence, the same issue is presented in the defendant’s final argument to the court, the defendant has preserved his right to appeal this issue, even though he did not make a motion to strike at the conclusion of his own evidence.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we hold that the trial court had an opportunity to, and did, consider and resolve the issue now raised on appeal.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 293 (1988), a divided panel of this court held that an appeal of the sufficiency of the evidence in a criminal case tried without a jury was barred by the failure of the defendant to move to strike the evidence even though the closing argument raised the question *481of the sufficiency of the evidence.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge could have inferred from all the evidence that this beating was delivered with the intent to disfigure or disable the child.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, therefore, we affirm the defendant’s conviction of malicious wounding.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 104 (1999), this Court held that a person can be acting lawfully, even if he is in unlawful possession of a weapon, if he was entitled to arm himself in self-defense at the time of the shooting.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1234004/', '1234004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1234004/', '1234004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986), this court held charges of delivery of a controlled substance and possession of a controlled substance with intent to deliver did not merge for double jeopardy purposes.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1236292/', '1236292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the multiple punishments imposed and overrule Birr.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1236292/', '1236292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987), we held that there is no violation of a defendant’s fundamental right to not be placed twice in jeopardy under the Fifth Amendment to the Constitution of the United States or under art.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1236292/', '1236292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Baum, we held that, if different criminal acts are at issue, supported by different factual evidence, even though they are separated in time by only a few seconds, one offense is not included in the other.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1236292/', '1236292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that conviction and punishment for both in a single trial is not prohibited by the provisions of either Constitution.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant may be tried for, convicted of, and punished separately for the crime of breaking or entering and the crime of felony larceny following that breaking or entering when the cases are jointly tried.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 666 (1972), superseded on other grounds by statute, we held that the crimes of felony breaking and entering and felony larceny merged with the crime of murder committed in the perpetration of those felonies.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even had the exchange on cross-examination constituted error, we conclude that, absent such error, the jury probably would have reached the same result.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature intended that the crime of breaking or entering and the crime of felony larceny pursuant to that breaking or entering be separately punished.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that these felonies were not elements of *469kidnapping nor were they sentence-enhancing factors.', 'sentencing', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Brightman v. State', 'https://www.courtlistener.com/opinion/1238104/', '1238104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Leonard', 'https://www.courtlistener.com/opinion/1238571/', '1238571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 523 (1974), where this Court held that where the police stop and surround the occupant of an automobile, they are “seizing” him within the meaning of the Fourth Amendment.', 'search_seizure', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the nature of marijuana as a substance which can be easily concealed and moved about and the relatively brief surveillance of defendant’s residence during the period of forty-two days from the date of the first purchase to the time of the application for search warrant (three brief incidents in a period of eleven days followed by thirty-one days of no surveillance whatever), we conclude that the three purchases at defendant’s residence, as the only facts known to the affiant Bridg...', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“Here, we need not be concerned with the adequacy of the showing of the reliability of Bowers (as the source of hearsay information to the affiant Bridges) because we conclude that, in any event, the hearsay information itself failed to provide any facts, additional to the facts known to the affiant (the three prior purchases), which, taken in conjunction with the three prior purchases, would be adequate to show;', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That evidentiary finding was found by the Court to be sustained by the appeal record, and on that basis we affirmed.', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the language in [two earlier cases] we hold that a defendant may employ deadly force in self-defense only if it reasonably appears to be necessary to protect against death or great bodily harm.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held 1) that the trial judge correctly denied defendant’s motion to suppress her inculpatory statements, and 2) the instructions on self-defense were not prejudicial to defendant.', 'suppression', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*591We conclude that the trial court erred in its ruling but that the error was harmless.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant has failed to show a reasonable possibility that the outcome at trial would have been different had the requested instructions been provided in writing rather than orally, we conclude that the trial court’s error was harmless error.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that this line of cross-examination was proper, as it was relevant to the issue of the credibility of defendant’s testimony that he carried the gun out of fear of robbery and only carried the gun in the club.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no error in admitting the evidence and allowing the prosecutor to refer to it in his closing argument.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s reliance upon Clay is misplaced.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that such an instruction conflicts with the long line of cases which hold that the State’s disproof of element two permits a conviction of murder, while the State’s disproof only of element four results in manslaughter.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we conclude that defendant has not shown error in the trial judge’s instruction on imperfect self-defense.', 'general', 'State v. McAvoy', 'https://www.courtlistener.com/opinion/1244847/', '1244847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Wor-ley could challenge the plea proceeding on appeal, despite his failure to do so by a motion in arrest of judgment.', 'plea', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under these circumstances, rule 23(3)(a) does not preclude our review of Kirchoff’s plea proceeding.', 'plea', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when Kirchoff’s petitions to plead guilty were introduced into the plea proceeding by direct reference and affirmed and acknowledged by Kirchoff in open court, substantial compliance with rule 8(2)(b) was achieved.', 'plea', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no error in either, we affirm.', 'general', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no error in either the plea or sentencing proceedings, we affirm the convictions and sentences.', 'sentencing', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 453 (Iowa 1988), we affirmed a conviction entered after a written plea of guilty despite the defendant’s argument that Fluhr required that we set aside his plea.', 'plea', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 721 (2000), wherein we held that the trial court did not err in refusing to instruct the jury on the specific examples of “sufficient legal provocation” requested by the defendant.', 'general', 'State v. Knoten', 'https://www.courtlistener.com/opinion/1247563/', '1247563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the fact that the defendant and a friend of the victim had previously fought *307and the victim’s friend had pushed over defendant’s stereo did not constitute sufficient legal provocation to support a charge on voluntary manslaughter.', 'general', 'State v. Knoten', 'https://www.courtlistener.com/opinion/1247563/', '1247563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was evidence — in this case introduced by the State — supporting a conviction for the lesser included offense of voluntary manslaughter, we reverse Appellant’s conviction in the slaying of Kimberly Brown.', 'general', 'State v. Knoten', 'https://www.courtlistener.com/opinion/1247563/', '1247563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a jury instruction on voluntary manslaughter was required based on the evidence presented at trial, we REVERSE Appellant’s conviction for the murder of Kim Brown.', 'jury_instruction', 'State v. Knoten', 'https://www.courtlistener.com/opinion/1247563/', '1247563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Cole, supra, we affirmed the defendant’s murder conviction despite the trial court’s failure to give a requested charge on voluntary manslaughter.', 'general', 'State v. Knoten', 'https://www.courtlistener.com/opinion/1247563/', '1247563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is no evidence in the record to support a charge on involuntary manslaughter in the death of Layah Brazil, we affirm Appellant’s murder conviction on that charge.', 'general', 'State v. Knoten', 'https://www.courtlistener.com/opinion/1247563/', '1247563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, as discussed above, we find no merit in Appellant’s other contentions, we AFFIRM Appellant’s remaining convictions and sentences.', 'sentencing', 'State v. Knoten', 'https://www.courtlistener.com/opinion/1247563/', '1247563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*489We hold that the complaint in the case was defective because it did not charge and describe an offense, and that prosecution under the complaint was a violation of Lopez’[s] due process rights under Art.', 'general', 'Crane Creek Country Club v. City of Boise', 'https://www.courtlistener.com/opinion/1249684/', '1249684') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we believe that acceptance of the State’s position is tantamount to the renunciation of a duty imposed upon us by the statutes and our own rules of criminal procedure, we hold that defendant may neither circumvent nor restrict the mandatory appeal to this court provided for him pursuant to the state’s capital-sentencing procedures.', 'sentencing', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defense counsel’s conduct fell “within the wide range of reasonable professional assistance____” Strickland, 466 U.', 'ineffective_assistance', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that defendant may not be charged for first-degree murder of the fetus, we decline the State’s invitation to decide whether the fetus was a “human being” as defined by the homicide statute.', 'general', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 41, 51 (1976), that “[t]he legislature charged this court with the duty to correct [death] sentences which are illegal and sentences where we find that the punishment imposed is greater than the circumstances of the case warrant.', 'sentencing', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the trial court, we find that none of the alleged mitigating factors, taken alone or collectively, is “sufficiently substantial to call for leniency.', 'general', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', his college and work experience, his interaction with the trial court, and the deliberateness with which he performed the prolonged, homicidal attack, we find that age is not a mitigating factor under A.', 'general', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We find that defendant lacks any true sense of remorse for his crime.', 'general', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered and weighed all the mitigation evidence presented, we find that, although it is significant, it is not sufficiently substantial to require leniency in light of the shocking cruelty and senselessness of defendant’s crime.', 'general', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm the trial court’s judgment of conviction upon a plea of guilty and the sentence of death.', 'sentencing', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s findings of an “especially heinous, cruel or depraved manner.', 'general', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a plain reading of Wis.', 'general', 'State v. Sample', 'https://www.courtlistener.com/opinion/1251264/', '1251264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the term "whoever" can be read as singular or plural.', 'general', 'State v. Sample', 'https://www.courtlistener.com/opinion/1251264/', '1251264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain language of Wis.', 'general', 'State v. Sample', 'https://www.courtlistener.com/opinion/1251264/', '1251264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a challenge to either the jury instructions for the inchoate crime of conspiracy, Wis.', 'jury_instruction', 'State v. Sample', 'https://www.courtlistener.com/opinion/1251264/', '1251264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '31 evinces a legislative intent to criminalize both unilateral and bilateral conspiracies, we affirm the judgment of the circuit court.', 'general', 'State v. Sample', 'https://www.courtlistener.com/opinion/1251264/', '1251264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that officer Doney’s frisk of Fleenor was justified because officer Doney possessed articulable facts that justified him in suspecting that Fleenor was armed and presently dangerous.', 'general', 'State v. Fleenor', 'https://www.courtlistener.com/opinion/1254382/', '1254382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the officers’ initial entry into the residence was pursuant to the consent of Fleenor’s roommate.', 'general', 'State v. Fleenor', 'https://www.courtlistener.com/opinion/1254382/', '1254382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that officer Doney’s frisk of Fleenor was reasonable, and that the scope of that frisk did not exceed constitutional bounds.', 'general', 'State v. Fleenor', 'https://www.courtlistener.com/opinion/1254382/', '1254382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that because the officer did not place his hands into the defendant’s pocket or under his outer clothing until the officer felt what he suspected to be a weapon, the search was reasonably confined in scope to discover weapons.', 'general', 'State v. Fleenor', 'https://www.courtlistener.com/opinion/1254382/', '1254382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Fleenor', 'https://www.courtlistener.com/opinion/1254382/', '1254382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prosecution may present evidence, if relevant and helpful, to generally explain the common post-incident behavior of children who are victims of sexual abuse.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Smith, we hold that the trial court exercised the proper discretion in allowing a single expert to clarify why child victims of sexual assault frequently delay reporting the incident.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, for the reasons set forth below, in Peterson, we find that the trial court erred in allowing certain aspects of the expert testimony to be presented to the jury.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in light of the overwhelming evidence against Peterson, we find that any error was harmless.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction in Smith, and note that the conduct of the trial presents an almost perfect model for the limitations that must be set in allowing expert testimony into evidence in child sexual abuse cases.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the use of testimony on general behavioral characteristics of sexually abused children is still the subject of contention and dispute among experts in the field, we find that its use as a general profile to be used to prove the existence of abuse is inappropriate.', 'general', 'People v. Peterson', 'https://www.courtlistener.com/opinion/1281140/', '1281140') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that an unauthorized entry is not a required element of the crime of daytime burglary by breaking and entering as defined in W.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Syllabus Point 2 of Ocheltree, we held that “[c]riminal trespass, as defined by W.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the appellant’s sentence is not subject to our review because the sentence imposed for each conviction is within the statutory limit and the appellant has identified no impermissible factor9 upon which his sentence is based.', 'sentencing', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court’s instruction was identical to the statutory language, we conclude that it was sufficient.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that an unauthorized entry is not an element of daytime burglary by breaking and entering.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that the appellant’s reliance on State v.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not err in declining to answer the jury’s questions.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this rule, we find that the appellant waived any error in the allegedly improper instruction.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the appellant’s conviction for daytime burglary by breaking and entering.', 'general', 'State v. Slater', 'https://www.courtlistener.com/opinion/1258785/', '1258785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '26 Accordingly, we hold that the provision in West Virginia Code § 61-3-24d [defining the crime of larceny by fraudulent scheme] found in subsection (e), which reads, “A violation of law may be prosecuted under this section notwithstanding any other provi*358sion of this code,” does not express a clear legislative intent to create a separate and distinct offense, with separate, additional punishment for the same acts.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing statutory comparison, we hold that every element necessary for a larceny conviction under West Virginia Code § 61-3-24 (false pretenses) is also an element for a larceny conviction under West Virginia Code § 61-3-24d (fraudulent scheme).', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing statutory comparison, we hold that, in the absence of proof that a defendant obtained “services” by a fraudulent scheme, every element necessary for a conviction of larceny by fraudulent scheme under West Virginia Code § 61-3-24d is also an element for conviction of an agent or employee for larceny by embezzlement under West Virginia Code § 61-3-20.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of these arguments in conjunction with the record, we conclude that two of the convictions constitute multiple convictions and sentences for the same acts which violated double jeopardy protections.', 'sentencing', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the jury might properly find Appellant guilty of a single act of larceny with regard to the property of Elkins.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '38 We conclude that the jury might properly find Appellant guilty of a single act of larceny of the property of Micro Vane.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand this case for new orders of conviction and sentencing consistent with this opinion.', 'sentencing', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1258993/', '1258993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that an action for wrongful pregnancy or wrongful conception may be maintained in Virginia.', 'general', 'Miller v. Johnson', 'https://www.courtlistener.com/opinion/1269227/', '1269227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the costs of rearing a reasonably healthy child to majority are not recoverable in a wrongful pregnancy or wrongful conception action.', 'general', 'Miller v. Johnson', 'https://www.courtlistener.com/opinion/1269227/', '1269227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a court or jury is not capable of determining with any reasonable certainty the costs of bringing a child to maturity less the offsetting value of the child’s life.', 'general', 'Miller v. Johnson', 'https://www.courtlistener.com/opinion/1269227/', '1269227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*526Upon consideration of all the above, we find that ample evidence in the record supports the jury’s conclusion that the Commonwealth proved beyond a reasonable doubt each and every constituent element of the crime of larceny.', 'general', 'Welch v. Commonwealth', 'https://www.courtlistener.com/opinion/1277571/', '1277571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the appellant’s conviction.', 'general', 'Welch v. Commonwealth', 'https://www.courtlistener.com/opinion/1277571/', '1277571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to the trial court.', 'general', 'State v. Fuller', 'https://www.courtlistener.com/opinion/1286797/', '1286797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Diamonds v. Greenville County', 'https://www.courtlistener.com/opinion/1288612/', '1288612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we held that New York''s requirement that the defendant, rather than the State, bear the burden of proof on this factual determination comported with the Fourteenth Amendment''s Due Process Clause.', 'general', 'Apprendi v. New Jersey', 'https://www.courtlistener.com/opinion/118381/', '118381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we held that the Constitution does not restrict a judge''s sentencing decision to information that is charged in an indictment and subject to cross-examination in open court.', 'sentencing', 'Apprendi v. New Jersey', 'https://www.courtlistener.com/opinion/118381/', '118381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Articulating for the first time, and then applying, a multifactor set of criteria for determining whether the Winship protections applied to bar such a system, we concluded that the Pennsylvania statute did not run afoul of our previous admonitions against relieving the State of its burden of proving guilt, or tailoring the mere form of a criminal statute solely to avoid Winship'' s strictures.', 'general', 'Apprendi v. New Jersey', 'https://www.courtlistener.com/opinion/118381/', '118381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*488 Rejecting Almendarez-Torres'' objection, we concluded that sentencing him to a term higher than that attached to the offense alleged in the indictment did not violate the strictures of Winship in that case.', 'sentencing', 'Apprendi v. New Jersey', 'https://www.courtlistener.com/opinion/118381/', '118381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*202On appeal, this Court held that appellant’s resistance of arrest was in fact ABHAN because the assault on the officer was the “essence of and inseparate from his resistance of arrest.', 'general', 'Stevenson v. State', 'https://www.courtlistener.com/opinion/1302606/', '1302606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we conclude that defendant’s stop and arrest was proper without resting our decision on the constitutionality of the checkpoint.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Officer Falls did have reasonable articulable suspicion to stop defendant.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case at bar, we conclude that the checkpoint is reasonable, and thus conforms to the Fourth Amendment.', 'search_seizure', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Falls’ standing permission to set up checkpoints pursuant to Captain Jonas’ oral guidelines and Officer Falls’ call to his supervisor before creating the checkpoint at issue are constitutionally sufficient restraints to keep Falls from abusing his discretion.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and because the officers stopped all oncoming traffic at the checkpoint, we conclude that the checkpoint was constitutional.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the absence in Lidster of any focus on an issue dealing with supervisory permission and written guidelines indicates that these issues do not merit a constitutionally mandated reversal in a roadblock case such as the one sub judice.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the Court of Appeals as modified herein.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1303315/', '1303315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for further proceedings.', 'general', 'People v. Greene', 'https://www.courtlistener.com/opinion/1305489/', '1305489') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the State presented substantial evidence of defendant’s intentional, willful, and wanton violation of the ordinance.', 'general', 'State v. Powell', 'https://www.courtlistener.com/opinion/1307857/', '1307857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the sentence of death is not excessive or disproportionate to sentences generally imposed by Virginia juries in crimes of a similar but less horrifying nature.', 'sentencing', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 623, 627 (1968), overruling an earlier decision to the contrary, we held that the trial court properly refused an instruction on second-degree murder where the evidence would support only findings of first-degree murder or not guilty.', 'general', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1031 (1981), we held that the relationships of time, place, and causal connection between a robbery and a murder need not necessarily be jury questions.', 'general', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the killing involved there was so closely related in time, place, and causal connection to the robbery as to make it a part of the same criminal enterprise as a matter of law.', 'general', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the vileness of Fitzgerald’s treatment of his victim exceeded that of any prior *596case we had reviewed until that time.', 'general', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the prosecutions under Code § 18.', 'general', 'Darnell v. Commonwealth', 'https://www.courtlistener.com/opinion/1314707/', '1314707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Grady, although decided after the decision was rendered in the trial court, is applicable to this case.', 'general', 'Darnell v. Commonwealth', 'https://www.courtlistener.com/opinion/1314707/', '1314707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although objections must be specific and not general, in this case we find that the objection was made with sufficient certainty so that the trial judge could understand the precise question he was called upon to decide.', 'general', 'Darnell v. Commonwealth', 'https://www.courtlistener.com/opinion/1314707/', '1314707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2-192 are barred by Grady and, therefore, we reverse the convictions.', 'general', 'Darnell v. Commonwealth', 'https://www.courtlistener.com/opinion/1314707/', '1314707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and dismiss the indictment.', 'dismissal', 'Darnell v. Commonwealth', 'https://www.courtlistener.com/opinion/1314707/', '1314707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing the conviction this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 891 (2002) (per curiam) this Court held as reversible error the following comment by a prosecuting attorney made during closing argument: “[t]here are cases in which the murderer himself says, T am so *742sorry;', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having already so found, we conclude that the fourth prong of Sugg, supra, is satisfied.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Syllabus Point 7 of LaRock, supra, and Syllabus Point 7 of Miller, supra, are dispositive of this issue.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the exception of the last comment considered by us relating to the testimony of the defendant, we find that the statements made by the prosecuting attorney were deliberate.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein we reverse and remand for a new trial.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the reasons stated herein, we reverse and remand for a new trial.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/1324188/', '1324188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Myers we held that “[ajmbiguous penal statutes must be strictly construed against the State and in favor of the defendant.', 'general', 'State v. McClain', 'https://www.courtlistener.com/opinion/1326341/', '1326341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a more plausible reading of the provisions in question which applies the rule of strict construction in favor of a criminal defendant that the Legislature intended under the provisions of West Virginia Code § 62—12—9(b)(4) to establish a six-month limit for the period of incarceration which may be imposed as a condition of probation.', 'general', 'State v. McClain', 'https://www.courtlistener.com/opinion/1326341/', '1326341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this holding to the instant case, we find that the period of incarceration imposed as a condition of probation by the sentencing court was appropriate.', 'sentencing', 'State v. McClain', 'https://www.courtlistener.com/opinion/1326341/', '1326341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Crenshaw, supra, we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the convictions, vacate the death penalty and remand for a new trial.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1330747/', '1330747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Franklin, we concluded that in post-Atkins cases the mental retardation determination is a two-step process.', 'general', 'State v. Laney', 'https://www.courtlistener.com/opinion/1337993/', '1337993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new sentencing proceeding.', 'sentencing', 'State v. Laney', 'https://www.courtlistener.com/opinion/1337993/', '1337993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the above reasoning, we reverse Appellant’s death sentence and remand this matter to the circuit court for a new sentencing proceeding consistent with this opinion.', 'sentencing', 'State v. Laney', 'https://www.courtlistener.com/opinion/1337993/', '1337993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Parris', 'https://www.courtlistener.com/opinion/1340365/', '1340365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we hold that the Miranda requirements did not apply to this situation inasmuch as nothing was asked of the defendant concerning his alleged crime;', 'general', 'State v. Rassmussen', 'https://www.courtlistener.com/opinion/1345472/', '1345472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“  In harmony with the declared public policy of this state with reference to the necessity of corroboration of testimony of the complaining witness in such sex crimes, we hold that the testimony of the prosecuting witness in the prosecution for lewd and lascivious acts must be corroborated either by direct evidence or evidence of surrounding circumstances which clearly corroborate the statements of the complaining witness under the rule as laid down in the case of State v.', 'general', 'State v. Rassmussen', 'https://www.courtlistener.com/opinion/1345472/', '1345472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we disagree with the court of appeals’ rationale, we affirm in result.', 'general', 'State v. Brannon', 'https://www.courtlistener.com/opinion/1346868/', '1346868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the result reached by the court of appeals and find the circuit court erred in denying Brannon’s motion for a directed verdict on the charge of resisting arrest.', 'general', 'State v. Brannon', 'https://www.courtlistener.com/opinion/1346868/', '1346868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in refusing to allow the questioning of prospective jurors concerning their views on parole, as such questioning is irrelevant under the facts of this capital resentencing proceeding.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant received a fair sentencing proceeding, free of prejudicial error.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Brown, 320 N.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bacon I, this Court held that any reasonable doubt about the submission of a mitigating circumstance must be resolved in defendant’s favor.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 703 (1983), this Court held the death sentences disproportionate.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circumstances of Gladden, Clark, and the numerous cases cited by defendant in which the jury returned a life sentence, or in which this Court held the death sentences disproportionate, distinguish those cases from the present case;', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we conclude that defendant received a fair sentencing proceeding, free of prejudicial error, and that the sentence of death is not disproportionate.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has failed to demonstrate any violation of his constitutional protections.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these challenged communications were of an administrative nature and did not relate to the consideration of defendant’s guilt or innocence.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we conclude that no prejudicial error has been shown.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” A chief reason this Court held the death sentence to be disproportionate in Benson was that, in comparison to Jackson, the sentencing jury in Benson found considerably more mitigating circumstances: that the defendant had no significant history of prior criminal activity;', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, after making such a comparison, we find that juries have consistently been returning death sentences in the similar cases, then we will have a strong basis for concluding that a death sentence in the case under review is not excessive or disproportionate.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the other hand if we find that juries have consistently been returning life sentences in the similar cases, we will have a strong basis for concluding that a death sentence in the case under review is excessive or disproportionate.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the State can proceed with the charge of perjury against Canon if the circuit judge finds that the new evidence proffered by the State satisfies the requirements set forth above.', 'general', 'State v. Canon', 'https://www.courtlistener.com/opinion/1348991/', '1348991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'State v. Canon', 'https://www.courtlistener.com/opinion/1348991/', '1348991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a customer who becomes voluntarily intoxicated, even if served liquor in violation of HRS § 281-78(a)(2)(B), is not within the class of persons protected by the statute.', 'general', 'Delos Reyes v. Kuboyama', 'https://www.courtlistener.com/opinion/1349805/', '1349805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that even a minor who was sold liquor in violation of subsection (a)(2)(A) was not part of the class meant to be protected by that statute if he had become voluntarily intoxicated and injured himself, as had the plaintiffs in Bertelmann and Feliciano.', 'general', 'Delos Reyes v. Kuboyama', 'https://www.courtlistener.com/opinion/1349805/', '1349805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Kuboyama owed a duty to Tiffany not to sell liquor to a minor in violation of HRS chapter 281, we vacate the grant of summary judgment and remand this case for further proceedings.', 'general', 'Delos Reyes v. Kuboyama', 'https://www.courtlistener.com/opinion/1349805/', '1349805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, we held that a defendant’s act of necrophilia “without question” constituted the infliction of gratuitous violence on the victim.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that admis*14sion of this evidence did not constitute fundamental error.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant was held accountable only for his own actions.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Overall, after considering the evidence that defendant was impaired to some degree on the night of the murder, as well as his history of drug and alcohol abuse, we find that defendant’s impairment constitutes a non-statutory mitigating circumstance in this case.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant’s initial actions evinced little remorse.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Yet, we find that defendant’s impairment on the night of the murder, when coupled with his history of drug and alcohol abuse,'' constitutes a non-statutory mitigating circumstance in this case.', 'general', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm defendant’s convictions but remand this case for resentencing on the first degree murder conviction.', 'sentencing', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both judgments of conviction, and we affirm defendant’s sentence for sexual conduct with a minor under the age of 15.', 'sentencing', 'State v. Gallegos', 'https://www.courtlistener.com/opinion/1349911/', '1349911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 31 (1980), we held that the trial court’s charge to the jury erroneously included reference to parole eligibility.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 329 (1987), we held that a curative instruction for the jury not to consider parole was unnecessary since the reference to parole was in the context of the defendant’s commission of prior crimes, not to its possibility in the event of a life sentence on the crime charged.', 'sentencing', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 587 (1988), this Court held that the trial court properly refused the defendant’s ex post facto application of increased time for parole eligibility.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the interim, this Court held in State v.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the solicitor’s jury arguments during the penalty phase require that appellant’s sentence of death be vacated.', 'sentencing', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the photographs were relevant to supplement the testimony of the victim’s wife and the medical examiner.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we cannot conclude that the Defendants were deprived of a fair trial by assignment to Division V nor do we conclude that by assigning MVU defendants to Division V, the Shelby County Courts are in violation of Local Rule 4.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the probative value of the photographs is not outweighed by their prejudicial effect and the trial court did not abuse its discretion in allowing their admission.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the jury’s verdict finding Defendant Thomas guilty of first degree murder.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we affirm the jury’s imposition of the sentence of death as to Defendant Thomas.', 'sentencing', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having fully reviewed the record, the briefs and the applicable authority, we affirm Defendant Thomas’ conviction for first degree felony murder.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Grippon is the sole remaining charge to be utilized by the courts of this state in instructing juries in cases relying, in whole or in part, on circumstantial evidence.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the recommended language in Grippon is the sole and exclusive charge to be given in circumstantial evidence cases in this state,14 along with a proper reasonable doubt instruction.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 372, 374 (1991), we held that a circumstantial evidence charge which requires the jury to seek some reasonable explanation other than the defendant’s guilt "turns the State’s burden of proof on its head by requiring the jury to find a ‘reasonable explanation'' of the evidence inconsistent with appellant’s guilt before it can find him not guilty.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '150 (1954), a majority of this Court held in State v.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '9 Although this Court held that the “reasonable hypothesis” language did not shift the burden of proof, we held the instruction actually given by the trial court, adequately conveyed the level of proof required to find Grippon guilty.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in result.', 'general', 'State v. Cherry', 'https://www.courtlistener.com/opinion/1359969/', '1359969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*30Applying the foregoing, we conclude that the State failed to meet its burden of producing substantial evidence that the defendant possessed more than one-half ounce of marijuana on 6 September 1989.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1378015/', '1378015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the State did not produce sufficient evidence that defendant’s vehicle was “used for keeping or selling” a controlled substance.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1378015/', '1378015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the remaining issues presented, we conclude that discretionary review was improvidently granted.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1378015/', '1378015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this evidence is insufficient to establish that defendant’s vehicle was “used for the keeping or selling of” a controlled substance.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1378015/', '1378015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*614We hold that the telephone toll records Saldana complains of were not “intercepted,” and they were not, in fact, acquired, disclosed, or used contrary to the provisions of Wyo.', 'general', 'Saldana v. State', 'https://www.courtlistener.com/opinion/1367458/', '1367458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the federal exclusionary rule, as narrowed by New York v.', 'general', 'Saldana v. State', 'https://www.courtlistener.com/opinion/1367458/', '1367458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that evidence illegally obtained by federal law enforcement personnel cannot be used in Nebraska state courts, provided the lawfulness of the seizure is properly raised and adjudicated.', 'general', 'Saldana v. State', 'https://www.courtlistener.com/opinion/1367458/', '1367458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '22 There, we held that the State must allege, in the face of a motion to quash, which type of intoxication it seeks to prove in a prosecution for involuntary manslaughter.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Porter, we held that the State need not allege which definition of “forgery” it seeks to prove.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that once the State made this allegation, it had to prove it.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Curry’s hypothetically correct jury charge would have instructed the jury to convict Curry if it found that he intentionally or knowingly abducted Williams with the intent to prevent his liberation by using or threatening to use deadly force namely, a firearm, on Williams and with intent to inflict bodily injury on Williams or to terrorize Williams or to violate and abuse Williams sexually.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the phrase “by using and threatening to use deadly force namely, a firearm” was not surplusage.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '24 We concluded that “[i]f the prohibited conduct is statutorily defined to include more than one manner or means of commission,” the State must allege, upon timely request, which manner or means it seeks to establish.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, albeit for different reasons, the court of appeals’ holding that the evidence was sufficient to convict.', 'general', 'Curry v. State', 'https://www.courtlistener.com/opinion/1368507/', '1368507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" In Francis, we held that a jury charge which allows for a non-unanimous verdict concerning what specific criminal act the defendant committed is error.', 'general', 'Ngo v. State', 'https://www.courtlistener.com/opinion/1369576/', '1369576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these particular circumstances, we conclude that, taken as a whole, the jury charge contained error.', 'general', 'Ngo v. State', 'https://www.courtlistener.com/opinion/1369576/', '1369576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 Because we agree with the court of appeals’ reasoning and result, we affirm its judgment.', 'general', 'Ngo v. State', 'https://www.courtlistener.com/opinion/1369576/', '1369576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '52 We affirm the judgment of the court of appeals.', 'general', 'Ngo v. State', 'https://www.courtlistener.com/opinion/1369576/', '1369576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 In Briones, we reversed Petitioner’s convictions of attempted second degree murder and second degree murder, in violation of HRS §§ 705-500 and 707-701.', 'general', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree with Petitioner in certain respects, we reverse his conviction of attempted first degree murder and remand to circuit court *447for a new trial.', 'general', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court’s denial of Petitioner’s Rule 40 petition and remand the case to circuit court.', 'general', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without directly addressing the double jeopardy issue,3 we affirmed Petitioner’s conviction and sentence *449on Count I but reversed his convictions on Counts II and III, and remanded the case for dismissal of those two counts based upon the trial court’s violation of an express statutory provision:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that.', 'general', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Briones I, “we affirm[ed] the [petitioner’s] conviction and sentence as to the attempted first degree murder offense (Count I) .', 'sentencing', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1036 (1982), we held that the denial of a petition to revoke probation, based on the state’s failure to establish a probation violation, did not collaterally estop the state from prosecuting the defendant for sexual assault, even though the sexual assault was the basis for the probation revocation petition.', 'general', 'State v. Nunez', 'https://www.courtlistener.com/opinion/1379263/', '1379263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 756, 765 (1960), this court held that an earlier judgment in a criminal case was conclusive as to all issues actually litigated and adjudicated.', 'general', 'State v. Nunez', 'https://www.courtlistener.com/opinion/1379263/', '1379263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without unduly prolonging this opinion, it is sufficient to say that, based upon our review of the entire record, we find that sufficient evidence exists to withstand defendant’s motion for acquittal.', 'general', 'State v. Nunez', 'https://www.courtlistener.com/opinion/1379263/', '1379263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s conviction and vacate that part of the court of appeals’ opinion designated “Double Jeopardy and Collateral Estop-pel.', 'general', 'State v. Nunez', 'https://www.courtlistener.com/opinion/1379263/', '1379263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 544 — we hold that the victim’s actions did not give rise to the defense of self-defense.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 991, and since Appellant did not offer any evidence showing that the witness had *827been convicted of a felony, we hold that the district court did not abuse its discretion by sustaining the State’s objection.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, while the district court erred by failing to conduct a Jackson-Denno hearing, the error was harmless constitutional error under Campbell v.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we hold that the district court’s failure to hold a Jackson-Denno hearing was harmless beyond a reasonable doubt and that, under the facts of this case, the judge was not required to make an express finding of voluntariness.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that our kidnaping statute, W.', 'general', 'State v. Haught', 'https://www.courtlistener.com/opinion/1386571/', '1386571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration of this matter, we affirm Appellant’s convictions.', 'general', 'State v. Haught', 'https://www.courtlistener.com/opinion/1386571/', '1386571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, finding no constitutional error in Appellant’s sentence, we affirm.', 'sentencing', 'State v. Haught', 'https://www.courtlistener.com/opinion/1386571/', '1386571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we affirm Appellant’s March 12, 2004, conviction for kidnaping and domestic battery.', 'general', 'State v. Haught', 'https://www.courtlistener.com/opinion/1386571/', '1386571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that this language literally required a “person” to be named as the perpetrator in the written instrument in order for that instrument to qualify as an indictment.', 'general', 'Teal v. State', 'https://www.courtlistener.com/opinion/1396275/', '1396275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”4 We held that an “offense” is charged if the written instrument “accuses someone of a crime with enough clarity and specificity to identify the penal statute under which the State intends to prosecute.', 'general', 'Teal v. State', 'https://www.courtlistener.com/opinion/1396275/', '1396275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when an insurer incorporates, into a policy of motor vehicle insurance, an exclusion pursuant to W.', 'general', 'Mitchell v. Broadnax', 'https://www.courtlistener.com/opinion/1396479/', '1396479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recognizing the State’s preeminent interest in protecting its citizens from the financial burdens of collisions with uninsured motorists, this Court held that policies of motor vehicle insurance are required to comply with the statutory requirements of W.', 'general', 'Mitchell v. Broadnax', 'https://www.courtlistener.com/opinion/1396479/', '1396479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a second review of the pertinent authorities, the record presented for appellate review, and the parties’ arguments, we conclude that we cannot definitively determine whether the circuit court’s ruling was in error.', 'general', 'Mitchell v. Broadnax', 'https://www.courtlistener.com/opinion/1396479/', '1396479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following Mitchell’s petition for rehearing, we concluded that justice required us to revisit the public policy attending the enforcement of “owned but not insured” exclusions to motor vehicle insurance coverage, noting in our August 31,1999, rehearing order that our reconsideration of this case would be limited to the “public policy” issue.', 'general', 'Mitchell v. Broadnax', 'https://www.courtlistener.com/opinion/1396479/', '1396479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 488 (1987), we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the court committed no error by using this information to evaluate Gibson’s character.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1397451/', '1397451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record adequately supports the jury’s determination *495that the elements of attempted subornation were proven.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1397451/', '1397451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons explained below, we affirm the judgment of conviction and the sentence.', 'sentencing', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1397451/', '1397451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it does not contradict the sequence of events related in our opinion.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1397451/', '1397451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the stop of defendant’s vehicle was constitutional, we affirm the majority decision of the Court of Appeals that affirmed the trial court’s denial of defendant’s motion to suppress all evidence obtained as a result of the stop.', 'suppression', 'State v. Barnard', 'https://www.courtlistener.com/opinion/1407728/', '1407728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that Thomas waived all but one of his appellate arguments by failing to make specific and timely objections at trial.', 'general', 'Thomas v. Commonwealth', 'https://www.courtlistener.com/opinion/1411697/', '1411697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the issue he preserved for appeal, we hold that the trial court did not abuse its discretion in admitting the contested evidence.', 'general', 'Thomas v. Commonwealth', 'https://www.courtlistener.com/opinion/1411697/', '1411697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Thomas waived all but one of his arguments by not properly raising them at trial.', 'general', 'Thomas v. Commonwealth', 'https://www.courtlistener.com/opinion/1411697/', '1411697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm Thomas’s conviction.', 'general', 'Thomas v. Commonwealth', 'https://www.courtlistener.com/opinion/1411697/', '1411697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '79, 80, this court said: ‘* * * This court held, in State v.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/1422247/', '1422247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 201, 205 (1968), in which this Court held that a plea of guilty to the crime of involuntary manslaughter is admissible in a civil action involving the same factual situation.', 'plea', 'Anderson v. City of Pocatello', 'https://www.courtlistener.com/opinion/1424620/', '1424620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s granting of summary judgment on all counts save the § 1983 claim against the officers.', 'general', 'Anderson v. City of Pocatello', 'https://www.courtlistener.com/opinion/1424620/', '1424620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As in Hodges, “[i]n the absence of an adequate record, or a sufficient reason for the failure to produce a record, we affirm the trial court.', 'general', 'Anderson v. City of Pocatello', 'https://www.courtlistener.com/opinion/1424620/', '1424620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 438 ("We hold that Article I, Section 9 of the Texas Constitution was not violated by [the police officers’] actions.', 'general', 'Laney v. State', 'https://www.courtlistener.com/opinion/1427607/', '1427607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Biegenwald IV, supra, we held that, in the penalty phase of a capital ease, the trial court’s refusal to permit voir dire of the defendant’s other murder convictions denied the defendant his right to a fair and impartial jury.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Rose, supra, we held that the use of specific instances of prior misconduct to impeach a capital defendant’s character evidence was permitted under Evid.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Long, supra, we held that the defendant’s 1985 simple-assault conviction was properly introduced to rebut his assertion under mitigating factor N.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that the Sixth Amendment requires that a jury, and not a judge, find the existence of any aggravating circumstances, and that they be found, not by a mere preponderance of the evidence, but beyond a reasonable doubt.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances, this Court held that the trial court did not abuse its discretion by refusing to permit voir dire regarding the defendant’s prior conviction, because the defendant had not indicated a present intention to take the stand at trial.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Brunson, in which this Court held that when a defendant testifies and the State seeks to impeach his credibility with a prior criminal conviction that is similar in kind to the charged offense, the prior criminal conviction should be sanitized to minimize the potential improper use of the evidence to show propensity to commit the charged offense.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial errors were sufficiently egregious so as to deny defendant a fair trial and, therefore, we are constrained to reverse.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court improperly limited the scope of voir dire.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court committed reversible error in permitting Hazelwood to testify absent the production of a reliable database.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on that record, we conclude that the trial court did not abuse its discretion in keeping non-competent and irrelevant evidence before the jury.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as this Court held in Rega and Speight, we also hold that Appellant has failed to demonstrate any prejudice “by counsel’s failure to ask life-qualification questions,” particularly when “each juror underwent extensive questioning concerning his or her ability to follow the law and assured the trial court that he or she would be able to render a fair and impartial verdict and sentence.', 'sentencing', 'Commonwealth v. Natividad', 'https://www.courtlistener.com/opinion/1440383/', '1440383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Natividad', 'https://www.courtlistener.com/opinion/1440383/', '1440383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for all of the above-stated reasons, we affirm the order of the PCRA court.', 'general', 'Commonwealth v. Natividad', 'https://www.courtlistener.com/opinion/1440383/', '1440383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that an instruction requiring the jury to explain why it is rejecting a death sentence is not per se unconstitutional, and Appellant’s claim fails.', 'sentencing', 'Commonwealth v. Natividad', 'https://www.courtlistener.com/opinion/1440383/', '1440383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally before this Court are the following questions: (1) Did the General Assembly intend that a person charged under Section 6312(d) be subjected to individual counts for each item of child pornography possessed? and (2) If the General Assembly so intended, is it constitutional to impose separate punishments for each conviction? For the following reasons, we hold that Section 6312(d) is not unconstitutionally vague or overbroad.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that charging, trying, convicting and sentencing appellant for multiple counts of possession of child pornography is not unlawful under the statute.', 'sentencing', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Section 6312(d) is not unconstitutionally vague in violation of Article I, Section 9 of the Pennsylvania Constitution or the Fourteenth Amendment.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that Section 6312(d) is not over-broad in violation of Article I, Section 7 of the Pennsylvania Constitution or the First Amendment.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that each image of child pornography creates a permanent record of a child’s abuse, which results in continuing exploitation of a child when the image is subsequently viewed.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that the General Assembly did intend that a person charged under Section 6312(d) may be subjected to individual counts and sentences for each item of child pornography possessed, and that the General Assembly’s intention in this regard is constitutional.', 'sentencing', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statute is not void for vagueness under Article I, Section 9 of the Pennsylvania Constitution or under the Four*27teenth Amendment.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that it was the General Assembly’s intention that a person charged under Section 6312(d) may be subjected to prosecution and punishment for each depiction of child pornography possessed, and that this intention is constitutional.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Superior Court.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Davidson', 'https://www.courtlistener.com/opinion/1440983/', '1440983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that Hock’s remark did not constitute disorderly conduct, and the officer thus lacked probable cause to arrest her for that offense.', 'probable_cause', 'Commonwealth v. Hock', 'https://www.courtlistener.com/opinion/1441554/', '1441554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we find the conduct at issue insufficient to support an arrest, we reverse.', 'general', 'Commonwealth v. Hock', 'https://www.courtlistener.com/opinion/1441554/', '1441554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Superior Court insofar as it relates to the charge of resisting arrest, and reinstate the trial court’s order dismissing that charge.', 'dismissal', 'Commonwealth v. Hock', 'https://www.courtlistener.com/opinion/1441554/', '1441554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Charboneau we held that I.', 'general', 'Stuart v. State', 'https://www.courtlistener.com/opinion/1442563/', '1442563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in State v.', 'general', 'Stuart v. State', 'https://www.courtlistener.com/opinion/1442563/', '1442563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After additional briefing and reargument, we conclude that the district court did not err in denying Stuart’s petition for post conviction relief, and affirm the district court’s judgment dismissing Stuart’s petition for post conviction relief.', 'dismissal', 'Stuart v. State', 'https://www.courtlistener.com/opinion/1442563/', '1442563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We have reviewed the record to determine whether a genuine question of material fact existed and we conclude that the district court did not err in dismissing Stuart’s petition for post conviction relief.', 'dismissal', 'Stuart v. State', 'https://www.courtlistener.com/opinion/1442563/', '1442563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that under State v.', 'general', 'Stuart v. State', 'https://www.courtlistener.com/opinion/1442563/', '1442563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While Stuart correctly recites our holding in Charboneau, we conclude that on the record in this case there was no improper weighing of the mitigating/aggravating circumstances.', 'general', 'Stuart v. State', 'https://www.courtlistener.com/opinion/1442563/', '1442563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that petitioner was not denied his right to counsel because a nonlawyer justice of the peace presided over the petitioner’s jury trial.', 'general', 'Amrein v. State', 'https://www.courtlistener.com/opinion/1445019/', '1445019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984), we held that an accused''s due process rights were not violated by a trial presided over by a nonlawyer justice of the peace.', 'general', 'Amrein v. State', 'https://www.courtlistener.com/opinion/1445019/', '1445019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse all but one of the convictions, sentences and fines, and affirm the petitioner’s conviction, sentence, and fine on one count of cruelty to animals.', 'sentencing', 'Amrein v. State', 'https://www.courtlistener.com/opinion/1445019/', '1445019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At the outset, we hold that DeVarona and Feldman properly testified as lay witnesses.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court erred in failing to explain its determination that Defendant White be held accountable for loss in the amount of $7,290,202.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the witness relied solely on information provided by the plaintiff company to calculate projected loss, we concluded that he lacked the basis necessary to offer such lay testimony.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the prosecution, we find that a rational trier of fact could find the essential elements of each of the offenses underlying Defendant White’s conviction beyond a reasonable doubt.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing, we find that Defendant White has failed to sustain his “heavy burden” on this issue, and that there was sufficient evidence at trial to support his convictions for Medicare fraud, conspiracy to commit Medicare fraud, and use of a false document.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that, viewing the evidence in the light most favorable to the prosecution, sufficient evidence supports Defendant White’s conviction for money laundering.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we found that the government violated Federal Rule of Criminal Procedure 16(a)(1)(G).', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only where the district court’s erroneous admission of evidence affects a substantial right of the party.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When faced with a challenge to the amount of restitution ordered, we reverse only if the district court abused its discretion.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we AFFIRM Defendants’ convictions;', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was legally sufficient to support Laster’s conviction for attempted aggravated kidnapping.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/1450793/', '1450793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '82 We find that the court of appeals applied the correct standard of review and considered all of the relevant evidence before finding that it was factually sufficient.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/1450793/', '1450793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Affording appropriate deference to the jury’s verdict, we therefore hold that the evidence supporting Laster’s conviction is legally sufficient.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/1450793/', '1450793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1452521/', '1452521') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the grandfather had actual authority to consent to a search of the appellant’s bedroom.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the grandfather had actual authority, we need not *557address whether the apparent-authority doctrine would validate his consent to a search of his grandson’s room.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on the facts as the trial court was entitled to view them, Reed had actual authority to consent to the search of the appellant’s bedroom.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that Reed had actual authority to consent to the search, there is no need for us to determine whether the officer’s conduct was justified by Reed’s apparent authority.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 Because we find that the analysis of whether a third party had authority to consent involves an application of legal principles to facts, we now hold that whether a third party had actual authority to consent to a search of another’s *560property and whether an officer was reasonable in finding that a third party had apparent authority to consent are mixed questions of law and fact which reviewing courts should examine de novo.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the court of appeals and, as there are no other points of error requiring remand, we affirm the judgment of the trial court.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the appellant was estopped from complaining that the State failed to establish reasonable suspicion because he invited the error with meritless objections.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that a motion challenging the joinder of the drug/ gun charges with the ADW/threats charges or a motion for severance would *1293have lacked merit.', 'general', 'Howerton v. United States', 'https://www.courtlistener.com/opinion/1489294/', '1489294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, we conclude that the trial judge did not err, let alone plainly err, in not severing the charges sua sponte.', 'general', 'Howerton v. United States', 'https://www.courtlistener.com/opinion/1489294/', '1489294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 5-4-104(a) and § 16-90-120(a-b) can be read harmoniously to mean that § 16-90-120(a-b) is only a sentence enhancement, while the Arkansas Criminal Code provides the minimum sentences to be imposed for each specific offense.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the enhanced felony charge based on the prior battering conviction for which the defendant was convicted, we held that it was error to enhance the defendant’s sentence further based on the general habitual offender statute, codified at Ark.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that enhancement had already occurred under the DWI statute and that the general habitual offender statute, § 5-4-501, could not precipitate an additional sentence.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, we held that the stacking of the two enhancement statutes could not occur.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that it is proper in a capital case to sequentially charge capital murder and felony murder.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a Me/m-type-ultimate-outcome charge during the guilt phase is not required.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[g]iven Bamseur’s intention to include within the reach of the term “depravity’’ only those murders that are entirely without motive, we hold that where, as here, greed, anger, revenge, or other similar motive is present, the depravity aspect of Section (c)(4)(c) [ie.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the centrality of “purpose” in any finding of the escape-detection factor, we hold that the trial court erred in failing to define it during the penalty phase.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 188, we held that a trial court must charge the jury regarding “all of the possible offenses that might reasonably be found from such facts.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that although the question was “very close,” the trial court had been within its discretion in admitting the photos.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the events surrounding Hollenback’s employment with the Monmouth County Prosecutor’s Office do not constitute reversible error.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*361We conclude that felony murder is not the moral equivalent of purposeful-or-knowing murder.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the absence of any legislative intent to create a unified crime of murder and the confusion such a charge would create, we conclude that the trial court properly rejected the request to give a unified-murder charge.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was error because the trial court was obligated to channel the jury’s discretion in its balancing of aggravating and mitigating factors.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brown, supra, we held that the jury should have been instructed that a nonunanimous verdict was acceptable on the question whether defendant had committed the murders by his own conduct.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mejia, supra, we held that the jury should have been informed in the guilt phase that a nonunanimous verdict was acceptable on the question whether the defendant had committed homicide with the intent to cause death or serious bodily injury that resulted in death.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Crosby’s sentence was the rare case where an habitual offender received a grossly disproportionate sentence.', 'sentencing', 'Forehand v. State', 'https://www.courtlistener.com/opinion/1543627/', '1543627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Beck', 'https://www.courtlistener.com/opinion/1576502/', '1576502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court was correct in finding that the evidence did not support the requested instruction on self-defense.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In determining whether the statutory elements of a prior felony conviction involve the use of violence against the person for purposes of § 39-13-204(i)(2), *12we hold that the trial judge must necessarily examine the facts underlying the prior felony if the statutory elements of that felony may be satisfied either with or without proof of violence.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ''' In the current case, we hold that the trial judge was not required to strictly follow the Tennessee Rules of Evidence in determining whether the State should be allowed to question the defense’s mitigation witnesses regarding Sims’s pri- or convictions.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our independent review, we hold that any error on the part of the trial judge in failing to follow this procedure was harmless.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that Sims has waived this issue by failing to raise a contemporaneous objection to the prosecutor’s statement at trial.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this evidence supports a finding of torture in this case.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we hold that the evidence supported application of the (i)(5) aggravator in the current case.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the underlying evidence, this Court held that there was insufficient evidence to support application of the prior violent felony aggravator, Id.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure to grant sua sponte a limiting instruction in this case did not amount to fundamental or prejudicial error.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s conduct does not mandate reversal.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that Taylor is not entitled to UIM coverage under her policies with American Family.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 In Dowhower, we held that a reducing clause in an UIM policy is valid so long as "the policy clearly sets forth that the insured is purchasing a fixed level of UIM recovery that will be arrived at by combining payments made from all sources.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the insureds failed to establish that § 632.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we conclude that the definition of underinsured vehicle in *144American Family''s policies is unambiguous.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the language in each of American Family''s policies at issue satisfies the requirements of Dowhower.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Smith was not entitled to UIM coverage.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the vehicle driven by the other driver was not an underinsured vehicle as defined by Smith''s UIM policy because the $50,000 limit of the other driver''s liability policy was equal to, not less than, the $50,000 limit of Smith''s UIM policy.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the vehicle driven by the other driver was not an underinsured vehicle, we concluded that Smith was not entitled to UIM coverage.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When we read the whole policy carefully, as noted on the first and third pages, we find that the policy clearly sets forth that Taylor purchased a fixed level of UIM recovery that is arrived at by combining payments from all sources, including payments from Hermanson''s liability coverage.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and hold that Taylor is not entitled to UIM coverage under her policies with American Family because the vehicle driven by Hermanson was not an underinsured vehicle as defined by American Family''s policies.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a person convicted of going armed with a concealed and dangerous weapon contrary to Wis.', 'general', 'State v. Perez', 'https://www.courtlistener.com/opinion/1581568/', '1581568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a seized dangerous weapon may not be returned to a person convicted of the crime of carrying a concealed and dangerous weapon.', 'general', 'State v. Perez', 'https://www.courtlistener.com/opinion/1581568/', '1581568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'State v. Perez', 'https://www.courtlistener.com/opinion/1581568/', '1581568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that once a person has been asked to leave the premises by one with authority to exclude him, and where that person has a reasonable opportunity to gather his personal effects prior to leaving, any expectation of privacy that he maintains in the premises is no longer one that society would view as reasonable.', 'general', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'According appropriate deference to the trial court’s decision, we hold that the court did not abuse its discretion in granting the State’s challenge for cause.', 'general', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McVickers, we held that the rules of evidence apply at a hearing on a motion to suppress evidence.', 'suppression', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '45 Viewing the voir dire in its entirety, we conclude that the trial court here had a rational basis for concluding that Crawford’s personal feelings would substantially impair her ability to be fair to the State and to follow the court’s instructions and her oath.', 'general', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The trial court denied the motion on this ground, and we affirmed.', 'general', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Approximately a decade ago, this Court held in McVickers that the rules of evidence apply at a hearing on a motion to suppress.', 'suppression', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 215 (1995), this court held that a “person” under the wrongful-death statute only included those who had been born.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, in Parish, we concluded that the previous caselaw where we granted municipalities immunity from tort liability for the negligence of their employees was patently unjust.', 'general', 'AKA v. Jefferson Hosp. Ass''n, Inc.', 'https://www.courtlistener.com/opinion/1591011/', '1591011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances in the present case, we hold that the school had more than enough reason to discipline Douglas for the content of his story.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although we hold that Douglas''s story is not a true threat and, therefore, cannot be punished under § 947.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that purely written speech, even written speech that fails to cause an actual disturbance, can constitute disorderly conduct as defined by § 947.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the First Amendment does not inherently bar the State from applying § 947.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '01, we conclude that the State is not barred from convicting Douglas for the content of his story merely because his story consisted of purely written speech.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the fact that Douglas''s story did not cause an actual disturbance is irrelevant to the present inquiry.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With this in mind, we conclude that Douglas''s story, although we find it to be offensive and distasteful, unquestionably is protected by the First Amendment.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we concluded that the statute could be interpreted to apply to disorderly physical acts.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16 We therefore hold as a *237matter of law that Douglas''s story cannot be prosecuted under § 947.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the district court and grant a new trial.', 'general', 'Ledezma v. State', 'https://www.courtlistener.com/opinion/1611878/', '1611878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Article I, Section 7 of the Minnesota Constitution prohibits a court from setting a monetary bail amount that can be satisfied only by a cash deposit in the full amount of bail set by the court.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Pettwe held that, following the abolishment of capital punishment in Minnesota, all crimes are bailable.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In construing the section 7 Bail Clause, we held that our constitution guarantees broader protection than the Eighth Amendment of the United States Constitution by providing that all crimes are bailable.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that cash only bail violates Minnesota’s Constitution, we reverse.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this phrase is unambiguous and that it prohibits cash only bail.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, to the extent that we conclude that the section 7 Bail Clause prohibits the court from setting a monetary bail amount that can be satisfied only by a cash deposit in the full amount of bail set by the court, our conclusion is consistent with the purpose of Rule 6.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the court of appeals and remand this matter to the district court for any further proceedings necessary for the actions of that court to be consistent with this opinion.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the meaning of the statutory provision in question is plain, then we give effect to that plain meaning, as long as it does not lead to an absurd result.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1619492/', '1619492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these dictionary definitions, we conclude that in common usage, the term “instrument” is broad enough to encompass a Social Security card and, therefore, that the phrase “other instruments issued by a state or national government or by a subdivision of either,” as used in Texas Penal Code § 32.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1619492/', '1619492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1619492/', '1619492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record is insufficient to determine whether Klessig''s waiver of counsel was knowing, intelligent and voluntary, and that the circuit court should have made an independent determination of Klessig''s competence to represent himself.', 'general', 'State v. Klessig', 'https://www.courtlistener.com/opinion/1623148/', '1623148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that in order for an accused''s waiver of his right to counsel to be valid, the record must reflect not only his deliberate choice to proceed without counsel, but also his awareness of the difficulties and disadvantages of self-representation, the seriousness of the charge or charges he is facing and the general range of possible penalties that may be imposed if he is found guilty.', 'general', 'State v. Klessig', 'https://www.courtlistener.com/opinion/1623148/', '1623148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Pickens, this court held that "competency to stand trial is not the same as competency to proceed pro se and that, even though he has knowingly waived counsel and elected to do so, a defendant may *209be prevented from representing himself.', 'general', 'State v. Klessig', 'https://www.courtlistener.com/opinion/1623148/', '1623148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the court of appeals.', 'general', 'State v. Klessig', 'https://www.courtlistener.com/opinion/1623148/', '1623148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 178 (1984), this court held that where the appellant denied any theft whatever, his request for an instruction on the lesser-included offense of theft by receiving was not rational, and the trial court committed no error in refusing to instruct the jury on the lesser-included offense.', 'general', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the closing argument concession by Gordon''s counsel was not the functional equivalent of a guilty plea on the disorderly conduct while armed count, but, rather, was a reasonable tactical decision under the circumstances of this case.', 'plea', 'State v. Gordon', 'https://www.courtlistener.com/opinion/1638215/', '1638215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Gordon', 'https://www.courtlistener.com/opinion/1638215/', '1638215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse *385State v.', 'general', 'State v. Gordon', 'https://www.courtlistener.com/opinion/1638215/', '1638215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court correctly granted summary judgment dismissing the claim of PMI for lost profits, as well as Mrozek''s claim for lost management fees that was dependent on PMI''s claim for lost profits.', 'dismissal', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that it was error to dismiss Mrozek''s and PMI''s other claims.', 'dismissal', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 However, after reviewing a wide range of authorities, we conclude that issue preclusion is not available based on Mrozek''s guilty pleas.', 'plea', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the following statement from the New Jersey Superior Court properly explains why applying issue preclusion should not be available based on a guilty plea:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Mrozek''s guilty pleas do not fulfill the "actually litigated" requirement for issue preclusion.', 'plea', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we decide that issue preclusion does not apply to a guilty plea and that neither judicial estoppel nor public policy bars a claim for the negligent provision of legal services, we conclude that the circuit court erred in granting summary judgment to Mallery.', 'plea', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we need not decide whether PMI''s claim is core because we conclude that PMI is correct in its contention that the bankruptcy trustee abandoned PMI''s claim against Mallery for the negligent provision of legal services.', 'general', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Morlan and Dewsnup provide the better reasoned view of the effect that a trustee''s abandonment of property has on a Chapter 7 debtor''s ability to proceed on a scheduled claim that has not been subject to administration.', 'general', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the order closing the bankruptcy proceeding did not operate as a final judgment on PMTs claim.', 'general', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part, reverse in part and remand to the circuit court for further proceedings on Mrozek''s and PMI''s remaining claims based on the allegedly negligent provision of legal services.', 'general', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the appellant’s claim was barred by Article 42.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*745In Prior, supra, we held that a trial court may revoke deferred adjudication after the probationary term has expired if three conditions are met: (1) the motion to revoke probation is filed before the probationary term expires, (2) the capias issues before the probationary term expires, and (3) the State has used due diligence in trying to apprehend the probationer.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we held that a defendant must raise due diligence at or before the.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that appellant has failed to preserve such a complaint for review on appeal, and we will not address the contentions in his second ground for review [.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Langston, supra, for example, we reversed the court of appeals, stating that the trial court should have granted the appellant’s motion to dismiss because the State had failed to meet its burden.', 'dismissal', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the same justification, we reversed the court of appeals in Rodriguez v.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Shahan we affirmed Stover''s holding that the trial court has authority to revoke community supervision where the defendant is arrested subsequent to the expiration of the community supervision.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion and that Relator has no adequate remedy by appeal;', 'general', 'Remington Arms Co., Inc. v. Caldwell', 'https://www.courtlistener.com/opinion/1717670/', '1717670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Craig waived any objections to these matters by failing to request a pretrial hearing on the alleged discovery abuse and by requesting a preferential trial setting.', 'general', 'Remington Arms Co., Inc. v. Caldwell', 'https://www.courtlistener.com/opinion/1717670/', '1717670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Craig waived any objections to these matters when he certified to the trial court that his pleadings were in order and that discovery was complete.', 'plea', 'Remington Arms Co., Inc. v. Caldwell', 'https://www.courtlistener.com/opinion/1717670/', '1717670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we hold that the district court erred when it denied Flowers’ motion to suppress the use of the gun as evidence.', 'suppression', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the court erred when it gave the additional instruction.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Olson, we held that the district court’s instruction was improper, and said that instructions on inferences “should be avoided as much as possible.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing general principles, we conclude that the officers did not carefully and appropriately limit their response to the facts and circumstances of this case.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if we were to assume that all of the actions taken by the officers to this point were permissible, we conclude that the officers impermissibly exceeded the scope of a Terry stop when — after their search of Flowers, their search of the vehicle, and the dog-sniff search of the vehicle — the officers returned to the vehicle and conducted another search which lasted for an unknown period of time.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that it is not plausible to believe that during that interval the officers gained a reasonable suspicion that Flowers might have been illegally possessing a firearm.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the officers exceeded the per*258missible scope of a Terry search when they conducted this search.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the totality of these facts and circumstances, we conclude that the state has not met its burden of proving that this Terry search was appropriately limited in scope.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred when it failed to make a record that it specifically considered and weighed the Jones factors.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have previously noted, however, that we will not hesitate to order a new trial when the state, intentionally or unintentionally, elicits information ruled to be inadmissible and we conclude that information is prejudicial to the defendant.', 'general', 'State v. Flowers', 'https://www.courtlistener.com/opinion/1740991/', '1740991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“We therefore hold that under the Double Jeopardy Clause a defendant who has already been punished in a criminal prosecution may not be subjected to an additional civil sanction to the extent that the second sanction may not be characterized as remedial, but only as a deterrent or retribution.', 'general', 'Stennett v. State', 'https://www.courtlistener.com/opinion/1780677/', '1780677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trooper did not articulate sufficient facts to support probable cause to arrest appellant.', 'probable_cause', 'Torres v. State', 'https://www.courtlistener.com/opinion/1796535/', '1796535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in denying appellant’s motion to suppress.', 'suppression', 'Torres v. State', 'https://www.courtlistener.com/opinion/1796535/', '1796535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is no inference to character, and because the evidence is powerfully probative of a primary issue in dispute, the defendant’s state of mind, we hold that Ward’s testimony would be admissible even if it were another act within the meaning of Rule 404(b).', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, in an opinion by Justice Boyle, signed by Chief Justice Riley and Justices Brickley and Griffin, and in a concurring opinion which I wrote, signed by Justices Cavanagh and Archer, that the other acts evidence (a photograph) was not admissible.', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 Consequently, we reverse the decision of the Court of Appeals in each case and remand to the trial court for further proceedings consistent with this opinion.', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals.', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '33 We therefore hold that the trial court erred in determining that the testimony of Steven C and John J was inadmissible.', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '166 is criminal/prohibitory, we hold that the district court and court of appeals erred when they concluded that Minnesota courts do not have jurisdiction to enforce the statute against a tribal member who fails to register while residing on his Indian reservation.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rejecting that claim, we held that the fundamental presumption-of-innoeence right only applies to statutes that “are punitive, or criminal, in nature.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that a tribal member’s violation of section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the broad conduct at issue is residing at an address or moving to a new address by Minnesota residents in general.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the fact that the legislature established a predatory offender registration system is an indication that the whereabouts of predatory offenders — in comparison with the whereabouts of the general population — “presents [a] substantially different or heightened public policy concern[ ].', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislative history of section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With our focus properly placed on the narrow conduct in this case, we conclude that the conduct is unequivocally prohibited by section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the need for the public to aid law enforcement in locating predatory offenders who fail to maintain a current address registration emphasizes the threat of direct physical harm that noncompliant offenders pose.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Jones was aware of the requirements of section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8 Therefore, for all the foregoing reasons, we conclude that Boutin and Kaiser are distinguishable and do not require us to conclude that section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Stone, we held that the state’s interest in enforcing traffic laws against tribal members on-reservation could not overcome “ ‘the right of reservation Indians to make their own laws and be ruled by them.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Busse, we held that Minnesota has jurisdiction to enforce Minn.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the conduct in question, driving after cancellation as inimical to public safety, presents heightened public policy concerns and is a criminal and prohibitory offense.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Crosby, we affirmed a burglary conviction that relied upon circumstantial evidence of intent, stating:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the possession of a large quantity of product, without additional evidence, either direct or circumstantial, is insufficient proof of intent to manufacture under the statute.', 'general', 'State v. Truesdell', 'https://www.courtlistener.com/opinion/1843643/', '1843643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment and sentence for possession of a precursor with intent to manufacture, and remand for dismissal of the charge.', 'dismissal', 'State v. Truesdell', 'https://www.courtlistener.com/opinion/1843643/', '1843643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and sentence of the district court for OWI third offense, driving while barred, and theft in the fourth degree.', 'sentencing', 'State v. Truesdell', 'https://www.courtlistener.com/opinion/1843643/', '1843643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Heuser we held that intent to manufacture could be inferred from the possession of an unusually large amount of pseu-doephedrine by one who also possessed lithium batteries that might be of use in the manufacturing process.', 'general', 'State v. Truesdell', 'https://www.courtlistener.com/opinion/1843643/', '1843643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant was entrapped as a matter of law.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the defendant’s conviction of attempted delivery of heroin.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and reinstate the defendant’s conviction of perjury without prejudice to his filing a motion seeking post-conviction relief on the ground of ineffective assistance of counsel.', 'ineffective_assistance', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the warrant was defective because of insufficient probable cause.', 'probable_cause', 'Arbitration Between Minnesota State Patrol Troopers Ass''n Ex Rel. Pince v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/1855920/', '1855920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the search warrant lacked probable cause and we decline to adopt a good-faith exception, we hold that the evidence seized in the search should have been suppressed at the arbitration hearing.', 'suppression', 'Arbitration Between Minnesota State Patrol Troopers Ass''n Ex Rel. Pince v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/1855920/', '1855920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the arbitration award.', 'general', 'Arbitration Between Minnesota State Patrol Troopers Ass''n Ex Rel. Pince v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/1855920/', '1855920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find ample support in the record for Pince’s discharge from the Patrol, we affirm the trial court on that basis and because of the severe limitation on our authority imposed by statute.', 'general', 'Arbitration Between Minnesota State Patrol Troopers Ass''n Ex Rel. Pince v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/1855920/', '1855920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 265 (1984), where we held that three blows to the head with a fist resulting in fractures to the face and the victim’s hospitalization for five days was sufficient to support a finding of serious physical injury.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, supra, where we held that immersion of the victim’s hands in hot water causing third-degree burns was not life-threatening conduct.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor will we reverse absent a showing of prejudice, as prejudice is not presumed.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that substantial evidence linking Mr.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this sort of mistake "constitutes a compelling equitable consideration under § 806.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But in Phillips we held that the evaluation of the timing of the search vis-a-vis the entry must also consider the conditions existing at the time of the consent.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that even when temporal proximity is very close, "the non-threatening, non-custodial conditions surrounding the search.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Berlin''s entry was justified by the exigent circumstance of hot pursuit.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Focusing on what was known and could reasonably be inferred by the officer at the time of the entry, we conclude that Berlin reasonably believed that the intruder he was pursuing posed a threat to the safety of the occupants of Richter''s trailer.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this information was sufficient to allow Richter to freely consent to the search.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Berlin''s conduct displays the necessary level of purposefulness which is proscribed under the attenuation analysis.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the warrant-less entry of the defendant''s home was justified based on the exigent circumstances of hot pursuit and threat *552to safety and was therefore reasonable under the Fourth Amendment and its Wisconsin counterpart.', 'search_seizure', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the circuit court''s failure to give the parties notice of the entry of the initial final order constituted a "mistake" under Wis.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude the entry was justified by exigent circumstances — specifically, the deputy''s "hot pursuit" of the burglary suspect and his need to protect the safety of those inside the trailer — we reverse.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the use of a peremptory challenge to correct a trial court error is adequate *767grounds for reversal because it arbitrarily deprives the defendant of a statutorily granted right.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Gesch,15 this court held that a defendant does not waive the right to challenge a conviction on the ground of an unfair trial if the defendant does not use a peremptory challenge to remove a juror whom the circuit court should have removed for cause.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03, but we find that there was not sufficient evidence to support a finding that Jeffrey violated § 28-311.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State failed to adduce sufficient evidence to support a finding that Jeffrey violated § 28-311.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we find that the State *826adduced insufficient evidence to support the adjudication, and we reverse the decision of the juvenile court.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although Jeffrey’s actions in this case cannot be condoned or approved of, on our de novo review, we find the evidence insufficient to support the adjudication, and we reverse the decision of the juvenile court.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court of appeals erred when it determined that this court''s decision in Waalen gave the statutory term "materially impaired" a "peculiar meaning in the context of criminal charges," Hubbard, 306 Wis.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1873301/', '1873301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court''s response to the jury''s request for clarification was not error.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1873301/', '1873301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1873301/', '1873301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does.', 'general', 'State v. Grunke', 'https://www.courtlistener.com/opinion/1873990/', '1873990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the legislature meant that subsection (7) would remedy the problems it identified within § 940.', 'general', 'State v. Grunke', 'https://www.courtlistener.com/opinion/1873990/', '1873990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals and remand to the circuit court for further proceedings consistent with this opinion.', 'general', 'State v. Grunke', 'https://www.courtlistener.com/opinion/1873990/', '1873990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the notice of appeal in this case was timely, and therefore we will reverse the court of appeals.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/1874233/', '1874233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Was the sentencing complete: 1) at the initial sentencing hearing on February 12, 2001, or 2) at the time the trial court ordered restitution, on March 12, 2001? Due to the unique facts of this case, we find that the sentence was actually imposed at the restitution hearing, and we reverse the court of appeals.', 'sentencing', 'Bailey v. State', 'https://www.courtlistener.com/opinion/1874233/', '1874233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that no appeal was allowed from the trial court’s order.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/1874233/', '1874233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Goff supra, on the other hand, this court held that strict compliance with § 16-89-125(e) had not been waived where the State failed to show what occurred during a trial judge’s visit to the jury room.', 'general', 'Atkinson v. State', 'https://www.courtlistener.com/opinion/1874985/', '1874985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we cannot say that the trial court erred in declining to instruct the jury on second-degree murder, and we affirm the trial court on this point.', 'general', 'Atkinson v. State', 'https://www.courtlistener.com/opinion/1874985/', '1874985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the trial court on all points.', 'general', 'Atkinson v. State', 'https://www.courtlistener.com/opinion/1874985/', '1874985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 202 (1986), we held that the State had not met its burden of overcoming the presumption of prejudice by showing what occurred when the trial judge answered the jury’s questions because the record was incomplete regarding the trial judge’s actual communication with the jury.', 'general', 'Atkinson v. State', 'https://www.courtlistener.com/opinion/1874985/', '1874985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we hold that the First Amendment to the United States Constitution prohibits L.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, this court held that Pritzlaffs claim for negligent supervision was precluded by the First Amendment because it would require an inquiry into church laws, practices, and policies.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This further explains why this court held that negligent *691supervision claims are "prohibited by the First Amendment under most if not all circumstances.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s claim, we conclude that the undisputed facts and all reasonable inferences drawn therefrom do not establish a genuine issue of material fact as to whether the Diocese knew or should have known about Clauder''s alleged propensity to use his position as chaplain to sexually exploit patients whom he counseled.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s claim, we conclude that the undisputed facts and all reasonable inferences drawn therefrom do not establish a genuine issue of material fact in regard to the element of notice.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the undisputed facts and all reasonable inferences drawn therefrom do not demonstrate a genuine issue of material fact as to whether the Diocese should have known about Clauder''s alleged propensity to use his position as chaplain to sexually exploit patients.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the First Amendment precludes L.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s claim, we conclude that the undisputed facts and all reasonable inferences drawn therefrom do not establish a genuine issue of material fact in regard to whether the Diocese knew or should have known about Clauder''s alleged propensity to use his position as chaplain to sexually exploit patients whom he counseled.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 462, 465 (1996), where we held that a person convicted of murder in the second degree based upon his plea of guilty was entitled to postconviction relief because the information did not allege the element of malice, and for that reason “did not sufficiently charge him with a crime.', 'plea', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 58 (1994), in which we held that it was plain error to omit the element of malice from a jury instruction defining second degree murder under § 28-304(1).', 'jury_instruction', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the doctrine of stare decisis forms the bedrock of our common-law jurisprudence, it does not require us to blindly perpetuate a prior interpretation of the law if we conclude that it was clearly incorrect.', 'general', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In keeping with our long-established rules of statutory construction, we conclude that the language of § 28-304(1) should be given its plain and ordinary meaning in light of the Legislature’s removal of the term “malice” from the definition of second degree murder in its 1977 revision of the criminal code.', 'general', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that construction of § 28-304(1) to include only those elements which the Legislature specifically included in its text does not result in constitutional infirmity.', 'general', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding plain error, we reversed the trial court’s decision, reasoning that “[t]o use a procedural default or waiver as a means of ignoring a plain error that results in an unconstitutional incarceration would place form over substance;', 'general', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in Myers, this court held that the omission of malice from the jury instruction on second degree murder was prejudicially erroneous and plain error.', 'jury_instruction', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Vega-Lara’s prior statements were not admissible as substantive evidence under Rule 801(d)(1)(A).', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore we hold that the district court did not abuse its discretion when it admitted, under Minn.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the extension of incarceration time for refusal to admit sexual offenses in sex-offender treatment rose to the level of compulsion for purposes of the Fifth Amendment.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that calling a witness who the prosecutor knows will claim a privilege can constitute prejudicial misconduct.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Johnson is not disposi-tive.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*751Based on the analysis in these cases, we conclude that immunized testimony cannot be used to convict an individual under Minn.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that once Vega-Lara was granted use immunity, he did not have a valid Fifth Amendment privilege.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that in cases where the State calls a witness who *753refuses to testify, the framework outlined in Mitchell should apply regardless of whether the refusal is based on a valid privilege.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, under the facts and circumstances of this case, we conclude that the State did not call Vega-Lara in bad faith.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State’s ability to call Vega-Lara and then present his prior testimony provided the State with an opportunity to introduce evidence that the district court had ruled was “not otherwise admissible.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In other words, because the State directly suggested to the jury that they should infer the defendant’s guilt from Cozart’s refusal to implicate the defendant in the crime, we held that the defendant’s right to a fair trial was violated.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this argument, we concluded that the State “did everything it could to implant prejudice in the minds of the jury by *770leaving with them the feeling that Cozart’s failure to testify pointed to defendant’s guilt.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the arrest of Appellant was unlawful because Officer Fetterman did not have probable cause to believe that Appellant had committed a crime which would justify his warrantless arrest.', 'probable_cause', 'Commonwealth v. Clark', 'https://www.courtlistener.com/opinion/1889555/', '1889555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is and reverse the Court of Appeals.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in order to constitute a "house of prostitution” a place must be one in which sexual *471acts are committed for compensation.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with our opinion in Diversiñed, we hold that the abatement statute applies only to houses of prostitution, assignation or lewdness, as places where sexual acts are committed.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that the abatement statute "was intended to apply to houses of prostitution and not motion picture theatres where sexual acts are not committed but are portrayed on the screen”.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, in order to determine whether instances of accosting and soliciting for purposes of prostitution constitute prohibited conduct under MCL 600.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*466Consistent with these definitions, we find that the term assignation as used in the abatement act encompasses instances of accosting and soliciting for purposes of prostitution because such instances involve the making of an appointment for the purpose of prostitution.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 We find that limiting this definition to the making of an appointment for the purpose of prostitution is consistent with the apparent legislative intent to eliminate the use of property in connection with prostitution;', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing several decisions in other states,2 we found that the statute is *469" ''directed to the abatement of * * * houses of lewdness, assignation, or prostitution’ ”, and that the terms "lewdness, assignation, and prostitution” are synonymous.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We conclude that the evidence adduced by the appellant establishes that the place was a nuisance under the statute.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no error by the Superior Court, we affirm.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1908680/', '1908680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Harvey, we held that information indicating that the defendant had ordered and received child pornography on thirteen occasions during the fifteen months preceding the issuance of the warrant was not stale.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1908680/', '1908680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 We affirm appel- ■ lant’s convictions and death sentence.', 'sentencing', 'Commonwealth v. Wright', 'https://www.courtlistener.com/opinion/1915693/', '1915693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the verdict and sentence of death.', 'sentencing', 'Commonwealth v. Wright', 'https://www.courtlistener.com/opinion/1915693/', '1915693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that time spent subject to electronic monitoring at home is not time spent in “custody” for purposes of credit under Section 9760.', 'general', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Superior Court erred as a matter of law in remanding this case to the PCRA Court for further evidentiary hearings, based on the Chiappini lead opinion’s case-by-ease approach.', 'general', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this Court held that Kriston was entitled to credit against a required prison sentence for the time he spent on electronic monitoring, essentially, as an equitable matter.', 'sentencing', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the trial court did have such discretionary power.', 'general', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we find that appellee is not entitled to sentencing credit toward his prison sentence for time he spent at home on bail subject to electronic monitoring.', 'sentencing', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Superi- or Court’s remand order and reinstate the order of the PCRA court, denying relief.', 'general', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 601, 603 (1978), we hold that the exception applies in a case like this where the evidence goes to the sanity of the defendant.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We find that the evidence was admissible.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we find that the testimony of the District Director on the relationship between insanity and child abuse was not unduly prejudicial.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that, under art 12 of the Massachusetts Declaration of Rights, counsel for the defendant is entitled to review the records of the complainant’s treatment at the New York Hospital and with the Greenwich, Connecticut, social worker to search for evidence of bias, prejudice, or motive to lie.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant’s convictions for possession of title without complete assignment must be reversed because the evidence at trial was insufficient to establish the mental state required for a violation of section 4— 104(a)(2).', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that section 5 — 401.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant has met his burden of establishing that section 5 — 401.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that section 5 — 401.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, according to the express terms of section 5 — 401.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we held that these statutes were invalid.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 397 (1992), this court held that a finding of knowledge plus criminal intent is required for a defendant to be found guilty of possession of title without complete assignment under section 4 — 104(a)(2) of the Illinois Vehicle Code (625 ILCS 5/4 — 104(a)(2) (West 1996)).', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 281 (1991), this court held that the mental state of knowledge is an element of offenses under section 4 — 104.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, this court held that, to prove a violation of section 4 — 104(a)(2), the State was required to show that a defendant possessed a certificate of title “knowing that he did not have authority or knowing it was without complete assignment.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 62 (1985), for example, this court held that the aggravated arson statute was not rationally related to its purpose because it could be applied to innocent activities.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Zaremba, we held that the following provision of the theft statute offends due process: “A person commits theft when he knowingly: * * * (5) Obtains or exerts control over property in the custody of any law enforcement agency which is explicitly represented to him by any law enforcement officer or any individual acting in behalf of a law enforcement agency as being stolen.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wick, we held that the aggravated arson statute (Ill.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the aggravated arson statute swept too broadly by punishing innocent as well as culpable conduct in setting fires.', 'general', 'People v. Wright', 'https://www.courtlistener.com/opinion/1977301/', '1977301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of these reasons, we hold that 75 Pa.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all the foregoing reasons we conclude that Section 3802(a)-(c) provides a reasonable standard for drivers to gauge their conduct, and therefore, the statute is not void for vagueness.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that they lack standing.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 26 As for Appellant Imes, whose case did involve an accident, we conclude that he has waived the issue.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'above, we conclude that Appellants have either faded to demonstrate that they have standing to challenge Section 3804 or, alternatively, they have waived this claim.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we conclude that 75 Pa.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because we find that § 3731(a)(5) clearly, palpably and plainly violates both the Constitutions of the United States and of this Commonwealth, the order of the trial court is hereby affirmed.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Legislature did not intend the harboring and concealing statute to encompass all aspects of aiding an escape.', 'general', 'People v. Thomas', 'https://www.courtlistener.com/opinion/1992571/', '1992571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant’s alleged conduct exceeds the strictures of MCL 752.', 'general', 'People v. Thomas', 'https://www.courtlistener.com/opinion/1992571/', '1992571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the Court of Appeals.', 'general', 'People v. Thomas', 'https://www.courtlistener.com/opinion/1992571/', '1992571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” For these reasons, we affirm the judgment of the Court of Appeals.', 'general', 'People v. Thomas', 'https://www.courtlistener.com/opinion/1992571/', '1992571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that 11 Del.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that there are facts which can be reasonably assumed to afford support for the decision of the General Assembly to enact legislation restricting the ability of persons who are convicted of a Class A felony or Class B felony sex offense from interacting with the public, during the first ten years of their confinement.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the proper ex post facto analysis, in a case raising the distinction between a punitive provision and a regulatory one, is not whether the enactment is a statute as opposed to a regulation, but rather "whether the legislative aim was to punish [the offender] for past activity, or whether the restriction .', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the finding by the Superior Court that the provisions of Section 6537(b) apply to DiStefano and Stewart.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Superior Court in this case, which held that 11 Del.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Superior Court’s conclusion that there has been no violation of DiStefano’s or Stewart’s right to substantive due process under either the United States Constitution or the Delaware Constitution.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, after a complete analysis, we concluded that DiStefano and Stewart have not been disadvantaged, in violation of the ex post facto prohibition, by the enactment of legislation which makes them generally ineligible for any furlough or work release program.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the use of this language violated due process because the defendant could be convicted in the absence of all facts being proven beyond a reasonable doubt.', 'general', 'State v. Brouillette', 'https://www.courtlistener.com/opinion/2018274/', '2018274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Brouillette', 'https://www.courtlistener.com/opinion/2018274/', '2018274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hausman, the most recent case to entertain any expansion of the public policy exception, we held that "[w]here the law imposes an affirmative obligation upon an employee.', 'general', 'Bammert v. Don''s SuperValu, Inc.', 'https://www.courtlistener.com/opinion/2013834/', '2013834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The case was properly dismissed for failure to state a claim, and we affirm.', 'dismissal', 'Bammert v. Don''s SuperValu, Inc.', 'https://www.courtlistener.com/opinion/2013834/', '2013834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For *245these reasons, we hold that the admission of evidence of the November assault, even if erroneous, was harmless.', 'general', 'State v. Rodriquez', 'https://www.courtlistener.com/opinion/2023007/', '2023007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s decision to permit evidence of prior bad acts by the defendant.', 'general', 'State v. Rodriquez', 'https://www.courtlistener.com/opinion/2023007/', '2023007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error or abuse of discretion in the trial court’s rulings, we affirm the defendant’s convictions.', 'general', 'State v. Rodriquez', 'https://www.courtlistener.com/opinion/2023007/', '2023007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '897 (1984), and the development of the good faith exception to the exclusionary rule in this court, we held that suppression was not necessary when police officers reasonably relied upon a warrant issued by an independent magistrate, even though the "no-knock" portion of the warrant was constitutionally infirm.', 'suppression', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the elements of constructive fraud are not met and that the trial court correctly concluded so.', 'general', 'Town & Country Homecenter of Crawfordsville, Indiana, Inc. v. Woods', 'https://www.courtlistener.com/opinion/2039937/', '2039937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that, while NCB had a duty to protect Fellows, it had no duty to protect T&amp;', 'general', 'Town & Country Homecenter of Crawfordsville, Indiana, Inc. v. Woods', 'https://www.courtlistener.com/opinion/2039937/', '2039937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that the elements of constructive fraud and of criminal deception are not met.', 'general', 'Town & Country Homecenter of Crawfordsville, Indiana, Inc. v. Woods', 'https://www.courtlistener.com/opinion/2039937/', '2039937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that they do not.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Court of Appeals in Woodland v Michigan Citizens Lobby, and we reverse the decision of the trial court in Equitable Life Assurance v Michigan Citizens Lobby.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the importance of the people’s reservation of the power of initiative and the minimal nature of the intrusion on the rights of the mall owners, we hold that allowing citizens to engage in initiative activity in large, privately owned shopping malls subject to reasonable time, place, and manner restrictions, does not unreasonably restrict the mall owners’ rights.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Const 1963, art 2, § 9, authorizes initiative activity in the common areas of large, privately owned shopping malls, subject to reasonable time, place, and manner restrictions, and that the minimal intrusion on the rights of the mall owners is justified in view of the importance of the power of initiative reserved by the people.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that the intrusion on the rights of the shopping center owners by the activities of *248persons seeking signatures on initiative petitions is minimal.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Milliner v. State', 'https://www.courtlistener.com/opinion/2042518/', '2042518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Milliner’s conviction for failing to register as a sex offender.', 'general', 'Milliner v. State', 'https://www.courtlistener.com/opinion/2042518/', '2042518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION In light of the foregoing, we hold that, for purposes of section 401(a)(6.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the search warrant at issue in this case did not violate the warrant clause of the Illinois Constitution (Ill.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the warrant described the items to be seized with sufficient particularity.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgments of the appellate court.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgments of the appellate court.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the trial court’s misapprehension of the evidence’s relevance, we hold that post-crime consciousness of guilt evidence is relevant to state of mind disputes arising in criminal prosecutions for reckless conduct.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the consciousness of guilt evidence is relevant to defendant’s mental state at the time of the shooting for which he is charged with reckless manslaughter.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that at trial on our remand, a strong limiting instruction should be administered by the trial court informing the jury that it should not draw any inference of consciousness of guilt by defendant from his post-crime conduct unless it believes that defendant acted to cover up a crime.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In these circumstances we conclude that this relevant information should not be kept from the jury.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence’s probative value is not outweighed by undue prejudice.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, as our earlier analysis detailed, we find that Cofield’s "similar in kind and reasonably close in time” prong does not have any applicability in this setting.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 951 (2006), and now, we reverse.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion then, we reverse the trial court’s relevance assessment that held, for purposes of Rule 404(b) admission, that defendant’s cover-up conduct was legally irrelevant in the re-prosecution of defendant for reckless manslaughter.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the trial court, affirmed by the Appellate Division, that found that the evidence of defendant’s post-shooting conduct was legally irrelevant and that the evidence’s prejudicial effect required its preclusion under Evidence Rule 404(b).', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2065767/', '2065767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We affirm.', 'general', 'State v. Burke', 'https://www.courtlistener.com/opinion/2070395/', '2070395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the Commonwealth met its burden of proving by a preponderance of the evidence that Nester’s confession was voluntary.', 'general', 'Commonwealth v. Nester', 'https://www.courtlistener.com/opinion/2071064/', '2071064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Commonwealth v. Nester', 'https://www.courtlistener.com/opinion/2071064/', '2071064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gregory, this Court held that where a prosecutor was fully aware of the facts necessary to bring an indictment against a defendant for the sale of heroin and possession with intent to distribute, but indicted and convicted defendant only of the sale charge, a subsequent prosecution for possession with intent to distribute would be barred on fundamental fairness grounds.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Graf we held that the plaintiffs injuries arose out of the "maintenance" of a motor vehicle.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when the action under consideration is undertaken to service or repair a vehicle, and the condition of the vehicle is such that it could not then be driven on a public roadway, the action does not constitute "operation of a motor vehicle" within the meaning of Wis.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Our decision herein is consistent with our discussion in Rocker when we conclude that actions that constitute maintenance or repairs of a motor vehicle, while the condition of the vehicle is such that it could not then be driven on a public roadway, cannot constitute operation of a motor vehicle.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '09, and relying on Modory, we concluded that a snowmobile need not be put in motion in order for it to be operated, but some affirmative action must have occurred.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Bloeehl''s action did not constitute operation of a motor vehicle because Bloeehl''s "primary intention and purpose in attempting to start the car was to finish the repairs.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the exclusion was invalid because a full-service car wash is a motor vehicle handler within § 632.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court''s summary judgment dismissing McNeil''s claims.', 'dismissal', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, in the absence of a different procedure being prescribed in the statute, the action by Ms.', 'general', 'Wright v. City of Little Rock', 'https://www.courtlistener.com/opinion/2100846/', '2100846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we conclude that the tip failed to provide reasonable suspicion to stop defendants, we need not address whether the officers exceeded the scope of a proper Terry search.', 'general', 'People v. Sparks', 'https://www.courtlistener.com/opinion/2100812/', '2100812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the foregoing reasons, as to both defendants, we conclude that the trial court correctly found that the stop of defendants violated their fourth amendment rights (U.', 'search_seizure', 'People v. Sparks', 'https://www.courtlistener.com/opinion/2100812/', '2100812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Sparks', 'https://www.courtlistener.com/opinion/2100812/', '2100812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that context, we hold that an anonymous tip lacking indicia of reliability of the kind contemplated in Adams and White does not justify a stop and frisk whenever and however it alleges the illegal possession of a firearm.', 'general', 'People v. Sparks', 'https://www.courtlistener.com/opinion/2100812/', '2100812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “if a plaintiff asserts the existence of facts that, if proven, establish a special relationship with a defendant in accordance with section 815(b) of the Restatement (Second) of Torts, an action may be maintained against the defendant for negligent supervision liability in accordance with section 317 of the Restatement.', 'general', 'Dragomir v. Spring Harbor Hospital', 'https://www.courtlistener.com/opinion/2107722/', '2107722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm the Superior Court’s order as to vicarious liability, and we vacate its order as to negligent supervision.', 'general', 'Dragomir v. Spring Harbor Hospital', 'https://www.courtlistener.com/opinion/2107722/', '2107722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Superior Court’s order granting summary judgment to Spring Harbor as to Dragomir’s claim of vicarious liability.', 'general', 'Dragomir v. Spring Harbor Hospital', 'https://www.courtlistener.com/opinion/2107722/', '2107722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that property, in this case money, which has been found in a judicial proceeding to have a logical nexus to items which are illegal to possess, such as controlled substances, or have been acquired through illicit means, may constitute contraband as defined in Wis.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature intended that the return of property provision in § 961.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other situations where the state has not initiated a forfeiture action, we conclude that a person claiming the right to property seized by the authorities is limited to the procedures set forth in Wis.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '20, we conclude that in order to retain the property, the state must establish that the property is either contraband or is needed as evidence in a case.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though the circuit court mistakenly placed the burden on the defendant to show whether the cash was or was not contraband, we conclude that based on the evidence of record, this error was harmless.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that it is ambiguous which return of property statute should have been employed, we look to the scope, history, context, subject matter, and object of the statutes to discern the legislative intent.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Rosen is not controlling.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that the legislature intended that the return provision of Wis.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In those situations where the state has not initiated a forfeiture action, we conclude that a person claiming the right to property seized by the authorities is limited to the procedures set forth in § 968.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '13(1)(a), we conclude that contraband is not limited to materials which are per se illegal.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 695 (1988), we held that a judge who initiates, invites, or considers an ex parte communication concerning a *475pending or impending proceeding before the judge must recuse himself or herself from the proceedings when a litigant requests such recusal.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we held that the judge must recuse himself or herself regardless of whether any prejudice is shown.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Mantich, supra, we held that instructions Nos.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 483 (1986), we held that the imposition of the death penalty for felony murder did not violate the Eighth Amendment.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 359 (1990), we held that a capital defendant has the risk of nonpersuasion as to the existence of mitigating circumstances.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the reports were material because they would have led to the discovery of other witnesses and that it was error *492not to grant a continuance to the defendant in light of the prosecution’s delay in producing the reports.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 429 (1985), this court held that evidence of a codefendant’s conviction was inadmissible and denied the defendant her right to a fair trial.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 881 (1977), this court held that subsection (2)(d) refers only to a child of tender age, a juvenile, or a person of advanced years, where senility may be involved.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'McHenry, supra, this court held that the underlying felony merges into a felony murder conviction and cannot be punished separately, barring a clear indication by the Legislature that independent punishments were intended.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 359, 386 (1990), this court held that the term “ ‘apparent’ ” as used in subsection (l)(b) means “ ‘readily perceptible,’ and therefore ‘the provision cannot be applied in speculative situations or where a strained construction is necessary to fulfill it.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 18, 29 (1979), we held that §§ 29-2521.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 54 (1979), this court held that §§ 29-2521.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, this court held that it would continue to make comparisons between first degree murder convictions.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, by definition, there can be no "attempt" to perform an act unless there is a simultaneous "intent" to accomplish such act.', 'general', 'Spradlin v. State', 'https://www.courtlistener.com/opinion/2139707/', '2139707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, we reverse.', 'general', 'Spradlin v. State', 'https://www.courtlistener.com/opinion/2139707/', '2139707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Fink v. Ryan', 'https://www.courtlistener.com/opinion/2148834/', '2148834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the circuit court’s judgment.', 'general', 'Fink v. Ryan', 'https://www.courtlistener.com/opinion/2148834/', '2148834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly held the defendant’s fitness hearing without a jury.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Judge Locallo’s admonishments, despite the omission of the sentences for burglary, substantially complied with Rule 401(a).', 'sentencing', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the trial court had substantially complied with Rule 401(a) in that it had informed the defendant of his right to counsel, described the nature of the charges and explained that the death penalty was a possible sentence.', 'sentencing', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Johnson, this court held a waiver of counsel to be valid despite the fact that the trial court had failed to specifically advise the defendant that he faced a mandatory minimum sentence of life imprisonment.', 'sentencing', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” After reviewing these comments and others made by the trial court, we conclude that the trial court did, as the defendant here claims, dispense with a hearing on eligibility and make a summary finding of eligibility.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the plain and ordinary meaning of the phrase "the defense,” as used in section 104 — 12, does not exclude the defendant.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we find that there was substantial compliance with Rule 401(a).', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the circumstances present in this case, we find that the lapse of time between the admonishments and the waiver did not negate the effectiveness of the admonishments.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this omission did not invalidate the defendant’s waiver of counsel.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons set forth above, we affirm the defendant’s convictions for intentional murder and burglary and affirm his death sentence.', 'sentencing', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, there is no language in our statute or case law that suggests jury unanimity is required on a mitigating circumstance before it can be weighed against any aggravating cireumstances that can be properly found, and we hold that such unanimity is not required.', 'general', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 349 (1986), we held that when the trial court grants the State''s motion in limine and the defendant fails to make an offer of proof during trial, the defendant has not preserved for appellate review any alleged error pertaining to that evidence.', 'general', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the recent Bivins case, we held that "the admissibility of victim impact evidence depends upon its relevance to the death penalty statute''s aggravating and mitigating circumstances.', 'general', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the foregoing sentencing order is insufficient.', 'sentencing', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions of defendant James P.', 'general', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a decision issued April 28, 2000, we reversed a district court decision and held that a defendant in a civil suspension proceeding may challenge the reasonableness of the underlying stop.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the sentence imposed, however, because the district court did not properly apply Iowa Code section 124.', 'sentencing', 'State v. Freeman', 'https://www.courtlistener.com/opinion/2156846/', '2156846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the district court order overruling Freeman’s motion to suppress.', 'suppression', 'State v. Freeman', 'https://www.courtlistener.com/opinion/2156846/', '2156846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court order overruling Freeman’s motion to suppress because the search was incident to a lawful arrest.', 'suppression', 'State v. Freeman', 'https://www.courtlistener.com/opinion/2156846/', '2156846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that if consent is not a defense to the underlying felony, then it is not a defense to the CSC-I charge under MCL 750.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant’s convictions do not violate the double jeopardy protection against multiple punishments.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '520 NW2d 363 (1994), in which this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing this evidence in the light most favorable to the prosecution, we conclude that there was sufficient evidence to permit a rational trier of fact to find that defendant made an intrusion, however slight, with a body part or object into the genital opening of the female victim’s body.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following Ward, we conclude that defendant’s claim has no merit.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that Wybi-erala is controlling in the present case, we do not encourage the use of such tactics by defense counsel.', 'general', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that where a defendant explicitly waives his right to instructions on a lesser included offense he forfeits his right to raise the issue on appeal.', 'general', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Excluding Saturday (the day of arrest) and Sunday, we held that the 36-hour period had not run and that there was no evidence of unnecessary delay.', 'general', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in admitting a statement defendant made at the time of arrest into evidence and that such error is not harmless beyond a reasonable doubt.', 'general', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the informant’s reliability, we think the affidavit was sufficient to support a finding of probable cause, and accordingly, we conclude that defendant’s position on this issue is without merit.', 'probable_cause', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that if a person commits one act of criminal violence, and that act is the only basis upon which he may be convicted of another crime, the act will merge into the other crime.', 'general', 'Commonwealth v. Anderson', 'https://www.courtlistener.com/opinion/2165027/', '2165027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it did not because the force requirement of kidnapping was supplied by holding the customer at gunpoint, not by the assault, and the assault was, therefore, a separate crime.', 'general', 'Commonwealth v. Anderson', 'https://www.courtlistener.com/opinion/2165027/', '2165027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Leon Williams we held that where the same facts are used to support convictions for crimes having different elements, the crimes do not merge for sentencing purposes, unless the same facts support convictions of lesser included offenses.', 'sentencing', 'Commonwealth v. Anderson', 'https://www.courtlistener.com/opinion/2165027/', '2165027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the defendants did not owe Heck a duty to safely store and keep the gun at issue.', 'general', 'Estate of Heck Ex Rel. Heck v. Stoffer', 'https://www.courtlistener.com/opinion/2167057/', '2167057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if we overlook the brief''s deficiencies, we conclude that there *203was no misfeasance because the defendants owed Heck no duty to safely store the gun.', 'general', 'Estate of Heck Ex Rel. Heck v. Stoffer', 'https://www.courtlistener.com/opinion/2167057/', '2167057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Estate of Heck Ex Rel. Heck v. Stoffer', 'https://www.courtlistener.com/opinion/2167057/', '2167057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that the failure to admonish did not require the circuit court to allow defendant’s motion.', 'general', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because a defendant’s right to waive a jury trial and enter a guilty plea will not necessarily be harmed in the absence of the admonishment, we conclude that the presumption of a directory reading of section 113 — 8 is not overcome.', 'plea', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As neither condition articulated in Robinson serves to overcome the presumption of a directory reading in this case, we conclude that the legislature intended such a reading.', 'general', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that section 113 — 8 is mandatory in that it imposes an obligation on the circuit court to admonish all defendants of the potential immigration consequences of a guilty plea.', 'plea', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As noted above, we concluded that the statute in that case was directory.', 'general', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the foregoing reasons, we reverse the judgment of the appellate court, vacating denial of defendant’s motion to withdraw his guilty plea, and affirm the judgment of the circuit court.', 'plea', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this court held with regard to a search warrant in State v.', 'general', 'State v. Gonzales', 'https://www.courtlistener.com/opinion/2170735/', '2170735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the express language of Article 38.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Nguyen’s oral statement was inadmissible under Section 3 of Article 38.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,25 In that case, we held that an individual incarcerated for one offense is not necessarily “in custody” under Miranda and Article 38.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that Nielssen was not under arrest and therefore implied that Nielssen was not in custody.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals’s judgment.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that the trial court erred in permitting James Heath to testify in the State’s case where he was not disclosed to Lowry as a witness prior to the trial.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient evidence of terroristic threats to “burn” the victim to support the stalking conviction, along with numerous incidents of harassment, vandalism, and other hostile acts directed toward the victim and her family.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient circumstantial evidence, properly connected, to support the conviction for arson.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the argument has merit under the circumstances of this case.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in denying Lowry’s motion for continuance.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although it is an issue that will not arise on retrial because Heath is now known to the defense, we conclude that it is a further basis for reversal of this case, based in essence upon the State’s conduct in discovery proceedings.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the evidence regarding the patio furniture does not have the same degree of connection to Lowry, we find that the trial court did not abuse its discretion in admitting the testimony.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for a new trial because the trial court abused its discretion by failing to grant a continuance when counsel for Lowry had received a voluminous amount of the State’s discovery just days prior to the trial, which materially affected the defense’s trial strategy and severely limited counsel’s ability to prepare for trial.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the intrasovereign context, we hold that in the absence of collusion, unlawfully seized evidence may properly be admitted for purposes of an independent civil tax assessment proceeding.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2178876/', '2178876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*536We hold that the introduction of hearsay evidence at a sentencing hearing pursuant to Minn.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), we held that instructions on simple assault were not necessary where the offense charged was aggravated assault.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the appellant’s prior convictions for burglaries, automobile theft, aggravated robbery and aggravated assault as well as the PSI established the necessary propensity toward violent crimes.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), this court held that the statutory language “disposed to the commission of criminal acts of violence” was not unconstitutionally vague as applied to the appellant in that case.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the accomplices’ and Pat Staples’ testimony was adequately corroborated by independent testimony.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s findings pursuant to Minn.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s conviction and sentence.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court was in clear error in granting appellee’s motion to quash the charge of criminal trespass.', 'general', 'Commonwealth v. McBride', 'https://www.courtlistener.com/opinion/2179385/', '2179385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the prosecution, we hold that a rational trier of fact could have found beyond a reasonable doubt that defendant was accountable for Debra’s and Samantha’s murders.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court properly found that, in the statements at issue, Joshua related an “act or matter or detail pertaining to any act which is an element of an offense which is the subject of a prosecution for a sexual or physical act against” him.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court correctly decided that, except for Joshua’s denial that he took medication, his statements were admissible under the spontaneous declaration exception to the hearsay rule.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Eligibility Based on Section 9 — 1(b)(6) for Joshua’s Murder We hold that defendant’s eligibility may be upheld based on the felony-murder statutory aggravating factor predicated on Joshua’s murder.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the challenged verdict form did not omit the required elements for eligibility under section 9 — 1(b)(6) and, therefore, find no plain error.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant was properly found eligible for the death penalty based on the felony-murder statutory aggravating factor premised on Joshua’s murder.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Coleman, we held that a de novo, rather than an abuse of discretion or manifestly erroneous, standard of review applies to a circuit court’s decision to dismiss a defendant’s claims under the Post-Conviction Hearing Act (725 ILCS 5/122 — 1 et seq.', 'dismissal', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mitchell, this court held that the circuit court erred in admitting hearsay statements by a child alleging sexual abuse because the circuit court failed to conduct a hearing, as required by section 115 — 10, and because the record did not support a conclusion that the statements were reliable.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brownell, this court held that the defendant was entitled to a new second stage sentencing hearing because the jury had considered an invalid aggravating factor at that stage.', 'sentencing', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, in Pasch, this court held that the felony-murder statutory aggravating factor was invalid because the evidence at trial did not support the predicate felony, but the jury’s consideration of this factor at the aggravation-mitigation stage was harmless.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '25 Consistently with the legislative mandate, we hold that the aggravating circumstance specified below should have been quashed and, because this was the only aggravating circumstance specified by the Commonwealth, we must vacate the sentence of death and remand *468for imposition of a sentence of life imprisonment.', 'sentencing', 'Commonwealth v. Boczkowski', 'https://www.courtlistener.com/opinion/2181355/', '2181355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 110, 119— 20 (2001), this Court held that for a statement to be considered an excited utterance, it must be made spontaneously and without opportunity for reflection:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we find that this sentence of death cannot stand under Section 9711(h)(3)(i)’s proscription against sentences that are the product of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Commonwealth v. Boczkowski', 'https://www.courtlistener.com/opinion/2181355/', '2181355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the verdict of guilt, but vacate the sentence of death and remand for imposition of a sentence of life imprisonment.', 'sentencing', 'Commonwealth v. Boczkowski', 'https://www.courtlistener.com/opinion/2181355/', '2181355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found appellant’s claims of pre-trial and guilt phase error to be meritless, we affirm appellant’s conviction for first degree murder.', 'general', 'Commonwealth v. Boczkowski', 'https://www.courtlistener.com/opinion/2181355/', '2181355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*43Under these circumstances, we find that harmless error has not been demonstrated beyond a reasonable doubt.', 'general', 'Commonwealth v. Wright', 'https://www.courtlistener.com/opinion/2183142/', '2183142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '299 NW2d 304 (1980), this Court held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In doing so, we find that the instructions, as a whole, correctly informed the jury of the Aaron standard governing malice in felony murder and do not require the jury to have determined such malice only on the basis of the intent to commit the underlying felony.', 'general', 'People v. Kelly', 'https://www.courtlistener.com/opinion/2189436/', '2189436') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the intent necessary for an aiding and abetting conviction is so overwhelmingly evident from the record, we find that no injustice has occurred.', 'general', 'People v. Kelly', 'https://www.courtlistener.com/opinion/2189436/', '2189436') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/2189862/', '2189862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/2189862/', '2189862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Legislature did not intend that knowledge that a firearm is loaded is an element of the offense.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the end sought to be achieved by MCL 750.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and reinstate the defendant’s conviction.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and reinstate the defendant’s conviction.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without restating the several salient facts established in the State’s case against Garza, we conclude that the evidence supports Garza’s conviction.', 'general', 'State v. Garza', 'https://www.courtlistener.com/opinion/2191182/', '2191182') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the district court’s judgment that Garza was guilty of theft by shoplifting, in violation of § 28-511.', 'general', 'State v. Garza', 'https://www.courtlistener.com/opinion/2191182/', '2191182') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Davis case is inapposite and that, therefore, the § 1447 conviction and sentence in the instant case do not fall by reason thereof.', 'sentencing', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons and the reasons stated in Part IV hereof, we conclude that § 1447 creates an offense distinct from the underlying § 613(1) felony of Assault First Degree, and that it was the legislative intent to subject this defendant to multiple penalties for the single criminal act in which she engaged.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Davis, we held that “defendant’s conviction under the weapons statute [§ 1447] cannot stand,” 400 A.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Davis we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the foregoing opinion, we concluded that the Blockburger rule was a rule of substantive law for determining whether two statutes proscribed the “same offense” for double jeopardy purposes.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Justice Rehnquist summarized Whalen on double jeopardy in the following manner: “[S]ix Members of this Court held that Congress’ intent to impose cumulative punishments at a single criminal proceeding completely controlled the question of double jeopardy.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 128 (1890), this court held unconstitutional a statute that required a trial court to issue an injunction, even though the petitioner did not prove damages justifying an injunction.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '407 (1923), this court held unconstitutional a statute prohibiting a trial court from granting a directed verdict before submitting the case to the jury.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 584 (1983), this court held that the legislature could require a circuit court to give the jury a copy of written instructions but could not mandate reversal if the circuit court did not abide by the statute.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judicial power is compromised when the district attorney is given the unilateral power to end a circuit court''s consideration of an inmate''s petition for sentence adjustment.', 'sentencing', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this statute overreaches the legislative power to define and punish criminal conduct.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because deciding the merits of a case is the essence of a court''s function, and because the statute delegates to a district attorney the power to mandate the denial of a petition in each case, we conclude that the legislation in question is an unconstitutional violation of the doctrine of separation of powers.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 660 (1998), we concluded that "[statutes are presumed to be constitutional;', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we reverse Casey’s conviction for intimidation, we note that this decision has no impact on his sentence.', 'sentencing', 'Casey v. State', 'https://www.courtlistener.com/opinion/2195008/', '2195008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was entitled to the benefit of the affirmative defense as shown by the evidence in the record.', 'general', 'People v. Jones', 'https://www.courtlistener.com/opinion/2195044/', '2195044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the appellate court’s holding, we find that the lesser included offense at issue was adequately described by the charging instrument.', 'general', 'People v. Jones', 'https://www.courtlistener.com/opinion/2195044/', '2195044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the foregoing reasons, we hold that Public Act 88 — 680 violates the single subject clause of the Illinois Constitution (Ill.', 'general', 'People v. Cervantes', 'https://www.courtlistener.com/opinion/2197155/', '2197155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Public Act 88 — 680 illustrates this disfavored practice of “logrolling,” wherein less popular legislation was bundled with more palatable bills, so that the well-received bills would carry the unpopular ones to passage.', 'general', 'People v. Cervantes', 'https://www.courtlistener.com/opinion/2197155/', '2197155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the circuit court and hold that Public Act 88 — 680 violates the single subject requirement.', 'general', 'People v. Cervantes', 'https://www.courtlistener.com/opinion/2197155/', '2197155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Court of Appeals erred in affirming the dismissal of the charges.', 'dismissal', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our decision, we hold that the evidence produced during the preliminary examinations necessitates that, the defendants be bound over for trial as charged.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that there is sufficient record support in the cases we decide today to support the charge of illegal possession of a short-barreled shotgun brought against each defendant.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that two defendants may be charged with possession of one short-barreled shotgun when each defendant has in his possession one of two components that comprise the weapon.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that possession of a prohibited firearm is not limited to actual possession, but may include both constructive possession, and joint possession by defendants acting in concert.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that the fact that a firearm is temporarily inoperable does not preclude prosecution for its possession where the statute expressly prohibits such possession.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the decisions of the Court of Appeals and the federal courts are well-reasoned interpretations of the intent of the respective Legislatures when they enacted the applicable statutes regulating the possession and use of firearms.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that MCL 750.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that it was an abuse of discretion to dismiss the charge against defendant Medley.', 'dismissal', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse the decision of the Court of Appeals, reinstate the charges against the defendants, and remand the cases to the trial court for proceedings consistent with this opinion.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2200054/', '2200054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*** Accordingly, we hold that section 5 — 401.', 'general', 'People v. Carpenter', 'https://www.courtlistener.com/opinion/2203829/', '2203829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that section 12— 612 of the Code is facially invalid on due process grounds.', 'general', 'People v. Carpenter', 'https://www.courtlistener.com/opinion/2203829/', '2203829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we held that these statutes were invalid.', 'general', 'People v. Carpenter', 'https://www.courtlistener.com/opinion/2203829/', '2203829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 potentially subjects *** innocent conduct to such a severe penalty, we find that it does not contain a reasonable means of preventing the trafficking of stolen vehicles and parts.', 'general', 'People v. Carpenter', 'https://www.courtlistener.com/opinion/2203829/', '2203829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 We conclude that the $52,000 award is not supported by the evidence.', 'general', 'Evans v. Evans', 'https://www.courtlistener.com/opinion/2205836/', '2205836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8 Therefore, we reverse the trial court''s $52,000 award and remand to the court for a hearing to determine the extent of James'' actual damages, if any, resulting from Evans'' contempt.', 'general', 'Evans v. Evans', 'https://www.courtlistener.com/opinion/2205836/', '2205836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand with instructions.', 'general', 'Evans v. Evans', 'https://www.courtlistener.com/opinion/2205836/', '2205836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the courts below erred in rejecting petitioner’s application for relief because of his failure to specify the points he would raise were his right to appeal reinstated.', 'general', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ill Because there is nothing of record to establish that defendant’s trial counsel ever reviewed the plea proceedings for error before deciding not to pursue an appeal, and because it is contrary to the holdings oí Flores-Ortega and Rodriquez under these circumstances to require defendant, who is proceeding pro se, to provide grounds for withdrawing his guilty plea and his appeal, we hold that the circuit court erred in dismissing defendant’s petition at the first stage of the post-conviction...', 'dismissal', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Moore, this court held that the prejudice prong of the test for ineffective assistance of counsel (see Strickland v.', 'ineffective_assistance', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgments of the circuit and appellate courts.', 'general', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At the conclusion of its opinion, however, the appellate court stated: “We affirm the trial court’s dismissal of defendant’s postconviction petition.', 'dismissal', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, “Under the Post-Conviction Hearing Act, the [defendant] must set forth the specific manner in which his rights were violated.', 'general', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '] At the conclusion of its opinion, however, the appellate court stated: ‘We affirm the trial court’s dismissal of defendant’s postconviction petition.', 'dismissal', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Rule 604(d) serves as a condition precedent for an appeal from a defendant’s guilty plea.', 'plea', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 493, we held that the Vermont Constitution requires a mental health patient, who had been conditionally discharged from the state mental institution and placed in the community, to be given a hearing before that discharge is revoked.', 'general', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the liberty interests involved in G.', 'general', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1132, 1133 (1992), in which we held that an inmate who requested counsel on a habeas petition was wrongfully denied it on the grounds that the defender general’s office was unable to handle the case.', 'habeas', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence of Hammer''s past sexual conduct is admissible under the three-step test set forth in State v.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the circuit court''s admission of Hammer''s prior sexual conduct, while excluding the victims'' prior sexual conduct, did not violate Hammer''s right to a fair trial.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence of the defendant''s prior sexual assault was admissible under the three-step analytical framework set forth in Sullivan, 216 Wis.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the other acts evidence was not too remote, and certainly is balanced by the similarity between the two events.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the Jason B.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the rape shield statute did not deprive the defendant of his rights to confrontation and compulsory process, because he failed to satisfy all of the Pulizzano criteria.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that "in sexual assault cases, especially those involving assaults against children, the greater latitude rule applies to the entire analysis of whether evidence of a defendant''s other crimes was properly admitted at trial.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence of Hammer''s other sexual conduct is admissible under the three-step test set *716forth in State v.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the circuit court.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the prior threat was admissible other acts evidence under Wis.', 'general', 'State v. Hammer', 'https://www.courtlistener.com/opinion/2221488/', '2221488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the public interest side, we conclude that permitting law enforcement officers to request identifying information from passengers in traffic stops serves the public interest in several ways that are reasonably related to the purpose of a traffic stop.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, on the public side of the balance, we conclude that asking the rear passenger for identification furthered several legitimate public interests and was reasonably related to the purpose of the stop.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Weighing the public interest served by permitting police to request identifying information from passengers against the incremental intrusion upon *73individual privacy interests, we conclude that the public interests are substantial and the interference with private liberty interests is de minimis.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In adherence to the law, we conclude that the incremental intrusion that resulted from the questioning did not transform the lawful, reasonable seizure into an unlawful, unreasonable one.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, on the private side of the equation, we find that the additional interference with the passenger''s personal liberty that resulted from the identification questions was minimal.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the court of appeals.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the identification questions did not transform the reasonable search into an unreasonable one under the circumstances of this case.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the issues presented in the instant controversy are ripe for review.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although legislative limits upon certain types of damages may be permitted, such as damages recoverable in statutory causes of action, we hold that the cap in section 2 — 1115.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the compensatory damages cap of section 2 — 1115.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that section 2 — 1117(b) cannot be severed from section 2 — 1117(a) and that the entirety of section 2 — 1117 is unconstitutional.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For similar reasons, we hold that section 2 — 1003(a) conflicts with Supreme Court Rule 201(c)(1), which governs the issuance of protective orders.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that section 2 — 1003(a) is invalid as violating the separation of powers clause of the Illinois Constitution.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we hold that Public Act 89 — 7 is void in its entirety.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 329, we held that the presumption of severability reflected by an express severability clause will be overcome and the entire statute held unconstitutional if the legislature would not have passed the statute without the provision deemed invalid.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In holding that this provision was severablefrom the remainder of the ordinance, we held that the ordinance still served the legislature’s intent of ensuring that new developments pay their fair share of road improvements.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we concluded that these things did not affect his understanding of the proceedings or his ability to participate in his own defense.', 'general', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “no bona fide doubt as to petitioner’s fitness would have existed at the time he pleaded guilty, even if the trial court had been aware of the facts now available.', 'plea', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court’s dismissal of the petition without a hearing.', 'dismissal', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 348 (2002), we affirmed the dismissal of postconviction petition without evidentiary hearing where the petitioner claimed both that the trial court had actual doubts as to his fitness and failed to hold a fitness hearing and that certain facts existed that would have raised a bona fide doubt of his fitness had the trial court been aware of them at the time it accepted his guilty plea.', 'dismissal', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that Holdmann had “waived the issue by not presenting it to the Board.', 'general', 'In Re Artis', 'https://www.courtlistener.com/opinion/2258485/', '2258485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that “to whom the exposure is directed is not an essential element of the offense of indecent exposure.', 'general', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that indecency with a child by sexual contact was a lesser-included offense of aggravated sexual assault of a child even though the indecency offense contained what might appear to be an extra element — intent to arouse or gratify sexual desire.', 'general', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '49 Employing an Ervin analysis in Bigon, we held that felony murder, intoxication manslaughter, and manslaughter (all involving the same victim) were the “same” for Double Jeopardy purposes.', 'general', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that indecent exposure was a lesser-included offense of indecency with a child by exposure for the purpose of determining whether a defendant was entitled to a lesser-included-offense jury instruction.', 'jury_instruction', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant was entitled to present the evidence and to have it considered and thus are compelled to reverse and remand for resentencing.', 'sentencing', 'State v. Randolph', 'https://www.courtlistener.com/opinion/2297077/', '2297077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the language of the Appellate Division’s remand order leaves room for ambiguity and that resolution of this dispute turns on a close examination of the exchanges during argument between the appellate panel and counsel.', 'general', 'State v. Randolph', 'https://www.courtlistener.com/opinion/2297077/', '2297077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Rose, supra, we held that a defendant is not entitled to a presumption against the death penalty charge.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we find that the evidence, viewed in the light most favorable to the State, would rationally support the conclusion that [the defendant] is guilty beyond a reasonable doubt of the crime of aggravated assault.', 'general', 'State v. Pabon', 'https://www.courtlistener.com/opinion/2326373/', '2326373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the 2001 amendments to the DWI statute, we conclude that the answer is no.', 'general', 'Getts v. State', 'https://www.courtlistener.com/opinion/2334456/', '2334456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Court of Appeals.', 'general', 'Getts v. State', 'https://www.courtlistener.com/opinion/2334456/', '2334456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing the mother’s conviction, we held that there was no statutory or common law duty in Kentucky requiring the mother “to prevent the commission of the rape,” Knox, supra, at 711;', 'general', 'Tharp v. Commonwealth', 'https://www.courtlistener.com/opinion/2337351/', '2337351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In affirming the mother’s conviction, we held that Kentucky law imposes a legal duty upon a parent to make a proper effort to protect his/her child from harm at the hands of another, thus trig*362gering the “legal duty” aspects of KRS 502.', 'general', 'Tharp v. Commonwealth', 'https://www.courtlistener.com/opinion/2337351/', '2337351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the case sub judice, we conclude that at the time Appellant committed the offense of wanton murder by complicity, she had “fair warning” that her failure to make a proper effort to protect her child from her husband’s assaults violated her “legal duty” to do so, as required by KRS 502.', 'general', 'Tharp v. Commonwealth', 'https://www.courtlistener.com/opinion/2337351/', '2337351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 505 (1980), where we held that an at-will employee, wrongfully discharged in violation of “a clear mandate of public policy,” has a common law cause of action against an employer.', 'general', 'D''Annunzio v. Prudential Insurance Co. of America', 'https://www.courtlistener.com/opinion/2353083/', '2353083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 196 (1996), this court held that where a record was vague as to which subsection a defendant was convicted of violating, there was no error committed because the subsections were merely different ways of proving a single violation.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2359065/', '2359065') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellant’s conviction for disorderly conduct.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2359065/', '2359065') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '54 Similarly, we held that when the Council enacted a statute requiring employers to provide reasonably safe working conditions for wage earners, the common law defense of contributory negligence could not be used to bar recovery for an injury caused by the employer’s failure to comply with the statute and related regulations.', 'general', 'Carl v. Children''s Hospital', 'https://www.courtlistener.com/opinion/2395626/', '2395626') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the contrary, this court held not long ago in Adams v.', 'general', 'Carl v. Children''s Hospital', 'https://www.courtlistener.com/opinion/2395626/', '2395626') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that truthful testimony at congressional hearings is “an act consistent with a clear and compelling public policy” that justifies a public policy exception to the at-will employment doctrine.', 'general', 'Carl v. Children''s Hospital', 'https://www.courtlistener.com/opinion/2395626/', '2395626') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today the majority states that “In Gray, we held that ‘only the en banc court may undertake the extension that appellant urges on us.', 'general', 'Carl v. Children''s Hospital', 'https://www.courtlistener.com/opinion/2395626/', '2395626') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the “engage in conduct” language of the injury to a child statute was, in fact, “vestigial” language and that the statute’s actual focus was on the result of a defendant’s conduct.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the charge, read as a whole limited the defendant''s culpable mental state to the "result of conduct.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that the correct analysis is that the inclusion of the “engage in conduct” language in the definitional portion of a jury charge is in fact error where the offense charged is a result offense.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it was not error to submit the penal code definition of intentional due to the wording of the indictment and the Wording of the application portion of the charge, which tracked the language of the indictment.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed and remanded for a harm analysis under Almanza v.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new sentencing hearing.', 'sentencing', 'Vasquez v. State', 'https://www.courtlistener.com/opinion/2398120/', '2398120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Otte v. State', 'https://www.courtlistener.com/opinion/2436043/', '2436043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no error in the trial court''s Criminal Rule 4(D) continuance or its admission of Creekbaum''s testimony, we affirm the trial court on both grounds.', 'general', 'Otte v. State', 'https://www.courtlistener.com/opinion/2436043/', '2436043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the protective measures were warranted.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2430181/', '2430181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, for example, the handcuffs were used because the defendant was charged with escape from the penitentiary, and we affirmed their use.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2430181/', '2430181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE the judgments of the court of appeals and AFFIRM the judgments of the trial court.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/2433594/', '2433594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and remand.', 'general', 'Bocanegra v. State', 'https://www.courtlistener.com/opinion/2438242/', '2438242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the jury could have reasonably inferred Bocanegra’s misrepresentations subjected his employer to potential injury, we affirm his conviction of forgery and remand for vacation of the identity deception conviction.', 'general', 'Bocanegra v. State', 'https://www.courtlistener.com/opinion/2438242/', '2438242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold potential injury remains a sufficient basis for a finding of criminal intent in a forgery prosecution.', 'general', 'Bocanegra v. State', 'https://www.courtlistener.com/opinion/2438242/', '2438242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and dismiss the convictions.', 'dismissal', 'Williams v. State', 'https://www.courtlistener.com/opinion/2441143/', '2441143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the Foster case, where we reversed and dismissed a first-degree murder conviction, the State argued in its petition for rehearing that the case should have been remanded for a new trial.', 'dismissal', 'Williams v. State', 'https://www.courtlistener.com/opinion/2441143/', '2441143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed that conviction.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/2441143/', '2441143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A plurality of this Court held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that appellee cannot benefit from the lesser included offense instruction and then attack his conviction of that lesser included offense on limitations grounds.', 'general', 'State v. Yount', 'https://www.courtlistener.com/opinion/2450499/', '2450499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that, following the 1985 amendments to Article V, § 12 of the Texas Constitution and Article 1.', 'general', 'State v. Yount', 'https://www.courtlistener.com/opinion/2450499/', '2450499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1973), we reversed a conviction on the.', 'general', 'State v. Yount', 'https://www.courtlistener.com/opinion/2450499/', '2450499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was erroneously admitted.', 'general', 'State v. McCary', 'https://www.courtlistener.com/opinion/2462824/', '2462824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that prior intoxication-related convictions serve the purpose of enhancing the offense in Section 49.', 'general', 'Gibson v. State', 'https://www.courtlistener.com/opinion/2463936/', '2463936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Section 49.', 'general', 'Gibson v. State', 'https://www.courtlistener.com/opinion/2463936/', '2463936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Doe 08 we held that the application of ASORA''s registration requirements to an offender who was convicted of sex offenses and sentenced nine years before ASORA''s effective date violated the ex post facto clause of article I, section 15 of the Alaska Constitution.', 'sentencing', 'John Doe v. Department of Public Safety', 'https://www.courtlistener.com/opinion/6658977/', '6658977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting "[t]he stigma which attaches to a discharge for incompetence," we held that constitutional due process requirements necessitated a hearing, even though non-tenured teachers were not entitled to one by statute.', 'general', 'John Doe v. Department of Public Safety', 'https://www.courtlistener.com/opinion/6658977/', '6658977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case we held that a competitor was entitled to judicial review of a tax exemption decision made by the Commissioner of Economic Development even though the applicable statute provided that the Commissioner''s decision was final and not subject to judicial review:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that ASORA''s registration requirements can constitutionally be applied to out-of-state offenders.', 'general', 'John Doe v. Department of Public Safety', 'https://www.courtlistener.com/opinion/6658977/', '6658977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*123While some of the State''s arguments are plausible, we find it unnecessary to rule on them because we conclude that the first premise of Doe''s argument is invalid.', 'general', 'John Doe v. Department of Public Safety', 'https://www.courtlistener.com/opinion/6658977/', '6658977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Alaska is not barred by lack of jurisdiction from requiring out-of-state offenders who are present in the state from registering under ASORA.', 'general', 'John Doe v. Department of Public Safety', 'https://www.courtlistener.com/opinion/6658977/', '6658977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we conclude that a sex offender may hold a legitimate and objectively reasonable privacy expectation that his conviction and personal information will not be disseminated as it is under ASORA.', 'general', 'John Doe v. Department of Public Safety', 'https://www.courtlistener.com/opinion/6658977/', '6658977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that Doe has the better of the argument.', 'general', 'John Doe v. Department of Public Safety', 'https://www.courtlistener.com/opinion/6658977/', '6658977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Doe 08 we found it unnecessary to address the first step of the intent-effects test because, regardless of the legislature''s intent, we found that the effects of ASORA were primarily punitive and therefore concluded that ASORA could not be applied to offenders who committed their crimes before the law''s effective date.', 'general', 'John Doe v. Department of Public Safety', 'https://www.courtlistener.com/opinion/6658977/', '6658977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we find that Jury Instruction S-2 did create a mandatory presumption.', 'jury_instruction', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the circuit court erred in denying Durham’s motion for a new trial.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Durham appeals his conviction, and finding error, we reverse the circuit court’s judgment and remand for a new trial.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we find error in the circuit court’s denial of Durham’s motion for a new trial, and we reverse the court’s judgment and remand this case for further proceedings consistent with this opinion.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the circuit court and remand for a new trial in accordance with this opinion.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that there is an actionable public policy tort in Alaska for retaliation against witnesses in legal proceedings.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that AS 09.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Anderson (Anderson I) we held that a wrongfully discharged employee’s “lost earnings should be measured by the amount and duration of the contract that [he or] she expected to have with [the employer],” which *818in that case was one year.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that APC did not adequately preserve the issue it argues on appeal and that there was no reversible error.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '33 To the extent APC objected to giving a mixed-motive instruction instead of a pretext instruction, we conclude that no error occurred.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the extent APC objected to the incompleteness of the mixed-motive instruction, we conclude that APC did not distinctly raise this issue at trial.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '43 As a result, we conclude that it was not an abuse of discretion to exclude Bailey’s testimony that Reust’s position had been eliminated.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that AS 09.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”7 We concluded that the State of Alaska has explicit public policies that protect employees who make workers’ compensation claims and who serve as whistleblow-ers.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State we concluded that because interests in “unlimited [punitive] damages are merely economic, the State’s objectives need only be ‘legitimate’— not ‘compelling’ — to justify the State’s action.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2000), this Court held that an officer’s request to search a car was lawful where the request was made before the issuance of the traffic citation had been completed and such request lengthened the process only by a second or two.', 'general', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d at 306-07, this Court held that it was permissible for one officer to question a vehicle’s driver about drugs and weapons and to take a drug dog around the car while another officer was busy checking with dispatch on the driver’s status and writing out a traffic citation.', 'general', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of all these facts, we conclude that the use of the drug dog impermissibly extended the duration of the detention authorized by Terry.', 'general', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the probable cause to search the interior of Aguirre’s pickup truck, which was secured by the drug detection dog’s alert on the exterior of the vehicle, was itself acquired through an unconstitutional expansion of the traffic stop.', 'probable_cause', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the district court granting Aguirre’s motion to suppress.', 'suppression', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'People v. Bartelt', 'https://www.courtlistener.com/opinion/2531060/', '2531060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court, reverse the judgment of the circuit court, and remand to the circuit court for further proceedings consistent with this opinion.', 'general', 'People v. Bartelt', 'https://www.courtlistener.com/opinion/2531060/', '2531060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this court has jurisdiction to address the merits of the prosecution’s appeal, inasmuch as the prosecution filed its notice of appeal within thirty days of the effective dates of both the written order granting Bohannon’s motions to suppress and to dismiss and the written order denying the prosecution’s motion for reconsideration, which was therefore timely pursuant to Hawai''i Rules of Appellate Procedure (HRAP) Rule 4(b) (1999).', 'suppression', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being the ease, we hold that the prosecution’s notice of appeal “is sufficient in form,” id.', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the same rule of strict construction applies to the Rule 4(b) HRAP requirement that the State must file its notice of appeal within 30 days of the entry of the judgment or order appealed from.', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 Accordingly, we hold that, in order to appeal a criminal matter in the district court, the appealing party must appeal from a written judgment or order that has been filed with the clerk of the court pursuant to HRAP Rule 4(b)(3).', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, viewing the present matter from the totality of the circumstances known to Officer Kashimoto at the time of the incident, we hold that his investigative stop of Bohannon was “within the parameters of permissible police conduct,” Barnes, 58 Haw.', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this evidence constitutes a knowing and willful course of conduct that qualifies as harassment under section 97-3-107(4).', 'general', 'McCALPIN v. State', 'https://www.courtlistener.com/opinion/2549155/', '2549155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2009), where we held that the trial court erred when it precluded cross-examination of a police detective about information the defense had received indicating that the detective "had been relieved of his powers as a police officer and [was] under investigation for a number of matters.', 'general', 'Jordan v. United States', 'https://www.courtlistener.com/opinion/2558215/', '2558215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '19 In both cases, we reversed the convictions because the trial court had erred in failing to clear up jury confusion about the meaning of terms in the governing law.', 'general', 'Jordan v. United States', 'https://www.courtlistener.com/opinion/2558215/', '2558215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 None of these arguments has merit and thus we affirm appellant’s convictions, subject to remand for amendment of the judgment and commitment order to account for merged offenses.', 'general', 'Jordan v. United States', 'https://www.courtlistener.com/opinion/2558215/', '2558215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons we affirm appellant’s convictions, remanding for amendment of the judgment and commitment order to account for merged offenses.', 'general', 'Jordan v. United States', 'https://www.courtlistener.com/opinion/2558215/', '2558215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a conviction under Ha-wai''i Revised Statutes (HRS) § 707-734 .', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As previously indicated, the prosecution contends that Rocker supports Defendant’s conviction because, in Rocker, this court held that the defendants’ nude sunbathing at a public beach supported their convictions of indecent exposure under HRS § 727-1 (1968).', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court applied the wrong legal standard in convicting Defendant under HRS § 707-734 and, further, as measured against the correct legal standard, there was insufficient evidence to establish his guilt.', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the evidence was not of “sufficient quality and probative value to enable [a person] of reasonable caution to support [the] conclusion” that Defendant acted intentionally under circumstances likely to cause affront.', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Defendant’s conviction because the court applied the wrong legal standard and because the evidence was insufficient to establish guilt under the legal standard that should have been applied.', 'general', 'State v. Kalama', 'https://www.courtlistener.com/opinion/2569557/', '2569557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed infra in section III, we hold that the language set forth in HRS § 291E-61(c), see infra note 10, manifests a clear- legislative intent to create a status offense in HRS § 291E-61 and, therefore, that it was not a violation of Ruggiero’s due process rights, guaranteed by section 1 of the fourteenth amendment to the United States Constitution1 and article I, section 5 of the Hawai''i Constitution2 to sentence him as a second-time offender on the basis of a prior convic...', 'sentencing', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Ruggiero failed to preserve the constitutional arguments for appeal and, therefore, we may only reach the merits of his arguments by noticing plain error on the district court’s part.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a fact susceptible to jury determination is a predicate to the imposition of an enhanced sentence, the Hawaii Constitution requires that such factual determinations be made by the trier of fact.', 'sentencing', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 (“In Lobendahn we held that, inasmuch as the statute created a ‘status offense,’ the subsequent invalidation of the predicate felony conviction did not affect the validity of the criminal possession charge because the defendant was ‘a convicted felon at the time he possessed the firearm and ammunition.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nine days later, on March 19, 2004, we reversed the January 29, 2003 conviction on the grounds that the prosecution failed to’ prove an essential element of the offense.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s judgment with respect to Ruggiero’s convictions of the infractions alleged in Counts II, III, and IV of the complaint, none of which Ruggiero appealed, see infra note 3.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s judgment in all other respects.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as Ruggiero does not appeal his conviction of and sentence for driving without no-fault insurance, in violation of HRS § 431:10C-104(a) (Count II), driving a motor vehicle with delinquent tax, in violation of HRS § 249-11 (Count III), and failure to signal, in violation of HRS § 291C-84(b) (Count IV), we affirm the district court’s judgment and sentence regarding those counts.', 'sentencing', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the 2003 amendments to HRS § 291E-61 transformed HRS § 291E-61 (b)(1) to (3) into status offenses.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In concluding the overbreadth discussion, the Court stated its holding as follows: “Accordingly, we hold that as applied to Hammers-ley, I.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that as applied to Hammersley, I.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 1285 (2000), we held that the adverbs “maliciously” and “willfully” modified the third verb “uses,” and they would therefore logically modify the first two verbs also.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hammersley’s conduct falls squarely within the specific intent requirement of I.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The dissent argues that because we affirm Poe’s conviction on an alternate ground, we did not need to address the overbreadth issue.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Poe has not alleged that the statute was unconstitutionally applied to his conduct or that he did not have fair notice that his conduct was proscribed, and because he has not shown any error by the trial court, we affirm the judgment of conviction.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 196 (1976) ]), we hold that the interior walkway to the main entrance to the Hospital is not historically nor traditionally associated with the exercise of free speech.', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that West engaged in dishonest conduct in violation of DR 1-102(A)(4).', 'general', 'In the Disciplinary Matter Involving West', 'https://www.courtlistener.com/opinion/2603669/', '2603669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that DR 1-102(A)(6), as applied to West, does not violate due process.', 'general', 'In the Disciplinary Matter Involving West', 'https://www.courtlistener.com/opinion/2603669/', '2603669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In the Disciplinary Matter Involving West', 'https://www.courtlistener.com/opinion/2603669/', '2603669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 We affirm the Board’s determination that disbarment or suspension are generally appropriate sanctions given the nature of West’s miscon*358duct,15 and specifically reject West’s assertion that Section 5.', 'general', 'In the Disciplinary Matter Involving West', 'https://www.courtlistener.com/opinion/2603669/', '2603669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As developed below, we hold that (1) the jury may have convicted Major solely for the possession which occurred on the reservation, and (2) the state lacked jurisdiction over this crime inside the reservation.', 'general', 'State v. Major', 'https://www.courtlistener.com/opinion/2616070/', '2616070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the tribal resolution did not grant consent over a class of offenses which included grand theft by possession of stolen property.', 'general', 'State v. Major', 'https://www.courtlistener.com/opinion/2616070/', '2616070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the above discussion indicates, neither do we conclude that the crime of grand theft by possession of stolen property found in I.', 'general', 'State v. Major', 'https://www.courtlistener.com/opinion/2616070/', '2616070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that 18 U.', 'general', 'State v. Major', 'https://www.courtlistener.com/opinion/2616070/', '2616070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s incarceration, and other factors, we conclude that the superior court did not err in finding that continued custody by T.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s incarceration would bring to these young children, we conclude that the superior court did not err in terminating T.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"23 We concluded that "because AA.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the particular facts of this case, we find that the totality of the cireumstances supports the superior court''s decision to terminate T.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the superior court''s termination of parental rights for both parents.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*109518 In A4, we affirmed the termination of a biological father''s parental rights.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s parental rights is squarely supported by the governing statute, we AFFIRM the termination of her rights.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that state law preempts Ordinance 1248 as it applies to a particular subset of registered sex offenders: adjudicated delinquent children whom the state places and supervises in state-created foster care families.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we hold that the state’s interest in fulfilling its statutory obligations to place and supervise delinquent children in state-created foster care families in a uniform manner overrides any city interest in regulating land uses.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*155We hold that Ordinance 1248, to the extent that it regulates the number of adjudicated delinquent children that may reside in a particular foster home, is a matter of statewide concern and is preempted.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we hold that Ordinance 1248, as it applies to adjudicated delinquent children in foster care homes, regulates a matter of statewide concern.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we hold that Ordinance 1248 is preempted because it regulates a matter of statewide concern: adjudicated delinquent children in state-created foster care families.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 953, 955 (1977), we held that the state had an overriding concern in the regulation of electricians because the electricians needed uniform access to markets throughout the state.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that a matter is of statewide concern, we must consider whether the Constitution or state statutes provide specific authorization to the locality to legislate in this area.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state’s interest in fulfilling its statutory mandates to protect adjudicated delinquent children in need of state supervision and appropriate treatment is sufficiently dominant to override a home-rule city’s interest in regulating the number of registered juvenile sex offenders who may live in one foster care family.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our statutes create such a need.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering this impact, we found that the local law constituted rent control and implicated the state statute.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that Mother’s conduct fell within the parameters of the justified parental discipline statute and that, as a matter of law, the evidence in this ease was insufficient to support a determination of guilt on the charge of abuse of a family or household member beyond a reasonable doubt.', 'general', 'State v. Matavale', 'https://www.courtlistener.com/opinion/2623891/', '2623891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon considering, inter alia, (1) the age and size of the complainant, (2) testimony that the force was excessive and caused the complainant to be unable to sit in her classes, and (3) the nature of the injuries, we held that the force used by the defendant was not reasonably related to protecting the complainant’s welfare.', 'general', 'State v. Matavale', 'https://www.courtlistener.com/opinion/2623891/', '2623891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Were that the case, even the use of mild force, which this court held as permissible under HRS § 703-309(1), see Stocker, 90 Hawai''i at 96, 976 P.', 'general', 'State v. Matavale', 'https://www.courtlistener.com/opinion/2623891/', '2623891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the father’s conviction, concluding that the pain inflicted upon the daughter by her father did not “come, in degree, anywhere near death, serious bodily injury, disfigurement, extreme mental distress or gross degradation.', 'general', 'State v. Matavale', 'https://www.courtlistener.com/opinion/2623891/', '2623891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the doctrine of mootness was applicable to the case on appeal because the controversy on appeal no longer affected the legal relations of the parties.', 'general', 'State v. Matavale', 'https://www.courtlistener.com/opinion/2623891/', '2623891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the maxim noscitur a sociis, a canon of statutory interpretation, we concluded that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we reversed the family court’s judgement of conviction.', 'general', 'State v. Matavale', 'https://www.courtlistener.com/opinion/2623891/', '2623891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that our indecent liberties statute is not unconstitutionally vague as applied to Mr.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Wyo.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶43] Similar to our conclusion in Pier-son, we hold that the jury instructions given by the district court left doubt as to the circumstances under which Giles could be found to have committed the crime of indecent liberties with a child.', 'jury_instruction', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, combined with the other facts noted above, we conclude that the jury’s verdict was supported by the evidence.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 6-2-304, and one was no more “specific” than the other, we concluded that Wyo.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, because the jury was not adequately instructed, we reverse and remand.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1303 (“Thus, we hold that in order to protect the right to testify under the Hawai''i Constitution, trial courts must advise criminal defendants of their right to testify and must obtain an on-the-record waiver of that right in every case in which the defendant does not testify.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/2625250/', '2625250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'State v. Murray', 'https://www.courtlistener.com/opinion/2625250/', '2625250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the substitution of the alternate juror after deliberations had begun constituted prejudicial error.', 'general', 'Alcalde v. State', 'https://www.courtlistener.com/opinion/2625308/', '2625308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Alcalde''s conviction and remand for a new trial.', 'general', 'Alcalde v. State', 'https://www.courtlistener.com/opinion/2625308/', '2625308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of an express statement to the contrary, we hold that the motion for reconsideration is not a tolling motion.', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1009 (1986), this court held that a motion to reconsider filed by the prosecution under HRPP Rule 47 following the granting of a motion to suppress does not toll the time for appeal of the suppression order.', 'suppression', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the circuit court plainly erred in its jury instructions regarding the charge of first degree robbery and, accordingly, we vacate Cordei-ro’s conviction of and sentence for first degree robbery and remand for further proceedings consistent with this opinion.', 'sentencing', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the failure of count 4 of the Blaisdell indictment either to *407name the person against whom Cordeiro allegedly used force or the victim of the theft did not render the charge fatally defective in this case.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Correlatively, “inasmuch as we cannot say that there was no reasonable possibility that the circuit court’s error contributed to [Cor-deiro’s] conviction[ ], we hold that the error was not harmless beyond a reasonable doubt[.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ']” Inasmuch as HRS § 708—840(l)(b)(i) does not require that a defendant use force in order to compel another person to acquiesce in his or her taking of property, we hold that it is not an element (i.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not err in failing to instruct the jury that the “victim” of the theft—whether the person against whom force is used or the owner of the property taken—must be aware of the theft.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” For the reasons discussed infra we hold that the circuit court did not err in granting the prosecution’s motions for consolidation.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that circuit court did not plainly err in determining that the public interest in judicial economy outweighed any potential prejudice to Cordeiro and, accordingly, in granting the prosecution’s motions for consolidation of the attempted first degree murder charges with the charges in the Blaisdell case.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '25 Accordingly, we hold that the cir*420cuit court did not err in striking Hill from the witness list.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, “assuming that the damr aging potential of the cross-examination were fully realized,” we hold that there is no reasonable possibility that it would have changed the outcome of Cordeiro’s trial.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the circuit court did not abuse its discretion in limiting the scope of Cordeiro’s defense counsel’s cross-examination, insofar as the circuit court merely excluded irrelevant and repetitious questions by defense counsel and the exclusions did not result in any “manifest prejudice” to Cordei-ro.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a defendant may not invoke tactical considerations to deprive the jury of the opportunity to consider whether the defendant is guilty of a lesser offense included within the crime charged.', 'general', 'State v. Haanio', 'https://www.courtlistener.com/opinion/2631226/', '2631226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2002), this Court held that section 18-205 does not require actual knowledge when prosecuting under subsection (2) of the statute, which pertains to harboring and protecting a person who has committed or been charged with a felony.', 'general', 'State v. Hauser', 'https://www.courtlistener.com/opinion/2632440/', '2632440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the State presented substantial and competent evidence by which a reasonable jury could find that Hauser was guilty as an accessory after the fact.', 'general', 'State v. Hauser', 'https://www.courtlistener.com/opinion/2632440/', '2632440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the district court erred in failing to excuse an admittedly biased juror who did not give an unequivocal assurance of impartiality, Hauser is entitled to a new trial.', 'general', 'State v. Hauser', 'https://www.courtlistener.com/opinion/2632440/', '2632440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the district court erred in failing to excuse Juror 31 for cause.', 'general', 'State v. Hauser', 'https://www.courtlistener.com/opinion/2632440/', '2632440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The prosecution concluded that if this court holds “that the trier of fact is constitutionally required to make the ‘necessary for the protection of the public’ finding[,]” we should also hold that the court “has the inherent power to empanel a jury to make that determination as part of a sentencing proceeding on remand where a defendant’s sentence has been vacated due to an Apprendi procedural error.', 'sentencing', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similar to the prosecution, the dissent noted that (1) in lanto this court held that the trier of fact, i.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wilson, this court held that the defendant, after being arrested for driving under the influence of intoxicating liquor, was not accurately informed of the consequences of taking a blood alcohol concentration (BAC) test because the officer informed the defendant that his driving privileges would be revoked for three months if he took the test and failed when in fact he would be subject to revocation of three months to one year if he failed the test.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an appellate court will reverse for plain error in jury instructions where the error cannot be said to be harmless beyond a reasonable doubt (i.', 'jury_instruction', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that standard to the instant case, we hold that the circuit court’s failure to instruct the jury that “it could consider relevant attributes of both the defendant and the subject of the allegedly threatening utterance in determining whether the subject’s fear of bodily injury, as allegedly induced by the defendant’s threatening utterance, was objectively reasonable under the circumstances in which the threat was uttered,” Valdivia, 95 Hawaii at 479, 24 P.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that, although as a general matter forfeited assignments of error are to be reviewed under the HRPP Rule 52(b) plain error standard of review, in the case of erroneous jury instructions, that standard of review is effectively merged with the HRPP Rule 52(a) harmless error standard of review because it is the duty of the trial court to properly instruct the jury.', 'jury_instruction', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we hold that: (1) the circuit court’s failure to give a “relevant attributes” instruction was plain error;', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A, we hold that: (1) the failure to give a relevant attributes instruction was erroneous, and (2) there is a reasonable possibility that the error contributed to Nichols’ conviction, ie.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the circuit court’s failure to provide a “relevant attributes” instruction was not harmless beyond a reasonable doubt.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 Accordingly, we hold that *342the circuit court on remand is not required to give a nexus instruction.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 Accordingly, unless Nichols presents evidence at a future trial that would allow some other rational inference to be drawn, we hold that the trial court is not required to instruct the jury on the lesser included offense of terroristic threatening in the second degree.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Haanio, we held that "the trial courts, not the parties, have the duty and ultimate responsi*336bility to insure that juries are properly instructed on issues of criminal liability.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Haa-nio, this court held that a trial court is obligated to give a lesser included offense instruction when there is a rational basis for it in the evidence, even if, as in this case, no request or objection is made by the parties.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that, although as a general matter forfeited assignments of error are to be reviewed under the HRPP 52(b) plain error standard of review, in the case of erroneous jury instructions, that standard of review is effectively merged with the HRPP 52(a) harmless error standard of review because it is the duty of the trial court to properly instruct the jury.', 'jury_instruction', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an attorney has a duty of candor to the courts, yet encourage gamesmanship and subterfuge to achieve the best possible result.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', the same must be said of the immediately preceding sentence, "we hold that, although as a general matter forfeited assignments of error are to be reviewed under the HRPP 52(b) plain error standard of review, in the case of erroneous jury instructions that standard of review is effectively merged with the HRPP 52(a) harmless error standard of review because it is the duty of the trial court properly to instruct the jwy.', 'sentencing', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2, supra, we hold that, given (1) the destructive, deceitful, and wasteful, albeit nonviolent, character of Ka-hapea’s offenses and (2) the primacy of the retributive, incapacitative, and deterrent objectives, five consecutive ten-year terms of imprisonment does not reflect a plain and manifest abuse of discretion on the part of the circuit court.', 'general', 'State v. Kahapea', 'https://www.courtlistener.com/opinion/2633655/', '2633655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, in which we held that the statutory caps on noneconomic and punitive damages did not amount to a remittitur that violated the separation of powers doctrine.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse in part and remand because we conclude that Instruction No.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But because her only viable claim is not based on the truth or falsity of Leyk-is''s words about Carpenter and is not based on harm to her reputational interest, we conclude that the heightened protections due speech about public figures and matters of public concern do not altogether foreclose Carpenter''s TIED claims.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in denying admission of the entire compendium.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"123 Because Anderson II squarely resolved the issue, we conclude that the superior court did not err by deducting a pro rata share of Carpenter''s contingent fee from the state''s portion of Carpenter''s punitive damages award.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" 120 We concluded that a later amendment that changed the word "after" to "before" "was meant to require the state to pay its share of a plaintiff''s attorney''s contingent fee.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we AFFIRM the grant of summary judgment dismissing Carpenter''s defamation and false light invasion of privacy claims.', 'dismissal', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM the denial of Leykis''s motion for a directed verdict on Carpenter''s spoliation claim.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Instruction No.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/2637112/', '2637112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that neither Chapter 706 nor Chapter 353 of ■ the Hawaii Revised Statutes (HRS) prohibit the HPA from setting a prisoner’s minimum term at a period equal to his or her maximum sentence.', 'sentencing', 'Williamson v. Hawai''i Paroling Authority', 'https://www.courtlistener.com/opinion/2637982/', '2637982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the relevant statutes, we hold that them plain language does not prohibit the HPA from establishing a prisoner’s minimum term at a period equal to his or her maximum sentence and that nothing in the legislative history supports such a restriction.', 'sentencing', 'Williamson v. Hawai''i Paroling Authority', 'https://www.courtlistener.com/opinion/2637982/', '2637982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that a prisoner does not have a statutory right to have his or her minimum term set at a period shorter than the maximum sentence.', 'sentencing', 'Williamson v. Hawai''i Paroling Authority', 'https://www.courtlistener.com/opinion/2637982/', '2637982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the ICA’s opinion.', 'general', 'Williamson v. Hawai''i Paroling Authority', 'https://www.courtlistener.com/opinion/2637982/', '2637982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury instructions were prejudicially misleading, prejudicially confusing, and likely contributed to the reckless manslaughter conviction.', 'jury_instruction', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the jury instructions were inconsistent and misleading.', 'jury_instruction', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court committed plain error and Culkin’s conviction must be set aside.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court erred by ruling that Thomas’s past use of the handgun was not relevant.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the forgoing reasons, we affirm Cul-kin’s conviction of reckless endangering in the second degree, vacate Culkin’s conviction of reckless manslaughter, and remand this matter to the circuit court for a new trial.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998) (“Today we hold that juror interrogation is no longer to be left to the discretion of the trial court, but rather is a practice that is condemned and outright forbidden by this court.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 901, 902 (1998) (“We hold that allowing juror-inspired questions in a criminal case is not prejudicial per se, but is a matter committed to the sound discretion of the trial court.', 'general', 'State v. Culkin', 'https://www.courtlistener.com/opinion/2637986/', '2637986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 112, a non-capital murder case, we held that a trial court may ignore a defendant’s lack of criminal history and impose an aggravated sentence.', 'sentencing', 'State v. Pena', 'https://www.courtlistener.com/opinion/2640047/', '2640047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On these facts, we find that standard was satisfied.', 'general', 'Joanna S. Robinson v. State of Indiana', 'https://www.courtlistener.com/opinion/2658881/', '2658881') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both trial courts and decline appel*364lants’ invitation to invade the fact-finder’s province.', 'general', 'Joanna S. Robinson v. State of Indiana', 'https://www.courtlistener.com/opinion/2658881/', '2658881') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the State was required to submit proof of “endangerment” that went beyond mere intoxication in order for the defendant to be convicted of operating while intoxicated, as a Class A misdemeanor.', 'general', 'Tin Thang v. State of Indiana', 'https://www.courtlistener.com/opinion/2681843/', '2681843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant was properly charged with three violations of the statute because “[b]y its plain language, the statute defines an act of kidnapping by reference to the victim.', 'general', 'In re Williams', 'https://www.courtlistener.com/opinion/2682676/', '2682676') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that when the statute did not explicitly address whether an operator is guilty of multiple offenses when multiple injuries occur, the decisive question was “whether the actus reus prohibited by the statute is the act of driving negligently, which defendant committed only once, or the act of causing serious injury, which defendant committed twice.', 'general', 'In re Williams', 'https://www.courtlistener.com/opinion/2682676/', '2682676') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the statute defined the crime of grossly negligent operation solely by reference to the standard of care of the driver, we held that it was plain error for defendant to be charged and convicted with two violations of the statute.', 'general', 'In re Williams', 'https://www.courtlistener.com/opinion/2682676/', '2682676') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in Martin, we held that the defendant could not be convicted of two counts of'' boating while intoxicated arising from a single accident resulting in two deaths because the act prohibited by the statute was defined solely by the operation of a vessel while intoxicated and not by the consequences.', 'general', 'In re Williams', 'https://www.courtlistener.com/opinion/2682676/', '2682676') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that the PCR court’s finding that petitioner did not receive adequate assistance of counsel is supported by the evidence.', 'general', 'In re Williams', 'https://www.courtlistener.com/opinion/2682676/', '2682676') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court’s decision that petitioner failed to demonstrate ineffective assistance of counsel prior to his guilty plea.', 'plea', 'In re Williams', 'https://www.courtlistener.com/opinion/2682676/', '2682676') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'T 68 In Canton we concluded that "[dlietio-naries [welre .', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of these search results, we concluded that "although Canton''s construction" of the Utah tolling provision was "semantically plausible based on dictionary definitions of ''out of and ''the state,'' it cannot be reconciled with the uniform understanding of the extended statutory phrase ''out of the state''" Id.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It comes into play only if we find that the legislature is not using words in some spe-clalized sense, and only if we cannot reject one of the parties'' definitions based on the structure or context of the statute.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse for insufficiency "only when the evidence .', 'general', 'Salt Lake City v. Carrera', 'https://www.courtlistener.com/opinion/2827593/', '2827593') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, for example, we held that a petitioner was entitled to an evidentiary hearing based on an affidavit from a third party who allegedly had heard the prosecution’s key witness confess to the crime of which the petitioner *771had been convicted.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Caldwell has alleged facts that, if proven, would entitle him to relief, we reverse and remand to the postconviction court for an evidentiary hearing.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, therefore, because we conclude that Caldwell’s allegations, if proven, would be sufficient to satisfy the first prong of the Larrison standard, the postconviction court abused its discretion when it denied an evidentiary hearing to Caldwell based in part on its conclusion that the recantations from Brooks and Carnell were not credible.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the decision of the postconviction court and remand for an evidentiary hearing on Caldwell’s witness-recantation claim.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the consolidated appeal, we affirmed Caldwell’s conviction and the denial of both petitions for post-conviction relief.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the postconviction court’s decision because the witness’s selective recall at the hearing was a sufficient reason to doubt the credibility of the recantation.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “under these circumstances,” a court could be reasonably well satisfied that it was the trial testimony, not the subsequent statement, that was false.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such testimony did not constitute a recantation for purposes of the Larrison test.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we held that the conflict between his refreshed memory and his trial testimony did not constitute a recantation.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that it did not.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the conflicting testimony in Pippitt did not “indicate that [the witness’s] trial testimony was false for purposes of the Larrison test.', 'general', 'Lincoln Lamar Caldwell v. State of Minnesota', 'https://www.courtlistener.com/opinion/2736454/', '2736454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rarely do we hold that it has been abused.', 'general', 'State of Minnesota v. Jose Arriage Soto, Jr.', 'https://www.courtlistener.com/opinion/2744712/', '2744712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, however, we conclude that Soto’s record provides very little, if any, support for the conclusion that he was particularly amenable to probation.', 'general', 'State of Minnesota v. Jose Arriage Soto, Jr.', 'https://www.courtlistener.com/opinion/2744712/', '2744712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that on this record Soto’s bargained-for guilty plea, by itself, provides no support for concluding that he was particularly amenable to probation.', 'plea', 'State of Minnesota v. Jose Arriage Soto, Jr.', 'https://www.courtlistener.com/opinion/2744712/', '2744712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying those principles to the current record in this case, we conclude that the district court abused its discretion in this case of first-degree criminal sexual conduct.', 'general', 'State of Minnesota v. Jose Arriage Soto, Jr.', 'https://www.courtlistener.com/opinion/2744712/', '2744712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that on the current record, the district court’s decision to depart from the presumptive disposition under the Sentencing Guidelines and to stay Soto’s sentence was an abuse of discretion.', 'sentencing', 'State of Minnesota v. Jose Arriage Soto, Jr.', 'https://www.courtlistener.com/opinion/2744712/', '2744712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that this is the exceptional case in which the district court abused its discretion in departing from the Sentencing Guidelines.', 'sentencing', 'State of Minnesota v. Jose Arriage Soto, Jr.', 'https://www.courtlistener.com/opinion/2744712/', '2744712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In another case, in which we affirmed the district court’s decision to stay two presumably executed sentences, we mentioned the district court’s findings that one defendant played a passive role in the underlying crimes, did not seriously injure anyone, and was unlikely to reof-fend, and that the other defendant did not pose a threat to public safety.', 'sentencing', 'State of Minnesota v. Jose Arriage Soto, Jr.', 'https://www.courtlistener.com/opinion/2744712/', '2744712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While Louisell’s appeal was pending, we held that, as applied to one of the other thirty-seven LWOP sentences imposed on juvenile offenders, the Governor’s commutation elevated form over substance.', 'sentencing', 'State of Iowa v. Yvette Marie Louisell', 'https://www.courtlistener.com/opinion/2812178/', '2812178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court erred in finding that Juror Campbell should have been removed from the jury panel for cause.', 'general', 'SER Michael W. Parker, Prosecuting Attorney v. Hon. Thomas H. Keadle, Judge', 'https://www.courtlistener.com/opinion/2807038/', '2807038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the five-point test of Hoover, supra, we find that the State does not have a right to appeal the order granting Derek S.', 'general', 'SER Michael W. Parker, Prosecuting Attorney v. Hon. Thomas H. Keadle, Judge', 'https://www.courtlistener.com/opinion/2807038/', '2807038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'verdict, we conclude that any error did not affect Wenthe’s substantial rights.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the clergy sexual conduct statute does not require the clergy member to know that the complainant seeks or is receiving spiritual counsel.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the challenged decisions of the district court were either not error, did not affect Wenthe’s substantial rights, or were harmless beyond a reasonable doubt, we reverse the court of appeals and reinstate Wenthe’s conviction.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the district court did not err, we need not determine which standard of review applies.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we concluded that a person who carries a knife on school property is not guilty of felony possession of a dangerous weapon on school property unless he knows he possesses the knife.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004), we concluded that the crime of possession of a controlled substance in a school zone does not require the State to prove the defendant knew he was in a school zone.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statute merely requires knowledge of possession of a pistol, which also is not inherently criminal conduct.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that because a mens rea requirement already existed for the underlying offenses — drug possession and burglary — the additional circumstances did not warrant an additional knowledge requirement.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State appealed and we reversed, holding that the clergy sexual conduct statute does not violate the Establishment Clause, either facially or as applied in this case.', 'general', 'State of Minnesota v. Christopher Thomas Wenthe', 'https://www.courtlistener.com/opinion/2811252/', '2811252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the district court erred by imposing too stringent a standard on Ms.', 'general', 'State v. DeJesus', 'https://www.courtlistener.com/opinion/4385450/', '4385450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Dejesus’s circumstances, we conclude that the loss of the surveillance footage was sufficiently significant to warrant the dismissal of the State’s case against her.', 'dismissal', 'State v. DeJesus', 'https://www.courtlistener.com/opinion/4385450/', '4385450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred by imposing a higher burden at the threshold level than is required under Tiedemann, and that under the proper standard, Ms.', 'general', 'State v. DeJesus', 'https://www.courtlistener.com/opinion/4385450/', '4385450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 41 Applying the correct standard, we conclude that Ms.', 'general', 'State v. DeJesus', 'https://www.courtlistener.com/opinion/4385450/', '4385450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And upon our consideration of these factors, we conclude that dismissal was an appropriate remedy.', 'dismissal', 'State v. DeJesus', 'https://www.courtlistener.com/opinion/4385450/', '4385450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”17 We concluded that “[o]ur approach under rule 16 should govern the destruction of evidence.', 'general', 'State v. DeJesus', 'https://www.courtlistener.com/opinion/4385450/', '4385450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimate*117ly, we reverse the decision of the district court and remand for an entry of dismissal.', 'dismissal', 'State v. DeJesus', 'https://www.courtlistener.com/opinion/4385450/', '4385450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that the Board abuses its discretion in failing to consider whether to grant CPVs credit for time spent at liberty on parole under the plain language of Subsection 6138(a)(2.', 'general', 'Pittman v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/4386166/', '4386166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As an initial matter, we hold that Subsection 6138(a)(2.', 'general', 'Pittman v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/4386166/', '4386166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Board must articulate the basis for its decision to grant or deny a CPV credit for time served at liberty on parole.', 'general', 'Pittman v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/4386166/', '4386166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1), we hold that the Board must provide a contemporaneous statement explaining its reason for denying a CPV credit for time spent at liberty on parole.', 'general', 'Pittman v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/4386166/', '4386166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that because the Board’s *43decision to deny Kevin Pittman (“Appellant”) such credit was based upon its erroneous belief that Appellant was automatically precluded from receiving credit under Subsection 6138(a)(2.', 'general', 'Pittman v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/4386166/', '4386166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, contrary to the Board’s position, and the majority below, we conclude that the General Assembly did not intend to allow the Board’s decisions pursuant to Subsection 6138(a)(2.', 'general', 'Pittman v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/4386166/', '4386166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we find that the Board abused its discretion when it denied Appellant credit for time spent at liberty on parole based upon its incorrect belief that all CPVs automatically forfeit credit under Subsection 6138(a)(2.', 'general', 'Pittman v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/4386166/', '4386166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '24 We held that the victim’s testimony was affirmative evidence directly germane to whether the defendant lacked intent to threaten his girlfriend for her services as a prospective witness and that a jury rationally could infer from that evidence that he lacked that intent.', 'general', 'Goad, Joshua Lee', 'https://www.courtlistener.com/opinion/2944231/', '2944231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '28 We held that this was not affirmative evidence that the appellant “did not intend [the victim’s] death or know that it was reasonably certain to occur” at the time he killed the victim.', 'general', 'Goad, Joshua Lee', 'https://www.courtlistener.com/opinion/2944231/', '2944231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,22 we concluded that the defendant, charged with retaliation for services as a prospective witness, was entitled to a lesser-included-offense- instruction on assault.', 'general', 'Goad, Joshua Lee', 'https://www.courtlistener.com/opinion/2944231/', '2944231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that Mathis’s testimony was not evidence upon which a jury could rationally find that he possessed a less culpable mental state than that alleged in the indictment.', 'general', 'Goad, Joshua Lee', 'https://www.courtlistener.com/opinion/2944231/', '2944231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Importantly, we concluded that, “[a]part from appellant’s own testimony that he did not intend to kill anyone, there was no other evidence in support of such theory, and in fact the evidence refuted that testimony.', 'general', 'Goad, Joshua Lee', 'https://www.courtlistener.com/opinion/2944231/', '2944231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statute is invalid on its face because it is,unconstitutionally over-broad in violation of the First Amendment.', 'general', 'State v. Johnson, Terence', 'https://www.courtlistener.com/opinion/3007650/', '3007650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the Texas flag-destruction statute is facially invalid because it is unconstitutionally overbroad in violation of the First Amendment.', 'general', 'State v. Johnson, Terence', 'https://www.courtlistener.com/opinion/3007650/', '3007650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”124 We conclude that the Texas flag-destruction statute, by its text and in actual fact, prohibits a substantial amount of activity that is protected by the First Amendment, judged in relation to its legitimate sweep.', 'general', 'State v. Johnson, Terence', 'https://www.courtlistener.com/opinion/3007650/', '3007650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments below.', 'general', 'State v. Johnson, Terence', 'https://www.courtlistener.com/opinion/3007650/', '3007650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '— Tyler 2014) (explaining, "we conclude that Appellee’s conduct was not ''sufficiently imbued with elements of communication’ to implicate the First and Fourteenth Amendments,” and "[t]he record before us shows that Appellee engaged in an act of criminal mischief with no intent to convey any particularized message.', 'general', 'State v. Johnson, Terence', 'https://www.courtlistener.com/opinion/3007650/', '3007650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '13 In Ex parte Tmmsend, we held that even constitutional claims are forfeited if the applicant had the opportunity to raise the issue on appeal.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '22 Following Gonzalez and Knipp, we held that an applicant’s double jeopardy claim may be reviewed on collateral attack, under an exception to the procedural bar, if two conditions are met: (1) the undisputed facts show that the double jeopardy violation is clearly apparent on the face of the record;', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We then analyzed whether the applicant’s double jeopardy claim had merit, and we held that it did.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”34 However, following Gonzalez, we held that, “although the double jeopardy violation appeared to be clear when the Bexar County record was reviewed along with the documents from the Hays County record, the error was not apparent on the face of the Bexar County record alone, which it must be to cmercome the procedural bar resulting from Applicant’s failure to lodge an objection before the trial court.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that the Townsend rule of forfeiture is a qualified one, and it does not apply to claims that would fit within the first category of Marin v.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 This Court held that through an application for writ of habeas corpus, Loper claimed his conviction was “void for many reasons, all of which are matters that could have and should have been urged upon the trial of the Harris County case or, upon an "appeal therefrom.', 'habeas', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that jurisdiction is a systemic requirement that operates independent of litigants’ wishes, this Court held that the merits of Moss’s claim could be entertained irrespective of Townsend’s broad holding.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held Gonzalez had the burden to preserve his double-jeopardy complaint by objecting at or before the time the charge was submitted to the jury.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ex parte Denton, this Court held, ‘While the state may have an interest in maintaining the finality of a conviction, we perceive no legitimate interest in maintaining a conviction when it is clear on the face of the record that the conviction was obtained in contravention of constitutional double-jeopardy protections.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this Court held in Gonzalez that the appellant had forfeited his double jeopardy claim on appeal by failing to raise it at trial, we announced an’ exception to such rule of procedural default:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Gonzalez’s complaint was procedurally forfeited because ,“[t]imely raising the matter in the trial court would have provided the trial *858court and the prosecution an opportunity to remove the basis of the objection, and it also would have provided the prosecution” the opportunity to proceed on the'' second paragraph without the risk of an unnecessary retrial.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Townsend had forfeited his claim by failing to raise the issue on direct appeal.', 'general', 'Marascio, Eric Reed', 'https://www.courtlistener.com/opinion/3007661/', '3007661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We granted the defendant''s petition for hearing to decide whether the deceased witness''s statement should have been admitted at trial, We conclude that it should have *415been admitted, and we therefore reverse the defendant''s convictions and remand for a new trial.', 'general', 'Sanders v. State', 'https://www.courtlistener.com/opinion/3133191/', '3133191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s proper application of the evidence rules did not unfairly limit Sanders''s ability to present a defense.', 'general', 'Sanders v. State', 'https://www.courtlistener.com/opinion/3133191/', '3133191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '32 Because we conclude that the superi- *422or court''s factual finding that Bacod merely extrapolated: violence from Richards''s statement to her was clearly erroneous, we must reverse the court of appeals'' decision upholding the superior court''s Rule 8088) ruling.', 'general', 'Sanders v. State', 'https://www.courtlistener.com/opinion/3133191/', '3133191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the error was not harmless under the less-demanding standard for non-constitutional errors, we need not determine whether the error was harmless beyond a reasonable doubt.', 'general', 'Sanders v. State', 'https://www.courtlistener.com/opinion/3133191/', '3133191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the excluded evidence should have been admitted and because its exclusion was not harmless, we REVERSE Sanders''s convictions and REMAND for a new trial.', 'general', 'Sanders v. State', 'https://www.courtlistener.com/opinion/3133191/', '3133191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the purpose of I.', 'general', 'State v. Dameniel Preston Owens', 'https://www.courtlistener.com/opinion/3133309/', '3133309') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that (1) Idaho Code section 18-309’s language unambiguously requires courts to credit a defendant any prejudgment incarceration served on each count and (2) State v.', 'general', 'State v. Dameniel Preston Owens', 'https://www.courtlistener.com/opinion/3133309/', '3133309') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold a defendant receives credit for any prejudgment incarceration served on each of his consecutive sentences.', 'sentencing', 'State v. Dameniel Preston Owens', 'https://www.courtlistener.com/opinion/3133309/', '3133309') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we hold that defendant has forfeited any ineffectiveness claims on review that are premised upon the requesting officer’s alleged failure to disclose the age of the mail found in defendant’s trash.', 'ineffective_assistance', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Palmer, this court held that the imposition of consecutive sentences in that case was “contrary to the legislature’s intent” and therefore void.', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After thoroughly reviewing both defendant’s petition and the supporting record, we conclude that the trial court properly dismissed defendant’s pro se petition as frivolous and patently without merit.', 'dismissal', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we find that there is no arguable legal basis for defendant’s ineffective assistance of appellate counsel claim and that summary dismissal of his pro se postconviction therefore was proper.', 'dismissal', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As for the merits of defendant’s voidness claim, we find that defendant’s reliance on Palmer is misplaced.', 'general', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that section 5 — 8—4(a) does not apply here, based on the plain meaning of the word ‘consecutive.', 'general', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 165 (“we hold that section 5 — 8—4(a) does not apply here, based on the plain meaning of the word ‘consecutive’ ”).', 'general', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we held that, because defendant was sentenced under the Habitual Criminal Act (720 ILCS 5/33B — 1 (West 2002)), he was not subject to consecutive sentencing.', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, and “more importantly,” we held that it was impossible to serve consecutive natural-life sentences, “both according to natural law and within the plain meaning of the ‘consecutive’ sentencing law, section 5 — 8—4(a).', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Palmer, we reversed the circuit court’s imposition of the defendant’s consecutive natural-life sentences and modified the sentences to run concurrently.', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant may only serve these sentences concurrently, we reverse the circuit court’s imposition of consecutive natural-life sentences on the five remaining convictions.', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/3135598/', '3135598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the photographs were relevant to the manner in which Defendant dismembered the victim’s body, and we further determine that the admission of the photographs was not outweighed by any prejudicial effect.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that there is sufficient evidence to support Defendant’s conviction of first degree murder.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the notice to seek enhanced punishment was not materially misleading.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion by ordering Defendant’s sentences to run consecutively.', 'sentencing', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not abuse its discretion by denying coram nobis relief.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that: (1) the defendant’s sentence of death was not imposed in an arbitrary fashion;', 'sentencing', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the time, place, and purpose of the encounter, the presence of multiple officers, the nature of the questioning, the actual restraint on the defendant’s liberty, the character of the questioning, which focused on the victim’s homicide, and the remaining totality of the circumstances certainly would have “communicated to a reasonable person that he was not at liberty to ignore the police presence and go about his business.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As did the Court of Criminal Appeals, we conclude that the evidence preponderates against the trial court’s finding that the encounter was consensual and instead establishes that the defendant had been seized without a warrant, for purposes of the Fourth Amendment and article I, section 7, when he gave the statement on February 16th.', 'search_seizure', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, even assuming the attenuation doctrine should not have been applied, admission of the defendant’s statement was harmless error beyond a reasonable doubt.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*38We conclude that, even if erroneous, admission of the defendant’s statement had minimal impact on the jury’s decision-making in this case.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having carefully considered the entire record on appeal, we conclude that the State has demonstrated beyond a reasonable doubt that the erroneous admission of the defendant’s statement did not affect the jury’s verdict and was harmless beyond a reasonable doubt.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 Thus, we conclude that the trial court did not abuse its discretion in refusing to consider the defendant’s guilty pleas under Rule 11(b).', 'plea', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2010) (“Given the proof of the on-again, off-again nature of the victim’s relationship with the defendant, we conclude that the statements she made shortly before her death about her fear of the defendant were relevant and admissible under the state of mind exception to show not only her state of mind at the''time she uttered the statements, but also her probable mental state and behavior at the time of her death .', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the proof abundantly supports and does not preponderate against the trial court’s determination that the State satisfied the requirements necessary for application of the forfeiture by wrongdoing exception.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” *50But, again, given the leeway lawyers are afforded in making closing argument, we conclude that this argument is properly characterized as a comment on the testimony that the defendant “did not seem particularly concerned” and seemed “disinterested” when discussing the victim’s disappearance and murder.', 'general', 'State of Tennessee v. James Hawkins', 'https://www.courtlistener.com/opinion/4387691/', '4387691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the length of Garcia’s sentence, but we reverse the order of restitution and remand for a new restitution hearing.', 'sentencing', 'John Paul Garcia v. State of Indiana', 'https://www.courtlistener.com/opinion/3164244/', '3164244') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse and rémand in part.', 'general', 'John Paul Garcia v. State of Indiana', 'https://www.courtlistener.com/opinion/3164244/', '3164244') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the district court acted within its discretion, we affirm.', 'general', 'Jane Doe 136 v. Ralph Liebsch', 'https://www.courtlistener.com/opinion/3166413/', '3166413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed, stating that the guilty plea “was an admission that defendant spoke the words charged in the warrant.', 'plea', 'Jane Doe 136 v. Ralph Liebsch', 'https://www.courtlistener.com/opinion/3166413/', '3166413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*209In conformance with the overwhelming majority view, and the plain language of our statute, we hold that the Legislature did not make any reference to an “unborn" child” or “fetus” in W.', 'general', 'State of West Virginia v. Stephanie Elaine Louk', 'https://www.courtlistener.com/opinion/3207732/', '3207732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '648 (1918), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like these other jurisdictions, we conclude that when our Legislature intends to include an unborn child in a statute, it writes that language into the statute.', 'general', 'State of West Virginia v. Stephanie Elaine Louk', 'https://www.courtlistener.com/opinion/3207732/', '3207732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we conclude that W.', 'general', 'State of West Virginia v. Stephanie Elaine Louk', 'https://www.courtlistener.com/opinion/3207732/', '3207732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that Section 6317 was infirm.', 'general', 'Commonwealth, Aplt. v. Wolfe, M.', 'https://www.courtlistener.com/opinion/3215163/', '3215163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based upon the issue before the Court, we affirmed the trial court’s determination, finding Section 6317 to be constitutionally deficient, as it failed to provide the due process and Sixth Amendment rights accorded a defendant under Alleyne.', 'general', 'Commonwealth, Aplt. v. Wolfe, M.', 'https://www.courtlistener.com/opinion/3215163/', '3215163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ex parte Parrott, we held that a post-conviction habeas applicant who raises an illegal-sentence claim must show harm.', 'sentencing', 'Wright, Sir Melvin Jr.', 'https://www.courtlistener.com/opinion/4310946/', '4310946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the judgment of the court of appeals.', 'general', 'Wright, Sir Melvin Jr.', 'https://www.courtlistener.com/opinion/4310946/', '4310946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*483We affirm the judgment of the court of appeals.', 'general', 'Wright, Sir Melvin Jr.', 'https://www.courtlistener.com/opinion/4310946/', '4310946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ex parte Parrott, this Court held that, in order to receive habeas relief due to an illegal sentence, an applicant must show both a cognizable irregularity and harm.', 'sentencing', 'Wright, Sir Melvin Jr.', 'https://www.courtlistener.com/opinion/4310946/', '4310946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we hold that the pre*691sumption does not apply to pro se prisoner petitioners, and so we affirm the Superior Court’s order remanding the matter to the trial court for further proceedings.', 'general', 'Commonwealth, Aplt. v. Burton, S.', 'https://www.courtlistener.com/opinion/4378698/', '4378698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we hold that the presumption that information which is of public record cannot be deemed “unknown” for purposes of subsection 9545(b)(1)(H) does not apply to pro se prisoner petitioners.', 'general', 'Commonwealth, Aplt. v. Burton, S.', 'https://www.courtlistener.com/opinion/4378698/', '4378698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1264 (2007), wherein we held that the public record presumption does not apply to PCRA prisoners who are abandoned by their counsel, the majority reasoned: “[i]f our Supreme Court [in Bennett] has recognized expressly that, without the benefit of counsel, we cannot presume a petitioner has access to information contained in his own public, criminal docket, then surely it cannot be that we presume a pro se petitioner’s access to public information contained elsewhere.', 'general', 'Commonwealth, Aplt. v. Burton, S.', 'https://www.courtlistener.com/opinion/4378698/', '4378698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In rejecting the petitioner’s claim, we cited the Lark footnote and our subsequent decision in Whitney, see supra, for the proposition that “information is not ‘unknown’ to a PCRA petitioner when the information was a matter of public record,” and we held that, merely because the petitioner did not discover evidence of trial counsel’s DUI arrest at an earlier date did not mean the information was “unknown” to him for purposes of subsection 9545(b)(1)(ii).', 'general', 'Commonwealth, Aplt. v. Burton, S.', 'https://www.courtlistener.com/opinion/4378698/', '4378698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, after careful consideration, we conclude that, however reasonable the public record presumption may be with regard to PCRA petitioners generally, the presumption cannot reasonably be applied to pro se PCRA petitioners who are incarcerated.', 'general', 'Commonwealth, Aplt. v. Burton, S.', 'https://www.courtlistener.com/opinion/4378698/', '4378698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that the substance of the tape was not publicized until April 1997, we concluded that, because “the facts upon which Appellant based his claim were not known to him and could not have been discovered in the exercise of due diligence until that date,” the appellant’s “presentation of the claim regarding the McMahon tape in the second PCRA petition was timely.', 'general', 'Commonwealth, Aplt. v. Burton, S.', 'https://www.courtlistener.com/opinion/4378698/', '4378698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[s]uch questions require further fact-finding and the PCRA court, acting as fact finder, should determine whether Appellant met the ‘proof requirement under 42 Pa.', 'general', 'Commonwealth, Aplt. v. Burton, S.', 'https://www.courtlistener.com/opinion/4378698/', '4378698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the PCRA court did not address the merits of the appellant’s Batson claim, we found that a sufficient record existed to enable this Court’s review of the claim.', 'general', 'Commonwealth, Aplt. v. Burton, S.', 'https://www.courtlistener.com/opinion/4378698/', '4378698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that neither the City nor any of its sub-units or employees may enforce the Rule to the extent it purports to prohibit carrying any knife or firearm (as defined by the Local Regulation Statute) or weapon (as defined by the Concealed-Carry Statute), so long as such carrying is not forbidden by (and is done in compliance with) the Vehicle Statute, Wis.', 'general', 'Wisconsin Carry, Inc. v. City of Madison', 'https://www.courtlistener.com/opinion/4373247/', '4373247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the City—acting either through its governing body or sub-units—has no authority to "regulate [] the .', 'general', 'Wisconsin Carry, Inc. v. City of Madison', 'https://www.courtlistener.com/opinion/4373247/', '4373247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that meaning in the statute''s text, context, and structure: "[Statutory interpretation ''begins with the language of the statute.', 'general', 'Wisconsin Carry, Inc. v. City of Madison', 'https://www.courtlistener.com/opinion/4373247/', '4373247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') (plurality opinion) ("We find that the state constitutional right to bear arms is fundamental.', 'general', 'Wisconsin Carry, Inc. v. City of Madison', 'https://www.courtlistener.com/opinion/4373247/', '4373247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless—given the relatively minimal bias the prospective juror must have had toward finding this particular defendant guilty, her final and unequivocal statement that she would give Allen the benefit of the doubt until the close of trial, and her demonstrated ability to follow the judge''s instructions—we hold that the district court was within its discretion to find that the prospective juror'' prior experience would not impede her ability to decide the case fairly.', 'general', 'State v. Jeffrey P. Lepsch', 'https://www.courtlistener.com/opinion/4379739/', '4379739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that offenders in a habitual offender proceeding must preserve error in any deficiencies in the proceeding by filing a motion in arrest of judgment.', 'general', 'State of Iowa v. Andre Letroy Antwan Harrington', 'https://www.courtlistener.com/opinion/4381493/', '4381493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with Kukowski and Brady, we conclude that a motion in arrest of judgment is a proper vehicle to bring claims of deficiencies in a habitual offender proceeding.', 'general', 'State of Iowa v. Andre Letroy Antwan Harrington', 'https://www.courtlistener.com/opinion/4381493/', '4381493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the uncontested judgment of guilt on the present offense, second-degree robbery.', 'general', 'State of Iowa v. Andre Letroy Antwan Harrington', 'https://www.courtlistener.com/opinion/4381493/', '4381493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Kukowski, we held that a defendant’s admission of prior convictions in the enhancement phase must be “voluntary and intelligent,” and I have no quarrel with that proposition.', 'general', 'State of Iowa v. Andre Letroy Antwan Harrington', 'https://www.courtlistener.com/opinion/4381493/', '4381493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the officers’ entry onto the De*64fendant’s property was constitutionally permissible in spite of the posted “No Trespassing” signs near the Defendant’s unobstructed driveway.', 'general', 'State of Tennessee v. James Robert Christensen, Jr.', 'https://www.courtlistener.com/opinion/4381703/', '4381703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, under the totality of the circumstances, the Defendant’s “No Trespassing” signs posted near his unobstructed driveway were not sufficient to revoke the implied license referred to in Jardines.', 'general', 'State of Tennessee v. James Robert Christensen, Jr.', 'https://www.courtlistener.com/opinion/4381703/', '4381703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reasons supporting our holding under the Jardines test, we hold that the Defendant has failed to satisfy the second prong of the reasonable expectations test.', 'general', 'State of Tennessee v. James Robert Christensen, Jr.', 'https://www.courtlistener.com/opinion/4381703/', '4381703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Investigators Green and Chunn did not violate either the federal or Tennessee constitutional prohibitions *79against unreasonable searches when they drove down the Defendant’s unobstructed driveway past “No Trespassing” signs and approached his residence in order to conduct a knoek-and-talk consensual encounter.', 'general', 'State of Tennessee v. James Robert Christensen, Jr.', 'https://www.courtlistener.com/opinion/4381703/', '4381703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals.', 'general', 'State of Tennessee v. James Robert Christensen, Jr.', 'https://www.courtlistener.com/opinion/4381703/', '4381703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the mandatory joinder statute did not require joinder of Mr.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such a broad interpretation of the phrase “single criminal objective” would render the permissive joinder statute inoperative, which would violate our principles of statutory interpretation.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that Mr.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we conclude that even though the mandatory and permissive joinder statutes “do not share a common statutory title,” they are related chapters and must be interpreted in harmony with one another.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our totality of the circumstances test, we conclude that Mr.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '15 We conclude that Mr.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rushton had the “opportunity to make a conscious and knowing decision to engage” in the next-in-time offense, we conclude that Mr.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 3 We affirm the decision of the court of appeals, albeit along a somewhat different *94line of reasoning.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 10 We affirm the court of appeals’ denial of Mr.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rushton’s tax crimes and wage crimes in a single prosecution, and we affirm the court of appeals’ decision upholding the denial of Mr.', 'general', 'State v. Rushton', 'https://www.courtlistener.com/opinion/4381764/', '4381764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), for example, this court held that the defendant’s “wide-eyed” nervousness, evasive act of “quickly walkpng] away from the police,” dishonest response to police questioning, and presence in a “high crime area,” along with other factors, were insufficient to furnish reasonable suspicion that the defendant was engaged in criminal activity.', 'general', 'Nathan P. Jackson v. United States', 'https://www.courtlistener.com/opinion/4382813/', '4382813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2017), this court held that a suspect description generated by officers who had reviewed a surveillance video and con*1274veyed to another officer who had not seen the video was insufficient to provide the latter officer with reasonable suspicion to stop the appellant.', 'general', 'Nathan P. Jackson v. United States', 'https://www.courtlistener.com/opinion/4382813/', '4382813') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Therefore, we conclude that the precedent relied upon by McNeil is distinguishable and does not compel a similar result here.', 'general', 'Brenton McNeil v. State of Florida', 'https://www.courtlistener.com/opinion/4382826/', '4382826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ragland, we held that a life-without-the-possibility-of-parole sentence, even if commuted to a mandatory term of sixty years, violated the Roper-Graham-MiUer principles under article I, section 17 of the Iowa Constitution.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Null, we held that the Roper-Graham-Miller principles apply to lengthy prison terms imposed as a result of consecutive sentencing.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the Roper-Grahamr-Miller principles applied, vacated the sentence, and remanded the ease to the district court for a Miller-type hearing.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sweet, we held that life without the possibility of parole was categorically prohibited under article I, section 17 of the Iowa Constitution.', 'general', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in Lyle, we held that a seven-year mandatory minimum sentence could not be imposed without a hearing to consider the impact of the characteristics of youth in lessening criminal culpability.', 'sentencing', 'State of Iowa v. Sayvon Andre Propps', 'https://www.courtlistener.com/opinion/4394388/', '4394388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'result element of the crime of threats, we hold that the government may carry its burden of proof by establishing that the defendant acted with the purpose to threaten or with knowledge that his words would be perceived as a threat.', 'general', 'Lee Carrell v. United States (Revised Version)', 'https://www.courtlistener.com/opinion/4414899/', '4414899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Echoing the analysis of the division, the government argues that, even if we hold that the mens rea for the result element- of threats is satisfied by proof of purpose or knowledge, as we have done, Mr.', 'general', 'Lee Carrell v. United States (Revised Version)', 'https://www.courtlistener.com/opinion/4414899/', '4414899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, at his bench trial, Mr.', 'general', 'Lee Carrell v. United States (Revised Version)', 'https://www.courtlistener.com/opinion/4414899/', '4414899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a reasonable factfinder could have determined that he acted with a mens rea adequate to *327support his conviction of attempted threats.', 'general', 'Lee Carrell v. United States (Revised Version)', 'https://www.courtlistener.com/opinion/4414899/', '4414899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we concluded that her argument was preserved for our review, because it was “in reality a challenge to the sufficiency of the evidence to sustain her conviction.', 'general', 'Lee Carrell v. United States (Revised Version)', 'https://www.courtlistener.com/opinion/4414899/', '4414899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus in jury trial cases, we affirm the conviction if we think "that the omitted element was uncontested and supported by.', 'general', 'Lee Carrell v. United States (Revised Version)', 'https://www.courtlistener.com/opinion/4414899/', '4414899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 24 We hold that Mr.', 'general', 'State v. Lambdin', 'https://www.courtlistener.com/opinion/4418214/', '4418214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 33 We hold that the defendant must establish, by a preponderance of the evidence, that his loss of self-control was reasonable and that the average person''s reason would have been overcome by extremely unusual and overwhelming stress and extreme emotions.', 'general', 'State v. Lambdin', 'https://www.courtlistener.com/opinion/4418214/', '4418214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 54 We hold that a criminal defendant who seeks to establish special mitigation by extreme emotional distress must prove that his loss of self-control is reasonable.', 'general', 'State v. Lambdin', 'https://www.courtlistener.com/opinion/4418214/', '4418214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this, we hold that the jury instructions in this case were an adequate depiction of the law.', 'jury_instruction', 'State v. Lambdin', 'https://www.courtlistener.com/opinion/4418214/', '4418214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals.', 'general', 'State v. Lambdin', 'https://www.courtlistener.com/opinion/4418214/', '4418214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 3] We conclude that the court erred in addressing the parents’ untimely raised allegations that they had received ineffective assistance of counsel at the jeopardy stage, in ordering further reunification efforts, and in declining to adjudicate the claim of ineffective assistance of counsel regarding the termination proceeding.', 'ineffective_assistance', 'In re Evelyn A.', 'https://www.courtlistener.com/opinion/4420708/', '4420708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the court abused its discretion in allowing the late motion to amend the Rule 60(b) motion, we need not, in this .', 'general', 'In re Evelyn A.', 'https://www.courtlistener.com/opinion/4420708/', '4420708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 22] In sum, given the intensely time-sensitive nature of child protection proceedings, we conclude that the court abused its discretion in granting the motion to amend the motion for relief to include allegations of ineffective assistance at the jeopardy stage.', 'ineffective_assistance', 'In re Evelyn A.', 'https://www.courtlistener.com/opinion/4420708/', '4420708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the court’s order as to both parents.', 'general', 'In re Evelyn A.', 'https://www.courtlistener.com/opinion/4420708/', '4420708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 33] Thus, to be clear, we affirm the court’s decision vacating its termination order, although we do so on other grounds.', 'general', 'In re Evelyn A.', 'https://www.courtlistener.com/opinion/4420708/', '4420708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶3 We conclude that exigent circumstances existed, permitting police to draw Dalton''s blood absent a warrant.', 'general', 'State v. Patrick H. Dalton', 'https://www.courtlistener.com/opinion/4513690/', '4513690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶68 In sum, we conclude that exigent circumstances existed, permitting police to draw Dalton''s blood absent a warrant.', 'general', 'State v. Patrick H. Dalton', 'https://www.courtlistener.com/opinion/4513690/', '4513690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶69 Accordingly, we reverse the decision of the court of appeals, and remand to the circuit court for resentencing.', 'sentencing', 'State v. Patrick H. Dalton', 'https://www.courtlistener.com/opinion/4513690/', '4513690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"6 *781With this understanding, we hold that there is no genuine issue regarding the fact that a fraudulent insurance act, as defined by MCL 500.', 'general', 'Kalvin Candler v. Farm Bureau Mutual Insurance Company of Michigan', 'https://www.courtlistener.com/opinion/4437270/', '4437270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the denial of defendant''s motion for summary disposition.', 'general', 'Kalvin Candler v. Farm Bureau Mutual Insurance Company of Michigan', 'https://www.courtlistener.com/opinion/4437270/', '4437270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the evidence, we conclude that the appellant understood his rights, yet still agreed to speak with law enforcement.', 'general', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the prosecuting attorney made several inappropriate comments during his closing arguments.', 'general', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no evidence of coercion on the part of law enforcement officials, we conclude that Hernandez'' statements were made voluntarily.', 'general', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hernandez'' statement, "I think I''ll probably stop talking now," was not a clear, unambiguous, and unequivocal of his right to remain silent and terminate the custodial interrogation.', 'general', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'rights, voluntarily spoke with the investigators, and did not subsequently invoke his right to remain silent until the end of the interview, we conclude that the district court did not err in denying Hernandez'' motion to suppress and trial objections to the video interview.', 'suppression', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion in finding the statements were relevant.', 'general', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion by overruling in part Hernandez'' motion in limine and trial objections.', 'general', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that a prosecutor''s acts were misconduct, we next consider whether the misconduct prejudiced the defendant''s right to a fair trial.', 'general', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Hernandez'' right to a fair trial was not prejudiced and the district court did not abuse its discretion in overruling Hernandez'' motion for mistrial.', 'mistrial', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the evidence, we find that he did.', 'general', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/4497144/', '4497144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in Read, we held that the "abusive language" prong of the disorderly conduct statute could only reach abusive language that falls outside the protection of the First Amendment-namely, "fighting words.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The majority suggests that in Sanville this Court held that verbal threats do not violate § 1026(a)(1).', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the evidence was insufficient to support a conviction for "threatening behavior" because the behavior did not convey an intent to do harm to another person.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the district court and the decision of the court of appeals.', 'general', 'State of Iowa v. Michael Cory Kelso-Christy', 'https://www.courtlistener.com/opinion/4495429/', '4495429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the circumstantial evidence was sufficient for a reasonable juror to conclude beyond a reasonable doubt that the defendant acted with the specific intent to commit sexual abuse, we affirmed his conviction.', 'general', 'State of Iowa v. Michael Cory Kelso-Christy', 'https://www.courtlistener.com/opinion/4495429/', '4495429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s home with the intent to commit sexual abuse, we affirm his conviction.', 'general', 'State of Iowa v. Michael Cory Kelso-Christy', 'https://www.courtlistener.com/opinion/4495429/', '4495429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2010), we held that a trial court must notify defendants of direct, not collateral, consequences of their guilty pleas.', 'plea', 'State of Tennessee v. Westley A. Albright', 'https://www.courtlistener.com/opinion/4572199/', '4572199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying strict scrutiny, we hold that application of the statute to defendant''s conduct was a narrowly tailored means of furthering the state''s compelling interest in preserving the impartiality and integrity of jurors.', 'general', 'People of Michigan v. Keith Eric Wood', 'https://www.courtlistener.com/opinion/4572256/', '4572256') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', a ''prospective juror'') in a pending trial impairs the administration of justice in exactly the same way that justice is impaired by a *281threat or influence of an impaneled ''juror,'' we conclude that the term ''juror'' in the statute includes a ''prospective juror'' within its reach.', 'general', 'People of Michigan v. Keith Eric Wood', 'https://www.courtlistener.com/opinion/4572256/', '4572256') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that to be valid, the indictment charging felony littering must allege that the accused is an unauthorized person who deposited refuse on property not designated for such activity.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that subdivision (a)(1) is so intertwined with the description of the offense of littering that it forms an essential element of the crime.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Greer we held that an indictment is facially invalid when it omits any essential elements of the crime to be charged.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the indictment was facially valid because it clearly identified "the conduct which [was] the subject of the accusation" by alleging that the defendant received United States currency by pawning stolen property as if it were his own.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the indictment was facially invalid, we affirm the decision of the Court of Appeals.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that subdivision (a)(1), which requires that the accused be an unauthorized person depositing refuse on land not designated by the State for such use, is an essential element of the crime of felony littering, however, we acknowledge the legislature''s power to determine otherwise.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that subdivision (a)(1), which requires that the accused be an unauthorized person depositing refuse on land not designated by the State for such use, is an essential element of the crime of felony littering.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Court of Appeals'' decision to vacate defendant''s conviction for felony littering of hazardous waste.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the holding of the Court of Appeals.', 'general', 'State v. Rankin', 'https://www.courtlistener.com/opinion/4576199/', '4576199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm on other grounds the panel''s judgment.', 'general', 'STATE IN the INTEREST OF D.M., a Juvenile', 'https://www.courtlistener.com/opinion/4650556/', '4650556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on other grounds the judgment of the Appellate Division.', 'general', 'STATE IN the INTEREST OF D.M., a Juvenile', 'https://www.courtlistener.com/opinion/4650556/', '4650556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our precedent in Lippay, we hold that we may not consider the inadmissible evidence of the lawyers’ statements in reviewing the sufficiency of the evidence sustaining the punitive award.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 195, in which we held that a plaintiffs claim of tor-tious interference with prospective relations, based on the theory that a defendant ruined his future prospects as a consultant by injuring his reputation, failed because he had not demonstrated a reasonable prospect of attaining future business.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), we held that a police officer’s explanations of cryptic remarks made in tape recorded conversations between drug traffickers were admissible under Fed.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we held that where the statements are clear, such opinion testimony is not helpful to the trier of fact and is inadmissible under both Rules 701 and 702.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such an allegation did not state an injury cognizable under section 1962(a);', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 708-10, we held that a complaint failed to state a section 1962(a) claim where the plaintiffs, a class of consumers who purchased allegedly defective residential oil furnaces from the defendant manufacturer, claimed an investment injury because the manufacturer was allowed to continue in business as a consequence of income derived from earlier frauds.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not resolve this issue now, however, because even if we held that the district court erred in holding that Witco could not be both the person and enterprise under section 1962(b),19 we would not change the district court’s result as it is clear that in any case Lightning Lube has failed to state a section 1962(b) claim.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing this evidence in the light most favorable to Lightning Lube, we conclude that it has produced at least that minimum quantum of evidence required to show that Witco damaged it.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to this case, we conclude that Lightning Lube established the amount of damages to a reasonable certainty.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But after carefully studying the record, we conclude that the court appropriately exercised its authority.', 'general', 'Lightning Lube, Inc. v. Witco Corp.', 'https://www.courtlistener.com/opinion/7026532/', '7026532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of recent federal precedent, we conclude that the second factor in the emergency-aid test set forth in Frankel, which addresses the officer’s subjective motivation, is no longer consonant with Fourth Amendment jurisprudence.', 'search_seizure', 'State v. Edmonds', 'https://www.courtlistener.com/opinion/7409392/', '7409392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite the defendant’s refusal to give the officer consent to enter his home, we found that the officer “had an objectively reasonable and good-faith basis to believe that an emergency was at hand that could not brook delay.', 'general', 'State v. Edmonds', 'https://www.courtlistener.com/opinion/7409392/', '7409392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the “carefully modulated response of the officers, and of [the sergeant] in particular,” was “objectively reasonable.', 'general', 'State v. Edmonds', 'https://www.courtlistener.com/opinion/7409392/', '7409392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed, we affirm the judgment of the Appellate Division, which upheld the trial court’s suppression of *145the handgun as the fruit of an unconstitutional search of a home.', 'suppression', 'State v. Edmonds', 'https://www.courtlistener.com/opinion/7409392/', '7409392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1974), this Court held that “[t]he validity of the search warrant, the legality of the search and the admissibility of the evidence obtained as a result of the search were matters of law to be determined by the trial court” and were “not questions to be determined by the jury.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/5105382/', '5105382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because “the parties at trial were in agreement that Burdette shot Smith at point-blank range,” this Court held that the constitutional error was harmless, as the evidence against Burdette was overwhelming.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/5105382/', '5105382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in Conners, this Court held that the admission of a ballistics report and a toxicology report violated the Confrontation Clause but constituted mere harmless error, since that “evidence was largely cumulative of other evidence before the jury,” and thus, “the error in admitting the reports in violation of Conners’s right to confront the analysts was harmless beyond a reasonable doubt.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/5105382/', '5105382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find error, we reverse the judgments of the trial court and the Court of Appeals and remand the case to the Circuit Court of Neshoba County for a new trial.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/5105382/', '5105382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In those cases we reversed, not only because of the violation of the defendants’ confrontation rights, but also because search warrants, including affidavits attesting to specific underlying facts and circumstances not appropriate *741for the consideration of the jury, contained other, highly prejudicial information.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/5105382/', '5105382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With all due respect for our fellow Justices, we disagree with the dissent and we find that a good cause does not exist to suspend our rules in this case and decline to do so.', 'general', 'McCalpin v. State', 'https://www.courtlistener.com/opinion/5105406/', '5105406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the doctrine of stare deci-sis does not apply to the Chacko footnote, because the passage was not necessary to the outcome of the case.', 'general', 'In the Interest of L.J.', 'https://www.courtlistener.com/opinion/5147304/', '5147304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the first statement should have been suppressed, because it was given during a custodial interrogation without Miranda warnings.', 'suppression', 'In the Interest of L.J.', 'https://www.courtlistener.com/opinion/5147304/', '5147304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, given that this opinion serves to right an inaccurate interpretation of prior law, we find that this decision significantly alters the appellate process of this and other cases substantially.', 'general', 'In the Interest of L.J.', 'https://www.courtlistener.com/opinion/5147304/', '5147304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that sufficient evidence was presented to permit the jury to properly conclude that Appellant was guilty of the first-degree murder of Diaz beyond a reasonable doubt.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5147462/', '5147462') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case sub judice, we hold that no voluntary manslaughter instruction was warranted because Appellant denied that he shot anyone.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5147462/', '5147462') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this issue is waived because counsel expressly conceded the admissibility of the photos at trial, and counsel’s objection to the proposed publication to the jury of the photo that included the sub-headline “two were killed over drug debt,” was sustained and that particular photo was not published.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5147462/', '5147462') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the challenged remark in that context, and on this record, we conclude that a new trial is not warranted on this issue.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5147462/', '5147462') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following review of the facts and the record, we conclude that the sentence of death was not the result of “passion, prejudice, or any other arbitrary factor,” but rather was based on the Commonwealth’s evidence admitted at trial.', 'sentencing', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5147462/', '5147462') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we conclude that the evidence admitted at trial was sufficient “to support the finding of at least one aggravating circumstance.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5147462/', '5147462') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5147462/', '5147462') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 75, 77 (1971), we affirmed a judgment of sentence for first-degree murder where no instruction on voluntary manslaughter had been given.', 'sentencing', 'Commonwealth v. Sanchez', 'https://www.courtlistener.com/opinion/5147462/', '5147462') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that juvenile offenders have a protected right to reputation encroached by SORNA’s presumption of recidivism, where the presumption is not universally true, and where there is a reasonable alternative means for ascertaining the likelihood of recidivating, we hold that the application of SORNA’s current lifetime *20registration requirements upon adjudication of specified offenses violates juvenile offenders’ due process rights by utilizing an irrebuttable presumption.', 'general', 'In the Interest of J.B.', 'https://www.courtlistener.com/opinion/5148392/', '5148392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, while the interest in precluding unsafe drivers from taking to Pennsylvania’s roads was important, it did not justify the recall of a licensee’s operating privileges -without first affording him a meaningful hearing on his competency to drive.', 'general', 'In the Interest of J.B.', 'https://www.courtlistener.com/opinion/5148392/', '5148392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As detailed below, we conclude that SORNA’s registration requirements violate juvenile offenders’ due process rights by utilizing the irrebuttable presumption that all juvenile offenders “pose a high risk of committing additional sexual offenses,” 42 Pa.', 'general', 'In the Interest of J.B.', 'https://www.courtlistener.com/opinion/5148392/', '5148392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '28 Accordingly, we conclude that the Juveniles have asserted a constitutionally protected interest in their reputation that has been encroached by the use of an irrebuttable presumption.', 'general', 'In the Interest of J.B.', 'https://www.courtlistener.com/opinion/5148392/', '5148392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the procedure provided a hearing regarding the fact of the seizure, we concluded that the hearing did not provide a meaningful opportunity to rebut the statutory presumption that a single seizure rendered the individual unfit to drive.', 'general', 'In the Interest of J.B.', 'https://www.courtlistener.com/opinion/5148392/', '5148392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we concluded that the hearing did not comport with due process.', 'general', 'In the Interest of J.B.', 'https://www.courtlistener.com/opinion/5148392/', '5148392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 After review, we affirm the determination that SORNA violates juvenile offenders’ .', 'general', 'In the Interest of J.B.', 'https://www.courtlistener.com/opinion/5148392/', '5148392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the determination of the trial court that the application of SORNA’s lifetime registration provision as applied to juveniles is unconstitutional.', 'general', 'In the Interest of J.B.', 'https://www.courtlistener.com/opinion/5148392/', '5148392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 947 (1967), this Court held that the appellant was denied due process where there was no transcript of the arraignment proceedings, thus necessitating resort to parol evidence to establish what took place at those proceedings.', 'general', 'State v. Aguilar', 'https://www.courtlistener.com/opinion/5340693/', '5340693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 113 (1954), this Court held as follows:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we hold that Section 38.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’ ”32 *746We hold that the purported restriction in question here — the police skirmish line— was a reasonable restriction on the time, place, and manner of protected speech because the skirmish line met the above three requirements.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the temporary skirmish line was a lawful means to effect the police purpose of preserving the peace at the gay pride parade.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the skirmish line did not violate appellants’ First- Amendment rights.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Section 38.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that defendant’s bare request for an acquittal, without articulating a reason, was not enough to preserve error of his constitutional claims.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2009), this Court held that "no technical considerations or forms of words” are required to preserve an error for appeal, and a party must only "be specific *745enough so as to ‘let the trial judge know what he wants, why he thinks himself entitled to it, and do so clearly enough for the judge to understand him at a time when the trial court is in a proper position to do something about it.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the skirmish line was content neutral, even though it may have had the incidental effect of temporarily hindering appellants’ ability to deliver their message to the parade-goers.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that, while a regulation of the time, place, or manner of protected speech must be narrowly tailored to serve the government’s legitimate, content-neutral interest, it need not be the least restrictive or least intrusive means of doing so.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus,, we find that the police officers narrowly tailored the restriction to serve a significant governmental interest.', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1978), we held that “[r]egardless of whether [Gonzalez’s] arrest was lawful or unlawful, the deputy constable was in the lawful discharge of his duty when he attempted to arrest [Gonzalez].', 'general', 'Faust v. State', 'https://www.courtlistener.com/opinion/5446902/', '5446902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the evidence did not support a finding that the car in which the defendant left the scene was a deadly weapon, since there was no indication he was speeding, the truck obeyed a traffic light, it never left the roadway, and there was no other traffic on the road.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/5448475/', '5448475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a rational factrfinder could infer that Appellant was using his motor vehicle in this case in a manner that was capable of causing death or serious bodily injury, even though it did not do so, and regardless of whether he intended it to.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/5448475/', '5448475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “the danger was real, .', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/5448475/', '5448475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was evidence of reckless or dangerous driving in that the defendant had been speeding, and had failed to apply his breaks or otherwise control his vehicle prior to the collision.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/5448475/', '5448475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals’ judgment to the extent that it deleted the deadly weapon finding, and we reinstate the original, unmodified judgment of the trial court.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/5448475/', '5448475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Burke', 'https://www.courtlistener.com/opinion/8081897/', '8081897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In several of our decisions, we have drawn a negative implication from this express directive that provisions contained within Titles 1 through 3 apply to offenses that are outside the Penal Code: We held that provisions contained in other titles of the Penal Code did not apply to offenses that are outside the Penal Code.', 'general', 'Chase, Ryan Francis', 'https://www.courtlistener.com/opinion/2949023/', '2949023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that a defensive issue does not become law applicable to the case if it is neither requested nor submitted.', 'general', 'Chase, Ryan Francis', 'https://www.courtlistener.com/opinion/2949023/', '2949023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does and affirm the judgment of the court of appeals.', 'general', 'Chase, Ryan Francis', 'https://www.courtlistener.com/opinion/2949023/', '2949023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the reasons we have discussed, we conclude that the various statutes at issue, are ambiguous with respect to whether § 822.', 'general', 'Chase, Ryan Francis', 'https://www.courtlistener.com/opinion/2949023/', '2949023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '013 and other relevant statutes, we conclude that § 822.', 'general', 'Chase, Ryan Francis', 'https://www.courtlistener.com/opinion/2949023/', '2949023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”) (“Under the circumstances, we find that appellant has failed to meet his burden of production to show the applicability of his claimed defense.', 'general', 'Chase, Ryan Francis', 'https://www.courtlistener.com/opinion/2949023/', '2949023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 The court acknowledged that we reversed the Fort Worth Court of Appeals but pointed out that our holding was based on the fact that the predecessor statute did not apply statewide.', 'general', 'Chase, Ryan Francis', 'https://www.courtlistener.com/opinion/2949023/', '2949023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the judgment of the court of appeals.', 'general', 'Chase, Ryan Francis', 'https://www.courtlistener.com/opinion/2949023/', '2949023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’s case, we held that “scent-discrimination lineups, when used alone or as primary evidence, are legally insufficient to support a conviction.', 'general', 'Winfrey, Megan AKA Megan Winfrey Hammond', 'https://www.courtlistener.com/opinion/2948611/', '2948611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that third-degree-felony family-violence assault is a result-of-conduct offense only and that the trial court did not err in limiting the definitions of the applicable culpable mental states in the jury charge to the result of conduct.', 'general', 'Price, Eric Ray', 'https://www.courtlistener.com/opinion/2950605/', '2950605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2008), in which we held that aggravated assault is a result-of-conduct offense with one gravamen-causing bodily injury.', 'general', 'Price, Eric Ray', 'https://www.courtlistener.com/opinion/2950605/', '2950605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Appellant did not object to the trial court’s failure to include nature-of-conduct language in the jury charge, thus if we find that the jury charge was erroneous, we will consider the effect of the error under the standard of egregious harm.', 'general', 'Price, Eric Ray', 'https://www.courtlistener.com/opinion/2950605/', '2950605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because domestic violence is a result-of-conduct offense only, we affirm the judgment of the court of appeals.', 'general', 'Price, Eric Ray', 'https://www.courtlistener.com/opinion/2950605/', '2950605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court erred to submit language in the abstract-definitions portion of the juiy charge with respect to how culpable mental states should apply to nature-of-conduct and circumstances-surrounding-conduct elements: "It is error for a trial judge to not limit the definitions of the culpable mental states as they relate to the conduct elements involved in the particular offense.', 'general', 'Price, Eric Ray', 'https://www.courtlistener.com/opinion/2950605/', '2950605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reversed and remanded for a harm analysis under Almanza v.', 'general', 'Price, Eric Ray', 'https://www.courtlistener.com/opinion/2950605/', '2950605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶40 After the trial court granted Gilbert’s “motion for summary judgment,” we reversed its ruling that returned the money to her, concluding that in view of the fictitious sender, deceptive packaging, and Gilbert’s denials and abandonment, the trial court had erred in finding that police lacked probable cause to seize the money.', 'probable_cause', 'In re United States Currency In Amount of $26,980.00', 'https://www.courtlistener.com/opinion/6603659/', '6603659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the vaguely and broadly worded standard in N.', 'general', 'State v. Burkert', 'https://www.courtlistener.com/opinion/7412916/', '7412916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we found that a defendant who ripped up a court support order and sent it to his estranged wife did not constitute harassment under N.', 'general', 'State v. Burkert', 'https://www.courtlistener.com/opinion/7412916/', '7412916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Burkert', 'https://www.courtlistener.com/opinion/7412916/', '7412916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm the judgment of the Appellate Division, which dismissed the harassment charges.', 'dismissal', 'State v. Burkert', 'https://www.courtlistener.com/opinion/7412916/', '7412916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is a prerequisite to a claim of ineffective representation on appeal to preserve the testimony of trial counsel.', 'ineffective_assistance', 'State v. Balliette', 'https://www.courtlistener.com/opinion/8238536/', '8238536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the defendant is not entitled to an evidentiary hearing because the allegations in his § 974.', 'general', 'State v. Balliette', 'https://www.courtlistener.com/opinion/8238536/', '8238536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we reverse the decision of the court of appeals.', 'general', 'State v. Balliette', 'https://www.courtlistener.com/opinion/8238536/', '8238536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Padilla is a new rule of constitutional criminal procedure, but is not a watershed rule, we hold that Reyes Campos may not avail himself of the retroactive application of Padilla.', 'general', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, because Minnesota law governing the standard for effective assistance of counsel at the time Reyes Campos’ conviction became final did not require counsel to inform a defendant of the immigration consequences of pleading guilty, we hold that Reyes Campos did not receive ineffective assistance of counsel.', 'plea', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Padilla announced a new rule of -criminal procedure that does not apply to a collateral review of Reyes Campos’ conviction, we reverse.', 'general', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As set forth below, we conclude that Padilla does not apply retroactively.', 'general', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing our retroactivity analysis under Teague, as well as decisions from other courts considering whether Padilla applies retroactively to cases on collateral review, we conclude that Padilla announced a new rule of federal constitutional criminal procedure.', 'general', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even under an independent “objective reading of the relevant cases,” however, we conclude that Padilla was not dictated by precedent.', 'general', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of these reasons we conclude that Padilla announced a new rule of criminal procedure.', 'general', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Alanis, we concluded that because deportation was merely a collateral consequence of a guilty plea, the defendant’s “attorney was under no obligation to advise him of the deportation possibility and, therefore, the failure to so inform him could not have fallen below an objective standard of reasonableness as required by Strickland.', 'plea', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*509In Alanis, we concluded that an attorney’s failure to inform his client “that his guilty plea might subject him to deportation” did not constitute ineffective assistance of counsel because, “as a collateral consequence of the guilty plea, his attorney was under no obligation to advise him of the deportation possibility and, therefore, the failure to so inform him could not have fallen below an objective standard of reasonableness as required by Strickland.', 'plea', 'Campos v. State', 'https://www.courtlistener.com/opinion/8280632/', '8280632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm our right to take jurisdiction in those situations where in the interests of justice the merits should be heard.', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the Commonwealth cogently noted, this Court held in Champney that *49a witness’s assumption that he will benefit from cooperating in the prosecution of the defendant, without more, is insufficient to establish that an agreement existed, and does not trigger Brady disclosure requirements.', 'general', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we conclude that the PCRA court’s findings of fact are supported by the record, and its legal conclusions are free of error.', 'general', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that trial counsel was not ineffective for failing to investigate and present evidence of the victim’s violent character during the penalty phase to support the aggravating circumstance of the Section 9711(e)(3) mitigating circumstance, ie.', 'ineffective_assistance', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with the PCRA court that Appellant is not entitled to relief, and reject the claim for lack of prejudice as we conclude that the outcome of Appellant’s direct appeal would not have been different had counsel challenged the admissibility of Melendez’s prior statement.', 'general', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon careful review, we find that the PCRA court’s factual findings are supported by the record and its conclusions of law are free from legal error.', 'general', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without hesitation, we find that it did not.', 'general', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that Appellant was not denied a fair trial when the prosecutor referred to his defense strategy of discrediting Commonwealth witnesses as “smoke and mirrors.', 'general', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth herein, we affirm.', 'general', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*76Accordingly, for the reasons set forth herein, we affirm the order of the PCRA court dismissing Appellant’s PCRA petition.', 'dismissal', 'Commonwealth v. Busanet', 'https://www.courtlistener.com/opinion/5145705/', '5145705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Alexander failed to prove by clear and convincing evidence that the circuit court erroneously exercised its discretion by actually relying on Alexander''s compelled, incriminating statements in imposing sentence.', 'sentencing', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Alexander was not prejudiced by his counsel''s lack of objection to those same statements.', 'general', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, after reviewing the sentencing transcript as a whole and the court''s comments in denying Alexander''s motion for resentencing, we conclude that the circuit court relied on proper factors in imposing sentence and did not actually rely on Alexander''s compelled statements.', 'sentencing', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Alexander failed to prove by clear and convincing evidence that the circuit court erroneously exercised its discretion by actually relying *317on Alexander''s compelled, incriminating statements in imposing sentence.', 'sentencing', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that race and gender, the two factors under examination in Harris (Landray M.', 'general', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we concluded that requiring a defendant to prove his case " ''promotes the policy of finality of judgments and satisfies the purpose of sentence modification, which is the correction of unjust sentences.', 'sentencing', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the discussion above, we concluded that the circuit court did not actually rely on Alexander''s compelled statements when imposing sentence.', 'sentencing', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the court of appeals and affirm the circuit court''s denial of Alexander''s motion for resentencing.', 'sentencing', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that the exception "does not apply to the aural perception of an oral statement privately told to a person.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 119, we held that the exception "does not apply to the aural perception of an oral statement privately told to a person.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bringing these various sources together and condensing a bit, we conclude that an "assertion" as used in Wis.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that an assertion must be intended by the speaker as an expression of a fact, opinion, or condition.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the preferable approach is to include within the meaning of "assertion" in Wis.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Elizabeth''s six statements of Daniel''s threats were hearsay and do not come within any of the exceptions argued by the State, we must decide whether these errors are harmless.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that neither suggests that implicit assertions may not constitute hearsay.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agreed with the defendant that this testimony was hearsay, but we concluded that it fell within the state-of-mind exception, and we went on to conclude the victim''s state of mind was relevant to the State''s theory of the case: the State wanted to prove that her husband had caused her death by chasing her which, because she was afraid of him, caused her to speed to get away from him.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
