INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of conviction for each of the four offenses.', 'general', 'State v. Kutz', 'https://www.courtlistener.com/opinion/1579084/', '1579084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “contrary to .', 'general', 'State v. Reeves', 'https://www.courtlistener.com/opinion/1578082/', '1578082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, we held that “contrary to .', 'general', 'State v. Reeves', 'https://www.courtlistener.com/opinion/1578082/', '1578082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that on the issue of malice aforethought the district court erred by requiring proof of an opportunity to deliberate as a part of the inference arising from the use of a deadly weapon in second-degree murder.', 'general', 'State v. Reeves', 'https://www.courtlistener.com/opinion/1578082/', '1578082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse where the district court has abused that discretion.', 'general', 'State v. Reeves', 'https://www.courtlistener.com/opinion/1578082/', '1578082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is a prerequisite to a claim of ineffective representation on appeal to preserve the testimony of trial counsel.', 'ineffective_assistance', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 111 ("Because we conclude that the record sufficiently establishes that Roberson was not prejudiced by his counsel''s actions, we further conclude that the circuit court did not err in denying Roberson a hearing on his postconviction motion alleging ineffective assistance of trial counsel in accordance with Machner" (citation omitted).', 'ineffective_assistance', 'State v. Danny Robert Alexander', 'https://www.courtlistener.com/opinion/2773475/', '2773475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that trial judges may order a defendant to participate in a drug rehabilitation program pursuant to section 397.', 'general', 'McKendry v. State', 'https://www.courtlistener.com/opinion/1584868/', '1584868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), this Court held that "[t]he plenary power of the legislature to prescribe punishment for criminal offenses cannot be abrogated by the courts in the guise of fashioning an equitable sentence outside the statutory provision.', 'sentencing', 'McKendry v. State', 'https://www.courtlistener.com/opinion/1584868/', '1584868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We find that a mere letter to the Clerk does not sufficiently raise or preserve an issue for appeal.', 'general', 'Sumrell v. State', 'https://www.courtlistener.com/opinion/1588912/', '1588912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, we find that this letter did not act as a pro se brief, nor did it bring or preserve this issue before the Court of Appeals.', 'general', 'Sumrell v. State', 'https://www.courtlistener.com/opinion/1588912/', '1588912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the above facts gleaned from the record, we find that Sumrell did not legitimately raise before the Court of Appeals either of the issues he now attempts to argue before this Court.', 'general', 'Sumrell v. State', 'https://www.courtlistener.com/opinion/1588912/', '1588912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm.', 'general', 'Sumrell v. State', 'https://www.courtlistener.com/opinion/1588912/', '1588912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that if a motion had been made for dismissal of the criminal proceeding after introduction into evidence of the decision of the administrative law judge, the criminal proceeding then should have been dismissed.', 'dismissal', 'People v. Watt', 'https://www.courtlistener.com/opinion/1752595/', '1752595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Accordingly, it is ordered that claimant’s ADC case be reopened retroactively from the date of closure.', 'general', 'People v. Watt', 'https://www.courtlistener.com/opinion/1752595/', '1752595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err in denying appellant’s motion.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2425752/', '2425752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a trial court is not required to give an instruction concerning the burden of proof at the time evidence of unadjudicated offenses and bad acts is admitted.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2425752/', '2425752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellant has failed to preserve error.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2425752/', '2425752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Flemons v. State', 'https://www.courtlistener.com/opinion/4330356/', '4330356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse in part and remand this case to the circuit court for
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'below, we affirm in part and reverse and remand in part.', 'general', 'Lenard v. Kelley', 'https://www.courtlistener.com/opinion/4392310/', '4392310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was harmless because other evidence was sufficient to sustain defendant’s conviction.', 'general', 'People v. Shepherd', 'https://www.courtlistener.com/opinion/848650/', '848650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, on the basis of this overwhelming evidence of the falsity of defendant’s testimony in the fleeing and eluding trial, we conclude that it is clear beyond a reasonable doubt that a reasonable jury would have found defendant guilty of perjury even if the transcript of Butters’s plea to the charge of subornation of perjury had not been admitted.', 'plea', 'People v. Shepherd', 'https://www.courtlistener.com/opinion/848650/', '848650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the admission of the guilty plea transcript was harmless, it is not necessary to address whether the admission of the transcript violated the Confrontation Clause of the United States Constitution, US Const, Am VI, and “it is an undisputed principle of judicial review that questions of constitutionality should not be decided if the *348case may be disposed of on other grounds.', 'plea', 'People v. Shepherd', 'https://www.courtlistener.com/opinion/848650/', '848650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals and remand the matter to the trial court for the reinstatement of the conviction and the sentence.', 'sentencing', 'People v. Shepherd', 'https://www.courtlistener.com/opinion/848650/', '848650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the record before us, we conclude that withdrawal of the plea should have been permitted as fair and just under the circumstances.', 'plea', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although, as we have already noted, the decision whether or not to grant the motion is vested in the sound discretion of the trial court, we conclude that this discretion has been abused.', 'general', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whether brought before or after sentence, these motions are addressed to the sound discretion of the trial court and we reverse only upon a showing of abuse of such discretion.', 'sentencing', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '22 We reverse so that appellant can have the opportunity to put his asserted coercion defense before a jury.', 'general', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed his convictions in an unpublished opinion.', 'general', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'No other error appearing, we affirm.', 'general', 'State v. Foster', 'https://www.courtlistener.com/opinion/2048637/', '2048637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the common-law offense of accessoiy after the fact is not a cognate offense of murder, and we likewise affirm.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth in this opinion, we hold that the common-law offense of accessory after the fact is not a cognate offense of murder, and that the circuit court did not err in refusing to give such a cognate instruction to the jury.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although several arguments in favor of adopting the federal model are attractive, we hold that this is not the case for such a change, largely because defendant was not entitled to an accessory after the fact instruction under our existing cognate lesser jurisprudence.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After the remand, we reversed on the ground that any error was harmless.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '23 Accordingly, we affirm the judgments of the circuit court and the Court of Appeals.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not decide whether to adopt Cohen’s reasoning because we hold that the trial court did not abuse its discretion in making the factual finding that the search of Beaver’s jail cell was not conducted at the direction of the prosecution, and therefore, was necessarily not a search for purposes of the Fourth Amendment.', 'search_seizure', 'Michael D. Tann v. United States', 'https://www.courtlistener.com/opinion/3155943/', '3155943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that an aider and abettor must act with the mens rea required by the specific crime with which the principal is charged and “be an associate in guilt of that crime.', 'general', 'Michael D. Tann v. United States', 'https://www.courtlistener.com/opinion/3155943/', '3155943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '45 We held that “[ijt''Was reasonably foreseeable that intimidation of and threats to witnesses could result in the murder of a witness.', 'general', 'Michael D. Tann v. United States', 'https://www.courtlistener.com/opinion/3155943/', '3155943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2000), we held that “it is only the party who wrongfully procures, a witness’ absence who waives the right to object to the adverse party’s introduction of the witness’ prior out-of-court statements.', 'general', 'Michael D. Tann v. United States', 'https://www.courtlistener.com/opinion/3155943/', '3155943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held in In re R-S- that evidence that the *454defendant displayed a firearm for the purpose of threatening a victim — conduct that was accompanied by verbal threats to the effect that “if you step, out here,, you see what I got” — was sufficient to demonstrate the defendant’s reliance on the op-erability of the firearm.', 'general', 'Michael D. Tann v. United States', 'https://www.courtlistener.com/opinion/3155943/', '3155943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*450• However, we conclude that the trial judge committed instructional error when he told the jury that a.', 'general', 'Michael D. Tann v. United States', 'https://www.courtlistener.com/opinion/3155943/', '3155943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, using any ''test for error, we conclude that appellants were not harmed.', 'general', 'Michael D. Tann v. United States', 'https://www.courtlistener.com/opinion/3155943/', '3155943') ON CONFLICT DO NOTHING;
