INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Eberly', 'https://www.courtlistener.com/opinion/6617553/', '6617553') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon careful review of the record in this matter, we conclude that the trial court did not commit error and, accordingly, affirm.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1201398/', '1201398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that an employer can be held liable under the Acts in question even when nonpayment of an award was not in bad faith, we affirm the ruling of the Superior Court.', 'general', 'National Union Fire Ins. Co. v. McDougall', 'https://www.courtlistener.com/opinion/2084369/', '2084369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm the judgment against National Union on Count IV, we do not reach McDougall’s cross-appeal from the grant of summary judgment for National Union on Counts I — III.', 'general', 'National Union Fire Ins. Co. v. McDougall', 'https://www.courtlistener.com/opinion/2084369/', '2084369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Superior Court.', 'general', 'National Union Fire Ins. Co. v. McDougall', 'https://www.courtlistener.com/opinion/2084369/', '2084369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we affirm.', 'general', 'People v. Putman', 'https://www.courtlistener.com/opinion/2780990/', '2780990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was insufficient evidence presented at the transfer hearing to prove probable cause.', 'probable_cause', 'State v. SONJA B.', 'https://www.courtlistener.com/opinion/1219622/', '1219622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition to there being a lack of probable cause to transfer, we find that there was inadequate consideration given by the court to the statutory factors found in W.', 'probable_cause', 'State v. SONJA B.', 'https://www.courtlistener.com/opinion/1219622/', '1219622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 899, we found that a remand on a transfer hearing was warranted because the court had only made a cursory inquiry into the factors required in subsection (d).', 'general', 'State v. SONJA B.', 'https://www.courtlistener.com/opinion/1219622/', '1219622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the mere refusal to identify oneself to a law enforcement officer does not constitute obstruction under West Virginia Code § 61-5-17(a).', 'general', 'State v. Carney', 'https://www.courtlistener.com/opinion/1217650/', '1217650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This argument fails because, as this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of this matter, we conclude that the evidence upon which the State relied to secure convictions against'' Appellants for obstructing a police officer does not meet the elements required for the statutory offense.', 'general', 'State v. Carney', 'https://www.courtlistener.com/opinion/1217650/', '1217650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the State failed to introduce evidence upon which a jury could properly find Appellants guilty of obstructing a police officer in his official capacity in violation of West Virginia Code § 61-5-17(a), we conclude that the convictions must be reversed.', 'general', 'State v. Carney', 'https://www.courtlistener.com/opinion/1217650/', '1217650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the lower court to sustain the convictions.', 'general', 'State v. Carney', 'https://www.courtlistener.com/opinion/1217650/', '1217650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals, but exercise our discretion to provide such guidance.', 'general', 'State v. Bird', 'https://www.courtlistener.com/opinion/2773040/', '2773040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '{ 27 We affirm the court of appeals'' reversal of Mr.', 'general', 'State v. Bird', 'https://www.courtlistener.com/opinion/2773040/', '2773040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Attorney Inglimo''s professional misconduct requires a three-year suspension of his license to practice law in this state.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this construction is too restrictive a reading of the rule.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that using an illegal drug with clients reflects adversely on an attorney''s fitness as a lawyer.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reason, we conclude that the referee erred in finding no violation of SCR 20:8.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the referee''s finding of marijuana use with T.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the referee''s report and the arguments of the parties, we conclude that a three-year suspension is necessary to protect the public in this case.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the cost amount we approve should not be reduced by one-fifteenth.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the submissions of the parties on the cost issue, we conclude that Attorney Inglimo should be required to pay the full costs of this disciplinary proceeding.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS ORDERED that the license of Michael R.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on the referee''s factual findings, we reverse the referee''s conclusion of no violation on Count 9 and determine that Attorney Inglimo''s possession and use of marijuana in June 2002 with clients EK.', 'general', 'Matter of Disciplinary Proceedings Against Inglimo', 'https://www.courtlistener.com/opinion/2128420/', '2128420') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed, we reverse the orders of the circuit courts dismissing the charges against the Kuenzis.', 'dismissal', 'State v. Kuenzi', 'https://www.courtlistener.com/opinion/8238421/', '8238421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Baby Girl K.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that although the father was incarcerated, he had the opportunity to develop a relationship with his child.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we held that the natural mother had a protected liberty interest.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Kelli established a fundamental liberty interest in parenting the children based on the amount of time she lived with and had custody of her children.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 845, we held that the mother, Jodie, had a fundamental liberty interest in parenting her son, Max.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Jodie had a protected liberty interest in parenting Max.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a fact-finder should consider a parent''s actions throughout the entirety of the child''s life when determining whether he has assumed parental responsibility.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the totality-of-the-circumstances test, a fact-finder may consider whether, during the time the parent was caring for his child, he exposed the child to a hazardous living environment.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that there was sufficient evidence to support the jury''s verdict.', 'general', 'Tammy W-G. v. Jacob T.', 'https://www.courtlistener.com/opinion/8238453/', '8238453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that dual convictions of aggravated battery with a deadly weapon and attempted second-degree murder for a single act of stabbing or shooting a victim do not violate double jeopardy.', 'general', 'State v. Florida', 'https://www.courtlistener.com/opinion/7830908/', '7830908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that convictions of attempted first-degree murder, felony causing bodily injury, and aggravated battery causing great bodily harm were authorized for the defendant’s act of shooting the victim during a robbery.', 'general', 'State v. Florida', 'https://www.courtlistener.com/opinion/7830908/', '7830908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in Sirmons that dual convictions of armed robbery and grand theft of an automobile were unauthorized because “these offenses are merely degree variants of the core offense of theft.', 'general', 'State v. Florida', 'https://www.courtlistener.com/opinion/7830908/', '7830908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that each offense contained an element not contained in the others, and that none of the three exceptions to the presumption of multiple convictions in section 775.', 'general', 'State v. Florida', 'https://www.courtlistener.com/opinion/7830908/', '7830908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001), we held that convictions as charged of attempted first-degree murder with a firearm and aggravated battery causing great bodily harm did not cause a double jeopardy violation.', 'general', 'State v. Florida', 'https://www.courtlistener.com/opinion/7830908/', '7830908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred when it entered judgment in favor of Providence.', 'general', 'RSI Bank v. Providence Mut. Fire Ins. Co.', 'https://www.courtlistener.com/opinion/8264592/', '8264592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court improperly enforced the indemnification provision and entered judgment in Providence''s favor.', 'general', 'RSI Bank v. Providence Mut. Fire Ins. Co.', 'https://www.courtlistener.com/opinion/8264592/', '8264592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Appellate Division''s judgment and remand the matter to the trial court for further proceedings.', 'general', 'RSI Bank v. Providence Mut. Fire Ins. Co.', 'https://www.courtlistener.com/opinion/8264592/', '8264592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record established circumstances rendering obtaining a warrant impractical and that the warrantless search is justified under the exigency exception to the Fourth Amendment’s warrant requirement.', 'search_seizure', 'Cole v. State', 'https://www.courtlistener.com/opinion/5446855/', '5446855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the totality of the circumstances, we conclude that law enforcement reasonably believed that obtaining a warrant in this ease would have significantly undermined the efficacy of searching Cole’s blood.', 'general', 'Cole v. State', 'https://www.courtlistener.com/opinion/5446855/', '5446855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Cox is not similarly situated to someone who violates the theft-by-check statute, we hold that the different penalties for violations of the theft-by-check statute and the dishonored-check statute do not deny Cox equal pro-teetion of the law.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 839 (stating also that “[b]ecause we conclude that Frazier is not similarly situated to someone who violates RICO, we hold that the different penalties for violations of the [two statutes at issue] do not deny equal protection”) (Anderson, Paul H.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “[a] statute violates the equal protection clause when it prescribes different punishments or different degrees of punishment for the same conduct committed under the same circumstances by persons similarly situated.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Cox has not made this showing, it is not necessary to determine whether Cox has also established that the disparity in sentencing between the theft-by-check and dishonored-check statutes fails the rational basis test under the Minnesota Constitution.', 'sentencing', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was no equal-protection violation because the statutes did not prohibit the same acts, and “[t]he mere fact that those who steal property of a greater value under like circumstances may be subject to a lesser penalty does not affect defendants.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude appellant, who has been charged with writing a dishonored check, is not similarly situated for equal-protection purposes to a person who commits theft by check, we affirm.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Kuhlmann did not validly waive his right to a jury trial on the previous-conviction elements of the charged offenses.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the error did not affect Kuhl-mann’s substantial rights, we need not consider whether the error was plain, or whether the error seriously affects the fairness and integrity of the judicial proceedings.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 455, we held that if a defendant wanted to have an entrapment defense decided by the court, and not the jury, the defendant "must in open court or in writing waive a juiy trial as to that issue.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s failure to obtain Kuhlmann’s personal waiver of his right to a jury trial on the *852previous-conviction elements of the charged offenses does not amount to structural error.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court’s failure to obtain a personal waiver in this case falls into the category of “trial errors” occurring in the prosecution of the case, rather than a defect in the constitution of the trial mechanism.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the error should be reviewed for plain error.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain error standard is not met because the error did not affect Kuhlmann’s substantial rights.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the previous DWI conviction was an element of the aggravated DWI offense, meaning that “the prior conviction is an element which the state must prove at trial and which defendant has a right to have a jury decide.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pietraszewski, in which we concluded that, although the trial court should have questioned the defendant more thoroughly when the defendant made his on-the-record expression of his waiver to a jury trial, the defendant had effectively waived his right to a jury trial because there was “sufficient evidence in the entire record from which the trial court could have determined that the defendant’s waiver was voluntarily and intelligently made.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2010), in which we concluded that a defen*850dant can be said to have acquiesced to his counsel’s strategy to concede guilt on an element of an offense despite the absence of a personal, on-the-record consent to such a strategy.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that waiver was sufficiently established, explaining that “[wjhile we intended [in Grilli] to make it clear that the waiver should be by defendant, not by his counsel, in this case defendant was present when his counsel made the waiver and defendant may well be said to have ratified the waiver and made it his personal act.', 'general', 'State v. Kuhlmann', 'https://www.courtlistener.com/opinion/8280402/', '8280402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the significant fact was that the defendant knew his conduct — reckless *595driving in a residential neighborhood— might injure or kill others.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/8280438/', '8280438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the defendant’s purpose was enough to make the sixth person a victim of the crime of tampering with a witness, and we permitted six sentences, notwithstanding the fact that the sixth “victim” was unaware of the firebombing at the time it occurred.', 'sentencing', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/8280438/', '8280438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, concluding that the multiple-victim exception did not apply when the crime for which the defendant was convicted — being an accomplice after the fact — was a victimless crime.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/8280438/', '8280438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because there is evidence in the record to support the finding, we hold that the referee’s finding is not clearly erroneous.', 'general', 'In re Disciplinary Action Against Fett', 'https://www.courtlistener.com/opinion/8279898/', '8279898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we hold that it was not clear error for the referee to conclude that Fett violated Minn.', 'general', 'In re Disciplinary Action Against Fett', 'https://www.courtlistener.com/opinion/8279898/', '8279898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with our precedent on using an attorney’s disciplinary history as an aggravating factor in determining an appropriate sanction and Fett’s uncontested disciplinary history, we hold that it was not clear error for the referee to conclude that Fett’s disciplinary history was an aggravating factor in determining the appropriate sanction.', 'general', 'In re Disciplinary Action Against Fett', 'https://www.courtlistener.com/opinion/8279898/', '8279898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was not clear error for the referee to conclude that Fett’s experience in the practice of law, and Fett’s experience in the practice of elder law in particular, is an aggravating factor in determining the appropriate sanction.', 'general', 'In re Disciplinary Action Against Fett', 'https://www.courtlistener.com/opinion/8279898/', '8279898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the referee did not err in his findings of fact and conclusions of law, and we publicly reprimand Fett and place him on unsupervised probation for a period of 1 year.', 'general', 'In re Disciplinary Action Against Fett', 'https://www.courtlistener.com/opinion/8279898/', '8279898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the referee’s conclusions are not clearly erroneous.', 'general', 'In re Disciplinary Action Against Fett', 'https://www.courtlistener.com/opinion/8279898/', '8279898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the referee’s finding was not clearly erroneous.', 'general', 'In re Disciplinary Action Against Fett', 'https://www.courtlistener.com/opinion/8279898/', '8279898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the referee’s finding that Fett failed to communicate was not clearly erroneous.', 'general', 'In re Disciplinary Action Against Fett', 'https://www.courtlistener.com/opinion/8279898/', '8279898') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having thoroughly considered the parties’ briefs, relevant portions of the appendix record, oral argument and relevant law, we find that Mr.', 'general', 'State v. Garner', 'https://www.courtlistener.com/opinion/8219351/', '8219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse this ease and remand for a new trial.', 'general', 'State v. Garner', 'https://www.courtlistener.com/opinion/8219351/', '8219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing analysis, we reverse this case and remanded for a new trial consistent with this opinion.', 'general', 'State v. Garner', 'https://www.courtlistener.com/opinion/8219351/', '8219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that movant failed to sustain the burden of showing grounds for relief, by a preponderance of the evidence, as required by Rule 27.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/5249988/', '5249988') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/5249988/', '5249988') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a reasonable inference of Smith''s guilt could have been drawn by the jury from the evidence presented at trial, viewed in its entirety, we hold that the evidence was sufficient to sustain the conviction and agree with the court of appeals'' decision in that regard.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/8238750/', '8238750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Smith did not waive his constitutional right to a jury determination of the drug quantity.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/8238750/', '8238750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we are bound by the sound and well-reasoned opinions of the United States Supreme Court in Neder and our own court in Harvey, and because we decline to sever our statutory protection for jury trials from the constitutional provisions upon which it is based, we conclude that the circuit court''s determination of the drug quantity involved in Smith''s offense, a fact which should have been submitted to the jury, is subject to harmless error review.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/8238750/', '8238750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals and reinstate the guilty verdict and judgment of conviction.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/8238750/', '8238750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the error was harmless, we reverse the court of appeals and reinstate Smith''s guilty verdict and judgment of conviction.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/8238750/', '8238750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“If the three prongs of the plain error test are met, we may reverse if we conclude that reversal is required to ensure fairness and the integrity of the judicial proceedings.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the district court’s instructions did not follow the clear statutory language, we conclude that the error was plain.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because whether Gunderson knew that his conduct was prohibited was closely contested by both parties, because Gunderson submitted evidence that tended to negate that element of the crime, and because there is a reasonable likelihood that a properly instructed jury could have accepted Gunderson’s argument, we conclude that the error had a significant efféct on the jury’s verdict and affected Gunderson’s substantial rights.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the erroneous instructions allowed the jury to ignore a significant portion of Gunderson’s argument, we conclude that reversal of Gun-derson’s conviction and remand for a new trial is necessary.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, although we conclude that the record may contain sufficient evidence to sustain the conviction, because the jury was denied the opportunity to weigh the conflicting evidence based on the proper instruction, we reverse and remand for a new trial.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court committed plain error when it failed to properly instruct the jury that, to convict, it must find not only that Gunderson knew- of the OFP but also that in entering his mother’s ten-acre parcel, her detached garage, or his shed, he knowingly violated the prohibition in the OFP.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because not instructing the jury that it must find a knowing violation of the HRO is plain error and because there is a reasonable likelihood that the error had a significant effect on the jury’s decision, we reverse appellant’s conviction and remand for a new trial.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the erroneous instruction affected Gunderson’s substantial rights by impacting the outcome of the trial, we reverse and remand for a new trial.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse and remand on the jury-instruction issue, we decline to address Gunderson’s argument that the district court erred when accepting the stipulation to his prior convictions without securing a formal waiver of his right to a jury trial on that element of felony violation of an:HRO.', 'general', 'State v. Gunderson', 'https://www.courtlistener.com/opinion/8280506/', '8280506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that his claims lack merit, we affirm appellant’s conviction.', 'general', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed all of the confidential social services documents in the record, we conclude that the district court did not abuse its discretion in limiting access to the social services records.', 'general', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion in ruling inadmissible evidence that M.', 'general', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion in excluding this evidence.', 'general', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When viewed in a light most favorable to the State, we conclude that the boyfriend’s testimony permitted the jury to reasonably conclude that the State proved beyond a *354reasonable doubt that appellant committed an intentional act of unreasonable force that was excessive under the circumstances when he threw 8-month-old Nicholas on a bed in a “harsh” manner.', 'general', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the State presented sufficient circumstantial evidence that appellant committed malicious punishment against Nicholas when he was 10 and 12 months old.', 'general', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More precisely, do the circumstances proved support a rational hypothesis that appellant did not commit malicious punishment against Nicholas when he was 10 and 12 months old? We conclude that they do not.', 'general', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When viewed as a whole, we conclude that the district court’s jury instructions fairly and correctly state the applicable law.', 'jury_instruction', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”5 Thus, we conclude that the court did not err in its jury instruction on the element of a past pattern of child abuse.', 'jury_instruction', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that the jury instructions given were not erroneous, much less plainly erroneous.', 'jury_instruction', 'State v. Hokanson', 'https://www.courtlistener.com/opinion/8280798/', '8280798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Minn.', 'general', 'State v. Rick', 'https://www.courtlistener.com/opinion/8280804/', '8280804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the language of section 609.', 'general', 'State v. Rick', 'https://www.courtlistener.com/opinion/8280804/', '8280804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2(2), does not unambiguously apply to acts of sexual penetration, and because sexual penetration was the only method of sperm transfer proved by the state at trial, we reverse Rick’s conviction under section 609.', 'general', 'State v. Rick', 'https://www.courtlistener.com/opinion/8280804/', '8280804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court violated Medina''s Fifth and Sixth Amendment rights when it entered its own conviction and sentence for a class 4 felony instead of determining the punishment warranted by the jury''s guilty verdict for the class 5 felony.', 'sentencing', 'Medina v. People', 'https://www.courtlistener.com/opinion/5324896/', '5324896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that the jury instructions were appropriate and that the plain error standard of review described in Neder and Griego for misdescribed or omitted elements in jury instructions does not apply.', 'jury_instruction', 'Medina v. People', 'https://www.courtlistener.com/opinion/5324896/', '5324896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we affirm Medina''s conviction for the class 5 felony, vacate Medina''s sentence for the class 4 felony, and remand this case to the court of appeals to be returned to the trial court for resentencing on the class 5 felony conviction.', 'sentencing', 'Medina v. People', 'https://www.courtlistener.com/opinion/5324896/', '5324896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm Medina''s conviction, vacate her sentence, and remand her case to the court of appeals to return the case to the trial court for resentencing on the jury''s class 5 felony accessory conviction.', 'sentencing', 'Medina v. People', 'https://www.courtlistener.com/opinion/5324896/', '5324896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we affirm Medina''s convietion for the class 5 felony, vacate Medina''s sentence for the class 4 felony, and remand this case to the court of appeals to be returned to the trial court for resentencing on the class 5 felony conviction.', 'sentencing', 'Medina v. People', 'https://www.courtlistener.com/opinion/5324896/', '5324896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the findings of the Hearing Committee and impose the sanction it recommended.', 'general', 'A v. Idaho State Bar', 'https://www.courtlistener.com/opinion/5342014/', '5342014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the determination that Defendant A did not violate Idaho Code § 63-3076.', 'general', 'A v. Idaho State Bar', 'https://www.courtlistener.com/opinion/5342014/', '5342014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the finding of the Hearing Committee that Defendant A violated Rule 8.', 'general', 'A v. Idaho State Bar', 'https://www.courtlistener.com/opinion/5342014/', '5342014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the terms of Minnesota’s civil commitment statute, we hold that appellants’ commitments were civil causes of action subject to Congress’ express grant of civil jurisdiction under section 1360(a), and that the district court therefore had jurisdiction to commit appellants.', 'general', 'In re the Civil Commitment of Johnson', 'https://www.courtlistener.com/opinion/8280180/', '8280180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Minnesota has jurisdiction to commit appellants, we affirm.', 'general', 'In re the Civil Commitment of Johnson', 'https://www.courtlistener.com/opinion/8280180/', '8280180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the commitment statute requires a judicial determination of the condition of private individuals, we conclude that it is more akin to the laws of “contract, tort, marriage, divorce, insanity, [or] descent,” than to an assertion of sovereignty like “the power to tax [or] grant franchises.', 'general', 'In re the Civil Commitment of Johnson', 'https://www.courtlistener.com/opinion/8280180/', '8280180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, in light of the exceptionally strong State interests presented, the fact that Congress has not pervasively regulated this area of the law, and the minimal intrusion on tribal sovereignty, we conclude that Minnesota’s enforcement of chapter 253B is not preempted.', 'general', 'In re the Civil Commitment of Johnson', 'https://www.courtlistener.com/opinion/8280180/', '8280180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the state has jurisdiction to civilly commit appellants.', 'general', 'In re the Civil Commitment of Johnson', 'https://www.courtlistener.com/opinion/8280180/', '8280180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that this factor, at most, weighs slightly in favor of a determination that the legislature did not intend for the same conduct to be punished under both statutes.', 'general', 'Llorens v. State', 'https://www.courtlistener.com/opinion/5448413/', '5448413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the jury had sufficient evidence to find Marshall guilty of impeding Shawne’s normal breathing, the third-degree felony assault.', 'general', 'Marshall v. State', 'https://www.courtlistener.com/opinion/5446288/', '5446288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because knowledge that the instrument is forged is an element which is strongly implied in the statutory definition of forgery, we hold that its absence in an indictment is a matter which may be raised by a motion to quash, but may not be raised for the first time after trial has commenced.', 'general', 'Okonkwo, Chidiebele Gabriel', 'https://www.courtlistener.com/opinion/2948172/', '2948172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the prosecution failed to meet that burden, we reverse and render Shotts’s conviction.', 'general', 'Shotts v. City of Madison', 'https://www.courtlistener.com/opinion/5008838/', '5008838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”46 We hold that the *542trial judge did not err in his instructions concerning a unanimous jury verdict.', 'general', 'Landrian v. State', 'https://www.courtlistener.com/opinion/1488121/', '1488121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not err.', 'general', 'Landrian v. State', 'https://www.courtlistener.com/opinion/1488121/', '1488121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold on this record, given the protected nature of what Crudup intends to elicit, that the DA’s selective disclosure of the prosecution file, while waiving the privilege as to the documents themselves, does not waive the DA’s testimonial work-product privilege regarding the prosecutor’s mental processes;', 'general', 'In Re Bexar County Criminal District Attorney''s Office', 'https://www.courtlistener.com/opinion/894858/', '894858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence in this case was legally insufficient to support the conviction for engaging in organized criminal activity.', 'general', 'Hart v. State', 'https://www.courtlistener.com/opinion/1353950/', '1353950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals’s judgment in part, render a verdict of guilt for theft of property valued greater than $20,000 but less than $100,000, and remand the case to the trial court for a new punishment determination.', 'general', 'Hart v. State', 'https://www.courtlistener.com/opinion/1353950/', '1353950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury in this case was not required to unanimously agree on any of these theories.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1401703/', '1401703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We conclude that it did not.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Mata timely informed the trial court of his grounds with sufficient specificity and, therefore, that he preserved error.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given McDougall’s inconsistent testimony, along with the single breath test conducted over two hours after the driving, we conclude that, in this case, the State failed to prove by clear and convincing evidence that McDougall’s retrograde extrapolation was reliable.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the testimony, we find that, while McDougall’s testimony indicates a general understanding of the BAC curve and the concepts of absorption and elimination, it reflects failure to explain the theory to the court with any clarity.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the factors in this case weigh against a finding of reliability.', 'general', 'Mata v. State', 'https://www.courtlistener.com/opinion/1560546/', '1560546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Because the dis-positive issue here is one of jurisdiction, we hold that its determination is not procedurally defaulted by [defendant’s] failure to raise it.', 'general', 'Karenev v. State', 'https://www.courtlistener.com/opinion/1578755/', '1578755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), we held that "a trial court has jurisdiction to revoke deferred adjudication probation imposed pursuant to Article 42.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and remand the case to that court so that it may address appellant’s remaining point of error.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nunfio, we held that the question “can you be fair and impartial if the victim in this case is a nun?” was a proper question and the trial court erred to prohibit Nunfio’s asking the question.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Abron, we held that the trial court abused its discretion in prohibiting the defendant from asking the venire members whether they would be biased because the defendant was a black man and the victim a white woman.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*41In Hernandez, we held that the defendant should have been allowed to ask whether venire members could not believe that a police officer would lie.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “a vague question about “what things’ the veniremember thought were important in determining whether an individual should receive a death sentence, wholly unrelated to the sentencing scheme, amounts to a fishing expedition going beyond the scope of proper voir dire.', 'sentencing', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant faded to show a juror had withheld information because defense counsel’s questions had been inadequate.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did not because the question was too vague to constitute a proper question.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the question was a proper one and in a proper form because the defendant was not seeking to commit the venire to a conclusion based on a given set of facts.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Standefer we held that “a question is a commitment question if one or more of the possible answers is that the prospective juror would resolve or refrain from resolving an issue in the case on the basis of one or more facts contained in the question.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We hold that subsections (a)(4) and (7) do implicate First Amendment freedoms.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2274154/', '2274154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the July 11, 2006 information against Scott was brought under § 42.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2274154/', '2274154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '07(a)(4), we conclude that it is not susceptible of application to communicative conduct that is protected by the First Amendment.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2274154/', '2274154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '07(a)(4), we find that, given the allegations in the charging instruments, the relevant portion of (a)(4) reads as follows: “A person commits an offense if, with intent to harass, annoy, alarm, abuse, torment, or embarrass another, he .', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2274154/', '2274154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2274154/', '2274154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgments of the court of appeals and affirm the judgments of the trial court.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2274154/', '2274154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when a trial court submits a single broad-form liability question incorporating multiple theories of liability, the error is harmful and a new trial is required when the appellate court cannot determine whether the jury based its verdict on an improperly submitted invalid theory.', 'general', 'Bagheri v. State', 'https://www.courtlistener.com/opinion/2170594/', '2170594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the sufficiency of the evidence to support conviction under an impairment theory does not alone establish that the error in admitting a flawed retrograde extrapolation analysis was harmless.', 'general', 'Bagheri v. State', 'https://www.courtlistener.com/opinion/2170594/', '2170594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We hold that finding error in the court’s charge to the jury begins — not ends — the inquiry;', 'general', 'Posey v. State', 'https://www.courtlistener.com/opinion/2377590/', '2377590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statute embodies two standards of review.', 'general', 'Posey v. State', 'https://www.courtlistener.com/opinion/2377590/', '2377590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 243, however, in addressing the burden of persuasion required of the proponent of posthypnotic testimony, we held that because of the “uncertainties inherent” in the evidence, “it [was] appropriate to require the proponent of such [evidence] to demonstrate .', 'general', 'Kelly v. State', 'https://www.courtlistener.com/opinion/2430249/', '2430249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Is the Frye general acceptance test still a part of Texas law? We conclude that it is not.', 'general', 'Kelly v. State', 'https://www.courtlistener.com/opinion/2430249/', '2430249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing that evidence in the light most favorable to the trial court’s decision, we conclude that it was demonstrated by clear and convincing evidence that the scientific principle underlying the RFLP technique was valid, that the RFLP technique itself was valid, that the technique was properly applied in this case, and that the related population frequency studies were also valid and reliable.', 'general', 'Kelly v. State', 'https://www.courtlistener.com/opinion/2430249/', '2430249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that the order was sufficiently specific to give rise to a personal duty on Chambers’ part to obey it, we grant his petition for writ of habeas corpus because we find that he has conclusively proven that the corporation was unable to comply with the order.', 'habeas', 'Ex Parte Chambers', 'https://www.courtlistener.com/opinion/2432565/', '2432565') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we find that Chambers has established IBS’s inability to comply defense, it is unnecessary to address his remaining points.', 'general', 'Ex Parte Chambers', 'https://www.courtlistener.com/opinion/2432565/', '2432565') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In response to the defendant’s statute of limitations claim in Schmidt, we said simply ”[t]his Court has dealt with a similar contention in [Ward], and in that case we held that this was a matter of defense which should be decided in the courts of the demanding state.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/2433594/', '2433594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in line with the precedents, other than Rubio, cited previously, we hold that the non-accomplice evidence adduced at appellant’s trial was sufficient to satisfy the accomplice witness rule.', 'general', 'Gill v. State', 'https://www.courtlistener.com/opinion/2433114/', '2433114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that that evidence was sufficient to satisfy the accomplice witness rule, although the defendant’s possession of the stolen items was not shown to have been exclusive.', 'general', 'Gill v. State', 'https://www.courtlistener.com/opinion/2433114/', '2433114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lucas, Cherb, and Alexander, we held that the non-accomplice evidence tended to connect the defendants to the offenses committed despite the fact that the defendants’ possession of the stolen items was joint rather than exclusive.', 'general', 'Gill v. State', 'https://www.courtlistener.com/opinion/2433114/', '2433114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE the judgment of the court of appeals and AFFIRM the judgment of the trial court.', 'general', 'Gill v. State', 'https://www.courtlistener.com/opinion/2433114/', '2433114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that not only did the State fail to provide evidence establishing the appellant''s exclusive or joint possession and control of the fruits of the burglary of the Pea Patch, but failed to produce any evidence tending to connect him to the commission of the burglary of the Pea Patch.', 'general', 'Gill v. State', 'https://www.courtlistener.com/opinion/2433114/', '2433114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant was dangerous to only some, but not all, of her own newborn children, which she would not likely have during her child-bearing years in prison, so the jury could not rationally find that the defendant was a future danger.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), we held that “[t]he procedural mechanisms for reviewing that *906conviction are not a vested and substantive right.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have listened to appellant’s recorded statement, and while we find that a word here or there might be inaudible, we do not find any inaudible portion of appellant’s recorded statement is necessary to the resolution of this appeal or to any understanding of the context of the exchange between appellant and the police.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the Berry case, this Court held that the jury was irrational to conclude that there was a probability that Kinesha Berry would be a future danger.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 In Berry, we held that the evidence was legally insufficient to establish that there was a probability that the defendant — a mother who had killed one new-born child and abandoned a second one — would commit criminal acts of violence that would constitute a continuing threat to society.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”3 Using that legal standard, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record is insufficient to establish that the provisions of the IADA were violated because it does not demonstrate that the trial court abused its discretion to grant the State’s November 4th request for a continuance under Article IV, Section (c).', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2541435/', '2541435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 Taking a slightly different tack, however, we reverse the court of appeals’s judgment with respect to this point of error and remand the cause for consideration of the appellant’s remaining points of error on direct appeal.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2541435/', '2541435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it was objectively reasonable for the officer to conclude that Heriberto’s general consent to come inside the apartment to talk to Erica included consent to walk down the open hallway to knock on the bathroom door.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, we conclude that a reasonable person would have believed that the officers had authority to conduct a full search of Starr’s home including his closet and a roll of film;', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') ("Given the evidence regarding the initial traffic stop and the arrival of the drug-detection dog, all of which shows that the dog arrived within eight minutes of the traffic stop and before Wing-field finished conducting normal procedures for a traffic stop, we conclude that the record supports an implied finding by the trial court that the time it took for the dog to arrive did not prolong the initial stop beyond the time reasonably required to complete the mission of the stop.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Weaver’s consent, we affirm the judgment of the trial court and that of the court of appeals.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/2546485/', '2546485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we ultimately disagree with its application of the objective standard, which we address in the State’s second ground for review, we hold that the court of appeals did properly employ an objective standard to evaluate counsel’s performance.', 'general', 'Okonkwo, Chidiebele Gabriel', 'https://www.courtlistener.com/opinion/2948172/', '2948172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the entire record, we hold that the court of appeals erred in determining that the trial court abused its discretion.', 'general', 'Okonkwo, Chidiebele Gabriel', 'https://www.courtlistener.com/opinion/2948172/', '2948172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to these two grounds, we conclude that, under an objective standard, appellant’s counsel was not unreasonable in failing to request the instruction.', 'general', 'Okonkwo, Chidiebele Gabriel', 'https://www.courtlistener.com/opinion/2948172/', '2948172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did.', 'general', 'Okonkwo, Chidiebele Gabriel', 'https://www.courtlistener.com/opinion/2948172/', '2948172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the record in this case, we conclude that counsel was not objectively unreasonable by failing to request an instruction on mistake of fact because that theory was inconsistent with a theory that counsel advanced at trial, and it would have misled the jury as to the State’s burden of proof.', 'general', 'Okonkwo, Chidiebele Gabriel', 'https://www.courtlistener.com/opinion/2948172/', '2948172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and render a judgment affirming the judgment of the trial court.', 'general', 'Okonkwo, Chidiebele Gabriel', 'https://www.courtlistener.com/opinion/2948172/', '2948172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 498 (stating that “[bjased on the foregoing, we conclude that the Illinois offense of Contributing to the Sexual Delinquency of a Child is ‘substantially similar’ to the Texas offense of Indecency with a Child and constitutes an offense that qualifies a parolee for sex-offender conditions”).', 'general', 'Crabtree, Mark Alan', 'https://www.courtlistener.com/opinion/2945915/', '2945915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At least under these circumstances,47 we hold that the court of appeals was correct to credit the trial judge’s recollection as it related to the question of whether the missing record was necessary to the resolution of the appeal.', 'general', 'Nava, Andres Maldonado', 'https://www.courtlistener.com/opinion/2947272/', '2947272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the charge as a whole, and from a common-sense perspective, and in the context of the rest of the trial, we conclude that the jury most likely understood the application paragraph in question in a manner consistent with the law.', 'general', 'Nava, Andres Maldonado', 'https://www.courtlistener.com/opinion/2947272/', '2947272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we concluded that similar language in the attempt statute required the actor to possess intent with respect to the result even if the object crime did not itself require intent with respect to the result:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding against appellants on both issues, we affirm.', 'general', 'Nava, Andres Maldonado', 'https://www.courtlistener.com/opinion/2947272/', '2947272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Nava, Andres Maldonado', 'https://www.courtlistener.com/opinion/2947272/', '2947272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, we hold that the court of appeals properly determined that the trial court’s instruction on the definition of “foreign legal consultant” was not an improper comment on the weight of the evidence.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the charge properly instructed the jury as to the “foreign legal consultant” criteria within the definition of “in good standing.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, in which we held that the felony-murder statute6 did not require a culpable mental state, we stated that “[i]t is significant and largely dispositive that [the felony-murder subsection] omits a culpable mental state while the other two subsections in [that section] expressly require a culpable mental state.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Interpreting the Closed Meeting Act,8 we held that it *426did not require proof of a mental state with respect to whether a closed meeting was statutorily prohibited, although it did expressly prescribe a mental state as to other elements.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “a culpable mental state applies to whether the defendant knew his use of the motor vehicle was without the effective consent of the owner.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, in which this Court held that criminal liability may be imposed without proof of a culpable mental state for certain types of conduct that place upon a person a duty to understand and comply with applicable legal requirements.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that the offense of holding oneself out as a lawyer required proof of a culpable mental state beyond intent to obtain an economic benefit.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that appellant was not entitled to an instruction on a mistake-of-fact defense because his requested instruction did not negate the culpability required for the offense.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain language of the false-lawyer statute requires proof of a mental state only as to the economic-benefit element and plainly dispenses with any additional culpable-mental-state requirement.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in this case, the Legislature intended to limit the mental-state requirement to the economic-benefit element and to dispense with it as to the other statutory elements.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '28 We held that he was not entitled to the defense because “[e]ven if [the defendant] did form, through mistake, a belief that the booth was not a public place, such mistake of fact could not be a defense since there is no requirement that a defendant know that the location where the act was performed was a public place.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the offense of capital murder by killing a peace officer includes the element that the peace officer was “acting in the lawful discharge of an official duty,”32 we held that the defendant was not entitled to *439a mistake of fact defense because, among other things, “the defendant need not know that specific fact,” and so, the mistake “would not negate the required culpability for capital murder.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,61 in which this Court held that a mistake-of-fact defense applied in an unauthorized use of a motor vehicle case when the defendant claimed that he had consent to drive what he mistakenly believed was Tim Eden’s motorcycle.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Dr.', 'general', 'Celis, Mauricio Rodriguez', 'https://www.courtlistener.com/opinion/2948210/', '2948210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”26 We conclude that the trial court’s resolution of this faetu*228al/credibility dispute between the parties— that the appellant’s invitation was not limited to food — is supported by the record.', 'general', 'Baird v. State', 'https://www.courtlistener.com/opinion/2948278/', '2948278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '35 If, having implemented these basic canons of statutory construction, we find that the statutory language is plain on its face, we are ordinarily constrained to adhere to the plain import of that statutory language, regarding it as the definitive indicium of the legislative intent.', 'general', 'Baird v. State', 'https://www.courtlistener.com/opinion/2948278/', '2948278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the court of appeals.', 'general', 'Baird v. State', 'https://www.courtlistener.com/opinion/2948278/', '2948278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the search in this .', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We consider each of these contentions in turn and, finding them to be without merit, we hold that none of these established exceptions to the warrant requirement categorically applies to except the warrantless, nonconsensual testing of a suspect’s blood pursuant to the provisions in the Transportation Code.', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the provisions in the Transportation Code do not, taken by themselves, form a constitutionally valid alternative to the Fourth Amendment warrant requirement.', 'search_seizure', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a nonconsensual search of a DWI suspect’s blood conducted pursuant to the mandatory-blood-draw and implied-consent provisions in the Transportation Code, when undertaken in the absence of a warrant or any applicable exception to the warrant requirement, violates the Fourth Amendment.', 'search_seizure', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addressing the merits of the State’s challenge to the trial court’s ruling, we conclude that the warrantless, nonconsen-sual testing of a DWI suspect’s blood does not categorically fall within any recognized exception to the Fourth Amendment’s warrant requirement, nor can it be justified under a general Fourth Amendment balancing test.', 'search_seizure', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the State’s specific complaints regarding the court of appeals’s analysis, we conclude that, although the court of appeals erred by determining that the State forfeited its implied-consent argument on appeal through stipulatioii, rem''and is unnecessary in light of both the.', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these principles, we conclude that the special-needs doctrine is inapplicable in the present context, when the search of a DWI suspect’s blood is undertaken by law-enforcement officers for the primary purpose of generating evidence to be used in a criminal prosecution.', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these considerations, we conclude that the search-incident-to-arrest exception is inapplicable.', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Knights and Samson, we conclude that there is no rational comparison between the .', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1477 (1946), we find that principle to be inapplicable here.', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Neither did we hold that police must always secure a search warrant to do so.', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '-Texarkana 2010) ("In order to prevent the term ''present'' from being rendered meaningless, we conclude that ''present'' under Section 32.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'violation, and we affirmed.', 'general', 'State v. Villarreal, David', 'https://www.courtlistener.com/opinion/2948963/', '2948963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '055 punishes what would otherwise be innocent behavior — moving to a new address [without giving proper notification]— under the circumstances that the person is a registered sex offender, we conclude that the statute creates a ‘circumstances surrounding the conduct’ offense.', 'general', 'Robinson, Leo Demory', 'https://www.courtlistener.com/opinion/2950353/', '2950353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that no rational juror could have found that appellant’s conduct constituted a use of force against a peace officer as required by the resisting-arrest statute, we hold that the evidence is insufficient to sustain appellant’s conviction.', 'general', 'Dobbs, Atha Albert', 'https://www.courtlistener.com/opinion/2949403/', '2949403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because he did not use force “against” a peace officer within the meaning of the resisting-arrest statute, we hold that the evidence is insufficient to sustain appellant’s conviction.', 'general', 'Dobbs, Atha Albert', 'https://www.courtlistener.com/opinion/2949403/', '2949403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding the meanings of these statutory terms plain and reading them in conjunction with the other statutory terms, we conclude that the Legislature would have understood the phrase “using force against the peace officer or another” as meaning violence or physical aggression, or an immediate threat thereof, in the direction of and/or into contact with, or in opposition or hostility to, a peace officer or another.', 'general', 'Dobbs, Atha Albert', 'https://www.courtlistener.com/opinion/2949403/', '2949403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a use of force “against” an officer must necessarily be in opposition to, or in the direction of and/or in contact with, the officer himself, meaning the officer’s physical person.', 'general', 'Dobbs, Atha Albert', 'https://www.courtlistener.com/opinion/2949403/', '2949403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the facts of this case, we conclude that the evidence is insufficient to sustain appellant’s resisting-arrest conviction.', 'general', 'Dobbs, Atha Albert', 'https://www.courtlistener.com/opinion/2949403/', '2949403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and render a judgment of acquittal.', 'general', 'Dobbs, Atha Albert', 'https://www.courtlistener.com/opinion/2949403/', '2949403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all of these Almanza factors, we hold that the error in the jury charge both affected the very basis of the case and deprived the appellant of a valuable right, ultimately depriving him of a fair and impartial trial.', 'general', 'Hollander, Joe Shawn', 'https://www.courtlistener.com/opinion/2947320/', '2947320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For two reasons, we conclude that this was a mistake.', 'general', 'Hollander, Joe Shawn', 'https://www.courtlistener.com/opinion/2947320/', '2947320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgments of the court of appeals and the trial court and remand the cause for a new trial.', 'general', 'Hollander, Joe Shawn', 'https://www.courtlistener.com/opinion/2947320/', '2947320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that criminal trespass can be a lesser-included offense of burglary.', 'general', 'State of Texas v. Meru, Mark', 'https://www.courtlistener.com/opinion/2947337/', '2947337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After doing a statutory comparison of the three offenses, we held that although racing and speeding are not necessarily lesser included offenses of reckless driving, in this case they were because the indictment charging the offense of reckless driving specifically alleged racing and speeding and the proof at trial showed racing and speeding.', 'general', 'State of Texas v. Meru, Mark', 'https://www.courtlistener.com/opinion/2947337/', '2947337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More than thirty years later, this Court held in Salazar v.', 'general', 'State of Texas v. Meru, Mark', 'https://www.courtlistener.com/opinion/2947337/', '2947337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, even though manslaughter does not include the elements required for establishing murder, that a defendant act "with intent to cause serious bodily injury to an individual” and "commit an act clearly dangerous to human life,” this Court held that the lesser offense of manslaughter was functionally equivalent to the greater offense of murder because the "commission of an act clearly dangerous to human life, shooting with a firearm, is the circumstance surrounding the conduct, which...', 'general', 'State of Texas v. Meru, Mark', 'https://www.courtlistener.com/opinion/2947337/', '2947337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Salazar was given notice that entry was forbidden by virtue of the bare pleading that he had entered a "habitation,” reasoning that the statutory definition of habitation served "inherently [to provide] notice that entry is forbidden.', 'plea', 'State of Texas v. Meru, Mark', 'https://www.courtlistener.com/opinion/2947337/', '2947337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 We reversed the judgment of the court of appeals, however, holding that the allegation in the indictment that the appellant “used” the motor vehicle did not commit the State to proving that the appellant necessarily drove it, as would be required to prove the lesser offense.', 'general', 'State of Texas v. Meru, Mark', 'https://www.courtlistener.com/opinion/2947337/', '2947337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the ordinary meaning of the words as used in the statute, we conclude that the statutory terms “use” and “present” may overlap in meaning, that a transaction need not be consummated to support a jury finding that a defendant used a debit card, and that the court of appeals erred by determining that the evidence is insufficient to establish debit card abuse.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reinstate the trial court’s judgment, we conclude that appellant’s petition regarding the reformation of the judgment was improvidently granted.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By applying this definition to the word “presents” as used in the debit-card statute, we conclude that the defendant must physically show or provide the card to an individual or for another individual, such as swiping a card for a store clerk, but presentment does not require any subsequent result, such as the consummation of the transaction.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 We conclude that the plain meaning of the words “uses” and “presents” includes some overlap in meaning such that someone can, with the same conduct, both use and present a credit card, and that neither word requires consummation of the transaction.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the court of appeals’s analysis, under circumstances like these, the defendant could be charged with “presentment” or with attempted “use,” with each offense potentially resulting in a different punishment range: We conclude that the disparity in the applicable punishment range for the same conduct is contrary to the “just and reasonable result” presumably intended by the Legislature.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any rational jury could have found the essential elements of the crime beyond a reasonable doubt.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and reinstate the judgment of the trial court.', 'general', 'Clinton, Katherine', 'https://www.courtlistener.com/opinion/2944092/', '2944092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a case of sexual assault of a child, we held that a used condom was inadmissible because it was taken from the appellant’s truck by his sister, who was the mother of the victim, and we determined that she took the condom with the intent to deprive the appellant of his property.', 'general', 'Baird v. State', 'https://www.courtlistener.com/opinion/2948278/', '2948278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In both Wilson and Jenschke, we held that the evidence was inadmissible under Article 38.', 'general', 'Baird v. State', 'https://www.courtlistener.com/opinion/2948278/', '2948278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 In Bowen, we held that a court of appeals, upon finding the evidence supporting a conviction to be legally insufficient, is not necessarily limited to ordering an acquittal, but may instead reform the judgment to reflect a verdict of guilty on a lesser-included offense — even when no lesser-included instruction was given at trial.', 'general', 'Thornton, Gregory', 'https://www.courtlistener.com/opinion/2949829/', '2949829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Prior to Bowen, we held that the courts of appeals were not authorized to intervene on behalf of “overreaching” parties.', 'general', 'Thornton, Gregory', 'https://www.courtlistener.com/opinion/2949829/', '2949829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”58 Synthesizing these statutory definitions, we conclude that the first prong of the reformation analysis described above can be answered in the affirmative only if the jury, by its verdict, must necessarily have found that, 1) knowing that an offense had been committed, and with 2) the specific intent to conceal the crack pipe,59 and 3) the specific intent to impair the availability of the crack pipe as evidence in a later *301investigation or proceeding, the appellant 4) did an act amounti...', 'general', 'Thornton, Gregory', 'https://www.courtlistener.com/opinion/2949829/', '2949829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the evidence presented at trial and determined that the same is sufficient to support a rational jury finding that the appellant harbored the specific intent to conceal evidence, we conclude that there is sufficient evidence to support a conviction for attempted tampering with evidence.', 'general', 'Thornton, Gregory', 'https://www.courtlistener.com/opinion/2949829/', '2949829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”38 We concluded that the “purpose” of the Collier rule, “which was to prevent the State from overreaching and having an unfair advan*297tage over the defendant .', 'general', 'Thornton, Gregory', 'https://www.courtlistener.com/opinion/2949829/', '2949829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bowen, this Court held that the court of appeals erred by entering a judgment of acquittal when the evidence adduced at trial, although insufficient to establish Bowen’s conviction for misapplication of $200,000 or more in fiduciary property, was nevertheless sufficient to sustain her conviction for the second-degree offense of misapplication of fiduciary property valued over $100,000.', 'general', 'Thornton, Gregory', 'https://www.courtlistener.com/opinion/2949829/', '2949829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that, by “analyzing the statutory elements of the offense as they were modified in the indictment, the assault by threats was not included within the allegation of murder.', 'general', 'Thornton, Gregory', 'https://www.courtlistener.com/opinion/2949829/', '2949829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has not preserved this complaint for appeal.', 'general', 'James Musgrove v. State', 'https://www.courtlistener.com/opinion/2984612/', '2984612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s judgment as to appellant’s conviction for attempted escape and remand that conviction for a new punishment trial.', 'general', 'James Musgrove v. State', 'https://www.courtlistener.com/opinion/2984612/', '2984612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment as to appellant’s attempted escape conviction and remand that conviction for a new punishment trial.', 'general', 'James Musgrove v. State', 'https://www.courtlistener.com/opinion/2984612/', '2984612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm the judgment of the trial court, as modified, with regard to appellant’s assault convictions, and reverse the judgment as to appellant’s attempted escape conviction for a new punishment trial.', 'general', 'James Musgrove v. State', 'https://www.courtlistener.com/opinion/2984612/', '2984612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, as modified, the judgment of the trial court with regard to appellant’s assault convictions.', 'general', 'James Musgrove v. State', 'https://www.courtlistener.com/opinion/2984612/', '2984612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we held that Dobbs’s use of force did -not constitute resisting arrest because he ultimately did not use force against the officers.', 'general', 'Finley, William Bryan Iii', 'https://www.courtlistener.com/opinion/3180657/', '3180657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 Applying a plain-meaning approach to the word “force,” we found that force requires some “violence, compulsion, or constraint exerted upon or against a person or thing.', 'general', 'Finley, William Bryan Iii', 'https://www.courtlistener.com/opinion/3180657/', '3180657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm its judgment because Finley used force “against” the officers in opppsing his arrest as required by Penal Code § 38.', 'general', 'Finley, William Bryan Iii', 'https://www.courtlistener.com/opinion/3180657/', '3180657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the court of appeals’ judgment affirming Finley’s conviction.', 'general', 'Finley, William Bryan Iii', 'https://www.courtlistener.com/opinion/3180657/', '3180657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Court of Appeals’ reasoning is correct and adopt it as our own.', 'general', 'Moosani v. State', 'https://www.courtlistener.com/opinion/1716683/', '1716683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that there was sufficient evidence for the jury to infer that the appellant intended to take Ms.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/6673849/', '6673849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/6673849/', '6673849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the issue is preserved for our review.', 'general', 'McAdory v. State', 'https://www.courtlistener.com/opinion/6674881/', '6674881') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that the inmates at TRRP are “prisoner[s] ” within the meaning of MCL 800.', 'general', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Legislature specifically excluded from the definition persons “released on parole” — as opposed to all parolees or all persons on parole — we conclude that the Legislature intended to limit the exclusion to a specific class of parolees rather than apply it to parolees in general.', 'general', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that the statutory phrase “released on parole” refers to a prisoner’s release to *41an intermediate facility such as TRRP rather than a parolee’s ultimate release into the community.', 'general', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we conclude that the phrase “released on parole” in MCL 800.', 'general', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a “state prison” is any facility operated by the Department to confine or involuntarily restrain persons committed to its jurisdiction.', 'general', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that TRRP is a state prison within the meaning of MCL 800.', 'general', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that there was probable cause to believe that defendant had furnished a cellular phone to a prisoner in violation of MCL 800.', 'probable_cause', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '565 NW2d 868 (1997), we conclude that defendant’s affidavit dated February 14, 2011, was insufficient to contradict or overcome his previous sworn statements at the plea proceeding of April 12,2010.', 'plea', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Armisted', 'https://www.courtlistener.com/opinion/8006557/', '8006557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State of Maine v. Luke A. Bryant', 'https://www.courtlistener.com/opinion/2685106/', '2685106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'infirmity in the statute, either facially or as applied, and we affirm the judgment.', 'general', 'Jason E. Bouchard v. Department of Public Safety', 'https://www.courtlistener.com/opinion/2798598/', '2798598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that in light of that evidence, the court erred by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court’s instructions were not erroneous even if Gagnier
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 103 (2014), we conclude that Gagnier was not entitled to a jury
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm the judgment.', 'general', 'State of Maine v. Christal N. Gagnier', 'https://www.courtlistener.com/opinion/2828001/', '2828001') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that section 6402 did not, at the time, authorize the three-year suspension in the absence of a criminal conviction, we vacate the judgment.', 'general', 'Rich v. DEPARTMENT OF MARINE RESOURCES', 'https://www.courtlistener.com/opinion/1999036/', '1999036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/2066060/', '2066060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we hold that the retroactive application of the lifetime registration requirement and quarterly in-person verification procedures of SORNA of 1999 to offenders originally sentenced subject to SORA of 1991 and SORNA of 1995, without, at a minimum, affording those offenders any opportunity to ever be relieved of the duty as was permitted under those laws, is punitive.', 'sentencing', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that if SORNA of 1999 registration was made a part of a criminal sentence, the exclusive means by which the State could seek to modify the offender''s sex offender classification under SORNA of 1999 was through Rule 35 of the Maine Rules of Criminal Procedure.', 'sentencing', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), this Court held that a civil drunk driving law was determined to have sufficient criminal characteristics to require constitutional safeguards;', 'general', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute imposes an ex post facto punishment as to offenders sentenced in the years before the effective date of SORNA of 1999 for whom registration was a required part of their sentence and who were subsequently made subject to the more burdensome requirements of SORNA of 1999 after its effective date of September 18, 1999.', 'sentencing', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 25] Thus, we conclude that the ex post facto clauses of the Maine and United States Constitutions are interpreted similarly and are coextensive, and a statute violates the prohibition against ex post facto laws if it: (1) punishes as criminal an act that was not criminal when done, (2) makes more burdensome the punishment for a crime after it has been committed, or (3) deprives the defendant of a defense that was available according to law at the time the act was committed.', 'general', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Maine''s statutory scheme is indistinguishable in this respect and, for the reasons articulated by the Supreme Court in Smith, we conclude that Internet posting pursuant to SORNA of 1999 is not punitive in purpose or effect.', 'general', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Haskell we concluded that it is not and that this factor supports SORNA being viewed as non-punitive.', 'general', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the detective''s search of Bailey''s computer and the subsequent search of his home exceeded the scope of his consent and violated the Fourth Amendment.', 'search_seizure', 'State v. Bailey', 'https://www.courtlistener.com/opinion/2294787/', '2294787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bailey I we concluded that this search of Bailey''s home computer exceeded the scope of Bailey''s consent.', 'general', 'State v. Bailey', 'https://www.courtlistener.com/opinion/2294787/', '2294787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the judgment.', 'general', 'State v. Bailey', 'https://www.courtlistener.com/opinion/2294787/', '2294787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Trott was not experiencing a restraint "other than incarceration or probation, imposed as a result of the sentence for the criminal judgment which is challenged" within the meaning of 15 M.', 'sentencing', 'LOI VAN NGO v. State', 'https://www.courtlistener.com/opinion/2356024/', '2356024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1034, 1037, we held that Trott''s sentence to time previously served, imposed without any additional term of probation or other restriction on the individual, was the "functional equivalent" of a "sentence of unconditional discharge resulting from a criminal judgment, for a period of 2 years following the date of sentence" within the meaning of section 2124(1)(C).', 'sentencing', 'LOI VAN NGO v. State', 'https://www.courtlistener.com/opinion/2356024/', '2356024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'LOI VAN NGO v. State', 'https://www.courtlistener.com/opinion/2356024/', '2356024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the judgment, holding that the District Court lacked jurisdiction because M.', 'general', 'LOI VAN NGO v. State', 'https://www.courtlistener.com/opinion/2356024/', '2356024') ON CONFLICT DO NOTHING;
