INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kelley, supra, we held that the statutory definitions of “sexual intercourse” and “deviate sexual intercourse” include vaginal intercourse, anal intercourse, oral intercourse, and penetration by a foreign object, but not digital penetration.', 'general', 'Commonwealth v. Martin', 'https://www.courtlistener.com/opinion/5148233/', '5148233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this circumstantial evidence “was sufficient to raise the reasonable inferences that the deceased had been raped or that rape had been attempted by the appellant at or near the time of death.', 'general', 'Commonwealth v. Martin', 'https://www.courtlistener.com/opinion/5148233/', '5148233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such evidence was not sufficient, as a matter of law, to establish the defendant''s guilt of rape beyond a reasonable doubt, citing Commonwealth v.', 'general', 'Commonwealth v. Martin', 'https://www.courtlistener.com/opinion/5148233/', '5148233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, and based on our review of the entire record, we conclude that the Commonwealth’s evidence, and all reasonable inferences deducible therefrom, was indeed sufficient to establish beyond a reasonable doubt each element of the first-degree murder of G.', 'general', 'Commonwealth v. Martin', 'https://www.courtlistener.com/opinion/5148233/', '5148233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the above authority contradicts Appellant’s argument that his refusal to sign a written waiver of rights without first consulting an attorney should have been construed as “an unambiguous re-assertion of his wish for counsel before proceeding with any custodial interrogation.', 'general', 'Commonwealth v. Martin', 'https://www.courtlistener.com/opinion/5148233/', '5148233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we conclude that Appellant’s arguments lack merit and, because sufficient evidence supports Appellant’s convictions and the sentence of death was not the result of “passion, prejudice, or any other arbitrary factor,” but rather was based on the Commonwealth’s evidence admitted at trial, the verdict and the sentence of death are hereby affirmed.', 'sentencing', 'Commonwealth v. Martin', 'https://www.courtlistener.com/opinion/5148233/', '5148233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'Commonwealth v. Martin', 'https://www.courtlistener.com/opinion/5148233/', '5148233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶39] We conclude that there is no illegality in the sentence, for four
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶42] In short, we conclude that there is no illegality in the sentence or
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State of Maine v. Pedro J. Rosario', 'https://www.courtlistener.com/opinion/7859654/', '7859654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because probable cause to search did not exist without the information obtained during the initial warrantless entry, no exception to the warrant requirement or the exclusionary rule applies, and we vacate the convictions.', 'probable_cause', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the warrantless entry of the apartment was neither justified under the exigent circumstances exception to the warrant requirement nor as a temporary seizure of the premises, an independent source exception analysis is justified.', 'general', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 19] The inevitable discovery exception is an additional analytical framework for considering the suppression of the evidence if we conclude that the initial warrantless entry into the Rabons’ apartment prior to the issuance of the search warrant was unlawful because there was no probable cause.', 'suppression', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons to be more fully addressed, we conclude that the evidence seized following the issuance of the search warrant is more properly analyzed under what is known as the independent source exception.', 'general', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 80] Taking this information into account, we held that the victim’s body would inevitably have been discovered because, if the police had not discovered the victim’s body as a result of the interrogation, they would have checked the defendant’s wife’s story and found that the victim was not with her grandparents.', 'general', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hank Watson’s waiver of counsel met constitutional requirements and affirm his conviction, but that Jonathan Blumberg’s waiver of counsel did not meet constitutional requirements and thus we vacate his conviction.', 'general', 'State v. Watson', 'https://www.courtlistener.com/opinion/2402274/', '2402274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm his conviction.', 'general', 'State v. Watson', 'https://www.courtlistener.com/opinion/2402274/', '2402274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Barrett, we affirmed the trial court’s finding that the defendant knowingly and intelligently waived his right to counsel when the trial court informed the defendant of his right to counsel, “thoroughly explained the dangers of proceeding pro se to defendant before [it] permitted defendant to exercise his right of self-representation,” and explained to the defendant the consequences of so acting.', 'general', 'State v. Watson', 'https://www.courtlistener.com/opinion/2402274/', '2402274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), this Court held that a civil drunk driving law was determined to have sufficient criminal characteristics to require constitutional safeguards;', 'general', 'State v. Letalien', 'https://www.courtlistener.com/opinion/2056690/', '2056690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the trial court erred by ordering defendant to surrender specific firearms and by suspending his concealed handgun *892permit for the duration of the DVPO, and we vacate those portions of the DVPO.', 'general', 'Jarrett v. Jarrett', 'https://www.courtlistener.com/opinion/7476852/', '7476852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that because defendant presented evidence after his motion for involuntary dismissal was denied, he has waived *893his right to appeal from the denial of the motion.', 'dismissal', 'Jarrett v. Jarrett', 'https://www.courtlistener.com/opinion/7476852/', '7476852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the testimony admitted during the DVPO hearing regarding defendant''s conduct, we conclude that competent evidence supported the trial court''s findings of fact.', 'general', 'Jarrett v. Jarrett', 'https://www.courtlistener.com/opinion/7476852/', '7476852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" After carefully reviewing the evidence, we conclude that the trial court did properly find that defendant stalked plaintiff.', 'general', 'Jarrett v. Jarrett', 'https://www.courtlistener.com/opinion/7476852/', '7476852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these principles, we find that plaintiff''s 20 July 2015 complaint gave defendant sufficient notice of the nature and basis of her claim.', 'general', 'Jarrett v. Jarrett', 'https://www.courtlistener.com/opinion/7476852/', '7476852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 93 (1989) and we find that the holding in that case controls the outcome here.', 'general', 'Jarrett v. Jarrett', 'https://www.courtlistener.com/opinion/7476852/', '7476852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we affirm in part, vacate in part, and dismiss in part.', 'dismissal', 'Jarrett v. Jarrett', 'https://www.courtlistener.com/opinion/7476852/', '7476852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that plaintiff did not engage in “protected activity” under MCL 15.', 'general', 'Pace v. Edel-Harrelson', 'https://www.courtlistener.com/opinion/8001864/', '8001864') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Court of Appeals’ contrary decision and remand this case to that court for further consideration.', 'general', 'Pace v. Edel-Harrelson', 'https://www.courtlistener.com/opinion/8001864/', '8001864') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jacks, we held that “the fact of non-consent to the taking may .', 'general', 'People v. March', 'https://www.courtlistener.com/opinion/8001868/', '8001868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the defendant, although the true owner, was guilty of larceny where he had “secretly removed” the buggy from Gilbert’s possession.', 'general', 'People v. March', 'https://www.courtlistener.com/opinion/8001868/', '8001868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that our larceny law prohibits the wrongful dispossession of property, protecting an individual’s possessory interests from a wrongful taking.', 'general', 'People v. March', 'https://www.courtlistener.com/opinion/8001868/', '8001868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse the Court of Appeals judgment *428and reinstate the trial court’s dismissal of the criminal charges against defendant.', 'dismissal', 'People v. March', 'https://www.courtlistener.com/opinion/8001868/', '8001868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the DOC retained jurisdiction over Greer despite the erroneous issuance of a discharge certificate.', 'general', 'Ardonis Greer v. Wayne J. Wiedenhoeft', 'https://www.courtlistener.com/opinion/2670494/', '2670494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the clear language of the statute and the code trump Greer''s *329argument that the DOC lost jurisdiction to initiate revocation proceedings when it erroneously issued a discharge certificate to Greer.', 'general', 'Ardonis Greer v. Wayne J. Wiedenhoeft', 'https://www.courtlistener.com/opinion/2670494/', '2670494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that a circuit court sitting in certiorari cannot properly entertain equitable arguments.', 'general', 'Ardonis Greer v. Wayne J. Wiedenhoeft', 'https://www.courtlistener.com/opinion/2670494/', '2670494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The department having determined that you have satisfied said sentence, it is ordered that effective September 28, 2007, you are discharged absolutely.', 'sentencing', 'Ardonis Greer v. Wayne J. Wiedenhoeft', 'https://www.courtlistener.com/opinion/2670494/', '2670494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude, therefore, that the DOC did possess the jurisdiction to revoke Greer''s probation, and we affirm the court of appeals.', 'general', 'Ardonis Greer v. Wayne J. Wiedenhoeft', 'https://www.courtlistener.com/opinion/2670494/', '2670494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals.', 'general', 'Ardonis Greer v. Wayne J. Wiedenhoeft', 'https://www.courtlistener.com/opinion/2670494/', '2670494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It informed Greer that "[t]he department having determined that you have satisfied said judgment, it is ordered that effective September 28, 2007, you are discharged from said judgment only.', 'general', 'Ardonis Greer v. Wayne J. Wiedenhoeft', 'https://www.courtlistener.com/opinion/2670494/', '2670494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The department having determined that you have satisfied said sentence, it is ordered that effective September 28, 2007, you are discharged absolutely.', 'sentencing', 'Ardonis Greer v. Wayne J. Wiedenhoeft', 'https://www.courtlistener.com/opinion/2670494/', '2670494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Kenneth Griesemer v. State of Indiana', 'https://www.courtlistener.com/opinion/2725005/', '2725005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances, we held that the statements contained in the report were hearsay and could not be admitted for their truth through the expert’s testimony.', 'general', 'State v. Julie L. Michaels (072106)', 'https://www.courtlistener.com/opinion/2713863/', '2713863') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is no confrontation violation caused by Dr.', 'general', 'State v. Julie L. Michaels (072106)', 'https://www.courtlistener.com/opinion/2713863/', '2713863') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, like a number of *29state high courts and federal courts of appeal, we find that the fractured holdings of Williams provide little guidance in understanding when testimony by a laboratory supervisor or co-analyst about a forensic report violates the Confrontation Clause.', 'general', 'State v. Julie L. Michaels (072106)', 'https://www.courtlistener.com/opinion/2713863/', '2713863') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Williams is such a case for the following reasons.', 'general', 'State v. Julie L. Michaels (072106)', 'https://www.courtlistener.com/opinion/2713863/', '2713863') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no denial of defendant’s confrontation rights in this proceeding, we affirm defendant’s conviction.', 'general', 'State v. Julie L. Michaels (072106)', 'https://www.courtlistener.com/opinion/2713863/', '2713863') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a fair-minded juror could reasonably conclude based on this evidence that the market value of the stolen parka was more than $500.', 'general', 'Morris v. State', 'https://www.courtlistener.com/opinion/2737444/', '2737444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM Morris''s conviction, and we refer Morris''s sentence appeal to the Alaska Supreme Court under Appellate Rule 215(k).', 'sentencing', 'Morris v. State', 'https://www.courtlistener.com/opinion/2737444/', '2737444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that rational basis review applies to Knipfer''s equal protection and substantive due process claims and to Alger''s equal protection claim.', 'general', 'State v. Ronald Knipfer', 'https://www.courtlistener.com/opinion/2771203/', '2771203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the legislature''s decision to apply the Daubert evidentiary standard to "actions" or "special proceedings" "commenced" on or after February 1, 2011, satisfies rational basis review and therefore is constitutional.', 'general', 'State v. Ronald Knipfer', 'https://www.courtlistener.com/opinion/2771203/', '2771203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the failure to apply the Daubert evidentiary standard to expert testimony in Alger''s and Knipfer''s Chapter 980 discharge petition trials satisfies rational basis review, and therefore survives constitutional scrutiny.', 'general', 'State v. Ronald Knipfer', 'https://www.courtlistener.com/opinion/2771203/', '2771203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that rational basis review was the appropriate level of judicial scrutiny.', 'general', 'State v. Ronald Knipfer', 'https://www.courtlistener.com/opinion/2771203/', '2771203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Daubert evidentiary standard under Wis.', 'general', 'State v. Ronald Knipfer', 'https://www.courtlistener.com/opinion/2771203/', '2771203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the Daubert evidentiary standard in Wis.', 'general', 'State v. Ronald Knipfer', 'https://www.courtlistener.com/opinion/2771203/', '2771203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that rational basis review applies to Alger''s and Knipfer''s constitutional claims because the failure to apply the Dauhert evidentiary standard to expert testimony in a Chapter 980 discharge petition trial does not implicate a fundamental right.', 'general', 'State v. Ronald Knipfer', 'https://www.courtlistener.com/opinion/2771203/', '2771203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure to apply the Daubert evidentiary standard to expert testimony at Alger''s and Knipfer''s Chapter 980 discharge petition trials satisfies rational basis review.', 'general', 'State v. Ronald Knipfer', 'https://www.courtlistener.com/opinion/2771203/', '2771203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2003) ("Without any testimony of particular prior bad acts [the defendant] participated in as a gang member, we find that evidence of his mere affiliation with the gang does not fall under Rule 404(b).', 'general', 'State v. Gonzalez', 'https://www.courtlistener.com/opinion/2773701/', '2773701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court on all issues.', 'general', 'State v. Gonzalez', 'https://www.courtlistener.com/opinion/2773701/', '2773701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we affirm the denial of his motion for directed verdict on the murder charge, this argument fails.', 'general', 'State v. Gonzalez', 'https://www.courtlistener.com/opinion/2773701/', '2773701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 51 We affirm Mr.', 'general', 'State v. Gonzalez', 'https://www.courtlistener.com/opinion/2773701/', '2773701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we reverse the decision of the court of appeals related to the sufficiency-of-the-evidence claim, reverse the judgment of the district court, and remand the matter for dismissal of the charge.', 'dismissal', 'State of Iowa v. David Howard Rooney', 'https://www.courtlistener.com/opinion/2792831/', '2792831') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, based on precedent, we hold that, in the context of evidence preservation and destruction, the Wisconsin Constitution does not provide greater due process protection under Article 1, Section 8, *14Clause 18 than the United States Constitution under either the Fifth9 or Fourteenth10 Amendments.', 'general', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we hold that operating a motor vehicle with a detectable amount of a restricted controlled substance in the blood under Wis.', 'general', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our precedent we hold that, in the context of evidence *25preservation and destruction, the Wisconsin Constitution does not provide greater due process protections under Article 1, Section 8, Clause 1 than the United States Constitution does under either the Fifth or Fourteenth Amendments.', 'general', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, because we hold that the State did not violate Luedtke and Weissinger''s due process rights, we conclude that the circuit court was not required to give a jury instruction allowing the jury to infer that the lost evidence was exculpatory.', 'jury_instruction', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that operating a motor vehicle with a detectable amount of a restricted controlled substance in the blood under Wis.', 'general', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
