INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we hold that operating a motor vehicle with a detectable amount of a restricted con*47trolled substance in the blood under Wis.', 'general', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As early as 1984, we held that "[t]he importance of the production of the original breath ampoule or a portion of the blood sample as the sine qua non of due process is a myth that should not be perpetuated.', 'general', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it was an error "to conclude due process will be violated if a blood test is not suppressed merely because a portion of the sample — even if it were retestable — could not be produced for further tests.', 'suppression', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dubose, we held that Article I, Section 8 of the Wisconsin Constitution contained a broader due process right than that contained within the Fifth and Fourteenth Amendments to the United States Constitution.', 'general', 'State v. Michael R. Luedtke', 'https://www.courtlistener.com/opinion/2796336/', '2796336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant claiming that he or she is solely in the presence or vicinity of the medical use of marijuana is not entitled to immunity under MCL 333.', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
