INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant is not entitled to either type of immunity under § 4(i) of the MMMA.', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that defendant is not entitled to immunity under § 4(i) of the MMMA, we conclude that the Court of Appeals erred in its interpretation of § 4(g) of the MMMA.', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held similarly in Woodard v Custer, 476 Mich 545;', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals and remand this case to the circuit court for further proceedings consistent with this opinion.', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and remand to the circuit court for further proceedings consistent with this opinion.', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '591 NW2d 642 (1999) (quotation marks and citation submitted) (this Court held in Husted that to the extent that the essential insurance act created an exception to the no-fault act, the two acts are in pari materia and thus should be read together);', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'see also Rathbun, 284 Mich at 544 (this Court held in Rathbun that “[statutes in pari materia, although in apparent conflict, should, so far as reasonably possible, be construed in harmony with each other, so as to give force and effect to each”);', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '468 NW2d 479 (1991) (this Court held in Malcolm that although the emergency medical services act created an exception to governmental immunity that is not found in the governmental tort liability act, these acts are in pari materia and must be read together);', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '369 NW2d 839 (1985) (this Court held in Galloway that the Michigan Employment Security Act, which allows non-lawyers to represent employers in proceedings before Michigan Employment Security Commission referees, and the unauthorized-practice of law statutes are in pari materia and therefore must be read together).', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Palmer, 304 Mich at 637, this Court held that “[wjhere a statute embraces only part of a subject covered comprehensively by a prior law, the two should be construed together unless a different legislative intent appears;', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '521 NW2d 230 (1994), this Court held that “[b]ecause these provisions should be read in pari materia, we deem it appropriate to use the definition of gross negligence as found in [MCL 691.', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '564 NW2d 861 (1997), this Court held that it was appropriate to rely on the definition of “personal representative” found in MCL 700.', 'general', 'People v. Mazur', 'https://www.courtlistener.com/opinion/2807772/', '2807772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that pursuant to the plain language of W.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth herein, we conclude that the circuit court erred by dismissing these fifty-three counts, abused its legitimate powers and deprived the State of its right to prosecute the case.', 'dismissal', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that W.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of this holding, we conclude that counts 2 through 54 of the indictment constitute distinct offenses, and prosecution under each count does not violate double jeopardy principles.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that both W.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pursuant to Hoover, we conclude that the State is entitled to the writ it seeks.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we conclude that the circuit court has abused its legitimate powers and denied the State the right to prosecute its case against Ms.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that the Hoover factors weigh in favor of granting the requested writ of prohibition to prohibit enforcement of the circuit court’s order entered September 5, 2014.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the indictment is sufficient.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the meaning of the word as it is used in the statute can be deduced from the context in which it is used.', 'general', 'SER Ralph A. Lorenzetti, Jr., Pros. Attorney v. Hon. David H. Sanders, Judge', 'https://www.courtlistener.com/opinion/2802310/', '2802310') ON CONFLICT DO NOTHING;
