INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'McGilton’s conviction, we concluded that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that a defendant may raise the question of statutory immunity pretrial and, when such a claim is raised, the trial court must determine whether the defendant has shown by a preponderance of the evidence that the immunity attaches.', 'general', 'Jared Bretherick v. State of Florida', 'https://www.courtlistener.com/opinion/2815837/', '2815837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Fifth District correctly determined that the defendant bears the burden of proof, by a preponderance of the evidence, to demonstrate entitlement to Stand Your Ground immunity at the pretrial evidentiary hearing.', 'general', 'Jared Bretherick v. State of Florida', 'https://www.courtlistener.com/opinion/2815837/', '2815837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that where a criminal defendant files a motion to dismiss on the basis of section 776.', 'dismissal', 'Jared Bretherick v. State of Florida', 'https://www.courtlistener.com/opinion/2815837/', '2815837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that placing the burden of proof on the defendant to establish entitlement to Stand Your Ground immunity by a preponderance of the evidence at the pretrial evidentiary hearing, rather than on the State to prove beyond a reasonable doubt that the defendant’s use of force was not justified, is consistent with this Court’s precedent and gives effect to the legislative intent.', 'general', 'Jared Bretherick v. State of Florida', 'https://www.courtlistener.com/opinion/2815837/', '2815837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After analyzing the appropriate procedure for pretrial claims - of Stand Your Ground immunity, we concluded that the procedure set forth in Peterson “best effectuates the intent of the Legislature.', 'general', 'Jared Bretherick v. State of Florida', 'https://www.courtlistener.com/opinion/2815837/', '2815837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a jury instruction may be considered erroneous when it describes a theory of criminal culpability that was not presented to the jury or it omits a valid theory of criminal culpability that was presented to the jury.', 'jury_instruction', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the erroneous jury instruction in this case was harmless error, and that there was sufficient evidence to convict Williams of felony murder in connection with Robinson''s death.', 'jury_instruction', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a jury instruction may be considered erroneous when it describes a theory of criminal culpability that was not presented to the jury or omits a valid theory of criminal culpability that was presented to the jury.', 'jury_instruction', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 813 (1997), in which we held that a defendant cannot be convicted on a theory of a crime not presented to a jury.', 'general', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 705 (1979), we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we conclude that Williams was not prejudiced by his trial counsel''s decision not to strike a juror and not to object to the admission of crime scene photographs.', 'general', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 729 (1979), we conclude that the jury instruction — which did not accurately reflect the State''s predominant theory of the case (as evidenced by the State''s closing argument) — was erroneous.', 'jury_instruction', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed each of the photographs used as exhibits at Williams'' trial, we conclude that they were neither overly gruesome nor unfairly prejudicial.', 'general', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the error was harmless because it was "clear beyond a reasonable doubt that the jury would have convicted Beamon" had the jury instruction been correct.', 'jury_instruction', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court''s judgment of conviction.', 'general', 'State v. Maltese Lavele Williams', 'https://www.courtlistener.com/opinion/2816262/', '2816262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thompson, we held that use of a pen register on a suspect''s telephone line was a “search” within the meaning of Article I, Section 17, even though the Supreme Court had held such conduct was not a search under the Federal Constitution.', 'general', 'State v. Alesha Ann Green', 'https://www.courtlistener.com/opinion/3133299/', '3133299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that under Simmons, a jury must be informed that life means life without the possibility of parole only when the prosecutor injects concerns of the defendant’s future dangerousness into the case.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*408We turn now to Appellant’s claim that trial counsel was ineffective for failing to develop a diminished capacity defense, and we conclude that Appellant has failed to show trial counsel rendered ineffective assistance with regard to the presentation of such a defense.', 'ineffective_assistance', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because the information contained in the additional records cited by Appellant would have been merely cumulative of the evidence of Appellant’s lifelong struggle with drugs, presented at trial through his own testimony and that of his mother and brother, Kevin, Appellant has failed to show that trial counsel’s failure to obtain the additional records was unreasonable.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Neither do we find that Appellant has proven that trial counsel acted unreasonably in retaining Dr.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our conclusion that there was no arguable merit to the pursuit of a mental deficit diminished capacity defense, our conclusion that trial counsel appropriately investigated and presented a voluntary intoxication defense, and the evidence of record concerning Appellant’s demeanor before, during, and after the commission of the crime that contradicted the assertion that he was unable to form the required specific intent, we find that Appellant has not shown that but for trial counse...', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed with regard to the previous issue, we find that this issue has not been preserved for our review.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed with regard to the previous issues, we find that this issue has not been preserved for our review.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we find that, where confronted with neither a basic, fundamental decision concerning Appellant’s PCRA challenge nor disagreement between counsel and Appellant with respect to the overarching objectives of the challenge, the PCRA court erred in ruling that counsels’ authority to seek an Atkins hearing was subject to Appellant’s veto.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons *476expressed with regard to the previous issues, we find that this issue has not been preserved for our review.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the claim preservation problem, we find that Appellant fails to demonstrate that he made a showing of good cause for the PCRA court to grant the discovery requests.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
