INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the payment of the debt from proceeds from the credit life policy in this case has the same legal effect as if Smith had paid the loan from his own funds.', 'general', 'Edwards v. Columbia, S. C., Teachers Federal Credit Union', 'https://www.courtlistener.com/opinion/8323806/', '8323806') ON CONFLICT DO NOTHING;
