INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Hunley v. Gibson', 'https://www.courtlistener.com/opinion/8325485/', '8325485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Davis v. South Carolina Department of Public Safety', 'https://www.courtlistener.com/opinion/8325996/', '8325996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we hold that the victim’s statement to the doctor falls within the medical diagnosis exception to the hearsay rule, we now proceed to the confrontation clause issue.', 'general', 'People v. Spicer', 'https://www.courtlistener.com/opinion/7121595/', '7121595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that we will defer to a trial court’s evidentiary ruling “unless the ‘ “trial court’s exercise of discretion has been frustrated by an erroneous rule of law.', 'general', 'People v. Spicer', 'https://www.courtlistener.com/opinion/7121595/', '7121595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The supreme court explained that: “In White, this court held that *** the victim’s age cannot form the basis for an extended-term sentence where the defendant is convicted of aggravated battery of a child.', 'sentencing', 'People v. Spicer', 'https://www.courtlistener.com/opinion/7121595/', '7121595') ON CONFLICT DO NOTHING;
