INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm.', 'general', 'People v. Spicer', 'https://www.courtlistener.com/opinion/7121595/', '7121595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this made out no claim under Bouie, for part (b) did not expand the reach of the statute.', 'general', 'Marks v. United States', 'https://www.courtlistener.com/opinion/9011945/', '9011945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '313 (1972), we reversed a conviction under a state obscenity law because it rested on an unforeseeable judicial construction of the statute.', 'general', 'Marks v. United States', 'https://www.courtlistener.com/opinion/9011945/', '9011945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold, in accordance with Bouie, that the Due Process Clause precludes the application to petitioners of the standards announced in Miller v.', 'general', 'Marks v. United States', 'https://www.courtlistener.com/opinion/9011945/', '9011945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is the fact of the lawful arrest which establishes the authority to search, and we hold that in the case of a lawful custodial arrest a full search of the person is not only an exception to the warrant requirement of the Fourth Amendment, but is also a ‘reasonable’ search under that Amendment.', 'search_seizure', 'United States v. Chadwick', 'https://www.courtlistener.com/opinion/109714/', '109714') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the complaint in the case was defective because it did not charge and describe an offense, and that prosecution under the complaint was a violation of Lopez’ due process rights under Art.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, under the authority of McMahan, we hold that it is a violation of the due process clause of Art.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the complaint under which the accused was convicted did not state an offense and that the conviction of the defendant Lopez under this complaint was a violation of her rights under Art.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in State v.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McMahan this Court held that putting the defendant on trial without setting forth in the information the acts constituting the offense for which he was charged was a violation of the due process clause of Art.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in order to give effect to the act we hold that it is to be construed as permitting the district judge to fix a maximum imprisonment at less than life.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1361856/', '1361856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute does not make an arbitrary or unreasonable classification, and does not deny defendant equal protection of the laws.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1361856/', '1361856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in this case it cannot.', 'general', 'State v. Joao', 'https://www.courtlistener.com/opinion/1370697/', '1370697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, since the offers were expressly limited to mitigation of punishment, and since the question of guilt is free from doubt, and since the error can be expunged by a commutation of the sentence, we hold that it does not require reversal of the judgment.', 'sentencing', 'State v. Owen', 'https://www.courtlistener.com/opinion/1422247/', '1422247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that no error was committed by requiring the appellants to state the nature of the felonies for which previous convictions had been admitted.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/1422247/', '1422247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful examination of the entire record, the evidence, proceedings and instructions of the court, we find that the defendants had a fair and impartial trial so far as concerns the question of their guilt.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/1422247/', '1422247') ON CONFLICT DO NOTHING;
