INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that petitioner''s multiple convictions and sentences are proper.', 'sentencing', 'Borges v. State', 'https://www.courtlistener.com/opinion/1100229/', '1100229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Tran''s indictment was defective.', 'general', 'Quang Thanh Tran v. State', 'https://www.courtlistener.com/opinion/1117954/', '1117954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Court of Appeals correctly reversed and rendered Nguyen''s conviction.', 'general', 'Quang Thanh Tran v. State', 'https://www.courtlistener.com/opinion/1117954/', '1117954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, were it not for the abundance of evidence in the record that Tran had fair notice and an opportunity to prepare a defense, his constitutionally-infirm indictment would require that we reverse his conviction.', 'general', 'Quang Thanh Tran v. State', 'https://www.courtlistener.com/opinion/1117954/', '1117954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Nguyen''s conviction and render a judgment of acquittal.', 'general', 'Quang Thanh Tran v. State', 'https://www.courtlistener.com/opinion/1117954/', '1117954') ON CONFLICT DO NOTHING;
