INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not err
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Jackson v. Commonwealth', 'https://www.courtlistener.com/opinion/1067945/', '1067945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '012 is an available defense in regard to both a charge of battery and resisting arrest with violence, and since there was evidence of excessive force which the jury could have believed, we reverse the convictions on counts two and three and remand for a new trial on both charges.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1091738/', '1091738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1935, Florida Statutes (1983), we reverse the sentence and remand for its reduction to one year.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1091738/', '1091738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the conviction under count one.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1091738/', '1091738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because the statute contains no expression of any intent to remove knowledge as an element of these offenses, the Fourth District was correct in applying the reasoning of Chicone and the relevant U.', 'general', 'State v. Giorgetti', 'https://www.courtlistener.com/opinion/1094104/', '1094104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the Fourth District was correct in determining that the sexual offender registration statutes include a requirement that the alleged offender knows of the obligation to register and maintain current addresses.', 'general', 'State v. Giorgetti', 'https://www.courtlistener.com/opinion/1094104/', '1094104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, relying on Staples and Chicone, we find that the Fourth District appropriately held that the public welfare offense rationale did not apply to the sexual offender registration statutes, which punish a violation as a third-degree felony, a serious consequence indeed, especially in this case where the defendant was sentenced to six and onehalf years'' imprisonment.', 'sentencing', 'State v. Giorgetti', 'https://www.courtlistener.com/opinion/1094104/', '1094104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the [plaintiffs] do not have a fundamental constitutional right to samesex marriage arising out of the right to privacy or otherwise.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 1249 ("We hold that the First and Fourteenth Amendments prohibit making mere private possession of obscene material a crime.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that HRS § 286-81(1)(A) and the regulations promulgated pursuant to it are within the proper exercise of police power.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a statute proscribing the commercial distribution of harmful substances may sweep within its ambit, as an enforcement measure, the possession of the substance for personal use.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In order to resolve the issue, we must answer the threshold question, "When in conflict, does the individual''s fundamental privacy right to possess pornography at home, as guaranteed by article I, section 6, take precedence over the sovereign police power of the state to regulate obscene material?" Because we answer the threshold question in the affirmative, we hold that HRS § 712-1214(1)(a) is, indeed, violative of article I, section 6 of the Hawai`i Constitution.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the clear and unambiguous history underlying the promulgation of article I, section 6, we hold that the personal decision to read or view pornographic material in the privacy of one''s own home is protected by article I, section 6 of the Hawai`i Constitution.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In other words, we hold that such activity does not implicate a "state interest," much less a "compelling" one, and that the state may not criminalize it.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that HRS § 712-1214(1)(a) violates article I, section 6 of the Hawai`i Constitution.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the applicant couples do not have a fundamental constitutional right to same-sex marriage arising out of the right to privacy or otherwise.', 'general', 'State v. Mallan', 'https://www.courtlistener.com/opinion/1111406/', '1111406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, this Court holds that Judge Bell was not disqualified from acting summarily on the direct contempt charge committed in his presence in order to preserve the integrity of the court.', 'general', 'Varvaris v. State', 'https://www.courtlistener.com/opinion/1111797/', '1111797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds, therefore, the proof was beyond a reasonable doubt.', 'general', 'Varvaris v. State', 'https://www.courtlistener.com/opinion/1111797/', '1111797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986) this Court held that in cases of direct contempt wherein a personal attack has been made on the court, necessitating instantaneous action, may be dealt with by the judge offended.', 'general', 'Varvaris v. State', 'https://www.courtlistener.com/opinion/1111797/', '1111797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For those reasons we conclude that the appellant''s convictions for organized fraud, forgery, and uttering false instruments were proper, but that he could not lawfully also be convicted of theft.', 'general', 'Donovan v. State', 'https://www.courtlistener.com/opinion/1117000/', '1117000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the essence of a single RICO offense is a series of appropriately related offenses, we conclude that the State unjustifiably tried to chop various components of a single pattern into separate patterns.', 'general', 'Donovan v. State', 'https://www.courtlistener.com/opinion/1117000/', '1117000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we find that costs were improperly imposed.', 'general', 'Donovan v. State', 'https://www.courtlistener.com/opinion/1117000/', '1117000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the appellant''s argument we find that the circumstances offered ample proof of his criminal intent to support his convictions, and that the trial court was correct in denying his motion for judgment of acquittal.', 'general', 'Donovan v. State', 'https://www.courtlistener.com/opinion/1117000/', '1117000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the appellant''s activities which gave rise to the RICO charges occurred *529 within a short time period, occurred in the same places, involved the same perpetrators (though many different victims were involved), violated the same criminal statutes, and were the same in overall nature and scope  thereby constituting only one pattern of racketeering activity.', 'general', 'Donovan v. State', 'https://www.courtlistener.com/opinion/1117000/', '1117000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In keeping with the usual practice, we reverse the lesser offenses and affirm the greater offense (organized fraud).', 'general', 'Donovan v. State', 'https://www.courtlistener.com/opinion/1117000/', '1117000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the imposition of costs because the appellant was not given any notice that they would be assessed.', 'general', 'Donovan v. State', 'https://www.courtlistener.com/opinion/1117000/', '1117000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction for organized fraud, reverse all of the convictions for grand theft, reverse all but one of the four RICO convictions, affirm the remaining RICO conviction, affirm the forgery convictions, affirm the conviction for uttering a false instrument, strike costs, and remand for resentencing.', 'sentencing', 'Donovan v. State', 'https://www.courtlistener.com/opinion/1117000/', '1117000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, to the extent we conclude that Breitbach has suffered no prejudice, we need not pass on the question of counsel''s competency.', 'general', 'State v. Breitbach', 'https://www.courtlistener.com/opinion/1613471/', '1613471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these considerations to the case at hand, we conclude that the cautionary instruction given by the court was sufficient to redress any prejudice to Breitbach that might otherwise have arisen as a consequence of the officers’ testimony.', 'general', 'State v. Breitbach', 'https://www.courtlistener.com/opinion/1613471/', '1613471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 665 (Iowa 1980), we concluded that subsection 1 of Iowa Code section 719.', 'general', 'State v. Breitbach', 'https://www.courtlistener.com/opinion/1613471/', '1613471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that since this latter form of escape does not give rise to “a danger of injury to persons or property,” it is reasonable to conclude that the legislature intended that it would be punishable under subsection 3 of Iowa Code section 719.', 'general', 'State v. Breitbach', 'https://www.courtlistener.com/opinion/1613471/', '1613471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no merit in any of Breit-bach’s three asserted errors, we affirm his conviction.', 'general', 'State v. Breitbach', 'https://www.courtlistener.com/opinion/1613471/', '1613471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Safiedine', 'https://www.courtlistener.com/opinion/1641311/', '1641311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm defendant’s conviction.', 'general', 'People v. Safiedine', 'https://www.courtlistener.com/opinion/1641311/', '1641311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the avoidance canon poses no obstacle and the interpretive circumstances point in a common direction, we conclude that, as a matter of statutory interpretation, § 924(c)(1)(A) defines a single offense.', 'general', 'Harris v. United States', 'https://www.courtlistener.com/opinion/121164/', '121164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reaffirming McMillan and employing the approach outlined in that case, we conclude that the federal provision at issue, 18 U.', 'general', 'Harris v. United States', 'https://www.courtlistener.com/opinion/121164/', '121164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not, and affirm.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1637065/', '1637065') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a person is entitled to the protection of the Fifth Amendment even prior to arrest or a custodial interrogation.', 'general', 'State v. Hassel', 'https://www.courtlistener.com/opinion/1657232/', '1657232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hassel''s statement, "I don''t know if I should speak to you," is ambiguous — and Hassel actually concedes as much — and not a clear invocation of the right.', 'general', 'State v. Hassel', 'https://www.courtlistener.com/opinion/1657232/', '1657232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment and order.', 'general', 'State v. Hassel', 'https://www.courtlistener.com/opinion/1657232/', '1657232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defective instruction could only constitute fundamental error if the malice issue was disputed at trial: "[F]undamental error occurred in the present case if the inaccurately defined term `maliciously'' was a disputed element in the trial of this case.', 'general', 'State v. Weaver', 'https://www.courtlistener.com/opinion/1681113/', '1681113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although Delva involved the trial court''s omission from the jury instructions of an element of an offense that the defendant did not contest, we conclude that the same principle applies to the erroneous inclusion of an element that the State does not argue is present and about which it presents no evidence.', 'jury_instruction', 'State v. Weaver', 'https://www.courtlistener.com/opinion/1681113/', '1681113') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Antenucci', 'https://www.courtlistener.com/opinion/1747004/', '1747004') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Texas’ capital-sentencing procedures .', 'sentencing', 'Hai Hai Vuong v. State', 'https://www.courtlistener.com/opinion/1766581/', '1766581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When this evidence is coupled with the expert psychiatric testimony and the evidence of prior extraneous offenses offered at punishment, we find that the evidence was clearly sufficient to sustain a jury’s affirmative answer to special issue two.', 'general', 'Hai Hai Vuong v. State', 'https://www.courtlistener.com/opinion/1766581/', '1766581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the court’s charge was not fundamentally defective, the issue of whether a fundamental defect denied the appellant a fair trial is no longer in the ease.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1774215/', '1774215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 556 (2002), we held that aggravating circumstances that make a defendant eligible for the death penalty "operate as `the functional equivalent of an element of a greater offense.', 'general', 'Butler v. State', 'https://www.courtlistener.com/opinion/1836985/', '1836985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In my view, the United States Supreme Court decision in Ring, considered in tandem with the jury-trial guarantee in article I, section 22 of the Florida Constitution, requires that we reverse Butler''s death sentence.', 'sentencing', 'Butler v. State', 'https://www.courtlistener.com/opinion/1836985/', '1836985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm Butler''s conviction and his sentence.', 'sentencing', 'Butler v. State', 'https://www.courtlistener.com/opinion/1836985/', '1836985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1996), we affirmed a sentence of death where the defendant shot his live-in girlfriend twice in her head.', 'sentencing', 'Butler v. State', 'https://www.courtlistener.com/opinion/1836985/', '1836985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm Butler''s conviction for first-degree murder and his sentence of death.', 'sentencing', 'Butler v. State', 'https://www.courtlistener.com/opinion/1836985/', '1836985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the disclosure information should continue to be required on the Florida Family Law Forms generally.', 'general', 'Amendments to the Florida Family Law Rules', 'https://www.courtlistener.com/opinion/1843757/', '1843757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we conclude that there should be a narrow exception to the disclosure requirement when domestic or repeat violence is at issue.', 'general', 'Amendments to the Florida Family Law Rules', 'https://www.courtlistener.com/opinion/1843757/', '1843757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered this proposal, we conclude that a victim should be permitted to leave the state with the parties'' minor child only if permitted through court order.', 'general', 'Amendments to the Florida Family Law Rules', 'https://www.courtlistener.com/opinion/1843757/', '1843757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the rule should not be amended to allow service by mail.', 'general', 'Amendments to the Florida Family Law Rules', 'https://www.courtlistener.com/opinion/1843757/', '1843757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the rule should continue to require any party making over $50,000 per annum to file the long-form affidavit, but note that the affidavit is shorter than the one currently contained in the rules.', 'general', 'Amendments to the Florida Family Law Rules', 'https://www.courtlistener.com/opinion/1843757/', '1843757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that rule 10-2.', 'general', 'Amendments to the Florida Family Law Rules', 'https://www.courtlistener.com/opinion/1843757/', '1843757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'NOW, THEREFORE, IT IS ORDERED that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained below, we hold that the Act, which requires certain defendants to register as sexual predators and limits their employment opportunities, is unconstitutional as applied to a defendant whose crime indisputably did not contain a sexual element.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1844126/', '1844126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the statute may have been based on the premise that providing the community with relevant information about certain types of offenders was a reasonable way to help them protect themselves and their children, we hold that the language used goes beyond that purpose when applied in this case.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1844126/', '1844126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the sexual offender designation is unconstitutional as applied to Robinson, who was not convicted of an offense containing a sexual element, in circumstances concededly involving no sexual act, and which was committed without any sexual motivation or purpose.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1844126/', '1844126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we held that mere injury to reputation, even if defamatory, does not constitute the deprivation of a liberty interest.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1844126/', '1844126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the application of the statutory requirement that Reine be classified as a sexually oriented offender, in a case in which it has been stipulated that his offenses were committed without any sexual motivation or purpose, is unreasonable and arbitrary, and bears no rational relationship to the purposes of the statute, we conclude that it offends the Due Process clauses of both the Ohio and United States constitutions.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1844126/', '1844126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the designation.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1844126/', '1844126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the district court in this case and remand for further proceedings consistent with this opinion.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1844126/', '1844126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the designation as a sexual predator constitutes a deprivation of a protected liberty interest.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1844126/', '1844126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), wherein this Court held that "[the] appellate courts of this state shall dismiss the appeal of a convicted defendant not yet sentenced who flees the jurisdiction before filing a notice of appeal.', 'dismissal', 'Griffis v. State', 'https://www.courtlistener.com/opinion/1855160/', '1855160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that while dismissal of an appeal pending while the defendant is a fugitive may serve substantial interests, the same interests do not support a rule of dismissal for all appeals filed by former fugitives, returned to custody before invocation of the appellate system.', 'dismissal', 'Griffis v. State', 'https://www.courtlistener.com/opinion/1855160/', '1855160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that the interpretation employed by the trial judge was too broad.', 'general', 'Brendle v. City of Houston', 'https://www.courtlistener.com/opinion/1855175/', '1855175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the circuit court committed manifest error in determining that Brendle''s conduct gave rise to probable cause for his arrest for a violation of Mississippi''s statute against public profanity.', 'probable_cause', 'Brendle v. City of Houston', 'https://www.courtlistener.com/opinion/1855175/', '1855175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that Brendle''s arrest for public profanity was unlawful, the charges of resisting arrest are thereby undergirded.', 'general', 'Brendle v. City of Houston', 'https://www.courtlistener.com/opinion/1855175/', '1855175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After determining that the circuit court committed manifest error in applying the law to the facts of this case, we reverse and vacate Brendle''s conviction.', 'general', 'Brendle v. City of Houston', 'https://www.courtlistener.com/opinion/1855175/', '1855175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991)], we held that a defendant "has no right to a mercy instruction.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), where a mother appealed her conviction under § 97-3-19(2)(f) for the death of her nine-month old son who died of internal injuries after she punched him in the abdomen when he would not stop crying, this Court held that she was entitled to a lesser included offense instruction on manslaughter pursuant to Miss.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Butler was entitled to have the jury instructed that she could be convicted under Miss.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Jackson''s reliance on Ake avails him nothing and we find that he had more than adequate time in which to secure a thorough evaluation by his psychiatrist of choice, Dr.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that the reasons for allowing Sheriff Banks to remain in the courtroom to be less than compelling, Jackson has failed to demonstrate any prejudice resulting from the sheriff''s presence or his testimony.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, there being no prejudice to Jackson in this particular case, we find that any error was harmless.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The jury having been so instructed through Instructions C-CR-3 and C-CR-5, as well as through S-2, we find that no error resulted from the wording of Count Four of Instruction S-2.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the circumstances of this case, where four children were stabbed to death and one adult and two other children received life-threatening stab wounds, we find that use of the "great risk to many persons" aggravating circumstance certainly is warranted.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having done so, we find that the sentence of death in this case was not influenced by passion, prejudice, or any other arbitrary factor and that the evidence supports the jury''s findings of statutory aggravating circumstances as listed in Miss.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the appellant and the facts of the crime committed, we find that the sentence of death in this case is neither excessive nor disproportionate to those cases in which such sentence has been imposed and upheld.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1868949/', '1868949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the PCRA does not impose a more stringent prejudice requirement than that applicable to direct appeals, and we decline to follow the plurality opinion in Buehl.', 'general', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that the PCRA does not create a more stringent standard for prevailing on an ineffectiveness claim, we nevertheless hold that Kimball failed to demonstrate that his trial counsel was ineffective for failing to cross-examine Shortridge concerning bias or for presenting the testimony of Reverend Kimball.', 'ineffective_assistance', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that the trial court erred in disallowing the defense the opportunity to cross-examine the witness concerning the other charges.', 'general', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the introduction of the defendant''s prior crimes to vouch for his credibility was not unreasonable, even if unsuccessful, under the circumstances.', 'general', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, due to the overwhelming evidence against Kimball and his counsel''s otherwise adequate cross-examination of Shortridge, we conclude that counsel''s error does not entitle Kimball to relief.', 'general', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the language of the PCRA does not create a higher burden on a defendant to show ineffective assistance of counsel than the standard for proving ineffectiveness on direct appeal.', 'ineffective_assistance', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, because Kimball failed to establish his counsel''s ineffectiveness pursuant to the standard set forth in Section 9543(a)(2)(ii) of the PCRA, we reverse the Order of the Superior Court and reinstate the Opinion and Order of the PCRA court, denying Kimball relief.', 'ineffective_assistance', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the denial of post-conviction relief and reinstated the judgment of sentence of death.', 'sentencing', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the qualified immunity analysis must, therefore, assume that defendant acted in retaliation for plaintiff’s speech and that plaintiff’s right not to be fired for that purpose, was clearly established.', 'general', 'Cook v. Nelson', 'https://www.courtlistener.com/opinion/1929623/', '1929623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 505, and we found that there was enough evidence for plaintiff to reach the jury on that claim.', 'general', 'Cook v. Nelson', 'https://www.courtlistener.com/opinion/1929623/', '1929623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm without reaching the additional ground raised by defendant.', 'general', 'Cook v. Nelson', 'https://www.courtlistener.com/opinion/1929623/', '1929623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we hold that: (i) the Superior Court committed plain error in not entering
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though we find that Monroe did waive his insufficiency claims, we hold that the waiver should be excused under the circumstances of this case.', 'general', 'Monroe v. State', 'https://www.courtlistener.com/opinion/1934571/', '1934571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because we reverse Monroe’s convictions based on a lack of sufficient evidence, the federal and State Double Jeopardy Clauses require that we remand the case for an entry of a judgment of acquittal.', 'general', 'Monroe v. State', 'https://www.courtlistener.com/opinion/1934571/', '1934571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE the judgment of conviction and REMAND the case to the Superior Court for an ENTRY OF A JUDGMENT OF ACQUITTAL in favor of Monroe as to the Burglary Third Degree and Theft Felony counts.', 'general', 'Monroe v. State', 'https://www.courtlistener.com/opinion/1934571/', '1934571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “given the facts and circumstances of this case,” suppression was not required.', 'suppression', 'State, City of Minneapolis v. Cook', 'https://www.courtlistener.com/opinion/1954095/', '1954095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm the court of appeals and the trial court.', 'general', 'State, City of Minneapolis v. Cook', 'https://www.courtlistener.com/opinion/1954095/', '1954095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the State must meet its burden of establishing whether a custodial interrogation occurred by a preponderance of the evidence.', 'general', 'State v. Armstrong', 'https://www.courtlistener.com/opinion/1987493/', '1987493') ON CONFLICT DO NOTHING;
