INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 753 (1965), this court held that a separate hearing before the trial judge is required in order to determine whether a defendant''s admission was voluntary.', 'general', 'State v. Armstrong', 'https://www.courtlistener.com/opinion/1987493/', '1987493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we conclude that Armstrong''s oral statements were inadmissible because Armstrong
