INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 816 (1984), we held that the same scope of review applies in the lenient sentence context as applies in the excessive sentence context.', 'sentencing', 'State v. Harrison', 'https://www.courtlistener.com/opinion/1987508/', '1987508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, based on the foregoing analysis, we conclude that the trial court did not abuse its discretion in sentencing Harrison to probation and, thus, that Harrison’s sentences are not excessively lenient.', 'sentencing', 'State v. Harrison', 'https://www.courtlistener.com/opinion/1987508/', '1987508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals, concluding that the trial court did not abuse its discretion in imposing probation.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/1987508/', '1987508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse, and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that the district court’s erroneous instruction that respondent had a duty to retreat constitutes plain error and requires a new trial.', 'general', 'State v. Baird', 'https://www.courtlistener.com/opinion/1996577/', '1996577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'from our general rule of retroactivity, we hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we conclude that it is simply impossible to determine whether the, jury rejected Baird’s version of the facts or whether it accepted his version but concluded that.', 'general', 'State v. Baird', 'https://www.courtlistener.com/opinion/1996577/', '1996577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '• Because there is a reasonable likelihood that the error had a significant effect on the jury’s verdict, we conclude that the error was prejudicial and affected the outcome of the case and therefore that it cannot be considered harmless.', 'general', 'State v. Baird', 'https://www.courtlistener.com/opinion/1996577/', '1996577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals.', 'general', 'State v. Baird', 'https://www.courtlistener.com/opinion/1996577/', '1996577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that the admission of Defendant’s refusal to submit to a breathalyzer test did not infringe upon his federal due process rights.', 'general', 'State v. Dvorak', 'https://www.courtlistener.com/opinion/2006065/', '2006065') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Dvorak', 'https://www.courtlistener.com/opinion/2006065/', '2006065') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From what we have stated above, we conclude that the judgment of the district court should be affirmed.', 'general', 'State v. McKenna', 'https://www.courtlistener.com/opinion/2031648/', '2031648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. McKenna', 'https://www.courtlistener.com/opinion/2031648/', '2031648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the cane did not function as a “container” for the knife.', 'general', 'State v. McCoy', 'https://www.courtlistener.com/opinion/2033009/', '2033009') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “a glove compartment, unlike an ordinary container such as a jar or box, is a specialized structure unique to a vehicle” and does not constitute a “container” under the statute.', 'general', 'State v. McCoy', 'https://www.courtlistener.com/opinion/2033009/', '2033009') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court on this issue, but do not remand because the defendant has already been once put in jeopardy for this offense.', 'general', 'State v. McCoy', 'https://www.courtlistener.com/opinion/2033009/', '2033009') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'AHB’s claim for treble damages, we affirm in part and reverse in part.', 'general', 'American Heritage Banco, Inc. v. McNaughton', 'https://www.courtlistener.com/opinion/2050976/', '2050976') ON CONFLICT DO NOTHING;
