INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Court, we affirm the circuit court’s denial of the Petitioner’s Rule 35(b) motion.', 'general', 'State of West Virginia v. Patrick Shawn Collins', 'https://www.courtlistener.com/opinion/4315918/', '4315918') ON CONFLICT DO NOTHING;
