INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 414 (2000), we held that trial counsel’s failure to investigate mitigating circumstances and present such evidence during the penalty phase constituted ineffective assistance of counsel.', 'ineffective_assistance', 'Springs v. State', 'https://www.courtlistener.com/opinion/5283858/', '5283858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Springs v. State', 'https://www.courtlistener.com/opinion/5283858/', '5283858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the statute violated due process because it criminalized family photographs of innocent caretaker-child conduct, such as bathing the child or changing a diaper.', 'general', 'State v. Adkins', 'https://www.courtlistener.com/opinion/5061572/', '5061572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained below, we conclude that the circuit court erred in determining the statute to be unconstitutional.', 'general', 'State v. Adkins', 'https://www.courtlistener.com/opinion/5061572/', '5061572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the Legislature did not exceed its constitutional authority in redefining section 893.', 'general', 'State v. Adkins', 'https://www.courtlistener.com/opinion/5061572/', '5061572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the circuit court erred in granting the motions to dismiss and we reverse the circuit court’s order.', 'dismissal', 'State v. Adkins', 'https://www.courtlistener.com/opinion/5061572/', '5061572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), we concluded that “a due process violation occurs if a criminal statute’s means is not rationally related to its purposes and, as a result, it criminalizes innocuous conduct.', 'general', 'State v. Adkins', 'https://www.courtlistener.com/opinion/5061572/', '5061572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the circuit court’s order granting the motions to dismiss.', 'dismissal', 'State v. Adkins', 'https://www.courtlistener.com/opinion/5061572/', '5061572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1996), this Court held that the defendant seeking to reverse an unfavorable ruling on a motion to suppress bears a heavy burden.', 'suppression', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held: “[W]hen the defendant is discovered with the personal property of the deceased on his person, it is entirely within reason for the jury to find that this fact in itself constitutes robbery.', 'general', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, this Court held that a defendant is not entitled to a sympathy or mercy instruction and allowing such an instruction results in a jury verdict that is based on “whim and caprice.', 'general', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that the trial judge did not err by failing to inform the jury that, “if they were unable to agree within a reasonable time on the punishment to be imposed, [the defendant] would be sentenced to life imprisonment.', 'sentencing', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989)) (the solitary instance where this Court held a photograph, a close-up of the victim’s partly decomposed skull, was gruesome and lacked an evidentiary purpose and was more prejudicial than probative).', 'general', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on a review of the record in the light most favorable to the verdict— including all the evidence discussed throughout this opinion and the inferences that can be drawn therefrom—we conclude that Gillett’s convictions were neither based on insufficient evidence nor against the overwhelming weight of the evidence.', 'general', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, based on our review of the record and a finding that the cases Gillett cites are distinguishable from the instant case, we conclude that Gillett’s sentence is not based on any impermissible, arbitrary factors.', 'sentencing', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that: 1) the record reveals that there was probable cause to arrest Gillett, and 2) thus, the items seized from Gillett’s person incident to his arrest and the custodial statement he provided incident to his arrest were lawful and should not have been suppressed.', 'suppression', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not err in denying Gillett’s motion to suppress the seizures from the warranted search of 606 North Ash Street.', 'suppression', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, based on the information included in the affidavit in support of the warrant for the search of the Gillett farm, there was a substantial basis for the magistrate judge to issue the warrant and for the trial court to conclude that probable cause existed.', 'probable_cause', 'Gillett v. State', 'https://www.courtlistener.com/opinion/5104845/', '5104845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This discrepancy between the indictment and the jury instructions was material, so we reverse.', 'jury_instruction', 'Decker v. State', 'https://www.courtlistener.com/opinion/5104893/', '5104893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998), in which this Court held that a defendant indicted for voyeurism was entitled to a jury instruction on the lesser-included offense of trespass.', 'jury_instruction', 'Jackson v. State', 'https://www.courtlistener.com/opinion/5104991/', '5104991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on today’s discussion, we conclude that the jury’s verdict finding *608David Anthony Jackson guilty of the crime of burglary of a dwelling house with the intent to commit the crime of larceny once inside, is supported by legally sufficient evidence and that the verdict is not contrary to the weight of the evidence.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/5104991/', '5104991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being the case, we find that this argument is without merit.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/5104991/', '5104991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the judgment of conviction and sentence entered in the Circuit Court for the First Judicial District of Hinds County.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/5104991/', '5104991') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More*103over, mindful of Mother’s erratic behavior throughout these proceedings and her inability to curb her anger or address her parenting deficiencies or even progress beyond the supervised hour-long semimonthly visitations, we find that she will not or cannot remedy the causes of the incapacity regardless of whether or not she completed some of the programs outlined in the FSP.', 'general', 'In re N.A.M.', 'https://www.courtlistener.com/opinion/5144779/', '5144779') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm.', 'general', 'In re N.A.M.', 'https://www.courtlistener.com/opinion/5144779/', '5144779') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because Lesko did not establish any ground for deeming counsel per se ineffective, and did not establish a lack of reasonable basis through trial counsel’s testimony at the PCRA hearing, he failed to sustain his burden of proof.', 'ineffective_assistance', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Daniels, we held that the PCRA petitioner was not prejudiced by counsel’s failure to challenge the trial court’s specific intent to kill instructions, even though an isolated portion of the charge appeared to have violated the ruling in Huffman.', 'general', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 220, 273 (2006) (where this Court held that a Simmons instruction is mandated only if the prosecutor placed the defendant’s future dangerousness at issue and the defendant requested the instruction at trial).', 'general', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the PCRA court’s factual findings are supported by the record and its legal conclusions are free from error.', 'general', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the only viable claim is one alleging counsel’s ineffectiveness for failing to review the transcripts of Curley’s penalty hearing and pursue on direct appeal a claim alleging a violation of due process based on the presentation of inconsistent theories at Appellant’s trial and Curley’s penalty hearing.', 'ineffective_assistance', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '15 We conclude that such claim lacks arguable merit because the record supports the PCRA court’s conclusion that the Commonwealth’s prosecutorial theories in the two proceedings were consistent — that Appellant coerced Curley to commit the murders of Clark and Hopper in order to train him to become a hit man.', 'general', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, as in Daniels, we conclude that Appellant was not prejudiced as there is not a reasonable probability that the outcome of the trial would have changed had trial counsel objected to the jury charge.', 'general', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More significantly, however, we conclude that the proposed charge, while an accurate statement of the law, was unnecessary given that the trial court correctly charged the jury on the elements of conspiracy.', 'general', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Lesko was given an evidentiary hearing and yet did not elicit from trial counsel his reasons for failing to request the cautionary charge, we concluded that Lesko failed to sustain his burden of demonstrating a lack of reasonable basis.', 'general', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 For the reasons set forth herein, we affirm the denial of relief.', 'general', 'Commonwealth v. Koehler', 'https://www.courtlistener.com/opinion/5144899/', '5144899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in determining that S.', 'general', 'Commonwealth v. Walsh', 'https://www.courtlistener.com/opinion/5144920/', '5144920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Commonwealth presented sufficient evidence to support the trial court’s determination that he is guilty of indirect criminal contempt.', 'general', 'Commonwealth v. Walsh', 'https://www.courtlistener.com/opinion/5144920/', '5144920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, as the *621subpoena was served late, we hold that the trial court did not abuse its discretion when it declined to enforce the subpoena.', 'general', 'Commonwealth v. Walsh', 'https://www.courtlistener.com/opinion/5144920/', '5144920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We affirm.', 'general', 'Commonwealth v. Walsh', 'https://www.courtlistener.com/opinion/5144920/', '5144920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellant’s judgment of sentence.', 'sentencing', 'Commonwealth v. Walsh', 'https://www.courtlistener.com/opinion/5144920/', '5144920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the facts in the light most favorable to the government, we conclude that there is no basis for a determination that a reasonable person in Ms.', 'general', 'In re S.W.', 'https://www.courtlistener.com/opinion/5145177/', '5145177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because an essential element of the crime was not proved, we reverse S.', 'general', 'In re S.W.', 'https://www.courtlistener.com/opinion/5145177/', '5145177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Ms.', 'general', 'Davidson v. United States', 'https://www.courtlistener.com/opinion/5145358/', '5145358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under the circumstances of this case, a retrial for voluntary manslaughter is not barred.', 'general', 'Davidson v. United States', 'https://www.courtlistener.com/opinion/5145358/', '5145358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that a mistrial occurred when the jury was discharged without returning a verdict, it was not error for the court to update the docket sheet at a later date to reflect that fact.', 'mistrial', 'Davidson v. United States', 'https://www.courtlistener.com/opinion/5145358/', '5145358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury returned a verdict on the negligent homicide count, we conclude that the Double Jeopardy Clause of the Fifth Amendment shields Ms.', 'general', 'Davidson v. United States', 'https://www.courtlistener.com/opinion/5145358/', '5145358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'United States, for example, we concluded that “[t]he failure of counsel to object to the declarations of mistrial [could not], in the circumstances of the trial, be attributed to consent or acquiescence.', 'mistrial', 'Davidson v. United States', 'https://www.courtlistener.com/opinion/5145358/', '5145358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we concluded that the “[l]aek of objection in these unique circumstances must be attributed to lack of opportunity for objection rather than acquiescence.', 'general', 'Davidson v. United States', 'https://www.courtlistener.com/opinion/5145358/', '5145358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1095, 1098 (1987), we held that an attempt to murder three people by a single act of arson would constitute three separate offenses of attempted murder, for criminal homicide is defined as causing “the death of another human being.', 'general', 'Commonwealth v. Glass', 'https://www.courtlistener.com/opinion/5145465/', '5145465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 Upon our review of the record, we affirm.', 'general', 'Commonwealth v. Glass', 'https://www.courtlistener.com/opinion/5145465/', '5145465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though recognizing that the right to self-representation may be curtailed once a trial has commenced, we held that a trial judge must develop a record that makes clear “either the factual findings or the legal reasoning underlying the trial judge’s denial of [the defendant’s] mid-trial request.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/5145912/', '5145912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse on this ground, it is unnecessary to address Williams’ remaining claim.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/5145912/', '5145912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”10 Because the defendant in Christopher later expressly waived his request to represent himself, we affirmed the judgment of conviction based on that waiver.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/5145912/', '5145912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court committed plain error in failing to obtain a valid waiver of appellant’s jury trial right with respect to the felon-in-possession charge.', 'general', 'Fortune v. United States', 'https://www.courtlistener.com/opinion/5146096/', '5146096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recognizing the fundamental nature of the jury trial right, we held that certain safeguards must attend its waiver and reminded trial judges, pursuant to D.', 'general', 'Fortune v. United States', 'https://www.courtlistener.com/opinion/5146096/', '5146096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances, we held that the appellant’s “voluntary acquiescence” in the voir dire proceedings conducted outside his presence constituted a waiver and foreclosed his opportunity to be heard on appeal.', 'general', 'Fortune v. United States', 'https://www.courtlistener.com/opinion/5146096/', '5146096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances, we conclude that to allow the verdict by the trial judge to stand affects the fairness and integrity of the judicial proceedings in this case.', 'general', 'Fortune v. United States', 'https://www.courtlistener.com/opinion/5146096/', '5146096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court plainly erred in fading to seek a valid waiver of Mr.', 'general', 'Fortune v. United States', 'https://www.courtlistener.com/opinion/5146096/', '5146096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Fortune’s jury trial right, we reverse the felon-in-possession conviction, but find no basis for reversal of the remaining convictions.', 'general', 'Fortune v. United States', 'https://www.courtlistener.com/opinion/5146096/', '5146096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm in part and reverse in part.', 'general', 'Fortune v. United States', 'https://www.courtlistener.com/opinion/5146096/', '5146096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Due to the fact that the police had been investigating the suspected drug ring for years, had additional photographic and video surveillance as well as information from controlled buys, we find that there was proof, beyond a reasonable doubt, of the involvement in a widespread drug enterprise through a pattern of racketeering.', 'general', 'Commonwealth v. Cuevas', 'https://www.courtlistener.com/opinion/5146194/', '5146194') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Cuevas', 'https://www.courtlistener.com/opinion/5146194/', '5146194') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that appellants’ argument claiming the government failed to establish the malice element was so tenuous that it “merit[ed] little discussion,” we held that striking the boot, removing the lug nuts, jacking up the car, removing the wheel with the boot’s “jaw” attached, placing it in the trunk, and attempting to put a spare wheel and tire on the car reflected a “showing of actual malice.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/5146497/', '5146497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the trial court did not abuse its discretion in quashing the defense subpoena.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/5146497/', '5146497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that by causing third-party merchants to “reasonably believe” that the card holder (as principal) had “consented to the exercise of authority” that the woman purported to have (as agent), the card holder had clothed the woman with “apparent authority” to make the charges.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/5146497/', '5146497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the theft we affirm, rejecting appellants’ respective contentions that the evidence was insufficient for conviction.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/5146497/', '5146497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In (Robert) Thomas,50 we affirmed an MDP conviction for breaking and disassembling a vehicle immobilization unit (“boot”) from a car after the participants were warned by an off-duty policeman that they were “doing wrong.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/5146497/', '5146497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987), another case of a vehicle crash after a high-speed police chase, we affirmed MDP convictions, applying Charles.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/5146497/', '5146497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court’s definition of “contraband message” as “a message conveyed by any other means not authorized by the D.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/5146672/', '5146672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”21 Read in context of the purpose of the statute, which is to prohibit the introduction of contraband into a prison, we find that this provision is not vague and thus we affirm appellants’ convictions for introducing contraband into a prison.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/5146672/', '5146672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was sufficient evidence to satisfy the two-witness rule.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/5146672/', '5146672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm appellant Smith’s conviction for obstruction of justice.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/5146672/', '5146672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm appellant Thompson’s convictions for perjury.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/5146672/', '5146672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As stated supra, we affirm appellant Thompson’s convictions for perjury, thus we affirm her conviction for obstruction of justice.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/5146672/', '5146672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on Howes, supra, and Cleaver-Bascombe II, supra, we held that “[e]ven absent evidence of intentional misappropriation, disbarment is warranted in this case based on respondent’s other serious and pervasive misconduct alone, particularly his flagrant dishonesty.', 'general', 'In re Vohra', 'https://www.courtlistener.com/opinion/5146675/', '5146675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Board’s recommended sanction of a three-year suspension and fitness requirement falls within the acceptable range of outcomes.', 'general', 'In re Vohra', 'https://www.courtlistener.com/opinion/5146675/', '5146675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that § 871 of the Unemployment Compensation Law was intended by the legislature to exclusively cover situations where a person obtains unemployment benefits by false representations.', 'general', 'Commonwealth v. Nypaver', 'https://www.courtlistener.com/opinion/5146750/', '5146750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, all four factors establishing the existence of a conspiracy are present herein, and we conclude that the evidence was sufficient to support Appellant’s conspiracy conviction and thereby also was sufficient to support his theft conviction.', 'general', 'Commonwealth v. Nypaver', 'https://www.courtlistener.com/opinion/5146750/', '5146750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Herein, we conclude that the trial court did not palpably abuse its discretion in concluding that the verdict does not shock one’s sense of justice.', 'general', 'Commonwealth v. Nypaver', 'https://www.courtlistener.com/opinion/5146750/', '5146750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s ruling only if the verdict “is so contrary to the evidence as to shock one’s sense of justice.', 'general', 'Commonwealth v. Nypaver', 'https://www.courtlistener.com/opinion/5146750/', '5146750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Nypaver', 'https://www.courtlistener.com/opinion/5146750/', '5146750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The indictments were quashed, and we affirmed on appeal.', 'general', 'Commonwealth v. Nypaver', 'https://www.courtlistener.com/opinion/5146750/', '5146750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 We affirm.', 'general', 'Commonwealth v. Griffin', 'https://www.courtlistener.com/opinion/5146473/', '5146473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the forgoing reasons, we affirm Griffin’s judgment of sentence.', 'sentencing', 'Commonwealth v. Griffin', 'https://www.courtlistener.com/opinion/5146473/', '5146473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the trial court did not err in failing to suppress all physical evidence.', 'suppression', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/5146940/', '5146940') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Upon our review of the record, we affirm.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/5146940/', '5146940') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”26 Accordingly, we hold that Valentin properly requested the dispatch recording in his discovery request and the State failed to comply.', 'general', 'Valentin v. State', 'https://www.courtlistener.com/opinion/5147030/', '5147030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the dispatch recording fell within the scope of the defendant’s discovery request and Superior Court Criminal Rule 16.', 'general', 'Valentin v. State', 'https://www.courtlistener.com/opinion/5147030/', '5147030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '15 If we conclude that a discovery violation occurred, we apply a three-factor test that considers “(1) the centrality of the error to the case;', 'general', 'Valentin v. State', 'https://www.courtlistener.com/opinion/5147030/', '5147030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 obligations18 if we find that Valentin is entitled to a new trial because the State failed to produce the dispatch recording in response to Valentin’s discovery request.', 'general', 'Valentin v. State', 'https://www.courtlistener.com/opinion/5147030/', '5147030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the dispatch recording clearly falls within the scope of Valentin’s discovery request for “other information relating to the credibility of any prosecution witness.', 'general', 'Valentin v. State', 'https://www.courtlistener.com/opinion/5147030/', '5147030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we REVERSE the Superior Court’s judgment regarding the appealed convictions and REMAND for a new trial.', 'general', 'Valentin v. State', 'https://www.courtlistener.com/opinion/5147030/', '5147030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we REVERSE the Superior Court’s judgment regarding the Failure to Stop at the Command of a Police Officer and Reckless Driving charges and REMAND for a new trial in accordance with this Opinion.', 'general', 'Valentin v. State', 'https://www.courtlistener.com/opinion/5147030/', '5147030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we hold that the trial court did not err in allowing the police officers to offer lay opinion testimony on the meaning of certain street lingo and we reject King’s contention that the trial court erred in allowing his carjacking and robbery counts to be joined with Holmes’ obstruction count.', 'general', 'King v. United States', 'https://www.courtlistener.com/opinion/5147032/', '5147032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1976), we held that joinder of counts in a multi-defendant prosecution is proper under Rule 8(b):
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, per Garcia, the trial court did not abuse its discretion by allowing the two officers to testify as lay witnesses.', 'general', 'King v. United States', 'https://www.courtlistener.com/opinion/5147032/', '5147032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the trial court’s admission of the officers’ testimony and Holmes’ conviction.', 'general', 'King v. United States', 'https://www.courtlistener.com/opinion/5147032/', '5147032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the trial court’s denial of King’s Rule 8(b) severance motion.', 'general', 'King v. United States', 'https://www.courtlistener.com/opinion/5147032/', '5147032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that § 22-2511 is unconstitutional on its face and that'' the trial court erred in allowing appellant to be convicted of violating that statute.', 'general', 'Conley v. United States', 'https://www.courtlistener.com/opinion/5147276/', '5147276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that given the well-known dangerous proclivities of the breed, the owner’s “knowledge that his dogs were pit bulls should have moved him to inquire into his heightened obligations under the Act.', 'general', 'Conley v. United States', 'https://www.courtlistener.com/opinion/5147276/', '5147276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Before we conclude that § 22-2511 im-permissibly shifts the burden of persuasion with respect to the element of voluntary presence, we must consider further whether the respective burdens of persuasion may coexist.', 'general', 'Conley v. United States', 'https://www.courtlistener.com/opinion/5147276/', '5147276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”95 We conclude that the error in this case is plain.', 'general', 'Conley v. United States', 'https://www.courtlistener.com/opinion/5147276/', '5147276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the attorneys’ alleged failure to consult with a forensic pathologist or toxicologist, to present more evidence regarding the victim’s dominant hand, to investigate ballistics issues, appeal certain issues, and to object to the dismissal of jurors who indicated that they could not impose the death penalty did not prejudice the defendant during his trial’s guilt phase.', 'dismissal', 'Ploof v. State', 'https://www.courtlistener.com/opinion/5147093/', '5147093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Rule 61’s time limit applies only to the initial filing, and that Rule 61 grants Superior Court judges discretion to permit defendants to amend their motions when justice so requires.', 'general', 'Ploof v. State', 'https://www.courtlistener.com/opinion/5147093/', '5147093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that Ploof has failed to establish prejudice under Strickland, we do not address whether Trial Counsel’s conduct fell below an objective standard of reasonableness.', 'ineffective_assistance', 'Ploof v. State', 'https://www.courtlistener.com/opinion/5147093/', '5147093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 swpra, we conclude that Ploof has waived these claims because he did not address these arguments’ merits within the body of his opening brief.', 'general', 'Ploof v. State', 'https://www.courtlistener.com/opinion/5147093/', '5147093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we AFFIRM in part and REMAND in part so that the postconviction judge can supplement his opinion for further review.', 'general', 'Ploof v. State', 'https://www.courtlistener.com/opinion/5147093/', '5147093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we AFFIRM the Superior Court’s decision in part and REMAND in part for the Superior Court judge to supplement the record by reweighing the sum of the mitigating and aggravating evidence.', 'general', 'Ploof v. State', 'https://www.courtlistener.com/opinion/5147093/', '5147093') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By way of summary, we hold that Grant’s general rule of deferral to PCRA review remains the pertinent law on the appropriate timing for review of claims of ineffective assistance of counsel;', 'ineffective_assistance', 'Commonwealth v. Holmes', 'https://www.courtlistener.com/opinion/5147283/', '5147283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and we hold that trial courts retain their discretion to entertain such claims.', 'general', 'Commonwealth v. Holmes', 'https://www.courtlistener.com/opinion/5147283/', '5147283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we concluded that “[djeferring review of trial counsel ineffectiveness claims until'' the collateral review stage of the proceedings offers a petitioner the best avenue to effect his Sixth Amendment right to counsel.', 'ineffective_assistance', 'Commonwealth v. Holmes', 'https://www.courtlistener.com/opinion/5147283/', '5147283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Liston’s sentence and vacated and disapproved of the Superior Court’s holding that a reinstatement of appellate rights nunc pro tunc also requires granting the defendant the right to file post-sentence motions nunc pro tunc.', 'sentencing', 'Commonwealth v. Holmes', 'https://www.courtlistener.com/opinion/5147283/', '5147283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because: (1) the defendant had presented his ineffectiveness claims to the trial court;', 'ineffective_assistance', 'Commonwealth v. Holmes', 'https://www.courtlistener.com/opinion/5147283/', '5147283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Byrd', 'https://www.courtlistener.com/opinion/5284103/', '5284103') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Young', 'https://www.courtlistener.com/opinion/5281790/', '5281790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that those facts supported the circuit judge’s decision not to instruct on simple robbery.', 'general', 'Sweet v. State', 'https://www.courtlistener.com/opinion/5282022/', '5282022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 884 (2002), we held that a suspect’s spontaneous statement while in police custody is admissible and that it is irrelevant whether the statement was made before or after Miranda warnings because a spontaneous statement is not compelled or the result of coercion under the Fifth Amendment’s privilege against self-incrimination.', 'general', 'Sweet v. State', 'https://www.courtlistener.com/opinion/5282022/', '5282022') ON CONFLICT DO NOTHING;
