INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Sweet v. State', 'https://www.courtlistener.com/opinion/5282022/', '5282022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the circuit court’s decision on the admissibility of this evidence.', 'general', 'Sweet v. State', 'https://www.courtlistener.com/opinion/5282022/', '5282022') ON CONFLICT DO NOTHING;
