INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And so it in many ways looks like schizophrenia, but when the person is separated from the methamphetamine and the persisting symptoms resolve or are directly treated, we find that there is no underlying mental illness that’s just been exacerbated.', 'general', 'State v. Wright', 'https://www.courtlistener.com/opinion/5282644/', '5282644') ON CONFLICT DO NOTHING;
