INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '514, 2010 WL 2522736, where we held that when circumstantial evidence alone is relied upon, the evidence must exclude every reasonable hypothesis other than the guilt of the accused.', 'general', 'Warden v. State', 'https://www.courtlistener.com/opinion/5283126/', '5283126') ON CONFLICT DO NOTHING;
