INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that collateral estop-pel barred the rape prosecution because, in light of the State’s theory of the case in the first trial, a jury could not rationally find that the defendant forcibly raped the victim but did not commit the violence that resulted in her death.', 'general', 'State v. Cusumano', 'https://www.courtlistener.com/opinion/5284982/', '5284982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that Defendant failed to establish that the admission of Victim’s testimony resulted in manifest injustice or a miscarriage of justice.', 'general', 'State v. Cusumano', 'https://www.courtlistener.com/opinion/5284982/', '5284982') ON CONFLICT DO NOTHING;
