INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 430, 437 (2002), where we held that the definition of “purposely” encompasses the culpable mental state óf acting knowingly with extreme indifference, which requires deliberate conduct with a knowledge or awareness that one’s actions are practically certain to bring about the prohibited result.', 'general', 'Holloway v. State', 'https://www.courtlistener.com/opinion/5286873/', '5286873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that second-degree murder under Ark.', 'general', 'Holloway v. State', 'https://www.courtlistener.com/opinion/5286873/', '5286873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the intent of the jury to convict the defendant of first-degree murder was clear and that even though the jury erred in returning all three forms instead of one form as instructed, there was no inconsistency and any error was harmless.', 'general', 'Holloway v. State', 'https://www.courtlistener.com/opinion/5286873/', '5286873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reversed the trial court’s refusal to give jury instructions on the lesser-included offenses of second-degree murder and manslaughter based solely on the court’s reasoning that it was the defense’s right “to gamble” and not to request lesser-included offenses.', 'jury_instruction', 'Holloway v. State', 'https://www.courtlistener.com/opinion/5286873/', '5286873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Holloway v. State', 'https://www.courtlistener.com/opinion/5286873/', '5286873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Holloway failed to meet his burden of demonstrating that his trial counsel’s performance was deficient and that he was prejudiced by this deficient performance to the extent that he was deprived of a fair trial, the circuit court did not clearly err in denying his petition for postconviction relief without a hearing, and we affirm.', 'general', 'Holloway v. State', 'https://www.courtlistener.com/opinion/5286873/', '5286873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Because we conclude that Graham is entitled to qualified immunity on one claim and that collateral estoppel bars the remaining claims, we reverse and remand.', 'general', 'Graham v. Cawthorn', 'https://www.courtlistener.com/opinion/5286925/', '5286925') ON CONFLICT DO NOTHING;
