INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '146 Regarding the First Case, we hold that we need not address whether the court of appeals correctly evaluated Mr.', 'general', 'State v. Moa', 'https://www.courtlistener.com/opinion/5327396/', '5327396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the Second Case, we hold that the court of appeals was correct in concluding that there is no evidence that the district court relied on any improper information in imposing consecutive sentences.', 'sentencing', 'State v. Moa', 'https://www.courtlistener.com/opinion/5327396/', '5327396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '67 Thus, after reviewing those factors, we held that the imposition of three consecutive sentences of five years to life imprisonment was excessive where the defendant committed crimes unlikely to lead to serious injury or death, accepted responsibility for his actions, had very little criminal history, and demonstrated an ability to rehabilitate himself,68 Unlike the situation in Gal, the district court in this case did not make any findings about what it considered in imposing consecutive s...', 'sentencing', 'State v. Moa', 'https://www.courtlistener.com/opinion/5327396/', '5327396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '145 For the foregoing reasons, we conclude that there is no evidence that the district court actually relied on the prosecutor''s statements in imposing consecutive sentences.', 'sentencing', 'State v. Moa', 'https://www.courtlistener.com/opinion/5327396/', '5327396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'According ly, we conclude that the court of appeals did not err in upholding the district court''s order of consecutive sentences.', 'sentencing', 'State v. Moa', 'https://www.courtlistener.com/opinion/5327396/', '5327396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '53 Regarding the ex parte phone call and letter, we concluded that, even though the judge mentioned these items at the sentencing hearing, he did not state that he had considered them in issuing his decision.', 'sentencing', 'State v. Moa', 'https://www.courtlistener.com/opinion/5327396/', '5327396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '54 Because there was no affirmative representation by the judge, we concluded that there was no evidence that these items were "part of [his] deliberative process.', 'general', 'State v. Moa', 'https://www.courtlistener.com/opinion/5327396/', '5327396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that there is no reversible error in this case.', 'general', 'State v. Silvernail', 'https://www.courtlistener.com/opinion/8281085/', '8281085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, in Brown, we concluded that a district court’s decision to lock the courtroom doors during jury instructions did not violate a defendant’s right to a public trial.', 'jury_instruction', 'State v. Silvernail', 'https://www.courtlistener.com/opinion/8281085/', '8281085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Silvernail’s conviction.', 'general', 'State v. Silvernail', 'https://www.courtlistener.com/opinion/8281085/', '8281085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Silvernail’s conviction of first-degree premeditated murder.', 'general', 'State v. Silvernail', 'https://www.courtlistener.com/opinion/8281085/', '8281085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”1 We therefore hold, based on Brown and our application of the Lindsey factors, that the district court did not violate Silvernail’s right to a public trial when it locked the courtroom doors during the State’s closing argument.', 'general', 'State v. Silvernail', 'https://www.courtlistener.com/opinion/8281085/', '8281085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*606The element-by-element approach that I would adopt is consistent with Al-Naseer, in which we held that the “circumstantial evidence standard” applies to individual elements of a criminal offense that are proven by circumstantial evidence, even when the State proves the other elements of the offense by direct evidence.', 'general', 'State v. Silvernail', 'https://www.courtlistener.com/opinion/8281085/', '8281085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, the only way that demand can be met is if we reverse Silvernail’s conviction and remand for a new trial.', 'general', 'State v. Silvernail', 'https://www.courtlistener.com/opinion/8281085/', '8281085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court did not violate Zornes’s constitutional right to a public trial when it sequestered E.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the court’s admission of Zornes’s statement did not constitute reversible error.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court did not abuse its discretion when it admitted the disputed items.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After applying and weighing the Jones factors in this case, we hold that the district court did not abuse its discretion when it ruled that the State could impeach Zornes with three prior felony convictions if Zornes chose to testify at trial.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Olek, we held that objects connected to the crime scene or the investigation can be admitted;', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taylor, we held that the fact that the victim’s blood was on a die stamp, the purported murder weapon, tended to show that the die stamp was the murder weapon.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we held that the die stamp being the murder weapon was consistent with the medical examiner’s testimony that the murder weapon was a heavy, man-made object, which was sufficient''to connect the die stamp to the murder.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that none of the alleged errors requires reversal, we affirm.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court is best suited to protecting the integrity of the trial process by managing witnesses and the content of voir dire as the court sees fit.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying those holdings to the facts of this case, we conclude that the sequestration of E.', 'general', 'State v. Zornes', 'https://www.courtlistener.com/opinion/8281086/', '8281086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/5335132/', '5335132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM the superior court’s order denying Brown’s application for post-conviction relief.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/5335132/', '5335132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we hold that the judge did not abuse his discretion in imposing the sentence or in later refusing to reduce it.', 'sentencing', 'State v. Langley', 'https://www.courtlistener.com/opinion/5341141/', '5341141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today we affirm the order denying his Rule 35 motion.', 'general', 'State v. Langley', 'https://www.courtlistener.com/opinion/5341141/', '5341141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*669Based on these facts, we hold that, even including the income and assets of Suiter’s wife, Suiter was a needy person as defined by I.', 'general', 'State v. Suiter', 'https://www.courtlistener.com/opinion/5341969/', '5341969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Thus, we hold that the jury instruction should have listed the purpose for which the canal in question was being used.', 'jury_instruction', 'State v. Suiter', 'https://www.courtlistener.com/opinion/5341969/', '5341969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, this Court holds that the district court acted correctly in considering the property and income of Suiter’s wife for purposes of assessing whether he was a needy person entitled to appointed counsel.', 'general', 'State v. Suiter', 'https://www.courtlistener.com/opinion/5341969/', '5341969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons argued by Suiter, we conclude that the language listing the various purposes for conducting water does modify the term “canal.', 'general', 'State v. Suiter', 'https://www.courtlistener.com/opinion/5341969/', '5341969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the intent to injure or destroy element applies only to the second way of violating the statute and that the omission of that element in the jury instruction was not error.', 'jury_instruction', 'State v. Suiter', 'https://www.courtlistener.com/opinion/5341969/', '5341969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For guidance on remand, we conclude that the district court erred when it failed to include the type of canal, in the jury instruction, as an element of the malicious injury to a canal offense.', 'jury_instruction', 'State v. Suiter', 'https://www.courtlistener.com/opinion/5341969/', '5341969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/5341375/', '5341375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Idaho law does not prohibit successive probation periods for multiple convictions.', 'general', 'State v. Clapper', 'https://www.courtlistener.com/opinion/5342079/', '5342079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reason set forth below, we affirm.', 'general', 'State v. Clapper', 'https://www.courtlistener.com/opinion/5342079/', '5342079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the order of the district court affirming Clapper’s judgments of conviction and sentences as entered by the magistrate.', 'sentencing', 'State v. Clapper', 'https://www.courtlistener.com/opinion/5342079/', '5342079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial court’s common-law authority to impose cumulative sentences as well as suspend a sentence and impose probation, combined with the authority established in I.', 'sentencing', 'State v. Clapper', 'https://www.courtlistener.com/opinion/5342079/', '5342079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 188 (1959), this Court held that at least for purposes of determining a statute constitutionally valid which conferred jurisdiction upon the Family Court to adjudicate certain delinquency charges against a minor, that matter should be viewed as involving the exercise of criminal jurisdiction.', 'general', 'State v. Juvenile', 'https://www.courtlistener.com/opinion/5342349/', '5342349') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 2 We affirm the magistrate’s determination.', 'general', 'State v. Machan', 'https://www.courtlistener.com/opinion/5344453/', '5344453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 25 We affirm the magistrate’s ruling dismissing Mr.', 'dismissal', 'State v. Machan', 'https://www.courtlistener.com/opinion/5344453/', '5344453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the evidence was “not so complex that a juror [could not] keep separate its admissibility against” Mr.', 'general', 'State v. Denzmore', 'https://www.courtlistener.com/opinion/5444483/', '5444483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the trial court did not plainly err in sentencing Defendant, in accordance with the jury’s verdict and assessment of punishment, to forty-four years’ imprisonment.', 'sentencing', 'State v. Denzmore', 'https://www.courtlistener.com/opinion/5444483/', '5444483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Denzmore', 'https://www.courtlistener.com/opinion/5444483/', '5444483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the sentencing order at issue is not illegal on its face.', 'sentencing', 'Turman v. State', 'https://www.courtlistener.com/opinion/5445761/', '5445761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the notice issue, we hold that the petition, as a whole, sufficiently communicated the purpose of the petition to Tur-man and advised her of the potential punishments.', 'general', 'Turman v. State', 'https://www.courtlistener.com/opinion/5445761/', '5445761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that A.', 'general', 'A.W. v. State', 'https://www.courtlistener.com/opinion/5447759/', '5447759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'failed to raise the argument he now makes on appeal to the circuit court, we hold that it is not preserved for our review.', 'general', 'A.W. v. State', 'https://www.courtlistener.com/opinion/5447759/', '5447759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, we hold that A.', 'general', 'A.W. v. State', 'https://www.courtlistener.com/opinion/5447759/', '5447759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under Rule 403 the trial court did not abuse its discretion in admitting the evidence.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/5449292/', '5449292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing trial courts’ balancing determinations under Rule 403, we reverse only rarely and upon a clear demonstration of abuse of discretion.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/5449292/', '5449292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/5449292/', '5449292') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Croy has failed to persuade us that his enhanced sentence is inappropriate.', 'sentencing', 'Croy v. State', 'https://www.courtlistener.com/opinion/7166872/', '7166872') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Croy v. State', 'https://www.courtlistener.com/opinion/7166872/', '7166872') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm the judgment of the trial court.', 'general', 'Croy v. State', 'https://www.courtlistener.com/opinion/7166872/', '7166872') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Castillo’s forfeiture judgment.', 'general', 'United States v. Guillen-Cervantes', 'https://www.courtlistener.com/opinion/8441704/', '8441704') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we AFFIRM her forfeiture judgment.', 'general', 'United States v. Guillen-Cervantes', 'https://www.courtlistener.com/opinion/8441704/', '8441704') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Bacchus v. Bacchus', 'https://www.courtlistener.com/opinion/4989047/', '4989047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the current statute does not provide for the issuance of a series of temporary injunctions in lieu of a permanent injunction and because there was insufficient evidence presented at the hearing to support the issuance of a permanent injunction, we reverse.', 'general', 'Bacchus v. Bacchus', 'https://www.courtlistener.com/opinion/4989047/', '4989047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '816], this court held that the crime of burglary referred to in section 189 of the Penal Code was committed whenever a person entered a house with intent to commit grand or petit larceny or any felony.', 'general', 'People v. Talbot', 'https://www.courtlistener.com/opinion/5607465/', '5607465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it may not.', 'general', 'Olive v. Faulkner', 'https://www.courtlistener.com/opinion/8908327/', '8908327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 For the following reasons, we conclude that it cannot.', 'general', 'Ferko-Fox v. Fox', 'https://www.courtlistener.com/opinion/5146679/', '5146679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we conclude that Lancaster County’s informal practice fails to provide the parties to a PFA petition the procedural safeguards required to ensure justice, we cannot countenance the practice.', 'general', 'Ferko-Fox v. Fox', 'https://www.courtlistener.com/opinion/5146679/', '5146679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we find that this case falls within a recognized exception to the mootness doctrine.', 'general', 'Ferko-Fox v. Fox', 'https://www.courtlistener.com/opinion/5146679/', '5146679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the stated practice does not comply with § 6107(b) because it reduces the procedural safeguards established within the section and increases the risk of an erroneous deprivation of the respondent’s liberty.', 'general', 'Ferko-Fox v. Fox', 'https://www.courtlistener.com/opinion/5146679/', '5146679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the trial court did not abuse its discretion in finding that the evidence warranted the issuance of a final PFA order pursuant to § 6102(a).', 'general', 'Ferko-Fox v. Fox', 'https://www.courtlistener.com/opinion/5146679/', '5146679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that the trial court did not abuse its discretion by granting the requested continuance so that Wife could obtain counsel, we must emphasize that the resultant six-month delay between the March 2011 PFA petition and the conclusion of the evidentiary hearing during September 2011 is inexcusable.', 'general', 'Ferko-Fox v. Fox', 'https://www.courtlistener.com/opinion/5146679/', '5146679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ferko-Fox v. Fox', 'https://www.courtlistener.com/opinion/5146679/', '5146679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we affirm the November 21, 2011 order granting Wife’s petition for a final PFA.', 'general', 'Ferko-Fox v. Fox', 'https://www.courtlistener.com/opinion/5146679/', '5146679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we held that the court should allow the alleged indigent plaintiff to file his petition along with his motion to proceed as a poor person.', 'general', 'Trice v. State', 'https://www.courtlistener.com/opinion/5250703/', '5250703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'evidence which this Court held in State v.', 'general', 'Trice v. State', 'https://www.courtlistener.com/opinion/5250703/', '5250703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the mov-ant’s 29.', 'general', 'Trice v. State', 'https://www.courtlistener.com/opinion/5250703/', '5250703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that movant has not met this burden.', 'general', 'Trice v. State', 'https://www.courtlistener.com/opinion/5250703/', '5250703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we are satisfied beyond a reasonable doubt that any error in admitting this evidence did not contribute to the verdict obtained, we conclude that the error was harmless.', 'general', 'State v. Patton', 'https://www.courtlistener.com/opinion/5145461/', '5145461') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for further proceedings.', 'general', 'K.T. v. L.S.', 'https://www.courtlistener.com/opinion/5148652/', '5148652') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court’s decision to -deny Paternal Grandparents’ request for'' partial physical custody and remand for the trial court to enter immediately as a final order, the interim custody *1170order dated October 4, 2013 and entered October 7, 2013.', 'general', 'K.T. v. L.S.', 'https://www.courtlistener.com/opinion/5148652/', '5148652') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'Stein v. Maine Criminal Justice Academy', 'https://www.courtlistener.com/opinion/5148046/', '5148046') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 40] We conclude that our decision in Lewis lacks vitality and the capacity to serve the interests of justice.', 'general', 'Alexandre v. State', 'https://www.courtlistener.com/opinion/5143160/', '5143160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 47] We conclude that Alexandre is prejudiced by his kidnapping conviction and should receive post-conviction relief.', 'general', 'Alexandre v. State', 'https://www.courtlistener.com/opinion/5143160/', '5143160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 18] We recognized in Schofield that the 1995 amendment was intended to codify our decision in Lewis, in which we concluded that section 1252(2)(A)’s authorization of a sentence for “a definite period not to exceed 40 years” actually meant that there were “two tiers of sentences for Class A offenses: up to twenty years for most offenses, and between twenty and forty years for ‘the most heinous and violent crimes committed against a person.', 'sentencing', 'Alexandre v. State', 'https://www.courtlistener.com/opinion/5143160/', '5143160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying Apprendi and Blakely to the upper tier sentence imposed against the defendant in Schofield, we concluded that section 1252(2)(A), as amended in 1995, “cannot be constitutionally applied without affording the defendant an opportunity to have the fact-finder of her choice, judge or jury, determine whether, beyond a reasonable doubt, the crime was among the most heinous offenses committed against a person.', 'sentencing', 'Alexandre v. State', 'https://www.courtlistener.com/opinion/5143160/', '5143160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Alexandre’s convictions in a memorandum of decision, see State v.', 'general', 'Alexandre v. State', 'https://www.courtlistener.com/opinion/5143160/', '5143160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court noted that Apprendi was the law of the land at the time of Alexandre’s sentencing, and that Blakely had been decided ten months before we affirmed Alexandre’s convictions.', 'sentencing', 'Alexandre v. State', 'https://www.courtlistener.com/opinion/5143160/', '5143160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 17] We conclude that the court did not abuse its discretion in denying Newbert’s motion to withdraw his plea where a full year had elapsed since entry of the plea, where the court found that the State’s case would be severely prejudiced, and where Newbert’s assertion of innocence came without explanation a year after he had pleaded guilty to the charges.', 'plea', 'State v. Newbert', 'https://www.courtlistener.com/opinion/5143170/', '5143170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶20] On the facts before us, we conclude that the court did not reject New-bert’s plea agreement.', 'plea', 'State v. Newbert', 'https://www.courtlistener.com/opinion/5143170/', '5143170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the record Newbert created does not detail the exact terms of the agreement, we conclude that the agreement contained the following terms: Newbert would receive a sentence of not more that sixty days for each of the five state crimes;', 'sentencing', 'State v. Newbert', 'https://www.courtlistener.com/opinion/5143170/', '5143170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and the sentence.', 'sentencing', 'State v. Newbert', 'https://www.courtlistener.com/opinion/5143170/', '5143170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the evidence offered by the State at trial was both sufficient to prove notice and nontestimonial under the United State Supreme Court’s decision in Crawford v.', 'general', 'State v. Tayman', 'https://www.courtlistener.com/opinion/5143837/', '5143837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that the Secretary of State’s certification stands unrebut-ted on the record, and viewing, as we must, the evidence in the light most favorable to the State, we conclude that the trial court could have rationally found that the element of notice was proved beyond a reasonable doubt.', 'general', 'State v. Tayman', 'https://www.courtlistener.com/opinion/5143837/', '5143837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 177 (2004), we affirm Tayman’s conviction.', 'general', 'State v. Tayman', 'https://www.courtlistener.com/opinion/5143837/', '5143837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We affirm the judgment.', 'general', 'State v. Rickett', 'https://www.courtlistener.com/opinion/5143922/', '5143922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lemay has not argued that evidence of his prior convictions or incarceration was improperly admitted because of the joinder, and we conclude that the joinder did not affect the admissibility of this evidence.', 'general', 'State v. Lemay', 'https://www.courtlistener.com/opinion/5145260/', '5145260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Lemay', 'https://www.courtlistener.com/opinion/5145260/', '5145260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1281 (2009), wherein we reversed an order of *877the Board recommitting the parolee as a convicted parole violator following his guilty plea and conviction of the summary offense of harassment before a common pleas court judge.', 'plea', 'Chesson v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/5145323/', '5145323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments.', 'general', 'State v. Haag', 'https://www.courtlistener.com/opinion/5145359/', '5145359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 26] In light of this evidence, the jury could rationally have found beyond a reasonable doubt that Haag was guilty of kidnapping the two girls, and we affirm the verdicts.', 'general', 'State v. Haag', 'https://www.courtlistener.com/opinion/5145359/', '5145359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and sentences but remand for the administrative task of correcting his judgment of sentence and the amount of restitution ordered.', 'sentencing', 'People v. Bowling', 'https://www.courtlistener.com/opinion/8006774/', '8006774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and sentences, although we remand for the administrative task of correcting the restitution amount of $5,890.', 'sentencing', 'People v. Bowling', 'https://www.courtlistener.com/opinion/8006774/', '8006774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For those reasons, the panel concluded that “contrary to the PCR judge’s conclusion, we find that defendant failed to offer competent proof that he was misinformed of the consequences of his plea, State v.', 'plea', 'State v. Nuñez-Valdéz', 'https://www.courtlistener.com/opinion/7409126/', '7409126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that fact and expert testimony about the victim’s failure to wear a seat belt is irrelevant to both “but for” causation under N.', 'general', 'State v. Buckley', 'https://www.courtlistener.com/opinion/7409802/', '7409802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that fact and expert testimony regarding the claimed discrepancy between the utility pole placement and the guidelines in the DOT Roadway Design Manual is inadmissible on the issue of causation under N.', 'general', 'State v. Buckley', 'https://www.courtlistener.com/opinion/7409802/', '7409802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Appellate Division’s determination.', 'general', 'State v. Buckley', 'https://www.courtlistener.com/opinion/7409802/', '7409802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Appellate Division’s determination affirming the trial court’s denial of the State’s motion with respect to that issue.', 'general', 'State v. Buckley', 'https://www.courtlistener.com/opinion/7409802/', '7409802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the offense of first degree arson set forth in West Virginia Code § 61-3-1 (a) is not a lesser included offense of arson resulting in serious bodily injury which is set forth in West Virginia Code § 61-3-7(b).', 'general', 'State ex rel. Games-Neely v. Silver', 'https://www.courtlistener.com/opinion/8219201/', '8219201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Upon our careful review of the statutory offenses at issue, we conclude that the trial court’s decision to dismiss the charge of first degree arson based on double jeopardy concerns was in error.', 'dismissal', 'State ex rel. Games-Neely v. Silver', 'https://www.courtlistener.com/opinion/8219201/', '8219201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 Accordingly, we reverse.', 'general', 'State ex rel. Games-Neely v. Silver', 'https://www.courtlistener.com/opinion/8219201/', '8219201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Denson''s argument is premised upon our decision in Weed, in which we held that "the constitutional right of a criminal defendant to testify on his or her own behalf is a fundamental right;', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that in order to ensure that a defendant is knowingly, voluntarily, and intelli*705gently waiving his or her right to testify, circuit courts should conduct an on-the-record colloquy with the defendant, outside the jury''s presence, and inquire whether the defendant (1) is aware of his or her right to testify and (2) has discussed this right with his or her counsel.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that circuit courts are not required to conduct an on-the-record colloquy to determine whether a defendant is knowingly, voluntarily, and intelligently waiving his or her right not to testify.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That is, we conclude that circuit courts are not required to conduct an on-the-record colloquy to determine whether a defendant is knowingly, voluntarily, and intelligently waiving his or her right not to testify.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 434, ¶¶ 41-42, we conclude that the risk that a circuit court''s inquiry into a criminal defendant''s decision to testify will influence the defendant to waive his or her right to testify or will improperly interfere with defense strategy outweighs the benefit of mandating an on-the-record colloquy to ensure that the defendant is knowingly, voluntarily, and intelligently waiving his or her right not to testify.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, consistent with the remedy adopted in Klessig and Bangert, we conclude that once a defendant properly raises in a postconviction motion the issue of an invalid waiver of the right not to testify, the circuit court must conduct an evidentiary hearing to determine whether the defendant knowingly, voluntarily, and intelligently waived his or her right not to testify.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these facts to the relevant constitutional standard, we conclude that Denson knowingly, voluntarily, and intelligently waived his right not to testify.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that Denson knowingly, voluntarily, and intelligently waived his right not to testify.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that whether or not a circuit court conducts an on-the-record colloquy, once a defendant properly raises in a postconviction motion the issue of an invalid waiver of the right not to testify, the circuit court must conduct an evidentiary hearing to determine whether the defendant knowingly, voluntarily, and intelligently waived his or her right not to testify.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a criminal defendant''s right to testify is a fundamental right and that circuit courts are required to conduct an on-the-record colloquy to ensure that the defendant is knowingly, voluntarily, and intelligently waiving his or her right to testify.', 'general', 'State v. Denson', 'https://www.courtlistener.com/opinion/8238522/', '8238522') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, Klingelhoets does not dispute that the evidence at trial was sufficient to find him guilty of the felony count if we hold that Wis.', 'general', 'State v. Klingelhoets', 'https://www.courtlistener.com/opinion/8238713/', '8238713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Klingelhoets'' conviction did not require proof that he intended Shakes'' death, the evidence on that count was sufficient.', 'general', 'State v. Klingelhoets', 'https://www.courtlistener.com/opinion/8238713/', '8238713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and order.', 'general', 'State v. Klingelhoets', 'https://www.courtlistener.com/opinion/8238713/', '8238713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When applying great weight deference, we will sustain the agency''s statutory interpretation as long as it is reasonable, even if we conclude that another interpretation is equally or more reasonable.', 'general', 'Turnpaugh v. State Claims Board', 'https://www.courtlistener.com/opinion/8238732/', '8238732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Turnpaugh v. State Claims Board', 'https://www.courtlistener.com/opinion/8238732/', '8238732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 488, we reversed his conviction by a jury of violating Wis.', 'general', 'Turnpaugh v. State Claims Board', 'https://www.courtlistener.com/opinion/8238732/', '8238732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse on both aspects of the legal issues presented by this appeal — (A) whether Turnpaugh proved his innocence by the requisite standard, and (B) whether he had been "imprisoned" as a result of his conviction — because the Claims Board''s legal conclusions are wholly unreasonable and directly contravene the statute it is charged with administering.', 'general', 'Turnpaugh v. State Claims Board', 'https://www.courtlistener.com/opinion/8238732/', '8238732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the circuit court''s order and remand this matter to the Claims Board for an assessment of what "will equitably compensate" under the guidelines set out in Wis.', 'general', 'Turnpaugh v. State Claims Board', 'https://www.courtlistener.com/opinion/8238732/', '8238732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that section 609.', 'general', 'Vickla v. State', 'https://www.courtlistener.com/opinion/8279972/', '8279972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence imposed is not unreasonable, excessive, inappropriate, unjustifiably disparate, or not warranted by the findings of fact issued by the district court.', 'sentencing', 'Vickla v. State', 'https://www.courtlistener.com/opinion/8279972/', '8279972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Previously, we concluded that the United States Supreme Court’s decision in Blakely v.', 'general', 'Vickla v. State', 'https://www.courtlistener.com/opinion/8279972/', '8279972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude the 240-month statutory-maximum sentence imposed on Vickla is not unreasonable, excessive, inappropriate, unjustifiably disparate, or not warranted by the findings of fact issued by the district court, we reverse the decision of the court of appeals and reinstate the 240-month sentence ordered by the district court.', 'sentencing', 'Vickla v. State', 'https://www.courtlistener.com/opinion/8279972/', '8279972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, the State urges that we reverse the court of appeals.', 'general', 'Vickla v. State', 'https://www.courtlistener.com/opinion/8279972/', '8279972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse the decision of the court of appeals and reinstate Vickla’s 240-month sentence.', 'sentencing', 'Vickla v. State', 'https://www.courtlistener.com/opinion/8279972/', '8279972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, on the issues raised before the district court in this case, we conclude that the district court did not err by imposing $1,000 of restitution per direct victim under the identity theft statute.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/8279998/', '8279998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/8279998/', '8279998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the time deadline in subdivision 3(b) does not govern Gaiovnik’s challenge, we hold that his failure to submit a written challenge within 30 days after the sentencing hearing does not preclude Gaiovnik from challenging in a direct appeal the district court’s legal authority to award restitution when he raised this legal issue with the district court at the sentencing hearing.', 'sentencing', 'State v. Gaiovnik', 'https://www.courtlistener.com/opinion/8280018/', '8280018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the district court’s authority to order restitution is not limited to those situations where a victim submits a request for restitution, we affirm.', 'general', 'State v. Gaiovnik', 'https://www.courtlistener.com/opinion/8280018/', '8280018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the procedures set forth in section 611A.', 'general', 'State v. Gaiovnik', 'https://www.courtlistener.com/opinion/8280018/', '8280018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, reading subdivision 3(b) within the context of subdivision 3 as a whole and *649in order to avoid a constitutional question, we conclude that the requirements of subdivision 3(b) do not apply to a challenge to the district court’s legal authority to award restitution.', 'general', 'State v. Gaiovnik', 'https://www.courtlistener.com/opinion/8280018/', '8280018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the district court did not err in ordering Gaiovnik to pay restitution to Hollister as part of his sentence.', 'sentencing', 'State v. Gaiovnik', 'https://www.courtlistener.com/opinion/8280018/', '8280018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this time disparity violated equal protection.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Thompson, we applied the same three-part test utilized in Wegan and Nelson when we held that the omission of intentional torts from the survival statute violated equal protection.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that probable cause was shown because
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this disparity was not rational.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Garcia, we held that the purpose of probation for both groups was to incentivize individuals to abide by the rules, and there was no reason to provide one group with a greater incentive.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But in Bemthal, we concluded that we should defer further analysis because resolution of the issue was not dispositive.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we concluded that individuals in the two classifications were similarly situated, we proceeded to “consider whether, on the facts presented, there is a rational basis” for the distinction in granting jail credits.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was a legitimate purpose to the statute (part 3 of our test), but concluded that the distinction between the two types of liquor retailers was arbitrary (part 1), and that the state’s classification of the retailers was not relevant to the purpose of the Dram Shop Act (part 2).', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was no rational basis for this distinction, because the purpose of probation is the same for all of juveniles on probation.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that it was "particularly appropriate that we apply our stricter standard of rational basis review in a case such as this where the challenged classification appears to impose a substantially disproportionate burden on the very class of persons whose history inspired the principles of equal protection.', 'general', 'State v. Cox', 'https://www.courtlistener.com/opinion/8280128/', '8280128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “[t]he context of the confrontation and the other person’s act of reaching behind his back provided a motive for [Holliday] to shoot at someone in that person’s group, thereby supporting the district court’s finding of premeditation.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this fact alone “permits an inference that defendant had sufficient time to contemplate his actions before carrying them out.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Austin, we held that premeditation was established by the amount of time it took to walk up a “short flight of stairs.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this was evidence of premeditation.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Based on all the evi*738dence, we conclude that this theory is not reasonable.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, even when we consider only the motive and nature-of-the-killing evidence occurring after Moss threatened to call the police, we conclude that the killing was not done as a “rash impulse” but was premeditated.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any failure by the district court to consider manslaughter offenses could not have affected Palmer’s substantial rights;', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the evidence presented to the district court was sufficient to convict Palmer of first-degree premeditated murder, we affirm his conviction.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Clark, we concluded that the nature of the killing indicated premeditation because Clark shot the victim twice.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Palmer', 'https://www.courtlistener.com/opinion/8280303/', '8280303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the court of appeals properly applied the 2-year time limit in Minn.', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Sanchez brought his petition for postconvietion relief more than 2 years after his interests-of-justice claim arose, we hold that subdivision 4(c) prevents Sanchez from invoking the interests-of-justice exception in subdivision 4(b)(5).', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 Because we conclude that Sanchez has not satisfied the high standard necessary for the limitations period to be tolled, we hold that Sanchez’s petition is untimely under Minn.', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that “Minn.', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Noske, we held that a claim for attorney malpractice in a criminal matter arose only after a court concluded that the attorney had rendered ineffective assistance of counsel and vacated the plaintiffs conviction.', 'ineffective_assistance', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But even if we held that Sanchez’s attorney’s alleged ineffective assistance of counsel could be an extraordinary circumstance for purposes of application of tolling, Sanchez clearly did not pursue his postconviction relief rights diligently.', 'ineffective_assistance', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a statute that limited the time a certain class of criminal defendants had to take an appeal was unconstitutional.', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2012), released today, we held that Minn.', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Because we conclude that Sanchez’s petition was untimely, we affirm.', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the same objective standard we apply in the context of the accrual of other statutes of limitations should also apply to the limitations period in the posteonviction statute.', 'general', 'Sanchez v. State', 'https://www.courtlistener.com/opinion/8280637/', '8280637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the aggravated-forgery statute does not apply to Reynua’s conduct of using a false Minnesota identification card.', 'general', 'State v. Reynua', 'https://www.courtlistener.com/opinion/8280418/', '8280418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state, for example, is not barred from prosecuting the crime of display or possession of a fictitious or fraudulently altered Minnesota identification card, Minn.', 'general', 'State v. Reynua', 'https://www.courtlistener.com/opinion/8280418/', '8280418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'State v. Reynua', 'https://www.courtlistener.com/opinion/8280418/', '8280418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that section 609.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the totality-of-the-circumstances test, we conclude that the State’s legitimate governmental interests in conducting a search of Johnson to collect a biological specimen for criminal identification purposes outweigh appellant’s reduced expectation of privacy following his misdemeanor conviction arising out of the same set of circumstances as his felony charge.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the physical intrusion of Johnson’s bodily integrity to acquire the DNA sample is minimal, especially when compared to the other intrusions Johnson is subjected to as part of his probation, including random urinalysis.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Like the court in Amerson, we conclude that Johnson’s status as a probationer significantly reduced his expectation of privacy in his identity.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '12 Balancing the State’s legitimate governmental interests in DNA collection against Johnson’s reduced expectation of privacy in his identity, we conclude that, as applied here, the statutorily-mandated collection of Johnson’s DNA for criminal identification purposes pursuant to section 609.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that when a person is convicted of a misdemeanor offense that arises out of the same set of circumstances as a felony charge and that person’s sentence includes probation with conditions such as random urinalyses, there is a significant reduction in that person’s expectation of privacy in his or her identity.', 'sentencing', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the totality-of-the-circumstances test to the facts of this case, we conclude that DNA collection by buccal swab for identification purposes is not an unreasonable search.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the statutorily-mandated collection of Johnson’s DNA pursuant to section 609.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that Johnson is not similarly situated to misdemeanants without a felony charge, and therefore his equal protection claim fails.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Knights-Samson totality-of-the-circumstances test, we concluded that “as a result of his felony burglary conviction, the warrantless, suspi-cionless taking of Bartylla’s DNA pursuant to Minn.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/8280545/', '8280545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the other hand, no error has been alleged or discovered relative to the vandalism conviction, which we affirm.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/5270061/', '5270061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that light, we hold that a restitution hearing under Minn.', 'general', 'State v. Maddox', 'https://www.courtlistener.com/opinion/8280902/', '8280902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the restitution hearing was not meaningful because Maddox did not have the benefit of assistance of counsel at the hearing.', 'general', 'State v. Maddox', 'https://www.courtlistener.com/opinion/8280902/', '8280902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, for a defendant to challenge restitution at a restitution hearing under section 611A.', 'general', 'State v. Maddox', 'https://www.courtlistener.com/opinion/8280902/', '8280902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court violated Maddox’s right to counsel by not obtaining his waiver of that right before proceeding with the restitution hearing under section 611A.', 'general', 'State v. Maddox', 'https://www.courtlistener.com/opinion/8280902/', '8280902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree that the district court violated appellant’s right to counsel, we need not reach the remaining issues, and we reverse and remand for a new restitution hearing.', 'general', 'State v. Maddox', 'https://www.courtlistener.com/opinion/8280902/', '8280902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse based on the district court’s failure to obtain a waiver of Maddox’s right to counsel, we need not reach Maddox’s arguments that the district court failed to comply with the restitution-hearing procedures under section 611A.', 'general', 'State v. Maddox', 'https://www.courtlistener.com/opinion/8280902/', '8280902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the challenged exhibits, our identification of certain characteristics that appear in multiple communications identifying different senders, and our application of Rule 901(b)(4), we hold that a reasonable fact finder could have found that the telephone number C.', 'general', 'Manuel v. State', 'https://www.courtlistener.com/opinion/5281392/', '5281392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a rational fact finder could have found that the State proved each essential element of the offense beyond a reasonable doubt.', 'general', 'Manuel v. State', 'https://www.courtlistener.com/opinion/5281392/', '5281392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a threatening visual or physical proximity is not an element of stalking.', 'general', 'Manuel v. State', 'https://www.courtlistener.com/opinion/5281392/', '5281392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that this is one of those rare cases in which the challenged conduct was “so outrageous that no competent attorney would have engaged in it.', 'general', 'Manuel v. State', 'https://www.courtlistener.com/opinion/5281392/', '5281392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But, even absent waiver, we conclude that the sentence of which Appellant complains does not constitute cruel and unusual punishment.', 'sentencing', 'Manuel v. State', 'https://www.courtlistener.com/opinion/5281392/', '5281392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Manuel v. State', 'https://www.courtlistener.com/opinion/5281392/', '5281392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having overruled Appellant’s seven issues, we affirm the judgment of the trial court.', 'general', 'Manuel v. State', 'https://www.courtlistener.com/opinion/5281392/', '5281392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, even if the trial court erroneously admitted Johnson’s juvenile criminal record, we hold that he was not prejudiced by that evidence.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/5282793/', '5282793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on this point.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/5282793/', '5282793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With this modification, we affirm on this point as well.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/5282793/', '5282793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we held that the challenging parties had not met their burden of showing that the ordinance violated the Fourth Amendment in all of its applications because, on its face, the statute allowed a judge to require individualized suspicion in issuing an administrative warrant.', 'search_seizure', 'State v. Ness', 'https://www.courtlistener.com/opinion/8281124/', '8281124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, violates procedural due process in all of its applications, and because we conclude that the statute does *180not encourage arbitrary and discriminatory enforcement, we affirm.', 'general', 'State v. Ness', 'https://www.courtlistener.com/opinion/8281124/', '8281124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the standards limiting a judge’s discretion in issuing a domestic abuse no contact order are at least the same as, if not greater than, the standards that must be satisfied in order for a judge to issue an OFP or HRO, which Ness effectively concedes are constitutionally sufficient.', 'general', 'State v. Ness', 'https://www.courtlistener.com/opinion/8281124/', '8281124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, based on our analysis of the totality of the circumstances, we hold that Brooks voluntarily consented to the searches at issue in this case.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/8281232/', '8281232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that Brooks consented based on our analysis of the *573totality of the circumstances of this case.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/8281232/', '8281232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Brooks has not demonstrated that Minne-sofa’s implied consent statute is unconstitutional.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/8281232/', '8281232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We followed the analysis in Neville when we held that Minnesota’s implied consent law, even though it makes it a crime to refuse testing, also does not coerce a driver into testifying against himself.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/8281232/', '8281232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Henning, we held that a statute that authorized the police to stop a car with “whiskey plates,” which were license plates issued to a person who had their driver’s license suspended for alcohol-related offenses, was unconstitutional.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/8281232/', '8281232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Brooks consented to the searches at issue, and thus that a warrant was unnecessary, we affirm.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/8281232/', '8281232') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'reason, we concluded that the defendant was provided with sufficient notice of count II.', 'general', 'People v. Dryer', 'https://www.courtlistener.com/opinion/4865178/', '4865178') ON CONFLICT DO NOTHING;
