INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the defendant was “in custody” while on furlough, and that his unauthorized departure from the limits of that custody constituted an escape.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2079852/', '2079852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with these courts, and we hold that, as an appellate court, this court has the authority to find trial court error harmless notwithstanding the government’s failure to claim harmlessness.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that where, as here, the government has failed to claim in timely fashion that erroneous admission of hearsay evidence was harmless in the traditional sense, we should apply the harmless error doctrine only when harmlessness is obvious.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in Randolph’s case, the issue of harmlessness is at least debatable, and that the government should not be relieved of its waiver.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, applying the rigorous standard that courts have adopted for cases in which the government has failed to make a timely claim of harmlessness, we conclude that the error in Randolph’s case was prejudicial, not harmless, and that Randolph’s convictions (except of CPWOL) must be reversed.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, however, we conclude that it is appropriate to affirm Stewart’s conviction notwithstanding that failure.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that reversal of Stewart’s convictions is warranted.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of this evidence violated the Confrontation Clause,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, after ordering supplemental post-argument submissions, we concluded that the evidence was insufficient to support the defendant’s conviction as an AAF to any offense at all.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Randolph’s convictions for armed first-degree murder, kidnapping, and PFCV, but affirm his conviction of CPWOL, because that conviction was not affected by the trial court’s erroneous ruling.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we reverse Randolph’s principal convictions on other grounds, an issue that he raises on this appeal may arise again at a retrial.', 'general', 'Randolph v. United States', 'https://www.courtlistener.com/opinion/2081827/', '2081827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, quite apart from the state of mind required to establish the underlying constitutional violationin that case, a violation of due process, 489 U.', 'general', 'Board of the County Commissioners of Bryan County v. Brown', 'https://www.courtlistener.com/opinion/118104/', '118104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Court of Appeals'' decision cannot be squared with our recognition that, in enacting § 1983, Congress did not intend to impose liability on a municipality unless deliberate action attributable to the municipality itself is the "moving force" behind the plaintiff''s deprivation of federal rights.', 'general', 'Board of the County Commissioners of Bryan County v. Brown', 'https://www.courtlistener.com/opinion/118104/', '118104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the statute''s imposition of liability on one who "subjects [a person], or causes [that person] to be subjected," to a deprivation of federal rights, we concluded that it "cannot be easily read to impose liability vicariously on governing bodies solely on the basis of the existence of an employeremployee relationship with a tortfeasor.', 'general', 'Board of the County Commissioners of Bryan County v. Brown', 'https://www.courtlistener.com/opinion/118104/', '118104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on Owen and Newport, we concluded that a final decisionmaker''s adoption of a course of action "tailored to a particular situation and not intended to control decisions in later situations" may, in some circumstances, give rise to municipal liability under § 1983.', 'general', 'Board of the County Commissioners of Bryan County v. Brown', 'https://www.courtlistener.com/opinion/118104/', '118104') ON CONFLICT DO NOTHING;
