INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the defendant''s alleged conduct falls within the definition of solicitation of prostitution under Wis.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
