INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the circuit court and the court of appeals, we conclude that the statutes the defendant is charged with violating encompass the conduct alleged at the preliminary examination.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the definition of prostitution in § 944.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the court of appeals and the circuit court, we conclude that the language of Wis.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agree with this reasoning in principle, we conclude that it is even clearer that the alleged threats constitute threats to the witness''s "calling or trade.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition to these threats to terminate the student''s studies, we conclude that the threats to end financial support may also have been threats to injure the student''s "person, property, business, profession, calling or trade" under the unique circumstances of this case.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While this might not have resulted in a physical injury to his person, we conclude that it would constitute "any injury to the person" within the meaning of the statute.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals.', 'general', 'State v. Kittilstad', 'https://www.courtlistener.com/opinion/2093976/', '2093976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1065 (1977), where we held that in robbery-murders the felony murder and pecuniary gain aggravators should be merged, appellant''s claim is without merit.', 'general', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the testimony of the victim''s brother, we conclude that it did not violate the dictates of section 921.', 'general', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this testimony, coupled with the fact that appellant and victim knew each other, and the appellant was aware that the victim was pressing charges against him for his prior theft, is sufficient to uphold the trial court''s finding of the avoid arrest aggravator.', 'general', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that the existence of the two aggravators is sufficient to outweigh the very little weight given to the nonstatutory mitigating circumstances set forth in the sentencing order.', 'sentencing', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 393 (1977), we concluded that when a sentencing judge intends to use any information not presented in open court as a factual basis for a sentence, he must advise the defendant of what it is and afford the defendant an opportunity to rebut it.', 'sentencing', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the trial court did not abuse its discretion in finding no discovery violation on the part of the State.', 'general', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Consequently, we find that the trial court did not err in giving the "unexplained possession" jury instruction.', 'jury_instruction', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that it was error for the trial court to utilize these out-of-court deposition statements, we find these errors are harmless beyond a reasonable doubt.', 'general', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that Consalvo''s death sentence is not disproportionate to other cases.', 'sentencing', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have jurisdiction under article V, section 3(b)(1), Florida Constitution, and we affirm the convictions and sentence.', 'sentencing', 'Consalvo v. State', 'https://www.courtlistener.com/opinion/1952514/', '1952514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we conclude that the lower court correctly denied the Motion.', 'general', 'State v. Lorenzo', 'https://www.courtlistener.com/opinion/1389276/', '1389276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm the judgment of the district court.', 'general', 'State v. Fintel', 'https://www.courtlistener.com/opinion/2100441/', '2100441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 655 (“We hold that all evidence obtained by searches and seizures in violation of the Constitution is, by that same authority, inadmissible in a state court”).', 'general', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '34 Today, for the first time, this Court holds that although the Constitution has been violated, no court should do anything about it at any time and in any proceeding.', 'general', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Lopez’ conviction for child abuse, a class 2 felony, and the trial court’s sentence of an aggravated term of 22 years’ imprisonment based on that conviction.', 'sentencing', 'State v. Lopez', 'https://www.courtlistener.com/opinion/2614939/', '2614939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the record before us, we conclude that it did not.', 'general', 'State v. Womack', 'https://www.courtlistener.com/opinion/2615023/', '2615023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we find that defendant’s nonviolent flight constituted an insufficient factual basis upon which to charge defendant with resisting arrest.', 'general', 'State v. Womack', 'https://www.courtlistener.com/opinion/2615023/', '2615023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the legislature did not intend to proscribe defendant’s conduct under the resisting arrest statute, we reverse defendant’s conviction on that count and remand to the trial court with directions to dismiss the charge of resisting arrest.', 'dismissal', 'State v. Womack', 'https://www.courtlistener.com/opinion/2615023/', '2615023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm Watts’s conviction and sentence.', 'sentencing', 'Watts v. State', 'https://www.courtlistener.com/opinion/5104922/', '5104922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm Watts’s conviction and sentence.', 'sentencing', 'Watts v. State', 'https://www.courtlistener.com/opinion/5104922/', '5104922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the verdict, we find that the verdict was not so contrary to the overwhelming weight of the evidence that to allow it to stand would sanction an unconscionable injustice.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/5104817/', '5104817') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this was not direct testimony of the value of the rims, we find that it circumstantially provided a basis from which the jury could infer that the rims were worth at least $250 because of the amount of the purchase price”).', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/5104817/', '5104817') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did have jurisdiction to hear the appeal.', 'general', 'State v. Gissel', 'https://www.courtlistener.com/opinion/2615092/', '2615092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In an earlier opinion in this case we agreed with the state on its first point and we held that the district court was without jurisdiction to hear the appeal from the magistrate’s division.', 'general', 'State v. Gissel', 'https://www.courtlistener.com/opinion/2615092/', '2615092') ON CONFLICT DO NOTHING;
