INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '60 For the reasons that follow, we conclude that in this case the trial court applied incori''ect legal principles, and did not fully consider the proffer presented under the three-part analysis we set forth in Dycis.', 'general', 'Benn v. United States', 'https://www.courtlistener.com/opinion/5144034/', '5144034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we are not generally bound by the rulings in another jurisdiction, we find that the New York high court''s analysis is thorough and persuasive.', 'general', 'Benn v. United States', 'https://www.courtlistener.com/opinion/5144034/', '5144034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed his convictions because the trial court had refused to allow appellant’s mother to retake the stand after she had sat in on the trial during the testimony of her son in contravention of the trial judge’s rule on witnesses.', 'general', 'Benn v. United States', 'https://www.courtlistener.com/opinion/5144034/', '5144034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dyas, we affirmed the exclusion of expert evidence regarding the effects of stress, lapse of time, suggestion by persons in authority and a prior identification by the witness, after the trial court found that such expert evidence was not “beyond the ken of the average layman” and would not assist the jury.', 'general', 'Benn v. United States', 'https://www.courtlistener.com/opinion/5144034/', '5144034') ON CONFLICT DO NOTHING;
