INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any sanction other than disbarment would not provide the necessary protection for the public, serve as a deterrent to the legal profession, or preserve the public’s trust and confidence in the integrity of the disciplinary process for Delaware lawyers.', 'general', 'In re Member of the Bar of the Supreme Court of Delaware', 'https://www.courtlistener.com/opinion/5145163/', '5145163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, while we find that the Supreme Court may find Davis’s creation of a settlement services company and speaking at seminars to realtors and lenders to be beyond what a suspended real estate attorney should have done, we cannot recommend that the Court find that Davis knowingly violated the Suspension Order by engaging in these activities.', 'general', 'In re Member of the Bar of the Supreme Court of Delaware', 'https://www.courtlistener.com/opinion/5145163/', '5145163') ON CONFLICT DO NOTHING;
