INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm both the findings of fact and conclusions of law reached by the Board on the basis of and for the reasons stated in its Violation Report.', 'general', 'In re Member of the Bar of the Supreme Court of Delaware', 'https://www.courtlistener.com/opinion/5145163/', '5145163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the bias impeachment was proper and that the defense had proffered a sufficient foundation.', 'general', 'Longus v. United States', 'https://www.courtlistener.com/opinion/5145602/', '5145602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we do not come to a final resolution of appellant’s Fifth Amendment claim, we conclude that his Sixth Amendment right to confrontation was violated and that his defense was prejudiced as a result.', 'general', 'Longus v. United States', 'https://www.courtlistener.com/opinion/5145602/', '5145602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s right to confront Detective Brown by exposing his various biases was violated by the limitations imposed on cross-examination and introduction of evidence about the detective’s involvement in witness coaching in the Club U investigation.', 'general', 'Longus v. United States', 'https://www.courtlistener.com/opinion/5145602/', '5145602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For instance, in McNeely, we noted that “the relative severity of the punishment, a fine of up to $20,000 and imprisonment of up to two years, favors the imposition of a mens rea requirement,” but we held that owning a pit bull was a strict liability crime.', 'general', 'Loftus v. District of Columbia', 'https://www.courtlistener.com/opinion/5145546/', '5145546') ON CONFLICT DO NOTHING;
