INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree with the trial court’s interpretation of § 3705(a), we affirm the trial
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a nursing home and affiliated entities are subject to potential direct liability for negligence, where the requisite resident-entity relationship exists to establish that the entity owes the resident a duty of care, as we explain infra.', 'general', 'Scampone v. Highland Park Care Center, LLC', 'https://www.courtlistener.com/opinion/5145950/', '5145950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'An example of the latter type of case is Tonsic, a matter in which this Court held that both an operating surgeon and a hospital may be held vicariously liable for the negligence of the hospital''s surgical personnel.', 'general', 'Scampone v. Highland Park Care Center, LLC', 'https://www.courtlistener.com/opinion/5145950/', '5145950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Superior Court in part, upon reasoning different from that articulated by the Superior Court, and we remand to the trial court for proceedings consistent with this Opinion.', 'general', 'Scampone v. Highland Park Care Center, LLC', 'https://www.courtlistener.com/opinion/5145950/', '5145950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Superior Court’s decision to reverse the grant of a nonsuit with respect to Grane Healthcare and to affirm the denial of a nonsuit with respect to Highland Park, and remand this matter to the trial court for further proceedings.', 'general', 'Scampone v. Highland Park Care Center, LLC', 'https://www.courtlistener.com/opinion/5145950/', '5145950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the above-summarized evidence was sufficient to establish that Ap-pellee was under the influence of a drug or combination of drugs to a degree that impaired her ability to safely drive.', 'general', 'Commonwealth v. Griffith', 'https://www.courtlistener.com/opinion/5144762/', '5144762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing all the evidence admitted in the instant case, we conclude that it is sufficient to sustain Appellee’s *1240conviction under subsection 3802(d)(2).', 'general', 'Commonwealth v. Griffith', 'https://www.courtlistener.com/opinion/5144762/', '5144762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Superior Court erroneously concluded that expert testimony was required under this statutory provision, we reverse.', 'general', 'Commonwealth v. Griffith', 'https://www.courtlistener.com/opinion/5144762/', '5144762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, considering the reasonableness of counsel’s investigation, the mitigation evidence that was actually presented, the additional or different mitigation evidence that could have been discovered and presented, and the Commonwealth’s failure to muster any relevant argument in defense of counsel’s performance, we hold that counsel’s performance related to the development and presentation of mitigating evidence was constitutionally deficient.', 'general', 'Commonwealth v. Sepulveda', 'https://www.courtlistener.com/opinion/5145856/', '5145856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a case involving a similar Bat-son/Strickland claim premised upon raw data and hindsight, we held that there was no gender-based purposeful discrimination when the prosecutor removed nine female potential jurors, four women served on the jury, and the prosecutor accepted four women who were later struck by the defense.', 'ineffective_assistance', 'Commonwealth v. Sepulveda', 'https://www.courtlistener.com/opinion/5145856/', '5145856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1124In this case, given appellant’s existing accounts- of his actions, the physical evidence, and the weakness of the now-proffered evidence as support for diminished capacity, we conclude that appellant has failed to prove that counsel was ineffective for not pursuing a diminished capacity defense.', 'ineffective_assistance', 'Commonwealth v. Sepulveda', 'https://www.courtlistener.com/opinion/5145856/', '5145856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under such circumstances, we conclude that appellant has not demonstrated a reasonable probability that, if only counsel would have introduced supporting expert testimony on the subjective half of his imperfect defense of others claim, the jury would have credited that his perceptions, if *1127genuinely held, were objectively reasonable.', 'general', 'Commonwealth v. Sepulveda', 'https://www.courtlistener.com/opinion/5145856/', '5145856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the evidence of the experts offered at the PCRA hearing established the possibility of additional mitigating circumstances, we conclude that the better course is to have the PCRA court conduct the prejudice inquiry in the first instance, assisted by relevant advocacy from both sides.', 'general', 'Commonwealth v. Sepulveda', 'https://www.courtlistener.com/opinion/5145856/', '5145856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '31 When this scant argument is coupled with the failure to inquire into counsel’s strategy at the PCRA hearing, we conclude that appellant’s ineffectiveness claim relating to the accomplice liability instruction fails as appellant has not established that counsel’s performance was deficient.', 'ineffective_assistance', 'Commonwealth v. Sepulveda', 'https://www.courtlistener.com/opinion/5145856/', '5145856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we find that the claim fails for different reasons.', 'general', 'Commonwealth v. Sepulveda', 'https://www.courtlistener.com/opinion/5145856/', '5145856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this issue of first impression, we hold that because Duran was charged with a crime involving a reckless act, rather than an intentional act, the affirmative defense of self-defense is not available to her.', 'general', 'Duran v. State', 'https://www.courtlistener.com/opinion/2615526/', '2615526') ON CONFLICT DO NOTHING;
