INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 Therefore, on this record, we conclude that further inquiry was necessary for the trial court to meet its obligation to “put to defense counsel (and to the defendant, if necessary) — on the record — specific questions designed to elicit whether or not the .', 'general', 'Portillo v. United States', 'https://www.courtlistener.com/opinion/5146277/', '5146277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we agree that some of appellant’s convictions merge, and therefore must be vacated, we conclude that resentencing is unnecessary.', 'sentencing', 'Portillo v. United States', 'https://www.courtlistener.com/opinion/5146277/', '5146277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that appellant’s concerns were sufficiently addressed by a dialogue between the trial court and counsel, which “reveal[ed] that in response to *1254appellant’s letter counsel visited appellant, wrote him a letter and conversed at length with him regarding his case and concerns, explained to appellant the plea process, and provided him a copy of the case file.', 'plea', 'Portillo v. United States', 'https://www.courtlistener.com/opinion/5146277/', '5146277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse outright when there is obvious prejudice or when it is clear from the record that pretrial counsel was ineffective.', 'ineffective_assistance', 'Portillo v. United States', 'https://www.courtlistener.com/opinion/5146277/', '5146277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this definition surely applies under both statutes.', 'general', 'Fadero v. United States', 'https://www.courtlistener.com/opinion/5146112/', '5146112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 Finding no error, we affirm all convictions except for ADW, which merges with appellant’s conviction for APOWA6 and must be remanded, accordingly, for the trial court to vacate.', 'general', 'Fadero v. United States', 'https://www.courtlistener.com/opinion/5146112/', '5146112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons we affirm all convictions, although as noted69 we remand with instructions for the trial court to vacate Fadero’s conviction for ADW, which merges into his APOWA conviction.', 'general', 'Fadero v. United States', 'https://www.courtlistener.com/opinion/5146112/', '5146112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 818, we concluded that the "natural and probable consequences” language contained in a standard aiding and abetting instruction impermissibly relieved the government of the burden of showing that the accomplice had the mens rea required to be guilty of the offense.', 'general', 'In re D.N.', 'https://www.courtlistener.com/opinion/5146396/', '5146396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“We are not to set aside the trial court’s judgment, except for errors of law, unless we find that it was plainly wrong or unsupported by the evidence.', 'general', 'In re D.N.', 'https://www.courtlistener.com/opinion/5146396/', '5146396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), for example, this court held that the law treats accomplices the same as principals for purposes of imposing felony murder liability.', 'general', 'In re D.N.', 'https://www.courtlistener.com/opinion/5146396/', '5146396') ON CONFLICT DO NOTHING;
