INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the possibility of probation revocation is a collateral consequence to a guilty plea, and the fact that a defendant was not informed that he faces such a possibility in an unrelated criminal case does not undermine the validity of the plea.', 'plea', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we held that the appellant must be permitted to withdraw his plea.', 'plea', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), upon which the dissent relies for the proposition that Appellant’s responses in his written'' and oral guilty plea colloquies bind Appellant to his representations therein, this Court held that a defendant "may not assert grounds for withdrawing the plea that contradict statements made when he pled.', 'plea', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we concluded that, due to counsel’s “ignorance of relevant sentencing law, counsel’s advice was legally unsound and devoid of any reasonable basis designed to effectuate [the appellant’s] interests.', 'sentencing', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Padilla does not hold the answer to the case before us, but inasmuch as its legal underpinnings limn the inquiry before us, we think it important to explain why.', 'general', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this case law, we find that Appellant has pleaded and proved that his challenge to plea counsel’s ineffectiveness has arguable merit.', 'plea', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, as set forth above and amply supported by the record, we find that the trial court erred as a matter of law in finding that Mr.', 'general', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the desired benefit of appellant’s plea was to serve a county sentence, we found that plea counsel’s failure to recognize that such a sentence could not result from the plea as negotiated rendered counsel’s assistance constitutionally infirm.', 'sentencing', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court’s order denying Appellant’s PCRA petition, and remand for the trial court to permit Appellant to withdraw his guilty plea.', 'plea', 'Commonwealth v. Barndt', 'https://www.courtlistener.com/opinion/5146993/', '5146993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 193 (“Having determined that the statute at issue imposes vicarious liability through the use of a rebuttable presumption, we turn to the question of whether such a system violates the constitutional protections of due process, and we conclude that it does not.', 'general', 'DeVita v. District of Columbia', 'https://www.courtlistener.com/opinion/5147037/', '5147037') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the procedures for administrative adjudication of ATE System cases do not deny due process.', 'general', 'DeVita v. District of Columbia', 'https://www.courtlistener.com/opinion/5147037/', '5147037') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Beaulieu’s arguments lack merit, we affirm.', 'general', 'State of Minnesota v. Clarence Bruce Beaulieu', 'https://www.courtlistener.com/opinion/2776460/', '2776460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a probationer does not have a separate constitutional right “to be advised” that he or she has the procedural due process rights articulated in Moms-sey.', 'general', 'State of Minnesota v. Clarence Bruce Beaulieu', 'https://www.courtlistener.com/opinion/2776460/', '2776460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Beaulieu has established the first two prongs of the plain-*282error doctrine.', 'general', 'State of Minnesota v. Clarence Bruce Beaulieu', 'https://www.courtlistener.com/opinion/2776460/', '2776460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that Beaulieu has not met his heavy burden of showing the error affected his substantial rights.', 'general', 'State of Minnesota v. Clarence Bruce Beaulieu', 'https://www.courtlistener.com/opinion/2776460/', '2776460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With all due respect to the dissent, we conclude that the basis for Beaulieu’s waiver claim throughout these proceedings is that the district court failed to advise Beaulieu of his Monissey rights on the record.', 'general', 'State of Minnesota v. Clarence Bruce Beaulieu', 'https://www.courtlistener.com/opinion/2776460/', '2776460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our order granting review, we directed: “IT IS HEREBY ORDERED that the petition of Clarence Bruce Beaulieu for further review of the decision of the Court of Appeals be, and the same is, granted on the Morrissey-waiver issue.', 'general', 'State of Minnesota v. Clarence Bruce Beaulieu', 'https://www.courtlistener.com/opinion/2776460/', '2776460') ON CONFLICT DO NOTHING;
