INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that Riske was entitled to sentence credit for the period from when the jailer refused him admission until he was required to report back to the jail.', 'sentencing', 'State v. Dentici', 'https://www.courtlistener.com/opinion/2120836/', '2120836') ON CONFLICT DO NOTHING;
