INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that police had reasonable suspicion of criminal activity to support the stop of the vehicle, based on the following facts: (1) Chief Pender received a report from a Wal-Mart employee who observed two men purchasing a large number of cold tablets;', 'general', 'State v. Vereb', 'https://www.courtlistener.com/opinion/2121294/', '2121294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although police did not formally arrest appellant until after they had detained and transported him to police headquarters, we conclude that once he believed he was not free to leave, his continued detention became a “de facto” arrest requiring probable cause.', 'probable_cause', 'State v. Vereb', 'https://www.courtlistener.com/opinion/2121294/', '2121294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was a reasonable articulable basis for the stop and probable cause to arrest appellant, we affirm.', 'probable_cause', 'State v. Vereb', 'https://www.courtlistener.com/opinion/2121294/', '2121294') ON CONFLICT DO NOTHING;
