INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] In Briones, we reversed *970 Petitioner''s convictions of attempted second degree murder and second degree murder, in violation of HRS §§ 705-500 and 707-701.', 'general', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree with Petitioner in certain respects, we reverse his conviction of attempted first degree murder and remand to circuit court for a new trial.', 'general', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court''s denial of Petitioner''s Rule 40 petition and remand the case to circuit court.', 'general', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without directly addressing the double jeopardy issue,[3] we affirmed Petitioner''s conviction and sentence *971 on Count I but reversed his convictions on Counts II and III, and remanded the case for dismissal of those two counts based upon the trial court''s violation of an express statutory provision:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Briones I, "we affirm[ed] the [petitioner''s] conviction and sentence as to the *981 attempted first degree murder offense (Count I) .', 'sentencing', 'Briones v. State', 'https://www.courtlistener.com/opinion/1375983/', '1375983') ON CONFLICT DO NOTHING;
