INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that *834review was available.', 'general', 'Heckler v. Chaney', 'https://www.courtlistener.com/opinion/111383/', '111383') ON CONFLICT DO NOTHING;
