INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '21, 28 (1974), instead of invoking notions of “absolute” prosecutorial discretion, we held that certain potentially vindictive exercises of prosecutorial discretion were both reviewable and impermissible.', 'general', 'Heckler v. Chaney', 'https://www.courtlistener.com/opinion/111383/', '111383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that absolute immunity for public officials in their discretionary functions acting in other than true judicial proceedings is not required and, indeed, is improper.', 'general', 'Grimm v. Arizona Board of Pardons & Paroles', 'https://www.courtlistener.com/opinion/2616459/', '2616459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that members of the State Board of Pardons and Paroles owe a duty to individual members of the general public when the Board decides to release on parole a prisoner with a history of violent and dangerous conduct toward his or her fellow human beings.', 'general', 'Grimm v. Arizona Board of Pardons & Paroles', 'https://www.courtlistener.com/opinion/2616459/', '2616459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that members of the Board of Pardons and Paroles have only partial immunity from suit, the trial court’s grant of summary judgment for appellees was error.', 'general', 'Grimm v. Arizona Board of Pardons & Paroles', 'https://www.courtlistener.com/opinion/2616459/', '2616459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the documents sought came under the “other matters” provision of § 12-412 A.', 'general', 'Grimm v. Arizona Board of Pardons & Paroles', 'https://www.courtlistener.com/opinion/2616459/', '2616459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, based upon the foregoing reasons we hold that imposition of a period of Conditional Release supervision after release from prison in which the releasee will have to comply with reasonable terms and conditions or be returned to prison to continue serving the eligible sentence without credit for gain time awarded does not violate any of the releasee''s constitutional rights under the Double Jeopardy Clause, the Ex Post Facto Clause, the Due Process Clause, or the Equal Protection Clause;', 'sentencing', 'Duncan v. Moore', 'https://www.courtlistener.com/opinion/1133525/', '1133525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that requiring that a Conditional Release eligible inmate finish his or her sentence by satisfactorily completing a period of post-prison supervision equal to the amount of gain time awarded does not violate double jeopardy.', 'sentencing', 'Duncan v. Moore', 'https://www.courtlistener.com/opinion/1133525/', '1133525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that attempting to dissuade releasees from returning to a life of crime is clearly a legitimate state purpose.', 'general', 'Duncan v. Moore', 'https://www.courtlistener.com/opinion/1133525/', '1133525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that maintaining such releasees under supervision is a reasonable means of achieving that goal.', 'general', 'Duncan v. Moore', 'https://www.courtlistener.com/opinion/1133525/', '1133525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the State has satisfied the rational basis test and thus there is no equal protection violation.', 'general', 'Duncan v. Moore', 'https://www.courtlistener.com/opinion/1133525/', '1133525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that imposition of Conditional Release supervision does not result in cruel and unusual punishment.', 'general', 'Duncan v. Moore', 'https://www.courtlistener.com/opinion/1133525/', '1133525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we hold that the argument of the prosecutor, although error, did not constitute plain error warranting the Court of Appeals to overlook the failure of the defense counsel to preserve the point by timely objection;', 'general', 'United States v. Young', 'https://www.courtlistener.com/opinion/111353/', '111353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that any potential harm from this remark was mitigated by the jury’s understanding that the prosecutor was countering defense counsel’s repeated attacks on the *18prosecution’s integrity and defense counsel’s argument that the evidence established no such crime.', 'general', 'United States v. Young', 'https://www.courtlistener.com/opinion/111353/', '111353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the context of the prosecutor’s remarks and defense counsel’s broadside attack, however, we conclude that the jury was not influenced to stray from its responsibility to be fair and unbiased.', 'general', 'United States v. Young', 'https://www.courtlistener.com/opinion/111353/', '111353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The concerns underlying our reactions against improper prosecutorial arguments to the jury are implicated here, but not to the extent that we conclude that the jury’s deliberations were compromised.', 'general', 'United States v. Young', 'https://www.courtlistener.com/opinion/111353/', '111353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that §263.', 'general', 'New York v. Ferber', 'https://www.courtlistener.com/opinion/110794/', '110794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we hold that § 263.', 'general', 'New York v. Ferber', 'https://www.courtlistener.com/opinion/110794/', '110794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, we hold that child pornography as defined in § 263.', 'general', 'New York v. Ferber', 'https://www.courtlistener.com/opinion/110794/', '110794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Most recently, we held that the Government’s interest in the “well-being of its youth” justified special treatment of indecent broadcasting received by adults as well as children.', 'general', 'New York v. Ferber', 'https://www.courtlistener.com/opinion/110794/', '110794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the marginal or nonexistent benefits produced by suppressing evidence obtained in objectively reasonable reliance on a subsequently invalidated search warrant cannot justify the substantial costs of exclusion.', 'suppression', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the rule can have no substantial deterrent effect in the sorts of situations under consideration in this case, see infra, at 916-921, we conclude that it cannot pay its way in those situations.', 'general', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In determining whether persons aggrieved solely by the introduction of damaging evidence unlawfully obtained from their co-conspirators or codefendants could seek suppression, for example, we found that the additional benefits of such an extension of the exclusionary rule would not outweigh its costs.', 'suppression', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals.', 'general', 'United States v. Leon', 'https://www.courtlistener.com/opinion/111262/', '111262') ON CONFLICT DO NOTHING;
