INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Guidelines’ standard for the consideration of hearsay testimony at sentencing meets the appropriate constitutional test and fulfills the Confrontation Clause’s basic purpose of promoting the integrity of the factfinding process.', 'sentencing', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we held that the sentencing court may properly consider “uncorroborated hearsay evidence that the defendant has had an *397opportunity to explain or rebut.', 'sentencing', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the enactment of the Guidelines has not so transformed the sentencing phase that it constitutes a separate criminal proceeding.', 'sentencing', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Sexson’s hearsay testimony was sufficiently reliable to support the district court’s finding that Wise had indeed been an organizer or leader of a criminal activity that involved five or more persons.', 'general', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, although we do not endorse the manner in which it was conducted, we conclude that the hearing did not deprive Wise of due process.', 'general', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the motion court did not err in denying Movant’s claim that counsel was ineffective for advising him to enter an open Alford plea of guilty in the absence of a promised benefit from the State.', 'plea', 'Lynn v. State', 'https://www.courtlistener.com/opinion/5286250/', '5286250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Lynn v. State', 'https://www.courtlistener.com/opinion/5286250/', '5286250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '127 Because the Plea Withdrawal Statute requires defendants to show that their pleas were not in fact knowingly and voluntarily made, we hold that the court of appeals erred in limiting its analysis to whether the district court complied with rule 11.', 'plea', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Alexander''s plea was unknowingly and involuntarily made, and we hold that Mr.', 'plea', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 54 Because the issue resolved in Hurst is separate and distinct from the issue presented in the case currently before us, we hold that the two cases do not conflict.', 'general', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 55 We hold that, although the court of appeals erred in limiting its review to whether the district court had complied with rule 11 during the plea hearing, the record nonetheless demonstrates that Mr.', 'plea', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we hold that the court of appeals did not err in failing to conduct a harmless error analysis because such an analysis is not required by rule 11(l).', 'general', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that, because the instant case involves a different issue than the one addressed in our holding in Hurst, the two cases do not conflict.', 'general', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lovell, we held that our case law does not support the application of a prejudice requirement to preserved claims of rule 11(e) violations.', 'general', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that errors in accepting a guilty plea are factually distinct from errors in other contexts, we decline to require a showing of prejudice in order for a defendant to withdraw his plea.', 'plea', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '90 Because subsection (F) merely clarifies that rule 11 violations alone are not sufficient to allow withdrawal of guilty pleas, we conclude that it does not require defendants to show prejudice before they may withdraw their pleas.', 'plea', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because our holding in Hurst was limited to a single issue, and that issue is not before us in this case, we conclude that the court of appeals'' decision does not conflict with our holding in Hurst.', 'general', 'State v. Alexander', 'https://www.courtlistener.com/opinion/5327211/', '5327211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We generally conclude that these conditions are sufficiently related to Diorec''s rehabilitation and the protection of the public But we conclude that the definition of "sexually explicit material" must be modified to provide constitutionally adequate notice of what is prohibited.', 'general', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this legislative history, we conclude that the polygraph testing specified in the statute was intended to promote the rehabilitation of sex offenders and to protect the public from further sexual offenses.', 'general', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that there are two restrictions on the probation officer''s discretion that are relevant to our construction of this condition.', 'general', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, when properly construed, this probation condition has a sufficient relationship to Dioree''s crime and to his rehabilitation.', 'general', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that part of Dioree''s argument is based on a misreading of this condition.', 'general', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this condition was well within the sentencing judge''s discretion.', 'sentencing', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is a sufficient relationship between this condition and the goal of protection of the public.', 'general', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16 We conclude that Dioree has not established that Judge Carey committed an abuse of discretion when he concluded that the restriction on adult material is necessary to protect the public and to promote Diorec''s rehabilitation.', 'general', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a condition prohibiting Internet access could be reasonable only if the condition allows a probation officer to allow necessary Internet use under appropriate conditions.', 'general', 'Diorec v. State', 'https://www.courtlistener.com/opinion/5328028/', '5328028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this error is harmless with regard to Pedersen''s defamation claims.', 'general', 'Pedersen v. Blythe', 'https://www.courtlistener.com/opinion/5327877/', '5327877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the superior court erred when, in deciding the motion to dismiss, it considered matters outside the pleadings without advising Pedersen of its intent to do so and giving him a reasonable opportunity to respond.', 'dismissal', 'Pedersen v. Blythe', 'https://www.courtlistener.com/opinion/5327877/', '5327877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Construing the complaint liberally, and accepting as true all factual allegations,24 we find that these claims are sufficient to survive a motion to dismiss.', 'dismissal', 'Pedersen v. Blythe', 'https://www.courtlistener.com/opinion/5327877/', '5327877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '25 We reverse the superior court''s dismissal of the trespass claims and remand to the superior court for consideration of those claims.', 'dismissal', 'Pedersen v. Blythe', 'https://www.courtlistener.com/opinion/5327877/', '5327877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2007) (en banc), this Court held that the defendant was properly sentenced for both indecent assault and corruption of minors where he had committed the separate acts of touching the victim’s breasts and her vagina.', 'sentencing', 'Commonwealth v. Leatherby', 'https://www.courtlistener.com/opinion/2795539/', '2795539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the time within which to file an appeal was tolled by Leatherby’s pro se motion, and we will consider his appeal timely.', 'general', 'Commonwealth v. Leatherby', 'https://www.courtlistener.com/opinion/2795539/', '2795539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As there was no evidence presented from which the jury could have inferred that Leatherby engaged in the kind of communication, either verbal or physical, contemplated in Velez, we find that there was insufficient evidence to support a conviction of unlawful contact as to M.', 'general', 'Commonwealth v. Leatherby', 'https://www.courtlistener.com/opinion/2795539/', '2795539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', however, we find that the evidence presented by the Commonwealth was sufficient to sustain a conviction of unlawful contact.', 'general', 'Commonwealth v. Leatherby', 'https://www.courtlistener.com/opinion/2795539/', '2795539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon careful review, we affirm in part and vacate in part.', 'general', 'Commonwealth v. Leatherby', 'https://www.courtlistener.com/opinion/2795539/', '2795539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 16 As we describe in greater detail below, we hold that each of Mr.', 'general', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We hold that the rule encompasses facial constitutional challenges to the sentence that do not implicate a fact-intensive analysis.', 'sentencing', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Houston facially attacks the constitutionality of the statute that authorized his sentence, we hold that he has properly challenged it as an "illegal sentence" under Utah Rule of Criminal Procedure 22(e).', 'sentencing', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '151 We hold that the unnecessary rigor clause does not apply to Mr.', 'general', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Mr.', 'general', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004) ("Because the defendant reserved the right to appeal an ''illegal sentence,'' and because an unconstitutional sentence is ''illegal," we hold that the defendant is entitled to challenge his sentence.', 'sentencing', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 24 In Prion, we held that the defendant''s statutory and double jeopardy challenges properly fell within the ambit of rule 22(6).', 'general', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '62 We held that the burden of proof rule articulated in Wood does not apply when the jury is not considering death as a possible sentence.', 'sentencing', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lofferty, we held that "[a] eriminal punish ment is cruel and unusual under article I, section 9 if it is so disproportionate to the offense committed that it shock{s] the moral sense of all reasonable men as to what is right and proper under the circumstances.', 'general', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we conclude that Mr.', 'general', 'State v. Houston', 'https://www.courtlistener.com/opinion/2789677/', '2789677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm.', 'general', 'State v. Martinez', 'https://www.courtlistener.com/opinion/6604059/', '6604059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 15 For the reasons above, we affirm Martinez’s conviction and resulting sentence.', 'sentencing', 'State v. Martinez', 'https://www.courtlistener.com/opinion/6604059/', '6604059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Shivers’ convictions and sentences.', 'sentencing', 'State v. Shivers', 'https://www.courtlistener.com/opinion/6604037/', '6604037') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that the Intermediate Court of Appeals (ICA) did not ultimately err in *39concluding that a colloquy was not required in the circumstances of this case, we provide guidance as to the proper allocation of authority between a defendant and defense counsel in light of statements by the ICA regarding defense counsel''s authority to stipulate to an evidentiary matter based on "trial tactics and procedure.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/6659120/', '6659120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court clearly did so in Won, in which we held that the search incident to arrest exception to the warrant requirement is inapplicable to intoxilyzer tests under the Hawai''i Constitution.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/6659120/', '6659120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As with a stipulation to facts establishing an element of an offense in Ui, this court held on review that the stipulation went beyond the bounds of mere trial tactics and strategy to impinge on the wife''s constitutional right to confrontation, and a colloquy was therefore required.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/6659120/', '6659120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that Neal’s conviction in Charlotte County for the fraudulent use of the credit card in question within the same six-month period violates his right not to be prosecuted and punished twice for the same offense.', 'general', 'Neal v. State', 'https://www.courtlistener.com/opinion/4989317/', '4989317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the unusual structure of section 817.', 'general', 'Neal v. State', 'https://www.courtlistener.com/opinion/4989317/', '4989317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Neal’s prior conviction in Sarasota County barred his conviction in Charlotte County for the fraudulent use of the same credit card within the same six-month period, we reverse his judgment and sentence for fraudulent use of a credit card.', 'sentencing', 'Neal v. State', 'https://www.courtlistener.com/opinion/4989317/', '4989317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Neal’s judgment and sentence for the fraudulent use of a credit card.', 'sentencing', 'Neal v. State', 'https://www.courtlistener.com/opinion/4989317/', '4989317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that summary judgment had been improperly entered in favor of the defendant restaurant in an action brought under 42 U.', 'general', 'Celotex Corp. v. Catrett, Administratrix of the Estate of Catrett', 'https://www.courtlistener.com/opinion/111722/', '111722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that it was error to grant summary judgment “on the basis of this record” because respondent had “failed to fulfill its initial burden” of demonstrating that there was no evidence that there was a policeman in the store.', 'general', 'Celotex Corp. v. Catrett, Administratrix of the Estate of Catrett', 'https://www.courtlistener.com/opinion/111722/', '111722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '350 (1960), we held that a naturalized citizen who had willfully and falsely stated during the naturalization process that he had never been arrested could nevertheless not be denaturalized pursuant to § 1451.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '265 (1961), we held that a naturalized citizen who had willfully and falsely stated during the naturalization process that his occupation was “real estate,” when in fact it would more accurately have been described as “bootlegging,” could be denaturalized pursuant to § 1451.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking, therefore, solely to the question whether Kungys’ misrepresentation of the date and place of his birth in his naturalization petition was material within the meaning of § 1451(a), we conclude that it was not.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In Fedorenko, we held that citizenship had been illegally procured because the petitioner, a former armed concentration camp guard, was ineligible for the visa he had been issued under the Displaced Persons Act of 1948 (DPA), 62 Stat.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In both Turkette and Russello, we found that the “declared purpose” of Congress in enacting the RICO statute was “‘to seek the eradication of organized crime in the United States.', 'general', 'Sedima, S. P. R. L. v. Imrex Co.', 'https://www.courtlistener.com/opinion/111508/', '111508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in order to show prejudice, the defendant must demonstrate a reasonable probability, defined as a probability sufficient to undermine confidence in the outcome, that (1) he or she would have accepted the offer had counsel advised the defendant correctly, (2) the prosecutor would not have withdrawn the offer, (3) the court would have accepted the offer, and (4) the conviction or sentence, or both, under the offer’s terms would have been less severe than under the judgment and sent...', 'sentencing', 'Alcorn v. State', 'https://www.courtlistener.com/opinion/4993972/', '4993972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Cottle, this Court held that the Strickland analysis extended to challenges arising out of the plea bargaining process, reasoning that this pretrial process was a critical stage in criminal adjudication that warranted the same constitutional guarantee of effective assistance of counsel as trial proceedings.', 'plea', 'Alcorn v. State', 'https://www.courtlistener.com/opinion/4993972/', '4993972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Fourth District in Alcorn also employed an incorrect prejudice analysis.', 'general', 'Alcorn v. State', 'https://www.courtlistener.com/opinion/4993972/', '4993972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '‘inherent power’ can only obscure analysis of the problem,” we held that “whether a court has power to dismiss a complaint because of non-compliance with a production order depends exclusively upon Rule 37.', 'dismissal', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '250, 254 (1988), we held that a federal court could not invoke its inherent supervisory power to circumvent the harmless-error inquiry prescribed by Federal Rule of Criminal Procedure 52(a).', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Piper, supra, we held that the costs recoverable under a prior version of 28 U.', 'general', 'Chambers v. Nasco, Inc.', 'https://www.courtlistener.com/opinion/112616/', '112616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it may not.', 'general', 'Burns v. United States', 'https://www.courtlistener.com/opinion/112620/', '112620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that before a district court can depart upward on a ground not identified as a ground for upward departure either in the presentence report or in a prehearing submission by the Government, Rule 32 requires that the district court give the parties reasonable notice that it is contemplating such a ruling.', 'sentencing', 'Burns v. United States', 'https://www.courtlistener.com/opinion/112620/', '112620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that petitioner is not estopped from challenging the ex-cludability under the Act of the 1997 continuance.', 'general', 'Zedner v. United States', 'https://www.courtlistener.com/opinion/145651/', '145651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the 91-day continuance granted on January 31 was not excluded from petitioner’s speedy trial clock.', 'general', 'Zedner v. United States', 'https://www.courtlistener.com/opinion/145651/', '145651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, although this claim was proeedurally defaulted, petitioner may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.', 'general', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Teague, we held that “new constitutional rules of criminal procedure will not be applicable *620to those cases which have become final before the new rules are announced,” id.', 'general', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '101 (1942) (per curiam), we held that there was such an exception for a claim that a plea of guilty had been coerced by threats made by a Government *622agent, when the facts were “dehors the record and their effect on the judgment was not open to consideration and review on appeal.', 'plea', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the error was neither jurisdictional nor constitutional, we held that collateral relief was unavailable.', 'general', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '637, 644-646 (1976), this Court held that where neither the indictment, defense counsel, nor the trial court explained to the defendant that intent to kill was an element of second-degree murder, his plea to that offense was “involuntary.', 'plea', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the “fundamental nature of criminal forfeiture” is punishment.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a defendant may decide to raise a claim of ineffectiveness of counsel on direct appeal, but, if so raised, “the issue will be foreclosed from collateral review.', 'ineffective_assistance', 'McIntire v. State', 'https://www.courtlistener.com/opinion/853753/', '853753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these jury instructions, we find that the defendant has demonstrated a reasonable possibility that the jury used the same evidentiary facts (Hilt’s head injury caused by the baseball bat) to establish the essential elements of both class A burglary and class D criminal recklessness.', 'jury_instruction', 'McIntire v. State', 'https://www.courtlistener.com/opinion/853753/', '853753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The only time we have found remand for re-sentencing to be unnecessary is when we affirmed all convictions and the trial court ordered identical sentences to run concurrently.', 'sentencing', 'McIntire v. State', 'https://www.courtlistener.com/opinion/853753/', '853753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the constitutional text, the history and circumstances surrounding its adoption, and the earliest cases interpreting and applying the provision, we conclude that Indiana’s Double Jeopardy Clause was intended to prevent the State from being able to proceed against a person twice for the same criminal transgression.', 'general', 'Richardson v. State', 'https://www.courtlistener.com/opinion/853754/', '853754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '48 From the evidence presented, we find that the defendant has demonstrated a reasonable possibility that the evidentiary facts used by the jury to establish the essential elements of robbery were also used to establish the essential elements of the class A misdemeanor battery.', 'general', 'Richardson v. State', 'https://www.courtlistener.com/opinion/853754/', '853754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reaching this conclusion, we found that “[wjithout any evidence as to the value of the truck, the State has failed to meet its burden of proof as to one of the elements of grand larceny and conviction of same cannot be upheld.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/5104817/', '5104817') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we find that S.', 'general', 'In the Interest of S.M.K.S. v. Youth Court of Union County', 'https://www.courtlistener.com/opinion/5105383/', '5105383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we find that Officer Kent’s actions in arresting S.', 'general', 'In the Interest of S.M.K.S. v. Youth Court of Union County', 'https://www.courtlistener.com/opinion/5105383/', '5105383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that S.', 'general', 'In the Interest of S.M.K.S. v. Youth Court of Union County', 'https://www.courtlistener.com/opinion/5105383/', '5105383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'So, in sum, we find that sufficient evidence exists to support the Union County Youth Court’s adjudication of S.', 'general', 'In the Interest of S.M.K.S. v. Youth Court of Union County', 'https://www.courtlistener.com/opinion/5105383/', '5105383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review, we find no error in the Court of Appeals’ conclusion, and we affirm.', 'general', 'In the Interest of S.M.K.S. v. Youth Court of Union County', 'https://www.courtlistener.com/opinion/5105383/', '5105383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In another case, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in denying Ronk’s imperfect-self-defense manslaughter instruction.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the evidence presented was sufficient to sustain a conviction of capital murder with the underlying felony of arson.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of some intervening precedent, we hold that Mississippi’s capital sentencing scheme is entirely constitutional.', 'sentencing', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, after considering each of Ronk’s claims, we hold that the cumulative effect of all alleged errors was not such that Ronk was denied a fundamentally fair trial.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ross, this Court held that the trial court did not err in admitting into evidence a gun of the same caliber as the murder weapon, even though no forensic evidence tied the gun to the defendant, where a witness testified that the defendant had disposed of the gun the day after admitting to the victim’s murder.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), this Court held that it was not error for the trial court to admit into evidence a pair of pliers as the possible murder weapon.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Keeping this standard in mind, we find that Ronk was not entitled to an instruction on imperfect-self-defense manslaughter.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not err in instructing the jury on the one-continuous-transaction doctrine, which was adopted by this Court to define the requisite causal nexus between a killing and the underlying felony in a capital felony-murder case.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these claims are not based on facts fully apparent from the record, and it would be inappropriate for this Court to attempt to dispose of them on direct appeal.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Ronk’s assertions are without merit.', 'general', 'Ronk v. State', 'https://www.courtlistener.com/opinion/5105427/', '5105427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though the defendant’s wife was the only person present at the time of the search, this Court held that there was sufficient evidence that the defendant, who resided at the apartment with his wife, constructively possessed the contraband.', 'general', 'State v. Bradshaw', 'https://www.courtlistener.com/opinion/6835792/', '6835792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the State presented sufficient evidence to support the jury’s determination that defendant constructively possessed the cocaine and rifle found in a bedroom — which also contained photographs, a Father’s Day card, a cable bill, a cable installation receipt, and a pay stub, all linking defendant to the contraband — we affirm the Court of Appeals.', 'general', 'State v. Bradshaw', 'https://www.courtlistener.com/opinion/6835792/', '6835792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decision of the Court of Appeals.', 'general', 'State v. Bradshaw', 'https://www.courtlistener.com/opinion/6835792/', '6835792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), this Court held it was apparent that La.', 'general', 'Succession of LeBouef', 'https://www.courtlistener.com/opinion/5004735/', '5004735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we reverse the portion of the district court judgment holding the defendants, Linda Ann L.', 'general', 'Succession of LeBouef', 'https://www.courtlistener.com/opinion/5004735/', '5004735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm the defendants’ removal as co-administrators, reverse the portion of the judgment holding them in contempt, and remand this matter.', 'general', 'Succession of LeBouef', 'https://www.courtlistener.com/opinion/5004735/', '5004735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did and order a new trial.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he was entitled to the instruction.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the willful blindness instruction is inconsistent with North Carolina law, and thus the trial court erred in giving such an instruction to the jury.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the error in giving the willful blindness instruction entitles defendant to a new trial.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Townsend’s testimony was competent evidence of defendant’s character for the relevant trait of lawabidingness, we hold that defendant was entitled to an instruction *200on his character trait of law-abidingness as substantive evidence of his innocence.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the traits of truthfulness and honesty are not “pertinent” character traits to the crime of trafficking in marijuana by possession or transportation.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that testimony of defendant and of the police officers of .', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence of a lack of convictions should not have been admitted as character evidence.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the error in instructing the jury on defendant’s willful blindness, the verdict and judgment of the trial court are vacated, and we reverse the decision of the Court of Appeals and remand the case to the Court of Appeals for further remand to the Superior Court, Northampton County, for a new trial.', 'general', 'State v. Bogle', 'https://www.courtlistener.com/opinion/1255229/', '1255229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Perley, we held that an information was- not fundamentally defective simply because it did not include any factual specifics surrounding, the charge.', 'general', 'Fravel v. State', 'https://www.courtlistener.com/opinion/5013688/', '5013688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on all issues, but write to address the double jeopardy issue.', 'general', 'Fravel v. State', 'https://www.courtlistener.com/opinion/5013688/', '5013688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed his convictions, explaining:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions but remand this cause with instructions to modify the sentence.', 'sentencing', 'Fointno v. State', 'https://www.courtlistener.com/opinion/2017317/', '2017317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we conclude that the State was not required, under section 111-3(c) of the Code of Criminal Procedure, to give the defendants pretrial notice that they would be sentenced as Class X offenders under section 5-5-3(c)(8) of the Unified Code of Corrections (Ill.', 'sentencing', 'People v. Jameson', 'https://www.courtlistener.com/opinion/2103792/', '2103792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this standard of review and the interests the contemporaneous objection rule serves, we hold that, with two exceptions, a defendant must preserve a claim of insufficiency of the evidence through timely challenge in the trial court.', 'general', 'F.B. v. State', 'https://www.courtlistener.com/opinion/7819013/', '7819013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the issue was not preserved below, we held that it “was not open to appellate review.', 'general', 'F.B. v. State', 'https://www.courtlistener.com/opinion/7819013/', '7819013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We held that “a conviction imposed upon a crime totally unsupported by evidence constitutes fundamental error.', 'general', 'F.B. v. State', 'https://www.courtlistener.com/opinion/7819013/', '7819013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Relying on Troedel’s fundamental error pronouncement, we held that because section 790.', 'general', 'F.B. v. State', 'https://www.courtlistener.com/opinion/7819013/', '7819013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the interests of justice are better served by applying this general rule to challenges to the sufficiency of the evidence.', 'general', 'F.B. v. State', 'https://www.courtlistener.com/opinion/7819013/', '7819013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed for entry of a petty larceny conviction.', 'general', 'F.B. v. State', 'https://www.courtlistener.com/opinion/7819013/', '7819013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984), we reversed one of the defendant’s two burglary convictions because “[tjhere was no evidence of more than one such unlawful entry.', 'general', 'F.B. v. State', 'https://www.courtlistener.com/opinion/7819013/', '7819013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the action of the Legislature in amending our statute to conform to the language of the Model Penal Code, and the intent of the Model Code drafters to limit the reach of the provision to "fighting words," we hold that the "abusive language" provision of § 1026(3) is properly construed as proscribing only "fighting words.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that "the abuse of the right must be submitted to in common with other evils in government, as subservient to the public welfare.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant having failed to demonstrate that the Vermont Constitution affords a more expansive free-speech right than is found under the federal charter, we conclude that the statements that formed the basis for his disorderly conduct conviction find no constitutional protection.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Oren, however, we affirmed a conviction for hindering a law enforcement officer under the "fighting words" doctrine, without regard to the fact that both the defendant and the officer were women.', 'general', 'State v. Read', 'https://www.courtlistener.com/opinion/1992986/', '1992986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the judgment in this case does not turn upon a factual finding, we conclude that the abuse of discretion standard is the appro-i priate benchmark by which to review the judgment in this case.', 'general', 'City of Baton Rouge v. Douglas', 'https://www.courtlistener.com/opinion/5025328/', '5025328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '| fjWe find no error in the trial court’s judgment, and we affirm the trial court’s refusal to issue the writ of mandamus.', 'general', 'City of Baton Rouge v. Douglas', 'https://www.courtlistener.com/opinion/5025328/', '5025328') ON CONFLICT DO NOTHING;
