INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Council', 'https://www.courtlistener.com/opinion/1335490/', '1335490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Justice requires that we reverse and remand appellant’s conviction and sentence for a new trial in which this novel scientific evidence is subjected to the newly formulated test.', 'sentencing', 'State v. Council', 'https://www.courtlistener.com/opinion/1335490/', '1335490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that these distinctions are readily identifiable and inherent in the dispositional process, which has been comprehensively addressed by our Legislature under chapter 985.', 'general', 'E.A.R. v. State', 'https://www.courtlistener.com/opinion/5045211/', '5045211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that simply parroting is insufficient to justify departure and that, instead, the juvenile court’s stated “reasons,” must provide a legally sufficient foundation for “disregarding” the DJJ’s professional assessment and PDR by identifying significant information that the DJJ has overlooked, failed to sufficiently consider, or misconstrued with regard to the child’s programmatic, rehabilitative needs along with the risks that the unrehabilitated child poses to the public.', 'general', 'E.A.R. v. State', 'https://www.courtlistener.com/opinion/5045211/', '5045211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1330651/', '1330651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the Husband’s arguments and the well-reasoned analyses in the First District’s opinions in Martinez, Janousek, and Sylvester, we conclude that a best interests determination in petitions for relocation must be made at the time of the final hearing and must be supported by competent, substantial evidence.', 'general', 'Arthur v. Arthur', 'https://www.courtlistener.com/opinion/5048405/', '5048405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the trial court in this case did not utilize this “present-based” analysis, we conclude that if it had done so, the court would have denied the relocation request.', 'general', 'Arthur v. Arthur', 'https://www.courtlistener.com/opinion/5048405/', '5048405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our determination that the trial court’s prospective best interest determination was erroneous, we conclude that it is unnecessary to address the Husband’s claim of trial court error.', 'general', 'Arthur v. Arthur', 'https://www.courtlistener.com/opinion/5048405/', '5048405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the findings of the trial court and the judgment of contempt but remand this cause to the trial court with instructions to reconsider the penalty provisions of the fine in accordance with the principles set out in South Dade Farms v.', 'general', 'Langbert v. Langbert', 'https://www.courtlistener.com/opinion/1139658/', '1139658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances in this case, we conclude that the district court did not err by dismissing Hassett’s application for post-conviction relief without further hearing or without obtaining a progress report from the correctional authorities.', 'dismissal', 'Hassett v. State', 'https://www.courtlistener.com/opinion/1158384/', '1158384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained below, we affirm.', 'general', 'Hassett v. State', 'https://www.courtlistener.com/opinion/1158384/', '1158384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the appropriate remedy is to strike the mandatory crime of violence sentencing provision under section 18-3-203(2)(c) as it applies to attempted second degree assault under subsection (l)(b) and remand the case for resentencing as a class 4 felony.', 'sentencing', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Smith, we held that “when an offender who acts with a less culpable intent may receive a greater penalty than the offender who acts with a greater culpable intent, such a statutory scheme is ‘unreasonably structured’ and ‘constitutionally infirm,’ even though the two offenses result in the same harm.', 'general', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the legislature has declined to modify the statute, we conclude that the legislature intended that attempt to commit bodily injury with a deadly weapon be sentenced pursuant to subsection (l)(b) rather than pursuant to the general criminal attempt statute as are all forms of attempted first degree assault under section 18-3-202 and all other forms of second degree assault under section 18-3-203.', 'sentencing', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that either proposal would cure the constitutional defect.', 'general', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that it would be inconsistent with Weller to strike the attempt language from section 18-3-203(l)(b) on equal protection grounds.', 'general', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse the district court’s judgment vacating Due Nguyen’s two convictions for attempted second degree assault and remand the case for resentencing consistent with this opinion.', 'sentencing', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we affirm the district court’s holding that section 18-3-203 violates the equal protection guarantees of the Colorado and United States Constitutions.', 'general', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant through her offer of proof made out a sufficient prima facie defense of bona fide claim of right to require the case to be submitted to a finder of fact where the burden is on the state to establish the contrary beyond a reasonable doubt.', 'general', 'State v. Hoyt', 'https://www.courtlistener.com/opinion/2062624/', '2062624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the conviction on other grounds, we deem it unnecessary to reach the constitutional claim herein presented.', 'general', 'State v. Hoyt', 'https://www.courtlistener.com/opinion/2062624/', '2062624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with this authority we conclude that AS 11.', 'general', 'Bachlet v. State', 'https://www.courtlistener.com/opinion/1172165/', '1172165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the statute was not unconstitutionally vague for failure to provide Bachlet notice of the prohibited conduct.', 'general', 'Bachlet v. State', 'https://www.courtlistener.com/opinion/1172165/', '1172165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state’s concession is sound and that Bachlet’s three solicitation convictions should merge into a single offense.', 'general', 'Bachlet v. State', 'https://www.courtlistener.com/opinion/1172165/', '1172165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bachlet v. State', 'https://www.courtlistener.com/opinion/1172165/', '1172165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lynn Thomas, Solicitor General for the office of the Attorney General,1 met the issue of fundamental error, discussed it, and urged upon the Court that we hold that beyond a reasonable doubt the error in placing upon the defendant the burden of establishing his innocence, per Mullaney v.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1177672/', '1177672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“Based on the above statutes, we find that in Idaho the crime of voluntary manslaughter consists of three elements which must be proved by the State: (1) the killing of a human being;', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1177672/', '1177672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The comments by the prosecutor in the instant case fall squarely within the principle established by the Seyle case, and we hold that such comments did not constitute error.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, “where the wife of a defendant in a criminal case, like that now before us, might be a material witness, and she is not placed on the stand by the defendant, it is permissible for the State in argument to infer that the absent testimony would have been both material and damaging.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 379, we held that, pursuant to § 7-1-112(c) (now § 7-6-106(c)), the district court could not order reimbursement without first determining the defendant’s ability to pay.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, since the fact and evidence of Jeffs confession came to appellant’s knowledge after the trial, we conclude that appellant satisfied the first Opie factor, and the denial of his motion for a new trial cannot be sustained on that basis.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s conduct in cross-examination, while improper, did not deny appellant a fair trial.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not err in admitting into evidence the preliminary hearing testimony of Patricia Koryn.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not need to reach appellant’s constitutional claim, however, because we conclude that the district court erred in ordering this reimbursement without first determining appellant’s ability to pay as required by § 7-6-106 and Keller v.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the district court failed to consider appellant’s ability to pay in ordering reimbursement of defense expenses, we reverse that aspect of the judgment and sentence.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm but modify the judgment and sentence with respect to costs.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this Court reversed Steve’s conviction on the basis of ineffective assistance of counsel, as emanating from the failure of counsel to investigate the nature and availability of Roger’s testimony, we affirmed, in a divided decision, the trial court’s denial of a new trial on the basis of newly discovered evidence.', 'ineffective_assistance', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that absolute immunity does not apply to the advisement and discussion with the probation officer regarding preparation of the original petition for revocation.', 'general', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the prior Cooney opinion we held that all of a deputy county attorney’s activities entitled him to absolute immunity in the probationer’s civil rights action against him.', 'general', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the deputy county attorney’s challenged activities involved in the attempted revocation of the probationer’s probation were “intimately associated with the judicial phase of the criminal process and [were] functions to which the reasons for absolute immunity apply with full force.', 'general', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that procuring a perjured probation revocation petition, assisting the Wyoming Department of Probation and Parole and its probation officer, using the perjured probation revocation petition to obtain a bench warrant for the probationer’s arrest and causing the probationer to be arrested and detained in jail for thirty-eight days were the functional equivalent of the prosecutor’s role as an advocate in a criminal proceeding.', 'general', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nothing in Bums affects or casts doubt upon that part of our decision in Cooney in which we affirmed the trial court’s dismissal of the Cooneys’ claims alleging liability under the Wyoming Governmental Claims Act, Wyo.', 'dismissal', 'Cooney v. White', 'https://www.courtlistener.com/opinion/1201860/', '1201860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that plaintiff failed to meet that burden and that the trial court’s conclusion to the contrary was error.', 'general', 'Matthews v. Blue Cross and Blue Shield', 'https://www.courtlistener.com/opinion/1252301/', '1252301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decisions of the trial court and the Court of Appeals and remand the case for entry of judgment notwithstanding the verdict.', 'general', 'Matthews v. Blue Cross and Blue Shield', 'https://www.courtlistener.com/opinion/1252301/', '1252301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that even if the three jurors were selected from beyond a fifty-mile radius of the Anchorage courthouse, this is not the sort of error which should lead to the dismissal of an indictment.', 'dismissal', 'Harris v. State', 'https://www.courtlistener.com/opinion/1217193/', '1217193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record supports Judge Carlson’s finding that Harris understood that the police were urging him to tell the truth and that if he did cooperate with them by telling the truth they would help him by bringing his cooperation to the attention of the prosecuting authorities.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1217193/', '1217193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the record, we conclude that, considering the totality of the circumstances, Harris’s confession was voluntary.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1217193/', '1217193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Harris voluntarily gave the handwriting samples to the police, that he was adequately warned of the consequences, and that he was informed of his right to counsel.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1217193/', '1217193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that Instruction No.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1217193/', '1217193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we believe that a defendant, in appropriate circumstances, does have the right to examine the author of the presentence report,6 having reviewed the record we conclude that all of the questions which Harris wanted to raise were adequately answered by the trial court making it unnecessary for the author of the presentence report testify.', 'sentencing', 'Harris v. State', 'https://www.courtlistener.com/opinion/1217193/', '1217193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that Harris waived any privilege which he had to keep the reports of Dr.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1217193/', '1217193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1217193/', '1217193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only when the officer, by means of physical force or show of authority, has in some way restrained the liberty of a citizen may we conclude that a ‘seizure’ has occurred.', 'general', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1219119/', '1219119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a person has been “seized” within the meaning of the Fourth Amendment only if, in view of all of the circumstances surrounding the incident, a reasonable person would have believed that he was not free to leave.', 'search_seizure', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1219119/', '1219119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Determining that a violation of federal constitutional rights occurred when the officer, following the policy of his department, seized a pedestrian to complete a check for outstanding warrants without reasonable suspicion of present or past criminal conduct, we reverse the judgment and sentence imposed by the district court.', 'sentencing', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1219119/', '1219119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Fla.', 'general', 'Hutchinson v. State', 'https://www.courtlistener.com/opinion/1138819/', '1138819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 268 (1990), we held that a person armed in self-defense is in lawful possession of a weapon.', 'general', 'State v. Goodson', 'https://www.courtlistener.com/opinion/1304259/', '1304259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing the conviction, this Court held that the evidence was insufficient to show that the town official’s misrepresentation had in any way induced the town to part with its money.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although, the name of the county was omitted from the body of the indictment, we find that sufficient information was contained in the indictment to confer jurisdiction upon the Wilkes County grand jury and to inform Michael Almond that the charges against him arose from activities in Wilkes County.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the above language was more than sufficient to give Michael Almond notice of the charge against him.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, given that the trial court has broad discretion to control discovéry so as to prevent undue embarrassment and annoyance, we find that the trial court did not err.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record we find that the evidentiary issues to which defendants objected were only tangential and did not affect defendants’ convictions.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendants received a fair trial frée from prejudicial error.', 'general', 'State v. Almond', 'https://www.courtlistener.com/opinion/1225214/', '1225214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, on the basis of the undisputed facts, we conclude that the sanction of disbarment is the reference point from which we begin our analysis of aggravating and mitigating factors.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon a consideration of all the above factors, we conclude that a sanction of not more than two years suspension and passage of the MPRE, as recommended by the Board, should be imposed on Schuler.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, given the relevant mitigating factors in this record, we conclude that a significant period of suspension from the practice of law is indicated.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '12, we affirmed the Disciplinary Board’s “determination that disbarment or suspension are generally appropriate sanctions given the nature of West’s misconduct.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the stipulated and recommended sanction should be approved.', 'general', 'In the Disciplinary Matter Involving Schuler', 'https://www.courtlistener.com/opinion/1227121/', '1227121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we hold that HRS § 708-830(6)(a) describes with reasonable clarity the acts that it proscribes, provides fixed standards for adjudging guilt, and gives persons of ordinary intelligence a reasonable opportunity to know what conduct is prohibited so that they may choose between lawful and unlawful conduct.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Gaylord having failed to meet his burden of plainly, clearly, manifestly, and unmistakably showing unconstitutionality beyond a reasonable doubt, we hold that HRS § 708-830(6)(a) is not unconstitutionally vague.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 and 4 of this opinion, we hold that HRS § 708-830(6)(a) is not'' unconstitutionally overbroad.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the sentencing court’s restitution order faded to comply with HRS § 706—605(l)(d) and was illegally imposed.', 'sentencing', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After full and thorough consideration, and based on a review of the entire record before us, we hold that Gaylord’s remaining points of error on appeal are without merit.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ordered that the defendant be given credit for time served while awaiting trial on these charges.', 'general', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Gaylord’s amended judgment of conviction, vacate his amended sentence, and remand the matter to the circuit court for resentencing.', 'sentencing', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Gay-lord’s amended judgment of conviction, vacate his amended sentence, and remand the matter to the circuit court for resentencing consistent with this opinion.', 'sentencing', 'State v. Gaylord', 'https://www.courtlistener.com/opinion/2617555/', '2617555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Alexander, we held that where the only issue was consent, an alleged rape victim’s testimony of her own emotional trauma was relevant.', 'general', 'State v. Schumpert', 'https://www.courtlistener.com/opinion/1225396/', '1225396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001), wherein we held that passage through a door that was propped open “broke the plane” and was an “act or force, however, slight, employed to effect an entrance.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004), this Court held that while there may not be direct evidence of the value of stolen items, the owner of the merchandise may establish the value of the stolen property by testifying about what he paid for the stolen items.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon further examination, we conclude that Chaney was wrongly decided.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Adopting the reasoning of Judge Southwick’s dissent in Chaney, we conclude that the mere act of walking through a raised, open garage door does not constitute an “act or force, however slight, employed to effect an entrance” and is not a “breaking.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that it was “unclear if [the testimony] meant the door was unlocked or standing open,” as an evidentiary photograph obtained from security cameras appeared to show Brown opening the porch door.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that the trial court did not err by denying Ladd’s motions for a directed verdict and a JNOV as to Count I, conspiracy to commit grand larceny, and therefore affirm Ladd’s conviction on this count.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, employing the plain-error doctrine, we find that the State failed to meet its burden of proof that Ladd’s actions satisfied the essential element of breaking.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While this action satisfies the “entering” element of burglary, we find that it does not satisfy the “breaking” element.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that Ladd’s act of walking through Brown’s open garage door does not satisfy the necessary “breaking” element to warrant a charge for burglary of a dwelling.', 'general', 'Ladd v. State', 'https://www.courtlistener.com/opinion/5057951/', '5057951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that reckless driving is not a lesser included offense of felony DUI, and we affirm the trial judge’s refusal of Cribb’s requested charge.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial judge abused his discretion in admitting the blood alcohol test.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Accordingly, we find that section 56-5-2950(a) is inapplicable to this case because Cribb was not arrested until some time after the blood alcohol test.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the issue before us, we find that felony DUI, the greater offense, does not contain all the elements of reckless driving, the lesser offense.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that the trial judge was correct in ruling that section 56-5-2950 is inapplicable to pre-arrest DUI investigations and that reckless driving is not a lesser included offense of felony DUI.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 98 (1992), this Court held that a judge’s exclusion of evidence, based on a chain of custody similar to the one presented here, was within his sound discretion.', 'general', 'State v. Cribb', 'https://www.courtlistener.com/opinion/1307625/', '1307625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we hold that the trial court did not depart from the essential requirements of the law by following the Fourth District, then any discussion we may undertake arguing that the Fourth District’s opinion is incorrect becomes mere dicta.', 'general', 'Nader v. Florida Department of Highway Safety & Motor Vehicles', 'https://www.courtlistener.com/opinion/5058105/', '5058105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Howell, n 2 supra, p 21, a plurality of this Court held that the gross indecency statutes prohibit oral sexual acts with a person under the age of consent.', 'general', 'People v. Lino', 'https://www.courtlistener.com/opinion/1303659/', '1303659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these changes [developments in the right to privacy] and in light of our own awareness that community values on the subject of permissible sexual conduct no longer are as monolithic as the Jaquith case suggested they were in 1954, we conclude that [Mass Ann Laws, ch 272, § 35] must be construed to be inapplicable to private, consensual conduct of adults.', 'general', 'People v. Lino', 'https://www.courtlistener.com/opinion/1303659/', '1303659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lino, we reverse the decision of the Court of Appeals and we affirm the defendant’s conviction.', 'general', 'People v. Lino', 'https://www.courtlistener.com/opinion/1303659/', '1303659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brashier, we reverse the decision of the Court of Appeals in part and affirm in part.', 'general', 'People v. Lino', 'https://www.courtlistener.com/opinion/1303659/', '1303659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence contained in the record before us fails, as a matter of law, to establish a causal relationship between the Minor’s speech at issue and the disturbance sought to be prevented by HRS § 711-1106(1)(b)—the likelihood of provoking Officer Mariani to a violent response.', 'general', 'In the Interest of Doe', 'https://www.courtlistener.com/opinion/1229793/', '1229793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 Because, for the reasons stated in this opinion, the evidence was insufficient as a matter of law to establish that the Minor violated HRS § 711-1106(1)(b), we reverse the district family court’s order and decree and remand for the entry of an order dismissing the petition.', 'dismissal', 'In the Interest of Doe', 'https://www.courtlistener.com/opinion/1229793/', '1229793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1242 (1977), we reversed a disorderly conduct conviction under HRS § 711-1101,19 premised solely upon “alleged[ly] abusive language .', 'general', 'In the Interest of Doe', 'https://www.courtlistener.com/opinion/1229793/', '1229793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the district family court’s amended findings, order, and decree adjudging the Minor a law violator and remand for the entry of an order dismissing the petition.', 'dismissal', 'In the Interest of Doe', 'https://www.courtlistener.com/opinion/1229793/', '1229793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Dover’s guilty plea was not voluntarily and knowingly made;', 'plea', 'Dover v. State', 'https://www.courtlistener.com/opinion/1233101/', '1233101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the PCR judge ruled to the contrary, we find that Dover’s plea was not voluntarily and understandingly made.', 'plea', 'Dover v. State', 'https://www.courtlistener.com/opinion/1233101/', '1233101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the facts of this case are very similar to those presented in Hazel.', 'general', 'Dover v. State', 'https://www.courtlistener.com/opinion/1233101/', '1233101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the evidence presented in the record, we find that Dover’s guilty plea was made in ignorance of its consequence and therefore was not voluntarily and understandingly made.', 'plea', 'Dover v. State', 'https://www.courtlistener.com/opinion/1233101/', '1233101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed on the grounds that she did not understand the consequences of her guilty plea.', 'plea', 'Dover v. State', 'https://www.courtlistener.com/opinion/1233101/', '1233101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we do not agree with the lower court’s reasoning, we affirm the result on other grounds appearing in the record.', 'general', 'Dover v. State', 'https://www.courtlistener.com/opinion/1233101/', '1233101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Williams, a divided panel of this Court held that an appeal which challenged the sufficiency of the evidence in a bench trial was procedurally barred because defense counsel had not made a motion to strike the evidence or a motion to set aside the verdict.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a defendant may be convicted for both malicious assault and attempted murder in the first degree without violating the proscription against double jeopardy found within article III, section 5 of the West Virginia Constitution since the provisions for each offense require proof of an additional fact which the other does not.', 'general', 'State v. George', 'https://www.courtlistener.com/opinion/1314560/', '1314560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[a]t that point from interviewing people there at the scene we found that, myself and .', 'general', 'State v. George', 'https://www.courtlistener.com/opinion/1314560/', '1314560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the bathroom stalls here, like the telephone booth in Katz, were temporarily private places whose momentary occupants’ expectations'' of privacy are recognized by society as reasonable.', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that defendant was forewarned that the conduct in which he was engaged is prohibited by the gross indecency statute.', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that, to the extent the search warrant issued authorized the video surveillance, it was invalid.', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the statute was not unconstitutionally vague in this instance.', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the prosecutor, in good faith, attempted to factually distinguish Dezek from the instant case on the basis that the activity at issue herein took place in "public” while the activity in Dezek took place in private (through a hole cut in the partition dividing the bathroom stalls).', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court made a mistake in not granting defendant’s motion and reverse on this basis.', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the search warrant issued herein was invalid to the extent that it authorized the video surveillance.', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this statement constitutes hearsay within hearsay.', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the personal knowledge requirement was satisfied.', 'general', 'People v. Kalchik', 'https://www.courtlistener.com/opinion/1236281/', '1236281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1317433/', '1317433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the trial court did not abuse its discretion in denying Anderson’s severance motion and Anderson was not prejudiced by the admission into evidence of prior convictions because the trial court gave a sufficient limiting instruction to the jury.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1317433/', '1317433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant cannot be required to pay restitution in an amount exceeding statutorily-prescribed monetary parameters of the crime to which he pleads guilty unless he voluntarily and intelligently agrees to pay a higher amount.', 'plea', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court could impose restitution as a proper condition of probation.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the trial court ordered an improper amount of restitution and erred in allowing the probation department to set the manner of payment.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only if one of these three statements are found in the record will we conclude that a defendant voluntarily and intelligently agreed to pay restitution in an amount exceeding statutorily-prescribed monetary parameters of the crime to which he pled guilty.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the Criminal Code, we conclude that the only statutes under which the trial court could have ordered restitution in this case are A.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1244066/', '1244066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Fink v. Ryan', 'https://www.courtlistener.com/opinion/2148834/', '2148834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the circuit court''s judgment.', 'general', 'Fink v. Ryan', 'https://www.courtlistener.com/opinion/2148834/', '2148834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a statement of reasons for the sentence was not required because “[t]he sentence of imprisonment was .', 'sentencing', 'State of Iowa v. Tina Lynn Thacker', 'https://www.courtlistener.com/opinion/2794535/', '2794535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a sentencing court does not abuse its discretion for failing to state sufficient reasons for imposing a sentence if it “was merely giving effect to the parties’ agreement.', 'sentencing', 'State of Iowa v. Tina Lynn Thacker', 'https://www.courtlistener.com/opinion/2794535/', '2794535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 921, however, we reversed the caselaw upon which Alloway was based.', 'general', 'State of Iowa v. Tina Lynn Thacker', 'https://www.courtlistener.com/opinion/2794535/', '2794535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held in Weiss v.', 'general', 'Wright v. City of Little Rock', 'https://www.courtlistener.com/opinion/2100846/', '2100846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, in the absence of a different procedure being prescribed in the statute, the action by Ms.', 'general', 'Wright v. City of Little Rock', 'https://www.courtlistener.com/opinion/2100846/', '2100846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying those criteria to the facts before us, we conclude that the trial court correctly refused to instruct on intoxication.', 'general', 'State v. Mauricio', 'https://www.courtlistener.com/opinion/1988780/', '1988780') ON CONFLICT DO NOTHING;
