INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the City failed to present sufficient evidence to establish Mr.', 'general', 'Salt Lake City v. Carrera', 'https://www.courtlistener.com/opinion/2827593/', '2827593') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '{24 We reverse the conviction of Mr.', 'general', 'Salt Lake City v. Carrera', 'https://www.courtlistener.com/opinion/2827593/', '2827593') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Flanagan, we conclude that Appellant’s guilty plea must also be withdrawn.', 'plea', 'Com. v. Dinell, Z.', 'https://www.courtlistener.com/opinion/10316093/', '10316093') ON CONFLICT DO NOTHING;
