INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Belton applied the Chimel rule to a passenger, concluding “we hold that when a policeman has made a lawful custodial arrest of the occupant of an automobile, he may, as a contemporaneous incident of that arrest, search the passenger compartment of that automobile.', 'general', 'State of Iowa v. Jesse Michael Gaskins', 'https://www.courtlistener.com/opinion/2812905/', '2812905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the court of appeals decision that had relied on Fourth Amendment precedent.', 'search_seizure', 'State of Iowa v. Jesse Michael Gaskins', 'https://www.courtlistener.com/opinion/2812905/', '2812905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '045, subdivision 1, and the surrounding statutory provisions, we conclude that the Legislature’s intent is discernible from the statute’s plain and unambiguous language.', 'general', 'State of Minnesota v. Brandon Wayne Riggs', 'https://www.courtlistener.com/opinion/2813698/', '2813698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '045, subdivision 1, according to the plain and ordinary meaning of its words, we conclude that the district court erred by considering factors beyond those expressed in this statutory provision when awarding restitution.', 'general', 'State of Minnesota v. Brandon Wayne Riggs', 'https://www.courtlistener.com/opinion/2813698/', '2813698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we concluded that the phrase “shall consider the following factors” in Minn.', 'general', 'State of Minnesota v. Brandon Wayne Riggs', 'https://www.courtlistener.com/opinion/2813698/', '2813698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '045, subdivision 1, provides an exclusive list of factors for determining the amount of restitution to award, we affirm the decision of the court of appeals.', 'general', 'State of Minnesota v. Brandon Wayne Riggs', 'https://www.courtlistener.com/opinion/2813698/', '2813698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the decision of the court of appeals and remand to the district court for further proceedings consistent with this opinion.', 'general', 'State of Minnesota v. Brandon Wayne Riggs', 'https://www.courtlistener.com/opinion/2813698/', '2813698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the entire record, we find that the trial judge
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We will not find error in the limitation of cross-examination unless we find that the rationale of the trial court for limiting cross-examination was clearly untenable.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/2160935/', '2160935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the judge’s decision not to recuse himself and allow an evidentiary hearing constituted an abuse of discretion because it deprived Owen of her substantial right to determine whether a further instruction on the State’s burden of proof had been given without her knowledge and, if so, whether such conduct was prejudicial.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/2160935/', '2160935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on all errors properly raised on appeal except those
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court on all matters properly raised on appeal except Owen’s motion for new trial.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/2160935/', '2160935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the officer was in possession of specific, articulable facts that, together with rational inferences from those facts, provided an objective basis for suspicion of criminal activity and therefore, the stop was warranted.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/1348993/', '1348993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), in which we held that an anonymous citizen report of a possibly drunken driver, giving the vehicle’s license plate number and vehicle’s location and direction of travel, did not provide reasonable suspicion for a traffic stop.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/1348993/', '1348993') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the low
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After an independent review of the undisputed facts, we conclude that the district court erred in its determination that the officer’s stop of Richardson was unlawful.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/1348993/', '1348993') ON CONFLICT DO NOTHING;
