INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these communications do not violate Rule 1.', 'general', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that Patton has made no showing that Judge Vollor engaged in any improper ex parte communications or “earwigging,” or that he had any personal knowledge of the disputed facts of Patton’s case prior to trial.', 'general', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '22 Therefore, as Patton has made absolutely no showing of actual prejudice or bias on the part of Judge Vollor, we find that Judge Vollor did not abuse his discretion in denying *79Patton’s motion for recusal.', 'general', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the circuit court did not abuse its discretion in releasing Evans from his subpoena, as Patton refused to divulge how Evans’s testimony would aid his defense and made no showing that there was a colorable need for his testimony-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the amendment to Count I did not prejudice Patton and that the circuit court did not err in allowing the amendment to Count I of the indictment to change the charge to attempt to commit false pretense.', 'general', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the amendments to Counts IV and V were to form only.', 'general', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As Patton does not challenge the sufficiency of the evidence, but rather again challenges the sufficiency of the indictment, we find that this issue is without merit.', 'general', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm Patton’s convictions and sentences.', 'sentencing', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm his convictions and sentences.', 'sentencing', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, *84we affirm the judgment of the Winston County Circuit Court.', 'general', 'Patton v. State', 'https://www.courtlistener.com/opinion/5105104/', '5105104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have reviewed the record and conclude that no abuse of discretion is disclosed, and therefore we affirm the judgment of the trial court.', 'general', 'State v. Hood', 'https://www.courtlistener.com/opinion/1377962/', '1377962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence was closely balanced, as there were a number of factual issues to resolve and testimony was presented in support of both the State’s and defendant’s version of events.', 'general', 'People v. Virgin', 'https://www.courtlistener.com/opinion/2156254/', '2156254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the cumulative effect of the admission of the inadmissible hearsay evidence served to deny defendant his right to confrontation and thus deprived him of a fair trial.', 'general', 'People v. Virgin', 'https://www.courtlistener.com/opinion/2156254/', '2156254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the conduct of the trial judge was proper.', 'general', 'People v. Virgin', 'https://www.courtlistener.com/opinion/2156254/', '2156254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we find that, should defendant be convicted, he would be subject to the mandatory sentencing requirements of section 5 — 8— 4(h).', 'sentencing', 'People v. Virgin', 'https://www.courtlistener.com/opinion/2156254/', '2156254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand this cause and find that the cumulative effect of the improperly admitted hearsay evidence denied defendant a fair trial.', 'general', 'People v. Virgin', 'https://www.courtlistener.com/opinion/2156254/', '2156254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand this cause for a new trial.', 'general', 'People v. Virgin', 'https://www.courtlistener.com/opinion/2156254/', '2156254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because inadmissible hearsay evidence denied defendant a fair trial, we reverse the defendant’s conviction and remand this cause for a new trial.', 'general', 'People v. Virgin', 'https://www.courtlistener.com/opinion/2156254/', '2156254') ON CONFLICT DO NOTHING;
