INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Springs v. State', 'https://www.courtlistener.com/opinion/4395754/', '4395754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the IRAA provides appellant with the requisite "meaningful opportunity" to obtain release from prison well before the end of his natural life expectancy based on his maturation and rehabilitation, we deny his request for a resentencing.', 'sentencing', 'Williams v. United States', 'https://www.courtlistener.com/opinion/6487581/', '6487581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the Superior Court''s denial of appellant''s § 23-110 motion for relief from his sentence, without prejudice to his right to seek a reduction of his sentence pursuant to the IRAA.', 'sentencing', 'Williams v. United States', 'https://www.courtlistener.com/opinion/6487581/', '6487581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that both defendants are entitled to precisely what the Rule provides: credits against all sentences “for any time served in custody in jail or in a state hospital between arrest and the imposition of sentence” on each ease.', 'sentencing', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/7409294/', '7409294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we concluded that although gap-time credits should be applied to the “back end,” as opposed to the “front end,” of sentences, those credits would serve to advance the “primary parole eligibility date” for defendants facing sentences “when neither a judicial nor a statutory parole bar has been imposed [.', 'sentencing', 'State v. Hernandez', 'https://www.courtlistener.com/opinion/7409294/', '7409294') ON CONFLICT DO NOTHING;
