INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that both Grist and Bergerud support the district court’s conclusion that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it can.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/9489643/', '9489643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the magistrate court did not abuse its discretion.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/9489643/', '9489643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the reasons below, we affirm.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/9489643/', '9489643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and if the district court affirmed the magistrate’s decision, we affirm the district
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the approach outlined in McBride is appropriate and hold that the trial court in this matter did not abuse its discretion when it viewed defendant’s intervening convic*445tions for disorderly persons offenses as removing the bar to admission of defendant’s prior criminal convictions as too remote.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/7409346/', '7409346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, based on our review of the pertinent standards and persuasive authority available, we hold that Padilla’s new constitutional pronouncement is not entitled to retroactive application on collateral review based on federal retroactivity standards.', 'general', 'State v. Gaitan', 'https://www.courtlistener.com/opinion/7409341/', '7409341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Giving typical deference due the findings of the PCR court, we held that Nuñez-Valdéz was misinformed by counsel about the deportation consequences of his plea, id.', 'plea', 'State v. Gaitan', 'https://www.courtlistener.com/opinion/7409341/', '7409341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nuñez-Valdéz, supra, this Court held that when counsel provides false or affirmatively misleading advice about the deportation consequences of a guilty plea, and the defendant demonstrates that he would not have pled guilty if he had been provided with accurate information, an ineffective assistance of counsel claim has been established.', 'plea', 'State v. Gaitan', 'https://www.courtlistener.com/opinion/7409341/', '7409341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As already noted, we find that, on this record, there is no demonstration of prejudice here because the record at the time of the plea and sentencing evidences that immigration consequences would not have changed anything for defendant at the time.', 'sentencing', 'State v. Gaitan', 'https://www.courtlistener.com/opinion/7409341/', '7409341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As for the specific deficiencies of counsel asserted, we find that the record is a far cry from what was presented in Nuñez-Valdéz, where the defendant was materially interested in immigration consequences, and initially was assured, inaccurately, that his plea to drug charges would not result in such consequences, and substitute counsel, against that backdrop, only amended the advice to state that deportation was a possibility.', 'plea', 'State v. Gaitan', 'https://www.courtlistener.com/opinion/7409341/', '7409341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we found that the misinformation denied the defendant his right to effective assistance of counsel under the New Jersey Constitution.', 'general', 'State v. Gaitan', 'https://www.courtlistener.com/opinion/7409341/', '7409341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 461 (2009), we hold that defendant has not demonstrated a color-able claim of innocence.', 'general', 'State v. McDonald', 'https://www.courtlistener.com/opinion/7409388/', '7409388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Balancing these factors in accordance with Slater, we hold that the interests of justice do not warrant an order permitting defendant to withdraw his guilty plea, and that the trial court properly denied defendant’s motion to withdraw.', 'plea', 'State v. McDonald', 'https://www.courtlistener.com/opinion/7409388/', '7409388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that trial judges are to consider and balance four factors in evaluating motions to withdraw a guilty plea: (1) whether the defendant has asserted a colorable claim of innocence;', 'plea', 'State v. McDonald', 'https://www.courtlistener.com/opinion/7409388/', '7409388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court properly applied the “interests of justice” standard of Rule 3:9-3(e) and this Court’s analysis in Slater to deny defendant’s motion to withdraw his plea of guilty to a violation of N.', 'plea', 'State v. McDonald', 'https://www.courtlistener.com/opinion/7409388/', '7409388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evi*27denee before the trial court established a factual basis for defendant’s guilty plea to a violation of N.', 'plea', 'State v. McDonald', 'https://www.courtlistener.com/opinion/7409388/', '7409388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the record we find that plaintiff’s statements that he used cocaine in March of 1989 amounted to an admission of the charges against him.', 'general', 'Washington v. POLICE BD. OF CITY OF CHICAGO', 'https://www.courtlistener.com/opinion/2158740/', '2158740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our careful review of the record we hold that the trial courts’ rulings are supported by the evidence.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial courts did not err in admitting appellant’s statements into evidence in his trials.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no deception was practiced by law enforcement agents.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence supports the conviction.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that this issue is spurious.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we hold that appellant’s argument based on references to the trial judge’s post-conviction actions is baseless.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on our previous discussion concerning the vol-untariness of appellant’s statements, we hold that no deception occurred;', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having carefully considered each of appellant’s points on appeal, we affirm the judgments, convictions and sentences in all respects.', 'sentencing', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Cash', 'https://www.courtlistener.com/opinion/1338833/', '1338833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dawkins, this Court held that probationary terms, and mandatory CSP terms for sentences deriving from “no parole offenses,” run concurrently.', 'sentencing', 'State v. PICKLESIMER', 'https://www.courtlistener.com/opinion/1394268/', '1394268') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. PICKLESIMER', 'https://www.courtlistener.com/opinion/1394268/', '1394268') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court erred when it held that the juvenile court did not have jurisdiction over the charges here, and the order waiving jurisdiction cannot be upheld on that basis.', 'general', 'Zamora v. State', 'https://www.courtlistener.com/opinion/1367475/', '1367475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the relevant statutes, we conclude that the juvenile court did have original jurisdiction over the criminal charges alleged to have been committed by Zamora.', 'general', 'Zamora v. State', 'https://www.courtlistener.com/opinion/1367475/', '1367475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), we conclude that the objective of these provisions is the establishment of guidelines for hospitals regarding the proper method for furnishing, subpoenaed hospital records.', 'general', 'State Ex Rel. Allen v. Bedell', 'https://www.courtlistener.com/opinion/1350428/', '1350428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that medical records containing the results of blood alcohol tests ordered by medical personnel for diagnostic purposes are subject to subpoena and shall not be deemed inadmissible by virtue of the provisions of West Virginia Code § 57-5-4d.', 'general', 'State Ex Rel. Allen v. Bedell', 'https://www.courtlistener.com/opinion/1350428/', '1350428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that:
(a) the trial court properly admitted the six-year-old victim’s statement to the police under the tender years exception to the hearsay rule, N.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When measured against this yardstick, we conclude that the prosecutor’s comments did not “raise a reasonable doubt as to whether the error led the jury to a result it otherwise might not have reached.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the requisite elements for admissibility of C.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We find that the prosecutor’s comment was fairly invited by the defense’s statements in summation that C.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the argument was improper, we find that, in those circumstances, it was harmless error.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we affirm the judgment of the Appellate Division affirming R.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the Appellate Division.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Frisby, supra, we held that “ ‘[t]here is no provision in our legal system for a “truth-teller” who is authorized to advise the jury on the basis of ex parte investigations what the facts are and that the defendant’s story is a lie.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[a]ny improper influence on the jury that could have tipped the credibility scale was necessarily harmful and warrant[ed] reversal.', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the defendant’s conviction because, “[b]ased on the hearsay evidence, the police essentially gave the jury their opinion regarding the innocence of [the father] and inferentially the guilt of [the defendant].', 'general', 'State v. R.B.', 'https://www.courtlistener.com/opinion/7408243/', '7408243') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the defendant must receive a new trial.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 911 (1989), this Court held that an indictment charging “that defendant ‘unlawfully, willfully and feloniously and of malice aforethought did kill and murder [the victim]’ is insufficient to support a verdict of guilty of assault, assault inflicting serious injury or assault with intent to kill” because such murder indictment does not specify a murder accomplished by assault.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having done so, we conclude that this is one of those rare cases in which the trial court’s error in failing to instruct on the lesser-included offense was, on the evidence presented, error so fundamental that it denied the defendant a fair trial and quite probably tilted the scales against him.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the defendant must receive a new trial.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that any error involved in the defendant’s conviction and sentence for attempted murder in Gilley was harmless for reasons which are of no consequence here and have since been rejected.', 'sentencing', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statute in question was clearly written and easily understandable by “men of common intelligence.', 'general', 'State v. McNair', 'https://www.courtlistener.com/opinion/1389597/', '1389597') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Neither do we find that defendant’s credibility was not in issue.', 'general', 'State v. McNair', 'https://www.courtlistener.com/opinion/1389597/', '1389597') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1]*505 We hold that it may not.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we hold that payments generated by pension benefits that had been previously equitably distributed are not income for purposes of alimony modification.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that annuity payments purchased with the proceeds of an equitable-distribution award also are not "income" for that purpose to the extent that they reflect return of the principal as opposed to income generated by the principal.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '219 (1974), we held that the statute was to be retroactively applied because that interpretation was necessary to make it workable and give it its most sensible interpretation.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because financial ability of the supporting spouse may be crucial to the proper disposition of a motion for modification, we conclude that a prima facie showing of changed circumstances meets this good cause standard.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed in Gibbons v.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record before us, we hold that defendant did not intentionally waive his right to counsel at the preliminary hearing.', 'general', 'Davila v. State', 'https://www.courtlistener.com/opinion/1399044/', '1399044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Blonigen, Assistant Dis- '' trict Attorney, and the Court having found that the County Court Judge did not abuse his discretion in denying a continuance in this matter at the preliminary hearing, it is ordered that the Defendant’s Motion to Dismiss should be, and is hereby, denied.', 'dismissal', 'Davila v. State', 'https://www.courtlistener.com/opinion/1399044/', '1399044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that he waived that right, and we affirm the judgment.', 'general', 'State v. Tuplin', 'https://www.courtlistener.com/opinion/5142471/', '5142471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶25] We conclude that the totality of Tuplin’s conduct during the trial implies a waiver of his right to testify and an election of his privilege against self-incrimination.', 'general', 'State v. Tuplin', 'https://www.courtlistener.com/opinion/5142471/', '5142471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Tuplin waived his right to testify by not electing to testify during the presentation of the defense, after the court had informed him of his rights and allowed him time to decide whether to testify or avoid self-incrimination.', 'general', 'State v. Tuplin', 'https://www.courtlistener.com/opinion/5142471/', '5142471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Stroman v. United States', 'https://www.courtlistener.com/opinion/5142555/', '5142555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the law does not permit concurrent terms of probation and supervised release and that, when imposing a split sentence, the trial court must suspend the term of supervised release in its entirety.', 'sentencing', 'Richardson v. United States', 'https://www.courtlistener.com/opinion/5143159/', '5143159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the trial judge did not err by initiating or considering an ex parte communication or by failing to recuse herself, and that appellant’s other assignments of error are without merit.', 'general', 'In re D.M.', 'https://www.courtlistener.com/opinion/5144157/', '5144157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We disagree, and as we find appellant’s other claims of error to be meritless, we affirm his delinquency adjudication.', 'general', 'In re D.M.', 'https://www.courtlistener.com/opinion/5144157/', '5144157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that T.', 'general', 'In re T.L.', 'https://www.courtlistener.com/opinion/5144181/', '5144181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court should have granted T.', 'general', 'In re T.L.', 'https://www.courtlistener.com/opinion/5144181/', '5144181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse T.', 'general', 'In re T.L.', 'https://www.courtlistener.com/opinion/5144181/', '5144181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse T.', 'general', 'In re T.L.', 'https://www.courtlistener.com/opinion/5144181/', '5144181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant does not qualify for application of Johnson’s “special rule.', 'general', 'Zanders v. United States', 'https://www.courtlistener.com/opinion/5144219/', '5144219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, because the evidence as a whole suffices to establish that Winston’s self-incriminatory statements to Clark (that also incriminated appellant) were reliable, we conclude that they were properly admitted under the hearsay exception for statements against penal interest.', 'general', 'Zanders v. United States', 'https://www.courtlistener.com/opinion/5144219/', '5144219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that appellant’s assault convictions related to the stabbing cannot stand, the related conviction for PFCV is also reversed.', 'general', 'Zanders v. United States', 'https://www.courtlistener.com/opinion/5144219/', '5144219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the error in admitting Lancaster’s statements about the stabbing are harmless beyond a reasonable doubt with respect to the murder convictions.', 'general', 'Zanders v. United States', 'https://www.courtlistener.com/opinion/5144219/', '5144219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered these claims of error and their effect on appellant’s trial, we reverse his convictions for assault related to the stabbing and remand the case to the trial court for further proceedings.', 'general', 'Zanders v. United States', 'https://www.courtlistener.com/opinion/5144219/', '5144219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse appellant’s convictions in connection with the stabbing (AAWA, ADW, and PFCV) and affirm appellant’s remaining convictions related to the shootings that left two people dead.', 'general', 'Zanders v. United States', 'https://www.courtlistener.com/opinion/5144219/', '5144219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We affirm appellant’s other convictions.', 'general', 'Zanders v. United States', 'https://www.courtlistener.com/opinion/5144219/', '5144219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. LaVallee-Davidson', 'https://www.courtlistener.com/opinion/5144597/', '5144597') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 586 (2007), where we held that an instruction permitting the jury to infer the specific intent to kill from the appellant’s use of a deadly weapon on a vital part of the victim’s body was in accordance with the law, and that trial counsel was not ineffective for failing to object.', 'ineffective_assistance', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '15 In Lively, this Court held that the admission of a prior inconsistent statement of a non-party witness shall be used as substantive evidence only when: (1) the statement was given under oath at a formal legal proceeding;', 'general', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In rejecting the defendant’s claim that the prosecutor improperly gave his personal opinion that the identification witness had told the truth, this Court held that the prosecutor’s comments “were a reasonable response, in both scope and force, to trial counsel’s attack on [the witness’] credibility.', 'general', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the PCRA court’s findings are supported by the ree-*458ord and are free from legal error.', 'general', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we conclude that the PCRA court’s conclusions are supported by the record and free of legal error.', 'general', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Once again, we conclude that the PCRA court’s conclusions are supported by the record and free of legal error.', 'general', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we appreciate that Appellant’s ineffectiveness claim is nuanced and is directed primarily at trial counsel’s failure to “impeach” Wiley’s statement to police, rather than his trial testimony repudiating such statement, we find that Appellant has failed to demonstrate that the proffered evidence would have accomplished such result.', 'ineffective_assistance', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As detailed below, we find that each of these claims, which challenge nearly every aspect of the prosecutor’s closing argument, lack arguable merit.', 'general', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon close examination of the challenged remarks, we find that Appellant’s claim lacks a factual basis as the prosecutor’s comments do not address the trustworthiness of Detective Mangold’s testimony.', 'general', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Once again, we find that the PCRA court’s ruling is supported by the record and free of legal error.', 'general', 'Commonwealth v. Hanible', 'https://www.courtlistener.com/opinion/5144668/', '5144668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Yoakums have not articulated any cogent reason for us to find in this ease that these two torts should be distinguished and we affirm the district court’s conclusion that these causes of action, at least for the purposes of this case, are identical.', 'general', 'Yoakum v. Hartford Fire Insurance', 'https://www.courtlistener.com/opinion/1444047/', '1444047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Yoakums have failed to allege or prove any special harm resulting from this alleged utterance and, thus, we affirm the district court’s granting of Hartford’s motion for summary judgment on the slander cause of action.', 'general', 'Yoakum v. Hartford Fire Insurance', 'https://www.courtlistener.com/opinion/1444047/', '1444047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s dismissal, under I.', 'dismissal', 'Yoakum v. Hartford Fire Insurance', 'https://www.courtlistener.com/opinion/1444047/', '1444047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'City of McCall, # CV 90-244 (Valley County, Idaho), we affirm the district court’s order granting Hartford’s motion for summary judgment for the reasons enunciated in this opinion.', 'general', 'Yoakum v. Hartford Fire Insurance', 'https://www.courtlistener.com/opinion/1444047/', '1444047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s due process rights were not violated, and affirm the trial court’s revocation of appellant’s probation and ordered execution of the previously imposed sentence.', 'sentencing', 'Morgan v. United States', 'https://www.courtlistener.com/opinion/5145312/', '5145312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*538Based on our review of the record, we conclude that the factual inconsistency between Lieutenant Murphy’s testimony at trial and at the probation-revocation show-cause hearing did not make the latter constitutionally infirm.', 'general', 'Morgan v. United States', 'https://www.courtlistener.com/opinion/5145312/', '5145312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the inconsistency was therefore largely immaterial to the revocation of appellant’s probation, we conclude that appellant’s due process rights were not violated.', 'general', 'Morgan v. United States', 'https://www.courtlistener.com/opinion/5145312/', '5145312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Williams’s convictions.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/5145607/', '5145607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 4] We affirm the judgment.', 'general', 'State v. George', 'https://www.courtlistener.com/opinion/5145606/', '5145606') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the judge did not abuse his discretionary authority over the order of proof by requiring English to present some evidence that he acted in self-defense before he could introduce the evidence of the decedent’s propensity for violence.', 'general', 'Hargraves v. United States', 'https://www.courtlistener.com/opinion/5146233/', '5146233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judge did not commit any error entitling Hargraves, Gilliam, or English to relief.', 'general', 'Hargraves v. United States', 'https://www.courtlistener.com/opinion/5146233/', '5146233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm appellants’ convictions.', 'general', 'Hargraves v. United States', 'https://www.courtlistener.com/opinion/5146233/', '5146233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the order of the ALJ.', 'general', 'Ray v. Office of Attorney General', 'https://www.courtlistener.com/opinion/5146442/', '5146442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the frisk was permissible under the circumstances.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1434252/', '1434252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1434252/', '1434252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we affirm Judge Moody’s finding that Brown consented to Stevens entering the room.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1434252/', '1434252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the order of the Superior Court, and remand to that court for consideration of Appellee’s PCRA issues that remain in abeyance.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/5147533/', '5147533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of the Superior Court and remand to that court for consideration of Appellee’s PCRA issues that *322remain in abeyance.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/5147533/', '5147533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, Appellee filed appeals from the denial of PCRA relief in each of these cases, and we affirmed.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/5147533/', '5147533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that Appellant’s appeal period had already expired before he requested an extension of time to file post-sentence motions, and that all claims not associated with our automatic review of capital cases were not preserved.', 'sentencing', 'Commonwealth v. Hairston', 'https://www.courtlistener.com/opinion/5147553/', '5147553') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion when it held that the arson evidence of which Appellant complains was relevant and admissible.', 'general', 'Commonwealth v. Hairston', 'https://www.courtlistener.com/opinion/5147553/', '5147553') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because evidence of Appellant’s escape was admissible, the photographs were not inflammatory, and Appellant has not established how admission of these photographs could have caused him prejudice, we conclude that any possible error resulting from their admission was harmless.', 'general', 'Commonwealth v. Hairston', 'https://www.courtlistener.com/opinion/5147553/', '5147553') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our automatic review, we affirmed Appellant’s conviction and sentence.', 'sentencing', 'Commonwealth v. Hairston', 'https://www.courtlistener.com/opinion/5147553/', '5147553') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellant’s judgment of sentence.', 'sentencing', 'Commonwealth v. Hairston', 'https://www.courtlistener.com/opinion/5147553/', '5147553') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that it would be improvident to review the merits of Orellana’s sentencing issue sua sponte without providing him his constitutionally mandated right to the assistance of counsel on direct appeal.', 'sentencing', 'Commonwealth v. Orellana', 'https://www.courtlistener.com/opinion/5147682/', '5147682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On December 30, 2013, we issued a memorandum, in which we found that counsel had failed to comply with the requirements of Anders/Santiago.', 'general', 'Commonwealth v. Orellana', 'https://www.courtlistener.com/opinion/5147682/', '5147682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we found that counsel’s theory that Orellana had waived his challenge to the sufficiency of the evidence was infirm.', 'general', 'Commonwealth v. Orellana', 'https://www.courtlistener.com/opinion/5147682/', '5147682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review, we conclude that the trial court properly rejected Orie’s claim, finding that the two theft by diversion of services counts were each based on separate and distinct criminal acts.', 'general', 'Commonwealth v. Orie', 'https://www.courtlistener.com/opinion/5147767/', '5147767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to Orie’s argument, we find that Orie’s defense was not that she believed comp time political activity done in the legislative office was lawful.', 'general', 'Commonwealth v. Orie', 'https://www.courtlistener.com/opinion/5147767/', '5147767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court is not bound by the federal district court’s decision in Wecht, and furthermore we find that it is clearly distinguishable from the case presently before us.', 'general', 'Commonwealth v. Orie', 'https://www.courtlistener.com/opinion/5147767/', '5147767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the following, we affirm.', 'general', 'Commonwealth v. Orie', 'https://www.courtlistener.com/opinion/5147767/', '5147767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Orie', 'https://www.courtlistener.com/opinion/5147767/', '5147767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that sections 9754(c)(ll) and (c)(13) do not authorize the PDA.', 'general', 'Commonwealth v. Rivera', 'https://www.courtlistener.com/opinion/5148054/', '5148054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of Pride, we hold that section 9754(c)(13) does not authorize imposition of the PDA on Rivera.', 'general', 'Commonwealth v. Rivera', 'https://www.courtlistener.com/opinion/5148054/', '5148054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Most significantly, in Pride, this Court held, 5-2, that the trial court lacked statutory authority to order the defendant to pay $500.', 'general', 'Commonwealth v. Rivera', 'https://www.courtlistener.com/opinion/5148054/', '5148054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Verilla, this Court held that no statutory authority existed to order the defendant to pay for the Public Defender following his conviction for rape and indecent assault.', 'general', 'Commonwealth v. Rivera', 'https://www.courtlistener.com/opinion/5148054/', '5148054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that this provision is not punitive under the two-prong Smith test.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Balancing the Mendozcb-Martinez factors, we hold that Section 9799.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We believe that it fairly falls within the admittedly broad ambit of the allegation in Coppolino’s Petition and, thus, we hold that it is not waived.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Insofar as we hold that the bulk of Megan’s Law IV does not constitute an ex post facto law and is not overbroad with regard to the requirement that registrants disclose their Internet identifiers to the PSP, we shall grant the Commissioner’s Cross-Motion for Summary Judgment in part and deny it in part.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The only part of this provision that this Court holds to be unconstitutionally punitive with regard to individuals convicted prior to the enactment of the provision, is the requirement that such updates be made in person.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') This Court held that Coppolino’s allegation was sufficiently specific to survive preliminary objections, stating:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Keeping such principles in mind, we conclude that the quarterly verification requirement of Section 9799.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that this provision is non-punitive.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '32 On balance, this disproportionality, along with the similarity to the traditional punishment of parole and the substantial infringement of a fundamental right, we conclude that this provision is punitive.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because none of the avenues of dissemination of registry information applicable in this case involve disclosure of registrants’ Internet identifiers, we conclude that, as in Shuttle''ff, the requirement that registrants disclose their Internet identifiers does not burden the right to anonymous speech.', 'general', 'Coppolino v. Noonan', 'https://www.courtlistener.com/opinion/5148293/', '5148293') ON CONFLICT DO NOTHING;
