INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the required definitional test, we hold that the crime of unauthorized use of a motor vehicle contains at least one essential element not present in the crime of possession of stolen goods;', 'general', 'State v. Nickerson', 'https://www.courtlistener.com/opinion/2509556/', '2509556') ON CONFLICT DO NOTHING;
