INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals as to the issue before us on discretionary review and remand this case to that court for consideration of defendant’s remaining issues on appeal.', 'general', 'State v. Nickerson', 'https://www.courtlistener.com/opinion/2509556/', '2509556') ON CONFLICT DO NOTHING;
