INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we conclude that the hearsay statements testified to by Dr.', 'general', 'People v. LaLone', 'https://www.courtlistener.com/opinion/1856483/', '1856483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in People v Hackett, supra, we concluded that the exclusion of evidence outside the exceptions stated under the rape-shield statute may violate the Sixth Amendment with regard to an individual defendant.', 'general', 'People v. LaLone', 'https://www.courtlistener.com/opinion/1856483/', '1856483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We disagree with that court’s interpretation of the Confrontation Clause and we reverse.', 'general', 'People v. LaLone', 'https://www.courtlistener.com/opinion/1856483/', '1856483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that the trial court erred in permitting James Heath to testify in the State''s case where he was not disclosed to Lowry as a witness prior to the trial.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient evidence of terroristic threats to "burn" the victim to support the stalking conviction, along with numerous incidents of harassment, vandalism, and other hostile acts directed toward the victim and her family.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient circumstantial evidence, properly connected, to support the conviction for arson.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the argument has merit under the circumstances of this case.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in denying Lowry''s motion for continuance.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although it is an issue that will not arise on retrial because Heath is now known to the defense, we conclude that it is a further basis for reversal of this case, based in essence upon the State''s conduct in discovery proceedings.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the evidence regarding the patio furniture does not have the same degree of connection to Lowry, we find that the trial court did not abuse its discretion in admitting *841 the testimony.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for a new trial because the trial court abused its discretion by failing to grant a continuance when counsel for Lowry had received a voluminous amount of the State''s discovery just days prior to the trial, which materially affected the defense''s trial strategy and severely limited counsel''s ability to prepare for trial.', 'general', 'Lowry v. State', 'https://www.courtlistener.com/opinion/2173083/', '2173083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we recognize that the statute grants a right to such treatment as is psychiatrically indicated, we hold that on this record the sentencing court erred in attempting to determine whether that treatment would in fact be provided.', 'sentencing', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that on the record before us the sentencing court was an inappropriate forum to determine that the sentencing provisions of MCL 768.', 'sentencing', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that this statute requires a sentencing court to obtain a report from the Center for Forensic Psychiatry evaluating a defendant’s present mental health prior to sentencing a defendant found guilty but mentally ill.', 'sentencing', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court’s factual finding that the conditions at the Department of Corrections facilities posed a threat of immediate and irreparable injury to the defendant was made on an inadequate factual record and consequently does not impair our holding.', 'general', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that it obviously contemplates such an inquiry and implicitly requires one.', 'general', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant’s interest in the legislatively created sentencing alternative of probation will be protected adequately if the sentencing court is required to obtain a report on defendant’s present mental health prior to sentencing and provides a procedure for review to allow shortening or discontinuing the period of probation if the reasons for the five-year period no longer obtain.', 'sentencing', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Court of Appeals.', 'general', 'People v. McLeod', 'https://www.courtlistener.com/opinion/1938332/', '1938332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the “potential imposition of a death sentence, for the crimes for which defendant is charged are clearly penal consequences about which a defendant must be fully informed.', 'sentencing', 'State v. McQuaid', 'https://www.courtlistener.com/opinion/2366355/', '2366355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When balancing the serious detriment to the State of conducting a trial after the delay of fourteen years with the fact that defendant gained substantial benefit from the plea bargain, we conclude that defendant cannot demonstrate that the death-eligibility misinformation materially and prejudicially influenced his decision to plead guilty.', 'plea', 'State v. McQuaid', 'https://www.courtlistener.com/opinion/2366355/', '2366355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[i]f a defendant does not ‘correctly assess every relevant factor entering into his decision’, this will not automatically render his plea involuntary or unintelligent.', 'plea', 'State v. McQuaid', 'https://www.courtlistener.com/opinion/2366355/', '2366355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that the information conveyed to the defendant was not false or misleading and did not constitute a material misrepresentation sufficient to allow the defendant to withdraw his plea.', 'plea', 'State v. McQuaid', 'https://www.courtlistener.com/opinion/2366355/', '2366355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a trial court must inform a defendant of any loss of parole opportunities that may be a component of a sentence imposed and that it is a court’s responsibility to ensure, through questioning, that a defendant understands that a period of parole ineligibility can be made part of the sentence.', 'sentencing', 'State v. McQuaid', 'https://www.courtlistener.com/opinion/2366355/', '2366355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 521 (1982), we affirmed the Appellate Division’s ruling that the defendant’s reasonable expectations in the plea bargain were not fulfilled because the defendant was not informed of the period of parole ineligibility to which he might be sentenced.', 'sentencing', 'State v. McQuaid', 'https://www.courtlistener.com/opinion/2366355/', '2366355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Appellate Division denying defendant’s petition for post-conviction relief.', 'general', 'State v. McQuaid', 'https://www.courtlistener.com/opinion/2366355/', '2366355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such an action is sufficiently analogous to the "defenses” of self-defense, entrapment and duress to require a similar allocation of the burdens of production and proof.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instructions given by the trial court, when viewed as a whole, adequately instructed the jury on the state’s burden of proof.', 'jury_instruction', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when, as in this case, the defendant is charged with premeditated murder and sufficient evidence is adduced at trial for a jury reasonably to infer that the defendant caused the death of another person in the heat of passion, provoked by such words or acts of another as would provoke a person of ordinary self-control under like circumstances, the state has the burden to prove beyond a reasonable doubt the absence of heat of passion.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the court’s jury instructions, when viewed as a whole, were more than adequate to inform the jury of the state’s burden of proof.', 'jury_instruction', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instructions in this case were more than sufficient to instruct the jury on the state’s burden of proof.', 'jury_instruction', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute is not impermissibly vague in all of its applications.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that the evidence presented at trial was sufficient for the jury to conclude that from the time Auchampach and Counts met in April 1991 until Counts’ murder in March 1993, Auchampach engaged in acts of assaultive behavior toward Counts and made terroristic threats against her.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Niska, for example, we concluded that an action taken to protect a child from physical or sexual assault or substantial emotional harm "is an affirmative defense" to the crime of deprivation of parental, custodial, or visitation rights.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We affirm.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reason set forth herein we find that the trial court did abuse its discretion and thus, reverse the decision of the Superior Court and remand this matter to the trial court for a new trial.', 'general', 'Commonwealth v. Shaffer', 'https://www.courtlistener.com/opinion/1929460/', '1929460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We may set aside Jones’ AAF conviction for evidentiary insufficiency only if, after viewing the record in the light most favorable to the prosecution, we conclude that there was no evidence upon which an impartial jury could fairly find, beyond a reasonable doubt, that Jones committed the offense.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 417, we held that when a defendant’s oral statements have been introduced against him, the trial court must instruct the jury that it should consider such evidence with caution “in view of the generally recognized risk of inaccuracy and error in communication and recollection of verbal utterances and misconstruction by the hearer.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Loftin I, supra, although rejecting the argument that a lengthy noncapital sentence must be presented as a mitigating factor, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure of the trial court to provide a Hampton charge regarding Wrigley’s testimony was not plain error clearly capable of producing an unjust result.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*77Nonetheless, we conclude that the trial court’s actions did not amount to reversible error.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brown we concluded that jury unanimity was required for the State to prove beyond a reasonable doubt that a defendant committed a murder by his own conduct.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Rose, supra, we concluded that the cumulative effect of numerous prosecutorial improprieties required reversal of a death sentence.', 'sentencing', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a preliminary matter, we find that Hampton does not apply to the bulk of the incriminating statements allegedly made by defendant;', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a reasonable jury could conclude that a conversation between defendant and Wrigley occurred, and that the court’s admission of Wrigley’s testimony was therefore appropriate.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the sequential charge in Mejia constituted one of the “crucial defects” in the court’s instructions that required reversal of the defendant’s death sentence.', 'sentencing', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 951, we reversed a death sentence primarily because of the trial court’s failure to provide the charge on serious-bodily-injury murder formerly re*37quired by Gerald, supra, 113 N.', 'sentencing', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 308 (1984), this Court held that empirical data regarding the diminished criminality of men over fifty-five years old was relevant and admissible at the penalty phase of a capital trial.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court’s instruction had the “potential to foreclose jury consideration of whether passion/provocation should reduce an otherwise purposeful killing from murder to manslaughter.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Biegenwald, we held that the failure to instruct the jury on accomplice liability, when neither that theory nor facts supporting such a charge was ever put before the jury, was not error.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Therefore, we conclude that Warren was convicted under Ark.', 'general', 'Law v. State', 'https://www.courtlistener.com/opinion/2172751/', '2172751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that there was substantial evidence showing that.', 'general', 'Law v. State', 'https://www.courtlistener.com/opinion/2172751/', '2172751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the circumstances of this case, the Probst jury should have received specific instructions regarding jury unanimity with regard to their assessment of which act (Probst’s shot or Miller’s) supported the verdict.', 'general', 'Probst v. State', 'https://www.courtlistener.com/opinion/1932327/', '1932327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the order of the jury instructions and the inaccurate use of gender had such potential for juror confusion that the reversal of Probst’s convictions is required.', 'jury_instruction', 'Probst v. State', 'https://www.courtlistener.com/opinion/1932327/', '1932327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In considering the Probst jury instructions as a whole, we find that they failed to meet the “reasonably informative and not misleading” standard.', 'jury_instruction', 'Probst v. State', 'https://www.courtlistener.com/opinion/1932327/', '1932327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under a prior statute, this Court held that an accessory was not a principal and that there could be no conviction of a defendant as an accessory upon an indictment as a principal.', 'general', 'Probst v. State', 'https://www.courtlistener.com/opinion/1932327/', '1932327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Commonwealth v. Roland', 'https://www.courtlistener.com/opinion/1947494/', '1947494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'United States, supra, we held that the retroactive application of the obscenity standards announced in Miller v.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that "[n]o legitimate state interest would have been served by requiring repetition of a patently futile objection," we held that the Alabama procedural ruling did not preclude our consideration of the defendant''s constitutional claim.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the gravity of the State''s interests in this context, we find that Ohio may constitutionally proscribe the possession and viewing of child pornography.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '18, we found that the statute was not overbroad because only "a tiny fraction of materials within the statute''s reach" was constitutionally protected.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the convictions on due process grounds because the South Carolina Supreme Court''s expansion of the statute was unforseeable and therefore the petitioners had no reason to suspect that their conduct was criminal.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To conclude, although we find Osborne''s First Amendment arguments unpersuasive, we reverse his conviction and remand *126A for a new trial in order to ensure that Osborne''s conviction stemmed from a finding that the State had proved each of the elements of § 2907.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ferber, we affirmed a conviction under a New York statute that made it a crime to promote the " `lewd exhibition of [a child''s] genitals.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ''' " In light of this construction, we rejected the petitioners'' facial challenge to the statute as written, and we affirmed the petitioners'' convictions under the section after finding that the petitioners had fair notice that their conduct was criminal.', 'general', 'Osborne v. Ohio', 'https://www.courtlistener.com/opinion/112417/', '112417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') (“Because this issue is cognizable on a petition for post-conviction relief, we hold that the Law Division judge erred by refusing to consider the question.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 621 (1997), we held that the public interest in the reliability and integrity of a decision to sentence a defendant to death transcends the normal procedures governing post-conviction review.', 'sentencing', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 76 (“We find that counsel’s examination .', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/1969802/', '1969802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 46121 provide such authorization, we hold that Bullers’s arrest was unlawful and the evidence found by the search pursuant thereto is inadmissi*94ble.', 'general', 'Commonwealth v. Bullers', 'https://www.courtlistener.com/opinion/1947647/', '1947647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Commonwealth alternatively argues that if we find that no authority exists for the arrest, we should consider the admissibility of the evidence incident to a pat-down search conducted while taking Bullers into custody for purposes of notification.', 'general', 'Commonwealth v. Bullers', 'https://www.courtlistener.com/opinion/1947647/', '1947647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Superior Court and find'' that warrantless arrests under such circumstances are not authorized.', 'general', 'Commonwealth v. Bullers', 'https://www.courtlistener.com/opinion/1947647/', '1947647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a violation of § 6308, unaccompanied by any disorderly conduct, a breach of the peace, or public drunkenness, does not fall within § 46121 of the Borough Code.', 'general', 'Commonwealth v. Bullers', 'https://www.courtlistener.com/opinion/1947647/', '1947647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the requirements of due process were not satisfied here.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1980302/', '1980302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given our view, however, that the proceeding set forth in the Act to determine whether one is a sexually violent predator is a separate factual determination, the end result of which is the imposition of criminal punishment, we hold that anything less than the full panoply of the relevant protections which due process guarantees is violative of the Fourteenth Amendment.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1980302/', '1980302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In weighing the two, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court properly determined that the Act is violative of the procedural due process requirements of the Fourteenth Amendment, we need not address the remaining constitutional challenges raised, or analyze the due process provisions of the State Constitution since the federal constitution establishes certain “minimum” standards, which each state has the power to expand.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1980302/', '1980302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, because we find that the procedure whereby one is determined to be a sexually violent predator is unconstitutional, we strike all of the provisions referring to this designation.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1980302/', '1980302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We hold that there was no error in the refusal to provide the cognate offense instruction because udaa and armed robbery are not of the same class or category of offenses.', 'general', 'People v. Hendricks', 'https://www.courtlistener.com/opinion/1969369/', '1969369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the requirement for instruction on cognate lesser included offenses that the principal offense and the lesser crime be of the same class or category, or be closely related, we find that armed robbery and udaa do not possess the requisite inherent relationship necessary to consider the possibility of such instruction.', 'general', 'People v. Hendricks', 'https://www.courtlistener.com/opinion/1969369/', '1969369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 655, 657-658 (1988) we held that section 1547(a)(1), 75 Pa.', 'general', 'Commonwealth, Department of Transportation, Bureau of Driver Licensing v. Bird', 'https://www.courtlistener.com/opinion/1973797/', '1973797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A year after the Lewis decision, a separate panel of this court held in Department of Transportation, Bureau of Driver Licensing v.', 'general', 'Commonwealth, Department of Transportation, Bureau of Driver Licensing v. Bird', 'https://www.courtlistener.com/opinion/1973797/', '1973797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Commonwealth, Department of Transportation, Bureau of Driver Licensing v. Bird', 'https://www.courtlistener.com/opinion/1973797/', '1973797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 533 (1989), this Court held that the police officer, who observed a licensee passed out in the drivers’ seat with the motor running, lacked reasonable grounds to believe that the licensee was driving under the influence on a highway or trafficway.', 'general', 'Commonwealth, Department of Transportation, Bureau of Driver Licensing v. Bird', 'https://www.courtlistener.com/opinion/1973797/', '1973797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1194 (1983), we held that § 110 did not bar the prosecution of an aggravated assault charge when the defendant had previously pled guilty to the summary offense of failing to identify himself at the scene of an accident.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the defendant was denied due process of law because “[ajppeal board panels which are membered by fulltime law enforcement officials are not fair and impartial tribunals to adjudge a law enforcement dispute between a citizen and a police officer.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Judge Giddings’ apparent conflict with the Governor is not a proper basis for disqualification under the test or the scenarios articulated in Cramp-*515ton.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that Judge Giddings’ advice to the plaintiffs appearing in propria persona regarding the structure of their motion was appropriate.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the lower court record, we find that the actions of Judge Giddings do not constitute a deprivation of the department’s due process guarantee of an unbiased and impartial decisionmaker.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ordered that from and after September 18, 1989, Defendant, its officers, agents, servants, employees, and those acting in concert or participation with them are restrained and enjoined from:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the Court of Appeals decision requiring disqualification and remand to the trial court for swift, fair, and accurate resolution.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the disqualification of Judge Giddings was erroneously ordered by the Court of Appeals, we reverse and remand this case for immediate scheduling of trial.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in order to avoid problems of proof on this issue, we hold that as an absolute rule it is reversible error for the trial court sitting without a jury to refer to the transcript of testimony taken at the preliminary examination except under the exceptions provided by statute.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '542 NW2d 344 (1995), in which the Court of Appeals held: “we conclude that the nature and scope of the media exposure create an appearance of bias in this case.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wheelock, supra, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that “[a]n explanation of the ‘tourist standard’ was properly omitted from the jury instructions in this case because it is not an element of any offense.', 'jury_instruction', 'Hasty v. United States', 'https://www.courtlistener.com/opinion/1983627/', '1983627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We conclude that the narrow construction accorded by this court to D.', 'general', 'Hasty v. United States', 'https://www.courtlistener.com/opinion/1983627/', '1983627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 443 (1994), we held that “a stop and frisk may be supported by a police radio bulletin only if evidence is offered at the suppression hearing establishing the articulable facts which support the reasonable suspicion.', 'suppression', 'Commonwealth v. Hawkins', 'https://www.courtlistener.com/opinion/1969512/', '1969512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances in this case, including the limited ability of the officers to confirm all of the anonymous tip information, the report that the occupants of the car possessed a gun, and the statistical likelihood that the gun was illegal, we conclude that the intrusion upon the privacy of the car’s occupants was minimal and that the officers had a reasonable suspicion under Terry that authorized their opening of the car doors and questioning the occupants.', 'general', 'Commonwealth v. Hawkins', 'https://www.courtlistener.com/opinion/1969512/', '1969512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that it was error to admit the incriminating statements at trial.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that because the State has not met its burden of proving that it is "clear beyond a reasonable doubt that a rational jury would have found the defendant guilty absent the error," State v.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Martin was subject to custodial interrogation *298during his exchange with law enforcement, and that the Constitution therefore compelled the officers to issue the warnings.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that because the State has not met its burden of proving that it is "clear beyond a reasonable doubt that a rational jury would have found the defendant guilty absent the error," Harvey, 254 Wis.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that in order for an error to be deemed harmless, the party who benefited from the error must show that "it is clear beyond a reasonable doubt that a rational jury would have found the defendant guilty absent the error.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Martin made incriminating statements while in police custody and while being subjected to interrogation by police officers, we conclude that he had a Fifth Amendment right to receive Miranda warnings.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Martin was in custody when asked whether the revolver belonged to him, and that the question constituted interrogation.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the error in this case — the admission of Martin''s statements taken in violation of Miranda — is not harmless as it relates to the felon in possession charge.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and remand the cause for a new trial.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we reverse the court of appeals and remand for a new trial.', 'general', 'State v. Martin', 'https://www.courtlistener.com/opinion/8238757/', '8238757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In keeping with past decisions of this court, we conclude that decriminalizing penalties alone is insufficient to manifest a legislative intent that a statute which previously had been construed to require scienter be applied as one of strict liability.', 'general', 'State v. Olson', 'https://www.courtlistener.com/opinion/1953757/', '1953757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990),[1] in which we held that a trial court''s failure to reduce to writing, at the time of sentencing, its reasons for departing from a guidelines sentence constituted reversible error.', 'sentencing', 'Davis v. State', 'https://www.courtlistener.com/opinion/1143104/', '1143104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we held that every decision of this Court announcing a new rule of law must be given retrospective application in all "pipeline" cases.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1143104/', '1143104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure of the trial judge to file contemporaneous written reasons for a departure sentence may not be raised for the first time in a collateral relief proceeding.', 'sentencing', 'Davis v. State', 'https://www.courtlistener.com/opinion/1143104/', '1143104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Davis failed to raise this issue in his appeal, we find that he, as with other similarly situated defendants, is precluded from raising this issue in a motion for postconviction relief.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1143104/', '1143104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that in applying the test of Harper, supra, to the record before us the evidence of the *548circumstances of the collision, in combination with the physical and testimonial evidence of appellee’s consumption of alcohol, was sufficient to support a reasonable inference that he violated the statute by operating an automobile while his faculties essential to the safe operation of an automobile were substantially impaired.', 'general', 'Commonwealth v. Griscavage', 'https://www.courtlistener.com/opinion/1996025/', '1996025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In examining the opinion of the Superior Court we find that they erréd in two respects.', 'general', 'Commonwealth v. Griscavage', 'https://www.courtlistener.com/opinion/1996025/', '1996025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 447, we held that first degree murder while armed is a “crime punishable by death” within the meamng of the accessory after the fact statute, even though the maximum sentence for first degree murder is now life in prison pursuant to D.', 'sentencing', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Williams, we held that the driver of a getaway car was not an accessory after the fact to armed robbery because the offense was not yet complete;', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these standards for review of claimed evidentiary insufficiency, we affirm''the convictions.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment on the obstruction of justice count and the conviction for accessory after the fact to first degree murder while armed, but remand for resentencing on the latter conviction.', 'sentencing', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1951837/', '1951837') ON CONFLICT DO NOTHING;
