INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the plain language of this statute does not
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Roberts, we held that Utah Code section
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we held that the classes created by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” 41 We conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Outzen', 'https://www.courtlistener.com/opinion/4398691/', '4398691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that neither Wis.', 'general', 'State v. Harrell', 'https://www.courtlistener.com/opinion/2067478/', '2067478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Judge DeChambeau clearly made a subjective determination regarding his ability to proceed in the case.', 'general', 'State v. Harrell', 'https://www.courtlistener.com/opinion/2067478/', '2067478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 662 (1989), we found that this subsection contains six fact-specific situations, the existence of which can be determined objectively, and one general subjective situation which is based solely upon the judge''s state of mind.', 'general', 'State v. Harrell', 'https://www.courtlistener.com/opinion/2067478/', '2067478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the trial court''s decision to *961excuse Wyatt for cause was neither illogical nor arbitrary.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2067285/', '2067285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the State did not change its theory, and we reject Jackson''s claim of prosecutorial misconduct.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2067285/', '2067285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and the 100-year sentence.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2067285/', '2067285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant was brought to trial within the statutory periods prescribed by the speedy-trial statute.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing reasons, we hold that .', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the ex parte communications did not prejudice defendant, and as a result, such improper communications were harmless beyond a reasonable doubt.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court did not err in admitting testimony concerning these statements, which were made during the course of and in furtherance of the conspiracy.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that there was no evidence that the sentencing judge improperly considered the memorandum for sentencing purposes, after noting that the sentencing judge did not refer to the memorandum or indicate that it influenced his sentencing decision.', 'sentencing', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Permanian’s statements made in the context of receiving payment from Rinaldi were admissible under the coconspirator exception to the hearsay rule.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the case at bar, we conclude that the trial judge abused her discretion in admitting evidence that defendant had pistol-whipped Behenna.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the context of the proceeding, we conclude that the prosecutor’s comments were not improper nor did they deprive defendant of a fair trial.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court abused its discretion in attributing this delay to the State.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that only 97 days from defendant’s arrest to commencement of his trial for murder are not attributable to defendant.', 'general', 'People v. Kliner', 'https://www.courtlistener.com/opinion/1998534/', '1998534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '551 NW2d 891 (1996), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the level of assurance that a preserved, nonconstitutional error justifies reversal of a conviction is the “more probable than not” standard.', 'general', 'People v. Lukity', 'https://www.courtlistener.com/opinion/1985231/', '1985231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the admission of evidence bolstering complainant’s character for truthfulness was error here, but that this error did not result in a miscarriage of justice that would justify reversal of defendant’s conviction under § 26.', 'general', 'People v. Lukity', 'https://www.courtlistener.com/opinion/1985231/', '1985231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that the other two.', 'general', 'People v. Lukity', 'https://www.courtlistener.com/opinion/1985231/', '1985231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '577 NW2d 422 (1998), we held that a court may not reverse a conviction unless it finds that it was “highly probable” that the error in question was not prejudicial.', 'general', 'People v. Lukity', 'https://www.courtlistener.com/opinion/1985231/', '1985231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '25(a) defines “promote” to mean both “distribute” and “disseminate,” we hold that making digital files available to others through peer-to-peer file sharing software like Shareaza is “dissemination” within the meaning of section 43.', 'general', 'Wenger v. State', 'https://www.courtlistener.com/opinion/2172789/', '2172789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence is legally sufficient to support the jury’s verdict.', 'general', 'Wenger v. State', 'https://www.courtlistener.com/opinion/2172789/', '2172789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in admitting the State’s exhibit because the probative value of that evidence was not substantially outweighed by the danger of undue prejudice.', 'general', 'Wenger v. State', 'https://www.courtlistener.com/opinion/2172789/', '2172789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, unless we conclude that it is necessary to correct manifest injustice, we must give due deference to the factfinder’s determinations, “particularly those determinations concerning the weight and credibility of the evidence.', 'general', 'Wenger v. State', 'https://www.courtlistener.com/opinion/2172789/', '2172789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having overruled Appellant’s three points, we affirm the trial court’s judgment.', 'general', 'Wenger v. State', 'https://www.courtlistener.com/opinion/2172789/', '2172789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence is factually sufficient to support the jury’s verdict, and we •overrule Appellant’s first point.', 'general', 'Wenger v. State', 'https://www.courtlistener.com/opinion/2172789/', '2172789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 *505We hold that it may not.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we hold that payments generated by pension benefits that had been previously equitably distributed are not income for purposes of alimony modification.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that annuity payments purchased with the proceeds of an equitable-distribution award also are not “income” for that purpose to the extent that they reflect return of the principal as opposed to income generated by the principal.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '219 (1974), we held that the statute was to be retroactively applied because that interpretation was necessary to make it workable and give it its most sensible interpretation.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed in Gibbons v.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because financial ability of the supporting spouse may be crucial to the proper disposition of a motion for modification, we conclude that a prima fade showing of changed circumstances meets this good cause standard.', 'general', 'Innes v. Innes', 'https://www.courtlistener.com/opinion/1981899/', '1981899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these uncontested facts, we hold that police officials could reasonably believe that Hillemeyer had common authority over the box.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that defendant failed to show that he did not receive an impartial trial.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant’s absence from the McCormack conference did not deny him his constitutional rights to an impartial jury, due process of law, or effective assistance of counsel.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that this issue does not warrant our consideration under the plain error doctrine.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant fails the prejudice prong of the Strickland test.', 'ineffective_assistance', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even assuming that the above evidence was erroneously admitted, we conclude that there is no reasonable probability that the result of the trial would have been different.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court adequately inquired into defendant’s allegations of ineffective assistance.', 'ineffective_assistance', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that mandatory joinder pursuant to N.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lynch we held that trial court’s erroneous dismissal of an indictment was “a judgment of acquittal.', 'dismissal', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gregory, we held that “the preparation of the precise contours and details of the compulsory joinder rule” should be left to “our Criminal Practice Committee for ultimate consideration and promulgation.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the meantime, however, we held that Section 1.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that the subsequent indictment does not violate the double jeopardy clauses of the federal and state constitutions.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that defendant’s prosecution for theft by deception and arson did not violate constitutional- or statutory-double-jeopardy principles.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Dively, we concluded that Vitale did alter the Blockburger test by establishing an additional prong to be met by the defendant seeking to assert a double-jeopardy claim.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In construing Vitale, we concluded that the defendant needed to: (a) meet the elements or Blockburger test;', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Describing Dively’s requirement that both prongs be satisfied as “erroneous,” we concluded that “the more accurate reading of Vitale is that it enhanced the protection afforded a defendant facing a second prosecution on the same facts,” and, therefore, that the second prong is an “alternative” to the first.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In applying the two-prong double-jeopardy analysis of DeLuca we find that defendant fails to satisfy either the “elements” or “evidence” tests.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '83, 106-07 (1989), a case involving multiple punishment, not multiple prosecutions, we concluded that the imposition of multiple punishment violated the double-jeopardy clause because the same evidence was used to prove an element of two different motor vehicle offenses.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '573, 583 (1983), we found that a subsequent prosecution for death-by-auto should have been barred because the sole evidence of the element of recklessness in that prosecution was the evidence of intoxication that provided the basis for the earlier prosecution for drunk driving.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
