INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Iowa Code section 903B.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/8279827/', '8279827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Jorgensen’s counsel did not render ineffective assistance by not making such claims.', 'ineffective_assistance', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/8279827/', '8279827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find Jorgen-sen’s counsel was not ineffective, we affirm.', 'ineffective_assistance', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/8279827/', '8279827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the sentence imposed by the district court.', 'sentencing', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/8279827/', '8279827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the motion judge should grant such motions unless the evidence, when viewed in the light most favorable to the non-moving party, sufficed to permit a rational factfinder to resolve the dispute in favor of the non-moving party.', 'general', 'MacDougall v. Weichert', 'https://www.courtlistener.com/opinion/2089418/', '2089418') ON CONFLICT DO NOTHING;
