INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgments of conviction entered against the appellant on counts 1, 4, and 7, charging her with possession with intent to deliver a controlled substance.', 'general', 'State v. Hardesty', 'https://www.courtlistener.com/opinion/1375288/', '1375288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we reverse the judgments of conviction entered against the appellant on indictment counts 1, 4, and 7, charging her with possession with intent to deliver a controlled substance.', 'general', 'State v. Hardesty', 'https://www.courtlistener.com/opinion/1375288/', '1375288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, we hold that the district court erred when it failed to include the element of physical assault in its jury instructions on the charge of felony fourth-degree assault of a peace officer (transfer of bodily fluids).', 'jury_instruction', 'State of Minnesota v. Thomas Raymond Struzyk', 'https://www.courtlistener.com/opinion/2830949/', '2830949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the.', 'general', 'State of Minnesota v. Thomas Raymond Struzyk', 'https://www.courtlistener.com/opinion/2830949/', '2830949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” While we conclude that Minn.', 'general', 'State of Minnesota v. Thomas Raymond Struzyk', 'https://www.courtlistener.com/opinion/2830949/', '2830949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2231, we conclude that subdivision 1 is not ambiguous.', 'general', 'State of Minnesota v. Thomas Raymond Struzyk', 'https://www.courtlistener.com/opinion/2830949/', '2830949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the district court erred by failing to include the element of “physical assault” in its instructions to the jury, we reverse and remand for proceedings consistent with this opinion.', 'general', 'State of Minnesota v. Thomas Raymond Struzyk', 'https://www.courtlistener.com/opinion/2830949/', '2830949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When a jury instruction given over a party’s objection is determined on appeal to be a prejudicial error, we reverse and remand for a new trial.', 'jury_instruction', 'State of Minnesota v. Thomas Raymond Struzyk', 'https://www.courtlistener.com/opinion/2830949/', '2830949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we disagree, we vacate the decision of the court of appeals, we reverse the district court''s judgment of conviction, and we remand for entry of a judgment of acquittal.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/2174322/', '2174322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We vacate the decision of the court of appeals, we reverse the district court''s judgment of conviction, and we remand for entry of a judgment of acquittal.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/2174322/', '2174322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with our belief, however, that “without claim of right” is integral to the definition of criminal trespass in Minnesota, and adhering to the rule that criminal statutes are to be strictly construed, we hold that “without claim of right” is an element the state must prove beyond a reasonable doubt.', 'general', 'State v. Brechon', 'https://www.courtlistener.com/opinion/2170521/', '2170521') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Addressing the second issue raised, we hold that the jury, not the court, decides the sufficiency of the evidence presented to establish a claim of right.', 'general', 'State v. Brechon', 'https://www.courtlistener.com/opinion/2170521/', '2170521') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Brechon', 'https://www.courtlistener.com/opinion/2170521/', '2170521') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the record in light of the applicable law, we hold that the trial court’s self-defense
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse the Court of Appeals’ decision to vacate defendant’s conviction for assault
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In the Smith case we held that a transcript of a conviction which does not show on its face that counsel was afforded or the right waived cannot be used as proof of the prior conviction in accordance with the rule set forth in Baldasar v.', 'general', 'State v. Gonzales', 'https://www.courtlistener.com/opinion/2170735/', '2170735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the stalking statutes are not void for vagueness under these standards.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/2176094/', '2176094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant’s separate convictions of misdemeanor stalking, a violation of a township ordinance, and felony stalking arose out of two distinct occurrences or episodes, we find that defendant’s subsequent felony stalking conviction did not violate double jeopardy principles.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/2176094/', '2176094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of these standards, we find that the stalking statutes are not unconstitutionally vague.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/2176094/', '2176094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm with respect to the double jeopardy and constitutionality issues, but we vacate the restitution order and remand for an evidentiary hearing to determine the appropriate amount of restitution, pursuant to MCL 780.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/2176094/', '2176094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and sentence but vacate with regard to the order of restitution and remand for a hearing to establish the appropriate amount of restitution, pursuant to MCL 780.', 'sentencing', 'People v. White', 'https://www.courtlistener.com/opinion/2176094/', '2176094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant could be convicted of one count of tampering for the intended victim in addition to five counts of assault — one for each occupant of the house — even though the person he was attempting to silence was not in the house.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/8280438/', '8280438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court of appeals misapplied the rule that a district court may not sentence a defendant to more than one crime for each victim, and that a single sentence for drive-by shooting at an occupied building is not commensurate with Ferguson’s culpability for using a dangerous weapon to intentionally cause eight persons to fear immediate bodily harm.', 'sentencing', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/8280438/', '8280438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, for purposes of the rule that a district court may not sentence a defendant for more than one crime for each victim, a single count of drive-by shooting at an occupied building does not constitute a crime against each building occupant.', 'sentencing', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/8280438/', '8280438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the court of appeals misapplied the multiple-victim rule and because a single sentence for drive-by shooting at an occupied building is not commensurate with Ferguson’s culpability for using a dangerous weapon to intentionally cause eight persons to fear immediate bodily harm, we reverse.', 'sentencing', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/8280438/', '8280438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the decision of the court of appeals and uphold the sentence imposed by the district court, we do not reach Ferguson’s argument that the State may not challenge the length of his 39-month sentence on drive-by shooting because no remand is necessary.', 'sentencing', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/8280438/', '8280438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a host who serves liquor to an adult social guest, knowing both that the guest is intoxicated and will thereafter be operating a motor vehicle, is liable for injuries inflicted on a third party as a result of the negligent operation of a motor vehicle by the adult guest when such negligence is caused by the intoxication.', 'general', 'Kelly v. Gwinnell', 'https://www.courtlistener.com/opinion/1468662/', '1468662') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, this Court holds that a social host who knowingly enables an adult guest to become intoxicated knowing that the guest will operate a motor vehicle is liable for damages to a third party caused by the intoxicated guest.', 'general', 'Kelly v. Gwinnell', 'https://www.courtlistener.com/opinion/1468662/', '1468662') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we hold that a State may not compete with other States for a share of interstate commerce;', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that one intended purpose of AS 12.', 'general', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we held that the police have no duty to advise a suspect of any right to counsel, we did not hold that the police may refuse the specific requests to contact counsel that were made in the instant cases.', 'general', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the videotape evidence of his actions after he requested to speak with his attorney should have been suppressed entirely.', 'suppression', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given those considerations and the absence of a history of excessive force in arrests by police officers, we concluded that the imposition of the exclusionary rule for violations of the forcible arrest statute would at best achieve only a marginal deterrent effect.', 'general', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that when a person is arrested for operating a motor vehicle while intoxicated and asks to consult a lawyer, AS 12.', 'general', 'Copelin v. State', 'https://www.courtlistener.com/opinion/1449697/', '1449697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a private citizen may not use force to resist a search by an authorized police officer engaged in the performance of his duties whether or not the arrest is illegal.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that a private citizen may not use force to resist a peaceful search by one he knows or has good reason to believe is an authorized police officer performing his duties, regardless of whether the search is ultimately determined to be illegal.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 421, 427 (Alaska 1969), we held that a private citizen may not use force to resist a peaceful arrest regardless of whether the arrest is illegal.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 289, 291 (Alaska 1963), we held that testimony regarding a defendant’s silence in the face of an accusatory statement is inadmissible in situations where the defendant’s silence is equally consistent with a state of mind other than acquiescence in the truth of what was said.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sears, we held that the judicial integrity rationale would be implicated only in cases of gross police misconduct.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the rationale of Bargas and Pad-gett applies with equal force to lawful searches.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1201Applying this standard to this ease, we conclude that Elson had no right to resist physically the pat down search by the officer.', 'general', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that where the illegally seized evidence is reliable, where the police conduct involved in obtaining the evidence does not shock the conscience of the court, and where it is clear that the evidence was not obtained for purposes of influencing the sentencing judge, illegally seized evidence may be considered in fashioning a sentence.', 'sentencing', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing these various policy considerations, we conclude that the Court of Appeals, in declining to apply the exclusionary rule in this case, struck a proper balance between the interests of the judicial system in sentencing and the purposes of the exclusionary rule.', 'sentencing', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that where the state30 is able to prove (1) that the illegal evidence is reliable, (2) that the police did not obtain the evidence as a result of gross or shocking misconduct, and (3) that the evidence was not obtained for purposes of influencing the sentencing court, the illegally seized evidence may be considered by the sentencing court in fashioning a defendant’s sentence.', 'sentencing', 'Elson v. State', 'https://www.courtlistener.com/opinion/1449715/', '1449715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 188 (1987), we held that penalty-phase juries, when deciding between life and death, must be instructed about the noncapital sentence for purposeful-or-knowing murder.', 'sentencing', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 19 (1994), we held that guilt-phase juries must be instructed that a failure to agree unanimously that a capital defendant committed murder “by his own conduct,” N.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 175 (1992), in which we held that, where the evidence provides a rational basis for the jury to convict of felony murder, felony murder must be charged to provide the jury with the opportunity to convict of that noncapital alternative form of murder.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 951 (1990), we held that, where a rational basis exists for the jury to convict a capital defendant of passion/provocation manslaughter, which is not death-eligible, instead of death-eligible purposeful-or-knowing murder, the two must be presented simultaneously so that the jury does not consider whether the defendant had an intent to kill without also considering whether passion or provocation actually caused the killing.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brown, supra, we held that the jury could reach a nonunanimous verdict about whether the defendant was a (death-eligible) principal or (non-death-eligible) accomplice in the murder.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the error was prejudicial because “the possibility that the jury, in the absence of sufficient evidence to sustain a first degree murder charge, may have reached a compromise verdict suggests that [defendant] may have suffered prejudice by that instruction in spite of his manslaughter conviction.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 873 (1996), we held that the erroneous submission of the escape-detection factor was harmless because the jury had rejected the factor and had found that the other factor alone outweighed the mitigating evidence.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that it would be speculative to *447assume that the jury’s consideration of one independent aggravating factor affected (via compromise) its consideration of the other independent factor.', 'general', 'State v. Cooper', 'https://www.courtlistener.com/opinion/1541360/', '1541360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of sentence.', 'sentencing', 'Commonwealth v. Rubright', 'https://www.courtlistener.com/opinion/1533062/', '1533062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the most appropriate remedy under the circumstances is to ameliorate the no-parole feature of the penalty.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it would be incongruous and not conducive to substantial justice to limit our consideration of the penalty issue to Hasson and not Bullock.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that it is, we need not express any view regarding how defendant Hasson’s alternative as-applied challenge to the penalty would properly have been dealt with, or whether a remand for sentencing hearings would have been necessary with regard to both Bullock and Hasson, in order to properly address any as-applied challenge.', 'sentencing', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that regardless of whether it is or should be necessary to adduce a "compelling reason” to interpret Const 1963, art 1, § 16 more broadly than the United States Supreme Court interprets the Eighth Amendment, at least three compelling reasons do, in fact, exist to interpret our state constitutional provision more broadly in these cases than the United States Supreme Court interpreted the Eighth Amendment in Harmelin.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that a proper interpretation of Const 1963, art 1, § 16, in accordance with this Court’s longstanding precedent in this area, requires us to strike down the penalty at issue as unjustifiably disproportionate to the crime for which it is imposed, and therefore "cruel or unusual.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated in parts ii(a) and (b), we reverse the judgments of the Court of Appeals and reinstate the convictions of both defendants at bar.', 'general', 'People v. Bullock', 'https://www.courtlistener.com/opinion/1599814/', '1599814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that an automobile was a public place in State v.', 'general', 'State v. Lake', 'https://www.courtlistener.com/opinion/1602070/', '1602070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'that we will explain, we conclude that each of these crimes involved one
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'weapon, we conclude that on the facts of this case it is also a continuing offense,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶25] In sum, we conclude that each of Coffill’s crimes was a continuing
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶30] We conclude that the jury could so find and identify two specific
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that venue was proper in either county.', 'general', 'State of Maine v. Thomas G. Coffill III', 'https://www.courtlistener.com/opinion/10800927/', '10800927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that when a trial judge denies counsel to a needy person by determining that defendant will not be sentenced to a period of imprisonment, the trial judge may not then impose on defendant a conditionally suspended sentence and probation.', 'sentencing', 'State v. DeRosa', 'https://www.courtlistener.com/opinion/2177060/', '2177060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the Vermont Public Defender Act was violated, we must determine the remedy to which defendant is entitled.', 'general', 'State v. DeRosa', 'https://www.courtlistener.com/opinion/2177060/', '2177060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. DeRosa', 'https://www.courtlistener.com/opinion/2177060/', '2177060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the entire court record, briefs of the parties, and applicable law, we AFFIRM the trial court’s judgment.', 'general', 'State v. Gieck', 'https://www.courtlistener.com/opinion/5271972/', '5271972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 765, this court held: “Before accepting a guilty plea a judge is expected to sufficiently examine the defendant to determine whether he understands the nature of the charge, the possible penalty, and the effect of his plea.', 'plea', 'State v. Irish', 'https://www.courtlistener.com/opinion/1640999/', '1640999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the taking of the foregoing steps is sufficient to assure that a plea represents a voluntary and intelligent choice among the alternative courses of action open to a criminal defendant, the ultimate standard by which pleas of guilty or nolo contendere are to be tested.', 'plea', 'State v. Irish', 'https://www.courtlistener.com/opinion/1640999/', '1640999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Irish', 'https://www.courtlistener.com/opinion/1640999/', '1640999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that no defendant may be imprisoned for any offense, whether a traffic infraction, misdemeanor, or felony, absent a knowing and intelligent waiver of his rights as provided for by the Boykin-Turner rule.', 'general', 'State v. Irish', 'https://www.courtlistener.com/opinion/1640999/', '1640999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the defendant had not met his burden of proving discriminatory enforcement.', 'general', 'State v. Russell', 'https://www.courtlistener.com/opinion/1647925/', '1647925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Bettin', 'https://www.courtlistener.com/opinion/2178711/', '2178711') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 652 (1976), we affirmed defendant''s conviction and 30-year sentence for an August 1974 aggravated rape of an 83-year-old woman friend of his parents who lived in a different unit of the same apartment complex for older people in which his parents lived.', 'sentencing', 'State v. Bettin', 'https://www.courtlistener.com/opinion/2178711/', '2178711') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that convictions of both first-degree criminal sexual conduct and the underlying felony of armed robbery or kidnapping in a single trial are not barred by either constitution.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without reference to Block-burger or to legislative intent, we found that the prohibition against double jeopardy had been violated because "[possession of the heroin present in this case was that necessary to its delivery”.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a matter of Michigan constitutional law, we found that multiple punishment under the statutes was impermissible because on the facts of the case before the Court the same facts proved all three crimes.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, in the case before the Court, proof of the charged predicate felony also served as proof of the compound felony of first-degree murder, we found that convictions of both crimes on the facts of the case violated the prohibition against double jeopardy.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in Martin, supra, we held that convictions obtained in one trial of possession of heroin and delivery of the same heroin contravened the constitutional guarantee.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that defendant lacks standing to raise the third party constitutional claims.', 'general', 'People v. Rocha', 'https://www.courtlistener.com/opinion/1757682/', '1757682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the facts warranted separate convictions.', 'general', 'State v. Alvarado', 'https://www.courtlistener.com/opinion/1760729/', '1760729') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and dismiss the conviction of attempted felony murder;', 'dismissal', 'State v. Alvarado', 'https://www.courtlistener.com/opinion/1760729/', '1760729') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we reverse and dismiss the conviction for attempted felony murder.', 'dismissal', 'State v. Alvarado', 'https://www.courtlistener.com/opinion/1760729/', '1760729') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'otherwise, we affirm.', 'general', 'State v. Alvarado', 'https://www.courtlistener.com/opinion/1760729/', '1760729') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that there was other sufficient value testimony by Smith and that the appellant failed to show prejudice, we do not address this issue.', 'general', 'Ross v. State', 'https://www.courtlistener.com/opinion/1775324/', '1775324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm.', 'general', 'Ross v. State', 'https://www.courtlistener.com/opinion/1775324/', '1775324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the consideration during the sentencing phase of a statutorily prescribed aggravating circumstance enacted following the crime required reversal, notwithstanding a failure to bring the issue to the attention of the trial court.', 'sentencing', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 772 (1993), in which we held that when the defendant is allowed to present the possible mitigators and the jury is told it is not limited to the mitigators listed on the form, it is not error to submit the standard form to the jury in lieu of a form proposed by the defendant.', 'general', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 800 (1992), in which this court held that Ark.', 'general', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the capital murder conviction, but we reverse the death sentence and remand for new sentencing.', 'sentencing', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm his convictions for capital murder, but reverse and remand his two sentences of death.', 'sentencing', 'Camargo v. State', 'https://www.courtlistener.com/opinion/1781365/', '1781365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State is correct in this regard and that the proper disposition of the case when evidence has been excluded on appeal due to trial error is a reversal and remand for the possibility of a new trial.', 'general', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand this case.', 'general', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the provisions in the Juvenile Justice Code (JJC), Wis.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that the provisions in Wis.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '357(4)(d), we conclude that those provisions in the JJC violate Article I, § 7 of the Wisconsin Constitution and the Sixth and Fourteenth Amendments to the United States Constitution because they essentially subject a juvenile to the consequences of a "criminal prosecution" without the right to a trial by jury.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the purposes and objectives of the JJC can be fully met even if the provisions in Wis.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '357(4)(d), we conclude that the JJC is not a criminal code.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '357(4)(d) may be severed, and that the remaining provisions in the JJC are non-criminal, we conclude that once those provisions are severed, there clearly is no violation of the juvenile''s state or federal constitu*893tional due process protections.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a reasonable basis exists in this case.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the legislature''s stated objectives in the JJC, and other persuasive authority cited herein, we conclude that the need for early intervention in the JJC is a reasonable basis for requiring that the trier of fact in a juvenile delinquency proceeding be the juvenile court judge.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the juveniles'' rights guaranteed under the equal protection clauses of the Wisconsin and United States Constitutions have not been violated.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the provisions in Wis.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that factor to have been properly considered.', 'general', 'People v. Adams', 'https://www.courtlistener.com/opinion/1827757/', '1827757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decisions of the Court of Appeals.', 'general', 'People v. Adams', 'https://www.courtlistener.com/opinion/1827757/', '1827757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Hryshko', 'https://www.courtlistener.com/opinion/8005331/', '8005331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse, reinstate the charge, and remand.', 'general', 'People v. Stiff', 'https://www.courtlistener.com/opinion/8005592/', '8005592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Schaw', 'https://www.courtlistener.com/opinion/8006253/', '8006253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Trott', 'https://www.courtlistener.com/opinion/2223950/', '2223950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding the defendant’s contentions to be without merit, we affirm.', 'general', 'State v. Trott', 'https://www.courtlistener.com/opinion/2223950/', '2223950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the merits of the asserted claim, we hold that the trial judge’s finding that the defendant was not entrapped is clearly erroneous.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and reinstate the conviction of perjury.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction of attempted delivery of heroin.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that trial courts should provide the following language as a circumstantial evidence charge, in addition to a proper reasonable doubt instruction, when so requested by a defendant:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 587, 607 (1984) ("We hold that an instruction on circumstantial evidence to the effect that a conviction may not be based upon it unless the circumstances point to guilt and exclude to moral certainty every reasonable hypothesis except that of guilt is unnecessary when a correct instruction on reasonable doubt is given.', 'general', 'State v. Logan', 'https://www.courtlistener.com/opinion/8327506/', '8327506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 However, in Cherry, this Court held that the traditional circumstantial evidence charge served to confuse juries by leading them to erroneously believe that the standard for measuring circumstantial evidence is different than that for measuring direct evidence.', 'general', 'State v. Logan', 'https://www.courtlistener.com/opinion/8327506/', '8327506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Appellant’s conviction.', 'general', 'State v. Logan', 'https://www.courtlistener.com/opinion/8327506/', '8327506') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is sufficient to support his controlled-substance convictions.', 'general', 'State v. Porte', 'https://www.courtlistener.com/opinion/8281099/', '8281099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that the district court erred by giving a permissive-inference instruction to the jury.', 'general', 'State v. Porte', 'https://www.courtlistener.com/opinion/8281099/', '8281099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the district court erred by giving the instruction.', 'general', 'State v. Porte', 'https://www.courtlistener.com/opinion/8281099/', '8281099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and remand for a new trial.', 'general', 'State v. Porte', 'https://www.courtlistener.com/opinion/8281099/', '8281099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse and remand for a new trial.', 'general', 'State v. Porte', 'https://www.courtlistener.com/opinion/8281099/', '8281099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Varner, this Court held that “[i]n the absence of a controlling statute, the common law requires that a convicted criminal receive the punishment in effect at the time he is sentenced, unless it is greater than the punishment provided for when the offense was committed.', 'sentencing', 'State v. Dawson', 'https://www.courtlistener.com/opinion/8327334/', '8327334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held the defendant was properly sentenced under the law in effect at the time he committed the murder because the legislature expressly stated the sentencing amendment applied prospectively to all crimes committed on or after the date of its enactment.', 'sentencing', 'State v. Dawson', 'https://www.courtlistener.com/opinion/8327334/', '8327334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Dawson', 'https://www.courtlistener.com/opinion/8327334/', '8327334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the circuit court’s denial of Appellant’s motion to be sentenced under the Act because the Act unambiguously states its sentencing amendments do not apply to criminal prosecutions arising under the amended laws.', 'sentencing', 'State v. Dawson', 'https://www.courtlistener.com/opinion/8327334/', '8327334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the prosecution failed to prove its theory that the unconscious defendant specifically intended to operate the vehicle while intoxicated at some point in the future but the police intervened before he could do so.', 'general', 'People v. Solmonson', 'https://www.courtlistener.com/opinion/8006061/', '8006061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions because they were supported by sufficient evidence and because defendant has failed to establish that his trial counsel was constitutionally deficient.', 'general', 'People v. Solmonson', 'https://www.courtlistener.com/opinion/8006061/', '8006061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and sentences.', 'sentencing', 'People v. Solmonson', 'https://www.courtlistener.com/opinion/8006061/', '8006061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that under the plain language of MCL 333.', 'general', 'Gauthier v. Alpena County Prosecutor', 'https://www.courtlistener.com/opinion/8006139/', '8006139') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we reverse the trial court’s holding that the pipes, bongs, and dugouts were not exempt from the definition of “drug paraphernalia” under MCL 333.', 'general', 'Gauthier v. Alpena County Prosecutor', 'https://www.courtlistener.com/opinion/8006139/', '8006139') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Gauthier v. Alpena County Prosecutor', 'https://www.courtlistener.com/opinion/8006139/', '8006139') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s conclusion that the items in question are drug paraphernalia because these items are specifically designed for the uses listed in MCL 333.', 'general', 'Gauthier v. Alpena County Prosecutor', 'https://www.courtlistener.com/opinion/8006139/', '8006139') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm the declaratory judgment issued by the trial court.', 'general', 'Gauthier v. Alpena County Prosecutor', 'https://www.courtlistener.com/opinion/8006139/', '8006139') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the TMLA creates a re-buttable presumption that a patient’s claims against a physician or health care provider based on facts implicating the defendant’s conduct during the patient’s care, treatment, or confinement are HCLCs.', 'general', 'Loaisiga v. Cerda', 'https://www.courtlistener.com/opinion/5282933/', '5282933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Palacios we held that the TMLA’s language requires a trial court to determine a report’s adequacy from its four corners.', 'general', 'Loaisiga v. Cerda', 'https://www.courtlistener.com/opinion/5282933/', '5282933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a claim against a medical or health care provider for assault is not an HCLC if the record conclusively shows that (1) there is no complaint about any act of the provider related to medical or health care services other than the alleged offensive contact, (2) the alleged offensive contact was not pursuant to actual or implied consent by the plaintiff, and (3) the only possible relationship between the alleged offensive contact and the rendition of medical services or healthca...', 'general', 'Loaisiga v. Cerda', 'https://www.courtlistener.com/opinion/5282933/', '5282933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record does not contain sufficient information to conclusively show that Dr.', 'general', 'Loaisiga v. Cerda', 'https://www.courtlistener.com/opinion/5282933/', '5282933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in formulating an adequate expert report under section 74.', 'general', 'Loaisiga v. Cerda', 'https://www.courtlistener.com/opinion/5282933/', '5282933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if the plaintiffs’ claims assert HCLCs, then the TMLA’s expert report requirements apply to the claims against the P.', 'general', 'Loaisiga v. Cerda', 'https://www.courtlistener.com/opinion/5282933/', '5282933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and remand the case to the trial court for further proceedings.', 'general', 'Loaisiga v. Cerda', 'https://www.courtlistener.com/opinion/5282933/', '5282933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals.', 'general', 'Loaisiga v. Cerda', 'https://www.courtlistener.com/opinion/5282933/', '5282933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that although not expressly articulated by our Supreme Court, the de novo standard of review is proper in reviewing defendants’ challenges that the evidence was insufficient to support their convictions.', 'general', 'People v. Harverson', 'https://www.courtlistener.com/opinion/8006386/', '8006386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Harverson', 'https://www.courtlistener.com/opinion/8006386/', '8006386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court was within its discretion in finding the prior acts admissible.', 'general', 'People v. Meissner', 'https://www.courtlistener.com/opinion/8006543/', '8006543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the lack of objections does not require reversal.', 'general', 'People v. Meissner', 'https://www.courtlistener.com/opinion/8006543/', '8006543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Meissner', 'https://www.courtlistener.com/opinion/8006543/', '8006543') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that state law preempts CADL’s weapons policy because the Legislature, through its statutory scheme in the field of firearm regulation, has completely occupied the field that CADL’s weapons policy attempts to regulate.', 'general', 'Capital Area District Library v. Michigan Open Carry, Inc.', 'https://www.courtlistener.com/opinion/8006709/', '8006709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that the trial court abused its discretion by granting CADL’s request for permanent injunctive relief, i.', 'general', 'Capital Area District Library v. Michigan Open Carry, Inc.', 'https://www.courtlistener.com/opinion/8006709/', '8006709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that, while stated in the negative rather than the affirmative, the state made a clear policy choice to occupy the field of firearm regulation to the exclusion of local units of government:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the Ferndale ordinance was preempted by MCL 123.', 'general', 'Capital Area District Library v. Michigan Open Carry, Inc.', 'https://www.courtlistener.com/opinion/8006709/', '8006709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the library’s weapons policy is permitted by the DLEA.', 'general', 'Capital Area District Library v. Michigan Open Carry, Inc.', 'https://www.courtlistener.com/opinion/8006709/', '8006709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that state law preempts CADL’s weapons policy to the extent that it attempts to regulate *241firearms contrary to the restrictions set forth in MCL 123.', 'general', 'Capital Area District Library v. Michigan Open Carry, Inc.', 'https://www.courtlistener.com/opinion/8006709/', '8006709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because all three factors support a finding of field preemption, and because we are bound by this Court’s field-preemption analysis in Mich Coalition, we reverse the trial court’s rulings upholding and enforcing CADL’s weapons policy to the extent it regulates firearm possession.', 'general', 'Capital Area District Library v. Michigan Open Carry, Inc.', 'https://www.courtlistener.com/opinion/8006709/', '8006709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s judgment upholding CADL’s weapons policy to the extent that it attempts to regulate firearms contrary to the restrictions set forth in MCL 123.', 'general', 'Capital Area District Library v. Michigan Open Carry, Inc.', 'https://www.courtlistener.com/opinion/8006709/', '8006709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that 25 points were properly assessed *488under OV 13 because of the “defendant’s four concurrent convictions .', 'general', 'People v. Gibbs', 'https://www.courtlistener.com/opinion/8006767/', '8006767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if Gibbs’s version of the events were true — that he did not know Henderson was going to rob the store and he was acting under duress by Henderson — then it would have been natural for him to contact the police.', 'general', 'People v. Gibbs', 'https://www.courtlistener.com/opinion/8006767/', '8006767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because requesting an instruction about permission to enter could have confused the jury by suggesting that defendant might have been the perpetrator, we conclude that trial counsel’s failure to request the instruction has not been shown to be unsound strategy or ineffective assistance.', 'ineffective_assistance', 'People v. Dunigan', 'https://www.courtlistener.com/opinion/8006776/', '8006776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it would have been sound trial strategy for counsel to avoid seeking to admit the casino records, so we find no ineffective assistance on that basis.', 'ineffective_assistance', 'People v. Dunigan', 'https://www.courtlistener.com/opinion/8006776/', '8006776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Dunigan', 'https://www.courtlistener.com/opinion/8006776/', '8006776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, because we conclude that Gibson’s testimony regarding his opinions and conclusions did not invade the province of the jury, we also conclude the trial court did not abuse its discretion by admitting Gibson’s testimony.', 'general', 'People v. Fomby', 'https://www.courtlistener.com/opinion/8006789/', '8006789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Fomby', 'https://www.courtlistener.com/opinion/8006789/', '8006789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this Court held that “through the Child Protection Law the Legislature intended to abrogate established immunity rales of the common law related to persons required to report abuse and neglect.', 'general', 'Jones v. Bitner', 'https://www.courtlistener.com/opinion/8006791/', '8006791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We conclude that the mandatory reporting provision of the Child Protection Law (CPL), MCL 722.', 'general', 'Jones v. Bitner', 'https://www.courtlistener.com/opinion/8006791/', '8006791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the mandatory reporting statute does not provide an exception to the general statutory rule of governmental immunity for individual governmental employees.', 'general', 'Jones v. Bitner', 'https://www.courtlistener.com/opinion/8006791/', '8006791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court did not have the opportunity to rule on these issues, we conclude that plaintiff ought to have the opportunity to seek leave to amend the complaint in the trial court.', 'general', 'Jones v. Bitner', 'https://www.courtlistener.com/opinion/8006791/', '8006791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that defendant is entitled to judgment as a matter of law under the governmental immunity statute, we decline to address the remainder of her arguments, including her claim that there was no “reasonable suspicion” to suspect abuse or neglect.', 'general', 'Jones v. Bitner', 'https://www.courtlistener.com/opinion/8006791/', '8006791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hannay, we concluded that while a plaintiff could bring a claim under the motor vehicle exception to governmental immunity, “the fact that a tort action arising from a motor vehicle accident may be pursued against a governmental entity does not except the action from the application of the no-fault act [MCL 500.', 'general', 'Jones v. Bitner', 'https://www.courtlistener.com/opinion/8006791/', '8006791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the order of the trial court and remand for further proceedings in order to afford plaintiff an opportunity to seek leave to amend the complaint.', 'general', 'Jones v. Bitner', 'https://www.courtlistener.com/opinion/8006791/', '8006791') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*202Based on Moll, Goecke, and the dictionary definitions of the term “likely,” we hold that MCL 750.', 'general', 'People v. Nix', 'https://www.courtlistener.com/opinion/8006828/', '8006828') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and sentences.', 'sentencing', 'People v. Nix', 'https://www.courtlistener.com/opinion/8006828/', '8006828') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court did not abuse its discretion in denying Appellant’s motion for continuance.', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/5283736/', '5283736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court did not abuse its discretion in refusing to instruct the jury on lesser-included offenses.', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/5283736/', '5283736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the circuit court did not err in refusing to order Rone to disclose D.', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/5283736/', '5283736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 694 (1986), this court held that, when a defendant’s defense is that he or she is entirely innocent of any crime, then no rational basis exists to instruct the jury on a lesser-included offense because the only issue for the jury is whether the defendant is guilty as charged.', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/5283736/', '5283736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the amendment did not change the nature of the kidnapping charge;', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/5283736/', '5283736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/5283736/', '5283736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm.', 'general', 'People v. Dillard', 'https://www.courtlistener.com/opinion/8006917/', '8006917') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following this rationale, consistent with Electrolines, we conclude that, when a judgment debtor owns property in Michigan, jurisdiction is proper in postjudgment enforcement proceedings without the necessity of demonstrating personal jurisdiction over the debtor.', 'general', 'Arbor Farms, LLC v. Geostar Corp.', 'https://www.courtlistener.com/opinion/8006994/', '8006994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We know of no basis for this unsound rule defendant urges us to adopt and, instead, following Shaffer’s reasoning, we conclude that the presence of a debtor’s property in Michigan provides the trial court with jurisdiction in postjudgment collection proceedings, which proceedings may include discovery and injunctive or other equitable relief related to property in Michigan.', 'general', 'Arbor Farms, LLC v. Geostar Corp.', 'https://www.courtlistener.com/opinion/8006994/', '8006994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such indicia are present in this case.', 'general', 'Arbor Farms, LLC v. Geostar Corp.', 'https://www.courtlistener.com/opinion/8006994/', '8006994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court’s jurisdiction over defendant’s property sufficed in this postjudgment collection action, we need not reach the question of the trial court’s personal jurisdiction over defendant.', 'general', 'Arbor Farms, LLC v. Geostar Corp.', 'https://www.courtlistener.com/opinion/8006994/', '8006994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS HEREBY ORDERED that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court had jurisdiction over defendant’s property in Michigan and did not abuse its discretion by appointing a receiver over defendant’s Michigan property or by holding defendant in contempt for its failure to comply with a court order, we affirm.', 'general', 'Arbor Farms, LLC v. Geostar Corp.', 'https://www.courtlistener.com/opinion/8006994/', '8006994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001) (“To sum up, we hold that attempted *130threats is a valid statutory offense under the laws of the District ■ of Columbia.', 'general', 'RICHARD C. JONES v. UNITED STATES', 'https://www.courtlistener.com/opinion/2959654/', '2959654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the government, we conclude that- the evidence is sufficient to sustain Mr.', 'general', 'RICHARD C. JONES v. UNITED STATES', 'https://www.courtlistener.com/opinion/2959654/', '2959654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'RICHARD C. JONES v. UNITED STATES', 'https://www.courtlistener.com/opinion/2959654/', '2959654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the record contained sufficient evidence that the “appellant acted with intent to commit the crime of cruelty to animals,” and we affirmed her conviction.', 'general', 'RICHARD C. JONES v. UNITED STATES', 'https://www.courtlistener.com/opinion/2959654/', '2959654') ON CONFLICT DO NOTHING;
