INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, based on the testimony and evidence offered at trial, we hold that there was substantial evidence to support the jury’s verdict that Laswell committed aggravated robbery and capital murder.', 'general', 'Laswell v. State', 'https://www.courtlistener.com/opinion/5285301/', '5285301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we hold that the circuit court did not abuse its discretion in admitting crime-scene evidence over Laswell’s chain-of-custody objections.', 'general', 'Laswell v. State', 'https://www.courtlistener.com/opinion/5285301/', '5285301') ON CONFLICT DO NOTHING;
