INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 766 (1998) (where this court held that evidence of the appel- lant’s party behavior, including the use of alcohol and marijuana, his engaging in sexual relations with a teenage girl, and his unauthorized use of his stepfather’s credit card and business checks was admissible because the State contended that | 14at least part of his motive in killing his victims was his desire to engage in a “hedonistic lifestyle”).', 'general', 'Laswell v. State', 'https://www.courtlistener.com/opinion/5285301/', '5285301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Per our normal practice, we conclude that the effective date for reinstatement purposes is the date on which respondent fully complied with the notice and affidavit requirements of D.', 'general', 'In re Silva', 'https://www.courtlistener.com/opinion/5144650/', '5144650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record and the Hearing Committee’s findings concerning his use of alcohol, we conclude that Respondent did not bear his burden of demonstrating by clear and convincing evidence that he was addicted to alcohol.', 'general', 'In re Silva', 'https://www.courtlistener.com/opinion/5144650/', '5144650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that Bar Counsel did not establish that Respondent violated D.', 'general', 'In re Silva', 'https://www.courtlistener.com/opinion/5144650/', '5144650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Bar Counsel has established that Respondent violated that rule in signing the names of the other parties to the purported ERA and affixing the names of fictitious notaries.', 'general', 'In re Silva', 'https://www.courtlistener.com/opinion/5144650/', '5144650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we conclude that the Hearing Committee erred in reaching that conclusion.', 'general', 'In re Silva', 'https://www.courtlistener.com/opinion/5144650/', '5144650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Code § 22-1404 requires that the actor both impersonate a notary and attempt to perform the functions of a notary, we conclude that Bar Counsel did not establish that Respondent violated that section.', 'general', 'In re Silva', 'https://www.courtlistener.com/opinion/5144650/', '5144650') ON CONFLICT DO NOTHING;
