INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the doctrine of ejusdem generis and the last antecedent rule, we find that the pellet/BB gun did not come within the scope of this clause and, consequently, was not a category I weapon as defined by the armed violence statute.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2205799/', '2205799') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the doctrine of ejusdem generis in conjunction with the last antecedent rule, we find that the phrase “any other deadly or dangerous weapon or instrument of like nature” was intended to refer only to weapons or instruments “such like” the class of blade-type weapons which immediately preceded the clause in the provision, i.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2205799/', '2205799') ON CONFLICT DO NOTHING;
