INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in light of the independent corroborating evidence supporting the defendant’s murder conviction and the fact that substantial impeachment evidence was introduced against Tillberry, the alleged withholding of the additional impeachment evidence from Baptista6 did not result in an unfair trial.', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
