INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the defendant''s failure to object to the State''s inquiry into his character or to the introduction of evidence of the three violent incidents precludes this Court from considering those grounds as the foundation for a reversal of his attempted-murder conviction, for which he received a sentence of less than death.', 'sentencing', 'Dunaway v. State', 'https://www.courtlistener.com/opinion/1787212/', '1787212') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After independently weighing the aggravating and mitigating circumstances, we conclude that the appellant''s sentence of death by electrocution is appropriate.', 'sentencing', 'Dunaway v. State', 'https://www.courtlistener.com/opinion/1787212/', '1787212') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the appellant''s conviction and sentence of life imprisonment without the possibility of parole for the murder of Tressa M.', 'sentencing', 'Dunaway v. State', 'https://www.courtlistener.com/opinion/1787212/', '1787212') ON CONFLICT DO NOTHING;
