INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1978), Before we hold that an error- has affected an accused’s substantial right, thus requiring reversal of a conviction, we must conclude that, based on the entire record, a reasonable possibility exists that, in the absence of the error, the verdict might have been more favorable to the accused.', 'general', 'Sam v. State', 'https://www.courtlistener.com/opinion/5345603/', '5345603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because the legislature had specifically made an “attempt to cause serious bodily injury” a crime under § 6-2-502(a)(i), the general attempt statute, Wyo.', 'general', 'Sam v. State', 'https://www.courtlistener.com/opinion/5345603/', '5345603') ON CONFLICT DO NOTHING;
