INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Mr.', 'general', 'Sam v. State', 'https://www.courtlistener.com/opinion/5345603/', '5345603') ON CONFLICT DO NOTHING;
