INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is no evidence of a failure to perceive a substantial and unjustifiable risk that constituted a gross deviation from the standard of care that an ordinary person would have exercised under the circumstances, and, thus, the evidence is legally insufficient to establish criminal negligence.', 'general', 'Queeman v. State', 'https://www.courtlistener.com/opinion/5448450/', '5448450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we held that a jury could have reasonably found that Montgomery’s failure to appreciate that substantial and unjustifiable risk, given the circumstances known to her at the time, was a gross deviation from a standard of care that an ordinary person would exercise under the same circumstances.', 'general', 'Queeman v. State', 'https://www.courtlistener.com/opinion/5448450/', '5448450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this case is distinguishable from Montgomery because, as compared to that case, here there is no evidence that appellant was excessively speeding or undertaking some unreasonable activity that caused his inattention and failure to gauge his distance, and his failures that are shown in this record cannot be characterized as a “gross deviation” from the ordinary standard of care.', 'general', 'Queeman v. State', 'https://www.courtlistener.com/opinion/5448450/', '5448450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s failure to maintain a safe speed and proper distance are acts showing a deviation from the ordinary standard of care expected of drivers on our roads, but, without more, they do not rise to the level of a gross deviation from that standard of care and thus do not constitute criminally negligent homicide.', 'general', 'Queeman v. State', 'https://www.courtlistener.com/opinion/5448450/', '5448450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On discretionary review, we found that the evidence presented in that case was sufficient to uphold Tello’s conviction.', 'general', 'Queeman v. State', 'https://www.courtlistener.com/opinion/5448450/', '5448450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Queeman v. State', 'https://www.courtlistener.com/opinion/5448450/', '5448450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Agreeing with the court of appeals that the evidence is legally insufficient to establish criminally negligent homicide, we affirm the judgment of the court of appeals.', 'general', 'Queeman v. State', 'https://www.courtlistener.com/opinion/5448450/', '5448450') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’s admission that she had agreed to have sex, we hold that there was substantial evidence to support the adjudication.', 'general', 'S.C. v. State', 'https://www.courtlistener.com/opinion/5445653/', '5445653') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We affirm.', 'general', 'S.C. v. State', 'https://www.courtlistener.com/opinion/5445653/', '5445653') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The dissent cites to cases in which this court held that substantial compliance with the statutory requirements for adoption petitions was sufficient.', 'general', 'Beason v. Parks', 'https://www.courtlistener.com/opinion/5445445/', '5445445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and dismiss based on Beason’s second point on appeal.', 'dismissal', 'Beason v. Parks', 'https://www.courtlistener.com/opinion/5445445/', '5445445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Thus, Parks’s petition failed to comply with the mandatory language in section 9-15-201, and we reverse and dismiss on this basis.', 'dismissal', 'Beason v. Parks', 'https://www.courtlistener.com/opinion/5445445/', '5445445') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Beason did not waive the issue of whether Parks’s petition complied with Arkansas Code Annotated section 9-15-201, we reverse and dismiss the circuit court’s order granting Parks’s petition for an order of protection against Beason.', 'dismissal', 'Beason v. Parks', 'https://www.courtlistener.com/opinion/5445445/', '5445445') ON CONFLICT DO NOTHING;
