INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Lincoln R. Pickett v. State of Indiana', 'https://www.courtlistener.com/opinion/4422903/', '4422903') ON CONFLICT DO NOTHING;
