INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that substantial evidence supports Steele’s convictions.', 'general', 'Steele v. State', 'https://www.courtlistener.com/opinion/5444375/', '5444375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the trial court’s imposition of consecutive sentences totaling 164 years’ imprisonment was not cruel and unusual punishment.', 'sentencing', 'Steele v. State', 'https://www.courtlistener.com/opinion/5444375/', '5444375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Steele v. State', 'https://www.courtlistener.com/opinion/5444375/', '5444375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '410 NW2d 266 (1987), in which this Court held that “ ‘[a]ny predictions of a defendant’s future behavior based on a status characteristic such as race, religion, gender, or age are suspect.', 'general', 'People v. Cline', 'https://www.courtlistener.com/opinion/2219814/', '2219814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the trial court improperly considered the defendant’s age in assessing the risk of recidivism.', 'general', 'People v. Cline', 'https://www.courtlistener.com/opinion/2219814/', '2219814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that Linda qualifies as a vulnerable adult under § 145m(u)(iii) because she was “a vulnerable person not less than 18 years of age who is suspected of being or believed to be abused, neglected, or exploited.', 'general', 'People v. Cline', 'https://www.courtlistener.com/opinion/2219814/', '2219814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that defendant is not entitled to resentencing.', 'sentencing', 'People v. Cline', 'https://www.courtlistener.com/opinion/2219814/', '2219814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Cline', 'https://www.courtlistener.com/opinion/2219814/', '2219814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 354 (1995), the court held that “[i]n a case, such as the one at bar, where the defendant was separately charged with the offense of second degree murder, we find that a verdict form which clearly reflects the absence of culpability for any of the charged offenses is especially vital.', 'general', 'People v. Villarreal', 'https://www.courtlistener.com/opinion/2219824/', '2219824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons above stated, we reverse the decision of the appellate court and reinstate defendant’s conviction and sentence for second degree murder.', 'sentencing', 'People v. Villarreal', 'https://www.courtlistener.com/opinion/2219824/', '2219824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Our supreme court then held, "in light of the lesser penalties which attach to marijuana offenses, relative to other controlled substances, we conclude that the application of § 35-48-4-4.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2219337/', '2219337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the penalty for identity deception is not so severe or entirely out of proportion so as to shock public sentiment and violate the judgment of a reasonable people.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2219337/', '2219337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed his convictions for criminal confinement and remanded for judgment of conviction to be entered for the identity deception verdicts and for re-sentencing.', 'sentencing', 'Brown v. State', 'https://www.courtlistener.com/opinion/2219337/', '2219337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm our previous opinion in all other respects.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2219337/', '2219337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in denying Hanna’s motion to suppress evidence because the warrantless search was clearly illegal.', 'suppression', 'Hanna v. State', 'https://www.courtlistener.com/opinion/2222955/', '2222955') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the police did not have probable cause to enter the residence without a warrant, and thus, all evidence obtained from the illegal
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Hanna v. State', 'https://www.courtlistener.com/opinion/2222955/', '2222955') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on the facts of this case, Gilow-had an objectively reasonable basis to justify at least a temporary detention to investigate the cause of Appellant’s unusual driving'', even if Appellant’s “erratic driving” (as the trial court aptly characterized *565it) might ultimately have proven to derive from some other, innocent cause.', 'general', 'Leming v. State', 'https://www.courtlistener.com/opinion/5447022/', '5447022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”29 We concluded that an officer lacks reasonable suspicion that an offense occurred if the officer does not observe both that a driver drives on an improved shoulder unnecessarily and does so unsafely.', 'general', 'Leming v. State', 'https://www.courtlistener.com/opinion/5447022/', '5447022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is sufficient and that the trial court did not err by admitting the challenged exhibits.', 'general', 'Grimm v. State', 'https://www.courtlistener.com/opinion/5447159/', '5447159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is legally sufficient evidence to support every essential element of the offense.', 'general', 'Grimm v. State', 'https://www.courtlistener.com/opinion/5447159/', '5447159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the evidence is sufficient to support the conviction and that the trial court did not err in admitting the challenged exhibits, we affirm the trial court’s judgment.', 'general', 'Grimm v. State', 'https://www.courtlistener.com/opinion/5447159/', '5447159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 774 ("Given that the verdict of a jury may in certain circumstances constitute an affirmative finding being made, we hold that where a charging instrument alleges accused caused death by shooting an individual with a firearm and a trial judge is trier of fact, a recitation in the judgment that offense is "murder with a firearm” coupled with a finding that accused is “guilty of the offense as confessed and set forth above,” approved and confirmed in the sentence, constitutes an affirmati...', 'sentencing', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '21 A year before Hooks, we held that “an appellate court has authority to reform a judgment to include an affirmative finding to make the record speak the truth when the matter has been called to its attention by any source.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We conclude that a remand is necessary because the State’s entitlement to a nunc pro tunc judgment depends on at least one issue of fact—whether, at the time of trial, the trial judge actually made a deadly-weapon finding—and this issue of fact has not been conclusively resolved in the State’s favor.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in Hooks v.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '27 We conclude that Hooks decided, by necessary implication, that a trial judge has the discretion to decline to make a deadly-weapon finding even after finding the defendant guilty of an offense in which ,use of a deadly weapon was a charged or necessary element.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, holding that, because the trial judge did not enter a deadly-weapon finding, the probation statute “will not operate as a bar to probation under the facts of [the defendant’s] cause.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and remand the case to the trial court for proceedings consistent with this opinion.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We held that even if the judge “made” a deadly-weapon finding, the judge’s failure to “enter” the judgment did not render Hook’s probation void.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”8 Therefore, we held that entering a judgment nunc pro tunc to reflect what the factfinder—not necessarily limited to a jury—-determined was proper.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 Although the case did not involve a judgment nunc pro tunc, we held that “[b]y properly admonishing [Huskins] and then accepting his guilty plea to the indictment, the trial court necessarily determined that [Huskins] used a deadly weapon in the commission of the offense,” and the entry of the finding was proper.', 'plea', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the judgment failed to contain the entry of an affirmative finding that was sufficiently specific to deprive the trial judge of his authority to impose regular probation.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Garza, we held that we had decided an issue by necessary implication in Ex parte Maxwell, 424 S.', 'general', 'Guthrie-Nail v. State', 'https://www.courtlistener.com/opinion/5447576/', '5447576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is insufficient evidence to sustain Stacy’s convictions for bribery under any theory alleged by the State, and we sustain her first ground for review.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447648/', '5447648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that it is.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447648/', '5447648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that the language is plain, that it refers specifically to Section 251.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447648/', '5447648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the record, we conclude that there is insufficient evidence to sustain Stacy’s conviction for engaging in organized criminal activity.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447648/', '5447648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is none.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447648/', '5447648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is insufficient evidence to support Stacy’s convictions for bribery, money laundering, and engaging in organized criminal activity, we reverse the judgment of the court of appeals and render acquittals on each count.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447648/', '5447648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court of appeals did not err in holding that appellant failed to prove that her counsel provided ineffective assistance by divulging privileged commu*749nications and affirm the judgment of the court of appeals.', 'ineffective_assistance', 'Bailey v. State', 'https://www.courtlistener.com/opinion/5447647/', '5447647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the assertions made in ground one are encompassed by the other grounds.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/5447647/', '5447647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence is insufficient to prove that David committed bribery as charged because the State failed to negate the political-contribution exception.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447649/', '5447649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We conclude that it did not, and we will affirm the judgment of the court of appeals.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447649/', '5447649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the State’s challenges to the holdings of the court of appeals are without merit, we affirm the judgment of the court of appeals.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447649/', '5447649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, we reversed the judgment of that panel and rendered acquittals on each count because the evidence is insufficient to support her convictions.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447649/', '5447649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reasons that we discussed in that opinion, we affirm the judgment of the court in this case rendering an acquittal on each count.', 'general', 'Cary v. State', 'https://www.courtlistener.com/opinion/5447649/', '5447649') ON CONFLICT DO NOTHING;
