INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 67       We conclude that the legislature’s decision not to include a time limit on former
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is legally sufficient evidence that appellant possessed the culpable mental state of criminal negligence.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the verdict, we conclude the jury could have found that appellant possessed the culpable mental state of criminal negligence when he caused Lopez’s death, and we hold that the evidence is legally sufficient to support the judgment of conviction.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, viewed in the light most favorable to the verdict, the evidence is legally sufficient to support the jury’s finding that appellant used a deadly weapon.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, viewing the evidence in the light most favorable to the verdict, the jury could have found, beyond a reasonable doubt, that appellant’s failure to perceive the risk of death resulting from his actions was “so grievous that the defendant should be held criminally liable.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, viewing the evidence in the light most favorable to the verdict, a reasonable trier of fact- could have found beyond a reasonable doubt that Lopez would not have died but for appellant’s conduct.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*626We conclude that legally sufficient evidence supports the jury’s finding that appellant caused Lopez’s death.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the second inquiry—whether appellant’s truck was capable of causing death or serious bodily injury—we conclude that a rational jury could answer in the affirmative.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having overruled appellant’s issues, we affirm the trial court’s judgment.', 'general', 'Pena v. State', 'https://www.courtlistener.com/opinion/5448572/', '5448572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the search-incident-to-arrest exception to the warrant requirement is a theory of law applicable to the case.', 'general', 'Mixon v. State', 'https://www.courtlistener.com/opinion/5448646/', '5448646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the search-incident-to-arrest issue was a theory of law applicable to the case because (1) appellant was fairly called upon to present evidence on the issue when raised by the State, and he actually did so;', 'general', 'Mixon v. State', 'https://www.courtlistener.com/opinion/5448646/', '5448646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm because appellant does not challenge on appeal a theory of law applicable to the case— whether a search of appellant was conducted incident to a valid arrest.', 'general', 'Mixon v. State', 'https://www.courtlistener.com/opinion/5448646/', '5448646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Mixon v. State', 'https://www.courtlistener.com/opinion/5448646/', '5448646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s reduced sentence of four years’ imprisonment was illegal and therefore’ void.', 'sentencing', 'Lombardo v. State', 'https://www.courtlistener.com/opinion/5448741/', '5448741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the former version of the statute applies.', 'general', 'Lombardo v. State', 'https://www.courtlistener.com/opinion/5448741/', '5448741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in revoking appellant’s probation based on a finding that appellant failed to pay restitution as a condition of community supervision and that her failure was intentional and willful and not because of an inability to pay.', 'general', 'Lombardo v. State', 'https://www.courtlistener.com/opinion/5448741/', '5448741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the reduced sentence is void, we reverse the trial court’s reduced sentence, and remand the case for the trial court tó (1) determine whether to impose a sentence of ten years’ confinement or to exercise its discretion to impose a sentence for a term of less than ten years, but no less than five years, in compliance with article 42A.', 'sentencing', 'Lombardo v. State', 'https://www.courtlistener.com/opinion/5448741/', '5448741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we sustain appellant’s first issue regarding the reduced sentence falling outside the statutory range of punishment, however, we reverse the trial court’s reduced sentence, and remand the case to the trial court for further proceedings in accordance with the instructions set forth above.', 'sentencing', 'Lombardo v. State', 'https://www.courtlistener.com/opinion/5448741/', '5448741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the revocation of appellant’s community supervision, but reverse the trial court’s reduced sentence, and remand the case for the trial court to determine the term of confinement in compliance with article 42A.', 'sentencing', 'Lombardo v. State', 'https://www.courtlistener.com/opinion/5448741/', '5448741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons detailed above, we hold that the circuit court''s findings are not clearly erroneous;', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/1951169/', '1951169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without specifically addressing each contention, we find that Giles cannot possibly establish any prejudice.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/1951169/', '1951169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Giles has failed to offer this Court any argument as to why the circuit court erred in denying relief on these grounds, we find that Giles has forfeited his right to have this Court review these issues.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/1951169/', '1951169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we find that these issues are waived for appellate review.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/1951169/', '1951169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm its judgment.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/1951169/', '1951169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '| ¡¡Accordingly, based on our review of the record and counsel’s brief, we hold that counsel has complied with the requirements of Anders and Arkansas Supreme Court Rule 4—3(k)(1) and that the appeal has no merit.', 'general', 'T.S. v. State', 'https://www.courtlistener.com/opinion/5449466/', '5449466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our review of the record and the brief presented to us, we affirm the adjudication and grant the motion to be relieved as counsel.', 'general', 'T.S. v. State', 'https://www.courtlistener.com/opinion/5449466/', '5449466') ON CONFLICT DO NOTHING;
