INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the above discussion, we conclude that the comments in the present case were mildly inappropriate.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the rule may not always apply in the same fashion to the erroneous exclusion of evidence, we find that the admission of evidence similar to what the appellant wished to offer may, under some circumstances, mitigate against the harm he would have otherwise suffered.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that such comments constitute “other errors” within the purview of Rule 44.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the second factor, we find that no curative action was taken.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we find that the third factor weighs heavily in favor of the State.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that admission of this testimony did not violate Rule 403.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, it is ordered that the newly created instructions set out in OUJI-CIV Nos.', 'general', 'IN RE: AMENDMENTS TO OKLAHOMA UNIFORM JURY INSTRUCTIONS - CIVIL', 'https://www.courtlistener.com/opinion/4258133/', '4258133') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that even if the defendant denies one or more elements of the crime, he is entitled to an entrapment instruction whenever there is sufficient evidence from which a reasonable jury could find entrapment.', 'general', 'Mathews v. United States', 'https://www.courtlistener.com/opinion/112012/', '112012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that a defendant may both deny the acts *66 and other elements necessary to constitute the crime charged and at the same time claim entrapment, the high risks to him make it unlikely as a strategic matter that he will choose to do so.', 'general', 'Mathews v. United States', 'https://www.courtlistener.com/opinion/112012/', '112012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State must also show that the actor was actually aware of the existence of the particular circumstance surrounding that conduct that renders it unlawful.', 'general', 'Delay v. State', 'https://www.courtlistener.com/opinion/5445693/', '5445693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, in Co-lyandro, 233 S.', 'general', 'Delay v. State', 'https://www.courtlistener.com/opinion/5445693/', '5445693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”61 Accordingly, we conclude that the Legislature must have intended to identify only one third-degree felony offense of making a corporate contribution in violation of Sub-chapter D of Chapter 253 of the Election Code, and that, moreover, it must have intended that such an offense be committed knowingly.', 'general', 'Delay v. State', 'https://www.courtlistener.com/opinion/5445693/', '5445693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ']”62 As with the money laundering statute, we conclude that the Legislature intended that conviction should depend upon proof of more than just the bare conduct (“make a political contribution”), which (while it may be subject to state regulation, within First Amendment boundaries) is not intrinsically condemnable.', 'general', 'Delay v. State', 'https://www.courtlistener.com/opinion/5445693/', '5445693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the court of appeals.', 'general', 'Delay v. State', 'https://www.courtlistener.com/opinion/5445693/', '5445693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that proof of psychological injury or trauma satisfies the injury element of section 12— 11(a)(2) of the Criminal Code of 1961.', 'general', 'People v. Hudson', 'https://www.courtlistener.com/opinion/2231842/', '2231842') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this particular form of psychological trauma constitutes a valid basis for departure [from sentencing guidelines] ***.', 'sentencing', 'People v. Hudson', 'https://www.courtlistener.com/opinion/2231842/', '2231842') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the trial court did not err when it allowed evidence of psychological harm and it instructed the jury with IPI Criminal 4th No.', 'general', 'People v. Hudson', 'https://www.courtlistener.com/opinion/2231842/', '2231842') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the judgment of the appellate court as to the issues presented in this appeal.', 'general', 'People v. Hudson', 'https://www.courtlistener.com/opinion/2231842/', '2231842') ON CONFLICT DO NOTHING;
