INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that these circumstances are sufficient under Rule 7(b) of the Arizona Rules of Procedure for Special Actions to justify our acceptance of jurisdiction in this case.', 'general', 'State Ex Rel. Pennartz v. Olcavage', 'https://www.courtlistener.com/opinion/2622650/', '2622650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the phlebotomists in this case are qualified persons within the meaning of section 28-1388(A), we do not address the State’s contention that evidence derived from blood drawn by an unqualified person may still be admissible under the general principles of the Rules of Evidence.', 'general', 'State Ex Rel. Pennartz v. Olcavage', 'https://www.courtlistener.com/opinion/2622650/', '2622650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on the language of the statute and the prior decisions by this court, we conclude that Downey’s testimony was properly excluded as substantive evidence because Castor failed to give the State notice before trial of her intent to use the testimony.', 'general', 'State v. Castor', 'https://www.courtlistener.com/opinion/2234706/', '2234706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in admitting Downey’s testimony only for its impeachment value.', 'general', 'State v. Castor', 'https://www.courtlistener.com/opinion/2234706/', '2234706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence, taken in the light most favorable to the State, is such that a jury could find beyond a reasonable doubt that Brown did not authorize the transactions in question.', 'general', 'State v. Castor', 'https://www.courtlistener.com/opinion/2234706/', '2234706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence regarding the first degree murder charge is sufficient that a jury could find beyond reasonable doubt that Castor is guilty of the charge.', 'general', 'State v. Castor', 'https://www.courtlistener.com/opinion/2234706/', '2234706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Castor’s assignment of error regarding this issue is without merit.', 'general', 'State v. Castor', 'https://www.courtlistener.com/opinion/2234706/', '2234706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Castor', 'https://www.courtlistener.com/opinion/2234706/', '2234706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm the January 6, 2003 post-judgment order denying the motion to withdraw guilty plea in Cr.', 'plea', 'Foo v. State', 'https://www.courtlistener.com/opinion/2623205/', '2623205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the county court judge''s authority was not invoked by § 25-2740.', 'general', 'Mahmood v. Mahmud', 'https://www.courtlistener.com/opinion/1896071/', '1896071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the county court judge in this case properly looked to what Nuzhat was asking for instead of simply the title of the petition.', 'general', 'Mahmood v. Mahmud', 'https://www.courtlistener.com/opinion/1896071/', '1896071') ON CONFLICT DO NOTHING;
