INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse, and remand with directions to vacate the harassment protection order.', 'general', 'Mahmood v. Mahmud', 'https://www.courtlistener.com/opinion/1896071/', '1896071') ON CONFLICT DO NOTHING;
