INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that counsel’s failure to call the character witnesses Schurz suggested at the sentencing hearing does not constitute ineffective assistance of counsel.', 'sentencing', 'State v. Schurz', 'https://www.courtlistener.com/opinion/2613176/', '2613176') ON CONFLICT DO NOTHING;
