INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Schurz’s convictions and sentences.', 'sentencing', 'State v. Schurz', 'https://www.courtlistener.com/opinion/2613176/', '2613176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*705 We hold that such an action for indemnity may not be brought.', 'general', 'Stuart v. Hertz Corp.', 'https://www.courtlistener.com/opinion/1658208/', '1658208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Hertz Corporation, the initial tortfeasor, may not file a third-party complaint seeking indemnity for the alleged aggravation of the injuries by the negligence of the treating physician.', 'general', 'Stuart v. Hertz Corp.', 'https://www.courtlistener.com/opinion/1658208/', '1658208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have reviewed the challenged photographs and, although they are not pleasant to look at, we conclude that the trial court did not err in admitting them at either stage of the proceedings.', 'plea', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1811577/', '1811577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor''s reasons for striking the prospective juror are race neutral.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1811577/', '1811577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we find that the line-up was unnecessarily suggestive, then we must review the ''totality of the circumstances'' (five factors) as set out in Neil v.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1811577/', '1811577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not abuse its discretion in denying the motion for mistrial.', 'mistrial', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1811577/', '1811577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, considering the circumstances and the testimony presented in this case, the prosecutor''s reason for removing the juror was race neutral.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1811577/', '1811577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence of flight was properly admitted.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1811577/', '1811577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State established to a reasonable certainty that none of the items had been altered, substituted, or tampered with.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1811577/', '1811577') ON CONFLICT DO NOTHING;
