INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2238552/', '2238552') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction in all respects.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2238552/', '2238552') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'Conner v. State', 'https://www.courtlistener.com/opinion/1102900/', '1102900') ON CONFLICT DO NOTHING;
