INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From a thorough review and analysis of the record, we conclude that the trial court did not err in imposing the death sentence.', 'sentencing', 'Conner v. State', 'https://www.courtlistener.com/opinion/1102900/', '1102900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rule 608, we find that the trial court did not abuse its discretion by permitting the prosecution to introduce evidence concerning Earnest Stevens'' agreement to take a lie detector test.', 'general', 'Conner v. State', 'https://www.courtlistener.com/opinion/1102900/', '1102900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Instruction D-16 cured any error which may have resulted from the admission of Frank Blair''s written statement into evidence.', 'general', 'Conner v. State', 'https://www.courtlistener.com/opinion/1102900/', '1102900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the impeachment, though improper, was harmless.', 'general', 'Conner v. State', 'https://www.courtlistener.com/opinion/1102900/', '1102900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the crime committed, the manner in which it was committed, and the defendant himself, we find that no prejudice, passion or any other whimsical or capricious factors were contemplated by the trial court.', 'general', 'Conner v. State', 'https://www.courtlistener.com/opinion/1102900/', '1102900') ON CONFLICT DO NOTHING;
