INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the “very narrow exception” created in Adams should not be read in a manner that makes it impossible to recognize any additional public policy exceptions to the at-will doctrine that may warrant recognition.', 'general', 'Carl v. Children''s Hospital', 'https://www.courtlistener.com/opinion/2395626/', '2395626') ON CONFLICT DO NOTHING;
