INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we conclude that Appellant’s convictions arose from separate criminal acts.', 'general', 'Commonwealth v. Kimmel', 'https://www.courtlistener.com/opinion/3150675/', '3150675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we conclude that the charges do not merge, and thus, there was no error in the sentence imposed.', 'sentencing', 'Commonwealth v. Kimmel', 'https://www.courtlistener.com/opinion/3150675/', '3150675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Kimmel', 'https://www.courtlistener.com/opinion/3150675/', '3150675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Kimmel', 'https://www.courtlistener.com/opinion/3150675/', '3150675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jenkins, a panel of this Court held that simple assault did not merge with robbery where the criminal information set forth detailed facts and expressly charged the defendant with as*1280sault arising from a punch that lacerated the victim’s fact and broke his jaw, and a robbery that stemmed from a wholly separate and distinct act of restraining the victim on the ground in order to steal his personal belongings.', 'general', 'Commonwealth v. Kimmel', 'https://www.courtlistener.com/opinion/3150675/', '3150675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recall Jenkins, in which this Court held that the defendant’s convictions arose from distinct criminal acts because separate conduct formed the basis of the charges leveled in the information.', 'general', 'Commonwealth v. Kimmel', 'https://www.courtlistener.com/opinion/3150675/', '3150675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8 In Tamer, a decision that I authored, this Court held that DUI-highest rate of alcohol, 75 Pa.', 'general', 'Commonwealth v. Kimmel', 'https://www.courtlistener.com/opinion/3150675/', '3150675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In so doing, this Court held that DUI (a lesser included offense of DUI-highest rate of alcohol) was a statutory element of both (1) homicide by motor vehicle while DUI, and (2) aggravated assault by vehicle while DUI.', 'general', 'Commonwealth v. Kimmel', 'https://www.courtlistener.com/opinion/3150675/', '3150675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that N.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2528408/', '2528408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred by admitting this prior misconduct evidence, as it consisted only of arrests and charges.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2528408/', '2528408') ON CONFLICT DO NOTHING;
