INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d at 1213 (“When we take into consideration all of the pertinent circumstances here — the underlying events of the evening in question, plus the subsequent actions and statements of Amouak, the nurse, and the doctor — we conclude that these circumstances objectively establish that Amouak and the emergency room personnel shared the primary purpose of obtaining/providing proper medical care for Amouak.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2528408/', '2528408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d at 218 (“We conclude that the victim’s statements to the deputy, both in a hospital emergency room, and later on tape at the sheriffs station, were testimonial .', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2528408/', '2528408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In line with the foregoing, we conclude that N.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2528408/', '2528408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we conclude that the admission of N.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2528408/', '2528408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In line with the foregoing, we conclude that the trial court erred in admitting evidence of Perry’s prior arrests and charges for domestic disturbances involving N.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2528408/', '2528408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand.', 'general', 'Perry v. State', 'https://www.courtlistener.com/opinion/2528408/', '2528408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that conditions must provide some degree of flexibility for their implementation, but cannot provide a probation officer with “open-ended authority.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the State’s approach does not reflect the best reading of 28 V.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record supports imposition of these conditions as properly related to the supervision of defendant.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Condition P is not supported by sufficient evidence of a reasonable relationship between defendant, the crime for which he was convicted, and the condition.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As with the change of residence condition at issue in Moses, we conclude that the changing of one’s employment “is not an incident of daily life,” and we can discern no reason why the sentencing court “cannot anticipate the relevant issues and construct a proper condition.', 'sentencing', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the condition includes an overbroad delegation of authority not supported by findings.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the purposes of defendant’s nexus-based challenge, we conclude that the restrictions on defendant’s liberty occasioned by these conditions are not so severe that they are “unduly restrictive of [his] liberty or autonomy” such that the State must use less restrictive methods to promote its supervisory goals.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that in this case this condition fails at the “nexus” stage, we do not here consider whether the delegation was adequately supported by findings.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, however, because we conclude that the condition is erroneous even on a plain-error standard, we do not address any potential objection to our use of a plain-error standard.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[cjompletion of counseling in a sex offender’s group is reasonably related to the crime of simple assault when the assault was of a sexual nature.', 'general', 'State v. Billy Joe Putnam', 'https://www.courtlistener.com/opinion/3132325/', '3132325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the circuit court had acted correctly in dismissing the complaint based on sovereign immunity, and rejected the plaintiffs argument that sovereign immunity should not apply because her claim was based on a statutory violation.', 'dismissal', 'Fritz v. Johnston', 'https://www.courtlistener.com/opinion/1991443/', '1991443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the claims against Gaffney and Ford are not barred by sovereign immunity.', 'general', 'Fritz v. Johnston', 'https://www.courtlistener.com/opinion/1991443/', '1991443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s judgment in part and reverse in part.', 'general', 'Fritz v. Johnston', 'https://www.courtlistener.com/opinion/1991443/', '1991443') ON CONFLICT DO NOTHING;
