INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[46] Based upon the record, we conclude that evidence of probative value was presented from which the jury could find beyond a reasonable doubt that Luke committed the offenses of invasion of privacy as class D felonies.', 'general', 'Billy Luke v. State of Indiana', 'https://www.courtlistener.com/opinion/3179945/', '3179945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the court did not abuse its discretion in instructing the jury on the definition of harassment.', 'general', 'Billy Luke v. State of Indiana', 'https://www.courtlistener.com/opinion/3179945/', '3179945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the record, we conclude that the court as the finder of fact could reasonably conclude by a preponderance of the evidence that while on probation Luke committed the new offense of invasion of privacy.', 'general', 'Billy Luke v. State of Indiana', 'https://www.courtlistener.com/opinion/3179945/', '3179945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the convictions for stalking and invasion of privacy violate the actual evidence test, they also constitute the "same offense” for the purposes of Ind.', 'general', 'Billy Luke v. State of Indiana', 'https://www.courtlistener.com/opinion/3179945/', '3179945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that there exists a reasonable probability that the jury in Cause No.', 'general', 'Billy Luke v. State of Indiana', 'https://www.courtlistener.com/opinion/3179945/', '3179945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we reverse Luke''s stalking conviction based upon double jeopardy principles, we need not address this argument.', 'general', 'Billy Luke v. State of Indiana', 'https://www.courtlistener.com/opinion/3179945/', '3179945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'Billy Luke v. State of Indiana', 'https://www.courtlistener.com/opinion/3179945/', '3179945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the error was corrected and that there was no harm to the appellant.', 'general', 'Hudson v. State', 'https://www.courtlistener.com/opinion/7695830/', '7695830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we find that appellant has not carried his burden of proving that section 5-54-103(b) unconstitutionally violated his freedom of speech rights, as it is written or as it was applied in this case.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/2457135/', '2457135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that knowledge that a defendant was in a school zone was not required because the underlying act of possession of illegal drugs was already a crime.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1739794/', '1739794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that knowledge that the defendant possessed a knife on school property was required because possession of a knife was not a crime in all circumstances.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1739794/', '1739794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the mens rea standard must relate to the culpable act (failing to stop when there was a duty to stop), not to the consequences of that act (causing property damage or bodily injury).', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1739794/', '1739794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the gross negligence conviction and remanded for a new trial, holding that “the jury, as fact finder, was not given a jury instruction on the lesser-included offense of careless driving and therefore was not in a position to weigh whether Al-Naseer’s conduct constituted gross negligence or ordinary negligence.', 'jury_instruction', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1739794/', '1739794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the reversal of Al-Naseer’s conviction but remand to the district court for reconsideration of the verdict and for amended findings based on this mens rea standard.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1739794/', '1739794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the reversal of Al-Naseer’s conviction but remand to the district court to reconsider its verdict based on the present record and to make amended findings in light of the mens rea standard that requires proof that Al-Na-seer knew that his vehicle was involved in an accident with a person or another vehicle.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1739794/', '1739794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not abuse its discretion by denying defendant’s motion for a new trial based on perjury.', 'general', 'People v. Schrauben', 'https://www.courtlistener.com/opinion/3172858/', '3172858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court’s *198factual finding that Lehman suffered a serious psychological injury was not clearly erroneous and was supported by a preponderance of the evidence.', 'general', 'People v. Schrauben', 'https://www.courtlistener.com/opinion/3172858/', '3172858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and sentences and the trial court’s order granting defendant’s motion for a directed verdict of acquittal.', 'sentencing', 'People v. Schrauben', 'https://www.courtlistener.com/opinion/3172858/', '3172858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court did not err in denying appellant’s motions for directed verdict.', 'general', 'Starling v. State', 'https://www.courtlistener.com/opinion/3172998/', '3172998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court did not abuse its discretion in excluding evidence about P.', 'general', 'Starling v. State', 'https://www.courtlistener.com/opinion/3172998/', '3172998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the circuit court did not err in refusing to instruct the jury on reckless manslaughter, we need not engage in a skip-rule analysis.', 'general', 'Starling v. State', 'https://www.courtlistener.com/opinion/3172998/', '3172998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that, through the testimony and evidence presented at trial, the jury was apprised of the witnesses’ involvement in the crime.', 'general', 'Starling v. State', 'https://www.courtlistener.com/opinion/3172998/', '3172998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the verdict, we conclude that it was reasonable for the jury to infer from the circumstances that appellant committed the offenses of first-degree murder and terroristic act.', 'general', 'Starling v. State', 'https://www.courtlistener.com/opinion/3172998/', '3172998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was no rational basis for giving an instruction for reckless manslaughter, we affirm the circuit court’s ruling.', 'general', 'Starling v. State', 'https://www.courtlistener.com/opinion/3172998/', '3172998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that to prevail under Rule 60(b)(3), the moving party must establish by clear and convincing evidence that the opposing party obtained a judgment by fraud, misrepresentation, or other misconduct, and that this conduct prevented the moving party from fully and fairly preparing or presenting a claim or a defense.', 'general', 'Gerald A. and Teresa L. Phillips v. Joshua D. Stear', 'https://www.courtlistener.com/opinion/3182136/', '3182136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we discuss below, we find that the circuit court abused its discretion and should have granted the motion.', 'general', 'Gerald A. and Teresa L. Phillips v. Joshua D. Stear', 'https://www.courtlistener.com/opinion/3182136/', '3182136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that “criminal intent” as used in the Idaho Tort Claims Act means the intentional commission of what the person knows to be a crime.', 'general', 'Melene James v. City of Boise', 'https://www.courtlistener.com/opinion/3188272/', '3188272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the district court.', 'general', 'Melene James v. City of Boise', 'https://www.courtlistener.com/opinion/3188272/', '3188272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the district court, but on a different ground.', 'general', 'Melene James v. City of Boise', 'https://www.courtlistener.com/opinion/3188272/', '3188272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that qualified immunity supported the dismissal on summary judgment of James’ claim under 42 U.', 'dismissal', 'Melene James v. City of Boise', 'https://www.courtlistener.com/opinion/3188272/', '3188272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Kessler’s expert “is qualified by knowledge and experience to assist the trier of fact with specialized knowledge on this subject.', 'general', 'Melene James v. City of Boise', 'https://www.courtlistener.com/opinion/3188272/', '3188272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 644 (Utah 1986), we held that our Due Process Clause requires
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Redd, we held that a prosecutor’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Redd, we held that the State misread a statute to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8 While we affirm Morgan’s reading that Brickey confined itself
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, although a better practice, a circuit court is not required to conduct a right-to-testify colloquy at the responsibility phase of a bifurcated trial resulting from a plea of not guilty by reason of mental disease or defect.', 'plea', 'State v. James Elvin Lagrone', 'https://www.courtlistener.com/opinion/3196912/', '3196912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Koput we concluded that, given the nature of the responsibility phase, a unanimous jury verdict on the issue of mental responsibility was not required.', 'general', 'State v. James Elvin Lagrone', 'https://www.courtlistener.com/opinion/3196912/', '3196912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals.', 'general', 'State v. James Elvin Lagrone', 'https://www.courtlistener.com/opinion/3196912/', '3196912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the Legislature’s inclusion of the requirement that the person be employed by or associated with an enterprise necessarily requires at least two distinct entities to have been involved to support a conviction under MCL 750.', 'general', 'People v. Kloosterman', 'https://www.courtlistener.com/opinion/8006632/', '8006632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, applying the plain and ordinary meaning of the words in MCL 750.', 'general', 'People v. Kloosterman', 'https://www.courtlistener.com/opinion/8006632/', '8006632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We hold that the prosecution must only show either offense, not both.', 'general', 'People v. Comella', 'https://www.courtlistener.com/opinion/8006633/', '8006633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the requirements for felony murder are satisfied by committing either first-degree vulnerable-adult abuse or second-degree vulnerable-adult abuse.', 'general', 'People v. Comella', 'https://www.courtlistener.com/opinion/8006633/', '8006633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that defendant’s arguments that there was insufficient evidence to prove first-degree vulnerable-adult abuse and that he was deprived of effective assistance of counsel by his counsel’s failing to request an instruction that the prosecutor had to prove first-degree vulnerable-adult abuse is without merit because first-degree vulnerable-adult abuse was not, and need not have been, part of the prosecutor’s theory of the case.', 'general', 'People v. Comella', 'https://www.courtlistener.com/opinion/8006633/', '8006633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'He now appeals, and we affirm.', 'general', 'People v. Comella', 'https://www.courtlistener.com/opinion/8006633/', '8006633') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we conclude that the prosecution has failed to meet its burden to establish that the victim’s legal fees should be included in the restitution amount.', 'general', 'People v. Fawaz', 'https://www.courtlistener.com/opinion/8006740/', '8006740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the prosecution has failed to meet its burden to show that Farmers’ legal and court reporter fees in connection with defendant’s deposition were investigatory under Allen and Gubachy.', 'general', 'People v. Fawaz', 'https://www.courtlistener.com/opinion/8006740/', '8006740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse this portion of the trial court’s restitution order, and direct the trial court to include these costs at resentencing.', 'sentencing', 'People v. Fawaz', 'https://www.courtlistener.com/opinion/8006740/', '8006740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the state’s strong interest in ensuring the safety of its roads and highways outweighs a driver’s diminished privacy interests in avoiding a search following an arrest for DWI.', 'general', 'Rita Ann Stevens v. Commissioner of Public Safety', 'https://www.courtlistener.com/opinion/2683359/', '2683359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the reasons stated above, we conclude that Minnesota’s implied-consent statute does not violate the unconstitutional-conditions doctrine by authorizing the commissioner of public safety to revoke the driver’s license of a person who has been arrested for DWI and has refused to submit to chemical testing.', 'general', 'Rita Ann Stevens v. Commissioner of Public Safety', 'https://www.courtlistener.com/opinion/2683359/', '2683359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Rita Ann Stevens v. Commissioner of Public Safety', 'https://www.courtlistener.com/opinion/2683359/', '2683359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we concluded that any finding of manifest injustice was clearly mistaken, we would remand to the trial court to perform the ministerial act of imposing the adjusted presumptive term.', 'general', 'Heathcock v. State', 'https://www.courtlistener.com/opinion/2604893/', '2604893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we concluded that the trial judge’s finding, that the adjusted presumptive term was manifestly too severe, was not clearly mistaken but that the panel''s decision that it was too lenient was clearly mistaken, we would so hold and remand to the three-judge panel to impose a sentence less than the presumptive term.', 'sentencing', 'Heathcock v. State', 'https://www.courtlistener.com/opinion/2604893/', '2604893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Jurco was not entitled to forcibly resist the troopers even if he reasonably believed that the seizure of his truck was illegal.', 'general', 'Jurco v. State', 'https://www.courtlistener.com/opinion/2618351/', '2618351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, the question presented by Jurco’s case is: which of these two statutes did the legislature intend to take precedence when law enforcement officers attempt to execute a court order calling for the seizure of property? We conclude that a person is not entitled to use force to resist the taking of property by law enforcement officers pursuant to a court order.', 'general', 'Jurco v. State', 'https://www.courtlistener.com/opinion/2618351/', '2618351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that when a person is confronted by a police officer (1) who is known to be or reasonably appears to be a police officer, and (2) who is known to be or reasonably appears to be required or authorized to take possession of the person’s property under a judicial decree, judgement, or order, that person must submit peaceably to the officer’s taking of the property.', 'general', 'Jurco v. State', 'https://www.courtlistener.com/opinion/2618351/', '2618351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we conclude that the trial judge’s mis-allocation of the burden of proof was harmless error, and that Jurco was not entitled to a continuance of the trial.', 'general', 'Jurco v. State', 'https://www.courtlistener.com/opinion/2618351/', '2618351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the affidavit contained enough particularized facts given by a named
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we hold that the search warrant affidavit established
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'despite giving deference to the magistrate in Duarte, this Court held that the officer’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Fifth Court
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Fifth Court of Appeals, vacate the trial court’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, quite apart from the state of mind required to establish the underlying constitutional violation — in that case, a violation of due process, 489 U.', 'general', 'Board of the County Commissioners of Bryan County v. Brown', 'https://www.courtlistener.com/opinion/118104/', '118104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Court of Appeals’ decision cannot be squared with our recognition that, in enacting § 1983, Congress did not intend to impose liability on a municipality unless deliberate action attributable to the municipality itself is the “moving force” behind the plaintiff’s deprivation of federal rights.', 'general', 'Board of the County Commissioners of Bryan County v. Brown', 'https://www.courtlistener.com/opinion/118104/', '118104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In'' light of the statute’s imposition of liability on one who “subjects [a person], or causes [that person] to be subjected,” to a deprivation of federal rights, we concluded that it “cannot be easily read to impose liability vicariously on governing bodies solely on the basis of the existence of an employer-employee relationship with a tortfeasor.', 'general', 'Board of the County Commissioners of Bryan County v. Brown', 'https://www.courtlistener.com/opinion/118104/', '118104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on Owen and Newport, we concluded that a final decisionmaker’s adoption of a course of action “tailored to a particular situation and not intended to control decisions in later situations” may, in some circumstances, give rise to municipal liability under § 1983.', 'general', 'Board of the County Commissioners of Bryan County v. Brown', 'https://www.courtlistener.com/opinion/118104/', '118104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court properly set forth all mitigating factors that it considered.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err by failing to consider the alternative sentences available for a conviction for first degree murder.', 'sentencing', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the first prong of the Rueth analysis has not been met by Pratt.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have compared the nature of the crime and the nature of the defendant in this case with other similar cases12, and we hold that the death penalty in this case is disproportionate.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “Grammer’s death was part of a stream of events which began the evening Fetterly and Windsor entered Grammer’s home and ended the following day when Grammer’s possessions were removed from the home.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, as this Court held in Rhoades, 121 Idaho at 82, 822 P.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 585 (1986), wherein we reversed the district court’s imposition of the death penalty as being disproportionate, are most similar to the present case.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the district court’s judgment of conviction and the sentences imposed, except (1) the conviction and sentence for Count XVI, attempted felony murder, which we vacate, and (2) the death sentence, which we vacate.', 'sentencing', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in light of our prior cases and the Supreme Court decision in White, the testimony of the professional counselor and the pediatrician, attacked as hearsay, properly was received in evidence at the trial.', 'general', 'Betzle v. State', 'https://www.courtlistener.com/opinion/2615047/', '2615047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this instance, we hold that since both the professional counselor and the pediatrician were qualified as experts, and their opinion was of assistance to the trier of fact, the testimony was properly admitted pursuant to Wyo.', 'general', 'Betzle v. State', 'https://www.courtlistener.com/opinion/2615047/', '2615047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), we held that an expert witness may give testimony about what was said to the witness by an abused child under the exception articulated in Wyo.', 'general', 'Betzle v. State', 'https://www.courtlistener.com/opinion/2615047/', '2615047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the conviction and sentence.', 'sentencing', 'Fortner v. State', 'https://www.courtlistener.com/opinion/2613456/', '2613456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'Fortner v. State', 'https://www.courtlistener.com/opinion/2613456/', '2613456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State appeals from this ruling, and, for the reasons that follow, we conclude that (1) while the trial court properly dismissed Count 1 of the indictment, the trial court erred by reaching the constitutional issue relating to OCGA § 16-8-16 (a) (3) in support of this result;', 'dismissal', 'State v. Cohen', 'https://www.courtlistener.com/opinion/5749890/', '5749890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we find that, based on the authority of other courts that have examined similar issues, mere “threats to sue cannot constitute criminal extortion.', 'general', 'State v. Cohen', 'https://www.courtlistener.com/opinion/5749890/', '5749890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that joinder was proper because the charges joined were "2 or more acts or transactions connected together or constituting parts of a common scheme or plan," the charges were "connected together," and the charges constituted parts of a "common scheme or plan.', 'general', 'State v. Luis C. Salinas', 'https://www.courtlistener.com/opinion/3207143/', '3207143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the initial decision to join the intimidation charges with the sexual assault charges was proper because these crimes were "2 or more acts or transactions connected together or constituting parts of a common scheme or plan.', 'general', 'State v. Luis C. Salinas', 'https://www.courtlistener.com/opinion/3207143/', '3207143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions.', 'general', 'State v. Drewry', 'https://www.courtlistener.com/opinion/5143597/', '5143597') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ahmed, where we held that “[i]t was not error, let alone obvious error” for the trial court to admit as excited utterances statements made by a still-crying victim seven minutes after she called 911.', 'general', 'State v. Metzger', 'https://www.courtlistener.com/opinion/5144235/', '5144235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we held that this provision bars admission of testimonial statements of a witness who did not appear at trial unless he was unavailable to testify, and the defendant had had a prior opportunity for cross-examination.', 'general', 'State v. Metzger', 'https://www.courtlistener.com/opinion/5144235/', '5144235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nugent, we held that evidence of a “boyfriend/girlfriend” relationship, without more, did not satisfy the statutory requirement.', 'general', 'State v. Metzger', 'https://www.courtlistener.com/opinion/5144235/', '5144235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the statements were nontesti-monial and thus did not offend the Confrontation Clause, we do not reach this issue.', 'general', 'State v. Metzger', 'https://www.courtlistener.com/opinion/5144235/', '5144235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this issue of first impression, we conclude that the Legislature had the authority to enact this statutory provision and that section 152-A’s provision of the possibility of life imprisonment does not offend those clauses of the Maine Constitution.', 'general', 'State v. Fortune', 'https://www.courtlistener.com/opinion/5144845/', '5144845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and the resulting sentences.', 'sentencing', 'State v. Fortune', 'https://www.courtlistener.com/opinion/5144845/', '5144845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the judgment.', 'general', 'State v. Gurney', 'https://www.courtlistener.com/opinion/5144935/', '5144935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the judgment.', 'general', 'Adoption of L.E.', 'https://www.courtlistener.com/opinion/5145928/', '5145928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction.', 'general', 'State v. Hofland', 'https://www.courtlistener.com/opinion/5146054/', '5146054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the judgment of conviction.', 'general', 'State v. Hofland', 'https://www.courtlistener.com/opinion/5146054/', '5146054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does and therefore affirm the judgment of conviction.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/8208806/', '8208806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 We held that Blakely did not limit a judge’s authority to impose consecutive sentences with the exception of one potential issue that we did not decide in Edmond’s case: Is the fact finding called for by the Neal-Mutschler rule subject to the procedural requirements of Blakely? The Neal-Mutschler rule is a common-law sentencing rule announced by our supreme court;', 'sentencing', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all the above, we conclude that, when a sentencing judge applying the Nealr-Mutschler rule assesses whether a composite term to serve exceeding the maximum term for the defendant’s single most serious crime is necessary to protect the public, the judge is not required to submit this issue to a jury.', 'sentencing', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Thompson properly applied the Nealr-Mutschler rule to impose a composite term that exceeds the maximum 5-year term for Vandergriffs individual crimes.', 'general', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the record, we conclude that Vandergriffs sentence is not clearly mistaken.', 'sentencing', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the superior court imposed the term to protect the public.', 'general', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,17 we affirmed the superior court’s sentence of 1500 days’ imprisonment with 1125 days suspended on eighteen counts of criminal contempt, which had a maximum penalty of 180 days imprisonment.', 'sentencing', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,19 we affirmed the superior court’s imposition of a composite 7-year term, a term that exceeded the 5-year maximum term for each of the five counts of second-degree theft for which Montes had been convicted.', 'general', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In re DLC Corp.', 'https://www.courtlistener.com/opinion/8209531/', '8209531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/4238773/', '4238773') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Jerry Linton v. State of Arkansas', 'https://www.courtlistener.com/opinion/10708737/', '10708737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the circuit court’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was not unfairly prejudiced by the admission of Ely’s testimony because the record reveals that, on balance, Ely’s live testimony actually supported the defense and not the prosecution.', 'general', 'State v. Franklin', 'https://www.courtlistener.com/opinion/8209911/', '8209911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, even if the videotaped statement was inadmissible, we conclude that the admissible evidence supported defendant’s conviction.', 'general', 'State v. Franklin', 'https://www.courtlistener.com/opinion/8209911/', '8209911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At the end of the State’s case, upon reviewing the evidence in the light most favorable to the State, we conclude that the State produced evidence fairly and reasonably tending to show defendant guilty beyond a reasonable doubt.', 'general', 'State v. Franklin', 'https://www.courtlistener.com/opinion/8209911/', '8209911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant appeals, and we affirm.', 'general', 'State v. Franklin', 'https://www.courtlistener.com/opinion/8209911/', '8209911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Since we are persuaded that `we will be in no better position than we are now'' to decide this question, we hold that it is presently ripe for adjudication.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the ordinance violates the U.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the entire ordinance is invalid.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court''s award of attorney fees.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s grant of summary judgment declaring the ordinance in violation of the U.', 'general', 'Boundary Backpackers v. Boundary County', 'https://www.courtlistener.com/opinion/1179651/', '1179651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Julian’s arrest was not unlawful.', 'general', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the district court that Julian was not informed of the cause of his arrest.', 'general', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the district court’s order suppressing evidence seized from Julian following his arrest and remand for further proceedings.', 'suppression', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the verdicts, even if they were inconsistent, should stand as rendered.', 'general', 'Hall v. State', 'https://www.courtlistener.com/opinion/7634785/', '7634785') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm.', 'general', 'State v. Rocheville', 'https://www.courtlistener.com/opinion/1277611/', '1277611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 In Gearinger, we held that when probation is revoked solely for the violation of a special condition, “the revocation court is authorized by section 42-8-34.', 'general', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 We conclude that in this case, unlawful confinement under a sentence longer than that permitted by state statute would constitute a denial of liberty without due process of law.', 'sentencing', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the habeas court incorrectly ruled that the revocation of the full balance of Petitioner’s probation violated the provisions of OCGA § 42-8-34.', 'habeas', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our decision in Gearinger, supra, authorizes a revocation court, when faced with a probationer who has both violated a special condition and committed a felony, to dispose of a probationer as having either violated a special condition or committed a felony.', 'general', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse.', 'general', 'Manville v. Hampton', 'https://www.courtlistener.com/opinion/1296907/', '1296907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the proof in a light most favorable to the prosecution, we find that *438 the evidence presented at trial was sufficient to uphold a finding of guilty upon a charge of trespass.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1153797/', '1153797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the evidence presented at trial is not sufficient to uphold the jury''s verdict, we reverse and remand the case to the trial court for resentencing on the lesser-included offense of willful trespass.', 'sentencing', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1153797/', '1153797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the proffered evidence was inadmissible as an attempt to prove defendant''s diminished capacity.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Accordingly, we hold that the trial court did not err by precluding Dr.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not abuse its discretion in admitting evidence of defendant''s prior acts.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[11]  That rejection, we should note, was not based on any evidentiary offer or formal objection raising the issue on which the majority today decides the case: "We hold that the proffered evidence was inadmissible as an attempt to prove defendant''s diminished capacity.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court erred in excluding the proffered testimony because it was relevant to the defendant''s "mere presence" defense and provided the jury with information essential to the assessment of credibility.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This was dicta, however, as we held that it was not fundamental error for the trial court not to give a proximate cause instruction sua sponte when causation was not at issue in the trial.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Christensen, this court held that to challenge the element of premeditation, a psychology expert could testify that the defendant reacted impulsively to stress.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 297, 303 (1983), this court held that an instruction stating that the defendant would not be subject to the death penalty should not have been given.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that defendant has not waived her claim that the trial court erred by precluding the proffered testimony.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court''s admission of this evidence was not an abuse of discretion.', 'general', 'State v. Mott', 'https://www.courtlistener.com/opinion/1169823/', '1169823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"In our judgment, however, no equal protection question is presented because we hold that the legislature did not intend to exclude drug-related offenses from the operation of the Habitual Felony Offender Act.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We hold that extrinsic evidence is not admissible to prove that a conviction in a foreign jurisdiction would have been a felony in Minnesota if, by definition, that crime could have constituted an offense which is not a felony in this state.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Hines case comes closer to carrying out the intent of our legislature, but we do not address in this opinion how the state can make proof of a "prior conviction.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that Temporary Rule 6(b)(3)(iv) was adopted to further the purposes of the Habitual Offender Act, as intended by the legislature.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Court of Criminal Appeals has authority to remand a case, if it determines justice would requireit, to the trial court for a determination to be made on the defendant''s claim that he was inadequately represented at his trial.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1775734/', '1775734') ON CONFLICT DO NOTHING;
