INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus in Campbell we concluded that AS 11.', 'general', 'Kimoktoak v. State', 'https://www.courtlistener.com/opinion/1160443/', '1160443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that instance, we found that we were unable to redraft the statute in several particulars so as to validate it.', 'general', 'Kimoktoak v. State', 'https://www.courtlistener.com/opinion/1160443/', '1160443') ON CONFLICT DO NOTHING;
