INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our disposition of the issues set forth above, we conclude that the trial court properly refused to bar the University''s claim for Clark''s dishonored draft.', 'general', 'Clark v. University of Evansville', 'https://www.courtlistener.com/opinion/2252690/', '2252690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse the trial court''s judgment in part and remand this case with instructions that the trial court recalculate damages and interest to which the University may be entitled.', 'general', 'Clark v. University of Evansville', 'https://www.courtlistener.com/opinion/2252690/', '2252690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that the trial court properly refused to bar the University''s claim for the dishonored draft but that it erred in declining to apply the corresponding statute of limitations to the University''s claims for punitive damages, we affirm in part, reverse in part, and remand.', 'general', 'Clark v. University of Evansville', 'https://www.courtlistener.com/opinion/2252690/', '2252690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our reading of HRS §§ 291E-11 and 291E-15, read in pari materia, and our interpretation of the legislative intent behind these statutes, we conclude that the Implied Consent Form did not comport with the procedure set forth in HRS §§ 291E-11 and 291E-15 because it did not provide an initial opportunity for Hosaka to refuse to submit to testing before being informed of possible sanctions.', 'general', 'State v. Hosaka', 'https://www.courtlistener.com/opinion/6658875/', '6658875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing Won as controlling precedent, we conclude that Hosaka''s consent given pursuant to the Implied Consent Form was valid.', 'general', 'State v. Hosaka', 'https://www.courtlistener.com/opinion/6658875/', '6658875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the ten-day driver''s license revocation provided for under N.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we conclude that *20 the ten-day driver''s license revocation does not constitute punishment as such, and consequently, defendant''s criminal conviction for DWI did not violate the Double Jeopardy Clause.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2(a), we conclude that the legislature intended to permit a qualified arresting officer to notify defendant of his rights, orally and in writing, regarding a chemical analysis of the breath, and we so construe the statute.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, as with the indecent liberties statute at issue in Hartness, we conclude that the disjunctive phrasing of the instruction was not a fatal ambiguity which resulted in a nonunanimous jury verdict.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons which follow, we affirm defendant''s conviction and sentence.', 'sentencing', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under the Double Jeopardy Clause a defendant who already has been punished in a criminal prosecution may not be subjected to an additional civil sanction to the extent that the second sanction may not fairly be characterized as remedial, but only as a deterrent or retribution.', 'general', 'State v. Oliver', 'https://www.courtlistener.com/opinion/1201686/', '1201686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason we held that it was permissible for the Commonwealth to introduce, in its case-in-chief, medical expert testimony to explain that the absence of physical trauma is not inconsistent with allegations of sexual abuse because there was adequate time for any trauma to heal.', 'general', 'Commonwealth v. Dillon', 'https://www.courtlistener.com/opinion/1925033/', '1925033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the Commonwealth was entitled to address this negative inference in its case-in-chief because the defense may choose not to introduce the results of the physical examination showing the lack of physical trauma, *145 thereby depriving the Commonwealth of the opportunity to address the juror''s potential negative inferences.', 'general', 'Commonwealth v. Dillon', 'https://www.courtlistener.com/opinion/1925033/', '1925033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the Superior Court.', 'general', 'Commonwealth v. Dillon', 'https://www.courtlistener.com/opinion/1925033/', '1925033') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm.', 'general', 'Commonwealth v. Dillon', 'https://www.courtlistener.com/opinion/1925033/', '1925033') ON CONFLICT DO NOTHING;
