INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 401 (1986), the Court reversed a conviction for kidnapping because we found that, of the three purposes for the restraint or removal of the victim which the jury was allowed to consider, one was not supported by the evidence.', 'general', 'State v. Belton', 'https://www.courtlistener.com/opinion/1212648/', '1212648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, where  as here  the asserted error relates not to infringement upon a constitutional right, but to violation of a rule or statute, we hold that the "fundamental error" doctrine is not invoked.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/1217124/', '1217124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that defects in the return of a search warrant are not of a constitutional dimension.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/1217124/', '1217124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, because most of the items seized were in fact related to the marijuana operation, and because none of the other items were used as a basis for charging any other crime, we conclude that the officers did not conduct an indiscriminate search so offensive to fourth amendment values that all evidence need be suppressed.', 'suppression', 'State v. Kelly', 'https://www.courtlistener.com/opinion/1217124/', '1217124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Kelly''s punishment is not grossly disproportionate to his offense, considering the amount of marijuana and paraphernalia seized, nor is it clearly arbitrary and shocking to the sense of justice.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/1217124/', '1217124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have carefully examined Kelly''s remaining assignments of error and we conclude that they also are without merit.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/1217124/', '1217124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/1217124/', '1217124') ON CONFLICT DO NOTHING;
