INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 116 Based on the undisputed facts, we conclude that before the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the warrant application and supporting affidavit provided probable cause to believe that evidence of criminal vehicular operation would be found in Fawcett’s blood and because the warrant satisfies the Particularity Clause in the Fourth Amendment, we affirm.', 'probable_cause', 'State of Minnesota v. Debra Lee Fawcett', 'https://www.courtlistener.com/opinion/4250755/', '4250755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this well-established law to the facts of this case, we conclude that the facts alleged in the warrant application provided the issuing judge a substantial basis to conclude there was a fair probability that evidence of criminal vehicular operation.', 'general', 'State of Minnesota v. Debra Lee Fawcett', 'https://www.courtlistener.com/opinion/4250755/', '4250755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '■ Having considered the circumstances of the case, as well as the nature of the crime under investigation and whether a mófe precise description was possible under the circumstances, we conclude that the authorization to submit Fawcett’s blood sample “to an approved lab for testing” meets minimal constitutional standards for particularity.', 'general', 'State of Minnesota v. Debra Lee Fawcett', 'https://www.courtlistener.com/opinion/4250755/', '4250755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not resolve in this case the exact extent of the expectation of privacy Fawcett retained in'' her blood because, as explained below, we conclude that the warrant provided a valid basis for the controlled substance testing.', 'general', 'State of Minnesota v. Debra Lee Fawcett', 'https://www.courtlistener.com/opinion/4250755/', '4250755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hannuksela, we concluded that although “an authorization permitting search for items belonging to Arthur Nelson [was] somewhat vague,” it “met minimal constitutional standards” because “the officers did not definitely know all of the circumstances surrounding'' Nelson’s disappearance although they were then in possession of sufficient facts to establish .', 'general', 'State of Minnesota v. Debra Lee Fawcett', 'https://www.courtlistener.com/opinion/4250755/', '4250755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the search warrant satisfies the Particularity Clause in the Fourth Amendment.', 'search_seizure', 'State of Minnesota v. Debra Lee Fawcett', 'https://www.courtlistener.com/opinion/4250755/', '4250755') ON CONFLICT DO NOTHING;
