INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we find that the appellant here was so clearly entitled to an instruction and verdict form on unlawful imprisonment, he did not have a fair trial on the kidnapping charge.', 'general', 'State v. Flores', 'https://www.courtlistener.com/opinion/1278717/', '1278717') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the jury could have found the appellant guilty only of unlawful imprisonment, a Class 6 felony carrying a presumptive term of 172 years, rather than kidnapping, a Class 2 felony with a presumptive sentence of 7 years, we find that he was harmed and that reversal is required.', 'sentencing', 'State v. Flores', 'https://www.courtlistener.com/opinion/1278717/', '1278717') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming, arguendo, that the record developed in the Rule 32 proceeding which we consolidated with this appeal, shows no such interview, we find that it was not required.', 'general', 'State v. Flores', 'https://www.courtlistener.com/opinion/1278717/', '1278717') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the trial record we find that the appellant was charged with a violation of his probation.', 'general', 'State v. Flores', 'https://www.courtlistener.com/opinion/1278717/', '1278717') ON CONFLICT DO NOTHING;
