INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ken Swindle v. the Benton County Prosecuting Attorney''s Office', 'https://www.courtlistener.com/opinion/9377262/', '9377262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s order dismissing Swindle’s petition with
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the Superior Court’s decision in Hainesworth, we hold that Appellees are entitled to the benefit of the bargains struck with the Commonwealth when the trial court accepted the parties’ plea agreements.', 'plea', 'Commonwealth, Aplt. v. Shower, W.', 'https://www.courtlistener.com/opinion/4276472/', '4276472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Yet, this Court held that Zuber was entitled to receive the benefit of his bargain—“a prison sentence commensurate with the term contemplated by all of the parties to the plea proceedings,” Zuber, 353 A.', 'sentencing', 'Commonwealth, Aplt. v. Shower, W.', 'https://www.courtlistener.com/opinion/4276472/', '4276472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Commonwealth’s belief in this regard is based upon this Court’s previous decisions where we found that the registration requirements of various versions of Megan’s Law did not constitute punishment but, rather, amounted to collateral consequences of qualifying criminal convictions.', 'general', 'Commonwealth, Aplt. v. Shower, W.', 'https://www.courtlistener.com/opinion/4276472/', '4276472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth, Aplt. v. Shower, W.', 'https://www.courtlistener.com/opinion/4276472/', '4276472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the orders of the Superior Court.', 'general', 'Commonwealth, Aplt. v. Shower, W.', 'https://www.courtlistener.com/opinion/4276472/', '4276472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the facts of this case, the trial court’s lengthy articulation of its reasons for departing from the guidelines, and the minor extent of the departure, we hold that the departure was reasonable.', 'general', 'People v. Ambrose', 'https://www.courtlistener.com/opinion/4315910/', '4315910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, and without declaring the fetus in this case to be a person under the law, we conclude that the trial court did not err by counting the fetus as a victim for purposes of scoring OV 9.', 'general', 'People v. Ambrose', 'https://www.courtlistener.com/opinion/4315910/', '4315910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, and because we conclude that the trial court could properly consider the fetus as a victim without finding the fetus to be a person, we hold, in our *561de novo review of the interpretation and application of the sentencing guidelines, that the trial court did not err by scoring OV 9 at 10 points.', 'sentencing', 'People v. Ambrose', 'https://www.courtlistener.com/opinion/4315910/', '4315910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm.', 'general', 'People v. Ambrose', 'https://www.courtlistener.com/opinion/4315910/', '4315910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without further ado, we hold that the evidence was such that, when viewed under the Harper-Lee-Fairchild standard, Mease was entitled as of right to have the jury instructed regarding the elements of Section 97-3-27 manslaughter.', 'general', 'Mease v. State', 'https://www.courtlistener.com/opinion/1095104/', '1095104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that context we held that the trial court has a duty to reform the tendered instruction or advise defense counsel of the perceived deficiencies and afford a reasonable opportunity to prepare another instruction.', 'general', 'Mease v. State', 'https://www.courtlistener.com/opinion/1095104/', '1095104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Mease v. State', 'https://www.courtlistener.com/opinion/1095104/', '1095104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wilcox, the Court held that embezzled money does not constitute taxable income to the embezzler in the year of the embezzlement under § 22 (a) of the internal Revenue Code of 1939, Six years later, this Court held, in Rutkin v.', 'general', 'James v. United States', 'https://www.courtlistener.com/opinion/106235/', '106235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We reverse.', 'general', 'Russin v. Wesson', 'https://www.courtlistener.com/opinion/1057371/', '1057371') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold on this record, given the protected nature of what Crudup intends to elicit, that the DA''s selective disclosure of the prosecution file, while waiving the privilege as to the documents themselves, does not waive the DA''s testimonial work-product privilege regarding the prosecutor''s mental processes;', 'general', 'In Re Bexar County Criminal District Attorney''s Office', 'https://www.courtlistener.com/opinion/894858/', '894858') ON CONFLICT DO NOTHING;
