INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that section 1385(a) does permit a court acting on its own motion to strike prior felony conviction allegations in cases *530brought under the Three Strikes law.', 'general', 'People v. Superior Court (Romero)', 'https://www.courtlistener.com/opinion/1135929/', '1135929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the transcript is not relevant to the statutory construction and constitutional issues before us and, therefore, deny defendant’s motion as to the transcript.', 'general', 'People v. Superior Court (Romero)', 'https://www.courtlistener.com/opinion/1135929/', '1135929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this issue of first impression, we hold that because Duran was charged with a crime involving a reckless act, rather than an intentional act, the affirmative defense of self-defense is not available to her.', 'general', 'Duran v. State', 'https://www.courtlistener.com/opinion/2615526/', '2615526') ON CONFLICT DO NOTHING;
