INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in the district court''s rulings concerning instructions or testimony presented to the jury, we affirm.', 'general', 'Duran v. State', 'https://www.courtlistener.com/opinion/2615526/', '2615526') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that where a defendant can establish a reasonable probability that the privileged records are likely to contain material information necessary to his defense, an in camera review of those records *650 must be conducted to ascertain whether they contain evidence that is reasonably necessary, and therefore essential, to the defense.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that the trial court abused its discretion when it allowed the improper impeachment of a prosecution witness with hearsay testimony that was highly prejudicial.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the records required under the act are subject to the privilege established by the act.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '340 NW2d 631 (1983), we held that a trial judge abused his discretion when he allowed the defendant''s prior criminal record to be admitted into evidence:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that allowing the police officer to present defendant''s statement purportedly made to his nephew requires reversal of the defendant''s conviction and a new trial.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that, under art 12 of the Massachusetts Declaration of Rights, counsel for the defendant is entitled to review the records of the complainant''s treatment at the New York Hospital and with the Greenwich, Connecticut, social worker to search for evidence of bias, prejudice, or motive to lie.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Stanaway''s conviction and remand for a new trial because the error was not harmless.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Stanaway, we affirm the trial court''s denial of an in camera review of the victim''s counseling records.', 'general', 'People v. Stanaway', 'https://www.courtlistener.com/opinion/1969230/', '1969230') ON CONFLICT DO NOTHING;
