INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶46 We affirm the court of appeals’ determinations that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court did not err in admitting the video in its entirety under Wis.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in light of the greater latitude rule and the fact that the other-acts evidence was so intertwined with the otherwise admissible videotaped statement of the child victim, the circuit court properly determined that each of the three prongs of the Sullivan analysis supported admission.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the first prong, we conclude that the circuit court reasonably concluded that, under Wis.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regarding the second prong, we conclude that the circuit court''s determination — that the hand-burning evidence was relevant to establish M.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the third prong, we conclude that the circuit court reasonably determined that, in accord with Wis.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to our review of the circuit court''s decision, we conclude that the circuit *591court reasonably concluded that the hand-burning evidence was admissible for the purposes of establishing M.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in light of the greater latitude rule, and the fact that the other-acts evidence was so intertwined with the otherwise admissible videotaped statement of the child victim, the circuit court properly determined that each of the three prongs of the Sullivan analysis supported admission.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regarding the second prong, we conclude that the circuit court''s determination that the hand-burning evidence was relevant to the above purposes was reasonable, pursuant to Wis.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, if we conclude that a circuit court erred in admitting other-acts evidence, how that evidence was used at trial becomes relevant to our subsequent analysis of whether that error was harmless.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the circuit court properly exercised its discretion in admitting the other-acts evidence, we do not reach the harmless error analysis in this case.', 'general', 'State v. Marinez', 'https://www.courtlistener.com/opinion/8238396/', '8238396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the record contained sufficient evidence that Ke-kuewa committed the offense of OVUII under HRS § 291E-61(a)(1) and (b)(1) and remanded for entry of judgment of conviction and resentencing for that offense.', 'sentencing', 'State v. Wheeler', 'https://www.courtlistener.com/opinion/2629510/', '2629510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we conclude that the operation of the vehicle on a public way, street, road, or highway is an essential element of the offense of OVUII, and that the oral charge did not adequately allege that element of the offense.', 'general', 'State v. Wheeler', 'https://www.courtlistener.com/opinion/2629510/', '2629510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles here, we conclude that HRS § 291E-1 establishes an attendant circumstance of the offense of OVUII, i.', 'general', 'State v. Wheeler', 'https://www.courtlistener.com/opinion/2629510/', '2629510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While there is a potential ambiguity in the statute with regard to defendants who engage in the conduct of “assuming] actual physical control” of a vehicle, we conclude that the attendant circumstance established in HRS § 291E-1 applies to those defendants as well.', 'general', 'State v. Wheeler', 'https://www.courtlistener.com/opinion/2629510/', '2629510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the oral charge was insufficient.', 'general', 'State v. Wheeler', 'https://www.courtlistener.com/opinion/2629510/', '2629510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the ICA’s judgment.', 'general', 'State v. Wheeler', 'https://www.courtlistener.com/opinion/2629510/', '2629510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the ICA’s April 15, 2009 judgment.', 'general', 'State v. Wheeler', 'https://www.courtlistener.com/opinion/2629510/', '2629510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that de novo review applies in Jamerson''s case.', 'general', 'Jamerson v. Department of Children & Families', 'https://www.courtlistener.com/opinion/8238669/', '8238669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 110, we conclude that a conviction under Wis.', 'general', 'Jamerson v. Department of Children & Families', 'https://www.courtlistener.com/opinion/8238669/', '8238669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '127(2m), we conclude that further factual inquiry is required to determine whether Jamerson''s failure to report "changes in income, assets, or other facts" as required by the federal food stamp law was in fact done with the intent to induce another to act to his or her detriment.', 'general', 'Jamerson v. Department of Children & Families', 'https://www.courtlistener.com/opinion/8238669/', '8238669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that, because there were issues of material fact, Jamerson was entitled to an administrative hearing regarding the revocation of her group childcare license.', 'general', 'Jamerson v. Department of Children & Families', 'https://www.courtlistener.com/opinion/8238669/', '8238669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the Department''s decision and the trial court''s subsequent order, and remand the matter to the Division of Hearings and Appeals ("the Division") for a hearing.', 'general', 'Jamerson v. Department of Children & Families', 'https://www.courtlistener.com/opinion/8238669/', '8238669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court and the Division erred in dismissing Jamerson''s administra*231tive appeal without a hearing, we reverse those orders, and remand the case to the Division to conduct a hearing not inconsistent with this opinion.', 'dismissal', 'Jamerson v. Department of Children & Families', 'https://www.courtlistener.com/opinion/8238669/', '8238669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that due process does not require a sex offender placed on judicial diversion with a probationary period to be informed specifically in conjunction with his plea that his judicial diversion and probation may be revoked if he is discharged from sex offender treatment due to his refusal to acknowledge that he committed the elements of the offense to which he pled.', 'plea', 'State of Tennessee v. Westley A. Albright', 'https://www.courtlistener.com/opinion/4572199/', '4572199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the Defendant is not entitled to relief on the basis that the trial court did not specifically inform him that his refusal to admit to criminal conduct during his sex offender therapy could result in the revocation of his judicial diversion.', 'general', 'State of Tennessee v. Westley A. Albright', 'https://www.courtlistener.com/opinion/4572199/', '4572199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that a trial court placing a sex offender on judicial diversion or probation that includes sex offender treatment as a condition is not required to inform the offender that his or her failure to admit to certain facts or states of mind in therapy may result in the revocation of his or her judicial diversion or probation.', 'general', 'State of Tennessee v. Westley A. Albright', 'https://www.courtlistener.com/opinion/4572199/', '4572199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the courts below.', 'general', 'State of Tennessee v. Westley A. Albright', 'https://www.courtlistener.com/opinion/4572199/', '4572199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment below.', 'general', 'State of Tennessee v. Westley A. Albright', 'https://www.courtlistener.com/opinion/4572199/', '4572199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ''' "11 Thus, we held that home confinement as a condition of pretrial bail is not the equivalent of incarceration:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 783 (2002), this Court held that "[t]he Double Jeopardy and Equal Protection Clauses of the West Virginia Constitution require that time spent in jail before conviction shall be credited against all terms of incarceration to a correctional facility imposed in a criminal case as a punishment upon conviction when the underlying offense is bailable.', 'general', 'State of West Virginia v. Jedediah C.', 'https://www.courtlistener.com/opinion/4477323/', '4477323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that in accordance with Hughes , the circuit court properly refused to grant the Petitioner credit for time served on home incarceration.', 'general', 'State of West Virginia v. Jedediah C.', 'https://www.courtlistener.com/opinion/4477323/', '4477323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"22 We conclude that Petitioner''s sentence should be affirmed.', 'sentencing', 'State of West Virginia v. Jedediah C.', 'https://www.courtlistener.com/opinion/4477323/', '4477323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we concluded that "[t]he absence of substantial restrictions indicates that bail, even with a home confinement restriction, is not the equivalent of incarceration.', 'general', 'State of West Virginia v. Jedediah C.', 'https://www.courtlistener.com/opinion/4477323/', '4477323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the Act applies only to post-conviction situations and is penal in nature.', 'general', 'State of West Virginia v. Jedediah C.', 'https://www.courtlistener.com/opinion/4477323/', '4477323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we hold that public safety officials in quarters where the reasonable expectation of Fourth Amendment privacy is diminished, such as airports and schools, cannot conduct protective searches on the basis of information insufficient to justify searches elsewhere.', 'search_seizure', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the police may act on an anonymous tip of reckless driving, but only under very narrow circumstances.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, based on the totality of the circumstances, we hold that the anonymous tip was sufficiently reliable to justify an investigatory stop.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, when examining the totality of circumstances in this case, we hold that Officer Sagun had a reasonable suspicion, based on specific and articulable facts, that Prendergast was engaged in criminal activity ,14
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that an investigative stop can be justified based on an objectively reasonable suspicion of any offense, provided that the offense for which reasonable suspicion exists is related to the offense articulated by the officer involved.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the circuit court should have suppressed this evidence.', 'suppression', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 580 (1974), in which this court held that a tip from a known informant was insufficient to justify a stop and frisk.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that “[w]ithout an adequate anchor, as to time and place, the reliability of this information becomes greatly attenuated.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the following, we affirm the district court’s ruling on the motion to suppress as well as the district court’s judgment of conviction and sentence.', 'suppression', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we affirm the district court’s denial of Prendergast’s motion to suppress''as well as the district court’s judgment of conviction and sentence.', 'suppression', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
