INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 288 (1979), we held that crimes not expressly provided for in the Code cannot be created by analogy to crimes that are provided for in the Code.', 'general', 'State v. Kaakimaka', 'https://www.courtlistener.com/opinion/1375362/', '1375362') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon analyzing the use of the word “felony” to describe the underlying offense of terroristic threatening, we held that “the specific underlying felony is an essential element of that offense.', 'general', 'State v. Kaakimaka', 'https://www.courtlistener.com/opinion/1375362/', '1375362') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s order, dismissing the charge of conspiracy to commit murder in the second degree against the defendants.', 'dismissal', 'State v. Kaakimaka', 'https://www.courtlistener.com/opinion/1375362/', '1375362') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the circuit court was correct in concluding that the statute of limitations for conspiracy to commit murder is three years, but that it erred in concluding, alternatively, that the statutory scheme failed to give notice of the applicable statute of limitations.', 'general', 'State v. Kaakimaka', 'https://www.courtlistener.com/opinion/1375362/', '1375362') ON CONFLICT DO NOTHING;
