INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the principal issue which Hunter presents for our consideration was not preserved in the trial court, and fashion our review accordingly.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain error standard applies.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient inconsistency between that omission and her testimony at trial to make it permissible to allow the jury to determine its significance.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that because the appellant had "made to the police a general denial of involvement with and knowledge of the crime but [had] made no statement concerning his whereabouts at the time during *153 which the crime was committed," the government "failed to establish a threshold inconsistency between appellant''s prior statement at the police station and his later alibi defense at trial.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Hunter''s conviction.', 'general', 'Hunter v. United States', 'https://www.courtlistener.com/opinion/2383219/', '2383219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, based on the record before us, we conclude that the trial court did not err in finding that the evidence presented at trial was sufficient to sustain appellant’s conviction.', 'general', 'Poole v. United States', 'https://www.courtlistener.com/opinion/2278265/', '2278265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Discerning no error on either ground, we affirm.', 'general', 'Poole v. United States', 'https://www.courtlistener.com/opinion/2278265/', '2278265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is also unnecessary for the government to prove that a defendant knows which particular bank will be victimized by his fraud as long as it is established that a defendant knows that a financial institution will be defrauded.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we find that defendants need not have had the specific intent to defraud Bay Loan so long as they intended to defraud some financial institution.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the publicity relating to this case did not particularly saturate the community with inflammatory sentiment nor do we have any reason to believe that the jury was anything but impartial.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it does not.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record supports the court’s finding that Granoff was not less culpable than most of the other defendants let alone substantially less culpable than an average defendant and we therefore affirm Granoffs sentence.', 'sentencing', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a reasonable jury could also conclude that Land-man’s actions indicated he already-knew that something illegal was going on and was trying to disassociate himself from it.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we found that neither of these elements were required for a conviction under the bank fraud statute, see supra Section IV, the trial court did not err in refusing to give the proffered instructions.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm all of the convictions except for the bank fraud convictions on Counts 24 and 25 against defendant John Ward and the bank fraud convictions on Counts 23 through 26 against defendant Owen Landman, which we reverse.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we see no evidence in the record to support any reasonable finding by the jury that Ward played a role in obtaining the loans in Counts 24 and 25, we reverse his convictions for these two counts.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence is insufficient to prove that Landman executed or aided in the execution of the schemes to defraud Bay Loan charged in Counts 23 through 26, we reverse his conviction on those counts.', 'general', 'United States v. Brandon', 'https://www.courtlistener.com/opinion/7028086/', '7028086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we hold that an individual held for interrogation must be clearly informed that he has the right to consult with a lawyer and to have the lawyer with him during interrogation under the system for protecting the privilege we delineate today.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To summarize, we hold that when an individual is taken into custody or otherwise deprived of his freedom by the authorities in any significant way and is subjected to questioning, the privilege against self-incrimination is jeopardized.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the statements thus made were constitutionally inadmissible.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
