INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this Court held in Rogers v.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was error to fail to charge the offense of solicitation.', 'general', 'State v. Burns', 'https://www.courtlistener.com/opinion/2277242/', '2277242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After exhaustively analyzing the facts and law pertinent to the case, we conclude that the defendant was deprived of the effective assistance of counsel when counsel failed to investigate adequately and present evidence concerning whether Paul Frappolo, and not the defendant, may have been responsible for soliciting Burns’s death.', 'general', 'State v. Burns', 'https://www.courtlistener.com/opinion/2277242/', '2277242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that the trial court’s failure to instruct the lesser-included offense of solicitation to commit a criminal offense was error.', 'general', 'State v. Burns', 'https://www.courtlistener.com/opinion/2277242/', '2277242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our interpretation of its terms, we find that the Model Penal Code approach, as hereinafter modified, is logical and consistent with the structure of our own criminal code.', 'general', 'State v. Burns', 'https://www.courtlistener.com/opinion/2277242/', '2277242') ON CONFLICT DO NOTHING;
