INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm that decision as herein modified.', 'general', 'State v. Burns', 'https://www.courtlistener.com/opinion/2277242/', '2277242') ON CONFLICT DO NOTHING;
