INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/10680152/', '10680152') ON CONFLICT DO NOTHING;
