INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that harmless error has not been demonstrated beyond a reasonable doubt.', 'general', 'Commonwealth v. Wright', 'https://www.courtlistener.com/opinion/2183142/', '2183142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the record shows that there is sufficient circumstantial evidence that demonstrates the authenticity of these documents, we conclude that the Board did not err in admitting the documents into evidence, and relying on them to find that respondent violated his ethical obligation.', 'general', 'In Re Slaughter', 'https://www.courtlistener.com/opinion/2279056/', '2279056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not resolve whether Alfredson''s search of Young''s coat was a frisk or a search, because we conclude that Alfredson had probable cause to believe Young had violated Wis.', 'probable_cause', 'State v. Young', 'https://www.courtlistener.com/opinion/1867862/', '1867862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Young''s evasive action, set against the above-described facts, reinforced reasonable suspicion.', 'general', 'State v. Young', 'https://www.courtlistener.com/opinion/1867862/', '1867862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and Mendenhall tests, we conclude that the two tests can coexist and that the analysis supplied by Hodari D.', 'general', 'State v. Young', 'https://www.courtlistener.com/opinion/1867862/', '1867862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we concluded that the police cruiser''s slow following of the defendant did not convey the message that he was not free to disregard the police and go about his business.', 'general', 'State v. Young', 'https://www.courtlistener.com/opinion/1867862/', '1867862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, the officer lawfully seized Young, and we affirm Young''s convictions on all three counts.', 'general', 'State v. Young', 'https://www.courtlistener.com/opinion/1867862/', '1867862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In re M.G.', 'https://www.courtlistener.com/opinion/10081899/', '10081899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 43   For the foregoing reasons, we affirm the judgment of the circuit court.', 'general', 'In re M.G.', 'https://www.courtlistener.com/opinion/10081899/', '10081899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Trooper Tyler’s war-rantless search of Blank’s breath was constitutional if.', 'general', 'State v. Blank', 'https://www.courtlistener.com/opinion/2634655/', '2634655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence was more than sufficient under Schmerber to support probable cause to search Blank’s breath.', 'probable_cause', 'State v. Blank', 'https://www.courtlistener.com/opinion/2634655/', '2634655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we REVERSE the court of appeals’s decision requiring suppression of the breath test results and REMAND so that the superior court can determine whether exigent circumstances justified the warrantless search.', 'suppression', 'State v. Blank', 'https://www.courtlistener.com/opinion/2634655/', '2634655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, this Court holds that, as a matter of law, the evidence was insufficient to establish the physical
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the State’s evidence established a contemporaneous nexus between the drug felony and the firearm and also satisfied the available and accessible definition of possession as used in the statute.', 'general', 'Barnett v. State', 'https://www.courtlistener.com/opinion/2279580/', '2279580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that “the required evidentiary nexus of physical accessibility between the weapon and [the defendant’s] engaging in the underlying felony of drug trafficking [was] insufficient as a matter of law.', 'general', 'Barnett v. State', 'https://www.courtlistener.com/opinion/2279580/', '2279580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the accessibility and availability definition of possession as used in Section 1447 was satisfied, where weapons were found in close proximity in the same room as the drugs, even though the defendant was
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that a jury must find that a weapon was “physically available and accessible to the defendant.', 'general', 'Barnett v. State', 'https://www.courtlistener.com/opinion/2279580/', '2279580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because no other evidentiary basis for the charges in the complaints exists, we conclude that suppression of the evidence seized from the Nolen residence has a critical impact on the state’s ability to prosecute these cases.', 'suppression', 'State v. McGrath', 'https://www.courtlistener.com/opinion/1875750/', '1875750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After supplying the omissions and correcting the erroneous information contained in the affidavit relating to the informant’s veracity, we conclude that the plastic bags with marijuana residue provided an independent and substantial basis to establish probable cause to issue a search warrant for the Nolen residence.', 'probable_cause', 'State v. McGrath', 'https://www.courtlistener.com/opinion/1875750/', '1875750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the totality of the circumstances, we conclude that there was probable cause to issue the search warrant for the Nolen residence and that the district court erred in suppressing the evidence seized during the search.', 'suppression', 'State v. McGrath', 'https://www.courtlistener.com/opinion/1875750/', '1875750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for further proceedings.', 'general', 'State v. McGrath', 'https://www.courtlistener.com/opinion/1875750/', '1875750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the threat of placing a bomb outside a business where the hearer is present constitutes a true threat.', 'general', 'State v. Button', 'https://www.courtlistener.com/opinion/1349059/', '1349059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that although the speaker’s language did not fall within the unprotected class of obscene language, but were mere threats of physical harm, this language alone was criminally punishable.', 'general', 'State v. Button', 'https://www.courtlistener.com/opinion/1349059/', '1349059') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that the defendant’s threatening statements deserved no constitutional protection even though the defendant
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we hold that the state may not subsequently use that information to prove a crime for which the defendant’s right to counsel had attached at the time the information was elicited.', 'general', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To clarify the record, we hold that appellant was sentenced under A.', 'sentencing', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we hold that this was also timely because appellant could have offered no rebuttal, did not ask for a continuance of the hearing, and was not prejudiced.', 'general', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellant’s conspiracy conviction is not an aggravating circumstance for the murder conviction within the language of A.', 'general', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we find that two aggravating circumstances were proved beyond a reasonable doubt and that the mitigating circumstances are not sufficiently substantial to call for leniency.', 'general', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In fact, we find that the trial court could have excluded it under Rule 402, Rules of Evidence, as irrelevant.', 'general', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 13-4031, and we affirm.', 'general', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In those cases we affirmed the sentence of death.', 'sentencing', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm all the convictions in this case.', 'general', 'State v. Ortiz', 'https://www.courtlistener.com/opinion/1378224/', '1378224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the District Court properly refused the instructions.', 'general', 'State v. Clough', 'https://www.courtlistener.com/opinion/1423777/', '1423777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our original opinion, we concluded that the defendant’s Montana conduct could constitute a felony theft in Arizona.', 'general', 'State v. Clough', 'https://www.courtlistener.com/opinion/1423777/', '1423777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To stretch a point in the state’s favor, even if we look to the meaning of “deprive” in the Montana Code, we find that it entails something less than “deprive” as it is used in the Arizona statute.', 'general', 'State v. Clough', 'https://www.courtlistener.com/opinion/1423777/', '1423777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 263.', 'general', 'New York v. Ferber', 'https://www.courtlistener.com/opinion/110794/', '110794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we hold that § 263.', 'general', 'New York v. Ferber', 'https://www.courtlistener.com/opinion/110794/', '110794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, we hold that child pornography as defined in § 263.', 'general', 'New York v. Ferber', 'https://www.courtlistener.com/opinion/110794/', '110794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Most recently, we held that the Government''s interest in the "well-being of its youth" justified special treatment of indecent broadcasting received by adults as well as children.', 'general', 'New York v. Ferber', 'https://www.courtlistener.com/opinion/110794/', '110794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this element of choice is dispositive, and that if a DUI suspect freely and voluntarily chooses a blood test over a breath test then the arresting officer does not need a warrant to have the suspect''s blood drawn.', 'general', 'People v. Gutierrez', 'https://www.courtlistener.com/opinion/6239959/', '6239959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, because Gutierrez chose between the two types of BAC test (as distinct from choosing whether to take a chemical test at all), we hold that the search in this case is properly characterized as a breath-or-blood test and is justified under the search-incident-to-arrest exception to the warrant requirement.', 'general', 'People v. Gutierrez', 'https://www.courtlistener.com/opinion/6239959/', '6239959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the blood draw in this case requires no warrant under the search-incident-to arrest exception.', 'general', 'People v. Gutierrez', 'https://www.courtlistener.com/opinion/6239959/', '6239959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') As in Birchfield , "[t]he need for BAC testing is great," and weighing this legitimate governmental interest against the intrusion on privacy, we conclude that the Fourth Amendment permits warrantless breath-or-blood testing, based on the same calculus that led the Supreme Court to approve warrantless breath testing.', 'search_seizure', 'People v. Gutierrez', 'https://www.courtlistener.com/opinion/6239959/', '6239959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that to analyze this case - or any case that fits into the broad category of breath-or-blood testing - as if it involved merely a blood test is a category error.', 'general', 'People v. Gutierrez', 'https://www.courtlistener.com/opinion/6239959/', '6239959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2185 ["Because breath tests are significantly less intrusive than blood tests and in most cases amply serve law enforcement interests, we conclude that a breath test, but not a blood test, may be administered as a search incident to a lawful arrest for drunk driving.', 'general', 'People v. Gutierrez', 'https://www.courtlistener.com/opinion/6239959/', '6239959') ON CONFLICT DO NOTHING;
