INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon careful review of the record and the briefs submitted by the parties and having given due consideration to the arguments advanced and the issues raised by the parties, we conclude that Coulter’s contentions are without merit.', 'general', 'Coulter v. State', 'https://www.courtlistener.com/opinion/2584235/', '2584235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the HPA’s minimum term decision was in violation of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree that the HPA violated its guidelines in setting Coulter’s minimum term, we reverse the judgment of the ICA, vacate the circuit court’s order, and remand to the circuit court with instructions to order the HPA to provide Coulter with a new minimum-term hearing under Hawaii Revised Statutes (HRS) § 706-669.', 'general', 'Coulter v. State', 'https://www.courtlistener.com/opinion/2584235/', '2584235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), we held that a person whose vehicle was damaged by the defendant was the “victim” of the charged offense of driving while intoxicated and therefore, under the protections of the Victims’ Bill of Rights, he was entitled to refuse a deposition.', 'general', 'Douglass v. State', 'https://www.courtlistener.com/opinion/2636264/', '2636264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that D.', 'general', 'Douglass v. State', 'https://www.courtlistener.com/opinion/2636264/', '2636264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 12 Accordingly, we conclude that the protected party under a domestic-violence order of protection qualifies as a crime victim under the Victims’ Bill of Rights when the person against whom the order of protection was issued is charged with interference with judicial proceedings by violating the order.', 'general', 'Douglass v. State', 'https://www.courtlistener.com/opinion/2636264/', '2636264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the superior court.', 'general', 'Douglass v. State', 'https://www.courtlistener.com/opinion/2636264/', '2636264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 13 For the foregoing reasons, we affirm the superior court.', 'general', 'Douglass v. State', 'https://www.courtlistener.com/opinion/2636264/', '2636264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, in the context of the other evidence linking Haag to the crime, the witness''s description of the perpetrators as black was not exculpatory: "The fact that [the witness] initially stated that both robbers were black is certainly something that a defense attorney might use to attack [the witness''s] later identification of Haag as one of the robbers.', 'general', 'TEGOSEAK v. State', 'https://www.courtlistener.com/opinion/2636640/', '2636640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that any potential suggestiveness in the photo lineup in Tegoseak''s case was harmless beyond a reasonable doubt, and we therefore affirm Tegoseak''s convictions.', 'general', 'TEGOSEAK v. State', 'https://www.courtlistener.com/opinion/2636640/', '2636640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that the potential suggestiveness of the photo lineup is harmless beyond a reasonable doubt
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellant has failed to show that the statute is unconstitutionally vague as applied to him.', 'general', 'Wagner v. State', 'https://www.courtlistener.com/opinion/6240859/', '6240859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State , we held that the First Amendment affords no protection to communicative conduct whereby one individual invades the substantial privacy interests of another in an essentially intolerable manner.', 'general', 'Wagner v. State', 'https://www.courtlistener.com/opinion/6240859/', '6240859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the application of these rules, we conclude that this statute narrowly applies to a limited group of people under a specified set of circumstances, and it requires evidence that a defendant acted with a culpable mental state in communicating in a harassing manner, such that the communications would persistently disturb, bother continually, or pester another person.', 'general', 'Wagner v. State', 'https://www.courtlistener.com/opinion/6240859/', '6240859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the rules of grammar and usage, we conclude that the requirement of a culpable mental state applies to the entire phrase, "communicates directly with a protected individual or a member of the family or household in a threatening or harassing manner.', 'general', 'Wagner v. State', 'https://www.courtlistener.com/opinion/6240859/', '6240859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"13 We conclude that these terms, viewed in the particular context of this statute, have ordinary meanings that are commonly understood.', 'general', 'Wagner v. State', 'https://www.courtlistener.com/opinion/6240859/', '6240859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the instant statute, we conclude that Section 25.', 'general', 'Wagner v. State', 'https://www.courtlistener.com/opinion/6240859/', '6240859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '23 Under these circumstances, we conclude that the statute does not have a substantial number of unconstitutional applications judged in relation to its plainly legitimate sweep, and thus is not overbroad in violation of the First Amendment.', 'general', 'Wagner v. State', 'https://www.courtlistener.com/opinion/6240859/', '6240859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '07(a)(2)(A) to the facts of this case, we conclude that the statutory language is sufficiently clear to provide a person of ordinary intelligence a reasonable opportunity to know that appellant''s course of conduct would be prohibited.', 'general', 'Wagner v. State', 'https://www.courtlistener.com/opinion/6240859/', '6240859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that child pornography can result from image editing and manipulation.', 'general', 'State v. Bolles', 'https://www.courtlistener.com/opinion/6241064/', '6241064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2003) ("We hold that the statute at issue in Ferber is legally indistinguishable from 18 U.', 'general', 'State v. Bolles', 'https://www.courtlistener.com/opinion/6241064/', '6241064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court of appeals erred in holding that the cropped image was not child pornography because it did not depict a child under the age of 18.', 'general', 'State v. Bolles', 'https://www.courtlistener.com/opinion/6241064/', '6241064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 We find that the court of appeals erred in holding that the evidence was insufficient.', 'general', 'State v. Bolles', 'https://www.courtlistener.com/opinion/6241064/', '6241064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this image constitutes a "lewd exhibition" of her genitals.', 'general', 'State v. Bolles', 'https://www.courtlistener.com/opinion/6241064/', '6241064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and remand the case to the trial court with instructions to reinstate Appellant''s conviction and his sentence.', 'sentencing', 'State v. Bolles', 'https://www.courtlistener.com/opinion/6241064/', '6241064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '80 We reverse the judgment of the court of appeals and remand the case to the trial court with instructions to reinstate the judgment of conviction and the sentence.', 'sentencing', 'State v. Bolles', 'https://www.courtlistener.com/opinion/6241064/', '6241064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence is sufficient to support the Appellant''s conviction on Count 1 because the zoomed-in cropped image depicting a child''s genitals constitutes child pornography as that term is defined in Texas Penal Code sections 43.', 'general', 'State v. Bolles', 'https://www.courtlistener.com/opinion/6241064/', '6241064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '13 In Robinson , we held that this offense is a "circumstances of the conduct" type of offense.', 'general', 'Febus v. State', 'https://www.courtlistener.com/opinion/6241197/', '6241197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, this Court held in Robinson that a culpable mental state applies to the duty to register (which arises under Article 62.', 'general', 'Febus v. State', 'https://www.courtlistener.com/opinion/6241197/', '6241197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"17 In McQueen , this Court held that the culpable mental state applied only to the actor''s knowledge of whether he or she had the consent of the owner-the circumstances surrounding the conduct.', 'general', 'Febus v. State', 'https://www.courtlistener.com/opinion/6241197/', '6241197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in Young that, "[b]ecause Article 62.', 'general', 'Febus v. State', 'https://www.courtlistener.com/opinion/6241197/', '6241197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In fact, this Court held in Young that the gravamen of the offense created by Article 62.', 'general', 'Febus v. State', 'https://www.courtlistener.com/opinion/6241197/', '6241197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '055 punishes what would otherwise be innocent behavior-moving to a new address-under the circumstances that the person is a registered sex offender, we conclude that the statute creates a ''circumstances surrounding the conduct'' offense.', 'general', 'Febus v. State', 'https://www.courtlistener.com/opinion/6241197/', '6241197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '17 We affirmed the court of appeals and upheld the conviction noting that the evidence convincingly established that Robinson had failed to report an intended change of address in person.', 'general', 'Febus v. State', 'https://www.courtlistener.com/opinion/6241197/', '6241197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Appellant''s conviction for failing to comply with his duty to register a prospective change of address.', 'general', 'Febus v. State', 'https://www.courtlistener.com/opinion/6241197/', '6241197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instructed by the Texas Supreme Court''s directive in determining the scope of an express waiver, we conclude that section 551.', 'general', 'City of New Braunfels v. Carowest Land, Ltd.', 'https://www.courtlistener.com/opinion/6241819/', '6241819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the particular circumstances of this case, we conclude that the law-of-the-case doctrine does not preclude us from revisiting our conclusions concerning the trial court''s subject matter jurisdiction over Carowest''s UDJA claims.', 'general', 'City of New Braunfels v. Carowest Land, Ltd.', 'https://www.courtlistener.com/opinion/6241819/', '6241819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instructed by the Texas Supreme Court''s opinions in Patel and Zachry Construction , we conclude that the trial court did not have subject matter jurisdiction over Carowest''s UDJA claims against the City and sustain the City''s first issue.', 'general', 'City of New Braunfels v. Carowest Land, Ltd.', 'https://www.courtlistener.com/opinion/6241819/', '6241819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, because we have concluded that the trial court did not have subject matter jurisdiction over Carowest''s UDJA claims against the City, we conclude that the trial court did not have jurisdiction to proceed solely against Yantis concerning the validity or legality of the North Tributary Contract.', 'general', 'City of New Braunfels v. Carowest Land, Ltd.', 'https://www.courtlistener.com/opinion/6241819/', '6241819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that chapter 271 does not provide a jurisdictional basis for Carowest''s UDJA claims.', 'general', 'City of New Braunfels v. Carowest Land, Ltd.', 'https://www.courtlistener.com/opinion/6241819/', '6241819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Carowest argues that the law-of-the-case doctrine bars a second appeal on the City''s jurisdictional issue because we concluded that the trial court had jurisdiction over Carowest''s UDJA claims in our opinion in Carowest I .', 'general', 'City of New Braunfels v. Carowest Land, Ltd.', 'https://www.courtlistener.com/opinion/6241819/', '6241819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our resolution of that interlocutory appeal, we concluded that the trial court "did not err in concluding that Carowest had standing to bring a claim under chapter 252 and, in turn, denying the City''s plea to the jurisdiction as to Carowest''s declaratory claim regarding the North Tributary Project contract.', 'plea', 'City of New Braunfels v. Carowest Land, Ltd.', 'https://www.courtlistener.com/opinion/6241819/', '6241819') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Cash Biz did not substantially invoke the judicial process.', 'general', 'Henry v. Cash Biz, LP', 'https://www.courtlistener.com/opinion/6242023/', '6242023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Henry v. Cash Biz, LP', 'https://www.courtlistener.com/opinion/6242023/', '6242023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the double jeopardy clause does not bar the prosecution of the charges pending against the defendant.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we are mindful of the requirements of stare decisis that we should not lightly overrule our precedent, in view of all the foregoing considerations, we hold that Tarver falls within that narrow category of cases for which adhering to precedent would not serve the purposes of the doctrine.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More than thirty years ago in Tarver , we held that the doctrine of collateral estoppel bars the State from prosecuting an offense following a trial judge''s finding of "not true" as to the commission of that same offense at an earlier probation revocation hearing.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of all these considerations, this Court held that "the issue of whether [Tarver] committed the particular assault alleged in the information has been found adversely to the State, and the doctrine of collateral estoppel bars relitigating that issue in the county criminal court at law prosecution.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Tarver meets the narrow criteria for overruling our prior precedent, and we now abandon the rule of that decision.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 With respect to the type of collateral estoppel that is embodied in the Fifth Amendment double jeopardy clause, we conclude that federal double jeopardy principles are not implicated by the instant situation, given that a person facing an allegation of a new offense at a probation revocation hearing has not been placed in jeopardy of punishment for that offense.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the applicability of state common law estoppel principles, we conclude that significant legal and policy considerations counsel against application of those principles to this situation.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Now that we have the benefit of more recent precedent declining to apply the concept of federal collateral estoppel in this context, we conclude that no aspect of the Fifth Amendment''s double jeopardy protections apply, including Ashe ''s collateral estoppel rule.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the third consideration addressing whether the parties had a full incentive or opportunity to litigate the issue in the prior proceeding, we conclude that this consideration also weighs against application of collateral estoppel here.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we recognize and agree that these are important interests, we conclude that, on the whole, these considerations are outweighed by the other factors discussed above.', 'general', 'State v. Waters', 'https://www.courtlistener.com/opinion/6243071/', '6243071') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence presented, we hold that the State failed to exclude every other reasonable hypothesis;', 'general', 'Snow v. State', 'https://www.courtlistener.com/opinion/6243681/', '6243681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that substantial evidence supports Snow''s conviction for first-degree endangering the welfare of a minor.', 'general', 'Snow v. State', 'https://www.courtlistener.com/opinion/6243681/', '6243681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and dismiss the battery conviction but affirm the endangering-the-welfare-of-a-child conviction.', 'dismissal', 'Snow v. State', 'https://www.courtlistener.com/opinion/6243681/', '6243681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Mecikalski v. Office of the Attorney General, Division of Criminal Investigation', 'https://www.courtlistener.com/opinion/2636893/', '2636893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Cosgro', 'https://www.courtlistener.com/opinion/5143578/', '5143578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Diecidue, we held that the close nature of the questions required that proof of the violation strictly conform to the violation pled, and that any ambiguities must be resolved in the defendant’s favor, thus requiring that the conviction be vacated.', 'general', 'State v. Cosgro', 'https://www.courtlistener.com/opinion/5143578/', '5143578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we are not going to permit a remand for development of a better record of the actual status and history of this charge, then it is difficult to see, as a matter of stare decisis, how we affirm here after vacating, on essentially the same facts, in Dieddue.', 'general', 'State v. Cosgro', 'https://www.courtlistener.com/opinion/5143578/', '5143578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 108(1-A) (2017), French was not entitled to that instruction, and we affirm the judgment.', 'general', 'State v. French', 'https://www.courtlistener.com/opinion/6483705/', '6483705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence produced at trial permitted a rational jury to find Cheney guilty beyond a reasonable doubt on each of the counts in the indictment and that Cheney’s other arguments do not justify vacating the convictions.', 'general', 'State v. Cheney', 'https://www.courtlistener.com/opinion/5145794/', '5145794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and (3) the significant evidence against the defendant does not suggest that the statement tipped a close case in favor of the State, we conclude that there was no error by the trial court.', 'general', 'State v. Cheney', 'https://www.courtlistener.com/opinion/5145794/', '5145794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Cheney', 'https://www.courtlistener.com/opinion/5145794/', '5145794') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶21] In summary, we conclude that Drost’s statements to Skidgel and DeVeau did not fall within the M.', 'general', 'State v. Guyette', 'https://www.courtlistener.com/opinion/5144939/', '5144939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that there is no constitutional bar to the participation of assistant judges at sentencing.', 'sentencing', 'State v. Hamlin', 'https://www.courtlistener.com/opinion/2292330/', '2292330') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the facts of this case do not fall within the minority guidelines set forth in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Hamlin', 'https://www.courtlistener.com/opinion/2292330/', '2292330') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 62-63, this Court held that “[w]hen determining eligibility for [the AFDC program], all sources of income must be considered unless an exception is specifically authorized by federal law.', 'general', 'People v. Joseph', 'https://www.courtlistener.com/opinion/2000780/', '2000780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking to the plain meaning of the words used in the statute, we conclude that defendant’s settlement check was “income” as contemplated by the Social Welfare Act.', 'general', 'People v. Joseph', 'https://www.courtlistener.com/opinion/2000780/', '2000780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Joseph', 'https://www.courtlistener.com/opinion/2000780/', '2000780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the juvenile court’s ruling denying Casey’s motion to strike and remand the case with instructions to grant the motion and to excise from the record any references designating Casey’s offense as a dangerous crime against children.', 'general', 'In Re Casey G.', 'https://www.courtlistener.com/opinion/2637696/', '2637696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm the juvenile court’s orders of adjudication and disposition.', 'general', 'In Re Casey G.', 'https://www.courtlistener.com/opinion/2637696/', '2637696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'D.P. v. State', 'https://www.courtlistener.com/opinion/5051765/', '5051765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statutory offense reaches and punishes a person who engages in a course of stalking conduct even if the person is operating under the motivation of an obsessed and disturbed love that purportedly obscures appreciation of the terror that his or her conduct would reasonably cause to the victimized person.', 'general', 'State v. Gandhi', 'https://www.courtlistener.com/opinion/1995643/', '1995643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statutory offense reaches and punishes one who engages in a course of stalking conduct even if that person is operating under the motivation of an obsessed and disturbed love that purportedly obscures appreciation of the terror that his or her conduct would reasonably cause
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the verdict sheet’s failure to use the word “repeatedly” with reference to the course of stalking conduct, and its failure to list the elements of harassment, did not constitute reversible error.', 'general', 'State v. Gandhi', 'https://www.courtlistener.com/opinion/1995643/', '1995643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the error on the verdict sheet does not constitute reversible error.', 'general', 'State v. Gandhi', 'https://www.courtlistener.com/opinion/1995643/', '1995643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Where we conclude that the oral instructions of a court were sufficient to convey an understanding of the elements to the jury, and where we also find that the verdict sheet was not misleading, any error in the verdict sheet can be regarded as harmless.', 'general', 'State v. Gandhi', 'https://www.courtlistener.com/opinion/1995643/', '1995643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we encourage completeness and consistency in the preparation of verdict sheets, in the absence of some showing that the jury failed to comprehend its duty, we conclude that the oral instructions were sufficient and that the verdict sheet was not misleading.', 'general', 'State v. Gandhi', 'https://www.courtlistener.com/opinion/1995643/', '1995643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the facts of the case to this analytical framework, we concluded that defendant’s use of surveillance equipment to follow his estranged wife could cause a reasonable person to fear bodily injury and was “the sort
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Legislature intended to cast a wide net of protection for stalking victims by broadly prohibiting and punishing persistent, unwanted, and frightening behaviors.', 'general', 'State v. Gandhi', 'https://www.courtlistener.com/opinion/1995643/', '1995643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We find that assertion, coupled with defendant’s subsequent unpredictable and frighteningly insistent reappearances in proximity to M.', 'general', 'State v. Gandhi', 'https://www.courtlistener.com/opinion/1995643/', '1995643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we disagree with the statutory interpretation urged by defendant, and because we also find no merit to his other assertions, we affirm defendant’s conviction and remand for the resentencing ordered by the Appellate Division.', 'sentencing', 'State v. Gandhi', 'https://www.courtlistener.com/opinion/1995643/', '1995643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '51 We held that the State had no duty to use due care in deciding whether to extend the commitment of a juvenile offender.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '62 In Neakok, we held that a duty of care is owed to victims who are foreseeable, though not necessarily specifically identifiable.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Alvord, where we held that parents who know that their child has a tendency towards violence can be held liable for harm committed by that child only if “the parent had reason to know with some specificity of a present opportunity and need to restrain the child to prevent some imminently foreseeable harm.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts of this case, we conclude that the trial court properly denied summary judgment on the issue of duty.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Our decision in Neakok addressed this question only in the context of whether a parole officer could be held liable for decisions regarding selection of parole conditions because we concluded that no reasonable jury could find the board at fault in that case.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that at least some of the State’s alleged acts of negligence are shielded by discretionary function immunity, we vacate the superior court’s order denying the State’s motion for summary judgment.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse and remand this case to the district court to hold an evidentiary hearing concerning Berkowitz''s arrest.', 'general', 'United States v. Marvin Berkowitz', 'https://www.courtlistener.com/opinion/557342/', '557342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, even assuming that defendant has satisfied the first requirement, we conclude that the privity requirement has not been met.', 'general', 'State v. O''ROURKE', 'https://www.courtlistener.com/opinion/1378297/', '1378297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the requirement of privity cannot be satisfied in the present case, and, therefore, the doctrine of collateral estoppel does not apply to the issue of defendant’s willful refusal to submit to a chemical analysis.', 'general', 'State v. O''ROURKE', 'https://www.courtlistener.com/opinion/1378297/', '1378297') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court.', 'general', 'People v. Hodges', 'https://www.courtlistener.com/opinion/2002975/', '2002975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the appellate court''s judgment affirming the circuit court''s summary dismissal of defendant''s petition for postconviction relief as frivolous and patently without merit.', 'dismissal', 'People v. Hodges', 'https://www.courtlistener.com/opinion/2002975/', '2002975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because police had that corroborating evidence and the informant''s tip linking the defendant to the apartment, we held that the warrant had a sufficient basis.', 'general', 'State v. Boone', 'https://www.courtlistener.com/opinion/8261603/', '8261603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, because there were no facts specifically pointing to that unit, the warrant application failed to establish probable cause.', 'probable_cause', 'State v. Boone', 'https://www.courtlistener.com/opinion/8261603/', '8261603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Appellate Division and vacate Boone''s convictions.', 'general', 'State v. Boone', 'https://www.courtlistener.com/opinion/8261603/', '8261603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Keyes we reversed, holding that a confidential informant''s tip could serve as the basis for issuing a warrant provided that there is "substantial evidence in the record to support the informant''s statements.', 'general', 'State v. Boone', 'https://www.courtlistener.com/opinion/8261603/', '8261603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Pickens v. State', 'https://www.courtlistener.com/opinion/2224438/', '2224438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the search warrant affidavit, by three factual allegations, established a sufficient nexus between Yarbrough’s drug activities *624and the apartment.', 'general', 'State v. Yarbrough', 'https://www.courtlistener.com/opinion/8281286/', '8281286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Gail, we held that it was reasonable to infer that a murder weapon would be found in the apartment where the defendant was arrested.', 'general', 'State v. Yarbrough', 'https://www.courtlistener.com/opinion/8281286/', '8281286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it did, we conclude that the issuing judge had a substantial basis to find probable cause that handgun and drug evidence would be found at Yarbrough’s residence.', 'probable_cause', 'State v. Yarbrough', 'https://www.courtlistener.com/opinion/8281286/', '8281286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the search warrant affidavit established a sufficient nexus between Yarbrough’s criminal activity and his residence for both gun evidence and drug evidence, we need not and do not address the court of appeals’ reliance on the plain view doctrine with respect to drug evidence.', 'general', 'State v. Yarbrough', 'https://www.courtlistener.com/opinion/8281286/', '8281286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Yarbrough', 'https://www.courtlistener.com/opinion/8281286/', '8281286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Minn.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/8281304/', '8281304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that, to obtain a conviction under Minn.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/8281304/', '8281304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '375 (2012) (“the care-and-support statute”) required the State to prove that Nelson omitted and failed to provide both care and support to his children, we reverse Nelson’s conviction.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/8281304/', '8281304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the decision of the court of appeals.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/8281304/', '8281304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the amendment created an expanded remedy, rather than a new liability, because the preexisting statute reflected a defendant’s responsibility for the child’s “support from birth.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/8281304/', '8281304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed in part and remanded, holding that the father was absolved from making the monthly child support payments because the mother had violated the divorce decree by moving with their two children to Cairo, Egypt, without the father’s consent.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/8281304/', '8281304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the record, we conclude that, although the terms and conditions of the extended OFP are broad, they are no broader than necessary.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the provisions of the extended OFP that restrict Bergstrom’s contact with Rew satisfy Madsen because the incidental restrictions on Bergstrom’s speech are no greater than necessary to satisfy the State’s significant interest in protecting Rew from domestic abuse.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the district court did not violate Bergstrom’s procedural due process rights when it granted the extended OFP to Rew.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these four reasqns, we conclude that the Legislature has indicated that an extended OFP is a civil remedy.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1140 (citation omitted) (internal quotation marks omitted), we conclude that an extended OFP is a civil remedy.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because we can discern no principled reason, textual or otherwise, to treat the prohibition on ex post facto laws in the Minnesota Constitution any differently than its federal counterpart, we conclude that there has been no violation of the Minnesota Constitution’s ex post facto clause in this case.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the extended OFP did not violate Berg-strom’s double-jeopardy rights under the Minnesota Constitution.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Although we conclude that Mad-sen provides the appropriate framework in this case, we note that the level of scrutiny applied to a content-neutral injunction under Madsen appears to be equivalent to or more exacting than the level of scrutiny applied under O''Brien.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the prohibition on double jeopardy does not apply to litigation between private parties, we express no opinion about whether we should reconsider our decision in Hanson in light of Hudson with respect to the standard that governs challenges brought under the Minnesota Constitution.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8 Accord*785ingly, we reverse and remand to the district court for further findings as to whether the provisions burdening Bergstrom’s speech to the children are necessary to serve a significant state interest.', 'general', 'Rew ex rel. T.C.B. v. Bergstrom', 'https://www.courtlistener.com/opinion/8281370/', '8281370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the plain language of the statute does not permit a person to raise the affirmative defense of necessity at an implied consent hearing, we affirm.', 'general', 'Axelberg v. Commissioner of Public Safety', 'https://www.courtlistener.com/opinion/8281406/', '8281406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that Minn.', 'general', 'Axelberg v. Commissioner of Public Safety', 'https://www.courtlistener.com/opinion/8281406/', '8281406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute does not implicate the First Amendment and that Brown lacks standing to challenge the statute on the other grounds.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2639089/', '2639089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 19 We conclude that Brown does not have standing to raise either his vagueness or overbreadth challenge.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2639089/', '2639089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that § 13-2921 does not implicate First Amendment rights, however, we do not specifically address this argument.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2639089/', '2639089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that contention dubious.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2639089/', '2639089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2639089/', '2639089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “an anonymous report of erratic driving must be evaluated in light of the imminent risks that a drunk driver poses to himself and the public.', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that both days’ events offend the Vermont Constitution.', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that he was, and that his motion to suppress should have been granted on that basis, we do not reach his other claims.', 'suppression', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2, the State stipulated that, if we conclude that there was no reasonable suspicion upon which to detain defendant, the motion to suppress'' should have been granted.', 'suppression', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the officer here did not have a reasonable, articulable suspicion of drug activity on May 5, and that the district court therefore erred in denying defendant’s motion to suppress the evidence obtained on that day.', 'suppression', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Langlois, we concluded that an officer did not have probable cause to search an automobile based on a telephone informant who stated that the defendant, Langlois, was driving around downtown Bennington in a 1989 pickup truck with fresh front-end damage and a bag of marijuana behind the front seat.', 'probable_cause', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “the information .', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sprague, we held that any “police intrusion [must] proceed no further than necessary to effectuate the purpose of the stop.', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 719, 722 (1986), we held that the testimony of a probationer at a probation revocation hearing held prior to the disposition of related criminal charges is inadmissible against probationer during the subsequent criminal proceedings.', 'general', 'State v. Brunelle', 'https://www.courtlistener.com/opinion/1533148/', '1533148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Brunelle', 'https://www.courtlistener.com/opinion/1533148/', '1533148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Seeking to balance these concerns, we therefore hold that previously suppressed evidence is unavailable to the State for impeachment purposes except when it is clear that the defendant has testified during direct examination in a manner contradictory to the suppressed evidence.', 'suppression', 'State v. Brunelle', 'https://www.courtlistener.com/opinion/1533148/', '1533148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 416, 419 (1989), for example, we concluded that the trial court had exercised its discretion under Rule 403 based on the trial court’s statement that it was “going to let in the cocaine evidence.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We concluded that the record did not indicate that the prejudicial effect of the admitted evidence “so overweighed the probative value that the evidence should have been excluded as a matter of law.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Senecal, we concluded that a defendant had waived his claim that the court erred in denying his motion to suppress where defendant failed to object at trial to the admission of the evidence that he had earlier sought to suppress.', 'suppression', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the court, by not instructing the jury on this element of the kidnap *297statute, failed to meet this duty and allowed the jury to engage in assumptions or speculations as to the actual nature of the offense charge.', 'general', 'State v. McLaren', 'https://www.courtlistener.com/opinion/1907792/', '1907792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the severity of the contempt at issue in this case did not exceed that which we expect trial courts to meet with professionalism and self-restraint, and because we see no evidence that the court lost its composure, we hold that the court acted within its discretion in punishing defendant’s contempts summarily.', 'general', 'State v. North', 'https://www.courtlistener.com/opinion/1057282/', '1057282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'State v. North', 'https://www.courtlistener.com/opinion/1057282/', '1057282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that defendant’s conduct does not justify the heightened charge.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the State argues that ‘Trom the person” may apply equally to items attached to and nearby the victim, we find that this is contrary to the common law understanding of the term.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that “and custody of another” refers to the area immediately within one’s control or presence, distinguishable from one’s person.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it was not, because defendant’s conduct did not satisfy any of the factors traditionally used by other jurisdictions that have similarly interpreted *285larceny from the person.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statement of the witness while on the stand was not inconsistent, in the sense urged by appellant, with his prior recorded statement.', 'general', 'State v. Settle', 'https://www.courtlistener.com/opinion/1916824/', '1916824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant’s possession of household items used in the commission of a crime and found at the scene of a crime established a sufficient *573nexus linking his nearby residence to the criminal enterprise because such items were often concealed at the home.', 'general', 'State v. Quigley', 'https://www.courtlistener.com/opinion/1925418/', '1925418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the district court’s findings, and the record on which they are based, we conclude that the State’s position is unsupported.', 'general', 'State v. Quigley', 'https://www.courtlistener.com/opinion/1925418/', '1925418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'State v. Quigley', 'https://www.courtlistener.com/opinion/1925418/', '1925418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this testimony alone, we affirm the trial court’s conclusion that there was no probable cause to conduct a search of Quigley’s bedroom, and that the “community living exception” does not apply.', 'probable_cause', 'State v. Quigley', 'https://www.courtlistener.com/opinion/1925418/', '1925418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the conviction could not stand because the information omitted an essential element of the offense and, therefore, the defendant had no opportunity to present any potential defense concerning the reason for the suspension.', 'general', 'State v. Longe', 'https://www.courtlistener.com/opinion/1435894/', '1435894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Williams, we reversed a § 674 conviction because the information stated that defendant operated a motor vehicle while his license was suspended in violation of § 674, but did not state the reason of the underlying suspension.', 'general', 'State v. Longe', 'https://www.courtlistener.com/opinion/1435894/', '1435894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the conviction.', 'general', 'State v. Longe', 'https://www.courtlistener.com/opinion/1435894/', '1435894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We ignore reality if we conclude that the existence of ethical obligations will by themselves ensure effective representation in the face of compelling and unavoidable economic pressures to the contrary.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record evidence here did not support a finding that defendant voluntarily exited his vehicle.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in denying defendant’s motion to suppress, and therefore that the judgment must be reversed.', 'suppression', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While recognizing the Fourth Amendment rule announced in Mimms, we held that an order to exit one’s vehicle is a “further ‘seizure’ within the meaning of Article Eleven.', 'search_seizure', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no basis for the exit order in the circumstances of this case involving a routine traffic stop for a speeding violation, we conclude that the trial court erred in denying defendant’s motion to suppress and therefore that the judgment must be reversed.', 'suppression', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the additional seizure represented by the officer’s request that defendant exit the vehicle was unsupported by the requisite showing of need, and in violation of Chapter I, Article 11 of the Vermont Constitution.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the circumstances here in their totality, we conclude that a reasonable person in defendant’s circumstances would not have felt free to refuse when the officer asked him if he would “mind having a seat in my car while I check your license.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the seizure effected by the officer in requiring defendant to exit the vehicle was illegal, we conclude that defendant’s subsequent “consents” to the search of his person, car, and home were *135tainted and ineffective.', 'ineffective_assistance', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In these circumstances, we find that the basic purposes underlying the preservation rule would not be served by declining to address defendant’s arguments.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that defendant was illegally seized when — absent any objective danger to the officer or others, or a reasonable suspicion of wrongdoing — he was required to exit the vehicle.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the action of the trial judge controlled and found this judge’s rationale to be valid.', 'general', 'State v. Lamb', 'https://www.courtlistener.com/opinion/2259118/', '2259118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” But, in that case, we held that the prior bad act evidence went to prove *150that defendant meant to intimidate and threaten the victim2 — and “to put the victim’s recantation of prior statements into context for the jury.', 'general', 'State v. Hendricks', 'https://www.courtlistener.com/opinion/2320755/', '2320755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '), where we held that the Due Process Clause of the Fourteenth Amendment requires the appointment of counsel in a civil contempt proceeding in which an indigent defendant faces “actual imprisonment.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was not entitled to counsel at this hearing because the court did not consider incarcerating defendant without providing him another opportunity, if necessary, to challenge his ability to comply with the child support orders and the reasonableness of the purge conditions with the aid of counsel.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s right to counsel was fully protected in these proceedings.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the public defender act does not authorize assignment of a public defender in this case, this does not *404end our inquiry.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s order of incarceration and deny the motion to withdraw.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that a respondent in an *410indirect civil contempt proceeding is not entitled to appointed counsel if he or she is indigent, even though the contempt proceeding may result in imprisonment.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that defendant is unable to meet his burden under the first Brady prong, we need not reach the two other prongs.', 'general', 'State v. Rooney', 'https://www.courtlistener.com/opinion/2556990/', '2556990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While appreciating the appeal of this approach, we conclude that the doctrine cannot be reconciled with the circumstances of this case.', 'general', 'State v. Rooney', 'https://www.courtlistener.com/opinion/2556990/', '2556990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Tester, for instance, we concluded that no Brady violation had occurred, despite the State’s failure to disclose a videotaped interview of the victim, when the defendant was “well aware” of the existence and contents of the interview.', 'general', 'State v. Rooney', 'https://www.courtlistener.com/opinion/2556990/', '2556990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in LeClaire, we concluded that the defendant had not shown that the State improperly suppressed evidence where the prosecution failed to produce a sample of the victim’s hair for DNA testing despite the defendant’s request to do so because the defendant had not taken steps to request the necessary exhumation order.', 'suppression', 'State v. Rooney', 'https://www.courtlistener.com/opinion/2556990/', '2556990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ORDERED that pursuant to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there were severe aggravating circumstances present, and we affirm the sentence.', 'sentencing', 'State v. Norton', 'https://www.courtlistener.com/opinion/1673402/', '1673402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we held that a greater than double durational departure was not justified.', 'general', 'State v. Norton', 'https://www.courtlistener.com/opinion/1673402/', '1673402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982) (where we held that committing an assault on a nursery school teacher in front of the children was a “particularly outrageous act,” and that while the children were not technically victims of the crime, “they were victims in another sense”);', 'general', 'State v. Norton', 'https://www.courtlistener.com/opinion/1673402/', '1673402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981) (where we held that the robbery was a more aggravated form of robbery because the defendants put a large number of people in fear, kidnapped one person, and assaulted several others during their escape).', 'general', 'State v. Norton', 'https://www.courtlistener.com/opinion/1673402/', '1673402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case we conclude that the trial court did not err in sentencing defendant to the 72-month prison term.', 'sentencing', 'State v. Norton', 'https://www.courtlistener.com/opinion/1673402/', '1673402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s greater than double, but nonetheless limited, durational departure.', 'general', 'State v. Norton', 'https://www.courtlistener.com/opinion/1673402/', '1673402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the issue was the admission of expert testimony on the credibility of the complaining witness, and it was on that issue that we reversed.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Then, in 1985, this Court held that the 1982 amendment was not self-executing and that a statutory change was therefore necessary before courts could deny bail under the new constitutional amendment.', 'general', 'State v. Pellerin', 'https://www.courtlistener.com/opinion/1057221/', '1057221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the trial court properly analyzed this case under § 7553.', 'general', 'State v. Pellerin', 'https://www.courtlistener.com/opinion/1057221/', '1057221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed and remanded because the trial court had based its ruling solely on the constitutional amendment and had ignored the statutory scheme that still applied to bail appeals.', 'general', 'State v. Pellerin', 'https://www.courtlistener.com/opinion/1057221/', '1057221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Pellerin', 'https://www.courtlistener.com/opinion/1057221/', '1057221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the definition in § 2631 applies only to the sections contained in subchapter 2.', 'general', 'State v. Beaudoin', 'https://www.courtlistener.com/opinion/1057308/', '1057308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not commit plain error in faffing to convene a new competency hearing because counsel for the defendant did not state the existence of new evidence, nor did she advance any new evidence for the court to consider.', 'general', 'State v. Beaudoin', 'https://www.courtlistener.com/opinion/1057308/', '1057308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Beaudoin', 'https://www.courtlistener.com/opinion/1057308/', '1057308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore we affirm its determination.', 'general', 'State v. Beaudoin', 'https://www.courtlistener.com/opinion/1057308/', '1057308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that not only do defendants charged under the 1985 version of the statute have no burden of production or persuasion, but there also is no reasonable belief or necessity requirement.', 'general', 'State v. Niska', 'https://www.courtlistener.com/opinion/2135066/', '2135066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that an amendment to a spousal maintenance statute would be applied retroactively.', 'general', 'State v. Niska', 'https://www.courtlistener.com/opinion/2135066/', '2135066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that the Fourteenth Amendment prohibited shifting the burden of proof on the element of intent to a criminal defendant.', 'general', 'State v. Niska', 'https://www.courtlistener.com/opinion/2135066/', '2135066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and hold that the consent of Dominique’s physical and legal custodian, Jody Niska, was sufficient to relieve the Niskas of any liability for kidnapping.', 'general', 'State v. Niska', 'https://www.courtlistener.com/opinion/2135066/', '2135066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals in holding that subdivision 2 of the 1985 statute does not codify the necessity defense, and we further hold that under subdivision 2 the state is required to disprove the defense beyond a reasonable doubt and that a defendant need only produce sufficient evidence to fairly make the statutory defense an issue in the case.', 'general', 'State v. Niska', 'https://www.courtlistener.com/opinion/2135066/', '2135066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 30, 32 (1973), wherein we held that implementing Administrative Order No.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Trombly, where we held that “delay arising out of the relationship between attorney and client must be attributed to the defendant, and omitted from consideration.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 138, 139 (1978), this Court held that “[t]he passage of over eighteen months from citation to trial, not brought about by the defendant, is so long as to constitute prejudice as a matter of law and a violation of the defendant’s constitutional rights.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining specific periods of time, we conclude that the period between July and November 2001 should not count against the state because much of the delay during that period was the result of defendant’s motion to recuse the trial judge.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, we conclude that a significant portion of the delay in bringing defendant to trial must be attributed to the state, even though most of the delay was caused by the inability or unwillingness of assigned counsel to move the case forward.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the entire circumstances in this case — particularly defendant’s lengthy pretrial incarceration, much of which is not attributable to defendant — we conclude that the prejudice factor must be weighed against the state.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that the plain language of the statute does not require intent to commit a crime within the building, we reverse and reinstate the judgment of the district court.', 'general', 'Munger v. State', 'https://www.courtlistener.com/opinion/1917677/', '1917677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the plain statutory language for the offense of first-degree burglary which proscribes nonconsensual entry into a building with intent to commit a crime does not also require that the intent be to commit a crime within the building entered.', 'general', 'Munger v. State', 'https://www.courtlistener.com/opinion/1917677/', '1917677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction.', 'general', 'State v. Tracy', 'https://www.courtlistener.com/opinion/2273835/', '2273835') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. LaCourse', 'https://www.courtlistener.com/opinion/8209550/', '8209550') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree that the evidence was erroneously admitted, we reverse and remand for a new trial.', 'general', 'State v. Maduro', 'https://www.courtlistener.com/opinion/8209726/', '8209726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that counsel’s assessment of the viability of a multiplicity challenge under 13 V.', 'general', 'In re Kirby', 'https://www.courtlistener.com/opinion/8210115/', '8210115') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In re Kirby', 'https://www.courtlistener.com/opinion/8210115/', '8210115') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the crime of embezzlement by a public official is not a specific intent crime, the intent5 to commit the act or acts that results in the misappropriation or misuse is still necessary to convict a public official under the second paragraph of West Virginia Code § 61-3-20.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/8218237/', '8218237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having fully reviewed the facts of the case in conjunction with the applicable statute, we reverse the circuit court’s finding that West Virginia Code § 61-3-20 (1989) requires proof of specific intent to convict a public official of embezzlement.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/8218237/', '8218237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we discuss briefly infra, the appellant was precluded from offering or eliciting certain evidence relating to why he issued the checks, but even without that evidence being put before the jury, we conclude that the State’s evidence of the appellant’s criminal intention to defraud using post-dated checks was insufficient to establish a criminal violation of W.', 'general', 'State v. Braham', 'https://www.courtlistener.com/opinion/8218915/', '8218915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, however, we have carefully examined the record, and we find that there was insufficient evidence to establish beyond a reasonable doubt that the appellant had a criminal intent with respect to the checks in question.', 'general', 'State v. Braham', 'https://www.courtlistener.com/opinion/8218915/', '8218915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we reverse the appellant’s conviction on a charge of fraudulent schemes because the State’s evidence did not show beyond a reasonable doubt that the appellant had the requisite criminal intent.', 'general', 'State v. Braham', 'https://www.courtlistener.com/opinion/8218915/', '8218915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 136 (1987), we reversed a conviction of a compulsive gambler on a worthless check charge.', 'general', 'State v. Braham', 'https://www.courtlistener.com/opinion/8218915/', '8218915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '111 (1933), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 822 (1986), wherein this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse the appellant’s conviction.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/8218978/', '8218978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in the exercise of our supervisory power to insure the fair administration of justice, we hold that all custodial interrogation including any information about rights, any waiver of those rights, and all questioning shall be electronically recorded where feasible and must be recorded when questioning occurs at a place of detention.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, the Alaska Supreme Court has also ruled that such recording is generally required: "we hold that an unexcused failure to electronically record a custodial interrogation conducted in a places of detention violates a suspect''s right to due process, under the Alaska Constitution, and that any statement thus obtained is generally inadmissible.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 558 (1987), for instance, we held that "[e]xpert testimony can be utilized to explain the psychological basis for the battered woman''s syndrome and to offer an opinion that the defendant meets the requisite profile of the syndrome.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whittaker contends that the excluded testimony should have been allowed as an exception to the hearsay rule, we conclude that the excluded testimony of Ms.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whittaker''s assignments of error, we conclude that the circuit court did not err by upholding Ms.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the parties'' arguments, the record presented for our consideration, and the pertinent authorities, we affirm Ms.', 'general', 'State v. Whittaker', 'https://www.courtlistener.com/opinion/1331345/', '1331345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in refusing defendant’s requests for an additional rule 11 examination based on his failure to cooperate with counsel.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in refusing to order an additional rule 11 examination to determine defendant’s competency to stand trial.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the trial court took adequate steps to assure defendant’s competency, we need not address this issue.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court acted within its discretion in denying defendant’s requests for continuances.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Det.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not commit clear and manifest error in finding defendant’s confession voluntary.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that A.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s finding of cruelty is supported by the record.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court properly found the existence of statutory aggravating circumstances that would support imposition of the death penalty in the absence of mitigating circumstances.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the overwhelming evidence of defendant’s guilt, principally his confession, we hold that he has failed to show substantial prejudice.', 'general', 'State v. Amaya-Ruiz', 'https://www.courtlistener.com/opinion/2612518/', '2612518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that legislative discretion was reasonably exercised in this case, and accordingly hold that the sentencing of the defendants to a minimum period of incarceration without possibility of parole for a period of five years under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we find that the defendants were properly sentenced under Act 181.', 'sentencing', 'State v. Freitas', 'https://www.courtlistener.com/opinion/1343616/', '1343616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the evidence was sufficient to sustain a conviction for aggravated kidnaping separate and apart from the offense of aggravated criminal sexual assault.', 'general', 'People v. Quintana', 'https://www.courtlistener.com/opinion/2238631/', '2238631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the facts of the instant case, we find that most of the Smith factors are satisfied, thereby making a separate conviction for aggravated kidnaping proper.', 'general', 'People v. Quintana', 'https://www.courtlistener.com/opinion/2238631/', '2238631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While at first glance the second factor may seem to favor defendant because the evidence established, at least through the testimony of the victim, that she was sexually assaulted as soon as she was pulled into the van, we find that the third and fourth factors heavily favor the State’s position.', 'general', 'People v. Quintana', 'https://www.courtlistener.com/opinion/2238631/', '2238631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was not only no plain error but no error at all, because Thames’ statement meets the statutory criteria for admission under section 14-102(b)(l).', 'general', 'Bell v. United States', 'https://www.courtlistener.com/opinion/2301144/', '2301144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm all three convictions, but remand Forte’s case for the purpose of modifying the amount of restitution he must pay.', 'general', 'Bell v. United States', 'https://www.courtlistener.com/opinion/2301144/', '2301144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that speech alone in certain contexts can constitute disorderly conduct;', 'general', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that application of the disorderly conduct statute to speech alone is permissible under appropriate circumstances.', 'general', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the factual allegations in the petition more closely resemble that of a threat under Watts than of an incitement to action under Brandenburg.', 'general', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s statement, we conclude that his statements, as alleged in the petition, did constitute true threats.', 'general', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under these circumstances such conduct supports a finding of probable cause of "otherwise disorderly" conduct.', 'probable_cause', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the petition was sufficient to establish probable cause on the second element.', 'probable_cause', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statute was sufficiently designed to overcome an attack for vagueness and that it was not so broad that it could be applied to conduct protected by the constitution.', 'general', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the city ordinance was similar in import to the first element of the state disorderly conduct statute and noted:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that such an examination is necessary because certain circumstances may require criminal culpability, even in instances where the alleged disorderly conduct may be protected under the First Amendment.', 'general', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that when viewing the conduct in light of the circumstances, especially the time and place of the conduct, the defendant''s actions were disorderly and did cause and provoke a disturbance.', 'general', 'State v. A.S.', 'https://www.courtlistener.com/opinion/8238090/', '8238090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the objective reason to believe standard to the Grant County case, we conclude that the complaint should have been referred to the district attorney.', 'general', 'Naseer v. Miller', 'https://www.courtlistener.com/opinion/8238325/', '8238325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Focusing on the allegations in the complaint, and ignoring Naseer''s history of filing frivolous complaints against prison officials, we conclude that his allegations that a prison guard squeezed his neck to the point of impairing his breathing, without any legitimate purpose for the chokehold, could conceivably support a charge of battery or some other offense.', 'general', 'Naseer v. Miller', 'https://www.courtlistener.com/opinion/8238325/', '8238325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'State v. Stuckey', 'https://www.courtlistener.com/opinion/8238943/', '8238943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As Weidner requires a scienter element in a variable obscenity statute, we affirm.', 'general', 'State v. Stuckey', 'https://www.courtlistener.com/opinion/8238943/', '8238943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the circuit court''s dismissal of Count 2 charging Stuckey with exposing genitals to a child as Wis.', 'dismissal', 'State v. Stuckey', 'https://www.courtlistener.com/opinion/8238943/', '8238943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There are no disputed material facts on this appeal, and we affirm.', 'general', 'State v. Guarnero', 'https://www.courtlistener.com/opinion/8239056/', '8239056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the circuit court.', 'general', 'State v. Giese', 'https://www.courtlistener.com/opinion/8239086/', '8239086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction, vacate the sentence, and remand for resentencing.', 'sentencing', 'State v. Pena', 'https://www.courtlistener.com/opinion/2640047/', '2640047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 26 For the foregoing reasons, we affirm Defendant’s conviction and remand for resen-tencing.', 'general', 'State v. Pena', 'https://www.courtlistener.com/opinion/2640047/', '2640047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the first justification under the Gant rule (arrestee unsecured and within reach of area to be *190searched) does not apply here.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/8327638/', '8327638') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the second justification under Gant (reasonable to believe vehicle contains evidence of a crime) does apply in this instance.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/8327638/', '8327638') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/8327638/', '8327638') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we REVERSE the circuit court’s ruling to the extent that it held Dawkins’ probation is tolled during his participation in the CSP.', 'general', 'State v. Dawkins', 'https://www.courtlistener.com/opinion/1389338/', '1389338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in denying defendant’s motion to dismiss the robbery charge.', 'dismissal', 'State v. Kemmerlin', 'https://www.courtlistener.com/opinion/1389346/', '1389346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the crimes do not merge with the first-degree murder conviction.', 'general', 'State v. Kemmerlin', 'https://www.courtlistener.com/opinion/1389346/', '1389346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the crime of solicitation requires the element of enticement, an element not required for murder under a theory of acting in concert, we hold that solicitation is not a lesser included offense of murder by acting in concert.', 'general', 'State v. Kemmerlin', 'https://www.courtlistener.com/opinion/1389346/', '1389346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant offered no other substantial evidence of this circumstance, we hold that the trial court did not err in refusing to submit the (f)(6) mitigating circumstance.', 'general', 'State v. Kemmerlin', 'https://www.courtlistener.com/opinion/1389346/', '1389346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in which we held that solicitation to commit murder is a lesser included offense of first-degree murder as an accessory before the fact.', 'general', 'State v. Kemmerlin', 'https://www.courtlistener.com/opinion/1389346/', '1389346') ON CONFLICT DO NOTHING;
