INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we conclude that the pre-trial issue, jury selection, guilt-innocence phase, and sentencing proceeding were free of prejudicial error but that the death sentence was disproportionate.', 'sentencing', 'State v. Kemmerlin', 'https://www.courtlistener.com/opinion/1389346/', '1389346') ON CONFLICT DO NOTHING;
