INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court applied the Miranda ruling soon after it was announced by the United States Supreme Court, and early on, we held that a suspect need not be re-Mirandized during continuous interrogation.', 'general', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
