INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing a trial judge''s ruling on a motion to suppress, we make an independent determination based upon the totality of the circumstances, viewing the evidence in a light most favorable to *145 the State [appellee], and we reverse only if the ruling is clearly against the preponderance of the evidence.', 'suppression', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The evidence was suppressed and we affirmed.', 'suppression', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court''s refusal to give an instruction on a lesser-included offense stating, "[the officers''s] testimony so sharply conflicted with Doby''s that it would not be reasonable to expect a jury to pick and choose and come up with a finding of a lesser offense when to do so would require a finding that Doby was a liar and the officers liars in part.', 'general', 'Grillot v. State', 'https://www.courtlistener.com/opinion/1637248/', '1637248') ON CONFLICT DO NOTHING;
