INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In response to an adult defendant''s claim that the Registration Act violated his right to substantive due process, we held that the public interest to be served by the Registration Act was the assistance of law enforcement in the protection of children.', 'general', 'In Re JW', 'https://www.courtlistener.com/opinion/2254721/', '2254721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Malchow, we held that the purpose of the Notification Law, like the Registration Act, was the protection of the public from sex offenders.', 'general', 'In Re JW', 'https://www.courtlistener.com/opinion/2254721/', '2254721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case at bar, this court holds that the requirements of the Registration Act apply equally to adults and juveniles and that our constitutional safeguards do not prevent the Registration Act''s lifetime registration provisions from being applied to minors of all ages.', 'general', 'In Re JW', 'https://www.courtlistener.com/opinion/2254721/', '2254721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, this court held that Rule 604(d) applies to juvenile proceedings.', 'general', 'In Re JW', 'https://www.courtlistener.com/opinion/2254721/', '2254721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reading section 2(A-5) together with section 2(E) so that no word or paragraph is rendered meaningless, we conclude that J.', 'general', 'In Re JW', 'https://www.courtlistener.com/opinion/2254721/', '2254721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was nothing unreasonable in the statute''s method of serving its purpose given the direct relationship between the registration of sex offenders and the protection of children.', 'general', 'In Re JW', 'https://www.courtlistener.com/opinion/2254721/', '2254721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the appellate court correctly determined that J.', 'general', 'In Re JW', 'https://www.courtlistener.com/opinion/2254721/', '2254721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that waiver does not bar consideration of these issues.', 'general', 'In Re JW', 'https://www.courtlistener.com/opinion/2254721/', '2254721') ON CONFLICT DO NOTHING;
