INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that Krogmann failed to preserve error.', 'general', 'State of Iowa v. Robert Paul Krogmann', 'https://www.courtlistener.com/opinion/4472399/', '4472399') ON CONFLICT DO NOTHING;
