INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 45 For these reasons, we conclude that the trial court did not abuse its discretion by finding that Payne’s statements were voluntary.', 'general', 'State of Arizona v. Christopher Mathew Payne', 'https://www.courtlistener.com/opinion/2643399/', '2643399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the State’s comment here was improper, we do not find fundamental error.', 'general', 'State of Arizona v. Christopher Mathew Payne', 'https://www.courtlistener.com/opinion/2643399/', '2643399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the circumstances clause is more like the “care and custody” provision, we decline to apply the means rea to the circumstances clause.', 'general', 'State of Arizona v. Christopher Mathew Payne', 'https://www.courtlistener.com/opinion/2643399/', '2643399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regarding the (F)(8) factor, because we found that the jury instructions did not constitute fundamental error and that no reasonable jury could have found the additional elements not satisfied, see supra ¶¶ 137-41, we reject these arguments.', 'jury_instruction', 'State of Arizona v. Christopher Mathew Payne', 'https://www.courtlistener.com/opinion/2643399/', '2643399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 167 For the foregoing reasons, we affirm Payne’s convictions and sentences.', 'sentencing', 'State of Arizona v. Christopher Mathew Payne', 'https://www.courtlistener.com/opinion/2643399/', '2643399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we conclude that the objections were timely and adequate to preserve the issue for review.', 'general', 'Ebron v. United States', 'https://www.courtlistener.com/opinion/2399176/', '2399176') ON CONFLICT DO NOTHING;
