INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Tennessee’s statutory rape provision sets the age of consent at eighteen and is therefore significantly broader than the generic offense, we hold that a conviction thereunder does not categorically qualify for the crime-of-violence enhancement.', 'general', 'United States v. Jorge Rodriguez', 'https://www.courtlistener.com/opinion/855401/', '855401') ON CONFLICT DO NOTHING;
