INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellant''s behavior was a continuing course of conduct from the middle of 1994 until his arrest in January 1997, that it constituted a single offense (not two separate offenses), and that he was therefore not entitled to a special unanimity instruction on the pre- and post-reconciliation facts.', 'general', 'Washington v. United States', 'https://www.courtlistener.com/opinion/1509822/', '1509822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), in which we held that a defendant''s right of confrontation under the Sixth Amendment is limited to eliciting evidence that is relevant and probative.', 'general', 'Washington v. United States', 'https://www.courtlistener.com/opinion/1509822/', '1509822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1993), this court held that a reference to the defendant''s previous incarceration, though "problematic," id.', 'general', 'Washington v. United States', 'https://www.courtlistener.com/opinion/1509822/', '1509822') ON CONFLICT DO NOTHING;
