INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that he has not done so.', 'general', 'Washington v. United States', 'https://www.courtlistener.com/opinion/1509822/', '1509822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the contrary, given the strength of the government''s case and the weakness of the defense, and assuming for the sake of argument that Drew even applies here,[7] we conclude that any possible harm flowing from this comment was "too trivial to worry about.', 'general', 'Washington v. United States', 'https://www.courtlistener.com/opinion/1509822/', '1509822') ON CONFLICT DO NOTHING;
