INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since exigent circumstances did not justify the warrantless seizure and search, we hold that the superior court erred in allowing the bag and its contents to be admitted into evidence.', 'general', 'Ingram v. State', 'https://www.courtlistener.com/opinion/1359006/', '1359006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the error in admitting the bank bag and its contents was harmless beyond a reasonable doubt.', 'general', 'Ingram v. State', 'https://www.courtlistener.com/opinion/1359006/', '1359006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in rejecting Ingram’s proposed informer instruction.', 'general', 'Ingram v. State', 'https://www.courtlistener.com/opinion/1359006/', '1359006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the search did not exceed the scope of the warrant.', 'general', 'Ingram v. State', 'https://www.courtlistener.com/opinion/1359006/', '1359006') ON CONFLICT DO NOTHING;
