INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that those articles were encompassed within Heriford’s general consent to the search of apartment 20.', 'general', 'Ingram v. State', 'https://www.courtlistener.com/opinion/1359006/', '1359006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither Ingram’s subjective state of mind nor his wife’s concealment of the bag in the shed can support a conclusion that the bag was abandoned.', 'general', 'Ingram v. State', 'https://www.courtlistener.com/opinion/1359006/', '1359006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the objective circumstances in this case, as they appeared at the time of the seizure and search of the bank bag, do not support a reasonable conclusion that the bag was abandoned.', 'general', 'Ingram v. State', 'https://www.courtlistener.com/opinion/1359006/', '1359006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we conclude that admission of the photocopies did not amount to error.', 'general', 'Ingram v. State', 'https://www.courtlistener.com/opinion/1359006/', '1359006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the undefined term
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, this Court held, the preprinted “general conditions” could be considered “special conditions” under the statute but only if the form expressly so provides.', 'general', 'Gamble v. State', 'https://www.courtlistener.com/opinion/1407747/', '1407747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, when the record clearly reflects an appropriate basis for a disparate sentence, the sentencing judge may impose a different sentence on a co-defendant in a criminal trial.', 'sentencing', 'State v. Follin', 'https://www.courtlistener.com/opinion/1389198/', '1389198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Follin', 'https://www.courtlistener.com/opinion/1389198/', '1389198') ON CONFLICT DO NOTHING;
