INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that MCL 768.', 'general', 'People v. Watkins; People v. Pullen', 'https://www.courtlistener.com/opinion/824721/', '824721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that evidence admissible pursuant to MCL 768.', 'general', 'People v. Watkins; People v. Pullen', 'https://www.courtlistener.com/opinion/824721/', '824721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we hold that MRE 403 applies to evidence admissible under MCL 768.', 'general', 'People v. Watkins; People v. Pullen', 'https://www.courtlistener.com/opinion/824721/', '824721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that MCL 768.', 'general', 'People v. Watkins; People v. Pullen', 'https://www.courtlistener.com/opinion/824721/', '824721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying McDougall, we conclude that MCL 768.', 'general', 'People v. Watkins; People v. Pullen', 'https://www.courtlistener.com/opinion/824721/', '824721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Appeals in People v Watkins, Docket No.', 'general', 'People v. Watkins; People v. Pullen', 'https://www.courtlistener.com/opinion/824721/', '824721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in Watkins.', 'general', 'People v. Watkins; People v. Pullen', 'https://www.courtlistener.com/opinion/824721/', '824721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the Court of Appeals’ judgment in Watkins, Docket No.', 'general', 'People v. Watkins; People v. Pullen', 'https://www.courtlistener.com/opinion/824721/', '824721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reading all the *177provisions of this statute together, and thus giving effect to the Legislature’s stated intent, we hold that MCL 777.', 'general', 'People v. Peltola', 'https://www.courtlistener.com/opinion/828410/', '828410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when calculating a defendant’s recommended minimum sentence range under the sentencing guidelines when the defendant’s minimum and maximum sentences may be enhanced pursuant to MCL 333.', 'sentencing', 'People v. Peltola', 'https://www.courtlistener.com/opinion/828410/', '828410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the 2006 amendments only clarified the OVs and offense class applicable to offenders falling under the purview of § 21(4).', 'general', 'People v. Peltola', 'https://www.courtlistener.com/opinion/828410/', '828410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that § 21(4) does not provide an instruction regarding the scoring of the PRVs contrary to that set forth in § 21(1).', 'general', 'People v. Peltola', 'https://www.courtlistener.com/opinion/828410/', '828410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm defendant’s sentences.', 'sentencing', 'People v. Peltola', 'https://www.courtlistener.com/opinion/828410/', '828410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither the Legislature in its enactment of the statute nor the Supreme Court in Bunn intended such a result.', 'general', 'State v. Spano', 'https://www.courtlistener.com/opinion/7403452/', '7403452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this standard was met in this case, and the record supports the findings.', 'general', 'State v. Spano', 'https://www.courtlistener.com/opinion/7403452/', '7403452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant appeals, and we affirm.', 'general', 'State v. Spano', 'https://www.courtlistener.com/opinion/7403452/', '7403452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Cornell, we held that an offense is an “offense inferior to that charged in the indictment” for purposes of MCL 768.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Court of Appeals erred in its double jeopardy analysis by comparing the felony-murder convictions to the non-predicate felonies of armed robbery.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in adopting Const 1963, art 1, § 15, the ratifiers of our constitution intended that our double jeopardy provision be construed consistently with then-existing Michigan caselaw and with the interpretation given to the Fifth Amendment by federal courts at the time of ratification.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the “same elements” test set forth in Blockburger best gives effect to the intentions of the ratifiers of our constitution.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that these offenses are not the “same offense” under either the Fifth Amendment or Const 1963, art 1, § 15 and therefore defendant may be punished separately for each offense.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that “same offense” in Const 1963, art 1, § 15 means the same thing in the context of the “multiple punishments” strand of double jeopardy as it does in the context of the “successive prosecutions” strand addressed by the Court in Nutt.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, and most critically, we concluded that White’s test was inconsistent with the understanding of the term “same offense” on the part of the ratifiers of our constitution.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the part of the judgment of the Court of Appeals that vacated the armed robbery convictions and sentences and two of the felony-firearm convictions and sentences, and remand this case to the trial court to reinstate defendant’s convictions and sentences for armed robbery and the accompanying felony-firearm convictions and sentences.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Blockburger sets forth the proper test to determine when multiple punishments are barred on double jeopardy grounds.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/842634/', '842634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was not “seized” within the meaning of the Fourth Amendment until after the totality of the circumstances gave the officer a reasonable suspicion that defendant had been engaged in criminal behavior.', 'search_seizure', 'People v. Jenkins', 'https://www.courtlistener.com/opinion/848668/', '848668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and remand this case to the trial court for reinstatement of the charges brought against defendant and for further proceedings.', 'general', 'People v. Jenkins', 'https://www.courtlistener.com/opinion/848668/', '848668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and remand this case to the trial court for reinstatement of the charges against defendant and for further proceedings consistent with this opinion.', 'general', 'People v. Jenkins', 'https://www.courtlistener.com/opinion/848668/', '848668') ON CONFLICT DO NOTHING;
