INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the trial court and remand with instructions to reinstate Counts II and III.', 'general', 'State v. Dugan', 'https://www.courtlistener.com/opinion/852992/', '852992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a discovery rule does not govern § 1681p.', 'general', 'TRW Inc. v. Andrews', 'https://www.courtlistener.com/opinion/118465/', '118465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the text and structure of § 1681p evince Congress'' intent to preclude judicial implication of a discovery rule.', 'general', 'TRW Inc. v. Andrews', 'https://www.courtlistener.com/opinion/118465/', '118465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding a violation of the Indiana Double Jeopardy clause, we held that "there is at least a reasonable ''possibility-indeed a high probability-that the jury used the same evidentiary fact-the restraining and strangulation of [the victim]l-to prove an essential element of the conspiracy to commit murder (the overt act) and also the essential element of murder.', 'general', 'Guyton v. State', 'https://www.courtlistener.com/opinion/853128/', '853128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without disaggre-gating the evidence into separate "eviden-tiary facts," we concluded that the same body of evidence (brutal beating plus taking wallet) may reasonably have been used by the jury to prove both offenses.', 'general', 'Guyton v. State', 'https://www.courtlistener.com/opinion/853128/', '853128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'factors, we conclude that Harris’s right to a speedy sentencing under the Sixth Amendment was infringed.', 'sentencing', 'Harris v. State', 'https://www.courtlistener.com/opinion/2313345/', '2313345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On balance, we find that this factor is neutral.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/2313345/', '2313345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of these circumstances, we find that the extraordinary length of the delay in this case and the absence of any justifiable reason or satisfactory explanation for six and one-half years of it outweigh the third and fourth factors, relating to the assertion of the right and prejudice.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/2313345/', '2313345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse on that ground, Harris’s remaining arguments are moot.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/2313345/', '2313345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/2313345/', '2313345') ON CONFLICT DO NOTHING;
