INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the due process requirements expressed by this court for probation revocations are also required when the trial court revokes a defendant’s placement in a community corrections program.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we hold that the evidence rules implicated in this case—the rule against hearsay and the definitions and exceptions with respect thereto—do not apply in proceedings relating to sentencing, probation, or parole.', 'sentencing', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'conclusion that the procedural rules applicable in community corrections placement revocation hearings are the same as in probation revocation hearings, we hold that the Indiana Rules of Evidence in general and the rules against hearsay in particular do not apply in community corrections placement revocation hearings.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that in probation and community corrections placement revocation hearings, judges may consider any relevant evidence bearing some substantial indicia of reliability.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this opinion, we hold that appellate review procedures, due process requirements, and evi-dentiary rules for probation revocation and community corrections placement revocation hearings are the same.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we held that the “formal procedural and evidentiary rules required at criminal trials are not required at probation revocation hearings.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we find that the trial court accorded Defendant his rights under the Due Process Clause and the Indiana statute at each stage of the revocation proceedings.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the use in a probation revocation hearing of a regular urinalysis report prepared by a company whose professional business it is to conduct such tests does not infringe upon a probationer’s confrontation rights.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') As to the latter, we find that Defendant did not object to lack of written notice at the hearing and has failed to preserve this issue for appeal.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/853904/', '853904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that it is within the trial court’s discretion to so condition a dismissal in appropriate circumstances.', 'dismissal', 'Moniz v. Freitas', 'https://www.courtlistener.com/opinion/1387176/', '1387176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court could impose HAR Rule 26 sanctions because the order dismissing the case was a “decision rendered in a trial
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, with regard to the admission of fingerprint-related testimony on rebuttal, the circuit court did not erroneously exercise its discretion.', 'general', 'State v. Brent T. Novy', 'https://www.courtlistener.com/opinion/855157/', '855157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the circuit court''s interpretation of the statute was consistent with prior appellate decisions, and that the circuit court''s decision to allow testimony relating to fingerprint evidence on rebuttal was not an erroneous exercise of discretion.', 'general', 'State v. Brent T. Novy', 'https://www.courtlistener.com/opinion/855157/', '855157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, with regard to the admission of rebuttal fingerprint-related testimony, the circuit court did not erroneously exercise its discretion.', 'general', 'State v. Brent T. Novy', 'https://www.courtlistener.com/opinion/855157/', '855157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals.', 'general', 'State v. Brent T. Novy', 'https://www.courtlistener.com/opinion/855157/', '855157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '9 Accordingly, we affirm the circuit court''s denial of Novy''s motion to *314strike the allegedly sleeping juror from further participation in his trial.', 'general', 'State v. Brent T. Novy', 'https://www.courtlistener.com/opinion/855157/', '855157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this discussion, we hold that W.', 'general', 'State v. Wyatt', 'https://www.courtlistener.com/opinion/1343587/', '1343587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the jury instruction related to the charge of murder by failure to provide medical care was misleading and misstated the applicable law, we reverse the June 22,1995 order of the Circuit Court of Raleigh County and remand for a new trial.', 'jury_instruction', 'State v. Wyatt', 'https://www.courtlistener.com/opinion/1343587/', '1343587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a satisfactory and compelling definition has been expressed in § 2.', 'general', 'State v. Wyatt', 'https://www.courtlistener.com/opinion/1343587/', '1343587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the failure of defense trial counsel to preserve appellant’s objections, we find that State’s Instruction No.', 'general', 'State v. Wyatt', 'https://www.courtlistener.com/opinion/1343587/', '1343587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for reasons stated, we find that the giving of State’s Instruction No.', 'general', 'State v. Wyatt', 'https://www.courtlistener.com/opinion/1343587/', '1343587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While there again was no timely objection to the satanic ritual questions, we find that the evidence was irrelevant and therefore inadmissible under Rule 401, W.', 'general', 'State v. Wyatt', 'https://www.courtlistener.com/opinion/1343587/', '1343587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, given our “inherent power and paramount obligation to interpret Montana’s Constitution and to protect the various rights set forth in that document,” we held that this Court may discretionarily review “claimed errors that implicate a criminal defendant’s fundamental constitutional rights,” even if a timely objection was not made in the trial court, and notwithstanding the inapplicability of the criteria set forth in § 46-20-701(2), MCA.', 'general', 'State v. West', 'https://www.courtlistener.com/opinion/888285/', '888285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶2 We conclude that revoking West’s suspended sentence notwithstanding the 26-month delay in bringing him before the District Court implicates his due process rights.', 'sentencing', 'State v. West', 'https://www.courtlistener.com/opinion/888285/', '888285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that this issue was not properly preserved in the District Court.', 'general', 'State v. West', 'https://www.courtlistener.com/opinion/888285/', '888285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶28  Applying the “without unreasonable delay” rule to West’s situation, we conclude that he has made the requisite threshold showing that plain error review of his constitutional-based delay claim is appropriate.', 'general', 'State v. West', 'https://www.courtlistener.com/opinion/888285/', '888285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶39  For these reasons, we conclude that the factual record presently before us is not adequate for deciding West’s constitutional-based delay claim on the merits.', 'general', 'State v. West', 'https://www.courtlistener.com/opinion/888285/', '888285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our reading of the record, we find that the circumstances of the present case, although at times approaching the limits of propriety, were not sufficiently prejudicial to grant a new trial.', 'general', 'State v. Blakeney', 'https://www.courtlistener.com/opinion/2295451/', '2295451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Blakeney', 'https://www.courtlistener.com/opinion/2295451/', '2295451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the ordinance directly conflicts with the state statute.', 'general', 'State v. Reyes', 'https://www.courtlistener.com/opinion/890617/', '890617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the city ordinance that classifies possession of an open container of alcohol as a misdemeanor is in direct conflict with the state statute, which classifies possession of an open container by a passenger as an infraction.', 'general', 'State v. Reyes', 'https://www.courtlistener.com/opinion/890617/', '890617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the classification of the crime as a misdemeanor under the city ordinance is in direct conflict with the state statute, we decline to address Reyes’s additional argumerit on appeal that the ordinance is unconstitutional because it prohibits that which is specifically authorized by the state statute.', 'general', 'State v. Reyes', 'https://www.courtlistener.com/opinion/890617/', '890617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse the district court’s order and vacate Reyes’s judgment of conviction.', 'general', 'State v. Reyes', 'https://www.courtlistener.com/opinion/890617/', '890617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the district court erred in concluding the ordinance was constitutional and in denying Reyes’s motion to suppress, we reverse the order denying Reyes’s motion.', 'suppression', 'State v. Reyes', 'https://www.courtlistener.com/opinion/890617/', '890617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Glass', 'https://www.courtlistener.com/opinion/890670/', '890670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'October 19, 2006), an opinion that has not been published because the Idaho Supreme Court has granted review, we held that the 2004 amendment to Rule 30(b) precludes appellate review, even for fundamental error, of claimed flaws in jury instructions to which no objection was made in the trial court.', 'jury_instruction', 'State v. Wolfrum', 'https://www.courtlistener.com/opinion/890722/', '890722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Wolfrum', 'https://www.courtlistener.com/opinion/890722/', '890722') ON CONFLICT DO NOTHING;
