INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we conclude that there was insufficient evidence that Kalaola violated HRS § 711-1102 by failing to disperse from the second floor of ATM.', 'general', 'State v. Kalaola', 'https://www.courtlistener.com/opinion/870424/', '870424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As set forth below, we conclude that double jeopardy does not bar retrial with regard to Kalaola’s failure to disperse from the first floor, for which there was clearly sufficient evidence adduced to support a conviction.', 'general', 'State v. Kalaola', 'https://www.courtlistener.com/opinion/870424/', '870424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we conclude that the lack of substantial evidence concerning Kalaola’s failure to disperse from the second floor of ATM does not bar remand with regard to Kalaola’s failure to disperse from the first floor of ATM, for which there clearly was sufficient evidence adduced at trial.', 'general', 'State v. Kalaola', 'https://www.courtlistener.com/opinion/870424/', '870424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that there was insufficient evidence that Kalaola knowingly failed to comply with Officer Alapa’s order to disperse on the second floor, we need not address whether there was sufficient evidence concerning each of the remaining elements as to the second floor, including whether there was sufficient evidence of each of the statutory alternative means.', 'general', 'State v. Kalaola', 'https://www.courtlistener.com/opinion/870424/', '870424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “unanimity is not required where alternative means of establishing an element of an offense are submitted to the jury, provided that there is no reasonable possibility *59that the jury’s verdict was based on an alternative unsupported by sufficient evidence.', 'general', 'State v. Kalaola', 'https://www.courtlistener.com/opinion/870424/', '870424') ON CONFLICT DO NOTHING;
