INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In those cases, we held that it is improper for a trial judge to communicate with the jury without notice to, or in the absence of, counsel.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/2293324/', '2293324') ON CONFLICT DO NOTHING;
