INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the record, we conclude that the trial judge engaged the jury to resolve purely ministerial matters (e.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/2293324/', '2293324') ON CONFLICT DO NOTHING;
