INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the record does not rebut those assertions, we conclude that the trial judge did not abuse his discretion by allowing the jury access to the laptop.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/2293324/', '2293324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State presented sufficient evidence that Weber was the person seen in the surveillance video accosting Naspo.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/2293324/', '2293324') ON CONFLICT DO NOTHING;
