INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the record supports Weber’s request for a lesser included offense instruction on Offensive Touching.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/2293324/', '2293324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Patterson', 'https://www.courtlistener.com/opinion/1343569/', '1343569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the trial judge’s denial of a motion for a change of venue made on the ground that jurors in Charleston are more likely to impose the death penalty on black defendants.', 'general', 'State v. Patterson', 'https://www.courtlistener.com/opinion/1343569/', '1343569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the denial of the motion to disqualify because the defendant could not show any prejudice.', 'general', 'State v. Patterson', 'https://www.courtlistener.com/opinion/1343569/', '1343569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though the word "presumption” or one similar to it was not used in the charge in this case, and we find that State ¶.', 'general', 'State v. Stasio', 'https://www.courtlistener.com/opinion/2294408/', '2294408') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, because we further conclude that it is not reasonably likely that the erroneous admission of the domestic assault evidence had significantly affected the jury’s verdict, we hold that the error was harmless.', 'general', 'State v. Courtney', 'https://www.courtlistener.com/opinion/1657444/', '1657444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the statement was not highly persuasive.', 'general', 'State v. Courtney', 'https://www.courtlistener.com/opinion/1657444/', '1657444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that S.', 'general', 'State v. Courtney', 'https://www.courtlistener.com/opinion/1657444/', '1657444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Balancing Courtney’s right to counsel of his choice against the public interest of maintaining an efficient and effective judicial system, and in light of Courtney’s lack of diligence, we conclude that the trial court did not abuse its discretion when it denied Courtney’s motion for a continuance.', 'general', 'State v. Courtney', 'https://www.courtlistener.com/opinion/1657444/', '1657444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was.', 'general', 'State v. Courtney', 'https://www.courtlistener.com/opinion/1657444/', '1657444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that S.', 'general', 'State v. Courtney', 'https://www.courtlistener.com/opinion/1657444/', '1657444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm.', 'general', 'State v. Roderick R. Mangum', 'https://www.courtlistener.com/opinion/880838/', '880838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Wolf’s trial counsel was not ineffective for failing to file a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Wolf’s trial counsel was not ineffective for
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err in denying Wolf’s application for post-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'Wolf v. State', 'https://www.courtlistener.com/opinion/880930/', '880930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 469 (1993), we hold that it was not error to admit that evidence, and affirm Coon’s conviction.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the voice spectrograph analysis evidence was admissible under Dau-bert and the Alaska Rules of Evidence in this *403case.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Frye test potentially excludes evidence that should be admitted under our rules, and also potentially admits evidence that should be excluded under our rules, we conclude that it is both unduly restrictive and unduly permissive.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as the Supreme Court concluded in Daubert that the Frye test is inconsistent with the federal evidence rules,41 we conclude that it is inconsistent with the Alaska Rules of Evidence.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that the “more good than harm” requirement is also met.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'So arguing, APDA relies on a passage from Pulakis, where we stated that “[o]n the basis of our study of the judicial authority and academic literature in this area, we conclude that the results of polygraph examinations should not be received in evidence over objection.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in finding on remand that this technique has been subjected to empirical testing.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the findings of other courts as to the relevant scientific community for the technique of forensic voice identification using spectrography, we conclude that the trial court did not abuse its discretion in determining the relevant scientific community.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the trial court did not err in finding the voice spectrographic evidence admissible under Daubert.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bailey I we concluded that this search of Bailey’s home computer exceeded the scope of Bailey’s consent.', 'general', 'State v. Bailey', 'https://www.courtlistener.com/opinion/2294787/', '2294787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the judgment.', 'general', 'State v. Bailey', 'https://www.courtlistener.com/opinion/2294787/', '2294787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the detective’s search of Bailey’s computer and the subsequent search of his home exceeded the scope of his consent and violated the Fourth Amendment.', 'search_seizure', 'State v. Bailey', 'https://www.courtlistener.com/opinion/2294787/', '2294787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the minimum standard of culpability for involuntary manslaughter under 13 V.', 'general', 'State v. Stanislaw', 'https://www.courtlistener.com/opinion/1938400/', '1938400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Stanislaw', 'https://www.courtlistener.com/opinion/1938400/', '1938400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court of appeals erred in concluding that the district court admitted evidence of similar prior conduct.', 'general', 'State v. McCoy', 'https://www.courtlistener.com/opinion/1866848/', '1866848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that evidence of prior domestic abuse does not need to be proven by clear and convincing evidence in first-degree domestic abuse homicide cases.', 'general', 'State v. McCoy', 'https://www.courtlistener.com/opinion/1866848/', '1866848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record before us, we conclude that no evidence of the alleged prior domestic assault was ever admitted.', 'general', 'State v. McCoy', 'https://www.courtlistener.com/opinion/1866848/', '1866848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ''' ■ For these reasons, we reverse.', 'general', 'State v. McCoy', 'https://www.courtlistener.com/opinion/1866848/', '1866848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the supreme court’s decision in Barbee, supra, we conclude that the decision to revoke is indeed an adverse ruling that must be addressed by counsel in an Anders brief.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2334424/', '2334424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As Brown’s simultaneous convictions of two new felonies provided clear and overwhelming grounds for revocation, we conclude that rebriefmg will not be necessary in this instance.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2334424/', '2334424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the record and the brief presented, we conclude that there has been sufficient compliance with Rule 4-3(j) such that an appeal of Brown’s probation revocation would be wholly without merit.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2334424/', '2334424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Brown’s two convictions and revocation of probation, and based upon our review of the record, we grant her counsel’s motion to withdraw.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2334424/', '2334424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Brown’s conviction of robbery.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2334424/', '2334424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in order to interpret § 28-1205 in a manner which is consistent with its objective, we hold that the language "to commit any felony," as it is used in that section, is synonymous with "for the purpose of committing any felony.', 'general', 'State v. Ring', 'https://www.courtlistener.com/opinion/1920411/', '1920411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse the district court''s judgment with respect to the use of a deadly weapon charge and vacate that conviction, but affirm the judgment of the district court with respect to the felony motor vehicle homicide conviction.', 'general', 'State v. Ring', 'https://www.courtlistener.com/opinion/1920411/', '1920411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the motor vehicle homicide conviction, but reverse and vacate the use of a deadly weapon conviction.', 'general', 'State v. Ring', 'https://www.courtlistener.com/opinion/1920411/', '1920411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the material facts surrounding the issue of probable cause are not in dispute, this Court holds (1) it, not a jury, makes the ultimate determination of whether there was probable cause and (2) in this case, there was probable cause.', 'probable_cause', 'Quartarone v. Kohl''s Department Stores, Inc.', 'https://www.courtlistener.com/opinion/2345669/', '2345669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that allegations of the failure of the complaining witness in the criminal action to provide the magistrate and the Grand Jury with all of the facts and circumstances known to that witness at the time preceding the prosecution was sufficient to withstand a motion to dismiss brought forward by the defendant in the civil case.', 'dismissal', 'Quartarone v. Kohl''s Department Stores, Inc.', 'https://www.courtlistener.com/opinion/2345669/', '2345669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the period of pre-emption ended on October 27, 1986, the effective date of SARA, which repealed the pre-emption language in § 114(c) of CERCLA.', 'general', 'Exxon Corp. v. Hunt', 'https://www.courtlistener.com/opinion/1533455/', '1533455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this connection, we hold that reimbursement of the Spill Fund must be for the entire amount of pre-empted expenditures, and reject the State’s contention that pro-rata reimbursement proportionate to the plaintiffs’ share of Spill Act taxes is sufficient.', 'general', 'Exxon Corp. v. Hunt', 'https://www.courtlistener.com/opinion/1533455/', '1533455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that an exclusively prospective application of the Court’s decision is inappropriate under these circumstances.', 'general', 'Exxon Corp. v. Hunt', 'https://www.courtlistener.com/opinion/1533455/', '1533455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that under these unique circumstances the appropriate remedy in this matter is that which best implements the intent of Congress in adopting SARA and the intent of the Legislature in adopting and amending the Spill Act.', 'general', 'Exxon Corp. v. Hunt', 'https://www.courtlistener.com/opinion/1533455/', '1533455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a period of six months from the final determination of the amount of pre-empted expenditures, from which no appeal is pending or can be taken, is sufficient for the Legislature to take action to reimburse the fund.', 'general', 'Exxon Corp. v. Hunt', 'https://www.courtlistener.com/opinion/1533455/', '1533455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we affirmed the judgment of the Appellate Division upholding the Tax Court’s determination that the tax imposed by the New Jersey Spill Compensation and Control Act, A.', 'general', 'Exxon Corp. v. Hunt', 'https://www.courtlistener.com/opinion/1533455/', '1533455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the circuit court correctly interpreted Md.', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/2353145/', '2353145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing this evidence in a light most favorable to the State, we find that a rational fact-finder could find each element of section 8-301 (c) to be satisfied beyond a reasonable doubt.', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/2353145/', '2353145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no error in the circuit court’s interpretation of the statute, and we find the evidence sufficient to support the guilty verdict, we affirm appellant’s convictions.', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/2353145/', '2353145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When we apply this rule to the language at issue, we conclude that the words "a conviction" plainly indicate one conviction.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/2110229/', '2110229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the words "a conviction" indicate that the defendant''s third offense of domestic battery must occur within ten years of only one of the defendant''s prior domestic violence convictions in order to enhance the third offense to a felony.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/2110229/', '2110229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 90 (1967), we held that even in a semi-public or public building one does not have a right to enter areas which are obviously not open to the public simply because there is no sign or warning forbidding entry as under such circumstances there is an implied warning not to enter.', 'general', 'Bond v. United States', 'https://www.courtlistener.com/opinion/2353930/', '2353930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these criteria, we find that appellant has made no showing of prejudice or even a reasonable possibility thereof.', 'general', 'Bond v. United States', 'https://www.courtlistener.com/opinion/2353930/', '2353930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Trial Judge proceeded properly on the lesser charge.', 'general', 'Bilinski v. State', 'https://www.courtlistener.com/opinion/2374390/', '2374390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bilinski v. State', 'https://www.courtlistener.com/opinion/2374390/', '2374390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4]  "We hold that finding error in the court''s charge to the jury beginsnot endsthe inquiry;', 'general', 'Posey v. State', 'https://www.courtlistener.com/opinion/2377590/', '2377590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statute embodies two standards of review.', 'general', 'Posey v. State', 'https://www.courtlistener.com/opinion/2377590/', '2377590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and affirm the trial court''s judgment.', 'general', 'Posey v. State', 'https://www.courtlistener.com/opinion/2377590/', '2377590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error we affirm.', 'general', 'Tarentino v. State', 'https://www.courtlistener.com/opinion/2381654/', '2381654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s denial of a directed verdict if there is substantial evidence to support the conviction.', 'general', 'Tarentino v. State', 'https://www.courtlistener.com/opinion/2381654/', '2381654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the victim’s awareness of the theft is a necessary element of robbery pursuant to HRS § 708-840(l)(b)(ii).', 'general', 'State v. Mitsuda', 'https://www.courtlistener.com/opinion/1195129/', '1195129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, for the reasons stated below, we agree with Mitsu-da’s second contention,4 we reverse Mitsuda’s conviction and sentence with respect to Count II, Robbery in the First Degree.', 'sentencing', 'State v. Mitsuda', 'https://www.courtlistener.com/opinion/1195129/', '1195129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Mitsuda’s conviction and sentence for Count II, Robbery in the First Degree.', 'sentencing', 'State v. Mitsuda', 'https://www.courtlistener.com/opinion/1195129/', '1195129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we reverse Mitsuda’s sentence for Robbery in the First Degree, we agree with Mitsuda that, pursuant to HRS §§ 706 — 606.', 'sentencing', 'State v. Mitsuda', 'https://www.courtlistener.com/opinion/1195129/', '1195129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we reverse Mitsuda’s conviction and sentence with respect to Count II, Robbery in the First Degree.', 'sentencing', 'State v. Mitsuda', 'https://www.courtlistener.com/opinion/1195129/', '1195129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such a result is in direct conflict with the language of the statute and is therefore impermissible.', 'general', 'Phelps v. State', 'https://www.courtlistener.com/opinion/2383062/', '2383062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, normally, a composite sentence exceeding 10 years was permissible only when the offender “ha[d] previously been convicted of [felonies] for which a sentence [of] at least one full year of incarceration was imposed.', 'sentencing', 'Phelps v. State', 'https://www.courtlistener.com/opinion/2383062/', '2383062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, the supreme court disapproved of this Court’s prior decisions in which we held that, among the sentencing goals codified in AS 12.', 'sentencing', 'Phelps v. State', 'https://www.courtlistener.com/opinion/2383062/', '2383062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'severe sentence”, but we held that Hodari’s composite sentence could not exceed 40 years to serve because “we have approved composite terms of forty years or more only for violent crimes committed by offenders with backgrounds that included habitual criminality or repeated acts of criminal violence” — criteria that were not present in Ho-dari’s background.', 'sentencing', 'Phelps v. State', 'https://www.courtlistener.com/opinion/2383062/', '2383062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though Wentz had an extensive misdemeanor record, and even though the sentencing judge found (based on prior failed attempts at rehabilitation) that Wentz was a dangerous offender who needed to be isolated to protect the public, this Court held that the 10-year ceiling applied to Wentz’s composite sentence because Wentz had no felony record.', 'sentencing', 'Phelps v. State', 'https://www.courtlistener.com/opinion/2383062/', '2383062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we explain in more detail in this opinion, we conclude that the facts of this case provide sufficient justification for imposing a more severe composite sentence than the 1-year
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And given the facts of the present case (as found by the district court), we conclude that the district court had a compelling justification for imposing a sentence exceeding 1 year to serve.', 'sentencing', 'Phelps v. State', 'https://www.courtlistener.com/opinion/2383062/', '2383062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And, given the totality of Phelps’s conduct, we conclude that Phelps’s composite sentence of 545 days to serve is not clearly mistaken.', 'sentencing', 'Phelps v. State', 'https://www.courtlistener.com/opinion/2383062/', '2383062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we conclude that it was plain error to deny suppression of such statements we must reverse and remand for a new trial.', 'suppression', 'Wainwright v. State', 'https://www.courtlistener.com/opinion/2382336/', '2382336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the defendant’s initial statement to Detective Griffith made outside the Magistrate’s Court was an elicited response to a statement made by a policeman which was reasonably likely to produce such a response.', 'general', 'Wainwright v. State', 'https://www.courtlistener.com/opinion/2382336/', '2382336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the defendant’s statements to Detective Griffith are rendered inadmissible by reason of the violations of his right to counsel under the Fifth Amendment, we decline to address his claim that his Sixth Amendment right to counsel is equally implicated.', 'general', 'Wainwright v. State', 'https://www.courtlistener.com/opinion/2382336/', '2382336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure to give a limiting instruction was not plain error.', 'general', 'Wortham v. State', 'https://www.courtlistener.com/opinion/1432263/', '1432263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming that there was a discovery violation, we conclude that on this record Wort-ham has forfeited any right to relief.', 'general', 'Wortham v. State', 'https://www.courtlistener.com/opinion/1432263/', '1432263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s final argument was not unduly prejudicial.', 'general', 'Wortham v. State', 'https://www.courtlistener.com/opinion/1432263/', '1432263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances we conclude that the sentence was not clearly mistaken.', 'sentencing', 'Wortham v. State', 'https://www.courtlistener.com/opinion/1432263/', '1432263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984) we found that a trial judge abused his discretion in refusing to consider a suppression motion which was filed after the omnibus hearing was scheduled.', 'suppression', 'Wortham v. State', 'https://www.courtlistener.com/opinion/1432263/', '1432263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with those contentions and, accordingly, we reverse and dismiss.', 'dismissal', 'Limited Stores, Inc. v. Wilson-Robinson', 'https://www.courtlistener.com/opinion/2455849/', '2455849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we affirmed.', 'general', 'Limited Stores, Inc. v. Wilson-Robinson', 'https://www.courtlistener.com/opinion/2455849/', '2455849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that, where a governmental agent is engaged in a lawful intrusion and inadvertently observes evidence of a crime, the seizure of such evidence does not require any further constitutional protection.', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not err in denying Jenkins’s motion to suppress evidence.', 'suppression', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in failing to instruct the jury regarding all of the material elements of the offense.', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we hold that, for the purposes of HRS § 134-7(b), “possession” must be analyzed employing a two-pronged analysis: (1) the voluntary act of “possession” of an object itself is, by way of HRS § 702-202, satisfied where an individual acts knowingly with respect to his or her conduct;', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'l, we hold that, for the purposes of HRS § 134-6(e), “carry” must be analyzed employing a two-pronged analysis: *113(1) the voluntary act of “carrying” an object is, by way of HRS § 702-202, established when an individual acts knowingly with respect to that conduct;', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Jenkins’s sentence did not violate the eighth amendment to the United States Constitution or article I, section 12 of the Hawai''i Constitution.', 'sentencing', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon consideration of the circumstances in this case, we conclude that this description is unduly broad and fails to comport with the constitutional requirement of particularity.', 'general', 'Namen v. State', 'https://www.courtlistener.com/opinion/1359960/', '1359960') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence seized as a result of the warrant authorizing the search of Namen’s residence for stolen jewelry must be suppressed.', 'suppression', 'Namen v. State', 'https://www.courtlistener.com/opinion/1359960/', '1359960') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 221 (1997), we held that generally "[t]he Supreme Court of Appeals reviews sentencing orders.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/1248820/', '1248820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 851, 857 (1983), we held that "[t]here are two tests to determine whether a sentence is so disproportionate to a crime that it violates our constitution.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/1248820/', '1248820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the sentence of 45 years for aggravated robbery on the grounds that the sentence shocked the conscience.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/1248820/', '1248820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the parties'' arguments on appeal, the record designated for appellate review, and the pertinent authorities, we affirm the decision of the Circuit Court of Putnam County.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1248820/', '1248820') ON CONFLICT DO NOTHING;
