INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was sufficient evidence before the trial court to support its finding that the State proved beyond a reasonable doubt that Krempetz intentionally killed Keim while committing or attempting to commit robbery.', 'general', 'Michael Inman v. State of Indiana', 'https://www.courtlistener.com/opinion/2653485/', '2653485') ON CONFLICT DO NOTHING;
