INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “where a prospective juror is a prosecutor currently employed by the same office as the prosecutor trying the defendant, the court shall imply bias as a matter of law and dismiss the prospective juror for cause.', 'dismissal', 'State v. Richie', 'https://www.courtlistener.com/opinion/1198898/', '1198898') ON CONFLICT DO NOTHING;
