INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under article I, section 10 of the Hawai''i Constitution, a reviewing court is required to address an express claim of insufficiency of the evidence prior to remanding for a new trial based on a defective charge.', 'general', 'State v. Davis.', 'https://www.courtlistener.com/opinion/2654848/', '2654848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that where a defendant expressly claims both a charging error and insufficient evidence to support the conviction, the reviewing court is required under article I, section 10 of the Hawai''i Constitution to examine the sufficiency of the evidence claim before vacating the conviction and remanding for a new trial based on the charging error.', 'general', 'State v. Davis.', 'https://www.courtlistener.com/opinion/2654848/', '2654848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that sufficient evidence was presented to establish that the defendant failed to disperse from the first floor of the subject building, but that there was insufficient evidence to establish that he failed to disperse from the second floor.', 'general', 'State v. Davis.', 'https://www.courtlistener.com/opinion/2654848/', '2654848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of the sufficiency of the evidence, we conclude that substantial evidence supported the conviction, and therefore double jeopardy does not preclude a retrial.', 'general', 'State v. Davis.', 'https://www.courtlistener.com/opinion/2654848/', '2654848') ON CONFLICT DO NOTHING;
