INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although a number of prospective jurors had read or heard about the case, we conclude that, in light of the totality of the circumstances, a reasonable likelihood does not exist that pretrial publicity prevented defendant from receiving a fair trial in Randolph County.', 'general', 'State v. Trull', 'https://www.courtlistener.com/opinion/1239434/', '1239434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err by refusing to grant defendant’s motion for change of venue, and this assignment of error is overruled.', 'general', 'State v. Trull', 'https://www.courtlistener.com/opinion/1239434/', '1239434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments and sentences.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1434329/', '1434329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the trial court properly instructed the jmy on the two statutory elements of the offense of robbery in the second degree as set forth in HRS § 708-841 and that the trial court’s presentation of the material elements of the offense in two, rather than three, parts was not prejudicially insufficient, erroneous, misleading or inconsistent.', 'general', 'State v. Iuli', 'https://www.courtlistener.com/opinion/2625903/', '2625903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, this court held that the trial court committed an abuse of discretion in failing to excuse the prospective juror in light of his employment and that the trial court’s error foreclosed the defendant from peremptorily challenging at least one of two additional prospective jurors.', 'general', 'State v. Iuli', 'https://www.courtlistener.com/opinion/2625903/', '2625903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm the trial court’s judgment.', 'general', 'State v. Iuli', 'https://www.courtlistener.com/opinion/2625903/', '2625903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm the judgment of conviction and sentence of the trial court.', 'sentencing', 'State v. Iuli', 'https://www.courtlistener.com/opinion/2625903/', '2625903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1993) this court held the state complied with the licensed medical personnel determination requirement of section 56-5-2950(a).', 'general', 'Peake v. South Carolina Department of Motor Vehicles', 'https://www.courtlistener.com/opinion/1268174/', '1268174') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reading the statute as a whole, this court held “the statute requires a licensed physician, licensed registered nurse, or other medical personnel trained to take blood samples .', 'general', 'Peake v. South Carolina Department of Motor Vehicles', 'https://www.courtlistener.com/opinion/1268174/', '1268174') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Peake v. South Carolina Department of Motor Vehicles', 'https://www.courtlistener.com/opinion/1268174/', '1268174') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Lee-Grigg', 'https://www.courtlistener.com/opinion/1324013/', '1324013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the statute discussed above and relevant case law, we conclude that no ambiguity should remain regarding this issue.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1392139/', '1392139') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the Court of Appeals which vacated the activation of defendant’s sentence for her conviction of obtaining property by false pretenses.', 'sentencing', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1392139/', '1392139') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, unless the statute describing the offense explicitly sets out a maximum sentence, the statutory maximum sentence for a criminal offense in North Carolina is that which results from: (1) findings that the defendant falls into the highest criminal history category for the applicable class offense and that the offense was aggravated, followed by (2) a decision by the sentencing court to impose the highest possible corresponding minimum sentence from the ranges presente...', 'sentencing', 'State v. Lucas', 'https://www.courtlistener.com/opinion/1328912/', '1328912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that in every instance where the State
