INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that under a plain error analysis, “[i]n light of the highly conflicting evidence in the instant kidnapping case on the unlawful removal and restraint issues, we think the instructional error might have .', 'general', 'State v. Lucas', 'https://www.courtlistener.com/opinion/1328912/', '1328912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite the court’s erroneous use of the phrases “should have known” and “reasonable grounds to believe,” we conclude that the instructions as a whole conveyed that under the theory of aiding and abetting, Mitchell had to have the specific intent to kill the victim;', 'general', 'State v. Lucas', 'https://www.courtlistener.com/opinion/1328912/', '1328912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a different result would not have been reached had the trial court instructed on confinement rather than removal and hold that the erroneous instructions do not constitute prejudicial error.', 'general', 'State v. Lucas', 'https://www.courtlistener.com/opinion/1328912/', '1328912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noles for the purpose of terrorizing her,” we concluded that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the error was not prejudicial.', 'general', 'State v. Lucas', 'https://www.courtlistener.com/opinion/1328912/', '1328912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the Court of Appeals as to the issue raised by the State.', 'general', 'State v. Lucas', 'https://www.courtlistener.com/opinion/1328912/', '1328912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, the Court of Appeals erred in holding that the trial court’s instructions were improper, and we reverse the decision of the Court of Appeals.', 'general', 'State v. Lucas', 'https://www.courtlistener.com/opinion/1328912/', '1328912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the nonsectarian, nonprofit hospital which held out the use of its facilities to the general public assumed quasi -pub-*581lie obligations akin to those assumed by common carriers and innkeepers at common law.', 'general', 'State v. Schmid', 'https://www.courtlistener.com/opinion/2000388/', '2000388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, viewing the evidence in the light most favorable to the verdict, a rational fact finder could conclude that appellant knowingly possessed cocaine.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1665161/', '1665161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that due process and equal protection are not violated by prosecution of knowing possession of minute amounts of cocaine.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1665161/', '1665161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1665161/', '1665161') ON CONFLICT DO NOTHING;
