INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we hold that the court did not abuse its discretion in sustaining the government’s objection to defense counsel’s question about drug abuse.', 'general', 'Williams v. United States', 'https://www.courtlistener.com/opinion/1435329/', '1435329') ON CONFLICT DO NOTHING;
