INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, relying on such cases as
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Supreme Court had held that the defense had "a right to be heard in summation of the evidence,” we reversed the conviction and remanded the case for a new trial.', 'general', 'Williams v. United States', 'https://www.courtlistener.com/opinion/1435329/', '1435329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reversed a conviction of first-degree theft, remanding the case with directions to reduce the charge to second-degree theft, because there was no proof of either the condition of the stolen items (several pieces of furniture) or their rate of depreciation.', 'general', 'Williams v. United States', 'https://www.courtlistener.com/opinion/1435329/', '1435329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find no merit in these arguments, and thus we affirm the judgment of conviction.', 'general', 'Williams v. United States', 'https://www.courtlistener.com/opinion/1435329/', '1435329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'denying Coleman''s request to instruct the jury on privilege, and, if so, is the error harmless? We hold that a narrow defense of privilege, which originates from
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that a narrow defense of privilege exists to a charge of felon in possession of a firearm.', 'general', 'State v. Coleman', 'https://www.courtlistener.com/opinion/1346453/', '1346453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a defense of privilege applies to § 941.', 'general', 'State v. Coleman', 'https://www.courtlistener.com/opinion/1346453/', '1346453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, we conclude that Coleman presented sufficient evidence in support of the defense of privilege.', 'general', 'State v. Coleman', 'https://www.courtlistener.com/opinion/1346453/', '1346453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a reasonable possibility exists that the error contributed to the conviction.', 'general', 'State v. Coleman', 'https://www.courtlistener.com/opinion/1346453/', '1346453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that recognizing a defense of legal justification does not necessarily conflict with the concept that violation of a traffic law is a strict liability offense.', 'general', 'State v. Coleman', 'https://www.courtlistener.com/opinion/1346453/', '1346453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we conclude that even though violation of § 941.', 'general', 'State v. Coleman', 'https://www.courtlistener.com/opinion/1346453/', '1346453') ON CONFLICT DO NOTHING;
