INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State failed to establish a prima facie case because defendant''s conduct conveyed neither the physical nor imminent threat of harm that we construe the definition of "threatening behavior" to require.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that [the statute] makes unlawful only the use of physical force or *828physical conduct which is immediately likely to produce the use of such force and which is intended to create or recklessly creates a risk of public inconvenience, annoyance or alarm.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we hold that the State has not demonstrated that it *834has a prima facie case that defendant violated 13 V.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we held that "threatening behavior" creates an objective standard-whether a reasonable person would conclude a defendant''s conduct was threatening-not a subjective standard-whether the recipient of a defendant''s allegedly threatening behavior perceived that behavior as a threat.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Sanville, we held that this probation condition was impermissibly vague as applied to the charged violation in that case.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the probationer could not have had notice that his behavior would violate the condition prohibiting threatening behavior because his behavior did not meet our caselaw''s standard for threatening behavior-the behavior "did not necessarily ''communicate intent to inflict physical or other harm.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Albarelli, we held that the disorderly conduct statute proscribing threatening behavior "proscribes conduct, not speech, and therefore does not penalize speech.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the language of [the disorderly conduct statute] involved in this case, namely, "violent or threatening behavior," evinces a legislative intent to proscribe conduct which actually involves physical violence or portends imminent physical violence.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Also as in Johnstone, we concluded that the trial court could not find that the defendant intended to put the target of the threat in fear of bodily harm because the defendant was delusional and there was no evidence that the target existed or that the threat was real.', 'general', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and grant defendant''s motion to dismiss.', 'dismissal', 'State v. William Schenk', 'https://www.courtlistener.com/opinion/4495433/', '4495433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Far from questioning the value of deterrence, in Pugh we held that the deterrence objective of sentencing is “particularly compelling in the child pornography context.', 'sentencing', 'United States v. Irey', 'https://www.courtlistener.com/opinion/151874/', '151874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, in Weir, we held that Jones was satisfied because “[t]he district court clearly understood the Government''s position and specifically rejected it.', 'general', 'United States v. Irey', 'https://www.courtlistener.com/opinion/151874/', '151874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2003) (“We conclude that the district court overlooked some highly relevant factors, and that it ultimately struck a balance that was an abuse of discretion.', 'general', 'United States v. Irey', 'https://www.courtlistener.com/opinion/151874/', '151874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Exercising that review, we conclude that the district court made a clear error of judgment in downplaying the importance of deterring this type of crime.', 'general', 'United States v. Irey', 'https://www.courtlistener.com/opinion/151874/', '151874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the guidelines sentences for child pornography crimes, which reflect judgments by both Congress and the Sentencing Commission as to the seriousness of the offense and the risk of recidivism, “do not exhibit the deficiencies the Supreme Court identified [in the crack cocaine guidelines] in Kimbrough.', 'sentencing', 'United States v. Irey', 'https://www.courtlistener.com/opinion/151874/', '151874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we have explained, “under the abuse of discretion standard of review there will be occasions in which we affirm the district court even though we would have gone the other way had it been our call.', 'general', 'United States v. Irey', 'https://www.courtlistener.com/opinion/151874/', '151874') ON CONFLICT DO NOTHING;
