INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the appellant’s claim could be resolved on the basis of the existing record and that the trial court was fully justified in denying the appellant’s motion for new trial without recourse to further factual development in an eviden-tiary hearing.', 'general', 'Gonzales v. State', 'https://www.courtlistener.com/opinion/1762748/', '1762748') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In so doing, we reverse only when the trial judge’s decision was so clearly wrong as to lie outside that zone within which reasonable persons might disagree.', 'general', 'Gonzales v. State', 'https://www.courtlistener.com/opinion/1762748/', '1762748') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When the State petitioned this Court for discretionary review, we reversed.', 'general', 'Gonzales v. State', 'https://www.courtlistener.com/opinion/1762748/', '1762748') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals to the extent that it set aside Count II of the indictment.', 'general', 'Gonzales v. State', 'https://www.courtlistener.com/opinion/1762748/', '1762748') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals insofar as it affirmed the appellant’s conviction with respect to Count I of the indictment.', 'general', 'Gonzales v. State', 'https://www.courtlistener.com/opinion/1762748/', '1762748') ON CONFLICT DO NOTHING;
