INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '42, we found that the Legislature’s use of the two terms in both Subsections (a)(1) and (a)(2) evinced its intent “to treat commission of a state jail felony after repeated commission of only other state jail felonies differently than commission of a state jail felony after repeated commission of more serious offenses.', 'general', 'Tapps v. State', 'https://www.courtlistener.com/opinion/1789187/', '1789187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '04(a)(1) includes state-jail felonies, we affirm the court of appeals’s holding that the appellant’s state-jail-felony conviction is legally sufficient to support his conviction.', 'general', 'Tapps v. State', 'https://www.courtlistener.com/opinion/1789187/', '1789187') ON CONFLICT DO NOTHING;
