INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the record, we reverse the judgment of the court of appeals and remand this case for a full harm analysis.', 'general', 'Barshaw v. State', 'https://www.courtlistener.com/opinion/2538725/', '2538725') ON CONFLICT DO NOTHING;
