INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1137101/', '1137101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '48(a)(2) the court had the power to dismiss, and as its holding that count II was a lesser included offense of count I was correct, as hereinafter discussed, we hold that the court was correct in ordering the dismissal.', 'dismissal', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1137101/', '1137101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the above principles, we hold that the court was correct in not applying the provisions of I.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1137101/', '1137101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hahn, supra, we hold that only the person who actually Used the gun can be subjected to the enhancement provisions of I.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1137101/', '1137101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that violation of our prison breach statute constitutes a continuing offense.', 'general', 'Craig v. United States', 'https://www.courtlistener.com/opinion/1976789/', '1976789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that prison breach is a continuing offense;', 'general', 'Craig v. United States', 'https://www.courtlistener.com/opinion/1976789/', '1976789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Craig v. United States', 'https://www.courtlistener.com/opinion/1976789/', '1976789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Laase is both an owner and the offender, we hold that the "innocent owner" defense does not apply, and that the *440 vehicle was properly forfeitable under section 169A.', 'general', 'Laase v. 2007 Chevrolet Tahoe', 'https://www.courtlistener.com/opinion/1271753/', '1271753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bosshart, we held that the application of the relevant canon in section 645.', 'general', 'Laase v. 2007 Chevrolet Tahoe', 'https://www.courtlistener.com/opinion/1271753/', '1271753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we held that the lack of a logical relationship rendered the application of the canon repugnant in Bosshart, we did not define repugnancy or discuss the requirements of the repugnancy standard.', 'general', 'Laase v. 2007 Chevrolet Tahoe', 'https://www.courtlistener.com/opinion/1271753/', '1271753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the defense is not available, we reverse.', 'general', 'Laase v. 2007 Chevrolet Tahoe', 'https://www.courtlistener.com/opinion/1271753/', '1271753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we conclude that it is not inconsistent with the legislature''s intent or repugnant to the context of the statute to apply the singular-includes-the-plural canon to the innocent owner defense.', 'general', 'Laase v. 2007 Chevrolet Tahoe', 'https://www.courtlistener.com/opinion/1271753/', '1271753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Among other things, we conclude that text messages are intrinsic to the cellular telephones in which they are stored.', 'general', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the text messages at issue here are part and parcel of the cellular telephone in which they were stored, just as pages in a book belong to the book by their very nature, and thus they are intrinsic to the telephone.', 'general', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the evidence presented to the jury, we conclude that there is not a substantial possibility that the text messages prejudiced the verdict.', 'general', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any error caused by the State''s question was cured by the stipulation read to the jury by the trial court.', 'general', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this testimony, and absent any evidence that the trial court engaged in any impermissible considerations, we conclude that the trial court did not abuse its discretion in failing to recognize Hape''s alleged remorse as a significant mitigating cireumstance.', 'general', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, the State concedes that the evidence is insufficient to support his habitual offender adjudication, and we reverse the trial court''s finding in this regard and remand for the trial court to vacate Hape''s thirty-year habitual offender sentencing enhancement.', 'sentencing', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reduced Hape''s sentence to fifty years because we reverse his habitual offender finding, as a matter of judicial efficiency, we now address the question of whether fifty years is an inappropriate sentence.', 'sentencing', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Hape''s convictions for possessing methamphetamine and resisting law enforcement.', 'general', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Hape v. State', 'https://www.courtlistener.com/opinion/2020514/', '2020514') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we note that although Elston expresses concern that she may be placed in the untenable position of arguing her own ineffectiveness on appeal, we find that Wright, by agreeing to proceed pro se and explicitly warning Elston to not interfere in bis trial, has waived any ineffective assistance claim for purposes of appeal.', 'ineffective_assistance', 'Wright v. State', 'https://www.courtlistener.com/opinion/2045024/', '2045024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the trial court did not abuse its discretion in denying Elston''s motion to withdraw as Wright''s appointed appellate counsel.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2045024/', '2045024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the district court’s denial of Weaver’s motion to suppress the evidence discovered in the war-rantless search.', 'suppression', 'State v. Weaver', 'https://www.courtlistener.com/opinion/1158307/', '1158307') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he received effective assistance of counsel and affirm the trial court.', 'general', 'Whitener v. State', 'https://www.courtlistener.com/opinion/2052686/', '2052686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1374 (1980), this Court held that a defendant convicted of accessory before the fact to felony murder under Ind.', 'general', 'Whitener v. State', 'https://www.courtlistener.com/opinion/2052686/', '2052686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the defendant was not entitled to the defense because, even if he had tried to dissuade the other man from proceeding further, he did not prevent the commission of the crime.', 'general', 'Whitener v. State', 'https://www.courtlistener.com/opinion/2052686/', '2052686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Superior Court neither erred nor abused its discretion.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2052708/', '2052708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our review of the factual record and the contentions of the parties, we hold that the trial court’s judgment is correct and should not be disturbed on appeal.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2052708/', '2052708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that, since the reduction in sentence was mandatory under the applicable statute, the defendants need not be present.', 'sentencing', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2052708/', '2052708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the Superior Court’s holding in regard to this statement was correct.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2052708/', '2052708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court’s ruling is well founded in the evidence and Dawson has provided no basis for a finding of abuse of discretion.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2052708/', '2052708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we AFFIRM the Superior Court’s decision denying Dawson’s requested post-conviction relief and reinstating Dawson’s capital sentence.', 'sentencing', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2052708/', '2052708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the district court.', 'general', 'State v. Neuzil', 'https://www.courtlistener.com/opinion/2066834/', '2066834') ON CONFLICT DO NOTHING;
