INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we have found three aggravating and no mitigating factors, we find that the death sentence was properly imposed.', 'sentencing', 'State v. Michael Apelt', 'https://www.courtlistener.com/opinion/1158223/', '1158223') ON CONFLICT DO NOTHING;
