INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the evidence was insufficient to authorize a rational trier of fact to find Beckom guilty beyond a reasonable doubt of the offense of obstruction of an officer.', 'general', 'Beckom v. State', 'https://www.courtlistener.com/opinion/1231339/', '1231339') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Because we conclude that the state did not present any evidence as to an essential element of this crime,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we reverse her conviction under Count 2.', 'general', 'Beckom v. State', 'https://www.courtlistener.com/opinion/1231339/', '1231339') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse.', 'general', 'Beckom v. State', 'https://www.courtlistener.com/opinion/1231339/', '1231339') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse her conviction under Count 3 for maintaining a disorderly house.', 'general', 'Beckom v. State', 'https://www.courtlistener.com/opinion/1231339/', '1231339') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as to Count 1 and reverse as to Counts 2 and 3.', 'general', 'Beckom v. State', 'https://www.courtlistener.com/opinion/1231339/', '1231339') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this appeal is controlled by Humbert and Johnson.', 'general', 'State v. Huff', 'https://www.courtlistener.com/opinion/1272376/', '1272376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, but for reasons different from those upon which the district court based its decision.', 'general', 'State v. Huff', 'https://www.courtlistener.com/opinion/1272376/', '1272376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed, we affirm the order of the district court overruling Huff''s plea in bar and remand for further proceedings.', 'plea', 'State v. Huff', 'https://www.courtlistener.com/opinion/1272376/', '1272376') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find no reversible error, and we affirm the judgment of the lower court.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/1238587/', '1238587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no substantial reasons tending to impair the trial judge’s impartiality, we affirm his decision not to recuse himself.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/1238587/', '1238587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without deciding whether the State indeed violated any discovery orders, we conclude that the failure of the witnesses to appear did not prejudice defendant.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1251302/', '1251302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any error was harmless beyond a reasonable doubt.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1251302/', '1251302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under Iowa Rule of Evidence 403, the probative value of the evidence of gang activity was not outweighed by the danger of unfair prejudice to defendant.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1251302/', '1251302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has not established ineffective assistance by his trial counsel.', 'ineffective_assistance', 'State v. Smith', 'https://www.courtlistener.com/opinion/1251302/', '1251302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and sentences entered by the district court upon defendant Smith’s convictions of assault with intent to inflict serious injury and terrorism.', 'sentencing', 'State v. Smith', 'https://www.courtlistener.com/opinion/1251302/', '1251302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State need only prove that element of the offense by a showing of constructive knowledge on the part of the defendant.', 'general', 'State v. Sidway', 'https://www.courtlistener.com/opinion/2385733/', '2385733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the actual knowledge of impact may be proven either by means of direct or circumstantial evidence.', 'general', 'State v. Sidway', 'https://www.courtlistener.com/opinion/2385733/', '2385733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, because the Clerk violated the injunction each time he collected the court reporter fee or the sheriff fee, the trial court could assess multiple fines.', 'general', 'In Re Long', 'https://www.courtlistener.com/opinion/2387416/', '2387416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this instance, we conclude that it was proper for the prosecution to rebut a defense counsel argument that certain evidence should be regarded as a mitigating circumstance.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the issue is without merit.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since this would lead to an improper result, we conclude that the testimony of Evans was properly excluded.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the omission of signature lines under all three options was not reversible error.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Davis did not make any request for special venire prior to trial, we find that the trial court was not in error for denying his motion to quash the regular venire.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was no showing of abuse of discretion, we find that the assignment of error is without merit.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court did not abuse its discretion in the case sub judice because the prosecution''s voir dire was within the permissible range of acceptable questioning.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no other portion of the closing arguments to this effect, we find that the comments by the State were isolated and do not warrant a reversal.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this issue is procedurally barred.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') Although we are not required to address this issue, we find that this issue is meritless.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1868563/', '1868563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand with instructions.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/2481120/', '2481120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand with instructions to vacate Thomas''s conviction for invasion of privacy as a class A misdemeanor and, at the trial court''s option, to resume direct contempt proceedings[3] to address Thomas''s comment to Smith at the November 16, 2009 hearing.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/2481120/', '2481120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction unless "no reasonable fact-finder could find the elements of the crime proven beyond a reasonable doubt.', 'general', 'Thomas v. State', 'https://www.courtlistener.com/opinion/2481120/', '2481120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury’s verdicts are merely inconsistent.', 'general', 'State v. Mumford', 'https://www.courtlistener.com/opinion/2396985/', '2396985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did err in its award of restitution but that the error was not prejudicial.', 'general', 'State v. Mumford', 'https://www.courtlistener.com/opinion/2396985/', '2396985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that the trial court erred in ordering restitution, but find that the error was not prejudicial.', 'general', 'State v. Mumford', 'https://www.courtlistener.com/opinion/2396985/', '2396985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the opinion of the Court of Appeals on these issues and remand the case to the Court of Appeals for consideration of assignments of error not addressed in that court’s initial opinion.', 'general', 'State v. Mumford', 'https://www.courtlistener.com/opinion/2396985/', '2396985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals vacating the portion of the trial court’s judgment ordering payment of restitution.', 'general', 'State v. Mumford', 'https://www.courtlistener.com/opinion/2396985/', '2396985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons we reverse the decision of the Court of Appeals vacating defendant’s convictions for felony serious injury by vehicle.', 'general', 'State v. Mumford', 'https://www.courtlistener.com/opinion/2396985/', '2396985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the Court of Appeal’s decision vacating that portion of the judgment.', 'general', 'State v. Mumford', 'https://www.courtlistener.com/opinion/2396985/', '2396985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the entire record, we conclude that the trial judge did not abuse his discretion by permitting Sally Keefer to testify regarding R.', 'general', 'State v. Jessica Jane M.', 'https://www.courtlistener.com/opinion/2397848/', '2397848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After thorough review of the briefs, the legal authority cited and the record presented for consideration, we find that the circuit court committed no reversible error and therefore affirm the judgment of conviction and sentencing order.', 'sentencing', 'State v. Jessica Jane M.', 'https://www.courtlistener.com/opinion/2397848/', '2397848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that the trial court did not commit error.', 'general', 'State v. Jessica Jane M.', 'https://www.courtlistener.com/opinion/2397848/', '2397848') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, pursuant to our supervisory authority, we hold that prosecutors are prohibited from making generic accusations of tailoring during summation.', 'general', 'State v. Daniels', 'https://www.courtlistener.com/opinion/2402131/', '2402131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the prosecutor’s comments were improper, we now reverse defendant’s conviction and remand for a new trial.', 'general', 'State v. Daniels', 'https://www.courtlistener.com/opinion/2402131/', '2402131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the framework established above, we conclude that the summation in this matter was improper.', 'general', 'State v. Daniels', 'https://www.courtlistener.com/opinion/2402131/', '2402131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the charge did not.', 'general', 'State v. Daniels', 'https://www.courtlistener.com/opinion/2402131/', '2402131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the prosecutor’s comments were unfairly prejudicial to defendant.', 'general', 'State v. Daniels', 'https://www.courtlistener.com/opinion/2402131/', '2402131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the decision of the Appellate Division and remand for a new trial consistent with this opinion.', 'general', 'State v. Daniels', 'https://www.courtlistener.com/opinion/2402131/', '2402131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that while the doctrine of parental immunity is a bar to a suit alleging negligent supervision, it does not protect a parent who has willfully or wantonly failed to watch over his or her child.', 'general', 'Foldi v. Jeffries', 'https://www.courtlistener.com/opinion/2404696/', '2404696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that an unemancipated child could sue his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there are such reasons.', 'general', 'Foldi v. Jeffries', 'https://www.courtlistener.com/opinion/2404696/', '2404696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the doctrine of parental immunity will continue to preclude liability in cases of negligent supervision, but not for a parent’s willful or wanton failure to supervise his or her children.', 'general', 'Foldi v. Jeffries', 'https://www.courtlistener.com/opinion/2404696/', '2404696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “it is entirely evident that under the pertinent modern legal concepts the [child’s action] .', 'general', 'Foldi v. Jeffries', 'https://www.courtlistener.com/opinion/2404696/', '2404696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Appellate Division’s judgment.', 'general', 'Foldi v. Jeffries', 'https://www.courtlistener.com/opinion/2404696/', '2404696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the objective facts of record fall within the community caretaking exception to the fourth amendment, rendering Brunnworth’s assumed seizure of defendant reasonable.', 'search_seizure', 'People v. McDonough', 'https://www.courtlistener.com/opinion/2483242/', '2483242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State alternatively contends that if we conclude that Brunnworth violated defendant’s fourth amendment rights, the exclusionary rule should not apply in this case to bar admission of the evidence discovered as a result of that seizure.', 'search_seizure', 'People v. McDonough', 'https://www.courtlistener.com/opinion/2483242/', '2483242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We explained: We concluded that the community caretaking doctrine “is analytically distinct from consensual encounters and is invoked to validate a search or seizure as reasonable under the fourth amendment.', 'search_seizure', 'People v. McDonough', 'https://www.courtlistener.com/opinion/2483242/', '2483242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the testimony from the jailers, in this case, violated the rule in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that a criminal defendant could not be convicted of both kidnapping and murder where the “restraint essential to the kidnapping conviction was an inherent and inevitable feature of [the] particular murder.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has met this burden in the present case.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that the prosecutor’s questions legitimately sought to determine the jurors’ ability to carry out their duties in defendant’s capital trial.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this brief contact was legally insignificant.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the note was not a confidential communication protected by the spousal privilege.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that the prosecution did not knowingly present perjured testimony.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Gabriel was competent to testify to his observations.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Reeves’ testimony was proper nonhearsay evidence and that the trial court did not commit error.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s rulings were proper.', 'general', 'State v. Call', 'https://www.courtlistener.com/opinion/1263631/', '1263631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the results of the HGN test were relevant to show alcohol consumption in conjunction with the results of other field sobriety tests performed.', 'general', 'Whitson v. State', 'https://www.courtlistener.com/opinion/2429564/', '2429564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this point is now academic because the appellant did receive a jury trial on the implied consent charge.', 'general', 'Whitson v. State', 'https://www.courtlistener.com/opinion/2429564/', '2429564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 639 (1993), and we conclude that this issue is not properly preserved for appeal.', 'general', 'Whitson v. State', 'https://www.courtlistener.com/opinion/2429564/', '2429564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that any error committed by the prosecutor’s first questioning which was objected to by defense counsel was rendered harmless by Curtis’s subsequent testimony to the same effect, though it related to a separate incident.', 'general', 'Whitson v. State', 'https://www.courtlistener.com/opinion/2429564/', '2429564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'None of the errors asserted requires reversal of this case, and we affirm.', 'general', 'Whitson v. State', 'https://www.courtlistener.com/opinion/2429564/', '2429564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 173 (1944), in which we held that a drunk passenger could be convicted as an accessory before the fact to involuntary manslaughter and held to the same degree of fault as the driver who was the principal offender.', 'general', 'Fight v. State', 'https://www.courtlistener.com/opinion/2429703/', '2429703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the appellate court erred in concluding that appellant had given the jury a false impression which the State was entitled to rebut by introducing the prior arson conviction.', 'general', 'Theus v. State', 'https://www.courtlistener.com/opinion/2429763/', '2429763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the factors to appellant’s case, we conclude that the arson conviction had very little probative value concerning appellant’s credibility, although four of the factors favor admissibility.', 'general', 'Theus v. State', 'https://www.courtlistener.com/opinion/2429763/', '2429763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, reveals that we concluded that when “the witness represents himself as a law-abiding citizen .', 'general', 'Theus v. State', 'https://www.courtlistener.com/opinion/2429763/', '2429763') ON CONFLICT DO NOTHING;
