INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that Reese was prejudiced by the solicitor’s improper Golden Rule argument since the question of malice was in contention.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1264694/', '1264694') ON CONFLICT DO NOTHING;
