INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'State v. Reese', 'https://www.courtlistener.com/opinion/1264694/', '1264694') ON CONFLICT DO NOTHING;
