INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to issues not specifically addressed herein, we affirm the decision
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "an anonymous report of erratic driving must be evaluated in light of the imminent risks that a drunk driver poses to himself and the public.', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sprague, we held that any "police intrusion [must] proceed no further than necessary to effectuate the purpose of the stop.', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that both days'' events offend the Vermont Constitution.', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that he was, and that his motion to suppress should have been granted on that basis, we do not reach his other claims.', 'suppression', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2, the State stipulated that, if we conclude that there was no reasonable suspicion upon which to detain defendant, the motion to suppress should have been granted.', 'suppression', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the officer here did not have a reasonable, articulable suspicion of drug activity on May 5, and that the district court therefore erred in denying defendant''s motion to suppress the evidence obtained on that day.', 'suppression', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Langlois, we concluded that an officer did not have probable cause to search an automobile based on a telephone informant who stated that the defendant.', 'probable_cause', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "the information .', 'general', 'State v. Cunningham', 'https://www.courtlistener.com/opinion/1057358/', '1057358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the jury’s finding that appellant intentionally killed the victim is not so contrary to the overwhelming weight of the evidence as to be clearly wrong or unjust.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2440978/', '2440978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because appellant never challenged the vol-untariness of his confession prior to its admission with regard to his mental capacity or his age, we hold that he has waived these arguments.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2440978/', '2440978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not err by overruling appellant’s motion to suppress and admitting his confession into evidence.', 'suppression', 'Jones v. State', 'https://www.courtlistener.com/opinion/2440978/', '2440978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Rule 105(a) “requires a limiting instruction, upon proper request, when evidence is admitted.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2440978/', '2440978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we held that the trial court erred by failing to give a simultaneous instruction and remanded the case to the court of appeals to determine whether such an error is subject to a harmless error analysis under Texas Rule of Appellate Procedure 81(b)(2).', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2440978/', '2440978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we conclude that the trial court erred by failing to grant appellant’s request for a limiting instruction at the time the photos were introduced into evidence.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2440978/', '2440978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that admitting the photos without a simultaneous limiting instruction was harmless beyond a reasonable doubt.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2440978/', '2440978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm the judgment of the trial court.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2440978/', '2440978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the totality of the circumstances, Poe’s tip carried with it sufficient evidence of reliability to justify an investigatory stop under Rule 3.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2441576/', '2441576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'consequently, we conclude that Johnson’s prior similar criminal acts were admissible to show his intent.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2441576/', '2441576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s ruling denying Johnson’s motion to suppress his statement.', 'suppression', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2441576/', '2441576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2441576/', '2441576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Echols made a sufficient offer of proof.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that even if the evidence of the defendant’s mental illness was uncontradicted, the jury was not required to believe the defendant’s evidence and was not required to find such a mitigating circumstance.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 223 (1986), we held that the jury did not have to find an eighteen year old’s youth was a mitigating factor.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the jury did not err in refusing to find that the defendant’s youth was a mitigating factor.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we held that the jury erred in failing to find, as a mitigating factor, the fact that the defendant committed the crime while his capacity to conform his conduct to the requirements of the law was impaired as a result of mental disease or defect.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 57 (1983), we held that, in determining whether to grant a severance, a trial court should weigh: (1) whether the defenses of the defendants are antagonistic;', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In a similar case, we held that this kind of ruling does not amount to a “binding commitment.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial judge had not made a binding commitment, but had alluded to the law as set forth in McDaniel v.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court did not abuse its discretion by denying severance when the facts had not developed to that point.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 57 (1983), we held that the cited statute had been superseded by Ark.', 'general', 'Echols v. State', 'https://www.courtlistener.com/opinion/2441634/', '2441634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Rule 53 of the Superior Court Rules Governing Domestic Relations Proceedings authorized the trial court both to appoint a parenting coordinator under the exceptional circumstances presented by this case, and to delegate decision-making authority to the parenting coordinator over day-to-day issues that do not implicate the court’s exclusive responsibility to adjudicate the parties’ rights to custody and visitation.', 'general', 'Jordan v. Jordan', 'https://www.courtlistener.com/opinion/2443342/', '2443342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in ordering Ms.', 'general', 'Jordan v. Jordan', 'https://www.courtlistener.com/opinion/2443342/', '2443342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in making this ruling.', 'general', 'Jordan v. Jordan', 'https://www.courtlistener.com/opinion/2443342/', '2443342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the court had erred
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we held that the court’s decision to allow unsupervised visitation was unsupported by the evidence because “no expert testified that unsupervised visits between [the father and the child] would be appropriate.', 'general', 'Jordan v. Jordan', 'https://www.courtlistener.com/opinion/2443342/', '2443342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that each of these claims of error lacks merit.', 'general', 'Jordan v. Jordan', 'https://www.courtlistener.com/opinion/2443342/', '2443342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2008), we reversed a trial court’s award of joint custody to a father who had committed intrafamily offenses, because “reading the judge’s order as whole, we [were] unable to state with confidence that full consideration and due weight were accorded to the District’s policy disfavoring a custody award to an abuser in the absence of proof that such an award is consistent with the safety and well-being of the child or children, and the judge’s order [did] not expressly address the point.', 'general', 'Jordan v. Jordan', 'https://www.courtlistener.com/opinion/2443342/', '2443342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm the judgment of the trial court with respect to the award of joint custody and the appointment of a parenting coordinator.', 'general', 'Jordan v. Jordan', 'https://www.courtlistener.com/opinion/2443342/', '2443342') ON CONFLICT DO NOTHING;
