INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even when we conclude that the trial court abused its discretion in finding aggravating circumstances or failing to find mitigating circumstances, we will not necessarily reverse the sentence.', 'sentencing', 'Roney v. State', 'https://www.courtlistener.com/opinion/2072750/', '2072750') ON CONFLICT DO NOTHING;
