INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in so finding.', 'general', 'Roney v. State', 'https://www.courtlistener.com/opinion/2072750/', '2072750') ON CONFLICT DO NOTHING;
