INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reweighing the proper aggra-vators and mitigators, we conclude that the sixty-five year sentence imposed by the trial court is proper.', 'sentencing', 'Roney v. State', 'https://www.courtlistener.com/opinion/2072750/', '2072750') ON CONFLICT DO NOTHING;
