INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that on retrial the jury should be instructed on the lesser-included offense of theft.', 'general', 'State v. Minano', 'https://www.courtlistener.com/opinion/1206726/', '1206726') ON CONFLICT DO NOTHING;
