INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm the trial court.', 'general', 'Richard C. Wagoner, Jr. v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/2669107/', '2669107') ON CONFLICT DO NOTHING;
