INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse the unpublished decision of the Court of Appeals and remand this case to that court for further remand to the Superior Court, Rowan County, for reinstatement of the judgments against defendant both for obtaining property by false pretenses and for being an habitual felon.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1205150/', '1205150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons we explain below, we affirm in part, reverse in part, and remand with directions that the trial court modify the injunction.', 'general', 'City of Milwaukee v. Burnette', 'https://www.courtlistener.com/opinion/1274668/', '1274668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review, we conclude that plaintiff has failed to demonstrate either how the conduct of Lieutenant Eubanks or Officer Dean breached a duty owed to plaintiffs decedent, or the existence of a causal connection between the conduct and the accident.', 'general', 'Parish v. Hill', 'https://www.courtlistener.com/opinion/1316441/', '1316441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that plaintiff has failed to demonstrate any negligence on the part of Lieutenant Eubanks and Officer Dean, and certainly has not shown the degree of gross negligence required in order to hold the officers liable for the decedent’s death.', 'general', 'Parish v. Hill', 'https://www.courtlistener.com/opinion/1316441/', '1316441') ON CONFLICT DO NOTHING;
