INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 23 We find that the legislature intended to prohibit driving with any amount of an impairing substance resulting from a drug proscribed in § 13-3401 in the body.', 'general', 'State of Arizona Ex Rel. Montgomery v. Hrach Shilgevorkyan', 'https://www.courtlistener.com/opinion/2670824/', '2670824') ON CONFLICT DO NOTHING;
