INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the conviction.', 'general', 'Tucker v. Commonwealth', 'https://www.courtlistener.com/opinion/1064618/', '1064618') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we held that a stop violated the Fourth Amendment when an officer merely had an inarticulate hunch about a vehicle the officer saw driving through a less traveled part of a mall parking lot.', 'search_seizure', 'State v. Tozier', 'https://www.courtlistener.com/opinion/2193260/', '2193260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 8] In contrast, we held that a stop was justified when the officer thought he recognized the driver of a car, ran a registration check on the vehicle, and learned that it was registered to that driver and the driver’s license was suspended.', 'general', 'State v. Tozier', 'https://www.courtlistener.com/opinion/2193260/', '2193260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the stop was justified, we vacate the grant of Tozier’s motion to suppress and remand the matter for further proceedings.', 'suppression', 'State v. Tozier', 'https://www.courtlistener.com/opinion/2193260/', '2193260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 10] Applying the same analysis, we conclude that Tozier’s Fourth Amendment rights were not violated.', 'search_seizure', 'State v. Tozier', 'https://www.courtlistener.com/opinion/2193260/', '2193260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In another case, we concluded that a stop comported with the Fourth Amendment when the police department received an anonymous tip identifying the location of a suspended driver who was operating a motor vehicle and verified the suspension, after which an officer observed the suspended driver’s vehicle on a public way and stopped the vehicle.', 'search_seizure', 'State v. Tozier', 'https://www.courtlistener.com/opinion/2193260/', '2193260') ON CONFLICT DO NOTHING;
