INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that prior domestic violence convictions in other states may be used to enhance the penalty for subsequent domestic violence convictions under West Virginia Code § 61-2-28.', 'general', 'State v. Hulbert', 'https://www.courtlistener.com/opinion/1266769/', '1266769') ON CONFLICT DO NOTHING;
