INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/9467509/', '9467509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Act exceeds the authority of Congress “[t]o regulate Commerce .', 'general', 'United States v. Lopez', 'https://www.courtlistener.com/opinion/117927/', '117927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 37, we held that the question of congressional power under the Commerce Clause “is necessarily one of degree.', 'general', 'United States v. Lopez', 'https://www.courtlistener.com/opinion/117927/', '117927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 (1895), this Court held that mere attempts to monopolize the manufacture of sugar could not be regulated pursuant to the Commerce Clause.', 'general', 'United States v. Lopez', 'https://www.courtlistener.com/opinion/117927/', '117927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The moment came, however, with the challenge to congressional Commerce Clause authority to prohibit racial discrimination in places of public accommodation, when the Court simply made explicit what the earlier cases had implied: “where we find that the legislators, in light of the facts and testimony before them, have a rational basis for finding a chosen regulatory scheme necessary to the protection of commerce, our investigation is at an end.', 'general', 'United States v. Lopez', 'https://www.courtlistener.com/opinion/117927/', '117927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a person has been “seized” within the meaning of the Fourth Amendment only if, in view of all of the circumstances surrounding the incident, a reasonable person would have believed that he was not free to leave.', 'search_seizure', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1219119/', '1219119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that the trial court’s actions in this case unduly influenced appellant to abandon his previously asserted decision to testify, we decline appellant''s invitation to limit our reasoning in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that because the judge’s statements in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the trial court’s denial of the defendant’s request to testify was not harmless beyond a reasonable doubt.', 'general', 'Arthur v. United States', 'https://www.courtlistener.com/opinion/1887302/', '1887302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that the trial court did not intimidate the defense witness by informing him of his Fifth Amendment right not to testify and the consequences of perjury.', 'general', 'Arthur v. United States', 'https://www.courtlistener.com/opinion/1887302/', '1887302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we now discuss, we conclude that reversal is warranted under plain error review.', 'general', 'Arthur v. United States', 'https://www.courtlistener.com/opinion/1887302/', '1887302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a close case, we conclude that the judge did not commit reversible error for four reasons.', 'general', 'Arthur v. United States', 'https://www.courtlistener.com/opinion/1887302/', '1887302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, even though we perceive that the trial judge’s actions were motivated by concern for the defendant, we conclude that they were more aligned with what the Court deemed impermissible in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred.', 'general', 'Arthur v. United States', 'https://www.courtlistener.com/opinion/1887302/', '1887302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the error in this case was clear.', 'general', 'Arthur v. United States', 'https://www.courtlistener.com/opinion/1887302/', '1887302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that, viewed in the context of appellant’s trial, the error affected appellant’s substantial rights.', 'general', 'Arthur v. United States', 'https://www.courtlistener.com/opinion/1887302/', '1887302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'Rita v. United States', 'https://www.courtlistener.com/opinion/145708/', '145708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it can.', 'general', 'Rita v. United States', 'https://www.courtlistener.com/opinion/145708/', '145708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And, for that reason, *356we find that nothing in § 3553(a) renders use of the presumption unlawful.', 'general', 'Rita v. United States', 'https://www.courtlistener.com/opinion/145708/', '145708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Gell, we held that both of these factors supported an “abuse-of-discretion” standard for review of a district judge’s imposition of sanctions for violations of Rule 11 of the Federal Rules of Civil Procedure.', 'general', 'Rita v. United States', 'https://www.courtlistener.com/opinion/145708/', '145708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that exposing a defendant to an increased penalty beyond the range for a basic crime, based on facts determined exclusively by a judge, violated the Sixth Amendment, in the absence of a jury waiver;', 'general', 'Rita v. United States', 'https://www.courtlistener.com/opinion/145708/', '145708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the additional factfinding necessary for a judge to sentence within a high subrange was comparable to the finding of additional fact required for a judge to impose an enhanced sentence under the law considered in Apprendi.', 'sentencing', 'Rita v. United States', 'https://www.courtlistener.com/opinion/145708/', '145708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a discovery rule does not govern §1681p.', 'general', 'TRW Inc. v. Andrews', 'https://www.courtlistener.com/opinion/118465/', '118465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the text and structure of §1681p evince Congress’ intent to preclude judicial implication of a discovery rule.', 'general', 'TRW Inc. v. Andrews', 'https://www.courtlistener.com/opinion/118465/', '118465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we hold that the Fourth Amendment does not put the State to such a choice.', 'search_seizure', 'United States v. Knights', 'https://www.courtlistener.com/opinion/118468/', '118468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the balance of these considerations requires no more than reasonable suspicion to conduct a search of this probationer’s house.', 'general', 'United States v. Knights', 'https://www.courtlistener.com/opinion/118468/', '118468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a State’s operation of its probation system presented a “special need” for the “exercise of supervision to assure that [probation] restrictions are in fact observed.', 'general', 'United States v. Knights', 'https://www.courtlistener.com/opinion/118468/', '118468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not decide whether Knights’ acceptance of the search condition constituted consent in the Schneckloth sense of a complete waiver of his Fourth Amendment rights, however, because we conclude that the search of Knights was reasonable under our general Fourth Amendment approach of “examining the totality of the circumstances,” Ohio v.', 'search_seizure', 'United States v. Knights', 'https://www.courtlistener.com/opinion/118468/', '118468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the warrantless search of Knights, supported by reasonable suspicion and authorized by a condition of probation, was reasonable within the meaning of the Fourth Amendment.', 'search_seizure', 'United States v. Knights', 'https://www.courtlistener.com/opinion/118468/', '118468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Worley could challenge the plea proceeding on appeal, despite his failure to do so by a motion in arrest of judgment.', 'plea', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under these circumstances, rule 23(3)(a) does not preclude our review of Kirchoff''s plea proceeding.', 'plea', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when Kirchoff''s petitions to plead guilty were introduced into the plea proceeding by direct reference and affirmed and acknowledged by Kirchoff in open court, substantial compliance with rule 8(2)(b) was achieved.', 'plea', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no error in either, we affirm.', 'general', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no error in either the plea or sentencing proceedings, we affirm the convictions and sentences.', 'sentencing', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 453 (Iowa 1988), we affirmed a conviction entered after a written plea of guilty despite the defendant''s argument that Fluhr required that we set aside his plea.', 'plea', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/1246031/', '1246031') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we do not find the challenged statute to be void for vagueness, we conclude that the State failed to introduce the necessary evidence to prove that Mr.', 'general', 'State of West Virginia v. James Scott Yocum', 'https://www.courtlistener.com/opinion/2673966/', '2673966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'State of West Virginia v. James Scott Yocum', 'https://www.courtlistener.com/opinion/2673966/', '2673966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a stun gun, even if inoperable, is per se a dangerous
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a stun gun is per se a dangerous weapon
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'preservation insofar as we conclude that Geier’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we hold that the evidence is sufficient to support both convictions and, accordingly, the judgments of the trial court are affirmed.', 'general', 'Sandoval v. Commonwealth', 'https://www.courtlistener.com/opinion/1219276/', '1219276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We frame the issue as follows: is an accused entitled to a verdict on the greater charge where the jury has unanimously decided that charge but is deadlocked on the lesser-included offenses? We conclude that the accused is entitled to such a verdict.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*278We conclude that the trial judge abused his discretion in refusing to resolve the questions posed by the juror which evidenced some possibility of reaching a partial verdict or to repoll the jury as requested by Whiteaker.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a consequence, we conclude that the trial judge abused his discretion in concluding that there was no probability that a unanimous verdict could be reached.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 948 (Alaska 1986), we concluded that manifest necessity was found where a jury could not agree on the greatest charge of attempted first-degree murder and that the defendant was not entitled to a verdict on any lesser-included offense under those facts.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a consequence we find that Whiteaker cannot face trial on an offense more serious than negligent homicide.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse her conviction.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we REVERSE the conviction for second degree murder and REMAND to the trial court.', 'general', 'Whiteaker v. State', 'https://www.courtlistener.com/opinion/1219351/', '1219351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Such conduct is not protected by the First Amendment and accordingly, we hold that § 16-17-420 is not a substantial threat to protected speech requiring overbreadth adjudication.', 'general', 'In Re Amir X.S.', 'https://www.courtlistener.com/opinion/1276706/', '1276706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 16-17-420(1), we find that it does not substantially prohibit First Amendment speech.', 'general', 'In Re Amir X.S.', 'https://www.courtlistener.com/opinion/1276706/', '1276706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'In Re Amir X.S.', 'https://www.courtlistener.com/opinion/1276706/', '1276706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the family court’s decision that § 16-17-420 is not unconstitutionally overbroad.', 'general', 'In Re Amir X.S.', 'https://www.courtlistener.com/opinion/1276706/', '1276706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that § 16-17-420 does not punish a substantial amount of protected speech, and accordingly, does not warrant overbreadth adjudication.', 'general', 'In Re Amir X.S.', 'https://www.courtlistener.com/opinion/1276706/', '1276706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that any rights created by the provisions of the Interstate Agreement on Detainers Act, W.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 588 (1989), we held that the rejection of a petition for appeal does not constitute a decision on the merits precluding all future consideration of the issues raised therein.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in Syllabus Point 4 of Moore v.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that our Legislature intended our adoption of the IAD to be consistent with the federal IAD enactment.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While it appears, at first blush, that Bozeman would control this matter, we find that it does not.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed in Section A, infra, we find that they may not.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it involves neither.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we find that Pethel''s guilty plea relative to the drug and burglary charges in the indictment waived his claims based upon violation of the IAD as to the indictment''s drug and burglary related charges.', 'plea', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding significant contrary authority, we reverse the finding of the circuit court.', 'general', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the circuit court''s grant of habeas relief to Pethel because the same was based upon a violation of the IAD''s anti-shuttling provision.', 'habeas', 'Pethel v. McBride', 'https://www.courtlistener.com/opinion/1265966/', '1265966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a probationer, like a parolee, is entitled to a preliminary and a final revocation hearing, *611under the conditions specified in Morrissey v.', 'general', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Loomis’s right to due process was violat*609ed when the Idaho Commission of Pardons and Parole delayed giving Loomis notice of the parole violation that was alleged to have occurred and failed to conduct a timely probable cause hearing on that allegation.', 'probable_cause', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because these constitutional violations do not presently entitle Loomis to release from custody, we affirm the magistrate’s denial of habeas corpus relief.', 'habeas', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because Loomis has not been entitled to release at any time after his belated preliminary hearing was conducted, we affirm the magistrate’s order denying Loomis’s petition for a writ of habeas corpus.', 'habeas', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the Commission’s failure to give Loomis notice of the nature of the alleged parole violation for a period of twenty-one days following his arrest was a violation of due process.', 'general', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we view [the "shock the conscience"] inquiry to be one of complete subjectivity, we hold that it is not to be undertaken in any analysis relating to remittitur.', 'general', 'People v. Milbourn', 'https://www.courtlistener.com/opinion/1231473/', '1231473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '199 NW2d 202 (1972), in which we held that the minimum term of incarceration in sentences imposed under the indeterminate sentence act could not be greater than two-thirds of the maximum term.', 'sentencing', 'People v. Milbourn', 'https://www.courtlistener.com/opinion/1231473/', '1231473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such sentences should be subject to appellate review and relief when warranted.', 'sentencing', 'People v. Milbourn', 'https://www.courtlistener.com/opinion/1231473/', '1231473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the imposition of the maximum possible sentence on Mr.', 'sentencing', 'People v. Milbourn', 'https://www.courtlistener.com/opinion/1231473/', '1231473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a guilty plea relinquishes the right to assert a multiplicity claim when the claim cannot be resolved on the record.', 'plea', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, after considering the relationship of Broce to Morris and its progeny, especially Hubbard, we conclude that the rule in Broce that a guilty plea can waive double jeopardy defects, subject to certain exceptions, is consistent with Wisconsin case law and properly balances the public''s interest in efficient judicial administration with a defendant''s double jeopardy rights.', 'plea', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither overbroad precedent from Wisconsin courts nor any policy view of our criminal justice system warrants our breaking ranks with Broce.', 'general', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Kelty''s guilty plea relinquished her opportunity to have a court determine the merits of her multiplicity challenge.', 'plea', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 Because Kelty''s attempt to withdraw her guilty plea cannot meet any of these grounds for withdrawal,4 we reverse the court of appeals.', 'plea', 'State v. Kelty', 'https://www.courtlistener.com/opinion/1277190/', '1277190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the recent amendment to section 1 — 6 does not apply retroactively to this case because it effected a change in substantive law.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, this court held that section 11 — 401 implicitly requires the mental state of knowledge on the part of a motorist.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of thé legislature’s focus on requiring a driver to render aid to an injured person, we find that it is consistent with legislative intent to require that a driver have knowledge that the accident involved another person.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Next, we find that the Carlsons’ testimony does not conclusively establish that a different vehicle struck Pranaitis.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence presented to the jury was sufficient to support a finding that defendant knew another person was involved in the accident.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm the holding of the appellate court reversing defendant’s conviction and sentence for failure to report a motor vehicle accident resulting in death.', 'sentencing', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons stated, we affirm the appellate court’s reversal of defendant’s conviction for failure to report an accident involving personal injury or death, and remand for a new trial.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that section 11 — 401 requires that a motorist have knowledge that he or she was involved in an accident that involved another person.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1005 (1982), we held that a motion for return of property under A.', 'general', 'State Ex Rel. Milstead v. Melvin', 'https://www.courtlistener.com/opinion/1278516/', '1278516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon examination of the issue, we conclude that whether an out-of-state offense is substantially similar to a North Carolina offense is a question of law that must be determined by the trial court, not the jury.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the- question of whether a conviction under an out-of-state statute is substantially similar to an offense under North Carolina statutes is a question of law to be resolved by the trial court.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court erred in finding New York’s second-degree assault to be substantially similar to North Carolina’s assault inflicting serious injury, which is a Class A1 misdemeanor, as opposed to simple assault, which is a Class 2 misdemeanor.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State had argued that defendant had stipulated to the fact that the New York offenses were substantially similar to the North Carolina offenses, but we found that defendant had not so stipulated, and thus that the State had not met its burden under N.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s order and judgment sentencing defendant to 251 to 311 months imprisonment, and grant defendant a new sentencing hearing.', 'sentencing', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “neither Blakely nor Allen preclude the trial court from assigning a point in the calculation of one’s prior record level where ‘all the elements of the present offense are included in [a] prior offense.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Blakely errors arising under North Carolina’s Structured Sentencing Act are structural and, therefore, reversible per se.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1279497/', '1279497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying Apprendi, this Court held that facts supporting such an enhanced sentence under N.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1279497/', '1279497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Blakely errors are structural and modify and affirm the decision of the Court of Appeals remanding defendant’s case to Gaston County Superior Court for resentencing.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1279497/', '1279497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Blakely *427applies to North Carolina’s Structured Sentencing Act and that N.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1279497/', '1279497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lucas, we conclude that those portions of N.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1279497/', '1279497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Court of Appeals remanding defendant’s case for resentencing and hold that, to the extent N.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1279497/', '1279497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004) (“Further, we hold that Blakely error is subject to harmless error or fundamental error analysis and may or may not require reversal based on the facts of a particular case.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1279497/', '1279497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the circuit court erred in sentencing and that consecutive sentences were required.', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kilpatrick, this court held that this action resulted in an impermissible increase in sentencing because section 5 — 8—1(c) of the Unified Code of Corrections (730 ILCS 5/5 — 8—1(c) (West 1992)) prohibited the circuit court from increasing a sentence after it was imposed.', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that knowledge of whether the underlying crime is a felony is not an element of the crime of felony accessory after the fact.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the evidence presented, even when viewed in the light most favorable to the State, is insufficient to establish that Bush entered Schantz’s apartment with the specific intent to commit a larceny.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, in considering an argument that the conviction of the accused for burglary could not be sustained because he had been acquitted of the attempted sexual assault which was the felony relied upon, we held that success in committing the felony was not material.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the evidence presented, even when viewed in the light most favorable to the State, is insufficient to establish that Bush entered Sehantz’s apartment with the specific intent to commit a larceny.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 590 (1974), this court held the following: “The verdict of a jury must be sustained if there is substantial evidence, taking the view most favorable to the State to support it.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1281029/', '1281029') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Court of Appeals applied the wrong standard of review and since we find the evidence sufficient to sustain the conviction upon the appropriate standard of review, we reverse and remand.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1281029/', '1281029') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Court of Appeals applied the wrong standard of review and since we find the evidence sufficient to sustain the conviction upon the appropriate standard of review, we reverse the judgment and remand this cause.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/1281029/', '1281029') ON CONFLICT DO NOTHING;
