INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we hold that (1) the local governments had the power to enact the ordinances, and (2) the ordinances are not inconsistent with either the Constitution or general law of this State.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although § 5-7-30 lists various specific powers possessed by municipalities, we hold that the broad grant of power stated at the beginning of the statute is not limited by the specifics mentioned in the remainder of the statute.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 5-7-30, especially when read in light of Article VIII’s mandatory liberal rule of construction, authorized the Town of Hilton Head to enact an ordinance promoting the general health, safety, and welfare of the Town’s residents and visitors by raising funds to improve, maintain, nourish and re-nourish the Town’s beaches.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the defendants had the power to enact the ordinances at issue, and the ordinances are not inconsistent with the Constitution or general law of this State, we hold that the ordinances are valid.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the classification under each ordinance bears a reasonable relation to the legislative purpose to be effected.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the principle quoted is applicable to our statutory requirement that the detention be carried out in a “reasonable manner.', 'general', 'Gortarez v. Smitty''s Super Valu, Inc.', 'https://www.courtlistener.com/opinion/1251856/', '1251856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court erred in its findings with respect to both the purpose and manner of detention.', 'general', 'Gortarez v. Smitty''s Super Valu, Inc.', 'https://www.courtlistener.com/opinion/1251856/', '1251856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] We hold that the evidence in the present case, viewed in the light most favorable to the verdict, is legally sufficient to support the assault-by-threat conviction.', 'general', 'Olivas v. State', 'https://www.courtlistener.com/opinion/1631136/', '1631136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[35] This Court held that because there was no evidence presented that the defendant threatened the mother before stabbing her, the State failed to prove the element of "threat" to the mother.', 'general', 'Olivas v. State', 'https://www.courtlistener.com/opinion/1631136/', '1631136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We conclude that McGowan held only that assault by threat requires the defendant to communicate a threat of imminent bodily injury;', 'general', 'Olivas v. State', 'https://www.courtlistener.com/opinion/1631136/', '1631136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Tunnell as required under the Texas Penal Code, we reverse the judgment of the court of appeals and remand the case to that court to address appellant''s remaining points of error.', 'general', 'Olivas v. State', 'https://www.courtlistener.com/opinion/1631136/', '1631136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[36] We affirmed the aggravated-assault-by-threat conviction against the daughter because "[t]he evidence showed that after she was initially stabbed by appellant [the daughter] saw him holding the knife and began begging appellant not to cut her.', 'general', 'Olivas v. State', 'https://www.courtlistener.com/opinion/1631136/', '1631136') ON CONFLICT DO NOTHING;
