INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“Accordingly, we hold that murder by means of torture under section 189 is murder committed with a wilful, deliberate, and premeditated intent to inflict extreme and prolonged pain.', 'general', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
