INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the majority’s reasoning in Gates, we conclude that the Gates totality of the circumstances approach does not provide the constitutional protection against unreasonable searches and seizures required by Article 1, Section 14 and Article 1, Section 22 of the Alaska Constitution.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1284136/', '1284136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the basis of knowledge prong was adequately demonstrated.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1284136/', '1284136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals’ decision under Article I, Section 14 and Article I, Section 22 of the Alaska Constitution.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1284136/', '1284136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Here, we find that the trial court acted properly in finding defendant’s claim frivolous.', 'general', 'State v. Borbon', 'https://www.courtlistener.com/opinion/1284145/', '1284145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the gravity of the offense, we find that appellant’s crimes were very serious.', 'general', 'State v. Borbon', 'https://www.courtlistener.com/opinion/1284145/', '1284145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that his actions were extremely dangerous and grave.', 'general', 'State v. Borbon', 'https://www.courtlistener.com/opinion/1284145/', '1284145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court’s actions stating that “[t]his was a preliminary determination of reasonable grounds only.', 'general', 'State v. Borbon', 'https://www.courtlistener.com/opinion/1284145/', '1284145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such an action is not a “criminal prosecution” within the meaning of Article 1, Section 11 of the Alaska Constitution, which provides that “[i]n all criminal prosecutions, the accused shall have the right to .', 'general', 'Resek v. State', 'https://www.courtlistener.com/opinion/1284172/', '1284172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This issue is really one of legislative intent, and we conclude that the nature of the forfeiture penalty clearly indicates that it was *292intended as a civil, not a criminal, sanction.', 'general', 'Resek v. State', 'https://www.courtlistener.com/opinion/1284172/', '1284172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the forfeiture action at issue here is a civil proceeding and not a “criminal prosecution” within the meaning of Article 1, Section 11 of the state constitution.', 'general', 'Resek v. State', 'https://www.courtlistener.com/opinion/1284172/', '1284172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we conclude that the trial court erred in admitting the VGN testimony.', 'general', 'Townsend v. Dist. of Columbia', 'https://www.courtlistener.com/opinion/6484416/', '6484416') ON CONFLICT DO NOTHING;
