INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/1285484/', '1285484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that there should not be such a duty, citing, among other reasons, the numerous “social and financial problems” with which the public schools are beset.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 In that case, a panel of this Court held that "it is a familiar and well-settled rule of American jurisprudence that equity will not enjoin a defamation, absent a showing of economic injury .', 'general', 'TM v. MZ', 'https://www.courtlistener.com/opinion/8287645/', '8287645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the amended PPO was issued on the basis of respondent''s constitutionally protected speech and amounted to an unconstitutional prior restraint on his speech, we reverse the trial court.', 'general', 'TM v. MZ', 'https://www.courtlistener.com/opinion/8287645/', '8287645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court order, vacate the PPO, and remand with instruction that the "PPO should be updated in LEIN as rescinded .', 'general', 'TM v. MZ', 'https://www.courtlistener.com/opinion/8287645/', '8287645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 2 We hold that the circuit court''s erroneous exclusion of the GPS data was harmless, and therefore affirm the decision of the court of appeals.', 'general', 'State v. Kyle Lee Monahan', 'https://www.courtlistener.com/opinion/4511938/', '4511938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 67 We hold that the circuit court''s erroneous exclusion of the GPS data was harmless, and therefore affirm the decision of the court of appeals.', 'general', 'State v. Kyle Lee Monahan', 'https://www.courtlistener.com/opinion/4511938/', '4511938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the circuit court erroneously exercised its discretion when it excluded Venske''s testimony because the testimony would have corroborated Hunt''s testimony.', 'general', 'State v. Kyle Lee Monahan', 'https://www.courtlistener.com/opinion/4511938/', '4511938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this factor weighs in favor of the State.', 'general', 'State v. Kyle Lee Monahan', 'https://www.courtlistener.com/opinion/4511938/', '4511938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that this factor weighs in favor of the State.', 'general', 'State v. Kyle Lee Monahan', 'https://www.courtlistener.com/opinion/4511938/', '4511938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 66 Based on the foregoing, we conclude that "it is beyond a reasonable doubt that the error complained of did not contribute to the verdict obtained.', 'general', 'State v. Kyle Lee Monahan', 'https://www.courtlistener.com/opinion/4511938/', '4511938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that an objective assessment of the facts as found by the district court gave the deputies probable cause to arrest Julian for aggravated battery.', 'probable_cause', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the officer’s decision to cite Julian for domestic battery does not foreclose an inquiry into whether an objective assessment of the facts present at the moment of arrest would lead a person of ordinary prudence to conclude that probable cause existed to arrest Julian for a felony arising from the same operative facts supporting the domestic battery arrest, i.', 'probable_cause', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that probable cause existed to arrest Julian for aggravated battery, the deputies were within the scope of either subsection of the arrest statute when they arrested Julian.', 'probable_cause', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the unobjected to errors of the judge and the prosecutor in this case are fundamental, obvious, and substantial;', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that these errors constitute plain error.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the facts of this case give rise to plain error and thus warrant a new trial.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the errors constitute plain error.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that even though disparaging remarks by both the prosecutor and the defense counsel were improper, those errors did not require a new trial based on plain error or in the interest of justice.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today we find that the errors constitute plain error.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we reverse the court of appeals'' decision and remand to the circuit court for a new trial.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that a hearing on a motion to modify or extend a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Troy Daniel Dowell v. State of Iowa', 'https://www.courtlistener.com/opinion/4514321/', '4514321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'which the district court relied, we affirm the summary dismissal of Dowell’s PCR
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, on the basis of the dual grounds of the automobile exception, we hold that suppression is not warranted by the Fourth Amendment as applied to the states by the Fourteenth Amendment because the arson investigator had probable cause to search the vehicle without a warrant.', 'suppression', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Next we hold that suppression is also unjustified under the Michigan Constitution.', 'suppression', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following our review de novo of the circuit court''s decision to affirm, we hold that the district court abused its discretion in dismissing the charges.', 'dismissal', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1684 ("We hold that all evidence obtained by searches and seizures in violation of the Constitution is, by that same authority, inadmissible in a state court.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 419 (1970), we held that when police officers have probable cause to believe there is contraband inside an automobile that has been stopped on the road, the officers may conduct a warrantless search of the vehicle, even after it has been impounded and is in police custody.', 'probable_cause', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, having concluded that the evidence of arson discovered during the search of defendant''s automobile was admissible, we conclude that the lower courts erred in dismissing the charges against defendant of burning personal property valued at greater than $1,000 but less than $20,000, M.', 'dismissal', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for trial.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/1658796/', '1658796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 608 (1994), where this Court held, inter alia, a municipal enactment prohibiting nude dancing violative of Article VIII, § 14, even though no State law prohibited nude dancing.', 'general', 'Diamonds v. Greenville County', 'https://www.courtlistener.com/opinion/1288612/', '1288612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the *562Court of Appeals erred when it improperly usurped the role of the fact-finder and misapplied this Court''s opinion in People v.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '13 Rather, we hold that the jury could reasonably infer and find from the factual record-separate and distinct from the sheer number of stab wounds alone-that defendant had an opportunity to subject his actions to a "second look," and therefore acted with premeditation and deliberation.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 73 (1999), this Court held that evidence of a struggle between the defendant and the victim can be evidence of premeditation and deliberation based on the defendant''s opportunity to take a "second look.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that from this evidence, an inference may be fairly drawn that defendant was the initial aggressor and not the victim, as defendant had claimed.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Therefore, given the record evidence, which reveals that defendant''s action escalated from physically assaultive conduct to the repeated use of a lethal weapon over an unspecified interval of time, we conclude that a reasonable juror could have found that the killing was committed with premeditation and deliberation.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the jury had sufficient evidence from which it could conclude beyond a reasonable doubt that defendant was guilty of first-degree premeditated murder.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In lieu of granting leave to appeal, we reverse Part II of the Court Appeals opinion and hold that, based on the record evidence presented at defendant''s trial, a reasonable juror could have found that the killing was committed with premeditation and deliberation.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we reverse Part II of the Court of Appeals opinion and reinstate defendant''s first-degree premeditated murder conviction and sentence.', 'sentencing', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the nature and number of wounds, plus the fact that the defendant spent "several moments" with the victim, was not sufficient evidence to allow the jury to reasonably infer premeditation and deliberation.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'I don''t know how that evidence is any different in quality from the evidence in Hoffmeister , in which we held that the evidence "le[ft] open the possibility of premeditation and deliberation" but found no basis in the record to conclude that the defendant actually took a second look.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the legislature intended to relieve the state of the burden of proving a defendant''s thought processes by direct evidence.', 'general', 'People of Michigan v. Christopher Allan Oros', 'https://www.courtlistener.com/opinion/4515055/', '4515055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'correctness standard, we affirm the trial court’s decision denying
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Smith’s conviction.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/9997656/', '9997656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s argument detailing the effect of the jury’s finding of an aggravating factor on defendant’s sentence was inaccurate and misleading.', 'sentencing', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, while we are aware that the capable trial judge could not foresee the analysis we undertake today, we conclude that the trial court abused its discretion in overruling defendant’s objection to the State’s argument, which argument contained misleading information.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that the jury’s understanding of aggravating factors is relevant to sentencing, we also find that the prosecutor’s argument introduced error into the trial.', 'sentencing', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we also find that the error was harmless, we affirm the result reached by the Court of Appeals.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because there is no reasonable possibility that but for the error a different result would have been reached, we affirm the result of the Court of Appeals.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals decision upholding the judgments of the trial court.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we reverse the district court’s order revoking Ross’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the phrase "term of supervision" in Wis.', 'general', 'State-Department of Corrections v. Schwarz', 'https://www.courtlistener.com/opinion/1292792/', '1292792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the phrase "term of supervision" in Wis.', 'general', 'State-Department of Corrections v. Schwarz', 'https://www.courtlistener.com/opinion/1292792/', '1292792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature intended to promote offender accountability and, therefore, the DOC had jurisdiction to revoke Dowell''s parole for a violation that he committed during his first period of parole supervision.', 'general', 'State-Department of Corrections v. Schwarz', 'https://www.courtlistener.com/opinion/1292792/', '1292792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because both parties agree that this case presents a question of first impression, we conclude that de novo review is applicable to the case before us.', 'general', 'State-Department of Corrections v. Schwarz', 'https://www.courtlistener.com/opinion/1292792/', '1292792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 844 (1978), in which we held that to qualify as inadvertent a putatively plain view seizure must not be marred by police intent to search for and seize items not described in the warrant.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1293789/', '1293789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse the ruling of the Court of Appeals granting a new trial on four counts but uphold the granting of a new trial on the three remaining counts on which defendant was convicted.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1293789/', '1293789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that it was error to admit as evidence the property seized with respect to these three charges.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1293789/', '1293789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the district court, which affirmed
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in order to prove necessity in this context, a defendant must show that:
(1) there is a present and imminent emergency arising without fault on the part of the actor concerned;', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that public policy mandates that we extend our prior decisions regarding necessity to cases where a defendant is accused of driving under a suspended license.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that fairness demands that the defendant be required to provide notice to the prosecution of his intention to rely on the defense of necessity.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for a new trial.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we reverse on the grounds of the necessity defense, we need not address appellant’s other contention.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
