INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '867 (2002), which addressed a similar due process issue, we conclude that such a civil commitment does not require a separate finding that the individual''s mental disorder involves serious difficulty for such person to control his or her behavior.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we conclude that evidence showing that the person''s mental disorder predisposes such individual to engage in acts of sexual violence, and evidence establishing a substantial probability that such person will again commit such acts, necessarily and implicitly includes proof that such person''s mental *190disorder involves serious difficulty in controlling his or her behavior.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the required proof of lack of control, therefore, may be established by evidence of the individual''s mental disorder and requisite level of dangerousness, which together distinguish a dangerous sexual offender who has serious difficulty controlling his or her behavior from a dangerous but typical recidivist.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the same nexus between the mental disorder and the substantial probability that the person will engage in acts of sexual violence, necessarily and implicitly requires proof that the person''s mental disorder involves serious difficulty for such person in controlling his or her behavior.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we concluded that the definition and use of the term "mental disorder" is sufficiently tailored to satisfy the mental condition component required by substantive due process.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we concluded that treatment is a bona fide objective and goal of ch.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, *196we concluded that the statute''s definition of dangerousness — that a mental disorder makes it substantially probable that the person will engage in acts of sexual violence — is constitutionally sound.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we concluded that the nature and duration of commitment is consistent with the legislature''s purposes of protecting the community and providing treatment for persons suffering from mental disorders that predispose them to commit sexually violent acts.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that ch.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kuntz, this court held that the use of a jury instruction containing a mandatory conclusive presumption on an elemental fact was constitutional error, but the error nevertheless was subject to application of the harmless error rule.', 'jury_instruction', 'State v. Harvey', 'https://www.courtlistener.com/opinion/1296567/', '1296567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, although we conclude that the judicial notice instruction as applied to the "city park" element of the enhanced drug offense in this case was constitutional error, we nevertheless affirm.', 'general', 'State v. Harvey', 'https://www.courtlistener.com/opinion/1296567/', '1296567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in view of the gradual merger of this court''s collective thinking in respect to harmless versus prejudicial error, whether of omission or commission, whether of constitutional proportions or not, the test should be whether there is a reasonable possibility that the error contributed to the conviction.', 'general', 'State v. Harvey', 'https://www.courtlistener.com/opinion/1296567/', '1296567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying Neder here, we conclude that the constitutional instructional error in this case was harmless beyond a reasonable doubt.', 'general', 'State v. Harvey', 'https://www.courtlistener.com/opinion/1296567/', '1296567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, while we conclude that the judicial notice jury instruction, as applied to the "city park" element of the enhanced drug offense in this case, operated as a mandatory conclusive presumption in violation of Harvey''s Fifth and Sixth Amendment rights, we nevertheless affirm his conviction.', 'jury_instruction', 'State v. Harvey', 'https://www.courtlistener.com/opinion/1296567/', '1296567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that when the solicitor violates
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Appellant was not in custody at the time he gave the statements in question.', 'general', 'State v. Easler', 'https://www.courtlistener.com/opinion/1296778/', '1296778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Easler', 'https://www.courtlistener.com/opinion/1296778/', '1296778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'State v. Randle', 'https://www.courtlistener.com/opinion/1296834/', '1296834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that territorial jurisdiction may be waived.', 'general', 'State v. Randle', 'https://www.courtlistener.com/opinion/1296834/', '1296834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that because territorial jurisdiction attached to the original charge of second-degree sexual assault, the trial court necessarily retained jurisdiction over all lesser-included offenses of the original charge, including third-degree sexual assault.', 'general', 'State v. Randle', 'https://www.courtlistener.com/opinion/1296834/', '1296834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Randle waived his right to challenge territorial jurisdiction, because territorial jurisdiction was established, and because Randle failed to prove that he received ineffective assistance of trial counsel, we affirm.', 'ineffective_assistance', 'State v. Randle', 'https://www.courtlistener.com/opinion/1296834/', '1296834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the officers reasonably believed that the girl who let them in had the authority to consent to the limited entry, and because the girl actually did give consent for the officers to enter the house, we hold that the consent to enter the house was valid.', 'general', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, we hold that the State has met its burden on the threshold question.', 'general', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '045(1) have been met, we hold that the threshold question, whether the evidence is admissible under a statutory hearsay exception, has been satisfied.', 'general', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the evidence is admissible under the statutory rules of evidence, we next address whether Tomlinson''s constitutional right to confrontation has nevertheless been violated.', 'general', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we hold that both parts of the test have been met.', 'general', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we agree with the presumption that the jury instruction was *533erroneous, we hold that the error was harmless as it was committed in this case.', 'jury_instruction', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the test is met here.', 'general', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, *537because we are convinced beyond a reasonable doubt that the error did not play any role in the jury''s verdict, we hold that the erroneous instruction was harmless.', 'general', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, although we hold that the circuit court erred in issuing a mandatory conclusive presumption in its jury instructions for the dangerous weapon sentence enhancer, we also hold that the error was harmless.', 'sentencing', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the concepts of Matlock in- that case, we held that the defendant''s father-in-law lacked the actual authority to consent to a police search of a garage attic, which the father-in-law rented to his daughter and the defendant, and in which the couple had essentially established a "separate household.', 'general', 'State v. Tomlinson', 'https://www.courtlistener.com/opinion/1296947/', '1296947') ON CONFLICT DO NOTHING;
