INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that departing from the guidelines because a defendant has failed to appear is not permissible as it does not constitute a clear and convincing reason for departure.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1708584/', '1708584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we hold that a defendant''s acquiescence cannot confer authority on the court for such departure.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1708584/', '1708584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Moyd', 'https://www.courtlistener.com/opinion/1297470/', '1297470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that both courts correctly concluded that the Sixth Amendment as construed in *227 Blakely does apply to the Sentencing Guidelines.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that it was impermissible for "the trial judge, sitting alone" to determine the presence or absence of the aggravating factors required by Arizona law for imposition of the death penalty.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '87 (1993), we held that the provisions of the Guidelines that require a sentence enhancement if the judge determines that the defendant committed perjury do not violate the privilege of the accused to testify on her own behalf.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '389 (1995), we held that the Double Jeopardy Clause did not bar a prosecution for conduct that had provided the basis for an enhancement of the defendant''s sentence in a prior case.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Watts, relying on Witte, we held that the Double Jeopardy Clause permitted a court to consider acquitted conduct in sentencing a defendant under the Guidelines.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this provision must be severed and excised, as must one other statutory section, § 3742(e) (main ed.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While reasonable minds can, and do, differ about the outcome, we conclude that the constitutional jury trial requirement is not compatible with the Act as written and that some severance and excision are necessary.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 232, we concluded that the harm to the victim was an element of the crime.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We concluded that `consideration of information about the defendant''s character and conduct at sentencing does not result in "punishment" for any offense other than the one of which the defendant was convicted.', 'sentencing', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But they failed to make that argument, and, based on our review of the record which showed "a series of interrelated drug transactions involving both cocaine and crack," we concluded that no such claim could succeed.', 'general', 'United States v. Booker', 'https://www.courtlistener.com/opinion/137739/', '137739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that standard here, we conclude that the superior court did not err in granting summary judgment to Chilkoot’s on French’s hostile work environment claim.', 'general', 'French v. Jadon, Inc.', 'https://www.courtlistener.com/opinion/1456082/', '1456082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, although we conclude that AS 18.', 'general', 'French v. Jadon, Inc.', 'https://www.courtlistener.com/opinion/1456082/', '1456082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the summary judgment on the defamation claim and vacate the award of attorney’s fees.', 'general', 'French v. Jadon, Inc.', 'https://www.courtlistener.com/opinion/1456082/', '1456082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we REVERSE the superior court’s grant of summary judgment on the defamation claim, and REMAND to the superior court for proceedings consistent with this opinion.', 'general', 'French v. Jadon, Inc.', 'https://www.courtlistener.com/opinion/1456082/', '1456082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on the remaining issues.', 'general', 'French v. Jadon, Inc.', 'https://www.courtlistener.com/opinion/1456082/', '1456082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM the superior court’s grant of summary judgment on all other issues.', 'general', 'French v. Jadon, Inc.', 'https://www.courtlistener.com/opinion/1456082/', '1456082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in ruling that the State was not required to prove Mr.', 'general', 'Short v. State', 'https://www.courtlistener.com/opinion/1748010/', '1748010') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that same year, we held that a statute criminalizing the operation of a gambling house, Ark.', 'general', 'Short v. State', 'https://www.courtlistener.com/opinion/1748010/', '1748010') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the availability of this evidence to these appellants, we hold that this count of the indictment is not fatally vague or overbroad.', 'general', 'State v. Gunn', 'https://www.courtlistener.com/opinion/1297776/', '1297776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the convictions of those who are not co-conspirators in that crime, holding they were entitled to directed verdicts of acquittal.', 'general', 'State v. Gunn', 'https://www.courtlistener.com/opinion/1297776/', '1297776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conspiracy convictions of appellants Olin Thompson, Ronnie Carpenter, Hazel Carpenter, Cliff Smith, Ed Smith, and Ken Smith for lack of evidence.', 'general', 'State v. Gunn', 'https://www.courtlistener.com/opinion/1297776/', '1297776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conspiracy convictions of appellants Lee Gunn, Evelyn Gunn, Harold Moss, and Earl Childers.', 'general', 'State v. Gunn', 'https://www.courtlistener.com/opinion/1297776/', '1297776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it may not.', 'general', 'Burns v. United States', 'https://www.courtlistener.com/opinion/112620/', '112620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that before a district court can depart upward on a ground not identified as a ground for upward departure either in the presentence report or in a prehearing submission by the Government, Rule 32 requires that the district court give the parties reasonable notice that it is contemplating such a ruling.', 'sentencing', 'Burns v. United States', 'https://www.courtlistener.com/opinion/112620/', '112620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, Cavness has not alleged that the HRS § 702-220 defense of mistake of law applies, and based on our review of the record, we conclude that it does not.', 'general', 'State v. Cavness', 'https://www.courtlistener.com/opinion/1456162/', '1456162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the appeal was moot because Cavness'' and Texhaw, Inc.', 'general', 'State v. Cavness', 'https://www.courtlistener.com/opinion/1456162/', '1456162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on the protections mandated by the West Virginia Constitution, we hold that no chronic alcoholic can be criminally prosecuted for public drunkenness.', 'general', 'State Ex Rel. Harper v. Zegeer', 'https://www.courtlistener.com/opinion/1339742/', '1339742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 793 (1978), we held that this statutory provision is mandatory.', 'general', 'State Ex Rel. Harper v. Zegeer', 'https://www.courtlistener.com/opinion/1339742/', '1339742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Mulvany', 'https://www.courtlistener.com/opinion/1310358/', '1310358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the difficulty that might be experienced in explaining the rationale of concurrent versus consecutive sentencing to young victims is an impermissible factor to consider in determining an appropriate sentence.', 'sentencing', 'State v. Laffey', 'https://www.courtlistener.com/opinion/1310581/', '1310581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that only if such an examination allows an inference of gross disproportion-ality, would the court engage in a detailed consideration of the proportionality of the offense to the sentence, including a comparison of the punishment for this crime with the sentences imposed on other criminals.', 'sentencing', 'State v. Laffey', 'https://www.courtlistener.com/opinion/1310581/', '1310581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a twenty-five-year term of imprisonment for second-degree kidnapping, to be served consecutively to a twenty-five-year term for first-degree robbery, did not violate the Eighth Amendment.', 'general', 'State v. Laffey', 'https://www.courtlistener.com/opinion/1310581/', '1310581') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Laffey’s convictions, preserving for postconviction relief his claim of ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Laffey', 'https://www.courtlistener.com/opinion/1310581/', '1310581') ON CONFLICT DO NOTHING;
