INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'court lacked subject-matter jurisdiction, and we reverse and dismiss Standridge’s conviction.', 'dismissal', 'Standridge v. State', 'https://www.courtlistener.com/opinion/2759875/', '2759875') ON CONFLICT DO NOTHING;
