INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 26 (1975), we held that an argument which was factually incorrect was not cured by a general charge which stated that arguments were not evidence because the general charge was undirected to the particular argument.', 'general', 'State v. Lapham', 'https://www.courtlistener.com/opinion/1948525/', '1948525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that there must be some prior acquaintanceship or contacts between the lay witness and the defendant which forms a reasonable basis to justify the opinion sought to be introduced concerning insanity.', 'general', 'State v. Lapham', 'https://www.courtlistener.com/opinion/1948525/', '1948525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 105 (1979), we held that this provision precludes a court from continuing the probation of one later convicted of a crime.', 'general', 'State v. Holcomb', 'https://www.courtlistener.com/opinion/1323303/', '1323303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the consecutive sentence imposed did not violate the prohibition against double jeopardy.', 'sentencing', 'State v. Holcomb', 'https://www.courtlistener.com/opinion/1323303/', '1323303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was sufficient evidence before the trial
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'as a suspect in another crime, we found that error to be harmless.', 'general', 'Michael Inman v. State of Indiana', 'https://www.courtlistener.com/opinion/2653485/', '2653485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Inman’s conviction and sentence.', 'sentencing', 'Michael Inman v. State of Indiana', 'https://www.courtlistener.com/opinion/2653485/', '2653485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Inman’s conviction and sentence.', 'sentencing', 'Michael Inman v. State of Indiana', 'https://www.courtlistener.com/opinion/2653485/', '2653485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "neither Blakely nor Allen preclude the trial court from assigning a point in the calculation of one''s prior record level where `all the elements of the present offense are included in [a] prior offense.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*604 Upon examination of the issue, we conclude that whether an out-of-state offense is substantially similar to a North Carolina offense is a question of law that must be determined by the trial court, not the jury.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the question of whether a conviction under an out-of-state statute is substantially similar to an offense under North Carolina statutes is a question of law to be resolved by the trial court.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court erred in finding New York''s second-degree assault to be substantially similar to North Carolina''s assault inflicting serious injury, which is a Class A1 misdemeanor, as opposed to simple assault, which is a Class 2 misdemeanor.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State had argued that defendant had stipulated to the fact that the New York offenses were substantially similar to the North Carolina offenses, but we found that defendant had not so stipulated, and thus that the State had not met its burden under N.', 'general', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court''s order and judgment sentencing defendant to 251 to 311 months imprisonment, and grant defendant a new sentencing hearing.', 'sentencing', 'State v. Hanton', 'https://www.courtlistener.com/opinion/1279271/', '1279271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree in part, and, therefore, we reverse in part and affirm in part.', 'general', 'State v. Welch', 'https://www.courtlistener.com/opinion/2638805/', '2638805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse the conviction and sentence for the possession of chemicals and equipment for manufacturing methamphetamine.', 'sentencing', 'State v. Welch', 'https://www.courtlistener.com/opinion/2638805/', '2638805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 15 For the foregoing reasons, we affirm the convictions and sentences for the manufacture of the dangerous drug methamphetamine and for the possession of drug paraphernalia.', 'sentencing', 'State v. Welch', 'https://www.courtlistener.com/opinion/2638805/', '2638805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'Cuellar v. State', 'https://www.courtlistener.com/opinion/1591416/', '1591416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Court of Appeals.', 'general', 'Cuellar v. State', 'https://www.courtlistener.com/opinion/1591416/', '1591416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, the Court held that “[bjecause the perceived evils these statutes attempt to combat are distinct, we conclude that the legislature’s intent was to proscribe and punish separately the offenses of felonious possession of cocaine and of trafficking in cocaine by possession.', 'general', 'State v. Ezell', 'https://www.courtlistener.com/opinion/1284851/', '1284851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful analysis, we conclude that the present case is analogous
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because defendant’s conduct is “covered under some other provision of law providing greater punishment,” we conclude that the court cannot convict and sentence him for both §§ 14-32 and 14-32.', 'sentencing', 'State v. Ezell', 'https://www.courtlistener.com/opinion/1284851/', '1284851') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute is not unconstitutional and that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'review, we conclude that the commissioner did not err by determining that Gustafson
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'Jason Daniel Gustafson, Relator v. Commissioner of Human Services', 'https://www.courtlistener.com/opinion/4241315/', '4241315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying established Arizona precedent, the most recent example of which is Dolny, to which we adhere, we hold that respondent is not entitled to a jury trial as of right under Arizona law, even assuming he would, if convicted, be a prohibited firearms possessor under federal law.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the most recent case in which this court spoke on this issue, we held that a defendant charged with possession of marijuana was entitled to a jury trial.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in Rothweiler this court held that a defendant charged with driving under the influence was entitled to a jury trial.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held, in Spitz v.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held "that where a defendant is charged with several petty offenses, factually related or arising out of a single event, there is no constitutional requirement of a jury trial, but the actual punishment may not exceed that which would be permissible without a jury trial in case of a single offense.', 'general', 'State Ex Rel. McDougall v. Strohson', 'https://www.courtlistener.com/opinion/1198152/', '1198152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that armed robbery is a crime of dishonesty under Rule 609(a)(2).', 'general', 'State v. Al-Amin', 'https://www.courtlistener.com/opinion/1408886/', '1408886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), this Court held that armed robbery could be used to test the credibility of a testifying defendant because it was a form of larceny, a crime which involves dishonesty.', 'general', 'State v. Al-Amin', 'https://www.courtlistener.com/opinion/1408886/', '1408886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Al-Amin', 'https://www.courtlistener.com/opinion/1408886/', '1408886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the case before us, we hold that Detective Pantke''s questioning of defendant Eastlack was entirely proper and was squarely within the boundaries set by both the majority opinion and the concurrence in Davis.', 'general', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite what may have been dilatory behavior on the part of defense counsel, we hold that, under the peculiar facts and circumstances of this case, it was improper to proceed to sentencing without providing defendant the opportunity of expert assistance.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that the trial court was well within its discretion in denying the motion for mistrial.', 'mistrial', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of circumstances, we conclude that the present sentences must be vacated and remanded for resentencing after the appointment of an appropriate expert to assist defendant in determining whether there is additional mitigating evidence to be presented and, if so, to assist defendant in presenting it.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all factors, we conclude that the appointment of an independent expert might well have produced mitigating evidence.', 'general', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we have problems with the "no appreciable space of time" language, we find that the remaining portions of the instructions clarified the definition of premeditation.', 'general', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having thoroughly reviewed the record, we find that defendant had the constitutional and statutory right to the assistance of proper psychological testing and expert assistance.', 'general', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons we develop more fully below, we affirm all of defendant''s convictions but remand for resentencing.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Apelt, the defendant moved to continue his sentencing hearing claiming that he was unable to adequately prepare, but we affirmed the trial judge''s denial of that motion.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial judge should have continued the sentencing hearing, done whatever was necessary to regularize the proceedings, and arranged for the appointment of an appropriate expert at reasonable cost before proceeding to sentencing in this capital case.', 'sentencing', 'State v. Eastlack', 'https://www.courtlistener.com/opinion/1388836/', '1388836') ON CONFLICT DO NOTHING;
