INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this issue is procedurally barred.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/1755805/', '1755805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Todd, this Court held that, "[i]n any case, Brady requires a `reasonable probability'' of a different outcome, not a mere possibility.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/1755805/', '1755805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we find that the record is devoid of proof that Montgomery attempted to subpoena the documents.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/1755805/', '1755805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case sub judice, regarding the exculpatory evidence, we find that Montgomery fails to satisfy the first and third prongs of the four-prong Brady test.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/1755805/', '1755805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this instruction would have been an improper comment upon the weight of the testimony.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/1755805/', '1755805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the ruling in Broadhead, we find that the trial judge did not abuse his discretion in prohibiting the cumulative testimony of Larry Montgomery.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/1755805/', '1755805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court did not commit reversible error in denying Montgomery''s motion for directed verdict and motion for a new trial on the ground that the offense she allegedly committed constituted larceny and not embezzlement.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/1755805/', '1755805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no merit in Montgomery''s assignments of error, we affirm the judgment of the Lee County Circuit Court.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/1755805/', '1755805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '81 NW2d 669 (1957), in which we held that the Legislature has the exclusive authority to determine the appropriate length of imprisonment for a felony and that a court, in imposing a sentence, has only limited discretion to act within the parameters set forth in the statute.', 'sentencing', 'People v. Coles', 'https://www.courtlistener.com/opinion/1733341/', '1733341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In order to ensure that the purpose of indeterminate sentencing could not be undermined by a sentencing court, this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a sentence following a conviction is as much a part of the final judgment of the trial court as is the conviction itself.', 'sentencing', 'People v. Coles', 'https://www.courtlistener.com/opinion/1733341/', '1733341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'quirement would further burden the appellate process, and thus we conclude that imposing the duty to resentence a defendant on the appellate courts is both unnecessary and unwise.', 'sentencing', 'People v. Coles', 'https://www.courtlistener.com/opinion/1733341/', '1733341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such sentences should be subject to appellate review and relief when warranted.', 'sentencing', 'People v. Coles', 'https://www.courtlistener.com/opinion/1733341/', '1733341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing analysis, we conclude that the existing scope of appellate review of sentences should be expanded.', 'sentencing', 'People v. Coles', 'https://www.courtlistener.com/opinion/1733341/', '1733341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that no manifest injustice resulted from the failure to give such an instruction.', 'general', 'People v. Coles', 'https://www.courtlistener.com/opinion/1733341/', '1733341') ON CONFLICT DO NOTHING;
