INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead we hold that L.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/4776719/', '4776719') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And we hold that that reasonableness inquiry must account
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that once the State has used a victim’s reliable hearsay to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, we hold that any authority a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that any power a defendant has to compel a victim
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in that case we held that the 1995 Victims’ Rights Amendment “clearly
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the unreasonableness inquiry must account for the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶32 We conclude that the key to balancing these various
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence as to this element of murder in the first degree as an accessory before the fact is less than overwhelming.', 'general', 'State v. Arnold', 'https://www.courtlistener.com/opinion/1348147/', '1348147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State having failed to prove that the error was harmless beyond a reasonable doubt, we hold that defendant was prejudiced by the trial court''s error and her conviction for murder in the second degree was properly reversed.', 'general', 'State v. Arnold', 'https://www.courtlistener.com/opinion/1348147/', '1348147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that there was no error in the failure of the trial court to dismiss the conspiracy charge.', 'dismissal', 'State v. Arnold', 'https://www.courtlistener.com/opinion/1348147/', '1348147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming, arguendo, that the trial court erred, we hold that the defendant was not prejudiced because there does not exist a reasonable possibility that a different outcome would have resulted absent the error.', 'general', 'State v. Arnold', 'https://www.courtlistener.com/opinion/1348147/', '1348147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the evidence supports the trial court''s decision.', 'general', 'State v. Arnold', 'https://www.courtlistener.com/opinion/1348147/', '1348147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Strickland, this Court held that a trial court is not required to submit lesser included offenses as possible jury verdicts where there is no evidence to support such lesser included offense.', 'ineffective_assistance', 'State v. Arnold', 'https://www.courtlistener.com/opinion/1348147/', '1348147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 278 (1984), and therefore we conclude that the husband-wife relationship permits the finding of this factor.', 'general', 'State v. Arnold', 'https://www.courtlistener.com/opinion/1348147/', '1348147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that mention of the lie detector test as the trigger point for Gerry''s decision to cooperate and the related issue of his lawyer''s vouching for Gerry''s credibility were improper but not reversible error in light of the trial judge''s limiting instruction and the totality of all the evidence presented in this long trial.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the quotations from Fahey going to her state of mind were properly admitted under established exceptions to the hearsay rules.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge was correct in not instructing the jury on the lesser included offenses.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge erroneously limited Capano''s allocution by not permitting him to discuss or argue in allocution from facts already in the record.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we hold that this error was harmless under all the circumstances and Capano was not unduly prejudiced.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the authority relied on by Capano does not support this argument.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Delaware Death Penalty Statute is constitutional and was properly applied here.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On harmless error analysis, therefore, we hold that the erroneous admission of Lyons'' testimony concerning Gerry''s polygraph test and his improper vouching did not substantially prejudice the defense and that admission of this testimony does not warrant a reversal of Capano''s conviction and sentence.', 'sentencing', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence produced at trial does not provide a rational basis for "a verdict acquitting the defendant of the offense charged and convicting the defendant of the included offense.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that as a matter of Delaware''s law of allocution, any erroneous limitations placed on Capano''s right of allocution and the trial judge''s colloquy with Capano in front of the jury, although regrettable, did not prejudice Capano and do not entitle him to a new penalty hearing.', 'general', 'Capano v. State', 'https://www.courtlistener.com/opinion/1494221/', '1494221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "the Legislature contemplated a requirement of something more than the mere exertion of physical effort necessary to commit the lewd act" to sustain a conviction for molestation of a juvenile.', 'general', 'State v. Schenck', 'https://www.courtlistener.com/opinion/1708824/', '1708824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the substance of San Martin''s interview with Detective Nabut concerning the whereabouts of the weapons used in the crime was admissible because it was individually self-incriminatory.', 'general', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, where a nontestifying codefendant''s confession incriminating the defendant is not directly admissible against the defendant, the Confrontation *1321 Clause bars its admission at their joint trial, even if the jury is instructed not to consider it against the defendant, and even if the defendant''s own confession is admitted against him.', 'general', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 128 (1991), we held that a capital murder defendant, who had also been convicted of three other offenses which carried lengthy maximum penalties, was not entitled to an instruction informing the jury of the maximum sentences for other crimes as a mitigating factor.', 'sentencing', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that, although the trial judge did not permit questioning about the prospective jurors'' personal views of what constitutes a mitigating circumstance, it was not an abuse of discretion since defense counsel was able to explore the potential jurors'' understanding of the two-part procedure involved and their ability to follow the law as instructed by the judge in the penalty phase.', 'general', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gray, this Court held that the crime of attempted felony murder no longer existed in the State of Florida and directed that our decision would be applied to all cases pending on direct review or not yet final.', 'general', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'May 16, 1997), in which this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After Valentine was sentenced, this Court held that the crime of attempted first-degree felony murder does not exist in Florida See State v.', 'sentencing', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though there is language in Cruz which may lend to an argument that error in the admission of interlocking confessions prohibits the error from being harmless, upon close analysis we conclude that both Cruz and Wright authorize a harmless-error review.', 'general', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the trial court did not err in finding the cold, calculated, and premeditated aggravator.', 'general', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the error in admitting San Martin''s confession was also harmless *1329 in the penalty phase because San Martin said nothing in his confession that was adverse to Franqui that was not contained in Franqui''s confession.', 'general', 'Franqui v. State', 'https://www.courtlistener.com/opinion/1723720/', '1723720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Hunter’s conviction and sentence for sexual exploitation of a minor.', 'sentencing', 'State v. Hunter', 'https://www.courtlistener.com/opinion/1711299/', '1711299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statute is constitutional if construed to require proof that the defendant’s sole intent was to annoy or harass the recipient of the telephone call, but we reverse McKillop’s conviction because the instructions his trial jury received did not
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '120(a)(4), we hold that the statute is neither vague nor overbroad.', 'general', 'McKillop v. State', 'https://www.courtlistener.com/opinion/1121449/', '1121449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Beckwith did not abuse her discretion when she refused to give McKillop’s proposed definitions to the jury.', 'general', 'McKillop v. State', 'https://www.courtlistener.com/opinion/1121449/', '1121449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the scope of the statute is potentially so broad, we conclude that AS 11.', 'general', 'McKillop v. State', 'https://www.courtlistener.com/opinion/1121449/', '1121449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we REVERSE McKillop’s harassment conviction and remand his case to the district court for a new trial.', 'general', 'McKillop v. State', 'https://www.courtlistener.com/opinion/1121449/', '1121449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that summary dismissal may be proper when, as in this case, the petitioner fails to attach to the habeas corpus petition pertinent documents from the record of the underlying proceedings to support his factual assertions.', 'dismissal', 'Summers v. State', 'https://www.courtlistener.com/opinion/1580727/', '1580727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the face of the judgment does not establish that the concurrent sentence for misdemeanor escape is void and illegal.', 'sentencing', 'Summers v. State', 'https://www.courtlistener.com/opinion/1580727/', '1580727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that Hickman was no longer imprisoned or restrained of liberty on the ten-day sentence he had received sixteen years earlier.', 'sentencing', 'Summers v. State', 'https://www.courtlistener.com/opinion/1580727/', '1580727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Benson was not presently “imprisoned or restrained of liberty” by any of the 1993 convictions because the sentences complained of were served and expired before Benson filed a habeas corpus petition to challenge them.', 'sentencing', 'Summers v. State', 'https://www.courtlistener.com/opinion/1580727/', '1580727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appointment of counsel is not necessary within the meaning of section 40-14-204 merely because a petition states a cognizable claim for habeas corpus relief.', 'habeas', 'Summers v. State', 'https://www.courtlistener.com/opinion/1580727/', '1580727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the escape judgment is facially valid and Summers failed to support his factual assertions with pertinent documents from the record of the underlying proceedings, we conclude that summary dismissal was proper.', 'dismissal', 'Summers v. State', 'https://www.courtlistener.com/opinion/1580727/', '1580727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Criminal Appeals and reinstate the trial court’s judgment dismissing the petition for writ of habeas corpus.', 'dismissal', 'Summers v. State', 'https://www.courtlistener.com/opinion/1580727/', '1580727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Criminal Appeals and reinstate the trial court’s judgment dismissing the habeas corpus petition.', 'dismissal', 'Summers v. State', 'https://www.courtlistener.com/opinion/1580727/', '1580727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Article I, Section 7 of the Minnesota Constitution prohibits a court from setting a monetary bail amount that can be satisfied only by a cash deposit in the full amount of bail set by the court.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Pettwe held that, following the abolishment of capital punishment in Minnesota, all crimes are bailable.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In construing the section 7 Bail Clause, we held that our constitution guarantees broader protection than the Eighth Amendment of the United States Constitution by providing that all crimes are bailable.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that cash only bail violates Minnesota''s Constitution, we reverse.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this phrase is unambiguous and that it prohibits cash only bail.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, to the extent that we conclude that the section 7 Bail Clause prohibits the court from setting a monetary bail amount that can be satisfied only by a cash deposit in the full amount of bail set by the court, our conclusion is consistent with the purpose of Rule 6.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the court of appeals and remand this matter to the district court for any further proceedings necessary for the actions of that court to be consistent with this opinion.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1615231/', '1615231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s decision was without error, structural or otherwise.', 'general', 'State v. Prevatte', 'https://www.courtlistener.com/opinion/1233870/', '1233870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, because we hold that defendant’s motion for new counsel was handled properly, we also reject defendant’s equal protection claim.', 'general', 'State v. Prevatte', 'https://www.courtlistener.com/opinion/1233870/', '1233870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State’s argument merely reemphasized what the jury already knew, namely, that if defendant was found guilty, additional evidence would be submitted on the question of defendant’s sentence.', 'sentencing', 'State v. Prevatte', 'https://www.courtlistener.com/opinion/1233870/', '1233870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly handled the portions of argument in issue.', 'general', 'State v. Prevatte', 'https://www.courtlistener.com/opinion/1233870/', '1233870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence in this case justified the submission of the (e)(9) aggravating circumstance.', 'general', 'State v. Prevatte', 'https://www.courtlistener.com/opinion/1233870/', '1233870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this overwhelming evidence, we hold that the (e)(9) aggra: vating circumstance was properly submitted to the jury.', 'general', 'State v. Prevatte', 'https://www.courtlistener.com/opinion/1233870/', '1233870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the record, we hold that the trial court’s instructions here were not like those given in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we held that if an aggravating circumstance could be supported by the evidence, the State must submit it.', 'general', 'State v. Prevatte', 'https://www.courtlistener.com/opinion/1233870/', '1233870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that argument did
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that
