INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To reiterate, we conclude that the trial court erred in enhancing the sentences for aggravated assault on the basis of Tenn.', 'sentencing', 'State v. Imfeld', 'https://www.courtlistener.com/opinion/1591751/', '1591751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record and applicable authority, we conclude that the lower courts erred in applying the “multiple victims” and “potential bodily injury to a victim” enhancement factors,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals.', 'general', 'State v. Imfeld', 'https://www.courtlistener.com/opinion/1591751/', '1591751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court’s failure to provide a definition for the term in its charge to the jury was not error.', 'general', 'State v. Jett', 'https://www.courtlistener.com/opinion/1406197/', '1406197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the trial court did not err in refusing to give the appellant’s instruction defining “attempt.', 'general', 'State v. Jett', 'https://www.courtlistener.com/opinion/1406197/', '1406197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we find that the word “attempt” as used by the trial court in its instruction to the jury is a common term which is widely used and generally understandable to the average person.', 'general', 'State v. Jett', 'https://www.courtlistener.com/opinion/1406197/', '1406197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the appellant’s proffered instruction is not substantively correct.', 'general', 'State v. Jett', 'https://www.courtlistener.com/opinion/1406197/', '1406197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” After careful consideration, we affirm the appellant’s conviction.', 'general', 'State v. Jett', 'https://www.courtlistener.com/opinion/1406197/', '1406197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no merit to the appellant’s assignment of error, we affirm the appellant’s January 27, 2005, conviction of the felony offense of operating or attempting to operate a clandestine drug laboratory pursuant to W.', 'general', 'State v. Jett', 'https://www.courtlistener.com/opinion/1406197/', '1406197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge''s findings in support of the sentence of death even without the finding of especially heinous, atrocious and cruel, meet the Tedder standard.', 'sentencing', 'Mills v. State', 'https://www.courtlistener.com/opinion/1688713/', '1688713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), we held that the underlying felony is not a necessarily lesser included offense of felony murder.', 'general', 'Mills v. State', 'https://www.courtlistener.com/opinion/1688713/', '1688713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court''s finding that there were no mitigating circumstances was correct.', 'general', 'Mills v. State', 'https://www.courtlistener.com/opinion/1688713/', '1688713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the imposition of a sentence of death after a jury recommendation of life was proper in this case.', 'sentencing', 'Mills v. State', 'https://www.courtlistener.com/opinion/1688713/', '1688713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there were no mitigating circumstances, we find that the court''s erroneous finding of two statutory aggravating circumstances was harmless and did not impair the sentencing process.', 'sentencing', 'Mills v. State', 'https://www.courtlistener.com/opinion/1688713/', '1688713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the facts suggesting a sentence of death are so clear and convincing that virtually no reasonable person could differ.', 'sentencing', 'Mills v. State', 'https://www.courtlistener.com/opinion/1688713/', '1688713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the court did not abridge Mills'' right to confront the witnesses against him.', 'general', 'Mills v. State', 'https://www.courtlistener.com/opinion/1688713/', '1688713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Harrold, supra, this court held that the trier of fact''s finding that the visual depiction of a man masturbating appealed to the prurient interest was not clearly wrong.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in our review of part B(1) and (2), for the purpose of declaratory judgment, we substitute our findings for that of the trier of fact only if we conclude that the trier of fact''s determination is clearly wrong.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our de novo review of part B(3), we conclude that the State did not prove beyond a reasonable doubt that "Takin'' It to the Jury" lacked any serious literary, artistic, political, or scientific value.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of exhibits 18 through 23 was error.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the admission of this testimony was prejudicial error, since the county attorney did not qualify as an expert.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, the State bears the burden of proving beyond a reasonable doubt all three elements of obscenity, and we find that this assignment of error is without merit.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the determination made by the district court under part B(3) as to exhibit 9.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 299 (1999), we affirmed the trier of facts finding that the visual depiction of a man masturbating appealed to the prurient interest, we do not compare that finding to the finding by the trier of fact in this case.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered the State''s assignments of error and finding that they have no merit, we affirm the judgment of the district court as modified.', 'general', 'Main Street Movies, Inc. v. Wellman', 'https://www.courtlistener.com/opinion/1793421/', '1793421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'that there may be circumstances under which the denial of funds for a pollster by a district court would be an abuse of discretion, we conclude that under the circumstances of this case, where no evidence to support the motion was offered, the district court did not abuse its discretion.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1804781/', '1804781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that defendant made no argument in his motion, when he objected, or in his brief which specifically addressed article I, § 11, we find that he has failed to meet his burden.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1804781/', '1804781') ON CONFLICT DO NOTHING;
