INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these cases, we conclude that nothing about E.', 'general', 'EC v. State', 'https://www.courtlistener.com/opinion/1847723/', '1847723') ON CONFLICT DO NOTHING;
