INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances, we hold that the district court did not err by allowing the State’s witnesses to testify about Diane’s prior consistent statements pursuant to W.', 'general', 'Lacey v. State', 'https://www.courtlistener.com/opinion/1131587/', '1131587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Appellant is not entitled to a new trial on the basis that the State utilized perjured testimony.', 'general', 'Lacey v. State', 'https://www.courtlistener.com/opinion/1131587/', '1131587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of that testimony and in the absence of a finding that Diane committed perjury, we hold that Appellant is not entitled to a new trial on the basis that the State violated his right to confront adverse witnesses.', 'general', 'Lacey v. State', 'https://www.courtlistener.com/opinion/1131587/', '1131587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that testimony, the suspicious nature of the recanting testimony, and the district court’s conclusion that Diane’s testimony at the motion hearing lacked credibility, we hold that the district court did not abuse its discretion by denying Appellant’s motion for a new trial.', 'general', 'Lacey v. State', 'https://www.courtlistener.com/opinion/1131587/', '1131587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not abuse, its discretion when it enhanced two sentences for two convictions arising out of a single occurrence.', 'sentencing', 'Lacey v. State', 'https://www.courtlistener.com/opinion/1131587/', '1131587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We held that three convictions arising out of one occurrence could only count as one previous conviction under § 6-10-201 because they “were not ‘separately brought and tried'' nor did they arise out of ‘separate occurrences.', 'general', 'Lacey v. State', 'https://www.courtlistener.com/opinion/1131587/', '1131587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Lacey v. State', 'https://www.courtlistener.com/opinion/1131587/', '1131587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because the attempt occurs during the commission of a felony, the law, as it does under the felony murder doctrine, presumes the existence of the specific intent required to prove attempt.', 'general', 'State v. Gray', 'https://www.courtlistener.com/opinion/1774394/', '1774394') ON CONFLICT DO NOTHING;
