INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '650(9), and we conclude that it would not be proper for us to imply this missing language where the Legislature has obviously intended that it be omitted.', 'general', 'Maddox v. State', 'https://www.courtlistener.com/opinion/1882515/', '1882515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we conclude that the Legislature intended that the phrase "any trial" in section 316.', 'general', 'Maddox v. State', 'https://www.courtlistener.com/opinion/1882515/', '1882515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the State''s assertion may be true, we conclude that this is a distinction without a material difference.', 'general', 'Maddox v. State', 'https://www.courtlistener.com/opinion/1882515/', '1882515') ON CONFLICT DO NOTHING;
