INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the determination of "dangerousness" is of import to FSPA, and that the State''s reliance on Conn.', 'general', 'Espindola v. State', 'https://www.courtlistener.com/opinion/1910142/', '1910142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, as several courts of other jurisdictions have done before us, we find that this total failure to provide for a judicial hearing on the risk of the defendant''s committing future offenses, makes it violative of procedural due process, and therefore unconstitutional.', 'general', 'Espindola v. State', 'https://www.courtlistener.com/opinion/1910142/', '1910142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we find that in the absence of a provision allowing for a hearing to determine whether the defendant presents a danger to the public sufficient to require registration and public notification, the Florida Sexual Predators Act violates procedural due process.', 'general', 'Espindola v. State', 'https://www.courtlistener.com/opinion/1910142/', '1910142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'Espindola v. State', 'https://www.courtlistener.com/opinion/1910142/', '1910142') ON CONFLICT DO NOTHING;
