INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not abuse its discretion in denying the motion for change of venue or venire filed by Drumheller.', 'general', 'Commonwealth v. Drumheller', 'https://www.courtlistener.com/opinion/1931673/', '1931673') ON CONFLICT DO NOTHING;
