INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 18, 29 (1979), we held that §§ 29- 2521.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the reports were material because they would have led to the discovery of other witnesses and that it was error not to grant a continuance to the defendant in light of the prosecution''s delay in producing the reports.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 429 (1985), this court held that evidence of a codefendant''s conviction was inadmissible and denied the defendant her right to a fair trial.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'McHenry, supra, this court held that the underlying felony merges into a felony murder conviction and cannot be punished separately, barring a clear indication by the Legislature that independent punishments were intended.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 359, 386 (1990), this court held that the term "`apparent''" as used in subsection (1)(b) means "`readily perceptible,'' and therefore `the provision cannot be applied in speculative situations or where a strained construction is necessary to fulfill it.', 'general', 'State v. Lotter', 'https://www.courtlistener.com/opinion/2116540/', '2116540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that the failure to admonish did not require the circuit court to allow defendant''s motion.', 'general', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because a defendant''s right to waive a jury trial and enter a guilty plea will not necessarily be harmed in the absence of the admonishment, we conclude that the presumption of a directory reading of section 113-8 is not overcome.', 'plea', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As neither condition articulated in Robinson serves to overcome the presumption of a directory reading in this case, we conclude that the legislature intended such a reading.', 'general', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that section 113-8 is mandatory in that it imposes an obligation on the circuit court to admonish all defendants of the potential immigration consequences of a guilty plea.', 'plea', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As noted above, we concluded that the statute in that case was directory.', 'general', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the judgment of the appellate court, vacating denial of defendant''s motion to withdraw his guilty plea, and affirm the judgment of the circuit court.', 'plea', 'People v. Delvillar', 'https://www.courtlistener.com/opinion/2169385/', '2169385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant in a civil suspension proceeding may challenge the reasonableness of the underlying stop pursuant to 23 V.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the stops in the two cases before us, we conclude that defendant Steven Lussier was lawfully stopped for operating a motor vehicle with only one functioning taillight, but that defendant Robert Lussier was unlawfully stopped for operating a vehicle with only one functioning rear license plate light.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that, in permitting defendants in a civil suspension proceeding to dispute whether the processing officer had reasonable grounds to believe that the motorist was driving while intoxicated, the Legislature assumed that a constitutional stop would be a necessary predicate to finding "reasonable grounds" for suspicion of DUI.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 981, 982 (1992), we conclude that it is appropriate to apply the exclusionary rule in civil license suspension proceedings to protect the core value of privacy embraced in Article 11, to promote the public''s trust in the judicial system, and to *1027 assure that unlawful police conduct is not encouraged.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we concluded that the State should not have to risk losing the criminal case because of how the issue was presented in the summary civil suspension proceeding.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the federal regulations under our earlier analysis, we find that they require passenger vehicles to display only one rear white license plate lamp to illuminate the plate from the top or sides.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a decision issued April 28, 2000, we reversed a district court decision and held that a defendant in a civil suspension proceeding may challenge the reasonableness of the underlying stop.', 'general', 'State v. Lussier', 'https://www.courtlistener.com/opinion/2156801/', '2156801') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence tending to connect Albert with wadcutter bullets just like the one found in Tappa’s body sufficiently corroborated Williamson’s testimony.', 'general', 'State v. Ware', 'https://www.courtlistener.com/opinion/2223508/', '2223508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 895, 900 (Iowa 1980), we held that the denial of a motion to sever will be deemed ah abuse of discretion only if the defendant proves sufficient prejudice to constitute a denial of a fair trial.', 'general', 'State v. Ware', 'https://www.courtlistener.com/opinion/2223508/', '2223508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 682, 686 (Iowa 1980), we held that recklessness is a necessary element in involuntary manslaughter.', 'general', 'State v. Ware', 'https://www.courtlistener.com/opinion/2223508/', '2223508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 62, 66 (Iowa 1982), we held that the word “act” in the section 707.', 'general', 'State v. Ware', 'https://www.courtlistener.com/opinion/2223508/', '2223508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that if a major offense consists of three elements, with the lesser offense consisting of only two of those elements, the lesser offense need not be submitted if the record does not contain substantial evidence from some quarter controverting the third element— that which elevates the lesser offense to the greater offense.', 'general', 'State v. Ware', 'https://www.courtlistener.com/opinion/2223508/', '2223508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we found that the adverse effect of other-crimes evidence introduced against a co-defendant so implicated the defendant as to establish unfair prejudice and require separate trials.', 'general', 'State v. Ware', 'https://www.courtlistener.com/opinion/2223508/', '2223508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no merit in any of Albert’s contentions, we affirm.', 'general', 'State v. Ware', 'https://www.courtlistener.com/opinion/2223508/', '2223508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was insufficient to sustain the conviction as a matter of law, and reverse.', 'general', 'State v. Robar', 'https://www.courtlistener.com/opinion/2188298/', '2188298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we find that Atkins’ inquest testimony meets the test for reliability laid out in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the evidence insufficient to support the conviction, we reverse defendant’s conviction and do not reach the third issue.', 'general', 'State v. Robar', 'https://www.courtlistener.com/opinion/2188298/', '2188298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that they do not.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the importance of the people''s reservation of the power of initiative and the minimal nature of the intrusion on the rights of the mall owners, we hold that allowing citizens to engage in initiative activity in large, privately owned shopping malls subject to reasonable time, place, and manner restrictions, does not unreasonably restrict the mall owners'' rights.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Const 1963, art 2, § 9, authorizes initiative activity in the common areas of large, privately owned shopping malls, subject to reasonable time, place, and manner restrictions, and that the minimal intrusion on the rights of the mall owners is justified in view of the importance of the power of initiative reserved by the people.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that the intrusion on the rights of the shopping center owners by the activities of *248 persons seeking signatures on initiative petitions is minimal.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Court of Appeals in Woodland v Michigan Citizens Lobby, and we reverse the decision of the trial court in Equitable Life Assurance v Michigan Citizens Lobby.', 'general', 'Woodland v. Michigan Citizens Lobby', 'https://www.courtlistener.com/opinion/2189706/', '2189706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons set out below, we reverse and dismiss.', 'dismissal', 'State v. Metzger', 'https://www.courtlistener.com/opinion/2206575/', '2206575') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that when the motion for judgment of acquittal did not make reference to the specific elements of the crime on which the evidence was claimed to be insufficient, it did not preserve the sufficiency of the evidence issue for review.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1278176/', '1278176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the district court.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1278176/', '1278176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the district court.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1278176/', '1278176') ON CONFLICT DO NOTHING;
