INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'that follow, we affirm the judgment of the Court of Criminal Appeals.', 'general', 'State v. Hoxie', 'https://www.courtlistener.com/opinion/1060908/', '1060908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State to make an election, we affirm the judgment of the Court of Criminal
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“lesser grade” holding is not supported by Tennessee law and is unworkable in application, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the indictment in this case is not sufficient to support a conviction for spousal rape, we reverse the judgment of the Court of Criminal Appeals, vacate the defendant’s convictions, dismiss the indictments, and remand this case to the trial court for further proceedings consistent with this decision.', 'dismissal', 'State v. Dominy', 'https://www.courtlistener.com/opinion/2277095/', '2277095') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 17 Because we find that sufficient evidence existed to support the conviction, we affirm.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/2633811/', '2633811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the conduct at issue here is sufficient to support a conviction, we affirm.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/2633811/', '2633811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the informant’s identifications were properly admitted at trial despite the unnecessarily suggestive identification procedure.', 'general', 'State v. Nigro', 'https://www.courtlistener.com/opinion/2328075/', '2328075') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 24] Applying these criteria to the case before us, we conclude that the informant’s identification of Nigro was independently reliable.', 'general', 'State v. Nigro', 'https://www.courtlistener.com/opinion/2328075/', '2328075') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Nigro', 'https://www.courtlistener.com/opinion/2328075/', '2328075') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'accordingly, we affirm.', 'general', 'Stivers v. State', 'https://www.courtlistener.com/opinion/2331320/', '2331320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court erred by declining to give Ogilvie’s requested charge on accident, we reverse.', 'general', 'Ogilvie v. State', 'https://www.courtlistener.com/opinion/2503625/', '2503625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the trial court’s failure to charge on accident under OCGA § 16-2-2, holding, “[t]he fact that there was no criminal scheme or undertaking or criminal negligence is not a defense to a ‘strict criminal liability’ motor vehicle safety statute.', 'general', 'Ogilvie v. State', 'https://www.courtlistener.com/opinion/2503625/', '2503625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"In the present case, we hold that the evidence of concealment was insufficient to sustain the convictions of obstruction of justice.', 'general', 'People v. Comage', 'https://www.courtlistener.com/opinion/2523452/', '2523452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court.', 'general', 'People v. Comage', 'https://www.courtlistener.com/opinion/2523452/', '2523452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, although the circumstances show that appellant probably intended to enter the Alfred house with intent to commit theft, his behavior after removal of the screen was sufficiently inexplicable that reasonable doubt remains as to what his specific criminal intentions actually were.', 'general', 'Gear v. State', 'https://www.courtlistener.com/opinion/2538612/', '2538612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We conclude that, although the circumstances show that appellant probably intended to enter the Alfred house with intent to commit theft, his behavior after removal of the screen was sufficiently inexplicable that reasonable doubt remains as to what his specific criminal intentions actually were.', 'general', 'Gear v. State', 'https://www.courtlistener.com/opinion/2538612/', '2538612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the issue whether the trial court erred in denying a Rule 40 petition without a hearing based on no showing of a colorable claim is reviewed de novo;', 'general', 'Killion v. State', 'https://www.courtlistener.com/opinion/2635053/', '2635053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any case, in light of these authorities, we hold that Tauiliili should be applied to Killion.', 'general', 'Killion v. State', 'https://www.courtlistener.com/opinion/2635053/', '2635053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Hawaii Supreme Court''s decision in Tauiliili can be applied to Killion''s sentences.', 'sentencing', 'Killion v. State', 'https://www.courtlistener.com/opinion/2635053/', '2635053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under Florida law, the crime of manslaughter by act does not require that the State prove that the defendant intended to kill the victim.', 'general', 'State v. Montgomery', 'https://www.courtlistener.com/opinion/2545886/', '2545886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that under Florida law, the crime of manslaughter by act does not require proof that the defendant intended to kill the victim.', 'general', 'State v. Montgomery', 'https://www.courtlistener.com/opinion/2545886/', '2545886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the instruction also provided that “it is not necessary for the State to prove that the defendant had a premeditated intent to cause death,” we conclude that this language was insufficient to erode the import'' of the second element: that the jury must find that the defendant intended to cause the death of the victim.', 'general', 'State v. Montgomery', 'https://www.courtlistener.com/opinion/2545886/', '2545886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that fundamental error occurred in this case, where Montgomery was indicted and tried for first-degree murder and ultimately convicted of second-degree murder after the jury was erroneously instructed on the lesser included offense of manslaughter.', 'general', 'State v. Montgomery', 'https://www.courtlistener.com/opinion/2545886/', '2545886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that the use of the standard jury instruction on manslaughter constituted fundamental, reversible error in Montgomery’s case and requires that Montgomery receive a new trial.', 'jury_instruction', 'State v. Montgomery', 'https://www.courtlistener.com/opinion/2545886/', '2545886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that “when the trial court fails to properly instruct on a crime two or more degrees removed from the crime for which the defendant is convicted, the error is not per se reversible, but instead is subject to a harmless error analysis.', 'general', 'State v. Montgomery', 'https://www.courtlistener.com/opinion/2545886/', '2545886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that in the future, courts must explicitly state that the clear and convincing evidence standard was applied in involuntary commitment cases;', 'general', 'In Re Christopher H.', 'https://www.courtlistener.com/opinion/2549771/', '2549771') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not err in instructing the jury on CCDW.', 'general', 'Gallman v. State', 'https://www.courtlistener.com/opinion/2559615/', '2559615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in mind, we concluded that the trial judge’s instruction was an accurate statement of the law.', 'general', 'Gallman v. State', 'https://www.courtlistener.com/opinion/2559615/', '2559615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part, reverse in part, and remand for a new trial on the PDW count.', 'general', 'Gallman v. State', 'https://www.courtlistener.com/opinion/2559615/', '2559615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that when an individual makes incriminating statements in response to explicit and false police assurances of confidentiality, those statements are deemed not voluntary and must be suppressed.', 'suppression', 'State v. Dodge', 'https://www.courtlistener.com/opinion/2554473/', '2554473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In these circumstances, we conclude that the admission of Dodge’s statements made after the detective remedied his initial mistaken representation would not undermine “a quality of fundamental fairness in the criminal justice system.', 'general', 'State v. Dodge', 'https://www.courtlistener.com/opinion/2554473/', '2554473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 15] We concluded that McConkie’s statements to the police should have been
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'State v. Dodge', 'https://www.courtlistener.com/opinion/2554473/', '2554473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, the statements Dodge made after the initial brief assurance of confidentiality but before the correction of that misimpression must be suppressed, and we affirm the court’s order suppressing those statements.', 'suppression', 'State v. Dodge', 'https://www.courtlistener.com/opinion/2554473/', '2554473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that when the accused makes an ambiguous or equivocal reference to counsel during a custodial interrogation, the officer need not immediately terminate the interrogation.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that a reasonable officer in these circumstances would have understood Munson’s statement that he was “done talkin’,” without condition or qualification, to be an unequivocal invocation of his right to silence.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'cause we conclude that Munson’s statement “Well, I’m done talkin’ then” was an unambiguous request to terminate the interview, the question is not whether Munson’s request was equivocal, but rather whether, in order for a suspect to validly invoke the right to silence, it must be clear that his reason for doing so is specifically motivated by a fear of self-incrimination.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Paul Munson unambiguously invoked his right to remain silent, and because the police interrogator failed to scrupulously honor this request, we conclude that Mun-son’s subsequent confession to the crime
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our independent review of the record, we conclude that Munson’s statement was voluntary.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that Detective Hoffbeck did not violate Munson’s constitutional right to remain silent when he continued to interview Mun-son after Munson made the statement “Well, I’m done talkin’ then.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that a fair and common sense reading of the totality of Nashoalook’s interview with the police did not reflect an intent on Nashoalook’s part to “cut off questioning entirely.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we concluded that Nashoalook was concerned that the interview was being tape recorded and that others in his community would find out what he told the police.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the circumstances around Nashoalook’s refusal to answer questions were ambiguous, we concluded that further questioning was not prohibited.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that Munson unambiguously invoked his right to remain silent, we reverse the decision of the court of appeals.', 'general', 'Munson v. State', 'https://www.courtlistener.com/opinion/2634775/', '2634775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the sentencing court did not render a non-individualized sentence in this matter and reject the Superior Court''s assertions to the contrary.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the findings upon which Walls'' sentence was based were legally permissible.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we find that the Superior Court did err.', 'general', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we appreciate the Superior Court''s scholarly review of sentencing discretion, we find that the Superior Court''s understanding of the import of the guidelines and of the nature of appellate review of sentencing led it to impermissibly characterize the sentencing court''s decision and to reweigh the reasons offered by the sentencing court.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that while the sentencing court unfortunately cast doubt upon the individualized nature of Walls'' sentence by making certain general comments about those who sexually victimize young children, when viewed as a whole, the sentencing court made a sentencing decision that was individualized with respect to Walls.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the Superior Court, we find that the sentencing court was permitted to rely on these factors to justify Walls'' sentence.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that the sentencing court took into account the general standards for sentencing.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the above, we find that the Superior Court exceeded its standard of review and erred in making certain legal determinations which led it to supplant the sentencing court''s discretion and to vacate the judgment of sentence imposed by the sentencing court.', 'sentencing', 'Commonwealth v. Walls', 'https://www.courtlistener.com/opinion/1910448/', '1910448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Accordingly, we hold that when separate and distinct culpable acts are subsumed within a single count charging a sexual assault — any one of which could support a conviction thereunder — and the defendant is ultimately convicted by a jury of the charged offense, the defendant’s constitutional right to a unanimous verdict is violated unless one or both of the following occurs: (1) at or before the close of its case-in-chief, the prosecution is required to elect the specific act upon which it ...', 'general', 'State v. Aki', 'https://www.courtlistener.com/opinion/2584117/', '2584117') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Act’s broad statutory language is clear, we hold that the LAD recognizes a cause of action against a school
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Summarizing, we hold that a cause of action against a school district alleging student-on-student affeetional or sexual orientation harassment that is not reasonably addressed by the school district is cognizable under the LAD.', 'general', 'L.W. v. Toms River Regional Schools Board of Education', 'https://www.courtlistener.com/opinion/2091949/', '2091949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the Act’s plain language, its broad remedial goal, and the prevalent nature of peer sexual harassment, we conclude that the LAD permits a cause of action against a school district for student-on-student harassment based on an individual’s perceived sexual orientation if the school district’s failure to reasonably address that harassment has the effect of denying to that student any of a school’s “accommodations, advantages, facilities or privileges.', 'general', 'L.W. v. Toms River Regional Schools Board of Education', 'https://www.courtlistener.com/opinion/2091949/', '2091949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reject the Title IX deliberate indifference standard because we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having established the standard by which a school district may be held liable under the LAD for student-on-student harassment and having provided guidance to future factfinders, we conclude that a remand is required in the present dispute.', 'general', 'L.W. v. Toms River Regional Schools Board of Education', 'https://www.courtlistener.com/opinion/2091949/', '2091949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified and remand this matter to the Director of the Division on Civil Rights, with the direction that the case be referred to the Office of Administrative Law for proceedings consistent with this opinion.', 'general', 'L.W. v. Toms River Regional Schools Board of Education', 'https://www.courtlistener.com/opinion/2091949/', '2091949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the requirement in Utah Code section 78B-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'his inchoate parental rights, we held that the ―natural mother‘s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that a provision of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that he has failed to make the kind of show-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And we concluded that that interest
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'Bogard v. State', 'https://www.courtlistener.com/opinion/1113569/', '1113569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Bogard''s convictions and sentences, save for his conviction of burglary of an inhabited dwelling, which we reverse for insufficient proof of habitation.', 'sentencing', 'Bogard v. State', 'https://www.courtlistener.com/opinion/1113569/', '1113569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, the evidence is sufficient to sustain a conviction for the lesser included offense of burglary of an unoccupied dwelling and we affirm as to Bogard''s guilt of that offense and remand for resentencing under Miss.', 'sentencing', 'Bogard v. State', 'https://www.courtlistener.com/opinion/1113569/', '1113569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'rather, we affirm Bogard''s conviction of burglary of an unoccupied dwelling house and remand for resentencing under Miss.', 'sentencing', 'Bogard v. State', 'https://www.courtlistener.com/opinion/1113569/', '1113569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that section 775.', 'general', 'State v. Stalder', 'https://www.courtlistener.com/opinion/1118661/', '1118661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1076 We conclude that our Florida statute contains elements similar to both the St.', 'general', 'State v. Stalder', 'https://www.courtlistener.com/opinion/1118661/', '1118661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, in a probation revocation hearing, a trial court must make an explicit finding, and must state its reasons on the record, whether there is good cause for dispensing with the probationer’s confrontation right and admitting hearsay into evidence.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finch, we held that “reliable hearsay can be admitted in a probation revocation proceeding and serve as the basis for revocation” without undermining the probationer’s confrontation rights.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “[t]he detoxification center report appears to be the kind of medical report where .', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the affidavit of the New Hampshire police officer does not bear the traditional indicia of reliability that will permit admissibility of the affidavit over a valid objection on confrontation grounds.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After observing that the hearsay sources were “mutually supportive,” and that the medical report was of the kind in which questions of credibility and veracity were not present, we concluded that “[t]he evidence in this case had sufficient indicia of reliability,” and affirmed the revocation order.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the determinations that defendant violated the travel and therapy conditions, but affirm the violation of the urinalysis condition.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), we held that the severity and duration of a beating alone will not support a finding of premeditation.', 'general', 'State v. Wahlberg', 'https://www.courtlistener.com/opinion/2164156/', '2164156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 120 (1975), we held that the trial court should submit instruction on a lesser degree of homicide to the jury if the evidence reasonably supports a conviction of the lesser degree and at the same time supports a finding of not guilty of the greater offense.', 'general', 'State v. Wahlberg', 'https://www.courtlistener.com/opinion/2164156/', '2164156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), we held that the trial court properly refused to submit to the jury the lesser included offense of third-degree murder where the victim was shot twice, there were no bullets fired at anything or anyone else, and no other person in the vicinity of the shooting was concerned for his safety.', 'general', 'State v. Wahlberg', 'https://www.courtlistener.com/opinion/2164156/', '2164156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1187 (1976), this court held that the duration and severe brutality of the beating which caused death showed intent and premeditation beyond a reasonable doubt.', 'general', 'State v. Wahlberg', 'https://www.courtlistener.com/opinion/2164156/', '2164156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 188 (1967), this court held that it was improper for plaintiff’s counsel to characterize one of the defendant’s doctors as a professional witness who would testify in a predetermined manner for money, precisely what the prosecutor did in the instant case.', 'general', 'State v. Wahlberg', 'https://www.courtlistener.com/opinion/2164156/', '2164156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Wahlberg', 'https://www.courtlistener.com/opinion/2164156/', '2164156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the conviction based on the brutality of the beating, the evidence of the decedent’s break-up with the defendant, and the other facts in the case.', 'general', 'State v. Wahlberg', 'https://www.courtlistener.com/opinion/2164156/', '2164156') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2178876/', '2178876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1082 ("Under the circumstances presented here, we hold that the Department of Public Safety and the state were in privity.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record before us, we conclude that Lemmer only challenged the constitutionality of Minn.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because collateral estoppel bars only the relitigation of certain issues, we conclude that collateral estoppel is not substantive in function.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the issue decided in the implied consent proceeding is identical to the one to be decided in the DWI prosecution.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the reasoning of House remains sound and, therefore, conclude that the state and the commissioner are not the same party.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in this case the differing functions and responsibilities of the Commissioner of Public Safety and the State of Minnesota are sufficiently distinct to support the conclusion that the parties are not in privity.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that privity does not exist between the Commissioner of Public Safety and the state in these circumstances.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the state did not have a full and fair opportunity to be heard on the litigated issue.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that collateral estoppel is inapplicable to issues litigated in DWI prosecutions that were previously litigated in implied consent proceedings because the Commissioner of Public Safety and the state are not in privity, and in this instance the state did not have a full and fair opportunity to be heard.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, because we conclude that the elements of collateral estoppel have not been satisfied and that public policy weighs against the application of collateral estoppel, we believe that Minn.', 'general', 'State v. Lemmer', 'https://www.courtlistener.com/opinion/2087446/', '2087446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not err in denying the motion for directed verdict.', 'general', 'State v. Lacy', 'https://www.courtlistener.com/opinion/1407698/', '1407698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the majority''s reasoning in Gates, we conclude that the Gates totality of the circumstances approach does not provide the constitutional protection against unreasonable searches and seizures required by Article 1, Section 14 and Article 1, Section 22 of the Alaska Constitution.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1284136/', '1284136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the basis of knowledge prong was adequately demonstrated.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1284136/', '1284136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals'' decision under Article I, Section 14 and Article I, Section 22 of the Alaska Constitution.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1284136/', '1284136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the stops and questioning at issue may be made in the absence of any individualized suspicion at reasonably located checkpoints.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that stops for brief questioning routinely conducted at permanent checkpoints are consistent with the Fourth Amendment and need not be authorized by warrant.', 'search_seizure', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '," although we held that apparent Mexican ancestry by itself could not create the reasonable suspicion required for a roving-patrol stop.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not address these holdings specifically, as we conclude that no warrant is needed.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[11]  On the facts of the case, we concluded that the stop was impermissible because reasonable suspicion was lacking.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the interference with Fourth Amendment interests involved in such a stop was "modest," 422 U.', 'search_seizure', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals for the Ninth Circuit and remand the case with directions to affirm the conviction of Martinez-Fuerte and to remand the other cases to the District Court for further proceedings.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the judgment of the Court of Appeals for the Fifth Circuit, which had affirmed the conviction of Sifuentes.', 'general', 'United States v. Martinez-Fuerte', 'https://www.courtlistener.com/opinion/109541/', '109541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held "the mere fact that [the mother] did not testify does not justify dismissal of the charge for indecent exposure in her presence[,]" id .', 'dismissal', 'State v. Hoyle', 'https://www.courtlistener.com/opinion/4517439/', '4517439') ON CONFLICT DO NOTHING;
