INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed in more detail below, we find that none of the evidence Appellant describes constituted plain error.', 'general', 'State v. Woodson', 'https://www.courtlistener.com/opinion/1156614/', '1156614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the error of admitting the victim’s testimony, if indeed it was error, does not rise to nearly such a level.', 'general', 'State v. Woodson', 'https://www.courtlistener.com/opinion/1156614/', '1156614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the victim’s testimony that Brown offered to sell him dings was relevant because it was inextricably intertwined with the crimes that occurred imme
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we find no error below and, accordingly, we affirm Appellant’s convictions of first degree robbery and malicious wounding and the sentences imposed.', 'sentencing', 'State v. Woodson', 'https://www.courtlistener.com/opinion/1156614/', '1156614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the sentences imposed by the trial court.', 'sentencing', 'State v. Woodson', 'https://www.courtlistener.com/opinion/1156614/', '1156614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we affirm Appellant’s convictions and sentences.', 'sentencing', 'State v. Woodson', 'https://www.courtlistener.com/opinion/1156614/', '1156614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that the warrantless seizure and subsequent warrantless search in this case were reasonable, we conclude that neither fit within the plain-view exception relied upon by the trial court and court of appeals.', 'general', 'In Re Welfare of G. (NMN) M.', 'https://www.courtlistener.com/opinion/1801886/', '1801886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the state failed to present this court with any other possible warrant exceptions that could have applied to this seizure and search, we hold that because the police had probable cause to believe the pouch contained cocaine, they had objective
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find there was both sufficient identification of the anonymous informant and a demonstrated basis for the informant’s knowledge, we conclude that the information provided by the unknown person had sufficient indicia of reliability to provide the officers with reasonable suspicion to believe the three individuals inside the car may have been engaged in criminal activity.', 'general', 'In Re Welfare of G. (NMN) M.', 'https://www.courtlistener.com/opinion/1801886/', '1801886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the officers made a lawful investigative stop of G.', 'general', 'In Re Welfare of G. (NMN) M.', 'https://www.courtlistener.com/opinion/1801886/', '1801886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the warrantless seizure and subsequent warrantless search of the pouch were reasonable because the police had probable cause to believe the pouch contained cocaine, and consequently, had objective probable cause to arrest the juvenile on the basis of that belief alone.', 'probable_cause', 'In Re Welfare of G. (NMN) M.', 'https://www.courtlistener.com/opinion/1801886/', '1801886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, under the totality of the circumstances, we conclude that G.', 'general', 'In Re Welfare of G. (NMN) M.', 'https://www.courtlistener.com/opinion/1801886/', '1801886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the contraband’s incriminating nature was not immediately apparent, we can dismiss the plain-view exception without considering the doctrine''s third element: whether the police had lawful access to the contraband.', 'dismissal', 'In Re Welfare of G. (NMN) M.', 'https://www.courtlistener.com/opinion/1801886/', '1801886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that a face-to-face confrontation between a tipster and an officer puts a tipster in a position where police might be able to trace his identity, and consequently we concluded that police might be able to hold the tipster accountable for providing any false information.', 'general', 'In Re Welfare of G. (NMN) M.', 'https://www.courtlistener.com/opinion/1801886/', '1801886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Gourdine', 'https://www.courtlistener.com/opinion/1344542/', '1344542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whether or not Julio''s speech was protected, we conclude that, as a whole, his conduct did not amount to seriously disruptive behavior.', 'general', 'In Re JULIO L', 'https://www.courtlistener.com/opinion/2544958/', '2544958') ON CONFLICT DO NOTHING;
