INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), following Gordon, we held that two crimes could be punished separately because each had its own "primary evil.', 'general', 'State v. Paul', 'https://www.courtlistener.com/opinion/1891081/', '1891081') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Gibbs v.', 'general', 'State v. Paul', 'https://www.courtlistener.com/opinion/1891081/', '1891081') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislative intent is clear that separate punishments be imposed for each criminal offense created by the statute.', 'general', 'State v. Paul', 'https://www.courtlistener.com/opinion/1891081/', '1891081') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that both crimes are not intended to punish the same primary evil but that the different subsections address different evils: one forbids lewd or lascivious exhibition;', 'general', 'State v. Paul', 'https://www.courtlistener.com/opinion/1891081/', '1891081') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we hold that Appellant is not entitled to relief on any of these claims.', 'general', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the evidence was sufficient to sustain the conviction of first-degree murder.', 'general', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did because the trial court prevented the Commonwealth from introducing evidence of prior abuse that occurred more than nine months from the day of the murder.', 'general', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a careful and intensive review of the entire record certified to this Court, we hold that the evidence was sufficient to support both aggravating factors found by the jury.', 'general', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 726, 738 (2002), wherein this Court held that “as a general rule, a petitioner should wait to raise claims of ineffective assistance of counsel until collateral review.', 'ineffective_assistance', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient to show Appellant’s actions manifested a specific intent to kill, given the brutality of the assault and the fact that Appellant again began punching and kicking the victim after having stopped twice.', 'general', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these circumstances, we conclude that Mar-lee’s statements to Ms.', 'general', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these instructions ameliorated any undue prejudice caused by the introduction of the prior bad acts.', 'general', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm these principles here and deny Appellant relief with respect to this claim because of the nature of the injuries to the child and the fact that evidence related thereto, such as blood spatter, could be found in numerous places throughout the residence.', 'general', 'Commonwealth v. Sherwood', 'https://www.courtlistener.com/opinion/1995264/', '1995264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the appellate court erred in finding defendant’s aggravated criminal sexual assault conviction based on home invasion to be the more serious offense and in vacating the sexual assault conviction based on residential burglary.', 'general', 'People v. Artis', 'https://www.courtlistener.com/opinion/2019665/', '2019665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the improper conviction was voidable and that the defendant had not preserved a claim of error as to that conviction.', 'general', 'People v. Artis', 'https://www.courtlistener.com/opinion/2019665/', '2019665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that we should continue to adhere to Garcia and hold that where there are multiple convictions for aggravated criminal sexual assault based upon the same physical act, none of the offenses are more serious than any other.', 'general', 'People v. Artis', 'https://www.courtlistener.com/opinion/2019665/', '2019665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the better course is to continue to adhere to the principle that when it cannot be determined which of two or more convictions based on a single physical act is the more serious offense, the cause will be remanded to the trial court for that determination.', 'general', 'People v. Artis', 'https://www.courtlistener.com/opinion/2019665/', '2019665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the remainder of the appellate court’s judgment.', 'general', 'People v. Artis', 'https://www.courtlistener.com/opinion/2019665/', '2019665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '05, we find that in order to prejudice the substantial rights of the defendant, it must be shown that the amendment either added or charged a different offense.', 'general', 'State v. Ostrem', 'https://www.courtlistener.com/opinion/2001397/', '2001397') ON CONFLICT DO NOTHING;
