INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agree that the issue defendant raises has not yet been decided by a Michigan appellate court, we conclude that compliance with SORA is not a punishment and, therefore, that ordering defendant to comply with SORA does not violate the Apprendi-Blakely rule.', 'general', 'People v. Golba', 'https://www.courtlistener.com/opinion/1811654/', '1811654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that judicial fact-finding in applying SORA does not violate defendant’s constitutional rights to a jury trial and due process of law as announced by the Supreme Court in Apprendi, supra at 490: “Other than the fact of a prior conviction, any fact that increases the penalty for a crime beyond the *621prescribed statutory maximum must be submitted to a jury, and proved beyond a reasonable doubt.', 'general', 'People v. Golba', 'https://www.courtlistener.com/opinion/1811654/', '1811654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', People v Stead, 66 P3d 117, 120 (Colo App, 2002) (“Because we conclude that the registration and Internet posting provisions of [Colorado’s sex-offender-registration law] do not constitute punishment, Apprendi is inapplicable.', 'general', 'People v. Golba', 'https://www.courtlistener.com/opinion/1811654/', '1811654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Golba', 'https://www.courtlistener.com/opinion/1811654/', '1811654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Legislature may prohibit the possession of weapons which are ordinarily used for criminal and improper purposes and which are not among those which are legitimate weapons of defense and protection and protected by Section 8 of the Florida Declaration of Rights.', 'general', 'Rinzler v. Carson', 'https://www.courtlistener.com/opinion/1131696/', '1131696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the statute is a valid exercise of the police power of the state, we hold that under the facts as presented to the trial court the statute is not applicable.', 'general', 'Rinzler v. Carson', 'https://www.courtlistener.com/opinion/1131696/', '1131696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the right of possession of the appellant herein to the weapon in question as of the time of the filing of the replevin suit was not foreclosed by the operation of Section 790.', 'general', 'Rinzler v. Carson', 'https://www.courtlistener.com/opinion/1131696/', '1131696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the district court.', 'general', 'State v. Wills', 'https://www.courtlistener.com/opinion/1657013/', '1657013') ON CONFLICT DO NOTHING;
