INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we find that the trial court abused its discretion in alio wing Joshua’s “control” testimony because it is not relevant evidence.', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/1439460/', '1439460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court.', 'general', 'People v. Hodges', 'https://www.courtlistener.com/opinion/2002975/', '2002975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION We reverse the appellate court’s judgment affirming the circuit court’s summary dismissal of defendant’s petition for postconviction relief as frivolous and patently without merit.', 'dismissal', 'People v. Hodges', 'https://www.courtlistener.com/opinion/2002975/', '2002975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that where a defendant in a criminal trial declines the opportunity to poll the jurors as to their exposure to possibly prejudicial publicity disseminated during trial, such error is waived and may not be raised after the return of the verdict, unless the defendant produces evidence which indicates that some member of the jury was improperly affected by such publicity.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and, in reliance on that decision, we hold that double jeopardy prohibits an accused charged with felony-murder, as defined by W.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that where the court finds that “a substantial likelihood exists that the verdict was influenced by the jury’s exposure to newspaper articles or other media reports” a new trial is mandated.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it was not, but, recognizing the possibility that the trial judge might make erroneous or improper comments to the jury panel during the orientation meeting which could prejudice the accused’s rights, we also held that despite the fact that the proceeding was not a critical stage a court reporter should be present at such proceedings to record the remarks of the trial court to the jury panel.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that where a defendant had been convicted of felony-murder, double jeopardy would prohibit a second trial of the defendant on the underlying felony of robbery.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 129 (1979), we held that the identity of the perpetrator of a crime is not generally held to be a part of the corpus delecti, "since this term means proof that the crime occurred and that somebody else’s criminality was the source of the crime, as distinguished from non-criminal source, e.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having discussed all of the errors raised by the appellant, we conclude that there was no error at trial which would warrant reversal of the appellant’s convictions.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To secure the protections afforded the appellant by our double jeopardy laws, we reverse the sentences for both the arson and robbery convictions and remand the case for resentencing.', 'sentencing', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the appellant’s conviction, but remand the case for resentencing.', 'sentencing', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the appellant’s convictions, but reverse the sentencing order and remand the case to the Circuit Court of McDowell County for resentencing in accordance with the principles set forth in this opinion.', 'sentencing', 'State v. Williams', 'https://www.courtlistener.com/opinion/1366018/', '1366018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the language of the statute has only one logical reading, namely that “repeatedly” modifies “follows” and not “harasses.', 'general', 'Snowden v. State', 'https://www.courtlistener.com/opinion/2089388/', '2089388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record in this case supports a jury finding that the elements of the offense had been established beyond a reasonable doubt.', 'general', 'Snowden v. State', 'https://www.courtlistener.com/opinion/2089388/', '2089388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Snowden’s behavior is not constitutionally protected under the standard enunciated in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Superior Court appropriately conducted the balancing test required by D.', 'general', 'Snowden v. State', 'https://www.courtlistener.com/opinion/2089388/', '2089388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 80] Taking this information into account, we held that the victim''s body would inevitably have been discovered because, if the police had not discovered the victim''s body as a result of the interrogation, they would have checked the defendant''s wife''s story and found that the victim was not with her grandparents.', 'general', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because probable cause to search did not exist without the information obtained during the initial warrantless entry, no exception to the warrant requirement or the exclusionary rule applies, and we vacate the convictions.', 'probable_cause', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the warrantless entry of the apartment was neither justified under the exigent circumstances exception to the warrant requirement nor as a temporary seizure of the premises, an independent source exception analysis is justified.', 'general', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 19] The inevitable discovery exception is an additional analytical framework for considering the suppression of the evidence if we conclude that the initial warrantless entry into the Rabons'' apartment prior to the issuance of the search warrant was unlawful because there was no probable cause.', 'suppression', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons to be more fully addressed, we conclude that the evidence seized following the issuance of the search warrant is more properly analyzed under what is known as the independent source exception.', 'general', 'State v. Rabon', 'https://www.courtlistener.com/opinion/2330498/', '2330498') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reversed a conviction pursuant to § 22-3214, because the jury was not given instructions sufficient to enable it to know what was an unlawful use in the context of that case.', 'general', 'Strong v. United States', 'https://www.courtlistener.com/opinion/2075789/', '2075789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these two facts, we hold that appellant has not met her obligation here, and therefore has not shifted the burden of proof to the state.', 'general', 'State v. Mellett', 'https://www.courtlistener.com/opinion/1350568/', '1350568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that those claims must also fail.', 'general', 'State v. Mellett', 'https://www.courtlistener.com/opinion/1350568/', '1350568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the district court did not commit error, we affirm.', 'general', 'State v. Mellett', 'https://www.courtlistener.com/opinion/1350568/', '1350568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence, along with Floyd''s pattern of lies, is sufficient to support his conviction.', 'general', 'State v. Floyd', 'https://www.courtlistener.com/opinion/2071172/', '2071172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶21 Without deciding whether counsel''s performance was deficient, we conclude that Floyd has not demonstrated he was prejudiced.', 'general', 'State v. Floyd', 'https://www.courtlistener.com/opinion/2071172/', '2071172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the prosecutor''s conduct here does not demand the same result as in Smith.', 'general', 'State v. Floyd', 'https://www.courtlistener.com/opinion/2071172/', '2071172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Sentencing is within the discretion of the circuit court and we reverse only if it erroneously exercised that discretion.', 'sentencing', 'State v. Floyd', 'https://www.courtlistener.com/opinion/2071172/', '2071172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, this court held that value was not an element of the offense of theft, but we specifically stated that “[although value is not an element of theft, the State must prove, by evidence beyond a reasonable doubt, the value of the property that is the subject of the theft charge.', 'general', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the circumstances of this case, Gartner was not prejudiced by the district court’s erroneous instruction.', 'general', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury was instructed that the State was required to prove, as an element of the offense, the value of the stolen property beyond a reasonable doubt, and because the record shows that the jury found the State to have met this burden, we conclude that Gartner was not prejudiced by the district court’s erroneous formulation of jury instruction No.', 'jury_instruction', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the prosecutor’s statement was improper, given the context of this record, we conclude that the district court’s prompt admonition to the jury was sufficient to dispel any potential prejudice resulting from the statement.', 'general', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the evidence is sufficient to sustain these convictions.', 'general', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, we conclude that, in the light most favorable to the State, the purchase price of the digital camera was sufficient evidence of fair market value to support Gartner’s conviction on count II of the information.', 'general', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the principles set forth above, we conclude that the evidence presented is insufficient to support the jury’s determination regarding the value of the fax machine.', 'general', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse, and remand this cause with directions to dismiss.', 'dismissal', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find no reversible error with respect to Gartner’s convictions and sentences on counts II, III, V, and VI of the information, and we affirm those convictions and sentences.', 'sentencing', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Gartner’s conviction on count VII of the information, but vacate the sentence and remand the cause to the district court with direction to impose an appropriate sentence on Gartner for misdemeanor theft of property with a value of less than $200, a Class II misdemeanor.', 'sentencing', 'State v. Gartner', 'https://www.courtlistener.com/opinion/1809760/', '1809760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we hold that defendant has forfeited any ineffectiveness claims on review that are premised upon the requesting officer''s alleged failure to disclose the age of the mail found in defendant''s trash.', 'ineffective_assistance', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that section 5-8-4(a) does not apply here, based on the plain meaning of the word `consecutive.', 'general', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 292 ("we hold that section 5-8-4(a) does not apply here, based on the plain meaning of the word `consecutive''").', 'general', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we held that, because defendant was sentenced under the Habitual Criminal Act (720 ILCS 5/33B-1 (West 2002)), he was not subject to consecutive sentencing.', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, and "more importantly," we held that it was impossible to serve consecutive natural-life sentences, "both according to natural law and within the plain meaning of the `consecutive'' sentencing law, section 5-8-4(a).', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Palmer, this court held that the imposition of consecutive sentences in that case was "contrary to the legislature''s intent" and therefore void.', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After thoroughly reviewing both defendant''s petition and the supporting record, we conclude that the trial court properly dismissed defendant''s pro se petition as frivolous and patently without merit.', 'dismissal', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we find that there is no arguable legal basis for defendant''s ineffective assistance of appellate counsel claim and that summary dismissal of his pro se postconviction therefore was proper.', 'dismissal', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As for the merits of defendant''s voidness claim, we find that defendant''s reliance on Palmer is misplaced.', 'general', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Palmer, we reversed the circuit court''s imposition of the defendant''s consecutive natural-life sentences and modified the sentences to run concurrently.', 'sentencing', 'People v. Petrenko', 'https://www.courtlistener.com/opinion/2076105/', '2076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Pace', 'https://www.courtlistener.com/opinion/1383023/', '1383023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'State v. Cook', 'https://www.courtlistener.com/opinion/2442697/', '2442697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 768, 772, and we affirm those convictions without any further discussion.', 'general', 'State v. Cook', 'https://www.courtlistener.com/opinion/2442697/', '2442697') ON CONFLICT DO NOTHING;
