INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the trial court’s denial of defendant’s motion to dismiss the charges under 13 V.', 'dismissal', 'Vermont v. Brunner', 'https://www.courtlistener.com/opinion/2679710/', '2679710') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error with the trial court’s disjunctive jury instruction, we held that while “many of the enumerated aggravating factors are in fact separate crimes under various provisions of our General Statutes, they are not separate offenses as in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Defendant’s statement was proper non-hearsay evidence introduced for the limited purpose of demonstrating malice, and we affirm the trial court’s overruling of Defendant’s hearsay objection.', 'general', 'State v. Hazelwood', 'https://www.courtlistener.com/opinion/1387167/', '1387167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Plain error review is not necessary, however, because we find that Defendant did not waive his right to appeal the trial court’s hearsay ruling under N.', 'general', 'State v. Hazelwood', 'https://www.courtlistener.com/opinion/1387167/', '1387167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed above in Part I, we find that Defendant’s attorney did interpose a timely objection adequate to preserve the contested hearsay issue for appellate review under N.', 'general', 'State v. Hazelwood', 'https://www.courtlistener.com/opinion/1387167/', '1387167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'officer to act? We conclude that although such direct testimony would be helpful
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court’s judgment.', 'general', 'State of Maine v. Samuel Sanchez', 'https://www.courtlistener.com/opinion/2679909/', '2679909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we held that the required intent for these offenses “relates to the assault, not to the injury which results.', 'general', 'State v. Cebuhar', 'https://www.courtlistener.com/opinion/1714841/', '1714841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 231 (1987), we held that the required intent for second degree assault concerns only the defendant’s choice of action involving a dangerous instrument and not the resulting injury.', 'general', 'State v. Cebuhar', 'https://www.courtlistener.com/opinion/1714841/', '1714841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the same reasoning applies to the failure to endorse the names of the alleged victims in that a defendant would have reason to know that the alleged victims will be called to testify at trial.', 'general', 'State v. Cebuhar', 'https://www.courtlistener.com/opinion/1714841/', '1714841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that assault on a peace officer is also a general intent crime.', 'general', 'State v. Cebuhar', 'https://www.courtlistener.com/opinion/1714841/', '1714841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse Cebuhar’s conviction of third degree assault because the jury was erroneously instructed.', 'general', 'State v. Cebuhar', 'https://www.courtlistener.com/opinion/1714841/', '1714841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Cebuhar’s conviction of third degree assault on a peace officer, concluding that knowledge of a victim’s status as a peace officer is not an element of § 28-931.', 'general', 'State v. Cebuhar', 'https://www.courtlistener.com/opinion/1714841/', '1714841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with the preceding analysis, we affirm Cebuhar’s conviction of third degree assault on a peace officer, but reverse his conviction of third degree assault and remand that matter for a new trial.', 'general', 'State v. Cebuhar', 'https://www.courtlistener.com/opinion/1714841/', '1714841') ON CONFLICT DO NOTHING;
