INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '18 We conclude that the Maine Constitution can be distinguished from the United States Constitution, and that SORNA of 1999 violates the Maine Constitution, even if it would pass muster under the United States Constitution.', 'general', 'John Doe I v. Robert Williams', 'https://www.courtlistener.com/opinion/2680019/', '2680019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Freeman we found that the civil proceeding by which some OUI laws were enforced had punitive consequences of the type that characterize criminal prosecution.', 'general', 'John Doe I v. Robert Williams', 'https://www.courtlistener.com/opinion/2680019/', '2680019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we found that the stigma was “highly suggestive of the true criminal nature of the procedure.', 'general', 'John Doe I v. Robert Williams', 'https://www.courtlistener.com/opinion/2680019/', '2680019') ON CONFLICT DO NOTHING;
