INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when an accountant is retained in order to assist in defending against a criminal tax fraud investigation, as Allen was here,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because the trial court failed to follow the proper procedure and allow defendant five peremptory challenges, we conclude that the trial court’s error requires reversal, even if defendant failed to prove prejudice.', 'general', 'People v. Paasche', 'https://www.courtlistener.com/opinion/1998806/', '1998806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record is insufficient to sustain either defendant’s or the prosecution’s position.', 'general', 'People v. Paasche', 'https://www.courtlistener.com/opinion/1998806/', '1998806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence constitutes a reasonable basis to suspect the perpetration of the fraud of tax evasion.', 'general', 'People v. Paasche', 'https://www.courtlistener.com/opinion/1998806/', '1998806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s right to a fair trial was denied because the lower court failed to resolve this issue outside the jury’s presence.', 'general', 'People v. Paasche', 'https://www.courtlistener.com/opinion/1998806/', '1998806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Last, we conclude that sufficient evidence existed to support defendant’s conviction.', 'general', 'People v. Paasche', 'https://www.courtlistener.com/opinion/1998806/', '1998806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of evidence that defendant failed to file income tax returns during four years when she and her husband earned substantial income, we conclude that a rational trier of fact could find both that the returns were not filed and that defendant possessed the requisite intent in failing to file.', 'general', 'People v. Paasche', 'https://www.courtlistener.com/opinion/1998806/', '1998806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the agents eventually returned all but one of the files, a file dealing exclusively with the Paasches’ tax returns, we find that the other files were also seized.', 'general', 'People v. Paasche', 'https://www.courtlistener.com/opinion/1998806/', '1998806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'People v. Paasche', 'https://www.courtlistener.com/opinion/1998806/', '1998806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Kampf v. Kampf', 'https://www.courtlistener.com/opinion/2094339/', '2094339') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Trinkle''s conviction after determining whether there was a substantial relationship between the prior representation and the criminal proceeding, and whether the prosecuting attorney gained any confidential information through their prior association.', 'general', 'Daugherty v. State', 'https://www.courtlistener.com/opinion/2087023/', '2087023') ON CONFLICT DO NOTHING;
