INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Sixth Amendment applies to both.', 'general', 'Ring v. Arizona', 'https://www.courtlistener.com/opinion/121165/', '121165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*602 We held that Apprendi''s sentence violated his right to "a jury determination that [he] is guilty of every element of the crime with which he is charged, beyond a reasonable doubt.', 'sentencing', 'Ring v. Arizona', 'https://www.courtlistener.com/opinion/121165/', '121165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '639 (1990), this Court held that Arizona''s sentencing scheme was compatible with the Sixth Amendment because the additional facts found by the judge qualified as sentencing considerations, not as "element[s] of the offense of capital murder.', 'sentencing', 'Ring v. Arizona', 'https://www.courtlistener.com/opinion/121165/', '121165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State has a substantial right to enforce the criminal laws of North Carolina and that this right is affected by a ruling declaring a statute, duly enacted by the General Assembly, to be unconstitutional.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/8913187/', '8913187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this evi*304dences generally law-abiding conduct since 1978 and is a factor to be weighed in favor of plaintiff.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/8913187/', '8913187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Act does not deprive plaintiffs of liberty without due process of law under the United States Constitution.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/8913187/', '8913187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the requirements of the Law of the Land Clause, we hold that the Act does not deprive individuals of a constitutionally protected liberty interest without due process of law under the North Carolina Constitution.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/8913187/', '8913187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that “we clearly have a sufficient evidentiary record upon which to evaluate the validity of Plaintiffs claim[.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/8913187/', '8913187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that intermediate scrutiny is more appropriate than strict scrutiny for Chester and similarly situated persons.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/8913187/', '8913187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After balancing these three factors, we conclude that the State’s interest in ensuring the public safety outweighs the private interest involved (if any) and any risk of erroneously depriving those interests.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/8913187/', '8913187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these provisions fully comply with procedural due process requirements as applied to defendant.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this situation is one of those “extraordinary situations where some valid governmental interest is at stake that justifies postponing the hearing until after” the deprivation, James Daniel Good Real Property, 510 U.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that an order requiring the surrender of firearms after an ex parte hearing under Chapter 50B is also constitutional under the Law of the Land Clause of the North Carolina Constitution.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that criminal prosecution for violation of an ex parte order requiring the surrender of defendant’s firearms does not violate his due process rights.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that the prosecution of defendant for violation of the ex parte order does not violate his procedural due process rights.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Supreme Court case relied upon by the trial court is not controlling on the issue presented here because of subsequent statutory amendments and that prosecution of defendant for violation of an ex parte order does not violate his procedural due process rights.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, we conclude that a “protective order” includes an ex parte or emergency order for purposes of N.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that an ex parte order is a “protective order” for purposes of N.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the trial court’s order and remand for further proceedings.', 'general', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the trial court’s order dismissing the indictment and remand for further proceedings.', 'dismissal', 'State v. Poole', 'https://www.courtlistener.com/opinion/8913700/', '8913700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "the Due Process Clause protects the accused against conviction except upon proof beyond a reasonable doubt of every fact necessary to constitute the crime with which he is charged," 397 U.', 'general', 'Almendarez-Torres v. United States', 'https://www.courtlistener.com/opinion/118188/', '118188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the subsection is a penalty provision, which simply authorizes a court to increase the sentence for a recidivist.', 'sentencing', 'Almendarez-Torres v. United States', 'https://www.courtlistener.com/opinion/118188/', '118188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not err when it allowed the State to amend Count III of the information.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2095585/', '2095585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2095585/', '2095585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '350 (1960), we held that a naturalized citizen who had willfully and falsely stated during the naturalization process that he had never been arrested could nevertheless not be denaturalized pursuant to § 1451.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '265 (1961), we held that a naturalized citizen who had willfully and falsely stated during the naturalization process that his occupation was "real estate," when in fact it would more accurately have been described as "bootlegging," could be denaturalized pursuant to § 1451.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" In Fedorenko, we held that citizenship had been illegally procured because the petitioner, a former armed concentration camp guard, was ineligible for the visa he had been issued under the Displaced Persons Act of 1948 (DPA), 62 Stat.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking, therefore, solely to the question whether Kungys'' misrepresentation of the date and place of his birth in his naturalization petition was material within the meaning of § 1451(a), we conclude that it was not.', 'general', 'Kungys v. United States', 'https://www.courtlistener.com/opinion/112052/', '112052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Com. v. Ratliff, E.', 'https://www.courtlistener.com/opinion/10288745/', '10288745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm Appellant’s judgment of sentence.', 'sentencing', 'Com. v. Ratliff, E.', 'https://www.courtlistener.com/opinion/10288745/', '10288745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the two to three minutes involved in these circumstances was sufficient to support the kidnapping conviction.', 'general', 'State v. Goodhue', 'https://www.courtlistener.com/opinion/1461715/', '1461715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In affirming the kidnapping conviction, we held that the confinement of the nurse was not incidental to the attempted escape.', 'general', 'State v. Goodhue', 'https://www.courtlistener.com/opinion/1461715/', '1461715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Evaluating defendant’s actions in this light, we conclude that the movement of Carolyn from the kitchen to the bathroom floor did not exceed the confinement or removal inherent in the commission of the crime of sexual assault nor did it increase the danger to the victim over and above the danger presented by the attempted sexual assault.', 'general', 'State v. Goodhue', 'https://www.courtlistener.com/opinion/1461715/', '1461715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[restraining or confining someone is not an essential or inherent component of an escape attempt and doing so only increased the level of risk and ‘dangerousness’ of [defendant’s] action.', 'general', 'State v. Goodhue', 'https://www.courtlistener.com/opinion/1461715/', '1461715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction for attempted sexual assault and reverse the conviction for kidnapping.', 'general', 'State v. Goodhue', 'https://www.courtlistener.com/opinion/1461715/', '1461715') ON CONFLICT DO NOTHING;
