INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this search violated Chapter I, Article 11, of the Vermont Constitution, and accordingly reverse.', 'general', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/2202269/', '2202269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On these facts, we find that the officers’ walk over defendant’s logging roads and through his woods violated his right to privacy under Article 11, and the evidence obtained thereby may not be used against him.', 'general', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/2202269/', '2202269') ON CONFLICT DO NOTHING;
