INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the seizure of the envelope did not violate defendant’s fourth-amendment rights.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*94On the record before us, we hold that the trial court’s decision to grant defense counsel’s request to limit death qualification with respect to those jurors whose answers to the questions printed on the jury questionnaire were acceptable, if it was error at all, was not error sufficiently “egregious as to ‘cut mortally into [defendant’s] substantive rights * * *.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that their admission into evidence by the trial court was not an abuse of discretion.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the excision of a portion of the tire did not deprive defendant of his constitutional right to a fair trial.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “mitigating factors must be introduced, regardless of defendant’s position.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that “a criminal defendant is entitled to the assistance of reasonably competent counsel, and that if counsel’s performance has been so deficient as to create a reasonable probability that these deficiencies materially contributed to defendant’s conviction, the constitutional right will have been violated.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant did not manifest an actual or subjective expectation of privacy in the envelope, in that he exposed the mailing address and the words “To be opened in the event of my death.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the regulation on which defendant relies does not invalidate the examination of the contents of defendant’s envelope pursuant to a lawfully-issued search warrant.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not abuse its discretion in granting defendant’s motion to try the case in a county other than Ocean County.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the voir dire adequately disclosed any impermissible exposure to pretrial publicity.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that plaintiff’s status under furlough more closely resembles that of an inmate seeking a particular right or status within an institution, rather than that of a parolee.', 'general', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking at the totality of the evidence in the trial, we hold that the defendant sufficiently demonstrated a reasonable probability that a different result would have occurred but for the failure to call Jones.', 'general', 'State v. Jimothy A. Jenkins', 'https://www.courtlistener.com/opinion/2682634/', '2682634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that the failure to call Jones as a witness at trial to give testimony contradictory to that of the State''s eyewitness had a reasonable probability of affecting the result of the case.', 'general', 'State v. Jimothy A. Jenkins', 'https://www.courtlistener.com/opinion/2682634/', '2682634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we conclude that defense trial counsel''s representation fell below the objective standard of reasonably effective assistance.', 'general', 'State v. Jimothy A. Jenkins', 'https://www.courtlistener.com/opinion/2682634/', '2682634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking into account all the circumstances of the case, we conclude that defense trial counsel''s performance was prejudicial to the defendant;', 'general', 'State v. Jimothy A. Jenkins', 'https://www.courtlistener.com/opinion/2682634/', '2682634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse the decision of the court of appeals and remand the cause to the circuit court for a new trial.', 'general', 'State v. Jimothy A. Jenkins', 'https://www.courtlistener.com/opinion/2682634/', '2682634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 12, another case involving a claim of ineffective assistance based on trial *209counsel''s failure to call certain witnesses, we concluded that the defendant had satisfied his burden of establishing prejudice notwithstanding the "the strength of the victim''s testimony and the existence of some inconsistency between [the victim''s] testimony and [the exculpatory confession that was the subject of the uncalled witness'' testimony].', 'ineffective_assistance', 'State v. Jimothy A. Jenkins', 'https://www.courtlistener.com/opinion/2682634/', '2682634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On review, we concluded that the circuit court "employed the wrong legal standard when determining that there was not a reasonable probability of a different outcome.', 'general', 'State v. Jimothy A. Jenkins', 'https://www.courtlistener.com/opinion/2682634/', '2682634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held the first sentence of the statute included only the murder victim, not others who had suffered harm because of her death.', 'sentencing', 'State v. Tesch', 'https://www.courtlistener.com/opinion/1697856/', '1697856') ON CONFLICT DO NOTHING;
