INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we hold that the prosecution presented sufficient evidence to prove armed robbery and felony murder beyond a reasonable doubt.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the plain error rule discussed in Olano and Grant extends to unpreserved claims of constitutional error.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regarding the instructional issue, we hold that the Olano/Grant forfeiture rule applies to unpreserved claims of constitutional error.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that plain error occurred, but that it was not decisive of the outcome.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the unpublished opinion of the Court of Appeals, which affirmed defendant’s convictions and sentence.', 'sentencing', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
