INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Phelps', 'https://www.courtlistener.com/opinion/2117175/', '2117175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the search was consensual and that defendant waived her opportunity for the animals to be held in custodial care, and affirm.', 'general', 'State v. Stevens', 'https://www.courtlistener.com/opinion/2195557/', '2195557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to her second argument, we conclude that the record is clear that defendant gave consent by her action of going into the house, obtaining the key to the kennel and opening the kennel.', 'general', 'State v. Stevens', 'https://www.courtlistener.com/opinion/2195557/', '2195557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 336, 344 (1982), we found that a sixteen-year-old boy’s consent to seize clothing and shoes as evidence was not voluntary because of his youth, his emotional state, the misleading statements of the police, the failure to give him
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that defendant’s exit from his vehicle at the officer’s request was not consensual because an inherently coercive atmosphere existed as a result of the officer’s stop of the vehicle, the “request” to exit followed a request, which could not be refused, to show the operator’s license and registration, and the officer did not inform the operator that he was free to refuse the officer’s request.', 'general', 'State v. Stevens', 'https://www.courtlistener.com/opinion/2195557/', '2195557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Searles', 'https://www.courtlistener.com/opinion/1463988/', '1463988') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of the circumstances, we hold that insufficient evidence existed to support the trial court’s determination that Tyler consented to the entry.', 'general', 'State v. Corpier', 'https://www.courtlistener.com/opinion/2376080/', '2376080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the defendant had a legitimate expectation of privacy in the apartment at 339 Buckner Court and as such has standing to challenge his arrest under the fourth amendment and the requirements set forth in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the evidence we find that the state failed to meet its burden in demonstrating that the consent was voluntary.', 'general', 'State v. Corpier', 'https://www.courtlistener.com/opinion/2376080/', '2376080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the record as a whole, we find that the prosecutor’s use of the words, “to hear him say” was merely a misstatement and not a direct reference to the defendant’s failure to testify.', 'general', 'State v. Corpier', 'https://www.courtlistener.com/opinion/2376080/', '2376080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we find that the trial court correctly overruled the defendant’s objections.', 'general', 'State v. Corpier', 'https://www.courtlistener.com/opinion/2376080/', '2376080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the same light, we find that the defendant’s assertion that the trial court erred in overruling an objection to the prosecutor’s argument regarding what facts the defendant’s psychologist did not consider in concluding that defendant Corpier lacked the capacity to emotionally appreciate the results of his conduct, is without merit.', 'general', 'State v. Corpier', 'https://www.courtlistener.com/opinion/2376080/', '2376080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Corpier', 'https://www.courtlistener.com/opinion/2376080/', '2376080') ON CONFLICT DO NOTHING;
