INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court abused its discretion in binding Hudson over for trial.', 'general', 'People v. Hudson', 'https://www.courtlistener.com/opinion/1830341/', '1830341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'People v. Hudson', 'https://www.courtlistener.com/opinion/1830341/', '1830341') ON CONFLICT DO NOTHING;
