INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'State v. Clayton W. Williams', 'https://www.courtlistener.com/opinion/2683719/', '2683719') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the statute is ambiguous18 and turn to the legislative history to glean the statute''s meaning.', 'general', 'State v. Clayton W. Williams', 'https://www.courtlistener.com/opinion/2683719/', '2683719') ON CONFLICT DO NOTHING;
