INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the imposition of a prospective coercive fine is reasonable in this case.', 'general', 'Vermont Women''s Health Center v. Operation Rescue', 'https://www.courtlistener.com/opinion/2389979/', '2389979') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was substantial, credible evidence to support the trial court’s findings that each defendant knew of the terms of the order.', 'general', 'Vermont Women''s Health Center v. Operation Rescue', 'https://www.courtlistener.com/opinion/2389979/', '2389979') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Vermont Women''s Health Center v. Operation Rescue', 'https://www.courtlistener.com/opinion/2389979/', '2389979') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rastopsojf, where this court held that a defendant should not be considered a repeat felony offender for presumptive sentencing purposes unless the defendant committed the subsequent felony after being sentenced for prior offenses.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a person has been “convicted of a felony” when the appropriate trier of fact has made a determination of guilt and sentence has been imposed.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In Kelly, we held that a witness could be impeached by evidence of a prior conviction of dishonesty or false statement under Evidence Rule 609 where the “verdict of guilt has been accepted but sentencing has not yet occurred.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the policy set forth in Carlson seems to- be better fulfilled by establishing the time of sentencing as the point when the conviction is final, rather than the time when there is a finding of guilty or a plea of guilty or nolo contende-re.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is preferable to have a clear and definite time when a conviction will be final and that this time is the time of sentencing.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a defendant has not been - finally convicted, on a charge, for presumptive sentencing purposes, until he has been sentenced on that charge.', 'sentencing', 'Brant v. State', 'https://www.courtlistener.com/opinion/1197028/', '1197028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the totality of the circumstances, we hold that a reasonable person in defendant''s position would not have believed that he was under arrest or that his freedom of movement was restrained to the degree of *739 a formal arrest.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant''s subsequent statements "so many black belts" and "I''ll kill you" are relevant in the context of direct examination to show that what was "up under [defendant''s] belt" was a human life, that the defendant had already "killed one" woman like Officer McCormick, and that by "belt," defendant meant black belt.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing and the entire record in this case, we hold that defendant received a fair trial and capital sentencing proceeding, free of reversible error.', 'sentencing', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hunt, this Court held that short-form *753 indictments satisfy state and federal constitutional requirements.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s findings of fact are supported by competent record evidence, and that the court properly applied the law to those facts.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence presented by the State is sufficient evidence from which a jury could infer defendant''s intent to engage in vaginal intercourse with the victim against her will.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After thoroughly reviewing the record, transcripts, and briefs in this case, we conclude that the evidence fully supports the aggravating circumstance found by the jury.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that nothing in the record suggests defendant''s death sentence was imposed under the influence of passion, prejudice, or any other arbitrary factor.', 'sentencing', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this and other relevant evidence, we conclude that the crime committed by defendant in this case was equally as brutal as other murders for which a death sentence has been imposed.', 'sentencing', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following careful review of the record, we find that defendant was not in "custody" for purposes of Miranda and that Miranda warnings were, therefore, not required.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Evans, Savage, Bradley, Brooks, and the 1991 version of section 947.', 'general', 'Bolden v. FL. DEPT. OF CORRECTIONS', 'https://www.courtlistener.com/opinion/1610485/', '1610485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court departed from the essential requirements of law.', 'general', 'Bolden v. FL. DEPT. OF CORRECTIONS', 'https://www.courtlistener.com/opinion/1610485/', '1610485') ON CONFLICT DO NOTHING;
