INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lee, State Probation and Parole Officer, having represented to the Court that the said defendant, Jerry Lee Grant, who was on September 28, 1976, placed on probation under supervision of this Officer, has satisfactorily complied with all conditions of probation, it is hereby ordered that the said defendant be released from supervised probation.', 'general', 'Grant v. Commonwealth', 'https://www.courtlistener.com/opinion/1361073/', '1361073') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the evidence is insufficient as a matter of law to sustain A.', 'general', 'AH v. State', 'https://www.courtlistener.com/opinion/2527191/', '2527191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We reverse.', 'general', 'AH v. State', 'https://www.courtlistener.com/opinion/2527191/', '2527191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the juvenile court''s adjudication of A.', 'general', 'AH v. State', 'https://www.courtlistener.com/opinion/2527191/', '2527191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse and find the evidence insufficient to sustain A.', 'general', 'AH v. State', 'https://www.courtlistener.com/opinion/2527191/', '2527191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse, however, on appellant''s other two points on appeal.', 'general', 'Nardone v. State', 'https://www.courtlistener.com/opinion/1649708/', '1649708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse appellant''s conviction and sentence and remand for a new trial.', 'sentencing', 'Nardone v. State', 'https://www.courtlistener.com/opinion/1649708/', '1649708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on the issue of sufficiency of the evidence.', 'general', 'Nardone v. State', 'https://www.courtlistener.com/opinion/1649708/', '1649708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Today we hold that “if the trial judge concludes the proposed testimony would be incriminating and thereby poses the risk of possible future prosecution of the witness, this ends that inquiry and a claim of privilege should be sustained.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2314198/', '2314198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that, as a matter of policy, appellate courts of this state shall dismiss the appeal of a convicted defendant not yet sentenced who flees the jurisdiction before filing a notice of appeal and who fails to return and timely file that appeal unless the defendant can establish that the absence was legally justified.', 'dismissal', 'State v. Gurican', 'https://www.courtlistener.com/opinion/1653315/', '1653315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Aussenberg''s view of the automatic stay is overly expansive.', 'general', 'Wyssbrod v. Wittjen', 'https://www.courtlistener.com/opinion/1655639/', '1655639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge was without authority to enter a judgment against Craig and Aussenberg for the funds received by them as attorney''s fees.', 'general', 'Wyssbrod v. Wittjen', 'https://www.courtlistener.com/opinion/1655639/', '1655639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But, we reverse and render the judgment against Aussenberg and Craig for disgorgement of corporate funds.', 'general', 'Wyssbrod v. Wittjen', 'https://www.courtlistener.com/opinion/1655639/', '1655639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the circuit court''s sanctions against Aussenberg, but reduce the award in accordance with Miss.', 'general', 'Wyssbrod v. Wittjen', 'https://www.courtlistener.com/opinion/1655639/', '1655639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the lower circuit court''s award of attorney fees and expenses under the Litigation Accountability Act.', 'general', 'Wyssbrod v. Wittjen', 'https://www.courtlistener.com/opinion/1655639/', '1655639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither Cummings nor Smith unequivocally invoked the right to remain silent during their interrogations.', 'general', 'State v. Adrean L. Smith', 'https://www.courtlistener.com/opinion/2685460/', '2685460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result of these competing inferences, we conclude that Cummings'' statement was not an unequivocal invocation of the right to remain silent.', 'general', 'State v. Adrean L. Smith', 'https://www.courtlistener.com/opinion/2685460/', '2685460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we conclude that the circuit court did not erroneously exercise its discretion and we affirm the court of appeals.', 'general', 'State v. Adrean L. Smith', 'https://www.courtlistener.com/opinion/2685460/', '2685460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellant''s prosecution for possession of a concealed firearm was permissible and that the firearm was wrongfully suppressed.', 'suppression', 'Ensor v. State', 'https://www.courtlistener.com/opinion/1662508/', '1662508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the instant facts fit properly into the third, pre-intrusion, category.', 'general', 'Ensor v. State', 'https://www.courtlistener.com/opinion/1662508/', '1662508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this weapon could qualify as hidden from the ordinary sight of the average person.', 'general', 'Ensor v. State', 'https://www.courtlistener.com/opinion/1662508/', '1662508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the result of the instant district court decision.', 'general', 'Ensor v. State', 'https://www.courtlistener.com/opinion/1662508/', '1662508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the provisions in the Juvenile Justice Code (JJC), Wis.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that the provisions in Wis.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '357(4)(d), we conclude that those provisions in the JJC violate Article I, ง 7 of the Wisconsin Constitution and the Sixth and Fourteenth Amendments to the United States Constitution because they essentially subject a juvenile to the consequences of a "criminal prosecution" without the right to a trial by jury.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the purposes and objectives of the JJC can be fully met even if the provisions in Wis.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '357(4)(d), we conclude that the JJC is not a criminal code.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '357(4)(d) may be severed, and that the remaining provisions in the JJC are non-criminal, we conclude that once those provisions are severed, there clearly is no violation of the juvenile''s state or federal constitutional *893 due process protections.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a reasonable basis exists in this case.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the legislature''s stated objectives in the JJC, and other persuasive authority cited herein, we conclude that the need for early intervention in the JJC is a reasonable basis for requiring that the trier of fact in a juvenile delinquency proceeding be the juvenile court judge.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the juveniles'' rights guaranteed under the equal protection clauses of the Wisconsin and United States Constitutions have not been violated.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the provisions in Wis.', 'general', 'State v. Hezzie R.', 'https://www.courtlistener.com/opinion/1709584/', '1709584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Jesus Cardoso v. State', 'https://www.courtlistener.com/opinion/3097908/', '3097908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial court’s judgment.', 'general', 'Jesus Cardoso v. State', 'https://www.courtlistener.com/opinion/3097908/', '3097908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts and circumstances before the trial judge when he made his decisions, we find that these two continuances satisfied the "reasonable" time limit.', 'general', 'Gay v. State', 'https://www.courtlistener.com/opinion/1667392/', '1667392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*289 Thus, we find no abuse of the trial judge''s discretion, nor do we find that the appellant''s Sixth Amendment right to compulsory process was violated.', 'general', 'Gay v. State', 'https://www.courtlistener.com/opinion/1667392/', '1667392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Judge Drake had, at a minimum,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that an appointed municipal court judge did not meet the constitutional requirements to hear and decide state cases.', 'general', 'State Ex Rel. Newsom v. Biggers', 'https://www.courtlistener.com/opinion/1667477/', '1667477') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the legislature’s attempt to vest the judicial authority of the juvenile court in the county executive was invalid.', 'general', 'State Ex Rel. Newsom v. Biggers', 'https://www.courtlistener.com/opinion/1667477/', '1667477') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons appearing below, we affirm the judgment of the Court of Criminal Appeals, 1994 WL 201829, holding the judge to be a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals.', 'general', 'State Ex Rel. Newsom v. Biggers', 'https://www.courtlistener.com/opinion/1667477/', '1667477') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Criminal Appeals’ holding that this issue has been waived.', 'general', 'State Ex Rel. Newsom v. Biggers', 'https://www.courtlistener.com/opinion/1667477/', '1667477') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court abused its discretion by requiring defendant to wear leg shackles in the courtroom because the court’s decision in this regard was not supported by the record evidence.', 'general', 'People v. Payne', 'https://www.courtlistener.com/opinion/1668200/', '1668200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion with respect to defendant’s personal appearance.', 'general', 'People v. Payne', 'https://www.courtlistener.com/opinion/1668200/', '1668200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the nature of the sentencing offense, and given defendant’s criminal history at the time, we conclude that the sentence of 40 to 60 years in prison did not violate the principle of proportionality.', 'sentencing', 'People v. Payne', 'https://www.courtlistener.com/opinion/1668200/', '1668200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that the reports constituted inadmissible hearsay, and were admitted in error.', 'general', 'People v. Payne', 'https://www.courtlistener.com/opinion/1668200/', '1668200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'plain-error rule sets a high bar for appellate review in cases of unpreserved error, we conclude that the plainly erroneous admission of the testimonial DNA reports in Kent Circuit Court Case Nos.', 'general', 'People v. Payne', 'https://www.courtlistener.com/opinion/1668200/', '1668200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'People v. Payne', 'https://www.courtlistener.com/opinion/1668200/', '1668200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '06 of Uniform Criminal Rules of Circuit Court Practice, we reverse.', 'general', 'Box v. State', 'https://www.courtlistener.com/opinion/1668717/', '1668717') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we reverse, the opinion of the Court wholly fails to articulate a principled basis for so doing.', 'general', 'Box v. State', 'https://www.courtlistener.com/opinion/1668717/', '1668717') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Then we affirm or reverse, seemingly willy nilly.', 'general', 'Box v. State', 'https://www.courtlistener.com/opinion/1668717/', '1668717') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding the record insufficient to determine whether Edmond received the proper due process requirements of a revocation proceeding, we reverse and remand this case to the circuit court for a determination of whether Edmond was afforded a proper revocation proceeding.', 'general', 'Edmond v. MISSISSIPPI DEPT. OF CORRECTIONS', 'https://www.courtlistener.com/opinion/1671170/', '1671170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that Edmond''s claims are not time-barred pursuant to the three-year statute of limitations as set forth in § 99-39-5(2) and finding that there is insufficient evidence to determine whether Edmond was afforded proper revocation procedure, we reverse and remand this case to the circuit court for a proper evidentiary hearing.', 'general', 'Edmond v. MISSISSIPPI DEPT. OF CORRECTIONS', 'https://www.courtlistener.com/opinion/1671170/', '1671170') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lara', 'https://www.courtlistener.com/opinion/1709753/', '1709753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991)], we held that the trial judge must seek a commitment from the prosecutor that the potential defense witness will not be prosecuted, but that even if no commitment is forthcoming, “the trial judge must make an independent assessment, based on all of the circumstances, of the likelihood of prosecution.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2314198/', '2314198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that even when the prosecutor cannot “make a commitment” that a potential defense witness will not be prosecuted, “the trial judge must make an independent assessment, based on all of the circumstances, of the likelihood of prosecution.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2314198/', '2314198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we held that the trial court did not abuse its discretion in denying a motion for a mistrial made immediately after a witness testified that he met the defendant in prison.', 'mistrial', 'Johnston v. State', 'https://www.courtlistener.com/opinion/1709768/', '1709768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jones, we held that a police officer''s testimony that the mark on the "stash house" window sill was made by the recoil of a high-powered rifle was admissible.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/1709768/', '1709768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court did not err in denying the following motions: to preclude challenge for cause of the potential jurors;', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/1709768/', '1709768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having carefully reviewed the record, we conclude that any alleged prejudice which may have resulted from a reference to prior incarceration was fully alleviated by the curative instruction.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/1709768/', '1709768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, based on Medina and the record in this case, we find that the following issues are without merit and do *866 not warrant discussion: whether a defendant is entitled to a statement of aggravating circumstances;', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/1709768/', '1709768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that no considerations of immunity came into play in this instance because the letters were produced by appellant''s attorney and received at trial against the defendant.', 'general', 'Johnston v. State', 'https://www.courtlistener.com/opinion/1709768/', '1709768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and death sentence.', 'sentencing', 'Johnston v. State', 'https://www.courtlistener.com/opinion/1709768/', '1709768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed, we affirm appellant''s conviction and imposition of the death sentence.', 'sentencing', 'Johnston v. State', 'https://www.courtlistener.com/opinion/1709768/', '1709768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Article VI, section 14 does apply to such proceedings when either the intended purpose or the actual purpose or effect of the monetary assessment is to serve as a punitive measure.', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that the actual purpose and effect of all these sanctions were to impose punishment for ordinance violations.', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that Tennessee Code Annotated section 6-54-306 does not facially violate Article VI, section 14.', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to section 55-10-307, we hold that this statute does not violate Article XI, section 8 for the sole reasons that a distinction is made between municipalities and unincorporated areas of the state or that different punishments may be imposed by substantially similar or identical offenses.', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that Davis lacks legal standing to challenge the policies and practices of the City of Chattanooga that arguably infringe upon the District Attorney General’s constitutional and statutory authority in Hamilton County.', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons given herein, we hold that proceedings involving the violation of a municipal ordinance may be subject to the limitations of Article VI, section 14 when either the intended purpose or the actual purpose or effect of the monetary assessment is to serve as a punitive measure.', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With regard to Barrett’s ease, we hold that the actual purpose and effect of these sanctions were to punish the violations of the Code of Laws and that these five fines must also be reduced to fifty dollars each.', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 660 (“We hold that the imposition of a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a monetary sanction imposed for a municipal ordinance violation falls within the scope of Article VI, section 14 when: (1) the legislative body creating the sanction primarily intended that the sanction punish the offender for the violation of an ordinance;', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Article VI, section 14 applies with regard to these fines.', 'general', 'City of Chattanooga v. Davis', 'https://www.courtlistener.com/opinion/1677203/', '1677203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that, in the course of deciding a motion for new trial, a judge may evaluate the credibility of the witnesses.', 'general', 'People v. Herbert', 'https://www.courtlistener.com/opinion/1677370/', '1677370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[16]  Earlier, we held that Judge Sosnick had full authority to reconsider Judge Thorburn''s earlier rulings.', 'general', 'People v. Herbert', 'https://www.courtlistener.com/opinion/1677370/', '1677370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The defendant asks that we reverse Judge Sosnick''s denial of the motion for a directed verdict.', 'general', 'People v. Herbert', 'https://www.courtlistener.com/opinion/1677370/', '1677370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the record, we find that no specific grounds for appellant''s objections were given.', 'general', 'Lee v. State', 'https://www.courtlistener.com/opinion/1677607/', '1677607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that a genuine issue of material fact does exist under this record as to whether reasonable grounds existed to believe that placing the cap on the check-out counter where the cashier had access to it— along with the other items — was an effort to conceal the cap in an effort to deprive the owner of it.', 'general', 'Lenstra v. Menard, Inc.', 'https://www.courtlistener.com/opinion/1677954/', '1677954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Lenstra v. Menard, Inc.', 'https://www.courtlistener.com/opinion/1677954/', '1677954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'these reasons, we reverse the trial court’s grant of summary judgment as to both counts of plaintiffs petition and remand this case to the district court for further proceedings in accordance with this decision.', 'general', 'Lenstra v. Menard, Inc.', 'https://www.courtlistener.com/opinion/1677954/', '1677954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying long-established Nebraska precedent to the cross-examination of Olsan, we conclude that the prosecutor transgressed the mandatory boundaries of Neb.', 'general', 'State v. Olsan', 'https://www.courtlistener.com/opinion/1678545/', '1678545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 897 (1987), we reversed a defendant’s conviction because the prosecutor had exceeded the proper scope for cross-examination of the defendant regarding a previous conviction used for impeachment.', 'general', 'State v. Olsan', 'https://www.courtlistener.com/opinion/1678545/', '1678545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this jurisdiction’s liquor control statute does impose a duty upon a tavern keeper not to serve a person under the influence of liquor.', 'general', 'Ono v. Applegate', 'https://www.courtlistener.com/opinion/1270764/', '1270764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the consequences of serving liquor to an intoxicated motorist, in light of the universal use of automobiles and the increasing frequency of accidents involving drunk drivers, are foreseeable to a tavern owner.', 'general', 'Ono v. Applegate', 'https://www.courtlistener.com/opinion/1270764/', '1270764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons hereinafter set forth, we affirm the decision of the court below.', 'general', 'Ono v. Applegate', 'https://www.courtlistener.com/opinion/1270764/', '1270764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to appellants’ analogy to recognized evidentiary privileges, contrary to appellants’ claim, we conclude that the Shield Law is not comparable to the attorney-client privilege, or, for that matter, to any other privilege with respect to the issue presented here.', 'general', 'Castellani v. Scranton Times, L.P.', 'https://www.courtlistener.com/opinion/2313266/', '2313266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the identity of the source was already known and the statements at issue were not confidential, we concluded that the Shield Law did not prevent disclosure of the murder-defendant’s statements to the reporter.', 'general', 'Castellani v. Scranton Times, L.P.', 'https://www.courtlistener.com/opinion/2313266/', '2313266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the amendment did not impact Erkins’s ability to prepare his defense, we conclude that the trial court did not err in permitting the change.', 'general', 'Kenyatta Erkins v. State of Indiana', 'https://www.courtlistener.com/opinion/2685885/', '2685885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the probative evidence and reasonable inferences supporting the verdict, we conclude that a reasonable fact-finder could find, beyond a reasonable doubt, that Erkins intended and agreed with Ojile to rob and seriously injure S.', 'general', 'Kenyatta Erkins v. State of Indiana', 'https://www.courtlistener.com/opinion/2685885/', '2685885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State met its burden and affirm Erkins’s conviction.', 'general', 'Kenyatta Erkins v. State of Indiana', 'https://www.courtlistener.com/opinion/2685885/', '2685885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Erkins’s conviction.', 'general', 'Kenyatta Erkins v. State of Indiana', 'https://www.courtlistener.com/opinion/2685885/', '2685885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Accordingly, we hold that a probationer, like a parolee, is entitled to a preliminary and a final revocation hearing, under the conditions specified in Morrissey v.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/1729457/', '1729457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Even though the revocation of parole is not a part of the criminal prosecution, we held that the loss of liberty entailed is a serious deprivation requiring that the parolee be accorded due process.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/1729457/', '1729457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we held that a parolee is entitled to two hearings, one a preliminary hearing at the time of his arrest and detention to determine whether there is probable cause to believe that he has committed a violation of his parole and the other a somewhat more comprehensive hearing prior to the making of the final revocation decision.', 'probable_cause', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/1729457/', '1729457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, this Court held in Brill v.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/1729457/', '1729457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the Eighth Amendment does not guarantee a right to bail pending revocation of probation.', 'general', 'Bernhardt v. State', 'https://www.courtlistener.com/opinion/1729457/', '1729457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth herein, we affirm.', 'general', 'State v. Owen', 'https://www.courtlistener.com/opinion/1710259/', '1710259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons previously set forth, we affirm the decision of the Buffalo County District Court which affirmed Owen’s conviction and sentence.', 'sentencing', 'State v. Owen', 'https://www.courtlistener.com/opinion/1710259/', '1710259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court’s response to appellant’s request was sufficient to meet the requirements of Tex.', 'general', 'Beebe v. State', 'https://www.courtlistener.com/opinion/1682111/', '1682111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that the Court of Appeals was correct in not subjecting this error to a harm analysis.', 'general', 'Beebe v. State', 'https://www.courtlistener.com/opinion/1682111/', '1682111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed above, we find that appellant’s trial attorney did request additional time under art.', 'general', 'Beebe v. State', 'https://www.courtlistener.com/opinion/1682111/', '1682111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that no waiver occurred when appellant was compelled to go to trial eight days after the State was allowed to amend the indictment.', 'general', 'Beebe v. State', 'https://www.courtlistener.com/opinion/1682111/', '1682111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we hold that a defendant seeking a jury instruction on perfect self-defense to a charge of first-degree intentional homicide must satisfy an objective threshold showing that she reasonably believed that she was preventing or terminating an unlawful interference with her person and reasonably believed that the force she used was necessary to prevent imminent death or great bodily harm.', 'jury_instruction', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we hold that a defendant seeking a jury instruction on unnecessary defensive force (imperfect self-defense) to a charge of first-degree intentional homicide is not required to satisfy an objective threshold showing that she was acting under a reasonable belief that she was in imminent danger of death or great bodily harm or that the force she used was necessary to defend herself.', 'jury_instruction', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, we hold that a defendant who claims self-defense to a charge of first-degree intentional homicide *208 may use evidence of a victim''s violent character and past acts of violence to show a satisfactory factual basis that she actually believed she was in imminent danger of death or great bodily harm and actually believed that the force used was necessary to defend herself, even if both beliefs were unreasonable.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a claim of imperfect self-defense, which mitigates first-degree intentional homicide to second-degree intentional homicide, does not require a showing that a person who used unnecessary defensive force was acting with a reasonable belief of an unlawful interference with her person.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because evidence that should have been admitted was excluded and because an instruction that should have been given was denied, we conclude that Debra Head is entitled to a new trial.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that Wis JICriminal 1014, the jury instruction involving the mitigation of first-degree intentional homicide to second-degree intentional homicide based on unnecessary defensive force, does not accurately reflect the law as set forth in this opinion.', 'jury_instruction', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '05(2), supported by the legislative history and articulated public policy behind the statute, we conclude that when imperfect self-defense is placed in issue by the trial evidence, the state has the burden to prove that the person had no actual belief that she was in imminent danger of death or great bodily harm, or no actual belief that the amount of force she used was necessary to prevent or terminate this interference.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that evidence of a victim''s violent character and of the victim''s prior acts of violence of which a defendant has knowledge should be considered in determining whether a sufficient factual basis exists to raise a claim of self-defense.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that a defendant need not meet an objective reasonable threshold to assert imperfect self-defense.', 'general', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that Debra Head was entitled to a jury instruction on second-degree intentional homicide, we note that Wis JICriminal 1014 "First Degree Intentional Homicide: Self Defense: Second Degree Intentional Homicide.', 'jury_instruction', 'State v. Head', 'https://www.courtlistener.com/opinion/1685369/', '1685369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Ceaser', 'https://www.courtlistener.com/opinion/1620316/', '1620316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Affirmatively we hold that a municipal corporation may be held liable for the torts of police officers under the doctrine of respondeat superior.', 'general', 'Everton v. Willard', 'https://www.courtlistener.com/opinion/1695024/', '1695024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, because Deputy Parker exercised a discretion inherent both in the nature of enforcement and in the implementation of basic planning level activity, we affirm the order of the trial court.', 'general', 'Everton v. Willard', 'https://www.courtlistener.com/opinion/1695024/', '1695024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Harkins sets out the proper construction of the kidnapping statute, i.', 'general', 'Faison v. State', 'https://www.courtlistener.com/opinion/1694903/', '1694903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in order to prove necessity in this context, a defendant must show that:
(1) there is a present and imminent emergency arising without fault on the part of the actor concerned;', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that public policy mandates that we extend our prior decisions regarding necessity to cases where a defendant is accused of driving under a suspended license.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that fairness demands that the defendant be required to provide notice to the prosecution of his intention to rely on the defense of necessity.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for a new trial.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we reverse on the grounds of the necessity defense, we need not address appellant''s other contention.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1294351/', '1294351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1973), this Court held that an instruction to the jury informing it, ".', 'general', 'Parker v. State', 'https://www.courtlistener.com/opinion/1702685/', '1702685') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1974), this Court held similar instructions error.', 'general', 'Parker v. State', 'https://www.courtlistener.com/opinion/1702685/', '1702685') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held an instruction reducing the right of the defendant to claim self-defense as a defense was "manifestly erroneous.', 'general', 'Parker v. State', 'https://www.courtlistener.com/opinion/1702685/', '1702685') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the purpose and policy of Beasley, we hold that all defendants facing the imposition of probation are on constructive notice of conditions one through eleven set forth in the form for order of probation, which is contained in the rules of criminal procedure.', 'general', 'State v. Hart', 'https://www.courtlistener.com/opinion/1703189/', '1703189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this was error.', 'general', 'State v. Gonsalves', 'https://www.courtlistener.com/opinion/2587727/', '2587727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we affirm the judgment and sentence of the circuit court.', 'sentencing', 'State v. Gonsalves', 'https://www.courtlistener.com/opinion/2587727/', '2587727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1706948/', '1706948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Horton', 'https://www.courtlistener.com/opinion/1708306/', '1708306') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the sentence imposed, however, because the district court did not properly apply Iowa Code section 124.', 'sentencing', 'State v. Freeman', 'https://www.courtlistener.com/opinion/2156846/', '2156846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the district court order overruling Freeman''s motion to suppress.', 'suppression', 'State v. Freeman', 'https://www.courtlistener.com/opinion/2156846/', '2156846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court order overruling Freeman''s motion to suppress because the search was incident to a lawful arrest.', 'suppression', 'State v. Freeman', 'https://www.courtlistener.com/opinion/2156846/', '2156846') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified and remand the case.', 'general', 'McGill v. State', 'https://www.courtlistener.com/opinion/1774542/', '1774542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature intended the insurance fraud statute to apply to third party claims;', 'general', 'State v. MARK MARKS, PA', 'https://www.courtlistener.com/opinion/1774680/', '1774680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the statute does apply to third party claims, and section 817.', 'general', 'State v. MARK MARKS, PA', 'https://www.courtlistener.com/opinion/1774680/', '1774680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only to this extent do we affirm the trial court''s actions, since we find that its application of "vagueness" beyond that to be erroneous.', 'general', 'State v. MARK MARKS, PA', 'https://www.courtlistener.com/opinion/1774680/', '1774680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that section 817.', 'general', 'State v. MARK MARKS, PA', 'https://www.courtlistener.com/opinion/1774680/', '1774680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 218, we held that a charge of lewd and lascivious conduct does not necessarily include assault with intent to commit rape, but that a charge of assault with intent to commit rape necessarily includes the charge of lewd and lascivious conduct.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Appellant, claiming inconsistence in the two decisions, asserts that in the Cox case we held that instructing the jury on offenses included within that of negligent homicide was reversible error, whereas we did not in the case here;', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 142, wherein this Court held that the charging part of the information containing similar phraseology as in the case at bar complied with the requirements of I.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, however, that neither driving recklessly nor under the influence of intoxicating liquor necessarily constituted offenses within the involuntary manslaughter charge of the information.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that it was error to refuse the defendant''s request for an instruction advising the jury that defendant might be found guilty of a simple assault, as an included offense.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that since the jury refused to find defendant guilty of an offense next higher in degree to simple assault, it was apparent that had the instruction been given, the jury would not have found the defendant guilty of simple assault, and that therefore there was no reversible error.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 976, this Court held that simple assault is an offense included in a charge of assault with intent to commit rape, but that error was not committed in refusing to instruct that the jury might find the accused guilty of simple assault in the absence of evidence which would tend to reduce the grade of the offense charged;', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the charge included murder in the first and second degrees, and manslaughter;', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 222, this Court held that acts going to the extent of the actual commission of the infamous crime against nature, where the victim was under 16 years of age, would also constitute lewd and lascivious conduct as a necessaily included offense.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold, in our desire to clear the confusion which has arisen in the premises, that pursuant to I.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellate counsel''s failure to *1282 raise this issue on appeal constituted deficient performance that undermined confidence in the correctness and fairness of the result of the appeal.', 'general', 'Gisi v. State', 'https://www.courtlistener.com/opinion/1780774/', '1780774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The defendant in Dealwas prosecuted for grand larceny *1047 of an automobile, and we held that the trial court had properly refused a trespass instruction since the defendant had not claimed he was joyriding or that he intended to return the vehicle after a short period of use.', 'general', 'Richmond v. State', 'https://www.courtlistener.com/opinion/1781457/', '1781457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After agreeing that in informant cases a defendant need only establish that the informant''s testimony "may be necessary to a determination of guilt or innocence," this court held that "in light of the strong public policy favoring protection of the counseling records .', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Charlotte did not waive her therapist-patient privilege, as she did not disclose any significant part of a confidential matter or communication.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In response to the court of appeals'' certified question, we conclude that there is a public policy exception to the therapist-patient privilege and to the confidentiality in patient health care records where negligent therapy causes false accusations against the parents for sexually or physically abusing their child.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that none of the records constitute a voluntary disclosure of "any significant part of the matter or communication.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Charlotte reasonably believed her communications with Phillips would be confidential with Phillips.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that public policy requires creating an exception to therapist-patient confidentiality and privilege where negligent therapy is alleged to have caused accusations against parents for sexually or physically abusing their child.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bearing this in mind, we conclude that the victim cannot impede the claim.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that Charlotte did not waive her therapist-patient privilege.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that there is a public policy exception to the therapist-patient privilege and to the confidentiality in patient health care records where negligent therapy causes false accusations against the parents for sexually or physically abusing their child.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] Therefore, we reverse the circuit court''s order and remand this case for further proceedings.', 'general', 'Johnson v. Rogers Memorial Hospital, Inc.', 'https://www.courtlistener.com/opinion/1714111/', '1714111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 770 (1982)], we held that the trial court could not find the defendant guilty of the uncharged offense of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Holscher', 'https://www.courtlistener.com/opinion/1717447/', '1717447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that no error was committed here for reason of the spousal privilege assertion, and even if so, any error would be harmless.', 'general', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that this statement does not constitute reversible error based upon a hearsay objection.', 'general', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that there is no merit to any of the seven portions of this assignment of error, and, as a consequence, to the assignment of error as a whole.', 'general', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no reversible error in this case, this Court holds that there is no aggregation of error so as to justify a reversal of Shell''s conviction on this assignment.', 'general', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having made a thorough review of this record, this Court holds that as to the above Miss.', 'general', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the "statistical aberration", which produced such a venire/jury, mandated a reversal of Mhoon''s conviction for a new sentencing hearing.', 'sentencing', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In upholding the appellant''s conviction, this Court held the following:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), this Court held that the admission of the confession to establish the corpus delicti of the underlying felony of robbery was proper so long as the corpus delicti of murder was sufficiently established.', 'general', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1976), where this Court held that a bifurcated trial was necessary in capital murder cases "to overcome problems with respect to the introduction of evidence in a death penalty case, some of which would be relevant to the sentencing decision but would have no relevance to, or may even be prejudicial to the question of guilt.', 'sentencing', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), where this Court held that while one found guilty of capital murder occurring during a robbery becomes subject to the death penalty, this penalty is not automatic.', 'general', 'Shell v. State', 'https://www.courtlistener.com/opinion/1721671/', '1721671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial judge did not abuse his discretion when he reached this conclusion.', 'general', 'Carpentino v. State', 'https://www.courtlistener.com/opinion/2639310/', '2639310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the statutory definition of "domestic violence" apparently leads to these counter-intuitive results, we conclude that the meaning of this statute is not as clear as the State would have it.', 'general', 'Carpentino v. State', 'https://www.courtlistener.com/opinion/2639310/', '2639310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reached this decision because we concluded that the trial judge mistakenly allowed the State to introduce evidence that Carpentino had gotten into bed with two other children in the same family (siblings of the victim named in the indictment).', 'general', 'Carpentino v. State', 'https://www.courtlistener.com/opinion/2639310/', '2639310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But on appeal, we concluded that the challenged evidence was relevant only to prove Carpentino''s propensity to commit sexual abuse and that the evidence was therefore barred by Evidence Rule 404(b)(1).', 'general', 'Carpentino v. State', 'https://www.courtlistener.com/opinion/2639310/', '2639310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2002), we reversed Carpentino''s convictions for sexual abuse of a minor.', 'general', 'Carpentino v. State', 'https://www.courtlistener.com/opinion/2639310/', '2639310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence sufficiently supported the verdict, that defendant''s right to confrontation was not violated, and that by failing to object, defendant waived the error relating to the prosecutor''s comment on plea bargaining.', 'plea', 'State v. Valdez', 'https://www.courtlistener.com/opinion/1129105/', '1129105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Valdez', 'https://www.courtlistener.com/opinion/1129105/', '1129105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment without prejudice to any further post-conviction proceedings defendant might institute.', 'general', 'State v. Valdez', 'https://www.courtlistener.com/opinion/1129105/', '1129105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, despite the Blockburger presumption, a determination that the Legislature allowed the imposition of two sentences would produce the absurd *605result of punishing the defendant for each aggravating factor under the statute.', 'sentencing', 'State v. Breed', 'https://www.courtlistener.com/opinion/2786013/', '2786013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that both articles are reasonably free from any call for action based upon emotional subjective judgments.', 'general', 'Crowe v. State', 'https://www.courtlistener.com/opinion/1732240/', '1732240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that sufficient evidence was presented to require that the question of appellant''s intent in taking the knife be submitted to the jury.', 'general', 'Crowe v. State', 'https://www.courtlistener.com/opinion/1732240/', '1732240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 572 (1993), we held that one who intentionally aids and abets the commission of a crime may be responsible not only for the intended crime, if it is in fact committed, but also for other crimes which are committed as a natural and probable consequence of the intended criminal act.', 'general', 'State v. Mantich', 'https://www.courtlistener.com/opinion/1734908/', '1734908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Mantich’s general objection on foundation was sufficient to preserve his objection for appeal.', 'general', 'State v. Mantich', 'https://www.courtlistener.com/opinion/1734908/', '1734908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that sexual intercourse between a husband and wife in the presence of a child under fourteen years of age for the purpose of demonstrating to such child the method of procreation of the human race is a lewd and lascivious act and a violation of Fla.', 'general', 'Chesebrough v. State', 'https://www.courtlistener.com/opinion/1830976/', '1830976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a viable substantive challenge has not been presented.', 'general', 'Longstreth v. State', 'https://www.courtlistener.com/opinion/2617538/', '2617538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no exposure to double jeopardy, we affirm.', 'general', 'Longstreth v. State', 'https://www.courtlistener.com/opinion/2617538/', '2617538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under article I, section 8, the warrant requirement has full applicability to home searches of both probationers and parolees by law enforcement.', 'general', 'State of Iowa v. Justin Dean Short', 'https://www.courtlistener.com/opinion/2687558/', '2687558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Cullison, we held that a parolee did not suffer a diminution of constitutional protections from war-rantless search and seizures simply because of his status as a parolee.', 'search_seizure', 'State of Iowa v. Justin Dean Short', 'https://www.courtlistener.com/opinion/2687558/', '2687558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the warrantless search of the parolee’s residence was invalid.', 'general', 'State of Iowa v. Justin Dean Short', 'https://www.courtlistener.com/opinion/2687558/', '2687558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More than forty years ago in Cullison, this court held that under the search and seizure provision of article I, section 8 of the Iowa Constitution, a valid warrant is required for law enforcement’s search of a parolee’s home.', 'search_seizure', 'State of Iowa v. Justin Dean Short', 'https://www.courtlistener.com/opinion/2687558/', '2687558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'because we conclude that the search of Knights was reasonable under our general Fourth Amendment approach of ‘examining the totality of the circumstances’.', 'search_seizure', 'State of Iowa v. Justin Dean Short', 'https://www.courtlistener.com/opinion/2687558/', '2687558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we reverse the district court and remand the case for further proceedings.', 'general', 'State of Iowa v. Justin Dean Short', 'https://www.courtlistener.com/opinion/2687558/', '2687558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Clark, this court held a provision of the 1857 Iowa Constitution providing “ ‘for the education of all of the youths of the State through a system of common schools’ ” required a local school board to integrate its schools.', 'general', 'State of Iowa v. Justin Dean Short', 'https://www.courtlistener.com/opinion/2687558/', '2687558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 506 (“We hold that the balance of these considerations requires no more than reasonable suspicion to conduct a search of this probationer’s house.', 'general', 'State of Iowa v. Justin Dean Short', 'https://www.courtlistener.com/opinion/2687558/', '2687558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the decision of the court of appeals and the judgment of the district court.', 'general', 'State of Iowa v. Randy Mitchell Copenhaver', 'https://www.courtlistener.com/opinion/2687658/', '2687658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals and affirm the judgment of the district court.', 'general', 'State of Iowa v. Randy Mitchell Copenhaver', 'https://www.courtlistener.com/opinion/2687658/', '2687658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in Chrisman, we held that section 714.', 'general', 'State of Iowa v. Randy Mitchell Copenhaver', 'https://www.courtlistener.com/opinion/2687658/', '2687658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In applying this definition of larceny, we found that “[t]he stealing of several articles at the same time and in the same act from the same person constitutes but one transaction, and is one act of larceny.', 'general', 'State of Iowa v. Randy Mitchell Copenhaver', 'https://www.courtlistener.com/opinion/2687658/', '2687658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find a factual basis to support the guilty plea and that the written record established Sutton understood the nature of the charge, we affirm his conviction.', 'plea', 'State of Iowa v. Walter Scott Sutton', 'https://www.courtlistener.com/opinion/2687964/', '2687964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Sutton’s judgment and sentence for public intoxication because we find a factual basis to support the plea and the court substantially complied with the requirement the defendant understand the nature of the charge to which he pled guilty.', 'sentencing', 'State of Iowa v. Walter Scott Sutton', 'https://www.courtlistener.com/opinion/2687964/', '2687964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that for someone to be guilty of public intoxication under section 123.', 'general', 'State of Iowa v. Walter Scott Sutton', 'https://www.courtlistener.com/opinion/2687964/', '2687964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taylor then filed a petition for review in this court, and we granted review only as to the second issue presented, namely: Is a sentence of 12 years of initial confinement and 6 years extended supervision excessive for this nineteen-year-old defendant who had non-forced sexual intercourse with a fifteen-year-old girl? We conclude that under the totality of the facts and circumstances of this case, the sentence is not excessive, and we affirm the court of appeals.', 'sentencing', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1742790/', '1742790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under our well-established standards for reviewing the circuit court''s exercise of its sentencing discretion, and in light of the individual facts and circumstances of this case, the circuit court exercised proper discretion in its sentence and in its refusal to modify that sentence.', 'sentencing', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1742790/', '1742790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately we concluded that "[w]hat has previously been satisfied with implied rationale must now be set forth on the record.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1742790/', '1742790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1742790/', '1742790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record demon*227strates Agent Anderson had reasonable grounds to believe the computers contained contraband and, accordingly, hold the circuit court properly denied Purtell''s motion to suppress.', 'suppression', 'State v. Jeremiah J. Purtell', 'https://www.courtlistener.com/opinion/2688488/', '2688488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, to the extent Agent Anderson''s subjective intent to search Purtell''s computer was motivated by concern he might possess still images of animal cruelty or mutilation, which was the basis for the court of appeals'' decision, we conclude that stated objective by Agent Anderson does not impact the lawfulness of the search.', 'general', 'State v. Jeremiah J. Purtell', 'https://www.courtlistener.com/opinion/2688488/', '2688488') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Heflin, we hold that the trial court did not err in refusing to instruct the jury regarding the offense of statutory involuntary manslaughter even though it instructed the jury regarding voluntary manslaughter.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Conversely, in the instant case, we hold that the trial judge did not err in refusing to instruct the jury regarding the offense of statutory involuntary manslaughter even though it instructed the jury regarding voluntary manslaughter.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Doss, we held that *499 the plaintiff does not have to prove "without malice" in order to establish commission of the alleged offense.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Arthur Jones, we held that the trial court erred in not instructing the jury regarding involuntary manslaughter because the defendant introduced some evidence by "accident.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the trial judge erred in refusing to give the instruction.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We relied upon Ora Jones, in which this Court held that the trial court erred in not instructing regarding involuntary manslaughter even though the defendant never requested the instruction because the trial court''s instruction did not accurately reflect defendant''s theory of the case.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the trial courts erred, then we must also decide whether the errors were harmless.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Heflin, we concluded that even if defendant requested an instruction with regard to a cognate lesser included offense, the trial judge must only issue the lesser included offense instruction when the evidence adduced at trial would support a conviction of that crime.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and reinstate the decision of the trial court.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the decision of the Court of Appeals and reinstate the decision of the trial court.', 'general', 'People v. Heflin', 'https://www.courtlistener.com/opinion/1745833/', '1745833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2002), Division One of this court held that resisting arrest is not a victimless crime based on aspects of the applicable statute that also exist in our riot statutes.', 'general', 'State of Arizona v. Matthew Erich Manzanedo', 'https://www.courtlistener.com/opinion/2688706/', '2688706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that, rather than creating two separate offenses, § 13-1207 creates a single offense that can be committed in alternate ways.', 'general', 'State of Arizona v. Matthew Erich Manzanedo', 'https://www.courtlistener.com/opinion/2688706/', '2688706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that "criminal history” was not necessarily equivalent to prior convictions, and therefore, the trial court''s finding was not exempt from the rule in Blakely.', 'general', 'State of Arizona v. Matthew Erich Manzanedo', 'https://www.courtlistener.com/opinion/2688706/', '2688706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his convictions and sentences.', 'sentencing', 'State of Arizona v. Matthew Erich Manzanedo', 'https://www.courtlistener.com/opinion/2688706/', '2688706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Manzanedo’s convictions.', 'general', 'State of Arizona v. Matthew Erich Manzanedo', 'https://www.courtlistener.com/opinion/2688706/', '2688706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the question presented is capable of repetition and evades review and thus address the merits.', 'general', 'State Ex Rel. Olson v. Litscher', 'https://www.courtlistener.com/opinion/1747487/', '1747487') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), this Court held that convictions of the manufacture, possession or transportation of untaxed liquor were within the crimes of dishonesty or false statement contemplated by M.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/1747920/', '1747920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we conclude that the trial court properly ordered the defendant to pay full restitution.', 'general', 'State v. Fancher', 'https://www.courtlistener.com/opinion/1227185/', '1227185') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because restitution is neither punishment nor an element of the offense, we conclude that a trial court has the authority to order restitution in full for damages caused by the criminal offense.', 'general', 'State v. Fancher', 'https://www.courtlistener.com/opinion/1227185/', '1227185') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 561 (1954), wherein this Court held that contributory negligence was not a defense against “reckless disregard of the rights of others” under the guest statute as it existed under the 1939 amendment.', 'general', 'Hodge v. Borden', 'https://www.courtlistener.com/opinion/1196080/', '1196080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the defense of contributory negligence may be asserted against alleged gross neglience, under Idaho’s present guest statute, I.', 'general', 'Hodge v. Borden', 'https://www.courtlistener.com/opinion/1196080/', '1196080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Freeman’s pretrial motion to suppress the pistol and quash the information should have been granted, and accordingly reverse his conviction.', 'suppression', 'People v. Freeman', 'https://www.courtlistener.com/opinion/1752701/', '1752701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Freeman’s conviction and remand for entry of an order quashing the information.', 'general', 'People v. Freeman', 'https://www.courtlistener.com/opinion/1752701/', '1752701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court did not err by admitting Newton’s statements.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2085821/', '2085821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We will affirm the conviction unless, based on this evidence, we conclude that no reasonable jury could find the defendant guilty beyond a reasonable doubt of each element of the crime charged.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2085821/', '2085821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant’s arguments are without merit, and, accordingly, we affirm his convictions.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2085821/', '2085821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Loschen', 'https://www.courtlistener.com/opinion/1755723/', '1755723') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because each amended section dealt in some fashion with reoffenders, we conclude that the statute meets that test.', 'general', 'Young v. State', 'https://www.courtlistener.com/opinion/1757273/', '1757273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On both points, we affirm.', 'general', 'Young v. State', 'https://www.courtlistener.com/opinion/1757273/', '1757273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We hold that defendant''s confrontation right was violated by the admission of the statements, notwithstanding that the Fischers refused to testify at trial.', 'general', 'State v. Hansen', 'https://www.courtlistener.com/opinion/1757692/', '1757692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), we held that the witness'' statements to police and her testimony at a prior trial were statements against penal interest under 804(b)(3) when they inculpated the defendant as well as the witness.', 'general', 'State v. Hansen', 'https://www.courtlistener.com/opinion/1757692/', '1757692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judgment of conviction must be reversed because introduction of the declarations violated both the hearsay rule and the confrontation clause of the sixth amendment, as incorporated in the fourteenth amendment, of the United States Constitution.', 'general', 'State v. Hansen', 'https://www.courtlistener.com/opinion/1757692/', '1757692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that under West Virginia Code § 61-8-12(b), which does not require a showing of consanguinity, a person is guilty of incest when such person engages in sexual intercourse or sexual intrusion with the step-child of his or her brother or sister.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "separate convictions for first and third-degree sexual assault and incest, although they arise from the same act, do not constitute the same offense for purposes of the double jeopardy clauses.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Doing so, we conclude that the Legislature clearly intended our incest statute and our first degree sexual assault statute to permit multiple sentences for different offenses arising from the same act.', 'sentencing', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that West Virginia Code § 61-8-12 meets the requirements of the West Virginia Constitution, Article III, Section 14, mandating that "the accused be fully and plainly informed of the character and cause of the accusation.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that these statutes are intended to permit multiple prosecutions for different offenses arising from a single act.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that separate convictions for first degree sexual assault and incest, although they arise from the same act, do not constitute the same offense for purposes of the Double Jeopardy Clause of the West Virginia Constitution.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the ruling of the circuit court.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the Appellant''s case, the circuit court properly construed and applied this statute, and thus, we affirm its ruling in this regard.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*536 We hold that the introduction of hearsay evidence at a sentencing hearing pursuant to Minn.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), we held that instructions on simple assault were not necessary where the offense charged was aggravated assault.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the appellant''s prior convictions for burglaries, automobile theft, aggravated robbery and aggravated assault as well as the PSI established the necessary propensity toward violent crimes.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), this court held that the statutory language "disposed to the commission of criminal acts of violence" was not unconstitutionally vague as applied to the appellant in that case.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the accomplices'' and Pat Staples'' testimony was adequately corroborated by independent testimony.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s findings pursuant to Minn.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant''s conviction and sentence.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/2178798/', '2178798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 59 (1987), in which this Court held expert testimony regarding common behavioral characteristics exhibited by child victims of sexual abuse was not admissible to establish abuse had occurred.', 'general', 'State v. Schumpert', 'https://www.courtlistener.com/opinion/1225396/', '1225396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions for criminal sexual conduct and kidnapping and vacate the conviction for false imprisonment.', 'general', 'State v. Schumpert', 'https://www.courtlistener.com/opinion/1225396/', '1225396') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that even though the conditional release statute applies to recidivists or repeat offenders, it is not a "recidivist" statute under Oyler.', 'general', 'Mayes v. Moore', 'https://www.courtlistener.com/opinion/1823992/', '1823992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, for all of these reasons, we conclude that conditional release is not a recidivist program which imposes an enhanced criminal penalty or sentence.', 'sentencing', 'Mayes v. Moore', 'https://www.courtlistener.com/opinion/1823992/', '1823992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the portion of the holding in Lancaster concluding that all types of gain time (including overcrowding credits) are forfeitable under the general gain time forfeiture statutes was not unforeseeable and thus there is no ex post facto violation.', 'general', 'Mayes v. Moore', 'https://www.courtlistener.com/opinion/1823992/', '1823992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that petitioners'' provisional credits were properly forfeited, they are not entitled to relief on this issue.', 'general', 'Mayes v. Moore', 'https://www.courtlistener.com/opinion/1823992/', '1823992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986), we held that emotional hardship to a victim in a sexual battery case cannot justify departure because "nearly all sexual battery cases inflict emotional hardship on the victim.', 'general', 'State v. Rousseau', 'https://www.courtlistener.com/opinion/1789525/', '1789525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this type of psychological trauma was an acceptable reason for departure for two reasons.', 'general', 'State v. Rousseau', 'https://www.courtlistener.com/opinion/1789525/', '1789525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Second, we concluded that the psychological trauma to the victim in this case was not of the same type involved in Lerma, and held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s judgment.', 'general', 'State v. Oldfield', 'https://www.courtlistener.com/opinion/1231402/', '1231402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with these numerous authorities, we hold that a law enforcement officer acting outside of his or her territorial jurisdiction has the same authority to arrest as does a private citizen and may make an extraterritorial arrest under those circumstances in which a private citizen would be authorized to make an arrest.', 'general', 'State Ex Rel. State v. Gustke', 'https://www.courtlistener.com/opinion/1302547/', '1302547') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the arrest was a valid citizen’s arrest.', 'general', 'State Ex Rel. State v. Gustke', 'https://www.courtlistener.com/opinion/1302547/', '1302547') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We find that driving under the influence of alcohol or other controlled substances falls within the scope of this precedent.', 'general', 'State Ex Rel. State v. Gustke', 'https://www.courtlistener.com/opinion/1302547/', '1302547') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the information supporting the no-knock and nighttime provisions in the search warrant was illegally obtained.', 'general', 'State v. Amundson', 'https://www.courtlistener.com/opinion/1792545/', '1792545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the searchwarrant application, when viewed in its totality, provided a reasonable basis for the issuing magistrate to conclude that probable cause exists.', 'probable_cause', 'State v. Amundson', 'https://www.courtlistener.com/opinion/1792545/', '1792545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse Amundson''s convictions, we need not reach the merits of this issue.', 'general', 'State v. Amundson', 'https://www.courtlistener.com/opinion/1792545/', '1792545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In the Interest of Dave G.', 'https://www.courtlistener.com/opinion/1221447/', '1221447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Dunlap', 'https://www.courtlistener.com/opinion/1241722/', '1241722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly submitted the two drug offenses to the jury.', 'general', 'McKinney v. State', 'https://www.courtlistener.com/opinion/1797478/', '1797478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d DCA 1990), this court held that a defendant who threw a bag of cocaine a short distance out the window of his stopped car, while surrounded by police, did not commit tampering when the bag was recovered.', 'general', 'McKinney v. State', 'https://www.courtlistener.com/opinion/1797478/', '1797478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the state proved a prima facie case of sale and possession of cocaine near a school, we reverse and remand the cause for a new trial on all three charges because the trial court committed an Allen charge error.', 'general', 'McKinney v. State', 'https://www.courtlistener.com/opinion/1797478/', '1797478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the polling of the jury was coupled with the non-standard Allen instruction, we conclude that the error was not harmless.', 'general', 'McKinney v. State', 'https://www.courtlistener.com/opinion/1797478/', '1797478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d DCA May 18, 1994), we affirmed a conviction for tampering with evidence when the defendant took a bag of marijuana from a vehicle after the police had obtained possession of the bag.', 'general', 'McKinney v. State', 'https://www.courtlistener.com/opinion/1797478/', '1797478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is a reasonable possibility that the deputy prosecutor’s comment during closing argument might have contributed to Rogan’s conviction, we hold that the deputy prosecutor’s comment constituted prosecutorial misconduct that denied Rogan his right to a fair trial.', 'general', 'State v. Rogan', 'https://www.courtlistener.com/opinion/2614563/', '2614563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In other words, we hold that reproseeution is barred where, in the face of egregious prose-cutorial misconduct, it cannot be said beyond a reasonable doubt that the defendant received a fair trial.', 'general', 'State v. Rogan', 'https://www.courtlistener.com/opinion/2614563/', '2614563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the deputy prosecutor’s remark was so egregious, from an objective standpoint, that the inference is inescapable that the remark clearly denied Rogan his right to a fair trial.', 'general', 'State v. Rogan', 'https://www.courtlistener.com/opinion/2614563/', '2614563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we hold that reprosecution is barred by the double jeopardy clause of the Hawai''i Constitution, Rogan’s contention that HRS ch.', 'general', 'State v. Rogan', 'https://www.courtlistener.com/opinion/2614563/', '2614563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that despite Ganal’s challenge to fourteen portions of the prosecution’s closing argument, the prosecution’s remarks did not constitute error in light of the overwhelming “strength of the case against Ganal[.', 'general', 'State v. Rogan', 'https://www.courtlistener.com/opinion/2614563/', '2614563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Rogan’s conviction.', 'general', 'State v. Rogan', 'https://www.courtlistener.com/opinion/2614563/', '2614563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we reverse the circuit court’s judgment, guilty conviction and sentence, and notice of entry filed on August 26,1998.', 'sentencing', 'State v. Rogan', 'https://www.courtlistener.com/opinion/2614563/', '2614563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that, where the sentencing judge was authorized to exceed the presumptive term because he found aggravating factors, these aggravating factors constituted the “good cause” required by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that Criminal Rule 35(a) employs the term “illegal sentence” in a narrow sense;', 'sentencing', 'Walsh v. State', 'https://www.courtlistener.com/opinion/2629320/', '2629320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that the superior court properly addressed the complaints Walsh raised about his attorney before and during trial.', 'general', 'Walsh v. State', 'https://www.courtlistener.com/opinion/2629320/', '2629320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the jury’s verdicts, and given the way in which Walsh litigated this case, we conclude that the error in failing to submit aggravator (c)(6) to a jury was harmless beyond a reasonable doubt.', 'general', 'Walsh v. State', 'https://www.courtlistener.com/opinion/2629320/', '2629320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained here, we AFFIRM Walsh’s convictions and we reject most of his attacks on his sentences.', 'sentencing', 'Walsh v. State', 'https://www.courtlistener.com/opinion/2629320/', '2629320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the totality of the facts of this case gave rise to a reasonable articulable suspicion that some offense, i.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1801879/', '1801879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons recited below, we affirm.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1801879/', '1801879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, upon review of the supplemented record, we find that even if said communications were privileged, no reversible error resulted in the introduction of said testimony due to the fact that appellant testified himself to these very statements later in the trial.', 'general', 'Crosslin v. State', 'https://www.courtlistener.com/opinion/1955982/', '1955982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that knowledge of whether the underlying crime is a felony is not an element of the crime of felony accessory after the fact.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, in considering an argument that the conviction of the accused for burglary could not be sustained because he had been acquitted of the attempted sexual assault which was the felony relied upon, we held that success in committing the felony was not material.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the evidence presented, even when viewed in the light most favorable to the State, is insufficient to establish that Bush entered Schantz''s apartment with the specific intent to commit a larceny.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1197752/', '1197752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the record, we find that the claimed errors, taken individually or collectively, do not constitute fundamental error.', 'general', 'Sochor v. State', 'https://www.courtlistener.com/opinion/1806584/', '1806584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we find that the prosecutor''s comments during closing argument in their totality did not rise to such a level as to pinpoint lack of remorse or warrant a new sentencing trial.', 'sentencing', 'Sochor v. State', 'https://www.courtlistener.com/opinion/1806584/', '1806584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and the death sentence.', 'sentencing', 'Sochor v. State', 'https://www.courtlistener.com/opinion/1806584/', '1806584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the Lindseys’ nuisance claim is barred by the Act unless they can establish that the alleged nuisance resulted from the negligent operation of DeGroot Dairy.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the Lindseys have failed to demonstrate a genuine issue of material fact supporting their contention that the statutory violations alleged in the preliminary injunction were the proximate cause of their claimed injury.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the Lindseys have failed to designate any evidence suggesting that their claimed injury, the loss of the use and enjoyment of their- property because of the noise and sounds associated with the Dairy, was a foreseeable consequence of the alleged statutory violations.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the Lindseys failed to designate any evidence establishing that them claimed injury was a foreseeable consequence of the alleged violations and that their claimed injury would not have occurred had the requirements of the statute been observed, we conclude that the Lindseys have failed to create a genuine issue of fact regarding whether De-Groot Dairy’s alleged statutory violations were the proximate cause of the Lindseys’ claimed injury.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, having concluded that DeGroot Dairy’s statutory violations were not the proximate cause of the Lindseys’ alleged injury, we conclude that DeGroot Dairy’s alleged violation of a statute does not give rise to liability for the Lindseys’ claimed injury, and because the Lindseys have alleged no general claims of negligence, they cannot establish that the claimed nuisance results from the negligent operation of DeGroot Dairy.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Lindseys failed to set forth specific facts demonstrating the existence of a genuinely disputed issue relating to the ownership of the grass strip, which would preclude summary judgment, we conclude that the trial court’s award of summary judgment to DeGroot Dairy on this ground was proper.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'dence refuting the Manship Affidavit which establishes that DeGroot Dairy owns the portion of the grass strip in question, we conclude that summary judgment was proper because the Lindseys have failed to designate any evidence suggesting that DeGroot Dairy recklessly, knowingly, or intentionally damaged or defaced their property, and therefore no issue of material fact remains.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not err in granting summary judgment to DeGroot Dairy upon the Lindseys’ claim of intentional infliction of emotional distress.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that the trial court’s award of summary judgment in favor of DeGroot Dairy was proper, we affirm.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, having concluded that the Lind-seys have failed to designate any evidence contrary to the trial court’s determination that the Indiana Right to Farm Act applied to the instant matter and barred the Lindseys’ nuisance claim against DeGroot Dairy, and that summary judgment was proper because no issue of material fact remained on the Lindseys’ criminal trespass, criminal mischief, or intentional infliction of emotional distress claims, we affirm the summary judgment of the trial court.', 'general', 'Lindsey v. DeGroot', 'https://www.courtlistener.com/opinion/2104958/', '2104958') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the procedure employed below, allowing impeachment by evidence of a prior nonspecified felony conviction, does not aid the trier of fact in judging a defendant''s credibility while affording a strong potential for prejudicing the defendant.', 'general', 'People v. Garth', 'https://www.courtlistener.com/opinion/1810867/', '1810867') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the critical issue when a defendant claimed a right to trial by jury is whether that right existed prior to 1776.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2310272/', '2310272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “raw physical ability” to exercise control over the marijuana was insufficient to prove constructive possession.', 'general', 'State of Iowa v. Donald Benjamin Earl Reed', 'https://www.courtlistener.com/opinion/3180691/', '3180691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse''the district court’s judgment of conviction for possession of a firearm and resulting sentence "enhancement under Iowa Code section 124.', 'sentencing', 'State of Iowa v. Donald Benjamin Earl Reed', 'https://www.courtlistener.com/opinion/3180691/', '3180691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his remaining convictions, We leave intact the court of appeals decision rejecting his ineffective-assistance-of-counsel claims.', 'ineffective_assistance', 'State of Iowa v. Donald Benjamin Earl Reed', 'https://www.courtlistener.com/opinion/3180691/', '3180691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm in part and vacate in part the court of appeals decision, reverse defendant’s convictions for possession of firearms, and remand the case for resentencing.', 'sentencing', 'State of Iowa v. Donald Benjamin Earl Reed', 'https://www.courtlistener.com/opinion/3180691/', '3180691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed his convictions.', 'general', 'State of Iowa v. Donald Benjamin Earl Reed', 'https://www.courtlistener.com/opinion/3180691/', '3180691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals rejecting Reed’s claims that his trial counsel was ineffective and vacate that court’s resolution of his remaining claims.', 'ineffective_assistance', 'State of Iowa v. Donald Benjamin Earl Reed', 'https://www.courtlistener.com/opinion/3180691/', '3180691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Reed’s remaining convictions and remand the case for resentencing consistent with this opinion.', 'sentencing', 'State of Iowa v. Donald Benjamin Earl Reed', 'https://www.courtlistener.com/opinion/3180691/', '3180691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court correctly granted summary judgment dismissing the claim of PMI for lost profits, as well as Mrozek''s claim for lost management fees that was dependent on PMI''s claim for lost profits.', 'dismissal', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that it was error to dismiss Mrozek''s and PMI''s other claims.', 'dismissal', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[7] However, after reviewing a wide range of authorities, we conclude that issue preclusion is not available based on Mrozek''s guilty pleas.', 'plea', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the following statement from the New Jersey Superior Court properly explains why applying issue preclusion should not be available based on a guilty plea:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Mrozek''s guilty pleas do not fulfill the "actually litigated" requirement for issue preclusion.', 'plea', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we decide that issue preclusion does not apply to a guilty plea and that neither judicial estoppel nor public policy bars a claim for the negligent provision of legal services, we conclude that the circuit court erred in granting summary judgment to Mallery.', 'plea', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we need not decide whether PMI''s claim is core because we conclude that PMI is correct in its contention that the bankruptcy trustee abandoned PMI''s claim against Mallery for the negligent provision of legal services.', 'general', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Morlan and Dewsnup provide the better reasoned view of the effect that a trustee''s abandonment of property has on a Chapter 7 debtor''s ability to proceed on a scheduled claim that has not been subject to administration.', 'general', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the order closing the bankruptcy proceeding did not operate as a final judgment on PMI''s claim.', 'general', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part, reverse in part and remand to the circuit court for further proceedings on Mrozek''s and PMI''s remaining claims based on the allegedly negligent provision of legal services.', 'general', 'Mrozek v. Intra Financial Corp.', 'https://www.courtlistener.com/opinion/1649623/', '1649623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we hold that a mere possibility of contradictory evidence does not, in the cause at issue, require us to determine that the trial court''s decision to admit the photographs to be an abuse of the judge''s discretion.', 'general', 'Musgrave v. State', 'https://www.courtlistener.com/opinion/1816627/', '1816627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When viewing the record as a whole, we conclude that the objection was aimed at precluding the witness from testifying after the recess to what she obviously did not know or understand before the recess.', 'general', 'Musgrave v. State', 'https://www.courtlistener.com/opinion/1816627/', '1816627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the record in its entirety, we find that this appellant has failed to show that the trial court abused its discretion by admitting these photographs into evidence.', 'general', 'Musgrave v. State', 'https://www.courtlistener.com/opinion/1816627/', '1816627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this possibility is sufficient to avoid dismissal for mootness.', 'dismissal', 'Cooper v. Cooper', 'https://www.courtlistener.com/opinion/2586077/', '2586077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because the order lacked an independent basis, it was an abuse of discretion to issue the mutual restraining order.', 'general', 'Cooper v. Cooper', 'https://www.courtlistener.com/opinion/2586077/', '2586077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'S-11649 we REVERSE the decision of the superior court granting a mutual restraining order and REMAND the case to the court with directions to VACATE the mutual restraining order.', 'general', 'Cooper v. Cooper', 'https://www.courtlistener.com/opinion/2586077/', '2586077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'S-11566 we AFFIRM the superior court’s denial of a domestic violence protective order.', 'general', 'Cooper v. Cooper', 'https://www.courtlistener.com/opinion/2586077/', '2586077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this charge we conclude that the State admits that Douglas did in some way respond to the information he either possessed or had available to him;', 'general', 'State v. Douglas', 'https://www.courtlistener.com/opinion/1820486/', '1820486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As fact finders, we conclude that defendant knew the $371,814 check was from Commonwealth and that defendant knew Commonwealth was, at least, furnishing interim financing to Judith Driscoll in December of 1977.', 'general', 'State v. Douglas', 'https://www.courtlistener.com/opinion/1820486/', '1820486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our consideration of the evidence we find that the allegations contained in specification No.', 'general', 'State v. Douglas', 'https://www.courtlistener.com/opinion/1820486/', '1820486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we find that Douglas is guilty of specification No.', 'general', 'State v. Douglas', 'https://www.courtlistener.com/opinion/1820486/', '1820486') ON CONFLICT DO NOTHING;
