INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, without deciding whether an equity court is empowered to extend a noncompetition provision on breach of the provision, we hold that in imposing a sanction for civil contempt, a court cannot use, as a requisite to purge contempt, a condition that, if fulfilled for compliance with a court’s order, affords equitable relief to a party.', 'general', 'Dunning v. Tallman', 'https://www.courtlistener.com/opinion/2220653/', '2220653') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that indemnification by an award of damages is unavailable in a contempt proceeding.', 'general', 'Dunning v. Tallman', 'https://www.courtlistener.com/opinion/2220653/', '2220653') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing, we reverse the district court’s judgment which imposed a fine on Dunning for her civil contempt.', 'general', 'Dunning v. Tallman', 'https://www.courtlistener.com/opinion/2220653/', '2220653') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the amount of attorney fee and costs awarded by the district court is supported by sufficient evidence and was not an abuse of discretion, we affirm the district court’s judgment assessing costs to Dunning, including a fee for Tallman’s lawyer.', 'general', 'Dunning v. Tallman', 'https://www.courtlistener.com/opinion/2220653/', '2220653') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was more than sufficient evidence of intent.', 'general', 'DeRamus v. State', 'https://www.courtlistener.com/opinion/1822222/', '1822222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment, and do not discuss the other
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Clinton Couch v. State of Indiana', 'https://www.courtlistener.com/opinion/2728940/', '2728940') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'Clinton Couch v. State of Indiana', 'https://www.courtlistener.com/opinion/2728940/', '2728940') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), we held that "[t]he word ''service,'' as it is used in [Wis.', 'general', 'State v. Denton', 'https://www.courtlistener.com/opinion/1301368/', '1301368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erroneously exercised its discretion when it admitted a computer-generated exhibit created and presented by a police officer who was not an expert, and who possessed no firsthand knowledge of the facts depicted in the animation which purportedly illustrated the State''s key witnesses'' combined testimony of "what people did" during the alleged crime.', 'general', 'State v. Denton', 'https://www.courtlistener.com/opinion/1301368/', '1301368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in its determination permitting admissibility of the exhibit.', 'general', 'State v. Denton', 'https://www.courtlistener.com/opinion/1301368/', '1301368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that it does.', 'general', 'State v. Denton', 'https://www.courtlistener.com/opinion/1301368/', '1301368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in its admission of the State''s computer-generated animation and that the error was not harmless.', 'general', 'State v. Denton', 'https://www.courtlistener.com/opinion/1301368/', '1301368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we reverse that determination.', 'general', 'State v. Denton', 'https://www.courtlistener.com/opinion/1301368/', '1301368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgments and orders and remand for further proceedings.', 'general', 'State v. Denton', 'https://www.courtlistener.com/opinion/1301368/', '1301368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because this construction gives independent meaning to each word in the motor-vehicle-theft statute and reconciles it with the simple-robbery statute and the common law of larceny, we hold that to “take” a motor'' vehicle under Minn.', 'general', 'State v. Thonesavanh', 'https://www.courtlistener.com/opinion/8282623/', '8282623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Solomon, we held that even temporary “control or- dominion” over another’s property was sufficient to “complete” the offense of simple robbery, even if there was no evidence that the defendant, had “earr[ied] away” the property.', 'general', 'State v. Thonesavanh', 'https://www.courtlistener.com/opinion/8282623/', '8282623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Madden, which also involved a car, we held that a common-law larceny had occurred because “[t]he car ran a distance of at least 150 feet before it mounted a curb,” but this conclusion was tied to our analysis of the “carrying away” element, not the “taking” element.', 'general', 'State v. Thonesavanh', 'https://www.courtlistener.com/opinion/8282623/', '8282623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that three canons, one intrinsic and two extrinsic, favor a construction of the word “takes” that requires adverse possession, not movement.', 'general', 'State v. Thonesavanh', 'https://www.courtlistener.com/opinion/8282623/', '8282623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude- that an individual does not need to move a- vehicle to “take” it, we reverse the decision of the court of appeals.', 'general', 'State v. Thonesavanh', 'https://www.courtlistener.com/opinion/8282623/', '8282623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the decision of the court of appeals and remand to the district court for further proceedings consistent with this opinion.', 'general', 'State v. Thonesavanh', 'https://www.courtlistener.com/opinion/8282623/', '8282623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998) ("Accordingly, we hold that the rule articulated in Sorensen, 895 P.', 'general', 'Chapman v. State', 'https://www.courtlistener.com/opinion/2629866/', '2629866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1186-87, this court held there was no plain error in admission of expert testimony on battered woman''s syndrome to explain the victim''s behavior.', 'general', 'Chapman v. State', 'https://www.courtlistener.com/opinion/2629866/', '2629866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that expert testimony regarding PTSD is sufficiently reliable to warrant admission, and we find no error on this ground.', 'general', 'Chapman v. State', 'https://www.courtlistener.com/opinion/2629866/', '2629866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[We find that CSAAS evidence has yet to reach the stage of development which would permit an expert to reasonably conclude, on the basis of CSAAS alone, that abuse occurred.', 'general', 'Chapman v. State', 'https://www.courtlistener.com/opinion/2629866/', '2629866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no such errors, we affirm.', 'general', 'Chapman v. State', 'https://www.courtlistener.com/opinion/2629866/', '2629866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed above, we hold that sentencing judges should evaluate the Miller factors at that time to “take into account how children are different, and how those differences counsel against irrevocably sentencing them to a lifetime in prison.', 'sentencing', 'State v. Zuber', 'https://www.courtlistener.com/opinion/7411277/', '7411277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, before a judge imposes consecutive terms that would result in a lengthy overall term of imprisonment for a juvenile, the court must consider the Miller factors along with other traditional concerns.', 'general', 'State v. Zuber', 'https://www.courtlistener.com/opinion/7411277/', '7411277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the same concerns apply to sentences that are the practical equivalent of life without parole, like the ones in these appeals.', 'sentencing', 'State v. Zuber', 'https://www.courtlistener.com/opinion/7411277/', '7411277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*448To be clear, we find that the force and logic of Millers concerns apply broadly: to cases in which a defendant commits multiple offenses during a single criminal episode;', 'general', 'State v. Zuber', 'https://www.courtlistener.com/opinion/7411277/', '7411277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” But we find that the lengthy term-of-years sentences imposed on the juveniles in these cases are sufficient to trigger the protections of Miller under the Federal and State Constitutions.', 'sentencing', 'State v. Zuber', 'https://www.courtlistener.com/opinion/7411277/', '7411277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand Zuber’s case and affirm and remand Comer’s case.', 'general', 'State v. Zuber', 'https://www.courtlistener.com/opinion/7411277/', '7411277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because he first raises the error in the identification of the proper statutory paragraph on appeal, we conclude that he has waived the right to do so by not timely raising the issue in the trial court.', 'general', 'State v. PILTZ', 'https://www.courtlistener.com/opinion/1295599/', '1295599') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that jurors could reasonably conclude beyond a reasonable doubt from the testimony at trial that Piltz knowingly appeared nude before two pre-teen girls, thus exposing his genitals in such a place and manner that he knew or had reason to know that he was doing so in the presence of other persons.', 'general', 'State v. PILTZ', 'https://www.courtlistener.com/opinion/1295599/', '1295599') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶13 We conclude that the testimony at trial was sufficient to establish the element of indecency to the requisite standard.', 'general', 'State v. PILTZ', 'https://www.courtlistener.com/opinion/1295599/', '1295599') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the appealed judgment, as modified to reflect the correct statutory paragraph for the offense Piltz committed.', 'general', 'State v. PILTZ', 'https://www.courtlistener.com/opinion/1295599/', '1295599') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶14 For the reasons discussed above we affirm the appealed judgment.', 'general', 'State v. PILTZ', 'https://www.courtlistener.com/opinion/1295599/', '1295599') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that as long as there is sufficient evidence for the State to make a prima facie showing that each defendant committed the murder by his or her own conduct, the State is permitted to charge more than one defendant with capital murder, even where it is clear that only one person actually killed the victim by his own conduct.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*446Thus, we conclude that the trial judge’s findings of facts were not clearly erroneous.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when the Legislature adopted the Attorney General’s suggested change, it intended to make any prior murder committed by a defendant at any time and at any place an aggravating factor.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that defendant is not entitled to a reversal of his death sentence or a new penalty-phase trial based on the exeusal of Clevenger for cause.', 'sentencing', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regardless, we find that the trial court did not abuse its discretion when failing to excuse Beebe for cause.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court did not err in failing to excuse this potential juror for cause.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not err in failing to exclude any of the nine jurors challenged in this appeal.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court properly denied defendant’s request for a stay.', 'general', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm all of the convictions as well as the sentence of death.', 'sentencing', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and capital and noncapital sentences.', 'sentencing', 'State v. Simon', 'https://www.courtlistener.com/opinion/1536017/', '1536017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he has not.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As part of that decision, we held that requiring sex offenders to register is not punishment.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Adams, we held that the legislature’s intent in requiring registration of sex offenders was to create an additional measure of protection for children from the increasing incidence of sexual assault and child abuse.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 500, 512-13 (1999), this court held that the legislature could pass legislation that amended several acts, as long as the amendments related to the single subject of “crime.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that defendant has not met his burden of showing that the Notification Law has such a punitive effect that the legislature’s intent to create a nonpunitive scheme may be disregarded.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering all of the relevant factors, we conclude that the requirements of the Notification Law are nonpunitive.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the appellate court’s decision to reverse defendant’s sentence and remand the cause for resentencing.', 'sentencing', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held: “We fail to see how any stigma attaches to a registrant that is not already present through his own actions.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in Boykin v.', 'general', 'Moosani v. State', 'https://www.courtlistener.com/opinion/1716683/', '1716683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that manifest injustice will result if a sentence is imposed without consideration being given to evidence of Smith’s and King’s amenability to rehabilitation.', 'sentencing', 'Smith v. State', 'https://www.courtlistener.com/opinion/1354602/', '1354602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the panel’s focus on the fairness of the presumptive term, rather than on the fairness of imposing a sentence without any consideration of evidence relating to potential for rehabilitation, constituted error.', 'sentencing', 'Smith v. State', 'https://www.courtlistener.com/opinion/1354602/', '1354602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we held that "Judge Chinn had no jurisdiction to change a sentence which a defendant had already begun serving.', 'sentencing', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Winder, we held that there was no violation of the 270-day rule where there was good cause shown for delay.', 'general', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990) where we held that "[a] court can only act as specifically authorized by either the Constitution or by statute.', 'general', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that circuit courts have the inherent authority to control proceedings before it and the conduct of those participating in such proceedings.', 'general', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held "the circuit judge clearly has the authority to inquire into Wigginton''s sentence, and see if there was any basis at all for Wigginton''s removal from the program, and it remains discretionary with the circuit judge to determine whether or not Wigginton''s sentence should be reviewed.', 'sentencing', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), this Court held, "[t]here is no simple, black-letter definition of conduct prejudicial to the administration of justice which brings the judicial office into disrepute.', 'general', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although, we recognized that "there has been a vast expansion by statutory enactment of the times within which circuit judges are lawfully empowered to conduct court affairs", this Court held that "the passage of the next term of court deprived the circuit court of any further authority to reinstate [the convictions].', 'general', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), where this Court held that the "precise holding of Spevack was that an attorney could not be disbarred solely for relying on his privilege against self incrimination and refusing to honor a subpoena duces tecum.', 'general', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Moreover, *945 this Court held "[c]areful analysis of Spevack and In re Ruffalo [390 U.', 'general', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, this Court held, "the attorney''s `guilt'' need not be established beyond a reasonable doubt, as in criminal cases.', 'general', 'Miss. Com''n of Jud. Perform. v. Russell', 'https://www.courtlistener.com/opinion/1826525/', '1826525') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Marcelletti v. Bathani', 'https://www.courtlistener.com/opinion/1625994/', '1625994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Bubar', 'https://www.courtlistener.com/opinion/2323195/', '2323195') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that an individual, such as Meier, who provides alcohol to an underage person that is a substantial factor in causing an accident cannot be considered an injured third party under Wis.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an individual who provides alcohol to an underage person that is a substantial factor in causing an accident is not a third party under Wis.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In deciding the issue today, we conclude that an individual who provides alcohol to an underage person that is
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with that statement, we conclude that as a result of the interplay of the terms "provider" and "3rd party" reasonable minds can differ as to the meaning of the statute.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the legislative goal of the statute is to deter the very conduct in which Meier engaged and that conduct was a substantial factor in bringing about his injuries, we conclude that he cannot take advantage of the exception to immunity in an action against another provider.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this canon of strict construction is inapplicable to § 125.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in mind and because the statute tracks the language of the case law, we conclude that the statute is not one in derogation of the common law, but indeed is one that attempted to codify the common law as it existed in 1985.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that a person "who contributes money with the intent of bringing about the purchase of alcohol beverages for consumption by an underage person whom the person knows, or should know, is under the legal drinking age, procures alcohol beverages for the underage person within the meaning of Wis.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '035(2), we find that cases based upon pre-statutory law but decided after that statute was passed do not bear on the statute''s interpretation and are of no assistance in our determination of legislative intent.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the orders of the circuit court.', 'general', 'Meier Ex Rel. Meier v. Champ''s Sport Bar & Grill, Inc.', 'https://www.courtlistener.com/opinion/1829149/', '1829149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon this interpretation of the statute, we hold that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'four enumerated factors in section 76-10-501(6)(b), we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence considered by the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, it is ordered that petitioner be and he is hereby remanded to the custody of the respondent with directions that he be presented to the Criminal Court of Record of Palm Beach County, Florida, for the imposition of judgment and the appropriate sentence pursuant to § 847.', 'sentencing', 'Adams v. Culver', 'https://www.courtlistener.com/opinion/1829242/', '1829242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the judgment and sentence imposed against her.', 'sentencing', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/1987047/', '1987047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that La.', 'general', 'State v. Brenan', 'https://www.courtlistener.com/opinion/1833400/', '1833400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review of the record, legislative history, and applicable law, we affirm for the following reasons.', 'general', 'State v. Brenan', 'https://www.courtlistener.com/opinion/1833400/', '1833400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Performing this balancing test in the context of cases requiring proof of felon status, we conclude that the admission of a defendant’s record of conviction creates a risk that he will be unfairly prejudiced.', 'general', 'People v. Walker', 'https://www.courtlistener.com/opinion/2227613/', '2227613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that revealing the name and nature of defendant’s prior conviction to the jury was prejudicial to defendant and cannot be viewed as harmless error.', 'general', 'People v. Walker', 'https://www.courtlistener.com/opinion/2227613/', '2227613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the appellate court’s ruling and hold that, in the case at bar, the trial court committed reversible error when it admitted evidence of the name and nature of defendant’s prior felony conviction rather than accept defendant’s offer to stipulate to his felon status.', 'general', 'People v. Walker', 'https://www.courtlistener.com/opinion/2227613/', '2227613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we affirm the appellate court’s reversal of defendant’s convictions on other grounds and the cause is being remanded for a new trial, we need not decide whether this error constitutes an independent basis for reversing defendant’s convictions, nor is it necessary to engage in a harmless error review.', 'general', 'People v. Walker', 'https://www.courtlistener.com/opinion/2227613/', '2227613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellant was properly sentenced for the commission of a third degree felony.', 'sentencing', 'McConnell v. State', 'https://www.courtlistener.com/opinion/1836327/', '1836327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in order to avoid problems of proof on this issue, we hold that as an absolute rule it is reversible error for the trial court sitting without a jury to refer to the transcript of testimony taken at the preliminary examination except under the exceptions provided by statute.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the defendant was denied due process of law because "[a]ppeal board panels which are membered by fulltime law enforcement officials are not fair and impartial tribunals to adjudge a law enforcement dispute between a citizen and a police officer.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 344 (1995), in which the Court of Appeals held: "we conclude that the nature and scope of the media exposure create an appearance of bias in this case.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Judge Giddings'' apparent conflict with the Governor is not a proper basis for disqualification under the test or the scenarios articulated in Crampton.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that Judge Giddings'' advice to the plaintiffs appearing in propria persona regarding the structure of their motion was appropriate.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the lower court record, we find that the actions of Judge Giddings do not constitute a deprivation of the department''s due process guarantee of an unbiased and impartial decisionmaker.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ordered that from and after September 18, 1989, Defendant, its officers, agents, servants, employees, and those acting in concert or participation with them are restrained and enjoined from:
(1) implementation of M.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the Court of Appeals decision requiring disqualification and remand to the trial court for swift, fair, and accurate resolution.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the disqualification of Judge Giddings was erroneously ordered by the Court of Appeals, we reverse and remand this case for immediate scheduling of trial.', 'general', 'Cain v Department of Corrections', 'https://www.courtlistener.com/opinion/1953592/', '1953592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statute is neither unconstitutional on its face nor as applied in this case.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1841184/', '1841184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1841184/', '1841184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Fourteenth Court of Appeals.', 'general', 'Stennett v. State', 'https://www.courtlistener.com/opinion/1780677/', '1780677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Heuser we held that intent to manufacture could be inferred from the possession of an unusually large amount of pseudoephedrine by one who also possessed lithium batteries that might be of use in the manufacturing process.', 'general', 'State v. Truesdell', 'https://www.courtlistener.com/opinion/1843643/', '1843643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the possession of a large quantity of product, without additional evidence, either direct or circumstantial, is insufficient proof of intent to manufacture under the statute.', 'general', 'State v. Truesdell', 'https://www.courtlistener.com/opinion/1843643/', '1843643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment and sentence for possession of a precursor with intent to manufacture, and remand for dismissal of the charge.', 'dismissal', 'State v. Truesdell', 'https://www.courtlistener.com/opinion/1843643/', '1843643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and sentence of the district court for OWI third offense, driving while barred, and theft in the fourth degree.', 'sentencing', 'State v. Truesdell', 'https://www.courtlistener.com/opinion/1843643/', '1843643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that there was no obvious error in the court’s instructions, we need not and do not evaluate this separate contention.', 'general', 'State v. Pabon', 'https://www.courtlistener.com/opinion/2326373/', '2326373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Pabon', 'https://www.courtlistener.com/opinion/2326373/', '2326373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today we affirmatively adopt the federal reasonable probability standard as part of the third element of the Rule 52(b) test.', 'general', 'State v. Pabon', 'https://www.courtlistener.com/opinion/2326373/', '2326373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the Ordinance does not impact more conduct than necessary to carry out its purpose.', 'general', 'State v. Doe', 'https://www.courtlistener.com/opinion/2630104/', '2630104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we find that the Ordinance is not unconstitutionally overbroad.', 'general', 'State v. Doe', 'https://www.courtlistener.com/opinion/2630104/', '2630104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the “loiter, idle, wander, stroll, play, or otherwise be upon” language is not unconstitutionally vague.', 'general', 'State v. Doe', 'https://www.courtlistener.com/opinion/2630104/', '2630104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that if the minor is in possession of documentation from one of the specified authorities and is engaged in the activity permitted by that document, he or she is engaged in legitimate business or an emergency errand.', 'general', 'State v. Doe', 'https://www.courtlistener.com/opinion/2630104/', '2630104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the Ordinance is enacted through the least restrictive means necessary to vindicate the government interest at issue.', 'general', 'State v. Doe', 'https://www.courtlistener.com/opinion/2630104/', '2630104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that analysis to be flawed because it did not demonstrate “a realistic danger that the statute itself will significantly compromise recognized First Amendment protections of parties not before the court.', 'general', 'State v. Doe', 'https://www.courtlistener.com/opinion/2630104/', '2630104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Doe', 'https://www.courtlistener.com/opinion/2630104/', '2630104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the underlying nature of the contempt order in the instant case is to advance R.', 'general', 'Department of Children and Families v. RH', 'https://www.courtlistener.com/opinion/1901449/', '1901449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the state must prove additional elements to establish a felony forgery as opposed to a misdemeanor forgery, we hold that the challenged statutes do not violate equal protection.', 'general', 'Hemphill v. State', 'https://www.courtlistener.com/opinion/1259959/', '1259959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The same would logically be true of faxes, and we hold that a conspiracy carried forward by sending faxes into Florida from another jurisdiction is punishable in Florida under Florida law.', 'general', 'Black v. State', 'https://www.courtlistener.com/opinion/1901523/', '1901523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Black v. State', 'https://www.courtlistener.com/opinion/1901523/', '1901523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), we conclude that the objective of these provisions is the establishment of guidelines for hospitals regarding the proper method for furnishing subpoenaed hospital records.', 'general', 'State Ex Rel. Allen v. Bedell', 'https://www.courtlistener.com/opinion/1350428/', '1350428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that medical records containing the results of blood alcohol tests ordered by medical personnel for diagnostic purposes are subject to subpoena and shall not be deemed inadmissible by virtue of the provisions of West Virginia Code § 57-5-4d.', 'general', 'State Ex Rel. Allen v. Bedell', 'https://www.courtlistener.com/opinion/1350428/', '1350428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute, by its plain terms, applies only to arrest situations.', 'general', 'Tillman v. State', 'https://www.courtlistener.com/opinion/1891198/', '1891198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record evidence here did not support a finding that defendant voluntarily exited his vehicle.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in denying defendant''s motion to suppress, and therefore that the judgment must be reversed.', 'suppression', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While recognizing the Fourth Amendment rule announced in Mimms, we held that an order to exit one''s vehicle is a "further `seizure'' within the meaning of Article Eleven.', 'search_seizure', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no basis for the exit order in the circumstances of this case involving a routine traffic stop for a speeding violation, we conclude that the trial court erred in denying defendant''s motion to suppress and therefore that the judgment must be reversed.', 'suppression', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the additional seizure represented by the officer''s request *547 that defendant exit the vehicle was unsupported by the requisite showing of need, and in violation of Chapter I, Article 11 of the Vermont Constitution.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the circumstances here in their totality, we conclude that a reasonable person in defendant''s circumstances would not have felt free to refuse when the officer asked him if he would "mind having a seat in my car while I check your license.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the seizure effected by the officer in requiring defendant to exit the vehicle was illegal, we conclude that defendant''s subsequent "consents" to the search of his person, car, and home were tainted and ineffective.', 'ineffective_assistance', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In these circumstances, we find that the basic purposes underlying the preservation rule would not be served by declining to address defendant''s arguments.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that defendant was illegally seized whenabsent any objective danger to the officer or others, or a reasonable suspicion of wrongdoinghe was required to exit the vehicle.', 'general', 'State v. Sprague', 'https://www.courtlistener.com/opinion/1892894/', '1892894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court, which was clearly aware of McLeod''s prior self-representation, did all that was "necessary relative to the circumstances to determine that [McLeod] made a knowing and intelligent [waiver]" of his right to counsel.', 'general', 'McLeod v. State', 'https://www.courtlistener.com/opinion/1695667/', '1695667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence was clearly sufficient to sustain McLeod''s convictions.', 'general', 'McLeod v. State', 'https://www.courtlistener.com/opinion/1695667/', '1695667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the 1980 adoption of article I, section 23 of the Florida Constitution, this Court held that Florida''s privacy amendment, which provides "an explicit textual foundation for those privacy interests inherent in the concept of liberty" extends to minors with respect to abortion.', 'general', 'BB v. State', 'https://www.courtlistener.com/opinion/1893270/', '1893270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Persons under the age of eighteen are still considered minors, and as this Court held in Jones, the legislature has a strong policy interest in protecting minors from harmful *262 sexual conduct.', 'general', 'BB v. State', 'https://www.courtlistener.com/opinion/1893270/', '1893270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with these decisions, we conclude that Florida''s clear constitutional mandate in favor of privacy is implicated in B.', 'general', 'BB v. State', 'https://www.courtlistener.com/opinion/1893270/', '1893270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having distinguished between the State''s interest in the adult-minor situation and in the minor-minor situation, we conclude that the State has failed to demonstrate in this minor-minor situation that the adjudication of B.', 'general', 'BB v. State', 'https://www.courtlistener.com/opinion/1893270/', '1893270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State failed to meet its burden in applying section 794.', 'general', 'BB v. State', 'https://www.courtlistener.com/opinion/1893270/', '1893270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 28-511(1) is neither overbroad nor vague and is, therefore, constitutional.', 'general', 'State v. Copple', 'https://www.courtlistener.com/opinion/1895384/', '1895384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that, at such hearing to determine whether the State had violated its agreement for immunity and restricted evidence or information, the State must present a prima facie case that it has fulfilled its agreement with the defendant, that is, demonstrate that the State’s evidence, to be adduced at the defendant’s trial, was obtained from a source or sources independent of the defendant and not by direct or indirect use of information obtained from the defendant as the result of ...', 'general', 'State v. Copple', 'https://www.courtlistener.com/opinion/1895384/', '1895384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that § 28-511(1) does reach a substantial amount of constitutionally protected conduct, and, therefore, Copple does have standing to challenge § 28-511(1) for overbreadth as that statute applies to his transactions with Commonwealth.', 'general', 'State v. Copple', 'https://www.courtlistener.com/opinion/1895384/', '1895384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the provisions of § 28-511, when read with §§ 28-509 and 28-510, clearly distinguish unlawful or criminal conduct from conduct which is lawful.', 'general', 'State v. Copple', 'https://www.courtlistener.com/opinion/1895384/', '1895384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we find that a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that instruction No.', 'general', 'State v. Copple', 'https://www.courtlistener.com/opinion/1895384/', '1895384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Copple’s contentions are without merit and that the instructions taken as a whole correctly state the law, are not misleading, and adequately cover the issues.', 'general', 'State v. Copple', 'https://www.courtlistener.com/opinion/1895384/', '1895384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the jury was properly instructed.', 'general', 'State v. Copple', 'https://www.courtlistener.com/opinion/1895384/', '1895384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the reasoning of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Copple', 'https://www.courtlistener.com/opinion/1895384/', '1895384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the notice of appeal in this case was timely, and therefore we will reverse the court of appeals.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/1874233/', '1874233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that no appeal was allowed from the trial court''s order.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/1874233/', '1874233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Was the sentencing complete: 1) at the initial sentencing hearing on February 12, 2001, or 2) at the time the trial court ordered restitution, on March 12, 2001? Due to the unique facts of this case, we find that the sentence was actually imposed at the restitution hearing, and we reverse the court of appeals.', 'sentencing', 'Bailey v. State', 'https://www.courtlistener.com/opinion/1874233/', '1874233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered each of Murphy’s assigned errors and finding them to be without merit, we hold that Murphy’s conviction and sentence are affirmed.', 'sentencing', 'State v. Murphy', 'https://www.courtlistener.com/opinion/1277320/', '1277320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth herein, we affirm.', 'general', 'State v. Murphy', 'https://www.courtlistener.com/opinion/1277320/', '1277320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'State v. Martinez', 'https://www.courtlistener.com/opinion/1896835/', '1896835') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the matter should be remanded for resentencing because, on the violation proceeding, the trial judge, considering the matter before Baylass and Molina were decided, violated its dictates and therefore imposed a sentence not "authorized" by N.', 'sentencing', 'State v. Ervin', 'https://www.courtlistener.com/opinion/1897919/', '1897919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Flores, supra, we concluded that a claimed violation of the Supreme Court''s guidelines developed in State v.', 'general', 'State v. Ervin', 'https://www.courtlistener.com/opinion/1897919/', '1897919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'These arguments were made at a hearing on our remand conducted after we reversed the initial summary denial of the petition for post-conviction relief without assignment of counsel.', 'general', 'State v. Ervin', 'https://www.courtlistener.com/opinion/1897919/', '1897919') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant appealed and we affirmed the sentence after argument on the Excessive Sentence calendar.', 'sentencing', 'State v. Ervin', 'https://www.courtlistener.com/opinion/1897919/', '1897919') ON CONFLICT DO NOTHING;
