INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that the circumstantial evidence presented was insufficient to convict the defendant of possession with intent to deliver methamphetamine.', 'general', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More specifically, we held that where narcotics are found in an area entirely outside the control of the defendant and exposed to the public at large, the State must provide more definite factors linking the defendant to the contraband than were provided in the Hodge case.', 'general', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on those facts, we held that “the State’s evidence failfed] to fink Hodge to constructive possession of the methamphetamine.', 'general', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 582 (1997), where we held that the chain of custody was not properly established because the methamphetamine at issue there was described differently by the undercover officer and the chemist.', 'general', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that there is insufficient evidence to support the convictions for possession of a controlled substance with intent to deliver and possession of drug paraphernalia, we reverse and dismiss those convictions.', 'dismissal', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Deputy Ring’s eyewitness account is sufficient to support the conviction of fleeing in a motor vehicle.', 'general', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the State failed to provide sufficient evidence to support the convictions based on constructive possession.', 'general', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that the trial court did not abuse its discretion in refusing to sever the charges and in admitting the flashlight into evidence.', 'general', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and dismiss the convictions of possession of a controlled substance with intent to deliver and possession of drug paraphernalia.', 'dismissal', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and dismiss the convictions for possession of a controlled substance with intent to deliver and possession of drug paraphernalia.', 'dismissal', 'Garner v. State', 'https://www.courtlistener.com/opinion/1879986/', '1879986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge did not abuse his discretion by warning a witness, out of the presence of the jury, of the consequences of perjury and committing him to jail when he gave testimony contradicting his prior statement.', 'general', 'State v. Stanley', 'https://www.courtlistener.com/opinion/1279406/', '1279406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Stanley', 'https://www.courtlistener.com/opinion/1279406/', '1279406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 462, 465 (1996), where we held that a person convicted of murder in the second degree based upon his plea of guilty was entitled to postconviction relief because the information did not allege the element of malice, and for that reason "did not sufficiently charge him with a crime.', 'plea', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 58 (1994), in which we held that it was plain error to omit the element of malice from a jury instruction defining second degree murder under § 28-304(1).', 'jury_instruction', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in Myers, this court held that the omission of malice from the jury instruction on second degree murder was prejudicially erroneous and plain error.', 'jury_instruction', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the doctrine of stare decisis forms the bedrock of our common-law jurisprudence, it does not require us to blindly perpetuate a prior interpretation of the law if we conclude that it was clearly incorrect.', 'general', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In keeping with our long-established rules of statutory construction, we conclude that the language of § 28-304(1) should be given its plain and ordinary meaning in light of the Legislature''s removal of the term "malice" from the definition of second degree murder in its 1977 revision of the criminal code.', 'general', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that construction of § 28-304(1) to include only those elements which the Legislature specifically included in its text does not result in constitutional infirmity.', 'general', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding plain error, we reversed the trial court''s decision, reasoning that "[t]o use a procedural default or waiver as a means of ignoring a plain error that results in an unconstitutional incarceration would place form over substance;', 'general', 'State v. Burlison', 'https://www.courtlistener.com/opinion/1881491/', '1881491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant has a right on timely request to change the plea, but that a court has no duty to do it on the court''s own motion.', 'plea', 'Mendez v. State', 'https://www.courtlistener.com/opinion/1859397/', '1859397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without deciding the effect, if any, that Ibarra and Cain have on a trial court''s duty to sua sponte withdraw a guilty plea under these circumstances, we hold that, under the current state of the law, appellant has waived any error by failing to call it to the trial court''s attention.', 'plea', 'Mendez v. State', 'https://www.courtlistener.com/opinion/1859397/', '1859397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*350 In the same year, ironically, we held that the trial court had no such duty in a case in which trial by jury has been waived.', 'general', 'Mendez v. State', 'https://www.courtlistener.com/opinion/1859397/', '1859397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[30] This court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[76] Some cases were the reverse of Harris: when defendants introduced evidence of insanity the trial court changed their pleas from guilty to not guilty, and we affirmed.', 'plea', 'Mendez v. State', 'https://www.courtlistener.com/opinion/1859397/', '1859397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 265 (1984), where we held that three blows to the head with a fist resulting in fractures to the face and the victim''s hospitalization for five days was sufficient to support a finding of serious physical injury.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, supra, where we held that immersion of the victim''s hands in hot water causing third-degree burns was not life-threatening conduct.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 156 (1980), we held that, in order to sustain a conviction of first-degree battery, life-endangering conduct must generally be involved.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor will we reverse absent a showing of prejudice, as prejudice is not presumed.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, in Bolden, we reversed a conviction for first-degree battery where the defendant had kicked and beaten a police officer about the head and chest, resulting in a broken jaw, because there was insufficient evidence to show that the injuries were caused by a weapon, rather than by the beating and kicking that the officer sustained.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that substantial evidence linking Mr.', 'general', 'Harmon v. State', 'https://www.courtlistener.com/opinion/1859512/', '1859512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is and reverse the Court of Appeals.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in order to constitute a "house of prostitution" a place must be one in which sexual *471 acts are committed for compensation.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with our opinion in Diversified, we hold that the abatement statute applies only to houses of prostitution, assignation or lewdness, as places where sexual acts are committed.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that the abatement statute "was intended to apply to houses of prostitution and not motion picture theaters where sexual acts are not committed but are portrayed on the screen".', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We conclude that the evidence adduced by the appellant establishes that the place was a nuisance under the statute.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, in order to determine whether instances of accosting and soliciting for purposes of prostitution constitute prohibited conduct under MCL 600.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*466 Consistent with these definitions, we find that the term assignation as used in the abatement act encompasses instances of accosting and soliciting for purposes of prostitution because such instances involve the making of an appointment for the purpose of prostitution.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[7] We find that limiting this definition to the making of an appointment for the purpose of prostitution is consistent with the apparent legislative intent to eliminate the use of property in connection with prostitution;', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing several decisions in other states,[2] we found that the statute is *469 "`directed to the abatement of * * * houses of lewdness, assignation, or prostitution''", and that the terms "lewdness, assignation, and prostitution" are synonymous.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals.', 'general', 'State Ex Rel. Wayne County Prosecuting Attorney v. Levenburg', 'https://www.courtlistener.com/opinion/1900551/', '1900551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the following instruction on excusable homicide shall be given in every homicide case in place of the short form now found on pages 61 and 62 of the manual.', 'general', 'Standard Jury Instructions-Criminal Cases', 'https://www.courtlistener.com/opinion/1862554/', '1862554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the present record, we find that the Circuit Court was within its discretionary authority[2] in the premises.', 'general', 'Goforth v. City of Ridgeland', 'https://www.courtlistener.com/opinion/1862805/', '1862805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the use of a peremptory challenge to correct a trial court error is adequate *767 grounds for reversal because it arbitrarily deprives the defendant of a statutorily granted right.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Gesch,[15] this court held that a defendant does not waive the right to challenge a conviction on the ground of an unfair trial if the defendant does not use a peremptory challenge to remove a juror whom the circuit court should have removed for cause.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8]  This court held similarly in Kohler v.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, we conclude that the defendant was not prejudiced by any alleged deficient performance of trial counsel.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the standards above, we conclude that prospective juror D.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the case produces some systemic problems that require correction.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Ramos case should be overruled because our good intentions did not produce good results.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Nathaniel Lindell was not prejudiced.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the automatic reversal rule of Ramos is not the appropriate rule.', 'general', 'State v. Lindell', 'https://www.courtlistener.com/opinion/1863727/', '1863727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the facts of this case, we conclude that the State induced Heitman to commit the crime.', 'general', 'State v. Heitman', 'https://www.courtlistener.com/opinion/1863832/', '1863832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Heitman', 'https://www.courtlistener.com/opinion/1863832/', '1863832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03, but we find that there was not sufficient evidence to support a finding that Jeffrey violated § 28-311.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State failed to adduce sufficient evidence to support a finding that Jeffrey violated § 28-311.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we find that the State adduced insufficient evidence to support the adjudication, and we reverse the decision of the juvenile court.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although Jeffrey''s actions in this case cannot be condoned or approved of, on our de novo review, we find the evidence insufficient to support the adjudication, and we reverse the decision of the juvenile court.', 'general', 'State v. Jeffrey K.', 'https://www.courtlistener.com/opinion/1868605/', '1868605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the trial court did not abuse its discretion because the evidence of defendant’s uncharged misconduct was relevant to show the defendant’s intent to inflict injury upon the victim and demonstrate an absence of mistake or accident.', 'general', 'State v. Mabry', 'https://www.courtlistener.com/opinion/1869047/', '1869047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse in part and affirmed in part.', 'general', 'State v. Mabry', 'https://www.courtlistener.com/opinion/1869047/', '1869047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4] We conclude that § 1202 is ambiguous in the critical respect.', 'general', 'United States v. Bass', 'https://www.courtlistener.com/opinion/108421/', '108421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that Congress has not "plainly and unmistakably," United States v.', 'general', 'United States v. Bass', 'https://www.courtlistener.com/opinion/108421/', '108421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in commerce or affecting commerce," for we conclude that the Government meets its burden here if it demonstrates that the firearm received has previously traveled in interstate commerce.', 'general', 'United States v. Bass', 'https://www.courtlistener.com/opinion/108421/', '108421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] We affirm the judgment of the court below, *339 but for substantially different reasons.', 'general', 'United States v. Bass', 'https://www.courtlistener.com/opinion/108421/', '108421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that the terroristic threatening statute is not impermissibly vague when “repeated” is accorded its ordinary meaning, we nonetheless recognize that applying the literal definition of the word may create problems in certain unusual circumstances in which a question might arise as to whether a single statement contains more than one threat.', 'general', 'Konrad v. State', 'https://www.courtlistener.com/opinion/1281721/', '1281721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that a bare foot could qualify as a dangerous instrument under certain circumstances.', 'general', 'Konrad v. State', 'https://www.courtlistener.com/opinion/1281721/', '1281721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that, while any object, including an unshod foot, that was capable of inflicting serious physical injury might qualify under the broad statutory definition of “dangerous instrument,” the actual determination of whether a dangerous instrument was used must be made on a case-by-case basis, based on the totality of the circumstances surrounding the actual use of the object in question.', 'general', 'Konrad v. State', 'https://www.courtlistener.com/opinion/1281721/', '1281721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the lack of an appropriate clarifying instruction and the ambiguity of the instruction actually given, we conclude that the trial court erred in denying Konrad’s pretrial motion to dismiss the count charging him with assault in the third degree.', 'dismissal', 'Konrad v. State', 'https://www.courtlistener.com/opinion/1281721/', '1281721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this standard to the present case, we conclude that insufficient evidence was adduced to support Konrad’s conviction of third-degree assault.', 'general', 'Konrad v. State', 'https://www.courtlistener.com/opinion/1281721/', '1281721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in denying Konrad’s motion for a judgment of acquittal as to the charge of assault in the third degree.', 'general', 'Konrad v. State', 'https://www.courtlistener.com/opinion/1281721/', '1281721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that sufficient evidence had been presented at trial to allow a finding that Wettanen’s foot was a dangerous instrument, even if it was unshod.', 'general', 'Konrad v. State', 'https://www.courtlistener.com/opinion/1281721/', '1281721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the evidence in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Konrad’s convictions for second-degree assault and terroristic threatening, but vacate his conviction for third-degree, assault.', 'general', 'Konrad v. State', 'https://www.courtlistener.com/opinion/1281721/', '1281721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we hold that (1) the local governments had the power to enact the ordinances, and (2) the ordinances are not inconsistent with either the Constitution or general law of this State.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although § 5-7-30 lists various specific powers possessed by municipalities, we hold that the broad grant of power stated at the beginning of the statute is not limited by the specifics mentioned in the remainder of the statute.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 5-7-30, especially when read in light of Article VIII''s mandatory liberal rule of construction, authorized the Town of Hilton Head to enact an ordinance promoting the general health, safety, and welfare of the Town''s residents and visitors by raising funds to improve, maintain, nourish and re-nourish the Town''s beaches.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the defendants had the power to enact the ordinances at issue, and the ordinances are not inconsistent with the Constitution or general law of this State, we hold that the ordinances are valid.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the classification under each ordinance bears a reasonable relation to the legislative purpose to be effected.', 'general', 'Hospitality Ass''n of South Carolina, Inc. v. County of Charleston', 'https://www.courtlistener.com/opinion/1282143/', '1282143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a person who contributes money with the intent of bringing about the purchase of alcohol beverages for consump
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the additional affirmative act requirement has superficial appeal, we conclude that it is not a workable requirement.', 'general', 'Miller v. Thomack', 'https://www.courtlistener.com/opinion/1877624/', '1877624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the parent in the defendants'' hypothetical does not come within the statutory definition of procure because we interpret the word procure as requiring, when contributing funds, the intent of bringing about the purchase of alcohol beverages for consumption by an underage person.', 'general', 'Miller v. Thomack', 'https://www.courtlistener.com/opinion/1877624/', '1877624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a person who contributes money with the intent of bringing about the purchase of alcohol beverages for consumption by an underage person whom the person knows, or should know, is under the legal drinking age, procures alcohol beverages for the underage person under the statutes.', 'general', 'Miller v. Thomack', 'https://www.courtlistener.com/opinion/1877624/', '1877624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the defendants'' actions constitute procuring we need not address this argument.', 'general', 'Miller v. Thomack', 'https://www.courtlistener.com/opinion/1877624/', '1877624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion, and we affirm.', 'general', 'City of Grand Forks v. Dohman', 'https://www.courtlistener.com/opinion/1839943/', '1839943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record supports and justifies the judge’s order of contempt and punitive sanction.', 'general', 'City of Grand Forks v. Dohman', 'https://www.courtlistener.com/opinion/1839943/', '1839943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s order.', 'general', 'City of Grand Forks v. Dohman', 'https://www.courtlistener.com/opinion/1839943/', '1839943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that Griller is not entitled to a new trial because of the erroneous defense-of-dwelling instruction.', 'general', 'State v. Griller', 'https://www.courtlistener.com/opinion/1881458/', '1881458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we hold that the district court did not abuse its discretion by admitting the contested evidence or by departing upward from the presumptive sentence.', 'sentencing', 'State v. Griller', 'https://www.courtlistener.com/opinion/1881458/', '1881458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that an instruction almost identical to that given at Griller’s trial “materially misstated the law” because it required the defendant to show fear of great bodily harm or death, even though the statutory defense requires no such showing for defense-of-dwelling.', 'general', 'State v. Griller', 'https://www.courtlistener.com/opinion/1881458/', '1881458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Griller was entitled to a defense-of-dwelling instruction.', 'general', 'State v. Griller', 'https://www.courtlistener.com/opinion/1881458/', '1881458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration, we conclude that this is one of those very rare cases where the fairness and integrity of judicial proceedings would be adversely affected if we granted Griller a new trial.', 'general', 'State v. Griller', 'https://www.courtlistener.com/opinion/1881458/', '1881458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, here, we conclude that it would be a miscarriage of justice to grant Griller a new trial.', 'general', 'State v. Griller', 'https://www.courtlistener.com/opinion/1881458/', '1881458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have conducted a thorough review of the record, and viewing the trial as a whole, we conclude that the district court did not abuse its discretion by admitting the contested evidence.', 'general', 'State v. Griller', 'https://www.courtlistener.com/opinion/1881458/', '1881458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the district court did not abuse its discretion in departing upward from the presumptive sentence.', 'sentencing', 'State v. Griller', 'https://www.courtlistener.com/opinion/1881458/', '1881458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'McCullough v. United States', 'https://www.courtlistener.com/opinion/1884723/', '1884723') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained here, we conclude that the Andersons'' conduct falls within the definition of first-degree hindering prose-ecution, and we further conclude that the police entry into the Andersons'' home, and the ensuing search of the Andersons'' bedroom, were constitutional.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2624200/', '2624200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained here, we conclude that the answer is "yes".', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2624200/', '2624200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the first-degree hindering prosecution statute, AS 11.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2624200/', '2624200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the troopers'' authority to enter the house under the authority of the arrest warrant is not affected by the fact that Daniel shared this residence with his parents.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2624200/', '2624200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the facts in the light most favorable to the superior court''s ruling, we conclude that the troopers had probable cause to believe that Daniel was inside the house.', 'probable_cause', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2624200/', '2624200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this is the proper rule.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2624200/', '2624200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that neither the Fourth Amendment nor Article I, Section 14 of the Alaska Constitution required the troopers to obtain a separate warrant to enter the bedroom of Lars and Lana Anderson.', 'search_seizure', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2624200/', '2624200') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the court, by not instructing the jury on this element of the kidnap statute, failed to meet this duty and allowed the jury to engage in assumptions or speculations as to the actual nature of the offense charge.', 'general', 'State v. McLaren', 'https://www.courtlistener.com/opinion/1907792/', '1907792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'opinion, we conclude that the officer did have a reasonable, articulable suspicion
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'reasons, we conclude that it does not.', 'general', 'State of Maine v. John E. Sasso', 'https://www.courtlistener.com/opinion/3217652/', '3217652') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the Stylette indictment fails to sufficiently allege the elements of second-degree burglary pursuant to § 16-11-312(A) or (B), and only alleges the elements of third-degree burglary.', 'general', 'Koon v. State', 'https://www.courtlistener.com/opinion/1265852/', '1265852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the denial of relief in part, but vacate one of petitioner’s convictions because we find that the trial court lacked subject
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the three indictments petitioner questions sufficiently set forth the elements of second-degree burglary under § 16-11~312(B), despite the fact that the indictments initially refer to the “buildings” as “dwellings.', 'general', 'Koon v. State', 'https://www.courtlistener.com/opinion/1265852/', '1265852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that there was a substantial basis for the trial court’s decision, and so affirm the judgment.', 'general', 'State v. Peirce', 'https://www.courtlistener.com/opinion/1267426/', '1267426') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because the consent was based in part on misleading information, the consent implied by law was not voluntary and the test results were inadmissible.', 'general', 'State v. Peirce', 'https://www.courtlistener.com/opinion/1267426/', '1267426') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the misleading information was relevant to the suspect’s decision whether to agree to the state-administered test.', 'general', 'State v. Peirce', 'https://www.courtlistener.com/opinion/1267426/', '1267426') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reversed the denial of a motion in limine where the officer informed the suspect that his failure to submit to a state-administered breath test would result in the suspension of his driver’s license, even though the suspect had a Tennessee driver’s license.', 'general', 'State v. Peirce', 'https://www.courtlistener.com/opinion/1267426/', '1267426') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1280, 1283 (1987), we held that Rule 41(c)''s standard for issuing warrants based on hearsay adopts the two-pronged test of Aguilar v.', 'general', 'State v. Bruyette', 'https://www.courtlistener.com/opinion/1481573/', '1481573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was highly probative on the identity issue, and that the relevance standard was satisfied.', 'general', 'State v. Bruyette', 'https://www.courtlistener.com/opinion/1481573/', '1481573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ostergard, supra, and with the special concurring opinion of Judge Barkdull, and we hold that absent allegations of multi-county activity on the face of the indictments, the Statewide Grand Jury was without authority to properly indict appellant.', 'general', 'McNamara v. State', 'https://www.courtlistener.com/opinion/1095808/', '1095808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State of Ohio, we conclude that under the facts of the present case, the police officer had a reasonable ground under the circumstances of his encounter with the defendant to believe the defendant to be armed and dangerous and made a reasonably limited search for the purpose of neutralizing such danger.', 'general', 'McNamara v. State', 'https://www.courtlistener.com/opinion/1095808/', '1095808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we find that petitioner was properly permitted to plead nolo contendere conditioned on reservation of the questions as to legality of the seizure of evidence to be used against him.', 'plea', 'McNamara v. State', 'https://www.courtlistener.com/opinion/1095808/', '1095808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that under the circumstances present in the instant cause, the officers had probable cause sufficient to justify the frisking of appellant for their own safety.', 'probable_cause', 'McNamara v. State', 'https://www.courtlistener.com/opinion/1095808/', '1095808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court properly denied the motion to suppress the pistol.', 'suppression', 'McNamara v. State', 'https://www.courtlistener.com/opinion/1095808/', '1095808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial court''s denial of the motion to suppress the pistol.', 'suppression', 'McNamara v. State', 'https://www.courtlistener.com/opinion/1095808/', '1095808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that absent the proper jurisdictional allegations on the face of the indictments, the Second Statewide Grand Jury was without authority to properly indict appellees and dismissal was proper.', 'dismissal', 'McNamara v. State', 'https://www.courtlistener.com/opinion/1095808/', '1095808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, in light of the foregoing holding, subsections 827.', 'general', 'Schmitt v. State', 'https://www.courtlistener.com/opinion/1099410/', '1099410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '071(5) are constitutional, since we find that these provisions are constitutional as we have construed them above.', 'general', 'Schmitt v. State', 'https://www.courtlistener.com/opinion/1099410/', '1099410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Otherwise, we affirm the judgments and sentences.', 'sentencing', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1100061/', '1100061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that as a matter of law, the CCP aggravator cannot be sustained on these facts.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that the trial court abused its discretion in refusing to consider Mahn''s age as a statutory mitigator because, unlike the defendant in Sims, there was much "more" than Mahn''s chronological age to be considered and which should have compelled the trial court to link those factors to his age or maturity as mitigation.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury''s recommendation of life for the murder of Debra Shanko was not so unreasonable as to permit the trial court to override the jury''s recommendation.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a robbery was not proven beyond a reasonable doubt.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we find that a reasonable hypothesis exists that Mahn did not intend to steal Debra''s money prior to the murders.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court erred in submitting the armed robbery charge to the jury.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court abused its discretion in finding the CCP aggravator applied to these killings.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court abused its discretion in rejecting Mahn''s age as a statutory mitigating circumstance.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the trial court erred in failing to give Mahn''s extensive and uncontroverted history of drug and alcohol abuse appropriate weight as a nonstatutory mitigating circumstance.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the trial court did not abuse its discretion in rejecting this aggravator.', 'general', 'Mahn v. State', 'https://www.courtlistener.com/opinion/1102289/', '1102289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'McKenzie v. State', 'https://www.courtlistener.com/opinion/1103048/', '1103048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the trial court in the present case is without jurisdiction to proceed in either the dissolution or the injunction actions to the extent discussed in this decision.', 'general', 'Tobkin v. State', 'https://www.courtlistener.com/opinion/1102732/', '1102732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the legislature has made a petition for injunction against domestic violence a private action, we conclude that this type of case may be voluntarily dismissed by the petitioner just like a dissolution, or any other civil action.', 'dismissal', 'Tobkin v. State', 'https://www.courtlistener.com/opinion/1102732/', '1102732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In essence, we hold that the misdemeanor-manslaughter doctrine was encom
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 897, 906 (Alaska 1970), we held that a killing done in the perpetration of a felony, but without a specific intent or purpose to kill, constitutes manslaughter.', 'general', 'Keith v. State', 'https://www.courtlistener.com/opinion/1270085/', '1270085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that there was no material misrepresentation to the grand jury.', 'general', 'Keith v. State', 'https://www.courtlistener.com/opinion/1270085/', '1270085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the jury instruction was a correct statement of the law.', 'jury_instruction', 'Keith v. State', 'https://www.courtlistener.com/opinion/1270085/', '1270085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the giving of a jury instruction of this kind, drawing attention to possible prejudicial inad
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that a reasonable construction of former AS 11.', 'general', 'Keith v. State', 'https://www.courtlistener.com/opinion/1270085/', '1270085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given our holding regarding the proper construction of the careless use of firearms statute, we conclude that this specification of error is without merit.', 'general', 'Keith v. State', 'https://www.courtlistener.com/opinion/1270085/', '1270085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Trooper Sumey’s inaccurate reportage of the time of the swab test was not significant to this determination.', 'general', 'Keith v. State', 'https://www.courtlistener.com/opinion/1270085/', '1270085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we find that after viewing all the evidence in the light most favorable to the prosecution, any rational trier of fact could have found defendant guilty beyond a reasonable doubt.', 'general', 'People v. Collins', 'https://www.courtlistener.com/opinion/2097058/', '2097058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with these principles, we find that the naming of Officers Svec and Dowling was surplusage and did not affect the validity of the complaints.', 'general', 'People v. Collins', 'https://www.courtlistener.com/opinion/2097058/', '2097058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court.', 'general', 'People v. Collins', 'https://www.courtlistener.com/opinion/2097058/', '2097058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed, we reverse the judgment of the appellate court and remand the matter to the appellate court for consideration of the remaining issues on appeal.', 'general', 'People v. Collins', 'https://www.courtlistener.com/opinion/2097058/', '2097058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that section 796.', 'general', 'Warren v. State', 'https://www.courtlistener.com/opinion/1117020/', '1117020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d DCA 1983), this court held that a BB gun was a deadly weapon when used in a robbery.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d DCA 1987), where there was no factual dispute about the characteristics of the knife, this court held that a jury could decide whether a four-inch pocketknife was or was not a concealed weapon.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
