INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, as a matter of law, no deadly weapon was used in the robbery because the defendant never threatened to use the nut driver as a bludgeon and he could not use it as a gun.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the defendant''s claim was sufficient to support the conviction.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With some hesitation, we conclude that the evidence also establishes trespass with a dangerous weapon, robbery with a deadly weapon, and aggravated assault *557 with a deadly weapon.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When a defendant''s words or actions imply that a device is dangerous or deadly, and the device is normally dangerous or deadly when used in its ordinary and usual manner, but at the time of the offense it is not dangerous or deadly due to a condition that cannot be observed by the victim, we conclude that a jury may find the device to be a dangerous or deadly weapon.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the reasoning in Depasquale, and influenced by the treatment of verbal threats in both Shelby and Butler, we conclude that this evidence is sufficient to support these convictions.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court in all respects.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the four simple assault convictions without discussion.', 'general', 'Mitchell v. State', 'https://www.courtlistener.com/opinion/1135832/', '1135832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the facts alleged there is no liability on the part of either party for false imprisonment.', 'general', 'Andrews v. Florida Parole Com''n', 'https://www.courtlistener.com/opinion/1139964/', '1139964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Commission was acting within the scope of its quasi-judicial duties when it placed Andrews on conditional release.', 'general', 'Andrews v. Florida Parole Com''n', 'https://www.courtlistener.com/opinion/1139964/', '1139964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1st DCA 1994), we held that under the provisions of section 947.', 'general', 'Andrews v. Florida Parole Com''n', 'https://www.courtlistener.com/opinion/1139964/', '1139964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999) ("This Court held in Cooper and further clarified in Pressley [v.', 'general', 'Andrews v. Florida Parole Com''n', 'https://www.courtlistener.com/opinion/1139964/', '1139964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the actions of the Commission were quasi-judicial in nature and entitled to protection under the doctrine of judicial immunity.', 'general', 'Andrews v. Florida Parole Com''n', 'https://www.courtlistener.com/opinion/1139964/', '1139964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Commission functions in a quasi-judicial capacity in carrying out its duties under the statute.', 'general', 'Andrews v. Florida Parole Com''n', 'https://www.courtlistener.com/opinion/1139964/', '1139964') ON CONFLICT DO NOTHING;
