INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the jury instructions as a whole, we conclude that the jury was adequately informed of the applicable law.', 'jury_instruction', 'State v. Woehlhoff', 'https://www.courtlistener.com/opinion/1911207/', '1911207') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the deputy’s personal knowledge gained from his prior experiences involving the defendant and the deputy’s observations at the crime scene and outside of Woehlhoffs residence provided the magistrate with a substantial basis to find probable cause to search Woehlhoffs premises.', 'probable_cause', 'State v. Woehlhoff', 'https://www.courtlistener.com/opinion/1911207/', '1911207') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction.', 'general', 'State v. Woehlhoff', 'https://www.courtlistener.com/opinion/1911207/', '1911207') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that a sentence imposed under § 13-2503 must run consecutively to the original sentence or sentences for which the defendant was confined when he escaped, if in fact he was so confined pursuant to such sentence or sentences;', 'sentencing', 'State v. Pena', 'https://www.courtlistener.com/opinion/1159734/', '1159734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 11, 13 (1998), we held that prior domestic assaults may be properly admitted to give context to a domestic violence charge because “[a]llegations of a single act of domestic violence, taken out of its situational context, are likely to seem incongruous and incredible to a jury.', 'general', 'State v. Hendricks', 'https://www.courtlistener.com/opinion/2320755/', '2320755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm with respect to all claims except the last which is moot.', 'general', 'State v. Hendricks', 'https://www.courtlistener.com/opinion/2320755/', '2320755') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lynn Thomas, Solicitor General for the office of the Attorney General,[1] met the issue of fundamental error, discussed it, and urged upon the Court that we hold that beyond a reasonable doubt the error in placing upon the defendant the burden of establishing his innocence, per Mullaney v.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1177672/', '1177672') ON CONFLICT DO NOTHING;
