INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that "[t]he evidence was not prejudicial.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1177672/', '1177672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the action of the legislature in repealing I.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1177672/', '1177672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, we find that there was substantial and competent evidence to support the jury''s conclusion that the defendant was guilty of voluntary manslaughter.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1177672/', '1177672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Based on the above statutes, we find that in Idaho the crime of voluntary manslaughter consists of three elements which must be proved by the State: (1) the killing of a human being;', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1177672/', '1177672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Juneby’s sentence must be vacated and that this case must be remanded for resentencing.', 'sentencing', 'Juneby v. State', 'https://www.courtlistener.com/opinion/1222995/', '1222995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Juneby’s sentence was not imposed in accordance with the requirements of these sections;', 'sentencing', 'Juneby v. State', 'https://www.courtlistener.com/opinion/1222995/', '1222995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that Juneby’s unlawful entry of V.', 'general', 'Juneby v. State', 'https://www.courtlistener.com/opinion/1222995/', '1222995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that subsection (f)’s requirement that findings “be set out with specificity” calls for sentencing judges to include, in their remarks on the record, the following specific information: (1) the specific factors in aggravation and in mitigation found to have been established by clear and convincing evidence;', 'sentencing', 'Juneby v. State', 'https://www.courtlistener.com/opinion/1222995/', '1222995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The comments by the prosecutor in the instant case fall squarely within the principle established by the Seyle case, and we hold that such comments did not constitute error.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, "where the wife of a defendant in a criminal case, like that now before us, might be a material witness, and she is not placed on the stand by the defendant, it is permissible for the State in argument to infer that the absent testimony would have been both material and damaging.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 379, we held that, pursuant to § 7-1-112(c) (now § 7-6-106(c)), the district court could not order reimbursement without first determining the defendant''s ability to pay.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, since the fact and evidence of Jeff''s confession came to appellant''s knowledge after the trial, we conclude that appellant satisfied the first Opie factor, and the denial of his motion for a new trial cannot be sustained on that basis.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor''s conduct in cross-examination, while improper, did not deny appellant a fair trial.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not err in admitting into evidence the preliminary hearing testimony of Patricia Koryn.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not need to reach appellant''s constitutional claim, however, because we conclude that the district court erred in ordering this reimbursement without first determining appellant''s ability to pay as required by § 7-6-106 and Keller v.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the district court failed to consider appellant''s ability to pay in ordering reimbursement of defense expenses, we reverse that aspect of the judgment and sentence.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm but modify the judgment and sentence with respect to costs.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this Court reversed Steve''s conviction on the basis of ineffective assistance of counsel, as emanating from the failure of counsel to investigate the nature and availability of Roger''s testimony, we affirmed, in a divided decision, the trial court''s denial of a new trial on the basis of newly discovered evidence.', 'ineffective_assistance', 'King v. State', 'https://www.courtlistener.com/opinion/1190856/', '1190856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the incorrect designation of the highway number on the jury instruction was harmless and that the evidence was sufficient to support the jury’s verdict.', 'jury_instruction', 'State v. Hanson', 'https://www.courtlistener.com/opinion/1194824/', '1194824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither the mistake in identifying the applicable state highway in a jury instruction nor the alleged variance between a jury instruction and the charging instrument amounted to reversible error.', 'jury_instruction', 'State v. Hanson', 'https://www.courtlistener.com/opinion/1194824/', '1194824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm.', 'general', 'State v. Hanson', 'https://www.courtlistener.com/opinion/1194824/', '1194824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that, where a governmental agent is engaged in a lawful intrusion and inadvertently observes evidence of a crime, the seizure of such evidence does not require any further constitutional protection.', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not err in denying Jenkins''s motion to suppress evidence.', 'suppression', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in failing to instruct the jury regarding all of the material elements of the offense.', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we hold that, for the purposes of HRS § 134-7(b), "possession" must be analyzed employing a two-pronged analysis: (1) the voluntary act of "possession" of an object itself is, by way of HRS § 702-202, satisfied where an individual acts knowingly with respect to his or her conduct;', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, we hold that, for the purposes of HRS § 134-6(e), "carry" must be analyzed employing a two-pronged analysis: *39 (1) the voluntary act of "carrying" an object is, by way of HRS § 702-202, established when an individual acts knowingly with respect to that conduct;', 'general', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Jenkins''s sentence did not violate the eighth amendment to the United States Constitution or article I, section 12 of the Hawai`i Constitution.', 'sentencing', 'State v. Jenkins', 'https://www.courtlistener.com/opinion/1195377/', '1195377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accord with this statutory language and the statutory scheme developed by the legislature, we hold that defendant has sufficiently shown that he is in immediate danger of being subjected to the permissive inference of section 4–103.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above-stated reasons, we hold that section 4–103.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the trial court improperly sustained defendant’s facial challenge of section 1–191 of the Code on vagueness grounds.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the defendant in 
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm in part and reverse in part the judgment of the circuit court, and hold that section 4–103.', 'general', 'People v. Greco', 'https://www.courtlistener.com/opinion/3135023/', '3135023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Superior Court judge was well within the bounds of the court’s inherent authority to manage the case docket when he struck the defendants’ answer.', 'general', 'Lomax v. Shaw', 'https://www.courtlistener.com/opinion/1202304/', '1202304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the imposition of sanctions was proper.', 'general', 'Lomax v. Shaw', 'https://www.courtlistener.com/opinion/1202304/', '1202304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rejecting both arguments, we affirm.', 'general', 'Couture v. Commonwealth', 'https://www.courtlistener.com/opinion/1208666/', '1208666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in the trial court’s response to the jury’s question and no insufficiency of evidence to support the verdict, we affirm Couture’s conviction for voluntary manslaughter.', 'general', 'Couture v. Commonwealth', 'https://www.courtlistener.com/opinion/1208666/', '1208666') ON CONFLICT DO NOTHING;
