INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing authority, we hold that Jones has not shown actual prejudice concerning the failure of his appellate counsel to raise the issue of whether he was entitled to be tried after Elam.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1229850/', '1229850') ON CONFLICT DO NOTHING;
