INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Jones has not carried his burden to show that Coleman’s testimony at his criminal trial was in fact perjured, we hold that Jones’ claim that the prosecution “knew or should have known" of Coleman’s alleged perjury likewise must fail.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1229850/', '1229850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that Jones is not entitled to a second postconviction hearing due to his claimed incompetency at the time of his original hearing.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1229850/', '1229850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the record as it existed at the time of the postconviction hearing, we conclude that the postconviction court did not err in failing to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that Iowa Code chapter 812 is not applicable to postconviction relief proceedings under chapter 663A.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1229850/', '1229850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Jones has not demonstrated “sufficient reason” for having not raised, on direct appeal from his criminal trial, the issue of ineffective assistance of trial counsel.', 'ineffective_assistance', 'Jones v. State', 'https://www.courtlistener.com/opinion/1229850/', '1229850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that Jones has failed to demonstrate prejudice in appellate counsel’s decision not to raise the issue of ineffective assistance of trial counsel because an aider and abetter such as Jones does not have a right to be tried after a principal such as Elam.', 'ineffective_assistance', 'Jones v. State', 'https://www.courtlistener.com/opinion/1229850/', '1229850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This is because we conclude that an aider or abetter has no right to be tried subsequent to the trial of a named principal.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1229850/', '1229850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that such statements should not automatically be allowed to interfere with the finality of the underlying trial.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1229850/', '1229850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Superior Court properly rejected Fawcett’s hearsay objection, as the challenged statement was not offered for the truth of the matter asserted.', 'general', 'Fawcett v. State', 'https://www.courtlistener.com/opinion/2360981/', '2360981') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this standard in Katt, this Court held that a child’s disclosure of sexual abuse to a CPS worker, though inadmissible under MRE 803A because it was not the child’s first corroborative statement concerning the abuse, was nonetheless admissible under MRE 803(24).', 'general', 'People v. Douglas', 'https://www.courtlistener.com/opinion/2710048/', '2710048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court abused its discretion by admitting KD’s out-of-court statements to Wheeler regarding the alleged fellatio.', 'general', 'People v. Douglas', 'https://www.courtlistener.com/opinion/2710048/', '2710048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that KD’s erroneously admitted statements during the forensic interview more probably than not “tipped the scales” against *583the defendant such that the reliability of the verdict against him was undermined and a new trial is warranted.', 'general', 'People v. Douglas', 'https://www.courtlistener.com/opinion/2710048/', '2710048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the defendant is entitled to a new trial, but is not entitled to reinstatement of the prosecution’s plea offer.', 'plea', 'People v. Douglas', 'https://www.courtlistener.com/opinion/2710048/', '2710048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals on this point and hold that the defendant is not entitled to reinstatement of the prosecution’s plea offer.', 'plea', 'People v. Douglas', 'https://www.courtlistener.com/opinion/2710048/', '2710048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Court of Appeals in part, reverse in part, and remand for proceedings consistent with this opinion.', 'general', 'People v. Douglas', 'https://www.courtlistener.com/opinion/2710048/', '2710048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Appeals in part, reverse in part, and remand for proceedings consistent with this opinion.', 'general', 'People v. Douglas', 'https://www.courtlistener.com/opinion/2710048/', '2710048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because a preponderance of the evidence established that Hardy racked a shotgun to increase the fear of his victim by a considerable amount, the circuit court properly assessed 50 points for OV 7 by finding that Hardy’s conduct of racking a shotgun while pointing it at the victim constituted “conduct designed to substantially increase the fear and anxiety a victim suffered during the offense.', 'general', 'People v. Hardy; People v. Glenn', 'https://www.courtlistener.com/opinion/2712642/', '2712642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain meaning of the phrase “conduct designed to substantially increase the fear and anxiety a victim suffered during the offense” encompasses both defendant Hardy’s act of racking a shotgun during a carjacking and defendant Glenn’s violent behavior during an armed robbery.', 'general', 'People v. Hardy; People v. Glenn', 'https://www.courtlistener.com/opinion/2712642/', '2712642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”28 Applying these definitions to the relevant text, we conclude that it is proper to assess points under OV 7 for conduct that was intended to make a victim’s fear or anxiety greater by a considerable amount.', 'general', 'People v. Hardy; People v. Glenn', 'https://www.courtlistener.com/opinion/2712642/', '2712642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that a defendant’s conduct does not have to be “similarly egregious” to “sadism, torture, or excessive brutality” for OV 7 to be scored at 50 points, and that, absent an express statutory prohibition, courts may consider circumstances inherently present in the crime when scoring OV 7.', 'general', 'People v. Hardy; People v. Glenn', 'https://www.courtlistener.com/opinion/2712642/', '2712642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Glenn, we reverse the judgment of the Court of Appeals and remand the case to the circuit court for reinstatement of defendant Glenn’s July 22, 2010 judgment of sentence.', 'sentencing', 'People v. Hardy; People v. Glenn', 'https://www.courtlistener.com/opinion/2712642/', '2712642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Glenn, we reverse the Court of Appeals and remand the case to the circuit court for reinstatement of the judgment of sentence.', 'sentencing', 'People v. Hardy; People v. Glenn', 'https://www.courtlistener.com/opinion/2712642/', '2712642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s scoring decision in Hardy.', 'general', 'People v. Hardy; People v. Glenn', 'https://www.courtlistener.com/opinion/2712642/', '2712642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we affirm the circuit court’s assessment of 50 points for OV 7 in Hardy.', 'general', 'People v. Hardy; People v. Glenn', 'https://www.courtlistener.com/opinion/2712642/', '2712642') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*308Based on the foregoing, we hold that Appellant has not met his burden to prove that section 63-3-590 violates either the federal or state constitution.', 'general', 'In the Interest of Kevin R.', 'https://www.courtlistener.com/opinion/2714001/', '2714001') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, this Court held a juvenile does not have a constitutional right to a jury trial in adjudication proceedings.', 'general', 'In the Interest of Kevin R.', 'https://www.courtlistener.com/opinion/2714001/', '2714001') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, this Court held that neither the federal nor the state constitution requires a jury trial in juvenile adjudication proceedings.', 'general', 'In the Interest of Kevin R.', 'https://www.courtlistener.com/opinion/2714001/', '2714001') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the ruling of the family court.', 'general', 'In the Interest of Kevin R.', 'https://www.courtlistener.com/opinion/2714001/', '2714001') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the family court’s denial of Appellant’s motion for a jury trial in his adjudication proceedings.', 'general', 'In the Interest of Kevin R.', 'https://www.courtlistener.com/opinion/2714001/', '2714001') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*450 We hold that the complaint in the case was defective because it did not charge and describe an offense, and that prosecution under the complaint was a violation of Lopez''[s] due process rights under Art.', 'general', 'Crane Creek Country Club v. City of Boise', 'https://www.courtlistener.com/opinion/1249684/', '1249684') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*448 We conclude that the Boise City Council''s proposed annexation was not without or in excess of the City Council''s jurisdiction.', 'general', 'Crane Creek Country Club v. City of Boise', 'https://www.courtlistener.com/opinion/1249684/', '1249684') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it was.', 'general', 'State v. Godwin', 'https://www.courtlistener.com/opinion/1249743/', '1249743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the principle quoted is applicable to our statutory requirement that the detention be carried out in a "reasonable manner.', 'general', 'Gortarez v. Smitty''s Super Valu, Inc.', 'https://www.courtlistener.com/opinion/1251856/', '1251856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court erred in its findings with respect to both the purpose and manner of detention.', 'general', 'Gortarez v. Smitty''s Super Valu, Inc.', 'https://www.courtlistener.com/opinion/1251856/', '1251856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such an action is not a "criminal prosecution" within the meaning of Article 1, Section 11 of the Alaska Constitution, which provides that "[i]n all criminal prosecutions, the accused shall have the right to .', 'general', 'Resek v. State', 'https://www.courtlistener.com/opinion/1284172/', '1284172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This issue is really one of legislative intent, and we conclude that the nature of the forfeiture penalty clearly indicates that it was *292 intended as a civil, not a criminal, sanction.', 'general', 'Resek v. State', 'https://www.courtlistener.com/opinion/1284172/', '1284172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the forfeiture action at issue here is a civil proceeding and not a "criminal prosecution" within the meaning of Article 1, Section 11 of the state constitution.', 'general', 'Resek v. State', 'https://www.courtlistener.com/opinion/1284172/', '1284172') ON CONFLICT DO NOTHING;
