INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court properly reversed the trial court''s order granting a directed verdict on punitive damages for Winn-Dixie Stores, Inc.', 'general', 'Winn-Dixie Stores, Inc. v. Robinson', 'https://www.courtlistener.com/opinion/1946630/', '1946630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Quashing the decision of the district court which had reversed the trial court''s order, we held that it is proper for the trial court to issue an order for new trial or remittitur when the manifest weight of the evidence shows that the amount of punitive damages assessed is out of all reasonable proportion to the malice, outrage, or wantonness of the tortious conduct.', 'general', 'Winn-Dixie Stores, Inc. v. Robinson', 'https://www.courtlistener.com/opinion/1946630/', '1946630') ON CONFLICT DO NOTHING;
