INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we disagree with the court of appeals'' rationale, we affirm in result.', 'general', 'State v. Brannon', 'https://www.courtlistener.com/opinion/1346868/', '1346868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the result reached by the court of appeals and find the circuit court erred in denying Brannon''s motion for a directed verdict on the charge of resisting arrest.', 'general', 'State v. Brannon', 'https://www.courtlistener.com/opinion/1346868/', '1346868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant has not met his burden under the plain error rule.', 'general', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the inclusion of the phrase "lack of provocation" in the instruction on premeditation and deliberation did not confuse the jury, reflect an opinion of the trial court, or impermissibly shift the burden of proof to defendant.', 'general', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial judge did not err when he gave peremptory instructions pursuant only to defendant''s specific request.', 'general', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that based on the evidence of defendant''s continuous involvement in violent criminal activities, similar to that for which he was sentenced in this case, no rational juror could have found that defendant had "no significant history of prior criminal activity.', 'sentencing', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Determining that the crimes occurred within moments of each other at the same location and that the same modus operandi was used in each killing, we hold that the facts clearly establish that the two crimes were committed as a part of a course of conduct in which defendant engaged and which included the commission by defendant of a crime of violence against another person.', 'general', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, based upon our review of the cases in the *288 pool and the experienced judgment of members of this Court, we hold that the sentence of death in this case is not disproportionate and decline to set aside the death penalty imposed.', 'sentencing', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brogden, we held that further questioning should have been allowed because the juror may have answered the crucial question about whether his views would substantially prevent or impair his duties as a juror differently if rehabilitation had been allowed.', 'general', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 418, we held that the question, "Would the fact that the defendant had no significant history of any criminal record, would that be something that you would consider important in determining whether or not to impose the death penalty?" was impermissible.', 'general', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brogden, this Court held that when a judge denies a defendant the opportunity to rehabilitate under the mistaken impression that defendant is not permitted to rehabilitate a juror, then the decision of the trial court is reviewable and is not considered under an abuse of discretion standard.', 'general', 'State v. Skipper', 'https://www.courtlistener.com/opinion/1347654/', '1347654') ON CONFLICT DO NOTHING;
