INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that, the trial court erred in admitting the evidence seized in violation of Aslinger''s Fourth Amendment rights and in imposing consecutive HSO sentence enhancements;', 'sentencing', 'Johnathon R. Aslinger v. State of Indiana', 'https://www.courtlistener.com/opinion/2725754/', '2725754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that Aslinger''s aggregate sentence of thirty-seven years, which is less than the maximum sentence authorized for dealing methamphetamine as a third substance offense, is not inappropriate in light of the nature of the offense and character of the offender.', 'sentencing', 'Johnathon R. Aslinger v. State of Indiana', 'https://www.courtlistener.com/opinion/2725754/', '2725754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'Johnathon R. Aslinger v. State of Indiana', 'https://www.courtlistener.com/opinion/2725754/', '2725754') ON CONFLICT DO NOTHING;
