INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the State concedes that Oster’s convictions may not both stand, we conclude that Oster’s other claims are without merit.', 'general', 'Thomas W. Oster, II v. State of Indiana', 'https://www.courtlistener.com/opinion/2726631/', '2726631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State produced sufficient evidence to prove that Oster broke and entered Large Ink with the intent to commit theft within.', 'general', 'Thomas W. Oster, II v. State of Indiana', 'https://www.courtlistener.com/opinion/2726631/', '2726631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s failure to instruct the jury on mens rea did not amount to fundamental error in this case.', 'general', 'Thomas W. Oster, II v. State of Indiana', 'https://www.courtlistener.com/opinion/2726631/', '2726631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State produced sufficient evidence to sustain Oster’s Class C felony burglary conviction and the finding that he is a habitual offender.', 'general', 'Thomas W. Oster, II v. State of Indiana', 'https://www.courtlistener.com/opinion/2726631/', '2726631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm in part, reverse in part, and remand with instructions.', 'general', 'Thomas W. Oster, II v. State of Indiana', 'https://www.courtlistener.com/opinion/2726631/', '2726631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction unless no reasonable fact-finder could find that the elements of the crime were proven beyond a reasonable doubt.', 'general', 'Thomas W. Oster, II v. State of Indiana', 'https://www.courtlistener.com/opinion/2726631/', '2726631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the foregoing, we conclude that the State failed to meet its burden of producing substantial evidence that the defendant possessed more than one-half ounce of marijuana on 6 September 1989.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1378015/', '1378015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the State did not produce sufficient evidence that defendant''s vehicle was "used for keeping or selling" a controlled substance.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1378015/', '1378015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the remaining issues presented, we conclude that discretionary review was improvidently granted.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1378015/', '1378015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this evidence is insufficient to establish that defendant''s vehicle was "used for the keeping or selling of" a controlled substance.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/1378015/', '1378015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d DCA 1979), we held that such denials will bar subsequent review if the order indicates that the denial is with prejudice or if it otherwise evinces an unequivocal determination by this court that the merits were considered.', 'general', 'Netherly v. State', 'https://www.courtlistener.com/opinion/1738217/', '1738217') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Mr.', 'general', 'Netherly v. State', 'https://www.courtlistener.com/opinion/1738217/', '1738217') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that our kidnaping statute, W.', 'general', 'State v. Haught', 'https://www.courtlistener.com/opinion/1386571/', '1386571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration of this matter, we affirm Appellant''s convictions.', 'general', 'State v. Haught', 'https://www.courtlistener.com/opinion/1386571/', '1386571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, finding no constitutional error in Appellant''s sentence, we affirm.', 'sentencing', 'State v. Haught', 'https://www.courtlistener.com/opinion/1386571/', '1386571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we affirm Appellant''s March 12, 2004, conviction for kidnaping and domestic battery.', 'general', 'State v. Haught', 'https://www.courtlistener.com/opinion/1386571/', '1386571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the sentence the trial court imposed on Price was illegal.', 'sentencing', 'State v. Price', 'https://www.courtlistener.com/opinion/1387784/', '1387784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 856 (1976), this Court held convictions for both armed robbery and unlawful possession of a pistol did not violate the Double Jeopardy Clause because proof of armed robbery only required possession of a weapon, regardless of whether such possession was lawful or not.', 'general', 'Hope v. State', 'https://www.courtlistener.com/opinion/1388669/', '1388669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the PCR judge’s denial of relief as to Hope’s conviction for assault to commit first degree CSC.', 'general', 'Hope v. State', 'https://www.courtlistener.com/opinion/1388669/', '1388669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we reverse the PCR judge’s grant of relief as to Hope’s conviction for first degree burglary.', 'general', 'Hope v. State', 'https://www.courtlistener.com/opinion/1388669/', '1388669') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that a defendant is guilty of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that evidence of the attempted murder was duly
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Conceptually, however, we conclude that the testimony regarded two distinct prior
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Conversely, we conclude that the trial court abused its discretion by admitting Bullard’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite that amendment, we conclude that the elements of the offense remain the same.', 'general', 'People v. Bass', 'https://www.courtlistener.com/opinion/4256219/', '4256219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Bass', 'https://www.courtlistener.com/opinion/4256219/', '4256219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the court''s imposition of four consecutive sentences was an abuse of discretion, in part because the "Board is in a far better position than a court to monitor a defendant''s subsequent behavior and possible progress toward rehabilitation while in prison and to adjust the maximum sentence accordingly.', 'sentencing', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ross, we held that "the fact finder must determine whether (1) subjectively, the defendant committed the [crime] while under the influence of extreme emotional distress, and (2) objectively, a reasonable person would have experienced an extreme emotional reaction and loss of self-control under the cireumstances.', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the district court improperly applied the sentencing provisions of section 76-5-302 of the Utah Code, we reverse Mr.', 'sentencing', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the court was so required, we then turn our attention to the proper meaning of "interests of justice" as used in subsection (4).', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, reading subsections (8) and (4) together, we conclude that the Legislature intended sentencing courts to consider the interests of justice when sentencing defendants under subsections (8)(a) or (3)(b), but not under subsection (8)(c).', 'sentencing', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'T 30 As an initial matter, we conclude that the Legislature did not intend the phrase "interests of justice" as a mere substitute for the weighing of aggravating and mitigating cireumstances recognized by the Sentencing
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Legislature replaced its previous aggravating-and-mitigating-cireumstances instruction with the new mandate to consider the interests of justice, we conclude that the district court''s analysis was in error,.', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '137 Keeping these basic principles in mind, we conclude that the Legislature''s use of the phrase "interests of justice" necessarily requires the court to consider the proportionality of the defendant''s sentence in relation to the severity of his offense.', 'sentencing', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the third Solem factor is inappropriate for an interests-of-justice analysis under section 76-5-302 of the Utah Code.', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though we agree that the Legislature''s use of the phrase "interests of justice" requires consideration of factors beyond the aggravating and mitigating circumstances of the crime, we conclude that the statute requires a more focused analysis than Mr.', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1241 (Utah 1980), we held that the information set forth in a presen-tence report may not be considered in sentencing unless it is provided to the defendant for the purpose of review and response.', 'sentencing', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In so doing, we held that such a sentence improperly deprived the parole board of the "flexibility" guaranteed it by statute and the constitution.', 'sentencing', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1297 (Utah 1993), we reversed the imposition of consecutive sentences of a minimum of fifteen years for child kidnapping and nine years for aggravated sexual assault for a defendant who was sixteen years old at the time of his offense.', 'sentencing', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 236 (Utah 1995), we reversed a decision imposing consecutive sentences amounting to "a minimum mandatory life sentence" because it would "deprive the Board of Pardons of discretion to take into account defendant''s future conduct and possible progress toward rehabilitation.', 'sentencing', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2735428/', '2735428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dawkins, this Court held that probationary terms, and mandatory CSP terms for sentences deriving from "no parole offenses," run concurrently.', 'sentencing', 'State v. PICKLESIMER', 'https://www.courtlistener.com/opinion/1394268/', '1394268') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. PICKLESIMER', 'https://www.courtlistener.com/opinion/1394268/', '1394268') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals and reinstate the original jury verdicts in favor of Bunch.', 'general', 'Lee v. Bunch', 'https://www.courtlistener.com/opinion/1406132/', '1406132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals and hold that the trial court properly allowed evidence of Lee’s pre-accident alcohol consumption.', 'general', 'Lee v. Bunch', 'https://www.courtlistener.com/opinion/1406132/', '1406132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we reverse the trial court and hold that the original defense verdicts in favor of Bunch on both the primary negligence claim and the loss of consortium claim are not inconsistent.', 'general', 'Lee v. Bunch', 'https://www.courtlistener.com/opinion/1406132/', '1406132') ON CONFLICT DO NOTHING;
