INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the stop of defendant''s vehicle was constitutional, we affirm the majority decision of the Court of Appeals that affirmed the trial court''s denial of defendant''s motion to suppress all evidence obtained as a result of the stop.', 'suppression', 'State v. Barnard', 'https://www.courtlistener.com/opinion/1407728/', '1407728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration of the record and briefs, we hold that defendant''s waiver of counsel was in accordance with the requirements set forth in N.', 'general', 'State v. Kinlock', 'https://www.courtlistener.com/opinion/1422146/', '1422146') ON CONFLICT DO NOTHING;
