INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 654 (1991), this Court held that a pretrial proceeding conducted by a judge different from the judge who presided over the trial satisfied the statutory requirement.', 'general', 'State v. Kinlock', 'https://www.courtlistener.com/opinion/1422146/', '1422146') ON CONFLICT DO NOTHING;
