INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having thoroughly reviewed this issue, we conclude that the lower court was correct in its ruling and accordingly, we affirm.', 'general', 'Pritt v. Suzuki Motor Co., Ltd.', 'https://www.courtlistener.com/opinion/1316456/', '1316456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the conviction could not stand because the information omitted an essential element of the offense and, therefore, the defendant had no opportunity to present any potential defense concerning the reason for the suspension.', 'general', 'State v. Longe', 'https://www.courtlistener.com/opinion/1435894/', '1435894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Williams, we reversed a § 674 conviction because the information stated that defendant operated a motor vehicle while his license was suspended in violation of § 674, but did not state the reason of the underlying suspension.', 'general', 'State v. Longe', 'https://www.courtlistener.com/opinion/1435894/', '1435894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the conviction.', 'general', 'State v. Longe', 'https://www.courtlistener.com/opinion/1435894/', '1435894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the showup procedure was impermissibly suggestive, but because the victim''s identification of defendant was reliable, it was properly admitted at trial.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that evidence obtained from an out-of-court showup is inherently suggestive and will not be admissible unless, based on the totality of the circumstances, the procedure was necessary.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in combination with the suggestiveness inherent in a showup, the added comments by the police rendered the showup procedures in the out-of-court identification of defendant impermissibly suggestive.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an approximate five-hour period between the incident and the identification does not subvert the reliability of the identification procedure.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the totality of the circumstances, we conclude that the trial court properly admitted Valentin''s out-of-court identification of defendant.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Appellate Division''s judgment.', 'general', 'State v. Herrera', 'https://www.courtlistener.com/opinion/1442836/', '1442836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 495, we determined that "[u]nder these circumstances *454 we conclude that the acts complained of were nothing more than an ordinary domestic contretemps which the Act was never intended to address.', 'general', 'Silver v. Silver', 'https://www.courtlistener.com/opinion/1443850/', '1443850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that on plaintiff''s puny proofs, the domestic violence order was unwarranted.', 'general', 'Silver v. Silver', 'https://www.courtlistener.com/opinion/1443850/', '1443850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kamen, supra, for example, although the predicate act of trespass had occurred, we concluded that a domestic violence restraining order was not warranted because the trespass was "unaccompanied by violence or a threat of violence[.', 'general', 'Silver v. Silver', 'https://www.courtlistener.com/opinion/1443850/', '1443850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 495 (1974), we found that "the judge correctly concluded that defendant had committed an act of criminal trespass by entering plaintiff''s home knowing that she was not licensed or privileged to do so on that occasion.', 'general', 'Silver v. Silver', 'https://www.courtlistener.com/opinion/1443850/', '1443850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the entry of a restraining order, finding that proof of the requisite elements "of the purpose to harass," a "course of alarming conduct" or "repeated acts intended to alarm or seriously annoy another" for establishment of "harassment," were absent.', 'general', 'Silver v. Silver', 'https://www.courtlistener.com/opinion/1443850/', '1443850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Peranio, supra, we reversed entry of a domestic violence restraining order because there was no finding by the trial court that the defendant had uttered the statement, "I''ll bury you," to the plaintiff with the purpose to harass her, nor was there a course or repeated acts of alarming conduct.', 'general', 'Silver v. Silver', 'https://www.courtlistener.com/opinion/1443850/', '1443850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion in summarily denying Hilton''s motion for a new trial without a hearing to determine if appellant''s claims of fear and intimidation were credible.', 'general', 'Lyons v. United States', 'https://www.courtlistener.com/opinion/1444074/', '1444074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in denying Lyons''s motion to suppress and affirm his conviction, but rem and for a hearing on Hilton''s motion for a new trial.', 'suppression', 'Lyons v. United States', 'https://www.courtlistener.com/opinion/1444074/', '1444074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8]  We affirm the ruling of the trial court denying Hilton''s motion for judgment of acquittal, holding that the evidence was sufficient for a reasonable jury to find the appellant guilty beyond a reasonable doubt.', 'general', 'Lyons v. United States', 'https://www.courtlistener.com/opinion/1444074/', '1444074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the affidavit failed to establish probable cause.', 'probable_cause', 'Sisson v. State', 'https://www.courtlistener.com/opinion/1443990/', '1443990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the legislature’s concern with the proliferation of child pornography using new and old technology, we conclude that the legislature had a rational basis for looking to the end product of the exploitation to set forth the per-visual-depiction unit of prosecution under § 1108.', 'general', 'Sisson v. State', 'https://www.courtlistener.com/opinion/1443990/', '1443990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the affidavit established probable cause, because Sisson was properly charged with ten counts of Sexual Exploitation, and because the evidence supports his conviction of six counts, we affirm the trial judge’s rulings and Sisson’s convictions.', 'probable_cause', 'Sisson v. State', 'https://www.courtlistener.com/opinion/1443990/', '1443990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no basis for reversal, we affirm.', 'general', 'State v. Newell', 'https://www.courtlistener.com/opinion/1742814/', '1742814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the defendant''s conviction of first-degree murder.', 'general', 'State v. Newell', 'https://www.courtlistener.com/opinion/1742814/', '1742814') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” nor do we hold that psychological harm cannot be “unjustifiable pain and suffering.', 'general', 'Alfaro v. United States', 'https://www.courtlistener.com/opinion/1476696/', '1476696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and for additional reasons set forth below, we conclude that simple assault is not a lesser included offense of attempted second-degree cruelty to children, and we therefore affirm Ms.', 'general', 'Alfaro v. United States', 'https://www.courtlistener.com/opinion/1476696/', '1476696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that assault contains an element that attempted second-degree cruelty to children does not, that the offenses do not'' merge, and that Ms.', 'general', 'Alfaro v. United States', 'https://www.courtlistener.com/opinion/1476696/', '1476696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, having reviewed the evidence in the light most favorable to the government, we conclude that the prosecution failed to prove that the telephone cord was “likely,” when used as Ms.', 'general', 'Alfaro v. United States', 'https://www.courtlistener.com/opinion/1476696/', '1476696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the evidence was insufficient to convict Ms.', 'general', 'Alfaro v. United States', 'https://www.courtlistener.com/opinion/1476696/', '1476696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding neither of these grounds nor any of a number of others also raised by appellant sufficient to warrant a new trial, we affirm the conviction.', 'general', 'Carr v. United States', 'https://www.courtlistener.com/opinion/1486227/', '1486227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no evidence that the appellant was harmed by the variance, we affirmed the conviction under the proper stat
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Under these circumstances, we hold that DHS received notice comporting with due process and the requirements of Ark.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the particular facts of this case, we hold that Doherty had notice of the accusation that otherwise comported with the requirements of section 16-10-108 and due process of law.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that DHS must first attempt to obtain relief in the trial court.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, we conclude that DHS has standing and has filed a timely notice of appeal from the trial court''s order denying its motion to set aside the September 30 order.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that the trial court is empowered to order family services in FINS cases to prevent a juvenile from being removed from a parent, which by definition includes cash assistance, we conclude that the General Assembly has specifically waived sovereign immunity as to DHS in such instances.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reasons expressed as to DHS above, we affirm the trial court here.', 'general', 'Arkansas Department of Human Services v. R.P.', 'https://www.courtlistener.com/opinion/1491821/', '1491821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, this Court holds that a conviction for resisting arrest cannot stand where the underlying arrest is found to be unlawful.', 'general', 'Commonwealth v. Biagini', 'https://www.courtlistener.com/opinion/1512513/', '1512513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Turning to the facts of the cases at bar, we conclude that the Commonwealth has met its respective burdens as to both Biagini and Barry W.', 'general', 'Commonwealth v. Biagini', 'https://www.courtlistener.com/opinion/1512513/', '1512513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the appeal of Biagini, we reverse only that part of the Order of the Superior Court which affirmed the conviction for resisting arrest.', 'general', 'Commonwealth v. Biagini', 'https://www.courtlistener.com/opinion/1512513/', '1512513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the remaining portion of the Superior Court Order which affirmed the conviction for aggravated assault and reversed the convictions for disorderly conduct, public drunkenness, prohibited offensive weapons and possession of a small amount of marijuana.', 'general', 'Commonwealth v. Biagini', 'https://www.courtlistener.com/opinion/1512513/', '1512513') ON CONFLICT DO NOTHING;
