INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, except with
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that this defendant did not "volunteer," under N.', 'general', 'State v. Valentin', 'https://www.courtlistener.com/opinion/1516529/', '1516529') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court failed to exercise its discretion under V.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this rule, we held that "[w]hen the sexual acts are taken together *573 with the specific statements that the girlfriend and the victim were forced to repeat, and the defendant''s frequent use of cocaine during the activity, the evidence strongly tended to show that defendant was the perpetrator.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[but][e]ven accounting for the court''s wide discretion, we conclude that probative value was substantially outweighed by the danger of unfair prejudice.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 416, 419 (1989), for example, we concluded that the trial court had exercised its discretion under Rule 403 based on the trial court''s statement that it was "going to let in the cocaine evidence.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We concluded that the record did not indicate that the prejudicial effect of the admitted evidence "so overweighed the probative value that the evidence should have been excluded as a matter of law.', 'general', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Senecal, we concluded that a defendant had waived his claim that the court erred in denying his motion to suppress where defendant failed to object at trial to the admission of the evidence that he had earlier sought to suppress.', 'suppression', 'State v. Shippee', 'https://www.courtlistener.com/opinion/1533666/', '1533666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the admission of Officer Semmel''s testimony relating the testimonial statements of the non-appearing eyewitness violated defendant''s Sixth Amendment right to confront the witnesses against him.', 'general', 'State Ex Rel. Ja', 'https://www.courtlistener.com/opinion/1541942/', '1541942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the non-appearing witness''s statements relating the details of a robbery that occurred ten minutes earlier is not the equivalent of describing the crime "immediately after" it occurred.', 'general', 'State Ex Rel. Ja', 'https://www.courtlistener.com/opinion/1541942/', '1541942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the non-appearing eyewitness''s statements to Officer *806 Semmel about the robbery were testimonial.', 'general', 'State Ex Rel. Ja', 'https://www.courtlistener.com/opinion/1541942/', '1541942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not decide that issue, however, because we find that defendant did not have a prior opportunity to cross-examine the non-appearing witness whose statements were clearly testimonial.', 'general', 'State Ex Rel. Ja', 'https://www.courtlistener.com/opinion/1541942/', '1541942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the reasoning of the United States Supreme Court, we held that only evidence that bore on defendant''s character would be admissible in a capital penalty phase proceeding.', 'general', 'State v. Blackmon', 'https://www.courtlistener.com/opinion/1542499/', '1542499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Crosby''s sentence was the rare case where an habitual offender received a grossly disproportionate sentence.', 'sentencing', 'Forehand v. State', 'https://www.courtlistener.com/opinion/1543627/', '1543627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that the trial court erred when instructing the jury that it could convict the defendant of first-degree murder on an aiding and abetting theory without requiring a finding that he had formed the specific intent to murder required to convict a principal;', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), in which we held that, because D.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2009), in which we concluded that "Wilson-Bey is not limited to specific intent crimes.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in Winstead, we concluded that for the purposes of the carjacking statute, a car is within a victim''s immediate actual possession if "`the car is within such range that the victim could, if not deterred by violence or fear, retain actual physical control over it.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2002), where we affirmed a conviction for carjacking by a defendant who had assaulted the victim, initially, in the security-guard booth where she was working, and then appropriated her car "only a few feet away" from the booth.', 'general', 'Sutton v. United States', 'https://www.courtlistener.com/opinion/1546590/', '1546590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that denying to committed same-sex couples the financial and social benefits and privileges given to their married heterosexual counterparts bears no substantial relationship to a legitimate governmental purpose.', 'general', 'Lewis v. Harris', 'https://www.courtlistener.com/opinion/1551161/', '1551161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained, we affirm in part and modify in part the judgment of the Appellate Division.', 'general', 'Lewis v. Harris', 'https://www.courtlistener.com/opinion/1551161/', '1551161') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the issues raised by Barnes are without merit and that her conviction should be affirmed.', 'general', 'Barnes v. State', 'https://www.courtlistener.com/opinion/1556296/', '1556296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record supports a finding that Barnes received the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we affirm the judgment of conviction of embezzlement in the Circuit Court of Warren County and sentence of ten years in the custody of the Mississippi Department of Corrections.', 'sentencing', 'Barnes v. State', 'https://www.courtlistener.com/opinion/1556296/', '1556296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But because we hold that the mandatory LWOR sentence on the first-degree premeditated murder conviction is unconstitutional under Miller, we vacate that sentence and remand for resentencing on the first-degree premeditated murder conviction following a Miller hearing.', 'sentencing', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the postconviction court did not abuse its discretion when it determined that the birth certificate was not admissible under Rule 901.', 'general', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the postconviction court did not err in denying Mahdi’s petition.', 'general', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in the context of the trial, the district court did not abuse its discretion in allowing Sergeant Kjos to testify that once she and her partner viewed the surveillance videos, they eliminated Abdisalan as one of the two assailants who entered the market and determined that Ahmed was the accomplice at the Seward Market who did not have a gun.', 'general', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, one of the Target analysts testified that by using the camera angle and distance from the camera, it is possible to tell that one suspect is taller than the other, The district court determined this sort of testimony would help the jury, and we hold that the court did not abuse its discretion in reaching that determination.', 'general', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court’s imposition of consecutive life sentences did not violate Article I, Section 5 of the Minnesota Constitution.', 'sentencing', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not abuse its discretion by imposing consecutive sentences on Mahdi.', 'sentencing', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our careful review of the record, we hold that Mahdi has not shown that his counsel was ineffective.', 'ineffective_assistance', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the district court did not abuse its discretion in admitting testimony about a letter sent to the Sioux Falls Police Department that started the investigation or the content of police interviews with neighbors.', 'general', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Fedziuk, we held that the implied consent law was facially unconstitutional.', 'general', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that the district court had the authority to impanel a sentencing jury.', 'sentencing', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this limitation, we concluded that the defense was not available.', 'general', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State we concluded that the Miller rule is procedural for retroactivity purposes.', 'general', 'State of Minnesota v. Mahdi Hassan Ali', 'https://www.courtlistener.com/opinion/2743646/', '2743646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when a policeman has made a lawful custodial arrest of the occupant of an automobile, he may, as a contemporaneous incident of that arrest, search the passenger compartment of that automobile.', 'general', 'United States v. Debruhl', 'https://www.courtlistener.com/opinion/1917628/', '1917628') ON CONFLICT DO NOTHING;
