INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, relying on
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'United States v. Debruhl', 'https://www.courtlistener.com/opinion/1917628/', '1917628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '66(1) to the offenses involved in this case, we conclude that second-degree reckless homicide is not a lesser-included offense of homicide by intoxicated use of a vehicle.', 'general', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that second-degree reckless homicide is not a less serious type of criminal homicide than homicide by intoxicated use of a vehicle under Wis.', 'general', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the legislature intended that multiple convictions and punishments attend the separate homicide offenses to which the defendant here pled no contest.', 'general', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts set out in record, we conclude that there was a sufficient break in the defendant''s conduct to constitute at least two separate and distinct criminal acts of second-degree reckless endangerment under Wis.', 'general', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there are no factors which clearly indicate that the legislature intended that all acts of second-degree reckless endangerment be prosecuted in a single count.', 'general', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the legislature intended that multiple punishments attend the separate counts to which the defendant here pled no contest.', 'general', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did not.', 'general', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the circumstances surrounding the defendant''s sentencing and the circuit court''s in-depth consideration of the gravity of the offenses in this case, the character of the defender, and the need for protection of the public, we conclude that the circuit court did not rely on inaccurate information in the presentence report and, therefore, did not violate the defendant''s due process right to be sentenced only on materially accurate information.', 'sentencing', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the State did not violate the defendant''s constitutional rights to be free from being twice placed in jeopardy for the same crime when the defendant pled no contest to and was sentenced for both second-degree reckless homicide and homicide by intoxicated use of a vehicle.', 'sentencing', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that the circuit court satisfied the requirements of Wis.', 'general', 'State v. Lechner', 'https://www.courtlistener.com/opinion/1573159/', '1573159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the trial judge did not err by initiating or considering an ex parte communication or by failing to recuse herself, and that appellant''s other assignments of error are without merit.', 'general', 'In Re DM', 'https://www.courtlistener.com/opinion/1917950/', '1917950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We disagree, and as we find appellant''s other claims of error to be meritless, we affirm his delinquency adjudication.', 'general', 'In Re DM', 'https://www.courtlistener.com/opinion/1917950/', '1917950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today we hold that Congress cannot circumvent that prohibition by conscripting the State''s officers directly.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the Department''s adoption of Nurse Aide Regulations does not violate traditional notions of federalism.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that Molden and Avery were afforded the constitutional requisite minimum procedural due process by the Department before final adverse findings were made against them.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that the standard of conduct for a charge of neglect adopted by the Department is not unconstitutionally vague, and thus, this issue is without merit.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, since the regulations do not provide that the formal rules of evidence and procedure are applicable at the hearing, we hold that the hearing officer did not err in denying Molden''s and Avery''s motion to compel discovery as to all documents possessed by the Department.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the agency''s decision to permanently revoke the certification of April Avery, remove her name from the Certified Nurse Aide Roster, and to permanently place her name on the State Nurse Aide Abuse Roster was not arbitrary and capricious.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that Molden and Avery were afforded notice of the pendency of the action and an opportunity to present their objections, and as a result, their due process rights were not violated.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that although the hearing officer applied an incorrect evidentiary standard for the revocation of Molden''s and Avery''s licenses, any such error was cured by the chancellor in his application of the requisite judicial review stated in Riddle and determination that the Department proved neglect by clear and convincing evidence.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that while the Department''s definition of neglect is broad and general and does not provide any specific examples of what actions may constitute neglect, the definition does provide a sufficiently definite warning as to the proscribed conduct when measured by common understanding and practices.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we find that this assignment of error is without merit.', 'general', 'Molden v. MISS. STATE DEPT. OF HEALTH', 'https://www.courtlistener.com/opinion/1918218/', '1918218') ON CONFLICT DO NOTHING;
