INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that based on the testimony offered, a jury could conclude beyond a reasonable doubt that Hackett’s conduct had the capacity to impair or debauch the morals of a minor.', 'general', 'State v. Hackett', 'https://www.courtlistener.com/opinion/1918389/', '1918389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court on all counts.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1579381/', '1579381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court erred in failing to exclude unauthenticated business records upon timely and proper defense objection, we reverse for a new trial.', 'general', 'Armstrong v. State', 'https://www.courtlistener.com/opinion/1581046/', '1581046') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a person convicted of going armed with a concealed and dangerous weapon contrary to Wis.', 'general', 'State v. Perez', 'https://www.courtlistener.com/opinion/1581568/', '1581568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a seized dangerous weapon may not be returned to a person convicted of the crime of carrying a concealed and dangerous weapon.', 'general', 'State v. Perez', 'https://www.courtlistener.com/opinion/1581568/', '1581568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'State v. Perez', 'https://www.courtlistener.com/opinion/1581568/', '1581568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defendant''s claims are factually without merit and that his guilty pleas in No.', 'plea', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record affirmatively shows the defendant understood the charge against him and was aware not only of the penalty range, but also of the specific penalty to be imposed.', 'general', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defendant''s guilty plea in No.', 'plea', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the district court entered determinate sentences for each conviction.', 'sentencing', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defendant was not prejudiced by the assignment of cases.', 'general', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defendant knowingly and voluntarily entered his guilty plea and waived his remedy.', 'plea', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the arrest warrant satisfies the requirements of La.', 'general', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this instance, we find that the defendant would be better served in having his ineffective assistance of counsel claim addressed through the PCR process in which his claims might be briefed in a more thorough manner.', 'ineffective_assistance', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review, we found that while this circuit never expressly required the trial court to explicitly enumerate the possible sentences, this circuit did hold that a guilty plea will not be rendered invalid where there is an affirmative showing on the record that the defendant understood the charge against him and was aware of the permissible penalty range.', 'sentencing', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with the aforementioned reasons, we affirm the convictions and sentences of the defendant, as amended.', 'sentencing', 'State v. Sebastien', 'https://www.courtlistener.com/opinion/1918611/', '1918611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '931, we conclude that defendant was properly bound over on that charge.', 'general', 'People v. LeClaire', 'https://www.courtlistener.com/opinion/2221235/', '2221235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court improperly substituted its judgment for that of the magistrate and resolved a factual question which should have been left for the trier of fact after consideration of evidence produced at a full trial.', 'general', 'People v. LeClaire', 'https://www.courtlistener.com/opinion/2221235/', '2221235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for reinstatement of the charges.', 'general', 'People v. LeClaire', 'https://www.courtlistener.com/opinion/2221235/', '2221235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it may not, and that a later court determining the character of an admitted burglary is generally limited to examining the statutory definition, charging document, written plea agreement, transcript of plea colloquy, and any explicit factual finding by the trial judge to which the defendant assented.', 'plea', 'Shepard v. United States', 'https://www.courtlistener.com/opinion/142875/', '142875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that enquiry under the ACCA to determine whether a plea of guilty to burglary defined by a nongeneric statute necessarily admitted elements of the generic offense is limited to the terms of the charging document, the terms of a plea agreement or transcript of colloquy between judge and defendant in which the factual basis for the plea was confirmed by the defendant, or to some comparable judicial record of this information.', 'plea', 'Shepard v. United States', 'https://www.courtlistener.com/opinion/142875/', '142875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '575 (1990), we held that a court sentencing under the ACCA could look to statutory elements, charging documents, and jury instructions to determine whether an earlier conviction after trial was for generic burglary.', 'sentencing', 'Shepard v. United States', 'https://www.courtlistener.com/opinion/142875/', '142875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We held that the ACCA generally prohibits the later court from delving into particular facts disclosed by the record of conviction, thus leaving the court normally to "look only to the fact of conviction and the statutory definition of the prior offense.', 'general', 'Shepard v. United States', 'https://www.courtlistener.com/opinion/142875/', '142875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“there is some basis for concluding that the witness[es][are] more likely to correctly identify the defendant from the photograph than is the jury,” we hold that the district court acted within its discretion in admitting lay opinion identification testimony from [the lay witnesses] .', 'general', 'Sanders v. United States', 'https://www.courtlistener.com/opinion/1547174/', '1547174') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, because [the lay witness] had met with [the appellant] approximately 50 times and [another lay witness] had known [the appellant] most of his life, the opinions testified to by [the lay witnesses] were rationally based and helpful to the jury in determining a fact in issue.', 'general', 'Sanders v. United States', 'https://www.courtlistener.com/opinion/1547174/', '1547174') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we conclude that the lay opinion identification testimony admitted was “helpful to the determination of a fact in issue” within the meaning of [F.', 'general', 'Sanders v. United States', 'https://www.courtlistener.com/opinion/1547174/', '1547174') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the case before us, we conclude that the trial court did not abuse its discretion by admitting into evidence the opinions of lay witnesses who identified Mr.', 'general', 'Sanders v. United States', 'https://www.courtlistener.com/opinion/1547174/', '1547174') ON CONFLICT DO NOTHING;
