INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, under the circumstances of that case, the PFCV conviction based on the merged aggravated assault/mayhem counts against one victim merged with a PFCV conviction grounded on assault with intent to kill pertaining to four victims.', 'general', 'Sanders v. United States', 'https://www.courtlistener.com/opinion/1547174/', '1547174') ON CONFLICT DO NOTHING;
