INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the above analysis, we conclude that section 775.', 'general', 'Clines v. State', 'https://www.courtlistener.com/opinion/1919090/', '1919090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Expanding on this ruling, we hold that a violation may be continuing under either the "amount owed theory" or the "time ordered theory.', 'general', 'People v. Monaco', 'https://www.courtlistener.com/opinion/1590690/', '1590690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to this case, we conclude that the statutory period of limitations on the felony-nonsupport charge against defendant has not yet begun to run.', 'general', 'People v. Monaco', 'https://www.courtlistener.com/opinion/1590690/', '1590690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '165, we conclude that felony-nonsupport charge against defendant does not violate ex post facto prohibitions.', 'general', 'People v. Monaco', 'https://www.courtlistener.com/opinion/1590690/', '1590690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Monaco', 'https://www.courtlistener.com/opinion/1590690/', '1590690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s denial of defendant''s motion to dismiss even though it reached the right result for the wrong reason.', 'dismissal', 'People v. Monaco', 'https://www.courtlistener.com/opinion/1590690/', '1590690') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bell v. State', 'https://www.courtlistener.com/opinion/1592705/', '1592705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the words "reasonable cause to suspect” speak for themselves and provide fair notice of the conduct expected in reporting suspected child abuse.', 'general', 'People v. Cavaiani', 'https://www.courtlistener.com/opinion/1594984/', '1594984') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In turn, this Court granted the people leave to appeal on February 11, 1988, and we reverse the order of the circuit court.', 'general', 'People v. Cavaiani', 'https://www.courtlistener.com/opinion/1594984/', '1594984') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the record, we find that Henley has failed to satisfy either prong of the Strickland.', 'ineffective_assistance', 'Henley v. State', 'https://www.courtlistener.com/opinion/1599358/', '1599358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Section 543.', 'general', 'State v. Gale Distributors, Inc.', 'https://www.courtlistener.com/opinion/1606515/', '1606515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We conclude that the State of California has exercised a power which it retained under the Constitution, and that the challenged statute, as applied in this case, does not intrude into an area which Congress has, up to now, pre-empted.', 'general', 'State v. Gale Distributors, Inc.', 'https://www.courtlistener.com/opinion/1606515/', '1606515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the statutory provision in question does not constitute ex post facto legislation.', 'general', 'State v. Gale Distributors, Inc.', 'https://www.courtlistener.com/opinion/1606515/', '1606515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we find that Section 543.', 'general', 'State v. Gale Distributors, Inc.', 'https://www.courtlistener.com/opinion/1606515/', '1606515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the foregoing construction, we find that Section 543.', 'general', 'State v. Gale Distributors, Inc.', 'https://www.courtlistener.com/opinion/1606515/', '1606515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'nevertheless we conclude that on balance actions which enhance the enforcement of our laws or expose unsafe conditions, or otherwise serve some singularly public purpose, will inure to the benefit of the public.', 'general', 'Wagner v. City of Globe', 'https://www.courtlistener.com/opinion/2603584/', '2603584') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s argument has no merit because the legal consequences of 1998 PA 350 attached to defendant only as a result of acts committed by defendant after the effective date of the statute.', 'general', 'People v. Callon', 'https://www.courtlistener.com/opinion/1608210/', '1608210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion by allowing the late endorsement of a critical prosecution witness where the witness was known to the defense, had been subjected to cross-examination at the preliminary examination, and where no continuance was requested and no unfair prejudice resulted to defendant.', 'general', 'People v. Callon', 'https://www.courtlistener.com/opinion/1608210/', '1608210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statute did not require separate findings of fact and that “ ‘due process neither compels a separate charge nor imposes trial-type evidentiary burdens on the sentencing process.', 'sentencing', 'People v. Callon', 'https://www.courtlistener.com/opinion/1608210/', '1608210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant failed to preserve this issue by making a timely, contemporaneous objection and request for a curative instruction.', 'general', 'People v. Callon', 'https://www.courtlistener.com/opinion/1608210/', '1608210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Callon', 'https://www.courtlistener.com/opinion/1608210/', '1608210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s conviction and sentence.', 'sentencing', 'People v. Callon', 'https://www.courtlistener.com/opinion/1608210/', '1608210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the trial court erred in finding the avoid arrest and committed in the course of a felony aggravators.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), this Court held that it was improper for the State to elicit testimony from a police officer about the criminal behavior pattern of drug addicts.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this Court held that the trial court erred in admitting and considering the evidence regarding the previous murder.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record in this case, we conclude that the State presented sufficient evidence of premeditated murder and there is no reasonable hypothesis to the contrary.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that the trial court in the instant case did not err in permitting White to testify that Anderson was on probation for eleven counts of attempted sexual battery on Keinya.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" With this in mind, we conclude that the alleged improper comments, taken both individually *404 and collectively, did not deprive Anderson of a fair trial.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we concluded that the proper finding of the remaining three aggravators renders the use of these two aggravators harmless.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, we find that the trial court did not abuse its discretion in denying Anderson''s motion for mistrial.', 'mistrial', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering each of the comments, we find that none of them amounted to fundamental error.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing all of the evidence in the record, we find that there is competent, substantial evidence to support Anderson''s conviction for first-degree murder.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1611561/', '1611561') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), we held that for offenses which neither expressly require, nor plainly dispense with a culpable mental state, an indictment which fails to specifically allege a mental state will be sufficient *106 so long as the mental state required can be logically inferred from the allegations in the indictment so as to satisfy constitutional and statutory requirements of notice and form.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), this Court held that to establish probable cause an affidavit must set forth facts from which a reasonable conclusion may be drawn that the evidence will be found in the place to be searched pursuant to the warrant.', 'probable_cause', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), this Court held that trial courts are statutorily required to instruct juries on all lesser-included and "lesser-grade or class"[1] offenses, if the evidence introduced at trial is legally sufficient to support a conviction for the lesser offenses.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the previously explained reasons, we conclude that the jury instructions read as a whole were not prejudicially erroneous;', 'jury_instruction', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Based upon this proof, we conclude that the evidence is sufficient to establish that the murder was especially heinous, atrocious, or cruel in that it involved serious physical abuse beyond that necessary to produce death.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying those rules to the facts of this case, we conclude that the Court of Criminal Appeals properly affirmed the trial court''s judgment denying the defendant''s motion to suppress.', 'suppression', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the nature of the crime and the defendant, we conclude that imposition of the death penalty for the cruel killing of this young child is not disproportionate to the penalty imposed in similar cases, and that this murder places Vann into the class of defendants for whom the death penalty is an appropriate punishment.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review, we conclude that the following cases in which the death penalty has been imposed have many similarities with this case.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s thorough instruction of the law was sufficient to counter the Defendant''s request for a specific instruction that the State''s case was based entirely upon circumstantial evidence.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*115 In this case, we conclude that the trial court carefully and meticulously orchestrated the jury selection process to insure the Defendant a fair trial.', 'general', 'State v. Vann', 'https://www.courtlistener.com/opinion/2460607/', '2460607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction of conspiracy to commit willful injury and remand for resentencing to eliminate the sentence for that offense.', 'sentencing', 'State v. Mapp', 'https://www.courtlistener.com/opinion/1619596/', '1619596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction for conspiracy to commit murder but reverse the conviction of conspiracy to commit willful injury.', 'general', 'State v. Mapp', 'https://www.courtlistener.com/opinion/1619596/', '1619596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction of conspiracy to commit murder.', 'general', 'State v. Mapp', 'https://www.courtlistener.com/opinion/1619596/', '1619596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the meaning of the statutory provision in question is plain, then we give effect to that plain meaning, as long as it does not lead to an absurd result.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1619492/', '1619492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these dictionary definitions, we conclude that in common usage, the term "instrument" is broad enough to encompass a Social Security card and, therefore, that the phrase "other instruments issued by a state or national government or by a subdivision of either," as used in Texas Penal Code § 32.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1619492/', '1619492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1619492/', '1619492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the clear and uncontested record evidence of penetration regarding Count I, we hold that no reasonable jury would have returned a verdict finding there was no penetration.', 'general', 'Galindez v. State', 'https://www.courtlistener.com/opinion/1619733/', '1619733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that harmless error analysis applies to Apprendi and Blakely error.', 'general', 'Galindez v. State', 'https://www.courtlistener.com/opinion/1619733/', '1619733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we explain below, we find that any failure to apply Apprendi and Blakely in this case constitutes harmless error.', 'general', 'Galindez v. State', 'https://www.courtlistener.com/opinion/1619733/', '1619733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Ceaser', 'https://www.courtlistener.com/opinion/1620316/', '1620316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the Rodriguez bifurcated trial process in felony DUI prosecutions in light of Gaudin,[[2]] we hold that in this bifurcated process the jury, not the judge, must determine the verdict from the evidence presented in the second phase.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1643603/', '1643603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court found that it should be amended: "Examining the Rodriguez bifurcated trial process in felony DUI prosecutions in light of Gaudin, we hold that in this bifurcated process the jury, not the judge, must determine the verdict from the evidence presented in the second phase.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1643603/', '1643603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if a defendant charged with felony DUI elects to be tried by jury, the court shall conduct a jury trial on the elements of the single incident of DUI at issue without allowing the jury to learn of the alleged prior DUI offenses.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1643603/', '1643603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial judge erred when he conducted a bench trial during the second phase.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1643603/', '1643603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the error in the instant case is not reversible but is, instead, harmless.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1643603/', '1643603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this assertion is without merit for multiple reasons.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1643603/', '1643603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that these distinctions are readily identifiable and inherent in the dispositional process, which has been comprehensively addressed by our Legislature under chapter 985.', 'general', 'EAR v. State', 'https://www.courtlistener.com/opinion/1644479/', '1644479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that simply parroting is insufficient to justify departure and that, instead, the juvenile court''s stated "reasons," must provide a legally sufficient foundation for "disregarding" the DJJ''s professional assessment and PDR by identifying significant information that the DJJ has overlooked, failed to sufficiently consider, or misconstrued with regard to the child''s programmatic, rehabilitative needs along with the risks that the unrehabilitated child poses to the public.', 'general', 'EAR v. State', 'https://www.courtlistener.com/opinion/1644479/', '1644479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Taking the evidence as a whole and viewing it in the light most favorable to the jury’s verdict, we hold that the evidence is sufficient to support the jury’s finding that Fisher’s murder was premeditated.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, on this record, we hold that Leake’s admission supports the court’s use of the conviction under the heinous crime statute.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the instant case involves only logical inconsistencies — between a verdict of acquittal on one count and a verdict of guilty on another count— we hold that the verdicts are not legally inconsistent and Leake is not entitled to a new trial.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “the constitutional protections articulated in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the jury’s verdicts finding the defendant guilty of both first- and second-degree murder were not legally inconsistent.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the verdicts of guilty of first-degree premeditated murder and guilty of second-degree manslaughter were legally inconsistent because the defendant could not have caused the death of his wife with premeditation and intent and at the same time cause her death through negligence or reckless conduct.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the record before us, we conclude that sufficient proof of premeditation was supplied by the circumstantial evidence presented at trial.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor’s speculation about the substance of the voice mail message and the conversation between Fisher and Leake was improper.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the prosecutor’s arguments could be interpreted as going beyond the mere facts, we conclude that these comments were not prejudicial and therefore did not affect appellant’s substantial rights.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if these statements go beyond arguing reasonable inferences from the testimony at trial, we conclude that they do hot satisfy the third prong of the-plain error test.', 'general', 'State v. Leake', 'https://www.courtlistener.com/opinion/1649738/', '1649738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "findings of fact as to the circumstances surrounding the interrogation are reviewed for clear error" but that the ultimate determination of whether, under those facts, "a reasonable person would have felt that he or she was or was not at liberty to terminate the interrogation and leave is reviewed de novo.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8] We held that when "taken in context," those statements "can be read as frustration with particular questions rather than clearly stated intent to end the interview.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] Once again, we held that this statement was more indicative of Thomas'' frustration *69 with the officers'' questions than "a clear invocation of his right to remain silent.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that Rogers unambiguously invoked her right to remain silent.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed, we conclude that the district court erred in denying Rogers'' motion to suppress to the extent that the court admitted statements made by Rogers after she unambiguously invoked her right to remain silent.', 'suppression', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a reasonable police officer could have interpreted this "single statement" as merely an expression of Thomas'' frustration with the investigators'' unwillingness to believe him.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mata, we concluded that when "the interview was conducted at the police station, it is reasonable to conclude that the atmosphere was `police dominated.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that Rogers'' confession was procured in violation of her Fifth Amendment right against self-incrimination, and we reverse the conviction and remand the cause for a new trial.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[115] We find that Rogers'' confession and the circumstantial evidence against her were sufficient to sustain the verdict.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thomas, for instance, we found that the defendant had not clearly invoked the right to remain silent when his statement, "`I''m done talkin'' man,''" was followed directly by "a question requesting further information, which also acted to encourage further dialog.', 'general', 'State v. Rogers', 'https://www.courtlistener.com/opinion/1654613/', '1654613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Superior Court holding that a savings clause must be implied in the amending legislation.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1922053/', '1922053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Superior Court.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1922053/', '1922053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that such an extraterritorial order by a circuit judge in a criminal case was void, and that jurisdiction for such an order could not be waived or conferred by consent.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1672968/', '1672968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 104 (1999), this court held that the choice of which charges to file against an accused is a matter entirely within the prosecutor’s discretion.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1672968/', '1672968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the trial judge should have granted appellant’s motion for joinder, and reversed and dismissed the rape conviction.', 'dismissal', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1672968/', '1672968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we reverse based on the trial court’s attempt to transfer the appellee’s prosecution outside the judicial district where the offense was charged, the State’s alternate argument that we issue a writ of certiorari is moot.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1672968/', '1672968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" In the instant case, we hold that an attorney''s communication to his client of the trial dates is not a communication "not intended to be disclosed to third persons.', 'general', 'Watkins v. State', 'https://www.courtlistener.com/opinion/1678357/', '1678357') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a trial court may not utilize a prior conviction in calculating a guidelines sentence which is subsequently held to be a nonexistent crime.', 'sentencing', 'Watkins v. State', 'https://www.courtlistener.com/opinion/1678357/', '1678357') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Watkins v. State', 'https://www.courtlistener.com/opinion/1678357/', '1678357') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm nonetheless, in light of the detail that both parties otherwise went into in describing appellant''s and Isaac''s apparel on the night in question, as well as in light of the other evidence tending to incriminate *1047 appellant, such as, of course, the surgical gloves.', 'general', 'Watkins v. State', 'https://www.courtlistener.com/opinion/1678357/', '1678357') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we affirm the points scored under prior record for appellant''s federal conviction as it corresponds with or is analogous to section 812.', 'general', 'Watkins v. State', 'https://www.courtlistener.com/opinion/1678357/', '1678357') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, this Court held that a person must have deliberately *1083 acted to create a disturbance in order to commit a criminal offense under section 871.', 'general', 'In Re Standard Jury Inst. in Crim. Cases No. 2007-03', 'https://www.courtlistener.com/opinion/1684173/', '1684173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that to establish a violation of section 726.', 'general', 'State v. Millsap', 'https://www.courtlistener.com/opinion/1697544/', '1697544') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 699 (Iowa 2000), wherein this court held the presiding judge should have recused himself.', 'general', 'State v. Millsap', 'https://www.courtlistener.com/opinion/1697544/', '1697544') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of the record and the arguments of the parties, we affirm with one exception.', 'general', 'State v. Millsap', 'https://www.courtlistener.com/opinion/1697544/', '1697544') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the stop of Baptiste at gunpoint solely on the basis of the anonymous tip is contrary to J.', 'general', 'Baptiste v. State', 'https://www.courtlistener.com/opinion/1697730/', '1697730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the conclusion of the Third District, we hold that this stop and search of Baptiste violated the Fourth Amendment.', 'search_seizure', 'Baptiste v. State', 'https://www.courtlistener.com/opinion/1697730/', '1697730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*295 We conclude that a person has been "seized" within the meaning of the Fourth Amendment only if, in view of all of the circumstances surrounding the incident, a reasonable person would have believed that he was not free to leave.', 'search_seizure', 'Baptiste v. State', 'https://www.courtlistener.com/opinion/1697730/', '1697730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1375, we conclude that like the officers in J.', 'general', 'Baptiste v. State', 'https://www.courtlistener.com/opinion/1697730/', '1697730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, unlike the Third District in the instant case, the Second District correctly applied the analysis of the Supreme Court in J.', 'general', 'Baptiste v. State', 'https://www.courtlistener.com/opinion/1697730/', '1697730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction, reverse the sentence for cruelty to a child, and remand for resentencing.', 'sentencing', 'State v. Lambert', 'https://www.courtlistener.com/opinion/1922722/', '1922722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the place where
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4   Similarly, we held that venue is proper in the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1702618/', '1702618') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals'' decision.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1702618/', '1702618') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 40 Accordingly, we affirm the decision of the court of appeals.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1702618/', '1702618') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm without discussion the conviction for discharging a firearm.', 'general', 'Lamb v. State', 'https://www.courtlistener.com/opinion/1702956/', '1702956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was not.', 'general', 'Chambers v. State', 'https://www.courtlistener.com/opinion/1708299/', '1708299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Continuing to apply the Ray analysis, we conclude that aggravated assault with a firearm, a second-degree felony, is lesser in degree and punishment than attempted second-degree murder with a firearm, a first-degree felony.', 'general', 'Chambers v. State', 'https://www.courtlistener.com/opinion/1708299/', '1708299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though the defendant did not object to the instructions on this lesser offense and the offense was lesser in both degree and penalty, we reversed the conviction without any discussion of Ray.', 'general', 'Chambers v. State', 'https://www.courtlistener.com/opinion/1708299/', '1708299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, in Wilburn, we reversed an aggravated assault conviction because the information had not charged that the victim had been placed in fear by the defendant''s actions.', 'general', 'Chambers v. State', 'https://www.courtlistener.com/opinion/1708299/', '1708299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the tampering with evidence conviction.', 'general', 'Chambers v. State', 'https://www.courtlistener.com/opinion/1708299/', '1708299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Thomas, we affirmed a conviction for driving under the influence (DUI) with serious bodily injury, even though this offense was not a lesser-included offense of DUI manslaughter as charged in the information.', 'general', 'Chambers v. State', 'https://www.courtlistener.com/opinion/1708299/', '1708299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[7] Accordingly, under the holding in Ray, we affirm Mr.', 'general', 'Chambers v. State', 'https://www.courtlistener.com/opinion/1708299/', '1708299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we determine that the violations of the different conditions of bond are different in fact and there is no clear indication to rebut the presumption that the legislature intended multiple punishments, we hold that the two convictions are not multiplicitous.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that charging this defendant with multiple counts of bail jumping for violating separate terms of the same bond is not multiplicitous.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that charging this defendant with multiple counts of bail jumping for violating separate terms of the same bond is not multiplicitous.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record, we conclude that the count of bail jumping for consuming alcohol and the count of bail jumping for contact with Lain are not identical in fact.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record, we conclude that the count of bail jumping based on Anderson''s consuming alcohol and the count of bail jumping based on his contact with Lain are different in fact.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the different interests meant to be protected by the legislature, we conclude that separate punishments for violations of different conditions of bond is appropriate.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our analysis of the four factors statutory language, legislative history and context, the nature of the proscribed conduct, and the appropriateness of multiple punishmentswe conclude that there is no clear indication to overcome the *757 presumption that the legislature intended multiple punishments for violations of different conditions of the same bond.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals'' decision.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and uphold the circuit court''s entry of judgment for two convictions of bail jumping.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1710205/', '1710205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that even if the initial stop of the defendant exceeded the scope of the investigative search and thus amounted to a seizure, the officers had probable cause to do so.', 'probable_cause', 'Floyd v. City of Crystal Springs', 'https://www.courtlistener.com/opinion/1711298/', '1711298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with a harmless error analysis, we conclude that the failure to make a specific finding of good cause is harmless where good cause exists, its basis is found in the record, and its finding is implicit in the AL J''s ruling.', 'general', 'State Ex Rel. Simpson v. Schwarz', 'https://www.courtlistener.com/opinion/1711980/', '1711980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not determine, however, the contours of the good cause requirement, because we conclude that the test is always met when the evidence offered in lieu of an adverse witness''s live testimony would be admissible under the Wisconsin Rules of Evidence.', 'general', 'State Ex Rel. Simpson v. Schwarz', 'https://www.courtlistener.com/opinion/1711980/', '1711980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, because the testimony proffered by the State in this case would have been admissible under the Wisconsin Rules of Evidence, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the factors as a whole, we conclude that LeAnn''s statements possess sufficient circumstantial guarantees of trustworthiness to qualify under the residual hearsay exception.', 'general', 'State Ex Rel. Simpson v. Schwarz', 'https://www.courtlistener.com/opinion/1711980/', '1711980') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the search was reasonable;', 'general', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the charge as to malice was harmless error beyond a reasonable doubt.', 'general', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these two Code sections are simply inapplicable.', 'general', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 221 (1981), we held that the solicitor need not provide in writing a list of all the evidence he intends to use in aggravation.', 'general', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'of these jurors is examined in its entirety, we conclude that no bias or prejudice was shown against Gaskins in qualifying these two jurors.', 'general', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From a review of all of the participation alleged to be prejudicial cited by counsel, we conclude that the trial judge did not participate in the trial beyond that permitted by the precedent established in this State.', 'general', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From a reading of the whole charge, we find that the jury could not have been mislead about its duties and the applicable law.', 'general', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the penalty imposed is not disproportionate to the penalty imposed in other cases under the comparatively new death penalty statute.', 'general', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both the conviction and the death sentence.', 'sentencing', 'State v. Gaskins', 'https://www.courtlistener.com/opinion/1250523/', '1250523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a claim of repressed memory of past sexual abuse does not delay the accrual of a cause of action for non-incestuous sexual assault, regardless of the victim''s minority and the position of trust occupied by the alleged perpetrator.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we held that her claim was barred because she delayed too long after discovering the elements of her claim to file suit.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the discovery rule did not save plaintiff''s cause of action because she knew all of the elements of her underlying claim against the priest, at the latest, by the time their relationship ended.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court of appeals certified the following question: Does the discovery rule save an otherwise untimely, non-incestuous, sexual assault claim against the individual alleged perpetrator when the alleged victim was a minor, and the alleged perpetrator was a person in a position of trust vis-à-vis the child/victim? Applying the discovery rule to these cases, we conclude that the plaintiffs'' claims were not timely filed because each of the plaintiffs discovered, or in the exercise of *319 reaso...', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in each case, the circuit court properly held that the claims of each plaintiff are barred by the statute of limitations for minors, and therefore affirm.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[15] Thus, we conclude that these five plaintiffs knew at least the identity of the responsible defendant and the nature of their injury no later than the time of the last sexual assault.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that, as a matter of law, these plaintiffs'' claims accrued at the time of their last assaults, we recognize that the legislature has given them varying amounts of time to file their causes of action based upon their respective ages at the time of the assaults.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon those considerations, as a matter of law we conclude that it would be contrary to public policy, and would defeat the purposes of limitations statutes, to allow claims of repressed memory to invoke the discovery rule and to indefinitely toll the statutory limitations for these plaintiffs.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that in each case, the respective circuit courts properly held that the claims of each plaintiff are barred by statutes of limitations.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we concluded that Ms.', 'general', 'Doe v. Archdiocese of Milwaukee', 'https://www.courtlistener.com/opinion/1724137/', '1724137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the plain language of the statute, we hold that the First District was correct in its analysis and conclusion both as to intent requirements of section 828.', 'general', 'Reynolds v. State', 'https://www.courtlistener.com/opinion/1836903/', '1836903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances, and based on the nature of the offenses, we held that the Legislature intended guilty knowledge associated with the possession to be an element of both crimes and that the State must prove that a person in possession of the illicit items knew that they were in his or her possession.', 'general', 'Reynolds v. State', 'https://www.courtlistener.com/opinion/1836903/', '1836903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that section 828.', 'general', 'Reynolds v. State', 'https://www.courtlistener.com/opinion/1836903/', '1836903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because *312 extension of incarceration constitutes compulsion and because there was a real and appreciable risk that any admissions made by Henderson would be incriminating in a potential perjury prosecution, we hold that the Commissioner violated Henderson''s privilege against self-incrimination by extending his incarceration by 45 days for refusal to admit his crime in sex offender treatment.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Morrow, we held that a disciplinary sanction extending an inmate''s incarceration for refusing to admit his offense as part of sex offender treatment while his conviction was on direct appeal did not constitute "compulsion" for Fifth Amendment purposes.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "when Morrow received a 36-month sentence, those 36 months belonged presumptively to the state," and when the state deprived Morrow of an opportunity for earlier supervised release, such deprivation did not constitute a substantial penalty.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that extension of incarceration "represents a significant departure from the basic conditions of the inmate''s sentence," we held that a Minnesota inmate has a "protected liberty interest in his supervised release date that triggers a right to procedural due process before that date can be extended.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Carrillo we held that under the Minnesota sentencing scheme the extension of an inmate''s term of incarceration as a disciplinary sanction meets the Sandin test for a liberty interest because it is an atypical and significant hardship.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Morrow, we held that giving an inmate a choice between treatment and confinement for a larger portion of his sentence was not compulsion within the meaning of the Fifth Amendment.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying Sandin, we held that "any extension of an inmate''s period of imprisonment represents a significant departure from the basic conditions of the inmate''s sentence" and concluded that Carrillo had "a protected liberty interest in his supervised release date that triggers a right to procedural due process before that date can be extended.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that principle applies to cases in which the sentence has been fixed and the judgment of conviction has become final.', 'sentencing', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004) ("[A]pplying the vast sea of compulsion principles applied by the various opinions in McKune and the federal appellate decisions that followed, [we find that] the loss of good time credits imposed automatically and directly for plaintiff''s failure to give up his right to silence and participate in the [sex offender treatment] program, violate every single one of them.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse, because Henderson had testified at trial that he did not commit the crime and admission of the offense in treatment would therefore have exposed him to prosecution for perjury.', 'general', 'Johnson v. Fabian', 'https://www.courtlistener.com/opinion/1727305/', '1727305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Kimmelman v. Heather Downs Management Limited', 'https://www.courtlistener.com/opinion/1728672/', '1728672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that defendant lacks standing to raise the third party constitutional claims.', 'general', 'People v. Rocha', 'https://www.courtlistener.com/opinion/1757682/', '1757682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence concerning Murrell''s actions, while sufficient to allow an inference of pain, is so weak in that regard that a new trial is required.', 'general', 'Murrell v. State', 'https://www.courtlistener.com/opinion/1730870/', '1730870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that it did not and that the contempt, if any, was constructive contempt.', 'general', 'Murrell v. State', 'https://www.courtlistener.com/opinion/1730870/', '1730870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, "Under these facts, no reasonable juror could find the glass slivers were not used in `such a manner as to cause serious bodily harm.', 'general', 'Murrell v. State', 'https://www.courtlistener.com/opinion/1730870/', '1730870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is such that a new trial is warranted and that a lesser included instruction on resisting arrest should have been given.', 'general', 'Murrell v. State', 'https://www.courtlistener.com/opinion/1730870/', '1730870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[9] We conclude that the judge exercised sound discretion in determining that a manifest necessity existed for the declaration of a mistrial, and that there was no other alternative.', 'mistrial', 'Quinones v. State', 'https://www.courtlistener.com/opinion/1733579/', '1733579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As concerns counsel''s professional behavior, however, we conclude that failing to reveal the existence of the knife and his intent to introduce it into evidence raises a substantial likelihood that he violated the provisions of Rule 4-3.', 'general', 'Quinones v. State', 'https://www.courtlistener.com/opinion/1733579/', '1733579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that the conduct of attorney Alex Michaels in this case raises a substantial likelihood of numerous violations of the above mentioned rules and therefore refer him to the Florida Bar for disciplinary proceedings.', 'general', 'Quinones v. State', 'https://www.courtlistener.com/opinion/1733579/', '1733579') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'LAT v. State', 'https://www.courtlistener.com/opinion/1751021/', '1751021') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 318 (1995), wherein this court held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rule 33.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1755270/', '1755270') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the state of this testimony, in light of the jurors'' strong assertion that they could render a fair and just verdict, we hold that the trial court''s decision was reasonably based on the testimony as a whole and, thus, we will not disturb its decision.', 'general', 'Newsome v. State', 'https://www.courtlistener.com/opinion/1755342/', '1755342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we find that, while Mrs.', 'general', 'Newsome v. State', 'https://www.courtlistener.com/opinion/1755342/', '1755342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence was reasonably necessary to the state''s case, that it was not unduly and unfairly prejudicial, and that its probative value in explaining the statement of appellant concerning the victim and in establishing a motive for the crime outweighed any potential prejudice.', 'general', 'Newsome v. State', 'https://www.courtlistener.com/opinion/1755342/', '1755342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the facts and pleadings in this case, we find that the trial court abused its discretion when it imposed the sanction of dismissal.', 'dismissal', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/1759531/', '1759531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse.', 'general', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/1759531/', '1759531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of dismissal and remand for further proceedings.', 'dismissal', 'State v. Carpenter', 'https://www.courtlistener.com/opinion/1759531/', '1759531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the State’s appeal we reverse the trial court and remand the case for further proceedings.', 'general', 'State v. Bauer', 'https://www.courtlistener.com/opinion/1760482/', '1760482') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the dismissal of the prosecution.', 'dismissal', 'State v. Bauer', 'https://www.courtlistener.com/opinion/1760482/', '1760482') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not.', 'general', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we hold that, while neither party disputes the existence of probable cause to effect the arrest, sufficient exigent circumstances did not exist to overcome the strong presumption that warrantless home arrests are unreasonable.', 'probable_cause', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the totality of the circumstances involved in the case at bar, we hold that, as in Patzner, Ms.', 'general', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the above-stated reasons, we hold that the State has failed to prove that the warrantless activity at issue in this case was reasonable based upon the totality of the circumstances, and hereby reverse and dismiss the case.', 'dismissal', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and, for the following reasons, we reverse the trial court and dismiss the case.', 'dismissal', 'Norris v. State', 'https://www.courtlistener.com/opinion/1763389/', '1763389') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we held that imposing a 1-year license revocation from the time the defendant''s probation was revoked violated the plain language of the statute mandating that the license revocation run "`from the date of his or her conviction.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1764855/', '1764855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion in denying probation, especially given the level of flexibility offered by the court in serving the jail time imposed.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1764855/', '1764855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''"[15] We concluded that the State''s concernthat such construction left little incentive not to violate the probationwas a concern "to be addressed by the Legislature rather than by this court.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1764855/', '1764855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the district court.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1764855/', '1764855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the constitutional prohibition against double *1065 jeopardy applied and that the State had no right to try the defendant at all.', 'general', 'Lippman v. State', 'https://www.courtlistener.com/opinion/1766399/', '1766399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the proscription against minor sibling contact is fairly viewed as a modification of an existing probation condition rather than the imposition of a new condition.', 'general', 'Lippman v. State', 'https://www.courtlistener.com/opinion/1766399/', '1766399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the added conditions, including the no-contact condition, enhanced the terms of Lippman''s original probationary sentence.', 'sentencing', 'Lippman v. State', 'https://www.courtlistener.com/opinion/1766399/', '1766399') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that attempted first-degree murder, felony causing bodily injury, and aggravated battery causing great bodily harm constitute separate offenses under Blockburger and are not "degree variants" of the same underlying offense.', 'general', 'Gordon v. State', 'https://www.courtlistener.com/opinion/1768658/', '1768658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), where we held that dual convictions for UBAL (unlawful blood alcohol level) manslaughter and vehicular homicide arising out of one death violated the Double Jeopardy Clause.', 'general', 'Gordon v. State', 'https://www.courtlistener.com/opinion/1768658/', '1768658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), we held that the double jeopardy clause prohibited multiple convictions for perjury in an official proceeding and providing false information in an application for bail when the charges arose out of a single act.', 'general', 'Gordon v. State', 'https://www.courtlistener.com/opinion/1768658/', '1768658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Carawan, we held that dual convictions for aggravated battery and attempted manslaughter arising out of the same act constituted double jeopardy.', 'general', 'Gordon v. State', 'https://www.courtlistener.com/opinion/1768658/', '1768658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984), this Court held that attempted felony murder was a crime in Florida.', 'general', 'Gordon v. State', 'https://www.courtlistener.com/opinion/1768658/', '1768658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the value of the goods or the taking of a firearm merely defined the degree of the felony and did not constitute *21 separate crimes.', 'general', 'Gordon v. State', 'https://www.courtlistener.com/opinion/1768658/', '1768658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that these two offenses were "aggravated forms of a single underlying offense distinguished only by degree factors.', 'general', 'Gordon v. State', 'https://www.courtlistener.com/opinion/1768658/', '1768658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "[b]oth statutes punish the same basic crime (i.', 'general', 'Gordon v. State', 'https://www.courtlistener.com/opinion/1768658/', '1768658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on all points.', 'general', 'Canto v. JB Ivey and Co.', 'https://www.courtlistener.com/opinion/1770120/', '1770120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the error, we affirm the trial court''s decision on other grounds.', 'general', 'Canto v. JB Ivey and Co.', 'https://www.courtlistener.com/opinion/1770120/', '1770120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because appellants have failed to provide an adequate record to permit this court to determine whether the trial court''s directed verdict was erroneous, we affirm the judgment entered on the directed verdict against appellants as to count II.', 'general', 'Canto v. JB Ivey and Co.', 'https://www.courtlistener.com/opinion/1770120/', '1770120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the directed verdict entered against appellants on counts IV and V.', 'general', 'Canto v. JB Ivey and Co.', 'https://www.courtlistener.com/opinion/1770120/', '1770120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987), this Court held that all questions regarding the sufficiency of indictments are determinable by reference to Rule 2.', 'general', 'Nguyen v. State', 'https://www.courtlistener.com/opinion/1770567/', '1770567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 272, 273 (1951), this Court held that an indictment describing the property stolen as "a certain diamond ring" was legally sufficient.', 'general', 'Nguyen v. State', 'https://www.courtlistener.com/opinion/1770567/', '1770567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As in Foster, once again we hold that although the Mississippi statutory scheme does in fact lack age specificity, there is a very strong statutory inference that the *364 death penalty cannot be imposed on an individual who is under thirteen years of age.', 'general', 'Puckett v. State', 'https://www.courtlistener.com/opinion/1771774/', '1771774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, this Court held "[w]here, .', 'general', 'Puckett v. State', 'https://www.courtlistener.com/opinion/1771774/', '1771774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, on the other hand, in Marks v.', 'general', 'Puckett v. State', 'https://www.courtlistener.com/opinion/1771774/', '1771774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), this Court held "[t]he circuit court correctly found that the 911 call was admissible under either the present sense impression or excited utterance exceptions to the rule against hearsay.', 'general', 'Puckett v. State', 'https://www.courtlistener.com/opinion/1771774/', '1771774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Unless we conclude that the discretion was arbitrary and clearly erroneous, amounting to an abuse of discretion, that decision will stand.', 'general', 'Puckett v. State', 'https://www.courtlistener.com/opinion/1771774/', '1771774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Recognizing that the proper degree of definition of an aggravating factor of this nature is not susceptible of mathematical precision, we conclude that the definition given to the `especially cruel'' provision by the Arizona Supreme Court is constitutionally sufficient because it gives meaningful guidance to the sentencer.', 'sentencing', 'Puckett v. State', 'https://www.courtlistener.com/opinion/1771774/', '1771774') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the New Jersey court''s logic and course of action is well-founded, and that it recognizes and accommodates the competing concerns and interests presented in this case.', 'general', 'Department of Revenue v. Jackson', 'https://www.courtlistener.com/opinion/1772446/', '1772446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the more just approach is to hold the petition to modify in abeyance until a time when a thorough evaluation of the obligor''s ability to pay may be conducted, and a farsighted plan for payment may be established.', 'general', 'Department of Revenue v. Jackson', 'https://www.courtlistener.com/opinion/1772446/', '1772446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the result attained by the New Jersey Superior Court in Halliwell v.', 'general', 'Department of Revenue v. Jackson', 'https://www.courtlistener.com/opinion/1772446/', '1772446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that incarceration, standing alone, does not warrant a finding of change of circumstances.', 'general', 'Department of Revenue v. Jackson', 'https://www.courtlistener.com/opinion/1772446/', '1772446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that those judges who properly complete the educational program, including examinations to test their proficiency, may preside over criminal misdemeanor cases as described above.', 'general', 'Treiman v. State Ex Rel. Miner', 'https://www.courtlistener.com/opinion/1775214/', '1775214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on careful scrutiny of the materials synopsized in the appendices, we conclude that a nonlawyer county judge who completes the Non-Lawyer County Judge Training Program at the University of Florida can constitutionally[2] sentence a defendant to a *824 prison term for commission of a misdemeanor as specified in Section 775.', 'sentencing', 'Treiman v. State Ex Rel. Miner', 'https://www.courtlistener.com/opinion/1775214/', '1775214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the circuit court erroneously excluded evidence and denied a defense instruction with respect to Knight''s justification for leaving when he did, we reverse.', 'general', 'Knight v. State', 'https://www.courtlistener.com/opinion/1776235/', '1776235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons we reverse and remand this matter to the circuit court.', 'general', 'Knight v. State', 'https://www.courtlistener.com/opinion/1776235/', '1776235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court incorrectly emphasized the economic and social disadvantages of respondent-parents as factors that excused or outweighed in significance the essentially uncontradicted showing of serious harm suffered by the children as a result of a lack of nurturing care in the home.', 'general', 'New Jersey Division of Youth & Family Services v. A.W.', 'https://www.courtlistener.com/opinion/1927603/', '1927603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that plain error is determined at the time of appellate review.', 'general', 'State of Minnesota v. Dylan Micheal Kelley', 'https://www.courtlistener.com/opinion/2744713/', '2744713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that for purposes of applying the plain-error doctrine the court examines the law in existence at the time of appellate review, not the law in existence at the time of.', 'general', 'State of Minnesota v. Dylan Micheal Kelley', 'https://www.courtlistener.com/opinion/2744713/', '2744713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that the arguments asserted by the concurrence lack merit.', 'general', 'State of Minnesota v. Dylan Micheal Kelley', 'https://www.courtlistener.com/opinion/2744713/', '2744713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that an accomplice liability instruction must explain that the intentionally aiding element requires that the jury find beyond a reasonable doubt that the defendant knew his alleged accomplice was going to commit a crime and the defendant intended his presence or actions to further the commission of that crime.', 'general', 'State of Minnesota v. Dylan Micheal Kelley', 'https://www.courtlistener.com/opinion/2744713/', '2744713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 Be*276cause we reversed the conviction based on plain error, our discussion of each prong of the plain-error doctrine was essential to our decision, and therefore not dicta.', 'general', 'State of Minnesota v. Dylan Micheal Kelley', 'https://www.courtlistener.com/opinion/2744713/', '2744713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 Nevertheless, because the error alleged in this case did not affect Kelley’s substantial rights, we affirm as modified.', 'general', 'State of Minnesota v. Dylan Micheal Kelley', 'https://www.courtlistener.com/opinion/2744713/', '2744713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we affirmed the district court’s denial of postconviction relief based on the third prong of the plain-error doctrine, which requires a showing that the alleged error affected the defendant’s substantial rights.', 'general', 'State of Minnesota v. Dylan Micheal Kelley', 'https://www.courtlistener.com/opinion/2744713/', '2744713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ramey, for instance, we held that, in cases involving prosecutorial misconduct, the State bears the burden of persuasion to disprove an effect on a defendant’s substantial rights under the plain-error standard, even though the approach we adopted was inconsistent with Supreme Court case law.', 'general', 'State of Minnesota v. Dylan Micheal Kelley', 'https://www.courtlistener.com/opinion/2744713/', '2744713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial courts of this state have the general authority to require incarceration as a condition of probation for felony and misdemeanor offenses pursuant to the general condition provisions of Section 948.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1790839/', '1790839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that prior to July 1, 1974, the provisions of Section 948.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1790839/', '1790839') ON CONFLICT DO NOTHING;
