INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that (I) the trial court did not abuse its discretion in summarily denying the defendant''s public records claim or in concluding that all but one of the public records the State did not disclose to the defendant are either exempt from disclosure or not relevant;', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), we hold that Ring does not apply retroactively in Florida to defendants whose convictions already were final when that decision was rendered.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998), we held that where doubt exists as to whether the State must disclose allegedly exempt documents, the trial court should first review the documents in camera.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Deferring to the United States Supreme Court''s assessment of its own decision in Ring, we conclude that the purpose of the new rule does not support retroactivity.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the three Witt factors, separately and together, weigh against the retroactive application of Ring in Florida.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After receiving a supplemental transcript, we affirmed the conviction and sentence.', 'sentencing', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, we affirmed.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the defendant "did not proffer or assert the existence of any evidence that such notes existed and were improperly being withheld," we affirmed the denial of relief.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1791862/', '1791862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a felony conviction for driving under a suspended license in violation of § 60-6,196(6) may not be used either to trigger application of the habitual criminal statute or as a prior offense for purposes of penalty enhancement pursuant thereto.', 'general', 'State v. Hittle', 'https://www.courtlistener.com/opinion/1793858/', '1793858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Expressing a reluctance “to apply an expansive reading to the Habitual Criminal Act,” we held that “offenses which are felonies because the defendant has been previously convicted of the same crime do not constitute ‘felonies’ within the meaning of prior felonies that enhance penalties under the habitual criminal statute.', 'general', 'State v. Hittle', 'https://www.courtlistener.com/opinion/1793858/', '1793858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under this standard, the evidence is sufficient to establish that Hittle committed the charged offenses on February 21, 1998, and the trial court did not err in overruling his motions to dismiss and for a directed verdict.', 'dismissal', 'State v. Hittle', 'https://www.courtlistener.com/opinion/1793858/', '1793858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the specific penalty for third and subsequent offenses as set forth in the DUI statute “exempts offenders such
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both convictions, but conclude that Hittle was improperly sentenced as a habitual criminal and therefore vacate the sentences imposed and remand the cause to the district court for resentencing.', 'sentencing', 'State v. Hittle', 'https://www.courtlistener.com/opinion/1793858/', '1793858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1054 (1991), we held that the sellers of obscene materials had vicarious standing to raise the privacy rights of their customers.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1797530/', '1797530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), in which we held that the right to privacy encompasses a minor''s right to terminate a *1087 pregnancy.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1797530/', '1797530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984), this court held that the defendant''s confession was not involuntarily made merely because he was in pain as a result of a gunshot wound at the time that he made his confession.', 'general', 'Holladay v. State', 'https://www.courtlistener.com/opinion/1799369/', '1799369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After our review of the defense''s exhibits relating to this issue and the testimony adduced at the hearing on this question, we conclude that the publicity in this case was factual and objective.', 'general', 'Holladay v. State', 'https://www.courtlistener.com/opinion/1799369/', '1799369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no reasonable theory under the evidence presented at this trial which could have justified a conviction of this appellant for intentional murder.', 'general', 'Holladay v. State', 'https://www.courtlistener.com/opinion/1799369/', '1799369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the appellant''s sentence of death was not imposed under the influence of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Holladay v. State', 'https://www.courtlistener.com/opinion/1799369/', '1799369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that to be guilty of driving or operating a motor vehicle while under the influence of drugs or alcohol, or with an illegally high blood alcohol content, the person must be shown by direct proof or reasonable inferences to have driven the vehicle while in that condition, or as in Jones [v.', 'general', 'Kramm v. State', 'https://www.courtlistener.com/opinion/1800667/', '1800667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the guidance provided in Holloway and Lewis, we conclude that the State is not required to provide eyewitness evidence that Kramm was the driver of the SUV at the time of the accident as long as it provides sufficient proof supporting a reasonable inference that the defendant was driving the vehicle.', 'general', 'Kramm v. State', 'https://www.courtlistener.com/opinion/1800667/', '1800667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Sitting as the *25 "thirteenth juror," we find that the evidence and testimony, weighed in the light most favorable to the verdict, support the jury''s conviction.', 'general', 'Kramm v. State', 'https://www.courtlistener.com/opinion/1800667/', '1800667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not abuse its discretion in overruling Kramm''s motion for a new trial.', 'general', 'Kramm v. State', 'https://www.courtlistener.com/opinion/1800667/', '1800667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'bar a retrial of the defendant as to the originally charged offense of attempted second degree murder? We hold that the double jeopardy clause of the Hawai''i Constitution does.', 'general', 'State v. Quitog', 'https://www.courtlistener.com/opinion/2606360/', '2606360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it would.', 'general', 'State v. Quitog', 'https://www.courtlistener.com/opinion/2606360/', '2606360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that principles of double jeopardy,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'court with respect to the federal double jeopardy clause, we hold that article I, section 10 of the Hawai''i Constitution “bars retrial for [a] charge when the government’s deliberate trial strategy”—which is completely incompatible with another approach that it could have pursued, but expressly chose not to—accompanies the termination of “the first trial .', 'general', 'State v. Quitog', 'https://www.courtlistener.com/opinion/2606360/', '2606360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Quitog’s "bad faith” argument is without merit.', 'general', 'State v. Quitog', 'https://www.courtlistener.com/opinion/2606360/', '2606360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that double jeopardy bars retrial under these circumstances.', 'general', 'State v. Quitog', 'https://www.courtlistener.com/opinion/2606360/', '2606360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the government at trial abandoned any theory that there were two separate and distinct criminal acts
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the record before us, however, we cannot say that the trial court’s declaration of a mistrial based on manifest necessity constituted an abuse of discretion, and we therefore hold that it did not.', 'mistrial', 'State v. Quitog', 'https://www.courtlistener.com/opinion/2606360/', '2606360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that article I, section 10 does not foreclose the prosecution from retrying Quitog for any lesser offenses included within attempted second degree murder, as charged in Count I.', 'general', 'State v. Quitog', 'https://www.courtlistener.com/opinion/2606360/', '2606360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that to read the statute as a coherent whole requires that stalking be a specific intent crime.', 'general', 'State v. Orsello', 'https://www.courtlistener.com/opinion/1928583/', '1928583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1979), where this court held that the legislature could criminalize an act without mention of a required intent level and thereby create a general intent crime.', 'general', 'State v. Orsello', 'https://www.courtlistener.com/opinion/1928583/', '1928583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that conviction under the statute requires proof of specific intent and therefore reverse.', 'general', 'State v. Orsello', 'https://www.courtlistener.com/opinion/1928583/', '1928583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because of the peculiar drafting of the statute, we conclude that our analysis must go further.', 'general', 'State v. Orsello', 'https://www.courtlistener.com/opinion/1928583/', '1928583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we hold that the trial court improperly based its decision to revoke solely on documentary evidence, which in the present case we find to be insufficient proof of the criminal activity in which the defendant is alleged to have participated.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/1812660/', '1812660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that the procedure by which the petitioner''s probation was revoked warrants reversal (see text of this opinion), we are unable to say that criminal violations complained of, if properly proven, do not warrant the drastic remedy of revocation.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/1812660/', '1812660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, like the First District, we do not decide this timeliness issue because we hold that the defendant''s motion was properly denied on its merits.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), we held that the defendant''s consent was given voluntarily where the law enforcement officer "truthfully informed Peterka of the different degrees of homicide and that law enforcement was seeking to charge him with first-degree murder" and the record showed that the officer "made no promises of leniency in return for any statements, did not threaten Peterka, and did not use *31 violence to induce the statements.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2003), we held that when a detective exaggerated the amount of DNA evidence against the defendant, the defendant''s confession was still voluntary because "police misrepresentations alone do not necessarily render a confession involuntary.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, when examined under the totality of the circumstances, we held that the confession was not rendered involuntary.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the deception was minimal because the police had a preliminary match between blood taken from the defendant and DNA evidence collected at the murders, and the defendant had voluntarily given his blood sample within a couple of hours of his arrest.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '") We find that Wyche''s consent was "the product of an essentially free and unconstrained choice by its maker.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there are circumstances in McCord upon which that court could have determined under the totality of the circumstances that McCord''s consent was coerced.', 'general', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), we affirmed the trial court''s denial of a motion to suppress a confession where "police detectives deluded [the defendant] before he gave his statements by falsely stating that they had obtained physical evidence and by failing to inform him that he could be sentenced to death.', 'suppression', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001), we affirmed the trial court''s denial of the defendant''s motion to suppress his confession where "police detectives deluded him before he gave his statements by falsely stating that they had obtained physical evidence and by failing to inform him that he could be sentenced to death.', 'suppression', 'Wyche v. State', 'https://www.courtlistener.com/opinion/1813641/', '1813641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Alternatively, assuming arguendo, this Court holds that subsequent offenses are admitted under the "other crimes" exception set forth in 404(b), appellant contends there is a further crucial consideration to which the trial court did not adhere in this case.', 'general', 'Ford v. State', 'https://www.courtlistener.com/opinion/1817285/', '1817285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Ford v. State', 'https://www.courtlistener.com/opinion/1817285/', '1817285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, having carefully considered the record and briefs filed herein, we affirm appellant''s conviction of grand larceny as an habitual offender and sentence of five years  not to be reduced or suspended, nor afforded eligibility for parole, probation, earned or good time, nor any other administrative reduction of time or early release  to run consecutively to that sentence imposed as a result of appellant''s conviction of conspiracy in Count One.', 'sentencing', 'Ford v. State', 'https://www.courtlistener.com/opinion/1817285/', '1817285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that the jury instructions requiring the state to prove beyond a reasonable doubt that the defendant had engaged in a “past pattern of domestic abuse” adequately set forth the law governing the domestic abuse homicide charge against Cross.', 'jury_instruction', 'State v. Cross', 'https://www.courtlistener.com/opinion/1816990/', '1816990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Cross', 'https://www.courtlistener.com/opinion/1816990/', '1816990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of any error, we affirm the convictions.', 'general', 'State v. Cross', 'https://www.courtlistener.com/opinion/1816990/', '1816990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*456 In summary, we hold that because the stipulated facts establish that there is no allegation that Colvin committed or intended to commit a crime other than the OFP violation, and because the district court specifically found that Colvin''s OFP violation was a violation of the prohibition against entry onto his ex-wife''s residence, Colvin''s unconsented entry in violation of the OFP cannot be the basis for a burglary charge.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Larson, this court held that trespass cannot serve as the crime committed or intended to be committed to establish burglary.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the district court found that Colvin violated the no-entry provision of the OFP, but made no other finding of additional OFP violations, we conclude that Colvin was not charged with violation of the no-contact provision of the OFP.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" The dissent erroneously states that we conclude that Colvin''s sole intent was to enter the home.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that violation of a no-entry provision of an OFP, like trespass, is excluded from the crimes that can be the bases for the independent crime element of burglary.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] But we conclude that the same entry is insufficient to satisfy both the illegal entry element of the burglary statute and the independent-crime requirement.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Colvin', 'https://www.courtlistener.com/opinion/1818384/', '1818384') ON CONFLICT DO NOTHING;
