INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the record, we conclude that the September 18 hearing was a continuing part of the initial habeas corpus proceeding.', 'habeas', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
