INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"IT IS HEREBY ORDERED AND THIS DOES ORDER that the Order of Contempt entered by this Court on September 19, 1980, be modified to provide that the witness, Ellen Marks, shall pay the sum of FIVE HUNDRED &amp;', 'general', 'Marks v. Vehlow', 'https://www.courtlistener.com/opinion/2605279/', '2605279') ON CONFLICT DO NOTHING;
