INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the lower court correctly refused to grant instruction D-3.', 'general', 'Hurns v. State', 'https://www.courtlistener.com/opinion/1824880/', '1824880') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Sudduth, this Court held that photographs of a murder victim should not ordinarily be admitted where the "killing is not contradicted or denied, and the corpus delicti and identity of victim have been established.', 'general', 'Hurns v. State', 'https://www.courtlistener.com/opinion/1824880/', '1824880') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence was admissible under Rule 404(b) to relate the complete story of the crime by showing that Hurns had total domination over all the inmates in the facility.', 'general', 'Hurns v. State', 'https://www.courtlistener.com/opinion/1824880/', '1824880') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that factor to have been properly considered.', 'general', 'People v. Adams', 'https://www.courtlistener.com/opinion/1827757/', '1827757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decisions of the Court of Appeals.', 'general', 'People v. Adams', 'https://www.courtlistener.com/opinion/1827757/', '1827757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "[a]s a general rule, a successor judge is precluded from correcting errors of law made by his predecessor or changing the latter''s judgment or order on the merits, but this rule does not apply where the order or judgment is not of a final character.', 'general', 'Byrom v. State', 'https://www.courtlistener.com/opinion/1831507/', '1831507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Judge Yerger, as the successor judge, could not void and vacate Judge Coleman''s order.', 'general', 'Byrom v. State', 'https://www.courtlistener.com/opinion/1831507/', '1831507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1973), wherein this Court held that "before interrogating a suspect in custody, the State or its representatives must tell the suspect of his right not to speak without counsel.', 'general', 'Byrom v. State', 'https://www.courtlistener.com/opinion/1831507/', '1831507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, this is similar to Holifield, wherein this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), where this Court held, "[w]e have repeatedly condemned the practice whereby law enforcement interrogators, or related third parties, convey to suspects the impression, however slight, that cooperation by the suspect might be of some benefit.', 'general', 'Byrom v. State', 'https://www.courtlistener.com/opinion/1831507/', '1831507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2000), where this Court held a conspiracy indictment to be sufficient where the time period of the conspiracy was stated, four of the alleged co-conspirators were named, and the offense was clearly described.', 'general', 'Byrom v. State', 'https://www.courtlistener.com/opinion/1831507/', '1831507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the indictment was insufficient to place the defendant on notice of the charges against him.', 'general', 'Byrom v. State', 'https://www.courtlistener.com/opinion/1831507/', '1831507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the letters in question "outlined the Defendant''s substantive theory of the case," this Court held that, pursuant to the then-existing uniform circuit court rule 4.', 'general', 'Byrom v. State', 'https://www.courtlistener.com/opinion/1831507/', '1831507') ON CONFLICT DO NOTHING;
