INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984), wherein this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm because we agree with the State that the trial court''s jury instructions were consistent with the rulings in Brown.', 'jury_instruction', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1836607/', '1836607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the search of Andrea Wynne''s purse cannot be justified as incident to a lawful arrest.', 'general', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the search of Wynne''s purse constituted a search of her person and did not fall within the ambit of the premises search warrant.', 'general', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a sufficient nexus does not exist in the current situation.', 'general', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Andrea Wynne''s status as the daughter of Joy Wynne, living in the elder''s home where drugs were found was not enough to form the basis for probable cause to arrest Andrea Wynne.', 'probable_cause', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case we conclude that the search of Andrea Wynne''s purse violated her constitutional rights.', 'general', 'State v. Wynne', 'https://www.courtlistener.com/opinion/1840594/', '1840594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Bell definition of double jeopardy, we conclude that McGee was proven to have committed only one offense under a single statute and his convictions and sentences on six counts of the information must be reversed and vacated.', 'sentencing', 'McGee v. State', 'https://www.courtlistener.com/opinion/1841007/', '1841007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'McGee v. State', 'https://www.courtlistener.com/opinion/1841007/', '1841007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed in this opinion, we hold that incarceration, pursuant to the split sentence alternatives found in sections 948.', 'sentencing', 'Villery v. Florida Parole & Probation Com''n', 'https://www.courtlistener.com/opinion/1841481/', '1841481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1978), we held that the combined period of incarceration and probation imposed under the split sentence alternative must be within the maximum period of incarceration provided by the particular criminal statute for the offense involved.', 'sentencing', 'Villery v. Florida Parole & Probation Com''n', 'https://www.courtlistener.com/opinion/1841481/', '1841481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statute is valid as against all of appellant''s challenges, and that the state''s evidence was sufficient to demonstrate his violation of the statute.', 'general', 'Cashatt v. State', 'https://www.courtlistener.com/opinion/1844411/', '1844411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that even if section 847.', 'general', 'Cashatt v. State', 'https://www.courtlistener.com/opinion/1844411/', '1844411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the state''s traverse adequately demonstrated a material dispute of the ultimate facts, and that the Internet communications alone constituted a prima facie case of guilt under section 847.', 'general', 'Cashatt v. State', 'https://www.courtlistener.com/opinion/1844411/', '1844411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming without deciding that it was error for Hubbard’s counsel to fail to object to this testimony, we conclude that there was no prejudice.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1850441/', '1850441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Hubbard', 'https://www.courtlistener.com/opinion/1850441/', '1850441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As developed below, we hold that (1) the jury may have convicted Major solely for the possession which occurred on the reservation, and (2) the state lacked jurisdiction over this crime inside the reservation.', 'general', 'State v. Major', 'https://www.courtlistener.com/opinion/2616070/', '2616070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the tribal resolution did not grant consent over a class of offenses which included grand theft by possession of stolen property.', 'general', 'State v. Major', 'https://www.courtlistener.com/opinion/2616070/', '2616070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the above discussion indicates, neither do we conclude that the crime of grand theft by possession of stolen property found in I.', 'general', 'State v. Major', 'https://www.courtlistener.com/opinion/2616070/', '2616070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that 18 U.', 'general', 'State v. Major', 'https://www.courtlistener.com/opinion/2616070/', '2616070') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the warrant was defective because of insufficient probable cause.', 'probable_cause', 'Arbitration Between Minnesota State Patrol Troopers Ass''n Ex Rel. Pince v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/1855920/', '1855920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the search warrant lacked probable cause and we decline to adopt a good-faith exception, we hold that the evidence seized in the search should have been suppressed at the arbitration hearing.', 'suppression', 'Arbitration Between Minnesota State Patrol Troopers Ass''n Ex Rel. Pince v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/1855920/', '1855920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the arbitration award.', 'general', 'Arbitration Between Minnesota State Patrol Troopers Ass''n Ex Rel. Pince v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/1855920/', '1855920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find ample support in the record for Pince''s discharge from the Patrol, we affirm the trial court on that basis and because of the severe limitation on our authority imposed by statute.', 'general', 'Arbitration Between Minnesota State Patrol Troopers Ass''n Ex Rel. Pince v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/1855920/', '1855920') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because the Lorcet tablets in this case contain less than fifteen milligrams of hydrocodone per dosage unit, the Lorcet tablets Hayes possessed are Schedule III substances.', 'general', 'Hayes v. State', 'https://www.courtlistener.com/opinion/1856114/', '1856114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, after considering these interrelated statutes in pari materia, as we are required to do, we conclude that the interpretation given to the trafficking statute and to the statutory provisions of Schedules II and III by the First and Second Districts is most consistent with a strict construction of the applicable statutes.', 'general', 'Hayes v. State', 'https://www.courtlistener.com/opinion/1856114/', '1856114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', specially concurring), we find that a "strict construction" of these criminal statutes, as is mandated by section 775.', 'general', 'Hayes v. State', 'https://www.courtlistener.com/opinion/1856114/', '1856114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), we held that the accused was entitled to such an instruction when he had good reason to fear his life had been threatened.', 'general', 'Duvall v. State', 'https://www.courtlistener.com/opinion/1858990/', '1858990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the erroneous refusal of a requested defense instruction, and the erroneous granting of a requested instruction for the State, we reverse.', 'general', 'Duvall v. State', 'https://www.courtlistener.com/opinion/1858990/', '1858990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[22] We hold that the district court''s failure to bind over on charges of second-degree murder was an abuse of discretion.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Goecke, we hold that there was sufficient evidence to bind the defendant *881 over on charges of second-degree murder under either a subjective or objective standard.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated by the dissenting judge in the Court of Appeals in Baker,[32] we hold that the evidence was sufficient to permit a reasonable jury to infer malice under either a subjective or objective standard.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because evidence of drunkenness is not a defense to second-degree murder, we hold that, under either standard, sufficient circumstantial evidence exists in Baker, and sufficient circumstantial and direct evidence exists in Goecke and Hoskinson, to support the bindovers and convictions of these defendants.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As early as 1874, this Court held that, to be convicted of murder, an accused must have an intent the "equivalent in legal character to a criminal purpose aimed against life.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecution may seek review of the magistrate''s findings under these circumstances by filing a motion to amend the information and that the circuit court does not have discretion to deny review on the ground that the prosecution was required to file an application for leave to appeal.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Baker and Hoskinson, we find that the evidence supported the juries'' findings of guilt.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 656 (1996), we found that the OUIL, causing death, statute was not enacted to codify the common law.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Goecke, we reverse the decision of the Court of Appeals.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and remand to the trial court for reinstatement of defendant''s second-degree murder conviction and sentence.', 'sentencing', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
