INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we concluded that the police cruiser''s slow following of the defendant did not convey the message that he was not free to disregard the police and go about his business.', 'general', 'State v. Young', 'https://www.courtlistener.com/opinion/1867862/', '1867862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, the officer lawfully seized Young, and we affirm Young''s convictions on all three counts.', 'general', 'State v. Young', 'https://www.courtlistener.com/opinion/1867862/', '1867862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have examined all the evidence impartially, and giving due deference to the jury’s verdict, we conclude that the verdict is not so contrary to the overwhelming weight of the evidence as to be clearly wrong and unjust.', 'general', 'Roise v. State', 'https://www.courtlistener.com/opinion/1870192/', '1870192') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the record as a whole, we conclude that Dr.', 'general', 'Roise v. State', 'https://www.courtlistener.com/opinion/1870192/', '1870192') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that the trial court did follow the correct legal standards to determine the admissibility of the contents of Cox'' confession to the officers and that there was substantial evidence to support his finding of voluntariness.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/1873849/', '1873849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In DeBussi, this Court held that re-prosecution of an habitual offender was barred where there was not sufficient evidence to support a conviction apart from the evidence erroneously admitted by the trial judge.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/1873849/', '1873849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that there was insufficient evidence to support Ishola''s conviction.', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/1560118/', '1560118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the term "another," as it is used in § 8-301(c), is ambiguous, the rule of strict construction requires that we resolve that ambiguity against the State and in favor of Ishola.', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/1560118/', '1560118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the evidence presented at trial was insufficient to sustain Ishola''s convictions under § 8-301(c).', 'general', 'Ishola v. State', 'https://www.courtlistener.com/opinion/1560118/', '1560118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that appellant’s statement was not, under the circumstances presented here, a clear request for counsel.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1890892/', '1890892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant’s contention was contrary to longstanding Texas law that was
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was ample support in the record for concluding that the prosecutor had race-neutral reasons for exercising the strike, we conclude that the trial court’s ruling was not clearly erroneous.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1890892/', '1890892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all factors, we conclude that the trial court did not abuse its discretion in determining that the probative value of the photograph was not substantially outweighed by its prejudicial effect.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1890892/', '1890892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court would not have abused its discretion if it had found that Detective Sanchez possessed sufficient expertise to give an expert opinion, based on his experience as a police officer and a homicide detective, regarding whether the wounds suffered by the cat could have been inflicted by the same knife that killed the victim.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1890892/', '1890892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that respect, we conclude that appellant is mistaken.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1890892/', '1890892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if we found that appellant had lodged a sufficient objection at trial, he has failed to present us with any reason to find the expert testimony to be inadmissible.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1890892/', '1890892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the trial court’s judgment and sentence of death.', 'sentencing', 'Davis v. State', 'https://www.courtlistener.com/opinion/1890892/', '1890892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1890892/', '1890892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that for improper vouching to constitute plain error: (1) credibility must be a central issue in a close case;', 'general', 'Trump v. State', 'https://www.courtlistener.com/opinion/1891330/', '1891330') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that it was appropriate for the purpose of showing intent and absence of mistake by the defendant for the trial court to allow the prosecution to present evidence that the defendant committed other improper sexual acts with the victim four years before he allegedly committed the sexual assault for
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not commit plain error by admitting the evidence under Delaware Rules of Evidence (D.', 'general', 'Trump v. State', 'https://www.courtlistener.com/opinion/1891330/', '1891330') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in deciding that the statute proscribing soliciting for prostitution is unconstitutional for its allegedly impermissible infringement of appellees’ rights to privacy.', 'general', 'United States v. Moses', 'https://www.courtlistener.com/opinion/1893603/', '1893603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not involve ourselves in this judgmental dispute (which properly is the function of the legislature), for we conclude that appellees’ alleged offers to perform sexual intercourse for a price are not within the bounds of First Amendment protection.', 'general', 'United States v. Moses', 'https://www.courtlistener.com/opinion/1893603/', '1893603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a solicitation for prostitution is not entitled to immunity under the First Amendment.', 'general', 'United States v. Moses', 'https://www.courtlistener.com/opinion/1893603/', '1893603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a would-be prostitute constitutionally may be forbidden to solicit customers, and that a would-be customer similarly may be forbidden to solicit a person to engage in prostitution.', 'general', 'United States v. Moses', 'https://www.courtlistener.com/opinion/1893603/', '1893603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'United States v. Moses', 'https://www.courtlistener.com/opinion/1893603/', '1893603') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the conflicting decisions and the relevant statutes, we hold that the plain language of section 400.', 'general', 'Florida Convalescent Centers v. Somberg', 'https://www.courtlistener.com/opinion/1894271/', '1894271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that based on the plain language of section 400.', 'general', 'Florida Convalescent Centers v. Somberg', 'https://www.courtlistener.com/opinion/1894271/', '1894271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '643(2), we find that the legislative history underlying those statutory subsections supports our conclusion regarding their relationship.', 'general', 'Florida Convalescent Centers v. Somberg', 'https://www.courtlistener.com/opinion/1894271/', '1894271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997) ("Accordingly, we find that the legislative history, like the plain language of section 817.', 'general', 'Florida Convalescent Centers v. Somberg', 'https://www.courtlistener.com/opinion/1894271/', '1894271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Observing that with respect to the specific factual situation in that case, the conviction for unauthorized use included proof of no fact not also adduced on the larceny charge, we held that the two charges were in that instance the “same offense” for multiple punishment purposes.', 'general', 'Byrd v. United States', 'https://www.courtlistener.com/opinion/1930387/', '1930387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a proper interpretation of that section permits appellant to be convicted of both RSP and UUV but to be sentenced for those crimes only concurrently, and not consecutively.', 'sentencing', 'Byrd v. United States', 'https://www.courtlistener.com/opinion/1930387/', '1930387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that given the intimate relationship between theft and RSP as discussed above, most notably demonstrated by the “rule of priority,” the provisions of § 22-3803 should be interpreted as a manifestation of legislative will to prohibit consecutive sentences for convictions of RSP and UUY arising out of the “same act or course of conduct.', 'sentencing', 'Byrd v. United States', 'https://www.courtlistener.com/opinion/1930387/', '1930387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that:
(a) the trial court properly admitted the six-year-old victim''s statement to the police under the tender years exception to the hearsay rule, N.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Frisby, supra, we held that "`[t]here is no provision in our legal system for a "truth-teller" who is authorized to advise the jury on the basis of ex parte investigations what the facts are and that the defendant''s story is a lie.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When measured against this yardstick, we conclude that the prosecutor''s comments did not "raise a reasonable doubt as *526 to whether the error led the jury to a result it otherwise might not have reached.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "[a]ny improper influence on the jury that could have tipped the credibility scale was necessarily harmful and warrant[ed] reversal.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the requisite elements for admissibility of C.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We find that the prosecutor''s comment was fairly invited by the defense''s statements in summation that C.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the argument was improper, we find that, in those circumstances, it was harmless error.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the defendant''s conviction because, "[b]ased on the hearsay evidence, the police essentially gave the jury their opinion regarding the innocence of [the father] and inferentially the guilt of [the defendant].', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we affirm the judgment of the Appellate Division affirming R.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the Appellate Division.', 'general', 'State v. RB', 'https://www.courtlistener.com/opinion/1903342/', '1903342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '539 NW2d 570 (1995), this Court held that because the restitution statute is silent regarding how to determine the amount of loss that the victim sustained, the amount should be “based upon the evidence.', 'general', 'People v. Cross', 'https://www.courtlistener.com/opinion/1654002/', '1654002') ON CONFLICT DO NOTHING;
