INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1132, this court held that a person in Mr.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1907531/', '1907531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the approach taken by the Fifth District in Nicholson v.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1907531/', '1907531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'King was designated as a sexual predator under circumstances where the law does not permit such a designation, we reverse the order of the circuit court and remand with directions for the circuit court to grant the motion as a motion to correct an illegal sentence filed pursuant to Florida Rule of Criminal Procedure 3.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1907531/', '1907531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of the circuit court and remand with directions for the circuit court to grant the motion as a motion to correct an illegal sentence filed pursuant to rule 3.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1907531/', '1907531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the judgment and sentence in an unwritten opinion.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1907531/', '1907531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although we affirm the order on appeal, we are convinced that Mr.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1907531/', '1907531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed, however, without prejudice to Mr.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1907531/', '1907531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that § 28-311.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1910818/', '1910818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “as used in § 28-311.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1910818/', '1910818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the mere assertion that a statute may be unconstitutional does not automatically deprive the Court of Appeals of jurisdiction over the case.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1910818/', '1910818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Court of Appeals had the authority, in this case, to consider Nelson’s constitutional claim.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1910818/', '1910818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[s]ubsection (l)(c) of § 28-311.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1910818/', '1910818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that for the constitutionality of a statute to be genuinely “involved” in an appeal, “‘[t]he constitutional issue must be real and substantial;', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1910818/', '1910818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although our reasoning differs from that of the Court of Appeals, the court’s ultimate decision was correct, and accordingly, we affirm.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/1910818/', '1910818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such an action is sufficiently analogous to the "defenses" of self-defense, entrapment and duress to require a similar allocation of the burdens of production and proof.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instructions given by the trial court, when viewed as a whole, adequately instructed the jury on the state''s burden of proof.', 'jury_instruction', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when, as in this case, the defendant is charged with premeditated murder and sufficient evidence is adduced at trial for a jury reasonably to infer that the defendant caused the death of another person in the heat of passion, provoked by such words or acts of another as would provoke a person of ordinary self-control under like circumstances, the state has the burden to prove beyond a reasonable doubt the absence of heat of passion.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the court''s jury instructions, when viewed as a whole, were more than adequate to inform the jury of the state''s burden of proof.', 'jury_instruction', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instructions in this case were more than sufficient to instruct the jury on the state''s burden of proof.', 'jury_instruction', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute is not impermissibly vague in all of its applications.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that the evidence presented at trial was sufficient for the jury to conclude that from the time Auchampach and Counts met in April 1991 until Counts'' murder in March 1993, Auchampach engaged in acts of assaultive behavior toward Counts and made terroristic threats against her.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Niska, for example, we concluded that an action taken to protect a child from physical or sexual assault or substantial emotional harm "is an affirmative defense" to the crime of deprivation of parental, custodial, or visitation rights.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We affirm.', 'general', 'State v. Auchampach', 'https://www.courtlistener.com/opinion/1911388/', '1911388') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 515, we conclude that there was sufficient evidence to support the jury’s conclusion that defendant intentionally killed his wife.', 'general', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 514-515, we conclude that there was sufficient evidence to support the jury’s conclusion that defendant premeditated and deliberated the victim’s murder.', 'general', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant waived any argument in this regard when defense counsel expressed satisfaction with the trial court’s instruction to the jury.', 'general', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that, but for counsel’s alleged errors, the result of defendant’s trial would have been different.', 'general', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
