INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is not beyond a forensic pathologist’s area of expertise to offer testimony in the courts of this state concerning both the cause of death and the manner of death.', 'general', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of this authority, we conclude that the trial court improperly conducted the jury view before any of the relevant evidence or testimony had been presented at trial.', 'general', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the autopsy photographs were relevant, MRE 401, and were not unduly prejudicial to defendant, MRE 403.', 'general', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s trial counsel was not ineffective for failing to challenge the potential juror in question.', 'ineffective_assistance', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant waived review of this issue when he affirmatively approved the trial court’s decision to instruct the jury only once concerning the testimony of all seven of the witnesses.', 'general', 'People v. Unger', 'https://www.courtlistener.com/opinion/1916834/', '1916834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Answering the question presented by the District Court of Appeal in the case sub judice, we hold that the zoning ordinance adopted by the zoning authorities and the Town Council after public hearing was rendered invalid because of the non-public activities of the citizens planning committee, which committee was established by the Town Council, active on behalf of the Council in an advisory capacity, and participated in the formulation of the zoning plan.', 'general', 'Town of Palm Beach v. Gradison', 'https://www.courtlistener.com/opinion/1917187/', '1917187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ogle, we held that both negligent participants in a "drag race" were equally liable for a fatal collision resulting from their negligence, even though only one of the tortfeasors struck a third automobile causing injury.', 'general', 'Richards v. Badger Mutual Insurance', 'https://www.courtlistener.com/opinion/1917348/', '1917348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '045(2) are employed and the concerted action theory of liability is explained, we conclude that § 895.', 'general', 'Richards v. Badger Mutual Insurance', 'https://www.courtlistener.com/opinion/1917348/', '1917348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We affirm the court of appeals.', 'general', 'Richards v. Badger Mutual Insurance', 'https://www.courtlistener.com/opinion/1917348/', '1917348') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these tactics did not affect the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'ing her daughter’s death and to statements made by defendant, which could not be fully evaluated by the jury without understanding defendant’s intellectual limitations, we conclude that it is more probable than not that the error was outcome determinative.', 'general', 'People v. Yost', 'https://www.courtlistener.com/opinion/1917649/', '1917649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the trial court’s decision to again deny defendant’s request to add a toxicologist on March 1 fell outside the range of reasonable and principled outcomes.', 'general', 'People v. Yost', 'https://www.courtlistener.com/opinion/1917649/', '1917649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the unique facts of this case, we conclude that the prejudicial nature of the evidence actually offered at trial substantially outweighed the value for which the evidence was properly probative.', 'general', 'People v. Yost', 'https://www.courtlistener.com/opinion/1917649/', '1917649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the limited necessity of the evidence to prove motive and the high probability that the jury improperly used the testimony, we conclude that the trial court abused its discretion when it determined that the evidence of specific allegations of abuse was not substantially outweighed by the danger of unfair prejudice.', 'general', 'People v. Yost', 'https://www.courtlistener.com/opinion/1917649/', '1917649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the trial court did not abuse its discretion in permitting the evidence of prior allegations of sexual abuse involving Monique.', 'general', 'People v. Yost', 'https://www.courtlistener.com/opinion/1917649/', '1917649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because these errors deprived defendant of a fair trial, we reverse defendant’s convictions, vacate her sentence, and remand for a new trial.', 'sentencing', 'People v. Yost', 'https://www.courtlistener.com/opinion/1917649/', '1917649') ON CONFLICT DO NOTHING;
