INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We disagree, and will affirm the judgment because we conclude that the warrantless entry was reasonable under the circumstances.', 'general', 'Gorman v. State', 'https://www.courtlistener.com/opinion/1922174/', '1922174') ON CONFLICT DO NOTHING;
