INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence considered by the court of appeals and available to the jury on this factor cannot, as a matter of law, weigh in favor of categorizing Mr.', 'general', 'Salt Lake City v. Miles', 'https://www.courtlistener.com/opinion/2745632/', '2745632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant''s possession of household items used in the commission of a crime and found at the scene of a crime established a sufficient nexus linking his nearby residence to the criminal enterprise because such items were often concealed at the home.', 'general', 'State v. Quigley', 'https://www.courtlistener.com/opinion/1925418/', '1925418') ON CONFLICT DO NOTHING;
