INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'State v. Quigley', 'https://www.courtlistener.com/opinion/1925418/', '1925418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this testimony alone, we affirm the trial court''s conclusion that there was no probable cause to conduct a search of *216 Quigley''s bedroom, and that the "community living exception" does not apply.', 'probable_cause', 'State v. Quigley', 'https://www.courtlistener.com/opinion/1925418/', '1925418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the verdict in the guilt-determining phase is within the law and the weight of the evidence.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1928340/', '1928340') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that defense counsel underscored Willie Reddix''s conviction and attempted to use that fact to appellant''s advantage, as can be seen from the following colloquy between defense counsel and state witness Annie Lee Reddix:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that: the sentence of death was not imposed in this case under the influence of passion, prejudice or any other arbitrary factor;', 'sentencing', 'Jones v. State', 'https://www.courtlistener.com/opinion/1928340/', '1928340') ON CONFLICT DO NOTHING;
