INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prosecutor’s remarks constituted misconduct which deprived Defendant of a fair trial, and reverse.', 'general', 'State v. Marsh', 'https://www.courtlistener.com/opinion/2606488/', '2606488') ON CONFLICT DO NOTHING;
