INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the level of assurance that a preserved, nonconstitutional error justifies reversal of a conviction is the "more probable than not" standard.', 'general', 'People v. Lukity', 'https://www.courtlistener.com/opinion/1985231/', '1985231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the admission of evidence bolstering complainant''s character for truthfulness was error here, but that this error did not result in a miscarriage of justice that would justify reversal of defendant''s conviction under § 26.', 'general', 'People v. Lukity', 'https://www.courtlistener.com/opinion/1985231/', '1985231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that the other two evidentiary errors found by the Court of Appeals were not, in fact, errors.', 'general', 'People v. Lukity', 'https://www.courtlistener.com/opinion/1985231/', '1985231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing considerations and the plain language of the statute, we hold that operating a motor vehicle without a permit in violation of D.', 'general', 'Santos v. District of Columbia', 'https://www.courtlistener.com/opinion/1968133/', '1968133') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Santos does not assert any constitutional bar to a statute imposing strict criminal liability without regard to scienter for driving without a license, nor could we conclude that such a bar exists.', 'general', 'Santos v. District of Columbia', 'https://www.courtlistener.com/opinion/1968133/', '1968133') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm Santos’s conviction.', 'general', 'Santos v. District of Columbia', 'https://www.courtlistener.com/opinion/1968133/', '1968133') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Santos’s convictions, except that we remand the case with directions to vacate his duplicative conviction for OWI.', 'general', 'Santos v. District of Columbia', 'https://www.courtlistener.com/opinion/1968133/', '1968133') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, a plurality of this Court held that the trial court may order two or more indictments against the same defendant to be tried together if the offenses could have been joined in a single indictment.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Appellant’s challenge that the evidence was insufficient to establish the requisite specific intent is without merit.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the record, we conclude that the sentence of death was not the product of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence of death imposed upon Appellant is not excessive or disproportionate to the penalty imposed in similar cases.', 'sentencing', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the evidence of the shooting of Dustin Spotz and Appellant’s subsequent flight was clearly relevant to the issue of Appellant’s motive for robbing and killing Mrs.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Since “defendants” is not included in section B(2), we find that the trial court properly determined that Pa.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since there is no procedure available by which a criminal defendant can compel the consolidation of separate defendants, we find that the trial court properly denied Appellant’s motion to compel consolidation of his case with Christina Noland’s.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ohlinger, we find that the trial court did not abuse its discretion in admitting the handgun into evidence.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the trial court did not abuse its discretion in denying Appellant’s motion for a mistrial.', 'mistrial', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons presented herein, we affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/1951566/', '1951566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 417, we held that when a defendant''s oral statements have been introduced against him, the trial court must instruct the jury that it should consider such evidence with caution "in view of the generally recognized risk of inaccuracy and error in communication and recollection of verbal utterances and misconstruction by the hearer.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Loftin I, supra, although rejecting the argument that a lengthy noncapital sentence must be presented as a mitigating factor, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court''s instruction had the "potential to foreclose jury consideration of whether passion/provocation should reduce an otherwise purposeful killing from murder to manslaughter.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Biegenwald, we held that the failure to instruct the jury on accomplice liability, when neither that theory nor facts supporting *456 such a charge was ever put before the jury, was not error.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 308 (1984), this Court held that empirical data regarding the diminished criminality of men over fifty-five years old was relevant and admissible at the penalty phase of a capital trial.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure of the trial court to provide a Hampton charge regarding Wrigley''s testimony was not plain error clearly capable of producing an unjust result.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we conclude that the trial court''s actions did not amount to reversible error.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brown we concluded that jury unanimity was required for the State to prove beyond a reasonable doubt that a defendant committed a murder by his own conduct.', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Rose, supra, we concluded that the cumulative effect of numerous prosecutorial improprieties required reversal of a death sentence.', 'sentencing', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a preliminary matter, we find that Hampton does not apply to the bulk of the incriminating statements allegedly made by defendant;', 'general', 'State v. Feaster', 'https://www.courtlistener.com/opinion/1951916/', '1951916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that the annoyance or alarm required by subsection (a) need not be serious, the catchall provision of subsection (a) must be interpreted to protect against unconstitutional vagueness and impermissible restrictions on speech.', 'general', 'State v. Hoffman', 'https://www.courtlistener.com/opinion/1952159/', '1952159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that defendant was improperly convicted under subsection (a) because those mailings did not invade Mary’s privacy so as to constitute harassment, we emphasize that the trial court is permitted to examine the totality of the circumstances, especially and including the context of domestic violence, in determining whether subsection (a) has been violated.', 'general', 'State v. Hoffman', 'https://www.courtlistener.com/opinion/1952159/', '1952159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the principal issue before us, the issue that divided the Appellate Division, whether a “serious” annoyance must be found under subsection (a), is the wrong issue upon which to focus.', 'general', 'State v. Hoffman', 'https://www.courtlistener.com/opinion/1952159/', '1952159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division and hold that the two mailings violated the permanent restraining order.', 'general', 'State v. Hoffman', 'https://www.courtlistener.com/opinion/1952159/', '1952159') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Appellate Division that the two mailings did not violate
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Section 856.', 'general', 'State v. Ecker', 'https://www.courtlistener.com/opinion/1952375/', '1952375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the holding by the trial court that the statute is unconstitutional and remand this cause to the trial court for determination not inconsistent with the construction of the subject statute herein expressed.', 'general', 'State v. Ecker', 'https://www.courtlistener.com/opinion/1952375/', '1952375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, we affirm the conviction but caution law enforcement officers that this statute contains separate, distinct elements that must be established in the same manner as those of any other criminal offense.', 'general', 'State v. Ecker', 'https://www.courtlistener.com/opinion/1952375/', '1952375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In keeping with past decisions of this court, we conclude that decriminalizing penalties alone is insufficient to manifest a legislative intent that a statute which previously had been construed to require scienter be applied as one of the strict liability.', 'general', 'State v. Olson', 'https://www.courtlistener.com/opinion/1953757/', '1953757') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1977), we held that the government’s “suggestion] that appellant’s presence during trial facilitated his ability to fabricate” was “improper, and .', 'general', 'Teoume-Lessane v. United States', 'https://www.courtlistener.com/opinion/1953866/', '1953866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the Council meant to remove impediments to DNA testing when it might prove that the wrong person had been convicted of a violent crime.', 'general', 'Teoume-Lessane v. United States', 'https://www.courtlistener.com/opinion/1953866/', '1953866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion by permitting the government to ask this one question to counter the implication that the FBI’s approach to testing the evidence in this case was biased.', 'general', 'Teoume-Lessane v. United States', 'https://www.courtlistener.com/opinion/1953866/', '1953866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the statement would better have been left unsaid, we conclude that it had no substantial influence on the jury’s verdict.', 'general', 'Teoume-Lessane v. United States', 'https://www.courtlistener.com/opinion/1953866/', '1953866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm.', 'general', 'Teoume-Lessane v. United States', 'https://www.courtlistener.com/opinion/1953866/', '1953866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the prosecutor did not im-permissibly comment upon the effect of the defendant’s presence at trial on his credibility as a witness, and that the trial court did not abuse its discretion in permitting the jury to consider the remarks.', 'general', 'Teoume-Lessane v. United States', 'https://www.courtlistener.com/opinion/1953866/', '1953866') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Weber’s convictions and remand for a new trial.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1955294/', '1955294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 601, 603 (1978), we hold that the exception applies in a case like this where the evidence goes to the sanity of the defendant.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We find that the evidence was admissible.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we find that the testimony of the District Director on the relationship between insanity and child abuse was not unduly prejudicial.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the issue was the admission of expert testimony on the credibility of the complaining witness, and it was on that issue that we reversed.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Valley', 'https://www.courtlistener.com/opinion/1955651/', '1955651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, viewing the evidence presented in the light most favorable to the non-moving party, we find that the jury award was not against the overwhelming weight of the evidence and that the trial court did not err in refusing to grant a new trial.', 'general', 'Milburn v. Vinson', 'https://www.courtlistener.com/opinion/1959435/', '1959435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of the evidence, we find that the trial court did not abuse its discretion in refusing to grant a remittitur.', 'general', 'Milburn v. Vinson', 'https://www.courtlistener.com/opinion/1959435/', '1959435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Milburn v. Vinson', 'https://www.courtlistener.com/opinion/1959435/', '1959435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we find that the Board committed an error of law, we reverse the Board and order Zdrok suspended from the practice of law for a period of six months.', 'general', 'Office of Disciplinary Counsel v. Zdrok', 'https://www.courtlistener.com/opinion/1959577/', '1959577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Board erred in determining that the Petition failed to specifically charge a violation of Pa.', 'general', 'Office of Disciplinary Counsel v. Zdrok', 'https://www.courtlistener.com/opinion/1959577/', '1959577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that this evidence is proper and relevant in considering the discipline to impose.', 'general', 'Office of Disciplinary Counsel v. Zdrok', 'https://www.courtlistener.com/opinion/1959577/', '1959577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the record, we find that the introduction and consideration of the other aggravating factors by the Hearing Committee was appropriate as well.', 'general', 'Office of Disciplinary Counsel v. Zdrok', 'https://www.courtlistener.com/opinion/1959577/', '1959577') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the error was harmless because “[t]he evidence against [the defendant] is substantial, and Blount’s proffered testimony is relatively insignificant in comparison.', 'general', 'Shouse v. State', 'https://www.courtlistener.com/opinion/2026469/', '2026469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we held that there is no federal double jeopardy violation where a defendant is convicted of resisting law enforcement by fleeing and resisting law enforcement by force.', 'general', 'Shouse v. State', 'https://www.courtlistener.com/opinion/2026469/', '2026469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that the trial court’s omission of the Section 19 instruction when it re-read its preliminary instructions among the final instructions does not warrant reversal.', 'general', 'Shouse v. State', 'https://www.courtlistener.com/opinion/2026469/', '2026469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we affirm Shouse’s convictions for resisting law enforcement.', 'general', 'Shouse v. State', 'https://www.courtlistener.com/opinion/2026469/', '2026469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the information did not mislead or embarrass him in the preparation of his defense.', 'general', 'McCreary v. State', 'https://www.courtlistener.com/opinion/1961956/', '1961956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the legislature intended to accomplish the latter, and we, therefore, conclude that the trial court did not err in denying defendant''s motion for judgment of acquittal and defendant''s motion to dismiss the information.', 'dismissal', 'McCreary v. State', 'https://www.courtlistener.com/opinion/1961956/', '1961956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that section 782.', 'general', 'McCreary v. State', 'https://www.courtlistener.com/opinion/1961956/', '1961956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '071 is constitutional, and that the evidence in this case is sufficient to support the jury''s verdict, we affirm.', 'general', 'McCreary v. State', 'https://www.courtlistener.com/opinion/1961956/', '1961956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 730 (1963) in which we held that the right to a preliminary hearing may be forfeited by one who becomes a fugitive.', 'general', 'Commonwealth v. Boyd', 'https://www.courtlistener.com/opinion/1963953/', '1963953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the appellant by becoming a fugitive lost his right to a review of his post-trial motions and that the trial court did not abuse its discretion in refusing to consider the motions upon his return to the jurisdiction.', 'general', 'Commonwealth v. Boyd', 'https://www.courtlistener.com/opinion/1963953/', '1963953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Of these two choices, we find that, based on our exhaustive review of the record, the second trial court erred in denying appellant the right to represent himself at trial.', 'general', 'Commonwealth v. Starr', 'https://www.courtlistener.com/opinion/1965063/', '1965063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Bollig''s plea was knowingly and intelligently made, that the circuit
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'standard, we conclude that Bollig''s lack of knowledge as to the consequences of his plea constituted a fair and just reason.', 'plea', 'State v. Bollig', 'https://www.courtlistener.com/opinion/1965322/', '1965322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that despite the circuit court''s failure to advise Bollig of one of the essential elements, the State has demonstrated by clear and convincing evidence that he was nevertheless aware of the nature of his offense.', 'general', 'State v. Bollig', 'https://www.courtlistener.com/opinion/1965322/', '1965322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'court did not place on Bollig the burden of proving lack of substantial prejudice, and that the circuit court properly exercised its discretion, we affirm the court of appeals.', 'general', 'State v. Bollig', 'https://www.courtlistener.com/opinion/1965322/', '1965322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals.', 'general', 'State v. Bollig', 'https://www.courtlistener.com/opinion/1965322/', '1965322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), in which we held that the trial judge has the responsibility to make an independent assessment of the sufficiency of the basis for a stop, and that in order to do so, the judge must be “apprised of sufficient facts to enable him [or her] to evaluate the reliability of that information.', 'general', 'Ellis v. United States', 'https://www.courtlistener.com/opinion/1965447/', '1965447') ON CONFLICT DO NOTHING;
