INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We accept the government’s concession, and we conclude that under the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Ellis’ drug conviction.', 'general', 'Ellis v. United States', 'https://www.courtlistener.com/opinion/1965447/', '1965447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that (1) the prearrest delay in this case was not prejudicial, (2) the pretrial delay did not violate the constitutional guarantee of a speedy trial, (3) the trial court did not err in permitting the prosecution to charge Cain with a single offense and introduce evidence of multiple acts of wrongdoing, (4) the written agreement did not make Cain’s conviction legally impossible, (5) the trial court did not commit any evidentiary errors warranting reversal, (6) the trial cou...', 'general', 'People v. Cain', 'https://www.courtlistener.com/opinion/1965715/', '1965715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Cain’s argument with respect to prejudice is simply too speculative to justify reversing her conviction.', 'general', 'People v. Cain', 'https://www.courtlistener.com/opinion/1965715/', '1965715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We note that Cain was on bond pending trial, and we conclude that the delay did not affect her person by subjecting her to lengthy pretrial incarceration.', 'general', 'People v. Cain', 'https://www.courtlistener.com/opinion/1965715/', '1965715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that the omission of a special instruction regarding competency, whether from
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and sentence in this case.', 'sentencing', 'People v. Cain', 'https://www.courtlistener.com/opinion/1965715/', '1965715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant does not need to admit to the factual basis in his or her own words;', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1965725/', '1965725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court followed the proper procedure for accepting a guilty plea, and that a factual basis for the plea was established.', 'plea', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1965725/', '1965725') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence in each trial was insufficient because it did not include proof of a crucial element of the offense, viz.', 'general', 'Ford v. United States', 'https://www.courtlistener.com/opinion/1967035/', '1967035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, however, we hold that Detective Papaj''s testimony was not probative of any material fact that had not already been established by other evidence.', 'general', 'Ford v. United States', 'https://www.courtlistener.com/opinion/1967035/', '1967035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985) (hereinafter "Ford I"), we held that the statute as amended was not unconstitutionally vague, but only because it "requires that conduct be for the purpose of prostitution and because it provides that objective criteria must be present in order to support a conviction.', 'general', 'Ford v. United States', 'https://www.courtlistener.com/opinion/1967035/', '1967035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the record before us, we conclude that withdrawal of the plea should have been permitted as fair and just under the circumstances.', 'plea', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although, as we have already noted, the decision whether or not to grant the motion is vested in the sound discretion of the trial court, we conclude that this discretion has been abused.', 'general', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whether brought before or after sentence, these motions are addressed to the sound discretion of the trial court and we reverse only upon a showing of abuse of such discretion.', 'sentencing', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[22] We reverse so that appellant can have the opportunity to put his asserted coercion defense before a jury.', 'general', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed his convictions in an unpublished opinion.', 'general', 'Gooding v. United States', 'https://www.courtlistener.com/opinion/1967458/', '1967458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that because the crime of receiving stolen property requires more than two acts, and one of the acts is that the property must be stolen and that act
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm.', 'general', 'State v. Lippold', 'https://www.courtlistener.com/opinion/1946466/', '1946466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed a conviction for theft by fraud where all the false statements were passed through a conduit to the victims).', 'general', 'State v. Lippold', 'https://www.courtlistener.com/opinion/1946466/', '1946466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Lippold', 'https://www.courtlistener.com/opinion/1946466/', '1946466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was sufficient substantial evidence to support the jury’s verdict.', 'general', 'Pryor v. State', 'https://www.courtlistener.com/opinion/1947039/', '1947039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the conviction.', 'general', 'Pryor v. State', 'https://www.courtlistener.com/opinion/1947039/', '1947039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Commonwealth v. Roland', 'https://www.courtlistener.com/opinion/1947494/', '1947494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the requirement in Utah Code section 78B-6-121(8) substantially advances the important governmental interests identified above.', 'general', 'Bolden v. Doe (In re Adoption of J.S.)', 'https://www.courtlistener.com/opinion/2747938/', '2747938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'had failed to satisfy the statutory prerequisites to perfecting his inchoate parental rights, we held that the "natural mother''s relinquishment of [his] child" for adoption "eliminate[d] his opportunity to acquire constitutionally protectable parental rights.', 'general', 'Bolden v. Doe (In re Adoption of J.S.)', 'https://www.courtlistener.com/opinion/2747938/', '2747938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that a provision of the Adoption Act that cut off unwed fathers'' ability to file on holidays and weekends was "not necessary to achieve the state''s compelling interests" nor was it a "narrowly tailored means of achieving those interests.', 'general', 'Bolden v. Doe (In re Adoption of J.S.)', 'https://www.courtlistener.com/opinion/2747938/', '2747938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that he has failed to make the kind of showing rooted in settled history and tradition, and thus that his claim is subject only to review for rationality or arbitrariness.', 'general', 'Bolden v. Doe (In re Adoption of J.S.)', 'https://www.courtlistener.com/opinion/2747938/', '2747938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And we concluded that that interest rises to the level of a fundamental right "only when [the father] ''demonstrates full commitment to the responsibilities of parenthood by [coming] forward to participate in the rearing of his child''" Id.', 'general', 'Bolden v. Doe (In re Adoption of J.S.)', 'https://www.courtlistener.com/opinion/2747938/', '2747938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this unique set of facts, we conclude that Douglas did not waive the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After due consideration of Douglas’s minimal criminal history, probation violations, and guilty plea, we find that the sentence imposed to be inappropriate and remand for the court to impose the presumptive sentence of eighteen months.', 'sentencing', 'Douglas v. State', 'https://www.courtlistener.com/opinion/2070415/', '2070415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and revise the sentence.', 'sentencing', 'Douglas v. State', 'https://www.courtlistener.com/opinion/2070415/', '2070415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “[o]ne cannot be convicted of manslaughter in the presence of an intervening cause of death, unless that intervening cause is found to be a natural result of one’s acts.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1972310/', '1972310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1972310/', '1972310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was error for the Trial Court to so amend the indictments.', 'general', 'Keller v. State', 'https://www.courtlistener.com/opinion/1973018/', '1973018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse defendant’s felony theft convictions.', 'general', 'Keller v. State', 'https://www.courtlistener.com/opinion/1973018/', '1973018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 655, 657-658 (1988) we held that section 1547(a)(1), 75 Pa.', 'general', 'Commonwealth, Department of Transportation, Bureau of Driver Licensing v. Bird', 'https://www.courtlistener.com/opinion/1973797/', '1973797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A year after the Lewis decision, a separate panel of this court held in Department of Transportation, Bureau of Driver Licensing v.', 'general', 'Commonwealth, Department of Transportation, Bureau of Driver Licensing v. Bird', 'https://www.courtlistener.com/opinion/1973797/', '1973797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 533 (1989), this Court held that the police officer, who observed a licensee passed out in the drivers'' seat with the motor running, lacked reasonable grounds to believe that the licensee was driving under the influence on a highway or trafficway.', 'general', 'Commonwealth, Department of Transportation, Bureau of Driver Licensing v. Bird', 'https://www.courtlistener.com/opinion/1973797/', '1973797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Commonwealth, Department of Transportation, Bureau of Driver Licensing v. Bird', 'https://www.courtlistener.com/opinion/1973797/', '1973797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court improperly restricted the scope of the identity theft statute to preclude its application to the facts present in this case.', 'general', 'State v. Peters', 'https://www.courtlistener.com/opinion/1974346/', '1974346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the circuit court''s order dismissing the identity theft charge, and remand for reinstatement of the charge and further proceedings consistent with the opinion.', 'dismissal', 'State v. Peters', 'https://www.courtlistener.com/opinion/1974346/', '1974346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the indictment was not constructively amended and that, although there was a variance between the indictment and the evidence presented at trial, Carter neither claimed prejudice nor made any evidentiary showing that the variance impaired his defense.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/1989377/', '1989377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judge was familiar with the statute and that, notwithstanding her failure explicitly to mention the portion of the thigh with which Carter had contact, she effectively found Carter guilty of a sexual touching of the inner thigh.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/1989377/', '1989377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/1989377/', '1989377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that concealing identity was not a separate offense, but, rather, a penalty enhancer, and therefore the two sentences for what was a single, enhanced offense, violated double jeopardy.', 'sentencing', 'State v. Church', 'https://www.courtlistener.com/opinion/1975112/', '1975112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that neither the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances here, we conclude that the longer sentence violated due process.', 'sentencing', 'State v. Church', 'https://www.courtlistener.com/opinion/1975112/', '1975112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that resentencing on convictions that remain intact after an appellate court reverses and vacates one or more counts in a multi-count case is not always required.', 'sentencing', 'State v. Church', 'https://www.courtlistener.com/opinion/1975112/', '1975112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the increased sentence was presumptively vindictive, in violation of Church''s right to due process, and that the presumption was not overcome by adequate, objective new factors in the record justifying the increase.', 'sentencing', 'State v. Church', 'https://www.courtlistener.com/opinion/1975112/', '1975112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Accordingly, rather than attempting to infer at the appellate level what sentence the trial court would have imposed had it proceeded on the proper assumption that concealing identity aggravates armed robbery but does not stand as a separate substantive offense, we conclude that the trial court is the proper court to resentence the defendant under a correct application of the law.', 'sentencing', 'State v. Church', 'https://www.courtlistener.com/opinion/1975112/', '1975112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that resentencing on convictions that remain intact after one or more counts in a multi-count case is vacated is not always required.', 'sentencing', 'State v. Church', 'https://www.courtlistener.com/opinion/1975112/', '1975112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the conviction and sentence for kidnapping as well as second-degree murder predicated upon kidnapping violated double jeopardy, and vacated the kidnapping count.', 'sentencing', 'State v. Church', 'https://www.courtlistener.com/opinion/1975112/', '1975112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 329, we concluded that separate, consecutive one-year sentences for possession of a controlled substance and habitual criminality violated double jeopardy, because the repeater statute was a penalty enhancer, not a separate offense.', 'sentencing', 'State v. Church', 'https://www.courtlistener.com/opinion/1975112/', '1975112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that neither the retention of legal counsel by a mentally ill person nor such counsel''s filing of a claim on the mentally ill person''s behalf causes, as a matter of law, that person''s mental illness to cease for purposes of § 893.', 'general', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '55(1), we conclude that the five-year repose period in paragraph (b) of that subsection is limited to the discovery accrual rule in § 893.', 'general', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16(1)? We conclude that a person who is mentally ill at the time his or her cause of action for medical malpractice accrues under § 893.', 'general', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such a finding is required.', 'general', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all, we conclude that, if Storm was mentally ill at the time her causes of action accrued against each defendant, and if her illness did not cease more than two years before she filed a claim against any of the individual defendants, then Storm timely filed her action alleging medical malpractice against Doctors Olson and Castillo.', 'general', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the legislature intended for § 893.', 'general', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16, we conclude that summary judgment on this question is inappropriate at the present time.', 'general', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the retention of legal counsel does not
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing reasons, we conclude that the five-year statute of repose in Wis.', 'general', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we reverse the circuit court’s grant of summary judgment and dismissal of Dr.', 'dismissal', 'Storm Ex Rel. Smoler v. Legion Insurance', 'https://www.courtlistener.com/opinion/1975196/', '1975196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Albury cannot avoid the showing of “prejudice” which
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that competent evidence exists to support the findings of fact and conclusions of law by the Superior Court.', 'general', 'Albury v. State', 'https://www.courtlistener.com/opinion/1976460/', '1976460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the Superior Court properly denied Albury’s claim that the alleged deficiencies of his trial attorney resulted in a denial of due process.', 'general', 'Albury v. State', 'https://www.courtlistener.com/opinion/1976460/', '1976460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record supports the conclusion that the State’s charges against Albury were brought in good faith and that the plea bargaining process was conducted in a nondiscriminatory manner.', 'plea', 'Albury v. State', 'https://www.courtlistener.com/opinion/1976460/', '1976460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did not.', 'general', 'State v. Grose', 'https://www.courtlistener.com/opinion/1979403/', '1979403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Grose', 'https://www.courtlistener.com/opinion/1979403/', '1979403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the interests of fairness and judicial economy do not support the creation of a broad rule establishing an appeal as of right following a stay of adjudication entered pursuant to section 152.', 'general', 'State v. Verschelde', 'https://www.courtlistener.com/opinion/1989673/', '1989673') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While both parties'' arguments have merit, we conclude that in the interests of judicial economy, piecemeal litigation should be discouraged.', 'general', 'State v. Verschelde', 'https://www.courtlistener.com/opinion/1989673/', '1989673') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the court of appeals'' conclusion that a stay of adjudication is a pretrial order, not a final judgment or sentence, and thus appealable by the state as of right even in nonfelony cases.', 'sentencing', 'State v. Verschelde', 'https://www.courtlistener.com/opinion/1989673/', '1989673') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the requirements of due process were not satisfied here.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1980302/', '1980302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given our view, however, that the proceeding set forth in the Act to determine whether one is a sexually violent predator is a separate factual determination, the end result of which is the imposition of criminal punishment, we hold that anything less than the full panoply of the relevant protections which due process guarantees is violative of the Fourteenth Amendment.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1980302/', '1980302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In weighing the two, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[17]  Because we conclude that the trial court properly determined that the Act is violative of the procedural due process requirements of the Fourteenth Amendment, we need not address the remaining constitutional challenges raised, or analyze the due process provisions of the State Constitution since the federal constitution establishes certain "minimum" standards, which each state has the power to expand.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1980302/', '1980302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, because we find that the procedure whereby one is determined to be a sexually violent predator is unconstitutional, we strike all of the provisions referring to this designation.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1980302/', '1980302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on the record evidence, the trial court correctly ruled that defendants are not directly liable for Forrest''s misconduct under 24 V.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on the Faragher analysis, we hold that if plaintiff can show that an on-duty law enforcement officer was aided in accomplishing an intentional tort involving a sexual assault on the plaintiff by the existence of the employment relationship with the law enforcement agency, vicarious liability will apply.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that summary judgment in favor of defendants on the claim of apparent authority was appropriate.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the holding in Gary did not survive the Supreme Court decisions in Faragher and Ellerth.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the superior court correctly held that defendants were entitled to summary judgment on the claim under 24 V.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Confronted with these uncertainties, we concluded that the decision "`involves significant and far-reaching policy concerns'' more properly left to the Legislature, where hearings may be held, data collected, and competing interests heard before a wise decision is reached.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that none of the reasons advanced by the trial court warrant summary judgment for defendants on the ง 219(2)(d) claim.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude there are questions of material fact regarding this issue, we reverse the trial court''s grant of summary judgment on this issue.', 'general', 'Doe v. Forrest', 'https://www.courtlistener.com/opinion/1980885/', '1980885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 152 (1990), the State suggests we hold that a defendant is in “custody” only when confined in a prison or jail.', 'general', 'People v. Campa', 'https://www.courtlistener.com/opinion/1981447/', '1981447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This is a distinction of note since, hereinafter, we hold that defendant was not on bail or recognizance while participating in the Day Reporting Center program.', 'general', 'People v. Campa', 'https://www.courtlistener.com/opinion/1981447/', '1981447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, as a participant in the Day Reporting Center program, defendant was in the “custody” of the Cook County Department of Corrections and the Department of Community Supervision and Intervention.', 'general', 'People v. Campa', 'https://www.courtlistener.com/opinion/1981447/', '1981447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the appellate court.', 'general', 'People v. Campa', 'https://www.courtlistener.com/opinion/1981447/', '1981447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the aforementioned reasons, we affirm the judgment of the appellate court.', 'general', 'People v. Campa', 'https://www.courtlistener.com/opinion/1981447/', '1981447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From a review of the entire record, and applying the facts to the law, we conclude that we must sustain the Trial Court’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, we conclude that the Trial Court did not abuse its discretion in denying Hu-ghey’s Rule 48(b) motion to dismiss for unnecessary delay.', 'dismissal', 'Hughey v. State', 'https://www.courtlistener.com/opinion/1982620/', '1982620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Trial Court did not commit legal error or abuse its discretion in denying Hughey’s motion to dismiss for violation of his Sixth Amendment right.', 'dismissal', 'Hughey v. State', 'https://www.courtlistener.com/opinion/1982620/', '1982620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the Superior Court’s dismissal of a criminal indictment based upon the State’s failure to secure the attendance of a vital witness.', 'dismissal', 'Hughey v. State', 'https://www.courtlistener.com/opinion/1982620/', '1982620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the trial court, we hold that the statute creates a "continuing offense" under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And since Ramirez obtained these things after the effective date of the statute, we hold that the statute as applied was not an ex post facto law.', 'general', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1986108/', '1986108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Ramirez obtained money in the form of wages, not merely the opportunity for employment, as the result of his unauthorized use of Wulfenstein''s personal identifying information.', 'general', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1986108/', '1986108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since Ramirez''s identity theft allowed him to obtain wages after the effective date of the statute, we hold that the application of the statute did not violate the ex post facto provisions of the Wisconsin Constitution.', 'general', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1986108/', '1986108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this scope, history, context, and legislative objective of the statute, we conclude that the legislature envisioned that the theft of a person''s identity would, in many instances, produce recurring episodes in which the defendant would obtain things of value as a result of the original act of identity theft.', 'general', 'State v. Ramirez', 'https://www.courtlistener.com/opinion/1986108/', '1986108') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that Wis.', 'general', 'State v. Leitner', 'https://www.courtlistener.com/opinion/1986342/', '1986342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both findings.', 'general', 'State v. Leitner', 'https://www.courtlistener.com/opinion/1986342/', '1986342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the testimony was prejudicial and clearly erroneous and reversed the judgment of conviction and awarded a new trial.', 'general', 'Sinclair v. State', 'https://www.courtlistener.com/opinion/1647833/', '1647833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Ho failed to demonstrate "a reasonable possibility that the same evidentiary facts may have been used to establish the essential elements of each challenged offense.', 'general', 'Calvert v. State', 'https://www.courtlistener.com/opinion/1987704/', '1987704') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Collier, this court held the defendant''s actions did not constitute a substantial step toward the murder of his estranged wife.', 'general', 'Calvert v. State', 'https://www.courtlistener.com/opinion/1987704/', '1987704') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'denied, this court held the defendant''s dual convictions of possessing a firearm as a serious violent felon and carrying a handgun without a license amounted to double jeopardy.', 'general', 'Calvert v. State', 'https://www.courtlistener.com/opinion/1987704/', '1987704') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that double jeopardy protections were not violated because "distinct evidentiary facts were used to prove that Ho committed robbery while armed with a handgun, while a lack of evidentiary facts was used to prove that Ho did not have a license to carry that handgun.', 'general', 'Calvert v. State', 'https://www.courtlistener.com/opinion/1987704/', '1987704') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand with instructions to vacate that conviction and the accompanying sentence.', 'sentencing', 'Calvert v. State', 'https://www.courtlistener.com/opinion/1987704/', '1987704') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Johnson is not entitled to relief on his collateral-estoppel claim, we affirm
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that the appellant failed to preserve his objection to venue where he moved for judgment of acquittal specifying other grounds only.', 'general', 'Porter v. United States', 'https://www.courtlistener.com/opinion/1989359/', '1989359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that standard, we conclude that the evidence was sufficient to support Alston’s convictions.', 'general', 'Porter v. United States', 'https://www.courtlistener.com/opinion/1989359/', '1989359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of these reasons, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these factors, we conclude that reversal is not warranted on the basis claimed.', 'general', 'Porter v. United States', 'https://www.courtlistener.com/opinion/1989359/', '1989359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm, but remand for the trial court to vacate the merged offenses.', 'general', 'Porter v. United States', 'https://www.courtlistener.com/opinion/1989359/', '1989359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We hold that there was no error in the refusal to provide the cognate offense instruction because UDAA and armed robbery are not of the same class or category of offenses.', 'general', 'People v. Hendricks', 'https://www.courtlistener.com/opinion/1969369/', '1969369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the requirement for instruction on cognate lesser included offenses that the principal offense and the lesser crime be of the same class or category, or be closely related, we find that armed robbery and UDAA do not possess the requisite inherent relationship necessary to consider the possibility of such instruction.', 'general', 'People v. Hendricks', 'https://www.courtlistener.com/opinion/1969369/', '1969369') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that the trial court properly sentenced defendant.', 'sentencing', 'People v. Horrell', 'https://www.courtlistener.com/opinion/2161971/', '2161971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court properly sentenced defendant to a term of probation on count VI which was to be served during the period of MSR, which is an inherent part of his prison sentence.', 'sentencing', 'People v. Horrell', 'https://www.courtlistener.com/opinion/2161971/', '2161971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 153 (2008), we concluded that “MSR was a mandatory part” of the defendant’s prison sentence and that he “remain[ed] under sentence” even after he was physically released from prison.', 'sentencing', 'People v. Horrell', 'https://www.courtlistener.com/opinion/2161971/', '2161971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court.', 'general', 'People v. Horrell', 'https://www.courtlistener.com/opinion/2161971/', '2161971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when a trial court submits a single broad-form liability question incorporating multiple theories of liability, the error is harmful and a new trial is required when the appellate court cannot determine whether the jury based its verdict on an improperly submitted invalid theory.', 'general', 'Bagheri v. State', 'https://www.courtlistener.com/opinion/2170594/', '2170594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the sufficiency of the evidence to support conviction under an impairment theory does not alone establish that the error in admitting a flawed retrograde extrapolation analysis was harmless.', 'general', 'Bagheri v. State', 'https://www.courtlistener.com/opinion/2170594/', '2170594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant may be convicted of obstruction under N.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in relying on the dispatch from headquarters the officers were "lawfully performing an official function" when they commanded defendant to stop.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not resolve whether the investigatory stop in this case met that constitutional standard because, ultimately, we conclude that under N.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find that sufficient credible evidence in the record supports the findings that Officers Williams and Milton reasonably relied on a dispatch from headquarters and therefore were "lawfully performing an official function"  an attempted investigatory stop  when defendant obstructed their efforts by fleeing.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We affirm, but for different reasons.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we affirm the judgment of the Appellate Division upholding defendant''s conviction of obstruction in violation of N.', 'general', 'State v. Crawley', 'https://www.courtlistener.com/opinion/1998486/', '1998486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these uncontested facts, we hold that police officials could reasonably believe that Hillemeyer had common authority over the box.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that defendant failed to show that he did not receive an impartial trial.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant''s absence from the McCormack conference did not deny him his constitutional rights to an impartial jury, due process of law, or effective assistance of counsel.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that this issue does not warrant our consideration under the plain error doctrine.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant fails the prejudice prong of the Strickland test.', 'ineffective_assistance', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even assuming that the above evidence was erroneously admitted, we conclude that there is no reasonable probability that the result of the trial would have been different.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court adequately inquired into defendant''s allegations of ineffective assistance.', 'ineffective_assistance', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Bull', 'https://www.courtlistener.com/opinion/1998703/', '1998703') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that evidence of the illegitimacy of defendant Bouchee’s four children was inadmissible impeachment evidence in a trial for assault with intent to commit rape because we found such evidence unrelated to the truthfulness or untruthfulness of the defendant or his wife as witnesses.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2192843/', '2192843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the words "evidence offered” applied only to witnesses other than the defendant, and thus that the notice provision did not apply to defendant’s own testimony.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2192843/', '2192843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without deciding whether § 520j embodies a mandatory preclusion sanction if its notice requirement is not met, or whether such a requirement can withstand constitutional scrutiny, we find that the evidence sought to be admitted was irrelevant in the context of this particular case to the asserted defense of consent.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2192843/', '2192843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals and reinstate defendants’ convictions.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2192843/', '2192843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor''s argument detailing the effect of the jury''s finding of an aggravating factor on defendant''s sentence was inaccurate and misleading.', 'sentencing', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, while we are aware that the capable trial judge could not foresee the analysis we undertake today, we conclude that the trial court abused its discretion in overruling defendant''s objection to the State''s argument, which argument contained misleading information.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that the jury''s understanding of aggravating factors is relevant to sentencing, we also find that the prosecutor''s argument introduced error into the trial.', 'sentencing', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we also find that the error was harmless, we affirm the result reached by the Court of Appeals.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because there is no reasonable possibility that but for the error a different result would have been reached, we affirm the result of the Court of Appeals.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals decision upholding the judgments of the trial court.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1292738/', '1292738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no one now serving a mandatory life sentence for murder under former law is entitled to reconsideration of that sentence under the resentencing provisions of the Code, and that the crime of murder under the Code carries a potential life sentence without the necessity of proving an enhancement criterion.', 'sentencing', 'State v. Maguire', 'https://www.courtlistener.com/opinion/2000651/', '2000651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we conclude that in every case (with the possible exception noted in note 10
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the Code the crime of murder is subject to a discretionary extended term of life imprisonment without separate proof of the specific enhancement criteria in section 2C:44-3.', 'general', 'State v. Maguire', 'https://www.courtlistener.com/opinion/2000651/', '2000651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm the decision of the Court of Appeals.', 'general', 'State v. Boslau', 'https://www.courtlistener.com/opinion/2001175/', '2001175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered Boslau’s assignment of error and having concluded that it is without merit, we affirm the decision of the Court of Appeals.', 'general', 'State v. Boslau', 'https://www.courtlistener.com/opinion/2001175/', '2001175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without this corroborating testimony, we conclude that "there is a reasonable probability that, absent the errors, the factfinder would have had a reasonable doubt respecting guilt.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/2208923/', '2208923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Montgomery''s arson convictions are similarly barred under the common law.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/2208923/', '2208923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse his convictions and remand for a new trial
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Montgomery''s convictions.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/2208923/', '2208923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse Montgomery''s convictions and remand for a new trial.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/2208923/', '2208923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we reverse Montgomery''s convictions based upon ineffective assistance, we are compelled to admonish the prosecutor for conduct that gave rise to the ineffectiveness claim.', 'ineffective_assistance', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/2208923/', '2208923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'fl3] Therefore, we hold that Section 5503(b) does not require that the Commonwealth prove that an offender acted with intent to cause substantial
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the evidence fully supported the jury’s finding of guilt on the charge of disorderly conduct as a misdemeanor of the third degree.', 'general', 'Commonwealth v. Fedorek', 'https://www.courtlistener.com/opinion/2355760/', '2355760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 5503(b) requires the Commonwealth to prove in a third-degree misdemeanor disorderly conduct prosecution that the offender acted with intent to cause substantial harm or serious inconvenience, rather than to prove substantial “public” harm or serious “public” inconvenience, and because the Commonwealth did prove in this case that Appellee, Jennifer Ann Fedorek, acted with intent to cause substantial harm, we reverse the Superior Court’s reversal and reinstate the judgment of sentence.', 'sentencing', 'Commonwealth v. Fedorek', 'https://www.courtlistener.com/opinion/2355760/', '2355760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of the Superior Court and reinstate the judgment of sentence.', 'sentencing', 'Commonwealth v. Fedorek', 'https://www.courtlistener.com/opinion/2355760/', '2355760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 38 Although we hold that the exclusionary rule applies because the warrant *578 was void when issued, the State asks us to extend the good-faith exception to the exclusionary rule in Wisconsin to render evidence admissible when it is seized pursuant to a warrant issued without statutory authority.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The dissent overlooks the language leading up to the Janis quote: "To the extent that recent cases state that deterrence is the prime purpose of the exclusionary rule, and that `judicial integrity'' is a relevant, albeit subordinate factor, we hold that in this case considerations of judicial integrity do not require exclusion of the evidence.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that suppression was necessary because the means by which the state procured evidence was in violation of the procedures set out by statute.', 'suppression', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By the same token, we held that suppression of an incriminating statement procured by use of those same documents was necessary to fully protect persons from the state''s failure to comply with the statute.', 'suppression', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held in Kriegbaum that where a magistrate lacked authority to issue a warrant, the search conducted and evidence seized resulted in a constitutional violation.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 46 In Wisconsin, the exclusionary rule dates back to 1923, when this court held that, for "the Bill of Rights as embodied in constitutions to be of substance rather than mere tinsel," a conviction may not rest on unlawfully seized evidence.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 2 We conclude that the good-faith exception to the exclusionary rule does not apply to a situation in which: (1) no facts existed that would justify an arrest without a warrant;', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 68 We conclude that the good-faith exception to the exclusionary rule does not apply to a situation in which: (1) no facts existed that would justify an arrest without a warrant;', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the decision of the court of appeals, State v.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the decision of the court of appeals.', 'general', 'State v. Hess', 'https://www.courtlistener.com/opinion/2214390/', '2214390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, this court held in Mason v.', 'general', 'Steeley v. State', 'https://www.courtlistener.com/opinion/1611015/', '1611015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), this court held that the Uniform Commercial Code does not apply to proceedings under the Worthless Check Act.', 'general', 'Steeley v. State', 'https://www.courtlistener.com/opinion/1611015/', '1611015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the defendant waived arraignment by failing to raise this question in the circuit court.', 'general', 'Steeley v. State', 'https://www.courtlistener.com/opinion/1611015/', '1611015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that, when § 12-22-113 requires that the complaint be "signed" by the district attorney, it does not necessarily mean a written signature as opposed to a signature by print or rubber stamp.', 'general', 'Steeley v. State', 'https://www.courtlistener.com/opinion/1611015/', '1611015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was ample evidence that this offense occurred on April 30, 1985.', 'general', 'Steeley v. State', 'https://www.courtlistener.com/opinion/1611015/', '1611015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances in the present case, we hold that the school had more than enough reason to discipline Douglas for the content of his story.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although we hold that Douglas''s story is not a true threat and, therefore, cannot be punished under § 947.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that purely written speech, even written speech that fails to cause an actual disturbance, can constitute disorderly conduct as defined by § 947.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the First Amendment does not inherently bar the State from applying § 947.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '01, we conclude that the State is not barred from convicting Douglas for the content of his story merely because his story consisted of purely written speech.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the fact that Douglas''s story did not cause an actual disturbance is irrelevant to the present inquiry.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With this in mind, we conclude that Douglas''s story, although we find it to be offensive and distasteful, unquestionably is protected by the First Amendment.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we concluded that the statute could be interpreted to apply to disorderly physical acts.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[16] We therefore hold as a *237 matter of law that Douglas''s story cannot be prosecuted under § 947.', 'general', 'State v. Douglas D.', 'https://www.courtlistener.com/opinion/1611761/', '1611761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing a recent appeal from the denial of post-conviction relief, we held that the Public Defender is not obligated to raise on appeal from a denial for post-conviction relief every issue that the petitioner requests be raised when the issue is clearly not a proper subject for post-conviction relief or is deemed to be a frivolous issue.', 'general', 'Marsillett v. State', 'https://www.courtlistener.com/opinion/2007860/', '2007860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we find that the examination of the checks would aid the jury in a proper consideration of this case.', 'general', 'Marsillett v. State', 'https://www.courtlistener.com/opinion/2007860/', '2007860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 564 (1983), we held that a defendant charged with a third-offense DUI under an earlier version of our current DUI statute had no right to collaterally attack his first- and second-offense convictions in order to prevent them from being used for enhancement.', 'general', 'State v. Louthan', 'https://www.courtlistener.com/opinion/1990048/', '1990048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 571 (1984), where we held that a defendant could properly raise objections under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we held that the petition for a “separate proceeding” was a proper vehicle for asserting the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a defendant may not utilize a special proceeding to col
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 319 (1967), this court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that Louthan’s 1994 DUI conviction was not subject to collateral attack in a separate proceeding and therefore reverse the judgment of the district court and remand the cause with directions to dismiss.', 'dismissal', 'State v. Louthan', 'https://www.courtlistener.com/opinion/1990048/', '1990048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we concluded that the collateral attack was without merit and therefore affirmed.', 'general', 'State v. Louthan', 'https://www.courtlistener.com/opinion/1990048/', '1990048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse, and remand with directions to dismiss.', 'dismissal', 'State v. Louthan', 'https://www.courtlistener.com/opinion/1990048/', '1990048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the due process requirements of both the state and federal Constitutions are satisfied by the right of direct appeal from a plea-based DUI conviction and the procedure set forth in § 60-6,196(3), which permits a defendant to challenge the validity of a prior DUI conviction offered for purposes of enhancement on the ground that it was obtained in violation of the defendant’s Sixth Amendment right to counsel.', 'plea', 'State v. Louthan', 'https://www.courtlistener.com/opinion/1990048/', '1990048') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that a dog can be a dangerous weapon if it is used or intended to be used in a manner calculated or likely to cause death or great bodily harm.', 'general', 'State v. Bodoh', 'https://www.courtlistener.com/opinion/1990109/', '1990109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a dog can be a dangerous weapon if used or intended to be used in a manner calculated or likely to cause death or great bodily harm, and that Bodoh "handled" his dogs in that he was responsible for supervising, directing and controlling them.', 'general', 'State v. Bodoh', 'https://www.courtlistener.com/opinion/1990109/', '1990109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although Bodoh was not physically present when the dogs attacked and bit the young boy, we conclude that he did "handle" the dogs as that term is used in the statutes.', 'general', 'State v. Bodoh', 'https://www.courtlistener.com/opinion/1990109/', '1990109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is sufficient and credible evidence to support the jury''s conclusion that Bodoh "handled" a dangerous weapon.', 'general', 'State v. Bodoh', 'https://www.courtlistener.com/opinion/1990109/', '1990109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the court of appeals.', 'general', 'State v. Bodoh', 'https://www.courtlistener.com/opinion/1990109/', '1990109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 645 (1980), we held that in order to predicate error upon an improper argument to the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In doing so, we affirm his conviction of first-degree theft, with its requirement that the stolen property have a total value of $250 or more.', 'general', 'Hebron v. United States', 'https://www.courtlistener.com/opinion/1990630/', '1990630') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that title insurers are subject to the assessments, and we therefore affirm the action of the Commissioner of Banking and Insurance (Commissioner) imposing them.', 'general', 'Chicago Title Ins. Co. v. Bryan', 'https://www.courtlistener.com/opinion/1990939/', '1990939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that our construction appropriately harmonizes the apparently conflicting provisions of the TIA and IFPA in a manner that avoids an actual conflict and accords with the legislative intent underlying each enactment.', 'general', 'Chicago Title Ins. Co. v. Bryan', 'https://www.courtlistener.com/opinion/1990939/', '1990939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Leasa, we held that a "second" PCRA petition requesting reinstatement of appeal rights as to the order dismissing the petitioner''s first petition would be considered merely an extension of the litigation of the petitioner''s first PCRA petition where the appeal from the denial of the first petition was dismissed because of counsel''s failure to file a brief.', 'dismissal', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1991005/', '1991005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Peterson, we held that a "second" petition raising the same issues as the petitioner''s first petition would be treated as an extension of his first petition where his appeal from the denial of his first petition was dismissed because of counsel''s failure to file a brief.', 'dismissal', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1991005/', '1991005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the totality of the evidence admitted at trial was sufficient to sustain Appellant’s conviction for retail theft.', 'general', 'Commonwealth v. Dent', 'https://www.courtlistener.com/opinion/1991085/', '1991085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 38 Based upon the foregoing, we hold that the totality of the evidence admitted at trial was sufficient to sustain Appellant’s conviction for retail theft.', 'general', 'Commonwealth v. Dent', 'https://www.courtlistener.com/opinion/1991085/', '1991085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this rationale instantly, we find that the testimony challenged herein constitutes inadmissible hearsay.', 'general', 'Commonwealth v. Dent', 'https://www.courtlistener.com/opinion/1991085/', '1991085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellant’s judgment of sentence.', 'sentencing', 'Commonwealth v. Dent', 'https://www.courtlistener.com/opinion/1991085/', '1991085') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons provided herein, we hold that a prior indirect criminal contempt conviction for violation of a PFA order issued under 23 Pa.', 'general', 'Commonwealth v. Bortz', 'https://www.courtlistener.com/opinion/1991047/', '1991047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we conclude that this'' type of prior conviction does constitute grounds to impose a third-degree felony gradation.', 'general', 'Commonwealth v. Bortz', 'https://www.courtlistener.com/opinion/1991047/', '1991047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the Superior Court.', 'general', 'Commonwealth v. Bortz', 'https://www.courtlistener.com/opinion/1991047/', '1991047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the trial court erred in ruling that the convictions could not be used for enhancement purposes.', 'general', 'State v. Olson', 'https://www.courtlistener.com/opinion/1991784/', '1991784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these rules to the case at hand, we find that Slapnicka, in pleading guilty to a third DUI or physical control offense, waived all violations of constitutional rights alleged to have occurred before the guilty plea was entered.', 'plea', 'State v. Olson', 'https://www.courtlistener.com/opinion/1991784/', '1991784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a question of fact exists whether or not Olson waived all defects by his guilty plea in the prior conviction, we reverse and remand for further proceedings.', 'plea', 'State v. Olson', 'https://www.courtlistener.com/opinion/1991784/', '1991784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for further proceedings consistent with this opinion.', 'general', 'State v. Olson', 'https://www.courtlistener.com/opinion/1991784/', '1991784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Briggs we held that the trial court should have conducted the Frendak inquiry where "the trial court itself expressed concerns about productivity based on bizarre pretrial behavior, where competency examinations indicated classic, long-term mental illness, and where appellant has resisted every inquiry into a possible insanity defense.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001), we held that even though pre-trial competency reports indicated the defendant was competent to stand trial and not then suffering from a mental illness, once the issue of the defendant''s mental health was called into question during sentencing the trial court should have, at that time, conducted a Frendak inquiry.', 'sentencing', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989),[19] where we held that "in light of an unchallenged expert''s report finding no productivity," and "[a]fter considering all the evidence before the trial judge at the time of trial, we cannot conclude the record raised a substantial question of the defendant''s sanity at the time of the crime.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held in Logan v.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of Frendak, Briggs and Patton, we conclude that, in this case, there were a number of factors that similarly call into question appellant''s sanity at the time of the offense.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these elements to the evidence at trial, we conclude that the evidence was sufficient  if appellant was not insane  to permit the jury to find that appellant intentionally set fire to his mother''s apartment and its contents and that he did so with conscious disregard of the substantial risk to the property and to the building''s occupants, including his six-year old niece.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the conviction, concluding that the trial court abused its discretion in failing to pursue the issue of insanity "without making a Frendak inquiry and taking *156 whatever [further] steps became necessary as a consequence.', 'general', 'Phenis v. United States', 'https://www.courtlistener.com/opinion/1991039/', '1991039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that the trial court did not err by refusing to hold an evidentiary hearing, as the amount in restitution was already established and agreed-upon as stipulated in the written plea petition as well as on the record orally at the plea hearing.', 'plea', 'Commonwealth v. Rush', 'https://www.courtlistener.com/opinion/1991371/', '1991371') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the amount of restitution ordered by the trial court was supported by the record and was neither speculative nor excessive.', 'general', 'Commonwealth v. Rush', 'https://www.courtlistener.com/opinion/1991371/', '1991371') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Rush', 'https://www.courtlistener.com/opinion/1991371/', '1991371') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Klatt’s conviction of vehicular homicide and remand for entry of judgment of acquittal on this charge.', 'general', 'State v. Klatt', 'https://www.courtlistener.com/opinion/1991589/', '1991589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'Commonwealth v. Smith', 'https://www.courtlistener.com/opinion/1992120/', '1992120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not err in denying appellant’s motion to quash the charges.', 'general', 'Commonwealth v. Smith', 'https://www.courtlistener.com/opinion/1992120/', '1992120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no merit in either argument, we affirm the judgment and sentence of the district court.', 'sentencing', 'State v. Clarke', 'https://www.courtlistener.com/opinion/1992517/', '1992517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these comments have merit, and we hold that the Superior Court did not err when it failed to include an instruction about the bill of particulars in its instructions to the jury.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1993689/', '1993689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 897, 899 (1983), this Court held that “[t]o assure a fair and impartial trial, a jury must be adequately informed by the Court .', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1993689/', '1993689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Superior Court did not err as a matter of law by allowing the State to amend the indictment to add the term “knowingly” and to correct the statutory citation.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1993689/', '1993689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Superior Court did not abuse its discretion by admitting evidence of Roe’s physical and mental condition as it existed at the time of and after the incident.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1993689/', '1993689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 1136(a) against the significant State interest in protecting the residential privacy rights of a “captive” patient or resident of a long-term care facility, we conclude that the patient abuse statute does not reach a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that the allegations that Robinson emotionally abused Roe “by ridiculing, demeaning, and making derogatory remarks directed toward [Jane Roe]” compel the requisite inference that Robinson acted “knowingly” as required by 16
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the amended indictment did not result in a new, additional, or different charge being made against Robinson and that the original indictment placed her on notice of the essential elements of the charge so that she could adequately prepare her defense.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1993689/', '1993689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence of the defendant’s guilt was very strong, and the information improperly put before the jury was not of great prejudicial significance, we find that it was within the sound discretion of the Superior Court to deny the motions for a mistrial and instead to issue an appropriate instruction to the jury to disregard the evidence.', 'mistrial', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1993689/', '1993689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While residents and patients, by necessity, allow others to come into their “home” to help take care of their personal needs, we find that such authorization does not result in a waiver of their right to privacy or their right to be free from sudden and unexpected offensive and insulting conduct or speech.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1993689/', '1993689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that the State satisfied its burden of proving that Robinson performed the above acts “knowingly”;', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1993689/', '1993689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, after a complete analysis, we concluded that DiStefano and Stewart have not been disadvantaged, in violation of the ex post facto prohibition, by the enactment of legislation which makes them generally ineligible for any furlough or work release program.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that 11 Del.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that there are facts which can be reasonably assumed to afford support for the decision of the General Assembly to enact legislation restricting the ability of persons who are convicted of a Class A felony or Class B felony sex offense from interacting with the public, during the first ten years of their confinement.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the proper ex post facto analysis, in a case raising the distinction between a punitive provision and a regulatory one, is not whether the enactment is a statute as opposed to a regulation, but rather "whether the legislative aim was to punish [the offender] for past activity, or whether the restriction.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the finding by the Superior Court that the provisions of Section 6537(b) apply to DiStefano and Stewart.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Superior Court in this case, which held that 11 Del.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Superior Court''s conclusion that there has been no violation of DiStefano''s or Stewart''s right to substantive due process under either the United States Constitution or the Delaware Constitution.', 'general', 'DiStefano v. Watson', 'https://www.courtlistener.com/opinion/2008658/', '2008658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that Indiana code section 35-46-3-12(b) is not unconstitutionally vague as applied to Price.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/1994092/', '1994092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the statute is not unconstitutionally vague as applied to Price and that the evidence was sufficient, we affirm.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/1994092/', '1994092') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that while section 921.', 'general', 'Donaldson v. State', 'https://www.courtlistener.com/opinion/1652321/', '1652321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record contains competent, substantial evidence which supports Donaldson''s convictions.', 'general', 'Donaldson v. State', 'https://www.courtlistener.com/opinion/1652321/', '1652321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, for reasons that follow, we reverse Donaldson''s sentence and remand this case to the trial court for a new penalty-phase proceeding.', 'sentencing', 'Donaldson v. State', 'https://www.courtlistener.com/opinion/1652321/', '1652321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '141(5)(b), we reverse his sentences of death and remand this case to the trial court with instructions to hold a new penalty phase proceeding before a new jury in accord with this opinion.', 'sentencing', 'Donaldson v. State', 'https://www.courtlistener.com/opinion/1652321/', '1652321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed, we affirm Donaldson''s convictions but reverse his sentence of death and remand this case to the trial court for a new penalty-phase proceeding.', 'sentencing', 'Donaldson v. State', 'https://www.courtlistener.com/opinion/1652321/', '1652321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Donaldson''s convictions for two counts of first-degree murder, kidnapping and aggravated child abuse.', 'general', 'Donaldson v. State', 'https://www.courtlistener.com/opinion/1652321/', '1652321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mitchell, this court held administration of psychotropic medication is not equivalent to a bona fide doubt of a defendant''s fitness.', 'general', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that petitioner''s postconviction allegations cannot be characterized as fantastic or delusional.', 'general', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we concluded that these things did not affect his understanding of the proceedings or his ability to participate in his own defense.', 'general', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "no bona fide doubt as to petitioner''s fitness would have existed at the time he pleaded guilty, even if the trial court had been aware of the facts now available.', 'plea', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the dismissal of the postconviction petition, affirm the judgment vacating the assessment of fees and court costs, and remand this matter to the circuit court for second stage postconviction proceedings.', 'dismissal', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the part of the appellate court''s judgment affirming the circuit court''s summary dismissal of petitioner''s postconviction petition.', 'dismissal', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the part of the appellate court''s judgment vacating the assessment of fees and court costs under section 22-105 of the Code.', 'general', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court''s dismissal of the petition without a hearing.', 'dismissal', 'People v. Brown', 'https://www.courtlistener.com/opinion/2255082/', '2255082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 469, 487 (1995), we held that “[a]s a general proposition, we will not disturb a sentence following a criminal conviction if it falls within the range of what is permitted under the statute.', 'sentencing', 'State v. GEORGIUS', 'https://www.courtlistener.com/opinion/1223352/', '1223352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 369, 373-74 (2003), this Court held that the circuit court did not abuse its discretion in denying a Rule 35(b) motion to reconsider where no new arguments or reasons for granting the motion were presented.', 'general', 'State v. GEORGIUS', 'https://www.courtlistener.com/opinion/1223352/', '1223352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed appellant’s conviction of burglary because, we said, there were several explanations of appellant’s actions which would be inconsistent with guilt.', 'general', 'Tiller v. State', 'https://www.courtlistener.com/opinion/1657338/', '1657338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these circumstances, we conclude that sufficient evidence was presented to support the three counts of theft.', 'general', 'Hightower v. State', 'https://www.courtlistener.com/opinion/2026556/', '2026556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the facts presented, we conclude that the State presented sufficient evidence to support Hightower’s conviction for conspiracy with Gutierrez to commit forgery.', 'general', 'Hightower v. State', 'https://www.courtlistener.com/opinion/2026556/', '2026556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm but remand with instructions.', 'general', 'Hightower v. State', 'https://www.courtlistener.com/opinion/2026556/', '2026556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When the sufficiency of the evidence to support a conviction is challenged, “we neither reweigh the evidence nor judge the credibility of the witnesses, and we affirm if there is substantial evidence of probative value supporting each element of the crime from which a reasonable trier of fact could have found the defendant guilty beyond a reasonable doubt.', 'general', 'Hightower v. State', 'https://www.courtlistener.com/opinion/2026556/', '2026556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Wittig v. Hoffart', 'https://www.courtlistener.com/opinion/1697395/', '1697395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Accordingly, we affirm.', 'general', 'Wittig v. Hoffart', 'https://www.courtlistener.com/opinion/1697395/', '1697395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the common-law offense of accessory after the fact is not a cognate offense of murder, and we likewise affirm.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth in this opinion, we hold that the common-law offense of *483 accessory after the fact is not a cognate offense of murder, and that the circuit court did not err in refusing to give such a cognate instruction to the jury.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although several arguments in favor of adopting the federal model are attractive, we hold that this is not the case for such a change, largely because defendant was not entitled to an accessory after the fact instruction under our existing cognate lesser jurisprudence.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After the remand, we reversed on the ground that any error was harmless.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[23] Accordingly, we affirm the judgments of the circuit court and the Court of Appeals.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2114469/', '2114469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred as a matter of law when it determined that Parkhurst lacked standing to seek a protection order and, accordingly, reverse and remand for further proceedings consistent with this opinion.', 'general', 'Parkhurst v. Van Winkle', 'https://www.courtlistener.com/opinion/2029745/', '2029745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for further proceedings.', 'general', 'Parkhurst v. Van Winkle', 'https://www.courtlistener.com/opinion/2029745/', '2029745') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these cireum-stances, we conclude that the taped statement was freely and voluntarily given.', 'general', 'Meadows v. State', 'https://www.courtlistener.com/opinion/2029879/', '2029879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to whether Meadows was prejudiced because of the presence of the uniformed officers in the courtroom, we conclude that he was not.', 'general', 'Meadows v. State', 'https://www.courtlistener.com/opinion/2029879/', '2029879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Were findings necessary, we conclude that the trial court''s statements were sufficient to indicate that the court considered the necessity of Meadows receiving a fair trial and that of keeping open access to the courtroom.', 'general', 'Meadows v. State', 'https://www.courtlistener.com/opinion/2029879/', '2029879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions but remand for reconsideration of the sentences.', 'sentencing', 'Meadows v. State', 'https://www.courtlistener.com/opinion/2029879/', '2029879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that MCL 768.', 'general', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that our restriction of consecutive sentencing authority to the court last in time to impose sentence strikes the appropriate balance between the deterrence sought by the Legislature and the defendant''s right to be accorded due consideration of the effect of a cumulative sentence upon his period of incarceration.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this jurisdiction''s clear preference for concurrent sentencing, we find that a defendant facing the specter of a cumulative *230 term of imprisonment is at a minimum entitled to due consideration of the relationship between the proposed consecutive sentence and any other period of incarceration the defendant may be subject to.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon examination of the underscored language in Rondon, we find that our order could reasonably be construed to sanction consecutive sentencing by the first-in-time sentencing court.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At 424 Mich 864, we reversed and remanded to the trial court for resentencing, stating in relevant part:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals finding that the first-in-time sentencing court lacked discretionary consecutive sentencing authority.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[16] Accordingly, while we affirm in part the decision of the Court of Appeals holding the first-in-time sentencing court lacked *232 discretionary consecutive sentencing authority, we vacate defendant''s sentences for both felony convictions and remand to the trial court for resentencing in accordance with this opinion.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We therefore hold that the prerogative of consecutive sentencing is accorded only to the court last in time to impose sentence.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the cocaine found in the pill bottle in Mr.', 'general', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a unanimous opinion authored by Justice Levin, this Court held that a search without a warrant of persons whom the police had probable cause to arrest was proper, even though the persons searched had not been formally arrested.', 'probable_cause', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With due deference to the trial court''s findings, we conclude that, upon feeling the pill bottle, under a totality of the circumstances, the officer had probable cause to believe that the pill bottle contained contraband.', 'probable_cause', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that [the officer] possessed probable cause to believe that the pill bottle contained crack cocaine.', 'probable_cause', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', the defendant''s furtive behavior, his refusal to remove his hands from his sweatpants, the officer''s recognition of defendant, and his knowledge of defendant''s past involvement in drug crimes, that we find that *860 removal of this particular pill bottle was authorized.', 'general', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse that Court''s holding that cocaine found in a pill bottle on the defendant''s person during a patdown search was inadmissible.', 'general', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse the Court of Appeals ruling that the cocaine found in the defendant''s possession was unlawfully seized.', 'general', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, although only defendant Charles Meyers objected to the information at the arraignment, we hold that the 120-day period was tolled with respect to defendant Daniel Meyers as well because he was present at the arraignment when the objection was made and made no objection to the obvious delay that was to ensue.', 'general', 'People v. Waclawski', 'https://www.courtlistener.com/opinion/1703326/', '1703326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we conclude that the circuit court did not clearly err by holding that the 239-day delay caused by this Court’s February 14, 2007, order staying proceedings would not count toward the running of the 120-day deadline set by the IAD.', 'general', 'People v. Waclawski', 'https://www.courtlistener.com/opinion/1703326/', '1703326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that defendant was not prejudiced by the delay.', 'general', 'People v. Waclawski', 'https://www.courtlistener.com/opinion/1703326/', '1703326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although a 24-month delay is presumptively prejudicial and defendant did assert his right to a speedy trial, because the reasons for the delay weighed against defendant and defendant’s ability to prepare a defense was not prejudiced, we conclude that the trial court properly held that defendant’s right to a speedy trial was not violated!
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that the challenged evidence clearly demonstrates both intent and identity, as well as common scheme, plan, or system.', 'general', 'People v. Waclawski', 'https://www.courtlistener.com/opinion/1703326/', '1703326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the definition of “fellatio” as adopted by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that while somewhat imperfect, the jury instructions make clear that the prosecutor must demonstrate entry into defendant’s mouth by the victim’s penis and, as a result, fairly presented the issues to be tried and sufficiently protected defendant’s rights.', 'jury_instruction', 'People v. Waclawski', 'https://www.courtlistener.com/opinion/1703326/', '1703326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court properly scored defendant 10 points for OV 9 because the record supports the inference that at least two other victims were placed in danger of physical injury when the sentencing offenses were committed.', 'sentencing', 'People v. Waclawski', 'https://www.courtlistener.com/opinion/1703326/', '1703326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that all these challenges are baseless.', 'general', 'People v. Waclawski', 'https://www.courtlistener.com/opinion/1703326/', '1703326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'merit relief, we affirm.', 'general', 'People v. Waclawski', 'https://www.courtlistener.com/opinion/1703326/', '1703326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court did not commit error by allowing the examiner to testify regarding his opinion that Overall''s death was a homicide.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the examiner''s testimony regarding the opinions of the nontestifying experts was inadmissible hearsay.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the admission of the hearsay evidence from nontestifying experts was harmless beyond a reasonable doubt because there is no reasonable possibility that the wrongfully admitted evidence could have affected the jury''s verdict.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the search warrant was supported by probable cause.', 'probable_cause', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that admission of any evidence that was not in plain view of the officers was harmless error beyond a reasonable doubt.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we hold that the court properly concluded that Bradford invoked his right to counsel, but then waived that right after reinitiating a conversation with the police.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the substantial amount of other admissible evidence at trial that demonstrated a pattern of domestic abuse, if the court erred by admitting the affidavit, we hold that such error is harmless beyond a reasonable doubt.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we acknowledge that there was a substantial amount of admissible evidence demonstrating a past pattern of domestic abuse, we hold that this error was also harmless beyond a reasonable doubt.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the substantial evidence of Bradford''s guilt compared with the isolated nature of this conduct, we hold that this prosecutorial misconduct was harmless beyond a reasonable doubt.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that heat-of-passion manslaughter is not a lesser-included mitigating offense of first-degree domestic abuse murder.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the exemption clearly does not encompass the defendant''s conduct because the exemption does not, under any circumstances, authorize the possession of child pornography.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that if an indictment or county attorney''s information facially shows a charge on which the State may not constitutionally prosecute, then a plea of guilty subsequent to an adverse ruling on a demurrer does not waive the claimed unconstitutionality as "no offense is stated.', 'plea', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant''s conduct clearly falls outside the parameters of the statutory exemption.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if this issue had been preserved, it would not alter the outcome here, because we hold that under no reasonable construction of the statute would a person of ordinary intelligence conclude that the legislature intended to permit the use of child pornography, inside or outside school.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Schrup, we held that a defendant could not be charged with the mere possession of obscene materials without also having the intent to distribute them.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our Hunter case, this court held that a guilty plea did not waive the defendant''s right to claim on appeal that the statute under which he was charged was unconstitutionally vague.', 'plea', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In response to an attempt to expand a statute to include certain areas not listed, this court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under no construction of the statute would a reasonably intelligent person believe that such material, showing children engaged in sexual acts, is "appropriate.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the defendant''s conviction, but preserve his ineffective-assistance-of-counsel claim.', 'ineffective_assistance', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when law enforcement has probable cause to believe a defendant has committed the offense of criminal vehicular homicide or operation under Minn.', 'probable_cause', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Two years later in Aguirre, we held that a nonconsensual, warrantless removal of a suspect''s blood did not violate the Fourth Amendment when an officer "had probable cause to believe that defendant driver was not only intoxicated but had just committed the felony offense of criminal negligence resulting in death.', 'probable_cause', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Paul, this court held that the police, who were in hot pursuit of a suspected DWI offender, could make a warrantless entry into the defendant''s home in order to effectuate arrest.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these special facts, we conclude that the attempt to secure evidence of blood-alcohol content in this case was an appropriate incident to petitioner''s arrest.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that when officers have probable cause to believe a defendant has committed the offense of criminal vehicular homicide or operation under Minn.', 'probable_cause', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today we conclude that in the case of criminal vehicular operation the undisputed rapid dissipation of alcohol in the defendant''s blood creates a single-factor exigent circumstance.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, due to the passage of time after the accident, immediate action was required to avoid the loss of blood-alcohol content evidence.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we found that "the need to preserve evidence of [the defendant''s] blood alcohol level is a compelling exigent circumstance under the `destruction of evidence'' exception to the warrant requirement first recognized [in Schmerber].', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that "the need to preserve evidence of Paul''s blood alcohol level is a compelling exigent circumstance," id.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We find that the continuance of “at least 60 days” was still in effect until at least May 17, the date when the court said the case would be tried.', 'general', 'State v. Dailey', 'https://www.courtlistener.com/opinion/2009843/', '2009843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the appeal is resolved by § 29-1207(4)(b), we need not address the trial court’s finding that time could also be excluded for good cause under § 29-1207(4)(f).', 'general', 'State v. Dailey', 'https://www.courtlistener.com/opinion/2009843/', '2009843') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that section 5-8-1(a)(1)(c)(ii) complies with article I, section 11, of the Illinois Constitution, and suffers from no constitutional infirmity.', 'general', 'People v. Wooters', 'https://www.courtlistener.com/opinion/2012163/', '2012163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that sections 15-1508 and 15-1701, as embodied in Public Act 89-203, *1112 are unrelated to the subjects of "law enforcement" and "crime.', 'general', 'People v. Wooters', 'https://www.courtlistener.com/opinion/2012163/', '2012163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we hold that Public Act 89-203 violates the single subject clause of the Illinois Constitution *1114 (Ill.', 'general', 'People v. Wooters', 'https://www.courtlistener.com/opinion/2012163/', '2012163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1026 (1995), this court held that mandatory life imprisonment can be harmonized with article I, section 11.', 'general', 'People v. Wooters', 'https://www.courtlistener.com/opinion/2012163/', '2012163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, the State requested that the court apply a harmless error standard to the court''s construction of Public Act 89-404, which this court held violated the single subject rule.', 'general', 'People v. Wooters', 'https://www.courtlistener.com/opinion/2012163/', '2012163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, contrary to the State''s interpretation of Rembert, the Rembert decision in fact demonstrates that the impetus to enact sections 15-1508 and 15-1701 flows from concerns unrelated to crime.', 'general', 'People v. Wooters', 'https://www.courtlistener.com/opinion/2012163/', '2012163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we affirm the 25-year sentence imposed by the circuit court on the sole basis that section 5-8-1(a)(1)(c)(ii) violates the single subject clause of the Illinois Constitution.', 'sentencing', 'People v. Wooters', 'https://www.courtlistener.com/opinion/2012163/', '2012163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IV, § 8), and therefore, we affirm the judgment of the circuit court.', 'general', 'People v. Wooters', 'https://www.courtlistener.com/opinion/2012163/', '2012163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '419 (1931), this court held that no error occurred when nothing in the record demonstrated that the Chicago attorney rendered any material aid to the district attorney in preparing the case for trial or that the Chicago attorney was present at the trial.', 'general', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*211 Even assuming that the officer''s conduct constituted the unauthorized practice of law, we conclude that suppression is not required in this case.', 'suppression', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In turn, we conclude that the court of appeals'' decision must be reversed, and Noble''s perjury conviction must be reinstated.', 'general', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the suppression of Noble''s testimony is not required in this case.', 'suppression', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the facts in this case do not support a finding of a due process violation.', 'general', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that, even assuming that the unauthorized practice of law was present in this case, suppression is not a valid remedy in this instance.', 'suppression', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we disagree with the court of appeals'' decision to suppress Noble''s testimony, and accordingly, we reverse the court''s decision overturning Noble''s conviction.', 'suppression', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because each amended section dealt in some fashion with reoffenders, we conclude that the statute meets that test.', 'general', 'Grant v. State', 'https://www.courtlistener.com/opinion/1707899/', '1707899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, *522 we conclude that Grant is prohibited from raising any argument that the Act is unconstitutionally vague.', 'general', 'Grant v. State', 'https://www.courtlistener.com/opinion/1707899/', '1707899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Grant v. State', 'https://www.courtlistener.com/opinion/1707899/', '1707899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we find that the statute does not give the trier of fact unstructured and unlimited discretion.', 'general', 'People v. Richards', 'https://www.courtlistener.com/opinion/1708106/', '1708106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Richards', 'https://www.courtlistener.com/opinion/1708106/', '1708106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred in instructing the jury that the State need only establish that the defendant intended to do the act that damaged the property.', 'general', 'State v. Li-Yu Chang', 'https://www.courtlistener.com/opinion/2015283/', '2015283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record and considering the arguments of the parties, we reverse the criminal-mischief conviction due to errors in instructing the jury, and we affirm the conviction for assaulting a police officer.', 'general', 'State v. Li-Yu Chang', 'https://www.courtlistener.com/opinion/2015283/', '2015283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction for second-degree criminal mischief and remand that charge to the district court for a new trial.', 'general', 'State v. Li-Yu Chang', 'https://www.courtlistener.com/opinion/2015283/', '2015283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the *125 better approach treats similar fact evidence as simply relevant to corroborate the victim''s testimony, and recognizes that in such cases the evidence''s probative value outweighs its prejudicial effect.', 'general', 'Heuring v. State', 'https://www.courtlistener.com/opinion/1708966/', '1708966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions but remand this cause with instructions to modify the sentence.', 'sentencing', 'Fointno v. State', 'https://www.courtlistener.com/opinion/2017317/', '2017317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the circuit court plainly erred in its jury instructions regarding the charge of first degree robbery and, accordingly, we vacate Cordeiro''s conviction of and sentence for first degree robbery and remand for further proceedings consistent with this opinion.', 'sentencing', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the failure of count 4 of the Blaisdell indictment either to *709 name the person against whom Cordeiro allegedly used force or the victim of the theft did not render the charge fatally defective in this case.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Correlatively, "inasmuch as we cannot say that there was no reasonable possibility that the circuit court''s error contributed to [Cordeiro''s] conviction[], we hold that the error was not harmless beyond a reasonable doubt[.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ']" Inasmuch as HRS § 708-840(1)(b)(i) does not require that a defendant use force in order to compel another person to acquiesce in his or her taking of property, we hold that it is not an element (i.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not err in failing to instruct the jury that the "victim" of the theftwhether the person against whom force is used or the owner of the property takenmust be aware of the theft.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" For the reasons discussed infra, we hold that the circuit court did not err in granting the prosecution''s motions for consolidation.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that circuit court did not plainly err in determining that the public interest in judicial economy outweighed any potential prejudice to Cordeiro and, accordingly, in granting the prosecution''s motions for consolidation of the attempted first degree murder charges with the charges in the Blaisdell case.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[25] Accordingly, we hold that the circuit *722 court did not err in striking Hill from the witness list.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, "assuming that the damaging potential of the cross-examination were fully realized," we hold that there is no reasonable possibility that it would have changed the outcome of Cordeiro''s trial.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the circuit court did not abuse its discretion in limiting the scope of Cordeiro''s defense counsel''s cross-examination, insofar as the circuit court merely excluded irrelevant and repetitious questions by defense counsel and the exclusions did not result in any "manifest prejudice" to Cordeiro.', 'general', 'State v. Cordeiro', 'https://www.courtlistener.com/opinion/2629770/', '2629770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Wilson v. Jackson', 'https://www.courtlistener.com/opinion/2018028/', '2018028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of the trial court granting a plenary order of protection in favor of the petitioner.', 'general', 'Wilson v. Jackson', 'https://www.courtlistener.com/opinion/2018028/', '2018028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we find that the judgment of the circuit court of Kane County was not against the manifest weight of the evidence.', 'general', 'People v. Fortney', 'https://www.courtlistener.com/opinion/2019758/', '2019758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Fortney', 'https://www.courtlistener.com/opinion/2019758/', '2019758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wheelock, supra, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that "[a]n explanation of the `tourist standard'' was properly omitted from the jury instructions in this case because it is not an element of any offense.', 'jury_instruction', 'Hasty v. United States', 'https://www.courtlistener.com/opinion/1983627/', '1983627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We conclude that the narrow construction accorded by this court to D.', 'general', 'Hasty v. United States', 'https://www.courtlistener.com/opinion/1983627/', '1983627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was the State’s burden to show both that Ransom’s consent was voluntary and that there was a break in the causal connection between the unlawful stop and the evidence obtained.', 'general', 'Ransom v. State', 'https://www.courtlistener.com/opinion/2034279/', '2034279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court abused its discretion in not suppressing the handgun.', 'suppression', 'Ransom v. State', 'https://www.courtlistener.com/opinion/2034279/', '2034279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Ransom v. State', 'https://www.courtlistener.com/opinion/2034279/', '2034279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Zaccaro, this Court held that a search warrant was not required under Article 11 for the introduction of evidence obtained through undercover activity, where the State proved that the officer was invited into the defendant''s home in order to purchase cocaine.', 'general', 'State v. Blow', 'https://www.courtlistener.com/opinion/2104535/', '2104535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that warrantless electronic participant monitoring conducted in a home offends the core values of Article 11.', 'general', 'State v. Blow', 'https://www.courtlistener.com/opinion/2104535/', '2104535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '404(a)(1), we conclude that the court erred.', 'general', 'State v. Blow', 'https://www.courtlistener.com/opinion/2104535/', '2104535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand on all counts.', 'general', 'State v. Blow', 'https://www.courtlistener.com/opinion/2104535/', '2104535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Doing so, we hold that, based on public policy grounds, a claim for common-law negligence cannot be maintained against social hosts, such as the Niesens, *223 who allegedly were aware that minors on their property were consuming alcohol, but who did not provide the alcohol, when an underage guest later allegedly caused an alcohol-related car accident.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Doing so, we hold that, based on public policy grounds, a claim for common-law negligence cannot be maintained against social hosts, such as the Niesens, who allegedly were aware that minors on their property were consuming alcohol, but who did not provide the alcohol, when an underage guest later allegedly caused an *234 alcohol-related car accident.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we concluded that the defendant had breached a duty that he owed to the plaintiff by not following through on his promise to drive his intoxicated co-worker home, we held that the plaintiffs claim should have been dismissed.', 'dismissal', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 37 In Hoida, we held that a subcontractor who incurred losses on a construction project, when the general contractor and the property owner fraudulently misappropriated about $650,000 of the project''s construction loan proceeds, had not provided sufficient facts to controvert the defendant-lenders'' "prima facie showing that it did not breach the duty of ordinary care under the circumstances.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While this court found that Tynan owed Rockweit a duty of care under Wisconsin law, we held that public policy factors precluded liability against Tynan, even though Rockweit had established all four elements of a commonlaw negligence claim.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 41 We held that "`once it is determined that a negligent act has been committed and that the act is a substantial factor in causing the harm, the question of duty is irrelevant and a finding of nonliability can be made only in terms of public policy.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 42 The Rockweit court then listed the six public policy factors described in detail previously in this opinion, and we held that the imposition of liability against Tynan, who did not "start, maintain, or provide any necessary incendiary materials for the fire[,] .', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, "although Tynan owed Anthony a duty of ordinary care which the jury determined was breached, .', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Koback, this court held that furnishing or giving alcoholic beverages to a minor constituted negligence per se and that social hosts were liable to third parties in proportion to the extent to which the provision of alcohol led to the harm.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this sixth factor is applicable to preclude liability against the Niesens.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court’s ruling failed to give Buchanan sufficient latitude to present evidence that could tend to make the existence of a consequential fact — that he intended to traffick in oxycodone — less probable than it would be without the evidence.', 'general', 'State v. Buchanan', 'https://www.courtlistener.com/opinion/2344458/', '2344458') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the child abduction statute creates an unconstitutional mandatory presumption, but the application of the presumption in this case was harmless error.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these facts, we conclude that the charges in the subsequent indictments are not “new and additional” for purposes of defendant’s speedy-trial challenge.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, we conclude that the child abduction statute is not unconstitutionally vague as applied to defendant.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with Pomykala, we conclude that the plain meaning of the phrase “shall be prima facie evidence” in section 10 — 5(b)(10) is that the ultimate fact must be presumed upon proof of the predicate facts unless disproved by evidence to the contrary.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court considered all of the evidence in finding defendant guilty.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the finding of guilt based upon all the evidence of defendant’s unlawful purpose would have been the same in the absence of the presumption.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that this statutory language could not reasonably be construed as creating a permissive presumption but, rather, it created an unconstitutional mandatory presumption.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the original indictments sufficiently notified defendant of the charges for the purpose of preparing a defense.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the indictment and the State’s disclosures were sufficient to enable defendant to prepare his defense.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this evidence, considered independently of the presumption in section 10 — 5(b)(10), overwhelmingly establishes defendant’s unlawful purpose in luring the children into his residence.', 'general', 'People v. Woodrum', 'https://www.courtlistener.com/opinion/2036554/', '2036554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the issue is a close one, we hold that the evidence of Gates''s actual malice was not clear and convincing.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we held that while a message may be false and defamatory as a whole, even though no single statement is false, proof of actual malice requires clear and convincing evidence that the defendant "knew or strongly suspected that the publication as a whole could present a false and defamatory impression.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with the court of appeals that only the one defendant is liable for defamation, but we conclude that the jury''s finding of $7 million in mental anguish damages has no evidentiary support and is excessive as a matter of law by constitutional standards.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Judging Gates''s words from the perspective of a reasonable listener, as we must, we conclude that they could easily have been considered defamatory as the jury found.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence that Bunton acted with actual malice in defaming Bentley was clear and convincing.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the First Amendment requires appellate review of amounts awarded for non-economic damages in defamation cases to ensure that any recovery only compensates the plaintiff for actual injuries and is not a disguised disapproval of the defendant.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Exercising that review in this case, we conclude that while the record supports Bentley''s recovery of some amount of mental anguish damages, it does not support the amount of those damages found by the jury.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we conclude that there is no evidence to support part of the actual damage award, punitive damages must be reassessed as well.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is legally and factually sufficient to support the jury''s award of $7,150,000.', 'general', 'Bentley v. Bunton', 'https://www.courtlistener.com/opinion/1773871/', '1773871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that there was other sufficient value testimony by Smith and that the appellant failed to show prejudice, we do not address this issue.', 'general', 'Ross v. State', 'https://www.courtlistener.com/opinion/1775324/', '1775324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm.', 'general', 'Ross v. State', 'https://www.courtlistener.com/opinion/1775324/', '1775324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that defendant’s conviction for first degree murder should not be reduced.', 'general', 'People v. Rodriguez', 'https://www.courtlistener.com/opinion/2039006/', '2039006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm defendant’s convictions for intentional murder, aggravated discharge of a firearm and reckless discharge of a firearm, vacate defendant’s convictions and sentences for knowing and felony murder and remand the cause to the circuit court of Cook County solely for resentencing upon defendant’s conviction for intentional murder.', 'sentencing', 'People v. Rodriguez', 'https://www.courtlistener.com/opinion/2039006/', '2039006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm defendant’s conviction for intentional first degree murder and decline defendant’s invitation to reduce his sentence to second degree murder, we need not address this argument.', 'sentencing', 'People v. Rodriguez', 'https://www.courtlistener.com/opinion/2039006/', '2039006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'Groves v. State', 'https://www.courtlistener.com/opinion/2041665/', '2041665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the trial court''s classification of Groves''s good time credit as Class III and reverse and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Milliner v. State', 'https://www.courtlistener.com/opinion/2042518/', '2042518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Milliner''s conviction for failing to register as a sex offender.', 'general', 'Milliner v. State', 'https://www.courtlistener.com/opinion/2042518/', '2042518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is no merit to Albers'' argument.', 'general', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to Albers'' reading of the statute, we conclude that under the first sentence of § 29-2261(6), a prosecutor is included in the category of "others entitled by law to receive" the information in the PSI and that therefore the sentencing court is not required to make a determination of the defendant''s best interest before allowing the prosecutor to review the PSI.', 'sentencing', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we conclude that prosecutors are included in the group comprising "others entitled by law" to disclosure of the information in the PSI.', 'general', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that prosecutors are among the "others entitled by law to receive" the information in a PSI under § 29-2261(6).', 'general', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The sentences were within statutory limits, and we conclude that the sentences imposed were not an abuse of discretion and therefore not excessive.', 'sentencing', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the factors noted above, we determine that the county court did not abuse its discretion by imposing concurrent sentences of 365 days'' imprisonment for the three convictions, and we conclude that the district court did not err in affirming such sentences.', 'sentencing', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that prosecutors are among the "others entitled to receive" information from the PSI under § 29-2261(6) and that therefore the county court did not err in overruling Albers'' motion to preclude review of the PSI by the prosecuting authority.', 'general', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore conclude that the district court did not err in affirming the foregoing rulings, and we affirm the decision of the district court.', 'general', 'State v. Albers', 'https://www.courtlistener.com/opinion/2043176/', '2043176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of these facts, we conclude that Count II was sufficient to give Malloy notice of the offense and the allegations of the State, thus allowing him to prepare his defense.', 'general', 'Malloy v. State', 'https://www.courtlistener.com/opinion/2374548/', '2374548') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the Fourth Amendment, Officer Englert''s inventory search was lawful, and the evidence seized is admissible.', 'search_seizure', 'Abran v. State', 'https://www.courtlistener.com/opinion/2043902/', '2043902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'scheme runs afoul of the Sixth Amendment for the reasons articulated in Blakely, we conclude that this finding would have no effect on Abran''s sentence.', 'sentencing', 'Abran v. State', 'https://www.courtlistener.com/opinion/2043902/', '2043902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we find that Officer Englert''s decision to impound the truck to protect Abran''s property was reasonable.', 'general', 'Abran v. State', 'https://www.courtlistener.com/opinion/2043902/', '2043902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'particularly considering the very volatile and dangerous nature of certain chemicals used to'' manufacture methamphetamine, we find that Officer Englert''s search of the truck was reasonable under Article 1, Section 11.', 'general', 'Abran v. State', 'https://www.courtlistener.com/opinion/2043902/', '2043902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Abran v. State', 'https://www.courtlistener.com/opinion/2043902/', '2043902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On our de novo review, we find that trial counsel was aware of the probability Anfinson suffered from postpartum depression after Jacob’s birth and categorically rejected any suggestion that this condition be explored in her defense.', 'general', 'Anfinson v. State', 'https://www.courtlistener.com/opinion/2044327/', '2044327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Anfinson’s conviction and remand this case to the district court for a new trial.', 'general', 'Anfinson v. State', 'https://www.courtlistener.com/opinion/2044327/', '2044327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the holding.', 'general', 'Bates v. Bates', 'https://www.courtlistener.com/opinion/2376259/', '2376259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004), we held that a trial court did not have authority to order a defendant to serve less than the entire amount of a previously suspended sentence upon revocation of probation.', 'sentencing', 'Sanders v. State', 'https://www.courtlistener.com/opinion/2044037/', '2044037') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not abuse its discretion by ordering Sanders to serve her suspended sentence.', 'sentencing', 'Sanders v. State', 'https://www.courtlistener.com/opinion/2044037/', '2044037') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Sanders v. State', 'https://www.courtlistener.com/opinion/2044037/', '2044037') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the trial court''s revocation of Sanders''s probation.', 'general', 'Sanders v. State', 'https://www.courtlistener.com/opinion/2044037/', '2044037') ON CONFLICT DO NOTHING;
