INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'No other error appearing, we affirm.', 'general', 'State v. Foster', 'https://www.courtlistener.com/opinion/2048637/', '2048637') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Garrard', 'https://www.courtlistener.com/opinion/2397121/', '2397121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, by omitting such language from the provision at issue, the legislature intended to make an inmate convicted of CDV 3rd ineligible to receive good time and earned work credits to reduce the time they are required to serve below the mandatory minimum of one year.', 'general', 'Nelson v. Ozmint', 'https://www.courtlistener.com/opinion/2397222/', '2397222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence and reasonable inferences therefrom satisfied the State''s burden of proving the requisite state of mind beyond a reasonable doubt.', 'general', 'Armour v. State', 'https://www.courtlistener.com/opinion/2050701/', '2050701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we disagree with the Appellate Division''s resolution of defendant''s double jeopardy argument, we reverse the judgment below and reinstate the original three-to-five year aggregate custodial sentence.', 'sentencing', 'State v. Ryan', 'https://www.courtlistener.com/opinion/2050654/', '2050654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Storey, this Court held that "in the absence of circumstances which put a reasonable man on notice of impending danger, a driver on a dual highway with a green light in his favor has the right to assume that he could traverse the intersection safely and that cross traffic would *1051 stop in obedience to the red light.', 'general', 'Bullock v. State', 'https://www.courtlistener.com/opinion/2050915/', '2050915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[53] Under plain error review, we found that the "jury instructions were erroneous as a matter of law.', 'jury_instruction', 'Bullock v. State', 'https://www.courtlistener.com/opinion/2050915/', '2050915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we REVERSE the judgment of the Superior Court and REMAND this case for a new trial.', 'general', 'Bullock v. State', 'https://www.courtlistener.com/opinion/2050915/', '2050915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing principles, we hold that, in order to facilitate sentencing under Yarbough in vehicular homicide cases, the multiple-victims factor is entitled to great weight and should ordinarily result in the imposition of at least two consecutive terms when multiple deaths or serious bodily injuries have been inflicted upon multiple victims by the defendant.', 'sentencing', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we do not adopt a per se rule, we conclude that it was not an abuse of the trial court''s discretion to impose consecutive sentences.', 'sentencing', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering also that the trial court was in a far better position to develop a "feel of the case" than was the Appellate Division, we conclude that the Appellate Division should not have disturbed the trial court''s finding that defendant was likely to re-offend.', 'general', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Appellate Division''s *499 judgment and reinstate the trial court''s sentences.', 'sentencing', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division and reinstate the trial court''s original sentence.', 'sentencing', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that defendant''s conduct does not justify the heightened charge.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the State argues that "from the person" may apply equally to items attached to and nearby the victim, we find that this is contrary to the common law understanding of the term.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that "and custody of another" refers to the area immediately within one''s control or presence, distinguishable from one''s person.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it was not, because defendant''s conduct did not satisfy any of the factors traditionally used by other jurisdictions that have similarly interpreted larceny from the person.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Brennan', 'https://www.courtlistener.com/opinion/2050989/', '2050989') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the statute is not unconstitutionally vague as applied to Bailey''s conduct.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wick, this court held that the former aggravated arson statute (Ill.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that Bailey lacks standing to raise a facial challenge to the statute because the statute does not implicate first amendment rights and because Bailey''s conduct clearly falls within the proscription of the statute.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that section 110-6.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, we conclude that the admission of the hotel and medical records would not have affected the outcome of the trial.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the enactment of the stalking statute, we find that the legislature only sought to prohibit conduct that was not constitutionally protected.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, because the statute only encompasses activities performed without lawful authority, we find that it does not implicate any other constitutionally protected activity.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we find that the statute''s proscriptions convey sufficiently clear standards as to avoid its arbitrary enforcement.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the extent that Coyne argues that the picketing exemption unconstitutionally discriminates against picketing at a workplace during a "bona fide labor dispute" and picketing occurring elsewhere, we find that Coyne lacks standing to make such an argument.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a rational basis exists for exempting picketing during a bona fide labor dispute from the purview of the statute.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court improperly dismissed the defendant’s petition.', 'dismissal', 'People v. Hall', 'https://www.courtlistener.com/opinion/2051625/', '2051625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 129, 134 (1983), where we held that a waiver of counsel in a probation revocation proceeding is invalid unless the court admonishes the defendant as to the purpose of the proceeding and the nature of the alleged violation, as well as his rights of confrontation, cross-examination, and representation by counsel, provide additional guidance.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2051625/', '2051625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that due process concerns did not necessitate Rule 402 admonitions for defendants admitting probation violations.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2051625/', '2051625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons we have discussed, we reverse the judgments of the appellate and circuit courts and remand to the circuit court for further proceedings.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2051625/', '2051625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Amtrak was not entitled to judgment on the pleadings.', 'plea', 'National RR Passenger Corp. v. Everton by Everton', 'https://www.courtlistener.com/opinion/2053761/', '2053761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the injury was intentional and further held that the intoxicated plaintiff could not recover under the Comparative Fault Act, which expressly exeludes *368 intentional acts.', 'general', 'National RR Passenger Corp. v. Everton by Everton', 'https://www.courtlistener.com/opinion/2053761/', '2053761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Everton has alleged facts sufficient to establish that Amtrak owed him a duty under the Dram Shop Act.', 'general', 'National RR Passenger Corp. v. Everton by Everton', 'https://www.courtlistener.com/opinion/2053761/', '2053761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'National RR Passenger Corp. v. Everton by Everton', 'https://www.courtlistener.com/opinion/2053761/', '2053761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the trial judge improperly considered a 1974 Florida conviction *122 for aggravated assault because the State did not prove that the prior offense was a felony, in sentencing appellant under the Alabama Habitual Felony Offenders Act.', 'sentencing', 'Cushing v. State', 'https://www.courtlistener.com/opinion/1719499/', '1719499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To avoid such collateral consequences, we conclude that a court should not admit into evidence in a criminal proceeding a prior statement made by a prosecutor unless the court concludes that the three guidelines established in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying those guidelines in this case, we conclude that statements ADA Smith made in the drug case were not admissible in the defendant''s perjury trial as admissions of a party-opponent under Wis.', 'general', 'State v. Cardenas-Hernandez', 'https://www.courtlistener.com/opinion/2054641/', '2054641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we conclude that ADA Smith''s statements in the drug case fail the first
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm the court of appeals'' decision reversing the defendant''s two convictions for criminal defamation because we conclude that the absolute civil privilege for statements made in judicial proceedings applies to criminal defamation under Wis.', 'general', 'State v. Cardenas-Hernandez', 'https://www.courtlistener.com/opinion/2054641/', '2054641') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And, because we hold that he was competent to exercise his right to proceed pro se, we do not reach the contention that there are two separate and distinct levels of mental capacity — one to stand trial, another to waive counsel.', 'general', 'State v. Ahearn', 'https://www.courtlistener.com/opinion/2054754/', '2054754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Otte v. State', 'https://www.courtlistener.com/opinion/2436043/', '2436043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no error in the trial court''s Criminal Rule 4(D) continuance or its admission of Creekbaum''s testimony, we affirm the trial court on both grounds.', 'general', 'Otte v. State', 'https://www.courtlistener.com/opinion/2436043/', '2436043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Being unpersuaded by these challenges, we affirm.', 'general', 'Chavez-Quintanilla v. United States', 'https://www.courtlistener.com/opinion/2078009/', '2078009') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the phrase “any person” has a commonly understood and ordinary meaning.', 'general', 'People v. Ellis', 'https://www.courtlistener.com/opinion/2079415/', '2079415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that public policy considerations, while legitimate, do no necessitate adoption of the exculpatory no doctrine in this context.', 'general', 'People v. Ellis', 'https://www.courtlistener.com/opinion/2079415/', '2079415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the plain language of section 31 — 4(a) of the Code negates defendant’s argument that the exculpatory no doctrine insulates him from criminal liability.', 'general', 'People v. Ellis', 'https://www.courtlistener.com/opinion/2079415/', '2079415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'People v. Ellis', 'https://www.courtlistener.com/opinion/2079415/', '2079415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that: (1) the mandatory sentencing provision of the statute is not an
