INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the rule clarified in the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶2     We conclude that revoking West’s suspended sentence notwithstanding the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that this issue
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶39    For these reasons, we conclude that the factual record presently before us is not
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the sentence imposed by the trial court is valid and must be affirmed.', 'sentencing', 'State v. Bieniek', 'https://www.courtlistener.com/opinion/2056765/', '2056765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In respect of the issue raised by the panel about whether the court recognized that it need not accept the sentence in the negotiated plea agreement, we find that there was no basis whatsoever for questioning the trial court''s understanding of its authority.', 'sentencing', 'State v. Bieniek', 'https://www.courtlistener.com/opinion/2056765/', '2056765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division and reinstate the sentence imposed by the trial court.', 'sentencing', 'State v. Bieniek', 'https://www.courtlistener.com/opinion/2056765/', '2056765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, because the defendant’s attorney, usually essential in reconstructing the record, had been accused of providing ineffective assistance at sentencing, we concluded that “the absence of a transcript in the circumstances of this ease” rendered the record inadequate for appellate review.', 'sentencing', 'State v. Milliken', 'https://www.courtlistener.com/opinion/2056790/', '2056790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Milliken', 'https://www.courtlistener.com/opinion/2056790/', '2056790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that the trial court complied fully with the requirements of Rule 6 of the Alabama Rules of Criminal Procedure Temporary Rules in sentencing appellant to life imprisonment without parole.', 'sentencing', 'Lyner v. State', 'https://www.courtlistener.com/opinion/1729646/', '1729646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that in giving the challenged instruction to the jury the trial court committed error, and that error was not harmless.', 'general', 'Rorie v. United States', 'https://www.courtlistener.com/opinion/2081712/', '2081712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that;', 'general', 'Rorie v. United States', 'https://www.courtlistener.com/opinion/2081712/', '2081712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, on this record we conclude that the giving of that instruction constituted error.', 'general', 'Rorie v. United States', 'https://www.courtlistener.com/opinion/2081712/', '2081712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under both of these harmless error standards, the error in giving criminal jury instruction no.', 'jury_instruction', 'Rorie v. United States', 'https://www.courtlistener.com/opinion/2081712/', '2081712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under either the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse the trial court’s judgment and remand the case for a new trial.', 'general', 'Rorie v. United States', 'https://www.courtlistener.com/opinion/2081712/', '2081712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the foregoing reasons, we reverse the judgment of the trial court and remand this case for a new trial.', 'general', 'Rorie v. United States', 'https://www.courtlistener.com/opinion/2081712/', '2081712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Winberry, we held that a court rule limiting the time in which to file an appeal fell within the Court''s constitutional authority over practice and procedure and that a statute conflicting with that rule exceeded the Legislature''s powers.', 'general', 'In Re Pl 2001, Chapter 362', 'https://www.courtlistener.com/opinion/2057978/', '2057978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'County of Passaic, we held that "the control of probation officers and of the whole statewide system of probation, seemingly entrusted to the Judiciary by the terms of the Constitution, [cannot] be in any way diluted or modified by legislation[.', 'general', 'In Re Pl 2001, Chapter 362', 'https://www.courtlistener.com/opinion/2057978/', '2057978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Salisbury, this Court held that "subject to law" meant substantive law, such as legislation and the common law, as opposed to pleading and practice.', 'plea', 'In Re Pl 2001, Chapter 362', 'https://www.courtlistener.com/opinion/2057978/', '2057978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Knight, supra, we found that the New Jersey Conflicts of Interest Law not only served "a significant governmental purpose," but also was consistent with ethical strictures in the Court''s Canons of Judicial Conduct.', 'general', 'In Re Pl 2001, Chapter 362', 'https://www.courtlistener.com/opinion/2057978/', '2057978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed, we affirm the judgment of the Appellate Division.', 'general', 'In Re Pl 2001, Chapter 362', 'https://www.courtlistener.com/opinion/2057978/', '2057978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we hold that the trial court''s denial of defendant''s motion to sever was not an abuse of discretion, and that defendant was not significantly prejudiced by the joinder of the March 20 counts with the homicide counts in the guilt phase of the proceedings.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as defense counsel did not request a diminished capacity charge, and the evidence offered did not significantly relate defendant''s mental disorder to the state of mind described by defendant''s psychiatric expert, we hold that it was not plain error for the trial court to have failed, sua sponte, to instruct the jury on diminished capacity and aggravated manslaughter on the theory that defendant''s mental condition afforded the jury a rational basis for convicting defendant of the less...', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To recapitulate, we hold that it was not plain error for the trial court to have omitted to charge the jury on aggravated manslaughter  whether in connection with the proofs offered by defendant bearing on imperfect self-defense, diminished capacity, or state of mind.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although we hold that defendant was not entitled to a charge on aggravated manslaughter, we are also satisfied that its submission to the jury would have had no effect on the verdict.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ramseur, supra, where we held that an instruction that the jury "should decide the case on the evidence without any bias, prejudice or sympathy * * *" did not violate a defendant''s constitutional rights, 106 N.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although expressly declining to rule on the admissibility of the proposed testimony in respects other than relevancy, we held that the proffered expert testimony "generally satisfies broad standards of relevancy" and hence was admissible to establish a mitigating factor in the penalty phase.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the Gerald charge would have been appropriate, we consider whether its omission was clearly capable of affecting the verdict.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the jury in this case did not specify which of the foregoing offenses (capital murder or non-capital murder) defendant was convicted of, and because it is possible, on this record, that the jury could have determined that the defendant had the purpose or knowledge to cause only serious bodily injury but not death, we conclude that the judgment of conviction .', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we concluded that the evidence in the record was susceptible to either finding, we reversed defendant''s capital murder conviction and remanded the matter for a new trial.', 'general', 'State v. Pitts', 'https://www.courtlistener.com/opinion/2058374/', '2058374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We also adopted in Ramseur a narrowing construction of c(4)(c) in order to satisfy constitutional standards, and we concluded that the defendant''s state of mind was the critical element:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Once the police officer determined Medrano was not the robbery suspect, this court held that the facts and circumstances which came to light during the investigation constituted sufficient grounds for a reasonable suspicion that criminal activity was afoot.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1224003/', '1224003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1224003/', '1224003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, applying the plain and ordinary meaning of the word "possession," the evidence here was sufficient to prove beyond a reasonable doubt that defendant knowingly distributed harmful material to a minor.', 'general', 'People v. Ward', 'https://www.courtlistener.com/opinion/2058950/', '2058950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we affirm the judgment of the appellate court affirming defendant''s conviction for distributing harmful material to a minor.', 'general', 'People v. Ward', 'https://www.courtlistener.com/opinion/2058950/', '2058950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that under West Virginia Code § 61-8-12(b), which does not require a showing of consanguinity, a person is guilty of incest when such person engages in sexual intercourse or sexual intrusion with the step-child of his or her brother or sister.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “separate convictions for first and third-degree sexual assault and incest, although they arise from the same act, do not constitute the same offense for purposes of the double jeopardy clauses.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Doing so, we conclude that the Legislature clearly intended our incest statute and our first degree sexual assault statute to permit multiple sentences for different offenses arising from the same act.', 'sentencing', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that West Virginia Code § 61-8-12 meets the requirements of the West Virginia Constitution, Article III, Section 14, mandating that “the accused be fully and plainly informed of the character and cause of the accusation.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that these statutes are intended to permit multiple prosecutions for different offenses arising from a single act.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that separate convictions for first degree sexual assault and incest, although they arise from the same act, do not constitute the same offense for purposes of the Double Jeopardy Clause of the West Virginia Constitution.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the ruling of the circuit court.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the Appellant’s case, the circuit court properly construed and applied this statute, and thus, we affirm its ruling in this regard.', 'general', 'State v. Ray', 'https://www.courtlistener.com/opinion/1224180/', '1224180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a person may not be detained for roadside questioning beyond the scope of a stop, absent at least an articulable basis for suspecting other criminal activity.', 'general', 'People v. Burrell', 'https://www.courtlistener.com/opinion/1733868/', '1733868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the facts presented, we conclude that defendants’ argument that the stop was pretextual is without, merit.', 'general', 'People v. Burrell', 'https://www.courtlistener.com/opinion/1733868/', '1733868') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Proceeding from the premise that a brief detention is at least as intrusive for Fourth Amendment purposes as a stop, we conclude that a brief detention for questioning is
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant through her offer of proof made out a sufficient prima facie defense of bona fide claim of right to require the case to be submitted to a finder of fact where the burden is on the state to establish the contrary beyond a reasonable doubt.', 'general', 'State v. Hoyt', 'https://www.courtlistener.com/opinion/2062624/', '2062624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the conviction on other grounds, we deem it unnecessary to reach the constitutional claim herein presented.', 'general', 'State v. Hoyt', 'https://www.courtlistener.com/opinion/2062624/', '2062624') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm, and thus overrule Davis.', 'general', 'LeCompte v. State', 'https://www.courtlistener.com/opinion/2063923/', '2063923') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that when one unlawfully dispatches a domestic animal belonging to another person by using a commonly accepted, humane method, and there is no evidence of any other form of malice, the killing is not malicious and consequently does not violate W.', 'general', 'State v. Burgess', 'https://www.courtlistener.com/opinion/1302508/', '1302508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Code § 54.', 'general', 'Battle v. Commonwealth', 'https://www.courtlistener.com/opinion/1354808/', '1354808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that, under the circumstances of the case, the trial court erred in refusing to dismiss the indictments charging more serious offenses following the nolle prosequi.', 'dismissal', 'Battle v. Commonwealth', 'https://www.courtlistener.com/opinion/1354808/', '1354808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge erred.', 'general', 'Battle v. Commonwealth', 'https://www.courtlistener.com/opinion/1354808/', '1354808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we affirm the trial judge.', 'general', 'Broome v. Broome', 'https://www.courtlistener.com/opinion/1739996/', '1739996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Appellate Division, vacate the PCR court’s grant of post-conviction relief, reinstate defendant’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statute does violate the federal and state constitutions as it applies to distributors of such materials, and decline to save the statute insofar as it applies to those accused of the proscribed activities of § 948.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Wis.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] We hold that it may not.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the statute is unconstitutional as it applies to those activities which do not include some interaction between the accused and the child-victim.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an essential element of the crime specified in Wis.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', criminalizes acts where an individual personally confronts, or has the opportunity to personally confront, a specific child, thereby allowing the individual to easily ascertain *155 the child''s age, we conclude that the statute does not create an unreasonable burden on the individual''s First Amendment rights.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the statute on its face does not allocate to the State the burden to prove that the defendant had knowledge of the minority of the child-victim.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this affirmative defense which could never be proved by most of the actors in § 948.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that the affirmative defense as provided in Wis.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we found that we had the power to do so, relying upon precedent supporting the supplementation of deficiencies to save a statute, id.', 'general', 'State v. Zarnke', 'https://www.courtlistener.com/opinion/2066431/', '2066431') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 296 (Iowa 1980), we held that consecutive sentences, even if lengthy, do not constitute cruel and unusual punishment.', 'sentencing', 'State v. August', 'https://www.courtlistener.com/opinion/2066873/', '2066873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a sentence that is not otherwise cruel and unusual does not become so simply because the defendant must servé the entire sentence.', 'sentencing', 'State v. August', 'https://www.courtlistener.com/opinion/2066873/', '2066873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant’s sentences did not lead to an inference of gross disproportionality given the risk of death or serious injury involved in the commission of first-degree robbery.', 'sentencing', 'State v. August', 'https://www.courtlistener.com/opinion/2066873/', '2066873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no constitutional violation and no abuse of discretion, we affirm.', 'general', 'State v. August', 'https://www.courtlistener.com/opinion/2066873/', '2066873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'wherein we affirmed consecutive sentences for second-degree murder and first-degree robbery imposed on a young defendant who claimed he was not as culpable as his accomplices.', 'sentencing', 'State v. August', 'https://www.courtlistener.com/opinion/2066873/', '2066873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we hold that while art.', 'general', 'State v. Wicklund', 'https://www.courtlistener.com/opinion/2066887/', '2066887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Article I, Section 3 of the Minnesota Constitution does not, under the circumstances here, offer greater protection to speech than the First Amendment, nor does public access to the MOA or public financing transform the nature of its property from private to public for purposes of free speech protection under the state constitution.', 'general', 'State v. Wicklund', 'https://www.courtlistener.com/opinion/2066887/', '2066887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the statute was neither vague nor overbroad under the federal standard for commercial speech.', 'general', 'State v. Wicklund', 'https://www.courtlistener.com/opinion/2066887/', '2066887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), we held that a statute regulating telephone calls made by automated equipment withstood state consti-.', 'general', 'State v. Wicklund', 'https://www.courtlistener.com/opinion/2066887/', '2066887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More than a century ago we held that the protections of our state constitution are triggered only by state action.', 'general', 'State v. Wicklund', 'https://www.courtlistener.com/opinion/2066887/', '2066887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we found “extensive interaction through funding, referrals, and regulation, and a high level of interdependence arising from the specialized nature and limited availability of the services,” we held that “more is required to constitute state action than the involvement of state funds or state regulations.', 'general', 'State v. Wicklund', 'https://www.courtlistener.com/opinion/2066887/', '2066887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding nothing from either the 1857 debates or decisions of other states having similar or identical provisions to suggest that our state’s free speech protection was intended to be applied more broadly than its federal counterpart, we conclude that there is nothing inherent in the language of Article I, Section 3 which requires more expansive protection for free speech than does the First Amendment.', 'general', 'State v. Wicklund', 'https://www.courtlistener.com/opinion/2066887/', '2066887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the circumstances here neither the presence of public financing alone nor the public financing coupled with an invitation to the public to come onto the property is sufficient to transform privately-owned property into public property for purposes of state action.', 'general', 'State v. Wicklund', 'https://www.courtlistener.com/opinion/2066887/', '2066887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 943.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Namely, we hold that summary judgment was warranted because Peters'' negligence exceeded any possible negligence of the defendants as a matter of law.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Wis.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Peters'' negligence exceeded any negligence which could be placed on defendants as a matter of law.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that plaintiffs are barred from recovery pursuant to Wis.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the word "detain" in § 943.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the legislature intended that the pursuit be allowed under § 943.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Peters'' unreasonable and dangerous behavior constituted a clear and extreme breach of his duty of care for his own safety.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we conclude that plaintiffs are barred from recovery as a matter of law on public policy grounds.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that there is no genuine issue as to any fact material to our comparison of negligence in this case.', 'general', 'Peters v. Menard, Inc.', 'https://www.courtlistener.com/opinion/2066934/', '2066934') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we hold that these two convictions merge because they concern violations of the same statute .', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2067034/', '2067034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm the judgments of conviction.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2067034/', '2067034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2067034/', '2067034') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that neither Wis.', 'general', 'State v. Harrell', 'https://www.courtlistener.com/opinion/2067478/', '2067478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Judge DeChambeau clearly made a subjective determination regarding his ability to proceed in the case.', 'general', 'State v. Harrell', 'https://www.courtlistener.com/opinion/2067478/', '2067478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 662 (1989), we found that this subsection contains six fact-specific situations, the existence of which can be determined objectively, and one general subjective situation which is based solely upon the judge''s state of mind.', 'general', 'State v. Harrell', 'https://www.courtlistener.com/opinion/2067478/', '2067478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court judgment ordering French to reimburse the city for incurred abatement costs is not punishment under Iowa Code section 665.', 'general', 'French v. Iowa District Court for Jones County', 'https://www.courtlistener.com/opinion/2067387/', '2067387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the trial court''s decision to *961 excuse Wyatt for cause was neither illogical nor arbitrary.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2067285/', '2067285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the State did not change its theory, and we reject Jackson''s claim of prosecutorial misconduct.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2067285/', '2067285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and the 100-year sentence.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2067285/', '2067285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the term “judge” as used in this section is not ambiguous and therefore refuse to interpret its meaning.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/2069583/', '2069583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that sufficient evidence exists to support his two Intimidation convictions, that his constitutional argument is precluded from review, and that the trial court did not err in imposing a four-and-one-half-year habitual offender enhancement, we affirm the judgment of the trial court.', 'general', 'Montgomery v. State', 'https://www.courtlistener.com/opinion/2069583/', '2069583') ON CONFLICT DO NOTHING;
