INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'cover the same conduct Since the conflict between the two statutes was irreconcilable and since the rule in such a situation is that the more specific statute governs, we concluded that the prosecution pursuant to the theft statute was barred.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2069883/', '2069883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for trial.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2069883/', '2069883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for trial on both the forgery and false representation counts.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2069883/', '2069883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the dismissal of felony theft charges against a defendant who allegedly fraudulently received welfare payments, holding that the legislature’s enactment of a specific law making welfare fraud of the type alleged a misdemeanor indicated a legislative intent that all welfare fraud of that type be prosecuted as a misdemeanor rather than under the felony theft statute.', 'dismissal', 'State v. Williams', 'https://www.courtlistener.com/opinion/2069883/', '2069883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that absent a statutory expression to the contrary, the judiciary, including the Family Court, possessed the inherent power to impose consecutive sentences for separate offenses.', 'sentencing', 'State v. Franklin', 'https://www.courtlistener.com/opinion/2070036/', '2070036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Appellate Division and remand to the *974 trial court for the calculation and award of gap-time credit toward the sentences imposed on Franklin''s robbery offenses consistent with this opinion.', 'sentencing', 'State v. Franklin', 'https://www.courtlistener.com/opinion/2070036/', '2070036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that Kennedy’s guilty pleas, validly entered and accepted, resulted in a waiver of Kennedy’s right to assistance of counsel and a jury trial.', 'plea', 'State v. Kennedy', 'https://www.courtlistener.com/opinion/2070024/', '2070024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse the judgment of the district court concerning case No.', 'general', 'State v. Kennedy', 'https://www.courtlistener.com/opinion/2070024/', '2070024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When a law enforcement officer kills the accomplice of a person committing a kidnapping, does the kidnapper commit felony murder under the Indiana murder statute? We hold that, under these circumstances, the kidnapper commits felony murder.', 'general', 'Palmer v. State', 'https://www.courtlistener.com/opinion/2071258/', '2071258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold the felony murder provision in our murder statute applies, and we affirm the defendant''s convictions.', 'general', 'Palmer v. State', 'https://www.courtlistener.com/opinion/2071258/', '2071258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'Palmer v. State', 'https://www.courtlistener.com/opinion/2071258/', '2071258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that (1) the underlying claims against the lawyer for offensive touching and sexual harassment cannot be based on criminal statutes, although they could be the basis for a claim of intentional tort;', 'general', 'Brett v. Berkowitz', 'https://www.courtlistener.com/opinion/2071463/', '2071463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that plaintiff’s motion to compel was properly denied with respect to her claim of intentional infliction of emotional distress.', 'general', 'Brett v. Berkowitz', 'https://www.courtlistener.com/opinion/2071463/', '2071463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the policies underlying the requirement that medical malpractice experts be competent to testify concerning the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of any showing of such familiarity, and without bridging testimony to harmonize the standard, of care in Hurowitz’ locality with that of Delaware, we hold that the expert testimony was properly excluded.', 'general', 'Brett v. Berkowitz', 'https://www.courtlistener.com/opinion/2071463/', '2071463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this argument misconstrues the nature of habit evidence.', 'general', 'Brett v. Berkowitz', 'https://www.courtlistener.com/opinion/2071463/', '2071463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this appeal we affirm the judgment for defendant entered upon a defense verdict in an action for sexual misconduct and malpractice by a client against a lawyer.', 'general', 'Brett v. Berkowitz', 'https://www.courtlistener.com/opinion/2071463/', '2071463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Superior Court’s ruling that plaintiffs claim, if properly stated, would be for the tort of intentional infliction of emotional distress, and cannot be based on the criminal statutes asserted here.', 'general', 'Brett v. Berkowitz', 'https://www.courtlistener.com/opinion/2071463/', '2071463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in prohibiting “any touching or fondling,” section 11 — 14(a) was specific enough to inform the defendants that touching through clothing was prohibited and to avoid the risk of arbitrary and discriminatory enforcement.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2071715/', '2071715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2071715/', '2071715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Liberty Mut. Ins. Co. v. Thomson', 'https://www.courtlistener.com/opinion/2074497/', '2074497') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that before a defendant may attack the propriety of a search or seizure, that search or seizure must have infringed upon an interest of the defendant which art 1, § 11 was designed to protect.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/2091620/', '2091620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon consideration, we conclude that there are no policy considerations which incline us to adopt the "automatic standing” test and that there is nothing in the differences in language between art 1, § 11 and Am IV that requires or suggests the adoption of the "automatic standing” test.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/2091620/', '2091620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and overrule
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that when a defendant testifies in support of a motion to suppress evidence on Fourth Amendment grounds, his testimony may not thereafter be admitted against him at trial on the issue of guilt unless he makes no objection.', 'suppression', 'People v. Smith', 'https://www.courtlistener.com/opinion/2091620/', '2091620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Chrysler also argues that if we find that an oral protest without an element of violence constitutes a breach of the peace, then we would be narrowing the self-help repossession statute to the point that it would be useless to a secured creditor.', 'general', 'Chrysler Credit Corp. v. Koontz', 'https://www.courtlistener.com/opinion/2093027/', '2093027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the circuit court of Bond County.', 'general', 'Chrysler Credit Corp. v. Koontz', 'https://www.courtlistener.com/opinion/2093027/', '2093027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature did not intend to require an officer to have probable cause to arrest before requesting a PBT.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that our case law establishes that "probable cause to believe" has different meanings at different stages of criminal proceedings.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the context, history and purpose of the statute all suggest that "probable cause to believe" refers to a quantum of proof greater than the reasonable suspicion necessary to justify an investigative stop, and greater than the "reason to believe" that is necessary to request a PBT from a commercial driver, but less than the level of proof required to establish probable cause for arrest.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the officer had the required degree of probable cause to request the defendant to submit to a PBT.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the legislature intended "probable cause to believe" in the first sentence of Wis.', 'sentencing', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[15]  Because we conclude that the officer had sufficient probable cause to request the PBT even without the HGN test results, we do not need to reach the issue of whether those test results were properly excluded.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that case law does not compel the conclusion that the legislature must have intended "probable cause to believe" to mean probable cause for an arrest.', 'probable_cause', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and remand the cause to the circuit court for reinstatement of the judgment of conviction.', 'general', 'County of Jefferson v. Renz', 'https://www.courtlistener.com/opinion/2093305/', '2093305') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Mr.', 'general', 'Ivy v. Keith', 'https://www.courtlistener.com/opinion/1752264/', '1752264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Judge Keith plainly, manifestly, and grossly abused his discretion in using criminal contempt as a penalty for failure to pay the Rule 11 sanctions.', 'general', 'Ivy v. Keith', 'https://www.courtlistener.com/opinion/1752264/', '1752264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jail sentence was intended as a punishment, not as an inducement to pay.', 'sentencing', 'Ivy v. Keith', 'https://www.courtlistener.com/opinion/1752264/', '1752264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hon.', 'general', 'Ivy v. Keith', 'https://www.courtlistener.com/opinion/1752264/', '1752264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not.', 'general', 'People v. Hanson', 'https://www.courtlistener.com/opinion/2094068/', '2094068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the appellate court, remanding the cause for a retrospective fitness hearing, and affirm the judgment of the circuit court.', 'general', 'People v. Hanson', 'https://www.courtlistener.com/opinion/2094068/', '2094068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that Ark.', 'general', 'Miner v. State', 'https://www.courtlistener.com/opinion/1754967/', '1754967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we held that a defendant in a nonjury trial need not challenge sufficiency of evidence, via a directed-verdict motion, to preserve the issue for appeal.', 'general', 'Miner v. State', 'https://www.courtlistener.com/opinion/1754967/', '1754967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we concluded that Rule 33.', 'general', 'Miner v. State', 'https://www.courtlistener.com/opinion/1754967/', '1754967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree, and we affirm the trial court’s order revoking Miner’s probation.', 'general', 'Miner v. State', 'https://www.courtlistener.com/opinion/1754967/', '1754967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given appellant’s failure to make a specific motion for dismissal, we affirm the trial court’s order revoking her probation.', 'dismissal', 'Miner v. State', 'https://www.courtlistener.com/opinion/1754967/', '1754967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In line with the reasoning in the Supreme Court''s decision on the Alaska act, we hold that the District''s SORA is not punitive.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we hold that due process requires the government to shoulder the burden of persuasion on the factual issue that determined whether W.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the District of Columbia Sex Offender Registration Act of 1999 is not punitive and does not inflict punishment on appellants in violation of the Ex Post Facto, Double Jeopardy, or Due Process Clauses of the Constitution.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the burden of persuasion on the predicate factual issue of use of force belongs with the government.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that when a person disputes CSOSA''s finding that "certain sexual acts or contacts were forcible," D.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Supreme Court has settled most, though not all, of the issues presented in the instant appeals.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that SORA does not infringe any fundamental rights or liberty interests of appellants and therefore is constitutional so long as it is rationally related to a legitimate governmental goala test the law meets easily.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the intent of the Council, like that of the Alaska Legislature, "was to create a civil, nonpunitive regime.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, having held that the District of Columbia Sex Offender Registration Act of 1999 does not violate the Ex Post Facto, Double Jeopardy, or Due Process Clauses of the Constitution, we affirm the orders of the Superior Court requiring appellants to register as sex offenders.', 'general', 'In Re WM', 'https://www.courtlistener.com/opinion/2095176/', '2095176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that their meanings are identical and that our construction of the term "final judgment of conviction" found in I.', 'general', 'State v. Wagenius', 'https://www.courtlistener.com/opinion/1289588/', '1289588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 934 (1976), we held that for purposes of I.', 'general', 'State v. Wagenius', 'https://www.courtlistener.com/opinion/1289588/', '1289588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that for purposes of I.', 'general', 'State v. Wagenius', 'https://www.courtlistener.com/opinion/1289588/', '1289588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 71 (1988) ("We hold that voluntary consent is not a prerequisite to admissibility of the breathalyzer results");', 'general', 'People v. Jones', 'https://www.courtlistener.com/opinion/2096832/', '2096832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held the statute did require consent to chemical testing for test results to be admissible as evidence.', 'general', 'People v. Jones', 'https://www.courtlistener.com/opinion/2096832/', '2096832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the facts known to Officer Biecker at the time he initiated the investigatory stop did not provide a reasonable, articulable suspicion that defendant had or was about to commit a crime, we hold that the Terry stop violated defendant''s constitutional rights.', 'general', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d *1253 229] (1983), where we held that when an officer, without reasonable suspicion or probable cause, approaches an individual, the individual has a right to ignore the police and go about his business.', 'probable_cause', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the arresting police officer did not have a reasonable, articulable suspicion that defendant was about to commit a crime sufficient to justify an investigative stop pursuant to Terry v.', 'general', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having determined that the Terry stop of defendant was illegal, we conclude that the trial court should have granted defendant''s motion and excluded all evidence obtained as a result of that illegality, including the cocaine discovered in the apple pie box.', 'general', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because on remand the State would be unable to prove that defendant committed the offense of unlawful possession of a controlled substance without the suppressed cocaine, we reverse defendant''s conviction and sentence.', 'suppression', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the State would be unable to prove beyond a reasonable doubt that defendant unlawfully possessed a controlled substance without the suppressed cocaine, we reverse outright defendant''s conviction and sentence.', 'suppression', 'People v. Kipfer', 'https://www.courtlistener.com/opinion/2097150/', '2097150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Hedger v. State', 'https://www.courtlistener.com/opinion/2097109/', '2097109') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Locken, we held that the resistance of even an unlawful arrest violates section 31-1.', 'general', 'City of Champaign v. Torres', 'https://www.courtlistener.com/opinion/2097165/', '2097165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being so, we held that the defendants could not lawfully employ physical force to prevent the police from entering their residence to effectuate the arrest.', 'general', 'City of Champaign v. Torres', 'https://www.courtlistener.com/opinion/2097165/', '2097165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because sections 7-7 and 31-1 deal specifically with the use of force against peace officers, while section 7-2 applies generally to the use of force against anyone, we concluded that the specific provisions of sections 7-7 and 31-1 controlled.', 'general', 'City of Champaign v. Torres', 'https://www.courtlistener.com/opinion/2097165/', '2097165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion in denying DF &amp;', 'general', 'Weiss v. Johnson', 'https://www.courtlistener.com/opinion/1760754/', '1760754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and dismiss, holding that the service provisions of Rule 4 are applicable because the statutory procedure at issue is silent on notice or service of process at the circuit court level.', 'dismissal', 'Weiss v. Johnson', 'https://www.courtlistener.com/opinion/1760754/', '1760754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2000), we held that expert medical testimony was needed where the only evidence of appellant’s inadequate care of her son’s eczema was the fact that the condition did not improve and her own testimony that it seemed to her like she did not know how to apply cortisone cream correctly and may have been mistreating him.', 'general', 'Jackson v. United States', 'https://www.courtlistener.com/opinion/2099094/', '2099094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Stated another way, we conclude that the complainant’s visible injuries resulting from his encounter with appellant were noticeable to lay persons, and were of such severity that the failure to report the matter as administratively required constituted neglectful behavior of a vulnerable adult in violation of the statute.', 'general', 'Jackson v. United States', 'https://www.courtlistener.com/opinion/2099094/', '2099094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the search condition of defendant''s MSR does not establish prospective consent to all searches.', 'general', 'People v. Moss', 'https://www.courtlistener.com/opinion/2099786/', '2099786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Balancing the defendant''s limited privacy interest with the government''s interest in performing a pat-down search to ensure officer safety, we hold that the pat-down search of defendant did not violate his fourth amendment right to be free from *713 unreasonable searches.', 'search_seizure', 'People v. Moss', 'https://www.courtlistener.com/opinion/2099786/', '2099786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this testimony, we hold that the search of defendant did not exceed the proper scope under Terry when Trooper Boyles continued his contact with defendant''s pants as he attempted to determine whether the object he felt was a weapon.', 'general', 'People v. Moss', 'https://www.courtlistener.com/opinion/2099786/', '2099786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we found that "the plain language of this probation search condition affirmatively required [the probationer''s] probation officer to ask her to consentor submitto a particular search prior to conducting it.', 'general', 'People v. Moss', 'https://www.courtlistener.com/opinion/2099786/', '2099786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction for escape, but otherwise affirm.', 'general', 'State v. Turgeon', 'https://www.courtlistener.com/opinion/2100041/', '2100041') ON CONFLICT DO NOTHING;
