INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that only one aggravation based on a combination of the same felonies is permitted.', 'general', 'People v. Siguenza-Brito', 'https://www.courtlistener.com/opinion/2100263/', '2100263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that defendant was properly convicted of both offenses.', 'general', 'People v. Siguenza-Brito', 'https://www.courtlistener.com/opinion/2100263/', '2100263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these factors to the present case, we conclude that the kidnapping of T.', 'general', 'People v. Siguenza-Brito', 'https://www.courtlistener.com/opinion/2100263/', '2100263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse that part of the appellate court judgment which reduced defendant’s aggravated kidnapping conviction to kidnapping.', 'general', 'People v. Siguenza-Brito', 'https://www.courtlistener.com/opinion/2100263/', '2100263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm defendant’s aggravated criminal sexual assault conviction predicated on kidnapping.', 'general', 'People v. Siguenza-Brito', 'https://www.courtlistener.com/opinion/2100263/', '2100263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we affirm that part of the appellate court judgment which upheld defendant’s aggravated criminal sexual assault conviction.', 'general', 'People v. Siguenza-Brito', 'https://www.courtlistener.com/opinion/2100263/', '2100263') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that context, we hold that an anonymous tip lacking indicia of reliability of the kind contemplated in Adams and White does not justify a stop and frisk whenever and however it alleges the illegal possession of a firearm.', 'general', 'People v. Sparks', 'https://www.courtlistener.com/opinion/2100812/', '2100812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we conclude that the tip failed to provide reasonable suspicion to stop defendants, we need not address whether the officers exceeded the scope of a proper Terry search.', 'general', 'People v. Sparks', 'https://www.courtlistener.com/opinion/2100812/', '2100812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, as to both defendants, we conclude that the trial court correctly found that the stop of defendants violated their fourth amendment rights (U.', 'search_seizure', 'People v. Sparks', 'https://www.courtlistener.com/opinion/2100812/', '2100812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Sparks', 'https://www.courtlistener.com/opinion/2100812/', '2100812') ON CONFLICT DO NOTHING;
