INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant challenges his convictions for abducting his wife and repeatedly raping her and, for the reasons stated in this opinion, we affirm his convictions without difficulty.', 'general', 'People v. Horn', 'https://www.courtlistener.com/opinion/1671638/', '1671638') ON CONFLICT DO NOTHING;
