INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 164 (1981), we held that before a guilty plea to a felony could be accepted, there must be a factual basis for that plea.', 'plea', 'State v. Ellis', 'https://www.courtlistener.com/opinion/2101383/', '2101383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse the judgment of the trial court and remand for further proceedings not inconsistent with this opinion.', 'general', 'State v. Ellis', 'https://www.courtlistener.com/opinion/2101383/', '2101383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these assumptions to the skeletal definition of "abuse" set out above, we conclude that § 9 derives its function from a constitutional arrangement calculated to correlate the enjoyment of individual rights and the exercise of state power such that the latter facilitates the former.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/2101520/', '2101520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, while we have little regard for either Price''s contumacious manner or her epithet, we conclude that her overall complaint constituted political speech.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/2101520/', '2101520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that Ind.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/2101520/', '2101520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that political expression becomes "unreasonably noisy" for purposes of Ind.', 'general', 'Price v. State', 'https://www.courtlistener.com/opinion/2101520/', '2101520') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the actions occurred in a place “open to common or general use” and thus in a public place.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/2102017/', '2102017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On that basis, we found that the necessary public element was present.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/2102017/', '2102017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/2102017/', '2102017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the provisions of the Omnibus Crime Bill were enacted after Section 16-11-312, we conclude that subsection (C) of Section 16-11-312 has been implicitly repealed.', 'general', 'Hair v. State', 'https://www.courtlistener.com/opinion/1354857/', '1354857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these two statutory provisions are in direct conflict;', 'general', 'Hair v. State', 'https://www.courtlistener.com/opinion/1354857/', '1354857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Hair v. State', 'https://www.courtlistener.com/opinion/1354857/', '1354857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we sustain the State’s first ground for review, and we hold that the court of appeals improperly resolved an “as applied” challenge when it held that the money laundering statute did not apply to checks.', 'general', 'Ex Parte Ellis', 'https://www.courtlistener.com/opinion/2102911/', '2102911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Election Code provisions at issue here are not facially unconstitutional due to vagueness.', 'general', 'Ex Parte Ellis', 'https://www.courtlistener.com/opinion/2102911/', '2102911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We find that Colyandro is mistaken in that regard.', 'general', 'Ex Parte Ellis', 'https://www.courtlistener.com/opinion/2102911/', '2102911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the judgment of the court of appeals.', 'general', 'Ex Parte Ellis', 'https://www.courtlistener.com/opinion/2102911/', '2102911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the need to make this choice is not a product of the challenged statute because the plaintiffs will remain subject to prosecution under federal law regardless of how we might rule.', 'general', 'State v. American Civil Liberties Union', 'https://www.courtlistener.com/opinion/2626724/', '2626724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, and because other factors that counsel against deciding cases in an abstract setting are also present, we conclude that any challenge to the statute must await an actual prosecution.', 'general', 'State v. American Civil Liberties Union', 'https://www.courtlistener.com/opinion/2626724/', '2626724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the risk of eriminal Hability argument rings hollow because the activities that the plaintiffs wish to engage in are already criminal under federal law.', 'general', 'State v. American Civil Liberties Union', 'https://www.courtlistener.com/opinion/2626724/', '2626724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reading the declarations, we conclude that any incremental deterrence associated with AS 11.', 'general', 'State v. American Civil Liberties Union', 'https://www.courtlistener.com/opinion/2626724/', '2626724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the above discussion we conclude that the "need" side of the scale has little or no weight.', 'general', 'State v. American Civil Liberties Union', 'https://www.courtlistener.com/opinion/2626724/', '2626724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that they are.', 'general', 'State v. American Civil Liberties Union', 'https://www.courtlistener.com/opinion/2626724/', '2626724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the actual controversy requirement of AS 22.', 'general', 'State v. American Civil Liberties Union', 'https://www.courtlistener.com/opinion/2626724/', '2626724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court employed the wrong legal standard *476 when determining that there was not a reasonable probability of a different outcome.', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the corroboration requirement in a recantation *478 case is met if: (1) there is a feasible motive for the initial false statement;', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that McCallum has established a feasible motive for H.', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse that part of the court of appeals'' decision granting a new trial.', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm that part of the court of appeals'' decision reversing the circuit court.', 'general', 'State v. McCallum', 'https://www.courtlistener.com/opinion/2105448/', '2105448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Congress has not expressly preempted a state common law claim that would provide compensation based on a common law claim of employer negligence for the failure to verify the proper identity of a prospective employee.', 'general', 'Piscitelli v. CLASSIC RESIDENCE', 'https://www.courtlistener.com/opinion/2084720/', '2084720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that "field" preemption does not bar the challenged tort.', 'general', 'Piscitelli v. CLASSIC RESIDENCE', 'https://www.courtlistener.com/opinion/2084720/', '2084720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a perusal of plaintiff''s amended and proposed amended complaints, we find that the gravamen of plaintiff''s legal action is her assertion that 8 U.', 'general', 'Piscitelli v. CLASSIC RESIDENCE', 'https://www.courtlistener.com/opinion/2084720/', '2084720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we do not adopt IRCA and the pilot program as the standard of conduct of a reasonable employer for the purposes of defining the standard of conduct for a tort action because we find that plaintiff is not a member of the class to be protected by IRCA and the pilot program and that identity theft is not the subject matter which Congress sought to address in IRCA and the pilot program.', 'general', 'Piscitelli v. CLASSIC RESIDENCE', 'https://www.courtlistener.com/opinion/2084720/', '2084720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we find, after carefully reviewing plaintiff''s amended and proposed amended pleadings, and giving her *969 the benefit of all reasonable inferences, that she has failed to state a cause of action, and, hence, we affirm the dismissal of her complaint.', 'dismissal', 'Piscitelli v. CLASSIC RESIDENCE', 'https://www.courtlistener.com/opinion/2084720/', '2084720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State argues, however, that this case is similar to Carpetland and Texaco-Cities, where we held that the plaintiffs waived review of their constitutional claims by failing to raise them before the administrative agency.', 'general', 'Arvia v. Madigan', 'https://www.courtlistener.com/opinion/2085088/', '2085088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On review before this court, we held that the employer had waived review of the matter by not raising it before the administrative tribunal.', 'general', 'Arvia v. Madigan', 'https://www.courtlistener.com/opinion/2085088/', '2085088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing the need to avoid piecemeal litigation and allow parties an opportunity to present evidence to refute the constitutional challenge, we held that the plaintiffs constitutional challenge “to the application of section 304(d)(2) in this case” was waived.', 'general', 'Arvia v. Madigan', 'https://www.courtlistener.com/opinion/2085088/', '2085088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that persons faced with summary suspension of driving privileges under the zero tolerance law are not similarly situated to persons faced with summary suspension under the DUI law for purposes of equal protection review, and the circuit court erred in finding the zero tolerance law unconstitutional on that basis.', 'general', 'Arvia v. Madigan', 'https://www.courtlistener.com/opinion/2085088/', '2085088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that plaintiffs constitutional challenge to the zero tolerance statute was properly before the circuit court, but that the circuit court erred in finding the statute unconstitutional on equal protection and due process grounds.', 'general', 'Arvia v. Madigan', 'https://www.courtlistener.com/opinion/2085088/', '2085088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Arvia v. Madigan', 'https://www.courtlistener.com/opinion/2085088/', '2085088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the circuit court.', 'general', 'Arvia v. Madigan', 'https://www.courtlistener.com/opinion/2085088/', '2085088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal to this court, we affirmed the judgment of the appellate court.', 'general', 'Arvia v. Madigan', 'https://www.courtlistener.com/opinion/2085088/', '2085088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Braddock', 'https://www.courtlistener.com/opinion/2085205/', '2085205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm the decision of the trial court.', 'general', 'People v. Braddock', 'https://www.courtlistener.com/opinion/2085205/', '2085205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the appellate court, which affirmed *1240 the circuit court''s dismissal of defendant''s postconviction petition.', 'dismissal', 'People v. Jones', 'https://www.courtlistener.com/opinion/2085274/', '2085274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that defendant''s contentions of constitutional error, not raised in her original petition, were forfeited on appeal from the circuit court''s first-stage dismissal of the petition.', 'dismissal', 'People v. Jones', 'https://www.courtlistener.com/opinion/2085274/', '2085274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the United States Supreme Court’s rationale for the dual standard of review, we conclude that deference on the ultimate question of the reasonableness of a seizure would be undesirable even in a civil case.', 'general', 'People v. Wear', 'https://www.courtlistener.com/opinion/2086129/', '2086129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this case fits within the rule of Hart-graves rather than Chitwood.', 'general', 'People v. Wear', 'https://www.courtlistener.com/opinion/2086129/', '2086129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reliance on the doctrine of hot pursuit, we reverse the trial court’s rescission of the summary suspension of defendant’s driver license.', 'general', 'People v. Wear', 'https://www.courtlistener.com/opinion/2086129/', '2086129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s rescission of the summary suspension of defendant’s driver’s license.', 'general', 'People v. Wear', 'https://www.courtlistener.com/opinion/2086129/', '2086129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we find that Henderson acquiesced to Judge Nardi''s jurisdiction.', 'general', 'Henderson v. State', 'https://www.courtlistener.com/opinion/2086240/', '2086240') ON CONFLICT DO NOTHING;
