INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the State’s evidence was sufficient to support
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because each conviction was established by at least one unique evidentiary fact, we conclude that Scott’s convictions do not violate Indiana’s prohibition against double jeopardy.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2086452/', '2086452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that Scott’s convictions are supported by sufficient evidence and that they do not violate Indiana’s double jeopardy clause, we affirm.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2086452/', '2086452') ON CONFLICT DO NOTHING;
