INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that there was no instructional error.', 'general', 'People v. Osantowski', 'https://www.courtlistener.com/opinion/2087190/', '2087190') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court’s provision and recitation of the elements of the charged offense served to fairly present the issues to be decided and was an adequate protection of defendant’s rights.', 'general', 'People v. Osantowski', 'https://www.courtlistener.com/opinion/2087190/', '2087190') ON CONFLICT DO NOTHING;
