INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the purpose of the contempt proceeding .', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that remedial contempt was properly employed, we also do not address whether Heidi was entitled to relief under § 806.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 4 We reverse the court of appeals and hold that the circuit court properly employed remedial contempt in this case.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 81 We reverse the court of appeals and hold that the circuit court properly employed remedial contempt in this case.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm the circuit court''s use of contempt, we also affirm the suspension of Heidi''s child support obligations.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we affirm the circuit court''s contempt finding against Ronald, we also reinstate the $32,000 overtrial award.', 'general', 'Frisch v. Henrichs', 'https://www.courtlistener.com/opinion/2087701/', '2087701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Most recently, we held that “the appropriate standard of care to which a lawyer is held in the performance of professional services is ‘that degree of care, skill, diligence and knowledge commonly possessed and exercised by a reasonable, careful and prudent lawyer in the practice of law in this jurisdiction.', 'general', 'In Re Pernicka', 'https://www.courtlistener.com/opinion/2088277/', '2088277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these standards to the facts of this case, we conclude that petitioner was not denied effective assistance of counsel.', 'general', 'In Re Pernicka', 'https://www.courtlistener.com/opinion/2088277/', '2088277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'In Re Pernicka', 'https://www.courtlistener.com/opinion/2088277/', '2088277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM the judgment of the trial court relating to the sentence but REMAND for entry of a formal judgment of conviction.', 'sentencing', 'State v. Johnson', 'https://www.courtlistener.com/opinion/2119709/', '2119709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the record before this Court, we AFFIRM the judgment of the trial court relating to the sentence but REMAND for entry of a proper judgment of conviction consistent with this Opinion.', 'sentencing', 'State v. Johnson', 'https://www.courtlistener.com/opinion/2119709/', '2119709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the motion judge should grant such motions unless the evidence, when viewed in the light most favorable to the non-moving party, sufficed to permit a rational factfinder to resolve the dispute in favor of the non-moving party.', 'general', 'MacDougall v. Weichert', 'https://www.courtlistener.com/opinion/2089418/', '2089418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*402 We conclude that the conflict-of-interest laws not only impose duties on public employees but they also constitute constraints on persons dealing with public employees.', 'general', 'MacDougall v. Weichert', 'https://www.courtlistener.com/opinion/2089418/', '2089418') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Artzer', 'https://www.courtlistener.com/opinion/2091179/', '2091179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the $150,000 restitution award payable to Kolacia''s estate.', 'general', 'State v. Artzer', 'https://www.courtlistener.com/opinion/2091179/', '2091179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Artzer''s conviction for murder in the second degree and the accompanying sentence which includes an indefinite term of imprisonment not to exceed fifty years and the $150,000 restitution award payable to Kolacia''s estate.', 'sentencing', 'State v. Artzer', 'https://www.courtlistener.com/opinion/2091179/', '2091179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons explained below, we affirm.', 'general', 'Matter of Clayton', 'https://www.courtlistener.com/opinion/1454036/', '1454036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and render Evans''s conviction and sentence for felony shoplifting but find that the evidence was sufficient to convict her of second offense shoplifting.', 'sentencing', 'Evans v. State', 'https://www.courtlistener.com/opinion/1680806/', '1680806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004) Consequently, we reverse and render Evans''s conviction for felony shoplifting, affirm her conviction of the lesser-included offense of second offense shoplifting, and reverse and remand for resentencing as a second offender.', 'sentencing', 'Evans v. State', 'https://www.courtlistener.com/opinion/1680806/', '1680806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that the bar against double jeopardy was not violated in this case, that the evidence was sufficient to support defendant’s conviction, and that defendant’s extended-term sentence was based on an improper double enhancement.', 'sentencing', 'People v. Milka', 'https://www.courtlistener.com/opinion/2128335/', '2128335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the appellate court which vacated defendant’s sentence and remanded the cause for resentencing.', 'sentencing', 'People v. Milka', 'https://www.courtlistener.com/opinion/2128335/', '2128335') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Williams, this Court held that “[i]f found to be relevant for any purpose save that of showing bad character or propensity,” “relevant evidence will not be excluded merely because it relates to similar facts which point to the commission of a separate crime.', 'general', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that such evidence was relevant to the issue of lack of consent to the extent that it showed “a common plan or scheme.', 'general', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), where this Court held that it was improper for an expert to testify that drug addicts often steal from their families and commit homicides to support their habit.', 'general', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2006), this Court held that the trial court did not abuse its discretion in permitting a medical examiner to testify using autopsy photographs depicting “the victim’s head, torso, and hands in a moderately decomposed state with extensive discoloration, skin sloughing off, and insect larvae on the wounds.', 'general', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” This Court held that the photographs were relevant to establish the manner and cause of death and the HAC aggravator.', 'general', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 432, this Court held that the trial court did not err in finding CCP based on collateral crime evidence and evidence of lack of resistance or struggle, which indicated that Gore acted calmly and deliberately.', 'general', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2003), this Court held *645the death sentence proportionate in a strangulation murder where the trial court found and weighed HAC and prior violent felony against the statutory mitigating factor of substantially impaired capacity and twenty-six nonstatutory mitigating factors.', 'sentencing', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that McWatters is not entitled to guilt-phase relief.', 'general', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in denying McWatters’ motion to suppress.', 'suppression', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these precedents, we conclude that the trial court did not abuse its discretion in determining the evidence of the Bradley homicide to be admissible in the trial of the Wiggins and Caughey homicides.', 'general', 'McWatters v. State', 'https://www.courtlistener.com/opinion/1554807/', '1554807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that exhibit one satisfies the reliable hearsay requirement of the statute.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Gilboy’s present attitude reflects amenability to rehabilitation, but his prior record of offenses, and reactions to those offenses, requires that he serve a period of incarceration in order to assure that the very serious nature of this offense is not lost on Gilboy or others.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that the appellant’s sentence should be enhanced because the “amount of damage to property sustained by .', 'sentencing', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Secondly, we find that the appellant had “no hesitation about committing a crime when the risk to human life was high.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that “the crime was committed under circumstances in which the potential for bodily injury was great.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there are.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the appellant, although guilty of the crime, committed the offense “under such unusual circumstances that it is unlikely that a sustained intent to violate the law motivated his conduct.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition to satisfying the “indicia of reliability” requirement for admissibility, we find that Gilboy was given a “fair opportunity” to rebut the hearsay.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the convictions on two of those offenses.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment on two of the three convictions for reckless driving.', 'general', 'State v. Gilboy', 'https://www.courtlistener.com/opinion/1683682/', '1683682') ON CONFLICT DO NOTHING;
