INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was "involved in" the accident because the evidence demonstrated that he was implicated in or connected with the accident in a logical or substantial manner.', 'general', 'People v. Aldrich', 'https://www.courtlistener.com/opinion/2133998/', '2133998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no error requiring reversal, we conclude that defendants'' convictions and sentences must be affirmed.', 'sentencing', 'People v. Aldrich', 'https://www.courtlistener.com/opinion/2133998/', '2133998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Aldrich', 'https://www.courtlistener.com/opinion/2133998/', '2133998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is sufficient proof that Williams assisted in the commission of the crimes for which he was convicted.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1710596/', '1710596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Williams made the corroboration argument to the trial court in somewhat veiled terms, but the State does not object to this argument on appeal, and we conclude that defense counsel adequately preserved the point.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1710596/', '1710596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1710596/', '1710596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court on this point.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1710596/', '1710596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the trial court did not abuse its discretion in allowing Sanders’ appraisal of the property as of September 1997.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/2108687/', '2108687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our resolution of the above issues, we hold that the trial court did not abuse its discretion by admitting the checks into evidence or by allowing Sanders to testify as to the property’s value in September 1997.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/2108687/', '2108687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we find that Sanders’ appraisal was at least marginally relevant to determining whether the house was undersold in August 1996.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/2108687/', '2108687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that any unfair prejudice that this evidence may have potentially caused was diminished by counsel’s effective cross-examination.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/2108687/', '2108687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence was sufficient to support
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of Ceja and Hopkins, we hold that a trial court need not allow a defendant''s request to have the jury instructed on offenses that are less serious, but not included, offenses to those offenses for which he or she was charged regardless of whether the evidence at trial could support the less serious offense.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2133639/', '2133639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that aggravated battery improperly served as the predicate for felony murder.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2133639/', '2133639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the act of throwing the infant formed the basis of the aggravated battery conviction and that it was also the same act underlying the killing.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2133639/', '2133639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1157 For the following reasons, we affirm the appellate court.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2133639/', '2133639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the State, we conclude that a jury could have found defendant guilty of both of the essential elements of the offense: (1) operating a motor vehicle (2) while under the influence of alcohol.', 'general', 'State v. Murphy', 'https://www.courtlistener.com/opinion/2109793/', '2109793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Murphy', 'https://www.courtlistener.com/opinion/2109793/', '2109793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that offers to provide or requests to obtain child pornography are categorically excluded from the First Amendment.', 'general', 'United States v. Williams', 'https://www.courtlistener.com/opinion/145810/', '145810') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this prohibition, which did “more than prohibit pandering,” was also facially overbroad.', 'general', 'United States v. Williams', 'https://www.courtlistener.com/opinion/145810/', '145810') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held unconstitutional Congress’s previous attempt to meet this new threat, and Congress responded with a carefully crafted attempt to eliminate the First Amendment problems we identified.', 'general', 'United States v. Williams', 'https://www.courtlistener.com/opinion/145810/', '145810') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, a panel of this court held that a defendant did not waive his Blakely argument by failing to present it at trial because a defendant must knowingly and intelligently waive his right to trial by jury, which the defendant could not have done prior to knowing he had such a right.', 'general', 'Goldsberry v. State', 'https://www.courtlistener.com/opinion/2133807/', '2133807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, a panel of this court held Blakely does not apply to a trial court''s decision to order sentences to be served consecutively, Cowens v.', 'sentencing', 'Goldsberry v. State', 'https://www.courtlistener.com/opinion/2133807/', '2133807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the trial court''s order based on violation of the ex post facto clauses, we need not determine whether the trial court is finding without the participation of the jury, that Goldsberry committed an act of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse and remand in part.', 'general', 'Goldsberry v. State', 'https://www.courtlistener.com/opinion/2133807/', '2133807') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the undisputed facts of this case, we conclude that the State fulfilled its disclosure requirements under Rule 412 with respect to the expert testimony the State attempted to elicit during its case in chief, and with respect to the expert testimony it presented during its case in rebuttal.', 'general', 'People v. Hood', 'https://www.courtlistener.com/opinion/2133759/', '2133759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State’s disclosure was proper.', 'general', 'People v. Hood', 'https://www.courtlistener.com/opinion/2133759/', '2133759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hindman’s calculations under the “spirit” of Rule 412, we conclude that defendant waived any objection to the State’s introduction of the doctor’s calculations on rebuttal.', 'general', 'People v. Hood', 'https://www.courtlistener.com/opinion/2133759/', '2133759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we reverse the judgment of the appellate court reversing defendant’s reckless homicide conviction and remand to the appellate court for consideration of the balance of defendant’s arguments on appeal.', 'general', 'People v. Hood', 'https://www.courtlistener.com/opinion/2133759/', '2133759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we reverse the appellate court judgment reversing defendant’s reckless homicide conviction.', 'general', 'People v. Hood', 'https://www.courtlistener.com/opinion/2133759/', '2133759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, reviewing the evidence in accord with the standard expressed above, we hold that a rational trier of fact could have found, beyond a reasonable doubt, that defendant''s belief that the circumstances *312 justified the use of deadly force was unreasonable.', 'general', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the State proved beyond a reasonable doubt that defendant''s claim of self-defense was unreasonable.', 'general', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that rape was the more serious offense and reversed the defendant''s conviction for incest, even though the defendant received a longer sentence for that conviction.', 'sentencing', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this court held that, because both convictions arose from the same act, only the conviction for the greater offense could stand.', 'general', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the appellate court on this issue and remand to the appellate court with directions to vacate defendant''s second degree murder conviction in favor of his aggravated battery with a firearm conviction, the sentence to run consecutively to defendant''s other 18-year sentence that has not been appealed.', 'sentencing', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hill, we affirmed the conviction for the more specific crime and vacated the conviction for the more general crime.', 'general', 'People v. Lee', 'https://www.courtlistener.com/opinion/2133829/', '2133829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with these interests, we hold that, where a prosecutor obtains a felony indictment, based upon the same conduct as was a previously
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, Sumstine’s entitlement to absolute discharge requires that we reverse the district court’s judgment and remand this cause with direction to enter judgment dismissing the arson information against Sumstine.', 'dismissal', 'State v. Sumstine', 'https://www.courtlistener.com/opinion/2111915/', '2111915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lafler', 'https://www.courtlistener.com/opinion/1692403/', '1692403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the corpus delicti rule is satisfied and a defendant’s confession may be admitted into evidence when the prosecutor presents direct or circumstantial evidence, independent of the confession, establishing (1) the occurrence of the specific injury and (2) some criminal agency as the source of the injury.', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the defendant’s confessions were inadmissible because there was no evidence of the victim’s detrimental reliance on the defendant’s misrepresentations, and therefore, the prosecution had failed to independently establish the corpus delicti of the crime of obtaining property valued over $100 by false pretenses, MCL 750.', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the corpus delicti rule is satisfied in any criminal case if the prosecution shows that the specific injury or loss has occurred and that some person’s criminality was the source or cause of the injury.', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review of the record, we conclude that the corpus delicti of each of the crimes at issue in this case was established sufficiently at the preliminary examinations to warrant the district court’s admission of defendants’ confessions.', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence was sufficient to independently establish that a crime was committed;', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the district court correctly concluded that the corpus delicti of the assault charge had been independently established and that it properly admitted defendants’ extrajudicial statements to establish their identities as the perpetrators of the assault and their intent to rob or steal.', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that defendants’ confessions were admissible as further evidence of the identity and intent of the conspirators.', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court’s decision to bind over defendants for trial in the Recorder’s Court was not an abuse of discretion and that the Recorder’s Court erred when it granted defendants’ motions to quash the information.', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'People v. Cotton', 'https://www.courtlistener.com/opinion/2112208/', '2112208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, under the plain language of the statutes defining these two offenses, it was impossible for one to commit a single assault both with the intent to inflict a serious injury and without the intent to inflict a serious injury.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/2134775/', '2134775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/2134775/', '2134775') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 739, 750 (1996), we held that because other crimes evidence placed the defendant “in the area where the sexual assault occurred near the time it occurred,” it was properly offered for the purpose of showing that the defendant had the opportunity to commit the crime in question.', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 616, 619-20 (1988), we held that while motive need not be proved in a prosecution for first degree sexual assault, it constituted “strong circumstantial evidence against a defendant” and therefore could be a subject of proof by other crimes evidence.', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred in admitting testimony regarding uncharged criminal acts occurring prior to the charged offense and, therefore, reverse, and remand for a new trial.', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion in excluding evidence of the boyfriend’s conduct.', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State met the threshold requirement imposed by rule 404(3) and therefore turn our consideration to the issue whether evidence of the uncharged prior crimes was admissible in this case under rule 404(2).', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because opportunity was not a fact of consequence in this case, it is not a basis upon which independent relevance of other crimes evidence can be asserted under rule 404(2).', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we conclude that the other crimes evidence in this case lacked the independent relevance which is
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 491 (1997), we did not reach the constitutional issue because we concluded that the defendant “did not adduce evidence of sufficient relevance, i.', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the evidence of the victim’s prior sexual behavior did not fall within the statutory exceptions provided for in § 28-321 and that it was not “so relevant and probative that Earl’s constitutional right to present it would be triggered.', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'a prosecution for eight counts of first degree sexual assault, we concluded that evidence regarding a previous sexual assault committed by the defendant was properly admitted on the issue of identity where the manner in which it was committed and certain statements made by the assailant to the victim during its commission bore marked similarities to each of the charged offenses.', 'general', 'State v. Sanchez', 'https://www.courtlistener.com/opinion/1693750/', '1693750') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 747 (1970), we find that appellant''s guilty plea was freely, unequivocally, intelligently, and understandingly made in open court with full knowledge "of the nature of the charge against [her] or proof that [she] in fact understood the charge.', 'plea', 'Morrow v. State', 'https://www.courtlistener.com/opinion/1694954/', '1694954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Brandt has failed to make a prima facie showing that the circuit court violated the Wis.', 'general', 'State v. Brandt', 'https://www.courtlistener.com/opinion/2114149/', '2114149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the circuit court properly denied Brandt''s motion to withdraw his pleas and affirm the court of appeals.', 'plea', 'State v. Brandt', 'https://www.courtlistener.com/opinion/2114149/', '2114149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Brandt did not overcome his initial burden of demonstrating a prima facie violation of Wis.', 'general', 'State v. Brandt', 'https://www.courtlistener.com/opinion/2114149/', '2114149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '08 plea procedure, we affirm the court of appeals.', 'plea', 'State v. Brandt', 'https://www.courtlistener.com/opinion/2114149/', '2114149') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that administrative revocation of probation, as provided in Wis.', 'general', 'State v. Horn', 'https://www.courtlistener.com/opinion/2114112/', '2114112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that disposition of a criminal case, including imposing and revoking probation, is within powers shared among the branches of government.', 'general', 'State v. Horn', 'https://www.courtlistener.com/opinion/2114112/', '2114112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because probation is so closely related to sentencing as a possible criminal disposition, we conclude that probation and administration of probation revocation are within powers constitutionally granted to the legislature.', 'sentencing', 'State v. Horn', 'https://www.courtlistener.com/opinion/2114112/', '2114112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the order of the circuit court.', 'general', 'State v. Horn', 'https://www.courtlistener.com/opinion/2114112/', '2114112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant has failed to produce any evidence that would lead us to conclude that there was a reasonable probability that, but for counsel’s unprofessional errors, the result would have been different, we hold that defendant’s ineffective assistance of counsel claim must fail.', 'ineffective_assistance', 'People v. Hoag', 'https://www.courtlistener.com/opinion/2114285/', '2114285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we believe that counsel''s error was not serious enough to deny defendant a fair trial, we reverse the judgment of the Court of Appeals.', 'general', 'People v. Hoag', 'https://www.courtlistener.com/opinion/2114285/', '2114285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals.', 'general', 'People v. Hoag', 'https://www.courtlistener.com/opinion/2114285/', '2114285') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully considering this matter, we conclude that Shelton pled guilty to a crime which triggers Rule 6 of the Rules of Discipline for the Mississippi Bar and that a plea under Rule 6(a) mandates immediate suspension from the practice of law.', 'plea', 'Mississippi Bar v. Shelton', 'https://www.courtlistener.com/opinion/1710997/', '1710997') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '222], where we held that a statutory bad faith claim for damages could not be recast as unfair competition and prosecuted under Bus.', 'general', 'American International Group, Inc. v. Superior Court', 'https://www.courtlistener.com/opinion/2135446/', '2135446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that insurance transactions were subject to federal regulation under the Commerce Clause, and that the antitrust laws, in particular, were applicable to them.', 'general', 'American International Group, Inc. v. Superior Court', 'https://www.courtlistener.com/opinion/2135446/', '2135446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that petitioners are correct and that a civil RICO cause of action cannot be asserted by an insured in California against an insurer for alleged misrepresentations made in the course of the marketing, sale or performance of an insurance policy contract.', 'general', 'American International Group, Inc. v. Superior Court', 'https://www.courtlistener.com/opinion/2135446/', '2135446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our examination of this record and the applicable law we conclude that (1) RICO does not “specifically relate to the business of insurance” and therefore does not come within the exception set out in McCarran-Ferguson’s section 2(b) (15 U.', 'general', 'American International Group, Inc. v. Superior Court', 'https://www.courtlistener.com/opinion/2135446/', '2135446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the court''s mutual combat charge acted as a limitation on the Petitioner''s ability to claim self-defense, and prejudiced him by transferring the State''s burden to disprove self-defense onto the Petitioner, forcing him to prove self-defense in violation of Burkhart;', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1311284/', '1311284') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we REVERSE Petitioner''s convictions and REMAND for a new trial.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1311284/', '1311284') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4]  We reverse Petitioner''s conviction for Possession of a Firearm or Knife during Commission of a Violent Crime in addition to his murder conviction because Petitioner''s murder conviction served as the prerequisite violent crime for his weapons charge conviction.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1311284/', '1311284') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that reversible error resulted from introduction of this evidence which, as to the charge against appellant, was both irrelevant and highly prejudicial.', 'general', 'Whitted v. State', 'https://www.courtlistener.com/opinion/1790330/', '1790330') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State was improperly permitted to introduce evidence of the good character of its witnesses Lisa Webb and Lucy Carr for truth and veracity.', 'general', 'Whitted v. State', 'https://www.courtlistener.com/opinion/1790330/', '1790330') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reason heretofore expressed, we reverse the conviction of appellant, Michael Whitted, and remand the cause to the County Court for Pinellas County, Florida, for disposition not inconsistent herewith.', 'general', 'Whitted v. State', 'https://www.courtlistener.com/opinion/1790330/', '1790330') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances we hold that the offenses were part of the same behavioral incident.', 'general', 'State v. Boley', 'https://www.courtlistener.com/opinion/2123507/', '2123507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant has not established a constitutional violation.', 'general', 'People v. Funches', 'https://www.courtlistener.com/opinion/2123963/', '2123963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 400 (2003), we held that application of this inference to “special mobile equipment,” as defined by the Code, violated due process and, therefore, was unconstitutional.', 'general', 'People v. Funches', 'https://www.courtlistener.com/opinion/2123963/', '2123963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Greco, we held that the inference at issue in this case, section 4 — 103.', 'general', 'People v. Funches', 'https://www.courtlistener.com/opinion/2123963/', '2123963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Wells’ convictions, we
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s ruling excluding this evidence.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1793824/', '1793824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Wells’ convictions.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1793824/', '1793824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[C]onsidering that the total value of the stolen goods was a close question, we hold that the evidence was not sufficient to eliminate the possibility that the verdict was based on surmise or conjecture.', 'general', 'Hebron v. United States', 'https://www.courtlistener.com/opinion/2159781/', '2159781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence adduced was sufficient for conviction and the statute is not unconstitutionally vague.', 'general', 'Ford v. United States', 'https://www.courtlistener.com/opinion/2160469/', '2160469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the record, we hold that the evidence was sufficient to support that finding.', 'general', 'Ford v. United States', 'https://www.courtlistener.com/opinion/2160469/', '2160469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such facts do not rebut the presumption that the appellant was represented by counsel and that counsel acted effectively.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record shows that the appellant was officially represented by counsel at all times in the litigation, and the appellant has failed to overcome the presumption that counsel was acting effectively at all times.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that motion had been overruled by operation of law and the order granting the motion was a nullity.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), we held that "trial counsel, retained or appointed, had the duty, obligation and responsibility to consult with and fully to advise his client concerning meaning and effect of the judgment rendered by the court, his right to appeal from that judgment, and the necessity of giving notice of appeal and taking other steps to pursue an appeal, as well as expressing his professional judgment as to possible grounds for appeal and their merit, and delineating advantages and disadvantages of ap...', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a motion for new trial is a critical stage of the proceedings and that appellant was entitled to be represented by an attorney.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986) (opinion on rehearing), we held that "[a]n advisory opinion results when a court attempts to decide an issue that does not arise from an actual controversy capable of final adjudication.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the State''s petition for discretionary review, we reversed and remanded the case instructing the First Court to address the issue.', 'general', 'Oldham v. State', 'https://www.courtlistener.com/opinion/1799354/', '1799354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the well established principle of expressio unius est exclusio alterius applies sub judice.', 'general', 'In Re Advisory Opinion of Governor Civil Rights', 'https://www.courtlistener.com/opinion/1802393/', '1802393') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the decision in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the district court did not err in determining that Al-Zubaidy was not prejudiced by the performance of his trial counsel, which he now challenges as deficient, and he therefore could not have been prejudiced by the fact that his appellate counsel did not raise this issue on appeal.', 'general', 'State v. Al-Zubaidy', 'https://www.courtlistener.com/opinion/1803860/', '1803860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we conclude that Al-Zubaidy was not prejudiced by the fact that appellate counsel did not petition for further review of the Court of Appeals’ disposition of the exclusion of Ways’ testimony.', 'general', 'State v. Al-Zubaidy', 'https://www.courtlistener.com/opinion/1803860/', '1803860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we conclude that the district court did not err in denying Al-Zubaidy’s motion for postconviction relief without conducting an evidentiary hearing.', 'general', 'State v. Al-Zubaidy', 'https://www.courtlistener.com/opinion/1803860/', '1803860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse and remand in part.', 'general', 'Ballinger v. State', 'https://www.courtlistener.com/opinion/2163858/', '2163858') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is no inference to character, and because the evidence is powerfully probative of a primary issue in dispute, the defendant''s state of mind, we hold that Ward''s testimony would be admissible even if it were another act within the meaning of Rule 404(b).', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, in an opinion by Justice BOYLE, signed by Chief Justice RILEY and Justices BRICKLEY and GRIFFIN, and in a concurring opinion which I wrote, signed by Justices CAVANAGH and ARCHER, that the other acts evidence (a photograph) was not admissible.', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] Consequently, we reverse the decision of the Court of Appeals in each case and remand to the trial court for further proceedings consistent with this opinion.', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals.', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[33] We therefore hold that the trial court erred in determining that the testimony of Steven C and John J was inadmissible.', 'general', 'People v. VanderVliet', 'https://www.courtlistener.com/opinion/1804994/', '1804994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*663After careful review, we conclude that defendant received a fair trial, free from error.', 'general', 'State v. Mylett', 'https://www.courtlistener.com/opinion/4569567/', '4569567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the undefined term "intimidate" does not render N.', 'general', 'State v. Mylett', 'https://www.courtlistener.com/opinion/4569567/', '4569567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the trial court properly denied the defendant’s motion to suppress.', 'suppression', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the officer’s testimony that unlaced boots pose a strong possibility that a weapon may be concealed inside and that the location provides quick access to a weapon, we conclude that the officer acted reasonably in having the defendant remove the boots before completing the investigative stop and allowing the defendant to return to the vehicle.', 'general', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the appropriate deference to the facts found and the inferences drawn by the trial court, we find that its factual determinations were well supported by the record and were not against the manifest weight of the evidence.', 'general', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the totality of the circumstances presented here, we find that Officer Cordery was warranted in his belief that his safety was in danger.', 'general', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the frisk of the defendant was proper in this case.', 'general', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of the present case, we find that Officer Cordery did not act unreasonably in directing the defendant to remove his unlaced boots to determine if they contained a weapon.', 'general', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we find that the scope of the search was sufficiently confined to “an intrusion reasonably designed to discover guns, knives, *** or other hidden instruments for the assault of the police officer” (Terry, 392 U.', 'general', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the appellate court.', 'general', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court.', 'general', 'People v. Sorenson', 'https://www.courtlistener.com/opinion/2167114/', '2167114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence presented at trial supports the venue chosen and that the information charging Swinson was not multiplicitous.', 'general', 'State v. Swinson', 'https://www.courtlistener.com/opinion/2166884/', '2166884') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we disagree with all of Swinson''s arguments, we affirm.', 'general', 'State v. Swinson', 'https://www.courtlistener.com/opinion/2166884/', '2166884') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed a conviction for theft by fraud where all the false statements were passed through a conduit to the victims).', 'general', 'State v. Swinson', 'https://www.courtlistener.com/opinion/2166884/', '2166884') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that reckless assault is not an intentional crime.', 'general', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under these circumstances, § 27-404 is not applicable.', 'general', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Pruett could not be convicted for use of a weapon to commit a felony when the underlying felonies were manslaughter and reckless assault.', 'general', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 908, 911 (1989), applying principles of statutory construction, we held that the language “‘to commit any felony’” in § 28-1205 is synonymous with “ ‘for the purpose of committing any felony.', 'general', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Pruett’s assignments of error regarding this issue are without merit.', 'general', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in refusing Pruett’s requested instruction and that his assignments of error regarding this issue are without merit.', 'general', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that Pruett was not entitled to an instruction on the definition of the term “accident.', 'general', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we concluded that when the felony which served as the basis of the use of a weapon charge was an unintentional crime, the accused could not be convicted of use of a weapon to commit a felony.', 'general', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Pruett’s conviction and sentence for manslaughter but set aside the verdict and vacate the sentence for use of a weapon to commit a felony because both manslaughter and reckless assault are unintentional crimes.', 'sentencing', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Pruett’s conviction and sentence for manslaughter but set aside the verdict and vacate the sentence for use of a weapon to commit a felony.', 'sentencing', 'State v. Pruett', 'https://www.courtlistener.com/opinion/1809444/', '1809444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that where defendant has explained his intent, and there is evidence negativing that explanation, the inference can be drawn that defendant knew he did not have a license or privilege to enter so that the case should not have been dismissed.', 'dismissal', 'State v. Fanger', 'https://www.courtlistener.com/opinion/2168053/', '2168053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Fanger', 'https://www.courtlistener.com/opinion/2168053/', '2168053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Although we conclude that appellant’s first two contentions warrant no relief, we agree with his contention regarding his sentence for contempt and remand the case for resentencing for contempt consistent with the principle of proportionality.', 'sentencing', 'Caldwell v. United States', 'https://www.courtlistener.com/opinion/2179176/', '2179176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that § 11-944 operates independently of and in addition to § 23-1329(c), so that the sentencing limit of six months’ imprisonment and $1,000 does not apply to convictions for violations of a pretrial release order constituting contempt under § 11-944.', 'sentencing', 'Caldwell v. United States', 'https://www.courtlistener.com/opinion/2179176/', '2179176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Florine, we held that the defendant was guilty under Minn.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Strong, we held that Minn.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[12] We conclude that the "catch all" language of section 609.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that in light of our jurisprudential history requiring clear legislative intent to dispense with proof of mens rea and our heightened concern when it relates to felony level crimes, and because we believe the nature of the weapon here-a knife-was not so inherently dangerous that appellant should be on notice that mere possession would be a crime, respondent was required to prove that appellant knew he possessed the knife on school property as an element of the section 609.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals decision and remand to the trial court to determine whether appellant had knowledge of possession of the knife while on school property.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[5] The court of appeals concluded that "[b]ecause *805 there is sufficient evidence that appellant should have known that the knife was in his coat, we affirm the trial court.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Siirila, we affirmed a conviction under Minn.', 'general', 'In Re Welfare of C.R.M.', 'https://www.courtlistener.com/opinion/2168644/', '2168644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Wis.', 'general', 'State v. Weidner', 'https://www.courtlistener.com/opinion/2168850/', '2168850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'did not fully develop the parameters of "personal meeting," we conclude that contact on the internet does not constitute a personal meeting because it does not entail face-to-face contact.', 'general', 'State v. Weidner', 'https://www.courtlistener.com/opinion/2168850/', '2168850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that because the State does not bear the burden to prove scienter under Wis.', 'general', 'State v. Weidner', 'https://www.courtlistener.com/opinion/2168850/', '2168850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11(2) is unconstitutional in the context of the internet and other situations that do not involve face-to-face contact between the minor and the accused, we affirm the circuit court.', 'general', 'State v. Weidner', 'https://www.courtlistener.com/opinion/2168850/', '2168850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Weidner', 'https://www.courtlistener.com/opinion/2168850/', '2168850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 755 (1978), in which this court held that a jury may consider the defendant’s physical appearance to determine his or her age if there is other circumstantial evidence to support an inference that the defendant is of sufficient age.', 'general', 'State v. McCulloch', 'https://www.courtlistener.com/opinion/1995126/', '1995126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record on direct appeal was not sufficient to determine whether McCulloch received ineffective assistance of counsel and that therefore, the Court of Appeals erred in concluding that he did.', 'ineffective_assistance', 'State v. McCulloch', 'https://www.courtlistener.com/opinion/1995126/', '1995126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record on appeal is not sufficient to review McCulloch’s claim of ineffective assistance of counsel and that therefore, the Court of Appeals erred in concluding in this direct appeal that McCulloch received ineffective assistance of counsel.', 'ineffective_assistance', 'State v. McCulloch', 'https://www.courtlistener.com/opinion/1995126/', '1995126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that McCulloch’s conviction should be affirmed, we need not consider whether a retrial would violate the Double Jeopardy Clause.', 'general', 'State v. McCulloch', 'https://www.courtlistener.com/opinion/1995126/', '1995126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the record in this direct appeal was not sufficient to determine whether McCulloch received ineffective assistance of counsel and that therefore, the Court of Appeals erred in determining that he had received ineffective assistance of counsel at trial.', 'ineffective_assistance', 'State v. McCulloch', 'https://www.courtlistener.com/opinion/1995126/', '1995126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and remand the cause to the Court of Appeals with instructions to affirm McCulloch’s conviction and sentence.', 'sentencing', 'State v. McCulloch', 'https://www.courtlistener.com/opinion/1995126/', '1995126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We conclude that `[t]he separation of legitimate from illegitimate speech calls for more sensitive tools than [Georgia] has supplied.', 'general', 'Gonzales v. City of Belle Glade', 'https://www.courtlistener.com/opinion/1598169/', '1598169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We find that the language does meet the test of common understanding [and] is constitutional.', 'general', 'Gonzales v. City of Belle Glade', 'https://www.courtlistener.com/opinion/1598169/', '1598169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the State confesses error with regard to the circuit court''s refusal to grant Ude a jury trial, we find that the circuit court committed reversible error in this regard;', 'general', 'Ude v. State', 'https://www.courtlistener.com/opinion/1812531/', '1812531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the circuit court erred in denying Ude a jury trial and reverse the judgment of the circuit court.', 'general', 'Ude v. State', 'https://www.courtlistener.com/opinion/1812531/', '1812531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on a thorough review of the record in this case, we find that there was sufficient evidence from which the circuit court could find Ude guilty of stalking.', 'general', 'Ude v. State', 'https://www.courtlistener.com/opinion/1812531/', '1812531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing evidence, we find that the evidence was legally sufficient to convict Ude of stalking.', 'general', 'Ude v. State', 'https://www.courtlistener.com/opinion/1812531/', '1812531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that the circuit court erred in denying Ude''s request for a jury trial;', 'general', 'Ude v. State', 'https://www.courtlistener.com/opinion/1812531/', '1812531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we reverse the judgment of circuit court and remand this case for a jury trial.', 'general', 'Ude v. State', 'https://www.courtlistener.com/opinion/1812531/', '1812531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'accordingly, we reverse the judgment of the circuit court finding Ude guilty of stalking.', 'general', 'Ude v. State', 'https://www.courtlistener.com/opinion/1812531/', '1812531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with our belief, however, that "without claim of right" is integral to the definition of criminal trespass in Minnesota, and adhering to the rule that criminal statutes are to be strictly construed, we hold that "without claim of right" is an element the state must prove beyond a reasonable doubt.', 'general', 'State v. Brechon', 'https://www.courtlistener.com/opinion/2170521/', '2170521') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Addressing the second issue raised, we hold that the jury, not the court, decides the sufficiency of the evidence presented to establish a claim of right.', 'general', 'State v. Brechon', 'https://www.courtlistener.com/opinion/2170521/', '2170521') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Brechon', 'https://www.courtlistener.com/opinion/2170521/', '2170521') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The evidence is sufficient to support the jury’s verdict, and we affirm the decision of the Court of Appeals.', 'general', 'Howard v. State', 'https://www.courtlistener.com/opinion/2276549/', '2276549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury in the case at bar properly could have and did find that the appellant''s failure to perceive the risk he created was a gross deviation from the standard of care that a reasonable man would observe under the circumstances.', 'general', 'Shirah v. State', 'https://www.courtlistener.com/opinion/1816696/', '1816696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that the variance in this case did not affect the substantial rights of this appellant.', 'general', 'Shirah v. State', 'https://www.courtlistener.com/opinion/1816696/', '1816696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that there was evidence that the appellant''s conduct in this case created a substantial and unjustifiable risk of death.', 'general', 'Shirah v. State', 'https://www.courtlistener.com/opinion/1816696/', '1816696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the State sufficiently proved the causal relationship between the appellant''s conduct and the victim''s death.', 'general', 'Shirah v. State', 'https://www.courtlistener.com/opinion/1816696/', '1816696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a variance between the indictment and the proof at trial did, in fact, exist in this case.', 'general', 'Shirah v. State', 'https://www.courtlistener.com/opinion/1816696/', '1816696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in light of the court''s instructions to the jury to disregard any evidence concerning the Secobarbitol and the fact that there was evidence that the victim''s ingestion of morphine alone could have caused the victim''s death, we find that the variance here was not fatal.', 'general', 'Shirah v. State', 'https://www.courtlistener.com/opinion/1816696/', '1816696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lewis, we found that the victim''s conduct was a superseding, intervening cause because we did not believe that the appellant should have perceived that the victim would go get the gun and shoot himself with it after the gun had been put away.', 'general', 'Shirah v. State', 'https://www.courtlistener.com/opinion/1816696/', '1816696') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that this crime is a continuing offense, we conclude the district court erred in dismissing the trial information on statute-of-limitations grounds.', 'dismissal', 'State v. Francois', 'https://www.courtlistener.com/opinion/1817501/', '1817501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and remand for further proceedings.', 'general', 'State v. Francois', 'https://www.courtlistener.com/opinion/1817501/', '1817501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand the case for further proceedings consistent with this opinion.', 'general', 'State v. Francois', 'https://www.courtlistener.com/opinion/1817501/', '1817501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 881 (1990), we held that an insurance carrier could be subjected to liability where it undertook to render a specific service to its insured which was necessary for the protection of a third person and its failure to exercise reasonable care in so doing resulted in (a) an increased risk of harm to the person, (b) the assumption by the actor of a duty owed to the third person, or (c) harm to the third person resulting from reliance on the understanding.', 'general', 'O''BRIEN v. Island Corp.', 'https://www.courtlistener.com/opinion/2175632/', '2175632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'O''BRIEN v. Island Corp.', 'https://www.courtlistener.com/opinion/2175632/', '2175632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the intrasovereign context, we hold that in the absence of collusion, unlawfully seized evidence may properly be admitted for purposes of an independent civil tax assessment proceeding.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nash, supra at 207-215, 225-226, this Court held that the Michigan Constitution does not provide *231 a greater degree of protection than the United States Constitution unless there is a "compelling reason" to impose a different interpretation.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, on finding that there were no "compelling reasons" to interpret art 1, § 11 of the Michigan Constitution any differently than the Fourth Amendment, this Court held that the evidence was admissible.', 'search_seizure', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By balancing each of *237 the five Wolf factors, we conclude that an application of the exclusionary rule in the instant case would not deter future violations of the Fourth Amendment.', 'search_seizure', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of more than "curious facts" and agreeing with the dissent that there is no direct evidence of bad faith, collusion between the agencies, or unethical behavior on the part of the law enforcement agents, we conclude that the Court of Appeals incorrectly found that evidence seized in an improper police search may not be used as the basis of an independent civil jeopardy tax assessment proceeding.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the secondary proceedings were intrasovereign.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals determination and find in favor of respondent Department of Treasury.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and reinstate the order of the Tax Tribunal.', 'general', 'Kivela v. Department of Treasury', 'https://www.courtlistener.com/opinion/2175753/', '2175753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court was in clear error in granting appellee''s motion to quash the charge of criminal trespass.', 'general', 'Commonwealth v. McBride', 'https://www.courtlistener.com/opinion/2179385/', '2179385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1970), in which we held that a governmental entity could not be held liable for damage caused during a riot, regardless of the fact that the city had removed police officers dispatched to guard against the damage.', 'general', 'Everton v. Willard', 'https://www.courtlistener.com/opinion/1821147/', '1821147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8] Nevertheless, we concluded that "certain policy-making, planning or judgmental governmental functions cannot be the subject of traditional tort liability.', 'general', 'Everton v. Willard', 'https://www.courtlistener.com/opinion/1821147/', '1821147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 781, 788 (Iowa 1989), we held that First Amendment considerations raised with respect to subsection (l)(a) of this statute were obviated because of the requirement that the communication be “without legitimate purpose.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/2179437/', '2179437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record and considering the arguments presented, we affirm the decision of the court of appeals and the judgment of the district court.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/2179437/', '2179437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Henceforth, we hold that an instruction which purports to set forth the elements which must be proven in order to convict of the crime of attempted murder must inform the jury that the State must prove beyond a reasonable doubt that the defendant, with intent to kill the victim, engaged in conduct which was a substantial step toward such killing.', 'general', 'Spradlin v. State', 'https://www.courtlistener.com/opinion/2139707/', '2139707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, by definition, there can be no "attempt" to perform an act unless there is a simultaneous "intent" to accomplish such act.', 'general', 'Spradlin v. State', 'https://www.courtlistener.com/opinion/2139707/', '2139707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, we reverse.', 'general', 'Spradlin v. State', 'https://www.courtlistener.com/opinion/2139707/', '2139707') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Miss.', 'general', 'James v. State', 'https://www.courtlistener.com/opinion/1846777/', '1846777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the decisions of the foregoing cases, we conclude that Miss.', 'general', 'James v. State', 'https://www.courtlistener.com/opinion/1846777/', '1846777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because these examples demonstrate that individuals of common intelligence know what "to solicit" means, we hold that the statute adequately advises persons of what conduct is proscribed.', 'general', 'Barr v. State', 'https://www.courtlistener.com/opinion/1846925/', '1846925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is a reasonable nexus between the restrictions imposed by the statute, and the ends sought to be achieved by the state, we conclude that no violation of Edelson''s or Barr''s substantive due process rights occurred.', 'general', 'Barr v. State', 'https://www.courtlistener.com/opinion/1846925/', '1846925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that section 817.', 'general', 'Barr v. State', 'https://www.courtlistener.com/opinion/1846925/', '1846925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a subscriber enjoys a reasonable expectation of privacy in the contents of emails “that are stored with, or sent or received through, a commercial ISP.', 'general', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, on balance, Kadon’s improper comments did not rise to the level of flagraney.', 'general', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this precedent, we hold that the district court did not abuse its discretion in denying the defendants’ discovery motion.', 'general', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Daniel, we held that “ ‘[a] scheme to defraud includes any plan or course of action by which someone intends to deprive another by deception of money *311.', 'general', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that, ”[t]o prove a violation of [the concealment subsection], it is not enough for the government to prove merely that a transaction had a concealing effect.', 'general', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Presser, this court held that “Rule 16 requires the government to disclose to the defense before trial only specific categories of evidence.', 'general', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Warshak had a subjective expectation of privacy in the contents of his emails.', 'general', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reason, we conclude that the information in Greg Cossman’s deposition was not suppressed.', 'suppression', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the government did violate Warshak’s Fourth Amendment rights by compelling his Internet Service Provider (“ISP”) to turn over the contents of his emails.', 'search_seizure', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning first to the subjective component of the test, we find that Warshak plainly manifested an expectation that his emails would be shielded from outside scrutiny.', 'general', 'United States v. Warshak', 'https://www.courtlistener.com/opinion/181032/', '181032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we held that the defendant had not been prejudiced by his attorney’s errors because the outcome there — a habitual offender finding — would have been the same.', 'general', 'State v. Van Cleave', 'https://www.courtlistener.com/opinion/2140929/', '2140929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the showing of prejudice necessary to establish a constitutional claim requires that Van Cleave have shown a reasonable probability that he would not have been convicted at trial.', 'general', 'State v. Van Cleave', 'https://www.courtlistener.com/opinion/2140929/', '2140929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, for three reasons we conclude that the “unfairness” or “unreliability” requirement discussed in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that to the extent
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, under Rule 52(A) the ultimate analysis is the same: “We reverse only upon a showing of ‘clear error’ — that which leaves us with a definite and firm conviction that mistake has been made.', 'general', 'State v. Van Cleave', 'https://www.courtlistener.com/opinion/2140929/', '2140929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Van Cleave’s conviction and death sentence on direct appeal.', 'sentencing', 'State v. Van Cleave', 'https://www.courtlistener.com/opinion/2140929/', '2140929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that section 12-7.', 'general', 'In Re BC', 'https://www.courtlistener.com/opinion/2144342/', '2144342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that section 12-7.', 'general', 'In Re BC', 'https://www.courtlistener.com/opinion/2144342/', '2144342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature, aware of this fact, intended that improper bias which motivates *1363 certain criminal acts be the component which elevates the conduct to the level of hate crime, rather than merely the status of a particular victim.', 'general', 'In Re BC', 'https://www.courtlistener.com/opinion/2144342/', '2144342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the petitions and stipulations sufficiently set forth charges of disorderly conduct against respondents by alleging that they displayed certain patently offensive depictions of violence toward African-Americans that disturbed an individual and provoked a breach of the peace.', 'general', 'In Re BC', 'https://www.courtlistener.com/opinion/2144342/', '2144342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgments of the appellate and circuit courts and remand this cause to the circuit court for further proceedings consistent with this opinion.', 'general', 'In Re BC', 'https://www.courtlistener.com/opinion/2144342/', '2144342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Minnesota courts have subject matter jurisdiction to enforce the charge of driving after cancellation as inimical to public safety against Busse even though he is an enrolled tribal member of the White Earth Reservation and committed this offense on that reservation.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, we held that a charge of driving after revocation, there based on failure to produce proof of insurance, was a civil/regulatory offense and consequently not within the state''s jurisdiction to enforce on a reservation.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, it is significant here that in Stone we held that driving without a valid license does not raise policy concerns substantially different from the general policy of public safety and therefore the violation is civil/regulatory.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in Stone we held that speed limits did not raise heightened public policy concerns and careless and reckless driving did raise those concerns.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Stone, we held that driving without a driver''s license in violation of Minn.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, we held that driving after revocation of a person''s driver''s license in violation of Minn.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the extent that in Johnson we held that the state had no jurisdiction to enforce the driving-after-revocation statute against tribal members driving on tribal lands, driving after cancellation as inimical to public safety should produce no different result.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Our ruling in Johnson was clear and unequivocalwe held that because the prior offense carries its own sanction, fairness dictates it not again be used to determine the sanction for the current-and substantially differentmatter before the court, Johnson, 598 N.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the offense of driving after cancellation as inimical to public safety presents substantially different or heightened public policy concerns.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Minn.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that, although it may not give an acquit-first instruction, “the trial court may direct the jury to consider voluntary manslaughter first in its deliberations.', 'general', 'Donaldson v. United States', 'https://www.courtlistener.com/opinion/2178146/', '2178146') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Donaldson v. United States', 'https://www.courtlistener.com/opinion/2178146/', '2178146') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the foregoing reasons, we affirm the judgment of the trial court.', 'general', 'Donaldson v. United States', 'https://www.courtlistener.com/opinion/2178146/', '2178146') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'a jury’s verdict only if we conclude that (4) the error seriously affects the fairness and integrity or
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to Williams’s argument, we conclude that the trial court committed no
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State of Maine v. Bradley Williams', 'https://www.courtlistener.com/opinion/4870147/', '4870147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the merits of the asserted claim, we hold that the trial judge''s finding that the defendant was not entrapped is clearly erroneous.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant was entrapped as a matter of law.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and reinstate the conviction of perjury.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction of attempted delivery of heroin.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the defendant''s conviction of attempted delivery of heroin.', 'general', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and reinstate the defendant''s conviction of perjury without prejudice to his filing a motion seeking post-conviction relief on the ground of ineffective assistance of counsel.', 'ineffective_assistance', 'People v. White', 'https://www.courtlistener.com/opinion/1853502/', '1853502') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that departure was justified but remand for redetermination of the length of imprisonment in accordance with the principles expressed herein.', 'general', 'State v. Schantzen', 'https://www.courtlistener.com/opinion/1853532/', '1853532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we conclude that departure was justified, we also conclude that the extent of the departure should be limited to that justified by the reason for departure.', 'general', 'State v. Schantzen', 'https://www.courtlistener.com/opinion/1853532/', '1853532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly held the defendant''s fitness hearing without a jury.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Judge Locallo''s admonishments, despite the omission of the sentences for burglary, substantially complied with Rule 401(a).', 'sentencing', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the trial court had substantially complied with Rule 401(a) in that it had informed the defendant of his right to counsel, described the nature of the charges and explained that the death penalty was a possible sentence.', 'sentencing', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Johnson, this court held a waiver of counsel to be valid despite the fact that the trial court had failed to specifically advise the defendant that he faced a mandatory minimum sentence of life imprisonment.', 'sentencing', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing these comments and others made by the trial court, we conclude that the trial court did, as the defendant here claims, dispense with a hearing on eligibility and make a summary finding of eligibility.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the plain and ordinary meaning of *327 the phrase "the defense," as used in section 104-12, does not exclude the defendant.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we find that there was substantial compliance with Rule 401(a).', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the circumstances present in this case, we find that the lapse of time between the admonishments and the waiver did not negate the effectiveness of the admonishments.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this omission did not invalidate the defendant''s waiver of counsel.', 'general', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we affirm the defendant''s convictions for intentional murder and burglary and affirm his death sentence.', 'sentencing', 'People v. Haynes', 'https://www.courtlistener.com/opinion/2148855/', '2148855') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Then, considering which party had the burden of proof concerning operability, we held that “operability is not an element of the crime to be proven by the State .', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1273453/', '1273453') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[and] we held that when the defendant fails to produce any evidence of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm.', 'general', 'Ahmed v. United States', 'https://www.courtlistener.com/opinion/2178210/', '2178210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, there is no language in our statute or case law that suggests jury unanimity is required on a mitigating circumstance before it can be weighed against any aggravating circumstances that can be properly found, and we hold that such unanimity is not required.', 'general', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 349 (1986), we held that when the trial court grants the State''s motion in limine and the defendant fails to make an offer of proof during trial, the defendant has not preserved for appellate review any alleged error pertaining to that evidence.', 'general', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the recent Bivins case, we held that "the admissibility of victim impact evidence depends upon its relevance to the death penalty statute''s aggravating and mitigating circumstances.', 'general', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the foregoing sentencing order is insufficient.', 'sentencing', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions of defendant James P.', 'general', 'Harrison v. State', 'https://www.courtlistener.com/opinion/2150043/', '2150043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the search warrant was based upon probable cause but that the State failed to lay a proper foundation for admitting the test results, namely, that Combs’s blood was drawn under the direction of or under a protocol prepared by a physician.', 'probable_cause', 'Combs v. State', 'https://www.courtlistener.com/opinion/2153235/', '2153235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these circumstances reflected a fair probability that evidence of intoxication would be found in Combs’s blood sample.', 'general', 'Combs v. State', 'https://www.courtlistener.com/opinion/2153235/', '2153235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, applying only the a/any rationale of Grappin, we held that the use of "any" created an ambiguity as to the intended unit of prosecution and this ambiguity precluded the State from charging multiple counts based on the defendant''s simultaneous possession of multiple items of contraband.', 'general', 'Bautista v. State', 'https://www.courtlistener.com/opinion/1831644/', '1831644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998), we held that a defendant who resisted two officers during a single incident could be charged with only one crime because the statute prohibited resisting "any" officer.', 'general', 'Bautista v. State', 'https://www.courtlistener.com/opinion/1831644/', '1831644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Within this context, we held that a continuous resistance to an ongoing attempt to effect an arrest constitutes only a single "instance of obstruction" under section 843.', 'general', 'Bautista v. State', 'https://www.courtlistener.com/opinion/1831644/', '1831644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1996), where this Court held that multiple convictions arising from a single DUI incident did not violate double jeopardy principles, the Fourth District Court of Appeal affirmed the convictions.', 'general', 'Bautista v. State', 'https://www.courtlistener.com/opinion/1831644/', '1831644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that chapter 843 is entitled "Obstructing Justice," we concluded that this context indicated a legislative focus on the obstruction of justice by resisting arrest and not just the physical protection of law enforcement officers.', 'general', 'Bautista v. State', 'https://www.courtlistener.com/opinion/1831644/', '1831644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As did the Second District, we found that our construction was consistent with federal circuit court decisions construing similar federal statutes that used either "any" firearm or "a" firearm.', 'general', 'Bautista v. State', 'https://www.courtlistener.com/opinion/1831644/', '1831644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the Florida Legislature had a similar purpose in enacting section 843.', 'general', 'Bautista v. State', 'https://www.courtlistener.com/opinion/1831644/', '1831644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the a/any test adopted in Grappin does not preclude multiple convictions of DUI manslaughter where multiple deaths occur in a single DUI crash.', 'general', 'Bautista v. State', 'https://www.courtlistener.com/opinion/1831644/', '1831644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a county prosecutor''s constitutional and statutory authority to supervise all law enforcement in the county includes the authority to supervise and control SPCA members who exercise law enforcement powers.', 'general', 'Gerofsky v. PASSAIC COUNTY SOC.', 'https://www.courtlistener.com/opinion/2156738/', '2156738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that a county prosecutor''s statutory authority to supervise all law enforcement in the county includes the authority to supervise and control SPCA *712 members who exercise law enforcement powers.', 'general', 'Gerofsky v. PASSAIC COUNTY SOC.', 'https://www.courtlistener.com/opinion/2156738/', '2156738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the trial court erred in granting the State SPCA''s application for a preliminary injunction revoking the Bergen SPCA''s certificate of authority.', 'general', 'Gerofsky v. PASSAIC COUNTY SOC.', 'https://www.courtlistener.com/opinion/2156738/', '2156738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Based on the County Prosecutor''s assumption of responsibility for the enforcement of the animal cruelty laws in Bergen County, the agreement by a substantial number of Bergen SPCA members to become animal cruelty investigators in accordance with the MOU and the Prosecutor''s certification that the revocation of the Bergen SPCA''s certificate of authority could interfere with implementation of the *713 MOU, we conclude that the trial court abused its discretion in granting the State SPCA''s app...', 'general', 'Gerofsky v. PASSAIC COUNTY SOC.', 'https://www.courtlistener.com/opinion/2156738/', '2156738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the preliminary injunction revoking the Bergen SPCA''s certificate of authority and directing that all animal cruelty complaints in Bergen County be transferred to the State SPCA, and remand the case to the trial court.', 'general', 'Gerofsky v. PASSAIC COUNTY SOC.', 'https://www.courtlistener.com/opinion/2156738/', '2156738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the district court and remand with instructions to credit Mr.', 'general', 'Gomez v. State', 'https://www.courtlistener.com/opinion/2639043/', '2639043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 21] We reverse and remand to the district court .', 'general', 'Gomez v. State', 'https://www.courtlistener.com/opinion/2639043/', '2639043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Buchman we held that the state did not have to prove the lack of an exemption to obtain a conviction for the sale of unregistered securities under section 517.', 'general', 'State v. Robarge', 'https://www.courtlistener.com/opinion/1832759/', '1832759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon further consideration of the various decisions and the statutes considered therein, however, we conclude that the district court''s decision does not conflict with the cases cited by the state.', 'general', 'State v. Robarge', 'https://www.courtlistener.com/opinion/1832759/', '1832759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Thompson we found that the antique weapon proviso in this statute constituted "an exception in a subsequent clause" under Beaumel.', 'general', 'State v. Robarge', 'https://www.courtlistener.com/opinion/1832759/', '1832759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the analysis of the First District, we hold that juveniles who may be charged as adults, but are actually adjudicated as delinquents, do not stand criminally convicted for the purpose of designation as a sexual predator under the Predator Act.', 'general', 'State v. JM', 'https://www.courtlistener.com/opinion/1833546/', '1833546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that an adjudication of delinquency does not trigger the sexual predator status provisions of the Predator Act.', 'general', 'State v. JM', 'https://www.courtlistener.com/opinion/1833546/', '1833546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge erred in so doing.', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[5] We conclude that, under the circumstances, the husband''s incarceration was a factor which may and should have been considered by the trial judge;', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that even if the husband remained incarcerated, that circumstance would not prevent him from engaging in conduct, either alone, through others, or both, that would be barred by the CPO if it had been extended.', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for further proceedings on the wife''s motion to extend the CPO.', 'general', 'Maldonado v. Maldonado', 'https://www.courtlistener.com/opinion/2328996/', '2328996') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prosecution *1036 need not disprove a heat of passion theory in a second-degree murder case because proof that the defendant acted maliciously nullifies that theory.', 'general', 'Yung v. State', 'https://www.courtlistener.com/opinion/1127691/', '1127691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the standard heat of passion instruction given by the district court was a correct statement of the law and it did not confuse or mislead the jury.', 'general', 'Yung v. State', 'https://www.courtlistener.com/opinion/1127691/', '1127691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant''s tape recorded confession is a non-testimonial exhibit which the jury may review during deliberations.', 'general', 'Yung v. State', 'https://www.courtlistener.com/opinion/1127691/', '1127691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Yung v. State', 'https://www.courtlistener.com/opinion/1127691/', '1127691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that, when confronted with a plaintiff who fails to appear as a witness, trial courts first must explore less drastic remedies before invoking the ultimate sanction of dismissal.', 'dismissal', 'Brunson v. Affinity Federal Credit Union', 'https://www.courtlistener.com/opinion/1943721/', '1943721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, because the plaintiffs arrest and detention were based on probable cause, his claim for malicious prosecution properly was dismissed by the trial court.', 'dismissal', 'Brunson v. Affinity Federal Credit Union', 'https://www.courtlistener.com/opinion/1943721/', '1943721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Yet, we conclude that the remedies allowed by either the trial court—dismissal of the complaint—or the Appellate Division—forbearing plaintiffs appearance entirely—are too extreme.', 'dismissal', 'Brunson v. Affinity Federal Credit Union', 'https://www.courtlistener.com/opinion/1943721/', '1943721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 529 (2008), and, for the reasons that follow, we reverse in part, and vacate in part the judgment of the Appellate Division, thereby reinstating the judgment of the trial court.', 'general', 'Brunson v. Affinity Federal Credit Union', 'https://www.courtlistener.com/opinion/1943721/', '1943721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Wharton’s Rule does not apply to preclude defendant’s conviction and so reverse the Court of Appeals.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2216657/', '2216657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Wharton’s Rule is inapplicable to this case.', 'general', 'People v. Davis', 'https://www.courtlistener.com/opinion/2216657/', '2216657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the final analysis, we hold that the photographs were more probative than prejudicial.', 'general', 'MacKbee v. State', 'https://www.courtlistener.com/opinion/1839020/', '1839020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our most recent case which explains the necessity for instructing the jury on the effect of a defendant''s habitual offender status, we held that the jury should have been informed of the defendant''s ineligibility of parole.', 'general', 'MacKbee v. State', 'https://www.courtlistener.com/opinion/1839020/', '1839020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the confession would not have been coherent, rational, or worthy of belief if the other crimes were dissected from the statement.', 'general', 'MacKbee v. State', 'https://www.courtlistener.com/opinion/1839020/', '1839020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have reviewed the extensive record, the issues Mackbee raised in this appeal, the briefs and the law, and we conclude that his conviction must be affirmed.', 'general', 'MacKbee v. State', 'https://www.courtlistener.com/opinion/1839020/', '1839020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was enough evidence to support the jury''s verdict in the case sub judice.', 'general', 'MacKbee v. State', 'https://www.courtlistener.com/opinion/1839020/', '1839020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of prior cases and as complemented by Turner and this opinion and the constitutional principles that have evolved in our death penalty jurisprudence, we reverse and remand this case for a new sentencing hearing.', 'sentencing', 'MacKbee v. State', 'https://www.courtlistener.com/opinion/1839020/', '1839020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not abuse its discretion by denying defendant’s motion for a continuance.', 'general', 'State v. Turnipseed', 'https://www.courtlistener.com/opinion/2217455/', '2217455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and its progeny, we conclude that the instruction given by the trial court on circumstantial evidence was adequate and proper.', 'general', 'State v. Turnipseed', 'https://www.courtlistener.com/opinion/2217455/', '2217455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the verdict, we conclude that the evidence presented is sufficient to support the verdict.', 'general', 'State v. Turnipseed', 'https://www.courtlistener.com/opinion/2217455/', '2217455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Turnipseed', 'https://www.courtlistener.com/opinion/2217455/', '2217455') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/2217910/', '2217910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the foregoing rule concerning an accomplice’s testimony.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/2217910/', '2217910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Collie''s plea bargain was not violated by his subsequent sexual predator designation.', 'plea', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the application of the 1996 Act in this case does not violate the Double Jeopardy Clauses of the United States and Florida Constitutions.', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that for the 1996 Act, as applied to Collie, these factors reflect a nonpunitive nature.', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the procedural safeguards built into section 775.', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After weighing the Mendoza-Martinez factors, we conclude that the registration requirements of section 775.', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the sexual predator proceedings were not criminal or quasi-criminal in nature and that Collie had no constitutional right to counsel.', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that they are appropriate for consideration here.', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that the registration requirements imposed on sexual predators do not constitute an affirmative disability or restraint.', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Fourth, while we find that the operation of the registration requirements (and the public notification requirements for offenders whose crimes were committed between October 1, 1995, and July 1, 1996) have some deterrent effects, these effects are de minimis in light of the nonpunitive aim;', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the registration requirement Collie faces is one of the least restrictive methods available to reduce the incidence of sexual predatory behavior and must be considered insignificant in comparison to the goal of protecting the public.', 'general', 'Collie v. State', 'https://www.courtlistener.com/opinion/1840233/', '1840233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when requested by a defendant in a felon-in-possession of a firearm case, the trial court must approve a stipulation whereby the parties acknowledge that the defendant is, without further elaboration, a prior convicted felon.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1757872/', '1757872') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a criminal defendant offers to stipulate to the convicted felon element of a charge of possession of a firearm by a convicted felon, the State and the trial court should accept that stipulation.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1757872/', '1757872') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1970), we held that the State could refuse a defendant''s stipulation to establish the "convicted felon" element of the crime of illegal possession of a firearm by a convicted felon.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1757872/', '1757872') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While much of that uncertainty may be ascribed to the ambiguities in our opinions in Parker and Williams, we conclude that the trial court erred in not utilizing the weighing process discussed in Parker.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1757872/', '1757872') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994) ("We find that our decision in Spencer being a change in procedure and not a change in the lawis to be applied prospectively only.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1757872/', '1757872') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the trial court’s decision to permit introduction of the coworker’s evidence at the pending trial in the prosecutor’s case-in-chief.', 'general', 'People v. Pattison', 'https://www.courtlistener.com/opinion/2220613/', '2220613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand for trial.', 'general', 'People v. Pattison', 'https://www.courtlistener.com/opinion/2220613/', '2220613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our examination of the postconviction motion and the files and records of the underlying criminal proceeding, we conclude that the district court did not err in denying post-conviction relief without conducting an evidentiary hearing.', 'general', 'State v. McLeod', 'https://www.courtlistener.com/opinion/2220541/', '2220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our conclusion that McLeod’s postconviction motion and the files and records of his case do not present any justiciable issue with respect to postconviction relief, we conclude that the district court did not abuse its discretion in denying his motion for appointment of counsel.', 'general', 'State v. McLeod', 'https://www.courtlistener.com/opinion/2220541/', '2220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed, we affirm the judgment of the district court.', 'general', 'State v. McLeod', 'https://www.courtlistener.com/opinion/2220541/', '2220541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the legislative purpose and the underpinnings of the Probate Code mandate the conclusion that a probate court''s discretion at the dispositional phase of a waiver hearing remains unfettered by certain evidentiary requirements recognized in criminal proceedings and already extended to the adjudicative phase of a waiver hearing.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '377 NW2d 262 (1985), in which this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the Court''s analysis of these cases is flawed, and thus it erred in reversing the probate court''s decision to waive jurisdiction over defendant.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Due Process Clause of the Fourteenth Amendment requires that in respect of proceedings to determine delinquency which may result in commitment to an institution in which the juvenile''s freedom is curtailed, the child and his parents must be notified of the child''s right to be represented by counsel retained by them, or if they are unable to afford counsel, that counsel will be appointed to represent the child.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the constitutional protections extended to juvenile proceedings in cases such as Kent and Gault apply in full force to the adjudicative phase of a juvenile waiver hearing.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and remand the case for consideration of the remaining issues raised by defendant.', 'general', 'People v. Hana', 'https://www.courtlistener.com/opinion/2220847/', '2220847') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that coercive police activity is a necessary predicate to the finding that a confession is not "voluntary" within the meaning of the Due Process Clause of the Fourteenth Amendment.', 'general', 'Butler v. State', 'https://www.courtlistener.com/opinion/1842908/', '1842908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Butler was entitled to have the jury instructed that she could be convicted under Miss.', 'general', 'Butler v. State', 'https://www.courtlistener.com/opinion/1842908/', '1842908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Butler v. State', 'https://www.courtlistener.com/opinion/1842908/', '1842908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse on this ground, the remainder of the opinion is confined to questions likely to recur on retrial.', 'general', 'Butler v. State', 'https://www.courtlistener.com/opinion/1842908/', '1842908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the defendant here was not in custody, we reverse the court of appeals.', 'general', 'State v. Magnuson', 'https://www.courtlistener.com/opinion/2221828/', '2221828') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that an offender''s status constitutes custody for sentence credit purposes when the offender is subject to an escape charge for leaving that status.', 'sentencing', 'State v. Magnuson', 'https://www.courtlistener.com/opinion/2221828/', '2221828') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our rule to Magnuson, we conclude that his conditions of release on bond, including home detention with electronic monitoring, did not subject him to an escape charge for any violation of bond conditions and therefore did not render him in custody.', 'general', 'State v. Magnuson', 'https://www.courtlistener.com/opinion/2221828/', '2221828') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals.', 'general', 'State v. Magnuson', 'https://www.courtlistener.com/opinion/2221828/', '2221828') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*75 Applying the applicable constitutional law, we conclude that appellant''s behavior did not present a serious and imminent threat to the fair administration of justice.', 'general', 'In Re Contempt of Dudzinski', 'https://www.courtlistener.com/opinion/2222308/', '2222308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statement on appellant''s shirt was constitutionally protected political speech that did not constitute an imminent threat to the administration of justice and that the trial court erred in ordering appellant to remove his shirt or leave the courtroom.', 'general', 'In Re Contempt of Dudzinski', 'https://www.courtlistener.com/opinion/2222308/', '2222308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did not.', 'general', 'In Re Contempt of Dudzinski', 'https://www.courtlistener.com/opinion/2222308/', '2222308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because appellant has already served his sentence, we conclude that this issue is moot.', 'sentencing', 'In Re Contempt of Dudzinski', 'https://www.courtlistener.com/opinion/2222308/', '2222308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude the trial court erred and infringed on appellant''s First Amendment right to free speech, we affirm the contempt order.', 'general', 'In Re Contempt of Dudzinski', 'https://www.courtlistener.com/opinion/2222308/', '2222308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6]  Because the statute does not attach any significance to the transfer of money in connection with the acts it proscribes, we conclude that the commercial aspect of the defendant''s proposition to the officers has no significance.', 'general', 'People v. Masten', 'https://www.courtlistener.com/opinion/2222708/', '2222708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the costs incurred by Fayette County to house the horses and for the veterinary bill were for caring for Glen’s horses and he does not tell us how they were unreasonable, we conclude that the trial court did not err in ordering Glen to pay the costs.', 'general', 'Lykins v. State', 'https://www.courtlistener.com/opinion/2222808/', '2222808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Lykins v. State', 'https://www.courtlistener.com/opinion/2222808/', '2222808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons we affirm the judgment of the trial court.', 'general', 'Lykins v. State', 'https://www.courtlistener.com/opinion/2222808/', '2222808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the proffered testimony does not meet ordinary standards of reliability for admission, we need not reach defendant’s constitutional challenges.', 'general', 'State v. MacK', 'https://www.courtlistener.com/opinion/2222730/', '2222730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 432 (1971), this court held that spectograph results, or “voiceprints” meet the standard of scientific reliability necessary for admissibility under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that section 5 — 6—3 of the Corrections Code (730 ILCS 5/5 — 6—3 (West 1998)), as well as defendant’s probation order based on that statute, proscribes conduct that is defined as criminal, whether that statutory definition is located in the Vehicle Code or anywhere else in the statutes of Illinois.', 'general', 'People v. Goleash', 'https://www.courtlistener.com/opinion/2222964/', '2222964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this statute is criminal in nature within the meaning of section 5 — 6—3(a)(1) of the Corrections Code and the order setting forth the conditions of probation at issue in this case.', 'general', 'People v. Goleash', 'https://www.courtlistener.com/opinion/2222964/', '2222964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we reverse defendant’s sentence for indirect criminal contempt, affirm the trial court’s finding that defendant violated a condition of his probation, and remand for further proceedings consistent with the views expressed herein.', 'sentencing', 'People v. Goleash', 'https://www.courtlistener.com/opinion/2222964/', '2222964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'People v. Goleash', 'https://www.courtlistener.com/opinion/2222964/', '2222964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 53 Because we conclude that Carter''s offer of proof fails the first and second prongs of the Pulizzano test, we hold that evidence of the alleged previous sexual assault against Cassandra is not excepted from the rape shield law and is therefore inadmissible.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 41 In Pulizzano, this court held that while Wisconsin''s rape shield law is constitutional on its face, as applied it may unconstitutionally infringe upon a defendant''s rights to confrontation and compulsory process.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 3 We conclude that the court of appeals improperly remanded the case to the circuit court for further proceedings.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 18 On review, we conclude that Carter did not receive ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 24 We conclude that Sargent''s performance was not deficient because his strategic decision not to present evidence of the previous sexual assault was objectively reasonable considering all the circumstances.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Sargent reasonably decided that further investigation of the alleged prior sexual assault and its admissibility was unnecessary.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', however, we conclude that Sargent''s decision not to investigate was reasonable.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 38 Even assuming that Sargent''s performance was deficient, we conclude that the deficiency did not prejudice Carter''s defense because evidence of the previous sexual assault would have been inadmissible.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 44 In this case, we conclude that Carter''s offer of proof fails the first and second prongs of the Pulizzano test, and therefore, evidence of the alleged previous sexual assault against Cassandra is not admissible as an exception to the rape shield law.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 54 To summarize, we conclude that the court of appeals improperly remanded the case to the circuit court for further proceedings.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2225342/', '2225342') ON CONFLICT DO NOTHING;
