INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that the phrase "hit-and-run" in the Zarders'' policy is susceptible to more than one reasonable construction, we conclude that it is ambiguous.', 'general', 'Zarder Ex Rel. Menard v. Humana Insurance', 'https://www.courtlistener.com/opinion/2225442/', '2225442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the policy provides for coverage for this type of accident, we need not examine the requirements of Wis.', 'general', 'Zarder Ex Rel. Menard v. Humana Insurance', 'https://www.courtlistener.com/opinion/2225442/', '2225442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court of appeals did not err in affirming the circuit court''s decision to deny Acuity''s motion for declaratory judgment.', 'general', 'Zarder Ex Rel. Menard v. Humana Insurance', 'https://www.courtlistener.com/opinion/2225442/', '2225442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that Acuity''s focus on the unidentified driver''s intention when leaving the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we concluded that this court has the exclusive power to overrule, modify, or withdraw language from prior Wisconsin cases.', 'general', 'Zarder Ex Rel. Menard v. Humana Insurance', 'https://www.courtlistener.com/opinion/2225442/', '2225442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals, but we modify the rationale and remand to the circuit court for further proceedings.', 'general', 'Zarder Ex Rel. Menard v. Humana Insurance', 'https://www.courtlistener.com/opinion/2225442/', '2225442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we need not reach the issue of whether DSS’ action was substantially justified, since we hold that DSS is precluded from raising that issue because DSS failed to appear, after notice, at the hearing regarding attorney fees.', 'general', 'Interest of Krystal P.', 'https://www.courtlistener.com/opinion/2226291/', '2226291') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that costs, including a reasonable attorney fee, may be assessed against the contemnor in a civil contempt proceeding.', 'general', 'Interest of Krystal P.', 'https://www.courtlistener.com/opinion/2226291/', '2226291') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there is such a uniform course of procedure.', 'general', 'Interest of Krystal P.', 'https://www.courtlistener.com/opinion/2226291/', '2226291') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of the record, we find that this action was brought by the State and that, therefore, § 25-1803(1) applies.', 'general', 'Interest of Krystal P.', 'https://www.courtlistener.com/opinion/2226291/', '2226291') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the promisor’s intention at the time of promising, as well as the promisor’s ability to fulfill the promise, are facts which may constitute a false pretense.', 'general', 'State v. Hogrefe', 'https://www.courtlistener.com/opinion/2226671/', '2226671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 197 (Iowa 1981) — another theft by check case — this court held that there is no “deception” in a case of a check allegedly made and presented with the agreement it would be held and was not immediately payable.', 'general', 'State v. Hogrefe', 'https://www.courtlistener.com/opinion/2226671/', '2226671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude there was not sufficient evidence to submit the instruction, we reverse and remand for a new trial.', 'general', 'State v. Hogrefe', 'https://www.courtlistener.com/opinion/2226671/', '2226671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the district court erred in giving the marshalling instruction, we reverse and remand for a new trial.', 'general', 'State v. Hogrefe', 'https://www.courtlistener.com/opinion/2226671/', '2226671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 158 (1985), we held that the underlying purpose of § 28-907(1)(a) is to prevent the public from willfully furnishing erroneous information to law enforcement officers and thus interfering with the performance of their duties.', 'general', 'In INTEREST OF McMANAMAN', 'https://www.courtlistener.com/opinion/2227020/', '2227020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the separate juvenile court properly *49 interpreted and applied § 28-907(1)(a) in this case.', 'general', 'In INTEREST OF McMANAMAN', 'https://www.courtlistener.com/opinion/2227020/', '2227020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he has not.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As part of that decision, we held that requiring sex offenders to register is not punishment.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Adams, we held that the legislature''s intent in requiring registration of sex offenders was to create an additional measure of protection for children from the increasing incidence of sexual assault and child abuse.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1102 (1999), this court held that the legislature could pass legislation that amended several acts, as long as the amendments related to the single subject of "crime.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that defendant has not met his burden of showing that the Notification Law has such a punitive effect that the legislature''s intent to create a nonpunitive scheme may be disregarded.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering all of the relevant factors, we conclude that the requirements of the Notification Law are nonpunitive.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the appellate court''s decision to reverse defendant''s sentence and remand the cause for resentencing.', 'sentencing', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court.', 'general', 'People v. Malchow', 'https://www.courtlistener.com/opinion/2180409/', '2180409') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '023, Florida Statutes (1995), which clearly and explicitly gives to the personal representative of a deceased nursing facility resident a right of action for the deceased''s pain and suffering when the death results from deprivation of the deceased''s rights, we hold that the elements of damages recoverable by the personal representative of a deceased nursing home resident whose death results from deprivation of the deceased''s rights are limited to those which a personal representative is speci...', 'general', 'First Healthcare Corp. v. Hamilton', 'https://www.courtlistener.com/opinion/1887648/', '1887648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that section 400.', 'general', 'First Healthcare Corp. v. Hamilton', 'https://www.courtlistener.com/opinion/1887648/', '1887648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such evidence was sufficient for the jury to conclude that defendants were "consciously indifferent to the rights of the resident" within the meaning *1198 of section 400.', 'general', 'First Healthcare Corp. v. Hamilton', 'https://www.courtlistener.com/opinion/1887648/', '1887648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That comment, though dicta in the Greenleaf case, is not dicta here and we affirm that view.', 'general', 'First Healthcare Corp. v. Hamilton', 'https://www.courtlistener.com/opinion/1887648/', '1887648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Utilizing the totality of the circumstances approach of the federal courts, we conclude that the State has failed to demonstrate that continuing criminal activity was suspected and corroborated.', 'general', 'Huffines v. State', 'https://www.courtlistener.com/opinion/2180555/', '2180555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the search of Huffines’ residence was unreasonable under Indiana law.', 'general', 'Huffines v. State', 'https://www.courtlistener.com/opinion/2180555/', '2180555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we conclude that the State has waived this argument.', 'general', 'Huffines v. State', 'https://www.courtlistener.com/opinion/2180555/', '2180555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the initial probable cause
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Huffines v. State', 'https://www.courtlistener.com/opinion/2180555/', '2180555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court lacked subject-matter jurisdiction, and we reverse and dismiss Standridge’s conviction.', 'dismissal', 'Standridge v. State', 'https://www.courtlistener.com/opinion/2759742/', '2759742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 157, 160 (1958), we held that the trial court lacked jurisdiction to try the defendant on the charge of disobeying a United States Army officer because there was no statute criminalizing such conduct.', 'general', 'Standridge v. State', 'https://www.courtlistener.com/opinion/2759742/', '2759742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In construing sections 5-53-134 and 9-15-207, we conclude that section 5-53-134 is the criminal statute under which the State should have charged Standridge to obtain a conviction for Class D felony violation of a protection order.', 'general', 'Standridge v. State', 'https://www.courtlistener.com/opinion/2759742/', '2759742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, the circuit court lacked subject-matter | ^jurisdiction, and we reverse and dismiss.', 'dismissal', 'Standridge v. State', 'https://www.courtlistener.com/opinion/2759742/', '2759742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and dismiss the case.', 'dismissal', 'Standridge v. State', 'https://www.courtlistener.com/opinion/2759742/', '2759742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreoever, even if Glen’s search did not exceed the scope of Hellums’s search, we conclude that Heliums was an agent of the police under the two-part test set out above.', 'general', 'Whisenant v. State', 'https://www.courtlistener.com/opinion/2183965/', '2183965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Heliums was an agent of the police and that the warrantless search of Whisenant’s purse violated the Fourth Amendment.', 'search_seizure', 'Whisenant v. State', 'https://www.courtlistener.com/opinion/2183965/', '2183965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the foregoing principles to the present case, we find that the warrantless search of Whisenant’s purse violated the Fourth Amendment.', 'search_seizure', 'Whisenant v. State', 'https://www.courtlistener.com/opinion/2183965/', '2183965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, Whisenant has failed to show that the trial court abused its discretion in denying her motion for a continuance, and we affirm on this point.', 'general', 'Whisenant v. State', 'https://www.courtlistener.com/opinion/2183965/', '2183965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because our reversal on the denial of the motion to suppress involves only the evidence found in Whisenant’s purse, we affirm her conviction for possession of firearms by a felon, and reverse and remand the remaining convictions, because, while all of the evidence of financial identity fraud was not found in Whisenant’s purse, we note that evidence from the purse was introduced with respect to all four counts.', 'suppression', 'Whisenant v. State', 'https://www.courtlistener.com/opinion/2183965/', '2183965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Baldwin’s conduct
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'novo review of the record, we conclude that the appropriate sanction is a
