INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our de novo review of the record, we find that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that Baldwin violated rules 32:1.', 'general', 'Iowa Supreme Court Attorney Disciplinary Board v. Seth Eugene Baldwin', 'https://www.courtlistener.com/opinion/2760235/', '2760235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we find that Baldwin violated rules 32:1.', 'general', 'Iowa Supreme Court Attorney Disciplinary Board v. Seth Eugene Baldwin', 'https://www.courtlistener.com/opinion/2760235/', '2760235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the government has failed to meet its burden to show that appellant’s right to a speedy trial was not violated.', 'general', 'Sell v. United States', 'https://www.courtlistener.com/opinion/2185967/', '2185967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that twelve months of the delay caused by the government’s failure to expedite the appeals weighs significantly against the government, while the remainder of the delay in the appellate court proceedings is justifiable.', 'general', 'Sell v. United States', 'https://www.courtlistener.com/opinion/2185967/', '2185967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1096, we held that in an expedited appeal the government should file its brief approximately twenty days after the record is filed with the court, rather than the normal forty days.', 'general', 'Sell v. United States', 'https://www.courtlistener.com/opinion/2185967/', '2185967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that appellant’s manner of asserting his right does not add much force to his speedy trial claim.', 'general', 'Sell v. United States', 'https://www.courtlistener.com/opinion/2185967/', '2185967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying those factors here, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'Sell v. United States', 'https://www.courtlistener.com/opinion/2185967/', '2185967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as the consecutive sentencing statute is enacted under the Code of Criminal Procedure, we find that the subsequent felony referred to in that statute includes two-year misdemeanors.', 'sentencing', 'People v. Comstock', 'https://www.courtlistener.com/opinion/1893650/', '1893650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we held that a “trial court’s determination as to whether a defendant has established purposeful discrimination in the selection of a jury is a finding of fact which will not be reversed on appeal unless clearly erroneous.', 'general', 'State v. Culver', 'https://www.courtlistener.com/opinion/2218580/', '2218580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '299 NW2d 304 (1980), this Court held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In doing so, we find that the instructions, as a whole, correctly informed the jury of the Aaron standard governing malice in felony murder and do not require the jury to have determined such malice only on the basis of the intent to commit the underlying felony.', 'general', 'People v. Kelly', 'https://www.courtlistener.com/opinion/2189436/', '2189436') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the intent necessary for an aiding and abetting conviction is so overwhelmingly evident from the record, we find that no injustice has occurred.', 'general', 'People v. Kelly', 'https://www.courtlistener.com/opinion/2189436/', '2189436') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a two-year misdemeanor conviction arising out of the first felony charge may serve as the "conviction of the prior charged offense" required for consecutive sentencing.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a charge remains "pending" for purposes of this statute until a defendant is sentenced on a conviction arising out of the offense, and until the original charge arising out of the offense is dismissed.', 'dismissal', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the right to counsel is violated, and a defendant must be resentenced, if the sentencing judge obtains information about the *435 defendant from the probation officer that is not included in the written presentence report.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that two-year misdemeanors may be considered "felonies" for whatever purposes that word is used in the consecutive sentencing statute.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the constitutional guarantee of an appeal as a matter of right from criminal prosecutions required that an indigent be provided with *445 appointed appellate counsel and a free transcript of the proceedings at trial, noting that "[t]he name `felony'' or `misdemeanor'' can make small difference as relates to [defendant''s] constitutional right to such assistance.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More recently, we held that the need for "complete, accurate, and reliable" information at sentencing required the use of a reasonably updated presentence report in sentencing for felonies.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In order to achieve the Legislature''s intended purpose in the Code of Criminal Procedure, we find that the Legislature meant exactly what it said: Offenses punishable by more than one year of imprisonment are "felonies" for purposes of the habitual-offender, probation, and consecutive sentencing statutes.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions of Timothy Smith under the habitual-offender statutes, because the two-year misdemeanor convictions which served as the bases for his habitual-offender charges could be considered "felonies" for purposes of the habitual-offender statutes.', 'general', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the sentences given to Paul Wallace *447 and David Shoup, because the two-year misdemeanors of which they were convicted could be considered "felonies" for purposes of the probation statute.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all the reasons above, we affirm the convictions *460 of and sentences received by all four defendants.', 'sentencing', 'People v. Smith', 'https://www.courtlistener.com/opinion/2189786/', '2189786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/2189862/', '2189862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Soto', 'https://www.courtlistener.com/opinion/2189862/', '2189862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the evidence in this case would have been admissible in separate trials, we
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '8(d), and we affirm the judgment.', 'general', 'State of Maine v. Havier Olmo', 'https://www.courtlistener.com/opinion/2760899/', '2760899') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Davis case is inapposite and that, therefore, the § 1447 conviction and sentence in the instant case do not fall by reason thereof.', 'sentencing', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Davis, we held that "defendant''s conviction under the weapons statute [§ 1447] cannot stand," 400 A.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Davis we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1]  Justice Rehnquist summarized Whalen on double jeopardy in the following manner: "[S]ix Members of this Court held that Congress'' intent to impose cumulative punishments at a single criminal proceeding completely controlled the question of double jeopardy.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons and the reasons stated in Part IV hereof, we conclude that § 1447 creates an offense distinct from the underlying § 613(1) felony of Assault First Degree, and that it was the legislative intent to subject this defendant to multiple penalties for the single criminal act in which she engaged.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the foregoing opinion, we concluded that the Blockburger rule was a rule of substantive law for determining whether two statutes proscribed the "same offense" for double jeopardy purposes.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/2191286/', '2191286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that Lucas’ movement and confinement were beyond that necessary to consummate the attempted especially aggravated robbery.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that due process principles, specifically article I, section 8 of the Tennessee Constitution, require us to determine “whether the confinement, movement, or detention is essentially incidental to the accompanying felony .', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the kidnappings were “essentially incidental” based upon the following factors: (1) the removal or confinement did not substantially increase the risk of harm to the victims;', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that Dixon’s movement of the victim to the back of a dark lot was beyond that necessary to consummate the attempted sexual battery because Dixon could have attempted to sexually penetrate the victim on the lighted path where he initially assaulted her.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Dixon moved the victim to the back of a dark lot to avoid detection.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While Howell’s movement to and confinement in the stockroom may have been helpful to Richardson, we conclude that this movement and confinement were beyond that necessary to consummate the attempted especially aggravated robbery.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the use of force for an excessively long period shows that Lucas was no longer confined to assist in opening the safe.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the intermediate appellate court and reinstate the convictions.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Criminal Appeals and reinstate the especially aggravated kidnapping convictions.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2191551/', '2191551') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Simms-Malone was in a position to discuss the encumbrances with her clients but she failed to do so.', 'general', 'Kendall v. State', 'https://www.courtlistener.com/opinion/2192210/', '2192210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Superior Court to admit the Maryland evidence as direct proof of Theft by False Pretense and of a pattern of Racketeering.', 'general', 'Kendall v. State', 'https://www.courtlistener.com/opinion/2192210/', '2192210') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court had the authority to modify this illegal condition of probation under § 16-90-111 (a).', 'general', 'Reeves v. State', 'https://www.courtlistener.com/opinion/2192485/', '2192485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The defendant appealed from denial of her motion to correct an illegal sentence, and we held that the sentence was unauthorized and remanded the case for resentencing.', 'sentencing', 'Reeves v. State', 'https://www.courtlistener.com/opinion/2192485/', '2192485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Sherman, supra, we held that the defendant could not appeal from the denial of a posttrial motion to correct an unexpected increase in his sentence following a guilty plea, because the increased sentence was an integral part and a direct result of his plea.', 'sentencing', 'Reeves v. State', 'https://www.courtlistener.com/opinion/2192485/', '2192485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the order in the instant case falls within an acknowledged exception to our rule disallowing appeals from guilty pleas.', 'plea', 'Reeves v. State', 'https://www.courtlistener.com/opinion/2192485/', '2192485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree that the condition requires her exile, and we reverse the trial court’s order and remand the matter for resentencing in accordance with this opinion.', 'sentencing', 'Reeves v. State', 'https://www.courtlistener.com/opinion/2192485/', '2192485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed for three reasons: (1) defense counsel agreed that resentencing, following the hearing, could be based on the full range of punishment;', 'sentencing', 'Reeves v. State', 'https://www.courtlistener.com/opinion/2192485/', '2192485') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the facts of this case, the defendant was properly convicted under both the aiding and abetting and conspiracy statutes.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/2192622/', '2192622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the totality of the circumstances, therefore, we hold that Potter’s in-court identification was supported by .', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/2192622/', '2192622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '411 Mich 342, we held that conviction and sentence for both first-degree felony murder and the underlying felony also contravened the state constitutional provision, because in that case "the evidence needed to prove first-degree felony murder require^] proof of the underlying lesser included felony”.', 'sentencing', 'People v. Carter', 'https://www.courtlistener.com/opinion/2192622/', '2192622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '236 NW2d 461 (1975), this Court held that a trial judge’s refusal to give a requested instruction on a lesser included offense supported by the evidence was reversible error.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/2192622/', '2192622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whether we focus on the desirability of a precise definition of the prosecutor’s duty or on the potential harm to the defendant, we conclude that there is no significant difference between cases in which there has been merely a general request for exculpatory matter and cases, like the one we must now decide, in which there has been no request at all.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/2192622/', '2192622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the facts of this case, we find that any error that may have occurred was cured by the cautionary instruction.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/2192622/', '2192622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm defendant’s convictions of extortion under an aiding and abetting theory and conspiracy to commit extortion.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/2192622/', '2192622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm defendant’s conviction of aiding and abetting the commission of extortion and conspiracy to commit extortion.', 'general', 'People v. Carter', 'https://www.courtlistener.com/opinion/2192622/', '2192622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these standards, we hold that the trial judge could not reasonably find beyond a reasonable doubt that appellant’s actions were calculated to lead to a breach of the peace.', 'general', 'Shepherd v. District of Columbia', 'https://www.courtlistener.com/opinion/2278974/', '2278974') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), we held that the record "fails to support a finding that appellant created a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reversed the conviction for insufficient evidence where a crowd had gathered after a policeman grabbed the juvenile-defendant’s bicycle and the latter began yelling and cursing at the officer, but where no evidence implied that the defendant “was .', 'general', 'Shepherd v. District of Columbia', 'https://www.courtlistener.com/opinion/2278974/', '2278974') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that Georgia''s robbery by sudden snatching is not a qualified offense for purposes of Florida''s habitual felony offender statute.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1136713/', '1136713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed herein, we find that the Florida and Georgia crimes differ as to their elements.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1136713/', '1136713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accord with our decision in McCloud, we find that in order for the snatching of property from another to amount to robbery, the perpetrator must employ more than the force necessary to remove the property from the person.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1136713/', '1136713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we find that the degree of force used in snatching someone''s purse or other property from their person, even where that person does not resist and is not injured, is sufficient to satisfy the force or violence element of robbery in Florida.', 'general', 'Robinson v. State', 'https://www.courtlistener.com/opinion/1136713/', '1136713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the plain language of ง 973.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As there is no dispute that Stenklyft had completed 75 percent of the initial confinement portion of his sentence at the time his petition was filed, we hold that Stenklyft''s petition in this case was not premature.', 'sentencing', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Tucker, this court held that ง 973.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 128 (1890), this court held unconstitutional a statute that required a trial court to issue an injunction, even though the petitioner did not prove damages justifying an injunction.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '407 (1923), this court held unconstitutional a statute prohibiting a trial court from granting a directed verdict before submitting the case to the jury.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 584 (1983), this court held that the legislature could require a circuit court to give the jury a copy of written instructions but could not mandate reversal if the circuit court did not abide by the statute.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the crime for which Stenklyft was convicted is now classified as a Class F felony and there is no dispute that he served 75 percent of the initial confinement portion of his sentence, we conclude that his petition for sentence adjustment was not premature under ง 973.', 'sentencing', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that ง 973.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the plain language of ง 973.', 'general', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not reach this issue because even assuming, arguendo, that the power to modify sentences is an exclusive power of the judiciary, we conclude that ง 973.', 'sentencing', 'State v. Stenklyft', 'https://www.courtlistener.com/opinion/2194155/', '2194155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that aggravating factor c(4)(f) may be submitted to the jury when the State has produced sufficient *283 evidence on which a jury can reasonably conclude that at least one of the motives of the defendant in killing his or her victim was to eliminate a witness or avoid subsequent apprehension and prosecution for criminal acts.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant never requested such an instruction, nor did the jury make an inquiry into the subject, we hold that no error resulted.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we hold that in the future when defense counsel or the jury requests instructions on the potential sentences a defendant will receive for convictions arising from the same trial as his capital-murder conviction, such information should be provided by the trial court.', 'sentencing', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 185 (1966), we held that the Constitution does not require a grand jury presentment before a convicted defendant may receive an enhanced sentence based on his status as a habitual offender.', 'sentencing', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, in Purnell, supra, we held that when the State sought to establish, as an aggravating factor, that a murder was committed in the course of a felony, the defendant was entitled to have the jury consider the non-capital verdict of felony-murder during the guilt-phase deliberations.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that opinion we held that defendants who had been served with a notice of an aggravating factors could, through summary proceedings before the trial court, challenge the sufficiency of the evidence to support those factors.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "our law does not regard a crime committed against a particularly virtuous person as more heinous than one committed against a victim whose moral qualities are perhaps less noteworthy or apparent.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because the defense is allowed to introduce mitigating evidence outside of the Rules of Evidence during the penalty phase to ensure that the jury imposes death only when the defendant is deserving of the punishment, the State should also be permitted to rebut that evidence under the same relaxed conditions.', 'general', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of that concern for the reliability of the jury''s verdict, we held that the court, either on defendant''s request or in the event of a jury inquiry, should instruct the jury that the court will decide whether a sentence is to be served concurrently or consecutively to any prior sentences.', 'sentencing', 'State v. Martini', 'https://www.courtlistener.com/opinion/2265144/', '2265144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, given these facts, a reasonable person should have known his or her act would be open to the observation of others.', 'general', 'Parnigoni v. District of Columbia', 'https://www.courtlistener.com/opinion/2194792/', '2194792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Parnigoni’s claim that O.', 'general', 'Parnigoni v. District of Columbia', 'https://www.courtlistener.com/opinion/2194792/', '2194792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 221-222, we conclude that the jury could have reasonably found that Parnigoni exposed his genitalia to J.', 'general', 'Parnigoni v. District of Columbia', 'https://www.courtlistener.com/opinion/2194792/', '2194792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that the appellant’s exposure of her buttocks and the side of her breast was insufficient exposure to sustain a conviction under section 22-1312.', 'general', 'Parnigoni v. District of Columbia', 'https://www.courtlistener.com/opinion/2194792/', '2194792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions.', 'general', 'Parnigoni v. District of Columbia', 'https://www.courtlistener.com/opinion/2194792/', '2194792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence is sufficient to support Parnigoni’s conviction for indecent exposure as to J.', 'general', 'Parnigoni v. District of Columbia', 'https://www.courtlistener.com/opinion/2194792/', '2194792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3]  Although we reverse Casey''s conviction for intimidation, we note that this decision has no impact on his sentence.', 'sentencing', 'Casey v. State', 'https://www.courtlistener.com/opinion/2195008/', '2195008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that Carawan has been overridden for offenses that occur after the effective date of chapter 88-131, section 7, but the override will not be retroactively applied.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1861895/', '1861895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we concluded that, by its terms, the rule of lenity controls and prohibits multiple punishments for the two offenses, even if each contains a unique statutory element and are separate offenses under subsection 775.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1861895/', '1861895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court had territorial jurisdiction in this case because an element of first-degree sexual abuse, the use of force for the purpose of compelling sexual activity, occurred within the boundaries of the District of Columbia.', 'general', 'Dyson v. United States', 'https://www.courtlistener.com/opinion/2195647/', '2195647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we conclude that the trial court properly admitted the testimony of a hospital nurse under the report of rape hearsay exception, and did not abuse its discretion in permitting the joinder of offenses occurring on two different dates and involving different complainants but the same defendant.', 'general', 'Dyson v. United States', 'https://www.courtlistener.com/opinion/2195647/', '2195647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s contextual view of the case as an ongoing
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the foregoing reasons, we affirm the judgment of the trial court.', 'general', 'Dyson v. United States', 'https://www.courtlistener.com/opinion/2195647/', '2195647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that evidence of Jacobson’s mistake of law is admissible because it is relevant to whether he intended to break the law — an element of the conspiracy charges.', 'general', 'State v. Jacobson', 'https://www.courtlistener.com/opinion/2195903/', '2195903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that evidence relating to a defendant’s misunderstanding of the law is admissible when relevant to whether the defendant had the intent required for the charged offense.', 'general', 'State v. Jacobson', 'https://www.courtlistener.com/opinion/2195903/', '2195903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that, on the record before us and based on the pending charges, Jacobson has a right to present evidence that he relied on Tigue’s advice and on Chief Deputy Dakota County Attorney Prokopowicz’s letter regarding the Minneapolis police officer matter.', 'general', 'State v. Jacobson', 'https://www.courtlistener.com/opinion/2195903/', '2195903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Public Act 88-680 violates the single subject clause of the Illinois Constitution (Ill.', 'general', 'People v. Cervantes', 'https://www.courtlistener.com/opinion/2197155/', '2197155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Public Act 88-680 illustrates this disfavored practice of "logrolling," wherein less popular legislation was bundled with more palatable bills, so that the well-received bills would carry the unpopular ones to passage.', 'general', 'People v. Cervantes', 'https://www.courtlistener.com/opinion/2197155/', '2197155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the circuit court and hold that Public Act 88-680 violates the single subject requirement.', 'general', 'People v. Cervantes', 'https://www.courtlistener.com/opinion/2197155/', '2197155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the convictions must be reversed and we remand for a new trial.', 'general', 'State v. Millett', 'https://www.courtlistener.com/opinion/2197265/', '2197265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we conclude that the prosecutor''s persistent emphasis on the clothing exchange at Forgione''s as evidence of defendant''s consciousness of guilt was *92 significant, prejudicial, and could have led to a result which the jury might not otherwise have reached on this evidence.', 'general', 'State v. Millett', 'https://www.courtlistener.com/opinion/2197265/', '2197265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the proximity of time and place satisfies the relevance standard of Sturdivant, supra, 31 N.', 'general', 'State v. Millett', 'https://www.courtlistener.com/opinion/2197265/', '2197265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the trial judge did not err in refusing to dismiss the indictment for violation of the Interstate Agreement on Detainers (IAD).', 'dismissal', 'State v. Millett', 'https://www.courtlistener.com/opinion/2197265/', '2197265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since this error had the capacity to deprive defendant of a fair trial, we reverse.', 'general', 'State v. Millett', 'https://www.courtlistener.com/opinion/2197265/', '2197265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal to this court, we reversed this ruling and counsel withdrew.', 'general', 'State v. Millett', 'https://www.courtlistener.com/opinion/2197265/', '2197265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a trial court may not impose waiver of appointed appellate counsel as a plea condition.', 'plea', 'People v. Billings', 'https://www.courtlistener.com/opinion/2197325/', '2197325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a trial court may not impose a waiver of appointed appellate counsel from a defendant before accepting a guilty plea and that doing so is unconstitutional.', 'plea', 'People v. Billings', 'https://www.courtlistener.com/opinion/2197325/', '2197325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant is not entitled to any relief, because even with our corrections to the guidelines scoring, defendant received a sentence that was below the guidelines range.', 'sentencing', 'People v. Billings', 'https://www.courtlistener.com/opinion/2197325/', '2197325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to defendants’ other issues, we affirm both convictions and sentences.', 'sentencing', 'People v. Billings', 'https://www.courtlistener.com/opinion/2197325/', '2197325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both defendants’ convictions and sentences.', 'sentencing', 'People v. Billings', 'https://www.courtlistener.com/opinion/2197325/', '2197325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, while we conclude that the evidence was sufficient to sustain defendant’s conviction, regardless of whether Officer Hoffman acquired probable cause to make a felony arrest during the traffic stop, we nonetheless reject defendant’s argument that Officer Hoffman was acting unlawfully when he informed defendant of his intention to arrest him.', 'probable_cause', 'People v. Chapo', 'https://www.courtlistener.com/opinion/2197767/', '2197767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Chapo', 'https://www.courtlistener.com/opinion/2197767/', '2197767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that guilty knowledge is an element of possession of a controlled substance under section 893.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that guilty knowledge is part of the statutory offenses charged.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the State was required to prove that Chicone knew of the illicit nature of the items in his possession.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '147(1), we hold that the trial court did not err in denying petitioner''s motion to dismiss the information.', 'dismissal', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[14] We hold that the defendant was entitled to a more specific instruction as requested here.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That is, we held that the State established a prima facie case and sufficient proof that the "defendant was aware of the nature of the drug" to get the case to the jury.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we conclude that good sense and the background rule of the common law favoring a scienter requirement *744 should govern interpretation of the two statutes in this case.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the State was not required to allege guilty knowledge in the information charging petitioner.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although by statutory construction we find that guilty knowledge is an element of the crimes defined in sections 893.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, since we find that guilty knowledge is implicit in the concept of possession as provided in the statute, it need not be specifically alleged in the information in a manner more explicit than that provided in the statute.', 'general', 'Chicone v. State', 'https://www.courtlistener.com/opinion/1868410/', '1868410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding issues warranting reversal of Lanier''s conviction, we reverse and remand for a hearing to determine whether Lanier may be retried.', 'general', 'Lanier v. State', 'https://www.courtlistener.com/opinion/1869152/', '1869152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Due to errors below, we reverse and remand for proceedings consistent herewith.', 'general', 'Lanier v. State', 'https://www.courtlistener.com/opinion/1869152/', '1869152') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the false testimony affected only the credibility of the witness which could be properly weighed and determined by the jury.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that tape recorded discussions were relevant to a defense of entrapment and were not hearsay because they showed the effect of the statements on the police officer’s state of mind.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the facts of the present case, we find that the statement of the unidentified informant was inadmissible hearsay under D.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we find that the confidential informant’s statement in this case was inadmissible hearsay under D.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that the statement of the unidentified informant was inadmissible by application of a standard which balances the dangers of hearsay testimony with the need for evidence in a criminal case, a review of the State’s complete case against Johnson shows that the error of admitting the hearsay testimony was harmless.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if we view the evidence in this case under the stricter standard required for evidentiary errors of constitutional magnitude, we find that the other evidence against Johnson was sufficient to sustain his convictions.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the jury would have reached the same result without the hearsay testimony identifying Johnson.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 449 (1982), where we found that out-of-court statements were admissible to explain police action.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After hearing oral argument and reviewing the record and the briefs, we affirm the decision of the Superior Court.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2202032/', '2202032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this Court held that there appeared to be no unfairness or injury by the course of action pursued.', 'general', 'State v. Roberge', 'https://www.courtlistener.com/opinion/2209046/', '2209046') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the jury action was in correction of the original verdict, rather than an impeachment of it.', 'general', 'State v. Roberge', 'https://www.courtlistener.com/opinion/2209046/', '2209046') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Roberge', 'https://www.courtlistener.com/opinion/2209046/', '2209046') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that a violation of this statute was a misdemeanor punishable under F.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/1901008/', '1901008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '* * * Accordingly, we hold that section 5-401.', 'general', 'People v. Carpenter', 'https://www.courtlistener.com/opinion/2203829/', '2203829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that section 12-612 of the Code is facially invalid on due process grounds.', 'general', 'People v. Carpenter', 'https://www.courtlistener.com/opinion/2203829/', '2203829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we held that these statutes were invalid.', 'general', 'People v. Carpenter', 'https://www.courtlistener.com/opinion/2203829/', '2203829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2 potentially subjects * * * innocent conduct to such a severe penalty, we find that it does not contain a reasonable means of preventing the trafficking of stolen vehicles and parts.', 'general', 'People v. Carpenter', 'https://www.courtlistener.com/opinion/2203829/', '2203829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'court, we conclude that a reasonable jury could find that the individual wax packets “presented an
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that any presumption that the word “knowingly” should extend to the amount of drugs
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Kirby Davis', 'https://www.courtlistener.com/opinion/4735784/', '4735784') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because one can obviously possess narcotics paraphernalia without necessarily possessing or using a controlled substance, we hold that possession of narcotics paraphernalia is not a lesser-included offense of personal possession or use for purposes of § 13-901.', 'general', 'State v. Estrada', 'https://www.courtlistener.com/opinion/2631820/', '2631820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm both decisions.', 'general', 'State v. Estrada', 'https://www.courtlistener.com/opinion/2631820/', '2631820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we hold that the First Amendment to the United States Constitution prohibits L.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, this court held that Pritzlaff''s claim for negligent supervision was precluded by the First Amendment because it would require an inquiry into church laws, practices, and policies.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This further explains why this court held that negligent *691 supervision claims are "prohibited by the First Amendment under most if not all circumstances.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s claim, we conclude that the undisputed facts and all reasonable inferences drawn therefrom do not establish a genuine issue of material fact as to whether the Diocese knew or should have known about Clauder''s alleged propensity to use his position as chaplain to sexually exploit patients whom he counseled.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s claim, we conclude that the undisputed facts and all reasonable inferences drawn therefrom do not establish a genuine issue of material fact in regard to the element of notice.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the undisputed facts and all reasonable inferences drawn therefrom do not demonstrate a genuine issue of material fact as to whether the Diocese should have known about Clauder''s alleged propensity to use his position as chaplain to sexually exploit patients.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the First Amendment precludes L.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s claim, we conclude that the undisputed facts and all reasonable inferences drawn therefrom do not establish a genuine issue of material fact in regard to whether the Diocese knew or should have known about Clauder''s alleged propensity to use his position as chaplain to sexually exploit patients whom he counseled.', 'general', 'L.L.N. v. Clauder', 'https://www.courtlistener.com/opinion/1877768/', '1877768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that no error has been shown, we affirm.', 'general', 'Aurigemma v. State', 'https://www.courtlistener.com/opinion/1881308/', '1881308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, because the offense of reckless driving does not contain any element not present in the offense of reckless homicide, we hold that reckless driving is a lesser-included offense of reckless homicide.', 'general', 'People v. Sienkiewicz', 'https://www.courtlistener.com/opinion/2207964/', '2207964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After applying the relevant six-factor test, we conclude that the reckless homicide charge and reckless driving conviction are both based on the same physical act.', 'general', 'People v. Sienkiewicz', 'https://www.courtlistener.com/opinion/2207964/', '2207964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that plaintiff''s status under furlough more closely resembles that of an inmate seeking a particular right or status within an institution, rather than that of a parolee.', 'general', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 493, we held that the Vermont Constitution requires a mental health patient, who had been conditionally discharged from the state mental institution and placed in the community, to be given a hearing before that discharge is revoked.', 'general', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the liberty interests involved in G.', 'general', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1132, 1133 (1992), in which we held that an inmate who requested counsel on a habeas petition was wrongfully denied it on the grounds that the defender general''s office was unable to handle the case.', 'habeas', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Conway v. Cumming', 'https://www.courtlistener.com/opinion/2208175/', '2208175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a probation revocation proceeding is a civil proceeding.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 296 (1986), we held that in a sexually dangerous person proceeding, the defendant was not entitled to refuse to answer a psychiatrist''s questions which might incriminate him.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Peterson, we held that collateral estoppel prohibited the State from challenging a finding that the defendant''s confession was involuntary at a subsequent probation revocation hearing.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that an involuntary confession cannot be admitted against a defendant in a probation revocation hearing.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, rather than "blindly follow the reasoning of a United States Supreme Court decision at all costs," this court should rely on its own case law, wisdom and reason to construe our state constitutional provisions.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it should not.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 631 (1977) ("Because of the statutory history of use of the contempt sanction for probation violations, the similarity between sentences of probation and periodic imprisonment and analogy to the common law treatment of sanctioning willful violations of other court orders by contempt, we conclude that a trial court is empowered to punish a willful violation of a condition of periodic imprisonment by holding the violator in indirect criminal contempt").', 'sentencing', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the above principles to the instant case, we find that defendant''s testimony at his probation revocation hearing was not a violation of defendant''s privilege against self-incrimination, under article I, section 10.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that defendant''s testimony at his probation revocation hearing was not a violation of defendant''s right against self-incrimination, pursuant to article I, section 10.', 'general', 'People v. Lindsey', 'https://www.courtlistener.com/opinion/2211377/', '2211377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has failed to show that the legislature exceeded its authority in implementing section 12 — ll(a)(3)’s mandatory add-on sentencing scheme.', 'sentencing', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the former, we conclude that the purpose of subsections (a)(1) and (a)(2) is still to protect the safety of persons in their homes.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the pervasive and enhanced danger arising from an intruder’s possession of a firearm, the legislature’s superior position to identify and address the evils of gun-related violence, and the presumptive constitutionality of a legislative enactment, we conclude that the purpose of subsections (a)(1) and (a)(2) are sufficiently distinct from that of subsection (a)(3) to make proportionality review inappropriate.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we find that mandatory sentencing schemes do not inherently usurp the judiciary’s power to impose a sentence.', 'sentencing', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we find that section 12 — 11(a)(3) does not violate the separation of powers clause.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it does not.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that section 12 — ll(a)(3)’s add-on sentencing scheme does not completely divest the circuit court of its ability to consider aggravating and mitigating factors.', 'sentencing', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a 21-to-45-year sentence for violating section 12 — 11(a)(3) is not cruel or degrading, nor does it shock the moral conscience.', 'sentencing', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'People v. Hill', 'https://www.courtlistener.com/opinion/2211410/', '2211410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the search violated Grant''s Fourth Amendment rights, we reverse the conviction, overturn the trial court''s denial of her motion to suppress, and remand for further proceedings.', 'suppression', 'State v. Grant', 'https://www.courtlistener.com/opinion/2211483/', '2211483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence of arson was legally sufficient and reinstate defendant''s convictions of felony murder.', 'general', 'People v. Nowack', 'https://www.courtlistener.com/opinion/2211727/', '2211727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We hold that the evidence was sufficient to establish the elevated level of intent required by the standard instruction.', 'general', 'People v. Nowack', 'https://www.courtlistener.com/opinion/2211727/', '2211727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 160 (1995), we held that "the word `arson'' in the felony murder statute refers to the common-law crime of arson, that is, the malicious and voluntary or wilful burning of a dwelling house of another.', 'general', 'People v. Nowack', 'https://www.courtlistener.com/opinion/2211727/', '2211727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an appellate court reviewing a competency determination must use the methodology set forth in Garfoot.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that although the circuit court had a duty to inform Byrge about the parole eligibility information before it accepted his plea, the State has met its burden to prove that, despite the deficiency of the plea colloquy, Byrge nonetheless entered the plea knowingly, voluntarily, and intelligently.', 'plea', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an appellate court reviewing a competency determination must utilize the clearly erroneous standard.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 351 (1975), in which we held that a circuit court is not required to notify defendants about parole rights.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Garfoot, a majority of this court held that competency to stand trial must be reviewed under the deferential clearly erroneous standard.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when a circuit court exercises its statutory option to fix a parole eligibility date, that date has a direct and automatic effect on the range of punishment.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our analysis of the case law since Fulford, we conclude that the Supreme Court classifies competency to stand trial within a discrete category in which the resolution of the legal issue is better left to the trial court.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the circuit court did not inform Byrge about a potential direct consequence of his conviction, we conclude that Byrge has made a prima facie showing that the plea was not knowing, voluntary, and intelligent according to the requirements outlined in Wis.', 'plea', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not disturb this finding of fact because we conclude that the circuit court''s determination was not clearly erroneous.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the circuit court''s decision that Byrge was competent to stand trial was not clearly erroneous because testimony at the competency hearing indicated Byrge was able to understand the proceedings and assist in his defense.', 'general', 'State v. Byrge', 'https://www.courtlistener.com/opinion/2211822/', '2211822') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2006), we held that, because only a felony conviction will justify a war-rantless, suspicionless search for DNA, requiring only probable cause of a felony offense to justify a warrantless, suspicion-less search for DNA is constitutionally insufficient;', 'probable_cause', 'State v. Johnson', 'https://www.courtlistener.com/opinion/2234289/', '2234289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a judicial finding of probable cause that a felony has been committed was not, by itself, sufficient to justify DNA collection pursuant to Minn.', 'probable_cause', 'State v. Johnson', 'https://www.courtlistener.com/opinion/2234289/', '2234289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'substantial state interests against the diminished privacy expectations and minimal intrusion that exist here, we conclude that Minn.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/2234289/', '2234289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Johnson', 'https://www.courtlistener.com/opinion/2234289/', '2234289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In response to the State of Hawai''i’s (the prosecution) petition, we granted certiorari to review the ICA’s holding, and, for the reasons set forth below, we hold that the trial court did not err in concluding that the police officer’s testimony about the absent witness’s statements constituted inadmissible hearsay.', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court correctly ruled that Officer Cravalho’s cross-examination testimony about Michael’s statements in the HPD-252 forms was inadmissible hearsay.', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the prosecution and in full recognition of the province of the trier of fact, we hold that the evidence was sufficient to support a prima facie case of assault in the second degree without justification, and thus, a reasonable mind might fairly conclude that Jhun was guilty beyond a reasonable doubt.', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court correctly ruled that Officer Cravalho’s cross-examination testimony about Michael’s statements in the HPD-262 forms was inadmissible hearsay.', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that the trial court did not err when it denied Jhun’s post-verdict motion for judgment of acquittal.', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record and all of the remaining issues that Jhun has raised on appeal, we hold that Jhun’s arguments regarding those remaining issues are without merit.', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the police report was not admissible under Rule 803(8)(iii).', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we reverse the ICA’s decision in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'thermore, after reviewing the remaining issues that Jhun has raised in his appeal, we affirm Jhun’s conviction of assault in the second degree.', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm the trial court’s denial of Jhun’s post-verdict motion for judgment of acquittal.', 'general', 'State v. Jhun', 'https://www.courtlistener.com/opinion/1123041/', '1123041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that an action brought under Indiana Code § 3$4-4-80-1 must be commenced within two years after the cause of action accrues.', 'general', 'Browning v. Walters', 'https://www.courtlistener.com/opinion/2234768/', '2234768') ON CONFLICT DO NOTHING;
