INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Count III of Browning''s complaint fails to state a common law claim upon which relief can be granted, and the trial court properly dismissed Count IIL.', 'dismissal', 'Browning v. Walters', 'https://www.courtlistener.com/opinion/2234768/', '2234768') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Browning v. Walters', 'https://www.courtlistener.com/opinion/2234768/', '2234768') ON CONFLICT DO NOTHING;
