INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the marijuana cigarette butts found in the ashtray, we conclude that their seizure is not sustainable under a consent theory, since the trooper neither asked for nor received permission to search the passenger compartment.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1095147/', '1095147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we conclude that the seizure of the marijuana cigarette butts in this instance was permissible as an incident of a proper impoundment.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1095147/', '1095147') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that the impoundment in this instance, and hence the search of the interior of the car that followed was proper under Bertine.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1095147/', '1095147') ON CONFLICT DO NOTHING;
