INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that under the facts and circumstances of the instant case the State failed to prove that the screwdriver was a weapon, i.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/1108002/', '1108002') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990)] we found that, where the "place" in question is a residence, the defendant must have a "substantial connection" to the home and must be more than a "casual visitor" in order to satisfy this element.', 'general', 'Ashley v. State', 'https://www.courtlistener.com/opinion/1110723/', '1110723') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, because we find that the allegation regarding weapons was surplusage, it was not necessary for it to be included in the jury instruction as an allegation which must be proved in order to convict.', 'jury_instruction', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the variance was not fatal.', 'general', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court made a proper sentencing statement with respect to this aggravating circumstance.', 'sentencing', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the trial court did engage in an evaluative balancing process, as discussed below, the trial court satisfied the second requirement of properly articulating the reasons why each factor was an aggravating or mitigating circumstance.', 'general', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that all three of the aggravating circumstances that the trial court identified were improperly applied as a justification for enhanced and consecutive sentences.', 'sentencing', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'VII, § 4, we find that it would be proper and just under the circumstances for defendant to serve the enhanced and consecutive sentences imposed.', 'sentencing', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it is appropriate under these circumstances for the defendant to serve the enhanced and consecutive sentences imposed.', 'sentencing', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court.', 'general', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'Mitchem v. State', 'https://www.courtlistener.com/opinion/2241986/', '2241986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State''s evidence was sufficient to submit to the jury and likewise was sufficient to sustain the jury''s verdict.', 'general', 'Craig v. State', 'https://www.courtlistener.com/opinion/1115491/', '1115491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, we find that appellant''s actions, when viewed in a light most favorable to the State, constituted "theft of property" as defined in the above section.', 'general', 'Craig v. State', 'https://www.courtlistener.com/opinion/1115491/', '1115491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), we find that the classification described in §13A-8-4 (e) furthers a proper governmental purpose and is rationally related to the purpose for which it was created.', 'general', 'Craig v. State', 'https://www.courtlistener.com/opinion/1115491/', '1115491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that scoring 100 points pursuant to MCL 777.', 'general', 'People v. Osantowski', 'https://www.courtlistener.com/opinion/839709/', '839709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse in part the judgment of the Court of Appeals and reinstate the Macomb Circuit Court’s judgment of sentence.', 'sentencing', 'People v. Osantowski', 'https://www.courtlistener.com/opinion/839709/', '839709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse the portion of the Court of Appeals judgment addressing OV 20 and reinstate the trial court’s score of zero points for OV 20 and judgment sentencing defendant to 30 months’ to 20 years’ imprisonment for the crimes of making a terrorist threat and using a computer to commit a crime.', 'sentencing', 'People v. Osantowski', 'https://www.courtlistener.com/opinion/839709/', '839709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm the judgment of the Greene County Circuit Court.', 'general', 'Boatner v. State', 'https://www.courtlistener.com/opinion/1133633/', '1133633') ON CONFLICT DO NOTHING;
