INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the appellant''s arrest and search were valid.', 'general', 'Congo v. State', 'https://www.courtlistener.com/opinion/1139516/', '1139516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the May 5, 2009 opinion of the Court of Appeals,1 reinstate defendant’s convictions, and remand to the Court of Appeals for that Court to consider defendant’s remaining arguments on appeal.', 'general', 'People v. Mardlin', 'https://www.courtlistener.com/opinion/830372/', '830372') ON CONFLICT DO NOTHING;
