INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the indictment was not constructively amended, and that the trial judge committed no error, much less plain error, in permitting the prosecutor to dismiss the “while armed” portion of the murder charge and to proceed on a theory that the baby was killed during the 5:00 a.', 'dismissal', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that “[w]hile the use of a police car to transport a suspect to the stationhouse might in other circumstances add to the coercive aspects of the questioning, it did not do so here.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the issue is not without difficulty, we conclude that the trial judge’s interpretation of the proper scope of the confidential communications privilege under D.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, after examining common law precedents regarding the proper scope of the marital privilege and in view of the legislative judgment about exceptions to the privilege, we conclude that the exception to the confidential communications privilege is applicable in the instant case.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that the legislatures have simply never addressed the issue presented in this appeal.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only when an officer, by means of physical force or show of authority, has in some way restrained the liberty of a citizen may we conclude that a “seizure” has occurred.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, under the limited circumstances here, where the materials sought did not fall, within the scope of the challenge to trial counsel under § 23-110, and in view of the undisputed fact found by the trial judge that PDS “had been extremely helpful and forthcoming” with successor counsel, we conclude that the trial judge did not abuse his discretion in denying the discovery motion.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because appellant’s other contentions are unpersuasive, we affirm.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgments.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2278027/', '2278027') ON CONFLICT DO NOTHING;
