INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we conclude that defendants’ alleged conduct falls within the ambit of MCL 750.', 'general', 'People v. Schutter', 'https://www.courtlistener.com/opinion/1278645/', '1278645') ON CONFLICT DO NOTHING;
