INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Howell, n 2 supra, p 21, a plurality of this Court held that the gross indecency statutes prohibit oral sexual acts with a person under the age of consent.', 'general', 'People v. Lino', 'https://www.courtlistener.com/opinion/1303659/', '1303659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these changes [developments in the right to privacy] and in light of our own awareness that community values on the subject of permissible sexual conduct no longer are as monolithic as the Jaquith case suggested they were in 1954, we conclude that [Mass Ann Laws, ch 272, § 35] must be construed to be inapplicable to private, consensual conduct of adults.', 'general', 'People v. Lino', 'https://www.courtlistener.com/opinion/1303659/', '1303659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lino, we reverse the decision of the Court of Appeals and we affirm the defendant''s conviction.', 'general', 'People v. Lino', 'https://www.courtlistener.com/opinion/1303659/', '1303659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brashier, we reverse the decision of the Court of Appeals in part and affirm in part.', 'general', 'People v. Lino', 'https://www.courtlistener.com/opinion/1303659/', '1303659') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he does.', 'general', 'Playmates Toys v. Director of Tax.', 'https://www.courtlistener.com/opinion/2259337/', '2259337') ON CONFLICT DO NOTHING;
