INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”5 Thus, this Court held that an owner’s consent to an intermediate user included the consent to any subsequent users of the vehicle, even when the owner set restrictions on the use by the intermediate user.', 'general', 'Spectrum Health Hospitals v. Farm Bureau Mutual Ins Co of Michigan', 'https://www.courtlistener.com/opinion/824276/', '824276') ON CONFLICT DO NOTHING;
