INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court erred by granting defendant’s request that the jury be instructed on moving violation causing death.', 'general', 'People v. Jones', 'https://www.courtlistener.com/opinion/2764782/', '2764782') ON CONFLICT DO NOTHING;
