INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, he argues that Seibel is factually similar to this case, and in Seibel this court held that an officer had reasonable suspicion that the defendant was operating while intoxicated.', 'general', 'State v. Michael R. Tullberg', 'https://www.courtlistener.com/opinion/2764887/', '2764887') ON CONFLICT DO NOTHING;
