INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reversed Barnett’s PDWPP conviction.', 'general', 'Lecates v. State', 'https://www.courtlistener.com/opinion/2270404/', '2270404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm Williams’s felony-evasion conviction and sentence of five years’ imprisonment.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/4996128/', '4996128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore we affirm.', 'general', 'State v. Hardin', 'https://www.courtlistener.com/opinion/1954518/', '1954518') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these facts and cireumstances, we conclude that the trial court could properly consider Rodriguez''s clear abuse of alcohol and the time of day of Rodriguez''s conduct together as a separate and proper aggravating cireumstance.', 'general', 'Rodriguez v. State', 'https://www.courtlistener.com/opinion/2029906/', '2029906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, and with the acknowledgement that this was an extraordinarily difficult sentencing for the trial court, and hardly less so for this court, we conclude that the trial court did not and could not appropriately weigh the aggravating and mitigating circumstances to determine that the aggravators outweighed the mitigators so as to warrant the maximum eight-year sentence.', 'sentencing', 'Rodriguez v. State', 'https://www.courtlistener.com/opinion/2029906/', '2029906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the trial court improperly evaluated Rodriguez''s aggravating and mitigating cireumstances and, therefore, the sentence was inappropriate.', 'sentencing', 'Rodriguez v. State', 'https://www.courtlistener.com/opinion/2029906/', '2029906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court improperly used the impact on the victim''s family as an aggravating circumstance.', 'general', 'Rodriguez v. State', 'https://www.courtlistener.com/opinion/2029906/', '2029906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court improperly used the fact that the imposition of a reduced sentence would reduce the seriousness of the crime as an aggravating cireumstance.', 'sentencing', 'Rodriguez v. State', 'https://www.courtlistener.com/opinion/2029906/', '2029906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that trial court properly declined to attach any significant weight to this proffered mitigating cireumstance.', 'general', 'Rodriguez v. State', 'https://www.courtlistener.com/opinion/2029906/', '2029906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we find that Rodriguez''s character does not merit the maximum allowable sentence of eight years.', 'sentencing', 'Rodriguez v. State', 'https://www.courtlistener.com/opinion/2029906/', '2029906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for resentenc-ing.', 'sentencing', 'Rodriguez v. State', 'https://www.courtlistener.com/opinion/2029906/', '2029906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude the district court properly overruled the pretrial motions to suppress the evidence, and we affirm the judgment and sentence of the district court.', 'suppression', 'State of Iowa v. Carrie McIver', 'https://www.courtlistener.com/opinion/2768587/', '2768587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and sentence of the district court.', 'sentencing', 'State of Iowa v. Carrie McIver', 'https://www.courtlistener.com/opinion/2768587/', '2768587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the undisputed facts concerning LaPointe''s knowledge at the time pursuit commenced, we conclude that La-Pointe reasonably believed that Morais had left the scene of an accident involving personal injury.', 'general', 'Morais v. Yee', 'https://www.courtlistener.com/opinion/1523231/', '1523231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and remand for further proceedings on the state law claims against LaPointe, Yee, and Tupper.', 'general', 'Morais v. Yee', 'https://www.courtlistener.com/opinion/1523231/', '1523231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Morais v. Yee', 'https://www.courtlistener.com/opinion/1523231/', '1523231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that plaintiffs have not demonstrated violations of Morais'' constitutional rights, we affirm summary judgment for the Town on the § 1983 claim.', 'general', 'Morais v. Yee', 'https://www.courtlistener.com/opinion/1523231/', '1523231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, although this case presents a close question, we conclude that the trial court did not abuse its discretion by admitting the testimony and videotape concerning defendant’s behavior in the holding cell.', 'general', 'State v. Synnott', 'https://www.courtlistener.com/opinion/1532386/', '1532386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the confinement in this case was criminally significant in and of itself and not merely incidental to defendant’s lewd and lascivious conduct.', 'general', 'State v. Synnott', 'https://www.courtlistener.com/opinion/1532386/', '1532386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to this case, we hold that the bus excise tax imposes an unconstitutional burden on interstate commerce.', 'general', 'Continental Trailways, Inc. v. Director, Division of Motor Vehicles', 'https://www.courtlistener.com/opinion/1538047/', '1538047') ON CONFLICT DO NOTHING;
