INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record, we conclude that the initial search of the residence was a true parole search and that the search was reasonable.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The statute does adequately advise the public of the proscribed conduct, namely possessing methamphetamine with the intent to manufacture methamphetamine, and we conclude that the statute is not unconstitutionally vague.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence permits the reasonable conclusion that two independent offenses were committed for which Micheau could be separately punished, we conclude that, under the circumstances, *1064 Count VI, the attempt charge, is not a lesser included offense of Count I, dealing in methamphetamine.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence presented at trial and the prosecutor''s closing argument, we conclude that the State distinguished and set forth independent evidence of Count I and Count VI.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Count II, possession of methamphetamine as a class D felony, is a lesser included offense of Count I, dealing in methamphetamine.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Micheau''s sentences for Count I and Count VI do not violate the Proportionality Clause.', 'sentencing', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only where the decision is clearly against the logic and effect of the facts and circumstances.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
