INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 251, we concluded that the trial court erred in requiring the defendant to provide raceneutral reasons for its peremptory strikes without there first being a finding of a prima facie case of discrimination.', 'general', 'Watts v. State', 'https://www.courtlistener.com/opinion/1621727/', '1621727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the circuit court failed to properly instruct the jury regarding the three sentencing options available in capital murder cases pursuant to Miss.', 'sentencing', 'Watts v. State', 'https://www.courtlistener.com/opinion/1621727/', '1621727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that the product rule has been accepted in the scientific community and found to be a reliable method of calculating population frequency data, we find that the trial court did not abuse its discretion by admitting the evidence.', 'general', 'Watts v. State', 'https://www.courtlistener.com/opinion/1621727/', '1621727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in the case sub judice, we find that a new trial is not warranted on the basis of the Batson issue since it was waived by the defendant.', 'general', 'Watts v. State', 'https://www.courtlistener.com/opinion/1621727/', '1621727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While there is no merit to most of the issues raised by Watts in his appeal, we find that despite his acquiescence to the Sentencing Instruction No.', 'sentencing', 'Watts v. State', 'https://www.courtlistener.com/opinion/1621727/', '1621727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998), we found that it was "proper" for an expert to present statistical evidence as to the frequency with which a DNA match might occur within the general population.', 'general', 'Watts v. State', 'https://www.courtlistener.com/opinion/1621727/', '1621727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), we found that "[w]here, as here, the delay is neither intentional nor egregiously protracted, and where there is a complete absence of actual prejudice, the balance is struck in favor of rejecting Rhymes'' speedy trial claim.', 'general', 'Watts v. State', 'https://www.courtlistener.com/opinion/1621727/', '1621727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the jury''s finding that Watts was guilty of capital murder and reverse and remand for re-sentencing proceedings, consistent with this opinion.', 'sentencing', 'Watts v. State', 'https://www.courtlistener.com/opinion/1621727/', '1621727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 217 (1996), cited by Appellant, we held that, although a contempt proceeding for a violation of a PFA Order is criminal in nature, double jeopardy does not bar a criminal
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the defendant’s indirect criminal contempt conviction for a violation of a PFA Order did not bar a subsequent prosecution for terroristic threats because the PFA Order did not include the elements of the substantive offense.', 'general', 'Commonwealth v. Majeed', 'https://www.courtlistener.com/opinion/2296264/', '2296264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the order of the Superior Court.', 'general', 'Commonwealth v. Majeed', 'https://www.courtlistener.com/opinion/2296264/', '2296264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1628124/', '1628124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that a defendant''s out-of-state incarceration on an unrelated offense does not toll the statute of limitations, nor does it suspend the statutory requirement that the capias, summons or other process issued on an indictment or information be executed without unreasonable delay.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1628124/', '1628124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reject the state''s claim that the statutes of limitation were tolled while Brown was incarcerated out of state on unrelated charges, we reverse.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1628124/', '1628124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand with instructions to discharge the defendant.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1628124/', '1628124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State proved Traylor to have knowingly and intelligently waived his rights.', 'general', 'Traylor v. State', 'https://www.courtlistener.com/opinion/2298115/', '2298115') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Pribil', 'https://www.courtlistener.com/opinion/1642966/', '1642966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that it is not error for a trial court to instruct the jury, over the defendant''s objection, on any lesser-included offenses supported by the evidence and the pleadings.', 'plea', 'State v. Pribil', 'https://www.courtlistener.com/opinion/1642966/', '1642966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 731 (1968), we find that Ms.', 'general', 'Donley v. City of Mountain Brook', 'https://www.courtlistener.com/opinion/1647136/', '1647136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that Superior Court Criminal Rule 11(c) required notification to the defendant at the time of the plea’s entry of the penal consequences of 21
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Slavens, this court held that a prior inconsistent statement given under oath to a deputy prosecuting attorney pursuant to a prosecutor’s subpoena was admissible as substantive evidence in accordance with Rule 801 (d) (1) (i).', 'general', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1651465/', '1651465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence was erroneously admitted, and accordingly, we reverse and remand for a new trial.', 'general', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1651465/', '1651465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 16-43-212(a), not by a prosecutor but instead by a police officer, and further considering that the testimony was not given at an “official proceeding” such that Weems was subject to the penalty of perjury, we conclude that the testimony was not given during a “proceeding” contemplated by Rule 801(d)(l)(i), and Slavens is not controlling.', 'general', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1651465/', '1651465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the statement was improperly admitted, and accordingly, we reverse and remand for a new trial.', 'general', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1651465/', '1651465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that while Fijo’s testimony that he called the pager to contact appellant was relevant to establish appellant’s identity, Fijo’s testimony regarding the purpose for calling appellant was not independently relevant to prove a material point related to the murder charge.', 'general', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1651465/', '1651465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the circuit court improperly admitted the testimony.', 'general', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1651465/', '1651465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s argument at trial challenging the applicability of Slavens preserved the point for appeal.', 'general', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1651465/', '1651465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In light of facts supporting respondent’s previous OFPs against appellant, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the record shows that appellant’s past abusive behavior has been directed at his children as well as respondent and that respondent was concerned for the children’s present safety, we conclude that the district court did not abuse its discretion by adding the parties’ children to the subsequent OFP.', 'general', 'Braend Ex Rel. Minor Children v. Braend', 'https://www.courtlistener.com/opinion/1652054/', '1652054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion by issuing the subsequent OFP for a fixed period of two years.', 'general', 'Braend Ex Rel. Minor Children v. Braend', 'https://www.courtlistener.com/opinion/1652054/', '1652054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no abuse of discretion, we affirm.', 'general', 'Braend Ex Rel. Minor Children v. Braend', 'https://www.courtlistener.com/opinion/1652054/', '1652054') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and (5) the district court did not abuse its discretion by adding the parties’ children to the OFP, we affirm.', 'general', 'Braend Ex Rel. Minor Children v. Braend', 'https://www.courtlistener.com/opinion/1652054/', '1652054') ON CONFLICT DO NOTHING;
