INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Cooper', 'https://www.courtlistener.com/opinion/2773096/', '2773096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm all the challenged rulings of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But in light of the totality of the evidence taken as a whole, we conclude that there was sufficient ''evidence to sustain a verdict based on a determination of constructive possession.', 'general', 'State v. Ashcraft', 'https://www.courtlistener.com/opinion/2773041/', '2773041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was and affirm on that basis.', 'general', 'State v. Ashcraft', 'https://www.courtlistener.com/opinion/2773041/', '2773041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on that basis.', 'general', 'State v. Ashcraft', 'https://www.courtlistener.com/opinion/2773041/', '2773041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '11 40 We affirm on the above grounds.', 'general', 'State v. Ashcraft', 'https://www.courtlistener.com/opinion/2773041/', '2773041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the CRA does encompass the instant facts as a matter of law, and that plaintiffs were denied public services because of their sex, we affirm.', 'general', 'Diamond v. Witherspoon', 'https://www.courtlistener.com/opinion/1657741/', '1657741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After studying the language of the CRA, we conclude that the facts of this case, as established, were sufficient to submit to the jury the question whether Wither-spoon’s actions amounted to sexual harassment.', 'general', 'Diamond v. Witherspoon', 'https://www.courtlistener.com/opinion/1657741/', '1657741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that plaintiffs’ claims do fall within the ambit of the CRA, and the trial court correctly denied defendant’s motion for summary disposition.', 'general', 'Diamond v. Witherspoon', 'https://www.courtlistener.com/opinion/1657741/', '1657741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s assertion that the jury instructions regarding the CRA were erroneous as a matter of law fails.', 'jury_instruction', 'Diamond v. Witherspoon', 'https://www.courtlistener.com/opinion/1657741/', '1657741') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the judgment of conviction.', 'general', 'State v. Herzog', 'https://www.courtlistener.com/opinion/2300040/', '2300040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As modified, we affirm the sentence.', 'sentencing', 'State v. Herzog', 'https://www.courtlistener.com/opinion/2300040/', '2300040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we hold that his mere status as a forest ranger, clothed as he might have been with law enforcement responsibilities in the abstract, does not make him, for purposes of the discovery rules, a "law enforcement officer, official, or employee.', 'general', 'Chisler v. State', 'https://www.courtlistener.com/opinion/1671014/', '1671014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that evidence of all four was admissible.', 'general', 'Chisler v. State', 'https://www.courtlistener.com/opinion/1671014/', '1671014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking into account the fact that the dispatcher was not instructed by the police department to make the call, she charged the call to her home telephone number, and she did not reveal the substance of the conversation until asked about it several days later, we held that her actions "were not connected to her employment by a law enforcement agency" but were the actions of a "private citizen.', 'general', 'Chisler v. State', 'https://www.courtlistener.com/opinion/1671014/', '1671014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that in order to determine whether the dispatcher "was acting as a law enforcement officer or as an agent to the police department, ''we must look to the circumstances surrounding the giving of the confession.', 'general', 'Chisler v. State', 'https://www.courtlistener.com/opinion/1671014/', '1671014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that much of the court''s charge was in error, outlining as it did the requirements for determiningconspiracy, rather than complicity liability, see Part IV, the error was not harmful to the defendant.', 'general', 'Chisler v. State', 'https://www.courtlistener.com/opinion/1671014/', '1671014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/1706019/', '1706019') ON CONFLICT DO NOTHING;
