INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any sanction other than disbarment would not provide the necessary protection for the public, serve as a deterrent to the legal profession, or preserve the public''s trust and confidence in the integrity of the disciplinary process for Delaware lawyers.', 'general', 'In Re Davis', 'https://www.courtlistener.com/opinion/2302531/', '2302531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, while we find that the Supreme Court may find Davis''s creation of a settlement services company and speaking at seminars to realtors and lenders to be beyond what a suspended real estate attorney should have done, we cannot recommend that the Court find that Davis knowingly violated the Suspension Order by engaging in these activities.', 'general', 'In Re Davis', 'https://www.courtlistener.com/opinion/2302531/', '2302531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ordered that Michael R.', 'general', 'In Re Davis', 'https://www.courtlistener.com/opinion/2302531/', '2302531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm both the findings of fact and conclusions of law reached by the Board on the basis of and for the reasons stated in its Violation Report.', 'general', 'In Re Davis', 'https://www.courtlistener.com/opinion/2302531/', '2302531') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, when we consider the negligible value of the erroneously admitted statements, together with the totality of the evidence, we hold that there is no reasonable possibility that the erroneously admitted statements contributed to Deparvine''s convictions.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this standard, we hold that the State has presented competent, substantial evidence that is consistent with Deparvine''s guilt and inconsistent with any reasonable hypothesis of innocence.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that there was sufficient evidence to support Deparvine''s murder convictions, and we affirm the jury''s verdicts of guilt.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Deparvine is procedurally barred from raising this issue on appeal.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hutchinson, this Court held that although it was error to introduce hearsay statements made over a telephone conversation as excited utterances, the error was harmless.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held the conversation was admissible, observing that "the statement was not infected with the vices which make such declarations usually inadmissible.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that although the statute cited in the indictment encompassed three separate child abuse offenses, "Any inquiry concerning the technical propriety of the indictment should have been raised prior to trial at which time any deficiency could have been cured.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that her "response was spontaneous, sprang from the stress, pain and excitement of the shootings and robberies, and was not the result of any premeditated design.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in that decision, this Court held that the statement was not admissible under the spontaneous statement exception because it did not describe an event.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that certain dicta in Hutchinson erroneously blurred the distinctions between the spontaneous statement and excited utterance exceptions to the rule barring admission of hearsay statements.', 'general', 'Deparvine v. State', 'https://www.courtlistener.com/opinion/1697763/', '1697763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the test conducted by Dr.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/1702154/', '1702154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the implied consent law does not absolutely forbid the admission into evidence of blood-alcohol test results and related testimony produced by an unlicensed expert, subject to two important provisos.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/1702154/', '1702154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Strong, we held that the failure to adhere to the implied consent law and its related regulations did not render blood-test results inadmissible where blood was drawn *791 for an exclusively medical purpose.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/1702154/', '1702154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In so holding, we concluded that this limited exception to the strict statutory language would not undermine the policies either of scientific accuracy or protecting the health of test subjects, since the person was working with authorization from HRS.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/1702154/', '1702154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the first certified question, we find that it must be answered in the negative.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/1702154/', '1702154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*792 Having reviewed the record of the proceedings below, we find that the trial court fully complied with the principles described above.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/1702154/', '1702154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Highway Patrol officers and troopers are “public officials” within the meaning of section 16-3-1040.', 'general', 'State v. Bridgers', 'https://www.courtlistener.com/opinion/1341327/', '1341327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '625 (1936), we held that while “the commission does not confer the office[,] .', 'general', 'State v. Bridgers', 'https://www.courtlistener.com/opinion/1341327/', '1341327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Highway Patrol officers and troopers come within this common law definition.', 'general', 'State v. Bridgers', 'https://www.courtlistener.com/opinion/1341327/', '1341327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals and reinstate the conviction and sentence of the trial court.', 'sentencing', 'State v. Bridgers', 'https://www.courtlistener.com/opinion/1341327/', '1341327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that convictions of both first-degree criminal sexual conduct and the underlying felony of armed robbery or kidnapping in a single trial are not barred by either constitution.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in Martin, supra, we held that convictions obtained in one trial of possession of heroin and delivery of the same heroin contravened the constitutional guarantee.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without reference to Blockburger or to legislative intent, we found that the prohibition against double jeopardy had been violated because "[p]ossession of the heroin present in this case was that necessary to its delivery".', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a matter of Michigan constitutional law, we found that multiple punishment under the statutes was impermissible because on the facts of the case before the Court the same facts proved all three crimes.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, in the case before the Court, proof of the charged predicate felony also served as proof of the compound felony of first-degree murder, we found that convictions of both crimes on the facts of the case violated the prohibition against double jeopardy.', 'general', 'People v. Robideau', 'https://www.courtlistener.com/opinion/1707680/', '1707680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Vega-Lara''s prior statements were not admissible as substantive evidence under Rule 801(d)(1)(A).', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore we hold that the district court did not abuse its discretion when it admitted, under Minn.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the extension of incarceration time for refusal to admit sexual offenses in sex-offender treatment rose to the level of compulsion for purposes of the Fifth Amendment.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that calling a witness who the prosecutor knows will claim a privilege can constitute prejudicial misconduct.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In other words, because the State directly suggested to the jury that they should infer the defendant''s guilt from Cozart''s refusal to implicate the defendant in the crime, we held that the defendant''s right to a fair trial was violated.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Johnson is not dispositive.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*751 Based on the analysis in these cases, we conclude that immunized testimony cannot be used to convict an individual under Minn.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that once Vega-Lara was granted use immunity, he did not have a valid Fifth Amendment privilege.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that in cases where the State calls a witness who *753 refuses to testify, the framework outlined in Mitchell should apply regardless of whether the refusal is based on a valid privilege.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, under the facts and circumstances of this case, we conclude that the State did not call Vega-Lara in bad faith.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/1889175/', '1889175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained in Ridley, because the dealing offense is a felony of the second degree and subject to greater punishment than the grand theft offense involved in this case, which is a third degree felony, we reverse the theft conviction and uphold the conviction *768 of dealing in stolen property (§ 812.', 'general', 'TSR v. State', 'https://www.courtlistener.com/opinion/1765678/', '1765678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the amended statute, as applied retroactively by the circuit court, did not violate the constitutional prohibition against
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'persuasive, we hold that admission of the evidence of a defendant’s refusal to submit to a breathalyzer test does not violate the defendant’s right against self incrimination as
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Absent such an express intention in the present case, coupled with our view that the change was procedural in nature, we conclude that retrospective application was appropriate.', 'general', 'Wyatt v. State', 'https://www.courtlistener.com/opinion/1889216/', '1889216') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that appellant’s reliance on
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 225, we held that we were without authority on appeal to reduce as excessive an imposed sentence which fell within the statutorily prescribed limits of punishment.', 'sentencing', 'Seeney v. State', 'https://www.courtlistener.com/opinion/2309795/', '2309795') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we can discern no compelling reason to withdraw from the jury the determination of materiality, we hold that the provision in N.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2310272/', '2310272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ingenito we held that the application of collateral estoppel to a defendant in a criminal case constituted an invasion of the factfinding function of the jury.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2310272/', '2310272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the critical issue when a defendant claimed a right to trial by jury is whether that right existed prior to 1776.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2310272/', '2310272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reexamined the rule ourselves, we conclude that the provision in N.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2310272/', '2310272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Returning to the circumstances before us, we conclude that Anderson''s conviction cannot stand.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2310272/', '2310272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we conclude that the court failed to make sufficient factual findings to justify its determination that J.', 'general', 'In Re JM', 'https://www.courtlistener.com/opinion/2310761/', '2310761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree that the family court did not satisfy its obligations under Rule 11, and we reverse the judgment of guilt.', 'general', 'In Re JM', 'https://www.courtlistener.com/opinion/2310761/', '2310761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in concluding that defendant''s inculpatory statement was admissible.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a defendant requests the trial court to instruct the jury that it may consider the mental condition of the defendant in deciding whether she formed a premeditated and deliberate specific intent to kill the victim, there must be sufficient evidence "reasonably to warrant inference of the fact at issue.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in refusing to charge the jury on murder in the second degree.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the sentencing court''s failure to find this mitigating factor was error.', 'sentencing', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the trial court had properly determined this *65 testimony admissible under Rule 704 of the North Carolina Rules of Evidence and that, as such, defendant was entitled to a jury instruction on this element of the crime.', 'jury_instruction', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, with regard to the conviction of conspiracy we conclude that the sentencing court''s erroneous failure to consider a statutory mitigating factor entitles defendant to a new sentencing hearing.', 'sentencing', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under this test, we conclude that the trial court in the case sub judice did not err in refusing to instruct the jury that it could consider evidence of defendant''s mental disorder as rendering her incapable of forming the specific intent to kill.', 'general', 'State v. Clark', 'https://www.courtlistener.com/opinion/1392859/', '1392859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no such constitutional violation because the Legislature contemplated and intended that multiple punishments might be imposed for stalking and for violating a protective order, and the two charges against Elliott were tried simultaneously.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/2272566/', '2272566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Elliott’s convictions.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/2272566/', '2272566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 89] We discern no defect in the charging instrument or in the jury instructions on either charge, and we affirm the judgments of conviction on both counts.', 'jury_instruction', 'State v. Elliott', 'https://www.courtlistener.com/opinion/2272566/', '2272566') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in the absence of some permanent deprivation of life, liberty, or property related to the collection of the tax, applicant suffered no "punishment" for the purposes of the Double Jeopardy Clause.', 'general', 'Ex Parte Chappell', 'https://www.courtlistener.com/opinion/1785250/', '1785250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'decided before the 1981 amendment, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court relied on pre-Code sentencing guidelines.', 'sentencing', 'State v. Hodge', 'https://www.courtlistener.com/opinion/2272756/', '2272756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that focus missing.', 'general', 'State v. Hodge', 'https://www.courtlistener.com/opinion/2272756/', '2272756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Paraphrasing our Supreme Court''s observation that `universal malice'' murder was not a lesser included offense of intentional murder, we conclude that homicide by vehicle `requires something more.', 'general', 'Jordan v. State', 'https://www.courtlistener.com/opinion/1785194/', '1785194') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we concluded that any finding of manifest injustice was clearly mistaken, we would remand to the trial court to perform the ministerial act of imposing the adjusted presumptive term.', 'general', 'Heathcock v. State', 'https://www.courtlistener.com/opinion/2604893/', '2604893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we concluded that the trial judge''s finding, that the adjusted presumptive term was manifestly too severe, was not clearly mistaken but that the panel''s decision that it was too lenient was clearly mistaken, we would so hold and remand to the three-judge panel to impose a sentence less than the presumptive term.', 'sentencing', 'Heathcock v. State', 'https://www.courtlistener.com/opinion/2604893/', '2604893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 555, 557 (1990), in which this court held that, pursuant to the sixth amendment to the United States Constitution, “an uneounseled conviction cannot be used collaterally to support an enhanced sentence where such enhanced sentence includes a term of imprisonment.', 'sentencing', 'State v. St. Clair', 'https://www.courtlistener.com/opinion/2598556/', '2598556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s judgment.', 'general', 'State v. St. Clair', 'https://www.courtlistener.com/opinion/2598556/', '2598556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we affirm the circuit court’s judgment of conviction and sentence.', 'sentencing', 'State v. St. Clair', 'https://www.courtlistener.com/opinion/2598556/', '2598556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these precedents, we hold that the government had to prove only that appellant intended to commit the acts which resulted in the injury (or the grave risk of injury) to the child, not that he had a specific intent to injure the child.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/2275532/', '2275532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that proof of the crime of second-degree cruelty to children is sufficient to convict a defendant of attempted second-degree cruelty to children.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/2275532/', '2275532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when there is sufficient evidence to support a conviction of cruelty to children, there is also sufficient evidence to support a conviction of attempted cruelty to children.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/2275532/', '2275532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Smith v. United States', 'https://www.courtlistener.com/opinion/2275532/', '2275532') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the evidence of this other victim was improperly admitted.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2275183/', '2275183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2275183/', '2275183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm a conviction if substantial evidence exists to support it.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2275183/', '2275183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the first issue we hold that Steffes made "false representations" to AT&amp;', 'general', 'State v. Matthew R. Steffes', 'https://www.courtlistener.com/opinion/904545/', '904545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the second question we hold that because AT&amp;', 'general', 'State v. Matthew R. Steffes', 'https://www.courtlistener.com/opinion/904545/', '904545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that providing fictitious business names and stolen personal identifying information to a phone company with the intent of setting up temporary phone numbers constitutes a "false representation.', 'general', 'State v. Matthew R. Steffes', 'https://www.courtlistener.com/opinion/904545/', '904545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having rejected Steffes''s view that the State was required to show that a member of the conspiracy promised to pay for the phone services, we hold that there was ample evidence that a "false representation" was made.', 'general', 'State v. Matthew R. Steffes', 'https://www.courtlistener.com/opinion/904545/', '904545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that 943.', 'general', 'State v. Matthew R. Steffes', 'https://www.courtlistener.com/opinion/904545/', '904545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on the plain language of the statute in conjunction with commonly used dictionaries, we conclude that Steffes stole electricity from AT&amp;', 'general', 'State v. Matthew R. Steffes', 'https://www.courtlistener.com/opinion/904545/', '904545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Only if the jury instructions, as a whole, misled the jury or communicated an incorrect statement of the law will we reverse and order a new trial.', 'jury_instruction', 'State v. Matthew R. Steffes', 'https://www.courtlistener.com/opinion/904545/', '904545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals.', 'general', 'State v. Matthew R. Steffes', 'https://www.courtlistener.com/opinion/904545/', '904545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), we hold that section 790.', 'general', 'LB v. State', 'https://www.courtlistener.com/opinion/1799501/', '1799501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the knife at issue here, we hold that petitioner''s knife plainly falls within the statutory exception to the definition of "weapon" found in section 790.', 'general', 'LB v. State', 'https://www.courtlistener.com/opinion/1799501/', '1799501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6]  In Brown, we held that the term "public housing facility" was unconstitutionally vague.', 'general', 'LB v. State', 'https://www.courtlistener.com/opinion/1799501/', '1799501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4] Accordingly, appellant''s conviction is vacated as we find that the knife in question was a "common pocketknife" under any intended definition of that term.', 'general', 'LB v. State', 'https://www.courtlistener.com/opinion/1799501/', '1799501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we reverse.', 'general', 'LB v. State', 'https://www.courtlistener.com/opinion/1799501/', '1799501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1657, and giving due deference to Officer Greene''s training and experience, we conclude that the totality of the circumstances established a reasonable suspicion that defendant was transporting illegal drugs and justified his further detention.', 'general', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 37 In balancing the justification for and circumstances of defendant''s detention against the degree to which his liberty was intruded upon, we conclude that Officer Greene did not act unreasonably by detaining defendant for one hour and forty minutes pending the arrival of a drug-detection dog.', 'general', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 44 We conclude that the record contains sufficient evidence from which reasonable persons could find that defendant knowingly transported marijuana.', 'general', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 47 For the foregoing reasons, we affirm defendant''s convictions and sentences.', 'sentencing', 'State v. Teagle', 'https://www.courtlistener.com/opinion/2600277/', '2600277') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the instant appeal.', 'general', 'Wickham v. State', 'https://www.courtlistener.com/opinion/2274873/', '2274873') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that King''s sentence is otherwise improper, we do not address the double jeopardy issue.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1809226/', '1809226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1141 For the reasons discussed above, we find that King was improperly sentenced as an habitual offender upon revocation of his probation.', 'sentencing', 'King v. State', 'https://www.courtlistener.com/opinion/1809226/', '1809226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, this court held: "A party indicted of one offence may be convicted of a lesser, provided it be of the same class with that which he is charged.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '712, 714 (1853), wherein this court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that under the third test in section 41-105(2)(c), now section 5-1-110(b)(3), negligent homicide was a lesser-included offense of manslaughter because the only difference between the two offenses was that negligent homicide required a lesser kind of culpable mental state than manslaughter.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the first of those cases, Martin, this court held that "the phrase `circumstances manifesting extreme indifference to the value of human life'' indicates that the attendant circumstances themselves must be such as to demonstrate the culpable mental state of the accused.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that second-degree murder was not a lesser-included offense of the type of first-degree murder charged in that case, because "the element of causing a death under circumstances manifesting extreme indifference to the value of human life is not an element of the charge for first-degree murder of a person aged fourteen years or younger.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court and affirm the court of appeals.', 'general', 'McCoy v. State', 'https://www.courtlistener.com/opinion/2278063/', '2278063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that the trial court and the appellate court erred in taking judicial notice of the general acceptance of the reliability of the HGN test as an indicator of alcohol impairment.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the disparate resolutions of the issue in foreign jurisdictions, the varying opinions expressed in articles on the subject, the fact that a Frye hearing has never been held on the matter in Illinois, and the fact that, as far as we are aware, the last Frye hearing held on this controversial methodology was held in Washington in 2000, we hold that a Frye hearing must be held to determine if the HGN test has been generally accepted as a reliable indicator of alcohol impairment.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” For this reason we hold that the admission of the HGN test results was not a harmless error.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State makes this argument in light of our ruling on the standard of review of Frye cases in In re Commitment of Simons, wherein we held that, in reviewing a trial court’s Frye analysis, we may consider not only the record, but also “sources outside the record, including legal and scientific articles, as well as court opinions from other jurisdictions.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court holds that HGN evidence requires a Frye foundation for admissibility.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the history of legal challenges to the admissibility of HGN test evidence, and the fact that a Frye hearing has never been held in Illinois on this matter, we conclude that the methodology of HGN testing is novel for purposes of Frye.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that HGN testing is a novel scientific methodology, we find that the trial and appellate courts did not err in determining that HGN testing must meet the Frye standard before defendant’s HGN test results were admitted as evidence.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we find that this issue cannot be resolved in Illinois on judicial notice alone.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the appellate court’s decision to reverse and remand, but held that the HGN issue had been waived by the defendant.', 'general', 'People v. McKown', 'https://www.courtlistener.com/opinion/2032679/', '2032679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" As in Harris, we conclude that the existence of three or more prior DUI convictions is an essential fact constituting the substantive offense of felony DUI.', 'general', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/1839251/', '1839251') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To protect the right to fair notice guaranteed by article I, sections 9 and 16 of the Florida Constitution, we conclude that the state must allege the specific prior DUI convictions in the charging document.', 'general', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/1839251/', '1839251') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if a defendant charged with felony DUI elects to be tried by jury,[6] the court shall conduct a jury trial on the elements of the single incident of DUI at issue without allowing the jury to learn of the alleged prior DUI offenses.', 'general', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/1839251/', '1839251') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the defendant in Myers benefitted from the illegal sentence in that the sentence imposed was more lenient than the sentence to which he was entitled, we held that he did not suffer "any fundamental unfairness from the illegal sentence, nor [were] his fundamental rights [ ] violated.', 'sentencing', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1850290/', '1850290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we find that the trial court committed plain error by sentencing Jefferson to a longer term of imprisonment than allowed by statute.', 'sentencing', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1850290/', '1850290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, on review of the entire record, we find that the trial court committed plain error by imposing a greater sentence than was authorized by the applicable statute.', 'sentencing', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1850290/', '1850290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even assuming, without deciding, that the trial judge in this case imposed an illegal sentence upon Jefferson by suspending part of his sentence and/or by sentencing Jefferson to house arrest, we find that such error by the trial court does not require reversal of Jefferson''s conviction or sentence.', 'sentencing', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1850290/', '1850290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although not raised by Jefferson in either his petition *1281 for post-conviction relief or in the appeal before this Court, we find that this error rises to the level of plain error.', 'general', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1850290/', '1850290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite Jefferson''s failure to raise this issue, we find that the imposition of a greater sentence than allowed by statute amounts to plain error.', 'sentencing', 'Jefferson v. State', 'https://www.courtlistener.com/opinion/1850290/', '1850290') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the impeachment of a witness by prior convictions is subject to the discretion of the trial court.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/2280249/', '2280249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Manning, supra, this Court held that a witness may be impeached by cross-examination concerning any prior convictions for crimes involving moral turpitude within 15 years.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/2280249/', '2280249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon reconsideration we conclude that Manning was decided incorrectly, and hold that the cross-examination of a witness concerning prior convictions is subject to the discretion of the trial court.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/2280249/', '2280249') ON CONFLICT DO NOTHING;
