INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we held that a defendant can not be convicted of multiple counts alleging possession of the same weapon unless the State proves, beyond a reasonable doubt, that the defendant''s possession of this weapon was not continuousin other words, that the defendant actually engaged in two discrete possessions.', 'general', 'Wiglesworth v. State', 'https://www.courtlistener.com/opinion/2631416/', '2631416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, *330 we held that Simmons could lawfully be convicted of only one countbecause "the jury was never required to consider or decide [this] issue":
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we conclude that the evidence was sufficient to support Wiglesworth''s burglary conviction, and we further conclude that, under Alaska law, Wiglesworth''s crime of burglary is a separately punishable offense, distinct from his drug offenses.', 'general', 'Wiglesworth v. State', 'https://www.courtlistener.com/opinion/2631416/', '2631416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we conclude that a person engaged in a single act of manufacturing methamphetamine is guilty of only one count of second-degree controlled substance misconduct, even though the defendant might, in the process, manufacture or possess two or more immediate precursor chemicals, or might possess two or more listed chemicals.', 'general', 'Wiglesworth v. State', 'https://www.courtlistener.com/opinion/2631416/', '2631416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that if the State believes that the facts of a particular case justify the entry of two or more separate convictions (under the rules stated in the preceding paragraph), the State must prove the facts supporting the separate convictions to the jury beyond a reasonable doubt.', 'general', 'Wiglesworth v. State', 'https://www.courtlistener.com/opinion/2631416/', '2631416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that the possession of two or more methamphetamine precursor chemicals and/or "listed" chemicals will support only one conviction for second-degree controlled substance misconduct if the defendant possesses these chemicals in connection with a single methamphetamine manufacturing operation
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] However, we conclude that this *327 text is important, because it illuminates the legislative purpose behind the statute.', 'general', 'Wiglesworth v. State', 'https://www.courtlistener.com/opinion/2631416/', '2631416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a defendant who violates two or more provisions of AS 11.', 'general', 'Wiglesworth v. State', 'https://www.courtlistener.com/opinion/2631416/', '2631416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[Citation omitted] Accordingly, we conclude that Simmons'' two convictions must merge.', 'general', 'Wiglesworth v. State', 'https://www.courtlistener.com/opinion/2631416/', '2631416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence presented at Wiglesworth''s trial supports his conviction for burglary, and we further conclude that Wiglesworth could properly be convicted separately of both this act of burglary and the controlled substance misconduct that was the ulterior motive for the burglary.', 'general', 'Wiglesworth v. State', 'https://www.courtlistener.com/opinion/2631416/', '2631416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[Bjased on our analysis of [the defendant''s rights to a unanimous verdict and to due process under article I of the Hawaii Constitution, we hold that unanimity is not required where alternative means of establishing an element of an offense are submitted to the jury, provided that there is no reasonable possibility that the jury’s verdict was based on an alternative unsupported by sufficient evidence.', 'general', 'State v. Kalaola', 'https://www.courtlistener.com/opinion/870424/', '870424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Jones, this court held that “[a] defendant’s rights are clearly prejudiced where the jury is instructed that it may find him guilty based upon a theory of guilt that is not supported by sufficient evidence as a matter of law.', 'general', 'State v. Kalaola', 'https://www.courtlistener.com/opinion/870424/', '870424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 323, we held that the factual
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the factual basis does not satisfy
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained, we reverse the judgment of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the facts alleged in the complaint, Florida law does not permit the maintenance of shareholders'' derivative suit on behalf of Lum''s.', 'general', 'Schein v. Chasen', 'https://www.courtlistener.com/opinion/1905182/', '1905182') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the rationale of Judge Kaufman in his dissent and the opinion of the United States District Court comport with Florida law and we would approve Judge Kaufman''s reasoning as dispositive of the issues presented sub judice which we answer in the negative.', 'general', 'Schein v. Chasen', 'https://www.courtlistener.com/opinion/1905182/', '1905182') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Harvey, we held that information indicating that the defendant had ordered and received child pornography on thirteen occasions during the fifteen months preceding the issuance of the warrant was not stale.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1908680/', '1908680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no error by the Superior Court, we affirm.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1908680/', '1908680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State cannot use Buchanan’s violation of a Family Court order as a predicate offense to establish Burglary.', 'general', 'Buchanan v. State', 'https://www.courtlistener.com/opinion/1913400/', '1913400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we REVERSE in part and AFFIRM in part.', 'general', 'Buchanan v. State', 'https://www.courtlistener.com/opinion/1913400/', '1913400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we REVERSE the Third Degree Burglary conviction.', 'general', 'Buchanan v. State', 'https://www.courtlistener.com/opinion/1913400/', '1913400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we REVERSE in part and AFFIRM in part the judgment of the Superior Court.', 'general', 'Buchanan v. State', 'https://www.courtlistener.com/opinion/1913400/', '1913400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] We affirm appellant''s convictions and death sentence.', 'sentencing', 'Commonwealth v. Wright', 'https://www.courtlistener.com/opinion/1915693/', '1915693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the verdict and sentence of death.', 'sentencing', 'Commonwealth v. Wright', 'https://www.courtlistener.com/opinion/1915693/', '1915693') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To assure *904 that this be so, we hold that Article 3, Section 26 of the Mississippi Constitution requires a transactional immunity grant.', 'general', 'Wright v. McAdory', 'https://www.courtlistener.com/opinion/1932060/', '1932060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that, although in other contexts, the word "fuck" had to carry a sexual context in order to be obscene, in the circumstances of the case before the court, where Pringle had called the police officers "goddamn fucking pigs", he had used "obscene" language within the context of section 5503(a)(3), without need for resort to the sexual content of the words.', 'general', 'Commonwealth v. Fenton', 'https://www.courtlistener.com/opinion/1926797/', '1926797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Commonwealth v. Fenton', 'https://www.courtlistener.com/opinion/1926797/', '1926797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we find that the trial court did not abuse its discretion by ordering counseling as a condition of probation.', 'general', 'State v. Peck', 'https://www.courtlistener.com/opinion/1932088/', '1932088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that the probation condition was never modified because the probation officer acted only pursuant to the original probation condition.', 'general', 'State v. Peck', 'https://www.courtlistener.com/opinion/1932088/', '1932088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Peck', 'https://www.courtlistener.com/opinion/1932088/', '1932088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since enforcement of the statute under present Arizona law is impossible, we hold that A.', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1257944/', '1257944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that petitioner has presented a colorable claim, and is entitled to an evidentiary hearing on the recantation issue.', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1257944/', '1257944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we hold that the affidavits which have been submitted raise a colorable claim sufficient to entitle petitioner to an evidentiary hearing.', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1257944/', '1257944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that all of the procedures mandated in potential death penalty cases were followed.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1344406/', '1344406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the sentence imposed in the instant case is not disproportionate to the sentence imposed in those cases reviewed in Creech where the death sentence was available as a form of punishment.', 'sentencing', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1344406/', '1344406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1344406/', '1344406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] For the reasons that follow, we conclude that the State presented legally sufficient evidence of first-degree felony murder based on kidnapping with intent to inflict bodily harm, and therefore affirm the murder conviction and the sentence of death.', 'sentencing', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these considerations, we conclude that the trial court did not commit fundamental error in instructing the jury on "intent to inflict bodily harm" as an alternative to "intent to commit homicide" in defining the underlying felony of kidnapping.', 'general', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the totality of these circumstances constitutes substantial, competent evidence from which the jury could reasonably have excluded all inferences other than that Amanda is dead and that Crain killed her.', 'general', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is sufficient to establish first-degree felony murder based on kidnapping with the intent to inflict bodily harm.', 'general', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this evidence, we conclude that the State presented legally sufficient evidence of a kidnapping with the intent to inflict bodily harm.', 'general', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Combined with the disparate height and weight, we conclude that the evidence that a struggle occurred between Amanda and Crain which resulted in both parties'' blood loss and numerous scratches and gouges to Crain''s arms is a compelling indication of Crain''s intent to inflict bodily harm on Amanda.', 'general', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that competent, substantial evidence does not exist to support the jury verdict of kidnapping with intent to commit homicide.', 'general', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming without deciding that Crain is correct in light of this Court''s reduction of the separate kidnapping conviction to false imprisonment, we conclude that any error in finding the "murder in the course of a felony" aggravator is harmless beyond a reasonable doubt.', 'general', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that any error in finding the aggravator of murder in the course of a felony does not affect our proportionality review based on the weight of the two remaining valid aggravators under the circumstances of this case.', 'general', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the strength of the aggravating factors, the relatively weak mitigation, and our affirmance of death sentences in comparable cases, we conclude that the death penalty is a proportional punishment.', 'sentencing', 'Crain v. State', 'https://www.courtlistener.com/opinion/1940000/', '1940000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" This Court held in Idaho State Bar v.', 'general', 'In Re Dodge', 'https://www.courtlistener.com/opinion/2626354/', '2626354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the hearing committee with respect to Dodge''s violation of I.', 'general', 'In Re Dodge', 'https://www.courtlistener.com/opinion/2626354/', '2626354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that Adamcik is not precluded by the invited error doctrine from raising this issue on appeal, as he did not encourage the district court to offer the specific malice instructions given, but merely failed to object.', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err in instructing the jury regarding malice, and the State’s burden of proof was not lowered through such instruction.', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that: (1) the jury was provided with sufficient evidence from which it could reasonably find beyond a reasonable doubt that Adameik was guilty of murder in the first degree;', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we held that Ayres “was fully advised of the acts he was charged to have committed, and he is presumed to know that he would be a principal and guilty as such whether he directly committed the acts charged or aided and abetted in their commission by another.', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this Court held that under I.', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Over six decades ago this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[although the evidence at trial showed that Severson could have murdered his wife by either overdosing her or suffocating her, it did not indicate that separate incidents involving distinct unions of mens rea and actus reas occurred.', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming the veracity of Shannon and Sean’s affidavits, we find that the district court had substantial and competent evidence to support its finding that the conduct the detectives engaged in was not such that it would overbear Shannon and Sean’s ability to voluntarily agree to waive Adam-cik’s right to counsel.', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 could have been better worded so as to clarify that the State need not demonstrate that Adamcik inflicted the fatal blow, we find that J.', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the prosecutors’ appeal to the jurors’ sympathy for Stod-dart’s family was harmless and, thus, did not constitute fundamental error.', 'general', 'State v. Adamcik', 'https://www.courtlistener.com/opinion/874752/', '874752') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 161.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Gove had waived his constitu
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, did the court of appeals err as a matter of law in holding that Petty was judicially estopped from challenging his state conviction? We conclude that Petty did not maintain inconsistent positions during the course of the state and federal litigation, and there is not sufficient evidence in the record to demonstrate that he attempted to "coldly manipulate" the judicial process.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Petty is judicially estopped from challenging his state conviction.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the appellate court erred as a matter of law.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that because the federal prosecution against Petty occurred after he was convicted in state court, the bar to a state prosecution contained in § 161.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this date was prior to the prosecution of Petty in federal court, we conclude that Wis.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the conviction in state court preceded the federal prosecution, we need not reach the issue of whether the two prosecutions were for the "same act.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence does not support the State''s contention that the adjournments were sought by the defendant so as to frustrate the court''s jurisdiction in the pending state criminal proceeding.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the court of appeals has mistakenly expanded the breadth of the legal elements required to invoke the doctrine of judicial estoppel by applying it to the facts of the present case.', 'general', 'State v. Petty', 'https://www.courtlistener.com/opinion/1952131/', '1952131') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the probation condition was so broad that compliance was beyond the defendant’s control, and thus the condition was invalid.', 'general', 'State v. Whitchurch', 'https://www.courtlistener.com/opinion/1958718/', '1958718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Whitchurch', 'https://www.courtlistener.com/opinion/1958718/', '1958718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judge implicitly resolved the credibility issues in favor of plaintiff and therefore found that defendant''s request for permission to visit her children was denied.', 'general', 'Kamen v. Egan', 'https://www.courtlistener.com/opinion/2342347/', '2342347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the judge erred in his legal conclusion that this single act of trespass, unaccompanied by violence or a threat of violence was sufficient to justify the issuance of a restraining order under the Act.', 'general', 'Kamen v. Egan', 'https://www.courtlistener.com/opinion/2342347/', '2342347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances we conclude that the acts complained of were nothing more than an ordinary domestic contretemps which the Act was never intended to address.', 'general', 'Kamen v. Egan', 'https://www.courtlistener.com/opinion/2342347/', '2342347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Kamen v. Egan', 'https://www.courtlistener.com/opinion/2342347/', '2342347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, however, we need not reach the question of whether Detective Patterson’s statement was false or reckless because we hold that the affidavit was sufficient to support a finding of probable cause even if the statements that were the subject of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that all of these facts, taken together, were sufficient to enable a reasonable and prudent officer to believe that appellant was guilty of murdering Darcie Silver, without even considering the statement about the similarity of the footprint and the marks on the toilet seat.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/1962940/', '1962940') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statute is constitutional, and we accordingly
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that § 1 does not violate Const 1963, art 3, § 2, because it does not offend the doctrine of separation of powers.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that § 1 does not unconstitutionally infringe on the Supreme Court’s rulemaking authority and that where § 1 and MCR 6.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '513 NW2d 152 (1994), this Court held that this provision did not give prosecutors judicial power.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendants did not meet this heavy burden of overcoming the presumption of constitutionality, and the lower courts therefore erred in finding that § 1 violated the constitutional guarantees of equal protection.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, because the entire juvenile justice system is a legislatively created system, the mere fact that legislatively mandated procedures are legislatively altered does not necessarily result in a violation of the right to due process.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because juveniles have no constitutional right to be treated differently from adults when they engage in criminal conduct, and because without the legislatively created juvenile justice system all juveniles at least fourteen years of age would be subject to adult criminal penalties, we conclude that the amended automatic waiver system does not deny juveniles the constitutional right to due process.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, although MCR 6.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court rules contained in MCR subchapter 6.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the constitutional questions presented are ripe for review and that the lower courts erred in holding that § 1 was unconstitutional.', 'general', 'People v. Conat', 'https://www.courtlistener.com/opinion/1965356/', '1965356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the state failed to articulate a persuasive reason for dispensing with the usual individualized suspicion requirement when it used temporary roadblocks to stop vehicles for the purpose of apprehending alcohol-impaired drivers, and therefore the stop violated Minn.', 'general', 'State v. Larsen', 'https://www.courtlistener.com/opinion/1966709/', '1966709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the state was not able to show that complying with the rule requiring individualized suspicion was impractical, for example, or that departing from it would significantly increase the effectiveness of law enforcement.', 'general', 'State v. Larsen', 'https://www.courtlistener.com/opinion/1966709/', '1966709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the roadblocks violated Minn.', 'general', 'State v. Larsen', 'https://www.courtlistener.com/opinion/1966709/', '1966709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is not.', 'general', 'State v. Larsen', 'https://www.courtlistener.com/opinion/1966709/', '1966709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We conclude that angling from a fish house is not a closely regulated industry fitting within the exception to the need for constitutional authorization for a search as set forth in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Larsen', 'https://www.courtlistener.com/opinion/1966709/', '1966709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In White, this court held that, although it is a statutory aggravating factor, the victim’s age cannot form the basis for an extended-term sentence where the defendant is convicted of aggravated battery of a child.', 'sentencing', 'People v. Phelps', 'https://www.courtlistener.com/opinion/2085558/', '2085558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that he must.', 'general', 'People v. Phelps', 'https://www.courtlistener.com/opinion/2085558/', '2085558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the present case, we conclude that defendant’s consecutive sentences do not constitute a double enhancement.', 'sentencing', 'People v. Phelps', 'https://www.courtlistener.com/opinion/2085558/', '2085558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse that portion of the appellate court’s opinion modifying defendant’s sentences to run concurrently.', 'sentencing', 'People v. Phelps', 'https://www.courtlistener.com/opinion/2085558/', '2085558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse that portion of the appellate court’s judgment modifying defendant’s sentences to run concurrently.', 'sentencing', 'People v. Phelps', 'https://www.courtlistener.com/opinion/2085558/', '2085558') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As in Singletary, we conclude that it cannot be said beyond a reasonable doubt that the appellant at bar would have been convicted without the taint of the impermissible remarks made to the jury.', 'general', 'Redish v. State', 'https://www.courtlistener.com/opinion/1775361/', '1775361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that none of these contentions are cause for reversal.', 'general', 'Redish v. State', 'https://www.courtlistener.com/opinion/1775361/', '1775361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm all issues raised,[1] with the *929 exception of that pertaining to the issue of prosecutorial misconduct, which we agree requires reversal and remand of the case for new trial.', 'general', 'Redish v. State', 'https://www.courtlistener.com/opinion/1775361/', '1775361') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result of an inmate''s substantial dependency and the extraordinary control jailers wield over their prisoners, we hold that inmates are not precluded from recovering damages from a sheriff for injuries suffered by intentional wrongful acts of jail employees.', 'general', 'Robins v. Harris', 'https://www.courtlistener.com/opinion/1977716/', '1977716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that Sheriff Harris is liable for the assault committed by Soules against Robins and that the Commissioners are not liable for Robins''s alleged injuries.', 'general', 'Robins v. Harris', 'https://www.courtlistener.com/opinion/1977716/', '1977716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994) ("We conclude that Weatherholt''s claim actually concerns the manner in which the county jail was administered, a matter which we have determined falls solely within the province of the sheriff.', 'general', 'Robins v. Harris', 'https://www.courtlistener.com/opinion/1977716/', '1977716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the summary judgment in favor of Sheriff Harris and direct the entry of partial summary judgment in favor of Robins.', 'general', 'Robins v. Harris', 'https://www.courtlistener.com/opinion/1977716/', '1977716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature intended that the term “debt counselor” refer to a person working on behalf of a debtor in performing the activity described in I.', 'general', 'State v. Beard', 'https://www.courtlistener.com/opinion/2623331/', '2623331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm in part, vacate in part, and reverse in part.', 'general', 'State v. Beard', 'https://www.courtlistener.com/opinion/2623331/', '2623331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find in those regulations both unworkable standards and an unacceptable delegation of authority to an ill-defined category of presumed experts, we conclude that the Department failed, in part, to carry out its mandate.', 'general', 'New Jersey Society for the Prevention of Cruelty to Animals v. New Jersey Department of Agriculture', 'https://www.courtlistener.com/opinion/1977935/', '1977935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore conclude that some, but not all, of the regulations are invalid and we reverse only those aspects of the Appellate Division’s judgment that concluded otherwise.', 'general', 'New Jersey Society for the Prevention of Cruelty to Animals v. New Jersey Department of Agriculture', 'https://www.courtlistener.com/opinion/1977935/', '1977935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such action constitutes the unauthorized practice of law.', 'general', 'In Re Richland County Magistrate''s Court', 'https://www.courtlistener.com/opinion/2109732/', '2109732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 491 ("Therefore, in light of the legislature''s extension of law enforcement authority to licensed security officers, we hold that licensed security officers may prosecute misdemeanor cases in magistrate''s or municipal court.', 'general', 'In Re Richland County Magistrate''s Court', 'https://www.courtlistener.com/opinion/2109732/', '2109732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that allowing prosecution decisions to be made by, or even influenced by, private interests would do irreparable harm to our criminal justice system.', 'general', 'In Re Richland County Magistrate''s Court', 'https://www.courtlistener.com/opinion/2109732/', '2109732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Marr, we held that the State failed to offer sufficient evidence to support kidnapping under the Rich tripartite test.', 'general', 'State of Iowa v. Scott Robert Robinson', 'https://www.courtlistener.com/opinion/2777515/', '2777515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 40, we held that the relatively short movement of a victim into a bedroom for’ purposes of seclusion is a factor that may be considered in determining whether a defendant may be convicted of kidnapping during the course of committing another felony.', 'general', 'State of Iowa v. Scott Robert Robinson', 'https://www.courtlistener.com/opinion/2777515/', '2777515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'State of Iowa v. Scott Robert Robinson', 'https://www.courtlistener.com/opinion/2777515/', '2777515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this heinous concept underlies the Rich tripartite test with its attendant intensifiers.', 'general', 'State of Iowa v. Scott Robert Robinson', 'https://www.courtlistener.com/opinion/2777515/', '2777515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'McGrew, however, also involved the binding of the hands and the detention of the victim for a four-hour period, and *480thus under the totality of circumstances, we concluded that there was a substantial increase in the risk of harm.', 'general', 'State of Iowa v. Scott Robert Robinson', 'https://www.courtlistener.com/opinion/2777515/', '2777515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we concluded that the State offered sufficient evidence to support a kidnapping conviction even under the incidental approach, we did not expressly decide the issue in that case.', 'general', 'State of Iowa v. Scott Robert Robinson', 'https://www.courtlistener.com/opinion/2777515/', '2777515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude the evidence was insufficient to support the conviction, we reverse the conviction.', 'general', 'State of Iowa v. Scott Robert Robinson', 'https://www.courtlistener.com/opinion/2777515/', '2777515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, the State generally argues that before we reverse a criminal conviction on grounds of lack of barrier-free contact with counsel, the defendant must show that he or she has been prejudiced by the denial of his or her right to counsel.', 'general', 'State of Iowa v. Scott Robert Robinson', 'https://www.courtlistener.com/opinion/2777515/', '2777515') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Watson we concluded that “where the trial court knew or should have known of a particular conflict, reversal is required without a showing that the conflict adversely affected counsel’s performance, even though no objection was made at trial.', 'general', 'State of Iowa v. Robert Lynn Vaughan', 'https://www.courtlistener.com/opinion/2777516/', '2777516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not decide whether an actual conflict existed before that time because we find that the appointment of conflict-free counsel nearly four months before trial under the circumstances, of this case remedied any potential conflict, actual or otherwise.', 'general', 'State of Iowa v. Robert Lynn Vaughan', 'https://www.courtlistener.com/opinion/2777516/', '2777516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we affirm the district court’s judgment of conviction and sentence.', 'sentencing', 'State of Iowa v. Robert Lynn Vaughan', 'https://www.courtlistener.com/opinion/2777516/', '2777516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Vaughan’s conviction for first-degree arson.', 'general', 'State of Iowa v. Robert Lynn Vaughan', 'https://www.courtlistener.com/opinion/2777516/', '2777516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Gentile', 'https://www.courtlistener.com/opinion/2135798/', '2135798') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this setting we conclude that the right of confrontation is paramount to the State’s policy of protecting a juvenile offender.', 'general', 'State v. Mills', 'https://www.courtlistener.com/opinion/2320012/', '2320012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Mills', 'https://www.courtlistener.com/opinion/2320012/', '2320012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because these analogies have not historically been regarded as punishment, we conclude that historical precedent does not demonstrate an objective punitive purpose.', 'general', 'Kellar v. Fayetteville Police Department', 'https://www.courtlistener.com/opinion/2192392/', '2192392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the law is not excessive in relation to its stated non-punitive purposes.', 'general', 'Kellar v. Fayetteville Police Department', 'https://www.courtlistener.com/opinion/2192392/', '2192392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not interpret this discussion as indicating that petitioner was abandoning his First Amendment claim if the Kentucky Court of Appeals did not agree with his statutory interpretation argument, and we hold that the constitutional question in Branzburg v.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, we held that the Secretary of State''s denial of a passport for travel to Cuba did not violate a citizen''s First Amendment rights.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The rule was justified by the "weightiest considerations of national security" and we concluded that the "right to speak and publish does not carry with it the unrestrained right to gather information.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Alabama, supra, we found that compelled disclosure of the names of those in Alabama who belonged to the NAACP "is likely to affect adversely the ability [of the NAACP] and its members to pursue their .', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Massachusetts Supreme Judicial Court and hold that petitioner must appear before the grand jury to answer the questions put to him, subject, of course, to the supervision of the presiding judge as to "the propriety, purposes, and scope of the grand jury inquiry and the pertinence of the probable testimony.', 'general', 'Branzburg v. Hayes', 'https://www.courtlistener.com/opinion/108611/', '108611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, because the State did not present evidence establishing a basis for refusing to return the property, we reverse the order of the district court.', 'general', 'State v. Agee', 'https://www.courtlistener.com/opinion/2220527/', '2220527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons set forth below, we hold that section 111 is not implicated where, as here, the conduct in question could not have "constitute[d] a sexual offense" under the referenced part of the Utah code because the activity involved non-Utahns outside of Utah, and thus could not have sustained a criminal charge under Title 76, Chapter 5, Part 4.', 'general', 'Nevares v. M.L.S.', 'https://www.courtlistener.com/opinion/2777751/', '2777751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And because Nevares''s parental rights would have remained intact under Colorado law unless and until he was given notice and an opportunity to be heard, we conclude that his parental rights are likewise preserved under Utah law.', 'general', 'Nevares v. M.L.S.', 'https://www.courtlistener.com/opinion/2777751/', '2777751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '{16 For these reasons we conclude that section cannot stand as a bar to the paternity petition on respondents'' motion for summary judgment.', 'general', 'Nevares v. M.L.S.', 'https://www.courtlistener.com/opinion/2777751/', '2777751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Nevares v. M.L.S.', 'https://www.courtlistener.com/opinion/2777751/', '2777751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '47 For the above reasons we reverse the decision dismissing Nevares''s paternity petition on summary judgment.', 'dismissal', 'Nevares v. M.L.S.', 'https://www.courtlistener.com/opinion/2777751/', '2777751') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶26 Last term, in Dubose, when this court held that evidence obtained from an out-of-court showup will not be admissible unless the procedure was "necessary," it based its decision on the due process clause in the Wisconsin Constitution.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court still has a limited gate-keeping function to exclude such evidence under Wis.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] Accordingly, we reverse the court of appeals and remand to the circuit court for a determination of whether evidence of the identification of Hibl should be excluded under § 904.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals and remand for the circuit court to make a determination of whether Stuller''s identification of Hibl should be excluded pursuant to § 904.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and remand to the circuit court for a determination of whether the identification evidence in this case should be excluded under § 904.', 'general', 'State v. Hibl', 'https://www.courtlistener.com/opinion/2233354/', '2233354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wilson, this court held that, once a defendant is warned of his rights, he is free to exercise his own decision of whether to make a second statement.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing considerations, we find that any failure to contact Jon''s parents or a juvenile officer prior to questioning Jon did not render his statements involuntary.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we find that the totality of circumstances indicates that Jon''s confession was the result of his own decision and was not the result of compulsion or inducement, nor was Jon''s will being overborne at the time of his confession.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not address whether the appellate court properly found that Harberts'' question was interrogation and that Jon was in custody because we find that, even if the trial court erroneously denied Jon''s motion to suppress his initial statement to Harberts, any error was, at most, harmless.', 'suppression', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As those statements, which repeated and in fact enlarged upon Jon''s initial response to Harberts, were admissible, we find that any purported error in admitting Jon''s initial statement to Harberts was harmless.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, this case is distinguishable from our decision in Clark, where we found that there was "not one scintilla of evidence in the record of the transfer proceeding that would have apprised anyone that the transfer could result in a term of natural life imprisonment.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we found that a juvenile''s confession was voluntary even though he was not provided with an opportunity to confer with a concerned adult because: the juvenile never requested to speak with a concerned adult;', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the holdings in Williams and Kidd to be erroneous, however, we reverse the appellate court''s finding that the trial court should have followed the precedent set forth in those cases and should have given second degree murder instructions on the felony-murder counts.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the appellate court''s finding that a second degree murder instruction should have been given on the charges of felony murder, and affirm the trial court''s order declining to give that instruction.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse the appellate court''s finding that it was prejudicial error to exclude the evidence set forth in Jon''s offers of proof, and affirm the trial court''s ruling excluding the evidence.', 'general', 'People v. Morgan', 'https://www.courtlistener.com/opinion/2234512/', '2234512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶38         We hold that petition forgery under A.', 'general', 'Moreno v. Jones', 'https://www.courtlistener.com/opinion/867406/', '867406') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse the trial court’s judgment in favor of Moreno and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[24]  In Shotwell, this Court held that the habitual offender act was applicable to a felony conviction for prison escape, even though the escape statute, at that time, provided for a maximum three-year sentence to be added to the original sentence.', 'sentencing', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[4] We conclude that the Legislature intended, as indicated by the plain meaning of the habitual offender act, that it be applicable to third and subsequent OUIL convictions.', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of our earlier analysis, and after considering again the purpose and wording of both the OUIL provisions and the habitual offender act, we conclude that the "double enhancement" of which defendant complains was intended by the Legislature.', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statutes in question do not conflict;', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Legislature intended that the sentence for an OUIL-3 felony, if it is a first felony conviction, shall be as provided in the Motor Vehicle Code: imprisonment for not less than one or more than five years, and a fine of not less than $500 or more than $5,000, or both.', 'sentencing', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part[32] and reverse in part the decision of the Court of Appeals in People v Bewersdorf.', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In People v Johnson, we affirm the decision of the Court of Appeals and remand the *75 case to the circuit court for proceedings consistent with this opinion.', 'general', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[32]  Because defendant Bewersdorf was adequately advised by the trial court of his right to have witnesses against him appear at trial, we affirm the panel''s ruling that defendant was not entitled to withdraw his plea.', 'plea', 'People v. Bewersdorf', 'https://www.courtlistener.com/opinion/1992276/', '1992276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Legislature did not intend the harboring and concealing statute to encompass all aspects of aiding an escape.', 'general', 'People v. Thomas', 'https://www.courtlistener.com/opinion/1992571/', '1992571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defendant''s alleged conduct exceeds the strictures of MCL 752.', 'general', 'People v. Thomas', 'https://www.courtlistener.com/opinion/1992571/', '1992571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the Court of Appeals.', 'general', 'People v. Thomas', 'https://www.courtlistener.com/opinion/1992571/', '1992571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" For these reasons, we affirm the judgment of the Court of Appeals.', 'general', 'People v. Thomas', 'https://www.courtlistener.com/opinion/1992571/', '1992571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed below, we conclude that an order of restitution under § 43-286(l)(a) should serve the rehabilitative purposes of the Nebraska Juvenile Code, and we further conclude that the juvenile court erred when it failed to consider appellants’ financial ability to pay restitution in the amount ordered.', 'general', 'In Re Interest of Laurance S.', 'https://www.courtlistener.com/opinion/1993883/', '1993883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that juvenile courts should have discretion to set the amount of restitution based on the record presented and the juvenile’s ability to pay and that the amount ordered be consistent with the purposes of the Nebraska Juvenile Code.', 'general', 'In Re Interest of Laurance S.', 'https://www.courtlistener.com/opinion/1993883/', '1993883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the restitution orders entered under § 43-286(l)(a) in delinquency proceedings must be supported by the record and that the amount ordered must be consistent with the educational, treatment, and rehabilitative purposes of the Nebraska Juvenile Code and the juvenile’s ability to pay.', 'general', 'In Re Interest of Laurance S.', 'https://www.courtlistener.com/opinion/1993883/', '1993883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the orders in part and remand the causes for further proceedings consistent with this opinion.', 'general', 'In Re Interest of Laurance S.', 'https://www.courtlistener.com/opinion/1993883/', '1993883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The juvenile court erred in entering the restitution portions of its dispositional orders, and we reverse those portions of the juvenile court’s dispositional orders relating to restitution entered in these juvenile proceedings and remand the causes for further proceedings consistent with this opinion.', 'general', 'In Re Interest of Laurance S.', 'https://www.courtlistener.com/opinion/1993883/', '1993883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'out of the air,’ ” and we reversed the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the portion of each dispositional order that ordered each appellant to pay $29,059.', 'general', 'In Re Interest of Laurance S.', 'https://www.courtlistener.com/opinion/1993883/', '1993883') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the circuit court erred in sentencing and that consecutive sentences were required.', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kilpatrick, this court held that this action resulted in an impermissible increase in sentencing because section 5-8-1(c) of the Unified Code of Corrections (730 ILCS 5/5-8-1(c) (West 1992)) prohibited the circuit court from increasing a sentence after it was imposed.', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Arna, we found that an order imposing concurrent terms of imprisonment is void when consecutive terms of imprisonment are required by section 5-8-4(a).', 'general', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the appellate court''s finding that the convictions and sentences for conspiracy imposed on Garcia (count 41), Wallace (count 41), and O''Neal (count 41) should be vacated.', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the appellate court''s finding that Garcia''s sentence for aggravated criminal sexual assault based on count 2 should be vacated.', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the appellate court''s finding that Wallace''s conviction and sentence for armed violence should be vacated (count 44).', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the appellate court''s finding that Wallace''s convictions and sentences for aggravated criminal sexual assault based on the penetration of S.', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the appellate court''s finding that Wallace''s convictions and corresponding sentences for aggravated criminal sexual assault premised on armed robbery should be vacated (counts 33 through 40).', 'sentencing', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given Wallace''s and the State''s concurrence, and the fact that neither party addresses this point on the merits, we affirm the appellate court''s finding as to Wallace.', 'general', 'People v. Garcia', 'https://www.courtlistener.com/opinion/2023800/', '2023800') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More particularly, we held that due process forbids the trial court "`to convert a hearing on a complaint alleging one act of domestic violence into a hearing on other acts of domestic violence which are not even alleged in the complaint.', 'general', 'Jd v. Mdf', 'https://www.courtlistener.com/opinion/2322902/', '2322902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence, although sufficient to convict for the misdemeanor of maliciously destroying property,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm appellant’s conviction for malicious destruction of property.', 'general', 'Shelton v. United States', 'https://www.courtlistener.com/opinion/2323163/', '2323163') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that none of these factors applies here.', 'general', 'Dobyns v. United States', 'https://www.courtlistener.com/opinion/2323278/', '2323278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that Dobyns could not have been convicted in the District of Columbia of larceny and larceny after trust under the previous law because all of the elements of these offenses occurred outside the District of Columbia, we are satisfied, for the reason stated in the text, that Dobyns’s conduct violated the theft statute, § 22-3211.', 'general', 'Dobyns v. United States', 'https://www.courtlistener.com/opinion/2323278/', '2323278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Dobyns v. United States', 'https://www.courtlistener.com/opinion/2323278/', '2323278') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 18] This Court holds that Blackhouse''s request for reasonable accommodation of his alleged disability requires that we accept as true all allegations, no matter how bizarre, and gives a plaintiff license to maintain a bizarre, vexatious, or incredible claim that a trial court would as it did heredismiss were it not brought by one claiming a disability.', 'dismissal', 'Blackhouse v. Doe', 'https://www.courtlistener.com/opinion/2323812/', '2323812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') dismissed Blackhouse''s prior action, and, on appeal, we affirmed the dismissal.', 'dismissal', 'Blackhouse v. Doe', 'https://www.courtlistener.com/opinion/2323812/', '2323812') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Superior Court committed no error, and affirm.', 'general', 'Winer v. State', 'https://www.courtlistener.com/opinion/2335028/', '2335028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the prosecution, we conclude that a rational jury could have found that Winer had intentionally started the fire at the CSI building.', 'general', 'Winer v. State', 'https://www.courtlistener.com/opinion/2335028/', '2335028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons next discussed, we find that Winer has not sustained that burden.', 'general', 'Winer v. State', 'https://www.courtlistener.com/opinion/2335028/', '2335028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the judge ruled appropriately and did not abuse her discretion in precluding Steele’s expert from explaining the law governing arrests and investigative stops to the jury and from expressing his legal conclusion that Harris lacked probable cause or reasonable articulable suspicion to detain Steele for shoplifting.', 'probable_cause', 'Steele v. D.C. Tiger Market', 'https://www.courtlistener.com/opinion/2326595/', '2326595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with precedent in this jurisdiction and elsewhere, we hold that the trial judge in this ease did not abuse her discretion in precluding Steele’s expert witness from interpreting and applying the governing law.', 'general', 'Steele v. D.C. Tiger Market', 'https://www.courtlistener.com/opinion/2326595/', '2326595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As neither of Steele’s contentions entitles him to relief, we affirm the judgment on appeal.', 'general', 'Steele v. D.C. Tiger Market', 'https://www.courtlistener.com/opinion/2326595/', '2326595') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the content of the instant messages written by and to the victim in this case constitutes "sexual conduct" within the meaning of N.', 'general', 'State v. JAC', 'https://www.courtlistener.com/opinion/2296465/', '2296465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in this case, the trial court conducted the careful inquiry required by N.', 'general', 'State v. JAC', 'https://www.courtlistener.com/opinion/2296465/', '2296465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Appellate Division.', 'general', 'State v. JAC', 'https://www.courtlistener.com/opinion/2296465/', '2296465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that a warrantless breath test of Bernard would have been constitutional under the search-incident-to-arrest exception to the Fourth Amendment’s warrant requirement.', 'search_seizure', 'State of Minnesota v. William Robert Bernard, Jr.', 'https://www.courtlistener.com/opinion/2778772/', '2778772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the breath test the police asked Bernard to take would have been constitutional as a search incident to a valid arrest, and as a result, charging Bernard with criminal test refusal does not implicate a fundamental right, and that the test refusal statute is a reasonable means to a permissive object, we affirm.', 'general', 'State of Minnesota v. William Robert Bernard, Jr.', 'https://www.courtlistener.com/opinion/2778772/', '2778772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '4 Based on this authority, we conclude that a warrantless breath test of Bernard would not have violated the Fourth Amendment because it is a search incident to Bernard’s valid arrest.', 'search_seizure', 'State of Minnesota v. William Robert Bernard, Jr.', 'https://www.courtlistener.com/opinion/2778772/', '2778772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the test refusal statute is a reasonable means to a permissive object and that it passes rational basis review.', 'general', 'State of Minnesota v. William Robert Bernard, Jr.', 'https://www.courtlistener.com/opinion/2778772/', '2778772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in Bernard’s case, it is not.', 'general', 'State of Minnesota v. William Robert Bernard, Jr.', 'https://www.courtlistener.com/opinion/2778772/', '2778772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in a prosecution under D.', 'general', 'Graves v. United States', 'https://www.courtlistener.com/opinion/2329689/', '2329689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, without need to address appellants’ constitutional arguments, we reverse with instructions to enter judgments of acquittal.', 'general', 'Graves v. United States', 'https://www.courtlistener.com/opinion/2329689/', '2329689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the quantity of cocaine, coupled with Edwards'' admission concerning his involvement in trafficking drugs, was sufficient to prove beyond a reasonable doubt Edwards'' possession of cocaine with the intent to distribute.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury''s verdict of guilt was reliable, that Edwards has failed to demonstrate prejudice with respect to the alleged omissions of his counsel as to the first three supposed errors of said counsel, and that attorney Perkins was not constitutionally ineffective for failing to object to the admission by Edwards at the scene, because the admission was unsolicited, voluntary, and spontaneous and Perkins could have reasonably expected any objection to be futile.', 'ineffective_assistance', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), this Court held that an intent to distribute or dispense a controlled substance may be established by circumstantial evidence.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Wallace, "[i]n the complete absence of facts showing that [the appellant''s] sentence exceeds others imposed for the same crime in either the same or other jurisdictions, it is impossible for this Court to hold the second and third prongs of the Solem test favor reversal of [the appellant''s] sentence.', 'sentencing', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After close examination of this issue and the trial record thereon, we conclude that attorney Perkins'' failure to object to the testimony in question might reasonably have been trial strategy since from the very moment of opening jury statements, Stan Perkins stated, inter alia, "We will also demonstrate to you that Deputy Spand has a vendetta against the defendant, and we will demonstrate to you that Deputy Spand, prior to this incident, has stopped the defendant and harassed him on the high...', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court was not in error and did not abuse its discretion because the sentence imposed was within the limits fixed by statute and not so grossly disproportionate nor shockingly excessive as to warrant its reversal.', 'sentencing', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the eyewitness testimony of Deputy Spand and the testimony of both Spand and Deputy Cooper, regarding the incriminating admission against interest of Edwards, were sufficient to have absolutely sealed his fate with the jury.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have examined Edwards'' assignments of error as to both the conviction and sentence and finding them to be without merit, we affirm.', 'sentencing', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm.', 'general', 'Edwards v. State', 'https://www.courtlistener.com/opinion/1618454/', '1618454') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, none of her arguments on appeal are supported by the record and we affirm the superior court’s order continuing the order of protection.', 'general', 'Cardoso v. Soldo', 'https://www.courtlistener.com/opinion/2330327/', '2330327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1468334/', '1468334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court.', 'general', 'People v. Cordell', 'https://www.courtlistener.com/opinion/2036507/', '2036507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Cordell', 'https://www.courtlistener.com/opinion/2036507/', '2036507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the State, we hold that this element was not proved.', 'general', 'Hunt v. State', 'https://www.courtlistener.com/opinion/2333187/', '2333187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree that substantial evidence did not exist to prove that appellant committed harassment, and we reverse.', 'general', 'Hunt v. State', 'https://www.courtlistener.com/opinion/2333187/', '2333187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse this case upon appellant’s first argument, we need not address his second argument concerning the length of his sentence.', 'sentencing', 'Hunt v. State', 'https://www.courtlistener.com/opinion/2333187/', '2333187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only if the Trial Court’s ruling is clearly against the preponderance of the evidence.', 'general', 'Travis v. State', 'https://www.courtlistener.com/opinion/1785510/', '1785510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the 2001 amendments to the DWI statute, we conclude that the answer is no.', 'general', 'Getts v. State', 'https://www.courtlistener.com/opinion/2334456/', '2334456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Court of Appeals.', 'general', 'Getts v. State', 'https://www.courtlistener.com/opinion/2334456/', '2334456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that where the State seeks to prosecute a defendant in a Hawaii state court, and seeks to admit evidence obtained in another jurisdiction, the court must give due consideration to the Hawaii Constitution and applicable case law, as indicated herein, when assessing whether such evidence is admissible against the defendant.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bridges, the evidence was obtained in California, so we held that California law determined the defendant’s conception of privacy;', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bridges we concluded that the integrity of Hawai''i courts would not be diminished by admitting evidence obtained in another jurisdiction, provided that the evidence was obtained legally under that jurisdiction’s law.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bridges, we concluded that a defendant’s notions of individual privacy derive from the location in which the defendant is physically present at the time of search, and not from any prescient conception of the jurisdiction in which he or she may eventually be on trial.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/871179/', '871179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was legally sufficient to support Laster''s conviction for attempted aggravated kidnapping.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/2334781/', '2334781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[82] We find that the court of appeals applied the correct standard of review and considered all of the relevant evidence before finding that it was factually sufficient.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/2334781/', '2334781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Affording appropriate deference to the jury''s verdict, we therefore hold that the evidence supporting Laster''s conviction is legally sufficient.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/2334781/', '2334781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a reasonable person in appellant’s shoes would not have perceived himself to be under arrest, or to be subject to a curtailment of his liberty comparable to a formal arrest, when he gave his first confession.', 'general', 'Graham v. United States', 'https://www.courtlistener.com/opinion/2334972/', '2334972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Williams did not engage in the functional equivalent of interrogation, or violate appellant’s Fifth Amendment rights, when he allowed appellant’s mother to remain with him and question him after he asked for an attorney.', 'general', 'Graham v. United States', 'https://www.courtlistener.com/opinion/2334972/', '2334972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a defendant provides to *731 officials in connection with a fraudulent claim a document or oral narrative that contains a material fact or facts relating to the claim, each such document or narration is a "statement" equating to an "act" of insurance fraud.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the connection between the IFPA and the later crime of insurance fraud, defined in similar language, we conclude that the Legislature would have presumed, consistent with our Merin holding, that each document or narrative statement containing materially false facts would be held to be a separate "act" of insurance fraud.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant''s oral and written statements related to a single claim of a stolen automobile, we conclude that the State presented three "acts" of insurance fraud to the grand jury: defendant''s report to the police, defendant''s oral report of the alleged theft to Liberty Mutual, and defendant''s affidavit submitted to Liberty Mutual in support of her claim.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that each document constituted a separate false statement in respect of the fraudulent claim.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that those extrinsic materials are of little assistance in resolving whether discrete facts within a single narrative advanced in furtherance of a fraudulent insurance claim should be considered individual fraudulent "acts.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1256, we found that the defendant had submitted six false statements that were material to his fraudulent claim.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that pursuant to Tennessee Code Annotated section 39-16-707 (1997), the prosecutor was not required to prove which of the two statements made by the defendant was false.', 'general', 'State v. Buford', 'https://www.courtlistener.com/opinion/2336513/', '2336513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the prosecutor was not required to allege or prove which of Buford’s two inconsistent statements was false.', 'general', 'State v. Buford', 'https://www.courtlistener.com/opinion/2336513/', '2336513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that pursuant to Tennessee Code Annotated section 39-16-707, the prosecutor was not required to prove which of the two statements made by Buford was false.', 'general', 'State v. Buford', 'https://www.courtlistener.com/opinion/2336513/', '2336513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that even if the attorney-client privilege applies in this case, the privilege has been waived.', 'general', 'State v. Buford', 'https://www.courtlistener.com/opinion/2336513/', '2336513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the intermediate appellate court, and we reinstate the trial court’s judgment.', 'general', 'State v. Buford', 'https://www.courtlistener.com/opinion/2336513/', '2336513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1273, 1275 (1989) ("Given the unequivocal evidence of appellant’s intent to commit the crime [sexual assault on a child], we hold that his acts of driving toward the apartment where the girl was allegedly waiting and purchasing vaseline to use as a lubricant sufficed for attempt liability.', 'general', 'In Re Doe (" Sd")', 'https://www.courtlistener.com/opinion/2336537/', '2336537') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing factors we hold that Sergeant Joline was justified in continuing to question defendant and, specifically, in asking for his driver’s license, car registration, and other identifying information.', 'general', 'State v. Nishina', 'https://www.courtlistener.com/opinion/2338280/', '2338280') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the search of defendant’s outer clothing is sustainable not as a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the Law Division’s finding that Sergeant Joline did not fear for his personal safety, we conclude that he was not authorized to conduct a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Stamper', 'https://www.courtlistener.com/opinion/2424574/', '2424574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that the order was sufficiently specific to give rise to a personal duty on Chambers'' part to obey it, we grant his petition for writ of habeas corpus because we find that he has conclusively proven that the corporation was unable to comply with the order.', 'habeas', 'Ex Parte Chambers', 'https://www.courtlistener.com/opinion/2432565/', '2432565') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we find that Chambers has established IBS''s inability to comply defense, it is unnecessary to address his remaining points.', 'general', 'Ex Parte Chambers', 'https://www.courtlistener.com/opinion/2432565/', '2432565') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and remand for resentencing.', 'sentencing', 'Cox v. State', 'https://www.courtlistener.com/opinion/2075904/', '2075904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Cox''s conviction as the evidence provided through the victim''s and witnesses'' testimony was sufficient to support the jury''s determination of Cox''s guilt beyond a reasonable doubt.', 'general', 'Cox v. State', 'https://www.courtlistener.com/opinion/2075904/', '2075904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and remand for a new sentencing hearing.', 'sentencing', 'Cox v. State', 'https://www.courtlistener.com/opinion/2075904/', '2075904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '166 is criminal/prohibitory, we hold that the district court and court of appeals erred when they concluded that Minnesota courts do not have jurisdiction to enforce the statute against a tribal member who fails to register while residing on his Indian reservation.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rejecting that claim, we held that the fundamental presumption-of-innocence right only applies to statutes that "are punitive, or criminal, in nature.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Stone, we held that the state''s interest in enforcing traffic laws against tribal members on-reservation could not overcome "`the right of reservation Indians to make their own laws and be ruled by them.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Busse, we held that Minnesota has jurisdiction to enforce Minn.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the conduct in question, driving after cancellation as inimical to public safety, presents heightened public policy concerns and is a criminal and prohibitory offense.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that a tribal member''s violation of section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the broad conduct at issue is residing at an address or moving to a new address by Minnesota residents in general.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the fact that the legislature established a predatory offender registration system is an indication that the whereabouts of predatory offenders  in comparison with the whereabouts of the general population  "presents [a] substantially different or heightened public policy concern[ ].', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislative history of section 243.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1812938/', '1812938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the government, we hold that it was sufficient to prove all three elements.', 'general', 'Freeman v. United States', 'https://www.courtlistener.com/opinion/2343272/', '2343272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, even though the victims had been shot, we held that the government had failed to prove that either of them had suffered “serious bodily injury.', 'general', 'Freeman v. United States', 'https://www.courtlistener.com/opinion/2343272/', '2343272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that this was an error on the part of the court reporter and that "facility” should reasonably be read as "vicinity.', 'general', 'Freeman v. United States', 'https://www.courtlistener.com/opinion/2343272/', '2343272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Freeman v. United States', 'https://www.courtlistener.com/opinion/2343272/', '2343272') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, for these reasons, we reverse defendant’s conviction of unlawful possession of a weapon by a felon and vacate the 3-year sentence imposed on that offense, and we affirm defendant’s 11-year sentence for residential burglary.', 'sentencing', 'People v. Chirchirillo', 'https://www.courtlistener.com/opinion/2057513/', '2057513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse and vacate in part.', 'general', 'People v. Chirchirillo', 'https://www.courtlistener.com/opinion/2057513/', '2057513') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1976) ("While a pardon removes all legal punishments and disabilities attached to a conviction, we hold that it cannot erase the fact that the offender was convicted of an infamous crime.', 'general', 'Heath v. State', 'https://www.courtlistener.com/opinion/2345481/', '2345481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “the pardon may have forgiven [the offender’s] conviction, [but] it did not obliterate the public memory of the offense .', 'general', 'Heath v. State', 'https://www.courtlistener.com/opinion/2345481/', '2345481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that an expunction extinguishes registration requirements.', 'general', 'Heath v. State', 'https://www.courtlistener.com/opinion/2345481/', '2345481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that it made no sense for an individual who has no record of a sexual offense, as a result of expunction, to register as a sexual offender.', 'general', 'Heath v. State', 'https://www.courtlistener.com/opinion/2345481/', '2345481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the General Assembly did not expressly intend for the Registry statute
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we REVERSE the judgment of the Superior Court.', 'general', 'Heath v. State', 'https://www.courtlistener.com/opinion/2345481/', '2345481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we REVERSE the judgment of the Superior Court.', 'general', 'Heath v. State', 'https://www.courtlistener.com/opinion/2345481/', '2345481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'to show that the restriction on expressive activity was narrowly tailored to serve a significant governmental interest," we reversed the defendant''s conviction for crossing the police line.', 'general', 'TETAZ v. District of Columbia', 'https://www.courtlistener.com/opinion/2067743/', '2067743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm their convictions, summarizing the relevant facts as they pertain to each offense-situs and appellants'' related arguments.', 'general', 'TETAZ v. District of Columbia', 'https://www.courtlistener.com/opinion/2067743/', '2067743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we affirm the convictions of appellants for crossing the police line outside the Capitol Building, although the question of whether that measure trenched too closely on protected activity is a closer one.', 'general', 'TETAZ v. District of Columbia', 'https://www.courtlistener.com/opinion/2067743/', '2067743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that where, as here, there is proof of the corpus delicti of a theft and the defendant is charged alternatively with theft or receiving stolen things, that sufficient proof of a corpus delicti exists to make admissible a voluntary confession to having received goods which were the subject of that theft.', 'general', 'Hart v. State', 'https://www.courtlistener.com/opinion/2373381/', '2373381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm that decision.', 'general', 'Hart v. State', 'https://www.courtlistener.com/opinion/2373381/', '2373381') ON CONFLICT DO NOTHING;
