INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. O''NEILL', 'https://www.courtlistener.com/opinion/2069041/', '2069041') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not exceed its authority under the statute or the constitution when it ordered drug testing as a condition of pretrial release.', 'general', 'Oliver v. United States', 'https://www.courtlistener.com/opinion/2069342/', '2069342') ON CONFLICT DO NOTHING;
