INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the condition im
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we conclude that requiring Oliver to submit to drug testing as a condition of his pretrial release was lawful and that the trial court properly denied his motion to suppress the results of his drug tests.', 'suppression', 'Oliver v. United States', 'https://www.courtlistener.com/opinion/2069342/', '2069342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There being no basis on which to\suppress the results of Oliver’s drug tests, we affirm.', 'suppression', 'Oliver v. United States', 'https://www.courtlistener.com/opinion/2069342/', '2069342') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the appellant prefers to focus on the police officers’ testimony that they could not say for sure who fired the shots they heard, we conclude that the above testimony is clearly sufficient to support the appellant’s conviction of attempted capital murder.', 'general', 'Abdullah v. State', 'https://www.courtlistener.com/opinion/2373296/', '2373296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm.', 'general', 'Abdullah v. State', 'https://www.courtlistener.com/opinion/2373296/', '2373296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that constructive, as distinguished from physical, restraint sufficient to constitute a constructive seizure or detention of an arrestee exists where an officer has the intention to effect an arrest, that intention has in some way been communicated to the arrestee, the arrestee understands that he is under legal restraint, and the officer has the apparent present power to control the person even though he has not yet asserted physical control.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/2033582/', '2033582') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the Commonwealth met its burden of proving by a preponderance of the evidence that Nester''s confession was voluntary.', 'general', 'Commonwealth v. Nester', 'https://www.courtlistener.com/opinion/2071064/', '2071064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Commonwealth v. Nester', 'https://www.courtlistener.com/opinion/2071064/', '2071064') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was no error and affirm.', 'general', 'State v. Gandy', 'https://www.courtlistener.com/opinion/1157258/', '1157258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the regulation does not violate Wilkerson’s rights of equal protection or due process because it is an efficient means of eliminating applicants who pose a potential risk to foster children;', 'general', 'Wilkerson v. State, Department of Health & Social Services, Division of Family & Youth Services', 'https://www.courtlistener.com/opinion/1161571/', '1161571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, for the reasons stated above in the discussion of Wilkerson’s equal protection claim, we conclude that the regulation does, not violate substantive due process.', 'general', 'Wilkerson v. State, Department of Health & Social Services, Division of Family & Youth Services', 'https://www.courtlistener.com/opinion/1161571/', '1161571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that competent and substantial evidence was presented to support the jury''s determination that Sewall knowingly obtained money with the intent to deprive the investors of any benefit therefrom, and that he used the investors'' money for his own use when he was not entitled to do so.', 'general', 'Sewall v. State', 'https://www.courtlistener.com/opinion/1671301/', '1671301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that there was sufficient evidence to support each of Sanford’s convictions despite his contention that the crimes were committed by a third party.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion when it allowed Gary’s statement into evidence.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 877 (1995), we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” In Green, supra, we held that the State could use a peremptory challenge to strike a juror who was morally opposed to the death penalty even though the State could not strike the juror for cause because he declared that he could consider the death penalty under certain circumstances.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Sanford’s contention is contrary to the evidence adduced at trial for several reasons.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As previously discussed, we conclude that there is sufficient evidence to support both of those convictions.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was sufficient evidence that Sanford took money and a weapon from Ward’s home, we affirm Sanford’s theft conviction.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Sanford’s conviction of residential burglary because there was sufficient evidence that he entered Ward’s home for the purpose of taking her property.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was sufficient evidence that Ward was alive at the time of the sexual assault, we affirm Sanford’s rape conviction.', 'general', 'Sanford v. State', 'https://www.courtlistener.com/opinion/1774530/', '1774530') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hamilton, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statements were made after Hilding waived his Miranda rights;', 'general', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court did not abuse its discretion by discharging the juror and replacing her with an alternate juror.', 'general', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the charges were properly joined and that the court did not err when it overruled the motion to sever.', 'general', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the stalking charge and the sexual assault charges were properly joined and that joinder did not prejudice Hilding.', 'general', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient to support the convictions.', 'general', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient to support Hilding''s convictions for stalking and two counts of first degree sexual assault.', 'general', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hilding''s sentences were not excessive.', 'sentencing', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Hilding''s convictions and sentences.', 'sentencing', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having rejected each of Hilding''s assignments of error, we affirm his convictions and sentences for two counts of first degree sexual assault and one count of stalking.', 'sentencing', 'State v. Hilding', 'https://www.courtlistener.com/opinion/2094969/', '2094969') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Kilby’s consent to the searches of his King Hill residence and his vehicle was given freely and voluntarily.', 'general', 'State v. Kilby', 'https://www.courtlistener.com/opinion/1195153/', '1195153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, under the totality of the circumstances, we conclude that Kilby’s consent to search his residence at King Hill and his vehicle at the Mountain Home residence was freely and voluntarily given.', 'general', 'State v. Kilby', 'https://www.courtlistener.com/opinion/1195153/', '1195153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the determination that Kilby lacked standing to challenge the initial search, combined with our holding that Kilby freely and voluntarily consented to the subsequent search of his residence at King Hill and his vehicle, we conclude that the fruit of the poisonous tree doctrine is inapplicable to Kilby’s case.', 'general', 'State v. Kilby', 'https://www.courtlistener.com/opinion/1195153/', '1195153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Kilby has failed to show that he did not receive a fair jury trial due to the juror’s outburst.', 'general', 'State v. Kilby', 'https://www.courtlistener.com/opinion/1195153/', '1195153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record on appeal is insufficient to review Kilby’s standing challenge.', 'general', 'State v. Kilby', 'https://www.courtlistener.com/opinion/1195153/', '1195153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the fruit of the poisonous tree doctrine is inapplicable to this case.', 'general', 'State v. Kilby', 'https://www.courtlistener.com/opinion/1195153/', '1195153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Kilby', 'https://www.courtlistener.com/opinion/1195153/', '1195153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Carlson did not err in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming for the sake of argument that we could uphold Judge Carlson’s denial of Martin’s suppression motion in this matter, we conclude that it would be improper for us to do so.', 'suppression', 'Martin v. State', 'https://www.courtlistener.com/opinion/1191999/', '1191999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, after reviewing the prosecutor’s opening statement, we conclude that the jury would not infer from the prosecutor’s statement that Martin had engaged in prior bad acts.', 'general', 'Martin v. State', 'https://www.courtlistener.com/opinion/1191999/', '1191999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the combination of Morgan’s references to Martin’s prior criminal record together with the prosecutor’s improper argument which suggested that Martin contemplated killing Dahl was sufficiently prejudicial that Judge Carlson erred by refusing to grant Martin’s motion for a mistrial.', 'mistrial', 'Martin v. State', 'https://www.courtlistener.com/opinion/1191999/', '1191999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the injection of Martin’s prior criminal record into the trial in combination with the prosecutor''s improper argument was sufficiently prejudicial so as to entitle Martin to a new trial.', 'general', 'Martin v. State', 'https://www.courtlistener.com/opinion/1191999/', '1191999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that we must vacate the superior court’s order finding Martin in contempt.', 'general', 'Martin v. State', 'https://www.courtlistener.com/opinion/1191999/', '1191999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Carlson acted within his discretion in requiring defense counsel to coordinate all motions and pleadings.', 'plea', 'Martin v. State', 'https://www.courtlistener.com/opinion/1191999/', '1191999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Martin’s conviction.', 'general', 'Martin v. State', 'https://www.courtlistener.com/opinion/1191999/', '1191999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'People v. Bartelt', 'https://www.courtlistener.com/opinion/2531060/', '2531060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court, reverse the judgment of the circuit court, and remand to the circuit court for further proceedings consistent with this opinion.', 'general', 'People v. Bartelt', 'https://www.courtlistener.com/opinion/2531060/', '2531060') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that N.', 'general', 'Fowler v. Valencourt', 'https://www.courtlistener.com/opinion/1225074/', '1225074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the resulting prejudice was clear in that the jury gave the maximum sentences for kidnapping and theft to a first offender.', 'sentencing', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2430181/', '2430181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the protective measures were warranted.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2430181/', '2430181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We must first determine the appellants'' sufficiency argument, even though we reverse on other grounds.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2430181/', '2430181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, for example, the handcuffs were used because the defendant was charged with escape from the penitentiary, and we affirmed their use.', 'general', 'Townsend v. State', 'https://www.courtlistener.com/opinion/2430181/', '2430181') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that our prior decisions are not subject to distinction and, after examining the Legislature''s actions following those decisions, we adhere to our precedent and affirm the Court of Appeals''s judgment.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Adhering to our prior decisions, we hold that Section 1.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b) of the Penal Code specified that only Titles 1, 2, and 3 of the Penal Code were applicable to offenses defined outside the Penal Code, we held that the attempt statute did not apply to the Controlled Substances Act.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Less than five months later, in Baker, we held that the Penal Code''s criminal conspiracy statute did not apply to the Controlled Substances Act.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b), we held that Section 1.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b) in Moore, in Baker we held that the criminal conspiracy statute, also contained in Title 4, does not apply to offenses in the Controlled Substances Act.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this we conclude that our prior construction of Section 1.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b) references only Titles 1, 2, and 3 of the Penal Code, we concluded that the criminal attempt and conspiracy statutes in Title 4 of the Penal Code did not apply to offenses defined in the Controlled Substances Act.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ']"[10] As a result, we reversed the trial court''s judgment revoking the appellant''s probation for the offense of conspiracy to sell marijuana, remanded the case, and ordered the prosecution dismissed.', 'dismissal', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '03(b) of the Penal Code in those cases was correct, we affirm the judgment of the Third Court of Appeals upholding the trial judge''s decision to quash the Election Code-based conspiracy charges against Colyandro, Ellis, and Delay.', 'general', 'State v. Colyandro', 'https://www.courtlistener.com/opinion/2101830/', '2101830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Keeping in mind the trial court''s role in credibility findings, and after reviewing the trial record and the § 23-110 hearing transcript, we conclude that the findings in the trial court''s lengthy and detailed memorandum are sufficiently supported by evidence in the record.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that in order for defense counsel to have argued any of those defenses (including those incorporating Dr.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that her testimony was sufficient for a reasonable juror reasonably to find that appellant had committed rape while armed.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agreed with the government that there was enough evidence to infer the defendant entered the home while armed with a dangerous weapon, and that the evidence "might support an inference that he intended to use the weapon if somebody attempted to interfere with his taking of property," we concluded that a burglary conviction "may not rest on such an `if''.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in a case where the evidence showed that two defendants engaged in surreptitious behavior before breaking into a basement and then left without taking anythingaccording to the government, because there was nothing in the basement "both small and valuable enough to steal"we concluded that the evidence was insufficient to sustain a burglary conviction.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, all convictions are affirmed, except the conviction for assault with a dangerous weapon (see supra note 2), which we reverse and remand for entry of an order of dismissal.', 'dismissal', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] Thus, we affirm the conviction of burglary.', 'general', 'Johnson v. United States', 'https://www.courtlistener.com/opinion/2382929/', '2382929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that defendant is unable to meet his burden under the first Brady prong, we need not reach the two other prongs.', 'general', 'State v. Rooney', 'https://www.courtlistener.com/opinion/2556990/', '2556990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While appreciating the appeal of this approach, we conclude that the doctrine cannot be reconciled with the circumstances of this case.', 'general', 'State v. Rooney', 'https://www.courtlistener.com/opinion/2556990/', '2556990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Tester, for instance, we concluded that no Brady violation had occurred, despite the State''s failure to disclose a videotaped interview of the victim, when the defendant was "well aware" of the existence and contents of the interview.', 'general', 'State v. Rooney', 'https://www.courtlistener.com/opinion/2556990/', '2556990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in LeClaire, we concluded that the defendant had not shown that the State improperly suppressed evidence where the prosecution failed to produce a sample of the victim''s hair for DNA testing despite the defendant''s request to do so because the defendant had not taken steps to request the necessary exhumation order.', 'suppression', 'State v. Rooney', 'https://www.courtlistener.com/opinion/2556990/', '2556990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 196, where we concluded that the trial judge had properly addressed the issues and removed potential for prejudice.', 'general', 'State v. McGuire', 'https://www.courtlistener.com/opinion/2558964/', '2558964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed defendant''s conviction, stating:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the verdict and sentence.', 'sentencing', 'State v. McGuire', 'https://www.courtlistener.com/opinion/2558964/', '2558964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the sentence of five months and twenty-nine days as a condition of the five-year probation violates the statutory limitation that a period of incarceration shall not exceed one-third of the minimum sentence established by law for the crime for which the individual was convicted.', 'sentencing', 'State v. White', 'https://www.courtlistener.com/opinion/1277465/', '1277465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in interpreting the order as it stands, we find that the lower court exceeded the maximum time of incarceration allowable as a condition of probation, and we remand this matter with directions to enter an order limiting the incarceration condition to the period allowed by law.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1277465/', '1277465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, for the reasons adopted in Oxford, we find that under § 16-46-304 a blood test will similarly be found not to be confidential information.', 'general', 'McVay v. State', 'https://www.courtlistener.com/opinion/2388698/', '2388698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the judgment appealed from.', 'general', 'McVay v. State', 'https://www.courtlistener.com/opinion/2388698/', '2388698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that only the issues raised in Veatch''s motion for new trial have been timely appealed, and we find no merit to Veatch''s assignments of error.', 'general', 'State v. Veatch', 'https://www.courtlistener.com/opinion/2126040/', '2126040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State adduced evidence that the letter was the same letter allegedly delivered by Warner to Veatch''s wife and that the letter was in the custody of law enforcement.', 'general', 'State v. Veatch', 'https://www.courtlistener.com/opinion/2126040/', '2126040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the proffered evidence was alibi evidence, we find no merit to Veatch''s assertion of error.', 'general', 'State v. Veatch', 'https://www.courtlistener.com/opinion/2126040/', '2126040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the properly admitted evidence, viewed and construed most favorably to the State, is sufficient to support the conviction.', 'general', 'State v. Veatch', 'https://www.courtlistener.com/opinion/2126040/', '2126040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that only the issues properly preserved for appellate review in Veatch''s motion for new trial are before us for resolution because Veatch did not file a timely direct appeal from the judgment.', 'general', 'State v. Veatch', 'https://www.courtlistener.com/opinion/2126040/', '2126040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Veatch', 'https://www.courtlistener.com/opinion/2126040/', '2126040') ON CONFLICT DO NOTHING;
