INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Hanapi failed to show that his conduct constituted protected constitutional activity, we affirm his conviction of and sentence for criminal trespass in the second degree.', 'sentencing', 'State v. Hanapi', 'https://www.courtlistener.com/opinion/1344879/', '1344879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we affirm Hanapi’s conviction of and sentence for criminal trespass in the second degree.', 'sentencing', 'State v. Hanapi', 'https://www.courtlistener.com/opinion/1344879/', '1344879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that it is the obligation of the person claiming the exercise of a native Hawaiian right to demonstrate that the right is protected.', 'general', 'State v. Hanapi', 'https://www.courtlistener.com/opinion/1344879/', '1344879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the court’s errors were harmless.', 'general', 'State v. Hanapi', 'https://www.courtlistener.com/opinion/1344879/', '1344879') ON CONFLICT DO NOTHING;
