INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that defendant’s convictions are merely inconsistent, rather than mutually exclusive.', 'general', 'State v. Blackmon', 'https://www.courtlistener.com/opinion/2391871/', '2391871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the order imposing costs of investigation because there is insufficient evidence to support the amount ordered.', 'general', 'Phillips v. State', 'https://www.courtlistener.com/opinion/1858317/', '1858317') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the order on appeal and remand with instructions to hold a new hearing.', 'general', 'Phillips v. State', 'https://www.courtlistener.com/opinion/1858317/', '1858317') ON CONFLICT DO NOTHING;
