INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'deliberations coerced a guilty verdict, we conclude that the trial court did not abuse its discretion
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State of Missouri v. Markus Steed', 'https://www.courtlistener.com/opinion/2781416/', '2781416') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we hold that the PCRA court erred in dismissing Williams'' twelfth ground for relief without conducting a factual hearing.', 'dismissal', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2395763/', '2395763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[7]  In Kimball, this Court held that the last of these elements, the PCRA''s prejudice requirement, although framed in different terms, is equivalent to the prejudice standard employed in adjudicating a claim of ineffectiveness on direct appeal.', 'ineffective_assistance', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2395763/', '2395763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since this would be inconsistent with our precedent, we find that the PCRA court abused its discretion *1181 not only in failing to make an independent credibility determination, but also in adopting reasons in support of its decision that were insufficient on their face.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2395763/', '2395763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, and remand for limited further proceedings.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2395763/', '2395763') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To that end we hold that, henceforth, in all cases where a minor is charged with a crime in any court a guardian ad litem shall be appointed.', 'general', 'In Re Dobson', 'https://www.courtlistener.com/opinion/2396382/', '2396382') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new sentencing hearing.', 'sentencing', 'Vasquez v. State', 'https://www.courtlistener.com/opinion/2398120/', '2398120') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that casino property was dedicated to use by the public, we held that casinos should not act in an arbitrary and discriminatory manner toward their patrons.', 'general', 'Campione v. Adamar of New Jersey, Inc.', 'https://www.courtlistener.com/opinion/2399877/', '2399877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that because the statute provided an adequate administrative remedy for depositors, the Law Division did not have jurisdiction over the claim.', 'general', 'Campione v. Adamar of New Jersey, Inc.', 'https://www.courtlistener.com/opinion/2399877/', '2399877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we concluded that casinos were not authorized to exclude card counters.', 'general', 'Campione v. Adamar of New Jersey, Inc.', 'https://www.courtlistener.com/opinion/2399877/', '2399877') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 575-after reviewing the record, we hold that the trial court gave proper consideration to both of these categories.', 'general', 'Sampsell v. State', 'https://www.courtlistener.com/opinion/2637430/', '2637430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Judgment and Sentence of the Court.', 'sentencing', 'Sampsell v. State', 'https://www.courtlistener.com/opinion/2637430/', '2637430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the conjunctive language of Count I was proper and charged one offense.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/2401615/', '2401615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the naming of the intended victim to be kidnapped was not required by Chapter I, Article 10th of the Vermont Constitution which provides that “in all prosecutions for criminal offenses a person hath a right to demand the cause and nature of his accusation.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/2401615/', '2401615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case this Court held that common law felonies were not required, by any provision of our own State Constitution, to be prosecuted by indictment,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', and this court held that such failure rendered this count fatally defective.', 'general', 'State v. Barr', 'https://www.courtlistener.com/opinion/2401615/', '2401615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the post-conviction claim on appeal, we hold that defendant waived his right to challenge his conviction under 13 V.', 'general', 'In Re Torres', 'https://www.courtlistener.com/opinion/2401924/', '2401924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant waived his right to challenge his conviction on this ground when he pled guilty to the domestic assault charge.', 'general', 'In Re Torres', 'https://www.courtlistener.com/opinion/2401924/', '2401924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we affirmed a trial court’s refusal to take judicial notice of a child’s testimony from a previous abuse case in the divorce case pending before that court.', 'general', 'In Re Torres', 'https://www.courtlistener.com/opinion/2401924/', '2401924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hank Watson''s waiver of counsel met constitutional requirements and affirm his conviction, but that Jonathan Blumberg''s waiver of counsel did not meet constitutional requirements and thus we vacate his conviction.', 'general', 'State v. Watson', 'https://www.courtlistener.com/opinion/2402274/', '2402274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm his conviction.', 'general', 'State v. Watson', 'https://www.courtlistener.com/opinion/2402274/', '2402274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Barrett, we affirmed the trial court''s finding that the defendant knowingly and intelligently waived his right to counsel when the trial court informed the defendant of his right to counsel, "thoroughly explained the dangers of proceeding pro se to defendant before [it] permitted defendant to exercise his right of self-representation," and explained to the defendant the consequences of so acting.', 'general', 'State v. Watson', 'https://www.courtlistener.com/opinion/2402274/', '2402274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, where an offender is incarcerated on both a Board detainer and new criminal charges, all time spent in confinement must be credited to either the new sentence or the original sentence.', 'sentencing', 'Martin v. Pennsylvania Board of Probation & Parole', 'https://www.courtlistener.com/opinion/2328682/', '2328682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We affirm.', 'general', 'State v. Burke', 'https://www.courtlistener.com/opinion/2070395/', '2070395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that if consent is not a defense to the underlying felony, then it is not a defense to the CSC-I charge under MCL 750.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant''s convictions do not violate the double jeopardy protection against multiple punishments.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 363 (1994), in which this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing this evidence in the light most favorable to the prosecution, we conclude that there was sufficient evidence to permit a rational trier of fact to find that defendant made an intrusion, however slight, with a body part or object into the genital opening of the female victim''s body.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following Ward, we conclude that defendant''s claim has no merit.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Wilkens', 'https://www.courtlistener.com/opinion/2159019/', '2159019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 505 (1980), where we held that an at-will employee, wrongfully discharged in violation of "a clear mandate of public policy," has a common law cause of action against an employer.', 'general', 'D''Annunzio v. Prudential Insurance Co. of America', 'https://www.courtlistener.com/opinion/2353083/', '2353083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1978), we held that evidence of specific instances of the rape victim''s consensual sexual intercourse with persons other than the defendant was not admissible for the purpose of drawing the inference of consent in another instance, citing Evid.', 'general', 'State v. Coruzzi', 'https://www.courtlistener.com/opinion/2353749/', '2353749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '274 (1977), a case in which defendant had been charged with taking large cash bribes, we found that evidence showing five large cash deposits over seven months in a new bank account was properly admissible.', 'general', 'State v. Coruzzi', 'https://www.courtlistener.com/opinion/2353749/', '2353749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 24-465(b) does not establish the exclusive penalty for a work
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that appellants were subject to prosecution under § 22-2601, we affirm their convictions.', 'general', 'Gonzalez v. United States', 'https://www.courtlistener.com/opinion/2160419/', '2160419') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, finding no error in the proceedings below, we affirm appellants’ convictions.', 'general', 'Gonzalez v. United States', 'https://www.courtlistener.com/opinion/2160419/', '2160419') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when law enforcement has probable cause to believe a defendant has committed the offense of criminal vehicular homicide or operation under Minn.', 'probable_cause', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Two years later in Aguirre, we held that a nonconsensual, warrantless removal of a suspect’s blood did not violate the Fourth Amendment when an officer “had probable cause to believe that defendant driver was not only intoxicated but had just committed the felony offense of criminal negligence resulting in death.', 'probable_cause', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Paul, this court held that the police, who were in hot pursuit of a suspected DWI offender, could make a war-rantless entry into the defendant’s home in order to effectuate arrest.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these special facts, we conclude that the attempt to secure evidence of blood-alcohol content in this case was an appropriate incident to petitioner’s arrest.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that when officers have probable cause to believe a defendant has committed the offense of criminal vehicular homicide or operation under Minn.', 'probable_cause', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today we conclude that in the case of criminal vehicular operation the undisputed rapid dissipation of alcohol in the defendant’s blood creates a single-factor exigent circumstance.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, due to the passage of time after the accident, immediate action was required to avoid the loss of blood-alcohol content evidence.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we found that “the need to preserve evidence of [the defendant’s] blood alcohol level is a compelling exigent circumstance under the ‘destruction of evidence’ exception to the warrant requirement first recognized [in Schmerber ].', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that “the need to preserve evidence of Paul’s blood alcohol level is a compelling exigent circumstance,” id.', 'general', 'State v. Shriner', 'https://www.courtlistener.com/opinion/2009694/', '2009694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/2355117/', '2355117') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, applying a common sense interpretation to the affidavit, we conclude that sufficient facts are alleged so as to create a reasonable suspicion that the defendant committed the rape and that the items sought would be found in the locations noted.', 'general', 'Jensen v. State', 'https://www.courtlistener.com/opinion/2355304/', '2355304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that Wybierala is controlling in the present case, we do not encourage the use of such tactics by defense counsel.', 'general', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that where a defendant explicitly waives his right to instructions on a lesser included offense he forfeits his right to raise the issue on appeal.', 'general', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Excluding Saturday (the day of arrest) and Sunday, we held that the 36-hour period had not run and that there was no evidence of unnecessary delay.', 'general', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred in admitting a statement defendant made at the time of arrest into evidence and that such error is not harmless beyond a reasonable doubt.', 'general', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the informant''s reliability, we think the affidavit was sufficient to support a finding of probable cause, and accordingly, we conclude that defendant''s position on this issue is without merit.', 'probable_cause', 'State v. Wiberg', 'https://www.courtlistener.com/opinion/2163965/', '2163965') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case we hold that the constitutional prohibition against double jeopardy does not bar criminal prosecution and punishment for driving under the influence of intoxicating liquor after the suspension of the defendant’s driver’s license in a civil proceeding resulting from the same underlying incident.', 'general', 'State v. Strong', 'https://www.courtlistener.com/opinion/2164338/', '2164338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on all of these factors, we conclude that defendant’s license suspension was not a “punishment” for double jeopardy purposes.', 'general', 'State v. Strong', 'https://www.courtlistener.com/opinion/2164338/', '2164338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that when one unlawfully dispatches a domestic animal belonging to another person by using a commonly accepted, humane method, and there is no evidence of any other form of malice, the killing is not malicious and consequently does not violate W.', 'general', 'State v. Burgess', 'https://www.courtlistener.com/opinion/1302508/', '1302508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm holding that at the conclusion of the statutory 90 day suspension period, the appellant''s failure to pay the $100 fee effectively rendered her status as one driving without a license.', 'general', 'Allen v. State', 'https://www.courtlistener.com/opinion/2358534/', '2358534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the forgoing reasons, we affirm the Court of Appeals.', 'general', 'Allen v. State', 'https://www.courtlistener.com/opinion/2358534/', '2358534') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 196 (1996), this court held that where a record was vague as to which subsection a defendant was convicted of violating, there was no error committed because the subsections were merely different ways of proving a single violation.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2359065/', '2359065') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Appellant''s conviction for disorderly conduct.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2359065/', '2359065') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 556 (1975), this Court held that legislation affecting substantive rights will not be applied retroactively unless the legislature has expressly provided that it shall, but legislation merely altering procedure will generally be applied to pending proceedings.', 'general', 'Commonwealth v. Gribble', 'https://www.courtlistener.com/opinion/2167000/', '2167000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'According to the legislature’s statutory mandate, we must affirm a sentence of death unless we find that it is “excessive or disproportionate to the penalty imposed in similar cases, considering both the circumstances of the crime and the character and record of the defendant.', 'sentencing', 'Commonwealth v. Gribble', 'https://www.courtlistener.com/opinion/2167000/', '2167000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have reviewed the sentencing data compiled by the AOPC, considering both the circumstances of the crime and the character and record of the defendant, and we find that the sentence of death here is not excessive or disproportionate to the penalty imposed in similar cases.', 'sentencing', 'Commonwealth v. Gribble', 'https://www.courtlistener.com/opinion/2167000/', '2167000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In contrast, where an act stated that it shall apply to “all criminal cases and appeals pending on the effective date of this act”, we found that the General Assembly intended the law to apply retroactively.', 'general', 'Commonwealth v. Gribble', 'https://www.courtlistener.com/opinion/2167000/', '2167000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm the judgment of sentence imposed by the trial court.', 'sentencing', 'Commonwealth v. Gribble', 'https://www.courtlistener.com/opinion/2167000/', '2167000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the verdict and sentence of death.', 'sentencing', 'Commonwealth v. Gribble', 'https://www.courtlistener.com/opinion/2167000/', '2167000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '), where we held that the Due Process *634 Clause of the Fourteenth Amendment requires the appointment of counsel in a civil contempt proceeding in which an indigent defendant faces "actual imprisonment.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was not entitled to counsel at this hearing because the court did not consider incarcerating defendant without providing him another opportunity, if necessary, to challenge his ability to comply with the child support orders and the reasonableness of the purge conditions with the aid of counsel.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant''s right to counsel was fully protected in these proceedings.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the public defender act does not authorize assignment of a public defender in this case, this does not end our inquiry.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that a respondent in an indirect civil contempt proceeding is not entitled to appointed counsel if he or she is indigent, even though the contempt proceeding may result in imprisonment.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s order of incarceration and deny the motion to withdraw.', 'general', 'Russell v. Armitage', 'https://www.courtlistener.com/opinion/2361273/', '2361273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the prosecutor''s comments were "clearly improper" because he implied that the expert''s testimony was fabricated or contrived with the assistance of defense counsel.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that the prosecutor''s remarks *272 were improper and constituted prosecutorial misconduct.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the expert witnesses'' testimony about where Makowski was riding her bicycle when she was hit by defendant''s car was highly contested at trial and because defendant''s guilt depended entirely on which experts the jury believed, we conclude that the inappropriate comments made by the prosecutor could have improperly swayed the jury and denied defendant a fair trial.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed defendant''s death sentence for a number of reasons, including that the cumulative effect of prosecutorial improprieties were substantially prejudicial and deprived defendant of his constitutional right to a fair trial.', 'sentencing', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the conviction on other grounds and did not determine whether any alleged *269 misconduct constituted reversible error.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division affirming defendant''s conviction and remand the matter to the Law Division for a new trial.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/2362247/', '2362247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the requirement imposed on
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the circumstances, we conclude that the Attorney Gen-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this appeal from a conviction for distributing cocaine, we hold that the Clause was violated when the prosecution introduced a Drug Enforcement Administration chemist’s written expert testimony against appellant without calling the chemist to appear and testify in person.', 'general', 'Thomas v. United States', 'https://www.courtlistener.com/opinion/2363213/', '2363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1993), we held that the Constitution does not require the government to produce the DEA chemist in its case-in-chief “instead of merely making him available during the defense case.', 'general', 'Thomas v. United States', 'https://www.courtlistener.com/opinion/2363213/', '2363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a saving construction is fairly possible along the lines of the government’s proposal.', 'general', 'Thomas v. United States', 'https://www.courtlistener.com/opinion/2363213/', '2363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1544, and we conclude that we must do the same in this case.', 'general', 'Thomas v. United States', 'https://www.courtlistener.com/opinion/2363213/', '2363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, and because we find no merit in appellant’s other claims of error, we affirm his conviction.', 'general', 'Thomas v. United States', 'https://www.courtlistener.com/opinion/2363213/', '2363213') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the embezzlement of property belonging to the United States Government, when embezzled in the State of Oklahoma, is an offense against the State and constitutes a crime as prescribed by our State statutes.', 'general', 'State v. Musto', 'https://www.courtlistener.com/opinion/2366964/', '2366964') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '04, we conclude that it may include within its sweep innocent and legitimate conduct.', 'general', 'Arkansas Game & Fish Commission v. Murders', 'https://www.courtlistener.com/opinion/2369683/', '2369683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we agree that the amended portion of the Commission’s rule is unconstitutionally overbroad and exceeds the scope of the Commission’s constitutional authority, we affirm the ruling of the trial court.', 'general', 'Arkansas Game & Fish Commission v. Murders', 'https://www.courtlistener.com/opinion/2369683/', '2369683') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6] Assuming arguendo that defendant may make an overbreadth challenge of the "follows" portion of the statute, we conclude that the statute is not overbroad.', 'general', 'Pallas v. State', 'https://www.courtlistener.com/opinion/1788542/', '1788542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Pallas v. State', 'https://www.courtlistener.com/opinion/1788542/', '1788542') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Apprendi, we held that a fact is by definition *108an element of the offense and must be submitted to the jury if it increases the punishment above what is otherwise legally prescribed.', 'general', 'Alleyne v. United States', 'https://www.courtlistener.com/opinion/903985/', '903985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We held that the Sixth Amendment provides defendants with the right to have a jury find those facts beyond a reasonable doubt.', 'general', 'Alleyne v. United States', 'https://www.courtlistener.com/opinion/903985/', '903985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That distinction was undermined by Apprendi, where we held that a legislature may not "remove from the jury the assessment of facts that increase the prescribed range of penalties to which a criminal defendant is exposed.', 'general', 'Alleyne v. United States', 'https://www.courtlistener.com/opinion/903985/', '903985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that this possibility did not preclude a Sixth Amendment violation.', 'general', 'Alleyne v. United States', 'https://www.courtlistener.com/opinion/903985/', '903985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From a consideration of this statute as a whole, and the public policy it appears designed to implement, that of public safety and removal from the highways of those drivers whose irresponsible operation has killed another human being, we hold that it was the intent of the legislature to subject all drivers who operate in violation of the enumerated offenses with a death resulting to the one year suspension provision.', 'general', 'Hill v. Conway', 'https://www.courtlistener.com/opinion/2372505/', '2372505') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State’s motion for summary judgment was properly granted, and plaintiff’s motion correctly denied.', 'general', 'Hill v. Conway', 'https://www.courtlistener.com/opinion/2372505/', '2372505') ON CONFLICT DO NOTHING;
