INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the opinion offered by the officer does not meet the requirements needed to qualify it as a lay opinion, and because we conclude that permitting the officer to testify about his opinion invaded the fact-finding province of the jury, we reverse defendant''s conviction and remand for further proceedings.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 702, we concluded that an expert could testify about matters including the acquisition of drugs in New York City, the comparatively higher street value of those drugs if sold here, the purpose of using plastic bags, and "the reasons why drug dealers use juveniles as `mules'' to carry drugs on their person in the course of transport.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More recently, we concluded that in the context of a transaction in which defendant did not personally hand over the drugs or accept payment, an expert may be utilized to explain to the jury how his actions fit into the scheme of a "street-level distribution network.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that there was no need for an expert "to explain the straightforward manner in which the transactions at issue [in those cases] took place," because they involved only a defendant who was "observed directly handing something to the alleged purchaser and receiving what appeared to be payment in return.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nesbitt, we concluded that such testimony sets forth facts that are not so outside the ken of jurors that they need an expert to spell out for them whether that defendant engaged in a criminal transaction and that offering an expert in those circumstances would be improper.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed defendant''s conviction, concluding that the expert''s inappropriate use of the phrase "constructive possession," a legal term that "mimicked the language of the statute," violated Odom''s directive that experts avoid the "precise terminology, and particularly the legalese, of an applicable criminal statute.', 'general', 'State v. McLean', 'https://www.courtlistener.com/opinion/2423079/', '2423079') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court committed reversible error in allowing the *644 State to present reputation and other bad acts evidence, and remand the case for a new trial.', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/1439460/', '1439460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hart''s statement, we find that the trial court abused its discretion when it failed to grant the motion for mistrial.', 'mistrial', 'Green v. State', 'https://www.courtlistener.com/opinion/1439460/', '1439460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we find that the trial court abused its discretion in allowing Joshua''s "control" testimony because it is not relevant evidence.', 'general', 'Green v. State', 'https://www.courtlistener.com/opinion/1439460/', '1439460') ON CONFLICT DO NOTHING;
