INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Davison''s multiplicity objection fails on the merits, we decline to decide whether, by pleading guilty, he waived his right to raise this claim.', 'plea', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the imposition of cumulative punishments from different statutes in a single prosecution for "the same offense" violates double jeopardy when the cumulative punishments are not intended by the legislature.', 'general', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our four-factor examination of legislative intent to this multiplicity challenge, we conclude that Davison has failed to meet his burden of *195 persuasion.', 'general', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we affirmed the circuit court''s decision refusing to submit either simple battery or intermediate battery to the jury as lesser-included offenses of aggravated battery.', 'general', 'State v. Davison', 'https://www.courtlistener.com/opinion/2219269/', '2219269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the pat-down search did not violate Morgan''s right under the federal and state constitutions to be free from unreasonable searches.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/2219473/', '2219473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an officer making a Terry stop need not reasonably believe that an individual is armed;', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/2219473/', '2219473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the time of nightfour a.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/2219473/', '2219473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that the court of appeals, and this court, can use Morgan''s nervousness as a factor in its de novo determination of the legality of Officer Mulock''s pat-down search.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/2219473/', '2219473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the court of appeals, we find that an officer''s perception of an area as "high-crime" can be a factor justifying a search.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/2219473/', '2219473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these facts, taken in combination, were sufficient to cause a reasonable officer to have a reasonable suspicion that Morgan might be armed, and justified the limited pat-down search for weapons which Officer Mulock conducted.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/2219473/', '2219473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/2219473/', '2219473') ON CONFLICT DO NOTHING;
