INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the two federal convictions do not qualify as historical prior felony convictions under A.', 'general', 'State v. Sharma', 'https://www.courtlistener.com/opinion/2518590/', '2518590') ON CONFLICT DO NOTHING;
