INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court improperly sentenced Rewitzer because the fines and surcharges imposed by the court violated the Excessive Fines Clauses of the United States and Minnesota Constitutions.', 'sentencing', 'State v. Rewitzer', 'https://www.courtlistener.com/opinion/2227356/', '2227356') ON CONFLICT DO NOTHING;
