INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these arguments are without merit.', 'general', 'In Re Tidwell', 'https://www.courtlistener.com/opinion/2267990/', '2267990') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that once an attorney is convicted of an offense involving moral turpitude, disbarment is mandatory, regardless of any mitigating circumstances such as alcoholism.', 'general', 'In Re Tidwell', 'https://www.courtlistener.com/opinion/2267990/', '2267990') ON CONFLICT DO NOTHING;
