INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bailey''s speech with immediate violence, the First Amendment requires that we reverse the conviction for disorderly conduct.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/2441447/', '2441447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we affirm the trial court''s judgment.', 'general', 'Bailey v. State', 'https://www.courtlistener.com/opinion/2441447/', '2441447') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that, “[a]s prosecuted in this case, defendant could not be convicted and sentenced for the crimes of giving false information to a law enforcement officer and impeding an officer *586without running afoul of the Double Jeopardy Clause.', 'sentencing', 'State v. Breed', 'https://www.courtlistener.com/opinion/2786013/', '2786013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In attempting to distinguish Hazelton — a case in which we held that the elements of the offense of engaging in a sexual act with an unmarried minor less than sixteen years old, in violation of § 3252(a)(3), are the same as the elements of the offense of committing an unconsented sexual assault, in violation of § 3252(a)(1)(A), see 2006 VT 121, ¶ 24 — the State argues that the penalties for the two charged offenses in the instant case, unlike the offenses in Hazelton, differ.', 'general', 'State v. Breed', 'https://www.courtlistener.com/opinion/2786013/', '2786013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1126 (“Our review of trial court evidentiary rulings is deferential, and we reverse only when there is an abuse of discretion resulting in prejudice.', 'general', 'State v. Breed', 'https://www.courtlistener.com/opinion/2786013/', '2786013') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Class B felony conviction and habitual offender adjudication but remand to the trial court with instructions to set aside the Class C felony conviction.', 'general', 'Kocielko v. State', 'https://www.courtlistener.com/opinion/2481416/', '2481416') ON CONFLICT DO NOTHING;
