INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s multiple punishments do not violate the principle of double jeopardy.', 'general', 'People v. Walker', 'https://www.courtlistener.com/opinion/2209836/', '2209836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While this Court held in Frohriep, supra at 697-698, 637 N.', 'general', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court''s findings were not clearly erroneous and that the coerciveness of the encounter constituted an unreasonable seizure of defendant''s person.', 'general', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Only when the officer, by means of physical force or show of authority, has in some way restrained the liberty of a citizen may we conclude that a "seizure" has occurred.', 'general', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, under these circumstances we conclude that the police officers'' persistence despite defendant''s efforts to terminate the encounter resulted in defendant being seized in violation of his constitutional rights.', 'general', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that defendant is entitled to the suppression of his incriminating statements and the marijuana.', 'suppression', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court''s order affirming the district court''s order of dismissal.', 'dismissal', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court''s order affirming the district court''s dismissal of this case.', 'dismissal', 'People v. Bolduc', 'https://www.courtlistener.com/opinion/2204665/', '2204665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 526, 533 (2004) ("We conclude that the testimony regarding the defendant''s gang affiliation did not constitute evidence of the defendant''s prior misconduct because it did not show any bad act or criminal conduct on his part.', 'general', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that N.', 'general', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the substance of the second factor, if it is applicable, has been satisfied.', 'general', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the fourth Cofield factor has been satisfied because the gang-related evidence explains Goodman''s killing of Bryant despite their prior friendship.', 'general', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence also satisfied the third factor, because there was sufficient proof that Goodman wrote the letter and that he spoke to Carney at the *782 jail.', 'general', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the record as a whole, we conclude that the trial judge acted appropriately and that he did not abuse his discretion in deciding to deny the application for a mistrial.', 'mistrial', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the record, we conclude that there was no rational basis for a charge of aggravated manslaughter, largely for the same reasons articulated by Judge Kennedy.', 'general', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we affirm the trial judge''s determination to allow the gang-related testimony, the testimony concerning Goodman''s letter to Jones, and the statement made by Goodman to Carney at the Essex County Jail.', 'general', 'State v. Goodman', 'https://www.courtlistener.com/opinion/2446999/', '2446999') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6] We conclude that the $52,000 award is not supported by the evidence.', 'general', 'Evans v. Evans', 'https://www.courtlistener.com/opinion/2205836/', '2205836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8] Therefore, we reverse the trial court''s $52,000 award and remand to the court for a hearing to determine the extent of James'' actual damages, if any, resulting from Evans'' contempt.', 'general', 'Evans v. Evans', 'https://www.courtlistener.com/opinion/2205836/', '2205836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand with instructions.', 'general', 'Evans v. Evans', 'https://www.courtlistener.com/opinion/2205836/', '2205836') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State of Maine v. Jerry Lee Adams', 'https://www.courtlistener.com/opinion/2786679/', '2786679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that 17-A M.', 'general', 'State of Maine v. David Reckards', 'https://www.courtlistener.com/opinion/2786680/', '2786680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in light of our prior cases and the Supreme Court decision in White, the testimony of the professional counselor and the pediatrician, attacked as hearsay, properly was received in evidence at the trial.', 'general', 'Betzle v. State', 'https://www.courtlistener.com/opinion/2615047/', '2615047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this instance, we hold that since both the professional counselor and the pediatrician were qualified as experts, and their opinion was of assistance to the trier of fact, the testimony was properly admitted pursuant to Wyo.', 'general', 'Betzle v. State', 'https://www.courtlistener.com/opinion/2615047/', '2615047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), we held that an expert witness may give testimony about what was said to the witness by an abused child under the exception articulated in Wyo.', 'general', 'Betzle v. State', 'https://www.courtlistener.com/opinion/2615047/', '2615047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm their convictions.', 'general', 'Cooper v. State', 'https://www.courtlistener.com/opinion/2459921/', '2459921') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the misdemeanor sexual abuse statute refers equally to the offensive touching of the enumerated areas of the abuser’s body, as well as the victim’s body, and that the evidence more than sufficed to prove that appellant solicited sex from and caused a child to touch his penis, thereby committing the offenses, respectively, of attempted lewd acts and misdemeanor sexual abuse.', 'general', 'Pinckney v. United States', 'https://www.courtlistener.com/opinion/2360451/', '2360451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the evidence supports the trial court’s finding that, by causing the “touching” of his own genitalia with S.', 'general', 'Pinckney v. United States', 'https://www.courtlistener.com/opinion/2360451/', '2360451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the clear statement of legislative intent to include “the broad range of abusive conduct which does in fact occur,” we conclude that the broader interpretation of the definition of “sexual contact” to include actions by another compelled by the defendant, is consistent with the legislative purpose.', 'general', 'Pinckney v. United States', 'https://www.courtlistener.com/opinion/2360451/', '2360451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986), this court held that the prosecutor had not improperly vouched for the credibility of a police officer witness by asking the defendant if he could “ ''think of any reason why [the officer] would come to court and perjure himself and risk fourteen years on the police force.', 'general', 'State v. Morales', 'https://www.courtlistener.com/opinion/2632179/', '2632179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence considered by the jury was sufficient to sustain Bouwkamp''s conviction on both felony murder and premeditation theories.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when there is such a danger of a fragmented verdict, the court must instruct a jury, on request, that if a guilty verdict is returned, the jury must be unanimous on the underlying facts.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we conclude that such an instruction was not required in this case.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the same bootstrapping is involved in instructing a jury that the intent to assault makes the entry burglary and that the burglary raises the homicide resulting from the assault to first degree murder without proof of malice aforethought and premeditation.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that heretofore we have not identified and articulated a method for evaluating evidence of premeditation.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Bouwkamp''s conviction.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm that premeditation remains the defining crux and the distinction which this court will require to uphold a first degree murder conviction.', 'general', 'Bouwkamp v. State', 'https://www.courtlistener.com/opinion/2607400/', '2607400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,[18] we held that in determining the weight of processed marijuana, all that was necessary to convict under the statute was "that the substance delivered contains marijuana, and that the aggregate weight of the substance meets the statutory requirement.', 'general', 'Maness v. State', 'https://www.courtlistener.com/opinion/2632372/', '2632372') ON CONFLICT DO NOTHING;
