INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Love', 'https://www.courtlistener.com/opinion/2480426/', '2480426') ON CONFLICT DO NOTHING;
