INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this proceeding, we affirm defendant’s conviction.', 'general', 'State v. Julie L. Michaels (072106)', 'https://www.courtlistener.com/opinion/2713863/', '2713863') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a judgment for support arrearages is enforceable by contempt proceedings after a child has reached the age of majority.', 'general', 'Gibson v. Bennett', 'https://www.courtlistener.com/opinion/1866865/', '1866865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After citing the rule announced in Sackler, this Court held that a nonresident wife may seek enforcement of a money judgment based on a final decree for support either in a court of law or a court of equity.', 'general', 'Gibson v. Bennett', 'https://www.courtlistener.com/opinion/1866865/', '1866865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*569 In Lamm, this Court held that when a custodial parent accepts public assistance money for the support of a dependent child, the Department of Health and Rehabilitative Services can seek reimbursement of the payments from the support obligated parent by asserting the custodial parent''s right to child support through any appropriate remedy available to the child''s custodian, including contempt.', 'general', 'Gibson v. Bennett', 'https://www.courtlistener.com/opinion/1866865/', '1866865') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'People v. Bingham', 'https://www.courtlistener.com/opinion/2037995/', '2037995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse, finding the trial court violated defendant’s right to choice of counsel by erroneously denying defendant’s motion for continuance to substitute counsel without conducting an adequate inquiry into the request.', 'general', 'People v. Bingham', 'https://www.courtlistener.com/opinion/2037995/', '2037995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we reverse the trial court’s judgment and remand for a new trial.', 'general', 'People v. Bingham', 'https://www.courtlistener.com/opinion/2037995/', '2037995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that when a party raises the question of statutory immunity prior to trial, the proper standard for the circuit court to use in determining immunity under the Act is a preponderance of the evidence.', 'general', 'State v. Duncan', 'https://www.courtlistener.com/opinion/2509688/', '2509688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we find that, by using the words “immune from criminal prosecution,” the legislature intended to create a true immunity, and not simply an affirmative defense.', 'general', 'State v. Duncan', 'https://www.courtlistener.com/opinion/2509688/', '2509688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Duncan', 'https://www.courtlistener.com/opinion/2509688/', '2509688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the State may properly charge the defendants with being parties to the crime of attempted first-degree intentional homicide and with conspiracy to commit first-degree intentional homicide of one intended victim.', 'general', 'State v. Moffett', 'https://www.courtlistener.com/opinion/2037112/', '2037112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Wis.', 'general', 'State v. Moffett', 'https://www.courtlistener.com/opinion/2037112/', '2037112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we conclude that the defendants'' conduct forms the basis for two different offenses tinder two different statutory provisions and that Wis.', 'general', 'State v. Moffett', 'https://www.courtlistener.com/opinion/2037112/', '2037112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we affirm the decision of the court of appeals.', 'general', 'State v. Moffett', 'https://www.courtlistener.com/opinion/2037112/', '2037112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the circuit court appropriately exercised its discretion in refusing to modify Crochiere''s sentence.', 'sentencing', 'State v. Crochiere', 'https://www.courtlistener.com/opinion/2038627/', '2038627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the court of appeals.', 'general', 'State v. Crochiere', 'https://www.courtlistener.com/opinion/2038627/', '2038627') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Graf, we held that the plaintiff''s injuries arose out of the "maintenance" of a motor vehicle.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 2 We conclude that when the action under consideration is undertaken to service or repair a vehicle, and the condition of the vehicle is such that it could not then be driven on a public roadway, the action does not constitute "operation of a motor vehicle" within the meaning of Wis.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 28 Our decision herein is consistent with our discussion in Rocker when we conclude that actions that constitute maintenance or repairs of a motor vehicle, while the condition of the vehicle is such that it could not then be driven on a public roadway, cannot constitute operation of a motor vehicle.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 29 We conclude that when the action under consideration is undertaken to service or repair a vehicle, and the condition of the vehicle is such that it could not then be driven on a public roadway, the action does not constitute "operation of a motor vehicle" within the meaning of Wis.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '09, and relying on Modory, we concluded that a snowmobile need not be put in motion in order for it to be operated, but some affirmative action must have occurred.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Bloechl''s action did not constitute operation of a motor vehicle because Bloechl''s "primary intention and purpose in attempting to start the car was to finish the repairs.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the exclusion was invalid because a full-service car wash is a motor vehicle handler within § 632.', 'general', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court''s summary judgment dismissing McNeil''s claims.', 'dismissal', 'McNeil v. Hansen', 'https://www.courtlistener.com/opinion/2078844/', '2078844') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the defendant must be granted a new trial for the reasons discussed above, we are not required to pass on the remaining issue presented.', 'general', 'State v. Moran', 'https://www.courtlistener.com/opinion/2380479/', '2380479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We decline this invitation because we conclude that even with the exclusion of the information in the affidavit that was obtained from the entry for purposes of making the arrest, the affidavit contained sufficient facts upon which an impartial judicial officer could have found probable cause for issuance of a warrant to search the defendant’s apartment.', 'probable_cause', 'State v. Moran', 'https://www.courtlistener.com/opinion/2380479/', '2380479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In line with the foregoing cases, we conclude that the use of “and/or” in the jury instructions did not amount to fundamental error in this case.', 'jury_instruction', 'Smith v. State', 'https://www.courtlistener.com/opinion/2489194/', '2489194') ON CONFLICT DO NOTHING;
