INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, concluding not only that the argument was waived by appellant’s request, but also that given the totality of the circumstances the instruction was not fundamental error.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2489194/', '2489194') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, "the basic concerns of criminal justice compel us to prohibit .', 'general', 'State v. Ramsay', 'https://www.courtlistener.com/opinion/2292504/', '2292504') ON CONFLICT DO NOTHING;
