INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse appellant''s conviction for disorderly intoxication.', 'general', 'Royster v. State', 'https://www.courtlistener.com/opinion/1879192/', '1879192') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the remaining three charges, we reverse and remand for a new trial.', 'general', 'Royster v. State', 'https://www.courtlistener.com/opinion/1879192/', '1879192') ON CONFLICT DO NOTHING;
