INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'pursued and no references are made to the record, we find that it is waived.', 'general', 'State v. Eddinger', 'https://www.courtlistener.com/opinion/1073992/', '1073992') ON CONFLICT DO NOTHING;
