INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing authorities and reasoning, we affirm the judgment of conviction.', 'general', 'State v. Eddinger', 'https://www.courtlistener.com/opinion/1073992/', '1073992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, in a probation revocation hearing, a trial court must make an explicit finding, and must state its reasons on the record, whether there is good cause for dispensing with the probationer''s confrontation right and admitting hearsay into evidence.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finch, we held that "reliable hearsay can be admitted in a probation revocation proceeding and serve as the basis for revocation" without undermining the probationer''s confrontation rights.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "[t]he detoxification center report appears to be the kind of medical report where .', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the affidavit of the New Hampshire police officer does not bear the traditional indicia of reliability that will permit admissibility of the affidavit over a valid objection on confrontation grounds.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After observing that the hearsay sources were "mutually supportive," and that the medical report was of the kind in which questions of credibility and veracity were not present, we concluded that "[t]he evidence in this case had sufficient indicia of reliability," and affirmed the revocation order.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the determinations that defendant violated the travel and therapy conditions, but affirm the violation of the urinalysis condition.', 'general', 'State v. Austin', 'https://www.courtlistener.com/opinion/2304790/', '2304790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sustaining the defendant’s contention, we held that his complaint was not forfeited because the defendant “could not reasonably be expected to have known that the testimony was false at the time that it was made.', 'general', 'Ex Parte Napper', 'https://www.courtlistener.com/opinion/2272718/', '2272718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, despite problems with the lab, applicant’s claims are without merit.', 'general', 'Ex Parte Napper', 'https://www.courtlistener.com/opinion/2272718/', '2272718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the likelihood of an exculpatory result is small, though not zero.', 'general', 'Ex Parte Napper', 'https://www.courtlistener.com/opinion/2272718/', '2272718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the new test results from ReliaGene and Orchid Cell-mark do not alter the prejudice analysis in applicant’s favor.', 'general', 'Ex Parte Napper', 'https://www.courtlistener.com/opinion/2272718/', '2272718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we find that the court did not abuse its discretion in imposing a twenty-nine-year sentence.', 'sentencing', 'State v. Reese', 'https://www.courtlistener.com/opinion/2273318/', '2273318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and the sentence.', 'sentencing', 'State v. Reese', 'https://www.courtlistener.com/opinion/2273318/', '2273318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Respondent''s cumulative misconduct warrants a suspension of one year and one day.', 'general', 'People v. Maynard', 'https://www.courtlistener.com/opinion/2499841/', '2499841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 13-2409 encompasses the conduct that occurred here — a misrepresentation to a minor child’s caregiver, rather than to a child victim or witness directly, for the purpose of obstructing, delaying, or preventing the victim or witness from communicating relevant information concerning an alleged crime to a peace officer.', 'general', 'State v. Carrasco', 'https://www.courtlistener.com/opinion/2515862/', '2515862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'to advise her of her right not to speak with the police, we conclude that the trial court abused its discretion in granting Carrasco’s motion for judgment of acquittal.', 'general', 'State v. Carrasco', 'https://www.courtlistener.com/opinion/2515862/', '2515862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the statute clearly describes the conduct it proscribes, we conclude that a person of reasonable intelligence has reasonable notice of the circumstances under which it applies.', 'general', 'State v. Carrasco', 'https://www.courtlistener.com/opinion/2515862/', '2515862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, as we have already noted, the statute is not violated unless and until a person makes a misrepresentation or commits other conduct specified in the statute, we conclude that the statute is not over-broad.', 'general', 'State v. Carrasco', 'https://www.courtlistener.com/opinion/2515862/', '2515862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding such abuse here, we reverse.', 'general', 'State v. Carrasco', 'https://www.courtlistener.com/opinion/2515862/', '2515862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 15 We reverse the trial court’s grant of Carrasco’s motion for judgment of acquittal, reinstate the jury’s verdict, and remand for sentencing.', 'sentencing', 'State v. Carrasco', 'https://www.courtlistener.com/opinion/2515862/', '2515862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[9]  In Jackson, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that even the testimony most adverse to the defense, Stroud''s testimony, established as a matter of law that Petitioner actually believed he was in imminent danger of losing his life or sustaining serious bodily injury, and that a reasonable person of ordinary firmness would have entertained the same belief.', 'general', 'State v. Dickey', 'https://www.courtlistener.com/opinion/2507697/', '2507697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that as a matter of law, Petitioner actually believed he was in imminent danger of losing his life, or sustaining serious bodily injury, and that a reasonable person would have entertained the same belief.', 'general', 'State v. Dickey', 'https://www.courtlistener.com/opinion/2507697/', '2507697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse.', 'general', 'State v. Dickey', 'https://www.courtlistener.com/opinion/2507697/', '2507697') ON CONFLICT DO NOTHING;
