INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 706 (1985), this court held that the state may prove prior convictions by evidence other than a certified judgment of conviction.', 'general', 'State v. Robles', 'https://www.courtlistener.com/opinion/2633582/', '2633582') ON CONFLICT DO NOTHING;
