INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified.', 'general', 'State v. Wissing', 'https://www.courtlistener.com/opinion/2027605/', '2027605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, save and except as modified above.', 'general', 'State v. Wissing', 'https://www.courtlistener.com/opinion/2027605/', '2027605') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant has standing to challenge the search under the Vermont Constitution, and reverse the court’s ruling.', 'general', 'State v. Wood', 'https://www.courtlistener.com/opinion/2350312/', '2350312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2, supra, we hold that, given (1) the destructive, deceitful, and wasteful, albeit nonviolent, character of Kahapea''s offenses and (2) the primacy of the retributive, incapacitative, and deterrent objectives, five consecutive ten-year terms of imprisonment does not reflect a plain and manifest abuse of discretion on the part of the circuit court.', 'general', 'State v. Kahapea', 'https://www.courtlistener.com/opinion/2633655/', '2633655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 497 (2001) ("We hold that the balance of these considerations requires no more than reasonable suspicion to conduct a search of this probationer''s house.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that an anonymous caller''s tip was not sufficiently corroborated where:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '19, we conclude that the probation officers should have conducted an independent assessment of the caller''s and of Lt.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ogden''s information did not form a basis for reasonable suspicion, we conclude that the probation officers had no basis under their mandated framework for analysis to believe there was reasonable suspicion to search Culver''s home on October 16.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it did not.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that the information supplied by Lt.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that Lt.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in this case we find that the caller''s description of Culver, and activity observable from the street, were not enough to provide a basis to find that the tip provided reason to believe that Culver was engaged in illicit drug activity.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ogden''s call, the probation officers would not have searched on October 16, we find that Lt.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that probation officers violated their clear statutory mandate, we do not reach any constitutional questions.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that because of double jeopardy protection, unless the sentence was due to inadvertent error, defendant could not be resentenced to a longer term for robbery even though the sentence for the assault and battery charge had to be set aside because it was in excess of the statutory maximum.', 'sentencing', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/2315275/', '2315275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that the slate was not “wiped clean” as in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Appellate Division’s judgment barring defendant’s resentencing for felony murder.', 'sentencing', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/2315275/', '2315275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that subject to the trial court''s overriding control of the proceedings, the State "should have the right to make a full showing before the jury whenever it considers such course necessary for the proper presentation of its case.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/2315254/', '2315254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While not condoning all aspects of the prosecutor''s conduct, we conclude that, in the context of the entire trial, it did not cause defendant to be denied a fair trial.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/2315254/', '2315254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the facts in this case, we find that the expert testimony was relevant to Gladys Kelly''s state of mind, namely, it was admissible to show she honestly believed she was in imminent danger of death.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/2315254/', '2315254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for a new trial.', 'general', 'State v. Kelly', 'https://www.courtlistener.com/opinion/2315254/', '2315254') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we conclude that under the right to counsel provision of article I, section 10 of the Iowa Constitution, a misdemeanor defendant has a right to the assistance of counsel when the defendant faces the possibility of imprisonment.', 'general', 'State of Iowa v. Archaletta Latrice Young', 'https://www.courtlistener.com/opinion/2791281/', '2791281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that under the Iowa Constitution, a defendant facing the possibility of imprisonment in a misdemeanor proceeding has a constitutional right to counsel, Young’s uncounseled 2003 misdemeanor conviction cannot be used to enhance her 2012 crime.', 'general', 'State of Iowa v. Archaletta Latrice Young', 'https://www.courtlistener.com/opinion/2791281/', '2791281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the Iowa Constitution, we conclude that a poor person has a right to appointed counsel when a statute authorizes imprisonment unless the defendant validly waives that right.', 'general', 'State of Iowa v. Archaletta Latrice Young', 'https://www.courtlistener.com/opinion/2791281/', '2791281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under article I, section 10 of the Iowa Constitution, an accused in a misdemeanor criminal prosecution who faces the possibility of imprisonment under the applicable criminal statute has a right to counsel.', 'general', 'State of Iowa v. Archaletta Latrice Young', 'https://www.courtlistener.com/opinion/2791281/', '2791281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that they could not.', 'general', 'State of Iowa v. Archaletta Latrice Young', 'https://www.courtlistener.com/opinion/2791281/', '2791281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we reverse the decision of the district court and remand for further proceedings.', 'general', 'State of Iowa v. Archaletta Latrice Young', 'https://www.courtlistener.com/opinion/2791281/', '2791281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we hold that applying ASORA to Doe burdens his fundamental liberty interests and right to procedural fairness arising out of the set-aside granted him in 1994, such that the state must establish a compelling governmental interest.', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that applying ASORA to a person whose conviction was set aside before ASORA became specifically applicable to convictions that were set aside violates the Alaska Constitution''s guarantee of due process.', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because ASORA compels affirmative post-discharge conduct under threat of prosecution, because this conduct is equivalent to that often required by criminal judgments, because this sort of conduct could not be compelled absent a criminal adjudication or its equivalent, because the conviction (since set aside) is the event that triggers these duties, and because the requirement impairs one''s post-set-aside freedom to be let alone, we conclude that it violates Doe''s liberty interests[75] to requ...', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given ASORA''s burden on Doe''s liberty interests and its interference with his settled expectations, we conclude that the Alaska Constitution''s guarantee of due process prevents the state from contradicting the judgment of the superior court and requiring Doe to satisfy ASORA.', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '085 before ASORA became specifically applicable to convictions that were set aside unconstitutionally interferes with the individual''s liberty interests and because the state has failed to establish that this application is justified by a compelling governmental interest, we REVERSE the judgment that upheld ASORA as applied to Doe and REMAND for entry of an order enjoining the state from publishing Doe''s registration information and requiring the state to return all information Doe provided w...', 'general', 'Doe v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2521559/', '2521559') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that a contrary holding would open the door to the assessment in juvenile proceedings of the unrelated costs, fees, and surcharges provided for in the adult criminal system without a clear legislative mandate to do so.', 'general', 'VKE v. State', 'https://www.courtlistener.com/opinion/1891715/', '1891715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 861 (1997), we held that, to the extent that § 5-65-205(c) prevents a defendant from having a jury determine whether he or she is guilty of refusing to submit to a chemical test, the statutory provision unconstitutionally infringes upon the right to jury trial under the Arkansas Constitution.', 'general', 'MacE v. State', 'https://www.courtlistener.com/opinion/2441189/', '2441189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the circuit court on direct appeal, but declare error on cross appeal.', 'general', 'MacE v. State', 'https://www.courtlistener.com/opinion/2441189/', '2441189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that Arkansas’s correct and uniform administration of the criminal law is not in issue.', 'general', 'State v. Banks', 'https://www.courtlistener.com/opinion/2452265/', '2452265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is not.', 'general', 'Rogers v. State', 'https://www.courtlistener.com/opinion/2527119/', '2527119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rogers waived his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we conclude that Rogers received a significant benefit from the plea agreement, and the trial court did not abuse its discretion in failing to consider the agreement as a mitigating factor.', 'plea', 'Rogers v. State', 'https://www.courtlistener.com/opinion/2527119/', '2527119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion in sentencing Rogers.', 'sentencing', 'Rogers v. State', 'https://www.courtlistener.com/opinion/2527119/', '2527119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that (1) Rogers waived his claim that his conviction violated the Indiana constitutional prohibition against
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we find that Rogers’ circumstances fit into the broader general rule that a defendant who pleads guilty pursuant to a plea agreement waives potential claims with respect to the propriety of his conviction on direct appeal.', 'plea', 'Rogers v. State', 'https://www.courtlistener.com/opinion/2527119/', '2527119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not abuse its discretion in deciding that Rogers’ crimes and his remorse were not mitigating factors.', 'general', 'Rogers v. State', 'https://www.courtlistener.com/opinion/2527119/', '2527119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Rogers v. State', 'https://www.courtlistener.com/opinion/2527119/', '2527119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'Self v. State', 'https://www.courtlistener.com/opinion/2634405/', '2634405') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Eldredge', 'https://www.courtlistener.com/opinion/2320216/', '2320216') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Mindful of this admonition, we hold that the conclusion of the jury was not without evidence to sustain it and that the actions of appellant were sufficient to constitute an overt act.', 'general', 'Steve Whitt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061446/', '1061446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A panel of this Court held that it was without active jurisdiction to consider Whitt’s appeal, and consequently dismissed it.', 'dismissal', 'Steve Whitt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061446/', '1061446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this Court may entertain Whitt’s motion to amend his assignment of error.', 'general', 'Steve Whitt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061446/', '1061446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the merits of the appeal, we affirm Whitt’s convictions.', 'general', 'Steve Whitt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061446/', '1061446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'Steve Whitt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061446/', '1061446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989) (en banc), we conclude that the prosecutor''s remarks coupled with the use of unnecessarily graphic photos of the corpse were improper.', 'general', 'Chatmon v. United States', 'https://www.courtlistener.com/opinion/2320585/', '2320585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Where appellant did not preserve the objection, we reverse only for plain error, i.', 'general', 'Chatmon v. United States', 'https://www.courtlistener.com/opinion/2320585/', '2320585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse on this ground, I do not associate myself with Judge Ruiz''s treatment of the issue of the prosecutor''s use of the photographs of the victim in closing argument, which has the character of lengthy dictum.', 'general', 'Chatmon v. United States', 'https://www.courtlistener.com/opinion/2320585/', '2320585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[5]  Because we reverse and remand on the ineffectiveness claim, we need not reach appellant''s other evidentiary and instructional claims relating to the introduction of a photograph with a police identification number or the sufficiency of evidence for an aiding and abetting instruction.', 'ineffective_assistance', 'Chatmon v. United States', 'https://www.courtlistener.com/opinion/2320585/', '2320585') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wilson-Bey, we held that it was error for the trial court to instruct the jury on aiding and abetting liability using the "natural and probable consequences" language that was included in the instruction given in this case because it allowed the jury to convict without finding the necessary mens rea for first-degree murder.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "[o]n the record before us, reasonable jurors could infer and conclude.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that while the evidence was sufficient to convict Jones for second-degree murder, see id.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we declined to grant relief to appellant because we held that appellant did not satisfy the fourth prong of the plain error test.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellants'' other challenges, singly and in the aggregate, do not require reversal, and we affirm their remaining convictions.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons that follow, we conclude that although the prosecutor''s use of subpoenas and payment of fees intended for grand jury witnesses was improper, the trial court did not abuse its discretion in rejecting appellants'' motions for new trial because the abuse did not lead to subornation of perjured testimony that was presented at trial by the prosecutor.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, although we emphasize that the information should have been disclosed before trial, because there was no material prejudice to the defense by the government''s delay in disclosing the transcript of Alemán''s grand jury testimony, nor by the government''s failure to disclose that Alemán had been subject to multiple subpoenas, we conclude that there was no Brady violation requiring reversal.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because appellants have not shown a reasonable probability of a different outcome, we conclude that there is no Brady violation requiring reversal.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s admission of the statements and *76 denial of the motions for severance were not an abuse of discretion.', 'general', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in denying, without a hearing, Salamanca''s motion for a new trial based on ineffectiveness of trial counsel.', 'ineffective_assistance', 'Perez v. United States', 'https://www.courtlistener.com/opinion/2321578/', '2321578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Cothran v. Brown', 'https://www.courtlistener.com/opinion/1303320/', '1303320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse the Court of Appeals’ application of judicial estoppel.', 'general', 'Cothran v. Brown', 'https://www.courtlistener.com/opinion/1303320/', '1303320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant''s right to challenge a prior conviction that the State intends to use to enhance a sentence is not limited solely to a claim that the conviction was obtained in violation of right to counsel.', 'sentencing', 'State v. Boskind', 'https://www.courtlistener.com/opinion/2332901/', '2332901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant''s collateral challenge to a prior conviction upon which the State relies to enhance a sentence is not limited solely to claims of invalidity based upon a violation of the right to counsel.', 'sentencing', 'State v. Boskind', 'https://www.courtlistener.com/opinion/2332901/', '2332901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In fact, we held that the defendant could be required to give exactly such evidence in Brown, 165 Vt.', 'general', 'State v. Boskind', 'https://www.courtlistener.com/opinion/2332901/', '2332901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the enhanced sentences imposed upon the respective defendants and hold that defendants, should they challenge convictions on the basis of a claim that the trial court did not comply with V.', 'sentencing', 'State v. Boskind', 'https://www.courtlistener.com/opinion/2332901/', '2332901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that they were not.', 'general', 'Griffith v. State', 'https://www.courtlistener.com/opinion/2335950/', '2335950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, when the appellant requested his attorney, the State had not proceeded far enough in its investigation or prosecution of him to implicate such rights.', 'general', 'Griffith v. State', 'https://www.courtlistener.com/opinion/2335950/', '2335950') ON CONFLICT DO NOTHING;
