INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that there was no
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'as authority for the proposition that any invocation of the right to counsel is inadmissible as evidence of guilt: “We therefore hold that evidence of one’s invocation of the right to counsel is inadmissible as evidence of guilt .', 'general', 'Griffith v. State', 'https://www.courtlistener.com/opinion/2335950/', '2335950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that evidence of one’s invocation of the right to counsel is inadmissible as evidence of guilt .', 'general', 'Griffith v. State', 'https://www.courtlistener.com/opinion/2335950/', '2335950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), where we held that a defendant’s act of tossing several rocks of cocaine to the ground as a police officer approached him did not constitute an act of suppression or concealment, but rather an act of abandonment.', 'suppression', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2634805/', '2634805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we held that a sentencing court should not find an aggravating factor based on conduct for which the defendant is being separately sentenced.', 'sentencing', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2634805/', '2634805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained here, we conclude that the superior court properly admitted evidence that N.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2634805/', '2634805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that Anderson’s conduct of tossing the articles from the car did not constitute the crime of evidence tampering, and thus his conviction for this crime must be reversed.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2634805/', '2634805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the position espoused by the State in this appeal is the correct one.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2634805/', '2634805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that we must refine the definition of “remove” that we offered in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Anderson’s conviction for evidence tampering must be reversed.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2634805/', '2634805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the least serious crimes for which he was being sentenced), we conclude that the reversal of this conviction does not affect our consideration and resolution of Anderson’s claim that his composite sentence is excessive.', 'sentencing', 'Anderson v. State', 'https://www.courtlistener.com/opinion/2634805/', '2634805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Blackmer', 'https://www.courtlistener.com/opinion/2328910/', '2328910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful consideration of the record, we hold that the ruling of the Superior Court was erroneous as a matter of law.', 'general', 'State v. Maxwell', 'https://www.courtlistener.com/opinion/1932932/', '1932932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 908 (1973), this Court held that probable cause can be established by reports of witnesses provided that the reports are sufficiently corroborated by other facts within the officer''s knowledge.', 'probable_cause', 'State v. Maxwell', 'https://www.courtlistener.com/opinion/1932932/', '1932932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the decision to proceed by stipulation was a matter of trial tactics and strategy.', 'general', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying upon those rulings as guidance, we held that defense counsel may generally waive a defendant’s right of confrontation by entering into an evidentiary stipulation where two elements are met: (1) the defendant does not object;', 'general', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon this rationale, we held that departure from the general rule that defense counsel may waive a defendant’s right of confrontation is warranted only in those instances where: (1) the State’s entire case is presented by stipulation and defendant fails to preserve a defense;', 'general', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In rejecting this argument, we held that the technician’s statement to the first officer at the scene that the video appeared to be child pornography provided a sufficient description of the file’s contents.', 'general', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that defendant did not object to the entry of the stipulation.', 'general', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the circuit court properly denied defendant’s motion to quash and suppress.', 'suppression', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court and remand this cause to that court for further proceedings consistent with this opinion.', 'general', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the judgment of the appellate court.', 'general', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed.', 'general', 'People v. Clendenin', 'https://www.courtlistener.com/opinion/2481533/', '2481533') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2007), where we held that a misdemeanor driving under the influence offense, which carries a penalty of up to six months jail time, falls under the category of an offense subject to the exigent circumstances doctrine.', 'general', 'State v. DeWitt', 'https://www.courtlistener.com/opinion/2633003/', '2633003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If those findings are so supported and the conclusions follow therefrom and if the district court affirmed the magistrate’s decision, we affirm the district court’s decision as a matter of procedure.', 'general', 'State v. DeWitt', 'https://www.courtlistener.com/opinion/2633003/', '2633003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a charging instrument, be it an indictment, complaint, or information, must include all "allegations, which if proved, would result in the application of a statute enhancing the penalty of the crime committed.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[14] Consistent with this requirement, we held that the "better rule is to include in the indictment the allegations, which if proved, would result in application of a statute enhancing the penalty for the crime committed.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The prosecution concluded that if this court holds "that the trier of fact is constitutionally required to make the `necessary for the protection of the public'' finding[,]" we should also hold that the court "has the inherent power to empanel a jury to make that determination as part of a sentencing proceeding on remand where a defendant''s sentence has been vacated due to an Apprendi procedural error.', 'sentencing', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Maugaotega II, this court held that HRS § 706-662 (Supp.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8]  Similar to the prosecution, the dissent noted that (1) in Janto this court held that the trier of fact, i.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wilson, this court held that the defendant, after being arrested for driving under the influence of intoxicating liquor, was not accurately informed of the consequences of taking a blood alcohol concentration (BAC) test because the officer informed the defendant that his driving privileges would be revoked for three months if he took the test and failed when in fact he would be subject to revocation of three months to one year if he failed the test.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, in light of the legislature''s expressed intent in Act 230 of the 2006 legislative session, see supra notes 3 and 4, and the legislature''s then-current failure to reach agreement on the creation of a jury-based system,[25] we concluded that it would
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the constitutional prohibition against ex post facto measures is not offended by the plain language of the new law.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse defendant’s conviction and sentence and remand for a new trial.', 'sentencing', 'State v. Taffaro', 'https://www.courtlistener.com/opinion/2335008/', '2335008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we reverse the judgment of the Appellate Division, vacate defendant’s conviction and sentence, and remand for a new trial.', 'sentencing', 'State v. Taffaro', 'https://www.courtlistener.com/opinion/2335008/', '2335008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We uphold a guilty verdict when we conclude that a reasonable jury could have concluded that the defendant was guilty beyond a reasonable doubt.', 'general', 'DELAY-WILSON v. State', 'https://www.courtlistener.com/opinion/2342077/', '2342077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, evaluating the evidence in the light most favorable to the jury''s verdict, the jury could have found Delay-Wilson guilty beyond a reasonable doubt.', 'general', 'DELAY-WILSON v. State', 'https://www.courtlistener.com/opinion/2342077/', '2342077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And, as in our analysis of her bad check convictions, we conclude that a reasonable jury could find that Delay Wilson acted with the intent to deprive Key Bank of property worth more than $500.', 'general', 'DELAY-WILSON v. State', 'https://www.courtlistener.com/opinion/2342077/', '2342077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the May 5, 2009 opinion of the Court of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse the Court of Appeals opinion, affirm the trial court’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[29] We hold that the parking and sidewalk area outside the Exxon station was a public place.', 'general', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Murphy, we held that the collateral-estoppel inquiry involved a two-part analysis: (1) determining exactly what facts were necessarily decided in the first proceeding, and (2) determining whether those necessarily decided facts constitute essential elements of the offense in the second trial.', 'general', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[75] We held that this assumption was incorrect.', 'general', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that, when the validity of an arrest or detention is an element of the charged offense, litigating the validity of the seizure as a suppression issue is inappropriate.', 'suppression', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After noting the distinctions between double jeopardy and "collateral estoppel,"[36] we held that if a jury determines a punishment-phase special issue in the defendant''s favor, "the doctrine of collateral estoppel bars the State from relitigating it in a second trial"[37] and affirmed the Court of Appeals.', 'general', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[83] We do not often say what standard applies in a motion-to-suppress setting, and we are unaware of any cases explicitly stating the State''s standard of proof in establishing reasonable suspicion,[84] but we conclude that the appropriate standard is the one that applies to most[85] constitutional suppression issues: preponderance of the evidence.', 'suppression', 'York v. State', 'https://www.courtlistener.com/opinion/2541647/', '2541647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, viewing the totality of the evidence and inferences in a light most favorable to the verdict, the jury could have reasonably inferred that appellant knowingly had care, custody, control, or management of the ten pornographic images of unknown children found on the free space of his computer.', 'general', 'Wise v. State', 'https://www.courtlistener.com/opinion/2542806/', '2542806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although these two general approaches are instructive in explaining the difficulties of establishing criminal intent in the possession of computer pornography, we conclude that each case must be analyzed on its own facts.', 'general', 'Wise v. State', 'https://www.courtlistener.com/opinion/2542806/', '2542806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals and render a judgment affirming the trial court.', 'general', 'Wise v. State', 'https://www.courtlistener.com/opinion/2542806/', '2542806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In contrast to the ICA''s opinion, we hold that, inasmuch as Locquiao adduced sufficient evidence at trial to warrant an ignorance-or-mistake-of-fact instruction, the circuit court''s refusal so to instruct was not harmless beyond a reasonable doubt.', 'general', 'State v. Locquiao', 'https://www.courtlistener.com/opinion/2543862/', '2543862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, based on the totality of the foregoing circumstances, we hold that the ICA did not gravely err in holding that Kim was acting as a private citizen in connection with the events with which Locquiao was charged and that, therefore, his search and/or seizure of Locquiao was not constrained by the fourth amendment to the United States Constitution and article 1, section 7 of the Hawai`i Constitution, see supra note 6.', 'search_seizure', 'State v. Locquiao', 'https://www.courtlistener.com/opinion/2543862/', '2543862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the plaintiffs'' appeal, we hold that the circuit court erred in apportioning liability between the DOE and Norton and, therefore, that the DOE is liable to the plaintiffs for the full extent of their damages.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing discussion, we hold that, where a plaintiff''s negligence claim against the State seeks to hold the State vicariously liable for a state employee''s "assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights" under the doctrine of respondeat superior, the State is, pursuant to HRS ง 662-15(4), immune from the plaintiff''s claim.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the duty of care that the DOE owes to students and their parents is, on a general level, a duty to take whatever precautions are necessary reasonably to ensure the safety and welfare of the children entrusted to its custody and control against harms that the DOE anticipates, or reasonably should anticipate.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'as she claimed, we hold that the DOE should have reasonably anticipated that Norton posed a potential threat to students and, therefore, that it was reasonably foreseeable that he would molest other students.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we hold that it was unreasonable at that point for the DOE to have failed specifically to supervise Norton and to restrict him from issuing hall passes and "hugging" students.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not clearly err in finding that the DOE''s negligence legally caused the plaintiffs'' various psychological injuries.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 519-20 ("We hold that serious mental distress may be found where a reasonable [person], normally constituted, would be unable to adequately cope with the mental stress engendered by the circumstances of the case.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Jane Roes, for example, we held that "exposure to HIV-positive blood `involve[s] circumstances which guarantee the genuineness and seriousness of the claim''" (quoting Rodrigues, 52 Haw.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Miller, this court held that the State "has a duty of reasonably supervising the public school students of Hawaii during their required attendance and presence at school and while the students are leaving school immediately after the school day is over.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this court held that rules and regulations that the DOE had adopted "provid[ed] the necessary guidelines and requirements for the personnel of the State educational system to perform its supervisory duties.', 'general', 'Mr. & Mrs. Doe Parents No. 1 v. State, Department of Education', 'https://www.courtlistener.com/opinion/2544598/', '2544598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'to this case,” (emphasis added), we conclude that defendant’s Sixth Amendment right to counsel had not yet attached when he was questioned by the detectives.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2395363/', '2395363') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant was dangerous to only some, but not all, of her own newborn children, which she would not likely have during her child-bearing years in prison, so the jury could not rationally find that the defendant was a future danger.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] In Berry, we held that the evidence was legally insufficient to establish that there was a probability that the defendanta mother who had killed one new-born child and abandoned a second onewould commit criminal acts of violence that would constitute a continuing threat to society.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[3] Using that legal standard, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), we held that "[t]he procedural mechanisms for reviewing that conviction are not a vested and substantive right.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the Berry case, this Court held that the jury was irrational to conclude that there was a probability that Kinesha Berry would be a future danger.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[13]  We have listened to appellant''s recorded statement, and while we find that a word here or there might be inaudible, we do not find any inaudible portion of appellant''s recorded statement is necessary to the resolution of this appeal or to any understanding of the context of the exchange between appellant and the police.', 'general', 'Lucio v. State', 'https://www.courtlistener.com/opinion/2546978/', '2546978') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the approach followed by the majority of the Federal Circuits favoring a broader application of the RICO conspiracy provision, is the better reasoned approach and the one, therefore, to adopt.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/2400931/', '2400931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*143 Applying the relationship test to this case, we hold that relatedness, as defined in N.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/2400931/', '2400931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the New Jersey RICO statute requires a showing that the predicate acts are related, but does not require continuity.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/2400931/', '2400931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the application of New Jersey''s statute is not limited to legitimate enterprises.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/2400931/', '2400931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986), where we held that procedural irregularities in a grand jury proceeding are rendered harmless where defendant is ultimately found guilty by petit jury.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/2400931/', '2400931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, we conclude that the higher degree of specificity in the New Jersey RICO statute, as opposed to its Federal counterpart, renders defendant''s claim of unconstitutional "vagueness" meritless.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/2400931/', '2400931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the issues they raise, we affirm.', 'general', 'State v. Ball', 'https://www.courtlistener.com/opinion/2400931/', '2400931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor will we reverse absent a showing of prejudice.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2352172/', '2352172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm his conviction, the question of his pretrial bond is moot.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2352172/', '2352172') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1155 (1989), in which we held that the defendant, threatened with deportation as a result of his conviction, “was not precluded by the phrase ‘imprisoned in a penitentiary’ from petitioning” under the Act, notwithstanding the fact that he had completed his probation.', 'general', 'People v. Rajagopal', 'https://www.courtlistener.com/opinion/2036104/', '2036104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm.', 'general', 'People v. Rajagopal', 'https://www.courtlistener.com/opinion/2036104/', '2036104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the circuit court dismissing defendant’s postconviction petition.', 'dismissal', 'People v. Rajagopal', 'https://www.courtlistener.com/opinion/2036104/', '2036104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Thus, we hold that the circuit court did not abuse its discretion in rejecting Jester’s instruction.', 'general', 'Jester v. State', 'https://www.courtlistener.com/opinion/2355688/', '2355688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'thus, we hold that the circuit court was correct in refusing it.', 'general', 'Jester v. State', 'https://www.courtlistener.com/opinion/2355688/', '2355688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 536, 539 (1999), this court held the following:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his conviction.', 'general', 'Jester v. State', 'https://www.courtlistener.com/opinion/2355688/', '2355688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm.', 'general', 'Jester v. State', 'https://www.courtlistener.com/opinion/2355688/', '2355688') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the town clerk''s decision to replace, or not to replace, the previously removed handrail was not a discretionary decision.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To support this conclusion, we held that "[in] cases where the questioned conduct has little or no purely governmental content but instead resembles decisions or activities carried on by people generally, there is an objective standard for judgment by the courts and the doctrine of discretionary immunity does not bar the action.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 44] We conclude that any inference that the lack of an edge line was an actual cause of the accident would amount to nothing more than speculation on the part of the jury.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 45] For the foregoing reasons, we conclude that MDOT was entitled to judgment as a matter of law in its favor.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Darling, we found that the commissioner and superintendent of a state mental health facility were entitled to discretionary function immunity from claims that they "negligently devised and oversaw [the facility''s] policies governing the commitment and release of patients.', 'general', 'Tolliver v. Department of Transportation', 'https://www.courtlistener.com/opinion/2357315/', '2357315') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Kasper', 'https://www.courtlistener.com/opinion/2363912/', '2363912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a charge of multiple counts of first degree arson for multiple intended victims based on a single fire constitutes an unconstitutional multiplicity prohibited by the Double Jeopardy Clause.', 'general', 'Handy v. State', 'https://www.courtlistener.com/opinion/2365144/', '2365144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the weight of the reasoning in the case law is against charging multiple counts of arson based upon multiple victims.', 'general', 'Handy v. State', 'https://www.courtlistener.com/opinion/2365144/', '2365144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no basis for a mistrial in this case.', 'mistrial', 'Handy v. State', 'https://www.courtlistener.com/opinion/2365144/', '2365144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Superior Court did not abuse its discretion in refusing to grant a mistrial for the courtroom incident involving Handy’s former teacher.', 'mistrial', 'Handy v. State', 'https://www.courtlistener.com/opinion/2365144/', '2365144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Superior Court and remand to vacate one of the two sentences for arson first degree and to resentence the defendant on the other charge.', 'sentencing', 'Handy v. State', 'https://www.courtlistener.com/opinion/2365144/', '2365144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part, reverse in part, and remand to the Superior Court for sentencing consistent with this opinion.', 'sentencing', 'Handy v. State', 'https://www.courtlistener.com/opinion/2365144/', '2365144') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though the sentence imposed is severe, we conclude that Key suffered no prejudice to any interest protected by a speedy sentencing right under the sixth amendment.', 'sentencing', 'Key v. State', 'https://www.courtlistener.com/opinion/2372523/', '2372523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that even under a “statutory elements” approach, the trial court is not obligated to charge the jury with an included offense unless there is a rational basis for such an instruction in the evidence.', 'general', 'Lilly v. State', 'https://www.courtlistener.com/opinion/2103477/', '2103477') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Mason’s conviction under NY PL § 220.', 'general', 'Curtis Lee Mason v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/2793424/', '2793424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we hold that Mason’s conviction under NY PL § 220.', 'general', 'Curtis Lee Mason v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/2793424/', '2793424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'parties, and viewing the facts in the light most favorable to the Commonwealth, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that although the wording of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Mason’s conviction and remand for a new trial, if the Commonwealth
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 609, this court held that there must be something in a criminal statute to indicate where the line is to be drawn between trivial and substantial things so that erratic arrests and convictions for trivial acts and omissions will not occur.', 'general', 'State v. Downey', 'https://www.courtlistener.com/opinion/2029134/', '2029134') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), this court held that the phrase “for a felony” as used in AS 11.', 'general', 'LeFever v. State', 'https://www.courtlistener.com/opinion/2613320/', '2613320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the escape statute applied because the defendant had escaped from official detention "for” the original felony of which he had been convicted.', 'general', 'LeFever v. State', 'https://www.courtlistener.com/opinion/2613320/', '2613320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that the legislature intended adjudicated delinquents to be subject to the unlawful evasion statutes.', 'general', 'LeFever v. State', 'https://www.courtlistener.com/opinion/2613320/', '2613320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the unlawful evasion
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM the conviction.', 'general', 'LeFever v. State', 'https://www.courtlistener.com/opinion/2613320/', '2613320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1289), we conclude that neither the Arizona nor the United States Constitution entitles a defendant facing a charge of judicial interference to a trial of that charge by a jury.', 'general', 'Ottaway v. Smith', 'https://www.courtlistener.com/opinion/2570303/', '2570303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons that follow, we affirm.', 'general', 'Ottaway v. Smith', 'https://www.courtlistener.com/opinion/2570303/', '2570303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 17 We affirm the municipal court’s denial of Ottaway’s request for a jury trial on the complaint against him and the superior court’s denial of special-action relief.', 'general', 'Ottaway v. Smith', 'https://www.courtlistener.com/opinion/2570303/', '2570303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 3 We hold that a trial on the charge of violating section 28-3473(B) (driving on a DUI suspended driver''s license) is not jury eligible.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/2570469/', '2570469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 29 Applying this test to the violation of section 28-3473(B) (driving on a license suspended for violation of the DUI statute), we hold that the offense is not linked to any which would have been jury eligible at common law, that penalties available for the offense do not rise to the level of seriousness as would mandate a jury trial, and that the offense does not implicate the moral element because it is neither a crime of moral turpitude nor a crime which may result in grave consequences.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/2570469/', '2570469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Compare, for example, Rothweiler, in which this court held that the charge of driving under the influence entitles one to a jury trial, with Strohson, in which this court held that a charge of domestic violence assault does not entitle one to a jury trial.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/2570469/', '2570469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that that circuit court’s actions did not constitute an abuse of discretion.', 'general', 'Beck v. State', 'https://www.courtlistener.com/opinion/2455723/', '2455723') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Neither issue has merit, and we affirm the decision of the circuit court.', 'general', 'Beck v. State', 'https://www.courtlistener.com/opinion/2455723/', '2455723') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Because we must give meaning to the word "intended" in the facilitation portion of § 13-1805(I), Superior Court, we conclude that, before a person may be convicted of the class four offense of "facilitated shoplifting," the state must not only prove the elements of shoplifting, as defined by § 13-1805(A), but the additional element that the person entered the store with something he or she intended to facilitate the shoplifting.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2571758/', '2571758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, although we agree with Brown that the facilitation portion of § 13-1805(I) creates a greater offense to the lesser offense of shoplifting under § 13-1805(A) and that he was entitled to the lesser-included offense instruction prescribed by LeBlanc, we conclude that the trial court''s instruction and interrogatory neither prejudiced Brown nor resulted in reversible error.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/2571758/', '2571758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm Brown''s conviction and sentence.', 'sentencing', 'State v. Brown', 'https://www.courtlistener.com/opinion/2571758/', '2571758') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the summary proceeding that is contemplated by West Virginia Code § 15-12-2a for the purpose of making a determination of whether a sex offender qualifies as a sexually violent predator within the meaning of the Act is intended to be held in conjunction with the sentencing phase of a criminal offense.', 'sentencing', 'State v. Myers', 'https://www.courtlistener.com/opinion/2506044/', '2506044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a summary proceeding pursuant to West Virginia Code § 15-12-2a may be initiated at any point prior to the offender’s release from prison for the purpose of making this determination.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/2506044/', '2506044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the trial court committed error in granting the prosecutor’s motion to permit the State to proceed with a summary proceeding and further in making the actual determination that Appellant was a sexually violent predator subsequent to his release from prison.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/2506044/', '2506044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our careful review of this matter, we find that the trial court committed error by holding the summary proceeding required to make a determination of whether a person is a sexually violent predator after Appellant had completed his period of incarceration.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/2506044/', '2506044') ON CONFLICT DO NOTHING;
