INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held “the defendant may offer any facts relevant to the question of the prosecutor’s discriminatory intent to satisfy this burden.', 'general', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, “there is not a per se rule that a certain number or percentage of the challenged jurors must be black in order for the court to conclude a prima facie case has been made out.', 'general', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held the defendant’s reliance on bare statistics to support a prima facie case of race discrimination was misplaced.', 'general', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held the trial judge had nothing from which to draw an inference of purposeful discrimination.', 'general', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In contrast, this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held “[t]he presumption is that a witness on oath testifies honestly until the contrary is shown.', 'general', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'even though the challenged juror sat on a similar case the previous day involving the same witness and found the witness’ testimony convincing, this Court held this “does not of itself make him partial.', 'general', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held a contemporaneous objection is required to preserve review of errors in both phases of a capital trial.', 'general', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held the testimony of four family members during the guilt phase was not victim-impact evidence because their testimony was very brief, non-dramatic, and recounted facts about the crime scene and elements of the state’s | Si&gt;', 'general', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of the law and evidence, we find none of the assignments of error constitute reversible error and therefore, we affirm defendant’s conviction and sentence.', 'sentencing', 'State v. Dorsey', 'https://www.courtlistener.com/opinion/2486030/', '2486030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Woodson v. State', 'https://www.courtlistener.com/opinion/2523527/', '2523527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 327), we held that a defendant may not seek to unilaterally reduce his sentence while holding the State to its part of the bargain {id.', 'sentencing', 'People v. Absher', 'https://www.courtlistener.com/opinion/2523970/', '2523970') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the “shall submit” language used in that provision, we held that it did not constitute a prospective consent, as it only charged the probationer with the duty to submit to a search when directed to do so, and she retained an element of choice as to whether to comply with the condition or face possible revocation of her probation.', 'general', 'People v. Absher', 'https://www.courtlistener.com/opinion/2523970/', '2523970') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Unlike in Lampitok where we held that the search condition “affirmatively required [the] probation officer to ask [the probationer’s] consent” to a search limited to verify her compliance with conditions of her probation (id.', 'general', 'People v. Absher', 'https://www.courtlistener.com/opinion/2523970/', '2523970') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that in the case of an open plea, because the State offers the defendant no inducements to plead guilty, defendants who enter such pleas may challenge their sentences without being required to also withdraw their guilty pleas.', 'sentencing', 'People v. Absher', 'https://www.courtlistener.com/opinion/2523970/', '2523970') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that defendant waived his fourth amendment rights by freely agreeing to the suspicionless search condition set forth in article 10(c) of his probation order, we need not address the remainder of the State’s arguments in support of its position that the search was valid.', 'search_seizure', 'People v. Absher', 'https://www.courtlistener.com/opinion/2523970/', '2523970') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Absher', 'https://www.courtlistener.com/opinion/2523970/', '2523970') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under the specific facts in this appeal, defendant’s agreement to the suspicionless search condition in article 10(c) of his probation order constituted prospective consent.', 'general', 'People v. Absher', 'https://www.courtlistener.com/opinion/2523970/', '2523970') ON CONFLICT DO NOTHING;
