INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we conclude that the defendant is not entitled to withdraw his plea on the basis of his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we conclude that the defendant is not entitled to withdraw his plea on the basis of his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the defendant was entitled to an evidentiary hearing on the basis of his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals, although on different grounds.', 'general', 'State v. Hoppe', 'https://www.courtlistener.com/opinion/1283256/', '1283256') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals, although on different grounds, affirming the circuit court''s judgment and order.', 'general', 'State v. Hoppe', 'https://www.courtlistener.com/opinion/1283256/', '1283256') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that in the case of a lawful custodial arrest a full search of the person is not only an exception to the warrant requirement of the Fourth Amendment, but is also a ‘reasonable’ search under that Amendment.', 'search_seizure', 'Smallwood v. State', 'https://www.courtlistener.com/opinion/2493191/', '2493191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the authority to conduct a full field search as incident to an arrest was a ‘bright-line rule,’ which was based on the concern for officer safety and destruction or loss of evidence, but which did not depend in every case upon the existence of either concern.', 'general', 'Smallwood v. State', 'https://www.courtlistener.com/opinion/2493191/', '2493191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2009), relied on by the State, is one of the only eases we found that addresses photographs found on cell phones.', 'general', 'Smallwood v. State', 'https://www.courtlistener.com/opinion/2493191/', '2493191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that dismissal was proper.', 'dismissal', 'People v. Collins', 'https://www.courtlistener.com/opinion/2038942/', '2038942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 486], where similar allegations of misrepresentations of counsel as to sentence were made, we held that dismissal of the petition without a hearing was improper;', 'dismissal', 'People v. Collins', 'https://www.courtlistener.com/opinion/2038942/', '2038942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Boclair, we held that it would be a "miscarriage of justice" for a meritorious claim of actual innocence to evade judicial review because of a procedural deficiency in the post-conviction petition.', 'general', 'People v. Collins', 'https://www.courtlistener.com/opinion/2038942/', '2038942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 697 (1970), this court held that when a pro se post-conviction petitioner''s claim of ineffective assistance of counsel is based on an attorney-client conversation, the only supporting affidavit required is the defendant''s own.', 'ineffective_assistance', 'People v. Collins', 'https://www.courtlistener.com/opinion/2038942/', '2038942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that this would be improper:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 927 (1979), this court held that "[u]nless conceded by the defendant, the state is required to show, by evidence satisfactory to the court, the fact of the defendant''s prior conviction, as well as the fact of his [or her] representation by counsel, or the waiver thereof, at the time of his [or her] prior conviction.', 'general', 'State v. Heggland', 'https://www.courtlistener.com/opinion/2514968/', '2514968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The ICA affirmed the trial court, stating that "[b]ased on the record, we conclude that the evidence reasonably satisfied the court.', 'general', 'State v. Heggland', 'https://www.courtlistener.com/opinion/2514968/', '2514968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the ICA''s analysis of the term "maximum term of imprisonment possible" in HRS § 706-606.', 'general', 'State v. Heggland', 'https://www.courtlistener.com/opinion/2514968/', '2514968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these statements were admissible because they were all statements of Richardson employees concerning matters within the course and scope of their employment with Richardson during the existence of their employment and are exceptions to the hearsay rule.', 'general', 'Azar v. Richardson Greenshields Sec., Inc.', 'https://www.courtlistener.com/opinion/1793831/', '1793831') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although Azar alleges there was an agreement between himself and Gill that Richardson would make margin calls within twenty-four hours of need for additional margin, we find that Azar and Richardson signed a standard customer trading agreement which did not include a provision regarding this subject.', 'general', 'Azar v. Richardson Greenshields Sec., Inc.', 'https://www.courtlistener.com/opinion/1793831/', '1793831') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse in part and affirm in part.', 'general', 'Azar v. Richardson Greenshields Sec., Inc.', 'https://www.courtlistener.com/opinion/1793831/', '1793831') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Addressing Azar''s complaint in reverse order, we affirm the trial court''s ruling as to count IV of the amended complaint.', 'general', 'Azar v. Richardson Greenshields Sec., Inc.', 'https://www.courtlistener.com/opinion/1793831/', '1793831') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in the absence of a designated culpable state of mind in Hawai''i Revised Statutes (HRS) § 291-4.', 'general', 'State v. Vliet', 'https://www.courtlistener.com/opinion/2524494/', '2524494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that plain error was not committed by the court in admitting, pursuant to Hawaii Rules of Evidence (HRE) Rule 702 (1993), expert evidence of the “Widmark
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that admission of Wong’s BAC opinion did not implicate the plain error standard.', 'general', 'State v. Vliet', 'https://www.courtlistener.com/opinion/2524494/', '2524494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There being no reversible error, we affirm Defendant’s September 9, 1999 judgment of conviction and sentence for habitually driving under the influence of intoxicating liquor or drugs, in violation of HRS § 291-4.', 'sentencing', 'State v. Vliet', 'https://www.courtlistener.com/opinion/2524494/', '2524494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the court’s September 9, 1999 judgment of conviction and sentence.', 'sentencing', 'State v. Vliet', 'https://www.courtlistener.com/opinion/2524494/', '2524494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'DP v. State', 'https://www.courtlistener.com/opinion/2496732/', '2496732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '683 (1947), this Court held that courts may not inquire into the sufficiency, legality, or character of evidence presented to a grand jury.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1834604/', '1834604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the testimony of Beasley and Gallon was properly admitted.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1834604/', '1834604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Faretta and Johnson do not apply to the situation before us and that the trial judge had no obligation to conduct a Faretta inquiry since Anderson was represented by counsel.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1834604/', '1834604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We affirm.', 'general', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1834604/', '1834604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the conviction and the sentence of death.', 'sentencing', 'Anderson v. State', 'https://www.courtlistener.com/opinion/1834604/', '1834604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Division One of this court held that ACRA “does not preempt a tort action for wrongful discharge.', 'general', 'Taylor v. Graham County Chamber of Commerce', 'https://www.courtlistener.com/opinion/2515912/', '2515912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because that ruling was consistent with and mandated by the EPA, we affirm.', 'general', 'Taylor v. Graham County Chamber of Commerce', 'https://www.courtlistener.com/opinion/2515912/', '2515912') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence of record satisfies each of the elements of criminal contempt, we affirm judgments of sentence.', 'sentencing', 'Commonwealth v. Owens', 'https://www.courtlistener.com/opinion/1520716/', '1520716') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Loring, we conclude that Inman was not sufficiently prejudiced to warrant the grant of a mistrial.', 'mistrial', 'State v. Inman', 'https://www.courtlistener.com/opinion/2510122/', '2510122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the facts of the instant case, we find that Inman''s guilty plea was unconditional.', 'plea', 'State v. Inman', 'https://www.courtlistener.com/opinion/2510122/', '2510122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Inman''s guilty plea and sentences.', 'sentencing', 'State v. Inman', 'https://www.courtlistener.com/opinion/2510122/', '2510122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that there is an actionable public policy tort in Alaska for retaliation against witnesses in legal proceedings.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that AS 09.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Anderson (Anderson I) we held that a wrongfully discharged employee''s "lost earnings should be measured by the amount and duration of the contract that [he or] she expected to have with [the employer]," which *818 in that case was one year.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that APC did not adequately preserve the issue it argues on appeal and that there was no reversible error.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[33] To the extent APC objected to giving a mixed-motive instruction instead of a pretext instruction, we conclude that no error occurred.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the extent APC objected to the incompleteness of the mixed-motive instruction, we conclude that APC did not distinctly raise this issue at trial.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[43] As a result, we conclude that it was not an abuse of discretion to exclude Bailey''s testimony that Reust''s position had been eliminated.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that AS 09.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[7] We concluded that the State of Alaska has explicit public policies that protect employees who make workers'' compensation claims and who serve as whistleblowers.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State we concluded that because interests in "unlimited [punitive] damages are merely economic, the State''s objectives need only be `legitimate''not `compelling''to justify the State''s action.', 'general', 'Reust v. Alaska Petroleum Contractors, Inc.', 'https://www.courtlistener.com/opinion/2510862/', '2510862') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2000), this Court held that an officer''s request to search a car was lawful where the request was made before the issuance of the traffic citation had been completed and such request lengthened the process only by a second or two.', 'general', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d at 306-07, this Court held that it was permissible for one officer to question a vehicle''s driver about drugs and weapons and to take a drug dog around the car while another officer was busy checking with dispatch on the driver''s status and writing out a traffic citation.', 'general', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of all these facts, we conclude that the use of the drug dog impermissibly extended the duration of the detention authorized by Terry.', 'general', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the probable cause to search the interior of Aguirre''s pickup truck, which was secured by the drug detection dog''s alert on the exterior of the vehicle, was itself acquired through an unconstitutional expansion of the traffic stop.', 'probable_cause', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the district court granting Aguirre''s motion to suppress.', 'suppression', 'State v. Aguirre', 'https://www.courtlistener.com/opinion/2518428/', '2518428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*151 Based on the foregoing, we find that the DPA''s questions and remarks did not constitute misconduct.', 'general', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court''s judgment of conviction and sentence.', 'sentencing', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the foregoing considerations, we affirm the denial of Hauge''s motion to suppress on the narrow ground that Hauge''s blood was initially drawn pursuant to a lawful warrant for DNA comparison and identification purposes in connection with the robbery investigation and that the blood sample was only used in connection with the burglary investigation giving rise to the present matter for the same DNA comparison and identification purposes.', 'suppression', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we affirm the circuit court''s judgment of conviction and sentence.', 'sentencing', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the circuit court''s improper comment on the evidence did not amount to reversible error or grounds for a new trial, inasmuch as the court''s jury instruction was sufficiently curative.', 'jury_instruction', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse Baird’s conviction for driving while suspended with a prior conviction and remand with instructions for the trial court to modify the judgment from a Class A misdemeanor to a Class A infraction.', 'general', 'Baird v. State', 'https://www.courtlistener.com/opinion/2527660/', '2527660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse Baird’s conviction for driving while suspended with a prior conviction as a Class A misdemeanor because the evidence is insufficient to sustain that conviction, but we remand for the trial court to enter judgment on the count of driving while suspended as a Class A infraction.', 'general', 'Baird v. State', 'https://www.courtlistener.com/opinion/2527660/', '2527660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Amalfitano v. State', 'https://www.courtlistener.com/opinion/2527735/', '2527735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Amalfitano v. State', 'https://www.courtlistener.com/opinion/2527735/', '2527735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 657 (1977), we held that guilty knowledge is an element of the crime of contributing to the delinquency of a minor, irrespective of the statute’s wording.', 'general', 'State v. Dunn', 'https://www.courtlistener.com/opinion/1225444/', '1225444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon careful examination of the opening remark, we conclude that while the prosecutor’s remark might have been potentially misleading in some sense, it neither clearly prejudices the accused nor results in a manifest injustice.', 'general', 'State v. Dunn', 'https://www.courtlistener.com/opinion/1225444/', '1225444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the closing remarks objected to did not prejudice the defendant or result in manifest injustice and, hence, we will not interfere with the trial court’s ruling on this point.', 'general', 'State v. Dunn', 'https://www.courtlistener.com/opinion/1225444/', '1225444') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing a trial court''s decision for an abuse of discretion, we reverse only where the decision is clearly against the logic and effect of the facts and circumstances.', 'general', 'Delagrange v. State', 'https://www.courtlistener.com/opinion/2529395/', '2529395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and remand.', 'general', 'Delagrange v. State', 'https://www.courtlistener.com/opinion/2529395/', '2529395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm the judgment of the trial court and remand for further proceedings.', 'general', 'Delagrange v. State', 'https://www.courtlistener.com/opinion/2529395/', '2529395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, this Court held that Bec-kum’s related allegation on appeal was proeedurally barred.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2532058/', '2532058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2532058/', '2532058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the introduction of the document into the deposition constituted an introduction of the document into the presence of the court, warranting a citation for direct contempt.', 'general', 'State v. Brandt', 'https://www.courtlistener.com/opinion/2508761/', '2508761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of a dollar amount, we hold that Brandt could have been found guilty only of a misdemeanor and sentenced to imprisonment for a period of three years or less, ordered to pay a fine, or both.', 'sentencing', 'State v. Brandt', 'https://www.courtlistener.com/opinion/2508761/', '2508761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because there was insufficient evidence to establish a dollar amount of the Edisto Farm letter, we reverse Brandt’s felony sentence.', 'sentencing', 'State v. Brandt', 'https://www.courtlistener.com/opinion/2508761/', '2508761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'State v. Brandt', 'https://www.courtlistener.com/opinion/2508761/', '2508761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there are three essential factors
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Hughes v. State', 'https://www.courtlistener.com/opinion/890545/', '890545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the record is insufficient to establish that the provisions of the IADA were violated because it does not demonstrate that the trial court abused its discretion to grant the State''s November 4th request for a continuance under Article IV, Section (c).', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2541435/', '2541435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4] Taking a slightly different tack, however, we reverse the court of appeals''s judgment with respect to this point of error and remand the cause for consideration of the appellant''s remaining points of error on direct appeal.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/2541435/', '2541435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), this Court held that based on the sentencing guidelines in effect at that time, points could be assessed for victim injury only if the victim suffered a physical injury.', 'sentencing', 'Seagrave v. State', 'https://www.courtlistener.com/opinion/1737101/', '1737101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the most common usage of the phrase "sexual contact" encompasses the physical touching of a person''s sexual body parts.', 'general', 'Seagrave v. State', 'https://www.courtlistener.com/opinion/1737101/', '1737101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After'' considering all of the arguments presented, we affirm the judgment of the district court.', 'general', 'State v. Gilmour', 'https://www.courtlistener.com/opinion/1834259/', '1834259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a probationer, like a parolee, is entitled to a preliminary and a final revocation hearing, *933 under the conditions specified in Morrissey v.', 'general', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Loomis''s right to due process was violated *931 when the Idaho Commission of Pardons and Parole delayed giving Loomis notice of the parole violation that was alleged to have occurred and failed to conduct a timely probable cause hearing on that allegation.', 'probable_cause', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because these constitutional violations do not presently entitle Loomis to release from custody, we affirm the magistrate''s denial of habeas corpus relief.', 'habeas', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because Loomis has not been entitled to release at any time after his belated preliminary hearing was conducted, we affirm the magistrate''s order denying Loomis''s petition for a writ of habeas corpus.', 'habeas', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the Commission''s failure to give Loomis notice of the nature of the alleged parole violation for a period of twenty-one days following his arrest was a violation of due process.', 'general', 'Loomis v. Killeen', 'https://www.courtlistener.com/opinion/2570802/', '2570802') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2009), where we held that the trial court erred when it precluded cross-examination of a police detective about information the defense had received indicating that the detective "had been relieved of his powers as a police officer and [was] under investigation for a number of matters.', 'general', 'Jordan v. United States', 'https://www.courtlistener.com/opinion/2558215/', '2558215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[19] In both cases, we reversed the convictions because the trial court had erred in failing to clear up jury confusion about the meaning of terms in the governing law.', 'general', 'Jordan v. United States', 'https://www.courtlistener.com/opinion/2558215/', '2558215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6] None of these arguments has merit and thus we affirm appellant''s convictions, subject to remand for amendment of the judgment and commitment order to account for merged offenses.', 'general', 'Jordan v. United States', 'https://www.courtlistener.com/opinion/2558215/', '2558215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons we affirm appellant''s convictions, remanding for amendment of the judgment and commitment order to account for merged offenses.', 'general', 'Jordan v. United States', 'https://www.courtlistener.com/opinion/2558215/', '2558215') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that the trial court erred in taking judicial notice of Appellant’s age in this case, “most constitutional errors can be harmless.', 'general', 'State v. Odom', 'https://www.courtlistener.com/opinion/2795680/', '2795680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Odom', 'https://www.courtlistener.com/opinion/2795680/', '2795680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on this issue.', 'general', 'State v. Odom', 'https://www.courtlistener.com/opinion/2795680/', '2795680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 840, this court held that the circuit court "clearly exceeded the bounds of reason in sentencing Vellina! 1” because the record failed to provide any evidence that Vellina actually transferred a semi-automatic firearm to a drug dealer in exchange for drugs as relied upon by the circuit court in sentencing Vellina as it did:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, this court held that "the circuit court plainly erred in sentencing Vellina to consecutive terms of imprisonment based on the unsubstantiated allegation that he had transferred the semiautomatic firearm to a drug dealer.', 'sentencing', 'State v. Solomon', 'https://www.courtlistener.com/opinion/2534429/', '2534429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the standard of review established by the IAPA does not apply to this appeal.', 'general', 'Idaho Historic Preservation Council, Inc. v. City Council', 'https://www.courtlistener.com/opinion/2569166/', '2569166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court''s decision.', 'general', 'Idaho Historic Preservation Council, Inc. v. City Council', 'https://www.courtlistener.com/opinion/2569166/', '2569166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the IAPA does not apply to the present case.', 'general', 'Idaho Historic Preservation Council, Inc. v. City Council', 'https://www.courtlistener.com/opinion/2569166/', '2569166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In concluding the overbreadth discussion, the Court stated its holding as follows: "Accordingly, we hold that as applied to Hammersley, I.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that as applied to Hammersley, I.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 1285 (2000), we held that the adverbs "maliciously" and "willfully" modified the third verb "uses," and they would therefore logically modify the first two verbs also.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Hammersley''s conduct falls squarely within the specific intent requirement of I.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The dissent argues that because we affirm Poe''s conviction on an alternate ground, we did not need to address the overbreadth issue.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Poe has not alleged that the statute was unconstitutionally applied to his conduct or that he did not have fair notice that his conduct was proscribed, and because he has not shown any error by the trial court, we affirm the judgment of conviction.', 'general', 'State v. Poe', 'https://www.courtlistener.com/opinion/2572480/', '2572480') ON CONFLICT DO NOTHING;
