INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Construing the statute''s text, we hold that an owner-occupied residence not used for any commercial purpose does not qualify as property "used in" commerce or *851 commerce-affecting activity;', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/118370/', '118370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the provision covers only property currently used in commerce or in an activity affecting commerce.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/118370/', '118370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that § 844(i) is not soundly read to make virtually every arson in the country a federal offense.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/118370/', '118370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Satisfied that § 844(i) does not reach an owner-occupied residence that is not used for any commercial purpose, we reverse the Court of Appeals'' judgment.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/118370/', '118370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, but we do so with great reluctance given the manner in which the attorneys for both the defense and the prosecution conducted the trial below.', 'general', 'Fleming v. State', 'https://www.courtlistener.com/opinion/1702179/', '1702179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that we do not need to decide this issue because we hold that Matthew has not established that he was "subjected to restrictions approximating those experienced by one who is incarcerated.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,[1] where we held that whether a person is entitled to credit for time served while released on bail or probation is determined by whether the "person released on bail or probation is subjected to restrictions approximating those experienced by one who is incarcerated.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[2] We conclude that the restrictions to which Matthew was subjected did not meet this standard.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that Matthew was not entitled to credit toward his sentence of imprisonment for the period of time he was subject to electronic monitoring
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Matthew''s court-ordered conditions of release did not subject him to "restrictions approximating those experienced by one who is incarcerated.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that, just because the Commissioner of the Department of Corrections has the authority to designate relatively unstructured ways in which a prisoner may serve a sentence, it does not follow that a person subject to those same conditions as a component of pre-custody release by the court must receive credit for time served.', 'sentencing', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the proper test for whether a person gets credit against his sentence for time spent on a court-ordered release is the test which the supreme court set forth in Lock: whether the conditions of release impose "substantial restrictions on one''s freedom of movement and behavior.', 'sentencing', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[23] When we apply the test in Nygren, we conclude that the restrictions which Matthew faced did not "approximate those experienced by one who is incarcerated.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Matthew v. State', 'https://www.courtlistener.com/opinion/2635321/', '2635321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Harris was not seized at this point in the encounter.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Harris was not seized when the officers approached and questioned him at his seat.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Harris did not voluntarily consent to the second search of his person.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the second search of Harris'' person and the resulting seizure of the marijuana found in Harris'' jacket was justified and that the marijuana should not have been suppressed.', 'suppression', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Ascher, we held that random sobriety checkpoints are unconstitutional under the Minnesota Constitution.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), where we held that the police seized an underage bar patron.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, under the facts of that case, Cripps had been seized within the meaning of Article I, Section 10 of the Minnesota Constitution after the officers first asked her to produce identification for the purpose of showing that she was of legal age to consume alcohol.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dezso, we held that the state did not meet its burden of showing that a police officer obtained voluntary consent when the officer searched a defendant''s wallet during a traffic stop on a highway at night.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In George, we held that the state produced insufficient evidence to show that the defendant voluntarily consented to a search of his motorcycle when the defendant was stopped for a minor traffic violation.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'is supported by our decision in Cripps, where we held that Cripps was seized because, "[u]nder [the] circumstances, * * * an objectively reasonable person would have believed that he or she was neither free to disregard the officer''s request nor free to terminate the encounter * * *.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2228003/', '2228003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion we hold that the death penalty is not a cruel and unusual punishment for a defendant, like Whalen, found guilty of felony murder pursuant to 11
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the original penalty hearing was defective because the jury was permitted to consider unconstitutionally vague statutory aggravating circumstances.', 'general', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1937403/', '1937403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s instructions in effect, amounted to no more than reading the relevant portions of 11
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that it is not unconstitutional to allow consideration of the underlying felony as a statutory aggravating circumstance in a felony-murder case.', 'general', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1937403/', '1937403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, given the defendant’s very late assertion of this
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion we find that the death penalty is not a grossly disproportionate and excessive punishment for a defendant found guilty of felony murder, who actually killed his victim under the circumstances present here.', 'general', 'Whalen v. State', 'https://www.courtlistener.com/opinion/1937403/', '1937403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that in failing to do this, the defendant, Sills, had abandoned this claim and had forfeited his right to argue at some subsequent time that the trial judge had erroneously admitted his statement into evidence because it was induced by an illegal arrest.', 'general', 'Delashmit v. State', 'https://www.courtlistener.com/opinion/1819859/', '1819859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with Chamberlin, we find that this statement was insufficient to invoke the right to counsel.', 'general', 'Delashmit v. State', 'https://www.courtlistener.com/opinion/1819859/', '1819859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the Lee County Circuit Court''s judgment of conviction and sentence.', 'sentencing', 'Delashmit v. State', 'https://www.courtlistener.com/opinion/1819859/', '1819859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm the Lee County Circuit Court''s judgment of conviction entered against Stephen Delashmit consistent with the jury verdict finding Delashmit guilty of the crime of having enticed, induced, or solicited an eight-year-old child for the purpose of engaging in sexually explicit conduct, and the resulting life sentence as a section 99-19-83 habitual offender without the possibility of parole.', 'sentencing', 'Delashmit v. State', 'https://www.courtlistener.com/opinion/1819859/', '1819859') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we hold that the district court did not err when it refused to suppress the guns that were seized in the search of Anderson’s residence.', 'suppression', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a felony theft conviction later deemed a misdemeanor under section 609.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the district court did not err in applying the firearm prohibition statute to Anderson and that the search of Anderson’s residence was reasonable under the totality of the circumstances, we affirm.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we conclude that Anderson’s claim is subject to review under the plain error doctrine.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we conclude that Anderson has not established that the district court committed error when it applied the firearm prohibition statute to him.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not, and do not, reach the issue of whether absent a valid probation condition, a probation search based on reasonable suspicion violates the Fourth Amendment because we conclude that (1) the search was supported by reasonable suspicion;', 'search_seizure', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing facts, we conclude that there was a sufficiently high probability that Anderson possessed guns to make the intrusion on his privacy interest reasonable.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the facts of this case, Anderson has not proved that the district court committed plain error when it failed to consider whether his probation condition was validly imposed in an entirely separate proceeding.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that this is not such a case.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Balancing Anderson’s expectations of privacy against the government’s interests under the circumstances of this case, we conclude that the Fourth Amendment required no more than reasonable suspicion to conduct a search of Anderson’s residence.', 'search_seizure', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1832937/', '1832937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the capital punishment act is in all respects constitutional.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that New Jersey''s death penalty does not conflict with contemporary standards of decency in this state.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that capital punishment is not per se a violation of our state constitutional ban against cruel and unusual punishments.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*190 We hold that the Act is constitutional under the eighth amendment to the federal Constitution.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the marginal strength of the statistical showing in comparison to other cases, the fact that the mechanism by which jury lists are now constituted is facially neutral and objective, the failure to demonstrate underrepresentativeness over a sufficient period of time, and the State''s efforts at reform, we hold that defendant *228 has failed to make a prima facie showing that the Essex County grand and petit jury selection procedures violate either the sixth or fourteenth amendments.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the principles set forth in Batson and Gilmore, however, we hold that the dismissal of two blacks from defendant''s grand jury was not an error of constitutional magnitude.', 'dismissal', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court''s refusal to rule on this issue earlier was not an abuse of discretion.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court''s scheduling decision did not deprive defendant of a fair trial.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion in admitting the evidence.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the trial court''s entire charge and numerous instructions to the jurors concerning their responsibility as factfinders, we hold that the charge neither constituted an abuse of discretion nor violated the defendant''s fundamental right to a fair trial and to a trial by jury.', 'general', 'State v. Ramseur', 'https://www.courtlistener.com/opinion/1522122/', '1522122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 844 (1978), in which we held that to qualify as inadvertent a putatively plain view seizure must not be marred by police intent to search for and seize items *395 not described in the warrant.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1293789/', '1293789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we reverse the ruling of the Court of Appeals granting a new trial on four counts but uphold the granting of a new trial on the three remaining counts on which defendant was convicted.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1293789/', '1293789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that it was error to admit as evidence the property seized with respect to these three charges.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1293789/', '1293789') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the appellant''s claim was barred by Article 42.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*745 In Prior, supra, we held that a trial court may revoke deferred adjudication after the probationary term has expired if three conditions are met: (1) the motion to revoke probation is filed before the probationary term expires, (2) the capias issues before the probationary term expires, and (3) the State has used due diligence in trying to apprehend the probationer.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we held that a defendant must raise due diligence at or before the revocation hearing in order to preserve error for appeal.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), we held that "a trial court has jurisdiction to revoke deferred adjudication probation imposed pursuant to Article 42.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that appellant has failed to preserve such a complaint for review on appeal, and we will not address the contentions in his second ground for review [.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals and remand the case to that court so that it may address appellant''s remaining point of error.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Langston, supra, for example, we reversed the court of appeals, stating that the trial court should have granted the appellant''s motion to dismiss because the State had failed to meet its burden.', 'dismissal', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10]  Based on the same justification, we reversed the court of appeals in Rodriguez v.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Shahan we affirmed Stover''s holding that the trial court has authority to revoke community supervision where the defendant is arrested subsequent to the expiration of the community supervision.', 'general', 'Connolly v. State', 'https://www.courtlistener.com/opinion/1678616/', '1678616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1096 (1978), we held that the statute requires the law enforcement officer to notify the appropriate public defender, without a prior determination of financial need, if the person has no attorney and does not effectively waive his right to one.', 'general', 'State v. Duff', 'https://www.courtlistener.com/opinion/1499655/', '1499655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the transcript is not confidential because it involves an adult charged with a crime.', 'general', 'Edelen v. State', 'https://www.courtlistener.com/opinion/2530545/', '2530545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not.', 'general', 'Edelen v. State', 'https://www.courtlistener.com/opinion/2530545/', '2530545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And with that presumption in mind, we hold that the November 2008 transcript is a record that “involv[es] an adult charged with a crime.', 'general', 'Edelen v. State', 'https://www.courtlistener.com/opinion/2530545/', '2530545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we affirm.', 'general', 'Edelen v. State', 'https://www.courtlistener.com/opinion/2530545/', '2530545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we affirm her convictions.', 'general', 'Edelen v. State', 'https://www.courtlistener.com/opinion/2530545/', '2530545') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if it were, at this point, we hold that the Burk-Sanford precedent supersedes.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that felonious assault is, as the statute states, assault with a dangerous weapon.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that specific intent is not an element of felonious assault.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Doud did not hold that an intent to injure or batter is required in every criminal assault case.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that they had been framed in the disjunctive and that either definition could stand alone.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"It is hereby ordered that defendant''s Proposed Instruction `A'' be given, this court having ruled that, contrary to the Michigan Criminal Jury Instructions and Commentary with respect to the crime of felonious assault, specific intent to do bodily injury to the complainant is an element of the crime of felonious assault which the people must prove beyond a reasonable doubt.', 'jury_instruction', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Johnson and remand for a new trial and affirm the trial court''s decision in Ring as modified and remand for trial.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the trial court to give the "intent to do bodily injury" instruction and remand for instructions consistent with this opinion.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court''s decision to give that instruction and remand for instructions consistent with this opinion.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals in People v Johnson.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brendle, Odem argues that this Court held that merely uttering vulgar, indecent or profane language in the presence of a law enforcement officer is not sufficient grounds to convict the defendant for profane language if that language does not rise to the level of fighting words.', 'general', 'Odem v. State', 'https://www.courtlistener.com/opinion/1896417/', '1896417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the arrest of Odem was a lawful arrest.', 'general', 'Odem v. State', 'https://www.courtlistener.com/opinion/1896417/', '1896417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that there is no merit to Odem''s first two issues.', 'general', 'Odem v. State', 'https://www.courtlistener.com/opinion/1896417/', '1896417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, in accordance with the appropriate standard of review and based on the evidence discussed in the preceding section, we find that the evidence was indeed sufficient to justify the verdict.', 'general', 'Odem v. State', 'https://www.courtlistener.com/opinion/1896417/', '1896417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the circuit court committed manifest error in determining that Brendle''s conduct gave rise to probable cause for his arrest for a violation of Mississippi''s statute against public profanity.', 'probable_cause', 'Odem v. State', 'https://www.courtlistener.com/opinion/1896417/', '1896417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brendle, we found that the profanity used did not constitute "fighting words" and therefore, did not give rise to probable cause to make an arrest for a violation of Mississippi''s statute against public profanity.', 'probable_cause', 'Odem v. State', 'https://www.courtlistener.com/opinion/1896417/', '1896417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Odem v. State', 'https://www.courtlistener.com/opinion/1896417/', '1896417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in directing a verdict for the plaintiffs.', 'general', 'City of Hialeah v. Rehm', 'https://www.courtlistener.com/opinion/1719614/', '1719614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Snider and Kendall, we held that the propriety of a search incident to arrest is to be assessed, not based on the police officer''s subjective belief or understanding concerning the ratio''nale for the arrest, but rather based on whether the facts known to the officer provided an objective justification for the arrest.', 'general', 'Baxter v. State', 'https://www.courtlistener.com/opinion/2584067/', '2584067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained here, we conclude that the evidence against the defendants was obtained lawfully, and we accordingly affirm the defendants'' convictions.', 'general', 'Baxter v. State', 'https://www.courtlistener.com/opinion/2584067/', '2584067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this question is answered by our decisions in Snider v.', 'general', 'Baxter v. State', 'https://www.courtlistener.com/opinion/2584067/', '2584067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that we need not resolve this potential dispute (nor ask the superior court to resolve it).', 'general', 'Baxter v. State', 'https://www.courtlistener.com/opinion/2584067/', '2584067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of this, we conclude that it was reasonable for Jurgens to examine the folded paper in Johnson''s wallet.', 'general', 'Baxter v. State', 'https://www.courtlistener.com/opinion/2584067/', '2584067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Jur-gens acted lawfully when he opened and inspected the folded piece of paper in Johnson''s wallet.', 'general', 'Baxter v. State', 'https://www.courtlistener.com/opinion/2584067/', '2584067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the issues are of significance, we conclude that we should not address them without a full record having been developed below.', 'general', 'People v. LaLone', 'https://www.courtlistener.com/opinion/1856483/', '1856483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we conclude that the hearsay statements testified to by Dr.', 'general', 'People v. LaLone', 'https://www.courtlistener.com/opinion/1856483/', '1856483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in People v Hackett, supra, we concluded that the exclusion of evidence outside the exceptions stated under the rape-shield statute may violate the Sixth Amendment with regard to an individual defendant.', 'general', 'People v. LaLone', 'https://www.courtlistener.com/opinion/1856483/', '1856483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We disagree with that court''s interpretation of the Confrontation Clause and we reverse.', 'general', 'People v. LaLone', 'https://www.courtlistener.com/opinion/1856483/', '1856483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the reference in the kidnapping statute to sexual abuse embraces all the various degrees of sexual abuse identified in chapter 709, including the crime of second-degree sexual abuse for which Mitchell has been convicted here.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/2055072/', '2055072') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that second-degree sexual abuse
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Mitchell', 'https://www.courtlistener.com/opinion/2055072/', '2055072') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we conclude that the trial court’s use of the word “probably” rather than “possibly” or “allegedly” was harmless error.', 'general', 'Rice v. State', 'https://www.courtlistener.com/opinion/7590686/', '7590686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this portion of the oral charge is a proper statement of the law, when considered with the court’s entire charge, and is not contrary to the appellant’s presumption of innocence.', 'general', 'Rice v. State', 'https://www.courtlistener.com/opinion/7590686/', '7590686') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his conviction and sentence for the reasons set forth below.', 'sentencing', 'State v. Henry', 'https://www.courtlistener.com/opinion/2601668/', '2601668') ON CONFLICT DO NOTHING;
