INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that under HRS 291C-12(a), a driver is “involved in an accident” when his or her vehicle is affected or implicated in the accident.', 'general', 'State v. Lian-Wen Chen', 'https://www.courtlistener.com/opinion/2611944/', '2611944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that there was no ineffective assistance of counsel, our affirmance is not affected.', 'ineffective_assistance', 'State v. Lian-Wen Chen', 'https://www.courtlistener.com/opinion/2611944/', '2611944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Doing so, we find that there was evidence of a close proximity of time, place and events which would enable a reasonable fact finder to conclude beyond a reasonable doubt that there was one accident, and that that accident resulted in the pedestrian’s death.', 'general', 'State v. Lian-Wen Chen', 'https://www.courtlistener.com/opinion/2611944/', '2611944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lian-Wen Chen', 'https://www.courtlistener.com/opinion/2611944/', '2611944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in light of the trial court’s definitive finding that the Commonwealth failed to prove that States was the driver of the car, States’ federal constitutional rights prohibit the Commonwealth from attempting to convince a second jury otherwise.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the Commonwealth may not retry States on the charges upon which the jury could not agree, for to do so would permit relitigation of an issue already determined, by final judgment, in States’ favor.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Never have we held that this new right of the Commonwealth is on equal footing with, let alone higher ground than, a federal constitutional right of the magnitude and significance that the protection against double jeopardy represents.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the circumstances of this case, the prohibition against double jeopardy, specifically, the principle of collateral estoppel, operates to prevent the Commonwealth from proceeding with a retrial on those charges on which the jury could not agree.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that they should not.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we conclude that in this case, the former must yield to the latter.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Commonwealth argues vigorously that if we affirm the Superior Court we have denied it its constitutional right to a jury trial.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we affirm the Order of the Superior Court, which reversed the Order of the Court of Common Pleas of Allegheny County.', 'plea', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the district court possessed authority to impose two-year periods of probation for each of Horejs’ misdemeanors and to direct that all of his periods of probation be served consecutively.', 'general', 'State v. Horejs', 'https://www.courtlistener.com/opinion/2633672/', '2633672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record provides sufficient evidence to support the jury’s verdict that the group’s acts as a whole amounted to aggravated assault.', 'general', 'State v. Horejs', 'https://www.courtlistener.com/opinion/2633672/', '2633672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Horejs', 'https://www.courtlistener.com/opinion/2633672/', '2633672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We affirm.', 'general', 'Porter v. State', 'https://www.courtlistener.com/opinion/1707681/', '1707681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found sufficient competent evidence in the record to support the verdicts in the guilt phase, we affirm each of the convictions.', 'general', 'Porter v. State', 'https://www.courtlistener.com/opinion/1707681/', '1707681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm each of the convictions and the sentence of death.', 'sentencing', 'Porter v. State', 'https://www.courtlistener.com/opinion/1707681/', '1707681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that both § 63-11-30(1)(a) and § 63-3-1213 provide drivers with adequate notice of the conduct for which they are subject to be penalized.', 'general', 'Leuer v. City of Flowood', 'https://www.courtlistener.com/opinion/1806247/', '1806247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the above reasoning, we conclude that Miss.', 'general', 'Leuer v. City of Flowood', 'https://www.courtlistener.com/opinion/1806247/', '1806247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'factors to § 16902(1), we conclude that even if the Legislature did not intend to create true strict liability, § 16902(1) at most requires only that the prosecution prove that defendant “purposefully or voluntarily performed the wrongful act.', 'general', 'People v. Schumacher', 'https://www.courtlistener.com/opinion/2126538/', '2126538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the Legislature intended in § 16902(1) to establish a so-called public-welfare offense: the only intent necessary to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this testimony did not affect defendant’s substantial rights for several reasons.', 'general', 'People v. Schumacher', 'https://www.courtlistener.com/opinion/2126538/', '2126538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all these reasons, we conclude that defendant has not established that plain error affected his substantial rights.', 'general', 'People v. Schumacher', 'https://www.courtlistener.com/opinion/2126538/', '2126538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Schumacher', 'https://www.courtlistener.com/opinion/2126538/', '2126538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this situation, we conclude that the statute is susceptible to two reasonable interpretations.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in such situations, the elements of the aggravated rape and the murder may overlap.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the facts in appellant''s case constituted a proper subject for prosecution under the capital murder statute.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that a rational jury could have found beyond a reasonable doubt that appellant constituted a continuing threat to society and overrule appellant''s sixteenth point of error.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we conclude that appellant was arrested upon probable cause in a suspicious place, under circumstances that reasonably show he had committed some felony.', 'probable_cause', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Before addressing the substance of appellant''s seventh and eighth points of error, we conclude that we need not address appellant''s Texas constitutional claims.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that the trial judge, acting as the factfinder, decided a controverted question in a manner supported by the record.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Zerbst, supra, we conclude that appellant knowingly relinquished his right to consult with an attorney.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that no evidence before the jury raised the issue of the voluntariness of appellant''s confession.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concerning appellant''s artistic abilities, we conclude that in this case the evidence adduced "is otherwise irrelevant to an individualized assessment of the deathworthiness of appellant.', 'general', 'Muniz v. State', 'https://www.courtlistener.com/opinion/1471480/', '1471480') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that this error is procedurally barred, we also find it to be without merit.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, since Holly was convicted of capital murder with armed robbery as an underlying offense, we find that conviction on the grand larceny charge, under the circumstances of this case, constitutes double jeopardy which prohibits multiple punishments for the same offense.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that all but one of these issues are either procedurally barred or without merit.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defense failed to contemporaneously object and is therefore procedurally barred.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the evidence was sufficient to show the money was taken from Norwood.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the monetary amount which distinguishes grand larceny from petit larceny and robbery is irrelevant for purposes of the double jeopardy analysis.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we found that the death penalty was not disproportionate for a seventeen-year-old and an eighteen-year-old, who together with a third young man, robbed and beat to death a taxi cab driver.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and vacate Holly''s conviction for grand larceny.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and vacate the grand larceny conviction.', 'general', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered carefully the record before us as well as the arguments presented on Holly''s behalf, we affirm the jury''s verdict and sentence on the kidnapping and capital murder charges.', 'sentencing', 'Holly v. State', 'https://www.courtlistener.com/opinion/1659705/', '1659705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that these remaining eight charges arose from conduct which formed part of the same criminal episode as the conduct on which the initial three possession and delivery charges were based.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1194 (1983), we held that § 110 did not bar the prosecution of an aggravated assault charge when the defendant had previously pled guilty to the summary offense of failing to identify himself at the scene of an accident.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In applying this analysis to the instant case, we conclude that Bracalielly''s criminal actions fail to constitute a single criminal episode.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*475 We conclude that the two drug transactions in Commonwealth v.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that neither Commonwealth v.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we concluded that the Section 110 barred the second attempt at prosecution and quashed the subsequent indictments.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we concluded that the drug charges brought against the defendant were not only temporally related but also logically related, and thus constituted a single criminal episode.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Starr involve drug transactions which constitute a "single criminal episode," we find that Section 110 does not bar the instant prosecutions of either Bracalielly or Starr.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hude, we found that such substantial duplication had occurred.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we found that these offenses presented substantial duplication of issues of law and fact because the *473 case did not involve "a situation where different evidence was required to be introduced to establish the alleged individual instances of possession and delivery", but rather, involved a situation in which the Commonwealth''s case in both the first and second drug trials rested solely upon the credibility of a single witness.', 'general', 'Commonwealth v. Bracalielly', 'https://www.courtlistener.com/opinion/1972169/', '1972169') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" In response to the defendant''s statute of limitations claim in Schmidt, we said simply "[t]his Court has dealt with a similar contention in [Ward], and in that case we held that this was a matter of defense which should be decided in the courts of the demanding state.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/2433594/', '2433594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE the judgments of the court of appeals and AFFIRM the judgments of the trial court.', 'general', 'Proctor v. State', 'https://www.courtlistener.com/opinion/2433594/', '2433594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 243, however, in addressing the burden of persuasion required of the proponent of posthypnotic testimony, we held that because of the "uncertainties inherent" in the evidence, "it [was] appropriate to require the proponent of such [evidence] to demonstrate .', 'general', 'Kelly v. State', 'https://www.courtlistener.com/opinion/2430249/', '2430249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Is the Frye general acceptance test still a part of Texas law? We conclude that it is not.', 'general', 'Kelly v. State', 'https://www.courtlistener.com/opinion/2430249/', '2430249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing that evidence in the light most favorable to the trial court''s decision, we conclude that it was demonstrated by clear and convincing evidence that the scientific principle underlying the RFLP technique was valid, that the RFLP technique itself was valid, that the technique was properly applied in this case, and that the related population frequency studies were also valid and reliable.', 'general', 'Kelly v. State', 'https://www.courtlistener.com/opinion/2430249/', '2430249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that the trial court''s failure to place the initial burden on the State to establish a prima facie case of racial discrimination was reversible error.', 'general', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1694374/', '1694374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that the defendant was precluded from being punished for the kidnaping of one individual and capital murder of a different individual if the kidnaping offense was used to elevate a plain murder charge into a capital murder charge.', 'general', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1694374/', '1694374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987), this Court held that a sentence of death was disproportionate for reasons including the fact that the codefendant ultimately received a life sentence.', 'sentencing', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1694374/', '1694374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that once the State has proven murder under this definition, no other evidence must be produced in order to establish the crime of conspiracy.', 'general', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1694374/', '1694374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without addressing the issue of hearsay, we find that Selders''s alleged offer to Anderson was not relevant to the case against Stewart.', 'general', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1694374/', '1694374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If this Court may consider the sentence received by a codefendant, then why should the jury be deprived of such information? Because of the specific circumstances of an offense and the complicated task of assessing the culpability of a codefendant based upon his role in the crime, we find that the consideration of the codefendant''s sentence in the case at hand is better suited for proportionality review.', 'sentencing', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1694374/', '1694374') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*642 We conclude that there was no probable cause to justify the arrest of Stephens for violation of Section 877.', 'probable_cause', 'State v. Saunders', 'https://www.courtlistener.com/opinion/1833853/', '1833853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that mere words, used as a tool of communication, are constitutionally protected.', 'general', 'White v. State', 'https://www.courtlistener.com/opinion/1949936/', '1949936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Commonwealth did not make out the crime of operating a waste disposal facility without a permit against Mr.', 'general', 'Commonwealth v. Scarpone', 'https://www.courtlistener.com/opinion/2308692/', '2308692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Lopez'' conviction for child abuse, a class 2 felony, and the trial court''s sentence of an aggravated term of 22 years'' imprisonment based on that conviction.', 'sentencing', 'State v. Lopez', 'https://www.courtlistener.com/opinion/2614939/', '2614939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this was not a fundamental error because there was other evidence adequate to sustain the conviction even in the absence of the confession.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1851947/', '1851947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed that case simply because we concluded that the error, although not preserved at the trial, was of such harmful nature that the ends *487 of justice required a new trial.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1851947/', '1851947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 482, in which we affirmed a murder conviction with the supreme penalty although the record will reveal that there was no instruction on third degree murder.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1851947/', '1851947') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that the admission of the second statement was harmless, beyond a reasonable doubt, as to the felony murder convictions.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 565, we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no merit in any of the defendant''s other contentions, we conclude that the felony murder convictions *585 and the death penalty imposed for those convictions should be affirmed.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite the fact that the defendant''s second confession was erroneously admitted into evidence, we conclude that the error was harmless beyond a reasonable doubt as to the felony murder convictions.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Enmund does not preclude the imposition of the death penalty in this case where Deputy was not "found guilty only vicariously as a felony murderer.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning first to subparagraph b, we conclude that the evidence supported the jury''s findings of the statutory aggravating *602 circumstances which have been discussed in this opinion.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we conclude that given "the totality of evidence in aggravation and mitigation which bears upon the particular circumstances or details of the offense and the character and propensities of the offender" the sentence of death imposed by the jury was neither arbitrarily nor capriciously imposed.', 'sentencing', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the imposition of death in this case was therefore not disproportionate and the defendant''s convictions and sentence as to the felony murder charges are accordingly affirmed.', 'sentencing', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, finding the initial detention pursuant *588 to 11 Del.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the trial court''s decision to admit the defendant''s first recorded statement.', 'general', 'Deputy v. State', 'https://www.courtlistener.com/opinion/1488407/', '1488407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] We hold that the Arizona Constitution also provides for a right to refuse medical treatment.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the doctrine of informed consent  a doctrine borne of the common-law right to be free from nonconsensual physical invasions  permits an individual to refuse medical treatment.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that court-resolved disputes in cases of this nature must be resolved by clear and convincing evidence.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the medical treatment decisions made in this case were not decisions to commit suicide, neither the physicians, nurses, health care facility, guardian, guardian ad litem, nor any similarly situated individual or entity can be charged with manslaughter.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rasmussen''s right to refuse medical treatment still existed despite her incompetency and her failure to articulate her medical treatment desires prior to becoming incompetent.', 'general', 'Rasmussen by Mitchell v. Fleming', 'https://www.courtlistener.com/opinion/1143517/', '1143517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the second prong of the pleading theory, the evidentiary examination, cannot replace satisfying either the pleading or statutory theories.', 'plea', 'State v. Curtis', 'https://www.courtlistener.com/opinion/1224045/', '1224045') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the pleading theory inattentive driving is not a lesser included offense of driving under the influence, I.', 'plea', 'State v. Curtis', 'https://www.courtlistener.com/opinion/1224045/', '1224045') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 192 (1986), this Court held that under the statutory theory, an offense is not considered a lesser included offense of the charged offense unless it is necessarily so under the statutory definition of the charged offense.', 'general', 'State v. Curtis', 'https://www.courtlistener.com/opinion/1224045/', '1224045') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State is constitutionally required to extend to same-sex couples the common benefits and protections that flow from marriage under Vermont law.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the current statutory scheme shall remain in effect for a reasonable period of time to enable the Legislature to consider and enact implementing legislation in an orderly and expeditious fashion.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that a woman who was co-parenting the two children of her same-sex partner could adopt the children without terminating the natural mother''s parental rights.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, although the State proffered at least a conceivable purpose for the legislative distinction between natural and adopted children, we held that the classification was unreasonable, explaining that "[a]dopted persons have historically been a target of discrimination," id.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather than eschewing the federal standards, we held that the educational financing system advanced no "legitimate governmental purpose" under any standard.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the Common Benefits Clause of the Vermont Constitution, which, in pertinent part, reads,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that this approach, rather than the rigid, multi-tiered analysis evolved by the federal courts under the Fourteenth Amendment, shall direct our inquiry under Article 7.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, viewed in the light of history, logic, and experience, we conclude that none of the interests asserted by the State provides a reasonable and just basis for the continued exclusion of same-sex couples from the benefits incident to a civil marriage license under Vermont law.', 'general', 'Baker v. State', 'https://www.courtlistener.com/opinion/2264443/', '2264443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that under
