INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the violation of the constitutional principle articulated in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It suffices to say that based on our de novo review of the record made in this proceeding, we conclude that the evidence was sufficient to conclude that Adam’s murder was “especially heinous, atrocious, cruel, or manifested exceptional depravity by ordinary standards of morality and intelligence” within the meaning of § 29-2523(l)(d), and that this aggravating factor outweighed the mitigating factors supported by the record.', 'general', 'State v. Mata', 'https://www.courtlistener.com/opinion/1616861/', '1616861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because the pretrial and trial “steps” of [the defendant’s] litigation were completed and became final at a time when the law did not require the State to file a notice of aggravation in order to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Mata’s convictions for first degree premeditated murder and kidnapping.', 'general', 'State v. Mata', 'https://www.courtlistener.com/opinion/1616861/', '1616861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 251 (2001), in which we held that § 28-304 was not unconstitutionally vague.', 'general', 'Glass v. Kenney', 'https://www.courtlistener.com/opinion/2029354/', '2029354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we conclude that the district court erred when it denied Glass’ motion to proceed in forma pauperis on appeal in case No.', 'general', 'Glass v. Kenney', 'https://www.courtlistener.com/opinion/2029354/', '2029354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the relevant statutes, constitutional provision, and our case law, we conclude that the district court improperly denied Glass’ application to proceed in forma pauperis on appeal.', 'general', 'Glass v. Kenney', 'https://www.courtlistener.com/opinion/2029354/', '2029354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in which we concluded that the second degree murder statute was not unconstitutionally vague.', 'general', 'Glass v. Kenney', 'https://www.courtlistener.com/opinion/2029354/', '2029354') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that an officer may perform an investigatory stop of a vehicle based on a reasonable suspicion of a non-criminal traffic violation.', 'general', 'State v. Colstad', 'https://www.courtlistener.com/opinion/2132857/', '2132857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that "the absence of a registration plate, and reasonable inferences that can be drawn from that fact, constitute[] reasonable suspicion sufficient to justify an investigatory stop of a motor vehicle.', 'general', 'State v. Colstad', 'https://www.courtlistener.com/opinion/2132857/', '2132857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the officer possessed a reasonable suspicion that Colstad was guilty of inattentive driving, contrary to Wis.', 'general', 'State v. Colstad', 'https://www.courtlistener.com/opinion/2132857/', '2132857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that, in a trial on a charge
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Colstad''s conviction.', 'general', 'State v. Colstad', 'https://www.courtlistener.com/opinion/2132857/', '2132857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We hold that, under Studer v.', 'general', 'Teal v. State', 'https://www.courtlistener.com/opinion/1396275/', '1396275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that this language literally required a "person" to be named as the perpetrator in the written instrument in order for that instrument to qualify as an indictment.', 'general', 'Teal v. State', 'https://www.courtlistener.com/opinion/1396275/', '1396275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[4] We held that an "offense" is charged if the written instrument "accuses someone of a crime with enough clarity and specificity to identify the penal statute under which the State intends to prosecute.', 'general', 'Teal v. State', 'https://www.courtlistener.com/opinion/1396275/', '1396275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,[45] this Court held that "a written instrument is an indictment or information under the Constitution if it accuses someone of a crime with enough clarity and specificity to identify the penal statute under which the State intends to prosecute, even if the instrument is otherwise defective.', 'general', 'Teal v. State', 'https://www.courtlistener.com/opinion/1396275/', '1396275') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s error was harmless beyond a reasonable doubt.', 'general', 'Bird v. State', 'https://www.courtlistener.com/opinion/1255211/', '1255211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 417 (1962), for example, we held that “collateral relief is not available when all that is shown is a failure to comply with the formal requirements” of a rule of criminal procedure in the absence of any indication that the defendant was prejudiced by the asserted technical error.', 'general', 'Bird v. State', 'https://www.courtlistener.com/opinion/1255211/', '1255211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the denial by the trial court of Bird’s efforts to withdraw his pleas of guilty.', 'plea', 'Bird v. State', 'https://www.courtlistener.com/opinion/1255211/', '1255211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a finder of fact could reasonably have found, based on the totality of the circumstances, that defendant''s behavior would have placed a reasonable person in fear of bodily injury.', 'general', 'Hes v. Jcs', 'https://www.courtlistener.com/opinion/2070086/', '2070086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that argument unpersuasive given the novelty of the factual circumstances and the legal issue involved.', 'general', 'Hes v. Jcs', 'https://www.courtlistener.com/opinion/2070086/', '2070086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and hold that the trial procedures violated defendant''s right to due process.', 'general', 'Hes v. Jcs', 'https://www.courtlistener.com/opinion/2070086/', '2070086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the Appellate Division erred when it concluded that, apparently as a matter of law, defendant''s conduct could not constitute harassment under N.', 'general', 'Hes v. Jcs', 'https://www.courtlistener.com/opinion/2070086/', '2070086') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that § 1442 and § 1448 are not unconstitutionally vague as applied in this case and we will not be swayed by defendant’s pleas on behalf of those whom he fears might be arrested if found to be carrying toy or table knives in their pockets.', 'plea', 'Upshur v. State', 'https://www.courtlistener.com/opinion/2191158/', '2191158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although our decision is based on the fact that we conclude that the Tempelises'' insurance policy is ambiguous, it is understandable why other courts have simply refused to allow a material misrepresentation that relates to one element of a claim, e.', 'general', 'Flores v. Allstate Ins. Co.', 'https://www.courtlistener.com/opinion/1901616/', '1901616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the provision as drafted by Allstate is ambiguous and should be construed in favor of the insured so as not to invalidate UM coverage, we do not reach the issue in this case of whether a provision that voided coverage of an entire automobile policy, including UM, PIP and liability coverage, upon the submission of a fraudulent PIP bill, would be contrary to the public policy of this State and the purpose of the statutorily mandated UM coverage.', 'general', 'Flores v. Allstate Ins. Co.', 'https://www.courtlistener.com/opinion/1901616/', '1901616') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Today we hold that "if the trial judge concludes the proposed testimony would be incriminating and thereby poses the risk of possible future prosecution of the witness, this ends that inquiry and a claim of privilege should be sustained.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2314198/', '2314198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991)], we held that the trial judge must seek a commitment from the prosecutor that the potential defense witness will not be prosecuted, but that even if no commitment is forthcoming, "the trial judge must make an independent assessment, based on all of the circumstances, of the likelihood of prosecution.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2314198/', '2314198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that even when the prosecutor cannot "make a commitment" that a potential defense witness will not be prosecuted, "the trial judge must make an independent assessment, based on all of the circumstances, of the likelihood of prosecution.', 'general', 'Carter v. United States', 'https://www.courtlistener.com/opinion/2314198/', '2314198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As did the Committee, we conclude that Respondent has violated Rules 8.', 'general', 'In Re Mitrano', 'https://www.courtlistener.com/opinion/1525615/', '1525615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Committee’s findings of fact are well written and amply supported by the record, and have adopted them with minor revisions.', 'general', 'In Re Mitrano', 'https://www.courtlistener.com/opinion/1525615/', '1525615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that Williams Industries, as represented by its now current president, Frank E Williams, III, and Frank E.', 'general', 'In Re Mitrano', 'https://www.courtlistener.com/opinion/1525615/', '1525615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that this misappropriation was intentional, the Committee and the Board recommend that Respondent be disbarred.', 'general', 'In Re Mitrano', 'https://www.courtlistener.com/opinion/1525615/', '1525615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that property, in this case money, which has been found in a judicial proceeding to have a logical nexus to items which are illegal to possess, such as controlled substances, or have been acquired through illicit means, may constitute contraband as defined in Wis.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature intended that the return of property provision in § 961.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other situations where the state has not initiated a forfeiture action, we conclude that a person claiming the right to property seized by the authorities is limited to the procedures set forth in Wis.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '20, we conclude that in order to retain the property, the state must establish that the property is either contraband or is needed as evidence in a case.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though the circuit court mistakenly placed the burden on the defendant to show whether the cash was or was not contraband, we conclude that based on the evidence of record, this error was harmless.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that it is ambiguous which return of property statute should have been employed, we look to the scope, history, context, subject matter, and object of the statutes to discern the legislative intent.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Rosen is not controlling.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that the legislature intended that the return provision of Wis.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In those situations where the state has not initiated a forfeiture action, we conclude that a person claiming the right to property seized by the authorities is limited to the procedures set forth in § 968.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '13(1)(a), we conclude that contraband is not limited to materials which are per se illegal.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2114697/', '2114697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, under the totality of the circumstances, these actions constituted a show of authority to which a reasonable person would feel compelled to submit.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the officers’ actions constituted a show of authority and that a reasonable person in the driver’s position would not have felt free to leave.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Supreme Court further elaborated on that point: “We conclude that a person has been ‘seized’ within the meaning of the Fourth Amendment only if, in view of all of the circumstances surrounding the incident, a reasonable person would have believed that he was not free to leave.', 'search_seizure', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While Cosby argues before this court that there was no break between the conclusion of the traffic stop and the officer’s request for consent to search, we conclude that the record does not support such an argument.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, applying the principles of Brownlee and Mendenhall, we conclude that Cosby was not seized and that his consent to search his car was therefore voluntary.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the officers’ stop of the vehicle was supported by probable cause.', 'probable_cause', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '100681, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '102584, we reverse the judgment of the appellate court, vacate the order of the circuit court, and remand the cause to the circuit court for further proceedings.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, relying on the long-standing and well-established principle that consistency in a verdict is not required, we hold that Appellee''s acquittal of the predicate offense of robbery does not necessitate the vacatur of his conviction of second-degree murder.', 'general', 'Commonwealth v. Miller', 'https://www.courtlistener.com/opinion/2319429/', '2319429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirmed the Superior Court''s vacatur of the Magliocco cross-appellee''s conviction for ethnic intimidation.', 'general', 'Commonwealth v. Miller', 'https://www.courtlistener.com/opinion/2319429/', '2319429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6]  After Magliocco was decided, the Commonwealth Court held, and we affirmed, that the ethnic intimidation statute was unconstitutional on procedural grounds related to its enactment by the General Assembly.', 'general', 'Commonwealth v. Miller', 'https://www.courtlistener.com/opinion/2319429/', '2319429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2008), we held that the rapid, natural dissipation of alcohol in the blood creates a single-factor exigent circumstance that allows law enforcement to force the drawing of blood from a defendant when probable cause exists that the defendant has committed criminal vehicular homicide or operation under Minn.', 'probable_cause', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we conclude that mandatory parole is lawful, that the Parole Board has the authority to set conditions governing the conduct of prisoners released to mandatory parole, and that a parolee who violates those conditions can lawfully be sent back to prison to serve the remainder of their sentence-i.', 'sentencing', 'Hill v. State', 'https://www.courtlistener.com/opinion/2623271/', '2623271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since it appears from the sketchy record presented to us that Morton''s [mandatory] parole status was revoked because of [his] violation of state laws, we conclude that [the] revocation was not prohibited by AS 33.', 'general', 'Hill v. State', 'https://www.courtlistener.com/opinion/2623271/', '2623271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained here, we conclude that mandatory parole is lawful, that the Parole Board has the authority to set conditions governing the conduct of prisoners released to mandatory parole, and that a parolee who violates those conditions can lawfully be sent back to prison to serve the remainder of their sentence-i.', 'sentencing', 'Hill v. State', 'https://www.courtlistener.com/opinion/2623271/', '2623271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that an anonymous caller’s tip was not sufficiently corroborated where:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '19, we conclude that the probation officers should have conducted an independent assessment of the caller’s and of Lt.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ogden’s information did not form a basis for reasonable suspicion, we conclude that the probation officers had no basis under their mandated framework for analysis to believe there was reasonable suspicion to search Culver’s home on October 16.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it did not.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that the information supplied by Lt.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that Lt.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in this case we find that the caller’s description of Culver, and activity observable from the street, were not enough to provide a basis to find that the tip provided reason to believe that Culver was engaged in illicit drug activity.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ogden’s call, the probation officers would not have searched on October 16, we find that Lt.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that probation officers violated their clear statutory mandate, we do not reach any constitutional questions.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Now, therefore, it is ordered that the judgment of the Superior Court is REVERSED, Culver’s conviction is VACATED and the case is REMANDED for proceedings consistent with this opinion.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 497 (2001) ("We hold that the balance of these considerations requires no more than reasonable suspicion to conduct a search of this probationer’s house.', 'general', 'Culver v. State', 'https://www.courtlistener.com/opinion/2313282/', '2313282') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that, although the trial court erred in its Frye analysis, this error was harmless.', 'general', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that defendant did not make a timely objection to the prosecutor’s opening statement.', 'general', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we conclude that the trial court erred in dismissing Juror 20.', 'dismissal', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the record, we conclude that had the jury been allowed to continue to deliberate with Juror 20 as a member of the jury, a nonunanimous verdict would likely have been rendered.', 'general', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we find that the trial court abused its discretion in dismissing Juror 20.', 'dismissal', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION We affirm defendant’s convictions, as well as his sentences on the home invasion and aggravated arson convictions.', 'sentencing', 'People v. Nelson', 'https://www.courtlistener.com/opinion/2169253/', '2169253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on the predecessor provision of section 115 — 16 of the Code of Criminal Procedure of 1963, this court held: “The introduction of such record of conviction for the purpose of affecting the credibility of a witness, or the defendant who has voluntarily testified, is provided for by statute.', 'general', 'People v. Naylor', 'https://www.courtlistener.com/opinion/2231413/', '2231413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Far from being “an issue of first impression in Illinois,” we conclude that the rule is evident.', 'general', 'People v. Naylor', 'https://www.courtlistener.com/opinion/2231413/', '2231413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s erroneous admission of defendant’s prior conviction to impeach his testimony constitutes reversible error.', 'general', 'People v. Naylor', 'https://www.courtlistener.com/opinion/2231413/', '2231413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the evidence is closely balanced, we nevertheless find, after carefully reviewing the record, that the evidence was sufficient to prove defendant guilty beyond a reasonable doubt.', 'general', 'People v. Naylor', 'https://www.courtlistener.com/opinion/2231413/', '2231413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record, we conclude that the initial search of the residence was a true parole search and that the search was reasonable.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The statute does adequately advise the public of the proscribed conduct, namely possessing methamphetamine with the intent to manufacture methamphetamine, and we conclude that the statute is not unconstitutionally vague.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence permits the reasonable conclusion that two independent offenses were committed for which Micheau could be separately punished, we conclude that, under the circumstances, *1064Count VI, the attempt charge, is not a lesser included offense of Count I, dealing in methamphetamine.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence presented at trial and the prosecutor’s closing argument, we conclude that the State distinguished and set forth independent evidence of Count I and Count VI.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Count II, possession of methamphetamine as a class D felony, is a lesser included offense of Count I, dealing in methamphetamine.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Micheau’s sentences for Count I and Count VI do not violate the Proportionality Clause.', 'sentencing', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only where the decision is clearly against the logic and effect of the facts and circumstances.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and vacate in part.', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Micheau’s convictions for Count I, dealing in methamphetamine as a class B felony;', 'general', 'Micheau v. State', 'https://www.courtlistener.com/opinion/2231583/', '2231583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that defendant’s double jeopardy claim was not forfeited, as it was properly raised in response to the State’s argument.', 'general', 'People v. Whitfield', 'https://www.courtlistener.com/opinion/2204818/', '2204818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*** We hold that the constitutional guarantee against multiple punishments for the same offense absolutely requires that punishment already exacted must be fully ‘credited’ in imposing sentence upon a new conviction for the same offense.', 'sentencing', 'People v. Whitfield', 'https://www.courtlistener.com/opinion/2204818/', '2204818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that a defendant sentenced to probation, and then sentenced to imprisonment for the same offense, is not subjected to an unconstitutional second punishment for double jeopardy purposes and, therefore, is not entitled to credit for time spent on probation.', 'sentencing', 'People v. Whitfield', 'https://www.courtlistener.com/opinion/2204818/', '2204818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION For the reasons above, we reverse the appellate court’s judgment remanding this matter to the trial court for consideration of sentencing credit for the time defendant spent on a void probation.', 'sentencing', 'People v. Whitfield', 'https://www.courtlistener.com/opinion/2204818/', '2204818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1137101/', '1137101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '48(a)(2) the court had the power to dismiss, and as its holding that count II was a lesser included offense of count I was correct, as hereinafter discussed, we hold that the court was correct in ordering the dismissal.', 'dismissal', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1137101/', '1137101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the above principles, we hold that the court was correct in not applying the provisions of I.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1137101/', '1137101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hahn, supra, we hold that only the person who actually used the gun can be subjected to the enhancement provisions of I.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1137101/', '1137101') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Carter is entitled to sentence credit for the days from December 14, 2003, when he was taken into custody in Illinois based on the charge in this case, until November 2, 2004, when he was sentenced on the Illinois charge.', 'sentencing', 'State v. Carter', 'https://www.courtlistener.com/opinion/2213845/', '2213845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that "custody" as used in sec.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/2213845/', '2213845') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was.', 'general', 'State of Maine v. Mark Gessner', 'https://www.courtlistener.com/opinion/4903081/', '4903081') ON CONFLICT DO NOTHING;
