INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Rule 11(c)(1) imposes no requirement that the court determine, and inform, the defendant of the applicable sentencing range under the Guidelines before accepting a guilty plea.', 'sentencing', 'United States v. David Allen Hagen Defusco, (Two Cases)', 'https://www.courtlistener.com/opinion/572183/', '572183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find DeFus-co’s contention to be totally devoid of merit, and thus we affirm.', 'general', 'United States v. David Allen Hagen Defusco, (Two Cases)', 'https://www.courtlistener.com/opinion/572183/', '572183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, even though a jury instruction on exigent circumstances could have been given under the evidence presented to the jury, because Ferguson struggled with the officers outside of her home when she was in lawful custody of the police, the instruction given accurately set out the law for the officers'' actions at that time.', 'jury_instruction', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury must have decided that the police were acting with lawful authority.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 45 Based on the test set forth in Harvey, we conclude that if the failure to instruct the jury on exigent circumstances was error, it was harmless.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 46 We conclude that, even though a jury instruction on exigent circumstances could have been given under the evidence presented to the jury, because Ferguson struggled with the officers outside of her home when she was in lawful custody of the police, the instruction given accurately set out the law for the officers'' actions at that time.', 'jury_instruction', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that due to the law-declaring function of this court, it is our responsibility to overrule Mikkelson''s incorrect interpretation.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and affirm the circuit court''s judgment of conviction.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1836341/', '1836341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the requirement in Utah Code section
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'his inchoate parental rights, we held that the ―natural mother‘s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we held that a provision of the
