INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and remand for a new sentencing order.', 'sentencing', 'Isaacs v. State', 'https://www.courtlistener.com/opinion/2148871/', '2148871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Isaacs’ convictions.', 'general', 'Isaacs v. State', 'https://www.courtlistener.com/opinion/2148871/', '2148871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Pinkard, we held that officers reasonably exercised their community caretaker function when they entered and searched a residence for two unconscious individuals.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that sending five officers from the unit that performed narcotics investigations "was a reasonable precautionary measure to prepare for another eventuality.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Blatterman''s stop and detention satisfied the reasonableness requirement of the Fourth Amendment of the United States Constitution and Article I, Section 11 of the Wisconsin Consti*151tution because they were supported by reasonable suspicion to conduct an investigatory detention.', 'search_seizure', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that ten miles is too distant a transportation to be within the vicinity so long as the temporary detention is supported by no more than a reasonable suspicion.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that the officer was engaged in a bona fide community caretaker function.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that although Nisius held subjective law enforcement concerns, as we have explained above, those subjective concerns did not negate the objectively reasonable basis for a community caretaker function.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the officer was engaged in a bona fide community caretaker function when he transported Blatterman to the hospital.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the second factor favors the conclusion that the officer reasonably performed his community caretaker function.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the circumstances relevant to this inquiry, we conclude that the fourth factor also weighs in favor of concluding that the officer reasonably exercised his community caretaker function.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the officer was engaged in a bona fide community caretaker function and that he exercised the community caretaker function reasonably under the totality of the circumstances.', 'general', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 217-18 ("We hold that the odor of a controlled substance may provide probable cause to arrest when the odor is unmistakable and may be linked to a specific person or persons .', 'probable_cause', 'State v. Dean M. Blatterman', 'https://www.courtlistener.com/opinion/2798569/', '2798569') ON CONFLICT DO NOTHING;
