INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the use of a hotel room is a thing of value and is, thus, within the statutory definition of property in section 15 — 1, we need not consider whether registration as a guest in a hotel creates a leasehold interest that would be considered a chattel real at common law, as argued by the State, or an interest in real estate.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'CONCLUSION In sum, we hold that the occupancy of a hotel room is “property” within the meaning of section 15 — 1 of the Criminal Code and that the taking of such property by deception can result in the owner’s being permanently deprived of its use or benefit.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
