INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '330, 336 (1937), this court held that the defendant was properly charged with larceny of electrical energy because larceny under the Criminal Code (Ill.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the use of a hotel room is a thing of value as that phrase is used in the first sentence of section 15 — 1.', 'sentencing', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this statutory definition, we conclude that in enacting section 15 — 1 the legislature intended the definition of property to include not only items of tangible personal property, but also other things of value.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Although the specific statements to which defendant is now objecting are not precisely the same statements that he mentioned in his posttrial motions, we conclude that he has adequately preserved this issue and, as a result, our analysis will be guided by the Strickland factors.', 'ineffective_assistance', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the trial court’s admonition to the jury and defense counsel’s counterargument, we conclude that the lack of objection to these statements was not deficient performance by defense counsel.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, with respect to each of the asserted instances of improper comment by the prosecutor, counsel’s performance was either not deficient or, even if deficient, did not result in prejudice to defendant that would require a new trial.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant cannot prevail on this claim because, even if the trial court’s written response to this jury question introduced error, the error is attributable to the trial court, not to ineffective assistance by defense counsel.', 'ineffective_assistance', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the use of a hotel room is a thing of value as that phrase is used in the first sentence of section 15 — 1.', 'sentencing', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the guilt-innocence determination phase of the defendant’s trial was free from prejudicial error.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the evidence as to the wives’ deaths was admissible to show motive as well as knowledge of the effect of poison in the killing for which the defendant was on trial.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '72 (1938), this Court held that evidence of previous poisonings was admissible to show scienter, intent and motive.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing Rule 901, this Court held that the tape recording was properly authenticated.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the guilt-innocence determination phase of the defendant’s trial was free from prejudicial error.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion by allowing these photographs into evidence for the limited purpose of illustrating witnesses’ testimony.', 'general', 'State v. Stager', 'https://www.courtlistener.com/opinion/1354986/', '1354986') ON CONFLICT DO NOTHING;
