INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We hold that defendant’s objections to his death sentence are without merit and, therefore, we affirm his convictions and sentences.', 'sentencing', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the contrary, we hold that all of those proofs were relevant to the aggravating and mitigating factors in this case, that the probative value of those proofs was not substantially outweighed by their claimed unduly prejudicial effect, and that the trial court’s determinations admitting such proofs were not “so wide of the mark that a manifest denial of justice resulted.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that standard, we hold that the cross-examination of defendant’s traumatic brain injury expert, clinical neuropsychiatrist, and developmental psychologist properly addressed these witnesses’ biases, interest and partiality and, hence, was proper.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hazard, defendant “realize[d] that this is a human being” and that he did not care, as well as the third comment that defendant does not have the “light” of compassion or remorse in him, we hold that, because defendant placed his character at issue by virtue of several of the mitigating factors he placed before the jury, it is entirely relevant, and proper, for the prosecution to respond as it did.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that none of the challenged comments improperly placed defendant’s character in issue and, hence, defendant’s objections thereto are unavailing.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we reject defendant’s assertions on appeal and we hold that, in each instance, the trial court’s admission of the victim impact evidence and the State’s use of that victim impact evidence was proper.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
