INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that defendant’s PCR petition is not procedurally barred.', 'general', 'State v. Afanador', 'https://www.courtlistener.com/opinion/2361197/', '2361197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In July 1994, we held that trial courts must instruct juries in a manner consistent with the intent of the Legislature.', 'general', 'State v. Afanador', 'https://www.courtlistener.com/opinion/2361197/', '2361197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that courts should instruct a jury that to meet the definition of a kingpin, a defendant’s position and status must be at a superior level in relation to others in the network and that the defendant has exercised in that capacity supervisory power or control over others engaged in organized drug-trafficking.', 'general', 'State v. Afanador', 'https://www.courtlistener.com/opinion/2361197/', '2361197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that an instruction under the kingpin statute must include more than the statutory language.', 'general', 'State v. Afanador', 'https://www.courtlistener.com/opinion/2361197/', '2361197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In October 1993, this Court held that the drug kingpin statute was not void for vagueness.', 'general', 'State v. Afanador', 'https://www.courtlistener.com/opinion/2361197/', '2361197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division denying post-conviction relief on the drug kingpin count and remand that charge to the Law Division for further proceedings consistent with this opinion.', 'general', 'State v. Afanador', 'https://www.courtlistener.com/opinion/2361197/', '2361197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Realistically, the PCR clock did not begin to run until October 1993 when we affirmed
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Appellate Division concerning the claims of ineffective assistance of counsel and use of perjurious testimony.', 'ineffective_assistance', 'State v. Afanador', 'https://www.courtlistener.com/opinion/2361197/', '2361197') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the absence of an
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the trial court''s imposition of concurrent sentences violates section 5-8-4 of the Code (730 ILCS 5/5-8-4 (West 1998)).', 'sentencing', 'People v. Harris', 'https://www.courtlistener.com/opinion/2252698/', '2252698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that consecutive sentences were required because two factors necessitated the application of section 5-8-4(b) (730 ILCS 5/5-8-4(b) (West 1998)).', 'sentencing', 'People v. Harris', 'https://www.courtlistener.com/opinion/2252698/', '2252698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the appellate court vacating the sentence and remanding for the imposition of consecutive sentences.', 'sentencing', 'People v. Harris', 'https://www.courtlistener.com/opinion/2252698/', '2252698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it can not.', 'general', 'Hudson v. Commonwealth', 'https://www.courtlistener.com/opinion/2409527/', '2409527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a defendant provides to officials in connection with a fraudulent claim a document or oral narrative that contains a material fact or facts relating to the claim, each such document or narration is a “statement” equating to an “act” of insurance fraud.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the connection between the IFPA and the later crime of insurance fraud, defined in similar language, we conclude that the Legislature would have presumed, consistent with our Merin holding, that each document or narrative statement containing materially false facts would be held to be a separate “act” of insurance fraud.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant’s oral and written statements related to a single claim of a stolen automobile, we conclude that the State presented three “acts” of insurance fraud to the grand jury: defendant’s report to the police, defendant’s oral report of the alleged theft to Liberty Mutual, and defendant’s affidavit submitted to Liberty Mutual in support of her claim.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that each document constituted a separate false statement in respect of the fraudulent claim.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that those extrinsic materials are of little assistance in resolving whether discrete facts within a single narrative advanced in furtherance of a fraudulent insurance claim should be considered individual fraudulent “acts.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1256, we found that the defendant had submitted six false statements that were material to his fraudulent claim.', 'general', 'State v. Fleischman', 'https://www.courtlistener.com/opinion/2372106/', '2372106') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we find that no contempt was committed, we need not address Warrick’s contentions as to the sentence imposed.', 'sentencing', 'Warrick v. United States', 'https://www.courtlistener.com/opinion/2257991/', '2257991') ON CONFLICT DO NOTHING;
