INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the |7evidence, viewed in the light most favorable to the State, supports Cantrell’s conviction for possession of drug paraphernalia with intent to manufacture.', 'general', 'Cantrell v. State', 'https://www.courtlistener.com/opinion/2546191/', '2546191') ON CONFLICT DO NOTHING;
