INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[11] Thus, in Smith, an indecent exposure case, we held that the State was required to plead the circumstances under which the defendant exposed himself  such as "in a public place"  to indicate why his otherwise lawful act was reckless.', 'plea', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/2546778/', '2546778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[21] Therefore, we affirm the lower court''s judgment which had upheld the trial judge''s ruling.', 'general', 'State v. Rodriguez', 'https://www.courtlistener.com/opinion/2546778/', '2546778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this evidence constitutes a knowing and willful course of conduct that qualifies as harassment under section 97-3-107(4).', 'general', 'McCALPIN v. State', 'https://www.courtlistener.com/opinion/2549155/', '2549155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that absolute immunity for public officials in their discretionary functions acting in other than true judicial proceedings is not required and, indeed, is improper.', 'general', 'Grimm v. Arizona Board of Pardons & Paroles', 'https://www.courtlistener.com/opinion/2616459/', '2616459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that members of the State Board of Pardons and Paroles owe a duty to individual members of the general public when the Board decides to release on parole a prisoner with a history of violent and dangerous conduct toward his or her fellow human beings.', 'general', 'Grimm v. Arizona Board of Pardons & Paroles', 'https://www.courtlistener.com/opinion/2616459/', '2616459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that members of the Board of Pardons and Paroles have only partial immunity from suit, the trial court''s grant of summary judgment for appellees was error.', 'general', 'Grimm v. Arizona Board of Pardons & Paroles', 'https://www.courtlistener.com/opinion/2616459/', '2616459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the documents sought came under the "other matters" provision of § 12-412 A.', 'general', 'Grimm v. Arizona Board of Pardons & Paroles', 'https://www.courtlistener.com/opinion/2616459/', '2616459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the Superior Court properly instructed the jury that if it found that Collins was an accomplice to the robbery, he could be held responsible for all reasonably foreseeable consequential criminal offenses committed by his confederates in furtherance of the robbery.', 'general', 'Chance v. State', 'https://www.courtlistener.com/opinion/2304700/', '2304700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, the Superior Court’s incorrect instruction actually aided, rather than prejudiced, Travis, and this Court held there was no plain error.', 'general', 'Chance v. State', 'https://www.courtlistener.com/opinion/2304700/', '2304700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing the mother''s conviction, we held that there was no statutory or common law duty in Kentucky requiring the mother "to prevent the commission of the rape," Knox, supra, at 711;', 'general', 'Tharp v. Commonwealth', 'https://www.courtlistener.com/opinion/2337351/', '2337351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In affirming the mother''s conviction, we held that Kentucky law imposes a legal duty upon a parent to make a proper effort to protect his/her child from harm at the hands of another, thus triggering *362 the "legal duty" aspects of KRS 502.', 'general', 'Tharp v. Commonwealth', 'https://www.courtlistener.com/opinion/2337351/', '2337351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the case sub judice, we conclude that at the time Appellant committed the offense of wanton murder by complicity, she had "fair warning" that her failure to make a proper effort to protect her child from her husband''s assaults violated her "legal duty" to do so, as required by KRS 502.', 'general', 'Tharp v. Commonwealth', 'https://www.courtlistener.com/opinion/2337351/', '2337351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence clearly and convincingly supports the conclusion that respondent violated Rule 8.', 'general', 'In Re White', 'https://www.courtlistener.com/opinion/2558572/', '2558572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the findings of fact and conclusions of law set forth below, which are drawn in substantial measure from the Hearing Committee Report, are supported by substantial evidence in the record, viewed as a whole.', 'general', 'In Re White', 'https://www.courtlistener.com/opinion/2558572/', '2558572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Particularly in the context of her many procedural defaults, we conclude that Respondent’s excuse for her failure to file her brief was dishonest.', 'general', 'In Re White', 'https://www.courtlistener.com/opinion/2558572/', '2558572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that even the testimony most adverse to the defense, Stroud’s testimony, established as a matter of law that Petitioner actually believed he was in imminent danger of losing his life or sustaining serious bodily injury, and that a reasonable person of ordinary firmness would have entertained the same belief.', 'general', 'State v. Dickey', 'https://www.courtlistener.com/opinion/2507697/', '2507697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that as a matter of law, Petitioner actually believed he was in imminent danger of losing his life, or sustaining serious bodily injury, and that a reasonable person would have entertained the same belief.', 'general', 'State v. Dickey', 'https://www.courtlistener.com/opinion/2507697/', '2507697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse.', 'general', 'State v. Dickey', 'https://www.courtlistener.com/opinion/2507697/', '2507697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the court of appeals and overturn Petitioner’s conviction.', 'general', 'State v. Dickey', 'https://www.courtlistener.com/opinion/2507697/', '2507697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Fitzpatrick voluntarily initiated the communication with the police by calling Bousquet on these two occasions.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles, we hold that the trial court properly allowed the probation officer to give hearsay testimony concerning Fitzpatrick''s prior violent felony.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this Court holds that these statements are admissible because, after asserting his right to counsel at the initial September 20 interview with Bousquet, it was Fitzpatrick who on his own subsequently and voluntarily initiated contact with the detective.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this Court holds that Fitzpatrick''s parole officer''s advising him to cooperate did not vitiate Fitzpatrick''s voluntary statements.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the State presented competent, substantial evidence to support the conviction.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion in admitting the testimony with regard to Romines'' statements made to the police at the hospital for the limited purpose of impeachment.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that there was no reasonable possibility that Bousquet''s testimony affected the jury verdict, and it was therefore harmless beyond a reasonable doubt.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the composition of the photo array in the instant case was not unduly suggestive.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming, without deciding, that the testimony with regard to the fingernail scrapings was relevant, we conclude that any error in its exclusion was harmless.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this evidence, as we consider all the testimony presented regarding Fitzpatrick''s clothing and the fact the jury viewed the tape, we conclude that the testimony of Bousquet and Fairbanks was not vital to the defense because although they were not able to physically point out Fitzpatrick, they did testify to what he was wearing.', 'general', 'Fitzpatrick v. State', 'https://www.courtlistener.com/opinion/1103334/', '1103334') ON CONFLICT DO NOTHING;
