INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we conclude that Appellant’s motion was a request for a mistrial.', 'mistrial', 'Commonwealth v. Parker', 'https://www.courtlistener.com/opinion/1482141/', '1482141') ON CONFLICT DO NOTHING;
