INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that Appellant’s sufficiency of the evidence claim lacks merit.', 'general', 'Commonwealth v. Parker', 'https://www.courtlistener.com/opinion/1482141/', '1482141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Parker', 'https://www.courtlistener.com/opinion/1482141/', '1482141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 18 For all of the foregoing reasons, we affirm the trial court’s judgment of sentence.', 'sentencing', 'Commonwealth v. Parker', 'https://www.courtlistener.com/opinion/1482141/', '1482141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Sanders v. State', 'https://www.courtlistener.com/opinion/1857516/', '1857516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because Jones’s rap lyrics constituted a true threat to Arnold, the rap song is not protected by the First Amendment.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1875301/', '1875301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In considering the various tests adopted by the circuit courts and various state supreme courts, we conclude that an objective test focusing on how a reasonable person would have taken the statement and using the Dinwiddie factors has the most merit.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1875301/', '1875301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the five Dinwiddie factors to this case, we conclude that Jones’s language constituted a true threat to Arnold.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1875301/', '1875301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing these factors together, we conclude that a reasonable person in Arnold’s position would have taken the rap song as a true threat.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1875301/', '1875301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the adjudication and the disposition.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1875301/', '1875301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the juvenile judge’s decision.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1875301/', '1875301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that expert testimony that there was a 99.', 'general', 'State v. Joon Kyu Kim', 'https://www.courtlistener.com/opinion/1658035/', '1658035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[5] Because we cannot meaningfully distinguish the evidence offered in Boyd from that in the case now before us, we conclude that Boyd controls.', 'general', 'State v. Joon Kyu Kim', 'https://www.courtlistener.com/opinion/1658035/', '1658035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals.', 'general', 'State v. Joon Kyu Kim', 'https://www.courtlistener.com/opinion/1658035/', '1658035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals and hold that the state has not clearly and unequivocally shown that the trial court order suppressing statistical population frequency evidence was erroneous.', 'suppression', 'State v. Joon Kyu Kim', 'https://www.courtlistener.com/opinion/1658035/', '1658035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 884, 891 (1989), we held that an information that tracks the statutory language of an offense but fails to specifically allege a knowledge element that is required by judicial decision to prove the offense was not fatally defective where defendant failed to object below.', 'general', 'State v. Conn', 'https://www.courtlistener.com/opinion/1561546/', '1561546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that the defendant was sufficiently apprised of the charges against him so that he was able to prepare his defense.', 'general', 'State v. Conn', 'https://www.courtlistener.com/opinion/1561546/', '1561546') ON CONFLICT DO NOTHING;
