INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'NOW, THEREFORE, IT IS ORDERED that the judgment of the Superior Court is AFFIRMED in part and REVERSED in part on procedural grounds, and the case is
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(8) We affirm the ruling of the Superior Court that the qualified immunity set forth in § 4001 applies to public defenders.', 'general', 'Browne v. Robb', 'https://www.courtlistener.com/opinion/2076469/', '2076469') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*46 From the foregoing, we hold that the Commonwealth has sustained its burden of proving, beyond a reasonable doubt, the existence of the aggravating circumstance of "killing a prosecution witness to a murder or other felony committed by the defendant .', 'general', 'Commonwealth v. Zettlemoyer', 'https://www.courtlistener.com/opinion/2367165/', '2367165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the death penalty is not "cruel punishment" within the proscription of Art.', 'general', 'Commonwealth v. Zettlemoyer', 'https://www.courtlistener.com/opinion/2367165/', '2367165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this Court held, based upon Furman and the 1976 quintet of same-day United States Supreme Court decisions,[10] that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] For the reasons stated herein, we affirm appellant''s conviction for murder of the first degree, find the sentencing procedures to be valid under both the federal and state constitutions, and uphold the sentence of death.', 'sentencing', 'Commonwealth v. Zettlemoyer', 'https://www.courtlistener.com/opinion/2367165/', '2367165') ON CONFLICT DO NOTHING;
