INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence in this case was legally insufficient to support her conviction under Section 22.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1440936/', '1440936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we cannot conclude that the act of taking a child from a house with working utilities to one without working utilities is the type of conduct that, by its nature, raises a substantial and unjustifiable risk of injury, we hold that it cannot support a finding of reckless injury to a child.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1440936/', '1440936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was not legally sufficient to permit a finding of gross criminal negligence on the part of the appellant and that the charge of manslaughter, therefore, should not have been submitted to the jury_ Alternatively, we hold that the evidence was not legally sufficient to permit a finding that any action of the appellant, even if assumed to have been grossly negligent, was the proximate cause of the decedent’s death and that the charge of manslaughter, therefore, should n...', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1440936/', '1440936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'had not been advised of the maximum total he could be sentenced to consecutively and, indeed, had been sentenced to the maximum total, this Court held that the defendant had demonstrated “prejudice on the order of manifest injustice,” and that, accordingly, he was entitled to withdraw his guilty plea.', 'sentencing', 'Commonwealth v. Carter', 'https://www.courtlistener.com/opinion/1474247/', '1474247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” For the reasons expressed below, we affirm the Superior Court’s affirmance of the judgments of sentence.', 'sentencing', 'Commonwealth v. Carter', 'https://www.courtlistener.com/opinion/1474247/', '1474247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Superior Court’s affirmation of the trial court’s judgment of sentence.', 'sentencing', 'Commonwealth v. Carter', 'https://www.courtlistener.com/opinion/1474247/', '1474247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In both Pruett and Ring, we held that an unintentional crime could not serve as the predicate felony for a weapons charge under § 28-1205.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence, even considered cumulatively, does not support Iromuanya''s assignments of error.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the error was harmless.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that the permissive inference language in instruction No.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the instructions given by the court adequately covered all pertinent matters included in Iromuanya''s proposed "theory of defense" instruction.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the district court did not err in refusing to give Iromuanya''s proposed instruction stating his theory of defense.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming the truth of Iromuanya''s statement to police that when Jenkins approached a second time, he asked if Iromuanya was the person who had punched him previously, we conclude that neither that statement nor any other circumstance reflected in the record would warrant a reasonable or good faith belief in the necessity of using deadly force.', 'general', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking into account all of the relevant circumstances, including but not limited to the fact that Iromuanya had no significant criminal record or history of violence, we conclude that the district court abused its discretion in setting life imprisonment as the minimum term of the sentence for second degree murder and that to that extent, the sentence was excessive.', 'sentencing', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence imposed by the district court of not less than life imprisonment nor more than life imprisonment on count III, murder in the second degree, is excessive, and we modify that sentence to not less than 50 years'' imprisonment nor more than life imprisonment, with the sentence on count III to be served concurrently with the sentence on count I.', 'sentencing', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that because the defendant was found guilty of two distinct predicate offenses, attempted second degree murder and first degree assault, the trial court did not err in imposing consecutive sentences on the two corresponding convictions for use of a weapon to commit a felony.', 'sentencing', 'State v. Iromuanya', 'https://www.courtlistener.com/opinion/1693833/', '1693833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" That being the case, we hold that the offense charged in Count II was "subsequent" to the offense charged in Count I, within the plain meaning of HRS § 709-906(5)(b).', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the family court did not abuse its discretion in applying the repeat offender provision of HRS § 709-906(5)(b) to Count II of the complaint.', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 288 (1979), despite a clear and unambiguous legislative historyas reflected in the relevant committee reportsof an intent to accomplish a particular result in amending the drug laws, this court held, by virtue of the plain language of its statutory work product, that "the [L]egislature did not carry its intention into effect.', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mattiello, this court held that a facial conflict existed between the language of HRS § 712-1240 (1993), which provided in relevant part that, "as applied to liquids," "`[o]unce'' means .', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') This court held that "the juxtaposition of the words `weight'' and `ounce'' in HRS § 712-1241(1)(b)(ii)(B) injects some ambiguity into the meaning of the term `ounce.', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 25, 26 (1991) ("Since the defendant did not expressly waive the right to appeal his sentence on the plea, nor was this issue mentioned at his plea hearing, we find that his right to appeal the sentence was not waived.', 'sentencing', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the family court''s judgment, guilty conviction, and sentence.', 'sentencing', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we affirm the family court''s judgment, guilty conviction, and sentence.', 'sentencing', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the found circumstances, we hold that the district court properly imputed knowledge of potential adult prosecution to Fardan.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the absence of Fardan''s father did not invalidate Fardan''s waiver of his Miranda rights.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on all of these factors, we hold that the district court did not abuse its discretion in admitting the evidence of the later robbery, burglary, kidnapping and shootings into the trunk.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the prejudicial impact of the criminal sexual conduct evidence outweighs any limited probative value, we hold that it was an *320 abuse of discretion to admit evidence of Fardan''s criminal sexual conduct.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was sufficient to support the conviction for intentional felony murder.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The evidence supports the court''s findings, and we hold that the court did not abuse its discretion in sentencing.', 'sentencing', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is no reasonable possibility that the erroneous admission of Fardan''s criminal sexual conduct *321 significantly affected the jury''s verdict, and hold that the district court''s erroneous admission of the evidence was not reversible error.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But, as Fardan notes, in Burrell, we concluded that a Miranda waiver was ineffective primarily because of the lack of a parent''s presence.', 'ineffective_assistance', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Courtney, we concluded that Spreigl evidence of a domestic assault was erroneously admitted to inform on the defendant''s intent to point a gun at a police officer.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that evidence that the defendant was armed with a pistol when he accosted the victim and shot him at close range would "alone" be sufficient for the jury''s finding of intentional murder.', 'general', 'State v. Fardan', 'https://www.courtlistener.com/opinion/1905193/', '1905193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred when it gave the jury the definition of "maliciously" included in the standard jury instruction, rather than that adopted by the court in Gaylord, and requested by appellant.', 'jury_instruction', 'Reed v. State', 'https://www.courtlistener.com/opinion/1146460/', '1146460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To resolve the question of what cases this decision is to be applied to, we hold that this decision shall be retroactively applied to cases pending on direct review or not yet final.', 'general', 'Reed v. State', 'https://www.courtlistener.com/opinion/1146460/', '1146460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Delva, we held that it was fundamental error to give a standard jury instruction which contained an erroneous statement as to the knowledge element of the charged crime.', 'jury_instruction', 'Reed v. State', 'https://www.courtlistener.com/opinion/1146460/', '1146460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure to use the correct definition is fundamental error in cases in which the essential element of malice was disputed at trial.', 'general', 'Reed v. State', 'https://www.courtlistener.com/opinion/1146460/', '1146460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his conviction.', 'general', 'State v. Dalton', 'https://www.courtlistener.com/opinion/1837614/', '1837614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Melvin Dalton’s conviction for vehicular homicide.', 'general', 'State v. Dalton', 'https://www.courtlistener.com/opinion/1837614/', '1837614') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that our decision in In re May 1991 Will County Grand Jury is inapposite to the facts in the matter before us.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant has failed to satisfy his burden to clearly establish that the Internet dissemination provisions contained in section 115(b) of the Notification Law violate his right to privacy under the Illinois Constitution.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the amendment to the Notification Law allowing for Internet dissemination of sex offender data— public information which is already available by other means — bears a rational relationship to these goals.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant has failed to clearly establish that section 115(b) of the Notification Law violates substantive due process under the Illinois Constitution.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that defendant had “utterly failed” to satisfy his burden of showing that the challenged statutes were unconstitutional.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, under the specific circumstances presented in that case, the privacy protections guaranteed under the Illinois Constitution required that there be a showing of individualized suspicion, as well as relevance, before physical evidence of a noninvasive nature — such as an in-person appearance for a lineup or fingerprinting — is demanded of a witness.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was no showing by the State that relevance and individualized suspicion were established before the subpoenas requiring the men to submit to a lineup and fingerprinting were issued, this court held that the subpoenas should have been quashed.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, with respect to the demand that the men submit hair samples, this court held that such a request is a far greater intrusion into an individual’s personal privacy than requesting evidence of a noninvasive nature and, therefore, is reasonable only when warranted by probable cause.', 'probable_cause', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, informed by the analysis of the Supreme Court in Smith, we conclude that Illinois may permissibly use the Internet dissemination of sex offender registry information as a “more efficient, cost effective and convenient” means of providing its citizens with important public information.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Using the rational basis test, we conclude that the Internet provisions of section 115(b) of the Notification Law bear a rational relationship to the purpose the legislature intended to achieve in enacting that statute.', 'general', 'People v. Cornelius', 'https://www.courtlistener.com/opinion/2133841/', '2133841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that there is sufficient evidence in the record to support the robbery conviction.', 'general', 'State v. Knutson', 'https://www.courtlistener.com/opinion/1119931/', '1119931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the record shows that Knutson made a forced entry into the home, we hold that the required intent to commit a theft, at the time Knutson entered the home, has been established by the evidence.', 'general', 'State v. Knutson', 'https://www.courtlistener.com/opinion/1119931/', '1119931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this undisputed testimony, we hold that the burglary conviction is supported by substantial evidence.', 'general', 'State v. Knutson', 'https://www.courtlistener.com/opinion/1119931/', '1119931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that it was not reversible error for the leg restraint to have been briefly left on the defendant at the start of jury selection.', 'general', 'State v. Knutson', 'https://www.courtlistener.com/opinion/1119931/', '1119931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the temporary leg restraint did not prejudice the jury, even if it was seen by a few of the prospective jurors prior to jury selection.', 'general', 'State v. Knutson', 'https://www.courtlistener.com/opinion/1119931/', '1119931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Knutson’s robbery sentence was not excessive.', 'sentencing', 'State v. Knutson', 'https://www.courtlistener.com/opinion/1119931/', '1119931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons explained below, we affirm the judgment of conviction as to each offense, and we uphold the sentence for robbery.', 'sentencing', 'State v. Knutson', 'https://www.courtlistener.com/opinion/1119931/', '1119931') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was erroneously admitted.', 'general', 'State v. McCary', 'https://www.courtlistener.com/opinion/2462824/', '2462824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this evidence of the defendant’s guilt of each crime more than satisfies the standard prescribed in Tenn.', 'general', 'State v. Ivy', 'https://www.courtlistener.com/opinion/1728598/', '1728598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it should have been charged to the jury.', 'general', 'State v. Ivy', 'https://www.courtlistener.com/opinion/1728598/', '1728598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The defendant neither argues nor do we find that the evidence raised the issue of self-defense as to the aggravated assault on the victim Brown.', 'general', 'State v. Ivy', 'https://www.courtlistener.com/opinion/1728598/', '1728598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction resulting in the three-year sentence and remand for a new trial.', 'sentencing', 'State v. Ivy', 'https://www.courtlistener.com/opinion/1728598/', '1728598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the motion is deemed denied pursuant to Arkansas Rule of Criminal Procedure 33.', 'general', 'Burley v. State', 'https://www.courtlistener.com/opinion/2105668/', '2105668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that decision, we held that, the burden of obtaining a ruling is on the movant, and the failure to secure a ruling constitutes a waiver, precluding its consideration on appeal.', 'general', 'Burley v. State', 'https://www.courtlistener.com/opinion/2105668/', '2105668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Burley v. State', 'https://www.courtlistener.com/opinion/2105668/', '2105668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1(c), and we affirm.', 'general', 'Burley v. State', 'https://www.courtlistener.com/opinion/2105668/', '2105668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'No abuse occurred here, therefore we affirm the trial court.', 'general', 'Burley v. State', 'https://www.courtlistener.com/opinion/2105668/', '2105668') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'was placed on notice of his criminal conduct and was not prejudiced by the amendment, this court held that it was permissible even though it involved a “substantive” change.', 'general', 'Commonwealth v. Grekis', 'https://www.courtlistener.com/opinion/2188709/', '2188709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under the circumstances of this case, the trial court properly permitted the amendment of the information.', 'general', 'Commonwealth v. Grekis', 'https://www.courtlistener.com/opinion/2188709/', '2188709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the amendment did not constitute error.', 'general', 'Commonwealth v. Grekis', 'https://www.courtlistener.com/opinion/2188709/', '2188709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that trial counsel here could not have prevailed in an effort to exclude the testimony regarding the act of oral sex from evidence and that therefore, counsel cannot be ineffective for failing to object to the testimony.', 'ineffective_assistance', 'Commonwealth v. Grekis', 'https://www.courtlistener.com/opinion/2188709/', '2188709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that the “charge of aggravated assault and criminal attempt murder arose out of the same set of facts” and that “under the particular facts of this case, the crimes charged involved the same basic elements.', 'general', 'Commonwealth v. Grekis', 'https://www.courtlistener.com/opinion/2188709/', '2188709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'prove a wilful disobedience of the court’s mandate and the accuser sat in judgment of the defendant, we reverse the trial court.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/1168258/', '1168258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we reverse the defendant’s conviction.', 'general', 'State v. Brown', 'https://www.courtlistener.com/opinion/1168258/', '1168258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence imposed is not excessive, and it is affirmed.', 'sentencing', 'State v. Reinke', 'https://www.courtlistener.com/opinion/1188198/', '1188198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the sentence.', 'sentencing', 'State v. Reinke', 'https://www.courtlistener.com/opinion/1188198/', '1188198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), this Court held that when an accused wields a weapon that is without question deadly and then intentionally strikes his victim, he is not entitled to a lesser included offense instruction for simple assault, even if the injury is relatively slight.', 'general', 'Hoops v. State', 'https://www.courtlistener.com/opinion/1809345/', '1809345') ON CONFLICT DO NOTHING;
