INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons subsequently discussed in this opinion, we conclude that the trial court applied inappropriate sentencing considerations.', 'sentencing', 'State v. Zeolia', 'https://www.courtlistener.com/opinion/2416465/', '2416465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, despite the appellant’s juvenile history of unruliness adjudications, we conclude that he should be afforded a presumption favoring the imposition of an alternative sentence.', 'sentencing', 'State v. Zeolia', 'https://www.courtlistener.com/opinion/2416465/', '2416465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this testimony is insufficient to establish a need for general deterrence.', 'general', 'State v. Zeolia', 'https://www.courtlistener.com/opinion/2416465/', '2416465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the appellant’s participation in the burning of four bams within one forty-eight hour period is directly relevant to the seriousness of the offense and weighs in favor of confinement.', 'general', 'State v. Zeolia', 'https://www.courtlistener.com/opinion/2416465/', '2416465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the appellant’s mental condition does not significantly mitigate the seriousness of the offense.', 'general', 'State v. Zeolia', 'https://www.courtlistener.com/opinion/2416465/', '2416465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, for the reasons discussed above, we conclude that the State has met its burden and adequately demonstrated that the circumstances of the offense and the circumstances of this appellant call for confinement in the Department of Correction.', 'general', 'State v. Zeolia', 'https://www.courtlistener.com/opinion/2416465/', '2416465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we affirm the judgment of the trial court.', 'general', 'State v. Zeolia', 'https://www.courtlistener.com/opinion/2416465/', '2416465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the record, we find that although the shotgun, shells, and photographs were irrelevant and should have been excluded, other evidence negatived prejudice from error in admitting that irrelevant evidence;', 'general', 'State v. Messersmith', 'https://www.courtlistener.com/opinion/2218193/', '2218193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, we find that Messersmith’s assignment of error based on the district court’s refusal to give a restrictive instruction authorized under Rule 105 has no merit.', 'general', 'State v. Messersmith', 'https://www.courtlistener.com/opinion/2218193/', '2218193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, since none of Messersmith’s assignments of error have merit, we affirm Messersmith’s convictions and sentences.', 'sentencing', 'State v. Messersmith', 'https://www.courtlistener.com/opinion/2218193/', '2218193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the residence registration requirements of the current statute do not apply to such homeless offenders.', 'general', 'State v. Iverson', 'https://www.courtlistener.com/opinion/1822587/', '1822587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Iv-erson did not waive the argument that his plea was not supported by a sufficient factual basis and remand for further proceedings consistent with this opinion.', 'plea', 'State v. Iverson', 'https://www.courtlistener.com/opinion/1822587/', '1822587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Iverson has not waived his argument that the residence registration requirements of the statute do not apply to him if he is a homeless person.', 'general', 'State v. Iverson', 'https://www.courtlistener.com/opinion/1822587/', '1822587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reason, we conclude that a bald assertion that one is homeless may not preclude application of the residence requirements of the statute.', 'general', 'State v. Iverson', 'https://www.courtlistener.com/opinion/1822587/', '1822587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such a result is appropriate in this case as well.', 'general', 'State v. Iverson', 'https://www.courtlistener.com/opinion/1822587/', '1822587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgments of conviction entered against the appellant on counts 1, 4, and 7, charging her with possession with intent to deliver a controlled substance.', 'general', 'State v. Hardesty', 'https://www.courtlistener.com/opinion/1375288/', '1375288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we reverse the judgments of conviction entered against the appellant on indictment counts 1, 4, and 7, charging her with possession with intent to deliver a controlled substance.', 'general', 'State v. Hardesty', 'https://www.courtlistener.com/opinion/1375288/', '1375288') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trooper did not articulate sufficient facts to support probable cause to arrest appellant.', 'probable_cause', 'Torres v. State', 'https://www.courtlistener.com/opinion/1796535/', '1796535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in denying appellant''s motion to suppress.', 'suppression', 'Torres v. State', 'https://www.courtlistener.com/opinion/1796535/', '1796535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing de novo the determination of probable cause for a warrantless search and seizure in this case, we conclude that, given the totality of the circumstances, the state failed to carry its burden to justify the warrantless arrest of appellant.', 'probable_cause', 'Torres v. State', 'https://www.courtlistener.com/opinion/1796535/', '1796535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the court of appeals.', 'general', 'Torres v. State', 'https://www.courtlistener.com/opinion/1796535/', '1796535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', this court held the Act is not punitive as applied to juveniles and, therefore, does not constitute cruel and unusual punishment.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, unlike the death penalty, the Act’s registration requirement cannot be considered a punishment.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the minor was “released on probation” within the meaning of section 5 of the Act.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain language of the Act imposes a clear nondiscretionary duty upon the respondent to order the minor to register, and the respondent has clear authority to comply with a mandamus order requiring that action.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the recent amendments to the Act, we conclude that the State has acted reasonably in imposing the registration obligation upon the minor.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given this different treatment, we conclude that the procedural protections in place for juvenile adjudications, along with the amendment allowing the minor the additional procedural right to seek termination of his registration after five years, are sufficient to satisfy the minor’s constitutional right to procedural due process.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has satisfied all elements necessary for issuance of a mandamus order.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the plain language of the Act clearly requires the minor to register and imposes a clear nondiscretionary duty upon the respondent to advise the minor of his obligation to register.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that mandamus is an appropriate remedy to compel compliance with the mandatory terms of the Act requiring the minor to register.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these circumstances, we find that the minor’s registration obligation is not sufficiently burdensome to mandate the additional procedural protection of a jury trial.', 'general', 'People Ex Rel. Birkett v. Konetski', 'https://www.courtlistener.com/opinion/2143121/', '2143121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did.', 'general', 'People v. Huddleston', 'https://www.courtlistener.com/opinion/1997121/', '1997121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that section 12 — 14.', 'general', 'People v. Huddleston', 'https://www.courtlistener.com/opinion/1997121/', '1997121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the circuit court and remand the cause for resentencing.', 'sentencing', 'People v. Huddleston', 'https://www.courtlistener.com/opinion/1997121/', '1997121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering all of the circumstances surrounding the prosecution’s question, we conclude that this alleged incident of prosecutorial misconduct was properly cured by the cautionary instruction given.', 'general', 'Commonwealth v. LaCava', 'https://www.courtlistener.com/opinion/2381563/', '2381563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, after considering all of the circumstances surrounding this conduct, we conclude that any prosecutorial misconduct which arose was properly cured by this cautionary instruction.', 'general', 'Commonwealth v. LaCava', 'https://www.courtlistener.com/opinion/2381563/', '2381563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this instruction clearly set forth a correct and useful principle of law and limited the purpose for which the evidence was offered.', 'general', 'Commonwealth v. LaCava', 'https://www.courtlistener.com/opinion/2381563/', '2381563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this instruction cured any potential impropriety that may have been arguably aroused by the comment.', 'general', 'Commonwealth v. LaCava', 'https://www.courtlistener.com/opinion/2381563/', '2381563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At the outset, we find that the trial court’s prompt and accurate cautionary instruction amply clarified that appellant bore no burden of proof at his trial.', 'general', 'Commonwealth v. LaCava', 'https://www.courtlistener.com/opinion/2381563/', '2381563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because appellant correctly argues that the prosecutor’s comments during the penalty phase were so prejudicial as to deprive him of a fair penalty determination, we find that trial counsel had no reasonable basis for failing to object to these comments which left the jury with a fixed bias against appellant based upon comments not grounded in evidence of record.', 'general', 'Commonwealth v. LaCava', 'https://www.courtlistener.com/opinion/2381563/', '2381563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm appellant’s convictions but vacate the sentence of death and remand the matter back to the trial court for a new sentencing hearing on appellant’s murder conviction.', 'sentencing', 'Commonwealth v. LaCava', 'https://www.courtlistener.com/opinion/2381563/', '2381563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that once the jury has been properly instructed on the reasonable doubt standard of proof, the defendant is not entitled to an additional instruction on circumstantial evidence even when all the evidence is circumstantial.', 'general', 'State v. Sheahan', 'https://www.courtlistener.com/opinion/2584053/', '2584053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that any evidence of resisting the unlawful arrest should be excluded.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1655478/', '1655478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the trial court erred in denying the defense''s proposed instructions.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1655478/', '1655478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Taylor this Court held that there is a crime of attempted manslaughter but that a conviction of such offense requires proof of a certain degree of criminal intent on the part of the defendant;', 'general', 'Tillman v. State', 'https://www.courtlistener.com/opinion/1816803/', '1816803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that no reversible error affects petitioner''s conviction of attempted manslaughter.', 'general', 'Tillman v. State', 'https://www.courtlistener.com/opinion/1816803/', '1816803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With regard to the certified question, we find that it is controlled by our decision in Taylor v.', 'general', 'Tillman v. State', 'https://www.courtlistener.com/opinion/1816803/', '1816803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon completing our review of the arguments, relevant statutes, applicable case law and commentary, we conclude that West Virginia Code § 62-12-26 is not facially unconstitutional on these grounds.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/2504769/', '2504769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the above discussion, we conclude that West Virginia Code § 62-12-26 does not facially violate due process principles of the Fourteenth Amendment to the Constitution of the United States or Article III, Section 10 of the Constitution of West Virginia.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/2504769/', '2504769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result of the foregoing analysis we conclude that the imposition of the legislatively mandated additional punishment of a period of supervised release as an inherent part of the sentencing scheme for certain offenses enumerated in West Virginia Code § 62-12-26 (2009) does not on its face violate the double jeopardy provisions contained in either the United States Constitution or the West Virginia Constitution.', 'sentencing', 'State v. James', 'https://www.courtlistener.com/opinion/2504769/', '2504769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that West Virginia Code § 62-12-26 is not facially unconstitutional on cruel and unusual punishment grounds in contravention of the Eighth Amendment to the United States Constitution or Article III, § 5 of the West Virginia Constitution.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/2504769/', '2504769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the appealed September 2, 2009, sentencing order of the Circuit Court of Ohio County, the August 10, 2009, sentencing order of the Circuit Court of Mineral County and the July 20, 2010, sentencing order of the Circuit Coui’t of Logan County.', 'sentencing', 'State v. James', 'https://www.courtlistener.com/opinion/2504769/', '2504769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the police were not justified in frisking Holden because the police failed to articulate any reasonable concern for their safety, nor would a reasonable person have believed that Holden
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 2 We hold that A.', 'general', 'State v. Bonnewell', 'https://www.courtlistener.com/opinion/2636839/', '2636839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the class created here is elastic.', 'general', 'State v. Bonnewell', 'https://www.courtlistener.com/opinion/2636839/', '2636839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As part of our decision that section 17-301(D) is not a special law, we concluded that it is rationally related to a legitimate purpose.', 'general', 'State v. Bonnewell', 'https://www.courtlistener.com/opinion/2636839/', '2636839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our view, there is a far greater imperative to rethink a precedent when amendatory or corrective measures are exclusively within this Court’s province — as where a rule of judicial procedure is at issue, or where we hold that the Constitution commands a particular result.', 'general', 'Kendrick v. DA OF PHILADELPHIA COUNTY', 'https://www.courtlistener.com/opinion/1979148/', '1979148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and when this Court holds that a statute does not encompass certain conduct, we do not have a “choice” in determining whether to give retroactive effect to our holding.', 'general', 'Kendrick v. DA OF PHILADELPHIA COUNTY', 'https://www.courtlistener.com/opinion/1979148/', '1979148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1109 (1993), a case involving Fiore’s co-defendant (and general manager of the facility), this Court held that the charged conduct under Section 401(a) was not criminal because Scarpone had a permit.', 'general', 'Kendrick v. DA OF PHILADELPHIA COUNTY', 'https://www.courtlistener.com/opinion/1979148/', '1979148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affect legislation when we affirm, alter, or overrule our prior decisions concerning a statute or when we declare it null and void, as unconstitutional.', 'general', 'Kendrick v. DA OF PHILADELPHIA COUNTY', 'https://www.courtlistener.com/opinion/1979148/', '1979148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the district court erred in granting Sheldon’s suppression motion.', 'suppression', 'State v. Sheldon', 'https://www.courtlistener.com/opinion/2572601/', '2572601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'where we held that a traffic stop had been impermissi-bly extended by unrelated questioning, we noted: “[T]he State does not contend, and the facts would not support a finding, that [the officer] possessed reasonable suspicion that would justify a detention to investigate any offense other than the speeding offense that motivated the initial stop.', 'general', 'State v. Sheldon', 'https://www.courtlistener.com/opinion/2572601/', '2572601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Sheldon', 'https://www.courtlistener.com/opinion/2572601/', '2572601') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 443 (1994), we held that "a stop and frisk may be supported by a police radio bulletin only if evidence is offered at the suppression hearing establishing the articulable facts which support the reasonable suspicion.', 'suppression', 'Commonwealth v. Hawkins', 'https://www.courtlistener.com/opinion/1969512/', '1969512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances in this case, including the limited ability of the officers to confirm all of the anonymous tip information, the report that the occupants of the car possessed a gun, and the statistical likelihood that the gun was illegal, we conclude that the intrusion upon the privacy of the car''s occupants was minimal and that the officers had a reasonable suspicion under Terry that authorized their opening of the car doors and questioning the occupants.', 'general', 'Commonwealth v. Hawkins', 'https://www.courtlistener.com/opinion/1969512/', '1969512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant’s claim was cognizable on post-conviction review and we therefore remand the matter to the trial court for an evidentiary hearing.', 'general', 'State v. Preciose', 'https://www.courtlistener.com/opinion/2309234/', '2309234') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that it was error to dismiss defendant’s post-conviction relief application on procedural grounds.', 'dismissal', 'State v. Preciose', 'https://www.courtlistener.com/opinion/2309234/', '2309234') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 669, we held that “an error [that] denies fundamental fairness in a constitutional sense and hence denies due process of law” can be asserted in post-conviction proceedings as long as it was not litigated previously.', 'general', 'State v. Preciose', 'https://www.courtlistener.com/opinion/2309234/', '2309234') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts set forth in defendant’s papers, we conclude that he has established a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that defendant did not have a reasonable opportunity to raise his claim in an earlier proceeding.', 'general', 'State v. Preciose', 'https://www.courtlistener.com/opinion/2309234/', '2309234') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that contention plausible and less speculative than other types of counsel errors.', 'general', 'State v. Preciose', 'https://www.courtlistener.com/opinion/2309234/', '2309234') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division and remand to the trial court for an evidentiary hearing on defendant’s ineffective-assistance-of-counsel claim and a new determination of the merits of that claim.', 'ineffective_assistance', 'State v. Preciose', 'https://www.courtlistener.com/opinion/2309234/', '2309234') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the evidence was relevant as part of a prolonged criminal episode demonstrating Zack''s motive, intent, modus operandi, and the entire context from which this murder arose.', 'general', 'Zack v. State', 'https://www.courtlistener.com/opinion/1907107/', '1907107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, in light of the ample evidence produced at trial, we conclude that there is no reasonable possibility that the objected-to comments contributed to the jury''s verdict.', 'general', 'Zack v. State', 'https://www.courtlistener.com/opinion/1907107/', '1907107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellate counsel was *1210 not ineffective for failing to raise this non-meritorious issue on appeal.', 'ineffective_assistance', 'Zack v. State', 'https://www.courtlistener.com/opinion/1907107/', '1907107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this claim, we find that the trial court properly summarily denied relief.', 'general', 'Zack v. State', 'https://www.courtlistener.com/opinion/1907107/', '1907107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm the trial court''s order denying postconviction relief, and we deny relief on Zack''s petition for writ of habeas corpus.', 'habeas', 'Zack v. State', 'https://www.courtlistener.com/opinion/1907107/', '1907107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, the trial court properly summarily denied relief on this claim, and we affirm the trial court''s denial.', 'general', 'Zack v. State', 'https://www.courtlistener.com/opinion/1907107/', '1907107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the trial court''s denial of postconviction relief.', 'general', 'Zack v. State', 'https://www.courtlistener.com/opinion/1907107/', '1907107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s order denying postconviction relief, and we deny relief on Zack''s petition for writ of habeas corpus.', 'habeas', 'Zack v. State', 'https://www.courtlistener.com/opinion/1907107/', '1907107') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we hold that error harmless beyond a reasonable doubt.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court reporter''s tapes are the substantial equivalent of the transcript and satisfy Britt''s articulation of the accused''s entitlement in the premises.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Hansen waived any claims he may have in the premises by not asserting them prior to trial and, in the alternative, that the Circuit Court cured any error under the authority of Section 99-15-41.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the present error was harmless beyond a reasonable doubt.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), we held that Rules 1.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1986), this Court held such instructions were properly refused.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For present purposes, we find that the grand jury process leading to indictment, coupled with the four-day pre-trial hearings, afforded Hansen substantially all the benefits, including discovery, he may reasonably have expected at a preliminary hearing.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Circuit Court''s process complied fully with the Turner-Berry-Mackbee mandate and that Instruction No.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is true in West a prosecution witness, previously disclosed in discovery, developed new testimony the day of trial and we reversed.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed because the prosecution was allowed to present to the jury a previously undisclosed expert theory explaining the defendant''s conduct at the time of the murder.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1829968/', '1829968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that Thomas waived all but one of his appellate arguments by failing to make specific and timely objections at trial.', 'general', 'Thomas v. Commonwealth', 'https://www.courtlistener.com/opinion/1411697/', '1411697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the issue he preserved for appeal, we hold that the trial court did not abuse its discretion in admitting the contested evidence.', 'general', 'Thomas v. Commonwealth', 'https://www.courtlistener.com/opinion/1411697/', '1411697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Thomas waived all but one of his arguments by not properly raising them at trial.', 'general', 'Thomas v. Commonwealth', 'https://www.courtlistener.com/opinion/1411697/', '1411697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm Thomas''s conviction.', 'general', 'Thomas v. Commonwealth', 'https://www.courtlistener.com/opinion/1411697/', '1411697') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a charging instrument, be it an indictment, complaint, or information, must include all “allegations, which if proved, would result in the application of a statute enhancing the penalty of the crime committed.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”14 Consistent with this requirement, we held that the “better rule is to include in the indictment the allegations, which if proved, would result in application of a statute enhancing the penalty for the crime committed.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Maugaotega II, this court held that HRS § 706-662 (Supp.', 'general', 'State v. Jess', 'https://www.courtlistener.com/opinion/2633019/', '2633019') ON CONFLICT DO NOTHING;
