INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Murray, this court held that the mere approaching and questioning of a person seated in a parked vehicle does not constitute a seizure and listed many decisions from other jurisdictions that had reached the same conclusion.', 'general', 'People v. Luedemann', 'https://www.courtlistener.com/opinion/2008176/', '2008176') ON CONFLICT DO NOTHING;
