INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 32 For all of the foregoing reasons, we affirm the trial court’s judgment of sentence and dismiss Appellant’s ineffective assistance of counsel claim pursuant to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '55 (1971), where we held that a State Supreme Court''s rejection of an accused''s pretrial plea of former jeopardy constituted a “final” order for purposes of our appellate jurisdiction under 28 U.', 'plea', 'Abney v. United States', 'https://www.courtlistener.com/opinion/109677/', '109677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thereafter, this Court held that the Court of Appeals had jurisdiction under § 1291 to entertain an appeal from the District Court’s pretrial order.', 'general', 'Abney v. United States', 'https://www.courtlistener.com/opinion/109677/', '109677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although it is true that a pretrial order denying a motion to dismiss an indictment on double jeopardy grounds lacks the finality traditionally considered indispensable to appellate review, we conclude that such orders fall within the “small class of cases” that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that pretrial orders rejecting claims of former jeopardy, such as that presently before us, constitute “final decisions” and thus satisfy the jurisdictional prerequisites of § 1291.', 'general', 'Abney v. United States', 'https://www.courtlistener.com/opinion/109677/', '109677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2001), we held that the detective''s testimony that McCary
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"   We find that this
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'marijuana with the intent to distribute, we reverse in part and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'marijuana with the intent to distribute, and we reverse his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the trial
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Kelly''s conviction for possession of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that physical evidence obtained as a result of statements made in contravention of Miranda is excludable under Article 10 of the Vermont Constitution.', 'general', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', where we held that simply feeling a plastic baggie during the course of a legal pat-down did not provide an officer with the requisite probable cause to seize the baggie.', 'probable_cause', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that the threshold determination of whether a reasonable expectation of privacy is implicated is not met.', 'general', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that a seizure in this circumstance is justified under Article 11 of the Vermont Constitution and under the Fourth Amendment.', 'search_seizure', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With regard to the court''s inference that defendant was engaged in selling drugs, we conclude that this inference was relevant to sentencing because it shed light on the nature of the crime and defendant''s proclivities.', 'sentencing', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the officer had probable cause to open the pouch even absent defendant''s consent, we do not reach this issue.', 'probable_cause', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we concluded that "mere possession of a plastic bag in a pocket is [not] sufficiently incriminating to render it immediately apparent that the contents of that bag are contraband.', 'general', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it was undisputed that the marijuana plants in that case were a fruit of the unwarned interrogation, we found that the trial court erred in failing to suppress them.', 'suppression', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lambert, we reversed a sentence where the sentencing court "specifically attempted to establish a minimum equal to the maximum term" by imposing a sentence of not less than twenty-four months or more than two years.', 'sentencing', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction on all three charges, reverse the sentence for cocaine possession, and remand for resentencing on this charge.', 'sentencing', 'State v. Delaoz', 'https://www.courtlistener.com/opinion/1043788/', '1043788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the record supports the suppression court’s conclusion that the officers viewed the contraband from a lawful vantage point.', 'suppression', 'Commonwealth v. Gibbs', 'https://www.courtlistener.com/opinion/1913985/', '1913985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review, we affirm.', 'general', 'Commonwealth v. Gibbs', 'https://www.courtlistener.com/opinion/1913985/', '1913985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Article 46.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of the voir dire, we hold that the record supports the trial court''s implicit finding that Blake was capable of discarding any preconceived conclusions he may have had and would follow the law as given to him by the court.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err by overruling appellant''s motion to suppress and admitting his confessions into evidence.', 'suppression', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not err in admitting the exhibits.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that appellant''s point of error 30 is without merit and is overruled.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the deceased''s statement to Peters was admissible as a spontaneous exclamation.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that the defendant''s mother''s mental health records were admissible where defendant was attempting to show that his childhood was unstable because his mother was hospitalized for mental problems for years and, as a result, the children were sent to live with various relatives.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In appellant''s prior case, this Court held that, although a defendant does have the statutory right to have the issue of voluntariness submitted to the jury, he is not entitled to have it resubmitted at the penalty phase when such issues have already been submitted at guilt/innocence.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the record, we conclude that appellant has failed to show that publicity created a prejudice so great as to prevent a fair trial.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a review of each exhibit, we conclude that any objectionable hearsay seems to involve appellant''s disciplinary problems as a youth, his activities concerning arson, his previous rape conviction, and his alleged homosexuality.', 'general', 'Penry v. State', 'https://www.courtlistener.com/opinion/2372264/', '2372264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that although intent is not specifically mentioned in the portion of the second degree arson statute which refers to one who “aids, counsels or procures the burning of a building”, criminal intent is required as a necessary element of the crime.', 'general', 'Riley v. State', 'https://www.courtlistener.com/opinion/2580971/', '2580971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we held that the wife could be held accountable as an accomplice to the first-degree assault only if the State proved that she acted
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a defendant does not intend “to promote or facilitate” the commission of such an offense unless the defendant intends that the prohibited result occur.', 'general', 'Riley v. State', 'https://www.courtlistener.com/opinion/2580971/', '2580971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that even though a person could be convicted of first-degree assault as a principal upon proof that they acted recklessly with respect to the prohibited result, a person could not be convicted as an accomplice unless the State proved a different, higher culpable mental state.', 'general', 'Riley v. State', 'https://www.courtlistener.com/opinion/2580971/', '2580971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we held that whenever the underlying crime requires proof of a particular result, the statutory requirement that an accomplice “inten[d] to promote or facilitate the commission of the offense” means that the State must prove that the defendant acted “intentionally” with respect to this prohibited result.', 'general', 'Riley v. State', 'https://www.courtlistener.com/opinion/2580971/', '2580971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But this Court held that the wife’s complicity could not be premised on recklessness.', 'general', 'Riley v. State', 'https://www.courtlistener.com/opinion/2580971/', '2580971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instruction did not amount to plain error for two reasons: first, the instruction was not obviously flawed, but only potentially ambiguous on the question of the required culpable mental state;', 'jury_instruction', 'Riley v. State', 'https://www.courtlistener.com/opinion/2580971/', '2580971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have done so and, for the reasons explained here, we conclude that we misstated the law of complicity in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The challenged jury instruction on complicity, and why we conclude that this instruction did not constitute plain eiror under the Echols rule
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we conclude that the parties’ closing arguments cured the potential ambiguity in the complicity instruction.', 'general', 'Riley v. State', 'https://www.courtlistener.com/opinion/2580971/', '2580971') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that dual convictions were improper.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature itself was fully aware of this fact and intended section 775.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At the outset, we conclude that the preeminence of legislative intent means that Blockburger necessarily is only the first step in the court''s analysis.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning now to the facts of the case at bar, we conclude that our decisions in Mills and Boivin are controlling.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of the Blockburger test, therefore, we concluded that separate punishments were permissible.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our own double jeopardy clause in article I, section 9, Florida Constitution, which has endured in this state with only minor changes since the constitution of 1845, was intended to mirror this intention of those who framed the double jeopardy clause of the fifth amendment.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that unreasonable results sometimes may be achieved by applying no rule of construction other than Blockburger to determine the intent behind a facially ambiguous penal statute.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we find that Florida''s lenity requirement constitutes a rule of construction coequal to the Blockburger test codified in section 775.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that both of these offenses address essentially the same evil, i.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although there is some question as to the number of shots that actually struck Knighten, we find that the record does not establish beyond a reasonable doubt that he was struck by more than one blast.', 'general', 'Carawan v. State', 'https://www.courtlistener.com/opinion/1897665/', '1897665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth herein, we affirm.', 'general', 'Commonwealth v. Whitney', 'https://www.courtlistener.com/opinion/1889058/', '1889058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the PCRA Court finding that it lacked jurisdiction to entertain this PCRA petition, because it was untimely, not because of the pending federal
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that only transactional immunity exists under the South Carolina Constitution, we also hold that since the indictments brought against Tom Thrift, Sam Thrift, Gary Thrift, and Rogers Carroll were obtained in violation of their state constitutional rights against compelled self-incrimination, they must be dismissed.', 'dismissal', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 399 (1950), we hold that an enactment of revisions designed to embrace an entire subject of legislation operates to repeal acts which deal with the same subject matter.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “[ajppellate courts are bound by the fact findings in response to motions preliminary to trial when the findings are supported by the evidence and not clearly wrong or controlled by error of law.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our interpretation of the state constitutional guarantee of freedom from compelled self-incrimination, we held that the federal interpretation of the Fifth Amendment, while persuasive, was not binding.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '217 (1935), we held that the absence of a savings clause was fatal to continuing prosecutions under a repealed statue.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In analyzing the common law crime of misconduct in office, we held that Hess’ nonelected position as the Chief of Police was sufficient to sustain his conviction for common law misconduct in office.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On strikingly similar facts, where a joint legislative committee charged with the investigation of public corruption in various police agencies compelled the testimony of a witness, this Court held that anything less than transactional immunity was unconstitutional under Article I, Section 12 (formerly § 17), of the South Carolina Constitution.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that the evidence in the record supports the trial judge’s order on this first issue.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the presentation of this evidence was severely prejudicial to Respondent Gilreath.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial judge erred in his conclusion and hold that indictments under the “old” Ethics Act remain viable as a basis for prosecution of Reeves and Wilson.', 'general', 'State v. Thrift', 'https://www.courtlistener.com/opinion/1304136/', '1304136') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 12 In summary, we hold that the explicit language of A.', 'general', 'State v. Helmer', 'https://www.courtlistener.com/opinion/2581953/', '2581953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the offense of failing to register as a sex offender under A.', 'general', 'State v. Helmer', 'https://www.courtlistener.com/opinion/2581953/', '2581953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Due to the fact that the jury instructions were fundamentally erroneous, we reverse the conviction for conspiracy to commit racketeering and remand for a new trial.', 'jury_instruction', 'Pizzo v. State', 'https://www.courtlistener.com/opinion/1880762/', '1880762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse as to the issues regarding (1) the denial of Mrs.', 'general', 'Pizzo v. State', 'https://www.courtlistener.com/opinion/1880762/', '1880762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we did in Pizzo I, we reverse Mrs.', 'general', 'Pizzo v. State', 'https://www.courtlistener.com/opinion/1880762/', '1880762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Mrs.', 'general', 'Pizzo v. State', 'https://www.courtlistener.com/opinion/1880762/', '1880762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we did in Pizzo I, we affirm without comment the issues regarding (1) the admission of bad acts evidence, (2) the admission of certain testimony of Special Agent Charles Leonard, (3) the denial of Mrs.', 'general', 'Pizzo v. State', 'https://www.courtlistener.com/opinion/1880762/', '1880762') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant was not in custody when she made her 6 March inculpatory statement, so that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant received a fair trial, free of prejudicial error.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1225929/', '1225929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 10 (1979), in which we held that a defendant’s confession cannot be used against her when “ ‘the evidence indisputably establishes the strongest probability that [the defendant] was insane and incompetent at the time [s]he allegedly confessed.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1225929/', '1225929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “upon request, a defendant who interposes a defense of insanity to a criminal charge is entitled to an instruction by the trial judge setting out in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was an adequate basis for Judge Mills’ findings of fact as to defendant’s capacity to understand and waive her constitutional rights.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1225929/', '1225929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in its management of the jury voir dire in defendant’s case.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1225929/', '1225929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find the district attorney’s conduct less than laudable, but we conclude that it was not sufficiently prejudicial to warrant the trial court’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in its instruction on defendant’s insanity defense.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1225929/', '1225929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this is not the “ ‘exceptional case where, after reviewing the entire record, it can be said the claimed error is a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because ASORA''s registration, disclosure, and dissemination provisions violate the protection against ex post facto laws afforded by the Alaska Constitution as it applies to defendants who committed their crimes before the legislature enacted ASORA, we hold that AS 12.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 Does applying ASORA to "John Doe," who committed his crime and was convicted and sentenced before ASORA was enacted, violate the ex post facto clause of the Alaska Constitution? We conclude that it does because ASORA imposes burdens that have the effect of adding punishment beyond what could be imposed when the crime was committed.', 'sentencing', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it is the criminal conviction, and only the eriminal conviction, that triggers obligations under ASORA, we conclude that this factor supports the conclusion that ASORA is punitive in effect.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Summing up the effects under the seven factors, we conclude that ASORA''s effects are punitive, and convincingly outweigh the statute''s non-punitive purposes and effects.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And because we conclude that ASORA is an ex post facto law under the same standard for reviewing ex post facto claims under the Alaska Constitution that courts apply under the Federal Constitution, we decline to adopt the standard Doe advocates.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on decisions of the United States Supreme Court and the Seventh and Ninth Circuit Courts of Appeals, we concluded that because the extension did not increase the punishment or change the elements of the offense necessary to establish guilt, it did not violate the Federal or the Alaska Constitution.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1109 (1960), which upheld a statute that was enacted for valid regulatory purposes and that was not punitive in effect, we concluded that because the statute''s purposes were compensatory rather than punitive it did not violate either the federal or state ex post facto clause.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that the Supreme Court had rejected a similar attack on a habitual offender statute that provided enhanced punishment for a fourth felony conviction, we affirmed the revocation.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that ASORA''s registration requirement does not apply to persons who committed their crimes before ASORA became effective, and reverse the superior court order granting final judgment in favor of the state and against Doe.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '13 Accordingly, we held that the Supreme Court decision disposed of Danks''s federal claim, and we saw "no reason for us to interpret Alaska''s constitutional provision differently.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the challenged condition is reasonably related to the goals of rehabilitation and deterrence and is no broader than legitimately necessary to serve those purposes.', 'general', 'United States v. Watson', 'https://www.courtlistener.com/opinion/1347861/', '1347861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a mandatory inference in a jury instruction was reversible error per se because it created “a conclusive presumption on an essential element of the crime
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We review such evidentiary determinations deferentially, recognizing that the trial court is in the best position to determine admissibility in the first instance, and we reverse only on a showing of prejudice.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/1043782/', '1043782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse such error when it is obvious, affects substantial rights bringing prejudice to the defendant, and “seriously affects the fairness, integrity or public reputation of judicial proceedings.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/1043782/', '1043782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/1043782/', '1043782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/1043782/', '1043782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm what we said in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm when the error is harmless.', 'general', 'State v. Myers', 'https://www.courtlistener.com/opinion/1043782/', '1043782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1260, we adopted Justice Brennan''s analysis in Dickey, and we held that, in the case of excessive delay, prejudice should be presumed.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that none of the cause for the delay can be attributed to appellant.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, we conclude that appellant adequately asserted his right to a speedy trial and that this factor also weighs in appellant''s favor in the balancing test.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, with respect to the factor of prejudice, we conclude that appellant was presumptively prejudiced by the lengthy delay, but only minimally, so that, as to this factor, the balance is tipped only slightly in appellant''s favor in the overall balancing test.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse appellant''s convictions and remand to the district court with instructions to dismiss the information.', 'dismissal', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1179510/', '1179510') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a single possession of the same substance, despite any broader mental intent, could support only one conviction when the facts relied on for both were the same.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2384167/', '2384167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these facts, we find that any error m the limitation on the defendant’s cross-exammation of the victim was harmless.', 'general', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2384167/', '2384167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and dismiss the conviction on the second count of possession of a deadly weapon.', 'dismissal', 'State v. Richardson', 'https://www.courtlistener.com/opinion/2384167/', '2384167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we hold that the lifetime registration component of the Hawaii sex offender registration statute implicates a protected liberty interest under the Hawaii State Constitution, article I, section V and requires that minimum requirements of due process-—notice and the opportunity to be heard—be afforded to convicted sex offenders.', 'general', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that requiring lifetime registration of all sex offenders without qualification, noncompliance with which is punishable by criminal penalties, implicates a liberty interest that cannot be curtailed absent procedural protections.', 'general', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that Guidry does not have standing to challenge HRS chapter 846E as unconstitutionally overbroad.', 'general', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that, under the Hawaii Constitution, “the absence of procedural safeguards in the public notification provision” rendered such provisions of “HRS chapter 846E unconstitutional, void, and unenforceable.', 'general', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of a hearing, this court held that “the public notification provisions of HRS chapter 846E are void and unenforceable.', 'general', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that "Bani has established that the public notification provisions of HRS chapter 846E implicate a liberty interest protected by the due process clause of the Hawaii Constitution.', 'general', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that the absence of a “judicial hearing on [such] a risk” violates procedural due process.', 'general', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we affirm the court’s June 3, 1999 order denying Guidry’s motion to dismiss and its judgment of conviction and sentence under HRS § 846E-6 for Guidry’s failure to comply with registration requirements.', 'dismissal', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the foregoing grounds, we affirm the court’s August 5, 1999 judgment as to Count I.', 'general', 'State v. Guidry', 'https://www.courtlistener.com/opinion/2623564/', '2623564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We hold that defendant''s objections to his death sentence are without merit and, therefore, we affirm his convictions and sentences.', 'sentencing', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the contrary, we hold that all of those proofs were relevant to the aggravating and mitigating factors in this case, that the probative value of those proofs was not substantially outweighed by *977 their claimed unduly prejudicial effect, and that the trial court''s determinations admitting such proofs were not "so wide of the mark that a manifest denial of justice resulted.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that standard, we hold that the cross-examination of defendant''s traumatic brain injury expert, clinical neuropsychiatrist, and developmental psychologist properly addressed these witnesses'' biases, interest and partiality and, hence, was proper.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hazard, defendant "realize[d] that this is a human being" and that he did not care, as well as the third comment that defendant does not have the "light" of compassion or remorse in him, we hold that, because defendant placed his character at issue by virtue of several of the mitigating factors he placed before the jury, it is entirely relevant, and proper, for the prosecution to respond as it did.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that none of the challenged comments improperly placed defendant''s character in issue and, hence, defendant''s objections thereto are unavailing.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we reject defendant''s assertions on appeal and we hold that, in each instance, the trial court''s admission of the victim impact evidence and the State''s use of that victim impact evidence was proper.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 798, as well as the results of the frequency analysis, we hold that defendant has failed to establish that his death sentence is disproportionate.', 'sentencing', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1058 (1988), where we held that there was "no basis in the Capital Punishment Act, or in any principle of federal or state constitutional law, that would require the instruction approved in [State v.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1208 (1993), we held that that aggravating factors are the functional equivalents of elements of a crime that, therefore, must be proven beyond a reasonable doubt.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Rose, supra, we held that a defendant is not entitled to a presumption against the death penalty charge.', 'general', 'State v. Wakefield', 'https://www.courtlistener.com/opinion/2344370/', '2344370') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 504-05, given the protective steps the district court took here to minimize prejudice to Tscheu, we hold that the court did not abuse its discretion when it allowed the use of Tscheu''s prior convictions for impeachment.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the first two Griller prongs, we hold that the admission of the snowplow driver''s testimony was error that was plain.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[18] Considering the vague detail regarding the date the snowplow driver observed the Jeep or van in Thoms''s driveway, and Tscheu''s own testimony that he visited Thoms at her home the night before her death, we hold that the verdict was surely unattributable to this error.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the admission of Downie''s testimony as to the content of this record was not an error that was plain, and that this issue therefore is not properly before us.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we conclude that Tscheu has not shown that he suffered any prejudice due to the lack of a separate notice.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We look first at the motor vehicle transfer record to determine if its admission was an error that was plain, and we conclude that it was not.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the district court did not err in denying Tscheu''s motion for judgment of acquittal.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Tscheu did not meet his burden to show that the error is properly before us for review.', 'general', 'State v. Tscheu', 'https://www.courtlistener.com/opinion/2044007/', '2044007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that based on the statutory language, and because each of the 18 differing photographs represented a separate violation under either § 28-1463.', 'general', 'State v. Mather', 'https://www.courtlistener.com/opinion/2013367/', '2013367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the 18 differing photographs and the statutory language, we conclude that the proper unit of prosecution under § 28-1463.', 'general', 'State v. Mather', 'https://www.courtlistener.com/opinion/2013367/', '2013367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Mather', 'https://www.courtlistener.com/opinion/2013367/', '2013367') ON CONFLICT DO NOTHING;
