INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court erred in granting Straub''s motion to suppress because Officer Grable was justified in pursuing Straub into his home in order to preserve evidence of Straub''s blood alcohol content.', 'suppression', 'State v. Straub', 'https://www.courtlistener.com/opinion/2185099/', '2185099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the trial court erred in granting Straub''s motion to suppress because Officer Grable was justified in pursuing Straub into his home in order to preserve Straub''s blood alcohol content.', 'suppression', 'State v. Straub', 'https://www.courtlistener.com/opinion/2185099/', '2185099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the police were required to obtain a valid warrant before entering the residence to arrest Timmons for the two misdemeanor offenses.', 'general', 'State v. Straub', 'https://www.courtlistener.com/opinion/2185099/', '2185099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Straub', 'https://www.courtlistener.com/opinion/2185099/', '2185099') ON CONFLICT DO NOTHING;
