INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals.', 'general', 'State v. Sutton', 'https://www.courtlistener.com/opinion/1058264/', '1058264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the trial court.', 'general', 'State v. Sutton', 'https://www.courtlistener.com/opinion/1058264/', '1058264') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the public interest side, we conclude that permitting law enforcement officers to request identifying information from passengers in traffic stops serves the public interest in several ways that are reasonably related to the purpose of a traffic stop.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, on the public side of the balance, we conclude that asking the rear passenger for identification furthered several legitimate public interests and was reasonably related to the purpose of the stop.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Weighing the public interest served by permitting police to request identifying information from passengers against the incremental intrusion upon *73 individual privacy interests, we conclude that the public interests are substantial and the interference with private liberty interests is de minimis.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In adherence to the law, we conclude that the incremental intrusion that resulted from the questioning did not transform the lawful, reasonable seizure into an unlawful, unreasonable one.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, on the private side of the equation, we find that the additional interference with the passenger''s personal liberty that resulted from the identification questions was minimal.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the decisions of the court of appeals.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the identification questions did not transform the reasonable search into an unreasonable one under the circumstances of this case.', 'general', 'State v. Griffith', 'https://www.courtlistener.com/opinion/2221428/', '2221428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'violate double jeopardy and his sentence is not inappropriate, we affirm
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the record contains no evidence of repeat violence to justify the trial court''s issuance of an injunction, we reverse.', 'general', 'McMath v. Biernacki', 'https://www.courtlistener.com/opinion/1126128/', '1126128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial court''s final judgment imposing an injunction against repeat violence.', 'general', 'McMath v. Biernacki', 'https://www.courtlistener.com/opinion/1126128/', '1126128') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the district court''s denial of Weaver''s motion to suppress the evidence discovered in the warrantless search.', 'suppression', 'State v. Weaver', 'https://www.courtlistener.com/opinion/1158307/', '1158307') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial judge committed error by requiring the defendant to prove, as a prerequisite to judicial in camera inspection of the personnel file, that the file likely contained the sought-after evidence:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In other words, we held that the trial judge should have used the approach we adopted in Dana: the judge should have conducted an in camera inspection of the personnel file because, if the personnel file contained the sort of information described in the defendant''s motion, this information would have been relevant to the defendant''s guilt or innocence, not just relevant to impeachment of the witness''s general credibility or impeachment of the witness on collateral matters.', 'general', 'Booth v. State', 'https://www.courtlistener.com/opinion/2455189/', '2455189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Dana v.', 'general', 'Booth v. State', 'https://www.courtlistener.com/opinion/2455189/', '2455189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained in this opinion, we conclude that the district court should have examined the personnel files in camera to see if the files contained citizen complaints of excessive force, disciplinary actions based on the use of excessive force, or training in the use of pepper spray.', 'general', 'Booth v. State', 'https://www.courtlistener.com/opinion/2455189/', '2455189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these factual assertions, and given Booth''s theory of defense at trial, we find that Booth satisfied the threshold requirement for an in camera inspection of Officer Griffith''s personnel file for prior complaints of excessive force or disciplinary actions based on the use of excessive *378 force.', 'general', 'Booth v. State', 'https://www.courtlistener.com/opinion/2455189/', '2455189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the State’s interest in effective crime investigations and prevention, as advanced by section 5—4—3, outweighs defendant’s privacy interest as a convicted felon.', 'general', 'People v. Garvin', 'https://www.courtlistener.com/opinion/2038191/', '2038191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we hold that there was sufficient probable cause to deny defendant’s motion to quash arrest and suppress the evidence, rejecting the appellate court’s contrary analysis.', 'suppression', 'People v. Garvin', 'https://www.courtlistener.com/opinion/2038191/', '2038191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the officers lacked probable cause to arrest the defendant for violating the drug-loitering ordinance.', 'probable_cause', 'People v. Garvin', 'https://www.courtlistener.com/opinion/2038191/', '2038191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the appellate court’s judgment affirming the trial court’s denial of the motion, albeit on a different basis, and upholding the constitutionality of the statute.', 'general', 'People v. Garvin', 'https://www.courtlistener.com/opinion/2038191/', '2038191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, while we reject in part the appellate court’s rationale, we affirm its ultimate judgment.', 'general', 'People v. Garvin', 'https://www.courtlistener.com/opinion/2038191/', '2038191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that based on the reasoning in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a warrantless search "may be incident to a subsequent arrest if the officers have probable cause to arrest before the search.', 'probable_cause', 'State v. Denk', 'https://www.courtlistener.com/opinion/2044516/', '2044516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "[t]he purposes of the search incident to arrest [protect
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the orders of the circuit court.', 'general', 'State v. Denk', 'https://www.courtlistener.com/opinion/2044516/', '2044516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that plain error occurred when the prosecutor told the jury in closing argument that they should infer guilt from the defendant''s silence during the period after his arrest but prior to receiving Miranda warnings.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that "[dlenial of a constitutional right, in the normal case, would affect substantial rights and give rise to plain error" unless the State proves that the error was "harmless beyond a reasonable doubt.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these standards to the present case, we conclude that there was plain error.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has not shown that the prosecutor''s improper questions and comment about post-arrest silence were harmless beyond a reasonable doubt.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And even if our analysis is limited to the non-constitutional claim that the prosecutor commented on Adams''s pre-arrest silence, we conclude that Adams has shown that there is a reasonable probability that the error affected the outcome of the case.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Adams has shown that there is a reasonable probability that the prosecutor''s comments on pre-arrest silence affected the jury''s verdict and that the State has not shown that the comments on post-arrest silence were harmless beyond a reasonable doubt.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brown, we concluded that there was no constitutional violation.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the same concerns expressed in Williams applied to workers'' compensation case decisions.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Adams''s conviction and remand for a new trial.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, a 1980 case, we reversed a conviction where the prosecutor had played a recording for the jury that included the defendant exercising her right to remain silent.', 'general', 'Adams v. State', 'https://www.courtlistener.com/opinion/2331594/', '2331594') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that decision factually distinguishable from this case, and therefore unpersuasive.', 'general', 'Titan Tire Corp. v. Labor Commissioner', 'https://www.courtlistener.com/opinion/1274318/', '1274318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on the appeal and annul the writ in the certiorari proceeding.', 'general', 'Titan Tire Corp. v. Labor Commissioner', 'https://www.courtlistener.com/opinion/1274318/', '1274318') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 438 ("We hold that Article I, Section 9 of the Texas Constitution was not violated by [the police officers''] actions.', 'general', 'Laney v. State', 'https://www.courtlistener.com/opinion/1427607/', '1427607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, "As part of his duty to `serve and protect,'' a police officer may stop and assist an individual whom a reasonable persongiven the totality of the circumstanceswould believe is in need of help," and then set forth the list of factors mentioned, but not applied, by the court of appeals below.', 'general', 'Laney v. State', 'https://www.courtlistener.com/opinion/1427607/', '1427607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these circumstances, we find that the emergency doctrine applies.', 'general', 'Laney v. State', 'https://www.courtlistener.com/opinion/1427607/', '1427607') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, for the reasons expressed above, we hold that chapter 95-182, Laws of Florida, is unconstitutional as violative of the single subject rule contained in article III, section 6 of the Florida Constitution.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1855912/', '1855912') ON CONFLICT DO NOTHING;
