INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that under those circumstances, “the officers’ actions constituted a show of authority,” and that a reasonable person “would likely conclude that, if he or she drove away, then the two officers would soon be in hot pursuit.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in Brownlee, this court held that the defendant was unlawfully seized after the justification for the traffic stop had ended, where the two officers continued to flank both sides of the vehicle after returning the motorist’s documents and stating that no citations would be issued, paused for a “couple of minutes,” and then requested that the occupants agree to a consent search.', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As noted, however, this statement contradicts the position taken by the majority earlier in its opinion, wherein it finds that there was a break between the conclusion of the traffic stop and Kaus’ request to Cosby to allow a search, and rejects precisely the same argument it now embraces, writing: “While Cosby argues before this court that there was no break between the conclusion of the traffic stop and the officer’s request for consent to search, we conclude that the record does not suppor...', 'general', 'People v. Cosby', 'https://www.courtlistener.com/opinion/2105166/', '2105166') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Appellant''s signature of a fictitious name on three fingerprint cards was sufficient to support his convictions for forgery.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we have determined that the property taken need not be physically attached to the victim in order to constitute theft from the person and that Appellant''s counsel had a reasonable basis to agree to the stipulation regarding the grading of the offense, we hold that the trial court properly sentenced Appellant''s theft convictions as first-degree misdemeanors based upon that stipulation.', 'sentencing', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in that case, we held that the sentencing court improperly had graded the defendant''s offense a first-degree misdemeanor as a theft from the person.', 'sentencing', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we conclude that theft from the person under Section 3903(b) includes not only theft from the victim''s body, but also theft in the victim''s presence and from his immediate possession and control.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that in order to be graded as a theft from the person under Section 3903, property need not be taken from the victim''s body as long as it is taken in his presence and from his immediate possession and control.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the present case concerns the propriety of the grading of the offense which thereby establishes the maximum penalty, and not an enhancement to the sentence beyond the statutory maximum penalty for the theft offenses, we conclude that Apprendi does not apply.', 'sentencing', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, we concluded that "common sense dictates that a person need not be in actual physical possession of property to have it taken from his person.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 39 Having found no merit to any of Appellant''s contentions on appeal, we affirm his judgment of sentence.', 'sentencing', 'Commonwealth v. Shamberger', 'https://www.courtlistener.com/opinion/2077885/', '2077885') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we do not agree with Pazden''s statutory challenge to the special conditions of his parole, we conclude that in general conditions of parole are subject to constitutional limitations and that in particular the conditions imposed on Pazden cannot withstand constitutional scrutiny.', 'general', 'Pazden v. NJ State Parole Bd.', 'https://www.courtlistener.com/opinion/1886959/', '1886959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that its analysis is applicable as well in the context of a challenge to conditions of parole.', 'general', 'Pazden v. NJ State Parole Bd.', 'https://www.courtlistener.com/opinion/1886959/', '1886959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the particular special conditions imposed on this parolee, we conclude that they cannot stand.', 'general', 'Pazden v. NJ State Parole Bd.', 'https://www.courtlistener.com/opinion/1886959/', '1886959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the additional special conditions fail the constitutional test for vagueness, a defect that cannot be remedied by an ad hoc system of interpretation.', 'general', 'Pazden v. NJ State Parole Bd.', 'https://www.courtlistener.com/opinion/1886959/', '1886959') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1147 Because we find that the special conditions imposed on Pazden are not ones that can be understood by a person of common intelligence and ordinary experience, because one must, of necessity, guess at the particular meaning of the conditions, and because their breadth of language gives rise to a very real possibility that their application will be arbitrary, we conclude that they are void for vagueness.', 'general', 'Pazden v. NJ State Parole Bd.', 'https://www.courtlistener.com/opinion/1886959/', '1886959') ON CONFLICT DO NOTHING;
