INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the appellate court correctly determined that J.', 'general', 'People v. J.W.', 'https://www.courtlistener.com/opinion/3135049/', '3135049') ON CONFLICT DO NOTHING;
