INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the trial court abused its discretion in admitting evidence of prior bad acts, we reverse and remand.', 'general', 'State v. Coonrod', 'https://www.courtlistener.com/opinion/1248867/', '1248867') ON CONFLICT DO NOTHING;
