INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that in cases where the defendant is accused of a sexual battery committed in the familial setting,[6] evidence of a prior *1257 sexual battery committed within the familial setting is admissible under the Williams rule because this evidence is relevant to corroborate the victim''s testimony.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court erred in admitting the collateral crime evidence under the relaxed standard for familial cases because there was only one similarity between the charged and collateral offenses other than the familial context.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In so holding, we conclude that due process is satisfied by weighing the probative value of the evidence of prior acts of child molestation against its potential for unfair prejudice, which is compelled by section 90.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the federal courts applying federal rule 403, we conclude that the application of section 90.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1263 We conclude that the trial court thoroughly examined the proffered evidence and did exactly what was required under section 90.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances we conclude that the trial court did not err in admitting the limited portions of Chambers'' testimony.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the constitutionality of this statute when addressing the issue of identity should be reviewed in another case where identity is a disputed issue.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that because the credibility of the victim "was very much an issue .', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead we concluded that the charged and collateral offenses were "strikingly similar" and therefore met the "strict standards of the Williams rule.', 'general', 'McLean v. State', 'https://www.courtlistener.com/opinion/1891312/', '1891312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶8           Applying these principles, we conclude that A.', 'general', 'State v. Hansen', 'https://www.courtlistener.com/opinion/867381/', '867381') ON CONFLICT DO NOTHING;
