INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶18             For these reasons, we affirm the order of the court
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lopez, we held that a prior conviction for resisting arrest did not death qualify the defendant because conduct that only created a "substantial risk" of physical injury to an officer was not conduct "involving the use or threat of violence.', 'general', 'State v. McKinney', 'https://www.courtlistener.com/opinion/1135841/', '1135841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Walden, this court held that a conviction that could have been obtained for merely reckless conduct did not qualify as a prior under the (F)(2) factor.', 'general', 'State v. McKinney', 'https://www.courtlistener.com/opinion/1135841/', '1135841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[3] Thus, under the facts of this case, we conclude that the Rule 609 hearing was not a critical stage of Hedlund''s proceedings.', 'general', 'State v. McKinney', 'https://www.courtlistener.com/opinion/1135841/', '1135841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the finding that Hedlund murdered for pecuniary gain.', 'general', 'State v. McKinney', 'https://www.courtlistener.com/opinion/1135841/', '1135841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Mendicoa v. State', 'https://www.courtlistener.com/opinion/1355635/', '1355635') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the appellate court erred in reversing defendant''s conviction based on a violation of Supreme Court Rule 431(b).', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s violation of the amended version of Supreme Court Rule 431(b) in this case does not fall within the very limited category of structural errors and, thus, does not require automatic reversal of defendant''s conviction.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the language and history of the rule, we concluded that the trial court''s violation of Rule 431(b) did not rise to the level of structural error.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that such inquiry was required.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the appellate court''s judgment and affirm the judgment of the circuit court.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the appellate court''s judgment reversing defendant''s conviction and remanding this matter for a new trial.', 'general', 'People v. Thompson', 'https://www.courtlistener.com/opinion/2481666/', '2481666') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the slayer statute prohibits a person who is found to have feloniously and intentionally killed another from profiting by that act, we affirm.', 'general', 'Castro v. Ballesteros-Suarez', 'https://www.courtlistener.com/opinion/2597826/', '2597826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s judgment.', 'general', 'Castro v. Ballesteros-Suarez', 'https://www.courtlistener.com/opinion/2597826/', '2597826') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the court of appeals failed to conduct a proper analysis, we remand this case to the court of appeals.', 'general', 'Vela v. State', 'https://www.courtlistener.com/opinion/1385129/', '1385129') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that while the State may have a legitimate reason for not immediately filing charges against a defendant who has been arrested previously, the State is not authorized to simply let the speedy trial period run prior to filing additional charges.', 'general', 'State v. Woodruff', 'https://www.courtlistener.com/opinion/1720118/', '1720118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1978),] we conclude that the existence of three or more prior DUI convictions is an essential fact constituting the substantive offense of felony DUI.', 'general', 'State v. Woodruff', 'https://www.courtlistener.com/opinion/1720118/', '1720118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering all of the evidence in the light most favorable to the prosecution, then, we hold that the record evidence reasonably supports a finding that defendant was guilty of first degree murder beyond a reasonable doubt in that: (1) defendant or someone for whose conduct he was legally responsible performed acts that caused Forrest’s death;', 'general', 'People v. Wheeler', 'https://www.courtlistener.com/opinion/2219911/', '2219911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2222 (1992), we held that the fact that a third party had threatened the victim with a handgun a week before the victim’s murder was not enough to link that third party to the murder.', 'general', 'People v. Wheeler', 'https://www.courtlistener.com/opinion/2219911/', '2219911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 74, 105-06 (1996), this court held that “[t]he act of sustaining an objection and properly admonishing the jury is usually viewed as sufficient to cure any prejudice.', 'general', 'People v. Wheeler', 'https://www.courtlistener.com/opinion/2219911/', '2219911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the above, we find that a chief goal of the prosecutor’s closing argument in this case was to inflame the passions and prejudices of the jury, uniting the interests of the jurors in their own safety with that of the interests of the State in convicting defendant.', 'general', 'People v. Wheeler', 'https://www.courtlistener.com/opinion/2219911/', '2219911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not abuse its discretion in refusing defendant’s offers of proof.', 'general', 'People v. Wheeler', 'https://www.courtlistener.com/opinion/2219911/', '2219911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we believe that statements made by the prosecutor during closing arguments in this case warrant the granting of a new trial, we reverse the judgments of the appellate and circuit courts and remand to the trial court.', 'general', 'People v. Wheeler', 'https://www.courtlistener.com/opinion/2219911/', '2219911') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because “conspiracy to commit first-degree murder is a specific intent crime .', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2534434/', '2534434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 117 On appeal, we held that “[t]here is no vicarious liability for cruelty in capital cases absent a plan intended or reasonably certain to cause suffering.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2534434/', '2534434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the evidence was insufficient to prove the alleged felony and thus concluded that the defendant should have been acquitted of felony murder.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2534434/', '2534434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 105 We conclude that the evidence established beyond a reasonable doubt that a motive for killing all three victims was to steal Wear’s truck.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2534434/', '2534434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we conclude that the jury instructions here were adequate to provide a narrowed construction of the facially vague statutory terms.', 'jury_instruction', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2534434/', '2534434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 135 We conclude that these mitigating factors are not sufficiently substantial to call for leniency.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2534434/', '2534434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reversed on other grounds, we declined to address this issue.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2534434/', '2534434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 147 For the foregoing reasons, we affirm the convictions and sentences imposed by the superior court, with the exception of the armed robbery sentence, which we will address in a supplemental opinion.', 'sentencing', 'State v. Anderson', 'https://www.courtlistener.com/opinion/2534434/', '2534434') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For *245 these reasons, we hold that the admission of evidence of the November assault, even if erroneous, was harmless.', 'general', 'State v. Rodriquez', 'https://www.courtlistener.com/opinion/2023007/', '2023007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court''s decision to permit evidence of prior bad acts by the defendant.', 'general', 'State v. Rodriquez', 'https://www.courtlistener.com/opinion/2023007/', '2023007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error or abuse of discretion in the trial court''s rulings, we affirm the defendant''s convictions.', 'general', 'State v. Rodriquez', 'https://www.courtlistener.com/opinion/2023007/', '2023007') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that section 16-15-342 is
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that Green has not satisfied his burden to prove that section 16-15-342 violates the First Amendment of the Constitution.', 'general', 'State v. Green', 'https://www.courtlistener.com/opinion/2507588/', '2507588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2006) ("After examining the text of the statute, its broad purpose and its legislative history, we conclude that Congress did not intend to allow the use of an adult decoy, rather than an actual minor, to be asserted as a defense to § 2422(b).', 'general', 'State v. Green', 'https://www.courtlistener.com/opinion/2507588/', '2507588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As an initial matter, we find that Green does not have standing to assert a facial challenge for vagueness as the statute provided adequate notice that his conduct fell within that proscribed by section 16-15-342.', 'general', 'State v. Green', 'https://www.courtlistener.com/opinion/2507588/', '2507588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even assuming standing, we find that Green’s challenge is without merit.', 'general', 'State v. Green', 'https://www.courtlistener.com/opinion/2507588/', '2507588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Green', 'https://www.courtlistener.com/opinion/2507588/', '2507588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we affirm Green’s convictions for criminal solicitation of a minor and attempted CSC with a minor in the second-degree as: (1) the criminal solicitation of a minor statute is not unconstitutionally overbroad or vague;', 'general', 'State v. Green', 'https://www.courtlistener.com/opinion/2507588/', '2507588') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court''s exercise of the inherent authority to assess attorneys'' fees against an attorney must be based upon an express finding of bad faith conduct and must be supported by detailed factual findings describing the specific acts of bad faith conduct that resulted in the unnecessary incurrence of attorneys'' fees.', 'general', 'Moakley v. Smallwood', 'https://www.courtlistener.com/opinion/1630953/', '1630953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that the Third District''s decision must be quashed because the trial court did not make an express finding of bad faith, and did not provide the attorney notice and an opportunity to be heard before imposing the attorneys'' fees.', 'general', 'Moakley v. Smallwood', 'https://www.courtlistener.com/opinion/1630953/', '1630953') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 771 (2006), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this Court held in Syllabus Point 6 of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We spell out our holding with some specificity in the following pages, but briefly stated, it is this: We hold that the State Patrol did have probable cause to stop the vehicle.', 'probable_cause', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, although the district court erred in admitting the airline ticket stub under the residual hearsay exception, we hold that this evidence was admissible as an adopted statement.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "a constitutional investigatory stop cannot be made solely to check a motorist''s documentation when the vehicle is properly displaying in-transit tags.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Jacob,[44] we held that a trial judge does not have discretion to admit inadmissible hearsay statements.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of these circumstances, we conclude that these facts, when viewed from the standpoint of an objectively reasonable police officer,[28] created a reasonable, articulable suspicion.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion in determining that evidence showing Draganescu made false exculpatory statements is relevant to his guilt.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[56] We conclude that under these circumstances, exhibit 20 was admissible as an adopted statement.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As noted, we conclude that exhibit 20 was admissible as an adopted statement.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circumstances are sufficient to show that Draganescu adopted the written statement by his possession of it.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the information contained in exhibit 20 supported a finding that it was what it purported to be: the tear-off portion of an airline ticket or boarding pass.', 'general', 'State v. Draganescu', 'https://www.courtlistener.com/opinion/1670832/', '1670832') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'analysis, we hold that the court did not commit clear error in overruling Pendleton’s objection to the state’s peremptory challenge of prospective juror 34.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1622392/', '1622392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court did not clearly abuse its discretion by admitting Pendleton’s two prior convictions at issue.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1622392/', '1622392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not commit error in its jury instruction as it relates to felony murder while committing kidnapping.', 'jury_instruction', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1622392/', '1622392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There is no discriminatory intent inherent in the explanations, and therefore we conclude that the state met its burden of production.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1622392/', '1622392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court engaged in all three steps of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we do not defer to the district court’s analysis, we conclude that the court properly overruled Pendleton’s objection.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1622392/', '1622392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that “while the trial court’s duty to rule on the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the “grouping of past acts of domestic abuse as a preliminary factual element * * * is in no way an
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 257-58, we reversed the conviction and remanded for a new trial not because of the district court’s error, but because the record was insufficient for us to make a determination of whether or not the prosecutor had a facially race-neutral reason for the challenge.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1622392/', '1622392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1622392/', '1622392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶23           Given this history, we conclude that the legislature
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Amendment issue, and we affirm the sentences.', 'sentencing', 'State v. Berger', 'https://www.courtlistener.com/opinion/867414/', '867414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that Rivera is entitled to relief.', 'general', 'Commonwealth v. Rivera', 'https://www.courtlistener.com/opinion/2422910/', '2422910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the statutory language at issue, we conclude that the meaning of the word “incarceration” is ambiguous and that we must, therefore, seek to ascertain the legislature’s intent through statutory construction.', 'general', 'Commonwealth v. Rivera', 'https://www.courtlistener.com/opinion/2422910/', '2422910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration, we reverse.', 'general', 'Commonwealth v. Rivera', 'https://www.courtlistener.com/opinion/2422910/', '2422910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that all departures from the Minnesota Sentencing Guidelines must be supported by substantial and compelling circumstances, and that a plea agreement— standing alone — is not a sufficient basis to depart from the sentencing guidelines.', 'sentencing', 'State v. Misquadace', 'https://www.courtlistener.com/opinion/1852415/', '1852415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that the upward durational departure was justified based on the defendant’s exploitation of the victim’s vulnerability, but stated: “We believe that the real question raised by this case is whether a defendant may waive his or her right to be sentenced under the guidelines.', 'sentencing', 'State v. Misquadace', 'https://www.courtlistener.com/opinion/1852415/', '1852415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court noted that this court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in order to abide by the guidelines’ overriding principles, we conclude that negotiated plea agreements that include a sentencing departure are justified under the guidelines in cases where substantial and compelling circumstances exist.', 'sentencing', 'State v. Misquadace', 'https://www.courtlistener.com/opinion/1852415/', '1852415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and remand to the district court for resentencing in accordance with this opinion.', 'sentencing', 'State v. Misquadace', 'https://www.courtlistener.com/opinion/1852415/', '1852415') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court was correct in finding that the evidence did not support the requested instruction on self-defense.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In determining whether the statutory elements of a prior felony conviction involve the use of violence against the person for purposes of § 39-13-204(i)(2), *12 we hold that the trial judge must necessarily examine the facts underlying the prior felony if the statutory elements of that felony may be satisfied either with or without proof of violence.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the current case, we hold that the trial judge was not required to strictly follow the Tennessee Rules of Evidence in determining whether the State should be allowed to question the defense''s mitigation witnesses regarding Sims''s prior convictions.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our independent review, we hold that any error on the part of the trial judge in failing to follow this procedure was harmless.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that Sims has waived this issue by failing to raise a contemporaneous objection to the prosecutor''s statement at trial.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this evidence supports a finding of torture in this case.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we hold that the evidence supported application of the (i)(5) aggravator in the current case.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the underlying evidence, this Court held that there was insufficient evidence to support application of the prior violent felony aggravator, Id.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the failure to grant sua sponte a limiting instruction in this case did not amount to fundamental or prejudicial error.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecutor''s conduct does not mandate reversal.', 'general', 'State v. Sims', 'https://www.courtlistener.com/opinion/1580541/', '1580541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Molina and Ayon do not have standing to raise this issue.', 'general', 'State v. Valdez-Molina', 'https://www.courtlistener.com/opinion/1213852/', '1213852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any error the trial court may have committed was harmless.', 'general', 'State v. Valdez-Molina', 'https://www.courtlistener.com/opinion/1213852/', '1213852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions.', 'general', 'State v. Valdez-Molina', 'https://www.courtlistener.com/opinion/1213852/', '1213852') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in this case, the appellant did not adequately advise the trial court of his desire to have a hearing.', 'general', 'Gardner v. State', 'https://www.courtlistener.com/opinion/1749178/', '1749178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1019 (1898), this Court held that a dying declaration does not violate the right of confrontation and explained,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the 911 call was admissible as a dying declaration,[20] we need not address *289 its admissibility as a nontestimonial excited utterance or present-sense impression.', 'general', 'Gardner v. State', 'https://www.courtlistener.com/opinion/1749178/', '1749178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial court''s judgment and sentence of death.', 'sentencing', 'Gardner v. State', 'https://www.courtlistener.com/opinion/1749178/', '1749178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no reversible error, we affirm the judgment of the trial court.', 'general', 'Gardner v. State', 'https://www.courtlistener.com/opinion/1749178/', '1749178') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Ingerson', 'https://www.courtlistener.com/opinion/2189207/', '2189207') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'Patterson v. State', 'https://www.courtlistener.com/opinion/2314209/', '2314209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on appeal, the plain error doctrine applies to unobjected-to prosecutorial misconduct.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 718 (1997), we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Griller, we held that the defendant bears the burden of persuasion on the third prong of the test.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that appellate courts should use the plain error doctrine when examining unobjected-to prosecutorial misconduct.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, although the Griller formulation applies, we conclude that, when prosecutorial *300 misconduct reaches the level of plain or obvious errorconduct the prosecutor should know is improperthe prosecution should bear the burden of demonstrating that its misconduct did not prejudice the defendant''s substantial rights.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 741, we conclude that prosecutorial misconduct is the type of trial error that justifies a shift in the burden for determining whether the plain error affected the defendant''s substantial rights.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the burden *302 should be on the prosecution to show lack of prejudice before we will affirm a conviction.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to the court of appeals to determine whether the prosecutor''s conduct constituted plain error affecting substantial rights in accordance with this opinion.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and remand to the court of appeals to determine whether the prosecutor''s conduct constituted plain error and to place the burden on the prosecution to show lack of prejudice.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that withdrawal of appellant''s guilty pleas was not required to correct a manifest injustice or for fair and just reason, and that he received effective assistance of counsel.', 'plea', 'Butala v. State', 'https://www.courtlistener.com/opinion/1822728/', '1822728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that the district court did not err in denying appellant''s request to withdraw his pleas and that appellant received effective assistance of counsel, we affirm.', 'plea', 'Butala v. State', 'https://www.courtlistener.com/opinion/1822728/', '1822728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Butala v. State', 'https://www.courtlistener.com/opinion/1822728/', '1822728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The instant case is very similar to Johnson, supra, where this Court held that a defendant on trial for murder of her infant son was not entitled to a Weathersby instruction because the testimony of the doctors and the physical facts of the condition of the child''s body substantially contradicted the defendant''s version of what happened.', 'general', 'Wetz v. State', 'https://www.courtlistener.com/opinion/1845490/', '1845490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court sustained objections to all of these questions, and this Court held on appeal:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1970) this Court held that while driving under the influence was classified as a misdemeanor, it differed in "essential particulars" from the usual traffic violation.', 'general', 'Wetz v. State', 'https://www.courtlistener.com/opinion/1845490/', '1845490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Wetz'' initial assignment of error challenges the legal sufficiency of the evidence and urges that we reverse and order his discharge from custody.', 'general', 'Wetz v. State', 'https://www.courtlistener.com/opinion/1845490/', '1845490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in the proceedings below, we affirm.', 'general', 'Wetz v. State', 'https://www.courtlistener.com/opinion/1845490/', '1845490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that imposition of two separate sentences violated the statutory prohibition against multiple punishments contained in Minn.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Evans, in which we concluded that, generally, upward durational departures should not exceed double the presumptive sentence length.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we concluded that a plea agreement standing alone could not be used to depart because it does not demonstrate that the defendant''s conduct in the offense of conviction was significantly more or less serious than that typically involved in the commission of the crime in question.', 'plea', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding the departure was impermissibly based on uncharged criminal conduct, we reverse and remand for resentencing.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Jackson''s enhanced sentence and remand for imposition of the presumptive sentence or, unless waived by Jackson, the empanelling of a resentencing jury to determine the existence of facts in support of legitimate aggravating factors for enhanced sentencing, including sentencing as a career or dangerous offender under Minn.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In my view, the departure in this case is consistent with the double upward departure we affirmed in State v.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the contrary, we affirmed the sentence because the departure was based on the "facts relating to the conduct underlying the offense to which the defendant pleaded guilty.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Jackson''s enhanced sentence was based upon impermissible departure factors.', 'sentencing', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1916837/', '1916837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in admitting evidence concerning the existence of a $100,000 life insurance policy for the purpose of establishing the source of the funds promised to Brooks for his role in killing Rachel Carlson and Alexis Stuart.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1788253/', '1788253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*212 As in the first appeal, in which we held that statements regarding the policy taken out by Davis were inadmissible to establish Brooks'' motive, the policy itself was inadmissible in Brooks'' second trial to either supply a motive for Brooks or establish the source of payment.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1788253/', '1788253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agreed with San Martin that there was insufficient evidence to support premeditation, we held that any error was harmless because the evidence clearly supported a conviction for felony murder.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1788253/', '1788253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that while the defendant could be found guilty of all three charges, it was not proper to convict him for aggravated battery and simultaneously for homicide as a result of one shotgun blast.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1788253/', '1788253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Straight, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court abused its discretion in admitting the record.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1788253/', '1788253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the trial court''s error in admitting the limited testimony of Madero and the Department of Revenue record was harmless beyond a reasonable doubt.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1788253/', '1788253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the trial court erred in refusing to provide the coconspirator hearsay instruction requested by defense counsel.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1788253/', '1788253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a close review of the record, we conclude that Brooks mischaracterizes the proceedings and that no improper burden-shifting occurred.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1788253/', '1788253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both the conviction and the sentence.', 'sentencing', 'State v. Oliver', 'https://www.courtlistener.com/opinion/2600346/', '2600346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s sentence.', 'sentencing', 'State v. Oliver', 'https://www.courtlistener.com/opinion/2600346/', '2600346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the jury verdict and Oliver’s sentence.', 'sentencing', 'State v. Oliver', 'https://www.courtlistener.com/opinion/2600346/', '2600346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, this Court held that a city is not liable to a citizen whose home is destroyed by fire through the negligence or inefficiency of the city’s fire department because the duty to extinguish fires is a public one, not owed to any individual in particular.', 'general', 'Ezell v. Cockrell', 'https://www.courtlistener.com/opinion/2372011/', '2372011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We granted the plaintiffs application for permission to appeal, and now affirm the Court of Appeals’ judgment, because we conclude that the public duty doctrine was not abolished by the Tennessee Governmental Tort Liability Act, and that sound policy reasons warrant its continuance.', 'general', 'Ezell v. Cockrell', 'https://www.courtlistener.com/opinion/2372011/', '2372011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the doctrine serves the impor
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering the various formulations of the doctrine, we conclude that a special duty of care exists when 1) officials, by their actions, affirmatively undertake to protect the plaintiff, and the plaintiff relies upon the undertaking;', 'general', 'Ezell v. Cockrell', 'https://www.courtlistener.com/opinion/2372011/', '2372011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the plaintiff has not alleged a cause of action under 42 U.', 'general', 'Ezell v. Cockrell', 'https://www.courtlistener.com/opinion/2372011/', '2372011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the public duty doctrine survived enactment of the Tennessee Governmental Tort Liability Act, and that sound public policy supports its continued application in Tennessee, as well as the continuing validity of the “special-duty” of care exception to the doctrine.', 'general', 'Ezell v. Cockrell', 'https://www.courtlistener.com/opinion/2372011/', '2372011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm, in all respects, the Court of Appeals’ judgment affirming the trial court’s dismissal of the plaintiffs action against Chief Adams and the City of Elkton.', 'dismissal', 'Ezell v. Cockrell', 'https://www.courtlistener.com/opinion/2372011/', '2372011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kupau, this court held that, in the situation where "(1) the prosecution does not request that included [offense] instructions be given and (2) the defendant specifically objects to the included offense instructions for tactical reasons," 76 Hawaii at 395, 879 P.', 'general', 'State v. Haanio', 'https://www.courtlistener.com/opinion/2631226/', '2631226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We must overrule the ICA''s formulaic interpretation of the discretionary standards set forth in Kupau, and, applying Kupau, we conclude that the court correctly followed its precepts.', 'general', 'State v. Haanio', 'https://www.courtlistener.com/opinion/2631226/', '2631226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite Petitioner''s contentions, we conclude that there was substantial evidence that Petitioner was "in the course of committing theft" when he inflicted serious bodily injury on Kamoku.', 'general', 'State v. Haanio', 'https://www.courtlistener.com/opinion/2631226/', '2631226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a defendant may not invoke tactical considerations to deprive the jury of the opportunity to consider whether the defendant is guilty of a lesser offense included within the crime charged.', 'general', 'State v. Haanio', 'https://www.courtlistener.com/opinion/2631226/', '2631226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the affirmance by the Intermediate Court of Appeals (the ICA) of the June 19, 1998 judgment of conviction and sentence of Petitioner-Appellant Oliver Haanio, Jr.', 'sentencing', 'State v. Haanio', 'https://www.courtlistener.com/opinion/2631226/', '2631226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the result reached by the ICA in upholding Petitioner''s June 19, 1998 conviction and sentence.', 'sentencing', 'State v. Haanio', 'https://www.courtlistener.com/opinion/2631226/', '2631226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the above, we conclude that there was probable cause to arrest Wear, as a reasonably cautious person would have thought a crime had taken place.', 'probable_cause', 'People v. Wear', 'https://www.courtlistener.com/opinion/2231471/', '2231471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, the Welsh Court explicitly stated that "[b]ecause we conclude that, in the circumstances presented by this case, there were no exigent circumstances sufficient to justify a warrantless home entry, we have no occasion to consider whether the Fourth Amendment may impose an absolute ban on warrantless home arrests for certain minor offenses.', 'search_seizure', 'People v. Wear', 'https://www.courtlistener.com/opinion/2231471/', '2231471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Officer Dawdy had probable cause to arrest Wear at the doorway.', 'probable_cause', 'People v. Wear', 'https://www.courtlistener.com/opinion/2231471/', '2231471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '315) and we affirm.', 'general', 'People v. Wear', 'https://www.courtlistener.com/opinion/2231471/', '2231471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the appellate court.', 'general', 'People v. Wear', 'https://www.courtlistener.com/opinion/2231471/', '2231471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the record below, we conclude that the sentence imposed was not a product of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Commonwealth v. Tharp', 'https://www.courtlistener.com/opinion/1922656/', '1922656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Tharp', 'https://www.courtlistener.com/opinion/1922656/', '1922656') ON CONFLICT DO NOTHING;
