INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we reversed the defendant‟s conviction, finding that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Palmer, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the credibility of the witnesses, we conclude that no reasonable fact-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'felony, we found that by engaging in kidnapping using a handgun, the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions for felony murder and criminal confinement.', 'general', 'Jenkins v. State', 'https://www.courtlistener.com/opinion/853639/', '853639') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the availability of this evidence to these appellants, we hold that this count of the indictment is not fatally vague or overbroad.', 'general', 'State v. Gunn', 'https://www.courtlistener.com/opinion/1297776/', '1297776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the convictions of those who are not coconspirators in that crime, holding they were entitled to directed verdicts of acquittal.', 'general', 'State v. Gunn', 'https://www.courtlistener.com/opinion/1297776/', '1297776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conspiracy convictions of appellants Olin Thompson, Ronnie Carpenter, Hazel Carpenter, Cliff Smith, Ed Smith, and Ken Smith for lack of evidence.', 'general', 'State v. Gunn', 'https://www.courtlistener.com/opinion/1297776/', '1297776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conspiracy convictions of appellants Lee Gunn, Evelyn Gunn, Harold Moss, and Earl Childers.', 'general', 'State v. Gunn', 'https://www.courtlistener.com/opinion/1297776/', '1297776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of the record, we hold that Perroni has failed to demonstrate the required bias on Judge Fox''s part.', 'general', 'Perroni v. State', 'https://www.courtlistener.com/opinion/2354900/', '2354900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm.', 'general', 'Perroni v. State', 'https://www.courtlistener.com/opinion/2354900/', '2354900') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the plaintiffs should be afforded their day in court.', 'general', 'Jones v. Fluor Daniel Services Corp.', 'https://www.courtlistener.com/opinion/1140983/', '1140983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this is not a situation which would merit an exception to the longstanding employment-at-will doctrine.', 'general', 'Jones v. Fluor Daniel Services Corp.', 'https://www.courtlistener.com/opinion/1140983/', '1140983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that Amaro''s statement would be admissible under M.', 'general', 'Jones v. Fluor Daniel Services Corp.', 'https://www.courtlistener.com/opinion/1140983/', '1140983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court erred in granting summary judgment as to the plaintiffs'' intentional infliction of emotional distress claims.', 'general', 'Jones v. Fluor Daniel Services Corp.', 'https://www.courtlistener.com/opinion/1140983/', '1140983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse and remand in part.', 'general', 'Jones v. Fluor Daniel Services Corp.', 'https://www.courtlistener.com/opinion/1140983/', '1140983') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the circuit court did not abuse its discretion in revoking the appellant’s probation.', 'general', 'State v. HOSBY', 'https://www.courtlistener.com/opinion/1231327/', '1231327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that if anything, the evidence supports manslaughter by culpable negligence.', 'general', 'Tait v. State', 'https://www.courtlistener.com/opinion/1142201/', '1142201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accord with Wells, Clemons, Dedeaux and other cases referred to in this opinion, we hold that it would serve no useful purpose to require the State and Tait to proceed with another trial for culpable negligence manslaughter.', 'general', 'Tait v. State', 'https://www.courtlistener.com/opinion/1142201/', '1142201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the defendant was convicted of manslaughter, this Court held that a jury issue was created as to whether the defendant was guilty of depraved heart murder because his conduct of moving and dumping the body and his initial statements denying the killing were not consistent with an accidental killing.', 'general', 'Tait v. State', 'https://www.courtlistener.com/opinion/1142201/', '1142201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), this Court held that evidence that the defendant pointed a gun at the victim, pulled the trigger, and the gun fired resulting in the victim''s death was sufficient to sustain a conviction of manslaughter by culpable negligence.', 'general', 'Tait v. State', 'https://www.courtlistener.com/opinion/1142201/', '1142201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that "The facts herein clearly support manslaughter.', 'general', 'Tait v. State', 'https://www.courtlistener.com/opinion/1142201/', '1142201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accord with Wells, we find that it would serve no useful purpose to subject the state and the defendant to another trial for manslaughter when the evidence has established guilt of that crime beyond a reasonable doubt.', 'general', 'Tait v. State', 'https://www.courtlistener.com/opinion/1142201/', '1142201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction of murder, affirm on culpable negligence manslaughter and remand the case to the lower court for resentencing only for the lesser offense of culpable negligence manslaughter.', 'sentencing', 'Tait v. State', 'https://www.courtlistener.com/opinion/1142201/', '1142201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After thorough consideration we find beyond a reasonable doubt that Tait''s conduct constituted the crime of manslaughter by culpable negligence and therefore we affirm on that crime.', 'general', 'Tait v. State', 'https://www.courtlistener.com/opinion/1142201/', '1142201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “evidence of prior misconduct is admissible when it has ‘independent logical relevance’ and when its probative value is not substantially outweighed by the danger of unfair prejudice.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1932472/', '1932472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, this Court holds that “when there is evidence that a statement about prior criminal activity was made by the defendant in order to threaten and intimidate his victim, and when force or threat of harm is an element of the crime for which the defendant is being tried, such evidence is admissible.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1932472/', '1932472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that “the requirement that the defendant ‘interfere substantially’ with the victim’s liberty insures that where the movement or restraint is
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that in order to allow a conviction for kidnapping in conjunction with an underlying crime such as rape, robbery, or assault, the movement and/or restraint of the victim must be more than incidental to the underlying crime.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1932472/', '1932472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that a specific instruction requiring the jury to find evidence of movement and/or restraint — that is not incidental to the underlying crime — to support an independent conviction for kidnapping may be desirable to assure the defendant a fair trial on both charges.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1932472/', '1932472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there is no merit to any of Weber’s other contentions.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1932472/', '1932472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the judge was not required by Canon 3C to disqualify himself and that there was no abuse of discretion when the trial judge declined to recuse himself.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1932472/', '1932472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial judge did not abuse his discretion, and, hence, did not commit plain error by not
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the juror’s responses to the trial judge’s questions, and in the absence of an objection from Weber’s attorney, we find that the trial judge did not commit plain error.', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1932472/', '1932472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In applying this holding to the facts of this case, we find that Weber’s statements to Long and Skidmore were properly admissible into evidence under Rule 404(b).', 'general', 'Weber v. State', 'https://www.courtlistener.com/opinion/1932472/', '1932472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that if a person commits one act of criminal violence, and that act is the only basis upon which he may be convicted of another crime, the act will merge into the other crime.', 'general', 'Commonwealth v. Anderson', 'https://www.courtlistener.com/opinion/2165027/', '2165027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*578 We held that it did not because the force requirement of kidnapping was supplied by holding the customer at gunpoint, not by the assault, and the assault was, therefore, a separate crime.', 'general', 'Commonwealth v. Anderson', 'https://www.courtlistener.com/opinion/2165027/', '2165027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Leon Williams we held that where the same facts are used to support convictions for crimes having different elements, the crimes do not merge for sentencing purposes, unless the same facts support convictions of lesser included offenses.', 'sentencing', 'Commonwealth v. Anderson', 'https://www.courtlistener.com/opinion/2165027/', '2165027') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we affirm the trial court on these issues, we reduce Wise’s conviction for arson as a Class A felony to a Glass B felony because the same evidence used by the jury to establish the essential elements of murder was also included among the evidence establishing the essential elements of arson as a Class A felony.', 'general', 'Wise v. State', 'https://www.courtlistener.com/opinion/853717/', '853717') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as this Court held in Rega and Speight, we also hold that Appellant has failed to demonstrate any prejudice "by counsel''s failure to ask life-qualification questions," particularly when "each juror underwent extensive questioning concerning his or her ability to follow the law and assured the trial court that he or she would be able to render a fair and impartial verdict and sentence.', 'sentencing', 'Commonwealth v. Natividad', 'https://www.courtlistener.com/opinion/1440383/', '1440383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Natividad', 'https://www.courtlistener.com/opinion/1440383/', '1440383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for all of the above-stated reasons, we affirm the order of the PCRA court.', 'general', 'Commonwealth v. Natividad', 'https://www.courtlistener.com/opinion/1440383/', '1440383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that an instruction requiring the jury to explain why it is rejecting a death sentence is not per se unconstitutional, and Appellant''s claim fails.', 'sentencing', 'Commonwealth v. Natividad', 'https://www.courtlistener.com/opinion/1440383/', '1440383') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the courts below erred in rejecting petitioner''s application for relief because of his failure to specify the points he would raise were his right to appeal reinstated.', 'general', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is nothing of record to establish that defendant''s trial counsel ever reviewed the plea proceedings for error before deciding not to pursue an appeal, and because it is contrary to the holdings of Flores-Ortega and Rodriquez under these circumstances to require defendant, who is proceeding pro se, to provide grounds for withdrawing his guilty plea and his appeal, we hold that the circuit court erred in dismissing defendant''s petition at the first stage of the post-conviction pro...', 'dismissal', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, "Under the Post-Conviction Hearing Act, the [defendant] must set forth the specific manner in which his rights were violated.', 'general', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Rule 604(d) serves as a condition precedent for an appeal from a defendant''s guilty plea.', 'plea', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Moore, this court held that the prejudice prong of the test for ineffective assistance of counsel (see Strickland v.', 'ineffective_assistance', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgments of the circuit and appellate courts.', 'general', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At the conclusion of its opinion, however, the appellate court stated: "We affirm the trial court''s dismissal of defendant''s postconviction petition.', 'dismissal', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '] At the conclusion of its opinion, however, the appellate court stated: `We affirm the trial court''s dismissal of defendant''s postconviction petition.', 'dismissal', 'People v. Edwards', 'https://www.courtlistener.com/opinion/2206677/', '2206677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Biegenwald IV, supra, we held that, in the penalty phase of a capital case, the trial court''s refusal to permit voir dire of the defendant''s other murder convictions denied the defendant his right to a fair and impartial jury.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Rose, supra, we held that the use of specific instances of prior misconduct to impeach a capital defendant''s character evidence was permitted under Evid.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Long, supra, we held that the defendant''s 1985 simple-assault conviction was properly introduced to rebut his assertion under mitigating factor N.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that the Sixth Amendment requires that a jury, and not a judge, find the existence of any aggravating circumstances, and that they be found, not by a mere preponderance of the evidence, but beyond a reasonable doubt.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances, this Court held that the trial court did not abuse its discretion by refusing to permit voir dire regarding the defendant''s prior conviction, because the defendant had not indicated a present intention to take the stand at trial.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Brunson, in which this Court held that when a defendant testifies and the State seeks to impeach his credibility with a prior criminal conviction that is similar in kind to the charged offense, the prior criminal conviction should be sanitized to minimize the potential improper use of the evidence to show propensity to commit the charged offense.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial errors were sufficiently egregious so as to deny defendant a fair trial and, therefore, we are constrained to reverse.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court improperly limited the scope of voir dire.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court committed reversible error in permitting Hazelwood to testify absent the production of a reliable database.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on that record, we conclude that the trial court did not abuse its discretion in keeping non-competent and irrelevant evidence before the jury.', 'general', 'State v. Fortin', 'https://www.courtlistener.com/opinion/1435973/', '1435973') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that section 4.', 'general', 'State v. Chrisman', 'https://www.courtlistener.com/opinion/2135158/', '2135158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that section 714.', 'general', 'State v. Chrisman', 'https://www.courtlistener.com/opinion/2135158/', '2135158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the seizure of Chrisman’s shoes was justified by the plain view exception to the Fourth Amendment warrant requirement.', 'search_seizure', 'State v. Chrisman', 'https://www.courtlistener.com/opinion/2135158/', '2135158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the value of the stolen property under the theft statute was an “element” used to determine punishment.', 'general', 'State v. Chrisman', 'https://www.courtlistener.com/opinion/2135158/', '2135158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Chrisman’s convictions on all counts and his sentences for second-degree burglary, vacate his sentences for third-degree theft, and remand for resentencing.', 'sentencing', 'State v. Chrisman', 'https://www.courtlistener.com/opinion/2135158/', '2135158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that Kupi-hea has failed to establish that the circuit court abused its discretion by accepting Wil-lets’s fifth amendment claim of privilege.', 'general', 'State v. Kupihea', 'https://www.courtlistener.com/opinion/1250910/', '1250910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the applicable factors, we hold that Kupihea has failed to show that the prosecutor’s conduct prejudiced his substantial rights and deprived him of a fair trial.', 'general', 'State v. Kupihea', 'https://www.courtlistener.com/opinion/1250910/', '1250910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of conviction.', 'general', 'State v. Kupihea', 'https://www.courtlistener.com/opinion/1250910/', '1250910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the circuit court was “right” in excluding the evidence of the cash because, under Kupihea’s defense as propounded at trial, the evidence was irrelevant.', 'general', 'State v. Kupihea', 'https://www.courtlistener.com/opinion/1250910/', '1250910') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At this juncture, it is helpful to recall that the failure to give the natural and probable consequences instruction affected only the premeditated murder count, and in the previous section, we held that the evidence of premeditation was insufficient to sustain a conviction of that crime.', 'general', 'State v. Winters', 'https://www.courtlistener.com/opinion/1485589/', '1485589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the principles of the foregoing cases to the one at bar, we conclude that the lower court did not err in omitting the natural and probable consequences instruction with respect to the especially aggravated robbery count, inasmuch as that count represented the target crime.', 'general', 'State v. Winters', 'https://www.courtlistener.com/opinion/1485589/', '1485589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, instructional error with respect to the first-degree premeditated murder conviction requires that we reverse that count and remand for a new trial.', 'general', 'State v. Winters', 'https://www.courtlistener.com/opinion/1485589/', '1485589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we are unconvinced that harmful error occurred, we affirm the defendant’s first-degree felony murder and aggravated robbery convictions.', 'general', 'State v. Winters', 'https://www.courtlistener.com/opinion/1485589/', '1485589') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that section 115— 7.', 'general', 'People v. Dabbs', 'https://www.courtlistener.com/opinion/2480728/', '2480728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the classification created by section 115 — 7.', 'general', 'People v. Dabbs', 'https://www.courtlistener.com/opinion/2480728/', '2480728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The language quoted above was in effect when this court held in Donoho that section 115— 7.', 'general', 'People v. Dabbs', 'https://www.courtlistener.com/opinion/2480728/', '2480728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statute met the rational basis test under equal protection analysis “because it also promotes effective prosecution of sex offenses and strengthens evidence in sexual abuse cases.', 'general', 'People v. Dabbs', 'https://www.courtlistener.com/opinion/2480728/', '2480728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that section 115 — 7.', 'general', 'People v. Dabbs', 'https://www.courtlistener.com/opinion/2480728/', '2480728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Dabbs', 'https://www.courtlistener.com/opinion/2480728/', '2480728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in refusing to question the jury about Woods-Alcide''s allegations.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above-stated reasons *179 regarding the trial court''s assessment of Woods-Alcide''s credibility, we hold that the trial court did not abuse its discretion in denying Boyd''s motion for a mistrial.', 'mistrial', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Boyd''s Brady claim is without merit.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that no Brady violation occurred.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Boyd''s claim is meritless because the trial court conducted a hearing sufficient to satisfy Richardson.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court properly conducted a Richardson hearing after the defense asserted the discovery violation, and we find no error.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Boyd''s motion for judgment of acquittal as to the sexual battery charge was properly denied by the trial court.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was competent, substantial evidence to support the jury''s guilty verdict for sexual battery.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court properly denied the motion for judgment of acquittal as to the armed kidnapping charge.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the substantial amount of DNA evidence against Boyd, as well as eyewitness testimony indicating that he was the last person seen with Dacosta, we hold that any error caused by admitting the citation is harmless.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1880670/', '1880670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we have no basis upon which to review the sanction order, we dismiss that portion of appellant’s appeal, and we affirm the May 23, 1994 order.', 'dismissal', 'Bettencourt v. Bettencourt', 'https://www.courtlistener.com/opinion/1250996/', '1250996') ON CONFLICT DO NOTHING;
