INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'statute and a traffic checkpoint, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a reasonable interpretation of the word “offense” as it appears in section 910A .', 'general', 'State v. Sailer', 'https://www.courtlistener.com/opinion/2016011/', '2016011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Sailer', 'https://www.courtlistener.com/opinion/2016011/', '2016011') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we hold that a nonresident motorist, although possessing a valid out-of-state license, may not operate a motor vehicle in this state following this state’s revocation of his driving privileges until the motorist complies with Tennessee’s reinstatement procedures.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1877289/', '1877289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A panel of this court held that evidence of the defendant’s restricted license before the jury was error under TenmR.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1877289/', '1877289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that all charges were properly joined pursuant to Tenn.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1877289/', '1877289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court properly denied the Appellant’s motion for judgment of acquittal.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1877289/', '1877289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not abuse its discretion in denying severance of the offenses.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1877289/', '1877289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review, we affirm.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1877289/', '1877289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review of the record, we affirm the judgments of conviction entered by the trial court.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1877289/', '1877289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), this Court held that a four-level downward departure was warranted because of the defendant''s good works that were of a personal nature.', 'general', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8] Therefore, we conclude that the District Court did not commit any procedural error at Tomko''s sentencing.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we conclude that the District Court did not abuse its discretion here.', 'general', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because we conclude that this sentence is substantively unreasonable, we dissent.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewed cumulatively, we conclude that the relevant § 3553(a) factors advocate in *586 the strongest possible terms for a sentence including a term of imprisonment.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[24]  To be clear, we acknowledge that § 3553(a)(3) and (7) arguably support certain aspects of the District Court''s lenient sentence, but we find it unnecessary to elaborate on these factors because we conclude that they are overpowered by § 3553(a)(1), (2), (4), (5), and (6), which advocate in the strongest possible terms for a sentence that includes some duration of imprisonment.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, in this case, given the Defendant''s lack of any significant criminal history, his involvement in exceptional charitable work and community activity, and his acceptance of responsibility, we find that a sentence that is mitigated by the factors of 3553[is] warranted.', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find it unnecessary to weigh in with our own cynical speculations as to the underlying motives of the authors of these letters, as we find that Tomko''s *585 "support in the community" and "charitable work" simply do not justify the degree of variance that was granted in this case, especially because his negligible criminal history and employment record keep him squarely in the category of typical tax evaders.', 'general', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the sentence imposed by the District Court fails to reflect the seriousness of the offense, promote respect for the law, provide just punishment for the offense, and afford adequate deterrence to criminal conduct, and therefore is inconsistent with the sentencing goals outlined in § 3553(a)(2)(A)-(B).', 'sentencing', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only when we discern an abuse-of-discretion.', 'general', 'United States v. Tomko', 'https://www.courtlistener.com/opinion/1253123/', '1253123') ON CONFLICT DO NOTHING;
