INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these responses, we hold that the trial court did not abuse its discretion in denying defendant’s requests to attempt to rehabilitate these jurors.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we hold that defendant has lost the benefit of his objection to Ms.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in allowing the State to question these rebuttal witnesses.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the great weight of evidence against defendant presented at trial, we hold that the combined effect of any erroneous evidentiary rulings was not prejudicial to defendant.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this evidence was sufficient to establish that defendant did more than merely leave the scene of the crime.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we hold that defendant’s attempt to read the facts from
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that while there was sufficient evidence to support submission of either aggravating circumstance, it was error to submit both.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these instructions were adequate and gave defendant the full benefit of relevant mitigating evidence.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that any error in not submitting this circumstance was harmless.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the evidence was insufficient to support submission of this mitigating circumstance, we hold that the trial court properly refused to submit it.', 'general', 'State v. Anthony', 'https://www.courtlistener.com/opinion/1247651/', '1247651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we hold that the sanction of dismissal by the trial court was improper and, accordingly, we affirm the order of the Superior Court.', 'dismissal', 'Commonwealth v. Burke', 'https://www.courtlistener.com/opinion/1494322/', '1494322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Superior Court’s reversal of the trial court’s dismissal of the charges against appellant and remand this matter to the trial court for a new trial.', 'dismissal', 'Commonwealth v. Burke', 'https://www.courtlistener.com/opinion/1494322/', '1494322') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the rules governing preliminary hearings in felony
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an appellate claim of prosecutorial misconduct presented
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the nature and extent of the evidence, we find that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Booher v. State', 'https://www.courtlistener.com/opinion/853112/', '853112') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, the state’s interest is overwhelming and outweighs the intrusion into a driver’s privacy and, thus, we hold that field sobriety tests are reasonable methods of conducting an investigation, based on specific and articulable facts that a driver is operating his or her vehicle contrary to I.', 'general', 'State v. Ferreira', 'https://www.courtlistener.com/opinion/1196184/', '1196184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that field sobriety tests are the least intrusive means
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that both the Fourth Amendment to the United States Constitution and Article I, Section 17 of the Idaho Constitution require reasonable suspicion that a driver is in violation of I.', 'search_seizure', 'State v. Ferreira', 'https://www.courtlistener.com/opinion/1196184/', '1196184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that field sobriety tests are the most reasonable, least intrusive method of confirming or dispelling an officer’s suspicion.', 'general', 'State v. Ferreira', 'https://www.courtlistener.com/opinion/1196184/', '1196184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that, in the instant case, the officer possessed reasonable suspicion that Ferreira was driving in violation of I.', 'general', 'State v. Ferreira', 'https://www.courtlistener.com/opinion/1196184/', '1196184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the odor of alcohol on the driver’s breath, the driver’s slurred speech, and the driver’s admitted alcohol consumption amounted to reasonable suspicion that the driver was under the influence and, thus, the administration of field sobriety tests was constitutionally proper.', 'general', 'State v. Ferreira', 'https://www.courtlistener.com/opinion/1196184/', '1196184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the administration of field sobriety tests following a traffic stop is but an investigative detention.', 'general', 'State v. Ferreira', 'https://www.courtlistener.com/opinion/1196184/', '1196184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Ferreira', 'https://www.courtlistener.com/opinion/1196184/', '1196184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Rutherford has not demonstrated that his appellate counsel was deficient with respect to his performance as to issues that were actually raised on direct appeal.', 'general', 'Rutherford v. Moore', 'https://www.courtlistener.com/opinion/1734913/', '1734913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, Rutherford cites no cases establishing that the failure to give these instructions constitutes reversible error, and we find that Rutherford has established neither deficiency nor prejudice with regard to the failure to raise these issues on appeal.', 'general', 'Rutherford v. Moore', 'https://www.courtlistener.com/opinion/1734913/', '1734913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because trial counsel''s alleged ineffectiveness was not apparent from the record, we find that appellate counsel was not constitutionally ineffective for failing to raise trial counsel''s ineffectiveness on direct appeal.', 'ineffective_assistance', 'Rutherford v. Moore', 'https://www.courtlistener.com/opinion/1734913/', '1734913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988) (stating that when "one of two convictions must fall, we hold that the conviction of the lesser crime should be set aside").', 'general', 'Pizzo v. State', 'https://www.courtlistener.com/opinion/1818779/', '1818779') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A comparison of statutory elements is the proper method for determining a lesser offense in the double jeopardy context, and based upon a comparison of the statutory elements, we find that grand theft is a lesser offense of organized fraud.', 'general', 'Pizzo v. State', 'https://www.courtlistener.com/opinion/1818779/', '1818779') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Mr.', 'general', 'Pizzo v. State', 'https://www.courtlistener.com/opinion/1818779/', '1818779') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the express language of Article 38.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Nguyen''s oral statement was inadmissible under Section 3 of Article 38.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[25] In that case, we held that an individual incarcerated for one offense is not necessarily "in custody" under Miranda and Article 38.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that Nielssen was not under arrest and therefore implied that Nielssen was not in custody.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals''s judgment.', 'general', 'Thai Ngoc Nguyen v. State', 'https://www.courtlistener.com/opinion/2172209/', '2172209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the balance to be struck falls within the wide discretion of the trial court.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/2264175/', '2264175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that defendant''s motive in fleeing from the police was irrelevant to the offense.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/2264175/', '2264175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lee', 'https://www.courtlistener.com/opinion/2264175/', '2264175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that since the Code requires this high standard even to downgrade, it “must have contemplated an even higher standard to give confidence to the ‘in or out’ decision.', 'general', 'State v. Roth', 'https://www.courtlistener.com/opinion/2272972/', '2272972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1, 9 (1981), a pre-Code case, we held that double jeopardy principles
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we find that the provisions for State sentence appeal lack sufficient standards to guide decisionmakers thus resulting in arbitrary and uneven sentence appeal by prosecutors: “Vague laws deprive citizens of adequate notice of proscribed conduct,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we find that the provisions for State appeal affect principles of fundamental fairness that we apply in supervision of the administration of justice.', 'general', 'State v. Roth', 'https://www.courtlistener.com/opinion/2272972/', '2272972') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the evidence is fragile, in view of the stage of the proceedings at this point we conclude that it was sufficient to satisfy the burden of a prima facie case.', 'general', 'Commonwealth v. Wojdak', 'https://www.courtlistener.com/opinion/1971909/', '1971909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" For the reasons that follow, we reverse in part and affirm in part the Order of the Superior Court.', 'general', 'Commonwealth v. Wojdak', 'https://www.courtlistener.com/opinion/1971909/', '1971909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this case is distinguishable on its facts and not governed by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that defendant’s contentions claiming denial of effective assistance of counsel and a fair trial must fail.', 'general', 'Dutton v. State', 'https://www.courtlistener.com/opinion/1929760/', '1929760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having examined the transcript, we find that the Trial Judge, being in the same position as the jury with regard to viewing demeanor and hearing the statement, took immediate steps to consider and correct any prejudice which could be attributed to it.', 'general', 'Dutton v. State', 'https://www.courtlistener.com/opinion/1929760/', '1929760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was no “rational basis” for the Trial Judge to have charged the jury with the above-mentioned lesser-included offenses.', 'general', 'Dutton v. State', 'https://www.courtlistener.com/opinion/1929760/', '1929760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At the outset, we hold that DeVarona and Feldman properly testified as lay witnesses.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court erred in failing to explain its determination that Defendant White be held accountable for loss in the amount of $7,290,202.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the witness relied solely on information provided by the plaintiff company to calculate projected loss, we concluded that he lacked the basis necessary to offer such lay testimony.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the prosecution, we find that a rational trier of fact could find the essential elements of each of the offenses underlying Defendant White''s conviction beyond a reasonable doubt.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing, we find that Defendant White has failed to sustain his "heavy burden" on this issue, and that there was sufficient evidence at trial to support his convictions for Medicare fraud, conspiracy to commit Medicare fraud, and use of a false document.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we find that, viewing the evidence in the light most favorable to the prosecution, sufficient evidence supports Defendant White''s conviction for money laundering.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we found that the government violated Federal Rule of Criminal Procedure 16(a)(1)(G).', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse only where the district court''s erroneous admission of evidence affects a substantial right of the party.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When faced with a challenge to the amount of restitution ordered, we reverse only if the district court abused its discretion.', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we AFFIRM Defendants'' convictions;', 'general', 'United States v. White', 'https://www.courtlistener.com/opinion/1446782/', '1446782') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a defendant may decide to raise a claim of ineffectiveness of counsel on direct appeal, but, if so raised, "the issue will be foreclosed from collateral review.', 'ineffective_assistance', 'McIntire v. State', 'https://www.courtlistener.com/opinion/853753/', '853753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these jury instructions, we find that the defendant has demonstrated a reasonable possibility that the jury used the same evidentiary facts (Hilt''s head injury caused by the baseball bat) to establish the essential elements of both class A burglary and class D criminal recklessness.', 'jury_instruction', 'McIntire v. State', 'https://www.courtlistener.com/opinion/853753/', '853753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[9]  The only time we have found remand for re-sentencing to be unnecessary is when we affirmed all convictions and the trial court ordered identical sentences to run concurrently.', 'sentencing', 'McIntire v. State', 'https://www.courtlistener.com/opinion/853753/', '853753') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a second motion for rehearing is required because Rule 32.', 'general', 'State v. Bortz', 'https://www.courtlistener.com/opinion/1238012/', '1238012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS ORDERED that the Petition be dismissed.', 'dismissal', 'State v. Bortz', 'https://www.courtlistener.com/opinion/1238012/', '1238012') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that without an ineffectiveness hearing, “there is an insufficient factual record to consider the claim.', 'ineffective_assistance', 'Commonwealth v. Powell', 'https://www.courtlistener.com/opinion/2313776/', '2313776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 726 (2002), in which this Court held that ineffectiveness claims are generally not reviewable on direct appeal, but should be deferred until collateral review.', 'ineffective_assistance', 'Commonwealth v. Powell', 'https://www.courtlistener.com/opinion/2313776/', '2313776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed all of appellant’s claims, we conclude that relief is not warranted.', 'general', 'Commonwealth v. Powell', 'https://www.courtlistener.com/opinion/2313776/', '2313776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review, we conclude that the evidence was sufficient to support all three aggravating factors found by the jury.', 'general', 'Commonwealth v. Powell', 'https://www.courtlistener.com/opinion/2313776/', '2313776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that a verdict of first-degree murder was amply supported by evidence that the appellant had starved her daughter to death over a long period of time.', 'general', 'Commonwealth v. Powell', 'https://www.courtlistener.com/opinion/2313776/', '2313776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the issues raised by appellant either to be without merit or unreviewable, we affirm the convictions and judgment of sentence.', 'sentencing', 'Commonwealth v. Powell', 'https://www.courtlistener.com/opinion/2313776/', '2313776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the verdict and the sentence of death imposed upon appellant by the Court of Common Pleas of Philadelphia County, and dismiss appellant’s claims of ineffectiveness of trial counsel without prejudice to appellant’s right to raise those claims on collateral review under the PCRA.', 'dismissal', 'Commonwealth v. Powell', 'https://www.courtlistener.com/opinion/2313776/', '2313776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the magistrate properly interpreted the elements of the felony domestic violence statute, we conclude that it did not reach a decision consistent with the definition of probable cause as used in the context of preliminary hearings.', 'probable_cause', 'State v. Reyes', 'https://www.courtlistener.com/opinion/2538524/', '2538524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the magistrate erred when it determined that the state failed to show probable cause to believe that Reyes willfully inflicted a traumatic injury.', 'probable_cause', 'State v. Reyes', 'https://www.courtlistener.com/opinion/2538524/', '2538524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the district court and remand for further proceedings.', 'general', 'State v. Reyes', 'https://www.courtlistener.com/opinion/2538524/', '2538524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the decision of the district court affirming the magistrate’s order reducing felony domestic violence to misdemeanor battery and remand for further proceedings.', 'general', 'State v. Reyes', 'https://www.courtlistener.com/opinion/2538524/', '2538524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, after reviewing the record, we conclude that there was no reversible error on this point.', 'general', 'State v. Sayre', 'https://www.courtlistener.com/opinion/1219503/', '1219503') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not abuse its discretion in admitting evidence offered by Mr.', 'general', 'Commonwealth v. Chamberlain', 'https://www.courtlistener.com/opinion/2317878/', '2317878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On direct appeal to this Court, we held that the trial court abused its discretion in denying a pretrial motion for continuance to allow Appellant to obtain DNA testing of certain blood evidence.', 'general', 'Commonwealth v. Chamberlain', 'https://www.courtlistener.com/opinion/2317878/', '2317878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we held that Kim Ulrich’s testimony regarding the telephone conversation was admissible under two exceptions to the general prohibition of hearsay evidence, either as an excited utterance, 731 A.', 'general', 'Commonwealth v. Chamberlain', 'https://www.courtlistener.com/opinion/2317878/', '2317878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we held that the participation of a deputy attorney general in the prosecution was appropriate.', 'general', 'Commonwealth v. Chamberlain', 'https://www.courtlistener.com/opinion/2317878/', '2317878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court abused its discretion in denying Appellant’s pretrial motion for a continuance to allow him to obtain DNA testing of the blood evidence.', 'general', 'Commonwealth v. Chamberlain', 'https://www.courtlistener.com/opinion/2317878/', '2317878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that suppression was required where the Commonwealth sought to introduce expert testimony that a lottery ticket was forged, and the Commonwealth lost the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the evidence in this case was sufficient to support Appellant’s first-degree murder convictions.', 'general', 'Commonwealth v. Chamberlain', 'https://www.courtlistener.com/opinion/2317878/', '2317878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although this is a troubling issue, we conclude that no relief is warranted.', 'general', 'Commonwealth v. Chamberlain', 'https://www.courtlistener.com/opinion/2317878/', '2317878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that these instances of alleged prosecutorial misconduct in the closing argument did not individually nor in the aggregate prejudice Appellant, this claim fails.', 'general', 'Commonwealth v. Chamberlain', 'https://www.courtlistener.com/opinion/2317878/', '2317878') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nichols, we conclude that Appellant is not entitled to a new trial for the reasons stated
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the alleged discovery violations do not require vacating Defendant’s convictions.', 'general', 'State v. Fukusaku', 'https://www.courtlistener.com/opinion/1124343/', '1124343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1281 (1990), we held that the prosecution has no right to appeal discovery orders before trial;', 'general', 'State v. Fukusaku', 'https://www.courtlistener.com/opinion/1124343/', '1124343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1200 (1975), we held that the longhand notes of a police detective were not a "statement” under HRCrP Rule 17 and were not subject to production.', 'general', 'State v. Fukusaku', 'https://www.courtlistener.com/opinion/1124343/', '1124343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1298 (1992), this court held that the failure of counsel to call certain witnesses constituted ineffective assistance of counsel;', 'ineffective_assistance', 'State v. Fukusaku', 'https://www.courtlistener.com/opinion/1124343/', '1124343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 43 (1995), this court held that “[e]vidence that a third person had
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that “HRS § 706-660.', 'general', 'State v. Fukusaku', 'https://www.courtlistener.com/opinion/1124343/', '1124343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS HEREBY ORDERED that Defendant’s convictions of two counts of murder in the second degree are affirmed;', 'general', 'State v. Fukusaku', 'https://www.courtlistener.com/opinion/1124343/', '1124343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that, in a jury trial, issues decided by the judge are “questions of law” appealable under HRS § 641-13, while issues decided by the jury are “questions of fact” and are not appealable.', 'general', 'State v. Fukusaku', 'https://www.courtlistener.com/opinion/1124343/', '1124343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), where we held that before admitting evidence of other crimes, a trial court must first conduct a jury-out hearing to determine the purpose for which the evidence is being offered, and to determine whether its probative value is outweighed by its prejudicial effect.', 'general', 'State v. Rickman', 'https://www.courtlistener.com/opinion/2455811/', '2455811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, in both
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Tennessee should not recognize a “sex crimes” exception to the general rule, but that it has recognized a narrow special rule which admits prior sex crimes into evidence if they are included in the indictment.', 'general', 'State v. Rickman', 'https://www.courtlistener.com/opinion/2455811/', '2455811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And so we hold that it is a defense to allege and prove good faith and reasonable belief in the validity of the arrest.', 'general', 'Children v. Burton', 'https://www.courtlistener.com/opinion/1613914/', '1613914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this arrest was on probable cause.', 'probable_cause', 'Children v. Burton', 'https://www.courtlistener.com/opinion/1613914/', '1613914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this retention, following the lawful arrest, was also lawful.', 'general', 'Children v. Burton', 'https://www.courtlistener.com/opinion/1613914/', '1613914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a plain reading of Section 9765 reveals the General Assembly''s intent that crimes with different statutory elements be punished separately.', 'general', 'Commonwealth v. Baldwin', 'https://www.courtlistener.com/opinion/2056083/', '2056083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As each of the two offenses here contains distinct elements, we conclude that, under Section 9765, the consecutive sentences imposed were proper.', 'sentencing', 'Commonwealth v. Baldwin', 'https://www.courtlistener.com/opinion/2056083/', '2056083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Baldwin', 'https://www.courtlistener.com/opinion/2056083/', '2056083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the defendant must receive a new trial.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 911 (1989), this Court held that an indictment charging "that defendant `unlawfully, willfully and feloniously and of malice aforethought did kill and murder [the victim]'' is insufficient to support a verdict of guilty of assault, assault inflicting serious injury or assault with intent to kill" because such murder indictment does not specify a murder accomplished by assault.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having done so, we conclude that this is one of those rare cases in which the trial court''s error in failing to instruct on the lesser-included offense was, on the evidence presented, error so fundamental that it denied the defendant a fair trial and quite probably tilted the scales against him.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the defendant must receive a new trial.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that any error involved in the defendant''s conviction and sentence for attempted murder in Gilley was harmless for reasons which are of no consequence here and have since been rejected.', 'sentencing', 'State v. Collins', 'https://www.courtlistener.com/opinion/1364546/', '1364546') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that section 243.', 'general', 'Boutin v. LaFleur', 'https://www.courtlistener.com/opinion/1313375/', '1313375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, because Boutin was charged with an enumerated predatory offense and was convicted of another offense which arose out of the same set of circumstances as the charged predatory offense, we conclude that he was required to register under the provisions of section 243.', 'general', 'Boutin v. LaFleur', 'https://www.courtlistener.com/opinion/1313375/', '1313375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that section 243.', 'general', 'Boutin v. LaFleur', 'https://www.courtlistener.com/opinion/1313375/', '1313375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Boutin v. LaFleur', 'https://www.courtlistener.com/opinion/1313375/', '1313375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*473 Viewing the evidence in the light most favorable to the prosecution, we hold that a rational trier of fact could have found beyond a reasonable doubt that defendant was accountable for Debra''s and Samantha''s murders.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court properly found that, in the statements at issue, Joshua related an "act or matter or detail pertaining to any act which is an element of an offense which is the subject of a prosecution for a sexual or physical act against" him.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court correctly decided that, except for Joshua''s denial that he took medication, his statements were admissible under the spontaneous declaration exception to the hearsay rule.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant''s eligibility may be upheld based on the felony-murder statutory aggravating factor predicated on Joshua''s murder.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the challenged verdict form did not omit the required elements for eligibility under section 9-1(b)(6) and, therefore, find no plain error.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant was properly found eligible for the death penalty based on the felony-murder statutory aggravating factor premised on Joshua''s murder.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Coleman, we held that a de novo, rather than an abuse of discretion or manifestly erroneous, standard of review applies to a circuit court''s decision to dismiss a defendant''s claims under the Post-Conviction Hearing Act (725 ILCS 5/122-1 et seq.', 'dismissal', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mitchell, this court held that the circuit court erred in admitting hearsay statements by a child alleging sexual abuse because the circuit court failed to conduct a hearing, as required by section 115-10, and because the record did not support a conclusion that the statements were reliable.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brownell, this court held that the defendant was entitled to a new second stage sentencing hearing because the jury had considered an invalid aggravating factor at that stage.', 'sentencing', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, in Pasch, this court held that the felony-murder statutory aggravating factor was invalid because the evidence at trial did not support the predicate felony, but the jury''s consideration of this factor at the aggravation-mitigation stage was harmless.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2180253/', '2180253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Trott', 'https://www.courtlistener.com/opinion/2223950/', '2223950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding the defendant''s contentions to be without merit, we affirm.', 'general', 'State v. Trott', 'https://www.courtlistener.com/opinion/2223950/', '2223950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to the trial court.', 'general', 'State v. Fuller', 'https://www.courtlistener.com/opinion/1286797/', '1286797') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse his conviction under this statute.', 'general', 'State v. Ahitow', 'https://www.courtlistener.com/opinion/1991494/', '1991494') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the denial of the father’s continuance motion
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the superior court’s finding that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that in these circumstances the State may not use as evidence the fruits of a search incident to an illegal arrest.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Superior Court erred as a matter of Delaware statutory and Delaware constitutional law in denying Jones'' motion to suppress evidence seized on the night of January 11, 1997.', 'suppression', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a seizure took place within the meaning of .', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the *868 trial court''s determination was clearly erroneous.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the defendant was illegally seized, in violation of article first, §§ 7 and 9 of the Connecticut constitution.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[64] We conclude that Jones'' actions in walking away from Patrolman Echevarria and his refusal to obey or submit to the officer''s commands to stop and remove his hands from his pockets did not furnish grounds for reasonable and articulable suspicion to effect the seizure.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 1902 and Article I, § 6 of the Delaware Constitution, we find that Patrolman Echevarria did not possess a reasonable and articulable suspicion to stop Jones.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this criminal appeal, we reverse the judgment and sentence of the Superior Court because evidence was invalidly seized from the defendant.', 'sentencing', 'Jones v. State', 'https://www.courtlistener.com/opinion/2087727/', '2087727') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In examining the record to determine if the proffered reasons are supported therein, we find that they are not.', 'general', 'Commonwealth v. Widmer', 'https://www.courtlistener.com/opinion/2264742/', '2264742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the decision of the Superior Court.', 'general', 'Commonwealth v. Widmer', 'https://www.courtlistener.com/opinion/2264742/', '2264742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the reasons as stated herein, we affirm the decision of the Superior Court.', 'general', 'Commonwealth v. Widmer', 'https://www.courtlistener.com/opinion/2264742/', '2264742') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the issue was preserved for appeal, and we need not discuss whether the arguments made to the trial judge at the hearing on Martin''s motion for a new trial for failure to give the instruction sufficed to preserve the issue.', 'general', 'Martin v. Commonwealth', 'https://www.courtlistener.com/opinion/1235726/', '1235726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the conviction and remand for a new trial.', 'general', 'Martin v. Commonwealth', 'https://www.courtlistener.com/opinion/1235726/', '1235726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we hold that the prosecution presented sufficient evidence to prove armed robbery and felony murder beyond a reasonable doubt.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the plain error rule discussed in Olano and Grant extends to unpreserved claims of constitutional error.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regarding the instructional issue, we hold that the Olano/Grant forfeiture rule applies to unpreserved claims of constitutional error.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that plain error occurred, but that it was not decisive of the outcome.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the unpublished opinion of the Court of Appeals, which affirmed defendant''s convictions and sentence.', 'sentencing', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Appeals.', 'general', 'People v. Carines', 'https://www.courtlistener.com/opinion/1693796/', '1693796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that the particular course chosen by counsel had some reasonable basis, our inquiry ceases and counsel’s assistance is deemed effective.', 'general', 'Commonwealth v. Pierce', 'https://www.courtlistener.com/opinion/1960329/', '1960329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review of the record we conclude that the sentence imposed was not the product of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Commonwealth v. Pierce', 'https://www.courtlistener.com/opinion/1960329/', '1960329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the crime of interference with official acts, section 719.', 'general', 'State v. Buchanan', 'https://www.courtlistener.com/opinion/2032316/', '2032316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Buchanan', 'https://www.courtlistener.com/opinion/2032316/', '2032316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that both enhancement factors were appropriate.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1772026/', '1772026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the § 40-35-114(10) enhancement factor was properly applied based upon evidence of the risk to the fives of firefighters.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1772026/', '1772026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the “particularly vulnerable victim” enhancement factor, Tenn.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1772026/', '1772026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that the record supports the “multiple victim” enhancement factor found at Tenn.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1772026/', '1772026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that multiple-resident aggravated arson is the very type of crime to which the legislature intended the § 40-35-114(10) enhancement factor to be applicable.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1772026/', '1772026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that the record supports the “multiple victim” enhancement factor, Tenn.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1772026/', '1772026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court properly increased Lewis’s sentence within the applicable range to reflect the enhancement factors and then reduced the sentence according to the mitigating evidence.', 'sentencing', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1772026/', '1772026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals as modified and affirm the twenty-one-year sentence imposed by the trial court.', 'sentencing', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1772026/', '1772026') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that a bona fide claim of right is a sincere, although perhaps mistaken, good faith belief that one has some legal right to be on the property.', 'general', 'Reed v. Commonwealth', 'https://www.courtlistener.com/opinion/1272164/', '1272164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that he established a bona fide claim of right as a matter of law.', 'general', 'Reed v. Commonwealth', 'https://www.courtlistener.com/opinion/1272164/', '1272164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the evidence was insufficient to support the conviction, we do not address the issue of jury instructions.', 'jury_instruction', 'Reed v. Commonwealth', 'https://www.courtlistener.com/opinion/1272164/', '1272164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the case before us presents the certainty of a miscarriage of justice apparent in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we reverse and dismiss on the grounds of sufficiency of the evidence, we do not reach the issue of the jury instructions.', 'dismissal', 'Reed v. Commonwealth', 'https://www.courtlistener.com/opinion/1272164/', '1272164') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding any defect to be harmless, we affirm.', 'general', 'Wayt v. State', 'https://www.courtlistener.com/opinion/1119167/', '1119167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this same evidence is sufficient to prove the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the search of appellant''s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the convictions.', 'general', 'Archer v. Commonwealth', 'https://www.courtlistener.com/opinion/1067256/', '1067256') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in allowing the conviction to stand.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such an experience meets the requirement of a sufficiently startling event.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, even if this statement is not admissible under the excited utterance exception, we hold that there is still no error
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the same standard of review set out above, we hold that the evidence taken in the light most favorable to the State does support a conviction of first-degree murder.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant has presented no evidence that he believed it was necessary to kill the deceased in order to save himself from death or great bodily harm;', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, having carefully reviewed the record and each of defendants’ assignments of error, we hold that defendants received a fair trial, free of prejudicial error.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the instructions would not have “caused the jurors to conclude that defendant acted with premeditation or deliberation merely because the evidence showed that defendant did not act in a heat of passion following adequate provocation the proof of which reduces the degree of homicide to voluntary manslaughter.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was substantial evidence from which the jury could reasonably infer that defendant Reid shot Antwane Drakeford with a deadly weapon, with the intent to kill, inflicting serious injury.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our previous decisions that it is not required that a principal be convicted in order for an aider and abettor to be convicted, and the United States Supreme Court’s view on inconsistent verdicts, we conclude that defendant Reid’s conviction should stand.', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge’s finding that defendant waived his rights under standingly, knowingly, and willingly is supported by competent evidence;', 'general', 'State v. Reid', 'https://www.courtlistener.com/opinion/1304224/', '1304224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the record supports such findings, we conclude that the court comported with due process by relying on information meeting the “minimal indicium of reliability beyond mere allegation” standard under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we conclude that the information relied upon lacked “some minimal indicium of reliability beyond mere allegation.', 'general', 'Mayes v. State', 'https://www.courtlistener.com/opinion/1481740/', '1481740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful examination, we find that defendant’s motion for reduction of sentence did not present any evidence which made any information relied upon by the sentencing court constitutionally unreliable.', 'sentencing', 'Mayes v. State', 'https://www.courtlistener.com/opinion/1481740/', '1481740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'Mayes v. State', 'https://www.courtlistener.com/opinion/1481740/', '1481740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We recognize that this Court held hi
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶26] If we conclude that a defendant fails to satisfy the prejudice prong, we need not address the performance of counsel prong:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no prejudicial error, we affirm.', 'general', 'Rutti v. State', 'https://www.courtlistener.com/opinion/2634523/', '2634523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record contains ample, indeed overwhelming, evidence in support of the jury’s verdicts.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1564448/', '1564448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any expectation of privacy under the circumstances of this case was unreasonable.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1564448/', '1564448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we affirm the convictions of both appellants.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1564448/', '1564448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the trial court in this ease abused its discretion by failing to undertake further inquiry into the defendant’s mental competency.', 'general', 'State v. Sanders', 'https://www.courtlistener.com/opinion/1287992/', '1287992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the fact that the psychological assessment that informed the trial court’s original competency determination was partly contingent upon an immediate trial that did not materialize, we find that this later psychiatric report, particularly when viewed in conjunction with the defendant’s aberrant behavior at trial, constituted a sufficient change of circumstance to raise good faith doubt as to Sanders’ continued mental fitness for trial.', 'general', 'State v. Sanders', 'https://www.courtlistener.com/opinion/1287992/', '1287992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that where a criminal defendant has already been afforded a competency hearing pursuant to W.', 'general', 'State v. Sanders', 'https://www.courtlistener.com/opinion/1287992/', '1287992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that Hock''s remark did not constitute disorderly conduct, and the officer thus lacked probable cause to arrest her for that offense.', 'probable_cause', 'Commonwealth v. Hock', 'https://www.courtlistener.com/opinion/1441554/', '1441554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we find the conduct at issue insufficient to support an arrest, we reverse.', 'general', 'Commonwealth v. Hock', 'https://www.courtlistener.com/opinion/1441554/', '1441554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Superior Court insofar as, it relates to the charge of resisting arrest, and reinstate the trial court''s order dismissing that charge.', 'dismissal', 'Commonwealth v. Hock', 'https://www.courtlistener.com/opinion/1441554/', '1441554') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that any error in this case is
