INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 507), we hold that they did not prejudice defendant such as to deny defendant a fair trial or threaten deterioration of the judicial process.', 'general', 'People v. Ceja', 'https://www.courtlistener.com/opinion/2200687/', '2200687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 497, 512-13 (1986), in which this court held that it had been improper for an expert to testify, as Luckas did here, that there was a “good probability” that two pieces of glass had a common source.', 'general', 'People v. Ceja', 'https://www.courtlistener.com/opinion/2200687/', '2200687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the challenged testimony, we conclude that its allegedly erroneous admission is not of such a character.', 'general', 'People v. Ceja', 'https://www.courtlistener.com/opinion/2200687/', '2200687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As in Linscott, we find that the prosecutor’s above-quoted comments in this case overstated the evidence.', 'general', 'People v. Ceja', 'https://www.courtlistener.com/opinion/2200687/', '2200687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in order to sustain a conviction for
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '”    Accordingly, we affirm
