INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This is of no consequence, however, because we find that the Commonwealth failed to demonstrate that Appellant possessed the necessary
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Commonwealth v. Bullick', 'https://www.courtlistener.com/opinion/1922709/', '1922709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if Officer Maggitti’s initial approach and questioning of defendant constitute a “seizure,” we hold that such a limited detainment was justified by defendant’s violation of the noise ordinance.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since Robertson’s responses were contradictory and arguably evasive, we conclude that Officer Maggitti had a reasonable basis for his suspicion that the car was stolen.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing all the circumstances of this case, we conclude that Officer Maggit-ti was justified in conducting a limited pat-down for weapons to insure his safety.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found reasonable suspicion for the stop and frisk under the circumstances, we conclude that defendant’s remaining arguments for exclusion of evidence must be rejected.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the General Assembly intended the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the plain error standard, we conclude that defendant’s right to a fair trial and due process have been infringed in a fundamental manner.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the prosecutor’s remarks constituted impermissible comments on defendant’s election not to testify, and further that such remarks amount to plain error.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the question is a close one, given the totality of the circumstances, we find that such a reasonable, articulable suspicion did exist.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given all these facts, we find that the officer reasonably feared for his safety.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the frequency of the improper remarks compels the conclusion that their purpose was to create an inference of guilt by focusing the jury’s attention on defendant’s failure to testify in support of his innocence.', 'general', 'Robertson v. State', 'https://www.courtlistener.com/opinion/2175914/', '2175914') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the videotapes do not rise to the level of materially exculpatory evidence.', 'general', 'Chissell v. State', 'https://www.courtlistener.com/opinion/1998720/', '1998720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Chissell was not denied due process of law.', 'general', 'Chissell v. State', 'https://www.courtlistener.com/opinion/1998720/', '1998720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State proved beyond a reasonable doubt that Chissell drove his vehicle in an impaired condition of thought and action and that his condition posed a danger to himself or others on the public roadways.', 'general', 'Chissell v. State', 'https://www.courtlistener.com/opinion/1998720/', '1998720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and dismiss in part.', 'dismissal', 'Chissell v. State', 'https://www.courtlistener.com/opinion/1998720/', '1998720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Chissell’s conviction for driving while intoxicated.', 'general', 'Chissell v. State', 'https://www.courtlistener.com/opinion/1998720/', '1998720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, upon review of the record we hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a thorough review of the evidence presented at trial, we hold that sufficient evidence supports Salazar''s conviction under both premeditated and felony murder theories.', 'general', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the imposition of the death penalty in this case is not disproportionate to other cases decided by this Court.', 'general', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), we held that "use of a harmless error analysis under [State v.', 'general', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that while the prosecutor''s comments were improper, they were not so prejudicial as to deny Salazar a fair trial.', 'general', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court in this case neither sustained Parker''s objection in front of the jury nor gave a curative instruction, we conclude that a harmless error analysis is appropriate in this case.', 'general', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth in this opinion, we affirm Salazar''s conviction and sentence.', 'sentencing', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s ruling.', 'general', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court''s ruling on Salazar''s objection to Detective Brock''s testimony that he was "trying to find the truth" in his investigation.', 'general', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Salazar''s conviction and death sentence.', 'sentencing', 'Salazar v. State', 'https://www.courtlistener.com/opinion/1818171/', '1818171') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Eastman', 'https://www.courtlistener.com/opinion/1399360/', '1399360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s refusal to give defendant''s requested instruction No.', 'general', 'State v. Eastman', 'https://www.courtlistener.com/opinion/1399360/', '1399360') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we hold that, for purposes of section 401(a)(6.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the search warrant at issue in this case did not violate the warrant clause of the Illinois Constitution (Ill.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the warrant described the items to be seized with sufficient particularity.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgments of the appellate court.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgments of the appellate court.', 'general', 'People v. McCarty', 'https://www.courtlistener.com/opinion/2045025/', '2045025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed Johnson’s conviction of abduction with intent to defile because the evidence did not support a finding that Johnson intended either to defile his victim
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1996), a majority of this court held that testimony concerning the victim''s good character is inadmissible.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, four members of this Court held that victim impact evidence was admissible but victim character evidence was not.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the above discussion, we conclude that the comments in the present case were mildly inappropriate.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the rule may not always apply in the same fashion to the erroneous exclusion of evidence, we find that the admission of evidence similar to what the appellant wished to offer may, under some circumstances, mitigate against the harm he would have otherwise suffered.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that such comments constitute "other errors" within the purview of Rule 44.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the second factor, we find that no curative action was taken.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we find that the third factor weighs heavily in favor of the State.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that admission of this testimony did not violate Rule 403.', 'general', 'Mosley v. State', 'https://www.courtlistener.com/opinion/1678386/', '1678386') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that interpretation of AS 12.', 'general', 'State v. Roberts', 'https://www.courtlistener.com/opinion/1159661/', '1159661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we find that Jury Instruction S-2 did create a mandatory presumption.', 'jury_instruction', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the circuit court erred in denying Durham''s motion for a new trial.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Durham appeals his conviction, and finding error, we reverse the circuit court''s judgment and remand for a new trial.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we find error in the circuit court''s denial of Durham''s motion for a new trial, and we reverse the court''s judgment and remand this case for further proceedings consistent with this opinion.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the circuit court and remand for a new trial in accordance with this opinion.', 'general', 'Durham v. State', 'https://www.courtlistener.com/opinion/2492385/', '2492385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following this familiar approach, we conclude that an unlawful “seizure” of the person occurred in this case and that the trial court erred in denying the motion to suppress evidence abandoned by appellant in response to the unlawful conduct of the police.', 'suppression', 'In Re the Welfare of E.D.J.', 'https://www.courtlistener.com/opinion/1826977/', '1826977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a person has been “seized” within the meaning of the Fourth Amendment only if, in view of all of the circumstances surrounding the incident, a reasonable person would have believed that he was not free to leave.', 'search_seizure', 'In Re the Welfare of E.D.J.', 'https://www.courtlistener.com/opinion/1826977/', '1826977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that they did not.', 'general', 'In Re the Welfare of E.D.J.', 'https://www.courtlistener.com/opinion/1826977/', '1826977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals and vacate the district court’s determination that appellant, a juvenile, committed a delinquent act.', 'general', 'In Re the Welfare of E.D.J.', 'https://www.courtlistener.com/opinion/1826977/', '1826977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the scientific acceptance of the Intoximeter 3000 is well-established, .', 'general', 'State v. Garrett', 'https://www.courtlistener.com/opinion/1120776/', '1120776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court.', 'general', 'State v. Garrett', 'https://www.courtlistener.com/opinion/1120776/', '1120776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the HGN test does satisfy the Frye standard, because the test is based on a generally accepted theory: Persons who are intoxicated (as well as some other non-intoxicated members of the population) exhibit nystagmus.', 'general', 'State v. Garrett', 'https://www.courtlistener.com/opinion/1120776/', '1120776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Legislature did not intend to include triggering offenses other than those specifically enumerated in the statute defining aggravated sexual assault and that, therefore, defendant could only have been guilty of second-degree sexual assault.', 'general', 'State v. Drury', 'https://www.courtlistener.com/opinion/2065723/', '2065723') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because kidnapping is an offense to which a twenty-year presumptive term,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when the Legislature intends to include carjacking as a relevant offense, it does so explicitly either by amending statutes that were enacted before the creation of the crime of carjacking or by referring specifically to both robbery and carjacking in statutes that were passed after the carjacking statute was enacted.', 'general', 'State v. Drury', 'https://www.courtlistener.com/opinion/2065723/', '2065723') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we reverse the judgment of the Appellate Division to the extent that it concluded that defendant’s sentence for kidnapping was not entitled to a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore reverse the conclusion of the Appellate Division that defendant’s commission of carjacking could support his conviction of first-degree aggravated sexual assault, but we affirm the judgment of the Appellate Division modifying his conviction on that count to a conviction of second-degree sexual assault.', 'general', 'State v. Drury', 'https://www.courtlistener.com/opinion/2065723/', '2065723') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under Iowa Code section 709.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1934564/', '1934564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Carter', 'https://www.courtlistener.com/opinion/1934564/', '1934564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to consider the circumstances of Appellant''s case, we conclude that the complainant''s clothing is not evidence so crucial to the defense that its destruction will necessarily result in a fundamentally unfair trial.', 'general', 'State v. Matafeo', 'https://www.courtlistener.com/opinion/1442818/', '1442818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that the evidence should have been suppressed because it was discovered during an unlawful frisk.', 'suppression', 'State v. Bishop', 'https://www.courtlistener.com/opinion/2640962/', '2640962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the order denying the motion to suppress, vacate Bishop’s conviction, and remand.', 'suppression', 'State v. Bishop', 'https://www.courtlistener.com/opinion/2640962/', '2640962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that retroactive application of the remedy in this case does not run afoul of the state or federal prohibitions against
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse its holding pertaining to the remedy.', 'general', 'State v. Natale', 'https://www.courtlistener.com/opinion/1530328/', '1530328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Appellate Division’s holding that the Code of Criminal Justice’s system of presumptive sentencing in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that pointing and presenting a firearm is not a lesser included offense of assault with intent to kill and therefore the conviction must be vacated.', 'general', 'State v. Burton', 'https://www.courtlistener.com/opinion/1310695/', '1310695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Also, we reverse the Court of Appeals’ ruling that the trial court erred in failing to direct a verdict on Burton’s charges due to a search and seizure violation.', 'search_seizure', 'State v. Burton', 'https://www.courtlistener.com/opinion/1310695/', '1310695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we REVERSE the Court of Appeals’ decision to direct verdicts as to the remaining convictions of assault while resisting arrest, and resisting arrest as a lesser included offense of assault while resisting arrest, as Burton’s arguments were not preserved for review.', 'general', 'State v. Burton', 'https://www.courtlistener.com/opinion/1310695/', '1310695') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court did not clearly abuse its discretion, and we therefore affirm.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/2173496/', '2173496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court did not abuse its discretion by admitting the 911 tape into evidence.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1967082/', '1967082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore we conclude that the evidence was legally sufficient to sustain appellant''s conviction for first-degree premeditated murder.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1967082/', '1967082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1967082/', '1967082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 607 (2000), we held that there
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, based on those facts alone, the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm in part and reverse and dismiss in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 673 (1964), we affirmed a conviction
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State presented sufficient evidence to prove beyond a reasonable doubt that the rape and criminal confinement were committed while Alvies and his co-perpetrators were armed with a deadly weapon.', 'general', 'Alvies v. State', 'https://www.courtlistener.com/opinion/2223102/', '2223102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as our supreme court did in Duncan and Prickett, and just as we did in Howell, we conclude that the trial court abused its discretion by relying upon Alvies'' record of juvenile adjudications as an aggravating cireumstance.', 'general', 'Alvies v. State', 'https://www.courtlistener.com/opinion/2223102/', '2223102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the State presented sufficient evidence to support Alvies'' convictions and that, but for one bad aggravator, the trial court properly sentenced Alvies.', 'sentencing', 'Alvies v. State', 'https://www.courtlistener.com/opinion/2223102/', '2223102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This appellate authority is implemented through Indiana Appellate Rule 7(B), which permits us to revise a sentence if, after due consideration of the trial court''s decision, we find that the sentence is inappropriate in light of the nature of the offense and the character of the offender.', 'sentencing', 'Alvies v. State', 'https://www.courtlistener.com/opinion/2223102/', '2223102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Alvies v. State', 'https://www.courtlistener.com/opinion/2223102/', '2223102') ON CONFLICT DO NOTHING;
