INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'develop a diminished capacity defense, and we conclude that Appellant has failed to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that because the information contained in the additional records cited
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Neither do we find that Appellant has proven that trial counsel acted unreasonably
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'issues, we find that this issue has not been preserved for our review.', 'general', 'Commonwealth v. Mason, L., Aplt', 'https://www.courtlistener.com/opinion/3166634/', '3166634') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we find that, where confronted with neither a basic,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the claim preservation problem, we find that Appellant fails to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'investigation, we found that the jury was aware of the apparent reconciliation through the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the above analysis demonstrating the general rule favoring application of the presumption and, in addition, finding no valid reason to reject the presumption in this context, we hold that it is appropriate to apply a presumption of constitutionality in this case.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 891, this court held that although a "facial" constitutional challenge was a matter of subject matter jurisdiction and *556 could not be waived, an "as applied" challenge was a non-jurisdictional defect that could be waived.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the CCW statute is a reasonable regulation on the time, place, and manner in which the right to bear arms may be exercised.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the CCW statute is a reasonable exercise of the state''s inherent police powers, we find that the CCW statute is not unconstitutional either on its face or as applied to Cole.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the state constitutional right to bear arms is fundamental.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that both claims fail.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that Cole has waived the opportunity to challenge the constitutionality of Wis.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in that case, we found that the unsubstantiated threat of four young men nearby, being loud and profane in a "high crime" area, was not "imminent and specific enough" for the defendant to invoke self-defense.', 'general', 'State v. Cole', 'https://www.courtlistener.com/opinion/1975660/', '1975660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the prejudice from such material "may indeed be greater" than when it is part of the prosecution''s evidence "for it is then not tempered by protective procedures.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Harvey''s right to a speedy trial for the conspiracy charges was not violated.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the conviction because of a speedy trial violation and directed the trial court to dismiss the indictment.', 'dismissal', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that when a defendant testifies in support of a motion to suppress evidence on Fourth Amendment grounds, his testimony may not thereafter be admitted against him at trial on the issue of guilt unless he makes no objection.', 'suppression', 'Harvey v. State', 'https://www.courtlistener.com/opinion/1118222/', '1118222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 972, we held that "the state through its drafting can foreclose as to the defendant, the tactical opportunity to seek a conviction for a lesser offense.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2087780/', '2087780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Appellate Rule 11(B)(3), we affirm Wright''s conviction for Reckless Homicide.', 'general', 'Wright v. State', 'https://www.courtlistener.com/opinion/2087780/', '2087780') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the father’s material misrepresentation entitled the insurer to rescission of the insurance contract, but that, under these compelling factual circumstances, the equitable remedy of rescission properly was molded to require payment of the statutorily required minimum level of PIP benefits to this young victim.', 'general', 'Rutgers Casualty Insurance v. Lacroix', 'https://www.courtlistener.com/opinion/2356063/', '2356063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding that the misrepresentation was not made at the inception of the insurance agreement, we held that the insurer was justified in rescinding the policy.', 'general', 'Rutgers Casualty Insurance v. Lacroix', 'https://www.courtlistener.com/opinion/2356063/', '2356063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the insured’s contractual commitment to avoid material misrepresentations extended to “misrepresentations [that] strike at the heart of the insurer’s ability to acquire the information necessary to determine its obligations and to protect itself from false claims.', 'general', 'Rutgers Casualty Insurance v. Lacroix', 'https://www.courtlistener.com/opinion/2356063/', '2356063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In these compelling circumstances foisted on Chrissy, we conclude that the Appellate Division correctly found error in the trial court’s determination that it lacked discretion to fashion a rescission remedy to provide minimal PIP benefits to this injured young driver, who was unaware that the automobile her father was allowing her to drive was insured as to every resident family member except her.', 'general', 'Rutgers Casualty Insurance v. Lacroix', 'https://www.courtlistener.com/opinion/2356063/', '2356063') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this evidence, we conclude that a rational factfinder could have
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in the light most favorable to the Commonwealth, appellant’s own
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that a rational trier of fact could have found that appellant acted with a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the following reasons, we affirm the trial court.', 'general', 'Kal Robert Molinet v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/3160663/', '3160663') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court did not err in concluding that the impoundment was improper because “there were no circumstances then existing which justified seizure of [Gauster’s] vehicle.', 'general', 'State v. Gauster', 'https://www.courtlistener.com/opinion/1873770/', '1873770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all the foregoing reasons we hold that the State waived its argument that the search of Gauster’s vehicle was justified under the automobile exception to the warrant requirement.', 'general', 'State v. Gauster', 'https://www.courtlistener.com/opinion/1873770/', '1873770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that the district court erred when it denied the defendant’s motion to suppress the evidence obtained during the inventory search.', 'suppression', 'State v. Gauster', 'https://www.courtlistener.com/opinion/1873770/', '1873770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'that the state faded to show the impoundment “was a reasonable means of furthering a reasonable state purpose,” we held that the search violated the defendant’s Fourth Amendment rights, and therefore the evidence obtained during the concomitant inventory search was inadmissible.', 'search_seizure', 'State v. Gauster', 'https://www.courtlistener.com/opinion/1873770/', '1873770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the impoundment of Gauster’s vehicle was unreasonable, making the concomitant inventory search of the vehicle a violation of Gauster’s Fourth Amendment rights, we reverse the court of appeals and reinstate the district court’s suppression order.', 'suppression', 'State v. Gauster', 'https://www.courtlistener.com/opinion/1873770/', '1873770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3, and because he was available to and capable of making his own arrangements for the vehicle, we conclude that as was the case in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'may reject the argument that the Fourth Amendment requires the police to ask an arrested driver if he wants to make alternative arrangements for his vehicle, we conclude that two facts distinguish
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the police still may be under an obligation to permit a driver to make reasonable alternative arrangements when the driver is able to do so and specifically makes a request to do so.', 'general', 'State v. Gauster', 'https://www.courtlistener.com/opinion/1873770/', '1873770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the impoundment of Gauster’s vehicle was not justified, we further conclude that the concomitant inventory search of the vehicle violated Gauster’s Fourth Amendment right against unreasonable searches or seizures.', 'search_seizure', 'State v. Gauster', 'https://www.courtlistener.com/opinion/1873770/', '1873770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State waived the automobile exception claim by failing to raise it at the district court.', 'general', 'State v. Gauster', 'https://www.courtlistener.com/opinion/1873770/', '1873770') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial judge did not err in failing to instruct the jury on self-defense.', 'general', 'State v. Goodson', 'https://www.courtlistener.com/opinion/1304259/', '1304259') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in light of the trial court''s definitive finding that the Commonwealth failed to prove that States was the driver of the car, States'' federal constitutional rights prohibit the Commonwealth from attempting to convince a second jury otherwise.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the Commonwealth may not retry States on the charges upon which the jury could not agree, for to do so would permit relitigation of an issue already determined, by final judgment, in States'' favor.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Never have we held that this new right of the Commonwealth is on equal footing with, let alone higher ground than, a federal constitutional right of the magnitude and significance that the protection against double jeopardy represents.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the circumstances of this case, the prohibition against double jeopardy, specifically, the principle of collateral estoppel, operates to prevent the Commonwealth from proceeding with a retrial on those charges on which the jury could not agree.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that they should not.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we conclude that in this case, the former must yield to the latter.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Commonwealth argues vigorously that if we affirm the Superior Court we have denied it its constitutional right to a jury trial.', 'general', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we affirm the Order of the Superior Court, which reversed the Order of the Court of Common Pleas of Allegheny County.', 'plea', 'Commonwealth v. States', 'https://www.courtlistener.com/opinion/1440754/', '1440754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court properly exercised its discretion by permitting the playback.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/2552429/', '2552429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that that its “explanation at sentencing, read in its totality, clearly indicates that the court considered the arguments in favor of mitigating factors urged by the defendant and rejected the applicability of those factors.', 'sentencing', 'State v. Miller', 'https://www.courtlistener.com/opinion/2552429/', '2552429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we affirm the judgment of the Appellate Division with regard to defendant’s conviction and remand to the trial court for resentencing.', 'sentencing', 'State v. Miller', 'https://www.courtlistener.com/opinion/2552429/', '2552429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that whether a prior conviction is a violent crime under § 13-901.', 'general', 'State v. Joyner', 'https://www.courtlistener.com/opinion/2622240/', '2622240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 34 For the reasons stated, we affirm Joyner’s convictions and his sentence for resisting arrest, but vacate his sentences for possession of a narcotic drug, possession of marijuana, and possession of drug paraphernalia and remand the case to the trial court for resentencing on those convictions.', 'sentencing', 'State v. Joyner', 'https://www.courtlistener.com/opinion/2622240/', '2622240') ON CONFLICT DO NOTHING;
