INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that non-disclosure of some grand jury testimony, most of which was already available to defendant, was not “ ‘material’ in the sense its nondisclosure deprived defendant of a fair trial.', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1576457/', '1576457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the modification of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that applicant did not deliberately bypass an opportunity to press his claim for relief.', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1576457/', '1576457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon consideration of all the evidence, however, we find that a rational trier of fact could find beyond a reasonable doubt that applicant shot and killed Roger Essem.', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1576457/', '1576457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that defense counsel made a specific request which included these reported statements.', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1576457/', '1576457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that much of the delay in presentment can be attributed to allowing Fryer to sleep.', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1576457/', '1576457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that applicant understood his rights and affirmatively relinquished them;', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1576457/', '1576457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the postconviction court’s denial of postconviction relief.', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1576457/', '1576457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'David Fryer pleaded guilty to murder and we affirmed the trial court’s determination that it was first degree murder.', 'plea', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1576457/', '1576457') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified.', 'general', 'Law v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/1301253/', '1301253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the directed verdict for Respondent on their wrongful termination claims because *440 they failed to state a cause of action.', 'general', 'Law v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/1301253/', '1301253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s grant of Respondent''s motions for summary judgment on the malicious prosecution claims and for JNOV on the false imprisonment claims.', 'general', 'Law v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/1301253/', '1301253') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm as modified the directed verdict for Respondent on the wrongful termination claims.', 'general', 'Law v. South Carolina Department of Corrections', 'https://www.courtlistener.com/opinion/1301253/', '1301253') ON CONFLICT DO NOTHING;
