INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the State’s failure to present evidence of the policies guiding the search precluded a determination of the search’s reasonableness, we reversed the conviction.', 'general', 'Goliday v. State', 'https://www.courtlistener.com/opinion/853895/', '853895') ON CONFLICT DO NOTHING;
