INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying a reasonable doubt standard, we held that there was sufficient evidence to convict, without regard to whether escape formed a part of the substantive offense.', 'general', 'People v. Dennis', 'https://www.courtlistener.com/opinion/2085397/', '2085397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the plain language in our accountability statute, we conclude that, for purposes of accountability, the duration of the commission of an offense is defined by the elements of the offense.', 'general', 'People v. Dennis', 'https://www.courtlistener.com/opinion/2085397/', '2085397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm the judgment of the appellate court, which reversed defendant''s conviction and remanded the cause to the circuit court for retrial.', 'general', 'People v. Dennis', 'https://www.courtlistener.com/opinion/2085397/', '2085397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 29 We conclude that Appellant has mischaracterized his arguments as sufficiency of the evidence claims, and in particular, we specifically disagree with his contention that his claims challenge the sufficiency, and not the weight, of the evidence.', 'general', 'Commonwealth v. Fuentes', 'https://www.courtlistener.com/opinion/2274019/', '2274019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Fuentes', 'https://www.courtlistener.com/opinion/2274019/', '2274019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 31 For all of the foregoing reasons, we affirm.', 'general', 'Commonwealth v. Fuentes', 'https://www.courtlistener.com/opinion/2274019/', '2274019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the trial court erred in its instructions to the jury,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse the convictions and remand for a new trial.', 'general', 'State v. Thornton', 'https://www.courtlistener.com/opinion/1080699/', '1080699') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the phrase "relevant to the offender''s deviant behavior pattern" qualifies each of the prohibitions in section 948.', 'general', 'Kasischke v. State', 'https://www.courtlistener.com/opinion/1819622/', '1819622') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the proceedings in open court on February 18 constituted a sentence, not a conditional proposal to sentence, and consequently that the February 20 proceedings must be considered a resentence for a longer term.', 'sentencing', 'Flowers v. State', 'https://www.courtlistener.com/opinion/1658052/', '1658052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On October 11, 1976, we affirmed the judgment and the February 20, 1976 sentence without opinion.', 'sentencing', 'Flowers v. State', 'https://www.courtlistener.com/opinion/1658052/', '1658052') ON CONFLICT DO NOTHING;
