INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'decision and the clear language and purpose of HRS § 641-13, we hold that the Prosecution is not barred from bringing this appeal.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1123578/', '1123578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the circumstances of the case, where defendant moved for and obtained a dismissal immediately after the jury was sworn, preventing a trial to determine his guilt or innocence, no jeopardy attaches.', 'dismissal', 'State v. Wells', 'https://www.courtlistener.com/opinion/1123578/', '1123578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the present case involves an order granting a timely motion to dismiss an indictment, we hold that the “liberal construction standard” is inapplicable.', 'dismissal', 'State v. Wells', 'https://www.courtlistener.com/opinion/1123578/', '1123578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that when a defendant is charged with a criminal violation of the Uniform Securities Act, HRS § 485-21 provides an essential element of the offense charged.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1123578/', '1123578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Counts 1 through 4 did not contain an essential element of the offenses charged, we hold that these counts were insufficient and affirm the circuit court’s order dismissing counts 1 through 4 of the indictment.', 'dismissal', 'State v. Wells', 'https://www.courtlistener.com/opinion/1123578/', '1123578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that the alleged deficiency in the indictment was raised by a timely motion, this court held that “[the] liberal construction rule laid down in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the State’s failure to cite HRS section 707-717 was an inconsequential defect of form which could not have reasonably misled juvenile-appellant to his prejudice.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1123578/', '1123578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that HRS § 485-21 is an essential element of the criminal charges brought pursuant to HRS §§ 485-8, 485-25(a)(2), 485-25(a)(4), and 485-14(a).', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1123578/', '1123578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') Thus, we find that subsection (1) of HRS § 641-13 is not necessarily limited to pretrial situations.', 'general', 'State v. Wells', 'https://www.courtlistener.com/opinion/1123578/', '1123578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles here, we conclude that the language of Wis.', 'general', 'State Ex Rel. Kalal v. Circuit Court for Dane County', 'https://www.courtlistener.com/opinion/2039068/', '2039068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that we should address that question when it is before this court in a case with adversary parties and with full briefing of the consequences of any statutory interpretation.', 'general', 'State Ex Rel. Kalal v. Circuit Court for Dane County', 'https://www.courtlistener.com/opinion/2039068/', '2039068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals.', 'general', 'State Ex Rel. Kalal v. Circuit Court for Dane County', 'https://www.courtlistener.com/opinion/2039068/', '2039068') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Jones''s confession "would clearly meet the requirements of Article 38.', 'general', 'Barfield v. State', 'https://www.courtlistener.com/opinion/1439935/', '1439935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court continued the trial as if it were a bifurcated proceeding, and because admonishments as to the punishment range were not required in a bifurcated trial, we held that failure to admonish was not reversible error.', 'general', 'Barfield v. State', 'https://www.courtlistener.com/opinion/1439935/', '1439935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, pursuant to its own order, a majority of this court holds that because appellant waived his right to a jury trial, his trial should not have been bifurcated.', 'general', 'Barfield v. State', 'https://www.courtlistener.com/opinion/1439935/', '1439935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our grant of the State''s petition was improvident because the record does not present a case in which the evidence was insufficient to prove the jurisdictional allegations of prior convictions for DWI.', 'general', 'Barfield v. State', 'https://www.courtlistener.com/opinion/1439935/', '1439935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Unified Code of Corrections does not preempt section 8 — 4—080 of the Chicago Municipal Code.', 'general', 'City of Chicago v. Roman', 'https://www.courtlistener.com/opinion/1998222/', '1998222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Unified Code of Corrections does not partially preempt Chicago Municipal Code section 8 — 4—080 or require that the ordinance conform to the Code.', 'general', 'City of Chicago v. Roman', 'https://www.courtlistener.com/opinion/1998222/', '1998222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, as this court held in Citizens Utilities, and as the legislature has repeatedly shown, even a high degree of comprehensiveness does not equal an express statement that home rule units are excluded from exercising power.', 'general', 'City of Chicago v. Roman', 'https://www.courtlistener.com/opinion/1998222/', '1998222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this appeal does not present a double jeopardy problem.', 'general', 'City of Chicago v. Roman', 'https://www.courtlistener.com/opinion/1998222/', '1998222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the use of a hotel room is a thing of value and is, thus, within the statutory definition of property in section 15-1, we need not consider whether registration as a guest in a hotel creates a leasehold interest that would be considered a chattel real at common law, as argued by the State, or an interest in real estate.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the occupancy of a hotel room is "property" within the meaning of section 15-1 of the Criminal Code and that the taking of such property by deception can result in the owner''s being permanently deprived of its use or benefit.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1044 (1911), this court held that waterpower created by a waterfall was property under the theft statute at the time.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 403 (1937), this court held that the defendant was properly charged with larceny of electrical energy because larceny under the Criminal Code (Ill.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the use of a hotel room is a thing of value as that phrase is used in the first sentence of section 15-1.', 'sentencing', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this statutory definition, we conclude that in enacting section 15-1 the legislature intended the definition of property to include not only items of tangible personal property, but also other things of value.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the specific statements to which defendant is now objecting are not precisely the same statements that he mentioned in his posttrial motions, we conclude that he has adequately preserved this issue and, as a result, our analysis will be guided by the Strickland factors.', 'ineffective_assistance', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the trial court''s admonition to the jury and defense counsel''s counter argument, we conclude that the lack of objection to these statements was not deficient performance by defense counsel.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, with respect to each of the asserted instances of improper comment by the prosecutor, counsel''s performance was either not deficient or, even if deficient, did not result in prejudice to defendant that would require a new trial.', 'general', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant cannot prevail on this claim because, even if the trial court''s written response to this jury question introduced error, the error is attributable to the trial court, not to ineffective assistance by defense counsel.', 'ineffective_assistance', 'People v. Perry', 'https://www.courtlistener.com/opinion/2093466/', '2093466') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that an automobile may not be "carried" as a deadly weapon under section 812.', 'general', 'State v. Burris', 'https://www.courtlistener.com/opinion/1696000/', '1696000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Using the ordinary meaning of the words in the statute, we conclude that Burris could not have carried the motor vehicle as required by the robbery statute.', 'general', 'State v. Burris', 'https://www.courtlistener.com/opinion/1696000/', '1696000') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the Michigan court and others that apply the jury function theory, we hold that Iowa trial courts shall no longer be required to review the record to determine whether there is sufficient evidence to support a verdict for a lesser-included offense.', 'general', 'State v. Jeffries', 'https://www.courtlistener.com/opinion/2208613/', '2208613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute, as applied to defendant under the discrete facts presented, deprived him of his federal constitutional right to procedural due process.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1264089/', '1264089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that defendant has failed to carry his burden of showing that the detention authorized by N.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1264089/', '1264089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has not satisfied his burden of “establish[ing] that no set of circumstances exists under which the [a]ct would be valid.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1264089/', '1264089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the application of N.', 'general', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1264089/', '1264089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and remand the case to that court for further remand to the Superior Court, Durham County, for the entry of an order of dismissal.', 'dismissal', 'State v. Thompson', 'https://www.courtlistener.com/opinion/1264089/', '1264089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was not.', 'general', 'State v. Friedel', 'https://www.courtlistener.com/opinion/2046334/', '2046334') ON CONFLICT DO NOTHING;
