INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reweighed the evidence, we find that the mitigation is not sufficiently substantial to call for leniency.', 'general', 'State v. Schackart', 'https://www.courtlistener.com/opinion/1195082/', '1195082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the convictions and non-capital sentences on direct appeal.', 'sentencing', 'State v. Schackart', 'https://www.courtlistener.com/opinion/1195082/', '1195082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that judicial diversion is similar in purpose to pretrial diversion and is to be imposed within the discretion of the trial court subject only to the same constraints applicable to prosecutors in applying pretrial diversion under T.', 'general', 'State v. Bonestel', 'https://www.courtlistener.com/opinion/1512446/', '1512446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Art.', 'general', 'Martinez v. State', 'https://www.courtlistener.com/opinion/1223729/', '1223729') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the district court’s order summarily dismissing Martinez’s application for post-conviction relief.', 'dismissal', 'Martinez v. State', 'https://www.courtlistener.com/opinion/1223729/', '1223729') ON CONFLICT DO NOTHING;
