INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a trial court could be well within its discretion in finding a willful and substantial violation where a defendant fails to complete a court-ordered drug treatment program, even though the order did not specify how many chances the defendant had to complete the program or when it had to be completed.', 'general', 'Lawson v. State', 'https://www.courtlistener.com/opinion/1822718/', '1822718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, as just discussed, we conclude that a trial court does not automatically abuse its discretion in revoking a defendant''s probation for being discharged from a drug treatment program, even though the order did not specify time parameters.', 'general', 'Lawson v. State', 'https://www.courtlistener.com/opinion/1822718/', '1822718') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the circumstances of the present case, the appeal is timely filed and may be considered by us.', 'general', 'Commonwealth v. Braykovich', 'https://www.courtlistener.com/opinion/1965402/', '1965402') ON CONFLICT DO NOTHING;
