INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully considering the record in this case, we conclude that the Court of Appeals erred, both in finding the evidence insufficient to support the contempt convictions and also in concluding that the trial judge lacked authority to order payment of attorney’s fees.', 'general', 'Black v. Blount', 'https://www.courtlistener.com/opinion/2369694/', '2369694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that standard to the facts in this case, we conclude that the Court of Appeals erred in holding the evidence insufficient to support Blount’s convictions for contempt.', 'general', 'Black v. Blount', 'https://www.courtlistener.com/opinion/2369694/', '2369694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such behavior is a contempt of court for the very reason expressed by the trial judge — that the court has the right and the duty to protect litigants, witnesses, attorneys and jurors from misbehavior and harassment while they are in or near the courtroom, whether they are arriving, waiting, or departing.', 'general', 'Black v. Blount', 'https://www.courtlistener.com/opinion/2369694/', '2369694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that attorney’s fees are recoverable in this case under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Appeals, reinstate the criminal contempt convictions, and remand to the trial court for calculation of reasonable attorney’s fees.', 'general', 'Black v. Blount', 'https://www.courtlistener.com/opinion/2369694/', '2369694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals, reinstate the criminal contempt convictions, and remand to the trial court for calculation of reasonable attorney’s fees.', 'general', 'Black v. Blount', 'https://www.courtlistener.com/opinion/2369694/', '2369694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we affirm the trial court’s decision to order Blount to pay attorney’s fees, we note that there is little evidence in this record to establish the reasonableness of the fees awarded.', 'general', 'Black v. Blount', 'https://www.courtlistener.com/opinion/2369694/', '2369694') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that victim impact evidence simply has no probative force in the sentencing context.', 'sentencing', 'Alvarado v. State', 'https://www.courtlistener.com/opinion/1676536/', '1676536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, given all the evidence, a rational jury would necessarily entertain a reasonable doubt as to the defendant''s guilt, the due process guarantee requires that we reverse and order a judgment of acquittal.', 'general', 'Alvarado v. State', 'https://www.courtlistener.com/opinion/1676536/', '1676536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no reversible error, we AFFIRM the judgments of the trial court.', 'general', 'Alvarado v. State', 'https://www.courtlistener.com/opinion/1676536/', '1676536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), this Court held that the jury was improperly instructed by a similar aiding and abetting instruction.', 'general', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1846539/', '1846539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that they did.', 'general', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1846539/', '1846539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in Berry, this Court stated, "in this case, however, we find that reading the instructions as a whole did not cure the error resulting from the improper instruction.', 'general', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1846539/', '1846539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we find that jury instructions S-13 and S-14 were erroneous.', 'jury_instruction', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1846539/', '1846539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm.', 'general', 'Wilson v. State', 'https://www.courtlistener.com/opinion/1846539/', '1846539') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we conclude that the appellate court stepped over the line from neutral jurist to that of an advocate for defendant to raise and rule on issues that were neither controlled by clear precedent nor dictated by an interest in a just result.', 'general', 'People v. Givens', 'https://www.courtlistener.com/opinion/2482051/', '2482051') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that defendant has failed to satisfy her burden of meeting the second prong of Strickland by showing that she was prejudiced by her trial counsel’s decision to withdraw the motion to suppress prior to trial.', 'suppression', 'People v. Givens', 'https://www.courtlistener.com/opinion/2482051/', '2482051') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that under the circumstances, the authority-to-consent issue and the possibility that counsel lacked effectiveness in raising it, which the appellate court identified and addressed as an issue, was not an obvious error that could have been resolved without speculating as to what the arguments of the parties would be.', 'general', 'People v. Givens', 'https://www.courtlistener.com/opinion/2482051/', '2482051') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the appellate court’s analysis finding that Mathews lacked authority to consent to the search must be vacated.', 'general', 'People v. Givens', 'https://www.courtlistener.com/opinion/2482051/', '2482051') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that the trial court erred in taking judicial notice of Appellant''s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Odom', 'https://www.courtlistener.com/opinion/2795680/', '2795680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on this issue.', 'general', 'State v. Odom', 'https://www.courtlistener.com/opinion/2795680/', '2795680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the appellate court.', 'general', 'People v. Espinoza', 'https://www.courtlistener.com/opinion/3168304/', '3168304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1304 (1984), this Court held that where a party seeks to introduce the testimony of a witness, who has previously been hypnotized that party is to: (1) advise the court of the existence of the hypnosis;', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, just as this Court held in Patterson that the trial court did not err in refusing to dismiss the juror at issue in that case, I agree with the majority that the trial court below did not err in refusing to dismiss the challenged venirepersons for cause here.', 'dismissal', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we conclude that the evidence was sufficient to support the finding of three aggravating circumstances in relation to killing of Fortney;', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we find that the trial court did not abuse its discretion in consolidating for trial the Informations relating to the homicides at issue.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because Appellant fails to make any contention relating to any specific item of pre-trial publicity other than the aforementioned Ladies'' Home Journal article, even if we assume the existence of such publicity, we find that his argument fails in relation to those items.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, *486 we find that Appellant is similarly not entitled to relief on his allegation of counsel ineffectiveness in relation to the motion to change venue/venire.', 'ineffective_assistance', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, given our deferential view of its decisions in this area of the law and the rationale explained above, we find that the trial court did not abuse its discretion in denying "for cause" challenges to these venire persons.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the third Smoyer guideline was satisfied and that Appellant''s claim of counsel ineffectiveness fails because the substantive claim lacks merit.', 'ineffective_assistance', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court acted entirely within its discretion in refusing to voir dire the jurors, thus avoiding inadvertently notifying the jury of the contents of the article, and giving a sufficient precautionary instruction to secure the integrity of the trial.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Appellant''s argument is without merit.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1886897/', '1886897') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our review of the record, we held that there was sufficient credible evidence to support the trial court’s finding of abuse.', 'general', 'New Jersey Division of Youth & Family Services v. P.W.R.', 'https://www.courtlistener.com/opinion/2423138/', '2423138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'as noted earlier, we concluded that there was sufficient evidence to support a finding of neglect where an employee at a hospital for mentally impaired persons mistakenly administered a dosage of medication to a disabled minor which was estimated to be seventy-eight times the prescribed amount.', 'general', 'New Jersey Division of Youth & Family Services v. P.W.R.', 'https://www.courtlistener.com/opinion/2423138/', '2423138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that a plain-language reading of the provision supported the conclusion that injuries caused accidentally can form the basis for a finding of neglect, and held that, “under Title 9, whether the guardian intended to harm the child is irrelevant.', 'general', 'New Jersey Division of Youth & Family Services v. P.W.R.', 'https://www.courtlistener.com/opinion/2423138/', '2423138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed a trial court’s finding of abuse and neglect, reversing the Appellate Division’s conclusion to the contrary.', 'general', 'New Jersey Division of Youth & Family Services v. P.W.R.', 'https://www.courtlistener.com/opinion/2423138/', '2423138') ON CONFLICT DO NOTHING;
