INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the petitioner, who is incarcerated in a federal correctional institution serving concurrent state and federal sentences, is not barred from challenging his state convictions by a state writ of habeas corpus.', 'sentencing', 'Faulkner v. State', 'https://www.courtlistener.com/opinion/2166096/', '2166096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that “[i]n the case of an illegal sentence claim based on facts not apparent from the face of the judgment, an adequate record for summary review must include pertinent documents to support those factual assertions.', 'sentencing', 'Faulkner v. State', 'https://www.courtlistener.com/opinion/2166096/', '2166096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the petitioner has failed to attach the requisite documentation in support of his claim that his sentences are illegal, however, we affirm the summary dismissal of the petition but do so on different grounds than either the trial court or the Court of Criminal Appeals.', 'dismissal', 'Faulkner v. State', 'https://www.courtlistener.com/opinion/2166096/', '2166096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Steven Michael could properly be convicted of assault in the second degree under AS 11.', 'general', 'Michael v. State', 'https://www.courtlistener.com/opinion/1247664/', '1247664') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute is not vague as applied to this case.', 'general', 'Michael v. State', 'https://www.courtlistener.com/opinion/1247664/', '1247664') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This finding is supported by the evidence, and we conclude that Judge Bryner did not err in convicting Steven Michael on a different theory and on fewer counts than Loreli Michael.', 'general', 'Michael v. State', 'https://www.courtlistener.com/opinion/1247664/', '1247664') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In viewing the evidence under this standard, we conclude that there was sufficient evidence to support Michael’s conviction.', 'general', 'Michael v. State', 'https://www.courtlistener.com/opinion/1247664/', '1247664') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient evidence to support the verdict.', 'general', 'Michael v. State', 'https://www.courtlistener.com/opinion/1247664/', '1247664') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, under the common law, a stepparent was not legally charged with the support of his stepchildren.', 'general', 'Michael v. State', 'https://www.courtlistener.com/opinion/1247664/', '1247664') ON CONFLICT DO NOTHING;
