INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 551, 566 (1977), this court held that when the State charges a defendant with multiple offenses that arise “from a series of incidental or closely related acts and the offenses are not, by definition, lesser included offenses” multiple convictions and sentences can be entered.', 'sentencing', 'People v. Miller', 'https://www.courtlistener.com/opinion/2478860/', '2478860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that retail theft is not a lesser-included offense of burglary and, therefore, both of defendant’s convictions can stand under King.', 'general', 'People v. Miller', 'https://www.courtlistener.com/opinion/2478860/', '2478860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the abstract elements approach applies to determine whether one charged offense is a lesser-included offense of another under King.', 'general', 'People v. Miller', 'https://www.courtlistener.com/opinion/2478860/', '2478860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“[Biased on the allegations in the indictment,” we concluded that home invasion was not a lesser-included offense of aggravated criminal sexual assault because the indictment referred to different conduct for each offense.', 'general', 'People v. Miller', 'https://www.courtlistener.com/opinion/2478860/', '2478860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the charging instrument approach, we concluded that the indictment in that case did not set out the main outline of home invasion and, therefore, home invasion was not a lesser-included offense of intentional murder.', 'general', 'People v. Miller', 'https://www.courtlistener.com/opinion/2478860/', '2478860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it is not.', 'general', 'People v. Miller', 'https://www.courtlistener.com/opinion/2478860/', '2478860') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Miller', 'https://www.courtlistener.com/opinion/2478860/', '2478860') ON CONFLICT DO NOTHING;
