INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1993), this court held that the right to be present is broader under the Minnesota Rules of Criminal Procedure than under the United States Constitution.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our independent review of the record, the violent nature of the crime charged, the number of people involved, and the actions of appellant and codefendants to avoid apprehension immediately following the crime, we conclude that the factor of victim impact favored joinder.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that based on the failure to show the existence of antagonistic defenses, joinder did not create the potential for prejudice to the appellant.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that all four factors found in Minn.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that the defenses presented at trial by Scot Christian, David Christian and appellant were not antagonistic, we conclude that the district court did not err by failing to sua sponte sever appellant’s case midtrial.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reiterate the improper nature of such arguments, but we conclude that those comments do not warrant reversal.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we conclude that appellant’s Sixth Amendment right to effective assistance of counsel was not violated.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s right to an impartial jury and adequate voir dire was not violated by having to select a jury with his codefendants.', 'general', 'State v. Powers', 'https://www.courtlistener.com/opinion/1995692/', '1995692') ON CONFLICT DO NOTHING;
