INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we held as a matter of law Van Hal had probable cause to arrest Johnson, it is unnecessary to address his false arrest and false imprisonment claims, and we hold that summary judgment dismissing those state tort claims was appropriate.', 'dismissal', 'Johnson v. Morris', 'https://www.courtlistener.com/opinion/1808076/', '1808076') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we hold that the trial court correctly granted summary judgment on this claim also.', 'general', 'Johnson v. Morris', 'https://www.courtlistener.com/opinion/1808076/', '1808076') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even should we conclude that Van Hal’s conduct was of such egregious nature as to its reasonableness as to create a jury question, his conduct, under the circumstances, came
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the claimed facts in the light most favorable to Johnson, we conclude that a fact issue exists whether Van Hal committed an assault.', 'general', 'Johnson v. Morris', 'https://www.courtlistener.com/opinion/1808076/', '1808076') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, on this issue we affirm the court of appeals and remand to the trial court for trial of the assault issue under state law only, but otherwise reverse the court of appeals and affirm the trial court grant of summary judgment on all other issues.', 'general', 'Johnson v. Morris', 'https://www.courtlistener.com/opinion/1808076/', '1808076') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Since the only evidence to support that instruction was derived from the test performed at the hospital, we hold that the instruction constituted prejudicial error in the trial of the drunken driving charge.', 'general', 'Essex v. Commonwealth', 'https://www.courtlistener.com/opinion/1319724/', '1319724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that this evidence, though probative, raised no legal presumption of intoxication.', 'general', 'Essex v. Commonwealth', 'https://www.courtlistener.com/opinion/1319724/', '1319724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that fundamental error and prejudice for ineffective assistance of trial counsel present two substantively different questions.', 'ineffective_assistance', 'Benefield v. State', 'https://www.courtlistener.com/opinion/2478887/', '2478887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that trial counsel’s decision not to object to the testimony was part of an objectively reasonable trial strategy and therefore does not constitute ineffective assistance.', 'ineffective_assistance', 'Benefield v. State', 'https://www.courtlistener.com/opinion/2478887/', '2478887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we conclude that the decision on direct appeal
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that Benefield fails to carry her burden to establish prejudice.', 'general', 'Benefield v. State', 'https://www.courtlistener.com/opinion/2478887/', '2478887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Benefield’s trial counsel’s decision not to object appears to have
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the extent that Final Instruction 6 suggests that a person recklessly making a representation may have the intent to defraud, we conclude that it is not a proper statement of the law.', 'general', 'Benefield v. State', 'https://www.courtlistener.com/opinion/2478887/', '2478887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, while Final Instruction 6 misstated the law, the repeated statements of the proper
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'applied to appellate counsel, we conclude that it cannot be mechanically applied to claims of ineffective assistance of trial counsel.', 'ineffective_assistance', 'Benefield v. State', 'https://www.courtlistener.com/opinion/2478887/', '2478887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that when a claim of ineffective assistance of trial counsel is based on a failure to object, and that error was advanced as fundamental error on direct appeal, a finding that the error did not rise to fundamental error does not automatically rule out the possibility that the error resulted in prejudice sufficient to establish ineffective assistance.', 'ineffective_assistance', 'Benefield v. State', 'https://www.courtlistener.com/opinion/2478887/', '2478887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we conclude that the bar establishing fundamental error is higher than that for prejudice of ineffective assistance of trial counsel.', 'ineffective_assistance', 'Benefield v. State', 'https://www.courtlistener.com/opinion/2478887/', '2478887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we hold that the evidence is sufficient to support both convictions and, accordingly, the judgments of the trial court are affirmed.', 'general', 'Sandoval v. Commonwealth', 'https://www.courtlistener.com/opinion/1219276/', '1219276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Trooper Tyler''s warrantless search of Blank''s breath was constitutional if it was a valid exigent circumstances search.', 'general', 'State v. Blank', 'https://www.courtlistener.com/opinion/2634655/', '2634655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence was more than sufficient under Schmerber to support probable cause to search Blank''s breath.', 'probable_cause', 'State v. Blank', 'https://www.courtlistener.com/opinion/2634655/', '2634655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we REVERSE the court of appeals''s decision requiring suppression of the breath test results and REMAND so that the superior court can determine whether exigent circumstances justified the warrantless search.', 'suppression', 'State v. Blank', 'https://www.courtlistener.com/opinion/2634655/', '2634655') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without further ado, we hold that the evidence was such that, when viewed under the Harper-Lee-Fairchild standard, Mease was entitled as of right to have the jury instructed regarding the elements of Section 97-3-27 manslaughter.', 'general', 'Mease v. State', 'https://www.courtlistener.com/opinion/1095104/', '1095104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that context we held that the trial court has a duty to reform the tendered instruction or advise defense counsel of the perceived deficiencies and afford a reasonable opportunity to prepare another instruction.', 'general', 'Mease v. State', 'https://www.courtlistener.com/opinion/1095104/', '1095104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Mease v. State', 'https://www.courtlistener.com/opinion/1095104/', '1095104') ON CONFLICT DO NOTHING;
