INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we hold that it did, and accordingly, we reverse the Superior Court’s order, vacate the trial court’s order quashing that charge, and remand this matter for trial.', 'general', 'Commonwealth v. Karetny', 'https://www.courtlistener.com/opinion/1487913/', '1487913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the evidence presented by the Commonwealth was sufficient to make a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we conclude that the Commonwealth was, and is, empowered to prosecute appellees under both provisions of the Crimes Code.', 'general', 'Commonwealth v. Karetny', 'https://www.courtlistener.com/opinion/1487913/', '1487913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the Commonwealth is not barred from prosecuting appellees for both risking a catastrophe and failure to prevent a catastrophe, nor is it barred from prosecuting appellees for criminal conspiracy to the extent the object of the conspiracy was to commit either of those crimes.', 'general', 'Commonwealth v. Karetny', 'https://www.courtlistener.com/opinion/1487913/', '1487913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the order of the Superior Court, vacate the trial court’s quashal order, and remand this matter for trial.', 'general', 'Commonwealth v. Karetny', 'https://www.courtlistener.com/opinion/1487913/', '1487913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that section 776.', 'general', 'Valdes v. State', 'https://www.courtlistener.com/opinion/1599516/', '1599516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), this Court held that the prohibition against double jeopardy was violated where the defendant was charged and convicted of both committing perjury in an official proceeding and providing false information in an application for bail, based on a single lie.', 'general', 'Valdes v. State', 'https://www.courtlistener.com/opinion/1599516/', '1599516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, because we conclude that our prior double jeopardy jurisprudence announcing the “primary evil” standard has proven difficult to apply and has strayed from the plain language of the governing statute, we now adopt the approach set forth in Justice Cantero’s special concurrence in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, by applying this simple test to this case we conclude that dual convictions under 790.', 'general', 'Valdes v. State', 'https://www.courtlistener.com/opinion/1599516/', '1599516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the “primary evil” test defies legislative intent because it strays from the plain meaning of the statute.', 'general', 'Valdes v. State', 'https://www.courtlistener.com/opinion/1599516/', '1599516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the factors that favor adherence to precedent are not met in this case, and therefore we recede from our precedent in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the only offenses that fall under subsection (4)(b)(2), are those that constitute different degrees of the same offense, as explicitly set forth in the relevant statutory sections.', 'general', 'Valdes v. State', 'https://www.courtlistener.com/opinion/1599516/', '1599516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus we concluded that, by its terms, the rule of lenity controls and prohibits multiple punishments for the two offenses, even if each contains a unique statutory element and are separate offenses under subsection 775.', 'general', 'Valdes v. State', 'https://www.courtlistener.com/opinion/1599516/', '1599516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that the second statutory exception was not met and therefore double jeopardy did not apply.', 'general', 'Valdes v. State', 'https://www.courtlistener.com/opinion/1599516/', '1599516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that police had a reasonable, articulable suspicion that Tim-berlake was engaged in criminal activity-based on the reliable informant’s report that Timberlake was carrying a gun in a motor vehicle.', 'general', 'State v. Timberlake', 'https://www.courtlistener.com/opinion/2036038/', '2036038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that the State did not have to prove as part of its case-in-chief that the defendant did not have a permit.', 'general', 'State v. Timberlake', 'https://www.courtlistener.com/opinion/2036038/', '2036038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the seizure was unlawful because police failed to articulate “a sufficient individualized suspicion of criminal activity.', 'general', 'State v. Timberlake', 'https://www.courtlistener.com/opinion/2036038/', '2036038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a conviction for carrying a pistol in a public place had to be reversed because the county attorney introduced the pistol at trial in contravention of a suppression order.', 'suppression', 'State v. Timberlake', 'https://www.courtlistener.com/opinion/2036038/', '2036038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that police had a sufficient basis to conduct an investigatory stop of the vehicle, we reverse.', 'general', 'State v. Timberlake', 'https://www.courtlistener.com/opinion/2036038/', '2036038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature did not intend to overrule
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals’ decision and reinstate Timberlake’s conviction.', 'general', 'State v. Timberlake', 'https://www.courtlistener.com/opinion/2036038/', '2036038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that once a person has been asked to leave the premises by one with authority to exclude him, and where that person has a reasonable opportunity to gather his personal effects prior to leaving, any expectation of privacy that he maintains in the premises is no longer one that society would view as reasonable.', 'general', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'According appropriate deference to the trial court''s decision, we hold that the court did not abuse its discretion in granting the State''s challenge for cause.', 'general', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McVickers, we held that the rules of evidence apply at a hearing on a motion to suppress evidence.', 'suppression', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Approximately a decade ago, this Court held in McVickers that the rules of evidence apply at a hearing on a motion to suppress.', 'suppression', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[45] Viewing the voir dire in its entirety, we conclude that the trial court here had a rational basis for concluding that Crawford''s personal feelings would substantially impair her ability to be fair to the State and to follow the court''s instructions and her oath.', 'general', 'Granados v. State', 'https://www.courtlistener.com/opinion/1588783/', '1588783') ON CONFLICT DO NOTHING;
