INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the state failed to prove beyond a reasonable doubt that appellant committed the offense of vehicular homicide, we reverse.', 'general', 'Web v. State', 'https://www.courtlistener.com/opinion/1670772/', '1670772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the above set forth facts, though sufficient perhaps for a finding of simple negligence, do not amount to the operation of a motor vehicle in a reckless manner likely to cause the death of, or great bodily harm to, another.', 'general', 'Web v. State', 'https://www.courtlistener.com/opinion/1670772/', '1670772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1st DCA 1984), wherein we affirmed an adjudication of delinquency for vehicular homicide noting that although M.', 'general', 'Web v. State', 'https://www.courtlistener.com/opinion/1670772/', '1670772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, although this claim was procedurally defaulted, petitioner may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.', 'general', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Teague, we held that "new constitutional rules of criminal procedure will not be applicable *620 to those cases which have become final before the new rules are announced," id.', 'general', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '101 (1942) (per curiam) , we held that there was such an exception for a claim that a plea of guilty had been coerced by threats made by a Government *622 agent, when the facts were "dehors the record and their effect on the judgment was not open to consideration and review on appeal.', 'plea', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the error was neither jurisdictional nor constitutional, we held that collateral relief was unavailable.', 'general', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '637, 644 646 (1976), this Court held that where neither the indictment, defense counsel, nor the trial court explained to the defendant that intent to kill was an element of second-degree murder, his plea to that offense was "involuntary.', 'plea', 'Bousley v. United States', 'https://www.courtlistener.com/opinion/118205/', '118205') ON CONFLICT DO NOTHING;
