INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the defendant must have knowledge regarding the truth or falsity of a statement before he can be considered to have adopted the statement by his silence.', 'general', 'State v. Browning', 'https://www.courtlistener.com/opinion/1205008/', '1205008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon all of these circumstances, taken in a light most favorable to the state, we find that a rational trier of fact could have found the defendant guilty of first degree murder beyond a reasonable doubt.', 'general', 'State v. Browning', 'https://www.courtlistener.com/opinion/1205008/', '1205008') ON CONFLICT DO NOTHING;
