INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the statement is an adoptive admission under Rule 801(d)(2)(B), its admission did not violate the defendant’s Sixth Amendment right to confront witnesses against her.', 'general', 'State v. Browning', 'https://www.courtlistener.com/opinion/1205008/', '1205008') ON CONFLICT DO NOTHING;
