INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the defendant waived appellate review of this issue.', 'general', 'State v. Browning', 'https://www.courtlistener.com/opinion/1205008/', '1205008') ON CONFLICT DO NOTHING;
