INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the defendant did receive the right of allocution prior to sentencing.', 'sentencing', 'State v. Browning', 'https://www.courtlistener.com/opinion/1205008/', '1205008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm.', 'general', 'State v. Browning', 'https://www.courtlistener.com/opinion/1205008/', '1205008') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With a decade and a half of federal appellate court experience behind me, I can say that even when we reverse a trial court it is rare that a brief successfully demonstrates that the trial court committed more than one or two reversible errors.', 'general', 'Commonwealth v. Hunter', 'https://www.courtlistener.com/opinion/1976264/', '1976264') ON CONFLICT DO NOTHING;
