INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that under those circumstances the trial court abused its discretion by denying the motion for continuance.', 'general', 'Marshall v. State', 'https://www.courtlistener.com/opinion/2024531/', '2024531') ON CONFLICT DO NOTHING;
