INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm these specific convictions.', 'general', 'Tidwell v. State', 'https://www.courtlistener.com/opinion/2462689/', '2462689') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that as a matter of law the officer had no reasonable grounds to believe the motorist was “operating” his motor vehicle while intoxicated and therefore had no basis to invoke the implied consent provisions of Iowa Code section 321J.', 'general', 'State v. Hopkins', 'https://www.courtlistener.com/opinion/1573384/', '1573384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because such reasonable grounds were lacking, we held that under Iowa Code section 321J.', 'general', 'State v. Hopkins', 'https://www.courtlistener.com/opinion/1573384/', '1573384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We affirm.', 'general', 'State v. Hopkins', 'https://www.courtlistener.com/opinion/1573384/', '1573384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and reinstate the judgment of conviction.', 'general', 'Gates v. State', 'https://www.courtlistener.com/opinion/1658428/', '1658428') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that any period of a suspended sentence must be included when calculating the maximum aggregate sentence under Indiana Code § 35-50-1-2(c)" (emphases added)).', 'sentencing', 'Jenkins v. State', 'https://www.courtlistener.com/opinion/2143188/', '2143188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State produced sufficient evidence to establish that the false-bottomed can found in the side yard of 9625 East 42nd Street was the object in Jenking''s actual possession as he fled.', 'general', 'Jenkins v. State', 'https://www.courtlistener.com/opinion/2143188/', '2143188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, although we conclude that Jenkins is far from the "worst of the worst," the nature of his offenses and his character justify his eight-year sentence when one considers that six of those years were suspended, two to probation.', 'sentencing', 'Jenkins v. State', 'https://www.courtlistener.com/opinion/2143188/', '2143188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Jenkins v. State', 'https://www.courtlistener.com/opinion/2143188/', '2143188') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But based on our analysis, as well as a natural reading of the statute, we hold that "failing to stop," "failing to return," and "failing to remain" are simply alternate methods of committing the same offense.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[5] In Ex parte Ervin, we held that the Double Jeopardy Clause prohibited convictions for both manslaughter and intoxication manslaughter when only one person was killed.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that a jury was not required to unanimously find which of three alleged acts or omissions resulted in the child victim''s death.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that the Double Jeopardy Clause prohibited the State from obtaining two injury to a child convictions for a death that resulted from both an act and an omission.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State with a jury charge that disjunctively charged these three different types of conduct as a single offense, we held that the State had charged "three different criminal acts," and the defendant''s constitutional right to a unanimous verdict required that the jurors "unanimously agree[] upon the commission of any one of these criminal acts.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that two different types of conduct described by the offense of indecency with a child occurring at two different times were separate offenses, so that the disjunctive submission of the two types of conduct in the jury charge violated the right to jury unanimity.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these various statutory methods for committing the offense do not constitute separate offenses, but are merely alternate means of committing the same offense.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[20] We concluded that "separately described conduct constitutes a separate statutory offense" and could be separately prosecuted.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6] We found that the Blockburger[7] "same elements" test was "not the sole test for determining whether offenses are the same under the multiple punishments aspect of the Double Jeopardy Clause.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] We found that "the essential element or focus" of the injury to a child statute was "the result of the defendant''s conduct"injury to child"and not the possible combinations of conduct that cause the result.', 'general', 'Huffman v. State', 'https://www.courtlistener.com/opinion/1794289/', '1794289') ON CONFLICT DO NOTHING;
