INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that Cell-mark’s match criteria are generally accepted in the relevant scientific community and comply with
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because the State has carried its heavy burden, we hold that the error in admitting the probability evidence was harmless.', 'general', 'State v. Bible', 'https://www.courtlistener.com/opinion/1154894/', '1154894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To summarize, we hold that the principles and theory underlying DNA testing and Cellmark’s match criteria are generally accepted in the relevant scientific community.', 'general', 'State v. Bible', 'https://www.courtlistener.com/opinion/1154894/', '1154894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, on the unique facts of this case, we hold that the admission of the inadmissible DNA probability evidence was harmless error.', 'general', 'State v. Bible', 'https://www.courtlistener.com/opinion/1154894/', '1154894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the comment during opening statement was improper but find no reason to reverse.', 'general', 'State v. Bible', 'https://www.courtlistener.com/opinion/1154894/', '1154894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there is no general acceptance in the relevant scientific community for Cellmark’s random match probability calculations.', 'general', 'State v. Bible', 'https://www.courtlistener.com/opinion/1154894/', '1154894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that when new evidence must be received or reweighing and balancing of aggravating and mitigating factors and evidence are required, the best approach is our traditional method.', 'general', 'State v. Bible', 'https://www.courtlistener.com/opinion/1154894/', '1154894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that one of those was improperly found.', 'general', 'State v. Bible', 'https://www.courtlistener.com/opinion/1154894/', '1154894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the killing was especially cruel.', 'general', 'State v. Bible', 'https://www.courtlistener.com/opinion/1154894/', '1154894') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that a discrepancy between oral and written sentence is cognizable in a rule 3.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1681320/', '1681320') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this standard of review and the interests the contemporaneous objection rule serves, we hold that, with two exceptions, a defendant must preserve a claim of insufficiency of the evidence through timely challenge in the trial court.', 'general', 'FB v. State', 'https://www.courtlistener.com/opinion/1776930/', '1776930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the issue was not preserved below, we held that it "was not open to appellate review.', 'general', 'FB v. State', 'https://www.courtlistener.com/opinion/1776930/', '1776930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We held that "a conviction imposed upon a crime totally unsupported by evidence constitutes fundamental error.', 'general', 'FB v. State', 'https://www.courtlistener.com/opinion/1776930/', '1776930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Relying on Troedel''s fundamental error pronouncement, we held that because section 790.', 'general', 'FB v. State', 'https://www.courtlistener.com/opinion/1776930/', '1776930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the interests of justice are better served by applying this general rule to challenges to the sufficiency of the evidence.', 'general', 'FB v. State', 'https://www.courtlistener.com/opinion/1776930/', '1776930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed for entry of a petty larceny conviction.', 'general', 'FB v. State', 'https://www.courtlistener.com/opinion/1776930/', '1776930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1984), we reversed one of the defendant''s two burglary convictions because "[t]here was no evidence of more than one such unlawful entry.', 'general', 'FB v. State', 'https://www.courtlistener.com/opinion/1776930/', '1776930') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1181 (1996), this court held that a voluntary manslaughter charge is not proper where the person who was killed is not the person who provoked the defendant, absent evidence of negligence or accident.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1508311/', '1508311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because the photographs were of limited, if any, probative value and were highly prejudicial, we find that they were erroneously admitted into evidence by the trial court.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1508311/', '1508311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '44 in the commission of the murder, we find that the Bulldog Pug 44 SPL did not establish a material fact in the instant case and thus, was erroneously admitted into evidence at trial.', 'general', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1508311/', '1508311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[18] Accordingly, we affirm the verdict and sentence of death imposed upon appellant, Antyane Robinson, by the Court of Common Pleas of Cumberland County.', 'sentencing', 'Commonwealth v. Robinson', 'https://www.courtlistener.com/opinion/1508311/', '1508311') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the determination of a pattern of criminal conduct under Minn.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1874643/', '1874643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we held that a pattern of criminal conduct “may be demonstrated by reference to past felony or gross misdemeanor convictions or by proof, through clear and convincing evidence, of prior, uncharged acts of criminal conduct, where such acts are similar to the present offense in motive, purpose, results, participants, victims or other characteristics.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1874643/', '1874643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that this precedent revealed a common understanding of “pattern” as “the organizing principle or relationship binding certain things, in this case incidents of criminal conduct, together.', 'general', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1874643/', '1874643') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for resentencing.', 'sentencing', 'State v. Henderson', 'https://www.courtlistener.com/opinion/1874643/', '1874643') ON CONFLICT DO NOTHING;
