INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that none of appellant’s claims of misconduct that was objected to at trial rise to the level to warrant reversal.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1783344/', '1783344') ON CONFLICT DO NOTHING;
