INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that there was sufficient evidence to find appellant guilty of first-degree premeditated murder and first-degree intentional murder committed in the course of a kidnapping, even if there was insufficient evidence to prove appellant’s direct involvement, he would also be guilty under a theory of aiding and abetting if he was intentionally present at the scene of the crime, knew his accomplices were going to commit a crime, and intended his presence to further that crime.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1783344/', '1783344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the prosecutorial misconduct here is harmless even under the standard for more, serious misconduct, we do not pass judgment on whether
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse a district court’s decision to deny a new trial only if the misconduct, when considered in light of the whole trial, impairs the defendant’s right to a- fair trial.', 'general', 'State v. Pendleton', 'https://www.courtlistener.com/opinion/1783344/', '1783344') ON CONFLICT DO NOTHING;
