INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the kidnapping and weapons charges necessarily depend upon the rape conviction and cannot stand independently of it, we reverse all of the convictions and remand the case for a new trial, subject to certain conditions.', 'general', 'Deberry v. State', 'https://www.courtlistener.com/opinion/1954733/', '1954733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, even if the "M-800" was an illegal firework,[3] its lone presence in the passenger compartment would not justify a search of the trunk any more than would a burning cigarette in the passenger compartment of an automobile occupied by a single minor, or an open container in the passenger compartment of a vehicle being operated on a public roadway.', 'general', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, assuming the single firecracker ran afoul of the ordinance, we conclude that its presence in the passenger compartment did not justify a search of the automobile''s trunk under the automobile exception.', 'general', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the record before us, we conclude that the district court correctly concluded that the slight odor of burnt marijuana alone was insufficient to justify Bowes'' warrantless search of the trunk of Schmadeka''s vehicle.', 'general', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the district court''s order denying the motion to suppress must be reversed and the case remanded to the district court for proceedings consistent with Schmadeka''s Rule 11 plea agreement.', 'suppression', 'State v. Schmadeka', 'https://www.courtlistener.com/opinion/2585227/', '2585227') ON CONFLICT DO NOTHING;
