INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given that Jones'' credibility was the crucial issue in this case, and in light of the severity of the crime charged, we find that the trial court committed reversible error in excluding her statement from evidence without conducting a Box hearing pursuant to Rule 9.', 'general', 'Ross v. State', 'https://www.courtlistener.com/opinion/1595336/', '1595336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" While these and other statements are provocative, we find that they fall within the wide discretion granted to parties in closing argument.', 'general', 'Ross v. State', 'https://www.courtlistener.com/opinion/1595336/', '1595336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the aggravating and mitigating circumstances without the contested aggravating circumstances, we find that there were sufficient aggravating circumstances to justify the sentence.', 'sentencing', 'Ross v. State', 'https://www.courtlistener.com/opinion/1595336/', '1595336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding errors in both the guilt and sentencing phases of the trial, we reverse and remand for a new trial.', 'sentencing', 'Ross v. State', 'https://www.courtlistener.com/opinion/1595336/', '1595336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that evidence regarding the underlying facts of each conviction is irrelevant in this case.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1791456/', '1791456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the evidence in the light most favorable to the State, we find that there was sufficient evidence to convict Jones of attempted burglary of a dwelling.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1791456/', '1791456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these facts, we find that any rational juror could have found beyond a reasonable doubt that all of the elements[2] had been met by the State in proving attempted burglary of a dwelling.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1791456/', '1791456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Jones has failed to prove that the State used its peremptory strikes in a discriminatory manner.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1791456/', '1791456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Court of Appeals'' judgment, address Jones'' two remaining issues and reinstate and affirm the circuit court''s judgment of conviction and sentence.', 'sentencing', 'Jones v. State', 'https://www.courtlistener.com/opinion/1791456/', '1791456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the introduction of evidence of prior crimes was appropriate, we reverse the Court of Appeals'' judgment.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1791456/', '1791456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the state submitted sufficient proof of the corpus delicti to admit Schwab''s admissions that he kidnapped and raped the victim.', 'general', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that such probable cause did exist.', 'probable_cause', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the same analysis to this record, we conclude that the failure to provide Chavez with a first appearance within twenty-four hours after his arrest did not compel his confession.', 'general', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, assuming that the failure to bring Chavez before a magistrate to determine probable cause violated the rule articulated in McLaughlin, we conclude that suppression of his last confession is not an appropriate remedy for the violation.', 'suppression', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the Brown factors, we conclude that the trial court did not err in denying suppression of Chavez''s confession.', 'suppression', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, after considering the above factors, we conclude that Chavez''s final confession, even if made while Chavez was held in violation of the Fourth Amendment, was not the product of the unlawful detention.', 'search_seizure', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[31]  Although, upon careful review, we conclude that the length of interrogation here did not coerce Chavez''s confession, we nonetheless emphasize the importance of providing detainees in the criminal justice system both a probable cause determination and a first appearance within the time constraints established by rules 3.', 'probable_cause', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Absent a showing that the delay induced this otherwise voluntary statement, we find that the trial court properly denied Keen''s motion to suppress.', 'suppression', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Chavez is likewise not entitled to relief on this claim.', 'general', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm the judgments and sentences under review.', 'sentencing', 'Chavez v. State', 'https://www.courtlistener.com/opinion/1740628/', '1740628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was legally sufficient to support Laster''s conviction for attempted aggravated kidnapping.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/1450793/', '1450793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[82] We find that the court of appeals applied the correct standard of review and considered all of the relevant evidence before finding that it was factually sufficient.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/1450793/', '1450793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Affording appropriate deference to the jury''s verdict, we therefore hold that the evidence supporting Laster''s conviction is legally sufficient.', 'general', 'Laster v. State', 'https://www.courtlistener.com/opinion/1450793/', '1450793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We hold that Gay''s failure to request such a question was not *154 ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court''s denial of Carriger''s Rule 32 petition was not an abuse of discretion.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In carefully reviewing the trial record, we conclude that Gay''s examination of the witnesses on the stand does not fall below the Watson standard.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that, assuming Gay did not adequately interview prospective witnesses, Carriger was not thereby prejudiced.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of the report was part of defense trial tactics and will not support a claim of ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4] We conclude that Carriger''s testimony would have been detrimental to him.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the aggravating circumstance of pecuniary gain was lawfully found to exist in this case.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Carriger was aware of the necessity of raising competency of counsel issues on appeal.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Carriger was sufficiently informed of the necessity of raising competency of counsel issues on appeal.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there is substantial corroboration of Dunbar''s testimony in Carriger''s testimony, we find that the jury would not have been persuaded to accept Carriger''s uncorroborated testimony concerning what he did at the time of the crime.', 'general', 'State v. Carriger', 'https://www.courtlistener.com/opinion/1173286/', '1173286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when the district court found that Allen was unamenable to probation, and on that basis executed his presumptively stayed sentence, it violated Allen''s Sixth Amendment right to have a jury make that determination using a reasonable-doubt standard.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1875296/', '1875296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the district court''s assigning Allen a custody-status point to calculate his criminal history score did not violate the Sixth Amendment.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1875296/', '1875296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), we held that the imposition of an upward durational departure from the presumptive sentence prescribed by the Minnesota Sentencing Guidelines, based solely on facts found by the judge, violates the Sixth Amendment right to trial by jury under Blakely v.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1875296/', '1875296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Shattuck, we held that for felonies other than first-degree murder, the presumptive sentence prescribed by the Sentencing Guidelines is the maximum a judge may impose based solely on facts reflected in the jury verdict or admitted by the defendant.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1875296/', '1875296') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a credit card is a written instrument within the meaning of A.', 'general', 'State v. Forrester', 'https://www.courtlistener.com/opinion/1159196/', '1159196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the basis of the foregoing, we conclude that the court was not required to submit the case to the jury on multiple forms of verdict.', 'general', 'State v. Forrester', 'https://www.courtlistener.com/opinion/1159196/', '1159196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was a reasonable possibility that the jury could have found that they were bound to ignore Forrester’s contention that he did not receive the notice and that they were bound by the presumption contained in the statute.', 'general', 'State v. Forrester', 'https://www.courtlistener.com/opinion/1159196/', '1159196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the statute unequivocally requires knowledge of cancellation to be presumed from the mailing of the written notice.', 'general', 'State v. Forrester', 'https://www.courtlistener.com/opinion/1159196/', '1159196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that A.', 'general', 'State v. Forrester', 'https://www.courtlistener.com/opinion/1159196/', '1159196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that notice of cancellation has been properly given under such circumstances.', 'general', 'State v. Forrester', 'https://www.courtlistener.com/opinion/1159196/', '1159196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse and set aside Forrester’s conviction on all counts pertaining to acts committed pri- or to March 22 (Counts 2-12) and we affirm Forrester’s convictions on all counts pertaining to checks passed subsequent to March 22 (Counts 13-23).', 'general', 'State v. Forrester', 'https://www.courtlistener.com/opinion/1159196/', '1159196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons hereinafter stated, we affirm the conviction of theft and eleven counts of fraudulent use of a credit card.', 'general', 'State v. Forrester', 'https://www.courtlistener.com/opinion/1159196/', '1159196') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this test to the present case, we conclude that Appellant was not entitled to a hearing on his renewed motion to vacate his plea of nolo contendere.', 'plea', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2604345/', '2604345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2604345/', '2604345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that Netland''s right to due process was not violated and that the criminal test-refusal statute did not result in an unconstitutional search, we reverse.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circumstances of Netland''s chemical test do not rise to the level of a violation of her right to due process.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the criminal test-refusal statute does not violate the prohibition against unreasonable searches and seizures found in the federal and state constitutions because under the exigency exception, no warrant is necessary to secure a blood-alcohol test where there is probable cause to suspect a crime in which chemical impairment is an element of the offense.', 'probable_cause', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Shriner, we held that the "rapid, natural dissipation of alcohol in the blood creates single-factor exigent circumstances that will justify the police taking a warrantless, nonconsensual blood draw from a defendant, provided that the police have probable cause to believe the defendant committed criminal vehicular homicide or operation.', 'probable_cause', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2008), we held that the rapid, natural dissipation of alcohol in the blood creates a single-factor exigent circumstance that allows law enforcement to force the drawing of blood from a defendant when probable cause exists that the defendant has committed criminal vehicular homicide or operation under Minn.', 'probable_cause', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our careful review of the record, we conclude that Netland''s conviction for criminal test refusal is not fundamentally unfair, as our cases have addressed that concept, nor does it offend our "sense of fair play and decency.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because, as set forth below, we conclude that Netland has not shown that a warrantless search for her blood-alcohol content would have been unconstitutional, we need not determine whether the unconstitutional conditions doctrine applies to Fourth Amendment rights or whether it should be applied to violations of the Minnesota Constitution.', 'search_seizure', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But because Netland did not argue that her conviction conflicts with the statute, we conclude that the statutory interpretation question is better left for another case when the record on this question is developed at the district court.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, we concluded that vanishing evidence of blood-alcohol content justified a warrantless entry into the defendant''s home because the officer pursued the defendant on probable cause of driving under the influence, a misdemeanor offense.', 'probable_cause', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that both cases "present[ed] similar compelling exigent circumstances," regardless of the underlying crimes.', 'general', 'State v. Netland', 'https://www.courtlistener.com/opinion/1918367/', '1918367') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed above, we hold that defendant was not denied the effective assistance of counsel, and that the evidence was sufficient to demonstrate that defendant violated his probation.', 'general', 'People v. Colon', 'https://www.courtlistener.com/opinion/2026617/', '2026617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the subsequent acquittal did not preclude the State from introducing evidence at the defendant’s sentencing hearing that the defendant committed the offense of which he was acquitted, as the sentencing hearing involved a lower burden of proof.', 'sentencing', 'People v. Colon', 'https://www.courtlistener.com/opinion/2026617/', '2026617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Colon', 'https://www.courtlistener.com/opinion/2026617/', '2026617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Colon', 'https://www.courtlistener.com/opinion/2026617/', '2026617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an appellate court will reverse for plain error in jury instructions where the error cannot be said to be harmless beyond a reasonable doubt (i.', 'jury_instruction', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that standard to the instant case, we hold that the circuit court''s failure to instruct the jury that "it could consider relevant attributes of both the defendant and the subject of the allegedly threatening utterance in determining whether the subject''s fear of bodily injury, as allegedly induced by the defendant''s threatening utterance, was objectively reasonable under the circumstances in which the threat was uttered," Valdivia, 95 Hawai`i at 479, 24 P.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that, although as a general matter forfeited assignments of error are to be reviewed under the HRPP Rule 52(b) plain error standard of review, in the case of erroneous jury instructions, that standard of review is effectively merged with the HRPP Rule 52(a) harmless error standard of review because it is the duty of the trial court to properly instruct the jury.', 'jury_instruction', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we hold that: (1) the circuit court''s failure to give a "relevant attributes" instruction was plain error;', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A, we hold that: (1) the failure to give a relevant attributes instruction was erroneous, and (2) there is a reasonable possibility that the error contributed to Nichols'' conviction, i.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the circuit court''s failure to provide a "relevant attributes" instruction was not harmless beyond a reasonable doubt.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] Accordingly, we hold that *989 the circuit court on remand is not required to give a nexus instruction.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[11] Accordingly, unless Nichols presents evidence at a future trial that would allow some other rational inference to be drawn, we hold that the trial court is not required to instruct the jury on the lesser included offense of terroristic threatening in the second degree.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that, although as a general matter forfeited assignments of error are to be reviewed under the HRPP 52(b) plain error standard of review, in the case of erroneous jury instructions, that standard of review is effectively merged with the HRPP 52(a) harmless error standard of review because it is the duty of the trial court to properly instruct the jury.', 'jury_instruction', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an attorney has a duty of candor to the courts, yet encourage gamesmanship and subterfuge to achieve the best possible result.', 'general', 'State v. Nichols', 'https://www.courtlistener.com/opinion/2633583/', '2633583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when the sole purpose of introducing evidence of a defendant’s prior convictions is to prove the status element of the offense, and when the defendant offers to stipulate his status as a felon, the probative value of the evidence is, as a matter of law, outweighed by the risk of unfair prejudice.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1377077/', '1377077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that evidence of the specific offenses for which the defendant had previously been convicted is relevant to establish the prior-conviction element of the offense of felony escape.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1377077/', '1377077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning now to the evidence at issue in this case, we conclude that the trial court was correct in utilizing Rule 404(b) to determine the admissibility of the defendant’s other-crimes evidence.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1377077/', '1377077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of the record, we conclude that the evidence of guilt in this case, while sufficient, was less than overwhelming to support the defendant’s convictions for aggravated robbery and especially aggravated kidnapping based upon criminal responsibility.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1377077/', '1377077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, because we find that the error in permitting the State to introduce the names of the defendant’s prior felonies was not harmless, we reverse his convictions for aggravated robbery and especially aggravated kidnapping, and we remand the case for a new trial.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1377077/', '1377077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the decision in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'dence of the specific offenses for which the defendant had previously been convicted was not harmless error, and consequently, we affirm the judgment of the Court of Criminal Appeals and remand the case for a new trial on the charges of aggravated robbery and especially aggravated kidnapping.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1377077/', '1377077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s ruling on this issue.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1377077/', '1377077') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the judgment of the Court
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, when the charged possession for sale is incidental to the charged transportation for sale, it is a lesser-included offense, for a person cannot commit the transportation offense without necessarily committing the possession offense.', 'general', 'State v. Chabolla-Hinojosa', 'https://www.courtlistener.com/opinion/1134825/', '1134825') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In answer to an issue that arose during fundamental error review, we conclude that, when the possession for sale charge is incidental to the transportation for sale charge, the former is a lesser-included offense and the defendant cannot be convicted of both offenses.', 'general', 'State v. Chabolla-Hinojosa', 'https://www.courtlistener.com/opinion/1134825/', '1134825') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We disagree, and we conclude that a conviction of possessing for sale the same marijuana one is convicted of transporting for sale violates the double jeopardy clause of the Fifth Amendment to the United States Constitution and article 2, section 10 of the Arizona Constitution.', 'general', 'State v. Chabolla-Hinojosa', 'https://www.courtlistener.com/opinion/1134825/', '1134825') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm, as modified by vacating the conviction and sentence on the possession for sale charge.', 'sentencing', 'State v. Chabolla-Hinojosa', 'https://www.courtlistener.com/opinion/1134825/', '1134825') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the evidence was sufficient to support Franks’ conviction for engaging in a pattern of harassing conduct.', 'general', 'State v. Franks', 'https://www.courtlistener.com/opinion/1282829/', '1282829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that the pattern of harassing conduct crime is the more serious crime and the crime on which the district court should have imposed sentence.', 'sentencing', 'State v. Franks', 'https://www.courtlistener.com/opinion/1282829/', '1282829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the evidence was sufficient, but that the district court erred in sentencing, we affirm in part, reverse in part, and remand for resentencing consistent with this opinion.', 'sentencing', 'State v. Franks', 'https://www.courtlistener.com/opinion/1282829/', '1282829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the above analysis, we conclude that the phrase feel terrorized in Minn.', 'general', 'State v. Franks', 'https://www.courtlistener.com/opinion/1282829/', '1282829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the word terrorize means “to cause extreme fear by use of violence or threats.', 'general', 'State v. Franks', 'https://www.courtlistener.com/opinion/1282829/', '1282829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence is sufficient to support a finding that Franks knew or had reason to know that his letters would cause J.', 'general', 'State v. Franks', 'https://www.courtlistener.com/opinion/1282829/', '1282829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge was in error in ruling victim-impact evidence permissible in Tillman’s juvenile disposition hearing.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/1754326/', '1754326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set out above, we affirm the trial judge’s decision as modified.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/1754326/', '1754326') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Legg and Pink, we held that although the defendants were in an area legally protected by the Fourth Amendment, the officer''s entrance did not violate the defendants'' Fourth Amendment rights.', 'search_seizure', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In weighing the competing interests of the State and the defendants as applied to the facts in each particular case, we concluded that the officers'' conduct was reasonable in both cases.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse and remand for a new trial.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court''s denial of Lewis''s motion to suppress.', 'suppression', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Lewis', 'https://www.courtlistener.com/opinion/1936528/', '1936528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[11] Although not directly presented in the instant case,[12] we hold that such abuses are analogous to cases in which a prisoner is contesting the legality of his incarceration.', 'general', 'Commonwealth v. Stanley', 'https://www.courtlistener.com/opinion/2082590/', '2082590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the evidence was relevant to resolving this matter, we hold that it was properly admitted as an essential part of the Commonwealth''s case.', 'general', 'Commonwealth v. Stanley', 'https://www.courtlistener.com/opinion/2082590/', '2082590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The majority recognizes that the extent of the duress defense is "not directly presented in the instant case," Majority slip opinion at 1171, yet goes on to say, "we hold that .', 'general', 'Commonwealth v. Stanley', 'https://www.courtlistener.com/opinion/2082590/', '2082590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 598 (1974), we held that the municipal court proceedings serve to apprise a defendant of the nature of the charges, and in that respect, obviate the need to conduct a preliminary hearing on those charges.', 'general', 'Commonwealth v. Stanley', 'https://www.courtlistener.com/opinion/2082590/', '2082590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 941 (1977), this court held that revolvers were not prohibited offensive weapons.', 'general', 'Commonwealth v. Stanley', 'https://www.courtlistener.com/opinion/2082590/', '2082590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm the judgment of the court below.', 'general', 'Commonwealth v. Stanley', 'https://www.courtlistener.com/opinion/2082590/', '2082590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that a rational finder of fact could have found that the essential elements of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'circumstantial evidence is equally as probative as direct evidence, we conclude that the jury
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '716, 719, this court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defining a substantial risk as one "different in kind" from the merely unreasonable risk sufficient for civil negligence best serves the purpose of circumscribing recklessness in such a manner that a fact-finder will not be misled into criminalizing conduct which is only civilly negligent.', 'general', 'In Re William G.', 'https://www.courtlistener.com/opinion/1348425/', '1348425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in the circumstances of this case, or cases closely analogous, the civil rule is what the legislature intended to incorporate by its reference to a standard of conduct.', 'general', 'In Re William G.', 'https://www.courtlistener.com/opinion/1348425/', '1348425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the evidence in this case is wholly inadequate to support a finding of recklessness.', 'general', 'In Re William G.', 'https://www.courtlistener.com/opinion/1348425/', '1348425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse the finding of delinquency.', 'general', 'In Re William G.', 'https://www.courtlistener.com/opinion/1348425/', '1348425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the grandfather had actual authority to consent to a search of the appellant''s bedroom.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the grandfather had actual authority, we need not *557 address whether the apparent-authority doctrine would validate his consent to a search of his grandson''s room.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on the facts as the trial court was entitled to view them, Reed had actual authority to consent to the search of the appellant''s bedroom.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that Reed had actual authority to consent to the search, there is no need for us to determine whether the officer''s conduct was justified by Reed''s apparent authority.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the appellant was estopped from complaining that the State failed to establish reasonable suspicion because he invited the error with meritless objections.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[14] Because we find that the analysis of whether a third party had authority to consent involves an application of legal principles to facts, we now hold that whether a third party had actual authority to consent to a search of another''s *560 property and whether an officer was reasonable in finding that a third party had apparent authority to consent are mixed questions of law and fact which reviewing courts should examine de novo.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the court of appeals.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the court of appeals and, as there are no other points of error requiring remand, we affirm the judgment of the trial court.', 'general', 'Hubert v. State', 'https://www.courtlistener.com/opinion/1464366/', '1464366') ON CONFLICT DO NOTHING;
