INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no merit in appellant’s arguments, we affirm his conviction and sentence.', 'sentencing', 'Ayers v. State', 'https://www.courtlistener.com/opinion/2428738/', '2428738') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the second officer''s testimony was a statement of fact, rather than reputation or character evidence.', 'general', 'Eakes v. State', 'https://www.courtlistener.com/opinion/1757479/', '1757479') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, regardless of the implication created by the in-chambers discussion, by virtue of the jury instructions given, we conclude that the elements of proximate cause and damages had not yet been determined at that point.', 'jury_instruction', 'Maple v. Gustafson', 'https://www.courtlistener.com/opinion/2244414/', '2244414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') Similarly, we conclude that the appellate court erred in effectively entering a judgment n.', 'general', 'Maple v. Gustafson', 'https://www.courtlistener.com/opinion/2244414/', '2244414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we conclude that the trial court did not abuse its discretion in denying plaintiffs’ motion for a new trial, as the jury’s verdict was not against the manifest weight of the evidence.', 'general', 'Maple v. Gustafson', 'https://www.courtlistener.com/opinion/2244414/', '2244414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the appellate court erred in reversing the trial court’s decision, by utilizing an incorrect standard, whereby it effectively granted a motion for a judgment n.', 'general', 'Maple v. Gustafson', 'https://www.courtlistener.com/opinion/2244414/', '2244414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the entry of judgment and sentence for burglary in the first degree and remand for entry of judgment and sentence for burglary in the second degree.', 'sentencing', 'State v. Pace', 'https://www.courtlistener.com/opinion/1934583/', '1934583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'State v. Pace', 'https://www.courtlistener.com/opinion/1934583/', '1934583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment for going armed with intent.', 'general', 'State v. Pace', 'https://www.courtlistener.com/opinion/1934583/', '1934583') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the error was not prejudicial.', 'general', 'State v. Cotton', 'https://www.courtlistener.com/opinion/1319994/', '1319994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the instruction should be sustained.', 'general', 'State v. Cotton', 'https://www.courtlistener.com/opinion/1319994/', '1319994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 61 (1974), where this court held that it was essential to have a psychological examination before pronouncing judgment.', 'general', 'State v. Cotton', 'https://www.courtlistener.com/opinion/1319994/', '1319994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There being no error requiring reversal, we affirm the judgment.', 'general', 'State v. Cotton', 'https://www.courtlistener.com/opinion/1319994/', '1319994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'McNeil, supra, we hold that here certiorari is the proper remedy.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that certiorari was the proper remedy.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though we held that the contempt citation was valid, we also held that the punishment of ninety days was unduly harsh, and we modified the penalty to five days and a fine of $500.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judge''s entered order controls and that the contempt was criminal contempt.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Clark, we reversed a contempt order where the trial judge held a lawyer in contempt for filing a motion for the judge to recuse.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The case was appealed to this court, and we affirmed the contempt finding because it was based on the attorney''s failure to comply with a court order to go to trial.', 'general', 'Johnson v. Johnson', 'https://www.courtlistener.com/opinion/1673730/', '1673730') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'I, and the challenged amendments to the statute are consistent with the above-stated objectives, we conclude that the General Assembly’s intent in enacting Megan’s Law II was not to punish, but to promote public safety through a civil, regulatory scheme.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1518571/', '1518571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that they do not, we reverse the trial court’s orders and remand for further proceedings.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1518571/', '1518571') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'factors, we find that the trial court should not have invalidated Megan’s Law II’s registration,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we held that in order for a defendant to be found guilty of criminal vehicular homicide (leaving the scene), the State is required to prove that the defendant knew he had been involved in an accident with a person or another vehicle.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the evidence was sufficient to support the verdict because "[a]lthough the evidence is circumstantial, it is `consistent with the hypothesis that the accused is guilty''i.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the court of appeals erred when it failed to apply the circumstantial-evidence test to Al-Naseer''s sufficiency-of-the-evidence claim.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that test to Al-Naseer''s leaving-the-scene conviction, we conclude that the evidence presented at trial is insufficient to support the conviction.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of that reasonable doubt, we conclude that there is insufficient evidence to support Al-Naseer''s conviction of criminal vehicular homicide-leaving the scene.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without reaching Al-Naseer''s constitutional challenges, we reverse.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[5]  Because we reverse Al-Naseer''s conviction based on the lack of sufficient evidence, we have no occasion to, and therefore do not, reach the due process issues raised by Al-Naseer.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After granting Al-Naseer''s petition for review, we affirmed the court of appeals'' leaving-the-scene decision but reversed the gross-negligence conviction because the district court failed to instruct the jury on the lesser-included offense of careless driving.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm our holding in Al-Naseer IV and decline to impose a new duty on a driver to stop and investigate if he is not aware that he hit a person or vehicle.', 'general', 'State v. Al-Naseer', 'https://www.courtlistener.com/opinion/1889569/', '1889569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that second-degree sexual abuse met the legal test for a lesser included offense of first-degree kidnaping.', 'general', 'State v. Finnel', 'https://www.courtlistener.com/opinion/2135661/', '2135661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we held that all degrees of sexual abuse, including second-degree sexual abuse, could be lesser included offenses of first-degree kidnaping.', 'general', 'State v. Finnel', 'https://www.courtlistener.com/opinion/2135661/', '2135661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that the defendant’s violent entry into an apartment, his possession of a dangerous weapon, his assault with the weapon upon the apartment’s occupant, and his parting statement to the occupant that he was going to kill his wife made the inference that he entered the apartment with an intent to commit assault
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Finnel', 'https://www.courtlistener.com/opinion/2135661/', '2135661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm his convictions of second-degree burglary and assault while participating in a felony.', 'general', 'State v. Finnel', 'https://www.courtlistener.com/opinion/2135661/', '2135661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the officer''s opinion was properly admitted, and we affirm Daly''s convictions and sentences.', 'sentencing', 'State v. Daly', 'https://www.courtlistener.com/opinion/1846967/', '1846967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the county court did not abuse its discretion in concluding that the DRE protocol was a sufficiently valid methodology to support Hilger''s opinion testimony.', 'general', 'State v. Daly', 'https://www.courtlistener.com/opinion/1846967/', '1846967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that a law enforcement officer with the training and experience offered by DRE certification is sufficiently qualified to testify, based on his or her evaluation, that a suspect was under the influence of drugs.', 'general', 'State v. Daly', 'https://www.courtlistener.com/opinion/1846967/', '1846967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that it was admissible as a demonstrative exhibit.', 'general', 'State v. Daly', 'https://www.courtlistener.com/opinion/1846967/', '1846967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that exhibit 30 was an appropriate illustration of Citek''s testimony and that the county court did not abuse its discretion by admitting it for purposes of the Daubert/Schafersman hearing.', 'general', 'State v. Daly', 'https://www.courtlistener.com/opinion/1846967/', '1846967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As the record before us shows neither the basis for [the defendant''s] objection nor any ruling on the objection, we conclude that [the defendant] has waived any error in this regard.', 'general', 'State v. Daly', 'https://www.courtlistener.com/opinion/1846967/', '1846967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that Daly has waived any error in this regard.', 'general', 'State v. Daly', 'https://www.courtlistener.com/opinion/1846967/', '1846967') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Superior Court Commissioners are without authority to conduct violation of probation hearings.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1472650/', '1472650') ON CONFLICT DO NOTHING;
