INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), this Court held the defendant has the burden of proving community prejudice denied him the right to a fair trial.', 'general', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1882379/', '1882379') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we find that the sentence of death in this case is proportional to other felony murder cases where we have upheld the death sentence.', 'sentencing', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1882379/', '1882379') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we affirm the judgment and sentence of death.', 'sentencing', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1882379/', '1882379') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the record in this case, we affirm Stephens'' convictions and sentences.', 'sentencing', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1882379/', '1882379') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2000), we affirmed a death sentence for a murder committed during the perpetration of aggravated child abuse.', 'sentencing', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1882379/', '1882379') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed above, we affirm Jason Demetrius Stephens'' convictions and sentences, including his sentence of death.', 'sentencing', 'Stephens v. State', 'https://www.courtlistener.com/opinion/1882379/', '1882379') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because the defendant "point[ed] to no specific error which occurred" during the portions of the record that remained untranscribed, we concluded that appellate counsel was not ineffective.', 'ineffective_assistance', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if we considered appellate counsel''s performance to be deficient for failing to specifically argue that the jury instructions for the CCP aggravating circumstance were overbroad, we find that Thompson was not prejudiced by this omission because we found the consideration of the CCP aggravating circumstance to be harmless error on direct appeal.', 'jury_instruction', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that postconviction claim 18, that electrocution is cruel and unusual, is procedurally barred because it was not alleged in the post-conviction motion filed in the trial court.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Thompson''s claim in postconviction issue 17 that he is not competent to be executed is not yet ripe for our consideration.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm the trial court''s order and deny habeas relief.', 'habeas', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Subsequently, we affirmed the trial court''s order denying relief on Thompson''s first postconviction motion, in which Thompson claimed that his codefendant Surace was the dominant actor in the murder and that Surace''s life sentence rendered the death sentence disproportionate.', 'sentencing', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we affirmed the death sentence.', 'sentencing', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed in this opinion, we affirm the trial court''s summary denial of the 3.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the trial court''s summary denial because Thompson did not make specific factual allegations concerning which agencies had failed to comply with the records requests or the types of records that were withheld.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s denial of the motion to disqualify because the motion to disqualify was not legally sufficient.', 'general', 'Thompson v. State', 'https://www.courtlistener.com/opinion/1855142/', '1855142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we hold that the Court of Appeals erred in concluding that Officer Thomas effected a seizure of McCain when he requested identification from McCain and conducted a check for outstanding warrants.', 'general', 'McCain v. Commonwealth', 'https://www.courtlistener.com/opinion/1232803/', '1232803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Therefore, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a trial court''s determination that evidence is clear and convincing will not be overturned unless it may be said as a matter of law that no one could reasonably find such evidence to be clear and convincing.', 'general', 'Nl v. Dept. of Children and Family Ser.', 'https://www.courtlistener.com/opinion/1654809/', '1654809') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '806 and contains no evidence of the provision of services (or the futility of providing services) necessary for termination under subsection (1)(c), we reverse and remand.', 'general', 'Nl v. Dept. of Children and Family Ser.', 'https://www.courtlistener.com/opinion/1654809/', '1654809') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We are unable to find that the statements made in the state''s closing argument *338 created such a prejudicial effect, nor do we find that the issue rises to "the level of plain error.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1154082/', '1154082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm the circuit court''s disposition.', 'general', 'Boyd v. State', 'https://www.courtlistener.com/opinion/1154082/', '1154082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS HEREBY ORDERED that Charles E.', 'general', 'In the Matter of Butler', 'https://www.courtlistener.com/opinion/2309084/', '2309084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that mandatory joinder pursuant to N.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lynch we held that trial court''s erroneous dismissal of an indictment was "a judgment of acquittal.', 'dismissal', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gregory, we held that "the preparation of the precise contours and details of the compulsory joinder rule" should be left to "our Criminal Practice Committee for ultimate consideration and promulgation.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the meantime, however, we held that Section 1.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gregory, this Court held that where a prosecutor was fully aware of the facts necessary to bring an indictment against a defendant for the sale of heroin and possession with intent to distribute, but indicted and convicted defendant only of the sale charge, a subsequent prosecution for possession with intent to distribute would be barred on fundamental fairness grounds.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that the subsequent indictment does not violate the double jeopardy clauses of the federal and state constitutions.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that defendant''s prosecution for theft by deception and arson did not violate constitutional- or statutory-double-jeopardy principles.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Dively, we concluded that Vitale did alter the Blockburger test by establishing an additional prong to be met by the defendant seeking to assert a double-jeopardy claim.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In construing Vitale, we concluded that the defendant needed to: (a) meet the elements or Blockburger test;', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Describing Dively''s requirement that both prongs be satisfied as "erroneous," we concluded that "the more accurate reading of Vitale is that it enhanced the protection afforded a defendant facing a second prosecution on the same facts," and, therefore, that the second prong is an "alternative" to the first.', 'general', 'State v. Yoskowitz', 'https://www.courtlistener.com/opinion/2072452/', '2072452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on the predecessor provision of section 115-16 of the Code of Criminal Procedure of 1963, this court held: "The introduction of such record of conviction for the purpose of affecting the credibility of a witness, or the defendant who has voluntarily testified, is provided for by statute.', 'general', 'People v. Naylor', 'https://www.courtlistener.com/opinion/2231413/', '2231413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Far from being "an issue of first impression in Illinois," we conclude that the rule is evident.', 'general', 'People v. Naylor', 'https://www.courtlistener.com/opinion/2231413/', '2231413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s erroneous admission of defendant''s prior conviction to impeach his testimony constitutes reversible error.', 'general', 'People v. Naylor', 'https://www.courtlistener.com/opinion/2231413/', '2231413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the evidence is closely balanced, we nevertheless find, after carefully reviewing the record, that the evidence was sufficient to prove defendant guilty beyond a reasonable doubt.', 'general', 'People v. Naylor', 'https://www.courtlistener.com/opinion/2231413/', '2231413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that a defendant may raise the question of statutory immunity pretrial and, when such a claim is raised, the trial court must determine whether the defendant has shown by a preponderance of the evidence that the immunity attaches.', 'general', 'Dennis v. State', 'https://www.courtlistener.com/opinion/2536132/', '2536132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that where a criminal defendant files a motion to dismiss on the basis of section 776.', 'dismissal', 'Dennis v. State', 'https://www.courtlistener.com/opinion/2536132/', '2536132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we conclude that the trial court’s error in denying Dennis a pretrial evidentiary hearing on immunity was harmless, we do not quash the Fourth District’s decision affirming Dennis’s conviction and sentence.', 'sentencing', 'Dennis v. State', 'https://www.courtlistener.com/opinion/2536132/', '2536132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In resolving the conflict issue, we conclude that the plain language of section 776.', 'general', 'Dennis v. State', 'https://www.courtlistener.com/opinion/2536132/', '2536132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the procedure set out by the First District in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that where a criminal defendant files a motion to dismiss pursuant to section 776.', 'dismissal', 'Dennis v. State', 'https://www.courtlistener.com/opinion/2536132/', '2536132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Dennis v. State', 'https://www.courtlistener.com/opinion/2536132/', '2536132') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that plaintiffs'' public nuisance claims against both the manufacturer and the dealer defendants must be dismissed.', 'dismissal', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We note, however, that in City of Chicago we held that the manufacturer and distributor defendants owed no duty to the plaintiff city or its residents to prevent the illegal possession and use of their products within the city.', 'general', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that although the village was empowered by statute to declare what would be deemed a nuisance within its borders, it did not have the power to declare a nuisance where no nuisance, in fact, existed.', 'general', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not, however, determine whether the tragic personal losses suffered by plaintiffs constitute the type of special injury necessary to confer standing because we conclude that, as a matter of law, they cannot state a claim in public nuisance against these defendants.', 'general', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is equally unreasonable to expect defendants to foresee that the aggregate effect of the lawful manufacture and sale of firearms will be the creation of a public nuisance in a distant city.', 'general', 'Young v. Bryco Arms', 'https://www.courtlistener.com/opinion/2133726/', '2133726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under Article I, paragraph 10 of the State Constitution a criminal defendant is entitled to the assistance of reasonably competent counsel, and that if counsel’s performance has been so deficient as to create a reasonable probability that these deficiencies materially contributed to defendant’s conviction, the constitutional right will have been violated.', 'general', 'State v. Fritz', 'https://www.courtlistener.com/opinion/1516609/', '1516609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the notations in the challenged exhibit
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a circuit court must not engage in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that when the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we concluded that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, because Deputy Pettit was on Boggs''s property for legitimate purposes, because he did not stray from the places a visitor might go, and because he did not move or manipulate anything in order to make his observation, we conclude that the officer''s observation of the tank inside of the Bronco did not violate the Fourth Amendment, and the trial court did not abuse its discretion in admitting the evidence seized pursuant to the search warrant.', 'search_seizure', 'Boggs v. State', 'https://www.courtlistener.com/opinion/2077922/', '2077922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a reasonable inference could be made that the element of weight was established based on the fact that 252 pills were found at Boggs''s residence and each contained 120 milligrams of pseudoephedrine, which would equal approximately 30.', 'general', 'Boggs v. State', 'https://www.courtlistener.com/opinion/2077922/', '2077922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that sufficient evidence was presented to support the inference that Boggs possessed methamphetamine.', 'general', 'Boggs v. State', 'https://www.courtlistener.com/opinion/2077922/', '2077922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Boggs''s forty-year aggregate sentence was not inappropriate in light of the nature of the offense and the character of the offender.', 'sentencing', 'Boggs v. State', 'https://www.courtlistener.com/opinion/2077922/', '2077922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and remand.', 'general', 'Boggs v. State', 'https://www.courtlistener.com/opinion/2077922/', '2077922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the appropriate remedy is to strike the mandatory crime of violence sentencing provision under section 18-3-203(2)(c) as it applies to attempted second degree assault under subsection (1)(b) and remand the case for resentencing as a class 4 felony.', 'sentencing', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Smith, we held that "when an offender who acts with a less culpable intent may receive a greater penalty than the offender who acts with a greater culpable intent, such a statutory scheme is `unreasonably structured'' and `constitutionally infirm,'' even though the two offenses result in the same harm.', 'general', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the legislature has declined to modify the statute, we conclude that the legislature intended that attempt to commit bodily injury with a deadly weapon be sentenced pursuant to subsection (1)(b) rather than pursuant to the general criminal attempt statute as are all forms of attempted first degree assault under section 18-3-202 and all other forms of second degree assault under section 18-3-203.', 'sentencing', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that either proposal would cure the constitutional defect.', 'general', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that it would be inconsistent with Weller to strike the attempt language from section 18-3-203(1)(b) on equal protection grounds.', 'general', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we reverse the district court''s judgment vacating Duc Nguyen''s two convictions for attempted second degree assault and remand the case for resentencing consistent with this opinion.', 'sentencing', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we affirm the district court''s holding that section 18-3-203 violates the equal protection guarantees of the Colorado and United States Constitutions.', 'general', 'People v. Nguyen', 'https://www.courtlistener.com/opinion/1158430/', '1158430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we hold that a judgment of conviction entered upon a guilty plea becomes final thirty days after acceptance of the plea agreement and imposition of sentence.', 'sentencing', 'State v. Green', 'https://www.courtlistener.com/opinion/1635114/', '1635114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a judgment of conviction upon a guilty plea becomes a final judgment thirty days after entry.', 'plea', 'State v. Green', 'https://www.courtlistener.com/opinion/1635114/', '1635114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court’s jurisdiction to hear and decide the motion to withdraw the guilty plea continued for thirty days after the plea was entered.', 'plea', 'State v. Green', 'https://www.courtlistener.com/opinion/1635114/', '1635114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the judgment of conviction based upon Green’s plea did not become final until thirty days after its entry;', 'plea', 'State v. Green', 'https://www.courtlistener.com/opinion/1635114/', '1635114') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence, we conclude that a rational trier of fact could have found that a robbery was committed and that the essential elements of the crime of first degree murder were proved beyond a reasonable doubt.', 'general', 'State v. Aldaco', 'https://www.courtlistener.com/opinion/1742661/', '1742661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we conclude that the trial court did not abuse its discretion in imposing the sentences.', 'sentencing', 'State v. Aldaco', 'https://www.courtlistener.com/opinion/1742661/', '1742661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we affirm Aldaco’s convictions and sentences.', 'sentencing', 'State v. Aldaco', 'https://www.courtlistener.com/opinion/1742661/', '1742661') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the officer had reasonable
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err in denying Smith’s motion to suppress because
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/880892/', '880892') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the admission of this evidence was fundamental error, and remand for a new trial.', 'general', 'Sasser v. State', 'https://www.courtlistener.com/opinion/2482946/', '2482946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We cannot and will not second-guess the jurors’ decision in this regard, and we find that the evidence was sufficient to support the conviction.', 'general', 'Sasser v. State', 'https://www.courtlistener.com/opinion/2482946/', '2482946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse.', 'general', 'Sasser v. State', 'https://www.courtlistener.com/opinion/2482946/', '2482946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the admission of that evidence was fundamental error, but also finding sufficient evidence supporting the conviction, we reverse and remand for a new trial.', 'general', 'Sasser v. State', 'https://www.courtlistener.com/opinion/2482946/', '2482946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, although we reverse based on the admission of the evidence discussed above, we also remand for a new trial.', 'general', 'Sasser v. State', 'https://www.courtlistener.com/opinion/2482946/', '2482946') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In affirming the district court’s denial of that claim, we held that the proper way for a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Bias’s pleadings and arguments were sufficient to raise a genuine
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm in part, reverse in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/2828359/', '2828359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that considering all of the evidence in a light most favorable to the verdict, the State proved each element of the offense of robbery beyond a reasonable doubt, and further proved that McKee was the person who committed the offense.', 'general', 'McKee v. State', 'https://www.courtlistener.com/opinion/1608240/', '1608240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not commit reversible error in refusing jury instruction D-7.', 'jury_instruction', 'McKee v. State', 'https://www.courtlistener.com/opinion/1608240/', '1608240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the prejudice, if any, from the erroneous admission of Officer Craft''s testimony, dims in light of the overwhelming evidence of McKee''s guilt presented by the State and in light of the fact that McKee''s own counsel repeatedly emphasized his prior theft convictions.', 'general', 'McKee v. State', 'https://www.courtlistener.com/opinion/1608240/', '1608240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] We affirm the convictions for DUI manslaughter but reverse the convictions for culpable negligence manslaughter.', 'general', 'Logan v. State', 'https://www.courtlistener.com/opinion/1829975/', '1829975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a reasonable person in Majaev''s position would not have felt free to leave the scene because doing so would have violated the law and that, therefore, a seizure occurred.', 'general', 'Majaev v. State', 'https://www.courtlistener.com/opinion/2590951/', '2590951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute, on its face, applies to a person in Majaev''s position.', 'general', 'Majaev v. State', 'https://www.courtlistener.com/opinion/2590951/', '2590951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the court of appeals that no seizure occurred and remand for a determination by the district court regarding whether Trooper Bordner had reasonable suspicion to seize Majaev.', 'general', 'Majaev v. State', 'https://www.courtlistener.com/opinion/2590951/', '2590951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we REVERSE and REMAND for a determination by the district court regarding whether Trooper Bordner had reasonable suspicion to seize Anton Majaey.', 'general', 'Majaev v. State', 'https://www.courtlistener.com/opinion/2590951/', '2590951') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the forehead qualifies as an "other bodily member" under Wis.', 'general', 'State v. Quintana', 'https://www.courtlistener.com/opinion/2141839/', '2141839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the violent crime in a school zone penalty enhancer is not unconstitutional as applied to Quintana.', 'general', 'State v. Quintana', 'https://www.courtlistener.com/opinion/2141839/', '2141839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we conclude that the forehead qualifies as an "other bodily member.', 'general', 'State v. Quintana', 'https://www.courtlistener.com/opinion/2141839/', '2141839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because all methods of analysis lead to the conclusion that the legislature intended the phrase "other bodily member" to be construed broadly rather than narrowly, we conclude that the forehead qualifies as an "other bodily member.', 'general', 'State v. Quintana', 'https://www.courtlistener.com/opinion/2141839/', '2141839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Quintana has not met his burden of proof to show that the penalty enhancer is unconstitutional as applied to him.', 'general', 'State v. Quintana', 'https://www.courtlistener.com/opinion/2141839/', '2141839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the school zone penalty enhancer is not unconstitutional as applied to Quintana.', 'general', 'State v. Quintana', 'https://www.courtlistener.com/opinion/2141839/', '2141839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals'' decision.', 'general', 'State v. Quintana', 'https://www.courtlistener.com/opinion/2141839/', '2141839') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Schevers', 'https://www.courtlistener.com/opinion/1191968/', '1191968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of conviction.', 'general', 'State v. Schevers', 'https://www.courtlistener.com/opinion/1191968/', '1191968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'D authorize the district court to make such an unconstitutional upward durational departure upon finding an aggravating factor without the aid of a jury, we hold that the statute is facially unconstitutional and section II.', 'general', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Grossman, we held that the patterned sex offender statute, which allowed the judge to increase by 10 years the maximum prison sentence prescribed by the first-degree criminal sexual conduct statute, based on the judge''s factual findings using a pre-ponderance-of-evidence standard, violated due process.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we conclude that in imposing sentence for a felony, the district court is required to impose the presumptive sentence set out in the Sentencing Guidelines *141 Grid absent additional findings.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the overriding purposes of the Sentencing Guidelines system, we conclude that the unconstitutional portion of Minn.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that severing the unconstitutional portion of Minn.', 'general', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Apprendi principles were not implicated because only the minimum term of imprisonment is affected by the finding of a heinous crime, and therefore the determination of a prior heinous crime conviction may be found by the district court.', 'general', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with the rule announced in that case, we reverse the court of appeals and remand to the district court.', 'general', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the court of appeals and remand this case to the district court for resentencing consistent with this opinion.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the upward departure from the presumptive sentence is unconstitutional.', 'sentencing', 'State v. Shattuck', 'https://www.courtlistener.com/opinion/1697435/', '1697435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the court did not err when it denied Pen-katy’s motion to dismiss the indictment.', 'dismissal', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the proposed testimony was neither unfairly prejudicial nor cumulative, we hold that the district court abused its discretion when it excluded this testimony.', 'general', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore conclude that Beverly’s testimony had a fundamental effect on the fairness and integrity of the trial, and we hold that the court committed plain error when it allowed Beverly to testify at Penkaty’s trial without his consent.', 'general', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we acknowledge that grand juror 19 was not the only grand juror with previous contacts with witnesses or Penkaty, we conclude that there is a significant difference between a grand juror who knew one or more witnesses due to living in the same small community and grand juror 19.', 'general', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that to preserve the integrity of the grand jury proceedings, the state should have acted to have grand juror 19 excused before it presented any evidence to the grand jury.', 'general', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we do not condone the state’s action in making a closing argument that “bordered on being argumentative,” we conclude that the court did not err when it denied Penkaty’s motion to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient admissible evidence to substantiate probable cause, and that the grand jury was repeatedly reminded of its independence.', 'probable_cause', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But Penkaty offered no evidence that he was aware of Knight’s reputation within the law enforcement community for violence and, for this reason, we conclude that this evidence is not probative of whether Pen-katy was reasonably put in apprehension of serious bodily harm, and is inadmissible for that purpose.', 'general', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the police officer’s testimony as to Knight’s reputation in the law enforcement community for violence was admissible for the purpose of showing that Knight was the aggressor.', 'general', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the police officers’ testimony about Knight’s prior acts of violence was admissible to show that Penkaty was reasonably put in apprehension of serious bodily harm.', 'general', 'State v. Penkaty', 'https://www.courtlistener.com/opinion/1313737/', '1313737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not abuse its discretion by denying defendant’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court’s factual finding that Lehman suffered a serious
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the EJJ context, we hold that all three of the Austin factors *769 must be considered when a court is determining whether "reasons exist to revoke the stay.', 'general', 'State v. By', 'https://www.courtlistener.com/opinion/2132646/', '2132646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the final analysis, we conclude that for a court to revoke probation and execute a previously stayed adult sentence for technical violations of EJJ probation, the violations must demonstrate that the offender "cannot be counted on to avoid antisocial activity.', 'sentencing', 'State v. By', 'https://www.courtlistener.com/opinion/2132646/', '2132646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the court of appeals and remand to the district court for further proceedings consistent with our ruling.', 'general', 'State v. By', 'https://www.courtlistener.com/opinion/2132646/', '2132646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the court of appeals and remand to the district court for reconsideration of whether the adult sentence should be executed under Minn.', 'sentencing', 'State v. By', 'https://www.courtlistener.com/opinion/2132646/', '2132646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to the district court for further proceedings consistent with our ruling.', 'general', 'State v. By', 'https://www.courtlistener.com/opinion/2132646/', '2132646') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the indictment in this case sufficiently alleges
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the indictment in this case satisfies these minimum requirements.', 'general', 'Wyatt v. State', 'https://www.courtlistener.com/opinion/1060565/', '1060565') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the lower
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Criminal Appeals.', 'general', 'Wyatt v. State', 'https://www.courtlistener.com/opinion/1060565/', '1060565') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the issues presented in the instant controversy are ripe for review.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although legislative limits upon certain types of damages may be permitted, such as damages recoverable in statutory causes of action, we hold that the cap in section 2-1115.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the compensatory damages cap of section 2-1115.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that section 2-1117(b) cannot be severed from section 2-1117(a) and that the entirety of section 2-1117 is unconstitutional.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For similar reasons, we hold that section 2-1003(a) conflicts with Supreme Court Rule 201(c)(1), which governs the issuance of protective orders.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that section 2-1003(a) is invalid as violating the separation of powers clause of the Illinois Constitution.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Accordingly, we hold that Public Act 89-7 is void in its entirety.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1024, we held that the presumption of severability reflected by an express severability clause will be overcome and the entire statute held unconstitutional if the legislature would not have passed the statute without the provision deemed invalid.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In holding that this provision was severable from the remainder of the ordinance, we held that the ordinance still served the legislature''s intent of ensuring that new developments pay their fair share of road improvements.', 'general', 'Best v. Taylor MacHine Works', 'https://www.courtlistener.com/opinion/2244731/', '2244731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court erred when it failed to suppress the evidence seized during the invalid nighttime search of Jackson''s home.', 'suppression', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 that requires suppression of the evidence seized during the search, we hold that the district court erred when it denied Jackson''s motion to suppress the evidence seized as a result of the illegal nighttime search of Jackson''s home.', 'suppression', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the welfare records in Smith were used simply to identify the defendant''s residence and not to disclose his welfare status, we held that the violation "did not subvert the basic purpose of the statute," and therefore did not require suppression.', 'suppression', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we concluded that a nighttime search should not have been authorized, we held that the evidence obtained in the search was admissible.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that it is, our case law indicates that the evidence seized during the search should be suppressed;', 'suppression', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that in order to determine whether the search of Jackson''s home seriously violated an interest that subverts the statute, we must define the protected interest more precisely than we have in the past, and in doing so more clearly incorporate the motivation behind the historical aversion to such searches.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that our definition of a period of nighttime repose provides a good template to determine the basic purpose behind section 626.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Given both of the aforementioned deficienciesthe time of the search and the lack of information provided to the courtwe conclude that these deficiencies represent fundamental departures from the mandate of section 626.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*173 We conclude that Jackson''s case is distinguishable from Lien because before the police entered Jackson''s home they lacked the type of information that the police who entered Lien''s apartment possessed before entering.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that allowing the state to characterize an insufficiently supported nighttime intrusion into Jackson''s home as a mere technical rather than serious violation based on an after-the-fact assessment that she and her children had not yet entered a period of nighttime repose significantly undermines Jackson''s statutory right to be free from the "abrasiveness of official intrusions" during the night.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1995209/', '1995209') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[40] Accordingly, we hold that for purposes of §§ 28-319.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/3170039/', '3170039') ON CONFLICT DO NOTHING;
