INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury was adequately instructed as to the mental state required for the bribery offense.', 'general', 'State v. Ferguson', 'https://www.courtlistener.com/opinion/1219709/', '1219709') ON CONFLICT DO NOTHING;
