INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the district court did not err by classifying his crime as a felony and sentencing him as a habitual felon based on the same two prior felony convictions, the district court correctly decided Maxwell’s motion for new trial, and his counsel did not provide ineffective assistance, we affirm his conviction and sentence.', 'sentencing', 'State v. Maxwell', 'https://www.courtlistener.com/opinion/1575903/', '1575903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found the district court did not err by imposing two sentencing enhancements based on the same two prior felony convictions, the district court correctly decided Maxwell’s motion for new trial, and his counsel did not provide ineffective assistance when he failed to object to the aiding and abetting instruction, we affirm Maxwell’s conviction and sentence.', 'sentencing', 'State v. Maxwell', 'https://www.courtlistener.com/opinion/1575903/', '1575903') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we hold that Section 2707.', 'general', 'Commonwealth v. McCoy', 'https://www.courtlistener.com/opinion/1940260/', '1940260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 does not apply to such conduct, and we reverse appellant''s conviction for discharge of a firearm into an occupied structure.', 'general', 'Commonwealth v. McCoy', 'https://www.courtlistener.com/opinion/1940260/', '1940260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse appellant''s conviction under 18 Pa.', 'general', 'Commonwealth v. McCoy', 'https://www.courtlistener.com/opinion/1940260/', '1940260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the defendant’s arguments lack merit and that the convictions should be affirmed.', 'general', 'Fink v. State', 'https://www.courtlistener.com/opinion/1888895/', '1888895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the affidavit contained ample information for the magistrate to conclude that it was reasonable that evidence of Fink’s misappropriation of funds and noncompliance with a court order could be found at Fink’s residence.', 'general', 'Fink v. State', 'https://www.courtlistener.com/opinion/1888895/', '1888895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge properly instructed the jury on the principles of law.', 'general', 'Fink v. State', 'https://www.courtlistener.com/opinion/1888895/', '1888895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court in Brunner''s case did not abuse its discretion in concluding that the source code may relate to his guilt or innocence.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1977), we held that a pretrial order will only be reversed if the State "demonstrates clearly and unequivocally that the trial court has erred in its judgment and that, unless reversed, the error will have a critical impact on the outcome of the trial.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the State failed to demonstrate that an error in the order would have a critical impact on the defendant''s prosecution.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the State had not established critical impact.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the Commissioner had failed to meet his burden of demonstrating that the *687 source code was "clearly not discoverable" because the source code was in "possession, custody or control" of the State;', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the Commissioner of Public Safety "failed to meet his burden of demonstrating that the [source code being] sought is clearly not discoverable.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to appellant Brunner, however, we reverse the court of appeals and reinstate the district court''s order for State production of the complete computer source code for the Minnesota model of the Intoxilyzer 5000EN.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we affirm the court of appeals'' decision to reverse the production order in appellant Underdahl''s case.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While not central to our decision, the rule we affirm today fulfills the original purpose behind Minn.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In appellant Underdahl''s case, we affirm the court of appeals and reverse the production order in his case.', 'general', 'State v. Underdahl', 'https://www.courtlistener.com/opinion/1835937/', '1835937') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the outcome of the trial was not fundamentally unfair or unreliable as a result of the alleged deficiencies in trial counsel’s performance, we reject the defendant’s claim of ineffective assistance of counsel.', 'ineffective_assistance', 'Vermillion v. State', 'https://www.courtlistener.com/opinion/853724/', '853724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defendant caused 511 days of delay and acquiesced in 7 days, extending the permissible period under Criminal Rule 4(C) to 883 days.', 'general', 'Vermillion v. State', 'https://www.courtlistener.com/opinion/853724/', '853724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While the defendant contends that some of the delay may be attributed to the State for failure to provide discovery promptly, we find that most of the delays are attributable to the defendant, with regard to both the length and the reasons for the delay.', 'general', 'Vermillion v. State', 'https://www.courtlistener.com/opinion/853724/', '853724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'factors, we find that the defendant is responsible for a substantial portion of the delay, did not assert his speedy trial rights until almost a year and a half after being charged, and has not shown that his rights were impaired as a result of any delay.', 'general', 'Vermillion v. State', 'https://www.courtlistener.com/opinion/853724/', '853724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Vermillion v. State', 'https://www.courtlistener.com/opinion/853724/', '853724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed infra in section III, we hold that the language set forth in HRS § 291E-61(c), see infra note 10, manifests a clear legislative intent to create a status offense in HRS § 291E-61 and, therefore, that it was not a violation of Ruggiero''s due process rights, guaranteed by section 1 of the fourteenth amendment to the United States Constitution[1] and article I, section 5 of the Hawai`i Constitution[2] to sentence him as a second-time offender on the basis of a prior con...', 'sentencing', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Ruggiero failed to preserve the constitutional arguments for appeal and, therefore, we may only reach the merits of his arguments by noticing plain error on the district court''s part.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a fact susceptible to jury determination is a predicate to the imposition of an enhanced sentence, the Hawai`i Constitution requires that such factual determinations be made by the trier of fact.', 'sentencing', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5 ("In Lobendahn we held that, inasmuch as the statute created a `status offense,'' the subsequent invalidation of the predicate felony conviction did not affect the validity of the criminal possession charge because the defendant was `a convicted felon at the time he possessed the firearm and ammunition.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nine days later, on March 19, 2004, we reversed the January 29, 2003 conviction on the grounds that the prosecution failed to prove an essential element of the offense.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court''s judgment with respect to Ruggiero''s convictions of the infractions alleged in Counts II, III, and IV of the complaint, none of which Ruggiero appealed, see infra note 3.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court''s judgment in all other respects.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as Ruggiero does not appeal his conviction of and sentence for driving without no-fault insurance, in violation of HRS § 431:10C-104(a) (Count II), driving a motor vehicle with delinquent tax, in violation of HRS § 249-11 (Count III), and failure to signal, in violation of HRS § 291C-84(b) (Count IV), we affirm the district court''s judgment and sentence regarding those counts.', 'sentencing', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the 2003 amendments to HRS § 291E-61 transformed HRS § 291E-61(b)(1) to (3) into status offenses.', 'general', 'State v. Ruggiero', 'https://www.courtlistener.com/opinion/2571433/', '2571433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that where a trial court finds that a witness is feigning lack of memory of the underlying events described in prior sworn testimony, the witness’s prior testimony is admissible as inconsistent under Minn.', 'general', 'State v. Amos', 'https://www.courtlistener.com/opinion/1298251/', '1298251') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concluding that the admission of prior testimony was proper where the witness feigned a lack of recall of the underlying events described in the prior testimony, the witness was present and testifying at trial, and the witness was subject to cross-examination concerning the prior testimony, we affirm.', 'general', 'State v. Amos', 'https://www.courtlistener.com/opinion/1298251/', '1298251') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the Florida stalking statute is neither unconstitutionally overbroad nor vague.', 'general', 'Bouters v. State', 'https://www.courtlistener.com/opinion/1892827/', '1892827') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand in part and revise in part.', 'general', 'Payton v. State', 'https://www.courtlistener.com/opinion/2124084/', '2124084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*499 For the foregoing reasons, we reverse Payton''s convictions for sexual battery and remand to the trial court with instructions to vacate Payton''s conviction of the lesser-included offenses of sexual battery and enter judgments of conviction and sentence only upon the greater offenses of child molesting and sexual misconduct with a minor.', 'sentencing', 'Payton v. State', 'https://www.courtlistener.com/opinion/2124084/', '2124084') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that in order for a defendant to be habitualized following a guilty or nolo plea, the following must take place prior to acceptance of the plea: 1) The defendant must be given written notice of intent to habitualize, and 2) the court must confirm that the defendant is personally aware of the possibility and reasonable consequences[8] of habitualization.', 'plea', 'State v. Will', 'https://www.courtlistener.com/opinion/1603375/', '1603375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not now decide whether Ashley''s "certain programs" includes basic gain time, since we conclude that defendant may not rely on Ashley in any event.', 'general', 'State v. Will', 'https://www.courtlistener.com/opinion/1603375/', '1603375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this portion of Ashley is not retroactive.', 'general', 'State v. Will', 'https://www.courtlistener.com/opinion/1603375/', '1603375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Will', 'https://www.courtlistener.com/opinion/1603375/', '1603375') ON CONFLICT DO NOTHING;
