INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we hold that this circumstance is an exception to the general rule of deferral in Grant.', 'general', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 384 (2000), this Court held that § 9714(a)(1) violated the procedural due process guarantees of the Fourteenth Amendment of the United States Constitution because it placed the burden upon the defendant to rebut the presumption that he is a high risk dangerous offender.', 'general', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Hughes'' rights under the Pennsylvania Constitution were not violated.', 'general', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the record below, we conclude that the sentence imposed was not a product of passion, prejudice or any other arbitrary factor but, instead, was the product of overwhelming evidence.', 'sentencing', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm the judgment of sentence of death.', 'sentencing', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of sentence of death.', 'sentencing', 'Commonwealth v. Bomar', 'https://www.courtlistener.com/opinion/1989353/', '1989353') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, however, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions.', 'general', 'Hooks v. State', 'https://www.courtlistener.com/opinion/1962073/', '1962073') ON CONFLICT DO NOTHING;
