INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under a proper interpretation of section 124.', 'general', 'State v. Royer', 'https://www.courtlistener.com/opinion/2234602/', '2234602') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the considerable doubt that exists concerning whether such a factual basis can be shown, we conclude that effective counsel would not have allowed defendant to plead guilty under these circumstances.', 'plea', 'State v. Royer', 'https://www.courtlistener.com/opinion/2234602/', '2234602') ON CONFLICT DO NOTHING;
