INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court properly admitted the evidence of Clark’s MySpace page.', 'general', 'Clark v. State', 'https://www.courtlistener.com/opinion/852312/', '852312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'evidence was admissible, and we affirm Clark’s conviction and sentence.', 'sentencing', 'Clark v. State', 'https://www.courtlistener.com/opinion/852312/', '852312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and sentence for murder.', 'sentencing', 'Clark v. State', 'https://www.courtlistener.com/opinion/852312/', '852312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, based on the facts established in the record and any legitimate inferences that can be drawn from them, a jury could reasonably have found Chambers guilty of first-degree murder of a peace officer, and thus the evidence was sufficient to support the guilty verdict.', 'general', 'State v. Chambers', 'https://www.courtlistener.com/opinion/2066740/', '2066740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because the jury could have neither rationally convicted Chambers of second-degree manslaughter or criminal vehicular homicide nor rationally acquitted Chambers of second-degree felony murder, the trial court did not abuse its discretion in refusing to instruct the jury on the lesser-included offenses.', 'general', 'State v. Chambers', 'https://www.courtlistener.com/opinion/2066740/', '2066740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the trial court did not abuse its discretion in any of its rulings and that the conviction and sentence are amply supported by law and fact.', 'sentencing', 'State v. Chambers', 'https://www.courtlistener.com/opinion/2066740/', '2066740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, Chambers has failed to meet his heavy burden of proving that his sentence is “well nigh universally rejected,” and we conclude that, as applied to Chambers, the sentence of life imprisonment without possibility of release does not constitute cruel or unusual punishment.', 'sentencing', 'State v. Chambers', 'https://www.courtlistener.com/opinion/2066740/', '2066740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not abuse its discretion in precluding the evidence of police pursuit policies as irrelevant.', 'general', 'State v. Chambers', 'https://www.courtlistener.com/opinion/2066740/', '2066740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and sentence.', 'sentencing', 'State v. Chambers', 'https://www.courtlistener.com/opinion/2066740/', '2066740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no merit to Chambers’ multiple assignments of error, we affirm the conviction and sentence of the trial court.', 'sentencing', 'State v. Chambers', 'https://www.courtlistener.com/opinion/2066740/', '2066740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial court did not abuse its discretion in finding that the jury could not rationally have convicted Chambers of a crime requiring a finding of negligence.', 'general', 'State v. Chambers', 'https://www.courtlistener.com/opinion/2066740/', '2066740') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that charges of robbery in the first degree brought under 11
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the undisputed testimony of Office Curran and of Officer Osowski, who test fired the pistol, meets the test that there is a reasonable probability no tampering had occurred and that the pistol was a deadly weapon at the time it was taken into police custody.', 'general', 'Bey v. State', 'https://www.courtlistener.com/opinion/1497364/', '1497364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no merit in defendant’s substantive grounds for reversal we affirm the conviction on the charge of robbery in the first degree.', 'general', 'Bey v. State', 'https://www.courtlistener.com/opinion/1497364/', '1497364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 469, 487 (1995), we held that "[a]s a general proposition, we will not disturb a sentence following a criminal conviction if it falls within the range of what is permitted under the statute.', 'sentencing', 'State v. GEORGIUS', 'https://www.courtlistener.com/opinion/1223352/', '1223352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 369, 373-74 (2003), this Court held that the circuit court did not abuse its discretion in denying a Rule 35(b) motion to reconsider where no new arguments or reasons for granting the motion were presented.', 'general', 'State v. GEORGIUS', 'https://www.courtlistener.com/opinion/1223352/', '1223352') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the trial court did not abuse its discretion in admitting the challenged statements.', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 441, we hold that the probative value of the testimony would outweigh the danger of unfair prejudice to the defendant and would survive a challenge under HRE 403.', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that when separate and distinct culpable acts are subsumed within a single count charging a sexual assaultany one of which could support a conviction thereunderand the defendant is ultimately convicted by a jury of the charged offense, the defendant''s constitutional right to a *875 unanimous verdict is violated unless one or both of the following occurs: (1) at or before the close of its case-in-chief, the prosecution is required to elect the specific act upon which it ...', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And inasmuch as we cannot say that there was no reasonable possibility that the circuit court''s error contributed to Arceo''s convictions, we hold that the error was not harmless beyond a reasonable doubt.', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[30] We therefore hold that, if the prosecution does so, then testimony regarding any or all of the multiple acts is "direct evidence of the charged offense" and does not implicate "`other'' crimes, wrongs, or acts with which HRE 404(b) is concerned.', 'general', 'State v. Arceo', 'https://www.courtlistener.com/opinion/1191793/', '1191793') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" In accordance with Bardonner, we hold that the State''s voir dire remarks constituted improper commentary on the disparate roles of defense and prosecution.', 'general', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the prosecutor''s comments disturbed the presumption of innocence, disparaged the right to confrontation, and impinged on the right to effective counsel.', 'general', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the State failed to prove that Casey threatened Kimberly to place her in fear of retaliation for a prior lawful act.', 'general', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that because "Seuro was charged with only one count of dissemination to D.', 'general', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that under Wilson, Debose, and Coy, the prosecutor''s allusion to Marlow''s potential sentence was inappropriate.', 'sentencing', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State improperly distinguished the roles of prose-ecution and defense, referred to the penal consequences of the offense charged, commented on Marlow''s failure to call corroborating witnesses, and personally vouched for Officer Roberts''s credibility.', 'general', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we found that the record did not support an inference that Casey was threatening Kimberly for this particular conduct.', 'general', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we reverse.', 'general', 'Lainhart v. State', 'https://www.courtlistener.com/opinion/2137193/', '2137193') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'Carnes v. State', 'https://www.courtlistener.com/opinion/2146772/', '2146772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that where probable cause exists to initiate criminal charges against a defendant, a due process violation does not occur when an officer threatens to file those charges.', 'probable_cause', 'Carnes v. State', 'https://www.courtlistener.com/opinion/2146772/', '2146772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm Leah''s conviction under Ind.', 'general', 'Carnes v. State', 'https://www.courtlistener.com/opinion/2146772/', '2146772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Michael''s conviction under § 835-48-4-7 for possession of methaqualone and affirm his conviction under § 35-48-4-11 for possession of marijuana.', 'general', 'Carnes v. State', 'https://www.courtlistener.com/opinion/2146772/', '2146772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '806(1)(d) went into effect, we held that "incarceration does not, as a matter of law, constitute abandonment," but that it is "a factor to be considered in determining whether abandonment has occurred.', 'general', 'In Re MF', 'https://www.courtlistener.com/opinion/1955025/', '1955025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the flexible approach taken by the Fifth District, rather than the per se rule adopted by the Second and Third Districts, is more consistent with the plain language of the Act.', 'general', 'In Re MF', 'https://www.courtlistener.com/opinion/1955025/', '1955025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a public officer is entitled to qualified immunity from civil damages for performance of discretionary functions where: (1) a trial court finds the alleged facts, taken in the light most favorable to the party asserting injury, do not demonstrate that the officer''s conduct violated a constitutional right;', 'general', 'City of Saint Albans v. Botkins', 'https://www.courtlistener.com/opinion/2505591/', '2505591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to appellants'' analogy to recognized evidentiary privileges, contrary to appellants'' claim, we conclude that the Shield Law is not comparable to the attorney-client privilege, or, for that matter, to any other privilege with respect to the issue presented here.', 'general', 'Castellani v. Scranton Times, L.P.', 'https://www.courtlistener.com/opinion/2313266/', '2313266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the identity of the source was already known and the statements at issue were not confidential, we concluded that the Shield Law did not prevent disclosure of the murder-defendant''s statements to the reporter.', 'general', 'Castellani v. Scranton Times, L.P.', 'https://www.courtlistener.com/opinion/2313266/', '2313266') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this standard, we hold that substantial evidence exists to support both the kidnapping and murder convictions.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that defendant was not denied a fair trial because of pretrial publicity, we do not address the various alleged incidents of improper contact with the media.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 411 (1991), we hold that defendant has failed to establish the degree of underrepresentation "by comparing the proportion of the group in the total population to the proportion called to serve as .', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Concerning his claim that "persons not employed by large corporations" were systematically excluded from the jury pool, we hold that, as with his sixth amendment claim, defendant has failed to demonstrate that those persons constitute a distinct group for purposes of equal protection analysis.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the "We The People" members were not sufficiently noticeable, persuasive, or influential  passively or otherwise  to deprive defendant of a fair trial.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the error was harmless.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial judge''s failure to make an Enmund finding is not error.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence presented, although circumstantial, plainly negated the possibility that the victim died as the result of an accident.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing this evidence in the light most favorable to upholding the jury''s finding, we conclude that the jury was presented with substantial evidence from which it could conclude beyond a reasonable doubt that defendant murdered the victim.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We address the merits of defendant''s claim in this direct appeal because, viewing the record in its entirety, we conclude that defendant''s claim is meritless.', 'general', 'State v. Atwood', 'https://www.courtlistener.com/opinion/1182224/', '1182224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the appellant waived his ineffective assistance of counsel claim on direct appeal by failing to include it in his Rule 1925(b) statement and, therefore, we held that the general rule announced in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 14 In the instant case, we conclude that the Commonwealth presented sufficient evidence to sustain Appellant’s convictions on two counts of REAP.', 'general', 'Commonwealth v. Reynolds', 'https://www.courtlistener.com/opinion/2341796/', '2341796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 18 We conclude that the totality of the circumstances present sufficient evidence to sustain Appellant’s conviction on the one count of terroristic threats as to Baker.', 'general', 'Commonwealth v. Reynolds', 'https://www.courtlistener.com/opinion/2341796/', '2341796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pursuant to our review of the entire sentencing transcript, we conclude that Judge Cunningham offered sufficient reasons on the record to support the sentence he imposed.', 'sentencing', 'Commonwealth v. Reynolds', 'https://www.courtlistener.com/opinion/2341796/', '2341796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the robbers placed the victims in a situation in which the risk of death or serious bodily injury was real, not merely apparent and, therefore, the Commonwealth did not need to prove that a bullet was in the chamber of the gun used by the defendant.', 'general', 'Commonwealth v. Reynolds', 'https://www.courtlistener.com/opinion/2341796/', '2341796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Reynolds', 'https://www.courtlistener.com/opinion/2341796/', '2341796') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 31 For the foregoing reasons, we affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Reynolds', 'https://www.courtlistener.com/opinion/2341796/', '2341796') ON CONFLICT DO NOTHING;
