INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the District Court.', 'general', 'Fink v. Time Warner Cable', 'https://www.courtlistener.com/opinion/866709/', '866709') ON CONFLICT DO NOTHING;
