INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the forty-three heat-sealed clear plastic packets were not “closed” containers, within the meaning of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, under the circumstances of this appeal, we hold that obtaining a warrant from a “neutral magistrate” was not a necessary precondition to subjecting the suspected cocaine to chemical testing.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1441674/', '1441674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the circuit court’s COL No.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1441674/', '1441674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court clearly abused its discretion in admitting Chinn’s testimony regarding the net weight of the cocaine.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1441674/', '1441674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'evidence, we hold that the prosecution failed to adduce sufficient evidence to prove every element of the offense beyond a reasonable doubt and that Wallace’s conviction must be vacated.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1441674/', '1441674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that, upon remand of Count One to the circuit court, a judgment should be entered convicting Wallace of promoting a dangerous drug in the third degree as defined by HRS § 712-1243(1).', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1441674/', '1441674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we hold that the issue of the accuracy of the certified gram scale has been waived.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1441674/', '1441674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the evidence adduced in the strongest light for the prosecution, and according to the trier of fact the prerogative of resolving all questions of fact, including reasonable and rational inferences under the facts in evidence, we hold that Wallace’s conviction of promoting a detrimental drug in the second degree, as charged in Count Three, was supported by substantial evidence.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1441674/', '1441674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 930 (1980), this court held that a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the district court did not err in denying Slaughter’s motion for acquittal.', 'general', 'State v. Slaughter', 'https://www.courtlistener.com/opinion/2047960/', '2047960') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court could reasonably weigh the testimony of Love and Jackson in such a way as to provide a rational basis to acquit of robbery.', 'general', 'State v. Slaughter', 'https://www.courtlistener.com/opinion/2047960/', '2047960') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Slaughter', 'https://www.courtlistener.com/opinion/2047960/', '2047960') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the admission of the other crimes evidence in this case constituted an abuse of discretion without regard to the balancing test required under D.', 'general', 'Getz v. State', 'https://www.courtlistener.com/opinion/1926452/', '1926452') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[46] We hold that the *542 trial judge did not err in his instructions concerning a unanimous jury verdict.', 'general', 'Landrian v. State', 'https://www.courtlistener.com/opinion/1488121/', '1488121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not err.', 'general', 'Landrian v. State', 'https://www.courtlistener.com/opinion/1488121/', '1488121') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court’s consideration of the EMT’s allegations submitted through the PSI and her testimony was proper.', 'general', 'State v. Burdett', 'https://www.courtlistener.com/opinion/2551895/', '2551895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having thoroughly reviewed the record on appeal, we hold that the district court did not abuse its discretion in reaching the sentence imposed in this case.', 'sentencing', 'State v. Burdett', 'https://www.courtlistener.com/opinion/2551895/', '2551895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court did not abuse its discretion when it denied Burdett’s Rule 35 motion for reduction of sentence.', 'sentencing', 'State v. Burdett', 'https://www.courtlistener.com/opinion/2551895/', '2551895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court properly considered the EMT’s testimony in fashioning a sentence because the EMT testified at the sentencing hearing and was subjected to cross-examination.', 'sentencing', 'State v. Burdett', 'https://www.courtlistener.com/opinion/2551895/', '2551895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the district court did not abuse its discretion when it denied Burdett’s Rule 35 motion.', 'general', 'State v. Burdett', 'https://www.courtlistener.com/opinion/2551895/', '2551895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we conclude that, considering the nature of the offense — second degree murder of an infant— Burdett’s character and the protection of the public interest, the fixed life sentence originally imposed by the district court was not an abuse of discretion.', 'sentencing', 'State v. Burdett', 'https://www.courtlistener.com/opinion/2551895/', '2551895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Burdett', 'https://www.courtlistener.com/opinion/2551895/', '2551895') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because that crime fell within the statutory definition of forcible felony and because a person commits murder in the first degree when he or she kills another person while participating in a forcible felony, this court held in Beeman that willful injury could serve as a basis for a felony-murder conviction under Iowa Code section 707.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although in Hinkle this court held that the merger argument had not been preserved for consideration, it discussed the doctrine, as considered by other courts, and stated:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we conclude that, while the second of the two assaults on [the victim] merged with the murder, the first did not.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Lyon''s estate did not waive the psychotherapist-patient privilege for purposes of the present case.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this setting we conclude that the right of confrontation is paramount to the State''s policy of protecting a juvenile offender.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a limited disclosure of the medical records should be ordered in this case.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the inclusion, by the legislature, of "felonious assault" in sections 707.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In rejecting the equal-protection challenge lodged in Ragland, we found that there was a rational basis for concluding that the crime of willful injury posed a greater risk to the victim than other crimes for which felony murder may not be invoked.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Heemstra', 'https://www.courtlistener.com/opinion/1652030/', '1652030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the indictment as charged impaired the defendant''s ability to prepare a defense that was available to him prior to the statute''s amendment and held that this substantive change amounted to a violation of the ex post facto clause as applied to the defendant.', 'general', 'Garrison v. State', 'https://www.courtlistener.com/opinion/1908339/', '1908339') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that if a trial court imposes a term of probation on one offense consecutive to a sentence of incarceration on another offense, credit for time served on the first offense must be awarded on the sentence imposed after revocation of probation on the second offense.', 'sentencing', 'Tripp v. State', 'https://www.courtlistener.com/opinion/1151775/', '1151775') ON CONFLICT DO NOTHING;
