INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor can we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the evidence was sufficient and affirm the judgment of the trial court.', 'general', 'Tooley v. State', 'https://www.courtlistener.com/opinion/1994301/', '1994301') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the statute is not unconstitutionally vague on its face or as applied to Tooley and that the evidence was sufficient, we affirm.', 'general', 'Tooley v. State', 'https://www.courtlistener.com/opinion/1994301/', '1994301') ON CONFLICT DO NOTHING;
