INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that under the facts of the present case, the original probation sentence is not to be considered in determining the legality of Appellant’s subsequent sentence.', 'sentencing', 'Commonwealth v. Crump', 'https://www.courtlistener.com/opinion/2077150/', '2077150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Crump', 'https://www.courtlistener.com/opinion/2077150/', '2077150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Verenzo Cartrell Green v. State of Mississippi', 'https://www.courtlistener.com/opinion/3173188/', '3173188') ON CONFLICT DO NOTHING;
