INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'of defendant’s arguments, we affirm his conviction.', 'general', 'State v. Hutchison', 'https://www.courtlistener.com/opinion/1719211/', '1719211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that where an issue of sufficiency of evidence is presented to a trial court, sitting without a jury, in a motion to strike at the conclusion of the Commonwealth''s evidence and, upon its denial and upon conclusion of the defendant''s evidence, the same issue is presented in the defendant''s final argument to the court, the defendant has preserved his right to appeal this issue, even though he did not make a motion to strike at the conclusion of his own evidence.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we hold that the trial court had an opportunity to, and did, consider and resolve the issue now raised on appeal.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 293 (1988), a divided panel of this court held that an appeal of the sufficiency of the evidence in a criminal case tried without a jury was barred by the failure of the defendant to move to strike the evidence even though the closing argument raised the question of the sufficiency of the evidence.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Williams, a divided panel of this Court held that an appeal which challenged the sufficiency of the evidence in a bench trial was procedurally barred because defense counsel had not made a motion to strike the evidence or a motion to set aside the verdict.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge could have inferred from all the evidence that this beating was delivered with the intent to disfigure or disable the child.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, therefore, we affirm the defendant''s conviction of malicious wounding.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1233468/', '1233468') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that for offenses which neither expressly require nor plainly dispense with the requirement for a culpable mental state, an indictment which fails to allege such mental state will be sufficient to support prosecution and conviction for that offense so long as
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that the indictment in this case charging the defendant with the offense of aggravated rape, in violation of Tenn.', 'general', 'State v. Hill', 'https://www.courtlistener.com/opinion/2442291/', '2442291') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the psychiatrist’s testimony should not contain any incriminating statements made by the defendant.', 'general', 'State v. McWilliams', 'https://www.courtlistener.com/opinion/1340638/', '1340638') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though we conclude that their testimony was insufficient to prove sanity, we do not mean to say that lay testimony can never rebut expert testimony.', 'general', 'State v. McWilliams', 'https://www.courtlistener.com/opinion/1340638/', '1340638') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the State had not presented
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we reverse the jury verdict of the Circuit Court of Monon-galia County and order that a judgment of acquittal be entered.', 'general', 'State v. McWilliams', 'https://www.courtlistener.com/opinion/1340638/', '1340638') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a guilty plea is valid only if the record affirmatively shows that a defendant understands that by pleading guilty he waives his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a guilty plea is valid only if the record affirmatively shows that a defendant understands that by pleading guilty he waives his right to confront witnesses against him, his right to a jury trial, and his privilege against self-incrimination, or otherwise affirmatively shows an express waiver of said rights.', 'plea', 'State v. Hays', 'https://www.courtlistener.com/opinion/1693219/', '1693219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse, and remand with directions, concluding that an affirmative, express waiver of the above rights is required and that the record does not affirmatively disclose such a waiver in this case.', 'general', 'State v. Hays', 'https://www.courtlistener.com/opinion/1693219/', '1693219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Hays did not expressly waive his rights to counsel, confrontation, and jury trial, and because the record does not affirmatively show that Hays understood that he was waiving those rights by pleading guilty, we reverse, and remand with directions to vacate the convictions and sentences.', 'sentencing', 'State v. Hays', 'https://www.courtlistener.com/opinion/1693219/', '1693219') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because the mental states required for the lesser offenses differ only in the level of culpability attached to each in terms of seriousness and punishment, the offenses of second degree murder, reckless homicide, and criminally negligent homicide are lesser-included offenses of felony murder under part (b) of the Burns test.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in failing to instruct the jury on the lesser included offenses of felony murder but that the error was harmless beyond a reasonable doubt.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Duncan, a case very similar to the present case, this Court held that a prospective juror was properly excused where she believed that she could not impose the death penalty "unless she saw the crime committed," and where she stated that she did not want to "judge another human being on the basis of what one says against what another person says.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not err in excusing prospective juror Pannell.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that the evidence in this case clearly supported the jury''s finding that the aggravating circumstance, i.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the photographs were relevant to supplement the testimony of the victim''s wife and the medical examiner.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we cannot conclude that the Defendants were deprived of a fair trial by assignment to Division V nor do we conclude that by assigning MVU defendants to Division V, the Shelby County Courts are in violation of Local Rule 4.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the probative value of the photographs is not outweighed by their prejudicial effect and the trial court did not abuse its discretion in allowing their admission.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the jury''s verdict finding Defendant Thomas guilty of first degree murder.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we affirm the jury''s imposition of the sentence of death as to Defendant Thomas.', 'sentencing', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1355273/', '1355273') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 23, 29 (1976), this court held that when the sufficiency of an indictment or information is attacked for the first time on appeal, the indictment is sufficient if it apprised the accused of the precise offense charged with sufficient specificity to prepare his defense and to allow him to plead a resulting conviction as a bar to future prosecutions arising from the same conduct.', 'plea', 'People v. Rowell', 'https://www.courtlistener.com/opinion/2042856/', '2042856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the applicable standard for a midtrial challenge to an indictment is the prejudice standard.', 'general', 'People v. Rowell', 'https://www.courtlistener.com/opinion/2042856/', '2042856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, although the terms were not interchangeable, the defendant was not prejudiced by the substitution.', 'general', 'People v. Rowell', 'https://www.courtlistener.com/opinion/2042856/', '2042856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Campbell, this court held that “defense counsel may waive a defendant’s right of confrontation as long as the defendant does not object and the decision to stipulate is a matter of trial tactics and strategy.', 'general', 'People v. Rowell', 'https://www.courtlistener.com/opinion/2042856/', '2042856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant acknowledges that earlier in the Campbell opinion, this court held that admonishments are required where the State’s entire case is to be presented by stipulation and the defendant does not preserve or present a defense.', 'general', 'People v. Rowell', 'https://www.courtlistener.com/opinion/2042856/', '2042856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not resolve this issue, however, because, as set forth below, even under the State’s more deferential standard of review, we find that the State failed to prove beyond a reasonable doubt that defendant committed the offense of felony retail theft.', 'general', 'People v. Rowell', 'https://www.courtlistener.com/opinion/2042856/', '2042856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant, however, points to the concluding language in Campbell, where this court stated: “Where the stipulation includes a statement that the evidence is sufficient to convict the defendant or where the State’s entire case is to be presented by stipulation, we find that a defendant must be personally admonished about the stipulation and must personally agree to the stipulation.', 'general', 'People v. Rowell', 'https://www.courtlistener.com/opinion/2042856/', '2042856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we reverse the judgment of the appellate court, affirming defendant’s conviction of felony retail theft, and the judgment of the circuit court.', 'general', 'People v. Rowell', 'https://www.courtlistener.com/opinion/2042856/', '2042856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion when it rejected both of Defendant’s tendered instructions.', 'general', 'Miller v. State', 'https://www.courtlistener.com/opinion/853731/', '853731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'He claims he shot the victim in self-defense, but we find that there was sufficient evidence to support the jury’s verdict to the contrary.', 'general', 'Miller v. State', 'https://www.courtlistener.com/opinion/853731/', '853731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering Defendant’s aggressive behavior and that he fired multiple shots at his victim, we find that there was sufficient evidence to disprove Defendant’s self-defense claim.', 'general', 'Miller v. State', 'https://www.courtlistener.com/opinion/853731/', '853731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Defendant’s conviction and sentence.', 'sentencing', 'Miller v. State', 'https://www.courtlistener.com/opinion/853731/', '853731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Goodwin has not demonstrated that trial counsel’s performance in fading to consult with him about appealing the denial of his Rule 35 motion constituted deficient performance and the district court did not err by denying Goodwin relief on this claim.', 'general', 'Goodwin v. State', 'https://www.courtlistener.com/opinion/2639167/', '2639167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that Goodwin has not demonstrated that the failure to record the pretrial conference held in the criminal proceeding rose to the level of a due process violation.', 'general', 'Goodwin v. State', 'https://www.courtlistener.com/opinion/2639167/', '2639167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, although trial counsel failed to adequately consult with Goodwin as defined in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the factors that counsel knew or should have known, we conclude that a rational defendant in Goodwin’s position would not have wanted to appeal the denial of his or her Rule 35 motion.', 'general', 'Goodwin v. State', 'https://www.courtlistener.com/opinion/2639167/', '2639167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that pretrial conferences are not required to be recorded by a court reporter.', 'general', 'Goodwin v. State', 'https://www.courtlistener.com/opinion/2639167/', '2639167') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Goodwin v. State', 'https://www.courtlistener.com/opinion/2639167/', '2639167') ON CONFLICT DO NOTHING;
