INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the claims lack merit, we do not address the Commonwealth''s alternative waiver argument.', 'general', 'Commonwealth v. Collins', 'https://www.courtlistener.com/opinion/2066555/', '2066555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the PCRA court’s denial of a new trial.', 'general', 'Commonwealth v. Collins', 'https://www.courtlistener.com/opinion/2066555/', '2066555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm that part of the order of the PCRA court denying appellant a new trial.', 'general', 'Commonwealth v. Collins', 'https://www.courtlistener.com/opinion/2066555/', '2066555') ON CONFLICT DO NOTHING;
