INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a rational trier of fact could have reached that conclusion.', 'general', 'State v. Keopasaeuth', 'https://www.courtlistener.com/opinion/1817918/', '1817918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record and considering the arguments presented, we affirm the decision of the court of appeals and the judgment of the district court.', 'general', 'State v. Keopasaeuth', 'https://www.courtlistener.com/opinion/1817918/', '1817918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we hold that the reckless disregard for human life implicit in knowingly engaging in criminal activities known to carry a grave risk of death represents a highly culpable mental state, a mental state that may be taken into account in making a capital sentencing judgment when that conduct causes its natural, though also not inevitable, lethal result.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1838747/', '1838747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "[a] third person''s attempt to influence a witness is inadmissible on the issue of the defendant''s guilt unless the defendant has authorized the third party''s action," and we barred the evidence because its probative value was "far outweighed by its prejudicial impact.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1838747/', '1838747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Tison and Enmund were satisfied because the evidence proved beyond all reasonable doubt that "Diaz was a major participant in the felonies and at the very least was recklessly indifferent to human life.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1838747/', '1838747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In DuBoise, we concluded that Tison and Enmund had been satisfied with proof that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By his conduct during the entire episode, we find that he exhibited the reckless indifference to human life required by Tison.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1838747/', '1838747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions but vacate the sentence of death and remand for imposition of a sentence of life imprisonment.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1838747/', '1838747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Diaz, we affirmed the death sentence of one of three men accused in the murder of a bar manager during a holdup.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1838747/', '1838747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the aforementioned reasons, we affirm the convictions for armed robbery and first-degree felony murder, but we vacate the sentence of death and remand to the circuit court for imposition of a sentence of life imprisonment.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1838747/', '1838747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"We hold that subsections (a)(4) and (7) do implicate First Amendment freedoms.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2274154/', '2274154') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the July 11, 2006 information against Scott was brought under § 42.', 'general', 'Scott v. State', 'https://www.courtlistener.com/opinion/2274154/', '2274154') ON CONFLICT DO NOTHING;
