INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 897 (1976), this court held that under section 6-303, the elements of the offense are "(1) the act of driving a motor vehicle on the highways of this State, and (2) the fact of the revocation of the driver''s license or privilege.', 'general', 'People v. Close', 'https://www.courtlistener.com/opinion/2479519/', '2479519') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm the judgment of the appellate court.', 'general', 'People v. Close', 'https://www.courtlistener.com/opinion/2479519/', '2479519') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the appellate court reversing the trial court''s order granting defendant''s motion to quash arrest and suppress evidence and remanding for further proceedings.', 'suppression', 'People v. Close', 'https://www.courtlistener.com/opinion/2479519/', '2479519') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court did not abuse its discretion by granting Atwood permission to file a belated notice of appeal as the record shows that Atwood has offered a justifiable excuse for the delay.', 'general', 'Atwood v. State', 'https://www.courtlistener.com/opinion/2223410/', '2223410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming without deciding that the instruction is erroneous, we find that the instructions, as a whole, properly informed the jury of the State''s burden of proof.', 'general', 'Atwood v. State', 'https://www.courtlistener.com/opinion/2223410/', '2223410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that the error in giving Final Instruction 11, if any, was harmless.', 'general', 'Atwood v. State', 'https://www.courtlistener.com/opinion/2223410/', '2223410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'sentence, we find that we may affirm, reduce, or increase Atwood''s sentence.', 'sentencing', 'Atwood v. State', 'https://www.courtlistener.com/opinion/2223410/', '2223410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Atwood v. State', 'https://www.courtlistener.com/opinion/2223410/', '2223410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6]  Although the trial judge erroneously charged the jury in the language of the 1989 statute, in Bush we held that the error was harmless beyond a reasonable doubt, concluding that the proof established that the murder was heinous, atrocious, or cruel in that it involved torture or depravity of mind.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1994), this Court held the jury''s consideration of that aggravating circumstance harmless error beyond a reasonable doubt.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained below, considering the nature of the crime and the defendant in light of these factors, we conclude that imposition of the death penalty for the torturous and cruel premeditated killing of this young woman is not disproportionate to the penalty imposed in similar cases.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the nature of the crime and the defendant, we conclude that the torturous and cruel murder of this nineteen-year-old woman places Pike into the class of defendants for whom the death penalty is an appropriate punishment.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review, we conclude that the following cases in which the death penalty has been imposed have many similarities with this case.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the risk to human life is inherent in the grading of the offense of conspiracy to commit first-degree murder.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For both of these reasons, we conclude that enhancement factor should not have been applied.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, given the circumstances surrounding this offense, especially the heinous nature of the crime and the fact that the Defendant showed no remorse, we conclude that the Defendant met the criteria for consecutive sentencing and the trial court did not abuse her discretion in ordering such.', 'sentencing', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon careful review of the record, we conclude that the Defendant has offered no grounds that warrant relief from her convictions of premeditated first degree murder and conspiracy to commit first degree murder.', 'general', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that the Defendant has failed to establish any ground warranting relief from the sentence of death and the consecutive sentence of twenty-five (25) years.', 'sentencing', 'State v. Pike', 'https://www.courtlistener.com/opinion/1720938/', '1720938') ON CONFLICT DO NOTHING;
