INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we conclude that at the point Officer McGinnis stopped Appellant, a reasonable person in the same position would not have felt free to leave;', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/2305968/', '2305968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Officer Unvert had a particularized and objective basis from the reports of Vorderstrasse and Waters for suspecting Brooks of criminal activity, namely the unauthorized use of Vorderstrasse’s calling card.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1928936/', '1928936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the county court did not err in overruling Brooks’ motion to suppress.', 'suppression', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1928936/', '1928936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1928936/', '1928936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we hold that it does not and thus, the sentence imposed by the trial court is affirmed.', 'sentencing', 'Commonwealth v. Yuhasz', 'https://www.courtlistener.com/opinion/2320944/', '2320944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because ASORA''s registration, disclosure, and dissemination provisions violate the protection against ex post facto laws afforded by the Alaska Constitution as it applies to defendants who committed their crimes before the legislature enacted ASORA, we hold that AS 12.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[13] Accordingly, we held that the Supreme Court decision disposed of Danks''s federal claim, and we saw "no reason for us to interpret Alaska''s constitutional provision differently.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] Does applying ASORA to "John Doe," who committed his crime and was convicted and sentenced before ASORA was enacted, violate the ex post facto clause of the Alaska Constitution? We conclude that it does because ASORA imposes burdens that have the effect of adding punishment beyond what could be imposed when the crime was committed.', 'sentencing', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it is the criminal conviction, and only the criminal conviction, that triggers obligations under ASORA, we conclude that this factor supports the conclusion that ASORA is punitive in effect.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Summing up the effects under the seven factors, we conclude that ASORA''s effects are punitive, and convincingly outweigh the statute''s non-punitive purposes and effects.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And because we conclude that ASORA is an ex post facto law under the same standard for reviewing ex post facto claims under the Alaska Constitution that courts apply under the Federal Constitution, we decline to adopt the standard Doe advocates.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on decisions of the United States Supreme Court and the Seventh and Ninth Circuit Courts of Appeals, we concluded that because the extension did not increase the punishment or change the elements of the offense necessary to establish guilt, it did not violate the Federal or the Alaska Constitution.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1109 (1960), which upheld a statute that was enacted for valid regulatory purposes and that was not punitive in effect, we concluded that because the statute''s purposes were compensatory rather than punitive it did not violate either the federal or state ex post facto clause.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that the Supreme Court had rejected a similar attack on a habitual offender statute that provided enhanced punishment for a fourth felony conviction, we affirmed the revocation.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that ASORA''s registration requirement does not apply to persons who committed their crimes before ASORA became effective, and reverse the superior court order granting final judgment in favor of the state and against Doe.', 'general', 'Doe v. State', 'https://www.courtlistener.com/opinion/2628160/', '2628160') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the district court erred in ruling that HRS § 286-163 was inapplicable to the present matter on the basis that Entrekin was the only person injured as a result of the vehicular accident in which he was involved.', 'general', 'State v. Entrekin', 'https://www.courtlistener.com/opinion/2521158/', '2521158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Entrekin argues that, even if we hold that HRS § 286-163 applies to single-car accidents in which only the driver of the vehicle is injured, the police are nevertheless required, pursuant to HRS § 286—151(b)(1),
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that HRS § 286-163 operates as an exception to HRS § 286-151, which generally requires the police lawfully to arrest the driver prior to administering a blood test.', 'general', 'State v. Entrekin', 'https://www.courtlistener.com/opinion/2521158/', '2521158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the above, we hold that HRS ch.', 'general', 'State v. Entrekin', 'https://www.courtlistener.com/opinion/2521158/', '2521158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the nonconsen-sual extraction of a blood sample from Entre-kin pursuant to HRS § 286-163 violated neither the fourth amendment to the United States Constitution nor article 1, section 7 of the Hawai''i Constitution, notwithstanding the fact that the police had not placed him under arrest prior to obtaining the blood sample.', 'search_seizure', 'State v. Entrekin', 'https://www.courtlistener.com/opinion/2521158/', '2521158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the district court erred in granting Entrekin’s motion to suppress the results of his blood test.', 'suppression', 'State v. Entrekin', 'https://www.courtlistener.com/opinion/2521158/', '2521158') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of these reasons, we hold that 75 Pa.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all the foregoing reasons we conclude that Section 3802(a)-(c) provides a reasonable standard for drivers to gauge their conduct, and therefore, the statute is not void for vagueness.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that they lack standing.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 26 As for Appellant Imes, whose case did involve an accident, we conclude that he has waived the issue.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'above, we conclude that Appellants have either failed to demonstrate that they have standing to challenge Section 3804 or, alternatively, they have waived this claim.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we conclude that 75 Pa.', 'general', 'Commonwealth v. Beshore', 'https://www.courtlistener.com/opinion/1979564/', '1979564') ON CONFLICT DO NOTHING;
