INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and dismiss the conviction of attempted felony murder;', 'dismissal', 'State v. Alvarado', 'https://www.courtlistener.com/opinion/1760729/', '1760729') ON CONFLICT DO NOTHING;
