INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under a prior statute, this Court held that an accessory was not a principal and that there could be no conviction of a defendant as an accessory upon an indictment as a principal.', 'general', 'Probst v. State', 'https://www.courtlistener.com/opinion/1932327/', '1932327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under the circumstances of this case, the Probst jury should have received specific instructions regarding jury unanimity with regard to their assessment of which act (Probst''s shot or Miller''s) supported the verdict.', 'general', 'Probst v. State', 'https://www.courtlistener.com/opinion/1932327/', '1932327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the order of the jury instructions and the inaccurate use of gender had such potential for juror confusion that the reversal of Probst''s convictions is required.', 'jury_instruction', 'Probst v. State', 'https://www.courtlistener.com/opinion/1932327/', '1932327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In considering the Probst jury instructions as a whole, we find that they failed to meet the "reasonably informative and not misleading" standard.', 'jury_instruction', 'Probst v. State', 'https://www.courtlistener.com/opinion/1932327/', '1932327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, given all of the evidence, a rational jury would necessarily entertain a reasonable doubt as to the defendant''s guilt, the due process guarantee requires that we reverse and order a judgment of acquittal.', 'general', 'Swearingen v. State', 'https://www.courtlistener.com/opinion/1634893/', '1634893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that appellee’s Sixth Amendment right to counsel remained when the telephone conversations at issue occurred.', 'general', 'State Ex Rel. Sims v. Perry', 'https://www.courtlistener.com/opinion/1335540/', '1335540') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that unless a criminal defendant can show that the government has obtained a, dismissal of adversarial judicial criminal proceedings against him or her in order to circumvent his or her constitutional rights, once such criminal proceedings have been dismissed, the right to the assistance of counsel .', 'dismissal', 'State Ex Rel. Sims v. Perry', 'https://www.courtlistener.com/opinion/1335540/', '1335540') ON CONFLICT DO NOTHING;
