INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this test to the facts of the case before us, we conclude that Chappell’s convictions for both Class A felony burglary and Class B felony burglary constitute impermissible double jeopardy.', 'general', 'Chappell v. State', 'https://www.courtlistener.com/opinion/2437309/', '2437309') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that when an objection to a charging document is not made until after the entry of judgment, if the applicable code section is named in the charging document its language may be read into the text of the charge.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/2508184/', '2508184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under that standard, this Court held that although the charging document filed against Cahoon contained only the date, time, the applicable code section and the words “resisting, obstructing and delaying an officer,” it was legally sufficient to confer jurisdiction.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/2508184/', '2508184') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction and the sentence reached by the district court.', 'sentencing', 'State v. Jones', 'https://www.courtlistener.com/opinion/2508184/', '2508184') ON CONFLICT DO NOTHING;
