INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Moffitt''s convictions for possession of cocaine, possession of marijuana, and resisting law enforcement.', 'general', 'Moffitt v. State', 'https://www.courtlistener.com/opinion/2094355/', '2094355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have reviewed the record and conclude that no abuse of discretion is disclosed, and therefore we affirm the judgment of the trial court.', 'general', 'State v. Hood', 'https://www.courtlistener.com/opinion/1377962/', '1377962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995) (“Because we hold that under the facts of this case defendant had no reasonable expectation of privacy in luggage relinquished to airline personnel, neither the Fourth Amendment to the United States Constitution nor article 2, section 8 of the Arizona Constitution is implicated in this case.', 'search_seizure', 'State v. Juarez', 'https://www.courtlistener.com/opinion/2598658/', '2598658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that White had automatic standing because:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a defendant who seeks to exclude evidence pursuant to Article 2, Section 8, of the Arizona Constitution must show that he or she had a legitimate expectation of privacy in the area searched.', 'general', 'State v. Juarez', 'https://www.courtlistener.com/opinion/2598658/', '2598658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that a defendant charged with a possessory offense does not have automatic standing to challenge a search and seizure in which someone else’s rights may have been violated.', 'search_seizure', 'State v. Juarez', 'https://www.courtlistener.com/opinion/2598658/', '2598658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '800 does not prohibit successive motions, we hold that where, as here, a defendant raises an issue under rule 3.', 'general', 'State v. McBride', 'https://www.courtlistener.com/opinion/1780977/', '1780977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that collateral estoppel will not be invoked to bar relief where its application would result in a manifest injustice.', 'general', 'State v. McBride', 'https://www.courtlistener.com/opinion/1780977/', '1780977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Cases in which we held that an unauthorized habitual offender sentence for a life felony could be rectified via rule 3.', 'sentencing', 'State v. McBride', 'https://www.courtlistener.com/opinion/1780977/', '1780977') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that a criminal defendant charged with murder is entitled to have his jury charged on voluntary manslaughter and involuntary manslaughter on request of counsel without regard to the evidence presented at trial.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1540573/', '1540573') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Williams', 'https://www.courtlistener.com/opinion/1540573/', '1540573') ON CONFLICT DO NOTHING;
