INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the presentment charging the Defendant with aggravated perjury was defective in that it did not sufficiently state the facts constituting the alleged offense.', 'general', 'State v. Cutshaw', 'https://www.courtlistener.com/opinion/2433397/', '2433397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the evidence would have been legally sufficient to support the conviction for aggravated perjury had the presentment properly charged the Defendant.', 'general', 'State v. Cutshaw', 'https://www.courtlistener.com/opinion/2433397/', '2433397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth in the discussion above, we conclude that the Defendant’s first and fourth issues on appeal have merit.', 'general', 'State v. Cutshaw', 'https://www.courtlistener.com/opinion/2433397/', '2433397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Defendant’s conviction for aggravated pexjury and dismiss the presentment against him.', 'dismissal', 'State v. Cutshaw', 'https://www.courtlistener.com/opinion/2433397/', '2433397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997), where we held that the prosecutor''s comments regarding merged aggravating circumstances were permissible, the prosecutor here clearly argued that because the armed robbery and pecuniary gain circumstances merged, "that makes them even more powerful, even more weighty, even more demanding.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After considering these standards, case law from this State and other jurisdictions, as well as the facts of this case, we conclude that the trial court did not clearly err in allowing Michael Johnson, an experienced crack cocaine dealer, to express opinion testimony regarding the identity and approximate weight of the rocky substance contained in the sandwich bag obtained from Darryl Jenkins.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these factual circumstances, we conclude that the limited, boilerplate motions for judgment of acquittal which were of a technical and pro-forma nature as voiced by counsel for Brooks were totally inadequate to preserve a sufficiency of the evidence claim for appellate review.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court abused its discretion in overruling defense counsel''s objection regarding this line of argument.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court abused its discretion in overruling defense counsel''s objections to these improper comments.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that the trial court did not clearly err in allowing Michael Johnson to express his opinion, in the form of expert testimony, that the sandwich bag contained crack cocaine.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the purely technical and pro-forma boilerplate motions for judgment of acquittal offered by Brooks were inadequate to preserve a sufficiency of the evidence claim for appellate review.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this direct and circumstantial evidence presented by the State amounts to competent, substantial evidence supporting a jury verdict finding Brooks guilty of first-degree felony murder with robbery as the underlying predicate offense.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this evidence was sufficient to establish that Brooks intended to obtain a specific amount of crack cocaine28 or more gramsthat was above the requisite amount to prove trafficking,[24] and we therefore determine that there is competent, substantial evidence to support a jury verdict finding Brooks guilty of first-degree felony murder with attempted trafficking in cocaine as the underlying offense.', 'general', 'Brooks v. State', 'https://www.courtlistener.com/opinion/1712849/', '1712849') ON CONFLICT DO NOTHING;
