INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At that time we held that no fairly debatable constitutional question was presented so as to give this court jurisdiction on direct appeal, and accordingly the cause was transferred to the Appellate Court for *14 the Second District.', 'general', 'Molitor v. Kaneland Community Unit District No. 302', 'https://www.courtlistener.com/opinion/2225058/', '2225058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If reason existed for legislative rather than judicial action to invalidate an exculpatory clause in a lease, as against public policy, as this court held in O''Callaghan, then, beyond doubt, the same rule should have been applied by the court in its decision in this case.', 'general', 'Molitor v. Kaneland Community Unit District No. 302', 'https://www.courtlistener.com/opinion/2225058/', '2225058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the rule of school district tort immunity is unjust, unsupported by any valid reason, and has no rightful place in modern day society.', 'general', 'Molitor v. Kaneland Community Unit District No. 302', 'https://www.courtlistener.com/opinion/2225058/', '2225058') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Historically we find that the doctrine of the sovereign immunity of the state, the theory that "the King can do no wrong," was first extended to a subdivision of the state in 1788 in Russell v.', 'general', 'Molitor v. Kaneland Community Unit District No. 302', 'https://www.courtlistener.com/opinion/2225058/', '2225058') ON CONFLICT DO NOTHING;
