INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an attempted child enticement under Wis.', 'general', 'State v. Robins', 'https://www.courtlistener.com/opinion/2013868/', '2013868') ON CONFLICT DO NOTHING;
