INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the offense of attempted child enticement under Wis.', 'general', 'State v. Robins', 'https://www.courtlistener.com/opinion/2013868/', '2013868') ON CONFLICT DO NOTHING;
