INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s decision not to instruct the jury on the substance of Fairchild’s requested charges and reverse and remand this case for a new trial.', 'general', 'Fairchild v. South Carolina Department of Transportation', 'https://www.courtlistener.com/opinion/1375427/', '1375427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand.', 'general', 'Fairchild v. South Carolina Department of Transportation', 'https://www.courtlistener.com/opinion/1375427/', '1375427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, because Palmer failed to offer evidence Fairchild violated traffic laws, was speeding or following too closely, or any other evidence to support an inference of negligence, we affirm the trial court’s grant of a directed verdict on the issue of comparative negligence.', 'general', 'Fairchild v. South Carolina Department of Transportation', 'https://www.courtlistener.com/opinion/1375427/', '1375427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s decision regarding the IME and affirm the trial court’s decision to direct Fairchild’s verdict on comparative negligence.', 'general', 'Fairchild v. South Carolina Department of Transportation', 'https://www.courtlistener.com/opinion/1375427/', '1375427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon a review of the evidence, we conclude that the Troopers had reasonable suspicion which supported the investigatory stop.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2029871/', '2029871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the definition of manufacturing quoted above, we conclude that onee an individual erushes up pills in order to separate the ephedrine from the pill binders, the manufacturing process has begun.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2029871/', '2029871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'denied, we concluded that I.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2029871/', '2029871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/2029871/', '2029871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that new constitutional rules of criminal procedure will
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that we must apply the rules governing procedural requirements before giving consideration to the merits of underlying claims for postconviction relief.', 'general', 'Flamer v. State', 'https://www.courtlistener.com/opinion/1486303/', '1486303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Indeed, as noted earlier, this Court held on direct appeal and we continue to find that the instructions actually given at Flamer’s penalty phase hearing were appropriate and adequate to guide the jury’s discretion.', 'general', 'Flamer v. State', 'https://www.courtlistener.com/opinion/1486303/', '1486303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'has no retroactive application to Flamer’s case, we conclude that reconsideration of his claim is not warranted in the interest of justice.', 'general', 'Flamer v. State', 'https://www.courtlistener.com/opinion/1486303/', '1486303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither justice nor the need to insure compliance with the Fourth Amendment requires reconsideration of Flamer’s challenge to the admissibility of the bayonet.', 'search_seizure', 'Flamer v. State', 'https://www.courtlistener.com/opinion/1486303/', '1486303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s instructions adequately apprised the jury members of their duties, responsibilities and options for imposing sentence on Flamer.', 'sentencing', 'Flamer v. State', 'https://www.courtlistener.com/opinion/1486303/', '1486303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we find that Flamer cannot establish the required prejudice.', 'general', 'Flamer v. State', 'https://www.courtlistener.com/opinion/1486303/', '1486303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since Flamer can demonstrate neither the requisite cause nor that actual prejudice resulted from his claimed procedural defects in the appeal of his convictions, we find that his contentions are barred pursuant to the provisions of Superior Court Criminal Rule 61(i)(3).', 'general', 'Flamer v. State', 'https://www.courtlistener.com/opinion/1486303/', '1486303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Flamer has failed to assert any reason in the interest of justice which requires further consideration of the penalty phase jury instructions.', 'jury_instruction', 'Flamer v. State', 'https://www.courtlistener.com/opinion/1486303/', '1486303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the contentions raised by Flamer and the actions taken by Reardon at trial, we find that Reardon’s performance, at both the guilt/innocence and penalty phases of the trial, was within the broad scope of reasonableness as set forth in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that, effective January 1, 1978, a waiver of a right to a Common Pleas trial in a criminal case for which a prison sentence is authorized by law may be accepted in a Justice of the Peace Court only if all the proceedings material to that waiver, under the guidelines hereinabove set forth, are also electronically or stenographically recorded.', 'sentencing', 'Shoemaker v. State', 'https://www.courtlistener.com/opinion/2169304/', '2169304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has failed in this case to make the requisite affirmative showing of a knowing and intelligent waiver of the right to trial in the Court of Common Pleas.', 'plea', 'Shoemaker v. State', 'https://www.courtlistener.com/opinion/2169304/', '2169304') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Shoemaker v. State', 'https://www.courtlistener.com/opinion/2169304/', '2169304') ON CONFLICT DO NOTHING;
