INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court did not abuse its discretion in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the verdict, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'manslaughter, we affirm the circuit court’s ruling.', 'general', 'Starling v. State', 'https://www.courtlistener.com/opinion/3172998/', '3172998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, in the exercise of our supervisory power to insure the fair administration of justice,[4] we hold that all custodial interrogation including any information about rights, any waiver of those rights, and all questioning shall be electronically recorded where feasible and must be recorded when questioning occurs at a place of detention.', 'general', 'State v. Scales', 'https://www.courtlistener.com/opinion/2197014/', '2197014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction.', 'general', 'State v. Scales', 'https://www.courtlistener.com/opinion/2197014/', '2197014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though the police in this case disregarded our prior warnings in Robinson and Pilcher, we affirm appellant''s conviction because even if the unrecorded statements had been suppressed the result would have been the same.', 'suppression', 'State v. Scales', 'https://www.courtlistener.com/opinion/2197014/', '2197014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction.', 'general', 'State v. Scales', 'https://www.courtlistener.com/opinion/2197014/', '2197014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances we hold that the trial court was within its discretion in concluding that the last test burn was performed under conditions “substantially similar” to those of the fire.', 'general', 'State v. Ritt', 'https://www.courtlistener.com/opinion/2111404/', '2111404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that Ritt’s statement to Rgnonti was voluntary and the trial court did not err in admitting it.', 'general', 'State v. Ritt', 'https://www.courtlistener.com/opinion/2111404/', '2111404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the confession was not involuntary despite the defendant’s emotional breakdown:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the police may have improperly suggested that they would advocate for psychiatric help and could influence the charges against the defendant, we held that the statements of the police, “though improper, were not the kind of statements that would make an innocent man confess.', 'general', 'State v. Ritt', 'https://www.courtlistener.com/opinion/2111404/', '2111404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing carefully the totality of the circumstances surrounding Rgnonti’s interview of Ritt, we conclude that her statement was not coerced.', 'general', 'State v. Ritt', 'https://www.courtlistener.com/opinion/2111404/', '2111404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court was within its discretion in excluding the expert testimony of Dr.', 'general', 'State v. Ritt', 'https://www.courtlistener.com/opinion/2111404/', '2111404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Ritt’s conviction.', 'general', 'State v. Ritt', 'https://www.courtlistener.com/opinion/2111404/', '2111404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that there was sufficient evidence to sustain appellant’s first-degree-battery conviction.', 'general', 'Bangs v. State', 'https://www.courtlistener.com/opinion/1501332/', '1501332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 501, 504 (1993), we held that a written waiver is not required to effect a valid waiver.', 'general', 'Bangs v. State', 'https://www.courtlistener.com/opinion/1501332/', '1501332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When the appellant in Bowen acknowledged that he understood his rights but answered questions without mentioning those rights, we held that he waived the rights by implication.', 'general', 'Bangs v. State', 'https://www.courtlistener.com/opinion/1501332/', '1501332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewed in the light most favorable to the State, we conclude that there is sufficient evidence to support appellant’s capital-murder convictions.', 'general', 'Bangs v. State', 'https://www.courtlistener.com/opinion/1501332/', '1501332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the evidence in the light most favorable to the State and given the totality of the circumstances, we conclude that the trial court was not clearly erroneous in denying appellant’s motion to suppress.', 'suppression', 'Bangs v. State', 'https://www.courtlistener.com/opinion/1501332/', '1501332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we conclude that the trial court did not abuse its discretion in granting the State’s challenge for cause.', 'general', 'Bangs v. State', 'https://www.courtlistener.com/opinion/1501332/', '1501332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find no merit in appellant’s arguments, and we affirm.', 'general', 'Bangs v. State', 'https://www.courtlistener.com/opinion/1501332/', '1501332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm appellant’s judgment of conviction.', 'general', 'Bangs v. State', 'https://www.courtlistener.com/opinion/1501332/', '1501332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although no physical force was used, given the totality of the circumstances, we hold that a seizure took place within the meaning of article I, section 7 of the Hawaii Constitution.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the State has failed to meet its burden of proof that consent was voluntary and uncoerced, we hold that Quino''s seizure was unlawful.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the police conduct violated Quino''s right to be secure against unreasonable seizures guaranteed by article I, section 7 of the Hawaii Constitution.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that an unlawful seizure occurred prior to Quino''s flight, it is unnecessary to address the remaining issues.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances of this case, we conclude that Quino did not voluntarily and intelligently agree to be detained.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Quino''s conviction, order the evidence suppressed, and remand the case to circuit court for proceedings consistent with this opinion.', 'suppression', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Tsukiyama''s conviction and held that no "stop" or "seizure" had taken place.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statement at issue is admissible within the present sense impression of our hearsay rule.', 'general', 'Turner v. State', 'https://www.courtlistener.com/opinion/1116640/', '1116640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Turner v. State', 'https://www.courtlistener.com/opinion/1116640/', '1116640') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Seager', 'https://www.courtlistener.com/opinion/1814933/', '1814933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the district court’s suppression of the challenged evidence and remand for further proceedings consistent with this opinion.', 'suppression', 'State v. Seager', 'https://www.courtlistener.com/opinion/1814933/', '1814933') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction if, looking to the evidence and reasonable inferences therefrom which support the verdict, there is substantial evidence of probative value to support the conclusion of the trier of fact.', 'general', 'Barger v. State', 'https://www.courtlistener.com/opinion/2225706/', '2225706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this appeal we reverse the trial court’s denial of a motion for a judgment of acquittal on the charge of possession of a controlled substance with intent to deliver.', 'general', 'Cline v. State', 'https://www.courtlistener.com/opinion/2259248/', '2259248') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we reverse Cline’s conviction for Possession with Intent to Deliver a Narcotic Controlled Substance, in violation of 11
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that "to whom the exposure is directed is not an essential element of the offense of indecent exposure.', 'general', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, we held that indecency with a child by sexual contact was a lesser-included offense of aggravated sexual assault of a child even though the indecency offense contained what might appear to be an extra elementintent to arouse or gratify sexual desire.', 'general', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[49] Employing an Ervin analysis in Bigon, we held that felony murder, intoxication manslaughter, and manslaughter (all involving the same victim) were the "same" for Double Jeopardy purposes.', 'general', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that indecent exposure was a lesser-included offense of indecency with a child by exposure for the purpose of determining whether a defendant was entitled to a lesser-included-offense jury instruction.', 'jury_instruction', 'Ex Parte Amador', 'https://www.courtlistener.com/opinion/2291805/', '2291805') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the provision ordering a person convicted of a dangerous crime against children supervised on parole "on such conditions as the court .', 'general', 'State v. Wagstaff', 'https://www.courtlistener.com/opinion/1218585/', '1218585') ON CONFLICT DO NOTHING;
