INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Michigan law requires a defendant to take property from the physical person or immediate presence of a victim to commit a larceny from the person.', 'general', 'People v. Smith-Anthony', 'https://www.courtlistener.com/opinion/2712493/', '2712493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that there was insufficient evidence on the from-the-person element because there was reasonable doubt regarding whether the defendant took the wallet from the victim’s pocket.', 'general', 'People v. Smith-Anthony', 'https://www.courtlistener.com/opinion/2712493/', '2712493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant in this case did not take property from the person or immediate presence of the victim, or use force or threats to separate a victim from the victim’s property, we conclude that she did not commit a larceny from the person.', 'general', 'People v. Smith-Anthony', 'https://www.courtlistener.com/opinion/2712493/', '2712493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that they did not.', 'general', 'People v. Smith-Anthony', 'https://www.courtlistener.com/opinion/2712493/', '2712493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '50 This approach allows a robbery conviction even where a defendant uses force for the first time after completing a taking, and we concluded that the robbery statute then in force did not permit this.', 'general', 'People v. Smith-Anthony', 'https://www.courtlistener.com/opinion/2712493/', '2712493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of Appeals, which reversed her conviction of larceny from the person.', 'general', 'People v. Smith-Anthony', 'https://www.courtlistener.com/opinion/2712493/', '2712493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the judgment of the Court of Appeals, which reversed defendant’s conviction.', 'general', 'People v. Smith-Anthony', 'https://www.courtlistener.com/opinion/2712493/', '2712493') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Court of Appeals properly reversed defendant’s conviction, so we affirm the judgment of Court of Appeals.', 'general', 'People v. Smith-Anthony', 'https://www.courtlistener.com/opinion/2712493/', '2712493') ON CONFLICT DO NOTHING;
