INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Without questioning this assumption, we hold that orders relating to class certification are not independently appealable under § 1291 prior to judgment.', 'general', 'Coopers & Lybrand v. Livesay', 'https://www.courtlistener.com/opinion/109908/', '109908') ON CONFLICT DO NOTHING;
