INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, for the foregoing reasons we hold that there was no abuse of discretion or error requiring reversal of appellant’s DUI conviction.', 'general', 'Terrence Melvin Koonce v. District of Columbia', 'https://www.courtlistener.com/opinion/2787400/', '2787400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we agree with ap*1012pellant’s claim that he should have been able to obtain the requested video and liquor bottle through discovery, we conclude that the trial court did not commit error in the actions it took in response to the government’s failure to preserve and produce these items of evidence, or in instructing the jury.', 'general', 'Terrence Melvin Koonce v. District of Columbia', 'https://www.courtlistener.com/opinion/2787400/', '2787400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1020We conclude that the trial court did not abuse discretion in its choice of sanction.', 'general', 'Terrence Melvin Koonce v. District of Columbia', 'https://www.courtlistener.com/opinion/2787400/', '2787400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Given the trial court’s finding that the government’s failure to meet discovery obligations with respect to the video, though negligent, was not willful, and the other evidence in the case, we conclude that the sanction imposed by the trial court was “just under the circumstances.', 'general', 'Terrence Melvin Koonce v. District of Columbia', 'https://www.courtlistener.com/opinion/2787400/', '2787400') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm appellant’s conviction.', 'general', 'Terrence Melvin Koonce v. District of Columbia', 'https://www.courtlistener.com/opinion/2787400/', '2787400') ON CONFLICT DO NOTHING;
