INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the Legislature’s use of the common-law term “tort,” we hold that “tort liability” as used in MCL 691.', 'general', 'in Re Bradley Estate', 'https://www.courtlistener.com/opinion/2712648/', '2712648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the GTLA barred the plaintiffs’ negligence claim, but that the plaintiffs’ second claim, breach of an implied contract, was not barred.', 'general', 'in Re Bradley Estate', 'https://www.courtlistener.com/opinion/2712648/', '2712648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accord with the Ross Court’s holding that the GTLA will not bar recoveiy simply because the underlying facts could have also established a tort cause of action, we conclude that tort-like damages are recoverable in a contempt action assuming contempt can be proved.', 'general', 'in Re Bradley Estate', 'https://www.courtlistener.com/opinion/2712648/', '2712648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because the word “tort” has “acquired a peculiar and appropriate meaning” in our common law, and because the Legislature is presumed to be aware of the *385common law when enacting legislation, we conclude that the term “tort” as used in MCL 691.', 'general', 'in Re Bradley Estate', 'https://www.courtlistener.com/opinion/2712648/', '2712648') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Court of Appeals reached a contrary conclusion, we reverse the judgment of the Court of Appeals and remand this case to the probate court for entry of an order granting summary disposition in favor of respondent.', 'general', 'in Re Bradley Estate', 'https://www.courtlistener.com/opinion/2712648/', '2712648') ON CONFLICT DO NOTHING;
