INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s admission of the testifying witness’ prior statement and preliminary hearing testimony was not reversible error and that the evidence was sufficient to support the Defendant’s convictions.', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a suspicion that a witness is exaggerating his or her memory loss at trial is not sufficient to abrogate the admissibility of a recorded recollection pursuant to Rule 803(5).', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, for the purposes of Tennessee Rule of Evidence 803(26), a pri- or statement about events that a witness claims at trial to be unable to remember is “inconsistent” with the witness’ trial testimony.', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we hold that, to the extent the trial court’s approach possibly could be considered error, any error in failing to technically order Spencer to testify clearly was harmless.', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '7 Accordingly, we hold that the trial court committed no reversible error in determining Spencer to be unavailable for the purposes of Rule 804(a)(3).', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the appropriate standard of review, we hold that the proof at trial was sufficient for the jury to determine that the Defendant accosted the victim in the victim’s back yard and pulled a handgun out of his pocket.', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the purposes of any further litigation in this case, we hold that the proof also was sufficient to support the Defendant’s conviction of reckless homicide.', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the Defendant is not entitled to any relief based on this argument.', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we hold that the Defendant is not entitled to relief on the issues raised in this appeal.', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth in the remainder of our analysis of this issue, we hold that the Defendant is not entitled to a new trial on the basis of the jury’s inconsistent verdicts.', 'general', 'State of Tennessee v. Marlo Davis', 'https://www.courtlistener.com/opinion/2805471/', '2805471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, when officials of a school district embezzled tax funds over the course of several years, we held that no mail fraud had occurred even though the success of the scheme plainly depended on the officials'' causing tax bills to be sent by mail (and thus tax payments to be received) every year.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Keeble, for example, we held that the defendant was entitled to an instruction on the lesser offense of simple assault:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the mailing of the cashed checks to the drawee banks could not supply the mailing element of the mail fraud charges.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on Kann, this Court held that these mailings were not in execution of the scheme as required by the statute because it was immaterial to the defendants how the oil company went about collecting its payment.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held, however, that in the absence of any evidence that the tax levy was increased as part of the fraud, the mailing element of the offense could not be supplied by mailings "made or caused to be made under the imperative command of duty imposed by state law.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Schmuck''s conviction was consistent with the statutory definition of mail fraud and that he was not entitled to a lesser included offense instruction on odometer tampering.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'United States, we concluded that even though defendants who cashed checks obtained as part of a fraudulent scheme knew that the bank cashing the checks would send them by mail to a drawee bank for collection, they did not thereby violate the mail fraud statute, because upon their receipt of the cash "[t]he scheme .', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, when those officials caused the school district to pay by mail credit card bills  a step plainly necessary to enable their continued fraudulent use of the credit card  we concluded that no mail fraud had occurred.', 'general', 'Schmuck v. United States', 'https://www.courtlistener.com/opinion/112222/', '112222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and in part reverse the judgment of the Court of Appeals and remand the cause with direction.', 'general', 'State v. Howard', 'https://www.courtlistener.com/opinion/1814347/', '1814347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As foreshadowed in part I, we affirm that portion of the Court of Appeals’ judgment which affirms the district court’s affirmance of the conviction of Howard on the refusal to submit and second-offense driving under the influence charges, reverse that portion of the Court of Appeals’ judgment which reverses the district court’s affirmance of the conviction of Howard on the reckless driving charge, and remand the cause to the Court of Appeals with the direction that it issue a mandate in accor...', 'general', 'State v. Howard', 'https://www.courtlistener.com/opinion/1814347/', '1814347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '] 568, we hold that, under § 5 of the Willis-Campbell Act, a civil action to recover taxes, which in fact are penalties, is punitive in character and barred by a prior conviction of the defendant for a criminal offense involving the same transactions.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that these in rem civil forfeitures are neither "punishment" nor criminal for purposes of the Double Jeopardy Clause.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In another unanimous decision, we held that the forfeiture was not barred by the prior criminal proceeding.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the Montana marijuana tax, we held that because "tax *286 statutes serve a purpose quite different from civil penalties,.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Michigan, supra, at 452, where we held that "forfeiture .', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the "fundamental nature of criminal forfeiture" is punishment.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 610, 621, we held that §§ 881(a)(4) and (a)(7) must be considered to qualify as such, partly because forfeitures have historically been understood as punishment and more importantly because no remedial purpose underlay the sanction the statute created.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that any forfeiture was subject to the constraints of the Excessive Fines Clause of the Eighth Amendment.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6] On that basis, we held that imposition of the tax after criminal prosecution of the taxpayer violated double jeopardy.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kurth Ranch we held that the Double Jeopardy Clause applies to punitive proceedings even if they are labeled a tax.', 'general', 'United States v. Ursery', 'https://www.courtlistener.com/opinion/118052/', '118052') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that application of N.', 'general', 'Britt v. State', 'https://www.courtlistener.com/opinion/1292876/', '1292876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that N.', 'general', 'Britt v. State', 'https://www.courtlistener.com/opinion/1292876/', '1292876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, we reverse the decision of the Court of Appeals to the extent that court determined N.', 'general', 'Britt v. State', 'https://www.courtlistener.com/opinion/1292876/', '1292876') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rom-er’s conduct in orchestrating and photographing sexual conduct between minors, including K.', 'general', 'State of Iowa v. Brent Michael Romer', 'https://www.courtlistener.com/opinion/4472221/', '4472221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the events at issue here all fall within a common scheme or pattern, and thus, it was appropriate for the charges to be joined.', 'general', 'State of Iowa v. Brent Michael Romer', 'https://www.courtlistener.com/opinion/4472221/', '4472221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, in Lam, we found that the two offenses with which Lam was charged— two otherwise unrelated burglaries — “were parts of a common scheme or plan to burglarize apartments during normal working hours.', 'general', 'State of Iowa v. Brent Michael Romer', 'https://www.courtlistener.com/opinion/4472221/', '4472221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Evidence of one burglary was not needed to prove any of the elements of the other burglary, yet we found that trying them together was appropriate.', 'general', 'State of Iowa v. Brent Michael Romer', 'https://www.courtlistener.com/opinion/4472221/', '4472221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, in Elston, we found that join-der of the charges was proper.', 'general', 'State of Iowa v. Brent Michael Romer', 'https://www.courtlistener.com/opinion/4472221/', '4472221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though we found that there was no temporal proximity and the modus operandi was dissimilar, we nonetheless found a “common scheme or plan” existed.', 'general', 'State of Iowa v. Brent Michael Romer', 'https://www.courtlistener.com/opinion/4472221/', '4472221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our review, we affirm the decision of the court of appeals and the judgment of the district court.', 'general', 'State of Iowa v. Brent Michael Romer', 'https://www.courtlistener.com/opinion/4472221/', '4472221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the rulings of the district court on each of the three issues Romer raises.', 'general', 'State of Iowa v. Brent Michael Romer', 'https://www.courtlistener.com/opinion/4472221/', '4472221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with these authorities, we hold that amending the information during trial to add an enhancement can prejudice “substantial rights of the defendant”'' — -if the defendant had no prior notice of the State’s plan to amend and would have pled guilty had he or she known of that plan before trial.', 'general', 'State of Iowa v. Anthony George Brothern', 'https://www.courtlistener.com/opinion/4472222/', '4472222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Also, we concluded that Maghee “appeared ready to defend against .', 'general', 'State of Iowa v. Anthony George Brothern', 'https://www.courtlistener.com/opinion/4472222/', '4472222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the defendant’s conviction and sentence, but vacate the court of appeals decision that rejected his ineffective-assistance claim.', 'sentencing', 'State of Iowa v. Anthony George Brothern', 'https://www.courtlistener.com/opinion/4472222/', '4472222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Brothern’s conviction and sentence, but we do so without foreclosing Brothern from filing an application for postconviction relief alleging he received ineffective assistance of counsel at trial when his attorney failed to object to the State’s motion to amend count I to add the habitual offender enhancement.', 'sentencing', 'State of Iowa v. Anthony George Brothern', 'https://www.courtlistener.com/opinion/4472222/', '4472222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the district court and vacate the decision of the court of appeals.', 'general', 'State of Iowa v. Anthony George Brothern', 'https://www.courtlistener.com/opinion/4472222/', '4472222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that exigent circumstances did not justify the warrant-less search of Kern’s home conducted in this case under both the Fourth Amendment to the United States Constitution *177and article I, section 8 of the Iowa Constitution.', 'search_seizure', 'State of Iowa v. Christine Ann Kern', 'https://www.courtlistener.com/opinion/4472227/', '4472227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Royer, we held that a defendant could not be convicted of manufacturing a controlled substance without actually producing the threshold amount of a controlled substance.', 'general', 'State of Iowa v. Christine Ann Kern', 'https://www.courtlistener.com/opinion/4472227/', '4472227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment and sentence of the district court and remand the case for further proceedings.', 'sentencing', 'State of Iowa v. Christine Ann Kern', 'https://www.courtlistener.com/opinion/4472227/', '4472227') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment and sentence of the district court and remand for a new trial on the count of conspiracy to manufacture a controlled substance.', 'sentencing', 'State of Iowa v. Christine Ann Kern', 'https://www.courtlistener.com/opinion/4472227/', '4472227') ON CONFLICT DO NOTHING;
