INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the conclusion of the jury that a sentence of death was neither excessive nor disproportionate in light of the defendant’s character and his wanton crime.', 'sentencing', 'State v. Copeland', 'https://www.courtlistener.com/opinion/1306039/', '1306039') ON CONFLICT DO NOTHING;
