INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), in which we held that the appellant had waived the right to raise the issue of whether the presiding judge, when presented with a change of judge motion, must recuse himself.', 'general', 'Broome v. State', 'https://www.courtlistener.com/opinion/2229994/', '2229994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the performance of Broome’s attorney was not deficient and was within the range of effective assistance.', 'general', 'Broome v. State', 'https://www.courtlistener.com/opinion/2229994/', '2229994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reason to depart from current Indiana practice in which a presiding judge is not only competent to determine the sufficiency of the affidavits required by the change of judge rule, but also is permitted to hear the motion for change of judge, we conclude that a presiding judge against whom a change of judge motion is directed may, but need not, recuse himself when a hearing on the motion is necessary.', 'general', 'Broome v. State', 'https://www.courtlistener.com/opinion/2229994/', '2229994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Broome’s declaration, in which no reference to an attorney was made, was also not a request for counsel.', 'general', 'Broome v. State', 'https://www.courtlistener.com/opinion/2229994/', '2229994') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence sufficiently overcame Broome’s self-defense claim.', 'general', 'Broome v. State', 'https://www.courtlistener.com/opinion/2229994/', '2229994') ON CONFLICT DO NOTHING;
