INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Miller ⅛ principles are fully applicable to a lengthy term-of-years sentence as was imposed in this case because an offender sentenced to a lengthy term-of-years sentence should not be worse off than an offender sentenced to life in prison without parole who has the benefit of an individualized hearing under Miller.', 'sentencing', 'State of Iowa v. Denem Anthony Null', 'https://www.courtlistener.com/opinion/4472206/', '4472206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we recognized that Roper was a death penalty case, we concluded that the reasoning in Roper, namely, that juveniles are materially different from adults for the *70purposes of assessing criminal culpability, had broad applicability outside the death penalty context.', 'general', 'State of Iowa v. Denem Anthony Null', 'https://www.courtlistener.com/opinion/4472206/', '4472206') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm Null’s conviction, but vacate his sentence and remand the case to the district court for resentencing consistent with this opinion.', 'sentencing', 'State of Iowa v. Denem Anthony Null', 'https://www.courtlistener.com/opinion/4472206/', '4472206') ON CONFLICT DO NOTHING;
