INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that under the totality of the circumstances, as applied to the facts in this case, information provided by the citizen informant alone, with no other objective data, does not support a particularized suspicion that Lee had been engaged in wrongdoing.', 'general', 'State of Iowa v. Leon Kooima', 'https://www.courtlistener.com/opinion/4472214/', '4472214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the ruling of the district court on the motion to suppress and find the stop of Kooima was illegal.', 'suppression', 'State of Iowa v. Leon Kooima', 'https://www.courtlistener.com/opinion/4472214/', '4472214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since either a single blow or a single series of blows caused each serious injury, we find that there were more than two completed *584acts, as Kennedy suffered at least two serious injuries.', 'general', 'State of Iowa v. Valentin Velez', 'https://www.courtlistener.com/opinion/4472247/', '4472247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that under either the completed-acts test or the break-in-the-action test, Velez committed two acts meeting the statutory definition of willful injury.', 'general', 'State of Iowa v. Valentin Velez', 'https://www.courtlistener.com/opinion/4472247/', '4472247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we find that Velez’s counsel was not ineffective for failing to object to the plea on the ground that there was no separate factual basis for a second count of willful injury.', 'plea', 'State of Iowa v. Valentin Velez', 'https://www.courtlistener.com/opinion/4472247/', '4472247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that this answer is contained within the words of the statute.', 'general', 'State of Iowa v. Valentin Velez', 'https://www.courtlistener.com/opinion/4472247/', '4472247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we found that “[t]he crime of exercising control over stolen property is not a continuing offense for double jeopardy purposes,” we further found that the Code “does not proscribe a course of conduct encompassing a series of acts, but rather prohibits a single act of possession of stolen property.', 'general', 'State of Iowa v. Valentin Velez', 'https://www.courtlistener.com/opinion/4472247/', '4472247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that, even though there was not a distinct temporal break in the action, the separate acts involved — hitting the victim and knocking him to the ground, and kicking him when he was on the ground— provided separate factual bases for the two guilty pleas.', 'plea', 'State of Iowa v. Valentin Velez', 'https://www.courtlistener.com/opinion/4472247/', '4472247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that under both the break-in-the-action test and the completed-acts test, Velez committed two or more discrete acts of willful injury.', 'general', 'State of Iowa v. Valentin Velez', 'https://www.courtlistener.com/opinion/4472247/', '4472247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the findings of the district court.', 'general', 'State of Iowa v. Valentin Velez', 'https://www.courtlistener.com/opinion/4472247/', '4472247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals and the judgment of the district court.', 'general', 'State Of Iowa Vs. Robert Joseph Vance', 'https://www.courtlistener.com/opinion/4472492/', '4472492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals and the judgment of the district court because there was reasonable suspicion to initiate an investigatory stop of the vehicle the defendant was driving, and substantial evidence supports his conviction for possession of a precursor product with the intent to manufacture methamphetamine.', 'general', 'State Of Iowa Vs. Robert Joseph Vance', 'https://www.courtlistener.com/opinion/4472492/', '4472492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding neither argument persuasive, we affirm.', 'general', 'Armstead v. Commonwealth', 'https://www.courtlistener.com/opinion/1062142/', '1062142') ON CONFLICT DO NOTHING;
