INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not err by denying Hyde’s motion to suppress evidence obtained after the traffic stop.', 'suppression', 'People v. Hyde', 'https://www.courtlistener.com/opinion/1848153/', '1848153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But even under this more expansive application of the inevitable discovery doctrine, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that because no application of the inevitable discovery doctrine saves the warrantless search, the trial court should have suppressed the evidence of Hyde’s blood sample and test results.', 'suppression', 'People v. Hyde', 'https://www.courtlistener.com/opinion/1848153/', '1848153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances presented here, we conclude that the trial court’s failure to suppress the blood sample evidence was not harmless beyond a reasonable doubt.', 'suppression', 'People v. Hyde', 'https://www.courtlistener.com/opinion/1848153/', '1848153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Despite the evidence presented in the record that could reasonably support a conviction under the first theory of OWI (the officers’ observations, Hyde’s own admissions, Hyde’s slurred speech and failure of two sobriety tests, and the physical beer bottle evidence), we conclude that it would be inconsistent with substantial justice
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse in part and remand.', 'general', 'People v. Hyde', 'https://www.courtlistener.com/opinion/1848153/', '1848153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse in part and remand for entry of an order vacating Hyde’s OWI conviction under the theory that he operated a vehicle “with a bodily alcohol content of 0.', 'general', 'People v. Hyde', 'https://www.courtlistener.com/opinion/1848153/', '1848153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we agree that the trial court erred in denying Smith the opportunity to further cross-examine Walker, we find that the error was harmless beyond a reasonable doubt and affirm on this issue.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1347734/', '1347734') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1347734/', '1347734') ON CONFLICT DO NOTHING;
