INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed, we reverse the judgment of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson, we held that a charge of driving after revocation, there based on failure to produce proof of insurance, was a civil/regulatory offense and consequently not within the state’s jurisdiction to enforce on a reservation.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, it is significant here that in Stone we held that driving without a valid license does not raise policy concerns substantially different from the general policy of public safety and therefore the violation is civil/regulatory.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, in Stone we held that speed limits did not raise heightened public policy concerns and careless and reckless driving did raise those concerns.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Minnesota courts have subject matter jurisdiction to enforce the charge of driving after cancellation as inimical to public safety against Busse even though he is an enrolled tribal member of the White Earth Reservation and committed this offense on that reservation.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the offense of driving after cancellation as inimical to public safety presents substantially different or heightened public policy concerns.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Minn.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, because we conclude that the offense of driving after cancellation as inimical to public safety is criminal/prohibitory and that the state has jurisdiction to enforce it against Busse while on his reservation, Busse’s argument that the charge can never apply to him on the reservation is without merit.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Busse has waived consideration of his equal protection claim.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Busse', 'https://www.courtlistener.com/opinion/1852224/', '1852224') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this sort of mistake "constitutes a compelling equitable consideration under § 806.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But in Phillips we held that the evaluation of the timing of the search vis-à-vis the entry must also consider the conditions existing at the time of the consent.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that even when temporal proximity is very close, "the non-threatening, non-custodial conditions surrounding the search.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Berlin''s entry was justified by the exigent circumstance of hot pursuit.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Focusing on what was known and could reasonably be inferred by the officer at the time of the entry, we conclude that Berlin reasonably believed that the intruder he was pursuing posed a threat to the safety of the occupants of Richter''s trailer.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this information was sufficient to allow Richter to freely consent to the search.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Berlin''s conduct displays the necessary level of purposefulness which is proscribed under the attenuation analysis.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the warrantless entry of the defendant''s home was justified based on the exigent circumstances of hot pursuit and threat *552 to safety and was therefore reasonable under the Fourth Amendment and its Wisconsin counterpart.', 'search_seizure', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the circuit court''s failure to give the parties notice of the entry of the initial final order constituted a "mistake" under Wis.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude the entry was justified by exigent circumstancesspecifically, the deputy''s "hot pursuit" of the burglary suspect and his need to protect the safety of those inside the trailerwe reverse.', 'general', 'State v. Richter', 'https://www.courtlistener.com/opinion/1862237/', '1862237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 239 (1977), this Court held that the defendant had not been unfairly surprised by the fact that a ballistics expert had been left off the list of witnesses, where defense counsel reasonably should have been aware of the state''s proposed proof by reason of information already known to the defendant.', 'general', 'Sireci v. State', 'https://www.courtlistener.com/opinion/1595692/', '1595692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we reverse
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the probation order pursuant to I.', 'general', 'State v. Josephson', 'https://www.courtlistener.com/opinion/1154776/', '1154776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Josephson’s sentence, including the order imposing probation, is not contrary to law.', 'sentencing', 'State v. Josephson', 'https://www.courtlistener.com/opinion/1154776/', '1154776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the order of the district court.', 'general', 'State v. Josephson', 'https://www.courtlistener.com/opinion/1154776/', '1154776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s order denying Rule 35 relief for an illegal sentence.', 'sentencing', 'State v. Josephson', 'https://www.courtlistener.com/opinion/1154776/', '1154776') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 469 (1993), we hold that it was not error to admit that evidence, and affirm Coon''s conviction.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the voice spectrograph analysis evidence was admissible under Daubert and the Alaska Rules of Evidence in this *403 case.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the Frye test potentially excludes evidence that should be admitted under our rules, and also potentially admits evidence that should be excluded under our rules, we conclude that it is both unduly restrictive and unduly permissive.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Just as the Supreme Court concluded in Daubert that the Frye test is inconsistent with the federal evidence rules,[41] we conclude that it is inconsistent with the Alaska Rules of Evidence.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we conclude that the "more good than harm" requirement is also met.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'So arguing, APDA relies on a passage from Pulakis, where we stated that "[o]n the basis of our study of the judicial authority and academic literature in this area, we conclude that the results of polygraph examinations should not be received in evidence over objection.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in finding on remand that this technique has been subjected to empirical testing.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the findings of other courts as to the relevant scientific community for the technique of forensic voice identification using spectrography, we conclude that the trial court did not abuse its discretion in determining the relevant scientific community.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the trial court did not err in finding the voice spectrographic evidence admissible under Daubert.', 'general', 'State v. Coon', 'https://www.courtlistener.com/opinion/1193824/', '1193824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Nunfio, we held that the question "can you be fair and impartial if the victim in this case is a nun?" was a proper question and the trial court erred to prohibit Nunfio''s asking the question.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Abron, we held that the trial court abused its discretion in prohibiting the defendant from asking the venire members whether they would be biased because the defendant was a black man and the victim a white woman.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*41 In Hernandez, we held that the defendant should have been allowed to ask whether venire members could not believe that a police officer would lie.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "a vague question about `what things'' the veniremember thought were important in determining whether an individual should receive a death sentence, wholly unrelated to the sentencing scheme, amounts to a fishing expedition going beyond the scope of proper voir dire.', 'sentencing', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant failed to show a juror had withheld information because defense counsel''s questions had been inadequate.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Standefer we held that "a question is a commitment question if one or more of the possible answers is that the prospective juror would resolve or refrain from resolving an issue in the case on the basis of one or more facts contained in the question.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did not because the question was too vague to constitute a proper question.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the question was a proper one and in a proper form because the defendant was not seeking to commit the venire to a conclusion based on a given set of facts.', 'general', 'Barajas v. State', 'https://www.courtlistener.com/opinion/1891691/', '1891691') ON CONFLICT DO NOTHING;
