INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Liuafi has not clearly demonstrated that the trial court abused its discretion in denying his motion to suppress and admitting his statements at trial.', 'suppression', 'State v. Liuafi', 'https://www.courtlistener.com/opinion/1240919/', '1240919') ON CONFLICT DO NOTHING;
