INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that where the record on appeal is insufficient to demonstrate ineffective assistance of counsel, but where: (1) the defendant alleges facts that if proven would entitle him or her to relief, and (2) the claim is not patently frivolous and without trace of support in the record,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'however, we conclude that: (1) Silva has alleged facts that, if proven, would entitle him to relief, and (2) Silva’s claim is not patently frivolous and without trace of support in the record.', 'general', 'State v. Silva', 'https://www.courtlistener.com/opinion/1199850/', '1199850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although it could be argued that eliciting testimony regarding Miranda’s bad eyesight may have strengthened Silva’s case, on balance, we conclude that defense counsel’s failure to do so does not rise to the level of ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Silva', 'https://www.courtlistener.com/opinion/1199850/', '1199850') ON CONFLICT DO NOTHING;
