INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s dismissal of plaintiffs’ claim for obstruction of justice against defendant.', 'dismissal', 'Burgess v. Busby', 'https://www.courtlistener.com/opinion/1266744/', '1266744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the order of the trial court as to this cause of action.', 'general', 'Burgess v. Busby', 'https://www.courtlistener.com/opinion/1266744/', '1266744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand the trial court’s dismissal under Rule 12 (b)(6) of plaintiffs’ claims for intentional infliction of emotional distress, common law obstruction of justice, and punitive damages.', 'dismissal', 'Burgess v. Busby', 'https://www.courtlistener.com/opinion/1266744/', '1266744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s dismissal of the plaintiffs’ tortious interference with contract claim.', 'dismissal', 'Burgess v. Busby', 'https://www.courtlistener.com/opinion/1266744/', '1266744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s dismissal of plaintiffs’ claim for interference with a fiduciary relationship.', 'dismissal', 'Burgess v. Busby', 'https://www.courtlistener.com/opinion/1266744/', '1266744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The allegations in plaintiffs’ complaint fail to state a claim for intrusive invasion of privacy and we affirm the trial court’s dismissal of this cause of action.', 'dismissal', 'Burgess v. Busby', 'https://www.courtlistener.com/opinion/1266744/', '1266744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s dismissal of plaintiffs’ complaint for unfair and deceptive trade practices.', 'dismissal', 'Burgess v. Busby', 'https://www.courtlistener.com/opinion/1266744/', '1266744') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In review, we affirm the trial court’s dismissal of plaintiffs’ claims for outrage, tortious interference with contract, interference with a fiduciary relationship, intrusive invasion of privacy, and unfair and deceptive trade practices.', 'dismissal', 'Burgess v. Busby', 'https://www.courtlistener.com/opinion/1266744/', '1266744') ON CONFLICT DO NOTHING;
