INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant''s trial was free of reversible error.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was, and that it was properly admitted by the trial court.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the evidence indicated that the incident with Foster occurred some ten weeks after the incident with the victim in this case, we conclude that the remarkably odd and strikingly similar licking modus operandi attributed to the defendant by both women rendered Foster''s testimony relevant and admissible as tending to prove the defendant''s modus operandi, motive, intent, preparation and plan.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, for the limited purposes for which the contested evidence was admitted here, the incident with Foster was not so remote that evidence of it should have been excluded under the Rule 403 balancing test.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in the present case by admitting the testimony of Foster concerning the defendant''s similar crime, wrong, or act against her.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence presented in this case, we conclude that the trial court did not err by failing to instruct on attempted first-degree sexual offense.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the quoted portions of the instructions did not mislead the jury.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 202 (1986), we held that the State had not met its burden of overcoming the presumption of prejudice by showing what occurred when the trial judge answered the jury''s questions because the record was incomplete regarding the trial judge''s actual communication with the jury.', 'general', 'Atkinson v. State', 'https://www.courtlistener.com/opinion/1874985/', '1874985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Goff, supra, on the other hand, this court held that strict compliance with § 16-89-125(e) had not been waived where the State failed to show what occurred during a trial judge''s visit to the jury room.', 'general', 'Atkinson v. State', 'https://www.courtlistener.com/opinion/1874985/', '1874985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we cannot say that the trial court erred in declining to instruct the jury on second-degree murder, and we affirm the trial court on this point.', 'general', 'Atkinson v. State', 'https://www.courtlistener.com/opinion/1874985/', '1874985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the trial court on all points.', 'general', 'Atkinson v. State', 'https://www.courtlistener.com/opinion/1874985/', '1874985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Barrie v. United States', 'https://www.courtlistener.com/opinion/1908960/', '1908960') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that a defendant prosecuted under HRS § 708-836 may assert the mistake-of-fact defense with respect to the authorization element, where he claims that he mistakenly believed that the person who authorized his operation of the vehicle was the vehicle’s registered owner, because such a belief would potentially “negative[] the state of mind required to establish [the authorization] element of the offense.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the record does not reflect whether Lopez received Miranda warnings from Officer Hawkins or any other police officer at the time or after he was arrested, we hold that the right against self-incrimination attached at least as of the time of the arrest,9 “because the right to remain silent derives from the Constitution and not from the Miranda warnings themselves.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that all three factors counsel that the DPA’s improper comments were not harmless beyond a reasonable doubt and, consequently, that Lopez is entitled to a new trial on remand.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Padilla, this court held that, because the defendant invoked an adverse inference with respect to the prosecution’s failure to call a witness, the prosecution was entitled to explain why it had not done so.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, although the defendant did not raise an alibi defense, he did undertake to "explain away” much of the prosecution''s evidence and, consequently, opened the door to the prosecution’s cross-examination and later " ‘comment on the stale of the evidence.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While these cases permit prosecutorial comment on issues raised by the defendant, we conclude that they are distinguishable.', 'general', 'State v. Mainaaupo', 'https://www.courtlistener.com/opinion/2507343/', '2507343') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the police did not need an arrest warrant before arresting Shorty for a felony, and we conclude that there was probable cause for Shorty''s arrest.', 'probable_cause', 'Shorty v. State', 'https://www.courtlistener.com/opinion/2628804/', '2628804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In each of these cases we held that the crimes were sufficiently connected to justify joinder under this subsection.', 'general', 'Shorty v. State', 'https://www.courtlistener.com/opinion/2628804/', '2628804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we reverse Shorty''s conviction for providing false information to a peace officer because we conclude that the trial judge improperly allowed the prosecution to substantively amend that charge at the conclusion of the trial.', 'general', 'Shorty v. State', 'https://www.courtlistener.com/opinion/2628804/', '2628804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Shorty failed to preserve this issue for appeal, and at the very least, he has not shown plain error.', 'general', 'Shorty v. State', 'https://www.courtlistener.com/opinion/2628804/', '2628804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these accounts, we conclude that there was ample evidence to support Shorty''s conviction for resisting arrest.', 'general', 'Shorty v. State', 'https://www.courtlistener.com/opinion/2628804/', '2628804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We REVERSE Shorty''s conviction for giving false information.', 'general', 'Shorty v. State', 'https://www.courtlistener.com/opinion/2628804/', '2628804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm Judge Wol-verton''s conclusion that the police had probable cause to arrest Shorty when they detained him on July 26th.', 'probable_cause', 'Shorty v. State', 'https://www.courtlistener.com/opinion/2628804/', '2628804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM the balance of the superior court''s judgment.', 'general', 'Shorty v. State', 'https://www.courtlistener.com/opinion/2628804/', '2628804') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that this was evidence of actual damages.', 'general', 'Biglane v. Under the Hill Corp.', 'https://www.courtlistener.com/opinion/1800410/', '1800410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case of ACI Chemicals, we affirmed a chancellor''s finding of tortious interference with business relations when a company, after suffering interference from a competitor, no longer received any new orders from a customer;', 'general', 'Biglane v. Under the Hill Corp.', 'https://www.courtlistener.com/opinion/1800410/', '1800410') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the offensive conduct warranting punitive damages is similar to the conduct that would sustain an intentional infliction of emotional distress claim.', 'general', 'Mitchell v. Heinrichs', 'https://www.courtlistener.com/opinion/2593756/', '2593756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we recognize that a pet''s actual value to the owner may exceed its fair market value and include the original cost to the owner or full reasonable replacement costs, we REVERSE the superior court''s dismissal of the case and REMAND to the superior court for trial on the conversion claim and determination of damages based on the principles set out in this opinion.', 'dismissal', 'Mitchell v. Heinrichs', 'https://www.courtlistener.com/opinion/2593756/', '2593756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Richardson, we affirmed a trial judge''s determination that the proper measure of damages was limited to the dog''s fair market value or replacement cost:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM these rulings.', 'general', 'Mitchell v. Heinrichs', 'https://www.courtlistener.com/opinion/2593756/', '2593756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that (1) unlawful police conduct is not a defense to a charge of Hindering Prosecution in the First Degree under HRS § 710-1029, however, (2) there was insufficient evidence to sustain a conviction for such an offense in this ease, and therefore, the April 28, 2009 judgment of the ICA and the March 3, 2006 judgment of conviction of the court are vacated;', 'general', 'State v. Line', 'https://www.courtlistener.com/opinion/2628949/', '2628949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that an illegal arrest did not affect a “resisting arrest charge.', 'general', 'State v. Line', 'https://www.courtlistener.com/opinion/2628949/', '2628949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that "under the circumstances, the constitution does not require the police officers to break off their pursuit to seek a warrant and chance violence or escape by the suspects.', 'general', 'State v. Line', 'https://www.courtlistener.com/opinion/2628949/', '2628949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[c]onsistent with the above precedent, we conclude that Jim’s continuing physical obstruction of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There was no conceivable basis in the law to uphold the entry as valid and so we reverse the court’s conclusion to the contrary.', 'general', 'State v. Line', 'https://www.courtlistener.com/opinion/2628949/', '2628949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“In each case, we concluded that the defendant’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the evidence is sufficient to show that the crime of malicious castration was committed in conjunction with Dowdy’s murder as part of a continuous chain of events, forming one single transaction.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in submitting the charge of first-degree burglary to the jury.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With regard to issues in the portion of the three assignments of error properly before the Court, we hold that the trial court did not err.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With regard to this contention, we hold that the trial court properly instructed the jurors by stating the following: “It is not a proper matter for your consideration in this phase of the trial.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that since the trial court “did not deny defendant the assistance of a second attorney or so drastically circumscribe the second attorney’s role as to render the appointment of two attorneys
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the interval of three and one-half hours between the victim’s death and the setting of the fire did not prevent a finding “based on all the surrounding circumstances that the interval was ‘short’ enough for the arson and the murder to be parts of one continuous transaction.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we conclude that defendant’s trial and capital sentencing proceeding were free of prejudicial error and that the death sentences are not disproportionate.', 'sentencing', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that while there may have been some initial confusion in the trial court’s instruction, the court ultimately set forth the required elements that the jury needed to find to properly determine whether the assault defendant intended to commit at the time he broke and entered Dowdy’s apartment was in fact a felony.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these principles to the instant case, we conclude that the prosecutor’s remarks did not shift the burden of proof in the trial.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the challenged argument in the overall context in which it was made and in view of the overall factual circumstances to which it referred, we conclude that the prosecutor’s argument was a comment on the strength of the State’s evidence and the absence of any contradictory evidence.', 'general', 'State v. Parker', 'https://www.courtlistener.com/opinion/1302596/', '1302596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in determining the validity of an injunction against harassment, the date of service is not included in the “one year” calculation.', 'general', 'State v. LYCHWICK', 'https://www.courtlistener.com/opinion/2595792/', '2595792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1301, we conclude that the date of service is excluded when calculating the injunction’s expiration date.', 'general', 'State v. LYCHWICK', 'https://www.courtlistener.com/opinion/2595792/', '2595792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 16 For the foregoing reasons, we affirm defendant’s conviction and sentence.', 'sentencing', 'State v. LYCHWICK', 'https://www.courtlistener.com/opinion/2595792/', '2595792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that an objective assessment of the facts as found by the district court gave the deputies probable cause to arrest Julian for aggravated battery.', 'probable_cause', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Julian''s arrest was not unlawful.', 'general', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the officer''s decision to cite Julian for domestic battery does not foreclose an inquiry into whether an objective assessment of the facts present at the moment of arrest would lead a person of ordinary prudence to conclude that probable cause existed to arrest Julian for a felony arising from the same operative facts supporting the domestic battery arrest, i.', 'probable_cause', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that probable cause existed to arrest Julian for aggravated battery, the deputies were within the scope of either subsection of the arrest statute when they arrested Julian.', 'probable_cause', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the district court that Julian was not informed of the cause of his arrest.', 'general', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the district court''s order suppressing evidence seized from Julian following his arrest and remand for further proceedings.', 'suppression', 'State v. Julian', 'https://www.courtlistener.com/opinion/1287283/', '1287283') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, this Court holds that police officials may not, without reason, deny access between an accused and his lawyer, when such access is requested and is readily available and will not interfere with investigation of the matter at hand.', 'general', 'State v. Welch', 'https://www.courtlistener.com/opinion/1908211/', '1908211') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1267097/', '1267097') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons articulated above we REVERSE and REMAND.', 'general', 'State v. Scott', 'https://www.courtlistener.com/opinion/1267097/', '1267097') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the PCRA does not impose a more stringent prejudice requirement than that applicable to direct appeals, and we decline to follow the plurality opinion in Buehl.', 'general', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that the PCRA does not create a more stringent standard for prevailing on an ineffectiveness claim, we nevertheless hold that Kimball failed to demonstrate that his trial counsel was ineffective for failing to cross-examine Shortridge concerning bias or for presenting the testimony of Reverend Kimball.', 'ineffective_assistance', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that the trial court erred in disallowing the defense the opportunity to cross-examine the witness concerning the other charges.', 'general', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the introduction of the defendant’s prior crimes to vouch for his credibility was not unreasonable, even if unsuccessful, under the circumstances.', 'general', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, due to the overwhelming evidence against Kimball and his counsel’s otherwise adequate cross-examination of Shortridge, we conclude that counsel’s error does not entitle Kimball to relief.', 'general', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the language of the PCRA does not create a higher burden on a defendant to show ineffective assistance of counsel than the standard for proving ineffectiveness on direct appeal.', 'ineffective_assistance', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, because Kimball failed to establish his counsel’s ineffectiveness pursuant to the standard set forth in Section 9543(a)(2)(ii) of the PCRA, we reverse the Order of the Superior Court and reinstate the Opinion and Order of the PCRA court, denying Kimball relief.', 'ineffective_assistance', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the denial of post-conviction relief and reinstated the judgment of sentence of death.', 'sentencing', 'Commonwealth v. Kimball', 'https://www.courtlistener.com/opinion/1906975/', '1906975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we hold that Idaho Code § 18-920(1), as it existed at the time of the offense in this case, provided only for the issuance of a no contact order as a condition of pre-trial release.', 'general', 'State v. Jeppesen', 'https://www.courtlistener.com/opinion/2602403/', '2602403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we hold that the magistrate judge did not err by admitting the letters in the sentencing hearing.', 'sentencing', 'State v. Jeppesen', 'https://www.courtlistener.com/opinion/2602403/', '2602403') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the result), this Court held that it was error to admit a letter in the sentencing hearing on a first degree murder ease.', 'sentencing', 'State v. Jeppesen', 'https://www.courtlistener.com/opinion/2602403/', '2602403') ON CONFLICT DO NOTHING;
