INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of conviction entered by the district court and remand for a new trial.', 'general', 'State v. Gansz', 'https://www.courtlistener.com/opinion/1755908/', '1755908') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the amendment of an indictment did not prejudice the defendant because “his defense at trial was a total denial that the incident ever occurred.', 'general', 'Dahl v. State', 'https://www.courtlistener.com/opinion/1910229/', '1910229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record is insufficient to support Dahl’s allegations of prejudice resulting from the amendment of the indictment.', 'general', 'Dahl v. State', 'https://www.courtlistener.com/opinion/1910229/', '1910229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the district court correctly instructed the jury as to the elements the state was required to prove in order for the jury to find Ruel guilty of the offense charged.', 'general', 'State v. Ruel', 'https://www.courtlistener.com/opinion/2590788/', '2590788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instructions correctly outlined the elements of the offense charged against Ruel.', 'jury_instruction', 'State v. Ruel', 'https://www.courtlistener.com/opinion/2590788/', '2590788') ON CONFLICT DO NOTHING;
