INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that Bur-cina’s plea of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that any claims for injuries unrelated to the arson conviction are not properly before this court.', 'general', 'Burcina v. City of Ketchikan', 'https://www.courtlistener.com/opinion/2607088/', '2607088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Adkinson, who was convicted of manslaughter for shooting and killing a person with a shotgun, had no claim for relief in tort against either the manufacturer or the seller of the shotgun.', 'general', 'Burcina v. City of Ketchikan', 'https://www.courtlistener.com/opinion/2607088/', '2607088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 660, 663 (Alaska 1991), we held that Lord, who was convicted of kidnapping, rape and assault which took place after he was served more than fourteen drinks at the Fogcutter Bar, was precluded from recovering in tort against the Fogcutter Bar.', 'general', 'Burcina v. City of Ketchikan', 'https://www.courtlistener.com/opinion/2607088/', '2607088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 280 (Alaska 1995), we held that Beilgard, who was convicted of violating Alaska’s game laws after requesting information and assistance from State employees as to what permits were required for his business, possessed no viable claim for relief in tort against the State.', 'general', 'Burcina v. City of Ketchikan', 'https://www.courtlistener.com/opinion/2607088/', '2607088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '9 (Alaska 1992), we held that AS 09.', 'general', 'Burcina v. City of Ketchikan', 'https://www.courtlistener.com/opinion/2607088/', '2607088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 4 (Alaska 1979), we held that an issue was not properly before our court where the issue was not properly raised or briefed at the superior court level and was not included in the statement of points on appeal.', 'general', 'Burcina v. City of Ketchikan', 'https://www.courtlistener.com/opinion/2607088/', '2607088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that the public policy principle enunciated in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the public policy principle which precludes a person who has been convicted of a crime from imposing liability on others for the consequences of his or her own antisocial conduct applies here.', 'general', 'Burcina v. City of Ketchikan', 'https://www.courtlistener.com/opinion/2607088/', '2607088') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district judge’s decision denying Workman’s request for counsel and dismissing his petition for post-conviction relief.', 'dismissal', 'Workman v. State', 'https://www.courtlistener.com/opinion/2631111/', '2631111') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), we conclude that the district court did not abuse its discretion in declining to reduce the sentence earlier pronounced.', 'sentencing', 'State v. Marks', 'https://www.courtlistener.com/opinion/2607657/', '2607657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Marks', 'https://www.courtlistener.com/opinion/2607657/', '2607657') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today we hold that one may be convicted as an accomplice to a negligent homicide and therefore affirm Nelson’s conviction and sentence.', 'sentencing', 'State v. Nelson', 'https://www.courtlistener.com/opinion/2632509/', '2632509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the construction given in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 19 We hold that a person may be convicted as an accomplice to an offense with a culpable mental state of criminal negligence.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/2632509/', '2632509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004), this court held that accomplice liability could attach to crimes for which the required mental state was recklessness, but we specifically left open for another day whether the same rule applies to a crime based on negligence.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/2632509/', '2632509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that attempted reckless manslaughter and attempted negligent homicide are not cognizable offenses.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/2632509/', '2632509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the Alaska court, we concluded that the “with the intent to promote or facilitate the commission of an offense” language in the definition of accomplice in A.', 'general', 'State v. Nelson', 'https://www.courtlistener.com/opinion/2632509/', '2632509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under the facts of this ease, Trooper Hazelaar could order Erickson out of the car.', 'general', 'Erickson v. State', 'https://www.courtlistener.com/opinion/2633580/', '2633580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that Trooper Hazelaar did not have a sufficient basis to conduct a pat-down search.', 'general', 'Erickson v. State', 'https://www.courtlistener.com/opinion/2633580/', '2633580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that Trooper Hazelaar could order Erickson out of the car
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that we do not need to decide this issue.', 'general', 'Erickson v. State', 'https://www.courtlistener.com/opinion/2633580/', '2633580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Hopwood did not err in concluding that Trooper Hazelaar had legitimate ease-specific reasons for ordering Erickson out of the car.', 'general', 'Erickson v. State', 'https://www.courtlistener.com/opinion/2633580/', '2633580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that Judge Hopwood erred in finding that Trooper Hazelaar could conduct a pat-down search of Erickson
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the information that Trooper Hazelaar had was sufficient to allow him to order Erickson to get out of the car, we do not believe that the record shows that the trooper had sufficient reason to conduct a pat-down search for weapons.', 'general', 'Erickson v. State', 'https://www.courtlistener.com/opinion/2633580/', '2633580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, because the officer had a reasonable suspicion that Brown was involved in a burglary, which was a felony under Alaska law, it was reasonable for him to “fear that someone suspected of burglary would carry a weapon and resort to violence.', 'general', 'Erickson v. State', 'https://www.courtlistener.com/opinion/2633580/', '2633580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the officer had not given “a convincing reason why he thought Adams might be armed and dangerous” and held that the officer had no basis to conduct a pat-down search.', 'general', 'Erickson v. State', 'https://www.courtlistener.com/opinion/2633580/', '2633580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and that the court’s allowing the comment would have made no difference in the verdict, we conclude that the trial court did not abuse its discretion in ruling as it did.', 'general', 'State v. Davidson', 'https://www.courtlistener.com/opinion/1578687/', '1578687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Davidson', 'https://www.courtlistener.com/opinion/1578687/', '1578687') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we find that appellant has not carried his burden of proving that section 5-54-103(b) unconstitutionally violated his freedom of speech rights, as it is written or as it was applied in this case.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/2457135/', '2457135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Yoder, we held that "[t]he description must be sufficiently clear so that the property to be searched is recognizable from other neighboring properties.', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 647 (1979), we held that a district court erred "in quashing a search warrant where the house to be searched was described by an erroneous house number, but was further identified by additional physical features contained in the warrant.', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 523 (1974), where this Court held that where the police stop and surround the occupant of an automobile, they are "seizing" him within the meaning of the Fourth Amendment.', 'search_seizure', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The possibility of a mistaken identification being minimal, we conclude that the description in the warrant is sufficient.', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the nature of marijuana as a substance which can be easily concealed and moved about and the relatively brief surveillance of defendant''s residence during the period of forty-two days from the date of the first purchase to the time of the application for search warrant (three brief incidents in a period of eleven days followed by thirty-one days of no surveillance whatever), we conclude that the three purchases at defendant''s residence, as the only facts known to the affiant Bridg...', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Here, we need not be concerned with the adequacy of the showing of the reliability of Bowers (as the source of hearsay information to the affiant Bridges) because we conclude that, in any event, the hearsay information itself failed to provide any facts, additional to the facts known to the affiant (the three prior purchases), which, taken in conjunction with the three prior purchases, would be adequate to show the requisite probable cause for issuance of a search warrant.', 'probable_cause', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 671 (1978), we affirmed a trial court''s suppression of evidence which was based, among other things, on the police officers'' failure to comply with the Idaho knock and announce statutes, I.', 'suppression', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That evidentiary finding was found by the Court to be sustained by the appeal record, and on that basis we affirmed.', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Coleman was not denied effective assistance of counsel for any of these reasons.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2608557/', '2608557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 348 (1977), in which we held that the societal interests violated by the crimes of rape and assault with a dangerous weapon are sufficiently distinct, even where the offenses are intertwined in a single episode of violence toward another person, to justify separate sentences.', 'sentencing', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2608557/', '2608557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 621, 629 (Alaska 1978), we concluded that the trial court had not abused its discretion in denying a severance for trial motion pertaining to two alleged rapes which had occurred 19 days apart, and indicated that if the counts had been tried separately, the facts pertaining to the count not charged could have been properly introduced for the purpose of showing the common identity of the attacker.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2608557/', '2608557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, even accepting appellant’s premise, we find that the trial court judge did not follow the course laid out by Standards 7.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2608557/', '2608557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both convictions as well as the sentences which were imposed.', 'sentencing', 'Coleman v. State', 'https://www.courtlistener.com/opinion/2608557/', '2608557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that while the police statements may have amounted to coercion, the failure to suppress the defendant''s response was harmless.', 'suppression', 'State v. Ault', 'https://www.courtlistener.com/opinion/1211385/', '1211385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 545 (1986), we reversed appellant''s convictions for second degree burglary, A.', 'general', 'State v. Ault', 'https://www.courtlistener.com/opinion/1211385/', '1211385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm our earlier reversal of appellant''s convictions but issue this supplemental opinion to clarify our reasons for doing so.', 'general', 'State v. Ault', 'https://www.courtlistener.com/opinion/1211385/', '1211385') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'indeed, this Court holds the video was of no probative value to the State''s case.', 'general', 'Holland v. State', 'https://www.courtlistener.com/opinion/1784340/', '1784340') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the video''s content as well as all the horrific and overwhelming evidence presented in this case, this Court holds that the video was not prejudicial.', 'general', 'Holland v. State', 'https://www.courtlistener.com/opinion/1784340/', '1784340') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, this Court holds that the evidence presented was sufficient to convince a rational factfinder of Holland''s guilt of capital murder and the underlying crime of rape beyond a reasonable doubt.', 'general', 'Holland v. State', 'https://www.courtlistener.com/opinion/1784340/', '1784340') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in the proceedings below, we affirm.', 'general', 'Holland v. State', 'https://www.courtlistener.com/opinion/1784340/', '1784340') ON CONFLICT DO NOTHING;
