INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Loring, we conclude that Inman was not sufficiently prejudiced to warrant the grant of a mistrial.', 'mistrial', 'State v. Inman', 'https://www.courtlistener.com/opinion/2510122/', '2510122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the facts of the instant case, we find that Inman’s guilty plea was unconditional.', 'plea', 'State v. Inman', 'https://www.courtlistener.com/opinion/2510122/', '2510122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Inman’s guilty plea and sentences.', 'sentencing', 'State v. Inman', 'https://www.courtlistener.com/opinion/2510122/', '2510122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, this Court holds that Weick’s failure to attend the May 13 debtor’s exam violated Judge Mitchell’s first order and made him liable for criminal contempt.', 'general', 'Watson v. Weick', 'https://www.courtlistener.com/opinion/2510302/', '2510302') ON CONFLICT DO NOTHING;
