INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that it was an abuse of discretion and reversible error for the court to refuse to question, individually, those jurors who had disclosed relationships or close associations with law enforcement officers, or alternatively, to excuse them.', 'general', 'State v. Ashcraft', 'https://www.courtlistener.com/opinion/1343901/', '1343901') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, because the trial court abused its discretion in denying the appellant’s request for individual voir dire of the jury panel, we reverse the appellant’s conviction, and remand this case for proceedings consistent with this opinion.', 'general', 'State v. Ashcraft', 'https://www.courtlistener.com/opinion/1343901/', '1343901') ON CONFLICT DO NOTHING;
