INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'None of these claims justify reversal and, accordingly, we affirm.', 'general', 'State v. Rathburn', 'https://www.courtlistener.com/opinion/1917234/', '1917234') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that sufficient evidence was presented to sustain Koonce’s conviction and that the CAC Tape was adopted as sworn testimony, and thus properly admitted at trial.', 'general', 'Koonce v. United States', 'https://www.courtlistener.com/opinion/1917294/', '1917294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the trial court did not commit clear error when it admitted into evidence those portions of the CAC Tape which S.', 'general', 'Koonce v. United States', 'https://www.courtlistener.com/opinion/1917294/', '1917294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that prior abuse evidence may be admitted under this narrow exception if (1) the sexual abuse involves a defendant and the same victim;', 'general', 'Koonce v. United States', 'https://www.courtlistener.com/opinion/1917294/', '1917294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, we held that “[b]ecause [she] testified, after being impeached with the .', 'general', 'Koonce v. United States', 'https://www.courtlistener.com/opinion/1917294/', '1917294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In essence, we held that the history of continuing conduct was admissible only to place the charged incidents of abuse in an understandable context.', 'general', 'Koonce v. United States', 'https://www.courtlistener.com/opinion/1917294/', '1917294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we also hold that the Maryland incident was wrongly admitted, prejudicing Koonce, we reverse and remand for a new trial.', 'general', 'Koonce v. United States', 'https://www.courtlistener.com/opinion/1917294/', '1917294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Koonce’s conviction for first-degree child sexual abuse and remand the case for a new trial.', 'general', 'Koonce v. United States', 'https://www.courtlistener.com/opinion/1917294/', '1917294') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'follow, we reverse the judgment of the Appellate Division and reinstate defendant’s convictions and sentence.', 'sentencing', 'State v. Robinson', 'https://www.courtlistener.com/opinion/1539942/', '1539942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that assault inflicting serious bodily injury, the offense for which the defendant was convicted, is not a lesser-included offense of assault with a deadly weapon with intent to kill and inflict serious injury, the offense charged in the indictment;', 'general', 'State v. Hannah', 'https://www.courtlistener.com/opinion/1306187/', '1306187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was substantial evidence that defendant committed the crimes of which he was convicted, irrespective of defendant’s drug use.', 'general', 'State v. Hannah', 'https://www.courtlistener.com/opinion/1306187/', '1306187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant is entitled to a new trial on the felonious assault, and we find no error of his conviction of first-degree burglary.', 'general', 'State v. Hannah', 'https://www.courtlistener.com/opinion/1306187/', '1306187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that all of the essential elements of assault inflicting serious bodily injury are not fully embraced in the offense with which defendant was charged in the indictment, assault with a deadly weapon with intent to kill and inflict serious injury;', 'general', 'State v. Hannah', 'https://www.courtlistener.com/opinion/1306187/', '1306187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the relevant statutes and case law, we conclude that “serious bodily injury” requires proof of more severe injury than the “serious injury” element of the indicted offense.', 'general', 'State v. Hannah', 'https://www.courtlistener.com/opinion/1306187/', '1306187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, because the element of “serious bodily injury” requires proof of more severe injury than the element of “serious injury”, assault inflicting serious bodily injury is not a lesser-included offense of assault with a deadly weapon with intent to kill and inflict serious injury.', 'general', 'State v. Hannah', 'https://www.courtlistener.com/opinion/1306187/', '1306187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no evidence of the lesser included offense, and further conclude that the trial court did not err in declining to instruct on misdemeanor breaking and entering as a lesser included offense of first-degree burglary.', 'general', 'State v. Hannah', 'https://www.courtlistener.com/opinion/1306187/', '1306187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the evidence of defendant’s prior drug use was admissible under Rule 404(b).', 'general', 'State v. Hannah', 'https://www.courtlistener.com/opinion/1306187/', '1306187') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the foregoing reasons, we hold that a reversal of Vance’s conviction for third-degree assault is necessary.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moore, we held that harmless error analysis is not applicable when the defendant is deprived of the right to have the jury determine that every element of the charged offense has been established.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Ihle, we held that jury instructions that omitted an element of the offense did not meet the third prong of the plain error test because there was “no *661reasonable likelihood that a more accurate instruction would have changed the outcome.', 'jury_instruction', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Baird, for example, we held that a jury instruction that erroneously stated that the defendant, who claimed self defense, had a duty to retreat from his home met the third prong of the plain error test.', 'jury_instruction', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If the three prongs of the plain error test are met, we may reverse if we conclude that reversal is required to ensure fairness and the integrity of the judicial proceedings.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that by omitting CRIMJIG 13.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we conclude that by instructing the jury that “it is not necessary for the State to prove that [Vance] intended to inflict substantial bodily harm” (emphasis added), the court gave the jury the opposite impression, namely that intent to harm did not have to be proven, and that intent to commit the act that resulted in the harm was enough.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the instructions the district court gave to the jury were erroneous because they created the possibility that the jury convicted Vance without finding that he intended to cause bodily harm.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that such an argument is more appropriately considered under the third prong of the plain error test, as the legal issue that is arguably unclear is whether jury instructions that omit an element of the crime can ever be harmless.', 'jury_instruction', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the district court committed plain error when it failed to instruct the jury on the intent element of the crime of third-degree assault.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1740020/', '1740020') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'IT IS HEREBY ORDERED that Francis Honrath, Attorney at Law, Inwood, Iowa, be and he is hereby allowed fees for services and advances on behalf of the defendant in this matter in the amount of $1,079.', 'general', 'State v. Iowa District Court for Lyon County', 'https://www.courtlistener.com/opinion/2177252/', '2177252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that there was a stipulation, and relied on such stipulation as a main predicate of the Court’s opinion.', 'general', 'Stuart v. State', 'https://www.courtlistener.com/opinion/1442563/', '1442563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’ We conclude that under State v.', 'general', 'Stuart v. State', 'https://www.courtlistener.com/opinion/1442563/', '1442563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Guidelines'' standard for the consideration of hearsay testimony at sentencing meets the appropriate constitutional test and fulfills the Confrontation Clause''s basic purpose of promoting the integrity of the factfinding process.', 'sentencing', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we held that the sentencing court may properly consider "uncorroborated hearsay evidence that the defendant has had an opportunity to explain or rebut.', 'sentencing', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the enactment of the Guidelines has not so transformed the sentencing phase that it constitutes a separate criminal proceeding.', 'sentencing', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Sexson''s hearsay testimony was sufficiently reliable to support the district court''s finding that Wise had indeed been an organizer or leader of a criminal activity that involved five or more persons.', 'general', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, although we do not endorse the manner in which it was conducted, we conclude that the hearing did not deprive Wise of due process.', 'general', 'United States v. James Michael Wise', 'https://www.courtlistener.com/opinion/591441/', '591441') ON CONFLICT DO NOTHING;
