INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defining a substantial risk as one “different in kind” from the merely unreasonable risk sufficient for civil negligence best serves the purpose of circumscribing recklessness in such a manner that a fact-finder will not be misled into criminalizing conduct which is only civilly negligent.', 'general', 'In Re William G.', 'https://www.courtlistener.com/opinion/1348425/', '1348425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in the circumstances of this case, or cases closely analogous, the civil rule is what the legislature intended to incorporate by its reference to a standard of conduct.', 'general', 'In Re William G.', 'https://www.courtlistener.com/opinion/1348425/', '1348425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that the evidence in this case is wholly inadequate to support a finding of recklessness.', 'general', 'In Re William G.', 'https://www.courtlistener.com/opinion/1348425/', '1348425') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse the finding of delinquency.', 'general', 'In Re William G.', 'https://www.courtlistener.com/opinion/1348425/', '1348425') ON CONFLICT DO NOTHING;
