INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that time spent subject to electronic monitoring at home is not time spent in "custody" for purposes of credit under Section 9760.', 'general', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Superior Court erred as a matter of law in remanding this case to the PCRA Court for further evidentiary hearings, based on the Chiappini lead opinion''s case-by-case approach.', 'general', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this Court held that Kriston was entitled to credit against a required prison sentence for the time he spent on electronic monitoring, essentially, as an equitable matter.', 'sentencing', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the trial court did have such discretionary power.', 'general', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we find that appellee is not entitled to sentencing credit toward his prison sentence for time he spent at home on bail subject to electronic monitoring.', 'sentencing', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Superior Court''s remand order and reinstate the order of the PCRA court, denying relief.', 'general', 'Commonwealth v. Kyle', 'https://www.courtlistener.com/opinion/1931189/', '1931189') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a trooper with two years experience as a crime scene investigator, but only two days training in blood-spatter analysis, qualified as an expert.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/1931448/', '1931448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the instruction on accomplice liability was appropriate, and if properly qualified, an expert may give gang-related testimony.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/1931448/', '1931448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/1931448/', '1931448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the expert gang-related evidence offered by Vazquez related to the hierarchy, organization, and discipline of the MS-13 gang was sufficiently reliable to satisfy the second requirement for its admissibility.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/1931448/', '1931448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the testimony of Vazquez did not compromise defendant’s confrontation rights and was properly admitted.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/1931448/', '1931448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the trial court did not abuse its discretion in finding Vazquez was qualified as an expert and that his testimony would be helpful for the jury to understand the issues in the case.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/1931448/', '1931448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although portions of the expert’s testimony may have been based on interviews of other gang members, we find that source, along with the other sources used by Vazquez, was sufficiently reliable to overcome defendant’s hearsay complaint.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/1931448/', '1931448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s admission of Vazquez’s expert testimony.', 'general', 'State v. Torres', 'https://www.courtlistener.com/opinion/1931448/', '1931448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*58Based on the foregoing, we find that the DPA’s questions and remarks did not constitute misconduct.', 'general', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the circuit court’s judgment of conviction and sentence.', 'sentencing', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the foregoing considerations, we affirm the denial of Hauge’s motion to suppress on the narrow ground that Hauge’s blood was initially drawn pursuant to a lawful warrant for DNA comparison and identification purposes in connection with the robbery investigation and that the blood sample was only used in connection with the burglary investigation giving rise to the present matter for the same DNA comparison and identification purposes.', 'suppression', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we affirm the circuit court’s judgment of conviction and sentence.', 'sentencing', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the circuit coart’s improper comment on the evidence did not amount to reversible error or grounds for a new trial, inasmuch as the court’s jury instruction was sufficiently curative.', 'jury_instruction', 'State v. Hauge', 'https://www.courtlistener.com/opinion/2520889/', '2520889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the nonsectarian, nonprofit hospital which held out the use of its facilities to the general public assumed quasi public *581 obligations akin to those assumed by common carriers and innkeepers at common law.', 'general', 'State v. Schmid', 'https://www.courtlistener.com/opinion/2000388/', '2000388') ON CONFLICT DO NOTHING;
