INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Act does not violate procedural due process or separation of powers and, as against these challenges, is constitutional.', 'general', 'Milks v. State', 'https://www.courtlistener.com/opinion/1940334/', '1940334') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[8]  In Robinson, this Court held that application of the Act to a person convicted of a crime that concededly involved no sexual component violated substantive due process.', 'general', 'Milks v. State', 'https://www.courtlistener.com/opinion/1940334/', '1940334') ON CONFLICT DO NOTHING;
