INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below, we hold that the sexual offender registration requirement is a collateral consequence of the plea, and therefore failure to inform the defendant of that requirement before he entered the plea does not render his plea involuntary.', 'plea', 'State v. Partlow', 'https://www.courtlistener.com/opinion/1894393/', '1894393') ON CONFLICT DO NOTHING;
