INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we recognized that deportation may be a severe consequence, we held that because the possibility of deportation was collateral, defense counsel was not ineffective for failing to advise his client about it.', 'ineffective_assistance', 'State v. Partlow', 'https://www.courtlistener.com/opinion/1894393/', '1894393') ON CONFLICT DO NOTHING;
