INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" From this, we conclude that defendant killed both of the victims to eliminate them as witnesses to the robbery.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Judge Scholl''s findings at the sentencing hearing were based on relevant evidence presented at defendant''s trial, as well as at the sentencing hearing.', 'sentencing', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We find that Judge Scholl, for purposes of aggravation, properly considered the presentence report as to all counts except for the murder counts and, as A.', 'sentencing', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the victims were helpless and the defendant relished the murders.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the facts in this case, we find that the record supports the trial court''s finding that the murders were committed in an especially heinous or depraved manner.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*173 Based upon our review of these decisions, we find that the imposition of the death penalty in this case is proportional to the sentences imposed in similar cases.', 'sentencing', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Walton, we found that the defendant relished the murder because he said that he had "never seen a man pee in his pants before.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gillies, we found that the extent and duration of defendant''s participation in the crime minimized the impact of his youth as a mitigating factor.', 'general', 'State v. Greenway', 'https://www.courtlistener.com/opinion/1150904/', '1150904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these facts, we conclude that appellant was not improperly induced into waiving his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence offered at trial, we conclude that the prosecutor’s comments were not delivered in an effort to appeal to the sympathies of the jury.', 'general', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these factual findings and credibility determinations by the trial court, which are supported by the record, we conclude that appellant was properly advised by his trial counsel on whether to testify and that appellant freely chose not to testify.', 'general', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this evidence, we conclude that the prosecutor did not ask the jury to find appellant guilty simply because he was from Philadelphia.', 'general', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these factual findings by the trial court, which are supported by the record, we conclude that trial counsel employed a reasonable trial strategy for not presenting evidence of appellant’s employment record since it would have disclosed that appellant did not have a substantial employment history and that he engaged in illegal activities while at one position.', 'general', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record below, we conclude that the sentence imposed was not the product of passion, prejudice or any other arbitrary factor, but rather was based upon the evidence that appellant killed the victim with premeditation and malice aforethought during the commission of a robbery.', 'sentencing', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that this evidence is sufficient to establish that appellant acted with malice aforethought and with the specific intent to kill the victim.', 'general', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Also, we find that appellant knowingly, intelligently and voluntarily waived his right to have counsel present.', 'general', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the prosecutor’s reference to appellant’s “cold heart” was proper argument since he was merely arguing a reasonable inference which could be drawn from the evidence.', 'general', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this evidence, which counters any educational advancements appellant may have achieved at Glen Mills School, we find that counsel had a reasonable basis aimed at protecting appellant’s interests in not presenting evidence of appellant’s educational history.', 'general', 'Commonwealth v. Hall', 'https://www.courtlistener.com/opinion/1927414/', '1927414') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the totality of the circumstances test the out-of-court identification of defendant was not so impermissibly suggestive as to violate defendant’s constitutional right to due process of law.', 'general', 'State v. Mobley', 'https://www.courtlistener.com/opinion/1216609/', '1216609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 262 (1978), this Court held that not every prejudicial statement by a juror would entitle the defendant to a new trial.', 'general', 'State v. Mobley', 'https://www.courtlistener.com/opinion/1216609/', '1216609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this Court held that the statement was not so prejudicial as to warrant a new trial because there was nothing in the record to show the defendant was prevented from questioning the jurors on
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and the legal and factual realities of law enforcement, we hold that no reasonable fact finder could conclude that Officer Schuppan acted as an unreasonable peace officer of substandard prudence by not arresting Mr.', 'general', 'Keehn v. Town of Torrington', 'https://www.courtlistener.com/opinion/1349067/', '1349067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the facts of the instant case in light of the foregoing discussion and the applicable standard of review, we conclude that the trial court did not err in granting summary judgment.', 'general', 'Keehn v. Town of Torrington', 'https://www.courtlistener.com/opinion/1349067/', '1349067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Seppi, we held that the trial court should instruct the jury on the consequences of the special findings which they make in their verdict.', 'general', 'Ross v. Coleman Co., Inc.', 'https://www.courtlistener.com/opinion/1366472/', '1366472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[13]  In Odenwalt, this Court held that the legislature, in enacting I.', 'general', 'Ross v. Coleman Co., Inc.', 'https://www.courtlistener.com/opinion/1366472/', '1366472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred in overruling the jury''s verdict, imputing Coast''s negligence to Coleman, and accordingly we reverse.', 'general', 'Ross v. Coleman Co., Inc.', 'https://www.courtlistener.com/opinion/1366472/', '1366472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any issue of parent-subsidiary liability was subsumed by Instruction No.', 'general', 'Ross v. Coleman Co., Inc.', 'https://www.courtlistener.com/opinion/1366472/', '1366472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court''s award of costs and attorney fees in this case was erroneous for several reasons and, accordingly, we reverse.', 'general', 'Ross v. Coleman Co., Inc.', 'https://www.courtlistener.com/opinion/1366472/', '1366472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all the reasons set out above, we conclude that the trial court erred egregiously in imposing sanctions against the defendants in this matter, and the order awarding $100,000 attorney fees and $17,000 costs is set aside.', 'general', 'Ross v. Coleman Co., Inc.', 'https://www.courtlistener.com/opinion/1366472/', '1366472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such inventory search, when made to safeguard property for the benefit of owner, police, and tow company, and not under pretext to gather evidence without a warrant, is reasonable and not violative of Fourth Amendment rights.', 'search_seizure', 'Lively v. State', 'https://www.courtlistener.com/opinion/1937398/', '1937398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the burden was upon the defendant to establish that he possessed a license to carry a concealed deadly weapon.', 'general', 'Lively v. State', 'https://www.courtlistener.com/opinion/1937398/', '1937398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence, viewed in its entirety and including all reasonable inferences, was amply sufficient to warrant a finding by the jury that the charge was established beyond a reasonable doubt.', 'general', 'Lively v. State', 'https://www.courtlistener.com/opinion/1937398/', '1937398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Lively v. State', 'https://www.courtlistener.com/opinion/1937398/', '1937398') ON CONFLICT DO NOTHING;
