INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 563 (1986), this Court held that a confession given after a defendant invokes his right to counsel need not be suppressed where the defendant: “(1) initiated ‘further communication, exchanges, or conversations with the police’, and (2) knowingly and intelligently waived the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the charges of robbery and aggravated assault made it apparent to the defense that the Commonwealth was proceeding on the aggravating circumstance of other felony offenses committed in conjunction with the murder.', 'general', 'Commonwealth v. Edwards', 'https://www.courtlistener.com/opinion/1443904/', '1443904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that the evidence presented in each case was sufficient to support the jury’s finding of two aggravating circumstances as to all threé victims — appellant knowingly created a grave risk of death to another person in addition to the victim (42 Pa.', 'general', 'Commonwealth v. Edwards', 'https://www.courtlistener.com/opinion/1443904/', '1443904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no merit to the issues raised by appellant, we affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Edwards', 'https://www.courtlistener.com/opinion/1443904/', '1443904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the verdict, the sentences of death, and the lesser sentences imposed.', 'sentencing', 'Commonwealth v. Edwards', 'https://www.courtlistener.com/opinion/1443904/', '1443904') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this definition to the facts before us, we conclude that Zambrana’s actions constituted Sexual Solicitation of a Child.', 'general', 'Zambrana v. State', 'https://www.courtlistener.com/opinion/2813654/', '2813654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the term “depiction” has multiple definitions, we find that for the purposes of § 1112A, “depiction” encompasses not only tangible manifestations such as photographs and videos, but also includes live conduct.', 'general', 'Zambrana v. State', 'https://www.courtlistener.com/opinion/2813654/', '2813654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Zambrana v. State', 'https://www.courtlistener.com/opinion/2813654/', '2813654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon consideration of the facts and legal principles pertinent to these issues, we affirm.', 'general', 'Guyer v. State', 'https://www.courtlistener.com/opinion/1947529/', '1947529') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the nurse was acting in concert with law enforcement in questioning the child and her parents to gather information for a potential criminal prosecution, we conclude that their statements to the nurse were testimonial under Crawford v.', 'general', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/1942590/', '1942590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Shulman''s testimony on the State''s ability to establish the elements of the crime, we conclude that this finding is sufficiently specific for purposes of our review.', 'general', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/1942590/', '1942590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s repetition of the "boilerplate language of the statute" is insufficient.', 'general', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/1942590/', '1942590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Ms.', 'general', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/1942590/', '1942590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the State has failed to show beyond a reasonable doubt that the error in admitting Ms.', 'general', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/1942590/', '1942590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse Mr.', 'general', 'Hernandez v. State', 'https://www.courtlistener.com/opinion/1942590/', '1942590') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"Accordingly, we hold that murder by means of torture under section 189 is murder committed with a wilful, deliberate, and premeditated intent to inflict extreme and prolonged pain.', 'general', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') Again, we held that `the evidence in the instant case shows only an explosion of violence without the necessary intent that the victim shall suffer.', 'general', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this evidence of brutal treatment of the victim and appellant''s sadistic treatment of others, we conclude that there was more than enough evidence presented to justify a murder by torture instruction to the jury.', 'general', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Wingo, supra, we find that there was no denial of appellant''s right to a speedy trial.', 'general', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the nature of the crime committed and the character of the defendant, we find that the sentence imposed in this case is not disproportionate to that imposed in other first degree murder cases.', 'sentencing', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1]  The Court''s order of September 20, 1985, stated: "IT IS HEREBY ORDERED that Appellant''s PETITION FOR REHEARING be, and hereby is, GRANTED only as to the single issue of Jury Instruction Number 18 concerning proof of intent and is hereby DENIED as to all other issues raised by Appellant.', 'jury_instruction', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Stuart', 'https://www.courtlistener.com/opinion/1387737/', '1387737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Kenneth Griesemer v. State of Indiana', 'https://www.courtlistener.com/opinion/2784230/', '2784230') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth in this opinion, we affirm the trial court.', 'general', 'Kenneth Griesemer v. State of Indiana', 'https://www.courtlistener.com/opinion/2784230/', '2784230') ON CONFLICT DO NOTHING;
