INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we affirm the order of the Superior Court.', 'general', 'Commonwealth v. Grant', 'https://www.courtlistener.com/opinion/2275598/', '2275598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that in a criminal trial, after a pretrial hearing and order which overrules a defendant’s motion to suppress his statement, the defendant must object at trial to the receipt of the statement in order to preserve the question for review on appeal.', 'suppression', 'State v. Pointer', 'https://www.courtlistener.com/opinion/1637141/', '1637141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that in a criminal case where a defendant has filed a timely pretrial motion to suppress physical evidence and the motion is denied after hearing, an objection at trial is not essential to preserve the question for review on appeal.', 'suppression', 'State v. Pointer', 'https://www.courtlistener.com/opinion/1637141/', '1637141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We affirm.', 'general', 'State v. Pointer', 'https://www.courtlistener.com/opinion/1637141/', '1637141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred in not instructing the jury on the lesser-included offense of negligent child abuse.', 'general', 'State v. Molina', 'https://www.courtlistener.com/opinion/1749529/', '1749529') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that this principle applied where new appellate counsel could have raised the ineffectiveness of trial counsel.', 'ineffective_assistance', 'State v. Molina', 'https://www.courtlistener.com/opinion/1749529/', '1749529') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that rule to be applicable here.', 'general', 'State v. Molina', 'https://www.courtlistener.com/opinion/1749529/', '1749529') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the judgment of the district court.', 'general', 'State v. Molina', 'https://www.courtlistener.com/opinion/1749529/', '1749529') ON CONFLICT DO NOTHING;
