INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Gaskins’s conviction and remand for proceedings consistent with this opinion.', 'general', 'State of Iowa v. Jesse Michael Gaskins', 'https://www.courtlistener.com/opinion/2812905/', '2812905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 112, a non-capital murder case, we held that a trial court may ignore a defendant''s lack of criminal history and impose an aggravated sentence.', 'sentencing', 'State v. Pena', 'https://www.courtlistener.com/opinion/2640047/', '2640047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction, vacate the sentence, and remand for resentencing.', 'sentencing', 'State v. Pena', 'https://www.courtlistener.com/opinion/2640047/', '2640047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 26 For the foregoing reasons, we affirm Defendant''s conviction and remand for resentencing.', 'sentencing', 'State v. Pena', 'https://www.courtlistener.com/opinion/2640047/', '2640047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that Judge Greene was not clearly erroneous in rejecting Abdulbaqui’s mitigating factors.', 'general', 'Abdulbaqui v. State', 'https://www.courtlistener.com/opinion/2606467/', '2606467') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the question was a question for the court, not the jury.', 'general', 'Abdulbaqui v. State', 'https://www.courtlistener.com/opinion/2606467/', '2606467') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming without deciding that the state has a duty to preserve police dispatch tapes, we find that the state has met its burden of establishing that the destruction of the tape was done in good faith.', 'general', 'Abdulbaqui v. State', 'https://www.courtlistener.com/opinion/2606467/', '2606467') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that the state has demonstrated that the defendant was not prejudiced by the tape’s destruction.', 'general', 'Abdulbaqui v. State', 'https://www.courtlistener.com/opinion/2606467/', '2606467') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM both Abdulbaqui’s and Cha-pin’s convictions.', 'general', 'Abdulbaqui v. State', 'https://www.courtlistener.com/opinion/2606467/', '2606467') ON CONFLICT DO NOTHING;
