INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In accordance with these basis constructs, we hold that an accused may not be convicted for an offense that is neither a lesser grade or class of the offense charged nor one necessarily included in the indictment even if the record contains sufficient evidence of the convicted offense.', 'general', 'State v. Trusty', 'https://www.courtlistener.com/opinion/2459751/', '2459751') ON CONFLICT DO NOTHING;
