INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Defendant is not entitled to a new trial on the basis of plain error.', 'general', 'State v. Bledsoe', 'https://www.courtlistener.com/opinion/2166066/', '2166066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Due to omissions of key parts of the record and the resulting uncertainties as to whether the failure to request a duress instruction was a tactical decision on the part of defense counsel, we hold that the Court of Criminal Appeals erred in concluding that considerations of “substantial justice” entitle the Defendant to a new trial on the weapons charge.', 'general', 'State v. Bledsoe', 'https://www.courtlistener.com/opinion/2166066/', '2166066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, under the unique facts and circumstances of this case, we conclude that the trial court’s failure to instruct the jury on the defense of duress with respect to the weapons charge was not an error so egregious as to require the Defendant be afforded a new trial in order to “do substantial justice.', 'general', 'State v. Bledsoe', 'https://www.courtlistener.com/opinion/2166066/', '2166066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the Defendant has failed to establish the prerequisites necessary to a finding of plain error, we reverse the judgment of the Court of Criminal Appeals and reinstate the trial court’s judgment of conviction on the single charge.', 'general', 'State v. Bledsoe', 'https://www.courtlistener.com/opinion/2166066/', '2166066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the Court of Criminal Appeals and reinstate the judgment of the trial court.', 'general', 'State v. Bledsoe', 'https://www.courtlistener.com/opinion/2166066/', '2166066') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Criminal Appeals and reinstate the trial court’s judgment of conviction for one count of unlawful possession of a weapon by a convicted felon.', 'general', 'State v. Bledsoe', 'https://www.courtlistener.com/opinion/2166066/', '2166066') ON CONFLICT DO NOTHING;
