INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the family was technically left in safe places — their home and work — we held that they were not “released,” as contemplated by Ark.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1401936/', '1401936') ON CONFLICT DO NOTHING;
