INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on all points.', 'general', 'Davis v. State', 'https://www.courtlistener.com/opinion/1401936/', '1401936') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court, vacating a court of appeals decision that held Van Baa-le’s common-law claims were viable.', 'general', 'Van Baale v. City of Des Moines', 'https://www.courtlistener.com/opinion/1711660/', '1711660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We therefore hold the claim for emotional distress was correctly dismissed.', 'dismissal', 'Van Baale v. City of Des Moines', 'https://www.courtlistener.com/opinion/1711660/', '1711660') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we conclude that the trial court erroneously instructed the jury that it could convict defendants Bobby Martin, Thompson, and Brown of keeping a house of prostitution as a necessarily included lesser offense of racketeering, we reverse and vacate their convictions for that offense.', 'general', 'People v. Martin', 'https://www.courtlistener.com/opinion/1651199/', '1651199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, we conclude that the Legislature did not intend the predicate offenses supporting a racketeering charge to be considered lesser included offenses of that charge.', 'general', 'People v. Martin', 'https://www.courtlistener.com/opinion/1651199/', '1651199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because the jury did not convict defendant of the predicate offenses, but rather returned a verdict of guilty on the racketeering charge alone, we conclude that any error in the instruction was harmless.', 'general', 'People v. Martin', 'https://www.courtlistener.com/opinion/1651199/', '1651199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that defendant does not have a Sixth Amendment right to have a jury determine the amount of the costs incurred in investigating and prosecuting his racketeering violation.', 'general', 'People v. Martin', 'https://www.courtlistener.com/opinion/1651199/', '1651199') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we reverse their convictions and vacate their sentences for keeping a house of prostitution in violation of MCL 750.', 'sentencing', 'People v. Martin', 'https://www.courtlistener.com/opinion/1651199/', '1651199') ON CONFLICT DO NOTHING;
