INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions of Billy Martin and Frasure.', 'general', 'People v. Martin', 'https://www.courtlistener.com/opinion/1651199/', '1651199') ON CONFLICT DO NOTHING;
