INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '45(l)(b), we hold that, because this was a criminal sexual conduct case involving a child victim, there was no error relative to the trial court’s multiple instructions to the jury regarding the dates of the offenses.', 'general', 'People v. Dobek', 'https://www.courtlistener.com/opinion/2231025/', '2231025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'supports the admission of the evidence, and we hold that the trial court did not err in allowing other-acts evidence concerning sexual acts between defendant and the victim.', 'general', 'People v. Dobek', 'https://www.courtlistener.com/opinion/2231025/', '2231025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the other-acts evidence relative to the victim was not submitted for purposes of showing defendant’s propensity to commit the crimes or his character;', 'general', 'People v. Dobek', 'https://www.courtlistener.com/opinion/2231025/', '2231025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we do not demand 100 percent scientific certainty, for all the reasons we have listed, we hold that sex-offender profiling is not sufficiently reliable, nor is the supporting data sufficient, to allow for admission.', 'general', 'People v. Dobek', 'https://www.courtlistener.com/opinion/2231025/', '2231025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summation, we hold that claims of prosecutorial misconduct were waived, not shown, or did not amount to a denial of defendant’s right to a fair and impartial trial;', 'general', 'People v. Dobek', 'https://www.courtlistener.com/opinion/2231025/', '2231025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the trial court did not abuse its discretion in admitting the opinion evidence regarding the speed and intensity of the fire.', 'general', 'People v. Dobek', 'https://www.courtlistener.com/opinion/2231025/', '2231025') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, for the most part, defendant waived claims of misconduct relative to closing argument.', 'general', 'People v. Dobek', 'https://www.courtlistener.com/opinion/2231025/', '2231025') ON CONFLICT DO NOTHING;
