INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the recent amendment to section 1-6 does not apply retroactively to this case because it effected a change in substantive law.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, this court held that section 11-401 implicitly requires the mental state of knowledge on the part of a motorist.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following Cockrum, this court held in Siemieniec v.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the legislature''s focus on requiring a driver to render aid to an injured person, we find that it is consistent with legislative intent to require that a driver have knowledge that the accident involved another person.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Next, we find that the Carlsons'' testimony does not conclusively establish that a different vehicle struck Pranaitis.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence presented to the jury was sufficient to support a finding that defendant knew another person was involved in the accident.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated above, we affirm the holding of the appellate court reversing defendant''s conviction and sentence for failure to report a motor vehicle accident resulting in death.', 'sentencing', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm the appellate court''s reversal of defendant''s conviction for failure to report an accident involving personal injury or death, and remand for a new trial.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that section 11-401 requires that a motorist have knowledge that he or she was involved in an accident that involved another person.', 'general', 'People v. Digirolamo', 'https://www.courtlistener.com/opinion/2023849/', '2023849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, because the investigator personally testified that he continued his investigation after Payton gave her recanting statement, and because Payton personally recanted her testimony at the evidentiary hearing, we find that any error was harmless.', 'general', 'People v. Canter', 'https://www.courtlistener.com/opinion/1282572/', '1282572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and remand for further proceedings.', 'general', 'People v. Canter', 'https://www.courtlistener.com/opinion/1282572/', '1282572') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Yoakums have not articulated any cogent reason for us to find in this case that these two torts should be distinguished and we affirm the district court''s conclusion that these causes of action, at least for the purposes of this case, are identical.', 'general', 'Yoakum v. Hartford Fire Insurance', 'https://www.courtlistener.com/opinion/1444047/', '1444047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Yoakums have failed to allege or prove any special harm resulting from this alleged utterance and, thus, we affirm the district court''s granting of Hartford''s motion for summary judgment on the slander cause of action.', 'general', 'Yoakum v. Hartford Fire Insurance', 'https://www.courtlistener.com/opinion/1444047/', '1444047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court''s dismissal, under I.', 'dismissal', 'Yoakum v. Hartford Fire Insurance', 'https://www.courtlistener.com/opinion/1444047/', '1444047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'City of McCall, # CV 90-244 (Valley County, Idaho), we affirm the district court''s order granting Hartford''s motion for summary judgment for the reasons enunciated in this opinion.', 'general', 'Yoakum v. Hartford Fire Insurance', 'https://www.courtlistener.com/opinion/1444047/', '1444047') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of convictions.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/2384094/', '2384094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the rules reconciled and the principles established in Ward and summarized by contemporary commentators, we hold that actual harm or prejudice to the rights of another was not an element of the crime of forgery of public records at English common law and that, pursuant to Code §§ 1-10 and -11, this became the law of this Commonwealth.', 'general', 'Campbell v. Commonwealth', 'https://www.courtlistener.com/opinion/1364586/', '1364586') ON CONFLICT DO NOTHING;
