INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Francis', 'https://www.courtlistener.com/opinion/2312707/', '2312707') ON CONFLICT DO NOTHING;
