INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Robert M. on behalf of Bella O. v. Danielle O.', 'https://www.courtlistener.com/opinion/4625043/', '4625043') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lagana , this Court held that an investigative detention was supported by reasonable suspicion of criminal activity where the police received an anonymous report of an armed individual wearing a yellow raincoat at a specified location and, upon their arrival, officers observed an individual matching the description who was "casing" a restaurant with a pair of binoculars.', 'general', 'Commonwealth v. Hicks, M., Aplt.', 'https://www.courtlistener.com/opinion/4625130/', '4625130') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the rule contravenes the requirements of the Terry doctrine, and thus subverts the fundamental protections of the Fourth Amendment, we overrule Robinson and its progeny.', 'search_seizure', 'Commonwealth v. Hicks, M., Aplt.', 'https://www.courtlistener.com/opinion/4625130/', '4625130') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have little difficulty in again rejecting this proposition, because we conclude that the Robinson rule contravenes the Terry doctrine and, indeed, the fundamental guarantees of the Fourth Amendment.', 'search_seizure', 'Commonwealth v. Hicks, M., Aplt.', 'https://www.courtlistener.com/opinion/4625130/', '4625130') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the agent could not as a matter of law, have reasonably suspected the petitioner of criminal activity on the basis of these observed circumstances.', 'general', 'Commonwealth v. Hicks, M., Aplt.', 'https://www.courtlistener.com/opinion/4625130/', '4625130') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', 7/14/2015, at 15, we conclude that the record contains minimal support for the suppression court''s finding that Hicks "showed" his firearm to another individual.', 'suppression', 'Commonwealth v. Hicks, M., Aplt.', 'https://www.courtlistener.com/opinion/4625130/', '4625130') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Superior Court''s decision in the instant case having descended from Robinson ''s erroneous proposition of law, and there being no other lawful basis for the seizure at issue, we reverse the order of the Superior Court.', 'general', 'Commonwealth v. Hicks, M., Aplt.', 'https://www.courtlistener.com/opinion/4625130/', '4625130') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'People v. Dry Land Marina, Inc', 'https://www.courtlistener.com/opinion/1856153/', '1856153') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the decision of the trial court to excuse the ailing juror constituted a proper exercise of judicial discretion supported by fact and logic.', 'general', 'People v. Dry Land Marina, Inc', 'https://www.courtlistener.com/opinion/1856153/', '1856153') ON CONFLICT DO NOTHING;
