INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm defendant’s conviction but vacate that portion of the sentence ordering defendant to pay restitution.', 'sentencing', 'People v. Owens', 'https://www.courtlistener.com/opinion/2095593/', '2095593') ON CONFLICT DO NOTHING;
