INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the plain language of W.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the parties'' arguments, the pertinent authorities, and the record designated for appellate consideration, we conclude that the circuit court erred by ruling that Mr.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statutes in question, i.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Code § 61-7-7(c) to persons who have received unconditional pardons for their convictions, we concluded that "the Legislature''s method of achieving th[e] goal [of public safety] has been crafted narrowly so as not to offend the Constitution.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rohrbaugh has been convicted of such a crime, we find that the prohibitions of W.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying these tenets to the matter at hand, we find that the Legislature did not violate the West Virginia or United States Constitutions by enacting the firearm restrictions contained in W.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Insofar as § 61-7-7 does not operate to increase the punishment for the crimes referenced therein, we find that it does not constitute cruel and unusual punishment under either the West Virginia or United States Constitutions.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the January 13, 2003, order of the Grant County Circuit Court.', 'general', 'Rohrbaugh v. State', 'https://www.courtlistener.com/opinion/1412091/', '1412091') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we hold that the policy exclusion precludes liability coverage in each of the six cases, and affirm in part and reverse in part the judgment of the appellate court.', 'general', 'Founders Insurance v. Munoz', 'https://www.courtlistener.com/opinion/1987028/', '1987028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pursuant to our analysis in Progressive, we hold that the exclusion does not violate Illinois public policy as set forth in section 7 — 317(b)(2) of the Vehicle Code.', 'general', 'Founders Insurance v. Munoz', 'https://www.courtlistener.com/opinion/1987028/', '1987028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the car-business exclusion conflicted with section 7 — 317(b)(2) and thus violated Illinois public policy:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the appellate court’s judgment in the LeVan, Honchar, Vallarta, and Tecpanecatl cases that reversed the trial court’s grant of summary judgment in favor of Founders.', 'general', 'Founders Insurance v. Munoz', 'https://www.courtlistener.com/opinion/1987028/', '1987028') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we affirm the appellate court judgment in the Munoz case affirming the trial court’s grant of summary judgment in favor of Founders.', 'general', 'Founders Insurance v. Munoz', 'https://www.courtlistener.com/opinion/1987028/', '1987028') ON CONFLICT DO NOTHING;
