INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that (6) Defendant was not entitled to credit on his Hawai''i sentence for time served for a Minnesota offense, and (7) any improper trial comments by the State were harmless beyond a reasonable doubt.', 'sentencing', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/2613636/', '2613636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that the thirty-five day period from February 8, 1993, the original theft trial date, to March 15, 1993, the continued trial date, must also be excluded from the 180-day speedy trial requirement because Defendant was “unable to stand trial” by virtue of the trial continuance “occasioned by [him].', 'general', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/2613636/', '2613636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After excluding these forty days, we conclude that Defendant was brought to trial on his theft charge in 170 days, 10 days within the 180-day speedy trial provision required by the IAD, HRS § 834-1, art.', 'general', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/2613636/', '2613636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, because Defendant moved for the theft trial continuance to March 15, 1993, agreed to consolidation of the theft and bail jumping cases for trial on March 15, 1993, and represented to the court that he sought the continuance to conduct plea bargain discussions in both cases, we conclude that Defendant implicitly consented to the March 15, 1993 bail jumping trial date.', 'plea', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/2613636/', '2613636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that these statements did not constitute error.', 'general', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/2613636/', '2613636') ON CONFLICT DO NOTHING;
