INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the May 14,1993 judgment.', 'general', 'State v. Schmidt', 'https://www.courtlistener.com/opinion/2613636/', '2613636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err, on first amendment grounds, in denying Viglielmo''s motions to dismiss or in finding her guilty, inasmuch as (1) the district court''s decisions did not run afoul of federal constitutional case law and (2) Viglielmo''s expressive conduct on the premises of Ala Moana Shopping Center was not protected under the first amendment to the United States Constitution.', 'dismissal', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that article I, section 4 of the Hawai''i Constitution affords Viglielmo no greater free speech protection than the first amendment to the United States Constitution and that she is therefore not insulated from criminal liability under HRS § 708-814(1)(b).', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there has been no such dedication of Lloyd''s privately owned and operated shopping center to public use as to entitle respondents to exercise therein the asserted [f]irst [a]mendment rights.', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in light of the United States Supreme Court''s decisions delineating the boundaries of first amendment protections in shopping centers, we hold that the district court did not err, on first amendment grounds, in denying Viglielmo''s motions to dismiss or in finding her guilty, inasmuch as (1) the district court''s decisions did not run afoul of federal constitutional case law and (2) Viglielmo''s expressive conduct on the premises of Ala Moana Shopping Center was not protected under th...', 'dismissal', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*968 Under these circumstances, we hold that article I, section 4 of the Hawai''i Constitution affords Viglielmo no greater free speech protection than the first amendment to the United States Constitution and that she is therefore not insulated from criminal liability under HRS § 708-814 (1)(b), see supra note 2.', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 196 (1976)]), we hold that the interior walkway to the main entrance to the Hospital is not historically nor traditionally associated with the exercise of free speech.', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 216 (1990), we held that a hospital''s no-solicitation policy precluding distribution of leaflets and other expressions of anti-abortion views did not implicate "state action" for the purposes of the state constitutional guarantee of free speech, and that an interior walkway adjacent to one of the main entrances of the hospital was not historically or traditionally associated with the exercise of free speech rights and therefore not to be treated as public property for free speech purposes.', 'general', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing analysis, we affirm the district court''s judgment of conviction and sentence.', 'sentencing', 'State v. Viglielmo', 'https://www.courtlistener.com/opinion/2597507/', '2597507') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the district court’s conclusion that Estrada’s attorney was deficient in failing to inform his client of this right.', 'general', 'Estrada v. State', 'https://www.courtlistener.com/opinion/2564650/', '2564650') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the superior court erred in barring the state from presenting evidence to prove McLaughlin''s previous conviction of a felony.', 'general', 'State v. McLaughlin', 'https://www.courtlistener.com/opinion/1145398/', '1145398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On those facts, we held that the heroin was not discovered by the private search, but by a second search conducted by the police.', 'general', 'People v. Phillips', 'https://www.courtlistener.com/opinion/2233260/', '2233260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that nonexperts are unacceptably prone to mistake other plants for marijuana.', 'general', 'People v. Phillips', 'https://www.courtlistener.com/opinion/2233260/', '2233260') ON CONFLICT DO NOTHING;
