INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we held that the driver’s criminal negligence, including driving without a license, not stopping when being pursued by a police officer, speeding through residential streets at 60 m.', 'general', 'Powell v. Drumheller', 'https://www.courtlistener.com/opinion/2011124/', '2011124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the complaint, we find that Powell is alleging that PENNDOT and Drumheller jointly and concurrently caused her husband’s death.', 'general', 'Powell v. Drumheller', 'https://www.courtlistener.com/opinion/2011124/', '2011124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Powell v. Drumheller', 'https://www.courtlistener.com/opinion/2011124/', '2011124') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed, affirming the concept of joint liability as applicable to municipalities for actions taken in concert with another tortfeasor.', 'general', 'Powell v. Drumheller', 'https://www.courtlistener.com/opinion/2011124/', '2011124') ON CONFLICT DO NOTHING;
