INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed these principles of concurrent or joint causation in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the government may prosecute parent-child assaults as violations of the simple assault statute, and that the government does not need to prove malice in order to overcome the parental discipline defense and secure a conviction.', 'general', 'Newby v. United States', 'https://www.courtlistener.com/opinion/1537393/', '1537393') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the simple assault statute, D.', 'general', 'Newby v. United States', 'https://www.courtlistener.com/opinion/1537393/', '1537393') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the government was not required to prove malice in order to rebut appellant’s assertion of the parental discipline defense.', 'general', 'Newby v. United States', 'https://www.courtlistener.com/opinion/1537393/', '1537393') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that malice was an element of cruelty to children as that offense was described before 1994, when the statute was amended to specify that the crime could be committed “intentionally, knowingly or recklessly.', 'general', 'Newby v. United States', 'https://www.courtlistener.com/opinion/1537393/', '1537393') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant preserved both her claims for full appellate review, though she did not raise either one of them with specificity in the trial court, because
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Null', 'https://www.courtlistener.com/opinion/1598202/', '1598202') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*649 We hold that the court of appeals applied the correct legal standard in determining whether the evidence "raised" the "Good Samaritan" defense in this case.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we hold that the trial court did not err in refusing to submit the defensive instruction to the jury.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As far back as 1937, we held that "[c]ourts are only required to submit [defensive] theories of cases when same are supported by some testimony of sufficient cogence and substance to make it appear, at least with some degree of likelihood, that there could be a finding by the jury in response to such suggested issue.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[31] We held that Young himself was not entitled to a necessity instruction because he merely "argued he did not commit the offense because he did not have the requisite intent and he did not perform the actions the State alleged.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[32] Similarly, in Ex parte Nailor, we held that the defendant was not entitled to a jury instruction on self defense because his defensive evidence did not show confession and avoidance, but only a lack of the required culpable act and mens rea.', 'jury_instruction', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, albeit for reasons somewhat different than those expressed by the court of appeals in its opinion below, we affirm its judgment affirming the judgment of the trial court.', 'general', 'Shaw v. State', 'https://www.courtlistener.com/opinion/2356644/', '2356644') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'to support it and, accordingly, we hold that the Court of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We affirm.', 'general', 'State v. Rocheville', 'https://www.courtlistener.com/opinion/1277611/', '1277611') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there was no abuse of discretion by the trial court in denying Jones’s requested modification of AMCI2d 401.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2387538/', '2387538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that though the trial court abused its discretion in disallowing impeachment, the error was harmless and did not contribute to the verdict in light of the other evidence.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2387538/', '2387538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the Due Process Clause requires the prosecution to prove beyond a reasonable doubt all the elements of the offense charged but that it does not require the prosecution to prove the nonexistence of all affirmative defenses.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2387538/', '2387538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, supra, we held that the erroneous denial of a defendant’s opportunity to impeach a witness is subject to a Chapman harmless-error review.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2387538/', '2387538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient evidence that Jones intended to rob the Subway shop and that Rummel was killed in furtherance of that plan.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2387538/', '2387538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But even assuming that the error in disallowing Polk’s impeachment was not cured, we conclude that the error was harmless beyond a reasonable doubt.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2387538/', '2387538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2387538/', '2387538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that, following the 1985 amendments to Article V, § 12 of the Texas Constitution and Article 1.', 'general', 'State v. Yount', 'https://www.courtlistener.com/opinion/2450499/', '2450499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A plurality of this Court held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that appellee cannot benefit from the lesser included offense instruction and then attack his conviction of that lesser included offense on limitations grounds.', 'general', 'State v. Yount', 'https://www.courtlistener.com/opinion/2450499/', '2450499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1973), we reversed a conviction on the grounds that the applicable statute of limitations had run even though the claim was presented for the first time in a motion for rehearing.', 'general', 'State v. Yount', 'https://www.courtlistener.com/opinion/2450499/', '2450499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that based on this evidence, the jury properly concluded that each and every element of the crimes charged was established beyond a reasonable doubt — i.', 'general', 'Commonwealth v. Baker', 'https://www.courtlistener.com/opinion/2319754/', '2319754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this evidence, we find that Judge Oler correctly opined that the misstatement was not “material”, in that even in redacted form, without reference to Baker as the person who was utilizing the computer at the time in question, the affidavit contained more than sufficient information to support a belief that contraband in the form of child pornography would be found in a search of the address in question.', 'general', 'Commonwealth v. Baker', 'https://www.courtlistener.com/opinion/2319754/', '2319754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his judgment of sentence and find that he was properly determined to be a sexually violent predator.', 'sentencing', 'Commonwealth v. Baker', 'https://www.courtlistener.com/opinion/2319754/', '2319754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we affirm Judge Oler’s denial of Baker’s request to suppress the evidence seized as the result of the execution of the search warrant.', 'suppression', 'Commonwealth v. Baker', 'https://www.courtlistener.com/opinion/2319754/', '2319754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Judge Oler’s denial of Baker’s request to suppress the statement he made.', 'suppression', 'Commonwealth v. Baker', 'https://www.courtlistener.com/opinion/2319754/', '2319754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm his judgment of sentence on these grounds.', 'sentencing', 'Commonwealth v. Baker', 'https://www.courtlistener.com/opinion/2319754/', '2319754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having concluded that Baker has failed to show that error occurred in his designation as a Sexually Violent Predator for purposes of Megan’s Law, we affirm that order.', 'general', 'Commonwealth v. Baker', 'https://www.courtlistener.com/opinion/2319754/', '2319754') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a discretionary act cannot create a legitimate expectation of release on the presumptive mandatory release date, we affirm the circuit court''s dismissal of Gendrich''s writ of certiorari.', 'dismissal', 'State Ex Rel. Gendrich v. Litscher', 'https://www.courtlistener.com/opinion/2234654/', '2234654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we hold that if, in the course of a lawful search, evidence of a crime is found, other than the crime for which the search was conducted or the accused arrested, the evidence may be seized and used against the accused in the trial of either offense.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/1509276/', '1509276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that it was unfairly prejudicial to admit testimony regarding the defendant’s predisposition to rape when he was on trial for burglary and conspiracy, because the testimony was neither relevant nor material to either of the charges at issue.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/1509276/', '1509276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because there is no right to refuse to submit to a breathalyzer.', 'general', 'Svedlund v. Municipality of Anchorage', 'https://www.courtlistener.com/opinion/2605252/', '2605252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that because there was no right to refuse to take a breathalyzer, a refusal was not privileged by the fifth amendment.', 'general', 'Svedlund v. Municipality of Anchorage', 'https://www.courtlistener.com/opinion/2605252/', '2605252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that punishing a refusal to take a breathalyzer test bears a fair and substantial relation to the legitimate governmental objective of gathering evidence of possible drunken driving.', 'general', 'Svedlund v. Municipality of Anchorage', 'https://www.courtlistener.com/opinion/2605252/', '2605252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that offering Svedlund a breathalyzer examination, where there was independent evidence establishing probable cause to charge him with driving while intoxicated, was a lawful search incident to an arrest.', 'probable_cause', 'Svedlund v. Municipality of Anchorage', 'https://www.courtlistener.com/opinion/2605252/', '2605252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that the nexus between the purpose of the law,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Svedlund v. Municipality of Anchorage', 'https://www.courtlistener.com/opinion/2605252/', '2605252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Svedlund’s constitutional rights were not violated by not informing him of his
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with this authority we conclude that AS 11.', 'general', 'Bachlet v. State', 'https://www.courtlistener.com/opinion/1172165/', '1172165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the statute was not unconstitutionally vague for failure to provide Bachlet notice of the prohibited conduct.', 'general', 'Bachlet v. State', 'https://www.courtlistener.com/opinion/1172165/', '1172165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state''s concession is sound and that Bachlet''s three solicitation convictions should merge into a single offense.', 'general', 'Bachlet v. State', 'https://www.courtlistener.com/opinion/1172165/', '1172165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bachlet v. State', 'https://www.courtlistener.com/opinion/1172165/', '1172165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Cunningham, this court held that a medical malpractice claim is not barred by the statute of repose where the plaintiff demonstrates that there was a continuous and unbroken course of negligent treatment so related as to constitute one continuing wrong.', 'general', 'Feltmeier v. Feltmeier', 'https://www.courtlistener.com/opinion/2148298/', '2148298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that neither the policy considerations commonly raised nor the law of this state support a conclusion that an action for intentional infliction of emotional distress based upon conduct occurring in the marital setting should be barred or subject to any heightened threshold for establishing outrageousness.', 'general', 'Feltmeier v. Feltmeier', 'https://www.courtlistener.com/opinion/2148298/', '2148298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, where the complaint sets forth sufficient facts which, if proven, could entitle Lynn to relief, we conclude that she has stated a cause of action for intentional infliction of emotional distress.', 'general', 'Feltmeier v. Feltmeier', 'https://www.courtlistener.com/opinion/2148298/', '2148298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, where we find that a reasonable trier of fact could easily conclude that Robert’s conduct was so outrageous as to be regarded as intolerable in a civilized community, we reject his contention that the complaint fails to sufficiently allege this element.', 'general', 'Feltmeier v. Feltmeier', 'https://www.courtlistener.com/opinion/2148298/', '2148298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we find that Lynn has sufficiently alleged that as a result of enduring Robert’s physical and psychological abuse for the duration of their 11-year marriage and beyond, she suffered severe emotional distress.', 'general', 'Feltmeier v. Feltmeier', 'https://www.courtlistener.com/opinion/2148298/', '2148298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the two-year statute of limitations for this action began to run in August 1999, because Lynn’s complaint includes allegations of tortious behavior by Robert occurring as late as that month.', 'general', 'Feltmeier v. Feltmeier', 'https://www.courtlistener.com/opinion/2148298/', '2148298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not reach this substantive analysis of the issue, however, because we find that Robert’s contention is erroneously based upon an earlier version of the statute which was no longer in effect at the time of the parties’ marriage in 1986.', 'general', 'Feltmeier v. Feltmeier', 'https://www.courtlistener.com/opinion/2148298/', '2148298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the omission of the ulterior crime amounts to a defect of form.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a criminal trespass count which fails to specify the ulterior crime that the defendant allegedly intended to commit is defective in form, but not in substance.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the failure of the information to specify the offense underlying the criminal trespass charge was a defect of form, but not a defect of substance.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Gomez, we held that an information count charging a defendant with burglary was fatally defective because it failed to state the specific crime which the defendant allegedly had intended to commit.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a consequence, we held that "[o]ne essential element in a charge of burglary is that at the very time and place of breaking and entering the accused have an intent to commit therein a specific crime.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] We conclude that the information charging Williams with criminal trespass was defective in form, but not in substance.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that, "by the great weight of authority," an information charging a defendant with burglary "must specify by name, at least, the ulterior crime which it is alleged the accused intended to commit upon entry of the building.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the "absence of a clear and specific incorporation by reference," we concluded that the burglary count must be evaluated independently of the other counts.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we found that, because the error divested the court of jurisdiction over the count, the information was fatally defective.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the court of appeals'' judgment and reinstate Williams'' conviction.', 'general', 'People v. Williams', 'https://www.courtlistener.com/opinion/2614620/', '2614620') ON CONFLICT DO NOTHING;
