INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the Court of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, if a probation term provides for warrantless searches and the terms of probation are narrowly tailored to fit the circumstances of the individual probationer, the Griffin "reasonable grounds" standard strikes the proper balance between probationer privacy rights and public protection concerns.', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a probation warrant is not the type of contract contemplated by § 9310(a)(2).', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court did not err when it decided not to order a third competency hearing prior to commencing revocation proceedings.', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we are mindful that limits must be placed on such searches and that consent to future searches "as required" does not permit unfettered intrusions into the private lives of probationers, we find that the "reasonable *663 grounds" standard establishes the proper safeguard.', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lockwood', 'https://www.courtlistener.com/opinion/2401501/', '2401501') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a judge who accepts a bribe must be removed from office.', 'general', 'Matter of Coruzzi', 'https://www.courtlistener.com/opinion/2357909/', '2357909') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that sexual assault in the fourth degree is not included in the charged offense as defined by HRS § 701-109(4).', 'general', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 288 (1979), despite a clear and unambiguous legislative history  as reflected in the relevant committee reports  of an intent to accomplish a particular result in amending the drug laws, this court held, by virtue of the plain language of its statutory work product, that "the [l]egislature did not carry its intention into effect.', 'general', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm.', 'general', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing discussion, we affirm Buch''s conviction, judgment, and sentence for sexual assault in the third degree.', 'sentencing', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a defendant is strictly liable with respect to the attendant circumstance of the victim''s age in a sexual assault;', 'general', 'State v. Buch', 'https://www.courtlistener.com/opinion/1160456/', '1160456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Noblit v. State', 'https://www.courtlistener.com/opinion/1219645/', '1219645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in order to give effect to the act we hold that *794 it is to be construed as permitting the district judge to fix a maximum imprisonment at less than life.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1361856/', '1361856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute does not make an arbitrary or unreasonable classification, and does not deny defendant equal protection of the laws.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1361856/', '1361856') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that parental rights may be terminated under section 39.', 'general', 'Florida Dept. of Children and Fam. v. Fl', 'https://www.courtlistener.com/opinion/1707939/', '1707939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Padgett, we held that to terminate the parental rights in one child based solely on the prior termination of rights in another child, "the state must show by clear and convincing evidence that reunification with the parent poses a substantial risk of significant harm to the child.', 'general', 'Florida Dept. of Children and Fam. v. Fl', 'https://www.courtlistener.com/opinion/1707939/', '1707939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '53–54 (2004), we held that this provision bars “admission
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the Supreme Court of Wash
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '286 (1969), this Court held that the Travel Act did not incorporate the common-law definition of "extortion," because that definition had been expanded in many States by the time the Act was passed, id.', 'general', 'Taylor v. United States', 'https://www.courtlistener.com/opinion/112435/', '112435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a person has been convicted of burglary for purposes of a § 924(e) enhancement if he is convicted of any crime, regardless of its exact definition or label, having the basic elements of unlawful or unprivileged entry into, or remaining in, a building or structure, with intent to commit a crime.', 'general', 'Taylor v. United States', 'https://www.courtlistener.com/opinion/112435/', '112435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that an offense constitutes "burglary" for purposes of a § 924(e) sentence enhancement if either its statutory definition substantially corresponds to "generic" burglary, or the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the defendant.', 'sentencing', 'Taylor v. United States', 'https://www.courtlistener.com/opinion/112435/', '112435') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the owner of premises is liable for injury proximately caused by the owner''s affirmative or active negligence in the operation or control of activities which subjects a licensee to unusual danger or increases the hazard to the licensee when the presence of the licensee is known.', 'general', 'Titus v. Williams', 'https://www.courtlistener.com/opinion/1629823/', '1629823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 304, we held that the Hoffman exception has no application where the licensee is injured as a result of the condition of the premises, or passive negligence.', 'general', 'Titus v. Williams', 'https://www.courtlistener.com/opinion/1629823/', '1629823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the facts presented in this case do not support application of the Hoffman exception to any of the defendants.', 'general', 'Titus v. Williams', 'https://www.courtlistener.com/opinion/1629823/', '1629823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that plaintiffs failed to establish that Titus''s tragic death was proximately caused by any negligence of the Flash Store and or Williams.', 'general', 'Titus v. Williams', 'https://www.courtlistener.com/opinion/1629823/', '1629823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that all the allegations brought by the plaintiffs involve things that the Flash Store (and Williams) failed to do.', 'general', 'Titus v. Williams', 'https://www.courtlistener.com/opinion/1629823/', '1629823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This being the case, we conclude that no duty was breached by the Flash Store.', 'general', 'Titus v. Williams', 'https://www.courtlistener.com/opinion/1629823/', '1629823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Sardis Police acted responsibly and within their discretion.', 'general', 'Titus v. Williams', 'https://www.courtlistener.com/opinion/1629823/', '1629823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the trial court''s judgment.', 'general', 'Titus v. Williams', 'https://www.courtlistener.com/opinion/1629823/', '1629823') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction and sentence for the purchase of cocaine, but reverse the conviction and sentence for tampering with evidence.', 'sentencing', 'Boice v. State', 'https://www.courtlistener.com/opinion/1864413/', '1864413') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that defendant''s double jeopardy claim was not forfeited, as it was properly raised in response to the State''s argument.', 'general', 'People v. Whitfield', 'https://www.courtlistener.com/opinion/2204818/', '2204818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '* * * We hold that the constitutional guarantee against multiple punishments for the same offense absolutely requires that punishment already exacted must be fully `credited'' in imposing sentence upon a new conviction for the same offense.', 'sentencing', 'People v. Whitfield', 'https://www.courtlistener.com/opinion/2204818/', '2204818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that a defendant sentenced to probation, and then sentenced to imprisonment for the same offense, is not subjected to an unconstitutional second punishment for double jeopardy purposes and, therefore, is not entitled to credit for time spent on probation.', 'sentencing', 'People v. Whitfield', 'https://www.courtlistener.com/opinion/2204818/', '2204818') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons above, we reverse the appellate court''s judgment remanding this matter to the trial court for consideration of sentencing credit for the time defendant spent on a void probation.', 'sentencing', 'People v. Whitfield', 'https://www.courtlistener.com/opinion/2204818/', '2204818') ON CONFLICT DO NOTHING;
