INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we affirmed solely because
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the trial court correctly denied defendant''s motion to suppress.', 'suppression', 'State v. Lamb', 'https://www.courtlistener.com/opinion/2259118/', '2259118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the action of the trial judge controlled and found this judge''s rationale to be valid.', 'general', 'State v. Lamb', 'https://www.courtlistener.com/opinion/2259118/', '2259118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the detention was amply justified because (a) the investigating officer had corroborating information that could only have come from a knowledgeable insider, (b) the officer knew that defendant had been arrested previously for DUI, and (c) the offense of DUI presented an imminent risk of injury to the suspect or the public.', 'general', 'State v. Lamb', 'https://www.courtlistener.com/opinion/2259118/', '2259118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Lamb', 'https://www.courtlistener.com/opinion/2259118/', '2259118') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm Flores’s conviction and sentence.', 'sentencing', 'State v. Flores', 'https://www.courtlistener.com/opinion/2465569/', '2465569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 21 We affirm Flores’s conviction and sentence.', 'sentencing', 'State v. Flores', 'https://www.courtlistener.com/opinion/2465569/', '2465569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 19 We therefore hold that because the officers acted appropriately and reasonably in the arrest, there was no fundamental error, and Flores’s resistance was not permissible under the law.', 'general', 'State v. Flores', 'https://www.courtlistener.com/opinion/2465569/', '2465569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the accused was not deprived of his constitutional rights to due process, and we affirm the judgment of conviction.', 'general', 'Hagen v. State', 'https://www.courtlistener.com/opinion/2428968/', '2428968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment because the circuit court reached the right result, albeit, for the wrong reason.', 'general', 'Hagen v. State', 'https://www.courtlistener.com/opinion/2428968/', '2428968') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the facts presented in this case, the appellate court erred by failing to hold that defendant waived his chain of custody challenge.', 'general', 'People v. Woods', 'https://www.courtlistener.com/opinion/2080631/', '2080631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in the matter before us, we hold that the appellate court erred in failing to apply the waiver rule to bar defendant from raising, for the first time on appeal, a challenge to the sufficiency of the State’s chain of custody.', 'general', 'People v. Woods', 'https://www.courtlistener.com/opinion/2080631/', '2080631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Officer Dineen’s testimony coupled with the stipulation sufficiently describe the condition of the evidence when seized which matches the description of the evidence when examined.', 'general', 'People v. Woods', 'https://www.courtlistener.com/opinion/2080631/', '2080631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the testimony of Officer Dineen and the contents of the stipulation are consistent in that they both speak of the same inventory number and the same number of items which were described as “packets.', 'general', 'People v. Woods', 'https://www.courtlistener.com/opinion/2080631/', '2080631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, under the unique facts of this case, we find that defendant also affirmatively waived his challenge to the sufficiency of the State’s chain of custody.', 'general', 'People v. Woods', 'https://www.courtlistener.com/opinion/2080631/', '2080631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Woods', 'https://www.courtlistener.com/opinion/2080631/', '2080631') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such action constitutes the unauthorized practice of law.', 'general', 'In Re Richland County Magistrate''s Court', 'https://www.courtlistener.com/opinion/2109732/', '2109732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 491 (“Therefore, in light of the legislature’s extension of law enforcement authority to licensed security officers, we hold that licensed security officers may prosecute misdemean- or cases in magistrate’s or municipal court.', 'general', 'In Re Richland County Magistrate''s Court', 'https://www.courtlistener.com/opinion/2109732/', '2109732') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that allowing prosecution decisions to be made by, or even influenced by, private interests would do irreparable harm to our criminal justice system.', 'general', 'In Re Richland County Magistrate''s Court', 'https://www.courtlistener.com/opinion/2109732/', '2109732') ON CONFLICT DO NOTHING;
