INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[5]  The Commonwealth alternatively argues that if we find that no authority exists for the arrest, we should consider the admissibility of the evidence incident to a pat-down search conducted while taking Bullers into custody for purposes of notification.', 'general', 'Commonwealth v. Bullers', 'https://www.courtlistener.com/opinion/1947647/', '1947647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the Superior Court and find that warrantless arrests under such circumstances are not authorized.', 'general', 'Commonwealth v. Bullers', 'https://www.courtlistener.com/opinion/1947647/', '1947647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that a violation of § 6308, unaccompanied by any disorderly conduct, a breach of the peace, or public drunkenness, does not fall within § 46121 of the Borough Code.', 'general', 'Commonwealth v. Bullers', 'https://www.courtlistener.com/opinion/1947647/', '1947647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons we conclude that an indictment under 2 U.', 'general', 'Russell v. United States', 'https://www.courtlistener.com/opinion/106407/', '106407') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, for the reasons discussed in this opinion, we conclude that the contempt order issued subsequent to the appeal from the circuit court declaratory judgment constituted an impermissible interference with the appellate jurisdiction of this court.', 'general', 'Madison Teachers, Inc. v. Scott Walker', 'https://www.courtlistener.com/opinion/2643628/', '2643628') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Morgan', 'https://www.courtlistener.com/opinion/1307300/', '1307300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an outstanding obligation to register under SORA does not sufficiently restrain a putative registrant’s liberty so as to render him “in custody” within the meaning of § 23-110.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2010300/', '2010300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Mr.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2010300/', '2010300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2004),” and, among other things, we concluded that “SORA is a remedial regulatory requirement, not a penal law.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2010300/', '2010300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, in the context of a constitutional challenge of SORA, we concluded that the law’s “registration and notification scheme does not impose a significant affirmative disability or restraint.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2010300/', '2010300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the foregoing reasons, we affirm the judgment of the trial court.', 'general', 'Mitchell v. United States', 'https://www.courtlistener.com/opinion/2010300/', '2010300') ON CONFLICT DO NOTHING;
