INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Court of Appeals for the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that when the preliminary facts relevant to Rule 801(d)(2)(E) are disputed, the offering party must prove them by a preponderance of the evidence.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Lonardo''s out-of-court statements were properly admitted against petitioner.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Confrontation Clause does not require a court to embark on an *184 independent inquiry into the reliability of statements that satisfy the requirements of Rule 801(d)(2)(E).', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '387 (1986), we held that the first of these two generalized inquiries, unavailability, was not required when the hearsay statement is the out-of-court declaration of a co-conspirator.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, we conclude that the second inquiry, independent indicia of reliability, is also not mandated by the Constitution.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bourjaily v. United States', 'https://www.courtlistener.com/opinion/111938/', '111938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that a subsequent prosecution for robbery with a firearm was barred by the Double Jeopardy Clause, because the defendant had already been tried for felony murder based on the same underlying felony.', 'general', 'United States v. Dixon', 'https://www.courtlistener.com/opinion/112906/', '112906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Harris, we held that a conviction for felony murder based on a killing in the course of an armed robbery foreclosed a subsequent prosecution for robbery with a firearm.', 'general', 'United States v. Dixon', 'https://www.courtlistener.com/opinion/112906/', '112906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '176 (1889), where we held that conviction for one statutory offense precluded later prosecution for another, even though each required proof of a fact the other did not.', 'general', 'United States v. Dixon', 'https://www.courtlistener.com/opinion/112906/', '112906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '682 (1977) (per curiam), we held that prosecution for a robbery with firearms was barred by the Double Jeopardy Clause when the defendant had already been convicted of felony murder comprising the same robbery with firearms as the underlying felony.', 'general', 'United States v. Dixon', 'https://www.courtlistener.com/opinion/112906/', '112906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Harris, however, we held that "[w]hen, as here, conviction of a greater crime, murder, cannot be had without conviction of the lesser crime, robbery with firearms, the Double Jeopardy Clause bars prosecution for the lesser crime after conviction of the greater one.', 'general', 'United States v. Dixon', 'https://www.courtlistener.com/opinion/112906/', '112906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "[i]f, as a matter of Illinois law, a careless failure to slow is always a necessary element of manslaughter by automobile, then the two offenses are the `same'' under Blockburger and Vitale''s trial on the latter charge would constitute double jeopardy .', 'general', 'United States v. Dixon', 'https://www.courtlistener.com/opinion/112906/', '112906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we concluded that a subsequent prosecution for conspiracy to manufacture, possess, and distribute methamphetamine was not barred by a previous conviction for attempt to manufacture the same substance.', 'general', 'United States v. Dixon', 'https://www.courtlistener.com/opinion/112906/', '112906') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we hold that an individual held for interrogation must be clearly informed that he has the right to consult with a lawyer and to have the lawyer with him during interrogation under the system for protecting the privilege we delineate today.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To summarize, we hold that when an individual is taken into custody or otherwise deprived of his freedom by the authorities in any significant way and is subjected to questioning, the privilege against self-incrimination is jeopardized.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the statements thus made were constitutionally inadmissible.', 'general', 'Miranda v. Arizona', 'https://www.courtlistener.com/opinion/107252/', '107252') ON CONFLICT DO NOTHING;
