INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that, although a unanimous jury verdict is required on whether the defendant committed the criminal act charged, a “defendant is not entitled to a unanimous verdict on the precise manner in which the act was committed.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/2611089/', '2611089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the anti-repeal provision of article 4 applied only to initiative measures approved by a majority of qualified electors, not merely a majority of those actually voting.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/2611089/', '2611089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we find that an instruction that tracks the statutory language of A.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/2611089/', '2611089') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the principal contested issue relevant to defendant’s culpability was whether he intended to defraud, we held that “fundamental fairness required that the jury be instructed” it had to find intent to defraud.', 'general', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Underwood, we held that it was not plain error for the court to fail to give an IPI instruction on the definition of “reasonable belief.', 'general', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it was not error to give the definitional instruction.', 'general', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the reasoning of the appellate court fails to show that defendant is entitled to relief.', 'general', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, had the jury in this case been properly instructed, it would have been given a definition of first degree murder that, when combined with the instructions on conspiracy, would make clear the State must prove defendant intended that her husband James be killed.', 'general', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that there is inadequate support in the record for defendant’s contention that the jury may have thought that the State did not prove that defendant intended that James be killed.', 'general', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has not shown from the record in this case that there is any significant likelihood that the jury concluded that the State did not prove that defendant intended that James be killed.', 'general', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ogunsola, we reversed defendant’s conviction because an omitted jury instruction “removed from the jury’s consideration a disputed issue essential to the determination of defendant’s guilt or innocence.', 'jury_instruction', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the appellate court and affirm the defendant’s conviction for conspiracy to commit first degree murder.', 'general', 'People v. Hopp', 'https://www.courtlistener.com/opinion/2012645/', '2012645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that conviction of first-degree premeditated murder on an aiding and abetting theory requires the prosecution to prove that the accomplice acted with premeditation and deliberation and intent to kill, and we decline to draw the government’s proposed analogy to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that as to Ms.', 'general', 'Wilson-Bey v. United States', 'https://www.courtlistener.com/opinion/1443806/', '1443806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Wilson-Bey, we reverse Ms.', 'general', 'Wilson-Bey v. United States', 'https://www.courtlistener.com/opinion/1443806/', '1443806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With a single exception unrelated to the principal issue before us, we affirm Ms.', 'general', 'Wilson-Bey v. United States', 'https://www.courtlistener.com/opinion/1443806/', '1443806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the administrative search did not violate Donald’s rights under the Fourth Amendment of the U.', 'search_seizure', 'Donald v. State', 'https://www.courtlistener.com/opinion/1443932/', '1443932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the totality of the circumstances, we conclude that the Superior Court did not abuse its discretion when it found that the administrative search of Harrison’s home was reasonable.', 'general', 'Donald v. State', 'https://www.courtlistener.com/opinion/1443932/', '1443932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Donald did not do that, we conclude that the Superior Court did not err when it denied the motion to suppress.', 'suppression', 'Donald v. State', 'https://www.courtlistener.com/opinion/1443932/', '1443932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Donald v. State', 'https://www.courtlistener.com/opinion/1443932/', '1443932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the officer’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'settled principles of law set forth above, we conclude that the officer’s decision to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even assuming that the officer''s conduct constituted the unauthorized practice of law, we conclude that suppression is not required in this case.', 'suppression', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In turn, we conclude that the court of appeals'' decision must be reversed, and Noble''s perjury conviction must be reinstated.', 'general', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the suppression of Noble''s testimony is not required in this case.', 'suppression', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the facts in this case do not support a finding of a due process violation.', 'general', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that, even assuming that the unauthorized practice of law was present in this case, suppression is not a valid remedy in this instance.', 'suppression', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we disagree with the court of appeals'' decision to suppress Noble''s testimony, and accordingly, we reverse the court''s decision overturning Noble''s conviction.', 'suppression', 'State v. Noble', 'https://www.courtlistener.com/opinion/2013483/', '2013483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion when it denied appellant’s motion to continue the trial of his case.', 'general', 'Smith v. Commonwealth', 'https://www.courtlistener.com/opinion/1202568/', '1202568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the facts presented by this record, we find that appellant’s motion for a continuance was not timely made and that the record fails to show that he was diligent in his efforts to obtain the evidence upon which his motion was based.', 'general', 'Smith v. Commonwealth', 'https://www.courtlistener.com/opinion/1202568/', '1202568') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the purpose of Wis.', 'general', 'State v. Leitner', 'https://www.courtlistener.com/opinion/2013656/', '2013656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we conclude that the words of Wis.', 'general', 'State v. Leitner', 'https://www.courtlistener.com/opinion/2013656/', '2013656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the court of appeals.', 'general', 'State v. Leitner', 'https://www.courtlistener.com/opinion/2013656/', '2013656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the decision of the court of appeals.', 'general', 'State v. Leitner', 'https://www.courtlistener.com/opinion/2013656/', '2013656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that section 5 — 8— 7(c) does not apply to this case.', 'general', 'People v. Roberson', 'https://www.courtlistener.com/opinion/1988963/', '1988963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[6]  In the Balint case, after acknowledging the general common-law rule that made knowledge of the facts an element of every crime, we held that as to statutory crimes the question is one of legislative intent,and that the Anti-Narcotic Act should be construed to authorize "punishment of a person for an act in violation of law[,][even] when ignorant of the facts making it so.', 'general', 'Staples v. United States', 'https://www.courtlistener.com/opinion/1087954/', '1087954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we conclude that the background rule of the common law favoring mens rea should govern interpretation of § 5861(d) in this case.', 'general', 'Staples v. United States', 'https://www.courtlistener.com/opinion/1087954/', '1087954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For example, in Balint, we concluded that the Narcotic Act of 1914, which was intended in part to minimize the spread of addictive drugs by criminalizing undocumented sales of certain narcotics, required proof only that the defendant knew that he was selling drugs, not that he knew the specific items he had sold were "narcotics" within the ambit of the statute.', 'general', 'Staples v. United States', 'https://www.courtlistener.com/opinion/1087954/', '1087954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4] The defendant knew that the items in his possession were grenades, and we concluded that § 5861(d) did not require the Government to prove the defendant also knew that the grenades were unregistered.', 'general', 'Staples v. United States', 'https://www.courtlistener.com/opinion/1087954/', '1087954') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, the court invoked the invited error doctrine, stating “because [the defendant’s] own procedural derelictions during discovery may have contributed to appellant’s inability to timely submit the amended affidavit, we hold that [the defendant] is estopped to assert untimeliness as a reason to deny consideration of the amended affidavit.', 'general', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that under the statute’s plain language, it applies to life insurance polices provided by an employer to an employee as well as to those acquired by the employer upon an employee.', 'general', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held the statute of limitations was tolled because the parents had concealed their fraud by not allowing the children to access the corporate checkbook or corporate tax information, falsifying their own tax documents, and refusing to divulge any information regarding their activities when asked by the children.', 'general', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in which this court held “[w]hen using the drastic remedy of default as a discovery sanction under T.', 'general', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2005), this court held that sales commissions, payable on a monthly basis based on the prior month’s accounting, and “based upon the profitability of the salesperson’s individual projects,” were not “wages” within the meaning of the Wage Payment Statute.', 'general', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that Law had not yet disclosed the forgery to Nichols, and that the statute of limitations had not run at the time Nichols amended her pleadings to allege forgery.', 'plea', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'According to this rationale, we conclude that it was improper to grant a judgment against Prime on Nichols’s claim for breach of fiduciary duty.', 'general', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these principles, we conclude that the appropriate standard of proof for damages following a default judgment is a preponderance of the evidence.', 'general', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not address the propriety of the trial court’s consideration of this evidence, however, as we conclude that the Defendants may not complain of the evidence submitted to and considered by the trial court for the simple reason that but for their flagrant discovery violations and stubborn refusal to provide Nichols with the documents to which she was entitled, she would have had this information much earlier in the proceedings and would have had no need to introduce this evidence via a p...', 'general', 'Prime Mortgage USA, Inc. v. Nichols', 'https://www.courtlistener.com/opinion/2036829/', '2036829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that convictions for attempted armed robbery and assault with a dangerous weapon against the same victim as a part of the same criminal incident merged.', 'general', 'Frye v. United States', 'https://www.courtlistener.com/opinion/1910074/', '1910074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that attempted AAWA and ADW merge, requiring the vacation of one of the convictions, and that although appellant has a right to be present at re-sentencing, any error in that regard was harmless beyond a reasonable doubt.', 'sentencing', 'Frye v. United States', 'https://www.courtlistener.com/opinion/1910074/', '1910074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the government, we conclude that there was sufficient evidence from which a reasonable jury could find appellant guilty of attempted AAWA.', 'general', 'Frye v. United States', 'https://www.courtlistener.com/opinion/1910074/', '1910074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the two offenses merge.', 'general', 'Frye v. United States', 'https://www.courtlistener.com/opinion/1910074/', '1910074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the trial court did not plainly err in failing to strike the government’s reference to the prior bad acts prior to the trial court’s ruling and instruction.', 'general', 'Frye v. United States', 'https://www.courtlistener.com/opinion/1910074/', '1910074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we conclude that appellant was entitled to an opportunity to alloeute.', 'general', 'Frye v. United States', 'https://www.courtlistener.com/opinion/1910074/', '1910074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm appellant’s conviction.', 'general', 'Frye v. United States', 'https://www.courtlistener.com/opinion/1910074/', '1910074') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We did not disturb the conviction but we held that "a sentence of death cannot be carried out if the jury that imposed or recommended it was chosen by excluding veniremen for cause simply because they voiced general objections to the death penalty or expressed conscientious or religious scruples against its infliction.', 'sentencing', 'Lockett v. Ohio', 'https://www.courtlistener.com/opinion/109935/', '109935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We are now faced with those questions and we conclude that the Eighth and Fourteenth Amendments require that the sentencer, in all but the rarest kind of capital case,[11] not be precluded from considering, as a mitigating factor, any aspect of a defendant''s character or record and any of the circumstances of the offense that the defendant proffers as a basis for a sentence less than death.', 'sentencing', 'Lockett v. Ohio', 'https://www.courtlistener.com/opinion/109935/', '109935') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the application of our State''s broader retroactivity jurisprudence to defendant''s PCR petition on collateral attack demonstrates that there should not be retroactive application of our decision in Anderson to defendant''s PCR petition.', 'general', 'State v. Purnell', 'https://www.courtlistener.com/opinion/1889536/', '1889536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that defendant is not permitted to collaterally attack his prior judgment of conviction for perjury by having the new rule announced in Anderson and Gaudin retroactively applied.', 'general', 'State v. Purnell', 'https://www.courtlistener.com/opinion/1889536/', '1889536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts of the case, we conclude that the procedure employed in defendant''s trial for perjury is a "far cry [different] from the kind of absolute prerequisite to the fundamental fairness that is `implicit in the concept of ordered liberty.', 'general', 'State v. Purnell', 'https://www.courtlistener.com/opinion/1889536/', '1889536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence should not have been suppressed.', 'suppression', 'State v. Patton', 'https://www.courtlistener.com/opinion/2432615/', '2432615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the term “defendant” includes all persons.', 'general', 'State v. Patton', 'https://www.courtlistener.com/opinion/2432615/', '2432615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), this court held that an unnecessary delay in taking a defendant before a magistrate in violation of Rule 5(a) does not mandate suppression of a statement obtained during the delay, but is only one of several
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court has a valid basis upon which to dismiss the second indictment.', 'dismissal', 'State v. Patton', 'https://www.courtlistener.com/opinion/2432615/', '2432615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court erred in dismissing counts one and two of the original indictment;', 'dismissal', 'State v. Patton', 'https://www.courtlistener.com/opinion/2432615/', '2432615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we find that the admission of the evidence will neither compromise any fundamental liberty interests nor serve to encourage unlawful police activity.', 'general', 'State v. Patton', 'https://www.courtlistener.com/opinion/2432615/', '2432615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'yet, we find that the trial court correctly determined that the defendant’s conduct did not constitute evidence tampering.', 'general', 'State v. Patton', 'https://www.courtlistener.com/opinion/2432615/', '2432615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'By the use of these guidelines, we find that the use of the word “defendant” does create some ambiguity.', 'general', 'State v. Patton', 'https://www.courtlistener.com/opinion/2432615/', '2432615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'thus we affirm in that regard.', 'general', 'State v. Patton', 'https://www.courtlistener.com/opinion/2432615/', '2432615') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As we did in Adkinson and Lord, we hold that if plaintiffs engaged in the criminal conduct they are accused of, then they alone should bear full responsibility for the consequences of their acts, including imprisonment.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Scott we held that the misdemeanor offense of operating a motor vehicle while under the influence of intoxicating liquor (OMVI) was a serious offense, even though the maximum term of imprisonment which *1334 could be imposed was one year.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that an assailant convicted of manslaughter for shooting and killing his victim with a shotgun had no claim for relief against either the manufacturer or the seller of the shotgun for direct personal losses alleged to have resulted from the shooting.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Scott this court held that prior criminal convictions can be admitted and given collateral estoppel effect if certain conditions are met.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that actual guilt was an affirmative defense.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal we affirmed in a discussion which implicitly assumed for the purpose of analysis that one cause of the victim''s death was a defect in the shotgun.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lord''s claim is barred for the same reasons we affirmed summary judgment against the plaintiff in Adkinson v.', 'general', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court''s dismissal of Burcina''s case on the authority of Adkinson, Lord, and Shaw: "[W]e conclude that the public policy principle which precludes a person who has been convicted of a crime from imposing liability on others for the consequences of his or her own antisocial conduct applies here.', 'dismissal', 'Howarth v. State, Public Defender Agency', 'https://www.courtlistener.com/opinion/1163175/', '1163175') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Palacio v. State', 'https://www.courtlistener.com/opinion/1229225/', '1229225') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the PCR court on this issue because there is no evidence of probative value to support the PCR court’s decision.', 'general', 'Palacio v. State', 'https://www.courtlistener.com/opinion/1229225/', '1229225') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the PCR court on this issue.', 'general', 'Palacio v. State', 'https://www.courtlistener.com/opinion/1229225/', '1229225') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because there is no question that Kelly’s mother did not actually possess the authority to consent to Detective Guillermo’s search of the Hauanios’ house, we hold that Detective Guillermo’s search of the Hauanios’ house violated article I, section 7 of the Hawai''i Constitution.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, based on the record before us, the prosecution has failed to meet its burden of proof that the evidence recovered from the Hauanios’ home would have been inevitably discovered lawfully pursuant to Sergeant Magnani’s investigation.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we hold that the circuit court’s COL 5(b) was not “wrong.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that the Hauanios were induced to make inculpatory statements and to consent to a search of their hotel room in violation of article I, sections 7 and 9 of the Hawaii Constitution.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 837, beyond that in which we are willing to engage at the expense of our constitution, we hold that it only applies to the admissibility of tangible physical evidence.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not err in suppressing the inculpatory statements of the Hauanios and the waivers of their rights to refuse consent to a search of the hotel room in which they were staying.', 'suppression', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we held that the inculpatory statements and the consent were induced as a result of a prior illegal search, and because the search of the hotel room was a direct result of the statements and consent to search, we hold that the evidence recovered amounts to “fruits” of the prior illegality.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summation, we hold that: (1) Detective Guillermo’s initial entrance into the Hauan-ios’ home was a “search” in the constitutional sense;', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the Hauanios were induced to make the statements in violation of their constitutional rights, there is no need for us to reach the issue whether these statements were obtained after they invoked their right to have counsel present during questioning.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the circuit court’s order granting the Hauanios’ motion to suppress evidence and for the return of all non-contraband property to the Hauanios.', 'suppression', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1288237/', '1288237') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the oral statements made by Brennan were properly suppressed.', 'suppression', 'Commonwealth v. Brennan', 'https://www.courtlistener.com/opinion/2102837/', '2102837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There we held that the Commonwealth could not compel a defendant to produce a certain gun in circumstances where the Commonwealth sought to determine, among other things, the existence, location, and possessor of the gun.', 'general', 'Commonwealth v. Brennan', 'https://www.courtlistener.com/opinion/2102837/', '2102837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither the Fourteenth Amendment nor art.', 'general', 'Commonwealth v. Brennan', 'https://www.courtlistener.com/opinion/2102837/', '2102837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the protections afforded by the Fifth Amendment are not available to an accused who submits to a breathalyzer test.', 'general', 'Commonwealth v. Brennan', 'https://www.courtlistener.com/opinion/2102837/', '2102837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that field sobriety tests do not elicit testimonial or communicative evidence and therefore do not trigger the protections afforded by the Fifth Amendment.', 'general', 'Commonwealth v. Brennan', 'https://www.courtlistener.com/opinion/2102837/', '2102837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that art.', 'general', 'Commonwealth v. Brennan', 'https://www.courtlistener.com/opinion/2102837/', '2102837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the production of the gun by the defendant would have revealed the defendant’s knowledge about its existence, location, and control, we concluded that the resulting evidence would have been testimonial and therefore protected by the Fifth Amendment from compelled disclosure.', 'general', 'Commonwealth v. Brennan', 'https://www.courtlistener.com/opinion/2102837/', '2102837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we find that the officers conducting the search of Anderson’s vehicle maintained
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that it could still reasonably color the officers’ perception of the surrounding circumstances
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the district court’s denial of Anderson’s motion to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that he was entitled to an instruction on the lesser
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Thus, we conclude that the statute is implicated by any lawful order or direction given by a law enforcement officer, by a traffic crash investigation officer, by a traffic infraction enforcement officer, or by a “member of the fire department at the scene of a fire, rescue operation, or other emergency.', 'general', 'Koch v. State', 'https://www.courtlistener.com/opinion/2546674/', '2546674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse his conviction for fleeing and eluding a law enforcement officer and remand for a new trial.', 'general', 'Koch v. State', 'https://www.courtlistener.com/opinion/2546674/', '2546674') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon these many authorities, we hold that when a party appeals a lower court’s ruling to the Supreme Court of Appeals of West Virginia and he/she is required to post an appeal bond, his/her failure to post such bond will result in the dismissal of that party’s appeal and the consequent affirmance, as to that party, of the lower court’s ruling.', 'dismissal', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that an appellant/defendant may not assign as error a circuit court’s affirmative assertion of personal jurisdiction over a coappellant/codefendant when the coappellant/codefendant either has not challenged the assertion of personal jurisdiction over him/her or has otherwise, by his/her acts and/or omissions, waived his/her right to challenge the personal jurisdiction ruling.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the instant a child is born, both unwed biological parents have a right to establish a parent-child relationship with their child.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we hold that any person or persons who plot, plan, scheme, or otherwise conspire to affirmatively, intentionally, and willfully conceal information regarding a newborn child’s birth or physical location, or indicating where and in whose care the child may be found, in response to inquiries by the child’s parent for such information, may be held liable for his/ her or their participation in such civil conspiracy.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because this relationship is so intimately connected with the parent’s person, we hold that where there is an intentional interference with a parent’s custody of his or her child, an injured parent is entitled to a remedy that completely compensates him or her.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a parent47 may maintain a cause of action against one who tortiously interferes with the parent’s parental or custodial relationship with his/her minor child, which right accrues the instant the child is born.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that where a parent presents a prima facie case of tortious interference with his/her parental or custodial relationship, the party interfering with such relationship may assert the affirmative defense of justification, ie.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lastly, we hold that a parent cannot charge his/her child’s other parent with tortious interference with parental or custodial relationship if both parents have equal rights, or substantially equal rights (as in the case of a nonmarital child where the putative biological father seeks to establish a meaningful parent-child relationship with his child and, until such a relationship has been commenced, does not have rights identical to those of the child’s biological mother), to establish or ma...', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Interstate Compact on the Placement of Children (ICPC), set forth in W.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 260 (1982), we held that “[a]n intended beneficiary may sue for tortious interference with a testamentary bequest.', 'general', 'Kessel v. Leavitt', 'https://www.courtlistener.com/opinion/1229609/', '1229609') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in the instant Mississippi prosecution Neal may invoke all rights secured to him by the Constitution and laws of this state, in addition, of course, to those rights secured by the Constitution of the United States, even with respect to the admissibility of the confession Neal gave in California.', 'general', 'Neal v. State', 'https://www.courtlistener.com/opinion/1869722/', '1869722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), wherein we held that evidence of burglary and attempted rape were admissible in a capital murder prosecution where defendant was charged with the killing of a police officer as distinguished from felony murder.', 'general', 'Neal v. State', 'https://www.courtlistener.com/opinion/1869722/', '1869722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having well in mind our limited scope of review in matters such as these, we affirm.', 'general', 'Neal v. State', 'https://www.courtlistener.com/opinion/1869722/', '1869722') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the offense of first degree arson set forth in West Virginia Code § 61-3-1(a) is not a lesser included offense of arson resulting in serious bodily injury which is set forth in West Virginia Code § 61-3-7(b).', 'general', 'STATE EX REL. GAMES-NEELY v. Silver', 'https://www.courtlistener.com/opinion/1346692/', '1346692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1] Upon our careful review of the statutory offenses at issue, we conclude that the trial court''s decision to dismiss the charge of first degree arson based on double jeopardy concerns was in error.', 'dismissal', 'STATE EX REL. GAMES-NEELY v. Silver', 'https://www.courtlistener.com/opinion/1346692/', '1346692') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[2] Accordingly, we reverse.', 'general', 'STATE EX REL. GAMES-NEELY v. Silver', 'https://www.courtlistener.com/opinion/1346692/', '1346692') ON CONFLICT DO NOTHING;
