INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the arrest was legal, on the basis of the violation of the CPO, we need not address the state’s alternative argument that the arrest was valid because the officer had probable cause to believe that Whiteley had committed a felony, kidnapping.', 'probable_cause', 'State v. Whiteley', 'https://www.courtlistener.com/opinion/1155015/', '1155015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we hold that the district court did not err in refusing to suppress statements made by Whiteley.', 'suppression', 'State v. Whiteley', 'https://www.courtlistener.com/opinion/1155015/', '1155015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the fact that all three tapes were heard by the jury during the trial, we hold that the court did not abuse its discretion by deciding initially not to provide the jury with a tape player.', 'general', 'State v. Whiteley', 'https://www.courtlistener.com/opinion/1155015/', '1155015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that there was no reasonable possibility that the action complained of contributed to the conviction.', 'general', 'State v. Whiteley', 'https://www.courtlistener.com/opinion/1155015/', '1155015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the applicable standards and the evidence presented in the record, we hold that there exists substantial, competent evidence to sustain the jury’s verdict.', 'general', 'State v. Whiteley', 'https://www.courtlistener.com/opinion/1155015/', '1155015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgments of conviction.', 'general', 'State v. Whiteley', 'https://www.courtlistener.com/opinion/1155015/', '1155015') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court erred when it sentenced appellant to 240 months for check forgery, and we vacate the sentence and remand to the district court for a determination of a reasonable sentence for the offense.', 'sentencing', 'Vickla v. State', 'https://www.courtlistener.com/opinion/1897271/', '1897271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that appellant’s sentence is unreasonable and excessive, we reverse and remand for resentencing.', 'sentencing', 'Vickla v. State', 'https://www.courtlistener.com/opinion/1897271/', '1897271') ON CONFLICT DO NOTHING;
