INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant’s sentence is not commensurate with the gravity of the crime and therefore is unreasonable and excessive.', 'sentencing', 'Vickla v. State', 'https://www.courtlistener.com/opinion/1897271/', '1897271') ON CONFLICT DO NOTHING;
