INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1108, we concluded that “[t]here was ample evidence, most of which was not denied, to justify revocation.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our review of Wyoming probation revocation statutes and case law, we find that it is possible to delineate revocation procedures within four relatively distinct categories: (1) Wyo.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'NOW, THEREFORE, IT IS ORDERED that the Defendant be remanded to the custody of the Sheriff of Natrona County, Wyoming, where he shall serve a term of nine (9) months in the Natrona County Jail, with credit for 188 day(s) served previously in the Natrona County Jail.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse this aspect of the district court’s actions in this case.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the sentence entered and authorize the district court to resentence Raymond Wlodarczyk to confinement for a period no longer than the term remaining on the three year probationary period on the day the petition for revocation was filed.', 'sentencing', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the revocation of probation on the basis of the charges presented and the admitted violations precluding use of intoxicating beverages.', 'general', 'Wlodarczyk v. State', 'https://www.courtlistener.com/opinion/1445024/', '1445024') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in which this court held that if two statutes require proof of identical elements, the specific statute controls over the general statute, unless the legislature manifestly intends otherwise.', 'general', 'State v. Meyer', 'https://www.courtlistener.com/opinion/2013820/', '2013820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the district court did not err, we affirm.', 'general', 'State v. Meyer', 'https://www.courtlistener.com/opinion/2013820/', '2013820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court properly construed “selling,” as the word is used in MinmStat.', 'general', 'State v. Meyer', 'https://www.courtlistener.com/opinion/2013820/', '2013820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that “selling,” as that word is used in MinmStat.', 'general', 'State v. Meyer', 'https://www.courtlistener.com/opinion/2013820/', '2013820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the unobjected to errors of the judge and the prosecutor in this case are fundamental, obvious, and substantial;', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that these errors constitute plain error.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the facts of this case give rise to plain error and thus warrant a new trial.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the errors constitute plain error.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that even though disparaging remarks by both the prosecutor and the defense counsel were improper, those errors did not require a new trial based on plain error or in the interest of justice.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today we find that the errors constitute plain error.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we reverse the court of appeals'' decision and remand to the circuit court for a new trial.', 'general', 'State v. Jorgensen', 'https://www.courtlistener.com/opinion/1287803/', '1287803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no indication that either prospective juror Lemon or prospective juror Scott would have been "unable faithfully and impartially to apply the law," we conclude that the trial court did not abuse its discretion in refusing to disqualify them.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/2504905/', '2504905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Osborne to commit the murder, we conclude that the trial court did not err in denying Mr.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/2504905/', '2504905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, since its holding is not contrary to Rule 801(d), we find that State v.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/2504905/', '2504905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set out above, we affirm the judgment finding Mr.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/2504905/', '2504905') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred, and because jeopardy has not attached, we remand for further proceedings.', 'general', 'State v. Rhea', 'https://www.courtlistener.com/opinion/2023392/', '2023392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We conclude that the district court erred in holding that the credit card account numbers on the statements Rhea took from FDR did not constitute financial transaction devices as defined by § 28-618(7).', 'general', 'State v. Rhea', 'https://www.courtlistener.com/opinion/2023392/', '2023392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our independent review, we conclude that the final sentence of § 28-618(7) requires that for purposes of Neb.', 'sentencing', 'State v. Rhea', 'https://www.courtlistener.com/opinion/2023392/', '2023392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that jeopardy has not attached.', 'general', 'State v. Rhea', 'https://www.courtlistener.com/opinion/2023392/', '2023392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our independent review of the pertinent penal statutes and the record in this case, we conclude that the district court erred in sustaining Rhea’s plea in abatement and in dismissing the charges which were the subject thereof.', 'dismissal', 'State v. Rhea', 'https://www.courtlistener.com/opinion/2023392/', '2023392') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that paragraph 2V is a nullity, and Ricci has not waived the right to appeal his sentence.', 'sentencing', 'Ricci v. State', 'https://www.courtlistener.com/opinion/2013932/', '2013932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Ricci has failed to carry his burden to establish that his sentence is inappropriate in light of the nature of the offenses and his character.', 'sentencing', 'Ricci v. State', 'https://www.courtlistener.com/opinion/2013932/', '2013932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ricci v. State', 'https://www.courtlistener.com/opinion/2013932/', '2013932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Glotzbach v. State', 'https://www.courtlistener.com/opinion/2022056/', '2022056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons we affirm Glotzbach''s conviction for public indecency as a class D felony.', 'general', 'Glotzbach v. State', 'https://www.courtlistener.com/opinion/2022056/', '2022056') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant''s speedy-trial motion did not present an issue of fact outside the record material to the court''s disposition of the motion, we hold that the trial court did not err in dismissing the motion without an evidentiary hearing.', 'dismissal', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the asserted error is not of such magnitude as to have denied defendant a fair trial.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the trial court did not abuse its discretion in denying defendant''s motion for a mistrial.', 'mistrial', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court did not abuse its discretion in denying defendant''s motions for a new trial.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that trial counsel was not ineffective in failing to object to evidence of spousal abuse.', 'ineffective_assistance', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that any error in the State''s examination of Andre Franklin was cured by the trial court''s action in immediately sustaining defendant''s objection.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our examination of the evidence in light of the foregoing principles, we conclude that a rational trier of fact could have found defendant guilty of the first degree murders of Masters and Beasley beyond a reasonable doubt.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such is the case here, and that the jury could properly *538 reject defendant''s theory of innocence.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is not so unreasonable, improbable or unsatisfactory as to justify a reasonable doubt of defendant''s guilt.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the evidence merely narrowed the class of individuals who may have killed the victim, but that it did not point specifically to the defendant, as there were two other men with the defendant on the night of the shooting, both of whom also wore dark clothing.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that the substitution of the alternate juror after deliberations had begun constituted prejudicial error.', 'general', 'Alcalde v. State', 'https://www.courtlistener.com/opinion/2625308/', '2625308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Alcalde''s conviction and remand for a new trial.', 'general', 'Alcalde v. State', 'https://www.courtlistener.com/opinion/2625308/', '2625308') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the unambiguous terminology employed in this section, we hold that the plain language of W.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Allen''s flight convictions do not offend constitutional principles of double jeopardy, and we affirm the trial court''s rulings in this regard.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the sentences imposed for Allen''s numerous misdemeanor convictions, we find that the trial court properly sentenced the defendant in accordance with the statutorily-prescribed punishments for such crimes.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed such evidence, we are not left with the impression that there remains a reasonable doubt as to Allen''s guilt of these crimes nor do we find that his convictions were tarnished by "misapprehension, or passion and prejudice.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the decision of the Wood County Circuit Court.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no impermissible factors influenced the trial court''s sentencing decision, we affirm the lower court''s ruling.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error with the trial court''s refusal of Allen''s duress or coercion instruction or with the court''s sentencing of the *106 defendant to consecutive sentences in the county jail for his multiple misdemeanor convictions, we affirm the decision of the Circuit Court of Wood County.', 'sentencing', 'State v. Allen', 'https://www.courtlistener.com/opinion/1358578/', '1358578') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we have rejected the (F)(6) finding, *119 leaving pecuniary gain as the sole aggravator, upon independent reweighing we conclude that the mitigation, considered individually and collectively, is not sufficiently substantial to warrant leniency.', 'general', 'State v. Greene', 'https://www.courtlistener.com/opinion/1210792/', '1210792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 42 We find that the statement and letters certainly demonstrate Greene''s vile state of mind and callous attitude toward the murder.', 'general', 'State v. Greene', 'https://www.courtlistener.com/opinion/1210792/', '1210792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse the kidnapping conviction and order the entry of a judgment of acquittal on the kidnapping charge.', 'general', 'State v. Greene', 'https://www.courtlistener.com/opinion/1210792/', '1210792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we reverse the kidnapping conviction, the robbery conviction remains as a sufficient predicate crime to affirm Greene''s felony murder conviction.', 'general', 'State v. Greene', 'https://www.courtlistener.com/opinion/1210792/', '1210792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction for kidnapping and order that a judgment of acquittal be entered on that count.', 'general', 'State v. Greene', 'https://www.courtlistener.com/opinion/1210792/', '1210792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm except as to the kidnapping conviction.', 'general', 'State v. Greene', 'https://www.courtlistener.com/opinion/1210792/', '1210792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 63 We affirm Greene''s convictions and sentences for first degree murder, robbery, theft, and forgery,[2] including the sentence of death.', 'sentencing', 'State v. Greene', 'https://www.courtlistener.com/opinion/1210792/', '1210792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In three other cases, where we affirmed the death sentences, there are striking similarities.', 'sentencing', 'State v. Greene', 'https://www.courtlistener.com/opinion/1210792/', '1210792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Circuit Court erred when it excluded the defense witnesses without following the Box guidelines.', 'general', 'Houston v. State', 'https://www.courtlistener.com/opinion/1150417/', '1150417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Over defense objections this Court held the evidence "indicating a series of injuries inflicted upon the child" relevant on grounds that it
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'Houston v. State', 'https://www.courtlistener.com/opinion/1150417/', '1150417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though we reverse on the point just noted, the pre-trial discovery issue concerns a recurring problem requiring discussion and comment.', 'general', 'Houston v. State', 'https://www.courtlistener.com/opinion/1150417/', '1150417') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this court has jurisdiction to address the merits of the prosecution''s appeal, inasmuch as the prosecution filed its notice of appeal within thirty days of the effective dates of both the written order granting Bohannon''s motions to suppress and to dismiss and the written order denying the prosecution''s motion for reconsideration, which was therefore timely pursuant to Hawai`i Rules of Appellate Procedure (HRAP) Rule 4(b) (1999).', 'suppression', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That being the case, we hold that the prosecution''s notice of appeal "is sufficient in form," id.', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the same rule of strict construction applies to the Rule 4(b) HRAP requirement that the State must file its notice of appeal within 30 days of the entry of the judgment or order appealed from.', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] Accordingly, we hold that, in order to appeal a criminal matter in the district court, the appealing party must appeal from a written judgment or order that has been filed with the clerk of the court pursuant to HRAP Rule 4(b)(3).', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, viewing the present matter from the totality of the circumstances known to Officer Kashimoto at the time of the incident, we hold that his investigative stop of Bohannon was "within the parameters of permissible police conduct," Barnes, 58 Haw.', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of an express statement to the contrary, we hold that the motion for reconsideration is not a tolling motion.', 'general', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1009 (1986), this court held that a motion to reconsider filed by the prosecution under HRPP Rule 47 following the granting of a motion to suppress does not toll the time for appeal of the suppression order.', 'suppression', 'State v. Bohannon', 'https://www.courtlistener.com/opinion/2625336/', '2625336') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not abuse its discretion by overruling the appellant’s disclosure motion.', 'general', 'State v. Reedy', 'https://www.courtlistener.com/opinion/1340613/', '1340613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 346 (1980), we held that “a general indictment as a principal in the first degree shall be sufficient to sustain a conviction regardless of whether the evidence demonstrates that the defendant was a principal, aider and abettor, or accessory before the fact.', 'general', 'State v. Reedy', 'https://www.courtlistener.com/opinion/1340613/', '1340613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 666 (1974), this Court held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court committed no error by giving the principal in the second degree instruction.', 'general', 'State v. Reedy', 'https://www.courtlistener.com/opinion/1340613/', '1340613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that the aiding and abetting instruction was proper.', 'general', 'State v. Reedy', 'https://www.courtlistener.com/opinion/1340613/', '1340613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we find that the trial court properly followed our holding in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the appellant’s convictions
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the appellant’s daytime burglary and recidivist convictions.', 'general', 'State v. Reedy', 'https://www.courtlistener.com/opinion/1340613/', '1340613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we reverse the appellant’s daytime burglary and recidivist convictions, and we remand this matter to the Circuit Court of Clay County for a new trial consistent with this opinion.', 'general', 'State v. Reedy', 'https://www.courtlistener.com/opinion/1340613/', '1340613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court abused its discretion in faffing to grant a new trial on excessive damages or, alternatively, to order a remittitur.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury verdicts were not based on passion or prejudice.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that while the compensatory damages awarded in this case were not the result of passion or prejudice, they do shock the conscience of this court.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court abused its discretion in not granting a new trial due to excessive punitive-damages awards or, alternatively, in failing to grant a remittitur.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When the instructions are read as a whole, we hold that they are not binding.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit court abused its discretion by not granting a new trial due to excessive damages under Ark.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that “at the conclusion of the evidence” means exactly that — when all the evidence is in.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing all of the pertinent evidence together, we conclude that punitive damages were indeed appropriate in this case.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an award of $63 million in punitive damages shocks the conscience of this court as a civil penalty.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though the Sauer Estate’s counsel disputed this at oral argument, we conclude that the three Gore criteria must be given equal weight.', 'general', 'Advocat, Inc. v. Sauer', 'https://www.courtlistener.com/opinion/1758759/', '1758759') ON CONFLICT DO NOTHING;
