INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the seizure was lawful, we affirm the turnover order.', 'general', 'Michael Hodges v. State of Indiana', 'https://www.courtlistener.com/opinion/4633575/', '4633575') ON CONFLICT DO NOTHING;
