INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), we held that, for purposes of double jeopardy, the statutory elements of Alaska’s crack-house statute, AS 11.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/1123473/', '1123473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the plain meaning of “keep” and “maintain” should govern the application of Alaska’s crack-house statute.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/1123473/', '1123473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In particular, we conclude that the statute must be construed to require a finding of continuity and to preclude conviction for an isolated incident of possession or distribution.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/1123473/', '1123473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that awareness of the illegal use is required.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/1123473/', '1123473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that, under Alaska’s crack-house statute, the accused must act knowingly both with respect to the proscribed conduct of keeping or maintaining property that is used for the purpose of illegal storage or distribution of controlled substances and with respect to the existence of the illegal use itself.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/1123473/', '1123473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To summarize, we conclude that, to establish a violation of AS 11.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/1123473/', '1123473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, even though Dawson failed to object to the jury instruction covering the elements of the offense, we conclude that allowing Dawson’s convictions to stand on even two of the crack-house counts would amount to plain error.', 'jury_instruction', 'Dawson v. State', 'https://www.courtlistener.com/opinion/1123473/', '1123473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that, as imposed, the challenged condition is unduly restrictive of liberty and cannot withstand scrutiny.', 'general', 'Dawson v. State', 'https://www.courtlistener.com/opinion/1123473/', '1123473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989), when we held that the culpable mental state of "knowingly" must apply to the surrounding circumstances in the statute prohibiting the unauthorized use of a motor vehicle.', 'general', 'Schultz v. State', 'https://www.courtlistener.com/opinion/1640345/', '1640345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Beggs this Court held that in a trial for injury to a child, the jury must be instructed that they cannot find the defendant guilty unless they find that he intended the result of his conduct.', 'general', 'Schultz v. State', 'https://www.courtlistener.com/opinion/1640345/', '1640345') ON CONFLICT DO NOTHING;
