INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Alternatively, if we find that the 1999 agreement did not authorize the arrest, we must determine whether the Lexington County officers effectuated a proper citizen’s arrest.', 'general', 'State v. Boswell', 'https://www.courtlistener.com/opinion/2393086/', '2393086') ON CONFLICT DO NOTHING;
