INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our harmless-error analysis in this case, we held that the evidence presented at trial, though largely circumstantial, nevertheless was overwhelming in support of defendant’s convictions.', 'general', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the well-established rule, pre-Crawford, that confrontation clause violations were subject to harmless-error analysis, and the numerous post-Crawford decisions applying harmless-error review to Crawford violations, as well as the Supreme Court’s admonition not to assume the implicit overruling of a Supreme Court decision, we conclude that Crawford violations are subject to harmless-error analysis.', 'general', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the presence and strength of the other evidence establishing the points raised in Rivera’s grand jury testimony, as well as the overwhelming nature of the evidence, other than Rivera’s testimony, supporting defendant’s convictions, we conclude that the State has proven beyond a reasonable doubt that the admission of Rivera’s testimony did not contribute to the verdict obtained.', 'general', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on these definitions, we conclude that “a photograph is the exposure of the film at the time the picture is snapped.', 'general', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, with regard to the challenging of Gannon’s qualifications as an expert, it cannot be said that counsel failed to conduct meaningful adversarial testing.', 'general', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State’s questioning of Gannon regarding the availability of the DNA sample did not constitute reversible error.', 'general', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking at this evidence in the light most favorable to the prosecution, we conclude that a rational trier of fact could have found the essential elements of the crimes charged beyond a reasonable doubt.', 'general', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the appellate court.', 'general', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the appellate court, which affirmed defendant’s convictions and sentence.', 'sentencing', 'People v. Patterson', 'https://www.courtlistener.com/opinion/2132698/', '2132698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is no merit to the points raised, and we affirm.', 'general', 'Isom v. State', 'https://www.courtlistener.com/opinion/1770491/', '1770491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we hold that a sentence of death cannot be carried out if the jury that imposed or recommended it was chosen by excluding veniremen for cause simply because they voiced general objections to the death penalty or expressed conscientious or religious scruples against its infliction.', 'sentencing', 'Isom v. State', 'https://www.courtlistener.com/opinion/1770491/', '1770491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Mr.', 'general', 'Isom v. State', 'https://www.courtlistener.com/opinion/1770491/', '1770491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was more than sufficient evidence, direct and circumstantial, that Mr.', 'general', 'Isom v. State', 'https://www.courtlistener.com/opinion/1770491/', '1770491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit judge did not abuse his discretion in refusing to allow Mr.', 'general', 'Isom v. State', 'https://www.courtlistener.com/opinion/1770491/', '1770491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this issue does not fall within that exception.', 'general', 'Isom v. State', 'https://www.courtlistener.com/opinion/1770491/', '1770491') ON CONFLICT DO NOTHING;
