INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when a prosecutor seeks to lessen the jury’s responsibility for rendering a verdict of death, this qualifies as a situation for when the circuit judge should intervene.', 'general', 'Isom v. State', 'https://www.courtlistener.com/opinion/1770491/', '1770491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In looking at the comments of the State, the comments of the judge, and the comments of the defense, we conclude that the prosecutor’s comments were not so flagrant as to require the judge to intervene sua sponte.', 'general', 'Isom v. State', 'https://www.courtlistener.com/opinion/1770491/', '1770491') ON CONFLICT DO NOTHING;
