INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Kendall Johnson v. State of Indiana', 'https://www.courtlistener.com/opinion/2727549/', '2727549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Kendall Johnson v. State of Indiana', 'https://www.courtlistener.com/opinion/2727549/', '2727549') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not and reverse.', 'general', 'State v. Scharmer', 'https://www.courtlistener.com/opinion/1309378/', '1309378') ON CONFLICT DO NOTHING;
