INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the statute did not regulate speech and observed that "internet conversations and e-mails .', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals'' decision.', 'general', 'State v. Baron', 'https://www.courtlistener.com/opinion/2098887/', '2098887') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Casey v. State', 'https://www.courtlistener.com/opinion/1409044/', '1409044') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the use of this language violated due process because the defendant could be convicted in the absence of all facts being proven beyond a reasonable doubt.', 'general', 'State v. Brouillette', 'https://www.courtlistener.com/opinion/2018274/', '2018274') ON CONFLICT DO NOTHING;
