INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 31 (1980), we held that the trial court''s charge to the jury erroneously included reference to parole eligibility.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 329 (1987), we held that a curative instruction for the jury not to consider parole was unnecessary since the reference to parole was in the context of the defendant''s commission of prior crimes, not to its possibility in the event of a life sentence on the crime charged.', 'sentencing', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 587 (1988), this Court held that the trial court properly refused the defendant''s ex post facto application of increased time for parole eligibility.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4]  In the interim, this Court held in State v.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the appellant has failed to demonstrate that he was prejudiced by the trial judge''s ruling.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court committed prejudicial error in denying appellant''s request to charge based upon section 24-21-640, in violation of the Eighth and Fourteenth Amendments of the United States Constitution and Article V, § 21, of the South Carolina Constitution.', 'general', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the solicitor''s jury arguments during the penalty phase require that appellant''s sentence of death be vacated.', 'sentencing', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse appellant''s death sentence and remand for a new sentencing proceeding.', 'sentencing', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and sentence of life imprisonment, reverse the death sentence, and remand for a new sentencing proceeding.', 'sentencing', 'State v. Torrence', 'https://www.courtlistener.com/opinion/1354792/', '1354792') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reason, we find that the appellate court in Gaffney erred in holding that the second criteria— whether the conduct occurred substantially within the authorized time and space limits of the employment— was relevant but not dispositive.', 'general', 'Adames v. Sheahan', 'https://www.courtlistener.com/opinion/2143062/', '2143062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the substance of the appellate court’s ruling, we find that the appellate court erred in finding that David was acting within the scope of his employment and that Sheahan is liable for David’s tortious acts.', 'general', 'Adames v. Sheahan', 'https://www.courtlistener.com/opinion/2143062/', '2143062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that Sheahan was entitled to summary judgment based upon respondeat superior, there is no need to address Sheahan’s remaining arguments concerning duty and proximate cause, nor do we need to remand to the trial court for consideration of Sheahan’s immunity claims.', 'general', 'Adames v. Sheahan', 'https://www.courtlistener.com/opinion/2143062/', '2143062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that plaintiffs’ lawsuit is a qualified civil liability action as defined in the PLCAA.', 'general', 'Adames v. Sheahan', 'https://www.courtlistener.com/opinion/2143062/', '2143062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that plaintiffs’ lawsuit was a qualified civil liability action, we next address whether the exceptions to the PLCAA apply in this case.', 'general', 'Adames v. Sheahan', 'https://www.courtlistener.com/opinion/2143062/', '2143062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As stated, we find that the PLCAA requires dismissal of plaintiffs’ failure to warn claim against Beretta.', 'dismissal', 'Adames v. Sheahan', 'https://www.courtlistener.com/opinion/2143062/', '2143062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review, we find that we need not consider whether the appellate court erred in finding that the Beretta was not unreasonably dangerous under the consumer expectation test and the risk-utility test.', 'general', 'Adames v. Sheahan', 'https://www.courtlistener.com/opinion/2143062/', '2143062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For that reason, we affirm the dismissal of those claims.', 'dismissal', 'Adames v. Sheahan', 'https://www.courtlistener.com/opinion/2143062/', '2143062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant who wishes to use this kind of evidence at trial must obtain a preliminary ruling from the trial court that it is admissible.', 'general', 'Covington v. State', 'https://www.courtlistener.com/opinion/1358982/', '1358982') ON CONFLICT DO NOTHING;
