INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed and remanded because the trial court had based its ruling solely on the constitutional amendment and had ignored the statutory scheme that still applied to bail appeals.', 'general', 'State v. Pellerin', 'https://www.courtlistener.com/opinion/1057221/', '1057221') ON CONFLICT DO NOTHING;
