INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we hold that it is the best method.', 'general', 'Tallent v. State', 'https://www.courtlistener.com/opinion/2611390/', '2611390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a trial judge can not do this.', 'general', 'Tallent v. State', 'https://www.courtlistener.com/opinion/2611390/', '2611390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal, this court held that AS 4.', 'general', 'Tallent v. State', 'https://www.courtlistener.com/opinion/2611390/', '2611390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a defendant is entitled to have the grand jury and the petit jury decide all essential elements of the charged offense, this court held that Morgan’s trial judge should have dismissed the indictment, and that the judge later erred “in not permitting the trial jury to decide whether the state had proved beyond a reasonable doubt the prior conviction element of this offense.', 'dismissal', 'Tallent v. State', 'https://www.courtlistener.com/opinion/2611390/', '2611390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that a defendant’s prior bootlegging conviction was an element of the offense, and the State would have to prove the prior conviction at trial.', 'general', 'Tallent v. State', 'https://www.courtlistener.com/opinion/2611390/', '2611390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1988), this court held that, under Crimi
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the existence of a defendant’s prior convictions is an element of the offense.', 'general', 'Tallent v. State', 'https://www.courtlistener.com/opinion/2611390/', '2611390') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that we need not resolve this issue.', 'general', 'Tallent v. State', 'https://www.courtlistener.com/opinion/2611390/', '2611390') ON CONFLICT DO NOTHING;
