INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '086(a), we conclude that the requirement of jail time as a special condition of probation was illegal, and that the sentence must therefore be vacated and the case remanded for resentencing.', 'sentencing', 'Whittlesey v. State', 'https://www.courtlistener.com/opinion/2613837/', '2613837') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that not every encounter between police officers and citizens amounts to a seizure of the person of the citizen, thus implicating constitutional rights, and we conclude that none of the other claims by Collins or the suggestion by the State constitutes error requiring reversal.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1448073/', '1448073') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistently, with that opinion, we hold that the crime of burglary as defined by Wyo.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1448073/', '1448073') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We made this proposition even more precise some two years later when we reversed a conviction relating to a confusing instruction defining reasonable doubt.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1448073/', '1448073') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), we affirmed a conviction of burglary of two automobiles.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1448073/', '1448073') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a person has been “seized” within the meaning of the Fourth Amendment only if, in view of all the circumstances surrounding the incident, a reasonable person would have believed that he was not free to leave.', 'search_seizure', 'Collins v. State', 'https://www.courtlistener.com/opinion/1448073/', '1448073') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Mathewses'' policy does not cover the plaintiffs'' claims because Jeffrey''s actions were not accidental and, thus, did not give rise to an "occurrence.', 'general', 'ESTATE OF SUSTACHE v. American Family Mutual Insurance Company', 'https://www.courtlistener.com/opinion/2009491/', '2009491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 4 After carefully considering the facts and circumstances of this case, especially the allegations of the complaint and the pertinent homeowner''s policy, we conclude that the Mathewses'' homeowner''s policy does not provide coverage for the plaintiffs'' claims.', 'general', 'ESTATE OF SUSTACHE v. American Family Mutual Insurance Company', 'https://www.courtlistener.com/opinion/2009491/', '2009491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 51 We conclude that the allegations in the plaintiffs'' first amended complaint, supplemented by Jeffrey''s deposition,[12] cannot reasonably be construed to constitute a covered claim under the Mathewses'' homeowner''s policy.', 'general', 'ESTATE OF SUSTACHE v. American Family Mutual Insurance Company', 'https://www.courtlistener.com/opinion/2009491/', '2009491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 56 We conclude that no reasonable person would regard the alleged intentional battery perpetrated by Jeffrey against Sustache as an "unexpected .', 'general', 'ESTATE OF SUSTACHE v. American Family Mutual Insurance Company', 'https://www.courtlistener.com/opinion/2009491/', '2009491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 61 After carefully considering the facts and circumstances of this case, especially the allegations of the complaint and the pertinent homeowner''s policy, we conclude that the Mathewses'' homeowner''s policy does not provide coverage for the plaintiffs'' claims.', 'general', 'ESTATE OF SUSTACHE v. American Family Mutual Insurance Company', 'https://www.courtlistener.com/opinion/2009491/', '2009491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the court of appeals.', 'general', 'ESTATE OF SUSTACHE v. American Family Mutual Insurance Company', 'https://www.courtlistener.com/opinion/2009491/', '2009491') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant’s speedy-trial motion did not present an issue of fact outside the record material to the court’s disposition of the motion, we hold that the trial court did not err in dismissing the motion without an evidentiary hearing.', 'dismissal', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we hold that the asserted error is not of such magnitude as to have denied defendant a fair trial.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the trial court did not abuse its discretion in denying defendant’s motion for a mistrial.', 'mistrial', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court did not abuse its discretion in denying defendant’s motions for a new trial.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that trial counsel was not ineffective in failing to object to evidence of spousal abuse.', 'ineffective_assistance', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that any error in the State’s examination of Andre Franklin was cured by the trial court’s action in immediately sustaining defendant’s objection.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our examination of the evidence in light of the foregoing principles, we conclude that a rational trier of fact could have found defendant guilty of the first degree murders of Masters and Beasley beyond a reasonable doubt.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that such is the case here, and that the jury could properly reject defendant’s theory of innocence.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence is not so unreasonable, improbable or unsatisfactory as to justify a reasonable doubt of defendant’s guilt.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the evidence merely narrowed the class of individuals who may have killed the victim, but that it did not point specifically to the defendant, as there were two other men with the defendant on the night of the shooting, both of whom also wore dark clothing.', 'general', 'People v. Hall', 'https://www.courtlistener.com/opinion/2014176/', '2014176') ON CONFLICT DO NOTHING;
