INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case we held that the removal of a suspect’s luggage from a baggage cart for an immediate on-the-spot sniff by a detector dog did not implicate the fourth amendment.', 'search_seizure', 'Pooley v. State', 'https://www.courtlistener.com/opinion/1116127/', '1116127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that when an officer’s observations lead him reasonably to believe that a traveler is carrying luggage that contains narcotics, the principles of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the particular course of investigation that the agents intended to pursue here — exposure of respondent’s luggage, which was located in a public place, to a trained canine — did not constitute a "search” within the meaning of the Fourth Amendment.', 'search_seizure', 'Pooley v. State', 'https://www.courtlistener.com/opinion/1116127/', '1116127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, if we find that some of the evidence presented to the magistrate in this case was the product of illegality, we must determine whether the remaining evidence would have been sufficient to support issuance of the warrant if the illegal evidence had not been presented.', 'general', 'Pooley v. State', 'https://www.courtlistener.com/opinion/1116127/', '1116127') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Francis, we held that a jury charge which allows for a non-unanimous verdict concerning what specific criminal act the defendant committed is error.', 'general', 'Ngo v. State', 'https://www.courtlistener.com/opinion/1369576/', '1369576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these particular circumstances, we conclude that, taken as a whole, the jury charge contained error.', 'general', 'Ngo v. State', 'https://www.courtlistener.com/opinion/1369576/', '1369576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[4] Because we agree with the court of appeals'' reasoning and result, we affirm its judgment.', 'general', 'Ngo v. State', 'https://www.courtlistener.com/opinion/1369576/', '1369576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[52] We affirm the judgment of the court of appeals.', 'general', 'Ngo v. State', 'https://www.courtlistener.com/opinion/1369576/', '1369576') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court correctly denied this motion and, therefore, we affirm.', 'general', 'State v. Atkinson', 'https://www.courtlistener.com/opinion/1199739/', '1199739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the nature of the evidence, and its place in the order of testimony, however, we conclude that the evidence was not admissible under the Idaho Rules of Evidence.', 'general', 'State v. Atkinson', 'https://www.courtlistener.com/opinion/1199739/', '1199739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was invited, and therefore the mistrial was properly denied.', 'mistrial', 'State v. Atkinson', 'https://www.courtlistener.com/opinion/1199739/', '1199739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated below, we affirm.', 'general', 'State v. Atkinson', 'https://www.courtlistener.com/opinion/1199739/', '1199739') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the court’s July 7, 2003 judgment.', 'general', 'State v. Keliiheleua', 'https://www.courtlistener.com/opinion/2597567/', '2597567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Noting that the defendants allegedly refrained from any physical action, we held that there were no physical acts of resistance.', 'general', 'People v. Synnott', 'https://www.courtlistener.com/opinion/2006677/', '2006677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this reasoning, we held that no offense had been committed because the officer had authority to request to enter the premises but not to demand entry, and the occupants were within their rights in refusing to admit the officer.', 'general', 'People v. Synnott', 'https://www.courtlistener.com/opinion/2006677/', '2006677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 124 (1990), this court held that criminal complaints alleging that the defendants “ ‘knowingly refused *** to remove [themselves] from the 400 block of Lincoln Highway, De Kalb, De Kalb County, Illinois, after being instructed to do so by [a De Kalb police officer]’ ” did not charge the offense of resisting a peace officer.', 'general', 'People v. Synnott', 'https://www.courtlistener.com/opinion/2006677/', '2006677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing, we conclude that the complaint sufficiently charged the offense of obstructing a peace officer and that the State produced sufficient evidence to sustain a conviction of that offense.', 'general', 'People v. Synnott', 'https://www.courtlistener.com/opinion/2006677/', '2006677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'People v. Synnott', 'https://www.courtlistener.com/opinion/2006677/', '2006677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the complaint was sufficient.', 'general', 'People v. Synnott', 'https://www.courtlistener.com/opinion/2006677/', '2006677') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for reconsideration of the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand to the sentencing
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking at the insignificant error in instructions "6" and "8" in relation to the uncontroverted facts supporting the jury''s verdict and counsel''s failure to alert the court to non-compliance with MAI, we hold that submission of these verdict directors did not prejudice appellant.', 'general', 'State v. Green', 'https://www.courtlistener.com/opinion/1523002/', '1523002') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not.', 'general', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the practice of “death qualifying” juries in capital cases violates neither the United States Constitution nor Article I, Section 19, of the North Carolina Constitution.', 'general', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court’s manner of inquiry was adequate, and as there was no evidence that any juror had read or otherwise been exposed to the article in question, the Court properly denied the defendant’s motion for a mistrial.', 'mistrial', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the immediate and thorough curative action taken by the trial court, we hold that there was no abuse of discretion in the trial court’s failure to declare a mistrial on this ground.', 'mistrial', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred by allowing Lockamy, Dawkins, and Bowes to testify concerning the defendant’s statements as to a prior break-in which he allegedly committed.', 'general', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in denying the defendant’s motion to dismiss the first-degree murder charge.', 'dismissal', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant’s taking and subsequent abandonment of the vehicle put it beyond his power to return and indicated a complete lack of concern as to whether the owner ever recovered the truck.', 'general', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in denying the defendant’s motions to dismiss the charges against him.', 'dismissal', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the evidence clearly shows that Braxton was singled out for the robbery, in part because of his advanced age, we hold that the trial court did not err in finding this factor in aggravation of the armed robbery.', 'general', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We hold that it does.', 'general', 'State v. Barts', 'https://www.courtlistener.com/opinion/1269310/', '1269310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant in a criminal ease has no substantial right to a jury nullification instruction, that is, an instruction informing the jury that it may acquit a defendant contrary to the law given by the court and the evidence, or to the deletion of instructions which inform the jury that it must follow the law.', 'general', 'State v. Hatori', 'https://www.courtlistener.com/opinion/2615623/', '2615623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Defendant had no substantial right to an instruction informing the jury of jury nullification or to the deletion of an instruction informing the jurors that they were to follow the law as given them by the court.', 'general', 'State v. Hatori', 'https://www.courtlistener.com/opinion/2615623/', '2615623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that plain error was not committed by the court.', 'general', 'State v. Hatori', 'https://www.courtlistener.com/opinion/2615623/', '2615623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that HRS § 710-1023(l)(b) is a lesser included offense of HRS § 710-1022(2)(b).', 'general', 'State v. Hatori', 'https://www.courtlistener.com/opinion/2615623/', '2615623') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in denying defendants the right to cross-examine *374 Arias concerning the polygraph test results, not because those results were reliable, but because the test results caused Arias to change her statement.', 'general', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that on this record, D''Amico failed to establish his claim for ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to reinstate the convictions and sentences.', 'sentencing', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Appellate Division judgment and reinstate the convictions and sentences of defendants Castagna and D''Amico.', 'sentencing', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Appellate Division upheld the defendants'' arguments in respect of both claims and we reverse that judgment.', 'general', 'State v. Castagna', 'https://www.courtlistener.com/opinion/1998350/', '1998350') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that conviction and punishment for both in a single trial is not prohibited by the provisions of either Constitution.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant may be tried for, convicted of, and punished separately for the crime of breaking or entering and the crime of felony larceny following that breaking or entering when the cases are jointly tried.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 666 (1972), superseded on other grounds by statute, we held that the crimes of felony breaking and entering and felony larceny merged with the crime of murder committed in the perpetration of those felonies.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even had the exchange on cross-examination constituted error, we conclude that, absent such error, the jury probably would have reached the same result.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature intended that the crime of breaking or entering and the crime of felony larceny pursuant to that breaking or entering be separately punished.', 'general', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that these felonies were not elements of kidnapping nor were they sentence-enhancing factors.', 'sentencing', 'State v. Gardner', 'https://www.courtlistener.com/opinion/1237889/', '1237889') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court in all respects.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1093249/', '1093249') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that evidence of the defendant''s prior acts of violence toward his wife was admissible under Evidence Rule 404(b)(1) to explain why she agreed to accompany the defendant to a hotel and did not forcibly resist his assault.', 'general', 'Bingaman v. State', 'https://www.courtlistener.com/opinion/2598471/', '2598471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2000), we held that this same analysis applied to Rule 404(b)(4).', 'general', 'Bingaman v. State', 'https://www.courtlistener.com/opinion/2598471/', '2598471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that this evidence should have been rejected because the probative value of the evidence implicitly rested on the inference that Velez had a propensity to sexually assault his dating partners:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the effect of Rule 404(b)(4) is to exempt evidence of a defendant''s other erimes of domestic violence from the normal bar on character evidence ("propensity" evidence) codified in Evidence Rule 404(b)(1).', 'general', 'Bingaman v. State', 'https://www.courtlistener.com/opinion/2598471/', '2598471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From all of this, we conclude that the trial judge violated Evidence Rule 402 and abused his discretion under Evidence Rule 408.', 'general', 'Bingaman v. State', 'https://www.courtlistener.com/opinion/2598471/', '2598471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rule 404(b)(4)-like its sibling provisions, Rules 404(b)(2) and (b)(8)-was intended to exempt certain evidence from Rule 404(b)(1)''s prohibition against propensity evidence.', 'general', 'Bingaman v. State', 'https://www.courtlistener.com/opinion/2598471/', '2598471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this principle limits the admission of the various sorts of character evidence governed by Evidence Rules 404(3) and 404(b).', 'general', 'Bingaman v. State', 'https://www.courtlistener.com/opinion/2598471/', '2598471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the danger posed by proving a defendant''s character through evidence of specific acts, we conclude that whenever the government offers evidence of a defendant''s other bad acts under Evidence Rules 404(b)(2), (b)(8), or (b)(4), trial judges must conduct a balancing under Evidence Rule 403 and must explain their decision on the record.', 'general', 'Bingaman v. State', 'https://www.courtlistener.com/opinion/2598471/', '2598471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998), we concluded that Rule 404(b)(8) has the same evidentiary effect as Rule 404(b)(2): that is, Rule 404(b)(8) exempts the specified evidence from Rule 404(b)(1)''s prohibition against propensity evidence.', 'general', 'Bingaman v. State', 'https://www.courtlistener.com/opinion/2598471/', '2598471') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, reverse in part, and remand to the trial court for further
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s ruling regarding plaintiff’s public policy claim, reverse its
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*371  *372 the trial judge weighed the evidence presented by both the prosecutor and defendant, we conclude that his findings and order are more consistent with the ordering of a new trial than with the direction of a verdict of acquittal.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon our own painstaking examination of the record in this case, conducted in conformance with the constitutionally binding standard announced in Jackson v Virginia, supra, we conclude that the trial court did not err in finding that the evidence *387 produced by the prosecutor was legally insufficient to support a finding of guilt beyond a reasonable doubt.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the facts as they have evolved, we find that the trial judge did not direct a verdict of acquittal.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we find that the trial judge, after applying a standard consistent with the one we announce today, directed a verdict of acquittal.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"IT IS ORDERED that the jury verdicts as to Defendant Hampton [handwritten by Judge Crockett] be set aside, defendant''s renewed motion for a directed verdict is *370 GRANTED, and a new trial is ordered.', 'general', 'People v. Hampton', 'https://www.courtlistener.com/opinion/2119242/', '2119242') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that subsection (b) of section 12 — 21.', 'general', 'People v. Jordan', 'https://www.courtlistener.com/opinion/2014465/', '2014465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Collins, we held that the discharge of a firearm into the air endangered those on the ground in the vicinity of the discharge:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We see no significant difference between the language of this statutory presumption and the one this court held unconstitutional in Watts.', 'general', 'People v. Jordan', 'https://www.courtlistener.com/opinion/2014465/', '2014465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that a rational trier of fact could have found that defendant knowingly endangered his infant daughter’s life or health by leaving her unattended in his vehicle, taking into account the setting where defendant’s vehicle was parked, the weather conditions, and the amount of time defendant left his daughter alone in the vehicle.', 'general', 'People v. Jordan', 'https://www.courtlistener.com/opinion/2014465/', '2014465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we find that there was evidence sufficient to support a finding of guilt, independent of the presumption, from this record, we are unable to ascertain the extent to which the witnesses’ credibility-figured into the circuit court’s ruling.', 'general', 'People v. Jordan', 'https://www.courtlistener.com/opinion/2014465/', '2014465') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '234(1), does not indicate, in terms that a person of common intelligence would understand, in what instances less than complete disclosure by an attorney becomes a criminal offense, we conclude that the statute does not provide adequate notice of the conduct by attorneys that it proscribes.', 'general', 'State v. Mark Marks, PA', 'https://www.courtlistener.com/opinion/1135656/', '1135656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the State may prosecute an attorney pursuant to section 817.', 'general', 'State v. Mark Marks, PA', 'https://www.courtlistener.com/opinion/1135656/', '1135656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we conclude that the reference to "claimant" in 817.', 'general', 'State v. Mark Marks, PA', 'https://www.courtlistener.com/opinion/1135656/', '1135656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that by using the term "incomplete," section 817.', 'general', 'State v. Mark Marks, PA', 'https://www.courtlistener.com/opinion/1135656/', '1135656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we find that the term "incomplete" renders section 817.', 'general', 'State v. Mark Marks, PA', 'https://www.courtlistener.com/opinion/1135656/', '1135656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the legislative history, like the plain language of section 817.', 'general', 'State v. Mark Marks, PA', 'https://www.courtlistener.com/opinion/1135656/', '1135656') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that trial judges are to consider and balance four factors in evaluating motions to withdraw a guilty plea: (1) whether the defendant has asserted a colorable claim of innocence;', 'plea', 'State v. Slater', 'https://www.courtlistener.com/opinion/1466364/', '1466364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On balancing those factors in the context of defendant’s pre-sentence motion to withdraw, we find that defendant has carried his burden and is entitled to withdraw his guilty plea.', 'sentencing', 'State v. Slater', 'https://www.courtlistener.com/opinion/1466364/', '1466364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the above factors, we find that Slater has met his burden and is entitled to withdraw his guilty plea in the interests of justice.', 'plea', 'State v. Slater', 'https://www.courtlistener.com/opinion/1466364/', '1466364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained below, we conclude that Valentino did not prof-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Valentino', 'https://www.courtlistener.com/opinion/4754317/', '4754317') ON CONFLICT DO NOTHING;
