INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not err
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The evidence provided by Bacon was probative of Pizzuto’s identity and we hold that the trial court did not abuse its discretion by admitting evidence of the similar uncharged conduct.', 'general', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Pizzuto’s right to a fair trial was not violated nor was he prejudiced as a result of late delivery of the jury panel.', 'general', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our decision in Garcia, we hold that the underlined portions of the quoted argument of the prosecutor were improper statements of personal belief or opinion.', 'general', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that their admission was not error.', 'general', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the record we hold that the trial court could consider the testimony of Berro as well as the contents of the 1986 presentence investigation report.', 'sentencing', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing cases we hold that I.', 'general', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lankford, and we hold that the limiting construction placed on I.', 'general', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In examining the manner and method in which Pizzuto murdered the Herndons we hold that the evidence supports a finding that the murders were especially heinous, atrocious or cruel, manifesting exceptional depravity.', 'general', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the facts in this case the trial court did not abuse its discretion by denying Pizzuto’s request for additional medical or legal assistance.', 'general', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is sufficient evidence to support the findings and that the sentences herein were not imposed under the influence of passion, prejudice or arbitrary factors.', 'sentencing', 'State v. Pizzuto', 'https://www.courtlistener.com/opinion/1232321/', '1232321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the requirement imposed on individuals to register is independent of the requirement imposed on the States to implement the enhanced registration and notification standards of SORNA.', 'general', 'United States v. Gould', 'https://www.courtlistener.com/opinion/1029151/', '1029151') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the circumstances, we conclude that the Attorney General had good cause to invoke the exception to providing the 30-day notice.', 'general', 'United States v. Gould', 'https://www.courtlistener.com/opinion/1029151/', '1029151') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the "engage in conduct" language of the injury to a child statute was, in fact, "vestigial" language and that the statute''s actual focus was on the result of a defendant''s conduct.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the charge, read as a whole limited the defendant''s culpable mental state to the "result of conduct.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we conclude that the correct analysis is that the inclusion of the "engage in conduct" language in the definitional portion of a jury charge is in fact error where the offense charged is a result offense.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it was not error to submit the penal code definition of intentional due to the wording of the indictment and the wording of the application portion of the charge, which tracked the language of the indictment.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed and remanded for a harm analysis under Almanza v.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2382891/', '2382891') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the trial judge on this issue.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse his conviction of possession with intent to distribute marijuana and remand for a new trial based on the trial judge''s burden-shifting jury instructions.', 'jury_instruction', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the trial judge''s ruling in this matter and hold that the taped conversations between Appellant and Johnson were properly admitted into evidence.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Appellant''s conviction of distribution of marijuana.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial judge''s instruction that possession of more than 28 grams or one ounce of marijuana was prima facie evidence of guilt of the charge of possession with intent to distribute marijuana constitutes an impermissible presumption which shifted the burden of proof from the State to Appellant.', 'general', 'State v. Andrews', 'https://www.courtlistener.com/opinion/1374355/', '1374355') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in Spotz III, we held that the Cumberland County murder was not part of the same criminal episode as the Clearfield, Schuylkill, and York County crimes.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we held that the remark did not put the future dangerousness of the appellant at issue.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*1238 On December 23, 1998, this Court held in Commonwealth v.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Rolan, "the crime of burglary has always been and continues to be viewed as a crime involving the use or threat of violence to the person.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 763, 779 (1998), this Court held that "the introduction of evidence concerning [the appellant]''s escape from prison and parole violations during the guilt phase of the trial .', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 439, 454 (1995) ("If we conclude that the particular course chosen by counsel had some reasonable basis, our inquiry ceases and counsel''s assistance is deemed effective.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'thus, we conclude that trial counsel was not ineffective for failing to object.', 'ineffective_assistance', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 454 ("If we conclude that the particular course chosen by counsel had some reasonable basis, our inquiry ceases and counsel''s assistance is deemed effective.', 'general', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the sentence of death imposed upon [Spotz] is not excessive or disproportionate to the penalty imposed in similar cases.', 'sentencing', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon review of the record, we conclude that the sentence of death was not the product of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Commonwealth v. Spotz', 'https://www.courtlistener.com/opinion/2074443/', '2074443') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the name of a church necessarily imports an entity capable of owning property, we hold that the indictment was sufficient on its face.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/6838924/', '6838924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that alleging ownership of property in an entity identified as a church or other place of religious worship, like identifying an entity as a “company” or “incorporated,” signifies an entity capable of owning property, and the line of cases from the Court of Appeals that has held otherwise is overruled.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/6838924/', '6838924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the larceny indictment alleging ownership of stolen property of Manna Baptist Church sufficiently alleged ownership in a legal entity capable of owning property.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/6838924/', '6838924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Thornton we held that an indictment alleging the defendant embezzled money belonging to “The Chuck Wagon” was “fatally defective” because it failed to allege “that ‘The Chuck Wagon’ is a corporation, and the words ‘The Chuck Wagon’ do not import a corporation.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/6838924/', '6838924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we conclude that the State presented sufficient evidence of defendant’s criminal intent to commit larceny.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/6838924/', '6838924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the decision of the Court of Appeals and remand this case to that court for consideration of any remaining issues.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/6838924/', '6838924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and remand this case to that court for consideration of any remaining issues on appeal.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/6838924/', '6838924') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that petitioner’s counsel was ineffective because he failed to advise petitioner that if he went to trial, he could have requested a charge on the lesser offense and might have been convicted of the misdemeanor of use of a vehicle without permission rather than the felony of grand larceny.', 'ineffective_assistance', 'Kerrigan v. State', 'https://www.courtlistener.com/opinion/1354724/', '1354724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that petitioner was prejudiced by counsel’s deficient performance because but for counsel’s failure to advise petitioner of the lesser offense, he would not have pled guilty.', 'general', 'Kerrigan v. State', 'https://www.courtlistener.com/opinion/1354724/', '1354724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Kerrigan v. State', 'https://www.courtlistener.com/opinion/1354724/', '1354724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '’s mental incapacity or Jackson’s knowledge of that incapacity and we conclude that the superior court did not err in denying Jackson’s motions for acquittal.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2617535/', '2617535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having independently reviewed the entire sentencing record, we conclude that the sentence imposed below was not clearly mistaken.', 'sentencing', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2617535/', '2617535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in the light most favorable to the state, we find that there was ample evidence to support a reasonable conclusion that the state met its burden of proving beyond'' a reasonable doubt that T.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2617535/', '2617535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2617535/', '2617535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, considering all the circumstances, the finder of fact could infer his intent was to commit a larceny rather than a rape or other crime.', 'general', 'Wright v. Commonwealth', 'https://www.courtlistener.com/opinion/1356359/', '1356359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that an investigative stop can be justified based on an objectively reasonable suspicion of any offense, provided that the offense for which reasonable suspicion exists is related to the offense articulated by the officer involved.', 'general', 'State v. Bolosan', 'https://www.courtlistener.com/opinion/2617621/', '2617621') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we held that “in order to satisfy the good faith defense of lack of knowledge, the borrower of a vehicle must at least inquire of the owner whether or not the vehicle is insured.', 'general', 'State v. Bolosan', 'https://www.courtlistener.com/opinion/2617621/', '2617621') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse Bo-losan’s driving without no-fault insurance conviction, vacate the driving without a license conviction, and remand for further proceedings on the constitutionality of the mitial stop.', 'general', 'State v. Bolosan', 'https://www.courtlistener.com/opinion/2617621/', '2617621') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the limitation placed upon the state''s right to appeal in a criminal case, found in AS 22.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] We hold that the superior court''s decision that in a case of direct contempt the contemnor is entitled to a jury trial, in regard to his purportedly contumacious conduct, is of such importance and substance as to justify our review of the matter.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that direct criminal contempts must be treated like any other criminal prosecution for purposes of the right to jury trial under article I, section 11 of the Alaska Constitution.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant was entitled to a jury trial.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that "willful disregard or disobedience of the authority or orders of the court" was a necessary element of indirect contempt.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 375 (Alaska 1960), where this court held that the superior court''s denial of a jury trial affected a substantial right of the petitioner under Supreme Ct.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[9] In view of these factors, we conclude that the case comes within the purview of Supreme Court Rule 23(c) (3).', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Rather, we find that a right to jury trial in a direct criminal contempt situation is "necessary for the kind of civilized life and ordered liberty which is at the core of our constitutional heritage.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It then appealed the dismissal of its petition, and we affirmed the superior court''s dismissal of the petition for review.', 'dismissal', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the state can invoke our discretionary review jurisdiction in criminal cases where the matter sought to be reviewed involves a non-final order or decision of the superior court.', 'general', 'State v. Browder', 'https://www.courtlistener.com/opinion/1383099/', '1383099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Stang', 'https://www.courtlistener.com/opinion/2682617/', '2682617') ON CONFLICT DO NOTHING;
