INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because the State’s failure to respond to the defendant’s discovery request caused the delay, the defendant was not accountable for the delay of the trial date.', 'general', 'Kirby v. State', 'https://www.courtlistener.com/opinion/2057032/', '2057032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “[t]o put the defendants in a position whereby they must either go to trial unprepared due to the State’s failure to respond to discovery requests or be prepared to waive their rights to a speedy trial, is to put the defendants in an untenable situation.', 'general', 'Kirby v. State', 'https://www.courtlistener.com/opinion/2057032/', '2057032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Kirby v. State', 'https://www.courtlistener.com/opinion/2057032/', '2057032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Kirby’s convictions and her two hundred and fifteen year sentence.', 'sentencing', 'Kirby v. State', 'https://www.courtlistener.com/opinion/2057032/', '2057032') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'In Re One 1983 Toyota', 'https://www.courtlistener.com/opinion/1388726/', '1388726') ON CONFLICT DO NOTHING;
