INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McNeal, we held that the admission of closeup color photographs of the victim''s decomposed, maggot-infested skull was an abuse of discretion.', 'general', 'Underwood v. State', 'https://www.courtlistener.com/opinion/1148850/', '1148850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Conner, this Court held that the trial court did not manifestly err in failing to hold a competency hearing for a schizophrenic defendant who was being treated with medication, even though the defendant had exhibited suicidal behavior and appeared confused during part of the court proceedings.', 'general', 'Underwood v. State', 'https://www.courtlistener.com/opinion/1148850/', '1148850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Neal''s confession was made voluntarily and that he knowingly waived his right against self-incrimination due to the fact that the interrogating officer stopped questioning Neal whenever he asked, and because Neal was re-Mirandized each day before questioning began.', 'general', 'Underwood v. State', 'https://www.courtlistener.com/opinion/1148850/', '1148850') ON CONFLICT DO NOTHING;
