INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse appellant’s conviction under 18 Pa.', 'general', 'Commonwealth v. McCoy', 'https://www.courtlistener.com/opinion/1940260/', '1940260') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that the trial judge did not abuse his discretion in overruling the motion for change of venue.', 'general', 'Cabello v. State', 'https://www.courtlistener.com/opinion/1875341/', '1875341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the voluntariness issue, this Court holds that the finding of the trial judge was neither manifestly in error nor contrary to the overwhelming weight of the evidence.', 'general', 'Cabello v. State', 'https://www.courtlistener.com/opinion/1875341/', '1875341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, this Court holds there was no error in overruling the defendant''s motion for a mistrial.', 'mistrial', 'Cabello v. State', 'https://www.courtlistener.com/opinion/1875341/', '1875341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, this Court holds there was no error in the trial court''s refusing to give a manslaughter instruction.', 'general', 'Cabello v. State', 'https://www.courtlistener.com/opinion/1875341/', '1875341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and remand for vacation of two convictions.', 'general', 'Morrison v. State', 'https://www.courtlistener.com/opinion/2097247/', '2097247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm Morrison''s convictions for Count I, attempted criminal deviate conduct, and Count III, sexual battery, as well as his executed fifteen-year sentence.', 'sentencing', 'Morrison v. State', 'https://www.courtlistener.com/opinion/2097247/', '2097247') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the admission of Staggs'' out-of-court statement did not violate Hawai`i''s confrontation *976 clause inasmuch as Fields was afforded a sufficient opportunity to cross-examine Staggs about her prior statement at trial.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[22]  This court granted certiorari in Sua I and in Sua II, reversed the ICA in part, indicating that "[i]n contrast to the ICA''s opinion, we hold that, under certain circumstances, receipt of grand jury testimony pursuant to a firmly rooted exception to the general rule against hearsay may adequately preserve a defendant''s right of cross-examination.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, because "[t]he error in this case was not harmless[,] it must be reversed and remanded for a new trial.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Eastman, this court held that the complainant''s prior inconsistent statement contained in a "Victim''s Voluntary Statement Form" (VVSF) which she gave to a police officer "met all the requirements under HRE Rule 802.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*983 Hence, we conclude that, considered in the light most favorable to the prosecution, the evidence is of sufficient quality and probative value to enable a person of reasonable caution to support the conclusion that Fields intentionally, knowingly, or recklessly maltreated Staggs.', 'general', 'State v. Fields', 'https://www.courtlistener.com/opinion/2582377/', '2582377') ON CONFLICT DO NOTHING;
