INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the officer’s testimony was properly admitted.', 'general', 'State v. Rosencrantz', 'https://www.courtlistener.com/opinion/1155790/', '1155790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Absent such a foundation, we hold that the district judge did not err in refusing to admit testimony about the sodium amytal interview in this case.', 'general', 'State v. Rosencrantz', 'https://www.courtlistener.com/opinion/1155790/', '1155790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that they were not excessive.', 'general', 'State v. Rosencrantz', 'https://www.courtlistener.com/opinion/1155790/', '1155790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the “best evidence” rule did not bar admission of the officer’s testimony.', 'general', 'State v. Rosencrantz', 'https://www.courtlistener.com/opinion/1155790/', '1155790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Neither do we find that the report was hearsay.', 'general', 'State v. Rosencrantz', 'https://www.courtlistener.com/opinion/1155790/', '1155790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons set forth below, we affirm.', 'general', 'State v. Rosencrantz', 'https://www.courtlistener.com/opinion/1155790/', '1155790') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that substantial evidence supported the magistrate’s finding of probable cause to believe Pole committed aggravated assault.', 'probable_cause', 'State v. Pole', 'https://www.courtlistener.com/opinion/2520949/', '2520949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence presented by the state at the preliminary hearing was sufficient to support the magistrate’s finding of probable cause to believe Pole committed aggravated assault but not aggravated battery.', 'probable_cause', 'State v. Pole', 'https://www.courtlistener.com/opinion/2520949/', '2520949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'State v. Pole', 'https://www.courtlistener.com/opinion/2520949/', '2520949') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For several reasons, we hold that an ineffective assistance of appellate counsel claim is not meritorious in this circumstance.', 'ineffective_assistance', 'Mintun v. State', 'https://www.courtlistener.com/opinion/2582323/', '2582323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the trial evidence satisfied the definition of solicitation.', 'general', 'Mintun v. State', 'https://www.courtlistener.com/opinion/2582323/', '2582323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, taken as a whole, Harvey’s sexual behavior and his sexually oriented questions and statements, together with his act of reaching for the child’s chest and asking her to lift her shirt, were sufficient to show that he was soliciting her to participate in a sexual act.', 'general', 'Mintun v. State', 'https://www.courtlistener.com/opinion/2582323/', '2582323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part and reverse in part.', 'general', 'Mintun v. State', 'https://www.courtlistener.com/opinion/2582323/', '2582323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court properly set forth all mitigating factors that it considered.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not err by failing to consider the alternative sentences available for a conviction for first degree murder.', 'sentencing', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the first prong of the Rueth analysis has not been met by Pratt.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have compared the nature of the crime and the nature of the defendant in this case with other similar cases[12], and we hold that the death penalty in this case is disproportionate.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "Grammer''s death was part of a stream of events which began the evening Fetterly and Windsor entered Grammer''s home and ended the following day when Grammer''s possessions were removed from the home.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, as this Court held in Rhoades, 121 Idaho at 82, 822 P.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 585 (1986), wherein we reversed the district court''s imposition of the death penalty as being disproportionate, are most similar to the present case.', 'general', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the district court''s judgment of conviction and the sentences imposed, except (1) the conviction and sentence for Count XVI, attempted felony murder, which we vacate, and (2) the death sentence, which we vacate.', 'sentencing', 'State v. Pratt', 'https://www.courtlistener.com/opinion/1209976/', '1209976') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following a thorough review of the record and controlling case law, we hold that some of the arguments raised by defendant constitute error and, cumulatively, deprived defendant of his due process right to a fair trial.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the trial court abused its discretion by permitting the jury to hear these arguments.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this appeal, we hold that a new trial is necessary in order to preserve the trustworthiness and reputation of the judicial process.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court holds that cumulative errors occurring at trial deprived defendant of his due process right to a fair trial.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court abused its discretion by permitting the State to argue that its verdict should be a vehicle to vindicate the Doffyn family.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, regardless of the weight of the evidence, as guardians of constitutional rights and the integrity of the criminal justice system, we must order a new trial when, as here, we conclude that defendant did not receive a fair trial.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a combination of errors occurring at trial may have coerced the jury into returning a verdict more likely grounded in sympathy than on a dispassionate evaluation of the facts.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case at bar, we find that the generic instructions tendered by the State were not likely to undo the damage to defendant’s case inflicted by the State’s pointed remarks.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Cumulatively, we find that the errors created a pervasive pattern of unfair prejudice to defendant’s case.', 'general', 'People v. Blue', 'https://www.courtlistener.com/opinion/2108726/', '2108726') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the new complaint sufficiently alleged all of the material elements of the offense of criminal conspiracy and, therefore, was not “fatally defective.', 'general', 'State v. Merino', 'https://www.courtlistener.com/opinion/1310715/', '1310715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, by its plain language, HRPP 11(f) applies only to guilty pleas and that, with respect to pleas of nolo contendere (¿a, no contest), the trial court is not required to make “such inquiry as shall satisfy it that there is a factual basis for the plea.', 'plea', 'State v. Merino', 'https://www.courtlistener.com/opinion/1310715/', '1310715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'at 13-16), we hold that it was immaterial whether the offer, which Judge Tsukiya-ma required in order to exercise his “wide discretion,”
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, looking to the totality of the facts and circumstances of the particular case, we hold that Merino’s waiver of his right to the assistance of counsel was know
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the circuit court did not commit an abuse of discretion when it accepted Merino’s no contest plea to the new complaint.', 'plea', 'State v. Merino', 'https://www.courtlistener.com/opinion/1310715/', '1310715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in the absence of a fair and just reason for withdrawal of Merino’s no contest plea, we hold that the circuit court did not commit an abuse of discretion in denying Merino’s HRPP 32(d) motion.', 'plea', 'State v. Merino', 'https://www.courtlistener.com/opinion/1310715/', '1310715') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 46 We hold that the trial court did not err in allowing the State to establish defendant''s guilt of money laundering with evidence of UPT''s receipts rather than its profits.', 'general', 'People v. Gutman', 'https://www.courtlistener.com/opinion/2523830/', '2523830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, because we hold that "gross receipts" is the correct definition of "proceeds" in the Illinois money laundering statute, we need not resolve this issue.', 'general', 'People v. Gutman', 'https://www.courtlistener.com/opinion/2523830/', '2523830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse that portion of the appellate court''s judgment that vacated defendant''s money laundering conviction.', 'general', 'People v. Gutman', 'https://www.courtlistener.com/opinion/2523830/', '2523830') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In all other respects, we affirm the appellate court''s judgment.', 'general', 'People v. Gutman', 'https://www.courtlistener.com/opinion/2523830/', '2523830') ON CONFLICT DO NOTHING;
