INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the burglary conviction and affirm the murder conviction.', 'general', 'State v. Lynch', 'https://www.courtlistener.com/opinion/1232742/', '1232742') ON CONFLICT DO NOTHING;
