INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We approve this caution and, applying it to the procedural and evidentiary facts of this particular case as disclosed by the record, we hold that the defendant has not been unduly prejudiced, and that any error was harmless.', 'general', 'State v. Nash', 'https://www.courtlistener.com/opinion/2403143/', '2403143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Nash', 'https://www.courtlistener.com/opinion/2403143/', '2403143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the record before us indicates that defendant was actually ensured a fair and impartial jury, we conclude that his constitutional rights were upheld and reversal is not warranted.', 'general', 'People v. Cain', 'https://www.courtlistener.com/opinion/2820053/', '2820053') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that defendant was properly tried in Jefferson County for the robbery of the victim’s car.', 'general', 'People v. Gilliam', 'https://www.courtlistener.com/opinion/2015103/', '2015103') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, we conclude that the trial court properly limited the testimony of Dr.', 'general', 'People v. Gilliam', 'https://www.courtlistener.com/opinion/2015103/', '2015103') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Detective Kaminski’s testimony was admissible.', 'general', 'People v. Gilliam', 'https://www.courtlistener.com/opinion/2015103/', '2015103') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that neither prong of the plain error rule is satisfied.', 'general', 'People v. Gilliam', 'https://www.courtlistener.com/opinion/2015103/', '2015103') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm defendant’s convictions and sentences.', 'sentencing', 'People v. Gilliam', 'https://www.courtlistener.com/opinion/2015103/', '2015103') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the assignation statute is constitutional.', 'general', 'McKenney v. State', 'https://www.courtlistener.com/opinion/1124712/', '1124712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defendant in this case lacks standing to complain of lack of notice since the facts adduced at trial reveal conduct which manifestly falls within the ambit of the assignation statute.', 'general', 'McKenney v. State', 'https://www.courtlistener.com/opinion/1124712/', '1124712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Absent such a showing, we find that the language describing the crime of assignation is precise enough to guide law enforcement officials in determining what conduct constitutes prohibited conduct.', 'general', 'McKenney v. State', 'https://www.courtlistener.com/opinion/1124712/', '1124712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that is the result in this case.', 'general', 'Dickeson v. State', 'https://www.courtlistener.com/opinion/2604258/', '2604258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, once the deficiency is demonstrated in that situation, the resulting prejudice will be presumed.', 'general', 'Dickeson v. State', 'https://www.courtlistener.com/opinion/2604258/', '2604258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), we held that, when multiple criminal defendants are represented by the same attorney, such dual representation constitutes ineffective assistance of counsel, and prejudice will be presumed in such an instance, in the absence of an appropriate waiver made in a prescribed manner.', 'ineffective_assistance', 'Dickeson v. State', 'https://www.courtlistener.com/opinion/2604258/', '2604258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record in this case demonstrates that Dickeson did not receive effective assistance from her attorney in the trial court as required by both the Wyoming and federal constitutions.', 'general', 'Dickeson v. State', 'https://www.courtlistener.com/opinion/2604258/', '2604258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we concluded that defense attorneys had failed to interview prospective eye witnesses, and no justification could be found in the record to explain why no interview was pursued.', 'general', 'Dickeson v. State', 'https://www.courtlistener.com/opinion/2604258/', '2604258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse her conviction and remand the case for a new trial.', 'general', 'Dickeson v. State', 'https://www.courtlistener.com/opinion/2604258/', '2604258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that Act 595 is not applicable to Ross’s probation judgment and disposition order entered in 1994, and, as a consequence, the trial court’s dismissal of the State’s FIP count against Ross was correct.', 'dismissal', 'State v. Ross', 'https://www.courtlistener.com/opinion/1947313/', '1947313') ON CONFLICT DO NOTHING;
