INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it did not.', 'general', 'State v. Mattiello', 'https://www.courtlistener.com/opinion/1133679/', '1133679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 452, we hold that, notwithstanding the use of the terms “mixture” and “weight” in HRS § 712-1241(1)(b)(ii)(B), dangerous drugs distributed in liquid form must be measured in fluid ounces.', 'general', 'State v. Mattiello', 'https://www.courtlistener.com/opinion/1133679/', '1133679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the prosecution adduced insufficient evidence that the amount of the methadone mixture sold by Mattiello was “three-eighths ounce or more.', 'general', 'State v. Mattiello', 'https://www.courtlistener.com/opinion/1133679/', '1133679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There being no indication whatsoever that (a) is true, we conclude that (b) is true.', 'general', 'State v. Mattiello', 'https://www.courtlistener.com/opinion/1133679/', '1133679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we reverse the ICA’s majority opinion, vacate the circuit court’s judgment, guilty conviction, and sentence, and remand to the circuit court for the entry of a judgment of conviction of and sentence for promoting a dangerous drug in the second degree, in violation of HRS § 712-1242(1)(c).', 'sentencing', 'State v. Mattiello', 'https://www.courtlistener.com/opinion/1133679/', '1133679') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is no violation and deny the petition.', 'general', 'Bowles v. Singletary', 'https://www.courtlistener.com/opinion/1135647/', '1135647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, by accepting the terms and conditions of early release under the Control Release program, Bowles and other inmates in his position waived any ex post facto argument they otherwise may have had as to the forfeiture of incentive and basic gain time after a violation of Control Release.', 'general', 'Bowles v. Singletary', 'https://www.courtlistener.com/opinion/1135647/', '1135647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[1]  Although we find that Bowles waived his ex post facto argument, we note that at the time of Bowles'' offenses in November 1989, all the post-prison supervision programs in effect provided for forfeiture of incentive and basic gain time upon revocation.', 'general', 'Bowles v. Singletary', 'https://www.courtlistener.com/opinion/1135647/', '1135647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that the decision in Lynce v.', 'general', 'Bowles v. Singletary', 'https://www.courtlistener.com/opinion/1135647/', '1135647') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that there was ample evidence to show that the defendants'' "purpose in setting out to stop [Rigg] was not peaceably to persuade him to stop work and join the union, but was to compel him by force and intimidation to accede to their demand," this Court held that all the defendants could be found guilty of assault because Orlandi''s act was within the parameters of their "common design to perform an illegal act.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing the basic principle that a person should not be convicted of a crime for which he does not possess the requisite intent, this Court held in Doucette that a jury may not convict a person of felony murder unless it finds, beyond a reasonable doubt, that the person had an intent to kill, an intent to do great bodily harm, or a wanton disregard of the likelihood that death or great bodily harm would result.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant''s hesitation to provide information that would inculpate Gundlah was not sufficiently direct or emphatic to constitute an invocation of his right to remain silent, and thus the officers were not obligated to cease the interrogation.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has failed to show that the alleged conflict of interest compromised trial counsel''s loyalty to defendant, adversely affected his performance, or imperiled defendant''s right to a fair trial.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant was required, but failed, to show that the alleged conflict jeopardized his right to a fair trial.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We ignore reality if we conclude that the existence of ethical obligations will by themselves ensure effective representation in the face of compelling and unavoidable economic pressures to the contrary.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we reverse the murder conviction based on the court''s instruction on intent, we address defendant''s ineffective-assistance-of-counsel claim because that claim necessarily challenges all of his convictions.', 'ineffective_assistance', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1972478/', '1972478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1998), this Court held that the trial court properly admitted an envelope with words significant to manufacture of methamphetamine as evidence of knowledge.', 'general', 'Ginn v. State', 'https://www.courtlistener.com/opinion/1096680/', '1096680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Pate, we reversed a conviction of possession of marijuana where the defendant had checked out of the hotel room the day before the marijuana was found.', 'general', 'Ginn v. State', 'https://www.courtlistener.com/opinion/1096680/', '1096680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm.', 'general', 'Ginn v. State', 'https://www.courtlistener.com/opinion/1096680/', '1096680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Powell, we affirmed a conviction where the controlled substance was found in the closet of the bedroom in the house on which the defendant paid the rent.', 'general', 'Ginn v. State', 'https://www.courtlistener.com/opinion/1096680/', '1096680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a thorough review of the record before us and consideration of the applicable law, we find no reversible error, and therefore we affirm the judgment of conviction and imposition of sentence on this two-count indictment in the Circuit Court of DeSoto County.', 'sentencing', 'Ginn v. State', 'https://www.courtlistener.com/opinion/1096680/', '1096680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶33 Consequently, we conclude that a criminal violation of A.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2638142/', '2638142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that there was a lack of substantial evidence to support count two, and the trial court should have dismissed it along with count one.', 'dismissal', 'State v. Ross', 'https://www.courtlistener.com/opinion/2638142/', '2638142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 38 For the reasons stated above, we reverse the conviction.', 'general', 'State v. Ross', 'https://www.courtlistener.com/opinion/2638142/', '2638142') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶16           We conclude that due process does not require that an open-ended offense be
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, it is because of the truly extraordinary procedural history of this case, set forth in detail above, that we hold that the trial court did not abuse its discretion in declining on the day of trial to engage in a colloquy with Veney (and then, presumably, granting his request for independent DNA testing that Veney’s counsel said he would make).', 'general', 'Veney v. United States', 'https://www.courtlistener.com/opinion/1946150/', '1946150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 930-31, we hold that “the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the DNA evidence was admissible under
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the totality of the pre-trial proceedings in this case and the information actually imparted to Veney in open court, we conclude that the trial court did not abuse its discretion in denying appellant’s request to enter into a colloquy, and therefore decline to reverse Veney’s convictions on the basis of the claim that he was not given the information regarding DNA testing in the manner required by the IPA.', 'general', 'Veney v. United States', 'https://www.courtlistener.com/opinion/1946150/', '1946150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Unpersuaded by appellant’s arguments, we affirm the judgment of conviction and the denial of his post-trial motion.', 'general', 'Veney v. United States', 'https://www.courtlistener.com/opinion/1946150/', '1946150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we affirm appellant’s conviction and the denial of his post-trial motion, and remand to the trial court so that it can vacate, as merged, appellant’s conviction of second-degree sex abuse.', 'general', 'Veney v. United States', 'https://www.courtlistener.com/opinion/1946150/', '1946150') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the face of the Petition sufficiently demonstrates that there was a factual basis for the imposition of the permanent injunction.', 'general', 'Jackson v. Echols', 'https://www.courtlistener.com/opinion/1100612/', '1100612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We find that an "ex live-in girlfriend" satisfies the "as in a family" requirement.', 'general', 'Jackson v. Echols', 'https://www.courtlistener.com/opinion/1100612/', '1100612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the order under review.', 'general', 'Jackson v. Echols', 'https://www.courtlistener.com/opinion/1100612/', '1100612') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these facts, we hold that the Liability Defendants'' waived any errors in the circuit court''s jury instructions regarding the theories of liability in Counts I, II and III by having failed to comply with HRAP Rule 28(b)(4)(B).', 'jury_instruction', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that the FIFRA did not preempt the Plaintiffs'' claims in Counts I and II alleging negligence and strict liability for the Liability Defendants'' defective manufacture or design of Benlate.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing justifications, we hold that EPA mandated warranties are preempted.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the FIFRA did not preempt the Plaintiffs'' claim for breach of express warranty, and we affirm the circuit court''s order denying the Liability Defendants'' motion for partial summary judgment with respect to the Plaintiffs'' claim in Count III for breach of express warranty.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that the circuit court did not, as a result of these two summary judgment orders, allow the jury to impose liability pursuant to claims that the FIFRA preempted.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the overwhelming and substantial evidence supporting the jury''s verdict, we hold that the cumulative effect of the three alleged errors did not deny the Liability Defendants their constitutional right to a fair trial.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the circumstances of this case, it affirmatively appears from the record as a whole that DuPont and the other Liability Defendants did not suffer prejudice as a result of the circuit court''s inappropriate remedial jury instruction.', 'jury_instruction', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although the circuit court abused its discretion through this particular sanction, we hold that the circuit court''s error was harmless.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the superior court''s ruling did not constitute prejudicial error.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in light of the brevity of the improper reference to the Greenlight verdict by the Plaintiffs'' counsel during his opening argument, the seven-month duration of the trial, the circuit court''s instructions to the jury, and the overwhelming evidence in the record supporting the jury''s verdict, we hold that, although it was improper for the Plaintiffs'' counsel to refer to the verdict in Greenlight during opening statements, this reference did not constitute an occurrence of such charac...', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that felony murder and intentional murder are
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained below, we hold that article V, section 3(b)(1) of the Florida Constitution does not authorize this Court''s jurisdiction over unelaborated per curiam decisions issued by a district court of appeal.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1106470/', '1106470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that article V, section 3(b)(1) of the Florida Constitution does not authorize this Court''s jurisdiction over unelaborated per curiam decisions issued by a district court of appeal.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1106470/', '1106470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1980), this Court held that "the Supreme Court of Florida lacks jurisdiction to review per curiam decisions of the several district courts of appeal .', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1106470/', '1106470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Today, we find that the analysis which led us to this determination applies just as readily to the context of mandatory review jurisdiction under article V, section 3(b)(1) of the Florida Constitution.', 'general', 'Jackson v. State', 'https://www.courtlistener.com/opinion/1106470/', '1106470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We continue to follow the analysis we delineated in Rodriguez, and we hold that the district court did not err by allowing the jury to hear the victim''s preliminary hearing testimony.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1120918/', '1120918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Appellant failed to show that the district court abused its discretion when it denied his motion for a continuance.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1120918/', '1120918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Giving all legitimate inferences to the State, we hold that the record is not void of substantial evidence from which reasonable persons could say Appellant is guilty beyond a reasonable doubt.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1120918/', '1120918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the district court did not err under W.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1120918/', '1120918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the district court''s allowance of the admission of the victim''s preliminary hearing testimony did not violate the defendant''s right to confront witnesses against him because the four parts of the reliability test were satisfied.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1120918/', '1120918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the jury could infer that there "were no *996 `circumstances manifesting a voluntary and complete renunciation of his criminal intention.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1120918/', '1120918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Rodriguez, this Court held that the admissibility of preliminary hearing testimony at trial would depend upon a case-by-case analysis.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1120918/', '1120918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Cardenas v. State', 'https://www.courtlistener.com/opinion/1120918/', '1120918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court erred on March 23, 1999 when, without statutory authority to do so, it deferred its judgment and took the matter under advisement on terms and conditions.', 'general', 'Powell v. Commonwealth', 'https://www.courtlistener.com/opinion/1396233/', '1396233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the trial court and remand this case for a new trial.', 'general', 'Powell v. Commonwealth', 'https://www.courtlistener.com/opinion/1396233/', '1396233') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with our decision in Perkins, we hold that, in determining whether a crime constitutes a forcible felony, courts must consider only the statutory elements of the offense, regardless of the particular circumstances involved.', 'general', 'State v. Hearns', 'https://www.courtlistener.com/opinion/1107651/', '1107651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 1310, however, we held that in determining whether an offense constitutes a forcible felony, a court may only consider the statutory elements.', 'general', 'State v. Hearns', 'https://www.courtlistener.com/opinion/1107651/', '1107651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that the record and Louisiana law supports the trial court''s order of reimbursements of amounts that Mr.', 'general', 'In Re Succession of Horrell', 'https://www.courtlistener.com/opinion/1108682/', '1108682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even assuming Walter''s character is pristine in all respects other than his involvement in the execution of his father''s will and the act of donation, we find that the circumstances here, in addition to the animosity among the family members which was noted by the trial court, were sufficient to support a finding that Walter could not serve as administrator.', 'general', 'In Re Succession of Horrell', 'https://www.courtlistener.com/opinion/1108682/', '1108682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that the trial court erred in making the fines payable to the Horrells'' attorneys as opposed to the court.', 'general', 'In Re Succession of Horrell', 'https://www.courtlistener.com/opinion/1108682/', '1108682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the actions for sanctions had not prescribed, as Mr.', 'general', 'In Re Succession of Horrell', 'https://www.courtlistener.com/opinion/1108682/', '1108682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the portion of the judgment placing the Horrells in partial possession and remand the matter to the trial court for further orders on the required accountings of the Provisional Administratrix before delivery of the decedent''s legacy.', 'general', 'In Re Succession of Horrell', 'https://www.courtlistener.com/opinion/1108682/', '1108682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the portion of the judgment placing the Horrells in partial possession and remand the matter to the trial court for further orders on the required accountings of the Provisional Administratrix before delivery of the decedent''s legacy.', 'general', 'In Re Succession of Horrell', 'https://www.courtlistener.com/opinion/1108682/', '1108682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the contempt judgment of the trial court, the trial court''s denial of Mr.', 'general', 'In Re Succession of Horrell', 'https://www.courtlistener.com/opinion/1108682/', '1108682') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'McGowan v. State', 'https://www.courtlistener.com/opinion/1109438/', '1109438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held the prejudicial effect of in-traducing the prior conviction outweighed the probative value of the conviction.', 'general', 'State v. Baker', 'https://www.courtlistener.com/opinion/1629157/', '1629157') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the basis for downward departure was not supported by competent, substantial evidence.', 'general', 'State v. Subido', 'https://www.courtlistener.com/opinion/1110728/', '1110728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no legal basis for the reasons given for departure, we reverse and remand for resentencing.', 'sentencing', 'State v. Subido', 'https://www.courtlistener.com/opinion/1110728/', '1110728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because a preponderance of the evidence does not support the reason given by the trial court for departing downward from the sentence range, we reverse and remand for sentencing within the guidelines.', 'sentencing', 'State v. Subido', 'https://www.courtlistener.com/opinion/1110728/', '1110728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we AFFIRM Subido''s conviction and designation as a sexual predator, REVERSE his downward departure sentence, and REMAND for resentencing within the guidelines.', 'sentencing', 'State v. Subido', 'https://www.courtlistener.com/opinion/1110728/', '1110728') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 7-18-112 (1987), we held that the defendant was entitled to receive credit.', 'general', 'Kupec v. State', 'https://www.courtlistener.com/opinion/1118358/', '1118358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Kupec v. State', 'https://www.courtlistener.com/opinion/1118358/', '1118358') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the court’s mutual combat charge acted as a limitation on the Petitioner’s ability to claim self-defense, and prejudiced him by transferring the State’s burden to disprove self-defense onto the Petitioner, forcing him to prove self-defense in violation of Burkhart;', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1311284/', '1311284') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we REVERSE Petitioner’s convictions and REMAND for a new trial.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1311284/', '1311284') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Petitioner’s conviction for Possession of a Firearm or Knife during Commission of a Violent Crime in addition to his murder *236conviction because Petitioner''s murder conviction served as the prerequisite violent crime for his weapons charge conviction.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1311284/', '1311284') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 7041 does not violate the Vermont Constitution’s separation-of-powers clause, and affirm.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/2403975/', '2403975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that § 7041 does not violate the separation-of-powers principle established in the Vermont Constitution.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/2403975/', '2403975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, considering the legislature’s right to set the parameters for punishment, and the similarity between the power accorded the state’s attorney in § 7041 and other prosecutorial and executive powers, we conclude that § 7041 does not impermissibly interfere with the judiciary’s core functions.', 'general', 'State v. Pierce', 'https://www.courtlistener.com/opinion/2403975/', '2403975') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we find that a defendant who requests an instruction on a lesser-included offense or affirmatively relies thereon may contest the sufficiency of the evidence on a lesser-included offense only when the evidence is insufficient to convict the defendant on the greater charge as well.', 'general', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the contrary, we find that the act of requesting the instruction on the lesser-included offense or affirmatively relying *827 on the instruction waives this right in exchange for the possibility of allowing the jury to exercise its pardon power.', 'general', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In appellate case number 96-1294, we reverse appellant''s conviction for armed burglary with a firearm and remand for new trial.', 'general', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In appellate case number 96-0861, we reverse appellant''s conviction on count V in case number 92-24200, thereby mooting the subsequent revocation of probation and resulting prison sentence on this count.', 'sentencing', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse appellant''s conviction on count V in case number 92-24200, thereby mooting the subsequent revocation of probation and resulting prison sentence on this count.', 'sentencing', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his conviction for aggravated assault with a firearm.', 'general', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the other probation revocations, we affirm.', 'general', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because it is clear from the record in the immediate case that there was sufficient evidence to support a conviction on the greater offense of attempted second degree murder of Damion Kerlew with a firearm, we affirm appellant''s aggravated assault with a firearm conviction based on the reasoning set forth in Espinosa.', 'general', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the revocation of appellant''s probation in the remaining cases.', 'general', 'Viveros v. State', 'https://www.courtlistener.com/opinion/1723698/', '1723698') ON CONFLICT DO NOTHING;
