INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'declare a mistrial, and we affirmed.', 'mistrial', 'RODNEY HARMON v. STATE OF ARKANSAS', 'https://www.courtlistener.com/opinion/4757591/', '4757591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the court committed no error by using this information to evaluate Gibson''s character.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1397451/', '1397451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record adequately supports the jury''s determination *5 that the elements of attempted subornation were proven.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1397451/', '1397451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it does not contradict the sequence of events related in our opinion.', 'general', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1397451/', '1397451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For reasons explained below, we affirm the judgment of conviction and the sentence.', 'sentencing', 'State v. Gibson', 'https://www.courtlistener.com/opinion/1397451/', '1397451') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a defendant’s right to trial in magistrate court under West Virginia Code § 50-5-7 attaches when a criminal proceeding has been initiated in that forum.', 'general', 'State v. Bruffey', 'https://www.courtlistener.com/opinion/1420177/', '1420177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful review of the entire record, the parties’ briefs, and the relevant law, we conclude that the first and second assignments of error merit reversal, while the thud does not.', 'general', 'State v. Bruffey', 'https://www.courtlistener.com/opinion/1420177/', '1420177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful analysis, we conclude that West Virginia Code § 50-5-7 is inapplicable on the record before us.', 'general', 'State v. Bruffey', 'https://www.courtlistener.com/opinion/1420177/', '1420177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand the matter to the circuit court with directions to resentenee the Appellant after first procuring a presentence report, if needed as a sentencing aid, and affording the Appellant his right of allocution.', 'sentencing', 'State v. Bruffey', 'https://www.courtlistener.com/opinion/1420177/', '1420177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the circuit court’s decision to dispense with a presentence investigation and report was based upon a misapprehension of the relevant sentencing statutes, we reverse and remand for a determination of whether a presentence investigation and report are needed for sentencing in light of the availability of home detention as an alternative to incarceration.', 'sentencing', 'State v. Bruffey', 'https://www.courtlistener.com/opinion/1420177/', '1420177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 1 We hold that driving on a DUI-suspended license is a jury-eligible offense and that Arizona Revised Statutes Annotated ("A.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that section 22-320 applies to all lower courts.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 21 We hold that section 22-320 is constitutional.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that driving on a DUI-suspended license is a jury-eligible offense and that A.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 8 When we apply the Rothweiler analysis and follow its holding, as all courts inferior to the supreme court must do, we conclude that a person charged with driving on a DUI-suspended license is entitled to a jury in Arizona for the same reasons that a person charged with DUI is entitled to a jury in Arizona.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because these different procedures were incorporated into the constitution without substantive change, we conclude that a reasonable basis exists for having different jury waiver procedures in inferior and superior courts.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 23 We conclude that Rule 18.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 24 We conclude that a defendant validly waives the right to a jury by failing to comply with section 22-320 after having been given timely notice of both the right to a jury and the provisions of section 22-320.', 'general', 'Benitez v. Dunevant', 'https://www.courtlistener.com/opinion/1191942/', '1191942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the totality of the circumstances, we hold that a reasonable person in defendant’s position would not have believed that he was under arrest or that his freedom of movement was restrained to the degree of a formal arrest.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant’s subsequent statements “so many black belts” and “I’ll kill you” are relevant in the context of direct examination to show that what was “up under [defendant’s] belt” was a human life, that the defendant had already “killed ope” woman like Officer McCormick, and that by “belt,” defendant meant black belt.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing and the entire record in this case, we hold that defendant received a fair trial and capital sentencing proceeding, free of reversible error.', 'sentencing', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hunt, this Court held that short-form indictments satisfy state and federal constitutional requirements.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s findings of fact are supported by competent record evidence, and that the court properly applied the law to those facts.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence presented by the State is sufficient evidence from which a jury could infer defendant’s intent to engage in vaginal intercourse with the victim against her will.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After thoroughly reviewing the record, transcripts, and briefs in this case, we conclude that the evidence fully supports the aggravating circumstance found by the jury.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that nothing in the record suggests defendant’s death sentence was imposed under the influence of passion, prejudice, or any other arbitrary factor.', 'sentencing', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From this and other relevant evidence, we conclude that the crime committed by defendant in this case was equally as brutal as other murders for which a death sentence has been *429imposed.', 'sentencing', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following careful review of the record, we find that defendant was not in “custody” for purposes of Miranda and that Miranda warnings were, therefore, not required.', 'general', 'State v. Garcia', 'https://www.courtlistener.com/opinion/1234039/', '1234039') ON CONFLICT DO NOTHING;
