INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Randel v.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1792208/', '1792208') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"In such cases where the prejudicial effect of what the jury heard was such that no amount of subsequent admonition from the trial judge would be likely to eradicate from the jury''s mind the prejudicial effect, we reverse, although such occasions are rare.', 'general', 'King v. State', 'https://www.courtlistener.com/opinion/1792208/', '1792208') ON CONFLICT DO NOTHING;
