INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to this point, we hold that Sears is not legally responsible for the time Koepnick was detained after he was arrested for disorderly conduct by the Mesa police.', 'general', 'Koepnick v. Sears Roebuck & Co.', 'https://www.courtlistener.com/opinion/1312179/', '1312179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the trial court did not err in denying Sears’ motion for a directed verdict on Koepnick’s claim for false arrest.', 'general', 'Koepnick v. Sears Roebuck & Co.', 'https://www.courtlistener.com/opinion/1312179/', '1312179') ON CONFLICT DO NOTHING;
