INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the order complies with rule 59(m) and there is no shift of the burden of persuasion to Sears.', 'general', 'Koepnick v. Sears Roebuck & Co.', 'https://www.courtlistener.com/opinion/1312179/', '1312179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s directed verdict in favor of Sears on this issue.', 'general', 'Koepnick v. Sears Roebuck & Co.', 'https://www.courtlistener.com/opinion/1312179/', '1312179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the reasoning of the United States Supreme Court, we held that only evidence that bore on defendant’s character would be admissible in a capital penalty phase proceeding.', 'general', 'State v. Blackmon', 'https://www.courtlistener.com/opinion/1542499/', '1542499') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the reasoning of courts in other jurisdictions, we hold that the testimony of Ms.', 'general', 'State v. Alexander', 'https://www.courtlistener.com/opinion/1312327/', '1312327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the''tést to the''unique facts of this casé, we hold that the emotional trauma evidence is unduly prejudicial and should have been excluded.', 'general', 'State v. Alexander', 'https://www.courtlistener.com/opinion/1312327/', '1312327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming the verdicts here were inconsistent, we hold that Alexander has suffered no prejudice from such.', 'general', 'State v. Alexander', 'https://www.courtlistener.com/opinion/1312327/', '1312327') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the facts testified to by the defendant raised the inference of self-defense.', 'general', 'State v. Lujan', 'https://www.courtlistener.com/opinion/1234395/', '1234395') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Ray v. Ray', 'https://www.courtlistener.com/opinion/1406222/', '1406222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the family court''s dismissal of this action and remand for further proceedings consistent with this opinion.', 'dismissal', 'Ray v. Ray', 'https://www.courtlistener.com/opinion/1406222/', '1406222') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying that standard, we conclude that the trial court misconceived the strength of defendant''s legal challenge to *114the *533complaint.', 'general', 'State v. Carroll', 'https://www.courtlistener.com/opinion/6486183/', '6486183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we disagree with the trial court''s finding of probable cause as to the former charge, and discern significant legal impediments to successful prosecution of the latter one, we reverse, and remand for reconsideration.', 'probable_cause', 'State v. Carroll', 'https://www.courtlistener.com/opinion/6486183/', '6486183') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Reynolds v. State', 'https://www.courtlistener.com/opinion/1234504/', '1234504') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 540 (1992) ("We conclude that sec.', 'general', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Knight, a unanimous decision of this court, we concluded that the law provided an ineffective assistance of appellate counsel claim must be brought in the court of appeals.', 'ineffective_assistance', 'State v. Tramell E. Starks', 'https://www.courtlistener.com/opinion/1033713/', '1033713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a rational factfinder could reasonably reject Moseley''s theories in his defense and find that the totality of the suspicious circumstances proved beyond a reasonable doubt that Moseley was the criminal agent in each of the offenses charged.', 'general', 'Commonwealth v. Moseley', 'https://www.courtlistener.com/opinion/4398229/', '4398229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a rational juror could have rejected the defendant''s theory of innocence as being unreasonable, based "upon consideration of all the evidence and the reasonable inferences that flow from that evidence.', 'general', 'Commonwealth v. Moseley', 'https://www.courtlistener.com/opinion/4398229/', '4398229') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that an error in the charge on the elements of a lesser-ineluded offense to felony murder was harmless because the evidence in support of any lesser-ineluded offense was “virtually nil.', 'general', 'State v. Kinney', 'https://www.courtlistener.com/opinion/2092271/', '2092271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the question is relatively close, we conclude that the evidence warranted an intoxication charge, informing the jury that it could consider defendant’s intoxication as bearing on his intent to commit the charged crimes.', 'general', 'State v. Kinney', 'https://www.courtlistener.com/opinion/2092271/', '2092271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court here acted well within its discretion in finding the motion to strike untimely.', 'general', 'State v. Kinney', 'https://www.courtlistener.com/opinion/2092271/', '2092271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that explanations or excuses offered by other rapists were not relevant, and, in any event, the prejudicial effect of the testimony outweighed the probative value because the jury could have convicted defendant because “he fit the mold” and not because of the evidence in the case.', 'general', 'State v. Kinney', 'https://www.courtlistener.com/opinion/2092271/', '2092271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the expert testimony was tantamount to an expert opinion that the victim was telling the truth and that it invaded the proper role of the jury.', 'general', 'State v. Kinney', 'https://www.courtlistener.com/opinion/2092271/', '2092271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed defendant’s conviction in part because of the admission of this testimony.', 'general', 'State v. Kinney', 'https://www.courtlistener.com/opinion/2092271/', '2092271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both the jury verdicts and the sentence.', 'sentencing', 'State v. Kinney', 'https://www.courtlistener.com/opinion/2092271/', '2092271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the admission of PTSD evidence in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and we affirm its decision that Dr.', 'general', 'State v. Kinney', 'https://www.courtlistener.com/opinion/2092271/', '2092271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the prosecutor’s argument was based on the evidence and did not misstate or manipulate the evidence, we hold that the argument was not improper.', 'general', 'State v. Warren', 'https://www.courtlistener.com/opinion/1312667/', '1312667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reading the prosecutor’s arguments in context, we hold that they were properly based on the facts in evidence.', 'general', 'State v. Warren', 'https://www.courtlistener.com/opinion/1312667/', '1312667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no distinction between these two aggravating circumstances, we hold that the “previously convicted” language in N.', 'general', 'State v. Warren', 'https://www.courtlistener.com/opinion/1312667/', '1312667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 360 (1994), we held that want of provocation on the part of the deceased, the brutality of the murder, and attempts to cover up involvement in the crime are among other circumstances from which premeditation and deliberation can be inferred.', 'general', 'State v. Warren', 'https://www.courtlistener.com/opinion/1312667/', '1312667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we note that in defendant’s previous assignment of error, we held that the “previously convicted” language in N.', 'general', 'State v. Warren', 'https://www.courtlistener.com/opinion/1312667/', '1312667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the prosecutor did not label “defendant an ‘animal’ or refer to him by any other disparaging term.', 'general', 'State v. Warren', 'https://www.courtlistener.com/opinion/1312667/', '1312667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that we will not condone an argument asking jurors to put themselves in place of the victims.', 'general', 'State v. Warren', 'https://www.courtlistener.com/opinion/1312667/', '1312667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the foregoing rules to the evidence presented in this case, we conclude that there was sufficient evidence from which a rational jury could find that defendant killed Katherine Johnson with premeditation and deliberation.', 'general', 'State v. Warren', 'https://www.courtlistener.com/opinion/1312667/', '1312667') ON CONFLICT DO NOTHING;
