INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we hold that the district court did not abuse its discretion.', 'general', 'State v. Cottew', 'https://www.courtlistener.com/opinion/2021177/', '2021177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such an extension is permitted, but is not required, by rule 27.', 'general', 'State v. Cottew', 'https://www.courtlistener.com/opinion/2021177/', '2021177') ON CONFLICT DO NOTHING;
