INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that our prior cases do not require the three
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we conclude that the district court did not revoke Cottew’s probation and execute her underlying sentence, and that the incarceration ordered in this case was instead an intermediate sanction for the probation violation.', 'sentencing', 'State v. Cottew', 'https://www.courtlistener.com/opinion/2021177/', '2021177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the rule must be construed to permit the district court to continue a probationer’s stay and place her on probation in any manner authorized by the statute.', 'general', 'State v. Cottew', 'https://www.courtlistener.com/opinion/2021177/', '2021177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '135 expressly authorizes the district court to impose intermediate sanctions with or without placing the defendant on probation, we conclude that a district court is not required to impose probation in connection with the imposition of intermediate sanctions for a probation violation.', 'general', 'State v. Cottew', 'https://www.courtlistener.com/opinion/2021177/', '2021177') ON CONFLICT DO NOTHING;
