INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm in part and reverse in part.', 'general', 'State v. Cottew', 'https://www.courtlistener.com/opinion/2021177/', '2021177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As early as 1924, this court held in State v.', 'general', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence seized must be suppressed.', 'suppression', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the order.', 'general', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we affirm the order of the circuit court granting the defendant''s motion to suppress the evidence.', 'suppression', 'State v. Tye', 'https://www.courtlistener.com/opinion/2023344/', '2023344') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Doing so, we hold that, based on public policy grounds, a claim for common-law negligence cannot be maintained against social hosts, such as the Niesens, who allegedly were aware that minors on their property were consuming alcohol, but who did not provide the alcohol, when an underage guest later allegedly caused an alcohol-related car accident.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we concluded that the defendant had breached a duty , that he owed to the plaintiff by not following through on his promise to drive his intoxicated co-worker home, we held that the *36plaintiffs claim should have been dismissed.', 'dismissal', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Hoida, we held that a subcontractor who incurred losses on a construction project, when the general contractor and the property owner fraudulently misappropriated about $650,000 of the project''s construction loan proceeds, had not provided sufficient facts to controvert the defendant-lenders'' "prima facie showing that it did not breach the duty of ordinary care under the circumstances .', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While this court found that Tynan owed Rockweit a duty of care under *42Wisconsin law, we held that public policy factors precluded liability against Tynan, even though Rockweit had established all four elements of a common-law negligence claim.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that" ''once it is determined that a negligent act has been committed and that the act is a substantial factor in causing the harm, the question of duty is irrelevant and a finding of nonliability can be made only in terms of public policy.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Rockweit court then listed the six public-policy factors described in detail previously in this opinion, and we held that the imposition of liability against Tynan, who did not "start, maintain, or provide any necessary incendiary materials for the fire[,] .', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that, "although Tynan owed Anthony a duty of ordinary care which the jury determined was breached,.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Koback, this court held that furnishing or giving alcoholic beverages to a minor constituted negligence per se and that social hosts were liable to third parties in proportion to the extent to which the provision of alcohol led to the harm.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this sixth factor is applicable to preclude liability against the Niesens.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a claim for common-law negligence cannot be maintained against social hosts who allegedly were aware that minors on their property were consuming alcohol, but who did not provide the alcohol, when an underage guest later was involved in an alcohol-related car accident.', 'general', 'Nichols v. Progressive Northern Insurance', 'https://www.courtlistener.com/opinion/2021681/', '2021681') ON CONFLICT DO NOTHING;
