INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing authorities, we find that appellant''s oral statement was, in itself, sufficient corroborative evidence to properly connect him with the crime.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1777808/', '1777808') ON CONFLICT DO NOTHING;
