INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Mr.', 'general', 'State of Tennessee v. Ledarren S. Hawkins', 'https://www.courtlistener.com/opinion/1043879/', '1043879') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 5-4-104(a) and § 16-90-120(a-b) can be read harmoniously to mean that § 16-90-120(a-b) is only a sentence enhancement, while the Arkansas Criminal Code provides the minimum sentences to be imposed for each specific offense.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the enhanced felony charge based on the prior battering conviction for which the defendant was convicted, we held that it was error to enhance the defendant''s sentence further based on the general habitual *821 offender statute, codified at Ark.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that enhancement had already occurred under the DWI statute and that the general habitual offender statute, § 5-4-501, could not precipitate an additional sentence.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Again, we held that the stacking of the two enhancement statutes could not occur.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of conviction.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1505049/', '1505049') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, considering all the circumstances, the finder of fact could infer his intent was to commit a larceny rather than a rape or other crime.', 'general', 'Wright v. Commonwealth', 'https://www.courtlistener.com/opinion/1356359/', '1356359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the jury conviction and the judgment and sentence of the trial court.', 'sentencing', 'Jansen v. State', 'https://www.courtlistener.com/opinion/1163337/', '1163337') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1991), this Court held that appellate courts have authority to review fines imposed by trial courts and that the review of fines should be conducted in accordance with the principles of the statutory sentencing scheme.', 'sentencing', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1591495/', '1591495') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute is not facially unconstitutional under either the state or the federal constitution.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1591495/', '1591495') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the $27,500 fine imposed by the jury in this case is excessive under the principles of the Criminal Sentencing Reform Act.', 'sentencing', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1591495/', '1591495') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the fine assessed by the jury is excessive under the Criminal Sentencing Reform Act, the fine is modified to the statutory minimum of $3,000.', 'sentencing', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1591495/', '1591495') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying first the second proposition stated above, we conclude that the Court of Criminal Appeals did not indulge every presumption in favor of the constitutionality of Tenn.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1591495/', '1591495') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, consistent with the fundamental principle that courts should decide constitutional issues only if absolutely necessary, we conclude that the Court of Criminal Appeals erred in reviewing the constitutional validity of the fine before first evaluating the propriety of the fine under the principles of the Criminal Sentencing Reform Act.', 'sentencing', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1591495/', '1591495') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we conclude that the Court of Criminal Appeals erred in holding TenmCode Ann.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1591495/', '1591495') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse that part of the judgment of the Court of Criminal Appeals holding Tenn.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1591495/', '1591495') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court erred in refusing to give the lesser included offense instructions on the crime of manslaughter in this case.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court erred in refusing to give the lesser included offense instructions on the ground that Eckert afforded the defendant the right to waive them and the State would be bound by such a waiver.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with this approach, and we hold that the language of WYOMING RULE 31(c), which is identical to FEDERAL RULE 31(c), implies and requires that both prosecution and defense have an equal right to a lesser included offense instruction.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the determination of what offenses are "necessarily included in the offense charged" is primarily a question of law.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, applying these standards, the trial court erred in denying the State''s request for a lesser included offense instruction on voluntary manslaughter.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the requested instruction should have been given because all five of the Chapman elements were present and satisfied.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Using this standard as stated, we held that no evidence at trial justified any instruction for lesser included offenses.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following the teachings of these cases, we conclude that the failure to give a lesser included offense instruction which was supported by the evidence must constitute error implicating due process guarantees.', 'general', 'State v. Keffer', 'https://www.courtlistener.com/opinion/1145365/', '1145365') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that evidence of the DNA match and the accompanying statistical probability was properly admitted.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, where mental health professionals specifically testified that the victim was abused at the hands of the defendant, we held that "[s]uch testimony cannot be perceived to address an area in which expert testimony provides assistance to the jury in resolving a factual issue.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that none of the delay in bringing appellant to trial may be included in the speedy trial calculation.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that "at some level, the statistical probability could be perceived as an opinion by the expert that the accused is guilty" and that the "better practice in Wyoming should be not to refer to the statistical probability of duplication when introducing DNA test results.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our determination in Rivera parallels a most recent decision of the United States Supreme Court.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Springfield v. State', 'https://www.courtlistener.com/opinion/1145372/', '1145372') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that this brief comment did not prejudice or influence the jury as to their duty.', 'general', 'Faraga v. State', 'https://www.courtlistener.com/opinion/1897319/', '1897319') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Persuaded no reversible error was committed, we affirm.', 'general', 'Faraga v. State', 'https://www.courtlistener.com/opinion/1897319/', '1897319') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that petitioner has not alleged facts sufficient to constitute excusable neglect so as to avoid the five-year time limitation set forth in R.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1441375/', '1441375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under those circumstances, we conclude that R.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1441375/', '1441375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this bare assertion of an alibi at this late date, without more, is insufficient to support a prima facie case of ineffectiveness.', 'ineffective_assistance', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1441375/', '1441375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, considering the extent and cause of the delay and the obvious prejudice to the State and balancing those considerations against the showing petitioner has made, we conclude that a prima facie showing of ineffective assistance has not been made.', 'ineffective_assistance', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1441375/', '1441375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that that argument was inconsistent with the language of R.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1441375/', '1441375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant again appealed, and in an unpublished opinion on December 1, 1992, we affirmed.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1441375/', '1441375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dugan, supra, we affirmed defendant''s conviction but remanded for resentencing.', 'sentencing', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1441375/', '1441375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our prior opinion we affirmed defendant''s convictions but remanded with the understanding that in the event the statements were deemed inadmissible the conviction should be vacated.', 'general', 'State v. Cummings', 'https://www.courtlistener.com/opinion/1441375/', '1441375') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reversing the conviction, we held that Simpson was convicted of a different incident than the one specified in the indictment.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that none of the issues raised in this appeal warrants reversing any of his convictions.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Grandstaff''s case is such a case.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Beistline did not abuse his discretion when he rejected Grand-staffs claims and declined to dismiss the indictment.', 'dismissal', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Judge Beistline did not abuse his discretion in denying the motion to sever.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Grandstaff does not explain his privacy argument further, so we conclude that it is waived for inadequate briefing.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that this error was harmless.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But given the length of Grandstaff''s trial and volume of evidence presented, we conclude that the error in eliciting Sergeant Geier''s personal opinion on these matters was harmless.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Beistline did not abuse his discretion by overruling Grand-staff''s objections to Sergeant Gefer''s testimony.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that any error in admitting this evidence was harmless.', 'general', 'Grandstaff v. State', 'https://www.courtlistener.com/opinion/2637338/', '2637338') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Chamberlain, we held that the legislature''s amendments to Section 1420 of the County Code, 16 Pa.', 'general', 'Commonwealth v. Shaffer', 'https://www.courtlistener.com/opinion/1897598/', '1897598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 593 (1999), where we concluded that the legislature''s amendment of Section 1420 of the County Code, 16 P.', 'general', 'Commonwealth v. Shaffer', 'https://www.courtlistener.com/opinion/1897598/', '1897598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we find that the Superior Court erred.', 'general', 'Commonwealth v. Shaffer', 'https://www.courtlistener.com/opinion/1897598/', '1897598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse its decision.', 'general', 'Commonwealth v. Shaffer', 'https://www.courtlistener.com/opinion/1897598/', '1897598') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that the State presented sufficient evidence that defendant changed her address and failed to comply with the requirements of the registration program.', 'general', 'State v. Abshire', 'https://www.courtlistener.com/opinion/1318917/', '1318917') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the legislature intended the definition of address under the registration program to carry an ordinary meaning of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When this evidence is viewed in the light most favorable to the State, and when the State is afforded the benefit of every reasonable inference supported by that evidence, we conclude that the State presented sufficient evidence that defendant changed her address to withstand defendant’s motion to dismiss.', 'dismissal', 'State v. Abshire', 'https://www.courtlistener.com/opinion/1318917/', '1318917') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the trial court properly denied defendant’s motions to dismiss, and we reverse the Court of Appeals.', 'dismissal', 'State v. Abshire', 'https://www.courtlistener.com/opinion/1318917/', '1318917') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the Court of Appeals based on the issue presented as the basis for the dissenting opinion, it is unnecessary for us to consider the additional issue presented by the State of whether the Court of Appeals majority used an improper standard for ruling on defendant’s motion to dismiss.', 'dismissal', 'State v. Abshire', 'https://www.courtlistener.com/opinion/1318917/', '1318917') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that this factor should not have been applied.', 'general', 'State v. Keel', 'https://www.courtlistener.com/opinion/2465148/', '2465148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the trial court should not have used this factor to enhance Marshall’s sentence.', 'sentencing', 'State v. Keel', 'https://www.courtlistener.com/opinion/2465148/', '2465148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that the trial court could not use the inherent traits of cocaine to enhance the sentence under factor (10) given the facts in this case.', 'sentencing', 'State v. Keel', 'https://www.courtlistener.com/opinion/2465148/', '2465148') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1993), we held that although age is an element of the offense of aggravated rape involving a child under the age of thirteen, factor (4) may be used if “circumstances show that the victim, because of [the victim’s] age or physical or mental condition, was in fact, particularly vulnerable.', 'general', 'State v. Kissinger', 'https://www.courtlistener.com/opinion/2462771/', '2462771') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The court reasoned that “in the absence of proof of violence or proof that appellant’s actions were motivated by hate, revenge or another non-sexual motive, we conclude that the record supports that trial court’s finding.', 'general', 'State v. Kissinger', 'https://www.courtlistener.com/opinion/2462771/', '2462771') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the single, isolated fact of orgasm is insufficient to justify any conclusion concerning the motivation for a rape.', 'general', 'State v. Kissinger', 'https://www.courtlistener.com/opinion/2462771/', '2462771') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the sentences imposed by the trial court.', 'sentencing', 'State v. Kissinger', 'https://www.courtlistener.com/opinion/2462771/', '2462771') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the accused, who was convicted of murder in the second degree and aggravated assault resulting from a motor vehicle collision, was not eligible for sentencing pursuant to the Community Corrections Act.', 'sentencing', 'State v. Braden', 'https://www.courtlistener.com/opinion/2425429/', '2425429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Recently, this Court held that a person who is convicted of vehicular homicide or vehicular assault is not eligible for sentencing pursuant to the Act.', 'sentencing', 'State v. Braden', 'https://www.courtlistener.com/opinion/2425429/', '2425429') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient to support the trial court’s conclusions on these points.', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court also properly analyzed defendant’s subjective awareness of that risk, as required for the mens rea of recklessness.', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the record contains more than enough evidence to establish that the bridge abutment was, in fact, “dangerous and unhealthy.', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is sufficient that a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both convictions as legally sound and supported by the evidence.', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the defendant’s conviction.', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed the conviction of a defendant charged with disorderly conduct for “recklessly creating] a risk of public inconvenience by engaging in violent behavior” when he struck a woman’s arm as she and another woman walked shoulder to shoulder down the side walk in the direction opposite his.', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed a conviction under § 1026(1) where a defendant, “in addition to yelling and screaming, .', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirmed a conviction under the abusive-language portion of the statute for conduct inside a hospital.', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is on this latter basis that we affirm.', 'general', 'State v. Amsden', 'https://www.courtlistener.com/opinion/1043608/', '1043608') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In several eases decided before the enactment of the Sentencing Act, this court held that probation should not be granted where a death was involved unless “exceptional circumstances” are present.', 'sentencing', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the presumption that the trial court’s findings were correct, we conclude that the appellant created a high risk to the lives of at least three people other than the victim.', 'general', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s mitigation findings were proper pursuant to Tenn.', 'general', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we conclude that one enhancement factor and two mitigating factors are present.', 'general', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'review, we conclude that the presumptive minimum sentence of three years is appropriate.', 'sentencing', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has failed to meet this burden.', 'general', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we have determined that the circumstances of the offense are not egregious enough by themselves to overcome the presumption of alternative sentencing, we conclude that they are sufficiently reprehensible to deny full probation.', 'sentencing', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'appellant is not entitled to full probation, we conclude that the trial court did not abuse its discretion in denying the appellant’s request for diversion.', 'general', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that a sentence of split confinement would both serve the ends of justice and fulfill the rehabilitative needs of the appellant.', 'sentencing', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that consideration of the appellant’s remorse and lack of any criminal record whatsoever as mitigating factors is consistent with the purposes and principles of the Sentencing Act.', 'sentencing', 'State v. Bingham', 'https://www.courtlistener.com/opinion/1638328/', '1638328') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 705 (1967), we held that before a federal constitutional error can be held harmless, the reviewing *412 court must find "beyond a reasonable doubt that the error complained of did not contribute to the verdict obtained.', 'general', 'State v. Walker', 'https://www.courtlistener.com/opinion/1638125/', '1638125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that this statement in Crabtree has been totally abrogated by the current statute, T.', 'general', 'State v. Walker', 'https://www.courtlistener.com/opinion/1638125/', '1638125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we hold that the indemnity provision is simply inapplicable to the factual predicate of Audi’s claim, we need not address the public policy issue.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly granted summary disposition in favor of Laser on Auch’s counterclaim, though it did so under an alternative ground.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion when it granted defendants’ motion in limine.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion when it excluded this evidence, and, were we to conclude there was error, that error would be harmless.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because neither BAS nor Auch was plaintiffs’ “employer” for the purposes of § 202, we hold that the trial court properly granted a directed verdict in favor of defendants.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly granted defendants’ motion for directed verdict.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly granted defendants’ motion for directed verdict because § 402 does not apply to the facts of this case.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly denied plaintiffs’ motion for JNOV with respect to the breach of contract count.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court properly granted summary disposition in favor of defendants with respect to plaintiffs’ third-party beneficiary claim.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion when it overruled plaintiffs’ objection to Schaer’s testimony.', 'general', 'Badiee v. Brighton Area Schools', 'https://www.courtlistener.com/opinion/1278331/', '1278331') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court''s finding of the HAC aggravator was proper.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1996), we held that the death sentence was disproportionate in connection with a shooting that occurred during what was described as probably a "robbery gone bad," id.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1987), this Court held in postconviction proceedings that trial counsel was not ineffective for failing to request special additional instructions on the presumption of innocence because "the general standard instructions on the presumption of innocence .', 'ineffective_assistance', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these statements were admissible under the concepts of excited utterances or dying declarations as we more fully discuss below.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While this assertion may be arguable, we conclude that it is insufficient to overcome the abuse of discretion standard necessary to overturn the trial court''s evidentiary ruling.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts and the dire medical circumstances present, we conclude that when Dyke made the Gillespie statements, she feared her death was imminent.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these facts, we conclude that the admission of the hospital statements as dying declarations was not clearly erroneous.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having considered Williams''s assertions, we conclude that his allegations of judicial bias are without merit.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that even if the claim were meritorious, which it is not, Williams waived his challenge to the prematurely prepared order.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With regard to the determination that the hospital statements were admissible on a ground not advanced by the State, we conclude that the trial court did not depart from a stance of neutrality and assume the role of prosecutor.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1846649/', '1846649') ON CONFLICT DO NOTHING;
