INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶2        For the reasons that follow, we affirm the judgment of the appellate court.', 'general', 'In re Shelby R.', 'https://www.courtlistener.com/opinion/1086953/', '1086953') ON CONFLICT DO NOTHING;
