INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Malo', 'https://www.courtlistener.com/opinion/4766245/', '4766245') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that Richardson’s failure to surrender to the sheriff s office constituted a lack of good behavior and the trial court’s finding that appellant violated the written condition of his suspension that he “shall live a law-abiding life” and “be of good behavior” was not against the preponderance of the evidence.', 'general', 'Harris v. State', 'https://www.courtlistener.com/opinion/1651516/', '1651516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the order revoking appellant’s suspended sentences and dismiss.', 'dismissal', 'Harris v. State', 'https://www.courtlistener.com/opinion/1651516/', '1651516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the trial court based its revocation of appellant’s suspended sentences on the violation of a condition that was not a written condition of his suspension, we reverse.', 'sentencing', 'Harris v. State', 'https://www.courtlistener.com/opinion/1651516/', '1651516') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the circuit judge did not abuse his discretion in denying the motion for a mistrial.', 'mistrial', 'Meadows v. State', 'https://www.courtlistener.com/opinion/2358082/', '2358082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Meadows''s arguments are without merit, and we affirm.', 'general', 'Meadows v. State', 'https://www.courtlistener.com/opinion/2358082/', '2358082') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 30, 32 (1973), wherein we held that implementing Administrative Order No.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Trombly, where we held that "delay arising out of the relationship between attorney and client must be attributed *1122 to the defendant, and omitted from consideration.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 138, 139 (1978), this Court held that "[t]he passage of over eighteen months from citation to trial, not brought about by the defendant, is so long as to constitute prejudice as a matter of law and a violation of the defendant''s constitutional rights.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining specific periods of time, we conclude that the period between July and November 2001 should not count against the state because much of the delay during that period was the result of defendant''s motion to recuse the trial judge.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, we conclude that a significant portion of the delay in bringing defendant to trial must be attributed to the state, even though most of the delay was caused by the inability or unwillingness of assigned counsel to move the case forward.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the entire circumstances in this caseparticularly defendant''s lengthy pretrial incarceration, much of which is not attributable to defendant we conclude that the prejudice factor must be weighed against the state.', 'general', 'State v. Brillon', 'https://www.courtlistener.com/opinion/1977472/', '1977472') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion in imposing a 24-year sentence on defendant.', 'sentencing', 'People v. Alexander', 'https://www.courtlistener.com/opinion/2481840/', '2481840') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon reviewing the record, we find that the trial court did not abuse its discretion in sentencing defendant to 24 years’ imprisonment.', 'sentencing', 'People v. Alexander', 'https://www.courtlistener.com/opinion/2481840/', '2481840') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the sentence imposed on defendant by the trial court was not “greatly at variance with the spirit and purpose of the law, or manifestly disproportionate to the nature of the offense.', 'sentencing', 'People v. Alexander', 'https://www.courtlistener.com/opinion/2481840/', '2481840') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the appellate court’s judgment and reinstate defendant’s 24-year sentence.', 'sentencing', 'People v. Alexander', 'https://www.courtlistener.com/opinion/2481840/', '2481840') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the judgment of the appellate court and reinstate defendant’s 24-year sentence.', 'sentencing', 'People v. Alexander', 'https://www.courtlistener.com/opinion/2481840/', '2481840') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the police may use a decoy victim over the age of 16 and still convict a defendant of attempted lewd and lascivious.', 'general', 'Hudson v. State', 'https://www.courtlistener.com/opinion/1707948/', '1707948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under these circumstances the trial court correctly decided the information charged a crime supported by an overt act.', 'general', 'Hudson v. State', 'https://www.courtlistener.com/opinion/1707948/', '1707948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we conclude that a jury could find that Mr.', 'general', 'Hudson v. State', 'https://www.courtlistener.com/opinion/1707948/', '1707948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm, discussing only the denial of his motions to dismiss the charge of attempted lewd and lascivious.', 'dismissal', 'Hudson v. State', 'https://www.courtlistener.com/opinion/1707948/', '1707948') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') 226 (1807), this Court held that a twenty dollar wager on a horse race was not illegal.', 'general', 'Berkebile v. Outen', 'https://www.courtlistener.com/opinion/1307803/', '1307803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 660 (1991), this Court held that the statute did not specifically exclude a nonmechanical payout for a video poker game.', 'general', 'Berkebile v. Outen', 'https://www.courtlistener.com/opinion/1307803/', '1307803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Berkebile v. Outen', 'https://www.courtlistener.com/opinion/1307803/', '1307803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a violation of probation relates to mitigating, not aggravating, factors as identified at a defendant’s original sentencing hearing.', 'sentencing', 'State v. Baylass', 'https://www.courtlistener.com/opinion/2059962/', '2059962') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In neither case did we hold that §§ 2113(d) and (e) set forth distinct offenses.', 'general', 'Jones v. United States', 'https://www.courtlistener.com/opinion/118274/', '118274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 883 (1964), a case in which the trial judge determined that a defendant freely, without coercion or duress, consented to a search of a rooming house, this court held that such a determination would not be overturned on appeal where the trial judge had a better opportunity to determine the circumstances surrounding the search and had the opportunity to hear the testimony and observe the demeanor of the witnesses.', 'general', 'Tombrello v. State', 'https://www.courtlistener.com/opinion/1097769/', '1097769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), a drug possession case where the State relied on constructive possession, this court held that in order to prove possession the State must prove beyond a reasonable doubt that the accused knew of the presence of the prohibited substance.', 'general', 'Tombrello v. State', 'https://www.courtlistener.com/opinion/1097769/', '1097769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), another drug possession case, this court held that, when the presence of the accused at the scene is established and evidence of his knowledge of the presence of the prohibited substance is shown (even by circumstantial evidence), along with any other incriminating evidence, the issue of defendant''s guilt should be submitted to the jury.', 'general', 'Tombrello v. State', 'https://www.courtlistener.com/opinion/1097769/', '1097769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After viewing the evidence in a light most favorable to the State, we find that there was sufficient evidence to support his conviction of receiving stolen property in the first degree.', 'general', 'Tombrello v. State', 'https://www.courtlistener.com/opinion/1097769/', '1097769') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the denial of the requested instruction was reversible error, and we remand this case for a new trial on this point.', 'general', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the facts of this case, the trial court abused its discretion in refusing the request.', 'general', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion in refusing the appellant’s request.', 'general', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that ordering a capias to compel previously-subpoenaed nonparty witnesses to appear in court to testify was not a critical stage of the criminal proceeding and was harmless to the defense of the absent defendant.', 'general', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not abuse its discretion in denying the motions for a bifurcated trial in the instant case.', 'general', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the additional element that the actor be 16 years of age or older for conviction under third degree sexual assault, W.', 'general', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 637 (1973), where we held that an instruction on a defendant’s disposition constituted impermissible advice to the jury on the question of “punishment”, a matter for the Court to consider and not the jury.', 'general', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “[i]n a criminal prosecution, the State is required to prove beyond a reasonable doubt every material element of the crime with which the defendant is charged, and it is error for the court to instruct the jury in such a manner as to require it to accept a presumption as proof beyond a reasonable doubt of any material element of the crime with which the defendant is charged or as requiring the defendant either to introduce evidence to rebut the presumption or to carry the burden ...', 'general', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
