INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that it was unfair to deny a defendant a requested jury instruction on his disposition should the jury find him not guilty by reason of insanity.', 'jury_instruction', 'State v. Daggett', 'https://www.courtlistener.com/opinion/1315126/', '1315126') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, after viewing the evidence in the light most favorable to the prosecution, a rational trier of fact could have found the essential elements of the crime beyond a reasonable doubt.', 'general', 'People v. Schmalz', 'https://www.courtlistener.com/opinion/1977652/', '1977652') ON CONFLICT DO NOTHING;
