INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that: (1) The record supports a finding that Kane''s conflict of interest could have compromised his ability to render effective assistance to appellant during the remainder of the trial.', 'general', 'Douglas v. United States', 'https://www.courtlistener.com/opinion/1479756/', '1479756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 56,[27] we conclude that a defendant''s choice of counsel is among the fundamental defense decisions constitutionally protected under Faretta and Frendak.', 'general', 'Douglas v. United States', 'https://www.courtlistener.com/opinion/1479756/', '1479756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Lewis, we affirmed a trial court''s restriction of a defendant''s choice of counsel, without a hearing, because it was "apparent .', 'general', 'Douglas v. United States', 'https://www.courtlistener.com/opinion/1479756/', '1479756') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in refusing to allow the questioning of prospective jurors concerning their views on parole, as such questioning is irrelevant under the facts of this capital resentencing proceeding.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant received a fair sentencing proceeding, free of prejudicial error.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this Court held in Brown, 320 N.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bacon I, this Court held that any reasonable doubt about the submission of a mitigating circumstance must be resolved in defendant''s favor.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 703 (1983), this Court held the death sentences disproportionate.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circumstances of Gladden, Clark, and the numerous cases cited by defendant in which the jury returned a life sentence, or in which this Court held the death sentences disproportionate, distinguish those cases from the present case;', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" A chief reason this Court held the death sentence to be disproportionate in Benson was that, in comparison to Jackson, the sentencing jury in Benson found considerably more mitigating circumstances: that the defendant had no significant history of prior criminal activity;', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed herein, we conclude that defendant received a fair sentencing proceeding, free of prejudicial error, and that the sentence of death is not disproportionate.', 'sentencing', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant has failed to demonstrate any violation of his constitutional protections.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these challenged communications were of an administrative nature and did not relate to the consideration of defendant''s guilt or innocence.', 'general', 'State v. Bacon', 'https://www.courtlistener.com/opinion/1347678/', '1347678') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the principles announced in Long, Chrisman, and Hensley, we hold that police officers may, whenever they possess an articulable and objectively reasonable belief that a suspect is presently or potentially dangerous, conduct a protective search of the area within the suspect’s immediate control.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Initially, we find that the “stop” of the defendant was clearly valid.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we do not go so far as to adopt such a per se rule in a Terry context, we find that the concerns present in an arrest situation may also be present in an investigatory detention.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that this holding is necessary in the interest of police protection.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that Officer Farmer’s warrantless entry into the motel room was reasonable.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we find that the impoundment of the defendant’s car was reasonable.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Guided by these principles, we find that the evidence was sufficient to support convictions of possession of marijuana and cocaine with the intent to distribute.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgments of the trial court.', 'general', 'Servis v. Commonwealth', 'https://www.courtlistener.com/opinion/1349258/', '1349258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Appellant was not subject to official detention while he attended his second Thunder Child treatment program.', 'general', 'YellowBear v. State', 'https://www.courtlistener.com/opinion/1219239/', '1219239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'YellowBear v. State', 'https://www.courtlistener.com/opinion/1219239/', '1219239') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 693 (1986), where we held that a juror should be removed for cause where the juror “indicates an inclination to believe or disbelieve the testimony of someone he knows.', 'general', 'State v. Grega', 'https://www.courtlistener.com/opinion/1508299/', '1508299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court acted well within its discretion in denying the motion for change of venue.', 'general', 'State v. Grega', 'https://www.courtlistener.com/opinion/1508299/', '1508299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under these circumstances, the police did not exceed the scope of defendant’s consent by continuing their search on two subsequent days.', 'general', 'State v. Grega', 'https://www.courtlistener.com/opinion/1508299/', '1508299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court did not abuse its discretion in granting the State’s motion in limine and excluding the evidence discussed above.', 'general', 'State v. Grega', 'https://www.courtlistener.com/opinion/1508299/', '1508299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking at the evidence in the light most favorable to the State, we conclude that it was sufficient to support a finding of guilt beyond a reasonable doubt.', 'general', 'State v. Grega', 'https://www.courtlistener.com/opinion/1508299/', '1508299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the severity of this sentence, where aggravated murder and aggravated sexual assault criminalize the same conduct, as it does in this case, we conclude that the Legislature intended to consolidate the punishment for murder and aggravated sexual assault into one sentence for aggravated murder.', 'sentencing', 'State v. Grega', 'https://www.courtlistener.com/opinion/1508299/', '1508299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm both convictions and his mandatory sentence of life in prison without the possibility of parole for aggravated murder, but vacate defendant’s sentence for aggravated sexual assault.', 'sentencing', 'State v. Grega', 'https://www.courtlistener.com/opinion/1508299/', '1508299') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1997) ("We conclude that Walker was afforded what Florida and U.', 'general', 'Ford v. State', 'https://www.courtlistener.com/opinion/1736487/', '1736487') ON CONFLICT DO NOTHING;
