INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we deny the writ because we find that the petitioner is not entitled to the specific relief which he seeks in this mandamus proceeding.', 'general', 'State Ex Rel. Simpkins v. Harvey', 'https://www.courtlistener.com/opinion/1366073/', '1366073') ON CONFLICT DO NOTHING;
