INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the proper analysis of defendant officers'' claims of privilege to rebut excessive-foree allegations, pursuant to AS 11.', 'general', 'Samaniego v. City of Kodiak', 'https://www.courtlistener.com/opinion/2636849/', '2636849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The superior court adopted a qualified immunity rule which emphasized the officers'' subjective beliefs, We reverse the court''s determination of the applicable law and remand for the court to apply a different standard.', 'general', 'Samaniego v. City of Kodiak', 'https://www.courtlistener.com/opinion/2636849/', '2636849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore we reverse the summary judgment and remand for trial.', 'general', 'Samaniego v. City of Kodiak', 'https://www.courtlistener.com/opinion/2636849/', '2636849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these constitute reversible error so that a new trial is required.', 'general', 'Ward v. State', 'https://www.courtlistener.com/opinion/1963760/', '1963760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the quantum of evidence as to an accidental shooting and its relevancy to reasonable doubt, we conclude that it falls within the plain error rule.', 'general', 'Ward v. State', 'https://www.courtlistener.com/opinion/1963760/', '1963760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Court of Appeals erred, and its decision on this issue is reversed.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1387708/', '1387708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the State did not present enough other incriminating evidence to support a verdict based on constructive possession.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1387708/', '1387708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that the State had made a sufficient case to go to the jury on the issue of constructive possession.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1387708/', '1387708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When all the evidence is examined in a light most favorable to the State, as it must be on a motion to dismiss, we conclude that the evidence was sufficient to go to the jury on the issue of defendant’s constructive possession of the narcotics found in the mobile home.', 'dismissal', 'State v. Davis', 'https://www.courtlistener.com/opinion/1387708/', '1387708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the evidence of this case in a light most favorable to the State, we conclude that there was sufficient evidence to go to the jury under an instruction on constructive possession.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1387708/', '1387708') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 817 (1990), this Court held an individual had no standing to contest a warrantless search and seizure because there was no showing that the person owned or leased the searched premises.', 'search_seizure', 'Davasher v. State', 'https://www.courtlistener.com/opinion/1740214/', '1740214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction.', 'general', 'Davasher v. State', 'https://www.courtlistener.com/opinion/1740214/', '1740214') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 327 (1972), in which we held that circumstantial evidence, in order to support a finding of guilt, need no longer be inconsistent with
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming, however, that seizure of the currency exceeded the scope of a reasonable search for weapons, we find that the evidence is admissible under the “inevitable discovery” exception to the exclusionary rules.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1964363/', '1964363') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we find that an acceptable foundation was established for the admission of the dog-tracking evidence.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/1964363/', '1964363') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this information could be used to justify the stop.', 'general', 'Newsom v. State', 'https://www.courtlistener.com/opinion/2602022/', '2602022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''We held that this reading of the two Coleman categories was "too rigid"
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we held that even though "the theoretical seriousness of the crime [being investigated] is a significant factor" when applying the Coleman test, the seriousness of the crime "is not in itself determinative.', 'general', 'Newsom v. State', 'https://www.courtlistener.com/opinion/2602022/', '2602022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the stop was lawful under the Coleman test as we interpreted that test in State v.', 'general', 'Newsom v. State', 'https://www.courtlistener.com/opinion/2602022/', '2602022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, as we explain in the remainder of this opinion, we conclude that the investigative stop of Newsom inside the Walmart store can be justified based on Busey''s knowledge at the time of his broadcast and the additional information obtained by Sims and Bell when they responded to Busey''s call for assistance.', 'general', 'Newsom v. State', 'https://www.courtlistener.com/opinion/2602022/', '2602022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Why we conclude that this investigative stop was lawful
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying this analysis to the facts of New-som''s case, we conclude that the investigative stop was lawful.', 'general', 'Newsom v. State', 'https://www.courtlistener.com/opinion/2602022/', '2602022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that the investigative stop of Newsom inside the Wal-mart store was lawful under Coleman, as interpreted in .', 'general', 'Newsom v. State', 'https://www.courtlistener.com/opinion/2602022/', '2602022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Accordingly, we conclude that the trial evidence was legally sufficient to support the verdict.', 'general', 'Newsom v. State', 'https://www.courtlistener.com/opinion/2602022/', '2602022') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If, based on all the evidence, a reasonably-minded jury must necessarily entertain a reasonable doubt of the defendant’s guilt, due process requires that we reverse and order a judgment of acquittal.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/2433459/', '2433459') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court of appeals erred in its application of the Strickland standard, and we REVERSE the judgment of that court and AFFIRM the judgment of the trial court.', 'ineffective_assistance', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2384922/', '2384922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1992), in which we held that a trial counsel''s assistance was not ineffective when he failed to strike or challenge, in a trial for cocaine possession, an ex-narcotics officer who knew the defendant and stated that he could not be impartial.', 'ineffective_assistance', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2384922/', '2384922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that appellant has not met his burden of showing that his trial counsel''s assistance was ineffective.', 'ineffective_assistance', 'Jackson v. State', 'https://www.courtlistener.com/opinion/2384922/', '2384922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the trial court.', 'general', 'Gunashekar v. Grose', 'https://www.courtlistener.com/opinion/852309/', '852309') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court abused its discretion and that Relator has no adequate remedy by appeal;', 'general', 'Remington Arms Co., Inc. v. Caldwell', 'https://www.courtlistener.com/opinion/1717670/', '1717670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Craig waived any objections to these matters by failing to request a pretrial hearing on the alleged discovery abuse and by requesting a preferential trial setting.', 'general', 'Remington Arms Co., Inc. v. Caldwell', 'https://www.courtlistener.com/opinion/1717670/', '1717670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Craig waived any objections to these matters when he certified to the trial court that his pleadings were in order and that discovery was complete.', 'plea', 'Remington Arms Co., Inc. v. Caldwell', 'https://www.courtlistener.com/opinion/1717670/', '1717670') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree that the error would have had but slight effect, and on that basis we hold that the error was harmless.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1488373/', '1488373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this state of the record, we conclude that the trial court abused its discretion to admit Volet''s testimony of J.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1488373/', '1488373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the court of appeals.', 'general', 'Taylor v. State', 'https://www.courtlistener.com/opinion/1488373/', '1488373') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our careful review of the record we hold that the trial courts'' rulings are supported by the evidence.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial courts did not err in admitting appellant''s statements into evidence in his trials.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that no deception was practiced by law enforcement agents.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence supports the conviction.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We hold that this issue is spurious.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we hold that appellant''s argument based on references to the trial judge''s post-conviction actions is baseless.', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Relying on our previous discussion concerning the voluntariness of appellant''s statements, we hold that no deception occurred;', 'general', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having carefully considered each of appellant''s points on appeal, we affirm the judgments, convictions and sentences in all respects.', 'sentencing', 'Burk v. State', 'https://www.courtlistener.com/opinion/1376364/', '1376364') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 63       For the above reasons, we reverse the appellate court’s judgment vacating defendant’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we affirm in part and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an indictment for burglary under W.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1417888/', '1417888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Failing to discern any talismanic significance in such word, we conclude that this common-law pleading requirement did not survive adoption of the West Virginia Rules of Criminal Procedure.', 'plea', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1417888/', '1417888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that an appeal pursued by the State under W.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1417888/', '1417888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does not.', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1417888/', '1417888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the indictment in this case was sufficient under both our state and federal constitutions, as well as Rule 7(c)(1).', 'general', 'State v. Wallace', 'https://www.courtlistener.com/opinion/1417888/', '1417888') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the language used within subsection (g) by the legislature was meant solely as a carefully thought out prophylactic measure to ensure that the written reports submitted by law enforcement officials called for under the statute be kept confidential.', 'general', 'Pagel v. Franscell', 'https://www.courtlistener.com/opinion/2602424/', '2602424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Pagel v. Franscell', 'https://www.courtlistener.com/opinion/2602424/', '2602424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 22] Given those reasons set forth above, we reverse the order entered by the district court requiring DCI to provide a list of all people living within Campbell County, Wyoming who currently had a permit or license to carry a concealed weapon under Wyoming law to Newspaper and further remand this matter back to the district court for entry of an order consistent with this opinion.', 'general', 'Pagel v. Franscell', 'https://www.courtlistener.com/opinion/2602424/', '2602424') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in the light of decisions directly on point, we hold that the appellant was not denied a fair and impartial trial according to the standards set out in Taylor v.', 'general', 'Clark v. State', 'https://www.courtlistener.com/opinion/1869484/', '1869484') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the other acts evidence was not probative of the defendant''s intent or absence of accident and that the circuit court erroneously exercised its discretion in admitting the other acts evidence.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the prosecutor''s repeated references to the other acts evidence in the opening and closing statements, and the fact that the cautionary instruction was not limited to evidence of the defendant''s intent or absence of accident, we conclude that the cautionary instruction was insufficient to cure the prejudicial impact of the other acts evidence.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful reading of the record we conclude that the State has not proven that the error did not contribute to the conviction.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record and the prosecutor''s own view of the case, we conclude that there is a reasonable possibility that the other acts evidence contributed to the defendant''s convictions.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we conclude that the State has not met its burden of proving beyond a reasonable doubt that the error did not contribute to the verdict.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth, we reverse the decision of the court of appeals.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we reverse the judgments of conviction and remand the cause to the circuit court.', 'general', 'State v. Sullivan', 'https://www.courtlistener.com/opinion/1573061/', '1573061') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Collins did not make clear what he intended the stipulation to include, and did not object to references to the prior conviction until after two such references had already been made, we conclude that Collins waived his right to challenge the admission of this evidence on appeal.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '02, subdivisions 9(3), (4), the district court properly instructed the jury that the offense of harassment requires specific intent, and we conclude that it did not err in its jury instructions.', 'jury_instruction', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when Collins’s conduct is considered in light of the evidence as a whole, a hypothesis other than specific intent to tamper with a witness is not rational, and the evidence is therefore sufficient to sustain the jury’s verdict.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that for this provision to have meaning, Collins must be correct in interpreting the guidelines to state that for a sentence to be presumptively consecutive and carry a criminal history score of one, it must be imposed consecutively to the sentence for which the inmate was confined at the time the offense was committed, rather than to a sentence that has not yet begun.', 'sentencing', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the witness tampering took place after the first incident of harassment, we conclude that under the guidelines, Collins’s sentence for witness tampering should either be (1) concurrent with the harassment sentence and presumptively consecutive to the sentence for which he was confined, thereby using a criminal history score of one, or (2) permissibly consecutive to the harassment sentence, using a criminal history score of zero.', 'sentencing', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The five-month departure in this case is minor, and under the circumstances we conclude that the district court did not abuse its discretion.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the jury instructions as to harassment were proper, that Collins waived his right to remove evidence of his prior conviction from the jury, and that the record contains sufficient evidence to support the witness tampering conviction.', 'jury_instruction', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that for purposes of section 609.', 'general', 'State v. Collins', 'https://www.courtlistener.com/opinion/1709781/', '1709781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that an illegal search only violates the rights of those who have “a legitimate expectation of privacy in the invaded place.', 'general', 'Parks v. Commonwealth', 'https://www.courtlistener.com/opinion/1315235/', '1315235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Parks did not have any legitimate expectation of privacy in the premises at 408 North 5th Street and therefore had no standing to assert Fourth Amendment protection.', 'search_seizure', 'Parks v. Commonwealth', 'https://www.courtlistener.com/opinion/1315235/', '1315235') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we find that the question likely would have confused the issue before the jury.', 'general', 'Stults v. State', 'https://www.courtlistener.com/opinion/1991932/', '1991932') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we are unable to conclude that defense counsel’s performance fell below an objective standard without evidence in the record, we find that the appellant has failed to meet the first prong of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the tort of negligent hiring, training or supervising is a valid claim in Wisconsin.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that a cause of action for negligent hiring, training or supervision is a valid claim in Wisconsin.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that negligent hiring, training or supervision is a valid claim in Wisconsin.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this evidence is sufficient to support an award of punitive damages, assuming a causal connection between the employer''s negligence and the employee''s wrongful act.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court''s denial of Wal-Mart''s motion for directed *274 verdict was not clearly erroneous.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of the circuit court and remand for further proceedings only with respect to the elements of the tort as set forth in this opinion.', 'general', 'Miller v. Wal-Mart Stores, Inc.', 'https://www.courtlistener.com/opinion/1709777/', '1709777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the investigatory stop was valid, we review the other five issues.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/2163517/', '2163517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in denying defendant’s motion for separate trials.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/2163517/', '2163517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because defendant was present in court on the day that the trial date was scheduled and because defendant substantiated that he knowingly and voluntarily failed to appear for his trial in statements he later made to the court, we conclude that defendant knowingly and voluntarily failed to appear at his trial.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/2163517/', '2163517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With essentially the same evidence properly before the jury, we conclude that even if the initial testimony violated Evid.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/2163517/', '2163517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“We will affirm a conviction if, after considering the reasonable inferences and probative evidence supporting the verdict, we conclude that a reasonable trier of fact could find each element of the charged crime beyond a reasonable doubt.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/2163517/', '2163517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The State should have properly arraigned defendant on the habitual offender charge but because we find that it did not result in prejudice to defendant, that error was harmless.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/2163517/', '2163517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a jury could infer intent to deal from this evidence that defendant was in constructive possession of an amount of cocaine greater than that ordinarily carried by an individual user and that the cocaine was packaged for sale and sorted according to price and size.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/2163517/', '2163517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm his conviction today in a separate opinion.', 'general', 'Lampkins v. State', 'https://www.courtlistener.com/opinion/2163517/', '2163517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 55 Considering all pertinent factors, we conclude that SWA’s misconduct falls within the low to middle range of the reprehensibility scale.', 'general', 'Hudgins v. SOUTHWEST AIRLINES, CO.', 'https://www.courtlistener.com/opinion/2590347/', '2590347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'guideposts, we conclude that punitive damages should be reduced to $500,000 for each plaintiff, for a total punitive damages award of $1 million.', 'general', 'Hudgins v. SOUTHWEST AIRLINES, CO.', 'https://www.courtlistener.com/opinion/2590347/', '2590347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm in part, reverse in part, and remand to the trial court for entry of a judgment reflecting this reduction in the punitive damages award.', 'general', 'Hudgins v. SOUTHWEST AIRLINES, CO.', 'https://www.courtlistener.com/opinion/2590347/', '2590347') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the HGN field sobriety test meets the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that while an HGN test result is relevant to show that an individual is impaired, such a result, standing alone, is insufficient to prove the offense of DUI as defined by § 60-6,196 beyond a reasonable doubt.', 'general', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we hold that the trial court committed prejudicial error in receiving testimony over objection regarding the digital readout generated by the first breath test administered to Baue after his arrest.', 'general', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that because there was no statutory or regulatory requirement that the results of a chemical breath test be shown on a test record card and there was no evidence of willful noncooperation, the motorist had “submitted” to the breath test as required by law.', 'general', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 840, we held that the State had not met its burden of proof where the State’s witness testified that a blood test indicated alcohol content of .', 'general', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 273, 276 (1987), also a DUI case based upon test results generated by an Intoxilyzer Model 401 IAS, we held that “when there is a conflict in the evidence as to what [the] margin of error [of the testing device] actually is, we will affirm the decision of the trier of fact so long as there is sufficient evidence in the record, if believed, to sustain its finding of guilt.', 'general', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that where the State offered no evidence at trial to rebut a defense expert’s testimony that the defendant’s blood alcohol content could be as much as 52.', 'general', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Lammers’ observations at the time of the traffic stop, together with Baue’s performance on the HGN and preliminary breath tests, established probable cause for the arrest and that the trial court did not err in overruling Baue’s motion to suppress the arrest.', 'suppression', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the evidence adduced at the pretrial hearing, we conclude that the basic scientific principle upon which the HGN field sobriety test is based, i.', 'general', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the majority view is sound, and adopt the view that a police officer may testify to the results of HGN testing if it is shown that the officer has been adequately trained in the administration and assessment of the HGN test and has conducted the testing and assessment in accordance with that training.', 'general', 'State v. Baue', 'https://www.courtlistener.com/opinion/1305102/', '1305102') ON CONFLICT DO NOTHING;
