INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'United States v. Gilbert Isgar', 'https://www.courtlistener.com/opinion/2649047/', '2649047') ON CONFLICT DO NOTHING;
