INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For those reasons, we reverse the judgment of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that witness immunity bars Gilbert’s fraud and misrepresentation claims against Dr.', 'general', 'Gilbert v. Sperbeck', 'https://www.courtlistener.com/opinion/2640438/', '2640438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that quasi-judicial immunity barred a lawsuit against a court-appointed expert witness.', 'general', 'Gilbert v. Sperbeck', 'https://www.courtlistener.com/opinion/2640438/', '2640438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that a pro se litigant’s briefing was adequate to avoid waiver of his claims on appeal because, “[a]l-though [the appellant] often failed to cite legal authority to support his arguments, his briefing was such that we could discern his legal arguments and [the appellee] could reply to them.', 'general', 'Gilbert v. Sperbeck', 'https://www.courtlistener.com/opinion/2640438/', '2640438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that “[c]ase-law and policy considerations clearly support the granting of absolute quasi-judicial immunity to Dr.', 'general', 'Gilbert v. Sperbeck', 'https://www.courtlistener.com/opinion/2640438/', '2640438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that witness immunity bars Gilbert’s claims of fraud and misrepresentation against Dr.', 'general', 'Gilbert v. Sperbeck', 'https://www.courtlistener.com/opinion/2640438/', '2640438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Gilbert has waived her AS 18.', 'general', 'Gilbert v. Sperbeck', 'https://www.courtlistener.com/opinion/2640438/', '2640438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Gilbert has waived this claim as well.', 'general', 'Gilbert v. Sperbeck', 'https://www.courtlistener.com/opinion/2640438/', '2640438') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on appeal, the plain error doctrine applies to unobjected-to prosecu-torial misconduct.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 718 (1997), we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Griller, we held that the defendant bears the burden of persuasion on the third prong of the test.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that appellate courts should use the plain error doctrine when examining unobjected-to prosecutorial misconduct.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, although the Griller formulation applies, we conclude that, when prosecuto-*300rial misconduct reaches the level of plain or obvious error — conduct the prosecutor should know is improper — the prosecution should bear the burden of demonstrating that its misconduct did not prejudice the defendant’s substantial rights.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 741, we conclude that prosecu-torial misconduct is the type of trial error that justifies a shift in the burden for determining whether the plain error affected the defendant’s substantial rights.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*302Therefore, we conclude that the burden should be on the prosecution to show lack of prejudice before we will affirm a conviction.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand to the court of appeals to determine whether the prosecutor’s conduct constituted plain error affecting substantial rights in accordance with this opinion.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and remand to the court of appeals to determine whether the prosecutor’s conduct constituted plain error and to place the burden on the prosecution to show lack of prejudice.', 'general', 'State v. Ramey', 'https://www.courtlistener.com/opinion/1651356/', '1651356') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As in Voyles, we hold that Walker "intended that which he did.', 'general', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, considering Coulter and the language of 5.', 'general', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the jury had ample evidence to support that a "substantial reason for the killing" was to avoid detection and arrest for the offenses against Edwards.', 'general', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the full Batson analysis was never triggered as no showing of a pattern of purposeful discrimination was ever demonstrated by Walker.', 'general', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that a one hour limitation does not "unduly limit" counsel''s ability to fully argue his case.', 'general', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State, this Court held that the trial court should have permitted the tape recording to go to the jury:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Butler was entitled to have the jury instructed that she could be convicted under Miss.', 'general', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that there was no error in admitting the black dress into evidence at trial.', 'general', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that these facts could sufficiently demonstrate beyond a reasonable doubt to the jury the lack of any logical reason for Edwards'' killing by Walker, other than to eliminate her as a witness, prevent identification of Edwards and prevent scientific comparison of evidence linking Walker to the crime, thus enabling Walker to avoid detection and apprehension.', 'general', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We find that a plain reading shows no mention of appellate review of capital murder convictions and death sentences.', 'sentencing', 'Walker v. State', 'https://www.courtlistener.com/opinion/1659262/', '1659262') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon this constitutional standard, we hold that the admission of the prosecution’s rebuttal evidence in the instant case violated neither appellant’s sixth nor his fourteenth amendment rights.', 'general', 'State v. Nash', 'https://www.courtlistener.com/opinion/1421711/', '1421711') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Reviewing the record of this case, we find that appellant’s ineffectiveness claim fails regarding both phases of the trial.', 'ineffective_assistance', 'State v. Nash', 'https://www.courtlistener.com/opinion/1421711/', '1421711') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that imposition of the death penalty in this case is not disproportionate to the imposition of the death penalty in prior cases in this state.', 'general', 'State v. Nash', 'https://www.courtlistener.com/opinion/1421711/', '1421711') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions and sentences.', 'sentencing', 'State v. Nash', 'https://www.courtlistener.com/opinion/1421711/', '1421711') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Halliburton failed to preserve error on his challenge to two of the searches and on his double jeopardy claim.', 'general', 'State v. Halliburton', 'https://www.courtlistener.com/opinion/2219569/', '2219569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we conclude that the merger requirement of section 701.', 'general', 'State v. Halliburton', 'https://www.courtlistener.com/opinion/2219569/', '2219569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Halliburton did not have a legitimate expectation of privacy in his mother’s automobile.', 'general', 'State v. Halliburton', 'https://www.courtlistener.com/opinion/2219569/', '2219569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that possession of an offensive weapon is a lesser included offense of possession of an offensive weapon by a felon under this test.', 'general', 'State v. Halliburton', 'https://www.courtlistener.com/opinion/2219569/', '2219569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'State v. Halliburton', 'https://www.courtlistener.com/opinion/2219569/', '2219569') ON CONFLICT DO NOTHING;
