INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Harris, this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McGilberry, this Court held the trial court did not abuse its discretion by denying a motion for a 12 hour cooling off period.', 'general', 'Howell v. State', 'https://www.courtlistener.com/opinion/1096700/', '1096700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 252, this Court held that "[t]he legislature''s intent was to protect the citizenry from the evil of the lesser felony by imposing a greater penalty upon a homicide occurring during its commission.', 'general', 'Howell v. State', 'https://www.courtlistener.com/opinion/1096700/', '1096700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1982), this Court held that "under Mississippi statutes and decisions, when a person has been convicted and placed on probation, particularly here, where four (4) years of a five-year sentence were suspended, such sentence is a sentence under imprisonment.', 'sentencing', 'Howell v. State', 'https://www.courtlistener.com/opinion/1096700/', '1096700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001) this Court held that "[i]t has been held that one who is under a suspended sentence is `under sentence of imprisonment'' for purposes of finding the aggravating circumstance listed at Miss.', 'sentencing', 'Howell v. State', 'https://www.courtlistener.com/opinion/1096700/', '1096700') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that:
