INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 37   For the reasons stated, we affirm the judgment of the circuit court of De Kalb County.', 'general', 'People v. Horne', 'https://www.courtlistener.com/opinion/9453250/', '9453250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we held that comparing different offenses and their penalties was an accepted part of our proportionate penalties jurisprudence.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court agreed with the defendant that armed violence predicated on aggravated robbery was the more serious offense, and thus we held that the 15-year enhancement for armed robbery while in possession of a firearm was unenforceable.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that it would violate the due process clause to make violations of section 5.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that “common sense and sound logic” would dictate identical penalties for these offenses.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the identical offenses did not yield identical penalties, this court held that the penalties were unconstitutionally disproportionate and the greater penalty could not stand.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the penalty violated the proportionate penalties clause and thus did not address the due process issue.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that it would, noting that the State had not presented a single persuasive reason why comparing different offenses within the same statute was different than comparing offenses in different statutes.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to the former, we conclude that the purpose of subsections (a)(1) and (a)(2) is still to protect the safety of persons in their homes.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We conclude that it would not shock the conscience of the community to learn that the legislature has determined that an additional penalty ought to be imposed when murder is committed with a weapon that not only enhances the perpetrator’s ability to kill the intended victim, but also increases the risk that grievous harm or death will be inflicted upon bystanders.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the circuit court’s judgment and remand the cause for further proceedings.', 'general', 'People v. Sharpe', 'https://www.courtlistener.com/opinion/2074483/', '2074483') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the
