INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse both convictions and dismiss the charges.', 'dismissal', 'Ford v. City of Newport News', 'https://www.courtlistener.com/opinion/1067808/', '1067808') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not err in denying the motion to suppress.', 'suppression', 'Debroux v. Commonwealth', 'https://www.courtlistener.com/opinion/1285162/', '1285162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that although the Commonwealth did not make "an express concession of [the accused''s] misdemeanor convictions[,] .', 'general', 'Debroux v. Commonwealth', 'https://www.courtlistener.com/opinion/1285162/', '1285162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the Commonwealth, "`[h]aving conceded the matter before the trial judge,.', 'general', 'Debroux v. Commonwealth', 'https://www.courtlistener.com/opinion/1285162/', '1285162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a private security guard who issued a summons for trespassing was a state actor for purposes of punishing the forgery of the trespasser in executing the summons.', 'general', 'Debroux v. Commonwealth', 'https://www.courtlistener.com/opinion/1285162/', '1285162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no reversible error, we affirm.', 'general', 'Debroux v. Commonwealth', 'https://www.courtlistener.com/opinion/1285162/', '1285162') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing, we hold that defense counsel’s ineffective assistance provides an alternative basis for vacating Pacheco’s conviction of escape in the second degree and remanding this matter for a new trial.', 'ineffective_assistance', 'State v. Pacheco', 'https://www.courtlistener.com/opinion/2621096/', '2621096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the case law that HRS § 703-302(8) was intended to codify and the absence of any legislative history to the contrary, we hold that the exclusivity of the narrow choice of evils defense set forth in HRS § 703-302(3) is limited to prosecutions for escape from correctional or detention facilities but not to prosecutions for escape from custody that does not implicate an incarcerational setting.', 'general', 'State v. Pacheco', 'https://www.courtlistener.com/opinion/2621096/', '2621096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that “reprosecution of a defendant after a mistrial or reversal on appeal as a result of prosecutorial misconduct is barred where the prosecutorial misconduct is so egregious that, from an objective standpoint, it clearly denied a defendant his or her right to a fair trial.', 'mistrial', 'State v. Pacheco', 'https://www.courtlistener.com/opinion/2621096/', '2621096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we held that “[i]t is enough that specific and articulable conditions
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in which this court held that evidence of a witness’s prior conviction admitted for impeachment purposes is “limited to those convictions that are relevant to the issue of truth and veracity.', 'general', 'State v. Pacheco', 'https://www.courtlistener.com/opinion/2621096/', '2621096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that, when a criminal defendant testifies but does not “introduce testimony for the sole purpose of establishing his [or her] credibility,” his or her constitutional right to testify is violated if the prosecution impeaches the defendant’s credibility via evidence of his or her prior convictions.', 'general', 'State v. Pacheco', 'https://www.courtlistener.com/opinion/2621096/', '2621096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '110 (1974), which also arose in the context of an escape from prison, this court held that a “limited defense of necessity” is available to a defendant charged with escape.', 'general', 'State v. Pacheco', 'https://www.courtlistener.com/opinion/2621096/', '2621096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Pacheco’s conviction of and sentence for the offense of chinking in a public park,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm Pacheco’s conviction of and sentence for the offense of drinking in a public park.', 'sentencing', 'State v. Pacheco', 'https://www.courtlistener.com/opinion/2621096/', '2621096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Pacheco’s trial counsel rendered him ineffective assistance.', 'ineffective_assistance', 'State v. Pacheco', 'https://www.courtlistener.com/opinion/2621096/', '2621096') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s incarceration, and other factors, we conclude that the superior court did not err in finding that continued custody by T.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s incarceration would bring to these young children, we conclude that the superior court did not err in terminating T.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"[23] We concluded that "because A.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the particular facts of this case, we find that the totality of the circumstances supports the superior court''s decision to terminate T.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the superior court''s termination of parental rights for both parents.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we affirmed the termination of a biological father''s parental rights.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''s parental rights is squarely supported by the governing statute, we AFFIRM the termination of her rights.', 'general', 'T.F. v. State, Department of Health & Social Services', 'https://www.courtlistener.com/opinion/2621105/', '2621105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that state law preempts Ordinance 1248 as it applies to a particular subset of registered sex offenders: adjudicated delinquent children whom the state places and supervises in state-created foster care families.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we hold that the state''s interest in fulfilling its statutory obligations to place and supervise delinquent children in state-created foster care families in a uniform manner overrides any city interest in regulating land uses.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*155 We hold that Ordinance 1248, to the extent that it regulates the number of adjudicated delinquent children that may reside in a particular foster home, is a matter of statewide concern and is preempted.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we hold that Ordinance 1248, as it applies to adjudicated delinquent children in foster care homes, regulates a matter of statewide concern.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the totality of the circumstances, we hold that Ordinance 1248 is preempted because it regulates a matter of statewide concern: adjudicated delinquent children in state-created foster care families.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 953, 955 (1977), we held that the state had an overriding concern in the regulation of electricians because the electricians needed uniform access to markets throughout the state.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If we conclude that a matter is of statewide concern, we must consider whether the Constitution or state statutes provide specific authorization to the locality to legislate in this area.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state''s interest in fulfilling its statutory mandates to protect adjudicated delinquent children in need of state supervision and appropriate treatment is sufficiently dominant to override a home-rule city''s interest in regulating the number of registered juvenile sex offenders who may live in one foster care family.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that our statutes create such a need.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering this impact, we found that the local law constituted rent control and implicated the state statute.', 'general', 'City of Northglenn v. Ibarra', 'https://www.courtlistener.com/opinion/2621475/', '2621475') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a matter of law, we hold that the physical force to which the federal statute refers is not
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 23 For the foregoing reasons, we hold that (1) John’s act in throwing a soda can at Jennifer constitutes a “gesture” under § 13-2904(A)(3);', 'general', 'In Re John M.', 'https://www.courtlistener.com/opinion/2621749/', '2621749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 18 In summary, we conclude that the evidence did not sufficiently support the juvenile court’s finding that John yelled a racial slur at Jennifer.', 'general', 'In Re John M.', 'https://www.courtlistener.com/opinion/2621749/', '2621749') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we hold that the public notification provisions of HRS chapter 846E deprive Bani of a protected liberty interest without due process of law.', 'general', 'State v. Bani', 'https://www.courtlistener.com/opinion/2621764/', '2621764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly,’ we hold that the public notification provisions of HRS chapter 846E are void and unenforceable.', 'general', 'State v. Bani', 'https://www.courtlistener.com/opinion/2621764/', '2621764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we conclude that Bani has shown substantial injury to both his reputation and other “tangible interests.', 'general', 'State v. Bani', 'https://www.courtlistener.com/opinion/2621764/', '2621764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the due process clause of the Hawaii constitution bars application of the public notification provisions of HRS chapter 846E, we need not consider these arguments.', 'general', 'State v. Bani', 'https://www.courtlistener.com/opinion/2621764/', '2621764') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that Rule 45 was satisfied on April 2, 1999, when Cook pleaded no contest under Rule ll1(c).', 'plea', 'Cook v. State', 'https://www.courtlistener.com/opinion/2621811/', '2621811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that [the defendant''s] behavior was a continuing course of conduct from the middle of 1994 until his arrest in January 1997, that it constituted a single offense .', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2621811/', '2621811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the facts of Cook''s case, we conclude that Judge Savell could properly take steps to apprise the jury of the second clause of the protective order (the clause that prohibited Cook from all contact with K.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2621811/', '2621811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After studying the summation as a whole, we conclude that any potential impropriety in the prosecutor''s remarks was not the type of egregious and gravely prejudicial misconduct that would create a manifest necessity for declaring a mistrial without the defendant''s consent.', 'mistrial', 'Cook v. State', 'https://www.courtlistener.com/opinion/2621811/', '2621811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Cook has not shown plain error.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2621811/', '2621811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons explained here, we reject each of Cook''s claims and we affirm his conviction.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2621811/', '2621811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed in the preceding section, we affirm Judge Beistline''s decision that Judge Savell''s action neither proved bias nor created a reasonable appearance of bias.', 'general', 'Cook v. State', 'https://www.courtlistener.com/opinion/2621811/', '2621811') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court properly excluded the jurors’ statements based upon the court’s interpretation of § 27-606(2).', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1274141/', '1274141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was insufficient to prove Thomas’ earlier convictions for purposes of sentence enhancement.', 'sentencing', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1274141/', '1274141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Thomas has failed to show he was prejudiced by counsel’s failure to obtain and offer Evans’ testimony at trial.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1274141/', '1274141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Thomas has failed to prove that he suffered any prejudice from the performance of his attorney in failing to move to strike Crawford’s testimony.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1274141/', '1274141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a victim’s contributory
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having found no merit to Thomas’ assignments of error except with regard to the sufficiency of the evidence to support a finding that Thomas is a habitual criminal, we affirm the judgment of conviction.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1274141/', '1274141') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that we do not have to adopt a definitive standard to decide this ease.', 'general', 'State v. Streich', 'https://www.courtlistener.com/opinion/1972250/', '1972250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When we look at the entirety of the charge, however, we find that the court repeatedly instructed that the State’s burden was proof beyond a reasonable doubt.', 'general', 'State v. Streich', 'https://www.courtlistener.com/opinion/1972250/', '1972250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we disagree with the trial court’s rationale regarding the admissibility of DNA statistical evidence, we affirm.', 'general', 'State v. Streich', 'https://www.courtlistener.com/opinion/1972250/', '1972250') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Adams, we held that a juror should not, prior to trial, be required to identify which witnesses he will believe or what type of witnesses he will believe;', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Adams we held that a trial judge must impress upon the jury that it cannot consider any confession unless it finds beyond a reasonable doubt that the accused gave his statement freely and voluntarily under the totality of the circumstances, and that the accused received and understood his Miranda rights.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '409 (1930), we held that a jury charge was incorrect in that it "did not clearly and correctly instruct the jury that, if they had a reasonable doubt as to whether the [defendant] was guilty of murder or manslaughter, it was their duty to resolve that doubt in his favor, and find him guilty of the lesser offense.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" However, in Elmore we held that physical torture occurs when a person is subject to "serious physical abuse" and "aggravated battery.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not err in utilizing section 17-21-85.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient evidence on the record, both lay and expert, to support the trial judge''s determination that Davis was competent to waive his Miranda rights.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*343 We conclude that the trial judge''s instruction properly explained to the jury that it should determine the voluntariness of Davis''s confession under the totality of the circumstances, and that Davis''s receipt of his Miranda warnings and ability to understand those warnings were appropriate factors to consider in deciding whether the confession was freely given.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not err in charging the jury that a hand or fist could constitute a deadly weapon or object.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Davis''s contention that the trial judge should have instructed the jury that it must resolve any reasonable doubt regarding whether Davis was guilty of first or second degree criminal sexual conduct in favor of the lesser offense is without merit.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Davis''s waiver was intelligently made.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Though we hold that the court of appeals reached the right result in Stewart v.', 'general', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1762517/', '1762517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that there was no evidence that Glover was notified and, thus, that he had been denied his right to a speedy trial.', 'general', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1762517/', '1762517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment and disposition order and dismiss the case.', 'dismissal', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1762517/', '1762517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment and disposition order and dismiss this case.', 'dismissal', 'Stewart v. State', 'https://www.courtlistener.com/opinion/1762517/', '1762517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that pursuant to N.', 'general', 'State v. Gelman', 'https://www.courtlistener.com/opinion/2335613/', '2335613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Appellate Division, reinstate the trial court''s dismissal of the indictment, and remand for proceedings consistent with this opinion.', 'dismissal', 'State v. Gelman', 'https://www.courtlistener.com/opinion/2335613/', '2335613') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” When reviewed under an abuse of discretion standard, we find that the circuit court did not abuse its discretion in the instant case in declining to sentence the appellant under the Young Adult Offenders Act.', 'sentencing', 'State v. Booth', 'https://www.courtlistener.com/opinion/1320617/', '1320617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the parties’ arguments, the record designated for our consideration, and the pertinent authorities, we affirm the sentencing decision by the circuit court.', 'sentencing', 'State v. Booth', 'https://www.courtlistener.com/opinion/1320617/', '1320617') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the seizure of the envelope did not violate defendant''s fourth-amendment rights.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*94 On the record before us, we hold that the trial court''s decision to grant defense counsel''s request to limit death qualification with respect to those jurors whose answers to the questions printed on the jury questionnaire were acceptable, if it was error at all, was not error sufficiently "egregious as to `cut mortally into [defendant''s] substantive rights * * *.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that their admission into evidence by the trial court was not an abuse of discretion.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the excision of a portion of the tire did not deprive defendant of his constitutional right to a fair trial.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that "mitigating factors must be introduced, regardless of defendant''s position.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that "a criminal defendant is entitled to the assistance of reasonably competent counsel, and that if counsel''s performance has been so deficient as to create a reasonable probability that these deficiencies materially contributed to defendant''s conviction, the constitutional right will have been violated.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant did not manifest an actual or subjective expectation of privacy in the envelope, in that he exposed the mailing address and the words "To be opened in the event of my death.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the regulation on which defendant relies does not invalidate the examination of the contents of defendant''s envelope pursuant to a lawfully-issued search warrant.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not abuse its discretion in granting defendant''s motion to try the case in a county other than Ocean County.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the voir dire adequately disclosed any impermissible exposure to pretrial publicity.', 'general', 'State v. Marshall', 'https://www.courtlistener.com/opinion/2316658/', '2316658') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Ayers', 'https://www.courtlistener.com/opinion/2189902/', '2189902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does.', 'general', 'People v. Aguilar', 'https://www.courtlistener.com/opinion/2650810/', '2650810') ON CONFLICT DO NOTHING;
