INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the language of the Holder instruction is to be applied only at the trial level, and is not an appellate standard of review.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Holder, we held that when guilt is proven by circumstantial evidence, the jury must be instructed to accept any reasonable explanation pointing to the defendant''s innocence.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Randles, we held that the Holder standard does not apply on review.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In considering these factors, we conclude that the studies used by the experts possessed sufficient indicia of reliability to meet the I.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our standard of review for matters involving judicial discretion, we conclude that the district court did not abuse its discretion by admitting expert testimony based on these studies.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In reviewing the record we find that the jury''s verdict was not without a basis in fact or reason.', 'general', 'State v. Merwin', 'https://www.courtlistener.com/opinion/1166701/', '1166701') ON CONFLICT DO NOTHING;
