INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts of this case, we conclude that the traditional "but for" test is the appropriate test.', 'general', 'Eversley v. State', 'https://www.courtlistener.com/opinion/1902833/', '1902833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that there is competent, substantial evidence in the record to support the jury''s finding as to the causation element.', 'general', 'Eversley v. State', 'https://www.courtlistener.com/opinion/1902833/', '1902833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the trial court erred in reducing the felony child abuse conviction.', 'general', 'Eversley v. State', 'https://www.courtlistener.com/opinion/1902833/', '1902833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that under the statute in effect at the time of the crime in this case, section 782.', 'general', 'Eversley v. State', 'https://www.courtlistener.com/opinion/1902833/', '1902833') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that when a volunteer firefighter calls in a false alarm it is misconduct related to a public office or position, and defendant receives a "benefit" by the joy or gratification of participating in the response or even by giving the unit work to keep it in existence.', 'general', 'State v. Quezada', 'https://www.courtlistener.com/opinion/2197963/', '2197963') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we hold that the Confrontation Clause of the North Carolina Constitution does not require a showing or finding of necessity before hearsay testimony may properly be admitted under a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that where hearsay proffered by the prosecution comes within a firmly rooted exception to the hearsay rule, the Confrontation Clause of the North Carolina Constitution is not violated, even though no particularized showing is made as to the necessity for using such hearsay or as to its reliability or trustworthiness.', 'general', 'State v. Jackson', 'https://www.courtlistener.com/opinion/1254346/', '1254346') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons given above, we affirm.', 'general', 'Pickens v. Black', 'https://www.courtlistener.com/opinion/2385944/', '2385944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court’s instruction was proper.', 'general', 'State v. Sexton', 'https://www.courtlistener.com/opinion/1308448/', '1308448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to this issue, we conclude that discretionary review was improvidently allowed.', 'general', 'State v. Sexton', 'https://www.courtlistener.com/opinion/1308448/', '1308448') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that under our State Constitution, law enforcement officers cannot request consent to search a disabled vehicle on the shoulder of a roadway unless they have reasonable and articulable suspicion to believe that evidence of criminal wrongdoing will be discovered in the vehicle.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 66 (1975), we held that Article I, Paragraph 7 of the New Jersey Constitution, which protects people within this State from "unreasonable searches,"[8] requires the State to prove, as a prerequisite to a lawful consent search, that a person have knowledge of his right to refuse to give consent.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in Carty, supra, we held that law enforcement officers are required to have a reasonable and articulable suspicion of criminal activity before requesting consent to search a car stopped for a motor vehicle infraction.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under our deferential standard of appellate review, we conclude that there was sufficient credible evidence in the record to support the motion judge''s findings that the troopers engaged in an unconstitutional investigatory detention and search of the Lincoln Town Car and individual defendants.', 'general', 'State v. Elders', 'https://www.courtlistener.com/opinion/2353203/', '2353203') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is not, and we modify the decision of the circuit court.', 'general', 'Wooten v. State', 'https://www.courtlistener.com/opinion/2381265/', '2381265') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that neither Chapter 706 nor Chapter 353 of the Hawai`i Revised Statutes (HRS) prohibit the HPA from setting a prisoner''s minimum term at a period equal to his or her maximum sentence.', 'sentencing', 'Williamson v. Hawai''i Paroling Authority', 'https://www.courtlistener.com/opinion/2637982/', '2637982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the relevant statutes, we hold that their plain language does not prohibit the HPA from establishing a prisoner''s minimum term at a period equal to his or her maximum sentence and that nothing in the legislative history supports such a restriction.', 'sentencing', 'Williamson v. Hawai''i Paroling Authority', 'https://www.courtlistener.com/opinion/2637982/', '2637982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that a prisoner does not have a statutory right to have his or her minimum term set at a period shorter than the maximum sentence.', 'sentencing', 'Williamson v. Hawai''i Paroling Authority', 'https://www.courtlistener.com/opinion/2637982/', '2637982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the ICA''s opinion.', 'general', 'Williamson v. Hawai''i Paroling Authority', 'https://www.courtlistener.com/opinion/2637982/', '2637982') ON CONFLICT DO NOTHING;
