INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and sentence of the district court.', 'sentencing', 'State v. Bentley', 'https://www.courtlistener.com/opinion/1945345/', '1945345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment and sentences for first-degree kidnapping and first-degree murder.', 'sentencing', 'State v. Bentley', 'https://www.courtlistener.com/opinion/1945345/', '1945345') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed and remanded the cause to the circuit court for such further proceedings as may be appropriate not inconsistent with the law and our written opinion.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/1784555/', '1784555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed and remanded this cause following Moore''s first appeal.', 'general', 'Moore v. State', 'https://www.courtlistener.com/opinion/1784555/', '1784555') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[51] We held that the State had no duty to use due care in deciding whether to extend the commitment of a juvenile offender.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[62] In Neakok, we held that a duty of care is owed to victims who are foreseeable, though not necessarily specifically identifiable.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Alvord, where we held that parents who know that their child has a tendency towards violence can be held liable for harm committed by that child only if "the parent had reason to know with some specificity of a present opportunity and need to restrain the child to prevent some imminently foreseeable harm.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that there should not be such a duty, citing, among other reasons, the numerous "social and financial problems" with which the public schools are beset.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts of this case, we conclude that the trial court properly denied summary judgment on the issue of duty.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Our decision in Neakok addressed this question only in the context of whether a parole officer could be held liable for decisions regarding selection of parole conditions because we concluded that no reasonable jury could find the board at fault in that case.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that at least some of the State''s alleged acts of negligence are shielded by discretionary function immunity, we vacate the superior court''s order denying the State''s motion for summary judgment.', 'general', 'State, Department of Corrections v. Cowles', 'https://www.courtlistener.com/opinion/2638201/', '2638201') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In short, we hold that Respondent plainly is not afforded any protection under the Double Jeopardy Clause because disciplinary proceedings, whether classified as civil, quasi-criminal, or special, are not criminal in nature.', 'general', 'In Re Chastain', 'https://www.courtlistener.com/opinion/1355671/', '1355671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Respondent’s criminal conviction, which followed a disciplinary proceeding in which he was sanctioned, provides a separate basis for an additional sanction.', 'general', 'In Re Chastain', 'https://www.courtlistener.com/opinion/1355671/', '1355671') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that Respondent is not afforded any protection under the Double Jeopardy Clause because disciplinary proceedings, whether classified as civil, quasi-criminal, or special, are not criminal in nature.', 'general', 'In Re Chastain', 'https://www.courtlistener.com/opinion/1355671/', '1355671') ON CONFLICT DO NOTHING;
