INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶2        For the reasons that follow, we affirm the judgment of the appellate court.', 'general', 'People v. Radojcic', 'https://www.courtlistener.com/opinion/2647713/', '2647713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 65      For the reasons stated, we affirm the judgment of the appellate court.', 'general', 'People v. Radojcic', 'https://www.courtlistener.com/opinion/2647713/', '2647713') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the grant of PCR on this basis.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1288645/', '1288645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ''' We affirm in part, reverse in part.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1288645/', '1288645') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that assault is not a lesser included offense of malicious harassment.', 'general', 'State v. Rae', 'https://www.courtlistener.com/opinion/2638477/', '2638477') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that, under the pleading theory, disturbing the peace in this case is a lesser included offense of malicious harassment.', 'plea', 'State v. Rae', 'https://www.courtlistener.com/opinion/2638477/', '2638477') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we do not have an adequate record for review, and we affirm the district court’s denial of the motion for
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the denial of the motions to advance costs and for
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we hold that the defendant’s convictions for aggravated sexual assault and endangering the welfare of a child do not merge.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/1983036/', '1983036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '492, where the defendant assaulted a police officer arresting him for theft, we held that the aggravated assault and first degree robbery convictions should merge because the proofs were identical and the violent act that was used to elevate the theft to first degree robbery also formed the basis of the aggravated assault conviction.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/1983036/', '1983036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the inquiry should be guided by the general purposes of the Code.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/1983036/', '1983036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we disagree with the Appellate Division’s decision to merge the offenses, we reverse.', 'general', 'State v. Miller', 'https://www.courtlistener.com/opinion/1983036/', '1983036') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record below, we conclude that the sentence imposed was not the product of passion, prejudice or any other arbitrary factor.', 'sentencing', 'Commonwealth v. Champney', 'https://www.courtlistener.com/opinion/1518563/', '1518563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find no merit to the issues appellant raises, we affirm the judgment of sentence.', 'sentencing', 'Commonwealth v. Champney', 'https://www.courtlistener.com/opinion/1518563/', '1518563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '81d requires a showing that defendant''s arrest was lawful, we reverse.', 'general', 'People v. Ventura', 'https://www.courtlistener.com/opinion/1590341/', '1590341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '81d does not require a showing that defendant''s arrest was lawful, we reverse.', 'general', 'People v. Ventura', 'https://www.courtlistener.com/opinion/1590341/', '1590341') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pickle states that "we hold that where the two crimes are connected in a chain of events and occur as part of the res gestae, the crime of capital murder is sustained.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/1868893/', '1868893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court holds that the State had a duty to ensure that the jury was properly instructed on the elements of the underlying crime.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/1868893/', '1868893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Ballenger''s argument with regard to that instruction was not properly preserved for appeal.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/1868893/', '1868893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Ballenger was procedurally barred from raising the argument on appeal.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/1868893/', '1868893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Dufour, no instruction defining the underlying felony of robbery was given to the jury and this Court held that the evidence adduced at trial proved that the murder was committed during the course of a robbery.', 'general', 'Hunter v. State', 'https://www.courtlistener.com/opinion/1868893/', '1868893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Turning to the second point raised by this assignment of error, we find that the trial court did not err in excluding Jury instruction D-1.', 'jury_instruction', 'Hunter v. State', 'https://www.courtlistener.com/opinion/1868893/', '1868893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1317433/', '1317433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold the trial court did not abuse its discretion in denying Anderson''s severance motion and Anderson was not prejudiced by the admission into evidence of prior convictions because the trial court gave a sufficient limiting instruction to the jury.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1317433/', '1317433') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that defendant''s 18-year sentence for attempted murder while armed with a firearm must be vacated and the cause remanded to the trial court to impose a sentence within the Class X range, enhanced by the 15-year mandatory penalty set forth in 720 ILCS 5/8-4(c)(1)(B) (West 2000).', 'sentencing', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to the appellate court''s conclusion, we hold that the comparison of armed robbery while armed with a firearm and armed violence predicated on robbery is permissible.', 'general', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 492 (2005), this court held that pursuant to the cross-comparison test, the statutory 15-year mandatory enhancement for armed robbery while armed with a firearm violated the proportionate penalties clause of the Illinois Constitution and was "unenforceable.', 'general', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, here, we find that defendant has not forfeited his claim, as it involves a determination of whether applying Sharpe retroactively in order to resentence him under the enhanced penalty statute would be a due process violation.', 'sentencing', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under this reasoning, we find that the rule announced in Sharpe is of constitutional dimension (see People v.', 'general', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the "new rule" in Sharpe, announced while defendant''s case was pending on direct appeal, does not afford defendant the same "choice of sentencing law" applicable where a statutory change occurs during the prosecution of a defendant''s case.', 'sentencing', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While defendant contends that Sharpe''s restricted interpretation of the proportionate penalties clause was a sudden and radical departure from prior law, we find that despite the proportionality attacks to the 15/20/25-to-life sentence enhancements, the statutes at issue remained intact and defendant was therefore on notice that his conduct might fall within their scope.', 'sentencing', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, although at the time of defendant''s sentencing Walden and Morgan had rendered the 15-year enhanced penalties for his armed robbery and attempted murder convictions unconstitutional, we find that the overruling of those cases during the pendency of defendant''s appeal has made the nonenhanced sentences imposed by the trial court statutorily nonconforming and thus void.', 'sentencing', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 658), we find that the trial court in this case did not abuse its discretion in failing to compare the reduced sentence imposed on codefendant Warden, with the sentence defendant received following a jury trial.', 'sentencing', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm in part and reverse in part the judgment of the appellate court.', 'general', 'People v. Hauschild', 'https://www.courtlistener.com/opinion/2219925/', '2219925') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There, Division One of this court held a trial court must give “great weight” to an attorney’s “avowal of an ethical conflict requiring withdrawal” because “ ‘[attorneys are officers of the court, and when they address the judge solemnly upon a matter before the court, their declarations are virtually made under oath.', 'general', 'State v. Paris-Sheldon', 'https://www.courtlistener.com/opinion/2626992/', '2626992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'State v. Paris-Sheldon', 'https://www.courtlistener.com/opinion/2626992/', '2626992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 35 We affirm Paris-Sheldon’s convictions and sentences.', 'sentencing', 'State v. Paris-Sheldon', 'https://www.courtlistener.com/opinion/2626992/', '2626992') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that where an arrestee''s right to an independent blood test effectively has been denied by law enforcement''s failure to render reasonable assistance, suppression under Florida Rule of Criminal Procedure 3.', 'suppression', 'Unruh v. State', 'https://www.courtlistener.com/opinion/1142099/', '1142099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the caveat that courts must strive to maintain neutrality, detachment, and the appearance of same, we affirm.', 'general', 'Basolo v. Basolo', 'https://www.courtlistener.com/opinion/1152421/', '1152421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the amended decree in all respects.', 'general', 'Basolo v. Basolo', 'https://www.courtlistener.com/opinion/1152421/', '1152421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse and dismiss appellant''s conviction.', 'dismissal', 'Marttila v. City of Lynchburg', 'https://www.courtlistener.com/opinion/1065464/', '1065464') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding the existence of an objectively valid probationary purpose, we hold that a warrantless probationary search is unreasonable if it is conducted for a subjectively improper purpose.', 'general', 'State v. Propios', 'https://www.courtlistener.com/opinion/1159017/', '1159017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1379 (1984), this court held that a probationer, like a parolee, may be subjected to warrantless searches by her probation officer.', 'general', 'State v. Propios', 'https://www.courtlistener.com/opinion/1159017/', '1159017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although several of the circuit court’s FOF were clearly erroneous, we conclude that these errors were harmless because there is sufficient evidence in the record to support the court’s conclusion that the search exceeded the rehabilitative scope for warrantless searches allowed by statute.', 'general', 'State v. Propios', 'https://www.courtlistener.com/opinion/1159017/', '1159017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Propios', 'https://www.courtlistener.com/opinion/1159017/', '1159017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the circuit court’s order granting Propios’s motion to suppress the evidence.', 'suppression', 'State v. Propios', 'https://www.courtlistener.com/opinion/1159017/', '1159017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the order suppressing evidence obtained during the purported probationary search.', 'suppression', 'State v. Propios', 'https://www.courtlistener.com/opinion/1159017/', '1159017') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Legislature did not intend that knowledge that a firearm is loaded is an element of the offense.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the end sought to be achieved by MCL 750.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Whether approached with the guidance of federal courts and sister jurisdictions, the methodology of our own precedent, or the factor analysis distilled by LaFave and Scott, we conclude that knowledge that a firearm is loaded is not an element of MCL 750.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals and reinstate the defendant''s conviction.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of the Court of Appeals and reinstate the defendant''s conviction.', 'general', 'People v. Quinn', 'https://www.courtlistener.com/opinion/2191165/', '2191165') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not err in refusing the requested self-defense instruction.', 'general', 'Elmore v. State', 'https://www.courtlistener.com/opinion/1588100/', '1588100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Appellant’s testimony satisfied, as a matter of law, all of the elements of “carrying a gun to a discussion,” and we conclude that he was, therefore, not entitled to a self-defense instruction.', 'general', 'Elmore v. State', 'https://www.courtlistener.com/opinion/1588100/', '1588100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Elmore v. State', 'https://www.courtlistener.com/opinion/1588100/', '1588100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court’s judgment.', 'general', 'Elmore v. State', 'https://www.courtlistener.com/opinion/1588100/', '1588100') ON CONFLICT DO NOTHING;
