INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although no physical force was used, given the totality of the circumstances, we hold that a seizure took place within the meaning of article I, section 7 of the Hawaii Constitution.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the State has failed to meet its burden of proof that consent was voluntary and uncoerced, we hold that Quino’s seizure was unlawful.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the police conduct violated Quino’s right to be secure against unreasonable seizures guaranteed by article I, section 7 of the Hawaii Constitution.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that an unlawful seizure occurred prior to Quino’s flight, it is unnecessary to address the remaining issues.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*175Under the circumstances of this case, we conclude that Quino did not voluntarily and intelligently agree to be detained.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Quino’s conviction, order the evidence suppressed, and remand the case to circuit court for proceedings consistent with this opinion.', 'suppression', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed Tsukiyama’s conviction and held that no “stop” or “seizure” had taken place.', 'general', 'State v. Quino', 'https://www.courtlistener.com/opinion/1449875/', '1449875') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Maryland docket abstract satisfied the requirements of AS 12.', 'general', 'Gant v. State', 'https://www.courtlistener.com/opinion/1217489/', '1217489') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Judge Ripley did not abuse his discretion in rejecting the proposed mitigating factor.', 'general', 'Gant v. State', 'https://www.courtlistener.com/opinion/1217489/', '1217489') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Judge Ripley properly found Gant to be subject to sentencing as a third felony offender.', 'sentencing', 'Gant v. State', 'https://www.courtlistener.com/opinion/1217489/', '1217489') ON CONFLICT DO NOTHING;
