INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the statutory references in the oral charge at issue in the instant ease did not cure the omission of essential elements in the challenged counts of the charge.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/2611918/', '2611918') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although the assault against a police officer conviction must be reversed, because all of the essential elements of assault in the third degree were alleged in the oral charge and proven at trial, we hold that the appropriate remedy for Elliott’s post-conviction challenge to the defective charge is to remand the case for entry of judgment of conviction of assault in the third degree and for resentencing in accordance therewith.', 'sentencing', 'State v. Elliott', 'https://www.courtlistener.com/opinion/2611918/', '2611918') ON CONFLICT DO NOTHING;
