INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the reasons set forth below, we reverse the resisting arrest and assault against a police officer convictions.', 'general', 'State v. Elliott', 'https://www.courtlistener.com/opinion/2611918/', '2611918') ON CONFLICT DO NOTHING;
