INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse all but one of the convictions, sentences and fines, and affirm the petitioner''s conviction, sentence, and fine on one count of cruelty to animals.', 'sentencing', 'Amrein v. State', 'https://www.courtlistener.com/opinion/1445019/', '1445019') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the limit on discovery in this case was not manifestly unreasonable, and that the superior court did not abuse its discretion in declining to allow Prentzel to depose Olsen.', 'general', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it was certainly within the governor''s scope of authority to make statements on matters of public interest.', 'general', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State we held that the superior court improperly assessed litigation-ending sanctions against a party when it dismissed the case after that party failed to comply with a discovery order.', 'dismissal', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We conclude that the superior court did not abuse its discretion in refusing to grant Prentzel leave to file a fourth amended complaint.', 'general', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the dismissal of Prentzel''s negligence claims against the state defendants and his § 1983 claim against Troopers Scott and Gilmore, Captain Tanner, and Colonel Godfrey
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in all respects but one, reversing a portion of the attorney''s fees awarded against Prentzel.', 'general', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '° Last, we affirmed the dismissal of Prentzel''s claim based on alleged violations of the Alaska Constitution because the issue was inadequately briefed.', 'dismissal', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the three-factor Aspen analysis, we affirm the superior court''s summary judgment order adopting qualified immunity as a ground for dismissing Prentzel''s state-law tort claims against the troopers.', 'dismissal', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the superior court''s order granting summary judgment to the state defendants on all of Prentzel''s claims.', 'general', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although we vacate the fees awarded under Rule 82, we affirm the award under Rule 68 and remand for entry of a modified judgment reflecting only that award.', 'general', 'Prentzel v. State, Department of Public Safety', 'https://www.courtlistener.com/opinion/2625226/', '2625226') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 863 (1967), where this court held that a statute allowing the state hospital to retain a defendant in custody until he was determined “sane” was an unconstitutional delegation of judicial power to the executive branch.', 'general', 'Leathers v. Cotton', 'https://www.courtlistener.com/opinion/1760538/', '1760538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court erred in finding that DF&amp;', 'general', 'Leathers v. Cotton', 'https://www.courtlistener.com/opinion/1760538/', '1760538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the sentence of death is not excessive or disproportionate to sentences generally imposed by Virginia juries in crimes of a similar but less horrifying nature.', 'sentencing', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 623, 627 (1968), overruling an earlier decision to the contrary, we held that the trial court properly refused an instruction on second-degree murder where the evidence would support only findings of first-degree murder or not guilty.', 'general', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 400 (1981), we held that the relationships of time, place, and causal connection between a robbery and a murder need not necessarily be jury questions.', 'general', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the killing involved there was so closely related in time, place, and causal connection to the robbery as to make it a part of the same criminal enterprise as a matter of law.', 'general', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the vileness of Fitzgerald''s treatment of his victim exceeded that of any prior case we had reviewed until that time.', 'general', 'LeVasseur v. Commonwealth', 'https://www.courtlistener.com/opinion/1308460/', '1308460') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[10] We held that Blakely did not limit a judge''s authority to impose consecutive sentences with the exception of one potential issue that we did not decide in Edmond''s case: Is the fact finding called for by the Neal-Mutschler rule subject to the procedural requirements of Blakely? The Neal-Mutschler rule is a common-law sentencing rule announced by our supreme court;', 'sentencing', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all the above, we conclude that, when a sentencing judge applying the Neal-Mutschler rule assesses whether a composite term to serve exceeding the maximum term for the defendant''s single most serious crime is necessary to protect the public, the judge is not required to submit this issue to a jury.', 'sentencing', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Thompson properly applied the Neal-Mutschler rule to impose a composite term that exceeds the maximum 5-year term for Vandergriff''s individual crimes.', 'general', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From our review of the record, we conclude that Vandergriff''s sentence is not clearly mistaken.', 'sentencing', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the superior court imposed the term to protect the public.', 'general', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,[17] we affirmed the superior court''s sentence of 1500 days'' imprisonment with 1125 days suspended on eighteen counts of criminal contempt, which had a maximum penalty of 180 days imprisonment.', 'sentencing', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'State,[19] we affirmed the superior court''s imposition of a composite 7-year term, a term that exceeded the 5-year maximum term for each of the five counts of second-degree theft for which Montes had been convicted.', 'general', 'Vandergriff v. State', 'https://www.courtlistener.com/opinion/2625556/', '2625556') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Wigginton', 'https://www.courtlistener.com/opinion/2625587/', '2625587') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 544  we hold that the victim''s actions did not give rise to the defense of self-defense.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 991, and since Appellant did not offer any evidence showing that the witness had *827 been convicted of a felony, we hold that the district court did not abuse its discretion by sustaining the State''s objection.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, while the district court erred by failing to conduct a Jackson-Denno hearing, the error was harmless constitutional error under Campbell v.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we hold that the district court''s failure to hold a Jackson-Denno hearing was harmless beyond a reasonable doubt and that, under the facts of this case, the judge was not required to make an express finding of voluntariness.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Ramos v. State', 'https://www.courtlistener.com/opinion/1379767/', '1379767') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in the absence of contractual provision such an employee may be fired for good cause or for no cause, but not for "bad" cause.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that an employer may fire for good cause or for no cause.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this was error.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because parties who petition this court for review under Rule 23 may never have the opportunity to submit "additional briefs," we hold that "briefs" in Rule 21(c) include petitions for review by this court.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Valley View Community Hospital, supra, this court held that a personnel manual can become part of an employment contract and remanded the cause for a jury determination as to whether the particular manual given to Leikvold had become part of her employment *382 contract with Valley View.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', supra, in which this court held attorney''s fees are awardable on appeal under § 12-341.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the grant of summary judgment against Wagenseller on the count alleging tortious interference with a contractual relationship.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the grant of summary judgment on the count seeking recovery for breach of the implied covenant of good faith and fair dealing.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm in part and reverse in part.', 'general', 'Wagenseller v. Scottsdale Memorial Hospital', 'https://www.courtlistener.com/opinion/1206853/', '1206853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We agree with the defendant in part because we find that the Parole Board should only have excluded the three years defendant actually served in Pennsylvania from the time defendant needs to serve on his Delaware parole.', 'general', 'Semick v. Department of Corrections', 'https://www.courtlistener.com/opinion/1506550/', '1506550') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that such a construction of § 4352(g) would render that section sur-plusage in view of the fact that § 4352(d) already gives the Parole Board power to revoke a parole.', 'general', 'Semick v. Department of Corrections', 'https://www.courtlistener.com/opinion/1506550/', '1506550') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the Double Jeopardy claim, we find that defendant’s reliance upon
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 39 We conclude that the order authorizing the installation and monitoring of a GPS tracking device on Sveum''s vehicle was a valid search warrant under the Fourth Amendment.', 'search_seizure', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it does.', 'general', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 43 Affording Judge Callaway''s probable cause determination great deference, we conclude that he had a substantial basis for concluding that given all the facts and circumstances set forth in Ricksecker''s ample and detailed affidavit, there was a fair probability that installing and monitoring a GPS tracking device on Sveum''s vehicle would produce evidence of stalking.', 'probable_cause', 'State v. Sveum', 'https://www.courtlistener.com/opinion/2122517/', '2122517') ON CONFLICT DO NOTHING;
