INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[¶ 43] Similar to our conclusion in Pierson, we hold that the jury instructions given by the district court left doubt as to the circumstances under which Giles could be found to have committed the crime of indecent liberties with a child.', 'jury_instruction', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given these facts, combined with the other facts noted above, we conclude that the jury''s verdict was supported by the evidence.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '§ 6-2-304, and one was no more "specific" than the other, we concluded that Wyo.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, because the jury was not adequately instructed, we reverse and remand.', 'general', 'Giles v. State', 'https://www.courtlistener.com/opinion/2623536/', '2623536') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that, in appropriate cases, the Attorney General may use his authority granted by § 13-2315 to investigate not only particular crimes but also classes and types of crime so long as they are crimes that constitute racketeering as defined in the statute.', 'general', 'State Ex Rel. Goddard v. WESTERN UNION FINANCIAL SERVICES INC.', 'https://www.courtlistener.com/opinion/2623651/', '2623651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the breadth of the Attorney General’s request was not reasonable in light of the justification offered for it, we vacate the trial court’s enforcement of the request pursuant to § 13-2315.', 'general', 'State Ex Rel. Goddard v. WESTERN UNION FINANCIAL SERVICES INC.', 'https://www.courtlistener.com/opinion/2623651/', '2623651') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the affidavits are not sufficient to compel a reversal of the trial court’s ruling.', 'general', 'State v. Derr', 'https://www.courtlistener.com/opinion/1327907/', '1327907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the trial court did not abuse its discretion under the facts of this case.', 'general', 'State v. Derr', 'https://www.courtlistener.com/opinion/1327907/', '1327907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that defendant’s allegations of error as to instruction number 21 has no merit.', 'general', 'State v. Derr', 'https://www.courtlistener.com/opinion/1327907/', '1327907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the defendant may pursue this matter in a habeas corpus proceeding.', 'habeas', 'State v. Derr', 'https://www.courtlistener.com/opinion/1327907/', '1327907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the case at bar, we find that although the photographs had only slight relevance, they were not in any way “unfairly prejudicial.', 'general', 'State v. Derr', 'https://www.courtlistener.com/opinion/1327907/', '1327907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the probative value in showing the jury the condition, identity, and location of the body clearly outweighs any speculative prejudicial effect.', 'general', 'State v. Derr', 'https://www.courtlistener.com/opinion/1327907/', '1327907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we find that the instructions given by the trial court were not misleading or confusing to the jury such that there was a reasonable likelihood that the conviction was based on insufficient proof, and, when viewed in- the context of the charge as a whole, the instructions “‘correctly eonvey[ed] the concept of reasonable doubt to the jury.', 'general', 'State v. Derr', 'https://www.courtlistener.com/opinion/1327907/', '1327907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the trial court gave a detailed admonition at the beginning of the trial.', 'general', 'State v. Derr', 'https://www.courtlistener.com/opinion/1327907/', '1327907') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the superior court did not clearly err in its findings of fact
