INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the court did not abuse its discretion when it entered the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'fees to Rene, and we conclude that there was no abuse of discretion.', 'general', 'Limeres v. Limeres', 'https://www.courtlistener.com/opinion/2656735/', '2656735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Rene was
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm on all issues.', 'general', 'Limeres v. Limeres', 'https://www.courtlistener.com/opinion/2656735/', '2656735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that this inadequacy, when combined with the trial court''s erroneous refusal to dismiss prospective juror Pfeiffer for cause, which effectively resulted in defendant''s loss of a peremptory challenge, requires reversal of both the guilt and penalty proceedings.', 'dismissal', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a juror''s bias need not "be proven with unmistakable clarity.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Pfeiffer''s death penalty views during the voir dire, we conclude that the trial court erred in failing to excuse this prospective juror for *441 cause.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, apart from the deficit in peremptories arising from the court''s failure to excuse prospective juror Pfeiffer for cause, we conclude that the trial court did not erroneously deprive defendant of peremptory challenges.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we concluded that "[t]his standard does not require that a juror''s bias be proven with unmistakable clarity.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Although this question was an appropriate starting point, we find that the trial court''s repeated refusal to go beyond this initial inquiry raises serious questions about the impartiality of the jury ultimately impanelled.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on an independent review of the voir dire, we find that the trial court relied much too heavily on closedended questions, and on several occasions did not ask adequate follow-up questions to overcome the inadequacy of the initial inquiry.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the voir dire of juror Stevenson did uncover potential bias, we find that the limited scope of the trial court''s questioning of jurors Reade, Vasanski, and Malloy was more representative of the jury selection process as a whole.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse both the conviction and the sentence.', 'sentencing', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Instead, we reverse, as noted above, because the deprivation of the peremptory challenge in conjunction with the perfunctory nature of the voir dire combined to deny defendant fundamental procedural protections that guarantee a fair and impartial jury panel.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1540316/', '1540316') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, for the purposes of Ark.', 'general', 'Brewer v. Arkansas Department of Human Services', 'https://www.courtlistener.com/opinion/1382886/', '1382886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed only on the point raised individually by Cheryl Brewer, agreeing that the trial court erred in refusing to order reunification services.', 'general', 'Brewer v. Arkansas Department of Human Services', 'https://www.courtlistener.com/opinion/1382886/', '1382886') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'David S. Delagrange v. State of Indiana', 'https://www.courtlistener.com/opinion/2657667/', '2657667') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this rule and Rule 13 of the Tennessee Rules of Appellate Procedure, which brings this case to us with the presumption that the findings of fact of the Trial Court are correct, we conclude that the evidence does not preponderate against his finding.', 'general', 'Estate of Acuff v. O''Linger', 'https://www.courtlistener.com/opinion/1426378/', '1426378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons expressed below we conclude that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Defendant appeals and upon consideration of the record we reverse the chancellor.', 'general', 'Estate of Acuff v. O''Linger', 'https://www.courtlistener.com/opinion/1426378/', '1426378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that defendant has failed to show that he could not or did not receive a fair trial in the jurisdiction in which he was convicted, and we find no abuse of judicial discretion in the trial court’s ruling.', 'general', 'Smith v. Commonwealth', 'https://www.courtlistener.com/opinion/1213381/', '1213381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We cannot say that this finding of fact was not “unmistakably clear”, and we hold that the ruling grounded upon that finding did not contravene the principles announced in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that his admission was fully competent to show motive, intent, and premeditaton.', 'general', 'Smith v. Commonwealth', 'https://www.courtlistener.com/opinion/1213381/', '1213381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In consideration of the record as a whole and to the extent we can make a meaningful comparison with other capital cases decided in this Commonwealth, we hold that the penalty imposed in this case was not excessive or disproportionate.', 'general', 'Smith v. Commonwealth', 'https://www.courtlistener.com/opinion/1213381/', '1213381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 258 (1974), we held that, until we had formally adjudicated a constitutional challenge, the statute “stand[s], at least presumptively, valid and enforceable.', 'general', 'Smith v. Commonwealth', 'https://www.courtlistener.com/opinion/1213381/', '1213381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that defendant’s waiver was voluntary and that the trial court did not err in admitting his confession.', 'general', 'Smith v. Commonwealth', 'https://www.courtlistener.com/opinion/1213381/', '1213381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On the other hand, we find that, of the 236 persons actually executed in the last seven decades, 232 had been convicted of murder or rape or murder in connection with rape.', 'general', 'Smith v. Commonwealth', 'https://www.courtlistener.com/opinion/1213381/', '1213381') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Here, we find that the trial court acted properly in finding defendant''s claim frivolous.', 'general', 'State v. Borbon', 'https://www.courtlistener.com/opinion/1284145/', '1284145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the gravity of the offense, we find that appellant''s crimes were very serious.', 'general', 'State v. Borbon', 'https://www.courtlistener.com/opinion/1284145/', '1284145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that his actions were extremely dangerous and grave.', 'general', 'State v. Borbon', 'https://www.courtlistener.com/opinion/1284145/', '1284145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the trial court''s actions stating that "[t]his was a preliminary determination of reasonable grounds only.', 'general', 'State v. Borbon', 'https://www.courtlistener.com/opinion/1284145/', '1284145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the defendant''s RICO conviction, his five convictions for organized fraud and his grand theft convictions in counts 2, 9 and 10.', 'general', 'Cherry v. State', 'https://www.courtlistener.com/opinion/1829733/', '1829733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite the previous interpretation of the rule, this court held that in child abuse cases, statements identifying the perpetrator as a member of the child’s household are admissible under Rule 803(4) because they can be reasonably pertinent to medical diagnosis and treatment.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2431437/', '2431437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When viewing the evidence in the light most favorable to the State, we conclude that the Defendant has not carried his burden of illustrating that the evidence is insufficient to support the jury’s verdict.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2431437/', '2431437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the former type of statements are still admissible under the Rule 803(4) exception, even when the statements are made to someone other than a physician, provided that such statements are for the purpose of diagnosis and treatment of a medical or physical problem.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2431437/', '2431437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'holding, we conclude that the trial court erred in admitting the entire contents of the patient’s history.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2431437/', '2431437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Defendant’s constitutional right to a unanimous jury verdict was not violated by the court’s instructions.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2431437/', '2431437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that the trial court erroneously applied this factor.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2431437/', '2431437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the victim suffered personal injuries beyond those statutorily defined as “bodily injury.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/2431437/', '2431437') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State has not met its burden in showing that the rape was committed in order to gratify the Defendant’s desire for pleasure or excitement.', 'plea', 'State v. Williams', 'https://www.courtlistener.com/opinion/2431437/', '2431437') ON CONFLICT DO NOTHING;
