INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the questioned statute (Section 440.', 'general', 'Seaboard Coast Line RR Co. v. Smith', 'https://www.courtlistener.com/opinion/1853333/', '1853333') ON CONFLICT DO NOTHING;
