INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we hold that admission of this testimony was error.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we hold that the admission of the testimony was not sufficiently prejudicial to justify a new trial.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the state did not engage in prosecutorial misconduct.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We hold that sufficient evidence was introduced at trial to support Lopez-Rios''s conviction for first-degree premeditated murder.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was little, if any, real value to much of the gang expert testimony, especially when considered in light of its probative value versus potential prejudice;', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '''" We conclude that the state''s remarks merely paraphrased the substance of the witness''s testimony and "at worst, [were] unartful, not misconduct.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that Lopez-Rios''s ineffective assistance of counsel claim is meritless.', 'ineffective_assistance', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, by failing to object at trial, where the court has the opportunity to remedy this oversight, Lopez-Rios waived the right to raise the issue on appeal.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that there was little, if any, real value to much of the gang expert testimony, especially when considered in light of its probative value versus potential prejudice * * *.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In DeShay, we concluded that expert testimony relating to gang activity in general and gang affiliation was neither necessary nor helpful to the jury in evaluating the relevant evidence.', 'general', 'State v. Lopez-Rios', 'https://www.courtlistener.com/opinion/1304421/', '1304421') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the defendant did not make a prima facie showing of purposeful discrimination on the part of the State.', 'general', 'Morse v. State', 'https://www.courtlistener.com/opinion/2025738/', '2025738') ON CONFLICT DO NOTHING;
