INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that, "Our caselaw states that the defendant is barred from introducing a statement made by the defendant immediately after the crime, if it is self-serving, and if the State refuses to use any of it.', 'general', 'Simmons v. State', 'https://www.courtlistener.com/opinion/1652484/', '1652484') ON CONFLICT DO NOTHING;
