INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, as the trial court instructed, Minick was a "witness" as a matter of law, and the failure to instruct by using the statutory language "in the discharge of his duty" does not constitute reversible error under these circumstances.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2607055/', '2607055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying our pragmatic definition of a section 1503 "witness" in light of the protective purpose of the obstruction of justice statute, we find that Mann retained his status as a "witness" while the Talapoosa Pipeline case was pending on direct appeal.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2607055/', '2607055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand the trial court''s Conditional Order Permitting Leave to Proceed in Forma Pauperis and Order Continuing Appointment of Counsel and Requiring Periodic Payments.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2607055/', '2607055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the Conditional Order Permitting Leave to Proceed in Forma Pauperis and Order Continuing Appointment of Counsel and Requiring Periodic Payments.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/2607055/', '2607055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that those objects which an officer has probable cause to believe are possible evidence and which are in the officer’s plain view when the officer is lawfully present in the place where the objects are found are subject to a warrantless seizure without the necessity of exigent circumstances being present, and we hold that those objects may be introduced into evidence.', 'probable_cause', 'Jones v. State', 'https://www.courtlistener.com/opinion/2607102/', '2607102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that seizing evidence which was in plain view without having a warrant was permitted only when exigent circumstances existed.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2607102/', '2607102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'If this court holds that Jason Strieker had authority to consent to search appellant’s home, then consent to “look around” was not a consent to search and that the subsequent seizure was thus beyond the scope of consent given by Jason Strieker.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2607102/', '2607102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the police officer properly seized the jacket, gloves, and knife and that the trial court did not err when it admitted these items into evidence.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2607102/', '2607102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that AppeEant’s claims are without merit.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2607102/', '2607102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/2607102/', '2607102') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court erred by dismissing the wife’s contempt petition.', 'dismissal', 'Long v. McAllister-Long', 'https://www.courtlistener.com/opinion/1508498/', '1508498') ON CONFLICT DO NOTHING;
