INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the due process guarantees do not mandate a hearing for a juvenile accused of a violent felony before the prosecutor can file the charges in the district court.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1387240/', '1387240') ON CONFLICT DO NOTHING;
