INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the statutory scheme in Wyoming, under the federal and state constitutions, satisfies the requirements of equal protection of the law and provides both substantive and procedural due process.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1387240/', '1387240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that a classification of a minor who has attained the age of seventeen is constitutional, although that statutory provision could lead to all the disparate results claimed by Hansen.', 'general', 'Hansen v. State', 'https://www.courtlistener.com/opinion/1387240/', '1387240') ON CONFLICT DO NOTHING;
