INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a consequence, we hold that defendant’s first-degree murder convictions must be reversed.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1381821/', '1381821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the Court of Appeals as well as defendant’s convictions and sentences of life imprisonment without parole for the first-degree murders of Julie Marie Hansen and Maia C.', 'sentencing', 'State v. Jones', 'https://www.courtlistener.com/opinion/1381821/', '1381821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, we affirm the Court of Appeals holding that the trial court committed no error by admitting evidence of defendant’s prior acts or by omitting defendant’s proposed jury instruction.', 'jury_instruction', 'State v. Jones', 'https://www.courtlistener.com/opinion/1381821/', '1381821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we affirm the Court of Appeals’ finding of no error on the part of the trial court involving defendant’s multiple convictions for AWDWISI, AWDW or DWI.', 'general', 'State v. Jones', 'https://www.courtlistener.com/opinion/1381821/', '1381821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, as a result of the foregoing analysis, we affirm the Court of Appeals’ holding of no error as to defendant’s convictions and sentences for AWDW and DWI.', 'sentencing', 'State v. Jones', 'https://www.courtlistener.com/opinion/1381821/', '1381821') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we affirm the Court of Appeals’ holding of no error as to defendant’s convictions for AWDWISI, but we remand those three cases to the Court of Appeals for further remand to the trial court for sentencing.', 'sentencing', 'State v. Jones', 'https://www.courtlistener.com/opinion/1381821/', '1381821') ON CONFLICT DO NOTHING;
