INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the above rules in our review of the newspaper articles and the other publicity concerning this case, we conclude that the trial court did not err in concluding that defendant failed to meet his burden of proving that pretrial publicity prevented his receiving a fair and impartial trial.', 'general', 'State v. Jaynes', 'https://www.courtlistener.com/opinion/1282470/', '1282470') ON CONFLICT DO NOTHING;
