INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that the trial court did not err by denying the challenge for cause.', 'general', 'State v. Jaynes', 'https://www.courtlistener.com/opinion/1282470/', '1282470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the grounds for the motion to suppress were the same as to all three letters and had previously been ruled upon, we conclude that there was no remaining legal basis for the motion and no reason for another suppression hearing.', 'suppression', 'State v. Jaynes', 'https://www.courtlistener.com/opinion/1282470/', '1282470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court committed no error, constitutional or otherwise, by summarily denying defendant’s renewed motion to suppress during the trial of this case.', 'suppression', 'State v. Jaynes', 'https://www.courtlistener.com/opinion/1282470/', '1282470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we conclude that in this case, the answer to the prosecutor’s question merely informed the jury of defendant’s failure to support his theory of the case, and it was not error to admit it as evidence.', 'general', 'State v. Jaynes', 'https://www.courtlistener.com/opinion/1282470/', '1282470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the remark of the prosecutor did not violate any of these principles.', 'general', 'State v. Jaynes', 'https://www.courtlistener.com/opinion/1282470/', '1282470') ON CONFLICT DO NOTHING;
