INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding separate and distinct crimes with cumulative sentences to be a matter of legislative will, we affirm.', 'sentencing', 'Rouse v. State', 'https://www.courtlistener.com/opinion/2609323/', '2609323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Respondents owed Edwards a duty solely as a result of the unique facts of this case, i.', 'general', 'Edwards v. Lexington County Sheriff''s Department', 'https://www.courtlistener.com/opinion/1349463/', '1349463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude Respondents owed a common law duty to Edwards, we reverse and remand.', 'general', 'Edwards v. Lexington County Sheriff''s Department', 'https://www.courtlistener.com/opinion/1349463/', '1349463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s grant of summary judgment and remand to the trial court for further proceedings.', 'general', 'Edwards v. Lexington County Sheriff''s Department', 'https://www.courtlistener.com/opinion/1349463/', '1349463') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'cause the circuit court did not abuse its discretion, we affirm.', 'general', 'Bank of Hawaii v. Kunimoto', 'https://www.courtlistener.com/opinion/2614619/', '2614619') ON CONFLICT DO NOTHING;
