INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 48       For the foregoing reasons, we affirm in part and reverse in part the appellate court
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court erred when it denied Askerooth''s motion to suppress the methamphetamine discovered in the back seat of Schmidt''s squad car.', 'suppression', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Schmidt''s request for Askerooth''s consent to search the van exceeded the scope of the stop and his prolonged detention of Askerooth beyond the time necessary to effectuate the purpose of the stop violated Article I, Section 10 of the Minnesota Constitution.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we held that article I, section 10 required police to have an "objective individualized articulable suspicion of criminal wrongdoing before subjecting a driver to an investigative stop.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in the context of traffic stops, following Atwater''s proposition that the existence of probable cause of a minor traffic violation eliminates the need for balancing individual and governmental interests would threaten the integrity and coherence of our interpretation of article I, section 10 in Fort.', 'probable_cause', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that the lack of a driver''s license, by itself, is not a reasonable basis for confining a driver in a squad car''s locked back seat when the driver is stopped for a minor traffic offense.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Askerooth''s interest in being free from unreasonable seizure in these circumstances outweighed Schmidt''s need for convenience because obtaining Askerooth''s name, date of birth, and address did not require confinement in Schmidt''s squad car.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that it was unreasonable to place Askerooth in the squad car for convenience purposes and, though it would have been permissible to order Askerooth out of the van, the act of ordering Askerooth out of the van, standing alone, did not justify confining him in the squad car.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, based on the facts presented to us, a reasonable person in Schmidt''s position would not conclude that confinement of Askerooth in the squad car was necessary either to effectuate the original purposes of the stop or for officer safety.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Askerooth''s abandoning of the methamphetamine is the result of an illegal seizure, we conclude that the methamphetamine must be suppressed.', 'suppression', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Fort, we concluded that article I, section 10 requires an officer to have reasonable articulable suspicion to expand the scope of a routine traffic stop in order to investigate other matters unrelated to the reason for the stop and to request consent to search.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Poland I, we held that an act of premedition, such as the kidnapping of a victim that occurred in Yavapai County, was a sufficient essential act requisite to the commission of the offense of premeditated first degree murder to establish venue in Yavapai County.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Frankel, this court held, in the context of a civil case, that peremptory challenges are a substantial right of a party, and that forcing use of peremptory challenges to strike jurors who should have been stricken for cause denies the party this right.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Pritchard charges and the Jones/Smith charges were connected together in their commission and were part of a common scheme or plan.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Pritchard offenses were properly joined with the Jones/Smith offenses pursuant to Rule 13.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we conclude that the trial court properly denied appellant''s motions for judgment of acquittal of the robbery count and the felony murder theory.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that there was conduct constituting two elements of sexual abuse (Count XII) and sexual assault (Count XIII) that occurred in Maricopa County.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the trial court did not abuse its discretion by refusing to strike the two jurors for cause.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence supports the trial court''s finding that appellant had two prior felony convictions involving the use or threat of violence against another person.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon our review of the record, we conclude that appellant''s words and actions demonstrate the killing was heinous and depraved.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Contrary to appellant''s argument, we find that sufficient evidence supported the armed robbery conviction.', 'general', 'State v. Comer', 'https://www.courtlistener.com/opinion/2610829/', '2610829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that such a decision did not constitute an abuse of the trial court’s discretion.', 'general', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that it would be inappropriate for a court to consider the possibility .', 'general', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not abuse its discretion in denying Reed’s motion for a bill of particulars, even if the denial effectively foreclosed any possibility that Reed could assert the procuring agent defense.', 'general', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we hold that there was substantial evidence to support the jury’s conclusion that Reed failed to prove entrapment by a preponderance of the evidence.', 'general', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the failure of Reed’s trial counsel to obtain a “purity” analysis of the white powder did not “result in the withdrawal or substantial impairment of a potentially meritorious defense” and, therefore, did not constitute ineffective assistance of counsel.', 'ineffective_assistance', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'garding how each of these asserted errors amounted to ineffective assistance of counsel, we hold that those arguments are without merit.', 'ineffective_assistance', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Reed’s equal protection claim fails.', 'general', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Wardell’s testimony constituted substantial evidence supporting the jury’s verdict finding Reed guilty of promoting a dangerous drug in the first degree in violation of HRS § 712-1241(l)(b)(ii)(A).', 'general', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the extent that he assigns the trial court’s denial of that motion as a point of error on appeal, we hold that the denial was proper.', 'general', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This time we held that the defense was available, but our opinion made clear that the holding was limited to the peculiar facts of the ease before us.', 'general', 'State v. Reed', 'https://www.courtlistener.com/opinion/1450927/', '1450927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that such purely subjective impressions of a juror''s qualities had to be coupled with objective support to overcome a prima facie showing of discrimination.', 'general', 'State v. Trostle', 'https://www.courtlistener.com/opinion/2611397/', '2611397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 192 (1993), we held that the trial court has "no obligation to instruct the jury on theories withdrawn in the prosecutor''s discretion.', 'general', 'State v. Trostle', 'https://www.courtlistener.com/opinion/2611397/', '2611397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that its probative value outweighed any danger of unfair prejudice.', 'general', 'State v. Trostle', 'https://www.courtlistener.com/opinion/2611397/', '2611397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the impairment was significant for (G)(1) purposes and considered it a substantial factor in our independent reweighing, which resulted in a reduction of the defendant''s three death sentences.', 'sentencing', 'State v. Trostle', 'https://www.courtlistener.com/opinion/2611397/', '2611397') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, because the manslaughter instruction neglected to include an essential element of the crime for which Vigil was convicted, we hold that the trial court committed plain error.', 'general', 'Vigil v. State', 'https://www.courtlistener.com/opinion/2613204/', '2613204') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court committed plain error by giving a jury instruction which omitted the necessary element of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6, we find that Instruction No.', 'general', 'Vigil v. State', 'https://www.courtlistener.com/opinion/2613204/', '2613204') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand because the jury instruction misstated the essential elements of the crime of involuntary manslaughter as presently enacted by the Wyoming State Legislature.', 'jury_instruction', 'Vigil v. State', 'https://www.courtlistener.com/opinion/2613204/', '2613204') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Vigil v. State', 'https://www.courtlistener.com/opinion/2613204/', '2613204') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In that case, we held that the period of restraint of a few minutes was substantial where it involved holding a correctional facility nurse by the throat in a hostage situation.', 'general', 'State v. Ellis', 'https://www.courtlistener.com/opinion/1057268/', '1057268') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the nature and purpose of the stalking law, we conclude that the definitions of the crimes of unlawful restraint apply to the stalking law.', 'general', 'State v. Ellis', 'https://www.courtlistener.com/opinion/1057268/', '1057268') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the court should have entered a judgment of acquittal, we do not reach the other issues raised by defendant.', 'general', 'State v. Ellis', 'https://www.courtlistener.com/opinion/1057268/', '1057268') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse Defendant’s conviction on Count II and, after a review of the record, vacate the convictions on Counts I and III.', 'general', 'State v. Radcliffe', 'https://www.courtlistener.com/opinion/2613252/', '2613252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the judgment of conviction on Count II, vacate'' the judgment of conviction on Counts I and III, and remand those latter counts for further proceedings.', 'general', 'State v. Radcliffe', 'https://www.courtlistener.com/opinion/2613252/', '2613252') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court erred by declining to consider the relevance of the oral agreement alleged on the ground that a pet is property.', 'general', 'Houseman v. Dare', 'https://www.courtlistener.com/opinion/1465928/', '1465928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm those determinations, R.', 'general', 'Houseman v. Dare', 'https://www.courtlistener.com/opinion/1465928/', '1465928') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'That the superior court even mentioned possible prejudice to petitioner may be due to confusion based on its recollection of In re Hall and In re Bentley — cases in which we held that a petitioner collaterally attacking a guilty plea must show prejudice when alleging only a technical violation of the Rule 11 procedures.', 'plea', 'In Re Miller', 'https://www.courtlistener.com/opinion/1057287/', '1057287') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And in Bentley — in which the attack was similarly premised on technical deficiency under Rule 11(c) — we held that “[t]o constitute prejudice .', 'general', 'In Re Miller', 'https://www.courtlistener.com/opinion/1057287/', '1057287') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'In Re Miller', 'https://www.courtlistener.com/opinion/1057287/', '1057287') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Wis.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '867 (2002), which addressed a similar due process issue, we conclude that such a civil commitment does not require a separate finding that the individual''s mental disorder involves serious difficulty for such person to control his or her behavior.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Specifically, we conclude that evidence showing that the person''s mental disorder predisposes such individual to engage in acts of sexual violence, and evidence establishing a substantial probability that such person will again commit such acts, necessarily and implicitly includes proof that such person''s mental *190 disorder involves serious difficulty in controlling his or her behavior.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the required proof of lack of control, therefore, may be established by evidence of the individual''s mental disorder and requisite level of dangerousness, which together distinguish a dangerous sexual offender who has serious difficulty controlling his or her behavior from a dangerous but typical recidivist.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the same nexus between the mental disorder and the substantial probability that the person will engage in acts of sexual violence, necessarily and implicitly requires proof that the person''s mental disorder involves serious difficulty for such person in controlling his or her behavior.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we concluded that the definition and use of the term "mental disorder" is sufficiently tailored to satisfy the mental condition component required by substantive due process.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we concluded that treatment is a bona fide objective and goal of ch.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, *196 we concluded that the statute''s definition of dangerousnessthat a mental disorder makes it substantially probable that the person will engage in acts of sexual violenceis constitutionally sound.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we concluded that the nature and duration of commitment is consistent with the legislature''s purposes of protecting the community and providing treatment for persons suffering from mental disorders that predispose them to commit sexually violent acts.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that ch.', 'general', 'Wisconsin v. Laxton', 'https://www.courtlistener.com/opinion/1296496/', '1296496') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the conviction and sentence.', 'sentencing', 'Fortner v. State', 'https://www.courtlistener.com/opinion/2613456/', '2613456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'Fortner v. State', 'https://www.courtlistener.com/opinion/2613456/', '2613456') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the single isolated incident of threatening suicide is a reasonable ground for the denial of Griess’ application under Wyo.', 'general', 'Griess v. Office of the Attorney General, Division of Criminal Investigation', 'https://www.courtlistener.com/opinion/2613563/', '2613563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the twenty-day response period found in Wyo.', 'general', 'Griess v. Office of the Attorney General, Division of Criminal Investigation', 'https://www.courtlistener.com/opinion/2613563/', '2613563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the district court.', 'general', 'Griess v. Office of the Attorney General, Division of Criminal Investigation', 'https://www.courtlistener.com/opinion/2613563/', '2613563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the district court that affirmed the denial of the permit by the Division.', 'general', 'Griess v. Office of the Attorney General, Division of Criminal Investigation', 'https://www.courtlistener.com/opinion/2613563/', '2613563') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ordered that any reference to Counts XIV and XIX, Cause Number 7979 in Raymond Tison’s formal judgment be deleted and that any reference to Count XIV, Cause Number 7979 in the sentence for Count IX, Cause Number 8007 in Ricky Tison’s formal judgment be changed to Count XIX, Cause Number 7979.', 'sentencing', 'State v. Greenawalt', 'https://www.courtlistener.com/opinion/2613889/', '2613889') ON CONFLICT DO NOTHING;
