INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, assuming that the other requirements for punitive damages have been met, we hold that nominal damages may support a punitive damage award in an action for intentional trespass to land.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the exception to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that when nominal damages are awarded for an intentional trespass to land, punitive damages may, in the discretion of the jury, be awarded.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that the $100,000 punitive damages awarded by the jury is not excessive.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that when nominal damages are awarded for an intentional trespass to land, punitive damages may, in the discretion of the jury, be awarded.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that both the private landowner and society have much more than a nominal interest in excluding others from private land.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the nominal damages awarded to the Jacques support the jury''s punitive damage award, and because we conclude that our holding today applies to Steenberg, the issue is not moot.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is not.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the degree of reprehensibility of Steenberg''s conduct supports the imposition of a substantial punitive award.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for reinstatement of the punitive damage award.', 'general', 'Jacque v. Steenberg Homes, Inc.', 'https://www.courtlistener.com/opinion/1877286/', '1877286') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that because the trial court failed to conduct the requisite Sims analysis of the underlying conviction, there was insufficient evidence that the defendant had been previously convicted of a felony whose statutory elements included the use of violence against a person.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Evans’ testimony was corroborated by other witnesses and because of the overall strength of the prosecution’s case, we hold that the trial court’s error in failing to allow the defendant to cross-examine Evans for bias was harmless beyond a reasonable doubt.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was not.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As discussed above, we hold that the evidence is sufficient to support the jury’s findings that the (i)(5) and (i)(7) aggravating circumstances had been established beyond a reasonable doubt.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the strength of the two valid aggravating circumstances and the relatively weak mitigating evidence, we hold that the evidence supports the finding, beyond a reasonable doubt, that the valid aggravating circumstances outweigh the mitigating circumstances.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that it was not “just as plausible” to conclude that consensual sexual activity had occurred because the victim had struggled with the defendant and refused to have sex with him shortly before she was killed.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Reid, we held that evidence of multiple stab wounds to two victims supported a finding of torture and serious physical injury beyond that necessary to produce death:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2001), we held that whether the statutory elements of an offense involve the use of violence to the person must be determined by the trial court, not the jury.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this “standard imposed too high a threshold for the admissibility of evidence concerning third-party culpability” and that the Rules of Evidence were “adequate to determine whether such evidence is admissible.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, in Stevens, we held that the trial court erred in excluding evidence offered by the defendant to establish a third party defense.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the trial court abused its discretion when it denied the admission of Detective Jacobs’ testimony as extrinsic evidence of Fitch’s prior inconsistent statement.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we have decided that the trial court abused its discretion, we conclude that this error was more probably than not harmless.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, in light of the Defendant’s statements to police and the weight of the other evidence presented at trial, we conclude that the trial court’s error was harmless.', 'general', 'State v. Rice', 'https://www.courtlistener.com/opinion/1058090/', '1058090') ON CONFLICT DO NOTHING;
