INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the lack of a special instruction to limit or condition the jury''s consideration of the marijuana evidence did not prevent the real controversy from being fully tried.', 'general', 'State v. Schutte', 'https://www.courtlistener.com/opinion/2029896/', '2029896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that judicial interpretations of the statutorily required "high degree of negligence" under the former § 940.', 'general', 'State v. Schutte', 'https://www.courtlistener.com/opinion/2029896/', '2029896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, we conclude that the State presented sufficient evidence for jurors to reasonably conclude, beyond a reasonable doubt, that Schutte''s conduct prior to the collision was criminally negligent within the meaning of Wis.', 'general', 'State v. Schutte', 'https://www.courtlistener.com/opinion/2029896/', '2029896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the challenged curative instruction did not incorrectly state the law, and further, that it constituted neither a "judicial endorsement" of a guilty finding nor an impermissible directed verdict.', 'general', 'State v. Schutte', 'https://www.courtlistener.com/opinion/2029896/', '2029896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we conclude that Schutte is not entitled to a new trial on the basis of the challenged instruction.', 'general', 'State v. Schutte', 'https://www.courtlistener.com/opinion/2029896/', '2029896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reject Schutte''s claims of error and her requests for discretionary reversal, we affirm the appealed judgment and order.', 'general', 'State v. Schutte', 'https://www.courtlistener.com/opinion/2029896/', '2029896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed above, we affirm the appealed judgment and order.', 'general', 'State v. Schutte', 'https://www.courtlistener.com/opinion/2029896/', '2029896') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'He presents two issues: (1) Does a magistrate have jurisdiction to pass judgment upon a petition for writ of habeas corpus challenging the interim detention of a prisoner held under a probation officer’s warrant alleging probation violations? (2) If so, is detention unconstitutional where the petitioner has not been provided with an initial or prerevocation hearing within forty-eight hours of his arrest? We hold that under the circumstances of this case the petitioner was entitled to be relea...', 'habeas', 'Gawron v. Roberts', 'https://www.courtlistener.com/opinion/2604138/', '2604138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it was within this magistrate’s jurisdiction to receive and rule upon the petition.', 'general', 'Gawron v. Roberts', 'https://www.courtlistener.com/opinion/2604138/', '2604138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse the ruling of the district court and affirm the decision of the magistrate.', 'general', 'Gawron v. Roberts', 'https://www.courtlistener.com/opinion/2604138/', '2604138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore reverse that determination and we affirm the order of the magistrate releasing Gawron from custody.', 'general', 'Gawron v. Roberts', 'https://www.courtlistener.com/opinion/2604138/', '2604138') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not abuse its discretion by allowing this evidence for the limited purpose of proving motive and an essential element of the crime of which Porter was charged under Code § 18.', 'general', 'Porter v. Com.', 'https://www.courtlistener.com/opinion/1058473/', '1058473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the appropriate standard of review and viewing the evidence in the light most favorable to Porter, we hold that the circuit court did not err in refusing to offer the second-degree murder instruction.', 'general', 'Porter v. Com.', 'https://www.courtlistener.com/opinion/1058473/', '1058473') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the circuit court did not err in refusing Porter''s request for a second-degree murder instruction.', 'general', 'Porter v. Com.', 'https://www.courtlistener.com/opinion/1058473/', '1058473') ON CONFLICT DO NOTHING;
