INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 338, 340 (1998) ("We hold that, unless continued cetention can be justified by what occurs during the brief period of time it takes to determine whether the motorist has a valid license and whether the vehicle has been reported stolen, a motorist who is subjected to a
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the defendant in this case was detained without sufficient justification for purposes unrelated to the traffic stop, we conclude that the Superior Court erred in denying the defendant’s motion to suppress the evidence discovered as the product of the illegal detention.', 'suppression', 'Caldwell v. State', 'https://www.courtlistener.com/opinion/1535057/', '1535057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the circumstances of this case, we conclude that the duration and intrusiveness of the traffic stop were not reasonably related to the justification for the stop (i.', 'general', 'Caldwell v. State', 'https://www.courtlistener.com/opinion/1535057/', '1535057') ON CONFLICT DO NOTHING;
