INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the officer’s decision to handcuff and detain Caldwell was outside the scope of the traffic stop and was not supported by independent facts sufficient to warrant such an intrusion, we conclude that the Superior Court erred as a matter of law in denying Caldwell’s mo
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the officer''s conduct in this case exceeded the scope of the traffic stop and was not supported by facts uncovered during the stop, the defendant’s federal constitutional rights were violated.', 'general', 'Caldwell v. State', 'https://www.courtlistener.com/opinion/1535057/', '1535057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the communication of this information to the jurors violated the defendant’s constitutional right to a fair trial by an impartial jury.', 'general', 'Caldwell v. State', 'https://www.courtlistener.com/opinion/1535057/', '1535057') ON CONFLICT DO NOTHING;
