INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that Caldwell’s rights under the Fourth Amendment of the United States Constitution were violated.', 'search_seizure', 'Caldwell v. State', 'https://www.courtlistener.com/opinion/1535057/', '1535057') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court holds that an order permitting a party to purge herself of contempt by delivering the custody of a minor child on a certain day when the contempt committed consisted of failing to deliver the child on a previous date is not a modification but an enforcement of the judgment, and therefore no appeal lies from that portion of the order.', 'general', 'Herzog v. Reinhardt', 'https://www.courtlistener.com/opinion/1138048/', '1138048') ON CONFLICT DO NOTHING;
