INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reasons that we affirmed in Daniel, we affirm the competency
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Ultimately, we held that “the trial court did not err in allowing the State to introduce evidence of Sanders’s conviction for the murder of Frederick LaSalle.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1534099/', '1534099') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial on the charge of assault with intent to commit criminal sexual conduct in the first degree.', 'general', 'State v. Drafts', 'https://www.courtlistener.com/opinion/1237737/', '1237737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '9, 2006), wherein we held that an agent who stole money from a limited liability company was improperly indicted and convicted under the Embezzlement Statute because the business was neither an "incorporated company" nor a "private person.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/1802179/', '1802179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the State could not produce legally sufficient evidence on each element of the crime of embezzlement, we reversed and rendered the defendant''s conviction.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/1802179/', '1802179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Now, after careful review of the entire record, the briefs, and the arguments presented, we find the decision of the Court of Appeals was correct, and accordingly, we affirm the judgment of the Court of Appeals and reverse Coleman''s conviction.', 'general', 'Coleman v. State', 'https://www.courtlistener.com/opinion/1802179/', '1802179') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that juries must be instructed that the findings under Subsection (7) must be made beyond a reasonable doubt.', 'general', 'White v. State', 'https://www.courtlistener.com/opinion/1093300/', '1093300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present state of the record, we hold that the evidence was legally insufficient to enable a rational trier of fact to find beyond a reasonable doubt that Willie Lee White, Jr.', 'general', 'White v. State', 'https://www.courtlistener.com/opinion/1093300/', '1093300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '826 (1896), this Court held that a witness may only be impeached on a statement which embodies "a fact substantive in its nature and relevant to the issue made in the case.', 'general', 'White v. State', 'https://www.courtlistener.com/opinion/1093300/', '1093300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1985), this Court held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 944 (1976), we find that this portion of his argument addresses a factual question well within the province of the jury, and this Court will not set aside his conviction without concluding that the evidence taken in the most favorable light could not have supported a reasonable juror''s conclusion that the defendant was guilty beyond a reasonable doubt.', 'general', 'White v. State', 'https://www.courtlistener.com/opinion/1093300/', '1093300') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence in this case was legally adequate to establish that Larry Fisher committed the underlying felony of robbery of Melinda Gail Weathers.', 'general', 'Fisher v. State', 'https://www.courtlistener.com/opinion/1152625/', '1152625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that venue of this case should have been transferred to a county substantially outside the coverage area described above.', 'general', 'Fisher v. State', 'https://www.courtlistener.com/opinion/1152625/', '1152625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Fisher v. State', 'https://www.courtlistener.com/opinion/1152625/', '1152625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand with instructions that venue be so transferred and that thereafter there be a new trial on all issues.', 'general', 'Fisher v. State', 'https://www.courtlistener.com/opinion/1152625/', '1152625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although as explained above, we reverse, a number of matters raised by Fisher''s assignments of error appear reasonably likely to recur on retrial.', 'general', 'Fisher v. State', 'https://www.courtlistener.com/opinion/1152625/', '1152625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Johnson we affirmed the trial judge''s refusal to "gag" none other than The Meridian Star.', 'general', 'Fisher v. State', 'https://www.courtlistener.com/opinion/1152625/', '1152625') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the fact that juror Ragdale no longer resided in Madison County to be a valid race neutral reason to allow the trial court to grant the State''s peremptory strike of juror Ragdale.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that since Stevens does not allege that he lacked the ability to differentiate between right and wrong, the fact that he had been abusing alcohol, pain and anti-depressant medication should not have been presented to the jury to show that he lacked the ability to formulate specific intent on the guilt phase at trial.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence unquestionably supports the finding that Stevens intended to kill his victims, and he was aware of what he was doing at the time the crimes were committed.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Stewart, this Court held that "one of the reasons the trial court is granted such deference in a Batson issue is because the demeanor of the attorney making the challenge is often the best evidence on the issue of race neutrality.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the trial court properly did not allow the defense of diminished capacity to rise to met the M''Naughten test according to the experts at trial.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to legal sufficiency, this Court held in Pinkney v.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the weight of the evidence, this Court held in McFee v.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record in this appeal as well as the death penalty cases listed in the appendix, we conclude that Stevens''s death sentence was not imposed under the influence of passion, prejudice, or any other factor.', 'sentencing', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the lower court did not err in allowing the four counts of capital murders being tried together under a multi-count indictment.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it was the intent of the Mississippi Legislature under Miss.', 'general', 'Stevens v. State', 'https://www.courtlistener.com/opinion/1782560/', '1782560') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Robinson must still meet the requirements of the registration act.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2594276/', '2594276') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that because Manner’s felony conviction was the “only basis of the Board’s decision to revoke” his license, that decision must be reversed.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2594276/', '2594276') ON CONFLICT DO NOTHING;
