INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'for example, we held that challenges to the state’s approval of an oil drilling project were moot once the driller had abandoned the project and the period for approving the project had expired.', 'general', 'GILBERT M. v. State', 'https://www.courtlistener.com/opinion/2600505/', '2600505') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Gilbert does not have standing to appeal Jan’s rights, and because the claims which he has standing to appeal are rendered moot by his lengthy incarceration, we affirm the judgment of the superior court.', 'general', 'GILBERT M. v. State', 'https://www.courtlistener.com/opinion/2600505/', '2600505') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly we AFFIRM the judgment of the superior court.', 'general', 'GILBERT M. v. State', 'https://www.courtlistener.com/opinion/2600505/', '2600505') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because we hold that the commencement of Hoey’s trial was untimely,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, for the reasons stated below, we hold that the trial court committed reversible error both when it allowed Hoey’s confession into evidence and when it refused to instruct the jury as to the applicable law regarding merger of offenses.', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because motions for supervised release and/or bail reduction in no way delay the commencement of criminal trials, we hold that time periods attributable to such motions are not excludable pursuant to HRPP 48(c).', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in excluding from its HRPP 48(b) calculation the thirty-six day period that elapsed between the filing of Hoey’s motion for supervised release and/or bail reduction and its disposition.', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the retreat and seminar did not, and could not, cause an actual delay in the commencement of Hoey’s trial, we hold that the four day period in question should not have been excluded.', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'in any way delayed the commencement of Hoey’s trial, and we hold that the trial court erred in excluding the eight days of defense counsel’s involvement in it.', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that (1) when a suspect makes an ambiguous or equivocal request for counsel during custodial interrogation, the police must either cease all questioning or seek non-substantive clarification of the suspect’s request, and (2) if, upon clarification, the defendant unambiguously and unequivocally invokes the right to counsel, all substantive questioning must cease until counsel is present.', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Conversely, we hold that if, upon clarification, the defendant voluntarily, knowingly, and intelligently waives the presence of counsel, substantive questioning may continue.', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that the prosecution failed to meet its burden of proving that Hoey voluntarily, knowingly, and intelligently waived his right to counsel at his interrogation, as guaranteed by article I, section 10 of the Hawai''i Constitution.', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we hold that the trial court erred in admitting Hoey’s redacted confession into evidence.', 'general', 'State v. Hoey', 'https://www.courtlistener.com/opinion/1450956/', '1450956') ON CONFLICT DO NOTHING;
