INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm the judgment of the Court of Appeals in the instant case.', 'general', 'People v. Harris', 'https://www.courtlistener.com/opinion/2710721/', '2710721') ON CONFLICT DO NOTHING;
