INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the circuit court’s holding and vacate the finding made by DSS.', 'general', 'Anthony Moore v. Martin D. Brown, Commissioner, Virginia Department of Social Services', 'https://www.courtlistener.com/opinion/2675016/', '2675016') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that MCL 768.', 'general', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that our restriction of consecutive sentencing authority to the court last in time to impose sentence strikes the appropriate balance between the deterrence sought by the Legislature and the defendant’s right to be accorded due consideration of the effect of a cumulative sentence upon his period of incarceration.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this jurisdiction’s clear preference for concurrent sentencing, we find that a defendant facing the specter of a cumula*230tive term of imprisonment is at a minimum entitled to due consideration of the relationship between the proposed consecutive sentence and any other period of incarceration the defendant may be subject to.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon examination of the underscored language in Rondon, we find that our order could reasonably be construed to sanction consecutive sentencing by the first-in-time sentencing court.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At 424 Mich 864, we reversed and remanded to the trial court for resentencing, stating in relevant part:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals finding that the first-in-time sentencing court lacked discretionary consecutive sentencing authority.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16 Accordingly, while we affirm in part the decision of the Court of Appeals holding the first-in-time sentencing court lacked *232discretionary consecutive sentencing authority, we vacate defendant’s sentences for both felony convictions and remand to the trial court for resentencing in accordance with this opinion.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') We therefore hold that the prerogative of consecutive sentencing is accorded only to the court last in time to impose sentence.', 'sentencing', 'People v. Chambers', 'https://www.courtlistener.com/opinion/2031325/', '2031325') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '(2d) 63 (1982), we held that prior inconsistent statements may be admitted, not only as impeachment evidence, but as substantive evidence as well.', 'general', 'State v. Mathis', 'https://www.courtlistener.com/opinion/1237870/', '1237870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Mathis', 'https://www.courtlistener.com/opinion/1237870/', '1237870') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we held that the trial court had properly committed the defendant to a reformatory, despite the literal language of the statute.', 'general', 'State v. Levine', 'https://www.courtlistener.com/opinion/2188509/', '2188509') ON CONFLICT DO NOTHING;
