INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a defendant has a right on timely request to change the plea, but that a court has no duty to do it on the court’s own motion.', 'plea', 'Mendez v. State', 'https://www.courtlistener.com/opinion/1449351/', '1449351') ON CONFLICT DO NOTHING;
