INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held, in conformity with our prior case law, that once a statutory ground for termination has been established, there is no constitutional requirement that the trial court make an additional finding of substantial harm.', 'general', 'In Re Audrey S.', 'https://www.courtlistener.com/opinion/1509090/', '1509090') ON CONFLICT DO NOTHING;
