INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed infra in section III, we hold that indecent exposure, in violation of HRS § 707-734, does not constitute an offense subject to the sex registration and public notification requirements of HRS ch.', 'general', 'State v. Chun', 'https://www.courtlistener.com/opinion/2598440/', '2598440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In sum, and to reiterate, we hold that indecent exposure, in violation of HRS § 707-734, see supra note 2, does not constitute an offense that entails "criminal sexual conduct" and, consequently, that persons convicted of indecent exposure are not "sex offenders" for purposes of HRS ch.', 'general', 'State v. Chun', 'https://www.courtlistener.com/opinion/2598440/', '2598440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3d 1255 (2002), this court held, inter alia, that the registration components of HRS ch.', 'general', 'State v. Chun', 'https://www.courtlistener.com/opinion/2598440/', '2598440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '846E is devoid of any suggestion that the legislature sought to exercise its discretion to require registration for "[o]ffenses that do not involve physical contact, such as exhibitionism," we conclude that the legislature did not intend to include indecent exposure, in violation of HRS § 707-734, among the offenses requiring registration pursuant to HRS ch.', 'general', 'State v. Chun', 'https://www.courtlistener.com/opinion/2598440/', '2598440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nor do we hold that public safety officials in quarters where the reasonable expectation of Fourth Amendment privacy is diminished, such as airports and schools, cannot conduct protective searches on the basis of information insufficient to justify searches elsewhere.', 'search_seizure', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the police may act on an anonymous tip of reckless driving, but only under very narrow circumstances.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, based on the totality of the circumstances, we hold that the anonymous tip was sufficiently reliable to justify an investigatory stop.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, when examining the totality of circumstances in this case, we hold that Officer Sagun had a reasonable suspicion, based on specific and articulable facts, that Prendergast was engaged in criminal activity .', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that an investigative stop can be justified based on an objectively reasonable suspicion of any offense, provided that the offense for which reasonable suspicion exists is related to the offense articulated by the officer involved.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the circuit court should have suppressed this evidence.', 'suppression', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 580 (1974), in which this court held that a tip from a known informant was insufficient to justify a stop and frisk.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that "[w]ithout an adequate anchor, as to time and place, the reliability of this information becomes greatly attenuated.', 'general', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the following, we affirm the district court''s ruling on the motion to suppress as well as the district court''s judgment of conviction and sentence.', 'suppression', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we affirm the district court''s denial of Prendergast''s motion to suppress as well as the district court''s judgment of conviction and sentence.', 'suppression', 'State v. Prendergast', 'https://www.courtlistener.com/opinion/2629186/', '2629186') ON CONFLICT DO NOTHING;
