INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment of the district court on different grounds, holding that there was no taking with regard to the dedication of the street and that the appellant failed to exhaust administrative remedies with respect to its challenge to the amount of the impact fees.', 'general', 'KMST, LLC. v. County of Ada', 'https://www.courtlistener.com/opinion/2598596/', '2598596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment dismissing KMST’s claim against the ACHD, but for reasons different than those of the district court.', 'dismissal', 'KMST, LLC. v. County of Ada', 'https://www.courtlistener.com/opinion/2598596/', '2598596') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that: (1) pursuant to the post-conviction liberal construction rule adopted by this court in State v.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Sprattling failed to prove by a preponderance of the evidence that his waiver was involuntary, we hold that the district court did not err in this regard.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Inasmuch as Sprattling fails to provide a clear showing of substantial prejudice or that the charge could not be reasonably interpreted to assert a criminal offense, this court holds that the charge was sufficient.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, this court holds that Sprattling validly waived his right to a trial by jury.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, this court holds that Sprattling''s conviction is affirmed.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Friedman, this court held that an analysis into whether a jury trial waiver was valid must be made in light of the totality of the circumstances.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In no case has this court held, as the majority would hold here, that, although the accusationas the oral charge herecannot be reasonably construed to charge an offense, a conviction obtained thereon must nonetheless stand unless the defendant can establish that he or she suffered actual "prejudice.', 'general', 'State v. Sprattling', 'https://www.courtlistener.com/opinion/2598706/', '2598706') ON CONFLICT DO NOTHING;
