INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the evidence in this case amply supports the jury’s finding that the defendant took a substantial step toward the commission of child rape in his first attack on B.', 'general', 'State v. Elkins', 'https://www.courtlistener.com/opinion/1060321/', '1060321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we affirm the Court of Criminal Appeals and hold that the evidence was sufficient to support the defendant’s convictions for child rape and attempted child rape.', 'general', 'State v. Elkins', 'https://www.courtlistener.com/opinion/1060321/', '1060321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the defendant’s conviction for child rape.', 'general', 'State v. Elkins', 'https://www.courtlistener.com/opinion/1060321/', '1060321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction.', 'general', 'State v. Elkins', 'https://www.courtlistener.com/opinion/1060321/', '1060321') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the conduct at issue violated the Fourth Amendment of the United States Constitution, we do not consider Divello''s Indiana Constitution claims.', 'search_seizure', 'Divello v. State', 'https://www.courtlistener.com/opinion/2039018/', '2039018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'Divello v. State', 'https://www.courtlistener.com/opinion/2039018/', '2039018') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that Taylor is not entitled to UIM coverage under her policies with American Family.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[11] In Dowhower, we held that a reducing clause in an UIM policy is valid so long as "the policy clearly sets forth that the insured is purchasing a fixed level of UIM recovery that will be arrived at by combining payments made from all sources.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the insureds failed to establish that § 632.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we conclude that the definition of underinsured vehicle in *144 American Family''s policies is unambiguous.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the language in each of American Family''s policies at issue satisfies the requirements of Dowhower.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that Smith was not entitled to UIM coverage.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the vehicle driven by the other driver was not an underinsured vehicle as defined by Smith''s UIM policy because the $50,000 limit of the other driver''s liability policy was equal to, not less than, the $50,000 limit of Smith''s UIM policy.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the vehicle driven by the other driver was not an underinsured vehicle, we concluded that Smith was not entitled to UIM coverage.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'When we read the whole policy carefully, as noted on the first and third pages, we find that the policy clearly sets forth that Taylor purchased a fixed level of UIM recovery that is arrived at by combining payments from all sources, including payments from Hermanson''s liability coverage.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm and hold that Taylor is not entitled to UIM coverage under her policies with American Family because the vehicle driven by Hermanson was not an underinsured vehicle as defined by American Family''s policies.', 'general', 'Taylor v. Greatway Insurance', 'https://www.courtlistener.com/opinion/1581378/', '1581378') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is ordered that the trial court allow counsel for the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the cocaine found in the pill bottle in Mr.', 'general', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a unanimous opinion authored by Justice Levin, this Court held that a search without a warrant of persons whom the police had probable cause to arrest was proper, even though the persons searched had not been formally arrested.', 'probable_cause', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*111With due deference to the trial court’s findings, we conclude that, upon feeling the pill bottle, under a totality of the circumstances, the officer had probable cause to believe that the pill bottle contained contraband.', 'probable_cause', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We conclude that [the officer] possessed probable cause to believe that the pill bottle contained crack cocaine.', 'probable_cause', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', the defendant’s furtive behavior, his refusal to remove his hands from his sweatpants, the officer’s recognition of defendant, and his knowledge of defendant’s past involvement in drug crimes, that we find that removal of this particular pill bottle was authorized.', 'general', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we reverse that Court’s holding that cocaine found in a pill bottle on the defendant’s person during a patdown search was inadmissible.', 'general', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we reverse the Court of Appeals ruling that the cocaine found in the defendant’s possession was unlawfully seized.', 'general', 'People v. Champion', 'https://www.courtlistener.com/opinion/2032324/', '2032324') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'by extension, we hold that a trial court’s acquiescence in the making of a factual finding expressly requested by a defendant in a criminal case cannot thereafter form the basis of alleged error in the making of the same finding.', 'general', 'State v. Batson', 'https://www.courtlistener.com/opinion/1399274/', '1399274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we hold that it is sufficient, as in the present case, that one offense allegedly committed in two different ways be charged
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is.', 'general', 'State v. Batson', 'https://www.courtlistener.com/opinion/1399274/', '1399274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that there is substantial evidence in the record before us in this case to support the trial court’s conclusion that Batson knowingly caused Amos’s death.', 'general', 'State v. Batson', 'https://www.courtlistener.com/opinion/1399274/', '1399274') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'aggravated kidnapping was “incidental” to the attempted rape, we hold that the aggravated
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After reviewing the record, we conclude that the evidence was sufficient to support
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'used by the trial court, we conclude that only part (a) is relevant to the instant issue and confine our
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we concluded that under the facts in this case, dual convictions for attempted rape and
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the facts of this case in light of the decision in Barney, we find that Defendant’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the test from Barney, we find that four factors support a single conviction in this
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the test delineated in Dixon, we find that the restraint used by Defendant to commit
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the State substantially complied with Tenn.', 'general', 'State v. Taylor', 'https://www.courtlistener.com/opinion/1077323/', '1077323') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding, we reverse and dismiss Defendant’s conviction for
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that plaintiffs have standing, that this case is ripe for decision, that the trial court did not make an improper finding of fact, and that the Position Statement is inconsistent with N.', 'general', 'NC Dept. of Correction v. NC MEDICAL BD.', 'https://www.courtlistener.com/opinion/1325861/', '1325861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that N.', 'general', 'NC Dept. of Correction v. NC MEDICAL BD.', 'https://www.courtlistener.com/opinion/1325861/', '1325861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this matter is ripe for judicial review, and defendant''s assignments of error are thus overruled.', 'general', 'NC Dept. of Correction v. NC MEDICAL BD.', 'https://www.courtlistener.com/opinion/1325861/', '1325861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the order of the trial court.', 'general', 'NC Dept. of Correction v. NC MEDICAL BD.', 'https://www.courtlistener.com/opinion/1325861/', '1325861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and because the Position Statement is an invalid exercise of defendant''s statutory powers, we affirm the decision of the trial court.', 'general', 'NC Dept. of Correction v. NC MEDICAL BD.', 'https://www.courtlistener.com/opinion/1325861/', '1325861') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In a separate part of the opinion, we held that the evidence did not support a conviction for especially aggravated robbery because the fists and feet used to beat the victim could not, as a matter of law, be deemed deadly weapons.', 'general', 'State v. Allen', 'https://www.courtlistener.com/opinion/1060411/', '1060411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the aggregation was proper, and defendant’s motion to quash the information was properly denied.', 'general', 'People v. Vargo', 'https://www.courtlistener.com/opinion/1708332/', '1708332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that defendant has not met his burden of coming forward with sufficient evidence of prejudice and affirm the trial court’s denial of defendant’s motion to dismiss.', 'dismissal', 'People v. Vargo', 'https://www.courtlistener.com/opinion/1708332/', '1708332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a trial court may constitutionally restrict extrajudicial comments by trial participants, including lawyers, parties, and witnesses, when the trial court determines that those comments pose a substantial likelihood of prejudicing a fair trial.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under this constitutional standard, we hold that the trial court was justified in imposing a gag order on Car-ruthers.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the extraordinary nature of this case, we hold that the trial court was entitled to make this judgment.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we hold that initial gag orders on trial participants should ordinarily contain the exceptions found in the Brown order and allow trial participants to make general statements asserting innocence, commenting on the nature of an allegation or defense, and discussing matters of public record.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2000), we held that dismissal of an indictment is appropriate where a prosecutor’s use of a private attorney who received substantial compensation from a private, special interest group created a conflict of interest and an appearance of impropriety and *533violated the defendants’ right to due process under the Tennessee Constitution.', 'dismissal', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully reviewing the rec*524ord and the relevant legal authorities, we conclude that none of the errors raised by Tony Carruthers require reversal, that the evidence is sufficient to support the jury’s findings of the aggravating circumstances, and that the sentences of death are not excessive or disproportionate considering the circumstances of the crimes and the defendant.', 'sentencing', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With respect to James Montgomery, we conclude that the trial court erred in denying him a severance and that the error resulted in Montgomery being deprived of a fair trial.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After carefully and fully reviewing the record, the briefs of counsel, and the relevant legal authority, we conclude that none of the assigned errors require reversal of defendant Carruthers’ convictions or sentences.', 'sentencing', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that an indigent criminal defendant may implicitly waive or forfeit the right to counsel by utilizing that right to manipulate, delay, or disrupt trial proceedings.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that an implicit waiver may appropriately be found, where, as here, the record reflects that the trial court advises the defendant the right to counsel will be lost if the misconduct persists and generally explains the risks associated with self-representation.', 'general', 'State v. Carruthers', 'https://www.courtlistener.com/opinion/1060523/', '1060523') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, we find that the trial court erred in entering Summary Judgment on the common law fraud claim.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After careful consideration of these five internal memoranda and the record as a whole, we find that Stockholder''s version of events is a reasonable possibility and find that Summary Judgment should not have been entered in favor of Bank on the common law fraud claim.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, we find that the trial court erred in entering Summary Judgment on the securities fraud claim under section 517.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, even if that were true, we find that Stockholder still has a securities fraud claim under section 517.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Based on the record before us, we find that a jury question exists as to whether the statements made by the Bank representative to Stockholder constituted "investment advice" for purposes of the statute.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For all of the reasons previously set forth herein discussing the common law fraud claim, while expressing no opinion as to the merits, we find that Stockholder put forth sufficient evidence to survive Summary Judgment on his securities fraud claim.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, we find that the trial court erred in entering Summary Judgment on the breach of fiduciary duty claim.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these particular facts and circumstances, we find that Bank owed Stockholder a fiduciary duty of loyalty and care.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As with Stockholder''s other claims, while expressing no opinion as to the merits, we find that Summary Judgment should not have been entered on the breach of fiduciary duty claim as there is sufficient evidence in the record to support said claim.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the following reasons, we reverse the entry of Summary Judgment on all three claims.', 'general', 'Ward v. Atlantic SEC. Bank', 'https://www.courtlistener.com/opinion/1102781/', '1102781') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having reviewed the record and arguments presented, we conclude that the trial court correctly granted summary judgment on the claims of intentional infliction of emotional distress, invasion of privacy[2], libel, and battery, and we affirm as to those counts.', 'general', 'Rivers v. Dillards Dept. Store, Inc.', 'https://www.courtlistener.com/opinion/1135759/', '1135759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This question of fact cannot be decided on summary judgment, therefore we reverse as to the claim of false imprisonment.', 'general', 'Rivers v. Dillards Dept. Store, Inc.', 'https://www.courtlistener.com/opinion/1135759/', '1135759') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that the statute is constitutional.', 'general', 'Raulerson v. State', 'https://www.courtlistener.com/opinion/1689720/', '1689720') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the state had power to try Defendant for the murder committed in Mexico.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we conclude that the trial judge was not required to send the question of jurisdiction to the jury.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'There being no textual limit on the reach of this statute conferring extra-territorial power, we conclude that the statute includes, on its face, offenses consummated in foreign countries as well as in other states and that it was properly applied by the trial court.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[17] We conclude that the *545 application of A.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the danger of unfair prejudice on this record was not so great that any error could be described as fundamental.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On balance, we conclude that Defendant''s record of good deeds does not outweigh the aggravating factor.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that there was no error, fundamental or otherwise, in refusing Defendant''s request to instruct the jury on the jurisdictional prerequisites and only harmless error in the judge''s statement that he found jurisdiction by a preponderance.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We affirm the finding that Defendant murdered for financial gain.', 'general', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Defendant''s convictions and death sentence.', 'sentencing', 'State v. Willoughby', 'https://www.courtlistener.com/opinion/1163368/', '1163368') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although all of Loa’s points of error are without merit, we hold that the trial court committed plain error in instructing the jury regarding “attempted reckless manslaughter”—which is nonexistent—as an offense allegedly included within the charged offense of attempted first degree murder.', 'general', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '55 was the “attempted murder weapon,” we hold that the trial court did not commit a clear abuse of discretion in ruling that “enough foundation” had been laid to identify State’s Exhibit No.', 'general', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court correctly ruled that “there [was] enough relevancy” to admit State’s Exhibit No.', 'general', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not commit a clear abuse of discretion in ruling as it did.', 'general', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court did not commit an abuse of discretion in denying Loa’s motion for a mistrial on that basis.', 'mistrial', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not commit a plain and manifest abuse of discretion in sentencing Loa to extended terms of imprisonment pursuant to HRS §§ 706-661 and -662.', 'sentencing', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial court did not clearly exceed the bounds of reason or disregard rules or principles of law or practice to Loa’s substantial detriment and, accordingly, that the trial court did not commit a plain and manifest abuse of discretion in sentencing Loa to consecutive terms of imprisonment pursuant to HRS § 706-668.', 'sentencing', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it does not.', 'general', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The jury having acquitted Loa of that charge by virtue of its verdict, we hold that Loa may not be retried for it.', 'general', 'State v. Loa', 'https://www.courtlistener.com/opinion/1160508/', '1160508') ON CONFLICT DO NOTHING;
