INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, on the record before us, we hold that Friedman knowingly and voluntarily waived his right to a jury trial.', 'general', 'State v. Friedman', 'https://www.courtlistener.com/opinion/1316312/', '1316312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, because there was no threat of imminent harm, the trial court did not err in refusing to consider the choice of evils defense.', 'general', 'State v. Friedman', 'https://www.courtlistener.com/opinion/1316312/', '1316312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that Friedman’s equal protection rights under Article I, section 5 of the Hawaii Constitution and the fourteenth amendment to the United States Constitution were not violated.', 'general', 'State v. Friedman', 'https://www.courtlistener.com/opinion/1316312/', '1316312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that, “[w]here the same act committed under the same circumstances is punishable either as a felony or as a misdemeanor, under either of two statutory provisions, and the elements of proof essential to either conviction are exactly the same, a conviction under the felony statute would constitute a violation of defendant’s right to due process and the equal protection of the laws.', 'general', 'State v. Friedman', 'https://www.courtlistener.com/opinion/1316312/', '1316312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons discussed below, we affirm the conviction and sentence of the trial court.', 'sentencing', 'State v. Friedman', 'https://www.courtlistener.com/opinion/1316312/', '1316312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we affirm the conviction and sentence of the trial court.', 'sentencing', 'State v. Friedman', 'https://www.courtlistener.com/opinion/1316312/', '1316312') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence of defendant’s control of the apartment at 823-C Suffolk Boulevard, where heroin and implements of manufacturing of heroin were found, when considered with the evidence of transportation of 82.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under G.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the trial judge did not err in denying defendant’s motion that he direct the State to elect between prosecuting defendant for trafficking in heroin and the offenses of possession, manufacturing and transporting heroin.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we hold that the trial judge did not err by increasing defendant’s bond during the course of the trial.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Though more detail would be helpful, we hold that this assignment of error is sufficient to state the “basis upon which error is assigned.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the evidence of defendant’s bad character related in part to his activities in the illegal drug trade we hold that it does bear a reasonable relationship to the purposes of sentencing by demonstrating his increased culpability and is a proper aggravating factor.', 'sentencing', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal this Court held that there was ample evidence that defendant was engaged in manufacturing the controlled substance.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'It is Ordered that Prayer for Judgment be continued, with the express consent of the defendant in open court, from term to term and session to session of the Wake County Superior Court for a maximum term of five (5) years from this date unless the Solicitor for the State in his/her unfettered and unbridled discretion prays judgment in the next five (5) years.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that there was ample evidence to give rise to a reasonable inference that defendant did manufacture heroin by packaging the controlled substance.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that possessing, manufacturing, and transporting heroin are separate and distinct offenses.', 'general', 'State v. Perry', 'https://www.courtlistener.com/opinion/1238062/', '1238062') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon rehearing the relevant issues en banc, we hold that the ends of justice exception does not apply to Holt’s case and affirm her conviction for obtaining money by false pretenses in violation of Code § 18.', 'general', 'Angela Maye Holt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/3193119/', '3193119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To clarify this inconsistency, we hold that the grant of en banc review stays a panel decision pending review of those issues for which rehearing en banc has been granted but does *208not vacate it, and we overrule Ferguson to the extent it holds otherwise.', 'general', 'Angela Maye Holt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/3193119/', '3193119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 (2007) (en banc)), this Court held that the “ ‘grant of en banc review vacates the prior panel opinion in toto .', 'general', 'Angela Maye Holt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/3193119/', '3193119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons previously stated, we conclude that the ends of justice exception to Rule 5A:18 does not apply under the facts and circumstances of this case.', 'general', 'Angela Maye Holt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/3193119/', '3193119') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1989) ("Thus, we hold that the trial court did not err in denying the defendant''s motion to require that the People elect specific acts.', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we conclude that the People referenced Melina''s conversations with several individuals to corroborate his intent to have someone kill Bueno, not to suggest that Melina had committed several crimes of solicitation.', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
