INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Woertman, we reversed the defendant''s convictions for sexual assault on a child after announcing that we were reviewing for plain error, but we did so only because the trial court also admitted evidence of over fifty separate acts, despite a bill of particulars limiting the charges to three specific acts, and not only failed to limit the purpose for which the additional acts could be considered but actually instructed the jury that it would be sufficient for conviction to find any act that...', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we affirm the judgment of the court of appeals.', 'general', 'Melina v. People', 'https://www.courtlistener.com/opinion/2599838/', '2599838') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that appointed counsel is constitutionally required under Wyoming’s judicial probation revocation procedure, we reverse.', 'general', 'Pearl v. State', 'https://www.courtlistener.com/opinion/1316359/', '1316359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, under Wyoming’s judicial revocation procedure where the State is represented by a prosecutor and the rules of evidence apply to a portion of the proceedings, we hold that the Sixth Amendment requires appointment of counsel for indigent probationers when the indigent probationer was entitled to be represented by an attorney under Wyo.', 'general', 'Pearl v. State', 'https://www.courtlistener.com/opinion/1316359/', '1316359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the Sixth Amendment dictates that counsel be appointed for all indigent probationers in Wyoming’s judicial proceedings.', 'general', 'Pearl v. State', 'https://www.courtlistener.com/opinion/1316359/', '1316359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that revocation proceedings in Wyoming are fundamentally different than the administrative process upon which
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As Pearl was denied his right to counsel, we reverse and remand to the district court to conduct a probation revocation hearing in accordance with this opinion.', 'general', 'Pearl v. State', 'https://www.courtlistener.com/opinion/1316359/', '1316359') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '100 to require convicted sex offenders to register and to periodically provide certain information to the State, we conclude that the legislature intended this clause to refer to all four subsections of AS 11.', 'general', 'Dailey v. State', 'https://www.courtlistener.com/opinion/2625874/', '2625874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although Dailey separately argues that this scheme is unconstitutionally vague because it did not provide him -with adequate notice that his conduct was a criminal offense, we conclude that the statutes provided him with adequate notice that it was a crime to knowingly fail to file sworn written quarterly verification forms.', 'general', 'Dailey v. State', 'https://www.courtlistener.com/opinion/2625874/', '2625874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Magistrate Landry did not err when he denied Dailey’s motion to dismiss.', 'dismissal', 'Dailey v. State', 'https://www.courtlistener.com/opinion/2625874/', '2625874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Here, we conclude that Magistrate Landry’s instruction was adequate to address Dailey’s concern about rebutting the trooper’s testimony.', 'general', 'Dailey v. State', 'https://www.courtlistener.com/opinion/2625874/', '2625874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the instruction Magistrate Landry gave defining “knowingly” was proper.', 'general', 'Dailey v. State', 'https://www.courtlistener.com/opinion/2625874/', '2625874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” But, despite the fact that both his objections and his proposed instruction served to confuse this issue more than to provide guidance, we find that Dailey adequately alerted the district court that the jury instructions were incomplete.', 'jury_instruction', 'Dailey v. State', 'https://www.courtlistener.com/opinion/2625874/', '2625874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons below, we affirm Dailey’s convictions.', 'general', 'Dailey v. State', 'https://www.courtlistener.com/opinion/2625874/', '2625874') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in syllabus point 8 of State v.', 'general', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Therefore, we conclude that the trial court''s *565 sentence for such a crime does not shock the conscience.', 'sentencing', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the sentence in this case does not violate the proportionality principle found in Article III, Section 5 of the State Constitution.', 'sentencing', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the parties'' arguments and the record, we affirm the circuit court.', 'general', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing, we affirm the circuit court''s sentencing order of 15 to 35 years in the penitentiary.', 'sentencing', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we reverse the judgment of the appellate court and remand this matter to the appellate court for consideration of sentencing issues previously raised, but not addressed, in the appellate court.', 'sentencing', 'People v. Hart', 'https://www.courtlistener.com/opinion/2080654/', '2080654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the issue is procedurally defaulted and that no basis exists to excuse the default under our case law.', 'general', 'People v. Hart', 'https://www.courtlistener.com/opinion/2080654/', '2080654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it did.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1316362/', '1316362') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the trial court erred by revoking probation and imposing the prison term it did.', 'general', 'State v. Thomas', 'https://www.courtlistener.com/opinion/1316362/', '1316362') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we hold that the complaint failed to adequately inform Israel of the nature and cause of the HRS § 134-6(a) charge and failed to ensure that the district court had before it all the facts necessary to find probable cause on that charge.', 'probable_cause', 'State v. Israel', 'https://www.courtlistener.com/opinion/2617509/', '2617509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the State failed to adequately inform Israel of the nature and cause of the HRS § 134-6(a) charge.', 'general', 'State v. Israel', 'https://www.courtlistener.com/opinion/2617509/', '2617509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the complaint failed to adequately inform Israel of the nature and cause of the HRS § 134-6(a) charge and failed to ensure that the district court had before it all the facts necessary to find probable cause on that charge.', 'probable_cause', 'State v. Israel', 'https://www.courtlistener.com/opinion/2617509/', '2617509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this court held that where the defendant could ascertain from the oral decision of the trial court and the grand jury transcript that the State’s accusation was that the “crime against a person or against property rights” that he intended to commit as part of a burglary charge was theft, his right to be informed of the nature and cause of the accusation was not violated.', 'general', 'State v. Israel', 'https://www.courtlistener.com/opinion/2617509/', '2617509') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Israel', 'https://www.courtlistener.com/opinion/2617509/', '2617509') ON CONFLICT DO NOTHING;
