INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In these consolidated appeals, Pearson-Anderson asks that we reverse the order denying her suppression motion and the order revoking probation.', 'suppression', 'State v. Pearson-Anderson', 'https://www.courtlistener.com/opinion/2600824/', '2600824') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying UCO, we find that the legislature has described a single offense in AS 11.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1172731/', '1172731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the jury instructions were proper, we reverse the decision of the court of appeals.', 'jury_instruction', 'State v. James', 'https://www.courtlistener.com/opinion/1172731/', '1172731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we reverse the appellate court on the issue of jury unanimity, we must consider a second contention James made in that court.', 'general', 'State v. James', 'https://www.courtlistener.com/opinion/1172731/', '1172731') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm.', 'general', 'State v. Brooks', 'https://www.courtlistener.com/opinion/1721384/', '1721384') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the evidence adequate to support the jury’s verdict, we affirm.', 'general', 'State v. Hutchison', 'https://www.courtlistener.com/opinion/1652619/', '1652619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error in the trial court’s refusal to enter judgments of acquittal, we affirm.', 'general', 'State v. Hutchison', 'https://www.courtlistener.com/opinion/1652619/', '1652619') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that where a burglary is alleged to be the felony on which the felony murder charge is predicated, the death that occurs must not only be “in the course of’ the burglary but also must be “in furtherance of’ the burglary.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1952665/', '1952665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we held that the felony murder statute does not encompass all homicides.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1952665/', '1952665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we reverse on this ground alone the death sentence from which this appeal is taken because the death sentence was predicated solely on the felony murder statute.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1952665/', '1952665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the sentence of the trial court and remand with direction that the court impose upon Williams a sentence of natural life without the possibility of parole on the other homicide conviction for intentional murder.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/1952665/', '1952665') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Jurco was not entitled to forcibly resist the troopers even if he reasonably believed that the seizure of his truck was illegal.', 'general', 'Jurco v. State', 'https://www.courtlistener.com/opinion/2618351/', '2618351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, the question presented by Jurco''s case is: which of these two statutes did the legislature intend to take precedence when law enforcement officers attempt to execute a court order calling for the seizure of property? We conclude that a person is not entitled to use force to resist the taking of property by law enforcement officers pursuant to a court order.', 'general', 'Jurco v. State', 'https://www.courtlistener.com/opinion/2618351/', '2618351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that when a person is confronted by a police officer (1) who is known to be or reasonably appears to be a police officer, and (2) who is known to be or reasonably appears to be required or authorized to take possession of the person''s property under a judicial decree, judgement, or order, that person must submit peaceably to the officer''s taking of the property.', 'general', 'Jurco v. State', 'https://www.courtlistener.com/opinion/2618351/', '2618351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For this reason, we conclude that the trial judge''s misallocation of the burden of proof was harmless error, and that Jurco was not entitled to a continuance of the trial.', 'general', 'Jurco v. State', 'https://www.courtlistener.com/opinion/2618351/', '2618351') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, as a matter of law, when [the insured] intentionally fired a gun into the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in denying the Auto-Owners motion for sum-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court''s decision to deny the Auto-Owners motion for summary judg-
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'A panel of this Court held that it was without active jurisdiction to consider Whitt’s appeal, and consequently dismissed it.', 'dismissal', 'Steve Whitt v. Commonwealth of Virginia', 'https://www.courtlistener.com/opinion/1061446/', '1061446') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '160 L Ed 2d 621 (2005), we hold that a guidelines minimum sentence range calculated in violation of Apprendi and Alleyne is advisory only and that sentences that depart from that threshold are to be reviewed by appellate courts for reasonableness.', 'sentencing', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To preserve as much as possible the legislative intent in enacting the guidelines, however, we hold that a sentencing court must determine the applicable guidelines range and take it into account when imposing a sentence.', 'sentencing', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that he cannot show the prejudice necessary to establish plain error under People v Carines, 460 Mich 750;', 'general', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that trial courts “must consult those Guidelines and take them into account when sentencing.', 'sentencing', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First, consistently with Crosby, we hold that Crosby remands are warranted only in cases involving sentences imposed on or before July 29, 2015, the date of today’s decision.', 'sentencing', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To remedy the constitutional flaw in the guidelines, we hold that they are advisory only.', 'general', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, because at that time the Apprendi rule only applied to maximum sentences, not mínimums, and judicial fact-finding to set the guidelines range only affected minimum sentences, we held that Michigan’s sentencing guidelines scheme did not violate the Sixth Amendment.', 'sentencing', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the rule from Apprendi v New Jersey, 530 US 466;', 'general', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Michigan’s sentencing guidelines produce a “mandatory minimum” sentence to which Alleyne applies.', 'sentencing', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Like the Supreme Court in Booker, however, we conclude that although the guidelines can no longer be mandatory, they remain a highly relevant consideration in a trial court’s exercise of sentencing discretion.', 'sentencing', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we held that the rule of Apprendi is inapplicable to Michigan’s sentencing system.', 'sentencing', 'People v. Lockridge', 'https://www.courtlistener.com/opinion/2822014/', '2822014') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a municipal police officer on off-duty status is not relieved of his obligation as an officer to preserve the public peace and to protect the public in general pursuant to West Virginia Code § 8-14-3 (1998).', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1238205/', '1238205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 484 (1988), we held that:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that at the time of the offenses at issue in this case, the officer in question was acting in his lawful, official capacity, and that the magistrate court did not err in refusing to give certain jury instructions, we affirm the order of the circuit court affirming the convictions.', 'jury_instruction', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1238205/', '1238205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of this syllabus point, we find that the trial court’s refusal to give Appellant’s proposed instruction numbered three was not in error and should not be reversed.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1238205/', '1238205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we find that the trial court’s redaction of the last sentence in Appellant’s instruction numbered six was not in error and should not be reversed.', 'sentencing', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1238205/', '1238205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we found that it “seem[ed] improper” for a Wheeling City Police Officer to withhold valid criminal warrants and then serve them at the direction of his private employer (Wheeling Downs Race Track) only after other debt collection measures had failed.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1238205/', '1238205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we affirm the order of the Circuit Court of Harrison County.', 'general', 'State v. Phillips', 'https://www.courtlistener.com/opinion/1238205/', '1238205') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that while "Maldonado may have been negligent, his actions do not rise to the level of reckless disregard.', 'general', 'City of Jackson v. Brister', 'https://www.courtlistener.com/opinion/1102117/', '1102117') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the officer''s actions did show a reckless disregard for the safety and well-being of others and affirmed the lower court''s ruling.', 'general', 'City of Jackson v. Brister', 'https://www.courtlistener.com/opinion/1102117/', '1102117') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1999), this Court held that a deputy sheriff acted with reckless disregard for the safety and well-being of others when he backed up an incline knowing that he could not see oncoming traffic.', 'general', 'City of Jackson v. Brister', 'https://www.courtlistener.com/opinion/1102117/', '1102117') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that "[t]he act of driving for police officers is a major part of their jobs.', 'general', 'City of Jackson v. Brister', 'https://www.courtlistener.com/opinion/1102117/', '1102117') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After review of the case, we find that the ruling of the trial court was correct and was supported by substantial, credible, and reasonable evidence.', 'general', 'City of Jackson v. Brister', 'https://www.courtlistener.com/opinion/1102117/', '1102117') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the learned trial judge applied our controlling case law, we affirm.', 'general', 'City of Jackson v. Brister', 'https://www.courtlistener.com/opinion/1102117/', '1102117') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that “good cause” existed as a matter of law to support the circuit court’s decision to grant the motion to nolle prosequi the indictment for multiple worthless checks.', 'general', 'Moore v. Commonwealth', 'https://www.courtlistener.com/opinion/1061721/', '1061721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we affirm the judgment of the trial court.', 'general', 'Moore v. Commonwealth', 'https://www.courtlistener.com/opinion/1061721/', '1061721') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated, we affirm the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, while "a State is free as a matter of its own law to impose greater restrictions on police activity than those this Court holds to be necessary upon federal constitutional standards .', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in light of the independent corroborating evidence supporting the defendant''s murder conviction and the fact that substantial impeachment evidence was introduced against Tillberry, the alleged withholding of the additional impeachment evidence from Baptista[6] did not result in an unfair trial.', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defendant has failed to carry this burden.', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the failure of the State to give the defendant this impeachment evidence does not undermine confidence in the trial''s outcome.', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, with respect to the claim involving his sentences for both Murder and Robbery/ Murder and Class A felony Robbery, the defendant has failed to carry his burden and, therefore, his claim fails.', 'sentencing', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, with respect to his sentences for both Conspiracy to Commit Battery and Conspiracy to Commit Robbery,[14]*478 we find that the defendant has established prejudice.', 'sentencing', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the defendant has established prejudice.', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Notwithstanding this deferential standard, we find that, under prevailing professional norms, there is no reasonable strategy for failing to raise this clear double jeopardy violation.', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The judgment of the post-conviction court is affirmed, with the exception of the multiple conspiracy convictions, wherein we find that the conviction for Conspiracy to Commit Battery must be vacated.', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the post-conviction court in part and reverse in part.', 'general', 'Games v. State', 'https://www.courtlistener.com/opinion/2247332/', '2247332') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm appellant’s conviction on that charge.', 'general', 'Holloway v. Commonwealth', 'https://www.courtlistener.com/opinion/1062003/', '1062003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm appellant’s conviction.', 'general', 'Holloway v. Commonwealth', 'https://www.courtlistener.com/opinion/1062003/', '1062003') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that evidence adduced at trial was insufficient to
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that “[a]lthough Rodriquez did
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we reverse Brown’s
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though Goss was sentenced *1210 under Section 47-7-33, this Court held that sentence time plus probation time is limited to the maximum sentence.', 'sentencing', 'Carter v. State', 'https://www.courtlistener.com/opinion/1133442/', '1133442') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that the trial court failed to make the factual findings required as a prerequisite for the application of the forfeiture by wrongdoing doctrine, we hold that the affidavit was admissible nonetheless.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*481Because the primary purpose of the affidavit was not to “prove past events potentially relevant to later criminal prosecution” but rather to obtain a civil, preliminary protective order, we hold that the statements contained therein were nontestimonial under Davis and, therefore, did not implicate Crawford’s Sixth Amendment right to confrontation.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we hold that the trial court incorrectly applied the forfeiture by wrongdoing doctrine because it did not consider whether Crawford acted with the intent to prevent Sarah from either testifying as a witness or seeking aid from the judicial process.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we hold that the statements contained in the affidavit were not testimonial under Davis, and thus, did not implicate Crawford’s Sixth Amendment right to confrontation, the trial court’s ultimate admission of the affidavit was not error.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, given counsel for Crawford’s concession that, with the affidavit, the evidence is sufficient to sustain his convictions for abduction with intent to defile and rape, we hold that Crawford has waived his argument with respect to this issue.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, our analysis is not yet complete because, as the Commonwealth argues on brief, although the trial court admitted the affidavit based upon the applicability of the forfeiture by wrongdoing doctrine, another rationale for its admissibility is reflected in *476the record before us, and we find that rationale sufficient to affirm the decision of the trial court in admitting the affidavit.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '10 For the following reasons, we disagree with Crawford and the analysis of both the panel majority and dissent, and we affirm Crawford’s convictions.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm Crawford’s convictions for abduction with intent to defile and rape.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm all of Crawford’s convictions.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we affirm Crawford’s convictions for abduction with intent to defile and rape, we also affirm his convictions for capital murder, use of a firearm in the commission of a murder, and use of a firearm in the commission of an abduction.', 'general', 'Crawford v. Commonwealth', 'https://www.courtlistener.com/opinion/1062279/', '1062279') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, based on our review of the record, we conclude that these errors, in view of the overwhelming evidence of Defendant’s guilt, had little effect on the outcome of the trial, did not cumulatively prejudice Defendant so as to deny him a fair and impartial trial, and were thus harmless.', 'general', 'State v. Palabay', 'https://www.courtlistener.com/opinion/1249067/', '1249067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Absent the finding of necessity and in view of the foregoing authorities, we conclude that it was error for the trial court to allow Complainant to testify while holding a teddy bear.', 'general', 'State v. Palabay', 'https://www.courtlistener.com/opinion/1249067/', '1249067') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case, we hold that E.', 'general', 'E.C. v. RCM of Washington, Inc.', 'https://www.courtlistener.com/opinion/2677201/', '2677201') ON CONFLICT DO NOTHING;
