INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in regard to suits brought under AS 09.', 'general', 'Spenard Action Committee v. Lot 3, Block 1, Evergreen Subdivision', 'https://www.courtlistener.com/opinion/2607137/', '2607137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the superior court did not abuse its discretion in rejecting SAC’s request for the entry of an establishment-preelusion order against Lot 3.', 'general', 'Spenard Action Committee v. Lot 3, Block 1, Evergreen Subdivision', 'https://www.courtlistener.com/opinion/2607137/', '2607137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that willfulness is not required for a sanction of attorney’s fees and expenses under Alaska Civil Rule 37(b)(2).', 'general', 'Spenard Action Committee v. Lot 3, Block 1, Evergreen Subdivision', 'https://www.courtlistener.com/opinion/2607137/', '2607137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that a conviction which has been set aside may be introduced as evidence in a future proceeding for certain purposes.', 'general', 'Spenard Action Committee v. Lot 3, Block 1, Evergreen Subdivision', 'https://www.courtlistener.com/opinion/2607137/', '2607137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the criminal conviction of a non-party following trial is not admissible as evidence in a subsequent .', 'general', 'Spenard Action Committee v. Lot 3, Block 1, Evergreen Subdivision', 'https://www.courtlistener.com/opinion/2607137/', '2607137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the superior court abused its discretion in permitting the police officers to express their opinions as to whether The Chateau was operating as a house of prostitution.', 'general', 'Spenard Action Committee v. Lot 3, Block 1, Evergreen Subdivision', 'https://www.courtlistener.com/opinion/2607137/', '2607137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the first criterion is satisfied.', 'general', 'Spenard Action Committee v. Lot 3, Block 1, Evergreen Subdivision', 'https://www.courtlistener.com/opinion/2607137/', '2607137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing, we hold that the superior court erred in concluding that SAC is not a public interest litigant.', 'general', 'Spenard Action Committee v. Lot 3, Block 1, Evergreen Subdivision', 'https://www.courtlistener.com/opinion/2607137/', '2607137') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 188 (Alaska 1978), this court held that the criminal conviction of a party is admissible in a subsequent civil trial where:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court did not commit error by allowing the examiner to testify regarding his opinion that Overall’s death was a homicide.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the examiner’s testimony regarding the opinions of the nontestifying experts was inadmissible hearsay.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the admission of the hearsay evidence from nontestifying experts was harmless beyond a reasonable doubt because there is no reasonable possibility that the wrongfully admitted evidence could have affected the jury’s verdict.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the search warrant was supported by probable cause.', 'probable_cause', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that admission of any evidence that was not in plain view of the officers was harmless error beyond a reasonable doubt.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'there-, fore, we hold that the court properly con-eluded that Bradford invoked his right to counsel, but then waived that right after reinitiating a conversation with the police.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the substantial amount of other admissible evidence at trial that demonstrated a pattern of domestic abuse, if the court erred by admitting the affidavit, we hold that such error is harmless beyond a reasonable doubt.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we acknowledge that there was a substantial amount of admissible evidence demonstrating a past pattern of domestic abuse, we hold that this error was also harmless beyond a reasonable doubt.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the substantial evidence of Bradford’s guilt compared with the isolated nature of this conduct, we hold that this prosecutorial misconduct was harmless beyond a reasonable doubt.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that heat-of-passion manslaughter is not a lesser-included mitigating offense of first-degree domestic abuse murder.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the “references were prosecutorial misconduct but harmless under the circumstances.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because of the jury’s adverse reaction to what we characterized as “amateur displays,” we concluded that the conduct did not prejudice the defendant, but we expressed concern that the prosecutor’s conduct demeaned the participants in the trial and the court.', 'general', 'State v. Bradford', 'https://www.courtlistener.com/opinion/2033411/', '2033411') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'such, we hold that the two statutes are similar.', 'general', 'Johnson v. Commonwealth', 'https://www.courtlistener.com/opinion/1062512/', '1062512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the language of Code § 9.', 'general', 'Johnson v. Commonwealth', 'https://www.courtlistener.com/opinion/1062512/', '1062512') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that a person convicted of second-degree
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm the decision of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the exemption clearly does not encompass the defendant’s conduct because the exemption does not, under any circumstances, authorize the possession of child pornography.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that if an indictment or county attorney’s information facially shows a charge on which the State may not constitutionally prosecute, then a plea of guilty subsequent to an adverse ruling on a demurrer does not waive the claimed unconstitutionality as “no offense is stated.', 'plea', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant’s conduct clearly falls outside the parameters of the statutory exemption.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if this issue had been preserved, it would not alter the outcome here, because we hold that under no reasonable construction of the statute would a person of ordinary intelligence conclude that the legislature intended to permit the use of child pornography, inside or outside school.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In our Hunter case, this court held that a guilty plea did not waive the defendant’s right to claim on appeal that the statute under which he was charged was unconstitutionally vague.', 'plea', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that under no construction of the statute would a reasonably intelligent person believe that such material, showing children engaged in sexual acts, is “appropriate.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the defendant’s conviction, but preserve his ineffective-assistance-of-counsel claim.', 'ineffective_assistance', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Schrup, we held that a defendant could not be charged with the mere possession of obscene materials without also having the intent to distribute them.', 'general', 'State v. Robinson', 'https://www.courtlistener.com/opinion/2033439/', '2033439') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In response to an attempt to expand a statute to include certain areas not listed, this court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/1232998/', '1232998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Court of Appeals’ decision and reinstate Defendant’s conviction.', 'general', 'State v. Wilson', 'https://www.courtlistener.com/opinion/1232998/', '1232998') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that section 1385(a) does permit a court acting on its own motion to strike prior felony conviction allegations in cases *530 brought under the Three Strikes law.', 'general', 'People v. Superior Court (Romero)', 'https://www.courtlistener.com/opinion/1135929/', '1135929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the transcript is not relevant to the statutory construction and constitutional issues before us and, therefore, deny defendant''s motion as to the transcript.', 'general', 'People v. Superior Court (Romero)', 'https://www.courtlistener.com/opinion/1135929/', '1135929') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering the evidence in the light most favorable to the State, we find that there was sufficient evidence to convict Bush of capital murder with the underlying felony being armed robbery.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1666850/', '1666850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these facts, we find that any rational juror could have found beyond a reasonable doubt that all of the elements had been met by the State in proving capital murder with the underlying felony being armed robbery.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1666850/', '1666850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we find that the opinions to which we cite in the body of our opinion today articulate the standards of review much more cogently than the previously cited opinions which contain cryptic and incongruous explanations of the standards.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1666850/', '1666850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, in Stoop, we found that the trial court inappropriately admitted the transcript testimony of a witness whom the State had not sufficiently demonstrated was unavailable to testify.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1666850/', '1666850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bush requests that we reverse and remand the case for a new trial.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1666850/', '1666850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Bush now appeals the conviction which we affirm.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1666850/', '1666850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Harrison County Circuit Court''s judgment.', 'general', 'Bush v. State', 'https://www.courtlistener.com/opinion/1666850/', '1666850') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Marcum, this Court held it could not conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'the prosecutor’s trial tactics in this case, we affirm the judgment of the trial court.', 'general', 'Bruce Ryan v. State of Indiana', 'https://www.courtlistener.com/opinion/2677538/', '2677538') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the primary purpose doctrine to the facts of this case, we conclude that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm the trial court’s judgment and appellant’s conviction.', 'general', 'Caison v. Commonwealth', 'https://www.courtlistener.com/opinion/1062705/', '1062705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'appellate review require that we affirm determinations of fact made by the trial court unless there
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we affirm the trial court’s judgment and appellant’s conviction.', 'general', 'Caison v. Commonwealth', 'https://www.courtlistener.com/opinion/1062705/', '1062705') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'An appellate claim of insufficient evidence will prevail if, considering the probative evidence and reasonable inferences that support the judgment, and without weighing evidence or assessing witness credibility, we conclude that no reasonable trier of fact could find the defendant guilty beyond a reasonable doubt.', 'general', 'Tobias v. State', 'https://www.courtlistener.com/opinion/2033567/', '2033567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence favorable to the judgment was sufficient to enable a reasonable jury to find the element of compulsion by force to have been proven beyond a reasonable doubt.', 'general', 'Tobias v. State', 'https://www.courtlistener.com/opinion/2033567/', '2033567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We need not decide whether such testimony was improper or, if so, whether counsel’s conduct was deficient, because we find that the presence of such evidence was not reasonably likely to have affected the outcome of the defendant’s trial.', 'general', 'Tobias v. State', 'https://www.courtlistener.com/opinion/2033567/', '2033567') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding the evidence sufficient, we affirm Coleman’s conviction for felony eluding in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we hold that the police had probable cause to arrest Jones.', 'probable_cause', 'Jones v. Commonwealth', 'https://www.courtlistener.com/opinion/1062788/', '1062788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing discussion, we hold that the trial court did not err in finding
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'sufficient probable cause in this case, we conclude that these facts taken as a whole provided the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Jones’ conviction.', 'general', 'Jones v. Commonwealth', 'https://www.courtlistener.com/opinion/1062788/', '1062788') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the common law power of inferior courts to require security for good behavior, as applied to attorneys, is obsolete and has been superceded by the modern organization of judicial power in West Virginia;', 'general', 'State Ex Rel. Askin v. Dostert', 'https://www.courtlistener.com/opinion/1342221/', '1342221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we therefore hold that W.', 'general', 'State Ex Rel. Askin v. Dostert', 'https://www.courtlistener.com/opinion/1342221/', '1342221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the Act is constitutional.', 'general', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Bowsher, we held that "Congress cannot reserve for itself the power of removal of an officer charged with the execution of the laws except by impeachment.', 'general', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing history and precedent, we conclude that the principle of separation of powers does not absolutely prohibit Article III judges from serving on commissions such as that created by the Act.', 'general', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although it is a judgment that is not without difficulty, we conclude that the participation of federal judges on the Sentencing Commission does not threaten, either in fact or in appearance, the impartiality of the Judicial Branch.', 'sentencing', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in creating the Sentencing Commission  an unusual hybrid in structure and authority  Congress neither delegated excessive legislative power nor upset the constitutionally mandated balance of powers among the coordinate Branches.', 'sentencing', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we concluded that those powers were not "judicial .', 'general', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given the consistent responsibility of federal judges to pronounce sentence within the statutory range established by Congress, we find that the role of the Commission in promulgating guidelines for the exercise of that judicial function bears considerable similarity to the role of this Court in establishing rules of procedure under the various enabling Acts.', 'sentencing', 'Mistretta v. United States', 'https://www.courtlistener.com/opinion/112173/', '112173') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To summarize, we hold that the facts shown in these cases by Appellants'' allegations in the complaints and responses to requests for discovery asserting Hutton''s violation of the statutory reporting requirements are legally sufficient to show the existence of a legal duty owed by Hutton to Appellants.', 'general', 'Palmer v. Shearson Lehman Hutton, Inc.', 'https://www.courtlistener.com/opinion/1151636/', '1151636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the facts alleged in support of the causes of action asserted in these cases are legally sufficient to satisfy these elements.', 'general', 'Palmer v. Shearson Lehman Hutton, Inc.', 'https://www.courtlistener.com/opinion/1151636/', '1151636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the facts alleged in the complaints, if proven, are sufficient to show that Hutton''s statutory violation could be found by a reasonable person to be a proximate or legal cause of Appellants'' injuries.', 'general', 'Palmer v. Shearson Lehman Hutton, Inc.', 'https://www.courtlistener.com/opinion/1151636/', '1151636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we conclude that Hutton''s legal duty under the statutes discussed extended to these Appellants to prevent the alleged losses they have sustained.', 'general', 'Palmer v. Shearson Lehman Hutton, Inc.', 'https://www.courtlistener.com/opinion/1151636/', '1151636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse.', 'general', 'Palmer v. Shearson Lehman Hutton, Inc.', 'https://www.courtlistener.com/opinion/1151636/', '1151636') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Heckman should have received 6 days’ credit on his sentences and affirm the judgment of the trial court in all other respects.', 'sentencing', 'State v. Heckman', 'https://www.courtlistener.com/opinion/2218271/', '2218271') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, on the facts of this case, the officer''s expeditious stop of the vehicle was based upon sufficiently reliable information, notwithstanding the absence of any personal observation of incriminating behavior by the driver.', 'general', 'State v. Boyea', 'https://www.courtlistener.com/opinion/1959712/', '1959712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Rather, we hold that the totality of the factual circumstances in this case satisfied the requirements of reliability.', 'general', 'State v. Boyea', 'https://www.courtlistener.com/opinion/1959712/', '1959712') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that this case "involved[d] more than a hunch.', 'general', 'State v. Boyea', 'https://www.courtlistener.com/opinion/1959712/', '1959712') ON CONFLICT DO NOTHING;
