INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The question in the case is, under these circumstances, does the combination of the strong odor of marijuana coming from the apartment, and the knowledge on the part of the occupants that the police are standing outside, amount to exigent circumstances justifying the warrantless entry and subsequent search? We hold that it does, and therefore reverse the court of appeals decision that reversed the circuit court''s order upholding this search.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1305055/', '1305055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, under the circumstances of this case, the determination of the seriousness of the offense for purposes of Fourth Amendment exigent circumstances analysis requires an evaluation of the overall penalty structure for offenses of this type.', 'search_seizure', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1305055/', '1305055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, taking the overall penalty structure for marijuana possession into consideration, and evaluating it against the backdrop of the very real and serious *301 exigency present here, we conclude that Welsh does not require invalidation of this warrantless home entry.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1305055/', '1305055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Court refrained from drawing a bright-line rule: "Because we conclude that, in the circumstances presented by this case, there were no exigent circumstances sufficient to justify a warrantless home entry, we have no occasion to consider whether the Fourth Amendment may impose an absolute ban on warrantless home arrests for certain minor offenses.', 'search_seizure', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1305055/', '1305055') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the record in this case establishes both, and thus hold that the entry was permissible.', 'general', 'State v. Hughes', 'https://www.courtlistener.com/opinion/1305055/', '1305055') ON CONFLICT DO NOTHING;
