INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of these decisions, the jury’s verdict forms, and the trial judge’s order entered upon the jury’s verdict, we hold that the trial judge’s failure to include a reference to Code § 18.', 'general', 'Bazemore v. Commonwealth', 'https://www.courtlistener.com/opinion/1063982/', '1063982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“We held that a manifest injustice had occurred because the ‘instructions given by the trial court relieved the Commonwealth of its burden to.', 'general', 'Bazemore v. Commonwealth', 'https://www.courtlistener.com/opinion/1063982/', '1063982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, in view of the arguments Bazemore actually advanced at trial and the evidence produced, we conclude that no basis exists to invoke the exceptions to Rule 5A:18.', 'general', 'Bazemore v. Commonwealth', 'https://www.courtlistener.com/opinion/1063982/', '1063982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that this record provides no basis to consider this claim under the exceptions to Rule 5A:18.', 'general', 'Bazemore v. Commonwealth', 'https://www.courtlistener.com/opinion/1063982/', '1063982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that we are likewise precluded from considering Bazemore’s final contention that the trial judge erred in instructing the jury on the elements of the offense of eluding.', 'general', 'Bazemore v. Commonwealth', 'https://www.courtlistener.com/opinion/1063982/', '1063982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon rehearing this case en banc, we affirm each of Bazemore’s convictions.', 'general', 'Bazemore v. Commonwealth', 'https://www.courtlistener.com/opinion/1063982/', '1063982') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we affirm Bazemore’s convictions.', 'general', 'Bazemore v. Commonwealth', 'https://www.courtlistener.com/opinion/1063982/', '1063982') ON CONFLICT DO NOTHING;
