INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the language of § 13A-8-11(b), Code of Alabama 1975, indicates a legislative intent to adopt the definitions of entry as defined by Alabama decisional law regarding burglary.', 'general', 'Pack v. State', 'https://www.courtlistener.com/opinion/1104398/', '1104398') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that thermal imaging is not an unconstitutional search, and the affidavit information was not stale.', 'general', 'State v. Norris', 'https://www.courtlistener.com/opinion/1079931/', '1079931') ON CONFLICT DO NOTHING;
