INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Page, this Court held that an indictment charging the defendant with a fourth offense felony DUI was insufficient because it failed to charge a felony offense.', 'general', 'Drennan v. State', 'https://www.courtlistener.com/opinion/1128478/', '1128478') ON CONFLICT DO NOTHING;
