INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the Implied Consent Law "increases the penalty for each succeeding conviction under that particular statute so that the third conviction is punishable as a felony.', 'general', 'Drennan v. State', 'https://www.courtlistener.com/opinion/1128478/', '1128478') ON CONFLICT DO NOTHING;
