INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1990), this Court held "[b]efore counsel can be deemed to have been ineffective, it must be shown (1) that counsel''s performance was deficient, and (2) that the defendant was prejudiced by counsel''s mistakes.', 'ineffective_assistance', 'Drennan v. State', 'https://www.courtlistener.com/opinion/1128478/', '1128478') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the trial court erred when it failed to suppress this evidence because the officer’s warrantless entry into the defendant’s home was without proper justification.', 'suppression', 'State v. White', 'https://www.courtlistener.com/opinion/1129404/', '1129404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 706 (1985), this court held that the state may prove prior convictions by evidence other than a certified judgment of conviction.', 'general', 'State v. White', 'https://www.courtlistener.com/opinion/1129404/', '1129404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we affirm the judgments of conviction and sentences on the burglary and sexual assault charge, we deem it appropriate to set aside the assault conviction pursuant to A.', 'sentencing', 'State v. White', 'https://www.courtlistener.com/opinion/1129404/', '1129404') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Schermerhorn’s constitutional challenge was not properly preserved, we affirm the jury’s decision without addressing the merit of his argument.', 'general', 'Schermerhorn v. State', 'https://www.courtlistener.com/opinion/4256257/', '4256257') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence of the images and videos showing the insertion of objects into persons'' anuses was properly admitted for the purpose of showing Normington''s motive.', 'general', 'State v. Normington', 'https://www.courtlistener.com/opinion/2035778/', '2035778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that, whichever formulation is used, the error of admitting the images and videos we have described in ¶ 40 was harmless.', 'general', 'State v. Normington', 'https://www.courtlistener.com/opinion/2035778/', '2035778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the circuit court did not erroneously exercise its discretion in admitting the images and videos showing the insertion of objects into persons'' anuses or testimony of the names of apparently related websites.', 'general', 'State v. Normington', 'https://www.courtlistener.com/opinion/2035778/', '2035778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that certain of the pornography was properly admissible for this purpose, we do not consider whether it might also he relevant for other purposes the State advances.', 'general', 'State v. Normington', 'https://www.courtlistener.com/opinion/2035778/', '2035778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'State v. Normington', 'https://www.courtlistener.com/opinion/2035778/', '2035778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the admission of other acts evidence is committed to the circuit court''s discretion, we affirm the decision on appeal if the circuit court reviewed the relevant facts, applied a proper standard of law, and, using a rational process, reached a reasonable conclusion.', 'general', 'State v. Normington', 'https://www.courtlistener.com/opinion/2035778/', '2035778') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Examining the Rodriguez bifurcated trial process in felony DUI prosecutions in light of Gaudin, we hold that in this bifurcated process the jury, not the judge, must determine the verdict from the evidence presented in the second phase.', 'general', 'State v. Harbaugh', 'https://www.courtlistener.com/opinion/1133557/', '1133557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1996), we held that in order to establish the crime of felony DUI there be: (1) a conviction of the current misdemeanor DUI;', 'general', 'State v. Harbaugh', 'https://www.courtlistener.com/opinion/1133557/', '1133557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Brown, this Court held that the State''s burden of proof as to the element of being a convicted felon (in a prosecution for possession of a firearm by a convicted felon) could be satisfied by a defendant''s stipulation that must be accepted by the trial court.', 'general', 'State v. Harbaugh', 'https://www.courtlistener.com/opinion/1133557/', '1133557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if a defendant charged with felony DUI elects to be tried by jury, the court shall conduct a jury trial on the elements of the single [present] incident of DUI at issue without allowing the jury to learn of the alleged prior [misdemeanor] DUI offenses.', 'general', 'State v. Harbaugh', 'https://www.courtlistener.com/opinion/1133557/', '1133557') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, as applied to these three defendants, the portions of the stalking statutes dealing with public encounters are constitutional.', 'general', 'Petersen v. State', 'https://www.courtlistener.com/opinion/1452672/', '1452672') ON CONFLICT DO NOTHING;
