INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As explained below, we conclude that the statutes do not violate the Constitution, and thus we affirm the defendants’ convictions.', 'general', 'Petersen v. State', 'https://www.courtlistener.com/opinion/1452672/', '1452672') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Peterson was under court order to have no contact with his victim, and because he does not challenge the lawfulness of this condition of probation, we conclude that Petersen had no constitutional right to knowingly approach or follow R.', 'general', 'Petersen v. State', 'https://www.courtlistener.com/opinion/1452672/', '1452672') ON CONFLICT DO NOTHING;
