INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Kuntz, this court held that the use of a jury instruction containing a mandatory conclusive presumption on an elemental fact was constitutional error, but the error nevertheless was subject to application of the harmless error rule.', 'jury_instruction', 'State v. Harvey', 'https://www.courtlistener.com/opinion/1296567/', '1296567') ON CONFLICT DO NOTHING;
