INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court.', 'general', 'State v. Harris', 'https://www.courtlistener.com/opinion/901944/', '901944') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having examined the indictments and the underlying facts of each conviction, we conclude that defendant’s conviction and sentencing on three counts of discharging a firearm into occupied property did not violate double jeopardy principles.', 'sentencing', 'State v. Rambert', 'https://www.courtlistener.com/opinion/1207849/', '1207849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the Court of Appeals on the issue of defendant’s three convictions for discharging a firearm into occupied property and remand to that court for remand to the trial court for reinstatement of the judgments.', 'general', 'State v. Rambert', 'https://www.courtlistener.com/opinion/1207849/', '1207849') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the “incredible dubiosity” rule is not applicable.', 'general', 'Gregory v. State', 'https://www.courtlistener.com/opinion/2036258/', '2036258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these questions did not amount to misconduct, let alone fundamental error.', 'general', 'Gregory v. State', 'https://www.courtlistener.com/opinion/2036258/', '2036258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that these comments amount to nothing more than the prosecutor’s opinion that methamphetamine has disastrous effects on the community.', 'general', 'Gregory v. State', 'https://www.courtlistener.com/opinion/2036258/', '2036258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm the conviction and sentence for Dealing Methamphetamine and remand with instructions to vacate the conspiracy conviction.', 'sentencing', 'Gregory v. State', 'https://www.courtlistener.com/opinion/2036258/', '2036258') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'established Sutton understood the nature of the charge, we affirm his conviction.', 'general', 'State of Iowa v. Walter Scott Sutton', 'https://www.courtlistener.com/opinion/2687964/', '2687964') ON CONFLICT DO NOTHING;
