INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that for someone to be
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶ 12 After review of other statutes found in title 13, chapter 28, as well as their predecessor statutes and related ease authority, we conclude that according “induce” its common meaning would not nullify the legislature’s reference to “a person [a defendant] believes may be called as a witness.', 'general', 'State v. Gray', 'https://www.courtlistener.com/opinion/2458787/', '2458787') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we hold that the reasoning set forth in Samson controls our analysis of the instant case.', 'general', 'People v. Wilson', 'https://www.courtlistener.com/opinion/2036430/', '2036430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Moss, we held that the search condition puts the parolee “on notice that law enforcement officials may ask his consent to search his ‘person, property, or residence ***’ *** with or without reasonable suspicion.', 'general', 'People v. Wilson', 'https://www.courtlistener.com/opinion/2036430/', '2036430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The Court then held, “Examining the totality of the circumstances pertaining to petitioner’s status as a parolee, ‘an established variation on imprisonment,’ [citation] including the plain terms of the parole search condition, we conclude that petitioner did not have an expectation of privacy that society would recognize as legitimate.', 'general', 'People v. Wilson', 'https://www.courtlistener.com/opinion/2036430/', '2036430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the parole systems of Illinois and California are very much alike in operation.', 'general', 'People v. Wilson', 'https://www.courtlistener.com/opinion/2036430/', '2036430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we find that any “special protection” afforded to defendant’s residence was lost when he became a parolee and agreed to consent to a search of his residence in his MSR agreement.', 'general', 'People v. Wilson', 'https://www.courtlistener.com/opinion/2036430/', '2036430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons that follow, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Wilson', 'https://www.courtlistener.com/opinion/2036430/', '2036430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Also, because we reverse the judgment of the appellate court, we need not consider defendant’s request for cross-relief.', 'general', 'People v. Wilson', 'https://www.courtlistener.com/opinion/2036430/', '2036430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we reverse the judgment of the appellate court and affirm the judgment of the circuit court.', 'general', 'People v. Wilson', 'https://www.courtlistener.com/opinion/2036430/', '2036430') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that under the set of circumstances presented in this appeal, the power to revoke probation is not so limited.', 'general', 'State v. Darrin', 'https://www.courtlistener.com/opinion/1576760/', '1576760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'indicated that this information would ordinarily concern renewed criminal conduct of the defendant, we conclude that if the defendant fraudulently conceals information from the sentencing court that may have significantly influenced the trial court not to grant the probation, the court does not abuse its discretion in revoking the probation.', 'sentencing', 'State v. Darrin', 'https://www.courtlistener.com/opinion/1576760/', '1576760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We granted discretionary review of the district court’s order revoking the defendant’s probation and, after careful consideration, we affirm.', 'general', 'State v. Darrin', 'https://www.courtlistener.com/opinion/1576760/', '1576760') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that regardless of whether the court erred by referencing an exhibit not formally entered at the contempt hearing, the passing reference to the unadmitted portions was harmless.', 'general', 'Reis v. Iowa District Court for Polk County', 'https://www.courtlistener.com/opinion/2122402/', '2122402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d at 783 (“In sum, although the court lacked power to impose new discovery-related obligations after dismissing the case on the merits, we find that, because the protective order was still in effect, the district court had the power to make postjudgment modifications to the protective order in light of changed circumstances.', 'dismissal', 'Reis v. Iowa District Court for Polk County', 'https://www.courtlistener.com/opinion/2122402/', '2122402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the district court’s finding that Reis be held in contempt.', 'general', 'Reis v. Iowa District Court for Polk County', 'https://www.courtlistener.com/opinion/2122402/', '2122402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we affirm the availability of reasonable expenses and fees as sanctions, we limit portions of the district court’s order based on our holding above.', 'general', 'Reis v. Iowa District Court for Polk County', 'https://www.courtlistener.com/opinion/2122402/', '2122402') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we find that the trial court did not err in denying appellant’s motion to suppress.', 'suppression', 'Jackson v. Commonwealth', 'https://www.courtlistener.com/opinion/1067945/', '1067945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding no error, we affirm.', 'general', 'Jackson v. Commonwealth', 'https://www.courtlistener.com/opinion/1067945/', '1067945') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm unless discretion has been abused.', 'general', 'State v. Pappas', 'https://www.courtlistener.com/opinion/1760766/', '1760766') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court''s ruling is rooted in an overly broad reading of Boice and find that swallowing an object clearly constitutes altering, destroying, concealing, or removing a "thing" within the meaning of section 918.', 'general', 'State v. Jennings', 'https://www.courtlistener.com/opinion/1094709/', '1094709') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the procedures required by our rules and the United States and Arizona Constitutions have been met in the instant case.', 'general', 'State v. Castaneda', 'https://www.courtlistener.com/opinion/1211486/', '1211486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Additionally, we find that Michael suffered physically as well.', 'general', 'State v. Castaneda', 'https://www.courtlistener.com/opinion/1211486/', '1211486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we find that imposition of the death penalty is proportional to the penalties imposed in similar eases.', 'general', 'State v. Castaneda', 'https://www.courtlistener.com/opinion/1211486/', '1211486') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the no-knock provision of the search warrant was valid, the item descriptions were adequate, and appellant’s seizure under the law of war-rantless arrests was constitutional.', 'general', 'Lobatos v. State', 'https://www.courtlistener.com/opinion/2612913/', '2612913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since we have never before considered the issue, we hold that the standard of review in considering whether a no-knock search warrant was properly issued is similar to our review of whether there was probable cause to issue a search warrant.', 'probable_cause', 'Lobatos v. State', 'https://www.courtlistener.com/opinion/2612913/', '2612913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we do not consider the application of these cases since we find that this warrant properly permitted an entry without announcement based on the affidavit’s contents describing the quantity and nature of the property and the circumstances surrounding its possession.', 'general', 'Lobatos v. State', 'https://www.courtlistener.com/opinion/2612913/', '2612913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Lobatos v. State', 'https://www.courtlistener.com/opinion/2612913/', '2612913') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the juvenile court could order DNA tests and the results of those tests could be used after the juveniles passed their eighteenth birthdays.', 'general', 'In Re Appeal in Maricopa County Juvenile Action No. JV-132744', 'https://www.courtlistener.com/opinion/1375387/', '1375387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We disagree, and we affirm.', 'general', 'In Re Appeal in Maricopa County Juvenile Action No. JV-132744', 'https://www.courtlistener.com/opinion/1375387/', '1375387') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'From the record before us, we conclude that it did not.', 'general', 'State v. Womack', 'https://www.courtlistener.com/opinion/2615023/', '2615023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the foregoing reasons, we find that defendant''s nonviolent flight constituted an insufficient factual basis upon which to charge defendant with resisting arrest.', 'general', 'State v. Womack', 'https://www.courtlistener.com/opinion/2615023/', '2615023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find the legislature did not intend to proscribe defendant''s conduct under the resisting arrest statute, we reverse defendant''s conviction on that count and remand to the trial court with directions to dismiss the charge of resisting arrest.', 'dismissal', 'State v. Womack', 'https://www.courtlistener.com/opinion/2615023/', '2615023') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finally, we hold that there is a legal basis for assessments to the Hillsborough County Drug Fund in cases involving drug offenses.', 'general', 'Reyes v. State', 'https://www.courtlistener.com/opinion/1730302/', '1730302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In order to review the trial court''s discretion in this area and to prevent these costs from being perceived as an extra charge for the privilege of probation on a withheld sentence, we hold that such a condition of probation must be imposed with the same procedures used to impose the costs of prosecution against convicted defendants.', 'sentencing', 'Reyes v. State', 'https://www.courtlistener.com/opinion/1730302/', '1730302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To avoid confusion, we hold that a reference to section 939.', 'general', 'Reyes v. State', 'https://www.courtlistener.com/opinion/1730302/', '1730302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that section 948.', 'general', 'Reyes v. State', 'https://www.courtlistener.com/opinion/1730302/', '1730302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the reference to the "Hillsborough County Drug Fund" is a sufficient description to adequately substitute for a statutory citation in this case.', 'general', 'Reyes v. State', 'https://www.courtlistener.com/opinion/1730302/', '1730302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the denial of the motion to suppress evidence.', 'suppression', 'Reyes v. State', 'https://www.courtlistener.com/opinion/1730302/', '1730302') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), Division One of this court held that a driver of a car traveling at least fifty miles per hour out of which a passenger deliberately leapt was " ''involved in an accident,’ ” but that inquiry focused on the statutory meaning of “accident.', 'general', 'State v. Korovkin', 'https://www.courtlistener.com/opinion/2521303/', '2521303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Korovkin', 'https://www.courtlistener.com/opinion/2521303/', '2521303') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In conclusion, we hold that there is no duty to retreat from the residence before resorting to deadly force against a co-occupant or invitee if necessary to prevent death or great bodily harm, although there is a limited duty to retreat within the residence to the extent reasonably possible.', 'general', 'Weiand v. State', 'https://www.courtlistener.com/opinion/1101329/', '1101329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In refusing to extend the privilege of nonretreat in Bobbitt, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nonetheless, we conclude that Justice Overton''s "middle ground" instruction, as set forth in his dissent in Bobbitt, 415 So.', 'general', 'Weiand v. State', 'https://www.courtlistener.com/opinion/1101329/', '1101329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Second, based on our increased understanding of the plight of victims of domestic violence in the years since our decision in Bobbitt, we find that there are sound policy reasons for not imposing a duty to retreat from the residence when a defendant resorts to deadly force in self-defense against a co-occupant.', 'general', 'Weiand v. State', 'https://www.courtlistener.com/opinion/1101329/', '1101329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the same reason, we find that in circumstances where the nonretreat instruction is applicable, the instructions are incomplete and misleading if the nonretreat instruction is not given.', 'general', 'Weiand v. State', 'https://www.courtlistener.com/opinion/1101329/', '1101329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we find that the Second District erred by concluding that the exclusion of the witnesses was harmless beyond a reasonable doubt.', 'general', 'Weiand v. State', 'https://www.courtlistener.com/opinion/1101329/', '1101329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We found that the instructions were incomplete because, without the privilege of nonretreat instruction, the jury may have believed that the defendant had a duty to retreat from her home.', 'general', 'Weiand v. State', 'https://www.courtlistener.com/opinion/1101329/', '1101329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '5th DCA 1996), in which this court held that petit theft was a necessarily lesser included offense of fraudulent use of a credit card.', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1101310/', '1101310') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that robbery, a second-degree felony, is a necessarily lesser included offense of carjacking.', 'general', 'Fryer v. State', 'https://www.courtlistener.com/opinion/1101310/', '1101310') ON CONFLICT DO NOTHING;
