INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the jury’s verdict.', 'general', 'State v. Roberts', 'https://www.courtlistener.com/opinion/1069005/', '1069005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we affirm the jury’s verdict on the disorderly conduct charge.', 'general', 'State v. Roberts', 'https://www.courtlistener.com/opinion/1069005/', '1069005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the jury’s decision to find Mr.', 'general', 'State v. Roberts', 'https://www.courtlistener.com/opinion/1069005/', '1069005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the decision of the trial court.', 'general', 'State v. Roberts', 'https://www.courtlistener.com/opinion/1069005/', '1069005') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that the affidavit charging Johnson with indecent exposure was sufficient.', 'general', 'Johnson v. State', 'https://www.courtlistener.com/opinion/1104035/', '1104035') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that it is entirely proper under our law that the same jurors who hear the guilt phase remain and continue to serve as the jurors at the sentencing phase of a capital murder trial.', 'sentencing', 'Jones v. State', 'https://www.courtlistener.com/opinion/1104481/', '1104481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, given the facts recited above, the arrest of Jones by Perry County Constable Barnes based upon a misdemeanor committed in his presence was lawful.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1104481/', '1104481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that all of the statements made by Jones to the Biloxi law enforcement officials on January 21, 1981, after Jones said "I prefer not to speak on that" were unlawfully secured.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1104481/', '1104481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1981), wherein we held that, to effect a lawful arrest of a misdemeanant, an officer must either be present as a witness to the offense or have an arrest warrant prior to the arrest.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1104481/', '1104481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1973), this Court held that a defendant in a drug possession case
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Jones'' conviction of capital murder and remand for a new trial.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1104481/', '1104481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" We affirm the conviction of Hughes.', 'general', 'Jones v. State', 'https://www.courtlistener.com/opinion/1104481/', '1104481') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, on this issue, we reverse and remand for resentencing.', 'sentencing', 'Pierce v. State', 'https://www.courtlistener.com/opinion/1105871/', '1105871') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that the evidence was insufficient to support a conviction of perjury, we reverse and render on that count, but affirm the conviction of conspiracy.', 'general', 'Smallwood v. State', 'https://www.courtlistener.com/opinion/1106155/', '1106155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that, even when taking the evidence in a light most favorable to the State, the prosecution failed to make out a prima facie case of perjury.', 'general', 'Smallwood v. State', 'https://www.courtlistener.com/opinion/1106155/', '1106155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering all the evidence most favorably to the State, we find that the lower court properly allowed the question of conspiracy to go the jury.', 'general', 'Smallwood v. State', 'https://www.courtlistener.com/opinion/1106155/', '1106155') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[19] Based on the legislative history and, more important, on *927 the fact that the statute refers specifically to the definition of intimate partners in the domestic assault statute, we hold that "misdemeanor offense involving intimate partners," within the meaning of § 29-1207(2), does not encompass any and all misdemeanors in which intimate partners may be engaged.', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2119966/', '2119966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the exception does not apply;', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2119966/', '2119966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State did not bring Lebeau to trial within the required time and that she is entitled to absolute discharge.', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2119966/', '2119966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the State did not bring Lebeau to trial within the required time and that the county court and district court erred in finding otherwise.', 'general', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2119966/', '2119966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'therefore, we reverse the judgment of the district court and remand the cause with directions to dismiss the complaint against Lebeau.', 'dismissal', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2119966/', '2119966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the lower courts'' orders denying Lebeau''s motion for absolute discharge and remand the matter to the district court with directions to reverse the judgment of the county court and remand the cause with directions to dismiss the complaint against Lebeau.', 'dismissal', 'State v. Lebeau', 'https://www.courtlistener.com/opinion/2119966/', '2119966') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Title 11''s definition of "serious physical injury" applies to AS 25.', 'general', 'Parks v. Parks', 'https://www.courtlistener.com/opinion/2628853/', '2628853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the automatic change provision was not in their daughter''s best interests and that entering it was therefore an abuse of discretion.', 'general', 'Parks v. Parks', 'https://www.courtlistener.com/opinion/2628853/', '2628853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm in part, vacate in part, and remand, because further factual findings are necessary to determine whether subsection .', 'general', 'Parks v. Parks', 'https://www.courtlistener.com/opinion/2628853/', '2628853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We AFFIRM in part, VACATE in part, and REMAND for further proceedings in accordance with this opinion.', 'general', 'Parks v. Parks', 'https://www.courtlistener.com/opinion/2628853/', '2628853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'factfinding, we affirm.', 'general', 'Boyd v. County of Henrico', 'https://www.courtlistener.com/opinion/1063916/', '1063916') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with the Fourth District''s decision, we find that petitioner''s arguments fail to overcome the presumption of constitutionality which applies.', 'general', 'Sieniarecki v. State', 'https://www.courtlistener.com/opinion/1110143/', '1110143') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that the deficiencies in the trial court’s instruction in this case do not warrant reversal of defendant’s convictions.', 'general', 'State v. Stevens', 'https://www.courtlistener.com/opinion/2277492/', '2277492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Stevens', 'https://www.courtlistener.com/opinion/2277492/', '2277492') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the offense of use of a firearm in the commission of second degree murder in violation of HRS § 134-6(a) is not an included offense[4] of second degree murder in violation of HRS § 707-701.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, because (1) theft is an element of first degree robbery, (2) a defendant cannot commit first degree robbery without committing theft or attempted theft, and (3) attempted theft is an included offense of theft, see HRS § 701-109(4)(b), we hold that theft and attempted theft, regardless of degree, are included offenses of first degree robbery.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Vinge, we held that theft and attempted theft are included offenses of robbery in the first degree.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '[5]  Although Jumila entered pleas of no contest to the second degree murder and HRS § 134-6(a) charges, because he raised the HRS § 701-109 argument at his sentencing hearing, before judgment was entered, and because the prosecution has never contended that Jumila should be precluded from raising the argument, we conclude that Jumila did not waive his HRS § 701-109 rights when he entered his no contest pleas.', 'sentencing', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 1210, 1219-20 (1996), wherein we concluded that the offenses of "theft and attempted theft, regardless of degree, are included offenses of first degree robbery.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, in order to remedy the HRS § 701-109 violation, we reverse Jumila''s conviction and sentence on the HRS § 134-6(a) charge.', 'sentencing', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed both convictions.', 'general', 'State v. Jumila', 'https://www.courtlistener.com/opinion/1111240/', '1111240') ON CONFLICT DO NOTHING;
