INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the judgment of the trial court.', 'general', 'State of Tennessee v. Paul H. Clever', 'https://www.courtlistener.com/opinion/1076105/', '1076105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the "independent source" exception does not apply, and remand the case for consideration of the "inevitable discovery" exception, as formulated herein.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the opening of the suitcase without a warrant was an unconstitutional search, and that the drugs found in the suitcase had to be suppressed under the exclusionary rule.', 'suppression', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 357 (Alaska 1990), this court held that the exclusionary rule applies to evidence procured in violation of AS 12.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if the prosecution can show, by clear and convincing evidence, that illegally obtained evidence would have been discovered through predictable investigative processes, such evidence need not be suppressed as long as the police have not knowingly or intentionally violated the rights of the accused in obtaining that evidence.', 'suppression', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal we affirmed.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because there was a causal relationship between the warrants and the prior felony convictions, we hold that Perencevic’s detention for his alleged supervision violation was “pursuant to a conviction of a felony.', 'general', 'State v. Stores', 'https://www.courtlistener.com/opinion/1115293/', '1115293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the term “official detention for a felony” in the second-degree escape statute was intended to encompass detention based on parole warrants for parole violations.', 'general', 'State v. Stores', 'https://www.courtlistener.com/opinion/1115293/', '1115293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Despite the fact that the history of the escape statute is somewhat complicated, we conclude that no ambiguity exists as to the core meaning of the statute.', 'general', 'State v. Stores', 'https://www.courtlistener.com/opinion/1115293/', '1115293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the judge erred in finding that the escape statute was unconstitutionally vague.', 'general', 'State v. Stores', 'https://www.courtlistener.com/opinion/1115293/', '1115293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Stores', 'https://www.courtlistener.com/opinion/1115293/', '1115293') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the imposition of court costs and remand.', 'general', 'Lawton v. State', 'https://www.courtlistener.com/opinion/1115747/', '1115747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the imposition of court costs on the appellants and remand for further action in accordance with this opinion, including a hearing on the issue of indigency, pursuant to notice, and issuing appropriate orders thereon.', 'general', 'Lawton v. State', 'https://www.courtlistener.com/opinion/1115747/', '1115747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, in the absence of a showing by the prosecutor under Criminal Rule 16(d)(6), the court should have allowed discovery of the report.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the court should have allowed discovery of the report brought in by the prosecutor.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a finding that the victim was particularly vulnerable under AS 12.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Since the finding of vulnerability in this case was based solely upon an environmental factor, we hold that the court erred in concluding that the aggravator in 12.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we conclude that accepting the defense stipulation would have been the preferable procedure, we conclude that any error in allowing the testimony on how the photograph was obtained did not appreciably effect the jury''s verdict and was harmless error.', 'general', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the conviction, but find it necessary to remand for further sentencing proceedings.', 'sentencing', 'Braaten v. State', 'https://www.courtlistener.com/opinion/1116080/', '1116080') ON CONFLICT DO NOTHING;
