INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this search violated Chapter I, Article 11, of the Vermont Constitution, and accordingly reverse.', 'general', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/2202269/', '2202269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On these facts, we find that the officers'' walk over defendant''s logging roads and through his woods violated his right to privacy under Article 11, and the evidence obtained thereby may not be used against him.', 'general', 'State v. Kirchoff', 'https://www.courtlistener.com/opinion/2202269/', '2202269') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the exemption of the Board''s hearing procedures from the WAPA does not evidence an intent to preclude judicial review of the Board''s revocation decisions.', 'general', 'Pisano v. Shillinger', 'https://www.courtlistener.com/opinion/1118592/', '1118592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Looking beyond our own jurisdiction, we find that appellate review of parole decisions is nothing new or radical.', 'general', 'Pisano v. Shillinger', 'https://www.courtlistener.com/opinion/1118592/', '1118592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'Pisano v. Shillinger', 'https://www.courtlistener.com/opinion/1118592/', '1118592') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the ITIA violates neither the Federal nor the Idaho Constitution.', 'general', 'State v. Bennion', 'https://www.courtlistener.com/opinion/1118922/', '1118922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Taking into account the universal right under territorial law to a jury trial whenever imprisonment threatened, the fact that imprisonment distinguishes criminal sanction, and the ardent desire of the Framers to interpose juries on the road to the prison cell, we conclude that Article 1, § 7 guarantees a jury trial whenever the possible sanction includes imprisonment.', 'general', 'State v. Bennion', 'https://www.courtlistener.com/opinion/1118922/', '1118922') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" In the Smith case we held that a transcript of a conviction which does not show on its face that counsel was afforded or the right waived cannot be used as proof of the prior conviction in accordance with the rule set forth in Baldasar v.', 'general', 'State v. Gonzales', 'https://www.courtlistener.com/opinion/2170735/', '2170735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As this court held with regard to a search warrant in State v.', 'general', 'State v. Gonzales', 'https://www.courtlistener.com/opinion/2170735/', '2170735') ON CONFLICT DO NOTHING;
