INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'McNair, supra, this court held that it was not cruel or unusual to impose a life sentence pursuant to A.', 'sentencing', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
