INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Assuming without deciding that a presumption of prosecutorial vindictiveness was triggered in this case, we conclude that the presumption has been rebutted, at least on the facts of this case.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Mulalley, supra, we concluded that there was a rational basis for the imposition of this same sentence for dangerous assaults by prisoners while in custody.', 'sentencing', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the absence of any prejudice, we find that the error in the indictment was a technical defect amendable upon the state''s motion under 17 A.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As to the gravity of the offense, we find that appellant''s crimes were very serious.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 225, 227 (1971), we found that Miranda warnings could be renewed at an interrogation two hours after the original warnings by asking the accused if he had been advised of his constitutional rights.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Noriega', 'https://www.courtlistener.com/opinion/1173427/', '1173427') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in syllabus point 8 of State v.', 'general', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Therefore, we conclude that the trial court’s *524sentence for such a crime does not shock the conscience.', 'sentencing', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we find that the sentence in this case does not violate the proportionality principle found in Article III, Section 5 of the State Constitution.', 'sentencing', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon a review of the parties’ arguments and the record, we affirm the circuit court.', 'general', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In view of the foregoing, we affirm the circuit court’s sentencing order of 15 to 35 years in the penitentiary.', 'sentencing', 'State v. Goff', 'https://www.courtlistener.com/opinion/1239191/', '1239191') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Following a review of the parties’ arguments, the record of the proceedings below, and the pertinent authorities, we affirm the decision of the Circuit Court of Harrison County.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Hence, we affirm the decision of the Circuit Court of Harrison County as our law clearly concludes that prior shoplifting convictions are an element of third offense shoplifting.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm the conviction and sentence.', 'sentencing', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 317 (1994), this Court held that prior shoplifting convictions are elements of the crime of third-offense shoplifting, and are therefore admissible before the jury.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In footnote 1 of Cozart, this Court held that previous convictions of driving under the influence of alcohol are admissible to show the defendant is currently guilty of a third offense of driving under the influence of alcohol.', 'general', 'State v. Morris', 'https://www.courtlistener.com/opinion/1239281/', '1239281') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'stated: “We hold that Alaska’s constitutional prohibition against double jeopardy prevents one from receiving multiple punishment for the same offense.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in reaching this decision.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that evidence of the fact that the phone calls were made was relevant.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not err in applying Criminal Rule 16(f)(3) to hold that Hohman had forfeited his right to raise the privacy issue by not bringing the motion until the middle of trial.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not abuse its discretion in giving the instruction.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that giving this intent instruction was not plain error.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, although the evidence appears to have been admissible if the theory which Hohman has argued in this court had been argued in the trial court, on this record the alleged error has not been preserved.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, the possible prejudice from this line of questioning is so limited that we conclude that any error in allowing this questioning was harmless.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the state adequately showed the relevance of the questions asked.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Hohman’s two convictions are not the same for double jeopardy purposes and Judge Serdahely did not err in imposing consecutive fines.', 'general', 'Hohman v. State', 'https://www.courtlistener.com/opinion/1177145/', '1177145') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'While we hold that recklessness regarding the consequences was the required culpable mental state for reckless murder, we conclude that the instructions given adequately conveyed that idea to the jury.', 'general', 'Neitzel v. State', 'https://www.courtlistener.com/opinion/1177765/', '1177765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these circumstances, we conclude that “recklessly” governs the surrounding circumstances and the result in reckless murder.', 'general', 'Neitzel v. State', 'https://www.courtlistener.com/opinion/1177765/', '1177765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we find that assumption to be unsound and conclude that the legislature intended AS 11.', 'general', 'Neitzel v. State', 'https://www.courtlistener.com/opinion/1177765/', '1177765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” We therefore hold that the Revised Code sufficiently distinguishes between reckless murder and reckless manslaughter to satisfy equal protection.', 'general', 'Neitzel v. State', 'https://www.courtlistener.com/opinion/1177765/', '1177765') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that in this prosecution for criminal sexual conduct where the defendant claimed consent it was reversible error for an expert to testify concerning typical post-rape symptoms and behavior of rape victims and give opinions that the complainant was a victim of rape and had not fantasized the rape.', 'general', 'State v. Saldana', 'https://www.courtlistener.com/opinion/1580100/', '1580100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the admission of Dreyer''s testimony was error.', 'general', 'State v. Saldana', 'https://www.courtlistener.com/opinion/1580100/', '1580100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the admission of such testimony requires the reversal of appellant''s conviction, and we remand for a new trial.', 'general', 'State v. Saldana', 'https://www.courtlistener.com/opinion/1580100/', '1580100') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse appellant''s conviction and remand for a new trial.', 'general', 'State v. Saldana', 'https://www.courtlistener.com/opinion/1580100/', '1580100') ON CONFLICT DO NOTHING;
