INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these facts we conclude that the media was not acting as an agent for the police, and therefore should be treated as any other private citizen who conducts an interview with a defendant.', 'general', 'Sears v. State', 'https://www.courtlistener.com/opinion/2038470/', '2038470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court properly admitted the videotaped interviews that defendant gave to the news media.', 'general', 'Sears v. State', 'https://www.courtlistener.com/opinion/2038470/', '2038470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We Affirm.', 'general', 'Sears v. State', 'https://www.courtlistener.com/opinion/2038470/', '2038470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '¶28          For these reasons, we affirm in part and vacate in part the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the defendant’s trial was free of reversible error.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it was, and that it was properly admitted by the trial court.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although the evidence indicated that the incident with Foster occurred some ten weeks after the incident with the victim in this case, we conclude that the remarkably odd and strikingly similar licking modus operandi attributed to the defendant by both women rendered Foster’s testimony relevant and admis*208sible as tending to prove the defendant’s modus operandi, motive, intent, preparation and plan.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, for the limited purposes for which the contested evidence was admitted here, the incident with Foster was not so remote that evidence of it should have been excluded under the Rule 403 balancing test.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court did not err in the present case by admitting the testimony of Foster concerning the defendant’s similar crime, wrong, or act against her.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the evidence presented in this case, we conclude that the trial court did not err by failing to instruct on attempted first-degree sexual offense.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the quoted portions of the instructions did not mislead the jury.', 'general', 'State v. Bagley', 'https://www.courtlistener.com/opinion/1239950/', '1239950') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Since the only evidence to support that instruction was derived from the test performed at the hospital, we hold that the instruction constituted prejudicial error in the trial of the drunken driving charge.', 'general', 'Essex v. Commonwealth', 'https://www.courtlistener.com/opinion/1319724/', '1319724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, we conclude that this evidence, though probative, raised no legal presumption of intoxication.', 'general', 'Essex v. Commonwealth', 'https://www.courtlistener.com/opinion/1319724/', '1319724') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'At any event, whether Frye is the rule to be applied to a new or controversial scientific technique is not one we are called upon to decide since we conclude that the method by which testimony is hypnotically induced is not one that falls within the ambit of Frye.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1695329/', '1695329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Returning to the first three problem areas that are inherent in the process of hypnosis: hypersuggestiveness, hypercompliance, and confabulation, we find that commentators generally approve the following safeguards to reduce the potentiality of prejudice.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1695329/', '1695329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it was error for the lower court to deny the appellant''s request for a cautionary jury instruction, although the particular instruction as requested was only a partially complete statement of the law.', 'jury_instruction', 'Brown v. State', 'https://www.courtlistener.com/opinion/1695329/', '1695329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse, however, the convictions of uttering a forged instrument and commission of grand theft, and remand those offenses to the lower court for further consistent proceedings.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1695329/', '1695329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the above two convictions and remand for a new trial for the reasons stated.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1695329/', '1695329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that there is substantial and competent evidence supporting the verdict for the offense of forgery, we affirm it.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1695329/', '1695329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the conviction of forgery.', 'general', 'Brown v. State', 'https://www.courtlistener.com/opinion/1695329/', '1695329') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the complaint in the case was defective because it did not charge and describe an offense, and that prosecution under the complaint was a violation of Lopez'' due process rights under Art.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, under the authority of McMahan, we hold that it is a violation of the due process clause of Art.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the complaint under which the accused was convicted did not state an offense and that the conviction of the defendant Lopez under this complaint was a violation of her rights under Art.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We do not, however, reach the issue of the effectiveness of the complaint since we hold that the statute is void-for-vagueness and violates appellant''s constitutional right to due process of law.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in State v.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In McMahan this Court held that putting the defendant on trial without setting forth in the information the acts constituting the offense for which he was charged was a violation of the due process clause of Art.', 'general', 'State v. Lopez', 'https://www.courtlistener.com/opinion/1186893/', '1186893') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the district court erred when it denied Askerooth’s motion to suppress the methamphetamine discovered in the back seat of Schmidt’s squad car.', 'suppression', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Schmidt’s request for Askerooth’s consent to search the van exceeded the scope of the stop and his prolonged detention of Askerooth beyond the time necessary to effectuate the purpose of the stop violated Article I, Section 10 of the Minnesota Constitution.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ''' Consequently, we held that article I, section 10 required police to have an “objective individualized articula-ble suspicion of criminal wrongdoing before subjecting a driver to an investigative stop.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, in the context of traffic stops, following Atwater’s proposition that the existence of probable cause of a minor traffic violation eliminates the need for balancing individual and governmental interests would threaten the integrity and coherence of our interpretation of article I, section 10 in Fort.', 'probable_cause', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Nevertheless, we conclude that the lack of a driver’s license, by itself, is not a reasonable basis for confining a driver in a squad car’s locked back seat _ when the driver is stopped for a minor traffic offense.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '- We conclude that Askerooth’s interest in being free from unreasonable seizure in these circumstances outweighed Schmidt’s need for convenience because obtaining Askerooth’s name, date of birth, and address did not require confinement in Schmidt’s squad car.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we conclude that it was unreasonable to place Askerooth in the squad car for convenience purposes and, though it would have been permissible to order Askerooth out of the van, the act of ordering Aske-rooth out of the van, standing alone, did not justify confining him in the squad car.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that, based on the facts presented to us, a reasonable person in Schmidt’s position would not conclude that confinement of Askerooth in the squad car was necessary either to effectuate the original purposes of the stop or for officer safety.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Askerooth’s abandoning of the methamphetamine is the result of an illegal seizure, we conclude that the methamphetamine must be suppressed.', 'suppression', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Fort, we concluded that article I, section 10 requires an officer to have reasonable articu-lable suspicion to expand the scope of a routine traffic stop in order to investigate other matters unrelated to the reason for the stop and to request consent to search.', 'general', 'State v. Askerooth', 'https://www.courtlistener.com/opinion/2038777/', '2038777') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*752 We held that, because Steve was attacking his conviction on a legal ground that did not require resolution of any of the facts of the case, his pleading was not a "motion for judgement of acquittal", and the granting of his motion would not preclude the State from re-trying him:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Souter did not abuse his discretion when he permitted that testimony over Collins''s objection.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this issue was waived.', 'general', 'Collins v. State', 'https://www.courtlistener.com/opinion/1187747/', '1187747') ON CONFLICT DO NOTHING;
