INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s denial of Appellant’s motion for directed verdict.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1403698/', '1403698') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the trial court’s ruling on this point.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/1403698/', '1403698') ON CONFLICT DO NOTHING;
