INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Yoder, we held that “[t]he description must be sufficiently clear so that the property to be searched is recognizable from other neighboring properties.', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 647 (1979), we held that a district court erred “in quashing a search warrant where the house to be searched was described by an erroneous house number, but was further identified by additional physical features contained in the warrant.', 'general', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
