INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 671 (1978), we affirmed a trial court’s suppression of evidence which was based, among other things, on the police officers’ failure to comply with the Idaho knock and announce statutes, I.', 'suppression', 'State v. Gomez', 'https://www.courtlistener.com/opinion/1241125/', '1241125') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Evans failed to prove the plain error exception to the invited error doctrine, we hold that the district court did not err by denying relief.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1241180/', '1241180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the district court did not abuse its discretion in limiting its review to the records from the May 5 visit.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1241180/', '1241180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the district court did not abuse its discretion in limiting Evans’s ability to cross-examine J.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1241180/', '1241180') ON CONFLICT DO NOTHING;
