INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Evans’s right to a fair trial was not violated because of the spark-of-life evidence presented about Vick.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1241180/', '1241180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the evidence was sufficient to show that Vick was on duty as a police officer when he was killed.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1241180/', '1241180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that the district court’s ruling was not erroneous and Frazer’s testimony did not deny Evans a fair trial.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1241180/', '1241180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the admission of Frazer''s statements was not error, we hold that Evans was not denied effective assistance of counsel.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1241180/', '1241180') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 301 (1960), we held that it was improper for litigants to have post-verdict contact with jurors for purposes of attaining information to be used to impeach the verdict.', 'general', 'State v. Evans', 'https://www.courtlistener.com/opinion/1241180/', '1241180') ON CONFLICT DO NOTHING;
