INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed.', 'general', 'Simmons v. State', 'https://www.courtlistener.com/opinion/1143735/', '1143735') ON CONFLICT DO NOTHING;
