INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Bouknight’s strategy regarding Jones amounts to deliberate withholding under § 22-4135(d) of the IPA, and that he therefore cannot satisfy an express prerequisite for relief under that statute.', 'general', 'Bouknight v. United States', 'https://www.courtlistener.com/opinion/1547524/', '1547524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even though we conclude that Bouk-night deliberately withheld any effort to get Jones’ testimony before the jury, the related issue of whether Jones’ statement constitutes “new evidence” under the IPA merits discussion.', 'general', 'Bouknight v. United States', 'https://www.courtlistener.com/opinion/1547524/', '1547524') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Bouknight v. United States', 'https://www.courtlistener.com/opinion/1547524/', '1547524') ON CONFLICT DO NOTHING;
