INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the statute is constitutional and that application of the rule of lenity is not appropriate, we reverse and remand.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1242313/', '1242313') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that fiduciary obligations may be, but are
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Given all of the evidence regarding respondent’s conduct introduced at the first trial, we conclude that a person in his position would have had substantial reason to believe that he was in a fiduciary relationship as stated in Minn.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1242313/', '1242313') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But we conclude that when there are joint bank accounts and a variety of other factors indicating a possible fiduciary relationship between a vulnerable adult and a person accused of misappropriating the vulnerable adult’s financial resources, Minn.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1242313/', '1242313') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the statute provides sufficient notice for an ordinary person to understand that, if he or she is in a fiduciary relationship with a vulnerable adult, he or she cannot spend the financial resources of the vulnerable adult on items unrelated to care or welfare of that adult without appropriate permission, especially when the items purchased principally benefit the fiduciary.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1242313/', '1242313') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the danger of arbitrary enforcement is speculative and insufficient to render the statute unconstitutionally vague as applied.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1242313/', '1242313') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consistent with our conclusion that the statute is drafted with sufficient definiteness to give defendants in respondent’s alleged position fair warning of the conduct prohibited, we conclude that the language of the statute is not sufficiently ambiguous to invoke the rule of lenity.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1242313/', '1242313') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'But because respondent failed to show that the statute is unduly vague as applied to respondent’s conduct and because the statute includes a mens rea requirement, we conclude that a lenity analysis is unwarranted in this case.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1242313/', '1242313') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1(1) (2002), is not unconstitutionally vague as applied to respondent’s conduct and because the rule of lenity is not applicable in this case, we reverse the decision of the district court.', 'general', 'State v. Campbell', 'https://www.courtlistener.com/opinion/1242313/', '1242313') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On this record, we conclude that a motion challenging the joinder of the drug/gun charges with the ADW/threats charges or a motion for severance would *1293 have lacked merit.', 'general', 'Howerton v. United States', 'https://www.courtlistener.com/opinion/1489294/', '1489294') ON CONFLICT DO NOTHING;
