INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that it was error to refuse the *302defendant’s request for an instruction advising the jury that defendant might be found guilty of a simple assault, as an included offense.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that since the jury refused to find defendant guilty of an offense next higher in degree to simple assault, it was apparent that had the instruction been given, the jury would not have found the defendant guilty of simple assault, and that therefore there was no reversible error.', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 976, this Court held that simple assault is an offense included in a charge of assault with intent to commit rape, but that error was not committed in refusing to instruct that the jury might find the accused guilty of simple assault in the absence of evidence which would tend to reduce the grade of the offense charged;', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that the charge included murder in the first and second degrees, and manslaughter;', 'general', 'State v. Anderson', 'https://www.courtlistener.com/opinion/1120223/', '1120223') ON CONFLICT DO NOTHING;
