INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Discerning neither reversible error nor abuse of discretion requiring reversal, we affirm the judgments of the trial court.', 'general', 'Kaliku v. United States', 'https://www.courtlistener.com/opinion/2049198/', '2049198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, for the foregoing reasons, we affirm the judgments of the trial court, but we remand the case with instructions to vacate the ADW convictions of both Mr.', 'general', 'Kaliku v. United States', 'https://www.courtlistener.com/opinion/2049198/', '2049198') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Even if it were, at this point, we hold that the Burk-Sanford precedent supersedes.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that felonious assault is, as the statute states, assault with a dangerous weapon.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that specific intent is not an element of felonious assault.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that Doud did not hold that an intent to injure or batter is required in every criminal assault case.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that they had been framed in the disjunctive and that either definition could stand alone.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"It is hereby ordered that defendant’s Proposed Instruction ''A’ be given, this court having ruled that, contrary to the Michigan Criminal Jury Instructions and Commentary with respect to the crime of felonious assault, specific intent to do bodily injury to the complainant is an element of the crime of felonious assault which the people must prove beyond a reasonable doubt.', 'jury_instruction', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Johnson and remand for a new trial and affirm the trial court’s decision in Ring as modified and remand for trial.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the decision of the trial court to give the "intent to do bodily injury” instruction and remand for instructions consistent with this opinion.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the trial court’s decision to give that instruction and remand for instructions consistent with this opinion.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the Court of Appeals in People v Johnson.', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '"As for defendant Neumayer, we affirm the circuit court’s reversal of his conviction because at the time he committed the conduct charged, this Court had not construed the statute per Miller [v California, 413 US 15;', 'general', 'People v. Joeseype Johnson', 'https://www.courtlistener.com/opinion/2049680/', '2049680') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As such, we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '6 Applying a plain-meaning approach to the word “force,” we found that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 We affirm its judgment because Finley used force
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we affirm the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we disagree with the Appellate Division’s resolution of defendant’s double jeopardy argument, we reverse the judgment below and reinstate the original three-to-five year aggregate custodial sentence.', 'sentencing', 'State v. Ryan', 'https://www.courtlistener.com/opinion/2050654/', '2050654') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we reverse the trial court’s 29 September 1999 judgment, we need not address Defendant’s additional assignments of error.', 'general', 'State v. Messer', 'https://www.courtlistener.com/opinion/1241806/', '1241806') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of these facts, we hold that the Liability Defendants’ waived any errors in the circuit court’s jury instructions regarding the theories of liability in Counts I, II and III by having failed to comply with HRAP Rule 28(b)(4)(B).', 'jury_instruction', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Likewise, we hold that the FIFRA did not preempt the Plaintiffs’ claims in Counts I and II alleging negligence and strict liability for the Liability Defendants’ defective manufacture or design of Benlate.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing justifications, we hold that EPA mandated warranties are preempted.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the FI-FRA did not preempt the Plaintiffs’ claim for breach of express warranty, and we affirm the circuit court’s order denying the Liability Defendants’ motion for partial summary judgment with respect to the Plaintiffs’ claim in Count III for breach of express warranty.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we hold that the circuit court did not, as a result of these two summary judgment orders, allow the jury to impose liability pursuant to claims that the FIFRA preempted.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the overwhelming and substantial evidence supporting the jury’s verdict, we hold that the cumulative effect of the three alleged errors did not deny the Liability Deféndants their constitutional right to a fair trial.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, under the circumstances of this case, it affirmatively appears from the record as a whole that DuPont and the other Liability Defendants did not suffer prejudice as a result of the circuit court’s inappropriate remedial jury instruction.', 'jury_instruction', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, although the circuit court abused its discretion through this particular sanction, we hold that the circuit court’s error was harmless.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that the superior court’s ruling did not constitute prejudicial error.', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, in light of the brevity of the improper reference to the Greenlight verdict by the Plaintiffs’ counsel during his opening argument, the seven-month duration of the trial, the circuit court’s instructions to the jury, and the overwhelming evidence in the record supporting the jury’s verdict, we hold that, although it was improper for the Plaintiffs’ counsel to refer to the verdict in Greenlight during opening statements, this reference did not constitute an occurrence of such charac...', 'general', 'Kawamata Farms, Inc. v. United Agri Products', 'https://www.courtlistener.com/opinion/1125042/', '1125042') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the “independent source” exception does not apply, and remand the case for consideration of the “inevitable discovery” exception, as formulated herein.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the opening of the suitcase without a warrant was an unconstitutional search, and that the drugs found in the suitcase had to be suppressed under the exclusionary rule.', 'suppression', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that if the prosecution can show, by clear and convincing evidence, that illegally obtained evidence would have been discovered through predictable investigative processes, such evidence need not be suppressed as long as the police have not knowingly or intentionally violated the rights of the accused in obtaining that evidence.', 'suppression', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On appeal we affirmed.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 357 (Alaska 1990), this court held that the exclusionary rule applies to evidence procured in violationof AS 12.', 'general', 'Smith v. State', 'https://www.courtlistener.com/opinion/1125135/', '1125135') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Storey, this Court held that “in the absence of circumstances which put a reasonable man on notice of impending danger, a driver on a dual highway with a green light in his favor has the right to assume that he could traverse the intersection safely and that cross traffic would *1051stop in obedience to the red light.', 'general', 'Bullock v. State', 'https://www.courtlistener.com/opinion/2050915/', '2050915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we REVERSE the judgment of the Superior Court and REMAND this case for a new trial.', 'general', 'Bullock v. State', 'https://www.courtlistener.com/opinion/2050915/', '2050915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '53 Under plain error review, we found that the “jury instructions were erroneous as a matter of law.', 'jury_instruction', 'Bullock v. State', 'https://www.courtlistener.com/opinion/2050915/', '2050915') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the foregoing principles, we hold that, in order to facilitate sentencing under Yarbough in vehicular homicide cases, the multiple-victims factor is entitled to great weight and should ordinarily result in the imposition of at least two consecutive terms when multiple deaths or serious bodily injuries have *430been inflicted upon multiple victims by the defendant.', 'sentencing', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we do not adopt a per se rule, we conclude that it was not an abuse of the trial court’s discretion to impose consecutive sentences.', 'sentencing', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Considering also that the trial court was in a far better position to develop a “feel of the case” than was the Appellate Division, we conclude that the Appellate Division should not have disturbed the trial court’s finding that defendant was likely to re-offend.', 'general', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the Appellate Division’s judgment and reinstate the trial court’s sentences.', 'sentencing', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the judgment of the Appellate Division and reinstate the trial court’s original sentence.', 'sentencing', 'State v. Carey', 'https://www.courtlistener.com/opinion/2050938/', '2050938') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the statute is not unconstitutionally vague as applied to Bailey’s conduct.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Wick, this court held that the former aggravated arson statute (Ill.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we conclude that Bailey lacks standing to raise a facial challenge to the statute because the statute does not implicate first amendment rights and because Bailey’s conduct clearly falls within the proscription of the statute.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that section 110 — 6.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In any event, we conclude that the admission of the hotel and medical records would not have affected the outcome of the trial.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the enactment of the stalking statute, we find that the legislature only sought to prohibit conduct that was not constitutionally protected.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, because the statute only encompasses activities performed without lawful authority, we find that it does not implicate any other constitutionally protected activity.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Moreover, we find that the statute’s proscriptions convey sufficiently clear standards as to avoid its arbitrary enforcement.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'To the extent that Coyne argues that the picketing exemption unconstitutionally discriminates against picketing at a workplace during a "bona fide labor dispute” and picketing occurring elsewhere, we find that Bailey lacks standing to make such an argument.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that a rational basis exists for exempting picketing during a bona fide labor dispute from the purview of the statute.', 'general', 'People v. Bailey', 'https://www.courtlistener.com/opinion/2051038/', '2051038') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Roper v. Dynamique Concepts, Inc.', 'https://www.courtlistener.com/opinion/1320076/', '1320076') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Vadas’ conduct does not constitute bribery under either state or federal law, and consequently cannot constitute racketeering activity, we affirm the trial court’s grant of a directed verdict on this issue.', 'general', 'Roper v. Dynamique Concepts, Inc.', 'https://www.courtlistener.com/opinion/1320076/', '1320076') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Based on our conclusion that proof that a result would have occurred but did not because of intervening events is irrelevant when that result is an element of the offense, we hold that such expert medical testimony is not relevant to prove “serious, permanent disfigurement.', 'general', 'State v. Malufau', 'https://www.courtlistener.com/opinion/1127440/', '1127440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the circuit court erred in admitting Dr.', 'general', 'State v. Malufau', 'https://www.courtlistener.com/opinion/1127440/', '1127440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'With the issue now before us, we hold that challenges to the sufficiency of the evidence must always be decided on appeal.', 'general', 'State v. Malufau', 'https://www.courtlistener.com/opinion/1127440/', '1127440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that there was insufficient evidence to convict Malufau of assault in the first degree.', 'general', 'State v. Malufau', 'https://www.courtlistener.com/opinion/1127440/', '1127440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that remanding a case for retrial on lesser included offenses following an appellate determination that insufficient evidence to support a conviction of a greater offense was presented at trial does not offend the double jeopardy clause of the United States Constitution.', 'general', 'State v. Malufau', 'https://www.courtlistener.com/opinion/1127440/', '1127440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that an appellate determination that insufficient evidence to support a conviction was presented at trial does not constitute an “acquittal” as that term is used in HRS § 701—111(1).', 'general', 'State v. Malufau', 'https://www.courtlistener.com/opinion/1127440/', '1127440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we hold that Malufau may not be retried for attempted assault in the first degree.', 'general', 'State v. Malufau', 'https://www.courtlistener.com/opinion/1127440/', '1127440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and we therefore hold that remanding a case for retrial on lesser included offenses following an appellate determination that insufficient evidence to support a conviction of a greater offense was presented at trial, does not offend the double jeopardy clause of the Hawai''i Constitution.', 'general', 'State v. Malufau', 'https://www.courtlistener.com/opinion/1127440/', '1127440') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 848, 853 (1977), we held that the violation of an accused’s constitutional right warrants a presumption of prejudice.', 'general', 'State v. Antone', 'https://www.courtlistener.com/opinion/1242040/', '1242040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial court’s omission constitutes harmless error.', 'general', 'State v. Antone', 'https://www.courtlistener.com/opinion/1242040/', '1242040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that counsel’s decision to refrain from objecting constituted a legitimate tactical choice.', 'general', 'State v. Antone', 'https://www.courtlistener.com/opinion/1242040/', '1242040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Regardless of the reasonableness of counsel’s decision, however, we find that the lie detector results elicited did not substantially impair appellant’s sole defense of mistaken identity.', 'general', 'State v. Antone', 'https://www.courtlistener.com/opinion/1242040/', '1242040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Upon examination of the record, we find that Lisa’s testimony, viewed as a whole, amply establishes her capacity to understand the significance of the oath and to testify truthfully.', 'general', 'State v. Antone', 'https://www.courtlistener.com/opinion/1242040/', '1242040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth below, we affirm.', 'general', 'State v. Antone', 'https://www.courtlistener.com/opinion/1242040/', '1242040') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence sufficiently supported the verdict, that defendant’s right to confrontation was not violated, and that by failing to object, defendant waived the error relating to the prosecutor’s comment on plea bargaining.', 'plea', 'State v. Valdez', 'https://www.courtlistener.com/opinion/1129105/', '1129105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Valdez', 'https://www.courtlistener.com/opinion/1129105/', '1129105') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the judgment without prejudice to any further post-conviction proceedings defendant might institute.', 'general', 'State v. Valdez', 'https://www.courtlistener.com/opinion/1129105/', '1129105') ON CONFLICT DO NOTHING;
