INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the injury was intentional and further held that the intoxicated plaintiff could not recover under the Comparative Fault Act, which expressly ex*368cludes intentional acts.', 'general', 'National RR Passenger Corp. v. Everton by Everton', 'https://www.courtlistener.com/opinion/2053761/', '2053761') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This case presents a question on which Courts of Appeals have divided: Does a defendant''s purpose to circumvent a bank''s reporting obligation suffice to sustain a conviction for "willfully violating" the antistructuring provision?[1] We hold that the "willfulness" *137 requirement mandates something more.', 'general', 'Ratzlaf v. United States', 'https://www.courtlistener.com/opinion/112919/', '112919') ON CONFLICT DO NOTHING;
