INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that this is multiplicitous and violates the constitutional prohibition against double jeopardy.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/2054541/', '2054541') ON CONFLICT DO NOTHING;
