INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we hold that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that, even though the judge erred in failing to issue a limiting instruction, this error does not rise to the level of plain error.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/2054541/', '2054541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'this Court held that a person
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that this was plain error.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/2054541/', '2054541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the Superior Court’s efforts in this case were sufficient to mitigate any prejudicial effects from the prosecutor’s comments.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/2054541/', '2054541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'test is conjunctive and these statements did not satisfy all the elements of the test, we find that the prosecutor’s statements, although improper, did not prejudicially affect Williams’ right to a fair trial and did not require reversal.', 'general', 'Williams v. State', 'https://www.courtlistener.com/opinion/2054541/', '2054541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we find that charging Williams twice for possession with intent to distribute cocaine was multiplicitous and violated the constitutional prohibition against double jeopardy, we reverse his sentence for one of the possession charges and remand to the Superior Court for re-sentencing.', 'sentencing', 'Williams v. State', 'https://www.courtlistener.com/opinion/2054541/', '2054541') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '22 We hold that the district court’s failure to bind over on charges of second-degree murder was an abuse of discretion.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Goecke, we hold that there was sufficient evidence to bind the defendant over on charges of second-degree murder under either a subjective or objective standard.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated by the dissenting judge in the Court of Appeals in Baker,32 we hold that the evidence was sufficient to permit a reasonable jury to infer malice under either a subjective or objective standard.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Viewing the evidence in a light most favorable to the prosecution, we hold that there was sufficient evidence to support the jury’s verdict.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because evidence of drunkenness is not a defense to second-degree murder, we hold that, under either standard, sufficient circumstantial evidence exists in Baker, and sufficient circumstantial and direct evidence exists in Goecke and Hoskinson, to support the bindovers and convictions of these defendants.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the prosecution may seek review of the magistrate’s findings under these circumstances by filing a motion to amend the information and that the circuit court does not have discretion to deny review on the ground that the prosecution was required to file an application for leave to appeal.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Baker and Hoskinson, we find that the evidence supported the juries’ findings of guilt.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '551 NW2d 656 (1996), we found that the ouil, causing death, statute was not enacted to codify the common law.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Goecke, we reverse the decision of the Court of Appeals.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse the decision of *473the Court of Appeals and remand to the trial court for reinstatement of defendant’s second-degree murder conviction and sentence.', 'sentencing', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As early as 1874, this Court held that, to be convicted of murder, an accused must have an intent the “equivalent in legal character to a criminal purpose aimed against life.', 'general', 'People v. Goecke', 'https://www.courtlistener.com/opinion/2054675/', '2054675') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under the circumstances, we find that counsel sufficiently preserved the argument for review.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Further, we find that it would have been futile to move to strike testimony which the trial court had already ruled was proper.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Bryant was unfairly prejudiced by the improper cross-examination.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse on this issue.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the Court of Appeals’ ruling on this issue.', 'general', 'State v. Bryant', 'https://www.courtlistener.com/opinion/1320177/', '1320177') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” That being the case, we hold that the offense charged in Count II was “subsequent” to the offense charged in Count I, within the plain meaning of HRS § 709-906(5)(b).', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the family court did not abuse its discretion in applying the repeat offender provision of HRS § 709-906(5)(b) to Count II of the complaint.', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 288 (1979), despite a clear and unambiguous legislative history — as reflected in the relevant committee reports'' — of an intent to accomplish a particular result in amending the drug laws, this court held, by virtue of the plain language of its statutory work product, that “the [ljegislature did not carry its intention into effect.', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Mattiello, this court held that a facial conflict existed between the language of HRS § 712-1240 (1993), which provided in relevant part that, "as applied to liquids,” " ''[o]unce'' means .', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ') This court held that "the juxtaposition of the words ''weight'' and ''ounce'' in HRS § 712—1241(1)(b)(ii)(B) injects some ambi*269guity into the meaning of the term ‘ounce.', 'general', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 25, 26 (1991) ("Since the defendant did not expressly waive the right to appeal his sentence on the plea, nor was this issue mentioned at his plea hearing, we find that his right to appeal the sentence was not waived.', 'sentencing', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm the family court’s judgment, guilty conviction, and sentence.', 'sentencing', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the foregoing analysis, we affirm the family court’s judgment, guilty conviction, and sentence.', 'sentencing', 'State v. Dudoit', 'https://www.courtlistener.com/opinion/1133569/', '1133569') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that, in order to convict a defendant of theft in the second degree, in violation of HRS §§ 708-830(8)(a) and 708-831(l)(b), the prosecution must prove beyond a reasonable doubt that the accused intended to steal property or services valued in excess of $300.', 'general', 'State v. Cabrera', 'https://www.courtlistener.com/opinion/1133528/', '1133528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 48, 65 (1997), we hold that the circuit court did not err in allowing the loss prevention officers to testify that they commenced surveillance of Cabrera because they “recognized” him.', 'general', 'State v. Cabrera', 'https://www.courtlistener.com/opinion/1133528/', '1133528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 599 (1996), in which a majority of this court held that HRS § 707-732(l)(b) (1993) imposed strict liability
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” Accordingly, we reverse Cabrera’s conviction and remand this matter to the circuit court for a new trial.', 'general', 'State v. Cabrera', 'https://www.courtlistener.com/opinion/1133528/', '1133528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons set forth above, we reverse Cabrera’s conviction and remand this matter to the circuit court for a new trial.', 'general', 'State v. Cabrera', 'https://www.courtlistener.com/opinion/1133528/', '1133528') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that § 28-611 is controlling of the disposition of this case, and that defendant’s prior misdemeanor conviction under § 28-1212 is not a “prior offense” within the plain import of § 28-611(l)(c) or (l)(d).', 'general', 'State v. Suhr', 'https://www.courtlistener.com/opinion/2055817/', '2055817') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that a plain reading of Section 9765 reveals the General Assembly’s intent that crimes with different statutory elements be punished separately.', 'general', 'Commonwealth v. Baldwin', 'https://www.courtlistener.com/opinion/2056083/', '2056083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As each of the two offenses here contains distinct elements, we conclude that, under Section 9765, the consecutive sentences imposed were proper.', 'sentencing', 'Commonwealth v. Baldwin', 'https://www.courtlistener.com/opinion/2056083/', '2056083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm.', 'general', 'Commonwealth v. Baldwin', 'https://www.courtlistener.com/opinion/2056083/', '2056083') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 320 (1975), we held that a misdemeanor arrest by a police officer without a warrant is lawful if the officer has probable cause to believe an offense is being committed in his presence.', 'probable_cause', 'State v. Vance', 'https://www.courtlistener.com/opinion/1320314/', '1320314') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 176 (1972), we held that a warrantless arrest is not rendered invalid by the fact that the arresting officer had a pre-empted ordinance in mind rather than a state statute with similar provisions, if the facts known to the arresting officer also constituted probable cause to arrest under the statute.', 'probable_cause', 'State v. Vance', 'https://www.courtlistener.com/opinion/1320314/', '1320314') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that the record below supports the existence of probable cause to justify the initial arrest of Michael Vance.', 'probable_cause', 'State v. Vance', 'https://www.courtlistener.com/opinion/1320314/', '1320314') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'More importantly, however, we find that the initial arrest of Michael may be upheld without necessarily establishing probable cause to arrest for the offense of disorderly conduct.', 'probable_cause', 'State v. Vance', 'https://www.courtlistener.com/opinion/1320314/', '1320314') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the instant case, we find that Michael’s repeated threatening and offensive remarks unquestionably afforded the police probable cause to arrest him for the offense of harassment,
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we find that the police had the authority to incarcerate under the limited circumstances of this case notwithstanding the appellant’s contention that he had a right to immediate release upon his mother’s offer of bail.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1320314/', '1320314') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the term “unnecessary delay” in Rule 5(a) (2) of the Hawaii Rules of Criminal Procedure should be similarly construed.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1320314/', '1320314') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the evidence was properly admitted.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1320314/', '1320314') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We have carefully reviewed the record and for the reasons hereinafter stated, we affirm.', 'general', 'State v. Vance', 'https://www.courtlistener.com/opinion/1320314/', '1320314') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because Detective Kim’s deliberate misrepresentations to Kelekolio were intrinsic to the facts of the present offenses and because we determine from the totality of the circumstances surrounding Kelekolio’s audiotaped statement, based on our review of the entire record, that the misrepresentations were not of a type that would reasonably induce a false confession, we hold that Detective Bum’s use of deception did not render Kelekolio’s inculpatory statements involuntary.', 'general', 'State v. Kelekolio', 'https://www.courtlistener.com/opinion/1135231/', '1135231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that the trial court committed plain error in failing to make an express determination of the complainant’s competence to testify, and because we are not convinced beyond a reasonable doubt that the error was harmless, we vacate Kelekolio’s convictions and remand for a new trial.', 'general', 'State v. Kelekolio', 'https://www.courtlistener.com/opinion/1135231/', '1135231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the jury instructions, when read and considered as a whole, were not prejudicially insufficient, erroneous, inconsistent, or misleading.', 'jury_instruction', 'State v. Kelekolio', 'https://www.courtlistener.com/opinion/1135231/', '1135231') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Jn a later homicide case, this court held it to be error to instruct the jury no particular time need intervene between the formation of the intention and the act in order to constitute premeditated malice.', 'general', 'Young v. State', 'https://www.courtlistener.com/opinion/1135736/', '1135736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This court held that the state does not have a constitutional duty to manufacture evidence in addition to its duty under Brady to disclose exculpatory evidence in its possession.', 'general', 'Young v. State', 'https://www.courtlistener.com/opinion/1135736/', '1135736') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Lopez, we held that a prior conviction for resisting arrest did not death qualify the defendant because conduct that only created a “substantial risk” of physical injury to an officer was not conduct “involving the use or threat of violence.', 'general', 'State v. McKinney', 'https://www.courtlistener.com/opinion/1135841/', '1135841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Walden, this court held that a conviction that could have been obtained for merely reckless conduct did not qualify as a prior under the (F)(2) factor.', 'general', 'State v. McKinney', 'https://www.courtlistener.com/opinion/1135841/', '1135841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '3 Thus, under the facts of this case, we conclude that the Rule 609 hearing was not a critical stage of Hedlund’s proceedings.', 'general', 'State v. McKinney', 'https://www.courtlistener.com/opinion/1135841/', '1135841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the finding that Hedlund murdered for pecuniary gain.', 'general', 'State v. McKinney', 'https://www.courtlistener.com/opinion/1135841/', '1135841') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on our review of the record, we hold that the trial court did not clearly err in finding that Ganal voluntarily consented to the search of his truck.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '14 For the reasons set forth below, we hold that the original version of HRS § 134-6(a) is inapplicable where the defendant’s use of a firearm establishes an element of the underlying felony.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, based on established rules of statutory construction, the language of HRS § 134-6(a), particularly when read together with the remainder of Act 195 and the subsequent legislative history, we hold that HRS § 134-6(a) does not apply where the defendant’s use of a firearm establishes an element of the underlying felony.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, taken in the context of the entire argument, and in view of the strength of the case against Ganal, we hold that none of the comments, alone or in combination, would lead us to the conclusion that the trial court abused its discretion in denying Ganal’s Motion for New Trial.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that Ganal should not be rewarded for his misconduct, especially by a post-verdict grant of a new trial.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Consequently, we hold that the trial court erred in declining to apply HRS §§ 701-109(l)(a) and (4)(b) to merge Ganal’s conviction for attempted first degree murder pursuant to Count II of the indictment into his conviction for first degree murder pursuant to Count I of the indictment, because Count II “consists *382of an attempt to commit the offense charged” in Count I.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 966 (1993), where we held that second degree murder is not an included offense of first degree murder because the two crimes entail different requisite states of mind, Ganal could have been charged with the attempted second degree murder of Mabel in Waipahu, and the counts would not have been subject to merger.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'First noting that the comments constituted plain error under HRPP Rule 52(b), this court held that the prejudicial impact of the remarks was not rendered harmless by the trial court’s instructions to the jury and reversed the conviction.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and (2) our view that it is impossible for anyone logically to conclude that Ga-nal, having started a single fire at the Tou-chette home in Kailua, possessed anything other than a single intent to cause the death of all of the victims therein, we conclude that Ganal possessed a single intent to cause the death of all of the victims named in both the first degree murder and attempted first degree murder counts of the indictment.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that Ganal’s conviction under Count III must be reversed because HRS § 134-6(a) does not apply, we need not address Ganal’s argument that the prosecution thereunder violated his right to equal protection.', 'general', 'State v. Ganal', 'https://www.courtlistener.com/opinion/1136030/', '1136030') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 613 (1996), this Court held:
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1983), we held that under certain circumstances AS 12.', 'general', 'Lee v. State', 'https://www.courtlistener.com/opinion/1259449/', '1259449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that it is inappropriate to broaden the statutory definition of a prior conviction by considering inflation.', 'general', 'Lee v. State', 'https://www.courtlistener.com/opinion/1259449/', '1259449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'On balance, we conclude that a broad interpretation of AS 12.', 'general', 'Lee v. State', 'https://www.courtlistener.com/opinion/1259449/', '1259449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Judge Buckalew’s analysis of the facts is supported by ample evidence and that he did not err in finding that Lee’s conduct was among the most serious within the definition of the offense.', 'general', 'Lee v. State', 'https://www.courtlistener.com/opinion/1259449/', '1259449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that a conviction for grand larceny under former AS 11.', 'general', 'Lee v. State', 'https://www.courtlistener.com/opinion/1259449/', '1259449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we find that the use of Lee’s prior conviction as a basis for presumptive sentencing in this case was inappropriate and that Lee must be resentenced to a non-presumptive term.', 'sentencing', 'Lee v. State', 'https://www.courtlistener.com/opinion/1259449/', '1259449') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that fidelity to these principles dictates that, in this category of cases, the judge does not sit as a thirteenth juror.', 'general', 'People v. Lemmon', 'https://www.courtlistener.com/opinion/1572995/', '1572995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Herbert, we held that it was error for the trial judge to conclude that he was not allowed to consider the credibility of witnesses when deciding a motion for a new trial.', 'general', 'People v. Lemmon', 'https://www.courtlistener.com/opinion/1572995/', '1572995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, because we find that the court did not err in ordering a new trial under the erroneous thirteenth juror standard previously permitted under Herbert, we affirm the decision of the Court of Appeals[27] and hold that the newly adopted limitations on Herbert apply prospectively to cases not yet final as of the date of this decision.', 'general', 'People v. Lemmon', 'https://www.courtlistener.com/opinion/1572995/', '1572995') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Washburn', 'https://www.courtlistener.com/opinion/1320632/', '1320632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we affirm the trial court’s denial of defendant’s motion to suppress the evidence obtained from both his individual storage unit and his residence.', 'suppression', 'State v. Washburn', 'https://www.courtlistener.com/opinion/1320632/', '1320632') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Act exceeds the authority of Congress "[t]o regulate Commerce .', 'general', 'United States v. Lopez', 'https://www.courtlistener.com/opinion/117927/', '117927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', at 37, we held that the question of congressional power under the Commerce Clause "is necessarily one of degree.', 'general', 'United States v. Lopez', 'https://www.courtlistener.com/opinion/117927/', '117927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 (1895), this Court held that mere attempts to monopolize the manufacture of sugar could not be regulated pursuant to the Commerce Clause.', 'general', 'United States v. Lopez', 'https://www.courtlistener.com/opinion/117927/', '117927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The moment came, however, with the challenge to congressional Commerce Clause authority to prohibit racial discrimination in places of public accommodation, when the Court simply made explicit what the earlier cases had implied: "where we find that the legislators, in light of the facts and testimony before them, have a rational basis for finding a chosen regulatory scheme necessary to the protection of commerce, our investigation is at an end.', 'general', 'United States v. Lopez', 'https://www.courtlistener.com/opinion/117927/', '117927') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held in syllabus point three of State v.', 'general', 'State of West Virginia v. Rick Brock', 'https://www.courtlistener.com/opinion/2803094/', '2803094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'appendix record, and all other matters submitted before the Court, we affirm the decision of
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the foregoing, we affirm the trial court’s decision.', 'general', 'State of West Virginia v. Rick Brock', 'https://www.courtlistener.com/opinion/2803094/', '2803094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1338834/', '1338834') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we hold that the evidence is sufficient to support the jury’s finding that the abduction occurred, in whole or in part, in the county.', 'general', 'Cheng v. Commonwealth', 'https://www.courtlistener.com/opinion/1242733/', '1242733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the evidence is insufficient to support Cheng’s conviction of capital murder.', 'general', 'Cheng v. Commonwealth', 'https://www.courtlistener.com/opinion/1242733/', '1242733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1111 (1985), we held that
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, on this record, we conclude that no undue prejudice could have resulted from trying the offenses together in a single trial.', 'general', 'Cheng v. Commonwealth', 'https://www.courtlistener.com/opinion/1242733/', '1242733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In the present case, we conclude that the trial court did not abuse its discretion in denying the motion.', 'general', 'Cheng v. Commonwealth', 'https://www.courtlistener.com/opinion/1242733/', '1242733') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Under these exceptional circumstances, we hold that this case should be remanded for resentencing.', 'sentencing', 'State v. Johnston', 'https://www.courtlistener.com/opinion/1338867/', '1338867') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that since this issue was not raised below and did not involve subject matter jurisdiction, the defendant was not entitled to have the issue considered for the first time on appeal.', 'general', 'State v. Johnston', 'https://www.courtlistener.com/opinion/1338867/', '1338867') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that Defendant’s challenge to the trial court’s sentencing authority does not involve a question of subject matter jurisdiction.', 'sentencing', 'State v. Johnston', 'https://www.courtlistener.com/opinion/1338867/', '1338867') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand.', 'general', 'State v. Johnston', 'https://www.courtlistener.com/opinion/1338867/', '1338867') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'we reverse.', 'general', 'State v. O''LEARY', 'https://www.courtlistener.com/opinion/1242772/', '1242772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for new trial.', 'general', 'State v. O''LEARY', 'https://www.courtlistener.com/opinion/1242772/', '1242772') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the superior court did not abuse its discretion when it ordered trial in Nenana.', 'general', 'Wholecheese v. State', 'https://www.courtlistener.com/opinion/5322943/', '5322943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we affirm Wholeeheese’s convictions.', 'general', 'Wholecheese v. State', 'https://www.courtlistener.com/opinion/5322943/', '5322943') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that in a nonjury criminal trial, jeopardy attaches when the court begins to hear evidence or testimony.', 'general', 'State v. Brunson', 'https://www.courtlistener.com/opinion/1242853/', '1242853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the above reasons, we affirm the Court of Appeals and remand this case to that court for further remand to Superior Court, Pasquotank County, for trial.', 'general', 'State v. Brunson', 'https://www.courtlistener.com/opinion/1242853/', '1242853') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the trial court.', 'general', 'People v. Rowell', 'https://www.courtlistener.com/opinion/4851013/', '4851013') ON CONFLICT DO NOTHING;
