INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Applying the guilty-knowledge exception, we hold that Lawson’s testimony was properly admitted in evidence.', 'general', 'Lewis v. Commonwealth', 'https://www.courtlistener.com/opinion/1321490/', '1321490') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that § 60-6,196 is a continuance and affirmation of the previous statute § 39-669.', 'general', 'State v. Sundling', 'https://www.courtlistener.com/opinion/1243533/', '1243533') ON CONFLICT DO NOTHING;
