INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we hold that, under the circumstances of this case, appellant violated section 836.', 'general', 'O''Leary v. State', 'https://www.courtlistener.com/opinion/4989629/', '4989629') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the State made out a prima facie case against appellant by submitting facts showing that appellant composed a threat to kill or do *878serious bodily injury, sent that communication to another, in this case Michael O’Leary, and the communication threatened a member of the recipient’s family.', 'general', 'O''Leary v. State', 'https://www.courtlistener.com/opinion/4989629/', '4989629') ON CONFLICT DO NOTHING;
