INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we AFFIRM the trial court’s denial of appellant’s motion to dismiss.', 'dismissal', 'O''Leary v. State', 'https://www.courtlistener.com/opinion/4989629/', '4989629') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As each of the images had been opened, and saved on defendant’s hard drive (regardless of what “directory” they were in), we hold that the evidence supports the conclusion that defendant “possessed” each of these 43 images, per N.', 'general', 'State v. Howell', 'https://www.courtlistener.com/opinion/1322829/', '1322829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Furthermore, we conclude that the listing of plural items in the definition of “material” is merely a matter of style.', 'general', 'State v. Howell', 'https://www.courtlistener.com/opinion/1322829/', '1322829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Similarly, we conclude that the plain language of N.', 'general', 'State v. Howell', 'https://www.courtlistener.com/opinion/1322829/', '1322829') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that defendant’s multiple convictions are consistent with the language and intent of the child pornography statutes and do not violate his right to be free from double jeopardy.', 'general', 'State v. Howell', 'https://www.courtlistener.com/opinion/1322829/', '1322829') ON CONFLICT DO NOTHING;
