INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'decisions that the statutes were not facially overbroad and we conclude that the statutes are constitutional as applied to defendant.', 'general', 'State v. Howell', 'https://www.courtlistener.com/opinion/1322829/', '1322829') ON CONFLICT DO NOTHING;
