INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 57 (2006), in which this Court held that the loss of a natural tooth, even one that could be replaced with a dental implant, was enough permanent disfigurement to go to the jury on the issue of serious bodily injury.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1324737/', '1324737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In affirming the trial court’s decision denying the motion to dismiss, this Court held the evidence that the victim had been strangled to the point of having difficulty breathing was sufficient to comprise “strangulation” under the statute.', 'dismissal', 'State v. Williams', 'https://www.courtlistener.com/opinion/1324737/', '1324737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 679 (2003), this Court held that legislative intent would rebut the presumption created by
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that there was one single act of touching and not multiple sexual acts.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1324737/', '1324737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We note that although the jury charge for kidnapping required a finding that the women were abducted “for the purpose of doing serious bodily injury” which more closely coincides with the charge of assault inflicting serious bodily injury, we conclude that “for the purpose of’ and the actual act of committing serious bodily injury are two different elements, the latter being more serious than the former.', 'general', 'State v. Williams', 'https://www.courtlistener.com/opinion/1324737/', '1324737') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For the reasons stated herein, we hold that the temporary restraining order (“TRO”) entered in this case pursuant to Rule 65(b) of the North Carolina Rules of Civil Procedure was not a valid domestic violence protective order as defined by Chapter 50B of the General Statutes.', 'general', 'State v. Byrd', 'https://www.courtlistener.com/opinion/1325786/', '1325786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Having determined that the TRO was not a valid protective order under Chapter 50B, we conclude that the trial court erred in submitting the sentencing enhancement issue to the jury.', 'sentencing', 'State v. Byrd', 'https://www.courtlistener.com/opinion/1325786/', '1325786') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Adams, we held that a juror should not, prior to trial, be required to identify which witnesses he will believe or what type of witnesses he will believe;', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Adams we held that a trial judge must impress upon the jury that it cannot consider any confession unless it finds beyond a reasonable doubt that the accused gave his statement freely and voluntarily under the totality of the circumstances, and that the accused received and understood his Miranda rights.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '409 (1930), we held that a jury charge was incorrect in that it “did not clearly and correctly instruct the jury that, if they had a reasonable doubt as to whether the [defendant] was guilty of murder or manslaughter, it was their duty to resolve that doubt in his favor, and find him guilty of the lesser offense.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '” However, in Elmore we held that physical torture occurs when a person is subject to “serious physical abuse” and “aggravated battery.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not err in utilizing section 17-21-85.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was sufficient evidence on the record, both lay and expert, to support the trial judge’s determination that Davis was competent to waive his Miranda rights.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*343We conclude that the trial judge’s instruction properly explained to the jury that it should determine the voluntariness of Davis’s confession under the totality of the circumstances, and that Davis’s receipt of his Miranda warnings and ability to understand those warnings were appropriate factors to consider in deciding whether the confession was freely given.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the trial judge did not err in charging the jury that a hand or fist could constitute a deadly weapon or object.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that Davis’s contention that the trial judge should have instructed the jury that it must resolve any reasonable doubt regarding whether Davis was guilty of first or second degree criminal sexual conduct in favor of the lesser offense is without merit.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Thus, we conclude that Davis’s waiver was intelligently made.', 'general', 'State v. Davis', 'https://www.courtlistener.com/opinion/1325942/', '1325942') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'offender argument, and we find that those arguments are without merit.', 'general', 'Christopher B. Sellers v. State of Mississippi', 'https://www.courtlistener.com/opinion/2806604/', '2806604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Finding that the circuit court committed no error, we affirm.', 'general', 'Christopher B. Sellers v. State of Mississippi', 'https://www.courtlistener.com/opinion/2806604/', '2806604') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'that the circuit court did not err in denying Sellers’s PCR motion, we affirm.', 'general', 'Christopher B. Sellers v. State of Mississippi', 'https://www.courtlistener.com/opinion/2806604/', '2806604') ON CONFLICT DO NOTHING;
