INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that “there was an entire lack of those elements of outrageous conduct which would subject the defendants to punitive damages.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'However, for the following reasons, we conclude that Officer Woolard was immune from suit in either capacity.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on the facts and circumstances as set forth above, however, we conclude that the searches were not consensual, but were the result of intimidation.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that there was no manifest abuse of discretion in the award of compensatory damages.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We therefore hold that the trial court erred in finding that Friend engaged in outrageous conduct and in concluding that Friend’s outrageous conduct entitled plaintiff to recover punitive damages from Friend.', 'general', 'Mullins Ex Rel. Mullins v. Brody''s Store Manager', 'https://www.courtlistener.com/opinion/1326470/', '1326470') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the judge erred in disallowing impeachment of the prosecutrix for her fraudulent check convictions.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/1248298/', '1248298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse and remand for a new trial.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/1248298/', '1248298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we reverse and remand for a new trial.', 'general', 'State v. Harrison', 'https://www.courtlistener.com/opinion/1248298/', '1248298') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that a miscarriage of justice occurred when the trial court sentenced the appellant for a crime other than that for which he had been convicted.', 'sentencing', 'Brown v. Commonwealth', 'https://www.courtlistener.com/opinion/1248503/', '1248503') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that, although there was no direct evidence that the vehicle’s value exceeded $200, there was circumstantial evidence of the age, make, and operating condition of the vehicle that could support a jury’s finding that the value of the car exceeded $200.', 'general', 'Brown v. Commonwealth', 'https://www.courtlistener.com/opinion/1248503/', '1248503') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that the defendant was, in fact, sentenced for a crime other than that for which he was convicted.', 'sentencing', 'Brown v. Commonwealth', 'https://www.courtlistener.com/opinion/1248503/', '1248503') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the evidence was sufficient to permit the jury to find the elements of a qualified privilege as to those acts as well.', 'general', 'Winckel v. Von Maur, Inc.', 'https://www.courtlistener.com/opinion/1248535/', '1248535') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because no police misconduct occurred that warrants applying the exclusionary rule for its deterrent effect, we reverse and remand without reaching the constitutional and standing issues.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1248803/', '1248803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because the exclusionary rule exists to deter police misconduct, and because no police misconduct of any kind occurred and no other special circumstances exist in this case, we reverse and remand without reaching the constitutional issue.', 'general', 'State v. Smith', 'https://www.courtlistener.com/opinion/1248803/', '1248803') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 221 (1997), we held that generally “[t]he Supreme Court of Appeals reviews sentencing orders .', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/1248820/', '1248820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 851, 857 (1983), we held that “[tjhere are two tests to determine whether a sentence is so disproportionate to a crime that it violates our constitution.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/1248820/', '1248820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed the sentence of 45 years for aggravated robbery on the grounds that the sentence shocked the conscience.', 'sentencing', 'State v. Adams', 'https://www.courtlistener.com/opinion/1248820/', '1248820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based upon the parties’ arguments on appeal, the record designated for appellate review, and the pertinent authorities, we affirm the decision of the Circuit Court of Putnam County.', 'general', 'State v. Adams', 'https://www.courtlistener.com/opinion/1248820/', '1248820') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that the district court erred in limiting the information it considered in determining whether to exonerate the bond.', 'general', 'State v. Beck', 'https://www.courtlistener.com/opinion/5342104/', '5342104') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirmed the district court’s conclusion that neither the statute nor the criminal rule gave a trial court discretion to extend the ninety-day time limit.', 'general', 'State v. Beck', 'https://www.courtlistener.com/opinion/5342104/', '5342104') ON CONFLICT DO NOTHING;
