INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'This Court held that Rule 611(b)
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'The murder in this case was at least as shocking and repugnant as the murders in Wallace, in which we affirmed the death sentence.', 'sentencing', 'State v. Brewer', 'https://www.courtlistener.com/opinion/1250206/', '1250206') ON CONFLICT DO NOTHING;
