INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we hold that the trial court erred in denying Tirado''s motion for mistrial and that he is entitled to a new sentencing proceeding.', 'sentencing', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'and defendant''s acquiescence in the procedure, we hold that this absence, occurring during a portion of his co-defendent''s sentencing hearing, did not violate Queen''s statutory right to the assistance of two attorneys.', 'sentencing', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this evidence, we hold that the ordeal that Lambert and Moore endured prior to their death supported submission of the (e)(9) circumstance.', 'general', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', 470 (1994), we held that the "right to challenge is not a right to select but to reject a juror" and concluded that the defendant had demonstrated no prejudice.', 'general', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In addition, as to any alleged statutory violation that defendants argue is preserved for appellate review, we conclude that the excusal of prospective juror McMillan was proper.', 'general', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, we conclude that a different result would not have been reached had the trial court instructed only on the purpose charged in the indictment, and that the error in the instructions was not prejudicial.', 'general', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" Therefore, in light of the court''s limiting instruction to the jury that Queen''s statements were not to be used against Tirado and the prosecutor''s statement reminding the jury of the defined purpose for which the evidence had been admitted, we conclude that Tirado''s contention that the prosecutor improperly used the statements of Queen to corroborate Black and thereby bolster the case against Tirado is without merit.', 'general', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Based on this record, we conclude that the State presented sufficient evidence to allow a rational juror to conclude that Tirado joined with one or more persons in the purpose to kidnap, rob, assault with a deadly weapon, and attempt to murder Cheeseborough and was constructively present when these crimes were carried out.', 'general', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'statement denying involvement in the kidnapping of Moore and Lambert is relevant to Queen''s strategy of focusing on his cooperation in order to win mitigation in the capital case, we conclude that he failed to show any prejudice arising from the nondisclosure.', 'general', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'that the issue had been preserved, we conclude that double jeopardy does not apply here.', 'general', 'State v. Tirado', 'https://www.courtlistener.com/opinion/1328094/', '1328094') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the conviction and sentence for armed robbery, but otherwise affirm Simmons’ convictions and sentences.', 'sentencing', 'State v. Simmons', 'https://www.courtlistener.com/opinion/1328122/', '1328122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse Simmons’ conviction and sentence for armed robbery and affirm his remaining convictions and sentences.', 'sentencing', 'State v. Simmons', 'https://www.courtlistener.com/opinion/1328122/', '1328122') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '*487We conclude that the Boise City Council’s proposed annexation was not without or in excess of the City Council’s jurisdiction.', 'general', 'Crane Creek Country Club v. City of Boise', 'https://www.courtlistener.com/opinion/1249684/', '1249684') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that it was.', 'general', 'State v. Godwin', 'https://www.courtlistener.com/opinion/1249743/', '1249743') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the convictions, but quash all of the sentences except the one given for first degree murder, because the record does not contain a guideline scoresheet, nor any written reasons for a "departure" sentence.', 'sentencing', 'Worthington v. State', 'https://www.courtlistener.com/opinion/1146902/', '1146902') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We find that by changing the aggravating circumstance from entering during the darkness to causing physical injury, the amendment to the indictment “substituted an entirely different [offense] for the one charged.', 'general', 'State v. Guthrie', 'https://www.courtlistener.com/opinion/1389574/', '1389574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse.', 'general', 'State v. Guthrie', 'https://www.courtlistener.com/opinion/1389574/', '1389574') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Mrs.', 'general', 'State v. Kornegay', 'https://www.courtlistener.com/opinion/1250939/', '1250939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After a careful review of the warrants and the documents attached to them, we hold that the warrants are sufficiently specific and that the applications for issuance of the warrants disclose probable cause to believe that the particular crimes listed had been committed by defendant.', 'probable_cause', 'State v. Kornegay', 'https://www.courtlistener.com/opinion/1250939/', '1250939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the warrants and supporting affidavits, we hold that the warrants are sufficiently particular to meet the requirements of the fourth amendment and article I, section 20 of the North Carolina Constitution.', 'search_seizure', 'State v. Kornegay', 'https://www.courtlistener.com/opinion/1250939/', '1250939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In this case we hold that the description by the State of the items to be seized was as specific as the circumstances and nature of defendant’s activities permitted.', 'general', 'State v. Kornegay', 'https://www.courtlistener.com/opinion/1250939/', '1250939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the statutes we hold that two separate and distinct offenses were charged in each case and that the trial court did not err in waiting until the close of all the evidence to require the State to make an election between the offenses of embezzlement and malfeasance of a corporate agent.', 'general', 'State v. Kornegay', 'https://www.courtlistener.com/opinion/1250939/', '1250939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In light of the fact that John Edwards and Robert Rice gave identical testimony concerning other checks that were properly admitted into evidence, we hold that admission of the testimony concerning the 10 December 1978 check was harmless error.', 'general', 'State v. Kornegay', 'https://www.courtlistener.com/opinion/1250939/', '1250939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After examining the circumstances surrounding the three offenses we conclude that the trial judge did not abuse his discretion in joining the offenses for trial.', 'general', 'State v. Kornegay', 'https://www.courtlistener.com/opinion/1250939/', '1250939') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the penalties set forth in N.', 'general', 'State ex rel. N.L.', 'https://www.courtlistener.com/opinion/7403673/', '7403673') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1995), speaking through Judge Wallace, we concluded that adjourning formal entry of disposition pursuant to *32N.', 'general', 'State ex rel. N.L.', 'https://www.courtlistener.com/opinion/7403673/', '7403673') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm appellant’s conviction and remand for resentencing.', 'sentencing', 'State v. Mims', 'https://www.courtlistener.com/opinion/1273985/', '1273985') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'After thoroughly reviewing the record and the additional briefing submitted by both parties, we find that Melvin failed to timely object to the State’s remark at trial.', 'general', 'Morse v. State', 'https://www.courtlistener.com/opinion/2825006/', '2825006') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reverse the order under review.', 'general', 'State v. Moraes-Pena', 'https://www.courtlistener.com/opinion/7404221/', '7404221') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '16 Our analysis proceeds in three parts: First, we hold that the allowable unit of prosecution for unlawful discharge of a firearm is each discrete shot;', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Third, we hold that the state and federal cruel and unusual punishment clauses are inapplicable *1262because those clauses deal with punishment, which is distinct from the allowable unit of prosecution for an offense.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Accordingly, insofar as the strict construction statute purports to abolish the rule of lenity, we hold that it does not.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '1 31 In sum, we hold that the single erimi-nal episode statute is inapplicable because Mr.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'And we hold that the single larceny rule is inapplicable because this case is governed by the allowable unit of prosecution defined by the Legislature in the statute criminalizing unlawful discharge of a firearm.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '134 In sum, we hold that the question of cruel and unusual punishment is not implicated in a determination of the allowable unit of prosecution for an offense.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '" 10 Accordingly, on the basis of the statutory language, we held that the allowable unit of prosecution for child pomogla-phy is each visual representation.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We conclude that neither the single criminal episode statute nor the single larceny rule apply here.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm the court of appeals.', 'general', 'State v. Rasabout', 'https://www.courtlistener.com/opinion/2827591/', '2827591') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We affirm.', 'general', 'Commonwealth v. Treiber, S., Aplt', 'https://www.courtlistener.com/opinion/2827857/', '2827857') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Although we hold that McNeely applies to cases on direct review at the time of decision, we also hold that the test results from Lindquist’s warrantless blood draw, even if unconstitutionally obtained, do not need to be suppressed because the officer who facilitated the blood draw acted in objectively reasonable reliance on bind- • ing appellate precedent.', 'suppression', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that Lindquist did not forfeit her right to challenge her warrantless blood draw because the Supreme Court’s *868decision in McNeely was an intervening change in the law that excused Lindquist’s failure to bring what would have otherwise been a futile argument in the district court and court of appeals.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In summary, we hold that the exclusionary rule does not apply to violations of the Fourth Amendment to the U.', 'search_seizure', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'As a result, we hold that the district court did not err in admitting the results of Lindquist’s blood draw because the officer who facilitated the blood draw acted in objectively reasonably reliance on binding appellate precedent.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Shriner, we held that “[t]he rapid, natural dissipation of alcohol in the blood creates single-factor exigent circumstances that will justify the *878police taking a warrantless, nonconsensual blood draw from a defendant, provided that the police have probable cause to believe that defendant committed criminal vehicular operation.', 'probable_cause', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'For these reasons, we conclude that Minn.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Because we conclude that the exclusionary rule does not apply to Lindquist’s blood draw, we need not decide this issue.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Citing Os-bome, we concluded that Miller applied.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '2d 340, 344-45 (1977), we concluded that a search warrant for a package was supported by probable cause despite the fact that the affidavit in support of the warrant contained a material misstatement of fact told by a mail clerk to a police officer.', 'probable_cause', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that the defendant could not show prejudice because the exclusionary rule would not have applied to this DNA evidence, which was obtained because of a court’s improper interpretation of a statute.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'In Davis, we held that, under Article I, Section 8, the Legislature could not “directly or indirectly, for any cause whatsoever, deprive [a person] of his [or her] constitutional right to commence, maintain, or defend any action or other judicial proceeding.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We concluded that district courts have original jurisdiction “in every case where the constitution itself does not clearly confer it on some other court,” id.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, ', we concluded that application of the “seat belt gag rule” to preclude evidence of seat belt use in a crashworthiness action involving an allegedly defective seat belt did not violate Article I, Section 8, because the remedy for crashworthiness actions had not vested at common law by the time the Legislature passed the gag rule.', 'general', 'State of Minnesota, Respondent/Cross-Appellant v. Bonnie Ann Lindquist, Appellant/Cross-Respondent.', 'https://www.courtlistener.com/opinion/2828527/', '2828527') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We hold that the Sixth Amendment mandates that juveniles convicted of homicide who face the possibility of a sentence of life without the possibility of parole have a right to have their sentences determined by a jury.', 'sentencing', 'People v. Skinner', 'https://www.courtlistener.com/opinion/2829890/', '2829890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '“In each case, we concluded that the defendant’s constitutional rights had been violated because the judge had imposed a sentence greater than the maximum he could have imposed under state law without the challenged factual finding.', 'sentencing', 'People v. Skinner', 'https://www.courtlistener.com/opinion/2829890/', '2829890') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Articulating for the first time, and then applying, a multifactor set of criteria for determining whether the Winship[8] protections applied to bar such a system, we concluded that the Pennsylvania statute did not run afoul of our previous admonitions against relieving the State of its burden of proving guilt, or tailoring the mere form of a criminal statute solely to avoid Winship’s strictures.', 'general', 'People v. Skinner', 'https://www.courtlistener.com/opinion/2829890/', '2829890') ON CONFLICT DO NOTHING;
