INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'Therefore, we affirm Lumbra''s conviction in every respect.', 'general', 'Vanvorst v. State', 'https://www.courtlistener.com/opinion/2551580/', '2551580') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We held that the prosecution had not been commenced in the First Judicial District of Hinds County, and the case therefore distinguishable fromColeman, supra, and Atkinson, supra.', 'general', 'Simmons v. State', 'https://www.courtlistener.com/opinion/1143735/', '1143735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, '377 [1911], we held that, where concurrent jurisdiction is vested in two courts, the court first acquiring jurisdiction acquires exclusive jurisdiction, and that if a proceeding is instituted in another court about the same subject-matter after one of the courts of concurrent jurisdiction has acquired control, the suit should be dismissed in the last court to acquire jurisdiction.', 'dismissal', 'Simmons v. State', 'https://www.courtlistener.com/opinion/1143735/', '1143735') ON CONFLICT DO NOTHING;
INSERT INTO judge_quotes (judge_id, quote, topic, case_cited, source_url, cluster_id) VALUES (NULL, 'We reversed.', 'general', 'Simmons v. State', 'https://www.courtlistener.com/opinion/1143735/', '1143735') ON CONFLICT DO NOTHING;
